INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Au commencement Dieu créa les cieux et la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Et la terre était désolation et vide, et il y avait des ténèbres sur la face de l’abîme. Et l’Esprit de Dieu planait sur la face des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Et Dieu dit: Que la lumière soit. Et la lumière fut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Et Dieu vit la lumière, qu’elle était bonne; et Dieu sépara la lumière d’avec les ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Et Dieu appela la lumière Jour; et les ténèbres, il les appela Nuit. Et il y eut soir, et il y eut matin: – premier jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Et Dieu dit: Qu’il y ait une étendue entre les eaux, et qu’elle sépare les eaux d’avec les eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Et Dieu fit l’étendue, et sépara les eaux qui sont au-dessous de l’étendue d’avec les eaux qui sont au-dessus de l’étendue. Et il fut ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Et Dieu appela l’étendue Cieux. Et il y eut soir, et il y eut matin: – second jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Et Dieu dit: Que les eaux [qui sont] au-dessous des cieux se rassemblent en un lieu, et que le sec paraisse. Et il fut ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Et Dieu appela le sec Terre, et le rassemblement des eaux, il l’appela Mers. Et Dieu vit que cela était bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Et Dieu dit: Que la terre produise l’herbe, la plante portant de la semence, l’arbre fruitier produisant du fruit selon son espèce, ayant sa semence en soi sur la terre. Et il fut ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Et la terre produisit l’herbe, la plante portant de la semence selon son espèce, et l’arbre produisant du fruit ayant sa semence en soi selon son espèce. Et Dieu vit que cela était bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Et il y eut soir, et il y eut matin: – troisième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Et Dieu dit: Qu’il y ait des luminaires dans l’étendue des cieux pour séparer le jour d’avec la nuit, et qu’ils soient pour signes et pour saisons [déterminées] et pour jours et pour années;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'et qu’ils soient pour luminaires dans l’étendue des cieux pour donner de la lumière sur la terre. Et il fut ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Et Dieu fit les deux grands luminaires, le grand luminaire pour dominer sur le jour, et le petit luminaire pour dominer sur la nuit; et les étoiles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Et Dieu les plaça dans l’étendue des cieux pour donner de la lumière sur la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'et pour dominer de jour et de nuit, et pour séparer la lumière d’avec les ténèbres. Et Dieu vit que cela était bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Et il y eut soir, et il y eut matin: – quatrième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Et Dieu dit: Que les eaux foisonnent d’un fourmillement d’êtres vivants, et que les oiseaux volent au-dessus de la terre devant l’étendue des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Et Dieu créa les grands animaux des eaux, et tout être vivant qui se meut, dont les eaux fourmillent, selon leurs espèces, et tout oiseau ailé selon son espèce. Et Dieu vit que cela était bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Et Dieu les bénit, disant: Fructifiez, et multipliez, et remplissez les eaux dans les mers, et que l’oiseau multiplie sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Et il y eut soir, et il y eut matin: – cinquième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Et Dieu dit: Que la terre produise des êtres vivants selon leur espèce, le bétail, et [tout] ce qui rampe, et les bêtes de la terre selon leur espèce. Et il fut ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Et Dieu fit les bêtes de la terre selon leur espèce, et le bétail selon son espèce, et tout reptile du sol selon son espèce. Et Dieu vit que cela était bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Et Dieu dit: Faisons [l’]homme à notre image, selon notre ressemblance, et qu’ils dominent sur les poissons de la mer, et sur les oiseaux des cieux, et sur le bétail, et sur toute la terre, et sur tout [animal] rampant qui rampe sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Et Dieu créa l’homme à son image; il le créa à l’image de Dieu; il les créa mâle et femelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Et Dieu les bénit; et Dieu leur dit: Fructifiez, et multipliez, et remplissez la terre et l’assujettissez; et dominez sur les poissons de la mer, et sur les oiseaux des cieux, et sur tout être vivant qui se meut sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Et Dieu dit: Voici, je vous ai donné toute plante portant semence, qui est sur la face de toute la terre, et tout arbre dans lequel il y a un fruit d’arbre, portant semence; [cela] vous sera pour nourriture;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'et à tout animal de la terre, et à tout oiseau des cieux, et à tout ce qui rampe sur la terre, qui a en soi une âme vivante, [j’ai donné] toute plante verte pour nourriture. Et il fut ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Et Dieu vit tout ce qu’il avait fait, et voici, cela était très bon. Et il y eut soir, et il y eut matin: – le sixième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Et les cieux et la terre furent achevés, et toute leur armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Et Dieu eut achevé au septième jour son œuvre qu’il fit; et il se reposa au septième jour de toute son œuvre qu’il fit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Et Dieu bénit le septième jour, et le sanctifia; car en ce jour il se reposa de toute son œuvre que Dieu créa en la faisant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, '*Ce sont ici les générations des cieux et de la terre lorsqu’ils furent créés, au jour où l’ Éternel Dieu fit la terre et les cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'et tout arbuste des champs avant qu’il soit sur la terre, et toute herbe des champs avant qu’elle croisse; car l’ Éternel Dieu n’avait pas fait pleuvoir sur la terre, et il n’y avait pas d’homme pour travailler le sol;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'mais une vapeur montait de la terre et arrosait toute la surface du sol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Et l’ Éternel Dieu forma l’homme, poussière du sol, et souffla dans ses narines une respiration de vie, et l’homme devint une âme vivante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Et l’ Éternel Dieu planta un jardin en Éden, du côté de l’orient, et il y plaça l’homme qu’il avait formé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Et l’ Éternel Dieu fit croître du sol tout arbre agréable à voir et bon à manger, et l’arbre de vie au milieu du jardin, et l’arbre de la connaissance du bien et du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Et un fleuve sortait d’Éden pour arroser le jardin, et de là il se divisait et devenait quatre rivières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Le nom de la première est Pishon: c’est elle qui entoure tout le pays de Havila, où il y a de l’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Et l’or de ce pays-là est bon; là est le bdellium et la pierre d’onyx.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Et le nom de la seconde rivière est Guihon: c’est elle qui entoure tout le pays de Cush.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Et le nom de la troisième rivière est Hiddékel: c’est elle qui coule en avant vers Assur. Et la quatrième rivière, c’est l’Euphrate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Et l’ Éternel Dieu prit l’homme et le plaça dans le jardin d’Éden pour le cultiver et pour le garder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Et l’ Éternel Dieu commanda à l’homme, disant: Tu mangeras librement de tout arbre du jardin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'mais de l’arbre de la connaissance du bien et du mal, tu n’en mangeras pas; car, au jour où tu en mangeras, tu mourras certainement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Et l’ Éternel Dieu dit: Il n’est pas bon que l’homme soit seul; je lui ferai une aide qui lui corresponde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Et l’ Éternel Dieu forma de la terre tous les animaux des champs et tous les oiseaux des cieux, et les fit venir vers l’homme pour voir comment il les nommerait; et tout nom que l’homme donnait à un être vivant fut son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Et l’homme donna des noms à tout le bétail, et aux oiseaux des cieux, et à toutes les bêtes des champs. Mais pour Adam, il ne trouva pas d’aide qui lui corresponde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Et l’ Éternel Dieu fit tomber un profond sommeil sur l’homme, et il dormit; et il prit une de ses côtes, et il en ferma la place avec de la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Et l’ Éternel Dieu forma une femme de la côte qu’il avait prise de l’homme, et l’amena vers l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Et l’homme dit: Cette fois, celle-ci est os de mes os et chair de ma chair; celle-ci sera appelée femme (Isha), parce qu’elle a été prise de l’homme (Ish).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'C’est pourquoi l’homme quittera son père et sa mère, et s’attachera à sa femme, et ils seront une seule chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Et ils étaient tous deux nus, l’homme et sa femme, et ils n’en avaient pas honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, '*Or le serpent était plus rusé qu’aucun animal des champs que l’ Éternel Dieu avait fait; et il dit à la femme: Quoi, Dieu a dit: Vous ne mangerez pas de tout arbre du jardin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Et la femme dit au serpent: Nous mangeons du fruit des arbres du jardin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'mais du fruit de l’arbre qui est au milieu du jardin, Dieu a dit: Vous n’en mangerez point, et vous n’y toucherez point, de peur que vous ne mouriez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Et le serpent dit à la femme: Vous ne mourrez point certainement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'car Dieu sait qu’au jour où vous en mangerez vos yeux seront ouverts, et vous serez comme Dieu, connaissant le bien et le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Et la femme vit que l’arbre était bon à manger, et qu’il était un plaisir pour les yeux, et que l’arbre était désirable pour rendre intelligent; et elle prit de son fruit et en mangea; et elle en donna aussi à son mari [pour qu’il en mange] avec elle, et il en mangea.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Et les yeux de tous deux furent ouverts, et ils connurent qu’ils étaient nus; et ils cousirent ensemble des feuilles de figuier et s’en firent des ceintures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Et ils entendirent la voix de l’ Éternel Dieu qui se promenait dans le jardin au frais du jour. Et l’homme et sa femme se cachèrent de devant l’ Éternel Dieu, au milieu des arbres du jardin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Et l’ Éternel Dieu appela l’homme, et lui dit: Où es-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Et il dit: J’ai entendu ta voix dans le jardin, et j’ai eu peur, car je suis nu, et je me suis caché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Et l’ Éternel Dieu dit: Qui t’a montré que tu étais nu? As-tu mangé de l’arbre dont je t’ai commandé de ne pas manger?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Et l’homme dit: La femme que tu [m’]as donnée [pour être] avec moi, – elle, m’a donné de l’arbre, et j’en ai mangé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Et l’ Éternel Dieu dit à la femme: Qu’est-ce que tu as fait? Et la femme dit: Le serpent m’a séduite, et j’en ai mangé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Et l’ Éternel Dieu dit au serpent: Parce que tu as fait cela, tu es maudit par-dessus tout le bétail et par-dessus toutes les bêtes des champs; tu marcheras sur ton ventre, et tu mangeras la poussière tous les jours de ta vie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'et je mettrai inimitié entre toi et la femme, et entre ta semence et sa semence. Elle te brisera la tête, et toi tu lui briseras le talon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'À la femme il dit: Je rendrai très grandes tes souffrances et ta grossesse; en travail tu enfanteras des enfants, et ton désir sera [tourné] vers ton mari, et lui dominera sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Et à Adam il dit: Parce que tu as écouté la voix de ta femme et que tu as mangé de l’arbre au sujet duquel je t’ai commandé, disant: Tu n’en mangeras pas, – maudit est le sol à cause de toi; tu en mangeras [en travaillant] péniblement tous les jours de ta vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Et il te fera germer des épines et des ronces, et tu mangeras l’herbe des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'À la sueur de ton visage tu mangeras du pain, jusqu’à ce que tu retournes au sol, car c’est de lui que tu as été pris; car tu es poussière et tu retourneras à la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Et l’homme appela sa femme du nom d’Ève, parce qu’elle était la mère de tous les vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Et l’ Éternel Dieu fit à Adam et à sa femme des vêtements de peau, et les revêtit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Et l’ Éternel Dieu dit: Voici, l’homme est devenu comme l’un de nous, pour connaître le bien et le mal; et maintenant, – afin qu’il n’avance pas sa main et ne prenne aussi de l’arbre de vie et n’en mange et ne vive à toujours...!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Et l’ Éternel Dieu le mit hors du jardin d’Éden, pour labourer le sol, d’où il avait été pris:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'il chassa l’homme, et plaça à l’orient du jardin d’Éden les chérubins et la lame de l’épée qui tournait çà et là, pour garder le chemin de l’arbre de vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, '*Et l’homme connut Ève sa femme; et elle conçut, et enfanta Caïn; et elle dit: J’ai acquis un homme avec l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Et elle enfanta encore son frère, Abel. Et Abel paissait le menu bétail, et Caïn labourait la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Et il arriva, au bout de quelque temps, que Caïn apporta, du fruit du sol, une offrande à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Et Abel apporta, lui aussi, des premiers-nés de son troupeau, et de leur graisse. Et l’ Éternel eut égard à Abel et à son offrande;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'mais à Caïn et à son offrande, il n’eut pas égard. Et Caïn fut très irrité, et son visage fut abattu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Et l’ Éternel dit à Caïn: Pourquoi es-tu irrité, et pourquoi ton visage est-il abattu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Si tu fais bien, ne seras-tu pas agréé? Et si tu ne fais pas bien, le péché est couché à la porte. Et son désir sera [tourné] vers toi, et toi tu domineras sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Et Caïn parla à Abel son frère; et il arriva, comme ils étaient aux champs, que Caïn se leva contre Abel, son frère, et le tua.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Et l’ Éternel dit à Caïn: Où est Abel, ton frère? Et il dit: Je ne sais. Suis-je, moi, le gardien de mon frère?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Et il dit: Qu’as-tu fait? La voix du sang de ton frère crie de la terre à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Et maintenant, tu es maudit de la terre qui a ouvert sa bouche pour recevoir de ta main le sang de ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Quand tu laboureras le sol, il ne te donnera plus sa force; tu seras errant et vagabond sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Et Caïn dit à l’ Éternel: Mon châtiment est trop grand pour que j’en porte le poids.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Voici, tu m’as chassé aujourd’hui de dessus la face de la terre, et je serai caché de devant ta face, et je serai errant et vagabond sur la terre; et il arrivera que quiconque me trouvera me tuera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Et l’ Éternel lui dit: C’est pourquoi quiconque tuera Caïn sera puni sept fois. Et l’ Éternel mit un signe sur Caïn, afin que quiconque le trouverait ne le tue point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Et Caïn sortit de devant l’ Éternel; et il habita dans le pays de Nod, à l’orient d’Éden.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Et Caïn connut sa femme, et elle conçut, et enfanta Hénoc; et il bâtit une ville, et appela le nom de la ville d’après le nom de son fils Hénoc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Et à Hénoc naquit Irad; et Irad engendra Mehujaël; et Mehujaël engendra Methushaël; et Methushaël engendra Lémec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Et Lémec prit deux femmes: le nom de l’une était Ada, et le nom de la seconde, Tsilla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Et Ada enfanta Jabal: lui, fut père de ceux qui habitent sous des tentes et ont du bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Et le nom de son frère fut Jubal: lui, fut père de tous ceux qui manient la harpe et la flûte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Et Tsilla, elle aussi, enfanta Tubal-Caïn, qui fut forgeur de tous les outils d’airain et de fer. Et la sœur de Tubal-Caïn fut Naama.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Et Lémec dit à ses femmes: Ada et Tsilla, écoutez ma voix; femmes de Lémec, prêtez l’oreille à ma parole: Je tuerai un homme pour ma blessure, et un jeune homme pour ma meurtrissure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'si Caïn est vengé sept fois, Lémec le sera 77 fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Et Adam connut encore sa femme; et elle enfanta un fils, et appela son nom Seth; car, [dit-elle], Dieu m’a assigné une autre semence au lieu d’Abel; car Caïn l’a tué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Et à Seth, à lui aussi, naquit un fils; et il appela son nom Énosh. Alors on commença à invoquer le nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, '*C’est ici le livre des générations d’Adam. Au jour où Dieu créa Adam, il le fit à la ressemblance de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Il les créa mâle et femelle, et les bénit; et il appela leur nom Adam, au jour où ils furent créés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Et Adam vécut 130 ans, et engendra [un fils] à sa ressemblance, selon son image, et appela son nom Seth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Et les jours d’Adam, après qu’il eut engendré Seth, furent 800 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Et tous les jours qu’Adam vécut furent 930 ans; et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Et Seth vécut 105 ans, et engendra Énosh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Et Seth, après qu’il eut engendré Énosh, vécut 807 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Et tous les jours de Seth furent 912 ans; et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Et Énosh vécut 90 ans, et engendra Kénan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Et Énosh, après qu’il eut engendré Kénan, vécut 815 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Et tous les jours d’Énosh furent 905 ans; et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Et Kénan vécut 70 ans, et engendra Mahalaleël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Et Kénan, après qu’il eut engendré Mahalaleël, vécut 840 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Et tous les jours de Kénan furent 910 ans; et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Et Mahalaleël vécut 65 ans, et engendra Jéred.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Et Mahalaleël, après qu’il eut engendré Jéred, vécut 830 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Et tous les jours de Mahalaleël furent 895 ans; et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Et Jéred vécut 162 ans, et engendra Hénoc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Et Jéred, après qu’il eut engendré Hénoc, vécut 800 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Et tous les jours de Jéred furent 962 ans; et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Et Hénoc vécut 65 ans, et engendra Methushélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Et Hénoc, après qu’il eut engendré Methushélah, marcha avec Dieu 300 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Et tous les jours de Hénoc furent 365 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Et Hénoc marcha avec Dieu; et il ne fut plus, car Dieu le prit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Et Methushélah vécut 187 ans, et engendra Lémec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Et Methushélah, après qu’il eut engendré Lémec, vécut 782 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Et tous les jours de Methushélah furent 969 ans; et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Et Lémec vécut 182 ans, et engendra un fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'et il appela son nom Noé, disant: Celui-ci nous consolera à l’égard de notre ouvrage et du travail de nos mains, à cause du sol que l’ Éternel a maudit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Et Lémec, après qu’il eut engendré Noé, vécut 595 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Et tous les jours de Lémec furent 777 ans; et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Et Noé était âgé de 500 ans, et Noé engendra Sem, Cham, et Japheth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Et il arriva, quand les hommes commencèrent à se multiplier sur la face de la terre et que des filles leur furent nées,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'que les fils de Dieu virent les filles des hommes, qu’elles étaient belles, et ils se prirent des femmes d’entre toutes celles qu’ils choisirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Et l’ Éternel dit: Mon Esprit ne contestera pas à toujours avec l’homme, puisque lui n’est que chair; mais ses jours seront 120 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Les géants étaient sur la terre en ces jours-là, et aussi après que les fils de Dieu furent venus vers les filles des hommes et qu’elles leur eurent donné des enfants: ceux-ci furent les vaillants hommes de jadis, des hommes de renom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Et l’ Éternel vit que la méchanceté de l’homme était grande sur la terre, et que toute l’imagination des pensées de son cœur n’était que méchanceté en tout temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Et l’ Éternel se repentit d’avoir fait l’homme sur la terre, et il s’en affligea dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Et l’ Éternel dit: J’exterminerai de dessus la face de la terre l’homme que j’ai créé, depuis l’homme jusqu’au bétail, jusqu’aux reptiles, et jusqu’aux oiseaux des cieux, car je me repens de les avoir faits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Mais Noé trouva grâce aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, '*Ce sont ici les générations de Noé: Noé était un homme juste; il était parfait parmi ceux de son temps; Noé marchait avec Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Et Noé engendra trois fils: Sem, Cham, et Japheth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Et la terre était corrompue devant Dieu, et la terre était pleine de violence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Et Dieu regarda la terre, et voici, elle était corrompue, car toute chair avait corrompu sa voie sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Et Dieu dit à Noé: La fin de toute chair est venue devant moi, car la terre est pleine de violence à cause d’eux; et voici, je vais les détruire avec la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Fais-toi une arche de bois de gopher. Tu feras l’arche avec des loges, et tu l’enduiras de poix en dedans et en dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Et c’est ainsi que tu la feras: la longueur de l’arche sera de 300 coudées, sa largeur de 50 coudées, et sa hauteur de 30 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Tu feras un jour à l’arche, et tu l’achèveras en [lui donnant] une coudée d’en haut; et tu placeras la porte de l’arche sur son côté; tu y feras un étage inférieur, un second, et un troisième.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Et moi, voici, je fais venir le déluge d’eaux sur la terre, pour détruire de dessous les cieux toute chair en laquelle il y a esprit de vie; tout ce qui est sur la terre expirera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Et j’établis mon alliance avec toi, et tu entreras dans l’arche, toi, et tes fils et ta femme et les femmes de tes fils avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Et de tout ce qui vit, de toute chair, tu feras entrer dans l’arche deux de chaque [espèce], pour les conserver en vie avec toi; ce seront le mâle et la femelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Des oiseaux selon leur espèce, et du bétail selon son espèce, de tout reptile du sol selon son espèce, deux de chaque [espèce] entreront vers toi, pour [les] conserver en vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Et toi, prends de tout aliment qui se mange, et tu en feras provision près de toi; et cela vous sera pour nourriture, à toi et à eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, '– Et Noé le fit; selon tout ce que Dieu lui avait commandé, ainsi il fit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Et l’ Éternel dit à Noé: Entre dans l’arche, toi et toute ta maison, car je t’ai vu juste devant moi en cette génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'De toutes les bêtes pures tu prendras sept par sept, le mâle et sa femelle, et des bêtes qui ne sont pas pures, deux, le mâle et sa femelle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'de même des oiseaux des cieux, sept par sept, mâle et femelle, pour conserver en vie une semence sur la face de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Car encore sept jours, et je fais pleuvoir sur la terre pendant 40 jours et 40 nuits, et j’exterminerai de dessus la face de la terre tout ce qui existe [et] que j’ai fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Et Noé fit selon tout ce que l’ Éternel lui avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Et Noé était âgé de 600 ans quand le déluge eut lieu [et qu’il vint] des eaux sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Et Noé entra dans l’arche, et ses fils et sa femme et les femmes de ses fils avec lui, à cause des eaux du déluge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Des bêtes pures, et des bêtes qui ne sont pas pures, et des oiseaux, et de tout ce qui rampe sur le sol,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'il en entra deux par deux vers Noé dans l’arche, mâle et femelle, comme Dieu l’avait commandé à Noé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Et il arriva, au bout de sept jours, que les eaux du déluge furent sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'L’an 600 de la vie de Noé, au second mois, le dix-septième jour du mois, en ce jour-là, toutes les fontaines du grand abîme se rompirent et les écluses des cieux s’ouvrirent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'et la pluie fut sur la terre 40 jours et 40 nuits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'En ce même jour-là, Noé, et Sem et Cham et Japheth, fils de Noé, et la femme de Noé, et les trois femmes de ses fils avec eux, entrèrent dans l’arche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'eux, et tous les animaux selon leur espèce, et tout le bétail selon son espèce, et tous les reptiles qui rampent sur la terre selon leur espèce, et tous les oiseaux selon leur espèce, tout oiseau de toute aile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'et ils entrèrent vers Noé dans l’arche, deux par deux, de toute chair ayant en elle esprit de vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Et ce qui entra, entra mâle et femelle, de toute chair, comme Dieu le lui avait commandé. Et l’ Éternel ferma [l’arche] sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Et le déluge fut sur la terre 40 jours; et les eaux crûrent et soulevèrent l’arche, et elle fut élevée au-dessus de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Et les eaux se renforcèrent et crûrent beaucoup sur la terre; et l’arche flottait sur la face des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Et les eaux se renforcèrent extraordinairement sur la terre; et toutes les hautes montagnes qui étaient sous tous les cieux furent couvertes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Les eaux se renforcèrent de 15 coudées par-dessus, et les montagnes furent couvertes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Et toute chair qui se mouvait sur la terre expira, tant les oiseaux que le bétail et les bêtes [des champs] et tout ce qui fourmille sur la terre, et tout homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Tout ce qui avait le souffle de vie dans ses narines, de tout ce qui était sur la terre sèche, mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Et tout ce qui existait sur la face de la terre fut détruit, depuis l’homme jusqu’au bétail, jusqu’aux reptiles et jusqu’aux oiseaux des cieux: ils furent détruits de dessus la terre; et il ne resta que Noé et ce qui était avec lui dans l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Et les eaux se renforcèrent sur la terre, 150 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Et Dieu se souvint de Noé, et de tous les animaux et de tout le bétail, qui étaient avec lui dans l’arche; et Dieu fit passer un vent sur la terre, et les eaux baissèrent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'et les fontaines de l’abîme et les écluses des cieux furent fermées, et la pluie qui tombait du ciel fut retenue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Et les eaux se retirèrent de dessus la terre, allant et se retirant; et les eaux diminuèrent au bout de 150 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Et l’arche reposa sur les montagnes d’Ararat, au septième mois, au dix-septième jour du mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Et les eaux allèrent diminuant jusqu’au dixième mois; au dixième [mois], le premier [jour] du mois, les sommets des montagnes apparurent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Et il arriva, au bout de 40 jours, que Noé ouvrit la fenêtre de l’arche qu’il avait faite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'et il lâcha le corbeau, qui sortit, allant et revenant jusqu’à ce que les eaux aient séché de dessus la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Et il lâcha d’avec lui la colombe, pour voir si les eaux avaient baissé sur la face du sol;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'mais la colombe ne trouva pas où poser la plante de son pied, et revint à lui dans l’arche, car les eaux étaient sur la face de toute la terre; et il étendit sa main, et la prit, et la fit entrer auprès de lui dans l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Et il attendit encore sept autres jours, et il lâcha de nouveau la colombe hors de l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Et la colombe vint à lui au temps du soir, et voici, dans son bec, une feuille d’olivier arrachée. Et Noé sut que les eaux avaient baissé sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Et il attendit encore sept autres jours, et il lâcha la colombe, et elle ne revint plus de nouveau vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Et il arriva, l’an 601, au premier [mois], le premier [jour] du mois, que les eaux furent séchées de dessus la terre; et Noé ôta la couverture de l’arche et regarda, et voici, la face du sol avait séché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Et au second mois, le vingt-septième jour du mois, la terre fut sèche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Et Dieu parla à Noé, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Sors de l’arche, toi, et ta femme et tes fils et les femmes de tes fils avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Fais sortir avec toi tout animal qui est avec toi, de toute chair, tant oiseaux que bétail, et tout reptile qui rampe sur la terre, et qu’ils foisonnent en la terre, et fructifient et multiplient sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Et Noé sortit, et ses fils, et sa femme et les femmes de ses fils avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Tout animal, tout reptile et tout oiseau, tout ce qui se meut sur la terre, selon leurs espèces, sortirent de l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Et Noé bâtit un autel à l’ Éternel, et prit de toute bête pure et de tout oiseau pur, et offrit des holocaustes sur l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Et l’ Éternel flaira une odeur agréable; et l’ Éternel dit en son cœur: Je ne maudirai plus de nouveau le sol à cause de l’homme, car l’imagination du cœur de l’homme est mauvaise dès sa jeunesse; et je ne frapperai plus de nouveau tout ce qui est vivant, comme je l’ai fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Désormais, tant que seront les jours de la terre, les semailles et la moisson, et le froid et le chaud, et l’été et l’hiver, et le jour et la nuit, ne cesseront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Et Dieu bénit Noé et ses fils, et leur dit: Fructifiez et multipliez et remplissez la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Et vous serez un sujet de crainte et de frayeur pour tout animal de la terre, et pour tout oiseau des cieux, pour tout ce qui se meut sur la terre, aussi bien que pour tous les poissons de la mer; ils sont livrés entre vos mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Tout ce qui se meut [et] qui est vivant vous sera pour nourriture; comme l’herbe verte, je vous donne tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Seulement, vous ne mangerez pas la chair avec sa vie, [c’est-à-dire] son sang;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'et certes je redemanderai le sang de vos vies; de la main de tout animal je le redemanderai, et de la main de l’homme; de la main de chacun, de son frère, je redemanderai la vie de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Qui aura versé le sang de l’homme, par l’homme son sang sera versé; car à l’image de Dieu, il a fait l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Et vous, fructifiez et multipliez; foisonnez sur la terre, et multipliez sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Et Dieu parla à Noé et à ses fils avec lui, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Et moi, voici, j’établis mon alliance avec vous, et avec votre semence après vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'et avec tout être vivant qui est avec vous, tant oiseaux que bétail et tout animal de la terre avec vous, d’entre tout ce qui est sorti de l’arche, – tout animal de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Et j’établis mon alliance avec vous, et toute chair ne périra plus par les eaux du déluge, et il n’y aura plus de déluge pour détruire la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Et Dieu dit: C’est ici le signe de l’alliance que je mets entre moi et vous et tout être vivant qui est avec vous, pour les générations, à toujours:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'je mettrai mon arc dans la nuée, et il sera pour signe d’alliance entre moi et la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'et il arrivera que quand je ferai venir des nuages sur la terre, alors l’arc apparaîtra dans la nuée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'et je me souviendrai de mon alliance qui est entre moi et vous et tout être vivant de toute chair; et les eaux ne deviendront plus un déluge pour détruire toute chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Et l’arc sera dans la nuée, et je le verrai pour me souvenir de l’alliance perpétuelle entre Dieu et tout être vivant de toute chair qui est sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Et Dieu dit à Noé: C’est là le signe de l’alliance que j’établis entre moi et toute chair qui est sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, '*Et les fils de Noé qui sortirent de l’arche étaient Sem, et Cham, et Japheth: et Cham fut le père de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Ces trois sont fils de Noé; et c’est d’eux que la population fut disséminée sur toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Et Noé commença à être cultivateur et il planta une vigne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'et il but du vin, et il s’enivra et se découvrit au milieu de la tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Et Cham, père de Canaan, vit la nudité de son père, et le rapporta à ses deux frères, dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Et Sem et Japheth prirent le manteau et le mirent, les deux, sur leurs épaules et marchèrent en arrière et couvrirent la nudité de leur père; et leur visage était [tourné] en arrière, et ils ne virent pas la nudité de leur père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Et Noé se réveilla de son vin et sut ce que lui avait fait son plus jeune fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'et il dit: Maudit soit Canaan! Il sera l’esclave des esclaves de ses frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Et il dit: Béni soit l’ Éternel, le Dieu de Sem, et que Canaan soit son esclave!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Que Dieu élargisse Japheth, et qu’il demeure dans les tentes de Sem, et que Canaan soit son esclave!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Et Noé vécut, après le déluge, 350 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Et tous les jours de Noé furent 950 ans; et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, '*Et ce sont ici les générations des fils de Noé: Sem, Cham, et Japheth; il leur naquit des fils après le déluge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Les fils de Japheth: Gomer, et Magog, et Madaï, et Javan, et Tubal, et Méshec, et Tiras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, '– Et les fils de Gomer: Ashkenaz, et Riphath, et Togarma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, '– Et les fils de Javan: Élisha, et Tarsis, Kittim, et Dodanim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, '– De ceux-là est venue la répartition des îles des nations selon leurs pays, chacune selon sa langue, selon leurs familles, dans leurs nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Et les fils de Cham: Cush, et Mitsraïm, et Puth, et Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, '– Et les fils de Cush: Seba, et Havila, et Sabta, et Rahma, et Sabteca. Et les fils de Rahma: Sheba et Dedan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Et Cush engendra Nimrod: lui, commença à être puissant sur la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'il fut un puissant chasseur devant l’ Éternel; c’est pourquoi on dit: Comme Nimrod, puissant chasseur devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Et le commencement de son royaume fut Babel, et Érec, et Accad, et Calné, au pays de Shinhar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'De ce pays-là sortit Assur, et il bâtit Ninive, et Rehoboth-Ir, et Calakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'et Résen entre Ninive et Calakh: c’est la grande ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, '– Et Mitsraïm engendra les Ludim, et les Anamim, et les Lehabim, et les Naphtukhim,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'et les Pathrusim, et les Caslukhim (d’où sortirent les Philistins), et les Caphtorim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, '– Et Canaan engendra Sidon, son premier-né, et Heth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'et le Jébusien, et l’Amoréen, et le Guirgasien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'et le Hévien, et l’Arkien, et le Sinien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'et l’Arvadien, et le Tsemarien, et le Hamathien. Et ensuite les familles des Cananéens se dispersèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Et les limites des Cananéens furent depuis Sidon, quand tu viens vers Guérar, jusqu’à Gaza; quand tu viens vers Sodome et Gomorrhe et Adma et Tseboïm, jusqu’à Lésha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, '– Ce sont là les fils de Cham, selon leurs familles, selon leurs langues, dans leurs pays, dans leurs nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Et à Sem, père de tous les fils d’Héber, [et] frère de Japheth, l’aîné, à lui aussi il naquit [des fils].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Les fils de Sem: Élam, et Assur, et Arpacshad, et Lud, et Aram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, '– Et les fils d’Aram: Uts, et Hul, et Guéther, et Mash.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, '– Et Arpacshad engendra Shélakh, et Shélakh engendra Héber.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Et il naquit à Héber deux fils: le nom de l’un fut Péleg, car en ses jours la terre fut partagée; et le nom de son frère fut Joktan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Et Joktan engendra Almodad, et Shéleph, et Hatsarmaveth, et Jérakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'et Hadoram, et Uzal, et Dikla,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'et Obal, et Abimaël, et Sheba,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'et Ophir, et Havila, et Jobab. Tous ceux-là étaient fils de Joktan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Et leur demeure était depuis Mésha, quand tu viens vers Sephar, montagne de l’orient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, '– Ce sont là les fils de Sem selon leurs familles, selon leurs langues, dans leurs pays, selon leurs nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Ce sont là les familles des fils de Noé, selon leurs générations, dans leurs nations; et c’est d’eux qu’est venue la répartition des nations sur la terre après le déluge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Et toute la terre avait une seule langue et les mêmes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Et il arriva que lorsqu’ils partirent de l’orient, ils trouvèrent une plaine dans le pays de Shinhar; et ils y habitèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Et ils se dirent l’un à l’autre: Allons, faisons des briques, et cuisons-les au feu. Et ils avaient la brique pour pierre, et ils avaient le bitume pour mortier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Et ils dirent: Allons, bâtissons-nous une ville, et une tour dont le sommet [atteigne] jusqu’aux cieux; et faisons-nous un nom, de peur que nous ne soyons dispersés sur la face de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Et l’ Éternel descendit pour voir la ville et la tour que bâtissaient les fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Et l’ Éternel dit: Voici, c’est un seul peuple, et ils n’ont, eux tous, qu’un seul langage, et ils ont commencé à faire ceci; et maintenant ils ne seront empêchés en rien de ce qu’ils pensent faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Allons, descendons, et confondons là leur langage, afin qu’ils n’entendent pas le langage l’un de l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Et l’ Éternel les dispersa de là sur la face de toute la terre; et ils cessèrent de bâtir la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'C’est pourquoi on appela son nom Babel, car là l’ Éternel confondit le langage de toute la terre; et de là l’ Éternel les dispersa sur la face de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, '*Ce sont ici les générations de Sem: Sem était âgé de 100 ans, et il engendra Arpacshad, deux ans après le déluge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Et Sem, après qu’il eut engendré Arpacshad, vécut 500 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Et Arpacshad vécut 35 ans, et engendra Shélakh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Et Arpacshad, après qu’il eut engendré Shélakh, vécut 403 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Et Shélakh vécut 30 ans, et engendra Héber.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Et Shélakh, après qu’il eut engendré Héber, vécut 403 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Et Héber vécut 34 ans, et engendra Péleg.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Et Héber, après qu’il eut engendré Péleg, vécut 430 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Et Péleg vécut 30 ans, et engendra Rehu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Et Péleg, après qu’il eut engendré Rehu, vécut 209 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Et Rehu vécut 32 ans, et engendra Serug.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Et Rehu, après qu’il eut engendré Serug, vécut 207 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Et Serug vécut 30 ans, et engendra Nakhor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Et Serug, après qu’il eut engendré Nakhor, vécut 200 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Et Nakhor vécut 29 ans, et engendra Térakh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Et Nakhor, après qu’il eut engendré Térakh, vécut 119 ans; et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Et Térakh vécut 70 ans, et engendra Abram, Nakhor, et Haran.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, '*Et ce sont ici les générations de Térakh: Térakh engendra Abram, Nakhor, et Haran. Et Haran engendra Lot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Et Haran mourut en la présence de Térakh, son père, au pays de sa naissance, à Ur des Chaldéens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, '– Et Abram et Nakhor prirent des femmes: le nom de la femme d’Abram était Saraï, et le nom de la femme de Nakhor, Milca, fille de Haran, père de Milca et père de Jisca.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Et Saraï était stérile, elle n’avait pas d’enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Et Térakh prit Abram son fils, et Lot, fils de Haran, fils de son fils, et Saraï, sa belle-fille, femme d’Abram, son fils; et ils sortirent ensemble d’Ur des Chaldéens pour aller au pays de Canaan; et ils vinrent jusqu’à Charan, et habitèrent là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Et les jours de Térakh furent 205 ans; et Térakh mourut à Charan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Et l’ Éternel avait dit à Abram: Va-t’en de ton pays, et de ta parenté, et de la maison de ton père, dans le pays que je te montrerai;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'et je te ferai devenir une grande nation, et je te bénirai, et je rendrai ton nom grand, et tu seras une bénédiction;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'et je bénirai ceux qui te béniront, et je maudirai ceux qui te maudiront; et en toi seront bénies toutes les familles de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Et Abram s’en alla, comme l’ Éternel lui avait dit; et Lot s’en alla avec lui. Et Abram était âgé de 75 ans lorsqu’il sortit de Charan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Et Abram prit Saraï, sa femme, et Lot, fils de son frère, et tout leur bien qu’ils avaient amassé, et les âmes qu’ils avaient acquises à Charan, et ils sortirent pour aller au pays de Canaan; et ils entrèrent au pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Et Abram passa au travers du pays, jusqu’au lieu de Sichem, jusqu’au chêne de Moré. Et le Cananéen était alors dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Et l’ Éternel apparut à Abram, et dit: Je donnerai ce pays à ta semence. Et [Abram] bâtit là un autel à l’ Éternel, qui lui était apparu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Et il se transporta de là vers la montagne, à l’orient de Béthel, et tendit sa tente, [ayant] Béthel à l’occident et Aï à l’orient; et il bâtit là un autel à l’ Éternel et invoqua le nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Et Abram partit, marchant et allant vers le midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Et il y eut une famine dans le pays; et Abram descendit en Égypte pour y séjourner, car la famine pesait sur le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Et il arriva, comme il était près d’entrer en Égypte, qu’il dit à Saraï, sa femme: Voici, je sais que tu es une femme belle de visage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'et il arrivera que lorsque les Égyptiens te verront, ils diront: C’est sa femme; et ils me tueront, et te laisseront vivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Dis, je te prie, que tu es ma sœur, afin qu’il m’arrive du bien en considération de toi, et que mon âme vive à cause de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Et il arriva que, lorsque Abram entra en Égypte, les Égyptiens virent sa femme, qu’elle était très belle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Et les princes du Pharaon la virent, et la louèrent devant le Pharaon; et la femme fut emmenée dans la maison du Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Et il traita bien Abram à cause d’elle; et il eut du menu bétail et du gros bétail, et des ânes, et des serviteurs et des servantes, et des ânesses, et des chameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Et l’ Éternel frappa de grandes plaies le Pharaon et sa maison, à cause de Saraï, femme d’Abram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Et le Pharaon appela Abram, et dit: Qu’est-ce que tu m’as fait? Pourquoi ne m’as-tu pas déclaré qu’elle était ta femme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Pourquoi as-tu dit: Elle est ma sœur, de sorte que je l’ai prise pour ma femme; et maintenant, voici ta femme: prends-la, et va-t’en.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Et le Pharaon donna ordre à ses gens à son sujet, et ils le renvoyèrent, lui, et sa femme, et tout ce qui était à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Et Abram monta d’Égypte vers le midi, lui, et sa femme, et tout ce qui était à lui, et Lot avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Et Abram était très riche en troupeaux, en argent et en or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Et il s’en alla, en ses traites, du midi jusqu’à Béthel, jusqu’au lieu où était sa tente au commencement, entre Béthel et Aï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'au lieu où était l’autel qu’il y avait fait auparavant; et Abram invoqua là le nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Et Lot aussi, qui allait avec Abram, avait du menu et du gros bétail, et des tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Et le pays ne pouvait les porter pour qu’ils habitent ensemble; car leur bien était grand, et ils ne pouvaient habiter ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Et il y eut querelle entre les bergers des troupeaux d’Abram et les bergers des troupeaux de Lot. Et le Cananéen et le Phérézien habitaient alors dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Et Abram dit à Lot: Qu’il n’y ait point, je te prie, de contestation entre moi et toi, et entre mes bergers et tes bergers, car nous sommes frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Tout le pays n’est-il pas devant toi? Sépare-toi, je te prie, d’avec moi. Si [tu prends] la gauche, j’irai à droite; et si [tu prends] la droite, j’irai à gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Et Lot leva ses yeux et vit toute la plaine du Jourdain, qui était arrosée partout, avant que l’ Éternel détruise Sodome et Gomorrhe, comme le jardin de l’ Éternel, comme le pays d’Égypte, quand tu viens à Tsoar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Et Lot choisit pour lui toute la plaine du Jourdain; et Lot partit vers l’orient. Et ils se séparèrent l’un de l’autre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram habita dans le pays de Canaan, et Lot habita dans les villes de la plaine, et dressa ses tentes jusqu’à Sodome.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Or les hommes de Sodome étaient méchants, et grands pécheurs devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Et l’ Éternel dit à Abram, après que Lot se fut séparé de lui: Lève tes yeux, et regarde, du lieu où tu es, vers le nord, et vers le midi, et vers l’orient, et vers l’occident;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'car tout le pays que tu vois, je te le donnerai, et à ta semence, pour toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'et je ferai que ta semence sera comme la poussière de la terre; en sorte que, si quelqu’un peut compter la poussière de la terre, ta semence aussi sera comptée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Lève-toi, et promène-toi dans le pays en long et en large, car je te le donnerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Et Abram leva ses tentes, et vint et habita auprès des chênes de Mamré, qui sont à Hébron; et il bâtit là un autel à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, '*Et il arriva, aux jours d’Amraphel, roi de Shinhar, d’Arioc, roi d’Ellasar, de Kedor-Laomer, roi d’Élam, et de Tidhal, roi des nations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'qu’ils firent la guerre contre Béra, roi de Sodome, et contre Birsha, roi de Gomorrhe, [contre] Shineab, roi d’Adma, et [contre] Shéméber, roi de Tseboïm, et [contre] le roi de Béla, qui est Tsoar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Tous ceux-ci se joignirent dans la vallée de Siddim, qui est la mer Salée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Douze ans, ils avaient été asservis à Kedor-Laomer, mais, la treizième année, ils se révoltèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Et la quatorzième année, Kedor-Laomer vint, et les rois qui étaient avec lui, et ils frappèrent les Rephaïm à Ashteroth-Karnaïm, et les Zuzim à Ham, et les Émim à Shavé-Kiriathaïm,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'et les Horiens dans leur montagne de Séhir, jusqu’à El-Paran, qui est près du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Et ils retournèrent, et vinrent à En-Mishpath, qui est Kadès, et ils frappèrent toute la contrée des Amalékites, et aussi les Amoréens qui habitaient à Hatsatson-Thamar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Et le roi de Sodome, et le roi de Gomorrhe, et le roi d’Adma, et le roi de Tseboïm, et le roi de Béla, qui est Tsoar, sortirent et se rangèrent en bataille contre eux dans la vallée de Siddim,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'contre Kedor-Laomer, roi d’Élam, et Tidhal, roi des nations, et Amraphel, roi de Shinhar, et Arioc, roi d’Ellasar: quatre rois contre cinq.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Et la vallée de Siddim était pleine de puits de bitume; et les rois de Sodome et de Gomorrhe s’enfuirent, et y tombèrent; et ceux qui restèrent s’enfuirent dans la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Et ils prirent tous les biens de Sodome et de Gomorrhe, et tous leurs vivres, et ils s’en allèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Ils prirent aussi Lot, fils du frère d’Abram, et son bien, et ils s’en allèrent; car [Lot] habitait dans Sodome.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Et un homme qui était échappé, vint et le rapporta à Abram, l’Hébreu, qui demeurait auprès des chênes de Mamré, l’Amoréen, frère d’Eshcol et frère d’Aner: ceux-ci étaient alliés d’Abram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Et Abram apprit que son frère avait été emmené captif, et il mit en campagne ses hommes exercés, 318 [hommes], nés dans sa maison, et poursuivit [les rois] jusqu’à Dan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'et il divisa [sa troupe, et se jeta] sur eux de nuit, lui et ses serviteurs, et il les frappa, et les poursuivit jusqu’à Hoba, qui est à la gauche de Damas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Et il ramena tout le bien, et ramena aussi Lot, son frère, et son bien, et aussi les femmes et le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Et comme il s’en revenait après avoir frappé Kedor-Laomer et les rois qui étaient avec lui, le roi de Sodome sortit à sa rencontre dans la vallée de Shavé, qui est la vallée du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Et Melchisédec, roi de Salem, fit apporter du pain et du vin, (or il était sacrificateur du ✶Dieu Très-haut);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'et il le bénit, et dit: Béni soit Abram de par le ✶Dieu Très-haut, possesseur des cieux et de la terre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Et béni soit le ✶Dieu Très-haut, qui a livré tes ennemis entre tes mains! Et [Abram] lui donna la dîme de tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Et le roi de Sodome dit à Abram: Donne-moi les personnes, et prends les biens pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Et Abram dit au roi de Sodome: J’ai levé ma main vers l’ Éternel, le ✶Dieu Très-haut, possesseur des cieux et de la terre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'si, depuis un fil jusqu’à une courroie de sandale, oui, si, de tout ce qui est à toi, je prends quoi que ce soit,... afin que tu ne dises pas: Moi, j’ai enrichi Abram!...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'sauf seulement ce qu’ont mangé les jeunes gens, et la part des hommes qui sont allés avec moi, Aner, Eshcol et Mamré: eux, ils prendront leur part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, '*Après ces choses, la parole de l’ Éternel fut [adressée] à Abram dans une vision, disant: Abram, ne crains point; moi, je suis ton bouclier [et] ta très grande récompense.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Et Abram dit: Seigneur Éternel, que me donneras-tu? Je m’en vais sans enfants, et l’héritier de ma maison, c’est Éliézer de Damas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Et Abram dit: Voici, tu ne m’as pas donné de postérité; et voici, celui qui est né dans ma maison est mon héritier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Et voici, la parole de l’ Éternel [vint] à lui, disant: Celui-ci ne sera pas ton héritier; mais celui qui sortira de tes entrailles, lui, sera ton héritier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Et il le fit sortir dehors, et dit: Regarde vers les cieux, et compte les étoiles, si tu peux les compter. Et il lui dit: Ainsi sera ta semence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Et il crut l’ Éternel; et il lui compta cela à justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Et il lui dit: Moi, je suis l’ Éternel, qui t’ai fait sortir d’Ur des Chaldéens, afin de te donner ce pays-ci pour le posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Et il dit: Seigneur Éternel, à quoi connaîtrai-je que je le posséderai?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Et il lui dit: Prends une génisse de trois ans, et une chèvre de trois ans, et un bélier de trois ans, et une tourterelle, et un jeune pigeon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Et il prit toutes ces choses, et les partagea par le milieu, et en mit les moitiés l’une vis-à-vis de l’autre; mais il ne partagea pas les oiseaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Et les oiseaux de proie descendirent sur ces bêtes mortes; et Abram les écarta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Et comme le soleil se couchait, un profond sommeil tomba sur Abram; et voici, une frayeur, une grande obscurité, tomba sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Et [l’ Éternel] dit à Abram: Sache certainement que ta semence séjournera dans un pays qui n’est pas le sien, et ils l’asserviront, et l’opprimeront pendant 400 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mais aussi je jugerai, moi, la nation qui les aura asservis; et après cela ils sortiront avec de grands biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Et toi, tu t’en iras vers tes pères en paix; tu seras enterré en bonne vieillesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Et en la quatrième génération ils reviendront ici, car l’iniquité des Amoréens n’est pas encore venue à son comble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Et il arriva que le soleil s’étant couché, il y eut une obscurité épaisse; et voici une fournaise fumante, et un brandon de feu qui passa entre les pièces des animaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'En ce jour-là, l’ Éternel fit une alliance avec Abram, disant: Je donne ce pays à ta semence, depuis le fleuve d’Égypte jusqu’au grand fleuve, le fleuve Euphrate:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'le Kénien, et le Kenizien, et le Kadmonien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'et le Héthien, et le Phérézien, et les Rephaïm,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'et l’Amoréen, et le Cananéen, et le Guirgasien, et le Jébusien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Et Saraï, femme d’Abram, ne lui donnait pas d’enfant; et elle avait une servante égyptienne, et son nom était Agar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Et Saraï dit à Abram: Tu vois que l’ Éternel m’a empêchée d’avoir des enfants; va, je te prie, vers ma servante; peut-être me bâtirai-je [une maison] par elle. Et Abram écouta la voix de Saraï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Et Saraï, femme d’Abram, prit Agar, l’Égyptienne, sa servante, après qu’Abram eut demeuré dix ans au pays de Canaan, et la donna à Abram, son mari, pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Et il vint vers Agar, et elle conçut; et elle vit qu’elle avait conçu, et sa maîtresse fut méprisée à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Et Saraï dit à Abram: Le tort qui m’est fait est sur toi: moi, je t’ai donné ma servante dans ton sein; et elle voit qu’elle a conçu, et je suis méprisée à ses yeux. L’ Éternel jugera entre moi et toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Et Abram dit à Saraï: Voici, ta servante est entre tes mains, fais-lui comme il sera bon à tes yeux. Et Saraï la maltraita, et elle s’enfuit de devant elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Mais l’Ange de l’ Éternel la trouva près d’une fontaine d’eau dans le désert, près de la fontaine qui est sur le chemin de Shur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Et il dit: Agar, servante de Saraï, d’où viens-tu, et où vas-tu? Et elle dit: Je m’enfuis de devant Saraï, ma maîtresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Et l’Ange de l’ Éternel lui dit: Retourne vers ta maîtresse, et humilie-toi sous sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Et l’Ange de l’ Éternel lui dit: Je multiplierai beaucoup ta semence, et elle ne pourra se nombrer à cause de sa multitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Et l’Ange de l’ Éternel lui dit: Voici, tu es enceinte, et tu enfanteras un fils, et tu appelleras son nom Ismaël, car l’ Éternel a entendu ton affliction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Et lui, sera un âne sauvage; sa main sera contre tous, et la main de tous sera contre lui; et il habitera à la vue de tous ses frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Et elle appela le nom de l’ Éternel qui lui avait parlé: Tu es le ✶Dieu qui te révèles; car elle dit: N’ai-je pas aussi vu ici, après qu’il s’est révélé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'C’est pourquoi on a appelé le puits: Beër-Lakhaï-roï; voici, il est entre Kadès et Béred.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Et Agar enfanta un fils à Abram; et Abram appela le nom de son fils, qu’Agar enfanta, Ismaël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Et Abram était âgé de 86 ans lorsque Agar enfanta Ismaël à Abram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, '*Et Abram était âgé de 99 ans; et l’ Éternel apparut à Abram, et lui dit: Je suis le ✶Dieu Tout-puissant; marche devant ma face, et sois parfait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'et je mettrai mon alliance entre moi et toi, et je te multiplierai extrêmement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Et Abram tomba sur sa face, et Dieu parla avec lui, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Quant à moi, voici, mon alliance est avec toi, et tu seras père d’une multitude de nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'et ton nom ne sera plus appelé Abram, mais ton nom sera Abraham, car je t’ai établi père d’une multitude de nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Et je te ferai fructifier extrêmement, et je te ferai devenir des nations; et des rois sortiront de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Et j’établirai mon alliance entre moi et toi et ta semence après toi, en leurs générations, pour être une alliance perpétuelle, afin que je sois ton Dieu, à toi et à ta semence après toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Et je te donne, et à ta semence après toi, le pays de ton séjournement, tout le pays de Canaan, en possession perpétuelle; et je serai leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Et Dieu dit à Abraham: Et toi, tu garderas mon alliance, toi et ta semence après toi, en leurs générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'C’est ici mon alliance, que vous garderez entre moi et vous et ta semence après toi: que tout mâle d’entre vous soit circoncis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Et vous circoncirez la chair de votre prépuce, et ce sera un signe d’alliance entre moi et vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Et tout mâle de huit jours, en vos générations, sera circoncis parmi vous, celui qui est né dans la maison, et celui qui est acheté à prix d’argent, tout fils d’étranger qui n’est point de ta semence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'On ne manquera point de circoncire celui qui est né dans ta maison et celui qui est acheté de ton argent; et mon alliance sera en votre chair comme alliance perpétuelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Et le mâle incirconcis, qui n’aura point été circoncis en la chair de son prépuce, cette âme sera retranchée de ses peuples: il a violé mon alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Et Dieu dit à Abraham: Quant à Saraï, ta femme, tu n’appelleras plus son nom Saraï; mais Sara sera son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Et je la bénirai, et même je te donnerai d’elle un fils; et je la bénirai, et elle deviendra des nations; des rois de peuples sortiront d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Et Abraham tomba sur sa face, et il rit et dit en son cœur: Naîtrait-il [un fils] à un homme âgé de 100 ans? et Sara, âgée de 90 ans, enfanterait-elle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Et Abraham dit à Dieu: Oh, qu’Ismaël vive devant toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Et Dieu dit: Certainement Sara, ta femme, t’enfantera un fils; et tu appelleras son nom Isaac; et j’établirai mon alliance avec lui, comme alliance perpétuelle, pour sa semence après lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Et, à l’égard d’Ismaël, je t’ai exaucé: voici, je l’ai béni, et je le ferai fructifier et multiplier extrêmement; il engendrera douze chefs, et je le ferai devenir une grande nation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Mais mon alliance, je l’établirai avec Isaac, que Sara t’enfantera en cette saison, l’année qui vient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Et ayant achevé de parler avec lui, Dieu monta d’auprès d’Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Et Abraham prit Ismaël, son fils, et tous ceux qui étaient nés dans sa maison, et tous ceux qui avaient été achetés de son argent, tous les mâles parmi les gens de la maison d’Abraham, et il circoncit la chair de leur prépuce en ce même jour-là, comme Dieu lui avait dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Et Abraham était âgé de 99 ans lorsqu’il fut circoncis en la chair de son prépuce;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'et Ismaël, son fils, était âgé de 13 ans lorsqu’il fut circoncis en la chair de son prépuce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'En ce même jour-là Abraham fut circoncis, et Ismaël son fils,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'et tous les hommes de sa maison, ceux qui étaient nés dans la maison, et ceux qui avaient été achetés à prix d’argent d’entre les fils de l’étranger, furent circoncis avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, '*Et l’ Éternel lui apparut auprès des chênes de Mamré; et il était assis à l’entrée de la tente, pendant la chaleur du jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Et il leva les yeux et regarda; et voici, trois hommes se tenaient près de lui; et quand il les vit, il courut de l’entrée de la tente à leur rencontre, et se prosterna en terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'et il dit: Seigneur, si j’ai trouvé grâce à tes yeux, ne passe point outre, je te prie, d’auprès de ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Qu’on prenne, je te prie, un peu d’eau, et vous laverez vos pieds, et vous vous reposerez sous l’arbre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'et je prendrai un morceau de pain, et vous réconforterez votre cœur, après quoi vous passerez outre; car c’est pour cela que vous avez passé près de votre serviteur. Et ils dirent: Fais ainsi, comme tu l’as dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Et Abraham alla en hâte dans la tente vers Sara, et dit: Prends vite trois mesures de fleur de farine, pétris, et fais des gâteaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Et Abraham courut au troupeau, et prit un veau tendre et bon, et le donna à un jeune homme qui se hâta de l’apprêter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Et il prit de la crème et du lait, et le veau qu’il avait apprêté, et le mit devant eux, et il se tint auprès d’eux sous l’arbre, et ils mangèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Et ils lui dirent: Où est Sara, ta femme? Et il dit: Voici, dans la tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Et il dit: Je reviendrai certainement vers toi quand [son] terme sera là, et voici, Sara, ta femme, aura un fils. Et Sara écoutait à l’entrée de la tente, qui était derrière lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Or Abraham et Sara étaient vieux, avancés en âge; Sara avait cessé d’avoir ce qu’ont les femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Et Sara rit en elle-même, disant: Étant vieille, aurai-je du plaisir?... mon seigneur aussi est âgé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Et l’ Éternel dit à Abraham: Pourquoi Sara a-t-elle ri, disant: Est-ce que vraiment j’aurai un enfant, moi qui suis vieille?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Y a-t-il quelque chose qui soit trop difficile pour l’ Éternel? Au temps fixé je reviendrai vers toi, quand [son] terme sera là, et Sara aura un fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Et Sara [le] nia, disant: Je n’ai pas ri; car elle eut peur. Et il dit: Non, car tu as ri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Et les hommes se levèrent de là, et regardèrent du côté de Sodome; et Abraham allait avec eux pour leur faire la conduite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Et l’ Éternel dit: Cacherai-je à Abraham ce que je vais faire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'puisque Abraham doit certainement devenir une nation grande et forte, et qu’en lui seront bénies toutes les nations de la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Car je le connais, [et je sais] qu’il commandera à ses fils et à sa maison après lui de garder la voie de l’ Éternel, pour pratiquer ce qui est juste et droit, afin que l’ Éternel fasse venir sur Abraham ce qu’il a dit à son égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Et l’ Éternel dit: Parce que le cri de Sodome et de Gomorrhe est grand, et que leur péché est très aggravé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'eh bien, je descendrai, et je verrai s’ils ont fait entièrement selon le cri qui en est venu jusqu’à moi; et sinon, je le saurai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Et les hommes se détournèrent de là, et ils allaient vers Sodome; et Abraham se tenait encore devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Et Abraham s’approcha, et dit: Feras-tu périr le juste avec le méchant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Peut-être y a-t-il 50 justes dans la ville; [la] détruiras-tu, et ne pardonneras-tu pas à la ville à cause des 50 justes qui seront en elle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Loin de toi d’agir de cette manière, de faire mourir le juste avec le méchant, et qu’il en soit du juste comme du méchant! Loin de toi! Le juge de toute la terre ne fera-t-il pas ce qui est juste?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Et l’ Éternel dit: Si je trouve dans Sodome 50 justes, au-dedans de la ville, je pardonnerai à tout le lieu à cause d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Et Abraham répondit et dit: Voici, je te prie, j’ai osé parler au Seigneur, moi qui suis poussière et cendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Peut-être en manquera-t-il cinq, des 50 justes; détruiras-tu pour cinq toute la ville? Et il dit: Je ne la détruirai pas, si j’y en trouve 45.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Et il continua encore de lui parler, et dit: Peut-être s’y en trouvera-t-il 40? Et il dit: Je ne le ferai pas, à cause des 40.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Et il dit: Je te prie, que le Seigneur ne s’irrite pas, et je parlerai: Peut-être s’y en trouvera-t-il 30? Et il dit: Je ne le ferai pas, si j’y en trouve 30.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Et il dit: Voici, j’ai osé parler au Seigneur: Peut-être s’y en trouvera-t-il 20? Et il dit: Je ne la détruirai pas, à cause des 20.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Et il dit: Je te prie, que le Seigneur ne s’irrite pas, et je parlerai encore une seule fois: Peut-être s’y en trouvera-t-il 10? Et il dit: Je ne la détruirai pas, à cause des 10.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Et l’ Éternel s’en alla quand il eut achevé de parler à Abraham; et Abraham s’en retourna en son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Et les deux anges vinrent à Sodome sur le soir; et Lot était assis à la porte de Sodome. Et Lot les vit, et il se leva pour aller à leur rencontre, et se prosterna le visage en terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'et il dit: Voici, mes seigneurs, détournez-vous, je vous prie, vers la maison de votre serviteur, et passez-y la nuit, et lavez vos pieds; et vous vous lèverez le matin, et vous irez votre chemin. Et ils dirent: Non, mais nous passerons la nuit sur la place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Et il les pressa beaucoup, et ils se détournèrent [pour aller] chez lui, et entrèrent dans sa maison; et il leur fit un festin, et cuisit des pains sans levain, et ils mangèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Ils n’étaient pas encore couchés que les hommes de la ville, les hommes de Sodome, entourèrent la maison, depuis le jeune homme jusqu’au vieillard, tout le peuple de tous les bouts [de la ville].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Et ils appelèrent Lot, et lui dirent: Où sont les hommes qui sont entrés chez toi cette nuit? Fais-les sortir vers nous, afin que nous les connaissions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Et Lot sortit vers eux à l’entrée, et ferma la porte après lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'et il dit: Je vous prie, mes frères, ne faites pas [ce] mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Voici, j’ai deux filles qui n’ont point connu d’homme; laissez-moi les faire sortir vers vous, et faites-leur comme il vous plaira. Seulement, à ces hommes ne faites rien, car c’est pour cela qu’ils sont venus à l’ombre de mon toit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Et ils dirent: Retire-toi! Et ils dirent: Cet individu est venu pour séjourner [ici], et il veut faire le juge! Maintenant nous te ferons pis qu’à eux. Et ils pressaient beaucoup Lot, et s’approchèrent pour briser la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Et les hommes étendirent leurs mains et firent entrer Lot vers eux dans la maison, et fermèrent la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Et ils frappèrent de cécité les hommes qui étaient à l’entrée de la maison, depuis le plus petit jusqu’au plus grand, [de sorte] qu’ils se lassèrent à chercher l’entrée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Et les hommes dirent à Lot: Qui as-tu encore ici? Gendre, et tes fils, et tes filles, et tout ce que tu as dans la ville, fais-les sortir de ce lieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'car nous allons détruire ce lieu, car leur cri est devenu grand devant l’ Éternel; et l’ Éternel nous a envoyés pour le détruire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Et Lot sortit, et parla à ses gendres qui avaient pris ses filles, et dit: Levez-vous, sortez de ce lieu, car l’ Éternel va détruire la ville. Et il sembla aux yeux de ses gendres qu’il se moquait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Et comme l’aube du jour se levait, les anges pressèrent Lot, disant: Lève-toi, prends ta femme et tes deux filles qui se trouvent ici, de peur que tu ne périsses dans l’iniquité de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Et il tardait; et les hommes saisirent sa main, et la main de sa femme, et la main de ses deux filles, l’ Éternel ayant pitié de lui; et ils le firent sortir, et le laissèrent hors de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Et il arriva, quand ils les eurent fait sortir dehors, qu’il dit: Sauve-toi, pour ta vie! ne regarde pas derrière toi, et ne t’arrête pas dans toute la plaine; sauve-toi sur la montagne, de peur que tu ne périsses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Et Lot leur dit: Non, Seigneur, je te prie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Voici, ton serviteur a trouvé grâce à tes yeux, et la bonté dont tu as usé à mon égard en conservant mon âme en vie a été grande; et je ne puis me sauver vers la montagne, de peur que le mal ne m’atteigne, et que je ne meure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Voici, je te prie, cette ville-là est proche pour y fuir, et elle est petite; que je m’y sauve donc, (n’est-elle pas petite?) et mon âme vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Et il lui dit: Voici, j’ai accueilli ta demande en cette chose aussi, de ne pas détruire la ville dont tu as parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Hâte-toi de te sauver là; car je ne peux rien faire jusqu’à ce que tu y sois entré. C’est pourquoi on a appelé le nom de la ville Tsoar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Le soleil se levait sur la terre quand Lot entra dans Tsoar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Et l’ Éternel fit pleuvoir des cieux sur Sodome et sur Gomorrhe du soufre et du feu, de la part de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'et il détruisit ces villes, et toute la plaine, et tous les habitants des villes, et les plantes de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Et la femme de Lot regarda en arrière, et elle devint une statue de sel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Et Abraham se leva de bon matin, [et vint] au lieu où il s’était tenu devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Et il regarda du côté de Sodome et de Gomorrhe, et du côté de tout le pays de la plaine, et il vit, et voici, la fumée de la terre montait comme la fumée d’une fournaise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Et il arriva, lorsque Dieu détruisit les villes de la plaine, que Dieu se souvint d’Abraham et renvoya Lot hors de la destruction, quand il détruisit les villes dans lesquelles Lot habitait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Et Lot monta de Tsoar, et habita dans la montagne, et ses deux filles avec lui; car il eut peur d’habiter dans Tsoar; et il habita dans une caverne, lui et ses deux filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Et l’aînée dit à la plus jeune: Notre père est vieux, et il n’y a pas d’homme sur la terre pour venir vers nous selon la manière de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Viens, faisons boire du vin à notre père, et couchons avec lui, afin que nous conservions une semence de notre père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Et elles firent boire du vin à leur père cette nuit-là; et l’aînée vint et coucha avec son père; et il ne s’aperçut ni quand elle se coucha, ni quand elle se leva.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Et il arriva, le lendemain, que l’aînée dit à la plus jeune: Voici, j’ai couché la nuit passée avec mon père; faisons-lui boire du vin encore cette nuit; et va, couche avec lui, et nous conserverons une semence de notre père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Et elles firent boire du vin à leur père cette nuit-là aussi; et la plus jeune se leva, et coucha avec lui; et il ne s’aperçut ni quand elle se coucha, ni quand elle se leva.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Et les deux filles de Lot conçurent de leur père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Et l’aînée enfanta un fils, et appela son nom Moab: lui, est le père de Moab, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Et la plus jeune, elle aussi, enfanta un fils, et appela son nom Ben-Ammi: lui, est le père des fils d’Ammon, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, '*Et Abraham s’en alla de là au pays du midi, et habita entre Kadès et Shur, et séjourna à Guérar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Et Abraham dit de Sara, sa femme: Elle est ma sœur. Et Abimélec, roi de Guérar, envoya et prit Sara.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Et Dieu vint vers Abimélec la nuit, dans un songe, et lui dit: Voici, tu es mort à cause de la femme que tu as prise, car elle est une femme mariée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Or Abimélec ne s’était pas approché d’elle; et il dit: Seigneur, feras-tu périr même une nation juste?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Ne m’a-t-il pas dit: Elle est ma sœur? Et elle-même m’a dit: Il est mon frère. J’ai fait cela dans l’intégrité de mon cœur et dans l’innocence de mes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Et Dieu lui dit en songe: Moi aussi je sais que tu as fait cela dans l’intégrité de ton cœur, et aussi je t’ai retenu de pécher contre moi; c’est pourquoi je n’ai pas permis que tu la touches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Et maintenant, rends la femme de cet homme; car il est prophète, et il priera pour toi, et tu vivras. Mais si tu ne la rends pas, sache que tu mourras certainement, toi et tout ce qui est à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Et Abimélec se leva de bon matin, et appela tous ses serviteurs, et dit toutes ces paroles à leurs oreilles; et ces hommes eurent une grande peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Et Abimélec appela Abraham, et lui dit: Que nous as-tu fait? et en quoi ai-je péché contre toi, que tu aies fait venir sur moi et sur mon royaume un grand péché? Tu as fait à mon égard des choses qui ne doivent pas se faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Et Abimélec dit à Abraham: Qu’as-tu vu pour avoir fait ainsi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Et Abraham dit: C’est parce que je disais: Assurément il n’y a point de crainte de Dieu en ce lieu, et ils me tueront à cause de ma femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Et aussi, à la vérité, elle est ma sœur, fille de mon père; seulement elle n’est pas fille de ma mère, et elle est devenue ma femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Et il est arrivé, lorsque Dieu m’a fait errer loin de la maison de mon père, que je lui ai dit: Voici la grâce que tu me feras: Dans tous les lieux où nous arriverons, dis de moi: Il est mon frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Et Abimélec prit du menu bétail et du gros bétail, et des serviteurs et des servantes, et il les donna à Abraham, et lui rendit Sara, sa femme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'et Abimélec dit: Voici, mon pays est devant toi; habite où il te plaira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Et à Sara il dit: Voici, j’ai donné 1 000 [pièces] d’argent à ton frère; voici, cela te sera une couverture des yeux pour tous ceux qui sont avec toi, et pour tous. Ainsi elle fut reprise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Et Abraham pria Dieu, et Dieu guérit Abimélec, et sa femme et ses servantes, et elles eurent des enfants:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'car l’ Éternel avait entièrement fermé toute matrice de la maison d’Abimélec, à cause de Sara, femme d’Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Et l’ Éternel visita Sara comme il avait dit, et l’ Éternel fit à Sara comme il en avait parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Et Sara conçut, et enfanta à Abraham un fils dans sa vieillesse, au temps fixé dont Dieu lui avait parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Et Abraham appela le nom de son fils qui lui était né, que Sara lui avait enfanté, Isaac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Et Abraham circoncit Isaac, son fils, à l’âge de huit jours, comme Dieu le lui avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Et Abraham était âgé de 100 ans lorsque Isaac, son fils, lui naquit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Et Sara dit: Dieu m’a donné lieu de rire; quiconque l’entendra rira avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Et elle dit: Qui aurait dit à Abraham: Sara allaitera des fils? Car je lui ai enfanté un fils dans sa vieillesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Et l’enfant grandit, et fut sevré; et Abraham fit un grand festin le jour où Isaac fut sevré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Et Sara vit rire le fils d’Agar, l’Égyptienne, qu’elle avait enfanté à Abraham;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'et elle dit à Abraham: Chasse cette servante et son fils; car le fils de cette servante n’héritera pas avec mon fils, avec Isaac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Et cela fut très mauvais aux yeux d’Abraham, à cause de son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Et Dieu dit à Abraham: Que cela ne soit pas mauvais à tes yeux à cause de l’enfant, et à cause de ta servante. Dans tout ce que Sara t’a dit, écoute sa voix; car en Isaac te sera appelée [une] semence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Et je ferai aussi devenir une nation le fils de la servante, car il est ta semence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Et Abraham se leva de bon matin, et il prit du pain et une outre d’eau, et les donna à Agar, les mettant sur son épaule, et [il lui donna] l’enfant, et la renvoya. Et elle s’en alla, et erra dans le désert de Beër-Shéba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Et l’eau de l’outre étant épuisée, elle jeta l’enfant sous un des arbrisseaux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'et s’en alla et s’assit vis-à-vis, à une portée d’arc; car elle disait: Que je ne voie pas mourir l’enfant. Et elle s’assit vis-à-vis, et elle éleva sa voix et pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Et Dieu entendit la voix de l’enfant, et l’Ange de Dieu appela des cieux Agar, et lui dit: Qu’as-tu, Agar? Ne crains point, car Dieu a entendu la voix de l’enfant, là où il est.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Lève-toi, relève l’enfant et prends-le de ta main; car je le ferai devenir une grande nation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Et Dieu lui ouvrit les yeux, et elle vit un puits d’eau; et elle alla et remplit d’eau l’outre, et fit boire l’enfant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Et Dieu fut avec l’enfant, et il grandit, et habita dans le désert et devint tireur d’arc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Et il habita dans le désert de Paran; et sa mère lui prit une femme du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Et il arriva, dans ce temps-là, qu’Abimélec, et Picol, chef de son armée, parlèrent à Abraham, disant: Dieu est avec toi en tout ce que tu fais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Et maintenant, jure-moi ici, par Dieu, que tu n’agiras faussement ni envers moi, ni envers mes enfants, ni envers mes petits-enfants: selon la bonté dont j’ai usé envers toi, tu agiras envers moi et envers le pays dans lequel tu as séjourné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Et Abraham dit: Je le jurerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Et Abraham reprit Abimélec à cause d’un puits d’eau dont les serviteurs d’Abimélec s’étaient emparés de force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Et Abimélec dit: Je ne sais pas qui a fait cette chose-là, et aussi tu ne m’en as pas averti, et moi, je n’en ai entendu parler qu’aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Et Abraham prit du menu et du gros bétail, et le donna à Abimélec, et ils firent alliance, eux deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Et Abraham mit à part sept jeunes brebis du troupeau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'et Abimélec dit à Abraham: Qu’est-ce que ces sept jeunes brebis que tu as mises à part?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Et il répondit: C’est que tu prendras de ma main ces sept jeunes brebis, pour me servir de témoignage que j’ai creusé ce puits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'C’est pourquoi on appela ce lieu-là Beër-Shéba, parce qu’ils y jurèrent, les deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Et ils firent alliance à Beër-Shéba. Et Abimélec se leva, et Picol, chef de son armée, et ils retournèrent au pays des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Et [Abraham] planta un tamaris à Beër-Shéba; et là il invoqua le nom de l’ Éternel, le ✶Dieu d’éternité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Et Abraham séjourna longtemps dans le pays des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, '*Et il arriva, après ces choses, que Dieu éprouva Abraham, et lui dit: Abraham! Et il dit: Me voici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Et [Dieu] dit: Prends ton fils, ton unique, celui que tu aimes, Isaac, et va-t’en au pays de Morija, et là offre-le en holocauste, sur une des montagnes que je te dirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Et Abraham se leva de bon matin et bâta son âne et prit avec lui deux de ses jeunes hommes, et Isaac, son fils; et il fendit le bois pour l’holocauste, et se leva, et s’en alla vers le lieu que Dieu lui avait dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Le troisième jour, Abraham leva ses yeux, et vit le lieu de loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Et Abraham dit à ses jeunes hommes: Restez ici, vous, avec l’âne; et moi et l’enfant nous irons jusque-là, et nous adorerons; et nous reviendrons vers vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Et Abraham prit le bois de l’holocauste, et le mit sur Isaac, son fils; et il prit dans sa main le feu et le couteau; et ils allaient les deux ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Et Isaac parla à Abraham, son père, et dit: Mon père! Et il dit: Me voici, mon fils. Et il dit: Voici le feu et le bois; mais où est l’agneau pour l’holocauste?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Et Abraham dit: Mon fils, Dieu se pourvoira de l’agneau pour l’holocauste. Et ils allaient les deux ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Et ils arrivèrent au lieu que Dieu lui avait dit. Et Abraham bâtit là l’autel, et arrangea le bois, et lia Isaac, son fils, et le mit sur l’autel, sur le bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Et Abraham étendit sa main et prit le couteau pour égorger son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Mais l’Ange de l’ Éternel lui cria des cieux, et dit: Abraham! Abraham! Et il dit: Me voici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Et il dit: N’étends pas ta main sur l’enfant, et ne lui fais rien; car maintenant je sais que tu crains Dieu, et que tu ne m’as pas refusé ton fils, ton unique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Et Abraham leva ses yeux, et vit, et voici, il y avait derrière [lui] un bélier retenu à un buisson par les cornes; et Abraham alla et prit le bélier, et l’offrit en holocauste à la place de son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Et Abraham appela le nom de ce lieu-là: Jéhovah-Jiré, comme on dit aujourd’hui: En la montagne de l’ Éternel il y sera pourvu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Et l’Ange de l’ Éternel cria des cieux à Abraham, une seconde fois,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'et dit: J’ai juré par moi-même, dit l’ Éternel: Parce que tu as fait cette chose-là, et que tu n’as pas refusé ton fils, ton unique,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'certainement je te bénirai, et je multiplierai abondamment ta semence comme les étoiles des cieux et comme le sable qui est sur le bord de la mer; et ta semence possédera la porte de ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Et toutes les nations de la terre se béniront en ta semence, parce que tu as écouté ma voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Et Abraham retourna vers ses jeunes hommes; et ils se levèrent, et s’en allèrent ensemble à Beër-Shéba; et Abraham habita à Beër-Shéba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, '*Et il arriva, après ces choses, qu’on rapporta à Abraham en disant: Voici, Milca, elle aussi, a enfanté des enfants à Nakhor, ton frère:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Uts, son premier-né; et Buz, son frère; et Kemuel, père d’Aram;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'et Késed, et Hazo, et Pildash, et Jidlaph, et Bethuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Or Bethuel engendra Rebecca. Milca enfanta ces huit à Nakhor, frère d’Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Et sa concubine, nommée Reüma, elle aussi enfanta Tébakh, et Gakham, et Thakhash, et Maaca.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, '*Et la vie de Sara fut de 127 ans: [ce sont là] les années de la vie de Sara.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Et Sara mourut à Kiriath-Arba, qui est Hébron, dans le pays de Canaan; et Abraham vint pour mener deuil sur Sara, et pour la pleurer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Et Abraham se leva de devant son mort; et il parla aux fils de Heth, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Je suis étranger, habitant parmi vous; donnez-moi la possession d’un sépulcre parmi vous, et j’enterrerai mon mort de devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Et les fils de Heth répondirent à Abraham, lui disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Écoute-nous, mon seigneur: Tu es un prince de Dieu au milieu de nous; enterre ton mort dans le meilleur de nos sépulcres; aucun de nous ne te refusera son sépulcre pour y enterrer ton mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Et Abraham se leva, et se prosterna devant le peuple du pays, devant les fils de Heth;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'et il leur parla, disant: Si c’est votre volonté que j’enterre mon mort de devant moi, écoutez-moi, et intercédez pour moi auprès d’Éphron, fils de Tsokhar,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'afin qu’il me donne la caverne de Macpéla, qui est à lui, qui est au bout de son champ; qu’il me la donne au milieu de vous pour sa pleine valeur, afin que je la possède comme sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Or Éphron habitait parmi les fils de Heth. Et Éphron, le Héthien, répondit à Abraham, aux oreilles des fils de Heth, devant tous ceux qui entraient par la porte de sa ville, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Non, mon seigneur, écoute-moi: Je te donne le champ; et la caverne qui s’y trouve, je te la donne; je te la donne aux yeux des fils de mon peuple: enterre ton mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Et Abraham se prosterna devant le peuple du pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'et il parla à Éphron, aux oreilles du peuple du pays, disant: Si pourtant tu voulais bien m’écouter. Je donne l’argent du champ, prends-le de moi, et j’y enterrerai mon mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Et Éphron répondit à Abraham, lui disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mon seigneur, écoute-moi: Une terre de 400 sicles d’argent, qu’est-ce que cela entre moi et toi? Enterre donc ton mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Et Abraham écouta Éphron, et Abraham pesa à Éphron l’argent dont il avait parlé en présence des fils de Heth, 400 sicles d’argent ayant cours entre les marchands.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Et le champ d’Éphron, qui était à Macpéla, devant Mamré, le champ et la caverne qui y était, et tous les arbres qui étaient dans le champ, dans toutes ses limites tout à l’entour,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'furent assurés en propriété à Abraham, aux yeux des fils de Heth, devant tous ceux qui entraient par la porte de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Et, après cela, Abraham enterra Sara, sa femme, dans la caverne du champ de Macpéla, en face de Mamré, qui est Hébron, dans le pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Et le champ et la caverne qui s’y trouve furent assurés à Abraham pour les posséder comme sépulcre, de la part des fils de Heth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, '*Et Abraham était vieux, avancé en âge; et l’ Éternel avait béni Abraham en toute chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Et Abraham dit à son serviteur, le plus ancien de sa maison, qui avait le gouvernement de tout ce qui était à lui: Mets, je te prie, ta main sous ma cuisse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'et je te ferai jurer par l’ Éternel, le Dieu des cieux et le Dieu de la terre, que tu ne prendras pas de femme pour mon fils d’entre les filles des Cananéens, parmi lesquels j’habite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'mais tu iras dans mon pays et vers ma parenté, et tu prendras une femme pour mon fils, pour Isaac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Et le serviteur lui dit: Peut-être la femme ne voudra-t-elle pas me suivre dans ce pays-ci; me faudra-t-il faire retourner ton fils dans le pays d’où tu es sorti?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Et Abraham lui dit: Garde-toi d’y faire retourner mon fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'L’ Éternel, le Dieu des cieux, qui m’a pris de la maison de mon père et du pays de ma parenté, et qui m’a parlé et qui m’a juré, disant: Je donnerai à ta semence ce pays-ci, lui-même enverra son ange devant toi, et tu prendras de là une femme pour mon fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Et si la femme ne veut pas te suivre, alors tu seras quitte envers moi de ce serment; seulement, tu ne feras pas retourner là mon fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Et le serviteur mit sa main sous la cuisse d’Abraham, son seigneur, et lui jura au sujet de ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Et le serviteur prit dix chameaux d’entre les chameaux de son maître, et s’en alla; or il avait tout le bien de son maître sous sa main. Et il se leva et s’en alla en Mésopotamie, à la ville de Nakhor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Et il fit agenouiller les chameaux en dehors de la ville, auprès d’un puits d’eau, au temps du soir, au temps où sortent celles qui vont puiser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Et il dit: Éternel, Dieu de mon seigneur Abraham, fais-moi faire, je te prie, une [heureuse] rencontre aujourd’hui, et use de grâce envers mon seigneur Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Voici, je me tiens près de la fontaine d’eau, et les filles des gens de la ville sortent pour puiser de l’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'qu’il arrive donc que la jeune fille à laquelle je dirai: Abaisse ta cruche, je te prie, afin que je boive, et qui dira: Bois, et j’abreuverai aussi tes chameaux, soit celle que tu as destinée à ton serviteur, à Isaac; et à cela je connaîtrai que tu as usé de grâce envers mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Et il arriva, avant qu’il ait achevé de parler, que voici sortir Rebecca, sa cruche sur son épaule: elle était née à Bethuel, fils de Milca, femme de Nakhor, frère d’Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Et la jeune fille était très belle de visage, vierge, et nul ne l’avait connue. Et elle descendit à la fontaine, et remplit sa cruche, et remonta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Et le serviteur courut à sa rencontre et dit: Permets, je te prie, que je boive un peu d’eau de ta cruche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Et elle dit: Bois, mon seigneur. Et vite elle abaissa sa cruche sur sa main, et lui donna à boire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Et, après qu’elle eut achevé de lui donner à boire, elle dit: Je puiserai aussi pour tes chameaux, jusqu’à ce qu’ils aient fini de boire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Et elle se hâta et vida sa cruche dans l’auge, et elle courut encore au puits pour puiser, et puisa pour tous ses chameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Et l’homme la regardait avec étonnement sans rien dire, pour savoir si l’ Éternel aurait fait prospérer son voyage, ou non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Et il arriva, quand les chameaux eurent fini de boire, que l’homme prit un anneau d’or, du poids d’un demi-sicle, et deux bracelets pour ses mains, du poids de dix [sicles] d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Et il dit: De qui es-tu fille? Fais-le-moi savoir, je te prie. Y a-t-il pour nous, dans la maison de ton père, un lieu pour y loger?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Et elle lui dit: Je suis fille de Bethuel, fils de Milca, qu’elle a enfanté à Nakhor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Et elle lui dit: Il y a chez nous de la paille, et aussi du fourrage en abondance, et de la place pour loger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Et l’homme s’inclina, et se prosterna devant l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'et dit: Béni soit l’ Éternel, le Dieu de mon seigneur Abraham, qui ne s’est pas départi de sa grâce et de sa vérité envers mon seigneur. Lorsque j’étais en chemin, l’ Éternel m’a conduit à la maison des frères de mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Et la jeune fille courut, et rapporta ces choses dans la maison de sa mère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'or Rebecca avait un frère, nommé Laban; et Laban courut vers l’homme, dehors, à la fontaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Et il arriva que, lorsqu’il vit l’anneau et les bracelets aux mains de sa sœur, et qu’il entendit les paroles de Rebecca, sa sœur, disant: Ainsi m’a parlé l’homme, il vint vers l’homme. Et voici, il se tenait auprès des chameaux, près de la fontaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Et il dit: Entre, béni de l’ Éternel; pourquoi te tiens-tu dehors? car j’ai préparé la maison, et de la place pour les chameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Et l’homme entra dans la maison, et on débarrassa les chameaux; et on donna de la paille et du fourrage aux chameaux, et [pour lui] de l’eau pour laver ses pieds et les pieds des gens qui étaient avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Et on mit devant lui de quoi manger; mais il dit: Je ne mangerai pas avant d’avoir dit ce que j’ai à dire. Et [Laban] dit: Parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Et il dit: Je suis serviteur d’Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Or l’ Éternel a béni abondamment mon seigneur, et il est devenu grand; et il lui a donné du menu bétail, et du gros bétail, et de l’argent, et de l’or, et des serviteurs, et des servantes, et des chameaux, et des ânes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Et Sara, femme de mon seigneur, a dans sa vieillesse enfanté un fils à mon seigneur; et il lui a donné tout ce qu’il a.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Et mon seigneur m’a fait jurer, disant: Tu ne prendras pas de femme pour mon fils d’entre les filles des Cananéens, dans le pays desquels j’habite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'mais tu iras à la maison de mon père et vers ma famille, et tu prendras une femme pour mon fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Et je dis à mon seigneur: Peut-être la femme ne viendra-t-elle pas après moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Et il me dit: L’ Éternel, devant qui je marche, enverra son ange avec toi et fera prospérer ton voyage, et tu prendras pour mon fils une femme de ma famille et de la maison de mon père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Quand tu seras arrivé auprès de ma famille, alors tu seras quitte du serment que je te fais faire; et, si on ne te la donne pas, tu seras quitte du serment que je te fais faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Et je suis venu aujourd’hui à la fontaine, et j’ai dit: Éternel, Dieu de mon seigneur Abraham, si tu veux bien faire prospérer le voyage que je fais,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'voici, je me tiens près de la fontaine d’eau: qu’il arrive que la jeune fille qui sortira pour puiser, et à laquelle je dirai: Donne-moi, je te prie, à boire un peu d’eau de ta cruche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'et qui me dira: Bois toi-même, et je puiserai aussi pour tes chameaux, que celle-là soit la femme que l’ Éternel a destinée au fils de mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Avant que j’aie achevé de parler en mon cœur, voici sortir Rebecca, sa cruche sur son épaule; et elle est descendue à la fontaine, et a puisé; et je lui ai dit: Donne-moi à boire, je te prie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Et elle s’est hâtée et a abaissé sa cruche de dessus son épaule, et a dit: Bois, et j’abreuverai aussi tes chameaux. Et j’ai bu, et elle a aussi abreuvé les chameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Et je l’ai interrogée, et j’ai dit: De qui es-tu fille? Et elle a dit: Je suis fille de Bethuel, fils de Nakhor, que Milca lui a enfanté. Et j’ai mis l’anneau à son nez, et les bracelets à ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Et je me suis incliné et je me suis prosterné devant l’ Éternel, et j’ai béni l’ Éternel, le Dieu de mon seigneur Abraham, qui m’a conduit par le vrai chemin, pour prendre la fille du frère de mon seigneur pour son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Et maintenant, si vous voulez user de grâce et de vérité envers mon seigneur, déclarez-le-moi; et sinon, déclarez-le-moi, et je me tournerai à droite ou à gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Et Laban et Bethuel répondirent et dirent: La chose procède de l’ Éternel; nous ne pouvons te dire ni mal, ni bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Voici Rebecca devant toi; prends-la, et t’en va; et qu’elle soit la femme du fils de ton seigneur, comme l’ Éternel l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Et il arriva, lorsque le serviteur d’Abraham entendit leurs paroles, qu’il se prosterna en terre devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'et le serviteur sortit des objets d’argent et des objets d’or, et des vêtements, et les donna à Rebecca; il fit aussi de riches présents à son frère et à sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Et ils mangèrent et burent, lui et les hommes qui étaient avec lui, et ils logèrent là; et ils se levèrent le matin, et il dit: Renvoyez-moi à mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Et le frère et la mère dirent: Que la jeune fille reste avec nous [quelques] jours, dix au moins; ensuite elle s’en ira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Et il leur dit: Ne me retardez point, quand l’ Éternel a fait prospérer mon voyage; renvoyez-moi, et que je m’en aille vers mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Et ils dirent: Appelons la jeune fille, et entendons-la.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Et ils appelèrent Rebecca, et lui dirent: Iras-tu avec cet homme? Et elle dit: J’irai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Et ils firent partir Rebecca, leur sœur, et sa nourrice, et le serviteur d’Abraham et ses gens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Et ils bénirent Rebecca, et lui dirent: Toi, notre sœur, deviens des milliers de myriades, et que ta semence possède la porte de ses ennemis!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Et Rebecca se leva, et ses filles; et elles montèrent sur les chameaux, et s’en allèrent après l’homme. Et le serviteur prit Rebecca, et s’en alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Et Isaac venait d’arriver du puits de Lakhaï-roï; or il habitait au pays du midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Et Isaac était sorti dans les champs pour méditer, à l’approche du soir. Et il leva ses yeux, et regarda, et voici des chameaux qui venaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Et Rebecca leva ses yeux, et vit Isaac; et elle descendit de dessus le chameau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Or elle avait dit au serviteur: Qui est cet homme qui marche dans les champs à notre rencontre? Et le serviteur dit: C’est mon seigneur. Et elle prit son voile et se couvrit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Et le serviteur raconta à Isaac toutes les choses qu’il avait faites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Et Isaac la conduisit dans la tente de Sara, sa mère; et il prit Rebecca, et elle fut sa femme, et il l’aima; et Isaac se consola quant à sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, '*Et Abraham prit encore une femme, nommée Ketura;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'et elle lui enfanta Zimran, et Jokshan, et Medan, et Madian, et Jishbak, et Shuakh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, '– Et Jokshan engendra Sheba et Dedan. Et les fils de Dedan furent Ashurim, et Letushim, et Leümmim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, '– Et les fils de Madian: Épha, et Épher, et Hénoc, et Abida, et Eldaa. – Tous ceux-là furent fils de Ketura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Et Abraham donna tout ce qui lui appartenait à Isaac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Et aux fils des concubines qu’eut Abraham, Abraham fit des dons; et, tandis qu’il était encore en vie, il les renvoya d’auprès d’Isaac, son fils, vers l’orient, au pays d’orient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Et ce sont ici les jours des années de la vie d’Abraham, qu’il vécut: 175 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Et Abraham expira et mourut dans une bonne vieillesse, âgé et rassasié [de jours]; et il fut recueilli vers ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Et Isaac et Ismaël, ses fils, l’enterrèrent dans la caverne de Macpéla, dans le champ d’Éphron, fils de Tsokhar, le Héthien, qui est en face de Mamré,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'le champ qu’Abraham avait acheté des fils de Heth. Là fut enterré Abraham, ainsi que Sara, sa femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Et il arriva, après la mort d’Abraham, que Dieu bénit Isaac, son fils. Et Isaac habitait près du puits de Lakhaï-roï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, '*Et ce sont ici les générations d’Ismaël, fils d’Abraham, qu’Agar, l’Égyptienne, servante de Sara, avait enfanté à Abraham;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'et voici les noms des fils d’Ismaël, par leurs noms, selon leurs générations: Le premier-né d’Ismaël, Nebaïoth; et Kédar, et Adbeël, et Mibsam,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'et Mishma, et Duma, et Massa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, et Théma, Jetur, Naphish et Kedma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Ce sont là les fils d’Ismaël, et ce sont là leurs noms, selon leurs villages et leurs campements: douze princes de leurs tribus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Et ce sont ici les années de la vie d’Ismaël: 137 ans; et il expira et mourut, et fut recueilli vers ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Et ils habitèrent depuis Havila jusqu’à Shur, qui est en face de l’Égypte, quand tu viens vers l’Assyrie. Il s’établit à la vue de tous ses frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, '*Et ce sont ici les générations d’Isaac, fils d’Abraham: Abraham engendra Isaac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Et Isaac était âgé de 40 ans lorsqu’il prit pour femme Rebecca, fille de Bethuel l’Araméen de Paddan-Aram, sœur de Laban l’Araméen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Et Isaac pria instamment l’ Éternel au sujet de sa femme, car elle était stérile; et l’ Éternel se rendit à ses prières, et Rebecca sa femme conçut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Et les enfants s’entre-poussaient dans son sein; et elle dit: S’il en est ainsi, pourquoi suis-je là? Et elle alla consulter l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Et l’ Éternel lui dit: Deux nations sont dans ton ventre, et deux peuples se sépareront en sortant de tes entrailles; et un peuple sera plus fort que l’autre peuple, et le plus grand sera asservi au plus petit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Et les jours où elle devait enfanter s’accomplirent, et voici, il y avait des jumeaux dans son ventre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Et le premier sortit, roux, tout entier comme un manteau de poil; et ils appelèrent son nom Ésaü.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Et ensuite sortit son frère, et sa main tenait le talon d’Ésaü; et on appela son nom Jacob. Et Isaac était âgé de 60 ans quand ils naquirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Et les enfants grandirent: et Ésaü était un homme habile à la chasse, un homme des champs; et Jacob était un homme simple, qui habitait les tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Et Isaac aimait Ésaü, car le gibier était sa viande; mais Rebecca aimait Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Et Jacob cuisait un potage; et Ésaü arriva des champs, et il était las.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Et Ésaü dit à Jacob: Laisse-moi, je te prie, avaler du roux, de ce roux-là; car je suis las. C’est pourquoi on appela son nom Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Et Jacob dit: Vends-moi aujourd’hui ton droit d’aînesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Et Ésaü dit: Voici, je m’en vais mourir; et de quoi me sert le droit d’aînesse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Et Jacob dit: Jure-moi aujourd’hui. Et il lui jura, et vendit son droit d’aînesse à Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Et Jacob donna à Ésaü du pain et du potage de lentilles; et il mangea et but, et se leva, et s’en alla: et Ésaü méprisa son droit d’aînesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, '*Et il y eut une famine dans le pays, outre la première famine qui avait eu lieu aux jours d’Abraham; et Isaac s’en alla vers Abimélec, roi des Philistins, à Guérar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Et l’ Éternel lui apparut, et dit: Ne descends pas en Égypte; demeure dans le pays que je t’ai dit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'séjourne dans ce pays-ci, et je serai avec toi, et je te bénirai; car à toi et à ta semence je donnerai tous ces pays, et j’accomplirai le serment que j’ai juré à Abraham, ton père,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'et je multiplierai ta semence comme les étoiles des cieux, et je donnerai tous ces pays à ta semence, et toutes les nations de la terre se béniront en ta semence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, '– parce qu’Abraham a écouté ma voix, et a gardé mon ordonnance, mes commandements, mes statuts et mes lois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Et Isaac habita à Guérar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Et les hommes du lieu s’enquirent au sujet de sa femme, et il dit: C’est ma sœur, car il craignait de dire: ma femme; de peur, [pensait-il], que les hommes du lieu ne me tuent à cause de Rebecca, car elle est belle de visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Et il arriva, comme son séjour dans ce [lieu] se prolongeait, qu’Abimélec, roi des Philistins, regarda par la fenêtre; et il vit, et voici, Isaac se jouait avec Rebecca sa femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Et Abimélec appela Isaac, et dit: Voici, assurément c’est ta femme; et comment as-tu dit: C’est ma sœur? Et Isaac lui dit: Parce que je disais: De peur que je ne meure à cause d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Et Abimélec dit: Qu’est-ce que tu nous as fait? Car peu s’en est fallu que quelqu’un du peuple n’ait couché avec ta femme, et tu aurais fait venir la culpabilité sur nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Et Abimélec commanda à tout le peuple, disant: Celui qui touchera cet homme ou sa femme sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Et Isaac sema dans cette terre; et il recueillit cette année-là le centuple; et l’ Éternel le bénit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Et l’homme grandissait, et il allait grandissant de plus en plus, jusqu’à ce qu’il devint fort grand;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'et il eut des troupeaux de menu bétail, et des troupeaux de gros bétail, et beaucoup de serviteurs; et les Philistins lui portèrent envie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'et tous les puits que les serviteurs de son père avaient creusés aux jours d’Abraham, son père, les Philistins les bouchèrent et les remplirent de terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Et Abimélec dit à Isaac: Va-t’en d’avec nous; car tu es beaucoup plus puissant que nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Et Isaac partit de là, et campa dans la vallée de Guérar, et y habita.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Et Isaac recreusa les puits d’eau qu’on avait creusés aux jours d’Abraham, son père, et que les Philistins avaient bouchés après la mort d’Abraham; et il leur donna des noms selon les noms que son père leur avait donnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Et les serviteurs d’Isaac creusèrent dans la vallée, et ils y trouvèrent un puits d’eau vive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Et les bergers de Guérar contestèrent avec les bergers d’Isaac, disant: L’eau est à nous. Et il appela le nom du puits Ések, parce qu’ils s’étaient disputés avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Et ils creusèrent un autre puits, et ils contestèrent aussi pour celui-là; et il appela son nom Sitna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Et il se transporta de là, et creusa un autre puits, et ils ne contestèrent pas pour celui-là; et il appela son nom Rehoboth, parce que, dit-il, l’ Éternel nous a maintenant donné de l’espace, et nous fructifierons dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Et de là il monta à Beër-Shéba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Et l’ Éternel lui apparut cette nuit-là, et dit: Je suis le Dieu d’Abraham ton père; ne crains pas, car je suis avec toi; et je te bénirai, et je multiplierai ta semence, à cause d’Abraham, mon serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Et il bâtit là un autel, et invoqua le nom de l’ Éternel; et il y dressa sa tente; et les serviteurs d’Isaac y creusèrent un puits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Et Abimélec alla de Guérar vers lui, avec Akhuzzath, son ami, et Picol, chef de son armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Et Isaac leur dit: Pourquoi venez-vous vers moi, puisque vous me haïssez et que vous m’avez renvoyé d’auprès de vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Et ils dirent: Nous avons vu clairement que l’ Éternel est avec toi, et nous avons dit: Qu’il y ait donc un serment entre nous, entre nous et toi; et nous ferons une alliance avec toi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'que tu ne nous feras pas de mal, comme nous ne t’avons pas touché, et comme nous ne t’avons fait que du bien, et t’avons renvoyé en paix. Tu es maintenant le béni de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Et il leur fit un festin, et ils mangèrent et burent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Et ils se levèrent de bon matin, et se jurèrent l’un à l’autre; et Isaac les renvoya, et ils s’en allèrent d’avec lui en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Et il arriva, en ce jour-là, que les serviteurs d’Isaac vinrent, et l’avertirent au sujet du puits qu’ils avaient creusé, et lui dirent: Nous avons trouvé de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Et il l’appela Shéba; c’est pourquoi le nom de la ville a été Beër-Shéba, jusqu’à aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Et Ésaü était âgé de 40 ans, et il prit pour femmes Judith, fille de Beéri, le Héthien, et Basmath, fille d’Élon, le Héthien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'et elles furent une amertume d’esprit pour Isaac et pour Rebecca.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, '*Et il arriva, lorsque Isaac fut vieux et que ses yeux furent affaiblis de manière à ne plus voir, qu’il appela Ésaü, son fils aîné, et lui dit: Mon fils! Et il lui dit: Me voici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Et il dit: Tu vois que je suis vieux; je ne sais pas le jour de ma mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Et maintenant, je te prie, prends tes armes, ton carquois et ton arc, et sors dans les champs, et prends-moi du gibier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'et apprête-moi un mets savoureux comme j’aime, et apporte-le-moi, et j’en mangerai, afin que mon âme te bénisse avant que je meure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Et Rebecca entendait Isaac pendant qu’il parlait à Ésaü, son fils. Et Ésaü s’en alla aux champs pour prendre du gibier, pour l’apporter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Et Rebecca parla à Jacob, son fils, disant: Voici, j’ai entendu ton père qui parlait à Ésaü, ton frère, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Apporte-moi du gibier, et apprête-moi un mets savoureux, afin que j’en mange, et que je te bénisse devant l’ Éternel avant ma mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Et maintenant, mon fils, écoute ma voix dans ce que je te commanderai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Va, je te prie, au troupeau, et prends-moi là deux bons chevreaux; et j’en apprêterai un mets savoureux pour ton père, comme il aime;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'et tu le porteras à ton père, et il mangera, afin qu’il te bénisse avant sa mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Et Jacob dit à Rebecca, sa mère: Voici, Ésaü, mon frère, est un homme velu, et moi je suis un homme sans poil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Peut-être que mon père me tâtera, et je passerai à ses yeux pour un trompeur, et je ferai venir sur moi la malédiction, et non pas la bénédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Et sa mère lui dit: Que ta malédiction soit sur moi, mon fils! Seulement, écoute ma voix, et va, prends-les-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Et il alla et les prit, et les apporta à sa mère; et sa mère apprêta un mets savoureux comme son père aimait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Et Rebecca prit les vêtements d’Ésaü, son fils aîné, les habits précieux qu’elle avait avec elle dans la maison, et elle en revêtit Jacob, son plus jeune fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'et avec les peaux des chevreaux elle recouvrit ses mains, et le nu de son cou.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Et elle mit dans la main de Jacob, son fils, le mets savoureux et le pain qu’elle avait préparés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Et il vint vers son père, et dit: Mon père! Et il dit: Me voici; qui es-tu, mon fils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Et Jacob dit à son père: Je suis Ésaü, ton premier-né; j’ai fait comme tu m’as dit: Lève-toi, je te prie, assieds-toi, et mange de mon gibier, afin que ton âme me bénisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Et Isaac dit à son fils: Comment en as-tu trouvé si tôt, mon fils? Et il dit: Parce que l’ Éternel, ton Dieu, me l’a fait rencontrer devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Et Isaac dit à Jacob: Approche, je te prie, et je te tâterai, mon fils, [pour savoir] si tu es véritablement mon fils Ésaü, ou non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Et Jacob s’approcha d’Isaac, son père; et il le tâta, et dit: La voix est la voix de Jacob; mais les mains sont les mains d’Ésaü.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Et il ne le reconnut pas, parce que ses mains étaient velues comme les mains d’Ésaü, son frère; et il le bénit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'et il dit: Es-tu vraiment mon fils Ésaü? Et il dit: Je le suis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Et il dit: Sers-moi, et que je mange du gibier de mon fils, afin que mon âme te bénisse. Et il le servit, et il mangea; et il lui apporta du vin, et il but.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Et Isaac, son père, lui dit: Approche-toi, je te prie, et embrasse-moi, mon fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Et il s’approcha, et l’embrassa. Et il sentit l’odeur de ses vêtements, et il le bénit, et dit: Regarde, – l’odeur de mon fils est comme l’odeur d’un champ que l’ Éternel a béni.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Que Dieu te donne de la rosée des cieux et de la graisse de la terre, et une abondance de froment et de moût!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Que des peuples te servent, et que des peuplades se prosternent devant toi! Sois le maître de tes frères, et que les fils de ta mère se prosternent devant toi! Maudit soit qui te maudit, et béni, qui te bénit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Et comme Isaac avait achevé de bénir Jacob, et que Jacob était à peine sorti de devant Isaac, son père, il arriva qu’Ésaü, son frère, revint de sa chasse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Et lui aussi apprêta un mets savoureux, et l’apporta à son père; et il dit à son père: Que mon père se lève, et qu’il mange du gibier de son fils, afin que ton âme me bénisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Et Isaac, son père, lui dit: Qui es-tu? Et il dit: Je suis ton fils, ton premier-né, Ésaü.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Alors Isaac fut saisi d’un tremblement très grand, et il dit: Qui donc est celui qui a pris du gibier, et m’en a apporté? Et j’ai mangé de tout avant que tu viennes, et je l’ai béni: aussi il sera béni.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Lorsque Ésaü entendit les paroles de son père, il jeta un cri très grand et amer; et il dit à son père: Bénis-moi, moi aussi, mon père!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Et il dit: Ton frère est venu avec ruse et a pris ta bénédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Et il dit: N’est-ce pas qu’on a appelé son nom Jacob? et il m’a supplanté ces deux fois: il a pris mon droit d’aînesse; et voici, maintenant il a pris ma bénédiction! Et il dit: Ne m’as-tu pas réservé une bénédiction?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Et Isaac répondit et dit à Ésaü: Voici, je l’ai établi ton maître, et je lui ai donné tous ses frères pour serviteurs, et je l’ai sustenté avec du froment et du moût; que ferai-je donc pour toi, mon fils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Et Ésaü dit à son père: N’as-tu que cette seule bénédiction, mon père? Bénis-moi, moi aussi, mon père! Et Ésaü éleva sa voix et pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Et Isaac, son père, répondit et lui dit: Voici, ton habitation sera en la graisse de la terre et en la rosée des cieux d’en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Et tu vivras de ton épée, et tu serviras ton frère; et il arrivera que, lorsque tu seras devenu nomade, tu briseras son joug de dessus ton cou.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, '*Et Ésaü eut Jacob en haine, à cause de la bénédiction dont son père l’avait béni; et Ésaü dit en son cœur: Les jours du deuil de mon père approchent, et je tuerai Jacob, mon frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Et on rapporta à Rebecca les paroles d’Ésaü, son fils aîné; et elle envoya, et appela Jacob, son plus jeune fils, et lui dit: Voici, Ésaü, ton frère, se console à ton sujet dans l’espoir de te tuer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Et maintenant, mon fils, écoute ma voix: Lève-toi, fuis chez Laban, mon frère, à Charan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'et tu demeureras avec lui quelques jours, jusqu’à ce que la fureur de ton frère se détourne,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'jusqu’à ce que la colère de ton frère se détourne de toi et qu’il oublie ce que tu lui as fait, et que j’envoie et que je te tire de là. Pourquoi serais-je privée de vous deux en un jour?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Et Rebecca dit à Isaac: J’ai la vie en aversion à cause des filles de Heth. Si Jacob prend une femme d’entre les filles de Heth, comme celles-ci, d’entre les filles du pays, à quoi bon pour moi de vivre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Et Isaac appela Jacob, et le bénit, et lui commanda, et lui dit: Tu ne prendras pas de femme d’entre les filles de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Lève-toi, va à Paddan-Aram, à la maison de Bethuel, père de ta mère, et prends de là une femme d’entre les filles de Laban, frère de ta mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Et que le ✶Dieu Tout-puissant te bénisse, et te fasse fructifier et te multiplie, afin que tu deviennes une assemblée de peuples;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'et qu’il te donne la bénédiction d’Abraham, à toi et à ta semence avec toi, afin que tu possèdes le pays où tu as séjourné, lequel Dieu a donné à Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Et Isaac fit partir Jacob, qui s’en alla à Paddan-Aram, vers Laban, fils de Bethuel, l’Araméen, frère de Rebecca, mère de Jacob et d’Ésaü.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Et Ésaü vit qu’Isaac avait béni Jacob, et l’avait fait partir pour Paddan-Aram pour y prendre une femme, et qu’en le bénissant il lui avait commandé, disant: Tu ne prendras pas de femme d’entre les filles de Canaan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'et que Jacob avait écouté son père et sa mère, et s’en était allé à Paddan-Aram;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'alors Ésaü vit que les filles de Canaan étaient mal vues d’Isaac, son père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'et Ésaü s’en alla vers Ismaël, et prit pour femme, outre les femmes qu’il avait, Mahalath, fille d’Ismaël, fils d’Abraham, sœur de Nebaïoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Et Jacob sortit de Beër-Shéba, et s’en alla à Charan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'et il se rencontra en un lieu où il passa la nuit, car le soleil était couché; et il prit des pierres du lieu, et s’en fit un chevet, et se coucha en ce lieu-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Et il songea: et voici une échelle dressée sur la terre, et son sommet touchait aux cieux; et voici, les anges de Dieu montaient et descendaient sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Et voici, l’ Éternel se tenait sur elle, et il dit: Je suis l’ Éternel, le Dieu d’Abraham, ton père, et le Dieu d’Isaac; la terre, sur laquelle tu es couché, je te la donnerai, et à ta semence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'et ta semence sera comme la poussière de la terre; et tu t’étendras à l’occident, et à l’orient, et au nord, et au midi; et toutes les familles de la terre seront bénies en toi et en ta semence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Et voici, je suis avec toi; et je te garderai partout où tu iras, et je te ramènerai dans cette terre-ci, car je ne t’abandonnerai pas jusqu’à ce que j’aie fait ce que je t’ai dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Et Jacob se réveilla de son sommeil, et il dit: Certainement, l’ Éternel est dans ce lieu, et moi je ne le savais pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Et il eut peur, et dit: Que ce lieu-ci est terrible! Ce n’est autre chose que la maison de Dieu, et c’est ici la porte des cieux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Et Jacob se leva de bon matin, et prit la pierre dont il avait fait son chevet, et la dressa en stèle, et versa de l’huile sur son sommet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Et il appela le nom de ce lieu-là Béthel; mais premièrement le nom de la ville était Luz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Et Jacob fit un vœu, en disant: Si Dieu est avec moi et me garde dans ce chemin où je marche, et qu’il me donne du pain à manger et un vêtement pour me vêtir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'et que je retourne en paix à la maison de mon père, l’ Éternel sera mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Et cette pierre que j’ai dressée en stèle sera la maison de Dieu; et de tout ce que tu me donneras, je t’en donnerai la dîme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, '*Et Jacob se mit en marche, et s’en alla au pays des fils de l’orient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Et il regarda, et voici un puits dans les champs, et voilà trois troupeaux de menu bétail couchés auprès, (car de ce puits-là on abreuvait les troupeaux); et il y avait une grosse pierre sur l’ouverture du puits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Et tous les troupeaux se rassemblaient là, et on roulait la pierre de dessus l’ouverture du puits, et on abreuvait le bétail; puis on remettait la pierre à sa place, sur l’ouverture du puits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Et Jacob leur dit: Mes frères, d’où êtes-vous? Et ils dirent: Nous sommes de Charan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Et il leur dit: Connaissez-vous Laban, fils de Nakhor? Et ils dirent: Nous le connaissons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Et il leur dit: Se porte-t-il bien? Et ils dirent: Bien; et voici Rachel, sa fille, qui vient avec le bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Et il dit: Voici, il est encore grand jour, il n’est pas temps de rassembler les troupeaux; abreuvez le bétail, et allez, faites-le paître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Et ils dirent: Nous ne le pouvons pas, jusqu’à ce que tous les troupeaux soient rassemblés; alors on roule la pierre de dessus l’ouverture du puits, et nous abreuvons le bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Comme il parlait encore avec eux, Rachel vint avec le bétail qui était à son père; car elle était bergère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Et il arriva, quand Jacob vit Rachel, fille de Laban, frère de sa mère, et le bétail de Laban, frère de sa mère, que Jacob s’approcha, et roula la pierre de dessus l’ouverture du puits, et abreuva le bétail de Laban, frère de sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Et Jacob embrassa Rachel, et éleva sa voix, et pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Et Jacob apprit à Rachel qu’il était frère de son père et qu’il était fils de Rebecca; et elle courut le rapporter à son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Et il arriva que, lorsque Laban apprit les nouvelles de Jacob, fils de sa sœur, il courut à sa rencontre, et l’embrassa et lui donna un baiser, et le fit entrer dans sa maison; et [Jacob] raconta à Laban toutes ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Et Laban lui dit: Certes, tu es mon os et ma chair. Et il demeura avec lui un mois de temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Et Laban dit à Jacob: Parce que tu es mon frère, me serviras-tu pour rien? Dis-moi quel sera ton salaire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Or Laban avait deux filles; le nom de l’aînée était Léa, et le nom de la plus jeune, Rachel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Et Léa avait les yeux délicats; mais Rachel était belle de taille et belle de visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Et Jacob aimait Rachel, et il dit: Je te servirai sept ans pour Rachel, ta plus jeune fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Et Laban dit: Mieux vaut que je te la donne que de la donner à un autre homme; demeure avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Et Jacob servit pour Rachel sept années; et elles furent à ses yeux comme peu de jours, parce qu’il l’aimait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Et Jacob dit à Laban: Donne-moi ma femme; car mes jours sont accomplis, et je viendrai vers elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Et Laban rassembla tous les gens du lieu, et fit un festin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Et il arriva, le soir, qu’il prit Léa, sa fille, et la lui amena; et il vint vers elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Et Laban donna Zilpa, sa servante, à Léa, sa fille, pour servante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Et il arriva, au matin, que voici, c’était Léa. Et il dit à Laban: Que m’as-tu fait? N’est-ce pas pour Rachel que je t’ai servi? et pourquoi m’as-tu trompé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Et Laban dit: On ne fait pas ainsi, dans notre lieu, de donner la plus jeune avant l’aînée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Accomplis la semaine de celle-ci, et nous te donnerons aussi celle-là, pour le service que tu feras chez moi encore sept autres années.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Et Jacob fit ainsi, et il accomplit la semaine de celle-ci. Et [Laban] lui donna Rachel, sa fille, pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Et Laban donna Bilha, sa servante, à Rachel, sa fille, pour servante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Et il vint aussi vers Rachel; et il aima aussi Rachel plus que Léa. Et il servit Laban encore sept autres années.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Et l’ Éternel vit que Léa était haïe, et il ouvrit sa matrice; mais Rachel était stérile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Et Léa conçut, et enfanta un fils, et elle appela son nom Ruben, car elle dit: Parce que l’ Éternel a regardé mon affliction; car maintenant mon mari m’aimera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Et elle conçut encore, et enfanta un fils, et dit: Parce que l’ Éternel a entendu que j’étais haïe, il m’a donné aussi celui-ci; et elle appela son nom Siméon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Et elle conçut encore, et enfanta un fils, et dit: Maintenant, cette fois, mon mari s’attachera à moi, car je lui ai enfanté trois fils; c’est pourquoi on appela son nom Lévi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Et elle conçut encore, et enfanta un fils, et dit: Cette fois, je louerai l’ Éternel; c’est pourquoi elle appela son nom Juda; et elle cessa d’enfanter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Et Rachel vit qu’elle ne donnait pas d’enfants à Jacob, et Rachel fut jalouse de sa sœur, et dit à Jacob: Donne-moi des fils, sinon je meurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Et la colère de Jacob s’enflamma contre Rachel, et il dit: Suis-je à la place de Dieu, qui t’a refusé le fruit du ventre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Et elle dit: Voici ma servante Bilha: va vers elle; et elle enfantera sur mes genoux, et moi aussi j’aurai des enfants par elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Et elle lui donna Bilha, sa servante, pour femme; et Jacob vint vers elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Et Bilha conçut, et enfanta un fils à Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Et Rachel dit: Dieu m’a fait justice, et il a aussi entendu ma voix, et m’a donné un fils; c’est pourquoi elle appela son nom Dan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Et Bilha, servante de Rachel, conçut encore, et enfanta un second fils à Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Et Rachel dit: J’ai soutenu des luttes de Dieu avec ma sœur, aussi je l’ai emporté. Et elle appela son nom Nephthali.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Et Léa vit qu’elle avait cessé d’enfanter, et elle prit Zilpa, sa servante, et la donna pour femme à Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Et Zilpa, servante de Léa, enfanta un fils à Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Et Léa dit: La bonne fortune vient. Et elle appela son nom Gad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Et Zilpa, servante de Léa, enfanta un second fils à Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Et Léa dit: Pour mon bonheur! car les filles me diront bienheureuse. Et elle appela son nom Aser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Et Ruben sortit aux jours de la moisson du froment, et il trouva des mandragores dans les champs, et les apporta à Léa, sa mère. Et Rachel dit à Léa: Donne-moi, je te prie, des mandragores de ton fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Et elle lui dit: Est-ce peu de chose que tu m’aies pris mon mari, et tu prends aussi les mandragores de mon fils! Et Rachel dit: Eh bien, il couchera avec toi cette nuit pour les mandragores de ton fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Et Jacob vint des champs sur le soir, et Léa sortit à sa rencontre, et dit: C’est vers moi que tu viendras, car je t’ai loué pour les mandragores de mon fils. Et il coucha avec elle cette nuit-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Et Dieu entendit Léa, et elle conçut, et enfanta à Jacob un cinquième fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Et Léa dit: Dieu m’a donné mon salaire, parce que j’ai donné ma servante à mon mari. Et elle appela son nom Issacar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Et Léa conçut encore, et enfanta à Jacob un sixième fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Et Léa dit: Dieu m’a fait un beau don; cette fois mon mari habitera avec moi, car je lui ai enfanté six fils. Et elle appela son nom Zabulon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Et après, elle enfanta une fille, et appela son nom Dina.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Et Dieu se souvint de Rachel; et Dieu l’écouta et ouvrit sa matrice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Et elle conçut, et enfanta un fils, et dit: Dieu a ôté mon opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Et elle appela son nom Joseph, en disant: Que l’ Éternel m’ajoute un autre fils!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Et il arriva, quand Rachel eut enfanté Joseph, que Jacob dit à Laban: Renvoie-moi, et j’irai dans mon lieu et dans mon pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Donne-moi mes femmes pour lesquelles je t’ai servi, et mes enfants, et je m’en irai; car tu sais quel a été le service que je t’ai rendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Et Laban lui dit: [Écoute], si au moins j’ai trouvé grâce à tes yeux! J’ai aperçu que l’ Éternel m’a béni à cause de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Et il dit: Fixe-moi ton salaire, et je te le donnerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Et il lui dit: Tu sais comment je t’ai servi, et ce qu’est devenu ton troupeau avec moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'car ce que tu avais avant moi était peu de chose, et s’est accru et est devenu une multitude; et l’ Éternel t’a béni depuis que je suis venu. Et maintenant, quand travaillerai-je, moi aussi, pour ma maison?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Et [Laban] dit: Que te donnerai-je? Et Jacob dit: Tu ne me donneras rien. Si tu veux faire ceci pour moi, je paîtrai encore ton bétail, [et] je le garderai:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'je passerai aujourd’hui par tout ton bétail, j’en ôterai toute bête marquetée et tachetée, et tous les agneaux foncés, et ce qui est tacheté et marqueté parmi les chèvres; et ce sera là mon salaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Et ma justice répondra pour moi désormais, quand elle viendra devant toi pour mon salaire; tout ce qui ne sera pas marqueté et tacheté parmi les chèvres, et foncé parmi les agneaux, auprès de moi, sera tenu pour volé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Et Laban dit: Voici, qu’il en soit selon ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Et il ôta ce jour-là les boucs rayés et tachetés, et toutes les chèvres marquetées et tachetées, toutes celles qui avaient du blanc, et tout ce qui était foncé parmi les agneaux, et il les remit entre les mains de ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Et il mit trois journées de chemin entre lui et Jacob; et Jacob paissait le reste du bétail de Laban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, '– Et Jacob prit des branches fraîches de peuplier blanc, de coudrier, et d’érable, et y pela des raies blanches, mettant à nu le blanc qui était aux branches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Et il plaça les branches, qu’il avait pelées, devant le bétail dans les auges, dans les abreuvoirs où le bétail venait boire; et le bétail entrait en chaleur lorsqu’il venait boire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'le bétail entrait en chaleur devant les branches, et il faisait des petits, rayés, marquetés, et tachetés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Et Jacob sépara les agneaux, et tourna la face du troupeau vers ce qui était rayé et tout ce qui était foncé dans le bétail de Laban; et il mit ses troupeaux à part, et ne les mit pas auprès du bétail de Laban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Et il arrivait que toutes les fois que les bêtes vigoureuses entraient en chaleur, Jacob mettait les branches dans les auges, devant les yeux du bétail, afin qu’elles entrent en chaleur en face des branches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Mais quand les bêtes étaient chétives, il ne les mettait pas; et les chétives étaient à Laban, et les vigoureuses à Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Et l’homme s’accrut extrêmement, et eut un bétail nombreux, et des servantes et des serviteurs, et des chameaux et des ânes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Et il entendit les paroles des fils de Laban, qui disaient: Jacob a pris tout ce qui était à notre père; et c’est avec ce qui était à notre père qu’il s’est fait toute cette gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Et Jacob regarda le visage de Laban; et voici, il n’était pas envers lui comme auparavant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Et l’ Éternel dit à Jacob: Retourne au pays de tes pères et vers ta parenté, et je serai avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Et Jacob envoya, et appela Rachel et Léa aux champs, vers son troupeau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'et il leur dit: Je vois le visage de votre père, qu’il n’est pas envers moi comme auparavant; mais le Dieu de mon père a été avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Et vous savez vous-mêmes que j’ai servi votre père de toute ma force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Et votre père s’est moqué de moi, et a changé dix fois mon salaire; mais Dieu ne lui a pas permis de me faire du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'S’il disait ainsi: Les marquetés seront ton salaire, alors tout le bétail faisait des marquetés. Et s’il disait ainsi: Les rayés seront ton salaire, alors tout le bétail faisait des rayés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Et Dieu a ôté le troupeau de votre père et me l’a donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Et il arriva, au temps où le bétail entrait en chaleur, que je levai mes yeux, et je vis en songe, et voici, les boucs qui couvraient le menu bétail étaient rayés, marquetés, et picotés de blanc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Et l’Ange de Dieu me dit en songe: Jacob! Et je dis: Me voici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Et il dit: Lève tes yeux, et vois: tous les boucs qui couvrent le menu bétail sont rayés, marquetés, et picotés de blanc; car j’ai vu tout ce que t’a fait Laban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Je suis le ✶Dieu de Béthel, où tu oignis une stèle, où tu me fis un vœu. Maintenant, lève-toi, sors de ce pays, et retourne au pays de ta parenté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Et Rachel et Léa répondirent et lui dirent: Avons-nous encore une portion et un héritage dans la maison de notre père?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'N’avons-nous pas été réputées par lui des étrangères? car il nous a vendues, et a même toujours mangé notre argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Car toutes les richesses que Dieu a ôtées à notre père sont à nous et à nos enfants. Et maintenant, fais tout ce que Dieu t’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Et Jacob se leva, et fit monter ses fils et ses femmes sur les chameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'et il emmena tous ses troupeaux et tout son bien qu’il avait acquis, les troupeaux qu’il possédait, qu’il avait acquis à Paddan-Aram, pour aller vers Isaac, son père, au pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Et Laban était allé tondre son menu bétail, et Rachel vola les théraphim qui étaient à son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Et Jacob trompa Laban, l’Araméen, car il ne lui apprit pas qu’il s’enfuyait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Et il s’enfuit, lui, et tout ce qui était à lui; et il se leva, et passa le fleuve, et dressa sa face vers la montagne de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Et le troisième jour on rapporta à Laban que Jacob s’était enfui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Et il prit ses frères avec lui, et le poursuivit le chemin de sept jours, et l’atteignit à la montagne de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Et Dieu vint vers Laban, l’Araméen, dans un songe, la nuit, et lui dit: Garde-toi de parler à Jacob, ni en bien, ni en mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Et Laban atteignit Jacob; et Jacob avait dressé sa tente sur la montagne; et Laban dressa [la sienne] avec ses frères, sur la montagne de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Et Laban dit à Jacob: Qu’as-tu fait de m’avoir trompé, et d’avoir emmené mes filles comme des captives de guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Pourquoi t’es-tu enfui en cachette, et t’es-tu dérobé d’avec moi, et ne m’as-tu pas averti? Et je t’aurais renvoyé avec joie, et avec des chants, avec le tambourin et avec la harpe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Et tu ne m’as pas laissé embrasser mes fils et mes filles; en cela, tu as agi follement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'J’ai en ma main le pouvoir de vous faire du mal; mais le Dieu de votre père m’a parlé la nuit passée, disant: Garde-toi de parler à Jacob, ni en bien, ni en mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Et maintenant que tu t’en es allé, parce que tu languissais tant après la maison de ton père, pourquoi as-tu volé mes dieux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Et Jacob répondit et dit à Laban: Parce que j’ai craint; car j’ai dit: De peur que tu ne me ravisses tes filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Qu’il ne vive pas, celui auprès de qui tu trouveras tes dieux! Devant nos frères reconnais ce qui est à toi chez moi, et prends-le. Or Jacob ne savait pas que Rachel les avait volés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Et Laban entra dans la tente de Jacob, et dans la tente de Léa, et dans la tente des deux servantes, et ne trouva [rien]; et il sortit de la tente de Léa, et entra dans la tente de Rachel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Or Rachel avait pris les théraphim, et les avait mis dans le bât du chameau, et s’était assise dessus; et Laban fouilla toute la tente, et ne trouva [rien].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Et elle dit à son père: Que mon seigneur ne voie pas d’un œil irrité que je ne puis me lever devant toi, car j’ai ce que les femmes ont coutume d’avoir. Et il chercha, mais il ne trouva pas les théraphim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Et Jacob se mit en colère, et querella Laban; et Jacob répondit et dit à Laban: Quelle est ma faute, quel est mon péché, que tu m’aies poursuivi avec ardeur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Quand tu as fouillé tous mes effets, qu’as-tu trouvé de tous les effets de ta maison? Mets-le ici devant mes frères et tes frères, et qu’ils jugent entre nous deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Ces 20 années j’ai été avec toi; tes brebis et tes chèvres n’ont pas avorté, et je n’ai pas mangé les béliers de ton troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Ce qui a été déchiré, je ne te l’ai pas rapporté; moi j’ai dû en souffrir la perte; tu as redemandé de ma main ce qui m’avait été volé de jour et ce qui m’avait été volé de nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'J’en étais là, que, de jour, la sécheresse me dévorait, et de nuit, la gelée; et mon sommeil fuyait mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Ces 20 années j’ai été dans ta maison; je t’ai servi 14 ans pour tes deux filles, et six ans pour ton menu bétail, et tu as changé dix fois mon salaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Si le Dieu de mon père, le Dieu d’Abraham et la frayeur d’Isaac, n’avait été pour moi, certes, tu m’aurais maintenant renvoyé à vide. Dieu a vu mon affliction et le labeur de mes mains, et il t’a repris la nuit passée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Et Laban répondit et dit à Jacob: Les filles sont mes filles, et les fils sont mes fils, et le bétail est mon bétail, et tout ce que tu vois est à moi! Et que ferais-je aujourd’hui à celles-ci, mes filles, ou à leurs fils qu’elles ont enfantés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Et maintenant, viens, nous ferons une alliance, moi et toi; et elle sera en témoignage entre moi et toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Et Jacob prit une pierre, et la dressa en stèle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Et Jacob dit à ses frères: Amassez des pierres. Et ils prirent des pierres, et en firent un monceau; et ils mangèrent là sur le monceau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Et Laban l’appela Jegar-Sahadutha, et Jacob l’appela Galhed.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Et Laban dit: Ce monceau est aujourd’hui témoin entre moi et toi. C’est pourquoi il appela son nom Galhed,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'et Mitspa, parce qu’il dit: Que l’ Éternel veille entre moi et toi, quand nous serons cachés l’un à l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Si tu maltraites mes filles, et si tu prends des femmes outre mes filles (il n’y a aucun homme avec nous), regarde, Dieu est témoin entre moi et toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Et Laban dit à Jacob: Voici ce monceau, et voici la stèle que j’ai élevée entre moi et toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'ce monceau sera témoin, et la stèle sera témoin, que moi je ne passerai point ce monceau [pour aller] vers toi, et que toi, tu ne passeras point ce monceau et cette stèle [pour venir] vers moi, pour [faire] du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Que le Dieu d’Abraham et le Dieu de Nakhor, le Dieu de leur père, juge entre nous. Et Jacob jura par la frayeur de son père Isaac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Et Jacob offrit un sacrifice sur la montagne et invita ses frères à manger le pain: et ils mangèrent le pain, et passèrent la nuit sur la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Et Laban se leva de bon matin, et il embrassa ses fils et ses filles, et les bénit; et Laban s’en alla, et retourna en son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, '*Et Jacob alla son chemin. Et les anges de Dieu le rencontrèrent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'et Jacob dit, quand il les vit: C’est l’armée de Dieu. Et il appela le nom de ce lieu-là Mahanaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Et Jacob envoya devant lui des messagers à Ésaü, son frère, au pays de Séhir, dans la campagne d’Édom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'et il leur commanda, disant: Vous parlerez ainsi à mon seigneur Ésaü: Ainsi a dit ton serviteur Jacob: J’ai séjourné chez Laban, et m’y suis arrêté jusqu’à présent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'et j’ai des bœufs, et des ânes, du menu bétail, et des serviteurs et des servantes; et je l’ai envoyé annoncer à mon seigneur, afin de trouver grâce à tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Et les messagers revinrent vers Jacob, disant: Nous sommes allés vers ton frère, vers Ésaü, et même il vient à ta rencontre, et 400 hommes avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Et Jacob craignit beaucoup, et fut dans l’angoisse; et il partagea le peuple qui était avec lui, et le menu bétail et le gros bétail, et les chameaux, en deux bandes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'et il dit: Si Ésaü vient à l’une des bandes et la frappe, la bande qui restera pourra échapper.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Et Jacob dit: Dieu de mon père Abraham, et Dieu de mon père Isaac! Éternel, qui m’as dit: Retourne en ton pays et vers ta parenté, et je te ferai du bien!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Je suis trop petit pour toutes les grâces et pour toute la vérité dont tu as usé envers ton serviteur; car j’ai passé ce Jourdain avec mon bâton; et maintenant je suis devenu deux bandes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Délivre-moi, je te prie, de la main de mon frère, de la main d’Ésaü, car je le crains, de peur qu’il ne vienne et ne me frappe – la mère avec les fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Et toi, tu as dit: Certes, je te ferai du bien, et je ferai devenir ta semence comme le sable de la mer, qui ne peut se nombrer à cause de son abondance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Et il passa là cette nuit; et il prit, de ce qui lui vint sous la main, un présent pour Ésaü, son frère:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, '200 chèvres, et 20 boucs; 200 brebis, et 20 béliers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, '30 chamelles allaitantes, et leurs petits; 40 vaches, et dix taureaux; 20 ânesses, et dix ânons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Et il les mit entre les mains de ses serviteurs, chaque troupeau à part, et il dit à ses serviteurs: Passez devant moi, et mettez de l’espace entre troupeau et troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Et il commanda au premier, disant: Quand Ésaü, mon frère, te rencontrera, et t’interrogera, disant: À qui es-tu? et où vas-tu? et à qui sont ces [troupeaux] devant toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'tu diras: À ton serviteur Jacob; c’est un présent envoyé à mon seigneur Ésaü; et voici, lui-même aussi [vient] après nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Et il commanda de même au second, de même au troisième, de même à tous ceux qui suivaient les troupeaux, disant: Selon cette parole vous parlerez à Ésaü, quand vous le trouverez;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'et vous direz aussi: Voici, ton serviteur Jacob [vient] après nous. Car il disait: Je l’apaiserai par le présent qui va devant moi, et après cela je verrai sa face; peut-être qu’il m’accueillera favorablement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Et le présent passa devant lui; mais, pour lui, il passa cette nuit-là dans le camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Et il se leva cette nuit-là, et prit ses deux femmes, et ses deux servantes, et ses onze enfants, et passa le gué de Jabbok.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Il les prit, et leur fit passer le torrent; et il fit passer ce qui était à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Et Jacob resta seul; et un homme lutta avec lui jusqu’au lever de l’aurore.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Et lorsqu’il vit qu’il ne prévalait pas sur lui, il toucha l’emboîture de sa hanche; et l’emboîture de la hanche de Jacob fut luxée, comme il luttait avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Et il dit: Laisse-moi aller, car l’aurore se lève. Et il dit: Je ne te laisserai point aller sans que tu m’aies béni.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Et il lui dit: Quel est ton nom? Et il dit: Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Et il dit: Ton nom ne sera plus appelé Jacob, mais Israël; car tu as lutté avec Dieu et avec les hommes, et tu as prévalu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Et Jacob demanda, et dit: Je te prie, déclare-moi ton nom. Et il dit: Pourquoi demandes-tu mon nom? Et il le bénit là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Et Jacob appela le nom du lieu Peniel: Car j’ai vu Dieu face à face, et mon âme a été délivrée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Et le soleil se levait sur lui comme il passait Peniel; et il boitait sur sa cuisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 33, 'C’est pourquoi, jusqu’à ce jour, les fils d’Israël ne mangent point du tendon qui est sur l’emboîture de la hanche; car il toucha l’emboîture de la hanche de Jacob sur le tendon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Et Jacob leva ses yeux, et regarda; et voici, Ésaü venait, et 400 hommes avec lui. Et il partagea les enfants entre Léa et Rachel et les deux servantes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Et il mit à la tête les servantes et leurs enfants, et puis Léa et ses enfants, et puis Rachel et Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Et il passa devant eux, et se prosterna en terre par sept fois, jusqu’à ce qu’il soit proche de son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Et Ésaü courut à sa rencontre, et l’embrassa, et se jeta à son cou, et lui donna un baiser; et ils pleurèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Et il leva ses yeux, et vit les femmes et les enfants, et dit: Que te sont-ils, ceux-là? Et il dit: Ce sont les enfants que Dieu a donnés à ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Et les servantes s’approchèrent, elles et leurs enfants, et se prosternèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Et Léa aussi s’approcha avec ses enfants, et ils se prosternèrent; et ensuite Joseph et Rachel s’approchèrent, et se prosternèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Et il dit: Que veux-tu avec tout ce camp que j’ai rencontré? Et il dit: C’est pour trouver grâce aux yeux de mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Et Ésaü dit: J’ai [de tout] en abondance, mon frère; que ce qui est à toi soit à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Et Jacob dit: Non, je te prie; si j’ai trouvé grâce à tes yeux, prends mon présent de ma main, car c’est pour cela que j’ai vu ta face comme si j’avais vu la face de Dieu, et que tu m’as accueilli favorablement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Prends, je te prie, mon présent qui t’a été amené; car Dieu a usé de grâce envers moi, et j’ai de tout. Et il le pressa, et il le prit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Et [Ésaü] dit: Partons et allons-nous-en, et je marcherai devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Et [Jacob] lui dit: Mon seigneur sait que les enfants sont délicats, et que je suis chargé de menu et de gros bétail qui allaite; et si on les presse un seul jour, ils mourront – tout le troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Que mon seigneur, je te prie, passe devant son serviteur; et moi je cheminerai tout doucement au pas de ce bétail qui est devant moi, et au pas des enfants, jusqu’à ce que j’arrive auprès de mon seigneur, à Séhir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Et Ésaü dit: Je te prie, que je laisse avec toi quelques-uns des gens qui sont avec moi. Et il dit: Pourquoi cela? Que je trouve grâce aux yeux de mon seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Et Ésaü s’en retourna ce jour-là, par son chemin, à Séhir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, '*Et Jacob s’en alla à Succoth, et bâtit une maison pour lui, et fit des cabanes pour son bétail: c’est pourquoi on appela le nom du lieu Succoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Et Jacob arriva en paix à la ville de Sichem, qui est dans le pays de Canaan, comme il venait de Paddan-Aram; et il campa en face de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Et il acheta de la main des fils de Hamor, père de Sichem, pour 100 kesitas, la portion du champ où il avait dressé sa tente;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'et il dressa là un autel et l’appela El-Élohé-Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Et Dina, fille de Léa, qu’elle avait enfantée à Jacob, sortit pour voir les filles du pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'et Sichem, fils de Hamor, le Hévien, prince du pays, la vit, et la prit, et coucha avec elle et l’humilia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Et son âme s’attacha à Dina, fille de Jacob, et il aima la jeune fille, et parla au cœur de la jeune fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Et Sichem parla à Hamor, son père, disant: Prends-moi cette jeune fille pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Et Jacob apprit qu’on avait déshonoré Dina, sa fille. Or ses fils étaient aux champs avec ses troupeaux; et Jacob se tut jusqu’à ce qu’ils viennent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Et Hamor, père de Sichem, vint vers Jacob pour parler avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Et les fils de Jacob vinrent des champs lorsqu’ils apprirent [ce qui était arrivé], et ces hommes furent affligés, et ils furent très irrités, parce qu’on avait commis une infamie en Israël, en couchant avec la fille de Jacob, ce qui ne devait point se faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Et Hamor leur parla, disant: L’âme de Sichem, mon fils, s’est attachée à votre fille; donnez-la-lui, je vous prie, pour femme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'et alliez-vous avec nous: donnez-nous vos filles, et prenez nos filles pour vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'et habitez avec nous, et le pays sera devant vous; habitez-y, et trafiquez, et ayez-y des possessions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Et Sichem dit au père et aux frères de Dina: Que je trouve grâce à vos yeux, et ce que vous me direz je le donnerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Haussez beaucoup pour moi la dot et le présent, et je donnerai selon que vous me direz; et donnez-moi la jeune fille pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Et les fils de Jacob répondirent avec ruse à Sichem et à Hamor, son père, et leur parlèrent (parce qu’il avait déshonoré Dina, leur sœur);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'et ils leur dirent: Nous ne pouvons point faire cela, de donner notre sœur à un homme incirconcis, car ce serait un opprobre pour nous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'nous nous accorderons avec vous seulement sous cette condition, que vous soyez comme nous en circoncisant tout mâle parmi vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'alors nous vous donnerons nos filles, et nous prendrons vos filles, et nous habiterons avec vous; et nous serons un seul peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Mais si vous ne nous écoutez pas, pour être circoncis, nous prendrons notre fille, et nous nous en irons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Et leurs paroles furent bonnes aux yeux de Hamor, et aux yeux de Sichem, fils de Hamor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Et le jeune homme ne différa point de faire la chose; car la fille de Jacob lui agréait beaucoup, et il était plus considéré que tous ceux de la maison de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Et Hamor, et Sichem, son fils, vinrent à la porte de leur ville, et parlèrent aux hommes de leur ville, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Ces hommes sont paisibles à notre égard; qu’ils habitent dans le pays, et y trafiquent: et voici, le pays est vaste devant eux; nous prendrons leurs filles pour femmes, et nous leur donnerons nos filles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'mais ces hommes s’accorderont avec nous, pour habiter avec nous, pour devenir un même peuple, seulement sous cette condition, que tout mâle parmi nous soit circoncis, comme ils sont circoncis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Leurs troupeaux, et leurs biens, et toutes leurs bêtes, ne seront-ils pas à nous? Seulement accordons-nous avec eux, et ils habiteront avec nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Et tous ceux qui sortaient par la porte de sa ville écoutèrent Hamor et Sichem, son fils; et tout mâle fut circoncis, tous ceux qui sortaient par la porte de sa ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Et il arriva, au troisième jour, comme ils étaient dans les souffrances, que deux fils de Jacob, Siméon et Lévi, frères de Dina, prirent chacun son épée, et vinrent hardiment contre la ville, et tuèrent tous les mâles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Et ils passèrent au fil de l’épée Hamor et Sichem, son fils, et emmenèrent Dina de la maison de Sichem, et s’en allèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Les fils de Jacob se jetèrent sur les tués et pillèrent la ville, parce qu’on avait déshonoré leur sœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'ils prirent leur menu bétail, et leur gros bétail, et leurs ânes, et ce qu’il y avait dans la ville et ce qu’il y avait aux champs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'et ils emmenèrent et pillèrent tous leurs biens, et tous leurs petits enfants, et leurs femmes, et tout ce qui était dans les maisons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Et Jacob dit à Siméon et à Lévi: Vous m’avez troublé, en me mettant en mauvaise odeur auprès des habitants du pays, les Cananéens et les Phéréziens, et moi je n’ai qu’un petit nombre d’hommes; et ils s’assembleront contre moi, et me frapperont, et je serai détruit, moi et ma maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Et ils dirent: Traitera-t-on notre sœur comme une prostituée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, '*Et Dieu dit à Jacob: Lève-toi, monte à Béthel, et habite là, et fais-y un autel au ✶Dieu qui t’apparut comme tu t’enfuyais de devant la face d’Ésaü, ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Et Jacob dit à sa maison et à tous ceux qui étaient avec lui: Ôtez les dieux étrangers qui sont au milieu de vous, et purifiez-vous, et changez vos vêtements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'et nous nous lèverons, et nous monterons à Béthel, et je ferai là un autel à ✶Dieu, qui m’a répondu au jour de ma détresse, et qui a été avec moi dans le chemin où j’ai marché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Et ils donnèrent à Jacob tous les dieux étrangers qui étaient en leurs mains, et les anneaux qui étaient à leurs oreilles, et Jacob les cacha sous le térébinthe qui était près de Sichem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Et ils partirent; et la frayeur de Dieu fut sur les villes qui les entouraient, et on ne poursuivit pas les fils de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Et Jacob vint à Luz (c’est Béthel), qui est dans le pays de Canaan, lui et tout le peuple qui était avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'et il bâtit là un autel, et il appela le lieu El-Béthel; car c’est là que Dieu s’était révélé à lui comme il s’enfuyait de devant la face de son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Et Debora, la nourrice de Rebecca, mourut; et elle fut enterrée au-dessous de Béthel, sous un chêne dont le nom fut appelé Allon-Bacuth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Et Dieu apparut encore à Jacob, à son retour de Paddan-Aram, et le bénit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'et Dieu lui dit: Ton nom est Jacob; ton nom ne sera plus appelé Jacob, mais Israël sera ton nom. Et il appela son nom Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Et Dieu lui dit: Je suis le ✶Dieu Tout-puissant; fructifie et multiplie; une nation, et une multitude de nations, proviendra de toi; et des rois sortiront de tes reins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Et le pays que j’ai donné à Abraham et à Isaac, je te le donnerai, et je donnerai le pays à ta semence après toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Et Dieu monta d’auprès de lui, dans le lieu où il avait parlé avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Et Jacob érigea une stèle au lieu où il avait parlé avec lui, une stèle de pierre, et il répandit dessus une libation, et y versa de l’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Et Jacob appela le nom du lieu où Dieu avait parlé avec lui Béthel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Et ils partirent de Béthel; et il y avait encore quelque espace de pays pour arriver à Éphrath, et Rachel enfanta, et elle eut un enfantement pénible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Et comme elle était en grand travail pour enfanter, la sage-femme lui dit: Ne crains point, car tu as ici encore un fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Et il arriva, comme son âme s’en allait (car elle mourut), qu’elle appela le nom du fils Ben-oni; et son père l’appela Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Et Rachel mourut; et elle fut enterrée au chemin d’Éphrath, qui est Bethléhem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Et Jacob érigea une stèle sur son sépulcre: c’est la stèle du sépulcre de Rachel, jusqu’à aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Et Israël partit, et dressa sa tente au-delà de Migdal-Éder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Et il arriva, pendant qu’Israël demeurait dans ce pays-là, que Ruben alla et coucha avec Bilha, concubine de son père; et Israël l’apprit. Et les fils de Jacob étaient douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Les fils de Léa: Ruben, premier-né de Jacob, et Siméon, et Lévi, et Juda, et Issacar, et Zabulon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'les fils de Rachel: Joseph et Benjamin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'et les fils de Bilha, la servante de Rachel: Dan et Nephthali;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'et les fils de Zilpa, la servante de Léa: Gad et Aser. Ce sont là les fils de Jacob, qui lui naquirent à Paddan-Aram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Et Jacob vint vers Isaac, son père, à Mamré, à Kiriath-Arba, qui est Hébron, où Abraham et Isaac avaient séjourné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Et les jours d’Isaac furent 180 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Et Isaac expira et mourut, et fut recueilli vers ses peuples, âgé et rassasié de jours; et Ésaü et Jacob, ses fils, l’enterrèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, '*Et ce sont ici les générations d’Ésaü, qui est Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ésaü prit ses femmes d’entre les filles de Canaan: Ada, fille d’Élon, le Héthien; et Oholibama, fille d’Ana, fille de Tsibhon, le Hévien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'et Basmath, fille d’Ismaël, sœur de Nebaïoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Et Ada enfanta à Ésaü Éliphaz; et Basmath enfanta Rehuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Et Oholibama enfanta Jehush, et Jahlam, et Coré. Ce sont là les fils d’Ésaü, qui lui naquirent dans le pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Et Ésaü prit ses femmes, et ses fils et ses filles, et toutes les personnes de sa maison, et ses troupeaux, et tout son bétail, et tout le bien qu’il avait acquis dans le pays de Canaan, et il s’en alla dans un pays, loin de Jacob, son frère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'car leur avoir était trop grand pour qu’ils puissent habiter ensemble, et le pays de leur séjour ne pouvait les porter à cause de leurs troupeaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Et Ésaü habita dans la montagne de Séhir: Ésaü, c’est Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Et ce sont ici les générations d’Ésaü, père d’Édom, dans la montagne de Séhir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Ce sont ici les noms des fils d’Ésaü: Éliphaz, fils d’Ada, femme d’Ésaü; Rehuel, fils de Basmath, femme d’Ésaü.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, '– Et les fils d’Éliphaz furent Théman, Omar, Tsepho, et Gahtam, et Kenaz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Et Thimna fut concubine d’Éliphaz, fils d’Ésaü, et elle enfanta à Éliphaz Amalek. Ce sont là les fils d’Ada, femme d’Ésaü.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, '– Et ce sont ici les fils de Rehuel: Nakhath et Zérakh, Shamma et Mizza. Ceux-là furent fils de Basmath, femme d’Ésaü.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, '– Et ceux-ci furent fils d’Oholibama, fille d’Ana, fille de Tsibhon, femme d’Ésaü: et elle enfanta à Ésaü Jehush, et Jahlam, et Coré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Ce sont ici les chefs des fils d’Ésaü. Les fils d’Éliphaz, premier-né d’Ésaü: le chef Théman, le chef Omar, le chef Tsepho, le chef Kenaz,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'le chef Coré, le chef Gahtam, le chef Amalek. Ce sont là les chefs [issus] d’Éliphaz, au pays d’Édom. Ce sont là les fils d’Ada.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, '– Et ce sont ici les fils de Rehuel, fils d’Ésaü: le chef Nakhath, le chef Zérakh, le chef Shamma, le chef Mizza. Ce sont là les chefs [issus] de Rehuel, au pays d’Édom. Ce sont là les fils de Basmath, femme d’Ésaü.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, '– Et ce sont ici les fils d’Oholibama, femme d’Ésaü: le chef Jehush, le chef Jahlam, le chef Coré. Ce sont là les chefs [issus] d’Oholibama, fille d’Ana, femme d’Ésaü.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, '– Ce sont là les fils d’Ésaü; et ce sont là leurs chefs: c’est Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Ce sont ici les fils de Séhir, le Horien, qui habitaient le pays: Lotan, et Shobal, et Tsibhon, et Ana,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'et Dishon, et Étser, et Dishan. Ce sont là les chefs des Horiens, fils de Séhir, au pays d’Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Et les fils de Lotan furent Hori et Hémam; et la sœur de Lotan, Thimna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, '– Et ce sont ici les fils de Shobal: Alvan, et Manakhath, et Ébal, Shepho et Onam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, '– Et ce sont ici les fils de Tsibhon: et Aïa et Ana. C’est cet Ana qui trouva les sources chaudes au désert, tandis qu’il paissait les ânes de Tsibhon, son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, '– Et ce sont ici les fils d’Ana: Dishon, et Oholibama, fille d’Ana.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, '– Et ce sont ici les fils de Dishon: Hemdan, et Eshban, et Jithran, et Keran.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, '– Ce sont ici les fils d’Étser: Bilhan, et Zaavan, et Akan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, '– Ce sont ici les fils de Dishan: Uts et Aran.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Ce sont ici les chefs des Horiens: le chef Lotan, le chef Shobal, le chef Tsibhon, le chef Ana,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'le chef Dishon, le chef Étser, le chef Dishan. Ce sont là les chefs des Horiens, selon leurs chefs, dans le pays de Séhir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Et ce sont ici les rois qui régnèrent dans le pays d’Édom, avant qu’un roi règne sur les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Béla, fils de Béor, régna en Édom, et le nom de sa ville était Dinhaba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, '– Et Béla mourut; et Jobab, fils de Zérakh, de Botsra, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, '– Et Jobab mourut; et Husham, du pays des Thémanites, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, '– Et Husham mourut; et à sa place régna Hadad, fils de Bedad, qui frappa Madian dans les champs de Moab; et le nom de sa ville était Avith.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, '– Et Hadad mourut; et Samla, de Masréka, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, '– Et Samla mourut; et Saül, de Rehoboth sur le fleuve, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, '– Et Saül mourut; et Baal-Hanan, fils d’Acbor, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, '– Et Baal-Hanan, fils d’Acbor, mourut; et Hadar régna à sa place; et le nom de sa ville était Pahu; et le nom de sa femme, Mehétabeël, fille de Matred, fille de Mézahab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Et ce sont ici les noms des chefs d’Ésaü, selon leurs familles, selon leurs lieux, par leurs noms: le chef Thimna, le chef Alva, le chef Jetheth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'le chef Oholibama, le chef Éla, le chef Pinon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'le chef Kenaz, le chef Théman, le chef Mibtsar,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'le chef Magdiel, le chef Iram. Ce sont là les chefs d’Édom, selon leurs habitations dans le pays de leur possession. C’est Ésaü, père d’Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, '*Et Jacob habita dans le pays où son père avait séjourné, dans le pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Ce sont ici les générations de Jacob: Joseph, âgé de 17 ans, paissait le menu bétail avec ses frères, et, [encore] jeune garçon, il était avec les fils de Bilha et les fils de Zilpa, femmes de son père; et Joseph rapporta à leur père leur mauvaise renommée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Et Israël aimait Joseph plus que tous ses fils, parce qu’il était pour lui le fils de sa vieillesse, et il lui fit une tunique bigarrée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Et ses frères virent que leur père l’aimait plus que tous ses frères; et ils le haïssaient, et ne pouvaient lui parler paisiblement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Et Joseph songea un songe, et le raconta à ses frères, et ils le haïrent encore davantage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Et il leur dit: Écoutez, je vous prie, ce songe que j’ai songé:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Voici, nous étions à lier des gerbes au milieu des champs; et voici, ma gerbe se leva, et elle se tint debout; et voici, vos gerbes l’entourèrent, et se prosternèrent devant ma gerbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Et ses frères lui dirent: Est-ce que tu dois donc régner sur nous? Domineras-tu sur nous? Et ils le haïrent encore davantage, à cause de ses songes et de ses paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Et il songea encore un autre songe, et le raconta à ses frères. Et il dit: Voici, j’ai encore songé un songe; et voici, le soleil, et la lune, et onze étoiles, se prosternaient devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Et il le conta à son père et à ses frères. Et son père le reprit, et lui dit: Qu’est-ce que ce songe que tu as songé? Est-ce que moi, et ta mère, et tes frères, nous viendrons nous prosterner en terre devant toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Et ses frères furent jaloux de lui; mais son père gardait cette parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Et ses frères allèrent paître le menu bétail de leur père à Sichem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Et Israël dit à Joseph: Tes frères ne paissent-ils pas [le troupeau] à Sichem? Viens, et je t’enverrai vers eux. Et il lui dit: Me voici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Et il lui dit: Va, je te prie; vois si tes frères se portent bien, et si le bétail est en bon état, et rapporte-m’en des nouvelles. Et il l’envoya de la vallée de Hébron; et il vint à Sichem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Et un homme le trouva, et voici, il errait dans les champs. Et l’homme lui demanda, disant: Que cherches-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Et il dit: Je cherche mes frères; indique-moi, je te prie, où ils paissent [le troupeau].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Et l’homme dit: Ils sont partis d’ici, car j’ai entendu qu’ils disaient: Allons à Dothan. Et Joseph alla après ses frères, et il les trouva en Dothan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Et ils le virent de loin; et avant qu’il soit proche d’eux, ils complotèrent contre lui pour le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Et ils se dirent l’un à l’autre: Le voici, il vient, ce maître songeur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Et maintenant, venez, tuons-le, et jetons-le dans une des citernes, et nous dirons: Une mauvaise bête l’a dévoré; et nous verrons ce que deviendront ses songes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Et Ruben entendit [cela], et le délivra de leurs mains; et il dit: Ne le frappons pas à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Et Ruben leur dit: Ne versez pas le sang. Jetez-le dans cette citerne qui est dans le désert, et ne mettez pas la main sur lui. [C’était] afin de le délivrer de leurs mains, pour le faire retourner vers son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Et il arriva, lorsque Joseph fut venu auprès de ses frères, qu’ils dépouillèrent Joseph de sa tunique, de la tunique bigarrée qui était sur lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'et ils le prirent et le jetèrent dans la citerne; or la citerne était vide: il n’y avait point d’eau dedans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Et ils s’assirent pour manger le pain; et ils levèrent les yeux et regardèrent, et voici, une caravane d’Ismaélites venait de Galaad; et leurs chameaux portaient des épices, du baume, et de la myrrhe, qu’ils allaient porter en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Et Juda dit à ses frères: Quel profit aurons-nous à tuer notre frère et à cacher son sang?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Venez, vendons-le aux Ismaélites; et que notre main ne soit pas sur lui; car il est notre frère, notre chair. Et ses frères l’écoutèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Et les hommes madianites, des marchands, passèrent. Et ils tirèrent Joseph de la citerne et le firent remonter; et ils vendirent Joseph pour 20 pièces d’argent aux Ismaélites; et ceux-ci emmenèrent Joseph en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Et Ruben retourna à la citerne; et voici, Joseph n’était pas dans la citerne; et il déchira ses vêtements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'et retourna vers ses frères, et dit: L’enfant n’y est pas, et moi, où irai-je?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Et ils prirent la tunique de Joseph, et tuèrent un bouc, et plongèrent la tunique dans le sang;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'et ils envoyèrent la tunique bigarrée, et la firent parvenir à leur père, et dirent: Nous avons trouvé ceci; reconnais si c’est la tunique de ton fils, ou non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Et il la reconnut, et dit: C’est la tunique de mon fils; une mauvaise bête l’a dévoré: Joseph a certainement été déchiré!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Et Jacob déchira ses vêtements, et mit un sac sur ses reins, et mena deuil sur son fils plusieurs jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Et tous ses fils se levèrent, et toutes ses filles, pour le consoler; mais il refusa de se consoler, et dit: Certainement je descendrai, menant deuil, vers mon fils, au shéol. Et son père le pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Et les Madianites le vendirent en Égypte à Potiphar, officier du Pharaon, chef des gardes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, '*Et il arriva, dans ce temps-là, que Juda descendit d’auprès de ses frères, et se retira vers un homme adullamite, nommé Hira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Et Juda y vit la fille d’un homme cananéen, et son nom était Shua; et il la prit, et vint vers elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Et elle conçut, et enfanta un fils, et on appela son nom Er.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Et elle conçut encore, et enfanta un fils, et elle appela son nom Onan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Et elle enfanta encore un fils, et elle appela son nom Shéla. Et [Juda] était à Kezib quand elle l’enfanta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Et Juda prit pour Er, son premier-né, une femme qui se nommait Tamar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Et Er, premier-né de Juda, était méchant aux yeux de l’ Éternel, et l’ Éternel le fit mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Et Juda dit à Onan: Va vers la femme de ton frère, et remplis envers elle le devoir de beau-frère, et suscite de la semence à ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Et Onan savait que la semence ne serait pas à lui; et il arriva que lorsqu’il entra vers la femme de son frère, il perdit sur la terre, pour ne pas donner de semence à son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Et ce qu’il faisait fut mauvais aux yeux de l’ Éternel, et il le fit mourir aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Et Juda dit à Tamar, sa belle-fille: Demeure veuve dans la maison de ton père, jusqu’à ce que Shéla, mon fils, soit devenu grand; car il dit: De peur qu’il ne meure, lui aussi, comme ses frères. Et Tamar s’en alla, et demeura dans la maison de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Et les jours se multiplièrent, et la fille de Shua, femme de Juda, mourut; et Juda se consola, et monta à Thimna, lui et Hira, l’Adullamite, son ami, vers les tondeurs de son troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Et on l’annonça à Tamar, en disant: Voici, ton beau-père monte à Thimna pour tondre son troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Et elle ôta de dessus elle les vêtements de son veuvage, et se couvrit d’un voile, et s’enveloppa, et s’assit à l’entrée d’Énaïm, qui était sur le chemin de Thimna; car elle voyait que Shéla était devenu grand, et qu’elle ne lui était pas donnée pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Et Juda la vit, et la tint pour une prostituée, car elle avait couvert son visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Et il se détourna vers elle, dans le chemin, et dit: Permets, je te prie, que je vienne vers toi. Car il ne savait pas que c’était sa belle-fille. Et elle dit: Que me donneras-tu, afin que tu viennes vers moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Et il dit: J’enverrai un chevreau du troupeau. Et elle dit: [Me] donneras-tu un gage, jusqu’à ce que tu l’envoies?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Et il dit: Quel gage te donnerai-je? Et elle dit: Ton cachet, et ton cordon, et ton bâton qui est en ta main. Et il [les] lui donna; et il vint vers elle, et elle conçut de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Et elle se leva et s’en alla, et ôta son voile de dessus elle, et revêtit les vêtements de son veuvage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Et Juda envoya le chevreau par la main de son ami, l’Adullamite, pour recevoir le gage de la main de la femme; mais il ne la trouva pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Et il interrogea les hommes du lieu, disant: Où est cette prostituée qui était à Énaïm, sur le chemin? Et ils dirent: Il n’y a pas eu ici de prostituée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Et il retourna vers Juda, et dit: Je ne l’ai pas trouvée, et aussi les gens du lieu m’ont dit: Il n’y a pas eu ici de prostituée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Et Juda dit: Qu’elle prenne le [gage] pour elle, de peur que nous ne soyons en mépris. Voici, j’ai envoyé ce chevreau, et toi tu ne l’as pas trouvée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Et il arriva, environ trois mois après, qu’on informa Juda, en disant: Tamar, ta belle-fille, s’est prostituée, et voici, elle est même enceinte par la prostitution. Et Juda dit: Faites-la sortir, et qu’elle soit brûlée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Comme on la faisait sortir, elle envoya vers son beau-père, disant: C’est de l’homme à qui appartiennent ces choses que je suis enceinte. Et elle dit: Reconnais, je te prie, à qui est ce cachet, et ce cordon, et ce bâton.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Et Juda [les] reconnut, et dit: Elle est plus juste que moi; parce que je ne l’ai pas donnée à Shéla, mon fils. Et il ne la connut plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Et il arriva, au temps où elle enfanta, que voici, des jumeaux étaient dans son ventre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'et il arriva, comme elle enfantait, que [l’un d’eux] tendit la main; et la sage-femme la prit, et lia sur sa main un fil écarlate, en disant: Celui-ci sort le premier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Et il arriva, comme il retira sa main, que voici, son frère sortit; et elle dit: Quelle brèche tu as faite! La brèche est sur toi. Et on appela son nom Pérets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Et ensuite sortit son frère, sur la main duquel était le fil écarlate; et on appela son nom Zérakh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, '*Et Joseph fut amené en Égypte; et Potiphar, officier du Pharaon, chef des gardes, homme égyptien, l’acheta de la main des Ismaélites qui l’y avaient amené.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Et l’ Éternel fut avec Joseph; et il était un homme qui faisait [tout] prospérer; et il était dans la maison de son seigneur, l’Égyptien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Et son seigneur vit que l’ Éternel était avec lui, et que tout ce qu’il faisait, l’ Éternel le faisait prospérer en sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Et Joseph trouva grâce à ses yeux, et il le servait; et [Potiphar] l’établit sur sa maison, et il mit entre ses mains tout ce qui était à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Et il arriva, depuis qu’il l’eut établi sur sa maison et sur tout ce qui était à lui, que l’ Éternel bénit la maison de l’Égyptien à cause de Joseph; et la bénédiction de l’ Éternel fut sur tout ce qui était à lui, dans la maison et aux champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Et il laissa aux mains de Joseph tout ce qui était à lui, et il ne prenait avec lui connaissance d’aucune chose, sauf du pain qu’il mangeait. Or Joseph était beau de taille et beau de visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Et il arriva, après ces choses, que la femme de son seigneur leva ses yeux sur Joseph; et elle dit: Couche avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Et il refusa, et dit à la femme de son seigneur: Voici, mon seigneur ne prend avec moi connaissance de quoi que ce soit dans la maison, et il a mis entre mes mains tout ce qui est à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Personne n’est plus grand que moi dans cette maison, et il ne m’a rien interdit que toi, parce que tu es sa femme; et comment ferais-je ce grand mal, et pécherais-je contre Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Et il arriva, comme elle parlait à Joseph, jour après jour, qu’il ne l’écouta pas pour coucher à côté d’elle, pour être avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, '– Et il arriva, un certain jour, qu’il entra dans la maison pour faire ce qu’il avait à faire, et qu’il n’y avait là, dans la maison, aucun des hommes de la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Et elle le prit par son vêtement, disant: Couche avec moi. Et il laissa son vêtement dans sa main, et s’enfuit, et sortit dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Et il arriva, quand elle vit qu’il lui avait laissé son vêtement dans la main et s’était enfui dehors,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'qu’elle appela les hommes de sa maison, et leur parla, disant: Voyez! on nous a amené un homme hébreu pour se moquer de nous: il est venu vers moi pour coucher avec moi; et j’ai crié à haute voix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'et il est arrivé, quand il a entendu que j’élevais ma voix et que je criais, qu’il a laissé son vêtement à côté de moi, et s’est enfui, et est sorti dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Et elle posa le vêtement de Joseph à côté d’elle, jusqu’à ce que son seigneur vienne à la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Et elle lui parla selon ces paroles, disant: Le serviteur hébreu que tu nous as amené est venu vers moi pour se moquer de moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'et il est arrivé, comme j’élevais ma voix et que je criais, qu’il a laissé son vêtement à côté de moi et s’est enfui dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Et quand son seigneur entendit les paroles de sa femme qu’elle lui disait: C’est de cette manière que ton serviteur a agi envers moi – il arriva que sa colère s’enflamma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Et le seigneur de Joseph le prit, et le mit dans la tour, dans le lieu où les prisonniers du roi étaient enfermés; et il fut là, dans la tour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Et l’ Éternel était avec Joseph; et il étendit sa bonté sur lui, et lui fit trouver grâce aux yeux du chef de la tour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Et le chef de la tour mit en la main de Joseph tous les prisonniers qui étaient dans la tour, et tout ce qui se faisait là, c’est lui qui le faisait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'le chef de la tour ne regardait rien de tout ce qui était en sa main, parce que l’ Éternel était avec lui; et ce qu’il faisait, l’ Éternel le faisait prospérer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Et il arriva, après ces choses, que l’échanson du roi d’Égypte et le panetier péchèrent contre leur seigneur, le roi d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Et le Pharaon fut irrité contre ses deux officiers, contre le chef des échansons et contre le chef des panetiers,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'et il les mit sous garde dans la maison du chef des gardes, dans la tour, dans le lieu où Joseph était emprisonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Et le chef des gardes les confia aux soins de Joseph, et il les servait; et ils furent [plusieurs] jours sous garde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Et ils songèrent un songe, tous les deux, chacun son songe, en une même nuit, chacun selon l’interprétation de son songe, l’échanson et le panetier du roi d’Égypte, qui étaient emprisonnés dans la tour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Et Joseph vint vers eux au matin, et les regarda; et voici, ils étaient tristes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Et il interrogea les officiers du Pharaon qui étaient avec lui sous garde dans la maison de son seigneur, disant: Pourquoi avez-vous mauvais visage aujourd’hui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Et ils lui dirent: Nous avons songé un songe, et il n’y a personne pour l’interpréter. Et Joseph leur dit: Les interprétations ne sont-elles pas à Dieu? Je vous prie, contez-moi [vos songes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Et le chef des échansons conta son songe à Joseph, et lui dit: Dans mon songe, voici, un cep était devant moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'et sur ce cep, trois sarments; et il était comme bourgeonnant: sa fleur monta, ses grappes produisirent des raisins mûrs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'et la coupe du Pharaon était dans ma main, et je pris les raisins, et les pressai dans la coupe du Pharaon, et je mis la coupe dans la main du Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Et Joseph lui dit: C’est ici son interprétation: Les trois sarments, ce sont trois jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Encore trois jours, et le Pharaon élèvera ta tête, et te rétablira dans ton poste, et tu mettras la coupe du Pharaon dans sa main, selon l’ancienne coutume quand tu étais son échanson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Mais souviens-toi de moi, quand tu seras dans la prospérité, et use, je te prie, de bonté envers moi, et fais mention de moi au Pharaon, et fais-moi sortir de cette maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'car j’ai été volé du pays des Hébreux; et ici non plus je n’ai rien fait pour qu’on me mette dans la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Et le chef des panetiers vit qu’il interprétait favorablement, et il dit à Joseph: Moi aussi, [j’ai vu] dans mon songe; et voici, trois corbeilles de pain blanc étaient sur ma tête;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'et dans la corbeille la plus élevée il y avait de toutes sortes de mets pour le Pharaon, d’ouvrage de paneterie; et les oiseaux les mangeaient de la corbeille au-dessus de ma tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Et Joseph répondit et dit: C’est ici son interprétation: Les trois corbeilles, ce sont trois jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Encore trois jours, et le Pharaon élèvera ta tête de dessus toi, et te pendra à un bois, et les oiseaux mangeront ta chair de dessus toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Et il arriva, le troisième jour, jour de la naissance du Pharaon, qu’il fit un festin à tous ses serviteurs; et il éleva la tête du chef des échansons et la tête du chef des panetiers au milieu de ses serviteurs:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'il rétablit le chef des échansons dans son office d’échanson, et il mit la coupe dans la main du Pharaon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'et il pendit le chef des panetiers, selon que Joseph le leur avait interprété.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Mais le chef des échansons ne se souvint pas de Joseph, et l’oublia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Et il arriva, au bout de deux années révolues, que le Pharaon songea, et voici, il se tenait près du fleuve:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'et voici, du fleuve montaient sept vaches, belles à voir, et grasses de chair, et elles paissaient dans les roseaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Et voici, après elles, sept autres vaches montaient du fleuve, laides à voir, et pauvres de chair; et elles se tinrent à côté des vaches qui étaient sur le bord du fleuve;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'et les vaches laides à voir, et pauvres de chair, mangèrent les sept vaches belles à voir, et grasses. Et le Pharaon s’éveilla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Et il s’endormit, et songea une seconde fois: et voici, sept épis gras et bons montaient sur une seule tige.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Et voici, sept épis pauvres et brûlés par le vent d’orient germaient après eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'et les épis pauvres dévorèrent les sept épis gras et pleins. Et le Pharaon s’éveilla; et voilà, [c’était] un songe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Et il arriva, au matin, que son esprit fut troublé; et il envoya, et appela tous les devins de l’Égypte, et tous ses sages. Et le Pharaon leur raconta ses songes; et il n’y eut personne qui les interprète au Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Et le chef des échansons parla au Pharaon, disant: Je rappelle aujourd’hui mes fautes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Le Pharaon fut irrité contre ses serviteurs, et me mit sous garde, moi et le chef des panetiers, dans la maison du chef des gardes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'et nous avons songé un songe dans une même nuit, moi et lui; nous avons songé chacun selon l’interprétation de son songe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Et il y avait là avec nous un jeune hébreu, serviteur du chef des gardes; et nous lui avons raconté, et il nous interpréta nos songes; il donna à chacun l’interprétation selon son songe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Et il arriva que, comme il nous avait interprété, ainsi il advint: moi, [le Pharaon] me rétablit dans mon poste, et lui, il le pendit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Et le Pharaon envoya, et appela Joseph; et on le fit accourir de la fosse, et il se rasa, et changea de vêtements; et il vint vers le Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Et le Pharaon dit à Joseph: J’ai songé un songe, et il n’y a personne pour l’interpréter; et j’ai entendu dire de toi que tu comprends un songe pour l’interpréter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Et Joseph répondit au Pharaon, disant: Cela n’est pas à moi; Dieu donnera une réponse de paix au Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Et le Pharaon dit à Joseph: Dans mon songe, voici, je me tenais sur le bord du fleuve;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'et voici, du fleuve montaient sept vaches grasses de chair, et belles à voir, et elles paissaient dans les roseaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Et voici, sept autres vaches montaient après elles, chétives, et très laides à voir, et maigres de chair: je n’en ai pas vu de semblables en laideur dans tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Et les vaches maigres et laides mangèrent les sept premières vaches, les grasses:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'elles entrèrent dans leur ventre, et il ne paraissait point qu’elles soient entrées dans leur ventre, et leur aspect était aussi laid qu’au commencement. Et je m’éveillai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Et je vis dans mon songe; et voici, sept épis montaient sur une seule tige, pleins et bons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'et voici, sept épis desséchés, pauvres, brûlés par le vent d’orient, germaient après eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'et les épis pauvres dévorèrent les sept bons épis. Et je l’ai dit aux devins; et il n’y a eu personne qui me l’explique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Et Joseph dit au Pharaon: Le songe du Pharaon est un: Dieu a déclaré au Pharaon ce qu’il va faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Les sept bonnes vaches, ce sont sept années; et les sept bons épis, ce sont sept années: c’est un seul songe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Et les sept vaches maigres et laides qui montaient après elles, ce sont sept années; et les sept épis vides, brûlés par le vent d’orient, ce sont sept années de famine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'C’est la parole que je dis au Pharaon; ce que Dieu va faire, il le montre au Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Voici, sept années de grande abondance viennent dans tout le pays d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'et sept années de famine se lèveront après elles; et toute l’abondance sera oubliée dans le pays d’Égypte, et la famine consumera le pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'et l’abondance ne sera plus connue dans le pays, à cause de cette famine [qui viendra] après; car elle sera très intense.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Et que le songe ait été répété deux fois au Pharaon, c’est que la chose est arrêtée de la part de Dieu, et que Dieu se hâte de la faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Et maintenant, que le Pharaon se cherche un homme intelligent et sage, et qu’il l’établisse sur le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Que le Pharaon fasse [cela], et qu’il prépose des commissaires sur le pays, et qu’il lève le cinquième du pays d’Égypte pendant les sept années d’abondance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'et qu’ils rassemblent tous les vivres de ces bonnes années qui viennent, et qu’ils amassent le blé sous la main du Pharaon pour nourriture dans les villes, et qu’ils le gardent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Et les vivres seront une réserve pour le pays, pour les sept années de famine qui seront dans le pays d’Égypte, et le pays ne sera pas détruit par la famine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Et la chose fut bonne aux yeux du Pharaon et aux yeux de tous ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Et le Pharaon dit à ses serviteurs: Trouverons-nous un homme semblable à celui-ci, en qui est l’esprit des dieux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Et le Pharaon dit à Joseph: Puisque Dieu t’a fait connaître tout cela, personne n’est intelligent et sage comme toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Toi, tu seras sur ma maison, et tout mon peuple se dirigera d’après ton commandement; seulement quant au trône, je serai plus grand que toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Et le Pharaon dit à Joseph: Vois, je t’ai établi sur tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Et le Pharaon ôta son anneau de sa main, et le mit à la main de Joseph, et il le revêtit de vêtements de byssus, et mit un collier d’or à son cou;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'et il le fit monter sur le second char qui était à lui; et on criait devant lui: Abrec! Et il l’établit sur tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Et le Pharaon dit à Joseph: Moi je suis le Pharaon: sans toi nul ne lèvera la main ni le pied dans tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Et le Pharaon appela le nom de Joseph Tsaphnath-Pahnéakh; et il lui donna pour femme Asnath, fille de Poti-Phéra, sacrificateur d’On. Et Joseph parcourut le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Et Joseph était âgé de 30 ans lorsqu’il se tint devant le Pharaon, le roi d’Égypte; et Joseph sortit de devant le Pharaon, et passa par tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, '*Et la terre rapporta à pleines mains pendant les sept années d’abondance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Et [Joseph] rassembla tous les vivres des sept années qui furent dans le pays d’Égypte, et mit les vivres dans les villes; il mit dans chaque ville les vivres [provenant] des champs qui étaient autour d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Et Joseph amassa du blé, comme le sable de la mer, une immense quantité, jusqu’à ce qu’on cessa de compter, parce qu’il était sans nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Et, avant que vienne l’année de la famine, il naquit à Joseph deux fils, qu’Asnath, fille de Poti-Phéra, sacrificateur d’On, lui enfanta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Et Joseph appela le nom du premier-né Manassé: car Dieu m’a fait oublier toute ma peine, et toute la maison de mon père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Et il appela le nom du second Éphraïm: car Dieu m’a fait fructifier dans le pays de mon affliction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Et les sept années de l’abondance qui avait été dans le pays d’Égypte finirent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'et les sept années de la famine commencèrent à venir, comme Joseph avait dit. Et il y eut famine dans tous les pays; mais dans tout le pays d’Égypte il y avait du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Et tout le pays d’Égypte eut faim, et le peuple cria au Pharaon pour du pain; et le Pharaon dit à tous les Égyptiens: Allez à Joseph; faites ce qu’il vous dira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Et la famine était sur toute la face de la terre; et Joseph ouvrit tous les lieux de dépôt, et vendit du blé aux Égyptiens; et la famine sévissait dans le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Et de toute la terre on venait en Égypte, vers Joseph, pour acheter du blé; car la famine sévissait sur toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, '*Et Jacob vit qu’il y avait du blé en Égypte; et Jacob dit à ses fils: Pourquoi vous regardez-vous les uns les autres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Et il dit: Voici, j’ai appris qu’il y a du blé en Égypte; descendez-y, et achetez-nous-en là, afin que nous vivions, et que nous ne mourions pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Et dix frères de Joseph descendirent pour acheter du blé en Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'mais Jacob n’envoya pas Benjamin, le frère de Joseph, avec ses frères, car il disait: De peur qu’un accident ne lui arrive!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Et les fils d’Israël allèrent pour acheter du blé, parmi ceux qui allaient; car la famine était dans le pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Et Joseph était gouverneur du pays; il vendait le blé à tout le peuple du pays. Et les frères de Joseph vinrent, et se prosternèrent devant lui la face contre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Et Joseph vit ses frères, et les reconnut; et il fit l’étranger vis-à-vis d’eux, et leur parla durement, et leur dit: D’où venez-vous? Et ils dirent: Du pays de Canaan, pour acheter des vivres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Et Joseph reconnut ses frères; et eux ne le reconnurent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Et Joseph se souvint des songes qu’il avait songés à leur sujet, et il leur dit: Vous êtes des espions; c’est pour voir les lieux ouverts du pays que vous êtes venus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Et ils lui dirent: Non, mon seigneur; mais tes serviteurs sont venus pour acheter des vivres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Nous sommes tous fils d’un seul homme; nous sommes d’honnêtes gens; tes serviteurs ne sont pas des espions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Et il leur dit: Non; mais vous êtes venus pour voir les lieux ouverts du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Et ils dirent: Tes serviteurs étaient douze frères; nous sommes fils d’un seul homme, au pays de Canaan; et voici, le plus jeune est aujourd’hui avec notre père, et l’un n’est plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Et Joseph leur dit: C’est ce que je vous disais, en disant: Vous êtes des espions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Par ceci vous serez mis à l’épreuve: Vie du Pharaon! si vous sortez d’ici, à moins que votre jeune frère ne vienne ici!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Envoyez l’un de vous, et qu’il aille chercher votre frère; et vous, vous serez liés, et vos paroles seront mises à l’épreuve, [pour voir] si la vérité est avec vous: sinon, vie du Pharaon! certainement vous êtes des espions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Et il les fit mettre ensemble sous garde pendant trois jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Et, le troisième jour, Joseph leur dit: Faites ceci, et vous vivrez; moi je crains Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Si vous êtes d’honnêtes gens, l’un de vous, qui êtes frères, sera lié dans la maison où vous avez été sous garde; et vous, allez, emportez du blé pour la faim de vos maisons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'et amenez-moi le plus jeune de vos frères, et vos paroles se trouveront vraies; et vous ne mourrez pas. Et ils firent ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Et ils se dirent l’un à l’autre: Certainement nous sommes coupables à l’égard de notre frère; car nous avons vu la détresse de son âme quand il nous demandait grâce, et nous ne l’avons pas écouté; c’est pourquoi cette détresse est venue sur nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Et Ruben leur répondit, disant: Ne vous ai-je pas parlé, disant: Ne péchez pas contre l’enfant? Mais vous n’avez pas écouté; et aussi, voici, son sang est redemandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Et ils ne savaient pas que Joseph comprenait, car il y avait entre eux un interprète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Et il se détourna d’auprès d’eux, et pleura; et il revint vers eux, et leur parla, et prit d’avec eux Siméon, et le lia devant leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Et Joseph commanda de remplir de blé leurs sacs, et de leur remettre leur argent à chacun dans son sac, et de leur donner des provisions pour le chemin; et on leur fit ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Et ils chargèrent leur blé sur leurs ânes, et s’en allèrent de là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Et l’un [d’eux] ouvrit son sac pour donner à manger à son âne, dans le caravansérail, et il vit son argent, et voici, il était à l’ouverture de son sac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Et il dit à ses frères: Mon argent m’a été rendu; et même, le voici dans mon sac! Et le cœur leur manqua, et ils furent saisis de peur, se disant l’un à l’autre: Qu’est-ce que Dieu nous a fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Et ils vinrent vers Jacob, leur père, au pays de Canaan, et ils lui racontèrent tout ce qui leur était arrivé, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'L’homme, le seigneur du pays, nous a parlé durement, et nous a traités comme des espions du pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'et nous lui avons dit: Nous sommes d’honnêtes gens, nous ne sommes pas des espions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Nous étions douze frères, fils de notre père: l’un n’est plus, et le plus jeune est aujourd’hui avec notre père au pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Et l’homme, le seigneur du pays, nous a dit: À ceci je connaîtrai que vous êtes d’honnêtes gens: Laissez auprès de moi l’un de vos frères, et prenez [du blé] pour la faim de vos maisons, et allez-vous-en.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Et amenez-moi votre plus jeune frère, et je connaîtrai que vous n’êtes pas des espions, mais que vous êtes d’honnêtes gens: je vous donnerai votre frère, et vous trafiquerez dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Et il arriva, comme ils vidaient leurs sacs, que voici, chacun avait son paquet d’argent dans son sac; et ils virent, eux et leur père, leurs paquets d’argent, et ils eurent peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Et Jacob, leur père, leur dit: Vous m’avez privé d’enfants: Joseph n’est plus, et Siméon n’est plus, et vous voulez prendre Benjamin! Toutes ces choses sont contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Et Ruben parla à son père, disant: Tu feras mourir mes deux fils si je ne te le ramène; remets-le entre mes mains, et je te le ramènerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Mais il dit: Mon fils ne descendra pas avec vous; car son frère est mort, et lui seul est resté; si quelque accident lui arrivait dans le chemin où vous allez, vous feriez descendre mes cheveux blancs avec douleur au shéol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, '*Et la famine pesait sur le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Et il arriva, lorsqu’ils eurent achevé de manger le blé qu’ils avaient apporté d’Égypte, que leur père leur dit: Retournez, achetez-nous un peu de vivres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Et Juda lui parla, disant: Cet homme nous a expressément protesté, disant: Vous ne verrez pas ma face, à moins que votre frère ne soit avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Si tu envoies notre frère avec nous, nous descendrons, et nous t’achèterons des vivres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'mais si tu ne l’envoies pas, nous ne descendrons pas; car l’homme nous a dit: Vous ne verrez pas ma face, à moins que votre frère ne soit avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Et Israël dit: Pourquoi m’avez-vous fait le tort de déclarer à l’homme que vous aviez encore un frère?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Et ils dirent: L’homme s’est soigneusement enquis de nous et de notre parenté, disant: Votre père vit-il encore? Avez-vous [encore] un frère? Et nous l’avons informé selon la teneur de ces paroles. Pouvions-nous donc savoir qu’il dirait: Faites descendre votre frère?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Et Juda dit à Israël, son père: Envoie le jeune homme avec moi, et nous nous lèverons et nous irons, et nous vivrons et ne mourrons pas, ni nous, ni toi, ni nos petits enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Moi, je réponds de lui; tu le redemanderas de ma main. Si je ne te le ramène, et si je ne le présente devant ta face, je serai tous mes jours coupable envers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Car si nous n’avions pas tardé, certes nous serions déjà revenus deux fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Et Israël, leur père, leur dit: Eh bien, s’il en est ainsi, faites ceci: Prenez dans vos vases des meilleurs produits du pays, et portez à l’homme un présent: un peu de baume et un peu de miel, des épices et de la myrrhe, des pistaches et des amandes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Et prenez d’autre argent dans vos mains; et l’argent qui a été remis à l’ouverture de vos sacs, reportez-le dans vos mains; peut-être était-ce une erreur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Et prenez votre frère, et levez-vous, retournez vers l’homme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'et le ✶Dieu Tout-puissant vous fasse trouver compassion devant l’homme, afin qu’il renvoie votre autre frère, et Benjamin! Et moi, si je suis privé d’enfants, j’en serai privé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Et les hommes prirent ce présent; et ils prirent double argent dans leurs mains, et Benjamin, et ils se levèrent, et descendirent en Égypte; et ils se tinrent devant Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Et Joseph vit Benjamin avec eux; et il dit à celui qui était [préposé] sur sa maison: Mène ces hommes dans la maison, et tue, et apprête; car ces hommes mangeront avec moi à midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Et l’homme fit comme Joseph avait dit, et il amena les hommes dans la maison de Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Et les hommes eurent peur de ce qu’on les menait dans la maison de Joseph, et ils dirent: C’est à cause de l’argent qui fut remis dans nos sacs au commencement, que nous sommes emmenés, pour qu’on se jette sur nous, et pour qu’on tombe sur nous, et pour qu’on nous prenne comme serviteurs, avec nos ânes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Et ils s’approchèrent de l’homme qui était [préposé] sur la maison de Joseph, et lui parlèrent à l’entrée de la maison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'et dirent: Ah, mon seigneur! nous sommes descendus au commencement pour acheter des vivres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'et il est arrivé, lorsque nous sommes venus au caravansérail, que nous avons ouvert nos sacs, et voici, l’argent de chacun était à l’ouverture de son sac, notre argent selon son poids; et nous l’avons rapporté dans nos mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Et nous avons apporté d’autre argent dans nos mains pour acheter des vivres; nous ne savons pas qui a mis notre argent dans nos sacs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Et il dit: Paix vous soit, ne craignez pas. C’est votre Dieu et le Dieu de votre père qui vous a donné un trésor dans vos sacs; votre argent m’est parvenu. Et il fit sortir Siméon vers eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Et l’homme introduisit ces hommes dans la maison de Joseph, et leur donna de l’eau, et ils lavèrent leurs pieds; et il donna du fourrage à leurs ânes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Et ils préparèrent le présent pour l’arrivée de Joseph à midi, car ils avaient entendu qu’ils mangeraient là le pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Et Joseph vint à la maison, et ils lui apportèrent dans la maison le présent qui était dans leurs mains, et se prosternèrent devant lui contre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Et il leur demanda s’ils étaient bien, et il dit: Votre père, le vieillard dont vous m’avez parlé, est-il bien? vit-il encore?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Et ils dirent: Ton serviteur, notre père, est bien; il vit encore. Et ils s’inclinèrent et se prosternèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Et il leva les yeux, et vit Benjamin, son frère, fils de sa mère, et dit: Est-ce là votre plus jeune frère dont vous m’avez parlé? Et il dit: Dieu te fasse grâce, mon fils!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Et Joseph se hâta, car ses entrailles s’étaient émues envers son frère, et il cherchait [où] pleurer; et il entra dans sa chambre, et y pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Puis il se lava le visage, et sortit; et il se contint, et dit: Servez le pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Et on le servit, lui à part, et eux à part, et les Égyptiens qui mangeaient avec lui, à part: car les Égyptiens ne pouvaient manger le pain avec les Hébreux; car c’est une abomination pour les Égyptiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Et ils s’assirent devant lui, le premier-né selon son droit d’aînesse, et le plus jeune selon sa jeunesse; et ces hommes s’étonnaient entre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Et il leur fit porter des mets de devant lui; et la portion de Benjamin était cinq fois plus grande que les portions d’eux tous; et ils burent, et firent bonne chère avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Et il commanda à celui qui était [préposé] sur sa maison, disant: Remplis de vivres les sacs de ces hommes, autant qu’ils en peuvent porter, et mets l’argent de chacun à l’ouverture de son sac;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'et mets ma coupe, la coupe d’argent, à l’ouverture du sac du plus jeune, avec l’argent de son blé. Et il fit selon la parole de Joseph, qu’il avait dite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Le matin ayant lui, ces hommes furent renvoyés, eux et leurs ânes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Ils sortirent de la ville; ils n’étaient pas loin, que Joseph dit à celui qui était [préposé] sur sa maison: Lève-toi, poursuis ces hommes, et quand tu les auras atteints, dis-leur: Pourquoi avez-vous rendu le mal pour le bien?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'N’est-ce pas la [coupe] dans laquelle mon seigneur boit, et par laquelle il devine? Vous avez mal agi dans ce que vous avez fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Et il les atteignit, et leur dit ces paroles-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Et ils lui dirent: Pourquoi mon seigneur parle-t-il ainsi? Loin de tes serviteurs de faire une telle chose!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Voici, l’argent que nous avons trouvé à l’ouverture de nos sacs, nous te l’avons rapporté du pays de Canaan; et comment aurions-nous volé de la maison de ton seigneur de l’argent ou de l’or?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Que celui de tes serviteurs chez qui [la coupe] se trouvera, meure; et nous aussi, nous serons serviteurs de mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Et il dit: Maintenant donc, qu’il en soit selon vos paroles: Celui chez qui elle sera trouvée sera mon serviteur, et vous, vous serez innocents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Et ils se hâtèrent, et descendirent chacun son sac à terre, et ouvrirent chacun son sac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Et il fouilla; il commença par l’aîné, et finit par le plus jeune; et la coupe fut trouvée dans le sac de Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Alors ils déchirèrent leurs vêtements, et chacun rechargea son âne, et ils retournèrent à la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Et Juda entra avec ses frères dans la maison de Joseph, qui y était encore, et ils se prosternèrent devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Et Joseph leur dit: Quelle action avez-vous faite? Ne savez-vous pas qu’un homme tel que moi sait deviner?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Et Juda dit: Que dirons-nous à mon seigneur? Comment parlerons-nous, et comment nous justifierons-nous? Dieu a trouvé l’iniquité de tes serviteurs. Voici, nous sommes serviteurs de mon seigneur, tant nous que celui dans la main duquel la coupe a été trouvée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Et il dit: Loin de moi de faire cela! Celui en la main duquel la coupe a été trouvée, lui, sera mon serviteur; et vous, montez en paix vers votre père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Et Juda s’approcha de lui, et dit: Hélas, mon seigneur, je te prie, que ton serviteur dise un mot aux oreilles de mon seigneur, et que ta colère ne s’enflamme pas contre ton serviteur; car tu es comme le Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mon seigneur a interrogé ses serviteurs, en disant: Avez-vous un père, ou un frère?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Et nous avons dit à mon seigneur: Nous avons un père âgé, et un enfant de sa vieillesse, [encore] jeune; et son frère est mort, et il reste seul de sa mère, et son père l’aime.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Et tu as dit à tes serviteurs: Faites-le descendre vers moi, afin que je le voie de mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Et nous avons dit à mon seigneur: Le jeune homme ne peut quitter son père; s’il le quitte, son père mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Et tu dis à tes serviteurs: Si votre jeune frère ne descend pas avec vous, vous ne reverrez pas ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Et il est arrivé, quand nous sommes montés vers ton serviteur, mon père, que nous lui avons rapporté les paroles de mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Et notre père dit: Retournez, achetez-nous un peu de vivres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'mais nous avons dit: Nous ne pouvons descendre. Si notre plus jeune frère est avec nous, alors nous descendrons; car nous ne pouvons voir la face de cet homme, si notre plus jeune frère n’est pas avec nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Et ton serviteur, mon père, nous dit: Vous savez que ma femme m’a enfanté deux [fils];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'et l’un s’en est allé d’avec moi, et j’ai dit: Certainement il a été déchiré; et je ne l’ai pas revu jusqu’à présent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Et si vous prenez aussi celui-ci de devant moi, et qu’un accident lui arrive, vous ferez descendre mes cheveux blancs avec tristesse au shéol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Et maintenant, si je viens vers ton serviteur, mon père, et que le jeune homme à l’âme duquel son âme est étroitement liée ne soit pas avec nous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'il arrivera qu’il mourra en voyant que le jeune homme n’y est pas; et tes serviteurs feront descendre les cheveux blancs de ton serviteur, notre père, avec douleur au shéol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Car ton serviteur a répondu du jeune homme auprès de mon père, en disant: Si je ne te le ramène, je serai coupable envers mon père tous mes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Et maintenant, que ton serviteur, je te prie, reste serviteur de mon seigneur, à la place du jeune homme, et le jeune homme montera avec ses frères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'car comment monterai-je vers mon père, si le jeune homme n’est pas avec moi? – de peur que je ne voie le malheur qui atteindrait mon père!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Et Joseph ne put plus se contenir devant tous ceux qui se tenaient près de lui, et il cria: Faites sortir tout le monde d’auprès de moi. Et personne ne se tint près de Joseph quand il se fit connaître à ses frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Et il laissa éclater sa voix en pleurs, et les Égyptiens l’entendirent, et la maison du Pharaon l’entendit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Et Joseph dit à ses frères: Je suis Joseph. Mon père vit-il encore? Et ses frères ne pouvaient lui répondre, car ils étaient troublés devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Et Joseph dit à ses frères: Approchez-vous de moi. Et ils s’approchèrent. Et il dit: Je suis Joseph, votre frère, que vous avez vendu pour l’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Et maintenant, ne soyez pas attristés, et ne voyez pas d’un œil chagrin que vous m’ayez vendu ici, car c’est pour la conservation de la vie que Dieu m’a envoyé devant vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Car voici deux ans que la famine est dans le pays, et il y a encore cinq ans, pendant lesquels il n’y aura ni labour, ni moisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Et Dieu m’a envoyé devant vous pour vous conserver de reste sur la terre, et pour vous conserver la vie par une grande délivrance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Et maintenant, ce n’est pas vous qui m’avez envoyé ici, mais c’est Dieu; et il m’a établi père du Pharaon, et seigneur de toute sa maison, et gouverneur sur tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Hâtez-vous, et montez vers mon père, et vous lui direz: Ainsi dit ton fils, Joseph: Dieu m’a établi seigneur de toute l’Égypte; descends vers moi, ne t’arrête pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Et tu habiteras dans le pays de Goshen, et tu seras près de moi, toi, et tes fils, et les fils de tes fils, et ton menu et ton gros bétail, et tout ce qui est à toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'et je t’y entretiendrai, car il y a encore cinq années de famine, de peur que tu ne sois réduit à la misère, toi, et ta maison, et tout ce qui est à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Et voici, vos yeux, et les yeux de Benjamin, mon frère, voient que c’est ma bouche qui vous parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Et vous raconterez à mon père toute ma gloire en Égypte, et tout ce que vous avez vu; et vous vous hâterez, et vous ferez descendre ici mon père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Et il se jeta au cou de Benjamin, son frère, et pleura; et Benjamin pleura sur son cou;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'et il embrassa tous ses frères, et pleura sur eux; et après cela, ses frères parlèrent avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Et la rumeur en arriva dans la maison du Pharaon, disant: Les frères de Joseph sont venus. Et cela fut bon aux yeux du Pharaon et aux yeux de ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Et le Pharaon dit à Joseph: Dis à tes frères: Faites ceci; chargez vos bêtes, et allez, entrez au pays de Canaan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'et prenez votre père et vos familles, et venez vers moi; et je vous donnerai ce qu’il y a de meilleur au pays d’Égypte, et vous mangerez la graisse du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Et à toi, il t’est ordonné: Faites ceci; prenez du pays d’Égypte des chariots pour vos petits enfants et pour vos femmes, et faites-y monter votre père, et venez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Que vos yeux ne regrettent pas vos meubles; car le meilleur de tout le pays d’Égypte sera à vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Et les fils d’Israël firent ainsi; et Joseph leur donna des chariots, selon le commandement du Pharaon; et il leur donna des provisions pour le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Il donna à chacun d’eux tous des vêtements de rechange; et à Benjamin il donna 300 [pièces] d’argent, et cinq vêtements de rechange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Et à son père il envoya ceci: dix ânes chargés de ce qu’il y avait de meilleur en Égypte, et dix ânesses chargées de blé, et de pain, et de vivres pour son père, pour le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Et il renvoya ses frères, et ils s’en allèrent. Et il leur dit: Ne vous querellez pas en chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Et ils montèrent de l’Égypte, et vinrent au pays de Canaan, vers Jacob, leur père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'et ils lui rapportèrent, disant: Joseph vit encore; et même c’est lui qui gouverne tout le pays d’Égypte. Mais son cœur resta froid, car il ne les crut pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Et ils lui dirent toutes les paroles de Joseph, qu’il leur avait dites; et il vit les chariots que Joseph avait envoyés pour le transporter; et l’esprit de Jacob leur père se ranima.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Et Israël dit: C’est assez! Joseph mon fils vit encore; j’irai, et je le verrai avant que je meure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Et Israël partit, et tout ce qui était à lui; et il vint à Beër-Shéba, et offrit des sacrifices au Dieu de son père Isaac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Et Dieu parla à Israël dans les visions de la nuit, et il dit: Jacob! Jacob! Et il dit: Me voici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Et il dit: Moi, je suis ✶Dieu, le Dieu de ton père: ne crains pas de descendre en Égypte; car je t’y ferai devenir une grande nation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Moi, je descendrai avec toi en Égypte, et moi je t’en ferai aussi certainement remonter; et Joseph mettra sa main sur tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Et Jacob se leva de Beër-Shéba; et les fils d’Israël firent monter Jacob, leur père, et leurs petits enfants, et leurs femmes, sur les chariots que le Pharaon avait envoyés pour le transporter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Et ils prirent leur bétail, et leur bien, qu’ils avaient acquis dans le pays de Canaan, et vinrent en Égypte, Jacob, et toute sa descendance avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'il amena avec lui en Égypte ses fils et les fils de ses fils, ses filles et les filles de ses fils, et toute sa descendance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Et ce sont ici les noms des fils d’Israël qui vinrent en Égypte: Jacob et ses enfants. Le premier-né de Jacob: Ruben.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Et les fils de Ruben: Hénoc, Pallu, et Hetsron, et Carmi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, '– Et les fils de Siméon: Jemuel, et Jamin, et Ohad, et Jakin, et Tsokhar, et Saül, fils d’une Cananéenne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, '– Et les fils de Lévi: Guershon, Kehath, et Merari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, '– Et les fils de Juda: Er, et Onan, et Shéla, et Pérets, et Zérakh; et Er et Onan moururent dans le pays de Canaan. Et les fils de Pérets furent Hetsron et Hamul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, '– Et les fils d’Issacar: Thola, et Puva, et Job, et Shimron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, '– Et les fils de Zabulon: Séred, et Élon, et Jakhleël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, '– Ce sont là les fils de Léa, qu’elle enfanta à Jacob à Paddan-Aram, et Dina, sa fille; toutes les âmes, ses fils et ses filles, 33.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Et les fils de Gad: Tsiphion, et Haggui, Shuni, et Etsbon, Éri, et Arodi, et Areéli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, '– Et les fils d’Aser: Jimna, et Jishva, et Jishvi, et Beriha, et Sérakh, leur sœur. Et les fils de Beriha: Héber et Malkiel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, '– Ce sont là les fils de Zilpa, que Laban donna à Léa, sa fille; et elle enfanta ceux-là à Jacob, 16 âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Les fils de Rachel, femme de Jacob: Joseph et Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Et il naquit à Joseph, dans le pays d’Égypte, Manassé et Éphraïm, que lui enfanta Asnath, fille de Poti-Phéra, sacrificateur d’On.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, '– Et les fils de Benjamin: Béla, et Béker, et Ashbel, Guéra, et Naaman, Ékhi, et Rosh, Muppim, et Huppim, et Ard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, '– Ce sont là les fils de Rachel, qui naquirent à Jacob; toutes les âmes, 14.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Et les fils de Dan: Hushim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, '– Et les fils de Nephthali: Jahtseël, et Guni, et Jétser, et Shillem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, '– Ce sont là les fils de Bilha, que Laban donna à Rachel sa fille; et elle enfanta ceux-là à Jacob; toutes les âmes, sept.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Tous ceux qui vinrent en Égypte, appartenant à Jacob, issus de ses reins, outre les femmes des fils de Jacob, toutes les âmes, 66.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Et les fils de Joseph qui lui étaient nés en Égypte, deux âmes. Toutes les âmes de la maison de Jacob qui vinrent en Égypte furent 70.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Et [Jacob] envoya Juda devant lui vers Joseph, pour qu’il prépare le chemin devant lui en Goshen. Et ils vinrent dans le pays de Goshen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Et Joseph attela son char, et monta à la rencontre d’Israël, son père, en Goshen. Et il se montra à lui, et se jeta à son cou, et pleura longtemps sur son cou.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Et Israël dit à Joseph: Que je meure à présent, après que j’ai vu ton visage, puisque tu vis encore.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, '*Et Joseph dit à ses frères, et à la maison de son père: Je monterai, et je rapporterai au Pharaon, et je lui dirai: Mes frères, et la maison de mon père, qui étaient dans le pays de Canaan, sont venus vers moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'et ces hommes sont bergers, car ils s’occupent de bétail, et ils ont amené leur menu et leur gros bétail, et tout ce qui est à eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Et il arrivera que lorsque le Pharaon vous appellera et vous dira: Quelle est votre occupation?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'vous direz: Tes serviteurs se sont occupés de bétail, dès notre jeunesse jusqu’à maintenant, tant nous que nos pères; afin que vous habitiez dans le pays de Goshen: car tous les bergers sont une abomination pour les Égyptiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Et Joseph entra, et rapporta au Pharaon, et dit: Mon père et mes frères, et leur menu et leur gros bétail, et tout ce qui est à eux, sont venus du pays de Canaan; et voici, ils sont dans le pays de Goshen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Et, d’entre ses frères, il prit cinq hommes, et les présenta au Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Et le Pharaon dit à ses frères: Quelle est votre occupation? Et ils dirent au Pharaon: Tes serviteurs sont bergers, tant nous que nos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Et ils dirent au Pharaon: Nous sommes venus pour séjourner dans le pays, parce qu’il n’y a point de pâture pour le bétail de tes serviteurs, car la famine pèse sur le pays de Canaan; et maintenant, que tes serviteurs, nous t’en prions, habitent dans le pays de Goshen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Et le Pharaon parla à Joseph, disant: Ton père et tes frères sont venus vers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Le pays d’Égypte est devant toi; fais habiter ton père et tes frères dans la meilleure partie du pays: qu’ils demeurent dans le pays de Goshen; et si tu connais qu’il y ait parmi eux des hommes capables, tu les établiras chefs des troupeaux qui sont à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Et Joseph fit entrer Jacob, son père, et le fit se tenir devant le Pharaon; et Jacob bénit le Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Et le Pharaon dit à Jacob: Combien sont les jours des années de ta vie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Et Jacob dit au Pharaon: Les jours des années de mon séjournement sont 130 ans; les jours des années de ma vie ont été courts et mauvais, et ils n’ont pas atteint les jours des années de la vie de mes pères, dans les jours de leur séjournement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Et Jacob bénit le Pharaon, et sortit de devant le Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Et Joseph assigna une demeure à son père et à ses frères, et leur donna une possession dans le pays d’Égypte, dans la meilleure partie du pays, dans le pays de Ramsès, comme le Pharaon l’avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Et Joseph fournit de pain son père et ses frères, et toute la maison de son père, selon le nombre des enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, '*Et il n’y avait pas de pain dans tout le pays, car la famine était très intense; et le pays d’Égypte et le pays de Canaan étaient épuisés à cause de la famine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Et Joseph recueillit tout l’argent qui se trouva dans le pays d’Égypte et dans le pays de Canaan, pour le blé qu’on achetait; et Joseph fit entrer l’argent dans la maison du Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Et quand l’argent du pays d’Égypte et du pays de Canaan fut épuisé, tous les Égyptiens vinrent à Joseph, disant: Donne-nous du pain; et pourquoi mourrions-nous devant toi, car l’argent manque?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Et Joseph dit: Donnez votre bétail, et je vous donnerai [du pain] contre votre bétail, si l’argent vous manque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Et ils amenèrent leur bétail à Joseph; et Joseph leur donna du pain contre des chevaux, et contre des troupeaux de menu bétail, et contre des troupeaux de gros bétail, et contre des ânes: et il les fournit de pain cette année-là contre tous leurs troupeaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Et cette année-là finit; et ils vinrent à lui la seconde année, et lui dirent: Nous ne cacherons pas à mon seigneur que l’argent est épuisé, et mon seigneur a les troupeaux de bétail: il ne reste rien devant mon seigneur que nos corps et nos terres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Pourquoi mourrions-nous devant tes yeux, tant nous que nos terres? Achète-nous, et nos terres, contre du pain; et nous serons, nous et nos terres, serviteurs du Pharaon. Et donne-nous de la semence, afin que nous vivions et ne mourions pas, et que la terre ne soit pas désolée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Et Joseph acheta tout le sol de l’Égypte pour le Pharaon: car les Égyptiens vendirent chacun son champ, parce que la famine les pressait; et la terre fut au Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Et quant au peuple, il le fit passer dans les villes, d’un bout des limites de l’Égypte jusqu’à l’autre bout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Seulement il n’acheta pas les terres des sacrificateurs, car il y avait de la part du Pharaon une portion assignée pour les sacrificateurs; et ils mangeaient leur portion assignée que le Pharaon leur donnait; c’est pourquoi ils ne vendirent pas leurs terres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Et Joseph dit au peuple: Voici, je vous ai achetés aujourd’hui, et vos terres, pour le Pharaon. Voici de la semence pour vous: ensemencez la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Et il arrivera, lors des récoltes, que vous donnerez le cinquième au Pharaon, et les quatre [autres] parties seront pour vous, pour la semence des champs, et pour votre nourriture, et pour ceux qui sont dans vos maisons, et pour la nourriture de vos petits enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Et ils dirent: Tu nous as conservé la vie; que nous trouvions grâce aux yeux de mon seigneur, et nous serons serviteurs du Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Et Joseph en fit une loi, jusqu’à ce jour, sur les terres de l’Égypte: au Pharaon un cinquième. Seulement, les terres des sacrificateurs seuls ne furent pas au Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, '*Et Israël habita dans le pays d’Égypte, dans le pays de Goshen; et ils y acquirent des possessions, et fructifièrent, et multiplièrent extrêmement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Et Jacob vécut dans le pays d’Égypte 17 ans; et les jours de Jacob, les années de sa vie, furent 147 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Et les jours d’Israël s’approchèrent de la mort. Et il appela Joseph, son fils, et lui dit: Si j’ai trouvé grâce à tes yeux, mets, je te prie, ta main sous ma cuisse, et use envers moi de bonté et de vérité: ne m’enterre pas, je te prie, en Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'mais quand je serai couché avec mes pères, tu m’emporteras d’Égypte, et tu m’enterreras dans leur sépulcre. Et il dit: Je ferai selon ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Et [Jacob] dit: Jure-le-moi. Et il le lui jura. Et Israël se prosterna sur le chevet du lit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, '*Et il arriva après ces choses, qu’on dit à Joseph: Voici, ton père est malade. Et il prit avec lui ses deux fils, Manassé et Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Et on avertit Jacob, et on dit: Voici, ton fils Joseph vient vers toi. Et Israël rassembla ses forces, et s’assit sur le lit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Et Jacob dit à Joseph: Le ✶Dieu Tout-puissant m’est apparu à Luz, dans le pays de Canaan, et il m’a béni,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'et m’a dit: Voici, je te ferai fructifier et je te multiplierai, et je te ferai devenir une assemblée de peuples, et je donnerai ce pays à ta semence, après toi, en possession perpétuelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Et maintenant, tes deux fils qui te sont nés dans le pays d’Égypte, avant que je vienne vers toi en Égypte, sont à moi: Éphraïm et Manassé sont à moi comme Ruben et Siméon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Et tes enfants que tu as engendrés après eux seront à toi; ils seront appelés d’après le nom de leurs frères, dans leur héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Et moi,... comme je venais de Paddan, Rachel mourut auprès de moi, dans le pays de Canaan, en chemin, comme il y avait encore quelque espace de pays pour arriver à Éphrath; et je l’enterrai là, sur le chemin d’Éphrath, qui est Bethléhem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Et Israël vit les fils de Joseph, et il dit: Qui sont ceux-ci?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Et Joseph dit à son père: Ce sont mes fils, que Dieu m’a donnés ici. Et il dit: Amène-les-moi, je te prie, et je les bénirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Or les yeux d’Israël étaient appesantis de vieillesse; il ne pouvait voir. Et [Joseph] les fit approcher de lui, et il leur donna un baiser et les embrassa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Et Israël dit à Joseph: Je n’avais pas pensé voir ton visage; et voici, Dieu m’a fait voir aussi ta semence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Et Joseph les retira d’entre ses genoux, et se prosterna le visage contre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Et Joseph les prit les deux, Éphraïm de sa main droite, à la gauche d’Israël, et Manassé de sa main gauche, à la droite d’Israël, et les fit approcher de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'mais Israël étendit sa main droite, et la posa sur la tête d’Éphraïm (or il était le plus jeune), et sa main gauche sur la tête de Manassé, plaçant ainsi ses mains à dessein, car Manassé était le premier-né.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Et il bénit Joseph, et dit: Que le Dieu devant la face duquel ont marché mes pères, Abraham et Isaac, le Dieu qui a été mon berger depuis que je suis jusqu’à ce jour,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'l’Ange qui m’a délivré de tout mal, bénisse ces jeunes hommes; et qu’ils soient appelés de mon nom et du nom de mes pères, Abraham et Isaac, et qu’ils croissent pour être une multitude au milieu du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Et Joseph vit que son père posait sa main droite sur la tête d’Éphraïm, et cela fut mauvais à ses yeux; et il saisit la main de son père pour la détourner de dessus la tête d’Éphraïm [et la poser] sur la tête de Manassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Et Joseph dit à son père: Pas ainsi, mon père; car celui-ci est le premier-né; mets ta main droite sur sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Et son père refusa, disant: Je le sais, mon fils, je le sais; lui aussi deviendra un peuple, et lui aussi sera grand; toutefois son frère, qui est le plus jeune, sera plus grand que lui, et sa semence sera une plénitude de nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Et il les bénit ce jour-là, disant: En toi Israël bénira, disant: Dieu te rende tel qu’Éphraïm et que Manassé! Et il mit Éphraïm avant Manassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Et Israël dit à Joseph: Voici, je meurs; et Dieu sera avec vous, et vous fera retourner dans le pays de vos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Et moi, je te donne, de plus qu’à tes frères, une portion que j’ai prise de la main de l’Amoréen avec mon épée et mon arc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, '*Et Jacob appela ses fils, et dit: Assemblez-vous, et je vous ferai savoir ce qui vous arrivera à la fin des jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Réunissez-vous, et écoutez, fils de Jacob; écoutez Israël, votre père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, tu es mon premier-né, ma force, et le commencement de ma vigueur, prééminent en dignité, et prééminent en force!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Bouillonnant comme les eaux, tu n’excelleras pas, car tu es monté sur la couche de ton père; tu l’as alors profanée... Il est monté sur mon lit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Siméon et Lévi sont frères. Leurs glaives ont été des instruments de violence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Mon âme, n’entre pas dans leur conseil secret; ma gloire, ne t’unis pas à leur assemblée! Car dans leur colère ils ont tué des hommes, et pour leur plaisir ils ont coupé les jarrets du taureau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Maudite soit leur colère, car elle a été violente; et leur furie, car elle a été cruelle! Je les diviserai en Jacob, et les disperserai en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Toi, Juda, tes frères te loueront; ta main sera sur la nuque de tes ennemis; les fils de ton père se prosterneront devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juda est un jeune lion. Tu es monté d’auprès de la proie, mon fils. Il se courbe, il se couche comme un lion, et comme une lionne; qui le fera lever?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Le sceptre ne se retirera point de Juda, ni un législateur d’entre ses pieds, jusqu’à ce que Shilo vienne; et à lui sera l’obéissance des peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Il attache à la vigne son ânon, et au cep excellent le petit de son ânesse; il lave dans le vin son vêtement, et dans le sang des raisins son manteau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Ses yeux sont rouges de vin, et ses dents blanches de lait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zabulon logera sur la côte des mers, et sera sur la côte des navires; et son côté sera près de Sidon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issacar est un âne ossu, couché entre deux parcs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Il voit que le repos est bon, et que le pays est agréable, et il incline son épaule pour porter, et s’assujettit au tribut du serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan jugera son peuple, comme une autre des tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan sera un serpent sur le chemin, une vipère sur le sentier, qui mord les talons du cheval, et celui qui le monte tombe à la renverse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'J’ai attendu ton salut, ô Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad, une troupe lui tombera dessus; et lui, il leur tombera sur les talons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'D’Aser [viendra] le pain excellent; et lui, il fournira les délices royales.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Nephthali est une biche lâchée; il profère de belles paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joseph est une branche qui porte du fruit, une branche qui porte du fruit près d’une fontaine; [ses] rameaux poussent par-dessus la muraille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Les archers l’ont provoqué amèrement, et ont tiré contre lui, et l’ont haï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Mais son arc est demeuré ferme, et les bras de ses mains sont souples par les mains du Puissant de Jacob. De là est le berger, la pierre d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'du ✶Dieu de ton père, et il t’aidera; et du Tout-puissant, et il te bénira des bénédictions des cieux en haut, des bénédictions de l’abîme qui est en bas, des bénédictions des mamelles et de la matrice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Les bénédictions de ton père surpassent les bénédictions de mes ancêtres jusqu’au bout des collines éternelles; elles seront sur la tête de Joseph, et sur le sommet de la tête de celui qui a été mis à part de ses frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin est un loup qui déchire: le matin, il dévore la proie, et le soir, il partage le butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Tous ceux-là sont les douze tribus d’Israël, et c’est là ce que leur père leur dit en les bénissant: il les bénit, chacun selon sa bénédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Et il leur commanda, et leur dit: Je suis recueilli vers mon peuple; enterrez-moi auprès de mes pères, dans la caverne qui est dans le champ d’Éphron, le Héthien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'dans la caverne qui est dans le champ de Macpéla, qui est en face de Mamré, au pays de Canaan, et qu’Abraham acheta d’Éphron, le Héthien, avec le champ, pour la posséder comme sépulcre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'là on a enterré Abraham et Sara, sa femme; là on a enterré Isaac et Rebecca, sa femme; et là j’ai enterré Léa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'L’acquisition du champ et de la caverne qui y est [fut faite] des fils de Heth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Et quand Jacob eut achevé de donner ses commandements à ses fils, il retira ses pieds dans le lit, et expira, et fut recueilli vers ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, '*Et Joseph se jeta sur le visage de son père, et pleura sur lui, et l’embrassa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Et Joseph commanda à ses serviteurs, les médecins, d’embaumer son père; et les médecins embaumèrent Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Et 40 jours s’accomplirent pour lui; car ainsi s’accomplissaient les jours de l’embaumement. Et les Égyptiens le pleurèrent 70 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Et les jours où on le pleura étant passés, Joseph parla à la maison du Pharaon, disant: Si j’ai trouvé grâce à vos yeux, parlez, je vous prie, aux oreilles du Pharaon, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mon père m’a fait jurer, disant: Voici, je meurs; dans le sépulcre que je me suis taillé dans le pays de Canaan, là tu m’enterreras. Et maintenant, permets que je monte, et que j’enterre mon père; et je reviendrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Et le Pharaon dit: Monte, et enterre ton père, comme il t’a fait jurer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Et Joseph monta pour enterrer son père; et tous les serviteurs du Pharaon, les anciens de sa maison, et tous les anciens du pays d’Égypte, montèrent avec lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'et toute la maison de Joseph, et ses frères, et la maison de son père; seulement ils laissèrent leurs petits enfants, et leur menu et leur gros bétail dans le pays de Goshen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Et avec lui montèrent aussi des chariots et des cavaliers; et il y eut un très gros camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Et ils vinrent à l’aire d’Atad, qui est au-delà du Jourdain, et ils s’y lamentèrent de grandes et profondes lamentations; et [Joseph] fit à son père un deuil de sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Et les habitants du pays, les Cananéens, virent le deuil dans l’aire d’Atad, et ils dirent: C’est ici un grand deuil pour les Égyptiens. C’est pourquoi on appela son nom Abel-Mitsraïm, – qui est au-delà du Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Et les fils de Jacob firent pour lui comme il leur avait commandé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'et ses fils le transportèrent dans le pays de Canaan, et l’enterrèrent dans la caverne du champ de Macpéla, qu’Abraham avait achetée d’Éphron, le Héthien, avec le champ, en face de Mamré, pour la posséder comme sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Et Joseph, après qu’il eut enterré son père, retourna en Égypte, lui et ses frères, et tous ceux qui étaient montés avec lui pour enterrer son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Et les frères de Joseph virent que leur père était mort, et ils dirent: Peut-être Joseph nous haïra-t-il, et ne manquera-t-il pas de nous rendre tout le mal que nous lui avons fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Et ils firent dire à Joseph, disant: Ton père a commandé avant sa mort, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Vous direz ainsi à Joseph: Pardonne, je te prie, la transgression de tes frères, et leur péché; car ils t’ont fait du mal. Et maintenant, pardonne, nous te prions, la transgression des serviteurs du Dieu de ton père. Et Joseph pleura quand ils lui parlèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Et ses frères aussi allèrent, et tombèrent [sur leurs faces] devant lui, et dirent: Nous voici, nous sommes tes serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Et Joseph leur dit: Ne craignez point; car suis-je à la place de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vous, vous aviez pensé du mal contre moi: Dieu l’a pensé en bien, pour faire comme il en est aujourd’hui, afin de conserver la vie à un grand peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Et maintenant, ne craignez point; moi je vous entretiendrai, vous et vos petits enfants. Et il les consola, et parla à leur cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Et Joseph habita en Égypte, lui et la maison de son père; et Joseph vécut 110 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Et Joseph vit les fils d’Éphraïm de la troisième [génération]; les fils aussi de Makir, fils de Manassé, naquirent sur les genoux de Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Et Joseph dit à ses frères: Je meurs, et Dieu vous visitera certainement, et vous fera monter de ce pays-ci dans le pays qu’il a promis par serment à Abraham, à Isaac et à Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Et Joseph fit jurer les fils d’Israël, disant: Certainement Dieu vous visitera, et vous ferez monter d’ici mes os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Et Joseph mourut, âgé de 110 ans; et on l’embauma, et on le mit dans un cercueil en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Et ce sont ici les noms des fils d’Israël qui entrèrent en Égypte; ils y entrèrent avec Jacob, chacun avec sa famille:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Siméon, Lévi et Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issacar, Zabulon et Benjamin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan et Nephthali; Gad et Aser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Et toutes les âmes issues des reins de Jacob étaient 70 âmes; or Joseph était en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Et Joseph mourut, et tous ses frères, et toute cette génération-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Et les fils d’Israël fructifièrent et foisonnèrent, et multiplièrent, et devinrent extrêmement forts; et le pays en fut rempli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, '*Et un nouveau roi se leva sur l’Égypte, qui n’avait point connu Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Et il dit à son peuple: Voici, le peuple des fils d’Israël est plus nombreux et plus fort que nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Allons, soyons prudents à son égard, de peur qu’il ne se multiplie, et que, s’il arrivait une guerre, il ne se joigne, lui aussi, à nos ennemis, et ne fasse la guerre contre nous, et ne monte hors du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Et ils établirent sur lui des chefs de corvées pour l’opprimer par leurs fardeaux. Et il bâtit pour le Pharaon des villes à greniers, Pithom et Ramsès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Et selon qu’ils l’opprimaient, il multipliait et croissait; et ils eurent peur des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Et les Égyptiens firent servir les fils d’Israël avec dureté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'et ils leur rendirent la vie amère par un dur service, en argile, et en briques, et par toute sorte de service aux champs: tout le service dans lequel on les faisait servir était avec dureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Et le roi d’Égypte parla aux sages-femmes hébreues, dont l’une avait nom Shiphra et la seconde se nommait Pua,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'et il dit: Quand vous accoucherez les femmes hébreues et que vous les verrez sur les sièges, si c’est un fils, vous le ferez mourir, et si c’est une fille, elle vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mais les sages-femmes craignirent Dieu, et ne firent pas comme le roi d’Égypte leur avait dit; et elles laissèrent vivre les enfants mâles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Et le roi d’Égypte appela les sages-femmes, et leur dit: Pourquoi avez-vous fait cela, et avez-vous laissé vivre les enfants mâles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Et les sages-femmes dirent au Pharaon: Parce que les femmes hébreues ne sont pas comme les Égyptiennes; car elles sont vigoureuses: avant que la sage-femme vienne vers elles, elles ont enfanté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Et Dieu fit du bien aux sages-femmes; et le peuple multiplia, et devint très fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Et il arriva, parce que les sages-femmes craignirent Dieu, qu’il leur fit des maisons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Et le Pharaon commanda à tout son peuple, disant: Tout fils qui naîtra, jetez-le dans le fleuve; mais toute fille, laissez-la vivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, '*Et un homme de la maison de Lévi alla, et prit une fille de Lévi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'et la femme conçut, et enfanta un fils; et elle vit qu’il était beau; et elle le cacha trois mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Et comme elle ne pouvait plus le cacher, elle prit pour lui un coffret de joncs, et l’enduisit de bitume et de poix, et mit dedans l’enfant, et le posa parmi les roseaux sur le bord du fleuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Et sa sœur se tint à distance pour savoir ce qu’on lui ferait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Et la fille du Pharaon descendit au fleuve pour se laver, et ses jeunes filles se promenaient sur le bord du fleuve; et elle vit le coffret au milieu des roseaux, et elle envoya sa servante, qui le prit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'et elle l’ouvrit, et vit l’enfant; et voici, c’était un petit garçon qui pleurait. Et elle eut compassion de lui, et dit: C’est un des enfants des Hébreux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Et sa sœur dit à la fille du Pharaon: Irai-je et appellerai-je auprès de toi une nourrice d’entre les Hébreues, et elle t’allaitera l’enfant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Et la fille du Pharaon lui dit: Va. Et la jeune fille alla, et appela la mère de l’enfant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Et la fille du Pharaon lui dit: Emporte cet enfant, et allaite-le pour moi, et je te donnerai ton salaire. Et la femme prit l’enfant, et l’allaita.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Et l’enfant grandit, et elle l’amena à la fille du Pharaon, et il fut son fils; et elle appela son nom Moïse, et dit: Car je l’ai tiré des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Et il arriva, en ces jours-là, que Moïse, étant devenu grand, sortit vers ses frères; et il vit leurs fardeaux. Et il vit un homme égyptien qui frappait un Hébreu d’entre ses frères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'et il regarda çà et là, et vit qu’il n’y avait personne, et il frappa l’Égyptien, et le cacha dans le sable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Et il sortit le second jour; et voici, deux hommes hébreux se querellaient. Et il dit au coupable: Pourquoi frappes-tu ton compagnon?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Et il dit: Qui t’a établi chef et juge sur nous? Est-ce que tu veux me tuer, comme tu as tué l’Égyptien? Et Moïse eut peur, et dit: Certainement le fait est connu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Et le Pharaon apprit la chose, et chercha à tuer Moïse; mais Moïse s’enfuit de devant le Pharaon, et habita dans le pays de Madian. Et il s’assit près d’un puits;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'or le sacrificateur de Madian avait sept filles; et elles vinrent, et puisèrent, et emplirent les auges pour abreuver le bétail de leur père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Et les bergers vinrent, et les chassèrent; et Moïse se leva, et les secourut, et abreuva leur bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Et elles vinrent vers Rehuel, leur père; et il dit: Pourquoi êtes-vous venues sitôt aujourd’hui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Et elles dirent: Un homme égyptien nous a délivrées de la main des bergers, et il a aussi puisé abondamment pour nous, et a abreuvé le bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Et il dit à ses filles: Où est-il donc? Pourquoi avez-vous laissé là cet homme? Appelez-le, et qu’il mange du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Et Moïse consentit à habiter avec lui; et il donna Séphora, sa fille, à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Et elle enfanta un fils, et il appela son nom Guershom; car, dit-il, j’ai séjourné dans un pays étranger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, '*Et il arriva en ces jours, qui furent nombreux, que le roi d’Égypte mourut; et les fils d’Israël soupirèrent à cause de leur service, et ils crièrent; et leur cri monta vers Dieu à cause de leur service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Et Dieu entendit leur gémissement, et Dieu se souvint de son alliance avec Abraham, avec Isaac, et avec Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Et Dieu regarda les fils d’Israël, et Dieu connut [leur état].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Et Moïse faisait paître le bétail de Jéthro, son beau-père, sacrificateur de Madian. Et il mena le troupeau derrière le désert, et il vint à la montagne de Dieu, à Horeb.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Et l’Ange de l’ Éternel lui apparut dans une flamme de feu, du milieu d’un buisson à épines; et il regarda, et voici, le buisson était [tout] ardent de feu, et le buisson n’était pas consumé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Et Moïse dit: Je me détournerai, et je verrai cette grande vision, pourquoi le buisson ne se consume pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Et l’ Éternel vit qu’il se détournait pour voir; et Dieu l’appela du milieu du buisson, et dit: Moïse! Moïse! Et il dit: Me voici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Et il dit: N’approche pas d’ici; ôte tes sandales de tes pieds, car le lieu sur lequel tu te tiens est une terre sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Et il dit: Je suis le Dieu de ton père, le Dieu d’Abraham, le Dieu d’Isaac, et le Dieu de Jacob. Et Moïse cacha son visage, car il craignait de regarder vers Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Et l’ Éternel dit: J’ai vu, j’ai vu l’affliction de mon peuple qui est en Égypte, et j’ai entendu le cri qu’il a jeté à cause de ses exacteurs; car je connais ses douleurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Et je suis descendu pour le délivrer de la main des Égyptiens, et pour le faire monter de ce pays-là dans un pays bon et spacieux, dans un pays ruisselant de lait et de miel, dans le lieu d’habitation du Cananéen, et du Héthien, et de l’Amoréen, et du Phérézien, et du Hévien, et du Jébusien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Et maintenant, voici, le cri des fils d’Israël est venu jusqu’à moi; et j’ai aussi vu l’oppression dont les Égyptiens les oppriment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Et maintenant, viens, et je t’enverrai vers le Pharaon, et tu feras sortir hors d’Égypte mon peuple, les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Et Moïse dit à Dieu: Qui suis-je, moi, pour que j’aille vers le Pharaon, et pour que je fasse sortir hors d’Égypte les fils d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Et il dit: Parce que je serai avec toi; et ceci te sera le signe que c’est moi qui t’ai envoyé: lorsque tu auras fait sortir le peuple hors d’Égypte, vous servirez Dieu sur cette montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Et Moïse dit à Dieu: Voici, quand je viendrai vers les fils d’Israël, et que je leur dirai: Le Dieu de vos pères m’a envoyé vers vous, et qu’ils me diront: Quel est son nom? que leur dirai-je?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Et Dieu dit à Moïse: Je suis celui qui suis. Et il dit: Tu diras ainsi aux fils d’Israël: Je suis m’a envoyé vers vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Et Dieu dit encore à Moïse: Tu diras ainsi aux fils d’Israël: L’ Éternel, le Dieu de vos pères, le Dieu d’Abraham, le Dieu d’Isaac, et le Dieu de Jacob, m’a envoyé vers vous: c’est là mon nom éternellement, et c’est là mon mémorial de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Va, et assemble les anciens d’Israël, et dis-leur: L’ Éternel, le Dieu de vos pères, m’est apparu, le Dieu d’Abraham, d’Isaac, et de Jacob, disant: Certainement je vous ai visités, et [j’ai vu] ce qu’on vous fait en Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'et j’ai dit: Je vous ferai monter hors de l’affliction de l’Égypte, dans le pays du Cananéen, et du Héthien, et de l’Amoréen, et du Phérézien, et du Hévien, et du Jébusien, dans un pays ruisselant de lait et de miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Et ils écouteront ta voix, et tu entreras, toi et les anciens d’Israël, vers le roi d’Égypte, et vous lui direz: L’ Éternel, le Dieu des Hébreux, s’est rencontré avec nous; et maintenant, nous te prions, laisse-nous aller le chemin de trois jours dans le désert, afin que nous sacrifiions à l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Et je sais que le roi d’Égypte ne vous permettra pas de vous en aller, pas même [contraint] par main forte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Et j’étendrai ma main, et je frapperai l’Égypte par toutes mes merveilles que je ferai au milieu d’elle; et après cela il vous renverra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Et je ferai trouver faveur à ce peuple aux yeux des Égyptiens, et il arrivera que, quand vous vous en irez, vous ne vous en irez pas à vide;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'et une femme demandera à sa voisine, et à celle qui séjourne dans sa maison, des objets d’argent, et des objets d’or, et des vêtements, et vous les mettrez sur vos fils et sur vos filles; et vous dépouillerez les Égyptiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Et Moïse répondit, et dit: Mais voici, ils ne me croiront pas, et n’écouteront pas ma voix; car ils diront: L’ Éternel ne t’est point apparu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Et l’ Éternel lui dit: Qu’est-ce [que tu as] dans ta main? Et il dit: Une verge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Et il dit: Jette-la à terre. Et il la jeta à terre, et elle devint un serpent; et Moïse fuyait devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Et l’ Éternel dit à Moïse: Étends ta main, et saisis-le par la queue (et il étendit sa main, et le saisit, et il devint une verge dans sa main),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'afin qu’ils croient que l’ Éternel, le Dieu de leurs pères, le Dieu d’Abraham, le Dieu d’Isaac, et le Dieu de Jacob, t’est apparu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Et l’ Éternel lui dit encore: Mets maintenant ta main dans ton sein. Et il mit sa main dans son sein; et il la retira, et voici, sa main était lépreuse, [blanche] comme neige.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Et il dit: Remets ta main dans ton sein. Et il remit sa main dans son sein; et il la retira de son sein, et voici, elle était redevenue comme sa chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Et il arrivera que, s’ils ne te croient pas et n’écoutent pas la voix du premier signe, ils croiront la voix de l’autre signe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Et il arrivera que, s’ils ne croient pas même à ces deux signes, et n’écoutent pas ta voix, tu prendras de l’eau du fleuve et tu la verseras sur le sec; et l’eau que tu auras prise du fleuve deviendra du sang sur le sec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Et Moïse dit à l’ Éternel: Ah, Seigneur! je ne suis pas un homme éloquent, – ni d’hier, ni d’avant-hier, ni depuis que tu parles à ton serviteur; car j’ai la bouche pesante et la langue pesante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Et l’ Éternel lui dit: Qui est-ce qui a donné une bouche à l’homme? ou qui a fait le muet, ou le sourd, ou le voyant, ou l’aveugle? N’est-ce pas moi, l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Et maintenant, va, et je serai avec ta bouche, et je t’enseignerai ce que tu diras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Et il dit: Ah, Seigneur! envoie, je te prie, par celui que tu enverras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Alors la colère de l’ Éternel s’embrasa contre Moïse, et il dit: Aaron, le Lévite, n’est-il pas ton frère? Je sais qu’il parlera très bien; et aussi le voici qui sort à ta rencontre, et quand il te verra, il se réjouira dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Et tu lui parleras, et tu mettras les paroles dans sa bouche; et moi, je serai avec ta bouche et avec sa bouche, et je vous enseignerai ce que vous ferez;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'et il parlera pour toi au peuple, et il arrivera qu’il te sera en la place de bouche, et toi, tu lui seras en la place de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Et tu prendras dans ta main cette verge, avec laquelle tu feras les signes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Et Moïse s’en alla, et retourna vers Jéthro, son beau-père, et lui dit: Je te prie, laisse-moi m’en aller, et retourner vers mes frères qui sont en Égypte, afin que je voie s’ils vivent encore. Et Jéthro dit à Moïse: Va en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Et l’ Éternel dit à Moïse, en Madian: Va, retourne en Égypte; car tous les hommes qui cherchaient ta vie sont morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Et Moïse prit sa femme et ses fils, et les fit monter sur un âne, et retourna au pays d’Égypte. Et Moïse prit la verge de Dieu dans sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Et l’ Éternel dit à Moïse: Quand tu t’en iras pour retourner en Égypte, vois tous les miracles que j’ai mis dans ta main, et tu les feras devant le Pharaon; et moi, j’endurcirai son cœur, et il ne laissera pas aller le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Et tu diras au Pharaon: Ainsi a dit l’ Éternel: Israël est mon fils, mon premier-né.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Et je te dis: Laisse aller mon fils pour qu’il me serve; et si tu refuses de le laisser aller, voici, je tuerai ton fils, ton premier-né.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Et il arriva, en chemin, dans le caravansérail, que l’ Éternel vint contre lui, et chercha à le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Et Séphora prit une pierre tranchante et coupa le prépuce de son fils, et le jeta à ses pieds, et dit: Certes tu m’es un époux de sang!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Et [l’ Éternel] le laissa. Alors elle dit: Époux de sang! à cause de la circoncision.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Et l’ Éternel dit à Aaron: Va à la rencontre de Moïse, au désert. Et il alla, et le rencontra en la montagne de Dieu, et l’embrassa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Et Moïse raconta à Aaron toutes les paroles de l’ Éternel qui l’avait envoyé, et tous les signes qu’il lui avait commandés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Et Moïse et Aaron allèrent, et assemblèrent tous les anciens des fils d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'et Aaron dit toutes les paroles que l’ Éternel avait dites à Moïse, et fit les signes devant les yeux du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Et le peuple crut; et ils apprirent que l’ Éternel avait visité les fils d’Israël, et qu’il avait vu leur affliction; et ils s’inclinèrent et se prosternèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, '*Et après [cela], Moïse et Aaron allèrent, et dirent au Pharaon: Ainsi dit l’ Éternel, le Dieu d’Israël: Laisse aller mon peuple, afin qu’il me célèbre une fête dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Et le Pharaon dit: Qui est l’ Éternel pour que j’écoute sa voix et que je laisse aller Israël? Je ne connais pas l’ Éternel, et je ne laisserai pas non plus aller Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Et ils dirent: Le Dieu des Hébreux s’est rencontré avec nous. Nous te prions, laisse-nous aller le chemin de trois jours dans le désert, et que nous sacrifiions à l’ Éternel, notre Dieu; de peur qu’il ne se jette sur nous par la peste ou par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Et le roi d’Égypte leur dit: Moïse et Aaron, pourquoi détournez-vous le peuple de son ouvrage? Allez à vos corvées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Et le Pharaon dit: Voici, le peuple du pays est maintenant nombreux, et vous les faites chômer de leurs corvées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Et le Pharaon commanda, ce jour-là, aux exacteurs du peuple et à ses commissaires, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Vous ne continuerez pas à donner de la paille au peuple pour faire des briques, comme auparavant; qu’ils aillent eux-mêmes, et qu’ils se ramassent de la paille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Et vous leur imposerez la quantité de briques qu’ils faisaient auparavant. Vous n’en retrancherez rien, car ils sont paresseux; c’est pourquoi ils crient, disant: Allons, et sacrifions à notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Que le service pèse sur ces hommes, et qu’ils s’y occupent, et ne regardent pas à des paroles de mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Et les exacteurs du peuple et ses commissaires sortirent, et parlèrent au peuple, disant: Ainsi dit le Pharaon: Je ne vous donnerai point de paille;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'allez vous-mêmes, et prenez de la paille où vous en trouverez; car il ne sera rien retranché de votre service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Et le peuple se dispersa dans tout le pays d’Égypte pour ramasser du chaume en lieu de paille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Et les exacteurs les pressaient, disant: Achevez vos ouvrages; à chaque jour sa tâche, comme quand il y avait de la paille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Et les commissaires des fils d’Israël, qu’avaient établis sur eux les exacteurs du Pharaon, furent battus, et il leur fut dit: Pourquoi n’avez-vous pas achevé votre tâche en faisant des briques, hier et aujourd’hui, comme auparavant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Et les commissaires des fils d’Israël vinrent et crièrent au Pharaon, disant: Pourquoi fais-tu ainsi à tes serviteurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'On ne donne point de paille à tes serviteurs, et on nous dit: Faites des briques! Et voici, tes serviteurs sont battus, et c’est ton peuple qui est coupable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Et il dit: Vous êtes paresseux, paresseux; c’est pourquoi vous dites: Allons, et sacrifions à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Et maintenant, allez, travaillez; on ne vous donnera point de paille, et vous livrerez la quantité de briques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Et les commissaires des fils d’Israël virent que leur cas était mauvais, puisqu’on disait: Vous ne retrancherez rien de vos briques; à chaque jour sa tâche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Et ils rencontrèrent Moïse et Aaron, qui se tenaient là pour les rencontrer, comme ils sortaient de devant le Pharaon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'et ils leur dirent: Que l’ Éternel vous regarde, et qu’il juge; car vous nous avez mis en mauvaise odeur auprès du Pharaon et auprès de ses serviteurs, de manière à leur mettre une épée à la main pour nous tuer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Et Moïse retourna vers l’ Éternel, et dit: Seigneur, pourquoi as-tu fait du mal à ce peuple? Pourquoi donc m’as-tu envoyé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Depuis que je suis entré vers le Pharaon pour parler en ton nom, il a fait du mal à ce peuple, et tu n’as pas du tout délivré ton peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Et l’ Éternel dit à Moïse: Tu verras maintenant ce que je ferai au Pharaon, car [contraint] par main forte, il les laissera aller, et [contraint] par main forte, il les chassera de son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Et Dieu parla à Moïse, et lui dit: Je suis l’ Éternel (Jéhovah).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Je suis apparu à Abraham, à Isaac, et à Jacob, comme le ✶Dieu Tout-puissant; mais je n’ai pas été connu d’eux par mon nom d’ Éternel (Jéhovah).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Et j’ai aussi établi mon alliance avec eux, pour leur donner le pays de Canaan, le pays de leur séjournement, dans lequel ils ont séjourné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Et j’ai aussi entendu le gémissement des fils d’Israël, que les Égyptiens font servir, et je me suis souvenu de mon alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'C’est pourquoi dis aux fils d’Israël: Je suis l’ Éternel, et je vous ferai sortir de dessous les fardeaux des Égyptiens, et je vous délivrerai de leur servitude; et je vous rachèterai à bras étendu, et par de grands jugements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'et je vous prendrai pour être mon peuple, et je vous serai Dieu; et vous saurez que je suis l’ Éternel, votre Dieu, qui vous fais sortir de dessous les fardeaux des Égyptiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Et je vous ferai entrer dans le pays au sujet duquel j’ai levé ma main, pour le donner à Abraham, à Isaac, et à Jacob, et je vous le donnerai en possession. Je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Et Moïse parla ainsi aux fils d’Israël; mais ils n’écoutèrent pas Moïse, à cause de leur angoisse d’esprit, et à cause de leur dure servitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Entre, et parle au Pharaon, roi d’Égypte, pour qu’il laisse sortir les fils d’Israël de son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Et Moïse parla devant l’ Éternel, en disant: Voici, les fils d’Israël ne m’ont point écouté; et comment le Pharaon m’écoutera-t-il, moi qui suis incirconcis de lèvres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Et l’ Éternel parla à Moïse et à Aaron, et leur donna des ordres pour les fils d’Israël, et pour le Pharaon, roi d’Égypte, pour faire sortir les fils d’Israël du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Ce sont ici les chefs de leurs maisons de pères: les fils de Ruben, premier-né d’Israël: Hénoc et Pallu, Hetsron et Carmi; ce sont là les familles de Ruben.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, '– Et les fils de Siméon: Jemuel, et Jamin, et Ohad, et Jakin, et Tsokhar, et Saül, fils d’une Cananéenne; ce sont là les familles de Siméon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Et ce sont ici les noms des fils de Lévi, selon leurs générations: Guershon, et Kehath, et Merari. Et les années de la vie de Lévi furent 137 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, '– Les fils de Guershon: Libni et Shimhi, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, '– Et les fils de Kehath: Amram, et Jitsehar, et Hébron, et Uziel. Et les années de la vie de Kehath furent 133 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, '– Et les fils de Merari: Makhli, et Mushi. Ce sont là les familles de Lévi, selon leurs générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Et Amram prit pour femme Jokébed, sa tante, et elle lui enfanta Aaron et Moïse. Et les années de la vie d’Amram furent 137 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, '– Et les fils de Jitsehar: Coré, et Népheg, et Zicri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, '– Et les fils d’Uziel: Mishaël, et Eltsaphan, et Sithri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, '– Et Aaron prit pour femme Élishéba, fille d’Amminadab, sœur de Nakhshon, et elle lui enfanta Nadab, et Abihu, Éléazar, et Ithamar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, '– Et les fils de Coré: Assir, et Elkana, et Abiasaph; ce sont là les familles des Corites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, '– Et Éléazar, fils d’Aaron, prit pour femme une des filles de Putiel, et elle lui enfanta Phinées. – Ce sont là les chefs des pères des Lévites, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'C’est là cet Aaron et ce Moïse auxquels l’ Éternel dit: Faites sortir les fils d’Israël du pays d’Égypte, selon leurs armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Ce sont eux qui parlèrent au Pharaon, roi d’Égypte, pour faire sortir d’Égypte les fils d’Israël: c’est ce Moïse, et cet Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Et il arriva, le jour où l’ Éternel parla à Moïse dans le pays d’Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'que l’ Éternel parla à Moïse, disant: Je suis l’ Éternel; dis au Pharaon, roi d’Égypte, tout ce que je te dis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Et Moïse dit devant l’ Éternel: Voici, je suis incirconcis de lèvres; et comment le Pharaon m’écoutera-t-il?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, '*Et l’ Éternel dit à Moïse: Vois, je t’ai fait Dieu pour le Pharaon; et Aaron, ton frère, sera ton prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Toi, tu diras tout ce que je te commanderai; et Aaron, ton frère, parlera au Pharaon, pour qu’il laisse aller les fils d’Israël hors de son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Et moi, j’endurcirai le cœur du Pharaon, et je multiplierai mes signes et mes miracles dans le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Et le Pharaon ne vous écoutera pas; et je mettrai ma main sur l’Égypte, et je ferai sortir mes armées, mon peuple, les fils d’Israël, hors du pays d’Égypte, par de grands jugements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'et les Égyptiens sauront que je suis l’ Éternel, lorsque j’aurai étendu ma main sur l’Égypte et que j’aurai fait sortir les fils d’Israël du milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Et Moïse et Aaron firent comme l’ Éternel leur avait commandé; ils firent ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Et Moïse était âgé de 80 ans, et Aaron âgé de 83 ans, quand ils parlèrent au Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Et l’ Éternel parla à Moïse et à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Quand le Pharaon vous parlera, en disant: Montrez pour vous un miracle, tu diras à Aaron: Prends ta verge, et jette-la devant le Pharaon: elle deviendra un serpent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Et Moïse et Aaron vinrent vers le Pharaon, et firent ainsi, selon que l’ Éternel avait commandé; et Aaron jeta sa verge devant le Pharaon et devant ses serviteurs, et elle devint un serpent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Et le Pharaon appela aussi les sages et les magiciens; et eux aussi, les devins d’Égypte, firent ainsi par leurs enchantements:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'ils jetèrent chacun sa verge, et elles devinrent des serpents; mais la verge d’Aaron engloutit leurs verges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Et le cœur du Pharaon s’endurcit, et il ne les écouta point, comme avait dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Et l’ Éternel dit à Moïse: Le cœur du Pharaon est endurci; il refuse de laisser aller le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Va, le matin, vers le Pharaon; voici, il sortira vers l’eau: et tu te présenteras à sa rencontre, sur le bord du fleuve, et tu prendras dans ta main la verge qui a été changée en serpent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'et tu lui diras: L’ Éternel, le Dieu des Hébreux, m’a envoyé vers toi, disant: Laisse aller mon peuple, pour qu’ils me servent dans le désert. Et voici, tu n’as point écouté jusqu’ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Ainsi dit l’ Éternel: À ceci tu connaîtras que je suis l’ Éternel: Voici, je frappe de la verge qui est dans ma main les eaux qui sont dans le fleuve, et elles seront changées en sang;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'et le poisson qui est dans le fleuve mourra, et le fleuve deviendra puant, et les Égyptiens seront dégoûtés de boire des eaux du fleuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Et l’ Éternel dit à Moïse: Dis à Aaron: Prends ta verge, et étends ta main sur les eaux des Égyptiens, sur leurs rivières, sur leurs canaux, et sur leurs étangs, et sur tous leurs amas d’eau; et elles deviendront du sang; et il y aura du sang par tout le pays d’Égypte, et dans les vases de bois et dans les vases de pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Et Moïse et Aaron firent ainsi, selon que l’ Éternel l’avait commandé. Et il leva la verge, et frappa les eaux qui étaient dans le fleuve, aux yeux du Pharaon et aux yeux de ses serviteurs: et toutes les eaux qui étaient dans le fleuve furent changées en sang;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'et le poisson qui était dans le fleuve mourut; et le fleuve devint puant, et les Égyptiens ne pouvaient boire de l’eau du fleuve; et il y avait du sang dans tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Et les devins d’Égypte firent de même par leurs enchantements. Et le cœur du Pharaon s’endurcit, et il ne les écouta point, comme avait dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Et le Pharaon se tourna, et entra dans sa maison, et n’appliqua pas son cœur à cela non plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Et tous les Égyptiens creusèrent autour du fleuve [pour trouver] de l’eau à boire, car ils ne pouvaient boire des eaux du fleuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Et sept jours s’accomplirent après que l’ Éternel eut frappé le fleuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 26, 'Et l’ Éternel dit à Moïse: Va vers le Pharaon, et dis-lui: Ainsi dit l’ Éternel: Laisse aller mon peuple, pour qu’ils me servent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 27, 'Mais si tu refuses de le laisser aller, voici, je vais frapper de grenouilles toutes tes limites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 28, 'et le fleuve fourmillera de grenouilles, et elles monteront et entreront dans ta maison, et dans la chambre où tu couches, et sur ton lit, et dans la maison de tes serviteurs, et parmi ton peuple, et dans tes fours et dans tes huches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 29, 'Et les grenouilles monteront sur toi, et sur ton peuple, et sur tous tes serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Et l’ Éternel dit à Moïse: Dis à Aaron: Étends ta main avec ta verge, sur les rivières, et sur les canaux, et sur les étangs, et fais monter les grenouilles sur le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Et Aaron étendit sa main sur les eaux de l’Égypte: et les grenouilles montèrent, et couvrirent le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Et les devins firent de même par leurs enchantements, et firent monter des grenouilles sur le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Et le Pharaon appela Moïse et Aaron, et dit: Suppliez l’ Éternel, afin qu’il retire les grenouilles de moi et de mon peuple; et je laisserai aller le peuple, et ils sacrifieront à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Et Moïse dit au Pharaon: Glorifie-toi sur moi! Pour quand supplierai-je [l’ Éternel] pour toi, et pour tes serviteurs, et pour ton peuple, afin qu’il ôte les grenouilles d’avec toi et de tes maisons? Il en restera seulement dans le fleuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Et il dit: Pour demain. Et il dit: Selon ta parole! afin que tu saches que nul n’est comme l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Et les grenouilles se retireront d’avec toi, et de tes maisons, et d’avec tes serviteurs, et d’avec ton peuple; il en restera seulement dans le fleuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Et Moïse et Aaron sortirent d’auprès du Pharaon; et Moïse cria à l’ Éternel au sujet des grenouilles qu’il avait fait venir sur le Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Et l’ Éternel fit selon la parole de Moïse. Et les grenouilles moururent dans les maisons, dans les cours et dans les champs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'et on les amassa par monceaux, et la terre devint puante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Et le Pharaon vit qu’il y avait du relâche, et il endurcit son cœur, et ne les écouta pas, comme avait dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Et l’ Éternel dit à Moïse: Dis à Aaron: Étends ta verge, et frappe la poussière de la terre, et elle deviendra des moustiques dans tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Et ils firent ainsi. Et Aaron étendit sa main avec sa verge, et frappa la poussière de la terre, et elle devint des moustiques sur les hommes et sur les bêtes; toute la poussière de la terre devint des moustiques dans tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Et les devins firent de même par leurs enchantements, pour produire les moustiques; mais ils ne le purent. Et les moustiques furent sur les hommes et sur les bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Et les devins dirent au Pharaon: C’est le doigt de Dieu. Et le cœur du Pharaon s’endurcit, et il ne les écouta point, comme avait dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Et l’ Éternel dit à Moïse: Lève-toi de bon matin, et tiens-toi devant le Pharaon; voici, il sortira vers l’eau, et tu lui diras: Ainsi dit l’ Éternel: Laisse aller mon peuple, pour qu’ils me servent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Car si tu ne laisses pas aller mon peuple, voici, j’enverrai contre toi, et contre tes serviteurs, et contre ton peuple, et dans tes maisons, la mouche venimeuse; et les maisons des Égyptiens seront remplies de mouches venimeuses, et aussi le sol sur lequel ils sont.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Et je distinguerai, en ce jour-là, le pays de Goshen, où se tient mon peuple, en sorte que là il n’y ait point de mouches venimeuses; afin que tu saches que moi, l’ Éternel, je suis au milieu du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Et je mettrai une séparation entre mon peuple et ton peuple. Ce signe sera pour demain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Et l’ Éternel fit ainsi: et les mouches entrèrent en multitude dans la maison du Pharaon et dans les maisons de ses serviteurs, et dans tout le pays d’Égypte; – le pays fut ruiné par la mouche venimeuse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Et le Pharaon appela Moïse et Aaron, et dit: Allez, sacrifiez à votre Dieu dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Et Moïse dit: Il n’est pas convenable de faire ainsi; car nous sacrifierions à l’ Éternel, notre Dieu, l’abomination des Égyptiens. Est-ce que nous sacrifierions l’abomination des Égyptiens devant leurs yeux, sans qu’ils nous lapident!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Nous irons le chemin de trois jours dans le désert, et nous sacrifierons à l’ Éternel, notre Dieu, comme il nous a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Et le Pharaon dit: Je vous laisserai aller, et vous sacrifierez à l’ Éternel, votre Dieu, dans le désert; seulement ne vous éloignez pas trop en vous en allant. Priez pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Et Moïse dit: Voici, je sors d’auprès de toi, et je supplierai l’ Éternel, et demain les mouches se retireront du Pharaon, de ses serviteurs, et de son peuple; seulement, que le Pharaon ne continue pas à se moquer, en ne laissant pas aller le peuple pour sacrifier à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Et Moïse sortit d’auprès du Pharaon, et supplia l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Et l’ Éternel fit selon la parole de Moïse: et il retira les mouches du Pharaon, de ses serviteurs, et de son peuple; il n’en resta pas une.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Et le Pharaon endurcit son cœur aussi cette fois, et ne laissa point aller le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Et l’ Éternel dit à Moïse: Va vers le Pharaon, et dis-lui: Ainsi dit l’ Éternel, le Dieu des Hébreux: Laisse aller mon peuple, pour qu’ils me servent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Car si tu refuses de les laisser aller, et que tu les retiennes encore,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'voici, la main de l’ Éternel sera sur tes troupeaux qui sont aux champs, sur les chevaux, sur les ânes, sur les chameaux, sur le gros bétail, et sur le menu bétail; il y aura une peste très grande;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'et l’ Éternel distinguera entre les troupeaux des Israélites et les troupeaux des Égyptiens, et rien ne mourra de tout ce qui est aux fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Et l’ Éternel assigna un temps, disant: Demain l’ Éternel fera cela dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Et l’ Éternel fit cela le lendemain; et tous les troupeaux des Égyptiens moururent; mais des troupeaux des fils d’Israël, il n’en mourut pas une [bête].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Et le Pharaon envoya, et voici, il n’y avait pas même une seule [bête] morte des troupeaux des Israélites. Et le cœur du Pharaon s’endurcit, et il ne laissa point aller le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Et l’ Éternel dit à Moïse et à Aaron: Prenez plein vos mains de cendre de fournaise, et que Moïse la répande vers les cieux, devant les yeux du Pharaon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'et elle deviendra une fine poussière sur tout le pays d’Égypte, et elle deviendra, sur les hommes et sur les bêtes, un ulcère faisant éruption en pustules, dans tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Et ils prirent de la cendre de fournaise, et se tinrent devant le Pharaon; et Moïse la répandit vers les cieux; et elle devint un ulcère faisant éruption en pustules, sur les hommes et sur les bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Et les devins ne purent se tenir devant Moïse, à cause de l’ulcère; car l’ulcère était sur les devins et sur tous les Égyptiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Et l’ Éternel endurcit le cœur du Pharaon, et il ne les écouta pas, comme l’ Éternel avait dit à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Et l’ Éternel dit à Moïse: Lève-toi de bon matin, et tiens-toi devant le Pharaon, et dis-lui: Ainsi dit l’ Éternel, le Dieu des Hébreux: Laisse aller mon peuple, pour qu’ils me servent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'car cette fois j’envoie toutes mes plaies dans ton cœur, et sur tes serviteurs et sur ton peuple, afin que tu saches que nul n’est comme moi, sur toute la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'car maintenant, j’étendrai ma main, et je te frapperai de peste, toi et ton peuple, et tu seras exterminé de dessus la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Mais je t’ai fait subsister pour ceci, afin de te faire voir ma puissance, et pour que mon nom soit publié dans toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'T’élèves-tu encore contre mon peuple, pour ne pas les laisser aller,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'voici, je ferai pleuvoir demain, à ces heures, une grêle très grosse, telle qu’il n’y en a pas eu en Égypte, depuis le jour où elle a été fondée jusqu’à maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Et maintenant, envoie, fais mettre en sûreté tes troupeaux et tout ce que tu as dans les champs; car la grêle tombera sur tout homme et toute bête qui se trouveront dans les champs et qu’on n’aura pas recueillis dans les maisons, et ils mourront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Celui d’entre les serviteurs du Pharaon qui craignit la parole de l’ Éternel, fit se réfugier dans les maisons ses serviteurs et ses troupeaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'et celui qui n’appliqua pas son cœur à la parole de l’ Éternel laissa ses serviteurs et ses troupeaux dans les champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Et l’ Éternel dit à Moïse: Étends ta main vers les cieux, et il y aura de la grêle dans tout le pays d’Égypte, sur les hommes et sur les bêtes, et sur toute herbe des champs dans le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Et Moïse étendit sa verge vers les cieux: et l’ Éternel envoya des tonnerres et de la grêle, et le feu se promenait sur la terre. Et l’ Éternel fit pleuvoir de la grêle sur le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Et il y eut de la grêle, et du feu entremêlé au milieu de la grêle, [qui était] très grosse, telle qu’il n’y en a pas eu dans tout le pays d’Égypte depuis qu’il est devenu une nation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Et la grêle frappa, dans tout le pays d’Égypte, tout ce qui était aux champs, depuis l’homme jusqu’aux bêtes; la grêle frappa aussi toute l’herbe des champs, et brisa tous les arbres des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Seulement dans le pays de Goshen, où étaient les fils d’Israël, il n’y eut point de grêle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Et le Pharaon envoya, et appela Moïse et Aaron, et leur dit: J’ai péché cette fois; l’ Éternel est juste, et moi et mon peuple nous sommes méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Suppliez l’ Éternel; et que ce soit assez des tonnerres de Dieu, et de la grêle; et je vous laisserai aller, et vous ne resterez pas davantage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Et Moïse lui dit: Quand je sortirai de la ville, j’étendrai mes mains vers l’ Éternel; les tonnerres cesseront, et il n’y aura plus de grêle: afin que tu saches que la terre est à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mais, quant à toi et à tes serviteurs, je sais que vous ne craindrez pas encore l’ Éternel Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Et le lin et l’orge avaient été frappés; car l’orge était en épis, et le lin nouait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'et le froment et l’épeautre n’avaient pas été frappés, parce qu’ils sont tardifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Et Moïse sortit d’auprès du Pharaon, hors de la ville, et étendit ses mains vers l’ Éternel: et les tonnerres et la grêle cessèrent, et la pluie ne se déversa plus sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Et le Pharaon vit que la pluie, et la grêle, et les tonnerres, avaient cessé, et il continua de pécher, et il endurcit son cœur, lui et ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Et le cœur du Pharaon s’endurcit, et il ne laissa point aller les fils d’Israël, comme l’ Éternel avait dit par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Et l’ Éternel dit à Moïse: Va vers le Pharaon; car j’ai endurci son cœur et le cœur de ses serviteurs, afin que je mette ces miens signes au milieu d’eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'et afin que tu racontes aux oreilles de ton fils et du fils de ton fils, ce que j’ai accompli en Égypte, et mes signes que j’ai opérés au milieu d’eux; et vous saurez que moi je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Et Moïse et Aaron vinrent vers le Pharaon, et lui dirent: Ainsi dit l’ Éternel, le Dieu des Hébreux: Jusques à quand refuseras-tu de t’humilier devant moi? Laisse aller mon peuple, pour qu’ils me servent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Car si tu refuses de laisser aller mon peuple, voici, je vais faire venir demain des sauterelles dans tes confins,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'et elles couvriront la face de la terre, de sorte qu’on ne pourra pas voir la terre; et elles mangeront le reste qui est échappé, que la grêle vous a laissé, et elles mangeront tout arbre qui croît dans vos champs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'et elles rempliront tes maisons, et les maisons de tous tes serviteurs, et les maisons de tous les Égyptiens: ce que tes pères n’ont point vu, ni les pères de tes pères, depuis le jour où ils ont été sur la terre, jusqu’à ce jour. Et il se tourna, et sortit d’auprès du Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Et les serviteurs du Pharaon lui dirent: Jusques à quand celui-ci sera-t-il pour nous un piège? Laisse aller ces hommes, et qu’ils servent l’ Éternel, leur Dieu. Ne sais-tu pas encore que l’Égypte est ruinée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Et on fit revenir Moïse et Aaron vers le Pharaon; et il leur dit: Allez, servez l’ Éternel, votre Dieu. Qui sont ceux qui iront?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Et Moïse dit: Nous irons avec nos jeunes gens et avec nos vieillards, nous irons avec nos fils et avec nos filles, avec notre menu bétail et avec notre gros bétail; car nous avons [à célébrer] une fête à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Et il leur dit: Que l’ Éternel soit ainsi avec vous, comme je vous laisserai aller avec vos petits enfants! Regardez, car le mal est devant vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Il n’en sera pas ainsi; allez donc, [vous] les hommes faits, et servez l’ Éternel: car c’est là ce que vous avez désiré. Et on les chassa de devant la face du Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Et l’ Éternel dit à Moïse: Étends ta main sur le pays d’Égypte, pour les sauterelles, et qu’elles montent sur le pays d’Égypte, et qu’elles mangent toute l’herbe du pays, tout ce que la grêle a laissé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Et Moïse étendit sa verge sur le pays d’Égypte; et l’ Éternel amena sur le pays un vent d’orient, tout ce jour-là et toute la nuit: le matin arriva, et le vent d’orient apporta les sauterelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Et les sauterelles montèrent sur tout le pays d’Égypte, et se posèrent dans tous les confins de l’Égypte, un fléau terrible; avant elles il n’y avait point eu de sauterelles semblables, et après elles il n’y en aura point de pareilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Et elles couvrirent la face de tout le pays, et le pays fut obscurci; et elles mangèrent toute l’herbe de la terre, et tout le fruit des arbres que la grêle avait laissé; et il ne demeura de reste aucune verdure aux arbres, ni à l’herbe des champs, dans tout le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Et le Pharaon se hâta d’appeler Moïse et Aaron, et dit: J’ai péché contre l’ Éternel, votre Dieu, et contre vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'et maintenant, pardonne, je te prie, mon péché seulement pour cette fois; et suppliez l’ Éternel, votre Dieu, afin seulement qu’il retire de dessus moi cette mort-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Et il sortit d’auprès du Pharaon, et il supplia l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Et l’ Éternel tourna [le vent en] un vent d’occident très fort, qui enleva les sauterelles, et les enfonça dans la mer Rouge. Il ne resta pas une sauterelle dans tous les confins de l’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Et l’ Éternel endurcit le cœur du Pharaon, et il ne laissa point aller les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Et l’ Éternel dit à Moïse: Étends ta main vers les cieux, et il y aura sur le pays d’Égypte des ténèbres, et on touchera de la main les ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Et Moïse étendit sa main vers les cieux: et il y eut d’épaisses ténèbres dans tout le pays d’Égypte, trois jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'On ne se voyait pas l’un l’autre, et nul ne se leva du lieu où il était pendant trois jours; mais pour tous les fils d’Israël il y eut de la lumière dans leurs habitations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Et le Pharaon appela Moïse, et dit: Allez, servez l’ Éternel; seulement que votre menu et votre gros bétail restent; vos petits enfants aussi iront avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Et Moïse dit: Tu nous donneras aussi dans nos mains des sacrifices et des holocaustes, et nous [les] offrirons à l’ Éternel, notre Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'nos troupeaux aussi iront avec nous; il n’en restera pas un ongle, car nous en prendrons pour servir l’ Éternel, notre Dieu; et nous ne savons pas comment nous servirons l’ Éternel, jusqu’à ce que nous soyons parvenus là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Et l’ Éternel endurcit le cœur du Pharaon, et il ne voulut pas les laisser aller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Et le Pharaon lui dit: Va-t’en d’auprès de moi; garde-toi de revoir ma face! car, au jour où tu verras ma face, tu mourras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Et Moïse dit: Comme tu l’as dit, je ne reverrai plus ta face!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Et l’ Éternel dit à Moïse: Je ferai venir encore une plaie sur le Pharaon et sur l’Égypte; après cela il vous laissera aller d’ici; lorsqu’il vous laissera aller complètement, il vous chassera tout à fait d’ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Parle donc aux oreilles du peuple: Que chaque homme demande à son voisin, et chaque femme à sa voisine, des objets d’argent et des objets d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Et l’ Éternel fit que le peuple trouva faveur aux yeux des Égyptiens; l’homme Moïse aussi était très grand dans le pays d’Égypte, aux yeux des serviteurs du Pharaon et aux yeux du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Et Moïse dit: Ainsi dit l’ Éternel: Sur le minuit je sortirai au milieu de l’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'et tout premier-né dans le pays d’Égypte mourra, depuis le premier-né du Pharaon, qui est assis sur son trône, jusqu’au premier-né de la servante qui est derrière la meule, et tout premier-né des bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Et il y aura un grand cri dans tout le pays d’Égypte, comme il n’y en a pas eu et il n’y en aura jamais de semblable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mais contre tous les fils d’Israël, depuis l’homme jusqu’aux bêtes, pas un chien ne remuera sa langue; afin que vous sachiez que l’ Éternel distingue entre les Égyptiens et Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Et tous ces tiens serviteurs descendront vers moi, et se prosterneront devant moi, disant: Sors, toi, et tout le peuple qui est à tes pieds. Et après cela je sortirai. Et [Moïse] sortit d’auprès du Pharaon dans une ardente colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Et l’ Éternel dit à Moïse: Le Pharaon ne vous écoutera point, afin de multiplier mes miracles dans le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Et Moïse et Aaron firent tous ces miracles devant le Pharaon. Et l’ Éternel endurcit le cœur du Pharaon, et il ne laissa point aller de son pays les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, '*Et l’ Éternel parla à Moïse et à Aaron dans le pays d’Égypte, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Ce mois-ci sera pour vous le commencement des mois; il sera pour vous le premier des mois de l’année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Parlez à toute l’assemblée d’Israël, disant: Au dixième [jour] de ce mois, vous prendrez chacun un agneau par maison de père, un agneau par maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Et si la maison est trop peu nombreuse pour un agneau, que lui et son voisin le plus rapproché de sa maison, le prennent, selon le nombre des âmes; vous compterez pour l’agneau d’après ce que chacun peut manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Vous aurez un agneau sans défaut, mâle, âgé d’un an; vous le prendrez d’entre les moutons ou d’entre les chèvres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'et vous le tiendrez en garde jusqu’au quatorzième jour de ce mois; et toute la congrégation de l’assemblée d’Israël l’égorgera entre les deux soirs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Et ils prendront de son sang, et en mettront sur les deux poteaux et sur le linteau de la porte, aux maisons dans lesquelles ils le mangeront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'et ils en mangeront la chair cette nuit-là; ils la mangeront rôtie au feu, avec des pains sans levain, et des herbes amères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Vous n’en mangerez pas qui soit à demi cuit ou qui ait été cuit dans l’eau, mais rôti au feu: la tête, et les jambes, et l’intérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Et vous n’en laisserez rien de reste jusqu’au matin; et ce qui en resterait jusqu’au matin, vous le brûlerez au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Et vous le mangerez ainsi: vos reins ceints, vos sandales à vos pieds, et votre bâton en votre main; et vous le mangerez à la hâte. C’est la pâque de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Et je passerai par le pays d’Égypte cette nuit-là, et je frapperai tout premier-né dans le pays d’Égypte, depuis l’homme jusqu’aux bêtes, et j’exercerai des jugements sur tous les dieux de l’Égypte. Je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Et le sang vous sera pour signe sur les maisons où vous serez; et je verrai le sang, et je passerai par-dessus vous, et il n’y aura point de plaie à destruction au milieu de vous, quand je frapperai le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Et ce jour-là vous sera en mémorial, et vous le célébrerez comme une fête à l’ Éternel; vous le célébrerez en vos générations comme un statut perpétuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Pendant sept jours vous mangerez des pains sans levain: dès le premier jour, vous ôterez le levain de vos maisons; car quiconque mangera du pain levé, du premier jour au septième jour, cette âme-là sera retranchée d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Et le premier jour vous aurez une sainte convocation, et le septième jour une sainte convocation; il ne se fera aucune œuvre en ces jours-là; seulement ce que chacun mangera, cela seul se fera par vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Et vous garderez la fête des pains sans levain, car en ce même jour j’ai fait sortir vos armées du pays d’Égypte; et vous garderez ce jour-là en vos générations, comme un statut perpétuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Le premier mois, le quatorzième jour du mois, au soir, vous mangerez des pains sans levain, jusqu’au vingt et unième jour du mois, au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Pendant sept jours il ne se trouvera point de levain dans vos maisons; car quiconque mangera de ce qui est levé, cette âme-là sera retranchée de l’assemblée d’Israël, étranger ou Israélite de naissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Vous ne mangerez rien de levé; dans toutes vos habitations vous mangerez des pains sans levain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Et Moïse appela tous les anciens d’Israël, et leur dit: Tirez à part et prenez du menu bétail selon vos familles, et égorgez la pâque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Et vous prendrez un bouquet d’hysope, et vous le tremperez dans le sang qui sera dans le bassin; et du sang qui sera dans le bassin, vous aspergerez le linteau et les deux poteaux; et nul d’entre vous ne sortira de la porte de sa maison, jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Car l’ Éternel passera pour frapper les Égyptiens; et il verra le sang sur le linteau et sur les deux poteaux, et l’ Éternel passera par-dessus la porte, et ne permettra pas au destructeur d’entrer dans vos maisons pour frapper.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Et vous garderez cela comme un statut pour toi et pour tes enfants, à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Et lorsque vous serez entrés dans le pays que l’ Éternel vous donnera, comme il l’a dit, il arrivera que vous garderez ce service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Et quand vos enfants vous diront: Que signifie pour vous ce service?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'il arrivera que vous direz: C’est le sacrifice de la pâque à l’ Éternel, qui passa par-dessus les maisons des fils d’Israël en Égypte, lorsqu’il frappa les Égyptiens et qu’il préserva nos maisons. Et le peuple s’inclina, et ils se prosternèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Et les fils d’Israël s’en allèrent, et firent comme l’ Éternel l’avait commandé à Moïse et à Aaron; ils firent ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Et il arriva, au milieu de la nuit, que l’ Éternel frappa tout premier-né dans le pays d’Égypte, depuis le premier-né du Pharaon qui était assis sur son trône, jusqu’au premier-né du captif qui était dans la maison de la fosse, et tout premier-né des bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Et le Pharaon se leva de nuit, lui et tous ses serviteurs, et toute l’Égypte; et il y eut un grand cri en Égypte, car il n’y avait pas de maison où il n’y eût un mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Et il appela Moïse et Aaron de nuit, et dit: Levez-vous, sortez du milieu de mon peuple, tant vous que les fils d’Israël, et allez-vous-en, servez l’ Éternel, comme vous l’avez dit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'prenez votre menu bétail et votre gros bétail, comme vous l’avez dit, et allez-vous-en, et bénissez-moi aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Et les Égyptiens pressaient le peuple, pour le renvoyer du pays en hâte; car ils disaient: Nous sommes tous morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Et le peuple prit sa pâte avant qu’elle soit levée, ayant leurs huches liées dans leurs vêtements sur leurs épaules.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Et les fils d’Israël firent selon la parole de Moïse, et demandèrent aux Égyptiens des objets d’argent, et des objets d’or, et des vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Et l’ Éternel fit que le peuple trouva faveur aux yeux des Égyptiens, qui accordèrent leurs demandes; et ils dépouillèrent les Égyptiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Et les fils d’Israël partirent de Ramsès pour Succoth, environ 600 000 hommes de pied, les hommes faits, sans les petits enfants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'et aussi un grand amas de gens monta avec eux, et du menu et du gros bétail, des troupeaux en très grand nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Et ils cuisirent en gâteaux sans levain la pâte qu’ils avaient emportée d’Égypte; car elle n’avait pas levé, parce qu’ils avaient été chassés d’Égypte et n’avaient pu tarder; ils ne s’étaient pas fait non plus de provisions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Et l’habitation des fils d’Israël qui avaient habité en Égypte, fut de 430 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Et il arriva, au bout de 430 ans, il arriva, en ce même jour, que toutes les armées de l’ Éternel sortirent du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'C’est une nuit à garder pour l’ Éternel, parce qu’il les a fait sortir du pays d’Égypte; – cette nuit-là est à garder pour l’ Éternel par tous les fils d’Israël, en leurs générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Et l’ Éternel dit à Moïse et à Aaron: C’est ici le statut de la Pâque: Aucun étranger n’en mangera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'mais tout esclave, homme acheté à prix d’argent, tu le circonciras; alors il en mangera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'L’habitant et l’homme à gages n’en mangeront point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Elle sera mangée dans une même maison; tu n’emporteras point de sa chair hors de la maison, et vous n’en casserez pas un os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Toute l’assemblée d’Israël la fera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Et si un étranger séjourne chez toi, et veut faire la Pâque à l’ Éternel, que tout mâle qui est à lui soit circoncis; et alors il s’approchera pour la faire, et sera comme l’Israélite de naissance; mais aucun incirconcis n’en mangera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Il y aura une même loi pour l’Israélite de naissance et pour l’étranger qui séjourne parmi vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Et tous les fils d’Israël firent comme l’ Éternel avait commandé à Moïse et à Aaron; ils firent ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Et il arriva, en ce même jour, que l’ Éternel fit sortir les fils d’Israël du pays d’Égypte, selon leurs armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Sanctifie-moi tout premier-né, tout ce qui ouvre la matrice parmi les fils d’Israël, tant des hommes que des bêtes; il est à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Et Moïse dit au peuple: Souvenez-vous de ce jour, auquel vous êtes sortis d’Égypte, de la maison de servitude, car l’ Éternel vous en a fait sortir à main forte; et on ne mangera point de pain levé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Vous sortez aujourd’hui, au mois d’Abib.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Et quand l’ Éternel t’aura fait entrer dans le pays du Cananéen, du Héthien, de l’Amoréen, du Hévien, et du Jébusien, qu’il a juré à tes pères de te donner, pays ruisselant de lait et de miel, il arrivera que tu feras ce service en ce mois-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Pendant sept jours tu mangeras des pains sans levain, et le septième jour il y aura une fête à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'On mangera pendant les sept jours des pains sans levain; et il ne se verra point chez toi de pain levé, et il ne se verra point de levain chez toi, dans tous tes confins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Et tu raconteras [ces choses] à ton fils, en ce jour-là, disant: C’est à cause de ce que l’ Éternel m’a fait quand je sortis d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Et cela te sera un signe sur ta main, et un mémorial entre tes yeux, afin que la loi de l’ Éternel soit en ta bouche, car l’ Éternel t’a fait sortir d’Égypte à main forte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Et tu garderas ce statut en sa saison, d’année en année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Et il arrivera, quand l’ Éternel t’aura fait entrer dans le pays du Cananéen, comme il l’a juré à toi et à tes pères, et qu’il te l’aura donné,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'que tu consacreras à l’ Éternel tout ce qui ouvre la matrice, et tout ce qui ouvre la portière des bêtes qui t’appartiendront: les mâles seront à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Et tout premier fruit des ânes, tu le rachèteras avec un agneau; et si tu ne le rachètes pas, tu lui briseras la nuque. Et tout premier-né des hommes parmi tes fils, tu le rachèteras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Et quand ton fils t’interrogera à l’avenir, disant: Qu’est-ce que ceci? alors tu lui diras: À main forte l’ Éternel nous a fait sortir d’Égypte, de la maison de servitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Et il arriva, quand le Pharaon s’obstinait à ne pas nous laisser aller, que l’ Éternel tua tous les premiers-nés dans le pays d’Égypte, depuis le premier-né des hommes jusqu’au premier-né des bêtes; c’est pourquoi je sacrifie à l’ Éternel tout ce qui ouvre la matrice, les mâles, et je rachète tout premier-né de mes fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Et ce sera un signe sur ta main et un fronteau entre tes yeux, car à main forte l’ Éternel nous a fait sortir d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, '*Et il arriva, quand le Pharaon laissa aller le peuple, que Dieu ne les conduisit pas par le chemin du pays des Philistins, qui est pourtant proche; car Dieu dit: De peur que le peuple ne se repente lorsqu’ils verront la guerre, et qu’ils ne retournent en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Et Dieu fit faire un détour au peuple par le chemin du désert de la mer Rouge; et les fils d’Israël montèrent en ordre de bataille hors du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Et Moïse prit les os de Joseph avec lui, car il avait expressément fait jurer les fils d’Israël, disant: Certainement Dieu vous visitera; et vous ferez monter mes os d’ici avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Et ils partirent de Succoth, et campèrent à Étham, à l’extrémité du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Et l’ Éternel allait devant eux, de jour dans une colonne de nuée pour les conduire par le chemin, et de nuit dans une colonne de feu pour les éclairer, afin qu’ils marchent jour et nuit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'la colonne de nuée ne se retira point, le jour, ni la colonne de feu, la nuit, de devant le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Dis aux fils d’Israël qu’ils se détournent, et qu’ils campent devant Pi-Hahiroth, entre Migdol et la mer; devant Baal-Tsephon, vis-à-vis, vous camperez près de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Et le Pharaon dira des fils d’Israël: Ils sont embarrassés dans le pays, le désert les a enfermés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Et j’endurcirai le cœur du Pharaon, et il les poursuivra: et je serai glorifié dans le Pharaon et en toute son armée; et les Égyptiens sauront que je suis l’ Éternel. Et ils firent ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Et il fut rapporté au roi d’Égypte que le peuple s’était enfui; et le cœur du Pharaon et de ses serviteurs fut changé à l’égard du peuple, et ils dirent: Qu’ avons-nous fait de laisser aller Israël, pour qu’il ne nous serve plus?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Et il attela son char, et prit son peuple avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Et il prit 600 chars d’élite, et tous les chars de l’Égypte, et des capitaines sur tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Et l’ Éternel endurcit le cœur du Pharaon, roi d’Égypte, et il poursuivit les fils d’Israël. Et les fils d’Israël sortaient à main levée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Et les Égyptiens les poursuivirent; et tous les chevaux, les chars du Pharaon, et ses cavaliers et son armée, les atteignirent campés près de la mer, près de Pi-Hahiroth, devant Baal-Tsephon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Et le Pharaon s’approcha, et les fils d’Israël levèrent leurs yeux, et voici, les Égyptiens marchaient après eux: et les fils d’Israël eurent une grande peur, et crièrent à l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'et ils dirent à Moïse: Est-ce parce qu’il n’y avait pas de sépulcres en Égypte, que tu nous as emmenés pour mourir dans le désert? Que nous as-tu fait, de nous avoir fait sortir d’Égypte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'N’est-ce pas ici la parole que nous te disions en Égypte, disant: Laisse-nous, et nous servirons les Égyptiens? Car il nous vaut mieux servir les Égyptiens que de mourir dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Et Moïse dit au peuple: Ne craignez point; tenez-vous là, et voyez la délivrance de l’ Éternel, qu’il opérera pour vous aujourd’hui; car les Égyptiens que vous voyez aujourd’hui, vous ne les verrez plus, à jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'L’ Éternel combattra pour vous, et vous, vous demeurerez tranquilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Et l’ Éternel dit à Moïse: Que cries-tu à moi? Parle aux fils d’Israël, et qu’ils marchent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Et toi, lève ta verge, et étends ta main sur la mer, et fends-la; et que les fils d’Israël entrent au milieu de la mer à sec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Et moi, voici, j’endurcirai le cœur des Égyptiens, et ils entreront après eux; et je me glorifierai dans le Pharaon et en toute son armée, en ses chars et en ses cavaliers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'et les Égyptiens sauront que je suis l’ Éternel, quand je serai glorifié dans le Pharaon, en ses chars et en ses cavaliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Et l’Ange de Dieu, qui allait devant le camp d’Israël, partit, et s’en alla derrière eux; et la colonne de nuée partit de devant eux et se tint derrière eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'et elle vint entre le camp des Égyptiens et le camp d’Israël; et elle fut [pour les uns] une nuée et des ténèbres, et [pour les autres] elle éclairait la nuit; et l’un n’approcha pas de l’autre de toute la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Et Moïse étendit sa main sur la mer: et l’ Éternel fit aller la mer toute la nuit par un fort vent d’orient, et mit la mer à sec, et les eaux se fendirent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'et les fils d’Israël entrèrent au milieu de la mer à sec; et les eaux étaient pour eux un mur à leur droite et à leur gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Et les Égyptiens les poursuivirent, et entrèrent après eux, tous les chevaux du Pharaon, ses chars et ses cavaliers, au milieu de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Et il arriva, sur la veille du matin, que l’ Éternel, dans la colonne de feu et de nuée, regarda l’armée des Égyptiens, et mit en désordre l’armée des Égyptiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Et il ôta les roues de leurs chars, et fit qu’on les menait difficilement. Et les Égyptiens dirent: Fuyons devant Israël, car l’ Éternel combat pour eux contre les Égyptiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Et l’ Éternel dit à Moïse: Étends ta main sur la mer, et les eaux retourneront sur les Égyptiens, sur leurs chars et sur leurs cavaliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Et Moïse étendit sa main sur la mer: et, vers le matin, la mer reprit sa force; et les Égyptiens s’enfuirent à sa rencontre; et l’ Éternel précipita les Égyptiens au milieu de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Et les eaux retournèrent et couvrirent les chars et les cavaliers de toute l’armée du Pharaon qui était entrée après eux dans la mer; il n’en resta pas même un seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Et les fils d’Israël marchèrent à sec au milieu de la mer, et les eaux étaient pour eux un mur à leur droite et à leur gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Et l’ Éternel délivra en ce jour-là Israël de la main des Égyptiens, et Israël vit les Égyptiens morts sur le rivage de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Et Israël vit la grande puissance que l’ Éternel avait déployée contre les Égyptiens; et le peuple craignit l’ Éternel, et ils crurent à l’ Éternel, et à Moïse son serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, '*Alors Moïse et les fils d’Israël chantèrent ce cantique à l’ Éternel, et parlèrent, disant: Je chanterai à l’ Éternel, car il s’est hautement élevé; il a précipité dans la mer le cheval et celui qui le montait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Jah est ma force et mon cantique, et il a été mon salut. Il est mon ✶Dieu, et je lui préparerai une habitation, – le Dieu de mon père, et je l’exalterai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'L’ Éternel est un homme de guerre; l’ Éternel est son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Les chars du Pharaon, et son armée, il les a jetés dans la mer; l’élite de ses capitaines a été enfoncée dans la mer Rouge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Les abîmes les ont couverts; ils sont descendus dans les eaux profondes, comme une pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Ta droite, ô Éternel! s’est montrée magnifique en force; ta droite, ô Éternel! a écrasé l’ennemi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Et dans la grandeur de ta majesté, tu as détruit ceux qui s’élevaient contre toi; tu as lâché ta colère, elle les a dévorés comme du chaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Et par le souffle de tes narines, les eaux se sont amoncelées; les courants se sont dressés comme une muraille; les abîmes sont devenus solides au cœur de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'L’ennemi disait: Je poursuivrai, j’atteindrai, je partagerai le butin; mon âme sera assouvie d’eux; je tirerai mon épée, ma main les exterminera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Tu as soufflé de ton souffle, la mer les a couverts; ils se sont enfoncés comme du plomb dans les eaux magnifiques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Qui est comme toi parmi les ✶dieux, ô Éternel? Qui est comme toi, magnifique en sainteté, terrible en louanges, opérant des merveilles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Tu as étendu ta droite, la terre les a engloutis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Tu as conduit par ta bonté ce peuple que tu as racheté; tu l’as guidé par ta force jusqu’à la demeure de ta sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Les peuples l’ont entendu, ils ont tremblé; l’effroi a saisi les habitants de la Philistie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Alors les chefs d’Édom ont été épouvantés; le tremblement a saisi les forts de Moab; tous les habitants de Canaan se sont fondus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'La crainte et la frayeur sont tombées sur eux: par la grandeur de ton bras ils sont devenus muets comme une pierre, jusqu’à ce que ton peuple, ô Éternel, ait passé, jusqu’à ce qu’ait passé ce peuple que tu t’es acquis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Tu les introduiras et tu les planteras sur la montagne de ton héritage, le lieu que tu as préparé pour ton habitation, ô Éternel! le sanctuaire, ô Seigneur! que tes mains ont établi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'L’ Éternel régnera à toujours et à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Car le cheval du Pharaon est entré dans la mer, avec son char et ses cavaliers, et l’ Éternel a fait retourner sur eux les eaux de la mer; et les fils d’Israël ont marché à sec au milieu de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Et Marie, la prophétesse, sœur d’Aaron, prit un tambourin en sa main, et toutes les femmes sortirent après elle, avec des tambourins et en chœurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'et Marie leur répondait: Chantez à l’ Éternel, car il s’est hautement élevé; il a précipité dans la mer le cheval et celui qui le montait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Et Moïse fit partir Israël de la mer Rouge, et ils sortirent vers le désert de Shur; et ils marchèrent trois jours dans le désert, et ne trouvèrent point d’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Et ils vinrent à Mara; mais ils ne pouvaient boire des eaux de Mara, car elles étaient amères: c’est pourquoi son nom fut appelé Mara.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Et le peuple murmura contre Moïse, disant: Que boirons-nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Et il cria à l’ Éternel; et l’ Éternel lui enseigna un bois, et il le jeta dans les eaux, et les eaux devinrent douces. Là il lui donna un statut et une ordonnance, et là il l’éprouva,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'et dit: Si tu écoutes attentivement la voix de l’ Éternel, ton Dieu, et si tu fais ce qui est droit à ses yeux, et si tu prêtes l’oreille à ses commandements, et si tu gardes tous ses statuts, je ne mettrai sur toi aucune des maladies que j’ai mises sur l’Égypte, car je suis l’ Éternel qui te guérit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Puis ils vinrent à Élim, où il y avait douze fontaines d’eau et 70 palmiers; et ils campèrent là, auprès des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, '*Et ils partirent d’Élim, toute l’assemblée des fils d’Israël, et vinrent au désert de Sin, qui est entre Élim et Sinaï, le quinzième jour du second mois après leur sortie du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Et toute l’assemblée des fils d’Israël murmura contre Moïse et contre Aaron, dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Et les fils d’Israël leur dirent: Ah! que ne sommes-nous morts par la main de l’ Éternel dans le pays d’Égypte, quand nous étions assis auprès des pots de chair, quand nous mangions du pain à satiété! Car vous nous avez fait sortir dans ce désert pour faire mourir de faim toute cette congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Et l’ Éternel dit à Moïse: Voici, je vais vous faire pleuvoir des cieux du pain, et le peuple sortira, et en recueillera chaque jour la portion d’un jour, afin que je l’éprouve, [pour voir] s’il marchera dans ma loi, ou non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Et il arrivera que, le sixième jour, ils prépareront ce qu’ils auront rapporté, et ce sera le double de ce qu’ils recueilleront chaque jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Et Moïse et Aaron dirent à tous les fils d’Israël: Au soir vous saurez que l’ Éternel vous a fait sortir du pays d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'et, au matin, vous verrez la gloire de l’ Éternel, parce qu’il a entendu vos murmures contre l’ Éternel; car que sommes-nous, que vous murmuriez contre nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Et Moïse dit: [Ce sera] en ce que l’ Éternel vous donnera le soir de la chair à manger, et au matin du pain à satiété; parce que l’ Éternel a entendu vos murmures que vous avez proférés contre lui; car que sommes-nous? Vos murmures ne sont pas contre nous, mais contre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Et Moïse dit à Aaron: Dis à toute l’assemblée des fils d’Israël: Approchez-vous devant l’ Éternel; car il a entendu vos murmures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Et il arriva, comme Aaron parlait à toute l’assemblée des fils d’Israël, qu’ils se tournèrent vers le désert; et voici, la gloire de l’ Éternel parut dans la nuée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'J’ai entendu les murmures des fils d’Israël. Parle-leur, disant: Entre les deux soirs vous mangerez de la chair, et au matin vous serez rassasiés de pain; et vous saurez que je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Et il arriva, le soir, que des cailles montèrent et couvrirent le camp; et, au matin, il y eut une couche de rosée autour du camp;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'et la couche de rosée se leva, et voici sur la surface du désert quelque chose de menu, de grenu, quelque chose de menu comme la gelée blanche sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Et les fils d’Israël le virent, et se dirent l’un à l’autre: Qu’est-ce que cela? Car ils ne savaient ce que c’était. Et Moïse leur dit: C’est le pain que l’ Éternel vous a donné à manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Voici la parole que l’ Éternel a commandée: Recueillez-en, chacun en proportion de ce qu’il peut manger, un omer par tête, selon le nombre de vos personnes; vous en prendrez chacun pour ceux qui sont dans sa tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Et les fils d’Israël firent ainsi, et ils recueillirent, l’un beaucoup, l’autre peu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Et ils mesurèrent à l’omer: et celui qui avait beaucoup, n’eut pas trop; et celui qui avait peu, n’en manqua pas; ils avaient recueilli, chacun en proportion de ce qu’il mangeait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Et Moïse leur dit: Que personne n’en laisse de reste jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mais ils n’écoutèrent pas Moïse, et quelques-uns [d’entre eux] en laissèrent de reste jusqu’au matin; et il s’y engendra des vers, et cela puait: et Moïse se mit en colère contre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Et ils en recueillaient chaque matin, chacun en proportion de ce qu’il mangeait; et à la chaleur du soleil cela fondait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Et il arriva que, le sixième jour, ils recueillirent du pain au double, deux omers pour chacun; et tous les principaux de l’assemblée vinrent et le rapportèrent à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Et il leur dit: C’est ici ce que l’ Éternel a dit: Demain est le repos, le sabbat consacré à l’ Éternel; faites cuire ce que vous avez à cuire, et faites bouillir ce que vous avez à faire bouillir, et tout le surplus serrez-le pour vous, pour le garder jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Et ils le serrèrent jusqu’au matin, comme Moïse l’avait commandé; et cela ne pua point, et il n’y eut point de vers dedans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Et Moïse dit: Mangez-le aujourd’hui, car aujourd’hui est le sabbat [consacré] à l’ Éternel; aujourd’hui vous n’en trouverez point aux champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Six jours vous en recueillerez, mais au septième jour est le sabbat; il n’y en aura point en ce [jour-là].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Et il arriva, le septième jour, que quelques-uns du peuple sortirent pour en recueillir, et ils n’en trouvèrent point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Et l’ Éternel dit à Moïse: Jusques à quand refuserez-vous de garder mes commandements et mes lois?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Voyez que l’ Éternel vous a donné le sabbat; c’est pourquoi il vous donne au sixième jour du pain pour deux jours. Que chacun reste chez lui; que personne ne sorte du lieu où il est, le septième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Et le peuple se reposa le septième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Et la maison d’Israël appela le nom de cela manne. Et elle était comme de la semence de coriandre, blanche, et avait le goût d’un gâteau au miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Et Moïse dit: Voici la parole que l’ Éternel a commandée: Qu’on en remplisse un omer pour le garder pour vos générations, afin qu’elles voient le pain que je vous ai fait manger dans le désert, lorsque je vous ai fait sortir du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Et Moïse dit à Aaron: Prends une cruche, et mets-y plein un omer de manne, et pose-la devant l’ Éternel, pour la garder pour vos générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Comme l’ Éternel l’avait commandé à Moïse, Aaron la posa devant le témoignage pour être gardée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Et les fils d’Israël mangèrent la manne 40 ans, jusqu’à ce qu’ils entrèrent dans un pays habité; ils mangèrent la manne jusqu’à leur arrivée à la frontière du pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Or l’omer est la dixième partie de l’épha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, '*Et toute l’assemblée des fils d’Israël partit du désert de Sin, selon leurs traites, d’après le commandement de l’ Éternel, et ils campèrent à Rephidim; et il n’y avait point d’eau à boire pour le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Et le peuple contesta avec Moïse, et ils dirent: Donnez-nous de l’eau pour que nous buvions. Et Moïse leur dit: Pourquoi contestez-vous avec moi? Pourquoi tentez-vous l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Et là, le peuple eut soif d’eau; et le peuple murmura contre Moïse, et dit: Pourquoi nous as-tu fait monter d’Égypte, pour nous faire mourir de soif, moi, et mes enfants, et mon bétail?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Et Moïse cria à l’ Éternel, disant: Que ferai-je à ce peuple? Encore un peu, et ils me lapideront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Et l’ Éternel dit à Moïse: Passe devant le peuple, et prends avec toi des anciens d’Israël; et prends dans ta main ta verge avec laquelle tu as frappé le fleuve, et va.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Voici, je me tiens là devant toi, sur le rocher, en Horeb; et tu frapperas le rocher, et il en sortira des eaux, et le peuple boira. Et Moïse fit ainsi devant les yeux des anciens d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Et il appela le nom du lieu Massa et Meriba, à cause de la contestation des fils d’Israël, et parce qu’ils avaient tenté l’ Éternel, en disant: L’ Éternel est-il au milieu de nous, ou n’y est-il pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Et Amalek vint, et combattit contre Israël, à Rephidim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Et Moïse dit à Josué: Choisis-nous des hommes, et sors, combats contre Amalek; demain je me tiendrai sur le sommet de la colline, la verge de Dieu dans ma main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Et Josué fit comme Moïse lui avait dit, pour combattre contre Amalek; et Moïse, Aaron, et Hur montèrent au sommet de la colline.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Et il arrivait, lorsque Moïse élevait sa main, qu’Israël avait le dessus; et quand il reposait sa main, Amalek avait le dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Mais les mains de Moïse étaient pesantes; et ils prirent une pierre, et la mirent sous lui, et il s’assit dessus; et Aaron et Hur soutenaient ses mains, l’un deçà, et l’autre delà; et ses mains furent fermes jusqu’au coucher du soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Et Josué abattit Amalek et son peuple au tranchant de l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Et l’ Éternel dit à Moïse: Écris ceci pour mémorial dans le livre, et fais-le entendre à Josué, que j’effacerai entièrement la mémoire d’Amalek de dessous les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Et Moïse bâtit un autel, et appela son nom: Jéhovah-Nissi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'et il dit: Parce que Jah a juré, l’ Éternel aura la guerre contre Amalek de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, '*Et Jéthro, sacrificateur de Madian, beau-père de Moïse, apprit tout ce que Dieu avait fait à Moïse et à Israël, son peuple, – que l’ Éternel avait fait sortir Israël d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'et Jéthro, beau-père de Moïse, prit Séphora, la femme de Moïse, après que celui-ci l’eut renvoyée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'et ses deux fils, dont l’un s’appelait Guershom, car il avait dit: J’ai séjourné dans un pays étranger;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'et l’autre Éliézer: Car le Dieu de mon père m’a été en aide, et m’a délivré de l’épée du Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Et Jéthro, beau-père de Moïse, vint, avec les fils et la femme de Moïse, vers celui-ci, au désert où il était campé, à la montagne de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'et il fit dire à Moïse: Moi, ton beau-père Jéthro, je suis venu vers toi, et ta femme, et ses deux fils avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Et Moïse sortit à la rencontre de son beau-père, et se prosterna et l’embrassa; et ils s’enquirent l’un de l’autre touchant leur bien-être, et entrèrent dans la tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Et Moïse raconta à son beau-père tout ce que l’ Éternel avait fait au Pharaon et à l’Égypte à cause d’Israël, toute la fatigue qui les avait atteints en chemin, et comment l’ Éternel les avait délivrés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Et Jéthro se réjouit de tout le bien que l’ Éternel avait fait à Israël, en ce qu’il l’avait délivré de la main des Égyptiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Et Jéthro dit: Béni soit l’ Éternel, qui vous a délivrés de la main des Égyptiens et de la main du Pharaon, – qui a délivré le peuple de dessous la main des Égyptiens!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Maintenant je connais que l’ Éternel est plus grand que tous les dieux; car en cela [même] en quoi ils ont agi présomptueusement, il a été au-dessus d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Et Jéthro, beau-père de Moïse, prit un holocauste et des sacrifices pour Dieu; et Aaron et tous les anciens d’Israël vinrent pour manger le pain avec le beau-père de Moïse, en la présence de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Et il arriva, le lendemain, que Moïse s’assit pour juger le peuple; et le peuple se tint auprès de Moïse depuis le matin jusqu’au soir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'et le beau-père de Moïse vit tout ce qu’il faisait avec le peuple, et il dit: Que fais-tu là avec le peuple? Pourquoi es-tu assis seul, et tout le peuple se tient auprès de toi depuis le matin jusqu’au soir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Et Moïse dit à son beau-père: C’est que le peuple vient à moi pour consulter Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Quand ils ont quelque affaire, on vient à moi, et je juge entre l’un et l’autre, et je leur fais connaître les statuts de Dieu et ses lois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Et le beau-père de Moïse lui dit: Ce que tu fais n’est pas bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Tu t’épuiseras certainement, toi et ce peuple qui est avec toi, car la chose est trop lourde pour toi; tu ne peux la faire toi seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Maintenant, écoute ma voix, je te conseillerai, et Dieu sera avec toi. Sois pour le peuple auprès de Dieu, et rapporte les affaires à Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'et enseigne-leur les statuts et les lois, et fais-leur connaître la voie dans laquelle ils doivent marcher, et l’œuvre qu’ils ont à faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Et choisis d’entre tout le peuple des hommes capables, craignant Dieu, des hommes de vérité, haïssant le gain déshonnête, et établis-les sur eux, chefs de milliers, chefs de centaines, chefs de cinquantaines, et chefs de dizaines;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'et qu’ils jugent le peuple en tout temps: et il arrivera qu’ils porteront devant toi toutes les grandes affaires, et toutes les petites affaires ils les jugeront eux-mêmes. Tu allégeras ce qui [pèse] sur toi; ils le porteront avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Si tu fais cela, et que Dieu te le commande, tu pourras subsister, et tout ce peuple aussi arrivera en paix en son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Et Moïse écouta la voix de son beau-père, et fit tout ce qu’il avait dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Et Moïse choisit d’entre tout Israël des hommes capables, et les établit chefs sur le peuple, chefs de milliers, chefs de centaines, chefs de cinquantaines, et chefs de dizaines;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'et ils jugèrent le peuple en tout temps: ils portaient devant Moïse les affaires difficiles, et toutes les petites affaires ils les jugeaient eux-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Et Moïse laissa partir son beau-père, et il s’en alla dans son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, '*Au troisième mois après que les fils d’Israël furent sortis du pays d’Égypte, en ce même jour, ils vinrent au désert de Sinaï:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'ils partirent de Rephidim, et vinrent au désert de Sinaï, et campèrent dans le désert; et Israël campa là devant la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Et Moïse monta vers Dieu; et l’ Éternel l’appela de la montagne, disant: Tu diras ainsi à la maison de Jacob, et tu l’annonceras aux fils d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vous avez vu ce que j’ai fait à l’Égypte, et comment je vous ai portés sur des ailes d’aigle, et vous ai amenés à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Et maintenant, si vous écoutez attentivement ma voix et si vous gardez mon alliance, vous m’appartiendrez en propre d’entre tous les peuples; car toute la terre est à moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'et vous me serez un royaume de sacrificateurs, et une nation sainte. Ce sont là les paroles que tu diras aux fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Et Moïse vint, et appela les anciens du peuple, et mit devant eux toutes ces paroles que l’ Éternel lui avait commandées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Et tout le peuple ensemble répondit et dit: Tout ce que l’ Éternel a dit, nous le ferons. Et Moïse rapporta à l’ Éternel les paroles du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Et l’ Éternel dit à Moïse: Voici, je viendrai à toi dans l’obscurité d’une nuée, afin que le peuple entende quand je parlerai avec toi, et qu’aussi ils te croient à toujours. Et Moïse rapporta à l’ Éternel les paroles du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Et l’ Éternel dit à Moïse: Va vers le peuple, et sanctifie-les, aujourd’hui et demain, et qu’ils lavent leurs vêtements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'et qu’ils soient prêts pour le troisième jour; car le troisième jour l’ Éternel descendra, aux yeux de tout le peuple, sur la montagne de Sinaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Et tu mettras des bornes pour le peuple, à l’entour, disant: Donnez-vous garde de monter sur la montagne et d’en toucher l’extrémité. Quiconque touchera la montagne sera certainement mis à mort:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'la main ne la touchera pas sans qu’elle soit lapidée ou transpercée; bête, ou homme, ils ne vivront point. Quand le cor sonnera longuement, ils monteront vers la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Et Moïse descendit de la montagne vers le peuple, et sanctifia le peuple, et ils lavèrent leurs vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Et il dit au peuple: Soyez prêts pour le troisième jour; ne vous approchez pas de [vos] femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Et il arriva, le troisième jour, quand le matin fut venu, qu’il y eut des tonnerres et des éclairs, et une épaisse nuée sur la montagne, et un son de trompette très fort; et tout le peuple qui était dans le camp trembla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Et Moïse fit sortir le peuple hors du camp à la rencontre de Dieu, et ils se tinrent au pied de la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Et toute la montagne de Sinaï fumait, parce que l’ Éternel descendit en feu sur elle; et sa fumée montait comme la fumée d’une fournaise, et toute la montagne tremblait fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Et comme le son de la trompette se renforçait de plus en plus, Moïse parla, et Dieu lui répondit par une voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Et l’ Éternel descendit sur la montagne de Sinaï, sur le sommet de la montagne, et l’ Éternel appela Moïse au sommet de la montagne; et Moïse monta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Et l’ Éternel dit à Moïse: Descends, avertis solennellement le peuple, de peur qu’ils ne rompent les barrières pour monter vers l’ Éternel pour voir, et qu’un grand nombre d’entre eux ne tombe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Et aussi, que les sacrificateurs qui s’approchent de l’ Éternel se sanctifient, de peur que l’ Éternel ne se jette sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Et Moïse dit à l’ Éternel: Le peuple ne pourra pas monter sur la montagne de Sinaï, car tu nous as solennellement avertis, en disant: Mets des bornes autour de la montagne, et sanctifie-la.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Et l’ Éternel lui dit: Va, descends; puis tu monteras, toi, et Aaron avec toi; mais que les sacrificateurs et le peuple ne rompent point les barrières pour monter vers l’ Éternel, de peur qu’il ne se jette sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Et Moïse descendit vers le peuple et lui dit [ces choses].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, '*Et Dieu prononça toutes ces paroles, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Je suis l’ Éternel, ton Dieu, qui t’ai fait sortir du pays d’Égypte, de la maison de servitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Tu n’auras point d’autres dieux devant ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Tu ne te feras point d’image taillée, ni aucune ressemblance de ce qui est dans les cieux en haut, et de ce qui est sur la terre en bas, et de ce qui est dans les eaux au-dessous de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Tu ne t’inclineras point devant elles, et tu ne les serviras point; car moi, l’ Éternel, ton Dieu, je suis un ✶Dieu jaloux, qui visite l’iniquité des pères sur les fils, sur la troisième et sur la quatrième [génération] de ceux qui me haïssent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'et qui use de bonté envers des milliers de ceux qui m’aiment et qui gardent mes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Tu ne prendras point le nom de l’ Éternel, ton Dieu, en vain; car l’ Éternel ne tiendra point pour innocent celui qui aura pris son nom en vain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Souviens-toi du jour du sabbat, pour le sanctifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Six jours tu travailleras, et tu feras toute ton œuvre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'mais le septième jour est le sabbat [consacré] à l’ Éternel, ton Dieu: tu ne feras aucune œuvre, ni toi, ni ton fils, ni ta fille, [ni] ton serviteur, ni ta servante, ni ta bête, ni ton étranger qui est dans tes portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Car en six jours l’ Éternel a fait les cieux, et la terre, la mer, et tout ce qui est en eux, et il s’est reposé le septième jour; c’est pourquoi l’ Éternel a béni le jour du sabbat, et l’a sanctifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honore ton père et ta mère, afin que tes jours soient prolongés sur la terre que l’ Éternel, ton Dieu, te donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Tu ne tueras point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Tu ne commettras point adultère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Tu ne déroberas point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Tu ne diras point de faux témoignage contre ton prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Tu ne convoiteras point la maison de ton prochain; tu ne convoiteras point la femme de ton prochain, ni son serviteur, ni sa servante, ni son bœuf, ni son âne, ni rien qui soit à ton prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, '*Et tout le peuple aperçut les tonnerres, et les flammes, et le son de la trompette, et la montagne fumante; et le peuple vit [cela], et ils tremblèrent et se tinrent loin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'et dirent à Moïse: Toi, parle avec nous, et nous écouterons; mais que Dieu ne parle point avec nous, de peur que nous ne mourions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Et Moïse dit au peuple: Ne craignez pas; car c’est afin de vous éprouver que Dieu est venu, et afin que sa crainte soit devant vos yeux, pour que vous ne péchiez point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Et le peuple se tint loin; et Moïse s’approcha de l’obscurité profonde où Dieu était.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Et l’ Éternel dit à Moïse: Tu diras ainsi aux fils d’Israël: Vous avez vu que j’ai parlé avec vous des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Vous ne ferez point de dieux d’argent à côté de moi, et vous ne vous ferez pas des dieux d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Tu me feras un autel de terre, et tu sacrifieras dessus tes holocaustes et tes sacrifices de prospérités, ton menu et ton gros bétail. En tout lieu où je mettrai la mémoire de mon nom, je viendrai à toi, et je te bénirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Et si tu me fais un autel de pierres, tu ne le bâtiras point de pierres taillées; car si tu lèves ton ciseau dessus, tu le profaneras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Et tu ne monteras point à mon autel par des degrés, afin que ta nudité n’y soit pas découverte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '*Ce sont ici les jugements que tu placeras devant eux:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Si tu achètes un serviteur hébreu, il servira six années, et, la septième, il sortira libre, gratuitement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'S’il est venu seul, il sortira seul; s’ il avait une femme, sa femme sortira avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Si son maître lui a donné une femme, et qu’elle lui ait enfanté des fils ou des filles, la femme et ses enfants seront à son maître, et lui, il sortira seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Mais si le serviteur dit positivement: J’aime mon maître, ma femme et mes enfants, je ne veux pas sortir libre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'alors son maître le fera venir devant les juges, et le fera approcher de la porte ou du poteau, et son maître lui percera l’oreille avec un poinçon; et il le servira à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Et si un homme vend sa fille pour être servante, elle ne sortira point comme sortent les serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Si elle déplaît aux yeux de son maître qui se l’était fiancée, il la fera racheter; il n’aura pas le pouvoir de la vendre à un peuple étranger, après l’avoir trompée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Et s’il l’a fiancée à son fils, il agira envers elle selon le droit des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'S’il en prend une autre, il ne retranchera rien pour elle à sa nourriture, à son vêtement, et à son droit conjugal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Et s’il ne fait pas pour elle ces trois choses-là, elle sortira gratuitement, sans [payer aucun] argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Si quelqu’un frappe un homme, et qu’il en meure, il sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Mais s’il ne lui a pas dressé d’embûche, et que Dieu l’ait fait tomber sous ses mains, je t’établirai un lieu où il s’enfuira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Et si un homme s’élève de propos délibéré contre son prochain, pour le tuer par ruse, tu l’arracheras de mon autel, pour qu’il meure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Et celui qui frappera son père ou sa mère sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Et si quelqu’un vole un homme et qu’il le vende, ou qu’il soit trouvé en sa main, il sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Et celui qui maudit son père ou sa mère sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Et si des hommes contestent entre eux, et que l’un frappe l’autre avec une pierre ou avec le poing, et qu’il ne meure pas, mais tienne le lit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 's’il se lève et marche dehors sur son bâton, celui qui l’a frappé sera tenu pour quitte; seulement, il paiera son chômage, et le fera guérir complètement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Et si quelqu’un frappe du bâton son serviteur ou sa servante, et qu’il meure sous sa main, il sera certainement vengé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'seulement, s’il reste debout un jour ou deux jours, il ne sera pas vengé, car il est son argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Et si des hommes se querellent, et que [l’un d’eux] heurte une femme enceinte et qu’elle accouche sans qu’il y ait de malheur, une amende sera payée selon ce que le mari de la femme lui imposera, et il la donnera suivant [la décision des] juges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Et s’il arrive malheur, tu donneras vie pour vie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'œil pour œil, dent pour dent, main pour main, pied pour pied,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'brûlure pour brûlure, blessure pour blessure, meurtrissure pour meurtrissure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Et si un homme frappe l’œil de son serviteur, ou l’œil de sa servante, et le lui fasse perdre, il les laissera aller libres pour l’œil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'et s’il fait tomber la dent de son serviteur ou la dent de sa servante, il les laissera aller libres pour la dent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Et si un bœuf frappe de ses cornes un homme ou une femme, et qu’ils en meurent, le bœuf sera certainement lapidé, et sa chair ne sera pas mangée; mais le maître du bœuf sera [tenu pour] non coupable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Et si le bœuf frappait de ses cornes auparavant, et que son maître en ait été averti et qu’il ne l’ait pas tenu sous garde, et qu’il tue un homme ou une femme, le bœuf sera lapidé, et son maître aussi sera mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Et si une indemnité lui est imposée, il donnera la rançon de sa vie selon tout ce qui lui sera imposé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Soit qu’il ait frappé un fils, ou qu’il ait frappé une fille, il lui sera fait selon ce jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Si le bœuf a frappé de ses cornes un serviteur ou une servante, le possesseur donnera à son maître 30 sicles d’argent, et le bœuf sera lapidé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Et si un homme ouvre une fosse, ou si un homme creuse une fosse, et ne la couvre pas, et qu’un bœuf ou un âne y tombe,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'le propriétaire de la fosse donnera une compensation, il remettra l’argent au maître de la [bête]; et la bête morte lui appartiendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Et si le bœuf d’un homme heurte le bœuf de son prochain, et qu’il en meure, ils vendront le bœuf vivant, et en partageront l’argent, et ils partageront aussi le mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ou s’il était connu que le bœuf frappait de ses cornes auparavant, et que son maître ne l’ait pas tenu sous garde, il fera certainement compensation, bœuf pour bœuf; et le [bœuf] mort lui appartiendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 37, 'Si un homme vole un bœuf, ou un mouton, et qu’il le tue ou le vende, il restituera cinq bœufs pour le bœuf, et quatre moutons pour le mouton.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Si le voleur est trouvé commettant effraction, et qu’il soit frappé et qu’il meure, il n’y aura pas coulpe de sang pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Si le soleil est levé sur lui, il y aura coulpe de sang pour lui: il aurait fait pleine compensation; s’il n’avait rien eu, il aurait été vendu pour son vol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Si ce qui a été volé est trouvé vivant entre ses mains, soit bœuf, soit âne, soit mouton, il fera compensation au double.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Si un homme fait brouter un champ ou une vigne, et envoie son bétail et qu’il broute dans le champ d’autrui, il fera compensation, du meilleur de son champ et du meilleur de sa vigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Si le feu sort et trouve des épines, et qu’un tas de gerbes, ou du blé sur pied, ou le champ, soit consumé, celui qui aura allumé l’incendie fera pleine compensation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Si quelqu’un donne à son prochain de l’argent ou des objets à garder, et qu’ils soient volés de la maison de cet homme, si le voleur est trouvé, il fera compensation au double.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Si le voleur n’est pas trouvé, le maître de la maison sera amené devant les juges, [pour jurer] s’il n’a pas mis sa main sur le bien de son prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Dans toute affaire d’infidélité touchant un bœuf, touchant un âne, touchant un mouton, touchant un vêtement, touchant toute chose perdue dont on dira: C’est cela, – l’affaire des deux [parties] viendra devant les juges; celui que les juges condamneront fera compensation au double à son prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Si un homme donne à garder à son prochain un âne, ou un bœuf, ou un mouton, ou une bête quelconque, et que la bête meure, ou qu’elle se soit fait une fracture, ou qu’on l’ait emmenée, sans que personne l’ait vu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'le serment de l’ Éternel interviendra entre les deux [parties], [pour jurer] s’il n’a pas mis sa main sur le bien de son prochain; et le maître de la [bête] l’acceptera, et celui-là ne fera pas compensation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'mais, si réellement elle lui a été volée, il fera compensation au maître:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'si elle a été déchirée, il l’apportera en témoignage; il ne compensera pas ce qui a été déchiré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Et si un homme a emprunté [une bête] à son prochain, et qu’elle se fasse une fracture, ou qu’elle meure, et que son maître n’ait pas été avec elle, il fera certainement compensation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Si son maître était avec elle, il ne fera pas compensation; si elle a été louée, elle sera venue pour son louage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Et si un homme séduit une vierge non fiancée, et couche avec elle, il la prendra pour sa femme, en payant une dot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Si son père refuse absolument de la lui donner, il [lui] pèsera de l’argent selon la dot des vierges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Tu ne laisseras point vivre la magicienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Quiconque couche avec une bête sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Celui qui sacrifie à un dieu, si ce n’est à l’ Éternel seul, sera voué à la destruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Tu ne traiteras pas mal et tu n’opprimeras pas l’étranger; car vous avez été étrangers dans le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Vous n’affligerez aucune veuve, ni aucun orphelin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Si, en quoi que ce soit, tu les affliges, et qu’ils crient à moi, certainement j’ entendrai leur cri;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'et ma colère s’embrasera, et je vous tuerai par l’épée, et vos femmes seront veuves, et vos enfants orphelins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Si tu prêtes de l’argent à mon peuple, au pauvre qui est avec toi, tu ne seras pas avec lui comme un usurier; vous ne lui imposerez pas d’intérêt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Si tu prends en gage le vêtement de ton prochain, tu le lui rendras avant que le soleil soit couché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'car c’est sa seule couverture, son vêtement pour sa peau: dans quoi coucherait-il? Il arrivera que, quand il criera à moi, je l’écouterai; car je suis miséricordieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Tu n’outrageras pas les juges, et tu ne maudiras pas le prince de ton peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Tu ne différeras point [à m’offrir de] l’abondance de ton [grenier] et de ce qui coule de ton pressoir. Le premier-né de tes fils, tu me le donneras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Tu feras ainsi de ton bœuf et de ton menu bétail: il sera sept jours avec sa mère; le huitième jour, tu me le donneras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Et vous me serez des hommes saints, et vous ne mangerez point de la chair déchirée aux champs; vous la jetterez aux chiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Tu ne feras pas courir de faux bruits. Tu ne donneras pas la main au méchant, pour être un témoin inique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Tu n’iras pas après la foule, pour mal faire; et tu ne répondras pas dans un procès en penchant du côté de la foule, pour faire fléchir [le jugement].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Et tu ne favoriseras pas le pauvre dans son procès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Si tu rencontres le bœuf de ton ennemi, ou son âne, égaré, tu ne manqueras pas de le lui ramener.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Si tu vois l’âne de celui qui te hait couché sous son fardeau, tu te garderas de l’abandonner; tu ne manqueras pas de le délier avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Tu ne feras pas fléchir le jugement de ton indigent dans son procès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Tu t’éloigneras de la parole de mensonge, et tu ne tueras pas l’innocent et le juste; car je ne justifierai pas le méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Et tu ne recevras pas de présent; car le présent aveugle ceux qui voient clair, et pervertit les paroles des justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Tu n’opprimeras pas l’étranger; car vous savez ce qu’est le cœur d’un étranger, car vous avez été étrangers dans le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Pendant six années tu sèmeras ta terre, et tu en recueilleras le rapport;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'et la septième, tu la laisseras en jachère, et tu la laisseras inculte, et les indigents de ton peuple en mangeront, et ce qu’ils laisseront de reste, les bêtes des champs le mangeront. Tu en feras de même pour ta vigne et pour ton olivier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, '– Six jours tu feras ton ouvrage, et le septième jour tu te reposeras, afin que ton bœuf et ton âne aient du repos, et que le fils de ta servante et l’étranger respirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Vous prendrez garde à tout ce que je vous ai dit; et vous ne mentionnerez pas le nom d’autres dieux; on ne l’entendra point de ta bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Trois fois l’an tu me célébreras une fête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, '– Tu garderas la fête des pains sans levain; pendant sept jours, au temps fixé du mois d’Abib, tu mangeras des pains sans levain, comme je t’ai commandé, car en ce [mois] tu es sorti d’Égypte; et on ne paraîtra pas à vide devant ma face;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, '– et la fête de la moisson des premiers fruits de tes travaux, de ce que tu auras semé dans le champ; – et la fête de la récolte, à la fin de l’année, quand tu recueilleras du champ [les fruits de] tes travaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, '– Trois fois l’an tous tes mâles paraîtront devant la face du Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Tu n’offriras point le sang de mon sacrifice avec du pain levé; et la graisse de ma fête ne passera pas la nuit jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Tu apporteras à la maison de l’ Éternel, ton Dieu, les prémices des premiers fruits de ta terre. – Tu ne cuiras pas le chevreau dans le lait de sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Voici, j’envoie un ange devant toi, pour te garder dans le chemin, et pour t’amener au lieu que j’ai préparé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Prends garde à toi à cause de sa présence, et écoute sa voix; ne l’irrite pas; car il ne pardonnera point votre transgression, car mon nom est en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Mais si tu écoutes attentivement sa voix, et si tu fais tout ce que je dirai, je serai l’ennemi de tes ennemis et l’adversaire de tes adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Car mon Ange ira devant toi, et t’amènera vers l’Amoréen, et le Héthien, et le Phérézien, et le Cananéen, le Hévien, et le Jébusien, et je les exterminerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Tu ne te prosterneras point devant leurs dieux, et tu ne les serviras point, et tu ne feras pas selon leurs œuvres; mais tu les détruiras absolument, et tu briseras entièrement leurs stèles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Vous servirez l’ Éternel, votre Dieu, et il bénira ton pain et tes eaux, et j’ôterai la maladie du milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Il n’y aura pas de femelle qui avorte, ou qui soit stérile dans ton pays; j’accomplirai le nombre de tes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'J’enverrai ma frayeur devant toi, et je mettrai en déroute tout peuple contre lequel tu iras, et je ferai que tous tes ennemis tourneront le dos devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Et j’enverrai des frelons devant toi, et ils chasseront le Hévien, le Cananéen et le Héthien de devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Je ne les chasserai pas devant toi en une année, de peur que le pays ne devienne un désert et que les bêtes des champs ne se multiplient contre toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'je les chasserai peu à peu devant toi, jusqu’à ce que tu croisses en nombre, et que tu hérites le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Et j’ai établi tes limites depuis la mer Rouge jusqu’à la mer des Philistins, et depuis le désert jusqu’au fleuve; car je livrerai entre tes mains les habitants du pays, et tu les chasseras de devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Tu ne traiteras point alliance avec eux, ni avec leurs dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Ils n’habiteront pas dans ton pays, de peur qu’ils ne te fassent pécher contre moi, car tu servirais leurs dieux; certainement ce serait un piège pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, '*Et il dit à Moïse: Monte vers l’ Éternel, toi et Aaron, Nadab et Abihu, et 70 des anciens d’Israël, et vous vous prosternerez de loin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'et Moïse s’approchera seul de l’ Éternel; mais eux ne s’approcheront pas, et le peuple ne montera pas avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Et Moïse vint, et raconta au peuple toutes les paroles de l’ Éternel, et toutes les ordonnances. Et tout le peuple répondit d’une seule voix, et dit: Toutes les paroles que l’ Éternel a dites, nous les ferons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Et Moïse écrivit toutes les paroles de l’ Éternel; et il se leva de bon matin, et bâtit un autel au pied de la montagne, et [dressa] douze stèles pour les douze tribus d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'et il envoya des jeunes hommes des fils d’Israël qui offrirent des holocaustes, et sacrifièrent des taureaux à l’ Éternel en sacrifices de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Et Moïse prit la moitié du sang et le mit dans des bassins; et de la moitié du sang il fit aspersion sur l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Et il prit le livre de l’alliance, et le lut aux oreilles du peuple; et ils dirent: Tout ce que l’ Éternel a dit, nous le ferons, et nous écouterons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Et Moïse prit le sang, et en fit aspersion sur le peuple, et dit: Voici le sang de l’alliance que l’ Éternel a faite avec vous selon toutes ces paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Et Moïse et Aaron, Nadab et Abihu, et 70 des anciens d’Israël montèrent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'et ils virent le Dieu d’Israël, – et sous ses pieds comme un ouvrage de saphir transparent, et comme le ciel même en pureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Et il ne porta point sa main sur les nobles d’entre les fils d’Israël: ils virent Dieu, et ils mangèrent et burent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Et l’ Éternel dit à Moïse: Monte vers moi sur la montagne, et sois là; et je te donnerai les tables de pierre, et la loi et le commandement que j’ai écrits pour les instruire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Et Moïse se leva, avec Josué qui le servait; et Moïse monta sur la montagne de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'et il dit aux anciens: Attendez-nous ici jusqu’à ce que nous revenions à vous; et voici, Aaron et Hur sont avec vous: quiconque aura quelque affaire, qu’il aille à eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Et Moïse monta sur la montagne, et la nuée couvrit la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Et la gloire de l’ Éternel demeura sur la montagne de Sinaï, et la nuée la couvrit pendant six jours; et le septième jour il appela Moïse du milieu de la nuée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Et l’apparence de la gloire de l’ Éternel était comme un feu dévorant sur le sommet de la montagne, aux yeux des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Et Moïse entra au milieu de la nuée, et monta sur la montagne; et Moïse fut sur la montagne 40 jours et 40 nuits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Parle aux fils d’Israël, et qu’ils prennent pour moi une offrande élevée. Vous prendrez mon offrande élevée de tout homme qui aura un esprit libéral.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Et c’est ici l’offrande élevée que vous prendrez d’eux: de l’or, et de l’argent, et de l’airain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'et du bleu, et de la pourpre, et de l’écarlate, et du coton blanc, et du poil de chèvre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'et des peaux de béliers teintes en rouge, et des peaux de taissons, et du bois de sittim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'de l’huile pour le luminaire, des aromates pour l’huile de l’onction et pour l’encens des drogues odoriférantes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'des pierres d’onyx, et des pierres à enchâsser pour l’éphod et pour le pectoral.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Et ils feront pour moi un sanctuaire, et j’habiterai au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Selon tout ce que je te montre, le modèle du tabernacle et le modèle de tous ses ustensiles, ainsi vous ferez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Et ils feront une arche de bois de sittim: sa longueur sera de deux coudées et demie, et sa largeur d’une coudée et demie, et sa hauteur d’une coudée et demie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Et tu la plaqueras d’or pur; tu la plaqueras dedans et dehors, et tu y feras un couronnement d’or tout autour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'et tu fondras pour elle quatre anneaux d’or, et tu les mettras à ses quatre coins, deux anneaux à l’un de ses côtés, et deux anneaux à l’autre de ses côtés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Et tu feras des barres de bois de sittim, et tu les plaqueras d’or;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'et tu feras entrer les barres dans les anneaux, aux côtés de l’arche, pour porter l’arche par elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Les barres seront dans les anneaux de l’arche; on ne les en retirera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Et tu mettras dans l’arche le témoignage que je te donnerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, '– Et tu feras un propitiatoire d’or pur: sa longueur sera de deux coudées et demie, et sa largeur d’une coudée et demie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Et tu feras deux chérubins d’or; tu les feras d’or battu, aux deux bouts du propitiatoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Fais un chérubin au bout de deçà, et un chérubin au bout de delà: vous ferez les chérubins [tirés] du propitiatoire, à ses deux bouts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Et les chérubins étendront les ailes en haut, couvrant de leurs ailes le propitiatoire, et leurs faces seront l’une vis-à-vis de l’autre; les faces des chérubins seront [tournées] vers le propitiatoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Et tu mettras le propitiatoire sur l’arche, par-dessus, et tu mettras dans l’arche le témoignage que je te donnerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Et je me rencontrerai là avec toi, et je parlerai avec toi de dessus le propitiatoire, d’entre les deux chérubins qui seront sur l’arche du témoignage, [et te dirai] tout ce que je te commanderai pour les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Et tu feras une table de bois de sittim: sa longueur sera de deux coudées, et sa largeur d’une coudée, et sa hauteur d’une coudée et demie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Et tu la plaqueras d’or pur, et tu y feras un couronnement d’or tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Et tu y feras un rebord d’une paume tout autour, et tu feras un couronnement d’or à son rebord, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Et tu lui feras quatre anneaux d’or, et tu mettras les anneaux aux quatre coins qui seront à ses quatre pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Les anneaux seront près du rebord, pour recevoir les barres, pour porter la table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Et tu feras les barres de bois de sittim, et tu les plaqueras d’or; et avec elles on portera la table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Et tu feras ses plats, et ses coupes, et ses gobelets, et ses vases, avec lesquels on fera les libations; tu les feras d’or pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Et tu mettras sur la table le pain de proposition, devant moi, continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Et tu feras un chandelier d’or pur: le chandelier sera fait [d’or] battu; son pied, et sa tige, ses calices, ses pommes, et ses fleurs, seront [tirés] de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Et six branches sortiront de ses côtés, trois branches du chandelier d’un côté, et trois branches du chandelier de l’autre côté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Il y aura, sur une branche, trois calices en forme de fleur d’amandier, une pomme et une fleur; et, sur une [autre] branche, trois calices en forme de fleur d’amandier, une pomme et une fleur; ainsi pour les six branches sortant du chandelier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Et il y aura au chandelier quatre calices en forme de fleur d’amandier, ses pommes et ses fleurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'et une pomme sous deux branches [sortant] de lui, et une pomme sous deux branches [sortant] de lui, et une pomme sous deux branches [sortant] de lui, pour les six branches sortant du chandelier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'leurs pommes et leurs branches seront [tirées] de lui, le tout battu, d’une pièce, d’or pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, '– Et tu feras ses sept lampes; et on allumera ses lampes, afin qu’elles éclairent vis-à-vis de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Et ses mouchettes et ses vases à cendre seront d’or pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'On le fera, avec tous ces ustensiles, d’un talent d’or pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Regarde, et fais selon le modèle qui t’en est montré sur la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Et tu feras le tabernacle de dix tapis de fin coton retors, et de bleu, et de pourpre, et d’écarlate; tu les feras avec des chérubins, d’ouvrage d’art.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'La longueur d’un tapis sera de 28 coudées, et la largeur d’un tapis de quatre coudées: une même mesure pour tous les tapis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Cinq tapis seront joints l’un à l’autre, et cinq tapis seront joints l’un à l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Et tu feras des ganses de bleu sur le bord d’un tapis, à l’extrémité de l’assemblage; et tu feras de même au bord du tapis qui sera à l’extrémité dans le second assemblage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Tu feras 50 ganses à un tapis, et tu feras 50 ganses à l’extrémité du tapis qui est dans le second assemblage, les ganses seront vis-à-vis l’une de l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Et tu feras 50 agrafes d’or, et tu joindras les tapis l’un à l’autre par les agrafes, et ce sera un seul tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Et tu feras des tapis de poil de chèvre pour une tente [qui sera] par-dessus le tabernacle; tu feras onze de ces tapis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'la longueur d’un tapis sera de 30 coudées, et la largeur d’un tapis de quatre coudées: une même mesure pour les onze tapis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Et tu joindras cinq tapis à part, et six tapis à part; et tu replieras le sixième tapis sur le devant de la tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Et tu feras 50 ganses sur le bord du tapis qui sera à l’extrémité de l’assemblage, et 50 ganses sur le bord du tapis du second assemblage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Et tu feras 50 agrafes d’airain, et tu feras entrer les agrafes dans les ganses; et tu assembleras la tente, et elle sera une.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Et ce qui pend, le surplus des tapis de la tente, la moitié du tapis, savoir le surplus, pendra sur le derrière du tabernacle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'et la coudée deçà, et la coudée delà, qui est de surplus dans la longueur des tapis de la tente, pendront sur les côtés du tabernacle, deçà et delà, pour le couvrir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Et tu feras pour la tente une couverture de peaux de béliers teintes en rouge, et une couverture de peaux de taissons par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Et tu feras les ais pour le tabernacle; ils seront de bois de sittim, [placés] debout;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'la longueur d’un ais sera de dix coudées, et la largeur d’un ais d’une coudée et demie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Il y aura deux tenons à un ais, en façon d’échelons, l’un répondant à l’autre; tu feras de même pour tous les ais du tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Et tu feras les ais pour le tabernacle, 20 ais pour le côté du midi vers le sud;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'et tu feras 40 bases d’argent sous les 20 ais, deux bases sous un ais pour ses deux tenons, et deux bases sous un ais pour ses deux tenons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'et pour l’autre côté du tabernacle, du côté du nord, 20 ais,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'et leurs 40 bases d’argent, deux bases sous un ais, et deux bases sous un ais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Et pour le fond du tabernacle, vers l’occident, tu feras six ais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Et tu feras deux ais pour les angles du tabernacle, au fond;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'ils seront joints par le bas, et parfaitement unis ensemble par le haut dans un anneau; il en sera de même pour les deux; ils seront aux deux angles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Et il y aura huit ais, et leurs bases d’argent: 16 bases, deux bases sous un ais, et deux bases sous un ais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, '– Et tu feras des traverses de bois de sittim, cinq pour les ais d’un côté du tabernacle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'et cinq traverses pour les ais de l’autre côté du tabernacle, et cinq traverses pour les ais du côté du tabernacle, pour le fond, vers l’occident;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'et la traverse du milieu sera au milieu des ais, courant d’un bout à l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Et tu plaqueras d’or les ais, et tu feras d’or leurs anneaux qui recevront les traverses, et tu plaqueras d’or les traverses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Et tu dresseras le tabernacle selon son ordonnance qui t’a été montrée sur la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Et tu feras un voile de bleu, et de pourpre, et d’écarlate, et de fin coton retors; on le fera d’ouvrage d’art, avec des chérubins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'et tu le mettras sur quatre piliers de [bois de] sittim, plaqués d’or, et leurs crochets seront d’or; ils seront sur quatre bases d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Et tu mettras le voile au-dessous des agrafes, et tu mettras là, au-dedans du voile, l’arche du témoignage; et le voile fera séparation pour vous entre le lieu saint et le lieu très saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Et tu mettras le propitiatoire sur l’arche du témoignage, dans le lieu très saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Et tu placeras la table en dehors du voile, et le chandelier vis-à-vis de la table, sur le côté du tabernacle qui est vers le sud, et tu mettras la table sur le côté nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Et tu feras pour l’entrée de la tente un rideau de bleu, et de pourpre, et d’écarlate, et de fin coton retors, en ouvrage de brodeur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'et tu feras pour le rideau cinq piliers de bois de sittim, et tu les plaqueras d’or, et leurs crochets seront d’or; et tu fondras pour eux cinq bases d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Et tu feras l’autel de bois de sittim: [il aura] cinq coudées de long, et cinq coudées de large; l’autel sera carré, et sa hauteur sera de trois coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Et tu feras ses cornes à ses quatre coins; ses cornes seront [tirées] de lui; et tu le plaqueras d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Et tu feras ses vases à cendre, et ses pelles, et ses bassins, et ses fourchettes, et ses brasiers; tous ses ustensiles, tu les feras d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Et tu lui feras une grille en ouvrage de treillis, d’airain; et tu feras au treillis quatre anneaux d’airain, à ses quatre bouts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'et tu le mettras au-dessous du contour de l’autel, en bas, et le treillis ira jusqu’au milieu de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Et tu feras des barres pour l’autel, des barres de bois de sittim, et tu les plaqueras d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Et on fera entrer ses barres dans les anneaux; et les barres seront aux deux côtés de l’autel, pour le porter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Tu le feras creux, avec des planches, comme il t’a été montré sur la montagne; on le fera ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Et tu feras le parvis du tabernacle: pour le côté du midi vers le sud, des tentures de fin coton retors pour le parvis, de 100 coudées en longueur pour un côté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'et ses 20 piliers, et leurs 20 bases d’airain; les crochets des piliers et leurs baguettes d’attache seront en argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Et de même pour le côté du nord, dans la longueur, [tu feras] des tentures de 100 [coudées] en longueur, et ses 20 piliers, et leurs 20 bases d’airain; les crochets des piliers et leurs baguettes d’attache seront en argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Et [pour] la largeur du parvis du côté de l’occident, [tu feras] 50 coudées de tentures, leurs dix piliers et leurs dix bases.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Et la largeur du parvis du côté de l’orient, vers le levant, sera de 50 coudées:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, '[tu feras], pour l’un des côtés, 15 coudées de tentures, leurs trois piliers et leurs trois bases,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'et pour l’autre côté, 15 [coudées] de tentures, leurs trois piliers et leurs trois bases,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'et pour la porte du parvis, un rideau de 20 coudées, de bleu, et de pourpre, et d’écarlate, et de fin coton retors, en ouvrage de brodeur, ses quatre piliers et leurs quatre bases.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Tous les piliers du parvis, à l’entour, auront des baguettes d’attache en argent, leurs crochets, d’argent, et leurs bases, d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'La longueur du parvis sera de 100 coudées, et la largeur de 50 tout le long, et la hauteur de cinq coudées, en fin coton retors; et les bases des piliers seront d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Tous les ustensiles du tabernacle, pour tout son service, et tous ses pieux, et tous les pieux du parvis, seront d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Et toi, tu commanderas aux fils d’Israël, et ils t’apporteront de l’huile d’olive pure, broyée, pour le luminaire, pour faire luire les lampes continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Aaron et ses fils les arrangeront devant l’ Éternel, depuis le soir jusqu’au matin, dans la tente d’assignation, en dehors du voile qui est devant le témoignage. Ce sera de la part des fils d’Israël un statut perpétuel, en leurs générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '*Et toi, fais approcher de toi Aaron, ton frère, et ses fils avec lui, du milieu des fils d’Israël, pour exercer la sacrificature devant moi: Aaron, Nadab et Abihu, Éléazar et Ithamar, fils d’Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Et tu feras de saints vêtements à Aaron, ton frère, pour gloire et pour ornement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Et toi, tu parleras à tous les hommes intelligents que j’ai remplis de l’esprit de sagesse, et ils feront les vêtements d’Aaron pour le sanctifier, afin qu’il exerce la sacrificature devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Et ce sont ici les vêtements qu’ils feront: un pectoral, et un éphod, et une robe, et une tunique brodée, une tiare, et une ceinture; et ils feront les saints vêtements pour Aaron, ton frère, et pour ses fils, afin qu’ils exercent la sacrificature devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Et ils prendront de l’or, et du bleu, et de la pourpre, et de l’écarlate, et du fin coton;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'et ils feront l’éphod, d’or, de bleu, et de pourpre, d’écarlate, et de fin coton retors, en ouvrage d’art.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Il aura, à ses deux bouts, deux épaulières pour l’assembler; il sera ainsi joint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Et la ceinture de son éphod, qui sera par-dessus, sera du même travail, de la même matière, d’or, de bleu, et de pourpre, et d’écarlate, et de fin coton retors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, '– Et tu prendras deux pierres d’onyx, et tu graveras sur elles les noms des fils d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'six de leurs noms sur une pierre, et les six noms restants sur la seconde pierre, selon leur naissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Tu graveras, en ouvrage de lapidaire, en gravure de cachet, les deux pierres, d’après les noms des fils d’Israël; tu les feras enchâsser dans des chatons d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Et tu mettras les deux pierres sur les épaulières de l’éphod, comme pierres de mémorial pour les fils d’Israël; et Aaron portera leurs noms devant l’ Éternel, sur ses deux épaules, en mémorial.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Et tu feras des chatons d’or,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'et deux chaînettes d’or pur, à bouts; tu les feras en ouvrage de torsade; et tu attacheras les chaînettes en torsade aux chatons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Et tu feras le pectoral de jugement; tu le feras en ouvrage d’art, comme l’ouvrage de l’éphod; tu le feras d’or, de bleu, et de pourpre, et d’écarlate, et de fin coton retors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Il sera carré, double; sa longueur sera d’un empan, et sa largeur d’un empan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Et tu le garniras de pierres enchâssées, de quatre rangées de pierres: la première rangée, une sardoine, une topaze, et une émeraude;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'et la seconde rangée, une escarboucle, un saphir, et un diamant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'et la troisième rangée, une opale, une agate, et une améthyste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'et la quatrième rangée, une chrysolithe, un onyx, et un jaspe; elles seront enchâssées dans de l’or, dans leurs montures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Et les pierres seront selon les noms des fils d’Israël, douze, selon leurs noms, en gravure de cachet, chacune selon son nom; elles seront pour les douze tribus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, '– Et tu feras sur le pectoral des chaînettes à bouts, en ouvrage de torsade, d’or pur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'et tu feras sur le pectoral deux anneaux d’or; et tu mettras les deux anneaux aux deux bouts du pectoral;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'et tu mettras les deux torsades d’or dans les deux anneaux, aux bouts du pectoral;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'et tu mettras les deux bouts des deux torsades dans les deux chatons, et tu les mettras sur les épaulières de l’éphod, sur le devant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Et tu feras deux anneaux d’or, et tu les placeras aux deux bouts du pectoral, sur son bord qui est contre l’éphod, en dedans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Et tu feras deux anneaux d’or, et tu les mettras aux deux épaulières de l’éphod par en bas, sur le devant, juste à sa jointure au-dessus de la ceinture de l’éphod.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Et on attachera le pectoral par ses anneaux aux anneaux de l’éphod avec un cordon de bleu, afin qu’il soit au-dessus de la ceinture de l’éphod, et que le pectoral ne bouge pas de dessus l’éphod.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Et Aaron portera les noms des fils d’Israël au pectoral de jugement sur son cœur, lorsqu’il entrera dans le lieu saint, comme mémorial devant l’ Éternel, continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, '– Et tu mettras sur le pectoral de jugement les urim et les thummim, et ils seront sur le cœur d’Aaron, quand il entrera devant l’ Éternel; et Aaron portera le jugement des fils d’Israël sur son cœur, devant l’ Éternel, continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Et tu feras la robe de l’éphod entièrement de bleu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'et son ouverture pour la tête sera au milieu; il y aura une bordure à son ouverture, tout autour, en ouvrage de tisserand; elle l’aura comme l’ouverture d’une cotte de mailles: elle ne se déchirera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, '– Et tu feras sur ses bords des grenades de bleu, et de pourpre, et d’écarlate, sur ses bords, tout autour, et des clochettes d’or entre elles, tout autour:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'une clochette d’or et une grenade, une clochette d’or et une grenade, sur les bords de la robe, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Et Aaron en sera revêtu quand il fera le service; et on en entendra le son quand il entrera dans le lieu saint, devant l’ Éternel, et quand il en sortira, afin qu’il ne meure pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Et tu feras une lame d’or pur, et tu graveras sur elle, en gravure de cachet: Sainteté à l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'et tu la poseras sur un cordon de bleu, et elle sera sur la tiare; elle sera sur le devant de la tiare:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'et elle sera sur le front d’Aaron; et Aaron portera l’iniquité des choses saintes que les fils d’Israël auront sanctifiées, dans tous les dons de leurs choses saintes; et elle sera sur son front continuellement, pour être agréée pour eux devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Et tu broderas la tunique de fin coton; et tu feras la tiare de fin coton; et tu feras la ceinture en ouvrage de brodeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Et pour les fils d’Aaron tu feras des tuniques, et tu leur feras des ceintures, et tu leur feras des bonnets, pour gloire et pour ornement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Et tu en revêtiras Aaron, ton frère, et ses fils avec lui; et tu les oindras, et tu les consacreras, et tu les sanctifieras, afin qu’ils exercent la sacrificature devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Et tu leur feras des caleçons de lin pour couvrir la nudité de leur chair; ils iront des reins jusqu’aux cuisses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Et ils seront sur Aaron et sur ses fils lorsqu’ils entreront dans la tente d’assignation ou lorsqu’ils s’approcheront de l’autel pour faire le service dans le lieu saint, afin qu’ils ne portent pas d’iniquité et ne meurent pas. [C’est] un statut perpétuel, pour lui et pour sa semence après lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Et c’est ici ce que tu feras pour eux, afin de les sanctifier pour exercer la sacrificature devant moi. Prends un jeune taureau et deux béliers sans défaut,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'et du pain sans levain, et des gâteaux sans levain, pétris à l’huile, et des galettes sans levain ointes d’huile; tu les feras de fine farine de froment;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'et tu les mettras dans une corbeille, et tu les présenteras dans la corbeille, et le jeune taureau et les deux béliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Et tu feras approcher Aaron et ses fils à l’entrée de la tente d’assignation, et tu les laveras avec de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Et tu prendras les vêtements, et tu feras revêtir à Aaron la tunique et la robe de l’éphod, et l’éphod, et le pectoral, et tu le ceindras avec la ceinture de l’éphod;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'et tu placeras la tiare sur sa tête, et tu mettras le saint diadème sur la tiare.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Et tu prendras l’huile de l’onction, et tu la verseras sur sa tête, et tu l’oindras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Et tu feras approcher ses fils, et tu les revêtiras des tuniques;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'et tu les ceindras de la ceinture, Aaron et ses fils, et tu leur attacheras les bonnets; et la sacrificature sera pour eux un statut perpétuel: et tu consacreras Aaron et ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Et tu feras approcher le jeune taureau devant la tente d’assignation, et Aaron et ses fils poseront leurs mains sur la tête du taureau,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'et tu égorgeras le taureau devant l’ Éternel, à l’entrée de la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'et tu prendras du sang du taureau, et tu le mettras avec ton doigt sur les cornes de l’autel, et tu verseras tout le sang au pied de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Et tu prendras toute la graisse qui couvre l’intérieur, et le réseau qui est sur le foie, et les deux rognons et la graisse qui est dessus, et tu les feras fumer sur l’autel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'et tu brûleras au feu, hors du camp, la chair du taureau, et sa peau, et sa fiente: c’est un sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Puis tu prendras l’un des béliers, et Aaron et ses fils poseront leurs mains sur la tête du bélier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'et tu égorgeras le bélier, et tu prendras son sang, et tu en feras aspersion sur l’autel, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Et tu couperas le bélier en morceaux; et tu laveras son intérieur et ses jambes, et tu les mettras sur ses morceaux et sur sa tête;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'et tu feras fumer tout le bélier sur l’autel: c’est un holocauste à l’ Éternel, une odeur agréable; c’est un sacrifice par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Et tu prendras le second bélier, et Aaron et ses fils poseront leurs mains sur la tête du bélier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'et tu égorgeras le bélier, et tu prendras de son sang, et tu le mettras sur le lobe de l’oreille droite d’Aaron, et sur le lobe de l’oreille droite de ses fils, et sur le pouce de leur main droite, et sur le gros orteil de leur pied droit; et tu feras aspersion du sang sur l’autel, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Et tu prendras du sang qui sera sur l’autel, et de l’huile de l’onction, et tu en feras aspersion sur Aaron et sur ses vêtements, et sur ses fils et sur les vêtements de ses fils avec lui: et il sera saint, lui et ses vêtements, et ses fils et les vêtements de ses fils avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, '– Et tu prendras la graisse du bélier, et la queue, et la graisse qui couvre l’intérieur, et le réseau du foie, et les deux rognons et la graisse qui est dessus, et l’épaule droite (car c’est un bélier de consécration),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'et un pain, et un gâteau de pain à l’huile, et une galette de la corbeille des pains sans levain qui sera devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'et tu mettras le tout sur les paumes des mains d’Aaron, et sur les paumes des mains de ses fils, et tu les tournoieras comme offrande tournoyée devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'et tu les prendras de leurs mains, et tu les feras fumer sur l’autel, sur l’holocauste, en odeur agréable devant l’ Éternel: c’est un sacrifice par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Et tu prendras la poitrine du bélier de consécration qui est pour Aaron, et tu la tournoieras comme offrande tournoyée devant l’ Éternel; et ce sera ta part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Et tu sanctifieras la poitrine tournoyée et l’épaule élevée, [ce] qui aura été tournoyé et [ce] qui aura été élevé du bélier de consécration, de celui qui est pour Aaron et de celui qui est pour ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Et cela sera pour Aaron et pour ses fils un statut perpétuel, de la part des fils d’Israël, car c’est une offrande élevée: et ce sera une offrande élevée de la part des fils d’Israël, de leurs sacrifices de prospérités, leur offrande élevée à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Et les saints vêtements qui sont pour Aaron seront pour ses fils après lui, afin qu’ils soient oints et consacrés dans ces vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Celui d’entre ses fils qui sera sacrificateur à sa place, qui entrera dans la tente d’assignation pour faire le service dans le lieu saint, les revêtira pendant sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Et tu prendras le bélier de consécration, et tu feras cuire sa chair dans un lieu saint;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'et Aaron et ses fils mangeront, à l’entrée de la tente d’assignation, la chair du bélier, et le pain qui sera dans la corbeille:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'ils mangeront ces choses par lesquelles la propitiation aura été faite, pour les consacrer et les sanctifier: mais nul étranger n’en mangera, car elles sont saintes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Et s’il reste de la chair des consécrations, ou du pain, jusqu’au matin, tu brûleras ce reste au feu; il ne sera pas mangé, car il est saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tu feras ainsi pour Aaron et pour ses fils, selon tout ce que je t’ai commandé; tu mettras sept jours à les consacrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Et tu offriras comme sacrifice pour le péché, chaque jour, un jeune taureau, pour [faire] propitiation, et tu purifieras l’autel en faisant propitiation pour lui; et tu l’oindras pour le sanctifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Pendant sept jours, tu feras propitiation pour l’autel, et tu le sanctifieras, et l’autel sera une chose très sainte; quiconque touchera l’autel sera saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Et voici ce que tu offriras sur l’autel: deux agneaux d’un an, chaque jour, continuellement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'tu offriras l’un des agneaux le matin, et le second agneau tu l’offriras entre les deux soirs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'et un dixième de fleur de farine, pétrie avec un quart de hin d’huile broyée, et une libation d’un quart de hin de vin, pour un agneau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Et tu offriras le second agneau entre les deux soirs; tu l’offriras avec la même offrande de gâteau qu’au matin, et la même libation, en odeur agréable, un sacrifice par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Ce sera l’holocauste continuel en vos générations, à l’entrée de la tente d’assignation, devant l’ Éternel, où je me rencontrerai avec vous pour y parler avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Et je me rencontrerai là avec les fils d’Israël, et la tente sera sanctifiée par ma gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Et je sanctifierai la tente d’assignation et l’autel; et je sanctifierai Aaron et ses fils, afin qu’ils exercent la sacrificature devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Et j’habiterai au milieu des fils d’Israël, et je leur serai Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'et ils sauront que moi, l’ Éternel, je suis leur Dieu, qui les ai fait sortir du pays d’Égypte, pour habiter au milieu d’eux. Je suis l’ Éternel, leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '*Et tu feras un autel pour faire fumer l’encens; tu le feras de bois de sittim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'sa longueur sera d’une coudée, et sa largeur d’une coudée; il sera carré; et sa hauteur sera de deux coudées; ses cornes seront [tirées] de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Et tu le plaqueras d’or pur, le dessus et ses parois, tout autour, et ses cornes. Et tu lui feras un couronnement d’or tout autour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'et tu lui feras deux anneaux d’or au-dessous de son couronnement, sur ses deux côtés; tu les feras à ses deux coins, et ils serviront à recevoir les barres, pour le porter par elles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'et tu feras les barres de bois de sittim, et tu les plaqueras d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Et tu le mettras vis-à-vis du voile qui est devant l’arche du témoignage, vis-à-vis du propitiatoire qui est sur le témoignage, où je me rencontrerai avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Et Aaron y fera fumer l’encens des drogues odoriférantes; chaque matin, il le fera fumer quand il arrangera les lampes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Et quand Aaron allumera les lampes, entre les deux soirs, il le fera fumer, – un encens continuel devant l’ Éternel, en vos générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Vous n’y brûlerez pas d’encens étranger, ni d’holocauste, ni d’offrande de gâteau; et vous n’y verserez pas de libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Et Aaron fera propitiation pour les cornes de l’autel une fois l’an; il fera propitiation pour l’autel une fois l’an, en vos générations, avec le sang du sacrifice de péché des propitiations. C’est une chose très sainte à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Quand tu relèveras le nombre des fils d’Israël selon leur dénombrement, ils donneront chacun une rançon de son âme à l’ Éternel, lorsque tu en feras le dénombrement, afin qu’il n’y ait pas de plaie au milieu d’eux quand tu en feras le dénombrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Voici ce que donneront tous ceux qui passeront par le dénombrement: un demi-sicle, selon le sicle du sanctuaire, à 20 guéras le sicle, un demi-sicle en offrande à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Tous ceux qui passeront par le dénombrement, depuis l’âge de 20 ans et au-dessus, donneront l’offrande de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Le riche n’augmentera pas, et le pauvre ne diminuera pas le demi-sicle, lorsque vous donnerez l’offrande de l’ Éternel pour faire propitiation pour vos âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Et tu prendras des fils d’Israël l’argent de la propitiation, et tu le donneras pour le service de la tente d’assignation, et il sera pour les fils d’Israël un mémorial devant l’ Éternel, afin de faire propitiation pour vos âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Tu feras aussi une cuve d’airain, et son soubassement d’airain, pour s’y laver; et tu la mettras entre la tente d’assignation et l’autel, et tu y mettras de l’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'et Aaron et ses fils y laveront leurs mains et leurs pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Quand ils entreront dans la tente d’assignation, ils se laveront avec de l’eau, afin qu’ils ne meurent pas, ou quand ils s’approcheront de l’autel pour faire le service, pour faire fumer le sacrifice fait par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Ils laveront leurs mains et leurs pieds, afin qu’ils ne meurent pas; et ce leur sera un statut perpétuel, pour Aaron et pour sa semence, en leurs générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Toi, prends des aromates les plus excellents: de la myrrhe franche, 500 [sicles], et du cinnamome aromatique, moitié autant, 250 [sicles], et du roseau aromatique, 250,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'et de la casse, 500, selon le sicle du sanctuaire, et un hin d’huile d’olive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Et tu en feras une huile pour l’onction sainte, une préparation composée, d’ouvrage de parfumeur: ce sera l’huile de l’onction sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Et tu en oindras la tente d’assignation, et l’arche du témoignage,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'et la table et tous ses ustensiles, et le chandelier et ses ustensiles, et l’autel de l’encens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'et l’autel de l’holocauste et tous ses ustensiles, et la cuve et son soubassement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'et tu les sanctifieras, et ils seront très saints; quiconque les touchera sera saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Et tu oindras Aaron et ses fils, et tu les sanctifieras pour exercer la sacrificature devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, '– Et tu parleras aux fils d’Israël, disant: Ce sera pour moi l’huile de l’onction sainte en vos générations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'on n’en versera pas sur la chair de l’homme, et vous n’en ferez point de semblable dans ses proportions: elle est sainte, elle vous sera sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Quiconque en composera de semblable, et en mettra sur un étranger, sera retranché de ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Et l’ Éternel dit à Moïse: Prends des drogues odoriférantes, du stacte, et de la coquille odorante, et du galbanum, – des drogues odoriférantes, et de l’encens pur: de tout, à poids égal;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'et tu en feras un encens composé, d’ouvrage de parfumeur, salé, pur, saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Et tu en pileras très fin, et tu en mettras sur le devant du témoignage dans la tente d’assignation, où je me rencontrerai avec toi: ce vous sera une chose très sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Et quant à l’encens que tu feras, vous n’en ferez point pour vous selon les mêmes proportions: il sera, pour toi, saint, [consacré] à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Quiconque en fera de semblable pour le flairer, sera retranché de ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Regarde, j’ai appelé par nom Betsaleël, fils d’Uri, fils de Hur, de la tribu de Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'et je l’ai rempli de l’esprit de Dieu, en sagesse, et en intelligence, et en connaissance, et pour toutes sortes d’ouvrages,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'pour faire des inventions: pour travailler en or, et en argent, et en airain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'pour tailler des pierres à enchâsser, et pour tailler le bois, afin d’exécuter toutes sortes d’ouvrages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Et voici, j’ai donné avec lui Oholiab, fils d’Akhisamac, de la tribu de Dan; et j’ai mis de la sagesse dans le cœur de tout homme intelligent, afin qu’ils fassent tout ce que je t’ai commandé:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'la tente d’assignation, et l’arche du témoignage, et le propitiatoire qui sera dessus, et tous les ustensiles de la tente,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'et la table et ses ustensiles, et le chandelier pur et tous ses ustensiles, et l’autel de l’encens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'et l’autel de l’holocauste et tous ses ustensiles, et la cuve et son soubassement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'et les vêtements de service, et les saints vêtements d’Aaron, le sacrificateur, et les vêtements de ses fils, pour exercer la sacrificature,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'et l’huile de l’onction, et l’encens des drogues odoriférantes pour le lieu saint. Ils feront selon tout ce que je t’ai commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Toi, parle aux fils d’Israël, disant: Certainement, vous garderez mes sabbats, car c’est un signe entre moi et vous, en vos générations, pour que vous sachiez que c’est moi, l’ Éternel, qui vous sanctifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Et vous garderez le sabbat, car il vous sera saint: celui qui le profanera sera certainement mis à mort, car quiconque fera une œuvre en ce jour-là,... cette âme sera retranchée du milieu de ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Pendant six jours le travail se fera, et le septième jour est le sabbat de repos consacré à l’ Éternel: quiconque fera une œuvre le jour du sabbat, sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Et les fils d’Israël garderont le sabbat, pour observer le sabbat en leurs générations, – une alliance perpétuelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'C’est un signe entre moi et les fils d’Israël, à toujours; car en six jours l’ Éternel a fait les cieux et la terre, et le septième jour il s’est reposé, et a été rafraîchi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Et lorsqu’il eut achevé de parler avec Moïse sur la montagne de Sinaï, il lui donna les deux tables du témoignage, tables de pierre, écrites du doigt de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, '*Et quand le peuple vit que Moïse tardait à descendre de la montagne, le peuple s’assembla auprès d’Aaron, et ils lui dirent: Lève-toi, fais-nous un dieu qui aille devant nous; car ce Moïse, cet homme qui nous a fait monter du pays d’Égypte, nous ne savons ce qui lui est arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Et Aaron leur dit: Brisez les pendants d’or qui sont aux oreilles de vos femmes, de vos fils et de vos filles, et apportez-les-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Et tout le peuple arracha les pendants d’or qui étaient à leurs oreilles, et ils les apportèrent à Aaron;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'et il les prit de leurs mains, et il forma l’or avec un ciseau, et il en fit un veau de fonte. Et ils dirent: C’est ici ton dieu, ô Israël! qui t’a fait monter du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Et Aaron vit [le veau], et bâtit un autel devant lui; et Aaron cria, et dit: Demain, une fête à l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Et le lendemain, ils se levèrent de bonne heure, et offrirent des holocaustes, et amenèrent des sacrifices de prospérités. Et le peuple s’assit pour manger et pour boire, et ils se levèrent pour se divertir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Et l’ Éternel dit à Moïse: Va, descends; car ton peuple, que tu as fait monter du pays d’Égypte, s’est corrompu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'ils se sont vite détournés du chemin que je leur avais commandé; ils se sont fait un veau de fonte, et se sont prosternés devant lui, et lui ont sacrifié, et ont dit: C’est ici ton dieu, ô Israël! qui t’a fait monter du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Et l’ Éternel dit à Moïse: J’ai vu ce peuple, et voici, c’est un peuple de cou roide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Et maintenant laisse-moi faire, afin que ma colère s’embrase contre eux, et que je les consume; et je ferai de toi une grande nation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Et Moïse implora l’ Éternel, son Dieu, et dit: Pourquoi, ô Éternel, ta colère s’embraserait-elle contre ton peuple, que tu as fait sortir du pays d’Égypte, avec grande puissance et à main forte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Pourquoi les Égyptiens parleraient-ils, disant: C’est pour leur mal qu’il les a fait sortir, pour les tuer dans les montagnes, et pour les consumer de dessus la face de la terre? Reviens de l’ardeur de ta colère, et repens-toi du mal [que tu veux faire] à ton peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Souviens-toi d’Abraham, d’Isaac, et d’Israël, tes serviteurs, auxquels tu as juré par toi-même, et auxquels tu as dit: Je multiplierai votre semence comme les étoiles des cieux, et je donnerai à votre semence tout ce pays dont j’ai parlé, et ils l’hériteront pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Et l’ Éternel se repentit du mal qu’il avait dit qu’il ferait à son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Et Moïse se tourna, et descendit de la montagne, les deux tables du témoignage dans sa main: les tables étaient écrites de leurs deux côtés; elles étaient écrites deçà et delà.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Et les tables étaient l’ouvrage de Dieu, et l’écriture était l’écriture de Dieu, gravée sur les tables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, '– Et Josué entendit la voix du peuple qui jetait des cris, et il dit à Moïse: Il y a un bruit de guerre au camp!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Et [Moïse] dit: Ce n’est pas un bruit de cris de victoire, ni un bruit de cris de défaite; j’entends une voix de gens qui chantent en s’entre-répondant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, '– Et il arriva que, lorsque [Moïse] s’approcha du camp, il vit le veau et les danses; et la colère de Moïse s’embrasa, et il jeta de ses mains les tables, et les brisa au pied de la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Et il prit le veau qu’ils avaient fait, et le brûla au feu, et le moulut jusqu’à ce qu’il fut en poudre; puis il le répandit sur la surface de l’eau, et en fit boire aux fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Et Moïse dit à Aaron: Que t’a fait ce peuple, pour que tu aies fait venir sur lui un si grand péché?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Et Aaron dit: Que la colère de mon seigneur ne s’embrase point; tu connais le peuple, qu’il est [plongé] dans le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Or ils m’ont dit: Fais-nous un dieu qui marche devant nous; car ce Moïse, cet homme qui nous a fait monter du pays d’Égypte, nous ne savons ce qui lui est arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Et je leur ai dit: Qui a de l’or? Ils l’ont arraché, et me l’ont donné; et je l’ai jeté au feu, et il en est sorti ce veau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Et Moïse vit que le peuple était dans le désordre; car Aaron l’avait livré au désordre, pour leur honte parmi leurs adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Et Moïse se tint à la porte du camp, et dit: À moi, quiconque est pour l’ Éternel! Et tous les fils de Lévi se rassemblèrent vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Et il leur dit: Ainsi dit l’ Éternel, le Dieu d’Israël: Que chacun mette son épée sur sa cuisse; passez et revenez d’une porte à l’autre dans le camp, et que chacun de vous tue son frère, et chacun son compagnon, et chacun son intime ami.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Et les fils de Lévi firent selon la parole de Moïse; et il tomba d’entre le peuple, ce jour-là, environ 3 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Et Moïse dit: Consacrez-vous aujourd’hui à l’ Éternel, chacun dans son fils et dans son frère, afin de faire venir aujourd’hui sur vous [une] bénédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Et il arriva, le lendemain, que Moïse dit au peuple: Vous avez commis un grand péché, et maintenant je monterai vers l’ Éternel: peut-être ferai-je propitiation pour votre péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Et Moïse retourna vers l’ Éternel, et dit: Hélas! ce peuple a commis un grand péché, et ils se sont fait un dieu d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Et maintenant, si tu pardonnes leur péché...; sinon, efface-moi, je te prie, de ton livre que tu as écrit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Et l’ Éternel dit à Moïse: Celui qui aura péché contre moi, je l’effacerai de mon livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Et maintenant, va, conduis le peuple où je t’ai dit. Voici, mon Ange ira devant toi: et le jour où je visiterai, je visiterai sur eux leur péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Et l’ Éternel frappa le peuple, parce qu’ils avaient fait le veau qu’Aaron avait fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, '*Et l’ Éternel dit à Moïse: Va, monte d’ici, toi et le peuple que tu as fait monter du pays d’Égypte, dans le pays que j’ai promis par serment à Abraham, à Isaac, et à Jacob, disant: Je le donnerai à ta semence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'et j’enverrai un ange devant toi, et je chasserai le Cananéen, l’Amoréen, et le Héthien, et le Phérézien, le Hévien, et le Jébusien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, '– dans un pays ruisselant de lait et de miel; car je ne monterai pas au milieu de toi, car tu es un peuple de cou roide; de peur que je ne te consume en chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Et le peuple entendit cette parole fâcheuse, et mena deuil, et personne ne mit ses ornements sur soi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Or l’ Éternel avait dit à Moïse: Dis aux fils d’Israël: Vous êtes un peuple de cou roide; je monterai en un instant au milieu de toi, et je te consumerai; et maintenant, ôte tes ornements de dessus toi, et je saurai ce que je te ferai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Et les fils d’Israël se dépouillèrent de leurs ornements, à la montagne de Horeb.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Et Moïse prit une tente, et la tendit pour lui hors du camp, loin du camp, et il l’appela la tente d’assignation; et il arriva que tous ceux qui cherchaient l’ Éternel sortirent vers la tente d’assignation qui était hors du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Et il arriva que, lorsque Moïse sortit vers la tente, tout le peuple se leva, et se tint chacun à l’entrée de sa tente, et suivit des yeux Moïse, jusqu’à ce qu’il entra dans la tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Et il arriva que, comme Moïse entrait dans la tente, la colonne de nuée descendit, et se tint à l’entrée de la tente, et [l’ Éternel] parla avec Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Et tout le peuple vit la colonne de nuée se tenant à l’entrée de la tente; et tout le peuple se leva, et ils se prosternèrent, chacun à l’entrée de sa tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Et l’ Éternel parlait à Moïse face à face, comme un homme parle avec son ami; et [Moïse] retournait au camp; et son serviteur Josué, fils de Nun, jeune homme, ne sortait pas de l’intérieur de la tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Et Moïse dit à l’ Éternel: Regarde, tu me dis: Fais monter ce peuple; et tu ne m’as pas fait connaître celui que tu enverras avec moi; et tu as dit: Je te connais par nom, et tu as aussi trouvé grâce à mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Et maintenant, je te prie, si j’ai trouvé grâce à tes yeux, fais-moi connaître, je te prie, ton chemin, et je te connaîtrai, afin que je trouve grâce à tes yeux; et considère que cette nation est ton peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Et [l’ Éternel] dit: Ma face ira, et je te donnerai du repos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Et [Moïse] lui dit: Si ta face ne vient pas, ne nous fais pas monter d’ici;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'car à quoi connaîtra-t-on que j’ai trouvé grâce à tes yeux, moi et ton peuple? Ne sera-ce pas en ce que tu marcheras avec nous? Ainsi, moi et ton peuple, nous serons séparés de tout peuple qui est sur la face de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Et l’ Éternel dit à Moïse: Je ferai cela aussi dont tu as parlé; car tu as trouvé grâce à mes yeux, et je te connais par nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Et [Moïse] dit: Fais-moi voir, je te prie, ta gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Et il dit: Je ferai passer toute ma bonté devant ta face, et je crierai le nom de l’ Éternel devant toi; et je ferai grâce à qui je ferai grâce, et je ferai miséricorde à qui je ferai miséricorde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Et il dit: Tu ne peux pas voir ma face, car l’homme ne peut me voir et vivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Et l’ Éternel dit: Voici un lieu près de moi, et tu te tiendras sur le rocher;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'et il arrivera, quand ma gloire passera, que je te mettrai dans la fente du rocher, et je te couvrirai de ma main jusqu’à ce que je sois passé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'puis je retirerai ma main, et tu me verras par-derrière; mais ma face ne se verra pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Et l’ Éternel dit à Moïse: Taille-toi deux tables de pierre comme les premières, et j’écrirai sur les tables les paroles qui étaient sur les premières tables que tu as brisées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Et sois prêt au matin, et monte au matin sur la montagne de Sinaï, et tiens-toi là devant moi, sur le sommet de la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Et personne ne montera avec toi, et même personne ne sera vu sur toute la montagne, et ni le menu ni le gros bétail ne paîtra devant cette montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Et Moïse tailla deux tables de pierre comme les premières, et se leva de bon matin, et monta sur la montagne de Sinaï, comme l’ Éternel le lui avait commandé, et prit en sa main les deux tables de pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Et l’ Éternel descendit dans la nuée, et se tint là avec lui, et cria le nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Et l’ Éternel passa devant lui, et cria: L’ Éternel, l’ Éternel! ✶Dieu, miséricordieux et faisant grâce, lent à la colère, et grand en bonté et en vérité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'gardant la bonté envers des milliers [de générations], pardonnant l’iniquité, la transgression et le péché, et qui ne tient nullement [celui qui en est coupable] pour innocent, qui visite l’iniquité des pères sur les fils, et sur les fils des fils, sur la troisième et sur la quatrième [génération]!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Et Moïse se hâta, et s’inclina jusqu’à terre, et se prosterna,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'et dit: Si j’ai trouvé grâce à tes yeux, Seigneur, que le Seigneur marche, je te prie, au milieu de nous; car c’est un peuple de cou roide; et pardonne nos iniquités et nos péchés, et prends-nous pour héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Et il dit: Voici, j’établis une alliance: devant tout ton peuple, je ferai des merveilles qui n’ont pas été opérées sur toute la terre, ni en aucune nation; et tout le peuple, au milieu duquel tu es, verra l’œuvre de l’ Éternel; car ce que je vais faire avec toi est une chose terrible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, '– Garde ce que je te commande aujourd’hui: Voici, je vais chasser de devant toi l’Amoréen, et le Cananéen, et le Héthien, et le Phérézien, et le Hévien, et le Jébusien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Garde -toi de traiter alliance avec l’habitant du pays dans lequel tu vas entrer, de peur qu’il ne soit en piège au milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Mais vous démolirez leurs autels, et vous briserez leurs statues, et vous abattrez leurs ashères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Car tu ne te prosterneras point devant un autre ✶dieu (car l’ Éternel dont le nom est Jaloux, est un ✶Dieu jaloux):');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'de peur que tu ne traites une alliance avec les habitants du pays, et que lorsqu’ils se prostituent après leurs dieux et sacrifient à leurs dieux, on ne t’invite, et que tu ne manges de leur sacrifice,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'et que tu ne prennes de leurs filles pour tes fils, et que leurs filles ne se prostituent après leurs dieux et ne fassent que tes fils se prostituent après leurs dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, '– Tu ne te feras point de dieu de fonte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, '– Tu garderas la fête des pains sans levain: pendant sept jours tu mangeras des pains sans levain, comme je te l’ai commandé, au temps fixé du mois d’Abib; car c’est au mois d’Abib que tu es sorti d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, '– Tout ce qui ouvre la matrice est à moi, et tout ce qui naît mâle de ton bétail, le premier-né, tant du gros que du menu bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Et le premier-né de l’âne, tu le rachèteras avec un agneau; et si tu ne le rachètes pas, tu lui briseras la nuque. Tout premier-né de tes fils, tu le rachèteras; et on ne paraîtra pas à vide devant ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, '– Six jours tu travailleras, et le septième jour, tu te reposeras; tu te reposeras, [même] au temps du labourage et de la moisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, '– Et tu feras la fête des semaines, des premiers fruits de la moisson du froment, et la fête de la récolte, à la fin de l’année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, '– Trois fois l’an, tout mâle d’entre vous paraîtra devant la face du Seigneur, l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Car je déposséderai les nations devant toi, et j’élargirai tes limites; et nul ne désirera ton pays, lorsque tu monteras pour paraître devant la face de l’ Éternel, ton Dieu, trois fois l’an.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, '– Tu n’offriras pas le sang de mon sacrifice avec du pain levé; et le sacrifice de la fête de la Pâque ne passera pas la nuit jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Tu apporteras à la maison de l’ Éternel, ton Dieu, les prémices des premiers fruits de ta terre. – Tu ne cuiras pas le chevreau dans le lait de sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Et l’ Éternel dit à Moïse: Écris ces paroles; car, selon la teneur de ces paroles, j’ai fait alliance avec toi et avec Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Et [Moïse] fut là avec l’ Éternel 40 jours et 40 nuits; il ne mangea point de pain et il ne but point d’eau; et [l’ Éternel] écrivit sur les tables les paroles de l’alliance, les dix paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, '*Et il arriva que, lorsque Moïse descendit de la montagne de Sinaï (et les deux tables du témoignage étaient dans la main de Moïse lorsqu’il descendit de la montagne), Moïse ne savait pas que la peau de son visage rayonnait parce qu’il avait parlé avec Lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Et Aaron et tous les fils d’Israël virent Moïse, et voici, la peau de son visage rayonnait, et ils craignirent de s’approcher de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'et Moïse les appela, et Aaron et tous les princes de l’assemblée revinrent auprès de lui, et Moïse leur parla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Et après cela, tous les fils d’Israël s’approchèrent, et il leur commanda tout ce que l’ Éternel lui avait dit sur la montagne de Sinaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Et Moïse cessa de parler avec eux: or il avait mis un voile sur son visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Et lorsque Moïse entrait devant l’ Éternel pour parler avec lui, il ôtait le voile jusqu’à ce qu’il sorte; puis il sortait et disait aux fils d’Israël ce qui lui avait été commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Et les fils d’Israël voyaient le visage de Moïse, que la peau du visage de Moïse rayonnait; et Moïse remettait le voile sur son visage jusqu’à ce qu’il entre pour parler avec Lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, '*Et Moïse réunit toute l’assemblée des fils d’Israël, et leur dit: Ce sont ici les choses que l’ Éternel a commandé de faire:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Pendant six jours le travail se fera, mais le septième jour sera pour vous un [jour] saint, un sabbat de repos [consacré] à l’ Éternel: quiconque fera une œuvre ce jour-là, sera mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Vous n’allumerez point de feu, dans toutes vos habitations, le jour du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Et Moïse parla à toute l’assemblée des fils d’Israël, en disant: Voici ce que l’ Éternel a commandé, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Prenez, de ce qui est à vous, une offrande pour l’ Éternel; que tout homme qui a un esprit libéral apporte l’offrande élevée de l’ Éternel: de l’or, et de l’argent, et de l’airain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'et du bleu, et de la pourpre, et de l’écarlate, et du coton blanc, et du poil de chèvre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'et des peaux de béliers teintes en rouge, et des peaux de taissons, et du bois de sittim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'et de l’huile pour le luminaire, et des aromates pour l’huile de l’onction et pour l’encens des drogues odoriférantes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'et des pierres d’onyx, et des pierres à enchâsser pour l’éphod et pour le pectoral.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, '– Et que tous les hommes intelligents parmi vous viennent, et fassent tout ce que l’ Éternel a commandé:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'le tabernacle, sa tente, et sa couverture, ses agrafes, et ses ais, ses traverses, ses piliers, et ses bases;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'l’arche et ses barres, le propitiatoire, et le voile qui sert de rideau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'la table et ses barres, et tous ses ustensiles, et le pain de proposition;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'et le chandelier du luminaire, et ses ustensiles, et ses lampes, et l’huile du luminaire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'et l’autel de l’encens et ses barres; et l’huile de l’onction, et l’encens des drogues odoriférantes; et le rideau de l’entrée, pour l’entrée du tabernacle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'l’autel de l’holocauste et la grille d’airain qui lui appartient, ses barres et tous ses ustensiles; la cuve et son soubassement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'les tentures du parvis, ses piliers, et ses bases, et le rideau de la porte du parvis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'les pieux du tabernacle, et les pieux du parvis, et leurs cordages;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'les vêtements de service pour servir dans le lieu saint, les saints vêtements pour Aaron, le sacrificateur, et les vêtements de ses fils pour exercer la sacrificature.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Et toute l’assemblée des fils d’Israël sortit de devant Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Et tout homme que son cœur y porta, et tous ceux qui avaient un esprit libéral, vinrent et apportèrent l’offrande de l’ Éternel pour l’œuvre de la tente d’assignation, et pour tout son service, et pour les saints vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Et les hommes vinrent avec les femmes: tout homme qui offrit une offrande tournoyée d’or à l’ Éternel, tous ceux qui avaient un esprit libéral apportèrent des anneaux de nez, et des pendants d’oreille, et des anneaux, et des colliers, toutes sortes d’objets d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Et tout homme chez qui se trouva du bleu, et de la pourpre, et de l’écarlate, et du coton blanc, et du poil de chèvre, et des peaux de béliers teintes en rouge, et des peaux de taissons, les apporta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Tout [homme] qui offrit une offrande élevée d’argent et d’airain, apporta l’offrande de l’ Éternel; et tout [homme] chez qui se trouva du bois de sittim pour toute l’œuvre du service, l’apporta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Et toute femme intelligente fila de sa main, et apporta ce qu’elle avait filé: le bleu, et la pourpre, et l’écarlate, et le fin coton;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'et toutes les femmes habiles que leur cœur y porta filèrent du poil de chèvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Et les princes apportèrent les pierres d’onyx et les pierres à enchâsser pour l’éphod et pour le pectoral;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'et les aromates, et l’huile pour le luminaire, et pour l’huile de l’onction, et pour l’encens des drogues odoriférantes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Les fils d’Israël, tout homme et toute femme qui eurent un esprit libéral pour apporter pour toute l’œuvre que, par Moïse, l’ Éternel avait commandé de faire, apportèrent une offrande volontaire à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Et Moïse dit aux fils d’Israël: Voyez, l’ Éternel a appelé par nom Betsaleël, fils d’Uri, fils de Hur, de la tribu de Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'et il l’a rempli de l’esprit de Dieu, en sagesse, en intelligence, et en connaissance, et pour toute espèce d’ouvrages;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'et pour faire des inventions, pour travailler en or, et en argent, et en airain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'et pour tailler des pierres à enchâsser, et pour tailler le bois, afin d’exécuter des dessins en toutes sortes d’ouvrages;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'et à lui et à Oholiab, fils d’Akhisamac, de la tribu de Dan, il a mis au cœur d’enseigner;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'il les a remplis de sagesse de cœur pour faire tout ouvrage de graveur et d’inventeur, et de brodeur en bleu et en pourpre, en écarlate et en fin coton, et [tout ouvrage] de tisserand, faisant toute espèce de travail, et inventant des dessins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, '*Et Betsaleël et Oholiab, et tout homme sage de cœur à qui l’ Éternel avait donné de la sagesse et de l’intelligence pour savoir faire toute l’œuvre du service du lieu saint, firent selon tout ce que l’ Éternel avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Et Moïse appela Betsaleël et Oholiab, et tout homme intelligent dans le cœur duquel l’ Éternel avait mis de la sagesse, tous ceux que leur cœur porta à s’approcher de l’œuvre, pour la faire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'et ils prirent de devant Moïse toute l’offrande que les fils d’Israël avaient apportée pour l’œuvre du service du lieu saint, pour la faire. Et on lui apportait encore chaque matin des offrandes volontaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Et tous les hommes sages qui travaillaient à toute l’œuvre du lieu saint vinrent chacun de l’ouvrage qu’ils faisaient,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'et parlèrent à Moïse, disant: Le peuple apporte beaucoup plus qu’il ne faut pour le service de l’œuvre que l’ Éternel a commandé de faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Et Moïse commanda, et on fit crier dans le camp: Que ni homme ni femme ne fasse plus d’ouvrage pour l’offrande pour le lieu saint. Et le peuple cessa d’apporter;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'car le travail était suffisant pour tout l’ouvrage à faire, et il y en avait de reste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Et tous les hommes intelligents parmi ceux qui travaillaient à l’œuvre du tabernacle, firent dix tapis de fin coton retors, et de bleu, et de pourpre, et d’écarlate; ils les firent avec des chérubins, d’ouvrage d’art.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'La longueur d’un tapis était de 28 coudées, et la largeur d’un tapis de quatre coudées: une même mesure pour tous les tapis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Et on joignit cinq tapis l’un à l’autre, et on joignit cinq tapis l’un à l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Et on fit des ganses de bleu sur le bord d’un tapis, à l’extrémité de l’assemblage; on fit de même au bord du tapis qui était à l’extrémité dans le second assemblage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'On fit 50 ganses à un tapis, et on fit 50 ganses à l’extrémité du tapis qui était dans le second assemblage, [mettant] les ganses vis-à-vis l’une de l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Et on fit 50 agrafes d’or, et on joignit un tapis à l’autre par les agrafes; et ce fut un seul tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Et on fit des tapis de poil de chèvre pour une tente par-dessus le tabernacle; on fit onze de ces tapis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'La longueur d’un tapis était de 30 coudées, et la largeur d’un tapis de quatre coudées: une même mesure pour les onze tapis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Et on joignit cinq tapis à part, et six tapis à part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Et on fit 50 ganses sur le bord du tapis qui était à l’extrémité de l’assemblage, et on fit 50 ganses sur le bord du tapis du second assemblage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'et on fit 50 agrafes d’airain pour assembler la tente, pour qu’elle soit une.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Et on fit pour la tente une couverture de peaux de béliers teintes en rouge, et une couverture de peaux de taissons par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Et on fit les ais pour le tabernacle; ils étaient de bois de sittim, [placés] debout;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'la longueur d’un ais était de dix coudées, et la largeur d’un ais d’une coudée et demie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'il y avait deux tenons à un ais, en façon d’échelons, l’un répondant à l’autre; on fit de même pour tous les ais du tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Et on fit les ais pour le tabernacle, 20 ais pour le côté du midi vers le sud;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'et on fit 40 bases d’argent sous les 20 ais, deux bases sous un ais pour ses deux tenons, et deux bases sous un ais pour ses deux tenons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Et on fit pour l’autre côté du tabernacle, du côté du nord, 20 ais,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'et leurs 40 bases d’argent, deux bases sous un ais, et deux bases sous un ais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Et pour le fond du tabernacle, vers l’occident, on fit six ais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Et on fit deux ais pour les angles du tabernacle, au fond;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'et ils étaient joints par le bas, et parfaitement unis ensemble par le haut dans un anneau; on fit de même pour les deux, aux deux angles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Et il y avait huit ais et leurs bases d’argent, 16 bases, deux bases sous chaque ais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, '– Et on fit des traverses de bois de sittim, cinq pour les ais d’un côté du tabernacle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'et cinq traverses pour les ais de l’autre côté du tabernacle, et cinq traverses pour les ais du tabernacle, pour le fond, vers l’occident;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'et on fit la traverse du milieu pour courir par le milieu des ais, d’un bout à l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Et on plaqua d’or les ais, et on fit d’or leurs anneaux pour recevoir les traverses, et on plaqua d’or les traverses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Et on fit le voile de bleu, et de pourpre, et d’écarlate, et de fin coton retors; on le fit d’ouvrage d’art, avec des chérubins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Et on lui fit quatre piliers de [bois de] sittim, et on les plaqua d’or, et leurs crochets étaient d’or; et on fondit pour eux quatre bases d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Et on fit pour l’entrée de la tente un rideau de bleu, et de pourpre, et d’écarlate, et de fin coton retors, en ouvrage de brodeur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'et ses cinq piliers, et leurs crochets; et on plaqua d’or leurs chapiteaux et leurs baguettes d’attache; et leurs cinq bases étaient d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Et Betsaleël fit l’arche de bois de sittim: sa longueur était de deux coudées et demie, et sa largeur d’une coudée et demie, et sa hauteur d’une coudée et demie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Et il la plaqua d’or pur, dedans et dehors, et lui fit un couronnement d’or tout autour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'et il fondit pour elle quatre anneaux d’or, pour ses quatre coins, deux anneaux à l’un de ses côtés, et deux anneaux à l’autre de ses côtés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Et il fit des barres de bois de sittim, et les plaqua d’or;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'et il fit entrer les barres dans les anneaux, aux côtés de l’arche, pour porter l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, '– Et il fit un propitiatoire d’or pur: sa longueur était de deux coudées et demie, et sa largeur d’une coudée et demie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Et il fit deux chérubins d’or; il les fit d’or battu, aux deux bouts du propitiatoire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'un chérubin au bout de deçà, et un chérubin au bout de delà; il fit les chérubins [tirés] du propitiatoire, à ses deux bouts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Et les chérubins étendaient les ailes en haut, couvrant de leurs ailes le propitiatoire; et leurs faces étaient l’une vis-à-vis de l’autre; les faces des chérubins étaient [tournées] vers le propitiatoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Et il fit la table de bois de sittim: sa longueur était de deux coudées, et sa largeur d’une coudée, et sa hauteur d’une coudée et demie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'et il la plaqua d’or pur, et y fit un couronnement d’or tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Et il y fit un rebord d’une paume tout autour, et il fit un couronnement d’or à son rebord, tout autour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'et il lui fondit quatre anneaux d’or, et il mit les anneaux aux quatre coins qui étaient à ses quatre pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Les anneaux étaient près du rebord, pour recevoir les barres, pour porter la table;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'et il fit les barres de bois de sittim, et les plaqua d’or, pour porter la table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Et il fit d’or pur les ustensiles qui étaient sur la table, ses plats, et ses coupes, et ses vases, et les gobelets avec lesquels on fait les libations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Et il fit le chandelier d’or pur; il fit le chandelier [d’or] battu; son pied, et sa tige, ses calices, ses pommes, et ses fleurs, étaient [tirés] de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'et six branches sortaient de ses côtés, trois branches du chandelier d’un côté, et trois branches du chandelier de l’autre côté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Il y avait, sur une branche, trois calices en forme de fleur d’amandier, une pomme et une fleur, et, sur une [autre] branche, trois calices en forme de fleur d’amandier, une pomme et une fleur; ainsi pour les six branches sortant du chandelier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Et il y avait au chandelier quatre calices en forme de fleur d’amandier, ses pommes et ses fleurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'et une pomme sous deux branches [sortant] de lui, et une pomme sous deux branches [sortant] de lui, et une pomme sous deux branches [sortant] de lui, pour les six branches qui sortaient de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'leurs pommes et leurs branches étaient [tirées] de lui, le tout battu, d’une pièce, d’or pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, '– Et il fit ses sept lampes, et ses mouchettes, et ses vases à cendre, d’or pur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'il le fit, avec tous ses ustensiles, d’un talent d’or pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Et il fit l’autel de l’encens, de bois de sittim: sa longueur était d’une coudée, et sa largeur d’une coudée; il était carré; et sa hauteur était de deux coudées; ses cornes étaient [tirées] de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Et il le plaqua d’or pur, le dessus et ses parois, tout autour, et ses cornes. Et il lui fit un couronnement d’or tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Et il lui fit deux anneaux d’or au-dessous de son couronnement, sur ses deux côtés, à ses deux coins, pour recevoir les barres, pour le porter par elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Et il fit les barres de bois de sittim, et les plaqua d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Et il fit l’huile sainte de l’onction et le pur encens des drogues odoriférantes, d’ouvrage de parfumeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Et il fit l’autel de l’holocauste de bois de sittim: sa longueur était de cinq coudées, et sa largeur de cinq coudées; il était carré, et sa hauteur était de trois coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Et il fit ses cornes à ses quatre coins; ses cornes étaient [tirées] de lui; et il le plaqua d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Et il fit tous les ustensiles de l’autel: les vases, et les pelles, et les bassins, les fourchettes, et les brasiers; il fit tous ses ustensiles d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Et il fit pour l’autel une grille en ouvrage de treillis, d’airain, au-dessous de son contour, en bas, jusqu’au milieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'et il fondit quatre anneaux pour les quatre bouts de la grille d’airain, pour recevoir les barres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Et il fit les barres de bois de sittim, et les plaqua d’airain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'et il fit entrer les barres dans les anneaux, sur les côtés de l’autel, pour le porter par elles; il le fit creux, avec des planches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Et il fit la cuve d’airain, et son soubassement d’airain, avec les miroirs des femmes qui s’attroupaient à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Et il fit le parvis: pour le côté du midi vers le sud, les tentures du parvis de fin coton retors, de 100 coudées,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'leurs 20 piliers, et leurs 20 bases d’airain; les crochets des piliers et leurs baguettes d’attache étaient d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Et pour le côté du nord, 100 coudées, leurs 20 piliers, et leurs 20 bases d’airain; les crochets des piliers et leurs baguettes d’attache, d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Et pour le côté de l’occident, des tentures de 50 coudées, leurs dix piliers et leurs dix bases; les crochets des piliers et leurs baguettes d’attache étaient d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Et pour le côté de l’orient, vers le levant, 50 coudées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'sur un côté 15 coudées de tentures, leurs trois piliers et leurs trois bases;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'et sur l’autre côté, deçà et delà de la porte du parvis, 15 coudées de tentures, leurs trois piliers et leurs trois bases.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Toutes les tentures du parvis, à l’entour, étaient de fin coton retors;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'et les bases des piliers, d’airain; les crochets des piliers et leurs baguettes d’attache, d’argent; et le plaqué de leurs chapiteaux, d’argent; et tous les piliers du parvis avaient des baguettes d’attache en argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, '– Et le rideau de la porte du parvis était de bleu, et de pourpre, et d’écarlate, et de fin coton retors, en ouvrage de brodeur; et la longueur, de 20 coudées; et la hauteur, dans la largeur [de la porte], de cinq coudées, correspondant aux tentures du parvis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'et ses quatre piliers, et leurs quatre bases, d’airain; leurs crochets, d’argent; et le plaqué de leurs chapiteaux et leurs baguettes d’attache, d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Et tous les pieux du tabernacle et du parvis, à l’entour, étaient d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Et c’est ici l’inventaire du tabernacle, du tabernacle du témoignage, qui fut dressé par le commandement de Moïse: [ce fut] le service des Lévites, sous la main d’Ithamar, fils d’Aaron, le sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Et Betsaleël, fils d’Uri, fils de Hur, de la tribu de Juda, fit tout ce que l’ Éternel avait commandé à Moïse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'et avec lui Oholiab, fils d’Akhisamac, de la tribu de Dan, graveur, et inventeur, et brodeur en bleu, et en pourpre, et en écarlate, et en fin coton.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Tout l’or qui fut employé pour l’œuvre, pour toute l’œuvre du lieu saint, l’or de l’offrande, fut de 29 talents et 730 sicles, selon le sicle du sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Et l’argent de ceux de l’assemblée qui furent dénombrés fut de 100 talents et 1 775 sicles, selon le sicle du sanctuaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'un béka par tête, la moitié d’un sicle, selon le sicle du sanctuaire, pour tous ceux qui passèrent par le dénombrement, depuis l’âge de 20 ans et au-dessus, pour 603 550 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Et les 100 talents d’argent étaient pour fondre les bases du lieu saint, et les bases du voile, 100 bases pour les 100 talents, un talent par base;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'et des 1 775 [sicles] on fit les crochets des piliers, et on plaqua leurs chapiteaux, et on les joignit par les baguettes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Et l’airain de l’offrande fut de 70 talents et 2 400 sicles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'et on en fit les bases de l’entrée de la tente d’assignation, et l’autel d’airain, et la grille d’airain qui lui appartient, et tous les ustensiles de l’autel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'et les bases du parvis tout autour, et les bases de la porte du parvis, et tous les pieux du tabernacle, et tous les pieux du parvis, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Et du bleu, et de la pourpre, et de l’écarlate, ils firent les vêtements de service pour servir dans le lieu saint; et ils firent les saints vêtements qui étaient pour Aaron, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Et on fit l’éphod d’or, de bleu, et de pourpre, et d’écarlate, et de fin coton retors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Et ils étendirent des lames d’or, et on les coupa par filets pour les brocher parmi le bleu, et parmi la pourpre, et parmi l’écarlate, et parmi le fin coton, en ouvrage d’art.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Ils y firent des épaulières qui l’assemblaient; il était joint par ses deux bouts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Et la ceinture de son éphod, qui était par-dessus, était de la même matière, du même travail, d’or, de bleu, et de pourpre, et d’écarlate, et de fin coton retors, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, '– Et ils firent les pierres d’onyx, enchâssées dans des chatons d’or, gravées en gravure de cachet d’après les noms des fils d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'et on les mit sur les épaulières de l’éphod comme pierres de mémorial pour les fils d’Israël, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Et on fit le pectoral en ouvrage d’art, comme l’ouvrage de l’éphod, d’or, de bleu, et de pourpre, et d’écarlate, et de fin coton retors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Il était carré; ils firent le pectoral double; sa longueur d’un empan, et sa largeur d’un empan, double;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'et ils le garnirent de quatre rangées de pierres: la première rangée, une sardoine, une topaze, et une émeraude;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'et la seconde rangée, une escarboucle, un saphir, et un diamant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'et la troisième rangée, une opale, une agate, et une améthyste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'et la quatrième rangée, une chrysolithe, un onyx, et un jaspe, enchâssés dans des chatons d’or, dans leurs montures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Et les pierres étaient selon les noms des fils d’Israël, douze, selon leurs noms, en gravure de cachet, chacune selon son nom, pour les douze tribus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, '– Et ils firent sur le pectoral des chaînettes à bouts, en ouvrage de torsade, d’or pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Et ils firent deux chatons d’or, et deux anneaux d’or, et ils mirent les deux anneaux aux deux bouts du pectoral;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'et ils mirent les deux torsades d’or dans les deux anneaux, aux bouts du pectoral;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'et ils mirent les deux bouts des deux torsades dans les deux chatons, et ils les mirent sur les épaulières de l’éphod, sur le devant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Et ils firent deux anneaux d’or, et les placèrent aux deux bouts du pectoral, sur son bord qui était contre l’éphod, en dedans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Et ils firent deux anneaux d’or, et les mirent aux deux épaulières de l’éphod par en bas, sur le devant, juste à sa jointure au-dessus de la ceinture de l’éphod;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'et ils attachèrent le pectoral par ses anneaux aux anneaux de l’éphod avec un cordon de bleu, afin qu’il soit au-dessus de la ceinture de l’éphod, et que le pectoral ne bouge pas de dessus l’éphod, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Et on fit la robe de l’éphod en ouvrage de tisserand, entièrement de bleu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'et l’ouverture de la robe était au milieu, comme l’ouverture d’une cotte de mailles; il y avait une bordure à son ouverture, tout autour, afin qu’elle ne se déchire pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, '– Et sur les bords de la robe ils firent des grenades de bleu et de pourpre et d’écarlate retors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Et ils firent des clochettes d’or pur, et mirent les clochettes entre les grenades sur les bords de la robe, tout autour, entre les grenades:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'une clochette et une grenade, une clochette et une grenade, sur les bords de la robe, tout autour, pour faire le service, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Et ils firent les tuniques de fin coton en ouvrage de tisserand, pour Aaron et pour ses fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'et la tiare de fin coton, et les bonnets d’ornement, de fin coton, et les caleçons de lin, de byssus retors;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'et la ceinture, de fin coton retors, et de bleu, et de pourpre, et d’écarlate, en ouvrage de brodeur, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Et ils firent la lame du saint diadème, d’or pur, et écrivirent dessus, en écriture de gravure de cachet: Sainteté à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Et ils mirent dessus un cordon de bleu, pour l’attacher à la tiare, par-dessus, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Et tout le travail du tabernacle de la tente d’assignation fut achevé; et les fils d’Israël firent selon tout ce que l’ Éternel avait commandé à Moïse: ils firent ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Et ils apportèrent le tabernacle à Moïse: la tente, et tous ses ustensiles, ses agrafes, ses ais, ses traverses, et ses piliers, et ses bases;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'et la couverture de peaux de béliers teintes en rouge, et la couverture de peaux de taissons, et le voile qui sert de rideau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'l’arche du témoignage, et ses barres, et le propitiatoire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'la table, tous ses ustensiles, et le pain de proposition;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'le chandelier pur, ses lampes, les lampes à ranger, et tous ses ustensiles, et l’huile du luminaire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'et l’autel d’or, et l’huile de l’onction, et l’encens des drogues odoriférantes; et le rideau de l’entrée de la tente;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'l’autel d’airain, et la grille d’airain qui lui appartient, ses barres, et tous ses ustensiles; la cuve et son soubassement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'les tentures du parvis, ses piliers, et ses bases; et le rideau pour la porte du parvis, ses cordages, et ses pieux; et tous les ustensiles du service du tabernacle, pour la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'les vêtements de service, pour servir dans le lieu saint: les saints vêtements pour Aaron, le sacrificateur, et les vêtements de ses fils, pour exercer la sacrificature.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Selon tout ce que l’ Éternel avait commandé à Moïse, ainsi les fils d’Israël firent tout le travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Et Moïse vit tout l’ouvrage, et voici, ils l’avaient fait comme l’ Éternel l’avait commandé; ils l’avaient fait ainsi. Et Moïse les bénit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Au premier mois, le premier jour du mois, tu dresseras le tabernacle de la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'et tu y placeras l’arche du témoignage, et tu couvriras l’arche avec le voile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Et tu apporteras la table, et tu y arrangeras ce qui doit y être arrangé; et tu apporteras le chandelier, et tu allumeras ses lampes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Et tu mettras l’autel d’or pour l’encens devant l’arche du témoignage; et tu placeras le rideau à l’entrée du tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Et tu mettras l’autel de l’holocauste devant l’entrée du tabernacle de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Et tu mettras la cuve entre la tente d’assignation et l’autel, et tu y mettras de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Et tu placeras le parvis tout autour, et tu mettras le rideau de la porte du parvis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Et tu prendras l’huile de l’onction, et tu en oindras le tabernacle et tout ce qui est dedans; et tu le sanctifieras avec tous ses ustensiles, et il sera saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Et tu oindras l’autel de l’holocauste et tous ses ustensiles; et tu sanctifieras l’autel, et l’autel sera une chose très sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Et tu oindras la cuve et son soubassement, et tu la sanctifieras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Et tu feras approcher Aaron et ses fils à l’entrée de la tente d’assignation, et tu les laveras avec de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Et tu revêtiras Aaron des saints vêtements, et tu l’oindras, et tu le sanctifieras, et il exercera la sacrificature devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Et tu feras approcher ses fils, et tu les revêtiras des tuniques,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'et tu les oindras comme tu auras oint leur père; et ils exerceront la sacrificature devant moi; et leur onction leur sera pour [exercer] une sacrificature perpétuelle en leurs générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Et Moïse fit selon tout ce que l’ Éternel lui avait commandé; il fit ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Et il arriva, le premier mois, en la seconde année, le premier [jour] du mois, que le tabernacle fut dressé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Et Moïse dressa le tabernacle, et mit ses bases, et plaça ses ais, et mit ses traverses, et dressa ses piliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Et il étendit la tente sur le tabernacle, et mit la couverture de la tente sur elle, par-dessus, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Et il prit et mit le témoignage dans l’arche; et il plaça les barres à l’arche; et il mit le propitiatoire sur l’arche, par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Et il apporta l’arche dans le tabernacle, et plaça le voile qui sert de rideau, et en couvrit l’arche du témoignage, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Et il mit la table dans la tente d’assignation, sur le côté du tabernacle, vers le nord, en dehors du voile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'et il rangea sur elle, en ordre, le pain devant l’ Éternel, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Et il plaça le chandelier dans la tente d’assignation, vis-à-vis de la table, sur le côté du tabernacle, vers le midi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'et il alluma les lampes devant l’ Éternel, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Et il plaça l’autel d’or dans la tente d’assignation, devant le voile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'et il fit fumer dessus l’encens des drogues odoriférantes, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Et il plaça le rideau de l’entrée du tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Et il plaça l’autel de l’holocauste à l’entrée du tabernacle de la tente d’assignation, et il offrit sur lui l’holocauste et l’offrande de gâteau, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Et il plaça la cuve entre la tente d’assignation et l’autel, et y mit de l’eau pour se laver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Et Moïse, et Aaron et ses fils, s’y lavèrent les mains et les pieds;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'lorsqu’ils entraient dans la tente d’assignation, et qu’ils s’approchaient de l’autel, ils se lavaient, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Et il dressa le parvis tout autour du tabernacle et de l’autel, et mit le rideau à la porte du parvis. Et Moïse acheva l’œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Et la nuée couvrit la tente d’assignation, et la gloire de l’ Éternel remplit le tabernacle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'et Moïse ne pouvait entrer dans la tente d’assignation; car la nuée demeura dessus, et la gloire de l’ Éternel remplissait le tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Et quand la nuée se levait de dessus le tabernacle, les fils d’Israël partaient, dans toutes leurs traites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'et si la nuée ne se levait pas, ils ne partaient pas, jusqu’au jour où elle se levait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'car la nuée de l’ Éternel était sur le tabernacle le jour, et un feu y était la nuit, aux yeux de toute la maison d’Israël, dans toutes leurs traites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Et l’ Éternel appela Moïse, et lui parla, de la tente d’assignation, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Parle aux fils d’Israël, et dis-leur: Quand un homme d’entre vous présentera une offrande à l’ Éternel, vous présenterez votre offrande de bétail, du gros ou du menu bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Si son offrande est un holocauste de gros bétail, il la présentera, – un mâle sans défaut; il la présentera à l’entrée de la tente d’assignation, pour être agréé devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Et il posera sa main sur la tête de l’holocauste, et il sera agréé pour lui, pour faire propitiation pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Et il égorgera le jeune taureau devant l’ Éternel; et les fils d’Aaron, les sacrificateurs, présenteront le sang, et ils feront aspersion du sang tout autour sur l’autel qui est à l’entrée de la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'et il écorchera l’holocauste et le coupera en morceaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Et les fils d’Aaron, le sacrificateur, mettront du feu sur l’autel, et arrangeront du bois sur le feu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'et les fils d’Aaron, les sacrificateurs, arrangeront les morceaux, la tête et la graisse, sur le bois qui est sur le feu qui est sur l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Et il lavera avec de l’eau l’intérieur et les jambes, et le sacrificateur fera fumer le tout sur l’autel; [c’est] un holocauste, un sacrifice par feu, une odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Et si son offrande pour l’holocauste est de menu bétail, d’entre les moutons ou d’entre les chèvres, il la présentera, – un mâle sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'et il l’égorgera à côté de l’autel, vers le nord, devant l’ Éternel; et les fils d’Aaron, les sacrificateurs, feront aspersion du sang sur l’autel, tout autour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'et il le coupera en morceaux, avec sa tête et sa graisse, et le sacrificateur les arrangera sur le bois qui est sur le feu qui est sur l’autel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'et il lavera avec de l’eau l’intérieur et les jambes; et le sacrificateur présentera le tout et le fera fumer sur l’autel: c’est un holocauste, un sacrifice par feu, une odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Et si son offrande à l’ Éternel est un holocauste d’oiseaux, il présentera son offrande de tourterelles ou de jeunes pigeons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Et le sacrificateur l’apportera à l’autel, et lui détachera la tête avec l’ongle, et la fera fumer sur l’autel; et il en épreindra le sang contre la paroi de l’autel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'et il ôtera son gésier avec son ordure, et les jettera à côté de l’autel, vers l’orient, au lieu où sont les cendres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'et il fendra l’oiseau entre les ailes, il ne le divisera pas; et le sacrificateur le fera fumer sur l’autel, sur le bois qui est sur le feu: c’est un holocauste, un sacrifice par feu, une odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, '*Et quand quelqu’un présentera en offrande une offrande de gâteau à l’ Éternel, son offrande sera de fleur de farine, et il versera de l’huile sur elle, et mettra de l’encens dessus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'et il l’apportera aux fils d’Aaron, les sacrificateurs; et le sacrificateur prendra une pleine poignée de la fleur de farine et de l’huile, avec tout l’encens, et il en fera fumer le mémorial sur l’autel: [c’est] un sacrifice par feu, une odeur agréable à l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'et le reste de l’offrande de gâteau sera pour Aaron et pour ses fils: [c’est] une chose très sainte entre les sacrifices de l’ Éternel faits par feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Et quand tu présenteras en offrande une offrande de gâteau cuit au four, ce sera de la fleur de farine, des gâteaux sans levain, pétris à l’huile, et des galettes sans levain ointes d’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Et si ton offrande est une offrande de gâteau cuit sur la plaque, elle sera de fleur de farine pétrie à l’huile, sans levain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Tu la briseras en morceaux, et tu verseras de l’huile dessus: c’est une offrande de gâteau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Et si ton offrande est une offrande de gâteau cuit dans la poêle, elle sera faite de fleur de farine, avec de l’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Et tu apporteras à l’ Éternel l’offrande de gâteau qui est faite de ces choses, et on la présentera au sacrificateur, et il l’apportera à l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Et le sacrificateur lèvera de l’offrande de gâteau son mémorial, et le fera fumer sur l’autel: [c’est] un sacrifice par feu, une odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Et le reste de l’offrande de gâteau sera pour Aaron et pour ses fils: [c’est] une chose très sainte entre les sacrifices de l’ Éternel faits par feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Aucune offrande de gâteau que vous présenterez à l’ Éternel ne sera faite avec du levain; car du levain et du miel, vous n’en ferez point fumer comme sacrifice par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Pour l’offrande des prémices, vous les présenterez à l’ Éternel; mais ils ne seront point brûlés sur l’autel en odeur agréable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Et toute offrande de ton offrande de gâteau, tu la saleras de sel, et tu ne laisseras point manquer sur ton offrande de gâteau le sel de l’alliance de ton Dieu; sur toutes tes offrandes tu présenteras du sel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Et si tu présentes à l’ Éternel une offrande de gâteau des premiers fruits, tu présenteras, pour l’offrande de gâteau de tes premiers fruits, des épis nouveaux rôtis au feu, les grains broyés d’épis grenus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'et tu mettras de l’huile dessus, et tu placeras de l’encens dessus: c’est une offrande de gâteau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Et le sacrificateur en fera fumer le mémorial, une portion de ses grains broyés et de son huile, avec tout son encens: [c’est] un sacrifice par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, '*Et si son offrande est un sacrifice de prospérités, si c’est du gros bétail qu’il présente, soit mâle, soit femelle, il le présentera sans défaut devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'et il posera sa main sur la tête de son offrande, et il l’égorgera à l’entrée de la tente d’assignation; et les fils d’Aaron, les sacrificateurs, feront aspersion du sang sur l’autel, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Et il présentera, du sacrifice de prospérités, un sacrifice fait par feu à l’ Éternel: la graisse qui couvre l’intérieur, et toute la graisse qui est sur l’intérieur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'et les deux rognons, et la graisse qui est dessus, qui est sur les reins, et le réseau qui est sur le foie, qu’on ôtera jusque sur les rognons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'et les fils d’Aaron feront fumer cela sur l’autel, sur l’holocauste qui est sur le bois qui est sur le feu: [c’est] un sacrifice par feu, une odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Et si son offrande pour le sacrifice de prospérités à l’ Éternel est de menu bétail, mâle ou femelle, il le présentera sans défaut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Si c’est un agneau qu’il présente pour son offrande, il le présentera devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'et il posera sa main sur la tête de son offrande, et il l’égorgera devant la tente d’assignation; et les fils d’Aaron feront aspersion du sang sur l’autel, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Et il présentera, du sacrifice de prospérités, un sacrifice fait par feu à l’ Éternel: sa graisse, la queue qu’on ôtera entière jusque contre l’échine, et la graisse qui couvre l’intérieur, et toute la graisse qui est sur l’intérieur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'et les deux rognons, et la graisse qui est dessus, qui est sur les reins, et le réseau qui est sur le foie, qu’on ôtera jusque sur les rognons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'et le sacrificateur fera fumer cela sur l’autel: [c’est] un pain de sacrifice par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Et si son offrande est une chèvre, il la présentera devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'et il posera sa main sur sa tête, et il l’égorgera devant la tente d’assignation; et les fils d’Aaron feront aspersion du sang sur l’autel, tout autour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'et il en présentera son offrande, un sacrifice par feu à l’ Éternel: la graisse qui couvre l’intérieur, et toute la graisse qui est sur l’intérieur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'et les deux rognons, et la graisse qui est dessus, qui est sur les reins, et le réseau qui est sur le foie, qu’on ôtera jusque sur les rognons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'et le sacrificateur les fera fumer sur l’autel: [c’est] un pain de sacrifice par feu, en odeur agréable. Toute graisse appartient à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, '[C’est] un statut perpétuel, en vos générations, dans toutes vos habitations: vous ne mangerez aucune graisse ni aucun sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Parle aux fils d’Israël, en disant: Si quelqu’un a péché par erreur contre quelqu’un des commandements de l’ Éternel dans les choses qui ne doivent pas se faire, et a commis quelqu’une de ces choses:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'si c’est le sacrificateur oint qui a péché selon quelque faute du peuple, alors il présentera à l’ Éternel, pour son péché qu’il aura commis, un jeune taureau sans défaut, en sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Et il amènera le taureau à l’entrée de la tente d’assignation, devant l’ Éternel; et il posera sa main sur la tête du taureau, et égorgera le taureau devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'et le sacrificateur oint prendra du sang du taureau, et il l’apportera dans la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'et le sacrificateur trempera son doigt dans le sang, et fera aspersion du sang sept fois, devant l’ Éternel, par-devant le voile du lieu saint;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'et le sacrificateur mettra du sang sur les cornes de l’autel de l’encens des drogues odoriférantes qui est dans la tente d’assignation, devant l’ Éternel; et il versera tout le sang du taureau au pied de l’autel de l’holocauste qui est à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Et toute la graisse du taureau du sacrifice pour le péché, il la lèvera: la graisse qui couvre l’intérieur, et toute la graisse qui est sur l’intérieur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'et les deux rognons, et la graisse qui est dessus, qui est sur les reins, et le réseau qui est sur le foie, qu’on ôtera jusque sur les rognons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'comme on les lève du bœuf du sacrifice de prospérités: et le sacrificateur les fera fumer sur l’autel de l’holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Et la peau du taureau et toute sa chair, avec sa tête, et ses jambes, et son intérieur, et sa fiente,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'tout le taureau, il l’emportera hors du camp, dans un lieu net, là où l’on verse les cendres, et il le brûlera sur du bois, au feu; il sera brûlé au lieu où l’on verse les cendres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Et si toute l’assemblée d’Israël a péché par erreur et que la chose soit restée cachée aux yeux de la congrégation, et qu’ils aient fait, à l’égard de l’un de tous les commandements de l’ Éternel, ce qui ne doit pas se faire, et se soient rendus coupables,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'et que le péché qu’ils ont commis contre le [commandement] vienne à être connu, alors la congrégation présentera un jeune taureau en sacrifice pour le péché, et on l’amènera devant la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'et les anciens de l’assemblée poseront leurs mains sur la tête du taureau, devant l’ Éternel; et on égorgera le taureau devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Et le sacrificateur oint apportera du sang du taureau dans la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'et le sacrificateur trempera son doigt dans ce sang, et en fera aspersion, sept fois, devant l’ Éternel, par-devant le voile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'et il mettra du sang sur les cornes de l’autel qui est devant l’ Éternel, dans la tente d’assignation; et il versera tout le sang au pied de l’autel de l’holocauste qui est à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Et il lèvera toute la graisse, et la fera fumer sur l’autel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'il fera du taureau comme il a fait du taureau pour le péché; il fera ainsi de lui. Et le sacrificateur fera propitiation pour eux, et il leur sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Et on emportera le taureau hors du camp, et on le brûlera comme on a brûlé le premier taureau: c’est un sacrifice pour le péché pour la congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Si un chef a péché, et a fait par erreur, à l’égard de l’un de tous les commandements de l’ Éternel, son Dieu, ce qui ne doit pas se faire, et s’est rendu coupable,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'si on lui a fait connaître son péché qu’il a commis, alors il amènera pour son offrande un bouc, un mâle sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'et il posera sa main sur la tête du bouc, et il l’égorgera au lieu où l’on égorge l’holocauste devant l’ Éternel: c’est un sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Et le sacrificateur prendra avec son doigt du sang du sacrifice pour le péché, et le mettra sur les cornes de l’autel de l’holocauste, et il versera le sang au pied de l’autel de l’holocauste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'et il fera fumer toute la graisse sur l’autel, comme la graisse du sacrifice de prospérités; et le sacrificateur fera propitiation pour lui [pour le purifier] de son péché, et il lui sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Et si quelqu’un du peuple du pays a péché par erreur, en faisant, à l’égard de l’un des commandements de l’ Éternel, ce qui ne doit pas se faire, et s’est rendu coupable,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'si on lui a fait connaître son péché qu’il a commis, alors il amènera son offrande, une chèvre, une femelle sans défaut, pour son péché qu’il a commis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'et il posera sa main sur la tête du sacrifice pour le péché, et égorgera le sacrifice pour le péché au lieu où [l’on égorge] l’holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Et le sacrificateur prendra du sang de la [chèvre] avec son doigt, et le mettra sur les cornes de l’autel de l’holocauste, et il versera tout le sang au pied de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Et il ôtera toute la graisse, comme la graisse a été ôtée de dessus le sacrifice de prospérités; et le sacrificateur la fera fumer sur l’autel, en odeur agréable à l’ Éternel; et le sacrificateur fera propitiation pour lui, et il lui sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Et s’il amène un agneau pour son offrande de sacrifice pour le péché, ce sera une femelle sans défaut qu’il amènera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'et il posera sa main sur la tête du sacrifice pour le péché, et l’égorgera en sacrifice pour le péché au lieu où l’on égorge l’holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Et le sacrificateur prendra, avec son doigt, du sang du sacrifice pour le péché et le mettra sur les cornes de l’autel de l’holocauste, et il versera tout le sang au pied de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Et il ôtera toute la graisse, comme la graisse de l’agneau a été ôtée du sacrifice de prospérités; et le sacrificateur la fera fumer sur l’autel, sur les sacrifices de l’ Éternel faits par feu; et le sacrificateur fera propitiation pour lui pour son péché qu’il a commis; et il lui sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, '*Et si quelqu’un a péché en ce que, étant témoin et ayant entendu la voix d’adjuration, ayant vu ou su, il ne déclare pas [la chose], alors il portera son iniquité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, '– ou si quelqu’un a touché une chose impure quelconque, soit le corps mort d’une bête sauvage impure, ou le corps mort d’une bête domestique impure, ou le corps mort d’un reptile impur, et que cela lui soit resté caché, alors il est impur et coupable;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, '– ou s’il a touché l’impureté de l’homme, quelle que soit son impureté par laquelle il se rend impur, et que cela lui soit resté caché, quand il le sait, alors il est coupable;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, '– ou si quelqu’un, parlant légèrement de ses lèvres, a juré de faire du mal ou du bien, selon tout ce que l’homme profère légèrement en jurant, et que cela lui soit resté caché, quand il le sait, alors il est coupable en l’un de ces points-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Et il arrivera, s’il est coupable en l’un de ces points-là, qu’il confessera ce en quoi il aura péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'et il amènera à l’ Éternel son sacrifice pour le délit, pour son péché qu’il a commis, une femelle du menu bétail, soit brebis, soit chèvre, en sacrifice pour le péché; et le sacrificateur fera propitiation pour lui [pour le purifier] de son péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Et si ses moyens ne peuvent atteindre à un agneau, il apportera à l’ Éternel, pour son délit qu’il a commis, deux tourterelles ou deux jeunes pigeons, l’un pour le sacrifice pour le péché, et l’autre pour l’holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Et il les apportera au sacrificateur, et le sacrificateur présentera celui qui est pour le sacrifice pour le péché, premièrement, et lui détachera la tête avec l’ongle près du cou, mais il ne le divisera pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'et il fera aspersion du sang du sacrifice pour le péché sur la paroi de l’autel, et le reste du sang, il l’épreindra au pied de l’autel: c’est un sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Et du second, il en fera un holocauste selon l’ordonnance. Et le sacrificateur fera propitiation pour lui [pour le purifier] de son péché qu’il a commis, et il lui sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Et si ses moyens ne peuvent atteindre à deux tourterelles ou à deux jeunes pigeons, alors celui qui a péché apportera pour son offrande la dixième partie d’un épha de fleur de farine en sacrifice pour le péché; il ne mettra pas d’huile dessus, et il ne mettra pas d’encens dessus; car c’est un sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Et il l’apportera au sacrificateur, et le sacrificateur en prendra une pleine poignée pour mémorial, et la fera fumer sur l’autel sur les sacrifices faits par feu à l’ Éternel: c’est un sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Et le sacrificateur fera propitiation pour lui, pour son péché qu’il a commis en l’une de ces choses-là, et il lui sera pardonné; et le [reste] sera pour le sacrificateur, comme l’offrande de gâteau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Si quelqu’un a commis une infidélité et a péché par erreur dans les choses saintes de l’ Éternel, il amènera son sacrifice pour le délit à l’ Éternel, un bélier sans défaut, pris du menu bétail, selon ton estimation en sicles d’argent, selon le sicle du sanctuaire, en sacrifice pour le délit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Et ce en quoi il a péché [en prenant] de la chose sainte, il le restituera, et y ajoutera par-dessus un cinquième, et le donnera au sacrificateur; et le sacrificateur fera propitiation pour lui avec le bélier du sacrifice pour le délit; et il lui sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Et si quelqu’un a péché, et a fait, à l’égard de l’un de tous les commandements de l’ Éternel, ce qui ne doit pas se faire, et ne l’a pas su, il sera coupable, et portera son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Et il amènera au sacrificateur un bélier sans défaut, pris du menu bétail, selon ton estimation, en sacrifice pour le délit; et le sacrificateur fera propitiation pour lui, pour son erreur qu’il a commise sans le savoir; et il lui sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'C’est un sacrifice pour le délit; certainement il s’est rendu coupable envers l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 20, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 21, 'Si quelqu’un a péché, et a commis une infidélité envers l’ Éternel, et a menti à son prochain pour une chose qu’on lui a confiée, ou qu’on a déposée entre ses mains, ou qu’il a volée, ou extorquée à son prochain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 22, 'ou s’il a trouvé une chose perdue, et qu’il mente à ce sujet, et qu’il jure en mentant à l’égard de l’une de toutes les choses qu’un homme fait de manière à pécher en les faisant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 23, 'alors, s’il a péché et qu’il soit coupable, il arrivera qu’il rendra l’objet qu’ il a volé, ou la chose qu’il a extorquée, ou le dépôt qui lui a été confié, ou la chose perdue qu’il a trouvée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 24, 'ou tout ce à l’égard de quoi il a juré en mentant; et il restituera le principal, et ajoutera un cinquième par-dessus; il le donnera à celui à qui cela appartient, le jour de son sacrifice pour le délit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 25, 'Et il amènera, pour l’ Éternel, au sacrificateur, son sacrifice pour le délit, un bélier sans défaut, pris du menu bétail, selon ton estimation, en sacrifice pour le délit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 26, 'Et le sacrificateur fera propitiation pour lui devant l’ Éternel; et il lui sera pardonné, quelle que soit la faute qu’il ait faite en laquelle il s’est rendu coupable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Commande à Aaron et à ses fils, en disant: C’est ici la loi de l’holocauste. C’est l’holocauste: il sera sur le foyer sur l’autel toute la nuit jusqu’au matin; et le feu de l’autel brûlera sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Et le sacrificateur revêtira sa tunique de lin, et mettra sur sa chair ses caleçons de lin, et il lèvera la cendre de l’holocauste que le feu a consumé sur l’autel, et la mettra à côté de l’autel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'et il ôtera ses vêtements, et revêtira d’autres vêtements, et il emportera la cendre hors du camp en un lieu pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Et le feu qui est sur l’autel y brûlera; on ne le laissera pas s’éteindre. Et le sacrificateur allumera du bois sur ce [feu] chaque matin, et y arrangera l’holocauste, et y fera fumer les graisses des sacrifices de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Le feu brûlera continuellement sur l’autel, on ne le laissera pas s’éteindre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Et c’est ici la loi de l’offrande de gâteau: [l’un] des fils d’Aaron la présentera devant l’ Éternel, devant l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Et il lèvera une poignée de la fleur de farine du gâteau et de son huile, et tout l’encens qui est sur le gâteau, et il fera fumer cela sur l’autel, une odeur agréable, son mémorial à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Et ce qui en restera, Aaron et ses fils le mangeront; on le mangera sans levain, dans un lieu saint; ils le mangeront dans le parvis de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'On ne le cuira pas avec du levain. C’est leur portion, que je leur ai donnée de mes sacrifices faits par feu. C’est une chose très sainte, comme le sacrifice pour le péché et comme le sacrifice pour le délit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Tout mâle d’entre les enfants d’Aaron en mangera; [c’est] un statut perpétuel en vos générations, [leur part] des sacrifices faits par feu à l’ Éternel: quiconque les touchera sera saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'C’est ici l’offrande d’Aaron et de ses fils, qu’ils présenteront à l’ Éternel, le jour de son onction: un dixième d’épha de fleur de farine, en offrande de gâteau continuelle, une moitié le matin, et une moitié le soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Elle sera apprêtée sur une plaque avec de l’huile; tu l’apporteras mêlée [avec de l’huile]; tu présenteras les morceaux cuits du gâteau en odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Et le sacrificateur d’entre ses fils qui sera oint à sa place, fera cela; [c’est] un statut perpétuel: on le fera fumer tout entier à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Et tout gâteau de sacrificateur sera [brûlé] tout entier; il ne sera pas mangé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Parle à Aaron et à ses fils, en disant: C’est ici la loi du sacrifice pour le péché: au lieu où l’holocauste sera égorgé, le sacrifice pour le péché sera égorgé devant l’ Éternel: c’est une chose très sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Le sacrificateur qui l’offre pour le péché le mangera; on le mangera dans un lieu saint, dans le parvis de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Quiconque en touchera la chair sera saint; et s’il en rejaillit du sang sur un vêtement, ce sur quoi le sang aura rejailli, tu le laveras dans un lieu saint;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'et le vase de terre dans lequel il a été cuit sera cassé; et s’il a été cuit dans un vase d’airain, il sera écuré et lavé dans l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Tout mâle d’entre les sacrificateurs en mangera: c’est une chose très sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Nul sacrifice pour le péché dont le sang sera porté dans la tente d’assignation pour faire propitiation dans le lieu saint, ne sera mangé; il sera brûlé au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Et c’est ici la loi du sacrifice pour le délit; c’est une chose très sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Au lieu où l’on égorge l’holocauste, on égorgera le sacrifice pour le délit, et on fera aspersion de son sang sur l’autel, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Et on en présentera toute la graisse, la queue, et la graisse qui couvre l’intérieur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'et les deux rognons et la graisse qui est dessus, qui est sur les reins, et le réseau qui est sur le foie, qu’on ôtera jusque sur les rognons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Et le sacrificateur les fera fumer sur l’autel, comme sacrifice par feu à l’ Éternel: c’est un sacrifice pour le délit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Tout mâle d’entre les sacrificateurs en mangera; il sera mangé dans un lieu saint: c’est une chose très sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Comme le sacrifice pour le péché, ainsi est le sacrifice pour le délit; il y a une seule loi pour eux: il appartient au sacrificateur qui a fait propitiation par lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, '– Et quant au sacrificateur qui présentera l’holocauste de quelqu’un, la peau de l’holocauste qu’il aura présenté sera pour le sacrificateur: elle lui appartient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Et toute offrande de gâteau qui sera cuit au four ou qui sera apprêté dans la poêle ou sur la plaque, sera pour le sacrificateur qui le présente: elle lui appartient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Et toute offrande de gâteau pétri à l’huile et sec, sera pour tous les fils d’Aaron, pour l’un comme pour l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Et c’est ici la loi du sacrifice de prospérités qu’on présentera à l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Si quelqu’un le présente comme action de grâces, il présentera, avec le sacrifice d’action de grâces, des gâteaux sans levain pétris à l’huile, et des galettes sans levain ointes d’huile, et de la fleur de farine mêlée [avec de l’huile], en gâteaux pétris à l’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Il présentera pour son offrande, avec les gâteaux, du pain levé avec son sacrifice d’action de grâces de prospérités;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'et de l’offrande entière, il en présentera un en offrande élevée à l’ Éternel: il sera pour le sacrificateur qui aura fait aspersion du sang du sacrifice de prospérités; il lui appartient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Et la chair de son sacrifice d’action de grâces de prospérités sera mangée le jour où elle sera présentée; on n’en laissera rien jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Et si le sacrifice de son offrande est un vœu, ou [une offrande] volontaire, son sacrifice sera mangé le jour où il l’aura présenté; et ce qui en restera sera mangé le lendemain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'et ce qui restera de la chair du sacrifice sera brûlé au feu le troisième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Et si quelqu’un mange de la chair de son sacrifice de prospérités le troisième jour, [le sacrifice] ne sera pas agréé; il ne sera pas imputé à celui qui l’aura présenté: ce sera une chose impure; et l’âme qui en mangera portera son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Et la chair qui aura touché quelque chose d’impur ne sera point mangée: elle sera brûlée au feu. Quant à la chair, quiconque est pur mangera la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Et l’âme qui, ayant sur soi son impureté, mangera de la chair du sacrifice de prospérités qui appartient à l’ Éternel, cette âme-là sera retranchée de ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Et si une âme touche quoi que ce soit d’impur, impureté d’homme, ou bête impure, ou toute [autre] chose abominable et impure, et qu’elle mange de la chair du sacrifice de prospérités qui appartient à l’ Éternel, cette âme-là sera retranchée de ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Parle aux fils d’Israël, en disant: Vous ne mangerez aucune graisse de bœuf ou de mouton ou de chèvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'La graisse d’un corps mort ou la graisse d’une [bête] déchirée pourra être employée à tout usage, mais vous n’en mangerez point;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'car quiconque mangera de la graisse d’une bête dont on présente à l’ Éternel un sacrifice fait par feu, l’âme qui en aura mangé sera retranchée de ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Et vous ne mangerez aucun sang, dans aucune de vos habitations, soit d’oiseaux, soit de bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Toute âme qui aura mangé de quelque sang que ce soit, cette âme-là sera retranchée de ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Parle aux fils d’Israël, en disant: Celui qui présentera son sacrifice de prospérités à l’ Éternel apportera à l’ Éternel son offrande, prise de son sacrifice de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Ses mains apporteront les sacrifices faits par feu à l’ Éternel; il apportera la graisse avec la poitrine: la poitrine, pour la tournoyer comme offrande tournoyée devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Et le sacrificateur fera fumer la graisse sur l’autel; et la poitrine sera pour Aaron et pour ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Et vous donnerez au sacrificateur, comme offrande élevée, l’épaule droite de vos sacrifices de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Celui des fils d’Aaron qui présentera le sang et la graisse des sacrifices de prospérités aura pour sa part l’épaule droite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Car j’ai pris des fils d’Israël la poitrine tournoyée et l’épaule élevée de leurs sacrifices de prospérités, et je les ai données à Aaron, le sacrificateur, et à ses fils, par statut perpétuel, de la part des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'C’est là [le droit de] l’onction d’Aaron et [de] l’onction de ses fils, dans les sacrifices de l’ Éternel faits par feu, du jour où on les aura fait approcher pour exercer la sacrificature devant l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'ce que l’ Éternel a commandé de leur donner, de la part des fils d’Israël, du jour où il les aura oints; [c’est] un statut perpétuel en leurs générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Telle est la loi de l’holocauste, de l’offrande de gâteau, et du sacrifice pour le péché, et du sacrifice pour le délit, et du sacrifice de consécration, et du sacrifice de prospérités,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'laquelle l’ Éternel commanda à Moïse sur la montagne de Sinaï, le jour où il commanda aux fils d’Israël de présenter leurs offrandes à l’ Éternel, dans le désert de Sinaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Prends Aaron et ses fils avec lui, et les vêtements, et l’huile de l’onction, et le jeune taureau du sacrifice pour le péché, et les deux béliers, et la corbeille des pains sans levain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'et convoque toute l’assemblée à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Et Moïse fit comme l’ Éternel lui avait commandé, et l’assemblée fut convoquée à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Et Moïse dit à l’assemblée: C’est ici ce que l’ Éternel a commandé de faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Et Moïse fit approcher Aaron et ses fils, et les lava avec de l’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'et il mit sur lui la tunique, et le ceignit avec la ceinture, et le revêtit de la robe, et mit sur lui l’éphod, et le ceignit avec la ceinture de l’éphod, qu’il lia par elle sur lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'et il plaça sur lui le pectoral, et mit sur le pectoral les urim et les thummim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'et il plaça la tiare sur sa tête, et, sur la tiare, sur le devant, il plaça la lame d’or, le saint diadème, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Et Moïse prit l’huile de l’onction, et oignit le tabernacle et toutes les choses qui y étaient, et les sanctifia;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'et il en fit aspersion sur l’autel sept fois, et il oignit l’autel, et tous ses ustensiles, et la cuve et son soubassement, pour les sanctifier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'et il versa de l’huile de l’onction sur la tête d’Aaron, et l’oignit, pour le sanctifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Et Moïse fit approcher les fils d’Aaron, et les revêtit des tuniques, et les ceignit de la ceinture, et leur attacha les bonnets, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Et il fit approcher le taureau du sacrifice pour le péché, et Aaron et ses fils posèrent leurs mains sur la tête du taureau du sacrifice pour le péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'et on l’égorgea, et Moïse prit le sang, et en mit avec son doigt sur les cornes de l’autel, tout autour, et il purifia l’autel; et il versa le sang au pied de l’autel et le sanctifia, faisant propitiation pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Et il prit toute la graisse qui était sur l’intérieur, et le réseau du foie, et les deux rognons, et leur graisse, et Moïse les fit fumer sur l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Et le taureau, et sa peau, et sa chair, et sa fiente, il les brûla au feu, hors du camp, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Et il fit approcher le bélier de l’holocauste, et Aaron et ses fils posèrent leurs mains sur la tête du bélier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'et on l’égorgea, et Moïse fit aspersion du sang sur l’autel, tout autour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'et on coupa le bélier en morceaux, et Moïse en fit fumer la tête, et les morceaux, et la graisse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'et on lava avec de l’eau l’intérieur et les jambes, et Moïse fit fumer tout le bélier sur l’autel: ce fut un holocauste en odeur agréable, ce fut un sacrifice par feu à l’ Éternel, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Et il fit approcher le second bélier, le bélier de consécration; et Aaron et ses fils posèrent leurs mains sur la tête du bélier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'et on l’égorgea, et Moïse prit de son sang, et le mit sur le lobe de l’oreille droite d’Aaron, et sur le pouce de sa main droite, et sur le gros orteil de son pied droit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'et il fit approcher les fils d’Aaron, et Moïse mit du sang sur le lobe de leur oreille droite, et sur le pouce de leur main droite, et sur le gros orteil de leur pied droit; et Moïse fit aspersion du sang sur l’autel, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Et il prit la graisse, et la queue, et toute la graisse qui était sur l’intérieur, et le réseau du foie, et les deux rognons et leur graisse, et l’épaule droite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'et il prit, de la corbeille des pains sans levain qui était devant l’ Éternel, un gâteau sans levain, et un gâteau de pain à l’huile, et une galette, et les plaça sur les graisses et sur l’épaule droite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'et il mit le tout sur les paumes des mains d’Aaron et sur les paumes des mains de ses fils, et les tournoya comme offrande tournoyée devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Et Moïse les prit des paumes de leurs mains, et les fit fumer sur l’autel sur l’holocauste: ce fut un sacrifice de consécration, en odeur agréable; ce fut un sacrifice par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Et Moïse prit la poitrine, et la tournoya comme offrande tournoyée devant l’ Éternel; ce fut – du bélier de consécration – la part de Moïse, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Et Moïse prit de l’huile de l’onction et du sang qui était sur l’autel, et il en fit aspersion sur Aaron, sur ses vêtements, et sur ses fils et sur les vêtements de ses fils avec lui: il sanctifia Aaron, ses vêtements, et ses fils et les vêtements de ses fils avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Et Moïse dit à Aaron et à ses fils: Cuisez la chair à l’entrée de la tente d’assignation, et vous la mangerez là, ainsi que le pain qui est dans la corbeille de consécration, comme j’ai commandé, en disant: Aaron et ses fils les mangeront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Et le reste de la chair et du pain, vous le brûlerez au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Et vous ne sortirez pas de l’entrée de la tente d’assignation pendant sept jours, jusqu’au jour de l’accomplissement des jours de votre consécration; car on mettra sept jours à vous consacrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'L’ Éternel a commandé de faire comme on a fait aujourd’hui, pour faire propitiation pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Et vous demeurerez pendant sept jours à l’entrée de la tente d’assignation, jour et nuit, et vous garderez ce que l’ Éternel vous a donné à garder, afin que vous ne mouriez pas; car il m’a été ainsi commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Et Aaron et ses fils firent toutes les choses que l’ Éternel avait commandées par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Et il arriva, le huitième jour, que Moïse appela Aaron et ses fils, et les anciens d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'et il dit à Aaron: Prends un jeune veau pour le sacrifice pour le péché, et un bélier pour l’holocauste, sans défaut, et présente-les devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Et tu parleras aux fils d’Israël, en disant: Prenez un bouc pour le sacrifice pour le péché; et un veau, et un agneau, âgés d’un an, sans défaut, pour l’holocauste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'et un taureau et un bélier pour le sacrifice de prospérités, pour sacrifier devant l’ Éternel, et une offrande de gâteau pétri à l’huile, car aujourd’hui l’ Éternel vous apparaîtra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Et ils amenèrent devant la tente d’assignation ce que Moïse avait commandé; et toute l’assemblée s’approcha, et ils se tinrent devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Et Moïse dit: C’est ici ce que l’ Éternel a commandé; faites-le, et la gloire de l’ Éternel vous apparaîtra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Et Moïse dit à Aaron: Approche-toi de l’autel, et offre ton sacrifice pour le péché, et ton holocauste, et fais propitiation pour toi et pour le peuple; et offre l’offrande du peuple, et fais propitiation pour eux, comme l’ Éternel a commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Et Aaron s’approcha de l’autel, et égorgea le veau du sacrifice pour le péché, qui était pour lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'et les fils d’Aaron lui présentèrent le sang, et il trempa son doigt dans le sang, et le mit sur les cornes de l’autel, et versa le sang au pied de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Et il fit fumer sur l’autel la graisse, et les rognons, et le réseau pris du foie du sacrifice pour le péché, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Et la chair et la peau, il les brûla au feu, hors du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Et il égorgea l’holocauste, et les fils d’Aaron lui présentèrent le sang, et il en fit aspersion sur l’autel, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Et ils lui présentèrent l’holocauste [coupé] en morceaux, et la tête, et il les fit fumer sur l’autel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'et il lava l’intérieur et les jambes, et il les fit fumer sur l’holocauste sur l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, '– Et il présenta l’offrande du peuple: il prit le bouc du sacrifice pour le péché qui était pour le peuple, et l’égorgea, et l’offrit pour le péché, comme précédemment [le veau].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Et il présenta l’holocauste, et le fit selon l’ordonnance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Et il présenta l’offrande de gâteau, et il en remplit la paume de sa main et la fit fumer sur l’autel, outre l’holocauste du matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Et il égorgea le taureau et le bélier du sacrifice de prospérités qui était pour le peuple, et les fils d’Aaron lui présentèrent le sang, et il en fit aspersion sur l’autel, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Et [ils présentèrent] les graisses du taureau et du bélier, la queue, et ce qui couvre [l’intérieur], et les rognons, et le réseau du foie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'et ils mirent les graisses sur les poitrines, et il fit fumer les graisses sur l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Et Aaron tournoya en offrande tournoyée devant l’ Éternel les poitrines et l’épaule droite, comme Moïse l’avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, '– Et Aaron éleva ses mains vers le peuple et les bénit; et il descendit après avoir offert le sacrifice pour le péché, et l’holocauste, et le sacrifice de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Et Moïse et Aaron entrèrent dans la tente d’assignation; puis ils sortirent et bénirent le peuple: et la gloire de l’ Éternel apparut à tout le peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'et le feu sortit de devant l’ Éternel, et consuma sur l’autel l’holocauste et les graisses; et tout le peuple le vit, et ils poussèrent des cris de joie, et tombèrent sur leurs faces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, '*Et les fils d’Aaron, Nadab et Abihu, prirent chacun leur encensoir, et y mirent du feu, et placèrent de l’encens dessus, et présentèrent devant l’ Éternel un feu étranger, ce qu’il ne leur avait pas commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Et le feu sortit de devant l’ Éternel, et les dévora, et ils moururent devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Et Moïse dit à Aaron: C’est là ce que l’ Éternel prononça, en disant: Je serai sanctifié en ceux qui s’approchent de moi, et devant tout le peuple je serai glorifié. Et Aaron se tut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Et Moïse appela Mishaël et Eltsaphan, fils d’Uziel, oncle d’Aaron, et leur dit: Approchez-vous, emportez vos frères de devant le lieu saint, hors du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Et ils s’approchèrent, et les emportèrent dans leurs tuniques hors du camp, comme Moïse avait dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Et Moïse dit à Aaron, et à Éléazar et à Ithamar, ses fils: Ne découvrez pas vos têtes et ne déchirez pas vos vêtements, afin que vous ne mouriez pas, et qu’il n’y ait pas de la colère contre toute l’assemblée; mais vos frères, toute la maison d’Israël, pleureront l’embrasement que l’ Éternel a allumé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Et ne sortez pas de l’entrée de la tente d’assignation, de peur que vous ne mouriez, car l’huile de l’onction de l’ Éternel est sur vous. Et ils firent selon la parole de Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Et l’ Éternel parla à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Vous ne boirez point de vin ni de boisson forte, toi et tes fils avec toi, quand vous entrerez dans la tente d’assignation, afin que vous ne mouriez pas. [C’est] un statut perpétuel, en vos générations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'afin que vous discerniez entre ce qui est saint et ce qui est profane, et entre ce qui est impur et ce qui est pur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'et afin que vous enseigniez aux fils d’Israël tous les statuts que l’ Éternel leur a dits par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Et Moïse dit à Aaron, et à Éléazar et à Ithamar, ses fils qui restaient: Prenez l’offrande de gâteau, ce qui reste des sacrifices de l’ Éternel faits par feu, et mangez-la en pains sans levain, à côté de l’autel; car c’est une chose très sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Et vous la mangerez dans un lieu saint, parce que c’est là ta part et la part de tes fils dans les sacrifices de l’ Éternel faits par feu; car il m’a été ainsi commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Et vous mangerez la poitrine tournoyée et l’épaule élevée, dans un lieu pur, toi et tes fils et tes filles avec toi; car elles vous sont données comme ta part et la part de tes fils dans les sacrifices de prospérités des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Ils apporteront l’épaule élevée et la poitrine tournoyée (avec les sacrifices par feu, qui sont les graisses), pour les tournoyer comme offrande tournoyée devant l’ Éternel; et cela t’appartiendra, et à tes fils avec toi, par statut perpétuel, comme l’ Éternel l’a commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Et Moïse chercha diligemment le bouc du sacrifice pour le péché; mais voici, il avait été brûlé; et [Moïse] se mit en colère contre Éléazar et Ithamar, les fils d’Aaron qui restaient, et il [leur] dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Pourquoi n’avez-vous pas mangé le sacrifice pour le péché dans un lieu saint? car c’est une chose très sainte; et Il vous l’a donné pour porter l’iniquité de l’assemblée, pour faire propitiation pour eux devant l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'voici, son sang n’a pas été porté dans l’intérieur du lieu saint; vous devez de toute manière le manger dans le lieu saint, comme je l’ai commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Et Aaron dit à Moïse: Voici, ils ont présenté aujourd’hui leur sacrifice pour le péché et leur holocauste devant l’ Éternel, et ces choses me sont arrivées; et si j’avais mangé aujourd’hui le sacrifice pour le péché, cela aurait-il été bon aux yeux de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Et Moïse l’entendit, et cela fut bon à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, '*Et l’ Éternel parla à Moïse et à Aaron, leur disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Parlez aux fils d’Israël, en disant: Ce sont ici les animaux dont vous mangerez, d’entre toutes les bêtes qui sont sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Vous mangerez, d’entre les bêtes qui ruminent, tout ce qui a l’ongle fendu et le pied complètement divisé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Seulement de ceci vous ne mangerez pas, d’entre celles qui ruminent, et d’entre celles qui ont l’ongle fendu: le chameau, car il rumine, mais il n’a pas l’ongle fendu; il vous est impur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'et le daman, car il rumine, mais il n’a pas l’ongle fendu; il vous est impur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'et le lièvre, car il rumine, mais il n’a pas l’ongle fendu; il vous est impur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'et le porc, car il a l’ongle fendu et le pied complètement divisé, mais il ne rumine nullement; il vous est impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Vous ne mangerez pas de leur chair, et vous ne toucherez pas leur corps mort; ils vous sont impurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Vous mangerez de ceci, d’entre tout ce qui est dans les eaux: vous mangerez tout ce qui a des nageoires et des écailles, dans les eaux, dans les mers et dans les rivières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Et tout ce qui n’a point de nageoires et d’écailles, dans les mers et dans les rivières, de tout ce qui fourmille dans les eaux et de tout être vivant qui est dans les eaux, – vous sera une chose abominable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Cela vous sera une chose abominable; vous ne mangerez pas de leur chair, et vous aurez en abomination leur corps mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Tout ce qui, dans les eaux, n’a point de nageoires et d’écailles, vous sera une chose abominable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Et d’entre les oiseaux, vous aurez ceux-ci en abomination; on n’en mangera point, ce sera une chose abominable: l’aigle, et l’orfraie, et l’aigle de mer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'et le faucon, et le milan, selon son espèce;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'tout corbeau, selon son espèce;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'et l’autruche femelle, et l’autruche mâle, et la mouette, et l’épervier, selon son espèce;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'et le hibou, et le plongeon, et l’ibis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'et le cygne, et le pélican, et le vautour,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'et la cigogne, [et] le héron, selon son espèce, et la huppe, et la chauve-souris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Tout reptile volant qui marche sur quatre [pieds], vous sera une chose abominable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Seulement de ceci vous mangerez, d’entre tous les reptiles volants qui marchent sur quatre [pieds], ceux qui ont, au-dessus de leurs pieds, des jambes avec lesquelles ils sautent sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Ce sont ici ceux d’entre eux dont vous mangerez: la sauterelle selon son espèce, et le solham selon son espèce, et le khargol selon son espèce, et le khagab selon son espèce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Mais tout reptile volant qui a quatre pieds vous sera une chose abominable;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'et par eux vous vous rendrez impurs: quiconque touchera leur corps mort sera impur jusqu’au soir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'et quiconque portera [quelque chose] de leur corps mort lavera ses vêtements, et sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Toute bête qui a l’ongle fendu, mais qui n’a pas le [pied] complètement divisé et ne rumine pas, vous sera impure; quiconque les touchera sera impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Et tout ce qui marche sur ses pattes, parmi tous les animaux qui marchent sur quatre [pieds], vous sera impur; quiconque touchera leur corps mort sera impur jusqu’au soir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'et celui qui aura porté leur corps mort lavera ses vêtements, et sera impur jusqu’au soir. Ils vous seront impurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Et ceci vous sera impur parmi les reptiles qui rampent sur la terre: la taupe, et la souris, et le lézard selon son espèce;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'et le lézard gémissant, et le coakh, et le letaa, et le khometh, et le caméléon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Ceux-ci vous seront impurs parmi tous les reptiles; quiconque les touchera morts sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Et tout ce sur quoi il en tombera quand ils seront morts, sera impur: ustensile de bois, vêtement, peau, ou sac, – tout objet qui sert à un usage quelconque, sera mis dans l’eau, et sera impur jusqu’au soir; alors il sera net;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'et tout vase de terre dans lequel il en tombe quelque chose,... tout ce qui est dedans, sera impur, et vous casserez le [vase];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'et tout aliment qu’on mange, sur lequel il sera venu de [cette] eau, sera impur; et tout breuvage qu’on boit, dans quelque vase que ce soit, sera impur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'et tout ce sur quoi tombe quelque chose de leur corps mort, sera impur; le four et le foyer seront détruits: ils sont impurs, et ils vous seront impurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'mais une fontaine ou un puits, un amas d’eaux, sera net. Mais celui qui touchera leur corps mort sera impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Et s’il tombe quelque chose de leur corps mort sur une semence qui se sème, elle sera pure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'mais si on avait mis de l’eau sur la semence, et qu’il tombe sur elle quelque chose de leur corps mort, elle vous sera impure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, '– Et s’il meurt une des bêtes qui vous servent d’aliment, celui qui en touchera le corps mort sera impur jusqu’au soir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'et celui qui mangera de son corps mort lavera ses vêtements, et sera impur jusqu’au soir; et celui qui portera son corps mort lavera ses vêtements, et sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Et tout reptile qui rampe sur la terre sera une chose abominable; on n’en mangera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'De tout ce qui marche sur le ventre, et de tout ce qui marche sur quatre [pieds], et de tout ce qui a beaucoup de pieds, parmi tous les reptiles qui rampent sur la terre, vous n’en mangerez pas; car c’est une chose abominable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Ne rendez pas vos âmes abominables par aucun reptile qui rampe, et ne vous rendez pas impurs par eux, de sorte que vous soyez impurs par eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Car je suis l’ Éternel, votre Dieu: et vous vous sanctifierez, et vous serez saints, car je suis saint; et vous ne rendrez pas vos âmes impures par aucun reptile qui se meut sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Car je suis l’ Éternel qui vous ai fait monter du pays d’Égypte, afin que je sois votre Dieu: et vous serez saints, car je suis saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Telle est la loi touchant les bêtes et les oiseaux, et tout être vivant qui se meut dans les eaux, et tout être qui rampe sur la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'afin de discerner entre ce qui est impur et ce qui est pur, et entre l’animal qu’on mange et l’animal qu’on ne mangera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Parle aux fils d’Israël, en disant: Si une femme conçoit et enfante un fils, elle sera impure sept jours; elle sera impure comme aux jours de l’impureté de ses mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Et au huitième jour on circoncira la chair du prépuce de l’[enfant].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Et elle demeurera 33 jours dans le sang de sa purification; elle ne touchera aucune chose sainte, et ne viendra pas au sanctuaire, jusqu’à ce que les jours de sa purification soient accomplis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Et si c’est une fille qu’elle enfante, elle sera impure deux semaines, comme dans sa séparation, et elle demeurera 66 jours dans le sang de sa purification.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Et quand les jours de sa purification seront accomplis, pour un fils ou pour une fille, elle amènera au sacrificateur, à l’entrée de la tente d’assignation, un agneau âgé d’un an pour holocauste, et un jeune pigeon ou une tourterelle pour sacrifice pour le péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'et il présentera ces choses devant l’ Éternel, et fera propitiation pour elle, et elle sera purifiée du flux de son sang. Telle est la loi de celle qui enfante un fils ou une fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Et si ses moyens ne suffisent pas pour trouver un agneau, elle prendra deux tourterelles ou deux jeunes pigeons, l’un pour l’holocauste, et l’autre pour le sacrifice pour le péché; et le sacrificateur fera propitiation pour elle, et elle sera pure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, '*Et l’ Éternel parla à Moïse et à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Si un homme a dans la peau de sa chair une tumeur, ou une dartre, ou une tache blanchâtre, et qu’elle soit devenue, dans la peau de sa chair, une plaie [comme] de lèpre, on l’amènera à Aaron, le sacrificateur, ou à l’un de ses fils, les sacrificateurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'et le sacrificateur verra la plaie qui est dans la peau de sa chair; et si le poil dans la plaie est devenu blanc, et si la plaie paraît plus enfoncée que la peau de sa chair, c’est une plaie de lèpre; et le sacrificateur le verra, et le déclarera impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Et si la tache dans la peau de sa chair est blanche, et si elle ne paraît pas plus enfoncée que la peau, et si le poil n’est pas devenu blanc, le sacrificateur fera enfermer pendant sept jours [celui qui a] la plaie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'et le sacrificateur le verra le septième jour: et voici, la plaie est demeurée à ses yeux au même état, la plaie ne s’est pas étendue dans la peau; alors le sacrificateur le fera enfermer pendant sept autres jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Et le sacrificateur le verra pour la seconde fois, le septième jour: et voici, la plaie s’efface, et la plaie ne s’est pas étendue dans la peau; alors le sacrificateur le déclarera pur: c’est une dartre; et il lavera ses vêtements, et sera pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mais si la dartre s’est beaucoup étendue dans la peau, après qu’il aura été vu par le sacrificateur pour sa purification, il sera vu une seconde fois par le sacrificateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'et le sacrificateur le regardera: et voici, la dartre s’est étendue dans la peau; alors le sacrificateur le déclarera impur: c’est une lèpre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'S’il y a une plaie [comme] de lèpre dans un homme, on l’amènera au sacrificateur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'et le sacrificateur le verra: et voici, il y a une tumeur blanche dans la peau, et elle a fait devenir blanc le poil, et il y a une trace de chair vive dans la tumeur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, '– c’est une lèpre invétérée dans la peau de sa chair; alors le sacrificateur le déclarera impur; il ne le fera pas enfermer, car il est impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Et si la lèpre fait éruption sur la peau, et que la lèpre couvre toute la peau de [celui qui a] la plaie, de la tête aux pieds, autant qu’en pourra voir le sacrificateur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'le sacrificateur le verra: et voici, la lèpre a couvert toute sa chair; alors il déclarera pur [celui qui a] la plaie: il est tout entier devenu blanc; il est pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Et le jour où l’on verra en lui de la chair vive, il sera impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Et le sacrificateur regardera la chair vive, et le déclarera impur: la chair vive est impure, c’est de la lèpre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mais si la chair vive change et devient blanche, il viendra vers le sacrificateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'et le sacrificateur le verra: et voici, la plaie est devenue blanche; alors le sacrificateur déclarera pur [celui qui a] la plaie: il est pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Et si la chair a eu dans sa peau un ulcère, et qu’il soit guéri,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'et qu’il y ait, à l’endroit de l’ulcère, une tumeur blanche, ou une tache blanche roussâtre, [l’homme] se montrera au sacrificateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'et le sacrificateur la verra: et voici, elle paraît plus enfoncée que la peau, et son poil est devenu blanc; alors le sacrificateur le déclarera impur: c’est une plaie de lèpre, elle a fait éruption dans l’ulcère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Et si le sacrificateur la voit, et voici, il n’y a pas en elle de poil blanc, et elle n’est pas plus enfoncée que la peau, mais elle s’efface, le sacrificateur le fera enfermer pendant sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Et si elle s’est beaucoup étendue dans la peau, alors le sacrificateur le déclarera impur: c’est une plaie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Mais si la tache est demeurée à sa place au même état, [et] ne s’est pas étendue, c’est la cicatrice de l’ulcère: le sacrificateur le déclarera pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Ou si la chair a dans sa peau une brûlure de feu, et que la marque de la brûlure soit une tache d’un blanc roussâtre ou blanche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'le sacrificateur la verra: et voici, le poil est devenu blanc dans la tache, et elle paraît plus enfoncée que la peau, – c’est une lèpre; elle a fait éruption dans la brûlure; et le sacrificateur le déclarera impur: c’est une plaie de lèpre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Et si le sacrificateur la voit, et voici, il n’y a pas de poil blanc dans la tache, et elle n’est pas plus enfoncée que la peau, et elle s’efface, le sacrificateur le fera enfermer pendant sept jours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'et le sacrificateur le verra le septième jour: – si la [tache] s’est beaucoup étendue dans la peau, alors le sacrificateur le déclarera impur: c’est une plaie de lèpre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Mais si la tache est demeurée à sa place au même état, [et] ne s’est pas étendue dans la peau, et qu’elle s’efface, c’est une tumeur de la brûlure, et le sacrificateur le déclarera pur; car c’est la cicatrice de la brûlure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Et si un homme ou une femme a une plaie à la tête ou à la barbe,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'le sacrificateur verra la plaie: et voici, elle paraît plus enfoncée que la peau, ayant en elle du poil jaunâtre et fin, alors le sacrificateur le déclarera impur: c’est la teigne, c’est une lèpre de la tête ou de la barbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Et si le sacrificateur voit la plaie de la teigne, et voici, elle ne paraît pas plus enfoncée que la peau, et elle n’a pas de poil noir, alors le sacrificateur fera enfermer pendant sept jours [celui qui a] la plaie de la teigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Et le sacrificateur verra la plaie le septième jour: et voici, la teigne ne s’est pas étendue, et elle n’a pas de poil jaunâtre, et la teigne ne paraît pas plus enfoncée que la peau,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'alors l’homme se rasera, mais il ne rasera pas [l’endroit de] la teigne; et le sacrificateur fera enfermer pendant sept autres jours [celui qui a] la teigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Et le sacrificateur verra la teigne le septième jour: et voici, la teigne ne s’est pas étendue dans la peau, et elle ne paraît pas plus enfoncée que la peau, alors le sacrificateur le déclarera pur; et l’homme lavera ses vêtements, et il sera pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Et si la teigne s’est beaucoup étendue dans la peau, après sa purification,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'le sacrificateur le verra; et si la teigne s’est étendue dans la peau, le sacrificateur ne cherchera pas de poil jaunâtre: il est impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Et si la teigne est demeurée au même état, à ses yeux, et que du poil noir y ait poussé, la teigne est guérie: il est pur, et le sacrificateur le déclarera pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Et si un homme ou une femme a dans la peau de sa chair des taches, des taches blanches,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'le sacrificateur le verra; et voici, dans la peau de leur chair, il y a des taches blanches, ternes, c’est une simple tache qui a fait éruption dans la peau: il est pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Et si un homme a perdu les cheveux de sa tête, il est chauve: il est pur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'et s’il a perdu les cheveux de sa tête du côté du visage, il est chauve par-devant: il est pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Et s’il y a, dans la partie chauve du haut ou de devant, une plaie blanche roussâtre, c’est une lèpre qui a fait éruption dans la partie chauve du haut ou de devant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'et le sacrificateur le verra: et voici, la tumeur de la plaie est d’un blanc roussâtre dans la partie chauve du haut ou de devant, comme une apparence de lèpre dans la peau de la chair;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'c’est un homme lépreux, il est impur; le sacrificateur le déclarera entièrement impur: sa plaie est en sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Et le lépreux en qui sera la plaie aura ses vêtements déchirés et sa tête découverte, et il se couvrira la barbe, et il criera: Impur! Impur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Tout le temps que la plaie sera en lui, il sera impur; il est impur; il habitera seul, son habitation sera hors du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Et s’il y a une plaie de lèpre en un vêtement, en un vêtement de laine ou en un vêtement de lin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'ou dans la chaîne ou dans la trame du lin ou de la laine, ou dans une peau, ou dans quelque ouvrage [fait] de peau,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'et si la plaie est verdâtre ou roussâtre dans le vêtement, ou dans la peau, ou dans la chaîne, ou dans la trame, ou dans quelque objet [fait] de peau, c’est une plaie de lèpre, et elle sera montrée au sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Et le sacrificateur verra la plaie, et il fera enfermer pendant sept jours [l’objet où est] la plaie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'et le septième jour, il verra la plaie: – si la plaie s’est étendue dans le vêtement, soit dans la chaîne, soit dans la trame, soit dans la peau, dans un ouvrage quelconque qui a été fait de peau, la plaie est une lèpre rongeante: la chose est impure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Alors on brûlera le vêtement, ou la chaîne, ou la trame de laine ou de lin, ou tout objet [fait] de peau dans lequel est la plaie; car c’est une lèpre rongeante; la chose sera brûlée au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Et si le sacrificateur regarde, et voici, la plaie ne s’est pas étendue dans le vêtement, ou dans la chaîne, ou dans la trame, ou dans quelque objet [fait] de peau,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'alors le sacrificateur commandera qu’on lave l’objet où est la plaie, et le fera enfermer pendant sept autres jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Et le sacrificateur verra, après que la plaie aura été lavée: et voici, la plaie n’a pas changé d’aspect, et la plaie ne s’est pas étendue, – la chose est impure, tu la brûleras au feu; c’est une érosion à son envers ou à son endroit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Et si le sacrificateur regarde, et voici, la plaie s’efface après avoir été lavée, alors on l’arrachera du vêtement, ou de la peau, ou de la chaîne, ou de la trame.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Et si elle paraît encore dans le vêtement, ou dans la chaîne, ou dans la trame, ou dans quelque objet [fait] de peau, c’est une [lèpre] qui fait éruption; tu brûleras au feu l’objet où est la plaie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Et le vêtement, ou la chaîne, ou la trame, ou tout objet [fait] de peau que tu auras lavé, et d’où la plaie s’est retirée, sera lavé une seconde fois, et il sera pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Telle est la loi touchant la plaie de la lèpre dans un vêtement de laine ou de lin, ou dans la chaîne ou dans la trame, ou dans quelque objet [fait] de peau, pour le purifier ou le déclarer impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'C’est ici la loi du lépreux, au jour de sa purification: il sera amené au sacrificateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'et le sacrificateur sortira hors du camp; et le sacrificateur le verra: et voici, le lépreux est guéri de la plaie de la lèpre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'alors le sacrificateur commandera qu’on prenne, pour celui qui doit être purifié, deux oiseaux vivants et purs, et du bois de cèdre, et de l’écarlate, et de l’hysope;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'et le sacrificateur commandera qu’on égorge l’un des oiseaux sur un vase de terre, sur de l’eau vive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Quant à l’oiseau vivant, il le prendra, et le bois de cèdre, et l’écarlate, et l’hysope, et il les trempera, ainsi que l’oiseau vivant, dans le sang de l’oiseau égorgé sur l’eau vive;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'et il fera aspersion, sept fois, sur celui qui doit être purifié de la lèpre, et il le purifiera; puis il lâchera dans les champs l’oiseau vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Et celui qui doit être purifié lavera ses vêtements et rasera tout son poil, et se lavera dans l’eau; et il sera pur. Et après cela, il entrera dans le camp, et il habitera sept jours hors de sa tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Et il arrivera que, le septième jour, il rasera tout son poil, sa tête et sa barbe et ses sourcils; il rasera tout son poil; et il lavera ses vêtements, et il lavera sa chair dans l’eau, et il sera pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Et le huitième jour, il prendra deux agneaux sans défaut, et une jeune brebis âgée d’un an, sans défaut, et trois dixièmes de fleur de farine pétrie à l’huile, en offrande de gâteau, et un log d’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Et le sacrificateur qui fait la purification placera l’homme qui doit être purifié, et ces choses, devant l’ Éternel, à l’entrée de la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'et le sacrificateur prendra l’un des agneaux, et le présentera comme sacrifice pour le délit, avec le log d’huile, et les tournoiera en offrande tournoyée devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'puis il égorgera l’agneau au lieu où l’on égorge le sacrifice pour le péché et l’holocauste, dans un lieu saint; car le sacrifice pour le délit est comme le sacrifice pour le péché, il appartient au sacrificateur: c’est une chose très sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Et le sacrificateur prendra du sang du sacrifice pour le délit, et le sacrificateur le mettra sur le lobe de l’oreille droite de celui qui doit être purifié, et sur le pouce de sa main droite, et sur le gros orteil de son pied droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Et le sacrificateur prendra du log d’huile, et en versera dans la paume de sa main gauche, à lui, le sacrificateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'et le sacrificateur trempera le doigt de sa [main] droite dans l’huile qui est dans sa paume gauche, et fera aspersion de l’huile avec son doigt, sept fois, devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Et du reste de l’huile qui sera dans sa paume, le sacrificateur en mettra sur le lobe de l’oreille droite de celui qui doit être purifié, et sur le pouce de sa main droite, et sur le gros orteil de son pied droit, sur le sang du sacrifice pour le délit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'et le reste de l’huile qui sera dans la paume du sacrificateur, il le mettra sur la tête de celui qui doit être purifié; et le sacrificateur fera propitiation pour lui devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Et le sacrificateur offrira le sacrifice pour le péché, et fera propitiation pour celui qui doit être purifié de son impureté; et après, il égorgera l’holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Et le sacrificateur offrira l’holocauste et le gâteau sur l’autel; et le sacrificateur fera propitiation pour celui [qui doit être purifié], et il sera pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Et s’il est pauvre, et que sa main ne puisse atteindre jusque-là, il prendra un agneau comme sacrifice pour le délit, pour offrande tournoyée, afin de faire propitiation pour lui, et un dixième de fleur de farine pétrie à l’huile, pour offrande de gâteau, et un log d’huile,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'et deux tourterelles ou deux jeunes pigeons, selon ce que sa main pourra atteindre: l’un sera un sacrifice pour le péché, l’autre un holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Et le huitième jour de sa purification, il les apportera au sacrificateur, à l’entrée de la tente d’assignation, devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'et le sacrificateur prendra l’agneau du sacrifice pour le délit, et le log d’huile, et le sacrificateur les tournoiera en offrande tournoyée devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'et il égorgera l’agneau du sacrifice pour le délit; et le sacrificateur prendra du sang du sacrifice pour le délit, et le mettra sur le lobe de l’oreille droite de celui qui doit être purifié, et sur le pouce de sa main droite, et sur le gros orteil de son pied droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Et le sacrificateur versera de l’huile dans la paume de sa main gauche, à lui, le sacrificateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'et avec le doigt de sa [main] droite, le sacrificateur fera aspersion de l’huile qui sera dans la paume de sa main gauche, sept fois, devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Et le sacrificateur mettra de l’huile qui sera dans sa paume, sur le lobe de l’oreille droite de celui qui doit être purifié, et sur le pouce de sa main droite, et sur le gros orteil de son pied droit, sur l’endroit où [aura été mis] le sang du sacrifice pour le délit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'et le reste de l’huile qui sera dans la paume du sacrificateur, il le mettra sur la tête de celui qui doit être purifié, pour faire propitiation pour lui devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Et, de ce que sa main aura pu atteindre, il offrira l’une des tourterelles, ou l’un des jeunes pigeons:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'de ce que sa main aura pu atteindre, l’un sera un sacrifice pour le péché, l’autre un holocauste, avec l’offrande de gâteau; et le sacrificateur fera propitiation pour celui qui doit être purifié, devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, '– Telle est la loi touchant celui en qui il y a une plaie de lèpre, et dont la main n’a pas su atteindre [ce qui était ordonné] pour sa purification.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, '*Et l’ Éternel parla à Moïse et à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Quand vous serez entrés dans le pays de Canaan, que je vous donne en possession, si je mets une plaie de lèpre dans une maison du pays de votre possession,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'celui à qui sera la maison viendra et le fera savoir au sacrificateur, en disant: Il me semble voir comme une plaie dans ma maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'et le sacrificateur commandera qu’on vide la maison avant que le sacrificateur entre pour voir la plaie, afin que tout ce qui est dans la maison ne soit pas rendu impur; et après cela, le sacrificateur entrera pour voir la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Et il regardera la plaie: et voici, la plaie est dans les murs de la maison, des creux verdâtres ou roussâtres, et ils paraissent plus enfoncés que la surface du mur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'alors le sacrificateur sortira de la maison, à l’entrée de la maison, et fera fermer la maison pendant sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Et le septième jour, le sacrificateur retournera, et regardera: et voici, la plaie s’est étendue dans les murs de la maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'alors le sacrificateur commandera qu’on arrache les pierres dans lesquelles est la plaie, et qu’on les jette hors de la ville, dans un lieu impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Et il fera racler la maison au-dedans, tout autour, et la poussière qu’on aura raclée, on la versera hors de la ville, dans un lieu impur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'et on prendra d’autres pierres, et on les mettra au lieu des [premières] pierres, et on prendra d’autre enduit, et on enduira la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Et si la plaie revient et fait éruption dans la maison après qu’on aura arraché les pierres, et après qu’on aura raclé la maison, et après qu’on l’aura enduite,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'le sacrificateur entrera et regardera: et voici, la plaie s’est étendue dans la maison, – c’est une lèpre rongeante dans la maison: elle est impure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Alors on démolira la maison, ses pierres et son bois, avec tout l’enduit de la maison, et on les transportera hors de la ville, dans un lieu impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Et celui qui sera entré dans la maison pendant tous les jours où elle aura été fermée, sera impur jusqu’au soir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'et celui qui aura couché dans la maison lavera ses vêtements; et celui qui aura mangé dans la maison lavera ses vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Mais si le sacrificateur entre, et regarde, et voici, la plaie ne s’est pas étendue dans la maison après que la maison a été enduite, le sacrificateur déclarera la maison pure, car la plaie est guérie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Et il prendra, pour purifier la maison, deux oiseaux, et du bois de cèdre, et de l’écarlate, et de l’hysope;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'et il égorgera l’un des oiseaux sur un vase de terre, sur de l’eau vive;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'et il prendra le bois de cèdre, et l’hysope, et l’écarlate, et l’oiseau vivant, et les trempera dans le sang de l’oiseau égorgé, et dans l’eau vive; et il fera aspersion sur la maison, sept fois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'et il purifiera la maison avec le sang de l’oiseau et avec l’eau vive, et avec l’oiseau vivant, et avec le bois de cèdre, et avec l’hysope, et avec l’écarlate;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'et il lâchera l’oiseau vivant hors de la ville, dans les champs. Et il fera propitiation pour la maison, et elle sera pure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Telle est la loi touchant toute plaie de lèpre, et la teigne,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'et touchant la lèpre des vêtements et des maisons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'et les tumeurs, et les dartres, et les taches blanchâtres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'pour enseigner en quel temps il y a impureté et en quel temps il y a pureté: telle est la loi de la lèpre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, '*Et l’ Éternel parla à Moïse et à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Parlez aux fils d’Israël, et dites-leur: Tout homme qui a un flux [découlant] de sa chair, – son flux le rend impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Et ceci sera son impureté, dans son flux: soit que sa chair laisse couler son flux, ou que sa chair retienne son flux, c’est son impureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Tout lit sur lequel aura couché celui qui est atteint d’un flux sera impur; et tout objet sur lequel il se sera assis sera impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Et l’homme qui aura touché son lit lavera ses vêtements, et se lavera dans l’eau; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Et celui qui s’assiéra sur un objet sur lequel celui qui a le flux se sera assis, lavera ses vêtements, et se lavera dans l’eau; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Et celui qui touchera la chair de celui qui a le flux, lavera ses vêtements, et se lavera dans l’eau; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Et si celui qui a le flux crache sur un [homme] qui est pur, celui-ci lavera ses vêtements, et se lavera dans l’eau; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Tout char sur lequel sera monté celui qui a le flux sera impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Et quiconque touchera quelque chose qui aura été sous lui, sera impur jusqu’au soir; et celui qui portera une de ces choses lavera ses vêtements, et se lavera dans l’eau; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Et quiconque aura été touché par celui qui a le flux et qui n’aura pas lavé ses mains dans l’eau, lavera ses vêtements, et se lavera dans l’eau; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Et les vases de terre que celui qui a le flux aura touchés seront cassés; et tout vase de bois sera lavé dans l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Et lorsque celui qui a le flux sera purifié de son flux, il comptera sept jours pour sa purification; puis il lavera ses vêtements, et il lavera sa chair dans l’eau vive; et il sera pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Et le huitième jour, il prendra deux tourterelles, ou deux jeunes pigeons, et il viendra devant l’ Éternel, à l’entrée de la tente d’assignation, et les donnera au sacrificateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'et le sacrificateur les offrira, l’un en sacrifice pour le péché, et l’autre en holocauste; et le sacrificateur fera propitiation pour lui devant l’ Éternel, à cause de son flux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Et lorsque la semence sort d’un homme, il lavera dans l’eau toute sa chair; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Et tout vêtement ou toute peau sur lesquels il y aura de la semence, sera lavé dans l’eau, et sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Et une femme avec laquelle un homme aura couché ayant commerce avec elle;... ils se laveront dans l’eau, et seront impurs jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Et si une femme a un flux, et que son flux en sa chair soit du sang, elle sera dans sa séparation sept jours, et quiconque la touchera sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Et toute chose sur laquelle elle aura couché durant sa séparation sera impure; et toute chose sur laquelle elle aura été assise sera impure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'et quiconque touchera son lit lavera ses vêtements, et se lavera dans l’eau; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Et quiconque touchera un objet, quel qu’il soit, sur lequel elle se sera assise, lavera ses vêtements, et se lavera dans l’eau; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Et s’il y a quelque chose sur le lit, ou sur l’objet, quel qu’il soit, sur lequel elle se sera assise, quiconque l’aura touché sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Et si un homme a couché avec elle, et que son impureté soit sur lui, il sera impur sept jours; et tout lit sur lequel il se couchera sera impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Et lorsqu’une femme a un flux de sang qui coule plusieurs jours hors le temps de sa séparation, ou lorsqu’elle a le flux au-delà du temps de sa séparation, tous les jours du flux de son impureté elle est impure, comme aux jours de sa séparation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Tout lit sur lequel elle couchera tous les jours de son flux sera pour elle comme le lit de sa séparation; et tout objet sur lequel elle se sera assise sera impur, selon l’impureté de sa séparation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Et quiconque aura touché ces choses sera impur, et il lavera ses vêtements, et se lavera dans l’eau; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Et si elle est purifiée de son flux, elle comptera sept jours, et après, elle sera pure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'et le huitième jour, elle prendra deux tourterelles ou deux jeunes pigeons, et les apportera au sacrificateur, à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Et le sacrificateur offrira l’un en sacrifice pour le péché, et l’autre en holocauste; et le sacrificateur fera propitiation pour elle devant l’ Éternel, à cause du flux de son impureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Et vous séparerez les fils d’Israël de leurs impuretés, et ils ne mourront pas dans leurs impuretés, en souillant mon tabernacle qui est au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Telle est la loi pour celui qui a un flux ou pour celui duquel sort de la semence qui le rend impur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'et pour la femme qui souffre à cause de ses mois, pendant sa séparation, et pour toute personne qui a un flux, soit homme, soit femme, et pour celui qui couche avec une femme impure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, '*Et l’ Éternel parla à Moïse, après la mort des deux fils d’Aaron, lorsque, s’étant approchés de l’ Éternel, ils moururent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'et l’ Éternel dit à Moïse: Dis à Aaron, ton frère, qu’il n’entre pas en tout temps dans le lieu saint, au-dedans du voile, devant le propitiatoire qui est sur l’arche, afin qu’il ne meure pas; car j’apparais dans la nuée sur le propitiatoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Aaron entrera de cette manière dans le lieu saint: avec un jeune taureau pour sacrifice pour le péché, et un bélier pour holocauste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'il se revêtira d’une sainte tunique de lin, et des caleçons de lin seront sur sa chair, et il se ceindra d’une ceinture de lin, et il s’enveloppera la tête d’une tiare de lin: ce sont de saints vêtements; et il lavera sa chair dans l’eau; puis il s’en vêtira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Et il prendra de l’assemblée des fils d’Israël deux boucs pour un sacrifice pour le péché, et un bélier pour un holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Et Aaron présentera le taureau du sacrifice pour le péché, qui est pour lui-même, et fera propitiation pour lui-même et pour sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Et il prendra les deux boucs, et les placera devant l’ Éternel, à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Et Aaron jettera le sort sur les deux boucs, un sort pour l’ Éternel et un sort pour azazel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Et Aaron présentera le bouc sur lequel le sort sera tombé pour l’ Éternel, et en fera un sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Et le bouc sur lequel le sort sera tombé pour azazel, sera placé vivant devant l’ Éternel, afin de faire propitiation sur lui, pour l’envoyer au désert pour être azazel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Et Aaron présentera le taureau du sacrifice pour le péché, qui est pour lui-même, et fera propitiation pour lui-même et pour sa maison; et il égorgera le taureau du sacrifice pour le péché, qui est pour lui-même;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'puis il prendra plein un encensoir de charbons de feu, de dessus l’autel [qui est] devant l’ Éternel, et plein ses paumes d’encens de drogues odoriférantes pulvérisées, et il les apportera au-dedans du voile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'et il mettra l’encens sur le feu, devant l’ Éternel, pour que la nuée de l’encens couvre le propitiatoire qui est sur le témoignage, afin qu’il ne meure pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Et il prendra du sang du taureau, et il en fera aspersion avec son doigt sur le devant du propitiatoire, vers l’orient; et il fera aspersion du sang avec son doigt, sept fois, devant le propitiatoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Et il égorgera le bouc du sacrifice pour le péché, qui est pour le peuple, et il apportera son sang au-dedans du voile, et fera avec son sang, comme il a fait avec le sang du taureau: il en fera aspersion sur le propitiatoire et devant le propitiatoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Et il fera propitiation pour le lieu saint, [le purifiant] des impuretés des fils d’Israël et de leurs transgressions, selon tous leurs péchés; et il fera de même pour la tente d’assignation, qui demeure avec eux au milieu de leurs impuretés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Et personne ne sera dans la tente d’assignation quand il y entrera pour faire propitiation dans le lieu saint, jusqu’à ce qu’il en sorte; et il fera propitiation pour lui-même et pour sa maison, et pour toute la congrégation d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Et il sortira vers l’autel qui est devant l’ Éternel, et fera propitiation pour lui; et il prendra du sang du taureau et du sang du bouc, et le mettra sur les cornes de l’autel, tout autour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'et il fera sur lui aspersion du sang avec son doigt, sept fois, et il le purifiera, et le sanctifiera des impuretés des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Et quand il aura achevé de faire propitiation pour le lieu saint, et pour la tente d’assignation, et pour l’autel, il présentera le bouc vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Et Aaron posera ses deux mains sur la tête du bouc vivant, et confessera sur lui toutes les iniquités des fils d’Israël et toutes leurs transgressions, selon tous leurs péchés; il les mettra sur la tête du bouc, et l’enverra au désert par un homme qui se tiendra prêt [pour cela];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'et le bouc portera sur lui toutes leurs iniquités dans une terre inhabitée; et l’homme laissera aller le bouc dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Et Aaron rentrera à la tente d’assignation, et quittera les vêtements de lin dont il s’était vêtu quand il était entré dans le lieu saint, et les déposera là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'et il lavera sa chair dans l’eau dans un lieu saint, et se revêtira de ses vêtements; et il sortira, et il offrira son holocauste et l’holocauste du peuple, et fera propitiation pour lui-même et pour le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Et il fera fumer sur l’autel la graisse du sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Et celui qui aura conduit le bouc pour être azazel, lavera ses vêtements, et lavera sa chair dans l’eau; et après cela il rentrera dans le camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Et on transportera hors du camp le taureau du sacrifice pour le péché et le bouc du sacrifice pour le péché, desquels le sang aura été porté dans le lieu saint pour faire propitiation, et on brûlera au feu leur peau, et leur chair, et leur fiente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Et celui qui les aura brûlées lavera ses vêtements, et lavera sa chair dans l’eau; et après cela il rentrera dans le camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Et ceci sera pour vous un statut perpétuel: au septième mois, le dixième [jour] du mois, vous affligerez vos âmes, et vous ne ferez aucune œuvre, tant l’Israélite de naissance que l’étranger qui séjourne au milieu de vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'car, en ce jour-là, il sera fait propitiation pour vous, afin de vous purifier: [et] vous serez purs de tous vos péchés devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ce sera pour vous un sabbat de repos, et vous affligerez vos âmes; [c’est] un statut perpétuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Et le sacrificateur qui aura été oint et qui aura été consacré pour exercer la sacrificature à la place de son père, fera propitiation; et il revêtira les vêtements de lin, les saints vêtements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'et il fera propitiation pour le saint sanctuaire, et il fera propitiation pour la tente d’assignation et pour l’autel, et il fera propitiation pour les sacrificateurs et pour tout le peuple de la congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Et ceci sera pour vous un statut perpétuel, afin de faire propitiation pour les fils d’Israël [pour les purifier] de tous leurs péchés, une fois l’an. Et on fit comme l’ Éternel avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Parle à Aaron et à ses fils, et à tous les fils d’Israël, et dis-leur: C’est ici ce que l’ Éternel a commandé, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Quiconque de la maison d’Israël aura égorgé un bœuf ou un mouton ou une chèvre, dans le camp, ou qui l’aura égorgé hors du camp,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'et ne l’aura pas amené à l’entrée de la tente d’assignation pour le présenter comme offrande à l’ Éternel devant le tabernacle de l’ Éternel, le sang sera imputé à cet homme-là: il a versé du sang; cet homme-là sera retranché du milieu de son peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, '– afin que les fils d’Israël amènent leurs sacrifices qu’ils sacrifient dans les champs, qu’ils les amènent à l’ Éternel, à l’entrée de la tente d’assignation, vers le sacrificateur, et qu’ils les sacrifient en sacrifices de prospérités à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Et le sacrificateur fera aspersion du sang sur l’autel de l’ Éternel, à l’entrée de la tente d’assignation, et en fera fumer la graisse en odeur agréable à l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'et ils ne sacrifieront plus leurs sacrifices aux démons après lesquels ils se prostituent. Ceci sera pour eux un statut perpétuel, en leurs générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Et tu leur diras: Quiconque de la maison d’Israël, ou des étrangers qui séjournent au milieu d’eux, offrira un holocauste ou un sacrifice,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'et ne l’amènera pas à l’entrée de la tente d’assignation pour le sacrifier à l’ Éternel, cet homme-là sera retranché de ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Et quiconque de la maison d’Israël ou des étrangers qui séjournent au milieu d’eux, aura mangé de quelque sang que ce soit, je mettrai ma face contre celui qui aura mangé du sang, et je le retrancherai du milieu de son peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'car l’âme de la chair est dans le sang; et moi je vous l’ai donné sur l’autel, pour faire propitiation pour vos âmes; car c’est le sang qui fait propitiation pour l’âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'C’est pourquoi j’ai dit aux fils d’Israël: Personne d’entre vous ne mangera du sang, et l’étranger qui séjourne au milieu de vous ne mangera pas de sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Et quiconque des fils d’Israël et des étrangers qui séjournent au milieu d’eux prendra, à la chasse, une bête ou un oiseau qui se mange, en versera le sang et le recouvrira de poussière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'car, quant à la vie de toute chair, son sang est sa vie en elle; et j’ai dit aux fils d’Israël: Vous ne mangerez le sang d’aucune chair; car l’âme de toute chair est son sang; quiconque en mangera sera retranché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Et toute personne, tant l’Israélite de naissance que l’étranger, qui mangera du corps d’une bête morte [d’elle-même] ou déchirée, lavera ses vêtements et se lavera dans l’eau, et sera impure jusqu’au soir: alors elle sera pure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Et si elle ne lave pas [ses vêtements] et ne lave pas sa chair, elle portera son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Parle aux fils d’Israël, et dis-leur: Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Vous ne ferez pas ce qui se fait dans le pays d’Égypte où vous avez habité, et vous ne ferez pas ce qui se fait dans le pays de Canaan où je vous fais entrer, et vous ne marcherez pas selon leurs coutumes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Vous pratiquerez mes ordonnances, et vous garderez mes statuts pour y marcher. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Et vous garderez mes statuts et mes ordonnances, par lesquels, s’il les pratique, un homme vivra. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nul homme ne s’approchera de sa proche parente, pour découvrir sa nudité. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Tu ne découvriras point la nudité de ton père, ni la nudité de ta mère: c’est ta mère; tu ne découvriras point sa nudité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Tu ne découvriras point la nudité de la femme de ton père; c’est la nudité de ton père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'La nudité de ta sœur, fille de ton père ou fille de ta mère, née dans la maison ou née au-dehors, – sa nudité, tu ne la découvriras point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'La nudité de la fille de ton fils ou de la fille de ta fille, – sa nudité, tu ne la découvriras point; car c’est ta nudité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'La nudité de la fille de la femme de ton père, née de ton père, – c’est ta sœur: tu ne découvriras point sa nudité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Tu ne découvriras point la nudité de la sœur de ton père; elle est propre chair de ton père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Tu ne découvriras point la nudité de la sœur de ta mère; car elle est propre chair de ta mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Tu ne découvriras point la nudité du frère de ton père; tu ne t’approcheras point de sa femme: elle est ta tante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Tu ne découvriras point la nudité de ta belle-fille: elle est la femme de ton fils; tu ne découvriras point sa nudité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Tu ne découvriras point la nudité de la femme de ton frère; c’est la nudité de ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Tu ne découvriras point la nudité d’une femme et de sa fille; tu ne prendras point la fille de son fils, ni la fille de sa fille, pour découvrir sa nudité; elles sont sa propre chair: c’est un crime.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Et tu ne prendras point une femme auprès de sa sœur pour l’affliger en découvrant sa nudité à côté d’elle, de son vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Et tu ne t’approcheras point d’une femme durant la séparation de son impureté, pour découvrir sa nudité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Et tu n’auras point commerce avec la femme de ton prochain, pour te rendre impur avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Et tu ne donneras point de tes enfants pour les faire passer [par le feu] à Moloc, et tu ne profaneras point le nom de ton Dieu. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Tu ne coucheras point avec un mâle, comme on couche avec une femme: c’est une abomination.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Tu ne coucheras point avec une bête pour te rendre impur avec elle; et une femme ne se tiendra pas devant une bête, pour se prostituer à elle: c’est une confusion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Vous ne vous rendrez point impurs par aucune de ces choses, car c’est par toutes ces choses que les nations que je chasse devant vous se sont rendues impures;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'et le pays s’est rendu impur; et je punis sur lui son iniquité, et le pays vomit ses habitants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Mais vous, vous garderez mes statuts et mes ordonnances, et vous ne ferez aucune de toutes ces abominations, ni l’Israélite de naissance, ni l’étranger qui séjourne au milieu de vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'car les hommes du pays, qui y ont été avant vous, ont pratiqué toutes ces abominations, et le pays en a été rendu impur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'afin que le pays ne vous vomisse pas, quand vous l’aurez rendu impur, comme il a vomi la nation qui y a été avant vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Car quiconque fera l’une de toutes ces abominations,... les âmes qui les pratiqueront, seront retranchées du milieu de leur peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Et vous garderez ce que j’ai ordonné de garder, en sorte que vous ne pratiquiez pas les coutumes abominables qui se sont pratiquées avant vous; et vous ne vous rendrez point impurs par elles. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Parle à toute l’assemblée des fils d’Israël, et dis-leur: Vous serez saints, car moi, l’ Éternel votre Dieu, je suis saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Vous craindrez chacun sa mère et son père; et vous garderez mes sabbats. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Vous ne vous tournerez point vers les idoles, et vous ne vous ferez point de dieux de fonte. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Et si vous sacrifiez un sacrifice de prospérités à l’ Éternel, vous le sacrifierez pour être agréés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Il sera mangé le jour où vous l’aurez sacrifié, et le lendemain; et ce qui restera le troisième jour, sera brûlé au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Et si on en mange de quelque manière le troisième jour, ce sera une chose impure; il ne sera point agréé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Et celui qui en mangera portera son iniquité, car il a profané ce qui est consacré à l’ Éternel; et cette âme-là sera retranchée de ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Et quand vous ferez la moisson de votre terre, tu n’achèveras pas de moissonner les coins de ton champ et tu ne glaneras pas la glanure de ta moisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Et tu ne grappilleras pas ta vigne, ni ne recueilleras les grains tombés de ta vigne; tu les laisseras pour le pauvre et pour l’étranger. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Vous ne volerez pas, et vous ne vous tromperez pas [l’un l’autre], et vous ne vous mentirez pas l’un à l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Et vous ne jurerez pas par mon nom, en mentant; et tu ne profaneras pas le nom de ton Dieu. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Tu n’opprimeras pas ton prochain, et tu ne le pilleras pas. Le salaire de ton homme à gages ne passera pas la nuit chez toi jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Tu ne maudiras pas le sourd, et tu ne mettras pas d’achoppement devant l’aveugle, mais tu craindras ton Dieu. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Vous ne ferez pas d’injustice dans le jugement: tu n’auras pas égard à la personne du pauvre, et tu n’honoreras pas la personne du riche; tu jugeras ton prochain avec justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Tu n’iras point çà et là médisant parmi ton peuple. Tu ne t’élèveras pas contre la vie de ton prochain. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Tu ne haïras point ton frère dans ton cœur. Tu ne manqueras pas à reprendre ton prochain, et tu ne porteras pas de péché à cause de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Tu ne te vengeras pas, et tu ne garderas pas rancune aux fils de ton peuple; mais tu aimeras ton prochain comme toi-même. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Vous garderez mes statuts. Tu n’accoupleras pas, parmi ton bétail, deux espèces différentes. Tu ne sèmeras pas ton champ de deux espèces [de semence]; et tu ne mettras pas sur toi un vêtement d’un tissu mélangé de deux espèces de fil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Et si un homme couche et a commerce avec une femme, et qu’elle soit servante, fiancée à un homme, et qu’elle n’ait aucunement été rachetée ni mise en liberté, ils seront châtiés; on ne les mettra pas à mort, car elle n’avait pas été mise en liberté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Et l’homme amènera à l’ Éternel, à l’entrée de la tente d’assignation, son sacrifice pour le délit, un bélier en sacrifice pour le délit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Et le sacrificateur fera propitiation pour lui devant l’ Éternel, avec le bélier du sacrifice pour le délit, à cause de son péché qu’il a commis; et son péché qu’il a commis lui sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Et quand vous serez entrés dans le pays, et que vous y aurez planté toute sorte d’arbres dont on mange, vous en regarderez le fruit comme incirconcis; il sera incirconcis pour vous pendant trois ans: on n’en mangera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Et la quatrième année tout leur fruit sera une chose sainte à la louange de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Et la cinquième année vous mangerez leur fruit, afin qu’ils vous multiplient leur rapport. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Vous ne mangerez rien avec le sang. – Vous ne pratiquerez ni enchantements, ni pronostics.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, '– Vous n’arrondirez point les coins de votre chevelure, et vous ne gâterez pas les coins de votre barbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Et vous ne ferez point d’incisions dans votre chair pour un mort, et vous ne vous ferez pas de tatouages. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, '– Tu ne profaneras point ta fille, pour la faire se prostituer, afin que le pays ne se prostitue pas et que le pays ne se remplisse pas d’infamie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, '– Vous garderez mes sabbats, et vous révérerez mon sanctuaire. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, '– Ne vous tournez pas vers ceux qui évoquent les esprits, ni vers les diseurs de bonne aventure; n’ayez pas recours à eux pour vous rendre impurs. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Tu te lèveras devant les cheveux blancs, et tu honoreras la personne du vieillard, et tu craindras ton Dieu. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Si quelque étranger séjourne avec toi dans votre pays, vous ne l’opprimerez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'L’étranger qui séjourne parmi vous sera pour vous comme l’Israélite de naissance, et tu l’aimeras comme toi-même; car vous avez été étrangers dans le pays d’Égypte. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Et vous ne ferez pas d’injustice dans le jugement, ni dans la mesure de longueur, ni dans le poids, ni dans la mesure de capacité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Vous aurez des balances justes, des poids justes, l’épha juste, et le hin juste. Moi, je suis l’ Éternel, votre Dieu, qui vous ai fait sortir du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Et vous garderez tous mes statuts et toutes mes ordonnances, et vous les ferez. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Tu diras aussi aux fils d’Israël: Quiconque d’entre les fils d’Israël, ou d’entre les étrangers qui séjournent en Israël, donnera de ses enfants à Moloc, sera certainement mis à mort; le peuple du pays le lapidera avec des pierres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Et moi, je mettrai ma face contre cet homme-là, et je le retrancherai du milieu de son peuple, parce qu’il a donné de ses enfants à Moloc, pour rendre impur mon sanctuaire et pour profaner mon saint nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Et si le peuple du pays ferme les yeux, en quelque manière, sur cet homme, quand il donne de ses enfants à Moloc, pour ne pas le faire mourir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'moi, je mettrai ma face contre cet homme et contre sa famille, et je le retrancherai du milieu de son peuple, lui et tous ceux qui se prostituent après lui, se prostituant après Moloc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, '– Et l’âme qui se tournera vers ceux qui évoquent les esprits, et vers les diseurs de bonne aventure, se prostituant après eux, je mettrai ma face contre cette âme-là, et je la retrancherai du milieu de son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Et vous vous sanctifierez et vous serez saints, car moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Et vous garderez mes statuts, et vous les ferez. Moi, je suis l’ Éternel qui vous sanctifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Tout homme qui maudira son père et sa mère sera certainement mis à mort; il a maudit son père et sa mère, son sang est sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Et un homme qui commet adultère avec la femme d’un autre, – qui commet adultère avec la femme de son prochain...: l’homme et la femme adultères seront certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Et l’homme qui couchera avec la femme de son père, découvre la nudité de son père; ils seront certainement mis à mort, tous deux: leur sang est sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Et si un homme couche avec sa belle-fille, ils seront certainement mis à mort, tous deux; ils ont fait une confusion: leur sang est sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Et si un homme couche avec un mâle, comme on couche avec une femme, ils ont fait tous deux une chose abominable; ils seront certainement mis à mort: leur sang est sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Et si un homme prend une femme et sa mère, c’est une infamie; on les brûlera au feu, lui et elles, et il n’y aura point d’infamie au milieu de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Et si un homme couche avec une bête, il sera certainement mis à mort; et vous tuerez la bête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Et si une femme s’approche d’une bête, quelle qu’elle soit, pour se prostituer à elle, tu tueras la femme et la bête; elles seront certainement mises à mort: leur sang est sur elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Et si un homme prend sa sœur, fille de son père, ou fille de sa mère, et voit sa nudité, et qu’elle voie sa nudité à lui, c’est une honte: ils seront retranchés devant les yeux des fils de leur peuple; il a découvert la nudité de sa sœur, il portera son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Et si un homme couche avec une femme qui a son infirmité, et découvre sa nudité, il met à découvert son flux, et elle découvre le flux de son sang: ils seront tous deux retranchés du milieu de leur peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Et tu ne découvriras point la nudité de la sœur de ta mère, ni de la sœur de ton père; car celui qui fait cela met à nu sa propre chair: ils porteront leur iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Et si un homme couche avec sa tante, il découvre la nudité de son oncle; ils porteront leur péché: ils mourront sans enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Et si un homme prend la femme de son frère, c’est une impureté; il découvre la nudité de son frère: ils n’auront pas d’enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Et vous garderez tous mes statuts et toutes mes ordonnances, et vous les ferez; afin que le pays où je vous fais entrer pour y habiter ne vous vomisse pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Et vous ne marcherez point dans les statuts de la nation que je chasse devant vous; car ils ont fait toutes ces choses-là, et je les ai eus en abomination;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'et je vous ai dit: C’est vous qui posséderez leur terre, et je vous la donnerai pour la posséder, un pays ruisselant de lait et de miel. Moi, je suis l’ Éternel, votre Dieu, qui vous ai séparés des peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Et vous discernerez entre la bête pure et l’impure, et entre l’oiseau impur et le pur, et vous ne vous rendrez point abominables par des bêtes, ou par des oiseaux, ou par tout ce qui rampe sur la terre, que j’ai séparé, le déclarant impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Et vous me serez saints, car je suis saint, moi, l’ Éternel; et je vous ai séparés des peuples, pour être à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Et si un homme ou une femme sont évocateurs d’esprits, ou diseurs de bonne aventure, ils seront certainement mis à mort; on les lapidera avec des pierres: leur sang sera sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, '*Et l’ Éternel dit à Moïse: Parle aux sacrificateurs, fils d’Aaron, et dis-leur: Que le sacrificateur ne se rende pas impur parmi ses peuples pour un mort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'excepté pour son proche parent, pour sa mère, et pour son père, et pour son fils, et pour sa fille, et pour son frère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'et pour sa sœur vierge qui lui est proche, et qui n’aura pas été mariée, pour elle il se rendra impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Il ne se rendra pas impur comme chef parmi son peuple, pour se profaner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Ils ne se feront point de place chauve sur leur tête, et ils ne raseront pas les coins de leur barbe ni ne se feront d’incisions dans leur chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Ils seront saints, [consacrés] à leur Dieu, et ils ne profaneront pas le nom de leur Dieu, car ils présentent les sacrifices de l’ Éternel faits par feu, le pain de leur Dieu; et ils seront saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Ils ne prendront point pour femme une prostituée ou une femme déshonorée; et ils ne prendront pas une femme répudiée par son mari, car le sacrificateur est saint, [consacré] à son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Et tu le tiendras pour saint, car il présente le pain de ton Dieu. Il te sera saint, car je suis saint, moi, l’ Éternel qui vous sanctifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Et si la fille d’un sacrificateur se profane en se prostituant, elle profane son père; elle sera brûlée au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Et le grand sacrificateur d’entre ses frères, sur la tête duquel l’huile de l’onction aura été versée et qui aura été consacré pour revêtir les [saints] vêtements, ne découvrira pas sa tête et ne déchirera pas ses vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Il n’ira vers aucune personne morte; il ne se rendra impur ni pour son père, ni pour sa mère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'et il ne sortira pas du sanctuaire, et ne profanera pas le sanctuaire de son Dieu; car la consécration de l’huile de l’onction de son Dieu est sur lui. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Et il prendra pour femme une vierge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Une veuve, ou une répudiée, ou une femme déshonorée, une prostituée, il ne les prendra point; mais il prendra pour femme une vierge d’entre ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Et il ne profanera pas sa semence parmi ses peuples, car moi, je suis l’ Éternel qui le sanctifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Parle à Aaron, en disant: Aucun homme de ta semence, en ses générations, qui a quelque défaut corporel, ne s’approchera pour présenter le pain de son Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'car quiconque a un défaut corporel ne s’approchera pas: l’homme aveugle, ou boiteux, ou camus, ou qui a l’un de ses membres plus long que l’autre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'ou l’homme qui a une fracture au pied ou une fracture à la main;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'ou celui qui est bossu, ou grêle, ou qui a une tache à l’œil, ou qui a une gale, ou une dartre, ou qui a les testicules écrasés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Nul homme de la semence d’Aaron, le sacrificateur, en qui il y aura quelque défaut corporel, ne s’approchera pour présenter les sacrifices de l’ Éternel faits par feu; il y a en lui un défaut corporel: il ne s’approchera pas pour présenter le pain de son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Il mangera du pain de son Dieu, des choses très saintes et des choses saintes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'seulement il n’entrera pas vers le voile, et ne s’approchera pas de l’autel, car il y a en lui un défaut corporel, et il ne profanera pas mes sanctuaires; car moi, je suis l’ Éternel qui les sanctifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Moïse parla ainsi à Aaron et à ses fils, et à tous les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Parle à Aaron et à ses fils, afin qu’ils se séparent des choses saintes des fils d’Israël, et qu’ils ne profanent pas mon saint nom dans les choses que ceux-ci me sanctifient. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Dis-leur: Tout homme de toute votre semence, en vos générations, qui, ayant son impureté sur lui, s’approchera des choses saintes que les fils d’Israël ont sanctifiées à l’ Éternel, cette âme-là sera retranchée de devant moi. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Aucun homme de la semence d’Aaron, qui est lépreux ou qui a un flux, ne mangera des choses saintes, jusqu’à ce qu’il soit purifié; et celui qui aura touché quelqu’un qui est impur par un mort, ou celui de qui est sorti de la semence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'ou celui qui a touché un reptile quelconque qui le rende impur, ou un homme qui le rende impur de quelque impureté dont il soit affecté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, '– l’homme qui aura touché cela, sera impur jusqu’au soir, et ne mangera pas des choses saintes, s’ il n’a pas lavé sa chair dans l’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'et après le coucher du soleil il sera pur; et ensuite, il mangera des choses saintes, car c’est son pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, '[Aucun d’eux] ne mangera d’une bête morte [d’elle-même] ou déchirée, pour se rendre impur par elle. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Et ils garderont ce que j’ai ordonné de garder, afin qu’ils ne portent pas de péché sur eux, et qu’ils ne meurent pas, pour avoir profané [mon ordonnance]. Moi, je suis l’ Éternel qui les sanctifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Et aucun étranger ne mangera de ce qui est saint; celui qui demeure chez un sacrificateur, et l’homme à gages, ne mangeront pas de ce qui est saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mais si le sacrificateur a acheté de son argent un esclave, celui-ci en mangera, ainsi que celui qui est né dans sa maison: ceux-là mangeront de son pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Et une fille de sacrificateur, si elle est [mariée] à un étranger, ne mangera pas des offrandes élevées des choses saintes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Mais si une fille de sacrificateur est veuve ou répudiée, et n’a pas d’enfants, et est retournée dans la maison de son père, comme dans sa jeunesse, elle mangera du pain de son père; mais aucun étranger n’en mangera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Et si un homme, par ignorance, mange d’une chose sainte, il donnera au sacrificateur la chose sainte, et y ajoutera un cinquième par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Et on ne profanera pas les choses saintes des fils d’Israël, qu’ils offrent en offrande élevée à l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'et on ne leur fera pas porter l’iniquité du délit quand ils mangeront de leurs choses saintes, car moi je suis l’ Éternel qui les sanctifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Parle à Aaron et à ses fils, et à tous les fils d’Israël, et dis-leur: Quiconque de la maison d’Israël ou de ceux qui séjournent en Israël, présentera son offrande, selon tous leurs vœux et selon toutes leurs offrandes volontaires qu’ils présentent en holocauste à l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, '– pour être agréé, [offrira] un mâle sans tare, de gros bétail, de moutons, ou de chèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Vous ne présenterez aucune chose qui ait quelque défaut corporel, car elle ne sera point agréée pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Et si un homme présente un sacrifice de prospérités à l’ Éternel, pour s’acquitter d’un vœu, ou en offrande volontaire, soit de gros bétail, soit de menu bétail, [son offrande] sera sans tare, pour être agréée; il n’y aura en elle aucun défaut corporel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Vous ne présenterez point à l’ Éternel ce qui est aveugle, ou qui a une fracture ou qui est mutilé, ou qui a des ulcères, ou une gale, ou une dartre, et vous n’en ferez pas un sacrifice fait par feu sur l’autel, à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Tu pourras faire un sacrifice volontaire d’un bœuf ou d’un agneau ayant quelque membre trop long ou trop court; mais pour un vœu, ils ne seront pas agréés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Et vous ne présenterez pas à l’ Éternel ce qui sera froissé, ou écrasé, ou arraché, ou coupé; vous ne ferez point cela dans votre pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Et de la main d’un étranger, vous ne présenterez aucune de ces choses comme le pain de votre Dieu; car leur corruption est en elles, il y a un défaut en elles: elles ne seront pas agréées pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Un veau, ou un agneau ou un chevreau, lorsqu’il sera né, sera sept jours sous sa mère; et depuis le huitième jour et après, il sera agréé pour l’offrande du sacrifice fait par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Et vous n’égorgerez pas la vache, ou la brebis, elle et son petit, en un même jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Et si vous sacrifiez un sacrifice d’action de grâces à l’ Éternel, vous le sacrifierez pour être agréé pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Il sera mangé le jour même; vous n’en laisserez rien jusqu’au matin. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Et vous garderez mes commandements, et vous les ferez. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Et vous ne profanerez pas mon saint nom, mais je serai sanctifié au milieu des fils d’Israël: moi, je suis l’ Éternel qui vous sanctifie');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, '[et] qui vous ai fait sortir du pays d’Égypte pour être votre Dieu. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Parle aux fils d’Israël, et dis-leur: Les jours solennels de l’ Éternel, que vous publierez, seront de saintes convocations. Ce sont ici mes jours solennels:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Six jours on travaillera; et le septième jour est un sabbat de repos, une sainte convocation; vous ne ferez aucune œuvre: c’est un sabbat [consacré] à l’ Éternel dans toutes vos habitations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Ce sont ici les jours solennels de l’ Éternel, de saintes convocations, que vous publierez en leurs temps assignés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Le premier mois, le quatorzième [jour] du mois, entre les deux soirs, est la Pâque à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Et le quinzième jour de ce mois, est la fête des pains sans levain à l’ Éternel: sept jours, vous mangerez des pains sans levain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Le premier jour, vous aurez une sainte convocation; vous ne ferez aucune œuvre de service;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'et vous présenterez à l’ Éternel, pendant sept jours, un sacrifice par feu: au septième jour [il y aura] une sainte convocation; vous ne ferez aucune œuvre de service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Parle aux fils d’Israël, et dis-leur: Quand vous serez entrés dans le pays que je vous donne et que vous en aurez fait la moisson, vous apporterez au sacrificateur une gerbe des prémices de votre moisson;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'et il tournoiera la gerbe devant l’ Éternel, pour que vous soyez agréés; le sacrificateur la tournoiera le lendemain du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Et le jour où vous ferez tournoyer la gerbe, vous offrirez un agneau sans défaut, âgé d’un an, en holocauste à l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'et pour son offrande de gâteau, deux dixièmes de fleur de farine pétrie à l’huile, un sacrifice par feu à l’ Éternel, une odeur agréable; et sa libation sera du vin, le quart d’un hin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Et vous ne mangerez ni pain, ni grain rôti, ni grain en épi, jusqu’à ce même jour, jusqu’à ce que vous ayez apporté l’offrande de votre Dieu. [C’est] un statut perpétuel, en vos générations, dans toutes vos habitations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, '– Et vous compterez depuis le lendemain du sabbat, depuis le jour où vous aurez apporté la gerbe de l’offrande tournoyée, sept semaines; elles seront complètes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'vous compterez 50 jours jusqu’au lendemain du septième sabbat, et vous présenterez à l’ Éternel une offrande de gâteau nouvelle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'vous apporterez de vos habitations deux pains, en offrande tournoyée; ils seront de deux dixièmes de fleur de farine; vous les cuirez avec du levain: ce sont les premiers fruits à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Et vous présenterez avec le pain sept agneaux sans défaut, âgés d’un an, et un jeune taureau, et deux béliers: ils seront un holocauste à l’ Éternel, avec leur offrande de gâteau et leurs libations, un sacrifice par feu, une odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Et vous offrirez un bouc en sacrifice pour le péché, et deux agneaux âgés d’un an en sacrifice de prospérités;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'et le sacrificateur les tournoiera avec le pain des premiers fruits, en offrande tournoyée devant l’ Éternel, avec les deux agneaux: ils seront saints, [consacrés] à l’ Éternel pour le sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Et vous publierez [une convocation] en ce même jour; ce sera pour vous une sainte convocation; vous ne ferez aucune œuvre de service: [c’est] un statut perpétuel, dans toutes vos habitations, en vos générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, '– Et quand vous ferez la moisson de votre terre, tu n’achèveras pas de moissonner les coins de ton champ, et tu ne glaneras pas la glanure de ta moisson; tu les laisseras pour le pauvre et pour l’étranger. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Parle aux fils d’Israël, en disant: Au septième mois, le premier [jour] du mois, il y aura un repos pour vous, un mémorial de jubilation, une sainte convocation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'vous ne ferez aucune œuvre de service, et vous présenterez à l’ Éternel un sacrifice fait par feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'De même, le dixième [jour] de ce septième mois, c’est le jour des propitiations: ce sera pour vous une sainte convocation, et vous affligerez vos âmes, et vous présenterez à l’ Éternel un sacrifice fait par feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Et ce même jour vous ne ferez aucune œuvre, car c’est un jour de propitiation, pour faire propitiation pour vous, devant l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Car toute âme qui ne s’affligera pas en ce même jour, sera retranchée de ses peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Et toute âme qui fera une œuvre quelconque en ce même jour, cette âme, je la ferai périr du milieu de son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Vous ne ferez aucune œuvre: [c’est] un statut perpétuel, en vos générations, dans toutes vos habitations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'C’est un sabbat de repos pour vous, et vous affligerez vos âmes. Le neuvième [jour] du mois, au soir, d’un soir à l’autre soir, vous célébrerez votre sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Parle aux fils d’Israël, en disant: Le quinzième jour de ce septième mois, la fête des tabernacles [se célébrera] à l’ Éternel pendant sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Le premier jour il y aura une sainte convocation; vous ne ferez aucune œuvre de service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Pendant sept jours vous présenterez à l’ Éternel un sacrifice fait par feu; le huitième jour, vous aurez une sainte convocation, et vous présenterez à l’ Éternel un sacrifice fait par feu: c’est une assemblée solennelle; vous ne ferez aucune œuvre de service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Ce sont là les jours solennels de l’ Éternel, que vous publierez, de saintes convocations, afin de présenter des sacrifices faits par feu à l’ Éternel, des holocaustes, et des offrandes de gâteau, des sacrifices, et des libations, chaque jour ce qui est établi pour ce jour,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'outre les sabbats de l’ Éternel, et outre vos dons, et outre tous vos vœux, et outre toutes vos offrandes volontaires que vous donnerez à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Mais le quinzième jour du septième mois, quand vous aurez recueilli le rapport de la terre, vous célébrerez la fête de l’ Éternel pendant sept jours: le premier jour il y aura repos, et le huitième jour il y aura repos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Et le premier jour vous prendrez du fruit de beaux arbres, des branches de palmiers, et des rameaux d’arbres touffus et de saules de rivière; et vous vous réjouirez devant l’ Éternel, votre Dieu, pendant sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Et vous célébrerez la fête comme fête à l’ Éternel, pendant sept jours chaque année; [c’est] un statut perpétuel, en vos générations: vous la célébrerez le septième mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Vous habiterez sept jours dans des tabernacles; tous les indigènes en Israël habiteront dans des tabernacles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'afin que vos générations sachent que j’ai fait habiter les fils d’Israël dans des tabernacles, lorsque je les fis sortir du pays d’Égypte. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Et Moïse dit aux fils d’Israël les jours solennels de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Commande aux fils d’Israël qu’ils t’apportent de l’huile d’olive pure, broyée, pour le luminaire, afin de faire brûler la lampe continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Aaron l’arrangera devant l’ Éternel, continuellement, du soir au matin, en dehors du voile du témoignage, dans la tente d’assignation: [c’est] un statut perpétuel en vos générations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'il arrangera les lampes sur le chandelier pur, devant l’ Éternel, continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Et tu prendras de la fleur de farine, et tu en cuiras douze gâteaux: chaque gâteau sera de deux dixièmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'et tu les placeras en deux rangées, six par rangée, sur la table pure, devant l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'et tu mettras de l’encens pur sur [chaque] rangée; et ce sera un pain de mémorial, un sacrifice par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Chaque jour de sabbat on les arrangera devant l’ Éternel, continuellement, de la part des fils d’Israël: [c’est] une alliance perpétuelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Et cela appartiendra à Aaron et à ses fils, et ils le mangeront dans un lieu saint; car ce lui sera une chose très sainte d’entre les sacrifices de l’ Éternel faits par feu: [c’est] un statut perpétuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Et le fils d’une femme israélite (mais il était fils d’un homme égyptien), sortit parmi les fils d’Israël; et le fils de la femme israélite et un homme israélite se battirent dans le camp;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'et le fils de la femme israélite blasphéma le Nom et [le] maudit; et on l’amena à Moïse. Or le nom de sa mère était Shelomith, fille de Dibri, de la tribu de Dan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Et on le mit sous garde, afin de décider [de son sort], selon la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Fais sortir hors du camp celui qui a maudit; et que tous ceux qui l’ont entendu posent leurs mains sur sa tête, et que toute l’assemblée le lapide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Et tu parleras aux fils d’Israël, en disant: Tout homme qui aura maudit son Dieu, portera son péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'et celui qui blasphémera le nom de l’ Éternel sera certainement mis à mort: toute l’assemblée ne manquera pas de le lapider; on mettra à mort tant l’étranger que l’Israélite de naissance, lorsqu’il aura blasphémé le Nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Et si quelqu’un a frappé à mort un homme, il sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Et celui qui aura frappé à mort une bête, fera compensation, vie pour vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Et si un homme a causé quelque mal corporel à son prochain, il lui sera fait comme il a fait:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'fracture pour fracture, œil pour œil, dent pour dent; selon le mal corporel qu’il aura causé à un homme, ainsi il lui sera fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Celui qui frappera [à mort] une bête, fera compensation pour elle, et celui qui aura frappé [à mort] un homme, sera mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Il y aura une même loi pour vous: il en sera de l’étranger comme de l’Israélite de naissance; car moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Et Moïse parla aux fils d’Israël, et ils firent sortir hors du camp celui qui avait maudit, et le lapidèrent avec des pierres. Et les fils d’Israël firent comme l’ Éternel avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, '*Et l’ Éternel parla à Moïse, sur la montagne de Sinaï, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Parle aux fils d’Israël, et dis-leur: Quand vous serez entrés dans le pays que je vous donne, le pays célébrera un sabbat à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Pendant six ans tu sèmeras ton champ, et pendant six ans tu tailleras ta vigne, et tu en recueilleras le rapport;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'et la septième année, il y aura un sabbat de repos pour le pays, un sabbat [consacré] à l’ Éternel: tu ne sèmeras pas ton champ, et tu ne tailleras pas ta vigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Tu ne moissonneras pas ce qui vient de soi-même de ta moisson [précédente], et tu ne vendangeras pas les grappes de ta vigne non taillée: ce sera une année de repos pour le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Et le sabbat du pays vous servira de nourriture, à toi, et à ton serviteur, et à ta servante, et à ton homme à gages et à ton hôte qui séjournent chez toi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'et à ton bétail et aux animaux qui seront dans ton pays: tout son rapport servira de nourriture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Et tu compteras sept sabbats d’années, sept fois sept ans; et les jours de ces sept sabbats d’années te feront 49 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Et, au septième mois, le dixième [jour] du mois, tu feras passer le son bruyant de la trompette; le jour des propitiations, vous ferez passer la trompette par tout votre pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'et vous sanctifierez l’année de l’an cinquantième, et vous publierez la liberté dans le pays à tous ses habitants: ce sera pour vous un jubilé; vous retournerez chacun dans sa possession, et vous retournerez chacun à sa famille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Cette année de l’an cinquantième sera pour vous un jubilé: vous ne sèmerez pas, et vous ne moissonnerez pas ce qui vient de soi-même, et vous ne vendangerez pas la vigne non taillée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'car c’est le Jubilé: il vous sera saint; vous mangerez en l’y prenant ce que le champ rapportera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'En cette année du Jubilé, vous retournerez chacun dans sa possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Et si vous vendez quelque chose à votre prochain, ou si vous achetez de la main de votre prochain, que nul ne fasse tort à son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Tu achèteras de ton prochain d’après le nombre des années depuis le Jubilé; il te vendra d’après le nombre des années de rapport.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'À proportion que le nombre des années sera grand, tu augmenteras le prix; et à proportion que le nombre des années sera petit, tu diminueras le prix, car c’est le nombre des récoltes qu’il te vend.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Et nul de vous ne fera tort à son prochain, et tu craindras ton Dieu, car moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Et vous pratiquerez mes statuts, et vous garderez mes ordonnances, et vous les pratiquerez, et ainsi vous habiterez dans le pays en sécurité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'et le pays vous donnera son fruit, et vous mangerez à rassasiement, et vous l’habiterez en sécurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Et si vous dites: Que mangerons-nous la septième année; voici, nous ne semons pas, et nous ne recueillons pas nos produits?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'je commanderai que ma bénédiction soit sur vous en la sixième année, et elle donnera le produit de trois ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Et vous sèmerez la huitième année et vous mangerez du vieux produit, jusqu’à la neuvième année; jusqu’à ce que son produit soit venu, vous mangerez le vieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Et le pays ne se vendra pas à perpétuité, car le pays est à moi; car vous, vous êtes chez moi comme des étrangers et comme des hôtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Et dans tout le pays de votre possession, vous donnerez le droit de rachat pour la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Si ton frère est devenu pauvre, et vend une partie de sa possession, alors que celui qui a le droit de rachat, son plus proche parent, vienne et rachète la chose vendue par son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Mais si un homme n’a personne qui ait le droit de rachat, et que sa main ait acquis et trouvé suffisamment de quoi faire son rachat,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'il comptera les années depuis sa vente, et restituera le surplus à celui à qui il avait vendu, et il retournera dans sa possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Et si sa main n’a pas trouvé suffisamment de quoi lui rendre, la chose vendue restera en la main de celui qui l’aura achetée, jusqu’à l’année du Jubilé: la chose vendue sera libérée au Jubilé, et [le vendeur] rentrera dans sa possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Et si quelqu’un a vendu une maison d’habitation dans une ville murée, il aura son droit de rachat jusqu’à la fin de l’année de sa vente: son droit de rachat subsistera une année entière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'mais si elle n’est pas rachetée avant que l’année entière soit accomplie, la maison qui est dans la ville murée restera définitivement à l’acheteur, en ses générations; elle ne sera pas libérée au Jubilé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mais les maisons des villages qui n’ont pas de murs tout autour, seront considérées comme des champs du pays; il y aura droit de rachat pour elles, et elles seront libérées au Jubilé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Et quant aux villes des Lévites et aux maisons des villes de leur possession, les Lévites auront un droit perpétuel de rachat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Et si quelqu’un a racheté d’un des Lévites, la maison vendue dans la ville de sa possession sera libérée au Jubilé; car les maisons des villes des Lévites sont leur possession au milieu des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Et les champs des banlieues de leurs villes ne seront pas vendus, car c’est leur possession à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Et si ton frère est devenu pauvre, et que sa main devienne tremblante à côté de toi, tu le soutiendras, étranger ou hôte, afin qu’il vive à côté de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Tu ne prendras de lui ni intérêt ni usure; et tu craindras ton Dieu, afin que ton frère vive à côté de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Tu ne lui donneras pas ton argent à intérêt, et tu ne lui donneras pas tes vivres à usure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Moi, je suis l’ Éternel, votre Dieu, qui vous ai fait sortir du pays d’Égypte pour vous donner le pays de Canaan, pour être votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Et si ton frère est devenu pauvre à côté de toi, et qu’il se vende à toi, tu ne lui feras pas faire un service d’esclave;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'il sera avec toi comme un homme à gages et un hôte; il te servira jusqu’à l’année du Jubilé:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'alors il sortira de chez toi, lui et ses fils avec lui, et il retournera à sa famille, et retournera dans la possession de ses pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Car ils sont mes serviteurs, que j’ai fait sortir du pays d’Égypte; ils ne seront pas vendus comme on vend les esclaves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Tu ne domineras pas sur lui avec dureté, et tu craindras ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Mais quant à ton serviteur et à ta servante qui seront à toi,... d’entre les nations qui vous environnent, de ceux-là, vous achèterez des serviteurs et des servantes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Et vous en achèterez aussi des fils des étrangers qui séjournent chez vous, et de leurs familles qui sont avec vous, qu’ils engendreront dans votre pays; et ils seront votre possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Et vous les laisserez en héritage à vos fils après vous, pour qu’ils en aient la possession; vous vous servirez d’eux à toujours; mais quant à vos frères, les fils d’Israël, un homme ne dominera pas avec dureté sur son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Et si un étranger ou un homme qui séjourne chez toi s’est enrichi, et que ton frère qui est à côté de lui soit devenu pauvre et se soit vendu à l’étranger qui séjourne chez toi, ou à un homme issu de la famille de l’étranger,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, '– après qu’il se sera vendu, il y aura pour lui droit de rachat; un de ses frères le rachètera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'ou son oncle, ou le fils de son oncle le rachètera; ou quelque proche parent de sa famille le rachètera; ou si sa main y peut atteindre, il se rachètera lui-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Et il comptera avec celui qui l’a acheté, depuis l’année où il s’est vendu à lui jusqu’à l’année du Jubilé; et l’argent de son prix sera à raison du nombre des années; il sera chez son maître selon les journées d’un homme à gages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'S’il y a encore beaucoup d’années, il restituera le prix de son rachat à raison de celles-ci, sur le prix pour lequel il aura été acheté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'et s’il reste peu d’années jusqu’à l’année du Jubilé, il comptera avec lui; à raison du nombre des années, il restituera le prix de son rachat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Il sera chez lui comme un homme à gages, d’année en année; le maître ne dominera pas sur lui avec dureté devant tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Et s’il n’est pas racheté par un de ces moyens, il sortira l’année du Jubilé, lui et ses fils avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Car les fils d’Israël me sont serviteurs; ils sont mes serviteurs que j’ai fait sortir du pays d’Égypte. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '*Vous ne vous ferez pas d’idoles, et vous ne vous dresserez pas d’image taillée, ou de statue, et vous ne mettrez pas de pierre sculptée dans votre pays, pour vous prosterner devant elles; car moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Vous garderez mes sabbats, et vous révérerez mon sanctuaire. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Si vous marchez dans mes statuts, et si vous gardez mes commandements et les pratiquez,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'je vous donnerai vos pluies en leur temps, et la terre donnera son rapport, et l’arbre des champs donnera son fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Le temps du foulage atteindra pour vous la vendange, et la vendange atteindra les semailles; et vous mangerez votre pain à rassasiement, et vous habiterez en sécurité dans votre pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Et je donnerai la paix dans le pays; et vous dormirez sans que personne vous épouvante; et je ferai disparaître du pays les bêtes mauvaises, et l’épée ne passera pas par votre pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Et vous poursuivrez vos ennemis, et ils tomberont devant vous par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Et cinq d’entre vous en poursuivront 100, et 100 d’entre vous en poursuivront 10 000, et vos ennemis tomberont devant vous par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Et je me tournerai vers vous, et je vous ferai fructifier, et je vous multiplierai, et je mettrai à effet mon alliance avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Et vous mangerez de vieilles provisions, et vous sortirez le vieux de devant le nouveau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Et je mettrai mon tabernacle au milieu de vous, et mon âme ne vous aura pas en horreur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'et je marcherai au milieu de vous; et je serai votre Dieu, et vous serez mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Moi, je suis l’ Éternel, votre Dieu, qui vous ai fait sortir du pays d’Égypte, afin que vous ne soyez pas leurs esclaves: j’ai brisé les liens de votre joug, et je vous ai fait marcher la tête levée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Mais si vous ne m’écoutez pas, et si vous ne pratiquez pas tous ces commandements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'et si vous méprisez mes statuts, et si votre âme a en horreur mes ordonnances, de sorte que vous ne pratiquiez pas tous mes commandements et que vous rompiez mon alliance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'moi aussi, je vous ferai ceci: J’ordonnerai sur vous la frayeur, la consomption et la fièvre qui consumeront vos yeux et feront défaillir votre âme; et vous sèmerez en vain votre semence, car vos ennemis la mangeront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Et je tournerai ma face contre vous: vous serez battus devant vos ennemis; ceux qui vous haïssent domineront sur vous; et vous fuirez sans que personne vous poursuive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Et si, après cela encore, vous ne m’écoutez pas, je vous châtierai encore sept fois plus à cause de vos péchés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'et je briserai l’orgueil de votre force, et je ferai que votre ciel sera comme de fer, et votre terre comme d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Et vous dépenserez votre force en vain, et votre terre ne donnera pas son rapport, et les arbres de la terre ne donneront pas leur fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Et si vous marchez en opposition avec moi et que vous ne vouliez pas m’écouter, je vous frapperai encore sept fois plus, selon vos péchés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'et j’enverrai contre vous les bêtes des champs, qui vous raviront vos enfants, et détruiront votre bétail, et vous réduiront à un petit nombre; et vos chemins seront désolés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Et si par ces choses-là vous ne recevez pas mon instruction, et que vous marchiez en opposition avec moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'je marcherai, moi aussi, en opposition avec vous, et je vous frapperai, moi aussi, sept fois plus, à cause de vos péchés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'et je ferai venir sur vous l’épée qui exécute la vengeance de l’alliance; et quand vous serez rassemblés dans vos villes, j’enverrai la peste au milieu de vous, et vous serez livrés en la main de l’ennemi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Quand je vous briserai le bâton du pain, dix femmes cuiront votre pain dans un seul four et vous rendront votre pain au poids; et vous mangerez, et vous ne serez pas rassasiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Et si avec cela vous ne m’écoutez pas, et que vous marchiez en opposition avec moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'je marcherai aussi en opposition avec vous, avec fureur, et je vous châtierai, moi aussi, sept fois plus, à cause de vos péchés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'et vous mangerez la chair de vos fils, et vous mangerez la chair de vos filles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'je détruirai vos hauts lieux, et j’abattrai vos colonnes consacrées au soleil, et je mettrai vos cadavres sur les cadavres de vos idoles, et mon âme vous aura en horreur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Et je réduirai vos villes en déserts, et je désolerai vos sanctuaires, et je ne flairerai pas l’odeur agréable de vos parfums,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'et je désolerai le pays, et vos ennemis qui y habiteront en seront étonnés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'et vous, je vous disperserai parmi les nations, et je tirerai l’épée après vous, et votre pays sera mis en désolation, et vos villes seront un désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Alors le pays jouira de ses sabbats tous les jours de sa désolation: quand vous, vous serez dans le pays de vos ennemis, alors le pays se reposera, et jouira de ses sabbats.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Tous les jours qu’il sera désolé, il se reposera, parce qu’il ne s’était pas reposé dans vos sabbats pendant que vous y habitiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Et quant à ceux qui demeureront de reste d’entre vous, je ferai venir la lâcheté dans leur cœur, dans les pays de leurs ennemis, et le bruit d’une feuille emportée [par le vent] les poursuivra, et ils fuiront comme on fuit l’épée, et tomberont sans que personne les poursuive;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'et ils trébucheront l’un par-dessus l’autre comme devant l’épée, sans que personne les poursuive; et vous ne pourrez pas tenir devant vos ennemis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'et vous périrez parmi les nations, et le pays de vos ennemis vous dévorera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Et ceux qui demeureront de reste d’entre vous, se consumeront dans leur iniquité, dans les pays de vos ennemis; et ils se consumeront, dans les iniquités de leurs pères, avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Et ils confesseront leur iniquité et l’iniquité de leurs pères, selon leurs infidélités par lesquelles ils ont été infidèles envers moi, et aussi comment ils ont marché en opposition avec moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'en sorte que moi aussi, j’ai marché en opposition avec eux, et que je les ai amenés dans le pays de leurs ennemis. Si alors leur cœur incirconcis s’humilie et qu’alors ils acceptent la punition de leur iniquité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'je me souviendrai de mon alliance avec Jacob, et aussi de mon alliance avec Isaac, et je me souviendrai aussi de mon alliance avec Abraham, et je me souviendrai de la terre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'la terre aura été abandonnée par eux, et elle aura joui de ses sabbats, dans sa désolation, eux n’y étant plus; et ils accepteront la punition de leur iniquité, parce que..., oui, parce qu’ils ont méprisé mes ordonnances, et que leurs âmes ont eu en horreur mes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Même alors, quand ils seront dans le pays de leurs ennemis, je ne les mépriserai pas et je ne les aurai pas en horreur pour en finir avec eux, pour rompre mon alliance avec eux; car moi, je suis l’ Éternel, leur Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'et je me souviendrai en leur faveur de l’alliance faite avec leurs ancêtres, lesquels j’ai fait sortir du pays d’Égypte, sous les yeux des nations, pour être leur Dieu. Moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Ce sont là les statuts, et les ordonnances, et les lois que l’ Éternel établit entre lui et les fils d’Israël, sur la montagne de Sinaï, par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Parle aux fils d’Israël, et dis-leur: Si quelqu’un a mis à part quoi que ce soit par un vœu, les personnes seront à l’ Éternel selon ton estimation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Et ton estimation d’un mâle depuis l’âge de 20 ans jusqu’à l’âge de 60 ans, ton estimation sera de 50 sicles d’argent, selon le sicle du sanctuaire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'et si c’est une femme, ton estimation sera de 30 sicles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Et si c’est un mâle depuis l’âge de cinq ans jusqu’à l’âge de 20 ans, ton estimation sera de 20 sicles, et pour une femme, de dix sicles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'et si c’est un mâle depuis l’âge d’un mois jusqu’à l’âge de cinq ans, ton estimation sera de cinq sicles d’argent, et ton estimation d’une fille sera de trois sicles d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Et si c’est un mâle de l’âge de 60 ans et au-dessus, ton estimation sera de 15 sicles, et pour une femme, de dix sicles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Et s’il est plus pauvre que ton estimation, on le fera se tenir devant le sacrificateur, et le sacrificateur en fera l’estimation: le sacrificateur en fera l’estimation à raison de ce que peut atteindre la main de celui qui a fait le vœu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Et si c’est une des bêtes qu’on présente en offrande à l’ Éternel, tout ce qu’on donnera à l’ Éternel sera saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'On ne la changera pas, et on ne la remplacera pas par une autre, une bonne par une mauvaise, ou une mauvaise par une bonne; et si l’on remplace, en quelque manière que ce soit, une bête par une autre, celle-ci et celle qui la remplacera seront saintes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Et si c’est quelque bête impure qu’on ne peut présenter en offrande à l’ Éternel, on placera la bête devant le sacrificateur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'et le sacrificateur en fera l’estimation, selon qu’elle sera bonne ou mauvaise; il en sera selon ton estimation, sacrificateur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Et si on veut la racheter, alors on ajoutera un cinquième à ton estimation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Et quand quelqu’un sanctifiera sa maison pour qu’elle soit sainte, [consacrée] à l’ Éternel, le sacrificateur en fera l’estimation, selon qu’elle sera bonne ou mauvaise; on s’en tiendra à l’estimation que le sacrificateur en fera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Et si celui qui l’a sanctifiée rachète sa maison, il ajoutera le cinquième de l’argent de ton estimation par-dessus, et elle lui appartiendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Et si quelqu’un sanctifie à l’ Éternel une partie du champ de sa possession, ton estimation sera à raison de ce qu’on peut y semer: le khomer de semence d’orge à 50 sicles d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'S’il sanctifie son champ dès l’année du Jubilé, on s’en tiendra à ton estimation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Et si c’est après le Jubilé qu’il sanctifie son champ, le sacrificateur lui comptera l’argent à raison des années qui restent jusqu’à l’année du Jubilé, et il sera fait une réduction sur ton estimation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Et si celui qui a sanctifié le champ veut le racheter, il ajoutera le cinquième de l’argent de ton estimation par-dessus, et il lui restera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Et s’il ne rachète pas le champ ou qu’il vende le champ à un autre homme, il ne pourra plus être racheté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Et le champ, en étant libéré au Jubilé, sera saint, [consacré] à l’ Éternel, comme un champ voué; la possession en sera au sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Et s’il sanctifie à l’ Éternel un champ qu’il ait acheté, qui ne soit pas des champs de sa possession,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'le sacrificateur lui comptera le montant de ton estimation jusqu’à l’année du Jubilé, et il donnera, ce jour-là, le montant de ton estimation, comme une chose sainte [consacrée] à l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'dans l’année du Jubilé, le champ retournera à celui de qui il l’avait acheté et à qui appartenait la possession de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Et toute estimation que tu auras faite sera selon le sicle du sanctuaire: le sicle sera de 20 guéras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Seulement, le premier-né d’entre les bêtes, qui est offert comme prémices à l’ Éternel, nul ne pourra le sanctifier: si c’est un bœuf ou un agneau, il est à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Et s’il est des bêtes impures, on le rachètera selon ton estimation, et on ajoutera un cinquième par-dessus; et si on ne le rachète pas, il sera vendu selon ton estimation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Seulement, aucune chose vouée que quelqu’un aura vouée à l’ Éternel, de tout ce qu’il a, soit homme, ou bête, ou champ de sa possession, ne se vendra ni ne se rachètera: toute chose vouée sera très sainte, [consacrée] à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Quiconque d’entre les hommes est voué [à Dieu] ne pourra être racheté: il sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Et toute dîme de la terre, de la semence de la terre, du fruit des arbres, est à l’ Éternel: c’est une chose sainte [consacrée] à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Et si quelqu’un veut racheter quelque chose de sa dîme, il y ajoutera un cinquième par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Quant à toute dîme du gros et du menu bétail, de tout ce qui passe sous la verge, la dîme sera sainte, [consacrée] à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'On ne distinguera pas entre le bon et le mauvais, et on ne le changera pas; et si on le change, la bête changée et celle qui la remplace seront saintes, elles ne seront pas rachetées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Ce sont là les commandements que l’ Éternel commanda à Moïse pour les fils d’Israël, sur la montagne de Sinaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Et l’ Éternel parla à Moïse, au désert de Sinaï, dans la tente d’assignation, le premier [jour] du second mois de la seconde année après leur sortie du pays d’Égypte, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Relevez la somme de toute l’assemblée des fils d’Israël, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, tous les mâles, par tête:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'depuis l’âge de 20 ans et au-dessus, tous ceux d’Israël qui sont propres au service militaire, vous les compterez selon leurs armées, toi et Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Et, avec vous, il y aura un homme par tribu, un homme chef de sa maison de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Et ce sont ici les noms des hommes qui se tiendront avec vous: pour Ruben, Élitsur, fils de Shedéur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'pour Siméon, Shelumiel, fils de Tsurishaddaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'pour Juda, Nakhshon, fils d’Amminadab;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'pour Issacar, Nethaneël, fils de Tsuar;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'pour Zabulon, Éliab, fils de Hélon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'pour les fils de Joseph, pour Éphraïm, Élishama, fils d’Ammihud; pour Manassé, Gameliel, fils de Pedahtsur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'pour Benjamin, Abidan, fils de Guidhoni;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'pour Dan, Akhiézer, fils d’Ammishaddaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'pour Aser, Paghiel, fils d’Ocran;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'pour Gad, Éliasaph, fils de Dehuel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'pour Nephthali, Akhira, fils d’Énan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Ce sont là ceux qui furent les principaux de l’assemblée, les princes des tribus de leurs pères, les chefs des milliers d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Et Moïse et Aaron prirent ces hommes-là, qui avaient été désignés par leurs noms,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'et ils réunirent toute l’assemblée, le premier [jour] du second mois; et chacun déclara sa filiation, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, par tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Comme l’ Éternel l’avait commandé à Moïse, ainsi il les dénombra dans le désert de Sinaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Et les fils de Ruben, premier-né d’Israël, leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, par tête, tous les mâles, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'ceux qui furent dénombrés de la tribu de Ruben furent 46 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Des fils de Siméon: leurs générations, selon leurs familles, selon leurs maisons de pères, ceux qui furent dénombrés suivant le nombre des noms, par tête, tous les mâles, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'ceux qui furent dénombrés de la tribu de Siméon furent 59 300.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Des fils de Gad: leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'ceux qui furent dénombrés de la tribu de Gad furent 45 650.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Des fils de Juda: leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'ceux qui furent dénombrés de la tribu de Juda furent 74 600.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Des fils d’Issacar: leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'ceux qui furent dénombrés de la tribu d’Issacar furent 54 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Des fils de Zabulon: leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'ceux qui furent dénombrés de la tribu de Zabulon furent 57 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Des fils de Joseph, des fils d’Éphraïm: leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'ceux qui furent dénombrés de la tribu d’Éphraïm furent 40 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Des fils de Manassé: leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'ceux qui furent dénombrés de la tribu de Manassé furent 32 200.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Des fils de Benjamin: leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'ceux qui furent dénombrés de la tribu de Benjamin furent 35 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Des fils de Dan: leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'ceux qui furent dénombrés de la tribu de Dan furent 62 700.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Des fils d’Aser: leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'ceux qui furent dénombrés de la tribu d’Aser furent 41 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Des fils de Nephthali: leurs générations, selon leurs familles, selon leurs maisons de pères, suivant le nombre des noms, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'ceux qui furent dénombrés de la tribu de Nephthali furent 53 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Ce sont là les dénombrés que Moïse et Aaron et les douze hommes, princes d’Israël, dénombrèrent: il y avait un homme pour chaque maison de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Et tous les dénombrés des fils d’Israël, selon leurs maisons de pères, depuis l’âge de 20 ans et au-dessus, tous ceux qui étaient propres au service militaire en Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'tous les dénombrés, furent 603 550.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Mais les Lévites, selon la tribu de leurs pères, ne furent pas dénombrés parmi eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Car l’ Éternel avait parlé à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Seulement, tu ne dénombreras pas la tribu de Lévi et tu n’en relèveras pas la somme parmi les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Et toi, tu préposeras les Lévites sur le tabernacle du témoignage, et sur tous ses ustensiles, et sur tout ce qui lui appartient: ce seront eux qui porteront le tabernacle et tous ses ustensiles; ils en feront le service, et camperont autour du tabernacle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'et quand le tabernacle partira, les Lévites le démonteront, et quand le tabernacle campera, les Lévites le dresseront; et l’étranger qui en approchera sera mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Et les fils d’Israël camperont chacun dans son camp, et chacun près de sa bannière, selon leurs armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Et les Lévites camperont autour du tabernacle du témoignage, afin qu’il n’y ait point de colère sur l’assemblée des fils d’Israël; et les Lévites auront la garde du tabernacle du témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Et les fils d’Israël firent selon tout ce que l’ Éternel avait commandé à Moïse; ils firent ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, '*Et l’ Éternel parla à Moïse et à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Les fils d’Israël camperont chacun près de sa bannière, sous les enseignes de leurs maisons de pères; ils camperont autour de la tente d’assignation, à distance, vis-à-vis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, '[Voici] ceux qui camperont à l’orient, vers le levant, [sous] la bannière du camp de Juda, selon leurs armées: le prince des fils de Juda, Nakhshon, fils d’Amminadab,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'et son armée; et ses dénombrés, 74 600.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, '– Et ceux qui camperont près de lui, sont la tribu d’Issacar: le prince des fils d’Issacar, Nethaneël, fils de Tsuar,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'et son armée; et ses dénombrés, 54 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, '– [Avec eux] sera la tribu de Zabulon: le prince des fils de Zabulon, Éliab, fils de Hélon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'et son armée; et ses dénombrés, 57 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, '– Tous les dénombrés du camp de Juda, 186 400, selon leurs armées; ils partiront les premiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'La bannière du camp de Ruben, selon ses armées, sera vers le midi: le prince des fils de Ruben, Élitsur, fils de Shedéur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'et son armée; et ses dénombrés, 46 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, '– Et ceux qui camperont près de lui, sont la tribu de Siméon: le prince des fils de Siméon, Shelumiel, fils de Tsurishaddaï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'et son armée; et ses dénombrés, 59 300.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, '– Et [avec eux] sera la tribu de Gad: le prince des fils de Gad, Éliasaph, fils de Rehuel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'et son armée; et ses dénombrés, 45 650.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, '– Tous les dénombrés du camp de Ruben, 151 450, selon leurs armées; et ils partiront les seconds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Et la tente d’assignation partira, le camp des Lévites étant au milieu des camps; comme ils auront campé, ainsi ils partiront, chacun à sa place, selon leurs bannières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'La bannière du camp d’Éphraïm, selon ses armées, sera vers l’occident: le prince des fils d’Éphraïm, Élishama, fils d’Ammihud,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'et son armée; et ses dénombrés, 40 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, '– Et près de lui la tribu de Manassé: le prince des fils de Manassé, Gameliel, fils de Pedahtsur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'et son armée; et ses dénombrés, 32 200.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, '– Et [avec eux] sera la tribu de Benjamin: le prince des fils de Benjamin, Abidan, fils de Guidhoni,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'et son armée; et ses dénombrés, 35 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, '– Tous les dénombrés du camp d’Éphraïm, 108 100, selon leurs armées; et ils partiront les troisièmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'La bannière du camp de Dan, selon ses armées, sera vers le nord: le prince des fils de Dan, Akhiézer, fils d’Ammishaddaï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'et son armée; et ses dénombrés, 62 700.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, '– Et ceux qui camperont près de lui, sont la tribu d’Aser: le prince des fils d’Aser, Paghiel, fils d’Ocran,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'et son armée; et ses dénombrés, 41 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, '– Et [avec eux] sera la tribu de Nephthali: le prince des fils de Nephthali, Akhira, fils d’Énan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'et son armée; et ses dénombrés, 53 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, '– Tous les dénombrés du camp de Dan, 157 600; ils partiront les derniers, selon leurs bannières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Ce sont là les dénombrés des fils d’Israël, selon leurs maisons de pères. Tous les dénombrés des camps, selon leurs armées, furent 603 550.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Mais les Lévites ne furent pas dénombrés parmi les fils d’Israël, ainsi que l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Et les fils d’Israël firent selon tout ce que l’ Éternel avait commandé à Moïse: ainsi ils campèrent selon leurs bannières, et ainsi ils partirent, chacun selon leurs familles, selon leurs maisons de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, '*Et ce sont ici les générations d’Aaron et de Moïse, au jour où l’ Éternel parla à Moïse sur la montagne de Sinaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Et ce sont ici les noms des fils d’Aaron: le premier-né, Nadab, et Abihu, Éléazar et Ithamar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Ce sont là les noms des fils d’Aaron, les sacrificateurs oints qui furent consacrés pour exercer la sacrificature.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Et Nadab et Abihu moururent devant l’ Éternel, lorsqu’ils présentèrent un feu étranger devant l’ Éternel dans le désert de Sinaï, et ils n’eurent point de fils; et Éléazar et Ithamar exercèrent la sacrificature en présence d’Aaron, leur père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Fais approcher la tribu de Lévi, et fais-la se tenir devant Aaron, le sacrificateur, afin qu’ils le servent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'et qu’ils accomplissent ce qui appartient à son service, et au service de toute l’assemblée, devant la tente d’assignation, pour faire le service du tabernacle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'et ils auront la charge de tous les ustensiles de la tente d’assignation, et de ce qui se rapporte au service des fils d’Israël, pour faire le service du tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Et tu donneras les Lévites à Aaron et à ses fils; ils lui sont absolument donnés d’entre les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Et tu établiras Aaron et ses fils, afin qu’ils accomplissent les devoirs de leur sacrificature; et l’étranger qui approchera sera mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Et moi, voici, j’ai pris les Lévites du milieu des fils d’Israël, à la place de tout premier-né d’entre les fils d’Israël qui ouvre la matrice; et les Lévites seront à moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'car tout premier-né est à moi. Le jour où j’ai frappé tout premier-né dans le pays d’Égypte, je me suis sanctifié tout premier-né en Israël, depuis l’homme jusqu’à la bête: ils seront à moi. Je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Et l’ Éternel parla à Moïse, dans le désert de Sinaï, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Dénombre les fils de Lévi selon leurs maisons de pères, selon leurs familles: tu dénombreras tous les mâles depuis l’âge d’un mois et au-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Et Moïse les dénombra selon le commandement de l’ Éternel, comme il lui avait été commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Ce sont ici les fils de Lévi, selon leurs noms: Guershon, et Kehath, et Merari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Et ce sont ici les noms des fils de Guershon, selon leurs familles: Libni et Shimhi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Et les fils de Kehath, selon leurs familles: Amram, et Jitsehar, Hébron, et Uziel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Et les fils de Merari, selon leurs familles: Makhli et Mushi. Ce sont là les familles de Lévi, selon leurs maisons de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'De Guershon, la famille des Libnites et la famille des Shimhites; ce sont là les familles des Guershonites:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'ceux d’entre eux qui furent dénombrés, en comptant tous les mâles depuis l’âge d’un mois et au-dessus, ceux qui furent dénombrés furent 7 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Les familles des Guershonites campèrent derrière le tabernacle, vers l’occident;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'et le prince de la maison de père des Guershonites était Éliasaph, fils de Laël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Et la charge des fils de Guershon, à la tente d’assignation, était le tabernacle et la tente, sa couverture, et le rideau de l’entrée de la tente d’assignation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'et les tentures du parvis, et le rideau de l’entrée du parvis qui entoure le tabernacle et l’autel, et ses cordages pour tout son service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Et de Kehath, la famille des Amramites, et la famille des Jitseharites, et la famille des Hébronites, et la famille des Uziélites; ce sont là les familles des Kehathites:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'en comptant tous les mâles, depuis l’âge d’un mois et au-dessus, il y en eut 8 600, qui avaient la charge du lieu saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Les familles des fils de Kehath campèrent à côté du tabernacle, vers le midi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'et le prince de la maison de père des familles des Kehathites était Élitsaphan, fils d’Uziel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Et leur charge était l’arche, et la table, et le chandelier, et les autels, et les ustensiles du lieu saint, avec lesquels on fait le service, et le rideau et tout le service qui s’y rattachait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, '– Et le prince des princes des Lévites était Éléazar, fils d’Aaron, le sacrificateur; il était établi sur ceux qui avaient la charge du lieu saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'De Merari, la famille des Makhlites et la famille des Mushites; ce sont là les familles de Merari:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'et ceux d’entre eux qui furent dénombrés, en comptant tous les mâles depuis l’âge d’un mois et au-dessus, furent 6 200.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Et le prince de la maison de père des familles de Merari était Tsuriel, fils d’Abikhaïl. Ils campèrent du côté du tabernacle, vers le nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Et la surveillance des ais du tabernacle, et de ses traverses, et de ses piliers, et de ses bases, et de tous ses ustensiles, et tout le service qui s’y rattachait,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'et les piliers du parvis tout autour, et leurs bases, et leurs pieux, et leurs cordages, furent confiés aux fils de Merari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Et ceux qui campèrent devant le tabernacle, vers l’orient, devant la tente d’assignation, vers le levant, furent Moïse et Aaron et ses fils, veillant au service du sanctuaire pour ce qui était confié aux fils d’Israël. – Et l’étranger qui approchera sera mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Tous les Lévites dénombrés, que Moïse et Aaron dénombrèrent selon leurs familles, selon le commandement de l’ Éternel, tous les mâles, depuis l’âge d’un mois et au-dessus, furent 22 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Et l’ Éternel dit à Moïse: Dénombre tous les premiers-nés mâles des fils d’Israël, depuis l’âge d’un mois et au-dessus, et relève le nombre de leurs noms.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Et tu prendras les Lévites pour moi (je suis l’ Éternel), à la place de tous les premiers-nés parmi les fils d’Israël, et le bétail des Lévites à la place de tous les premiers-nés parmi le bétail des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Et Moïse fit le dénombrement de tous les premiers-nés parmi les fils d’Israël, comme l’ Éternel lui avait commandé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'et tous les premiers-nés mâles, selon le nombre des noms, depuis l’âge d’un mois et au-dessus, selon leur dénombrement, furent 22 273.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Prends les Lévites, à la place de tous les premiers-nés parmi les fils d’Israël, et le bétail des Lévites, à la place de leur bétail; et les Lévites seront à moi. Je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Et quant à ceux qu’il faut racheter, les 273 parmi les premiers-nés des fils d’Israël, qui sont de plus que les Lévites,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'tu prendras cinq sicles par tête; tu les prendras selon le sicle du sanctuaire, le sicle à 20 guéras,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'et tu donneras à Aaron et à ses fils l’argent de ceux qui sont rachetés, qui sont de plus que les [Lévites].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Et Moïse prit l’argent du rachat, de ceux qui étaient de plus que le nombre de ceux qui avaient été rachetés par les Lévites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'il prit l’argent de la part des premiers-nés des fils d’Israël, 1 365 [sicles], selon le sicle du sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Et Moïse donna l’argent des rachetés à Aaron et à ses fils, selon le commandement de l’ Éternel, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, '*Et l’ Éternel parla à Moïse et à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Relève la somme des fils de Kehath d’entre les fils de Lévi, selon leurs familles, selon leurs maisons de pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'depuis l’âge de 30 ans et au-dessus, jusqu’à l’âge de 50 ans, tous ceux qui entrent en service pour faire l’œuvre dans la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'C’est ici le service des fils de Kehath, dans la tente d’assignation: c’est une chose très sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, '– Et lorsque le camp partira, Aaron et ses fils entreront, et ils démonteront le voile qui sert de rideau, et en couvriront l’arche du témoignage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'et ils mettront dessus une couverture de peaux de taissons, et étendront par-dessus un drap tout de bleu; et ils y placeront les barres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Et ils étendront un drap de bleu sur la table des pains de proposition, et mettront sur elle les plats, et les coupes, et les vases, et les gobelets de libation; et le pain continuel sera sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Et ils étendront sur ces choses un drap d’écarlate, et ils le couvriront d’une couverture de peaux de taissons, et ils y placeront les barres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Et ils prendront un drap de bleu, et en couvriront le chandelier du luminaire, et ses lampes, et ses mouchettes, et ses vases à cendre, et tous ses vases à huile, dont on fait usage pour son service;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'et ils le mettront, avec tous ses ustensiles, dans une couverture de peaux de taissons, et le mettront sur une perche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Et sur l’autel d’or ils étendront un drap de bleu, et le couvriront d’une couverture de peaux de taissons, et y placeront les barres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Et ils prendront tous les ustensiles du service avec lesquels on sert dans le lieu saint, et ils les mettront dans un drap de bleu, et les couvriront d’une couverture de peaux de taissons, et les mettront sur une perche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Et ils ôteront les cendres de l’autel, et ils étendront sur lui un drap de pourpre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Et ils mettront dessus tous ses ustensiles dont on fait usage pour son service: les brasiers, les fourchettes, et les pelles, et les bassins, tous les ustensiles de l’autel; et ils étendront dessus une couverture de peaux de taissons, et y placeront les barres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, '– Et lorsque Aaron et ses fils auront achevé de couvrir le lieu saint et tous les ustensiles du lieu saint, lors du départ du camp, après cela les fils de Kehath viendront pour les porter, afin qu’ils ne touchent pas les choses saintes, et ne meurent pas. C’est là ce que les fils de Kehath porteront de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Et Éléazar, fils d’Aaron, le sacrificateur, aura la surveillance de l’huile du luminaire, et de l’encens des drogues odoriférantes, et de l’offrande de gâteau continuelle, et de l’huile de l’onction, la surveillance de tout le tabernacle et de tout ce qui y est, du lieu saint et de ses ustensiles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Et l’ Éternel parla à Moïse et à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Ne faites pas que la tribu des familles des Kehathites soit retranchée d’entre les Lévites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'et faites ceci pour eux, afin qu’ils vivent et ne meurent pas, en s’approchant du lieu très saint: Aaron et ses fils viendront, et les placeront chacun à son service et à son fardeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Et ils n’entreront pas pour voir, quand on enveloppera les choses saintes, afin qu’ils ne meurent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Relève aussi la somme des fils de Guershon, selon leurs maisons de pères, selon leurs familles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'tu les dénombreras depuis l’âge de 30 ans et au-dessus, jusqu’à l’âge de 50 ans: tous ceux qui entrent en service pour s’employer au service, à la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'C’est ici le service des familles des Guershonites, pour servir et pour porter:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'ils porteront les tapis du tabernacle et la tente d’assignation, sa couverture, et la couverture de peaux de taissons qui est sur elle par-dessus, et le rideau de l’entrée de la tente d’assignation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'et les tentures du parvis, et le rideau de l’entrée de la porte du parvis qui entoure le tabernacle et l’autel, et leurs cordages, et tous les ustensiles de leur service; tout ce qui doit être fait avec eux constituera leur service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Tout le service des fils des Guershonites, dans tout ce qu’ils portent et dans tout leur service, sera selon les ordres d’Aaron et de ses fils; et vous leur donnerez en charge tout ce qu’ils doivent porter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'C’est là le service des familles des fils des Guershonites à la tente d’assignation; et leur charge sera sous la main d’Ithamar, fils d’Aaron, le sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Quant aux fils de Merari, tu les dénombreras selon leurs familles, selon leurs maisons de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Tu les dénombreras depuis l’âge de 30 ans et au-dessus, jusqu’à l’âge de 50 ans, tous ceux qui entrent en service pour s’employer au service de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Et c’est ici la charge de ce qu’ils auront à porter, selon tout leur service à la tente d’assignation: les ais du tabernacle, et ses traverses, et ses piliers, et ses bases,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'et les piliers du parvis tout autour, et leurs bases, et leurs pieux, et leurs cordages, tous leurs ustensiles, selon tout leur service; et vous leur compterez, [en les désignant] par nom, les objets qu’ils auront charge de porter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'C’est là le service des familles des fils de Merari, pour tout leur service à la tente d’assignation, sous la main d’Ithamar, fils d’Aaron, le sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Et Moïse et Aaron, et les princes de l’assemblée, dénombrèrent les fils des Kehathites, selon leurs familles et selon leurs maisons de pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'depuis l’âge de 30 ans et au-dessus, jusqu’à l’âge de 50 ans, tous ceux qui entraient en service pour servir dans la tente d’assignation:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'leurs dénombrés, selon leurs familles, furent 2 750.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Ce sont là les dénombrés des familles des Kehathites, tous ceux qui servaient dans la tente d’assignation, que Moïse et Aaron dénombrèrent selon le commandement de l’ Éternel par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Et ceux qui furent dénombrés d’entre les fils de Guershon, selon leurs familles, et selon leurs maisons de pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'depuis l’âge de 30 ans et au-dessus, jusqu’à l’âge de 50 ans, tous ceux qui entraient en service pour servir à la tente d’assignation:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'leurs dénombrés, selon leurs familles, selon leurs maisons de pères, furent 2 630.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Ce sont là les dénombrés des familles des fils de Guershon, tous ceux qui servaient à la tente d’assignation, que Moïse et Aaron dénombrèrent selon le commandement de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Et ceux qui furent dénombrés d’entre les familles des fils de Merari, selon leurs familles, selon leurs maisons de pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'depuis l’âge de 30 ans et au-dessus, jusqu’à l’âge de 50 ans, tous ceux qui entraient en service pour servir à la tente d’assignation:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'leurs dénombrés, selon leurs familles, furent 3 200.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Ce sont là les dénombrés des familles des fils de Merari, que Moïse et Aaron dénombrèrent selon le commandement de l’ Éternel par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Tous ceux qui furent dénombrés, que Moïse et Aaron et les princes d’Israël dénombrèrent, savoir les Lévites, selon leurs familles et selon leurs maisons de pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'depuis l’âge de 30 ans et au-dessus, jusqu’à l’âge de 50 ans, tous ceux qui entraient pour s’employer à l’œuvre du service et à l’œuvre du portage, à la tente d’assignation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, '– les dénombrés, furent 8 580.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'On les dénombra selon le commandement de l’ Éternel par Moïse, chacun selon son service et selon son fardeau; et ils furent dénombrés par lui, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Commande aux fils d’Israël qu’ils mettent hors du camp tout lépreux, et quiconque a un flux, et quiconque est impur pour un mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Tant homme que femme, vous les mettrez dehors; vous les mettrez hors du camp, afin qu’ils ne rendent pas impurs leurs camps, au milieu desquels j’habite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Et les fils d’Israël firent ainsi, et les mirent hors du camp; comme l’ Éternel avait dit à Moïse, ainsi firent les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Parle aux fils d’Israël: Si un homme ou une femme a commis quelqu’un de tous les péchés de l’homme, en commettant une infidélité envers l’ Éternel, et que cette âme-là se soit rendue coupable,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'ils confesseront leur péché qu’ils ont commis; et le coupable restituera en principal ce en quoi il s’est rendu coupable, et il y ajoutera un cinquième, et le donnera à celui envers qui il s’est rendu coupable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Et si l’homme n’a pas de proche parent à qui restituer la chose due, alors la chose due, restituée à l’ Éternel, sera au sacrificateur, outre le bélier de propitiation avec lequel on fera propitiation pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Et toute offrande élevée de toutes les choses saintes des fils d’Israël qu’ils présenteront au sacrificateur, sera à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Et les choses saintes de chacun seront à lui; ce que chacun donnera au sacrificateur sera à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Parle aux fils d’Israël, et dis-leur: Si la femme de quelqu’un se détourne et lui devient infidèle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'et qu’un homme couche avec elle, ayant commerce avec elle, et que cela soit caché aux yeux de son mari, et qu’elle se soit rendue impure en secret, et qu’il n’y ait pas de témoin contre elle, et qu’elle n’ait pas été surprise;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, '– et que l’esprit de jalousie vienne sur lui et qu’il soit jaloux de sa femme, et qu’elle se soit rendue impure; ou si l’esprit de jalousie vient sur lui et qu’il soit jaloux de sa femme, et qu’elle ne se soit pas rendue impure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, '– alors l’homme amènera sa femme au sacrificateur, et il apportera pour elle son offrande, le dixième d’un épha de farine d’orge; il ne versera pas d’huile dessus et n’y mettra pas d’encens, car c’est une offrande de gâteau de jalousie, un gâteau de mémorial, qui met en mémoire l’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Et le sacrificateur la fera approcher, et la fera se tenir devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'et le sacrificateur prendra de l’eau sainte dans un vase de terre, et le sacrificateur prendra de la poussière qui sera sur le sol du tabernacle, et la mettra dans l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Et le sacrificateur fera tenir la femme debout devant l’ Éternel, et découvrira la tête de la femme et mettra sur les paumes de ses mains le gâteau de mémorial; c’est un gâteau de jalousie; et dans la main du sacrificateur seront les eaux amères qui apportent la malédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Et le sacrificateur adjurera la femme, et lui dira: Si un homme n’a pas couché avec toi, et si tu ne t’es pas détournée et rendue impure en étant avec un autre que ton mari, sois quitte de [l’effet de] ces eaux amères qui apportent la malédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mais si tu t’es détournée en étant avec un autre que ton mari, et que tu te sois rendue impure, et qu’un autre que ton mari ait couché avec toi:...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'alors le sacrificateur adjurera la femme avec un serment d’exécration, et le sacrificateur dira à la femme: Que l’ Éternel fasse de toi une exécration et un serment, au milieu de ton peuple, l’ Éternel faisant dessécher ta hanche et enfler ton ventre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'et ces eaux qui apportent la malédiction entreront dans tes entrailles pour te faire enfler le ventre et pour faire dessécher ta hanche. Et la femme dira: Amen! amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, '– Et le sacrificateur écrira ces exécrations dans un livre, et les effacera avec les eaux amères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Et il fera boire à la femme les eaux amères qui apportent la malédiction, et les eaux qui apportent la malédiction entreront en elle, pour être amères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Et le sacrificateur prendra, de la main de la femme, le gâteau de jalousie, et tournoiera le gâteau devant l’ Éternel, et le présentera à l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Et le sacrificateur prendra de l’offrande de gâteau une poignée pour mémorial, et la fera fumer sur l’autel; et après, il fera boire les eaux à la femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Quand il lui aura fait boire les eaux, il arrivera que, si elle s’est rendue impure et qu’elle ait été infidèle à son mari, les eaux qui apportent la malédiction entreront en elle pour être amères, et son ventre enflera, et sa hanche se desséchera: et la femme sera une exécration au milieu de son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Et si la femme ne s’est pas rendue impure, mais qu’elle soit pure, alors elle sera quitte, et elle aura des enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Telle est la loi de jalousie, quand une femme se sera détournée pour être avec un autre que son mari et se sera rendue impure,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'ou si l’esprit de jalousie est venu sur un homme et qu’il soit jaloux de sa femme: il fera tenir la femme debout devant l’ Éternel, et le sacrificateur lui appliquera toute cette loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'l’homme sera exempt d’iniquité, et cette femme portera son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Parle aux fils d’Israël, et dis-leur: Si un homme ou une femme se consacre en faisant vœu de nazaréat, pour se séparer [afin d’être] à l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'il s’abstiendra de vin et de boisson forte, il ne boira ni vinaigre de vin, ni vinaigre de boisson forte, et il ne boira d’aucune liqueur de raisins, et ne mangera point de raisins, frais ou secs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Pendant tous les jours de son nazaréat, il ne mangera rien de ce qui est fait de la vigne, depuis les pépins jusqu’à la peau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Pendant tous les jours du vœu de son nazaréat, le rasoir ne passera pas sur sa tête; jusqu’à l’accomplissement des jours pour lesquels il s’est séparé [pour être] à l’ Éternel, il sera saint; il laissera croître les boucles des cheveux de sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Pendant tous les jours de sa consécration à l’ Éternel, il ne s’approchera d’aucune personne morte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Il ne se rendra pas impur pour son père, ni pour sa mère, [ni] pour son frère, ni pour sa sœur, quand ils mourront; car le nazaréat de son Dieu est sur sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Pendant tous les jours de son nazaréat, il est consacré à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Et si quelqu’un vient à mourir subitement auprès de lui, d’une manière imprévue, et qu’il ait rendu impure la tête de son nazaréat, il rasera sa tête au jour de sa purification; il la rasera le septième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Et le huitième jour il apportera au sacrificateur deux tourterelles ou deux jeunes pigeons, à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Et le sacrificateur offrira l’un en sacrifice pour le péché, et l’autre en holocauste, et fera propitiation pour lui de ce qu’il a péché à l’occasion du mort; et il sanctifiera sa tête ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Et il consacrera à l’ Éternel les jours de son nazaréat, et il amènera un agneau, âgé d’un an, en sacrifice pour le délit; et les premiers jours seront comptés pour rien, car il a rendu impur son nazaréat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Et c’est ici la loi du nazaréen: au jour où les jours de son nazaréat seront accomplis, on le fera venir à l’entrée de la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'et il présentera son offrande à l’ Éternel, un agneau mâle, âgé d’un an, sans défaut, pour holocauste, et un agneau femelle, âgé d’un an, sans défaut, en sacrifice pour le péché, et un bélier sans défaut, pour sacrifice de prospérités;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'et une corbeille de pains sans levain, des gâteaux de fleur de farine pétris à l’huile, et des galettes sans levain ointes d’huile, et leur offrande de gâteau et leurs libations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Et le sacrificateur les présentera devant l’ Éternel, et il offrira son sacrifice pour le péché, et son holocauste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'et il offrira le bélier en sacrifice de prospérités à l’ Éternel, avec la corbeille des pains sans levain; et le sacrificateur offrira son offrande de gâteau et sa libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Et le nazaréen rasera, à l’entrée de la tente d’assignation, la tête de son nazaréat, et il prendra les cheveux de la tête de son nazaréat et les mettra sur le feu qui est sous le sacrifice de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Et le sacrificateur prendra l’épaule cuite du bélier, et un gâteau sans levain de la corbeille, et une galette sans levain, et il les mettra sur les paumes des mains du nazaréen, après qu’il aura fait raser [les cheveux de] son nazaréat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Et le sacrificateur les tournoiera en offrande tournoyée devant l’ Éternel: c’est une chose sainte qui appartient au sacrificateur, avec la poitrine tournoyée, et avec l’épaule élevée. Et après cela le nazaréen boira du vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Telle est la loi du nazaréen qui se sera voué, [telle] son offrande à l’ Éternel pour son nazaréat, outre ce que sa main aura pu atteindre; selon son vœu qu’il aura fait, ainsi il fera, suivant la loi de son nazaréat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Parle à Aaron et à ses fils, disant: Vous bénirez ainsi les fils d’Israël, en leur disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'L’ Éternel te bénisse, et te garde!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'L’ Éternel fasse lever la lumière de sa face sur toi et use de grâce envers toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'L’ Éternel lève sa face sur toi et te donne la paix!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Et ils mettront mon nom sur les fils d’Israël; et moi, je les bénirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, '*Et il arriva, le jour où Moïse eut achevé de dresser le tabernacle, et qu’il l’eut oint et sanctifié avec tous ses ustensiles, et l’autel avec tous ses ustensiles, et qu’il les eut oints et sanctifiés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'que les princes d’Israël, chefs de leurs maisons de pères, princes des tribus, qui avaient été préposés sur ceux qui furent dénombrés, présentèrent [leur offrande].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Ils amenèrent leur offrande devant l’ Éternel: six chariots couverts et douze bœufs, un chariot pour deux princes, et un bœuf pour un [prince]; et ils les présentèrent devant le tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Prends d’eux [ces choses], et elles seront employées au service de la tente d’assignation, et tu les donneras aux Lévites, à chacun en proportion de son service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Et Moïse prit les chariots et les bœufs, et les donna aux Lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Il donna deux chariots et quatre bœufs aux fils de Guershon, en proportion de leur service;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'et il donna quatre chariots et huit bœufs aux fils de Merari, en proportion de leur service, – sous la main d’Ithamar, fils d’Aaron, le sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Et il n’en donna pas aux fils de Kehath, car le service du lieu saint leur appartenait: ils portaient sur l’épaule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Et les princes présentèrent [leur offrande pour] la dédicace de l’autel, le jour où il fut oint: les princes présentèrent leur offrande devant l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Et l’ Éternel dit à Moïse: Ils présenteront, un prince un jour, et un prince l’autre jour, leur offrande pour la dédicace de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Et celui qui présenta son offrande le premier jour, fut Nakhshon, fils d’Amminadab, de la tribu de Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'et son offrande fut: un plat d’argent du poids de 130 [sicles], un bassin d’argent de 70 sicles, selon le sicle du sanctuaire, tous deux pleins de fleur de farine pétrie à l’huile, pour une offrande de gâteau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'une coupe d’or de dix [sicles], pleine d’encens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'un jeune taureau, un bélier, un agneau âgé d’un an, pour l’holocauste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'un bouc, en sacrifice pour le péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'et, pour le sacrifice de prospérités, deux taureaux, cinq béliers, cinq boucs, cinq agneaux âgés d’un an. Telle fut l’offrande de Nakhshon, fils d’Amminadab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Le second jour, Nethaneël, fils de Tsuar, prince d’Issacar, présenta [son offrande].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Il présenta son offrande: un plat d’argent du poids de 130 [sicles], un bassin d’argent de 70 sicles, selon le sicle du sanctuaire, tous deux pleins de fleur de farine pétrie à l’huile, pour une offrande de gâteau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'une coupe d’or de dix [sicles], pleine d’encens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'un jeune taureau, un bélier, un agneau âgé d’un an, pour l’holocauste;');
