INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Le douzième jour, le prince des fils de Nephthali, Akhira, fils d’Énan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Son offrande fut: un plat d’argent du poids de 130 [sicles], un bassin d’argent de 70 sicles, selon le sicle du sanctuaire, tous deux pleins de fleur de farine pétrie à l’huile, pour une offrande de gâteau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'une coupe d’or de dix [sicles], pleine d’encens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'un jeune taureau, un bélier, un agneau âgé d’un an, pour l’holocauste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'un bouc, en sacrifice pour le péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'et, pour le sacrifice de prospérités, deux taureaux, cinq béliers, cinq boucs, cinq agneaux âgés d’un an. Telle fut l’offrande d’Akhira, fils d’Énan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Telle fut, de la part des princes d’Israël, [l’offrande pour] la dédicace de l’autel, au jour où il fut oint: douze plats d’argent, douze bassins d’argent, douze coupes d’or;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'chaque plat d’argent était de 130 [sicles], et chaque bassin de 70: tout l’argent des vases fut de 2 400 [sicles], selon le sicle du sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Douze coupes d’or, pleines d’encens, chacune de dix [sicles], selon le sicle du sanctuaire: tout l’or des coupes, de 120 [sicles].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Tout le bétail pour l’holocauste fut: douze taureaux, douze béliers, douze agneaux âgés d’un an, et leurs offrandes de gâteau; et douze boucs, en sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Et tout le bétail pour le sacrifice de prospérités fut: 24 taureaux, 60 béliers, 60 boucs, 60 agneaux âgés d’un an. Telle fut [l’offrande pour] la dédicace de l’autel, après qu’il fut oint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, '*Et quand Moïse entrait dans la tente d’assignation pour parler avec Lui, il entendait la voix qui lui parlait de dessus le propitiatoire qui était sur l’arche du témoignage, d’entre les deux chérubins; et il Lui parlait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Parle à Aaron et dis-lui: Quand tu allumeras les lampes, les sept lampes éclaireront sur le devant, vis-à-vis du chandelier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Et Aaron fit ainsi; il alluma les lampes [pour éclairer] sur le devant, vis-à-vis du chandelier, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Et le chandelier était fait ainsi: il était d’or battu; depuis son pied jusqu’à ses fleurs, il était [d’or] battu. Selon la forme que l’ Éternel avait montrée à Moïse, ainsi il avait fait le chandelier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Prends les Lévites du milieu des fils d’Israël, et purifie-les.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Et tu leur feras ainsi pour les purifier: tu feras aspersion sur eux de l’eau de purification du péché; et ils feront passer le rasoir sur toute leur chair, et ils laveront leurs vêtements, et se purifieront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Et ils prendront un jeune taureau, et son offrande de gâteau de fleur de farine pétrie à l’huile; et tu prendras un second jeune taureau, pour sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Et tu feras approcher les Lévites devant la tente d’assignation, et tu réuniras toute l’assemblée des fils d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'et tu feras approcher les Lévites devant l’ Éternel, et les fils d’Israël poseront leurs mains sur les Lévites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'et Aaron offrira les Lévites en offrande tournoyée devant l’ Éternel, de la part des fils d’Israël, et ils seront employés au service de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Et les Lévites poseront leurs mains sur la tête des taureaux; et tu offriras l’un en sacrifice pour le péché, et l’autre en holocauste à l’ Éternel, afin de faire propitiation pour les Lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Et tu feras tenir les Lévites devant Aaron et devant ses fils, et tu les offriras en offrande tournoyée à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Et tu sépareras les Lévites du milieu des fils d’Israël, et les Lévites seront à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, '– Après cela les Lévites viendront pour faire le service de la tente d’assignation, et tu les purifieras, et tu les offriras en offrande tournoyée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'car ils me sont entièrement donnés du milieu des fils d’Israël: je les ai pris pour moi à la place de tous ceux qui ouvrent la matrice, de tous les premiers-nés d’entre les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Car tout premier-né parmi les fils d’Israël est à moi, tant les hommes que les bêtes; je me les suis sanctifiés le jour où je frappai tout premier-né dans le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Et j’ai pris les Lévites à la place de tous les premiers-nés parmi les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Et j’ai donné les Lévites en don à Aaron et à ses fils, du milieu des fils d’Israël, pour s’employer au service des fils d’Israël à la tente d’assignation, et pour faire propitiation pour les fils d’Israël, afin qu’il n’y ait pas de plaie au milieu des fils d’Israël quand les fils d’Israël s’approcheraient du lieu saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, '– Et Moïse et Aaron, et toute l’assemblée des fils d’Israël, firent à l’égard des Lévites tout ce que l’ Éternel avait commandé à Moïse touchant les Lévites; les fils d’Israël firent ainsi à leur égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Et les Lévites se purifièrent, et lavèrent leurs vêtements; et Aaron les offrit en offrande tournoyée devant l’ Éternel; et Aaron fit propitiation pour eux, pour les purifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Et après cela, les Lévites vinrent pour faire leur service à la tente d’assignation, devant Aaron et devant ses fils. Comme l’ Éternel avait commandé à Moïse touchant les Lévites, ainsi on fit à leur égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'C’est ici ce qui concerne les Lévites: Depuis l’âge de 25 ans et au-dessus, [le Lévite] entrera en service pour être employé à la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'et depuis l’âge de 50 ans, il se retirera du labeur du service, et ne servira plus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'et il s’emploiera avec ses frères à la tente d’assignation, pour garder ce qui doit être gardé, mais il ne fera pas de service. Tu feras ainsi à l’égard des Lévites touchant leurs charges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, '*Et l’ Éternel parla à Moïse, dans le désert de Sinaï, le premier mois de la seconde année après leur sortie du pays d’Égypte, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Que les fils d’Israël fassent aussi la Pâque au temps fixé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Vous la ferez au temps fixé, le quatorzième jour de ce mois, entre les deux soirs; vous la ferez selon tous ses statuts et selon toutes ses ordonnances.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, '– Et Moïse dit aux fils d’Israël de faire la Pâque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Et ils firent la Pâque, le premier [mois], le quatorzième jour du mois, entre les deux soirs, au désert de Sinaï: selon tout ce que l’ Éternel avait commandé à Moïse, ainsi firent les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Et il y eut des hommes qui étaient impurs à cause du corps mort d’un homme, et qui ne pouvaient pas faire la Pâque ce jour-là; et ils se présentèrent ce jour-là devant Moïse et devant Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Et ces hommes lui dirent: Nous sommes impurs à cause du corps mort d’un homme; pourquoi serions-nous exclus de présenter l’offrande de l’ Éternel au temps fixé, au milieu des fils d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Et Moïse leur dit: Tenez-vous là, et j’entendrai ce que l’ Éternel commandera à votre égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Parle aux fils d’Israël, en disant: Si un homme d’entre vous ou de votre postérité est impur à cause d’un corps mort, ou est en voyage au loin, il fera la Pâque à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Ils la feront le second mois, le quatorzième jour, entre les deux soirs; ils la mangeront avec des pains sans levain et des herbes amères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'ils n’en laisseront rien jusqu’au matin et n’en casseront pas un os; ils la feront selon tous les statuts de la Pâque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Mais l’homme qui est pur et qui n’est pas en voyage, qui s’abstient de faire la Pâque, cette âme sera retranchée de ses peuples; car il n’a pas présenté l’offrande de l’ Éternel au temps fixé: cet homme portera son péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Et si un étranger séjourne chez vous, et veut faire la Pâque à l’ Éternel, il la fera ainsi, selon le statut de la Pâque et selon son ordonnance. Il y aura un même statut pour vous, tant pour l’étranger que pour l’Israélite de naissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, '*Et le jour où le tabernacle fut dressé, la nuée couvrit le tabernacle de la tente du témoignage, et elle était le soir sur le tabernacle comme l’apparence du feu, jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Il en fut ainsi continuellement: la nuée le couvrait, et la nuit, elle avait l’apparence du feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Et selon que la nuée se levait de dessus la tente, après cela les fils d’Israël partaient; et au lieu où la nuée demeurait, là les fils d’Israël campaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Au commandement de l’ Éternel, les fils d’Israël partaient, et au commandement de l’ Éternel, ils campaient; pendant tous les jours que la nuée demeurait sur le tabernacle, ils campaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Et si la nuée prolongeait sa demeure sur le tabernacle plusieurs jours, alors les fils d’Israël gardaient ce que l’ Éternel leur avait donné à garder, et ne partaient pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Et s’il arrivait que la nuée soit sur le tabernacle peu de jours, ils campaient au commandement de l’ Éternel, et au commandement de l’ Éternel ils partaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Et s’il arrivait que la nuée y soit depuis le soir jusqu’au matin, et que la nuée se lève au matin, alors ils partaient; ou si, après un jour et une nuit, la nuée se levait, ils partaient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'ou si la nuée prolongeait sa demeure pendant deux jours, ou un mois, ou [beaucoup] de jours sur le tabernacle, pour y demeurer, les fils d’Israël campaient et ne partaient pas; mais quand elle se levait, ils partaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Au commandement de l’ Éternel ils campaient, et au commandement de l’ Éternel ils partaient; ils gardaient ce que l’ Éternel leur avait donné à garder, selon le commandement de l’ Éternel par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Fais-toi deux trompettes; tu les feras d’argent battu; et elles te serviront pour la convocation de l’assemblée, et pour le départ des camps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Et lorsqu’on en sonnera, toute l’assemblée s’assemblera vers toi, à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Et si l’on sonne d’une seule, alors les princes, les chefs des milliers d’Israël, s’assembleront vers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Et quand vous sonnerez avec éclat, les camps qui sont campés à l’orient partiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Et quand vous sonnerez avec éclat une seconde fois, les camps qui sont campés au midi partiront; on sonnera avec éclat pour leurs départs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Et quand on réunira la congrégation, vous sonnerez, mais non pas avec éclat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Les fils d’Aaron, les sacrificateurs, sonneront des trompettes; et elles seront pour vous un statut perpétuel en vos générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Et quand, dans votre pays, vous irez à la guerre contre l’ennemi qui vous presse, alors vous sonnerez des trompettes avec éclat, et vous serez rappelés en mémoire devant l’ Éternel, votre Dieu, et vous serez délivrés de vos ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Et dans vos jours de joie, et dans vos jours solennels, et au commencement de vos mois, vous sonnerez des trompettes sur vos holocaustes, et sur vos sacrifices de prospérités, et elles seront un mémorial pour vous devant votre Dieu. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, '*Et il arriva, en la seconde année, au second mois, le vingtième [jour] du mois, que la nuée se leva de dessus le tabernacle du témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Et les fils d’Israël partirent du désert de Sinaï, selon leur ordre de départ, et la nuée demeura dans le désert de Paran.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Et ils partirent, pour la première fois, selon le commandement de l’ Éternel par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'La bannière du camp des fils de Juda partit la première, selon leurs armées; et son armée était sous Nakhshon, fils d’Amminadab;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'et l’armée de la tribu des fils d’Issacar était sous Nethaneël, fils de Tsuar;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'et l’armée de la tribu des fils de Zabulon était sous Éliab, fils de Hélon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Et le tabernacle fut démonté; puis les fils de Guershon et les fils de Merari partirent, portant le tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Et la bannière du camp de Ruben partit, selon leurs armées; et son armée était sous Élitsur, fils de Shedéur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'et l’armée de la tribu des fils de Siméon était sous Shelumiel, fils de Tsurishaddaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'et l’armée de la tribu des fils de Gad était sous Éliasaph, fils de Dehuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Puis les Kehathites partirent, portant le sanctuaire; et on dressa le tabernacle, en attendant leur arrivée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Et la bannière du camp des fils d’Éphraïm partit, selon leurs armées; et son armée était sous Élishama, fils d’Ammihud;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'et l’armée de la tribu des fils de Manassé était sous Gameliel, fils de Pedahtsur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'et l’armée de la tribu des fils de Benjamin était sous Abidan, fils de Guidhoni.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Et la bannière du camp des fils de Dan partit, à l’arrière-garde de tous les camps, selon leurs armées; et son armée était sous Akhiézer, fils d’Ammishaddaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'et l’armée de la tribu des fils d’Aser était sous Paghiel, fils d’Ocran;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'et l’armée de la tribu des fils de Nephthali était sous Akhira, fils d’Énan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Tel fut l’ordre de marche des fils d’Israël, selon leurs armées; et ils partirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Et Moïse dit à Hobab, fils de Rehuel, Madianite, beau-père de Moïse: Nous partons pour le lieu dont l’ Éternel a dit: Je vous le donnerai. Viens avec nous, et nous te ferons du bien; car l’ Éternel a dit du bien à l’égard d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Et il lui dit: Je n’irai pas; mais je m’en irai dans mon pays, et vers ma parenté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Et [Moïse] dit: Je te prie, ne nous laisse pas, parce que tu connais les lieux où nous aurons à camper dans le désert; et tu nous serviras d’yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Et il arrivera, si tu viens avec nous, que le bien que l’ Éternel veut nous faire nous te le ferons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Et ils partirent de la montagne de l’ Éternel, le chemin de trois jours; et l’arche de l’alliance de l’ Éternel alla devant eux, le chemin de trois jours, pour leur chercher un lieu de repos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Et la nuée de l’ Éternel était sur eux de jour, quand ils partaient de leur campement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Et il arrivait qu’au départ de l’arche, Moïse disait: Lève-toi, Éternel! et que tes ennemis soient dispersés, et que ceux qui te haïssent s’enfuient devant toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Et quand elle se reposait, il disait: Reviens, Éternel, aux 10 000 milliers d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, '*Et il arriva que comme le peuple se plaignait, cela fut mauvais aux oreilles de l’ Éternel; et l’ Éternel l’entendit, et sa colère s’embrasa, et le feu de l’ Éternel brûla parmi eux, et dévora au bout du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Et le peuple cria à Moïse, et Moïse pria l’ Éternel, et le feu s’éteignit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Et on appela le nom de ce lieu Tabhéra, parce que le feu de l’ Éternel avait brûlé parmi eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, '*Et le ramassis [de peuple] qui était au milieu d’eux s’éprit de convoitise, et les fils d’Israël aussi se mirent encore à pleurer, et dirent: Qui nous fera manger de la chair?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Il nous souvient du poisson que nous mangions en Égypte pour rien, des concombres, et des melons, et des poireaux, et des oignons, et de l’ail;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'et maintenant notre âme est asséchée; il n’y a rien, si ce n’est cette manne devant nos yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, '– Et la manne était comme la graine de coriandre, et son apparence comme l’apparence du bdellium.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Le peuple se dispersait et la ramassait; et ils la broyaient sous la meule ou la pilaient dans le mortier; et ils la cuisaient dans des pots, et en faisaient des gâteaux; et son goût était comme le goût d’un gâteau à l’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Et quand la rosée descendait la nuit sur le camp la manne descendait dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Et Moïse entendit le peuple pleurant, selon ses familles, chacun à l’entrée de sa tente; et la colère de l’ Éternel s’embrasa extrêmement, et cela fut mauvais aux yeux de Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Et Moïse dit à l’ Éternel: Pourquoi as-tu fait ce mal à ton serviteur? et pourquoi n’ai-je pas trouvé grâce à tes yeux, que tu aies mis sur moi le fardeau de tout ce peuple?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Est-ce moi qui ai conçu tout ce peuple? Est-ce moi qui l’ai enfanté, pour que tu me dises: Porte-le dans ton sein, comme le nourricier porte l’enfant qui tète, jusqu’au pays que tu as promis par serment à ses pères?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'D’où aurais-je de la chair pour en donner à tout ce peuple? car ils pleurent après moi, disant: Donne-nous de la chair, afin que nous en mangions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Je ne puis, moi seul, porter tout ce peuple, car il est trop pesant pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Et si tu agis ainsi avec moi, tue -moi donc, je te prie, si j’ai trouvé grâce à tes yeux, et que je ne voie pas mon malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Et l’ Éternel dit à Moïse: Assemble-moi 70 hommes des anciens d’Israël, que tu sais être les anciens du peuple et ses magistrats, et amène-les à la tente d’assignation, et ils se tiendront là avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Et je descendrai, et je parlerai là avec toi, et j’ôterai de l’Esprit qui est sur toi, et je le mettrai sur eux, afin qu’ils portent avec toi le fardeau du peuple, et que tu ne le portes pas toi seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Et tu diras au peuple: Sanctifiez-vous pour demain, et vous mangerez de la chair; car vous avez pleuré aux oreilles de l’ Éternel, disant: Qui nous fera manger de la chair? car nous étions bien en Égypte! Et l’ Éternel vous donnera de la chair, et vous en mangerez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Vous n’en mangerez pas un jour, ni deux jours, ni cinq jours, ni dix jours, ni 20 jours,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, '[mais] jusqu’à un mois entier, jusqu’à ce qu’elle vous sorte par les narines et que vous l’ayez en dégoût; parce que vous avez méprisé l’ Éternel qui est au milieu de vous, et que vous avez pleuré devant lui, disant: Pourquoi sommes-nous donc sortis d’Égypte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Et Moïse dit: Il y a 600 000 hommes de pied dans ce peuple au milieu duquel je suis, et tu as dit: Je leur donnerai de la chair, et ils en mangeront un mois entier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Leur égorgera-t-on du menu et du gros bétail, afin qu’il y en ait assez pour eux? ou assemblera-t-on tous les poissons de la mer pour eux, afin qu’il y en ait assez pour eux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Et l’ Éternel dit à Moïse: La main de l’ Éternel est-elle devenue courte? Tu verras maintenant si ce que j’ai dit t’arrivera ou non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Et Moïse sortit, et dit au peuple les paroles de l’ Éternel; et il assembla 70 hommes des anciens du peuple, et les fit se tenir tout autour de la tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Et l’ Éternel descendit dans la nuée, et lui parla; et il ôta de l’Esprit qui était sur lui, et le mit sur les 70 anciens. Et il arriva qu’aussitôt que l’Esprit reposa sur eux, ils prophétisèrent, mais ils ne continuèrent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Et il était demeuré deux hommes dans le camp; le nom de l’un était Eldad, et le nom du second, Médad; et l’Esprit reposa sur eux; et ils étaient de ceux qui avaient été inscrits, mais ils n’étaient pas sortis vers la tente, et ils prophétisèrent dans le camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Et un jeune homme courut et rapporta cela à Moïse, disant: Eldad et Médad prophétisent dans le camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Et Josué, fils de Nun, qui servait Moïse, l’un de ses jeunes gens, répondit et dit: Mon seigneur Moïse, empêche-les.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Et Moïse lui dit: Es-tu jaloux pour moi? Ah! que plutôt tout le peuple de l’ Éternel soit prophète; que l’ Éternel mette son Esprit sur eux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Et Moïse revint dans le camp, lui et les anciens d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Et il se leva, de par l’ Éternel, un vent qui fit venir de la mer des cailles, et les jeta sur le camp, environ une journée de chemin en deçà, et environ une journée de chemin en delà, tout autour du camp, et environ deux coudées sur la surface de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Et le peuple se leva tout ce jour-là, et toute la nuit, et tout le jour du lendemain, et amassa des cailles: celui qui en avait amassé le moins, en avait amassé dix khomers; et ils les étendirent pour eux tout autour du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, '– La chair était encore entre leurs dents, avant qu’elle soit mâchée, que la colère de l’ Éternel s’embrasa contre le peuple, et que l’ Éternel frappa le peuple d’un fort grand coup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Et on appela le nom de ce lieu-là Kibroth-Hattaava, parce qu’on y enterra le peuple qui avait convoité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'De Kibroth-Hattaava le peuple partit pour Hatséroth, et ils furent à Hatséroth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, '*Et Marie et Aaron parlèrent contre Moïse à l’occasion de la femme éthiopienne qu’il avait prise, car il avait pris une femme éthiopienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Et ils dirent: L’ Éternel n’a-t-il parlé que par Moïse seulement? n’a-t-il pas parlé aussi par nous? Et l’ Éternel l’entendit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Et cet homme, Moïse, était très doux, plus que tous les hommes qui étaient sur la face de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Et soudain l’ Éternel dit à Moïse, et à Aaron et à Marie: Sortez, vous trois, vers la tente d’assignation. Et ils sortirent eux trois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Et l’ Éternel descendit dans la colonne de nuée, et se tint à l’entrée de la tente; et il appela Aaron et Marie, et ils sortirent eux deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Et il dit: Écoutez mes paroles: S’il y a un prophète parmi vous, moi l’ Éternel, je me ferai connaître à lui en vision, je lui parlerai en songe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Il n’en est pas ainsi de mon serviteur Moïse, qui est fidèle dans toute ma maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'je parle avec lui bouche à bouche, et [en me révélant] clairement, et non en énigmes; et il voit la ressemblance de l’ Éternel. Et pourquoi n’avez-vous pas craint de parler contre mon serviteur, contre Moïse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Et la colère de l’ Éternel s’embrasa contre eux, et il s’en alla;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'et la nuée se retira de dessus la tente: et voici, Marie était lépreuse, comme la neige; et Aaron se tourna vers Marie, et voici, elle était lépreuse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, '– Et Aaron dit à Moïse: Ah, mon seigneur! ne mets pas, je te prie, sur nous, ce péché par lequel nous avons agi follement et par lequel nous avons péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Je te prie, qu’elle ne soit pas comme un [enfant] mort, dont la chair est à demi consumée quand il sort du ventre de sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Et Moïse cria à l’ Éternel, disant: Ô ✶Dieu! je te prie, guéris-la, je te prie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Et l’ Éternel dit à Moïse: Si son père lui avait craché au visage, ne serait-elle pas pendant sept jours dans la honte? Qu’elle soit exclue, sept jours, hors du camp, et après, qu’elle y soit recueillie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Et Marie demeura exclue hors du camp sept jours; et le peuple ne partit pas jusqu’à ce que Marie ait été recueillie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, '*Et après, le peuple partit de Hatséroth, et il campa au désert de Paran.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Envoie des hommes, et ils reconnaîtront le pays de Canaan, que je donne aux fils d’Israël; vous enverrez un homme pour chaque tribu de ses pères, tous des princes parmi eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Et Moïse les envoya du désert de Paran, selon le commandement de l’ Éternel. Tous ces hommes étaient des chefs des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Et ce sont ici leurs noms: pour la tribu de Ruben, Shammua, fils de Zaccur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'pour la tribu de Siméon, Shaphath, fils de Hori;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'pour la tribu de Juda, Caleb, fils de Jephunné;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'pour la tribu d’Issacar, Jighal, fils de Joseph;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'pour la tribu d’Éphraïm, Osée, fils de Nun;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'pour la tribu de Benjamin, Palti, fils de Raphu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'pour la tribu de Zabulon, Gaddiel, fils de Sodi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'pour la tribu de Joseph, pour la tribu de Manassé, Gaddi, fils de Susi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'pour la tribu de Dan, Ammiel, fils de Guemalli;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'pour la tribu d’Aser, Sethur, fils de Micaël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'pour la tribu de Nephthali, Nakhbi, fils de Vophsi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'pour la tribu de Gad, Gueuël, fils de Maki.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, '– Ce sont là les noms des hommes que Moïse envoya pour reconnaître le pays. Et Moïse appela Osée, fils de Nun, Josué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Et Moïse les envoya pour reconnaître le pays de Canaan, et leur dit: Montez de ce côté, par le midi; et vous monterez [dans] la montagne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'et vous verrez le pays, ce qu’il est, et le peuple qui l’habite; s’il est fort ou faible, s’il est en petit nombre ou en grand nombre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'et quel est le pays où il habite, s’il est bon ou mauvais; et quelles sont les villes dans lesquelles il habite, si c’est dans des camps ou dans des villes murées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'et quel est le pays, s’il est gras ou maigre, s’il y a des arbres ou s’il n’y en a pas. Ayez bon courage, et prenez du fruit du pays. Or c’était le temps des premiers raisins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Et ils montèrent et reconnurent le pays, depuis le désert de Tsin jusqu’à Rehob, quand on vient à Hamath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Et ils montèrent par le midi, et vinrent jusqu’à Hébron; et là étaient Akhiman, Shéshaï et Thalmaï, enfants d’Anak. Et Hébron avait été bâtie sept ans avant Tsoan d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Et ils vinrent jusqu’au torrent d’Eshcol, et coupèrent de là un sarment avec une grappe de raisin; et ils le portèrent à deux au moyen d’une perche, et des grenades et des figues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'On appela ce lieu-là torrent d’Eshcol, à cause de la grappe que les fils d’Israël y coupèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Et ils revinrent de la reconnaissance du pays au bout de 40 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Et ils allèrent, et arrivèrent auprès de Moïse et d’Aaron, et de toute l’assemblée des fils d’Israël, au désert de Paran, à Kadès; et ils leur rendirent compte, ainsi qu’à toute l’assemblée, et leur montrèrent le fruit du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Et ils racontèrent à Moïse, et dirent: Nous sommes allés dans le pays où tu nous as envoyés; et vraiment il est ruisselant de lait et de miel, et en voici le fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Seulement, le peuple qui habite dans le pays est fort, et les villes sont fortifiées, très grandes; et nous y avons vu aussi les enfants d’Anak.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalek habite le pays du midi; et le Héthien, le Jébusien et l’Amoréen habitent la montagne; et le Cananéen habite le long de la mer et sur le rivage du Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Et Caleb fit taire le peuple devant Moïse, et dit: Montons hardiment et prenons possession du [pays], car nous sommes bien capables de le faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Mais les hommes qui étaient montés avec lui, dirent: Nous ne sommes pas capables de monter contre ce peuple, car il est plus fort que nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Et ils décrièrent devant les fils d’Israël le pays qu’ils avaient reconnu, disant: Le pays par lequel nous avons passé pour le reconnaître est un pays qui dévore ses habitants, et tout le peuple que nous y avons vu est de haute stature.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Et nous y avons vu les géants, fils d’Anak, qui est [de la race] des géants; et nous étions à nos yeux comme des sauterelles, et nous étions de même à leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, '*Et toute l’assemblée éleva sa voix, et jeta des cris, et le peuple pleura cette nuit-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Et tous les fils d’Israël murmurèrent contre Moïse et contre Aaron; et toute l’assemblée leur dit: Oh! si nous étions morts dans le pays d’Égypte! Ou si nous étions morts dans ce désert!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Et pourquoi l’ Éternel nous fait-il venir dans ce pays, pour y tomber par l’épée, pour que nos femmes et nos petits enfants deviennent une proie? Ne serait-il pas bon pour nous de retourner en Égypte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Et ils se dirent l’un à l’autre: Établissons un chef, et retournons en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Et Moïse et Aaron tombèrent sur leurs faces devant toute la congrégation de l’assemblée des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Et Josué, fils de Nun, et Caleb, fils de Jephunné, qui étaient d’entre ceux qui avaient reconnu le pays, déchirèrent leurs vêtements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'et parlèrent à toute l’assemblée des fils d’Israël, disant: Le pays par lequel nous avons passé pour le reconnaître est un très bon pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Si l’ Éternel prend plaisir en nous, il nous fera entrer dans ce pays-là et nous le donnera, un pays qui ruisselle de lait et de miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Seulement, ne vous rebellez pas contre l’ Éternel; et ne craignez pas le peuple du pays, car ils seront notre pain: leur protection s’est retirée de dessus eux, et l’ Éternel est avec nous; ne les craignez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Et toute l’assemblée parla de les lapider avec des pierres. Et la gloire de l’ Éternel apparut à tous les fils d’Israël à la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Et l’ Éternel dit à Moïse: Jusques à quand ce peuple-ci me méprisera-t-il, et jusques à quand ne me croira-t-il pas, après tous les signes que j’ai faits au milieu de lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Je le frapperai de peste, et je le détruirai; et je ferai de toi une nation plus grande et plus forte que lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Et Moïse dit à l’ Éternel: Mais les Égyptiens en entendront parler (car par ta force tu as fait monter ce peuple du milieu d’eux),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'et ils [le] diront aux habitants de ce pays, qui ont entendu que toi, Éternel, tu étais au milieu de ce peuple, que toi, Éternel, tu te faisais voir face à face, et que ta nuée se tenait sur eux, et que tu marchais devant eux dans une colonne de nuée, le jour, et dans une colonne de feu, la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Si tu fais périr ce peuple comme un seul homme, les nations qui ont entendu parler de toi, parleront, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Parce que l’ Éternel ne pouvait pas faire entrer ce peuple dans le pays qu’il leur avait promis par serment, il les a tués dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Et maintenant, je te prie, que la puissance du Seigneur soit magnifiée, comme tu as parlé, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'L’ Éternel est lent à la colère, et grand en bonté, pardonnant l’iniquité et la transgression, et qui ne tient nullement [celui qui en est coupable] pour innocent, qui visite l’iniquité des pères sur les fils, sur la troisième et sur la quatrième [génération].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Pardonne, je te prie, l’iniquité de ce peuple, selon la grandeur de ta bonté, et comme tu as pardonné à ce peuple depuis l’Égypte jusqu’ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Et l’ Éternel dit: J’ai pardonné selon ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Mais, aussi vrai que je suis vivant, toute la terre sera remplie de la gloire de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Car tous ces hommes qui ont vu ma gloire, et mes signes, que j’ai faits en Égypte et dans le désert, et qui m’ont tenté ces dix fois, et qui n’ont pas écouté ma voix;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 's’ils voient le pays que j’avais promis par serment à leurs pères! Aucun de ceux qui m’ont méprisé ne le verra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Mais mon serviteur Caleb, parce qu’il a été animé d’un autre esprit et qu’il m’a pleinement suivi, je l’introduirai dans le pays où il est entré, et sa semence le possédera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Or l’Amalékite et le Cananéen habitent dans la vallée: demain tournez-vous, et partez pour le désert, vous dirigeant vers la mer Rouge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Et l’ Éternel parla à Moïse et à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Jusques à quand [supporterai-je] cette méchante assemblée qui murmure contre moi? J’ai entendu les murmures des fils d’Israël, qu’ils murmurent contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Dis-leur: Je suis vivant, dit l’ Éternel, si je ne vous fais comme vous avez parlé à mes oreilles...!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Vos cadavres tomberont dans ce désert. Et tous ceux d’entre vous qui ont été dénombrés, selon tout le compte qui a été fait de vous, depuis l’âge de 20 ans et au-dessus, vous qui avez murmuré contre moi,...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'si vous entrez dans le pays touchant lequel j’ai levé ma main pour vous y faire habiter, excepté Caleb, fils de Jephunné, et Josué, fils de Nun!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Mais vos petits enfants, dont vous avez dit qu’ils seraient une proie, je les ferai entrer, et ils connaîtront le pays que vous avez méprisé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Et quant à vous, vos cadavres tomberont dans ce désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Et vos fils seront paissant dans le désert 40 ans, et ils porteront [la peine de] vos prostitutions, jusqu’à ce que vos cadavres soient consumés dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Selon le nombre des jours que vous avez mis à reconnaître le pays, 40 jours, un jour pour une année, vous porterez vos iniquités 40 ans, et vous connaîtrez ce que c’est que je me sois détourné de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Moi, l’ Éternel, j’ai parlé; si je ne fais ceci à toute cette méchante assemblée qui s’est assemblée contre moi! Ils seront consumés dans ce désert, et ils y mourront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Et les hommes que Moïse avait envoyés pour reconnaître le pays, et qui revinrent et firent murmurer contre lui toute l’assemblée en décriant le pays,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'ces hommes qui avaient décrié le pays, moururent de plaie devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Mais d’entre les hommes qui étaient allés pour reconnaître le pays, Josué, fils de Nun, et Caleb, fils de Jephunné, [seuls] vécurent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Et Moïse dit ces choses à tous les fils d’Israël, et le peuple mena très grand deuil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Et ils se levèrent de bon matin et montèrent sur le sommet de la montagne, disant: Nous voici; nous monterons au lieu dont l’ Éternel a parlé; car nous avons péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Et Moïse dit: Pourquoi transgressez-vous ainsi le commandement de l’ Éternel? Cela ne réussira point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Ne montez pas, car l’ Éternel n’est pas au milieu de vous, afin que vous ne soyez pas battus devant vos ennemis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'car l’Amalékite et le Cananéen sont là devant vous, et vous tomberez par l’épée; car, parce que vous vous êtes détournés de l’ Éternel, l’ Éternel ne sera pas avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Toutefois ils s’obstinèrent à monter sur le sommet de la montagne; mais l’arche de l’alliance de l’ Éternel et Moïse ne bougèrent pas du milieu du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Et les Amalékites et les Cananéens qui habitaient cette montagne-là, descendirent, et les battirent, et les taillèrent en pièces jusqu’à Horma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Parle aux fils d’Israël, et dis-leur: Quand vous serez entrés dans le pays de votre habitation, que je vous donne,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'et que vous offrirez un sacrifice par feu à l’ Éternel, un holocauste, ou un sacrifice pour s’acquitter d’un vœu, ou un sacrifice volontaire, ou dans vos jours solennels, pour offrir une odeur agréable à l’ Éternel, de gros ou de menu bétail,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'alors celui qui présentera son offrande à l’ Éternel, présentera une offrande de gâteau d’un dixième de fleur de farine pétrie avec le quart d’un hin d’huile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'et tu offriras le quart d’un hin de vin pour la libation, sur l’holocauste ou le sacrifice, pour un agneau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Et pour un bélier, tu offriras comme offrande de gâteau deux dixièmes de fleur de farine pétrie avec le tiers d’un hin d’huile,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'et le tiers d’un hin de vin pour la libation; tu le présenteras comme odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Et si tu offres un jeune taureau comme holocauste, ou comme sacrifice pour t’acquitter d’un vœu, ou comme sacrifice de prospérités à l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'on présentera avec le jeune taureau, comme offrande de gâteau, trois dixièmes de fleur de farine pétrie avec un demi-hin d’huile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'et tu présenteras un demi-hin de vin pour la libation, en sacrifice par feu, d’odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'On en fera ainsi pour un taureau, ou pour un bélier, ou pour un agneau, ou pour un chevreau,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'selon le nombre que vous en offrirez; vous en ferez ainsi pour chacun, selon leur nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Tous les Israélites de naissance feront ces choses ainsi, en présentant un sacrifice par feu, d’odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Et si un étranger séjourne parmi vous, ou si quelqu’un est au milieu de vous en vos générations, et qu’il offre un sacrifice par feu, d’odeur agréable à l’ Éternel, – comme vous faites, ainsi il fera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Pour ce qui est de la congrégation, il y aura un même statut pour vous et pour l’étranger en séjour, un statut perpétuel en vos générations; comme vous, ainsi sera l’étranger devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Il y aura une même loi et une même ordonnance pour vous et pour l’étranger qui séjourne parmi vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Parle aux fils d’Israël, et dis-leur: Quand vous serez entrés dans le pays où je vous fais entrer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'et que vous mangerez du pain du pays, vous en offrirez à l’ Éternel une offrande élevée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'vous offrirez les prémices de votre pâte, une galette, en offrande élevée; comme l’offrande élevée de l’aire, ainsi vous l’offrirez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Vous donnerez, en vos générations, à l’ Éternel, une offrande élevée des prémices de votre pâte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Et lorsque vous aurez péché par erreur, et que vous n’aurez pas fait tous ces commandements que l’ Éternel a dits à Moïse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'tout ce que l’ Éternel vous a commandé par Moïse, depuis le jour où l’ Éternel a donné ses commandements, et dans la suite en vos générations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 's’il arrive que la chose a été faite par erreur, loin des yeux de l’assemblée, alors toute l’assemblée offrira un jeune taureau en holocauste, en odeur agréable à l’ Éternel, et son offrande de gâteau et sa libation, selon l’ordonnance, et un bouc en sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Et le sacrificateur fera propitiation pour toute l’assemblée des fils d’Israël, et il leur sera pardonné, car c’est une chose arrivée par erreur, et ils ont amené devant l’ Éternel leur offrande, un sacrifice par feu à l’ Éternel, et le sacrifice pour leur péché, à cause de leur erreur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Et il sera pardonné à toute l’assemblée des fils d’Israël et à l’étranger qui séjourne parmi eux, car [cela est arrivé] à tout le peuple par erreur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Et si une âme pèche par erreur, elle présentera une chèvre âgée d’un an pour sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Et le sacrificateur fera propitiation pour l’âme qui aura péché par erreur, quand elle aura péché par erreur devant l’ Éternel, afin de faire propitiation pour elle, et il lui sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Il y aura une même loi pour vous quant à celui qui a agi par erreur, tant pour celui qui est né dans le pays parmi les fils d’Israël, que pour l’étranger qui séjourne au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Mais l’âme qui aura péché par fierté, tant l’Israélite de naissance que l’étranger, elle a outragé l’ Éternel: cette âme sera retranchée du milieu de son peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'car elle a méprisé la parole de l’ Éternel, et elle a enfreint son commandement: cette âme sera certainement retranchée; son iniquité est sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Et comme les fils d’Israël étaient au désert, ils trouvèrent un homme qui ramassait du bois le jour du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Et ceux qui le trouvèrent ramassant du bois, l’amenèrent à Moïse et à Aaron, et à toute l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Et on le mit sous garde, car ce qu’on devait lui faire n’avait pas été clairement indiqué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, '– Et l’ Éternel dit à Moïse: L’homme sera mis à mort; que toute l’assemblée le lapide avec des pierres hors du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Et toute l’assemblée le mena hors du camp, et ils le lapidèrent avec des pierres, et il mourut, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Parle aux fils d’Israël, et dis-leur qu’ils se fassent, en leurs générations, une houppe aux coins de leurs vêtements, et qu’ils mettent à la houppe du coin un cordon de bleu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Et elle sera pour vous une houppe; et vous la verrez, et il vous souviendra de tous les commandements de l’ Éternel, afin que vous les fassiez, et que vous ne recherchiez pas [les pensées de] votre cœur, ni [les désirs de] vos yeux, après lesquels vous vous prostituez;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'afin que vous vous souveniez de tous mes commandements, et que vous les fassiez, et que vous soyez saints, [consacrés] à votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Moi, je suis l’ Éternel, votre Dieu, qui vous ai fait sortir du pays d’Égypte pour être votre Dieu. Moi, je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, '*Et Coré, fils de Jitsehar, fils de Kehath, fils de Lévi, s’éleva dans son esprit, et Dathan et Abiram, fils d’Éliab, et On, fils de Péleth, [qui étaient] fils de Ruben;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'et ils se levèrent devant Moïse, avec 250 hommes des fils d’Israël, princes de l’assemblée, [hommes] appelés au conseil, des hommes de renom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Et ils s’attroupèrent contre Moïse et contre Aaron, et leur dirent: C’en est assez! car toute l’assemblée, eux tous sont saints, et l’ Éternel est au milieu d’eux; et pourquoi vous élevez-vous au-dessus de la congrégation de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Et Moïse l’entendit, et tomba sur sa face;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'et il parla à Coré et à toute son assemblée, disant: Demain, l’ Éternel fera connaître qui est à lui, et qui est saint, et il le fera approcher de lui; et celui qu’il a choisi, il le fera approcher de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Faites ceci: Prenez des encensoirs, Coré et toute son assemblée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'et demain, mettez-y du feu et placez de l’encens dessus, devant l’ Éternel; et il arrivera que l’homme que l’ Éternel aura choisi, celui-là sera saint. C’en est assez, fils de Lévi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Et Moïse dit à Coré: Écoutez, fils de Lévi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Est-ce peu de chose pour vous que le Dieu d’Israël vous ait séparés de l’assemblée d’Israël, en vous faisant approcher de lui pour faire le service du tabernacle de l’ Éternel, et pour vous tenir devant l’assemblée afin de la servir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, '– qu’il t’ait fait approcher, toi et tous tes frères, les fils de Lévi, avec toi,... que vous recherchiez aussi la sacrificature?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'C’est pourquoi, toi et toute ton assemblée, vous vous êtes rassemblés contre l’ Éternel; et Aaron, qui est-il, que vous murmuriez contre lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Et Moïse envoya appeler Dathan et Abiram, fils d’Éliab; mais ils dirent: Nous ne monterons pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Est-ce peu de chose que tu nous aies fait monter hors d’un pays ruisselant de lait et de miel, pour nous faire mourir dans le désert, que tu te fasses absolument dominateur sur nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Certes tu ne nous as pas introduits dans un pays ruisselant de lait et de miel, et tu ne nous as pas donné un héritage de champs et de vignes! Veux-tu crever les yeux de ces gens? Nous ne monterons pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Et Moïse entra dans une ardente colère, et il dit à l’ Éternel: N’aie pas égard à leur offrande; je n’ai pas pris d’eux même un âne, et je n’ai pas fait tort à un seul d’entre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Et Moïse dit à Coré: Toi, et toute ton assemblée, soyez demain devant l’ Éternel, toi et eux, et Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Et prenez chacun votre encensoir, et mettez de l’encens dessus; et présentez devant l’ Éternel chacun votre encensoir, 250 encensoirs; et toi, et Aaron, chacun son encensoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Et ils prirent chacun son encensoir, et y mirent du feu, et placèrent de l’encens dessus, et se tinrent à l’entrée de la tente d’assignation, avec Moïse et Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Et Coré réunit contre eux toute l’assemblée à l’entrée de la tente d’assignation; et la gloire de l’ Éternel apparut à toute l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Et l’ Éternel parla à Moïse et à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Séparez-vous du milieu de cette assemblée, et je les consumerai en un moment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Et ils tombèrent sur leurs faces, et dirent: Ô ✶Dieu! Dieu des esprits de toute chair! un seul homme péchera, et tu seras courroucé contre toute l’assemblée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Parle à l’assemblée, en disant: Retirez-vous d’autour de la demeure de Coré, de Dathan et d’Abiram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Et Moïse se leva et alla vers Dathan et Abiram; et les anciens d’Israël allèrent après lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Et il parla à l’assemblée, disant: Éloignez-vous, je vous prie, d’auprès des tentes de ces méchants hommes, et ne touchez à rien qui leur appartienne, de peur que vous ne périssiez dans tous leurs péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Et ils se retirèrent d’auprès de la demeure de Coré, de Dathan et d’Abiram, tout à l’entour. Et Dathan et Abiram sortirent, et se tinrent à l’entrée de leurs tentes avec leurs femmes, et leurs fils, et leurs petits enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Et Moïse dit: À ceci vous connaîtrez que l’ Éternel m’a envoyé pour faire toutes ces œuvres, car elles ne sont pas sorties de mon cœur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'si ceux-là meurent selon la mort de tout homme, et s’ils sont visités de la visitation de tout homme, l’ Éternel ne m’a pas envoyé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'mais si l’ Éternel crée une chose nouvelle, et que le sol ouvre sa bouche et les engloutisse avec tout ce qui est à eux, et qu’ils descendent vivants dans le shéol, alors vous saurez que ces hommes ont méprisé l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Et il arriva, comme il achevait de prononcer toutes ces paroles, que le sol qui était sous eux se fendit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'et la terre ouvrit sa bouche, et les engloutit, [eux] et leurs maisons, et tous les hommes qui étaient à Coré, et tout leur avoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Et ils descendirent vivants dans le shéol, eux et tout ce qui était à eux; et la terre les couvrit, et ils périrent du milieu de la congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Et tout Israël qui était autour d’eux s’enfuit à leur cri; car ils disaient:... De peur que la terre ne nous engloutisse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Et il sortit du feu de la part de l’ Éternel, et il consuma les 250 hommes qui présentaient l’encens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Dis à Éléazar, fils d’Aaron, le sacrificateur, qu’il relève les encensoirs du milieu de l’incendie, et répands-en le feu au loin, car ils sont sanctifiés, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'les encensoirs de ceux-là qui ont péché contre leurs propres âmes; et on en fera des lames aplaties pour en plaquer l’autel; car ils les ont présentés devant l’ Éternel, et ils sont sanctifiés; et ils seront un signe aux fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Et Éléazar, le sacrificateur, prit les encensoirs d’airain qu’avaient présentés les [hommes] qui furent brûlés, et on les aplatit pour plaquer l’autel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'en mémorial pour les fils d’Israël, afin qu’aucun étranger qui n’est pas de la semence d’Aaron ne s’approche pour brûler l’encens devant l’ Éternel, et ne soit comme Coré et son assemblée, – selon que l’ Éternel lui avait parlé par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Et le lendemain, toute l’assemblée des fils d’Israël murmura contre Moïse et contre Aaron, disant: Vous avez mis à mort le peuple de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Et il arriva, comme l’assemblée se réunissait contre Moïse et contre Aaron, qu’ils regardèrent vers la tente d’assignation, et voici, la nuée la couvrit, et la gloire de l’ Éternel apparut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Et Moïse et Aaron vinrent devant la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Retirez-vous du milieu de cette assemblée, et je les consumerai en un moment. Et ils tombèrent sur leurs faces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Et Moïse dit à Aaron: Prends l’encensoir, et mets-y du feu de dessus l’autel, et mets-y de l’encens, et porte-le promptement vers l’assemblée, et fais propitiation pour eux; car la colère est sortie de devant l’ Éternel, la plaie a commencé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Et Aaron le prit, comme Moïse lui avait dit, et il courut au milieu de la congrégation; et voici, la plaie avait commencé au milieu du peuple. Et il mit l’encens, et fit propitiation pour le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Et il se tint entre les morts et les vivants, et la plaie s’arrêta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 14, 'Et il y en eut 14 700 qui moururent de la plaie, outre ceux qui étaient morts dans l’affaire de Coré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 15, 'Et Aaron retourna vers Moïse, à l’entrée de la tente d’assignation; et la plaie s’arrêta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 16, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 17, 'Parle aux fils d’Israël, et prends d’eux, de tous leurs princes, selon leurs maisons de pères, une verge par maison de père, douze verges; tu écriras le nom de chacun sur sa verge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 18, 'et tu écriras le nom d’Aaron sur la verge de Lévi; car il y aura une verge pour [chaque] chef de leurs maisons de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 19, 'Et tu les poseras dans la tente d’assignation, devant le témoignage, où je me rencontre avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 20, 'Et il arrivera que la verge de l’homme que j’ai choisi bourgeonnera; et je ferai cesser de devant moi les murmures des fils d’Israël, par lesquels ils murmurent contre vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 21, 'Et Moïse parla aux fils d’Israël; et tous leurs princes lui donnèrent une verge, une verge pour chaque prince, selon leurs maisons de pères: douze verges; et la verge d’Aaron était au milieu de ces verges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 22, 'Et Moïse posa les verges devant l’ Éternel, dans la tente du témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 23, 'Et il arriva, le lendemain, que Moïse entra dans la tente du témoignage, et voici, la verge d’Aaron, pour la maison de Lévi, avait bourgeonné, et avait poussé des boutons, et avait produit des fleurs et mûri des amandes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 24, 'Et Moïse porta toutes les verges de devant l’ Éternel à tous les fils d’Israël; et ils les virent, et reprirent chacun sa verge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 25, 'Et l’ Éternel dit à Moïse: Reporte la verge d’Aaron devant le témoignage, pour être gardée comme un signe aux fils de rébellion; et tu feras cesser leurs murmures de devant moi, et ils ne mourront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 26, 'Et Moïse fit comme l’ Éternel lui avait commandé; il fit ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 27, 'Et les fils d’Israël parlèrent à Moïse, disant: Voici, nous expirons, nous périssons, nous périssons tous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 28, 'Quiconque s’approche en aucune manière du tabernacle de l’ Éternel, meurt; faut-il donc que nous expirions tous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Et l’ Éternel dit à Aaron: Toi, et tes fils, et la maison de ton père avec toi, vous porterez l’iniquité du sanctuaire; et toi et tes fils avec toi, vous porterez l’iniquité de votre sacrificature.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Et fais aussi approcher tes frères, la tribu de Lévi, la tribu de ton père, avec toi, et ils te seront adjoints, et ils te serviront; et toi et tes fils avec toi, [vous servirez] devant la tente du témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Et ils vaqueront à ce dont tu leur donneras la charge, et au service de toute la tente; seulement, ils n’approcheront pas des ustensiles du lieu saint, et de l’autel, de peur qu’ils ne meurent, eux et vous aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Et ils te seront adjoints, et ils seront chargés de ce qui concerne la tente d’assignation, selon tout le service de la tente; et nul étranger n’approchera de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Et vous serez chargés de ce qui concerne le lieu saint, et de ce qui concerne l’autel, afin qu’il n’y ait plus de colère contre les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Et moi, voici, j’ai pris vos frères, les Lévites, du milieu des fils d’Israël; ils vous sont donnés en don pour l’ Éternel, afin qu’ils s’emploient au service de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Et toi, et tes fils avec toi, vous accomplirez les fonctions de votre sacrificature en tout ce qui regarde l’autel et relativement à ce qui est au-dedans du voile, et vous ferez le service. Je vous donne votre sacrificature comme un service de [pur] don; et l’étranger qui approchera sera mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Et l’ Éternel parla à Aaron: Et moi, voici, je t’ai donné la charge de mes offrandes élevées, de toutes les choses saintes des fils d’Israël; je te les ai données, à cause de l’onction, et à tes fils, par statut perpétuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Ceci sera à toi des choses très saintes, qui n’ont pas été consumées: toutes leurs offrandes, savoir toutes leurs offrandes de gâteau et tous leurs sacrifices pour le péché et tous leurs sacrifices pour le délit qu’ils m’apporteront; ce sont des choses très saintes pour toi et pour tes fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Tu les mangeras comme des choses très saintes, tout mâle en mangera: ce sera pour toi une chose sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Et ceci sera à toi: les offrandes élevées de leurs dons, avec toutes les offrandes tournoyées des fils d’Israël; je te les ai données, et à tes fils et à tes filles avec toi, par statut perpétuel; quiconque sera pur dans ta maison en mangera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Tout le meilleur de l’huile et tout le meilleur du moût et du froment, les prémices qu’ils donneront à l’ Éternel, je te les donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Les premiers fruits de tout ce qui est dans leur pays, qu’ils apporteront à l’ Éternel, seront à toi; quiconque sera pur dans ta maison en mangera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Tout ce qui est voué [à Dieu] en Israël sera à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Tout ce qui ouvre la matrice, de toute chair, qui sera présenté à l’ Éternel, tant homme que bête, sera à toi; seulement tu ne manqueras pas de racheter le premier-né de l’homme, et tu rachèteras le premier-né des bêtes impures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Et ceux qui doivent être rachetés, depuis l’âge d’un mois, tu les rachèteras selon ton estimation, qui sera de cinq sicles d’argent, selon le sicle du sanctuaire, qui est de 20 guéras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Seulement tu ne rachèteras pas le premier-né de la vache, ou le premier-né de la brebis, ou le premier-né de la chèvre; ils sont saints. Tu feras aspersion de leur sang sur l’autel, et tu feras fumer leur graisse en sacrifice par feu, en odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Et leur chair sera à toi; elle sera à toi, comme la poitrine tournoyée et comme l’épaule droite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Toutes les offrandes élevées des choses saintes que les fils d’Israël offrent à l’ Éternel, je te les ai données, et à tes fils et à tes filles avec toi, par statut perpétuel; c’est une alliance de sel, à perpétuité, devant l’ Éternel, pour toi et pour ta semence avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Et l’ Éternel dit à Aaron: Tu n’auras pas d’héritage dans leur pays, et il n’y aura pas de part pour toi au milieu d’eux: moi, je suis ta part et ton héritage au milieu des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Et voici, j’ai donné pour héritage aux fils de Lévi toutes les dîmes en Israël, pour leur service auquel ils s’emploient, le service de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Et les fils d’Israël n’approcheront plus de la tente d’assignation, pour porter le péché et mourir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'mais le Lévite, lui, s’emploiera au service de la tente d’assignation, et ils porteront leur iniquité; c’est un statut perpétuel en vos générations. Et ils ne posséderont pas d’héritage au milieu des fils d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'car j’ai donné pour héritage aux Lévites les dîmes des fils d’Israël, qu’ils offrent à l’ Éternel en offrande élevée; c’est pourquoi j’ai dit d’eux qu’ils ne posséderont pas d’héritage au milieu des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Tu parleras aussi aux Lévites, et tu leur diras: Quand vous prendrez des fils d’Israël la dîme que je vous ai donnée, de leur part, pour votre héritage, vous en offrirez une offrande élevée à l’ Éternel, la dîme de la dîme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Et votre offrande élevée vous sera comptée comme le froment pris de l’aire, et comme l’abondance [du moût] pris de la cuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Ainsi, vous aussi, vous offrirez une offrande élevée à l’ Éternel, de toutes vos dîmes que vous prendrez de la part des fils d’Israël; et vous en donnerez l’offrande élevée de l’ Éternel à Aaron, le sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'De toutes les choses qui vous sont données, vous offrirez toute l’offrande élevée de l’ Éternel, – de tout le meilleur, la partie sanctifiée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Et tu leur diras: Quand vous en aurez offert le meilleur [en offrande élevée], cela sera compté aux Lévites comme le produit de l’aire et comme le produit de la cuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Et vous le mangerez en tout lieu, vous et vos maisons; car c’est votre salaire pour votre service à la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Et vous ne porterez pas de péché à son sujet, quand vous en aurez offert le meilleur [en offrande élevée]; et vous ne profanerez pas les choses saintes des fils d’Israël, et vous ne mourrez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, '*Et l’ Éternel parla à Moïse et à Aaron, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'C’est ici le statut de la loi que l’ Éternel a commandé, en disant: Parle aux fils d’Israël, et qu’ils t’amènent une génisse rousse, sans tare, qui n’ait aucun défaut corporel, [et] qui n’ait point porté le joug.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Et vous la donnerez à Éléazar, le sacrificateur, et il la mènera hors du camp, et on l’égorgera devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Et Éléazar, le sacrificateur, prendra de son sang avec son doigt et fera aspersion de son sang, sept fois, droit devant la tente d’assignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'et on brûlera la génisse devant ses yeux: on brûlera sa peau, et sa chair, et son sang, avec sa fiente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Et le sacrificateur prendra du bois de cèdre, et de l’hysope, et de l’écarlate, et les jettera au milieu du feu où brûle la génisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Et le sacrificateur lavera ses vêtements et lavera sa chair dans l’eau; et après, il entrera dans le camp; et le sacrificateur sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Et celui qui l’aura brûlée lavera ses vêtements dans l’eau, et lavera sa chair dans l’eau; et il sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Et un homme pur ramassera la cendre de la génisse, et la déposera hors du camp en un lieu pur, et elle sera gardée pour l’assemblée des fils d’Israël comme eau de séparation: c’est une purification pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Et celui qui aura ramassé la cendre de la génisse lavera ses vêtements, et sera impur jusqu’au soir. Ce sera un statut perpétuel pour les fils d’Israël et pour l’étranger qui séjourne au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Celui qui aura touché un mort, un cadavre d’homme quelconque, sera impur sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Il se purifiera avec cette [eau] le troisième jour, et le septième jour il sera pur; mais s’il ne se purifie pas le troisième jour, alors il ne sera pas pur le septième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Quiconque aura touché un mort, le cadavre d’un homme qui est mort, et ne se sera pas purifié, a rendu impur le tabernacle de l’ Éternel; et cette âme sera retranchée d’Israël, car l’eau de séparation n’a pas été répandue sur elle; elle sera impure, son impureté est encore sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'C’est ici la loi, lorsqu’un homme meurt dans une tente: quiconque entre dans la tente, et tout ce qui est dans la tente, sera impur sept jours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'et tout vase découvert, sur lequel il n’y a pas de couvercle attaché, sera impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Et quiconque touchera, dans les champs, [un homme] qui aura été tué par l’épée, ou un mort, ou un ossement d’homme, ou un sépulcre, sera impur sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Et on prendra, pour l’homme impur, de la poudre de ce qui a été brûlé pour la purification, et on mettra dessus de l’eau vive dans un vase.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Et un homme pur prendra de l’hysope, et la trempera dans l’eau, et en fera aspersion sur la tente, et sur tous les ustensiles, et sur les personnes qui sont là, et sur celui qui aura touché l’ossement, ou l’homme tué, ou le mort, ou le sépulcre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'et l’homme pur fera aspersion sur l’homme impur, le troisième jour et le septième jour, et il le purifiera le septième jour; et il lavera ses vêtements, et se lavera dans l’eau, et le soir il sera pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Et l’homme qui sera impur, et qui ne se sera pas purifié, cette âme-là sera retranchée du milieu de la congrégation, – car il a rendu impur le sanctuaire de l’ Éternel; l’eau de séparation n’a pas été répandue sur lui; il est impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Et ce sera pour eux un statut perpétuel. Et celui qui aura fait aspersion avec l’eau de séparation lavera ses vêtements, et celui qui aura touché l’eau de séparation sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Et tout ce que l’homme impur aura touché sera impur; et celui qui l’aura touché sera impur jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, '*Et les fils d’Israël, toute l’assemblée, vinrent au désert de Tsin, le premier mois; et le peuple habita à Kadès; et Marie mourut là, et y fut enterrée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Et il n’y avait pas d’eau pour l’assemblée; et ils s’attroupèrent contre Moïse et contre Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Et le peuple contesta avec Moïse, et ils parlèrent, disant: Que n’avons-nous péri, quand nos frères périrent devant l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Et pourquoi avez-vous amené la congrégation de l’ Éternel dans ce désert, pour y mourir, nous et nos bêtes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Et pourquoi nous avez-vous fait monter d’Égypte, pour nous amener dans ce mauvais lieu? Ce n’est pas un lieu où l’on puisse semer; [on n’y trouve] ni figuiers, ni vignes, ni grenadiers, et il n’y a pas d’eau pour boire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Et Moïse et Aaron vinrent de devant la congrégation à l’entrée de la tente d’assignation, et tombèrent sur leurs faces; et la gloire de l’ Éternel leur apparut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Prends la verge, et réunis l’assemblée, toi et Aaron, ton frère, et vous parlerez devant leurs yeux au rocher, et il donnera ses eaux; et tu leur feras sortir de l’eau du rocher, et tu donneras à boire à l’assemblée et à leurs bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Et Moïse prit la verge de devant l’ Éternel, comme il lui avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Et Moïse et Aaron réunirent la congrégation devant le rocher, et il leur dit: Écoutez, rebelles! Vous ferons-nous sortir de l’eau de ce rocher?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Et Moïse leva sa main, et frappa le rocher de sa verge, deux fois; et il en sortit des eaux en abondance, et l’assemblée but, et leurs bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Et l’ Éternel dit à Moïse et à Aaron: Parce que vous ne m’avez pas cru, pour me sanctifier aux yeux des fils d’Israël, à cause de cela vous n’introduirez pas cette congrégation dans le pays que je leur donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Ce sont là les eaux de Meriba, où les fils d’Israël contestèrent avec l’ Éternel; et il se sanctifia en eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, '*Et Moïse envoya de Kadès des messagers au roi d’Édom: Ainsi dit ton frère, Israël: Tu sais toute la fatigue qui nous a atteints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Nos pères descendirent en Égypte, et nous avons habité en Égypte longtemps, et les Égyptiens nous ont maltraités, nous et nos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Et nous avons crié à l’ Éternel, et il a entendu notre voix, et il a envoyé un ange, et nous a fait sortir d’Égypte. Et voici, nous sommes à Kadès, ville à l’extrémité de tes limites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Je te prie, que nous passions par ton pays; nous ne passerons pas par les champs, ni par les vignes, et nous ne boirons pas de l’eau des puits; nous marcherons par le chemin du roi, nous ne nous détournerons ni à droite ni à gauche, jusqu’à ce que nous ayons passé tes limites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Et Édom lui dit: Tu ne passeras pas chez moi, de peur que je ne sorte à ta rencontre avec l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Et les fils d’Israël lui dirent: Nous monterons par le chemin battu; et si nous buvons de tes eaux, moi et mon bétail, j’en donnerai le prix; seulement, sans autre chose, je passerai avec mes pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Et [Édom] dit: Tu ne passeras pas. Et Édom sortit à sa rencontre avec un grand peuple, et à main forte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Et Édom refusa de laisser passer Israël par ses limites; et Israël se détourna d’auprès de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, '*Et ils partirent de Kadès; et les fils d’Israël, toute l’assemblée, vinrent à la montagne de Hor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Et l’ Éternel parla à Moïse et à Aaron, dans la montagne de Hor, sur la limite du pays d’Édom, en disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Aaron sera recueilli vers ses peuples, car il n’entrera pas dans le pays que j’ai donné aux fils d’Israël, parce que vous vous êtes rebellés contre mon commandement aux eaux de Meriba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Prends Aaron et Éléazar, son fils, et fais-les monter sur la montagne de Hor;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'et dépouille Aaron de ses vêtements, et fais-les revêtir à Éléazar, son fils; et Aaron sera recueilli, et mourra là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Et Moïse fit comme l’ Éternel avait commandé; et ils montèrent sur la montagne de Hor aux yeux de toute l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Et Moïse dépouilla Aaron de ses vêtements, et en revêtit Éléazar, son fils; et Aaron mourut là, au sommet de la montagne; puis Moïse et Éléazar descendirent de la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Et toute l’assemblée vit qu’Aaron avait expiré, et toute la maison d’Israël pleura Aaron 30 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, '*Et le Cananéen, le roi d’Arad, qui habitait le midi, entendit qu’Israël venait par le chemin d’Atharim, et il combattit contre Israël, et lui emmena des prisonniers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Et Israël fit un vœu à l’ Éternel, et dit: Si tu livres ce peuple en ma main, je détruirai entièrement ses villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Et l’ Éternel entendit la voix d’Israël, et [lui] livra les Cananéens; et il les détruisit entièrement, ainsi que leurs villes. Et on appela le nom de ce lieu Horma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Et ils partirent de la montagne de Hor, par le chemin de la mer Rouge, pour faire le tour du pays d’Édom; et le cœur du peuple se découragea en chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Et le peuple parla contre Dieu et contre Moïse: Pourquoi nous avez-vous fait monter hors d’Égypte, pour mourir dans le désert? car il n’y a pas de pain, et il n’y a pas d’eau, et notre âme est dégoûtée de ce pain misérable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Et l’ Éternel envoya parmi le peuple les serpents brûlants, et ils mordaient le peuple; et, de ceux d’Israël, il mourut un grand peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Et le peuple vint à Moïse, et dit: Nous avons péché, car nous avons parlé contre l’ Éternel et contre toi; prie l’ Éternel qu’il retire de dessus nous les serpents. Et Moïse pria pour le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Et l’ Éternel dit à Moïse: Fais-toi un [serpent] brûlant, et mets-le sur une perche; et il arrivera que quiconque sera mordu, et le regardera, vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Et Moïse fit un serpent d’airain, et le mit sur une perche; et il arrivait que, lorsqu’un serpent avait mordu un homme, et qu’il regardait le serpent d’airain, il vivait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Et les fils d’Israël partirent, et campèrent à Oboth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Et ils partirent d’Oboth, et campèrent à Ijim-Abarim, dans le désert qui est vis-à-vis de Moab, vers le soleil levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'De là ils partirent, et campèrent dans la vallée de Zéred.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'De là ils partirent, et campèrent de l’autre côté de l’Arnon, qui est dans le désert, sortant des limites des Amoréens; car l’Arnon est la frontière de Moab, entre Moab et l’Amoréen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'C’est pourquoi il est dit dans le livre des guerres de l’ Éternel: Vaheb en Supha, et les rivières de l’Arnon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Et le cours des rivières, qui tend vers l’habitation d’Ar, Et qui s’appuie sur la frontière de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Et de là [ils vinrent] à Beër. C’est là le puits au sujet duquel l’ Éternel dit à Moïse: Assemble le peuple, et je leur donnerai de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Alors Israël chanta ce cantique: Monte, puits! Chantez-lui:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Puits, que des princes ont creusé, que les hommes nobles du peuple, avec le législateur, ont creusé avec leurs bâtons! Et du désert, [ils vinrent] à Matthana;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'et de Matthana, à Nakhaliel; et de Nakhaliel, à Bamoth;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'et de Bamoth, à la vallée qui est dans les champs de Moab, au sommet du Pisga, qui se montre au-dessus de la surface du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Et Israël envoya des messagers à Sihon, roi des Amoréens, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Je passerai par ton pays: nous ne nous détournerons pas dans les champs, ni dans les vignes; nous ne boirons pas de l’eau des puits; nous marcherons par le chemin du roi, jusqu’à ce que nous ayons passé tes limites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Mais Sihon ne permit pas à Israël de passer par ses limites; et Sihon rassembla tout son peuple, et sortit à la rencontre d’Israël, au désert, et vint à Jahats et combattit contre Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Et Israël le frappa par le tranchant de l’épée, et prit possession de son pays depuis l’Arnon jusqu’au Jabbok, jusqu’aux fils d’Ammon; car la frontière des fils d’Ammon était forte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Et Israël prit toutes ces villes, et Israël habita dans toutes les villes des Amoréens, à Hesbon et dans tous les villages de son ressort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Car Hesbon était la ville de Sihon, roi des Amoréens; et il avait fait la guerre au précédent roi de Moab, et avait pris de sa main tout son pays jusqu’à l’Arnon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'C’est pourquoi les poètes disent: Venez à Hesbon; que la ville de Sihon soit bâtie et établie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Car un feu est sorti de Hesbon, une flamme, de la cité de Sihon; il a dévoré Ar de Moab, les seigneurs des hauts lieux de l’Arnon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Malheur à toi, Moab! tu es perdu, peuple de Kemosh! Il a livré ses fils qui avaient échappé, et ses filles, à la captivité, à Sihon, roi des Amoréens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Nous avons tiré contre eux; Hesbon est périe jusqu’à Dibon; et nous avons dévasté jusqu’à Nophakh,... avec du feu jusqu’à Médeba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Et Israël habita dans le pays des Amoréens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Et Moïse envoya pour explorer Jahzer; et ils prirent les villages de son ressort, et en dépossédèrent les Amoréens qui y étaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Puis ils se tournèrent et montèrent par le chemin de Basan; et Og, le roi de Basan, sortit à leur rencontre, lui et tout son peuple, à Édréhi, pour livrer bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Et l’ Éternel dit à Moïse: Ne le crains pas, car je l’ai livré en ta main, lui et tout son peuple, et son pays; et tu lui feras comme tu as fait à Sihon, roi des Amoréens, qui habitait à Hesbon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Et ils le frappèrent, lui et ses fils, et tout son peuple, jusqu’à ne pas lui laisser un réchappé; et ils prirent possession de son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, '*Et les fils d’Israël partirent, et campèrent dans les plaines de Moab, de l’autre côté du Jourdain de Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Et Balak, fils de Tsippor, vit tout ce qu’Israël avait fait aux Amoréens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'et Moab eut une fort grande peur du peuple, car il était nombreux; et Moab fut dans l’effroi à cause des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Et Moab dit aux anciens de Madian: Maintenant, cette multitude broutera tout ce qui est autour de nous, comme le bœuf broute l’herbe des champs. Or Balak, fils de Tsippor, était roi de Moab en ce temps-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Et il envoya des messagers à Balaam, fils de Béor, à Pethor, qui est sur le fleuve, dans le pays des fils de son peuple, pour l’appeler, disant: Voici, un peuple est sorti d’Égypte; voici, il couvre le dessus du pays, et il habite vis-à-vis de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Et maintenant, viens, je te prie, maudis-moi ce peuple, car il est plus fort que moi: peut-être pourrai-je le frapper, et le chasserai-je du pays; car je sais que celui que tu bénis est béni, et que celui que tu maudis est maudit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Et les anciens de Moab et les anciens de Madian s’en allèrent, ayant dans leurs mains le salaire de la divination; et ils vinrent à Balaam et lui dirent les paroles de Balak.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Et il leur dit: Passez ici la nuit, et je vous rapporterai la parole selon que l’ Éternel m’aura parlé. Et les seigneurs de Moab demeurèrent avec Balaam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Et Dieu vint à Balaam, et dit: Qui sont ces hommes [que tu as] chez toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Et Balaam dit à Dieu: Balak, fils de Tsippor, roi de Moab, a envoyé vers moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Voici, un peuple est sorti d’Égypte, et il couvre le dessus du pays; viens maintenant, maudis-le-moi: peut-être pourrai-je combattre contre lui, et le chasserai-je.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Et Dieu dit à Balaam: Tu n’iras pas avec eux; tu ne maudiras pas le peuple, car il est béni.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Et Balaam se leva le matin, et dit aux seigneurs de Balak: Allez dans votre pays; car l’ Éternel refuse de me laisser aller avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Et les seigneurs de Moab se levèrent, et s’en allèrent vers Balak, et dirent: Balaam a refusé de venir avec nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Et Balak envoya encore des seigneurs, plus nombreux et plus considérables que ceux-là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'et ils vinrent à Balaam, et lui dirent: Ainsi a dit Balak, fils de Tsippor: Je te prie, ne te laisse pas empêcher de venir vers moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'car je te comblerai d’honneurs, et tout ce que tu me diras, je le ferai; viens donc, je te prie, maudis-moi ce peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Et Balaam répondit et dit aux serviteurs de Balak: Quand Balak me donnerait plein sa maison d’argent et d’or, je ne pourrais transgresser le commandement de l’ Éternel, mon Dieu, pour faire une chose petite ou grande;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'et maintenant, je vous prie, demeurez ici, vous aussi, cette nuit, et je saurai ce que l’ Éternel aura de plus à me dire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Et Dieu vint la nuit à Balaam, et lui dit: Si ces hommes sont venus pour t’appeler, lève-toi, va avec eux; seulement, la parole que je te dirai, tu la feras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Et Balaam se leva le matin, et sella son ânesse, et s’en alla avec les seigneurs de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Mais la colère de Dieu s’embrasa parce qu’il s’en allait; et l’Ange de l’ Éternel se plaça sur le chemin pour s’opposer à lui. Et il était monté sur son ânesse, et ses deux jeunes hommes étaient avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Et l’ânesse vit l’Ange de l’ Éternel se tenant dans le chemin, son épée nue dans sa main; et l’ânesse se détourna du chemin et alla dans les champs; et Balaam frappa l’ânesse pour la faire retourner dans le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Et l’Ange de l’ Éternel se tint dans un chemin creux, dans les vignes; il y avait un mur d’un côté et un mur de l’autre côté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Et l’ânesse vit l’Ange de l’ Éternel, et elle se serra contre la muraille, et serra le pied de Balaam contre la muraille; et il la frappa de nouveau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Et l’Ange de l’ Éternel passa plus loin, et se tint dans un lieu étroit où il n’y avait point de chemin pour se détourner à droite ou à gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Et l’ânesse vit l’Ange de l’ Éternel, et elle se coucha sous Balaam; et la colère de Balaam s’embrasa, et il frappa l’ânesse avec le bâton.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Et l’ Éternel ouvrit la bouche de l’ânesse, et elle dit à Balaam: Que t’ai-je fait, que tu m’aies frappée ces trois fois?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Et Balaam dit à l’ânesse: Parce que tu t’es jouée de moi. Que n’ai-je une épée dans ma main; certes je te tuerais maintenant!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Et l’ânesse dit à Balaam: Ne suis-je pas ton ânesse, sur laquelle tu montes depuis que je suis à toi jusqu’à ce jour? Ai-je coutume de te faire ainsi? Et il dit: Non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Et l’ Éternel ouvrit les yeux de Balaam, et il vit l’Ange de l’ Éternel qui se tenait sur le chemin, son épée nue dans sa main; et il s’inclina et se prosterna sur sa face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Et l’Ange de l’ Éternel lui dit: Pourquoi as-tu frappé ton ânesse ces trois fois? Voici, moi, je suis sorti pour m’opposer à toi, car ton chemin est pervers devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Et l’ânesse m’a vu et s’est détournée devant moi ces trois fois; si elle ne s’était pas détournée de devant moi, je t’aurais maintenant tué; et elle, je l’aurais laissée en vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Et Balaam dit à l’Ange de l’ Éternel: J’ai péché, car je ne savais pas que tu t’étais placé à ma rencontre dans le chemin; et maintenant, si cela est mauvais à tes yeux, je m’en retournerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Et l’Ange de l’ Éternel dit à Balaam: Va avec les hommes; mais seulement tu ne diras que la parole que je te dirai. Et Balaam s’en alla avec les seigneurs de Balak.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Et Balak entendit que Balaam venait, et il sortit à sa rencontre, jusqu’à la ville de Moab, sur la frontière de l’Arnon qui est à l’extrémité de la frontière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Et Balak dit à Balaam: N’ai-je pas envoyé vers toi avec instance pour t’appeler? Pourquoi n’es-tu pas venu vers moi? Vraiment, ne puis-je pas te donner des honneurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Et Balaam dit à Balak: Voici, je suis venu vers toi; maintenant, puis -je dire quoi que ce soit? La parole que Dieu m’aura mise dans la bouche, je la dirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Et Balaam alla avec Balak, et ils vinrent à Kiriath-Hutsoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Et Balak sacrifia du gros et du menu bétail, et il en envoya à Balaam et aux seigneurs qui étaient avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Et il arriva, le matin, que Balak prit Balaam et le fit monter aux hauts lieux de Baal, et de là il vit l’extrémité du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Et Balaam dit à Balak: Bâtis-moi ici sept autels, et prépare-moi ici sept taureaux et sept béliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Et Balak fit comme Balaam avait dit; et Balak et Balaam offrirent un taureau et un bélier sur [chaque] autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Et Balaam dit à Balak: Tiens-toi auprès de ton offrande, et je m’en irai; peut-être que l’ Éternel viendra à ma rencontre, et ce qu’il m’aura fait voir je te le rapporterai. Et il s’en alla sur une hauteur découverte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Et Dieu rencontra Balaam, et [Balaam] lui dit: J’ai préparé sept autels, et j’ai offert un taureau et un bélier sur [chaque] autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Et l’ Éternel mit une parole dans la bouche de Balaam, et dit: Retourne vers Balak, et tu parleras ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Et il s’en retourna vers lui; et voici, il se tenait auprès de son offrande, lui et tous les seigneurs de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Et [Balaam] proféra son discours sentencieux, et dit: Balak, roi de Moab, m’a amené d’Aram, des montagnes d’orient: Viens, maudis-moi Jacob! viens, appelle l’exécration sur Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Comment maudirai-je ce que ✶Dieu n’a pas maudit? Et comment appellerai-je l’exécration sur celui que l’ Éternel n’a pas en exécration?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Car du sommet des rochers je le vois, et des hauteurs je le contemple. Voici, c’est un peuple qui habitera seul, et il ne sera pas compté parmi les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Qui est-ce qui comptera la poussière de Jacob, et le nombre de la quatrième partie d’Israël? Que mon âme meure de la mort des hommes droits, et que ma fin soit comme la leur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Et Balak dit à Balaam: Que m’as-tu fait? Je t’avais pris pour maudire mes ennemis, et voici, tu les as bénis expressément.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Et il répondit et dit: Ne prendrai-je pas garde de dire ce que l’ Éternel aura mis dans ma bouche?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Et Balak lui dit: Viens, je te prie, avec moi, dans un autre lieu d’où tu puisses le voir; tu n’en verras que l’extrémité, et tu ne le verras pas tout entier; et maudis-le-moi de là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Et il le conduisit au champ de Tsophim, au sommet du Pisga, et il bâtit sept autels, et offrit un taureau et un bélier sur [chaque] autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Et [Balaam] dit à Balak: Tiens-toi ici auprès de ton offrande, et moi, j’irai à la rencontre, là...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Et l’ Éternel vint à la rencontre de Balaam, et mit une parole dans sa bouche, et dit: Retourne vers Balak, et tu parleras ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Et il vint à lui, et voici, il se tenait auprès de son offrande, et les seigneurs de Moab avec lui. Et Balak lui dit: Qu’a dit l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Et il proféra son discours sentencieux, et dit: Lève-toi, Balak, et écoute! Prête-moi l’oreille, fils de Tsippor!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, '✶Dieu n’est pas un homme, pour mentir, ni un fils d’homme, pour se repentir: aura-t-il dit, et ne fera-t-il pas? aura-t-il parlé, et ne l’accomplira-t-il pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Voici, j’ai reçu [mission] de bénir; il a béni et je ne le révoquerai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Il n’a pas aperçu d’iniquité en Jacob, ni n’a vu d’injustice en Israël; l’ Éternel, son Dieu, est avec lui, et un chant de triomphe royal est au milieu de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, '✶Dieu les a fait sortir d’Égypte; il a comme la force des buffles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Car il n’y a pas d’enchantement contre Jacob, ni de divination contre Israël. Selon ce temps il sera dit de Jacob et d’Israël: Qu’est-ce que ✶Dieu a fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Voici, le peuple se lèvera comme une lionne, et se dressera comme un lion; il ne se couchera pas qu’il n’ait mangé la proie, et bu le sang des tués.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Et Balak dit à Balaam: Ne le maudis donc pas; mais du moins ne le bénis pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Et Balaam répondit et dit à Balak: Ne t’ai-je pas parlé, disant: Tout ce que l’ Éternel dira, je le ferai?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Et Balak dit à Balaam: Viens donc, je te conduirai à un autre lieu: peut-être sera-t-il bon aux yeux de Dieu que tu me le maudisses de là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Et Balak conduisit Balaam au sommet du Péor, qui se montre au-dessus de la surface du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Et Balaam dit à Balak: Bâtis-moi ici sept autels, et prépare-moi ici sept taureaux et sept béliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Et Balak fit comme Balaam avait dit; et il offrit un taureau et un bélier sur [chaque] autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Et Balaam vit qu’il était bon aux yeux de l’ Éternel de bénir Israël, et il n’alla pas, comme d’autres fois, à la rencontre des enchantements, mais il tourna sa face vers le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Et Balaam leva ses yeux et vit Israël habitant dans ses tentes selon ses tribus; et l’Esprit de Dieu fut sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Et il proféra son discours sentencieux, et dit: Balaam, fils de Béor, dit, et l’homme qui a l’œil ouvert, dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Celui qui entend les paroles de ✶Dieu, qui voit la vision du Tout-puissant, qui tombe et qui a les yeux ouverts, dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Que tes tentes sont belles, ô Jacob! et tes demeures, ô Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Comme des vallées elles s’étendent, comme des jardins auprès d’un fleuve, comme des arbres d’aloès que l’ Éternel a plantés, comme des cèdres auprès des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'L’eau coulera de ses seaux; et sa semence sera au milieu de grandes eaux; Et son roi sera élevé au-dessus d’Agag, et son royaume sera haut élevé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, '✶Dieu l’a fait sortir d’Égypte; il a comme la force des buffles; il dévorera les nations, ses ennemis; il cassera leurs os, et les frappera de ses flèches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Il s’est courbé, il s’est couché comme un lion, et comme une lionne: qui le fera lever? Bénis sont ceux qui te bénissent, et maudits sont ceux qui te maudissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Alors la colère de Balak s’embrasa contre Balaam, et il frappa des mains; et Balak dit à Balaam: C’est pour maudire mes ennemis que je t’ai appelé, et voici, tu les as bénis expressément ces trois fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Et maintenant, fuis en ton lieu. J’avais dit que je te comblerais d’honneurs; et voici, l’ Éternel t’a empêché d’en recevoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Et Balaam dit à Balak: N’ai-je pas aussi parlé à tes messagers que tu as envoyés vers moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Quand Balak me donnerait plein sa maison d’argent et d’or, je ne pourrais transgresser le commandement de l’ Éternel pour faire de mon propre mouvement du bien ou du mal; ce que l’ Éternel dira, je le dirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Et maintenant, voici, je m’en vais vers mon peuple; viens, je t’avertirai de ce que ce peuple fera à ton peuple à la fin des jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Et il proféra son discours sentencieux, et dit: Balaam, fils de Béor, dit, et l’homme qui a l’œil ouvert, dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Celui qui entend les paroles de ✶Dieu, et qui connaît la connaissance du Très-haut, qui voit la vision du Tout-puissant, qui tombe et qui a les yeux ouverts, dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Je le verrai, mais pas maintenant; je le regarderai, mais pas de près. Une étoile surgira de Jacob, et un sceptre s’élèvera d’Israël, et transpercera les coins de Moab, et détruira tous les fils de tumulte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Et Édom sera une possession, et Séhir sera une possession,... [eux], ses ennemis; et Israël agira avec puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Et celui qui sortira de Jacob dominera, et il fera périr de la ville le résidu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Et il vit Amalek, et proféra son discours sentencieux, et dit: Amalek était la première des nations; et sa fin sera la destruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Et il vit le Kénien, et il proféra son discours sentencieux, et dit: Forte est ta demeure, et tu as placé ton nid dans le rocher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Toutefois le Kénien doit être consumé, jusqu’à ce qu’Assur t’emmène captif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Et il proféra son discours sentencieux, et dit: Malheur! Qui vivra, quand ✶Dieu fera ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Et des navires viendront de la côte de Kittim, et affligeront Assur, et affligeront Héber, et lui aussi ira à la destruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Et Balaam se leva, et s’en alla, et s’en retourna en son lieu; et Balak aussi s’en alla son chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, '*Et Israël habitait en Sittim; et le peuple commença à commettre fornication avec les filles de Moab;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'et elles invitèrent le peuple aux sacrifices de leurs dieux, et le peuple mangea, et se prosterna devant leurs dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Et Israël s’attacha à Baal-Péor; et la colère de l’ Éternel s’embrasa contre Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Et l’ Éternel dit à Moïse: Prends tous les chefs du peuple et fais-les pendre devant l’ Éternel, à la face du soleil, afin que l’ardeur de la colère de l’ Éternel se détourne d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Et Moïse dit aux juges d’Israël: Que chacun de vous tue ses hommes qui se sont attachés à Baal-Péor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Et voici, un homme des fils d’Israël vint, et amena vers ses frères une Madianite, sous les yeux de Moïse et sous les yeux de toute l’assemblée des fils d’Israël qui pleuraient à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Et Phinées, fils d’Éléazar, fils d’Aaron, le sacrificateur, le vit, et il se leva du milieu de l’assemblée, et prit une pique dans sa main,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'et entra après l’homme d’Israël dans l’intérieur de la tente, et les transperça tous deux, l’homme d’Israël, et la femme, par le bas-ventre; et la plaie s’arrêta de dessus les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Et ceux qui moururent de la plaie furent 24 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Phinées, fils d’Éléazar, fils d’Aaron, le sacrificateur, a détourné mon courroux de dessus les fils d’Israël, étant jaloux de ma jalousie au milieu d’eux, de sorte que je ne consume pas les fils d’Israël dans ma jalousie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'C’est pourquoi dis: Voici, je lui donne mon alliance de paix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'et ce sera une alliance de sacrificature perpétuelle, pour lui et pour sa semence après lui, parce qu’il a été jaloux pour son Dieu, et a fait propitiation pour les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Et le nom de l’homme d’Israël frappé, qui fut frappé avec la Madianite, était Zimri, fils de Salu, prince d’une maison de père des Siméonites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Et le nom de la femme madianite qui fut frappée, était Cozbi, fille de Tsur, chef de peuplade d’une maison de père en Madian.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Serrez de près les Madianites, et frappez-les;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'car eux vous ont serrés de près par leurs ruses, par lesquelles ils vous ont séduits dans l’affaire de Péor, et dans l’affaire de Cozbi, fille d’un prince de Madian, leur sœur, qui a été frappée le jour de la plaie, à cause de l’affaire de Péor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 19, '*Et il arriva, après la plaie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'que l’ Éternel parla à Moïse et à Éléazar, fils d’Aaron, le sacrificateur, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Relevez la somme de toute l’assemblée des fils d’Israël, depuis l’âge de 20 ans et au-dessus, selon leurs maisons de pères, tous ceux qui sont propres au service militaire en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Et Moïse, et Éléazar, le sacrificateur, leur parlèrent dans les plaines de Moab, près du Jourdain de Jéricho, disant:...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Depuis l’âge de 20 ans et au-dessus, comme l’ Éternel le commanda à Moïse et aux fils d’Israël, qui sortirent du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, le premier-né d’Israël. Les fils de Ruben: [de] Hénoc, la famille des Hénokites; de Pallu, la famille des Palluites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'de Hetsron, la famille des Hetsronites; de Carmi, la famille des Carmites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, '– Ce sont là les familles des Rubénites; et leurs dénombrés furent 43 730.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, '– Et les fils de Pallu: Éliab;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'et les fils d’Éliab: Nemuel, et Dathan, et Abiram. C’est ce Dathan et cet Abiram, des principaux de l’assemblée, qui se soulevèrent contre Moïse et contre Aaron dans l’assemblée de Coré, lorsqu’ils se soulevèrent contre l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'et la terre ouvrit sa bouche et les engloutit, ainsi que Coré, lorsque l’assemblée mourut, quand le feu dévora les 250 hommes; et ils furent pour signe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Mais les fils de Coré ne moururent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Les fils de Siméon, selon leurs familles: de Nemuel, la famille des Nemuélites; de Jamin, la famille des Jaminites; de Jakin, la famille des Jakinites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'de Zérakh, la famille des Zarkhites; de Saül, la famille des Saülites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, '– Ce sont là les familles des Siméonites, 22 200.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Les fils de Gad, selon leurs familles: de Tsephon, la famille des Tsephonites; de Haggui, la famille des Hagguites; de Shuni, la famille des Shunites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'd’Ozni, la famille des Oznites; d’Éri, la famille des Érites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'd’Arod, la famille des Arodites; d’Areéli, la famille des Areélites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, '– Ce sont là les familles des fils de Gad, selon leur dénombrement, 40 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Les fils de Juda: Er et Onan; et Er et Onan moururent dans le pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Et les fils de Juda, selon leurs familles: de Shéla, la famille des Shélanites; de Pérets, la famille des Partsites; de Zérakh, la famille des Zarkhites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Et les fils de Pérets: de Hetsron, la famille des Hetsronites; de Hamul, la famille des Hamulites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, '– Ce sont là les familles de Juda, selon leur dénombrement, 76 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Les fils d’Issacar, selon leurs familles: [de] Thola, la famille des Tholaïtes; de Puva, la famille des Punites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'de Jashub, la famille des Jashubites; de Shimron, la famille des Shimronites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, '– Ce sont là les familles d’Issacar, selon leur dénombrement, 64 300.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Les fils de Zabulon, selon leurs familles: de Séred, la famille des Sardites; d’Élon, la famille des Élonites; de Jakhleël, la famille des Jakhleélites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, '– Ce sont là les familles des Zabulonites, selon leur dénombrement, 60 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Les fils de Joseph, selon leurs familles, Manassé et Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, '– Les fils de Manassé: de Makir, la famille des Makirites; et Makir engendra Galaad; de Galaad, la famille des Galaadites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, '– Ce sont ici les fils de Galaad: [d’]Ihézer, la famille des Ihézrites; de Hélek, la famille des Helkites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'd’Asriel, la famille des Asriélites; [de] Sichem, la famille des Sichémites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, '[de] Shemida, la famille des Shemidaïtes; [de] Hépher, la famille des Héphrites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, '– Et Tselophkhad, fils de Hépher, n’eut pas de fils, mais des filles; et les noms des filles de Tselophkhad étaient: Makhla, et Noa, Hogla, Milca, et Thirtsa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, '– Ce sont là les familles de Manassé; et leurs dénombrés, 52 700.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Ce sont ici les fils d’Éphraïm, selon leurs familles: de Shuthélakh, la famille des Shuthalkhites; de Béker, la famille des Bacrites; de Thakhan, la famille des Thakhanites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, '– Et ce sont ici les fils de Shuthélakh: d’Éran, la famille des Éranites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, '– Ce sont là les familles des fils d’Éphraïm, selon leur dénombrement, 32 500. – Ce sont là les fils de Joseph, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Les fils de Benjamin, selon leurs familles: de Béla, la famille des Balites; d’Ashbel, la famille des Ashbélites; d’Akhiram, la famille des Akhiramites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'de Shephupham, la famille des Shuphamites; de Hupham, la famille des Huphamites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, '– Et les fils de Béla furent Ard et Naaman: [d’Ard], la famille des Ardites; de Naaman, la famille des Naamites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, '– Ce sont là les fils de Benjamin, selon leurs familles; et leurs dénombrés, 45 600.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Ce sont ici les fils de Dan, selon leurs familles: de Shukham, la famille des Shukhamites. Ce sont là les familles de Dan, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, '– Toutes les familles des Shukhamites, selon leur dénombrement, 64 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Les fils d’Aser, selon leurs familles: de Jimna, la famille des Jimna; de Jishvi, la famille des Jishvites; de Beriha, la famille des Berihites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, '– Des fils de Beriha: de Héber, la famille des Hébrites; de Malkiel, la famille des Malkiélites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, '– Et le nom de la fille d’Aser était Sérakh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Ce sont là les familles des fils d’Aser, selon leur dénombrement, 53 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Les fils de Nephthali, selon leurs familles: de Jahtseël, la famille des Jahtseélites; de Guni, la famille des Gunites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'de Jétser, la famille des Jitsrites; de Shillem, la famille des Shillémites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, '– Ce sont là les familles de Nephthali, selon leurs familles; et leurs dénombrés, 45 400.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Ce sont là les dénombrés des fils d’Israël, 601 730.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Le pays sera partagé à ceux-ci en héritage, selon le nombre des noms.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'À ceux qui sont nombreux, tu augmenteras l’héritage; et à ceux qui sont peu nombreux, tu diminueras l’héritage: tu donneras à chacun son héritage en proportion de ses dénombrés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Seulement, le pays sera partagé par le sort; ils l’hériteront selon les noms des tribus de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'C’est selon la décision du sort que leur héritage sera partagé, qu’ils soient en grand nombre ou en petit nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Et ce sont ici les dénombrés de Lévi, selon leurs familles: de Guershon, la famille des Guershonites; de Kehath, la famille des Kehathites; de Merari, la famille des Merarites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Ce sont ici les familles de Lévi: la famille des Libnites, la famille des Hébronites, la famille des Makhlites, la famille des Mushites, la famille des Corites. – Et Kehath engendra Amram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Et le nom de la femme d’Amram était Jokébed, fille de Lévi, qui naquit à Lévi en Égypte; et elle enfanta à Amram, Aaron et Moïse, et Marie, leur sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Et à Aaron naquirent Nadab, et Abihu, Éléazar, et Ithamar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Et Nadab et Abihu moururent comme ils présentaient du feu étranger devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, '– Et les dénombrés des Lévites furent 23 000, tous les mâles, depuis l’âge d’un mois et au-dessus; car ils ne furent pas dénombrés avec les fils d’Israël, parce qu’on ne leur donna pas d’héritage parmi les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Ce sont là ceux qui furent dénombrés par Moïse et Éléazar, le sacrificateur, qui dénombrèrent les fils d’Israël dans les plaines de Moab, près du Jourdain de Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Et parmi ceux-là, il n’y en eut aucun de ceux qui avaient été dénombrés par Moïse et Aaron, le sacrificateur, qui dénombrèrent les fils d’Israël dans le désert de Sinaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'car l’ Éternel avait dit d’eux: Ils mourront certainement dans le désert; et il n’en resta pas un homme, excepté Caleb, fils de Jephunné, et Josué, fils de Nun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, '*Et les filles de Tselophkhad, fils de Hépher, fils de Galaad, fils de Makir, fils de Manassé, des familles de Manassé, fils de Joseph, s’approchèrent (et ce sont ici les noms de ses filles: Makhla, Noa, et Hogla, et Milca, et Thirtsa);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'et elles se tinrent devant Moïse et devant Éléazar, le sacrificateur, et devant les princes et toute l’assemblée, à l’entrée de la tente d’assignation, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Notre père est mort dans le désert, et il n’était pas dans l’assemblée de ceux qui s’ameutèrent contre l’ Éternel, dans l’assemblée de Coré; mais il est mort dans son péché, et il n’a pas eu de fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Pourquoi le nom de notre père serait-il retranché du milieu de sa famille parce qu’il n’a pas de fils? Donne-nous une possession au milieu des frères de notre père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Et Moïse apporta leur cause devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Les filles de Tselophkhad ont bien parlé. Tu leur donneras une possession d’héritage au milieu des frères de leur père, et tu feras passer à elles l’héritage de leur père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Et tu parleras aux fils d’Israël, disant: Quand un homme mourra sans avoir de fils, vous ferez passer son héritage à sa fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Et s’il n’a pas de fille, vous donnerez son héritage à ses frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Et s’il n’a pas de frères, vous donnerez son héritage aux frères de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Et s’il n’y a pas de frères de son père, vous donnerez son héritage à son parent qui, de sa famille, lui est le plus proche, et il le possédera. Et ce sera pour les fils d’Israël un statut de droit, comme l’ Éternel a commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, '*Et l’ Éternel dit à Moïse: Monte sur cette montagne d’Abarim, et regarde le pays que j’ai donné aux fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Tu le regarderas, et tu seras recueilli vers tes peuples, toi aussi, comme Aaron, ton frère, a été recueilli;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'parce que, au désert de Tsin, lors de la contestation de l’assemblée, vous avez été rebelles à mon commandement, quand vous auriez dû me sanctifier à leurs yeux à l’occasion des eaux: ce sont là les eaux de Meriba à Kadès, dans le désert de Tsin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Et Moïse parla à l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Que l’ Éternel, le Dieu des esprits de toute chair, établisse sur l’assemblée un homme');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'qui sorte devant eux et entre devant eux, et qui les fasse sortir et les fasse entrer; et que l’assemblée de l’ Éternel ne soit pas comme un troupeau qui n’a pas de berger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Et l’ Éternel dit à Moïse: Prends Josué, fils de Nun, un homme en qui est l’Esprit, et pose ta main sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Et tu le feras se tenir devant Éléazar, le sacrificateur, et devant toute l’assemblée, et tu lui donneras des ordres devant leurs yeux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'et tu mettras sur lui de ta gloire, afin que toute l’assemblée des fils d’Israël l’écoute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Et il se tiendra devant Éléazar, le sacrificateur, qui interrogera pour lui les jugements d’urim devant l’ Éternel: à sa parole ils sortiront, et à sa parole ils entreront, lui et tous les fils d’Israël avec lui, toute l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Et Moïse fit comme l’ Éternel lui avait commandé; et il prit Josué et le fit se tenir devant Éléazar, le sacrificateur, et devant toute l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Et il posa ses mains sur lui, et lui donna des ordres, comme l’ Éternel l’avait dit par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Commande aux fils d’Israël, et dis-leur: Vous prendrez garde à me présenter, au temps fixé, mon offrande, mon pain, pour mes sacrifices par feu, qui me sont une odeur agréable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Et tu leur diras: C’est ici le sacrifice fait par feu que vous présenterez à l’ Éternel: deux agneaux âgés d’un an, sans défaut, chaque jour, en holocauste continuel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'tu offriras l’un des agneaux le matin, et le second agneau, tu l’offriras entre les deux soirs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'et le dixième d’un épha de fleur de farine, pour l’offrande de gâteau, pétrie avec un quart de hin d’huile broyée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, '[c’est] l’holocauste continuel qui a été offert en la montagne de Sinaï, en odeur agréable, un sacrifice par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Et sa libation sera d’un quart de hin pour un agneau; tu verseras dans le lieu saint la libation de boisson forte à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Et tu offriras le second agneau entre les deux soirs; tu l’offriras avec la même offrande de gâteau qu’au matin et la même libation, en sacrifice par feu, d’odeur agréable à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Et le jour du sabbat, [vous offrirez] deux agneaux âgés d’un an, sans défaut, et deux dixièmes de fleur de farine pétrie à l’huile, comme offrande de gâteau, et sa libation:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, '[c’est] l’holocauste du sabbat pour chaque sabbat, outre l’holocauste continuel et sa libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Et au commencement de vos mois, vous présenterez en holocauste à l’ Éternel deux jeunes taureaux, et un bélier, [et] sept agneaux âgés d’un an, sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'et trois dixièmes de fleur de farine pétrie à l’huile, comme offrande de gâteau, pour un taureau; et deux dixièmes de fleur de farine pétrie à l’huile, comme offrande de gâteau, pour le bélier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'et un dixième de fleur de farine pétrie à l’huile, comme offrande de gâteau, pour un agneau: [c’est] un holocauste d’odeur agréable, un sacrifice par feu à l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'et leurs libations seront d’un demi-hin de vin pour un taureau, et d’un tiers de hin pour le bélier, et d’un quart de hin pour un agneau. C’est l’holocauste mensuel, pour [tous] les mois de l’année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Et on offrira à l’ Éternel un bouc en sacrifice pour le péché, outre l’holocauste continuel et sa libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Et au premier mois, le quatorzième jour du mois, est la Pâque à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Et le quinzième jour de ce mois, est la fête: on mangera pendant sept jours des pains sans levain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Le premier jour, il y aura une sainte convocation; vous ne ferez aucune œuvre de service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Et vous présenterez un sacrifice fait par feu, en holocauste à l’ Éternel: deux jeunes taureaux, et un bélier, et sept agneaux âgés d’un an; vous les prendrez sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'et leur offrande de gâteau sera de fleur de farine pétrie à l’huile: vous en offrirez trois dixièmes pour un taureau, et deux dixièmes pour le bélier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'tu en offriras un dixième par agneau, pour les sept agneaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'et un bouc en sacrifice pour le péché, afin de faire propitiation pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Vous offrirez ces choses-là, outre l’holocauste du matin, qui est l’holocauste continuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Vous offrirez ces choses-là chaque jour, pendant sept jours, le pain du sacrifice par feu, d’odeur agréable à l’ Éternel; on les offrira, outre l’holocauste continuel et sa libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Et au septième jour, vous aurez une sainte convocation; vous ne ferez aucune œuvre de service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Et le jour des premiers fruits, quand vous présenterez une offrande nouvelle de gâteau à l’ Éternel, en votre [fête] des semaines, vous aurez une sainte convocation; vous ne ferez aucune œuvre de service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Et vous présenterez un holocauste, en odeur agréable à l’ Éternel, deux jeunes taureaux, un bélier, sept agneaux âgés d’un an;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'et leur offrande de gâteau de fleur de farine pétrie à l’huile, trois dixièmes pour un taureau, deux dixièmes pour le bélier,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'un dixième par agneau, pour les sept agneaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, '[et] un bouc, afin de faire propitiation pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Vous les offrirez outre l’holocauste continuel et son gâteau (vous les prendrez sans défaut), et leurs libations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Et au septième mois, le premier [jour] du mois, vous aurez une sainte convocation; vous ne ferez aucune œuvre de service; ce sera pour vous le jour du son éclatant [des trompettes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Et vous offrirez un holocauste en odeur agréable à l’ Éternel, un jeune taureau, un bélier, sept agneaux âgés d’un an, sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'et leur offrande de gâteau de fleur de farine pétrie à l’huile, trois dixièmes pour le taureau, deux dixièmes pour le bélier,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'et un dixième pour un agneau, pour les sept agneaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'et un bouc en sacrifice pour le péché, afin de faire propitiation pour vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, '– outre l’holocauste du mois, et son gâteau, et l’holocauste continuel et son gâteau, et leurs libations, selon leur ordonnance, en odeur agréable, un sacrifice par feu à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Et le dixième [jour] de ce septième mois, vous aurez une sainte convocation, et vous affligerez vos âmes; vous ne ferez aucune œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Et vous présenterez à l’ Éternel un holocauste d’odeur agréable, un jeune taureau, un bélier, sept agneaux âgés d’un an (vous les prendrez sans défaut);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'et leur offrande de gâteau de fleur de farine pétrie à l’huile, trois dixièmes pour le taureau, deux dixièmes pour le bélier,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'un dixième par agneau, pour les sept agneaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, '[et] un bouc en sacrifice pour le péché, – outre le sacrifice de péché des propitiations, et l’holocauste continuel et son gâteau, et leurs libations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Et le quinzième jour du septième mois, vous aurez une sainte convocation; vous ne ferez aucune œuvre de service, et vous célébrerez une fête à l’ Éternel pendant sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Et vous présenterez un holocauste, un sacrifice par feu d’odeur agréable à l’ Éternel, 13 jeunes taureaux, deux béliers, 14 agneaux âgés d’un an (ils seront sans défaut);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'et leur offrande de gâteau de fleur de farine pétrie à l’huile, trois dixièmes par taureau, pour les 13 taureaux, deux dixièmes par bélier, pour les deux béliers,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'et un dixième par agneau, pour les 14 agneaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'et un bouc en sacrifice pour le péché, – outre l’holocauste continuel, son gâteau et sa libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Et le second jour, [vous présenterez] douze jeunes taureaux, deux béliers, 14 agneaux âgés d’un an, sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'et leur offrande de gâteau et leurs libations pour les taureaux, pour les béliers, et pour les agneaux, d’après leur nombre, selon l’ordonnance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'et un bouc en sacrifice pour le péché, – outre l’holocauste continuel et son gâteau, et leurs libations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Et le troisième jour, onze taureaux, deux béliers, 14 agneaux âgés d’un an, sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'et leur offrande de gâteau et leurs libations pour les taureaux, pour les béliers, et pour les agneaux, d’après leur nombre, selon l’ordonnance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'et un bouc en sacrifice pour le péché, – outre l’holocauste continuel et son gâteau et sa libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Et le quatrième jour, dix taureaux, deux béliers, 14 agneaux âgés d’un an, sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'leur offrande de gâteau et leurs libations pour les taureaux, pour les béliers, et pour les agneaux, d’après leur nombre, selon l’ordonnance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'et un bouc en sacrifice pour le péché, – outre l’holocauste continuel, son gâteau et sa libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Et le cinquième jour, neuf taureaux, deux béliers, 14 agneaux âgés d’un an, sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'et leur offrande de gâteau et leurs libations pour les taureaux, pour les béliers, et pour les agneaux, d’après leur nombre, selon l’ordonnance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'et un bouc en sacrifice pour le péché, – outre l’holocauste continuel et son gâteau et sa libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Et le sixième jour, huit taureaux, deux béliers, 14 agneaux âgés d’un an, sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'et leur offrande de gâteau et leurs libations pour les taureaux, pour les béliers, et pour les agneaux, d’après leur nombre, selon l’ordonnance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'et un bouc en sacrifice pour le péché, – outre l’holocauste continuel, son gâteau et ses libations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Et le septième jour, sept taureaux, deux béliers, 14 agneaux âgés d’un an, sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'et leur offrande de gâteau et leurs libations pour les taureaux, pour les béliers, et pour les agneaux, d’après leur nombre, selon leur ordonnance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'et un bouc en sacrifice pour le péché, – outre l’holocauste continuel, son gâteau et sa libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Le huitième jour, vous aurez une fête solennelle; vous ne ferez aucune œuvre de service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Et vous présenterez un holocauste, un sacrifice par feu d’odeur agréable à l’ Éternel, un taureau, un bélier, sept agneaux âgés d’un an, sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'leur offrande de gâteau et leurs libations pour le taureau, pour le bélier, et pour les agneaux, d’après leur nombre, selon l’ordonnance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'et un bouc en sacrifice pour le péché, – outre l’holocauste continuel et son gâteau et sa libation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Vous offrirez ces choses à l’ Éternel dans vos jours solennels, outre vos vœux et vos offrandes volontaires en vos holocaustes et vos offrandes de gâteau, et vos libations, et vos sacrifices de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Et Moïse parla aux fils d’Israël selon tout ce que l’ Éternel avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, '*Et Moïse parla aux chefs des tribus des fils d’Israël, disant: C’est ici la parole que l’ Éternel a commandée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Quand un homme aura fait un vœu à l’ Éternel, ou quand il aura fait un serment, pour lier son âme par une obligation, il ne violera pas sa parole; il fera selon tout ce qui sera sorti de sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Et si une femme a fait un vœu à l’ Éternel, et qu’elle se soit liée par une obligation dans la maison de son père, dans sa jeunesse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'et que son père ait entendu son vœu et son obligation par laquelle elle a obligé son âme, et que son père ait gardé le silence envers elle, tous ses vœux demeureront obligatoires, et toute obligation par laquelle elle aura obligé son âme demeurera obligatoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Mais si son père la désapprouve le jour où il en a entendu parler, aucun de ses vœux et de ses obligations par lesquelles elle a obligé son âme ne demeureront obligatoires; et l’ Éternel lui pardonnera, car son père l’a désapprouvée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Et si elle a un mari, et que son vœu soit sur elle, ou quelque chose qui ait échappé de ses lèvres par quoi elle a obligé son âme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'et si son mari l’a entendu, et que le jour où il l’a entendu il ait gardé le silence envers elle, ses vœux demeureront obligatoires, et ses obligations par lesquelles elle aura obligé son âme demeureront obligatoires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Mais si, le jour où son mari l’aura entendu, il la désapprouve et casse le vœu qui est sur elle et ce qui a échappé de ses lèvres, par quoi elle avait obligé son âme, l’ Éternel lui pardonnera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Mais le vœu d’une veuve, ou d’une femme répudiée, – tout ce par quoi elle aura obligé son âme, demeurera obligatoire pour elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Et si elle a fait un vœu dans la maison de son mari, ou si elle a obligé son âme par serment,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'et que son mari l’ait entendu et ait gardé le silence envers elle, [et] ne l’ait pas désapprouvée, tous ses vœux demeureront obligatoires, et toute obligation par laquelle elle aura obligé son âme demeurera obligatoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Mais si son mari les a expressément cassés le jour où il les a entendus, alors rien de ce qui sera sorti de ses lèvres, vœu ou obligation [liée] sur son âme, ne demeurera obligatoire: son mari l’a cassé; et l’ Éternel lui pardonnera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Tout vœu et tout serment par lequel on s’oblige à affliger son âme, le mari peut le ratifier et le mari peut le casser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Et si son mari se tait absolument envers elle, jour après jour, alors il aura ratifié tous ses vœux, ou toutes ses obligations qu’elle a prises sur elle; il les a ratifiés, car il a gardé le silence envers elle le jour où il les a entendus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Mais s’il les a expressément cassés après les avoir entendus, alors il portera l’iniquité de sa femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, 'Ce sont là les statuts que l’ Éternel commanda à Moïse, entre un homme et sa femme, entre un père et sa fille, dans sa jeunesse, dans la maison de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Exécute la vengeance des fils d’Israël sur les Madianites; ensuite tu seras recueilli vers tes peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Et Moïse parla au peuple, disant: Équipez d’entre vous des hommes pour l’armée, afin qu’ils marchent contre Madian, pour exécuter la vengeance de l’ Éternel sur Madian.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Vous enverrez à l’armée 1 000 [hommes] par tribu, de toutes les tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Et on détacha d’entre les milliers d’Israël 1 000 [hommes] par tribu, 12 000 [hommes] équipés en guerre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'et Moïse les envoya à l’armée, 1 000 par tribu, à la guerre, eux et Phinées, fils d’Éléazar, le sacrificateur; et il avait en sa main les ustensiles du lieu saint, savoir les trompettes au son éclatant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Et ils firent la guerre contre Madian, comme l’ Éternel l’avait commandé à Moïse, et ils tuèrent tous les mâles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Et ils tuèrent les rois de Madian, outre ceux qui leur furent tués, Évi, et Rékem, et Tsur, et Hur, et Réba, cinq rois de Madian; et ils tuèrent par l’épée Balaam, fils de Béor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Et les fils d’Israël emmenèrent captives les femmes de Madian et leurs petits enfants, et pillèrent tout leur bétail et tous leurs troupeaux et tout leur bien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'et ils brûlèrent par le feu toutes les villes de leurs habitations, et tous leurs campements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'et ils emportèrent tout le butin et tout ce qu’ils avaient pris, en hommes et en bêtes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'et ils amenèrent les captifs, et ce qu’ils avaient pris, et le butin, à Moïse et à Éléazar, le sacrificateur, et à l’assemblée des fils d’Israël, au camp, dans les plaines de Moab, qui sont auprès du Jourdain de Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Et Moïse et Éléazar, le sacrificateur, et tous les princes de l’assemblée, sortirent à leur rencontre, hors du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Et Moïse se mit en colère contre les commandants de l’armée, les chefs de milliers et les chefs de centaines, qui revenaient du service de la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Et Moïse leur dit: Avez-vous laissé en vie toutes les femmes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Voici, ce sont elles qui, à la parole de Balaam, ont donné occasion aux fils d’Israël de commettre une infidélité contre l’ Éternel, dans l’affaire de Péor, et il y eut une plaie sur l’assemblée de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Et maintenant, tuez tous les mâles parmi les enfants, et tuez toute femme qui a connu un homme, en couchant avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'et vous laisserez en vie, pour vous, tous les enfants, les jeunes filles qui n’ont pas eu compagnie d’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Et vous, demeurez hors du camp, sept jours, quiconque aura tué un homme, et quiconque aura touché quelqu’un de tué; vous vous purifierez le troisième jour et le septième jour, vous et vos captifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Et vous purifierez tout vêtement, et tout objet [fait] de peau, et tout ouvrage en poil de chèvres, et tout ustensile de bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Et Éléazar, le sacrificateur, dit aux hommes de l’armée, qui étaient allés à la guerre: C’est ici le statut de la loi que l’ Éternel a commandée à Moïse:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'L’or, et l’argent, l’airain, le fer, l’étain, et le plomb,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'tout ce qui peut supporter le feu, vous le ferez passer par le feu, et ce sera pur; seulement, on le purifiera avec l’eau de séparation; et tout ce qui ne peut pas supporter le feu, vous le ferez passer par l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Et vous laverez vos vêtements le septième jour, et vous serez purs; et, après cela, vous entrerez dans le camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Relève la somme de ce qui a été pris et mené captif, en hommes et en bêtes, toi et Éléazar, le sacrificateur, et les chefs des pères de l’assemblée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'et partage le butin par moitié entre ceux qui ont pris part à la guerre, qui sont allés à l’armée, et toute l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Et tu lèveras pour l’ Éternel un tribut sur les hommes de guerre qui sont allés à l’armée, un sur 500, tant des hommes que du gros bétail, et des ânes, et du menu bétail;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'vous le prendrez de leur moitié, et tu le donneras à Éléazar, le sacrificateur, comme offrande élevée à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Et de la moitié qui revient aux fils d’Israël, tu prendras une part sur 50, des hommes, du gros bétail, des ânes, et du menu bétail, de toutes les bêtes, et tu les donneras aux Lévites, qui vaquent au service du tabernacle de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Et Moïse et Éléazar, le sacrificateur, firent comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Et ce qui fut pris, le reste du pillage dont le peuple de l’armée s’était emparé, était de 675 000 [têtes de] menu bétail,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, '72 000 [têtes de] gros bétail,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, '61 000 ânes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'et les personnes, les femmes qui n’avaient pas eu compagnie d’homme, en tout, 32 000 âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Et la moitié, la part de ceux qui étaient allés à l’armée, fut, en nombre, de 337 500 [têtes de] menu bétail,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, '– et le tribut pour l’ Éternel, du menu bétail, fut de 675;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, '– et 36 000 [têtes de] gros bétail, dont le tribut pour l’ Éternel fut de 72;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'et 30 500 ânes, dont le tribut pour l’ Éternel fut de 61;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'et 16 000 personnes, dont le tribut pour l’ Éternel fut de 32 âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Et Moïse donna le tribut de l’offrande élevée de l’ Éternel à Éléazar, le sacrificateur, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Et de la moitié qui revenait aux fils d’Israël, que Moïse avait séparée [de celle] des hommes qui avaient été à la guerre');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(or la moitié qui était à l’assemblée fut de 337 500 [têtes de] menu bétail,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, '36 000 [têtes de] gros bétail,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, '30 500 ânes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'et 16 000 personnes),...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'de cette moitié qui était aux fils d’Israël, Moïse prit une part sur 50, tant des hommes que du bétail, et les donna aux Lévites, qui vaquent au service du tabernacle de l’ Éternel, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Et ceux qui étaient préposés sur les milliers de l’armée, les chefs de milliers et les chefs de centaines, s’approchèrent de Moïse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'et ils dirent à Moïse: Tes serviteurs ont relevé la somme des hommes de guerre qui sont sous notre main, et il ne manque pas un seul homme d’entre nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Et nous présentons une offrande à l’ Éternel, chacun ce qu’il a trouvé, des objets d’or, des bracelets pour les bras, et des bracelets pour les mains, des anneaux, des pendants d’oreilles, et des colliers, afin de faire propitiation pour nos âmes devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Et Moïse et Éléazar, le sacrificateur, prirent d’eux cet or, tous les objets ouvragés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Et tout l’or de l’offrande élevée, qu’ils avaient offert à l’ Éternel, fut de 16 750 sicles, de la part des chefs de milliers et des chefs de centaines;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, '(les hommes de l’armée avaient pillé chacun pour soi).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Et Moïse et Éléazar, le sacrificateur, prirent l’or des chefs de milliers et des chefs de centaines, et l’apportèrent à la tente d’assignation, comme mémorial pour les fils d’Israël, devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, '*Et les troupeaux des fils de Ruben et des fils de Gad étaient en grand nombre, en très grande quantité. Et ils virent le pays de Jahzer et le pays de Galaad, et voici, le lieu était un lieu propre pour des troupeaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Et les fils de Gad et les fils de Ruben vinrent, et parlèrent à Moïse et à Éléazar, le sacrificateur, et aux princes de l’assemblée, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Ataroth, et Dibon, et Jahzer, et Nimra, et Hesbon, et Elhalé, et Sebam, et Nebo, et Béon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'le pays que l’ Éternel a frappé devant l’assemblée d’Israël, est un pays propre pour des troupeaux, et tes serviteurs ont des troupeaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Et ils dirent: Si nous avons trouvé faveur à tes yeux, que ce pays soit donné en possession à tes serviteurs; ne nous fais pas passer le Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Et Moïse dit aux fils de Gad et aux fils de Ruben: Vos frères iront-ils à la guerre, et vous, vous habiterez ici?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Et pourquoi découragez-vous les fils d’Israël de passer dans le pays que l’ Éternel leur a donné?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Ainsi firent vos pères lorsque je les envoyai de Kadès-Barnéa pour voir le pays:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'ils montèrent à la vallée d’Eshcol, et virent le pays; et ils découragèrent les fils d’Israël, afin qu’ils n’entrent pas dans le pays que l’ Éternel leur avait donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Et la colère de l’ Éternel s’embrasa en ce jour-là, et il jura, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Si les hommes qui sont montés d’Égypte, depuis l’âge de 20 ans et au-dessus, voient la terre que j’ai promise par serment à Abraham, à Isaac, et à Jacob! car ils ne m’ont pas pleinement suivi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, '– excepté Caleb, fils de Jephunné, le Kenizien, et Josué, fils de Nun, car ils ont pleinement suivi l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Et la colère de l’ Éternel s’embrasa contre Israël, et il les a fait errer dans le désert 40 ans, jusqu’à ce qu’ait péri toute la génération qui avait fait ce qui est mauvais aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Et voici, vous vous êtes levés à la place de vos pères, une progéniture d’hommes pécheurs, pour ajouter encore à l’ardeur de la colère de l’ Éternel contre Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Si vous vous détournez de lui, il le laissera encore dans le désert, et vous détruirez tout ce peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Et ils s’approchèrent de lui, et dirent: Nous bâtirons ici des enclos pour nos troupeaux, et des villes pour nos petits enfants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'et nous nous équiperons promptement [pour marcher] devant les fils d’Israël, jusqu’à ce que nous les ayons introduits en leur lieu; et nos petits enfants habiteront dans les villes fortes, à cause des habitants du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Nous ne reviendrons pas dans nos maisons, jusqu’à ce que les fils d’Israël aient pris possession chacun de son héritage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'car nous n’hériterons pas avec eux au-delà du Jourdain, ni plus loin, parce que notre héritage nous est échu, à nous, de ce côté du Jourdain, vers le levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Et Moïse leur dit: Si vous faites cela, si vous vous équipez devant l’ Éternel pour la guerre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'et que tous ceux d’entre vous qui sont équipés passent le Jourdain devant l’ Éternel, jusqu’à ce qu’il ait dépossédé ses ennemis devant lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'et que le pays soit subjugué devant l’ Éternel, et qu’ensuite vous vous en retourniez, alors vous serez innocents envers l’ Éternel et envers Israël; et ce pays-ci sera votre possession devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Mais si vous ne faites pas ainsi, voici, vous pécherez contre l’ Éternel; et sachez que votre péché vous trouvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Bâtissez-vous des villes pour vos petits enfants, et des enclos pour vos troupeaux; et ce qui est sorti de votre bouche, faites-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Et les fils de Gad et les fils de Ruben parlèrent à Moïse, disant: Tes serviteurs feront comme mon seigneur l’a commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Nos petits enfants, nos femmes, nos troupeaux et toutes nos bêtes seront là, dans les villes de Galaad;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'et tes serviteurs, tous équipés pour l’armée, passeront devant l’ Éternel [pour aller] à la guerre, comme mon seigneur l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Et Moïse commanda à leur sujet à Éléazar, le sacrificateur, et à Josué, fils de Nun, et aux chefs des pères des tribus des fils d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'et Moïse leur dit: Si les fils de Gad et les fils de Ruben passent avec vous le Jourdain devant l’ Éternel, tous équipés pour la guerre, et que le pays soit subjugué devant vous, vous leur donnerez le pays de Galaad en possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Mais s’ils ne passent pas équipés avec vous, alors ils auront des possessions au milieu de vous dans le pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Et les fils de Gad et les fils de Ruben répondirent, disant: Nous ferons ainsi que l’ Éternel a dit à tes serviteurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'nous passerons équipés devant l’ Éternel dans le pays de Canaan, et la possession de notre héritage en deçà du Jourdain sera à nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Et Moïse leur donna, – aux fils de Gad, et aux fils de Ruben, et à la demi-tribu de Manassé, fils de Joseph, – le royaume de Sihon, roi des Amoréens, et le royaume d’Og, roi de Basan, le pays, selon ses villes, dans leurs confins, les villes du pays à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, '– Et les fils de Gad bâtirent Dibon, et Ataroth, et Aroër,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'et Atroth-Shophan, et Jahzer, et Jogbeha,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'et Beth-Nimra, et Beth-Haran, villes fortes, et des enclos pour le petit bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, '– Et les fils de Ruben bâtirent Hesbon, et Elhalé, et Kiriathaïm,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'et Nebo, et Baal-Méon, dont les noms furent changés, et Sibma; et ils donnèrent d’autres noms aux villes qu’ils bâtirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, '– Et les fils de Makir, fils de Manassé, allèrent dans [le pays de] Galaad, et le prirent, et dépossédèrent les Amoréens qui y étaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Et Moïse donna Galaad à Makir, fils de Manassé, et il y habita.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Et Jaïr, fils de Manassé, alla, et prit leurs bourgs, et les appela bourgs de Jaïr.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Et Nobakh alla, et prit Kenath et les villages de son ressort, et il l’appela Nobakh, d’après son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, '*Ce sont ici les traites des fils d’Israël, qui sortirent du pays d’Égypte, selon leurs armées, sous la main de Moïse et d’Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Et Moïse écrivit leurs départs, selon leurs traites, suivant le commandement de l’ Éternel; et ce sont ici leurs traites, selon leurs départs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Ils partirent de Ramsès, le premier mois, le quinzième jour du premier mois: le lendemain de la Pâque, les fils d’Israël sortirent à main levée, aux yeux de tous les Égyptiens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'et les Égyptiens enterraient ceux que l’ Éternel avait frappés parmi eux, tous les premiers-nés; et l’ Éternel avait exécuté des jugements sur leurs dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Et les fils d’Israël partirent de Ramsès, et campèrent à Succoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Et ils partirent de Succoth, et campèrent à Étham, qui est à l’extrémité du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Et ils partirent d’Étham et retournèrent à Pi-Hahiroth, qui est vis-à-vis de Baal-Tsephon, et campèrent devant Migdol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Et ils partirent de devant Hahiroth, et passèrent au milieu de la mer, vers le désert, et allèrent le chemin de trois jours dans le désert d’Étham, et campèrent à Mara.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Et ils partirent de Mara, et vinrent à Élim; et à Élim, il y avait douze fontaines d’eau et 70 palmiers, et ils campèrent là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Et ils partirent d’Élim, et campèrent près de la mer Rouge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Et ils partirent de la mer Rouge, et campèrent dans le désert de Sin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Et ils partirent du désert de Sin, et campèrent à Dophka.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Et ils partirent de Dophka, et campèrent à Alush.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Et ils partirent d’Alush, et campèrent à Rephidim, où il n’y avait pas d’eau à boire pour le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Et ils partirent de Rephidim, et campèrent dans le désert de Sinaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Et ils partirent du désert de Sinaï, et campèrent à Kibroth-Hattaava.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Et ils partirent de Kibroth-Hattaava, et campèrent à Hatséroth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Et ils partirent de Hatséroth, et campèrent à Rithma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Et ils partirent de Rithma, et campèrent à Rimmon-Pérets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Et ils partirent de Rimmon-Pérets, et campèrent à Libna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Et ils partirent de Libna, et campèrent à Rissa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Et ils partirent de Rissa, et campèrent à Kehélatha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Et ils partirent de Kehélatha, et campèrent dans la montagne de Shapher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Et ils partirent de la montagne de Shapher, et campèrent à Harada.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Et ils partirent de Harada, et campèrent à Makhéloth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Et ils partirent de Makhéloth, et campèrent à Thakhath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Et ils partirent de Thakhath, et campèrent à Thérakh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Et ils partirent de Thérakh, et campèrent à Mithka.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Et ils partirent de Mithka, et campèrent à Hashmona.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Et ils partirent de Hashmona, et campèrent à Moséroth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Et ils partirent de Moséroth, et campèrent à Bené-Jaakan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Et ils partirent de Bené-Jaakan, et campèrent à Hor-Guidgad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Et ils partirent de Hor-Guidgad, et campèrent à Jotbatha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Et ils partirent de Jotbatha, et campèrent à Abrona.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Et ils partirent d’Abrona, et campèrent à Étsion-Guéber.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Et ils partirent d’Étsion-Guéber, et campèrent dans le désert de Tsin, qui est Kadès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Et ils partirent de Kadès, et campèrent dans la montagne de Hor, aux confins du pays d’Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Et Aaron le sacrificateur monta sur la montagne de Hor, suivant le commandement de l’ Éternel, et il y mourut, en la quarantième année après que les fils d’Israël furent sortis du pays d’Égypte, le cinquième mois, le premier [jour] du mois:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'et Aaron était âgé de 123 ans, quand il mourut sur la montagne de Hor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Et le Cananéen, roi d’Arad, qui habitait le midi, dans le pays de Canaan, apprit que les fils d’Israël venaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Et ils partirent de la montagne de Hor, et campèrent à Tsalmona.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Et ils partirent de Tsalmona, et campèrent à Punon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Et ils partirent de Punon, et campèrent à Oboth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Et ils partirent d’Oboth, et campèrent à Ijim-Abarim, sur la frontière de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Et ils partirent d’Ijim, et campèrent à Dibon-Gad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Et ils partirent de Dibon-Gad, et campèrent à Almon, vers Diblathaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Et ils partirent d’Almon vers Diblathaïm, et campèrent dans les montagnes d’Abarim, devant Nebo.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Et ils partirent des montagnes d’Abarim, et campèrent dans les plaines de Moab, près du Jourdain de Jéricho;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'et ils campèrent près du Jourdain, depuis Beth-Jeshimoth jusqu’à Abel-Sittim, dans les plaines de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Et l’ Éternel parla à Moïse, dans les plaines de Moab, près du Jourdain de Jéricho, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Parle aux fils d’Israël, et dis-leur: Quand vous aurez passé le Jourdain [et que vous serez entrés] dans le pays de Canaan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'vous déposséderez tous les habitants du pays devant vous, et vous détruirez toutes leurs figures sculptées, et vous détruirez toutes leurs images de fonte, et vous dévasterez tous leurs hauts lieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'et vous prendrez possession du pays, et vous y habiterez, car je vous ai donné le pays pour le posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Et vous recevrez le pays en héritage par le sort, selon vos familles: à ceux qui sont nombreux, vous augmenterez l’héritage, et à ceux qui sont peu nombreux, vous diminuerez l’héritage; là où le sort lui sera échu, là sera [l’héritage] de chacun: vous hériterez selon les tribus de vos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Et si vous ne dépossédez pas devant vous les habitants du pays, ceux d’entre eux que vous laisserez de reste seront comme des épines à vos yeux et comme des piquants dans vos côtés, et ils vous opprimeront dans le pays que vous habiterez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Et il arrivera que je vous ferai à vous, comme j’ai pensé de leur faire, à eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, '*Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Commande aux fils d’Israël, et dis-leur: Quand vous serez entrés dans le pays de Canaan, ce sera ici le pays qui vous écherra en héritage, le pays de Canaan selon ses limites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Votre côté méridional sera depuis le désert de Tsin, le long d’Édom, et votre frontière méridionale sera depuis le bout de la mer Salée, vers l’orient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'et votre frontière tournera au midi de la montée d’Akrabbim, et passera vers Tsin; et elle s’étendra au midi de Kadès-Barnéa, et sortira par Hatsar-Addar, et passera vers Atsmon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'et la frontière tournera depuis Atsmon vers le torrent d’Égypte, et aboutira à la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Et, pour frontière occidentale, vous aurez la grande mer et [ses] côtes; ce sera là votre frontière occidentale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Et ce sera ici votre frontière septentrionale: depuis la grande mer, vous marquerez pour vous la montagne de Hor;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'depuis la montagne de Hor, vous tracerez jusqu’à l’entrée de Hamath, et la frontière aboutira vers Tsedad;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'et la frontière sortira vers Ziphron, et aboutira à Hatsar-Énan; ce sera là votre frontière septentrionale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Et vous vous tracerez, pour frontière orientale, depuis Hatsar-Énan à Shepham;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'et la frontière descendra de Shepham vers Ribla, à l’orient d’Aïn; et la frontière descendra, et touchera l’extrémité de la mer de Kinnéreth, à l’orient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'et la frontière descendra au Jourdain, et aboutira à la mer Salée. Ce sera là votre pays, selon ses limites, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Et Moïse commanda aux fils d’Israël, disant: C’est là le pays que vous recevrez en héritage par le sort, lequel l’ Éternel a commandé de donner aux neuf tribus et à la demi-tribu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'car la tribu des fils des Rubénites, selon leurs maisons de pères, et la tribu des fils des Gadites, selon leurs maisons de pères, et la demi-tribu de Manassé, ont pris leur héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Les deux tribus et la demi-tribu ont pris leur héritage en deçà du Jourdain de Jéricho, à l’orient, vers le levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Ce sont ici les noms des hommes qui vous partageront le pays: Éléazar le sacrificateur, et Josué, fils de Nun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, '– Et vous prendrez un prince de chaque tribu, pour faire le partage du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Et ce sont ici les noms des hommes: pour la tribu de Juda, Caleb, fils de Jephunné;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'et pour la tribu des fils de Siméon, Samuel, fils d’Ammihud;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'pour la tribu de Benjamin, Élidad, fils de Kislon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'et pour la tribu des fils de Dan, un prince, Bukki, fils de Jogli;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'pour les fils de Joseph, pour la tribu des fils de Manassé, un prince, Hanniel, fils d’Éphod;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'et pour la tribu des fils d’Éphraïm, un prince, Kemuel, fils de Shiphtan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'et pour la tribu des fils de Zabulon, un prince, Élitsaphan, fils de Parnac;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'et pour la tribu des fils d’Issacar, un prince, Paltiel, fils d’Azzan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'et pour la tribu des fils d’Aser, un prince, Akhihud, fils de Shelomi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'et pour la tribu des fils de Nephthali, un prince, Pedahel, fils d’Ammihud.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Ce sont là ceux auxquels l’ Éternel commanda de distribuer l’héritage aux fils d’Israël dans le pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, '*Et l’ Éternel parla à Moïse, dans les plaines de Moab, près du Jourdain de Jéricho, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Commande aux fils d’Israël que, de l’héritage de leur possession, ils donnent aux Lévites des villes pour y habiter. Vous donnerez aussi aux Lévites les banlieues de ces villes, autour d’elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Et ils auront les villes pour y habiter, et leurs banlieues seront pour leur bétail et pour leurs biens et pour tous leurs animaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Et les banlieues des villes que vous donnerez aux Lévites seront de 1 000 coudées à l’entour, depuis la muraille de la ville en dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Et vous mesurerez, en dehors de la ville, le côté de l’orient, 2 000 coudées, et le côté du midi, 2 000 coudées, et le côté de l’occident, 2 000 coudées, et le côté du nord, 2 000 coudées; et la ville sera au milieu: ce seront là les banlieues de leurs villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Et [parmi] les villes que vous donnerez aux Lévites, seront les six villes de refuge, que vous donnerez pour que l’homicide s’y enfuie; et outre celles-là, vous donnerez 42 villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Toutes les villes que vous donnerez aux Lévites seront 48 villes, elles et leurs banlieues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Et quant aux villes que vous donnerez sur la possession des fils d’Israël, de ceux qui en auront beaucoup vous en prendrez beaucoup, et de ceux qui en auront peu vous en prendrez peu: chacun donnera de ses villes aux Lévites, à proportion de l’héritage qu’il aura reçu en partage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Et l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Parle aux fils d’Israël, et dis-leur: Quand vous aurez passé le Jourdain [et que vous serez entrés] dans le pays de Canaan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'alors vous vous désignerez des villes; elles seront pour vous des villes de refuge, et l’homicide qui, par mégarde, aura frappé à mort quelqu’un, s’y enfuira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Et ce seront pour vous des villes de refuge de devant le vengeur, afin que l’homicide ne meure point qu’il n’ait comparu en jugement devant l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Et les villes que vous donnerez seront pour vous six villes de refuge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'vous donnerez trois de ces villes en deçà du Jourdain, et vous donnerez trois de ces villes dans le pays de Canaan: ce seront des villes de refuge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Ces six villes serviront de refuge aux fils d’Israël, et à l’étranger, et à celui qui séjourne parmi eux, afin que quiconque aura, par mégarde, frappé à mort une personne, s’y enfuie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, '– Et s’il l’a frappée avec un instrument de fer, et qu’elle meure, il est meurtrier: le meurtrier sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Et s’il l’a frappée avec une pierre qu’il tenait à la main, [et] dont on puisse mourir, et qu’elle meure, il est meurtrier: le meurtrier sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Ou s’il l’a frappée avec un instrument de bois qu’il tenait à la main, [et] dont on puisse mourir, et qu’elle meure, il est meurtrier: le meurtrier sera certainement mis à mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'le vengeur du sang mettra à mort le meurtrier; quand il le rencontrera, c’est lui qui le mettra à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Et s’il l’a poussée par haine, ou s’il a jeté [quelque chose] sur elle avec préméditation, et qu’elle meure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'ou qu’il l’ait frappée de la main par inimitié, et qu’elle meure, celui qui l’a frappée sera certainement mis à mort: il est meurtrier; le vengeur du sang mettra à mort le meurtrier quand il le rencontrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, '– Mais s’il l’a poussée subitement, sans inimitié, ou s’il a jeté sur elle un objet quelconque, sans préméditation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'ou si, n’étant pas son ennemi et ne cherchant pas son mal, il fait tomber sur elle, ne la voyant pas, quelque pierre qui puisse la faire mourir, et qu’elle meure,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'alors l’assemblée jugera entre celui qui a frappé et le vengeur du sang, selon ces ordonnances;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'et l’assemblée délivrera l’homicide de la main du vengeur du sang, et l’assemblée le fera retourner dans la ville de son refuge où il s’était enfui; et il y demeurera jusqu’à la mort du grand sacrificateur qu’on a oint de l’huile sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Mais si l’homicide vient à sortir des limites de la ville de son refuge, où il s’est enfui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'et que le vengeur du sang le trouve en dehors des limites de la ville de son refuge, et que le vengeur du sang tue l’homicide, le sang ne sera pas sur lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'car l’homicide doit demeurer dans la ville de son refuge jusqu’à la mort du grand sacrificateur; et après la mort du grand sacrificateur, il retournera dans la terre de sa possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Et ces choses seront pour vous un statut de droit, en vos générations, partout où vous habiterez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Si quelqu’un frappe à mort une personne, le meurtrier sera tué sur la parole de témoins; mais un seul témoin ne rendra pas témoignage contre quelqu’un, pour le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Et vous ne prendrez point de rançon pour la vie du meurtrier qui est coupable d’avoir tué; mais il sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Et vous ne prendrez point de rançon pour celui qui s’est enfui dans la ville de son refuge, pour qu’il retourne habiter dans le pays, jusqu’à la mort du sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Et vous ne profanerez point le pays où vous êtes, car le sang profane le pays; et l’expiation du sang ne pourra être faite, pour le pays où il a été versé, que par le sang de celui qui l’a versé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Et vous ne rendrez pas impur le pays où vous demeurez, au milieu duquel j’habite; car moi, l’ Éternel, j’habite au milieu des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, '*Et les chefs des pères de la famille des fils de Galaad, fils de Makir, fils de Manassé, d’entre les familles des fils de Joseph, s’approchèrent et parlèrent devant Moïse et devant les princes, chefs des pères des fils d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'et ils dirent: L’ Éternel a commandé à mon seigneur de donner le pays en héritage par le sort aux fils d’Israël, et mon seigneur a reçu de l’ Éternel commandement de donner l’héritage de Tselophkhad, notre frère, à ses filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Si elles deviennent femmes de quelqu’un des fils des [autres] tribus des fils d’Israël, leur héritage sera ôté de l’héritage de nos pères, et sera ajouté à l’héritage de la tribu à laquelle elles viendront à appartenir; et il sera ôté du lot de notre héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Et quand le Jubilé des fils d’Israël arrivera, leur héritage sera ajouté à l’héritage de la tribu à laquelle elles appartiendront; et leur héritage sera ôté de l’héritage de la tribu de nos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Et Moïse commanda aux fils d’Israël, sur le commandement de l’ Éternel, disant: La tribu des fils de Joseph a dit juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'C’est ici la parole que l’ Éternel a commandée à l’égard des filles de Tselophkhad, disant: Elles deviendront femmes de qui leur semblera bon; seulement, qu’elles deviennent femmes dans la famille de la tribu de leurs pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'afin que l’héritage ne passe point de tribu en tribu chez les fils d’Israël; car les fils d’Israël seront attachés chacun à l’héritage de la tribu de ses pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Et toute fille qui possédera un héritage dans les tribus des fils d’Israël, sera mariée à quelqu’un de la famille de la tribu de son père, afin que les fils d’Israël possèdent chacun l’héritage de ses pères');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'et qu’un héritage ne passe pas d’une tribu à une autre tribu; car les tribus des fils d’Israël resteront attachées chacune à son héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Les filles de Tselophkhad firent comme l’ Éternel l’avait commandé à Moïse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'et Makhla, Thirtsa, et Hogla, et Milca, et Noa, filles de Tselophkhad, se marièrent aux fils de leurs oncles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Elles furent mariées à ceux qui étaient des familles des fils de Manassé, fils de Joseph; et leur héritage resta dans la tribu de la famille de leur père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Ce sont là les commandements et les ordonnances que l’ Éternel prescrivit par Moïse aux fils d’Israël, dans les plaines de Moab, près du Jourdain de Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Ce sont ici les paroles que Moïse dit à tout Israël, en deçà du Jourdain, dans le désert, dans la plaine, vis-à-vis de Suph, entre Paran et Thophel, Laban, Hatséroth et Di-Zahab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Il y a onze journées depuis Horeb, par le chemin de la montagne de Séhir, jusqu’à Kadès-Barnéa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, '– Et il arriva, en la quarantième année, au onzième mois, le premier [jour] du mois, que Moïse parla aux fils d’Israël, selon tout ce que l’ Éternel lui avait commandé pour eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'après qu’il eut frappé Sihon, roi des Amoréens, qui habitait à Hesbon, et Og, roi de Basan, qui habitait à Ashtaroth, à Édréhi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'En deçà du Jourdain, dans le pays de Moab, Moïse commença à exposer cette loi, en disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'L’ Éternel, notre Dieu, nous parla en Horeb, disant: Vous avez assez demeuré dans cette montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Tournez-vous, et partez, et allez à la montagne des Amoréens et dans tous les lieux voisins, dans la plaine, dans la montagne, et dans le pays plat, et dans le midi, et sur le rivage de la mer, au pays des Cananéens et au Liban, jusqu’au grand fleuve, le fleuve Euphrate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Regarde, j’ai mis le pays devant vous: entrez, et possédez le pays que l’ Éternel a juré à vos pères, à Abraham, à Isaac, et à Jacob, de leur donner, et à leur semence après eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Et je vous parlai, en ce temps-là, disant: Je ne puis, moi seul, vous porter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'L’ Éternel, votre Dieu, vous a multipliés, et vous voici aujourd’hui, en multitude, comme les étoiles des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Que l’ Éternel, le Dieu de vos pères, ajoute à votre nombre 1 000 fois ce que vous êtes, et vous bénisse, comme il vous l’a dit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Comment porterais-je, moi seul, votre charge, et votre fardeau, et vos contestations?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Donnez-vous des hommes sages, et intelligents, et connus, selon vos tribus, et je les établirai chefs sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Et vous m’avez répondu et avez dit: La chose que tu as dit de faire est bonne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Et je pris les chefs de vos tribus, des hommes sages et connus, et je les établis chefs sur vous, chefs de milliers, et chefs de centaines, et chefs de cinquantaines, et chefs de dizaines, et officiers sur vos tribus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, '– Et je commandai à vos juges, en ce temps-là, disant: Écoutez [les différends] entre vos frères, et jugez avec justice entre un homme et son frère, et l’étranger qui est avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Vous ne ferez point acception des personnes dans le jugement; vous entendrez aussi bien le petit que le grand; vous n’aurez peur d’aucun homme, car le jugement est de Dieu; et l’affaire qui sera trop difficile pour vous, vous me la présenterez, et je l’entendrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Et je vous commandai, en ce temps-là, toutes les choses que vous devez faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Et nous sommes partis d’Horeb, et nous avons traversé tout ce grand et terrible désert que vous avez vu, le chemin de la montagne des Amoréens, comme l’ Éternel, notre Dieu, nous l’avait commandé, et nous sommes venus jusqu’à Kadès-Barnéa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Et je vous dis: Vous êtes arrivés jusqu’à la montagne des Amoréens, laquelle l’ Éternel, notre Dieu, nous donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Regarde, l’ Éternel, ton Dieu, a mis devant toi le pays: monte, prends possession, comme l’ Éternel, le Dieu de tes pères, te l’a dit; ne crains point et ne t’effraie point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Et vous vous êtes tous approchés de moi, et vous avez dit: Envoyons des hommes devant nous, et ils examineront le pays pour nous, et ils nous rapporteront des nouvelles du chemin par lequel nous pourrons monter et des villes auxquelles nous viendrons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Et la chose fut bonne à mes yeux, et je pris d’entre vous douze hommes, un homme par tribu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Et ils se tournèrent, et montèrent dans la montagne, et vinrent jusqu’au torrent d’Eshcol, et explorèrent le [pays].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Et ils prirent dans leurs mains du fruit du pays et nous l’apportèrent, et ils nous rendirent compte et dirent: Le pays que l’ Éternel, notre Dieu, nous donne, est bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Mais vous n’avez pas voulu monter, et vous avez été rebelles au commandement de l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Et vous avez murmuré dans vos tentes et vous avez dit: C’est parce que l’ Éternel nous hait, qu’il nous a fait sortir du pays d’Égypte, afin de nous livrer aux mains des Amoréens, pour nous détruire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Où monterions-nous? Nos frères nous ont fait fondre le cœur, en disant: [C’est] un peuple plus grand et de plus haute taille que nous; les villes sont grandes, et murées jusqu’aux cieux; et de plus nous avons vu là des fils des Anakim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, '– Et je vous dis: Ne vous épouvantez pas, et ne les craignez point;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'l’ Éternel, votre Dieu, qui marche devant vous, combattra lui-même pour vous, selon tout ce qu’il a fait pour vous sous vos yeux, en Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'et dans le désert, où tu as vu que l’ Éternel, ton Dieu, t’a porté comme un homme porte son fils, dans tout le chemin où vous avez marché, jusqu’à ce que vous soyez arrivés en ce lieu-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Mais, dans cette circonstance, vous n’avez point cru l’ Éternel, votre Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'qui, afin de reconnaître pour vous un lieu pour que vous y campiez, allait devant vous dans le chemin, la nuit, dans le feu, pour vous faire voir le chemin où vous deviez marcher, et, le jour, dans la nuée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Et l’ Éternel entendit la voix de vos paroles et fut courroucé, et jura, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Si aucun de ces hommes, de cette génération méchante, voit ce bon pays que j’ai juré de donner à vos pères!...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'excepté Caleb, fils de Jephunné: lui, le verra, et je lui donnerai, et à ses fils, le pays où il a marché, parce qu’il a pleinement suivi l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Contre moi aussi l’ Éternel s’irrita, à cause de vous, disant: Toi non plus, tu n’y entreras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Josué, fils de Nun, qui se tient devant toi, lui, y entrera; fortifie-le, car c’est lui qui le fera hériter à Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Et vos petits enfants dont vous avez dit qu’ils seraient une proie, et vos fils qui aujourd’hui ne connaissent pas le bien et le mal, ceux-là y entreront, et c’est à eux que je le donnerai, et ils le posséderont.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Et vous, tournez-vous, et partez pour le désert, par le chemin de la mer Rouge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, '– Et vous avez répondu et m’avez dit: Nous avons péché contre l’ Éternel; nous monterons, et nous combattrons, selon tout ce que l’ Éternel, notre Dieu, nous a commandé. Et vous avez ceint chacun ses armes de guerre, et légèrement vous avez entrepris de monter dans la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Et l’ Éternel me dit: Dis-leur: Ne montez pas, et ne combattez pas, car je ne suis point au milieu de vous, afin que vous ne soyez pas battus par vos ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Et je vous parlai; mais vous n’avez point écouté, et vous avez été rebelles au commandement de l’ Éternel, et vous avez été présomptueux, et êtes montés dans la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Et l’Amoréen, qui habitait cette montagne, sortit à votre rencontre, et vous poursuivit, comme font les abeilles, et il vous tailla en pièces en Séhir, jusqu’à Horma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Et à votre retour vous avez pleuré devant l’ Éternel; et l’ Éternel n’écouta point votre voix et ne vous prêta point l’oreille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Et vous avez demeuré à Kadès plusieurs jours, selon les jours que vous y avez habité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Et nous nous sommes tournés, et nous sommes partis pour le désert, par le chemin de la mer Rouge, comme l’ Éternel m’avait dit, et nous avons tourné autour de la montagne de Séhir, plusieurs jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Et l’ Éternel me parla, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Vous avez assez tourné autour de cette montagne; dirigez-vous vers le nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Et commande au peuple, disant: Vous allez passer par les confins de vos frères, les fils d’Ésaü, qui habitent en Séhir, et ils auront peur de vous; et soyez bien sur vos gardes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'vous n’engagerez pas de lutte avec eux, car je ne vous donnerai rien de leur pays, pas même de quoi poser la plante du pied, car j’ai donné la montagne de Séhir en possession à Ésaü.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Vous achèterez d’eux la nourriture à prix d’argent, et vous la mangerez; et l’eau aussi, vous l’achèterez d’eux à prix d’argent, et vous la boirez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Car l’ Éternel, ton Dieu, t’a béni dans toute l’œuvre de ta main; il a connu ta marche par ce grand désert; pendant ces 40 ans, l’ Éternel, ton Dieu, a été avec toi; tu n’as manqué de rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Et nous avons laissé nos frères, les fils d’Ésaü, qui habitent en Séhir, passant devant la plaine, devant Élath et Étsion-Guéber, et nous nous sommes tournés, et nous avons passé par le chemin du désert de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Et l’ Éternel me dit: Tu n’attaqueras pas Moab, et tu ne te mettras pas en guerre avec eux; car je ne te donnerai rien de leur pays en possession, car j’ai donné Ar en possession aux fils de Lot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Les Émim y habitaient auparavant, un peuple grand et nombreux et de haute stature comme les Anakim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'ils sont réputés, eux aussi, des géants, comme les Anakim, mais les Moabites les appellent Émim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Et les Horiens habitaient auparavant en Séhir, et les fils d’Ésaü les dépossédèrent, et les détruisirent devant eux, et habitèrent à leur place, comme a fait Israël dans le pays de sa possession, que l’ Éternel lui a donné.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Maintenant, levez-vous et passez le torrent de Zéred. – Et nous avons passé le torrent de Zéred.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Et les jours que nous avons marché depuis Kadès-Barnéa jusqu’à ce que nous ayons passé le torrent de Zéred, ont été 38 ans, jusqu’à ce que toute la génération des hommes de guerre ait péri du milieu du camp, comme l’ Éternel le leur avait juré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Et la main de l’ Éternel a aussi été contre eux, pour les détruire du milieu du camp, jusqu’à ce qu’ils aient péri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Et il arriva que, lorsque tous les hommes de guerre eurent péri du milieu du peuple par la mort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'l’ Éternel me parla, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Tu vas passer aujourd’hui la frontière de Moab, [qui est] Ar,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'et tu t’approcheras vis-à-vis des fils d’Ammon; tu ne les attaqueras pas, et tu n’engageras pas de lutte avec eux, car je ne te donnerai rien du pays des fils d’Ammon en possession, parce que je l’ai donné en possession aux fils de Lot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Il est aussi réputé pays des Rephaïm; les Rephaïm y habitaient auparavant, et les Ammonites les appellent Zamzummim,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'peuple grand et nombreux et de haute stature comme les Anakim; mais l’ Éternel les détruisit devant eux, et ils les dépossédèrent et habitèrent à leur place,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, '– comme il fit pour les fils d’Ésaü, qui habitent en Séhir, lorsqu’il détruisit les Horiens devant eux, et qu’ils les dépossédèrent; et ils ont habité à leur place jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Et quant aux Avviens qui habitaient dans des hameaux jusqu’à Gaza, les Caphtorim, sortis de Caphtor, les détruisirent et habitèrent à leur place.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Levez-vous, partez, et passez le torrent de l’Arnon. Regarde, j’ai livré en ta main Sihon, roi de Hesbon, l’Amoréen, et son pays: commence, prends possession, et fais-lui la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Aujourd’hui je commencerai à mettre la frayeur et la peur de toi sur les peuples, sous tous les cieux; car ils entendront le bruit de ce que tu fais, et ils trembleront, et seront en angoisse devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Et j’envoyai, du désert de Kedémoth, des messagers à Sihon, roi de Hesbon, avec des paroles de paix, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Je passerai par ton pays; j’irai seulement par le chemin, je ne m’écarterai ni à droite ni à gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Tu me vendras de la nourriture à prix d’argent, afin que je mange; et tu me donneras de l’eau à prix d’argent, afin que je boive; je ne ferai que passer avec mes pieds:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'comme m’ont fait les fils d’Ésaü qui habitent en Séhir, et les Moabites qui habitent à Ar; jusqu’à ce que je passe le Jourdain [et que j’entre] dans le pays que l’ Éternel, notre Dieu, nous donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Et Sihon, roi de Hesbon, ne voulut pas nous laisser passer par son [pays]; car l’ Éternel, ton Dieu, avait endurci son esprit et roidi son cœur, afin de le livrer en ta main, comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Et l’ Éternel me dit: Regarde, j’ai commencé à livrer devant toi Sihon et son pays: commence, prends possession, afin que tu possèdes son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, '– Et Sihon sortit à notre rencontre, lui et tout son peuple, à Jahats, pour livrer bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Et l’ Éternel, notre Dieu, le livra devant nous; et nous l’avons battu, lui, et ses fils, et tout son peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'et nous avons pris toutes ses villes, en ce temps-là, et nous avons détruit entièrement toutes les villes, hommes, et femmes, et enfants; nous n’avons pas laissé un réchappé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'seulement, nous avons pillé pour nous les bêtes et le butin des villes que nous avions prises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Depuis Aroër, qui est sur le bord du torrent de l’Arnon, et la ville qui est dans le torrent, jusqu’à Galaad, il n’y eut pas de ville qui soit trop haute pour nous; l’ Éternel, notre Dieu, livra tout devant nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Seulement, tu ne t’es pas approché du pays des fils d’Ammon, de toute la rive du torrent de Jabbok, ni des villes de la montagne, ni de tout ce que l’ Éternel, notre Dieu, nous avait commandé [de ne pas toucher].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Et nous nous sommes tournés, et nous sommes montés par le chemin de Basan; et Og, le roi de Basan, sortit à notre rencontre, lui et tout son peuple, à Édréhi, pour livrer bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Et l’ Éternel me dit: Ne le crains pas, car je l’ai livré en ta main, lui et tout son peuple, et son pays; et tu lui feras comme tu as fait à Sihon, roi des Amoréens, qui habitait à Hesbon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, '– Et l’ Éternel, notre Dieu, livra aussi en notre main Og, le roi de Basan, et tout son peuple; et nous l’avons battu jusqu’à ne pas lui laisser un réchappé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Et nous avons pris toutes ses villes, en ce temps-là; il n’y eut point de ville que nous ne leur ayons prise: 60 villes, toute la région d’Argob, le royaume d’Og, en Basan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'toutes ces villes-là étaient fortifiées avec de hautes murailles, des portes et des barres, outre les villes ouvertes, en fort grand nombre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'et nous les avons entièrement détruites, comme nous avions fait à Sihon, roi de Hesbon, détruisant toutes les villes, hommes, femmes, et enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Et nous avons pillé pour nous toutes les bêtes, et le butin des villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Et nous avons pris en ce temps-là, de la main des deux rois des Amoréens, le pays qui était en deçà du Jourdain, depuis le torrent de l’Arnon jusqu’à la montagne de l’Hermon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(les Sidoniens appellent l’Hermon, Sirion, et les Amoréens l’appellent Senir);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'toutes les villes du plateau, et tout Galaad, et tout Basan jusqu’à Salca et à Édréhi, villes du royaume d’Og, en Basan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Car Og, le roi de Basan, était seul demeuré du reste des Rephaïm. Voici, son lit, un lit de fer, n’est-il pas dans Rabba des fils d’Ammon? Sa longueur est de neuf coudées, et sa largeur de quatre coudées, en coudées d’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Et nous avons pris possession de ce pays-là, en ce même temps. Depuis Aroër, qui est sur le torrent de l’Arnon, la moitié de la montagne de Galaad, et ses villes, je les donnai aux Rubénites et aux Gadites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'et le reste de Galaad, et tout Basan, le royaume d’Og, je le donnai à la demi-tribu de Manassé. (Toute la région d’Argob, comme tout Basan, était appelée le pays des Rephaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jaïr, fils de Manassé, prit toute la région d’Argob, jusqu’à la frontière des Gueshuriens et des Maacathiens; et il appela de son nom Basan, Havoth-Jaïr, [ce qui est son nom] jusqu’à aujourd’hui.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Et je donnai Galaad à Makir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Et aux Rubénites et aux Gadites je donnai depuis Galaad jusqu’au torrent de l’Arnon, le milieu du torrent et ce qui y confine, et jusqu’au torrent du Jabbok, frontière des fils d’Ammon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'et la plaine, et le Jourdain et [sa] rive depuis Kinnéreth jusqu’à la mer de la plaine, la mer Salée, sous les pentes du Pisga, vers le levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Et, en ce temps-là, je vous commandai, disant: L’ Éternel, votre Dieu, vous a donné ce pays pour le posséder; vous passerez équipés devant vos frères, les fils d’Israël, vous tous, les hommes valides.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Seulement, vos femmes, et vos enfants, et vos troupeaux – je sais que vos troupeaux sont nombreux – demeureront dans vos villes que je vous ai données,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'jusqu’à ce que l’ Éternel ait donné du repos à vos frères comme à vous, et qu’eux aussi possèdent le pays que l’ Éternel, votre Dieu, leur donne au-delà du Jourdain; alors vous retournerez chacun dans sa possession, que je vous ai donnée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Et je commandai à Josué en ce temps-là, disant: Tes yeux ont vu tout ce que l’ Éternel, votre Dieu, a fait à ces deux rois; l’ Éternel fera ainsi à tous les royaumes où tu vas passer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Ne les craignez pas; car l’ Éternel, votre Dieu, est celui qui combat pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Et en ce temps-là, je suppliai l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Seigneur Éternel! tu as commencé à faire voir à ton serviteur ta grandeur et ta main forte, car quel est le ✶Dieu, dans les cieux et sur la terre, qui fasse [des œuvres] comme tes œuvres et selon ta force?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Que je passe, je te prie, et que je voie ce bon pays qui est au-delà du Jourdain, cette bonne montagne, et le Liban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, '– Et l’ Éternel fut irrité contre moi à cause de vous, et il ne m’écouta point; et l’ Éternel me dit: C’est assez, ne me parle plus de cette affaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Monte au sommet du Pisga, et élève tes yeux vers l’occident, et vers le nord, et vers le midi, et vers le levant, et regarde de tes yeux; car tu ne passeras pas ce Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Mais commande à Josué, et fortifie-le et affermis-le; car lui, passera devant ce peuple, et lui, les mettra en possession du pays que tu verras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Et nous avons habité dans la vallée, vis-à-vis de Beth-Péor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, '*Et maintenant, Israël, écoute les statuts et les ordonnances que je vous enseigne, pour les pratiquer, afin que vous viviez, et que vous entriez dans le pays que l’ Éternel, le Dieu de vos pères, vous donne, et que vous le possédiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Vous n’ajouterez rien à la parole que je vous commande, et vous n’en retrancherez rien, afin de garder les commandements de l’ Éternel, votre Dieu, que je vous commande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Vos yeux ont vu ce que l’ Éternel a fait à cause de Baal-Péor; car tout homme qui était allé après Baal-Péor, l’ Éternel, ton Dieu, l’a détruit du milieu de toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'et vous qui vous êtes tenus attachés à l’ Éternel, votre Dieu, vous êtes tous vivants aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Regarde, je vous ai enseigné les statuts et les ordonnances, comme l’ Éternel, mon Dieu, me l’a commandé, afin que vous fassiez ainsi au milieu du pays où vous allez entrer pour le posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Et vous les garderez et les pratiquerez; car ce sera là votre sagesse et votre intelligence aux yeux des peuples qui entendront tous ces statuts et diront: Quel peuple sage et intelligent que cette grande nation!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Car quelle est la grande nation qui ait Dieu près d’elle, comme l’ Éternel, notre Dieu, [est près de nous], dans tout ce pour quoi nous l’invoquons?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Et quelle est la grande nation qui ait des statuts et des ordonnances justes, comme toute cette loi que je mets aujourd’hui devant vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Seulement, prends garde à toi et garde soigneusement ton âme, de peur que tu n’oublies les choses que tes yeux ont vues (et afin que, tous les jours de ta vie, elles ne s’éloignent pas de ton cœur, mais que tu les fasses connaître à tes fils et aux fils de tes fils),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'le jour où tu te tins devant l’ Éternel, ton Dieu, à Horeb, quand l’ Éternel me dit: Assemble-moi le peuple, et je leur ferai entendre mes paroles, qu’ils apprendront pour me craindre tous les jours qu’ils seront vivants sur la terre, et qu’ils enseigneront à leurs fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'alors vous vous êtes approchés et vous vous êtes tenus au bas de la montagne (et la montagne était brûlante de feu jusqu’au cœur des cieux,... ténèbres, nuées, et profonde obscurité),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'et l’ Éternel vous parla du milieu du feu; vous entendiez la voix de [ses] paroles, mais vous n’avez vu aucune forme, seulement [vous entendiez] une voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Et il vous déclara son alliance, qu’il vous commanda de pratiquer, les dix paroles; et il les écrivit sur deux tables de pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Et l’ Éternel me commanda, en ce temps-là, de vous enseigner des statuts et des ordonnances, pour que vous les pratiquiez dans le pays dans lequel vous allez passer pour le posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Et vous prendrez bien garde à vos âmes (car vous n’avez vu aucune forme au jour où l’ Éternel vous parla du milieu du feu, à Horeb),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'de peur que vous ne vous corrompiez, et que vous ne vous fassiez quelque image taillée, la forme d’une image quelconque, la figure d’un mâle ou d’une femelle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'la figure de quelque bête qui soit sur la terre, la figure de quelque oiseau ailé qui vole dans les cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'la figure de quelque reptile du sol, la figure de quelque poisson qui soit dans les eaux, au-dessous de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'et de peur que tu ne lèves tes yeux vers les cieux et que tu ne voies le soleil, et la lune et les étoiles, toute l’armée des cieux, et que tu ne te laisses séduire et ne te prosternes devant eux, et ne les serves: lesquels l’ Éternel, ton Dieu, a donnés en partage à tous les peuples, sous tous les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Mais vous, l’ Éternel vous a pris, et vous a fait sortir d’Égypte, de la fournaise de fer, afin que vous soyez le peuple de sa possession, comme [vous l’êtes] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Et l’ Éternel s’irrita contre moi, à cause de vous, et il jura que je ne passerais pas le Jourdain et que je n’entrerais pas dans le bon pays que l’ Éternel, ton Dieu, te donne en héritage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'car, pour moi, je mourrai dans ce pays, je ne passerai pas le Jourdain; mais vous allez le passer, et vous posséderez ce bon pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Prenez garde à vous, de peur que vous n’oubliiez l’alliance de l’ Éternel, votre Dieu, qu’il a traitée avec vous, et que vous ne vous fassiez une image taillée, la forme d’une chose quelconque, – ce que l’ Éternel, ton Dieu, t’a commandé [de ne pas faire].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Car l’ Éternel, ton Dieu, est un feu consumant, un ✶Dieu jaloux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Quand tu auras engendré des fils et des petits-fils, et que vous aurez vécu longtemps dans le pays, et que vous vous serez corrompus, et que vous aurez fait une image taillée, la forme d’une chose quelconque, et que vous aurez fait ce qui est mauvais aux yeux de l’ Éternel, ton Dieu, pour le provoquer à colère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'j’appelle aujourd’hui à témoin contre vous les cieux et la terre, que vous périrez bientôt entièrement de dessus le pays où, en passant le Jourdain, vous [entrez] afin de le posséder; vous n’y prolongerez pas vos jours, car vous serez entièrement détruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Et l’ Éternel vous dispersera parmi les peuples; et vous resterez en petit nombre parmi les nations où l’ Éternel vous mènera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Et vous servirez là des dieux, ouvrage de mains d’homme, du bois et de la pierre, qui ne voient, ni n’entendent, ni ne mangent, ni ne flairent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Et de là vous chercherez l’ Éternel, ton Dieu; et tu le trouveras, si tu le cherches de tout ton cœur et de toute ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Dans ta détresse, et lorsque toutes ces choses t’auront atteint, à la fin des jours, tu retourneras à l’ Éternel, ton Dieu, et tu écouteras sa voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Car l’ Éternel, ton Dieu, est un ✶Dieu miséricordieux, il ne t’abandonnera pas et ne te détruira pas; et il n’oubliera pas l’alliance de tes pères, qu’il leur a jurée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Car, enquiers-toi donc des premiers jours qui ont été avant toi, depuis le jour où Dieu a créé l’homme sur la terre, et d’un bout des cieux jusqu’à l’autre bout des cieux, si [jamais] il est rien arrivé comme cette grande chose, et s’il a été rien entendu de semblable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Est-ce qu’un peuple a entendu la voix de Dieu parlant du milieu du feu, comme toi tu l’as entendue, et est demeuré en vie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Ou Dieu a-t-il essayé de venir prendre pour lui une nation du milieu d’une nation, par des épreuves, par des signes, et par des prodiges, et par la guerre, et à main forte, et à bras étendu, et par de grandes terreurs, selon tout ce que l’ Éternel, votre Dieu, a fait pour vous en Égypte, sous tes yeux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Cela t’a été montré, afin que tu connaisses que l’ Éternel est Dieu, et qu’il n’y en a point d’autre que lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Des cieux, il t’a fait entendre sa voix pour t’instruire, et, sur la terre, il t’a fait voir son grand feu, et tu as entendu ses paroles du milieu du feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Et parce qu’il a aimé tes pères, et qu’il a choisi leur semence après eux, il t’a fait sortir d’Égypte par sa face, par sa grande puissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'pour déposséder devant toi des nations plus grandes et plus fortes que toi, pour t’introduire dans leur pays, afin de te le donner en héritage, comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Sache donc aujourd’hui, et médite en ton cœur, que l’ Éternel est Dieu dans les cieux en haut, et sur la terre en bas: il n’y en a point d’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Et garde ses statuts et ses commandements que je te commande aujourd’hui, afin que tu prospères, toi et tes fils après toi, et que tu prolonges tes jours sur la terre que l’ Éternel, ton Dieu, te donne, pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, '*Alors Moïse sépara trois villes, en deçà du Jourdain, vers le soleil levant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'afin que l’homicide qui aurait tué son prochain sans le savoir, et qui ne l’aurait pas haï auparavant, s’y enfuie, et que, s’enfuyant dans l’une de ces villes-là, il vive:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Bétser, dans le désert, sur le plateau, [qui est] aux Rubénites; et Ramoth, en Galaad, [qui est] aux Gadites; et Golan, en Basan, [qui est] aux Manassites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, '*Et c’est ici la loi que Moïse plaça devant les fils d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'ce sont ici les témoignages, et les statuts, et les ordonnances que Moïse exposa aux fils d’Israël, à leur sortie d’Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'en deçà du Jourdain, dans la vallée vis-à-vis de Beth-Péor, dans le pays de Sihon, roi des Amoréens, qui habitait à Hesbon, que Moïse et les fils d’Israël frappèrent à leur sortie d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'et ils possédèrent son pays, et le pays d’Og, roi de Basan, deux rois des Amoréens, qui étaient en deçà du Jourdain, vers le soleil levant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'depuis Aroër qui est sur le bord du torrent de l’Arnon, jusqu’à la montagne de Scion qui est l’Hermon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'et toute la plaine en deçà du Jourdain, vers le levant et jusqu’à la mer de la plaine, sous les pentes du Pisga.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Et Moïse appela tout Israël, et leur dit: Écoute, Israël, les statuts et les ordonnances que je prononce aujourd’hui à vos oreilles: vous les apprendrez, et vous les garderez pour les pratiquer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'L’ Éternel, notre Dieu, fit avec nous une alliance à Horeb.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Ce n’est pas avec nos pères que l’ Éternel a fait cette alliance, mais avec nous, avec nous qui sommes ici aujourd’hui tous vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'L’ Éternel vous parla face à face, sur la montagne, du milieu du feu');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '(moi, je me tenais en ce temps-là entre l’ Éternel et vous, pour vous déclarer la parole de l’ Éternel, car vous aviez peur à cause du feu et vous n’êtes point montés sur la montagne), disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Je suis l’ Éternel, ton Dieu, qui t’ai fait sortir du pays d’Égypte, de la maison de servitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Tu n’auras point d’autres dieux devant ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Tu ne te feras point d’image taillée, aucune ressemblance de ce qui est dans les cieux en haut, ni de ce qui est sur la terre en bas, ni de ce qui est dans les eaux au-dessous de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Tu ne t’inclineras point devant elles et tu ne les serviras point; car moi, l’ Éternel, ton Dieu, je suis un ✶Dieu jaloux, qui visite l’iniquité des pères sur les fils, et sur la troisième et sur la quatrième [génération] de ceux qui me haïssent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'et qui use de bonté envers des milliers de ceux qui m’aiment et qui gardent mes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Tu ne prendras point le nom de l’ Éternel, ton Dieu, en vain; car l’ Éternel ne tiendra point pour innocent celui qui aura pris son nom en vain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Garde le jour du sabbat pour le sanctifier, comme l’ Éternel, ton Dieu, te l’a commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Six jours tu travailleras et tu feras toute ton œuvre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'mais le septième jour est le sabbat [consacré] à l’ Éternel, ton Dieu: tu ne feras aucune œuvre, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton bœuf, ni ton âne, ni aucune de tes bêtes, ni ton étranger qui est dans tes portes, afin que ton serviteur et ta servante se reposent comme toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'et tu te souviendras que tu as été serviteur dans le pays d’Égypte, et que l’ Éternel, ton Dieu, t’a fait sortir de là à main forte et à bras étendu; c’est pourquoi l’ Éternel, ton Dieu, t’a commandé de garder le jour du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Honore ton père et ta mère, comme l’ Éternel, ton Dieu, te l’a commandé, afin que tes jours soient prolongés, et afin que tu prospères sur la terre que l’ Éternel, ton Dieu, te donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Tu ne tueras point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Et tu ne commettras point adultère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Et tu ne déroberas point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Et tu ne diras point de faux témoignage contre ton prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Et tu ne convoiteras point la femme de ton prochain; et tu ne désireras point la maison de ton prochain, [ni] son champ, ni son serviteur, ni sa servante, [ni] son bœuf, ni son âne, ni rien qui soit à ton prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'L’ Éternel prononça ces paroles à toute votre congrégation, sur la montagne, du milieu du feu, de la nuée et de l’obscurité profonde, avec une voix forte, et il n’ajouta rien. Et il les écrivit sur deux tables de pierre, et me les donna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Et il arriva que, lorsque vous avez entendu la voix du milieu des ténèbres, la montagne étant brûlante de feu, vous vous êtes approchés de moi, tous les chefs de vos tribus et vos anciens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'et vous avez dit: Voici, l’ Éternel, notre Dieu, nous a fait voir sa gloire et sa grandeur, et nous avons entendu sa voix du milieu du feu; aujourd’hui nous avons vu que Dieu parle avec l’homme, et que [l’homme] vit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Et maintenant, pourquoi mourrions-nous? car ce grand feu nous dévorera; si nous entendons encore la voix de l’ Éternel, notre Dieu, nous mourrons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Car qui, de toute chair, a entendu, comme nous, la voix du Dieu vivant parlant du milieu du feu, et est demeuré en vie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Toi, approche, et écoute tout ce que dira l’ Éternel, notre Dieu; et toi tu nous diras tout ce que l’ Éternel, notre Dieu, t’aura dit, et nous l’écouterons, et nous le pratiquerons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Et l’ Éternel entendit la voix de vos paroles, lorsque vous me parliez; et l’ Éternel me dit: J’ai entendu la voix des paroles de ce peuple, qu’ils t’ont dites: tout ce qu’ils ont dit, ils l’ont bien dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Oh! s’ils avaient toujours ce cœur-là pour me craindre et pour garder tous mes commandements, afin de prospérer, eux et leurs fils, à toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Va, dis-leur: Retournez à vos tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Mais toi, tiens-toi ici auprès de moi, et je te dirai tous les commandements et les statuts et les ordonnances que tu leur enseigneras, afin qu’ils les pratiquent dans le pays que je leur donne pour le posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, '– Vous prendrez donc garde à faire comme l’ Éternel, votre Dieu, vous a commandé; vous ne vous écarterez ni à droite ni à gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Vous marcherez dans tout le chemin que l’ Éternel, votre Dieu, vous a commandé, afin que vous viviez, et que vous prospériez, et que vous prolongiez vos jours dans le pays que vous posséderez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, '*Et ce sont ici les commandements, les statuts, et les ordonnances, que l’ Éternel, votre Dieu, a commandé de vous enseigner, afin que vous les pratiquiez dans le pays dans lequel vous passez pour le posséder;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'afin que tu craignes l’ Éternel, ton Dieu, pour garder, tous les jours de ta vie, toi, et ton fils, et le fils de ton fils, tous ses statuts et ses commandements que je te commande, et afin que tes jours soient prolongés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Et tu écouteras, Israël! et tu prendras garde à les pratiquer, afin que tu prospères, et que vous multipliiez beaucoup dans un pays ruisselant de lait et de miel, comme l’ Éternel, le Dieu de tes pères, te l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Écoute, Israël: L’ Éternel, notre Dieu, est un seul Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Et tu aimeras l’ Éternel, ton Dieu, de tout ton cœur, et de toute ton âme, et de toute ta force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Et ces paroles, que je te commande aujourd’hui, seront sur ton cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Tu les inculqueras à tes fils, et tu en parleras, quand tu seras assis dans ta maison, et quand tu marcheras par le chemin, et quand tu te coucheras, et quand tu te lèveras;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'et tu les lieras comme un signe sur ta main, et elles te seront pour fronteau entre les yeux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'et tu les écriras sur les poteaux de ta maison et sur tes portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Et il arrivera, quand l’ Éternel, ton Dieu, t’aura introduit dans le pays qu’il a juré à tes pères, à Abraham, à Isaac, et à Jacob, de te donner: de grandes et bonnes villes que tu n’as pas bâties,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'et des maisons pleines de tout bien que tu n’as pas remplies, et des puits creusés que tu n’as pas creusés, des vignes et des oliviers que tu n’as pas plantés; et que tu mangeras, et que tu seras rassasié;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, '[alors] prends garde à toi, de peur que tu n’oublies l’ Éternel qui t’a fait sortir du pays d’Égypte, de la maison de servitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Tu craindras l’ Éternel, ton Dieu, et tu le serviras, et tu jureras par son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Vous n’irez point après d’autres dieux, d’entre les dieux des peuples qui seront autour de vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'car l’ Éternel, ton Dieu, qui est au milieu de toi, est un ✶Dieu jaloux; de peur que la colère de l’ Éternel, ton Dieu, ne s’embrase contre toi, et qu’il ne te détruise de dessus la face de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Vous ne tenterez point l’ Éternel, votre Dieu, comme vous l’avez tenté à Massa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Vous garderez soigneusement les commandements de l’ Éternel, votre Dieu, et ses témoignages et ses statuts qu’il t’a commandés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Et tu feras ce qui est droit et bon aux yeux de l’ Éternel, afin que tu prospères, et que tu entres dans le bon pays que l’ Éternel a promis par serment à tes pères, et que tu le possèdes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'en chassant tous tes ennemis de devant toi, comme l’ Éternel l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Quand ton fils t’interrogera à l’avenir, disant: Que sont les témoignages, et les statuts et les ordonnances que l’ Éternel, notre Dieu, vous a commandés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'alors tu diras à ton fils: Nous étions serviteurs du Pharaon en Égypte, et l’ Éternel nous a fait sortir d’Égypte à main forte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'et l’ Éternel a opéré, devant nos yeux, des signes et des prodiges, grands et accablants, sur l’Égypte, sur le Pharaon, et sur toute sa maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'et il nous a fait sortir de là, pour nous faire entrer dans le pays qu’il avait promis par serment à nos pères, pour nous le donner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Et l’ Éternel nous a commandé de pratiquer tous ces statuts, de craindre l’ Éternel, notre Dieu, pour notre bien, toujours, pour nous conserver en vie, comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Et ce sera notre justice, que nous prenions garde à pratiquer tous ces commandements devant l’ Éternel, notre Dieu, comme il nous l’a commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Quand l’ Éternel, ton Dieu, t’aura introduit dans le pays où tu entres pour le posséder, et qu’il aura chassé de devant toi des nations nombreuses, le Héthien, et le Guirgasien, et l’Amoréen, et le Cananéen, et le Phérézien, et le Hévien, et le Jébusien, sept nations plus nombreuses et plus fortes que toi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'et que l’ Éternel, ton Dieu, les aura livrées devant toi, et que tu les auras frappées, tu les détruiras entièrement comme un anathème; tu ne traiteras point alliance avec elles, et tu ne leur feras pas grâce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Tu ne t’allieras point par mariage avec elles, tu ne donneras pas ta fille à leur fils, et tu ne prendras pas leur fille pour ton fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'car ils détourneraient de moi ton fils, et il servirait d’autres dieux, et la colère de l’ Éternel s’embraserait contre vous, et te détruirait aussitôt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Mais vous leur ferez ainsi: Vous démolirez leurs autels, et vous briserez leurs statues, et vous abattrez leurs ashères, et vous brûlerez au feu leurs images taillées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Car tu es un peuple saint, [consacré] à l’ Éternel, ton Dieu; l’ Éternel, ton Dieu, t’a choisi, afin que tu sois pour lui un peuple qui lui appartienne en propre, d’entre tous les peuples qui sont sur la face de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Ce n’est pas parce que vous étiez plus nombreux que tous les peuples, que l’ Éternel s’est attaché à vous et vous a choisis; car vous êtes le plus petit de tous les peuples;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'mais parce que l’ Éternel vous a aimés et parce qu’il garde le serment qu’il a juré à vos pères, l’ Éternel vous a fait sortir à main forte, et t’a racheté de la maison de servitude, de la main du Pharaon, roi d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Connais donc que c’est l’ Éternel, ton Dieu, qui est Dieu, le ✶Dieu fidèle, qui garde l’alliance et la bonté jusqu’à 1 000 générations à ceux qui l’aiment et qui gardent ses commandements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'et qui récompense en face ceux qui le haïssent, pour les faire périr: il ne différera pas à l’égard de celui qui le hait; il le récompensera en face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Et tu garderas les commandements, et les statuts et les ordonnances que je te commande aujourd’hui, pour les pratiquer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Et, si vous écoutez ces ordonnances, et que vous les gardiez et les fassiez, il arrivera que l’ Éternel, ton Dieu, te gardera l’alliance et la bonté qu’il a jurées à tes pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Et il t’aimera, et te bénira, et te multipliera; et il bénira le fruit de ton ventre, et le fruit de ta terre, ton froment, et ton moût, et ton huile, et la portée de ton gros bétail, et l’accroissement de ton menu bétail, sur la terre qu’il a juré à tes pères de te donner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Tu seras béni plus que tous les peuples; il n’y aura, parmi toi et parmi tes bêtes, ni mâle ni femelle stérile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'et l’ Éternel éloignera de toi toute maladie, et il ne mettra sur toi aucune des plaies malignes de l’Égypte, que tu as connues, mais il les mettra sur tous ceux qui te haïssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Et tu consumeras tous les peuples que l’ Éternel, ton Dieu, te livre; ton œil ne les épargnera pas, et tu ne serviras pas leurs dieux, car ce serait un piège pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Si tu dis dans ton cœur: Ces nations sont plus nombreuses que moi, comment pourrai-je les déposséder?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'ne les crains point; souviens-toi de ce que l’ Éternel, ton Dieu, a fait au Pharaon et à toute l’Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'de ces grandes épreuves que tes yeux ont vues, et des signes et des prodiges, et de la main forte et du bras étendu, par lesquels l’ Éternel, ton Dieu, t’a fait sortir: ainsi fera l’ Éternel, ton Dieu, à tous les peuples dont tu as peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Et l’ Éternel, ton Dieu, enverra aussi les frelons contre eux, jusqu’à ce que ceux qui seront restés et ceux qui se seront cachés devant toi aient péri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Tu ne t’épouvanteras pas à cause d’eux, car l’ Éternel, ton Dieu, est au milieu de toi, un ✶Dieu grand et terrible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Et l’ Éternel, ton Dieu, chassera ces nations de devant toi peu à peu. Tu ne pourras pas les détruire tout aussitôt, de peur que les bêtes des champs ne se multiplient contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Mais l’ Éternel, ton Dieu, les livrera devant toi, et les jettera dans une grande confusion, jusqu’à ce qu’il les ait détruites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'et il livrera leurs rois en ta main, et tu feras périr leur nom de dessous les cieux; nul ne tiendra devant toi, jusqu’à ce que tu les aies détruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Vous brûlerez au feu les images taillées de leurs dieux; tu ne désireras pas l’argent ou l’or qui sont dessus, et tu ne les prendras pas pour toi, de peur que, par là, tu ne sois pris dans un piège; car c’est une abomination pour l’ Éternel, ton Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'afin que tu n’introduises pas l’abomination dans ta maison, et que tu ne sois pas anathème comme elle: tu l’auras en extrême horreur et en extrême abomination; car c’est un anathème.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Vous prendrez garde à pratiquer tous les commandements que je vous commande aujourd’hui, afin que vous viviez, et que vous multipliiez, et que vous entriez dans le pays que l’ Éternel a promis par serment à vos pères, et que vous le possédiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Et tu te souviendras de tout le chemin par lequel l’ Éternel, ton Dieu, t’a fait marcher ces 40 ans, dans le désert, afin de t’humilier, [et] de t’éprouver, pour connaître ce qui était dans ton cœur, si tu garderais ses commandements, ou non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Et il t’a humilié, et t’a fait avoir faim; et il t’a fait manger la manne que tu n’avais pas connue et que tes pères n’ont pas connue, afin de te faire connaître que l’homme ne vit pas de pain seulement, mais que l’homme vivra de tout ce qui sort de la bouche de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Ton vêtement ne s’est point usé sur toi, et ton pied ne s’est point enflé, pendant ces 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Connais dans ton cœur que, comme un homme châtie son fils, l’ Éternel, ton Dieu, te châtie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'et garde les commandements de l’ Éternel, ton Dieu, pour marcher dans ses voies et pour le craindre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Car l’ Éternel, ton Dieu, te fait entrer dans un bon pays, un pays de ruisseaux d’eau, de sources, et d’eaux profondes, qui sourdent dans les vallées et dans les montagnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'un pays de froment, et d’orge, et de vignes, et de figuiers, et de grenadiers, un pays d’oliviers à huile, et de miel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'un pays où tu ne mangeras pas [ton] pain dans la pauvreté, où tu ne manqueras de rien; un pays dont les pierres sont du fer, et des montagnes duquel tu tailleras l’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Et tu mangeras, et tu seras rassasié, et tu béniras l’ Éternel, ton Dieu, à cause du bon pays qu’il t’a donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Prends garde à toi, de peur que tu n’oublies l’ Éternel, ton Dieu, pour ne pas garder ses commandements, et ses ordonnances, et ses statuts, que je te commande aujourd’hui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'de peur que, quand tu mangeras, et que tu seras rassasié, et que tu bâtiras de bonnes maisons et y habiteras,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'et que ton gros et ton menu bétail se multipliera, et que l’argent et l’or te seront multipliés, et que tout ce qui est à toi se multipliera,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'alors ton cœur ne s’élève, et que tu n’oublies l’ Éternel, ton Dieu, qui t’a fait sortir du pays d’Égypte, de la maison de servitude;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'qui t’a fait marcher dans le désert grand et terrible, [désert] de serpents brûlants et de scorpions, une terre aride où il n’y a point d’eau; qui a fait sortir pour toi de l’eau du roc dur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'qui t’a fait manger dans le désert la manne que tes pères n’ont pas connue, afin de t’humilier et afin de t’éprouver, pour te faire du bien à la fin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, '– et que tu ne dises dans ton cœur: Ma puissance et la force de ma main m’ont acquis ces richesses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Mais tu te souviendras de l’ Éternel, ton Dieu, que c’est lui qui te donne de la force pour acquérir ces richesses, afin de ratifier son alliance, qu’il a jurée à tes pères, comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Et s’il arrive que tu oublies en aucune manière l’ Éternel, ton Dieu, et que tu ailles après d’autres dieux, et que tu les serves et que tu t’inclines devant eux, je rends témoignage aujourd’hui contre vous que vous périrez entièrement:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'comme les nations que l’ Éternel fait périr devant vous, ainsi vous périrez, parce que vous n’aurez pas écouté la voix de l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Écoute, Israël: Tu passes aujourd’hui le Jourdain, pour entrer, pour posséder des nations plus grandes et plus fortes que toi, des villes grandes et murées jusqu’aux cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'un peuple grand et de haute stature, les fils des Anakim, que tu connais et dont tu as entendu dire: Qui peut tenir devant les fils d’Anak?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Et sache aujourd’hui que l’ Éternel, ton Dieu, c’est lui qui passe devant toi, un feu consumant; c’est lui qui les détruira, et lui qui les abattra devant toi; et tu les déposséderas, et tu les feras périr subitement, comme l’ Éternel te l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Ne parle pas en ton cœur, quand l’ Éternel, ton Dieu, les aura chassés de devant toi, disant: C’est à cause de ma justice que l’ Éternel m’a fait entrer pour posséder ce pays. Mais c’est à cause de la méchanceté de ces nations que l’ Éternel les dépossède devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ce n’est point à cause de ta justice, ni à cause de la droiture de ton cœur, que tu entres pour posséder leur pays; car c’est à cause de la méchanceté de ces nations, que l’ Éternel, ton Dieu, les dépossède devant toi, et afin de ratifier la parole que l’ Éternel a jurée à tes pères, à Abraham, à Isaac, et à Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Et sache que ce n’est pas à cause de ta justice que l’ Éternel, ton Dieu, te donne ce bon pays pour le posséder; car tu es un peuple de cou roide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Souviens-toi, [et] n’oublie pas comment tu as excité à colère l’ Éternel, ton Dieu, dans le désert: depuis le jour où tu es sorti du pays d’Égypte, jusqu’à votre arrivée en ce lieu, vous avez été rebelles contre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Et à Horeb, vous avez excité à colère l’ Éternel, et l’ Éternel s’irrita contre vous, pour vous détruire:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'quand je montai sur la montagne pour recevoir les tables de pierre, les tables de l’alliance que l’ Éternel avait faite avec vous, je demeurai sur la montagne 40 jours et 40 nuits; je ne mangeai point de pain, et je ne bus point d’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'et l’ Éternel me donna les deux tables de pierre, écrites du doigt de Dieu; et sur elles étaient écrites toutes les paroles que l’ Éternel vous avait dites sur la montagne, du milieu du feu, le jour de la congrégation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'et il arriva, au bout de 40 jours et de 40 nuits, que l’ Éternel me donna les deux tables de pierre, les tables de l’alliance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'et l’ Éternel me dit: Lève-toi, descends promptement d’ici, car ton peuple, que tu as fait sortir d’Égypte, s’est corrompu; ils se sont vite détournés du chemin que je leur avais commandé, ils se sont fait une image de fonte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Et l’ Éternel me parla, disant: J’ai vu ce peuple, et voici, c’est un peuple de cou roide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Laisse-moi, et je les détruirai, et j’effacerai leur nom de dessous les cieux; et je ferai de toi une nation plus forte et plus nombreuse qu’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Et je me tournai, et je descendis de la montagne (et la montagne était brûlante de feu), et les deux tables de l’alliance étaient sur mes deux mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Et je vis, et voici, vous aviez péché contre l’ Éternel, votre Dieu; vous vous étiez fait un veau de fonte; vous vous étiez vite détournés du chemin que l’ Éternel vous avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Et je saisis les deux tables, et les jetai de dessus mes deux mains, et je les brisai devant vos yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Et je me prosternai devant l’ Éternel, comme au commencement, 40 jours et 40 nuits; je ne mangeai point de pain et je ne bus point d’eau, à cause de tout votre péché que vous aviez commis, en faisant ce qui est mauvais aux yeux de l’ Éternel, afin de le provoquer à colère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'car j’eus peur de la colère et de la fureur dont l’ Éternel était courroucé contre vous, pour vous détruire; et l’ Éternel m’écouta aussi cette fois-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Et l’ Éternel fut fort irrité contre Aaron, pour le détruire; et j’intercédai aussi pour Aaron, en ce temps-là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'et je pris votre péché, le veau que vous aviez fait, et je le brûlai au feu, et je le pilai, je le moulus bien, jusqu’à ce qu’il soit réduit en poudre, et j’en jetai la poudre dans le torrent qui descendait de la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Et à Tabhéra, et à Massa, et à Kibroth-Hattaava, vous avez excité à colère l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Et lorsque l’ Éternel vous envoya de Kadès-Barnéa, en disant: Montez, et possédez le pays que je vous ai donné, vous avez été rebelles au commandement de l’ Éternel, votre Dieu, et vous ne l’avez point cru, et vous n’avez pas écouté sa voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Vous avez été rebelles à l’ Éternel depuis le jour où je vous ai connus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Et je me prosternai devant l’ Éternel, les 40 jours et les 40 nuits pendant lesquels je me prosternai [devant lui]; car l’ Éternel avait dit qu’il vous détruirait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Et je suppliai l’ Éternel, et je dis: Seigneur Éternel! ne détruis pas ton peuple, et ton héritage, que tu as racheté par ta grandeur, que tu as fait sortir d’Égypte à main forte!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Souviens-toi de tes serviteurs, d’Abraham, d’Isaac, et de Jacob; ne regarde pas à la dureté de ce peuple, et à sa méchanceté, et à son péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'de peur qu’on ne dise dans le pays d’où tu nous as fait sortir: Parce que l’ Éternel ne pouvait pas les faire entrer dans le pays qu’il leur avait promis, et parce qu’il les haïssait, il les a fait sortir pour les faire mourir dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Or ils sont ton peuple et ton héritage, que tu as fait sortir par ta grande puissance et par ton bras étendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'En ce temps-là, l’ Éternel me dit: Taille-toi deux tables de pierre comme les premières, et monte vers moi sur la montagne, et fais-toi une arche de bois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'et j’écrirai sur les tables les paroles qui étaient sur les premières tables que tu as brisées, et tu les mettras dans l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Et je fis une arche de bois de sittim, et je taillai deux tables de pierre comme les premières; et je montai sur la montagne, les deux tables dans ma main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, '– Et il écrivit sur les tables, selon ce qu’il avait écrit la première fois, les dix paroles que l’ Éternel vous avait dites sur la montagne, du milieu du feu, le jour de la congrégation; et l’ Éternel me les donna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Et je me tournai, et je descendis de la montagne, et je mis les tables dans l’arche que j’avais faite, et elles sont là, comme l’ Éternel me l’avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, '(Et les fils d’Israël partirent de Beéroth-Bené-Jaakan pour Moséra. Là mourut Aaron, et il y fut enseveli; et Éléazar, son fils, exerça la sacrificature à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'De là ils partirent pour Gudgoda, et de Gudgoda pour Jotbatha, un pays de ruisseaux d’eau.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, '– En ce temps-là, l’ Éternel sépara la tribu de Lévi pour porter l’arche de l’alliance de l’ Éternel, pour se tenir devant l’ Éternel, pour faire son service, et pour bénir en son nom, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'C’est pourquoi Lévi n’a point de part ni d’héritage avec ses frères; l’ Éternel est son héritage, comme l’ Éternel, ton Dieu, le lui a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Et moi, je me tins sur la montagne comme les jours précédents, 40 jours et 40 nuits; et l’ Éternel m’écouta aussi cette fois-là: l’ Éternel ne voulut pas te détruire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Et l’ Éternel me dit: Lève-toi, va, pour marcher devant le peuple, et qu’ils entrent dans le pays que j’ai juré à leurs pères de leur donner, et qu’ils le possèdent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Et maintenant, Israël! qu’est-ce que l’ Éternel, ton Dieu, demande de toi, sinon que tu craignes l’ Éternel, ton Dieu, pour marcher dans toutes ses voies, et pour l’aimer, et pour servir l’ Éternel, ton Dieu, de tout ton cœur et de toute ton âme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'en gardant les commandements de l’ Éternel, et ses statuts, que je te commande aujourd’hui, pour ton bien?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Voici, à l’ Éternel, ton Dieu, appartiennent les cieux, et les cieux des cieux, la terre et tout ce qui est en elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Cependant l’ Éternel s’est attaché à tes pères pour les aimer; et il vous a choisis, vous, leur semence, après eux, d’entre tous les peuples, comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Circoncisez donc votre cœur, et ne roidissez plus votre cou;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'car l’ Éternel, votre Dieu, est le Dieu des dieux et le Seigneur des seigneurs, le ✶Dieu grand, puissant, et terrible, qui ne fait point acception de personnes, et qui ne prend pas de présents;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'qui fait droit à l’orphelin et à la veuve, et qui aime l’étranger pour lui donner le pain et le vêtement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Et vous aimerez l’étranger; car vous avez été étrangers dans le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Tu craindras l’ Éternel, ton Dieu; tu le serviras, et tu t’attacheras à lui, et tu jureras par son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Lui est ta louange, et lui est ton Dieu, qui a fait pour toi ces choses grandes et terribles que tes yeux ont vues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Tes pères sont descendus en Égypte au nombre de 70 âmes; et maintenant l’ Éternel, ton Dieu, t’a fait devenir comme les étoiles des cieux, en multitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Tu aimeras donc l’ Éternel, ton Dieu, et tu garderas ce qu’il te donne à garder, et ses statuts, et ses ordonnances, et ses commandements, toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Et vous savez aujourd’hui,... car [je ne parle] pas à vos fils, qui n’ont pas connu et n’ont pas vu le châtiment de l’ Éternel, votre Dieu, sa grandeur, sa main forte, et son bras étendu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'et ses signes et ses œuvres, qu’il a faits au milieu de l’Égypte, au Pharaon, roi d’Égypte, et à tout son pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'et ce qu’il a fait à l’armée de l’Égypte, à ses chevaux et à ses chars, sur lesquels il a fait déborder les eaux de la mer Rouge, lorsqu’ils vous poursuivaient, et l’ Éternel les a fait périr, jusqu’à aujourd’hui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, '– et ce qu’il vous a fait dans le désert, jusqu’à ce que vous soyez arrivés en ce lieu-ci;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'et ce qu’il a fait à Dathan et à Abiram, les fils d’Éliab, fils de Ruben, quand la terre ouvrit sa bouche, et les engloutit, avec leurs maisons et leurs tentes et tout ce qui était à leur suite, au milieu de tout Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'car ce sont vos yeux qui ont vu toute la grande œuvre de l’ Éternel, qu’il a faite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Vous garderez donc tout le commandement que je vous commande aujourd’hui, afin que vous soyez forts, et que vous entriez, et que vous possédiez le pays dans lequel vous passez pour le posséder,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'et afin que vous prolongiez vos jours sur la terre que l’ Éternel a juré à vos pères de leur donner, à eux et à leur semence, un pays ruisselant de lait et de miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Car le pays où tu entres pour le posséder n’est pas comme le pays d’Égypte d’où vous êtes sortis, où tu semais ta semence et où tu l’arrosais avec ton pied comme un jardin à légumes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Mais le pays dans lequel vous allez passer pour le posséder est un pays de montagnes et de vallées; il boit l’eau de la pluie des cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, '– un pays dont l’ Éternel, ton Dieu, a soin, sur lequel l’ Éternel, ton Dieu, a continuellement les yeux, depuis le commencement de l’année jusqu’à la fin de l’année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, '– Et il arrivera que, si vous écoutez attentivement mes commandements que je vous commande aujourd’hui, pour aimer l’ Éternel, votre Dieu, et pour le servir de tout votre cœur et de toute votre âme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'alors je donnerai la pluie de votre pays en son temps, la pluie de la première saison et la pluie de la dernière saison; et tu recueilleras ton froment, et ton moût, et ton huile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'et je donnerai l’herbe dans tes champs, pour ton bétail; et tu mangeras, et tu seras rassasié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Prenez garde à vous, de peur que votre cœur ne soit séduit, et que vous ne vous détourniez, et ne serviez d’autres dieux et ne vous prosterniez devant eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'et que la colère de l’ Éternel ne s’embrase contre vous, et qu’il ne ferme les cieux, en sorte qu’il n’y ait pas de pluie, et que la terre ne donne pas son rapport, et que vous périssiez rapidement de dessus ce bon pays que l’ Éternel vous donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Et mettez ces miennes paroles dans votre cœur et dans votre âme, et liez-les pour signes sur vos mains, et qu’elles soient comme des fronteaux entre vos yeux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'et vous les enseignerez à vos fils, en leur en parlant, quand tu seras assis dans ta maison, et quand tu marcheras par le chemin, et quand tu te coucheras, et quand tu te lèveras;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'et tu les écriras sur les poteaux de ta maison et sur tes portes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'afin que vos jours et les jours de vos fils, sur la terre que l’ Éternel a juré à vos pères de leur donner, soient multipliés comme les jours des cieux [qui sont] au-dessus de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Car si vous gardez soigneusement tout ce commandement que je vous commande, pour le pratiquer, en aimant l’ Éternel, votre Dieu, en marchant dans toutes ses voies et en vous attachant à lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'l’ Éternel dépossédera toutes ces nations devant vous; et vous prendrez possession de nations plus grandes et plus fortes que vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Tout lieu que foulera la plante de votre pied sera à vous: votre limite sera depuis le désert et le Liban, depuis le fleuve, le fleuve Euphrate, jusqu’à la mer d’occident.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Personne ne pourra tenir devant vous; l’ Éternel, votre Dieu, mettra la frayeur et la crainte de vous sur la face de tout le pays que vous foulerez, comme il vous l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Regarde, je mets aujourd’hui devant vous la bénédiction et la malédiction:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'la bénédiction, si vous écoutez les commandements de l’ Éternel, votre Dieu, que je vous commande aujourd’hui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'la malédiction, si vous n’écoutez pas les commandements de l’ Éternel, votre Dieu, et si vous vous détournez du chemin que je vous commande aujourd’hui, pour aller après d’autres dieux, que vous n’avez pas connus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Et il arrivera que, quand l’ Éternel, ton Dieu, t’aura fait entrer dans le pays où tu vas pour le posséder, tu mettras la bénédiction sur la montagne de Garizim, et la malédiction sur la montagne d’Ébal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Ces [montagnes] ne sont-elles pas de l’autre côté du Jourdain, par-delà le chemin du soleil couchant, qui traverse le pays des Cananéens qui habitent dans la plaine, vis-à-vis de Guilgal, à côté des chênes de Moré?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Car vous allez passer le Jourdain pour entrer, pour posséder le pays que l’ Éternel, votre Dieu, vous donne; et vous le posséderez, et vous y habiterez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Et vous prendrez garde à pratiquer tous les statuts et les ordonnances que je mets aujourd’hui devant vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, '*Ce sont ici les statuts et les ordonnances que vous garderez pour les pratiquer dans le pays que l’ Éternel, le Dieu de tes pères, te donne pour le posséder, tous les jours que vous vivrez sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Vous détruirez entièrement tous les lieux où les nations que vous déposséderez auront servi leurs dieux sur les hautes montagnes et sur les collines et sous tout arbre vert;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'et vous démolirez leurs autels, et vous briserez leurs statues; et vous brûlerez au feu leurs ashères, et vous abattrez les images taillées de leurs dieux, et vous ferez périr leur nom de ce lieu-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Vous ne ferez pas ainsi à l’ Éternel, votre Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'mais vous chercherez le lieu que l’ Éternel, votre Dieu, choisira d’entre toutes vos tribus pour y mettre son nom, le lieu où il habitera, et vous y viendrez;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'et vous apporterez là vos holocaustes, et vos sacrifices, et vos dîmes, et l’offrande élevée de vos mains, et vos vœux, et vos offrandes volontaires, et les premiers-nés de votre gros et de votre menu bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Et là, vous mangerez devant l’ Éternel, votre Dieu, et vous vous réjouirez, vous et vos maisons, dans toutes les choses auxquelles vous aurez mis la main, dans lesquelles l’ Éternel, ton Dieu, t’aura béni.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Vous ne ferez pas selon tout ce que nous faisons ici aujourd’hui, chacun ce qui est bon à ses yeux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'car, jusqu’à présent, vous n’êtes pas entrés dans le repos et dans l’héritage que l’ Éternel, ton Dieu, te donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Mais lorsque vous aurez passé le Jourdain, et que vous habiterez dans le pays que l’ Éternel, votre Dieu, vous fait hériter, et qu’il vous aura donné du repos à l’égard de tous vos ennemis, à l’entour, et que vous habiterez en sécurité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'alors il y aura un lieu que l’ Éternel, votre Dieu, choisira pour y faire habiter son nom; là vous apporterez tout ce que je vous commande, vos holocaustes, et vos sacrifices, vos dîmes, et l’offrande élevée de vos mains, et tout le choix de vos vœux que vous aurez voués à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Et vous vous réjouirez devant l’ Éternel, votre Dieu, vous, et vos fils, et vos filles, et vos serviteurs, et vos servantes, et le Lévite qui est dans vos portes, car il n’a point de part ni d’héritage avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Prends garde à toi, de peur que tu n’offres tes holocaustes dans tous les lieux que tu verras;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'mais dans le lieu que l’ Éternel choisira dans l’une de tes tribus, là tu offriras tes holocaustes, et là tu feras tout ce que je te commande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Toutefois, suivant tout le désir de ton âme, tu sacrifieras et tu mangeras de la chair dans toutes tes portes, selon la bénédiction de l’ Éternel, ton Dieu, qu’il t’aura donnée. Celui qui est impur et celui qui est pur en mangeront, comme [on mange] de la gazelle et du cerf;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'seulement, vous ne mangerez pas le sang: tu le verseras sur la terre, comme de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Tu ne pourras pas manger, dans tes portes, la dîme de ton froment, ou de ton moût, ou de ton huile, ni les premiers-nés de ton gros et de ton menu bétail, ni aucune des choses que tu auras vouées, ni tes offrandes volontaires, ni l’offrande élevée de ta main;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'mais tu les mangeras devant l’ Éternel, ton Dieu, au lieu que l’ Éternel, ton Dieu, aura choisi, toi, et ton fils, et ta fille, et ton serviteur, et ta servante, et le Lévite qui est dans tes portes; et tu te réjouiras devant l’ Éternel, ton Dieu, en tout ce à quoi tu auras mis la main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Prends garde à toi, de peur que tu ne délaisses le Lévite, tous les jours que tu seras sur ta terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Quand l’ Éternel, ton Dieu, aura étendu tes limites, comme il te l’a promis, et que tu diras: Je mangerai de la chair, parce que ton âme désirera de manger de la chair, tu mangeras de la chair, selon tout le désir de ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Si le lieu que l’ Éternel, ton Dieu, aura choisi pour y mettre son nom est loin de toi, alors tu sacrifieras de ton gros et de ton menu bétail, que l’ Éternel t’aura donné, comme je te l’ai commandé, et tu en mangeras dans tes portes, selon tout le désir de ton âme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'comme on mange de la gazelle et du cerf, ainsi tu en mangeras: celui qui est impur et celui qui est pur en mangeront également.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Seulement, tiens ferme à ne pas manger le sang, car le sang est la vie; et tu ne mangeras pas l’âme avec la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Tu n’en mangeras pas, tu le verseras sur la terre, comme de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Tu n’en mangeras pas, afin que tu prospères, toi et tes fils après toi, parce que tu auras fait ce qui est droit aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Toutefois les choses que tu auras sanctifiées, qui seront à toi, et celles que tu auras vouées, tu les prendras, et tu viendras au lieu que l’ Éternel aura choisi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'et tu offriras tes holocaustes, la chair et le sang, sur l’autel de l’ Éternel, ton Dieu, et le sang de tes sacrifices sera versé sur l’autel de l’ Éternel, ton Dieu, et tu en mangeras la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Prends garde à écouter toutes ces paroles que je te commande, afin que tu prospères, toi et tes fils après toi, à toujours, parce que tu auras fait ce qui est bon et droit aux yeux de l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Quand l’ Éternel, ton Dieu, aura retranché devant toi les nations vers lesquelles tu entres pour les posséder, et que tu les posséderas, et que tu habiteras dans leur pays,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'prends garde à toi, de peur que tu ne sois pris au piège pour faire comme elles, après qu’elles auront été détruites devant toi, et de peur que tu ne recherches leurs dieux, en disant: Comment ces nations servaient-elles leurs dieux? et je ferai de même, moi aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Tu ne feras pas ainsi à l’ Éternel, ton Dieu; car tout ce qui est en abomination à l’ Éternel, ce qu’il hait, ils l’ont fait à leurs dieux; car même ils ont brûlé au feu leurs fils et leurs filles à leurs dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Toutes les choses que je vous commande, vous prendrez garde à les pratiquer. Tu n’y ajouteras rien, et tu n’en retrancheras rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'S’il s’élève au milieu de toi un prophète, ou un songeur de songes, et qu’il te donne un signe ou un miracle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'et que le signe arrive, ou le miracle dont il t’avait parlé lorsqu’il disait: Allons après d’autres dieux, [des dieux] que tu n’as point connus, et servons-les;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'tu n’écouteras pas les paroles de ce prophète, ni ce songeur de songes, car l’ Éternel, votre Dieu, vous éprouve, pour savoir si vous aimez l’ Éternel, votre Dieu, de tout votre cœur et de toute votre âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Vous marcherez après l’ Éternel, votre Dieu; et vous le craindrez, et vous garderez ses commandements, et vous écouterez sa voix, et vous le servirez, et vous vous attacherez à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Et ce prophète, ou ce songeur de songes, sera mis à mort, car il a parlé de révolte contre l’ Éternel, votre Dieu, qui vous a fait sortir du pays d’Égypte et vous a rachetés de la maison de servitude, afin de te pousser hors de la voie dans laquelle l’ Éternel, ton Dieu, t’a commandé de marcher; et tu ôteras le mal du milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Si ton frère, fils de ta mère, ou ton fils, ou ta fille, ou la femme de ton cœur, ou ton ami, qui t’est comme ton âme, t’incite en secret, disant: Allons, et servons d’autres dieux, [des dieux] que tu n’as point connus, toi, ni tes pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'd’entre les dieux des peuples qui sont autour de vous, près de toi ou loin de toi, d’un bout de la terre à l’autre bout de la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'tu ne t’accorderas pas avec lui et tu ne l’écouteras pas; et ton œil ne l’épargnera pas, et tu n’auras pas pitié de lui, et tu ne le cacheras pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'mais tu le tueras certainement: ta main sera la première contre lui pour le mettre à mort, et la main de tout le peuple ensuite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'et tu l’assommeras de pierres, et il mourra, car il a cherché à t’entraîner loin de l’ Éternel, ton Dieu, qui t’a fait sortir du pays d’Égypte, de la maison de servitude;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'et tout Israël l’entendra et craindra, et ne fera plus une pareille méchante action au milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Si, dans l’une de tes villes que l’ Éternel, ton Dieu, te donne pour y habiter, tu entends dire:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Des hommes, fils de Bélial, sont sortis du milieu de toi, et ont incité les habitants de leur ville, disant: Allons, et servons d’autres dieux, [des dieux] que vous n’avez pas connus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'alors tu rechercheras, et tu t’informeras, et tu t’enquerras bien; et si c’est la vérité, si la chose est établie, si cette abomination a été commise au milieu de toi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'tu frapperas certainement par le tranchant de l’épée les habitants de cette ville; tu la détruiras entièrement, et tout ce qui y sera, et toutes ses bêtes, par le tranchant de l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Et tout son butin, tu le rassembleras au milieu de sa place, et tu brûleras tout entiers au feu la ville et tout son butin, à l’ Éternel, ton Dieu; et elle sera un monceau perpétuel, elle ne sera plus rebâtie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Et il ne s’attachera rien de cet anathème à ta main, afin que l’ Éternel revienne de l’ardeur de sa colère, et qu’il te fasse miséricorde, et ait compassion de toi, et qu’il te multiplie, comme il a juré à tes pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 19, 'quand tu écouteras la voix de l’ Éternel, ton Dieu, pour garder tous ses commandements que je te commande aujourd’hui, afin de pratiquer ce qui est droit aux yeux de l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Vous êtes les fils de l’ Éternel, votre Dieu: Vous ne vous ferez pas d’incisions, et vous ne vous ferez pas de tonsure entre les yeux, pour un mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Car tu es un peuple saint, [consacré] à l’ Éternel, ton Dieu, et l’ Éternel t’a choisi, afin que tu sois pour lui un peuple qui lui appartienne en propre, d’entre tous les peuples qui sont sur la face de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Tu ne mangeras aucune chose abominable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Ce sont ici les bêtes que vous mangerez: le bœuf, le mouton, et la chèvre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'le cerf, et la gazelle, et le daim, et le bouquetin, et le dishon, et le bœuf sauvage, et le mouflon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Et toute bête qui a l’ongle fendu et le [pied] complètement divisé en deux ongles, et qui rumine, parmi les bêtes, vous la mangerez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Seulement, de ceci vous ne mangerez pas, d’entre celles qui ruminent et d’entre celles qui ont l’ongle fendu [et] divisé: le chameau, et le lièvre, et le daman; car ils ruminent, mais ils n’ont pas l’ongle fendu; ils vous sont impurs:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'et le porc, car il a l’ongle fendu, mais il ne rumine pas; il vous est impur. Vous ne mangerez pas de leur chair, et vous ne toucherez pas leur corps mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, '– Vous mangerez de ceci, d’entre tout ce qui est dans les eaux: vous mangerez tout ce qui a des nageoires et des écailles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'et vous ne mangerez pas ce qui n’a point de nageoires et d’écailles; cela vous est impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, '– Vous mangerez tout oiseau pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Mais ceux-ci vous ne les mangerez pas: l’aigle, et l’orfraie, et l’aigle de mer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'et le faucon, et le milan, et l’autour, selon son espèce;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'et tout corbeau, selon son espèce;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'et l’autruche femelle, et l’autruche mâle, et la mouette, et l’épervier, selon son espèce;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'le hibou, et l’ibis, et le cygne,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'et le pélican, et le vautour, et le plongeon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'et la cigogne, et le héron, selon son espèce, et la huppe, et la chauve-souris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, '– Et tout reptile volant vous sera impur; on n’en mangera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Vous mangerez tout oiseau pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, '– Vous ne mangerez d’aucun corps mort; tu le donneras à l’étranger qui est dans tes portes, et il le mangera; ou tu le vendras au forain; car tu es un peuple saint, [consacré] à l’ Éternel, ton Dieu. – Tu ne cuiras pas le chevreau dans le lait de sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Tu dîmeras exactement tout le rapport de ta semence, que ton champ produira chaque année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Et tu mangeras devant l’ Éternel, ton Dieu, au lieu qu’il aura choisi pour y faire habiter son nom, la dîme de ton froment, de ton moût, et de ton huile, et les premiers-nés de ton gros et de ton menu bétail, afin que tu apprennes à craindre toujours l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Et si le chemin est trop long pour toi, de sorte que tu ne puisses les transporter, parce que le lieu que l’ Éternel, ton Dieu, aura choisi pour y mettre son nom, sera trop éloigné de toi, parce que l’ Éternel, ton Dieu, t’aura béni:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'alors tu les donneras pour de l’argent, et tu serreras l’argent dans ta main, et tu iras au lieu que l’ Éternel, ton Dieu, aura choisi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'et tu donneras l’argent pour tout ce que ton âme désirera, pour du gros ou du menu bétail, ou pour du vin ou pour des boissons fortes, pour tout ce que ton âme te demandera, et tu le mangeras là, devant l’ Éternel, ton Dieu, et tu te réjouiras, toi et ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Et tu ne délaisseras pas le Lévite qui est dans tes portes, car il n’a point de part ni d’héritage avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, '– Au bout de trois ans, tu mettras à part toute la dîme de ta récolte de cette année-là, et tu la déposeras dans tes portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Et le Lévite, qui n’a point de part ni d’héritage avec toi, et l’étranger, et l’orphelin, et la veuve, qui seront dans tes portes, viendront, et ils mangeront et seront rassasiés; afin que l’ Éternel, ton Dieu, te bénisse dans tout l’ouvrage de ta main, que tu fais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Au bout de sept ans, tu feras relâche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Et c’est ici la manière du relâche: tout créancier relâchera sa main du prêt qu’il aura fait à son prochain; il ne l’exigera pas de son prochain ou de son frère, car on aura proclamé le relâche de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Tu l’exigeras de l’étranger; mais ta main relâchera ce que ton frère aura de ce qui t’appartient,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'sauf quand il n’y aura point de pauvre au milieu de toi; car l’ Éternel te bénira abondamment dans le pays que l’ Éternel, ton Dieu, te donne en héritage pour le posséder,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'pourvu seulement que tu écoutes attentivement la voix de l’ Éternel, ton Dieu, pour prendre garde à pratiquer tout ce commandement que je te commande aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Car l’ Éternel, ton Dieu, te bénira, comme il t’a dit; et tu prêteras sur gage à beaucoup de nations, mais toi tu n’emprunteras pas sur gage; et tu domineras sur beaucoup de nations, et elles ne domineront pas sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Quand il y aura au milieu de toi un pauvre, quelqu’un de tes frères, dans l’une de tes portes, dans ton pays que l’ Éternel, ton Dieu, te donne, tu n’endurciras pas ton cœur, et tu ne fermeras pas ta main à ton frère pauvre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'mais tu lui ouvriras libéralement ta main, et tu lui prêteras sur gage, assez pour le besoin dans lequel il se trouve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Prends garde à toi, de peur qu’il n’y ait dans ton cœur quelque pensée de Bélial, et que tu ne dises: La septième année approche, l’année de relâche, et que ton œil ne soit méchant contre ton frère pauvre, et que tu ne lui donnes pas, et qu’il ne crie contre toi à l’ Éternel, et qu’il n’y ait du péché en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Tu lui donneras libéralement, et ton cœur ne sera pas triste quand tu lui donneras; car à cause de cela l’ Éternel, ton Dieu, te bénira dans toute ton œuvre, et dans tout ce à quoi tu mettras la main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Car le pauvre ne manquera pas au milieu du pays; c’est pourquoi je te commande, disant: Tu ouvriras libéralement ta main à ton frère, à ton affligé et à ton pauvre, dans ton pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Si ton frère, un Hébreu, homme ou femme, t’a été vendu, il te servira six ans, et, la septième année, tu le renverras libre de chez toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Et quand tu le renverras libre de chez toi, tu ne le renverras pas à vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Tu lui donneras libéralement de ton menu bétail, et de ton aire, et de ta cuve: tu lui donneras de ce en quoi l’ Éternel, ton Dieu, t’aura béni;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'et tu te souviendras que tu as été serviteur dans le pays d’Égypte, et que l’ Éternel, ton Dieu, t’a racheté; c’est pourquoi je te commande ces choses aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, '– Et s’il arrive qu’il te dise: Je ne sortirai pas de chez toi (car il t’aime, toi et ta maison, et il se trouve bien chez toi),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'alors tu prendras un poinçon et tu lui en perceras l’oreille contre la porte, et il sera ton serviteur pour toujours; et tu feras aussi de même avec ta servante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Ce ne sera pas à tes yeux chose pénible de le renvoyer libre de chez toi, car il t’a servi six ans, [ce qui te vaut] le double du salaire d’un mercenaire; et l’ Éternel, ton Dieu, te bénira dans tout ce que tu feras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Tu sanctifieras à l’ Éternel, ton Dieu, tout premier-né mâle qui naîtra parmi ton gros bétail ou ton menu bétail. Tu ne laboureras pas avec le premier-né de ta vache; et tu ne tondras pas le premier-né de tes brebis:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'tu le mangeras, toi et ta maison, devant l’ Éternel, ton Dieu, d’année en année, au lieu que l’ Éternel aura choisi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Et s’il a un défaut corporel, s’il est boiteux ou aveugle, [s’il a] un mauvais défaut quelconque, tu ne le sacrifieras pas à l’ Éternel, ton Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'tu le mangeras dans tes portes; celui qui est impur et celui qui est pur [en mangeront] également, comme de la gazelle et du cerf.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Seulement, tu n’en mangeras pas le sang; tu le verseras sur la terre, comme de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Garde le mois d’Abib, et fais la Pâque à l’ Éternel, ton Dieu; car au mois d’Abib, l’ Éternel, ton Dieu, t’a fait sortir, de nuit, hors d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Et sacrifie la pâque à l’ Éternel, ton Dieu, du menu et du gros bétail, au lieu que l’ Éternel aura choisi pour y faire habiter son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Tu ne mangeras pas avec elle de pain levé; pendant sept jours tu mangeras avec elle des pains sans levain, pains d’affliction, parce que tu es sorti en hâte du pays d’Égypte, afin que, tous les jours de ta vie, tu te souviennes du jour de ta sortie du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Et il ne se verra pas de levain chez toi, dans toutes tes limites, pendant sept jours; et de la chair que tu sacrifieras le soir du premier jour, rien ne passera la nuit jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, '– Tu ne pourras pas sacrifier la pâque dans l’une de tes portes que l’ Éternel, ton Dieu, te donne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'mais au lieu que l’ Éternel, ton Dieu, aura choisi pour y faire habiter son nom, là tu sacrifieras la pâque, le soir, au coucher du soleil, au temps où tu sortis d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'et tu la cuiras et la mangeras au lieu que l’ Éternel, ton Dieu, aura choisi; et le matin tu t’en retourneras, et tu t’en iras dans tes tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Pendant six jours tu mangeras des pains sans levain; et, le septième jour, il y aura une fête solennelle à l’ Éternel, ton Dieu: tu ne feras aucune œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Tu compteras sept semaines; depuis que la faucille commence à être mise aux blés, tu commenceras à compter sept semaines,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'et tu célébreras la fête des semaines à l’ Éternel, ton Dieu, avec un tribut d’offrande volontaire de ta main, que tu donneras selon que l’ Éternel, ton Dieu, t’aura béni.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Et tu te réjouiras devant l’ Éternel, ton Dieu, toi, et ton fils, et ta fille, et ton serviteur, et ta servante, et le Lévite qui est dans tes portes, et l’étranger, et l’orphelin, et la veuve, qui sont au milieu de toi, au lieu que l’ Éternel, ton Dieu, aura choisi pour y faire habiter son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Et tu te souviendras que tu as été serviteur en Égypte, et tu garderas et tu pratiqueras ces statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Tu célébreras la fête des tabernacles pendant sept jours, quand tu auras recueilli [les produits] de ton aire et de ta cuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Et tu te réjouiras dans ta fête, toi, et ton fils, et ta fille, et ton serviteur, et ta servante, et le Lévite, et l’étranger, et l’orphelin, et la veuve, qui sont dans tes portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Tu feras pendant sept jours la fête à l’ Éternel, ton Dieu, au lieu que l’ Éternel aura choisi, car l’ Éternel, ton Dieu, te bénira dans toute ta récolte et dans tout l’ouvrage de tes mains; et tu ne seras que joyeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Trois fois l’an tout mâle d’entre vous paraîtra devant l’ Éternel, ton Dieu, au lieu qu’il aura choisi: à la fête des pains sans levain, et à la fête des semaines, et à la fête des tabernacles; et on ne paraîtra pas devant l’ Éternel à vide,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, '[mais] chacun selon ce que sa main peut donner, selon la bénédiction de l’ Éternel, ton Dieu, laquelle il te donnera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Tu t’établiras des juges et des magistrats, selon tes tribus, dans toutes tes portes que l’ Éternel, ton Dieu, te donnera, pour qu’ils jugent le peuple par un jugement juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Tu ne feras pas fléchir le jugement; tu ne feras pas acception de personnes; et tu ne recevras pas de présent; car le présent aveugle les yeux des sages et pervertit les paroles des justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'La parfaite justice, tu la poursuivras, afin que tu vives et que tu possèdes le pays que l’ Éternel, ton Dieu, te donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Tu ne te planteras pas d’ashère, de quelque bois que ce soit, à côté de l’autel de l’ Éternel, ton Dieu, que tu te feras;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'et tu ne te dresseras pas de statue, – [chose] que hait l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Tu ne sacrifieras à l’ Éternel, ton Dieu, ni bœuf ni mouton qui ait un défaut corporel, quoi que ce soit de mauvais; car c’est une abomination pour l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'S’il se trouve au milieu de toi, dans une de tes portes, que l’ Éternel, ton Dieu, te donne, un homme ou une femme qui fasse ce qui est mauvais aux yeux de l’ Éternel, ton Dieu, en transgressant son alliance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'et qui aille et serve d’autres dieux, et s’incline devant eux, soit devant le soleil, ou devant la lune, ou devant toute l’armée des cieux, ce que je n’ai pas commandé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'et que cela t’ait été rapporté, et que tu l’aies entendu, alors tu rechercheras bien; et si c’est la vérité, si la chose est établie, si cette abomination a été commise en Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'tu feras sortir vers tes portes cet homme ou cette femme, qui auront fait cette mauvaise chose, l’homme ou la femme, et tu les assommeras de pierres, et ils mourront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Sur la déposition de deux témoins ou de trois témoins, celui qui doit mourir sera mis à mort; il ne sera pas mis à mort sur la déposition d’un seul témoin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'La main des témoins sera la première contre lui pour le mettre à mort, et la main de tout le peuple ensuite; et tu ôteras le mal du milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Lorsqu’une affaire sera pour toi trop difficile à juger, entre sang et sang, entre cause et cause, et entre coup et coup, – des cas de dispute dans tes portes, alors tu te lèveras, et tu monteras au lieu que l’ Éternel, ton Dieu, aura choisi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'et tu viendras vers les sacrificateurs, les Lévites, et vers le juge qu’il y aura en ces jours-là, et tu rechercheras, et ils te déclareront la sentence du jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Et tu agiras conformément à la sentence qu’ils t’auront déclarée, de ce lieu que l’ Éternel aura choisi, et tu prendras garde à faire selon tout ce qu’ils t’auront enseigné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Tu agiras conformément à la loi qu’ils t’auront enseignée, et selon le droit qu’ils t’auront annoncé; tu ne t’écarteras, ni à droite ni à gauche, de la sentence qu’ils t’auront déclarée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Et l’homme qui agira avec fierté, n’écoutant point le sacrificateur qui se tiendra là pour servir l’ Éternel ton Dieu, ou le juge, cet homme-là mourra, et tu ôteras le mal [du milieu] d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'et tout le peuple l’entendra, et craindra, et n’agira plus avec fierté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Quand tu seras entré dans le pays que l’ Éternel, ton Dieu, te donne, et que tu le posséderas et y habiteras, et que tu diras: J’établirai un roi sur moi, comme toutes les nations qui sont autour de moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'tu établiras sur toi le roi que l’ Éternel, ton Dieu, choisira; tu établiras sur toi un roi d’entre tes frères; tu ne pourras pas établir sur toi un homme étranger, qui ne soit pas ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Seulement, il n’aura pas une multitude de chevaux, et il ne fera pas retourner le peuple en Égypte pour avoir beaucoup de chevaux; car l’ Éternel vous a dit: Vous ne retournerez plus jamais par ce chemin-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Et il n’aura pas un grand nombre de femmes, afin que son cœur ne se détourne pas; et il ne s’amassera pas beaucoup d’argent et d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Et il arrivera, lorsqu’il sera assis sur le trône de son royaume, qu’il écrira pour lui, dans un livre, une copie de cette loi, faite d’après le livre qui est devant les sacrificateurs, les Lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Et il l’aura auprès de lui; et il y lira tous les jours de sa vie, afin qu’il apprenne à craindre l’ Éternel, son Dieu, [et] à garder toutes les paroles de cette loi, et ces statuts, pour les faire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'en sorte que son cœur ne s’élève pas au-dessus de ses frères, et qu’il ne s’écarte pas du commandement, ni à droite ni à gauche; afin qu’il prolonge ses jours dans son royaume, lui et ses fils, au milieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Les sacrificateurs, les Lévites, [et] toute la tribu de Lévi, n’auront point de part ni d’héritage avec Israël: ils mangeront des sacrifices de l’ Éternel faits par feu, et de son héritage,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'mais ils n’auront point d’héritage au milieu de leurs frères. L’ Éternel est leur héritage, comme il le leur a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Or c’est ici le droit des sacrificateurs de la part du peuple, de la part de ceux qui offrent un sacrifice, que ce soit un bœuf, ou un mouton: on donnera au sacrificateur l’épaule, et les mâchoires, et l’estomac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Tu lui donneras les prémices de ton froment, de ton moût et de ton huile, et les prémices de la toison de tes moutons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Car l’ Éternel, ton Dieu, l’a choisi, lui et ses fils, d’entre toutes tes tribus, pour qu’il se tienne toujours [devant lui] pour faire le service au nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Et si le Lévite vient de l’une de tes portes, de tout Israël où il séjourne, et qu’il vienne, selon tout le désir de son âme, au lieu que l’ Éternel aura choisi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'et qu’il serve au nom de l’ Éternel, son Dieu, comme tous ses frères, les Lévites, qui se tiennent là devant l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'il mangera une portion égale, outre ce qu’il aura vendu de son patrimoine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Quand tu seras entré dans le pays que l’ Éternel, ton Dieu, te donne, tu n’apprendras pas à faire selon les abominations de ces nations:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'il ne se trouvera au milieu de toi personne qui fasse passer par le feu son fils ou sa fille, ni devin qui se mêle de divination, ni pronostiqueur, ni enchanteur, ni magicien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'ni sorcier, ni personne qui consulte les esprits, ni diseur de bonne aventure, ni personne qui interroge les morts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'car quiconque fait ces choses est en abomination à l’ Éternel; et à cause de ces abominations, l’ Éternel, ton Dieu, les dépossède devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Tu seras parfait avec l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Car ces nations, que tu vas déposséder, écoutent les pronostiqueurs et les devins; mais pour toi, l’ Éternel, ton Dieu, ne t’a pas permis d’agir ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'L’ Éternel, ton Dieu, te suscitera un prophète comme moi, du milieu de toi, d’entre tes frères; vous l’écouterez,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'selon tout ce que tu demandas à l’ Éternel, ton Dieu, à Horeb, le jour de la congrégation, disant: Que je n’entende plus la voix de l’ Éternel, mon Dieu, et que je ne voie plus ce grand feu, afin que je ne meure pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Et l’ Éternel me dit: Ils ont bien dit ce qu’ils ont dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Je leur susciterai un prophète comme toi, du milieu de leurs frères, et je mettrai mes paroles dans sa bouche, et il leur dira tout ce que je lui commanderai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Et il arrivera que l’homme qui n’écoutera pas mes paroles, lesquelles il dira en mon nom, moi, je le lui redemanderai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Seulement, le prophète qui prétendra dire en mon nom une parole que je ne lui aurai pas commandé de dire, ou qui parlera au nom d’autres dieux, ce prophète-là mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Et si tu dis dans ton cœur: Comment connaîtrons-nous la parole que l’ Éternel n’a pas dite?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Quand le prophète parlera au nom de l’ Éternel, et que la chose n’aura pas lieu et n’arrivera pas, c’est cette parole-là que l’ Éternel n’a pas dite; le prophète l’a dite présomptueusement: tu n’auras pas peur de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Quand l’ Éternel, ton Dieu, aura retranché les nations dont l’ Éternel, ton Dieu, te donne le pays, et que tu les auras dépossédées, et que tu habiteras dans leurs villes et dans leurs maisons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'tu sépareras pour toi trois villes au milieu de ton pays que l’ Éternel, ton Dieu, te donne pour le posséder:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'tu t’en prépareras le chemin, et tu diviseras en trois parties le territoire de ton pays que l’ Éternel, ton Dieu, te donne en héritage; et ce sera afin que tout homicide s’y enfuie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Et voici ce qui concerne l’homicide qui s’y enfuira, pour qu’il vive: Celui qui aura frappé son prochain sans le savoir, et sans l’avoir haï auparavant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'comme si quelqu’un va avec son prochain dans la forêt pour couper du bois, et que sa main lève la hache pour couper l’arbre, et que le fer échappe du manche et atteigne son prochain, et qu’il meure: il s’enfuira dans une de ces villes, et il vivra;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'de peur que le vengeur du sang ne poursuive l’homicide pendant que son cœur est échauffé, et qu’il ne l’atteigne, parce que le chemin est long, et ne le frappe à mort, quoiqu’il ne mérite pas la mort, car il ne le haïssait pas auparavant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'C’est pourquoi, je te commande, disant: Sépare-toi trois villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Et si l’ Éternel, ton Dieu, étend tes limites, comme il l’a juré à tes pères, et qu’il te donne tout le pays qu’il a promis de donner à tes pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'parce que tu auras gardé tout ce commandement que je te commande aujourd’hui, pour le pratiquer, en aimant l’ Éternel, ton Dieu, et en marchant toujours dans ses voies, alors tu t’ajouteras encore trois villes à ces trois-là,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'afin que le sang innocent ne soit pas versé au milieu de ton pays, que l’ Éternel, ton Dieu, te donne en héritage, et qu’ainsi le sang ne soit pas sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Mais si un homme hait son prochain, et lui dresse une embûche, et se lève contre lui et le frappe à mort, en sorte qu’il meure, et qu’il s’enfuie dans l’une de ces villes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'alors les anciens de sa ville enverront et le prendront de là, et le livreront en la main du vengeur du sang; et il mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Ton œil ne l’épargnera point, et tu ôteras d’Israël le sang innocent, et tu prospéreras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Tu ne reculeras point les bornes de ton prochain, que des prédécesseurs auront fixées dans ton héritage lequel tu hériteras dans le pays que l’ Éternel, ton Dieu, te donne pour le posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Un seul témoin ne se lèvera pas contre un homme, pour une iniquité ou un péché quelconque, quelque péché qu’il ait commis: sur la déposition de deux témoins ou sur la déposition de trois témoins, la chose sera établie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Quand un témoin inique s’élèvera contre un homme, pour témoigner contre lui d’un crime,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'alors les deux hommes qui ont le différend, comparaîtront devant l’ Éternel, devant les sacrificateurs et les juges qu’il y aura en ces jours-là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'et les juges rechercheront bien, et, si le témoin est un faux témoin, s’il a témoigné faussement contre son frère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'alors vous lui ferez comme il pensait faire à son frère; et tu ôteras le mal du milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Et les autres l’entendront et craindront, et ne feront plus désormais une pareille méchante action au milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Et ton œil n’épargnera point: vie pour vie, œil pour œil, dent pour dent, main pour main, pied pour pied.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Quand tu sortiras pour faire la guerre contre tes ennemis, et que tu verras des chevaux et des chars, un peuple plus nombreux que toi, tu n’auras point peur d’eux; car l’ Éternel, ton Dieu, qui t’a fait monter du pays d’Égypte, est avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Et il arrivera que, quand vous vous approcherez pour le combat, le sacrificateur s’approchera et parlera au peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'et leur dira: Écoute, Israël! Vous vous approchez aujourd’hui pour livrer bataille à vos ennemis: que votre cœur ne faiblisse point, ne craignez point, ne soyez point alarmés, et ne soyez point épouvantés devant eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'car l’ Éternel, votre Dieu, marche avec vous, pour combattre pour vous contre vos ennemis, pour vous sauver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Et les magistrats parleront au peuple, disant: Qui est l’homme qui a bâti une maison neuve et qui ne l’a pas consacrée? qu’il s’en aille et retourne en sa maison, de peur qu’il ne meure dans la bataille et qu’un autre ne la consacre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Et qui est l’homme qui a planté une vigne et n’en a pas joui? qu’il s’en aille et retourne en sa maison, de peur qu’il ne meure dans la bataille et qu’un autre n’en jouisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Et qui est l’homme qui s’est fiancé une femme et ne l’a pas encore prise? qu’il s’en aille et retourne en sa maison, de peur qu’il ne meure dans la bataille et qu’un autre ne la prenne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Et les magistrats continueront à parler au peuple, et diront: Qui est l’homme qui a peur et dont le cœur faiblit? qu’il s’en aille et retourne en sa maison, de peur que le cœur de ses frères ne se fonde comme le sien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Et quand les magistrats auront achevé de parler au peuple, ils établiront les chefs des armées à la tête du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Quand tu approcheras d’une ville pour lui faire la guerre, tu l’inviteras à la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Et s’il arrive qu’elle te fasse une réponse de paix et qu’elle s’ouvre à toi, alors tout le peuple qui sera trouvé dedans te sera tributaire et te servira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Et si elle ne fait pas la paix avec toi, mais qu’elle fasse la guerre contre toi, tu l’assiégeras;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'et quand l’ Éternel, ton Dieu, la livrera en ta main, tu frapperas tous les mâles par le tranchant de l’épée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'mais les femmes et les enfants, et le bétail, et tout ce qui sera dans la ville, tout son butin, tu le pilleras pour toi; et tu mangeras le butin de tes ennemis, que l’ Éternel, ton Dieu, t’aura donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'C’est ainsi que tu feras à toutes les villes qui sont très éloignées de toi, qui ne sont point des villes de ces nations-ci;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'mais des villes de ces peuples-ci que l’ Éternel, ton Dieu, te donne en héritage, tu ne laisseras en vie rien de ce qui respire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'car tu les détruiras entièrement comme un anathème; le Héthien et l’Amoréen, le Cananéen et le Phérézien, le Hévien et le Jébusien, comme l’ Éternel, ton Dieu, te l’a commandé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'afin qu’ils ne vous enseignent pas à faire selon toutes leurs abominations qu’ils ont faites à leurs dieux, et que vous ne péchiez pas contre l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Quand tu assiégeras une ville pendant plusieurs jours en lui faisant la guerre pour la prendre, tu ne détruiras pas ses arbres en levant la hache contre eux, car tu pourras en manger: tu ne les couperas pas, car l’arbre des champs est-il un homme, pour être assiégé par toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Seulement, l’arbre que tu connaîtras n’être pas un arbre dont on mange, celui-là tu le détruiras et tu le couperas, et tu en construiras des ouvrages pour assiéger la ville qui est en guerre avec toi, jusqu’à ce qu’elle tombe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Quand on trouvera sur la terre que l’ Éternel, ton Dieu, te donne pour la posséder, un homme tué, étendu dans les champs, sans qu’on sache qui l’a frappé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'tes anciens et tes juges sortiront, et mesureront jusqu’aux villes qui sont autour de l’homme tué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Et [quand ils auront établi quelle est] la ville la plus rapprochée de l’homme tué, les anciens de cette ville prendront une génisse qui n’a pas servi et qui n’a pas tiré au joug,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'et les anciens de cette ville feront descendre la génisse dans une vallée [où coule un torrent] qui ne tarit pas, dans laquelle on ne travaille ni ne sème, et là, dans la vallée, ils briseront la nuque à la génisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Et les sacrificateurs, fils de Lévi, s’approcheront; car ce sont eux que l’ Éternel, ton Dieu, a choisis pour faire son service et pour bénir au nom de l’ Éternel; et ce sont eux qui prononceront sur tout différend et sur toute blessure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Et tous les anciens de cette ville, qui sont les plus rapprochés de l’homme tué, laveront leurs mains sur la génisse à laquelle on aura brisé la nuque dans la vallée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'et ils prendront la parole et diront: Nos mains n’ont pas versé ce sang, et nos yeux ne l’ont pas vu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Pardonne, ô Éternel, à ton peuple Israël que tu as racheté, et n’impute pas à ton peuple Israël le sang innocent. Et le sang leur sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Et toi, tu ôteras le sang innocent du milieu de toi, quand tu auras fait ce qui est droit aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Si tu sors pour faire la guerre contre tes ennemis, et que l’ Éternel, ton Dieu, les livre en ta main, et que tu en emmènes des captifs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'si tu vois parmi les captifs une femme belle de figure, et que tu t’attaches à elle, et que tu la prennes pour femme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'tu l’introduiras dans l’intérieur de ta maison; et elle rasera sa tête et se fera les ongles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'et elle ôtera de dessus elle le vêtement de sa captivité; et elle habitera dans ta maison, et pleurera son père et sa mère un mois entier; et après cela tu viendras vers elle, et tu seras son mari, et elle sera ta femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Et s’il arrive qu’elle ne te plaise pas, tu la renverras à son gré; mais tu ne la vendras point pour de l’argent: tu ne la traiteras pas en esclave, parce que tu l’as humiliée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Si un homme a deux femmes, l’une aimée et l’autre haïe, et qu’elles lui aient enfanté des fils, tant celle qui est aimée que celle qui est haïe, et que le fils premier-né soit de celle qui est haïe,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'alors, le jour où il fera hériter à ses fils ce qui est à lui, il ne pourra pas faire premier-né le fils de celle qui est aimée, de préférence au fils de celle qui est haïe, lequel est le premier-né;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'mais il reconnaîtra pour premier-né le fils de celle qui est haïe, pour lui donner double portion de tout ce qui se trouvera être à lui; car il est le commencement de sa vigueur, le droit d’aînesse lui appartient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Si un homme a un fils indocile et rebelle, qui n’écoute pas la voix de son père ni la voix de sa mère, et qu’ils l’aient châtié, et qu’il ne les ait pas écoutés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'alors son père et sa mère le prendront et l’amèneront aux anciens de sa ville, à la porte de son lieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'et ils diront aux anciens de sa ville: Voici notre fils, il est indocile et rebelle, il n’écoute pas notre voix, il est débauché et ivrogne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'et tous les hommes de sa ville le lapideront avec des pierres, et il mourra; et tu ôteras le mal du milieu de toi, et tout Israël l’entendra et craindra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Et si un homme a commis un péché digne de mort, et qu’il ait été mis à mort, et que tu l’aies pendu à un bois,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'son cadavre ne passera pas la nuit sur le bois; mais tu l’enterreras sans faute le jour même, car celui qui est pendu est malédiction de Dieu; et tu ne rendras pas impure la terre que l’ Éternel, ton Dieu, te donne en héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Si tu vois le bœuf de ton frère, ou son mouton, égarés, tu ne te cacheras pas de devant eux: tu ne manqueras pas de les ramener à ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Et si ton frère n’est pas près de toi, ou que tu ne le connaisses pas, tu mèneras la bête dans ta maison; et elle sera chez toi jusqu’à ce que ton frère la cherche, alors tu la lui rendras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Et tu feras de même pour son âne, et tu feras de même pour son vêtement, et tu feras de même pour tout objet perdu que ton frère aura perdu et que tu auras trouvé: tu ne pourras pas te cacher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Si tu vois l’âne de ton frère, ou son bœuf, tombés sur le chemin, tu ne te cacheras pas de devant eux: tu ne manqueras pas de les relever avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'La femme ne portera pas un habit d’homme, et l’homme ne se vêtira pas d’un vêtement de femme; car quiconque fait ces choses est en abomination à l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Si tu rencontres devant toi dans le chemin, sur quelque arbre ou sur la terre, un nid d’oiseau avec des petits ou des œufs, et que la mère soit assise sur les petits ou sur les œufs, tu ne prendras pas la mère avec les petits;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'tu ne manqueras pas de laisser aller la mère, et tu prendras les petits pour toi; afin que tu prospères et que tu prolonges tes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Si tu bâtis une maison neuve, tu feras un parapet à ton toit, afin que tu ne mettes pas du sang sur ta maison, si quelqu’un venait à en tomber.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Tu ne sèmeras pas ta vigne de deux espèces [de semence], de peur que la totalité de la semence que tu as semée et le rapport de ta vigne ne soient sanctifiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, '– Tu ne laboureras pas avec un bœuf et un âne [attelés] ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, '– Tu ne te vêtiras pas d’une étoffe mélangée, de laine et de lin [tissés] ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Tu te feras des houppes aux quatre coins de ton vêtement, dont tu te couvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Si un homme a pris une femme, et est allé vers elle, et qu’il la haïsse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'et lui impute des actes qui donnent occasion de parler, et fasse courir sur elle quelque mauvais bruit, et dise: J’ai pris cette femme, et je me suis approché d’elle, et je ne l’ai pas trouvée vierge:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'alors le père de la jeune femme, et sa mère, prendront les signes de la virginité de la jeune femme et les produiront devant les anciens de la ville, à la porte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'et le père de la jeune femme dira aux anciens: J’ai donné ma fille pour femme à cet homme, et il la hait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'et voici, il lui impute des actes qui donnent occasion de parler, disant: Je n’ai pas trouvé ta fille vierge; et voici les signes de la virginité de ma fille. Et ils déploieront le drap devant les anciens de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Et les anciens de cette ville prendront l’homme et le châtieront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Et parce qu’il aura fait courir un mauvais bruit sur une vierge d’Israël, ils lui feront payer une amende de 100 pièces d’argent, et ils les donneront au père de la jeune femme; et elle restera sa femme, et il ne pourra pas la renvoyer, tous ses jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, '– Mais si cette chose est vraie, si les signes de la virginité n’ont pas été trouvés chez la jeune femme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'alors ils feront sortir la jeune femme à l’entrée de la maison de son père, et les hommes de sa ville l’assommeront de pierres, et elle mourra; car elle a commis une infamie en Israël, en se prostituant dans la maison de son père; et tu ôteras le mal du milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Si un homme a été trouvé couché avec une femme mariée, ils mourront tous deux, l’homme qui a couché avec la femme, et la femme; et tu ôteras le mal [du milieu] d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, '– Si une jeune fille vierge est fiancée à un homme, et qu’un homme la trouve dans la ville et couche avec elle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'vous les ferez sortir tous les deux à la porte de cette ville, et vous les assommerez de pierres, et ils mourront: la jeune fille, parce que, étant dans la ville, elle n’a pas crié, et l’homme, parce qu’il a humilié la femme de son prochain; et tu ôteras le mal du milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Et si c’est dans les champs, que l’homme a trouvé la jeune fille fiancée, et que, lui faisant violence, il couche avec elle, alors l’homme qui aura couché avec elle mourra, lui seul;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'et tu ne feras rien à la jeune fille: il n’y a pas de péché digne de mort sur la jeune fille; car c’est comme si quelqu’un s’élevait contre son prochain et le tuait: ainsi est ce cas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'car il l’a trouvée dans les champs, la jeune fille fiancée a crié, et il n’y a eu personne pour la sauver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Si un homme trouve une jeune fille vierge qui n’est pas fiancée, et qu’il la saisisse et couche avec elle, et qu’ils soient trouvés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'l’homme qui aura couché avec elle donnera au père de la jeune fille 50 pièces d’argent, et elle sera sa femme, puisqu’ il l’a humiliée; il ne pourra pas la renvoyer, tous ses jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Un homme ne prendra pas la femme de son père, et ne relèvera pas le pan du vêtement de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Celui qui est eunuque, soit pour avoir été froissé, soit pour avoir été taillé, n’entrera point dans la congrégation de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'L’enfant illégitime n’entrera pas dans la congrégation de l’ Éternel; même sa dixième génération n’entrera pas dans la congrégation de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'L’Ammonite et le Moabite n’entreront pas dans la congrégation de l’ Éternel; même leur dixième génération n’entrera pas dans la congrégation de l’ Éternel, à jamais;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'parce qu’ils ne sont pas venus à votre rencontre avec du pain et de l’eau dans le chemin, lorsque vous sortiez d’Égypte, et parce qu’ils ont loué [à prix d’argent] contre toi, Balaam, fils de Béor, de Pethor, en Mésopotamie, pour te maudire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Mais l’ Éternel, ton Dieu, ne voulut pas écouter Balaam; et l’ Éternel, ton Dieu, a changé pour toi la malédiction en bénédiction, car l’ Éternel, ton Dieu, t’a aimé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Tu ne chercheras jamais leur paix, ni leur prospérité, tous tes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, '– Tu n’auras pas en abomination l’Édomite, car il est ton frère; tu n’auras pas en abomination l’Égyptien, car tu as séjourné comme étranger dans son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Les fils qui leur naîtront, à la troisième génération, entreront dans la congrégation de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Lorsque le camp sortira contre tes ennemis, garde-toi de toute chose mauvaise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'S’il y a parmi toi un homme qui ne soit pas pur, pour quelque accident de nuit, il sortira hors du camp; il n’entrera pas dans l’intérieur du camp;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'et sur le soir il se lavera dans l’eau; et au coucher du soleil il entrera dans l’intérieur du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Et tu auras un endroit hors du camp, et tu sortiras là dehors;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'et tu auras, outre tes armes, un pieu; et il arrivera, quand tu t’assiéras dehors, que tu creuseras avec ce [pieu], et tu te retourneras, et tu couvriras ce qui est sorti de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Car l’ Éternel, ton Dieu, marche au milieu de ton camp pour te délivrer et pour livrer tes ennemis devant toi; et ton camp sera saint, afin qu’il ne voie parmi toi rien de malséant, et qu’il ne se détourne d’avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Tu ne livreras point à son maître le serviteur qui se sera sauvé chez toi d’auprès de son maître;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'il habitera avec toi, au milieu de toi, dans le lieu qu’il choisira en l’une de tes portes, là où bon lui semble: tu ne l’opprimeras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Il n’y aura, d’entre les filles d’Israël, aucune femme vouée à la prostitution, et il n’y aura, d’entre les fils d’Israël, aucun homme voué à la prostitution.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Tu n’apporteras point dans la maison de l’ Éternel, ton Dieu, pour aucun vœu, le salaire d’une prostituée, ni le prix d’un chien; car ils sont tous les deux en abomination à l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Tu ne prendras pas d’intérêt de ton frère, intérêt d’argent, intérêt de vivres, intérêt de quelque chose que ce soit qu’on prête à intérêt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Tu prendras un intérêt de l’étranger, mais de ton frère tu ne prendras pas d’intérêt; afin que l’ Éternel, ton Dieu, te bénisse en tout ce à quoi tu mets la main, dans le pays où tu entres pour le posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Quand tu voueras un vœu à l’ Éternel, ton Dieu, tu ne tarderas pas à l’acquitter; car l’ Éternel, ton Dieu, le redemandera certainement de ta part, et il y aura du péché sur toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'mais si tu t’abstiens de faire un vœu, il n’y aura pas du péché sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Ce qui sera sorti de tes lèvres, l’offrande volontaire que tu auras promise de ta bouche, tu prendras garde à le faire, comme tu auras voué à l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Si tu entres dans la vigne de ton prochain, tu pourras manger des raisins selon ton appétit et te rassasier; mais tu n’en mettras pas dans ta corbeille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 26, 'Si tu entres dans les blés de ton prochain, tu pourras arracher des épis avec ta main; mais tu ne lèveras pas la faucille sur les blés de ton prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Si un homme prend une femme et l’épouse, et qu’il arrive qu’elle ne trouve pas grâce à ses yeux, parce qu’il aura trouvé en elle quelque chose de malséant, il écrira pour elle une lettre de divorce, et la lui mettra dans la main, et la renverra hors de sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Et elle sortira de sa maison et s’en ira, et elle pourra être à un autre homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Et si le dernier mari la hait, et qu’il lui écrive une lettre de divorce et la lui mette dans la main, et la renvoie de sa maison, ou si le dernier mari qui l’avait prise pour sa femme vient à mourir:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'alors son premier mari, qui l’a renvoyée, ne pourra pas la reprendre pour être sa femme, après qu’elle aura été rendue impure; car c’est une abomination devant l’ Éternel: tu ne chargeras pas de péché le pays que l’ Éternel, ton Dieu, te donne en héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Si un homme a nouvellement pris une femme, il n’ira point à l’armée, et il ne sera chargé d’aucune affaire: il en sera exempt, pour sa maison, pendant une année, et il réjouira sa femme qu’il a prise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'On ne prendra point en gage les deux meules, ni la meule tournante, car ce serait prendre en gage la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Si on trouve un homme qui ait volé l’un d’entre ses frères, les fils d’Israël, et qui l’ait traité en esclave et l’ait vendu, ce voleur mourra; et tu ôteras le mal du milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Prends garde à la plaie de la lèpre, afin de bien observer et de faire selon tout ce que les sacrificateurs, les Lévites, vous enseigneront; vous prendrez garde à faire comme je leur ai commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Souviens-toi de ce que l’ Éternel, ton Dieu, fit à Marie dans le chemin, quand vous sortiez d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Lorsque tu feras à ton prochain un prêt quelconque, tu n’entreras pas dans sa maison pour recevoir son gage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'tu te tiendras dehors, et l’homme à qui tu prêtes t’apportera le gage dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Et si l’homme est pauvre, tu ne te coucheras pas sur son gage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'tu ne manqueras pas de lui rendre le gage au coucher du soleil; et il couchera dans son vêtement, et te bénira; et cela te sera justice devant l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Tu n’opprimeras pas l’homme à gages affligé et pauvre d’entre tes frères ou d’entre tes étrangers qui sont dans ton pays, dans tes portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'En son jour, tu lui donneras son salaire; le soleil ne se couchera pas sur lui, car il est pauvre et son désir s’y porte; afin qu’il ne crie pas contre toi à l’ Éternel et qu’il n’y ait pas du péché sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Les pères ne seront pas mis à mort pour les fils, et les fils ne seront pas mis à mort pour les pères: ils seront mis à mort chacun pour son péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Tu ne feras pas fléchir le jugement de l’étranger [ni] de l’orphelin, et tu ne prendras pas en gage le vêtement de la veuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Et tu te souviendras que tu as été serviteur en Égypte, et que l’ Éternel, ton Dieu, t’a racheté de là; c’est pourquoi je te commande de faire cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Quand tu feras ta moisson dans ton champ, et que tu auras oublié une gerbe dans ton champ, tu ne retourneras pas pour la prendre; elle sera pour l’étranger, pour l’orphelin, et pour la veuve, afin que l’ Éternel, ton Dieu, te bénisse dans toute l’œuvre de tes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Quand tu battras ton olivier, tu ne reviendras pas cueillir ce qui reste aux branches après toi; ce sera pour l’étranger, pour l’orphelin, et pour la veuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Quand tu vendangeras ta vigne, tu ne grappilleras pas après; ce sera pour l’étranger, pour l’orphelin, et pour la veuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Et tu te souviendras que tu as été serviteur dans le pays d’Égypte; c’est pourquoi je te commande de faire cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Quand il y aura une contestation entre des hommes, et qu’ils viendront devant la justice et qu’on les jugera, on déclarera juste le juste, et on déclarera méchant le méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Et s’il arrive que le méchant ait mérité d’être battu, le juge le fera mettre par terre et battre devant lui d’un certain nombre [de coups], selon la mesure de sa méchanceté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Il le fera battre de 40 [coups], sans les dépasser, de peur que s’il continuait à le battre de beaucoup de coups outre ceux-là, ton frère ne soit méprisable à tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Tu n’emmuselleras pas le bœuf, pendant qu’il foule [le grain].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Quand des frères habiteront ensemble, et que l’un d’entre eux mourra, et qu’il n’aura pas de fils, la femme du mort n’ira pas s’allier dehors à un homme étranger; son lévir viendra vers elle, et la prendra pour femme et s’acquittera envers elle de son devoir de lévir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Et il arrivera que le premier-né qu’elle enfantera succédera au nom du frère mort, et son nom ne sera pas effacé d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Et s’il ne plaît pas à l’homme de prendre sa belle-sœur, sa belle-sœur montera à la porte vers les anciens, et dira: Mon lévir refuse de relever le nom de son frère en Israël, il ne veut pas s’acquitter envers moi de son lévirat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Et les anciens de sa ville l’appelleront, et lui parleront; et s’il tient ferme, et dit: Il ne me plaît pas de la prendre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'alors sa belle-sœur s’approchera de lui devant les yeux des anciens, et lui ôtera la sandale de son pied, et lui crachera à la figure, et elle répondra et dira: C’est ainsi qu’il sera fait à l’homme qui ne bâtira pas la maison de son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Et son nom sera appelé en Israël la maison du déchaussé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Si des hommes ont une rixe l’un avec l’autre, et que la femme de l’un s’approche pour délivrer son mari de la main de celui qui le frappe, et qu’elle étende sa main et saisisse celui-ci par les parties honteuses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'tu lui couperas la main: ton œil ne l’épargnera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Tu n’auras pas dans ton sac deux poids différents, un grand et un petit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'tu n’auras pas dans ta maison deux éphas différents, un grand et un petit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Tu auras un poids exact et juste, tu auras un épha exact et juste, afin que tes jours soient prolongés sur la terre que l’ Éternel, ton Dieu, te donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Car quiconque fait ces choses, quiconque pratique l’iniquité, est en abomination à l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Souviens-toi de ce que t’a fait Amalek, en chemin, quand vous sortiez d’Égypte:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'comment il te rencontra dans le chemin, et tomba en queue sur toi, sur tous les faibles qui se traînaient après toi, lorsque tu étais las et harassé, et ne craignit pas Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Et quand l’ Éternel, ton Dieu, t’aura donné du repos de tous tes ennemis à l’entour, dans le pays que l’ Éternel, ton Dieu, te donne en héritage pour le posséder, il arrivera que tu effaceras la mémoire d’Amalek de dessous les cieux: tu ne l’oublieras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Et quand tu seras entré dans le pays que l’ Éternel, ton Dieu, te donne en héritage, et que tu le posséderas, et y habiteras,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'alors tu prendras des prémices de tous les fruits de la terre, que tu tireras de ton pays que l’ Éternel, ton Dieu, te donne, et tu les mettras dans une corbeille, et tu iras au lieu que l’ Éternel, ton Dieu, aura choisi pour y faire habiter son nom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'et tu viendras vers le sacrificateur qu’il y aura en ces jours-là, et tu lui diras: Je déclare aujourd’hui à l’ Éternel, ton Dieu, que je suis arrivé dans le pays que l’ Éternel a juré à nos pères de nous donner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Et le sacrificateur prendra la corbeille de ta main, et la posera devant l’autel de l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Et tu prendras la parole, et tu diras devant l’ Éternel, ton Dieu: Mon père était un Araméen qui périssait, et il descendit en Égypte avec peu de gens, et il y séjourna, et y devint une nation grande, forte, et nombreuse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Et les Égyptiens nous maltraitèrent, et nous humilièrent, et nous imposèrent un dur service;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'et nous avons crié à l’ Éternel, le Dieu de nos pères, et l’ Éternel entendit notre cri, et vit notre humiliation, et notre labeur, et notre oppression;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'et l’ Éternel nous fit sortir d’Égypte à main forte, et à bras étendu, et avec une grande terreur, et avec des signes et des prodiges;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'et il nous a fait entrer dans ce lieu-ci, et nous a donné ce pays, pays ruisselant de lait et de miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Et maintenant, voici, j’ai apporté les prémices du fruit de la terre que tu m’as donnée, ô Éternel! Et tu les poseras devant l’ Éternel, ton Dieu, et tu te prosterneras devant l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Et tu te réjouiras de tout le bien que l’ Éternel, ton Dieu, t’aura donné, et à ta maison, toi et le Lévite et l’étranger qui est au milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Quand tu auras achevé de lever toute la dîme de ta récolte, dans la troisième année, qui est l’année de la dîme, tu la donneras au Lévite, à l’étranger, à l’orphelin, et à la veuve; et ils la mangeront dans tes portes et seront rassasiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Et tu diras devant l’ Éternel, ton Dieu: J’ai emporté de ma maison les choses saintes, et je les ai aussi données au Lévite, et à l’étranger, à l’orphelin, et à la veuve, selon tout ton commandement que tu m’as commandé; je n’ai transgressé aucun de tes commandements, ni ne les ai oubliés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Je n’ai pas mangé de ces choses dans mon affliction, et je n’en ai rien emporté quand j’étais impur, et n’en ai point donné pour un mort; j’ai écouté la voix de l’ Éternel, mon Dieu: j’ai fait selon tout ce que tu m’as commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Regarde de ta sainte demeure, des cieux, et bénis ton peuple Israël et la terre que tu nous as donnée, comme tu avais juré à nos pères, un pays ruisselant de lait et de miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Aujourd’hui l’ Éternel, ton Dieu, te commande de pratiquer ces statuts et ces ordonnances; et tu les garderas et tu les feras de tout ton cœur et de toute ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Tu as fait promettre aujourd’hui à l’ Éternel qu’il sera ton Dieu, pour que tu marches dans ses voies, et que tu gardes ses statuts, et ses commandements, et ses ordonnances, et que tu écoutes sa voix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'et l’ Éternel t’a fait promettre aujourd’hui que tu seras pour lui un peuple qui lui appartienne en propre, comme il t’a dit, et que tu garderas tous ses commandements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'pour qu’il te place très haut en louange et en renommée et en beauté, au-dessus de toutes les nations qu’il a faites; et que tu seras un peuple saint, [consacré] à l’ Éternel, ton Dieu, comme il l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, '*Et Moïse et les anciens d’Israël commandèrent au peuple, disant: Gardez tout le commandement que je vous commande aujourd’hui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'et il arrivera que le jour où vous passerez le Jourdain, [pour entrer] dans le pays que l’ Éternel, ton Dieu, te donne, tu te dresseras de grandes pierres, et tu les enduiras de chaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'et tu écriras sur elles toutes les paroles de cette loi, quand tu auras passé, pour entrer dans le pays que l’ Éternel, ton Dieu, te donne, pays ruisselant de lait et de miel, comme l’ Éternel, le Dieu de tes pères, t’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Et il arrivera, quand vous passerez le Jourdain, que vous dresserez ces pierres sur la montagne d’Ébal, [selon ce] que je vous commande aujourd’hui, et tu les enduiras de chaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Et tu bâtiras là un autel à l’ Éternel, ton Dieu, un autel de pierres, sur lesquelles tu ne lèveras pas le fer:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'tu bâtiras l’autel de l’ Éternel, ton Dieu, de pierres entières; et tu offriras dessus des holocaustes à l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Et tu y sacrifieras des sacrifices de prospérités, et tu mangeras là, et te réjouiras devant l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Et tu écriras sur ces pierres toutes les paroles de cette loi, en les gravant bien nettement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Et Moïse et les sacrificateurs, les Lévites, parlèrent à tout Israël, disant: Fais silence et écoute, Israël: Aujourd’hui tu es devenu le peuple de l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Et tu écouteras la voix de l’ Éternel, ton Dieu, et tu pratiqueras ses commandements et ses statuts, que je te commande aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Et Moïse commanda au peuple ce jour-là, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Quand vous aurez passé le Jourdain, ceux-ci se tiendront sur la montagne de Garizim pour bénir le peuple: Siméon, et Lévi, et Juda, et Issacar, et Joseph, et Benjamin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'et ceux-ci se tiendront sur la montagne d’Ébal, pour maudire: Ruben, Gad, et Aser, et Zabulon, Dan, et Nephthali.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Et les Lévites prendront la parole, et diront à haute voix à tous les hommes d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Maudit l’homme qui fait une image taillée, ou une image de fonte (une abomination de l’ Éternel, œuvre des mains d’un artisan), et qui la place dans un lieu secret! Et tout le peuple répondra, et dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Maudit qui méprise son père et sa mère! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Maudit qui recule les bornes de son prochain! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Maudit qui fait égarer l’aveugle dans le chemin! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Maudit qui fait fléchir le jugement de l’étranger, de l’orphelin, et de la veuve! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Maudit qui couche avec la femme de son père, car il relève le pan du vêtement de son père! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Maudit qui couche avec une bête quelconque! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Maudit qui couche avec sa sœur, fille de son père, ou fille de sa mère! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Maudit qui couche avec sa belle-mère! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Maudit qui frappe son prochain en secret! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Maudit qui prend un présent pour frapper à mort un homme, [en versant] le sang innocent! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Maudit qui n’accomplit pas les paroles de cette loi, en les pratiquant! Et tout le peuple dira: Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, '*Et il arrivera que si tu écoutes attentivement la voix de l’ Éternel, ton Dieu, pour prendre garde à pratiquer tous ses commandements que je te commande aujourd’hui, l’ Éternel, ton Dieu, te mettra très haut au-dessus de toutes les nations de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'et toutes ces bénédictions viendront sur toi et t’atteindront, si tu écoutes la voix de l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Tu seras béni dans la ville, et tu seras béni dans les champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Le fruit de ton ventre sera béni, et le fruit de ta terre, et le fruit de tes bêtes, les portées de ton gros bétail, et l’accroissement de ton menu bétail;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'ta corbeille sera bénie, et ta huche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Tu seras béni en entrant, et tu seras béni en sortant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'L’ Éternel fera que tes ennemis qui s’élèveront contre toi, seront battus devant toi; ils sortiront contre toi par un chemin, et par sept chemins ils fuiront devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'L’ Éternel commandera à la bénédiction d’être avec toi, dans tes greniers et dans tout ce à quoi tu mettras ta main; et il te bénira dans le pays que l’ Éternel, ton Dieu, te donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'L’ Éternel t’établira pour lui être un peuple saint, selon qu’il te l’a juré, si tu gardes les commandements de l’ Éternel, ton Dieu, et que tu marches dans ses voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Et tous les peuples de la terre verront que tu es appelé du nom de l’ Éternel; et ils auront peur de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Et l’ Éternel te fera surabonder en prospérité dans le fruit de ton ventre, et dans le fruit de ton bétail, et dans le fruit de ta terre, sur la terre que l’ Éternel a juré à tes pères de te donner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'L’ Éternel t’ouvrira son bon trésor, les cieux, pour donner à ton pays la pluie en sa saison et pour bénir tout l’ouvrage de ta main; et tu prêteras à beaucoup de nations, et tu n’emprunteras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Et l’ Éternel te mettra à la tête, et non à la queue; et tu ne seras qu’en haut, et tu ne seras pas en bas, si tu écoutes les commandements de l’ Éternel, ton Dieu, que je te commande aujourd’hui, pour les garder et les pratiquer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'et si tu ne t’écartes, ni à droite ni à gauche, d’aucune des paroles que je vous commande aujourd’hui, pour aller après d’autres dieux, pour les servir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Et si tu n’écoutes pas la voix de l’ Éternel, ton Dieu, pour prendre garde à pratiquer tous ses commandements et ses statuts que je te commande aujourd’hui, il arrivera que toutes ces malédictions viendront sur toi et t’atteindront:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'tu seras maudit dans la ville, et tu seras maudit dans les champs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'ta corbeille sera maudite, et ta huche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Le fruit de ton ventre sera maudit, et le fruit de ta terre, les portées de ton gros bétail, et l’accroissement de ton menu bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Tu seras maudit en entrant, et tu seras maudit en sortant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'L’ Éternel enverra sur toi la malédiction, le trouble, et la réprobation, dans tout ce à quoi tu mettras ta main [et] que tu feras, jusqu’à ce que tu sois détruit, et jusqu’à ce que tu périsses rapidement, à cause de la méchanceté de tes actions, en ce que tu m’as abandonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'L’ Éternel fera que la peste s’attache à toi, jusqu’à ce qu’il t’ait consumé de dessus la terre où tu entres pour la posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'L’ Éternel te frappera de consomption, et de fièvre, et d’inflammation, et de chaleur brûlante, et de sécheresse, et par la brûlure, et par la rouille, et elles te poursuivront jusqu’à ce que tu périsses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Et tes cieux qui sont sur ta tête seront d’airain, et la terre qui est sous toi sera de fer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'L’ Éternel donnera pour pluie de ton pays une fine poudre et de la poussière; elles descendront des cieux sur toi jusqu’à ce que tu sois détruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'L’ Éternel fera que tu seras battu devant tes ennemis; tu sortiras contre eux par un chemin, et par sept chemins tu fuiras devant eux; et tu seras chassé çà et là dans tous les royaumes de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'et tes cadavres seront en pâture à tous les oiseaux des cieux et aux bêtes de la terre, et il n’y aura personne qui les effraie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'L’ Éternel te frappera de l’ulcère d’Égypte, et d’hémorroïdes, et de gale, et de teigne, dont tu ne pourras guérir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'L’ Éternel te frappera de délire, et d’aveuglement, et d’étourdissement de cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Et tu iras tâtonnant en plein midi, comme l’aveugle tâtonne dans les ténèbres; et tu ne feras pas réussir tes voies; et tu ne seras qu’opprimé et pillé tous les jours, et il n’y aura personne qui sauve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Tu te fianceras une femme, et un autre homme couchera avec elle; tu bâtiras une maison, et tu ne l’habiteras pas; tu planteras une vigne, et tu n’en jouiras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Ton bœuf sera tué devant tes yeux, et tu n’en mangeras pas; ton âne sera enlevé devant toi, et ne reviendra pas à toi; ton menu bétail sera livré à tes ennemis, et tu n’auras personne qui sauve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Tes fils et tes filles seront livrés à un autre peuple, et tes yeux le verront, et se consumeront tout le jour après eux, et tu n’auras aucune force en ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Un peuple que tu ne connaissais pas, mangera le fruit de ta terre et tout ton labeur; et tu ne seras qu’opprimé et écrasé tous les jours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'et tu seras dans le délire à cause des choses que tu verras de tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'L’ Éternel te frappera sur les genoux et sur les cuisses d’un ulcère malin dont tu ne pourras guérir, depuis la plante de ton pied jusqu’au sommet de ta tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'L’ Éternel te fera marcher, toi et ton roi que tu auras établi sur toi, vers une nation que tu n’as pas connue, ni toi ni tes pères, et là, tu serviras d’autres dieux, le bois et la pierre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'et tu seras un sujet d’étonnement, et de proverbe, et de raillerie, parmi tous les peuples où l’ Éternel t’emmènera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Tu porteras dehors beaucoup de semence au champ, et tu recueilleras peu; car la sauterelle la dévorera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Tu planteras des vignes et tu les cultiveras, mais tu n’en boiras pas de vin et tu n’en recueilleras rien; car le ver les mangera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Tu auras des oliviers dans tous tes confins, mais tu ne t’oindras pas d’huile; car ton olivier perdra son fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Tu engendreras des fils et des filles, mais ils ne seront pas à toi; car ils iront en captivité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Le hanneton possédera tous tes arbres et le fruit de ta terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'L’étranger qui est au milieu de toi montera toujours plus haut au-dessus de toi, et toi, tu descendras toujours plus bas:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'il te prêtera, et toi, tu ne lui prêteras pas; il sera à la tête, et toi, tu seras à la queue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Et toutes ces malédictions viendront sur toi, et te poursuivront et t’atteindront, jusqu’à ce que tu sois détruit; parce que tu n’as pas écouté la voix de l’ Éternel, ton Dieu, pour garder ses commandements et ses statuts qu’il t’a commandés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'et elles seront sur toi et sur ta semence à toujours comme un signe et comme un prodige.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Parce que tu n’as pas servi l’ Éternel, ton Dieu, avec joie et de bon cœur, à cause de l’abondance de toutes choses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'tu serviras, dans la faim et dans la soif et dans la nudité et dans la disette de toutes choses, tes ennemis que l’ Éternel enverra contre toi; et il mettra un joug de fer sur ton cou, jusqu’à ce qu’il t’ait détruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'L’ Éternel amènera contre toi, de loin, du bout de la terre, une nation semblable à l’aigle qui vole, une nation dont tu n’entends pas la langue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'une nation au visage dur, qui n’a pas égard au vieillard et n’a pas pitié de l’enfant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'et elle mangera le fruit de tes bêtes et le fruit de ta terre, jusqu’à ce que tu sois détruit; car elle ne te laissera de reste ni froment, ni moût, ni huile, ni portée de ton gros bétail, ni accroissement de ton menu bétail, jusqu’à ce qu’elle t’ait fait périr.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Et elle t’assiégera dans toutes tes portes, jusqu’à ce que s’écroulent, dans tout ton pays, tes hautes et fortes murailles en lesquelles tu te confiais; et elle t’assiégera dans toutes tes portes, dans tout ton pays que l’ Éternel, ton Dieu, t’a donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Et, dans le siège et dans la détresse dont ton ennemi t’enserrera, tu mangeras le fruit de ton ventre, la chair de tes fils et de tes filles que l’ Éternel, ton Dieu, t’aura donnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'L’homme tendre et très délicat au milieu de toi regardera d’un œil méchant son frère et la femme de son cœur, et le reste de ses fils qu’il a conservés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'pour ne donner à aucun d’eux de la chair de ses fils qu’il mangera; parce que, dans le siège et dans la détresse dont ton ennemi t’enserrera dans toutes tes portes, il ne lui restera rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'La femme tendre et délicate au milieu de toi, qui, par délicatesse et par mollesse, n’aurait pas tenté de poser la plante de son pied sur la terre, regardera d’un œil méchant l’homme de son cœur, et son fils, et sa fille,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'à cause de son arrière-faix qui sera sorti d’entre ses pieds, et de ses fils qu’elle enfantera; car elle les mangera en secret, dans la disette de toutes choses, dans le siège et dans la détresse dont ton ennemi t’enserrera dans tes portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Si tu ne prends pas garde à faire toutes les paroles de cette loi, qui sont écrites dans ce livre, pour craindre ce nom glorieux et terrible de l’ Éternel, ton Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'alors l’ Éternel rendra extraordinaires tes plaies et les plaies de ta semence, [te frappant] de plaies grandes et opiniâtres, de maladies mauvaises et opiniâtres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'et il fera retourner sur toi tous les maux de l’Égypte, dont tu as peur, et ils s’attacheront à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'L’ Éternel fera venir aussi sur toi toutes les maladies et toutes les plaies qui ne sont pas écrites dans le livre de cette loi, jusqu’à ce que tu sois détruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Et vous resterez un petit nombre d’hommes, au lieu que vous étiez comme les étoiles des cieux en multitude; parce que tu n’as pas écouté la voix de l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Et il arrivera que, comme l’ Éternel se réjouissait à votre égard, pour vous faire du bien et pour vous multiplier, ainsi l’ Éternel se réjouira à votre égard, pour vous faire périr et pour vous détruire; et vous serez arrachés de dessus la terre où tu vas entrer pour la posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Et l’ Éternel te dispersera parmi tous les peuples, d’un bout de la terre jusqu’à l’autre bout de la terre; et là tu serviras d’autres dieux, que ni toi ni tes pères vous n’avez connus, le bois et la pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Et parmi ces nations tu n’auras pas de tranquillité, et il n’y aura pas de repos pour la plante de ton pied; et l’ Éternel te donnera là un cœur tremblant, et des yeux languissants, et une âme défaillante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Et ta vie sera en suspens devant toi; et tu seras dans l’effroi, nuit et jour, et tu ne seras pas sûr de ta vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Le matin tu diras: Qui donnera le soir? et le soir tu diras: Qui donnera le matin? à cause de l’effroi de ton cœur dont tu seras effrayé, et à cause des choses que tu verras de tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Et l’ Éternel te fera retourner en Égypte sur des navires, par le chemin dont je t’ai dit: Tu ne le reverras plus. Et là vous vous vendrez à vos ennemis pour être serviteurs et servantes, et il n’y aura pas d’acheteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 69, 'Ce sont là les paroles de l’alliance que l’ Éternel commanda à Moïse de faire avec les fils d’Israël dans le pays de Moab, outre l’alliance qu’il avait faite avec eux à Horeb.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, '*Et Moïse appela tout Israël, et leur dit: Vous avez vu tout ce que l’ Éternel a fait devant vos yeux dans le pays d’Égypte, au Pharaon, et à tous ses serviteurs, et à tout son pays:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'les grandes épreuves que tes yeux ont vues, ces signes et ces grands prodiges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Mais l’ Éternel ne vous a pas donné un cœur pour connaître, ni des yeux pour voir, ni des oreilles pour entendre, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Et je vous ai conduits 40 ans par le désert: vos vêtements ne se sont pas usés sur vous, et ta sandale ne s’est pas usée à ton pied.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Vous n’avez pas mangé de pain, et vous n’avez bu ni vin ni boisson forte, afin que vous connaissiez que moi, l’ Éternel, je suis votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Et vous êtes parvenus en ce lieu-ci; et Sihon, roi de Hesbon, et Og, le roi de Basan, sortirent à notre rencontre pour nous livrer bataille, et nous les avons battus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'et nous avons pris leur pays, et nous l’avons donné en héritage aux Rubénites, et aux Gadites, et à la demi-tribu des Manassites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Vous garderez donc les paroles de cette alliance et vous les pratiquerez, afin que vous prospériez dans tout ce que vous ferez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Vous vous tenez tous aujourd’hui devant l’ Éternel, votre Dieu, vos chefs, vos tribus, vos anciens, et vos magistrats, tout homme d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'vos enfants, vos femmes, et ton étranger qui est au milieu de ton camp, ton coupeur de bois aussi bien que ton puiseur d’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'afin que tu entres dans l’alliance de l’ Éternel, ton Dieu, et dans son serment, que l’ Éternel, ton Dieu, fait aujourd’hui avec toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'afin qu’il t’établisse aujourd’hui pour être son peuple, et pour qu’il soit ton Dieu, ainsi qu’il te l’a dit, et ainsi qu’il a juré à tes pères, à Abraham, à Isaac, et à Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Et ce n’est pas avec vous seulement que je fais cette alliance et ce serment;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'mais c’est avec celui qui est ici, qui se tient avec nous aujourd’hui devant l’ Éternel, notre Dieu, et avec celui qui n’est pas ici aujourd’hui avec nous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, '(car vous savez comment nous avons habité dans le pays d’Égypte, et comment nous avons passé à travers les nations que vous avez traversées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'et vous avez vu leurs abominations, et leurs idoles, du bois et de la pierre, de l’argent et de l’or, qui sont parmi eux);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'de peur qu’il n’y ait parmi vous homme, ou femme, ou famille, ou tribu, dont le cœur se détourne aujourd’hui d’avec l’ Éternel, notre Dieu, pour aller servir les dieux de ces nations; de peur qu’il n’y ait parmi vous une racine qui produise du poison et de l’absinthe,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'et qu’il n’arrive que quelqu’un, en entendant les paroles de ce serment, ne se bénisse dans son cœur, disant: J’aurai la paix, lors même que je marcherai dans l’obstination de mon cœur, afin de détruire ce qui est arrosé, et ce qui est altéré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'L’ Éternel ne voudra pas lui pardonner, mais la colère de l’ Éternel et sa jalousie fumeront alors contre cet homme; et toute la malédiction qui est écrite dans ce livre reposera sur lui; et l’ Éternel effacera son nom de dessous les cieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'et l’ Éternel le séparera de toutes les tribus d’Israël pour le malheur, selon toutes les malédictions de l’alliance qui est écrite dans ce livre de la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Et la génération à venir, vos fils qui se lèveront après vous, et l’étranger qui viendra d’un pays éloigné, diront, lorsqu’ils verront les plaies de ce pays, et ses maladies, dont l’ Éternel l’aura affligé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, '[et] que tout son sol n’est que soufre et sel, – un embrasement (qu’il n’est pas semé, et qu’il ne fait rien germer, et qu’aucune herbe n’y pousse), comme la subversion de Sodome et de Gomorrhe, d’Adma et de Tseboïm, que l’ Éternel détruisit dans sa colère et dans sa fureur, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'toutes les nations diront: Pourquoi l’ Éternel a-t-il fait ainsi à ce pays? d’où vient l’ardeur de cette grande colère?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Et on dira: C’est parce qu’ils ont abandonné l’alliance de l’ Éternel, le Dieu de leurs pères, qu’il avait faite avec eux quand il les fit sortir du pays d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'et ils sont allés, et ont servi d’autres dieux, et se sont prosternés devant eux, des dieux qu’ils n’avaient pas connus et qu’il ne leur avait pas donnés en partage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Et la colère de l’ Éternel s’est embrasée contre ce pays, pour faire venir sur lui toute la malédiction écrite dans ce livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Et l’ Éternel les a arrachés de dessus leur terre dans [sa] colère, et dans [sa] fureur, et dans [sa] grande indignation, et les a chassés dans un autre pays, comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Les choses cachées sont à l’ Éternel, notre Dieu; et les choses révélées sont à nous et à nos fils, à toujours, afin que nous pratiquions toutes les paroles de cette loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Et lorsque toutes ces choses que j’ai mises devant toi seront venues sur toi, la bénédiction et la malédiction, et lorsque tu les auras rappelées dans ton cœur, parmi toutes les nations où l’ Éternel, ton Dieu, t’aura chassé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'et que tu seras retourné à l’ Éternel, ton Dieu, et que tu auras écouté sa voix, selon tout ce que je te commande aujourd’hui, toi et tes fils, de tout ton cœur et de toute ton âme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'il arrivera que l’ Éternel, ton Dieu, rétablira tes captifs, et aura pitié de toi; et il te rassemblera de nouveau d’entre tous les peuples, où l’ Éternel, ton Dieu, t’avait dispersé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Quand tes dispersés seraient au bout des cieux, l’ Éternel, ton Dieu, te rassemblera de là, et te prendra de là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'et l’ Éternel, ton Dieu, te ramènera dans le pays que tes pères ont possédé, et tu le posséderas; et il te fera du bien, et il te rendra plus nombreux que tes pères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'et l’ Éternel, ton Dieu, circoncira ton cœur et le cœur de ta semence, pour que tu aimes l’ Éternel, ton Dieu, de tout ton cœur et de toute ton âme, afin que tu vives;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'et l’ Éternel, ton Dieu, mettra toutes ces malédictions sur tes ennemis et sur ceux qui te haïssent, qui t’ont persécuté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Et toi, tu reviendras, et tu écouteras la voix de l’ Éternel, et tu pratiqueras tous ses commandements que je te commande aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Et l’ Éternel, ton Dieu, te fera surabonder en prospérité dans toute l’œuvre de ta main, dans le fruit de ton ventre, et dans le fruit de tes bêtes, et dans le fruit de ta terre; car l’ Éternel prendra de nouveau plaisir en toi, pour [ton] bien, comme il a pris plaisir en tes pères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'car tu écouteras la voix de l’ Éternel, ton Dieu, pour garder ses commandements et ses statuts, ce qui est écrit dans ce livre de la loi, quand tu retourneras à l’ Éternel, ton Dieu, de tout ton cœur et de toute ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Car ce commandement que je te commande aujourd’hui, n’est pas trop merveilleux pour toi, et il n’est pas éloigné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Il n’est pas dans les cieux, pour que tu dises: Qui montera pour nous dans les cieux, et le prendra pour nous, et nous le fera entendre, afin que nous le pratiquions?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Et il n’est pas au-delà de la mer, pour que tu dises: Qui passera pour nous au-delà de la mer, et le prendra pour nous, et nous le fera entendre, afin que nous le pratiquions?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Car la parole est très près de toi, dans ta bouche et dans ton cœur, pour la pratiquer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Regarde, j’ai mis aujourd’hui devant toi la vie et le bonheur, et la mort et le malheur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'en ce que je te commande aujourd’hui d’aimer l’ Éternel, ton Dieu, de marcher dans ses voies, de garder ses commandements et ses statuts et ses ordonnances, afin que tu vives et que tu multiplies, et que l’ Éternel, ton Dieu, te bénisse dans le pays où tu entres pour le posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Mais si ton cœur se détourne, et que tu n’écoutes pas, et que tu te laisses séduire, et que tu te prosternes devant d’autres dieux et que tu les serves:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'je vous déclare aujourd’hui que vous périrez certainement, et que vous ne prolongerez pas vos jours sur la terre où, en passant le Jourdain, vous entrez afin de la posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'J’appelle aujourd’hui à témoin contre vous les cieux et la terre: j’ai mis devant toi la vie et la mort, la bénédiction et la malédiction. Choisis la vie, afin que tu vives, toi et ta semence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'en aimant l’ Éternel, ton Dieu, en écoutant sa voix, et en t’attachant à lui; car c’est là ta vie et la longueur de tes jours, afin que tu habites sur la terre que l’ Éternel a juré à tes pères, à Abraham, à Isaac, et à Jacob, de leur donner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Et Moïse alla, et dit ces paroles à tout Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'et il leur dit: Je suis aujourd’hui âgé de 120 ans, je ne puis plus sortir et entrer; et l’ Éternel m’a dit: Tu ne passeras pas ce Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'L’ Éternel, ton Dieu, lui-même, va passer devant toi; c’est lui qui détruira ces nations devant toi, et tu les déposséderas: Josué, lui, va passer devant toi, comme l’ Éternel l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Et l’ Éternel leur fera comme il a fait à Sihon et à Og, rois des Amoréens, et à leur pays, qu’il a détruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Et l’ Éternel les livrera devant vous, et vous leur ferez selon tout le commandement que je vous ai commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Fortifiez-vous et soyez fermes, ne les craignez pas, et ne soyez point épouvantés devant eux; car c’est l’ Éternel, ton Dieu, qui marche avec toi; il ne te laissera pas et il ne t’abandonnera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Et Moïse appela Josué, et lui dit devant les yeux de tout Israël: Fortifie-toi et sois ferme; car toi, tu entreras avec ce peuple dans le pays que l’ Éternel a juré à leurs pères de leur donner, et toi, tu le leur feras hériter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Et l’ Éternel est celui qui marche devant toi; lui, sera avec toi; il ne te laissera pas et il ne t’abandonnera pas: ne crains point, et ne t’effraie point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Et Moïse écrivit cette loi, et la donna aux sacrificateurs, fils de Lévi, qui portaient l’arche de l’alliance de l’ Éternel, et à tous les anciens d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Et Moïse leur commanda, disant: Au bout de sept ans, au temps fixé de l’année de relâche, à la fête des tabernacles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'quand tout Israël viendra pour paraître devant l’ Éternel, ton Dieu, au lieu qu’il aura choisi, tu liras cette loi devant tout Israël, à leurs oreilles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'tu réuniras le peuple, hommes et femmes, et enfants, et ton étranger qui sera dans tes portes, afin qu’ils entendent, et afin qu’ils apprennent, et qu’ils craignent l’ Éternel, votre Dieu, et qu’ils prennent garde à pratiquer toutes les paroles de cette loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'et que leurs fils qui n’en auront pas eu connaissance, entendent, et apprennent à craindre l’ Éternel, votre Dieu, tous les jours que vous vivrez sur la terre où, en passant le Jourdain, vous [entrez] afin de la posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, '*Et l’ Éternel dit à Moïse: Voici, le jour de ta mort s’approche; appelle Josué, et présentez-vous dans la tente d’assignation, afin que je lui donne mon commandement. Et Moïse et Josué allèrent, et se présentèrent dans la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Et l’ Éternel apparut dans la tente, dans la colonne de nuée; et la colonne de nuée se tint sur l’entrée de la tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Et l’ Éternel dit à Moïse: Voici, tu vas dormir avec tes pères; et ce peuple se lèvera et se prostituera après les dieux étrangers du pays au milieu duquel il va entrer; et il m’abandonnera, et rompra mon alliance que j’ai faite avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Et ma colère s’enflammera contre lui en ce jour-là; et je les abandonnerai, et je leur cacherai ma face; et il sera dévoré, et des maux nombreux et des détresses l’atteindront; et il dira en ce jour-là: N’est-ce pas parce que mon Dieu n’est pas au milieu de moi que ces maux m’ont atteint?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Et moi, je cacherai entièrement ma face, en ce jour-là, à cause de tout le mal qu’il aura fait; parce qu’il se sera tourné vers d’autres dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Et maintenant, écrivez ce cantique, et enseigne-le aux fils d’Israël; mets-le dans leur bouche, afin que ce cantique me serve de témoignage contre les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Car je l’introduirai dans la terre ruisselante de lait et de miel, que j’ai promise par serment à ses pères, et il mangera, et sera rassasié et engraissé, et se tournera vers d’autres dieux; et ils les serviront, et ils me mépriseront, et il rompra mon alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Et quand des maux nombreux et des détresses l’auront atteint, il arrivera que ce cantique élèvera la voix devant lui en témoignage; car il ne sera pas oublié dans la bouche de sa postérité; car je connais sa pensée qu’il a formée [déjà] aujourd’hui, avant que je l’introduise dans le pays que je lui ai promis par serment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Et Moïse écrivit ce cantique, en ce jour-là, et il l’enseigna aux fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Et [l’ Éternel] commanda à Josué, fils de Nun, disant: Fortifie-toi et sois ferme, car c’est toi qui introduiras les fils d’Israël dans le pays que je leur ai promis par serment, et moi, je serai avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Et quand Moïse eut achevé d’écrire dans un livre les paroles de cette loi, jusqu’à ce qu’elles soient complètes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'il arriva que Moïse commanda aux Lévites qui portaient l’arche de l’alliance de l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Prenez ce livre de la loi, et placez-le à côté de l’arche de l’alliance de l’ Éternel, votre Dieu; et il sera là en témoignage contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Car moi, je connais ton esprit de rébellion et ton cou roide. Voici, aujourd’hui, tandis que je suis encore vivant avec vous, vous avez été rebelles à l’ Éternel; combien plus [le serez-vous] après ma mort!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Réunissez auprès de moi tous les anciens de vos tribus, et vos magistrats, et je prononcerai ces paroles à leurs oreilles, et j’appellerai à témoin contre eux les cieux et la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Car je sais qu’après ma mort vous vous corromprez certainement, et vous vous détournerez du chemin que je vous ai commandé; et il vous arrivera du mal à la fin des jours, parce que vous ferez ce qui est mauvais aux yeux de l’ Éternel, pour le provoquer à colère par l’œuvre de vos mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, '*Et Moïse prononça aux oreilles de toute la congrégation d’Israël les paroles de ce cantique-ci, jusqu’à ce qu’elles soient complètes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Cieux, prêtez l’oreille, et je parlerai; et [toi] terre, écoute les paroles de ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Ma doctrine distillera comme la pluie; ma parole descendra comme la rosée, comme une pluie fine sur l’herbe tendre, et comme des ondées sur l’herbe mûre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Car je proclamerai le nom de l’ Éternel: Attribuez la grandeur à notre Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Il est le Rocher, son œuvre est parfaite; car toutes ses voies sont justice. C’est un ✶Dieu fidèle, et il n’y a pas d’iniquité [en lui]; il est juste et droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Ils se sont corrompus à son égard, leur tache n’est pas celle de ses fils; c’est une génération tortue et perverse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Est-ce ainsi que vous récompensez l’ Éternel, peuple insensé et dénué de sagesse? N’est-il pas ton père, qui t’a acheté? C’est lui qui t’a fait et qui t’a établi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Souviens-toi des jours d’autrefois, considérez les années de génération en génération; interroge ton père, et il te le déclarera, tes anciens, et ils te le diront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Quand le Très-haut partageait l’héritage aux nations, quand il séparait les fils d’Adam, il établit les limites des peuples selon le nombre des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Car la portion de l’ Éternel, c’est son peuple; Jacob est le lot de son héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Il le trouva dans un pays désert et dans la désolation des hurlements d’une solitude; il le conduisit çà et là; il prit soin de lui, il le garda comme la prunelle de son œil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Comme l’aigle éveille son nid, plane au-dessus de ses petits, étend ses ailes, les prend, les porte sur ses plumes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'L’ Éternel seul l’a conduit, et il n’y a point eu avec lui de ✶dieu étranger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Il l’a fait passer à cheval sur les lieux hauts de la terre; et il a mangé le produit des champs, et il lui a fait sucer le miel du rocher, et l’huile du roc dur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Le caillé des vaches, et le lait des brebis, et la graisse des agneaux et des béliers de la race de Basan, et des boucs, avec la fine graisse du froment; et tu as bu le vin pur, le sang du raisin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Mais Jeshurun s’est engraissé, et a regimbé: tu es devenu gras, gros, replet; et il a abandonné le ✝Dieu qui l’a fait, et il a méprisé le Rocher de son salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Ils l’ont ému à jalousie par des [dieux] étrangers; ils l’ont provoqué à colère par des abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Ils ont sacrifié aux démons qui ne sont point ✝Dieu, à des dieux qu’ils ne connaissaient pas, [dieux] nouveaux, venus depuis peu, que vos pères n’ont pas révérés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Tu as oublié le Rocher qui t’a engendré, et tu as mis en oubli le ✶Dieu qui t’a enfanté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Et l’ Éternel l’a vu et les a rejetés, par indignation contre ses fils et ses filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Et il a dit: Je leur cacherai ma face, je verrai quelle sera leur fin, car ils sont une génération perverse, des fils en qui il n’y a point de fidélité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Ils m’ont ému à jalousie par ce qui n’est point ✶Dieu, ils m’ont provoqué à colère par leurs vanités; et moi, je les exciterai à la jalousie par ce qui n’est pas un peuple, je les provoquerai à la colère par une nation insensée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Car un feu s’est allumé dans ma colère, et il brûlera jusqu’au shéol le plus profond, et dévorera la terre et son rapport, et embrasera les fondements des montagnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'J’accumulerai sur eux des maux; j’épuiserai contre eux mes flèches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Ils seront consumés par la famine et rongés par des ardeurs dévorantes, et par une peste maligne; Et j’enverrai contre eux la dent des bêtes, avec le venin de ce qui rampe dans la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Au-dehors l’épée, et au-dedans la terreur, détruiront le jeune homme et la vierge, l’enfant qui tète et l’homme à cheveux blancs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Je dirais: Je les disperserai, j’abolirai du milieu des hommes leur mémoire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'si je ne craignais la provocation de l’ennemi, que leurs adversaires ne s’y méprennent et qu’ils ne disent: Notre main est élevée, et ce n’est pas l’ Éternel qui a fait tout cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Car ils sont une nation qui a perdu le conseil, et il n’y a en eux aucune intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Oh! s’ils avaient été sages, ils auraient compris ceci, ils auraient considéré leur fin!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Comment un seul en aurait-il poursuivi mille, et deux en auraient-ils mis en fuite dix mille, si leur Rocher ne les avait pas vendus, et si l’ Éternel ne les avait pas livrés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Car leur rocher n’est pas comme notre Rocher, et nos ennemis en sont juges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Car leur vigne est de la vigne de Sodome et du terroir de Gomorrhe; Leurs raisins sont des raisins vénéneux, et leurs grappes sont amères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Leur vin est un venin de monstres et un poison cruel d’aspic.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Cela n’est-il pas caché par-devers moi, scellé dans mes trésors?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'À moi la vengeance et la rétribution, au temps où leur pied bronchera. Car le jour de leur calamité est proche, et ce qui leur est préparé se hâte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Car l’ Éternel jugera son peuple, et se repentira en faveur de ses serviteurs, quand il verra que la force s’en est allée, et qu’il n’y a plus personne, homme lié ou homme libre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Et il dira: Où sont leurs dieux, le rocher en qui ils se confiaient,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Qui mangeaient la graisse de leurs sacrifices, [et] buvaient le vin de leurs libations? Qu’ils se lèvent, et qu’ils vous secourent, qu’ils soient une retraite pour vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Voyez maintenant que c’est moi, moi, le Même, et il n’y a point de dieu à côté de moi; Moi, je tue, et moi, je fais vivre; moi, je blesse, et moi, je guéris; et il n’y a personne qui délivre de ma main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Car je lève ma main aux cieux, et je dis: Je vis éternellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Si j’aiguise l’éclair de mon épée et que ma main saisisse le jugement, je rendrai la vengeance à mes adversaires et je récompenserai ceux qui me haïssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'J’enivrerai mes flèches de sang, et mon épée dévorera de la chair; [je les enivrerai] du sang des tués et des captifs, de la tête des chefs de l’ennemi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Réjouissez-vous, nations, [avec] son peuple; car il vengera le sang de ses serviteurs, et il rendra la vengeance à ses adversaires, et il pardonnera à sa terre, à son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, '*Et Moïse vint, et prononça toutes les paroles de ce cantique aux oreilles du peuple, lui et Josué, fils de Nun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Et Moïse acheva de prononcer toutes ces paroles à tout Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'et il leur dit: Appliquez votre cœur à toutes les paroles par lesquelles je rends témoignage parmi vous aujourd’hui, pour les commander à vos fils, afin qu’ils prennent garde à pratiquer toutes les paroles de cette loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Car ce n’est pas ici une parole vaine pour vous, mais c’est votre vie; et par cette parole vous prolongerez [vos] jours sur la terre où, en passant le Jourdain, vous [entrez] afin de la posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Et, en ce même jour, l’ Éternel parla à Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Monte sur cette montagne d’Abarim, le mont Nebo, qui est dans le pays de Moab, qui est vis-à-vis de Jéricho; et regarde le pays de Canaan que je donne en possession aux fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Et tu mourras sur la montagne sur laquelle tu monteras, et tu seras recueilli vers tes peuples, comme Aaron, ton frère, est mort sur la montagne de Hor et a été recueilli vers ses peuples;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'parce que vous avez été infidèles envers moi, au milieu des fils d’Israël, aux eaux de Meriba-Kadès, dans le désert de Tsin, en ce que vous ne m’avez pas sanctifié au milieu des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Car tu verras devant toi le pays, mais tu n’y entreras pas, dans le pays que je donne aux fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, '*Et c’est ici la bénédiction dont Moïse, homme de Dieu, bénit les fils d’Israël, avant sa mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Et il dit: L’ Éternel est venu de Sinaï, et il s’est levé pour eux de Séhir; il a resplendi de la montagne de Paran, et est venu des saintes myriades; de sa droite [sortit] une loi de feu pour eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Oui, il aime les peuples; tous ses saints sont dans ta main, et ils se tiennent à tes pieds; ils reçoivent tes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Moïse nous a commandé une loi, héritage de la congrégation de Jacob;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'et il a été roi en Jeshurun, quand les chefs du peuple se réunirent ensemble avec les tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Que Ruben vive et ne meure pas, et que ses hommes soient en petit nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Et ceci pour Juda: et il dit: Éternel, écoute la voix de Juda, et amène-le à son peuple; qu’il combatte de ses mains pour lui, et sois-lui en aide contre ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Et de Lévi il dit: Tes thummim et tes urim sont à l’homme de ta bonté, que tu as éprouvé à Massa, [et] avec lequel tu as contesté aux eaux de Meriba;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Qui dit de son père et de sa mère: Je ne l’ai point vu; et qui n’a pas reconnu ses frères, et n’a pas connu ses fils. Car ils ont gardé tes paroles et observé ton alliance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Ils enseigneront tes ordonnances à Jacob et ta loi à Israël; ils mettront l’encens sous tes narines et l’holocauste sur ton autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Éternel! bénis sa force; et que l’œuvre de ses mains te soit agréable! Brise les reins de ceux qui s’élèvent contre lui, et de ceux qui le haïssent, en sorte qu’ils ne puissent plus se relever.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'De Benjamin il dit: Le bien-aimé de l’ Éternel, – il habitera en sécurité auprès de lui; [l’ Éternel] le couvrira tout le jour, et il habitera entre ses épaules.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Et de Joseph il dit: Son pays soit béni par l’ Éternel de ce qu’il y a de plus précieux au ciel, de la rosée, et [de ce qui vient] des profondeurs qui gisent en bas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Et du plus précieux des produits du soleil, et du plus précieux des produits des mois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'Et de [ce qui croît sur] le sommet des montagnes d’ancienneté, et du plus précieux des collines éternelles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Et du plus précieux de la terre et de sa plénitude. Et que la faveur de celui qui demeurait dans le buisson, vienne sur la tête de Joseph, sur le sommet de la tête de celui qui a été mis à part de ses frères!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Sa magnificence est comme le premier-né de son taureau, et ses cornes sont des cornes de buffle. Avec elles, il poussera les peuples ensemble jusqu’aux bouts de la terre. Ce sont les myriades d’Éphraïm, et ce sont les milliers de Manassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Et de Zabulon il dit: Réjouis-toi, Zabulon, en ta sortie; et toi, Issacar, dans tes tentes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Ils appelleront les peuples à la montagne; là ils offriront des sacrifices de justice, car ils suceront l’abondance des mers, et les trésors cachés du sable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Et de Gad il dit: Béni soit celui qui élargit Gad. Il habite comme une lionne, et il déchire le bras, même le sommet de la tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Et il s’est choisi la première partie [du pays]; car là était réservée la part du législateur; et il est allé [avec] les chefs du peuple; il a accompli avec Israël la justice de l’ Éternel et ses jugements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Et de Dan il dit: Dan est un jeune lion, il s’élance de Basan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Et de Nephthali il dit: Nephthali, rassasié de faveurs et comblé de la bénédiction de l’ Éternel, possède la mer et le Darôm!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Et d’Aser il dit: Aser sera béni en fils; il sera agréable à ses frères, et il trempera son pied dans l’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Tes verrous seront de fer et d’airain, et ton repos comme tes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Nul n’est comme le ✶Dieu de Jeshurun, qui est porté sur les cieux à ton secours, et sur les nuées dans sa majesté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Le Dieu d’ancienneté est [ta] demeure, et au-dessous [de toi] sont les bras éternels; il chasse l’ennemi devant toi, et il dit: Détruis!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Et Israël habitera en sécurité, la source de Jacob, à part, dans un pays de froment et de moût, et ses cieux distilleront la rosée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Tu es bienheureux, Israël! Qui est comme toi, un peuple sauvé par l’ Éternel, le bouclier de ton secours et l’épée de ta gloire? Tes ennemis dissimuleront devant toi, et toi, tu marcheras sur leurs lieux élevés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, '*Et Moïse monta des plaines de Moab sur le mont Nebo, le sommet du Pisga, qui est vis-à-vis de Jéricho; et l’ Éternel lui fit voir tout le pays: Galaad, jusqu’à Dan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'et tout Nephthali, et le pays d’Éphraïm et de Manassé, et tout le pays de Juda jusqu’à la mer d’occident,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'et le midi, et la plaine [du Jourdain], la vallée de Jéricho, la ville des palmiers, jusqu’à Tsoar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, '– Et l’ Éternel lui dit: C’est ici le pays au sujet duquel j’ai juré à Abraham, à Isaac, et à Jacob, disant: Je le donnerai à ta semence. Je te l’ai fait voir de tes yeux, mais tu n’y passeras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Et Moïse, serviteur de l’ Éternel, mourut là dans le pays de Moab, selon la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Et il l’enterra dans la vallée, dans le pays de Moab, vis-à-vis de Beth-Péor; et personne ne connaît son sépulcre, jusqu’à aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Et Moïse était âgé de 120 ans quand il mourut; son œil n’était pas affaibli, et sa vigueur ne s’en était pas allée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, '– Et les fils d’Israël pleurèrent Moïse dans les plaines de Moab, 30 jours; et les jours des pleurs du deuil de Moïse furent terminés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Et Josué, fils de Nun, était rempli de l’esprit de sagesse, car Moïse avait posé ses mains sur lui; et les fils d’Israël l’écoutèrent, et firent comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Et il ne s’est plus levé en Israël de prophète tel que Moïse, que l’ Éternel ait connu face à face,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'selon tous les signes et les merveilles que l’ Éternel l’envoya faire dans le pays d’Égypte contre le Pharaon et tous ses serviteurs et tout son pays,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'et selon toute cette main forte, et selon tous les terribles prodiges que fit Moïse aux yeux de tout Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Et il arriva, après la mort de Moïse, serviteur de l’ Éternel, que l’ Éternel parla à Josué, fils de Nun, qui servait Moïse, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Moïse, mon serviteur, est mort; et maintenant, lève-toi, passe ce Jourdain, toi et tout ce peuple, [pour entrer] dans le pays que je leur donne à eux, les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Tout lieu que foulera la plante de votre pied, je vous l’ai donné, comme j’ai dit à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Vos frontières seront depuis le désert et ce Liban jusqu’au grand fleuve, le fleuve Euphrate, tout le pays des Héthiens, et jusqu’à la grande mer, vers le soleil couchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Personne ne tiendra devant toi, tous les jours de ta vie; comme j’ai été avec Moïse, ainsi je serai avec toi: je ne te laisserai point et je ne t’abandonnerai point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Fortifie-toi et sois ferme, car toi, tu feras hériter à ce peuple le pays que j’ai juré à leurs pères de leur donner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Seulement fortifie-toi et sois très ferme, pour prendre garde à faire selon toute la loi que Moïse, mon serviteur, t’a commandée; ne t’en écarte ni à droite ni à gauche, afin que tu prospères partout où tu iras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Que ce livre de la loi ne s’éloigne pas de ta bouche, et médite-le jour et nuit, afin que tu prennes garde à faire selon tout ce qui y est écrit; car alors tu feras réussir tes voies, et alors tu prospéreras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Ne t’ai-je pas commandé: Fortifie-toi et sois ferme? Ne te laisse point terrifier, et ne sois point effrayé; car l’ Éternel, ton Dieu, est avec toi partout où tu iras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Et Josué commanda aux officiers du peuple, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Passez par le milieu du camp, et commandez au peuple, disant: Préparez-vous des provisions, car dans trois jours vous passerez ce Jourdain pour aller prendre possession du pays que l’ Éternel, votre Dieu, vous donne pour le posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Et Josué parla aux Rubénites, et aux Gadites, et à la demi-tribu de Manassé, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Souvenez-vous de la parole que Moïse, serviteur de l’ Éternel, vous a commandée, disant: L’ Éternel, votre Dieu, vous a donné du repos, et vous a donné ce pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Vos femmes, vos enfants, et vos troupeaux, demeureront dans le pays que Moïse vous a donné en deçà du Jourdain; et vous passerez armés devant vos frères, vous tous, les vaillants hommes, et vous les aiderez');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'jusqu’à ce que l’ Éternel donne du repos à vos frères, comme à vous, et qu’eux aussi, ils possèdent le pays que l’ Éternel, votre Dieu, leur donne; alors vous retournerez dans le pays de votre possession, et vous le posséderez, celui que Moïse, serviteur de l’ Éternel, vous a donné en deçà du Jourdain, vers le soleil levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Et ils répondirent à Josué, disant: Tout ce que tu nous commandes, nous le ferons, et nous irons partout où tu nous enverras:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'comme nous avons écouté Moïse en toute chose, ainsi nous t’écouterons; seulement, que l’ Éternel, ton Dieu, soit avec toi, comme il a été avec Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Tout homme qui sera rebelle à ton commandement et qui n’écoutera pas tes paroles en tout ce que tu nous commanderas, sera mis à mort; seulement fortifie-toi et sois ferme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, '*Et Josué, fils de Nun, envoya secrètement de Sittim deux espions, disant: Allez, voyez le pays et Jéricho. Et ils s’en allèrent, et vinrent dans la maison d’une prostituée, nommée Rahab, et y couchèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Et on parla au roi de Jéricho, disant: Voici, des hommes d’entre les fils d’Israël sont venus ici cette nuit pour examiner le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Et le roi de Jéricho envoya vers Rahab, disant: Fais sortir les hommes qui sont venus chez toi, qui sont entrés dans ta maison; car ils sont venus pour examiner tout le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Et la femme prit les deux hommes et les cacha; et elle dit: Il est vrai, les hommes sont venus chez moi, et je ne savais pas d’où ils étaient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'et comme la porte allait être fermée, dans les ténèbres, les hommes sont sortis; je ne sais pas où ces hommes sont allés; poursuivez-les en hâte, car vous les atteindrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Or elle les avait fait monter sur le toit, et les avait cachés sous des tiges de lin qu’elle avait arrangées pour elle sur le toit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Et les hommes les poursuivirent par le chemin du Jourdain, jusqu’aux gués; et après que ceux qui les poursuivaient furent sortis, on ferma la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Et, avant qu’ils se couchent, elle monta vers les hommes sur le toit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'et leur dit: Je sais que l’ Éternel vous a donné le pays, et que la terreur de votre [nom] est tombée sur nous, et que tous les habitants du pays se fondent devant vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'car nous avons entendu comment l’ Éternel a mis à sec les eaux de la mer Rouge devant vous, lorsque vous sortiez d’Égypte, et ce que vous avez fait aux deux rois des Amoréens qui étaient au-delà du Jourdain, à Sihon et à Og, que vous avez entièrement détruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Nous l’avons entendu, et notre cœur s’est fondu, et le courage d’aucun homme ne se soutient plus devant vous; car l’ Éternel, votre Dieu, est Dieu dans les cieux en haut, et sur la terre en bas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Et maintenant, je vous prie, jurez-moi par l’ Éternel, que, puisque j’ai usé de bonté envers vous, vous aussi vous userez de bonté envers la maison de mon père; et vous me donnerez un signe certain');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'que vous laisserez vivre mon père, et ma mère, et mes frères, et mes sœurs, et tous ceux qui sont à eux, et que vous sauverez nos âmes de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Et les hommes lui dirent: Nos vies paieront pour vous, si vous ne divulguez pas notre affaire, et il arrivera que, lorsque l’ Éternel nous aura donné le pays, nous userons de bonté et de vérité envers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Et elle les fit descendre avec une corde par la fenêtre, car sa maison était sur la muraille du rempart, et elle habitait sur le rempart.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Et elle leur dit: Allez à la montagne, de peur que ceux qui [vous] poursuivent ne vous rencontrent; et cachez-vous là trois jours, jusqu’à ce que ceux qui [vous] poursuivent soient de retour; et après, vous irez votre chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Et les hommes lui dirent: Nous serons quittes de ce serment que tu nous as fait prêter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Voici, nous allons entrer dans le pays; tu attacheras ce cordon de fil écarlate à la fenêtre par laquelle tu nous as fait descendre, et tu rassembleras auprès de toi, dans la maison, ton père, et ta mère, et tes frères, et toute la maison de ton père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Et il arrivera que quiconque sortira hors des portes de ta maison, son sang sera sur sa tête, et nous serons quittes; mais quiconque sera avec toi dans la maison, son sang sera sur notre tête, si on met la main sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Et si tu divulgues notre affaire, nous serons quittes du serment que tu nous as fait prêter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Et elle dit: Qu’il en soit selon vos paroles. Et elle les renvoya, et ils s’en allèrent; et elle attacha le cordon d’écarlate à la fenêtre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Et ils s’en allèrent, et vinrent à la montagne, et demeurèrent là trois jours, jusqu’à ce que ceux qui les poursuivaient soient de retour. Et ceux qui les poursuivaient cherchèrent par tout le chemin, et ils ne les trouvèrent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Et les deux hommes s’en retournèrent et descendirent de la montagne, et passèrent, et vinrent vers Josué, fils de Nun, et lui racontèrent tout ce qui leur était arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Et ils dirent à Josué: Oui, l’ Éternel a livré tout le pays en nos mains; et aussi tous les habitants du pays se fondent devant nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, '*Et Josué se leva de bonne heure le matin; et ils partirent de Sittim et vinrent jusqu’au Jourdain, lui et tous les fils d’Israël, et là ils passèrent la nuit avant de traverser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Et il arriva, au bout de trois jours, que les officiers passèrent au milieu du camp;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'et ils commandèrent au peuple, disant: Aussitôt que vous verrez l’arche de l’alliance de l’ Éternel, votre Dieu, et les sacrificateurs, les Lévites, qui la portent, vous partirez de là où vous êtes, et vous marcherez après elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Seulement, il y aura entre vous et elle une distance de la mesure d’environ 2 000 coudées: n’en approchez pas, afin que vous connaissiez le chemin par lequel vous devez marcher, car vous n’avez pas passé par ce chemin précédemment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Et Josué dit au peuple: Sanctifiez-vous, car demain l’ Éternel fera des merveilles au milieu de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Et Josué parla aux sacrificateurs, disant: Chargez sur vous l’arche de l’alliance, et passez devant le peuple. Et ils chargèrent sur eux l’arche de l’alliance, et marchèrent devant le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Et l’ Éternel dit à Josué: Aujourd’hui je commencerai à t’élever aux yeux de tout Israël, afin qu’ils sachent que, comme j’ai été avec Moïse, ainsi je serai avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Et toi, commande aux sacrificateurs qui portent l’arche de l’alliance, disant: Lorsque vous arriverez au bord des eaux du Jourdain, vous vous arrêterez dans le Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Et Josué dit aux fils d’Israël: Approchez d’ici, et écoutez les paroles de l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Et Josué dit: À ceci vous connaîtrez que le ✶Dieu vivant est au milieu de vous, et qu’il dépossédera certainement devant vous le Cananéen, et le Héthien, et le Hévien, et le Phérézien, et le Guirgasien, et l’Amoréen, et le Jébusien:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'voici, l’arche de l’alliance du Seigneur de toute la terre va passer devant vous dans le Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Et maintenant, prenez douze hommes des tribus d’Israël, un homme par tribu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Et il arrivera que, lorsque les plantes des pieds des sacrificateurs qui portent l’arche de l’ Éternel, le Seigneur de toute la terre, se poseront dans les eaux du Jourdain, les eaux du Jourdain seront coupées, les eaux qui descendent d’en haut, et elles s’arrêteront en un monceau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Et il arriva que, lorsque le peuple partit de ses tentes pour passer le Jourdain, les sacrificateurs qui portaient l’arche de l’alliance étaient devant le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Et comme ceux qui portaient l’arche arrivèrent au Jourdain et que les pieds des sacrificateurs qui portaient l’arche trempèrent au bord de l’eau (or le Jourdain regorge par-dessus tous ses bords, tout le temps de la moisson),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'les eaux qui descendaient d’en haut s’arrêtèrent: elles s’élevèrent en un monceau très loin, près d’Adam, ville qui est à côté de Tsarthan; et celles qui descendaient à la mer de la plaine, la mer Salée, s’écoulèrent complètement; et le peuple passa vis-à-vis de Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Et les sacrificateurs qui portaient l’arche de l’alliance de l’ Éternel, s’arrêtèrent de pied ferme sur le sec, au milieu du Jourdain; et tout Israël passa à sec, jusqu’à ce que toute la nation eut achevé de passer le Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Et il arriva, quand toute la nation eut achevé de passer le Jourdain, que l’ Éternel parla à Josué, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Prenez d’entre le peuple douze hommes, un homme de chaque tribu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'et commandez-leur, disant: Enlevez d’ici, du milieu du Jourdain, de là où se sont tenus les pieds des sacrificateurs, douze pierres; et vous les transporterez avec vous, et vous les poserez dans le lieu où vous passerez cette nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Et Josué appela les douze hommes qu’il avait désignés d’entre les fils d’Israël, un homme de chaque tribu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'et Josué leur dit: Passez devant l’arche de l’ Éternel, votre Dieu, au milieu du Jourdain, et levez chacun de vous une pierre sur son épaule, selon le nombre des tribus des fils d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'afin que cela soit un signe au milieu de vous. Lorsque dans l’avenir vos fils demanderont, disant: Que signifient pour vous ces pierres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'alors vous leur direz que les eaux du Jourdain furent coupées devant l’arche de l’alliance de l’ Éternel; lorsqu’elle passa dans le Jourdain, les eaux du Jourdain furent coupées. Et ces pierres serviront de mémorial aux fils d’Israël pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Et les fils d’Israël firent comme Josué avait commandé: ils enlevèrent douze pierres du milieu du Jourdain, comme l’ Éternel l’avait dit à Josué, selon le nombre des tribus des fils d’Israël; et ils les transportèrent avec eux au lieu de leur campement, et les posèrent là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Et Josué dressa douze pierres au milieu du Jourdain, à la place où s’étaient tenus les pieds des sacrificateurs qui portaient l’arche de l’alliance; et elles sont là jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Et les sacrificateurs qui portaient l’arche s’arrêtèrent au milieu du Jourdain, jusqu’à ce que tout ce que l’ Éternel avait commandé à Josué de dire au peuple soit exécuté, selon tout ce que Moïse avait commandé à Josué; et le peuple se hâta et passa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Et quand tout le peuple eut achevé de passer, il arriva que l’arche de l’ Éternel et les sacrificateurs passèrent devant le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Et les fils de Ruben, et les fils de Gad, et la moitié de la tribu de Manassé, passèrent armés devant les fils d’Israël, comme leur avait dit Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Environ 40 000 hommes, équipés en guerre, passèrent devant l’ Éternel pour combattre, dans les plaines de Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'En ce jour-là, l’ Éternel éleva Josué aux yeux de tout Israël, et ils le craignirent comme ils avaient craint Moïse, tous les jours de sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Et l’ Éternel parla à Josué, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Commande aux sacrificateurs qui portent l’arche du témoignage, qu’ils montent hors du Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Et Josué commanda aux sacrificateurs, disant: Montez hors du Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Et il arriva que, comme les sacrificateurs qui portaient l’arche de l’alliance de l’ Éternel montèrent du milieu du Jourdain, [et] que les plantes des pieds des sacrificateurs se retirèrent sur le sec, les eaux du Jourdain retournèrent en leur lieu, et coulèrent par-dessus tous ses bords comme auparavant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Et le peuple monta hors du Jourdain, le dixième [jour] du premier mois; et ils campèrent à Guilgal, à l’extrémité orientale de Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Et ces douze pierres qu’ils avaient prises du Jourdain, Josué les dressa à Guilgal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Et il parla aux fils d’Israël, disant: Lorsque dans l’avenir vos fils interrogeront leurs pères, disant: Que sont ces pierres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'vous instruirez vos fils, en disant: Israël a passé ce Jourdain à sec,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'parce que l’ Éternel, votre Dieu, sécha les eaux du Jourdain devant vous jusqu’à ce que vous ayez passé, comme l’ Éternel, votre Dieu, a fait à la mer Rouge, qu’il mit à sec devant nous jusqu’à ce que nous ayons passé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'afin que tous les peuples de la terre connaissent la main de l’ Éternel, qu’elle est forte; afin que vous craigniez toujours l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, '*Et il arriva que, lorsque tous les rois des Amoréens qui étaient en deçà du Jourdain vers l’occident, et tous les rois des Cananéens qui étaient près de la mer, entendirent comment l’ Éternel avait mis à sec les eaux du Jourdain devant les fils d’Israël, jusqu’à ce que nous soyons passés, leur cœur se fondit, et il n’y eut plus de courage en eux, à cause des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'En ce temps-là, l’ Éternel dit à Josué: Fais-toi des couteaux de pierre, et circoncis encore une fois les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Et Josué se fit des couteaux de pierre, et circoncit les fils d’Israël à la colline d’Araloth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Et c’est ici la raison pour laquelle Josué [les] circoncit: tout le peuple qui était sorti d’Égypte, les mâles, tous les hommes de guerre, étaient morts dans le désert, en chemin, après être sortis d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'car tout le peuple qui était sorti avait bien été circoncis, mais de tout le peuple né dans le désert, en chemin, après être sorti d’Égypte, aucun n’avait été circoncis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Car les fils d’Israël avaient marché dans le désert 40 ans, jusqu’à ce qu’ait péri toute la nation des hommes de guerre sortis d’Égypte, qui n’avaient pas écouté la voix de l’ Éternel, auxquels l’ Éternel avait juré de ne point leur faire voir le pays que l’ Éternel avait juré à leurs pères de nous donner, pays ruisselant de lait et de miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Et il suscita leurs fils à leur place: ceux-là, Josué les circoncit, car ils étaient incirconcis, parce qu’on ne les avait pas circoncis en chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Et il arriva que, lorsqu’on eut achevé de circoncire toute la nation, ils demeurèrent à leur place dans le camp, jusqu’à ce qu’ils soient guéris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Et l’ Éternel dit à Josué: Aujourd’hui j’ai roulé de dessus vous l’opprobre de l’Égypte. Et on appela le nom de ce lieu-là Guilgal, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Et les fils d’Israël campèrent à Guilgal; et ils célébrèrent la Pâque, le quatorzième jour du mois, au soir, dans les plaines de Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Et dès le lendemain de la Pâque, ils mangèrent du vieux blé du pays, des pains sans levain et du grain rôti, en ce même jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Et la manne cessa dès le lendemain, après qu’ils eurent mangé du vieux blé du pays; et il n’y eut plus de manne pour les fils d’Israël; et ils mangèrent du cru du pays de Canaan cette année-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Et il arriva, comme Josué était près de Jéricho, qu’il leva ses yeux et vit; et voici, un homme se tenait debout devant lui, son épée nue dans sa main; et Josué alla vers lui et lui dit: Es-tu pour nous, ou pour nos ennemis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Et il dit: Non, car c’est comme chef de l’armée de l’ Éternel que je suis venu maintenant. Et Josué tomba sur sa face contre terre, et lui rendit hommage, et lui dit: Qu’est-ce que mon Seigneur dit à son serviteur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Et le chef de l’armée de l’ Éternel dit à Josué: Ôte ta sandale de ton pied, car le lieu sur lequel tu te tiens est saint. Et Josué fit ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, '*Et Jéricho était fermée, et avait barré [ses portes] devant les fils d’Israël; personne ne sortait, et personne n’entrait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Et l’ Éternel dit à Josué: Vois, j’ai livré en ta main Jéricho, et son roi [et ses] hommes vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Et vous ferez le tour de la ville, vous tous les hommes de guerre, en tournant autour de la ville une fois: tu feras ainsi pendant six jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Et sept sacrificateurs porteront sept trompettes retentissantes devant l’arche; et le septième jour, vous ferez le tour de la ville sept fois, et les sacrificateurs sonneront des trompettes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Et il arrivera que, lorsqu’ils sonneront longuement de la corne retentissante, aussitôt que vous entendrez le son de la trompette, tout le peuple jettera un grand cri, et la muraille de la ville tombera sous elle-même, et le peuple montera, chacun devant soi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Et Josué, fils de Nun, appela les sacrificateurs, et leur dit: Portez l’arche de l’alliance, et que sept sacrificateurs portent sept trompettes retentissantes devant l’arche de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Et il dit au peuple: Passez, et faites le tour de la ville, et que les hommes armés passent devant l’arche de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Et il arriva, quand Josué eut parlé au peuple, que les sept sacrificateurs qui portaient les sept trompettes retentissantes devant l’ Éternel passèrent et sonnèrent des trompettes; et l’arche de l’alliance de l’ Éternel allait après eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Et les hommes armés allaient devant les sacrificateurs qui sonnaient des trompettes, et l’arrière-garde marchait après l’arche; ils sonnaient des trompettes en marchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Et Josué avait commandé au peuple, disant: Vous ne jetterez pas de cris, et vous ne ferez pas entendre votre voix, et il ne sortira pas de votre bouche un seul mot, jusqu’au jour où je vous dirai: Criez; alors vous crierez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Et l’arche de l’ Éternel fit le tour de la ville, tournant autour une fois; puis ils entrèrent dans le camp, et passèrent la nuit dans le camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Et Josué se leva de bonne heure le matin, et les sacrificateurs portèrent l’arche de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Et les sept sacrificateurs qui portaient les sept trompettes retentissantes devant l’arche de l’ Éternel, marchaient, et en allant sonnaient des trompettes; et les hommes armés allaient devant eux; et l’arrière-garde marchait après l’arche de l’ Éternel; ils sonnaient des trompettes en marchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Et le second jour, ils firent le tour de la ville une fois, puis ils revinrent dans le camp. Ils firent ainsi, six jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Et le septième jour, ils se levèrent de bonne heure, au lever de l’aurore, et firent le tour de la ville, de la même manière, sept fois; seulement, ce jour-là, ils firent le tour de la ville sept fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Et à la septième fois, comme les sacrificateurs sonnaient des trompettes, il arriva que Josué dit au peuple: Criez; car l’ Éternel vous a donné la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Et la ville sera anathème à l’ Éternel, elle et tout ce qui s’y trouve; Rahab seule, la prostituée, vivra, elle et tous ceux qui sont chez elle dans la maison, parce qu’elle a caché les messagers que nous avions envoyés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Seulement vous vous garderez de l’anathème, de peur qu’en prenant de l’anathème, vous ne vous rendiez [vous-mêmes] anathème, et que vous ne fassiez devenir anathème le camp d’Israël, et que vous ne le troubliez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Et tout l’argent, et l’or, et les vases d’airain et de fer, seront saints, [consacrés] à l’ Éternel: ils entreront dans le trésor de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Et le peuple jeta des cris, et on sonna des trompettes. Et comme le peuple entendait le son des trompettes et que le peuple jetait un grand cri, la muraille tomba sous elle-même, et le peuple monta dans la ville, chacun devant soi, et ils prirent la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Et ils détruisirent entièrement, par le tranchant de l’épée, tout ce qui était dans la ville, et homme et femme, et enfant et vieillard, les bœufs, les moutons et les ânes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Et Josué dit aux deux hommes qui avaient exploré le pays: Entrez dans la maison de la prostituée, et faites-en sortir la femme et tous ceux qui sont à elle, comme vous le lui avez juré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Et les jeunes hommes, les espions, entrèrent et firent sortir Rahab, et son père, et sa mère, et ses frères, et tous ceux qui étaient à elle; ils firent sortir toutes les familles des siens, et ils les laissèrent en dehors du camp d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Et ils brûlèrent par le feu la ville et tout ce qui y était; seulement l’argent et l’or, et les vases d’airain et de fer, ils les mirent dans le trésor de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Et Josué conserva la vie à Rahab, la prostituée, et à la maison de son père, et à tous ceux qui étaient à elle; et elle a habité au milieu d’Israël jusqu’à ce jour, car elle avait caché les messagers que Josué avait envoyés pour explorer Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Et Josué jura en ce temps-là, disant: Maudit soit devant l’ Éternel l’homme qui se lèvera et bâtira cette ville de Jéricho! Il la fondera sur son premier-né, et en posera les portes sur son plus jeune fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Et l’ Éternel était avec Josué; et sa renommée se répandit dans tout le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, '*Mais les fils d’Israël commirent un crime au sujet de l’anathème: Acan, fils de Carmi, fils de Zabdi, fils de Zérakh, de la tribu de Juda, prit de l’anathème; et la colère de l’ Éternel s’embrasa contre les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Or Josué envoya de Jéricho des hommes vers Aï, qui est près de Beth-Aven, à l’orient de Béthel, et leur parla, disant: Montez, et explorez le pays. Et les hommes montèrent, et explorèrent Aï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Et ils retournèrent vers Josué, et lui dirent: Que tout le peuple ne monte point; que 2 000 ou 3 000 hommes environ montent, et ils frapperont Aï. Ne fatigue pas tout le peuple [en l’envoyant] là; car ils sont peu nombreux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Et il y monta du peuple environ 3 000 hommes; mais ils s’enfuirent devant les hommes d’Aï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Et les hommes d’Aï en frappèrent environ 36 hommes, et ils les poursuivirent depuis la porte jusqu’à Shebarim, et les battirent à la descente; et le cœur du peuple se fondit et devint comme de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Et Josué déchira ses vêtements, et tomba sur sa face contre terre, devant l’arche de l’ Éternel, jusqu’au soir, lui et les anciens d’Israël, et ils jetèrent de la poussière sur leurs têtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Et Josué dit: Hélas, Seigneur Éternel! pourquoi donc as-tu fait passer le Jourdain à ce peuple, pour nous livrer en la main de l’Amoréen, pour nous faire périr? Si seulement nous avions su être contents, et que nous soyons demeurés au-delà du Jourdain!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Hélas, Seigneur! que dirai-je, après qu’Israël a tourné le dos devant ses ennemis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Le Cananéen et tous les habitants du pays l’entendront, et nous envelopperont, et ils retrancheront notre nom de dessus la terre; et que feras-tu pour ton grand nom?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Et l’ Éternel dit à Josué: Lève-toi; pourquoi te jettes-tu ainsi sur ta face?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israël a péché, et même ils ont transgressé mon alliance que je leur avais commandée, et même ils ont pris de l’anathème, et même ils ont volé, et même ils ont menti, et ils l’ont aussi mis dans leur bagage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Et les fils d’Israël ne pourront subsister devant leurs ennemis, ils tourneront le dos devant leurs ennemis; car ils sont devenus anathème. Je ne serai plus avec vous si vous ne détruisez pas l’anathème du milieu de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Lève-toi, sanctifie le peuple, et dis: Sanctifiez-vous pour demain; car ainsi a dit l’ Éternel, le Dieu d’Israël: Il y a de l’anathème au milieu de toi, Israël; tu ne pourras pas subsister devant tes ennemis, jusqu’à ce que vous ayez ôté l’anathème du milieu de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Vous vous approcherez le matin, selon vos tribus; et il arrivera que la tribu que l’ Éternel prendra s’approchera par familles; et la famille que l’ Éternel prendra s’approchera par maisons; et la maison que l’ Éternel prendra s’approchera par hommes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'et il arrivera que celui qui aura été pris avec de l’anathème sera brûlé au feu, lui et tout ce qui est à lui; car il a transgressé l’alliance de l’ Éternel, et il a commis une iniquité en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Et Josué se leva de bonne heure le matin, et fit approcher Israël selon ses tribus; et la tribu de Juda fut prise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Et il fit approcher les familles de Juda; et il prit la famille des Zarkhites. Et il fit approcher la famille des Zarkhites par hommes; et Zabdi fut pris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Et il fit approcher sa maison par hommes; et Acan, fils de Carmi, fils de Zabdi, fils de Zérakh, de la tribu de Juda, fut pris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Et Josué dit à Acan: Mon fils, je te prie, donne gloire à l’ Éternel, le Dieu d’Israël, et rends-lui louange; et déclare-moi, je te prie, ce que tu as fait; ne me le cache pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Et Acan répondit à Josué et dit: En vérité, j’ai péché contre l’ Éternel, le Dieu d’Israël, et j’ai fait telle et telle chose:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'j’ai vu parmi le butin un beau manteau de Shinhar, et 200 sicles d’argent, et un lingot d’or du poids de 50 sicles; je les ai convoités, et je les ai pris; et voilà, ils sont cachés dans la terre, au milieu de ma tente, et l’argent est dessous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Et Josué envoya des messagers qui coururent à la tente, et voici, [le manteau] était caché dans la tente d’Acan, et l’argent dessous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Et ils les prirent du milieu de la tente, et les apportèrent à Josué et à tous les fils d’Israël, et les déposèrent devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Alors Josué et tout Israël avec lui prirent Acan, fils de Zérakh, et l’argent, et le manteau, et le lingot d’or, et ses fils, et ses filles, et ses bœufs, et ses ânes, et son menu bétail, et sa tente, et tout ce qui était à lui, et les firent monter dans la vallée d’Acor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Et Josué dit: Comme tu nous as troublés! L’ Éternel te troublera en ce jour. Et tout Israël le lapida avec des pierres, et ils les brûlèrent au feu et les assommèrent avec des pierres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Et ils élevèrent sur lui un grand monceau de pierres, [qui est demeuré] jusqu’à ce jour. Et l’ Éternel revint de l’ardeur de sa colère. C’est pourquoi on a appelé le nom de ce lieu-là la vallée d’Acor, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, '*Et l’ Éternel dit à Josué: Ne crains point, et ne t’effraie point. Prends avec toi tout le peuple de guerre, et lève-toi, monte à Aï. Vois, j’ai livré en ta main le roi d’Aï, et son peuple, et sa ville, et son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Et tu feras à Aï et à son roi comme tu as fait à Jéricho et à son roi; seulement, vous pillerez pour vous le butin et les bêtes. Dresse une embuscade contre la ville, derrière elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Et Josué se leva avec tout le peuple de guerre pour monter vers Aï; et Josué choisit 30 000 vaillants hommes, et les envoya de nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Et il leur commanda, disant: Voyez, vous serez en embuscade contre la ville, derrière la ville; ne vous éloignez pas beaucoup de la ville, mais soyez tous prêts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Et moi et tout le peuple qui est avec moi, nous nous approcherons de la ville; et il arrivera que, lorsqu’ils sortiront à notre rencontre comme la première fois, nous fuirons devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Et ils sortiront après nous, jusqu’à ce que nous les ayons attirés loin de la ville; car ils diront: Ils fuient devant nous comme la première fois; et nous fuirons devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Et vous, vous vous lèverez de l’embuscade, et vous prendrez possession de la ville, et l’ Éternel, votre Dieu, la livrera en vos mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Et lorsque vous aurez pris la ville, vous incendierez la ville; vous ferez selon la parole de l’ Éternel. Voyez, je vous l’ai commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, '– Et Josué les envoya; et ils allèrent se mettre en embuscade, et se tinrent entre Béthel et Aï, à l’occident d’Aï; et Josué passa cette nuit au milieu du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Et Josué se leva de bonne heure le matin, et inspecta le peuple; et il monta, lui et les anciens d’Israël, devant le peuple, vers Aï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'et tout le peuple de guerre qui était avec lui monta et s’approcha; et ils vinrent devant la ville et campèrent au nord d’Aï; et la vallée était entre lui et Aï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Or il avait pris environ 5 000 hommes, et les avait placés en embuscade entre Béthel et Aï, à l’occident de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Et après qu’on eut placé le peuple, tout le camp qui était au nord de la ville et son embuscade à l’occident de la ville, alors Josué s’avança cette nuit-là au milieu de la vallée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Et il arriva que, lorsque le roi d’Aï vit cela, les hommes de la ville se hâtèrent et se levèrent de bonne heure, et sortirent, lui et tout son peuple, à la rencontre d’Israël, pour livrer bataille, au lieu assigné, devant la plaine. Or il ne savait pas qu’il y avait une embuscade contre lui, derrière la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Et Josué et tout Israël se laissèrent battre devant eux, et s’enfuirent par le chemin du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Et tout le peuple qui était dans la ville fut assemblé à grands cris pour les poursuivre; et ils poursuivirent Josué, et furent attirés loin de la ville;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'et il ne resta pas un homme dans Aï et dans Béthel, qui ne sorte après Israël; et ils laissèrent la ville ouverte, et poursuivirent Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Et l’ Éternel dit à Josué: Étends vers Aï le javelot qui est dans ta main, car je la livrerai entre tes mains. Et Josué étendit vers la ville le javelot qui était dans sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Et l’embuscade se leva en hâte de son lieu, et ils coururent comme il étendait sa main, et ils entrèrent dans la ville et la prirent, et se hâtèrent de mettre le feu à la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Et les hommes d’Aï se retournèrent, et virent: et voici, la fumée de la ville montait vers les cieux; et il n’y eut en eux aucune force pour fuir ni d’un côté ni de l’autre. Et le peuple qui fuyait vers le désert se tourna contre ceux qui le poursuivaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Et Josué et tout Israël, voyant que l’embuscade avait pris la ville et que la fumée de la ville montait, se retournèrent et frappèrent les hommes d’Aï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'et les autres sortirent de la ville à leur rencontre. Alors ils se trouvèrent au milieu d’Israël, les uns deçà, et les autres delà; et [les Israélites] les frappèrent jusqu’à ne leur laisser ni reste ni réchappé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Et ils prirent vivant le roi d’Aï, et l’amenèrent à Josué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Et il arriva que, lorsque Israël eut achevé de tuer tous les habitants d’Aï dans la campagne, dans le désert où ils les avaient poursuivis, et que tous furent tombés sous le tranchant de l’épée, jusqu’à être consumés, alors tout Israël revint vers Aï, et ils la frappèrent par le tranchant de l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Et tous ceux qui tombèrent ce jour-là, hommes ou femmes, furent 12 000, tous les gens d’Aï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Et Josué ne retira point sa main qu’il avait étendue avec le javelot, jusqu’à ce qu’on ait entièrement détruit tous les habitants d’Aï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Seulement, Israël pilla pour lui les bêtes et le butin de cette ville-là, selon la parole que l’ Éternel avait commandée à Josué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Et Josué brûla Aï, et en fit pour toujours un monceau de ruines, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Et il pendit le roi d’Aï à un arbre, jusqu’au temps du soir; et, comme le soleil se couchait, Josué commanda, et on descendit de l’arbre son cadavre, et on le jeta à l’entrée de la porte de la ville, et on éleva sur lui un grand monceau de pierres, [qui est demeuré] jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, '*Alors Josué bâtit un autel à l’ Éternel, le Dieu d’Israël, sur la montagne d’Ébal,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'comme Moïse, serviteur de l’ Éternel, l’avait commandé aux fils d’Israël, ainsi qu’il est écrit dans le livre de la loi de Moïse, un autel de pierres entières, sur lesquelles le fer n’avait pas été levé; et ils offrirent dessus des holocaustes à l’ Éternel, et sacrifièrent des sacrifices de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Et il écrivit là, sur les pierres, une copie de la loi de Moïse, qu’il avait écrite devant les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Et tout Israël, et ses anciens, et ses magistrats, et ses juges, se tenaient des deux côtés de l’arche, devant les sacrificateurs, les Lévites, qui portaient l’arche de l’alliance de l’ Éternel, aussi bien l’étranger que l’Israélite de naissance, une moitié vis-à-vis de la montagne de Garizim, et l’autre moitié vis-à-vis de la montagne d’Ébal, comme Moïse, serviteur de l’ Éternel, avait commandé de bénir le peuple d’Israël, au commencement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Et après cela il lut toutes les paroles de la loi, la bénédiction et la malédiction, selon tout ce qui est écrit dans le livre de la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Il n’y eut pas une parole de tout ce que Moïse avait commandé, que Josué ne lise devant toute la congrégation d’Israël, et les femmes, et les enfants, et l’étranger marchant au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, '*Et il arriva que, lorsque tous les rois qui étaient en deçà du Jourdain, dans la montagne et dans le pays plat, et sur tout le rivage de la grande mer, jusque vers le Liban, le Héthien, et l’Amoréen, le Cananéen, le Phérézien, le Hévien, et le Jébusien, eurent entendu [ces choses],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'ils se réunirent ensemble pour faire la guerre à Josué et à Israël, d’un commun accord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Et les habitants de Gabaon entendirent ce que Josué avait fait à Jéricho et à Aï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'et ils usèrent de ruse, eux aussi; et ils se mirent en route, préparés comme pour un voyage, et prirent de vieux sacs sur leurs ânes, et de vieilles outres à vin crevassées et recousues,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'et de vieilles sandales rapiécées à leurs pieds, et de vieux habits sur eux; et tout le pain de leur provision était sec [et] s’était moisi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Et ils allèrent vers Josué, au camp de Guilgal, et ils lui dirent, et aux hommes d’Israël: Nous venons d’un pays éloigné; et maintenant, traitez alliance avec nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Et les hommes d’Israël dirent au Hévien: Peut-être que tu habites au milieu de nous; et comment traiterions -nous alliance avec toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Et ils dirent à Josué: Nous sommes tes serviteurs. Et Josué leur dit: Qui êtes-vous? et d’où venez-vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Et ils lui dirent: Tes serviteurs viennent d’un pays très éloigné, au nom de l’ Éternel, ton Dieu; car nous avons entendu sa renommée, et tout ce qu’il a fait en Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'et tout ce qu’il a fait aux deux rois des Amoréens qui étaient au-delà du Jourdain, à Sihon, roi de Hesbon, et à Og, roi de Basan, qui était à Ashtaroth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Et nos anciens et tous les habitants de notre pays nous ont parlé, disant: Prenez avec vous des provisions pour la route, et allez au-devant d’eux, et dites-leur: Nous sommes vos serviteurs, et maintenant traitez alliance avec nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'C’est ici notre pain; nous l’avons pris chaud de nos maisons pour notre provision, le jour où nous sommes partis pour venir vers vous; et maintenant, voici, il est sec et s’est moisi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Et ce sont ici les outres à vin que nous avions remplies neuves; et voici, elles se sont crevassées; et ce sont ici nos habits et nos sandales qui sont vieillis à cause de la grande longueur de la route.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Et les hommes [d’Israël] prirent de leurs provisions; et on n’interrogea point la bouche de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Et Josué fit la paix avec eux, et traita alliance avec eux, pour les laisser vivre; et les princes de l’assemblée s’obligèrent envers eux par serment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Et il arriva qu’au bout de trois jours, après avoir traité alliance avec eux, ils entendirent qu’ils étaient leurs voisins, et qu’ils habitaient au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Et les fils d’Israël partirent, et vinrent à leurs villes, le troisième jour. Et leurs villes étaient Gabaon, et Kephira, et Beéroth, et Kiriath-Jéarim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Et les fils d’Israël ne les frappèrent point, car les princes de l’assemblée s’étaient obligés envers eux par serment au nom de l’ Éternel, le Dieu d’Israël; et toute l’assemblée murmura contre les princes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Et tous les princes dirent à toute l’assemblée: Nous nous sommes obligés envers eux par serment au nom de l’ Éternel, le Dieu d’Israël; et maintenant, nous ne pouvons pas les toucher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Faisons-leur ceci, et laissons-les vivre, et il n’y aura point de colère sur nous à cause de notre serment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Et les princes leur dirent: Qu’ils vivent. Et ils furent coupeurs de bois et puiseurs d’eau pour toute l’assemblée, comme les princes avaient dit à leur égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Et Josué les appela, et leur parla, disant: Pourquoi nous avez-vous trompés, en disant: Nous sommes très éloignés de vous, tandis que vous habitez au milieu de nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Or maintenant, vous êtes maudits, et vous ne cesserez jamais d’être serviteurs, coupeurs de bois et puiseurs d’eau pour la maison de mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Et ils répondirent à Josué, et dirent: Parce qu’il a été clairement déclaré à tes serviteurs, que l’ Éternel, ton Dieu, avait commandé à Moïse, son serviteur, de vous donner tout le pays et d’exterminer tous les habitants du pays devant vous; et nous avons beaucoup craint pour nos vies à cause de vous, et nous avons fait cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Et maintenant nous voici en ta main; fais comme il est bon et droit à tes yeux de nous faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Et il leur fit ainsi, et les sauva de la main des fils d’Israël; et ils ne les tuèrent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Et en ce jour-là Josué les établit coupeurs de bois et puiseurs d’eau pour l’assemblée et pour l’autel de l’ Éternel, jusqu’à ce jour, dans le lieu qu’il choisirait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Et il arriva que, lorsque Adoni-Tsédek, roi de Jérusalem, eut entendu que Josué avait pris Aï et l’avait entièrement détruite, qu’il avait fait à Aï et à son roi comme il avait fait à Jéricho et à son roi, et que les habitants de Gabaon avaient fait la paix avec Israël et étaient au milieu d’eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'ils eurent une grande peur; car Gabaon était une grande ville, comme une des villes royales, et elle était plus grande qu’Aï, et tous ses hommes étaient vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Et Adoni-Tsédek, roi de Jérusalem, envoya vers Hoham, roi de Hébron, et vers Piream, roi de Jarmuth, et vers Japhia, roi de Lakis, et vers Debir, roi d’Églon, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Montez vers moi, et aidez-moi, et frappons Gabaon; car elle a fait la paix avec Josué et avec les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Et les cinq rois des Amoréens, le roi de Jérusalem, le roi de Hébron, le roi de Jarmuth, le roi de Lakis, le roi d’Églon, s’assemblèrent et montèrent, eux et toutes leurs armées, et ils campèrent contre Gabaon, et lui firent la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Et les hommes de Gabaon envoyèrent à Josué, au camp, à Guilgal, disant: Ne retire pas tes mains de tes serviteurs; monte vers nous en hâte, et sauve-nous et aide-nous; car tous les rois des Amoréens qui habitent dans la montagne se sont réunis contre nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Et Josué monta de Guilgal, lui et tout le peuple de guerre avec lui, tous les vaillants hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Et l’ Éternel dit à Josué: Ne les crains pas, car je les ai livrés en ta main; pas un d’entre eux ne tiendra devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Et Josué arriva sur eux tout à coup; il monta de Guilgal toute la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Et l’ Éternel les mit en déroute devant Israël, qui leur infligea une grande défaite près de Gabaon, et les poursuivit par le chemin de la montée de Beth-Horon, et les battit jusqu’à Azéka et jusqu’à Makkéda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Et il arriva que, comme ils fuyaient devant Israël – ils étaient à la descente de Beth-Horon, – l’ Éternel jeta des cieux de grosses pierres sur eux, jusqu’à Azéka, et ils moururent; ceux qui moururent des pierres de grêle furent plus nombreux que ceux que les fils d’Israël tuèrent par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Alors Josué parla à l’ Éternel, le jour où l’ Éternel livra les Amoréens entre les mains des fils d’Israël; et il dit en présence d’Israël: Soleil, arrête-toi sur Gabaon; et toi, lune, en la vallée d’Ajalon!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Et le soleil s’arrêta, et la lune demeura où elle était, jusqu’à ce que la nation se soit vengée de ses ennemis. Cela n’est-il pas écrit dans le livre de Jashar? Et le soleil demeura au milieu des cieux, et ne se hâta point de se coucher, environ un jour entier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Et il n’y a point eu de jour comme celui-là, ni avant ni après, où l’ Éternel ait écouté la voix d’un homme, car l’ Éternel combattait pour Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Et Josué, et tout Israël avec lui, retourna au camp, à Guilgal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Et ces cinq rois s’enfuirent et se cachèrent dans la caverne, à Makkéda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Et on rapporta à Josué, en disant: Les cinq rois ont été trouvés cachés dans la caverne, à Makkéda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Et Josué dit: Roulez de grandes pierres à l’ouverture de la caverne, et postez près d’elle des hommes pour les garder;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'et vous, ne vous arrêtez pas; poursuivez vos ennemis, et frappez-les en queue; ne les laissez pas entrer dans leurs villes; car l’ Éternel, votre Dieu, les a livrés en votre main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Et quand Josué et les fils d’Israël eurent achevé de leur infliger une très grande défaite, jusqu’à les détruire, il arriva que les fuyards d’entre eux échappèrent et entrèrent dans les villes fortifiées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'et tout le peuple retourna en paix au camp, vers Josué, à Makkéda; personne ne remua sa langue contre les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Et Josué dit: Ouvrez l’entrée de la caverne, et amenez-moi ces cinq rois hors de la caverne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Et ils firent ainsi, et ils lui amenèrent hors de la caverne ces cinq rois: le roi de Jérusalem, le roi de Hébron, le roi de Jarmuth, le roi de Lakis, le roi d’Églon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Et lorsqu’ils eurent amené ces rois à Josué, il arriva que Josué appela tous les hommes d’Israël, et dit aux capitaines des hommes de guerre qui avaient marché avec lui: Approchez-vous, mettez vos pieds sur les cous de ces rois. Et ils s’approchèrent, et mirent leurs pieds sur leurs cous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Et Josué leur dit: Ne craignez point, et ne soyez pas effrayés; fortifiez-vous, et soyez fermes; car l’ Éternel fera ainsi à tous vos ennemis contre lesquels vous combattez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Et après cela Josué les frappa et les fit mourir, et il les pendit à cinq arbres; et ils pendirent aux arbres jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Et au temps du coucher du soleil, il arriva que Josué commanda, et on les descendit des arbres, et on les jeta dans la caverne où ils s’étaient cachés; et on mit à l’ouverture de la caverne de grandes pierres, [qui sont demeurées] jusqu’à ce jour même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Et Josué prit en ce jour-là Makkéda, et la frappa par le tranchant de l’épée; et son roi, lui, et toute âme qui s’y trouvait, il les détruisit entièrement: il ne laissa pas un réchappé; et il fit au roi de Makkéda comme il avait fait au roi de Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Et Josué, et tout Israël avec lui, passa de Makkéda à Libna, et fit la guerre à Libna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Et l’ Éternel la livra, elle aussi et son roi, en la main d’Israël; et il la frappa par le tranchant de l’épée, ainsi que toute âme qui s’y trouvait; il n’y laissa pas un réchappé; et il fit à son roi comme il avait fait au roi de Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Et Josué, et tout Israël avec lui, passa de Libna à Lakis, et campa contre elle, et lui fit la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Et l’ Éternel livra Lakis en la main d’Israël, et il la prit le second jour et la frappa par le tranchant de l’épée, ainsi que toute âme qui s’y trouvait, selon tout ce qu’il avait fait à Libna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Alors Horam, roi de Guézer, monta pour secourir Lakis; et Josué le frappa, lui et son peuple, jusqu’à ne pas lui laisser un réchappé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Et Josué, et tout Israël avec lui, passa de Lakis à Églon, et ils campèrent contre elle, et lui firent la guerre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'et ils la prirent ce jour-là, et la frappèrent par le tranchant de l’épée; et il détruisit entièrement ce jour-là toute âme qui s’y trouvait, selon tout ce qu’il avait fait à Lakis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Et Josué, et tout Israël avec lui, monta d’Églon à Hébron, et ils lui firent la guerre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'et ils la prirent, et la frappèrent par le tranchant de l’épée, et son roi, et toutes ses villes, et toute âme qui s’y trouvait: il ne laissa pas un réchappé, selon tout ce qu’il avait fait à Églon; il la détruisit entièrement, ainsi que toute âme qui s’y trouvait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Et Josué, et tout Israël avec lui, rebroussa chemin vers Debir, et ils lui firent la guerre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'et il la prit, et son roi, et toutes ses villes; et ils les frappèrent par le tranchant de l’épée, et détruisirent entièrement toute âme qui s’y trouvait: il ne laissa pas un réchappé. Comme il avait fait à Hébron, et comme il avait fait à Libna et à son roi, ainsi il fit à Debir et à son roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Et Josué frappa tout le pays, la montagne, et le midi, et le pays plat, et les pentes des montagnes, et tous leurs rois: il ne laissa pas un réchappé; mais il détruisit entièrement tout ce qui respirait, comme l’ Éternel, le Dieu d’Israël, l’avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Et Josué les frappa depuis Kadès-Barnéa jusqu’à Gaza, et tout le pays de Goshen, jusqu’à Gabaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Et Josué prit en une seule fois tous ces rois et leur pays; car l’ Éternel, le Dieu d’Israël, combattait pour Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Et Josué, et tout Israël avec lui, retourna au camp, à Guilgal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, '*Et il arriva que, lorsque Jabin, roi de Hatsor, entendit [ces choses], il envoya vers Jobab, roi de Madon, et vers le roi de Shimron, et vers le roi d’Acshaph,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'et vers les rois qui étaient au nord, dans la montagne, et dans la plaine au midi de Kinnéreth, et dans le pays plat, et sur les hauteurs de Dor à l’occident,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'vers le Cananéen à l’orient et à l’occident, et vers l’Amoréen, et vers le Héthien, et vers le Phérézien, et vers le Jébusien, dans la montagne, et vers le Hévien au pied de l’Hermon, dans le pays de Mitspé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Et ils sortirent, eux et toutes leurs armées avec eux, un peuple nombreux, en multitude comme le sable qui est sur le bord de la mer, avec des chevaux et des chars en très grand nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Et tous ces rois-là se donnèrent rendez-vous, et vinrent et campèrent ensemble vers les eaux de Mérom pour faire la guerre contre Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Et l’ Éternel dit à Josué: Ne les crains point, car demain, environ en ce temps-ci, je les livrerai tous tués devant Israël; tu couperas les jarrets à leurs chevaux et tu brûleras au feu leurs chars.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Et Josué, et tout le peuple de guerre avec lui, vint contre eux à l’improviste près des eaux de Mérom; et ils tombèrent sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Et l’ Éternel les livra en la main d’Israël; et ils les frappèrent, et les poursuivirent jusqu’à Sidon la grande, et jusqu’à Misrephoth-Maïm, et jusqu’à la vallée de Mitspé, vers le levant; et ils les frappèrent jusqu’à ne pas leur laisser un réchappé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Et Josué leur fit comme l’ Éternel lui avait dit: il coupa les jarrets à leurs chevaux, et brûla au feu leurs chars.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Et en ce temps-là Josué rebroussa chemin, et prit Hatsor, et frappa son roi avec l’épée; car Hatsor était auparavant la capitale de tous ces royaumes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Et ils frappèrent par le tranchant de l’épée toutes les âmes qui s’y trouvaient, les détruisant entièrement: il n’y resta rien de ce qui respirait; et il brûla Hatsor par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Et Josué prit toutes les villes de ces rois et tous leurs rois, et les frappa par le tranchant de l’épée; il les détruisit entièrement, comme Moïse, serviteur de l’ Éternel, l’avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Seulement, Israël ne brûla aucune des villes qui étaient demeurées tranquilles sur leurs collines, excepté Hatsor seule, que Josué brûla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Et les fils d’Israël pillèrent pour eux tout le butin de ces villes et les bêtes; seulement ils frappèrent par le tranchant de l’épée tous les hommes, jusqu’à ce qu’ils les aient détruits: ils n’y laissèrent rien de ce qui respirait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Comme l’ Éternel l’avait commandé à Moïse, son serviteur, ainsi Moïse commanda à Josué, et ainsi fit Josué; il n’omit rien de tout ce que l’ Éternel avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Et Josué prit tout ce pays, la montagne et tout le midi, et tout le pays de Goshen, et le pays plat, et la plaine, et la montagne d’Israël, et son pays plat,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'depuis la montagne de Halak qui s’élève vers Séhir, jusqu’à Baal-Gad dans la vallée du Liban, au pied de la montagne de l’Hermon; et il prit tous leurs rois, et les frappa et les fit mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Josué fit longtemps la guerre à tous ces rois-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Il n’y eut aucune ville qui fasse la paix avec les fils d’Israël, excepté les Héviens qui habitaient Gabaon; ils les prirent toutes par la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Car ce fut de par l’ Éternel que leur cœur fut endurci pour s’en aller en guerre contre Israël, afin qu’il les détruise entièrement sans qu’il y ait pour eux de merci; car c’était afin de les détruire, comme l’ Éternel l’avait commandé à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Et Josué vint en ce temps-là et retrancha les Anakim de la montagne, de Hébron, de Debir, d’Anab, et de toute la montagne de Juda, et de toute la montagne d’Israël: Josué les détruisit entièrement avec leurs villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Il ne resta point d’Anakim dans le pays des fils d’Israël; il en demeura seulement dans Gaza, dans Gath, et dans Asdod.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Et Josué prit tout le pays, selon tout ce que l’ Éternel avait dit à Moïse; et Josué le donna en héritage à Israël, selon leurs distributions, selon leurs tribus. Et le pays se reposa de la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, '*Et ce sont ici les rois du pays, que les fils d’Israël frappèrent et dont ils possédèrent le pays, de l’autre côté du Jourdain, vers le soleil levant, depuis le torrent de l’Arnon jusqu’à la montagne de l’Hermon, et toute la plaine au levant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihon, roi des Amoréens, qui habitait à Hesbon, dominant depuis Aroër qui est sur le bord du torrent de l’Arnon et depuis le milieu du torrent, sur la moitié de Galaad, jusqu’au Jabbok, torrent qui est la frontière des fils d’Ammon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'et [sur] la plaine, jusqu’à la mer de Kinnéreth, vers le levant, et jusqu’à la mer de la plaine, la mer Salée, au levant, du côté de Beth-Jeshimoth, et au midi, sous les pentes du Pisga;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'et le territoire d’Og, roi de Basan, du reste des Rephaïm, qui habitait à Ashtaroth et à Édréhi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'et il dominait sur la montagne de l’Hermon, et sur Salca, et sur tout Basan, jusqu’à la frontière des Gueshuriens et des Maacathiens, et [sur] la moitié de Galaad, [jusqu’à la] frontière de Sihon, roi de Hesbon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Moïse, serviteur de l’ Éternel, et les fils d’Israël, les frappèrent; et Moïse, serviteur de l’ Éternel, en donna la possession aux Rubénites, et aux Gadites, et à la demi-tribu de Manassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Et ce sont ici les rois du pays, que Josué et les fils d’Israël frappèrent en deçà du Jourdain, vers l’occident, depuis Baal-Gad, dans la vallée du Liban, jusqu’à la montagne de Halak qui s’élève vers Séhir; et Josué en donna la possession aux tribus d’Israël, selon leurs distributions,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'dans la montagne, et dans le pays plat, et dans la plaine, et sur les pentes des montagnes, et dans le désert, et dans le midi: le Héthien, l’Amoréen, et le Cananéen, le Phérézien, le Hévien, et le Jébusien: –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'le roi de Jéricho, un; le roi d’Aï, qui est à côté de Béthel, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'le roi de Jérusalem, un; le roi de Hébron, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'le roi de Jarmuth, un; le roi de Lakis, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'le roi d’Églon, un; le roi de Guézer, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'le roi de Debir, un; le roi de Guéder, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'le roi de Horma, un; le roi d’Arad, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'le roi de Libna, un; le roi d’Adullam, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'le roi de Makkéda, un; le roi de Béthel, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'le roi de Tappuakh, un; le roi de Hépher, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'le roi d’Aphek, un; le roi de Lassaron, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'le roi de Madon, un; le roi de Hatsor, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'le roi de Shimron-Meron, un; le roi d’Acshaph, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'le roi de Thaanac, un; le roi de Meguiddo, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'le roi de Kédesh, un; le roi de Jokneam, au Carmel, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'le roi de Dor, des hauteurs de Dor, un; le roi de Goïm, à Guilgal, un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'le roi de Thirtsa, un; tous les rois étaient 31.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, '*Et Josué était vieux, avancé en âge, et l’ Éternel lui dit: Tu es devenu vieux, tu avances en âge, et il reste un très grand pays à posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'C’est ici le pays qui reste: tous les districts des Philistins et tous les Gueshuriens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'depuis le Shikhor qui est devant l’Égypte, jusqu’à la frontière d’Ékron, vers le nord; il est réputé appartenir aux Cananéens: cinq princes des Philistins, celui de Gaza, et celui d’Asdod, celui d’Askalon, celui de Gath, et celui d’Ékron, et les Avviens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'au sud, tout le pays des Cananéens, et Méara, qui est aux Sidoniens, jusqu’à Aphek, jusqu’à la frontière de l’Amoréen;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'et le pays des Guibliens, et tout le Liban, vers le soleil levant, depuis Baal-Gad, au pied de la montagne de l’Hermon, jusqu’à l’entrée de Hamath;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'tous les habitants de la montagne, depuis le Liban jusqu’à Misrephoth-Maïm, tous les Sidoniens. Moi, je les déposséderai devant les fils d’Israël. Seulement, répartis par le sort [ce pays] en héritage à Israël, comme je te l’ai commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Et maintenant, distribue ce pays en héritage aux neuf tribus, et à la demi-tribu de Manassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Avec l’autre moitié de Manassé, les Rubénites et les Gadites ont reçu leur héritage, que Moïse leur a donné au-delà du Jourdain, vers le levant, selon ce que Moïse, serviteur de l’ Éternel, leur a donné,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'depuis Aroër, qui est sur le bord du torrent de l’Arnon, et la ville qui est au milieu du torrent, et tout le plateau de Médeba, jusqu’à Dibon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'et toutes les villes de Sihon, roi des Amoréens, qui régnait à Hesbon, jusqu’à la frontière des fils d’Ammon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'et Galaad, et les confins des Gueshuriens et des Maacathiens, et toute la montagne de l’Hermon; et tout Basan, jusqu’à Salca,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'tout le royaume d’Og, en Basan, qui régnait à Ashtaroth et à Édréhi; (il était demeuré du reste des Rephaïm); et Moïse les frappa et les déposséda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, '– Mais les fils d’Israël ne dépossédèrent pas les Gueshuriens et les Maacathiens; et Gueshur et Maaca habitent au milieu d’Israël jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'À la tribu de Lévi seule il ne donna point d’héritage; les sacrifices de l’ Éternel, le Dieu d’Israël, faits par feu, c’est là son héritage, comme il le lui avait dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Et Moïse donna [une part] à la tribu des fils de Ruben, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Et leur territoire était depuis Aroër, qui est sur le bord du torrent de l’Arnon, et la ville qui est au milieu du torrent, et tout le plateau près de Médeba;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon et toutes ses villes, qui étaient sur le plateau: Dibon, et Bamoth-Baal, et Beth-Baal-Méon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'et Jahtsa, et Kedémoth, et Méphaath,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'et Kiriathaïm, et Sibma, et Tséreth-Shakhar dans la montagne de la vallée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'et Beth-Péor, et les pentes du Pisga, et Beth-Jeshimoth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'toutes les villes du plateau et tout le royaume de Sihon, roi des Amoréens, qui régnait à Hesbon, que Moïse frappa, lui et les princes de Madian: Évi, et Rékem, et Tsur, et Hur, et Réba, seigneurs de Sihon, habitants du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Et les fils d’Israël tuèrent par l’épée Balaam, fils de Béor, le devin, avec les autres qui furent tués.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Et la frontière des fils de Ruben fut le Jourdain et [sa] rive. Ce fut là l’héritage des fils de Ruben, selon leurs familles: les villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Et Moïse donna [une part] à la tribu de Gad, aux fils de Gad, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Et leur territoire était Jahzer, et toutes les villes de Galaad, et la moitié du pays des fils d’Ammon, jusqu’à Aroër, qui est vis-à-vis de Rabba;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'et depuis Hesbon jusqu’à Ramath-Mitspé et Betonim, et depuis Mahanaïm jusqu’à la frontière de Debir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'et, dans la vallée, Beth-Haram, et Beth-Nimra, et Succoth, et Tsaphon, le reste du royaume de Sihon, roi de Hesbon, le Jourdain et [sa] rive, jusqu’au bout de la mer de Kinnéreth, au-delà du Jourdain, vers le levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Ce fut là l’héritage des fils de Gad, selon leurs familles: les villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Et Moïse donna [une part] à la demi-tribu de Manassé; et pour la demi-tribu des fils de Manassé, selon leurs familles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'leur territoire était depuis Mahanaïm: tout Basan, tout le royaume d’Og, roi de Basan, et tous les bourgs de Jaïr, qui sont en Basan, 60 villes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'et la moitié de Galaad, et Ashtaroth, et Édréhi, villes du royaume d’Og, en Basan, furent aux fils de Makir, fils de Manassé, à la moitié des fils de Makir, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'C’est là ce que Moïse distribua en héritage dans les plaines de Moab, au-delà du Jourdain de Jéricho, vers le levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Mais Moïse ne donna point d’héritage à la tribu de Lévi; l’ Éternel, le Dieu d’Israël, était leur héritage, comme il le leur avait dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, '*Et c’est ici ce que les fils d’Israël ont reçu en héritage dans le pays de Canaan, ce qu’Éléazar, le sacrificateur, et Josué, fils de Nun, et les chefs des pères des tribus des fils d’Israël, leur distribuèrent en héritage:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'leur héritage fut [distribué] par le sort, comme l’ Éternel l’avait commandé par Moïse, aux neuf tribus et à la demi-tribu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Car Moïse avait donné un héritage à deux tribus et à une demi-tribu, de l’autre côté du Jourdain; mais il n’avait pas donné d’héritage parmi eux aux Lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Car les fils de Joseph étaient deux tribus: Manassé et Éphraïm; et on ne donna point de part aux Lévites dans le pays, excepté les villes d’habitation, et leurs banlieues pour leurs troupeaux et pour leurs biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Les fils d’Israël firent comme l’ Éternel l’avait commandé à Moïse, et ils partagèrent le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Et les fils de Juda s’approchèrent de Josué, à Guilgal; et Caleb, fils de Jephunné, le Kenizien, lui dit: Tu sais la parole que l’ Éternel a dite, à mon sujet et à ton sujet, à Moïse, homme de Dieu, à Kadès-Barnéa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'J’étais âgé de 40 ans quand Moïse, serviteur de l’ Éternel, m’envoya de Kadès-Barnéa pour explorer le pays, et je lui rapportai la chose comme elle était dans mon cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Et mes frères qui étaient montés avec moi faisaient fondre le cœur du peuple; mais moi, je suivis pleinement l’ Éternel, mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Et Moïse jura en ce jour-là, disant: Si le pays que ton pied a foulé n’est à toi pour héritage, et à tes fils, pour toujours! car tu as pleinement suivi l’ Éternel, mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Et maintenant, voici, comme il l’a dit, l’ Éternel m’a conservé en vie ces 45 ans, depuis que l’ Éternel a dit cette parole à Moïse, lorsque Israël marchait dans le désert; et maintenant, voici, moi je suis aujourd’hui âgé de 85 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Je suis encore aujourd’hui fort comme le jour où Moïse m’envoya; telle que ma force était alors, telle ma force est maintenant, pour la guerre, et pour sortir et entrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Et maintenant, donne-moi cette montagne dont l’ Éternel a parlé en ce jour-là; car tu as entendu, en ce jour-là, que les Anakim y sont, et de grandes villes fortes; peut-être que l’ Éternel sera avec moi, et je les déposséderai, comme l’ Éternel a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Et Josué le bénit, et donna Hébron en héritage à Caleb, fils de Jephunné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'C’est pourquoi Hébron appartient en héritage, jusqu’à ce jour, à Caleb, fils de Jephunné, le Kenizien, parce qu’il avait pleinement suivi l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Or le nom de Hébron était auparavant Kiriath-Arba; [Arba] était le grand homme parmi les Anakim. Et le pays se reposa de la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Et le lot échu à la tribu des fils de Juda, selon leurs familles, fut jusqu’à la frontière d’Édom, le désert de Tsin, vers le midi, à l’extrémité sud.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Et leur frontière méridionale était depuis le bout de la mer Salée, depuis la pointe qui regarde vers le midi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'et elle sortait vers le midi de la montée d’Akrabbim, et passait vers Tsin, et montait au midi de Kadès-Barnéa, et passait à Hetsron, et montait vers Addar, et tournait vers Karkaa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'et passait vers Atsmon, et sortait au torrent d’Égypte; et la frontière aboutissait à la mer. Telle sera votre frontière au midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, '– Et la frontière orientale était la mer Salée jusqu’à l’extrémité du Jourdain. – Et la frontière, du côté du nord, était depuis la pointe de la mer qui est à l’extrémité du Jourdain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'et la frontière montait vers Beth-Hogla, et passait vers le nord de Beth-Araba; et la frontière montait vers la pierre de Bohan, fils de Ruben;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'et la frontière montait vers Debir, depuis la vallée d’Acor, et tournait contre le nord vers Guilgal, qui est vis-à-vis de la montée d’Adummim, laquelle est au midi du torrent; et la frontière passait vers les eaux d’En-Shémesh, et aboutissait à En-Roguel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'et la frontière montait la vallée de Ben-Hinnom, vers le côté méridional de Jébus, qui est Jérusalem; et la frontière montait au sommet de la montagne qui est en face de la vallée de Hinnom, à l’occident, qui est à l’extrémité de la vallée des Rephaïm, au nord;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'et la frontière fut tracée depuis le sommet de la montagne jusqu’à la source des eaux de Nephtoah, et elle sortait vers les villes de la montagne d’Éphron; et la frontière fut tracée par Baala, qui est Kiriath-Jéarim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'et la frontière faisait un détour depuis Baala, vers l’occident, jusqu’à la montagne de Séhir; et elle passait à côté de la montagne de Jéarim, qui est Kesalon, vers le nord; et elle descendait à Beth-Shémesh et passait par Thimna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Et la frontière sortait vers le côté d’Ékron, vers le nord; et la frontière fut tracée vers Shicron; et elle passait la montagne de Baala, et sortait vers Jabneël; et la frontière aboutissait à la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, '– Et la frontière occidentale était la grande mer et [ses] côtes. Telle fut la frontière des fils de Juda, tout à l’entour, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Et, selon le commandement de l’ Éternel à Josué, il donna à Caleb, fils de Jephunné, une part au milieu des fils de Juda: Kiriath-Arba ([Arba était] père d’Anak), c’est Hébron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Et Caleb en déposséda les trois fils d’Anak: Shéshaï, et Akhiman, et Thalmaï, enfants d’Anak.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Et de là, il monta contre les habitants de Debir; or le nom de Debir était auparavant Kiriath-Sépher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Et Caleb dit: À qui frappera Kiriath-Sépher et la prendra, je lui donnerai ma fille Acsa pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Et Othniel, fils de Kenaz, frère de Caleb, la prit; et [Caleb] lui donna sa fille Acsa pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, '– Et il arriva que, comme elle entrait, elle l’incita à demander à son père un champ. Et elle descendit de dessus l’âne; et Caleb lui dit: Qu’as-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Et elle dit: Donne-moi une bénédiction; car tu m’as donné une terre du midi, donne-moi aussi des sources d’eau. Et il lui donna les sources du haut et les sources du bas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'C’est ici l’héritage de la tribu des fils de Juda, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Les villes de l’extrémité de la tribu des fils de Juda, vers la frontière d’Édom, dans le midi, furent: Kabtseël, et Éder, et Jagur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'et Kina, et Dimona, et Adhada,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'et Kédesh, et Hatsor, et Jithnan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Ziph, et Télem, et Bealoth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'et Hatsor la neuve, et Kerijoth-Hetsron (c’est Hatsor),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, et Shema, et Molada,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'et Hatsar-Gadda, et Heshmon, et Beth-Péleth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'et Hatsar-Shual, et Beër-Shéba, et Biziothia;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, et Ijim, et Étsem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'et Eltholad, et Kesil, et Horma,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'et Tsiklag, et Madmanna, et Sansanna,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'et Lebaoth, et Shilkhim, et Aïn, et Rimmon: toutes ces villes, 29 [villes] et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, '– Dans le pays plat: Eshtaol, et Tsorha, et Ashna,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'et Zanoakh, et En-Gannim, Tappuakh et Énam,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmuth et Adullam, Soco et Azéka,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'et Shaaraïm, et Adithaïm, et Guedéra, et Guedérothaïm: 14 villes et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Tsenan, et Hadasha, et Migdal-Gad,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'et Dilhan, et Mitspé, et Joktheël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lakis, et Botskath, et Églon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'et Cabbon, et Lakhmas, et Kithlish,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'et Guedéroth, Beth-Dagon, et Naama, et Makkéda: 16 villes et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, et Éther, et Ashan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'et Jiphtah, et Ashna, et Netsib,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'et Kehila, et Aczib, et Marésha: neuf villes et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ékron, et les villages de son ressort, et ses hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'depuis Ékron, et vers la mer, toutes celles qui étaient à côté d’Asdod, et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod, les villages de son ressort, et ses hameaux; Gaza, les villages de son ressort, et ses hameaux, jusqu’au torrent d’Égypte, et la grande mer et [ses] côtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, '– Et dans la montagne: Shamir, et Jatthir, et Soco,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'et Danna, et Kiriath-Sanna, qui est Debir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'et Anab, et Eshtemo, et Anim,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'et Goshen, et Holon, et Guilo: onze villes et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, et Duma, et Éshean,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'et Janum, et Beth-Tappuakh, et Aphéka,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'et Humta, et Kiriath-Arba, qui est Hébron, et Tsihor: neuf villes et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Carmel, et Ziph, et Juta,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'et Jizreël, et Jokdeam, et Zanoakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kaïn, Guibha, et Thimna: dix villes et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halkhul, Beth-Tsur, et Guedor,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'et Maarath, et Beth-Anoth, et Elthekon: six villes et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kiriath-Baal, qui est Kiriath-Jéarim, et Rabba: deux villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, '– Dans le désert: Beth-Araba, Middin, et Secaca,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'et Nibshan, et Ir-Hammélakh, et En-Guédi: six villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Mais les Jébusiens qui habitaient Jérusalem, les fils de Juda ne purent pas les déposséder, et le Jébusien a habité avec les fils de Juda à Jérusalem jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Et le lot échut aux fils de Joseph depuis le Jourdain de Jéricho, jusqu’aux eaux de Jéricho, vers le levant, [vers] le désert qui monte de Jéricho à la montagne de Béthel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Et [la frontière] sortait de Béthel vers Luz, et passait vers la frontière de l’Arkite à Ataroth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'et elle descendait vers l’occident, à la frontière des Japhlétiens, jusqu’à la frontière de Beth-Horon la basse, et jusqu’à Guézer, et aboutissait à la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Et les fils de Joseph, Manassé et Éphraïm, eurent [cela pour] héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Et le territoire des fils d’Éphraïm fut selon leurs familles: la frontière de leur héritage vers le levant était Ataroth-Addar, jusqu’à Beth-Horon la haute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Et la frontière sortait à l’occident vers Micmethath, au nord; et la frontière tournait vers l’orient, jusqu’à Thaanath-Silo, et la dépassait vers l’orient, vers Janokha,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'et descendait de Janokha à Ataroth et à Naaratha, et touchait à Jéricho, et aboutissait au Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Depuis Tappuakh la frontière allait vers l’occident, au torrent de Kana, et aboutissait à la mer. Ce fut là l’héritage de la tribu des fils d’Éphraïm, selon leurs familles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'avec les villes qui furent séparées pour les fils d’Éphraïm, au milieu de l’héritage des fils de Manassé, toutes ces villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Mais ils ne dépossédèrent pas le Cananéen qui habitait à Guézer; et le Cananéen a habité au milieu d’Éphraïm jusqu’à ce jour; et il a été asservi au tribut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Et le lot échut à la tribu de Manassé (or il était le premier-né de Joseph), à Makir, premier-né de Manassé, père de Galaad; comme il était un homme de guerre, Galaad et Basan furent à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Et [le lot] échut aux autres fils de Manassé, selon leurs familles, aux fils d’Abiézer, et aux fils de Hélek, et aux fils d’Asriel, et aux fils de Sichem, et aux fils de Hépher, et aux fils de Shemida. Ce sont là les fils de Manassé, fils de Joseph, les mâles, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Et Tselophkhad, fils de Hépher, fils de Galaad, fils de Makir, fils de Manassé, n’eut point de fils, mais seulement des filles; et ce sont ici les noms de ses filles: Makhla, et Noa, Hogla, Milca, et Thirtsa;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'et elles se présentèrent devant Éléazar, le sacrificateur, et devant Josué, fils de Nun, et devant les princes, disant: L’ Éternel a commandé à Moïse de nous donner un héritage au milieu de nos frères. Et [Josué] leur donna, selon le commandement de l’ Éternel, un héritage au milieu des frères de leur père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Et il échut dix parts à Manassé, outre le pays de Galaad et de Basan, qui est au-delà du Jourdain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'car les filles de Manassé reçurent un héritage au milieu de ses fils; et le pays de Galaad fut pour les autres fils de Manassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Et le territoire de Manassé allait d’Aser à Micmethath, qui est devant Sichem; et la frontière allait à droite vers les habitants d’En-Tappuakh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'La campagne de Tappuakh était à Manassé; mais Tappuakh, sur la frontière de Manassé, était aux fils d’Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Et la frontière descendait au torrent de Kana, au midi du torrent. Ces villes-là étaient à Éphraïm, au milieu des villes de Manassé. Et le territoire de Manassé était au nord du torrent, et aboutissait à la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Le midi était à Éphraïm, et le nord à Manassé, et la mer était sa frontière; et au nord, ils touchaient à Aser, et à l’orient, à Issacar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Et Manassé avait, dans Issacar et dans Aser, Beth-Shean et les villages de son ressort, et Jibleam et les villages de son ressort, et les habitants de Dor et les villages de son ressort, et les habitants d’En-Dor et les villages de son ressort, et les habitants de Thaanac et les villages de son ressort, et les habitants de Meguiddo et les villages de son ressort: les trois districts montueux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Mais les fils de Manassé ne purent pas déposséder [les habitants de] ces villes-là, et le Cananéen voulut habiter dans ce pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Et il arriva que, quand les fils d’Israël furent devenus forts, ils rendirent le Cananéen tributaire; mais ils ne le dépossédèrent pas entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Et les fils de Joseph parlèrent à Josué, disant: Pourquoi m’as-tu donné en héritage un seul lot et une seule part, à moi qui suis un peuple nombreux, selon que l’ Éternel m’a béni jusqu’à présent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Et Josué leur dit: Si tu es un peuple nombreux, monte à la forêt, et coupe-la pour t’y [faire de la place] dans le pays des Phéréziens et des Rephaïm, si la montagne d’Éphraïm est trop étroite pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Et les fils de Joseph dirent: Nous ne pouvons pas acquérir la montagne, et il y a des chars de fer chez tous les Cananéens qui habitent le pays de la vallée, chez ceux de Beth-Shean et des villages de son ressort, et chez ceux de la vallée de Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Et Josué parla à la maison de Joseph, à Éphraïm et à Manassé, disant: Tu es un peuple nombreux, et tu as une grande puissance; tu n’auras pas un seul lot,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'mais la montagne sera à toi; comme c’est une forêt, tu la couperas, et elle sera à toi jusqu’à ses extrémités; car tu déposséderas le Cananéen, quoiqu’il ait des chars de fer [et] qu’il soit fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, '*Et toute l’assemblée des fils d’Israël se réunit à Silo, et ils y dressèrent la tente d’assignation; et le pays leur fut assujetti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Et il restait parmi les fils d’Israël sept tribus auxquelles on n’avait pas encore distribué leur héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Et Josué dit aux fils d’Israël: Jusques à quand vous porterez-vous lâchement à aller prendre possession du pays que l’ Éternel, le Dieu de vos pères, vous a donné?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Choisissez-vous trois hommes par tribu, et je les enverrai; et ils se lèveront, et ils parcourront le pays, et ils en feront le relevé selon la proportion de leur héritage, puis ils viendront vers moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Ils le diviseront en sept parts; Juda se tiendra dans ses limites au midi, et la maison de Joseph se tiendra dans ses limites au nord;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'et vous ferez le relevé du pays en sept parts, et vous me l’apporterez ici; et je jetterai ici le sort pour vous devant l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Mais il n’y a point de part pour les Lévites au milieu de vous, car la sacrificature de l’ Éternel est leur héritage. Et Gad, et Ruben, et la demi-tribu de Manassé, ont reçu au-delà du Jourdain, vers le levant, leur héritage, que Moïse, serviteur de l’ Éternel, leur a donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Et les hommes se levèrent et s’en allèrent; et Josué commanda à ceux qui s’en allaient faire le relevé du pays, disant: Allez et parcourez le pays, et faites-en le relevé, et revenez auprès de moi, et je jetterai ici le sort pour vous devant l’ Éternel, à Silo.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Et les hommes s’en allèrent, et traversèrent le pays, et en firent le relevé dans un livre, en sept parts, selon les villes; puis ils vinrent vers Josué, au camp, à Silo.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Et Josué jeta le sort pour eux, à Silo, devant l’ Éternel, et Josué répartit là le pays aux fils d’Israël, selon leurs distributions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Et le sort tomba pour la tribu des fils de Benjamin, selon leurs familles. Et le territoire de leur lot leur échut entre les fils de Juda et les fils de Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Et leur frontière, du côté du nord, partait du Jourdain; et la frontière montait à côté de Jéricho, vers le nord, et montait dans la montagne vers l’occident, et aboutissait au désert de Beth-Aven;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'et la frontière passait de là à Luz, au côté méridional de Luz, qui est Béthel; et la frontière descendait à Ataroth-Addar, près de la montagne qui est au midi de Beth-Horon la basse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, '– Et la frontière fut tracée, et elle faisait un détour du côté occidental vers le midi, depuis la montagne qui est en face de Beth-Horon, vers le midi, et aboutissait à Kiriath-Baal, qui est Kiriath-Jéarim, ville des fils de Juda. C’est là le côté de l’occident.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, '– Et le côté méridional partait de l’extrémité de Kiriath-Jéarim; et la frontière sortait vers l’occident, et elle sortait vers la source des eaux de Nephtoah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Et la frontière descendait jusqu’au bout de la montagne qui est en face de la vallée de Ben-Hinnom, qui est dans la vallée des Rephaïm, vers le nord, et elle descendait la vallée de Hinnom à côté de Jébus, au midi, et descendait à En-Roguel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Et elle était tracée vers le nord, et sortait par En-Shémesh, et sortait à Gueliloth, qui est vis-à-vis de la montée d’Adummim, et descendait à la pierre de Bohan, fils de Ruben,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'et passait au côté nord, qui est vis-à-vis d’Araba, et descendait à Araba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Et la frontière passait à côté de Beth-Hogla, au nord; et la frontière aboutissait à la pointe de la mer Salée, vers le nord, à l’extrémité méridionale du Jourdain. C’est là la frontière du midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, '– Et le Jourdain formait la limite du côté de l’orient. Tel fut l’héritage des fils de Benjamin, selon ses frontières, à l’entour, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Et les villes de la tribu des fils de Benjamin, selon leurs familles, étaient: Jéricho, et Beth-Hogla, et Émek-Ketsits,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'et Beth-Araba, et Tsemaraïm, et Béthel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'et Avvim, et Para, et Ophra,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'et Kephar-Ammonaï, et Ophni, et Guéba: douze villes et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, '– Gabaon, et Rama, et Beéroth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'et Mitspé, et Kephira, et Motsa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'et Rékem, et Jirpeël, et Thareala,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'et Tséla, Éleph, et Jébus, qui est Jérusalem, Guibha, Kiriath: 14 villes et leurs hameaux. Tel fut l’héritage des fils de Benjamin, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Et le deuxième lot échut à Siméon, pour la tribu des fils de Siméon, selon leurs familles; et leur héritage fut au milieu de l’héritage des fils de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Et ils eurent dans leur héritage Beër-Shéba, et Shéba, et Molada,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'et Hatsar-Shual, et Bala, et Étsem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'et Eltholad, et Bethul, et Horma,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'et Tsiklag, et Beth-Marcaboth, et Hatsar-Susa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'et Beth-Lebaoth, et Sharukhen: 13 villes et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Aïn, Rimmon, et Éther, et Ashan: quatre villes et leurs hameaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'et tous les hameaux qui étaient autour de ces villes, jusqu’à Baalath-Beër, la Rama du midi. Tel fut l’héritage de la tribu des fils de Siméon, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'L’héritage des fils de Siméon fut pris du lot des fils de Juda, car la part des fils de Juda était trop grande pour eux; et les fils de Siméon héritèrent au milieu de leur héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Et le troisième sort tomba pour les fils de Zabulon, selon leurs familles; et la frontière de leur héritage fut jusqu’à Sarid;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'et leur frontière montait vers l’occident, et à Marhala, et touchait à Dabbésheth, et touchait au torrent qui est devant Jokneam;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'et elle tournait de Sarid vers l’orient au soleil levant, sur la frontière de Kisloth-Thabor, et sortait vers Dabrath, et montait à Japhia,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'et de là passait vers l’orient, au levant, à Gath-Hépher, à Eth-Katsin, et sortait à Rimmon, qui s’étend jusqu’à Néa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Et la frontière en faisait le tour, au nord, vers Hannathon, et aboutissait à la vallée de Jiphtah-El;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, '... et Kattath, et Nahalal, et Shimron, et Jideala, et Bethléhem: douze villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Tel fut l’héritage des fils de Zabulon, selon leurs familles: ces villes-là et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Le quatrième sort échut à Issacar, pour les fils d’Issacar, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Et leur territoire fut vers Jizreël, et Kesulloth, et Sunem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'et Hapharaïm, et Shion, et Anakharath,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'et Rabbith, et Kishion, et Ébets,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'et Rémeth, et En-Gannim, et En-Hadda, et Beth-Patsets;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'et la frontière touchait à Thabor, et à Shakhatsim, et à Beth-Shémesh; et leur frontière aboutissait au Jourdain: 16 villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Tel fut l’héritage de la tribu des fils d’Issacar, selon leurs familles: ces villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Et le cinquième sort échut à la tribu des fils d’Aser, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Et leur territoire fut Helkath, et Hali, et Béten, et Acshaph,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'et Allammélec, et Amhad, et Misheal; et [la frontière] touchait au Carmel, à l’occident, et au Shikhor-Libnath;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'et elle tournait vers le soleil levant, contre Beth-Dagon, et touchait à Zabulon et à la vallée de Jiphtah-El, au nord de Beth-Émek et de Neïel, et sortait vers Cabul au nord;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'et vers Ébron, et Rehob, et Hammon, et Kana, jusqu’à Sidon la grande;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'et la frontière tournait vers Rama et jusqu’à la ville forte de Tyr; et la frontière tournait vers Hosa, et aboutissait à la mer, près de la contrée d’Aczib;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, '... et Umma, et Aphek, et Rehob: 22 villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Tel fut l’héritage de la tribu des fils d’Aser, selon leurs familles: ces villes-là et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Le sixième sort échut aux fils de Nephthali, pour les fils de Nephthali, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Et leur frontière fut depuis Héleph, depuis le chêne de Tsaanannim, et Adami-Nékeb, et Jabneël, jusqu’à Lakkum, et elle aboutissait au Jourdain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'et la frontière tournait vers l’occident, contre Aznoth-Thabor, et sortait de là vers Hukkok, et touchait au midi à Zabulon; et à l’occident elle touchait à Aser, et à Juda sur le Jourdain au soleil levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Et les villes fortes étaient: Tsiddim, Tser, et Hammath, Rakkath, et Kinnéreth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'et Adama, et Rama, et Hatsor,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'et Kédesh, et Édréhi, et En-Hatsor,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'et Jireon, et Migdal-El, Horem, et Beth-Anath, et Beth-Shémesh: 19 villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Tel fut l’héritage de la tribu des fils de Nephthali, selon leurs familles: ces villes et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Le septième sort échut à la tribu des fils de Dan, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Et le territoire de leur héritage fut: Tsorha, et Eshtaol, et Ir-Shémesh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'et Shaalabbin, et Ajalon, et Jithla,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'et Élon, et Thimnatha, et Ékron,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'et Eltheké, et Guibbethon, et Baalath,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'et Jehud, et Bené-Berak, et Gath-Rimmon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'et Mé-Jarkon, et Rakkon, avec la frontière vis-à-vis de Japho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Et la frontière des fils de Dan se terminait par elles. Et les fils de Dan montèrent et combattirent contre Léshem, et la prirent, et la frappèrent par le tranchant de l’épée, et en prirent possession et y habitèrent; et ils appelèrent Léshem, Dan, du nom de Dan, leur père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Tel fut l’héritage de la tribu des fils de Dan, selon leurs familles: ces villes-là et leurs hameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Et quand on eut achevé de partager le pays selon ses frontières, les fils d’Israël donnèrent un héritage au milieu d’eux à Josué, fils de Nun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Selon le commandement de l’ Éternel, ils lui donnèrent la ville qu’il demanda: Thimnath-Sérakh, dans la montagne d’Éphraïm; et il bâtit la ville, et y habita.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Ce sont là les héritages qu’Éléazar, le sacrificateur, et Josué, fils de Nun, et les chefs des pères des tribus des fils d’Israël, distribuèrent par le sort, à Silo, devant l’ Éternel, à l’entrée de la tente d’assignation; et ils achevèrent le partage du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, '*Et l’ Éternel parla à Josué, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Parle aux fils d’Israël, en disant: Établissez-vous les villes de refuge dont je vous ai parlé par Moïse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'afin que l’homicide qui, par mégarde, aura frappé à mort quelqu’un sans le savoir, s’y enfuie; et elles vous serviront de refuge devant le vengeur du sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Et [l’homicide] s’enfuira dans l’une de ces villes, et il se tiendra à l’entrée de la porte de la ville, et dira aux oreilles des anciens de cette ville l’affaire qui lui est arrivée; et ils le recueilleront auprès d’eux dans la ville et lui donneront un lieu pour habiter avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Et si le vengeur du sang le poursuit, ils ne livreront pas l’homicide en sa main; car c’est sans le savoir qu’il a frappé son prochain: il ne le haïssait pas auparavant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Et il habitera dans cette ville, jusqu’à ce qu’il comparaisse en jugement devant l’assemblée, jusqu’à la mort du grand sacrificateur qui sera en ces jours-là; alors l’homicide s’en retournera et reviendra dans sa ville et dans sa maison, dans la ville d’où il s’était enfui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Et ils sanctifièrent Kédesh, en Galilée, dans la montagne de Nephthali; et Sichem, dans la montagne d’Éphraïm; et Kiriath-Arba, qui est Hébron, dans la montagne de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Et au-delà du Jourdain de Jéricho, vers le levant, ils établirent, de la tribu de Ruben, Bétser, dans le désert, sur le plateau; et Ramoth, en Galaad, de la tribu de Gad; et Golan, en Basan, de la tribu de Manassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Ce furent là les villes assignées à tous les fils d’Israël et à l’étranger qui séjournait parmi eux, afin que quiconque aurait, par mégarde, frappé à mort quelqu’un, s’y enfuie, et ne meure pas de la main du vengeur du sang, jusqu’à ce qu’il ait comparu devant l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, '*Et les chefs des pères des Lévites s’approchèrent d’Éléazar, le sacrificateur, et de Josué, fils de Nun, et des chefs des pères des tribus des fils d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'et leur parlèrent à Silo, dans le pays de Canaan, disant: L’ Éternel a commandé par Moïse qu’on nous donne des villes pour y habiter, et leurs banlieues pour nos bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Et les fils d’Israël donnèrent de leur héritage aux Lévites, selon le commandement de l’ Éternel, ces villes-ci, avec leurs banlieues:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Et le lot échut aux familles des Kehathites. Et il y eut, par le sort, pour les fils d’Aaron, le sacrificateur, d’entre les Lévites, 13 villes de la tribu de Juda, et de la tribu des Siméonites, et de la tribu de Benjamin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'et pour les autres fils de Kehath, dix villes des familles de la tribu d’Éphraïm, et de la tribu de Dan, et de la demi-tribu de Manassé, par le sort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'et pour les fils de Guershon, 13 villes des familles de la tribu d’Issacar, et de la tribu d’Aser, et de la tribu de Nephthali, et de la demi-tribu de Manassé, en Basan, par le sort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, '[et] pour les fils de Merari, selon leurs familles, douze villes de la tribu de Ruben, et de la tribu de Gad, et de la tribu de Zabulon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Et les fils d’Israël donnèrent aux Lévites, par le sort, ces villes-là et leurs banlieues, comme l’ Éternel l’avait commandé par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Et ils donnèrent, de la tribu des fils de Juda et de la tribu des fils de Siméon, ces villes-ci, qu’on nomma par leurs noms,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'et qui furent pour les fils d’Aaron, des familles des Kehathites, d’entre les fils de Lévi; car le premier lot fut pour eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'On leur donna: Kiriath-Arba ([Arba était] père d’Anak), c’est Hébron, dans la montagne de Juda, et sa banlieue autour d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Mais la campagne de la ville et ses hameaux, ils les donnèrent à Caleb, fils de Jephunné, pour sa possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Et ils donnèrent aux fils d’Aaron, le sacrificateur, la ville de refuge pour l’homicide: Hébron et sa banlieue; et Libna et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'et Jatthir et sa banlieue, et Eshtemoa et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'et Holon et sa banlieue, et Debir et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'et Aïn et sa banlieue, et Jutta et sa banlieue, [et] Beth-Shémesh et sa banlieue, neuf villes de ces deux tribus-là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'et de la tribu de Benjamin: Gabaon et sa banlieue, Guéba et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anathoth et sa banlieue, et Almon et sa banlieue, quatre villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Toutes les villes des fils d’Aaron, sacrificateurs: 13 villes et leurs banlieues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Et pour les familles des fils de Kehath, les autres Lévites d’entre les fils de Kehath, les villes de leur lot furent de la tribu d’Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Ils leur donnèrent la ville de refuge pour l’homicide: Sichem et sa banlieue, dans la montagne d’Éphraïm; et Guézer et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'et Kibtsaïm et sa banlieue, et Beth-Horon et sa banlieue, quatre villes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'et de la tribu de Dan: Eltheké et sa banlieue, Guibbethon et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalon et sa banlieue, Gath-Rimmon et sa banlieue, quatre villes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'et de la demi-tribu de Manassé: Thaanac et sa banlieue, et Gath-Rimmon et sa banlieue, deux villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'En tout dix villes et leurs banlieues, pour les familles des autres fils de Kehath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Et pour les fils de Guershon, d’entre les familles des Lévites, il y eut, de la demi-tribu de Manassé, la ville de refuge pour l’homicide: Golan, en Basan, et sa banlieue; et Beeshtra et sa banlieue, deux villes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'et de la tribu d’Issacar: Kishion et sa banlieue, Dabrath et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmuth et sa banlieue, En-Gannim et sa banlieue, quatre villes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'et de la tribu d’Aser: Misheal et sa banlieue, Abdon et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkath et sa banlieue, et Rehob et sa banlieue, quatre villes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'et de la tribu de Nephthali, la ville de refuge pour l’homicide: Kédesh, en Galilée, et sa banlieue; et Hammoth-Dor et sa banlieue, et Karthan et sa banlieue, trois villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Toutes les villes des Guershonites, selon leurs familles: 13 villes et leurs banlieues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Et pour les familles des fils de Merari, les autres Lévites, [on donna], de la tribu de Zabulon: Jokneam et sa banlieue, Kartha et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna et sa banlieue, Nahalal et sa banlieue, quatre villes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'et de la tribu de Ruben: Bétser et sa banlieue, et Jahtsa et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedémoth et sa banlieue, et Méphaath et sa banlieue, quatre villes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'et de la tribu de Gad, la ville de refuge pour l’homicide: Ramoth, en Galaad, et sa banlieue; et Mahanaïm et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbon et sa banlieue, Jahzer et sa banlieue: en tout, quatre villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Toutes ces villes étaient aux fils de Merari, selon leurs familles, – le reste des familles des Lévites; leur lot fut de douze villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Toutes les villes des Lévites, au milieu de la possession des fils d’Israël: 48 villes et leurs banlieues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Chacune de ces villes avait sa banlieue autour d’elle; il en était ainsi pour toutes ces villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Et l’ Éternel donna à Israël tout le pays qu’il avait juré de donner à leurs pères; et ils le possédèrent, et y habitèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Et l’ Éternel leur donna du repos à l’entour, selon tout ce qu’il avait juré à leurs pères; et, de tous leurs ennemis, pas un homme ne tint devant eux; l’ Éternel livra tous leurs ennemis entre leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Il ne tomba pas un mot de toutes les bonnes paroles que l’ Éternel avait dites à la maison d’Israël: tout arriva.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, '*Alors Josué appela les Rubénites, et les Gadites, et la demi-tribu de Manassé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'et leur dit: Vous avez gardé tout ce que Moïse, serviteur de l’ Éternel, vous avait commandé, et vous avez écouté ma voix en tout ce que je vous ai commandé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'vous n’avez pas abandonné vos frères pendant ce long temps, jusqu’à ce jour, et vous avez gardé ce que l’ Éternel, votre Dieu, vous a commandé de garder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Et maintenant, l’ Éternel, votre Dieu, a donné du repos à vos frères, comme il le leur avait dit. Et maintenant, retournez et allez dans vos tentes, dans le pays de votre possession, que Moïse, serviteur de l’ Éternel, vous a donné de l’autre côté du Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Seulement, prenez bien garde à pratiquer le commandement et la loi que vous a commandés Moïse, serviteur de l’ Éternel, pour aimer l’ Éternel, votre Dieu, et marcher dans toutes ses voies, et garder ses commandements, et pour vous attacher à lui, et pour le servir de tout votre cœur et de toute votre âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Et Josué les bénit et les renvoya; et ils s’en allèrent dans leurs tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Et Moïse avait donné à la demi-tribu de Manassé [son héritage] en Basan; et à l’autre demi-tribu, Josué avait donné [son héritage] avec leurs frères en deçà du Jourdain, à l’occident. Et lorsque Josué les renvoya dans leurs tentes, il les bénit aussi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'et leur parla, disant: Vous retournez à vos tentes avec de grands biens, et avec des troupeaux en très grand nombre, avec de l’argent, et de l’or, et de l’airain, et du fer, et des vêtements, en très grande abondance; partagez le butin de vos ennemis avec vos frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Et les fils de Ruben, et les fils de Gad, et la demi-tribu de Manassé, s’en retournèrent et s’en allèrent d’auprès des fils d’Israël, de Silo, qui est dans le pays de Canaan, pour aller dans le pays de Galaad, le pays de leur possession, dont ils avaient reçu la possession selon le commandement de l’ Éternel par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Et ils vinrent dans les contrées du Jourdain, qui sont dans le pays de Canaan; et les fils de Ruben, et les fils de Gad, et la demi-tribu de Manassé, bâtirent là un autel auprès du Jourdain, un autel de grande apparence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Et les fils d’Israël entendirent dire: Voici, les fils de Ruben, et les fils de Gad, et la demi-tribu de Manassé, ont bâti un autel en face du pays de Canaan, dans les contrées du Jourdain, à côté des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Et les fils d’Israël l’ayant appris, toute l’assemblée des fils d’Israël se réunit à Silo, pour monter en bataille contre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Et les fils d’Israël envoyèrent vers les fils de Ruben, et vers les fils de Gad, et vers la demi-tribu de Manassé, au pays de Galaad, Phinées, fils d’Éléazar, le sacrificateur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'et avec lui dix princes, un prince par maison de père, de toutes les tribus d’Israël; et chacun d’eux était chef de maison de père des milliers d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'et ils vinrent vers les fils de Ruben, et vers les fils de Gad, et vers la demi-tribu de Manassé, au pays de Galaad, et leur parlèrent, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Ainsi dit toute l’assemblée de l’ Éternel: Quel est ce crime que vous avez commis contre le Dieu d’Israël, vous détournant aujourd’hui de l’ Éternel en vous bâtissant un autel, vous rebellant aujourd’hui contre l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Est-ce peu de chose que l’iniquité de Péor, dont nous ne nous sommes pas purifiés jusqu’à aujourd’hui, quoiqu’il y ait eu une plaie sur l’assemblée de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'et vous vous détournez aujourd’hui de l’ Éternel! Or il arrivera, si vous vous rebellez aujourd’hui contre l’ Éternel, que demain il sera courroucé contre toute l’assemblée d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Si toutefois le pays de votre possession est impur, passez dans le pays qui est la possession de l’ Éternel, où est le tabernacle de l’ Éternel, et ayez votre possession au milieu de nous, mais ne vous rebellez pas contre l’ Éternel, et ne vous rebellez pas contre nous, en vous bâtissant un autel outre l’autel de l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Acan, le fils de Zérakh, ne commit-il pas un crime au sujet de l’anathème? et il y eut de la colère contre toute l’assemblée d’Israël. Et lui n’expira pas seul dans son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Et les fils de Ruben, et les fils de Gad, et la demi-tribu de Manassé, répondirent et dirent aux chefs des milliers d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Le ✶Dieu des dieux, l’ Éternel, le ✶Dieu des dieux, l’ Éternel, lui le sait, et Israël, lui le saura, si c’est par rébellion, et si c’est par iniquité contre l’ Éternel, (ne nous sauve pas en ce jour!)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'que nous nous sommes bâti un autel pour nous détourner de l’ Éternel, si ç’a été pour y offrir des holocaustes et des offrandes de gâteaux, et si ç’a été pour y faire des sacrifices de prospérités, (que l’ Éternel lui-même le redemande!)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'et si ce n’est pas par crainte de cette chose, que nous avons fait cela, disant: Dans l’avenir vos fils parleront à nos fils, disant: Qu’y a-t-il de commun entre vous et l’ Éternel, le Dieu d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'L’ Éternel a mis une frontière, le Jourdain entre nous et vous, fils de Ruben et fils de Gad; vous n’avez point de part à l’ Éternel. Et ainsi vos fils feraient que nos fils cesseraient de craindre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Et nous avons dit: Mettons-nous donc à bâtir un autel, non pour des holocaustes, ni pour des sacrifices,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'mais comme témoin entre nous et vous, et entre nos générations après nous, afin de faire le service de l’ Éternel devant lui par nos holocaustes, et par nos sacrifices, et par nos sacrifices de prospérités; afin que vos fils ne disent pas dans l’avenir à nos fils: Vous n’avez point de part à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Et nous avons dit: S’il arrive qu’ils nous disent cela, à nous et à nos générations dans l’avenir, nous [leur] dirons: Voyez la forme de l’autel de l’ Éternel que nos pères ont fait, non pour des holocaustes, ni pour des sacrifices, mais comme témoin entre nous et vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Loin de nous que nous nous rebellions contre l’ Éternel, et que nous nous détournions aujourd’hui de l’ Éternel en bâtissant un autel pour des holocaustes, pour des offrandes de gâteaux et pour des sacrifices, outre l’autel de l’ Éternel, notre Dieu, qui est devant son tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Et quand Phinées, le sacrificateur, et les princes de l’assemblée, et les chefs des milliers d’Israël qui étaient avec lui, entendirent les paroles que prononcèrent les fils de Ruben et les fils de Gad et les fils de Manassé, la chose fut bonne à leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Et Phinées, fils d’Éléazar, le sacrificateur, dit aux fils de Ruben et aux fils de Gad et aux fils de Manassé: Nous connaissons aujourd’hui que l’ Éternel est au milieu de nous, en ce que vous n’avez pas commis ce crime contre l’ Éternel; maintenant vous avez sauvé les fils d’Israël de la main de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Et Phinées, fils d’Éléazar, le sacrificateur, et les princes, s’en retournèrent d’auprès des fils de Ruben et d’auprès des fils de Gad, du pays de Galaad au pays de Canaan, vers les fils d’Israël, et leur rapportèrent la chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Et la chose fut bonne aux yeux des fils d’Israël; et les fils d’Israël bénirent Dieu, et ne pensèrent plus à monter en bataille contre eux pour détruire le pays où habitaient les fils de Ruben et les fils de Gad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Et les fils de Ruben et les fils de Gad donnèrent un nom à l’autel; car, [dirent-ils,] il est témoin entre nous que l’ Éternel est Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, '*Et longtemps après que l’ Éternel eut donné du repos à Israël de tous leurs ennemis à l’entour, – et Josué était vieux, avancé en âge,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, '– il arriva que Josué appela tout Israël, ses anciens, et ses chefs, et ses juges, et ses magistrats, et leur dit: Je suis vieux, je suis avancé en âge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'et vous avez vu tout ce que l’ Éternel, votre Dieu, a fait à toutes ces nations à cause de vous; car l’ Éternel, votre Dieu, est celui qui a combattu pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Voyez, je vous ai distribué par le sort, en héritage, selon vos tribus, ces nations qui restent, depuis le Jourdain, ainsi que toutes les nations que j’ai exterminées, jusqu’à la grande mer vers le soleil couchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Et l’ Éternel, votre Dieu, les chassera devant vous, et les dépossédera devant vous; et vous prendrez possession de leur pays, comme l’ Éternel, votre Dieu, vous l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Et fortifiez-vous beaucoup pour garder et pour pratiquer tout ce qui est écrit dans le livre de la loi de Moïse, afin de ne vous en écarter ni à droite ni à gauche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'afin que vous n’entriez pas parmi ces nations qui restent parmi vous, et que vous ne fassiez pas mention du nom de leurs dieux, et que vous ne fassiez pas jurer par eux, et que vous ne les serviez pas, et que vous ne vous prosterniez pas devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Mais vous vous attacherez à l’ Éternel, votre Dieu, comme vous l’avez fait jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Et l’ Éternel a dépossédé devant vous des nations grandes et fortes; et quant à vous, personne n’a tenu devant vous, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Un seul homme d’entre vous en poursuit 1 000; car l’ Éternel, votre Dieu, est celui qui combat pour vous, comme il vous l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Or prenez bien garde à vos âmes pour aimer l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Car si vous retournez en arrière, et que vous vous attachiez au reste de ces nations, à celles qui sont demeurées parmi vous, et que vous vous alliiez par mariage avec elles, et que vous entriez parmi elles et elles parmi vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'sachez certainement que l’ Éternel, votre Dieu, ne continuera pas à déposséder ces nations devant vous; et elles vous seront un filet, et un piège, et un fouet dans vos côtés, et des épines dans vos yeux, jusqu’à ce que vous ayez péri de dessus ce bon pays que l’ Éternel, votre Dieu, vous a donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Et voici, moi je m’en vais aujourd’hui le chemin de toute la terre, et vous savez de tout votre cœur et de toute votre âme qu’il n’est pas tombé un seul mot de toutes les bonnes paroles que l’ Éternel, votre Dieu, a dites à votre sujet: tout vous est arrivé; il n’en est pas tombé un seul mot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Et il arrivera que, comme chaque bonne parole que l’ Éternel, votre Dieu, vous a dite, s’est accomplie à votre égard, ainsi l’ Éternel fera venir sur vous chaque mauvaise parole, jusqu’à ce qu’il vous ait détruits de dessus ce bon pays que l’ Éternel, votre Dieu, vous a donné,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'lorsque vous aurez transgressé l’alliance de l’ Éternel, votre Dieu, qu’il vous a commandée, et que vous serez allés et aurez servi d’autres dieux, et que vous vous serez prosternés devant eux, en sorte que la colère de l’ Éternel s’embrase contre vous, et que vous périssiez rapidement de dessus le bon pays qu’il vous a donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, '*Et Josué assembla toutes les tribus d’Israël à Sichem, et il appela les anciens d’Israël, et ses chefs, et ses juges, et ses magistrats; et ils se tinrent devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Et Josué dit à tout le peuple: Ainsi dit l’ Éternel, le Dieu d’Israël: Vos pères, Térakh, père d’Abraham et père de Nakhor, ont habité anciennement au-delà du fleuve, et ils ont servi d’autres dieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'et je pris votre père Abraham d’au-delà du fleuve, et je le fis aller par tout le pays de Canaan, et je multipliai sa semence: je lui donnai Isaac,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'et je donnai à Isaac Jacob et Ésaü; et je donnai à Ésaü la montagne de Séhir pour la posséder; et Jacob et ses fils descendirent en Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'et j’envoyai Moïse et Aaron, et je frappai l’Égypte de plaies, selon ce que j’ai fait au milieu d’elle; et ensuite je vous en fis sortir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Je fis sortir vos pères de l’Égypte, et vous êtes venus à la mer; et les Égyptiens poursuivirent vos pères avec des chars et des cavaliers jusqu’à la mer Rouge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'et ils crièrent à l’ Éternel, et il mit une obscurité entre vous et les Égyptiens, et fit venir la mer sur eux, et les couvrit; et vos yeux virent ce que je fis aux Égyptiens; et vous avez habité longtemps dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Et je vous amenai au pays des Amoréens qui habitaient au-delà du Jourdain; et ils vous firent la guerre; et je les livrai en votre main, et vous avez pris possession de leur pays, et je les détruisis devant vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Et Balak, fils de Tsippor, roi de Moab, se leva et fit la guerre contre Israël; et il envoya et appela Balaam, fils de Béor, pour vous maudire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'mais je ne voulus pas écouter Balaam, et il vous bénit expressément; et je vous délivrai de sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Et vous avez passé le Jourdain, et vous êtes venus à Jéricho; et les hommes de Jéricho, [et] l’Amoréen, et le Phérézien, et le Cananéen, et le Héthien, et le Guirgasien, le Hévien, et le Jébusien, vous firent la guerre, et je les livrai en votre main;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'et j’envoyai devant vous les frelons qui les chassèrent devant vous, [comme] les deux rois des Amoréens: ce ne fut point par ton épée ni par ton arc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Et je vous donnai un pays où tu n’avais pas travaillé et des villes que vous n’aviez point bâties, et vous y habitez; vous mangez [le fruit] des vignes et des oliviers que vous n’avez pas plantés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Et maintenant, craignez l’ Éternel, et servez-le en intégrité et en vérité; et ôtez les dieux que vos pères ont servis de l’autre côté du fleuve et en Égypte, et servez l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Et s’il est mauvais à vos yeux de servir l’ Éternel, choisissez aujourd’hui qui vous voulez servir, soit les dieux que vos pères qui étaient de l’autre côté du fleuve ont servis, soit les dieux de l’Amoréen, dans le pays duquel vous habitez. Mais moi et ma maison, nous servirons l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Et le peuple répondit et dit: Loin de nous que nous abandonnions l’ Éternel pour servir d’autres dieux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Car l’ Éternel, notre Dieu, c’est lui qui nous a fait monter, nous et nos pères, du pays d’Égypte, de la maison de servitude, et qui a fait devant nos yeux ces grands signes, et qui nous a gardés dans tout le chemin par lequel nous avons marché, et parmi tous les peuples au milieu desquels nous avons passé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Et l’ Éternel a chassé de devant nous tous les peuples, et l’Amoréen qui habitait dans le pays. Aussi nous, nous servirons l’ Éternel, car c’est lui qui est notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Et Josué dit au peuple: Vous ne pourrez pas servir l’ Éternel; car il est un Dieu saint, il est un ✶Dieu jaloux: il ne pardonnera pas votre transgression et vos péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Si vous abandonnez l’ Éternel, et si vous servez des dieux étrangers, alors il se retournera et vous fera du mal et vous consumera après vous avoir fait du bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Et le peuple dit à Josué: Non, car nous servirons l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Et Josué dit au peuple: Vous êtes témoins contre vous-mêmes que c’est vous qui vous êtes choisi l’ Éternel pour le servir. Et ils dirent: [Nous en sommes] témoins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Et maintenant, ôtez les dieux étrangers qui sont au milieu de vous, et inclinez votre cœur vers l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Et le peuple dit à Josué: Nous servirons l’ Éternel, notre Dieu, et nous écouterons sa voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Et Josué fit une alliance avec le peuple en ce jour-là, et lui établit un statut et une ordonnance, à Sichem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Et Josué écrivit ces paroles dans le livre de la loi de Dieu. Et il prit une grande pierre, et la dressa là sous le chêne qui était auprès du sanctuaire de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'et Josué dit à tout le peuple: Voici, cette pierre sera témoin contre nous, car elle a entendu toutes les paroles de l’ Éternel, qu’il nous a dites; et elle sera témoin contre vous, de peur que vous ne reniiez votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Et Josué renvoya le peuple, chacun à son héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Et il arriva, après ces choses, que Josué, fils de Nun, serviteur de l’ Éternel, mourut, âgé de 110 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Et on l’enterra dans les limites de son héritage, à Thimnath-Sérakh, qui est dans la montagne d’Éphraïm, au nord de la montagne de Gaash.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Et Israël servit l’ Éternel tous les jours de Josué, et tous les jours des anciens dont les jours se prolongèrent après Josué et qui avaient connu toute l’œuvre de l’ Éternel, qu’il avait faite pour Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Et on enterra à Sichem les os de Joseph, que les fils d’Israël avaient transportés d’Égypte, dans la portion de champ que Jacob avait achetée des fils de Hamor, père de Sichem, pour 100 kesitas, et qui devint l’héritage des fils de Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Et Éléazar, fils d’Aaron, mourut; et on l’enterra dans le coteau de Phinées, son fils, qui lui avait été donné dans la montagne d’Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Et il arriva, après la mort de Josué, que les fils d’Israël interrogèrent l’ Éternel, disant: Qui de nous montera le premier contre le Cananéen, pour lui faire la guerre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Et l’ Éternel dit: Juda montera; voici, j’ai livré le pays en sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Et Juda dit à Siméon, son frère: Monte avec moi dans mon lot, et faisons la guerre contre le Cananéen; et moi aussi j’irai avec toi dans ton lot. Et Siméon alla avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Et Juda monta; et l’ Éternel livra le Cananéen et le Phérézien en leur main; et ils les frappèrent à Bézek, 10 000 hommes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'ils trouvèrent Adoni-Bézek à Bézek, et ils lui firent la guerre, et frappèrent le Cananéen et le Phérézien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Et Adoni-Bézek s’enfuit; et ils le poursuivirent, et le saisirent, et lui coupèrent les pouces des mains et des pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Et Adoni-Bézek dit: 70 rois, ayant les pouces de leurs mains et de leurs pieds coupés, ramassaient sous ma table; comme j’ai fait, ainsi Dieu m’a rendu. Et on l’amena à Jérusalem, et il y mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Et les fils de Juda avaient fait la guerre contre Jérusalem, et l’avaient prise, et ils l’avaient frappée par le tranchant de l’épée, et avaient livré la ville au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Et ensuite les fils de Juda descendirent pour faire la guerre au Cananéen qui habitait la montagne, et le midi et le pays plat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Et Juda s’en alla contre le Cananéen qui habitait à Hébron (or le nom de Hébron était auparavant Kiriath-Arba), et ils frappèrent Shéshaï, et Akhiman, et Thalmaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Et de là il s’en alla contre les habitants de Debir; or le nom de Debir était auparavant Kiriath-Sépher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Et Caleb dit: À qui frappera Kiriath-Sépher et la prendra, je lui donnerai ma fille Acsa pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Et Othniel, fils de Kenaz, frère puîné de Caleb, la prit; et [Caleb] lui donna sa fille Acsa pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Et il arriva que, comme elle entrait, elle l’incita à demander à son père un champ. Et elle descendit de dessus l’âne; et Caleb lui dit: Qu’as-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Et elle lui dit: Donne-moi une bénédiction; car tu m’as donné une terre du midi, donne-moi aussi des sources d’eau. Et Caleb lui donna les sources du haut et les sources du bas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Et les fils du Kénien, beau-père de Moïse, étaient montés de la ville des palmiers, avec les fils de Juda, au désert de Juda, qui est au midi d’Arad; et ils allèrent et habitèrent avec le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Et Juda s’en alla avec Siméon, son frère, et ils frappèrent le Cananéen qui habitait à Tsephath, et détruisirent entièrement la [ville]; et on appela la ville du nom de Horma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Et Juda prit Gaza et ses confins, et Askalon et ses confins, et Ékron et ses confins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Et l’ Éternel fut avec Juda; et il prit possession de la montagne; car il ne déposséda pas les habitants de la vallée, parce qu’ils avaient des chars de fer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Et on donna Hébron à Caleb, comme Moïse l’avait dit, et il en déposséda les trois fils d’Anak.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Et les fils de Benjamin ne dépossédèrent pas le Jébusien, habitant de Jérusalem; et le Jébusien a habité avec les fils de Benjamin à Jérusalem jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Et la maison de Joseph, eux aussi, montèrent à Béthel, et l’ Éternel fut avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Et la maison de Joseph fit reconnaître Béthel: le nom de la ville était auparavant Luz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Et les gardes virent un homme qui sortait de la ville, et ils lui dirent: Montre-nous, nous t’en prions, par où l’on entre dans la ville; et nous userons de bonté envers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Et il leur montra par où l’on entrait dans la ville; et ils frappèrent la ville par le tranchant de l’épée, mais ils laissèrent aller l’homme et toute sa famille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Et l’homme s’en alla dans le pays des Héthiens, et bâtit une ville et l’appela du nom de Luz: c’est là son nom jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Et Manassé ne déposséda pas Beth-Shean et les villages de son ressort, ni Thaanac et les villages de son ressort, ni les habitants de Dor et des villages de son ressort, ni les habitants de Jibleam et des villages de son ressort, ni les habitants de Meguiddo et des villages de son ressort; et le Cananéen voulut habiter dans ce pays-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Et il arriva que, quand Israël fut devenu fort, il rendit le Cananéen tributaire; mais il ne le déposséda pas entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Et Éphraïm ne déposséda pas le Cananéen qui habitait à Guézer; mais le Cananéen a habité au milieu d’eux à Guézer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zabulon ne déposséda pas les habitants de Kitron, ni les habitants de Nahalol; mais le Cananéen a habité au milieu d’eux, et fut rendu tributaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Aser ne déposséda pas les habitants d’Acco, ni les habitants de Sidon, ni Akhlab, ni Aczib, ni Helba, ni Aphik, ni Rehob;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'et l’Asérite a habité au milieu des Cananéens, habitants du pays, car il ne les déposséda pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Nephthali ne déposséda pas les habitants de Beth-Shémesh, ni les habitants de Beth-Anath; et il a habité au milieu des Cananéens, habitants du pays; mais les habitants de Beth-Shémesh et de Beth-Anath lui devinrent tributaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Et les Amoréens repoussèrent dans la montagne les fils de Dan, car ils ne leur permirent pas de descendre dans la vallée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Et l’Amoréen voulut habiter dans la montagne de Hérès, à Ajalon et à Shaalbim; mais la main de la maison de Joseph devint forte, et ils furent soumis au tribut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Et la frontière de l’Amoréen était depuis la montée d’Akrabbim, depuis le rocher, et en dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Et l’Ange de l’ Éternel monta de Guilgal à Bokim; et il dit: Je vous ai fait monter d’Égypte, et je vous ai introduits dans le pays que j’avais promis par serment à vos pères, et j’ai dit: Je ne romprai jamais mon alliance avec vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'et vous, vous ne traiterez point alliance avec les habitants de ce pays, vous démolirez leurs autels. Et vous n’avez pas écouté ma voix. Pourquoi avez-vous fait cela?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Et aussi j’ai dit: Je ne les chasserai pas de devant vous, et ils seront à vos côtés, et leurs dieux vous seront en piège.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Et il arriva que, comme l’Ange de l’ Éternel disait ces paroles à tous les fils d’Israël, le peuple éleva sa voix et pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Et ils appelèrent le nom de ce lieu-là Bokim; et ils sacrifièrent là à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, '*Et Josué renvoya le peuple, et les fils d’Israël s’en allèrent chacun à son héritage pour posséder le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Et le peuple servit l’ Éternel tous les jours de Josué, et tous les jours des anciens dont les jours se prolongèrent après Josué, [et] qui avaient vu toute la grande œuvre de l’ Éternel, qu’il avait faite pour Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Et Josué, fils de Nun, serviteur de l’ Éternel, mourut, âgé de 110 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Et on l’enterra dans les limites de son héritage, à Thimnath-Hérès, dans la montagne d’Éphraïm, au nord de la montagne de Gaash.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Et toute cette génération fut aussi recueillie vers ses pères; et après eux, se leva une autre génération qui ne connaissait pas l’ Éternel, ni l’œuvre qu’il avait faite pour Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Et les fils d’Israël firent ce qui est mauvais aux yeux de l’ Éternel, et servirent les Baals.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Et ils abandonnèrent l’ Éternel, le Dieu de leurs pères, qui les avait fait sortir du pays d’Égypte; et ils marchèrent après d’autres dieux, d’entre les dieux des peuples qui étaient autour d’eux, et se prosternèrent devant eux; et ils provoquèrent à colère l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'et abandonnèrent l’ Éternel, et servirent Baal et Ashtaroth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Et la colère de l’ Éternel s’embrasa contre Israël; et il les livra en la main de pillards qui les pillèrent; et il les vendit en la main de leurs ennemis d’alentour; et ils ne purent plus se maintenir devant leurs ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Partout où ils sortaient, la main de l’ Éternel était contre eux en mal, comme l’ Éternel avait dit, et comme l’ Éternel le leur avait juré; et ils furent dans une grande détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Et l’ Éternel suscita des juges; et ils les délivrèrent de la main de ceux qui les pillaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Mais, même leurs juges, ils ne les écoutèrent pas; car ils se prostituèrent après d’autres dieux et se prosternèrent devant eux; ils se détournèrent vite du chemin où leurs pères avaient marché en écoutant les commandements de l’ Éternel: ils ne firent pas ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Et quand l’ Éternel leur suscitait des juges, l’ Éternel était avec le juge, et les délivrait de la main de leurs ennemis pendant tous les jours du juge; car l’ Éternel avait pitié, à cause de leur gémissement devant ceux qui les opprimaient et qui les accablaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Et il arrivait que, lorsque le juge mourait, ils retournaient à se corrompre plus que leurs pères, marchant après d’autres dieux pour les servir et pour se prosterner devant eux: ils n’abandonnaient rien de leurs actions et de leur voie obstinée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Et la colère de l’ Éternel s’embrasa contre Israël, et il dit: Puisque cette nation a transgressé mon alliance, que j’avais commandée à leurs pères, et qu’ils n’ont pas écouté ma voix,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'moi aussi je ne déposséderai plus un homme devant eux, d’entre les nations que Josué laissa quand il mourut,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'afin d’éprouver par elles Israël, s’ils garderont la voie de l’ Éternel pour y marcher, comme leurs pères l’ont gardée, ou non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Et l’ Éternel laissa subsister ces nations sans se hâter de les déposséder; il ne les livra pas en la main de Josué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Et ce sont ici les nations que l’ Éternel laissa subsister pour éprouver par elles Israël, [savoir] tous ceux qui n’avaient pas connu toutes les guerres de Canaan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, '[et cela] seulement afin que les générations des fils d’Israël connaissent, en l’apprenant, ce que c’est que la guerre, ceux du moins qui auparavant n’en avaient rien connu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'cinq princes des Philistins, et tous les Cananéens et les Sidoniens et les Héviens qui habitaient dans la montagne du Liban, depuis la montagne de Baal-Hermon jusqu’à l’entrée de Hamath;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'elles étaient [laissées] pour éprouver par elles Israël, pour savoir s’ils écouteraient les commandements de l’ Éternel, qu’il avait commandés à leurs pères par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, '*Et les fils d’Israël habitèrent au milieu des Cananéens, des Héthiens, et des Amoréens, et des Phéréziens, et des Héviens, et des Jébusiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Et ils prirent leurs filles pour femmes, et donnèrent leurs filles à leurs fils, et servirent leurs dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Et les fils d’Israël firent ce qui est mauvais aux yeux de l’ Éternel, et ils oublièrent l’ Éternel, leur Dieu, et servirent les Baals et les ashères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Et la colère de l’ Éternel s’embrasa contre Israël, et il les vendit en la main de Cushan-Rishhathaïm, roi d’Aram-Naharaïm. Et les fils d’Israël servirent Cushan-Rishhathaïm huit ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Et les fils d’Israël crièrent à l’ Éternel; et l’ Éternel suscita aux fils d’Israël un sauveur qui les délivra, Othniel, fils de Kenaz, frère puîné de Caleb.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Et l’Esprit de l’ Éternel fut sur lui, et il jugea Israël; et il sortit pour la guerre, et l’ Éternel livra en sa main Cushan-Rishhathaïm, roi d’Aram, et sa main fut forte contre Cushan-Rishhathaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Et le pays fut en repos 40 ans. Et Othniel, fils de Kenaz, mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Et les fils d’Israël firent de nouveau ce qui est mauvais aux yeux de l’ Éternel, et l’ Éternel fortifia Églon, roi de Moab, contre Israël, parce qu’ils faisaient ce qui est mauvais aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Et [Églon] assembla auprès de lui les fils d’Ammon et Amalek, et il alla et frappa Israël; et ils prirent possession de la ville des palmiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Et les fils d’Israël servirent Églon, roi de Moab, 18 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Et les fils d’Israël crièrent à l’ Éternel; et l’ Éternel leur suscita un sauveur, Éhud, fils de Guéra, le Benjaminite, qui était gaucher. Et les fils d’Israël envoyèrent par lui un présent à Églon, roi de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Et Éhud se fit faire une épée à deux tranchants, longue d’une petite coudée, et il la ceignit par-dessous ses vêtements, sur la hanche droite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Et il offrit le présent à Églon, roi de Moab; or Églon était un homme très gras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Et il arriva que, lorsqu’il eut achevé d’offrir le présent, il renvoya les gens qui avaient apporté le présent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Mais lui s’en revint des images taillées, qui étaient près de Guilgal, et dit: J’ai pour toi une parole secrète, ô roi! Et il dit: Silence! Et tous ceux qui étaient près de lui sortirent d’auprès de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Et Éhud entra vers lui; or il était assis dans une chambre haute de rafraîchissement, qui était pour lui seul; et Éhud dit: J’ai une parole de Dieu pour toi. Et [le roi] se leva de son siège;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'et Éhud étendit sa main gauche, et prit l’épée de dessus son côté droit, et la lui enfonça dans le ventre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'et même la poignée entra après la lame, et la graisse se referma sur la lame; car il ne retira pas l’épée de son ventre, et elle sortit entre les jambes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Et Éhud sortit par le portique, et ferma sur lui les portes de la chambre haute, et mit le verrou.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Et quand il fut sorti, les serviteurs du roi vinrent, et virent: et voici, les portes de la chambre haute étaient fermées au verrou; et ils dirent: Sans doute il se couvre les pieds dans la chambre de rafraîchissement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Et ils attendirent jusqu’à en avoir honte; et voici, on n’ouvrait pas les portes de la chambre; et ils prirent la clé et ouvrirent, et voici, leur seigneur gisait par terre, mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Et Éhud s’était échappé pendant qu’ils tardaient, et avait dépassé les images taillées; et il se sauva à Sehira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Et quand il y fut entré, il arriva qu’il sonna de la trompette dans la montagne d’Éphraïm; et les fils d’Israël descendirent avec lui de la montagne, et lui devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Et il leur dit: Suivez-moi, car l’ Éternel a livré en votre main vos ennemis, les Moabites. Et ils descendirent après lui, et enlevèrent à Moab les gués du Jourdain, et ne laissèrent passer personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Et en ce temps-là, ils frappèrent Moab, environ 10 000 hommes, tous forts et tous vaillants, et pas un n’échappa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Et en ce jour-là, Moab fut abattu sous la main d’Israël; et le pays fut en repos 80 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Et après lui, il y eut Shamgar, fils d’Anath; et il frappa les Philistins, 600 hommes, avec un aiguillon à bœufs. Et lui aussi sauva Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, '*Et les fils d’Israël firent de nouveau ce qui est mauvais aux yeux de l’ Éternel; or Éhud était mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Et l’ Éternel les vendit en la main de Jabin, roi de Canaan, qui régnait à Hatsor; et le chef de son armée était Sisera, et celui-ci habitait à Harosheth des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Et les fils d’Israël crièrent à l’ Éternel; car [Jabin] avait 900 chars de fer, et il opprima fortement les fils d’Israël pendant 20 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Et Debora, une prophétesse, femme de Lappidoth, jugeait Israël en ce temps-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Et elle habitait sous le palmier de Debora, entre Rama et Béthel, dans la montagne d’Éphraïm; et les fils d’Israël montaient vers elle pour être jugés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Et elle envoya, et appela Barak, fils d’Abinoam, de Kédesh de Nephthali, et lui dit: L’ Éternel, le Dieu d’Israël, ne l’a-t-il pas commandé? Va, et rends-toi sur le mont Thabor, et prends avec toi 10 000 hommes des fils de Nephthali et des fils de Zabulon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'et j’attirerai vers toi, vers le torrent de Kison, Sisera, chef de l’armée de Jabin, et ses chars, et sa multitude, et je le livrerai en ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Et Barak lui dit: Si tu vas avec moi, j’irai; mais si tu ne vas pas avec moi, je n’irai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Et elle dit: J’irai bien avec toi; seulement ce ne sera pas à ton honneur dans le chemin où tu vas, car l’ Éternel vendra Sisera en la main d’une femme. Et Debora se leva, et s’en alla avec Barak à Kédesh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Et Barak rassembla Zabulon et Nephthali à Kédesh; et 10 000 hommes montèrent à sa suite, et Debora monta avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, '(Or Héber, le Kénien, s’était séparé des Kéniens, fils de Hobab, beau-père de Moïse, et avait dressé sa tente jusqu’au chêne de Tsaannaïm, qui est près de Kédesh.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Et on rapporta à Sisera que Barak, fils d’Abinoam, était monté sur le mont Thabor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Et Sisera rassembla tous ses chars, 900 chars de fer, et tout le peuple qui était avec lui, depuis Harosheth des nations, au torrent de Kison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Et Debora dit à Barak: Lève-toi, car c’est ici le jour où l’ Éternel livrera Sisera en ta main. L’ Éternel n’est-il pas sorti devant toi? Et Barak descendit du mont Thabor, et 10 000 hommes après lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Et l’ Éternel mit en déroute Sisera, et tous ses chars, et toute l’armée, par le tranchant de l’épée, devant Barak; et Sisera descendit de son char, et s’enfuit à pied.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Et Barak poursuivit les chars et l’armée jusqu’à Harosheth des nations; et toute l’armée de Sisera tomba sous le tranchant de l’épée: il n’en resta pas un seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Et Sisera s’enfuit à pied vers la tente de Jaël, femme de Héber, le Kénien; car il y avait paix entre Jabin, roi de Hatsor, et la maison de Héber, le Kénien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Et Jaël sortit à la rencontre de Sisera, et lui dit: Retire-toi, mon seigneur, retire-toi chez moi, ne crains point. Et il se retira chez elle dans la tente, et elle le couvrit d’une couverture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Et il lui dit: Je te prie, donne-moi un peu d’eau à boire, car j’ai soif. Et elle ouvrit l’outre du lait et lui donna à boire, et le couvrit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Et il lui dit: Tiens-toi à l’entrée de la tente, et s’il arrive qu’on vienne et qu’on t’interroge et dise: Y a-t-il quelqu’un ici? tu diras: Non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Et Jaël, femme de Héber, prit un pieu de la tente, et saisit le marteau dans sa main, et elle vint vers lui doucement, et lui enfonça le pieu dans la tempe, de sorte qu’il pénétra dans la terre; or il dormait profondément et était fatigué; et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Et voici Barak, qui poursuivait Sisera; et Jaël sortit à sa rencontre, et lui dit: Viens, et je te montrerai l’homme que tu cherches. Et il entra chez elle; et voici, Sisera gisait [là], mort, et le pieu dans sa tempe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Et en ce jour-là, Dieu abattit Jabin, roi de Canaan, devant les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Et la main des fils d’Israël avançait toujours et pesait durement sur Jabin, roi de Canaan, jusqu’à ce qu’ils eurent retranché Jabin, roi de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Et Debora chanta, en ce jour-là, avec Barak, fils d’Abinoam, en disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Parce que des chefs se sont mis en avant en Israël, parce que le peuple a été porté de bonne volonté, bénissez l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Rois, écoutez! princes, prêtez l’oreille! Moi, moi, je chanterai à l’ Éternel; je chanterai un hymne à l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Éternel! quand tu sortis de Séhir, quand tu t’avanças des champs d’Édom, la terre trembla, et les cieux distillèrent, et les nuées distillèrent des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Les montagnes se fondirent devant l’ Éternel, ce Sinaï, devant l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Aux jours de Shamgar, fils d’Anath, aux jours de Jaël, les chemins étaient délaissés, et ceux qui allaient par les grands chemins allaient par des sentiers détournés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Les villes ouvertes étaient délaissées en Israël, elles étaient délaissées, – jusqu’à ce que je me suis levée, moi Debora, jusqu’à ce que je me suis levée, une mère en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'On choisissait de nouveaux dieux, alors la guerre était aux portes! On ne voyait ni bouclier ni pique chez quarante milliers en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mon cœur est aux gouverneurs d’Israël qui ont été portés de bonne volonté parmi le peuple. Bénissez l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Vous qui montez sur des ânesses blanches, vous qui êtes assis sur des tapis, et vous qui allez par les chemins, méditez!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'À cause de la voix de ceux qui partagent [le butin], au milieu des lieux où l’on puise l’eau: là, ils racontent les justes actes de l’ Éternel, ses justes actes envers ses villes ouvertes en Israël. Alors le peuple de l’ Éternel est descendu aux portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Réveille-toi, réveille-toi, Debora! Réveille-toi, réveille-toi, dis un cantique! Lève-toi, Barak, et emmène captifs tes captifs, fils d’Abinoam!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Alors descends, toi, le résidu des nobles, [comme son] peuple; Éternel! descends avec moi au milieu des hommes forts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'D’Éphraïm [sont venus] ceux dont la racine est en Amalek; derrière toi [vient] Benjamin, au milieu de tes peuples. De Makir sont descendus les gouverneurs, et de Zabulon sont venus ceux qui tiennent le bâton du commandant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Et les princes d’Issacar ont été avec Debora, et Issacar, comme Barak; [il a été] envoyé sur ses pas dans la vallée. Aux divisions de Ruben, grandes considérations de cœur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Pourquoi es-tu resté entre les barres des étables, à écouter le bêlement des troupeaux? Aux divisions de Ruben, grandes délibérations de cœur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Galaad est demeuré au-delà du Jourdain; et Dan, pourquoi a-t-il séjourné sur les navires? Aser est resté au bord de la mer, et il est demeuré dans ses ports.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zabulon est un peuple qui a exposé son âme à la mort, Nephthali aussi, sur les hauteurs des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Les rois sont venus, ils ont combattu; alors les rois de Canaan ont combattu à Thaanac, près des eaux de Meguiddo; [mais], de butin d’argent, ils n’en ont pas emporté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'On a combattu des cieux; du chemin qu’elles parcourent, les étoiles ont combattu contre Sisera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Le torrent de Kison les a emportés, le torrent des anciens temps, le torrent de Kison. Mon âme, tu as foulé aux pieds la force!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Alors les talons des chevaux battirent [le sol] à cause de la course rapide, de la course rapide de leurs [hommes] vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Maudissez Méroz, dit l’Ange de l’ Éternel; maudissez, maudissez ses habitants! car ils ne sont pas venus au secours de l’ Éternel, au secours de l’ Éternel, avec les hommes forts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Bénie soit, au-dessus des femmes, Jaël, femme de Héber, le Kénien! Qu’elle soit bénie au-dessus des femmes qui se tiennent dans les tentes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Il a demandé de l’eau, elle lui a donné du lait; dans la coupe des nobles elle lui a présenté du caillé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Elle a étendu sa main vers le pieu, et sa droite vers le marteau des ouvriers; elle a frappé Sisera, elle lui a brisé la tête, elle lui a fracassé et transpercé la tempe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Entre ses pieds il s’est courbé, il est tombé, il s’est étendu [par terre]; entre ses pieds il s’est courbé, il est tombé; là où il s’est courbé, là il est tombé anéanti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'La mère de Sisera regarde par la fenêtre, et s’écrie à travers le treillis: Pourquoi son char tarde-t-il à venir? Pourquoi la marche de ses chars est-elle si lente?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Les sages d’entre ses princesses lui répondent; elle s’est donné la réponse à elle-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'N’ont-ils pas trouvé, n’ont-ils pas divisé le butin? Une jeune fille, deux jeunes filles par tête d’homme; du butin de vêtements de couleur pour Sisera, du butin de vêtements de couleur brodés, deux vêtements de couleur brodés, pour le cou des captives!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Qu’ainsi périssent tous tes ennemis, ô Éternel! mais que ceux qui t’aiment soient comme le soleil quand il sort dans sa force! Et le pays fut en repos 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, '*Et les fils d’Israël firent ce qui est mauvais aux yeux de l’ Éternel; et l’ Éternel les livra en la main de Madian pendant sept ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Et la main de Madian fut forte sur Israël. À cause de Madian, les fils d’Israël se firent les antres qui sont dans les montagnes, et les cavernes, et les lieux forts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Et il arrivait que, quand Israël avait semé, Madian montait, et Amalek et les fils de l’orient; et ils montaient contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Et ils campaient contre eux, et détruisaient les produits du pays jusqu’à ce que tu viennes à Gaza, et ils ne laissaient point de vivres en Israël, ni mouton, ni bœuf, ni âne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Car ils montaient, eux et leurs troupeaux et leurs tentes; ils venaient nombreux comme des sauterelles; et eux et leurs chameaux étaient sans nombre; et ils venaient dans le pays pour le ravager.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Et Israël fut très appauvri à cause de Madian; et les fils d’Israël crièrent à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Et il arriva que, lorsque les fils d’Israël crièrent à l’ Éternel à cause de Madian,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'l’ Éternel envoya aux fils d’Israël un prophète qui leur dit: Ainsi dit l’ Éternel, le Dieu d’Israël: Je vous ai fait monter d’Égypte, et je vous ai fait sortir de la maison de servitude,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'et je vous ai délivrés de la main des Égyptiens et de la main de tous vos oppresseurs; et je les ai chassés de devant vous, et je vous ai donné leur pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Et je vous ai dit: Moi, je suis l’ Éternel, votre Dieu; vous ne craindrez point les dieux de l’Amoréen, dans le pays duquel vous habitez. Et vous n’avez pas écouté ma voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Et un ange de l’ Éternel vint, et s’assit sous le térébinthe qui est à Ophra, lequel était à Joas, l’Abiézerite. Et Gédéon, son fils, battait du froment dans le pressoir, pour le mettre en sûreté de devant Madian.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Et l’Ange de l’ Éternel lui apparut, et lui dit: L’ Éternel est avec toi, fort et vaillant homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Et Gédéon lui dit: Ah! mon seigneur, si l’ Éternel est avec nous, pourquoi donc toutes ces choses nous sont-elles arrivées? Et où sont toutes ses merveilles que nos pères nous ont racontées, en disant: L’ Éternel ne nous a-t-il pas fait monter hors d’Égypte? Et maintenant l’ Éternel nous a abandonnés, et nous a livrés en la main de Madian.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Et l’ Éternel le regarda, et [lui] dit: Va avec cette force que tu as, et tu sauveras Israël de la main de Madian. Ne t’ai-je pas envoyé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, '– Et il lui dit: Ah! Seigneur, avec quoi sauverai-je Israël? Voici, mon millier est le plus pauvre en Manassé, et moi je suis le plus petit dans la maison de mon père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Et l’ Éternel lui dit: Moi je serai avec toi; et tu frapperas Madian comme un seul homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Et il lui dit: Je te prie, si j’ai trouvé grâce à tes yeux, donne-moi un signe que c’est toi qui parles avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Ne te retire pas d’ici, je te prie, jusqu’à ce que je vienne à toi, et que j’apporte mon présent et que je le dépose devant toi. Et il dit: Je m’assiérai jusqu’à ce que tu reviennes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Et Gédéon entra, et apprêta un chevreau et des pains sans levain d’un épha de farine; il mit la chair dans un panier et mit le bouillon dans un pot, et les lui apporta sous le térébinthe, et les présenta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Et l’Ange de Dieu lui dit: Prends la chair et les pains sans levain, et pose-les sur ce rocher-là, et verse le bouillon. Et il fit ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Et l’Ange de l’ Éternel étendit le bout du bâton qu’il avait en sa main, et toucha la chair et les pains sans levain; et le feu monta du rocher et consuma la chair et les pains sans levain. Et l’Ange de l’ Éternel s’en alla de devant ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Et Gédéon vit que c’était un ange de l’ Éternel, et Gédéon dit: Ah! Seigneur Éternel, si c’est pour cela que j’ai vu l’Ange de l’ Éternel face à face!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Et l’ Éternel lui dit: Paix te soit; ne crains point, tu ne mourras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Et Gédéon bâtit là un autel à l’ Éternel, et l’appela Jéhovah-Shalom. Jusqu’à ce jour il est encore à Ophra des Abiézerites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Et il arriva, en cette nuit-là, que l’ Éternel lui dit: Prends le jeune taureau qui est à ton père et le second taureau de sept ans; et tu renverseras l’autel de Baal qui est à ton père, et tu couperas l’ashère qui est auprès;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'et tu bâtiras un autel à l’ Éternel, ton Dieu, sur le sommet de ce lieu fort, avec l’arrangement [convenable]. Et tu prendras le second taureau, et tu l’offriras en holocauste sur le bois de l’ashère que tu auras coupée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Et Gédéon prit dix hommes d’entre ses serviteurs, et fit comme l’ Éternel lui avait dit; et comme, à le faire de jour, il craignait la maison de son père et les hommes de la ville, il le fit de nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Et quand les hommes de la ville se levèrent de bonne heure le matin, voici, l’autel de Baal était démoli, et l’ashère qui était auprès était coupée, et le second taureau était offert sur l’autel qui avait été bâti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Et ils se dirent l’un à l’autre: Qui a fait cela? Et ils s’enquirent et cherchèrent, et dirent: Gédéon, fils de Joas, a fait cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Et les hommes de la ville dirent à Joas: Fais sortir ton fils, et qu’il meure; car il a démoli l’autel de Baal et a coupé l’ashère qui était auprès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Et Joas dit à tous ceux qui se tenaient près de lui: Est-ce vous qui plaiderez pour Baal? Est-ce vous qui le sauverez? Celui qui plaide pour lui, qu’il soit mis à mort, d’ici au matin. S’il est dieu, qu’il plaide pour lui-même, car on a démoli son autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Et en ce jour on appela Gédéon Jerubbaal, en disant: Que Baal plaide contre lui, car il a démoli son autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Et tout Madian, et Amalek, et les fils de l’orient, se réunirent ensemble et passèrent [le Jourdain], et campèrent dans la vallée de Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Et l’Esprit de l’ Éternel revêtit Gédéon, et il sonna de la trompette, et les Abiézerites furent assemblés à sa suite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Et il envoya des messagers par tout Manassé, et eux aussi furent assemblés à sa suite; et il envoya des messagers à Aser, et à Zabulon, et à Nephthali; et ils montèrent à leur rencontre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Et Gédéon dit à Dieu: Si tu veux sauver Israël par ma main, comme tu l’as dit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'voici, je mets une toison de laine dans l’aire: si la rosée est sur la toison seule, et que la sécheresse soit sur toute la terre, alors je connaîtrai que tu sauveras Israël par ma main, comme tu l’as dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Et il arriva ainsi. Et il se leva de bonne heure le lendemain, et il pressa la toison et exprima la rosée de la toison, plein une coupe d’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Et Gédéon dit à Dieu: Que ta colère ne s’embrase pas contre moi, et je parlerai seulement cette fois: encore une seule fois, je te prie, je ferai un essai avec la toison; je te prie qu’il n’y ait de la sécheresse que sur la toison, et que sur toute la terre il y ait de la rosée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Et Dieu fit ainsi cette nuit-là: et la sécheresse fut sur la toison seule, et sur toute la terre il y eut de la rosée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Et Jerubbaal, qui est Gédéon, se leva de bonne heure, et tout le peuple qui était avec lui, et ils campèrent près de la source de Harod; et il avait le camp de Madian au nord, du côté de la colline de Moré, dans la vallée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Et l’ Éternel dit à Gédéon: Le peuple qui est avec toi est trop nombreux, pour que je livre Madian en leur main, de peur qu’Israël ne se glorifie contre moi, disant: Ma main m’a sauvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Et maintenant, crie aux oreilles du peuple, disant: Quiconque est peureux et tremble, qu’il s’en retourne et s’éloigne de la montagne de Galaad. Et 22 000 [hommes] du peuple s’en retournèrent; et il en resta 10 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Et l’ Éternel dit à Gédéon: Le peuple est encore nombreux; fais-les descendre vers l’eau, et là je te les épurerai; et il arrivera que celui dont je te dirai: Celui-ci ira avec toi, celui-là ira avec toi; et que chacun de qui je te dirai: Celui-ci n’ira pas avec toi, celui-là n’ira pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Et il fit descendre le peuple vers l’eau. Et l’ Éternel dit à Gédéon: Quiconque lapera l’eau avec sa langue, comme lape le chien, tu le mettras à part, et aussi tous ceux qui se courberont sur leurs genoux pour boire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Et le nombre de ceux qui lapèrent dans leur main [en la portant] à leur bouche, fut de 300 hommes; et tout le reste du peuple se courba sur ses genoux pour boire l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Et l’ Éternel dit à Gédéon: Par les 300 hommes qui ont lapé [l’eau] je vous sauverai, et je livrerai Madian en ta main; mais que tout le peuple s’en aille, chacun en son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Et les [300 hommes] prirent en leurs mains les vivres du peuple et ses trompettes. Et [Gédéon] renvoya tous les hommes d’Israël, chacun à sa tente, et retint les 300 hommes. Or le camp de Madian était au-dessous de lui, dans la vallée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Et il arriva, cette nuit-là, que l’ Éternel lui dit: Lève-toi; descends au camp, car je l’ai livré en ta main;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'et si tu crains d’y descendre, descends vers le camp, toi et Pura, ton jeune homme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'et tu entendras ce qu’ils diront, et ensuite tes mains seront fortifiées et tu descendras au camp. Et il descendit, lui et Pura, son jeune homme, aux avant-postes des hommes armés qui étaient dans le camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Et Madian et Amalek et tous les fils de l’orient s’étendaient dans la vallée, nombreux comme des sauterelles; et leurs chameaux étaient sans nombre, en multitude comme le sable qui est sur le bord de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Et Gédéon arriva, et voici, un homme racontait un songe à son compagnon; et il disait: Voici, j’ai songé un songe; et voici, un gâteau de pain d’orge roulait dans le camp de Madian, et il arriva jusqu’à la tente et la heurta, et elle tomba; et il la retourna sens dessus dessous, et la tente était là renversée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Et son compagnon répondit et dit: Ce n’est pas autre chose que l’épée de Gédéon, fils de Joas, homme d’Israël: Dieu a livré Madian et tout le camp en sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Et il arriva que, lorsque Gédéon entendit le récit du songe et son interprétation, il se prosterna. Et il retourna au camp d’Israël, et dit: Levez-vous, car l’ Éternel a livré le camp de Madian en votre main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Et il divisa les 300 hommes en trois corps, et il leur mit à tous des trompettes à la main, et des cruches vides, et des torches dans les cruches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Et il leur dit: Regardez ce que je vais faire, et faites de même; voici, quand j’arriverai au bout du camp, alors ce que je ferai, vous le ferez de même;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'et quand je sonnerai de la trompette, moi et tous ceux qui sont avec moi, vous aussi vous sonnerez des trompettes autour de tout le camp, et vous direz: Pour l’ Éternel et pour Gédéon!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Et Gédéon et les 100 hommes qui étaient avec lui arrivèrent au bout du camp, au commencement de la veille du milieu [de la nuit]; on venait seulement de placer les gardes. Et ils sonnèrent des trompettes, et brisèrent les cruches qu’ils avaient à la main;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'et les trois corps sonnèrent des trompettes, et brisèrent les cruches: ils tenaient dans leur main gauche les torches, et dans leur main droite les trompettes pour sonner, et criaient: L’épée de l’ Éternel et de Gédéon!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Et ils se tenaient chacun à sa place autour du camp; et tout le camp se mit à courir, et à pousser des cris, et à fuir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Et les 300 hommes sonnaient des trompettes; et l’ Éternel tourna l’épée de chacun contre son compagnon, dans tout le camp. Et le camp s’enfuit jusqu’à Beth-Sitta, vers Tseréra, jusqu’au bord d’Abel-Mehola, près de Tabbath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Et les hommes d’Israël se rassemblèrent, de Nephthali, et d’Aser, et de tout Manassé, et poursuivirent Madian.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Et Gédéon envoya des messagers dans toute la montagne d’Éphraïm, pour dire: Descendez à la rencontre de Madian, et enlevez-leur les eaux jusqu’à Beth-Bara, et le Jourdain. Et tous les hommes d’Éphraïm se rassemblèrent, et s’emparèrent des eaux jusqu’à Beth-Bara, et du Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Et ils prirent les deux princes de Madian, Oreb et Zeëb; et ils tuèrent Oreb au rocher d’Oreb, et ils tuèrent Zeëb au pressoir de Zeëb. Et ils poursuivirent Madian, et apportèrent les têtes d’Oreb et de Zeëb, à Gédéon, de l’autre côté du Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Et les hommes d’Éphraïm lui dirent: Que nous as-tu fait, de ne pas nous avoir appelés lorsque tu es allé faire la guerre contre Madian? Et ils contestèrent fortement avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Et il leur dit: Qu’ai-je fait maintenant en comparaison de vous? Les grappillages d’Éphraïm ne sont-ils pas meilleurs que la vendange d’Abiézer?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Dieu a livré en votre main les princes de Madian, Oreb et Zeëb; et qu’ai-je pu faire en comparaison de vous? Alors leur esprit s’apaisa envers lui, quand il [leur] eut dit cette parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Et Gédéon vint au Jourdain, [et] le passa, lui et les 300 hommes qui étaient avec lui, fatigués, mais poursuivant toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Et il dit aux hommes de Succoth: Donnez, je vous prie, des pains au peuple qui me suit, car ils sont fatigués; et je poursuis Zébakh et Tsalmunna, rois de Madian.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Et les principaux de Succoth dirent: La paume de Zébakh et celle de Tsalmunna sont-elles déjà en ta main, que nous donnions du pain à ton armée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Et Gédéon dit: À cause de cela, dès que l’ Éternel aura livré Zébakh et Tsalmunna en ma main, je broierai votre chair avec des épines du désert et avec des chardons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Et de là il monta à Penuel, et leur parla de la même manière. Et les hommes de Penuel lui répondirent comme les hommes de Succoth avaient répondu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Et il parla de même aux hommes de Penuel, en disant: Quand je reviendrai en paix, je démolirai cette tour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Et Zébakh et Tsalmunna étaient à Karkor, et leurs camps avec eux, environ 15 000 [hommes], tous ceux qui restaient de tout le camp des fils de l’orient; car il en était tombé 120 000 hommes tirant l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Et Gédéon monta par le chemin de ceux qui habitent dans les tentes, à l’orient de Nobakh et de Jogbeha, et il frappa le camp; et le camp était en sécurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Et Zébakh et Tsalmunna s’enfuirent, et il les poursuivit, et prit les deux rois de Madian, Zébakh et Tsalmunna, et mit tout leur camp en déroute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Et Gédéon, fils de Joas, revint de la bataille, de la montée de Hérès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Et il saisit un jeune garçon d’entre les hommes de Succoth, et l’interrogea; et le [garçon] lui mit par écrit les principaux de Succoth et ses anciens, 77 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Et il vint vers les hommes de Succoth, et dit: Voici Zébakh et Tsalmunna, au sujet desquels vous m’avez insulté, disant: La paume de Zébakh et celle de Tsalmunna sont-elles déjà en ta main, que nous donnions du pain à tes hommes fatigués?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Et il prit les anciens de la ville, et des épines du désert et des chardons, et enseigna par eux les hommes de Succoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Et il démolit la tour de Penuel, et tua les hommes de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Et il dit à Zébakh et à Tsalmunna: Comment étaient les hommes que vous avez tués à Thabor? Et ils dirent: Comme toi, tels ils étaient; chacun d’eux comme la figure d’un fils de roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Et il dit: C’étaient mes frères, fils de ma mère. L’ Éternel est vivant, si vous les aviez laissés vivre, je ne vous tuerais pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Et il dit à Jéther, son premier-né: Lève-toi, tue-les. Mais le jeune garçon ne tirait pas son épée, parce qu’il avait peur, car il était encore un jeune garçon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Et Zébakh et Tsalmunna dirent: Lève-toi, toi-même, et jette-toi sur nous; car tel qu’est l’homme, telle est sa force. Et Gédéon se leva et tua Zébakh et Tsalmunna, et prit les petites lunes qui étaient aux cous de leurs chameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Et les hommes d’Israël dirent à Gédéon: Domine sur nous, et toi et ton fils, et le fils de ton fils; car tu nous as sauvés de la main de Madian.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Et Gédéon leur dit: Je ne dominerai point sur vous, et mon fils ne dominera point sur vous; l’ Éternel dominera sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Et Gédéon leur dit: Je vous ferai une demande: Donnez-moi chacun de vous les anneaux de son butin. Car [les Madianites] avaient des anneaux d’or, parce qu’ils étaient Ismaélites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Et ils dirent: Nous les donnerons volontiers. Et ils étendirent un manteau, et y jetèrent chacun les anneaux de son butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Et le poids des anneaux d’or qu’il avait demandés fut de 1 700 [sicles] d’or, sans les petites lunes, et les pendants d’oreille, et les vêtements de pourpre dont étaient couverts les rois de Madian, et sans les colliers qui étaient aux cous de leurs chameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Et Gédéon en fit un éphod, et le mit dans sa ville, dans Ophra; et tout Israël se prostitua là après celui-ci; et cela devint un piège pour Gédéon et pour sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Et Madian fut humilié devant les fils d’Israël; et il ne leva plus sa tête. Et le pays fut en repos 40 ans, aux jours de Gédéon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Et Jerubbaal, fils de Joas, s’en alla, et habita dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Et Gédéon eut 70 fils, issus de ses reins, car il eut beaucoup de femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Et sa concubine qui était à Sichem, elle aussi, lui enfanta un fils; et il lui donna le nom d’Abimélec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Et Gédéon, fils de Joas, mourut dans une bonne vieillesse, et fut enterré dans le sépulcre de Joas, son père, à Ophra des Abiézerites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Et quand Gédéon fut mort, il arriva que les fils d’Israël retournèrent et se prostituèrent après les Baals, et ils s’établirent Baal-Berith pour dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Et les fils d’Israël ne se souvinrent pas de l’ Éternel, leur Dieu, qui les avait délivrés de la main de tous leurs ennemis tout à l’entour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'et ils n’usèrent pas de bonté envers la maison de Jerubbaal, [qui est] Gédéon, selon tout le bien qu’il avait fait à Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, '*Et Abimélec, fils de Jerubbaal, alla à Sichem, vers les frères de sa mère, et leur parla, et à toute la famille de la maison du père de sa mère, en disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Dites, je vous prie, aux oreilles de tous les hommes de Sichem: Lequel est le meilleur pour vous, que 70 hommes, tous fils de Jerubbaal, dominent sur vous, ou qu’un seul homme domine sur vous? Et souvenez-vous que je suis votre os et votre chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Et les frères de sa mère dirent de lui toutes ces paroles aux oreilles de tous les hommes de Sichem; et leur cœur fut incliné vers Abimélec, car ils dirent: Il est notre frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Et ils lui donnèrent 70 [pièces] d’argent tirées de la maison de Baal-Berith; et Abimélec loua avec elles des hommes légers et téméraires, et ils le suivirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Et il vint à la maison de son père, à Ophra, et tua sur une seule pierre ses frères, les fils de Jerubbaal, 70 hommes; mais Jotham, le plus jeune fils de Jerubbaal, demeura de reste, car il s’était caché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Et tous les hommes de Sichem s’assemblèrent, et toute la maison de Millo, et ils allèrent, et établirent roi Abimélec, près du chêne du monument qui est à Sichem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Et on le rapporta à Jotham. Et il s’en alla, et se tint sur le sommet de la montagne de Garizim; et il éleva sa voix et cria, et leur dit: Écoutez-moi, hommes de Sichem, et Dieu vous écoutera!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Les arbres allèrent pour oindre un roi sur eux; et ils dirent à l’olivier: Règne sur nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Et l’olivier leur dit: Laisserais-je ma graisse, par laquelle on honore par moi Dieu et les hommes, et irais-je m’agiter pour les arbres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Et les arbres dirent au figuier: Viens, toi, règne sur nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Et le figuier leur dit: Laisserais-je ma douceur et mon bon fruit, et irais-je m’agiter pour les arbres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Et les arbres dirent à la vigne: Viens, toi, règne sur nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Et la vigne leur dit: Laisserais-je mon moût, qui réjouit Dieu et les hommes, et irais-je m’agiter pour les arbres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Et tous les arbres dirent à l’épine: Viens, toi, règne sur nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Et l’épine dit aux arbres: Si vraiment vous voulez m’oindre roi sur vous, venez, mettez votre confiance en mon ombre; sinon, un feu sortira de l’épine, et dévorera les cèdres du Liban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, '– Et maintenant, si vous avez agi avec vérité et en intégrité en établissant roi Abimélec, et si vous avez bien fait envers Jerubbaal et envers sa maison, et si vous lui avez fait selon les actes de ses mains;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, '(car mon père a combattu pour vous, et a exposé sa vie, et vous a délivrés de la main de Madian;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, '– et vous vous êtes levés aujourd’hui contre la maison de mon père, et vous avez tué ses fils, 70 hommes, sur une seule pierre, et vous avez établi roi Abimélec, fils de sa servante, sur les hommes de Sichem, parce qu’il est votre frère);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'si donc vous avez agi aujourd’hui avec vérité et en intégrité envers Jerubbaal et envers sa maison, réjouissez-vous en Abimélec, et que lui aussi se réjouisse en vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'sinon, qu’un feu sorte d’Abimélec, et qu’il dévore les hommes de Sichem et la maison de Millo; et qu’un feu sorte des hommes de Sichem et de la maison de Millo, et qu’il dévore Abimélec!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Et Jotham s’échappa et s’enfuit, et alla à Beër, et y habita, à cause d’Abimélec son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Et Abimélec fut prince sur Israël, trois ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Et Dieu envoya un mauvais esprit entre Abimélec et les hommes de Sichem; et les hommes de Sichem agirent perfidement envers Abimélec,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'afin que la violence commise sur les 70 fils de Jerubbaal vienne [sur lui], et que leur sang soit mis sur Abimélec, leur frère, qui les avait tués, et sur les hommes de Sichem, qui avaient fortifié ses mains pour tuer ses frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Et les hommes de Sichem placèrent contre lui des gens en embuscade sur les sommets des montagnes, et ils pillaient tous ceux qui passaient près d’eux sur le chemin; et cela fut rapporté à Abimélec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Et Gaal, fils d’Ébed, vint avec ses frères, et ils passèrent à Sichem; et les hommes de Sichem eurent confiance en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Et ils sortirent aux champs, et vendangèrent leurs vignes, et foulèrent [le raisin], et firent joyeuse fête, et entrèrent dans la maison de leur dieu, et mangèrent et burent, et maudirent Abimélec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Et Gaal, fils d’Ébed, dit: Qui est Abimélec, et qui est Sichem, que nous le servions? N’est-il pas fils de Jerubbaal? et Zebul n’est-il pas son lieutenant? Servez les hommes de Hamor, père de Sichem! Mais nous, pourquoi le servirions-nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Oh! que n’ai-je ce peuple sous ma main, et j’ôterais Abimélec! Et il dit d’Abimélec: Augmente ton armée, et sors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Et Zebul, chef de la ville, entendit les paroles de Gaal, fils d’Ébed, et sa colère s’embrasa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Et il envoya astucieusement des messagers à Abimélec, disant: Voici, Gaal, fils d’Ébed, et ses frères, sont venus à Sichem; et voici, ils ferment la ville contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Et maintenant, lève-toi de nuit, toi et le peuple qui est avec toi, et mets-toi en embuscade dans la campagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Et, le matin, tu te lèveras de bonne heure, au lever du soleil, et tu fondras sur la ville; et voici, Gaal et le peuple qui est avec lui sortiront contre toi, et tu lui feras selon ce que ta main rencontrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Et Abimélec se leva de nuit, et tout le peuple qui était avec lui, et ils se mirent en embuscade contre Sichem, en quatre corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Et Gaal, fils d’Ébed, sortit, et se tint à l’entrée de la porte de la ville; et Abimélec et le peuple qui était avec lui se levèrent de l’embuscade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Et Gaal vit le peuple, et il dit à Zebul: Voici du peuple qui descend du sommet des montagnes. Et Zebul lui dit: C’est l’ombre des montagnes, que tu vois comme des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Et Gaal parla encore, et dit: Voici du peuple qui descend du haut du pays, et un corps vient par le chemin du chêne des pronostiqueurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Et Zebul lui dit: Où est maintenant ta bouche, toi qui disais: Qui est Abimélec, que nous le servions? N’est-ce pas là le peuple que tu as méprisé? Sors maintenant, je te prie, et combats contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Et Gaal sortit devant les hommes de Sichem, et combattit contre Abimélec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Et Abimélec le poursuivit, et il s’enfuit devant lui, et un grand nombre tombèrent tués jusqu’à l’entrée de la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Et Abimélec resta à Aruma; et Zebul chassa Gaal et ses frères, de sorte qu’ils ne demeurèrent plus à Sichem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Et il arriva le lendemain que le peuple sortit dans la campagne; et cela fut rapporté à Abimélec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Et il prit ses gens, et les divisa en trois corps, et les mit en embuscade dans la campagne. Et il regarda, et voici, le peuple sortait de la ville: et il se leva contre eux et les frappa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Et Abimélec et les corps qui étaient avec lui se précipitèrent, et se tinrent à l’entrée de la porte de la ville, et deux des corps se précipitèrent sur tous ceux qui étaient dans la campagne et les frappèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Et Abimélec combattit tout ce jour-là contre la ville; et il prit la ville, et tua le peuple qui y était; et il démolit la ville, et y sema du sel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Et tous les hommes de la tour de Sichem apprirent cela, et ils entrèrent dans le donjon de la maison du dieu Berith.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Et on rapporta à Abimélec que tous les hommes de la tour de Sichem s’étaient rassemblés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Et Abimélec monta sur la montagne de Tsalmon, lui et tout le peuple qui était avec lui. Et Abimélec prit des haches avec lui et coupa une branche d’arbre, et l’enleva, et la mit sur son épaule, et dit au peuple qui était avec lui: Ce que vous m’avez vu faire, hâtez-vous, faites-le comme moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Et tout le peuple aussi coupa chacun sa branche; et ils suivirent Abimélec, et mirent [les branches] contre le donjon, et ils brûlèrent par le feu le donjon sur eux. Et tous les hommes de la tour de Sichem moururent aussi, un millier d’hommes et de femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Et Abimélec s’en alla à Thébets, et campa contre Thébets et la prit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Et il y avait une tour forte au milieu de la ville; et tous les hommes et toutes les femmes s’y enfuirent, tous les hommes de la ville; et ils fermèrent derrière eux, et montèrent sur le toit de la tour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Et Abimélec vint jusqu’à la tour, et l’attaqua; et il s’avança jusqu’à l’entrée de la tour pour la brûler par le feu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'et une femme jeta sur la tête d’Abimélec une meule tournante, et lui brisa le crâne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Et il appela en hâte le jeune homme qui portait ses armes, et lui dit: Tire ton épée et tue-moi, de peur qu’on ne dise de moi: Une femme l’a tué. Et son jeune homme le transperça, et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Et quand les hommes d’Israël virent qu’Abimélec était mort, ils s’en allèrent chacun en son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Et Dieu fit retomber sur Abimélec le mal qu’il avait fait à son père en tuant ses 70 frères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'et tout le mal des hommes de Sichem, Dieu le fit retomber sur leurs têtes; et la malédiction de Jotham, fils de Jerubbaal, vint sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, '*Et après Abimélec, Thola, fils de Pua, fils de Dodo, homme d’Issacar, se leva pour sauver Israël; et il habitait à Shamir, dans la montagne d’Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Et il jugea Israël 23 ans; et il mourut, et fut enterré à Shamir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Et après lui, se leva Jaïr, le Galaadite; et il jugea Israël 22 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Et il avait 30 fils, qui montaient sur 30 ânons; et ils avaient 30 villes qu’on a nommées jusqu’à aujourd’hui les bourgs de Jaïr, lesquels sont dans le pays de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Et Jaïr mourut, et fut enterré à Kamon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, '*Et les fils d’Israël firent de nouveau ce qui est mauvais aux yeux de l’ Éternel, et ils servirent les Baals, et les Ashtoreths, et les dieux de Syrie, et les dieux de Sidon, et les dieux de Moab, et les dieux des fils d’Ammon, et les dieux des Philistins; et ils abandonnèrent l’ Éternel et ne le servirent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Et la colère de l’ Éternel s’embrasa contre Israël, et il les vendit en la main des Philistins et en la main des fils d’Ammon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'qui opprimèrent et écrasèrent les fils d’Israël cette année-là; pendant 18 ans [ils écrasèrent] tous les fils d’Israël qui étaient au-delà du Jourdain, dans le pays des Amoréens, qui est en Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Et les fils d’Ammon passèrent le Jourdain pour faire la guerre aussi contre Juda et contre Benjamin, et contre la maison d’Éphraïm. Et Israël fut dans une grande détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Et les fils d’Israël crièrent à l’ Éternel, disant: Nous avons péché contre toi; car nous avons abandonné notre Dieu, et nous avons servi les Baals.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Et l’ Éternel dit aux fils d’Israël: [Ne vous ai-je] pas [délivrés] des Égyptiens, et des Amoréens, des fils d’Ammon, et des Philistins?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Et les Sidoniens, et Amalek, et Maon, vous ont opprimés, et vous avez crié vers moi, et je vous ai sauvés de leur main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Mais vous, vous m’avez abandonné, et vous avez servi d’autres dieux; c’est pourquoi je ne vous sauverai plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Allez, et criez aux dieux que vous avez choisis; eux, vous sauveront au temps de votre détresse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Et les fils d’Israël dirent à l’ Éternel: Nous avons péché; fais-nous selon tout ce qui sera bon à tes yeux; seulement, nous te prions, délivre-nous ce jour-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Et ils ôtèrent du milieu d’eux les dieux étrangers, et servirent l’ Éternel; et son âme fut en peine de la misère d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Et les fils d’Ammon se rassemblèrent, et campèrent en Galaad; et les fils d’Israël s’assemblèrent, et campèrent à Mitspa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Et le peuple, les princes de Galaad, se dirent l’un à l’autre: Quel est l’homme qui commencera à faire la guerre contre les fils d’Ammon? Il sera chef de tous les habitants de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Or Jephthé, le Galaadite, était un fort et vaillant homme, et il était fils d’une prostituée; et Galaad avait engendré Jephthé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Et la femme de Galaad lui enfanta des fils; et les fils de sa femme grandirent, et chassèrent Jephthé, et lui dirent: Tu n’auras point d’héritage dans la maison de notre père; car toi, tu es fils d’une autre femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Et Jephthé s’enfuit de devant ses frères, et habita dans le pays de Tob; et des hommes légers se ramassèrent autour de Jephthé, et ils entraient en campagne avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Et il arriva, quelque temps après, que les fils d’Ammon firent la guerre à Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'et comme les fils d’Ammon faisaient la guerre à Israël, les anciens de Galaad allèrent pour amener Jephthé du pays de Tob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Et ils dirent à Jephthé: Viens, et tu seras notre capitaine, et nous combattrons contre les fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Et Jephthé dit aux anciens de Galaad: N’est-ce pas vous qui m’avez haï et qui m’avez chassé de la maison de mon père? Et pourquoi venez-vous à moi, maintenant que vous êtes dans la détresse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Et les anciens de Galaad dirent à Jephthé: C’est pour ceci que nous sommes maintenant revenus vers toi, afin que tu viennes avec nous, et que tu fasses la guerre contre les fils d’Ammon; et tu seras notre chef, à nous tous, les habitants de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Et Jephthé dit aux anciens de Galaad: Si vous me ramenez pour faire la guerre contre les fils d’Ammon et que l’ Éternel les livre devant moi, serai-je votre chef?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Et les anciens de Galaad dirent à Jephthé: L’ Éternel est témoin entre nous si nous ne faisons pas selon ce que tu as dit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Et Jephthé alla avec les anciens de Galaad, et le peuple l’établit chef et capitaine sur lui. Et Jephthé prononça toutes ses paroles devant l’ Éternel, à Mitspa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Et Jephthé envoya des messagers au roi des fils d’Ammon, disant: Qu’y a-t-il entre moi et toi, que tu viennes contre moi pour faire la guerre à mon pays?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Et le roi des fils d’Ammon dit aux messagers de Jephthé: C’est parce qu’Israël a pris mon pays, quand il monta d’Égypte, depuis l’Arnon jusqu’au Jabbok et jusqu’au Jourdain; et maintenant, rends-moi ces [contrées] en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Et Jephthé envoya de nouveau des messagers au roi des fils d’Ammon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'et lui dit: Ainsi dit Jephthé: Israël n’a point pris le pays de Moab ni le pays des fils d’Ammon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'car, quand ils montèrent d’Égypte, Israël marcha par le désert jusqu’à la mer Rouge, et il vint à Kadès;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'et Israël envoya des messagers au roi d’Édom, disant: Laisse-moi passer par ton pays; mais le roi d’Édom n’écouta pas. Et il envoya aussi au roi de Moab; mais il ne voulut pas. Et Israël demeura à Kadès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Et il marcha par le désert, et tourna le pays d’Édom et le pays de Moab, et vint du côté du soleil levant au pays de Moab, et ils campèrent au-delà de l’Arnon, mais n’entrèrent pas dans les limites de Moab, car l’Arnon était la limite de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Et Israël envoya des messagers à Sihon, roi des Amoréens, roi de Hesbon, et Israël lui dit: Laisse-nous passer par ton pays, jusqu’en notre lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Mais Sihon ne se fia pas à Israël pour le laisser passer par ses limites; et Sihon rassembla tout son peuple, et ils campèrent à Jahtsa, et combattirent contre Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Et l’ Éternel, le Dieu d’Israël, livra Sihon et tout son peuple en la main d’Israël, et [Israël] les frappa; et Israël prit possession de tout le pays des Amoréens qui habitaient dans ce pays-là:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'et ils eurent la possession de tout le territoire des Amoréens, depuis l’Arnon jusqu’au Jabbok, et depuis le désert jusqu’au Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Et maintenant l’ Éternel, le Dieu d’Israël, a dépossédé les Amoréens devant son peuple Israël, et toi, tu nous en déposséderais?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Ne possèdes-tu pas ce que ton dieu Kemosh t’a fait posséder? Et nous aurons la possession de tous ceux que l’ Éternel, notre Dieu, aura dépossédés devant nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Et maintenant, vaux-tu donc mieux que Balak, fils de Tsippor, roi de Moab? A-t-il jamais contesté contre Israël? a-t-il jamais combattu contre eux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Pendant qu’Israël a habité Hesbon et les villages de son ressort, et Aroër et les villages de son ressort, et toutes les villes qui sont le long de l’Arnon, pendant 300 ans, pourquoi ne les avez-vous pas délivrées en ce temps-là?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Et ce n’est pas moi qui ai péché contre toi; mais c’est toi qui me fais tort, en m’attaquant. L’ Éternel, le juge, jugera aujourd’hui entre les fils d’Israël et les fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Et le roi des fils d’Ammon n’écouta pas les paroles que Jephthé lui avait envoyées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Et l’Esprit de l’ Éternel fut sur Jephthé; et il passa à travers Galaad et Manassé, et il passa par Mitspé de Galaad, et de Mitspé de Galaad, il passa vers les fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Et Jephthé voua un vœu à l’ Éternel, et dit: Si tu livres en ma main les fils d’Ammon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'il arrivera que ce qui sortira des portes de ma maison à ma rencontre, lorsque je reviendrai en paix des fils d’Ammon, sera à l’ Éternel, et je l’offrirai en holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Et Jephthé passa vers les fils d’Ammon pour combattre contre eux; et l’ Éternel les livra en sa main:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'et il leur infligea une très grande défaite, depuis Aroër jusqu’à ce que tu viennes à Minnith, [leur prenant] 20 villes, et jusqu’à Abel-Keramim; et les fils d’Ammon furent humiliés devant les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Et Jephthé vint à Mitspa, dans sa maison; et voici, sa fille sortit à sa rencontre avec des tambourins et des danses; et elle était seule, unique: il n’avait, à part elle, ni fils ni fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Et il arriva, quand il la vit, qu’il déchira ses vêtements, et dit: Ah, ma fille! tu m’as accablé, et tu es de ceux qui me troublent! car j’ai ouvert [ma] bouche à l’ Éternel, et ne puis revenir en arrière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Et elle lui dit: Mon père, si tu as ouvert ta bouche à l’ Éternel, fais-moi selon ce qui est sorti de ta bouche, après que l’ Éternel t’a vengé de tes ennemis, les fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Et elle dit à son père: Que cette chose me soit faite: laisse-moi pendant deux mois, et je m’en irai, et je descendrai sur les montagnes, et je pleurerai ma virginité, moi et mes compagnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Et il lui dit: Va. Et il la renvoya pour deux mois. Et elle s’en alla, elle et ses compagnes, et pleura sa virginité sur les montagnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Et il arriva, au bout de deux mois, qu’elle revint vers son père; et il accomplit à son égard le vœu qu’il avait voué. Et elle n’avait point connu d’homme. Et ce fut une coutume en Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'que d’année en année les filles d’Israël allaient célébrer la fille de Jephthé, le Galaadite, quatre jours par année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, '*Et les hommes d’Éphraïm se rassemblèrent, et ils passèrent vers le nord, et dirent à Jephthé: Pourquoi as-tu passé pour combattre contre les fils d’Ammon, et ne nous as-tu pas appelés pour aller avec toi? Nous brûlerons au feu ta maison sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Et Jephthé leur dit: Nous avons eu de grands débats, moi et mon peuple, avec les fils d’Ammon; et je vous ai appelés, et vous ne m’avez pas sauvé de leur main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Et quand j’ai vu que vous ne me sauviez pas, j’ai mis ma vie dans ma main, et j’ai passé vers les fils d’Ammon; et l’ Éternel les a livrés en ma main. Et pourquoi êtes-vous montés contre moi en ce jour-ci, pour me faire la guerre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Et Jephthé rassembla tous les hommes de Galaad et fit la guerre à Éphraïm; et les hommes de Galaad frappèrent Éphraïm, parce qu’ils avaient dit: Vous, Galaad, vous êtes des fugitifs d’Éphraïm, au milieu d’Éphraïm, au milieu de Manassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Et Galaad enleva à Éphraïm les gués du Jourdain; et il arriva que, lorsqu’un des fuyards d’Éphraïm disait: Je veux passer, les hommes de Galaad lui disaient: Es-tu Éphraïmite? et il disait: Non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Alors ils lui disaient: Dis donc Shibboleth. Mais il disait Sibboleth, car il ne pouvait pas bien prononcer. Alors ils le saisissaient et l’égorgeaient aux gués du Jourdain. Et il tomba en ce temps-là 42 000 [hommes] d’Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Et Jephthé jugea Israël six ans. Et Jephthé, le Galaadite, mourut, et il fut enterré dans une des villes de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Et après lui, Ibtsan de Bethléhem jugea Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Et il eut 30 fils, et 30 filles qu’il envoya au-dehors, et il fit venir du dehors 30 filles pour ses fils. Et il jugea Israël sept ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Et Ibtsan mourut, et il fut enterré à Bethléhem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Et après lui, Élon, le Zabulonite, jugea Israël; et il jugea Israël dix ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Et Élon, le Zabulonite, mourut, et il fut enterré à Ajalon, dans le pays de Zabulon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Et après lui, Abdon, fils d’Hillel, le Pirhathonite, jugea Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Et il eut 40 fils et 30 petits-fils, qui montaient sur 70 ânons. Et il jugea Israël huit ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Et Abdon, fils d’Hillel, le Pirhathonite, mourut; et il fut enterré à Pirhathon, dans le pays d’Éphraïm, sur la montagne de l’Amalékite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, '*Et les fils d’Israël firent de nouveau ce qui est mauvais aux yeux de l’ Éternel; et l’ Éternel les livra en la main des Philistins pendant 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Et il y avait un homme de Tsorha, de la famille des Danites, et son nom était Manoah; et sa femme était stérile et n’enfantait pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Et l’Ange de l’ Éternel apparut à la femme, et lui dit: Voici, tu es stérile et tu n’enfantes pas; mais tu concevras, et tu enfanteras un fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Et maintenant, prends garde, je te prie, et ne bois ni vin ni boisson forte, et ne mange rien d’impur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'car voici, tu concevras, et tu enfanteras un fils; et le rasoir ne passera pas sur sa tête, car le jeune garçon sera nazaréen de Dieu dès le ventre [de sa mère]; et ce sera lui qui commencera à sauver Israël de la main des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Et la femme vint, et parla à son mari, disant: Un homme de Dieu est venu vers moi, et son aspect était comme l’aspect d’un ange de Dieu, très terrible; et je ne lui ai pas demandé d’où il était, et il ne m’a pas fait connaître son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Et il m’a dit: Voici, tu concevras, et tu enfanteras un fils; et maintenant, ne bois ni vin ni boisson forte, et ne mange rien d’impur; car le jeune garçon sera nazaréen de Dieu dès le ventre [de sa mère], jusqu’au jour de sa mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Et Manoah supplia l’ Éternel, et dit: Ah, Seigneur! que l’homme de Dieu que tu as envoyé, vienne encore vers nous, je te prie, et qu’il nous enseigne ce que nous devons faire au jeune garçon qui naîtra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Et Dieu exauça la voix de Manoah; et l’Ange de Dieu vint encore vers la femme, comme elle était assise aux champs, et Manoah, son mari, n’était pas avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Et la femme se hâta et courut et rapporta à son mari, et lui dit: Voici, l’homme qui était venu vers moi l’autre jour m’est apparu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Et Manoah se leva et suivit sa femme; et il vint vers l’homme, et lui dit: Es-tu l’homme qui a parlé à cette femme? Et il dit: [C’est] moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Et Manoah dit: Quand donc ta parole arrivera, quelle sera la règle du jeune garçon, et que devra-t-il faire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Et l’Ange de l’ Éternel dit à Manoah: La femme se gardera de tout ce que je lui ai dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Elle ne mangera rien de ce qui sort de la vigne, et elle ne boira ni vin ni boisson forte, et ne mangera rien d’impur. Elle prendra garde à tout ce que je lui ai commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Et Manoah dit à l’Ange de l’ Éternel: Laisse-nous te retenir, et t’apprêter un chevreau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Et l’Ange de l’ Éternel dit à Manoah: Si tu me retiens, je ne mangerai pas de ton pain; et si tu fais un holocauste, tu l’offriras à l’ Éternel. Car Manoah ne savait pas que c’était l’Ange de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Et Manoah dit à l’Ange de l’ Éternel: Quel est ton nom, afin que nous t’honorions, quand ce que tu as dit arrivera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Et l’Ange de l’ Éternel lui dit: Pourquoi demandes-tu mon nom? Il est merveilleux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Et Manoah prit le chevreau et le gâteau, et il les offrit à l’ Éternel sur le rocher. Et il fit une chose merveilleuse, tandis que Manoah et sa femme regardaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Et il arriva que, comme la flamme montait de dessus l’autel vers les cieux, l’Ange de l’ Éternel monta dans la flamme de l’autel, Manoah et sa femme regardant; et ils tombèrent sur leurs faces contre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Et l’Ange de l’ Éternel n’apparut plus à Manoah, ni à sa femme. Alors Manoah connut que c’était l’Ange de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Et Manoah dit à sa femme: Nous mourrons certainement, car nous avons vu Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Et sa femme lui dit: Si l’ Éternel avait pris plaisir à nous faire mourir, il n’aurait pas accepté de notre main l’holocauste et le gâteau, et il ne nous aurait pas fait voir toutes ces choses, et ne nous aurait pas fait entendre, dans ce moment, des choses comme celles-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Et la femme enfanta un fils, et appela son nom Samson; et l’enfant grandit, et l’ Éternel le bénit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Et l’Esprit de l’ Éternel commença de le pousser, – à Mahané-Dan, entre Tsorha et Eshtaol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Et Samson descendit à Thimna; et il vit à Thimna une femme d’entre les filles des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Et il remonta et le raconta à son père et à sa mère, et dit: J’ai vu à Thimna une femme d’entre les filles des Philistins; et maintenant, prenez-la-moi pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Et son père et sa mère lui dirent: N’y a-t-il pas de femme parmi les filles de tes frères, et dans tout mon peuple, que tu ailles prendre une femme d’entre les Philistins, les incirconcis? Et Samson dit à son père: Prends celle-là pour moi, car elle plaît à mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Et son père et sa mère ne savaient pas que cela venait de l’ Éternel; car [Samson] cherchait une occasion de la part des Philistins. Or en ce temps-là les Philistins dominaient sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Et Samson descendit à Thimna avec son père et sa mère; et ils arrivèrent jusqu’aux vignes de Thimna. Et voici, un jeune lion rugissant [vint] à sa rencontre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Et l’Esprit de l’ Éternel le saisit: et il le déchira, comme on déchire un chevreau, quoiqu’il n’ait rien en sa main; et il ne déclara point à son père ni à sa mère ce qu’il avait fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Et il descendit, et parla à la femme, et elle plut aux yeux de Samson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Et il retourna quelque temps après pour la prendre, et se détourna pour voir le cadavre du lion; et voici, il y avait dans le corps du lion un essaim d’abeilles, et du miel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'et il en prit dans ses mains, et s’en alla, mangeant en chemin; et il alla vers son père et vers sa mère, et leur en donna, et ils en mangèrent; mais il ne leur raconta pas qu’il avait tiré le miel du corps du lion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Et son père descendit vers la femme, et Samson fit là un festin; car c’est ainsi que les jeunes gens avaient l’habitude de faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Et il arriva que, quand ils le virent, ils prirent 30 compagnons, et ils furent avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Et Samson leur dit: Je vous proposerai, s’il vous plaît, une énigme; si vous me l’ expliquez dans les sept jours du festin et si vous la trouvez, je vous donnerai 30 chemises, et 30 vêtements de rechange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Mais si vous ne pouvez pas me l’expliquer, c’est vous qui me donnerez 30 chemises, et 30 vêtements de rechange. Et ils lui dirent: Propose ton énigme, et nous l’entendrons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Et il leur dit: De celui qui mange est sorti le manger, et du fort est sortie la douceur. Et pendant trois jours ils ne purent expliquer l’énigme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Et il arriva, le septième jour, qu’ils dirent à la femme de Samson: Persuade ton mari, et il nous expliquera l’énigme, de peur que nous ne te brûlions au feu, toi et la maison de ton père. C’est pour nous dépouiller que vous nous avez appelés, n’est-ce pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Et la femme de Samson pleura auprès de lui, et dit: Tu n’as pour moi que de la haine, et tu ne m’aimes pas; tu as proposé une énigme aux fils de mon peuple, et tu ne me l’as pas expliquée. Et il lui dit: Voici, je ne l’ai pas expliquée à mon père et à ma mère, et je te l’expliquerais à toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Et elle pleura auprès de lui pendant les sept jours qu’ils eurent le festin; et il arriva, le septième jour, qu’il la lui expliqua, parce qu’elle le tourmentait; et elle expliqua l’énigme aux fils de son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Et le septième jour, avant que le soleil se couche, les hommes de la ville lui dirent: Qu’y a-t-il de plus doux que le miel, et qu’y a-t-il de plus fort que le lion? Et il leur dit: Si vous n’aviez pas labouré avec ma génisse, vous n’auriez pas trouvé mon énigme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Et l’Esprit de l’ Éternel le saisit; et il descendit à Askalon, et en tua 30 hommes, et prit leurs dépouilles, et donna les vêtements de rechange à ceux qui avaient expliqué l’énigme. Et sa colère s’embrasa, et il monta à la maison de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Et la femme de Samson fut [donnée] à son compagnon, dont il avait fait son ami.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Et il arriva quelque temps après, pendant les jours de la moisson des froments, que Samson alla visiter sa femme, avec un chevreau; et il dit: Je veux entrer vers ma femme dans la chambre. Mais le père ne lui permit pas d’entrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Et le père dit: J’ai pensé que tu l’avais en haine, et je l’ai donnée à ton compagnon. Sa jeune sœur n’est-elle pas plus belle qu’elle? Prends-la à sa place, je te prie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Et Samson leur dit: Cette fois je suis innocent à l’égard des Philistins si je leur fais du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Et Samson s’en alla, et prit 300 chacals; et il prit des torches, et tourna [les chacals] queue contre queue, et mit une torche entre les deux queues, au milieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Et il mit le feu aux torches, et lâcha [les chacals] dans les blés des Philistins; et il brûla tant les tas de gerbes que le blé sur pied et les plantations d’oliviers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Et les Philistins dirent: Qui a fait cela? Et on dit: Samson, le gendre du Thimnite; parce qu’il lui a pris sa femme et l’a donnée à son compagnon. Et les Philistins montèrent, et la brûlèrent au feu, elle et son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Et Samson leur dit: Si c’est ainsi que vous faites, alors certes je me vengerai de vous, et après je cesserai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Et il les frappa d’un grand coup, à leur casser bras et jambes. Et il descendit, et habita dans une caverne du rocher d’Étam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Et les Philistins montèrent, et campèrent en Juda, et se répandirent en Lékhi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Et les hommes de Juda dirent: Pourquoi êtes-vous montés contre nous? Et ils dirent: Nous sommes montés pour lier Samson, afin de lui faire comme il nous a fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Et 3 000 hommes de Juda descendirent à la caverne du rocher d’Étam, et dirent à Samson: Ne sais-tu pas que les Philistins dominent sur nous? Et que nous as-tu fait? Et il leur dit: Comme ils m’ont fait, ainsi je leur ai fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Et ils lui dirent: Nous sommes descendus pour te lier, afin de te livrer en la main des Philistins. Et Samson leur dit: Jurez-moi que vous ne vous jetterez pas sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Et ils lui parlèrent, disant: Non, mais nous voulons te lier, et nous te livrerons en leur main; mais certainement nous ne te tuerons pas. Et ils le lièrent avec deux cordes neuves, et le firent monter hors du rocher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Il vint jusqu’à Lékhi, et les Philistins poussèrent des cris à sa rencontre. Et l’Esprit de l’ Éternel le saisit; et les cordes qui étaient à ses bras devinrent comme de l’étoupe qui brûle au feu, et ses liens coulèrent de dessus ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Et il trouva une mâchoire d’âne fraîche, et il étendit sa main et la prit, et en frappa 1 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Et Samson dit: Avec la mâchoire de l’âne, un monceau, deux monceaux! Avec la mâchoire de l’âne j’ai frappé 1 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Et il arriva que, quand il eut achevé de parler, il jeta de sa main la mâchoire, et nomma ce lieu-là Ramath-Lékhi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Et il eut une très grande soif, et il cria à l’ Éternel, et dit: Tu as donné par la main de ton serviteur cette grande délivrance, et maintenant je mourrais de soif, et je tomberais entre les mains des incirconcis!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Et Dieu fendit le rocher creux qui était à Lékhi, et il en sortit de l’eau; et il but, et son esprit revint, et il vécut: c’est pourquoi le nom de cette [source] fut appelé En-Hakkoré; elle est à Lékhi, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Et [Samson] jugea Israël, aux jours des Philistins, 20 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, '*Et Samson alla à Gaza, et il vit là une prostituée et entra vers elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, '[Et on rapporta] aux Gazites, disant: Samson est venu ici. Et ils l’entourèrent, et le guettèrent toute la nuit à la porte de la ville, et se tinrent tranquilles toute la nuit, disant: À la lumière du matin, nous le tuerons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Et Samson resta couché jusqu’au milieu de la nuit; et il se leva au milieu de la nuit; et il saisit les battants de la porte de la ville et les deux poteaux, et les arracha avec la barre, et les mit sur ses épaules, et les porta au sommet de la montagne qui est en face de Hébron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Et il arriva, après cela, qu’il aima une femme dans la vallée de Sorek, et son nom était Delila.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Et les princes des Philistins montèrent vers elle, et lui dirent: Persuade-le, et vois en quoi [consiste] sa grande force, et comment nous pourrions le vaincre et le lier pour l’humilier; et nous te donnerons chacun 1 100 [pièces] d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Et Delila dit à Samson: Déclare-moi, je te prie, en quoi [consiste] ta grande force, et avec quoi tu pourrais être lié pour t’humilier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Et Samson lui dit: Si on me liait avec sept cordelettes fraîches, qui ne soient pas desséchées, alors je deviendrais faible, et je serais comme un autre homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Et les princes des Philistins lui apportèrent sept cordelettes fraîches, qui n’étaient pas desséchées, et elle le lia avec ces [cordelettes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Et des hommes embusqués étaient chez elle dans la chambre; et elle lui dit: Les Philistins sont sur toi, Samson! Et il rompit les cordelettes comme se rompt une ficelle d’étoupe lorsqu’elle sent le feu; et sa force ne fut pas découverte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Et Delila dit à Samson: Voici, tu t’es moqué de moi et tu m’as dit des mensonges; maintenant déclare-moi, je te prie, avec quoi tu pourrais être lié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Et il lui dit: Si on me liait bien avec des cordes neuves, dont on n’aurait fait aucun usage, alors je deviendrais faible, et je serais comme un autre homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Et Delila prit des cordes neuves, et le lia avec ces [cordes], et lui dit: Les Philistins sont sur toi, Samson! Et les hommes embusqués étaient dans la chambre. Et il les rompit de dessus ses bras comme un fil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Et Delila dit à Samson: Jusqu’ici tu t’es moqué de moi, et tu m’as dit des mensonges; déclare-moi avec quoi tu pourrais être lié. Et il lui dit: Si tu tissais sept tresses de ma tête avec le fil à tisser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Et elle les fixa avec la cheville, et lui dit: Les Philistins sont sur toi, Samson! Et il se réveilla de son sommeil, et arracha la cheville du tissu et le fil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Et elle lui dit: Comment dis-tu: Je t’aime, – et ton cœur n’est pas avec moi? Tu t’es moqué de moi ces trois fois; et tu ne m’as pas déclaré en quoi [consiste] ta grande force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Et il arriva, comme elle le tourmentait par ses paroles tous les jours et le pressait, que son âme en fut ennuyée jusqu’à la mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'et il lui déclara tout [ce qui était dans] son cœur, et lui dit: Le rasoir n’a jamais passé sur ma tête, car je suis nazaréen de Dieu dès le ventre de ma mère. Si j’étais rasé, ma force s’en irait de moi, et je deviendrais faible, et je serais comme tous les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Et Delila vit qu’il lui avait déclaré tout [ce qui était dans] son cœur; et elle envoya, et appela les princes des Philistins, disant: Montez cette fois, car il m’a déclaré tout [ce qui est dans] son cœur. Et les princes des Philistins montèrent vers elle, et apportèrent l’argent dans leur main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Et elle l’endormit sur ses genoux, et appela un homme, et rasa les sept tresses de sa tête; et elle commença de l’humilier, et sa force se retira de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Et elle dit: Les Philistins sont sur toi, Samson! Et il se réveilla de son sommeil, et se dit: Je m’en irai comme les autres fois, et je me dégagerai. Or il ne savait pas que l’ Éternel s’était retiré de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Et les Philistins le saisirent et lui crevèrent les yeux, et le firent descendre à Gaza, et le lièrent avec des chaînes d’airain; et il tournait la meule dans la maison des prisonniers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Et les cheveux de sa tête commencèrent à croître, après qu’il eut été rasé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Et les princes des Philistins s’assemblèrent pour offrir un grand sacrifice à Dagon, leur dieu, et pour se réjouir; et ils dirent: Notre dieu a livré entre nos mains Samson, notre ennemi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Et le peuple le vit, et ils louèrent leur dieu, car ils disaient: Notre dieu a livré entre nos mains notre ennemi, et le dévastateur de notre pays, et celui qui multipliait nos tués.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Et il arriva, comme ils avaient le cœur joyeux, qu’ils dirent: Appelez Samson, et qu’il nous amuse! Et ils appelèrent Samson de la maison des prisonniers; et il joua devant eux; et ils le placèrent entre les colonnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Et Samson dit au garçon qui le tenait par la main: Laisse-moi, et fais-moi toucher les colonnes sur lesquelles la maison est assise, et que je m’y appuie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Et la maison était remplie d’hommes et de femmes; et tous les princes des Philistins étaient là, et, sur le toit, environ 3 000 hommes et femmes qui regardaient Samson jouer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Et Samson cria à l’ Éternel, et dit: Seigneur Éternel! souviens-toi de moi, je te prie, et fortifie-moi, je te prie, seulement cette fois, ô Dieu! afin que, d’une seule vengeance, je me venge des Philistins pour mes deux yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Et Samson saisit les deux colonnes du milieu, sur lesquelles la maison était assise (et il s’appuya sur elles), l’une de sa main droite, et l’autre de sa main gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Et Samson dit: Que mon âme meure avec les Philistins! Et il se pencha avec force, et la maison tomba sur les princes et sur tout le peuple qui y était. Et les morts qu’il fit mourir dans sa mort furent plus nombreux que ceux qu’il avait fait mourir pendant sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Et ses frères et toute la maison de son père descendirent, et l’emportèrent; et ils le remontèrent, et l’enterrèrent entre Tsorha et Eshtaol dans le sépulcre de Manoah, son père. Et il avait jugé Israël 20 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, '*Et il y avait un homme de la montagne d’Éphraïm, dont le nom était Michée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'et il dit à sa mère: Les 1 100 [pièces] d’argent qui t’ont été prises, et au sujet desquelles tu as fait des imprécations et as aussi parlé à mes oreilles..., voici, l’argent est par-devers moi; c’est moi qui l’avais pris. Et sa mère dit: Béni soit mon fils de par l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Et il rendit à sa mère les 1 100 [pièces] d’argent; et sa mère dit: J’avais consacré de ma main l’argent à l’ Éternel pour mon fils, afin d’en faire une image taillée, et une image de fonte; et maintenant, je te le rends.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Et il rendit l’argent à sa mère; et sa mère prit 200 [pièces] d’argent et les donna au fondeur, et il en fit une image taillée, et une image de fonte; et elles furent dans la maison de Michée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Et l’homme Michée eut une maison de dieux, et il fit un éphod et des théraphim, et consacra l’un de ses fils, et celui-ci fut son sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'En ces jours-là, il n’y avait pas de roi en Israël; chacun faisait ce qui était bon à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Et il y avait un jeune homme de Bethléhem de Juda, [ville] de la famille de Juda, et il était Lévite, et il séjournait là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Et l’homme s’en alla de sa ville, de Bethléhem de Juda, pour séjourner là où il trouverait [un lieu]; et, chemin faisant, il vint à la montagne d’Éphraïm, jusqu’à la maison de Michée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Et Michée lui dit: D’où viens-tu? Et il lui dit: Je suis un Lévite de Bethléhem de Juda, et je m’en vais pour séjourner là où je trouverai [un lieu].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Et Michée lui dit: Demeure avec moi, et tu seras pour moi un père et un sacrificateur, et je te donnerai dix [pièces] d’argent par an, et un habillement complet, et ton entretien. Et le Lévite alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Et le Lévite consentit à demeurer avec l’homme, et le jeune homme fut pour lui comme un de ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Et Michée consacra le Lévite; et le jeune homme fut son sacrificateur; et il fut dans la maison de Michée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Et Michée dit: Maintenant je connais que l’ Éternel me fera du bien, puisque j’ai un Lévite pour sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'En ces jours-là il n’y avait pas de roi en Israël; et, en ces jours, la tribu des Danites se cherchait un héritage pour y demeurer, car, jusqu’à ce jour-là, [leur lot] ne leur était point échu en héritage parmi les tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Et les fils de Dan envoyèrent de Tsorha et d’Eshtaol cinq hommes de leur famille, pris d’entre eux tous, des hommes vaillants, pour explorer le pays et le reconnaître; et ils leur dirent: Allez, reconnaissez le pays. Et ils vinrent à la montagne d’Éphraïm, jusqu’à la maison de Michée, et ils y passèrent la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Comme ils étaient près de la maison de Michée, ils reconnurent la voix du jeune homme, du Lévite; et ils entrèrent là, et lui dirent: Qui t’a amené ici, et que fais-tu par ici, et qu’as-tu ici?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Et il leur dit: Michée a fait pour moi telle et telle chose, et il me donne un salaire, et je suis son sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Et ils lui dirent: Nous te prions, interroge Dieu, afin que nous sachions si notre chemin par lequel nous allons prospérera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Et le sacrificateur leur dit: Allez en paix, le chemin où vous marchez est devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Et les cinq hommes s’en allèrent, et vinrent à Laïs; et ils virent le peuple qui était au milieu d’elle, habitant en sécurité, à la manière des Sidoniens, tranquille et confiant; et il n’y avait dans le pays personne qui, possédant la domination, les moleste en aucune chose; et ils étaient éloignés des Sidoniens, et n’avaient commerce avec personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, '– Et ils vinrent vers leurs frères, à Tsorha et à Eshtaol; et leurs frères leur dirent: Que [rapportez]-vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Et ils dirent: Levons-nous, et montons contre eux; car nous avons vu le pays, et voici, il est très bon: et vous vous tenez tranquilles? Ne soyez pas paresseux pour aller, et entrer, et posséder le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Quand vous y entrerez, vous entrerez vers un peuple confiant, et le pays est spacieux en tout sens; car Dieu l’a livré en votre main: c’est un lieu où rien ne manque de tout ce qui est sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Et de là, de Tsorha et d’Eshtaol, partirent 600 hommes de la famille des Danites, ceints de [leurs] armes de guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Et ils montèrent, et campèrent à Kiriath-Jéarim, en Juda; c’est pourquoi on a appelé ce lieu-là Mahané-Dan, jusqu’à ce jour: voici, il est derrière Kiriath-Jéarim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Et de là ils passèrent vers la montagne d’Éphraïm, et arrivèrent jusqu’à la maison de Michée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Et les cinq hommes qui étaient allés pour explorer le pays de Laïs, prirent la parole et dirent à leurs frères: Savez-vous qu’il y a dans ces maisons un éphod, et des théraphim, et une image taillée, et une image de fonte? Et maintenant vous savez ce que vous avez à faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Et ils se détournèrent vers ce lieu-là, et entrèrent dans la maison du jeune homme, du Lévite, la maison de Michée, et ils le saluèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Et les 600 hommes des fils de Dan, ceints de leurs armes de guerre, se tinrent à l’entrée de la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Et les cinq hommes qui étaient allés pour explorer le pays, montèrent, entrèrent là, [et] prirent l’image taillée, et l’éphod, et les théraphim, et l’image de fonte. Et le sacrificateur se tenait à l’entrée de la porte, ainsi que les 600 hommes qui étaient ceints de leurs armes de guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Et ceux-là entrèrent dans la maison de Michée, et prirent l’image taillée, et l’éphod, et les théraphim, et l’image de fonte; et le sacrificateur leur dit: Que faites-vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Et ils lui dirent: Tais-toi, mets ta main sur ta bouche, et viens avec nous, et sois pour nous un père et un sacrificateur. Vaut-il mieux pour toi d’être sacrificateur de la maison d’un homme seul, ou d’être sacrificateur d’une tribu et d’une famille en Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Et le cœur du sacrificateur s’en réjouit, et il prit l’éphod, et les théraphim, et l’image taillée, et il s’en alla au milieu du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Et ils se tournèrent, et s’en allèrent, et mirent devant eux les petits enfants, et les troupeaux, et les choses précieuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Quand ils furent loin de la maison de Michée, les hommes qui étaient dans les maisons voisines de celle de Michée furent assemblés à grands cris, et ils atteignirent les fils de Dan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Et ils crièrent aux fils de Dan; et eux tournèrent leurs visages, et dirent à Michée: Qu’as-tu, que tu aies rassemblé [ces gens]?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Et il dit: Vous avez pris mes dieux que j’ai faits, et le sacrificateur, et vous vous en êtes allés; et que me reste-t-il? Et comment me dites-vous: Qu’as-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Et les fils de Dan lui dirent: Ne fais pas entendre ta voix au milieu de nous, de peur que des hommes exaspérés ne se jettent sur vous, et que tu n’y perdes ta vie et la vie de ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Et les fils de Dan s’en allèrent leur chemin; et Michée vit qu’ils étaient trop forts pour lui, et se tourna, et revint à sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Et eux, prirent ce que Michée avait fait, et le sacrificateur qu’il avait, et vinrent à Laïs, vers un peuple tranquille et confiant, et ils les frappèrent par le tranchant de l’épée, et brûlèrent au feu leur ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Et il n’y avait personne qui la délivre; car elle était loin de Sidon, et ils n’avaient commerce avec personne: elle était dans la vallée qui est vers Beth-Rehob. Et ils bâtirent la ville, et y habitèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Et ils appelèrent le nom de la ville: Dan, d’après le nom de Dan, leur père, qui était né à Israël; mais, au commencement, le nom de la ville était Laïs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Et les fils de Dan dressèrent pour eux l’image taillée; et Jonathan, fils de Guershom, fils de Moïse, lui et ses fils, furent sacrificateurs pour la tribu des Danites, jusqu’au jour de la captivité du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Et ils dressèrent pour eux l’image taillée de Michée, qu’il avait faite, pendant tout le temps que la maison de Dieu fut à Silo.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, '*Et il arriva en ces jours-là, quand il n’y avait point de roi en Israël, qu’un Lévite qui séjournait au fond de la montagne d’Éphraïm, prit une concubine de Bethléhem de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Et sa concubine lui étant infidèle se prostitua, et s’en alla d’avec lui à la maison de son père, à Bethléhem de Juda; et elle fut là quelque temps, quatre mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Et son mari se leva, et alla après elle pour parler à son cœur, afin de la ramener, et il avait avec lui son jeune homme et une paire d’ânes. Et elle le fit entrer dans la maison de son père; et quand le père de la jeune femme le vit, il se réjouit de le rencontrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Et son beau-père, le père de la jeune femme, le retint; et il demeura avec lui trois jours; et ils mangèrent et burent, et ils passèrent la nuit là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Et il arriva, le quatrième jour, qu’ils se levèrent de bonne heure le matin; et, comme il se levait pour s’en aller, le père de la jeune femme dit à son gendre: Fortifie ton cœur avec une bouchée de pain, et après, vous vous en irez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Et ils s’assirent, et mangèrent et burent, eux deux ensemble; et le père de la jeune femme dit à l’homme: Consens, je te prie, et passe [ici] la nuit, et que ton cœur se réjouisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Et l’homme se leva pour s’en aller, mais son beau-père le pressa, et il revint et passa [encore] la nuit là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Et le cinquième jour, il se leva de bonne heure le matin pour s’en aller; mais le père de la jeune femme dit: Je te prie, fortifie ton cœur. Et ils s’attardèrent jusqu’à ce que le jour baissa, et ils mangèrent eux deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Et l’homme se leva pour s’en aller, lui et sa concubine, et son serviteur. Et son beau-père, le père de la jeune femme, lui dit: Tu vois que le jour faiblit, le soir approche; je vous prie, passez la nuit; voici, le jour tombe, passe ici la nuit, et que ton cœur se réjouisse; et demain vous vous lèverez de bonne heure pour [aller] votre chemin, et tu t’en iras à ta tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Mais l’homme ne voulut point passer la nuit, et il se leva, et s’en alla; et il vint jusque vis-à-vis de Jébus qui est Jérusalem, et, avec lui, la paire d’ânes bâtés, et sa concubine avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Ils étaient tout près de Jébus, et le jour avait beaucoup baissé; et le serviteur dit à son maître: Allons, je te prie, et détournons-nous vers cette ville des Jébusiens, et passons-y la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Et son maître lui dit: Nous ne nous détournerons point vers une ville des étrangers, qui n’est pas des fils d’Israël; mais nous passerons jusqu’à Guibha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Et il dit à son serviteur: Viens, et approchons-nous d’un de ces endroits, et passons la nuit à Guibha ou à Rama.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Et ils passèrent plus avant, et marchèrent, et le soleil se coucha, comme ils étaient près de Guibha, qui est à Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Et ils se détournèrent pour entrer [et] pour passer la nuit à Guibha. Et il entra, et s’assit sur la place de la ville, et il n’y eut personne qui les reçoive dans sa maison pour passer la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Et voici, sur le soir, un vieillard venait des champs, de son travail; et l’homme était de la montagne d’Éphraïm, et séjournait à Guibha; et les hommes du lieu étaient Benjaminites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Et il leva ses yeux, et vit le voyageur sur la place de la ville; et le vieillard [lui] dit: Où vas-tu, et d’où viens-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Et il lui dit: Nous passons de Bethléhem de Juda vers le fond de la montagne d’Éphraïm; je suis de là, et je suis allé à Bethléhem de Juda, et j’ai à faire avec la maison de l’ Éternel; et il n’y a personne qui me reçoive dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Et pourtant j’ai de la paille et du fourrage pour nos ânes, et j’ai aussi du pain et du vin pour moi et pour ta servante, et pour le jeune homme qui est avec tes serviteurs; rien ne nous manque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Et le vieillard lui dit: Paix te soit! Seulement, que tous tes besoins soient à ma charge; mais ne passe pas la nuit sur la place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Et il le fit entrer dans sa maison, et donna le fourrage aux ânes; et ils lavèrent leurs pieds, et mangèrent et burent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Comme ils faisaient bonne chère, voici, les hommes de la ville, des hommes, fils de Bélial, entourèrent la maison, frappant à la porte; et ils parlèrent au vieillard, maître de la maison, disant: Fais sortir l’homme qui est entré dans ta maison, afin que nous le connaissions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Et le maître de la maison sortit vers eux, et leur dit: Non, mes frères, ne faites pas [ce] mal, je vous prie; après que cet homme est entré dans ma maison, ne faites pas cette infamie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Voici ma fille qui est vierge, et sa concubine: laissez-moi les faire sortir, et vous les humilierez, et vous leur ferez ce qu’il vous plaira; mais à cet homme ne faites pas cette chose infâme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Mais ces gens ne voulurent pas l’écouter; et l’homme saisit sa concubine et la leur amena dehors; et ils la connurent et abusèrent d’elle toute la nuit jusqu’au matin; et ils la renvoyèrent comme l’aurore se levait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Et comme le matin arrivait, la femme vint et tomba à l’entrée de la maison de l’homme chez qui était son seigneur, [et y resta] jusqu’au jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Et son seigneur se leva le matin, et ouvrit la porte de la maison, et sortit pour aller son chemin; et voici, la femme, sa concubine, était tombée à l’entrée de la maison, ses mains sur le seuil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Et il lui dit: Lève-toi, et allons-nous-en. Mais personne ne répondit. Et l’homme la prit sur son âne, et se leva et s’en alla en son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Et il entra dans sa maison, et prit le couteau, et saisit sa concubine, et la partagea selon ses os en douze morceaux, et l’envoya dans tous les confins d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Et il arriva que tous ceux qui virent cela, dirent: Jamais chose pareille n’a eu lieu ni ne s’est vue, depuis le jour où les fils d’Israël sont montés du pays d’Égypte jusqu’à ce jour. Pensez à cela, prenez conseil, et parlez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Et tous les fils d’Israël sortirent, depuis Dan jusqu’à Beër-Shéba, et le pays de Galaad; et l’assemblée se réunit comme un seul homme, vers l’ Éternel, à Mitspa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Et les principaux de tout le peuple, toutes les tribus d’Israël, se présentèrent dans la congrégation du peuple de Dieu, 400 000 hommes de pied, tirant l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Et les fils de Benjamin apprirent que les fils d’Israël étaient montés à Mitspa. Et les fils d’Israël dirent: Dites comment ce mal est arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Et le Lévite, le mari de la femme tuée, répondit et dit: J’étais venu à Guibha, qui est à Benjamin, moi et ma concubine, pour passer la nuit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'et les hommes de Guibha se levèrent contre moi, et entourèrent de nuit la maison, à cause de moi; ils avaient l’intention de me tuer, et ils ont humilié ma concubine, et elle est morte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Et j’ai saisi ma concubine et je l’ai coupée en morceaux, et je l’ai envoyée dans toutes les campagnes de l’héritage d’Israël; car ils ont commis une énormité et une infamie en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Voici, vous tous, fils d’Israël, délibérez, et donnez ici [votre] avis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Et tout le peuple se leva comme un seul homme, disant: Aucun de nous n’ira à sa tente, et aucun de nous ne se retirera dans sa maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'et maintenant, voici ce que nous ferons à Guibha: nous la traiterons selon ce que le sort décidera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'et nous prendrons 10 hommes sur 100, de toutes les tribus d’Israël, et 100 sur 1 000, et 1 000 sur 10 000, qui prendront des provisions pour le peuple, afin que, à leur arrivée, on traite Guibha de Benjamin selon toute l’infamie qu’elle a commise en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Et tous les hommes d’Israël se rassemblèrent contre la ville, unis comme un seul homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Et les tribus d’Israël envoyèrent des hommes dans toutes les familles de Benjamin, disant: Quel est ce mal qui est arrivé au milieu de vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Et maintenant, livrez-nous ces hommes, fils de Bélial, qui sont à Guibha, afin que nous les fassions mourir et que nous ôtions le mal du milieu d’Israël. Mais [les fils de] Benjamin ne voulurent pas écouter la voix de leurs frères, les fils d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'et les fils de Benjamin se rassemblèrent de leurs villes à Guibha, pour sortir en guerre contre les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Et en ce jour-là furent dénombrés les fils de Benjamin qui vinrent de leurs villes: 26 000 hommes tirant l’épée, sans les habitants de Guibha, qui furent dénombrés: 700 hommes d’élite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'De tout ce peuple, il y avait 700 hommes d’élite qui étaient gauchers; tous ceux-là lançaient avec la fronde une pierre contre un cheveu, et ne manquaient pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Et les hommes d’Israël furent dénombrés, sauf Benjamin: 400 000 hommes tirant l’épée, tous gens de guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Et les fils d’Israël se levèrent, et montèrent à Béthel, et interrogèrent Dieu, et dirent: Qui de nous montera le premier pour livrer bataille aux fils de Benjamin? Et l’ Éternel dit: Juda, le premier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Et les fils d’Israël se levèrent le matin, et campèrent contre Guibha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Et les hommes d’Israël sortirent en guerre contre Benjamin, et les hommes d’Israël se rangèrent en bataille contre eux devant Guibha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Et les fils de Benjamin sortirent de Guibha; et en ce jour-là ils étendirent morts par terre 22 000 hommes de ceux d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Et le peuple, les hommes d’Israël, se fortifièrent, et se rangèrent de nouveau en bataille dans le lieu où ils s’étaient rangés le premier jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Et les fils d’Israël montèrent, et ils pleurèrent devant l’ Éternel jusqu’au soir, et ils interrogèrent l’ Éternel, disant: M’approcherai-je de nouveau pour livrer bataille aux fils de Benjamin, mon frère? Et l’ Éternel dit: Montez contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Et les fils d’Israël s’avancèrent contre les fils de Benjamin, le second jour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'et Benjamin sortit contre eux de Guibha, le second jour; et de nouveau ils étendirent morts par terre 18 000 hommes des fils d’Israël, tous tirant l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Et tous les fils d’Israël et tout le peuple montèrent et vinrent à Béthel, et pleurèrent et demeurèrent là devant l’ Éternel, et jeûnèrent ce jour-là jusqu’au soir; et ils offrirent des holocaustes et des sacrifices de prospérités devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Et les fils d’Israël interrogèrent l’ Éternel (et l’arche de l’alliance de Dieu était là, en ces jours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'et Phinées, fils d’Éléazar, fils d’Aaron, se tenait devant elle, en ces jours), et ils dirent: Sortirai-je encore de nouveau pour livrer bataille aux fils de Benjamin, mon frère, ou cesserai-je? Et l’ Éternel dit: Montez; car demain je les livrerai en ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Et Israël plaça des embuscades contre Guibha, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Et les fils d’Israël montèrent, le troisième jour, contre les fils de Benjamin; et ils se rangèrent contre Guibha, comme les autres fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Et les fils de Benjamin sortirent à la rencontre du peuple; ils furent attirés loin de la ville, et commencèrent à frapper quelques-uns du peuple, qui furent tués comme les autres fois, environ 30 hommes d’Israël, sur les routes, dont l’une monte à Béthel, et l’autre à Guibha, par la campagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Et les fils de Benjamin dirent: Ils sont battus devant nous comme la première fois. Et les fils d’Israël dirent: Fuyons, et nous les attirerons loin de la ville, sur les routes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Et tous les hommes d’Israël se levèrent de leur lieu, et se rangèrent à Baal-Thamar; et l’embuscade d’Israël s’élança de son lieu, de la prairie de Guibha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Et 10 000 hommes d’élite de tout Israël vinrent contre Guibha, et la bataille fut rude; et ceux [de Benjamin] ne savaient pas que le mal les atteignait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Et l’ Éternel battit Benjamin devant Israël, et les fils d’Israël étendirent morts en ce jour-là 25 100 hommes de Benjamin, tous tirant l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Et les fils de Benjamin virent qu’ils étaient battus. – Or les hommes d’Israël firent place à ceux de Benjamin, car ils se confiaient en l’embuscade qu’ils avaient placée contre Guibha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Et l’embuscade se hâta, et se jeta sur Guibha; et l’embuscade se porta en avant, et frappa toute la ville par le tranchant de l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Et le signal convenu entre les hommes d’Israël et l’embuscade était qu’ils fassent monter de la ville une épaisse colonne de fumée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Et les hommes d’Israël avaient tourné visage dans la bataille, et Benjamin avait commencé de frapper à mort une trentaine d’hommes parmi les hommes d’Israël, car ils disaient: Certainement il est complètement battu devant nous comme dans la première bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Et quand l’incendie commença à monter de la ville comme une colonne de fumée, Benjamin se tourna en arrière, et voici, toute la ville montait [en fumée] vers les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Et les hommes d’Israël tournèrent visage: et les hommes de Benjamin furent épouvantés; car ils virent que le mal les avait atteints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Et ils tournèrent le dos devant les hommes d’Israël, vers le chemin du désert, et la bataille les serra de près. Et ceux qui sortirent des villes les détruisirent au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Ils environnèrent Benjamin, le poursuivirent, le foulèrent aux pieds là où il voulait se reposer, jusque vis-à-vis de Guibha, vers le soleil levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Et il tomba de Benjamin 18 000 hommes, tous hommes vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Et ils tournèrent le dos, et s’enfuirent au désert, vers le rocher de Rimmon; et [les Israélites] en grappillèrent sur les routes 5 000 hommes, et ils les serrèrent de près en les poursuivant jusqu’à Guidhom, et en frappèrent 2 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Et tous ceux de Benjamin qui tombèrent en ce jour-là, furent 25 000 hommes tirant l’épée, tous hommes vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Et 600 hommes tournèrent le dos et s’enfuirent au désert, vers le rocher de Rimmon, et ils demeurèrent au rocher de Rimmon quatre mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Et les hommes d’Israël retournèrent vers les fils de Benjamin et les frappèrent par le tranchant de l’épée, et les hommes de chaque ville, et les bêtes, et tout ce qui fut trouvé; même toutes les villes qu’ils rencontrèrent, ils les livrèrent au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Et les hommes d’Israël jurèrent à Mitspa, disant: Nul de nous ne donnera sa fille pour femme à Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Et le peuple vint à Béthel, et ils demeurèrent là jusqu’au soir devant Dieu; et ils élevèrent leur voix et pleurèrent amèrement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'et dirent: Éternel, Dieu d’Israël, pourquoi ceci est-il arrivé en Israël, qu’il manque aujourd’hui à Israël une tribu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Et le lendemain, il arriva que le peuple se leva de bonne heure et bâtit là un autel; et ils offrirent des holocaustes et des sacrifices de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Et les fils d’Israël dirent: Qui est celui qui n’est pas monté vers l’ Éternel, dans la congrégation, d’entre toutes les tribus d’Israël? Car un grand serment avait été [fait] contre celui qui ne monterait pas vers l’ Éternel, à Mitspa, disant: Il sera certainement mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Et les fils d’Israël se repentirent à l’égard de Benjamin, leur frère, et ils dirent: Une tribu a été aujourd’hui retranchée d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Que ferons-nous pour ceux qui restent, pour qu’ils aient des femmes, vu que nous avons juré par l’ Éternel de ne pas leur donner de nos filles pour femmes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Et ils dirent: Y a-t-il quelqu’un d’entre les tribus d’Israël qui ne soit pas monté vers l’ Éternel à Mitspa? Or voici, aucun homme de Jabès de Galaad n’était venu au camp, à la congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Et le peuple fut dénombré: et voici, il n’y avait là aucun homme des habitants de Jabès de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Et l’assemblée y envoya 12 000 d’entre les vaillants hommes, et on leur commanda, disant: Allez, et frappez les habitants de Jabès de Galaad par le tranchant de l’épée, et les femmes et les enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Et voici ce que vous ferez: vous exterminerez tout mâle, ainsi que toute femme qui aura eu compagnie d’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Et ils trouvèrent parmi les habitants de Jabès de Galaad 400 jeunes filles vierges qui n’avaient point connu d’homme en couchant avec lui; et ils les amenèrent dans le camp, à Silo, qui est dans le pays de Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Et toute l’assemblée envoya parler aux fils de Benjamin, qui étaient au rocher de Rimmon, et leur annonça la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Et, en ce temps-là, Benjamin revint, et on leur donna les femmes qu’on avait laissé vivre d’entre les femmes de Jabès de Galaad; mais ainsi ils n’en trouvèrent pas assez pour eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Et le peuple se repentait au sujet de Benjamin, parce que l’ Éternel avait fait une brèche dans les tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Et les anciens de l’assemblée dirent: Que ferons-nous pour ceux qui restent, pour qu’ils aient des femmes, car les femmes ont été détruites en Benjamin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Et ils dirent: Il faut une possession pour ceux de Benjamin qui sont réchappés, afin qu’une tribu ne soit pas effacée d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Et nous, nous ne pouvons pas leur donner des femmes d’entre nos filles; car les fils d’Israël ont juré, disant: Maudit celui qui donne une femme à Benjamin!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Et ils dirent: Voici, il y a tous les ans une fête à l’ Éternel à Silo, qui est au nord de Béthel, au soleil levant de la route qui monte de Béthel à Sichem, et au midi de Lebona.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Et ils commandèrent aux fils de Benjamin, disant: Allez, et mettez-vous en embuscade dans les vignes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Et vous regarderez, et voici, quand les filles de Silo sortiront en chœurs pour danser, alors vous sortirez des vignes et vous ravirez pour vous, chacun sa femme d’entre les filles de Silo, et vous vous en irez dans le pays de Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Et s’il arrive que leurs pères ou leurs frères viennent nous quereller, nous leur dirons: Usez de grâce envers nous à leur sujet, car nous n’avons pas reçu chacun sa femme par la guerre; car ce n’est pas vous qui les leur avez données, de sorte que vous soyez coupables maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Et les fils de Benjamin firent ainsi, et enlevèrent des femmes selon leur nombre, d’entre les danseuses dont ils s’emparèrent; et ils s’en allèrent et retournèrent dans leur héritage, et rebâtirent les villes et y habitèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Et les fils d’Israël s’en allèrent de là, en ce temps-là, chacun dans sa tribu et dans sa famille; et ils partirent de là chacun pour son héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'En ces jours-là, il n’y avait pas de roi en Israël; chacun faisait ce qui était bon à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Et il arriva, dans les jours où les juges jugeaient, qu’il y eut une famine dans le pays; et un homme s’en alla de Bethléhem de Juda, pour séjourner aux champs de Moab, lui et sa femme et ses deux fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Et le nom de l’homme était Élimélec, et le nom de sa femme, Naomi; et les noms de ses deux fils, Makhlon et Kilion, Éphratiens, de Bethléhem de Juda; et ils vinrent aux champs de Moab, et ils demeurèrent là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Et Élimélec, mari de Naomi, mourut; et elle resta avec ses deux fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Et ils prirent des femmes moabites: le nom de l’une était Orpa, et le nom de la seconde, Ruth; et ils habitèrent là environ dix ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Et Makhlon et Kilion, eux deux aussi, moururent; et la femme resta, [privée] de ses deux enfants et de son mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Et elle se leva, elle et ses belles-filles, et s’en revint des champs de Moab; car elle avait entendu dire, au pays de Moab, que l’ Éternel avait visité son peuple pour leur donner du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Et elle partit du lieu où elle était, et ses deux belles-filles avec elle; et elles se mirent en chemin pour retourner dans le pays de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Et Naomi dit à ses deux belles-filles: Allez, retournez chacune dans la maison de sa mère. Que l’ Éternel use de bonté envers vous, comme vous avez fait envers les morts et envers moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'L’ Éternel vous donne de trouver du repos, chacune dans la maison de son mari! Et elle les embrassa; et elles élevèrent leur voix et pleurèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Et elles lui dirent: [Non], mais nous retournerons avec toi vers ton peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Et Naomi dit: Retournez, mes filles; pourquoi iriez-vous avec moi? Ai-je encore des fils dans mon sein, de sorte qu’ils soient vos maris?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Retournez, mes filles, allez; car je suis trop vieille pour être à un mari; si je disais que j’en ai l’espérance, quand cette nuit même je serais à un mari, et que même j’enfanterais des fils:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'attendriez-vous pour cela jusqu’à ce qu’ils soient grands? Resteriez-vous pour cela sans être à un mari? Non, mes filles; car je suis dans une plus grande amertume que vous, car la main de l’ Éternel s’est étendue contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Et elles élevèrent leur voix, et pleurèrent encore; et Orpa embrassa sa belle-mère, mais Ruth s’attacha à elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Et [Naomi] dit: Voici, ta belle-sœur est retournée vers son peuple et vers ses dieux; retourne-t’en après ta belle-sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Et Ruth dit: Ne me prie pas de te laisser, pour que je m’en retourne d’avec toi; car où tu iras, j’irai, et où tu demeureras, je demeurerai: ton peuple sera mon peuple, et ton Dieu sera mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Là où tu mourras, je mourrai et j’y serai enterrée. Ainsi me fasse l’ Éternel, et ainsi il y ajoute, si la mort [seule] ne me sépare de toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Et [Naomi] vit qu’elle était résolue d’aller avec elle, et elle cessa de lui parler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Et elles marchèrent les deux jusqu’à ce qu’elles arrivèrent à Bethléhem. Et il arriva que, comme elles entraient dans Bethléhem, toute la ville s’émut à leur sujet; et les [femmes] disaient: Est-ce là Naomi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Et elle leur dit: Ne m’appelez pas Naomi, appelez-moi Mara; car le Tout-puissant m’a remplie d’amertume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Je m’en allai comblée, et l’ Éternel me ramène à vide. Pourquoi m’appelez-vous Naomi, quand l’ Éternel m’a abattue, et que le Tout-puissant m’a affligée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Ainsi Naomi revint, et avec elle Ruth, la Moabite, sa belle-fille, qui était venue des champs de Moab; et elles vinrent à Bethléhem, au commencement de la moisson des orges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, '*Et Naomi avait un ami de son mari, homme puissant [et] riche, de la famille d’Élimélec, et son nom était Boaz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Et Ruth, la Moabite, dit à Naomi: Je te prie, j’irai aux champs, et je glanerai parmi les épis, à la suite de celui aux yeux duquel je trouverai grâce. Et elle lui dit: Va, ma fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Et elle s’en alla, et entra, et glana dans un champ après les moissonneurs; et il se rencontra fortuitement que c’était la portion de champ de Boaz, qui était de la famille d’Élimélec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Et voici, Boaz vint de Bethléhem; et il dit aux moissonneurs: L’ Éternel soit avec vous! Et ils lui dirent: L’ Éternel te bénisse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Et Boaz dit à son serviteur qui était établi sur les moissonneurs: À qui est cette jeune femme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Et le serviteur qui était établi sur les moissonneurs répondit et dit: C’est la jeune Moabite qui est revenue avec Naomi des champs de Moab;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'et elle [nous] a dit: Permettez que je glane et que je ramasse entre les gerbes, après les moissonneurs. Et elle est venue, et est demeurée depuis le matin jusqu’à cette heure; ce qu’elle a été assise dans la maison est peu de chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Et Boaz dit à Ruth: Tu entends, n’est-ce pas, ma fille? ne va pas glaner dans un autre champ, et ne t’en va pas non plus d’ici, mais tiens-toi ici auprès de mes jeunes filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Aie les yeux sur le champ qu’on moissonne, et va après elles. N’ai-je pas commandé aux jeunes hommes de ne pas te toucher? Et si tu as soif, tu iras aux vases, et tu boiras de ce que puisent les jeunes hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Et elle tomba sur sa face, et se prosterna contre terre, et lui dit: Pourquoi ai-je trouvé grâce à tes yeux, que tu me reconnaisses, et je suis une étrangère?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Et Boaz répondit et lui dit: Tout ce que tu as fait pour ta belle-mère après la mort de ton mari, m’a été rapporté, et comment tu as quitté ton père et ta mère, et le pays de ta naissance, et tu es venue vers un peuple que tu ne connaissais pas auparavant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Que l’ Éternel récompense ton œuvre, et que ton salaire soit entier de la part de l’ Éternel, le Dieu d’Israël, sous les ailes duquel tu es venue t’abriter!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Et elle dit: Mon seigneur, que je trouve grâce à tes yeux! car tu m’as consolée, et tu as parlé au cœur de ta servante, et pourtant je ne suis pas comme une de tes servantes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Et, au temps du repas, Boaz lui dit: Approche-toi ici, et mange du pain, et trempe ton morceau dans le vinaigre. Et elle s’assit à côté des moissonneurs, et il lui tendit du grain rôti; et elle mangea, et fut rassasiée, et en laissa de reste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Et elle se leva pour glaner; et Boaz commanda à ses jeunes hommes, disant: Qu’elle glane même entre les gerbes, et ne lui en faites pas de reproche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'et vous tirerez aussi pour elle [quelques épis] des poignées, et vous les laisserez; et elle les glanera, et vous ne l’en reprendrez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Et elle glana dans le champ jusqu’au soir, et elle battit ce qu’elle avait glané, et il y eut environ un épha d’orge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Et elle le chargea [sur elle], et vint à la ville; et sa belle-mère vit ce qu’elle avait glané. Et elle sortit ce qu’elle avait laissé de reste après avoir été rassasiée, et le lui donna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Et sa belle-mère lui dit: Où as-tu glané aujourd’hui, et où as-tu travaillé? Béni soit celui qui t’a reconnue! Et elle raconta à sa belle-mère chez qui elle avait travaillé, et dit: Le nom de l’homme chez qui j’ai travaillé aujourd’hui est Boaz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Et Naomi dit à sa belle-fille: Béni soit-il de l’ Éternel, qui n’a pas discontinué sa bonté envers les vivants et envers les morts! Et Naomi lui dit: L’homme nous est proche parent, il est de ceux qui ont sur nous le droit de rachat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Et Ruth, la Moabite, dit: Même il m’a dit: Tiens-toi près de mes jeunes hommes jusqu’à ce qu’ils aient achevé toute la moisson que j’ai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Et Naomi dit à Ruth, sa belle-fille: Il est bon, ma fille, que tu sortes avec ses jeunes filles, et qu’on ne te rencontre pas dans un autre champ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Et elle se tint auprès des jeunes filles de Boaz, pour glaner, jusqu’à ce que la moisson des orges et la moisson des froments soit achevée; et elle habitait avec sa belle-mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, '*Et Naomi, sa belle-mère, lui dit: Ma fille, ne te chercherai-je pas du repos, afin que tu sois heureuse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Et maintenant, Boaz, avec les jeunes filles duquel tu as été, n’est-il pas de nos amis? Voici, il vanne cette nuit les orges dans l’aire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Lave-toi donc, et oins-toi, et mets sur toi tes habits, et descends dans l’aire; ne te fais pas connaître à l’homme, jusqu’à ce qu’il ait achevé de manger et de boire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Et lorsqu’il se couchera, alors tu remarqueras le lieu où il se couche, et tu entreras, et tu découvriras ses pieds, et tu te coucheras; et lui, te fera connaître ce que tu auras à faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Et elle lui dit: Tout ce que tu as dit, je le ferai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Et elle descendit à l’aire, et fit selon tout ce que sa belle-mère lui avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Et Boaz mangea et but, et son cœur devint gai, et il alla se coucher au bout du tas des gerbes. Et elle vint tout doucement, et découvrit ses pieds, et se coucha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Et il arriva au milieu de la nuit, que l’homme eut peur et se tourna; et voici, une femme était couchée à ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Et il dit: Qui es-tu? Et elle dit: Je suis Ruth, ta servante; et étends ton aile sur ta servante, car tu as le droit de rachat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Et il dit: Bénie sois-tu de l’ Éternel, ma fille! Tu as montré plus de bonté à la fin qu’au commencement, en ce que tu n’es pas allée après les jeunes hommes, pauvres ou riches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Et maintenant, ma fille, ne crains pas; tout ce que tu [me] dis, je le ferai pour toi; car toute la porte de mon peuple sait que tu es une femme vertueuse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Et maintenant, il est bien vrai que j’ai le droit de rachat, toutefois il y en a un qui a le droit de rachat, [et qui est] plus proche que moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Passe [ici] la nuit; et s’il arrive que, le matin, il veuille te racheter, c’est bien! qu’il le fasse; et s’il ne lui plaît pas de te racheter, l’ Éternel est vivant que je le ferai, moi! Reste couchée jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Et elle resta couchée là à ses pieds jusqu’au matin; et elle se leva avant qu’on puisse se reconnaître l’un l’autre. Et il dit: Qu’on ne sache pas qu’une femme est venue dans l’aire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Et il [lui] dit: Donne le manteau qui est sur toi, et tiens-le. Et elle le tint, et il mesura six [mesures] d’orge, et les mit sur elle; et il entra dans la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Et elle vint vers sa belle-mère; et celle-ci dit: Qui es-tu, ma fille? Et elle lui raconta tout ce que l’homme avait fait pour elle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'et elle dit: Il m’a donné ces six [mesures] d’orge; car il m’a dit: Tu n’iras pas à vide vers ta belle-mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Et [Naomi] dit: Demeure, ma fille, jusqu’à ce que tu saches comment l’affaire tournera; car l’homme n’aura pas de repos qu’ il n’ait terminé l’affaire aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, '*Et Boaz monta à la porte, et s’assit là. Et voici, celui qui avait le droit de rachat, [et] dont Boaz avait parlé, vint à passer; et il dit: Toi, un tel, détourne-toi, assieds-toi ici. Et il se détourna et s’assit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Et [Boaz] prit dix hommes des anciens de la ville, et dit: Asseyez-vous ici. Et ils s’assirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Et il dit à celui qui avait le droit de rachat: Naomi, qui est revenue des champs de Moab, vend la pièce de terre qui était à notre frère Élimélec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Et moi, je me suis dit: Je t’en informerai, et je te dirai: Achète-la en la présence des habitants et en la présence des anciens de mon peuple. Si tu veux racheter, rachète; et si tu ne veux pas racheter, déclare-le-moi, afin que je le sache; car il n’y a personne que toi pour racheter, et moi je suis après toi. Et il dit: Je rachèterai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Et Boaz dit: Au jour où tu achèteras le champ de la main de Naomi, tu l’achèteras aussi de Ruth, la Moabite, femme du défunt, pour relever le nom du défunt sur son héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Et celui qui avait le droit de rachat dit: Je ne puis pas le racheter pour moi, de peur que je ne ruine mon héritage; use, toi, de mon droit de rachat, car je ne puis racheter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Or c’était jadis [une coutume] en Israël, en cas de rachat et d’échange, que, pour confirmer toute affaire, l’un ôtait sa sandale et la donnait à l’autre; c’était là une coutume en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Et celui qui avait le droit de rachat dit à Boaz: Achète pour toi; et il ôta sa sandale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Et Boaz dit aux anciens et à tout le peuple: Vous êtes aujourd’hui témoins que j’ai acheté de la main de Naomi tout ce qui était à Élimélec, et tout ce qui était à Kilion et à Makhlon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'et aussi que je me suis acquis pour femme Ruth, la Moabite, la femme de Makhlon, pour relever le nom du défunt sur son héritage, afin que le nom du défunt ne soit pas retranché d’entre ses frères et de la porte de son lieu: vous en êtes témoins aujourd’hui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Et tout le peuple qui était à la porte, et les anciens, dirent: [Nous en sommes] témoins. Fasse l’ Éternel que la femme qui entre dans ta maison soit comme Rachel, et comme Léa, qui toutes deux ont bâti la maison d’Israël! Et deviens puissant dans Éphrata, et fais-toi un nom dans Bethléhem!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Et que, de la postérité que l’ Éternel te donnera de cette jeune femme, ta maison soit comme la maison de Pérets, que Tamar enfanta à Juda!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Et Boaz prit Ruth, et elle fut sa femme; et il vint vers elle; et l’ Éternel lui donna de concevoir, et elle enfanta un fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Et les femmes dirent à Naomi: Béni soit l’ Éternel, qui ne t’a pas laissé manquer aujourd’hui d’un homme qui ait le droit de rachat! et que son nom soit nommé en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Et il sera pour toi un restaurateur de ton âme, et un soutien de ta vieillesse! Car ta belle-fille qui t’aime, l’a enfanté, elle qui vaut mieux pour toi que sept fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Et Naomi prit l’enfant, et le mit dans son sein, et elle lui tint lieu de nourrice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Et les voisines lui donnèrent un nom, disant: Un fils est né à Naomi! Et elles l’appelèrent du nom d’Obed. Ce fut le père d’Isaï, père de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Et ce sont ici les générations de Pérets: Pérets engendra Hetsron;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'et Hetsron engendra Ram; et Ram engendra Amminadab;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'et Amminadab engendra Nakhshon; et Nakhshon engendra Salma;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'et Salmon engendra Boaz; et Boaz engendra Obed;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'et Obed engendra Isaï; et Isaï engendra David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Et il y avait un homme de Ramathaïm-Tsophim, de la montagne d’Éphraïm, et son nom était Elkana, fils de Jerokham, fils d’Élihu, fils de Thohu, fils de Tsuph, Éphratien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'et il avait deux femmes: le nom de l’une était Anne, et le nom de la seconde, Peninna. Et Peninna avait des enfants, mais Anne n’avait pas d’enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Et cet homme montait chaque année de sa ville pour adorer l’ Éternel des armées et lui sacrifier à Silo; et là étaient les deux fils d’Éli, Hophni et Phinées, sacrificateurs de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Et il arriva que, le jour où Elkana sacrifia, il donna des portions à Peninna, sa femme, et à chacun de ses fils et de ses filles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'mais à Anne il donna une portion double, car il aimait Anne; mais l’ Éternel avait fermé sa matrice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Et son ennemie la chagrinait aigrement, afin de la pousser à l’irritation, parce que l’ Éternel avait fermé sa matrice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Et [Elkana] faisait ainsi d’année en année. Chaque fois qu’elle montait à la maison de l’ Éternel, [Peninna] la chagrinait ainsi; et elle pleurait, et ne mangeait pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Et Elkana, son mari, lui dit: Anne, pourquoi pleures-tu? et pourquoi ne manges-tu pas? et pourquoi ton cœur est-il chagrin? Est-ce que je ne vaux pas mieux pour toi que dix fils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Et Anne se leva, après qu’on eut mangé à Silo, et après qu’on eut bu; (et Éli, le sacrificateur, était assis sur un siège près de l’un des poteaux du temple de l’ Éternel);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'et elle avait l’amertume dans l’âme, et elle pria l’ Éternel et pleura abondamment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Et elle fit un vœu, et dit: Éternel des armées! si tu veux regarder à l’affliction de ta servante, et si tu te souviens de moi et n’oublies pas ta servante, et que tu donnes à ta servante un enfant mâle, je le donnerai à l’ Éternel [pour] tous les jours de sa vie; et le rasoir ne passera pas sur sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Et il arriva que, comme elle priait longuement devant l’ Éternel, Éli observa sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Et Anne parlait dans son cœur; ses lèvres seulement remuaient, mais on n’entendait pas sa voix; et Éli pensa qu’elle était ivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Et Éli lui dit: Jusques à quand seras-tu ivre? Ôte ton vin d’avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Et Anne répondit et dit: Non, mon seigneur; je suis une femme qui a l’esprit accablé; je n’ai bu ni vin ni boisson forte, mais je répandais mon âme devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Ne mets pas ta servante au rang d’une fille de Bélial; car c’est dans la grandeur de ma plainte et de mon chagrin que j’ai parlé jusqu’à présent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Et Éli répondit et dit: Va en paix; et que le Dieu d’Israël t’accorde la demande que tu lui as faite!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Et elle dit: Que ta servante trouve grâce à tes yeux! Et la femme s’en alla son chemin; et elle mangea, et elle n’eut plus le même visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Et ils se levèrent de bonne heure le matin, et se prosternèrent devant l’ Éternel; et ils s’en retournèrent et vinrent dans leur maison, à Rama. Et Elkana connut Anne, sa femme; et l’ Éternel se souvint d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Et il arriva que, quand les jours furent révolus, Anne, ayant conçu, enfanta un fils; et elle appela son nom Samuel: car je l’ai demandé à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Et Elkana, son mari, monta avec toute sa maison pour sacrifier à l’ Éternel le sacrifice annuel et son vœu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Mais Anne ne monta pas, car elle dit à son mari: [J’attendrai] jusqu’à ce que l’enfant soit sevré; alors je le mènerai, afin qu’il paraisse devant l’ Éternel et qu’il habite là pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Et Elkana, son mari, lui dit: Fais ce qui est bon à tes yeux, demeure jusqu’à ce que tu l’aies sevré; seulement, que l’ Éternel accomplisse sa parole! Et la femme demeura, et elle allaita son fils jusqu’à ce qu’elle l’ait sevré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Et sitôt qu’elle l’eut sevré, elle l’emmena avec elle, avec trois jeunes taureaux, et un épha de farine et une outre de vin; et elle le mena à la maison de l’ Éternel à Silo; et l’enfant était très jeune.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Et ils égorgèrent le taureau, et ils amenèrent le jeune garçon à Éli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Et elle dit: Ah, mon seigneur! ton âme est vivante, mon seigneur, je suis la femme qui se tenait ici près de toi pour prier l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'J’ai prié pour cet enfant, et l’ Éternel m’a accordé la demande que je lui ai faite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Et aussi, moi je l’ai prêté à l’ Éternel; [pour] tous les jours de sa vie, il est prêté à l’ Éternel. Et il se prosterna là devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, '*Et Anne pria, et dit: Mon cœur s’égaie en l’ Éternel; ma corne est élevée en l’ Éternel; ma bouche s’ouvre sur mes ennemis, car je me réjouis en ton salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Nul n’est saint comme l’ Éternel, car il n’y en a point d’autre que toi; et il n’y a pas de rocher comme notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Ne multipliez pas vos paroles hautaines; que l’insolence ne sorte pas de votre bouche; car l’ Éternel est un ✶Dieu de connaissance, et par lui les actions sont pesées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'L’arc des puissants est brisé, et ceux qui chancelaient se ceignent de force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Ceux qui étaient rassasiés se sont loués pour du pain; et ceux qui étaient affamés ont cessé de l’être; même la stérile en enfante sept, et celle qui avait beaucoup de fils est devenue languissante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'L’ Éternel fait mourir et fait vivre; il fait descendre au shéol et [en] fait monter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'L’ Éternel appauvrit et enrichit; il abaisse, et il élève aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'De la poussière il fait lever le misérable, de dessus le fumier il élève le pauvre, pour les faire asseoir avec les nobles: et il leur donne en héritage un trône de gloire; car les piliers de la terre sont à l’ Éternel, et sur eux il a posé le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Il garde les pieds de ses saints, et les méchants se taisent dans les ténèbres; car l’homme ne prévaut pas par sa force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Ceux qui contestent contre l’ Éternel seront brisés; il tonnera sur eux dans les cieux. L’ Éternel jugera les bouts de la terre, et il donnera la force à son roi, et élèvera la corne de son oint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Et Elkana s’en alla à Rama, dans sa maison; et le jeune garçon servait l’ Éternel en la présence d’Éli, le sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, '*Et les fils d’Éli étaient des fils de Bélial, ils ne connaissaient pas l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Et la coutume des sacrificateurs à l’égard du peuple [était celle-ci]: quand quelqu’un sacrifiait un sacrifice, le serviteur du sacrificateur venait, lorsqu’on faisait bouillir la chair, ayant en sa main une fourchette à trois dents,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'et il piquait dans la chaudière, ou dans le chaudron, ou dans la marmite, ou dans le pot: le sacrificateur en prenait tout ce que la fourchette amenait en haut. Ils faisaient ainsi à tous ceux d’Israël qui venaient là, à Silo.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Même, avant qu’on ait fait fumer la graisse, le serviteur du sacrificateur venait, et disait à l’homme qui sacrifiait: Donne de la chair à rôtir pour le sacrificateur; et il ne prendra pas de toi de la chair bouillie, mais [de la chair] crue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Si l’homme lui disait: On va d’abord faire fumer la graisse, puis tu prendras selon le désir de ton âme, alors il [lui] disait: Non, car tu en donneras maintenant; sinon, j’en prendrai de force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Et le péché de ces jeunes hommes fut très grand devant l’ Éternel; car les hommes méprisaient l’offrande de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Et Samuel servait devant l’ Éternel, jeune garçon, ceint d’un éphod de lin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Et sa mère lui faisait une petite robe et la lui apportait d’année en année quand elle montait avec son mari pour sacrifier le sacrifice annuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Et Éli bénit Elkana et sa femme, et dit: Que l’ Éternel te donne des enfants de cette femme, à la place du prêt qui a été fait à l’ Éternel! Et ils s’en retournèrent chez lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Et l’ Éternel visita Anne, et elle conçut, et enfanta trois fils et deux filles; et le jeune garçon Samuel grandissait auprès de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Et Éli était fort âgé, et il apprit tout ce que ses fils faisaient à l’égard de tout Israël, et qu’ils couchaient avec les femmes qui servaient à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Et il leur dit: Pourquoi faites-vous des actions comme celles-là? Car, de tout le peuple, j’apprends vos méchantes actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Non, mes fils; car ce que j’entends dire n’est pas bon: vous entraînez à la transgression le peuple de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Si un homme a péché contre un homme, Dieu le jugera; mais si un homme pèche contre l’ Éternel, qui priera pour lui? Mais ils n’écoutèrent pas la voix de leur père, car c’était le bon plaisir de l’ Éternel de les faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Et le jeune garçon Samuel allait grandissant, agréable à l’ Éternel et aux hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Et un homme de Dieu vint vers Éli, et lui dit: Ainsi dit l’ Éternel: Je me suis clairement révélé à la maison de ton père, quand ils étaient en Égypte dans la maison du Pharaon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'et je l’ai choisi d’entre toutes les tribus d’Israël, pour être mon sacrificateur, pour offrir [des sacrifices] sur mon autel, pour faire fumer l’encens, pour porter l’éphod devant moi; et j’ai donné à la maison de ton père tous les sacrifices des fils d’Israël faits par feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Pourquoi foulez-vous aux pieds mon sacrifice et mon offrande, que j’ai commandé [de faire] dans ma demeure? Et tu honores tes fils plus que moi, pour vous engraisser des prémices de toutes les offrandes d’Israël, mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'C’est pourquoi l’ Éternel, le Dieu d’Israël, dit: J’avais bien dit: Ta maison et la maison de ton père marcheront devant moi à toujours; mais maintenant l’ Éternel dit: Que cela soit loin de moi; car ceux qui m’honorent, je les honorerai; et ceux qui me méprisent seront en petite estime.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Voici, les jours viennent que je couperai ton bras et le bras de la maison de ton père, de sorte qu’il n’y aura plus de vieillard dans ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Et tu verras un adversaire [établi dans ma] demeure, dans tout le bien qui aura été fait à Israël; et il n’y aura plus de vieillard dans ta maison à jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Et celui des tiens que je ne retrancherai pas d’auprès de mon autel, sera pour consumer tes yeux et attrister ton âme; et tout l’accroissement de ta maison: – ils mourront à la fleur de l’âge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Et ceci t’en sera le signe: ce qui arrivera à tes deux fils, Hophni et Phinées; ils mourront tous deux en un seul jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Et je me susciterai un sacrificateur fidèle: il fera selon ce qui est dans mon cœur et dans mon âme, et je lui bâtirai une maison stable, et il marchera toujours devant mon oint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Et il arrivera que quiconque restera de ta maison viendra et se prosternera devant lui, pour avoir une pièce d’argent et un rond de pain, et dira: Place-moi, je te prie, dans quelqu’une des charges de la sacrificature, afin que je mange une bouchée de pain!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Et le jeune garçon Samuel servait l’ Éternel devant Éli; et la parole de l’ Éternel était rare en ces jours-là: la vision n’était pas répandue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Et il arriva en ce temps-là, qu’Éli était couché en son lieu (or ses yeux commençaient à être troubles, il ne pouvait voir);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'et la lampe de Dieu n’était pas encore éteinte, et Samuel était couché dans le temple de l’ Éternel, où était l’arche de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'et l’ Éternel appela Samuel. Et il dit: Me voici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Et il courut vers Éli et [lui] dit: Me voici, car tu m’as appelé. Mais il dit: Je n’ai pas appelé; retourne, couche-toi. Et il s’en alla et se coucha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Et l’ Éternel appela de nouveau: Samuel! Et Samuel se leva et alla vers Éli, et [lui] dit: Me voici, car tu m’as appelé. Et il dit: Je n’ai pas appelé, mon fils; retourne, couche-toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Et Samuel ne connaissait pas encore l’ Éternel, et la parole de l’ Éternel ne lui avait pas encore été révélée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Et l’ Éternel appela de nouveau: Samuel! pour la troisième fois; et [Samuel] se leva et alla vers Éli, et [lui] dit: Me voici, car tu m’as appelé. Et Éli s’aperçut que l’ Éternel avait appelé le jeune garçon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Et Éli dit à Samuel: Va, couche-toi; et s’il t’appelle, alors tu diras: Parle, Éternel, car ton serviteur écoute. Et Samuel s’en alla et se coucha en son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Et l’ Éternel vint et se tint là, et appela comme les autres fois: Samuel! Samuel! Et Samuel dit: Parle, car ton serviteur écoute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Et l’ Éternel dit à Samuel: Voici, je vais faire en Israël une chose telle, que quiconque l’entendra, les deux oreilles lui tinteront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'En ce jour-là j’accomplirai sur Éli tout ce que j’ai dit touchant sa maison: je commencerai et j’achèverai;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'car je lui ai déclaré que je vais juger sa maison pour toujours, à cause de l’iniquité qu’il connaît, parce que ses fils se sont avilis et qu’il ne les a pas retenus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'C’est pourquoi j’ai juré à la maison d’Éli: Si jamais propitiation est faite pour l’iniquité de la maison d’Éli, par sacrifice ou par offrande!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Et Samuel resta couché jusqu’au matin; et il ouvrit les portes de la maison de l’ Éternel. Et Samuel craignait de rapporter sa vision à Éli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Et Éli appela Samuel, et [lui] dit: Samuel, mon fils! Et il dit: Me voici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Et [Éli] dit: Quelle est la parole qu’il t’a dite? Je te prie, ne me le cache pas. Ainsi Dieu te fasse, et ainsi il y ajoute, si tu me caches quoi que ce soit de toute la parole qu’il t’a dite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Et Samuel lui rapporta toutes les paroles, et ne les lui cacha pas. Et [Éli] dit: C’est l’ Éternel, qu’il fasse ce qui est bon à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Et Samuel grandissait; et l’ Éternel était avec lui, et il ne laissa tomber à terre aucune de ses paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Et tout Israël, depuis Dan jusqu’à Beër-Shéba, sut que Samuel était établi prophète de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Et l’ Éternel continua d’apparaître à Silo; car l’ Éternel se révélait à Samuel, à Silo, par la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, '*Et ce que Samuel avait dit arriva à tout Israël. Et Israël sortit en bataille à la rencontre des Philistins, et ils campèrent près d’Ében-Ézer; et les Philistins campèrent à Aphek.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Et les Philistins se rangèrent en bataille contre Israël; et la bataille devint générale, et Israël fut battu devant les Philistins; et ils frappèrent environ 4 000 hommes en bataille rangée, dans la campagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Et le peuple rentra dans le camp, et les anciens d’Israël dirent: Pourquoi l’ Éternel nous a-t-il battus aujourd’hui devant les Philistins? Prenons à nous, de Silo, l’arche de l’alliance de l’ Éternel, et qu’elle vienne au milieu de nous et nous sauve de la main de nos ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Et le peuple envoya à Silo, et on apporta de là l’arche de l’alliance de l’ Éternel des armées, qui siège entre les chérubins; et les deux fils d’Éli, Hophni et Phinées, étaient là avec l’arche de l’alliance de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Et aussitôt que l’arche de l’alliance de l’ Éternel entra dans le camp, tout Israël se mit à pousser de grands cris, de sorte que la terre en frémit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Et les Philistins entendirent le bruit des cris, et dirent: Quel est ce bruit de grands cris dans le camp des Hébreux? Et ils surent que l’arche de l’ Éternel était venue dans le camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Et les Philistins craignirent, car ils dirent: Dieu est venu dans le camp. Et ils dirent: Malheur à nous! car il n’en a jamais été ainsi auparavant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Malheur à nous! Qui nous délivrera de la main de ces dieux puissants? Ce sont là les dieux qui ont frappé les Égyptiens de toutes sortes de plaies dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Philistins, fortifiez-vous et soyez hommes, de peur que vous ne soyez asservis aux Hébreux, comme ils vous ont été asservis! Soyez hommes, et combattez!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Et les Philistins combattirent, et Israël fut battu; et ils s’enfuirent chacun à sa tente; et la défaite fut très grande, et il tomba d’Israël 30 000 hommes de pied.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Et l’arche de Dieu fut prise, et les deux fils d’Éli, Hophni et Phinées, moururent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Et un homme de Benjamin courut de la bataille, et vint à Silo ce même jour, ayant ses vêtements déchirés, et de la terre sur sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Et il entra, et voici, Éli était assis sur un siège, aux aguets, à côté du chemin; car son cœur tremblait pour l’arche de Dieu. Et l’homme entra pour annoncer dans la ville [ce qui était arrivé]; et toute la ville jeta des cris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Et Éli entendit le bruit des cris, et dit: Qu’est-ce que ce bruit de tumulte? Et l’homme vint en hâte et informa Éli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Or Éli était âgé de 98 ans, et il avait les yeux fixes et il ne pouvait voir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Et l’homme dit à Éli: Je viens de la bataille, et je me suis enfui de la bataille aujourd’hui. Et [Éli] dit: Qu’est-il arrivé, mon fils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Et celui qui portait le message répondit et dit: Israël a fui devant les Philistins, et même il y a eu une grande défaite du peuple, et aussi tes deux fils, Hophni et Phinées, sont morts, et l’arche de Dieu est prise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Et il arriva que, lorsqu’il mentionna l’arche de Dieu, [Éli] tomba à la renverse de dessus son siège, à côté de la porte, et se brisa la nuque et mourut; car c’était un homme âgé et pesant. Et il avait jugé Israël 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Et sa belle-fille, femme de Phinées, était enceinte, près d’accoucher; et elle entendit la nouvelle que l’arche de Dieu était prise, et que son beau-père et son mari étaient morts, et elle se courba et enfanta, car les douleurs la surprirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Et comme elle se mourait, celles qui se tenaient auprès d’elle [lui] dirent: Ne crains point, car tu as enfanté un fils. Et elle ne répondit pas et n’y fit pas attention;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'et elle appela l’enfant I-Cabod, disant: La gloire s’en est allée d’Israël; – parce que l’arche de Dieu était prise, et à cause de son beau-père et de son mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Et elle dit: La gloire s’en est allée d’Israël, car l’arche de Dieu est prise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Et les Philistins prirent l’arche de Dieu et la transportèrent d’Ében-Ézer à Asdod.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Et les Philistins prirent l’arche de Dieu et l’apportèrent dans la maison de Dagon et la placèrent à côté de Dagon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Et le lendemain, les Asdodiens se levèrent de bonne heure, et voici, Dagon était gisant sur sa face contre terre, devant l’arche de l’ Éternel; et ils prirent Dagon et le remirent à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Et ils se levèrent de bonne heure le lendemain matin, et voici, Dagon était gisant sur sa face contre terre, devant l’arche de l’ Éternel; et la tête de Dagon et les deux paumes de ses mains coupées étaient sur le seuil; le Dagon seul était resté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'C’est pourquoi les sacrificateurs de Dagon, et tous ceux qui entrent dans la maison de Dagon, ne marchent pas sur le seuil de Dagon, à Asdod, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Et la main de l’ Éternel s’appesantit sur les Asdodiens, et il les désola; et il frappa d’hémorroïdes Asdod et ses confins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Et les hommes d’Asdod, voyant qu’il en était ainsi, dirent: L’arche du dieu d’Israël ne restera pas avec nous; car sa main pèse durement sur nous et sur Dagon, notre dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Et ils envoyèrent, et assemblèrent auprès d’eux tous les princes des Philistins, et dirent: Que ferons-nous de l’arche du dieu d’Israël? Et ils dirent: Qu’on dirige l’arche du dieu d’Israël vers Gath. Et ils y dirigèrent l’arche du Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Et, après qu’ils l’y eurent dirigée, il arriva que la main de l’ Éternel fut sur la ville: il y eut un très grand trouble, et il frappa les hommes de la ville, depuis le petit jusqu’au grand, et ils eurent des éruptions d’hémorroïdes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Et ils envoyèrent l’arche de Dieu à Ékron. Et il arriva, comme l’arche de Dieu entrait à Ékron, que les Ékroniens poussèrent des cris, disant: Ils ont dirigé vers nous l’arche du dieu d’Israël, pour nous faire mourir, nous et notre peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Et ils envoyèrent, et assemblèrent tous les princes des Philistins, et dirent: Renvoyez l’arche du dieu d’Israël, et qu’elle retourne en son lieu, afin qu’elle ne nous fasse pas mourir, nous et notre peuple. Car il y avait une consternation mortelle dans toute la ville: la main de Dieu s’y appesantissait fort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'et les hommes qui ne mouraient pas étaient frappés d’hémorroïdes; et le cri de la ville montait aux cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Et l’arche de l’ Éternel fut sept mois dans le pays des Philistins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'et les Philistins appelèrent les sacrificateurs et les devins, disant: Que ferons-nous de l’arche de l’ Éternel? Faites-nous savoir comment nous la renverrons en son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Et ils dirent: Si vous renvoyez l’arche du dieu d’Israël, ne la renvoyez pas à vide; ne manquez pas de lui rendre un sacrifice pour le délit; alors vous serez guéris, et vous saurez pourquoi sa main ne s’est pas retirée de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Et ils dirent: Quel est le sacrifice pour le délit que nous lui rendrons? Et ils dirent: Selon le nombre des princes des Philistins, cinq hémorroïdes d’or, et cinq souris d’or; car une même plaie a été sur vous tous et sur vos princes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Et vous ferez des figures de vos hémorroïdes, et des figures de vos souris qui détruisent le pays, et vous donnerez gloire au dieu d’Israël. Peut-être allégera-t-il sa main de dessus vous, et de dessus vos dieux, et de dessus votre pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Et pourquoi endurciriez-vous votre cœur, comme les Égyptiens et le Pharaon ont endurci leur cœur? Après qu’il eut opéré puissamment parmi eux, ne les laissèrent-ils pas aller? et ils s’en allèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Et maintenant, faites un chariot neuf, et prenez deux vaches qui allaitent, sur lesquelles le joug n’ait jamais été mis, et attelez les vaches au chariot, et faites ramener à la maison leurs petits d’auprès d’elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Et prenez l’arche de l’ Éternel, et mettez-la sur le chariot, et mettez dans un coffret, à côté d’elle, les objets d’or que vous lui rendez comme offrande pour le délit; et vous la renverrez, et elle s’en ira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Et vous verrez: si elle monte par le chemin de sa frontière, vers Beth-Shémesh, c’est lui qui nous a fait ce grand mal; sinon, nous saurons que ce n’est pas sa main qui nous a frappés, [mais] que c’est une chose accidentelle qui nous est arrivée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Et les hommes firent ainsi, et prirent deux vaches qui allaitaient, et les attelèrent au chariot, et enfermèrent leurs petits dans la maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'et ils mirent l’arche de l’ Éternel sur le chariot, et le coffret, avec les souris d’or et les figures de leurs hémorroïdes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Et les vaches allèrent tout droit par le chemin, du côté de Beth-Shémesh; elles marchèrent par une seule route, allant et mugissant, et elles ne se détournèrent ni à droite ni à gauche; et les princes des Philistins allèrent après elles jusqu’à la frontière de Beth-Shémesh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Et ceux de Beth-Shémesh moissonnaient les froments dans la vallée; et ils levèrent leurs yeux et virent l’arche, et se réjouirent en la voyant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Et le chariot vint au champ de Josué, le Beth-Shémite, et s’arrêta là. Et il y avait là une grande pierre; et ils fendirent le bois du chariot, et offrirent les vaches en holocauste à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Et les Lévites descendirent l’arche de l’ Éternel, et le coffret qui était auprès, dans lequel étaient les objets d’or, et ils les mirent sur la grande pierre. Et les hommes de Beth-Shémesh offrirent en ce jour des holocaustes et sacrifièrent des sacrifices à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Et les cinq princes des Philistins virent cela, et s’en retournèrent à Ékron ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Et ce sont ici les hémorroïdes d’or que les Philistins rendirent à l’ Éternel comme offrande pour le délit: pour Asdod une, pour Gaza une, pour Askalon une, pour Gath une, pour Ékron une;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'et les souris d’or, selon le nombre de toutes les villes des Philistins, des cinq princes, depuis les villes fortifiées jusqu’aux villages des campagnards; et [ils les amenèrent] jusqu’à la grande [pierre d’]Abel, sur laquelle ils posèrent l’arche de l’ Éternel; elle est jusqu’à ce jour dans le champ de Josué, le Beth-Shémite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Et [l’ Éternel] frappa des hommes de Beth-Shémesh, car ils regardèrent dans l’arche de l’ Éternel; et il frappa du peuple 70 hommes; et le peuple mena deuil, parce que l’ Éternel avait frappé le peuple d’un grand coup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Et les hommes de Beth-Shémesh dirent: Qui peut tenir devant l’ Éternel, ce Dieu saint? Et vers qui montera-t-il de chez nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Et ils envoyèrent des messagers aux habitants de Kiriath-Jéarim, disant: Les Philistins ont ramené l’arche de l’ Éternel: descendez, faites-la monter vers vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Et les hommes de Kiriath-Jéarim vinrent, et firent monter l’arche de l’ Éternel et l’apportèrent dans la maison d’Abinadab, sur la colline; et ils sanctifièrent Éléazar, son fils, pour garder l’arche de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, '*Et il arriva que, depuis le jour où l’arche demeura à Kiriath-Jéarim, il se passa un long temps, 20 années; et toute la maison d’Israël se lamenta après l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Et Samuel parla à toute la maison d’Israël, disant: Si de tout votre cœur vous retournez à l’ Éternel, ôtez du milieu de vous les dieux étrangers, et les Ashtoreths, et attachez fermement votre cœur à l’ Éternel, et servez-le lui seul; et il vous délivrera de la main des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Et les fils d’Israël ôtèrent les Baals et les Ashtoreths, et servirent l’ Éternel seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Et Samuel dit: Assemblez tout Israël à Mitspa, et je prierai l’ Éternel pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Et ils s’assemblèrent à Mitspa, et ils puisèrent de l’eau et la répandirent devant l’ Éternel; et ils jeûnèrent ce jour-là, et dirent là: Nous avons péché contre l’ Éternel. Et Samuel jugea les fils d’Israël à Mitspa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Et les Philistins apprirent que les fils d’Israël s’étaient assemblés à Mitspa, et les princes des Philistins montèrent contre Israël; et les fils d’Israël l’apprirent, et eurent peur des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Et les fils d’Israël dirent à Samuel: Ne cesse pas de crier pour nous à l’ Éternel, notre Dieu, afin qu’il nous sauve de la main des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Et Samuel prit un agneau de lait, et l’offrit tout entier à l’ Éternel en holocauste; et Samuel cria à l’ Éternel pour Israël, et l’ Éternel l’exauça.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Comme Samuel offrait l’holocauste, les Philistins s’approchèrent pour livrer bataille à Israël; et l’ Éternel fit tonner ce jour-là un grand tonnerre sur les Philistins, et les mit en déroute, et ils furent battus devant Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Et les hommes d’Israël sortirent de Mitspa et poursuivirent les Philistins, et les frappèrent jusqu’au-dessous de Beth-Car.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Et Samuel prit une pierre et la plaça entre Mitspa et le rocher, et il appela son nom Ében-Ézer, et dit: L’ Éternel nous a secourus jusqu’ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Et les Philistins furent abaissés, et ils n’entrèrent plus dans les confins d’Israël; et la main de l’ Éternel fut sur les Philistins pendant tous les jours de Samuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Et les villes que les Philistins avaient prises sur Israël retournèrent à Israël, depuis Ékron jusqu’à Gath; et Israël délivra leur territoire de la main des Philistins. Et il y eut paix entre Israël et l’Amoréen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Et Samuel jugea Israël tous les jours de sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Et il allait d’année en année, et faisait le tour, à Béthel, et à Guilgal, et à Mitspa, et jugeait Israël dans tous ces lieux-là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'et il s’en retournait à Rama, car là était sa maison, et là il jugeait Israël; et il bâtit là un autel à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Et il arriva que, lorsque Samuel fut vieux, il établit ses fils juges sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Et le nom de son fils premier-né était Joël, et le nom de son second [fils], Abija: ils jugeaient à Beër-Shéba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Et ses fils ne marchaient pas dans ses voies; mais ils se détournaient après le gain déshonnête, et prenaient des présents, et faisaient fléchir le jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Et tous les anciens d’Israël s’assemblèrent et vinrent vers Samuel, à Rama;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'et ils lui dirent: Voici, tu es vieux, et tes fils ne marchent pas dans tes voies; maintenant, établis sur nous un roi pour nous juger, comme toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Et la chose fut mauvaise aux yeux de Samuel, qu’ils aient dit: Donne-nous un roi pour nous juger. Et Samuel pria l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Et l’ Éternel dit à Samuel: Écoute la voix du peuple en tout ce qu’ils te disent; car ce n’est pas toi qu’ils ont rejeté, mais c’est moi qu’ils ont rejeté, afin que je ne règne pas sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Selon toutes les actions qu’ils ont commises, depuis le jour où je les ai fait monter d’Égypte, jusqu’à ce jour, en ce qu’ils m’ont abandonné et ont servi d’autres dieux: ainsi ils font aussi à ton égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Et maintenant, écoute leur voix; seulement tu leur rendras clairement témoignage, et tu leur annonceras le régime du roi qui régnera sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Et Samuel dit toutes les paroles de l’ Éternel au peuple qui lui demandait un roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Et il dit: Ce sera ici le régime du roi qui régnera sur vous: il prendra vos fils et les mettra pour lui sur son char et parmi ses cavaliers, et ils courront devant son char;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'et [il les prendra] pour s’en faire des chefs de milliers et des chefs de cinquantaines, et pour labourer ses champs, et pour récolter sa moisson, et pour faire ses instruments de guerre et l’attirail de ses chars.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Et il prendra vos filles pour parfumeuses et pour cuisinières et pour boulangères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Et il prendra vos champs et vos vignes et vos oliviers, les meilleurs, et les donnera à ses serviteurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'et il prendra la dîme de vos semences et de vos vignes, et la donnera à ses eunuques et à ses serviteurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'et il prendra vos serviteurs et vos servantes et vos jeunes hommes d’élite, les meilleurs, et vos ânes, et les emploiera à ses ouvrages;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'il dîmera votre menu bétail, et vous serez ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Et en ce jour-là vous crierez à cause de votre roi que vous vous serez choisi; mais l’ Éternel ne vous exaucera pas, en ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Et le peuple refusa d’écouter la voix de Samuel; et ils dirent: Non, mais il y aura un roi sur nous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'et nous serons, nous aussi, comme toutes les nations; et notre roi nous jugera, et il sortira devant nous et conduira nos guerres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Et Samuel écouta toutes les paroles du peuple, et les rapporta aux oreilles de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Et l’ Éternel dit à Samuel: Écoute leur voix, et établis sur eux un roi. Et Samuel dit aux hommes d’Israël: Allez chacun dans sa ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, '*Et il y avait un homme de Benjamin, et son nom était Kis, homme fort et vaillant, fils d’Abiel, fils de Tseror, fils de Becorath, fils d’Aphiakh, fils d’un Benjaminite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'et il avait un fils, et son nom était Saül, homme d’élite et beau; et il n’y avait aucun des fils d’Israël qui soit plus beau que lui; il était plus grand que tout le peuple, depuis les épaules en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Et les ânesses de Kis, père de Saül, s’étaient perdues; et Kis dit à Saül, son fils: Prends, je te prie, avec toi un des jeunes hommes, et lève-toi, va, cherche les ânesses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Et il passa par la montagne d’Éphraïm, et passa par le pays de Shalisha; et ils ne les trouvèrent pas; et ils passèrent par le pays de Shaalim, mais elles n’y étaient pas; et il passa par le pays de Benjamin, mais ils ne les trouvèrent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Quand ils furent venus dans le pays de Tsuph, Saül dit à son serviteur qui était avec lui: Viens, et retournons-nous-en, de peur que mon père n’ait cessé de penser aux ânesses, et qu’il ne soit en peine de nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Et il lui dit: Voici, je te prie, il y a un homme de Dieu dans cette ville, et c’est un homme considéré; tout ce qu’il dit arrive infailliblement: allons-y maintenant, peut-être nous enseignera-t-il le chemin par lequel nous devons aller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Et Saül dit à son serviteur: Mais si nous y allons, que porterons-nous à l’homme? car le pain manque dans nos sacs, et il n’y a pas de présent à porter à l’homme de Dieu. Qu’avons-nous avec nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Et le serviteur répondit de nouveau à Saül et dit: Voici, il se trouve que j’ai en main le quart d’un sicle d’argent, et je le donnerai à l’homme de Dieu, et il nous enseignera notre chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(Autrefois, en Israël, un homme, quand il allait consulter Dieu, disait ainsi: Venez, et allons vers le voyant. Car celui qu’on appelle prophète aujourd’hui, se nommait autrefois le voyant.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Et Saül dit à son serviteur: Tu dis bien; viens, allons. Et ils allèrent à la ville où était l’homme de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Comme ils montaient la montée de la ville, ils trouvèrent des jeunes filles qui sortaient pour puiser de l’eau, et ils leur dirent: Le voyant est-il ici?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Et elles leur répondirent et dirent: Il y est; le voilà devant toi: hâte-toi maintenant, car aujourd’hui il est venu à la ville, parce que le peuple a aujourd’hui un sacrifice sur le haut lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Aussitôt que vous serez entrés dans la ville, vous le trouverez, avant qu’il monte au haut lieu pour manger; car le peuple ne mange pas, jusqu’à ce qu’il soit venu, parce que c’est lui qui bénit le sacrifice; après cela, les conviés mangent. Et maintenant, montez, car vous le trouverez précisément aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Et ils montèrent à la ville. Comme ils entraient dans la ville, voilà Samuel qui sortait au-devant d’eux pour monter au haut lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Or, un jour avant que Saül vienne, l’ Éternel avait averti Samuel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Demain, à cette heure, je t’enverrai un homme du pays de Benjamin, et tu l’oindras pour être prince sur mon peuple Israël; et il sauvera mon peuple de la main des Philistins; car j’ai regardé mon peuple, car son cri est parvenu jusqu’à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Et comme Samuel vit Saül, l’ Éternel lui répondit: Voilà l’homme dont je t’ai parlé; c’est lui qui dominera sur mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Et Saül s’approcha de Samuel, au milieu de la porte, et [lui] dit: Je te prie, montre-moi où est la maison du voyant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Et Samuel répondit à Saül et dit: Moi, je suis le voyant; monte devant moi au haut lieu, et vous mangerez avec moi aujourd’hui, et le matin je te laisserai aller; et je te déclarerai tout ce qui est dans ton cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Et quant aux ânesses que tu as perdues, il y a aujourd’hui trois jours, n’en sois pas en peine, car elles sont trouvées. Et vers qui est [tourné] tout le désir d’Israël? N’est-ce pas vers toi et vers toute la maison de ton père?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Et Saül répondit et dit: Ne suis-je pas Benjaminite, de la plus petite des tribus d’Israël? et ma famille n’est-elle pas la moindre de toutes les familles de la tribu de Benjamin? Et pourquoi me dis-tu de telles choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Et Samuel prit Saül et son jeune homme, et les fit entrer dans la salle, et leur donna place à la tête des invités; et ils étaient environ 30 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Et Samuel dit au cuisinier: Donne la portion que je t’ai donnée, dont je t’ai dit: Serre-la par-devers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Et le cuisinier leva l’épaule, et ce qui était dessus, et il la mit devant Saül. Et [Samuel] dit: Voici ce qui a été réservé; mets-le devant toi [et] mange; car cela a été gardé pour toi, pour le temps fixé, lorsque j’ai dit: J’inviterai le peuple. Et Saül mangea avec Samuel ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Et ils descendirent du haut lieu dans la ville, et [Samuel] parla avec Saül sur le toit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Et ils se levèrent de bonne heure. Et comme l’aurore se levait, Samuel appela Saül sur le toit, disant: Lève-toi, et je te laisserai aller. Et Saül se leva, et ils sortirent les deux dehors, lui et Samuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Comme ils descendaient au bout de la ville, Samuel dit à Saül: Dis au jeune homme qu’il passe devant nous (et il passa); et toi, arrête-toi maintenant, et je te ferai entendre la parole de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Et Samuel prit une fiole d’huile et la versa sur la tête de Saül, et il l’embrassa, et dit: L’ Éternel ne t’a-t-il pas oint pour prince sur son héritage?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'En t’en allant aujourd’hui d’avec moi, tu trouveras deux hommes près du sépulcre de Rachel, sur la frontière de Benjamin, à Tseltsakh, et ils te diront: Les ânesses que tu étais allé chercher sont trouvées; et voici, ton père a oublié l’affaire des ânesses, et il est en peine de vous, disant: Que ferai-je au sujet de mon fils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Et de là tu passeras plus loin, et tu viendras au chêne de Thabor; et là te trouveront trois hommes qui montent vers Dieu à Béthel, l’un portant trois chevreaux, l’autre portant trois gâteaux de pain, et l’autre portant une outre de vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Et ils te demanderont comment tu te portes, et ils te donneront deux pains, et tu les prendras de leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Après cela, tu viendras au coteau de Dieu, où sont des postes des Philistins; et il arrivera qu’en entrant là, dans la ville, tu rencontreras une troupe de prophètes descendant du haut lieu, ayant devant eux un luth, un tambourin, une flûte, et une harpe, et eux-mêmes prophétisant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Et l’Esprit de l’ Éternel te saisira, et tu prophétiseras avec eux, et tu seras changé en un autre homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Et lorsque ces signes te seront arrivés, tu feras ce qui se présentera à toi; car Dieu est avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Et tu descendras devant moi à Guilgal; et voici, je descendrai vers toi pour offrir des holocaustes et sacrifier des sacrifices de prospérités; tu attendras sept jours, jusqu’à ce que je vienne vers toi, et je te ferai savoir ce que tu devras faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Et il arriva que, lorsque [Saül] tourna le dos pour s’en aller d’avec Samuel, Dieu lui changea son cœur en un autre; et tous ces signes eurent lieu ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Et ils arrivèrent là, au coteau; et voici, une troupe de prophètes [venait] à sa rencontre, et l’Esprit de Dieu le saisit, et il prophétisa au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Et il arriva que, quand tous ceux qui l’avaient connu auparavant virent qu’il prophétisait avec les prophètes, les gens se dirent l’un à l’autre: Qu’est-il donc arrivé au fils de Kis? Saül aussi est-il parmi les prophètes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Et quelqu’un de là répondit et dit: Et qui est leur père? C’est pourquoi cela passa en proverbe: Saül aussi est-il parmi les prophètes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Et quand [Saül] eut cessé de prophétiser, il vint au haut lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Et l’oncle de Saül lui dit, à lui et à son jeune homme: Où êtes-vous allés? Et il dit: Chercher les ânesses; mais voyant qu’elles n’étaient nulle part, nous sommes allés vers Samuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Et l’oncle de Saül dit: Déclare-moi, je te prie, ce que vous a dit Samuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Et Saül dit à son oncle: Il nous a déclaré expressément que les ânesses étaient trouvées. Mais quant à l’affaire du royaume, dont Samuel avait parlé, il ne la lui déclara pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Et Samuel convoqua le peuple devant l’ Éternel à Mitspa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Et il dit aux fils d’Israël: Ainsi a dit l’ Éternel, le Dieu d’Israël: Moi, j’ai fait monter Israël hors d’Égypte, et je vous ai délivrés de la main des Égyptiens et de la main de tous les royaumes qui vous opprimaient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'et vous, aujourd’hui, vous avez rejeté votre Dieu, lui qui vous a sauvés de tous vos maux et de toutes vos détresses, et vous lui avez dit: [Non], mais établis un roi sur nous. Et maintenant, tenez-vous devant l’ Éternel, selon vos tribus et selon vos milliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Et Samuel fit approcher toutes les tribus d’Israël, et la tribu de Benjamin fut prise;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'et il fit approcher la tribu de Benjamin selon ses familles, et la famille de Matri fut prise; et Saül, fils de Kis, fut pris: et on le chercha, mais on ne le trouva pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Et ils interrogèrent encore l’ Éternel: L’homme viendra-t-il encore ici? Et l’ Éternel dit: Voici, il s’est caché parmi les bagages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Et ils coururent, et le prirent de là; et il se tint au milieu du peuple, et il était plus grand que tout le peuple, depuis les épaules en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Et Samuel dit à tout le peuple: Voyez-vous celui que l’ Éternel a choisi? Il n’y en a point comme lui dans tout le peuple. Et tout le peuple poussa des cris, et dit: Vive le roi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Et Samuel dit au peuple le droit du royaume, et il l’écrivit dans un livre, et le posa devant l’ Éternel. Et Samuel renvoya tout le peuple, chacun à sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Et Saül aussi s’en alla à sa maison, à Guibha; et la troupe de ceux dont Dieu avait touché le cœur alla avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Et des fils de Bélial dirent: Comment celui-ci nous sauverait-il? Et ils le méprisèrent et ne lui apportèrent point de présent; et il fit le sourd.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, '*Et Nakhash, l’Ammonite, monta et campa contre Jabès de Galaad. Et tous les hommes de Jabès dirent à Nakhash: Fais alliance avec nous, et nous te servirons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Et Nakhash, l’Ammonite, leur dit: Je traiterai avec vous, à la condition que je vous crève à tous l’œil droit et que j’en mette l’opprobre sur tout Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Et les anciens de Jabès lui dirent: Donne-nous un délai de sept jours, et nous enverrons des messagers dans tous les confins d’Israël; et s’il n’y a personne qui nous sauve, alors nous sortirons vers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Et les messagers vinrent à Guibha de Saül, et dirent ces paroles aux oreilles du peuple. Et tout le peuple éleva sa voix, et pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Et voici, Saül venait des champs, derrière ses bœufs; et Saül dit: Qu’a donc le peuple, pour qu’ils pleurent? Et on lui raconta les paroles des hommes de Jabès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Et l’Esprit de Dieu saisit Saül, lorsqu’il entendit ces paroles, et sa colère s’embrasa fortement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Et il prit une paire de bœufs, et les coupa en morceaux, et envoya dans tous les confins d’Israël par des messagers, en disant: Celui qui ne sortira pas après Saül et après Samuel, on fera ainsi à ses bœufs. Et la frayeur de l’ Éternel tomba sur le peuple, et ils sortirent comme un seul homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Et [Saül] les dénombra en Bézek; et les fils d’Israël étaient 300 000, et les hommes de Juda 30 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Et ils dirent aux messagers qui étaient venus: Vous direz ainsi aux hommes de Jabès de Galaad: Demain vous serez délivrés, quand le soleil sera dans sa chaleur. Et les messagers vinrent et rapportèrent cela aux hommes de Jabès, et ils s’en réjouirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Et les hommes de Jabès dirent [aux Ammonites]: Demain nous sortirons vers vous, et vous nous ferez selon tout ce qui sera bon à vos yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Et il arriva que, le lendemain, Saül rangea le peuple en trois corps; et ils entrèrent au milieu du camp pendant la veille du matin, et ils frappèrent Ammon jusqu’à la chaleur du jour; et ceux qui restèrent furent dispersés; et il n’en resta pas deux ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Et le peuple dit à Samuel: Qui est-ce qui a dit: Saül régnera-t-il sur nous? Livrez ces hommes, et nous les ferons mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Et Saül dit: On ne fera mourir personne en ce jour, car l’ Éternel a opéré aujourd’hui une délivrance en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Et Samuel dit au peuple: Venez, et allons à Guilgal, et nous y renouvellerons la royauté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Et tout le peuple s’en alla à Guilgal; et là ils établirent Saül pour roi, devant l’ Éternel, à Guilgal; et ils sacrifièrent là des sacrifices de prospérités devant l’ Éternel; et Saül et tous les hommes d’Israël firent là de grandes réjouissances.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, '*Et Samuel dit à tout Israël: Voici, j’ai écouté votre voix en tout ce que vous m’avez dit, et j’ai établi un roi sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Et maintenant, voici, le roi marche devant vous; et moi, je suis vieux et j’ai blanchi; et voici, mes fils sont avec vous; et moi, j’ai marché devant vous depuis ma jeunesse jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Me voici, témoignez contre moi, devant l’ Éternel et devant son oint. De qui ai-je pris le bœuf? ou de qui ai-je pris l’âne? ou à qui ai-je fait tort? à qui ai-je fait violence? ou de la main de qui ai-je pris un présent pour que par lui j’aie fermé mes yeux? et je vous le rendrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Et ils dirent: Tu ne nous as point fait tort, et tu ne nous as point fait violence, et tu n’as rien pris de la main de personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Et il leur dit: L’ Éternel est témoin contre vous, et son oint est témoin aujourd’hui, que vous n’avez rien trouvé dans ma main. Et ils dirent: [Il en est] témoin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Et Samuel dit au peuple: C’est l’ Éternel qui a établi Moïse et Aaron, et qui a fait monter vos pères du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Et maintenant, présentez-vous, et je vous jugerai devant l’ Éternel au sujet de tous les actes justes de l’ Éternel, qu’il a opérés envers vous et envers vos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Quand Jacob fut entré en Égypte, vos pères crièrent à l’ Éternel, et l’ Éternel envoya Moïse et Aaron; et ils firent sortir vos pères hors d’Égypte, et les firent habiter dans ce lieu-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Et ils oublièrent l’ Éternel, leur Dieu, et il les vendit en la main de Sisera, chef de l’armée de Hatsor, et en la main des Philistins, et en la main du roi de Moab, qui leur firent la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Et ils crièrent à l’ Éternel, et dirent: Nous avons péché; car nous avons abandonné l’ Éternel, et nous avons servi les Baals et les Ashtoreths. Et maintenant, délivre-nous de la main de nos ennemis, et nous te servirons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Et l’ Éternel envoya Jerubbaal, et Bedan, et Jephthé, et Samuel, et il vous délivra de la main de vos ennemis tout autour, et vous avez habité en sécurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Et vous avez vu que Nakhash, roi des fils d’Ammon, venait contre vous, et vous m’avez dit: Non, mais un roi régnera sur nous, – et l’ Éternel, votre Dieu, était votre roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Et maintenant, voici le roi que vous avez choisi, que vous avez demandé; et voici, l’ Éternel a mis un roi sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Si vous craignez l’ Éternel et que vous le serviez, et que vous écoutiez sa voix, et que vous ne soyez pas rebelles au commandement de l’ Éternel, alors vous, et le roi qui règne sur vous, vous irez après l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Mais si vous n’écoutez pas la voix de l’ Éternel, et si vous vous rebellez contre le commandement de l’ Éternel, alors la main de l’ Éternel sera contre vous comme contre vos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Aussi, tenez-vous là maintenant, et voyez cette grande chose que l’ Éternel va opérer devant vos yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'N’est-ce pas aujourd’hui la moisson des froments? Je crierai à l’ Éternel, et il enverra des tonnerres et de la pluie; et vous saurez et vous verrez que le mal que vous avez fait est grand aux yeux de l’ Éternel, d’avoir demandé un roi pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Et Samuel cria à l’ Éternel, et l’ Éternel envoya des tonnerres et de la pluie, ce jour-là; et tout le peuple craignit beaucoup l’ Éternel et Samuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Et tout le peuple dit à Samuel: Prie l’ Éternel, ton Dieu, pour tes serviteurs, afin que nous ne mourions point; car, à tous nos péchés, nous avons ajouté ce mal d’avoir demandé un roi pour nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Et Samuel dit au peuple: Ne craignez pas. Vous avez fait tout ce mal, seulement ne vous détournez pas de l’ Éternel, et servez l’ Éternel de tout votre cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'et ne vous détournez point, car [ce serait vous en aller] après des choses de néant, qui ne profitent pas et ne délivrent pas, car ce sont des choses de néant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Car l’ Éternel, à cause de son grand nom, n’abandonnera point son peuple, parce que l’ Éternel s’est plu à faire de vous son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Quant à moi aussi, loin de moi que je pèche contre l’ Éternel, que je cesse de prier pour vous; mais je vous enseignerai le bon et le droit chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Seulement, craignez l’ Éternel, et servez-le en vérité, de tout votre cœur; car voyez quelles grandes choses il a faites pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Mais si vous vous adonnez au mal, vous périrez, vous et votre roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, '*Saül était âgé de ... ans lorsqu’il devint roi; et il régna deux ans sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, '– Et Saül se choisit d’Israël 3 000 hommes: il y en avait 2 000 avec Saül, à Micmash et sur la montagne de Béthel, et 1 000 étaient avec Jonathan à Guibha de Benjamin. Et il renvoya le reste du peuple, chacun à sa tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Et Jonathan frappa le poste des Philistins qui était à Guéba, et les Philistins l’apprirent; et Saül sonna de la trompette par tout le pays, disant: Que les Hébreux l’entendent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Et tout Israël entendit dire: Saül a frappé le poste des Philistins, et aussi Israël est détesté par les Philistins. Et le peuple se rassembla auprès de Saül à Guilgal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Et les Philistins s’assemblèrent pour faire la guerre à Israël: 30 000 chars, et 6 000 cavaliers, et un peuple nombreux comme le sable qui est sur le bord de la mer; et ils montèrent et campèrent à Micmash, à l’orient de Beth-Aven.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Et les hommes d’Israël se virent dans la détresse, car le peuple était serré de près; et le peuple se cacha dans les cavernes, et dans les broussailles, et dans les rochers, et dans les lieux forts, et dans les fosses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Et les Hébreux passèrent le Jourdain [pour aller] au pays de Gad et de Galaad. Et Saül était encore à Guilgal, et tout le peuple le suivait en tremblant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Et [Saül] attendit sept jours, jusqu’au temps assigné par Samuel. Et Samuel ne venait point à Guilgal, et le peuple se dispersait d’auprès de [Saül].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Et Saül dit: Amenez-moi l’holocauste et les sacrifices de prospérités. Et il offrit l’holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Et comme il achevait d’offrir l’holocauste, voici que Samuel vint; et Saül sortit à sa rencontre pour le saluer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Et Samuel dit: Qu’as-tu fait? Et Saül dit: Parce que je voyais que le peuple se dispersait d’auprès de moi, et que tu ne venais pas au jour assigné, et que les Philistins étaient assemblés à Micmash,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'j’ai dit: Maintenant les Philistins descendront contre moi à Guilgal, et je n’ai pas supplié l’ Éternel. Et je me suis fait violence et j’ai offert l’holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Et Samuel dit à Saül: Tu as agi follement, tu n’as pas gardé le commandement de l’ Éternel, ton Dieu, qu’il t’avait ordonné; car maintenant l’ Éternel aurait établi pour toujours ton règne sur Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'et maintenant ton règne ne subsistera pas: l’ Éternel s’est cherché un homme selon son cœur, et l’ Éternel l’a établi prince sur son peuple, car tu n’as pas gardé ce que l’ Éternel t’avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Et Samuel se leva et monta de Guilgal à Guibha de Benjamin. Et Saül dénombra le peuple qui se trouvait avec lui, environ 600 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Et Saül et Jonathan, son fils, et le peuple qui se trouvait avec eux, demeuraient à Guéba de Benjamin, et les Philistins campaient à Micmash.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Et les ravageurs sortirent du camp des Philistins en trois corps: un corps prit le chemin d’Ophra, vers le pays de Shual,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'et un corps prit le chemin de Beth-Horon, et un corps prit le chemin de la frontière qui regarde la vallée de Tseboïm, vers le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Et il ne se trouvait pas de forgeron dans tout le pays d’Israël; car les Philistins avaient dit: Que les Hébreux ne puissent faire ni épée ni lance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Et tout Israël descendait vers les Philistins pour aiguiser chacun son soc, et sa houe, et sa hache, et sa faucille,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'lorsque le tranchant des faucilles et des houes et des tridents et des haches était émoussé, et pour redresser un aiguillon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Et il arriva que, le jour du combat, il ne se trouva ni épée ni lance dans la main de tout le peuple qui était avec Saül et avec Jonathan; il ne s’en trouvait que chez Saül et chez Jonathan, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Et le poste des Philistins sortit pour [occuper] le passage de Micmash.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, '*Et il arriva qu’un jour Jonathan, fils de Saül, dit au jeune homme qui portait ses armes: Viens, et passons jusqu’au poste des Philistins qui est là, de l’autre côté; mais il n’en avertit pas son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Et Saül se tenait à l’extrémité de Guibha, sous un grenadier qui était à Migron; et le peuple qui était avec lui était d’environ 600 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Et Akhija, fils d’Akhitub, frère d’I-Cabod, fils de Phinées, fils d’Éli, sacrificateur de l’ Éternel à Silo, portait l’éphod. Et le peuple ne savait pas que Jonathan s’en était allé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Et entre les passages par lesquels Jonathan cherchait à passer vers le poste des Philistins, il y avait une dent de rocher d’un côté, et une dent de rocher de l’autre côté: et le nom de l’une était Botsets, et le nom de l’autre Séné;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'l’une des dents se dressait à pic du côté du nord, vis-à-vis de Micmash, et l’autre, du côté du midi, vis-à-vis de Guéba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Et Jonathan dit au jeune homme qui portait ses armes: Viens, et passons jusqu’au poste de ces incirconcis; peut-être que l’ Éternel opérera pour nous, car rien n’empêche l’ Éternel de sauver, avec beaucoup ou avec peu [de gens].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Et celui qui portait ses armes lui dit: Fais tout ce qui est dans ton cœur; va où tu voudras, voici, je suis avec toi selon ton cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Et Jonathan dit: Voici, nous allons passer vers ces hommes et nous nous montrerons à eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'S’ils nous disent ainsi: Tenez-vous là jusqu’à ce que nous vous joignions, alors nous nous tiendrons à notre place, et nous ne monterons pas vers eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'et s’ils disent ainsi: Montez vers nous, alors nous monterons, car l’ Éternel les aura livrés en notre main; et ce sera pour nous le signe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Et ils se montrèrent les deux au poste des Philistins; et les Philistins dirent: Voici les Hébreux qui sortent des trous où ils se sont cachés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Et les hommes du poste répondirent à Jonathan et à celui qui portait ses armes, et dirent: Montez vers nous, et nous vous ferons savoir quelque chose. Et Jonathan dit à celui qui portait ses armes: Monte après moi, car l’ Éternel les a livrés en la main d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Et Jonathan monta avec ses mains et ses pieds, et celui qui portait ses armes après lui. Et ils tombèrent devant Jonathan, et celui qui portait ses armes les tuait après lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Et ce premier coup que frappèrent Jonathan et celui qui portait ses armes, mit [par terre] une vingtaine d’hommes, sur la moitié environ du sillon d’un arpent de terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Et l’épouvante fut dans le camp, dans la campagne et parmi tout le peuple; le poste et les ravageurs, eux aussi, furent saisis d’épouvante; et le pays trembla, et ce fut une frayeur de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Et les sentinelles de Saül, qui étaient à Guibha de Benjamin, regardèrent, et voici, la multitude s’écoulait, et s’en allait, et ils s’entre-tuaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Et Saül dit au peuple qui était avec lui: Faites donc l’appel, et voyez qui s’en est allé d’avec nous. Et ils firent l’appel; et voici, Jonathan n’y était pas, ni celui qui portait ses armes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Et Saül dit à Akhija: Fais approcher l’arche de Dieu (car l’arche de Dieu était en ce jour-là avec les fils d’Israël).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Et il arriva que, pendant que Saül parlait au sacrificateur, le tumulte qui était dans le camp des Philistins allait toujours croissant; et Saül dit au sacrificateur: Retire ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Et Saül et tout le peuple qui était avec lui furent assemblés à grands cris, et vinrent à la bataille; et voici, l’épée de chacun était contre l’autre: ce fut une confusion terrible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Et il y avait, comme auparavant, des Hébreux parmi les Philistins, lesquels étaient montés avec eux dans le camp, [de tout] alentour, et eux aussi [se tournèrent] pour être avec Israël qui était avec Saül et Jonathan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Et tous les hommes d’Israël qui s’étaient cachés dans la montagne d’Éphraïm, entendirent que les Philistins fuyaient, et ils s’attachèrent, eux aussi, à leur poursuite dans la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Et l’ Éternel sauva Israël ce jour-là. Et la bataille s’étendit au-delà de Beth-Aven.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Et les hommes d’Israël furent accablés ce jour-là. Or Saül avait adjuré le peuple, disant: Maudit soit l’homme qui mangera du pain, jusqu’au soir, et [jusqu’à ce] que je me sois vengé de mes ennemis; et, entre tout le peuple, nul ne goûta de pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Et tout le [peuple du] pays vint dans une forêt; et il y avait du miel sur le dessus des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Et le peuple entra dans la forêt; et voici du miel qui coulait; mais nul ne porta sa main à sa bouche, car le peuple avait peur du serment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Et Jonathan n’avait pas entendu, lorsque son père avait fait jurer le peuple, et il étendit le bout du bâton qu’il avait à la main et le trempa dans un rayon de miel et ramena sa main à sa bouche, et ses yeux furent éclaircis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Et quelqu’un du peuple répondit et dit: Ton père a fait expressément jurer le peuple, en disant: Maudit soit l’homme qui mangera du pain aujourd’hui! et le peuple était fatigué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Et Jonathan dit: Mon père a troublé le pays. Voyez donc comme mes yeux ont été éclaircis, parce que j’ai goûté un peu de ce miel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Qu’aurait-ce été, si le peuple avait aujourd’hui mangé du butin de ses ennemis qu’il a trouvé? maintenant la défaite des Philistins n’aurait-elle pas été plus grande?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Et ils frappèrent ce jour-là les Philistins, depuis Micmash jusqu’à Ajalon; et le peuple fut très fatigué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Et le peuple se jeta sur le butin, et ils prirent du menu et du gros bétail, et des veaux, et ils les égorgèrent sur le sol; et le peuple les mangeait avec le sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Et on le rapporta à Saül, en disant: Voici, le peuple pèche contre l’ Éternel en mangeant avec le sang. Et il dit: Vous avez agi infidèlement. Roulez à présent vers moi une grande pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Et Saül dit: Dispersez-vous parmi le peuple, et dites-leur: Amenez-moi chacun son bœuf et chacun son mouton, et égorgez-les ici et mangez; et ne péchez pas contre l’ Éternel en mangeant avec le sang. Et, cette nuit-là, tout le peuple amena chacun son bœuf à la main, et ils les égorgèrent là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Et Saül bâtit un autel à l’ Éternel; ce fut le premier autel qu’il bâtit à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Et Saül dit: Descendons de nuit après les Philistins, et pillons-les jusqu’à la lumière du matin, et n’en laissons pas un homme de reste. Et ils dirent: Fais tout ce qui est bon à tes yeux. Et le sacrificateur dit: Approchons-nous ici de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Et Saül interrogea Dieu: Descendrai-je après les Philistins? Les livreras-tu en la main d’Israël? Et il ne lui répondit pas ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Et Saül dit: Approchez ici, vous tous les principaux du peuple, et sachez et voyez comment ce péché est arrivé aujourd’hui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'car l’ Éternel qui a sauvé Israël est vivant, que si c’était par Jonathan, mon fils, il mourra certainement! Et personne de tout le peuple ne lui répondit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Et il dit à tout Israël: Vous, soyez d’un côté, et moi et Jonathan, mon fils, nous serons de l’autre côté. Et le peuple dit à Saül: Fais ce qui est bon à tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Et Saül dit à l’ Éternel, le Dieu d’Israël: Donne [un sort] parfait. Et Jonathan et Saül furent pris, et le peuple échappa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Et Saül dit: Jetez le sort entre moi et Jonathan, mon fils. Et Jonathan fut pris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Et Saül dit à Jonathan: Déclare-moi ce que tu as fait. Et Jonathan le lui déclara, et dit: Je n’ai fait que goûter un peu de miel avec le bout du bâton que j’avais à la main, [et] voici, je meurs!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Et Saül dit: Que Dieu [me] fasse ainsi, et ainsi y ajoute, si tu ne meurs certainement, Jonathan!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Et le peuple dit à Saül: Jonathan, qui a opéré cette grande délivrance en Israël, mourra-t-il? Qu’ainsi n’advienne! L’ Éternel est vivant, s’il tombe à terre un des cheveux de sa tête! car il a opéré avec Dieu aujourd’hui. Et le peuple délivra Jonathan, et il ne mourut pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Et Saül remonta de la poursuite des Philistins, et les Philistins s’en allèrent en leur lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Et Saül prit la royauté sur Israël, et il fit la guerre tout à l’entour contre tous ses ennemis: contre Moab, et contre les fils d’Ammon, et contre Édom, et contre les rois de Tsoba, et contre les Philistins; et partout où il se tournait, il les châtiait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Et il forma une armée et frappa Amalek, et délivra Israël de la main de ceux qui le pillaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Et les fils de Saül étaient Jonathan, et Jishvi, et Malki-Shua; et les noms de ses deux filles: le nom de l’aînée était Mérab, et le nom de la plus jeune, Mical.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Et le nom de la femme de Saül était Akhinoam, fille d’Akhimaats; et le nom du chef de son armée était Abner, fils de Ner, oncle de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Et Kis, père de Saül, et Ner, père d’Abner, étaient fils d’Abiel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Et la guerre fut forte contre les Philistins durant tous les jours de Saül; et quand Saül voyait quelque homme fort et quelque homme vaillant, il le prenait auprès de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, '*Et Samuel dit à Saül: L’ Éternel m’a envoyé pour t’oindre comme roi sur son peuple, sur Israël; et maintenant, écoute la voix des paroles de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Ainsi dit l’ Éternel des armées: J’ai considéré ce qu’Amalek a fait à Israël, comment il se plaça contre lui sur le chemin quand il montait d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Va maintenant, et frappe Amalek, et vous détruirez entièrement tout ce qui est à lui, et tu ne l’épargneras pas, mais tu feras mourir les hommes et les femmes, les enfants et ceux qui tètent, les bœufs et les moutons, les chameaux et les ânes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Et Saül convoqua le peuple et le dénombra à Telaïm, 200 000 hommes de pied, et 10 000 hommes de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Et Saül vint jusqu’à la ville d’Amalek, et il plaça une embuscade dans la vallée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Et Saül dit aux Kéniens: Allez, retirez-vous, descendez du milieu des Amalékites, de peur que je ne te détruise avec eux; car toi, tu usas de bonté envers tous les fils d’Israël lorsqu’ils montèrent d’Égypte. Et le Kénien se retira du milieu d’Amalek.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Et Saül frappa Amalek depuis Havila en allant vers Shur, qui est en face de l’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Et il prit vivant Agag, roi d’Amalek, et détruisit entièrement tout le peuple par le tranchant de l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Et Saül et le peuple épargnèrent Agag, et le meilleur du menu et du gros bétail, et les bêtes de la seconde portée, et les agneaux, et tout ce qui était bon, et ils ne voulurent pas les détruire entièrement; mais tout ce qui était misérable et chétif, cela ils le détruisirent entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Et la parole de l’ Éternel vint à Samuel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Je me repens d’avoir établi Saül pour roi; car il s’est détourné de moi et n’a point exécuté mes paroles. Et Samuel fut fort attristé, et il cria à l’ Éternel toute la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Et Samuel se leva de bonne heure pour aller le matin à la rencontre de Saül. Et on rapporta à Samuel, disant: Saül est allé à Carmel; et voici, il s’est érigé un trophée, et il s’est tourné ailleurs, et a passé plus loin, et est descendu à Guilgal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Et Samuel vint vers Saül, et Saül lui dit: Béni sois-tu de l’ Éternel! j’ai exécuté la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Et Samuel dit: Quel est donc ce bêlement de brebis à mes oreilles, et ce beuglement de bœufs que j’entends?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Et Saül dit: Ils les ont amenés des Amalékites, car le peuple a épargné le meilleur du menu et du gros bétail, pour sacrifier à l’ Éternel, ton Dieu; et le reste, nous l’avons détruit entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Et Samuel dit à Saül: Arrête, et je te déclarerai ce que l’ Éternel m’a dit cette nuit. Et il lui dit: Parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Et Samuel dit: N’est-ce pas, quand tu étais petit à tes propres yeux, tu es devenu chef des tribus d’Israël, et l’ Éternel t’a oint pour roi sur Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Et l’ Éternel t’avait envoyé par un chemin, et t’avait dit: Va et détruis entièrement ces pécheurs, les Amalékites, et fais-leur la guerre jusqu’à ce qu’ils soient consumés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Et pourquoi n’as-tu pas écouté la voix de l’ Éternel, et t’es-tu jeté sur le butin, et as-tu fait ce qui est mauvais aux yeux de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Et Saül dit à Samuel: J’ai écouté la voix de l’ Éternel, et je suis allé par le chemin par lequel l’ Éternel m’a envoyé; et j’ai amené Agag, roi d’Amalek, et j’ai entièrement détruit Amalek.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Et le peuple a pris, dans le butin, du menu et du gros bétail, comme prémices de ce qui était voué à l’exécration, pour sacrifier à l’ Éternel, ton Dieu, à Guilgal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Et Samuel dit: L’ Éternel prend-il plaisir aux holocaustes et aux sacrifices, comme à ce qu’on écoute la voix de l’ Éternel? Voici, écouter est meilleur que sacrifice, prêter l’oreille, meilleur que la graisse des béliers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'car la rébellion est comme le péché de divination, et l’obstination comme une idolâtrie et des théraphim. Parce que tu as rejeté la parole de l’ Éternel, il t’a aussi rejeté comme roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Et Saül dit à Samuel: J’ai péché, car j’ai transgressé le commandement de l’ Éternel et tes paroles, car j’ai craint le peuple et j’ai écouté leur voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Et maintenant, pardonne, je te prie, mon péché, et retourne-t’en avec moi, et je me prosternerai devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Et Samuel dit à Saül: Je ne retournerai point avec toi; car tu as rejeté la parole de l’ Éternel, et l’ Éternel t’a rejeté pour que tu ne sois plus roi sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Et Samuel se tourna pour s’en aller, et [Saül] saisit le pan de sa robe, qui se déchira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Et Samuel lui dit: L’ Éternel a déchiré aujourd’hui la royauté d’Israël de dessus toi, et l’a donnée à ton prochain, qui est meilleur que toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Et aussi, la sûre Confiance d’Israël ne ment point et ne se repent point; car il n’est pas un homme pour se repentir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Et [Saül] dit: J’ai péché; honore-moi maintenant, je te prie, en la présence des anciens de mon peuple et en la présence d’Israël, et retourne-t’en avec moi, et je me prosternerai devant l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Et Samuel retourna après Saül, et Saül se prosterna devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Et Samuel dit: Amenez-moi Agag, roi d’Amalek. Et Agag vint à lui gaiement; et Agag disait: Certainement l’amertume de la mort est passée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Et Samuel dit: Comme ton épée a privé d’enfants les femmes, de même, entre les femmes, ta mère sera privée d’enfants. Et Samuel mit Agag en pièces devant l’ Éternel, à Guilgal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Et Samuel s’en alla à Rama; et Saül monta à sa maison, à Guibha de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Et Samuel ne vit plus Saül jusqu’au jour de sa mort, car Samuel menait deuil sur Saül, parce que l’ Éternel s’était repenti d’avoir établi Saül roi sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, '*Et l’ Éternel dit à Samuel: Jusques à quand mèneras-tu deuil sur Saül, vu que moi je l’ai rejeté pour qu’il ne soit pas roi sur Israël? Remplis ta corne d’huile, et va: je t’enverrai vers Isaï, le Bethléhémite; car j’ai vu parmi ses fils un roi pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Et Samuel dit: Comment irai-je? Dès que Saül l’entendra, il me tuera. Et l’ Éternel dit: Tu prendras avec toi une génisse, et tu diras: Je suis venu pour sacrifier à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Et tu appelleras Isaï au sacrifice, et moi je te ferai savoir ce que tu auras à faire, et tu oindras pour moi celui que je te dirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Et Samuel fit ce que l’ Éternel avait dit, et vint à Bethléhem; et les anciens de la ville allèrent tremblants à sa rencontre, et dirent: Ta venue est-elle la paix?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Et il dit: La paix. Je suis venu pour sacrifier à l’ Éternel; sanctifiez-vous, et venez avec moi au sacrifice. Et il sanctifia Isaï et ses fils, et les appela au sacrifice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Et il arriva que, comme ils entraient, il vit Éliab, et il dit: Certainement l’oint de l’ Éternel est devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Et l’ Éternel dit à Samuel: Ne regarde pas son apparence, ni la hauteur de sa taille, car je l’ai rejeté; car [l’ Éternel ne regarde] pas ce à quoi l’homme regarde, car l’homme regarde à l’apparence extérieure, et l’ Éternel regarde au cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Et Isaï appela Abinadab et le fit passer devant Samuel. Et il dit: L’ Éternel n’a pas non plus choisi celui-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Et Isaï fit passer Shamma. Et il dit: L’ Éternel n’a pas non plus choisi celui-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Et Isaï fit passer ses sept fils devant Samuel. Et Samuel dit à Isaï: L’ Éternel n’a pas choisi ceux-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Et Samuel dit à Isaï: Sont-ce là tous les jeunes gens? Et il dit: Il reste encore le plus jeune, et voici, il paît le menu bétail. Et Samuel dit à Isaï: Envoie, et fais-le amener; car nous ne nous placerons point autour [de la table], jusqu’à ce qu’il soit venu ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Et il envoya et le fit venir. Or il avait le teint rosé, avec de beaux yeux, et était beau de visage. Et l’ Éternel dit: Lève-toi, oins-le; car c’est celui-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Et Samuel prit la corne d’huile, et l’oignit au milieu de ses frères. Et l’Esprit de l’ Éternel saisit David, depuis ce jour-là et dans la suite. Et Samuel se leva et s’en alla à Rama.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Et l’Esprit de l’ Éternel se retira d’avec Saül, et un mauvais esprit [envoyé] par l’ Éternel le troublait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Et les serviteurs de Saül lui dirent: Tu vois qu’un mauvais esprit [envoyé] de Dieu te trouble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Que notre seigneur veuille parler: tes serviteurs sont devant toi, ils chercheront un homme qui sache jouer de la harpe; et il arrivera que, quand le mauvais esprit [envoyé] de Dieu sera sur toi, il jouera de sa main et tu t’en trouveras bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Et Saül dit à ses serviteurs: Je vous prie, trouvez-moi un homme qui sache bien jouer, et amenez-le-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Et l’un des jeunes hommes répondit et dit: Voici, j’ai vu un fils d’Isaï, le Bethléhémite, qui sait jouer, un homme fort et vaillant, et un homme de guerre, et qui a l’intelligence des choses, et un bel homme, et l’ Éternel est avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Et Saül envoya des messagers à Isaï, et dit: Envoie-moi David, ton fils, qui est avec le menu bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Et Isaï prit un âne chargé de pain, et une outre de vin, et un chevreau, et les envoya à Saül par la main de David, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Et David vint vers Saül, et il se tint devant lui; et [Saül] l’aima beaucoup, et il fut son porteur d’armes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Et Saül envoya vers Isaï, disant: Que David, je te prie, se tienne devant moi; car il a trouvé grâce à mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Et il arrivait que, quand l’esprit [envoyé] de Dieu était sur Saül, David prenait la harpe et en jouait de sa main; et Saül était soulagé et se trouvait bien, et le mauvais esprit se retirait de dessus lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, '*Et les Philistins rassemblèrent leurs armées pour faire la guerre, et ils s’assemblèrent à Soco, qui appartient à Juda, et campèrent entre Soco et Azéka, à Éphès-Dammim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Et Saül et les hommes d’Israël se rassemblèrent, et campèrent dans la vallée d’Éla, et se rangèrent en bataille contre les Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Et les Philistins se tenaient sur la montagne, d’un côté, et Israël se tenait sur la montagne, de l’autre côté, et le ravin était entre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Et il sortit du camp des Philistins un champion [de l’armée]; son nom était Goliath, il était de Gath; sa hauteur était de six coudées et un empan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Et il avait un casque d’airain sur sa tête, et était revêtu d’une cotte de mailles à écailles; et le poids de la cotte de mailles était de 5 000 sicles d’airain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'et il avait des jambières d’airain aux jambes, et un javelot d’airain entre ses épaules;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'et le bois de sa lance était comme l’ensouple des tisserands, et le fer de sa lance pesait 600 sicles de fer; et celui qui portait son bouclier marchait devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Et il se tenait là et criait aux troupes rangées d’Israël, et leur disait: Pourquoi sortez-vous pour vous ranger en bataille? Ne suis-je pas le Philistin, et vous, des serviteurs de Saül? Choisissez-vous un homme, et qu’il descende contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'S’il est capable de combattre avec moi et qu’il me tue, nous serons vos serviteurs; et si moi j’ai l’avantage sur lui et que je le tue, c’est vous qui serez nos serviteurs et qui nous servirez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Et le Philistin dit: Moi, j’ai outragé aujourd’hui les troupes rangées d’Israël! Donnez-moi un homme, et nous combattrons ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Et Saül et tout Israël entendirent ces paroles du Philistin, et ils furent effrayés et eurent une grande peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Et David était fils de cet homme éphratien de Bethléhem de Juda, dont le nom était Isaï; et il avait huit fils; et cet homme, aux jours de Saül, était vieux, avancé en âge parmi les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Et les trois fils aînés d’Isaï étaient partis, ils avaient suivi Saül à la guerre. Et les noms de ses trois fils qui étaient partis pour la guerre, étaient: Éliab, le premier-né, et Abinadab, le second, et Shamma, le troisième.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Et David était le plus jeune; et les trois aînés avaient suivi Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Et David allait et revenait d’auprès de Saül pour paître le menu bétail de son père à Bethléhem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Et le Philistin s’approchait le matin et le soir, et il se présenta pendant 40 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Et Isaï dit à David, son fils: Prends, je te prie, pour tes frères, cet épha de froment rôti et ces dix pains, et porte-les vite au camp vers tes frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Et ces dix fromages de lait, tu les porteras au chef du millier; et tu t’informeras touchant le bien-être de tes frères, et tu prendras d’eux un gage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Or Saül, et eux, et tous les hommes d’Israël, étaient dans la vallée d’Éla, faisant la guerre contre les Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Et David se leva de bonne heure le matin et laissa le menu bétail à un gardien, et prit sa charge et s’en alla, comme Isaï le lui avait commandé; et il vint à l’enceinte formée par les chars. Or l’armée sortait pour se ranger en bataille, et on poussait le cri de guerre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'et Israël et les Philistins se rangèrent en bataille, ligne contre ligne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Et David laissa aux mains de celui qui gardait le bagage les objets qu’il portait, et courut vers la ligne de bataille; et il vint et interrogea ses frères touchant leur bien-être.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Et comme il parlait avec eux, voici le champion, nommé Goliath, le Philistin de Gath, qui s’avançait hors des rangs des Philistins et il proféra les mêmes paroles; et David l’entendit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Et tous les hommes d’Israël, voyant l’homme, s’enfuirent de devant lui et eurent très peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Et les hommes d’Israël dirent: Avez-vous vu cet homme-là qui monte? car c’est pour outrager Israël qu’il est monté. Et il arrivera que l’homme qui le frappera, le roi l’enrichira de grandes richesses, et il lui donnera sa fille, et affranchira la maison de son père en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Et David parla aux hommes qui se tenaient là avec lui, disant: Que sera-t-il fait à l’homme qui aura frappé ce Philistin-là, et qui aura ôté l’opprobre de dessus Israël? Car qui est ce Philistin, cet incirconcis, pour outrager les troupes rangées du Dieu vivant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Et le peuple lui parla selon cette parole, et dit: C’est ainsi qu’on fera à l’homme qui l’aura frappé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Et Éliab, son frère aîné, entendit pendant qu’il parlait à ces hommes; et la colère d’Éliab s’embrasa contre David, et il [lui] dit: Pourquoi donc es-tu descendu? et à qui as-tu laissé ce peu de brebis dans le désert? Je connais, moi, ton orgueil et la méchanceté de ton cœur; car c’est pour voir la bataille que tu es descendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Et David dit: Qu’ai-je fait maintenant? N’y a-t-il pas de quoi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Et il se détourna d’auprès de lui vers un autre, et dit les mêmes paroles; et le peuple lui répondit comme la première fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Et les paroles que David avait dites furent entendues, et on les rapporta en la présence de Saül; et il le fit venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Et David dit à Saül: Que le cœur ne défaille à personne à cause de lui! Ton serviteur ira et combattra avec ce Philistin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Et Saül dit à David: Tu n’es pas capable d’aller contre ce Philistin pour combattre avec lui; car tu es un jeune homme, et lui, il est homme de guerre dès sa jeunesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Et David dit à Saül: Ton serviteur paissait le menu bétail de son père, et un lion vint, et un ours: et il enleva un mouton du troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Et je sortis après lui et le frappai, et je délivrai [le mouton] de sa gueule; et il se leva contre moi, et je le saisis par sa barbe, et le frappai, et le tuai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Ton serviteur a frappé et le lion et l’ours; et ce Philistin, cet incirconcis, sera comme l’un d’eux, car il a outragé les troupes rangées du Dieu vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Et David dit: L’ Éternel qui m’a délivré de la patte du lion et de la patte de l’ours, lui me délivrera de la main de ce Philistin. Et Saül dit à David: Va, et que l’ Éternel soit avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Et Saül revêtit David de ses vêtements, et lui mit un casque d’airain sur la tête, et le revêtit d’une cotte de mailles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Et David ceignit son épée par-dessus ses vêtements, et voulut marcher, car il ne l’avait pas essayé. Et David dit à Saül: Je ne puis marcher avec ces choses, car je ne l’ai [jamais] essayé. Et David les ôta de dessus lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'et il prit son bâton en sa main, et se choisit du torrent cinq pierres lisses, et les mit dans le sac de berger qu’il avait, dans la poche; et il avait sa fronde à la main. Et il s’approcha du Philistin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Et le Philistin s’avança, allant et s’approchant de David, et, devant lui, l’homme qui portait son bouclier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Et le Philistin regarda et vit David, et le méprisa; car c’était un jeune homme au teint rosé, et beau de visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Et le Philistin dit à David: Suis-je un chien, moi, que tu viennes à moi avec des bâtons? Et le Philistin maudit David par ses dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Et le Philistin dit à David: Viens vers moi, et je donnerai ta chair aux oiseaux des cieux et aux bêtes des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Et David dit au Philistin: Toi, tu viens à moi avec une épée, et avec une lance, et avec un javelot; et moi, je viens à toi au nom de l’ Éternel des armées, du Dieu des troupes rangées d’Israël, que tu as outragé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'En ce jour, l’ Éternel te livrera en ma main; et je te frapperai, et j’ôterai ta tête de dessus toi, et je donnerai en ce jour les cadavres du camp des Philistins aux oiseaux des cieux et aux animaux de la terre; et toute la terre saura qu’il y a un Dieu pour Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'et toute cette congrégation saura que ce n’est ni par l’épée, ni par la lance, que l’ Éternel sauve; car la bataille est à l’ Éternel, et il vous livrera entre nos mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Et il arriva que, comme le Philistin se levait et s’avançait, et s’approchait à la rencontre de David, David se hâta et courut vers la ligne de bataille, à la rencontre du Philistin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Et David mit sa main à son sac, et y prit une pierre, et la lança avec sa fronde; et il frappa le Philistin au front, et la pierre s’enfonça dans son front; et il tomba sur sa face contre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Et David, avec une fronde et une pierre, fut plus fort que le Philistin, et frappa le Philistin et le tua; et David n’avait pas d’épée en sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Et David courut, et se tint sur le Philistin, et prit son épée, et la tira de son fourreau, et le tua, et lui coupa la tête. Et les Philistins, voyant que leur homme fort était mort, s’enfuirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Et les hommes d’Israël et de Juda se levèrent et poussèrent des cris, et poursuivirent les Philistins jusqu’à l’entrée du ravin et jusqu’aux portes d’Ékron; et les Philistins tombèrent tués, sur le chemin de Shaaraïm, et jusqu’à Gath, et jusqu’à Ékron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Et les fils d’Israël s’en revinrent de la poursuite des Philistins et pillèrent leur camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Et David prit la tête du Philistin et l’apporta à Jérusalem; et ses armes, il les mit dans sa tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Et quand Saül avait vu David sortant à la rencontre du Philistin, il avait dit à Abner, chef de l’armée: Abner, de qui ce jeune homme est-il fils? Et Abner avait dit: Ton âme est vivante, ô roi! je n’en sais rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Et le roi dit: Enquiers-toi de qui ce jeune homme est fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Et comme David revenait d’avoir frappé le Philistin, Abner le prit et l’amena devant Saül, ayant la tête du Philistin à la main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Et Saül lui dit: Jeune homme, de qui es-tu fils? Et David dit: Je suis fils de ton serviteur Isaï, le Bethléhémite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Et il arriva, comme il achevait de parler à Saül, que l’âme de Jonathan se lia à l’âme de David; et Jonathan l’aima comme son âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Et Saül le prit ce jour-là, et ne lui permit pas de retourner à la maison de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Et Jonathan fit alliance avec David, parce qu’il l’aimait comme son âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Et Jonathan se dépouilla de la robe qui était sur lui, et la donna à David, ainsi que ses vêtements, jusqu’à son épée, et à son arc, et à sa ceinture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Et David allait partout où Saül l’envoyait, [et] il prospérait; et Saül l’établit sur les hommes de guerre, et il était agréable aux yeux de tout le peuple, et même aux yeux des serviteurs de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Et il arriva que, comme ils revenaient, lors du retour de David après qu’il eut frappé le Philistin, les femmes sortirent de toutes les villes d’Israël à la rencontre du roi Saül, avec joie, en chantant et en dansant, avec des tambourins et des triangles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Et les femmes qui jouaient s’entre-répondaient et disaient: Saül a frappé ses 1 000, et David ses 10 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Et Saül fut très irrité, et cette parole fut mauvaise à ses yeux, et il dit: On en a donné à David 10 000, et à moi, on m’a donné les 1 000: il n’y a plus pour lui que la royauté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Et depuis ce jour-là et dans la suite, Saül eut l’œil sur David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Et il arriva, dès le lendemain, qu’un mauvais esprit [envoyé] de Dieu saisit Saül; et il prophétisa dans l’intérieur de la maison, et David jouait comme les autres jours, et il y avait une lance dans la main de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Et Saül jeta la lance, et dit: Je frapperai David et la paroi. Et David se détourna de devant lui par deux fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Et Saül eut peur de David; car l’ Éternel était avec lui, et il s’était retiré de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Et Saül l’éloigna de lui, et l’établit chef de millier; et [David] sortait et entrait devant le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Et David était sage dans toutes ses voies; et l’ Éternel était avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Et Saül vit qu’il était très sage, et il le craignit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Et tout Israël et Juda aimaient David, car il sortait et entrait devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Et Saül dit à David: Voici ma fille aînée, Mérab; je te la donnerai pour femme; seulement, sois-moi un homme vaillant, et combats les combats de l’ Éternel. Or Saül disait: Que ma main ne soit pas sur lui, mais que la main des Philistins soit sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Et David dit à Saül: Qui suis-je, et quelle est ma vie, quelle est en Israël la famille de mon père, pour que je sois gendre du roi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Et il arriva qu’au moment où l’on devait donner Mérab, fille de Saül, à David, elle fut donnée pour femme à Adriel, le Meholathite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Et Mical, fille de Saül, aima David; et on le rapporta à Saül, et la chose fut bonne à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Et Saül dit: Je la lui donnerai, et elle lui sera en piège, et la main des Philistins sera sur lui. Et Saül dit à David: Par l’une ou l’autre, tu seras aujourd’hui mon gendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Et Saül commanda à ses serviteurs: Parlez secrètement à David, en disant: Voici, le roi prend plaisir en toi, et tous ses serviteurs t’aiment; maintenant donc sois gendre du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Et les serviteurs de Saül dirent ces paroles aux oreilles de David. Et David dit: Est-ce peu de chose à vos yeux que de devenir gendre du roi? et moi, je suis un homme pauvre et peu considérable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Et les serviteurs de Saül lui rapportèrent cela, disant: David a parlé de cette manière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Et Saül dit: Vous direz ainsi à David: Le roi ne désire point de dot, mais 100 prépuces de Philistins, pour que le roi soit vengé de ses ennemis. Et Saül pensait faire tomber David par la main des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Et ses serviteurs rapportèrent ces paroles à David, et la chose fut bonne aux yeux de David de devenir gendre du roi. Et les jours n’étaient pas accomplis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'que David se leva, et s’en alla, lui et ses hommes, et frappa 200 hommes des Philistins; et David apporta leurs prépuces, et on en livra au roi le nombre complet, pour qu’il soit gendre du roi. Et Saül lui donna Mical, sa fille, pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Et Saül vit et connut que l’ Éternel était avec David; et Mical, fille de Saül, l’aimait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Et Saül eut encore plus peur de David, et Saül fut ennemi de David tous ses jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Or les chefs des Philistins entrèrent en campagne; et chaque fois qu’ils entraient en campagne, David prospérait plus que tous les serviteurs de Saül; et son nom fut en grande estime.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Et Saül parla à Jonathan, son fils, et à tous ses serviteurs, de faire mourir David (or Jonathan, fils de Saül, était très affectionné à David),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'et Jonathan en informa David, disant: Saül, mon père, cherche à te faire mourir; et maintenant, je te prie, sois sur tes gardes, au matin, et demeure dans quelque lieu secret, et cache-toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Et moi, je sortirai, et je me tiendrai à côté de mon père, dans la campagne où tu seras; et je parlerai de toi à mon père, et je verrai ce qu’il en est, et te le ferai savoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Et Jonathan parla en bien de David à Saül, son père, et lui dit: Que le roi ne pèche point contre son serviteur, contre David, car il n’a point péché contre toi; et même ce qu’il a fait est très avantageux pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Car il a mis sa vie en sa main, et a frappé le Philistin, et l’ Éternel a opéré une grande délivrance pour tout Israël; tu l’as vu et tu t’en es réjoui; pourquoi donc pécherais-tu contre le sang innocent, en faisant mourir David sans cause?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Et Saül écouta la voix de Jonathan, et Saül jura: L’ Éternel est vivant, si on le fait mourir!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Et Jonathan appela David, et Jonathan lui rapporta toutes ces choses. Et Jonathan amena David à Saül, et il fut devant lui comme auparavant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Et il y eut de nouveau la guerre; et David entra en campagne et combattit contre les Philistins et les frappa d’un grand coup, et ils s’enfuirent devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Et le mauvais esprit [envoyé] de l’ Éternel vint sur Saül: et il était assis dans sa maison, sa lance à la main, et David jouait [de la harpe].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Et Saül chercha à frapper de sa lance David et la paroi; et il se détourna de devant Saül, qui, de sa lance, frappa la paroi. Et David s’enfuit, et échappa cette nuit-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Et Saül envoya des messagers à la maison de David, pour le surveiller et le faire mourir au matin. Et Mical, sa femme, en informa David, disant: Si tu ne sauves pas ta vie cette nuit, demain tu seras mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Et Mical fit descendre David par la fenêtre; et il s’en alla et s’enfuit, et échappa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Et Mical prit le théraphim et le mit dans le lit, et mit à son chevet un tissu de poils de chèvre, et le couvrit d’un tapis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Et Saül envoya des messagers pour prendre David, et elle dit: Il est malade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Et Saül envoya les messagers pour voir David, disant: Apportez-le-moi dans le lit, pour le mettre à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Et les messagers vinrent, et voici, le théraphim était sur le lit, et un tissu de poils de chèvre à son chevet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Et Saül dit à Mical: Pourquoi m’as-tu ainsi trompé et as-tu laissé aller mon ennemi, de sorte qu’il s’est échappé? Et Mical dit à Saül: Il m’a dit: Laisse-moi aller, pourquoi te tuerais-je?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Et David s’enfuit, et il échappa; et il vint vers Samuel à Rama, et lui rapporta tout ce que Saül lui avait fait. Et ils s’en allèrent, lui et Samuel, et ils habitèrent à Naïoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Et on le rapporta à Saül, disant: Voici, David est à Naïoth, en Rama.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Et Saül envoya des messagers pour prendre David; et ils virent une assemblée de prophètes qui prophétisaient, et Samuel se tenait là, les présidant. Et l’Esprit de Dieu vint sur les messagers de Saül, et eux aussi ils prophétisèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Et on le rapporta à Saül, et il envoya d’autres messagers; et eux aussi ils prophétisèrent. Et Saül envoya encore des messagers, pour la troisième fois, et eux aussi ils prophétisèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Et il alla, lui aussi, à Rama, et vint jusqu’au grand puits qui est à Sécu; et il s’informa, disant: Où sont Samuel et David? Et on lui dit: Voici, ils sont à Naïoth, en Rama.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Et il se rendit là, à Naïoth, en Rama. Et l’Esprit de Dieu vint sur lui aussi, et, continuant son chemin, il prophétisa, jusqu’à ce qu’il fut venu à Naïoth, en Rama.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Et lui aussi, il se dépouilla de ses vêtements, et prophétisa, lui aussi, devant Samuel, et tomba nu par terre, tout ce jour-là et toute la nuit. C’est pourquoi on dit: Saül aussi est-il parmi les prophètes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Et David s’enfuit de Naïoth, en Rama, et vint, et dit devant Jonathan: Qu’ai-je fait? Quelle est mon iniquité, et quel est mon péché devant ton père, qu’il cherche ma vie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Et [Jonathan] lui dit: Qu’ainsi n’advienne! tu ne mourras point. Voici, mon père ne fait aucune chose, ni grande, ni petite, qu’il ne me la découvre; et pourquoi mon père me cacherait-il cette chose-là? Il n’en est rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Et David jura encore et dit: Ton père sait très bien que j’ai trouvé grâce à tes yeux, et il aura dit: Que Jonathan ne sache point cela, de peur qu’il n’en soit attristé. Mais l’ Éternel est vivant, et ton âme est vivante, qu’il n’y a qu’un pas entre moi et la mort!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Et Jonathan dit à David: Ce que ton âme dit, je le ferai pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Et David dit à Jonathan: Voici, c’est demain la nouvelle lune, et je devrai m’asseoir auprès du roi pour manger; laisse-moi donc aller, et je me cacherai dans les champs jusqu’au troisième soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Si ton père s’aperçoit de mon absence, tu diras: David m’a demandé instamment de courir à Bethléhem, sa ville, car il y a là un sacrifice annuel pour toute la famille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'S’il dit ainsi: C’est bon! il y a paix pour ton serviteur. Mais s’il se met dans une grande colère, sache que le mal est décidé de sa part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Use donc de bonté envers ton serviteur, car tu as fait entrer ton serviteur dans une alliance de l’ Éternel avec toi; et s’il y a de l’iniquité en moi, fais-moi mourir toi-même; et pourquoi me mènerais-tu vers ton père?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Et Jonathan dit: Loin de toi [une telle pensée]; car si je savais certainement que mon père soit décidé à faire venir le mal sur toi, ne t’en informerais-je pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Et David dit à Jonathan: Qui m’en informera? Et si ton père te fait une réponse dure...?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Et Jonathan dit à David: Viens, et sortons aux champs. Et ils sortirent les deux aux champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Et Jonathan dit à David: Éternel, Dieu d’Israël! quand j’aurai sondé mon père demain à cette heure, ou après-demain, s’il y a quelque chose de bon pour David, et qu’alors je n’envoie pas vers toi et ne te le découvre pas,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'que l’ Éternel fasse ainsi à Jonathan, et ainsi y ajoute! S’il semble bon à mon père de te faire du mal, je te le ferai savoir, et je te laisserai aller, et tu t’en iras en paix. Et que l’ Éternel soit avec toi, comme il a été avec mon père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Et n’est-ce pas? si je suis encore vivant, – n’est-ce pas, tu useras envers moi de la bonté de l’ Éternel, et je ne mourrai point;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'et tu ne retireras point ta bonté de ma maison, à jamais, non pas même lorsque l’ Éternel retranchera chacun des ennemis de David de dessus la face de la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Et Jonathan fit alliance avec la maison de David: Que l’ Éternel le redemande de la main des ennemis de David!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Et Jonathan fit encore jurer David par l’amour qu’il lui portait; car il l’aimait comme il aimait son âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Et Jonathan lui dit: C’est demain la nouvelle lune, et on s’apercevra que tu manques, car ton siège sera vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Et le troisième jour, tu descendras en hâte, et tu viendras au lieu où tu t’étais caché le jour de l’affaire, et tu demeureras près de la pierre d’Ézel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Et moi, je tirerai trois flèches du côté de cette pierre, comme si je tirais vers un but;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'et voici, j’enverrai le jeune garçon [en disant]: Va, trouve les flèches. Si je dis expressément au jeune garçon: Voici, les flèches sont en deçà de toi, prends-les; alors viens, car il y a paix pour toi, et il n’y a rien, l’ Éternel est vivant!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Et si je dis ainsi au jeune homme: Voici, les flèches sont au-delà de toi; va, car l’ Éternel te renvoie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Et quant à la parole que nous avons dite, moi et toi, voici, l’ Éternel est entre moi et toi, à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Et David se cacha dans les champs; et c’était la nouvelle lune, et le roi s’assit au repas pour manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Et le roi s’assit sur son siège comme les autres fois, sur le siège contre la paroi; et Jonathan se leva, et Abner s’assit à côté de Saül, et la place de David était vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Et Saül ne dit rien ce jour-là, car il disait: Il lui est arrivé quelque chose; il n’est pas pur, certainement il n’est pas pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Et le lendemain de la nouvelle lune, le second jour, comme la place de David était vide, Saül dit à Jonathan, son fils: Pourquoi le fils d’Isaï n’est-il venu au repas ni hier ni aujourd’hui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Et Jonathan répondit à Saül: David m’a instamment demandé [d’aller] jusqu’à Bethléhem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'et il m’a dit: Laisse-moi aller, je te prie, car nous avons un sacrifice de famille dans la ville, et mon frère même m’a commandé [de m’y trouver]; et maintenant, je te prie, si j’ai trouvé grâce à tes yeux, je me sauverai, et je verrai mes frères. C’est pourquoi il n’est pas venu à la table du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Et la colère de Saül s’embrasa contre Jonathan, et il lui dit: Fils de la [femme] perverse et rebelle, ne sais-je pas que tu as choisi le fils d’Isaï à ta honte et à la honte de la nudité de ta mère?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Car tous les jours que le fils d’Isaï sera vivant sur la terre, tu ne seras pas établi, ni toi ni ton règne; et maintenant, envoie, et amène-le-moi; car il mourra certainement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Et Jonathan répondit à Saül, son père, et lui dit: Pourquoi serait-il mis à mort? Qu’a-t-il fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Et Saül jeta sa lance contre lui pour le frapper. Et Jonathan connut que c’était chose décidée de la part de son père, de faire mourir David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Et Jonathan se leva de table dans une ardente colère, et ne mangea pas le pain le second jour de la nouvelle lune; car il était affligé à cause de David, parce que son père l’avait outragé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Et il arriva, le matin, que Jonathan sortit aux champs, au lieu convenu avec David, et un petit garçon avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Et il dit à son garçon: Cours, trouve, je te prie, les flèches que je tire. Le garçon courut, et [Jonathan] tira la flèche au-delà de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Et le garçon vint au lieu où était la flèche que Jonathan avait tirée, et Jonathan cria après le garçon, et dit: La flèche n’est-elle pas au-delà de toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Et Jonathan criait après le garçon: Vite! hâte-toi, ne t’arrête pas! Et le garçon de Jonathan ramassa les flèches et revint auprès de son maître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Or le garçon ne savait rien, Jonathan et David seuls savaient l’affaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Et Jonathan donna ses armes au garçon qu’il avait, et lui dit: Va, porte-les à la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, '[Et] le garçon s’en alla; et David se leva du côté du midi, et tomba, sa face contre terre, et se prosterna par trois fois; et ils s’embrassèrent l’un l’autre et pleurèrent l’un avec l’autre, jusqu’à ce que les pleurs de David devinrent excessifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Et Jonathan dit à David: Va en paix, selon que nous avons juré, nous deux, au nom de l’ Éternel, disant: L’ Éternel sera entre moi et toi, et entre ma semence et ta semence, à toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Et [David] se leva et s’en alla; et Jonathan entra dans la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, '*Et David vint à Nob, auprès d’Akhimélec, le sacrificateur; et Akhimélec trembla en rencontrant David, et lui dit: Pourquoi es-tu seul et n’y a-t-il personne avec toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Et David dit à Akhimélec, le sacrificateur: Le roi m’a commandé quelque chose, et m’a dit: Que personne ne sache rien de l’affaire pour laquelle je t’envoie, ni de ce que je t’ai commandé. Et j’ai indiqué à mes jeunes hommes un certain lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Et maintenant, qu’as-tu sous la main? Donne-moi dans la main cinq pains, ou ce qui se trouvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Et le sacrificateur répondit à David, et dit: Je n’ai point sous la main de pain commun, il n’y a que du pain sacré; si seulement les jeunes hommes se sont gardés des femmes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Et David répondit au sacrificateur, et lui dit: Oui, nous avons été privés des femmes depuis deux ou trois jours que je suis sorti, et les vases de mes jeunes hommes sont saints; et le [pain] est en quelque sorte commun, vu qu’on en consacre [de nouveau] dans les vases aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Et le sacrificateur lui donna du [pain] sacré, car il n’y avait point là d’autre pain que le pain de proposition qui avait été ôté de devant l’ Éternel pour remettre du pain chaud le jour où on levait l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Et il y avait là un homme d’entre les serviteurs de Saül, retenu ce jour-là devant l’ Éternel, et son nom était Doëg, l’Édomite; il était le chef des bergers de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Et David dit à Akhimélec: N’as-tu pas ici sous la main une lance ou une épée? car je n’ai pris dans ma main ni mon épée ni mes armes, parce que l’affaire du roi était pressante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Et le sacrificateur dit: L’épée de Goliath, le Philistin, que tu as frappé dans la vallée d’Éla, la voilà, enveloppée dans un manteau derrière l’éphod: si tu veux la prendre, prends-la; car il n’y en a point d’autre ici que celle-là. Et David dit: Il n’y en a point de pareille; donne-la-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Et David se leva et s’enfuit ce jour-là de devant Saül, et vint vers Akish, roi de Gath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Et les serviteurs d’Akish lui dirent: N’est-ce pas là David, le roi du pays? N’est-ce pas au sujet de celui-ci qu’on s’entre-répondait dans les danses, en disant: Saül a frappé ses 1 000, et David ses 10 000?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Et David prit à cœur ces paroles, et il eut très peur d’Akish, roi de Gath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Et il se contrefit devant eux, et fit l’insensé entre leurs mains; il marquait les battants de la porte, et laissait couler sa salive sur sa barbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Et Akish dit à ses serviteurs: Voici, vous voyez que cet homme est fou. Pourquoi me l’avez-vous amené?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 16, 'Manqué-je de fous, moi, que vous m’ayez amené celui-ci pour faire le fou devant moi? Celui-ci entrerait-il dans ma maison?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, '*Et David partit de là, et se sauva dans la caverne d’Adullam; et ses frères et toute la maison de son père l’apprirent, et descendirent là vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Et tout homme qui était dans la détresse, et tout homme qui était dans les dettes, et tout homme qui avait de l’amertume dans l’âme, s’assembla vers lui, et il fut leur chef; et il y eut avec lui environ 400 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Et David s’en alla de là à Mitspé de Moab, et il dit au roi de Moab: Je te prie, que mon père et ma mère se retirent chez vous jusqu’à ce que je sache ce que Dieu fera de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Et il les amena devant le roi de Moab, et ils demeurèrent avec lui tous les jours que David fut dans le lieu fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Et Gad, le prophète, dit à David: Ne demeure pas dans ce lieu fort; va, et entre dans le pays de Juda. Et David s’en alla et entra dans la forêt de Héreth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Et Saül entendit que David et les hommes qui étaient avec lui s’étaient montrés. Et Saül était assis à Guibha sous un tamaris, sur la hauteur, sa lance à la main, et tous ses serviteurs se tenaient auprès de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Et Saül dit à ses serviteurs qui se tenaient auprès de lui: Écoutez, Benjaminites: Le fils d’Isaï vous donnera-t-il, à vous tous aussi, des champs et des vignes? Vous établira-t-il tous chefs de milliers et chefs de centaines,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'que vous ayez tous conspiré contre moi, et que personne ne m’avertisse quand mon fils fait alliance avec le fils d’Isaï, et que personne d’entre vous ne soit peiné pour moi et ne m’avertisse que mon fils a soulevé contre moi mon serviteur pour me dresser des embûches, comme [il le fait] aujourd’hui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Et Doëg, l’Édomite, qui était établi sur les serviteurs de Saül, répondit et dit: J’ai vu le fils d’Isaï venir à Nob vers Akhimélec, fils d’Akhitub;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'et il a interrogé l’ Éternel pour lui, et il lui a donné des provisions, et il lui a donné l’épée de Goliath, le Philistin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Et le roi envoya appeler Akhimélec, le sacrificateur, fils d’Akhitub, et toute la maison de son père, les sacrificateurs qui étaient à Nob; et ils vinrent tous vers le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Et Saül dit: Écoute, je te prie, fils d’Akhitub. Et il dit: Me voici, mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Et Saül lui dit: Pourquoi avez-vous conspiré contre moi, toi et le fils d’Isaï, que tu lui aies donné du pain et une épée, et que tu aies interrogé Dieu pour lui, afin qu’il s’élève contre moi pour me dresser des embûches, comme [il le fait] aujourd’hui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Et Akhimélec répondit au roi, et dit: Et qui, parmi tous tes serviteurs, est comme David, fidèle, et gendre du roi, et ayant accès à tes audiences privées, et honoré dans ta maison?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Ai-je commencé aujourd’hui à interroger Dieu pour lui? Loin de moi! Que le roi ne mette aucune chose à la charge de son serviteur [ni de personne] de toute la maison de mon père, car de tout ceci ton serviteur ne sait aucune chose, ni petite, ni grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Et le roi [lui] dit: Certainement tu mourras, Akhimélec, toi et toute la maison de ton père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Et le roi dit aux coureurs qui se tenaient près de lui: Tournez-vous, et mettez à mort les sacrificateurs de l’ Éternel, parce que leur main aussi est avec David, et parce qu’ils ont bien su qu’il s’enfuyait, et qu’ils ne m’en ont point averti. Et les serviteurs du roi ne voulurent pas étendre leurs mains pour se jeter sur les sacrificateurs de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Et le roi dit à Doëg: Tourne-toi, et jette-toi sur les sacrificateurs. Et Doëg, l’Édomite, se tourna, et se jeta sur les sacrificateurs; et il mit à mort, ce jour-là, 85 hommes portant l’éphod de lin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Et [Saül] frappa Nob, ville des sacrificateurs, par le tranchant de l’épée, homme et femme, enfant et celui qui tète, bœuf et âne, et mouton, par le tranchant de l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Et un des fils d’Akhimélec, fils d’Akhitub, dont le nom était Abiathar, se sauva, et s’enfuit après David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Et Abiathar rapporta à David que Saül avait tué les sacrificateurs de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Et David dit à Abiathar: Je le savais, ce jour-là, lorsque Doëg, l’Édomite, était là, qu’il ne manquerait pas de le rapporter à Saül; moi je suis cause [de la mort] de tous ceux de la maison de ton père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Demeure avec moi, ne crains point; car celui qui cherche ma vie, cherche ta vie, et près de moi tu seras bien gardé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, '*Et on rapporta à David, en disant: Voici, les Philistins font la guerre à Kehila et pillent les aires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Et David interrogea l’ Éternel, disant: Irai-je, et frapperai-je ces Philistins? Et l’ Éternel dit à David: Va, et tu frapperas les Philistins, et tu sauveras Kehila.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Et les hommes de David lui dirent: Voici, [même] ici en Juda, nous avons peur, et comment irions-nous à Kehila, contre les troupes rangées des Philistins?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Et David interrogea encore l’ Éternel, et l’ Éternel lui répondit et dit: Lève-toi, descends à Kehila; car je livrerai les Philistins en ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Et David alla avec ses hommes à Kehila, et combattit contre les Philistins et emmena leurs troupeaux, et leur infligea une grande défaite. Et David sauva les habitants de Kehila.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Et il était arrivé que, lorsque Abiathar, fils d’Akhimélec, s’était enfui auprès de David à Kehila, il était descendu avec un éphod en sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Et on rapporta à Saül que David était entré à Kehila. Et Saül dit: Dieu l’a rejeté [et livré] en ma main; car il s’est enfermé en entrant dans une ville qui a des portes et des barres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Et Saül convoqua tout le peuple pour la guerre, pour descendre à Kehila, afin d’assiéger David et ses hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Et David sut que Saül méditait du mal contre lui, et il dit à Abiathar, le sacrificateur: Apporte l’éphod.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Et David dit: Éternel, Dieu d’Israël! ton serviteur a appris comme une chose certaine que Saül cherche à entrer dans Kehila, pour détruire la ville à cause de moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'les hommes de Kehila me livreront-ils en sa main? Saül descendra-t-il, comme ton serviteur l’a entendu dire? Éternel, Dieu d’Israël! déclare-le, je te prie, à ton serviteur. Et l’ Éternel dit: Il descendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Et David dit: Les hommes de Kehila me livreront-ils, moi et mes hommes, en la main de Saül? Et l’ Éternel dit: Ils [te] livreront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Et David se leva, et ses hommes, environ 600 hommes, et ils sortirent de Kehila et s’en allèrent où ils purent. Et on rapporta à Saül que David s’était échappé de Kehila, et il s’abstint d’entrer en campagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Et David habita au désert, dans des lieux forts, et il habita dans la montagne, au désert de Ziph. Et Saül le cherchait tous les jours; mais Dieu ne le livra pas en sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Et David vit que Saül était sorti pour chercher sa vie; et David [se tenait] au désert de Ziph, dans un bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Et Jonathan, fils de Saül, se leva et alla vers David dans le bois, et fortifia sa main en Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'et il lui dit: Ne crains pas, car la main de Saül, mon père, ne te trouvera pas; et tu régneras sur Israël, et moi, je serai le second après toi; et Saül, mon père, le sait aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Et ils firent, les deux, alliance devant l’ Éternel; et David demeura dans le bois, et Jonathan s’en alla à sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Et les Ziphiens montèrent vers Saül, à Guibha, disant: David ne se tient-il pas caché auprès de nous, dans les lieux forts, dans le bois, sur la colline de Hakila, qui est au midi de Jeshimon?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Et maintenant, ô roi, puisque tout le désir de ton âme est de descendre, descends; et ce sera à nous de le livrer en la main du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Et Saül dit: Bénis soyez-vous de par l’ Éternel, de ce que vous avez eu pitié de moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Allez, je vous prie, assurez-vous encore davantage, et sachez et voyez le lieu où est son pied, [et] qui l’y a vu, car on m’a dit qu’il est très rusé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Et voyez et sachez toutes les cachettes où il se cache, et revenez vers moi avec quelque chose de certain, et j’irai avec vous; et il arrivera que, s’il est dans le pays, je le chercherai soigneusement parmi tous les milliers de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Et ils se levèrent et s’en allèrent à Ziph, devant Saül; mais David et ses hommes étaient au désert de Maon, dans la plaine, au midi de Jeshimon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Et Saül et ses hommes allèrent pour le chercher; et on le rapporta à David, et il descendit le rocher, et habita au désert de Maon. Et Saül l’apprit, et il poursuivit David au désert de Maon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Et Saül allait de ce côté-ci de la montagne, et David et ses hommes de l’autre côté de la montagne; et David fuyait en hâte pour échapper à Saül, et Saül et ses hommes cherchaient à environner David et ses hommes, pour les prendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Et un messager vint à Saül, disant: Hâte-toi, et viens, car les Philistins se sont jetés sur le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Et Saül cessa de poursuivre David, et il marcha à la rencontre des Philistins. C’est pourquoi on a appelé ce lieu-là Séla-Hammakhlekoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, '*Et David monta de là, et habita dans les lieux forts d’En-Guédi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Et il arriva que, quand Saül fut revenu de la poursuite des Philistins, on lui rapporta, en disant: Voici, David est au désert d’En-Guédi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Et Saül prit 3 000 hommes d’élite de tout Israël, et il s’en alla pour chercher David et ses hommes sur les rochers des bouquetins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Et il vint aux parcs du menu bétail, sur le chemin; et là il y avait une caverne, et Saül y entra pour se couvrir les pieds; et David et ses hommes étaient assis au fond de la caverne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Et les hommes de David lui dirent: Voici le jour dont l’ Éternel t’a dit: Voici, je livre ton ennemi en ta main, et tu lui feras comme il sera bon à tes yeux. Et David se leva et coupa secrètement le pan de la robe de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Et il arriva, après cela, que le cœur de David le reprit de ce qu’il avait coupé le pan [de la robe] de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Et il dit à ses hommes: Loin de moi, de par l’ Éternel, que je fasse une telle chose à mon seigneur, à l’oint de l’ Éternel, que d’étendre ma main sur lui; car il est l’oint de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Et David retint ses hommes par ses paroles, et ne leur permit pas de s’élever contre Saül. Et Saül se leva de la caverne, et alla son chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Et après cela, David se leva, et sortit de la caverne, et cria après Saül, disant: Ô roi, mon seigneur! Et Saül regarda derrière lui, et David s’inclina le visage contre terre et se prosterna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Et David dit à Saül: Pourquoi écouterais-tu les paroles des hommes qui disent: Voici, David cherche à te faire du mal?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Voici, tes yeux ont vu en ce jour que l’ Éternel t’a livré aujourd’hui en ma main, dans la caverne. Et on m’a dit de te tuer; et [mon œil] t’a épargné, et j’ai dit: Je n’étendrai point ma main sur mon seigneur, car il est l’oint de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Et regarde, mon père, regarde le pan de ta robe dans ma main; car en ce que j’ai coupé le pan de ta robe et ne t’ai point tué, sache et vois qu’il n’y a pas de mal en ma main, ni de transgression, et que je n’ai pas péché contre toi; et toi, tu fais la chasse à mon âme pour la prendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'L’ Éternel jugera entre moi et toi, et l’ Éternel me vengera de toi; mais ma main ne sera pas sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Comme dit le proverbe des anciens: Des méchants vient la méchanceté; mais ma main ne sera pas sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Après qui est sorti le roi d’Israël? Qui poursuis-tu? Un chien mort, une puce!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Et l’ Éternel sera juge, et il jugera entre moi et toi; et il verra et plaidera ma cause, et me fera droit [en me délivrant] de ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Et lorsque David eut achevé de dire ces paroles à Saül, Saül dit: Est-ce là ta voix, mon fils David? Et Saül éleva sa voix et pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Et il dit à David: Tu es plus juste que moi, car toi tu m’as rendu le bien, et moi je t’ai rendu le mal;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'et tu as fait connaître aujourd’hui que tu agissais en bien envers moi, en ce que l’ Éternel m’avait livré en ta main, et que tu ne m’as pas tué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Et si un homme a trouvé son ennemi, le laissera-t-il aller sain et sauf? Que l’ Éternel te fasse du bien, en récompense de ce que tu as fait aujourd’hui à mon égard!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Et maintenant, voici, je sais que certainement tu régneras, et que le royaume d’Israël sera établi en ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Et maintenant, jure-moi par l’ Éternel que tu ne retrancheras point ma semence après moi, et que tu n’ôteras point mon nom de la maison de mon père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'Et David le jura à Saül; et Saül s’en alla dans sa maison; et David et ses hommes montèrent au lieu fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, '*Et Samuel mourut; et tout Israël s’assembla, et se lamenta sur lui; et on l’enterra dans sa maison, à Rama. Et David se leva, et descendit au désert de Paran.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Et il y avait à Maon un homme qui avait ses affaires à Carmel; et cet homme était très riche; il avait 3 000 moutons et 1 000 chèvres. Et il était à Carmel pendant qu’on tondait ses moutons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Et le nom de l’homme était Nabal, et le nom de sa femme, Abigaïl; et la femme avait du bon sens et était belle de visage; et l’homme était dur et méchant dans ses actes; et il était de la race de Caleb.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Et David apprit dans le désert que Nabal tondait ses moutons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Et David envoya dix jeunes hommes; et David dit aux jeunes hommes: Montez à Carmel, et entrez chez Nabal, et saluez-le en mon nom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'et vous [lui] direz ainsi: Vis longtemps! et paix te soit, et paix à ta maison, et paix à tout ce qui t’appartient!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Et maintenant j’ai entendu dire que tu as les tondeurs; or tes bergers ont été avec nous, et nous ne les avons pas molestés, et rien n’a manqué du leur, tous les jours qu’ils ont été à Carmel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Demande-le à tes jeunes gens et ils t’en informeront. Que les jeunes hommes trouvent donc grâce à tes yeux, car nous sommes venus dans un bon jour. Donne, je te prie, à tes serviteurs et à ton fils David ce que ta main trouvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Et les jeunes hommes de David vinrent et parlèrent à Nabal selon toutes ces paroles, au nom de David; et ils se tinrent tranquilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Et Nabal répondit aux serviteurs de David, et dit: Qui est David? Et qui est le fils d’Isaï? Aujourd’hui ils sont nombreux les serviteurs qui se sauvent chacun de son maître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Et je prendrais mon pain et mon eau, et ma viande que j’ai tuée pour mes tondeurs, et je les donnerais à des hommes dont je ne sais d’où ils sont?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Et les jeunes hommes de David rebroussèrent chemin et s’en retournèrent; et ils vinrent et lui racontèrent selon toutes ces paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Et David dit à ses hommes: Ceignez chacun votre épée. Et ils ceignirent chacun leur épée, et David aussi ceignit son épée. Et environ 400 hommes montèrent après David, et 200 restèrent près du bagage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Et un jeune homme des gens [de Nabal] informa Abigaïl, femme de Nabal, disant: Voici, David a envoyé du désert des messagers pour bénir notre maître, et il s’est emporté contre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Et les hommes ont été très bons pour nous, et nous n’avons pas été molestés, et il n’a rien manqué de ce qui était à nous, tout le temps que nous avons marché avec eux pendant que nous étions aux champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Ils ont été une muraille pour nous, de nuit et de jour, tout le temps que nous avons été avec eux, faisant paître le menu bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Et maintenant, sache et vois ce que tu as à faire; car le mal est décidé contre notre maître et contre toute sa maison; et il est trop fils de Bélial pour qu’on parle avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Et Abigaïl se hâta, et prit 200 pains, et deux outres de vin, et cinq moutons tout apprêtés, et cinq mesures de grain rôti, et 100 gâteaux de raisins secs, et 200 gâteaux de figues sèches, et les mit sur des ânes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'et elle dit à ses jeunes hommes: Passez devant moi; voici, je viens après vous. Et elle ne dit rien à Nabal, son mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Et comme elle descendait, montée sur son âne, à couvert de la montagne, voici, David et ses hommes descendaient au-devant d’elle; et elle les rencontra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Et David avait dit: Certainement c’est en vain que j’ai gardé tout ce que cet [homme] avait au désert, et que rien n’a manqué de tout ce qui était à lui: il m’a rendu le mal pour le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Que Dieu fasse ainsi aux ennemis de David, et ainsi y ajoute, si, de tout ce qui est à lui, je laisse jusqu’à la lumière du matin un seul homme de reste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Et Abigaïl vit David, et elle se hâta et descendit de dessus son âne; et elle tomba sur sa face devant David et se prosterna contre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Et elle tomba à ses pieds, et dit: À moi l’iniquité, mon seigneur! Mais je te prie, que ta servante parle à tes oreilles; et écoute les paroles de ta servante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Que mon seigneur, je te prie, ne fasse pas attention à cet homme de Bélial, à Nabal; car il est tel que son nom: son nom est Nabal, et la folie est avec lui. Et moi, ta servante, je n’ai pas vu les jeunes hommes de mon seigneur que tu as envoyés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Et maintenant, mon seigneur, l’ Éternel est vivant et ton âme est vivante, que l’ Éternel t’a empêché d’en venir au sang et de te faire justice par ta main. Et maintenant, que tes ennemis et ceux qui cherchent à faire du tort à mon seigneur soient comme Nabal!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Et maintenant, [voici] ce présent que ton esclave a apporté à mon seigneur pour qu’on le donne aux jeunes hommes qui marchent à la suite de mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Pardonne, je te prie, la transgression de ta servante, car l’ Éternel fera certainement une maison stable à mon seigneur; car mon seigneur combat les combats de l’ Éternel, et la méchanceté n’a jamais été trouvée en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Et un homme s’est levé pour te poursuivre et pour chercher ta vie, mais la vie de mon seigneur est liée dans le faisceau des vivants par-devers l’ Éternel, ton Dieu; et l’âme de tes ennemis, il la lancera du creux de la fronde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Et il arrivera que, lorsque l’ Éternel aura fait à mon seigneur selon tout le bien dont il a parlé à ton sujet, et qu’il t’aura établi prince sur Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'ceci ne sera point pour toi une occasion de chute, ni un achoppement pour le cœur de mon seigneur, d’avoir sans cause versé le sang, et que mon seigneur se soit fait justice à lui-même. Et quand l’ Éternel aura fait du bien à mon seigneur, souviens-toi de ta servante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Et David dit à Abigaïl: Béni soit l’ Éternel, le Dieu d’Israël, qui en ce jour t’a envoyée à ma rencontre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Et bénie soit ta sagesse, et bénie sois-tu, toi qui en ce jour m’as empêché d’en venir au sang et de me faire justice par ma main!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Mais l’ Éternel, le Dieu d’Israël, qui m’a empêché de te faire du tort, est vivant, que si tu ne t’étais hâtée et n’étais venue à ma rencontre, il ne serait pas resté à Nabal un seul homme jusqu’à la lumière du matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Et David prit de sa main ce qu’elle lui avait apporté, et il lui dit: Monte en paix dans ta maison; regarde, j’ai écouté ta voix, et je t’ai accueillie avec faveur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Et Abigaïl vint vers Nabal; et voici, il faisait dans sa maison un festin comme un festin de roi; et le cœur de Nabal était gai, et il était ivre à l’excès; aussi elle ne lui raconta aucune chose, ni petite, ni grande, jusqu’à la lumière du matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Et il arriva le matin, quand le vin de Nabal eut passé, que sa femme lui rapporta ces choses; et son cœur mourut au-dedans de lui, et il devint comme une pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Et il arriva, environ dix jours après, que l’ Éternel frappa Nabal, et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Et David apprit que Nabal était mort, et il dit: Béni soit l’ Éternel qui a pris en main ma cause touchant l’outrage que m’avait fait Nabal, et qui a retenu son serviteur de faire le mal! Et l’ Éternel a fait retomber le mal de Nabal sur sa tête. Et David envoya parler à Abigaïl, afin de la prendre pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Et les serviteurs de David vinrent vers Abigaïl, à Carmel, et lui parlèrent, disant: David nous a envoyés vers toi afin de te prendre pour sa femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Et elle se leva et se prosterna le visage contre terre, et dit: Voici, ta servante sera une esclave pour laver les pieds des serviteurs de mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Et Abigaïl se leva en hâte, et monta sur un âne, et ses cinq jeunes filles qui la suivaient; et elle s’en alla après les messagers de David, et fut sa femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'David avait pris aussi Akhinoam de Jizreël, et elles furent toutes les deux ses femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Et Saül avait donné Mical, sa fille, femme de David, à Palti, fils de Laïsh, qui était de Gallim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Et les Ziphiens vinrent vers Saül, à Guibha, disant: David ne se tient-il pas caché à la colline de Hakila qui est en face de Jeshimon?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Et Saül se leva et descendit au désert de Ziph, et avec lui 3 000 hommes d’élite d’Israël, pour chercher David dans le désert de Ziph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Et Saül campa sur la colline de Hakila, qui est en face de Jeshimon, sur le chemin. Or David habitait dans le désert; et il vit que Saül était venu après lui au désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Et David envoya des espions, et il sut très certainement que Saül était venu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Et David se leva, et vint au lieu où Saül était campé; et David vit le lieu où étaient couchés Saül et Abner, fils de Ner, chef de son armée: et Saül était couché dans l’enceinte des chars, et le peuple était campé tout autour de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Et David prit la parole, et dit à Akhimélec, le Héthien, et à Abishaï, fils de Tseruïa, frère de Joab, disant: Qui descendra avec moi vers Saül, au camp? Et Abishaï dit: Moi, je descendrai avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Et David et Abishaï vinrent de nuit vers le peuple; et voici, Saül dormait, couché dans l’enceinte des chars, sa lance fichée en terre à son chevet; et Abner et le peuple étaient couchés autour de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Et Abishaï dit à David: Dieu a livré aujourd’hui ton ennemi en ta main; et maintenant, je te prie, que je le frappe de la lance jusqu’en terre, une seule fois, et je ne le referai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Et David dit à Abishaï: Ne le détruis pas! car qui étendra sa main sur l’oint de l’ Éternel et sera innocent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Et David dit: L’ Éternel est vivant, si ce n’est l’ Éternel qui le frappera, soit que son jour vienne et qu’il meure, soit qu’il descende à la bataille et soit emporté!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Loin de moi, de par l’ Éternel, que j’étende ma main sur l’oint de l’ Éternel! Mais prends maintenant, je te prie, la lance qui est à son chevet et la cruche à eau, et allons-nous-en.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Et David prit, du chevet de Saül, la lance et la cruche à eau, et ils s’en allèrent; et personne ne [les] vit, et personne ne [le] sut, et personne ne s’éveilla; car ils dormaient tous, car un profond sommeil [envoyé] par l’ Éternel était tombé sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Et David passa de l’autre côté, et se tint sur le sommet de la montagne, de loin: il y avait un grand espace entre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Et David cria au peuple et à Abner, fils de Ner, disant: Ne répondras-tu pas, Abner? Et Abner répondit et dit: Qui es-tu, toi qui cries au roi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Et David dit à Abner: N’es-tu pas un homme? et qui est comme toi en Israël? Et pourquoi n’as-tu pas gardé le roi, ton seigneur? car quelqu’un du peuple est venu pour tuer le roi, ton seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Ce que tu as fait là n’est pas bien. L’ Éternel est vivant, que vous êtes dignes de mort, vous qui n’avez pas gardé votre seigneur, l’oint de l’ Éternel! Et maintenant, regarde où est la lance du roi, et la cruche à eau qui était à son chevet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Et Saül reconnut la voix de David et dit: Est-ce là ta voix, mon fils David? Et David dit: C’est ma voix, ô roi, mon seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Et il dit: Pourquoi mon seigneur poursuit-il son serviteur? car qu’ai-je fait, et quel mal y a-t-il dans ma main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Et maintenant, que le roi, mon seigneur, écoute, je te prie, les paroles de son serviteur. Si c’est l’ Éternel qui t’a incité contre moi, qu’il accepte une offrande! mais si ce sont les fils des hommes, qu’ils soient maudits devant l’ Éternel, parce qu’ils m’ont chassé aujourd’hui pour que je ne sois pas associé à l’héritage de l’ Éternel, disant: Va, sers d’autres dieux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Et maintenant, que mon sang ne tombe point en terre loin de la face de l’ Éternel, car le roi d’Israël est sorti pour chercher une puce, comme on poursuivrait une perdrix dans les montagnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Et Saül dit: J’ai péché; reviens, mon fils David; car je ne te ferai plus de mal, puisque aujourd’hui mon âme a été précieuse à tes yeux. Voici, j’ai agi follement et j’ai commis une très grande erreur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Et David répondit et dit: Voici la lance du roi; qu’un des jeunes hommes passe ici, et la prenne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Et l’ Éternel rendra à chacun sa justice et sa fidélité, puisque l’ Éternel t’avait livré aujourd’hui en [ma] main, et que je n’ai pas voulu étendre ma main sur l’oint de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Et voici, comme ton âme a été aujourd’hui précieuse à mes yeux, que de même aussi mon âme soit précieuse aux yeux de l’ Éternel, et qu’il me délivre de toute détresse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Et Saül dit à David: Béni sois-tu, mon fils David! certainement tu feras de grandes choses et tu en viendras à bout. Et David alla son chemin, et Saül retourna en son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, '*Et David dit en son cœur: Maintenant, je périrai un jour par la main de Saül; il n’y a rien de bon pour moi que de me sauver en hâte dans le pays des Philistins, et Saül renoncera à me chercher encore dans tous les confins d’Israël, et j’échapperai à sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Et David se leva et passa, lui et 600 hommes qui étaient avec lui, vers Akish, fils de Maoc, roi de Gath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Et David habita chez Akish, à Gath, lui et ses hommes, chacun avec sa famille, David et ses deux femmes, Akhinoam, la Jizreélite, et Abigaïl, femme de Nabal, la Carmélite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Et on rapporta à Saül que David s’était enfui à Gath; et il ne le chercha plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Et David dit à Akish: Je te prie, si j’ai trouvé grâce à tes yeux, qu’on me donne un lieu dans l’une des villes de la campagne, et je demeurerai là; car pourquoi ton serviteur habiterait-il dans la ville royale avec toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Et, en ce jour-là, Akish lui donna Tsiklag; c’est pourquoi Tsiklag appartient aux rois de Juda jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Et le nombre des jours que David habita dans la campagne des Philistins fut d’un an et quatre mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Et David et ses hommes montèrent et firent des incursions chez les Gueshuriens, et les Guirziens, et les Amalékites; car ces [nations], dès les temps anciens, habitaient le pays, quand tu viens vers Shur et jusqu’au pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Et David frappa le pays; et il ne laissait vivre ni homme ni femme, et il prenait le menu et le gros bétail, et les ânes, et les chameaux, et les vêtements; et il s’en retournait et venait vers Akish.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Et Akish disait: N’avez-vous pas fait d’incursion aujourd’hui? Et David disait: Vers le midi de Juda, et vers le midi des Jerakhmeélites, et vers le midi des Kéniens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Et David ne laissait vivre ni homme ni femme pour les ramener à Gath, de peur, disait-il, qu’ils ne rapportent quelque chose contre nous, disant: Ainsi a fait David. Et telle fut sa coutume pendant tous les jours qu’il habita la campagne des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Et Akish crut David, et disait: Il s’est mis en mauvaise odeur auprès de son peuple, auprès d’Israël, et il sera mon serviteur à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Et il arriva, en ces jours-là, que les Philistins rassemblèrent leurs armées pour la guerre, pour combattre contre Israël; et Akish dit à David: Sache bien que tu sortiras avec moi [pour aller] au camp, toi et tes hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Et David dit à Akish: Aussi tu sauras ce que ton serviteur fera. Et Akish dit à David: Aussi je t’établirai, pour toujours, gardien de ma personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Or Samuel était mort, et tout Israël s’était lamenté sur lui, et on l’avait enterré à Rama, dans sa ville. Et Saül avait ôté du pays les évocateurs d’esprits et les diseurs de bonne aventure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Et les Philistins s’assemblèrent, et ils vinrent, et campèrent à Sunem; et Saül rassembla tout Israël, et ils campèrent à Guilboa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Et Saül vit le camp des Philistins, et il eut peur, et son cœur trembla très fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Et Saül interrogea l’ Éternel, et l’ Éternel ne lui répondit pas, ni par les songes, ni par l’urim, ni par les prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Et Saül dit à ses serviteurs: Cherchez-moi une femme qui évoque les esprits, et j’irai vers elle, et je la consulterai. Et ses serviteurs lui dirent: Voici, il y a à En-Dor une femme qui évoque les esprits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Et Saül se déguisa et revêtit d’autres vêtements, et il s’en alla, lui et deux hommes avec lui, et ils vinrent de nuit chez la femme. Et il dit: Devine pour moi, je te prie, par un esprit, et fais-moi monter celui que je te dirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Et la femme lui dit: Voici, tu sais ce que Saül a fait, qu’il a retranché du pays les évocateurs d’esprits et les diseurs de bonne aventure; et pourquoi dresses-tu un piège à mon âme pour me faire mourir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Et Saül lui jura par l’ Éternel, disant: L’ Éternel est vivant, s’il t’arrive aucun mal pour cette affaire!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Et la femme dit: Qui te ferai-je monter? Et il dit: Fais-moi monter Samuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Et la femme vit Samuel, et elle poussa un grand cri; et la femme parla à Saül, disant: Pourquoi m’as-tu trompée? et tu es Saül!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Et le roi lui dit: Ne crains point; mais que vois-tu? Et la femme dit à Saül: Je vois un dieu qui monte de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Et il lui dit: Quelle est sa forme? Et elle dit: C’est un vieillard qui monte, et il est enveloppé d’un manteau. Et Saül connut que c’était Samuel; et il se baissa le visage contre terre et se prosterna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Et Samuel dit à Saül: Pourquoi as-tu troublé mon repos en me faisant monter? Et Saül dit: Je suis dans une grande détresse; car les Philistins me font la guerre, et Dieu s’est retiré de moi, et ne me répond plus, ni par les prophètes, ni par les songes; et je t’ai appelé pour me faire savoir ce que j’ai à faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Et Samuel dit: Et pourquoi m’interroges-tu, quand l’ Éternel s’est retiré de toi et qu’il est devenu ton ennemi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Et l’ Éternel a fait pour lui-même comme il l’a dit par moi; et l’ Éternel a déchiré le royaume d’entre tes mains et l’a donné à ton prochain, à David;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'parce que tu n’as pas écouté la voix de l’ Éternel et que tu n’as pas exécuté l’ardeur de sa colère contre Amalek: à cause de cela, l’ Éternel t’a fait ceci aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Et l’ Éternel livrera aussi Israël avec toi en la main des Philistins; et demain, toi et tes fils, vous serez avec moi; l’ Éternel livrera aussi l’armée d’Israël en la main des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Et Saül aussitôt tomba à terre de toute sa hauteur, et il fut extrêmement effrayé des paroles de Samuel; même il n’y avait plus de force en lui, car il n’avait pas mangé de pain de tout le jour et de toute la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Et la femme vint à Saül, et elle vit qu’il était très troublé, et elle lui dit: Voici, ta servante a écouté ta voix, et j’ai mis ma vie dans ma main, et j’ai écouté les paroles que tu m’as dites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'et maintenant, je te prie, écoute, toi aussi, la voix de ta servante, et je mettrai devant toi une bouchée de pain, et mange, et tu auras de la force pour aller ton chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Et il refusa et dit: Je ne mangerai point. Et ses serviteurs et la femme aussi le pressèrent; et il écouta leur voix, et se leva de terre et s’assit sur le lit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Et la femme avait dans la maison un veau gras, et elle se hâta de le tuer; et elle prit de la farine et la pétrit, et en cuisit des pains sans levain,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'qu’elle apporta devant Saül et devant ses serviteurs; et ils mangèrent; et ils se levèrent, et s’en allèrent cette même nuit-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, '*Et les Philistins rassemblèrent toutes leurs armées à Aphek; et Israël était campé à la source qui est à Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Et les princes des Philistins passèrent par centaines et par milliers, et David et ses hommes passèrent à l’arrière-garde avec Akish.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Et les chefs des Philistins dirent: Que sont ces Hébreux? Et Akish dit aux chefs des Philistins: N’est-ce pas David, serviteur de Saül, roi d’Israël, qui a été avec moi tant de jours [déjà], ou tant d’années? et je n’ai rien trouvé en lui, depuis le jour où il est tombé chez moi jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Et les chefs des Philistins se mirent en colère contre lui, et les chefs des Philistins lui dirent: Renvoie cet homme, et qu’il retourne en son lieu, là où tu l’as établi, et qu’il ne descende pas avec nous à la bataille, afin qu’il ne soit pas notre adversaire dans la bataille; car comment celui-là se rendrait-il agréable à son seigneur, sinon avec les têtes de ces hommes-ci?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'N’est-ce pas ce David, au sujet duquel on s’entre-répondait dans les danses, en disant: Saül a frappé ses 1 000, et David ses 10 000?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Et Akish appela David, et lui dit: L’ Éternel est vivant, que tu es [un homme] droit, et ta sortie et ton entrée avec moi à l’armée ont été bonnes à mes yeux, car je n’ai pas trouvé de mal en toi depuis le jour de ton entrée auprès de moi jusqu’à ce jour; mais tu n’es pas agréable aux yeux des princes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Et maintenant, retourne-t’en et va en paix, afin que tu ne fasses rien qui soit mauvais aux yeux des princes des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Et David dit à Akish: Mais qu’ai-je fait? et qu’as-tu trouvé en ton serviteur, depuis le jour où j’ai été devant toi jusqu’à ce jour, pour que je ne puisse pas aller et combattre contre les ennemis du roi, mon seigneur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Et Akish répondit et dit à David: Je sais que tu es agréable à mes yeux comme un ange de Dieu; seulement les chefs des Philistins ont dit: Il ne montera point avec nous à la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Et maintenant, lève-toi de bonne heure le matin, et les serviteurs de ton seigneur qui sont venus avec toi, et levez-vous de bon matin, dès qu’il fait jour, et allez-vous-en.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Et David se leva de bonne heure, lui et ses hommes, pour partir dès le matin, afin de retourner au pays des Philistins. Et les Philistins montèrent à Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, '*Et il se trouva que, lorsque David et ses hommes arrivèrent à Tsiklag, le troisième jour, les Amalékites avaient fait une incursion sur le [pays du] midi, et sur Tsiklag; et ils avaient frappé Tsiklag et l’avaient brûlée par le feu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'et ils avaient emmené captives les femmes qui y étaient; depuis le petit jusqu’au grand, ils n’avaient fait mourir personne, mais ils les avaient emmenés et s’en étaient allés leur chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Et David et ses hommes vinrent à la ville; et voici, elle était brûlée par le feu, et leurs femmes, et leurs fils, et leurs filles, étaient emmenés captifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Et David et le peuple qui était avec lui élevèrent leurs voix et pleurèrent, jusqu’à ce qu’il n’y eut plus en eux de force pour pleurer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Et les deux femmes de David, Akhinoam, la Jizreélite, et Abigaïl, femme de Nabal, le Carmélite, étaient emmenées captives.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Et David fut dans une grande détresse, car le peuple parlait de le lapider; car l’âme de tout le peuple était pleine d’amertume, chacun à cause de ses fils et à cause de ses filles. Et David se fortifia en l’ Éternel, son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Et David dit à Abiathar, le sacrificateur, fils d’Akhimélec: Je te prie, apporte-moi l’éphod. Et Abiathar apporta l’éphod à David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Et David interrogea l’ Éternel, disant: Poursuivrai-je cette troupe? l’atteindrai-je? Et il lui dit: Poursuis, car tu l’atteindras certainement, et tu recouvreras tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Et David s’en alla, lui et les 600 hommes qui étaient avec lui, et ils arrivèrent au torrent de Besçor; et ceux qui restaient en arrière s’arrêtèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Et David et 400 hommes firent la poursuite, et 200 hommes s’arrêtèrent, qui étaient trop fatigués pour passer le torrent de Besçor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Et ils trouvèrent dans les champs un homme égyptien, et ils l’amenèrent à David; et ils lui donnèrent du pain, et il mangea, et ils lui donnèrent de l’eau à boire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'ils lui donnèrent aussi un morceau de gâteau de figues sèches et deux gâteaux de raisins secs, et il mangea; et l’esprit lui revint, car il n’avait pas mangé de pain et n’avait pas bu d’eau, pendant trois jours et trois nuits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Et David lui dit: À qui es-tu? et d’où es-tu? Et il dit: Je suis un garçon égyptien, serviteur d’un homme amalékite; et mon maître m’a abandonné, il y a trois jours, car j’étais malade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Nous avons fait une incursion au midi des Keréthiens, et sur ce qui est à Juda, et sur le midi de Caleb, et nous avons brûlé Tsiklag par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Et David lui dit: Me ferais-tu descendre vers cette troupe? Et il dit: Jure-moi par Dieu que tu ne me feras pas mourir, et que tu ne me livreras pas en la main de mon maître, et je te ferai descendre vers cette troupe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Et il l’y fit descendre. Et voici, ils étaient répandus sur la face de tout le pays, mangeant et buvant, et dansant, à cause de tout le grand butin qu’ils avaient enlevé du pays des Philistins et du pays de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Et David les frappa depuis le crépuscule jusqu’au soir du lendemain, et aucun d’eux n’échappa, sauf 400 jeunes hommes qui s’enfuirent montés sur des chameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Et David recouvra tout ce qu’Amalek avait pris, et David recouvra ses deux femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Et il n’y eut rien qui leur manque, petits ou grands, fils ou filles, butin, ou quoi que ce soit qu’on leur avait pris: David ramena tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Et David prit tout le menu et le gros bétail qu’on fit marcher devant ce troupeau-là; et on dit: C’est ici le butin de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Et David vint vers les 200 hommes qui avaient été trop fatigués pour suivre David, et qu’on avait fait rester auprès du torrent de Besçor; et ils sortirent à la rencontre de David et à la rencontre du peuple qui était avec lui; et David s’approcha du peuple, et les interrogea touchant leur bien-être.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Et tout homme méchant et inique, d’entre les hommes qui étaient allés avec David, répondit et dit: Puisqu’ ils ne sont pas venus avec nous, nous ne leur donnerons pas du butin que nous avons recouvré, sauf à chacun sa femme et ses fils; et qu’ils les emmènent et s’en aillent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Mais David dit: Vous ne ferez pas ainsi mes frères, avec ce que nous a donné l’ Éternel, qui nous a gardés et a livré entre nos mains la troupe qui était venue contre nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Et qui vous écoutera dans cette affaire? Car telle qu’est la part de celui qui descend à la bataille, telle sera la part de celui qui demeure auprès du bagage: ils partageront ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Et il en fut [ainsi] depuis ce jour-là et dans la suite, et on l’établit comme statut et comme ordonnance en Israël, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Et David revint à Tsiklag, et envoya du butin aux anciens de Juda, à ses amis, disant: Voici un présent pour vous, sur le butin des ennemis de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, '[Il en envoya] à ceux qui étaient à Béthel, et à ceux qui étaient à Ramoth du midi, et à ceux qui étaient à Jatthir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'et à ceux qui étaient à Aroër, et à ceux qui étaient à Siphmoth, et à ceux qui étaient à Eshtemoa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'et à ceux qui étaient à Racal, et à ceux qui étaient dans les villes des Jerakhmeélites, et à ceux qui étaient dans les villes des Kéniens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'et à ceux qui étaient à Horma, et à ceux qui étaient à Cor-Ashan, et à ceux qui étaient à Athac,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'et à ceux qui étaient à Hébron, et dans tous les lieux où David était allé et venu, lui et ses hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, '*Et les Philistins combattirent contre Israël, et les hommes d’Israël s’enfuirent devant les Philistins, et tombèrent tués sur la montagne de Guilboa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Et les Philistins pressèrent fortement Saül et ses fils; et les Philistins frappèrent Jonathan, et Abinadab, et Malki-Shua, fils de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Et la bataille se renforça contre Saül, et les archers l’atteignirent; et il eut une très grande peur des archers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Et Saül dit à celui qui portait ses armes: Tire ton épée et perce-m’en, de peur que ces incirconcis ne viennent et ne me percent, et ne m’outragent. Et celui qui portait ses armes ne voulut pas [le faire], car il avait très peur. Et Saül prit son épée et se jeta dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Et quand celui qui portait ses armes vit que Saül était mort, il se jeta, lui aussi, sur son épée, et mourut avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Et en ce jour moururent ensemble Saül et ses trois fils, et celui qui portait ses armes, et tous ses hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Et les hommes d’Israël qui étaient de ce côté de la vallée, et ceux qui étaient de ce côté du Jourdain, virent que les hommes d’Israël s’enfuyaient, et que Saül et ses fils étaient morts, et ils abandonnèrent les villes, et s’enfuirent; et les Philistins vinrent et y habitèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Et il arriva que, le lendemain, les Philistins vinrent pour dépouiller les tués; et ils trouvèrent Saül et ses trois fils tombés sur la montagne de Guilboa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Et ils lui coupèrent la tête, et le dépouillèrent de ses armes, et les envoyèrent partout dans le pays des Philistins pour annoncer la bonne nouvelle dans les maisons de leurs idoles et au peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Et ils placèrent ses armes dans la maison d’Ashtaroth, et clouèrent son corps à la muraille de Beth-Shan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Et les habitants de Jabès de Galaad entendirent parler de ce que les Philistins avaient fait à Saül;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'et tous les hommes vaillants se levèrent et marchèrent toute la nuit, et prirent de la muraille de Beth-Shan le corps de Saül et les corps de ses fils, et vinrent à Jabès, et les brûlèrent là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Et ils prirent leurs os, et les enterrèrent sous le tamaris de Jabès, et jeûnèrent sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Et il arriva, après la mort de Saül, quand David fut revenu d’avoir frappé Amalek, que David habita deux jours à Tsiklag.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Et, le troisième jour, voici, un homme vint du camp, d’auprès de Saül, ses vêtements déchirés et de la terre sur sa tête; et aussitôt qu’il arriva auprès de David, il tomba contre terre et se prosterna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Et David lui dit: D’où viens-tu? Et il lui dit: Je me suis échappé du camp d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Et David lui dit: Que s’est-il passé? raconte-le-moi, je te prie. Et il dit que le peuple s’était enfui de la bataille, et que beaucoup d’entre le peuple étaient tombés et étaient morts, et que Saül aussi et Jonathan, son fils, étaient morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Et David dit au jeune homme qui lui racontait [ces choses]: Comment sais-tu que Saül et Jonathan, son fils, sont morts?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Et le jeune homme qui lui rapportait [ces choses] dit: Je passais par aventure sur la montagne de Guilboa; et voici, Saül s’appuyait sur sa lance, et voici, les chars et les gens de cheval le serraient de près.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Et il se tourna en arrière et me vit, et m’appela; et je dis: Me voici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Et il me dit: Qui es-tu? Et je lui dis: Je suis Amalékite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Et il me dit: Tiens-toi, je te prie, sur moi, et tue-moi, car l’angoisse m’a saisi, parce que ma vie est encore toute en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Alors je me suis tenu sur lui, et je l’ai mis à mort; car je savais qu’il ne vivrait pas après sa chute; et j’ai pris la couronne qui était sur sa tête et le bracelet qui était à son bras, et je les ai apportés ici à mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Alors David saisit ses vêtements et les déchira; et tous les hommes qui étaient avec lui [firent] de même;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'et ils menèrent deuil, et pleurèrent, et jeûnèrent jusqu’au soir sur Saül et sur Jonathan, son fils, et sur le peuple de l’ Éternel, et sur la maison d’Israël, parce qu’ils étaient tombés par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Et David dit au jeune homme qui lui avait rapporté [ces choses]: D’où es-tu? Et il dit: Je suis fils d’un homme étranger, d’un Amalékite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Et David lui dit: Comment n’as-tu pas craint d’étendre ta main pour tuer l’oint de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Alors David appela un des jeunes hommes et [lui] dit: Approche [et] jette-toi sur lui! Et il le frappa, et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Et David lui dit: Ton sang soit sur ta tête, car ta bouche a témoigné contre toi, disant: J’ai mis à mort l’oint de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Et David prononça sur Saül et sur Jonathan, son fils, cette complainte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'et il dit d’enseigner aux fils de Juda [le chant de] l’Arc; voici, il est écrit au livre de Jashar:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Ton ornement, ô Israël, est tué sur tes hauts lieux. Comment les hommes forts sont-ils tombés!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Ne le racontez pas dans Gath, n’en portez pas la nouvelle dans les rues d’Askalon; de peur que les filles des Philistins ne se réjouissent, de peur que les filles des incirconcis ne tressaillent de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Montagnes de Guilboa, qu’il n’y ait pas de rosée, pas de pluie sur vous, ni des champs d’offrandes; car là fut jeté comme une chose souillée le bouclier des hommes forts, le bouclier de Saül, [comme s’il n’avait] pas été oint d’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'L’arc de Jonathan ne se retirait pas du sang des tués [et] de la graisse des hommes forts; et l’épée de Saül ne retournait pas à vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saül et Jonathan, aimés et agréables dans leur vie, n’ont pas été séparés dans leur mort. Ils étaient plus rapides que les aigles, plus forts que les lions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Filles d’Israël, pleurez sur Saül, qui vous revêtait d’écarlate, magnifiquement, qui a couvert vos vêtements d’ornements d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Comment les hommes forts sont-ils tombés au milieu de la bataille! Comment Jonathan a-t-il été tué sur tes hauts lieux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Je suis dans l’angoisse à cause de toi, Jonathan, mon frère! Tu étais pour moi plein de charmes; ton amour pour moi était merveilleux, plus [grand] que l’amour des femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Comment sont tombés les hommes forts, et ont péris les instruments de guerre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Et il arriva, après cela, que David interrogea l’ Éternel, disant: Monterai-je dans une des villes de Juda? Et l’ Éternel lui dit: Monte. Et David dit: Où monterai-je? Et il dit: À Hébron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Et David y monta, et ses deux femmes aussi, Akhinoam, la Jizreélite, et Abigaïl, femme de Nabal, le Carmélite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Et ses hommes qui étaient avec lui, David les fit monter, chacun avec sa maison, et ils habitèrent dans les villes de Hébron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Et les hommes de Juda vinrent et oignirent là David pour roi sur la maison de Juda. Et on rapporta à David, disant: Ce sont les hommes de Jabès de Galaad qui ont enterré Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Et David envoya des messagers aux hommes de Jabès de Galaad, et leur fit dire: Bénis soyez-vous de l’ Éternel, de ce que vous avez usé de cette bonté envers votre seigneur Saül, et de ce que vous l’avez enterré!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Et maintenant, que l’ Éternel use envers vous de bonté et de vérité! Et moi aussi je vous rendrai ce bien, parce que vous avez fait cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Et maintenant, que vos mains se fortifient, et soyez des hommes vaillants; car votre seigneur Saül est mort, et de plus, c’est moi que la maison de Juda a oint pour roi sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Et Abner, fils de Ner, chef de l’armée de Saül, prit Ish-Bosheth, fils de Saül, et le fit passer à Mahanaïm');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'et l’établit roi sur Galaad, et sur les Ashurites, et sur Jizreël, et sur Éphraïm, et sur Benjamin, et sur Israël tout entier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Ish-Bosheth, fils de Saül, était âgé de 40 ans lorsqu’il régna sur Israël, et il régna deux ans. Toutefois la maison de Juda suivit David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Et le nombre des jours, pendant lesquels David fut roi à Hébron sur la maison de Juda, fut de sept ans et six mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Et Abner, fils de Ner, et les serviteurs d’Ish-Bosheth, fils de Saül, sortirent de Mahanaïm vers Gabaon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'et Joab, fils de Tseruïa, et les serviteurs de David, sortirent aussi; et ils se rencontrèrent ensemble près du réservoir de Gabaon; et ceux-ci s’assirent d’un côté du réservoir, et ceux-là de l’autre côté du réservoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Et Abner dit à Joab: Que les jeunes hommes se lèvent donc et jouent [entre eux] devant nous! Et Joab dit: Qu’ils se lèvent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Et ils se levèrent et passèrent, au nombre de douze pour Benjamin et pour Ish-Bosheth, fils de Saül, et de douze d’entre les serviteurs de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Et chacun saisit son adversaire par la tête, et [passa] son épée dans le flanc de son adversaire, et ils tombèrent [tous] ensemble. Et on appela ce lieu-là Helkath-Hatsurim, qui est en Gabaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Et le combat fut très rude ce jour-là; et Abner et les hommes d’Israël furent battus devant les serviteurs de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Et il y avait là trois fils de Tseruïa, Joab, et Abishaï, et Asçaël. Et Asçaël était léger de ses pieds comme une des gazelles qui sont dans les champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Et Asçaël poursuivit Abner, et il ne se détourna pas d’Abner pour aller à droite ou à gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Et Abner regarda derrière lui, et dit: Est-ce toi, Asçaël? Et il dit: C’est moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Et Abner lui dit: Détourne-toi à droite ou à gauche, et saisis-toi de l’un des jeunes hommes et prends pour toi son armure. Mais Asçaël ne voulut pas se détourner de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Et Abner dit encore à Asçaël: Détourne-toi de moi! Pourquoi te jetterais-je mort par terre? Et comment lèverais-je ma face devant Joab, ton frère?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Mais il refusa de se détourner, et Abner le frappa au ventre avec la hampe de sa lance, et sa lance lui sortit par-derrière, et il tomba là et mourut sur place. Et tous ceux qui venaient à l’endroit où Asçaël était tombé et était mort, s’arrêtaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Et Joab et Abishaï poursuivirent Abner; et le soleil se couchait quand ils arrivèrent à la colline d’Amma, qui est devant Guiakh, sur le chemin du désert de Gabaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Et les fils de Benjamin se rassemblèrent derrière Abner; et ils formèrent une seule troupe, et se tinrent sur le sommet d’une colline.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Et Abner cria à Joab et dit: L’épée dévorera-t-elle à toujours? Ne sais-tu pas qu’il y aura de l’amertume à la fin? et jusques à quand ne diras-tu pas au peuple de revenir de la poursuite de ses frères?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Et Joab dit: Dieu est vivant, que, si tu n’avais parlé, dès le matin [déjà] le peuple se serait retiré, chacun de la poursuite de son frère!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Et Joab sonna de la trompette, et tout le peuple s’arrêta; et ils ne poursuivirent plus Israël, et ils ne continuèrent plus à se battre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Et Abner et ses hommes marchèrent toute cette nuit-là dans la plaine, et traversèrent le Jourdain, et marchèrent par tout le Bithron, et vinrent à Mahanaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Et Joab s’en retourna de la poursuite d’Abner et rassembla tout le peuple; et, des serviteurs de David, il manquait 19 hommes et Asçaël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Et les serviteurs de David avaient frappé à mort 360 hommes de Benjamin et des hommes d’Abner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Et ils enlevèrent Asçaël, et l’enterrèrent dans le sépulcre de son père, qui était à Bethléhem; et Joab et ses hommes marchèrent toute la nuit; et il faisait jour lorsqu’ils [arrivèrent] à Hébron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Et la guerre fut longue entre la maison de Saül et la maison de David. Et David allait se fortifiant, et la maison de Saül allait s’affaiblissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Et il naquit à David des fils à Hébron: son premier-né fut Amnon, d’Akhinoam, la Jizreélite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'et le second, Kileab, d’Abigaïl, femme de Nabal, le Carmélite; et le troisième, Absalom, fils de Maaca, fille de Talmaï, roi de Gueshur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'et le quatrième, Adonija, fils de Hagguith; et le cinquième, Shephatia, fils d’Abital;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'et le sixième, Jithream, d’Égla, femme de David. Ceux-ci naquirent à David à Hébron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Et il arriva que, pendant qu’il y eut guerre entre la maison de Saül et la maison de David, Abner tint ferme pour la maison de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Et Saül avait une concubine: son nom était Ritspa, fille d’Aïa; et [Ish-Bosheth] dit à Abner: Pourquoi es-tu entré vers la concubine de mon père?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Et Abner fut fort irrité à cause des paroles d’Ish-Bosheth, et il dit: Suis-je une tête de chien, moi qui aujourd’hui, contre Juda, ai usé de bonté envers la maison de Saül, ton père, envers ses frères et envers ses amis, et qui ne t’ai pas livré aux mains de David, que tu m’imputes aujourd’hui de l’iniquité à cause de cette femme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Que Dieu fasse ainsi à Abner et ainsi y ajoute, si je ne fais pas à David comme l’ Éternel lui a juré,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'en faisant passer le royaume de la maison de Saül, et en établissant le trône de David sur Israël et sur Juda, depuis Dan jusqu’à Beër-Shéba!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Et [Ish-Bosheth] ne put répliquer un mot à Abner, parce qu’il avait peur de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Et Abner envoya des messagers à David de sa part, disant: À qui est le pays? – disant: Fais alliance avec moi; et voici, ma main sera avec toi pour tourner vers toi tout Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Et [David] dit: Bien, je ferai alliance avec toi; seulement je demande de toi une chose, savoir: Tu ne verras pas ma face, à moins qu’ auparavant tu ne fasses venir Mical, fille de Saül, quand tu viendras pour voir ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Et David envoya des messagers à Ish-Bosheth, fils de Saül, disant: Donne-moi ma femme Mical, que je me suis fiancée pour 100 prépuces de Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Et Ish-Bosheth envoya, et la prit d’auprès de son mari, d’auprès de Paltiel, fils de Laïsh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Et son mari alla avec elle, marchant et pleurant après elle, jusqu’à Bakhurim. Et Abner lui dit: Va, retourne-t’en. Et il s’en retourna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Et Abner s’était entretenu avec les anciens d’Israël, disant: Avant vous recherchiez David, pour qu’il soit roi sur vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'et maintenant, agissez; car l’ Éternel a parlé touchant David, disant: Par la main de David, mon serviteur, je délivrerai mon peuple Israël de la main des Philistins et de la main de tous ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Et Abner parla aussi aux oreilles de Benjamin, et Abner alla aussi pour dire aux oreilles de David, à Hébron, tout ce qui était bon aux yeux d’Israël et aux yeux de toute la maison de Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Et Abner vint vers David, à Hébron, et avec lui 20 hommes; et David fit un festin à Abner, ainsi qu’aux hommes qui étaient avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Et Abner dit à David: Je me lèverai, et j’irai, et j’assemblerai vers mon seigneur, le roi, tout Israël; et ils feront alliance avec toi; et tu régneras sur tout ce que ton âme désire. Et David congédia Abner, et il s’en alla en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Et voici, les serviteurs de David, et Joab, revenaient d’une expédition, et ils amenaient avec eux un grand butin; et Abner n’était pas avec David, à Hébron, car il l’avait congédié, et il s’en était allé en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Et Joab et toute l’armée qui était avec lui vinrent; et on rapporta à Joab, en disant: Abner, fils de Ner, est venu vers le roi qui l’a congédié, et il s’en est allé en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Et Joab entra auprès du roi et dit: Qu’as-tu fait? Voici, Abner est venu vers toi; pourquoi l’as-tu congédié, en sorte qu’il s’en est allé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Tu connais Abner, fils de Ner, qu’il est venu pour te tromper, et pour connaître tes sorties et tes entrées, et pour savoir tout ce que tu fais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Et Joab sortit d’auprès de David, et envoya après Abner des messagers qui le firent rebrousser depuis la citerne de Sira; et David ne le savait pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Et Abner revint à Hébron, et Joab le tira à part au milieu de la porte, pour lui parler tranquillement, et là il le frappa au ventre, en sorte qu’il mourut, à cause du sang de son frère Asçaël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Et David l’apprit plus tard, et il dit: Je suis innocent, moi et mon royaume, devant l’ Éternel, à jamais, du sang d’Abner, fils de Ner:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'qu’il tombe sur la tête de Joab, et sur toute la maison de son père; et que la maison de Joab ne soit jamais sans un homme ayant un flux, ou la lèpre, ou qui s’appuie sur un bâton, ou qui tombe par l’épée, ou qui manque de pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Ainsi Joab et Abishaï, son frère, tuèrent Abner, parce qu’il avait donné la mort à Asçaël, leur frère, à Gabaon, dans la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Et David dit à Joab et à tout le peuple qui était avec lui: Déchirez vos vêtements et ceignez-vous de sacs, et menez deuil devant Abner. Et le roi David marchait après le cercueil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Et ils enterrèrent Abner à Hébron; et le roi éleva sa voix et pleura au sépulcre d’Abner; et tout le peuple pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Et le roi prononça une complainte sur Abner, et dit: Abner devait-il mourir comme meurt un insensé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Tes mains n’étaient pas liées, et tes pieds n’avaient pas été mis dans des chaînes; tu es tombé comme on tombe devant les fils d’iniquité. Et tout le peuple pleura encore sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Et tout le peuple vint vers David pour l’engager à manger du pain, pendant qu’il était encore jour; mais David jura, disant: Que Dieu me fasse ainsi et ainsi y ajoute, si avant que le soleil se soit couché, je goûte du pain ou aucune autre chose!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Et tout le peuple y eut égard, et cela fut bon à leurs yeux, comme tout ce que faisait le roi était bon aux yeux de tout le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Et en ce jour-là tout le peuple et tout Israël reconnurent que ce n’était point de par le roi qu’on avait fait mourir Abner, fils de Ner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Et le roi dit à ses serviteurs: Ne savez-vous pas qu’un prince, et un grand homme, est tombé aujourd’hui en Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Et moi, je suis aujourd’hui faible, bien que j’aie reçu l’onction de roi; et ces hommes-là, les fils de Tseruïa, sont trop durs pour moi. Que l’ Éternel rende à celui qui fait le mal, selon son méfait!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Et quand le fils de Saül apprit qu’Abner était mort à Hébron, ses mains furent affaiblies, et tout Israël fut troublé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Et il y avait deux hommes, chefs de bandes du fils de Saül; le nom de l’un était Baana, et le nom du second, Récab: [ils étaient] fils de Rimmon, le Beérothien, d’entre les fils de Benjamin; car aussi Beéroth est comptée comme étant de Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Et les Beérothiens s’enfuirent à Guitthaïm, et ils y ont séjourné jusqu’à aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Et Jonathan, fils de Saül, avait un fils perclus des pieds; il était âgé de cinq ans lorsque le bruit touchant Saül et Jonathan vint de Jizreël; et sa nourrice l’emporta et s’enfuit; et il arriva que, comme elle se hâtait de fuir, il tomba et devint boiteux; et son nom était Mephibosheth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Et les fils de Rimmon, le Beérothien, Récab et Baana, s’en allèrent et vinrent, pendant la chaleur du jour, dans la maison d’Ish-Bosheth; et il était couché pour son repos de midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Et ils entrèrent jusque dans l’intérieur de la maison, comme pour prendre du froment, et ils le frappèrent au ventre; et Récab et Baana, son frère, s’échappèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Ils entrèrent dans la maison pendant qu’il était couché sur son lit dans sa chambre à coucher, et ils le frappèrent et le tuèrent; et ils lui ôtèrent la tête, et ils prirent sa tête, et s’en allèrent toute la nuit par le chemin de la plaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Et ils apportèrent la tête d’Ish-Bosheth à David, à Hébron, et ils dirent au roi: Voici la tête d’Ish-Bosheth, fils de Saül, ton ennemi qui cherchait ta vie; et l’ Éternel a donné en ce jour au roi, mon seigneur, d’être vengé de Saül et de sa race.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Et David répondit à Récab et à Baana, son frère, fils de Rimmon, le Beérothien, et leur dit: L’ Éternel est vivant, qui a racheté mon âme de toute détresse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'que celui qui me rapporta, disant: Voici, Saül est mort! et qui était à ses propres yeux comme un messager de bonnes nouvelles, je le saisis et le tuai à Tsiklag, lui donnant [ainsi] le salaire de sa bonne nouvelle:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'combien plus, quand de méchants hommes ont tué un homme juste dans sa maison, sur son lit! Et maintenant, ne redemanderai-je pas son sang de votre main; et ne vous exterminerai-je pas de la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Et David commanda à ses jeunes hommes, et ils les tuèrent et leur coupèrent les mains et les pieds, et les pendirent au réservoir de Hébron. Et on prit la tête d’Ish-Bosheth, et on l’enterra dans le sépulcre d’Abner, à Hébron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, '*Et toutes les tribus d’Israël vinrent vers David à Hébron, et parlèrent, disant: Voici, nous sommes ton os et ta chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Et autrefois, quand Saül était roi sur nous, c’était toi qui faisais sortir et qui faisais entrer Israël; et l’ Éternel t’a dit: Tu paîtras mon peuple Israël, et tu seras prince sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Et tous les anciens d’Israël vinrent vers le roi à Hébron; et le roi David fit alliance avec eux à Hébron, devant l’ Éternel; et ils oignirent David pour roi sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'David était âgé de 30 ans lorsqu’il devint roi; il régna 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Il régna à Hébron, sur Juda, sept ans et six mois; et, à Jérusalem, il régna 33 ans sur tout Israël et Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Et le roi alla avec ses hommes à Jérusalem contre les Jébusiens, habitants du pays; et ils parlèrent à David, disant: Tu n’entreras point ici; mais les aveugles et les boiteux te repousseront; – pour dire: David n’entrera pas ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Mais David prit la forteresse de Sion: c’est la ville de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Et David dit en ce jour-là: Quiconque frappera les Jébusiens et atteindra le canal, et les boiteux et les aveugles qui sont haïs de l’âme de David...! C’est pourquoi on dit: L’aveugle et le boiteux n’entreront pas dans la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Et David habita dans la forteresse, et l’appela ville de David; et David bâtit tout autour, depuis Millo vers l’intérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Et David allait grandissant de plus en plus; et l’ Éternel, le Dieu des armées, était avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Et Hiram, roi de Tyr, envoya des messagers à David, et des bois de cèdre, et des charpentiers, et des tailleurs de pierres pour les murailles; et ils bâtirent une maison à David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Et David connut que l’ Éternel l’avait établi roi sur Israël, et qu’il avait élevé son royaume à cause de son peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Et David prit encore des concubines et des femmes de Jérusalem, après qu’il fut venu de Hébron, et il naquit encore à David des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Et ce sont ici les noms de ceux qui lui naquirent à Jérusalem: Shammua, et Shobab, et Nathan, et Salomon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'et Jibkhar, et Élishua, et Népheg, et Japhia,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'et Élishama, et Éliada, et Éliphéleth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Et les Philistins apprirent qu’on avait oint David pour roi sur Israël, et tous les Philistins montèrent pour chercher David; et David l’apprit, et descendit à la forteresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Et les Philistins vinrent et se répandirent dans la vallée des Rephaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Et David interrogea l’ Éternel, disant: Monterai-je contre les Philistins? Les livreras-tu en ma main? Et l’ Éternel dit à David: Monte, car certainement je livrerai les Philistins en ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Et David vint à Baal-Peratsim; et là David les frappa, et il dit: L’ Éternel a fait une brèche au milieu de mes ennemis devant moi, comme une brèche faite par les eaux; c’est pourquoi il appela le nom de ce lieu Baal-Peratsim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Et ils laissèrent là leurs idoles, et David et ses hommes les emportèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Et les Philistins montèrent encore de nouveau, et se répandirent dans la vallée des Rephaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Et David interrogea l’ Éternel. Et il dit: Tu ne monteras pas; tourne-les par-derrière, et tu viendras contre eux vis-à-vis des mûriers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'et aussitôt que tu entendras sur le sommet des mûriers un bruit de gens qui marchent, alors tu t’élanceras, car alors l’ Éternel sera sorti devant toi pour frapper l’armée des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'Et David fit ainsi, comme l’ Éternel lui avait commandé; et il frappa les Philistins depuis Guéba jusqu’à ce que tu viennes vers Guézer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, '*Et David assembla encore toute l’élite d’Israël, 30 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Et David se leva et se mit en marche, et tout le peuple qui était avec lui, vers Baalé de Juda, pour en faire monter l’arche de Dieu, qui est appelée du nom, du nom de l’ Éternel des armées, qui siège entre les chérubins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Et ils montèrent l’arche de Dieu sur un chariot neuf, et l’emmenèrent de la maison d’Abinadab, qui était sur la colline; et Uzza et Akhio, les fils d’Abinadab, conduisaient le chariot neuf.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Et ils l’emmenèrent, avec l’arche de Dieu, de la maison d’Abinadab, qui était sur la colline, et Akhio allait devant l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Et David et toute la maison d’Israël s’égayaient devant l’ Éternel avec toutes sortes [d’instruments] de bois de cyprès: avec des harpes, et des luths, et des tambourins, et des sistres, et des cymbales.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Et ils arrivèrent à l’aire de Nacon, et Uzza étendit [la main] vers l’arche de Dieu et la saisit, parce que les bœufs avaient bronché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Et la colère de l’ Éternel s’embrasa contre Uzza, et Dieu le frappa là à cause de sa faute; et il mourut là, près de l’arche de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Alors David fut irrité de ce que l’ Éternel avait fait une brèche en [la personne d’]Uzza; et il appela ce lieu-là du nom de Pérets-Uzza, [qui lui est resté] jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Et David eut peur de l’ Éternel en ce jour-là, et il dit: Comment l’arche de l’ Éternel entrerait-elle chez moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Et David ne voulut pas retirer l’arche de l’ Éternel chez lui dans la ville de David, mais David la fit détourner dans la maison d’Obed-Édom, le Guitthien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Et l’arche de l’ Éternel demeura trois mois dans la maison d’Obed-Édom, le Guitthien; et l’ Éternel bénit Obed-Édom et toute sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Et on rapporta au roi David, en disant: L’ Éternel a béni la maison d’Obed-Édom et tout ce qui est à lui, à cause de l’arche de Dieu. Et David alla, et fit monter l’arche de Dieu de la maison d’Obed-Édom dans la ville de David, avec joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Et il arriva que, quand ceux qui portaient l’arche de l’ Éternel avaient fait six pas, il sacrifiait un taureau et une bête grasse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Et David dansait de toute sa force devant l’ Éternel; et David était ceint d’un éphod de lin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Et David et toute la maison d’Israël faisaient monter l’arche de l’ Éternel avec des cris de joie et au son des trompettes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Et comme l’arche de l’ Éternel entrait dans la ville de David, Mical, fille de Saül, regarda par la fenêtre, et elle vit le roi David sautant et dansant devant l’ Éternel, et elle le méprisa dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Et ils amenèrent l’arche de l’ Éternel, et la placèrent en son lieu, dans la tente que David avait tendue pour elle. Et David offrit des holocaustes et des sacrifices de prospérités devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Et quand David eut achevé d’offrir les holocaustes et les sacrifices de prospérités, il bénit le peuple au nom de l’ Éternel des armées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'et il distribua à tout le peuple, à toute la multitude d’Israël, tant aux femmes qu’aux hommes, à chacun un pain, et une ration [de vin], et un gâteau de raisins. Et tout le peuple s’en alla, chacun en sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Et David s’en retourna pour bénir sa maison; et Mical, fille de Saül, sortit à la rencontre de David, et dit: Combien s’est honoré aujourd’hui le roi d’Israël, qui s’est découvert aujourd’hui devant les yeux des servantes de ses serviteurs, comme se découvrirait sans honte un homme de rien!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Et David dit à Mical: Ç’a été devant l’ Éternel, qui m’a choisi plutôt que ton père et que toute sa maison pour m’établir prince sur le peuple de l’ Éternel, sur Israël; et j’ai dansé devant l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'et je me rendrai plus vil encore que cela, et je serai abaissé à mes yeux; mais auprès des servantes dont tu as parlé, auprès d’elles, je serai honoré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Et Mical, fille de Saül, n’eut point d’enfant jusqu’au jour de sa mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, '*Et quand le roi habita dans sa maison, et que, tout autour, l’ Éternel lui eut donné du repos de tous ses ennemis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'il arriva que le roi dit à Nathan, le prophète: Regarde, je te prie, moi j’habite dans une maison de cèdres, et l’arche de Dieu habite sous des tapis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Et Nathan dit au roi: Va, fais tout ce qui est dans ton cœur, car l’ Éternel est avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Et il arriva, cette nuit-là, que la parole de l’ Éternel vint à Nathan, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Va, et dis à mon serviteur, à David: Ainsi dit l’ Éternel: Me bâtirais-tu une maison pour que j’y habite?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'car je n’ai pas habité dans une maison, depuis le jour où j’ai fait monter les fils d’Israël hors d’Égypte, jusqu’à ce jour; mais j’ai marché çà et là dans une tente et dans un tabernacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Partout où j’ai marché au milieu de tous les fils d’Israël, ai-je dit un mot à quelqu’une des tribus d’Israël à laquelle j’ai commandé de paître mon peuple Israël, en disant: Pourquoi ne me bâtissez-vous pas une maison de cèdres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Et maintenant tu diras ainsi à mon serviteur, à David: Ainsi dit l’ Éternel des armées: Je t’ai pris des parcs, d’auprès du menu bétail, pour que tu sois prince sur mon peuple, sur Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'et j’ai été avec toi partout où tu as marché; et j’ai retranché tous tes ennemis de devant toi, et je t’ai fait un grand nom, comme le nom des grands qui sont sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Et j’ai établi un lieu à mon peuple, à Israël, et je le planterai, et il habitera chez lui et ne sera plus agité; et les fils d’iniquité ne l’affligeront plus comme au commencement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'et depuis le jour où j’ai établi des juges sur mon peuple Israël. Et je t’ai donné du repos de tous tes ennemis; et l’ Éternel t’annonce que l’ Éternel te fera une maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Quand tes jours seront accomplis et que tu dormiras avec tes pères, je susciterai après toi ta semence qui sortira de tes entrailles, et j’affermirai son royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Lui, bâtira une maison à mon nom; et j’affermirai le trône de son royaume pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Moi, je lui serai pour père, et lui me sera pour fils: s’il commet l’iniquité, je le châtierai avec une verge d’hommes et avec des plaies des fils des hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'mais ma bonté ne se retirera point de lui, comme je l’ai retirée d’avec Saül que j’ai ôté de devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Et ta maison et ton royaume seront rendus stables à toujours devant toi, ton trône sera affermi pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Nathan parla ainsi à David, selon toutes ces paroles et selon toute cette vision.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Et le roi David entra et s’assit devant l’ Éternel, et dit: Qui suis-je, Seigneur Éternel! et quelle est ma maison, que tu m’aies amené jusqu’ici?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Et encore cela a été peu de chose à tes yeux, Seigneur Éternel! et tu as même parlé de la maison de ton serviteur pour un long avenir. Est-ce là la manière de l’homme, Seigneur Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Et David, que pourrait-il te dire de plus? Et toi, Seigneur Éternel, tu connais ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'C’est à cause de ta parole, et selon ton cœur, que tu as fait toute cette grande chose, pour la faire connaître à ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'C’est pourquoi, Éternel Dieu! tu t’es montré grand, car il n’y en a point comme toi, et il n’y a point de Dieu si ce n’est toi, selon tout ce que nous avons entendu de nos oreilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Et qui est comme ton peuple, comme Israël, seule nation sur la terre que Dieu soit allé racheter, afin qu’elle lui soit un peuple, et pour se faire un nom à lui-même, et pour opérer en leur faveur cette grande chose, et des choses terribles pour ton pays, devant ton peuple, que tu t’es racheté d’Égypte, des nations et de leurs dieux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Et tu t’es établi ton peuple Israël pour peuple, à toujours; et toi, Éternel, tu es devenu leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Et maintenant, Éternel Dieu! confirme pour toujours la parole que tu as prononcée touchant ton serviteur et touchant sa maison, et fais comme tu as dit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'et que ton nom soit magnifié à toujours, de sorte qu’on dise: L’ Éternel des armées est Dieu sur Israël. Et que la maison de ton serviteur David soit affermie devant toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Car toi, Éternel des armées, Dieu d’Israël, tu as révélé à ton serviteur, disant: Je te bâtirai une maison; c’est pourquoi ton serviteur a trouvé son cœur pour te faire cette prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Et maintenant, Seigneur Éternel, toi, tu es Dieu, et tes paroles sont vraies, et tu as dit ce bien à ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Et maintenant, qu’il te plaise de bénir la maison de ton serviteur, afin qu’elle soit à toujours devant toi; car toi, Seigneur Éternel, tu as parlé; et que la maison de ton serviteur soit bénie de ta bénédiction pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, '*Et il arriva, après cela, que David frappa les Philistins et les subjugua; et David prit Métheg-Amma de la main des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Et il frappa Moab, et il les mesura au cordeau, les faisant coucher par terre, et il en mesura deux cordeaux pour les faire mourir, et un plein cordeau pour les laisser vivre; et les Moabites devinrent serviteurs de David: ils lui apportèrent des présents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Et David frappa Hadadézer, fils de Rehob, roi de Tsoba, comme il allait pour rétablir sa puissance sur le fleuve [Euphrate].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Et David lui prit 1 700 cavaliers et 20 000 hommes de pied; et David coupa les jarrets [aux chevaux] de tous les chars, mais il réserva 100 attelages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Et les Syriens de Damas vinrent au secours d’Hadadézer, roi de Tsoba; et David frappa 22 000 hommes des Syriens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Et David mit des garnisons dans la Syrie de Damas, et les Syriens devinrent serviteurs de David: ils lui apportèrent des présents. Et l’ Éternel sauvait David partout où il allait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Et David prit les boucliers d’or qui étaient aux serviteurs d’Hadadézer, et les apporta à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Et de Bétakh et de Bérothaï, villes d’Hadadézer, le roi David prit une grande quantité d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Et Tohi, roi de Hamath, apprit que David avait frappé toutes les forces d’Hadadézer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Et Tohi envoya Joram, son fils, au roi David, pour le saluer et le féliciter de ce qu’il avait fait la guerre à Hadadézer et l’avait battu; car Hadadézer était continuellement en guerre avec Tohi; et [Joram] avait avec lui des vases d’argent, et des vases d’or, et des vases d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Ceux-ci aussi, le roi David les consacra à l’ Éternel, avec l’argent et l’or qu’il avait consacrés de toutes les nations qu’il avait soumises:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'de Syrie, et de Moab, et des fils d’Ammon, et des Philistins, et d’Amalek, et du butin d’Hadadézer, fils de Rehob, roi de Tsoba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Et David se fit un nom, en revenant d’avoir frappé les Syriens dans la vallée du Sel, [au nombre de] 18 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Et il mit des garnisons en Édom; il mit des garnisons dans tout Édom, et tout Édom fut asservi à David. Et l’ Éternel sauvait David partout où il allait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Et David régna sur tout Israël; et David faisait droit et justice à tout son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Et Joab, fils de Tseruïa, était [préposé] sur l’armée; et Josaphat, fils d’Akhilud, était rédacteur des chroniques;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'et Tsadok, fils d’Akhitub, et Akhimélec, fils d’Abiathar, étaient sacrificateurs; et Seraïa était scribe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'et Benaïa, fils de Jehoïada, [était chef] des Keréthiens et des Peléthiens; et les fils de David étaient les principaux officiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, '*Et David dit: Y a-t-il encore quelqu’un qui soit demeuré de reste de la maison de Saül? et j’userai de bonté envers lui à cause de Jonathan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Et il y avait un serviteur de la maison de Saül, dont le nom était Tsiba; et on l’appela auprès de David. Et le roi lui dit: Es-tu Tsiba? Et il dit: Ton serviteur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Et le roi dit: N’y a-t-il plus personne de la maison de Saül? et j’userai envers lui d’une bonté de Dieu. Et Tsiba dit au roi: Il y a encore un fils de Jonathan, perclus des pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Et le roi lui dit: Où est-il? Et Tsiba dit au roi: Voici, il est dans la maison de Makir, fils d’Ammiel, à Lodebar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Et le roi David envoya, et le prit de la maison de Makir, fils d’Ammiel, à Lodebar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Et Mephibosheth, fils de Jonathan, fils de Saül, vint vers David, et il tomba sur sa face et se prosterna. Et David dit: Mephibosheth! Et il dit: Voici ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Et David lui dit: Ne crains point, car certainement j’userai de bonté envers toi à cause de Jonathan, ton père, et je te rendrai tous les champs de Saül, ton père, et tu mangeras continuellement le pain à ma table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Et il se prosterna, et dit: Qu’est ton serviteur, que tu aies regardé un chien mort tel que moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Et le roi appela Tsiba, le serviteur de Saül, et lui dit: Tout ce qui appartenait à Saül et à toute sa maison, je le donne au fils de ton seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'et tu cultiveras pour lui la terre, toi et tes fils et tes serviteurs, et tu en apporteras [les fruits], et le fils de ton seigneur aura du pain à manger; et Mephibosheth, fils de ton seigneur, mangera continuellement le pain à ma table. Or Tsiba avait 15 fils et 20 serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Et Tsiba dit au roi: Ton serviteur fera selon tout ce que le roi, mon seigneur, a commandé à son serviteur. Et Mephibosheth, [dit le roi,] mangera à ma table comme un des fils du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Et Mephibosheth avait un jeune fils, et son nom était Mica; et tous ceux qui habitaient dans la maison de Tsiba étaient serviteurs de Mephibosheth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Et Mephibosheth habitait à Jérusalem, car il mangeait toujours à la table du roi; et il était boiteux des deux pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, '*Et il arriva, après cela, que le roi des fils d’Ammon mourut; et Hanun, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Et David dit: J’userai de bonté envers Hanun, fils de Nakhash, comme son père a usé de bonté envers moi. Et David l’envoya consoler par ses serviteurs au sujet de son père. Et les serviteurs de David arrivèrent dans le pays des fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Et les chefs des fils d’Ammon dirent à Hanun, leur seigneur: Est-ce, à tes yeux, pour honorer ton père que David t’a envoyé des consolateurs? N’est-ce pas pour reconnaître la ville, et pour l’explorer, et pour la détruire, que David t’a envoyé ses serviteurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Et Hanun prit les serviteurs de David, et fit raser la moitié de leur barbe, et fit couper leurs vêtements par le milieu jusqu’au bas des reins, et les renvoya.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Et on le rapporta à David; et il envoya à leur rencontre, car les hommes étaient très confus. Et le roi dit: Habitez à Jéricho jusqu’à ce que votre barbe ait poussé, alors vous reviendrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Et les fils d’Ammon virent qu’ils s’étaient mis en mauvaise odeur auprès de David; et les fils d’Ammon envoyèrent, et prirent à leur solde des Syriens de Beth-Rehob et des Syriens de Tsoba, 20 000 hommes de pied, et le roi de Maaca [avec] 1 000 hommes, et ceux de Tob, 12 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Et David l’apprit, et il envoya Joab et toute l’armée, les hommes forts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Et les fils d’Ammon sortirent et se rangèrent en bataille à l’entrée de la porte; et les Syriens de Tsoba et de Rehob, et ceux de Tob et de Maaca, étaient à part dans la campagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Et Joab vit que le front de la bataille était contre lui, devant et derrière; et il choisit des hommes de toute l’élite d’Israël, et les rangea contre les Syriens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'et il plaça le reste du peuple sous la main d’Abishaï, son frère, et le rangea contre les fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Et il dit: Si les Syriens sont plus forts que moi, tu me seras en aide; et si les fils d’Ammon sont plus forts que toi, j’irai pour t’aider.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Sois fort, et fortifions-nous à cause de notre peuple et à cause des villes de notre Dieu; et que l’ Éternel fasse ce qui est bon à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Et Joab s’approcha, et le peuple qui était avec lui, pour livrer bataille aux Syriens; et ils s’enfuirent devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Et quand les fils d’Ammon virent que les Syriens s’étaient enfuis, ils s’enfuirent devant Abishaï, et rentrèrent dans la ville. Et Joab s’en retourna d’auprès des fils d’Ammon, et vint à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Et quand les Syriens virent qu’ils étaient battus devant Israël, ils se rassemblèrent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'et Hadarézer envoya, et fit sortir les Syriens qui étaient au-delà du fleuve, et ils vinrent à Hélam; et Shobac, chef de l’armée d’Hadarézer, était à leur tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Et cela fut rapporté à David, et il assembla tout Israël, et passa le Jourdain, et vint à Hélam; et les Syriens se rangèrent [en bataille] contre David, et se battirent avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Et les Syriens s’enfuirent devant Israël; et David tua aux Syriens 700 chars et 40 000 cavaliers, et il frappa Shobac, chef de leur armée, et il mourut là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Et tous les rois qui étaient serviteurs d’Hadarézer virent qu’ils étaient battus devant Israël, et ils firent la paix avec Israël, et le servirent. Et les Syriens craignirent d’aider encore les fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, '*Et il arriva, au retour de l’année, au temps où les rois entrent en campagne, que David envoya Joab, et ses serviteurs avec lui, et tout Israël; et ils détruisirent les fils d’Ammon et assiégèrent Rabba; mais David resta à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Et il arriva, au temps du soir, que David se leva de dessus son lit de repos et se promena sur le toit de la maison du roi, et, du toit, il vit une femme qui se lavait, et la femme était très belle à voir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Et David envoya et s’informa de cette femme, et on [lui] dit: N’est-ce pas là Bath-Shéba, fille d’Éliam, femme d’Urie, le Héthien?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Et David envoya des messagers, et la prit; et elle vint vers lui, et il coucha avec elle (et elle se purifia de son impureté); et elle s’en retourna dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Et la femme conçut; et elle envoya, et informa David et dit: Je suis enceinte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Et David envoya vers Joab, [disant]: Envoie-moi Urie, le Héthien. Et Joab envoya Urie à David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Et Urie vint vers lui; et David s’enquit de l’état de Joab, et de l’état du peuple, et de l’état de la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Et David dit à Urie: Descends dans ta maison, et lave tes pieds. Et Urie sortit de la maison du roi, et on envoya après lui un présent de la part du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Et Urie se coucha à l’entrée de la maison du roi avec tous les serviteurs de son seigneur, et ne descendit pas dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Et on le rapporta à David, disant: Urie n’est pas descendu dans sa maison. Et David dit à Urie: Ne viens-tu pas de voyage? Pourquoi n’es-tu pas descendu dans ta maison?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Et Urie dit à David: L’arche, et Israël, et Juda, habitent sous des tentes; et mon seigneur Joab et les serviteurs de mon seigneur campent dans les champs, et moi, j’entrerais dans ma maison pour manger et boire, et pour coucher avec ma femme? Tu es vivant, et ton âme est vivante, si je fais une telle chose!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Et David dit à Urie: Demeure ici encore aujourd’hui, et demain je te renverrai. Et Urie demeura à Jérusalem ce jour-là et le lendemain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Et David l’appela, et il mangea et but devant lui, et [David] l’enivra; et il sortit le soir pour se coucher sur son lit avec les serviteurs de son seigneur, et il ne descendit pas dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Et il arriva, le matin, que David écrivit une lettre à Joab, et l’envoya par la main d’Urie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Et il écrivit dans la lettre, disant: Placez Urie sur la première ligne au fort de la bataille, et retirez-vous d’auprès de lui, afin qu’il soit frappé et qu’il meure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Et il arriva que, comme Joab surveillait la ville, il plaça Urie à l’endroit où il savait qu’étaient de vaillants hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Et les hommes de la ville sortirent et se battirent contre Joab; et il en tomba quelques-uns d’entre le peuple, d’entre les serviteurs de David, et Urie, le Héthien, mourut aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Et Joab envoya, et rapporta à David tous les faits du combat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Et il commanda au messager, disant: Quand tu auras achevé de dire au roi tous les faits du combat,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 's’il arrive que la fureur du roi monte, et qu’il te dise: Pourquoi vous êtes-vous approchés de la ville pour combattre? Ne savez-vous pas qu’on tire de dessus la muraille?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Qui frappa Abimélec, fils de Jerubbésheth? N’est-ce pas une femme qui jeta sur lui, de dessus la muraille, une meule tournante, et il en mourut à Thébets? Pourquoi vous êtes-vous approchés de la muraille? – alors tu diras: Ton serviteur Urie, le Héthien, est mort aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Et le messager s’en alla; et étant arrivé, il rapporta à David tout ce pour quoi Joab l’avait envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Et le messager dit à David: Les hommes ont eu l’avantage sur nous; ils sont sortis contre nous dans la campagne, et nous les avons chargés jusqu’à l’entrée de la porte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'et les archers ont tiré sur tes serviteurs de dessus la muraille, et des serviteurs du roi sont morts, et ton serviteur Urie, le Héthien, est mort aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Et David dit au messager: Tu diras ainsi à Joab: Que cela ne soit pas mauvais à tes yeux, car l’épée dévore tantôt ici, tantôt là; renforce le combat contre la ville, et détruis-la. Et toi, encourage-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Et la femme d’Urie apprit qu’Urie, son mari, était mort, et elle se lamenta sur son mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Et quand le deuil fut passé, David envoya, et la recueillit dans sa maison, et elle devint sa femme, et lui enfanta un fils. Mais la chose que David avait faite fut mauvaise aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Et l’ Éternel envoya Nathan à David; et il vint vers lui, et lui dit: Il y avait deux hommes dans une ville, l’un riche, et l’autre pauvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Le riche avait du menu et du gros bétail en grande quantité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'mais le pauvre n’avait rien du tout qu’ une seule petite brebis, qu’il avait achetée, et qu’il nourrissait, et qui grandissait auprès de lui et ensemble avec ses fils: elle mangeait de ses morceaux et buvait de sa coupe, et elle couchait dans son sein, et était pour lui comme une fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Et un voyageur vint chez l’homme riche; et il évita de prendre de son menu ou de son gros bétail pour en apprêter au voyageur qui était venu chez lui, et il a pris la brebis de l’homme pauvre, et l’a apprêtée pour l’homme qui était venu vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Et la colère de David s’embrasa fort contre l’homme; et il dit à Nathan: L’ Éternel est vivant que l’homme qui a fait cela est digne de mort!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'et il rendra la brebis au quadruple, parce qu’il a fait cette chose-là et qu’il n’a pas eu de pitié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Et Nathan dit à David: Tu es cet homme! Ainsi dit l’ Éternel, le Dieu d’Israël: Je t’ai oint pour roi sur Israël, et je t’ai délivré de la main de Saül,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'et je t’ai donné la maison de ton seigneur, et les femmes de ton seigneur dans ton sein, et je t’ai donné la maison d’Israël et de Juda; et si c’était peu, je t’aurais ajouté telle et telle chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Pourquoi as-tu méprisé la parole de l’ Éternel, en faisant ce qui est mauvais à ses yeux? Tu as frappé avec l’épée Urie, le Héthien; et sa femme, tu l’as prise pour en faire ta femme, et lui, tu l’as tué par l’épée des fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Et maintenant, l’épée ne s’éloignera pas de ta maison, à jamais, parce que tu m’as méprisé, et que tu as pris la femme d’Urie, le Héthien, pour qu’elle soit ta femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Ainsi dit l’ Éternel: Voici, je susciterai de ta propre maison un mal contre toi: je prendrai tes femmes devant tes yeux, et je les donnerai à ton compagnon, et il couchera avec tes femmes à la vue de ce soleil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'car tu l’as fait en secret, et moi, je ferai cette chose-là devant tout Israël et devant le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Et David dit à Nathan: J’ai péché contre l’ Éternel. Et Nathan dit à David: Aussi l’ Éternel a fait passer ton péché: tu ne mourras pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'toutefois, comme par cette chose tu as donné occasion aux ennemis de l’ Éternel de blasphémer, le fils qui t’est né mourra certainement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Et Nathan s’en alla dans sa maison. Et l’ Éternel frappa l’enfant que la femme d’Urie avait enfanté à David; et il fut très malade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Et David supplia Dieu pour l’enfant, et David jeûna; et il alla et passa la nuit couché sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Et les anciens de sa maison se levèrent [et vinrent] vers lui pour le faire lever de terre; mais il ne voulut pas, et ne mangea pas le pain avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Et il arriva, le septième jour, que l’enfant mourut; et les serviteurs de David craignirent de lui apprendre que l’enfant était mort, car ils disaient: Voici, lorsque l’enfant était en vie, nous lui avons parlé, et il n’a pas écouté notre voix; et comment lui dirions-nous: L’enfant est mort? Il fera quelque mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Et David vit que ses serviteurs parlaient bas, et David comprit que l’enfant était mort; et David dit à ses serviteurs: L’enfant est-il mort? Et ils dirent: Il est mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Et David se leva de terre, et se lava et s’oignit, et changea de vêtements; et il entra dans la maison de l’ Éternel et se prosterna; et il rentra dans sa maison, et demanda qu’on mette du pain devant lui, et il mangea.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Et ses serviteurs lui dirent: Qu’est-ce que tu fais? Tu as jeûné et tu as pleuré à cause de l’enfant, pendant qu’il était en vie; et quand l’enfant est mort, tu te lèves et tu manges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Et il dit: Tant que l’enfant vivait encore, j’ai jeûné et j’ai pleuré, car je disais: Qui sait: l’ Éternel me fera grâce, et l’enfant vivra?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Mais maintenant qu’il est mort, pourquoi jeûnerais-je? Pourrais-je le faire revenir encore? Moi, je vais vers lui, mais lui ne reviendra pas vers moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Et David consola Bath-Shéba, sa femme, et vint vers elle et coucha avec elle; et elle enfanta un fils, et il appela son nom Salomon; et l’ Éternel l’aima;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'et il envoya par Nathan le prophète, et l’appela du nom de Jedidia, à cause de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Et Joab fit la guerre contre Rabba des fils d’Ammon, et il prit la ville royale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Et Joab envoya des messagers à David, et dit: J’ai fait la guerre contre Rabba, et j’ai aussi pris la ville des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Et maintenant, assemble le reste du peuple, et campe contre la ville et prends-la, de peur que moi je ne prenne la ville, et qu’elle ne soit appelée de mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Et David assembla tout le peuple, et marcha sur Rabba; et il combattit contre elle, et la prit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Et il prit la couronne de leur roi de dessus sa tête (et son poids était d’un talent d’or, et elle [avait] des pierres précieuses); et elle fut [mise] sur la tête de David; et il emmena de la ville une grande quantité de butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Et il fit sortir le peuple qui s’y trouvait, et les mit sous la scie, et sous des herses de fer, et sous des haches de fer, et les fit passer par un four à briques: il fit ainsi à toutes les villes des fils d’Ammon. Et David et tout le peuple s’en retournèrent à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, '*Et après cela, Absalom, fils de David, ayant une sœur nommée Tamar, qui était belle, il arriva qu’Amnon, fils de David, l’aima.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Et Amnon fut tourmenté jusqu’à en tomber malade, à cause de Tamar, sa sœur; car elle était vierge, et il était trop difficile aux yeux d’Amnon de lui faire quoi que ce soit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Et Amnon avait un ami, nommé Jonadab, fils de Shimha, frère de David; et Jonadab était un homme très habile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Et il lui dit: Pourquoi maigris-tu ainsi d’un matin à l’autre, toi, fils du roi? Ne me le déclareras-tu pas? Et Amnon lui dit: J’aime Tamar, sœur d’Absalom mon frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Et Jonadab lui dit: Couche-toi sur ton lit et fais le malade; et ton père viendra te voir, et tu lui diras: Je te prie, que Tamar, ma sœur, vienne et qu’elle me donne à manger du pain, et qu’elle apprête devant mes yeux un mets, afin que je la voie, et que je le mange de sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Et Amnon se coucha et fit le malade; et le roi vint le voir, et Amnon dit au roi: Je te prie, que Tamar, ma sœur, vienne et prépare sous mes yeux deux beignets, et que je les mange de sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Et David envoya vers Tamar dans la maison, disant: Va, je te prie, dans la maison d’Amnon, ton frère, et apprête-lui un mets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Et Tamar alla dans la maison d’Amnon, son frère, et il était couché; et elle prit de la pâte et la pétrit, et prépara sous ses yeux des beignets, et elle cuisit les beignets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Et elle prit la poêle et les versa devant lui; et il refusa de manger. Et Amnon dit: Faites sortir tout homme d’auprès de moi. Et tout homme sortit d’auprès de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Et Amnon dit à Tamar: Apporte le mets dans la chambre intérieure, et je mangerai de ta main. Et Tamar prit les beignets qu’elle avait préparés, et les apporta à Amnon, son frère, dans la chambre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Et elle les lui présenta à manger; et il la saisit, et lui dit: Viens, couche avec moi, ma sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Et elle lui dit: Non, mon frère, ne m’humilie pas; car on ne fait point ainsi en Israël: ne fais pas cette infamie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Et moi, où porterais-je ma honte? Et toi, tu serais comme l’un des infâmes en Israël. Et maintenant, parle au roi, je te prie, car il ne me refusera point à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Et il ne voulut pas écouter sa voix, et il fut plus fort qu’elle et l’humilia et coucha avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Et Amnon la haït d’une très grande haine, car la haine dont il la haït était plus grande que l’amour dont il l’avait aimée. Et Amnon lui dit: Lève-toi, va-t’en.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Et elle lui dit: Il n’y a pas de raison [pour cela]; ce tort de me chasser est plus grand que l’autre que tu m’as fait. Mais il ne voulut pas l’écouter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Et il appela son jeune homme qui le servait, et dit: Chassez donc cette [femme] dehors, de devant moi; et ferme la porte au verrou après elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Et elle avait sur elle une tunique bigarrée; car les filles du roi qui étaient vierges étaient ainsi habillées de robes. Et celui qui le servait la mit dehors, et ferma la porte après elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Et Tamar prit de la poussière [et la mit] sur sa tête, et déchira la tunique bigarrée qu’elle avait sur elle, et elle mit sa main sur sa tête, et s’en alla, marchant et criant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Et Absalom, son frère, lui dit: Est-ce que ton frère Amnon a été avec toi? Et maintenant, ma sœur, garde le silence: il est ton frère; ne prends pas cette chose à cœur. Et Tamar demeura désolée dans la maison d’Absalom, son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Et le roi David entendit parler de toutes ces choses, et il en fut très irrité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Et Absalom ne parla à Amnon, ni en mal, ni en bien, car Absalom haïssait Amnon, parce qu’il avait humilié Tamar, sa sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Et il arriva, après deux années entières, qu’Absalom avait les tondeurs à Baal-Hatsor, qui est près d’Éphraïm; et Absalom invita tous les fils du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Et Absalom vint vers le roi, et dit: Tu vois que ton serviteur a les tondeurs: je te prie, que le roi et ses serviteurs aillent avec ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Et le roi dit à Absalom: Non, mon fils, nous n’irons pas tous, et nous ne te serons pas à charge. Et il le pressa, mais il ne voulut pas aller; et il le bénit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Et Absalom dit: Si [tu ne viens] pas, que mon frère Amnon, je te prie, vienne avec nous. Et le roi lui dit: Pourquoi irait-il avec toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Et Absalom le pressa, et il envoya avec lui Amnon et tous les fils du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Et Absalom commanda à ses serviteurs, disant: Faites attention, je vous prie, quand le cœur d’Amnon sera gai par le vin, et que je vous dirai: Frappez Amnon, alors tuez-le, ne craignez point; n’est-ce pas moi qui vous l’ai commandé? Fortifiez-vous, et soyez vaillants!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Et les serviteurs d’Absalom firent à Amnon comme Absalom l’avait commandé; et tous les fils du roi se levèrent, et montèrent chacun sur son mulet et s’enfuirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Et il arriva, comme ils étaient en chemin, que le bruit en vint à David; on disait: Absalom a frappé tous les fils du roi, et il n’en reste pas un seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Et le roi se leva, et déchira ses vêtements, et se coucha par terre; et tous ses serviteurs étaient là, les vêtements déchirés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Et Jonadab, fils de Shimha, frère de David, prit la parole et dit: Que mon seigneur ne pense pas qu’on ait tué tous les jeunes hommes, fils du roi, car Amnon seul est mort; car cela a eu lieu par l’ordre d’Absalom, qu’il avait arrêté dès le jour où [Amnon] humilia Tamar, sa sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Et maintenant, que le roi, mon seigneur, ne prenne pas ceci à cœur, disant: Tous les fils du roi sont morts; car Amnon seul est mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Et Absalom s’enfuit. Et le jeune homme qui était en sentinelle leva ses yeux et regarda; et voici, un grand peuple venait par le chemin qui était derrière lui, du côté de la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Et Jonadab dit au roi: Voici les fils du roi qui viennent; selon la parole de ton serviteur, ainsi il en est arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Et comme il achevait de parler, voici, les fils du roi arrivèrent, et ils élevèrent leur voix et pleurèrent; et le roi aussi, et tous ses serviteurs pleurèrent très amèrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Et Absalom s’enfuit, et s’en alla vers Talmaï, fils d’Ammihud, roi de Gueshur; et [David] menait deuil tous les jours sur son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Ainsi Absalom s’enfuit, et il vint à Gueshur et fut là trois ans;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'et le roi David languissait d’aller vers Absalom, car il était consolé à l’égard d’Amnon, parce qu’il était mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Et Joab, fils de Tseruïa, s’aperçut que le cœur du roi était pour Absalom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'et Joab envoya à Thekoa, et fit venir de là une femme habile, et il lui dit: Je te prie, fais semblant de mener deuil, et revêts-toi, je te prie, de vêtements de deuil, et ne t’oins pas d’huile, mais sois comme une femme qui mène deuil depuis longtemps pour un mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'et entre vers le roi, et parle-lui de cette manière. Et Joab lui mit les paroles dans la bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Et la femme thekohite parla au roi, et tomba sur son visage contre terre et se prosterna, et dit: Sauve-moi, ô roi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Et le roi lui dit: Qu’as-tu? Et elle dit: Certainement, je suis une femme veuve, et mon mari est mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Et ta servante avait deux fils, et ils se sont disputés tous deux dans les champs, et il n’y avait personne pour les séparer; et l’un a frappé l’autre et l’a tué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Et voici, toute la famille s’est élevée contre ta servante, et ils ont dit: Livre celui qui a frappé son frère, afin que nous le mettions à mort, à cause de la vie de son frère qu’il a tué, et que nous détruisions aussi l’héritier. Et ainsi ils éteindraient le tison qui me reste, afin de ne laisser à mon mari ni nom, ni reste, sur la face de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Et le roi dit à la femme: Va dans ta maison, et je donnerai mes ordres à ton égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Et la femme thekohite dit au roi: Ô roi, mon seigneur! que l’iniquité soit sur moi et sur la maison de mon père, et que le roi et son trône en soient innocents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Et le roi dit: Celui qui te parlera, amène-le-moi, et il ne te touchera plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Et elle dit: Je te prie, que le roi se souvienne de l’ Éternel, ton Dieu, afin que le vengeur du sang ne multiplie pas la ruine, et qu’on ne détruise pas mon fils. Et il dit: L’ Éternel est vivant, s’il tombe à terre un des cheveux de ton fils!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Et la femme dit: Je te prie, que ta servante dise un mot au roi, mon seigneur. Et il dit: Parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Et la femme dit: Et pourquoi as-tu pensé ainsi contre le peuple de Dieu? et le roi dit cette parole comme un [homme] coupable, le roi ne faisant point revenir celui qu’il a chassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Car nous mourrons certainement, et nous sommes comme de l’eau versée sur la terre, qu’on ne peut recueillir. Et Dieu ne [lui] a point ôté la vie, mais il a la pensée que celui qui est chassé ne demeure plus chassé loin de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Et maintenant, si je suis venue dire cette parole au roi, mon seigneur, c’est parce que le peuple m’a fait peur; et ta servante a dit: Que je parle donc au roi, peut-être que le roi accomplira la parole de sa servante;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'car le roi écoutera, pour délivrer sa servante de la main de l’homme qui veut nous exterminer, moi et mon fils ensemble, de l’héritage de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Et ta servante a dit: Que la parole du roi, mon seigneur, nous apporte du repos! car le roi, mon seigneur, est comme un ange de Dieu, pour entendre le bien et le mal; et l’ Éternel, ton Dieu, sera avec toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Et le roi répondit, et dit à la femme: Je te prie, ne me cache pas la chose que je vais te demander. Et la femme dit: Que le roi, mon seigneur, parle, je te prie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Et le roi dit: La main de Joab n’est-elle pas avec toi dans tout ceci? Et la femme répondit et dit: Ton âme est vivante, ô roi, mon seigneur, qu’on ne peut [s’écarter] à droite ou à gauche de tout ce que dit le roi, mon seigneur; car ton serviteur Joab, lui, m’a commandé, et a mis toutes ces paroles dans la bouche de ta servante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'C’est afin de donner une autre apparence à la chose, que ton serviteur Joab a fait cela; et mon seigneur est sage comme la sagesse d’un ange de Dieu, pour savoir tout ce qui [se passe] sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Et le roi dit à Joab: Voici, j’ai fait cela; va, fais revenir le jeune homme Absalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Et Joab tomba sur sa face contre terre et se prosterna, et bénit le roi. Et Joab dit: Aujourd’hui ton serviteur connaît que j’ai trouvé faveur à tes yeux, ô roi, mon seigneur, parce que le roi a fait ce que son serviteur a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Et Joab se leva et s’en alla à Gueshur, et il ramena Absalom à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Et le roi dit: Qu’il se retire dans sa maison, et qu’il ne voie point ma face. Et Absalom se retira dans sa maison et ne vit pas la face du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Et dans tout Israël il n’y avait pas d’homme beau comme Absalom [et si] fort à louer [pour sa beauté]; depuis la plante de ses pieds jusqu’au sommet de sa tête, il n’y avait point en lui de défaut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Et quand il se rasait la tête (or c’était d’année en année qu’il la rasait, parce que [sa chevelure] lui pesait; alors il la rasait), les cheveux de sa tête pesaient 200 sicles au poids du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Et il naquit à Absalom trois fils, et une fille, qui avait nom Tamar, et elle était une femme belle de visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Et Absalom habita deux années entières à Jérusalem sans voir la face du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Et Absalom envoya vers Joab pour l’envoyer auprès du roi; et [Joab] ne voulut pas venir vers lui; et il envoya encore pour la seconde fois, et il ne voulut pas venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Alors [Absalom] dit à ses serviteurs: Voyez, le champ de Joab est auprès du mien; il y a de l’orge, allez et mettez-y le feu. Et les serviteurs d’Absalom mirent le feu au champ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Alors Joab se leva et vint vers Absalom dans la maison, et lui dit: Pourquoi tes serviteurs ont-ils mis le feu à mon champ?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Et Absalom dit à Joab: Voici, j’ai envoyé vers toi, disant: Viens ici, et je t’enverrai vers le roi, pour [lui] dire: Pourquoi suis-je venu de Gueshur? il serait bon pour moi d’y être encore. Et maintenant, que je voie la face du roi; et s’il y a de l’iniquité en moi, qu’il me fasse mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Et Joab vint vers le roi et le lui rapporta. Et [le roi] appela Absalom, et il vint vers le roi et se prosterna le visage contre terre devant le roi, et le roi embrassa Absalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, '*Et il arriva, après cela, qu’Absalom se procura des chars et des chevaux, et 50 hommes qui couraient devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Et Absalom se levait de bonne heure, et se tenait à côté du chemin de la porte; et tout homme qui avait une cause qui l’oblige d’aller vers le roi pour un jugement, Absalom l’appelait, et disait: De quelle ville es-tu? Et il disait: Ton serviteur est de l’une des tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Et Absalom lui disait: Vois, tes affaires sont bonnes et justes, mais tu n’as personne pour les entendre de la part du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Et Absalom disait: Que ne m’établit-on juge dans le pays! alors tout homme qui aurait une cause ou un procès viendrait vers moi, et je lui ferais justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Et s’il arrivait qu’un homme s’approche pour se prosterner devant lui, il lui tendait la main, et le prenait, et l’embrassait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Et Absalom agissait de cette manière envers tous ceux d’Israël qui venaient vers le roi pour un jugement; et Absalom dérobait les cœurs des hommes d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Et il arriva au bout de 40 ans, qu’Absalom dit au roi: Je te prie, que je m’en aille et que j’acquitte à Hébron mon vœu que j’ai voué à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Car ton serviteur voua un vœu, quand je demeurais à Gueshur, en Syrie, disant: Si l’ Éternel me fait retourner à Jérusalem, je servirai l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Et le roi lui dit: Va en paix. Et il se leva, et s’en alla à Hébron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Et Absalom envoya des émissaires dans toutes les tribus d’Israël, disant: Quand vous entendrez le son de la trompette, dites: Absalom règne à Hébron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Et 200 hommes qui avaient été invités, s’en allèrent de Jérusalem avec Absalom, et ils allaient dans leur simplicité, et ne savaient rien de l’affaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Et Absalom envoya [appeler] Akhitophel, le Guilonite, le conseiller de David, de sa ville de Guilo, pendant qu’il offrait les sacrifices; et la conjuration devint puissante, et le peuple allait croissant auprès d’Absalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Et il vint à David quelqu’un qui lui rapporta, disant: Les cœurs des hommes d’Israël suivent Absalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Et David dit à tous ses serviteurs qui étaient avec lui à Jérusalem: Levez-vous, et fuyons, car nous ne saurions échapper devant Absalom. Hâtez-vous de vous en aller, de peur qu’il ne se hâte, et ne nous atteigne, et ne fasse tomber le malheur sur nous, et ne frappe la ville par le tranchant de l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Et les serviteurs du roi dirent au roi: Selon tout ce que choisira le roi, notre seigneur, voici tes serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Et le roi sortit, et toute sa maison à sa suite; et le roi laissa dix femmes concubines pour garder la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Et le roi sortit, et tout le peuple à sa suite; et ils s’arrêtèrent à Beth-Merkhak.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Et tous ses serviteurs marchaient à ses côtés; et tous les Keréthiens, et tous les Peléthiens, et tous les Guitthiens, 600 hommes qui étaient venus de Gath à sa suite, marchaient devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Et le roi dit à Itthaï, le Guitthien: Pourquoi viendrais-tu, toi aussi, avec nous? Retourne-t’en, et demeure avec le roi; car tu es étranger, et de plus tu as émigré dans le lieu que tu habites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Tu es venu hier, et aujourd’hui je te ferais errer avec nous çà et là? Et quant à moi, je vais où je puis aller. Retourne-t’en, et emmène tes frères. Que la bonté et la vérité soient avec toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Mais Itthaï répondit au roi, et dit: L’ Éternel est vivant, et le roi, mon seigneur, est vivant, que dans le lieu où sera le roi, mon seigneur, soit pour la mort, soit pour la vie, là aussi sera ton serviteur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Et David dit à Itthaï: Va, et passe! Alors Itthaï, le Guitthien, passa avec tous ses hommes et tous les enfants qui étaient avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Et tout le pays pleurait à haute voix, et tout le peuple passait; et le roi passa le torrent du Cédron, et tout le peuple passa en face du chemin du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Et voici Tsadok aussi, et tous les Lévites avec lui, portant l’arche de l’alliance de Dieu, et ils posèrent l’arche de Dieu, et Abiathar monta, jusqu’à ce que tout le peuple ait achevé de passer hors de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Et le roi dit à Tsadok: Reporte l’arche de Dieu dans la ville; si je trouve grâce aux yeux de l’ Éternel, alors il me ramènera, et me la fera voir, elle et sa demeure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Et s’il dit ainsi: Je ne prends point de plaisir en toi; – me voici, qu’il fasse de moi ce qui sera bon à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Et le roi dit à Tsadok, le sacrificateur: N’es-tu pas le voyant? Retourne-t’en en paix à la ville, et Akhimaats, ton fils, et Jonathan, fils d’Abiathar, vos deux fils, avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Voyez, j’attendrai dans les plaines du désert, jusqu’à ce que vienne de votre part une parole pour m’apporter des nouvelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Et Tsadok et Abiathar reportèrent l’arche de Dieu à Jérusalem, et y demeurèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Et David monta par la montée des Oliviers, montant et pleurant; et il avait la tête couverte et marchait nu-pieds, et tout le peuple qui était avec lui montait, chacun ayant sa tête couverte, et en montant ils pleuraient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Et on rapporta à David, en disant: Akhitophel est parmi les conjurés avec Absalom. Et David dit: Éternel! je te prie, rends vain le conseil d’Akhitophel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Et David, étant parvenu au sommet où il se prosterna devant Dieu, il arriva que voici, Hushaï, l’Arkite, vint au-devant de lui, sa tunique déchirée et de la terre sur sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Et David lui dit: Si tu passes avec moi, tu me seras à charge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Mais si tu retournes à la ville, et que tu dises à Absalom: Ô roi! je serai ton serviteur; comme j’ai été autrefois serviteur de ton père, maintenant aussi je serai ton serviteur, – alors tu annuleras pour moi le conseil d’Akhitophel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Et les sacrificateurs Tsadok et Abiathar ne sont-ils pas là avec toi? Et il arrivera que tout ce que tu entendras de la maison du roi, tu le rapporteras à Tsadok et à Abiathar, les sacrificateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Voici, leurs deux fils, Akhimaats, [fils] de Tsadok, et Jonathan, [fils] d’Abiathar, sont là avec eux; et vous me ferez savoir par eux tout ce que vous aurez entendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Et Hushaï, l’ami de David, vint dans la ville; et Absalom entra à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Et David avait passé un peu au-delà du sommet, lorsque voici, Tsiba, serviteur de Mephibosheth, vint à sa rencontre avec deux ânes bâtés, sur lesquels il y avait 200 pains, et 100 gâteaux de raisins secs, et 100 de fruits d’été, et une outre de vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Et le roi dit à Tsiba: Que veux-tu faire de cela? Et Tsiba dit: Les ânes sont pour la maison du roi, pour les monter; et le pain et les fruits d’été, pour que les jeunes hommes les mangent; et le vin, pour que celui qui est fatigué dans le désert en boive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Et le roi dit: Et où est le fils de ton seigneur? Et Tsiba dit au roi: Voici, il est demeuré à Jérusalem; car il a dit: Aujourd’hui la maison d’Israël me rendra le royaume de mon père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Et le roi dit à Tsiba: Voici, tout ce qui est à Mephibosheth est à toi. Et Tsiba dit: Je me prosterne; que je trouve faveur à tes yeux, ô roi, mon seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Et le roi David vint jusqu’à Bakhurim; et voici, il en sortit un homme de la famille de la maison de Saül, et son nom était Shimhi, fils de Guéra: il sortit en maudissant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'et lança des pierres contre David et contre tous les serviteurs du roi David; et tout le peuple et tous les hommes forts étaient à sa droite et à sa gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Et Shimhi disait ainsi en maudissant: Sors, sors, homme de sang, et homme de Bélial!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'L’ Éternel a fait retomber sur toi tout le sang de la maison de Saül, à la place duquel tu as régné, et l’ Éternel a mis le royaume dans la main d’Absalom, ton fils; et te voilà [pris] dans ton propre mal, car tu es un homme de sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Et Abishaï, fils de Tseruïa, dit au roi: Pourquoi ce chien mort maudit-il le roi, mon seigneur? Laisse-moi passer et lui ôter la tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Et le roi dit: Qu’y a-t-il entre moi et vous, fils de Tseruïa? Oui, qu’il maudisse; car l’ Éternel lui a dit: Maudis David! Et qui dira: Pourquoi fais-tu ainsi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Et David dit à Abishaï et à tous ses serviteurs: Voici, mon fils qui est sorti de mes entrailles, cherche ma vie; combien plus maintenant ce Benjaminite! Laissez-le, et qu’il maudisse! car l’ Éternel le lui a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Peut-être l’ Éternel regardera mon affliction, et l’ Éternel me rendra le bien pour la malédiction qui tombe aujourd’hui sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Et David et ses hommes allèrent leur chemin; et Shimhi marchait sur le flanc de la montagne, vis-à-vis de lui, et en marchant il maudissait et lançait des pierres contre lui, et jetait de la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Et le roi, et tout le peuple qui était avec lui, arrivèrent fatigués, et là ils se refirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Et Absalom, et tout le peuple, les hommes d’Israël, vinrent à Jérusalem, et Akhitophel avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Et il arriva que, lorsque Hushaï, l’Arkite, l’ami de David, vint vers Absalom, Hushaï dit à Absalom: Vive le roi! vive le roi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Et Absalom dit à Hushaï: Est-ce là ta bonté pour ton ami? Pourquoi n’es-tu pas allé avec ton ami?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Et Hushaï dit à Absalom: Non, car je serai à celui qu’ont choisi l’ Éternel et ce peuple, et tous les hommes d’Israël, et c’est avec lui que je demeurerai;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'et de plus, qui servirai-je? Ne sera-ce pas devant son fils? Comme j’ai servi devant ton père, ainsi je serai devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Et Absalom dit à Akhitophel: Donnez un conseil sur ce que nous ferons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Et Akhitophel dit à Absalom: Va vers les concubines de ton père, qu’il a laissées pour garder la maison; et tout Israël entendra dire que tu es en mauvaise odeur auprès de ton père, et les mains de tous ceux qui sont avec toi seront fortifiées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Et on tendit une tente pour Absalom sur le toit; et Absalom entra vers les concubines de son père, aux yeux de tout Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Et le conseil que donnait Akhitophel, en ces jours-là, était comme si on s’était enquis de la parole de Dieu. Ainsi était tout le conseil d’Akhitophel, tant auprès de David qu’auprès d’Absalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Et Akhitophel dit à Absalom: Laisse-moi choisir 12 000 hommes, et je me lèverai, et je poursuivrai David cette nuit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'et j’arriverai sur lui tandis qu’il est fatigué et que ses mains sont faibles, et je l’épouvanterai; et tout le peuple qui est avec lui s’enfuira, et je frapperai le roi seul;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'et je ramènerai à toi tout le peuple. L’homme que tu cherches est autant que le retour de tous: tout le peuple sera en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Et la parole fut bonne aux yeux d’Absalom et aux yeux de tous les anciens d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Et Absalom dit: Appelle aussi Hushaï, l’Arkite, et nous entendrons ce que lui aussi dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Et Hushaï vint vers Absalom; et Absalom lui parla, disant: Akhitophel a parlé de cette manière; ferons-nous ce qu’il a dit? Sinon, parle, toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Et Hushaï dit à Absalom: Le conseil qu’Akhitophel a donné cette fois n’est pas bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Et Hushaï dit: Tu connais ton père et ses hommes, que ce sont des hommes vaillants, et qu’ils ont l’amertume dans l’âme, comme une ourse dans les champs, privée de ses petits; et ton père est un homme de guerre: il ne passera pas la nuit avec le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Voici, il est maintenant caché dans quelque fosse, ou dans quelque autre lieu. Et il arrivera que, si quelques-uns tombent dès le commencement, quiconque l’apprendra, dira: Il y a une déroute parmi le peuple qui suit Absalom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'et celui-là même qui est un homme courageux, qui a un cœur de lion, se fondra entièrement, car tout Israël sait que ton père est un homme vaillant, et que ceux qui sont avec lui sont des hommes courageux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Mais je conseille qu’on assemble en hâte auprès de toi tout Israël, depuis Dan jusqu’à Beër-Shéba, nombreux comme le sable qui est près de la mer, et que toi-même tu marches au combat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Et nous arriverons à lui dans l’un des lieux où il se trouvera, et nous nous abattrons sur lui comme la rosée tombe sur le sol; et, de lui et de tous les hommes qui sont avec lui, il n’en restera pas un seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Et s’il s’est retiré dans une ville, alors tout Israël apportera des cordes vers cette ville-là, et nous la traînerons jusque dans le torrent, jusqu’à ce qu’il ne s’en trouve pas même une petite pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Et Absalom et tous les hommes d’Israël dirent: Le conseil de Hushaï, l’Arkite, est meilleur que le conseil d’Akhitophel. Et l’ Éternel avait décrété d’annuler le bon conseil d’Akhitophel, pour que l’ Éternel fasse venir le mal sur Absalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Et Hushaï dit à Tsadok et à Abiathar, les sacrificateurs: Akhitophel a conseillé ainsi et ainsi à Absalom et aux anciens d’Israël, et ainsi et ainsi moi j’ai conseillé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Et maintenant, envoyez promptement, et avertissez David, en disant: Ne passe pas la nuit dans les plaines du désert, et ne manque pas de passer plus avant, de peur que le roi ne soit englouti, et tout le peuple qui est avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Et Jonathan et Akhimaats se tenaient à En-Roguel, et une servante alla et les avertit, et ils allèrent et avertirent le roi David; car ils ne pouvaient pas se montrer entrant dans la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Et un garçon les vit, et le rapporta à Absalom; alors ils s’en allèrent les deux en hâte, et vinrent à la maison d’un homme, à Bakhurim; et il avait dans sa cour un puits, où ils descendirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Et la femme prit une couverture et l’étendit sur la bouche du puits, et répandit dessus du grain pilé; et on ne s’aperçut de rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Et les serviteurs d’Absalom allèrent vers la femme dans la maison, et dirent: Où sont Akhimaats et Jonathan? Et la femme leur dit: Ils ont passé le ruisseau. Et ils les cherchèrent et ne les trouvèrent pas, et retournèrent à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Et après qu’ils s’en furent allés, [Akhimaats et Jonathan] montèrent du puits, et allèrent et rapportèrent au roi David; et ils dirent à David: Levez-vous et passez l’eau en hâte, car Akhitophel a donné tel conseil contre vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Et David se leva, et tout le peuple qui était avec lui, et ils passèrent le Jourdain; à la lumière du matin il n’en manqua pas un qui n’ait passé le Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Et quand Akhitophel vit que son conseil n’était pas exécuté, il sella son âne, et se leva et s’en alla en sa maison, dans sa ville; et il donna des ordres à sa maison, et s’étrangla, et mourut; et il fut enterré dans le sépulcre de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Et David vint à Mahanaïm; et Absalom passa le Jourdain, lui et tous les hommes d’Israël avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Et Absalom établit Amasa sur l’armée, à la place de Joab. Et Amasa était le fils d’un homme nommé Jithra, l’Israélite, qui était entré vers Abigaïl, fille de Nakhash et sœur de Tseruïa, mère de Joab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Et Israël et Absalom se campèrent au pays de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Et comme David arrivait à Mahanaïm, Shobi, fils de Nakhash, de Rabba des fils d’Ammon, et Makir, fils d’Ammiel, de Lodebar, et Barzillaï, le Galaadite, de Roguelim,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'amenèrent des lits, et des bassins, et des vases en poterie, et du froment, et de l’orge, et de la farine, et du grain rôti, et des fèves, et des lentilles, et des grains rôtis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'et du miel, et du caillé, et du menu bétail, et des fromages de vache, pour David et pour le peuple qui était avec lui, pour qu’ils en mangent, car ils dirent: Le peuple a faim, et il est fatigué, et il a soif dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Et David passa en revue le peuple qui était avec lui, et il établit sur eux des chefs de milliers et des chefs de centaines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Et David envoya le peuple, un tiers sous la main de Joab, et un tiers sous la main d’Abishaï, fils de Tseruïa [et] frère de Joab, et un tiers sous la main d’Itthaï, le Guitthien. Et le roi dit au peuple: Certainement je sortirai moi aussi avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Mais le peuple dit: Tu ne sortiras point; car quand nous viendrions à fuir, ils ne prendraient pas garde à nous, et quand la moitié d’entre nous mourrait, ils ne prendraient pas garde à nous; car toi, tu es comme 10 000 d’entre nous; et maintenant il est bon que, de la ville, tu nous sois en secours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Et le roi leur dit: Je ferai ce qui est bon à vos yeux. Et le roi se tint à côté de la porte, et tout le peuple sortit par centaines et par milliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Et le roi commanda à Joab, et à Abishaï, et à Itthaï, disant: Usez-moi de douceur envers le jeune homme, Absalom. Et tout le peuple entendit lorsque le roi donna ses ordres à tous les chefs touchant Absalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Et le peuple sortit dans la campagne à la rencontre d’Israël; et la bataille eut lieu dans la forêt d’Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Et le peuple d’Israël fut battu là par les serviteurs de David; et le carnage fut grand ce jour-là,... 20 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Et la bataille s’étendit là sur toute la surface du pays, et la forêt dévora en ce jour plus de peuple que n’en dévora l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Et Absalom se trouva en présence des serviteurs de David, et Absalom montait un mulet; et le mulet entra sous les branches entrelacées d’un grand térébinthe; et la tête d’Absalom se prit dans le térébinthe, et il demeura suspendu entre le ciel et la terre; et le mulet qui était sous lui passa outre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Et un homme vit cela, et le rapporta à Joab, et dit: Voici, j’ai vu Absalom suspendu à un térébinthe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Et Joab dit à l’homme qui le lui rapportait: Et voici, tu l’as vu, et pourquoi ne l’as-tu pas abattu là par terre? Et ç’aurait été à moi de te donner dix [pièces] d’argent et une ceinture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Et l’homme dit à Joab: Et quand je pèserais dans ma main 1 000 [pièces] d’argent, je n’étendrais pas ma main sur le fils du roi; car à nos oreilles le roi t’a commandé, à toi, et à Abishaï, et à Itthaï, disant: Prenez garde, qui [de vous] que ce soit, au jeune homme Absalom;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'ou j’aurais agi perfidement contre ma vie, car rien n’est caché au roi, et toi, tu aurais pris parti contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Et Joab dit: Je ne m’attarderai pas ainsi devant toi. Et il prit trois javelots dans sa main, et les enfonça dans le cœur d’Absalom, alors qu’il était encore vivant au milieu du térébinthe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Et dix jeunes hommes qui portaient les armes de Joab entourèrent et frappèrent Absalom, et le mirent à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Et Joab sonna de la trompette, et le peuple revint de la poursuite d’Israël, car Joab retint le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Et ils prirent Absalom et le jetèrent dans la forêt, dans une grande fosse, et élevèrent sur lui un très grand monceau de pierres. Et tout Israël s’enfuit, chacun à sa tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Et Absalom avait pris et dressé pour lui, de son vivant, une stèle qui est dans la vallée du Roi; car il disait: Je n’ai pas de fils pour rappeler la mémoire de mon nom. Et il appela la stèle de son nom; et elle est appelée jusqu’à ce jour le monument d’Absalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Et Akhimaats, fils de Tsadok, dit: Laisse-moi courir et porter au roi la nouvelle que l’ Éternel lui a fait justice de la main de ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Et Joab lui dit: Tu ne seras pas l’homme qui porteras les nouvelles aujourd’hui, mais tu porteras les nouvelles un autre jour; aujourd’hui tu ne porteras pas les nouvelles, puisque le fils du roi est mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Et Joab dit au Cushite: Va, rapporte au roi ce que tu as vu. Et le Cushite se prosterna devant Joab, et courut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Et Akhimaats, le fils de Tsadok, dit encore une fois à Joab: Quoi qu’il arrive, que je coure, moi aussi, je te prie, après le Cushite. Et Joab dit: Pourquoi veux-tu courir, mon fils, puisque tu n’as pas des nouvelles opportunes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, '– Et quoi qu’il arrive, je veux courir. Et [Joab] lui dit: Cours! Et Akhimaats courut par le chemin de la plaine, et dépassa le Cushite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Et David était assis entre les deux portes; et la sentinelle alla sur le toit de la porte, sur la muraille, et elle leva les yeux, et regarda, et voici un homme qui courait seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Et la sentinelle cria et le rapporta au roi; et le roi dit: S’il est seul, il y a des nouvelles dans sa bouche. Et [l’homme] allait toujours, et approchait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Et la sentinelle vit un autre homme qui courait, et la sentinelle cria au portier et dit: Voici, un homme qui court seul. Et le roi dit: Celui-ci aussi apporte des nouvelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Et la sentinelle dit: Je vois le premier courir comme court Akhimaats, fils de Tsadok. Et le roi dit: C’est un homme de bien, il vient avec de bonnes nouvelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Et Akhimaats cria, et dit au roi: Paix! Et il se prosterna devant le roi, le visage contre terre, et dit: Béni soit l’ Éternel, ton Dieu, qui a livré les hommes qui avaient levé leurs mains contre le roi, mon seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Et le roi dit: Y a-t-il paix pour le jeune homme Absalom? Et Akhimaats dit: J’ai vu un grand tumulte lorsque Joab envoya le serviteur du roi et ton serviteur; et je ne sais ce qu’il y avait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Et le roi dit: Tourne-toi, et tiens-toi là. Et il se tourna, et se tint là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Et voici, le Cushite arriva, et le Cushite dit: Que le roi, mon seigneur, reçoive une bonne nouvelle, car l’ Éternel t’a aujourd’hui fait justice de la main de tous ceux qui s’étaient levés contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Et le roi dit au Cushite: Y a-t-il paix pour le jeune homme Absalom? Et le Cushite dit: Que les ennemis du roi, mon seigneur, et tous ceux qui se sont levés contre toi pour le mal, soient comme ce jeune homme!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Et le roi fut très ému, et il monta à la chambre au-dessus de la porte et pleura; et en allant, il disait ainsi: Mon fils Absalom! mon fils! mon fils Absalom! Fussé-je mort à ta place! Absalom, mon fils, mon fils!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Et on rapporta à Joab: Voici, le roi pleure et mène deuil sur Absalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Et la victoire fut changée en deuil pour tout le peuple, ce jour-là, car le peuple entendit ce jour-là qu’on disait: Le roi est affligé à cause de son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Et le peuple entra, ce jour-là, dans la ville à la dérobée, comme s’en irait à la dérobée un peuple honteux d’avoir pris la fuite dans la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Et le roi avait couvert son visage, et le roi criait à haute voix: Mon fils Absalom! Absalom, mon fils, mon fils!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Et Joab vint vers le roi dans la maison, et dit: Tu as aujourd’hui rendu honteuse la face de tous tes serviteurs, qui ont aujourd’hui sauvé ta vie, et la vie de tes fils et de tes filles, et la vie de tes femmes, et la vie de tes concubines,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'en ce que tu aimes ceux qui te haïssent, et que tu hais ceux qui t’aiment; car tu as montré aujourd’hui que tes chefs et tes serviteurs ne te sont rien; et je sais aujourd’hui que, si Absalom vivait et que, nous tous, nous soyons morts aujourd’hui, alors cela serait bon à tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Et maintenant, lève-toi, sors, et parle au cœur de tes serviteurs; car je jure par l’ Éternel que si tu ne sors, pas un homme ne demeurera cette nuit avec toi; et ceci sera pire pour toi que tout le mal qui t’est arrivé depuis ta jeunesse jusqu’à maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Et le roi se leva, et s’assit dans la porte; et on rapporta à tout le peuple, en disant: Voici, le roi est assis dans la porte. Et tout le peuple vint devant le roi. Et Israël s’était enfui, chacun à sa tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Et tout le peuple était à se disputer dans toutes les tribus d’Israël, disant: Le roi nous a délivrés de la main de nos ennemis, et c’est lui qui nous a sauvés de la main des Philistins, et maintenant il s’est enfui du pays à cause d’Absalom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'et Absalom, que nous avions oint sur nous, est mort dans la bataille; et maintenant, pourquoi gardez-vous le silence pour ce qui est de ramener le roi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Et le roi David envoya à Tsadok et à Abiathar, les sacrificateurs, disant: Parlez aux anciens de Juda, en disant: Pourquoi êtes-vous les derniers pour ramener le roi dans sa maison, alors que la parole de tout Israël est venue au roi dans sa maison?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Vous êtes mes frères, vous êtes mon os et ma chair; et pourquoi êtes-vous les derniers pour ramener le roi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Et dites à Amasa: N’es-tu pas mon os et ma chair? Que Dieu me fasse ainsi, et ainsi y ajoute, si tu n’es chef de l’armée devant moi, pour toujours, à la place de Joab!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Et il inclina le cœur de tous les hommes de Juda comme un seul homme, et ils envoyèrent dire au roi: Reviens, toi et tous tes serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Et le roi s’en retourna, et vint jusqu’au Jourdain; et Juda vint à Guilgal pour aller à la rencontre du roi, pour faire passer au roi le Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Et Shimhi, fils de Guéra, le Benjaminite, qui était de Bakhurim, se hâta et descendit avec les hommes de Juda à la rencontre du roi David,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'et, avec lui, 1 000 hommes de Benjamin, et Tsiba, serviteur de la maison de Saül, et ses 15 fils et ses 20 serviteurs avec lui; et ils traversèrent le Jourdain devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Et un bac passa pour faire passer la maison du roi, et faire ce qui était bon à ses yeux. Et Shimhi, fils de Guéra, tomba devant le roi comme il allait passer le Jourdain,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'et il dit au roi: Ne m’impute pas d’iniquité, mon seigneur, et ne te souviens pas de l’iniquité commise par ton serviteur au jour où le roi, mon seigneur, sortit de Jérusalem, en sorte que le roi le prenne à cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Car moi, ton serviteur, je sais que j’ai péché; et voici, je suis venu aujourd’hui le premier de toute la maison de Joseph, pour descendre à la rencontre du roi, mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Et Abishaï, fils de Tseruïa, répondit et dit: Ne fera-t-on pas mourir Shimhi pour cela, car il a maudit l’oint de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Et David dit: Qu’ai-je à faire avec vous, fils de Tseruïa? car vous êtes aujourd’hui des adversaires pour moi. Ferait-on mourir aujourd’hui un homme en Israël? car ne sais-je pas que je suis aujourd’hui roi sur Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Et le roi dit à Shimhi: Tu ne mourras point. Et le roi le lui jura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Et Mephibosheth, fils de Saül, descendit à la rencontre du roi; et il n’avait pas soigné ses pieds, et n’avait pas fait sa barbe, et n’avait pas lavé ses vêtements, depuis le jour où le roi s’en était allé, jusqu’au jour où il revint en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Et lorsque Jérusalem vint à la rencontre du roi, le roi lui dit: Pourquoi n’es-tu pas allé avec moi, Mephibosheth?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Et il dit: Ô roi, mon seigneur! mon serviteur m’a trompé; car ton serviteur disait: Je sellerai mon âne, et je monterai dessus, et j’irai avec le roi, car ton serviteur est boiteux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'et il a calomnié ton serviteur auprès du roi, mon seigneur; mais le roi, mon seigneur, est comme un ange de Dieu: fais donc ce qui est bon à tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Car toute la maison de mon père n’était que des hommes morts devant le roi, mon seigneur; et tu as mis ton serviteur parmi ceux qui mangent à ta table; et quel droit ai-je encore? et pour quel sujet crierai-je encore au roi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Et le roi lui dit: Pourquoi me parles-tu encore de tes affaires? Je l’ai dit: Toi et Tsiba, partagez les champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Et Mephibosheth dit au roi: Qu’il prenne même le tout, puisque le roi, mon seigneur, est revenu en paix dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Et Barzillaï, le Galaadite, descendit de Roguelim, et passa le Jourdain avec le roi, pour l’accompagner au-delà du Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Et Barzillaï était très vieux, âgé de 80 ans, et il avait entretenu le roi pendant qu’il habitait à Mahanaïm, car il était un homme très riche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Et le roi dit à Barzillaï: Passe avec moi, et je t’entretiendrai auprès de moi à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Et Barzillaï dit au roi: Combien seront les jours des années de ma vie, pour que je monte avec le roi à Jérusalem?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Je suis aujourd’hui âgé de 80 ans; puis-je distinguer ce qui est bon de ce qui est mauvais? Ton serviteur peut-il savourer ce que je mange et ce que je bois? Puis-je encore entendre la voix des chanteurs et des chanteuses? Et pourquoi ton serviteur serait-il encore à charge au roi, mon seigneur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Ton serviteur passera pour peu [de temps] le Jourdain avec le roi; et pourquoi le roi me donnerait-il cette récompense?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Que ton serviteur, je te prie, s’en retourne, afin que je meure dans ma ville, auprès du sépulcre de mon père et de ma mère; et voici ton serviteur Kimham, il passera avec le roi, mon seigneur: fais-lui ce qui sera bon à tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Et le roi dit: Kimham passera avec moi, et je lui ferai ce qui sera bon à tes yeux; et tout ce que tu voudras de moi, je te le ferai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Et tout le peuple passa le Jourdain, et le roi passa. Et le roi embrassa Barzillaï, et le bénit; et [Barzillaï] s’en retourna en son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Et le roi passa à Guilgal, et Kimham passa avec lui; et tout le peuple de Juda, et aussi la moitié du peuple d’Israël, firent passer le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Et voici, tous les hommes d’Israël vinrent vers le roi, et dirent au roi: Pourquoi nos frères, les hommes de Juda, t’ont-ils enlevé et ont-ils fait passer le Jourdain au roi, et à sa maison, et à tous les hommes de David avec lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Et tous les hommes de Juda répondirent aux hommes d’Israël: Parce que le roi m’est proche; et pourquoi y a-t-il chez toi cette colère à cause de cela? Avons-nous mangé quelque chose qui vienne du roi, ou nous a-t-il fait des présents?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 44, 'Et les hommes d’Israël répondirent aux hommes de Juda, et dirent: J’ai dix parts au roi, et aussi en David j’ai plus que toi; et pourquoi m’as-tu méprisé? Et ma parole n’a-t-elle pas été la première pour ramener mon roi? Et la parole des hommes de Juda fut plus dure que la parole des hommes d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Et il se rencontra là un homme de Bélial, son nom était Shéba, fils de Bicri, Benjaminite; et il sonna de la trompette, et dit: Nous n’avons point de part en David, ni d’héritage dans le fils d’Isaï. Chacun à sa tente, Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Et tous les hommes d’Israël, se séparant de David, suivirent Shéba, fils de Bicri; mais les hommes de Juda s’attachèrent à leur roi, depuis le Jourdain jusqu’à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Et David vint dans sa maison à Jérusalem. Et le roi prit les dix femmes concubines qu’il avait laissées pour garder la maison, et les mit dans une maison où elles étaient gardées, et les entretint; mais il n’entra pas vers elles; et elles furent enfermées jusqu’au jour de leur mort, vivant dans le veuvage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Et le roi dit à Amasa: Rassemble-moi en trois jours les hommes de Juda; et toi, sois présent ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Et Amasa s’en alla pour rassembler Juda; mais il tarda au-delà du terme qui lui était assigné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Et David dit à Abishaï: Maintenant Shéba, fils de Bicri, nous fera plus de mal qu’Absalom. Toi, prends les serviteurs de ton seigneur, et poursuis-le, de peur qu’il ne trouve des villes fortes, et qu’il ne se dérobe à nos yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Et les hommes de Joab sortirent après lui, et les Keréthiens, et les Peléthiens, et tous les hommes forts; et ils sortirent de Jérusalem pour poursuivre Shéba, fils de Bicri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Ils étaient près de la grande pierre qui est à Gabaon, qu’Amasa arriva devant eux. Et Joab était ceint de la casaque dont il était vêtu, et, par-dessus, il avait le ceinturon de l’épée attachée sur ses reins dans son fourreau; et comme il s’avançait, elle tomba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Et Joab dit à Amasa: Te portes-tu bien, mon frère? Et Joab de sa main droite saisit la barbe d’Amasa, pour l’embrasser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Et Amasa ne prenait pas garde à l’épée qui était dans la main de Joab; et [Joab] l’en frappa dans le ventre, et répandit ses entrailles à terre, sans le [frapper] une seconde fois; et il mourut. Et Joab, et Abishaï, son frère, poursuivirent Shéba, fils de Bicri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Et l’un des jeunes hommes de Joab se tint près d’Amasa, et dit: Quiconque prend plaisir en Joab et quiconque est pour David, qu’il suive Joab!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Et Amasa se roulait dans son sang, au milieu de la route; et quand cet homme vit que tout le peuple s’arrêtait, il tira Amasa hors de la route dans un champ, et jeta un vêtement sur lui, quand il vit que tous ceux qui arrivaient près de lui s’arrêtaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Quand il fut ôté de la route, tous les hommes passèrent outre après Joab, afin de poursuivre Shéba, fils de Bicri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Et [celui-ci] passa par toutes les tribus d’Israël, jusqu’à Abel et Beth-Maaca, et tout Bérim; et ils se rassemblèrent, et le suivirent aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Et ils vinrent et assiégèrent [Shéba] dans Abel-Beth-Maaca, et ils élevèrent contre la ville une terrasse, et elle se dressait contre l’avant-mur; et tout le peuple qui était avec Joab sapait pour faire tomber la muraille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Et une femme sage cria de la ville: Écoutez, écoutez! Dites, je vous prie, à Joab: Approche jusqu’ici, et je te parlerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Et il s’approcha d’elle. Et la femme dit: Es-tu Joab? Et il dit: C’est moi. Et elle lui dit: Écoute les paroles de ta servante. Et il dit: J’écoute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Et elle parla et dit: On avait coutume autrefois de parler, disant: Demandez seulement à Abel, et ainsi on en finissait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Moi, je suis paisible [et] fidèle en Israël; toi, tu cherches à faire périr une ville et une mère en Israël; pourquoi veux-tu engloutir l’héritage de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Et Joab répondit et dit: Loin de moi, loin de moi, de vouloir engloutir et détruire!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'La chose n’est pas ainsi, mais un homme de la montagne d’Éphraïm, qui a nom Shéba, fils de Bicri, a levé sa main contre le roi, contre David; livrez-le, lui seul, et je m’en irai de devant la ville. Et la femme dit à Joab: Voici, sa tête te sera jetée par la muraille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Et la femme vint vers tout le peuple, avec sa sagesse; et ils coupèrent la tête de Shéba, fils de Bicri, et la jetèrent à Joab. Et il sonna de la trompette, et on se dispersa de devant la ville, chacun à sa tente; et Joab retourna à Jérusalem vers le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Et Joab était [préposé] sur toute l’armée d’Israël; et Benaïa, fils de Jehoïada, sur les Keréthiens et sur les Peléthiens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'et Adoram, sur les levées; et Josaphat, fils d’Akhilud, était rédacteur des chroniques;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'et Sheva était scribe, et Tsadok et Abiathar, sacrificateurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'et Ira aussi, le Jaïrite, était principal officier de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, '*Et il y eut, du temps de David, une famine de trois ans, année après année. Et David rechercha la face de l’ Éternel, et l’ Éternel dit: C’est à cause de Saül et de sa maison de sang, parce qu’il a fait mourir les Gabaonites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Et le roi appela les Gabaonites et leur parla. (Or les Gabaonites n’étaient pas des fils d’Israël, mais du reste des Amoréens, et les fils d’Israël s’étaient obligés envers eux par serment; et Saül, dans son zèle pour les fils d’Israël et de Juda, avait cherché à les frapper.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Et David dit aux Gabaonites: Que ferai-je pour vous, et avec quoi ferai-je expiation, de sorte que vous bénissiez l’héritage de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Et les Gabaonites lui dirent: Il ne s’agit pas pour nous d’argent ou d’or à l’égard de Saül et de sa maison, ni qu’on fasse mourir personne en Israël. Et il dit: Ce que vous direz, je le ferai pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Et ils dirent au roi: L’homme qui nous a consumés et qui a formé un plan contre nous afin de nous détruire, pour que nous ne puissions subsister dans tous les confins d’Israël...:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'qu’on nous livre sept hommes de ses fils, et nous les pendrons devant l’ Éternel à Guibha de Saül, l’élu de l’ Éternel. Et le roi dit: Je les livrerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Et le roi épargna Mephibosheth, fils de Jonathan, fils de Saül, à cause du serment de l’ Éternel, qui était entre eux, entre David et Jonathan, fils de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Et le roi prit les deux fils de Ritspa, fille d’Aïa, qu’elle avait enfantés à Saül, Armoni et Mephibosheth, et les cinq fils de Mical, fille de Saül, qu’elle avait enfantés à Adriel, fils de Barzillaï, le Meholathite,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'et il les livra aux mains des Gabaonites, qui les pendirent sur la montagne, devant l’ Éternel; et les sept tombèrent ensemble, et on les fit mourir aux premiers jours de la moisson, au commencement de la moisson des orges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Et Ritspa, fille d’Aïa, prit un sac et l’étendit sur le rocher, depuis le commencement de la moisson jusqu’à ce qu’il tombe de l’eau des cieux sur eux; et elle ne permit pas aux oiseaux des cieux de se poser sur eux le jour, ni aux bêtes des champs la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Et ce que Ritspa, fille d’Aïa, concubine de Saül, avait fait fut rapporté à David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Et David alla et prit les os de Saül et les os de Jonathan, son fils, de chez les habitants de Jabès de Galaad, qui les avaient dérobés de la place de Beth-Shan, où les Philistins les avaient suspendus le jour où les Philistins avaient frappé Saül à Guilboa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Et il emporta de là les os de Saül et les os de Jonathan, son fils; et on recueillit les os de ceux qui avaient été pendus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'et on les enterra avec les os de Saül et de Jonathan, son fils, dans le pays de Benjamin, à Tséla, dans le sépulcre de Kis, son père. Et on fit tout ce que le roi avait commandé: et après cela, Dieu fut propice au pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Et il y eut encore une guerre des Philistins contre Israël; et David descendit, et ses serviteurs avec lui, et ils se battirent avec les Philistins; et David était fatigué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Et Jishbi-Benob, qui était des enfants du géant (le poids de sa lance était de 300 sicles d’airain, et il était ceint d’une [armure] neuve), pensa frapper David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Et Abishaï, fils de Tseruïa, le secourut, et frappa le Philistin et le tua. Alors les hommes de David lui jurèrent, disant: Tu ne sortiras plus avec nous pour la guerre, et tu n’éteindras pas la lampe d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Et il arriva, après cela, qu’il y eut encore un combat, à Gob, avec les Philistins. Alors Sibbecaï, le Hushathite, frappa Saph, qui était un des enfants du géant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Et il y eut encore un combat, à Gob, avec les Philistins: et Elkhanan, fils de Jaaré-Oreguim, le Bethléhémite, frappa Goliath, le Guitthien; et le bois de sa lance était comme l’ensouple des tisserands.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Et il y eut encore un combat, à Gath: et il y avait [là] un homme de haute stature qui avait six doigts aux mains et six orteils aux pieds, en tout 24; et lui aussi était né au géant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Et il outragea Israël; mais Jonathan, fils de Shimha, frère de David, le frappa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Ces quatre étaient nés au géant, à Gath, et tombèrent par la main de David et par la main de ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, '*Et David adressa à l’ Éternel les paroles de ce cantique, le jour où l’ Éternel l’eut délivré de la main de tous ses ennemis et de la main de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Et il dit: L’ Éternel est mon rocher et mon lieu fort, et celui qui me délivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Dieu est mon rocher, je me confierai en lui, mon bouclier et la corne de mon salut, ma haute retraite et mon refuge. Mon Sauveur, tu me sauveras de la violence!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Je crierai à l’ Éternel, qui est digne d’être loué, et je serai sauvé de mes ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Car les vagues de la mort m’ont environné, les torrents de Bélial m’ont fait peur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Les cordeaux du shéol m’ont entouré, les filets de la mort m’ont surpris:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Dans ma détresse, j’ai invoqué l’ Éternel, et j’ai appelé mon Dieu, et, de son temple, il a entendu ma voix, et mon cri est [parvenu] à ses oreilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Alors la terre fut ébranlée et trembla; les fondements des cieux furent secoués et furent ébranlés, parce qu’il était irrité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Une fumée montait de ses narines, et un feu sortant de sa bouche dévorait; des charbons en jaillissaient embrasés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Et il abaissa les cieux, et descendit; et il y avait une obscurité profonde sous ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Et il était monté sur un chérubin, et volait, et il parut sur les ailes du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Et il mit autour de lui les ténèbres pour tente, des amas d’eaux, d’épaisses nuées de l’air.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'De la splendeur qui était devant lui jaillissaient, embrasés, des charbons de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'L’ Éternel tonna des cieux, et le Très-haut fit retentir sa voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Et il tira des flèches et dispersa [mes ennemis]; [il lança] l’éclair, et les mit en déroute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Alors les lits de la mer parurent, les fondements du monde furent mis à découvert, quand l’ Éternel les tançait par le souffle du vent de ses narines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'D’en haut, il étendit [sa main], il me prit, il me tira des grandes eaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Il me délivra de mon puissant ennemi, de ceux qui me haïssaient; car ils étaient plus forts que moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Ils m’avaient surpris au jour de ma calamité, mais l’ Éternel fut mon appui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Et il me fit sortir au large, il me délivra, parce qu’il prenait son plaisir en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'L’ Éternel m’a récompensé selon ma justice, il m’a rendu selon la pureté de mes mains;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Car j’ai gardé les voies de l’ Éternel, et je ne me suis point méchamment détourné de mon Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Car toutes ses ordonnances ont été devant moi; et de ses statuts, je ne me suis pas écarté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Et j’ai été parfait envers lui, et je me suis gardé de mon iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Et l’ Éternel m’a rendu selon ma justice, selon ma pureté devant ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Avec celui qui use de grâce, tu uses de grâce; avec l’homme parfait, tu te montres parfait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Avec celui qui est pur, tu te montres pur; et avec le pervers, tu es roide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Et tu sauveras le peuple affligé, et tes yeux sont sur les hautains, [et] tu les abaisses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Car toi, Éternel! tu es ma lampe; et l’ Éternel fait resplendir mes ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Car, par toi, je courrai au travers d’une troupe; par mon Dieu, je franchirai une muraille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Quant à ✶Dieu, sa voie est parfaite; la parole de l’ Éternel est affinée; il est un bouclier à tous ceux qui se confient en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Car qui est ✶Dieu, hormis l’ Éternel? et qui est un rocher, hormis notre Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, '✶Dieu est ma puissante forteresse, et il aplanit parfaitement ma voie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Il rend mes pieds pareils à ceux des biches, et me fait tenir debout sur mes lieux élevés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Il enseigne mes mains à combattre; et mes bras bandent un arc d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Et tu m’as donné le bouclier de ton salut, et ta débonnaireté m’a agrandi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Tu as mis au large mes pas sous moi, et les chevilles de mes pieds n’ont pas chancelé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'J’ai poursuivi mes ennemis, et je les ai détruits; et je ne m’en suis pas retourné que je ne les aie consumés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Et je les ai consumés, je les ai transpercés, et ils ne se sont pas relevés, mais ils sont tombés sous mes pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Et tu m’as ceint de force pour le combat; tu as courbé sous moi ceux qui s’élevaient contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Et tu as fait que mes ennemis m’ont tourné le dos; et ceux qui me haïssaient, je les ai détruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Ils regardaient, et il n’y avait point de sauveur; [ils regardaient] vers l’ Éternel, et il ne leur a pas répondu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Et je les ai brisés menu comme la poussière de la terre; comme la boue des rues, je les ai écrasés, je les ai foulés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Et tu m’as délivré des débats de mon peuple; tu m’as gardé pour être le chef des nations; un peuple que je ne connaissais pas me servira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Les fils de l’étranger se sont soumis à moi en dissimulant; dès qu’ils ont entendu de leur oreille, ils m’ont obéi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Les fils de l’étranger ont dépéri, et ils sont sortis en tremblant de leurs lieux cachés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'L’ Éternel est vivant; et que mon Rocher soit béni! Et que Dieu, le rocher de mon salut, soit exalté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Le ✶Dieu qui m’a donné des vengeances, et qui a amené les peuples sous moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Et qui m’a fait sortir du milieu de mes ennemis. Tu m’as élevé au-dessus de ceux qui s’élèvent contre moi, tu m’as délivré de l’homme violent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'C’est pourquoi, Éternel! je te célébrerai parmi les nations, et je chanterai des cantiques à [la gloire de] ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, '[C’est lui] qui a donné de grandes délivrances à son roi, et qui use de bonté envers son oint, envers David, et envers sa semence, à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, '*Et ce sont ici les dernières paroles de David. David, le fils d’Isaï, a dit, et l’homme haut placé, l’oint du Dieu de Jacob, et le doux psalmiste d’Israël, a dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'L’Esprit de l’ Éternel a parlé en moi, et sa parole a été sur ma langue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Le Dieu d’Israël a dit, le Rocher d’Israël m’a parlé: Celui qui domine parmi les hommes sera juste, dominant en la crainte de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'et il sera comme la lumière du matin, quand le soleil se lève, un matin sans nuages: par sa clarté l’herbe tendre [germe] de la terre après la pluie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Quoique ma maison ne soit pas ainsi avec ✶Dieu, cependant il a établi avec moi une alliance éternelle, à tous égards bien ordonnée et assurée, car c’est là tout mon salut et tout mon plaisir, quoiqu’il ne la fasse pas germer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Mais [les fils de] Bélial sont tous comme des épines qu’on jette loin, car on ne les prend pas avec la main,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Et l’homme qui les touche se munit d’un fer ou d’un bois de lance; et ils seront entièrement brûlés par le feu sur le lieu même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, '*Ce sont ici les noms des hommes forts qu’avait David: Josheb-Bashébeth, Thacmonite, chef des principaux capitaines; c’était Adino, l’Etsnite, qui eut le dessus sur 800 hommes, qu’il tua en une fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Et après lui, Éléazar, fils de Dodo, fils d’un Akhokhite; il était l’un des trois hommes forts qui étaient avec David, lorsqu’ils avaient défié les Philistins qui s’étaient assemblés là pour combattre, et que les hommes d’Israël étaient montés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Il se leva, et frappa les Philistins, jusqu’à ce que sa main fut lasse et que sa main demeura attachée à l’épée; et l’ Éternel opéra une grande délivrance ce jour-là; et le peuple revint après [Éléazar], seulement pour piller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Et après lui, Shamma, fils d’Agué, Hararite: les Philistins s’étaient assemblés en troupe; et il y avait là une portion de champ pleine de lentilles, et le peuple avait fui devant les Philistins:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'et il se plaça au milieu du champ, et le sauva, et frappa les Philistins; et l’ Éternel opéra une grande délivrance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Et trois des trente chefs descendirent et vinrent au temps de la moisson vers David, dans la caverne d’Adullam, comme une troupe de Philistins était campée dans la vallée des Rephaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Et David était alors dans le lieu fort, et il y avait alors un poste des Philistins à Bethléhem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Et David convoita, et dit: Qui me fera boire de l’eau du puits de Bethléhem, qui est près de la porte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Et les trois hommes forts forcèrent le passage à travers le camp des Philistins, et puisèrent de l’eau du puits de Bethléhem, qui est près de la porte, et la prirent et l’apportèrent à David; et il ne voulut pas la boire, mais il en fit une libation à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Et il dit: Loin de moi, Éternel, que je fasse cela! N’est-ce pas le sang des hommes qui sont allés au péril de leur vie? Et il ne voulut pas la boire. Ces trois hommes forts firent cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Et Abishaï, frère de Joab, fils de Tseruïa, était chef de trois; il leva sa lance contre 300 hommes, qu’il tua. Et il eut un nom parmi les trois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Ne fut-il pas le plus honoré des trois? Et il fut leur chef; mais il n’atteignit pas les trois [premiers].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Et Benaïa, fils de Jehoïada, fils d’un homme vaillant, de Kabtseël, grand en exploits, lui, frappa deux lions de Moab; et il descendit, et frappa le lion dans une fosse, par un jour de neige.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Et c’est lui qui frappa un homme égyptien qui était de grande apparence, et l’Égyptien avait en sa main une lance; et il descendit vers lui avec un bâton, et arracha la lance de la main de l’Égyptien, et le tua avec sa propre lance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Voilà ce que fit Benaïa, fils de Jehoïada; et il eut un nom parmi les trois hommes forts:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'il fut plus honoré que les trente, mais il n’atteignit pas les trois [premiers]. Et David lui donna une place dans ses audiences privées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asçaël, frère de Joab, était des trente; Elkhanan, fils de Dodo, de Bethléhem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Shamma, le Harodite; Élika, le Harodite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Hélets, le Paltite; Ira, fils d’Ikkesh, le Thekohite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiézer, l’Anathothite; Mebunnaï, le Hushathite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Tsalmon, l’Akhokhite; Maharaï, le Netophathite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Héleb, fils de Baana, le Netophathite; Itthaï, fils de Ribaï, de Guibha des fils de Benjamin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaïa, le Pirhathonite; Hiddaï, des torrents de Gaash;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abi-Albon, l’Arbathite; Azmaveth, le Barkhumite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Éliakhba, le Shaalbonite; Bené-Jashen; Jonathan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Shamma, l’Hararite; Akhiam, fils de Sharar, l’Ararite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Éliphéleth, fils d’Akhasbaï, fils d’un Maacathien; Éliam, fils d’Akhitophel, le Guilonite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hetsraï, le Carmélite; Paaraï, l’Arbite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jighal, fils de Nathan, de Tsoba; Bani, le Gadite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Tsélek, l’Ammonite; Nakharaï, le Beérothien, qui portait les armes de Joab, fils de Tseruïa;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira, le Jéthrien; Gareb, le Jéthrien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urie, le Héthien: en tout, 37.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, '*Et la colère de l’ Éternel s’embrasa de nouveau contre Israël; et il incita David contre eux, disant: Va, dénombre Israël et Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Et le roi dit à Joab, chef de l’armée, qui était avec lui: Parcours, je te prie, toutes les tribus d’Israël depuis Dan jusqu’à Beër-Shéba, et qu’on dénombre le peuple, afin que je sache le nombre du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Et Joab dit au roi: Que l’ Éternel, ton Dieu, ajoute au peuple 100 fois autant qu’il y en a, et que les yeux du roi, mon seigneur, le voient! Mais pourquoi le roi, mon seigneur, prend-il plaisir à cela?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Mais la parole du roi prévalut sur Joab, et sur les chefs de l’armée; et Joab et les chefs de l’armée sortirent de devant le roi pour dénombrer le peuple, Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Et ils passèrent le Jourdain et campèrent à Aroër, à droite de la ville qui est au milieu du torrent de Gad, et vers Jahzer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Et ils vinrent en Galaad, et dans le bas pays de Hodshi, et vinrent à Dan-Jaan, et dans les environs de Sidon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Et ils vinrent à la ville forte de Tyr, et dans toutes les villes des Héviens et des Cananéens, et sortirent au midi de Juda, à Beër-Shéba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Et ils parcoururent tout le pays, et revinrent à Jérusalem au bout de neuf mois et 20 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Et Joab donna au roi le chiffre du recensement du peuple; et il y avait d’Israël 800 000 hommes de guerre tirant l’épée, et des hommes de Juda, 500 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Et le cœur de David le reprit, après qu’il eut dénombré le peuple; et David dit à l’ Éternel: J’ai grandement péché dans ce que j’ai fait; et maintenant, ô Éternel, fais passer, je te prie, l’iniquité de ton serviteur, car j’ai agi très follement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Et le matin, quand David se leva, la parole de l’ Éternel vint à Gad, le prophète, le voyant de David, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Va, et parle à David: Ainsi dit l’ Éternel: Je t’impose [l’une de ces] trois choses; choisis-en une, et je te la ferai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Et Gad vint vers David, et lui rapporta [cela], et lui dit: La famine viendra-t-elle sur toi sept ans dans ton pays; ou veux-tu fuir trois mois devant tes ennemis, et qu’ils te poursuivent; ou y aura-t-il trois jours de peste dans ton pays? Sache maintenant, et vois quelle parole je rapporterai à celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Et David dit à Gad: Je suis dans une grande détresse. Que nous tombions, je te prie, dans les mains de l’ Éternel, car ses compassions sont grandes; et que je ne tombe point dans la main des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Et l’ Éternel envoya la peste en Israël depuis le matin jusqu’au temps assigné; et il mourut du peuple, depuis Dan jusqu’à Beër-Shéba, 70 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Et l’ange étendit sa main sur Jérusalem pour la détruire; et l’ Éternel se repentit de ce mal, et dit à l’ange qui détruisait parmi le peuple: Assez! Retire maintenant ta main. Or l’ange de l’ Éternel était près de l’aire d’Arauna, le Jébusien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Et David, quand il vit l’ange qui frappait parmi le peuple, parla à l’ Éternel, et dit: Voici, moi j’ai péché, et moi j’ai commis l’iniquité; mais ces brebis, qu’ont-elles fait? Que ta main, je te prie, soit sur moi et sur la maison de mon père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Et Gad vint vers David, ce jour-là, et lui dit: Monte, dresse un autel à l’ Éternel dans l’aire d’Arauna, le Jébusien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Et David monta selon la parole de Gad, comme l’ Éternel l’avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Et Arauna regarda, et il vit le roi et ses serviteurs qui passaient vers lui; et Arauna sortit, et se prosterna devant le roi, le visage contre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Et Arauna dit: Pourquoi le roi, mon seigneur, vient-il vers son serviteur? Et David dit: Pour acheter de toi l’aire, pour bâtir un autel à l’ Éternel, afin que la plaie soit arrêtée de dessus le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Et Arauna dit à David: Que le roi, mon seigneur, prenne et offre ce qui est bon à ses yeux. Vois, les bœufs seront pour l’holocauste, et les traîneaux à fouler et l’attirail des bœufs, pour le bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Tout cela, ô roi! Arauna le donne au roi. Et Arauna dit au roi: L’ Éternel, ton Dieu, veuille t’avoir pour agréable!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Et le roi dit à Arauna: Non, car certainement j’ achèterai de toi pour un prix, et je n’offrirai pas à l’ Éternel, mon Dieu, des holocaustes qui ne coûtent rien. Et David acheta l’aire et les bœufs pour 50 sicles d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Et David bâtit là un autel à l’ Éternel, et offrit des holocaustes et des sacrifices de prospérités. Et l’ Éternel fut propice au pays; et la plaie fut arrêtée de dessus Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Et le roi David était vieux, avancé en âge. Et on le couvrit de vêtements, mais il ne fut pas réchauffé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Et ses serviteurs lui dirent: Qu’on cherche pour le roi, mon seigneur, une jeune fille vierge, et qu’elle se tienne devant le roi, et qu’elle le soigne, et qu’elle couche dans ton sein, et que le roi, mon seigneur, se réchauffe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Et on chercha une belle jeune fille dans tous les confins d’Israël; et on trouva Abishag, la Sunamite, et on l’amena au roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Et la jeune fille était extrêmement belle; et elle soignait le roi et le servait; mais le roi ne la connut pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, '*Et Adonija, fils de Hagguith, s’éleva, disant: Moi, je serai roi. Et il se procura des chars et des cavaliers, et 50 hommes qui couraient devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Et son père ne l’avait jamais chagriné, en disant: Pourquoi fais-tu ainsi? Et il était aussi un très bel homme; et sa mère l’avait enfanté après Absalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Et il conféra avec Joab, fils de Tseruïa, et avec Abiathar, le sacrificateur, et ils aidèrent Adonija et le suivirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Mais Tsadok, le sacrificateur, et Benaïa, fils de Jehoïada, et Nathan, le prophète, et Shimhi, et Réï, et les hommes forts qui étaient à David, ne furent pas avec Adonija.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Et Adonija sacrifia du menu et du gros bétail et des bêtes grasses, près de la pierre de Zokheleth, qui est à côté d’En-Roguel. Et il invita tous ses frères, les fils du roi, et tous les hommes de Juda, serviteurs du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Mais il n’invita pas Nathan, le prophète, ni Benaïa, ni les hommes forts, ni Salomon, son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Et Nathan parla à Bath-Shéba, mère de Salomon, en disant: N’as-tu pas entendu qu’Adonija, fils de Hagguith, règne? Et notre seigneur David ne le sait pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Maintenant donc viens, et que je te donne un conseil, je te prie, et sauve ta vie et la vie de ton fils Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Va, et entre auprès du roi David, et dis-lui: Ô roi, mon seigneur, n’as-tu pas juré à ta servante, en disant: Salomon, ton fils, régnera après moi, et lui s’assiéra sur mon trône? Et pourquoi Adonija règne-t-il?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Voici, pendant que tu parleras encore là avec le roi, moi je viendrai après toi, et je confirmerai tes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Et Bath-Shéba entra auprès du roi, dans la chambre; et le roi était très vieux; et Abishag, la Sunamite, servait le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Et Bath-Shéba s’inclina, et se prosterna devant le roi. Et le roi [lui] dit: Que veux-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Et elle lui dit: Mon seigneur, tu as juré par l’ Éternel, ton Dieu, à ta servante: Salomon, ton fils, régnera après moi, et il s’assiéra sur mon trône.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Et maintenant, voici Adonija règne; et maintenant, ô roi, mon seigneur, tu ne le sais pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Et il a sacrifié des bœufs et des bêtes grasses, et du menu bétail en abondance, et il a invité tous les fils du roi, et Abiathar, le sacrificateur, et Joab, le chef de l’armée; mais Salomon, ton serviteur, il ne l’a pas invité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Et quant à toi, ô roi, mon seigneur, les yeux de tout Israël sont sur toi, pour que tu leur déclares qui doit s’asseoir sur le trône du roi, mon seigneur, après lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Et il arrivera que, quand le roi, mon seigneur, sera endormi avec ses pères, moi et mon fils Salomon, nous serons [trouvés] coupables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Et voici, elle parlait encore avec le roi, que Nathan, le prophète, arriva.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Et on l’annonça au roi, en disant: Voici Nathan, le prophète. Et il entra devant le roi, et se prosterna en terre sur sa face devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Et Nathan dit: Ô roi, mon seigneur, as-tu dit: Adonija régnera après moi, et lui s’assiéra sur mon trône?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Car il est descendu aujourd’hui, et a sacrifié des bœufs et des bêtes grasses, et du menu bétail en abondance, et a invité tous les fils du roi, et les chefs de l’armée, et Abiathar, le sacrificateur; et voilà, ils mangent et boivent devant lui, et disent: Vive le roi Adonija!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mais moi, ton serviteur, et Tsadok, le sacrificateur, et Benaïa, fils de Jehoïada, et ton serviteur Salomon, il ne nous a pas invités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Est-ce de la part du roi, mon seigneur, que cette chose a lieu? et tu n’as pas fait connaître à tes serviteurs qui s’assiéra sur le trône du roi, mon seigneur, après lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Et le roi David répondit et dit: Appelez-moi Bath-Shéba. Et elle entra devant le roi, et se tint devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Et le roi jura, et dit: L’ Éternel est vivant, qui a racheté mon âme de toute détresse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'que, comme je t’ai juré par l’ Éternel, le Dieu d’Israël, disant: Salomon, ton fils, régnera après moi, et lui s’assiéra sur mon trône, à ma place, – ainsi je ferai ce jour-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Et Bath-Shéba s’inclina, le visage contre terre, et se prosterna devant le roi, et dit: Que le roi David, mon seigneur, vive à toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Et le roi David dit: Appelez-moi Tsadok, le sacrificateur, et Nathan, le prophète, et Benaïa, fils de Jehoïada. Et ils entrèrent devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Et le roi leur dit: Prenez avec vous les serviteurs de votre seigneur, et faites monter Salomon, mon fils, sur ma mule, et faites-le descendre à Guihon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'et que Tsadok, le sacrificateur, et Nathan, le prophète, l’oignent là pour roi sur Israël; et vous sonnerez de la trompette, et vous direz: Vive le roi Salomon!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Et vous monterez après lui; et qu’il vienne et qu’il s’asseye sur mon trône; et lui régnera à ma place; et j’ai ordonné qu’il soit prince sur Israël et sur Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Et Benaïa, fils de Jehoïada, répondit au roi et dit: Amen! Que l’ Éternel, le Dieu du roi, mon seigneur, dise ainsi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Comme l’ Éternel a été avec le roi, mon seigneur, qu’il soit de même avec Salomon, et qu’il rende son trône plus grand que le trône du roi David, mon seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Et Tsadok, le sacrificateur, et Nathan, le prophète, et Benaïa, fils de Jehoïada, et les Keréthiens, et les Peléthiens, descendirent, et firent monter Salomon sur la mule du roi David, et le menèrent à Guihon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Et Tsadok, le sacrificateur, prit la corne d’huile dans le tabernacle, et oignit Salomon; et ils sonnèrent de la trompette, et tout le peuple dit: Vive le roi Salomon!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Et tout le peuple monta après lui, et le peuple jouait de la flûte, et ils se réjouissaient d’une grande joie; et la terre se fendait au bruit qu’ils faisaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Et Adonija et tous les invités qui étaient avec lui l’entendirent, comme ils terminaient leur repas. Et Joab entendit la voix de la trompette, et il dit: Pourquoi ce bruit de la ville en tumulte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Tandis qu’il parlait, voici, Jonathan, fils d’Abiathar, le sacrificateur, arriva. Et Adonija dit: Entre, car tu es un vaillant homme, et tu apportes de bonnes nouvelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Et Jonathan répondit et dit à Adonija: Oui, mais le roi David, notre seigneur, a fait Salomon roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Et le roi a envoyé avec lui Tsadok, le sacrificateur, et Nathan, le prophète, et Benaïa, fils de Jehoïada, et les Keréthiens, et les Peléthiens, et ils l’ont fait monter sur la mule du roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'et Tsadok, le sacrificateur, et Nathan, le prophète, l’ont oint pour roi à Guihon; et, de là, ils sont montés en se réjouissant; et la ville est en tumulte. C’est là le bruit que vous avez entendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Et aussi Salomon est assis sur le trône du royaume;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'et les serviteurs du roi sont aussi venus pour bénir le roi David, notre seigneur, disant: Que ton Dieu fasse le nom de Salomon plus excellent que ton nom, et rende son trône plus grand que ton trône! Et le roi s’est prosterné sur son lit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Et le roi a aussi dit ainsi: Béni soit l’ Éternel, le Dieu d’Israël, qui a donné aujourd’hui quelqu’un qui soit assis sur mon trône, et mes yeux le voient!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Et tous les invités qui étaient avec Adonija furent saisis de peur; et ils se levèrent, et s’en allèrent chacun son chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Et Adonija eut peur à cause de Salomon, et il se leva, et s’en alla, et saisit les cornes de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Et on [le] rapporta à Salomon, disant: Voici, Adonija craint le roi Salomon; et voici, il a saisi les cornes de l’autel, disant: Que le roi Salomon me jure aujourd’hui qu’il ne fera pas mourir son serviteur par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Et Salomon dit: S’il est un homme fidèle, pas un de ses cheveux ne tombera en terre; mais si du mal est trouvé en lui, il mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Et le roi Salomon envoya, et on le fit descendre de l’autel. Et il vint et se prosterna devant le roi Salomon; et Salomon lui dit: Va dans ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, '*Et les jours de David s’approchèrent de la mort; et il commanda à Salomon, son fils, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Je m’en vais le chemin de toute la terre; fortifie-toi, et sois un homme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'et prends garde à ce qui doit être observé devant l’ Éternel, ton Dieu, en marchant dans ses voies, en gardant ses statuts, et ses commandements, et ses ordonnances, et ses témoignages, comme il est écrit dans la loi de Moïse, afin que tu réussisses dans tout ce que tu fais et où que tu te tournes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'afin que l’ Éternel accomplisse sa parole, qu’il a prononcée à mon sujet, disant: Si tes fils prennent garde à leur voie, pour marcher devant moi en vérité, de tout leur cœur et de toute leur âme, tu ne manqueras pas d’un homme sur le trône d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Et toi, tu sais aussi ce que m’a fait Joab, fils de Tseruïa, ce qu’il a fait aux deux chefs des armées d’Israël, à Abner, fils de Ner, et à Amasa, fils de Jéther, en les tuant et en versant le sang de la guerre en [temps de] paix, et [comment] il a mis le sang de la guerre sur la ceinture qui était sur ses reins, et sur les sandales qui étaient à ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Et fais selon ta sagesse, et ne laisse pas ses cheveux blancs descendre dans le shéol en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Mais tu useras de bonté envers les fils de Barzillaï, le Galaadite, et ils seront de ceux qui mangent à ta table, car ils sont venus ainsi à ma rencontre, quand je m’enfuyais devant Absalom, ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Et voici, il y a avec toi Shimhi, fils de Guéra, le Benjaminite, de Bakhurim: celui-là m’a maudit d’une malédiction violente, au jour où je m’en allais à Mahanaïm. Mais il descendit à ma rencontre au Jourdain, et je lui jurai par l’ Éternel, disant: Si je te fais mourir par l’épée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Et maintenant, ne le tiens pas pour innocent, car tu es un homme sage, et tu sais ce que tu as à lui faire; mais fais descendre, dans le sang, ses cheveux blancs au shéol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Et David s’endormit avec ses pères; et il fut enterré dans la ville de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Et les jours que David régna sur Israël furent 40 ans: à Hébron il régna sept ans, et à Jérusalem il régna 33 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Et Salomon s’assit sur le trône de David, son père, et son royaume fut très affermi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, '*Et Adonija, fils de Hagguith, vint vers Bath-Shéba, mère de Salomon; et elle dit: Est-ce en paix que tu viens? Et il dit: En paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Et il dit: J’ai quelque chose à te dire. Et elle dit: Parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Et il dit: Tu sais que le royaume était à moi, et que tout Israël avait porté ses yeux sur moi pour que je sois roi; mais le royaume a tourné, et est [passé] à mon frère, car il était à lui de par l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Et maintenant je te fais une seule requête; ne me repousse pas. Et elle lui dit: Parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Et il dit: Parle, je te prie, au roi Salomon, car il ne te repoussera pas, afin qu’il me donne Abishag, la Sunamite, pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Et Bath-Shéba dit: Bien; je parlerai au roi pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Et Bath-Shéba entra auprès du roi Salomon pour lui parler pour Adonija. Et le roi se leva pour aller à sa rencontre, et il s’inclina devant elle; et il s’assit sur son trône, et fit mettre un trône pour la mère du roi; et elle s’assit à sa droite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Et elle dit: J’ai une petite requête à te faire, ne me repousse pas. Et le roi lui dit: Demande, ma mère, car je ne te repousserai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Et elle dit: Qu’Abishag, la Sunamite, soit donnée pour femme à Adonija, ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Et le roi Salomon répondit et dit à sa mère: Et pourquoi demandes-tu Abishag, la Sunamite, pour Adonija? Demande aussi pour lui le royaume, car il est mon frère plus âgé que moi, – et pour lui, et pour Abiathar, le sacrificateur, et pour Joab, fils de Tseruïa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Et le roi Salomon jura par l’ Éternel, disant: Que Dieu me fasse ainsi, et ainsi y ajoute, si Adonija n’a pas prononcé cette parole contre sa propre vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Et maintenant, l’ Éternel est vivant, qui m’a affermi et m’a fait asseoir sur le trône de David, mon père, et m’a fait une maison comme il l’avait dit, qu’aujourd’hui Adonija sera mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Et le roi Salomon envoya par Benaïa, fils de Jehoïada, qui se jeta sur lui, et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Et le roi dit à Abiathar, le sacrificateur: Va dans tes champs, à Anathoth, car tu es digne de mort; mais, aujourd’hui, je ne te mettrai pas à mort, car tu as porté l’arche du Seigneur Éternel devant David, mon père, et tu as été affligé en tout ce en quoi mon père a été affligé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Et Salomon chassa Abiathar de la sacrificature de l’ Éternel, pour accomplir la parole de l’ Éternel, qu’il prononça au sujet de la maison d’Éli, en Silo.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Et la nouvelle en vint jusqu’à Joab (car Joab s’était détourné après Adonija, mais ne s’était pas détourné après Absalom), et Joab s’enfuit à la tente de l’ Éternel, et saisit les cornes de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Et on rapporta au roi Salomon que Joab s’était enfui à la tente de l’ Éternel: et voici, il est à côté de l’autel! Et Salomon envoya Benaïa, fils de Jehoïada, disant: Va, jette-toi sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Et Benaïa se rendit à la tente de l’ Éternel, et dit à Joab: Ainsi dit le roi: Sors! Et il dit: Non, car je mourrai ici. Et Benaïa rapporta la chose au roi, disant: Ainsi a dit Joab, et ainsi il m’a répondu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Et le roi lui dit: Fais comme il a dit, et jette-toi sur lui, et enterre-le; et ôte de dessus moi et de dessus la maison de mon père le sang que Joab a versé sans cause;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'et l’ Éternel fera retomber sur sa propre tête le sang qu’il a versé, parce qu’il s’est jeté sur deux hommes plus justes et meilleurs que lui, et les a tués avec l’épée, et mon père David n’en savait rien: Abner, fils de Ner, chef de l’armée d’Israël, et Amasa, fils de Jéther, chef de l’armée de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Et leur sang retombera sur la tête de Joab et sur la tête de sa semence, à toujours; mais la paix sera de par l’ Éternel sur David et sur sa semence, et sur sa maison, et sur son trône, à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Et Benaïa, fils de Jehoïada, monta et se jeta sur lui, et le tua; et il fut enterré dans sa maison, dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Et le roi mit Benaïa, fils de Jehoïada, à sa place sur l’armée; et le roi mit Tsadok, le sacrificateur, à la place d’Abiathar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Et le roi envoya, et appela Shimhi, et lui dit: Bâtis-toi une maison à Jérusalem, et habite là; et tu ne sortiras pas de là, où que ce soit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'et il arrivera qu’au jour où tu sortiras et que tu passeras le torrent du Cédron..., sache bien que tu mourras; ton sang sera sur ta tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Et Shimhi dit au roi: La parole est bonne; selon que le roi, mon seigneur, a parlé, ainsi fera ton serviteur. Et Shimhi demeura à Jérusalem bien des jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Et il arriva, au bout de trois ans, que deux serviteurs de Shimhi s’enfuirent vers Akish, fils de Maaca, roi de Gath. Et on le fit savoir à Shimhi, disant: Voici, tes serviteurs sont à Gath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Et Shimhi se leva et sella son âne, et s’en alla à Gath, vers Akish, pour chercher ses serviteurs. Et Shimhi alla, et ramena de Gath ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Et on rapporta à Salomon que Shimhi était allé de Jérusalem à Gath, et qu’il était de retour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Et le roi envoya, et appela Shimhi, et lui dit: Ne t’ai-je pas fait jurer par l’ Éternel, et ne t’ai-je pas protesté, disant: Au jour où tu sortiras et que tu t’en iras où que ce soit, sache bien que tu mourras? Et tu me dis: La parole que j’ai entendue est bonne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Et pourquoi n’as-tu pas observé le serment de l’ Éternel, et le commandement que je t’ai commandé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Et le roi dit à Shimhi: Tu sais tout le mal que ton cœur a la conscience d’avoir fait à David, mon père; et l’ Éternel fait retomber ton iniquité sur ta tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Et le roi Salomon sera béni, et le trône de David sera affermi devant l’ Éternel à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Et le roi commanda à Benaïa, fils de Jehoïada, et il sortit, et se jeta sur lui; et il mourut. Et le royaume fut affermi dans la main de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, '*Et Salomon s’allia par mariage avec le Pharaon, roi d’Égypte, et prit [pour femme] la fille du Pharaon; et il l’amena dans la ville de David, jusqu’à ce qu’il ait achevé de bâtir sa maison, et la maison de l’ Éternel, et la muraille de Jérusalem, tout à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Seulement le peuple sacrifiait sur les hauts lieux; car aucune maison ne fut bâtie pour le nom de l’ Éternel jusqu’à ces jours-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Et Salomon aimait l’ Éternel, marchant dans les statuts de David, son père; seulement il offrait des sacrifices et faisait fumer de l’encens sur les hauts lieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Et le roi s’en alla à Gabaon pour y sacrifier, car c’était le principal haut lieu; Salomon offrit 1 000 holocaustes sur cet autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'L’ Éternel apparut à Salomon, à Gabaon, dans un songe de la nuit. Et Dieu dit: Demande ce que tu veux que je te donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Et Salomon dit: Tu as usé d’une grande bonté envers ton serviteur David, mon père, selon qu’il a marché devant toi en vérité et en justice, et en droiture de cœur avec toi; et tu lui as gardé cette grande bonté, et tu lui as donné un fils qui est assis sur son trône, comme [il en est] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Et maintenant, Éternel, mon Dieu, tu as fait roi ton serviteur en la place de David, mon père, et moi, je suis un jeune garçon, je ne sais pas sortir et entrer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'et ton serviteur est au milieu de ton peuple, que tu as choisi, un peuple nombreux, qui ne peut se compter ni nombrer à cause de [sa] multitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Donne donc à ton serviteur un cœur qui écoute, pour juger ton peuple, pour discerner entre le bien et le mal; car qui est capable de juger ton si grand peuple?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Et la parole fut bonne aux yeux du Seigneur, que Salomon ait demandé cette chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Et Dieu lui dit: Parce que tu as demandé cela, et que tu n’as pas demandé pour toi de longs jours, et que tu n’as pas demandé pour toi des richesses, et que tu n’as pas demandé la vie de tes ennemis, mais que tu as demandé pour toi du discernement afin de comprendre le juste jugement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'voici, j’ai fait selon ta parole; voici, je t’ai donné un cœur sage et intelligent, en sorte qu’il n’y aura eu personne comme toi, avant toi, et qu’après toi il ne se lèvera personne comme toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Et je t’ai donné aussi ce que tu n’as pas demandé, tant les richesses que la gloire, de sorte qu’il n’y aura personne comme toi parmi les rois, tous tes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Et si tu marches dans mes voies, gardant mes statuts et mes commandements, comme David, ton père, a marché, alors je prolongerai tes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Et Salomon se réveilla, et voici, [c’était] un songe. Et il vint à Jérusalem, et se tint devant l’arche de l’alliance de l’ Éternel, et offrit des holocaustes, et offrit des sacrifices de prospérités, et fit un festin à tous ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Alors deux femmes prostituées vinrent vers le roi, et se tinrent devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Et la première femme dit: Ah, mon seigneur! moi et cette femme nous habitions la même maison, et j’accouchai, étant avec elle dans la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Et il arriva, le troisième jour après que j’eus accouché, que cette femme aussi accoucha. Et nous étions ensemble; aucun étranger n’était avec nous dans la maison, il n’y avait que nous deux dans la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Et le fils de cette femme mourut dans la nuit, parce qu’elle s’était couchée sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Et elle se leva au milieu de la nuit, et prit mon fils d’à côté de moi, pendant que ta servante dormait, et le coucha dans son sein; et son fils, qui était mort, elle le coucha dans mon sein.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Et je me levai le matin pour donner à téter à mon fils, et voici, il était mort; et je le considérai au matin, et voici, ce n’était pas mon fils que j’avais enfanté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Et l’autre femme dit: Non, car mon fils est celui qui vit, et ton fils est celui qui est mort. Et celle-là disait: Non, car ton fils est celui qui est mort, et mon fils est celui qui vit. Elles parlaient ainsi devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Et le roi dit: Celle-ci dit: Celui-ci est mon fils, qui vit, et ton fils, c’est celui qui est mort; et celle-là dit: Non, car c’est ton fils qui est mort, et mon fils est celui qui vit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Et le roi dit: Apportez-moi une épée. Et on apporta l’épée devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Et le roi dit: Coupez en deux l’enfant qui vit, et donnez la moitié à l’une, et la moitié à l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Et la femme à qui était l’enfant vivant parla au roi, car ses entrailles étaient tout émues pour son fils, et elle dit: Ah, mon seigneur! donnez-lui l’enfant vivant, et ne le tuez point. Et l’autre dit: Qu’il ne soit ni à moi, ni à toi; coupez-le en deux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Et le roi répondit et dit: Donnez à celle-là l’enfant qui vit, et ne le tuez point: c’est elle qui est sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Et tout Israël entendit parler du jugement que le roi avait prononcé; et ils craignirent le roi, car ils voyaient que la sagesse de Dieu était en lui pour faire justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Et le roi Salomon était roi sur tout Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Et ce sont ici les princes qu’il avait: Azaria, fils de Tsadok, le sacrificateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Élihoreph et Akhija, fils de Shisha, scribes; Josaphat, fils d’Akhilud, rédacteur des chroniques;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'et Benaïa, fils de Jehoïada, [préposé] sur l’armée; et Tsadok, et Abiathar, sacrificateurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'et Azaria, fils de Nathan, [préposé] sur les intendants; et Zabud, fils de Nathan, principal officier, ami du roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'et Akhishar, [préposé] sur la maison, et Adoniram, fils d’Abda, sur les levées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Et Salomon avait douze intendants sur tout Israël, et ils pourvoyaient à l’entretien du roi et de sa maison; chacun était tenu de pourvoir à cet entretien un mois dans l’année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Et ce sont ici leurs noms: le fils de Hur, dans la montagne d’Éphraïm;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'le fils de Déker, à Makats, et à Shaalbim, et à Beth-Shémesh, et à Élon-Beth-Hanan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'le fils de Hésed, à Arubboth: il avait Soco et tout le pays de Hépher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Le fils d’Abinadab avait toutes les hauteurs de Dor; il avait Taphath, fille de Salomon, pour femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, fils d’Akhilud, avait Thaanac et Meguiddo, et tout Beth-Shean, qui est à côté de Tsarthan, sous Jizreël, depuis Beth-Shean jusqu’à Abel-Mehola, jusqu’au-delà de Jokmeam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Le fils de Guéber était à Ramoth de Galaad: il avait les bourgs de Jaïr, fils de Manassé, qui sont en Galaad, la région d’Argob, qui est en Basan, 60 grandes villes avec des murailles et des barres d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Akhinadab, fils d’Iddo, était à Mahanaïm;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Akhimaats, en Nephthali: lui aussi avait pris Basmath, fille de Salomon, pour femme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, fils de Hushaï, en Aser et en Aloth;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josaphat, fils de Paruakh, en Issacar;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Shimhi, fils d’Éla, en Benjamin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Guéber, fils d’Uri, dans le pays de Galaad, le pays de Sihon, roi des Amoréens, et d’Og, roi de Basan: il était le seul intendant qui soit dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juda et Israël étaient nombreux, comme le sable qui est près de la mer, en multitude, – mangeant et buvant, et se réjouissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Et Salomon domina sur tous les royaumes, depuis le fleuve jusqu’au pays des Philistins, et jusqu’à la frontière d’Égypte: ils apportèrent des présents et servirent Salomon tous les jours de sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Et l’ordinaire de Salomon, pour un jour, était: 30 cors de fleur de farine, et 60 cors de farine,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'dix bœufs gras, et 20 bœufs de pâturages, et 100 moutons, outre les cerfs, et les gazelles, et les daims, et la volaille engraissée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Car il dominait sur tout [ce qui était] en deçà du fleuve, depuis Thiphsakh jusqu’à Gaza, sur tous les rois en deçà du fleuve; et il était en paix avec tous ses alentours, de tous côtés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Et Juda et Israël habitèrent en sécurité, chacun sous sa vigne et sous son figuier, depuis Dan jusqu’à Beër-Shéba, tous les jours de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Et Salomon avait 40 000 stalles pour les chevaux de ses chars, et 12 000 cavaliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Et ces intendants pourvoyaient à l’entretien du roi Salomon et de tous ceux qui venaient à la table du roi Salomon, chacun en son mois; ils ne laissaient rien manquer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Et ils faisaient venir l’orge et la paille pour les chevaux et les coursiers au lieu où était [l’intendant], chacun selon sa règle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Et Dieu donna à Salomon de la sagesse et une très grande intelligence, et un cœur large comme le sable qui est sur le bord de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Et la sagesse de Salomon était plus grande que la sagesse de tous les fils de l’orient et toute la sagesse de l’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Et il était plus sage qu’aucun homme, plus qu’Éthan, l’Ezrakhite, et qu’Héman, et Calcol, et Darda, les fils de Makhol. Et sa renommée était [répandue] parmi toutes les nations, à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Et il proféra 3 000 proverbes, et ses cantiques furent [au nombre] de 1 005.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Et il parla sur les arbres, depuis le cèdre qui est sur le Liban, jusqu’à l’hysope qui sort du mur; et il parla sur les bêtes, et sur les oiseaux, et sur les reptiles, et sur les poissons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Et de tous les peuples on venait pour entendre la sagesse de Salomon, de la part de tous les rois de la terre qui avaient entendu parler de sa sagesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, '*Et Hiram, roi de Tyr, envoya ses serviteurs vers Salomon, car il avait entendu qu’on l’avait oint pour roi à la place de son père; car Hiram avait toujours aimé David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Et Salomon envoya vers Hiram, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Tu sais, quant à David, mon père, qu’il ne put bâtir une maison pour le nom de l’ Éternel, son Dieu, à cause de la guerre dont [ses ennemis] l’entourèrent jusqu’à ce que l’ Éternel les mit sous la plante de ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Mais maintenant l’ Éternel, mon Dieu, m’a donné de la tranquillité de tous les côtés; il n’y a ni adversaire ni événement fâcheux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 19, 'Et voici, j’ai résolu de bâtir une maison pour le nom de l’ Éternel, mon Dieu, ainsi que l’ Éternel a parlé à David, mon père, disant: Ton fils, que je mettrai à ta place sur ton trône, lui, bâtira une maison à mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 20, 'Et maintenant, commande qu’on me coupe des cèdres dans le Liban; et mes serviteurs seront avec tes serviteurs, et je te donnerai les gages de tes serviteurs selon tout ce que tu [me] diras; car tu sais qu’il n’y a personne parmi nous qui s’entende à couper le bois comme les Sidoniens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 21, 'Et il arriva, quand Hiram entendit les paroles de Salomon, qu’il s’en réjouit beaucoup; et il dit: Béni soit aujourd’hui l’ Éternel, qui a donné à David un fils sage, sur ce grand peuple!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 22, 'Et Hiram envoya à Salomon, disant: J’ai entendu ce que tu m’as envoyé [dire]; je ferai tout ce que tu désires, à l’égard des bois de cèdre et des bois de cyprès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 23, 'Mes serviteurs les descendront du Liban à la mer, et je les mettrai en radeaux sur la mer [pour les faire passer] jusqu’au lieu que tu m’enverras [dire]; et je les ferai délier là, et tu les enlèveras. Et toi, tu accompliras mon désir, en donnant du pain à ma maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 24, 'Et Hiram donna à Salomon des bois de cèdre, et des bois de cyprès, tout ce qu’il désirait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 25, 'et Salomon donna à Hiram 20 000 cors de froment pour nourrir sa maison, et 20 cors d’huile fine. C’est là ce que Salomon donna à Hiram chaque année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 26, 'Et l’ Éternel donna de la sagesse à Salomon, comme il le lui avait dit. Et il y eut paix entre Hiram et Salomon, et ils firent alliance eux deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 27, 'Et le roi Salomon fit une levée sur tout Israël, et la levée fut de 30 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 28, 'Et il les envoya au Liban, 10 000 par mois, par relais: ils étaient un mois au Liban, deux mois à la maison; et Adoniram était [préposé] sur la levée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 29, 'Et Salomon avait 70 000 [hommes] qui portaient des fardeaux, et 80 000 qui taillaient [la pierre] sur la montagne,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 30, 'outre les chefs, les intendants de Salomon, qui étaient [préposés] sur l’œuvre, 3 300, qui avaient autorité sur le peuple qui travaillait à l’œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 31, 'Et le roi commanda, et on transporta de grandes pierres, des pierres de prix, pour faire les fondements de la maison, des pierres de taille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 32, 'Et les ouvriers de Salomon et les ouvriers de Hiram, et les Guibliens, taillèrent et préparèrent le bois et les pierres pour bâtir la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, '*Et il arriva, en la quatre cent quatre-vingtième année après la sortie des fils d’Israël du pays d’Égypte, en la quatrième année du règne de Salomon sur Israël, au mois de Ziv, qui est le second mois, que [Salomon] bâtit la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Et la maison que le roi Salomon bâtit à l’ Éternel avait 60 coudées de longueur, et 20 [coudées] de largeur, et 30 coudées de hauteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Et le portique devant le temple de la maison avait 20 coudées de longueur, selon la largeur de la maison; sa profondeur était de dix coudées devant la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Et il fit à la maison des fenêtres fermées à linteaux saillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Et il bâtit, contre le mur de la maison, des étages à l’entour, contre les murs de la maison à l’entour du temple et de l’oracle; et il fit des chambres latérales à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'L’étage inférieur avait cinq coudées de largeur, et celui du milieu six coudées de largeur, et le troisième sept coudées de largeur; car il fit des retraites dans [l’épaisseur du mur de] la maison, tout à l’entour, en dehors, afin que [la charpente] n’entre pas dans les murs de la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Et la maison, quand on la bâtit, fut bâtie de pierre entièrement préparée avant d’être transportée; et on n’entendit ni marteaux, ni hache, aucun instrument de fer, dans la maison, quand on la bâtit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'L’entrée des chambres latérales [de l’étage] du milieu était du côté droit de la maison; et on montait par un escalier tournant à [l’étage] du milieu, et de celui du milieu au troisième.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Et il bâtit la maison et l’acheva; et il couvrit la maison de poutres et de rangées [de planches] de cèdre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Et il bâtit les étages contre toute la maison, hauts de cinq coudées, et ils tenaient à la maison par des bois de cèdre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Et la parole de l’ Éternel vint à Salomon, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Quant à cette maison que tu bâtis, si tu marches dans mes statuts, et que tu pratiques mes ordonnances, et que tu gardes tous mes commandements, pour y marcher, j’accomplirai à ton égard ma parole, que j’ai dite à David, ton père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'et je demeurerai au milieu des fils d’Israël, et je n’abandonnerai pas mon peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Et Salomon bâtit la maison et l’acheva.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, '– Et il revêtit les murs de la maison, par-dedans, de planches de cèdre; depuis le sol de la maison jusqu’au haut des murs du toit, il les recouvrit de bois par-dedans; et il couvrit le sol de la maison de planches de cyprès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Et il revêtit de planches de cèdre, tant le sol que les murs, les 20 coudées du fond de la maison; et il les revêtit par-dedans, pour [être] l’oracle, le lieu très saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Et la maison, c’est-à-dire le temple, devant [l’oracle], était de 40 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Et le cèdre qui revêtait la maison, au-dedans, [était orné] de sculptures de coloquintes et de fleurs entrouvertes: tout était de cèdre, on ne voyait pas de pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Et il prépara l’oracle à l’intérieur de la maison, au-dedans, pour y mettre l’arche de l’alliance de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Et l’intérieur de l’oracle était de 20 coudées en longueur, et de 20 coudées en largeur, et de 20 coudées en hauteur; et il le recouvrit d’or pur; il [en] recouvrit aussi l’autel de cèdre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Et Salomon recouvrit d’or pur la maison, au-dedans. Et il ferma avec des chaînes d’or l’oracle, par-devant, et le recouvrit d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Et il recouvrit d’or toute la maison, toute la maison entièrement. Et il recouvrit d’or tout l’autel qui [appartenait] à l’oracle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Et il fit dans l’oracle deux chérubins de bois d’olivier, hauts de dix coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Et une aile d’un chérubin avait cinq coudées, et l’autre aile du chérubin avait cinq coudées: dix coudées d’un bout de ses ailes jusqu’à l’autre bout de ses ailes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'et l’autre chérubin avait dix coudées. Les deux chérubins avaient une même mesure, et une même forme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'La hauteur d’un chérubin était de dix coudées, et de même [celle] de l’autre chérubin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Et il mit les chérubins au milieu de la maison intérieure; et les chérubins étendaient leurs ailes, de sorte que l’aile de l’un touchait le mur, et que l’aile de l’autre chérubin touchait l’autre mur; et leurs ailes, au milieu de la maison, se touchaient, aile à aile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Et il recouvrit d’or les chérubins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Et il sculpta tous les murs de la maison, tout à l’entour, les ouvrageant de figures de chérubins, et de palmiers, et de fleurs entrouvertes, à l’intérieur et à l’extérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Et il recouvrit d’or le plancher de la maison, à l’intérieur et à l’extérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Et, pour l’entrée de l’oracle, il fit des portes de bois d’olivier. Le linteau [et] les poteaux [occupaient] un cinquième [de la largeur de la maison].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Et les deux battants étaient de bois d’olivier; et il sculpta dessus des figures de chérubins, et de palmiers, et de fleurs entrouvertes, et recouvrit d’or [le tout], et étendit l’or sur les chérubins et sur les palmiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Et il fit de même, à l’entrée du temple, des poteaux en bois d’olivier [occupant] un quart [de la largeur de la maison],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'et deux battants en bois de cyprès; les deux vantaux de l’un des battants tournaient sur eux-mêmes, et les deux vantaux de l’autre battant tournaient sur eux-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Et il sculpta [dessus] des chérubins et des palmiers, et des fleurs entrouvertes, et recouvrit [le tout] avec de l’or appliqué sur la sculpture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Et il bâtit le parvis intérieur de trois rangées de pierres de taille et d’une rangée de poutres de cèdre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'La quatrième année, au mois de Ziv, les fondements de la maison de l’ Éternel furent posés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'et la onzième année, au mois de Bul, qui est le huitième mois, la maison fut achevée dans toutes ses parties et selon toute l’ordonnance à son égard. Et [Salomon] la bâtit en sept ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, '*Et Salomon mit 13 ans à bâtir sa propre maison, et il acheva toute sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Et il bâtit la maison de la forêt du Liban, longue de 100 coudées, et large de 50 coudées, et haute de 30 coudées, sur quatre rangs de colonnes de cèdre, et il y avait des poutres de cèdre sur les colonnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'et elle était couverte de cèdre en haut, par-dessus les chambres latérales, qui reposaient sur 45 colonnes, 15 par rang;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'et il y avait trois rangées de [fenêtres à] linteaux saillants, un jour vis-à-vis d’un jour, trois fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Et toutes les entrées et les poteaux étaient carrés, avec une architrave, un jour répondant à un jour, trois fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Et il fit le portique à colonnes, long de 50 coudées, et large de 30 coudées, et un portique par-devant, et des colonnes et un perron devant elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Et il fit le portique du trône, où il jugeait, le portique de jugement; et il était couvert de cèdre, de plancher à plancher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Et sa maison, où il habitait, [avait] une autre cour au-dedans du portique; elle était en ouvrage du même genre. Et il fit, [sur] le même [plan] que ce portique, une maison pour la fille du Pharaon, que Salomon avait prise [pour femme].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Tous ces [bâtiments] étaient en pierres de prix, des pierres de taille selon les mesures, sciées à la scie, au-dedans et au-dehors, depuis les fondements jusqu’au chaperon, et depuis le dehors jusqu’à la grande cour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Et les fondements étaient en pierres de prix, de grandes pierres, des pierres de dix coudées et des pierres de huit coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Et au-dessus, il y avait des pierres de prix, des pierres de taille selon les mesures, et du cèdre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Et la grande cour avait, tout à l’entour, trois rangées de pierres de taille et une rangée de poutres de cèdre; et [de même] le parvis intérieur de la maison de l’ Éternel et le portique de la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Et le roi Salomon envoya, et prit de Tyr Hiram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Il était fils d’une femme veuve de la tribu de Nephthali, et son père était Tyrien, ouvrier en airain; et il était rempli de sagesse et d’intelligence, et de connaissance pour faire tous les ouvrages en airain; et il vint vers le roi Salomon, et fit tout son ouvrage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Et il forma les deux colonnes d’airain: une colonne avait 18 coudées de hauteur, et un fil de douze coudées faisait le tour de l’autre colonne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Et il fit deux chapiteaux d’airain fondu pour les mettre sur les sommets des colonnes; l’un des chapiteaux avait cinq coudées de hauteur, et l’autre chapiteau avait cinq coudées de hauteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Il y avait aux chapiteaux qui étaient sur le sommet des colonnes, des réseaux en ouvrage réticulé de torsades, en façon de chaînes, sept à un chapiteau, et sept à l’autre chapiteau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Il fit aussi des grenades, savoir deux rangées à l’entour, sur un réseau, pour couvrir les chapiteaux qui étaient sur le sommet des colonnes; et il en fit de même pour l’autre chapiteau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Et les chapiteaux qui étaient sur le sommet des colonnes étaient d’un ouvrage de lis, [comme] dans le portique, de quatre coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Et les chapiteaux, sur les deux colonnes, en haut, joignaient le renflement qui était derrière le réseau; et il y avait 200 grenades, en rangées, autour de l’autre chapiteau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Et il dressa les colonnes vers le portique du temple; et il dressa la colonne de droite, et appela son nom Jakin; et il dressa la colonne de gauche, et appela son nom Boaz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Et sur le sommet des colonnes, il y avait un ouvrage de lis. Et l’ouvrage des colonnes fut achevé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Et il fit la mer de fonte, de dix coudées d’un bord à l’autre bord, ronde tout autour, et haute de cinq coudées; et un cordon de 30 coudées l’entourait tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Et au-dessous du bord, tout à l’entour, il y avait des coloquintes qui l’environnaient, dix par coudée, entourant la mer tout autour, deux rangs de coloquintes, fondues d’une seule fonte avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Elle était posée sur douze bœufs, trois tournés vers le nord, et trois tournés vers l’occident, et trois tournés vers le midi, et trois tournés vers le levant; et la mer était sur eux, par-dessus; et toute leur partie postérieure était en dedans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Et son épaisseur était d’une paume, et son bord était comme le travail du bord d’une coupe, en fleurs de lis; elle contenait 2 000 baths.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Et il fit les dix bases d’airain; la longueur d’une base était de quatre coudées, et la largeur, de quatre coudées, et la hauteur, de trois coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Et voici quel était l’ouvrage de la base: elles avaient des panneaux, des panneaux entre les baguettes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'et, sur les panneaux qui étaient entre les baguettes, il y avait des lions, des bœufs, et des chérubins; et sur les baguettes, au-dessus, il y avait un socle; et, au-dessous des lions et des bœufs, il y avait des guirlandes en façon de festons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Et il y avait quatre roues d’airain à une base, et des essieux d’airain; et les quatre pieds avaient des épaules. Au-dessous de la cuve, il y avait des épaules jetées en fonte, vis-à-vis de chacune des guirlandes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Et son ouverture, au-dedans du chapiteau et au-dessus, était d’une coudée, et l’ouverture du chapiteau était ronde [comme] l’ouvrage du socle, d’une coudée et une demi-coudée; et sur son ouverture il y avait aussi des sculptures; et leurs panneaux étaient carrés, non pas ronds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Et les quatre roues étaient au-dessous des panneaux; et les supports des roues étaient dans la base; et la hauteur d’une roue était d’une coudée et une demi-coudée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Et l’ouvrage des roues était comme l’ouvrage d’une roue de char: leurs supports, et leurs jantes, et leurs rayons, et leurs moyeux, tout était de fonte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Et il y avait quatre épaules, aux quatre coins d’une base; les épaules sortaient de la base.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Et à la partie supérieure de la base, il y avait une élévation d’une demi-coudée, ronde, tout autour, et, sur la partie supérieure de la base, les supports et les panneaux, de la même [pièce].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Et il grava sur les tables de ses supports et sur ses panneaux des chérubins, des lions, et des palmiers, selon le champ de chacune, et des guirlandes tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Selon ce [modèle] il fit les dix bases: toutes d’une même fonte, d’une même mesure, d’une même forme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Et il fit dix cuves d’airain: une cuve contenait 40 baths; une cuve était de quatre coudées; chaque cuve était sur une base, pour les dix bases;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'et il plaça les bases, cinq sur le côté droit de la maison, et cinq sur le côté gauche de la maison. Et il plaça la mer sur le côté droit de la maison, à l’orient, vers le midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Et Hiram fit les cuves, et les pelles, et les bassins. Et Hiram acheva de faire tout l’ouvrage qu’il fit pour le roi Salomon, pour la maison de l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'deux colonnes, et les deux globes des chapiteaux qui étaient sur le sommet des colonnes; et les deux réseaux pour couvrir les deux globes des chapiteaux qui étaient sur le sommet des colonnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'et les 400 grenades pour les deux réseaux, deux rangs de grenades à un réseau, pour couvrir les deux globes des chapiteaux qui étaient sur le sommet des colonnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'et les dix bases, et les dix cuves sur les bases;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'et la mer unique, et les douze bœufs sous la mer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'et les vases [à cendre], et les pelles, et les bassins. Et tous ces objets, que Hiram fit pour le roi Salomon, [pour la] maison de l’ Éternel, étaient d’airain poli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Le roi les fit fondre dans la plaine du Jourdain, dans l’épaisseur du sol, entre Succoth et Tsarthan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Et Salomon laissa tous les objets [sans les peser], à cause de leur très grand nombre; on ne rechercha pas le poids de l’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Et Salomon fit tous les objets qui étaient dans la maison de l’ Éternel: l’autel d’or; et la table d’or, sur laquelle [on mettait] le pain de proposition;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'et les chandeliers, d’or pur, cinq à droite, et cinq à gauche, devant l’oracle; et les fleurs, et les lampes, et les pincettes, d’or;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'et les écuelles, et les couteaux, et les bassins, et les coupes, et les brasiers, d’or pur; et les gonds, d’or, pour les portes de la maison intérieure, pour le lieu très saint, [et] pour les portes de la maison, pour le temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Et tout l’ouvrage que le roi Salomon fit pour la maison de l’ Éternel fut achevé. Et Salomon apporta les choses saintes de David, son père, l’argent, et l’or, et les ustensiles: il les mit dans les trésors de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, '*Alors Salomon assembla les anciens d’Israël et tous les chefs des tribus, les princes des pères des fils d’Israël, auprès du roi Salomon à Jérusalem, pour faire monter l’arche de l’alliance de l’ Éternel de la ville de David, qui est Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Et tous les hommes d’Israël s’assemblèrent vers le roi Salomon, à la fête, au mois d’Éthanim, qui est le septième mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Et tous les anciens d’Israël vinrent, et les sacrificateurs portèrent l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Et ils firent monter l’arche de l’ Éternel, et la tente d’assignation, et tous les ustensiles du lieu saint qui étaient dans la tente: les sacrificateurs et les lévites les firent monter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Et le roi Salomon et toute l’assemblée d’Israël, qui s’était réunie auprès de lui [et qui était] avec lui devant l’arche, sacrifiaient du menu et du gros bétail, qu’on ne pouvait nombrer ni compter, à cause de [sa] multitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Et les sacrificateurs firent entrer l’arche de l’alliance de l’ Éternel en son lieu, dans l’oracle de la maison, dans le lieu très saint, sous les ailes des chérubins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'car les chérubins étendaient les ailes sur le lieu de l’arche, et les chérubins couvraient l’arche et ses barres, par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Et les barres étaient longues, de sorte que les bouts des barres se voyaient depuis le lieu saint, sur le devant de l’oracle, mais ils ne se voyaient pas du dehors; et elles sont là jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Il n’y avait rien dans l’arche, sauf les deux tables de pierre que Moïse y plaça en Horeb, quand l’ Éternel fit alliance avec les fils d’Israël, lorsqu’ils sortirent du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Et il arriva que, comme les sacrificateurs sortaient du lieu saint, la nuée remplit la maison de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'et les sacrificateurs ne pouvaient pas s’y tenir pour faire le service, à cause de la nuée, car la gloire de l’ Éternel remplissait la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Alors Salomon dit: L’ Éternel a dit qu’il habiterait dans l’obscurité profonde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'J’ai bâti toutefois une maison d’habitation pour toi, un lieu fixe pour que tu y demeures à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Et le roi tourna sa face, et bénit toute la congrégation d’Israël; et toute la congrégation d’Israël était debout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Et il dit: Béni soit l’ Éternel, le Dieu d’Israël, qui parla de sa bouche à David, mon père, et de sa main a accompli [sa parole], disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Depuis le jour où j’ai fait sortir d’Égypte mon peuple Israël, je n’ai choisi aucune ville d’entre toutes les tribus d’Israël pour [y] bâtir une maison afin que mon nom y soit; mais j’ai choisi David pour être [roi] sur mon peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Et David, mon père, avait à cœur de bâtir une maison pour le nom de l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Et l’ Éternel dit à David, mon père: Puisque tu as eu à cœur de bâtir une maison pour mon nom, tu as bien fait de l’avoir eu à cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'toutefois, tu ne bâtiras pas la maison; mais ton fils qui sortira de tes reins, lui, bâtira une maison pour mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Et l’ Éternel a accompli sa parole, qu’il a prononcée; et je me suis levé à la place de David, mon père, et je suis assis sur le trône d’Israël, comme l’ Éternel l’a dit; et j’ai bâti la maison pour le nom de l’ Éternel, le Dieu d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'et là j’ai établi un lieu pour l’arche, où est l’alliance de l’ Éternel, qu’il fit avec nos pères quand il les fit sortir du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Et Salomon se tint devant l’autel de l’ Éternel, en face de toute la congrégation d’Israël, et étendit ses mains vers les cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'et dit: Éternel, Dieu d’Israël! il n’y a point de Dieu comme toi, dans les cieux en haut, et sur la terre en bas, qui gardes l’alliance et la bonté envers tes serviteurs qui marchent devant toi de tout leur cœur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'toi qui as gardé envers ton serviteur David, mon père, ce que tu lui as dit: tu as parlé de ta bouche, et de ta main tu as accompli [ta parole], comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Et maintenant, Éternel, Dieu d’Israël, garde envers ton serviteur David, mon père, ce que tu lui as dit, disant: Tu ne manqueras pas, devant ma face, d’un homme assis sur le trône d’Israël, si seulement tes fils prennent garde à leur voie, pour marcher devant moi comme tu as marché devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Et maintenant, ô Dieu d’Israël, je te prie, que tes paroles, que tu as dites à ton serviteur David, mon père, soient fermes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Mais Dieu habitera-t-il vraiment sur la terre? Voici, les cieux, et les cieux des cieux, ne peuvent te contenir; combien moins cette maison que j’ai bâtie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Cependant, Éternel, mon Dieu, aie égard à la prière de ton serviteur et à sa supplication, pour écouter le cri et la prière que ton serviteur t’adresse aujourd’hui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'pour que tes yeux soient ouverts nuit et jour sur cette maison, sur le lieu dont tu as dit: Mon nom sera là, – pour écouter la prière que ton serviteur t’adressera [en se tournant] vers ce lieu-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Et écoute la supplication de ton serviteur et de ton peuple Israël, qu’ils t’adresseront [en se tournant] vers ce lieu-ci; toi, écoute dans le lieu de ton habitation, dans les cieux; écoute et pardonne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Si un homme pèche contre son prochain, et qu’on lui impose le serment pour le faire jurer, et que le serment vienne devant ton autel, dans cette maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'alors, toi, écoute dans les cieux, et agis, et juge tes serviteurs, en condamnant le méchant, pour faire retomber sa voie sur sa tête, et en justifiant le juste, en lui donnant selon sa justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Quand ton peuple Israël sera battu devant l’ennemi, parce qu’ils auront péché contre toi, s’ils retournent vers toi, et confessent ton nom, et te prient, et t’adressent leur supplication dans cette maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'alors, toi, écoute dans les cieux, et pardonne le péché de ton peuple Israël; et fais-les retourner dans la terre que tu as donnée à leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Quand les cieux seront fermés et qu’il n’y aura pas de pluie, parce qu’ils auront péché contre toi, s’ils prient [en se tournant] vers ce lieu-ci, et qu’ils confessent ton nom et reviennent de leur péché, parce que tu les auras affligés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'alors, toi, écoute dans les cieux, et pardonne le péché de tes serviteurs et de ton peuple Israël, quand tu leur auras enseigné le bon chemin dans lequel ils doivent marcher; et donne la pluie sur ton pays que tu as donné en héritage à ton peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'S’il y a famine dans le pays, s’il y a peste, s’il y a brûlure, rouille, sauterelles, locustes, si son ennemi l’assiège dans le pays de ses portes, quelque plaie, quelque maladie qu’il y ait,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'quelle que soit la prière, quelle que soit la supplication que fera un homme quelconque de tout ton peuple Israël, quand ils reconnaîtront chacun la plaie de son propre cœur et qu’ils étendront leurs mains vers cette maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'alors, toi, écoute dans les cieux, le lieu de ton habitation, et pardonne, et agis, et donne à chacun selon toutes ses voies, suivant que tu connais son cœur (car tu connais, toi seul, le cœur de tous les fils des hommes),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'afin qu’ils te craignent tous les jours qu’ils vivront sur la face de la terre que tu as donnée à nos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Et quant à l’étranger aussi, qui ne sera pas de ton peuple Israël, mais qui viendra d’un pays lointain à cause de ton nom');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(car ils entendront parler de ton grand nom, et de ta main forte, et de ton bras étendu), s’il vient et présente sa prière [en se tournant] vers cette maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'toi, écoute dans les cieux, le lieu de ton habitation, et agis selon tout ce que l’étranger réclamera de toi; afin que tous les peuples de la terre connaissent ton nom, [et] te craignent, comme ton peuple Israël, et qu’ils sachent que cette maison que j’ai bâtie est appelée de ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Lorsque ton peuple sortira pour la guerre contre son ennemi, par le chemin par lequel tu l’auras envoyé, et qu’ils prieront l’ Éternel, en se tournant vers la ville que tu as choisie et vers la maison que j’ai bâtie pour ton nom:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'alors, écoute dans les cieux leur prière et leur supplication, et fais-leur droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'S’ils ont péché contre toi (car il n’y a point d’homme qui ne pèche), et que tu te sois irrité contre eux, et que tu les aies livrés à l’ennemi, et qu’ils les aient emmenés captifs dans le pays de l’ennemi, loin ou près,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'et que, dans le pays où ils auront été emmenés captifs, ils rentrent en eux-mêmes, et reviennent [à toi] et te supplient, dans le pays de ceux qui les auront emmenés captifs, disant: Nous avons péché, et nous avons commis l’iniquité, nous avons agi méchamment;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'et s’ils reviennent à toi de tout leur cœur et de toute leur âme, dans le pays de leurs ennemis qui les ont emmenés captifs, et qu’ils te prient en se tournant vers leur pays, que tu as donné à leurs pères, vers la ville que tu as choisie et vers la maison que j’ai bâtie pour ton nom:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'alors, écoute dans les cieux, le lieu de ton habitation, leur prière et leur supplication, et fais-leur droit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'et pardonne à ton peuple ce en quoi ils ont péché contre toi, et toutes leurs transgressions qu’ils ont commises contre toi, et donne-leur de trouver compassion auprès de ceux qui les ont emmenés captifs, en sorte que ceux-ci aient compassion d’eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'car ils sont ton peuple et ton héritage, que tu as fait sortir d’Égypte, du milieu de la fournaise de fer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, '– tes yeux étant ouverts à la supplication de ton serviteur et à la supplication de ton peuple Israël, pour les entendre dans tout ce pour quoi ils crieront à toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'car tu les as mis à part [en les séparant] de tous les peuples de la terre pour être ton héritage, selon ce que tu as dit par ton serviteur Moïse, quand tu fis sortir d’Égypte nos pères, ô Seigneur Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Et il arriva que, quand Salomon eut achevé d’adresser à l’ Éternel toute cette prière et cette supplication, il se leva de devant l’autel de l’ Éternel, où il était à genoux, ses mains étendues vers les cieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'et il se tint debout et bénit à haute voix toute la congrégation d’Israël, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Béni soit l’ Éternel, qui a donné du repos à son peuple Israël, selon tout ce qu’il avait dit! Pas un mot de toute sa bonne parole qu’il prononça par Moïse, son serviteur, n’est tombé [à terre].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Que l’ Éternel, notre Dieu, soit avec nous comme il a été avec nos pères, (qu’il ne nous abandonne pas et ne nous délaisse pas)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'pour incliner nos cœurs vers lui, pour que nous marchions dans toutes ses voies et que nous gardions ses commandements et ses statuts et ses ordonnances, qu’il a commandés à nos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Et que ces miennes paroles, par lesquelles j’ai fait ma supplication devant l’ Éternel, soient présentes à l’ Éternel, notre Dieu, jour et nuit, pour qu’il fasse droit à son serviteur et droit à son peuple Israël, chaque jour selon que le cas le demande;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'afin que tous les peuples de la terre sachent que l’ Éternel, lui, est Dieu, qu’il n’y en a pas d’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Et que votre cœur soit parfait avec l’ Éternel, notre Dieu, pour marcher dans ses statuts et pour garder ses commandements, comme il en est aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Et le roi et tout Israël avec lui sacrifièrent des sacrifices devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Et Salomon offrit, pour le sacrifice de prospérités qu’il offrit à l’ Éternel, 22 000 bœufs et 120 000 moutons. Et le roi et tous les fils d’Israël firent la dédicace de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'En ce jour-là le roi sanctifia le milieu du parvis qui était devant la maison de l’ Éternel; car il offrit là l’holocauste, et l’offrande de gâteau, et la graisse des sacrifices de prospérités, parce que l’autel d’airain qui était devant l’ Éternel était trop petit pour recevoir l’holocauste, et l’offrande de gâteau, et la graisse des sacrifices de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Et en ce temps-là, Salomon et tout Israël avec lui, une grande congrégation, depuis l’entrée de Hamath jusqu’au torrent d’Égypte, célébrèrent la fête devant l’ Éternel, notre Dieu, sept jours, et sept jours: 14 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Le huitième jour, il renvoya le peuple; et ils bénirent le roi, et s’en allèrent à leurs tentes, joyeux et le cœur heureux à cause de tout le bien que l’ Éternel avait fait à David, son serviteur, et à Israël, son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, '*Et quand Salomon eut achevé de bâtir la maison de l’ Éternel et la maison du roi, et tout le désir de Salomon qu’il prit plaisir de faire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'il arriva que l’ Éternel apparut à Salomon une seconde fois, comme il lui était apparu à Gabaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Et l’ Éternel lui dit: J’ai entendu ta prière et la supplication que tu as faite devant moi; j’ai sanctifié cette maison que tu as bâtie, pour y mettre mon nom à jamais; et mes yeux et mon cœur seront toujours là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Et toi, si tu marches devant moi comme a marché David, ton père, d’un cœur parfait et en droiture, pour faire selon tout ce que je t’ai commandé, [et] si tu gardes mes statuts et mes ordonnances,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'j’affermirai le trône de ton royaume sur Israël à toujours, comme j’ai parlé à David, ton père, disant: Tu ne manqueras pas d’un homme sur le trône d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Si vous vous détournez de moi, vous et vos fils, et que vous ne gardiez pas mes commandements, mes statuts que j’ai mis devant vous, et que vous alliez et serviez d’autres dieux et vous prosterniez devant eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'je retrancherai Israël de dessus la face de la terre que je leur ai donnée; et la maison que j’ai sanctifiée pour mon nom, je la rejetterai de devant ma face; et Israël sera un proverbe et un sujet de raillerie parmi tous les peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Et cette maison, si haut élevée qu’elle soit, quiconque passera près d’elle sera étonné et sifflera; et on dira: Pourquoi l’ Éternel a-t-il fait ainsi à ce pays et à cette maison?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Et on dira: Parce qu’ils ont abandonné l’ Éternel, leur Dieu, qui fit sortir leurs pères du pays d’Égypte, et qu’ils se sont attachés à d’autres dieux, et se sont prosternés devant eux et les ont servis: c’est pourquoi l’ Éternel a fait venir sur eux tout ce mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, '*Et il arriva qu’au bout de 20 ans, lorsque Salomon eut bâti les deux maisons, la maison de l’ Éternel et la maison du roi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Hiram, roi de Tyr, ayant fourni Salomon de bois de cèdre, et de bois de cyprès, et d’or, selon tout son désir, alors le roi Salomon donna à Hiram 20 villes dans le pays de Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Et Hiram sortit de Tyr pour voir les villes que Salomon lui avait données, et elles ne lui plurent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Et il dit: Qu’est-ce que ces villes-là, que tu m’as données, mon frère? Et il les appela pays de Cabul, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Et Hiram envoya au roi 120 talents d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Et c’est ici ce qui concerne la levée que fit le roi Salomon pour bâtir la maison de l’ Éternel, et sa propre maison, et Millo, et la muraille de Jérusalem, et Hatsor, et Meguiddo, et Guézer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, '(Le Pharaon, roi d’Égypte, était monté et avait pris Guézer et l’avait brûlée au feu, et avait tué les Cananéens qui habitaient la ville, et l’avait donnée en présent à sa fille, femme de Salomon.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Et Salomon bâtit Guézer, et Beth-Horon la basse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'et Baalath, et Tadmor dans le désert, dans le pays,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'et toutes les villes à entrepôts qu’avait Salomon, et les villes pour les chars, et les villes pour la cavalerie, et ce que Salomon désira de bâtir à Jérusalem, et au Liban, et dans tout le pays de sa domination.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, '– Tout le peuple qui restait des Amoréens, des Héthiens, des Phéréziens, des Héviens, et des Jébusiens, qui n’étaient pas des fils d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, '– leurs fils qui étaient restés après eux dans le pays [et] que les fils d’Israël n’avaient pu détruire, Salomon les assujettit aux levées pour servir, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Mais des fils d’Israël, Salomon n’en fit pas des esclaves; car ils étaient hommes de guerre, et ses serviteurs, et ses chefs, et ses capitaines, et chefs de ses chars et de sa cavalerie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'C’est ici [le nombre] des chefs des intendants qui étaient [établis] sur l’ouvrage de Salomon: 550, qui avaient autorité sur le peuple qui faisait l’ouvrage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Mais la fille du Pharaon monta de la ville de David dans sa maison, qu’il avait bâtie pour elle: alors il bâtit Millo.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Et Salomon offrait trois fois par an des holocaustes et des sacrifices de prospérités sur l’autel qu’il avait bâti pour l’ Éternel, et il faisait fumer l’encens sur celui qui était devant l’ Éternel. Et il acheva la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Et le roi Salomon fit une flotte, à Étsion-Guéber, qui est près d’Éloth, sur le bord de la mer Rouge, dans le pays d’Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Et Hiram envoya sur la flotte ses serviteurs, des matelots connaissant la mer, avec les serviteurs de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Et ils allèrent à Ophir, et y prirent de l’or, 420 talents, et les apportèrent au roi Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, '*Et la reine de Sheba entendit parler de la renommée de Salomon, en relation avec le nom de l’ Éternel, et elle vint pour l’éprouver par des énigmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Et elle vint à Jérusalem avec un fort grand train, avec des chameaux qui portaient des aromates, et de l’or en très grande quantité, et des pierres précieuses; et elle vint vers Salomon et lui parla de tout ce qu’elle avait sur son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Et Salomon lui expliqua toutes les choses dont elle parlait: il n’y eut pas une chose cachée pour le roi, [pas une chose] qu’il ne lui explique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Et la reine de Sheba vit toute la sagesse de Salomon, et la maison qu’il avait bâtie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'et les mets de sa table, et la tenue de ses serviteurs, et l’ordre de service de ses officiers, et leurs vêtements, et ses échansons, et la rampe par laquelle il montait dans la maison de l’ Éternel, et il n’y eut plus d’esprit en elle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'et elle dit au roi: Ce que j’ai entendu dire dans mon pays sur tout ton état et sur ta sagesse, était la vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'mais je n’ai pas cru ces choses, jusqu’à ce que je sois venue et que mes yeux aient vu; et voici, on ne m’avait pas rapporté la moitié; tu surpasses en sagesse et en prospérité la rumeur que j’en ai entendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Heureux tes gens, heureux ceux-ci, tes serviteurs, qui se tiennent continuellement devant toi, et qui entendent ta sagesse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Béni soit l’ Éternel, ton Dieu, qui a pris plaisir en toi pour te placer sur le trône d’Israël! Parce que l’ Éternel aimait Israël à toujours, il t’a établi roi pour faire droit et justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Et elle donna au roi 120 talents d’or, et des aromates en très grande quantité, et des pierres précieuses. Il n’est plus venu une abondance d’aromates pareille à ce que la reine de Sheba en donna au roi Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, '(La flotte aussi de Hiram qui amenait de l’or d’Ophir, apporta d’Ophir du bois d’almuggim en très grande quantité, et des pierres précieuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Et, avec le bois d’almuggim, le roi fit des balustrades pour la maison de l’ Éternel et pour la maison du roi, et des harpes et des luths pour les chanteurs. Il n’est pas venu de semblable bois d’almuggim, et on n’en a pas vu jusqu’à ce jour.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Et le roi Salomon donna à la reine de Sheba tout son désir, [tout ce] qu’elle demanda, outre ce qu’il lui donna selon le pouvoir du roi Salomon. Et elle s’en retourna, et s’en alla dans son pays, elle et ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, '*Et le poids de l’or qui arrivait à Salomon dans une année était de 666 talents d’or,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'outre [ce qui lui venait] des commerçants ambulants et du trafic des marchands, et de tous les rois de l’Arabie, et des gouverneurs du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Et le roi Salomon fit 200 grands boucliers d’or battu, mettant à chaque bouclier 600 [sicles] d’or,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'et 300 petits boucliers d’or battu, mettant à chaque bouclier trois mines d’or; et le roi les mit dans la maison de la forêt du Liban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Et le roi fit un grand trône d’ivoire, et le recouvrit d’or affiné:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'le trône avait six degrés, et le haut du trône par-derrière était arrondi; et il y avait des bras d’un côté et de l’autre à l’endroit du siège, et deux lions qui se tenaient à côté des bras,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'et douze lions qui se tenaient là sur les six degrés, d’un côté et de l’autre: il ne s’en était point fait de pareil dans aucun royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Et tous les vases à boire du roi Salomon étaient d’or, et tous les vases de la maison de la forêt du Liban, d’or pur: aucun n’était d’argent, il n’était compté pour rien aux jours de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Car la flotte de Tarsis qu’avait le roi, tenait la mer avec la flotte de Hiram; une fois tous les trois ans la flotte de Tarsis venait, apportant de l’or et de l’argent, de l’ivoire, et des singes et des paons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Et le roi Salomon fut plus grand que tous les rois de la terre, en richesse et en sagesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Et toute la terre recherchait la face de Salomon, pour entendre sa sagesse, que Dieu avait mise dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Et ils apportaient chacun son présent: des vases d’argent et des vases d’or, et des vêtements, et des armes, et des aromates, des chevaux et des mulets: chaque année le tribut de l’année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Et Salomon rassembla des chars et des cavaliers; et il eut 1 400 chars, et 12 000 cavaliers; et il les plaça dans les villes à chars et auprès du roi à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Et le roi fit que l’argent, dans Jérusalem, était comme les pierres, et il fit que les cèdres étaient, en quantité, comme les sycomores qui sont dans le pays plat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Et quant aux chevaux de Salomon, il les tirait d’Égypte: une caravane de marchands du roi prenait un convoi [de chevaux] pour un certain prix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'et un char montait et sortait d’Égypte pour 600 [sicles] d’argent, et un cheval pour 150; et on en faisait venir ainsi, par leur main, pour tous les rois des Héthiens et pour les rois de Syrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, '*Mais le roi Salomon aima beaucoup de femmes étrangères, outre la fille du Pharaon: des Moabites, des Ammonites, des Édomites, des Sidoniennes, des Héthiennes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, '– d’entre les nations dont l’ Éternel avait dit aux fils d’Israël: Vous n’entrerez pas vers elles, et elles ne viendront pas vers vous; certainement elles détourneraient vos cœurs après leurs dieux; Salomon s’attacha à elles par amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Et il avait 700 femmes princesses, et 300 concubines; et ses femmes détournèrent son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Et il arriva, au temps de la vieillesse de Salomon, que ses femmes détournèrent son cœur après d’autres dieux, et son cœur ne fut pas parfait avec l’ Éternel, son Dieu, comme le cœur de David, son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Et Salomon alla après Ashtoreth, la divinité des Sidoniens, et après Milcom, l’abomination des Ammonites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Et Salomon fit ce qui est mauvais aux yeux de l’ Éternel, et ne suivit pas pleinement l’ Éternel, comme David, son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Alors Salomon bâtit un haut lieu pour Kemosh, l’abomination de Moab, sur la montagne qui est vis-à-vis de Jérusalem, et pour Moloc, l’abomination des fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Et il en fit ainsi pour toutes ses femmes étrangères, qui brûlaient de l’encens et sacrifiaient à leurs dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Et l’ Éternel eut de la colère contre Salomon, parce que son cœur s’était détourné de l’ Éternel, le Dieu d’Israël, qui s’était révélé à lui deux fois,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'et lui avait commandé, à ce sujet, de ne pas aller après d’autres dieux, et il ne garda pas ce que l’ Éternel lui avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Et l’ Éternel dit à Salomon: Parce que tu as fait cela, et que tu n’as pas gardé mon alliance et mes statuts, que je t’ai commandés, je t’arracherai certainement le royaume, et je le donnerai à ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Seulement, je ne le ferai pas dans tes jours, à cause de David, ton père; [mais] je l’arracherai de la main de ton fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Toutefois je ne [lui] arracherai pas tout le royaume; je donnerai une tribu à ton fils, à cause de David, mon serviteur, et à cause de Jérusalem, que j’ai choisie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Et l’ Éternel suscita un adversaire à Salomon, Hadad, l’Édomite: il était de la semence royale en Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Et il était arrivé, pendant que David était en Édom [et] que Joab, chef de l’armée, était monté pour enterrer les morts, car il avait frappé tout mâle en Édom');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(or Joab resta là six mois avec tout Israël, jusqu’à ce qu’il ait retranché tous les mâles en Édom),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'qu’Hadad s’enfuit, lui et quelques Édomites d’entre les serviteurs de son père avec lui, pour aller en Égypte; et Hadad était un jeune garçon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Et ils se levèrent de Madian et vinrent à Paran; et ils prirent des hommes avec eux de Paran, et vinrent en Égypte vers le Pharaon, roi d’Égypte, qui lui donna une maison, et lui assigna des provisions, et lui donna des terres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Et Hadad trouva grande faveur aux yeux du Pharaon, et [le Pharaon] lui donna pour femme la sœur de sa femme, la sœur de la reine Thakhpenès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Et la sœur de Thakhpenès lui enfanta Guenubath, son fils, et Thakhpenès le sevra dans la maison du Pharaon; et Guenubath était dans la maison du Pharaon, parmi les fils du Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Et Hadad apprit en Égypte que David s’était endormi avec ses pères, et que Joab, chef de l’armée, était mort; et Hadad dit au Pharaon: Laisse-moi aller, et j’irai dans mon pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Et le Pharaon lui dit: Que te manque-t-il auprès de moi, que voici, tu désires de t’en aller dans ton pays? Et il dit: Rien, mais quoi qu’il en soit, laisse-moi aller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Dieu lui suscita encore un adversaire, Rezon, fils d’Éliada, qui s’enfuit de chez Hadadézer, roi de Tsoba, son seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'et il rassembla des hommes auprès de lui, et devint chef de bande, lorsque David tua ceux [de Tsoba]. Et ils s’en allèrent à Damas, et y demeurèrent, et ils régnèrent à Damas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Et il fut l’adversaire d’Israël tous les jours de Salomon, outre le mal que [fit] Hadad; et il détesta Israël, et régna sur la Syrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Et Jéroboam, fils de Nebath, Éphratien de Tseréda, serviteur de Salomon (et le nom de sa mère, une femme veuve, était Tserua), leva aussi sa main contre le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Et c’est ici l’occasion pour laquelle il leva sa main contre le roi: Salomon bâtissait Millo, [et] fermait la brèche de la ville de David, son père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'et Jéroboam était un fort et vaillant homme; et Salomon vit que le jeune homme faisait de l’ouvrage, et le préposa sur tout le travail de la maison de Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Et il arriva en ce temps-là que Jéroboam sortit de Jérusalem; et Akhija, le Silonite, le prophète, le trouva sur le chemin, et il était revêtu d’un manteau neuf, et ils étaient seuls, eux deux, dans les champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Et Akhija saisit le manteau neuf qu’il avait sur lui, et le déchira en douze morceaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Et il dit à Jéroboam: Prends dix morceaux pour toi; car ainsi dit l’ Éternel, le Dieu d’Israël: Voici, j’arrache le royaume de la main de Salomon, et je te donne dix tribus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'mais une tribu sera à lui, à cause de mon serviteur David, et à cause de Jérusalem, la ville que j’ai choisie d’entre toutes les tribus d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'parce qu’ils m’ont abandonné, et ont adoré Ashtoreth, la divinité des Sidoniens, Kemosh, le dieu de Moab, et Milcom, le dieu des fils d’Ammon, et n’ont pas marché dans mes voies pour pratiquer ce qui est droit à mes yeux, et mes statuts et mes ordonnances, comme David, son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Cependant je n’ôterai pas tout le royaume de sa main, car je l’établirai prince tous les jours de sa vie, à cause de David, mon serviteur, que j’ai choisi, qui gardait mes commandements et mes statuts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'mais j’ôterai le royaume de la main de son fils, et je te le donnerai, [savoir] dix tribus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'et je donnerai une tribu à son fils, afin qu’il y ait toujours une lampe pour David, mon serviteur, devant moi, à Jérusalem, la ville que je me suis choisie pour y placer mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Et je te prendrai, et tu régneras sur tout ce que ton âme désire, et tu seras roi sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Et si tu écoutes tout ce que je te commanderai, et si tu marches dans mes voies et que tu fasses ce qui est droit à mes yeux, en gardant mes statuts et mes commandements, comme a fait David, mon serviteur, alors je serai avec toi, et je te bâtirai une maison stable, comme je l’ai bâtie pour David, et je te donnerai Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Et j’humilierai la semence de David, à cause de cela, seulement pas à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Et Salomon chercha à faire mourir Jéroboam; et Jéroboam se leva et s’enfuit en Égypte, vers Shishak, roi d’Égypte; et il fut en Égypte jusqu’à la mort de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Et le reste des actes de Salomon, et tout ce qu’il fit, et sa sagesse, cela n’est-il pas écrit dans le livre des actes de Salomon?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Et les jours que Salomon régna à Jérusalem sur tout Israël furent 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Et Salomon s’endormit avec ses pères, et fut enterré dans la ville de David, son père; et Roboam, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, '*Et Roboam alla à Sichem, car tout Israël était venu à Sichem pour le faire roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Et quand Jéroboam, fils de Nebath, l’apprit (il était encore en Égypte, où il s’était enfui de devant le roi Salomon, et Jéroboam habitait l’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'et ils envoyèrent et l’appelèrent), il arriva que Jéroboam et toute la congrégation d’Israël vinrent et parlèrent à Roboam, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Ton père a rendu notre joug dur; et toi, maintenant, allège le dur service de ton père et son joug pesant qu’il a mis sur nous, et nous te servirons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Et il leur dit: Allez-vous-en encore pour trois jours, et revenez vers moi. Et le peuple s’en alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Et le roi Roboam tint conseil avec les vieillards qui s’étaient tenus devant Salomon, son père, lorsqu’il vivait, disant: Comment conseillez-vous de répondre à ce peuple?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Et ils lui parlèrent, disant: Si aujourd’hui tu deviens serviteur de ce peuple, et que tu les serves, et leur répondes, et leur dises de bonnes paroles, ils seront toujours tes serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Mais il laissa le conseil des vieillards, qu’ils lui avaient donné, et tint conseil avec les jeunes gens qui avaient grandi avec lui, qui se tenaient devant lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'et il leur dit: Que conseillez-vous que nous répondions à ce peuple, qui m’a parlé, disant: Allège le joug que ton père a mis sur nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Et les jeunes gens qui avaient grandi avec lui, lui parlèrent, disant: Tu diras ainsi à ce peuple qui t’a parlé, disant: Ton père a rendu pesant notre joug; toi, allège-le de dessus nous; – tu leur diras ainsi: Mon petit doigt est plus gros que les reins de mon père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'et maintenant, mon père a chargé sur vous un joug pesant, et moi j’ajouterai à votre joug; mon père vous a corrigés avec des fouets, et moi je vous corrigerai avec des scorpions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Et Jéroboam et tout le peuple vinrent vers Roboam le troisième jour, comme le roi avait dit, en disant: Revenez vers moi le troisième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Et le roi répondit au peuple avec dureté, et laissa le conseil que les vieillards lui avaient donné;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'et il leur parla selon le conseil des jeunes gens, disant: Mon père a rendu pesant votre joug, et moi j’ajouterai à votre joug; mon père vous a corrigés avec des fouets, et moi je vous corrigerai avec des scorpions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Et le roi n’écouta pas le peuple, car cela était amené par l’ Éternel, afin d’accomplir sa parole, que l’ Éternel avait dite par Akhija, le Silonite, à Jéroboam, fils de Nebath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Et tout Israël vit que le roi ne les avait pas écoutés. Et le peuple répondit au roi, disant: Quelle part avons-nous en David? Et nous n’avons pas d’héritage dans le fils d’Isaï. À tes tentes, Israël! Maintenant, David, regarde à ta maison! Et Israël s’en alla à ses tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Mais quant aux fils d’Israël qui habitaient dans les villes de Juda, Roboam régna sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Et le roi Roboam envoya Adoram, qui était préposé sur les levées; et tout Israël le lapida avec des pierres, et il mourut. Et le roi Roboam se hâta de monter sur un char pour s’enfuir à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Et Israël se rebella contre la maison de David, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Et il arriva que, quand tout Israël apprit que Jéroboam était de retour, ils envoyèrent et l’appelèrent à l’assemblée, et l’établirent roi sur tout Israël. Il n’y eut que la tribu de Juda seule qui suive la maison de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Et Roboam s’en alla à Jérusalem. Et il assembla toute la maison de Juda, et la tribu de Benjamin, 180 000 hommes d’élite propres à la guerre, pour faire la guerre à la maison d’Israël, afin de ramener le royaume à Roboam, fils de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Et la parole de Dieu vint à Shemahia, homme de Dieu, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Parle à Roboam, fils de Salomon, roi de Juda, et à toute la maison de Juda et de Benjamin, et au reste du peuple, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Ainsi dit l’ Éternel: Ne montez pas, et ne faites pas la guerre à vos frères, les fils d’Israël; retournez chacun à sa maison, car c’est de par moi que cette chose a eu lieu. Et ils écoutèrent la parole de l’ Éternel, et s’en retournèrent pour s’en aller, selon la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, '*Et Jéroboam bâtit Sichem dans la montagne d’Éphraïm, et y habita; et il sortit de là, et bâtit Penuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Et Jéroboam dit en son cœur: Maintenant le royaume retournera à la maison de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Si ce peuple monte pour offrir des sacrifices dans la maison de l’ Éternel à Jérusalem, le cœur de ce peuple retournera à son seigneur, à Roboam, roi de Juda, et ils me tueront, et ils retourneront à Roboam, roi de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Et le roi prit conseil, et fit deux veaux d’or, et dit au peuple: C’est trop pour vous de monter à Jérusalem; voici tes dieux, Israël! qui t’ont fait monter du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Et il en mit un à Béthel, et l’autre il le plaça à Dan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Et cela devint un péché, et le peuple alla devant l’un [des veaux] jusqu’à Dan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Et il fit une maison de hauts lieux, et établit des sacrificateurs d’entre toutes les classes du peuple, lesquels n’étaient pas des fils de Lévi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Et Jéroboam établit une fête au huitième mois, le quinzième jour du mois, comme la fête qui [avait lieu] en Juda; et il offrit sur l’autel. Il fit ainsi à Béthel, sacrifiant aux veaux qu’il avait faits, et il plaça à Béthel les sacrificateurs des hauts lieux qu’il avait établis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Et il offrit sur l’autel qu’il avait fait à Béthel, le quinzième jour du huitième mois, le mois qu’il avait imaginé dans son propre cœur; et il fit une fête pour les fils d’Israël, et offrit sur l’autel, faisant fumer l’encens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Et voici, un homme de Dieu vint de Juda, par la parole de l’ Éternel, à Béthel, et Jéroboam se tenait près de l’autel pour faire fumer l’encens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Et il cria contre l’autel, par la parole de l’ Éternel, et dit: Autel, autel! ainsi dit l’ Éternel: Voici, un fils naîtra à la maison de David; son nom sera Josias, et il offrira sur toi les sacrificateurs des hauts lieux qui font fumer de l’encens sur toi, et on brûlera sur toi des ossements d’hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Et il donna en ce même jour un signe, disant: C’est ici le signe que l’ Éternel a parlé: Voici, l’autel se fendra, et la cendre qui est dessus sera répandue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Et il arriva, comme le roi entendait la parole de l’homme de Dieu qu’il cria contre l’autel de Béthel, que Jéroboam étendit sa main de dessus l’autel, disant: Saisissez-le! Et sa main, qu’il avait étendue contre lui, sécha, et il ne put la ramener à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Et l’autel se fendit et la cendre fut répandue de dessus l’autel, selon le signe que l’homme de Dieu avait donné par la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Et le roi répondit et dit à l’homme de Dieu: Implore, je te prie, l’ Éternel, ton Dieu, et prie pour moi, afin que ma main me soit rendue. Et l’homme de Dieu implora l’ Éternel, et la main du roi lui fut rendue et fut comme auparavant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Et le roi dit à l’homme de Dieu: Viens avec moi à la maison, et rafraîchis-toi, et je te donnerai un présent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Et l’homme de Dieu dit au roi: Quand tu me donnerais la moitié de ta maison, je n’irais pas avec toi; et je ne mangerai pas de pain et je ne boirai pas d’eau dans ce lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Car il m’est ainsi commandé par la parole de l’ Éternel, disant: Tu ne mangeras pas de pain, et tu ne boiras pas d’eau, et tu ne t’en retourneras point par le chemin par lequel tu es allé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Et il s’en alla par un autre chemin; il ne s’en retourna point par le chemin par lequel il était venu à Béthel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Et un certain vieux prophète habitait Béthel; et ses fils vinrent et lui racontèrent toute l’œuvre que l’homme de Dieu avait faite ce jour-là à Béthel; les paroles qu’il avait dites au roi, ils les rapportèrent aussi à leur père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Et leur père leur dit: Par quel chemin s’en est-il allé? Et ses fils avaient vu le chemin par lequel s’en était allé l’homme de Dieu qui venait de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Et il dit à ses fils: Sellez-moi l’âne; et ils lui sellèrent l’âne, et il monta dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Et il s’en alla après l’homme de Dieu, et le trouva assis sous un térébinthe; et il lui dit: Es-tu l’homme de Dieu qui est venu de Juda? Et il dit: C’est moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Et il lui dit: Viens avec moi à la maison, et mange du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Et il dit: Je ne puis retourner avec toi ni entrer avec toi, et je ne mangerai pas de pain et je ne boirai pas d’eau avec toi dans ce lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Car il m’a été dit par la parole de l’ Éternel: Tu n’y mangeras pas de pain, et tu n’y boiras pas d’eau; tu ne retourneras pas, en t’en allant, par le chemin par lequel tu es venu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Et il lui dit: Moi aussi je suis prophète comme toi, et un ange m’a parlé par la parole de l’ Éternel, disant: Fais-le revenir avec toi à ta maison, et qu’il mange du pain et boive de l’eau. Il lui mentait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Et il retourna avec lui, et mangea du pain dans sa maison, et but de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Et il arriva, comme ils étaient assis à table, que la parole de l’ Éternel vint au prophète qui l’avait ramené;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'et il cria à l’homme de Dieu qui était venu de Juda, disant: Ainsi dit l’ Éternel: Parce que tu as été rebelle à la parole de l’ Éternel, et que tu n’as pas gardé le commandement que l’ Éternel, ton Dieu, t’avait commandé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'et que tu es retourné, et que tu as mangé du pain et que tu as bu de l’eau dans le lieu dont il t’avait dit: Tu n’y mangeras pas de pain et tu n’y boiras pas d’eau, ton cadavre n’entrera pas dans le sépulcre de tes pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Et après qu’il eut mangé du pain et après qu’il eut bu, il arriva qu’il sella l’âne pour lui, pour le prophète qu’il avait ramené.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Et il s’en alla; et un lion le trouva sur le chemin, et le tua. Et son cadavre était jeté sur le chemin, et l’âne se tenait à côté de lui, le lion aussi se tenait à côté du cadavre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Et voici, des hommes passaient, et ils virent le cadavre jeté sur le chemin, et le lion se tenant à côté du cadavre; et ils vinrent et le dirent dans la ville dans laquelle habitait le vieux prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Et le prophète qui l’avait ramené du chemin l’apprit, et il dit: C’est l’homme de Dieu qui a été rebelle à la parole de l’ Éternel, et l’ Éternel l’a livré au lion qui l’a déchiré et l’a tué, selon la parole de l’ Éternel qu’il lui avait dite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Et il parla à ses fils, disant: Sellez-moi l’âne; et ils le sellèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Et il s’en alla, et trouva le cadavre jeté sur le chemin, et l’âne et le lion se tenant à côté du cadavre; le lion n’avait pas mangé le cadavre ni déchiré l’âne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Et le prophète releva le cadavre de l’homme de Dieu, et le mit sur l’âne, et le ramena; et le vieux prophète entra dans la ville pour mener deuil, et pour l’enterrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Et il déposa son cadavre dans son propre sépulcre – et on mena deuil sur lui, – [disant]: Hélas, mon frère!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Et, après l’avoir enterré, il parla à ses fils, disant: Quand je mourrai, vous m’enterrerez dans le sépulcre où l’homme de Dieu est enterré; placez mes os à côté de ses os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Car la parole qu’il a criée, par la parole de l’ Éternel, contre l’autel qui est à Béthel et contre toutes les maisons des hauts lieux qui sont dans les villes de Samarie, arrivera certainement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Après cela, Jéroboam ne revint pas de sa mauvaise voie; et il établit encore, d’entre toutes les classes du peuple, des sacrificateurs des hauts lieux. Quiconque le désirait, il le consacrait, et il devenait sacrificateur des hauts lieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Et par cela il y eut du péché sur la maison de Jéroboam, pour l’exterminer et pour la détruire de dessus la face de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Dans ce temps-là, Abija, fils de Jéroboam, fut malade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Et Jéroboam dit à sa femme: Lève-toi, je te prie, et déguise-toi, et qu’on ne sache pas que tu es la femme de Jéroboam, et va-t’en à Silo; voici, là est Akhija, le prophète, qui a dit de moi que je serais roi sur ce peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Et tu prendras avec toi dix pains, et des gâteaux, et une cruche de miel, et tu iras vers lui; il te dira ce qui arrivera à l’enfant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Et la femme de Jéroboam fit ainsi, et elle se leva et s’en alla à Silo, et vint à la maison d’Akhija. Et Akhija ne pouvait voir, car ses yeux étaient fixes à cause de son âge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Et l’ Éternel dit à Akhija: Voici, la femme de Jéroboam vient te demander quelque chose au sujet de son fils, car il est malade; tu lui diras ainsi et ainsi; et il arrivera, quand elle viendra, qu’elle feindra d’être une autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Et il arriva, quand Akhija entendit le bruit de ses pieds, que, comme elle entrait par la porte, il dit: Entre, femme de Jéroboam, pourquoi feins-tu d’être une autre? Or je suis envoyé vers toi [pour t’annoncer] des choses dures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Va, dis à Jéroboam: Ainsi dit l’ Éternel, le Dieu d’Israël: Parce que je t’ai élevé du milieu du peuple, et que je t’ai établi prince sur mon peuple Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'et que j’ai arraché le royaume de la maison de David, et que je te l’ai donné, et que tu n’as pas été comme mon serviteur David, qui gardait mes commandements et marchait après moi de tout son cœur pour ne faire que ce qui est droit à mes yeux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'mais que tu as fait ce qui est mauvais, plus que tous ceux qui ont été avant toi, et que tu es allé et t’es fait d’autres dieux et des images de fonte pour me provoquer à colère, et que tu m’as jeté derrière ton dos,...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'à cause de cela, voici, je vais faire venir du mal sur la maison de Jéroboam, et je retrancherai de Jéroboam tous les mâles, l’homme lié et l’homme libre en Israël, et j’ôterai la maison de Jéroboam comme on ôte le fumier, jusqu’à ce qu’il n’en reste plus rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Celui de [la maison de] Jéroboam qui mourra dans la ville, les chiens le mangeront, et celui qui mourra dans les champs, les oiseaux des cieux le mangeront, car l’ Éternel a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Et toi, lève-toi, va-t’en dans ta maison: quand tes pieds entreront dans la ville, l’enfant mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Et tout Israël mènera deuil sur lui et l’enterrera; car celui-ci seul, de [la maison de] Jéroboam, entrera dans le sépulcre, parce qu’en lui [seul], dans la maison de Jéroboam, a été trouvé quelque chose d’agréable à l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Et l’ Éternel suscitera pour lui-même un roi sur Israël, qui retranchera la maison de Jéroboam ce jour-là;... mais quoi?... déjà maintenant!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Et l’ Éternel frappera Israël comme quand le roseau est agité dans les eaux; et il arrachera Israël de dessus cette bonne terre qu’il donna à leurs pères, et il les dispersera au-delà du fleuve, parce qu’ils se sont fait des ashères, provoquant l’ Éternel à la colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Et il livrera Israël à cause des péchés de Jéroboam, qu’il a commis et par lesquels il a fait pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Et la femme de Jéroboam se leva et s’en alla, et vint à Thirtsa: comme elle arrivait sur le seuil de la maison, l’enfant mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Et on l’enterra, et tout Israël mena deuil sur lui, selon la parole de l’ Éternel, qu’il avait dite par son serviteur Akhija, le prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Et le reste des actes de Jéroboam, comment il fit la guerre, et comment il régna, voici, cela est écrit dans le livre des chroniques des rois d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Et les jours que Jéroboam régna furent 22 ans. Et il s’endormit avec ses pères, et Nadab, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, '*Et Roboam, fils de Salomon, régna sur Juda. Roboam était âgé de 41 ans lorsqu’il commença de régner; et il régna 17 ans à Jérusalem, la ville que l’ Éternel avait choisie d’entre toutes les tribus d’Israël pour y mettre son nom; et le nom de sa mère était Naama, une Ammonite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Et Juda fit ce qui est mauvais aux yeux de l’ Éternel; et ils le provoquèrent à la jalousie plus que tout ce que leurs pères avaient fait par leurs péchés qu’ils commirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Et ils bâtirent, eux aussi, pour eux-mêmes, des hauts lieux, et des statues, et des ashères, sur toute haute colline et sous tout arbre vert;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'il y avait aussi dans le pays des hommes voués à la prostitution. Ils firent selon toutes les abominations des nations que l’ Éternel avait dépossédées devant les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Et il arriva, en la cinquième année du roi Roboam, que Shishak, roi d’Égypte, monta contre Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Et il prit les trésors de la maison de l’ Éternel et les trésors de la maison du roi: il prit tout. Et il prit tous les boucliers d’or que Salomon avait faits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Et le roi Roboam fit à leur place des boucliers d’airain, et les confia aux mains des chefs des coureurs qui gardaient l’entrée de la maison du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Et toutes les fois que le roi entrait dans la maison de l’ Éternel, il arrivait que les coureurs les portaient, puis ils les rapportaient dans la chambre des coureurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Et le reste des actes de Roboam, et tout ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Et il y eut guerre entre Roboam et Jéroboam, tous [leurs] jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Et Roboam s’endormit avec ses pères, et il fut enterré avec ses pères dans la ville de David; et le nom de sa mère était Naama, une Ammonite. Et Abijam, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Et la dix-huitième année du roi Jéroboam, fils de Nebath, Abijam commença de régner sur Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Il régna trois ans à Jérusalem; et le nom de sa mère était Maaca, fille d’Abishalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Et il marcha dans tous les péchés de son père, que celui-ci avait pratiqués avant lui; et son cœur ne fut pas parfait avec l’ Éternel, son Dieu, comme le cœur de David, son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Toutefois, à cause de David, l’ Éternel, son Dieu, lui donna une lampe à Jérusalem, établissant son fils après lui, et faisant subsister Jérusalem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'parce que David avait fait ce qui est droit aux yeux de l’ Éternel, et ne s’était détourné de rien de ce qu’il lui avait commandé, tous les jours de sa vie, excepté dans l’affaire d’Urie, le Héthien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Et il y eut guerre entre Roboam et Jéroboam, tous les jours de sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Et le reste des actes d’Abijam, et tout ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda? Et il y eut guerre entre Abijam et Jéroboam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Et Abijam s’endormit avec ses pères, et on l’enterra dans la ville de David; et Asa, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Et en la vingtième année de Jéroboam, roi d’Israël, Asa commença de régner sur Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'et il régna 41 ans à Jérusalem; et le nom de sa mère était Maaca, fille d’Abishalom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Et Asa fit ce qui est droit aux yeux de l’ Éternel, comme David, son père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'et il fit disparaître du pays les hommes voués à la prostitution, et ôta toutes les idoles que ses pères avaient faites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Et même à Maaca, sa mère, il ôta sa position de reine, parce qu’elle avait fait un simulacre pour Ashère; et Asa abattit son simulacre, et le brûla dans la vallée du Cédron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Mais les hauts lieux ne furent pas ôtés; cependant le cœur d’Asa fut parfait avec l’ Éternel, tous ses jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Et il apporta dans la maison de l’ Éternel les choses saintes de son père et les choses que lui-même avait consacrées, de l’argent, et de l’or, et des ustensiles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Et il y eut guerre entre Asa et Baësha, roi d’Israël, tous leurs jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Et Baësha, roi d’Israël, monta contre Juda; et il bâtit Rama, afin de ne permettre à personne de sortir de chez Asa, roi de Juda, ou d’entrer vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Et Asa prit tout l’argent et l’or qui restaient dans les trésors de la maison de l’ Éternel et dans les trésors de la maison du roi, et les mit entre les mains de ses serviteurs; et le roi Asa les envoya à Ben-Hadad, fils de Tabrimmon, fils de Hézion, roi de Syrie, qui habitait à Damas, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Il y a alliance entre moi et toi, entre mon père et ton père; voici, je t’envoie un présent d’argent et d’or: va, romps ton alliance avec Baësha, roi d’Israël, afin qu’il s’en aille d’auprès de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Et Ben-Hadad écouta le roi Asa, et envoya les chefs de ses troupes contre les villes d’Israël, et il frappa Ijon, et Dan, et Abel-Beth-Maaca, et tout Kinneroth avec tout le pays de Nephthali.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Et il arriva, quand Baësha l’apprit, qu’il se désista de bâtir Rama, et il habita à Thirtsa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Et le roi Asa convoqua tout Juda; personne n’était exempté; et ils emportèrent les pierres de Rama, et les bois avec lesquels Baësha bâtissait; et le roi Asa en bâtit Guéba de Benjamin et Mitspa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Et le reste de tous les actes d’Asa, et toute sa puissance, et tout ce qu’il fit, et les villes qu’il bâtit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda? Seulement, au temps de sa vieillesse, il fut malade des pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Et Asa s’endormit avec ses pères; et il fut enterré avec ses pères dans la ville de David, son père; et Josaphat, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, '*Et Nadab, fils de Jéroboam, commença de régner sur Israël la seconde année d’Asa, roi de Juda; et il régna sur Israël deux ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, et marcha dans la voie de son père et dans son péché par lequel il avait fait pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Et Baësha, fils d’Akhija, de la maison d’Issacar, conspira contre lui; et Baësha le frappa à Guibbethon, qui était aux Philistins, pendant que Nadab et tout Israël assiégeaient Guibbethon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Et Baësha le mit à mort la troisième année d’Asa, roi de Juda, et régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Et il arriva que, quand il fut roi, il frappa toute la maison de Jéroboam; il ne laissa de Jéroboam personne qui respire, jusqu’à ce qu’il ait détruit sa maison selon la parole de l’ Éternel qu’il avait dite par son serviteur Akhija, le Silonite,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'à cause des péchés de Jéroboam, qu’il avait commis et par lesquels il avait fait pécher Israël, par sa provocation par laquelle il avait provoqué l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Et le reste des actes de Nadab, et tout ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Et il y eut guerre entre Asa et Baësha, roi d’Israël, tous leurs jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'La troisième année d’Asa, roi de Juda, Baësha, fils d’Akhija, commença de régner sur tout Israël, à Thirtsa, [et il régna] 24 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, et marcha dans la voie de Jéroboam, et dans son péché par lequel il avait fait pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Et la parole de l’ Éternel vint à Jéhu, fils de Hanani, contre Baësha, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Parce que je t’ai élevé de la poussière, et que je t’ai établi prince sur mon peuple Israël, et que tu as marché dans la voie de Jéroboam, et que tu as fait pécher mon peuple Israël, pour qu’ils me provoquent par leurs péchés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'voici, j’ôterai Baësha et sa maison; et je ferai de ta maison comme [j’ai fait] de la maison de Jéroboam, fils de Nebath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Celui de [la maison de] Baësha qui mourra dans la ville, les chiens le mangeront, et celui de sa [maison] qui mourra dans les champs, les oiseaux des cieux le mangeront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Et le reste des actes de Baësha, et ce qu’il fit, et sa puissance, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Et Baësha s’endormit avec ses pères, et il fut enterré à Thirtsa; et Éla, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Et par Jéhu, fils de Hanani, le prophète, la parole de l’ Éternel vint aussi contre Baësha, et contre sa maison, à cause de tout le mal qu’il faisait devant les yeux de l’ Éternel, pour le provoquer à colère par l’œuvre de ses mains, pour qu’il soit comme la maison de Jéroboam, et parce qu’il tua celui-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'La vingt -sixième année d’Asa, roi de Juda, Éla, fils de Baësha, commença de régner sur Israël à Thirtsa, [et il régna] deux ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Et son serviteur Zimri, chef de la moitié de ses chars, conspira contre lui. Et il était à Thirtsa, buvant et s’enivrant dans la maison d’Artsa, qui était [préposé] sur sa maison à Thirtsa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Et Zimri y alla et le frappa, et le mit à mort la vingt-septième année d’Asa, roi de Juda; et il régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Et il arriva que, lorsqu’il commença de régner, aussitôt qu’il s’assit sur son trône, il frappa toute la maison de Baësha; il ne lui laissa pas un seul mâle, ni ses parents, ni un ami.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Et Zimri détruisit toute la maison de Baësha, selon la parole de l’ Éternel qu’il prononça contre Baësha par Jéhu, le prophète,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'à cause de tous les péchés de Baësha et des péchés d’Éla, son fils, qu’ils avaient commis et par lesquels ils avaient fait pécher Israël, pour provoquer à colère l’ Éternel, le Dieu d’Israël, par leurs vanités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Et le reste des actes d’Éla, et tout ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'La vingt -septième année d’Asa, roi de Juda, Zimri régna sept jours à Thirtsa. Et le peuple était campé contre Guibbethon, qui était aux Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Et le peuple qui campait entendit dire: Zimri a conspiré, et il a aussi frappé le roi. Et ce même jour, dans le camp, tout Israël établit Omri, chef de l’armée, roi sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Et Omri et tout Israël avec lui montèrent de Guibbethon, et mirent le siège devant Thirtsa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Et il arriva que, quand Zimri vit que la ville était prise, il entra dans le palais de la maison du roi, et brûla par le feu la maison du roi sur lui; et il mourut');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'à cause de ses péchés qu’il avait commis en faisant ce qui est mauvais aux yeux de l’ Éternel, en marchant dans la voie de Jéroboam et dans son péché qu’il fit pour faire pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Et le reste des actes de Zimri, et la conspiration qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Alors le peuple d’Israël fut divisé par moitiés: la moitié du peuple suivit Thibni, fils de Guinath, pour le faire roi; et la moitié suivit Omri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Et le peuple qui suivit Omri prévalut sur le peuple qui suivit Thibni, fils de Guinath; et Thibni mourut, et Omri régna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'La trente et unième année d’Asa, roi de Juda, Omri commença de régner sur Israël, [et il régna] douze ans. Il régna six ans à Thirtsa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Et il acheta de Shémer la montagne de Samarie pour deux talents d’argent; et il bâtit sur la montagne, et appela le nom de la ville qu’il bâtit Samarie, selon le nom de Shémer, propriétaire de la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Et Omri fit ce qui est mauvais aux yeux de l’ Éternel, et il fit pis que tous ceux qui avaient été avant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Et il marcha dans toute la voie de Jéroboam, fils de Nebath, et dans ses péchés par lesquels il avait fait pécher Israël pour provoquer à colère l’ Éternel, le Dieu d’Israël, par leurs vanités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Et le reste des actes d’Omri, ce qu’il fit, et sa puissance qu’il montra, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Et Omri s’endormit avec ses pères, et il fut enterré à Samarie; et Achab, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Et Achab, fils d’Omri, commença de régner sur Israël la trente -huitième année d’Asa, roi de Juda. Et Achab, fils d’Omri, régna sur Israël à Samarie, 22 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Et Achab, fils d’Omri, fit ce qui est mauvais aux yeux de l’ Éternel, plus que tous ceux qui avaient été avant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Et il arriva que, comme si c’était peu de chose qu’il marche dans les péchés de Jéroboam, fils de Nebath, il prit pour femme Jézabel, fille d’Ethbaal, roi des Sidoniens, et alla et servit Baal, et se prosterna devant lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'et dressa un autel à Baal dans la maison de Baal qu’il bâtit à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Et Achab fit une ashère; et Achab fit plus que tous les rois d’Israël qui avaient été avant lui, pour provoquer à colère l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'De son temps, Hiel, le Béthélite, bâtit Jéricho; il la fonda sur Abiram, son premier-né, et posa ses portes sur Segub, son plus jeune fils, selon la parole de l’ Éternel, qu’il avait dite par Josué, fils de Nun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, '*Et Élie, le Thishbite, d’entre les habitants de Galaad, dit à Achab: L’ Éternel, le Dieu d’Israël, devant qui je me tiens, est vivant, qu’il n’y aura ces années-ci ni rosée ni pluie, sinon à ma parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Et la parole de l’ Éternel vint à lui, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Va-t’en d’ici, et tourne-toi vers l’orient, et cache-toi au torrent du Kerith, qui est vers le Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Et il arrivera que tu boiras du torrent, et j’ai commandé aux corbeaux de te nourrir là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Et il s’en alla et fit selon la parole de l’ Éternel: il s’en alla et habita au torrent du Kerith, qui est vers le Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Et les corbeaux lui apportaient du pain et de la chair le matin, et du pain et de la chair le soir, et il buvait du torrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Et il arriva, au bout de quelque temps, que le torrent sécha, car il n’y avait pas de pluie dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Et la parole de l’ Éternel vint à lui, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Lève-toi, va-t’en à Sarepta, qui appartient à Sidon, et tu habiteras là; voici, j’ai commandé là à une femme veuve de te nourrir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Et il se leva et s’en alla à Sarepta; et il vint à l’entrée de la ville; et voici, [il y avait] là une femme veuve qui ramassait du bois; et il lui cria et dit: Prends-moi, je te prie, un peu d’eau dans un vase, afin que je boive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Et elle s’en alla pour en prendre. Et il lui cria et dit: Prends-moi dans ta main, je te prie, un morceau de pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Et elle dit: L’ Éternel ton Dieu est vivant, que je n’ai pas un morceau de pain cuit, rien qu’une poignée de farine dans un pot, et un peu d’huile dans une cruche; et voici, je ramasse deux bûchettes, afin que j’entre, et que je prépare cela pour moi et pour mon fils; puis nous le mangerons et nous mourrons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Et Élie lui dit: Ne crains point; va, fais selon ta parole; seulement fais-moi premièrement de cela un petit gâteau, et apporte-le-moi; et, après, tu en feras pour toi et pour ton fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'car ainsi dit l’ Éternel, le Dieu d’Israël: Le pot de farine ne s’épuisera pas, et la cruche d’huile ne manquera pas, jusqu’au jour où l’ Éternel donnera de la pluie sur la face de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Et elle s’en alla, et fit selon la parole d’Élie. Et elle mangea, elle, et lui, et sa maison, toute une année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Le pot de farine ne s’épuisa pas et la cruche d’huile ne manqua pas, selon la parole de l’ Éternel, qu’il avait dite par Élie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Et il arriva, après ces choses, que le fils de la femme, maîtresse de la maison, tomba malade; et sa maladie devint très forte, de sorte qu’il ne resta plus de souffle en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Et elle dit à Élie: Qu’y a-t-il entre moi et toi, homme de Dieu? Es-tu venu chez moi pour mettre en mémoire mon iniquité et faire mourir mon fils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Et il lui dit: Donne-moi ton fils. Et il le prit de son sein, et le monta dans la chambre haute où il habitait, et le coucha sur son lit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Et il cria à l’ Éternel, et dit: Ô Éternel, mon Dieu! as-tu aussi fait venir du mal sur la veuve chez laquelle je séjourne, en faisant mourir son fils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Et il s’étendit sur l’enfant, trois fois, et il cria à l’ Éternel, et dit: Éternel, mon Dieu! fais revenir, je te prie, l’âme de cet enfant au-dedans de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Et l’ Éternel écouta la voix d’Élie, et fit revenir l’âme de l’enfant au-dedans de lui, et il vécut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Et Élie prit l’enfant, et le descendit de la chambre haute dans la maison, et le donna à sa mère. Et Élie dit: Vois, ton fils vit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Et la femme dit à Élie: Maintenant, à cela je connais que tu es un homme de Dieu, et que la parole de l’ Éternel dans ta bouche est la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, '*Et il arriva, après bien des jours, que la parole de l’ Éternel vint à Élie, la troisième année, disant: Va, montre-toi à Achab, et je donnerai de la pluie sur la face de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Et Élie s’en alla pour se montrer à Achab. Et la famine était forte à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Et Achab appela Abdias qui était [préposé] sur sa maison; (et Abdias craignait beaucoup l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Et il était arrivé, quand Jézabel exterminait les prophètes de l’ Éternel, qu’Abdias avait pris 100 prophètes et les avait cachés par 50 hommes dans une caverne, et les avait nourris de pain et d’eau.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Et Achab dit à Abdias: Va dans le pays, à toutes les sources d’eaux, et à tous les torrents; peut-être trouverons-nous de l’herbage, et nous conserverons la vie aux chevaux et aux mulets, et nous ne serons pas obligés de détruire de [nos] bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Et ils se partagèrent le pays pour le parcourir. Achab s’en alla seul par un chemin, et Abdias alla seul par un autre chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Et comme Abdias était en chemin, voici, Élie le rencontra; et il le reconnut, et tomba sur sa face, et dit: Est-ce bien toi, mon seigneur Élie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Et il lui dit: [C’est] moi; va, dis à ton seigneur: Voici Élie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Et il dit: Quel péché ai-je commis, que tu livres ton serviteur en la main d’Achab, pour me faire mourir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'L’ Éternel, ton Dieu, est vivant, s’il y a nation ou royaume où mon seigneur n’ait pas envoyé pour te chercher! Et quand ils disaient: Il n’est pas [ici], il faisait jurer le royaume ou la nation qu’on ne t’avait pas trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Et maintenant, tu dis: Va, dis à ton seigneur: Voici Élie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Et il arrivera, dès que je m’en irai d’auprès de toi, que l’Esprit de l’ Éternel te portera je ne sais où; et je serai venu informer Achab, et il ne te trouvera pas, et il me tuera. Et ton serviteur craint l’ Éternel dès sa jeunesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'N’a-t-on pas rapporté à mon seigneur ce que j’ai fait quand Jézabel tuait les prophètes de l’ Éternel, comment j’ai caché 100 hommes des prophètes de l’ Éternel, par 50 hommes dans une caverne, et je les ai nourris de pain et d’eau?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Et maintenant tu dis: Va, dis à ton seigneur: Voici Élie! Et il me tuera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Et Élie dit: L’ Éternel des armées, devant qui je me tiens, est vivant, qu’aujourd’hui je me montrerai à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Et Abdias s’en alla à la rencontre d’Achab, et le lui rapporta. Et Achab alla à la rencontre d’Élie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Et il arriva que, quand Achab vit Élie, Achab lui dit: Est-ce bien toi, – celui qui trouble Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Et il dit: Je ne trouble pas Israël, mais c’est toi et la maison de ton père, parce que vous avez abandonné les commandements de l’ Éternel et que tu as marché après les Baals.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Et maintenant, envoie, rassemble vers moi tout Israël, à la montagne du Carmel, et les 450 prophètes de Baal et les 400 prophètes des ashères, qui mangent à la table de Jézabel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Et Achab envoya à tous les fils d’Israël, et rassembla les prophètes à la montagne du Carmel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Et Élie s’approcha de tout le peuple, et dit: Combien de temps hésiterez-vous entre les deux côtés? Si l’ Éternel est Dieu, suivez-le; et si c’est Baal, suivez-le! Et le peuple ne lui répondit mot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Et Élie dit au peuple: Je reste, moi seul, prophète de l’ Éternel, et les prophètes de Baal sont 450 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Qu’on nous donne deux taureaux; et qu’ils choisissent pour eux l’un des taureaux, et qu’ils le dépècent, et qu’ils le placent sur le bois, et qu’ils n’y mettent pas de feu; et moi j’offrirai l’autre taureau, et je le placerai sur le bois, et je n’y mettrai pas de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Et vous invoquerez le nom de votre dieu, et moi j’invoquerai le nom de l’ Éternel, et le dieu qui répondra par le feu, lui, sera Dieu. Et tout le peuple répondit et dit: La parole est bonne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Et Élie dit aux prophètes de Baal: Choisissez pour vous l’un des taureaux, et offrez les premiers, car vous êtes nombreux, et invoquez le nom de votre dieu, et ne mettez pas de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Et ils prirent le taureau qu’on leur avait donné, et l’offrirent, et invoquèrent le nom de Baal depuis le matin jusqu’à midi, disant: Ô Baal, réponds-nous! Mais il n’y eut pas de voix, ni personne qui réponde. Et ils sautaient autour de l’autel qu’on avait fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Et il arriva qu’à midi Élie se moqua d’eux, et dit: Criez à haute voix, car il est un dieu; car il médite, ou il est allé à l’écart, ou il est en voyage; peut-être qu’il dort, et il se réveillera!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Et ils crièrent à haute voix, et se firent des incisions, selon leur coutume, avec des épées et des piques, jusqu’à faire couler le sang sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Et il arriva, quand midi fut passé, qu’ils prophétisèrent jusqu’à [l’heure] où l’on offre le gâteau; et il n’y eut pas de voix, et personne qui réponde, et personne qui fasse attention.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Alors Élie dit à tout le peuple: Approchez-vous de moi. Et tout le peuple s’approcha de lui. Et il répara l’autel de l’ Éternel, qui avait été renversé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Et Élie prit douze pierres, selon le nombre des tribus des fils de Jacob, auquel vint la parole de l’ Éternel, disant: Israël sera ton nom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'et il bâtit avec les pierres un autel au nom de l’ Éternel, et fit autour de l’autel un fossé de la capacité de deux mesures de semence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'et il arrangea le bois, et dépeça le taureau, et le plaça sur le bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Et il dit: Remplissez d’eau quatre cruches, et versez-les sur l’holocauste et sur le bois. Et il dit: Faites-le une seconde fois; et ils le firent une seconde fois. Et il dit: Faites-le une troisième fois; et ils le firent une troisième fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Et l’eau coula autour de l’autel; et il remplit d’eau aussi le fossé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Et il arriva, à [l’heure] où l’on offre le gâteau, qu’Élie, le prophète, s’approcha, et dit: Éternel, Dieu d’Abraham, d’Isaac, et d’Israël, qu’il soit connu aujourd’hui que toi tu es Dieu en Israël, et que moi je suis ton serviteur, et que c’est par ta parole que j’ai fait toutes ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Réponds-moi, Éternel, réponds-moi, et que ce peuple sache que toi, Éternel, tu es Dieu, et que tu as ramené leur cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Et le feu de l’ Éternel tomba, et consuma l’holocauste, et le bois, et les pierres, et la poussière, et lécha l’eau qui était dans le fossé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Et tout le peuple le vit; et ils tombèrent sur leurs faces, et dirent: L’ Éternel, c’est lui qui est Dieu! L’ Éternel, c’est lui qui est Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Et Élie leur dit: Saisissez les prophètes de Baal, que pas un d’entre eux n’échappe! Et ils les saisirent; et Élie les fit descendre au torrent de Kison, et les égorgea là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Et Élie dit à Achab: Monte, mange et bois, car il y a un bruit d’une abondance de pluie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Et Achab monta pour manger et pour boire. Et Élie monta au sommet du Carmel, et il se courba jusqu’à terre, et mit sa face entre ses genoux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Et il dit à son jeune homme: Monte, je te prie; regarde du côté de l’ouest. Et il monta, et regarda, et il dit: Il n’y a rien. Et il dit: Retournes-y sept fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Et il arriva qu’à la septième fois, il dit: Voici un petit nuage, comme la main d’un homme, qui s’élève de la mer. Et il dit: Lève-toi, dis à Achab: Attelle, et descends, afin que la pluie ne t’arrête pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Et il arriva, en attendant, que les cieux devinrent noirs par d’épais nuages accompagnés de vent, et il y eut une forte pluie; et Achab monta dans son char et s’en alla à Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Et la main de l’ Éternel fut sur Élie, et il ceignit ses reins, et courut devant Achab jusque là où tu arrives à Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, '*Et Achab raconta à Jézabel tout ce qu’Élie avait fait, et, en détail, comment il avait tué par l’épée tous les prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Et Jézabel envoya un messager à Élie, disant: Ainsi [me] fassent les dieux, et ainsi ils y ajoutent, si demain, à cette heure, je ne mets ton âme comme l’âme de l’un d’eux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Et voyant cela, il se leva, et s’en alla pour sa vie, et vint à Beër-Shéba, qui appartient à Juda, et il y laissa son jeune homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Et il s’en alla, lui, dans le désert, le chemin d’un jour, et vint et s’assit sous un genêt; et il demanda la mort pour son âme, et dit: C’est assez! maintenant, Éternel, prends mon âme, car je ne suis pas meilleur que mes pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Et il se coucha, et dormit sous le genêt. Et voici, un ange le toucha, et lui dit: Lève-toi, mange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Et il regarda, et voici, à son chevet, un gâteau cuit sur les pierres chaudes, et une cruche d’eau; et il mangea et but, et se recoucha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Et l’ange de l’ Éternel revint une seconde fois, et le toucha, et dit: Lève-toi, mange, car le chemin est trop long pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Et il se leva, et mangea et but; et il alla, avec la force de ces aliments, 40 jours et 40 nuits, jusqu’à Horeb, la montagne de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Et là, il entra dans la caverne, et y passa la nuit. Et voici, la parole de l’ Éternel vint à lui et lui dit: Que fais-tu ici, Élie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Et il dit: J’ai été très jaloux pour l’ Éternel, le Dieu des armées; car les fils d’Israël ont abandonné ton alliance, ils ont renversé tes autels et ils ont tué tes prophètes par l’épée, et je suis resté, moi seul, et ils cherchent ma vie pour me l’ôter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Et il dit: Sors, et tiens-toi sur la montagne devant l’ Éternel. Et voici, l’ Éternel passa, et devant l’ Éternel un grand vent impétueux déchirait les montagnes et brisait les rochers: l’ Éternel n’était pas dans le vent. Et après le vent, un tremblement de terre: l’ Éternel n’était pas dans le tremblement de terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Et après le tremblement de terre, du feu: l’ Éternel n’était pas dans le feu. Et après le feu, une voix douce, subtile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Et il arriva, quand Élie l’entendit, qu’il enveloppa son visage dans son manteau, et sortit et se tint à l’entrée de la caverne. Et voici, une voix lui [parla], et dit: Que fais-tu ici, Élie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Et il dit: J’ai été très jaloux pour l’ Éternel, le Dieu des armées; car les fils d’Israël ont abandonné ton alliance, ils ont renversé tes autels et ils ont tué tes prophètes par l’épée, et je suis resté, moi seul, et ils cherchent ma vie pour me l’ôter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Et l’ Éternel lui dit: Va, retourne par ton chemin, vers le désert de Damas, et quand tu seras arrivé, tu oindras Hazaël pour qu’il soit roi sur la Syrie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'et Jéhu, fils de Nimshi, tu l’oindras pour qu’il soit roi sur Israël, et tu oindras Élisée, fils de Shaphath, d’Abel-Mehola, pour qu’il soit prophète à ta place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Et il arrivera que celui qui échappera à l’épée de Hazaël, Jéhu le fera mourir; et celui qui échappera à l’épée de Jéhu, Élisée le fera mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Mais je me suis réservé en Israël 7 000 [hommes], tous les genoux qui n’ont pas fléchi devant Baal, et toutes les bouches qui ne l’ont pas embrassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Et il s’en alla de là, et trouva Élisée, fils de Shaphath; et il labourait avec douze paires [de bœufs] devant lui, et lui était avec la douzième. Et Élie passa vers lui et jeta son manteau sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Et il abandonna les bœufs, et courut après Élie, et dit: Que j’embrasse, je te prie, mon père et ma mère, et je m’en irai après toi. Et il lui dit: Va, retourne; car que t’ai-je fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Et il s’en retourna d’auprès de lui, et prit la paire de bœufs, et en fit un sacrifice; et, avec le harnachement des bœufs, il fit cuire leur chair et la donna au peuple, et ils mangèrent; et il se leva et s’en alla après Élie; et il le servait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, '*Et Ben-Hadad, roi de Syrie, rassembla toutes ses forces; et il y avait 32 rois avec lui, et des chevaux et des chars. Et il monta et assiégea Samarie, et lui fit la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Et il envoya des messagers à Achab, roi d’Israël, dans la ville;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'et il lui dit: Ainsi dit Ben-Hadad: Ton argent et ton or sont à moi, et tes femmes, et tes fils, les [plus] beaux, sont à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Et le roi d’Israël répondit et dit: Selon ta parole, ô roi, mon seigneur, je suis à toi, moi et tout ce que j’ai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Et les messagers revinrent et dirent: Ainsi a parlé Ben-Hadad, disant: Je t’ai envoyé dire en effet: Tu me donneras ton argent et ton or, et tes femmes, et tes fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'mais demain à cette heure, j’enverrai mes serviteurs vers toi, et ils fouilleront ta maison et les maisons de tes serviteurs, et ils mettront dans leurs mains tout ce qui est désirable à tes yeux, et l’emporteront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Et le roi d’Israël appela tous les anciens du pays, et dit: Sachez, je vous prie, et voyez comment cet [homme] cherche du mal; car il a envoyé vers moi pour mes femmes, et pour mes fils, et pour mon argent, et pour mon or, et je ne lui ai [rien] refusé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Et tous les anciens et tout le peuple lui dirent: Ne l’écoute pas, et ne consens pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Et il dit aux messagers de Ben-Hadad: Dites au roi, mon seigneur: Tout ce que tu as demandé à ton serviteur la première fois, je le ferai; mais cette chose-ci, je ne puis la faire. Et les messagers s’en allèrent et lui rapportèrent cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Et Ben-Hadad envoya vers lui, et dit: Ainsi me fassent les dieux et ainsi ils y ajoutent, si la poussière de Samarie suffit pour [remplir] le creux des mains de tout le peuple qui me suit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Et le roi d’Israël répondit et dit: Dites-lui: Que celui qui se ceint ne se vante pas comme celui qui délie [sa ceinture].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Et il arriva que, lorsque [Ben-Hadad] entendit cette parole (il était à boire, lui et les rois, dans les tentes) il dit à ses serviteurs: Placez-vous. Et ils se rangèrent contre la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Et voici, un prophète s’approcha d’Achab, roi d’Israël, et dit: Ainsi dit l’ Éternel: Vois-tu toute cette grande multitude? Voici, je l’ai livrée aujourd’hui en ta main, et tu sauras que moi, je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Et Achab dit: Par qui? Et il dit: Ainsi dit l’ Éternel: Par les serviteurs des chefs des provinces. Et il dit: Qui engagera le combat? Et il dit: Toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Et il dénombra les serviteurs des chefs des provinces; et ils étaient 232; et après eux, il dénombra tout le peuple, tous les fils d’Israël, 7 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Et ils sortirent à midi; et Ben-Hadad buvait, s’enivrant dans les tentes, lui et les rois, 32 rois qui l’aidaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Et les serviteurs des chefs des provinces sortirent les premiers. Et Ben-Hadad envoya, et on lui rapporta, disant: Des hommes sont sortis de Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Et il dit: S’ils sont sortis pour la paix, saisissez-les vivants; et s’ils sont sortis pour la guerre, saisissez-les vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Et ces serviteurs des chefs des provinces sortirent de la ville, ainsi que l’armée qui les suivait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Et ils frappèrent chacun son homme, et les Syriens s’enfuirent; et Israël les poursuivit; et Ben-Hadad, roi de Syrie, échappa sur un cheval, avec des cavaliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Et le roi d’Israël sortit et frappa les chevaux et les chars, et il infligea aux Syriens une grande défaite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Et le prophète s’approcha du roi d’Israël, et lui dit: Va, fortifie-toi, et sache et vois ce que tu dois faire; car au retour de l’année le roi de Syrie montera contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Et les serviteurs du roi de Syrie lui dirent: Leurs dieux sont des dieux de montagnes; c’est pourquoi ils ont été plus forts que nous; mais si nous les combattons dans la plaine, certainement nous serons plus forts qu’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Et fais ceci: ôte les rois chacun de sa place, et mets en leur lieu des capitaines;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'et toi, dénombre-toi une armée comme l’armée que tu as perdue, et cheval pour cheval, et char pour char, et nous nous battrons avec eux dans la plaine: certainement nous serons plus forts qu’eux. Et il écouta leur voix, et fit ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Et il arriva, qu’au retour de l’année, Ben-Hadad dénombra les Syriens, et monta à Aphek pour faire la guerre contre Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Et les fils d’Israël furent dénombrés et approvisionnés; et les fils d’Israël allèrent à leur rencontre, et ils campèrent vis-à-vis d’eux, comme deux petits troupeaux de chèvres, et les Syriens remplissaient le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Et l’homme de Dieu s’approcha, et parla au roi d’Israël et dit: Ainsi dit l’ Éternel: Parce que les Syriens ont dit: L’ Éternel est un dieu de montagnes, et pas un dieu de plaines, je livrerai toute cette grande multitude en ta main; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Et ils campèrent, ceux-ci vis-à-vis de ceux-là, sept jours; et il arriva, le septième jour, que le combat se livra. Et les fils d’Israël frappèrent les Syriens, 100 000 hommes de pied, en un seul jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Et le reste s’enfuit à Aphek, dans la ville, et la muraille tomba sur 27 000 hommes de ceux qui restaient. Et Ben-Hadad s’enfuit et entra dans la ville, d’une chambre dans l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Et ses serviteurs lui dirent: Voici, nous avons entendu dire que les rois de la maison d’Israël sont des rois [doux et] cléments; mettons, je te prie, des sacs sur nos reins et des cordes à nos têtes, et sortons vers le roi d’Israël: peut-être qu’il laissera vivre ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Et ils ceignirent de sacs leurs reins et [mirent] des cordes à leurs têtes, et s’en vinrent vers le roi d’Israël. Et ils dirent: Ton serviteur Ben-Hadad dit: Je te prie, laisse vivre mon âme. Et il dit: Vit-il encore? Il est mon frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Et les hommes en augurèrent [du bien], et se hâtèrent de saisir ce qui venait de lui; et ils dirent: Ton frère Ben-Hadad... Et il dit: Allez, amenez-le. Et Ben-Hadad sortit vers lui, et il le fit monter sur son char.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Et [Ben-Hadad] lui dit: Les villes que mon père a prises à ton père, je les rends, et tu feras pour toi des rues à Damas, comme mon père en a fait à Samarie. Et moi, [dit Achab], je te renverrai avec cette alliance. Et il fit alliance avec lui, et le renvoya.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Et un homme d’entre les fils des prophètes dit à son compagnon, par la parole de l’ Éternel: Frappe-moi, je te prie. Et l’homme refusa de le frapper.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Et il lui dit: Parce que tu n’as pas écouté la voix de l’ Éternel, voici, quand tu sortiras d’auprès de moi, le lion te tuera. Et il sortit d’auprès de lui, et le lion le trouva, et le tua.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Et il trouva un autre homme, et il dit: Frappe-moi, je te prie. Et l’homme le frappa fort, et le blessa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Et le prophète s’en alla, et se tint sur le chemin du roi, et se déguisa avec un bandeau sur les yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Et, comme le roi passait, il cria au roi, et dit: Ton serviteur était sorti au milieu de la bataille, et voici, un homme se détourna, et m’amena un homme, et dit: Garde cet homme; s’il vient à manquer, ta vie sera à la place de sa vie, ou tu me pèseras un talent d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Et, comme ton serviteur était occupé çà et là, l’homme a disparu. Et le roi d’Israël lui dit: Ainsi est ton jugement: tu en as décidé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Et il ôta avec hâte le bandeau de dessus ses yeux, et le roi d’Israël le reconnut pour l’un des prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Et il lui dit: Ainsi dit l’ Éternel: Parce que tu as laissé aller d’entre tes mains l’homme que j’avais voué à la destruction, ta vie sera pour sa vie, et ton peuple pour son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Et le roi d’Israël alla en sa maison, triste et irrité, et il vint à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, '*Et il arriva, après ces choses, que Naboth, le Jizreélite, avait une vigne qui était à Jizreël, à côté du palais d’Achab, roi de Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Et Achab parla à Naboth, disant: Donne-moi ta vigne afin que j’en fasse un jardin potager, car elle est proche, à côté de ma maison, et je te donnerai à sa place une meilleure vigne que celle-là, ou, si cela est bon à tes yeux, je te donnerai l’argent que vaut celle-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Et Naboth dit à Achab: Que l’ Éternel me garde de te donner l’héritage de mes pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Et Achab s’en vint à sa maison, triste et irrité, à cause de la parole que Naboth, le Jizreélite, lui avait dite; car il avait dit: Je ne te donnerai pas l’héritage de mes pères. Et il s’étendit sur sa couche, et détourna sa face, et ne mangea pas du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Et Jézabel, sa femme, vint vers lui et lui dit: Pourquoi donc ton esprit est-il triste et ne manges-tu pas du pain?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Et il lui dit: Parce que j’ai parlé à Naboth, le Jizreélite, et lui ai dit: Donne-moi ta vigne pour de l’argent, ou, si cela te plaît, je te donnerai une vigne à la place. Et il a dit: Je ne te donnerai pas ma vigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Et Jézabel, sa femme, lui dit: Est-ce toi qui exerces maintenant la royauté sur Israël? Lève-toi, mange du pain, et que ton cœur soit gai; moi, je te donnerai la vigne de Naboth, le Jizreélite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Et elle écrivit des lettres au nom d’Achab, et les scella de son sceau, et envoya les lettres aux anciens et aux nobles qui étaient dans sa ville, qui habitaient avec Naboth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Et elle écrivit dans les lettres, disant: Proclamez un jeûne et mettez Naboth en tête du peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'et mettez deux hommes, fils de Bélial, en face de lui, et qu’ils témoignent contre lui, disant: Tu as maudit Dieu et le roi. Et menez-le dehors et lapidez-le, et qu’il meure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Et les hommes de sa ville, les anciens et les nobles qui habitaient sa ville, firent selon ce que Jézabel leur avait demandé, selon ce qui était écrit dans les lettres qu’elle leur avait envoyées:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'ils proclamèrent un jeûne et mirent Naboth en tête du peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'et deux hommes, fils de Bélial, vinrent et s’assirent en face de lui; et les hommes de Bélial témoignèrent contre lui, contre Naboth, devant le peuple, disant: Naboth a maudit Dieu et le roi. Et ils le menèrent hors de la ville, et l’assommèrent de pierres, et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Et ils envoyèrent à Jézabel, disant: Naboth a été lapidé, et il est mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Et il arriva que, lorsque Jézabel apprit que Naboth avait été lapidé et était mort, Jézabel dit à Achab: Lève-toi, prends possession de la vigne de Naboth, le Jizreélite, qu’il refusa de te donner pour de l’argent, car Naboth n’est pas vivant, mais il est mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Et il arriva que, quand Achab apprit que Naboth était mort, Achab se leva pour descendre à la vigne de Naboth, le Jizreélite, pour en prendre possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Et la parole de l’ Éternel vint à Élie, le Thishbite, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Lève-toi, descends à la rencontre d’Achab, le roi d’Israël, qui est à Samarie: voici, il est dans la vigne de Naboth, où il est descendu pour en prendre possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Et tu lui parleras, disant: Ainsi dit l’ Éternel: As-tu tué, et aussi pris possession? Et tu lui parleras, disant: Ainsi dit l’ Éternel: Au lieu où les chiens ont léché le sang de Naboth, les chiens lécheront ton sang, à toi aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Et Achab dit à Élie: M’as-tu trouvé, mon ennemi? Et il dit: Je t’ai trouvé, parce que tu t’es vendu pour faire ce qui est mauvais aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Voici, je vais faire venir du mal sur toi, et j’ôterai ta postérité, et je retrancherai d’Achab tous les mâles, l’homme lié et l’homme libre en Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'et je ferai de ta maison comme de la maison de Jéroboam, fils de Nebath, et de la maison de Baësha, fils d’Akhija, à cause de la provocation par laquelle tu m’as provoqué et tu as fait pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Et aussi à l’égard de Jézabel, l’ Éternel parla, disant: Les chiens mangeront Jézabel à l’avant-mur de Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Celui [de la maison] d’Achab qui mourra dans la ville, les chiens le mangeront, et celui qui mourra dans les champs, les oiseaux des cieux le mangeront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, '(Certainement il n’y eut point [de roi] comme Achab, qui se vendit pour faire ce qui est mauvais aux yeux de l’ Éternel, sa femme Jézabel le poussant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Et il agit très abominablement, en allant après les idoles, selon tout ce que faisaient les Amoréens que l’ Éternel avait dépossédés devant les fils d’Israël.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Et il arriva, quand Achab entendit ces paroles, qu’il déchira ses vêtements, et mit un sac sur sa chair, et jeûna; et il couchait avec le sac et marchait doucement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Et la parole de l’ Éternel vint à Élie, le Thishbite, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Vois-tu comment Achab s’est humilié devant moi? Parce qu’il s’est humilié devant moi, je ne ferai pas venir le mal en ses jours; [mais] dans les jours de son fils, je ferai venir le mal sur sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, '*Et on resta trois ans sans qu’il y ait guerre entre la Syrie et Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Et il arriva, en la troisième année, que Josaphat, roi de Juda, descendit vers le roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Et le roi d’Israël dit à ses serviteurs: Savez-vous que Ramoth de Galaad est à nous? Et nous nous taisons, sans la reprendre de la main du roi de Syrie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Et il dit à Josaphat: Viendras-tu avec moi à la guerre, à Ramoth de Galaad? Et Josaphat dit au roi d’Israël: Moi, je suis comme toi, mon peuple comme ton peuple, mes chevaux comme tes chevaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Et Josaphat dit au roi d’Israël: Enquiers-toi aujourd’hui, je te prie, de la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Et le roi d’Israël rassembla les prophètes, environ 400 hommes, et leur dit: Irai-je à la guerre contre Ramoth de Galaad, ou m’en abstiendrai-je? Et ils dirent: Monte; et le Seigneur la livrera en la main du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Et Josaphat dit: N’y a-t-il pas ici encore un prophète de l’ Éternel, pour que nous nous enquérions auprès de lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Et le roi d’Israël dit à Josaphat: Il y a encore un homme, pour consulter l’ Éternel par lui; mais je le hais, car il ne prophétise pas du bien à mon égard, mais du mal; c’est Michée, fils de Jimla. Et Josaphat dit: Que le roi ne parle pas ainsi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Et le roi d’Israël appela un eunuque, et dit: Fais promptement venir Michée, fils de Jimla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Et le roi d’Israël et Josaphat, roi de Juda, étaient assis chacun sur son trône, revêtus de leurs robes, sur une place ouverte, à l’entrée de la porte de Samarie; et tous les prophètes prophétisaient devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Et Sédécias, fils de Kenaana, se fit des cornes de fer, et dit: Ainsi dit l’ Éternel: Avec celles-ci tu heurteras les Syriens, jusqu’à les exterminer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Et tous les prophètes prophétisaient de même, disant: Monte à Ramoth de Galaad, et prospère; et l’ Éternel la livrera en la main du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Et le messager qui était allé pour appeler Michée, lui parla, disant: Voici, les paroles des prophètes, d’une seule bouche, [annoncent] du bien au roi; que ta parole soit, je te prie, comme la parole de l’un d’eux, et annonce du bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Mais Michée dit: L’ Éternel est vivant, que ce que l’ Éternel me dira, je l’annoncerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Et il vint vers le roi. Et le roi lui dit: Michée, irons-nous à la guerre à Ramoth de Galaad, ou nous en abstiendrons-nous? Et il lui dit: Monte et prospère; et l’ Éternel la livrera en la main du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Et le roi lui dit: Combien de fois t’adjurerai-je de ne me dire que la vérité au nom de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Et [Michée] dit: J’ai vu tout Israël dispersé sur les montagnes, comme un troupeau qui n’a pas de berger; et l’ Éternel a dit: Ceux-ci n’ont pas de seigneur; qu’ils s’en retournent en paix chacun à sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Et le roi d’Israël dit à Josaphat: Ne t’ai-je pas dit qu’il ne prophétise pas du bien à mon égard, mais du mal?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Et [Michée] dit: C’est pourquoi, écoute la parole de l’ Éternel. J’ai vu l’ Éternel assis sur son trône, et toute l’armée des cieux se tenant près de lui, à sa droite et à sa gauche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'et l’ Éternel dit: Qui persuadera Achab, afin qu’il monte et qu’il tombe à Ramoth de Galaad? Et celui-ci dit ainsi, et celui-là dit ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Et un esprit sortit, et se tint devant l’ Éternel, et dit: Moi, je le persuaderai. Et l’ Éternel lui dit: Comment?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Et il dit: Je sortirai, et je serai un esprit de mensonge dans la bouche de tous ses prophètes. Et [l’ Éternel] dit: Tu le persuaderas, et aussi tu réussiras: sors, et fais ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Et maintenant, voici, l’ Éternel a mis un esprit de mensonge dans la bouche de tous tes prophètes que voilà, et l’ Éternel a prononcé du mal à ton sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Et Sédécias, fils de Kenaana, s’approcha et frappa Michée sur la joue, et dit: Par où a passé l’Esprit de l’ Éternel, d’avec moi, pour te parler?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Et Michée dit: Voici, tu le verras ce jour-là, quand tu iras de chambre en chambre pour te cacher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Et le roi d’Israël dit: Prends Michée, et emmène-le à Amon, chef de la ville, et à Joas, fils du roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'et tu diras: Ainsi dit le roi: Mettez cet [homme] en prison, et donnez-lui à manger le pain d’affliction et l’eau d’affliction, jusqu’à ce que je revienne en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Et Michée dit: Si jamais tu reviens en paix, l’ Éternel n’a point parlé par moi. Et il dit: Peuples, entendez-le tous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Et le roi d’Israël monta, et Josaphat, roi de Juda, à Ramoth de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Et le roi d’Israël dit à Josaphat: Je me déguiserai, et j’irai à la bataille; mais toi, revêts-toi de tes robes. Et le roi d’Israël se déguisa et fut à la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Et le roi de Syrie commanda aux 32 chefs de ses chars, disant: Ne combattez ni contre petit ni contre grand, mais contre le roi d’Israël seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Et il arriva que, quand les chefs des chars virent Josaphat, ils dirent: Certainement c’est le roi d’Israël. Et ils se détournèrent, pour combattre contre lui; et Josaphat cria.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Et il arriva que, lorsque les chefs des chars virent que ce n’était pas le roi d’Israël, ils s’en revinrent de sa poursuite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Et un homme tira de l’arc à l’aventure et frappa le roi d’Israël entre les pièces d’attache et la cuirasse; et [Achab] dit au conducteur de son char: Tourne ta main, et mène-moi hors de l’armée, car je suis blessé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Et la bataille se renforça ce jour-là, et le roi fut soutenu debout sur [son] char, vis-à-vis des Syriens; et il mourut le soir; et le sang de la blessure coulait dans le fond du char.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Et une proclamation passa par le camp, au coucher du soleil, disant: Chacun à sa ville, et chacun à son pays!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Et le roi mourut, et on l’amena à Samarie; et on enterra le roi à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Et on lava le char à l’étang de Samarie, et les chiens léchèrent le sang d’Achab, là où les prostituées se lavaient, selon la parole de l’ Éternel qu’il avait prononcée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Et le reste des actes d’Achab, et tout ce qu’il fit, et la maison d’ivoire qu’il bâtit, et toutes les villes qu’il bâtit: ces choses ne sont-elles pas écrites dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Et Achab s’endormit avec ses pères; et Achazia, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, '*Et Josaphat, fils d’Asa, commença de régner sur Juda, la quatrième année d’Achab, roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Josaphat était âgé de 35 ans, lorsqu’il commença de régner, et il régna 25 ans à Jérusalem; et le nom de sa mère était Azuba, fille de Shilkhi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Et il marcha dans toute la voie d’Asa, son père; il ne s’en détourna pas, faisant ce qui est droit aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Seulement, les hauts lieux ne furent pas ôtés: le peuple sacrifiait encore et faisait fumer de l’encens sur les hauts lieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Et Josaphat fut en paix avec le roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Et le reste des actes de Josaphat, et la puissance qu’il montra, et les guerres qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Et il extermina du pays le reste des hommes voués à la prostitution, qui étaient restés dans les jours d’Asa, son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Et il n’y avait pas de roi en Édom; un gouverneur y régnait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Josaphat construisit des navires de Tarsis pour aller à Ophir chercher de l’or; mais ils n’allèrent pas, car les navires furent brisés à Étsion-Guéber.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Alors Achazia, fils d’Achab, dit à Josaphat: Que mes serviteurs aillent avec tes serviteurs dans les navires; et Josaphat ne le voulut pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Et Josaphat s’endormit avec ses pères, et il fut enterré avec ses pères dans la ville de David, son père; et Joram, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, '*Achazia, fils d’Achab, commença de régner sur Israël, à Samarie, la dix-septième année de Josaphat, roi de Juda; et il régna sur Israël deux ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, et il marcha dans la voie de son père, et dans la voie de sa mère, et dans la voie de Jéroboam, fils de Nebath, qui fit pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'Et il servit Baal, et se prosterna devant lui, et provoqua à colère l’ Éternel, le Dieu d’Israël, selon tout ce que son père avait fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Et Moab se rebella contre Israël, après la mort d’Achab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Et Achazia tomba par le treillis de sa chambre haute qui était à Samarie, et en fut malade. Et il envoya des messagers, et leur dit: Allez, consultez Baal-Zebub, dieu d’Ékron, [pour savoir] si je relèverai de cette maladie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Et l’ange de l’ Éternel dit à Élie, le Thishbite: Lève-toi, monte à la rencontre des messagers du roi de Samarie, et dis-leur: Est-ce parce qu’il n’y a point de Dieu en Israël que vous allez consulter Baal-Zebub, dieu d’Ékron?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Et c’est pourquoi, ainsi dit l’ Éternel: Tu ne descendras pas du lit sur lequel tu es monté, car tu mourras certainement. Et Élie partit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Et les messagers revinrent vers Achazia, et il leur dit: Pourquoi revenez-vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Et ils lui dirent: Un homme est monté à notre rencontre, et nous a dit: Allez, retournez vers le roi qui vous a envoyés, et dites-lui: Ainsi dit l’ Éternel: Est-ce parce qu’il n’y a point de Dieu en Israël, que tu envoies consulter Baal-Zebub, dieu d’Ékron? C’est pourquoi tu ne descendras pas du lit sur lequel tu es monté; car tu mourras certainement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Et il leur dit: Quelle manière d’homme était-ce, qui est monté à votre rencontre et vous a dit ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Et ils lui dirent: Un homme vêtu de poil, et ceint sur ses reins d’une ceinture de cuir. Et il dit: C’est Élie, le Thishbite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Et il envoya vers lui un chef de cinquantaine et sa cinquantaine; et il monta vers lui. Et voici, il était assis au sommet d’une montagne. Et il lui dit: Homme de Dieu, le roi dit: Descends!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Et Élie répondit et dit au chef de cinquantaine: Si je suis un homme de Dieu, que le feu descende des cieux et te dévore, toi et ta cinquantaine! Et le feu descendit des cieux, et le dévora, lui et sa cinquantaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Et [Achazia] envoya de nouveau vers lui un autre chef de cinquantaine, et sa cinquantaine. Et il prit la parole et lui dit: Homme de Dieu, ainsi dit le roi: Descends promptement!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Et Élie répondit et leur dit: Si je suis un homme de Dieu, que le feu descende des cieux, et te dévore, toi et ta cinquantaine! Et le feu de Dieu descendit des cieux, et le dévora, lui et sa cinquantaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Et [Achazia] envoya de nouveau un chef d’une troisième cinquantaine, et sa cinquantaine. Et ce troisième chef de cinquantaine monta, et vint et se mit sur ses genoux devant Élie, et le supplia, et lui dit: Homme de Dieu, je te prie, que ma vie et les vies de ces 50 hommes, tes serviteurs, soient précieuses à tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Voici, le feu est descendu des cieux et a dévoré les deux premiers chefs de cinquantaine et leurs cinquantaines; mais maintenant, que ma vie soit précieuse à tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Et l’ange de l’ Éternel dit à Élie: Descends avec lui; ne le crains pas. Et il se leva et descendit avec lui vers le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Et il lui dit: Ainsi dit l’ Éternel: Puisque tu as envoyé des messagers pour consulter Baal-Zebub, dieu d’Ékron, est-ce parce qu’il n’y avait point de Dieu en Israël pour consulter sa parole?... c’est pourquoi tu ne descendras pas du lit sur lequel tu es monté; car tu mourras certainement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Et il mourut, selon la parole de l’ Éternel qu’Élie avait prononcée. Et Joram régna à sa place, en la seconde année de Joram, fils de Josaphat, roi de Juda; car il n’avait pas de fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Et le reste des actes d’Achazia, ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, '*Et il arriva que, lorsque l’ Éternel fit monter Élie aux cieux dans un tourbillon, Élie et Élisée partirent de Guilgal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Et Élie dit à Élisée: Reste ici, je te prie; car l’ Éternel m’envoie jusqu’à Béthel. Et Élisée dit: L’ Éternel est vivant, et ton âme est vivante, que je ne te laisserai point. Et ils descendirent à Béthel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Et les fils des prophètes qui étaient à Béthel sortirent vers Élisée, et lui dirent: Sais-tu qu’aujourd’hui l’ Éternel va enlever ton maître d’au-dessus de ta tête? Et il dit: Je le sais, moi aussi; taisez-vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Et Élie lui dit: Élisée, je te prie, reste ici; car l’ Éternel m’envoie à Jéricho. Et il dit: L’ Éternel est vivant, et ton âme est vivante, que je ne te laisserai point. Et ils s’en vinrent à Jéricho.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Et les fils des prophètes qui étaient à Jéricho s’approchèrent d’Élisée, et lui dirent: Sais-tu qu’aujourd’hui l’ Éternel va enlever ton maître d’au-dessus de ta tête? Et il dit: Je le sais, moi aussi; taisez-vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Et Élie lui dit: Reste ici, je te prie; car l’ Éternel m’envoie au Jourdain. Et il dit: L’ Éternel est vivant, et ton âme est vivante, que je ne te laisserai point. Et ils s’en allèrent eux deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Et 50 hommes d’entre les fils des prophètes allèrent et se tinrent vis-à-vis, à distance; et eux deux se tinrent auprès du Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Et Élie prit son manteau, et le plia, et frappa les eaux, et elles se divisèrent deçà et delà; et ils passèrent eux deux à sec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Et il arriva, quand ils eurent passé, qu’Élie dit à Élisée: Demande ce que je ferai pour toi avant que je sois enlevé d’avec toi. Et Élisée dit: Qu’il y ait, je te prie, une double mesure de ton esprit sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Et il dit: Tu as demandé une chose difficile; si tu me vois [quand je serai] enlevé d’avec toi, il en sera ainsi pour toi; sinon, cela ne sera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Et il arriva, comme ils allaient marchant et parlant, que voici un char de feu et des chevaux de feu; et ils les séparèrent l’un de l’autre; et Élie monta aux cieux dans un tourbillon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Et Élisée le vit, et s’écria: Mon père! mon père! Char d’Israël et sa cavalerie! Et il ne le vit plus. Et il saisit ses vêtements et les déchira en deux pièces;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'et il releva le manteau d’Élie qui était tombé de dessus lui, et s’en retourna, et se tint sur le bord du Jourdain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'et il prit le manteau d’Élie qui était tombé de dessus lui, et frappa les eaux, et dit: Où est l’ Éternel, le Dieu d’Élie? – Lui aussi frappa les eaux, et elles se divisèrent deçà et delà; et Élisée passa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Et les fils des prophètes qui étaient à Jéricho, vis-à-vis, le virent, et ils dirent: L’esprit d’Élie repose sur Élisée. Et ils allèrent à sa rencontre, et se prosternèrent devant lui en terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'et lui dirent: Voici, il y a avec tes serviteurs 50 hommes, des hommes vaillants; qu’ils aillent, nous te prions, et qu’ils cherchent ton maître: l’Esprit de l’ Éternel l’aura peut-être emporté et l’aura jeté sur quelque montagne ou dans quelque vallée. Et il dit: N’y envoyez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Et ils le pressèrent jusqu’à ce qu’il en fut honteux. Et il [leur] dit: Envoyez. Et ils envoyèrent 50 hommes; et ils cherchèrent trois jours, et ne le trouvèrent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Et ils retournèrent vers Élisée (il habitait à Jéricho); et il leur dit: Ne vous avais-je pas dit: N’y allez pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Et les hommes de la ville dirent à Élisée: Tu vois que l’emplacement de la ville est bon, comme mon seigneur le voit; mais les eaux sont mauvaises, et la terre est stérile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Et il dit: Apportez-moi un vase neuf, et mettez-y du sel. Et ils le lui apportèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Et il sortit vers le lieu d’où sortaient les eaux, et y jeta le sel, et dit: Ainsi dit l’ Éternel: J’ai assaini ces eaux; il ne proviendra plus d’ici ni mort ni stérilité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Et les eaux furent assainies jusqu’à ce jour, selon la parole qu’Élisée avait prononcée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Et il monta de là à Béthel; et, comme il montait par le chemin, des petits garçons sortirent de la ville, et se moquèrent de lui, et lui dirent: Monte, chauve! monte, chauve!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Et il se tourna en arrière et les vit, et il les maudit au nom de l’ Éternel. Et deux ourses sortirent de la forêt, et déchirèrent d’entre eux 42 enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Et, de là, il se rendit à la montagne de Carmel, d’où il s’en retourna à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Et Joram, fils d’Achab, commença de régner sur Israël à Samarie la dix-huitième année de Josaphat, roi de Juda; et il régna douze ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, non pas toutefois comme son père et sa mère; et il ôta la stèle de Baal que son père avait faite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Seulement il s’attacha aux péchés de Jéroboam, fils de Nebath, par lesquels il avait fait pécher Israël; il ne s’en détourna point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Or Mésha, roi de Moab, possédait des troupeaux, et payait au roi d’Israël 100 000 agneaux et 100 000 béliers avec leur laine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Et il arriva, à la mort d’Achab, que le roi de Moab se rebella contre le roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Et le roi Joram sortit en ce temps-là de Samarie, et passa en revue tout Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Et il s’en alla, et envoya vers Josaphat, roi de Juda, disant: Le roi de Moab s’est rebellé contre moi; viendras-tu avec moi à la guerre contre Moab? Et il dit: J’y monterai; moi je suis comme toi, mon peuple comme ton peuple, mes chevaux comme tes chevaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Et il dit: Par quel chemin monterons-nous? Et il dit: Par le chemin du désert d’Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Et le roi d’Israël, et le roi de Juda, et le roi d’Édom, partirent; et ils firent un circuit de sept jours de chemin. Et il n’y avait pas d’eau pour l’armée et pour le bétail qui les suivaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Et le roi d’Israël dit: Hélas! l’ Éternel a appelé ces trois rois pour les livrer en la main de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Et Josaphat dit: N’y a-t-il point ici un prophète de l’ Éternel, afin que nous consultions l’ Éternel par lui? Et un des serviteurs du roi d’Israël répondit et dit: Il y a ici Élisée, fils de Shaphath, qui versait l’eau sur les mains d’Élie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Et Josaphat dit: La parole de l’ Éternel est avec lui. Et le roi d’Israël, et Josaphat, et le roi d’Édom, descendirent vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Et Élisée dit au roi d’Israël: Qu’y a-t-il entre moi et toi? Va vers les prophètes de ton père et vers les prophètes de ta mère. Et le roi d’Israël lui dit: Non; car l’ Éternel a appelé ces trois rois pour les livrer en la main de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Et Élisée dit: L’ Éternel des armées, devant qui je me tiens, est vivant, que si je n’avais égard à la personne de Josaphat, roi de Juda, je ne te regarderais pas, et je ne te verrais pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Et maintenant amenez-moi un joueur de harpe. Et il arriva, comme le joueur de harpe jouait, que la main de l’ Éternel fut sur Élisée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Et il dit: Ainsi dit l’ Éternel: Qu’on remplisse de fosses cette vallée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Car ainsi dit l’ Éternel: Vous ne verrez pas de vent, et vous ne verrez pas de pluie, et cette vallée sera remplie d’eau, et vous boirez, vous et vos troupeaux et votre bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Et cela est peu de chose aux yeux de l’ Éternel: il livrera aussi Moab entre vos mains;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'et vous frapperez toutes les villes fortes et toutes les villes principales, et vous abattrez tous les bons arbres, et vous boucherez toutes les sources d’eau, et vous ruinerez avec des pierres toutes les bonnes portions [de terre].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Et il arriva, au matin, à l’heure d’offrir l’offrande, que voici, des eaux vinrent du chemin d’Édom, et le pays fut rempli d’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Et tout Moab apprit que ces rois étaient montés pour leur faire la guerre, et ils convoquèrent tout homme qui était [en âge] de ceindre une ceinture, – et au-dessus; et ils se tinrent sur la frontière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Et ils se levèrent de bon matin; et le soleil se levait sur les eaux, et Moab vit en face [de lui] les eaux rouges comme du sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Et ils dirent: C’est du sang! Ces rois se sont certainement détruits et se sont frappés l’un l’autre; et maintenant, Moab, au butin!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Et ils vinrent au camp d’Israël, et les Israélites se levèrent et frappèrent les Moabites, qui s’enfuirent devant eux. Et ils entrèrent dans [le pays], et frappèrent Moab;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'et ils détruisirent les villes; et ils jetèrent chacun sa pierre dans toutes les bonnes portions [de terre], et les en remplirent; et ils bouchèrent toutes les sources d’eau et abattirent tous les bons arbres,... jusqu’à ne laisser à Kir-Haréseth que ses pierres: les frondeurs l’environnèrent et la frappèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Et le roi de Moab vit que la bataille devenait trop forte pour lui, et il prit avec lui 700 hommes tirant l’épée, pour se frayer un chemin jusqu’au roi d’Édom; mais ils ne purent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Et il prit son fils, le premier-né, qui devait régner à sa place, et il l’offrit en holocauste sur la muraille. Et il y eut une grande indignation contre Israël; et ils se retirèrent de lui, et s’en retournèrent dans leur pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Et une femme d’entre les femmes des fils des prophètes cria à Élisée, disant: Ton serviteur, mon mari, est mort; et tu sais que ton serviteur craignait l’ Éternel; et le créancier est venu pour prendre mes deux enfants, afin qu’ils soient ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Et Élisée lui dit: Que ferai-je pour toi? Dis-moi ce que tu as à la maison. Et elle dit: Ta servante n’a rien du tout dans la maison qu’ un pot d’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Et il dit: Va, demande pour toi, du dehors, des vases à tous tes voisins, des vases vides (n’en demande pas peu);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'et rentre, et ferme la porte sur toi et sur tes fils, et verse dans tous ces vases, et ôte ceux qui seront remplis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Et elle s’en alla d’auprès de lui, et elle ferma la porte sur elle et sur ses fils: ceux-ci lui apportaient [les vases], et elle versait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Et il arriva que, quand les vases furent remplis, elle dit à son fils: Apporte-moi encore un vase. Et il lui dit: Il n’y a plus de vase. Et l’huile s’arrêta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Et elle s’en vint et le raconta à l’homme de Dieu, et il dit: Va, vends l’huile, et paie ta dette; et vous vivrez, toi et tes fils, de ce qui restera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Et, un jour, il arriva qu’Élisée passa par Sunem; et il y avait là une femme riche, et elle le retint pour manger le pain. Et il se trouva que, chaque fois qu’il passait, il se retirait là pour manger le pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Et elle dit à son mari: Voici, je connais que c’est un saint homme de Dieu qui passe chez nous continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Faisons, je te prie, une petite chambre haute en maçonnerie, et mettons-y pour lui un lit, et une table, et un siège, et un chandelier; et il arrivera que, quand il viendra chez nous, il se retirera là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Or, un jour, il arriva qu’il vint là, et qu’il se retira dans la chambre haute et y coucha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Et il dit à Guéhazi, son jeune homme: Appelle cette Sunamite. Et il l’appela, et elle se tint devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Et il dit à Guéhazi: Dis-lui, je te prie: Voici, tu as montré pour nous tout cet empressement; qu’y a-t-il à faire pour toi? Faut-il parler pour toi au roi, ou au chef de l’armée? Et elle dit: J’habite au milieu de mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Et il dit: Qu’y a-t-il donc à faire pour elle? Et Guéhazi dit: Eh bien, elle n’a pas de fils, et son mari est vieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Et [Élisée] dit: Appelle-la. Et il l’appela. Et elle se tint dans la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Et il [lui] dit: À cette même époque, quand ton terme sera là, tu embrasseras un fils. Et elle dit: Non, mon seigneur, homme de Dieu, ne mens pas à ta servante!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Et la femme conçut, et enfanta un fils à cette même époque, quand son terme fut là, comme Élisée lui avait dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Et l’enfant grandit: et il arriva qu’un jour il sortit vers son père, vers les moissonneurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'et il dit à son père: Ma tête! ma tête! Et [le père] dit au serviteur: Porte-le à sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Et il l’emporta, et l’amena à sa mère; et il resta sur ses genoux jusqu’à midi, et mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Et elle monta, et le coucha sur le lit de l’homme de Dieu; et elle ferma la porte sur lui, et sortit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Et elle appela son mari, et dit: Envoie-moi, je te prie, un des jeunes hommes, et une des ânesses, et je courrai jusqu’à l’homme de Dieu; et je reviendrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Et il dit: Pourquoi vas-tu vers lui aujourd’hui? Ce n’est ni nouvelle lune ni sabbat. Et elle dit: Tout va bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Et elle fit seller l’ânesse, et dit à son jeune homme: Mène-la, et marche; ne m’arrête pas dans la course, à moins que je ne te le dise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Et elle s’en alla, et vint vers l’homme de Dieu, sur la montagne du Carmel. Et il arriva que, quand l’homme de Dieu la vit de loin, il dit à Guéhazi, son jeune homme: Voici cette Sunamite!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Cours maintenant, je te prie, à sa rencontre, et dis-lui: Tout va-t-il bien? Ton mari va-t-il bien? L’enfant va-t-il bien? Et elle dit: Bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Et elle vint vers l’homme de Dieu sur la montagne, et elle le saisit par les pieds; et Guéhazi s’approcha pour la repousser; et l’homme de Dieu dit: Laisse-la, car son âme est dans l’amertume, et l’ Éternel me l’a caché et ne me l’a pas déclaré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Alors elle dit: Ai-je demandé un fils à mon seigneur? N’ai-je pas dit: Ne me trompe pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Et il dit à Guéhazi: Ceins tes reins, et prends mon bâton en ta main, et va-t’en: si tu trouves quelqu’un, ne le salue pas, et si quelqu’un te salue, ne lui réponds pas, et tu mettras mon bâton sur le visage du jeune garçon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Et la mère du jeune garçon dit: L’ Éternel est vivant, et ton âme est vivante, que je ne te laisserai point! Et il se leva, et s’en alla après elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Et Guéhazi les devança, et il mit le bâton sur le visage du jeune garçon, mais il n’y eut pas de voix, pas de signe d’attention. Et il s’en retourna à la rencontre d’Élisée, et lui rapporta, disant: Le jeune garçon ne s’est pas réveillé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Et Élisée entra dans la maison, et voici, le jeune garçon était mort, couché sur son lit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Et il entra, et ferma la porte sur eux deux, et supplia l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Et il monta, et se coucha sur l’enfant, et mit sa bouche sur sa bouche, et ses yeux sur ses yeux, et ses mains sur ses mains, et se courba sur lui; et la chair de l’enfant se réchauffa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Et il se retirait et allait par la maison, tantôt ici, tantôt là; et il montait, et se courbait sur lui. Et le jeune garçon éternua par sept fois, et le jeune garçon ouvrit ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Et [Élisée] appela Guéhazi, et [lui] dit: Appelle cette Sunamite. Et il l’appela, et elle vint vers lui. Et il dit: Prends ton fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Et elle vint et tomba à ses pieds, et se prosterna en terre; et elle prit son fils et sortit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Et Élisée retourna à Guilgal. Or il y avait une famine dans le pays. Et les fils des prophètes étaient assis devant lui; et il dit à son jeune homme: Mets la grande marmite, et cuis un potage pour les fils des prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Et l’un [d’eux] sortit aux champs pour cueillir des herbes, et il trouva de la vigne sauvage et y cueillit des coloquintes sauvages, plein sa robe; et il rentra et les coupa en morceaux dans la marmite du potage, car on ne les connaissait pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Et on versa à manger aux hommes; et il arriva que, comme ils mangeaient du potage, on cria et dit: Homme de Dieu, la mort est dans la marmite! Et ils n’en pouvaient manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Et il dit: Apportez de la farine. Et il la jeta dans la marmite, et dit: Verses-en à ce peuple, et qu’ils mangent. Et il n’y avait rien de mauvais dans la marmite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Et il vint de Baal-Shalisha un homme qui apporta à l’homme de Dieu du pain des premiers fruits, 20 pains d’orge et du grain en épi dans son sac. Et [Élisée] dit: Donne [cela] au peuple, et qu’ils mangent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Et celui qui le servait, dit: Comment mettrai-je ceci devant 100 hommes? Et il dit: Donne-le au peuple, et qu’ils mangent; car ainsi dit l’ Éternel: On mangera, et il y en aura de reste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Et il le mit devant eux, et ils mangèrent, et ils en eurent de reste, selon la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Or Naaman, chef de l’armée du roi de Syrie, était un grand homme devant son seigneur, et considéré, car par lui l’ Éternel avait délivré les Syriens; et cet homme était fort et vaillant, [mais] lépreux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Et les Syriens étaient sortis par bandes, et avaient amené captive du pays d’Israël une petite fille, et elle servait la femme de Naaman.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Et elle dit à sa maîtresse: Oh, si mon seigneur était devant le prophète qui est à Samarie! alors il le délivrerait de sa lèpre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Et [Naaman] vint et [le] rapporta à son seigneur, disant: La jeune fille qui est du pays d’Israël a dit ainsi et ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Et le roi de Syrie dit: Soit! va, et j’enverrai une lettre au roi d’Israël. Et il alla, et prit en sa main dix talents d’argent, et 6 000 [pièces] d’or, et dix vêtements de rechange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Et il apporta au roi d’Israël la lettre, qui disait: Maintenant, quand cette lettre te parviendra, voici, je t’ai envoyé Naaman, mon serviteur, afin que tu le délivres de sa lèpre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Et il arriva que, lorsque le roi d’Israël eut lu la lettre, il déchira ses vêtements, et dit: Suis-je Dieu, pour faire mourir et pour faire vivre, que celui-ci envoie vers moi pour délivrer un homme de sa lèpre? Sachez donc, et voyez qu’il cherche une occasion contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Et il arriva que, lorsque Élisée, homme de Dieu, eut entendu que le roi d’Israël avait déchiré ses vêtements, il envoya dire au roi: Pourquoi as-tu déchiré tes vêtements? Qu’il vienne, je te prie, vers moi, et il saura qu’il y a un prophète en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Et Naaman vint avec ses chevaux et avec son char, et se tint à l’entrée de la maison d’Élisée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Et Élisée envoya vers lui un messager, disant: Va, et lave-toi sept fois dans le Jourdain, et ta chair redeviendra [saine], et tu seras pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Et Naaman se mit en colère, et s’en alla, et dit: Voici, je me disais: Il sortira sans doute, et se tiendra là, et invoquera le nom de l’ Éternel, son Dieu, et il promènera sa main sur la place [malade] et délivrera le lépreux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'L’Abana et le Parpar, rivières de Damas, ne sont-elles pas meilleures que toutes les eaux d’Israël? Ne puis-je pas m’y laver et être pur? Et il se tourna, et s’en alla en colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Et ses serviteurs s’approchèrent de lui, et lui parlèrent, et dirent: Mon père, si le prophète t’avait dit quelque grande chose, ne l’aurais-tu pas faite? Combien plus, quand il t’a dit: Lave-toi, et tu seras pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Et il descendit, et se plongea sept fois dans le Jourdain, selon la parole de l’homme de Dieu; et sa chair redevint comme la chair d’un jeune garçon, et il fut pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Et il retourna vers l’homme de Dieu, lui et tout son camp, et il vint et se tint devant lui, et dit: Voici, je sais qu’il n’y a point de Dieu en toute la terre, sinon en Israël. Et maintenant, je te prie, prends un présent de ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Mais [Élisée] dit: L’ Éternel, devant qui je me tiens, est vivant, que je ne le prendrai pas. Et [Naaman] le pressa de le prendre, mais il refusa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Et Naaman dit: Si cela ne se peut, qu’on donne, je te prie, de [cette] terre à ton serviteur la charge de deux mulets. Car ton serviteur n’offrira plus d’holocauste ni de sacrifice à d’autres dieux, mais seulement à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Qu’en ceci l’ Éternel pardonne à ton serviteur: quand mon seigneur entrera dans la maison de Rimmon pour s’y prosterner, et qu’il s’appuiera sur ma main, et que je me prosternerai dans la maison de Rimmon, que l’ Éternel, je te prie, pardonne à ton serviteur en ceci, quand je me prosternerai dans la maison de Rimmon!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Et il lui dit: Va en paix. Et il s’en alla d’avec lui un bout de chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Et Guéhazi, le jeune homme d’Élisée, homme de Dieu, dit: Voici, mon maître a épargné Naaman, ce Syrien, en ne prenant pas de sa main ce qu’il avait apporté; l’ Éternel est vivant, si je ne cours après lui, et si je ne prends de lui quelque chose!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Et Guéhazi poursuivit Naaman: et Naaman vit qu’il courait après lui; et il descendit de son char à sa rencontre, et [lui] dit: Tout va-t-il bien?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Et il dit: Bien. Mon maître m’a envoyé, disant: Voici, dans ce moment, deux jeunes hommes d’entre les fils des prophètes sont venus vers moi, de la montagne d’Éphraïm; donne-leur, je te prie, un talent d’argent et deux vêtements de rechange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Et Naaman dit: Consens à prendre deux talents. Et il le pressa avec insistance; et il lia deux talents d’argent dans deux sacs, et deux vêtements de rechange, et il les donna à deux de ses jeunes hommes; et ils les portèrent devant Guéhazi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Et quand il fut arrivé à la colline, il les prit de leurs mains, et les serra dans la maison; et il renvoya les hommes et ils s’en allèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Et lui, il entra et se tint devant son maître. Et Élisée lui dit: D’où [viens-tu], Guéhazi? Et il dit: Ton serviteur n’est allé nulle part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Et [Élisée] lui dit: Mon cœur n’est-il pas allé, quand l’homme s’est retourné de dessus son char à ta rencontre? Est-ce le temps de prendre de l’argent, et de prendre des vêtements, et des oliviers, et des vignes, et du menu et du gros bétail, et des serviteurs et des servantes?...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'La lèpre de Naaman s’attachera à toi et à ta semence pour toujours. Et [Guéhazi] sortit de devant lui, lépreux, [blanc] comme la neige.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Et les fils des prophètes dirent à Élisée: Tu vois que le lieu où nous habitons devant toi est trop étroit pour nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Allons, s’il te plaît, jusqu’au Jourdain, et nous y prendrons chacun une pièce de bois, et nous y bâtirons un lieu pour y habiter. Et il dit: Allez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Et l’un d’eux dit: Consens, je te prie, à venir avec tes serviteurs. Et il dit: J’irai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Et il alla avec eux; et ils vinrent au Jourdain, et coupèrent des arbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Et il arriva, comme l’un d’eux abattait une pièce de bois, que le fer tomba dans l’eau; et il s’écria et dit: Hélas, mon maître! il était emprunté!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Et l’homme de Dieu dit: Où est-il tombé? Et il lui montra l’endroit; et [Élisée] coupa un morceau de bois, et l’y jeta, et fit surnager le fer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'et il dit: Enlève-le. Et il étendit sa main, et le prit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Or le roi de Syrie faisait la guerre contre Israël; et il tint conseil avec ses serviteurs, disant: En tel et tel lieu sera mon camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Et l’homme de Dieu envoya au roi d’Israël, disant: Garde-toi de passer par ce lieu-là; car les Syriens y sont descendus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Et le roi d’Israël envoya au lieu au sujet duquel l’homme de Dieu lui avait parlé et l’avait averti, et il y fut gardé. [Cela eut lieu] non pas une fois, ni deux fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Et le cœur du roi de Syrie fut agité à cause de cela; et il appela ses serviteurs, et leur dit: Ne me déclarerez-vous pas qui d’entre nous est pour le roi d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Et l’un de ses serviteurs [lui] dit: Personne, ô roi, mon seigneur! mais Élisée, le prophète qui est en Israël, déclare au roi d’Israël les paroles que tu dis dans ta chambre à coucher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Et il dit: Allez, et voyez où il est, et j’enverrai et je le prendrai. Et on lui rapporta, disant: Le voilà à Dothan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Et il y envoya des chevaux, et des chars, et de grandes forces; et ils allèrent de nuit, et environnèrent la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Et celui qui servait l’homme de Dieu se leva de bon matin et sortit: et voici, une armée entourait la ville, et des chevaux, et des chars. Et son jeune homme lui dit: Hélas! mon seigneur, comment ferons-nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Et il dit: Ne crains pas; car ceux qui sont avec nous sont en plus grand nombre que ceux qui sont avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Et Élisée pria, et dit: Éternel, je te prie, ouvre ses yeux, afin qu’il voie. Et l’ Éternel ouvrit les yeux du jeune homme, et il vit: et voici la montagne était pleine de chevaux et de chars de feu autour d’Élisée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Et [les Syriens] descendirent vers Élisée; et il pria l’ Éternel, et dit: Je te prie, frappe cette nation de cécité. Et il les frappa de cécité, selon la parole d’Élisée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Et Élisée leur dit: Ce n’est pas ici le chemin, et ce n’est pas ici la ville; venez après moi, et je vous mènerai vers l’homme que vous cherchez. Et il les mena à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Et il arriva, quand ils furent entrés à Samarie, qu’Élisée dit: Éternel, ouvre les yeux à ces [hommes], afin qu’ils voient. Et l’ Éternel ouvrit leurs yeux, et ils virent: et voici, [ils étaient] au milieu de Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Et le roi d’Israël dit à Élisée, quand il les vit: Frapperai-je, frapperai-je, mon père?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Et il dit: Tu ne frapperas point; ceux que tu aurais faits captifs avec ton épée et ton arc, les frapperais-tu? Mets du pain et de l’eau devant eux; et qu’ils mangent et boivent, et qu’ils s’en aillent vers leur seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Et il leur prépara un grand festin, et ils mangèrent et burent; et il les renvoya, et ils s’en allèrent vers leur seigneur. Et les bandes des Syriens ne revinrent plus dans le pays d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Et il arriva, après cela, que Ben-Hadad, roi de Syrie, rassembla toute son armée, et monta, et assiégea Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Et il y eut une grande famine dans Samarie; et voici, ils la serraient de près, jusqu’à ce que la tête d’un âne fut à 80 [sicles] d’argent, et le quart d’un kab de fiente de pigeon à cinq [sicles] d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Et il arriva, comme le roi d’Israël passait sur la muraille, qu’une femme lui cria, disant: Sauve-moi, ô roi, mon seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Et il dit: Si l’ Éternel ne te sauve pas, comment te sauverais-je? Serait-ce au moyen de l’aire ou de la cuve?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Et le roi lui dit: Qu’as-tu? Et elle dit: Cette femme-là m’a dit: Donne ton fils, et nous le mangerons aujourd’hui; et demain nous mangerons mon fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Et nous avons bouilli mon fils, et nous l’avons mangé; et le jour après, je lui ai dit: Donne ton fils, et nous le mangerons. Et elle a caché son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Et aussitôt que le roi entendit les paroles de la femme, il déchira ses vêtements. Et comme il passait sur la muraille, le peuple le vit: et voici, il avait un sac sur sa chair, en dedans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Et [le roi] dit: Ainsi Dieu me fasse, et ainsi il y ajoute, si la tête d’Élisée, fils de Shaphath, demeure sur lui aujourd’hui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Et Élisée était assis dans sa maison, et les anciens étaient assis avec lui, et [le roi] envoya un homme devant lui. Avant que le messager arrive auprès de lui, [Élisée] dit aux anciens: Voyez-vous que ce fils d’un meurtrier envoie pour m’ôter la tête? Voyez quand le messager entrera; fermez la porte, et repoussez-le avec la porte: n’est-ce pas le bruit des pieds de son maître après lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Il parlait encore avec eux, quand voici, le messager descendit vers lui. Et [le roi] dit: Voici, ce mal est de par l’ Éternel; pourquoi m’attendrais-je encore à l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Et Élisée dit: Écoutez la parole de l’ Éternel. Ainsi dit l’ Éternel: Demain à cette heure-ci, la mesure de fleur de farine sera à un sicle, et les deux mesures d’orge à un sicle, à la porte de Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Et le capitaine, sur la main duquel le roi s’appuyait, répondit à l’homme de Dieu, et dit: Voici, quand l’ Éternel ferait des fenêtres aux cieux, cela arriverait-il? Et [Élisée] dit: Voici, tu le verras de tes yeux, mais tu n’en mangeras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Et il y avait à l’entrée de la porte quatre hommes lépreux, et ils se dirent l’un à l’autre: Pourquoi sommes-nous assis ici jusqu’à ce que nous mourions?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Si nous disons: Entrons dans la ville, la famine est dans la ville, et nous y mourrons; et si nous restons assis ici, nous mourrons. Et maintenant, venez, et passons dans le camp des Syriens: s’ils nous laissent vivre, nous vivrons; et s’ils nous font mourir, nous mourrons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Et ils se levèrent au crépuscule pour entrer dans le camp des Syriens; et ils vinrent jusqu’au bout du camp des Syriens, et voici, il n’y avait personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Car le Seigneur avait fait entendre dans le camp des Syriens un bruit de chars et un bruit de chevaux, le bruit d’une grande armée; et ils se dirent l’un à l’autre: Voici, le roi d’Israël a pris à sa solde contre nous les rois des Héthiens et les rois des Égyptiens, pour venir sur nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Et ils se levèrent au crépuscule, et s’enfuirent; et ils abandonnèrent leurs tentes, et leurs chevaux, et leurs ânes, le camp tel quel; et ils s’enfuirent pour [sauver] leur vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Et ces lépreux vinrent jusqu’au bout du camp; et ils entrèrent dans une tente, et mangèrent et burent, et en emportèrent de l’argent, et de l’or, et des vêtements; et ils s’en allèrent et les cachèrent. Et ils retournèrent, et entrèrent dans une autre tente et en emportèrent [du butin], et ils s’en allèrent et le cachèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Et ils se dirent l’un à l’autre: Nous ne faisons pas bien. Ce jour est un jour de bonnes nouvelles, et nous nous taisons. Si nous attendons jusqu’à la lumière du matin, l’iniquité nous trouvera. Et maintenant, venez, allons et rapportons-le à la maison du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Et ils vinrent et crièrent aux portiers de la ville, et leur rapportèrent, disant: Nous sommes venus dans le camp des Syriens; et voici, il n’y avait personne, ni voix d’homme, seulement les chevaux attachés, et les ânes attachés, et les tentes comme elles étaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Et les portiers le crièrent et le rapportèrent dans la maison du roi, à l’intérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Et le roi se leva de nuit, et dit à ses serviteurs: Je veux vous dire ce que les Syriens nous ont fait: ils savent que nous avons faim, et ils sont sortis du camp pour se cacher dans les champs, disant: Ils sortiront hors de la ville, et nous les prendrons vivants, et nous entrerons dans la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Et un de ses serviteurs répondit et dit: Qu’on prenne donc cinq des chevaux restants, qui demeurent de reste dans la [ville]; voici, ils sont comme toute la multitude d’Israël qui est de reste en elle; voici, ils sont comme toute la multitude d’Israël qui a péri. Envoyons-les, et nous verrons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Et ils prirent deux chars avec leurs chevaux, et le roi envoya après le camp des Syriens, disant: Allez et voyez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Et ils s’en allèrent après eux jusqu’au Jourdain; et voici, tout le chemin était plein de vêtements et d’objets que les Syriens avaient jetés dans leur fuite précipitée; et les messagers s’en retournèrent et le rapportèrent au roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Et le peuple sortit, et pilla le camp des Syriens: et la mesure de fleur de farine fut à un sicle, et les deux mesures d’orge à un sicle, selon la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Et le roi avait préposé à la garde de la porte le capitaine sur la main duquel il s’appuyait; et le peuple le foula aux pieds dans la porte, et il mourut, selon ce qu’avait dit l’homme de Dieu, ce qu’il avait dit quand le roi était descendu vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Et il arriva selon la parole que l’homme de Dieu avait adressée au roi, disant: Les deux mesures d’orge seront à un sicle, et la mesure de fleur de farine sera à un sicle, demain à cette heure-ci, à la porte de Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Et le capitaine avait répondu à l’homme de Dieu, et avait dit: Voici, quand l’ Éternel ferait des fenêtres aux cieux, pareille chose arriverait-elle? Et il dit: Voici, tu le verras de tes yeux, mais tu n’en mangeras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Et il lui en arriva ainsi: le peuple le foula aux pieds dans la porte, et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Et Élisée parla à la femme, au fils de laquelle il avait rendu la vie, disant: Lève-toi, et va-t’en, toi et ta maison, et séjourne où tu pourras séjourner; car l’ Éternel a appelé la famine, et même elle viendra sur le pays pour sept ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Et la femme se leva et fit selon la parole de l’homme de Dieu, et s’en alla, elle et sa maison, et séjourna au pays des Philistins sept ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Et il arriva, au bout de sept ans, que la femme s’en revint du pays des Philistins. Et elle sortit pour crier au roi au sujet de sa maison et de ses champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Et le roi parlait à Guéhazi, serviteur de l’homme de Dieu, disant: Raconte-moi, je te prie, toutes les grandes choses qu’Élisée a faites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Et il arriva que, tandis qu’il racontait au roi comment il avait rendu la vie à un mort, voici, la femme au fils de laquelle il avait rendu la vie, vint crier au roi au sujet de sa maison et de ses champs. Et Guéhazi dit: Ô roi, mon seigneur! c’est ici la femme, et c’est ici son fils auquel Élisée a rendu la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Et le roi interrogea la femme, et elle lui raconta [tout]. Et le roi lui donna un eunuque, disant: Rends-lui tout ce qui lui appartient, et tout le revenu des champs, depuis le jour où elle a quitté le pays, jusqu’à maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Et Élisée vint à Damas; et Ben-Hadad, roi de Syrie, était malade, et on lui rapporta, disant: L’homme de Dieu est venu jusqu’ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Et le roi dit à Hazaël: Prends dans ta main un présent, et va à la rencontre de l’homme de Dieu, et consulte par lui l’ Éternel, disant: Relèverai-je de cette maladie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Et Hazaël alla à sa rencontre, et prit dans sa main un présent de toutes les bonnes choses de Damas, la charge de 40 chameaux; et il vint, et se tint devant lui, et dit: Ton fils Ben-Hadad, roi de Syrie, m’a envoyé vers toi, disant: Relèverai-je de cette maladie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Et Élisée lui dit: Va, dis-lui: Certainement tu en relèveras. Mais l’ Éternel m’a montré qu’il mourra certainement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Et il arrêta sa face et la fixa [sur lui], jusqu’à ce qu’il fut confus; puis l’homme de Dieu pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Et Hazaël dit: Pourquoi mon seigneur pleure-t-il? Et il dit: Parce que je sais le mal que tu feras aux fils d’Israël: tu mettras le feu à leurs villes fortes, et tu tueras avec l’épée leurs jeunes hommes, et tu écraseras leurs petits enfants, et tu fendras le ventre à leurs femmes enceintes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Et Hazaël dit: Mais qu’est ton serviteur, un chien, pour qu’il fasse cette grande chose? Et Élisée dit: L’ Éternel m’a montré que tu seras roi sur la Syrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Et il s’en alla d’avec Élisée, et vint vers son maître; et [Ben-Hadad] lui dit: Que t’a dit Élisée? Et il dit: Il m’a dit que certainement tu en relèveras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Et il arriva le lendemain, qu’il prit la couverture, et la plongea dans l’eau, et l’étendit sur le visage du roi; et il mourut. Et Hazaël régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, '*Et la cinquième année de Joram, fils d’Achab, roi d’Israël, et Josaphat étant roi de Juda, Joram, fils de Josaphat, roi de Juda, commença de régner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Il était âgé de 32 ans lorsqu’il commença de régner; et il régna huit ans à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Et il marcha dans la voie des rois d’Israël, selon ce que faisait la maison d’Achab, car il avait pour femme une fille d’Achab; et il fit ce qui est mauvais aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Mais l’ Éternel ne voulut point détruire Juda, à cause de David, son serviteur, selon ce qu’il lui avait dit, qu’il lui donnerait une lampe pour ses fils, à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'En ses jours, Édom se révolta de dessous la main de Juda, et ils établirent un roi sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Et Joram passa à Tsaïr, et tous les chars avec lui; et il se leva de nuit, et frappa Édom qui l’avait entouré, et les chefs des chars; et le peuple s’enfuit à ses tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Mais Édom se révolta de dessous la main de Juda, jusqu’à ce jour. Alors, dans ce même temps, Libna se révolta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Et le reste des actes de Joram, et tout ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Et Joram s’endormit avec ses pères, et fut enterré avec ses pères dans la ville de David; et Achazia, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, '*La douzième année de Joram, fils d’Achab, roi d’Israël, Achazia, fils de Joram, roi de Juda, commença de régner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Achazia était âgé de 22 ans lorsqu’il commença de régner; et il régna un an à Jérusalem; et le nom de sa mère était Athalie, fille d’Omri, roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Et il marcha dans la voie de la maison d’Achab et fit ce qui est mauvais aux yeux de l’ Éternel, comme la maison d’Achab; car il était gendre de la maison d’Achab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Et il alla avec Joram, fils d’Achab, à la guerre contre Hazaël, roi de Syrie, à Ramoth de Galaad. Et les Syriens blessèrent Joram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Et le roi Joram s’en retourna à Jizreël pour se faire guérir des blessures que les Syriens lui avaient faites à Rama, lorsqu’il combattait contre Hazaël, roi de Syrie; et Achazia, fils de Joram, roi de Juda, descendit à Jizreël pour voir Joram, fils d’Achab, parce qu’il était malade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, '*Et Élisée, le prophète, appela un des fils des prophètes, et lui dit: Ceins tes reins, et prends cette fiole d’huile en ta main, et va-t’en à Ramoth de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Et entre là, et vois-y Jéhu, fils de Josaphat, fils de Nimshi; et tu entreras, et tu le feras lever du milieu de ses frères, et tu le mèneras dans une chambre intérieure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Et tu prendras la fiole d’huile, et tu la verseras sur sa tête, et tu diras: Ainsi dit l’ Éternel: Je t’oins roi sur Israël. Et tu ouvriras la porte, et tu t’enfuiras, et tu n’attendras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Et le jeune homme, le jeune prophète, s’en alla à Ramoth de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Et il entra, et voici, les chefs de l’armée étaient assis; et il dit: Chef, j’ai une parole pour toi. Et Jéhu dit: Pour qui de nous tous? Et il dit: Pour toi, chef.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Et [Jéhu] se leva, et entra dans la maison. Et [le jeune homme] versa l’huile sur sa tête, et lui dit: Ainsi dit l’ Éternel, le Dieu d’Israël: Je t’oins roi sur le peuple de l’ Éternel, sur Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'et tu frapperas la maison d’Achab, ton seigneur; et je vengerai, de la main de Jézabel, le sang de mes serviteurs les prophètes et le sang de tous les serviteurs de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Et toute la maison d’Achab périra; et je retrancherai à Achab tous les mâles, l’homme lié et l’homme libre en Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'et je rendrai la maison d’Achab semblable à la maison de Jéroboam, fils de Nebath, et à la maison de Baësha, fils d’Akhija;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'et les chiens mangeront Jézabel dans le champ de Jizreël, et il n’y aura personne qui l’enterre. Et il ouvrit la porte et s’enfuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Et Jéhu sortit vers les serviteurs de son seigneur, et on lui dit: Tout va-t-il bien? Pourquoi ce fou est-il venu vers toi? Et il leur dit: Vous connaissez l’homme et sa pensée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Et ils dirent: Mensonge! Dis-le-nous donc. Et il dit: Il m’a parlé de telle et telle manière, disant: Ainsi dit l’ Éternel: Je t’ai oint roi sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Et ils se hâtèrent, et prirent chacun son vêtement, et les mirent sous lui sur les degrés mêmes; et ils sonnèrent de la trompette, et dirent: Jéhu est roi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Et Jéhu, fils de Josaphat, fils de Nimshi, conspira contre Joram. (Et Joram gardait Ramoth de Galaad, lui et tout Israël, à cause de Hazaël, roi de Syrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Et le roi Joram s’en était retourné à Jizreël pour se faire guérir des blessures que les Syriens lui avaient faites lorsqu’il combattait contre Hazaël, roi de Syrie.) Et Jéhu dit: Si c’est votre pensée, que personne ne s’échappe de la ville et ne sorte pour aller raconter [la nouvelle] à Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Et Jéhu monta en char, et s’en alla à Jizreël, car Joram y était alité; et Achazia, roi de Juda, était descendu pour voir Joram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Et la sentinelle se tenait sur la tour à Jizreël, et vit la troupe de Jéhu, comme il arrivait, et dit: Je vois une troupe [de gens]. Et Joram dit: Prends un cavalier, et envoie-le à leur rencontre, et qu’il dise: Est-ce la paix?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Et l’homme à cheval partit à sa rencontre, et dit: Ainsi a dit le roi: Est-ce la paix? Et Jéhu dit: Qu’as-tu à faire de la paix? Tourne, [et passe] derrière moi. Et la sentinelle annonça, disant: Le messager est venu jusqu’à eux, et il ne revient pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Et il envoya un second homme à cheval; et il vint à eux, et dit: Ainsi dit le roi: Est-ce la paix? Et Jéhu dit: Qu’as-tu à faire de la paix? Tourne, [et passe] derrière moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Et la sentinelle annonça, disant: Il est venu jusqu’à eux, et ne revient pas. Et la manière de conduire est celle de Jéhu, fils de Nimshi; car il conduit avec furie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Et Joram dit: Qu’on attelle. Et on attela son char. Et Joram, roi d’Israël, sortit, et Achazia, roi de Juda, chacun dans son char; et ils sortirent à la rencontre de Jéhu, et le trouvèrent dans le champ de Naboth, Jizreélite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Et il arriva que, quand Joram vit Jéhu, il dit: Est-ce la paix, Jéhu? Et il dit: Quelle paix,... aussi longtemps que les prostitutions de Jézabel, ta mère, et ses enchantements sont en si grand nombre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Et Joram tourna sa main, et s’enfuit, et dit à Achazia: Trahison, Achazia!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Et Jéhu prit son arc en main, et frappa Joram entre les bras, et la flèche sortit au travers de son cœur; et il s’affaissa dans son char.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Et [Jéhu] dit à Bidkar, son lieutenant: Prends-le, [et] jette-le dans la portion de champ de Naboth, le Jizreélite; car souviens-toi que, quand moi et toi, nous étions en char tous les deux, à la suite d’Achab, son père, l’ Éternel prononça cet oracle contre lui:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'N’ai-je pas vu hier le sang de Naboth et le sang de ses fils, dit l’ Éternel? et je te le rendrai dans ce champ-ci, dit l’ Éternel. Et maintenant, prends-le [et] jette-le dans le champ, selon la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Et Achazia, roi de Juda, vit [cela], et s’enfuit par le chemin de la maison du jardin; et Jéhu le poursuivit, et dit: Frappez-le, lui aussi, sur le char. [Ils le frappèrent] à la montée de Gur, qui est près de Jibleam; et il s’enfuit à Meguiddo, et y mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Et ses serviteurs le transportèrent sur un char à Jérusalem, et l’enterrèrent dans son sépulcre, avec ses pères, dans la ville de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Or la onzième année de Joram, fils d’Achab, Achazia avait commencé de régner sur Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Et Jéhu vint à Jizreël; et Jézabel l’apprit, et mit du fard à ses yeux, et orna sa tête, et regarda par la fenêtre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Et Jéhu entra dans la porte, et elle dit: Est-ce la paix, Zimri, assassin de son seigneur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Et il leva sa face vers la fenêtre, et dit: Qui est pour moi? Qui? Et deux ou trois eunuques regardèrent vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Et il dit: Jetez-la en bas. Et ils la jetèrent, et il rejaillit de son sang contre la muraille et contre les chevaux; et il la foula aux pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Et il entra, et mangea et but; et il dit: Allez donc voir cette maudite, et enterrez-la, car elle est fille de roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Et ils s’en allèrent pour l’enterrer, mais ils ne trouvèrent rien d’elle que le crâne, et les pieds, et les paumes des mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Et ils revinrent et le lui rapportèrent; et il dit: C’est la parole de l’ Éternel, qu’il a dite par son serviteur Élie, le Thishbite, disant: Dans le champ de Jizreël, les chiens mangeront la chair de Jézabel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'et le cadavre de Jézabel sera comme du fumier sur la face des champs, dans le champ de Jizreël, en sorte qu’on ne dira pas: C’est ici Jézabel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Or Achab avait 70 fils à Samarie; et Jéhu écrivit des lettres, et les envoya à Samarie aux chefs de Jizreël, aux anciens, et aux gouverneurs des enfants d’Achab, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Maintenant, quand cette lettre vous sera parvenue, puisque vous avez avec vous les fils de votre seigneur, et que vous avez les chars et les chevaux, et une ville forte et des armes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'regardez lequel des fils de votre seigneur est le meilleur et le plus apte, et mettez-le sur le trône de son père, et combattez pour la maison de votre seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Et ils eurent extrêmement peur, et dirent: Voici, les deux rois n’ont pu tenir devant lui, et nous, comment tiendrions-nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Et celui qui était préposé sur la maison, et celui qui était préposé sur la ville, et les anciens, et les gouverneurs des enfants, envoyèrent à Jéhu, disant: Nous sommes tes serviteurs, et tout ce que tu nous diras, nous le ferons; nous n’établirons roi personne; fais ce qui est bon à tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Et il leur écrivit une lettre pour la seconde fois, disant: Si vous êtes à moi et si vous écoutez ma voix, prenez les têtes des hommes, fils de votre seigneur, et venez vers moi demain à cette heure-ci, à Jizreël. Et les fils du roi, 70 hommes, étaient avec les grands de la ville, qui les élevaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Et il arriva que, quand la lettre leur parvint, ils prirent les fils du roi et les égorgèrent, 70 hommes; et ils mirent leurs têtes dans des corbeilles et les lui envoyèrent à Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Et un messager vint, et le lui rapporta, disant: Ils ont apporté les têtes des fils du roi. Et il dit: Mettez-les en deux tas à l’entrée de la porte, jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Et il arriva que, le matin, il sortit, et se tint là, et dit à tout le peuple: Vous êtes justes: voici, j’ai conspiré contre mon seigneur et je l’ai tué; mais qui a frappé tous ceux-ci?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Sachez donc que rien ne tombera en terre de la parole de l’ Éternel que l’ Éternel a prononcée contre la maison d’Achab; et l’ Éternel a fait ce qu’il avait dit par son serviteur Élie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Et Jéhu frappa tous ceux qui restaient de la maison d’Achab à Jizreël, et tous ses grands, et tous ceux qui étaient de sa connaissance, et ses sacrificateurs, jusqu’à ne pas lui laisser un réchappé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Et il se leva et partit, et s’en alla à Samarie. Et comme il était près de la cabane des bergers sur le chemin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Jéhu trouva les frères d’Achazia, roi de Juda, et dit: Qui êtes-vous? Et ils dirent: Nous sommes les frères d’Achazia, et nous sommes descendus pour saluer les fils du roi et les fils de la reine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Et il dit: Saisissez-les vivants. Et ils les saisirent vivants, et les égorgèrent, 42 hommes, près du puits de la cabane, et il n’en laissa pas un seul de reste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Et il s’en alla de là, et trouva Jonadab, fils de Récab, qui venait à sa rencontre; et il le salua, et lui dit: Ton cœur est-il droit comme mon cœur l’est à l’égard de ton cœur? Et Jonadab dit: Il l’est. – S’il l’est, donne-moi ta main. – Et il lui donna sa main, et [Jéhu] le fit monter auprès de lui dans le char,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'et dit: Viens avec moi, et vois mon zèle pour l’ Éternel. Et on le mena dans le char de Jéhu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Et [Jéhu] arriva à Samarie; et il frappa tous ceux qui restaient d’Achab à Samarie, jusqu’à ce qu’il l’ait détruit, selon la parole de l’ Éternel qu’il avait dite à Élie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Et Jéhu assembla tout le peuple, et leur dit: Achab a servi Baal un peu; Jéhu le servira beaucoup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Et maintenant, appelez vers moi tous les prophètes de Baal, tous ses serviteurs et tous ses sacrificateurs; que pas un ne manque, car j’ai [à offrir] un grand sacrifice à Baal. Quiconque manquera ne vivra point. Et Jéhu agissait avec ruse, afin de faire périr les serviteurs de Baal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Et Jéhu dit: Sanctifiez une fête solennelle à Baal. Et ils la publièrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Et Jéhu envoya par tout Israël; et tous les serviteurs de Baal vinrent: et il n’en resta pas un qui ne vienne; et ils entrèrent dans la maison de Baal, et la maison de Baal fut remplie d’un bout à l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Et il dit à celui qui était [préposé] sur le vestiaire: Sors des vêtements pour tous les serviteurs de Baal. Et il leur sortit des vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Et Jéhu et Jonadab, fils de Récab, entrèrent dans la maison de Baal, et [Jéhu] dit aux serviteurs de Baal: Examinez et voyez, afin qu’il n’y ait pas ici avec vous quelqu’un des serviteurs de l’ Éternel, mais seulement des serviteurs de Baal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Et ils entrèrent pour offrir des sacrifices et des holocaustes. Et Jéhu plaça par-dehors 80 hommes, et il [leur] dit: Celui qui laissera échapper [un seul] d’entre les hommes que j’ai mis entre vos mains, sa vie sera pour la vie de cet homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Et il arriva que, quand on eut achevé d’offrir l’holocauste, Jéhu dit aux coureurs et aux capitaines: Entrez, frappez-les; que pas un ne sorte. Et ils les frappèrent par le tranchant de l’épée. Et les coureurs et les capitaines les jetèrent là; et ils s’en allèrent jusqu’à la ville de la maison de Baal,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'et tirèrent les stèles hors de la maison de Baal, et les brûlèrent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'et ils abattirent la stèle de Baal, et ils abattirent la maison de Baal, et en firent des cloaques, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Ainsi Jéhu extermina Baal du milieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Seulement, quant aux péchés de Jéroboam, fils de Nebath, par lesquels il avait fait pécher Israël – [savoir] les veaux d’or qui étaient à Béthel et à Dan – Jéhu ne s’en détourna pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Et l’ Éternel dit à Jéhu: Parce que tu as bien exécuté ce qui était droit à mes yeux, [et] que tu as fait à la maison d’Achab selon tout ce qui était dans mon cœur, tes fils, jusqu’à la quatrième génération, seront assis sur le trône d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Mais Jéhu ne prit pas garde à marcher de tout son cœur dans la loi de l’ Éternel, le Dieu d’Israël; il ne se détourna pas des péchés de Jéroboam, par lesquels il avait fait pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'En ces jours-là, l’ Éternel commença à entamer Israël; et Hazaël les frappa dans toutes les frontières d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'depuis le Jourdain, vers le soleil levant, tout le pays de Galaad, les Gadites, et les Rubénites, et les Manassites, depuis Aroër qui est sur le torrent de l’Arnon, et Galaad, et Basan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Et le reste des actes de Jéhu, et tout ce qu’il fit, et toute sa puissance, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Et Jéhu s’endormit avec ses pères, et on l’enterra à Samarie; et Joakhaz, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Et les jours que Jéhu régna sur Israël à Samarie furent 28 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, '*Or Athalie, mère d’Achazia, vit que son fils était mort, et elle se leva et fit périr toute la semence royale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Mais Jehoshéba, fille du roi Joram, sœur d’Achazia, prit Joas, fils d’Achazia, et le déroba du milieu des fils du roi qu’on mettait à mort [et le cacha], lui et sa nourrice, dans la chambre à coucher; et on le cacha de devant Athalie, et il ne fut pas mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Et il fut caché six ans auprès d’elle dans la maison de l’ Éternel. Et Athalie régna sur le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Et la septième année, Jehoïada envoya, et prit les chefs de centaines des gardes et des coureurs; et il les fit entrer vers lui dans la maison de l’ Éternel, et fit un pacte avec eux et les fit jurer dans la maison de l’ Éternel, et leur montra le fils du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Et il leur commanda, disant: C’est ici ce que vous ferez: un tiers d’entre vous qui entrez le [jour du] sabbat, fera la garde de la maison du roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'et un tiers sera à la porte de Sur; et un tiers sera à la porte qui est derrière les coureurs; et vous veillerez à la garde de la maison, pour tenir à distance [tout étranger].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Et les deux tiers d’entre vous, tous ceux qui sortent le [jour du] sabbat, feront la garde de la maison de l’ Éternel, auprès du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Et vous entourerez le roi de tous côtés, chacun ses armes à la main; et celui qui entrera dans les rangs sera mis à mort; et soyez avec le roi quand il sortira et quand il entrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Et les chefs de centaines firent selon tout ce que Jehoïada, le sacrificateur, avait commandé; et ils prirent chacun ses hommes, ceux qui entraient le [jour du] sabbat et ceux qui sortaient le [jour du] sabbat; et ils vinrent auprès de Jehoïada, le sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Et le sacrificateur donna aux chefs de centaines les lances et les boucliers qui avaient appartenu au roi David, et qui étaient dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Et les coureurs se tinrent là, chacun ses armes à la main, depuis le côté droit de la maison jusqu’au côté gauche de la maison, vers l’autel et vers la maison, auprès du roi, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Et on fit sortir le fils du roi, et on mit sur lui la couronne et le témoignage; et ils le firent roi, et l’oignirent, et frappèrent des mains, et dirent: Vive le roi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Et Athalie entendit le cri des coureurs [et] du peuple, et elle entra vers le peuple dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Et elle regarda, et voici, le roi se tenait sur l’estrade, suivant l’usage, et les chefs et les trompettes étaient auprès du roi, et tout le peuple du pays se réjouissait et sonnait des trompettes. Et Athalie déchira ses vêtements, et s’écria: Conspiration! Conspiration!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Et Jehoïada, le sacrificateur, commanda aux chefs de centaines qui étaient préposés sur l’armée, et leur dit: Faites-la sortir en dehors des rangs, et celui qui la suivra mettez-le à mort par l’épée; car le sacrificateur dit: Qu’elle ne soit pas mise à mort dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Et ils lui firent place; et elle alla par le chemin de l’entrée des chevaux dans la maison du roi, et là elle fut mise à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Et Jehoïada fit une alliance entre l’ Éternel et le roi et le peuple, qu’ils seraient le peuple de l’ Éternel, – et entre le roi et le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Et tout le peuple du pays entra dans la maison de Baal, et ils la démolirent; ses autels et ses images, ils les brisèrent entièrement; et ils tuèrent devant les autels Matthan, sacrificateur de Baal. Et le sacrificateur établit des gardes sur la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Et il prit les chefs de centaines, et les gardes, et les coureurs, et tout le peuple du pays, et ils firent descendre le roi de la maison de l’ Éternel, et entrèrent dans la maison du roi par le chemin de la porte des coureurs; et il s’assit sur le trône des rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Et tout le peuple du pays se réjouit, et la ville fut tranquille: et ils avaient mis à mort Athalie par l’épée, dans la maison du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Joas était âgé de sept ans lorsqu’il commença de régner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, '*La septième année de Jéhu, Joas commença de régner; et il régna 40 ans à Jérusalem; et le nom de sa mère était Tsibia, de Beër-Shéba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Et Joas fit ce qui est droit aux yeux de l’ Éternel, tous les jours que Jehoïada, le sacrificateur, l’instruisit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Seulement les hauts lieux ne furent pas ôtés; le peuple sacrifiait encore et faisait fumer de l’encens sur les hauts lieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Et Joas dit aux sacrificateurs: Tout l’argent des choses saintes qui est apporté dans la maison de l’ Éternel, l’argent de tout homme qui passe [par le dénombrement], l’argent des âmes selon l’estimation de chacun, tout argent qu’il monte au cœur de chacun d’apporter dans la maison de l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'que les sacrificateurs le prennent, chacun de la part [des gens] de sa connaissance, et qu’ils réparent les brèches de la maison, partout où il se trouvera des brèches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Et il arriva, la vingt -troisième année du roi Joas, que les sacrificateurs n’avaient point réparé les brèches de la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Et le roi Joas appela Jehoïada, le sacrificateur, et les [autres] sacrificateurs, et il leur dit: Pourquoi n’avez-vous pas réparé les brèches de la maison? Et maintenant, ne prenez pas d’argent de vos connaissances, mais vous le donnerez pour les brèches de la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Et les sacrificateurs consentirent à ne plus prendre d’argent de la part du peuple, et que seulement on répare les brèches de la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Et Jehoïada, le sacrificateur, prit un coffre et fit un trou dans son couvercle, et le mit à côté de l’autel, à droite quand on entre dans la maison de l’ Éternel; et les sacrificateurs qui gardaient le seuil mettaient là tout l’argent qui était apporté à la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Et il arrivait que, lorsqu’ils voyaient qu’il y avait beaucoup d’argent dans le coffre, le secrétaire du roi montait, et le grand sacrificateur, et ils serraient et comptaient l’argent qui était trouvé dans la maison de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'et ils remettaient l’argent pesé entre les mains de ceux qui faisaient l’ouvrage, qui étaient établis sur la maison de l’ Éternel, et ceux-ci le livraient aux charpentiers et aux constructeurs qui travaillaient à la maison de l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'et aux maçons, et aux tailleurs de pierres, pour acheter des bois et des pierres de taille, afin de réparer les brèches de la maison de l’ Éternel, et pour tout ce qui se dépensait pour la maison afin de la réparer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Toutefois on ne fit pas pour la maison de l’ Éternel des écuelles d’argent, des couteaux, des bassins, des trompettes, ni aucun ustensile d’or ou ustensile d’argent, avec l’argent qu’on apportait dans la maison de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'mais on le donnait à ceux qui faisaient l’ouvrage, et ils l’employaient à réparer la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Et on ne comptait pas avec les hommes entre les mains desquels on remettait l’argent pour le donner à ceux qui faisaient l’ouvrage, car ils agissaient fidèlement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'L’argent des sacrifices pour le délit et l’argent des sacrifices pour le péché n’était point apporté dans la maison de l’ Éternel; il était pour les sacrificateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Alors Hazaël, roi de Syrie, monta, et fit la guerre contre Gath, et la prit; et Hazaël tourna sa face pour monter contre Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Et Joas, roi de Juda, prit toutes les choses saintes, que Josaphat, et Joram, et Achazia, ses pères, rois de Juda, avaient consacrées, et celles qu’il avait lui-même consacrées, et tout l’or qui se trouvait dans les trésors de la maison de l’ Éternel et de la maison du roi, et les envoya à Hazaël, roi de Syrie: et il se retira de devant Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Et le reste des actes de Joas, et tout ce qu’il fit, cela n’est-il pas écrit au livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Et ses serviteurs se levèrent et firent une conspiration, et frappèrent Joas dans la maison de Millo, à la descente de Silla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 22, 'Et Jozacar, fils de Shimhath, et Jozabad, fils de Shomer, ses serviteurs, le frappèrent, et il mourut; et on l’enterra avec ses pères dans la ville de David. Et Amatsia, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, '*La vingt -troisième année de Joas, fils d’Achazia, roi de Juda, Joakhaz, fils de Jéhu, commença de régner sur Israël à Samarie; [il régna] 17 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel; et il marcha après les péchés de Jéroboam, fils de Nebath, par lesquels il avait fait pécher Israël; il ne s’en détourna point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Et la colère de l’ Éternel s’embrasa contre Israël, et il les livra en la main de Hazaël, roi de Syrie, et en la main de Ben-Hadad, fils de Hazaël, tous ces jours-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, '(Et Joakhaz implora l’ Éternel, et l’ Éternel l’écouta, car il vit l’oppression d’Israël, car le roi de Syrie les opprimait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Et l’ Éternel donna à Israël un sauveur, et ils sortirent de dessous la main de la Syrie: et les fils d’Israël habitèrent dans leurs tentes comme auparavant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Toutefois ils ne se détournèrent point des péchés de la maison de Jéroboam, par lesquels il avait fait pécher Israël; ils y marchèrent; et même l’ashère resta à Samarie.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Car il n’avait laissé de peuple à Joakhaz que 50 cavaliers et dix chars, et 10 000 hommes de pied, car le roi de Syrie les avait fait périr, et les avait rendus comme la poussière de l’aire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Et le reste des actes de Joakhaz, et tout ce qu’il fit, et sa puissance, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Et Joakhaz s’endormit avec ses pères, et on l’enterra à Samarie; et Joas, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, '*La trente -septième année de Joas, roi de Juda, Joas, fils de Joakhaz, commença de régner sur Israël à Samarie; [il régna] 16 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel: il ne se détourna d’aucun des péchés de Jéroboam, fils de Nebath, par lesquels il avait fait pécher Israël; il y marcha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Et le reste des actes de Joas, et tout ce qu’il fit, et sa puissance, comment il fit la guerre contre Amatsia, roi de Juda, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Et Joas s’endormit avec ses pères; et Jéroboam s’assit sur son trône; et Joas fut enterré à Samarie avec les rois d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, '*Et Élisée était malade de la maladie dont il mourut; et Joas, roi d’Israël, descendit vers lui et pleura sur son visage, et dit: Mon père! mon père! Char d’Israël et sa cavalerie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Et Élisée lui dit: Prends un arc et des flèches. Et il prit un arc et des flèches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Et il dit au roi d’Israël: Mets ta main sur l’arc. Et il y mit sa main. Et Élisée mit ses mains sur les mains du roi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'et dit: Ouvre la fenêtre vers l’orient. Et il l’ouvrit. Et Élisée dit: Tire! Et il tira. Et il dit: Une flèche de salut de par l’ Éternel, une flèche de salut contre les Syriens; et tu battras les Syriens à Aphek, jusqu’à les détruire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Et il dit: Prends les flèches. Et il les prit. Et il dit au roi d’Israël: Frappe contre terre. Et il frappa trois fois, et s’arrêta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Et l’homme de Dieu se mit en colère contre lui, et dit: [Il fallait] frapper cinq ou six fois, alors tu aurais battu les Syriens jusqu’à les détruire; mais maintenant tu ne battras les Syriens que trois fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Et Élisée mourut, et on l’enterra. Et des troupes de Moab entrèrent dans le pays au commencement de l’année suivante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Et il arriva que, comme on enterrait un homme, voici, on vit [venir] la troupe, et on jeta l’homme dans le sépulcre d’Élisée. Et l’homme alla toucher les os d’Élisée, et il reprit vie, et se leva sur ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, '*Et Hazaël, roi de Syrie, opprima Israël tous les jours de Joakhaz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Et l’ Éternel usa de grâce envers eux, et eut compassion d’eux, et se tourna vers eux, à cause de son alliance avec Abraham, Isaac, et Jacob; et il ne voulut pas les détruire, et il ne les rejeta pas de devant sa face, dans ce temps-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Et Hazaël, roi de Syrie, mourut; et Ben-Hadad, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Et Joas, fils de Joakhaz, reprit des mains de Ben-Hadad, fils de Hazaël, les villes que celui-ci avait prises, dans la guerre, des mains de Joakhaz, son père. Joas le battit trois fois, et recouvra les villes d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, '*La seconde année de Joas, fils de Joakhaz, roi d’Israël, Amatsia, fils de Joas, roi de Juda, commença de régner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Il était âgé de 25 ans lorsqu’il commença de régner; et il régna 29 ans à Jérusalem; et le nom de sa mère était Jehoaddan, de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Et il fit ce qui est droit aux yeux de l’ Éternel, non pas toutefois comme David, son père; il fit selon tout ce que son père, Joas, avait fait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'seulement, les hauts lieux ne furent pas ôtés: le peuple sacrifiait encore et faisait fumer de l’encens sur les hauts lieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Et il arriva que, quand la royauté fut affermie dans sa main, il fit mourir ses serviteurs qui avaient frappé le roi, son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Mais les fils de ceux qui l’avaient frappé, il ne les mit pas à mort, selon ce qui est écrit dans le livre de la loi de Moïse, où l’ Éternel a commandé, disant: Les pères ne seront pas mis à mort pour les fils, et les fils ne seront pas mis à mort pour les pères, mais chacun sera mis à mort pour son péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Il frappa 10 000 [hommes] d’Édom dans la vallée du Sel; et il prit Séla, dans la guerre, et l’appela du nom de Joktheël, [qu’elle porte] jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Alors Amatsia envoya des messagers à Joas, fils de Joakhaz, fils de Jéhu, roi d’Israël, disant: Viens, voyons-nous face à face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Et Joas, roi d’Israël, envoya vers Amatsia, roi de Juda, disant: L’épine qui est au Liban a envoyé au cèdre qui est au Liban, disant: Donne ta fille pour femme à mon fils. Et une bête des champs qui est au Liban a passé, et a foulé l’épine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Tu as bien frappé Édom, et ton cœur s’est élevé. Glorifie-toi, et reste dans ta maison; pourquoi te mettrais-tu aux prises avec le malheur, et tomberais-tu, toi, et Juda avec toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Et Amatsia n’écouta pas; et Joas, roi d’Israël, monta; et ils se virent face à face, lui et Amatsia, roi de Juda, à Beth-Shémesh, qui est à Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Et Juda fut battu devant Israël; et ils s’enfuirent, chacun dans sa tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Et Joas, roi d’Israël, prit Amatsia, roi de Juda, fils de Joas, fils d’Achazia, à Beth-Shémesh; et il vint à Jérusalem, et abattit la muraille de Jérusalem depuis la porte d’Éphraïm jusqu’à la porte du coin, 400 coudées,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'et prit tout l’or et l’argent et tous les ustensiles qui furent trouvés dans la maison de l’ Éternel et dans les trésors de la maison du roi, et des otages; et il s’en retourna à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Et le reste des actes de Joas, ce qu’il fit, et sa puissance, et comment il fit la guerre contre Amatsia, roi de Juda, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Et Joas s’endormit avec ses pères, et fut enterré à Samarie avec les rois d’Israël; et Jéroboam, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Et Amatsia, fils de Joas, roi de Juda, vécut 15 ans après la mort de Joas, fils de Joakhaz, roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Et le reste des actes d’Amatsia, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Et on fit une conspiration contre lui à Jérusalem, et il s’enfuit à Lakis; et on envoya après lui à Lakis, et là on le mit à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Et on le transporta sur des chevaux, et il fut enterré à Jérusalem auprès de ses pères, dans la ville de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Et tout le peuple de Juda prit Azaria, qui était âgé de 16 ans, et ils le firent roi à la place de son père Amatsia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Ce fut lui qui bâtit Élath, et la recouvra pour Juda, après que le roi se fut endormi avec ses pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, '*La quinzième année d’Amatsia, fils de Joas, roi de Juda, Jéroboam, fils de Joas, roi d’Israël, commença de régner à Samarie; [il régna] 41 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel; il ne se détourna d’aucun des péchés de Jéroboam, fils de Nebath, par lesquels il avait fait pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Il rétablit la frontière d’Israël, depuis l’entrée de Hamath jusqu’à la mer de la plaine, selon la parole de l’ Éternel, le Dieu d’Israël, qu’il avait dite par son serviteur Jonas, le prophète, fils d’Amitthaï, qui était de Gath-Hépher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Car l’ Éternel vit que l’affliction d’Israël était très amère, et qu’il n’y avait plus personne, homme lié ou homme libre, et qu’il n’y avait personne qui secoure Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'et l’ Éternel n’avait pas dit qu’il effacerait le nom d’Israël de dessous les cieux; et il les sauva par la main de Jéroboam, fils de Joas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Et le reste des actes de Jéroboam, et tout ce qu’il fit, et sa puissance, comment il fit la guerre, et comment il recouvra pour Israël ce qui, de Damas et de Hamath, avait été à Juda, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Et Jéroboam s’endormit avec ses pères, avec les rois d’Israël; et Zacharie, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, '*La vingt -septième année de Jéroboam, roi d’Israël, Azaria, fils d’Amatsia, roi de Juda, commença de régner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Il était âgé de 16 ans lorsqu’il commença de régner; et il régna 52 ans à Jérusalem; et le nom de sa mère était Jecolia, de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Et il fit ce qui est droit aux yeux de l’ Éternel, selon tout ce qu’avait fait Amatsia, son père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'seulement les hauts lieux ne furent pas ôtés; le peuple sacrifiait encore et faisait fumer de l’encens sur les hauts lieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Et l’ Éternel frappa le roi, et il fut lépreux jusqu’au jour de sa mort, et il habita dans une maison d’isolement; et Jotham, fils du roi, fut chef de la maison [du roi], jugeant le peuple du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Et le reste des actes d’Azaria, et tout ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Et Azaria s’endormit avec ses pères, et on l’enterra auprès de ses pères dans la ville de David; et Jotham, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, '*La trente -huitième année d’Azaria, roi de Juda, Zacharie, fils de Jéroboam, commença de régner sur Israël à Samarie; [il régna] six mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, selon ce que ses pères avaient fait: il ne se détourna pas des péchés de Jéroboam, fils de Nebath, par lesquels il avait fait pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Et Shallum, fils de Jabesh, conspira contre lui, et le frappa devant le peuple, et le fit mourir; et il régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Et le reste des actes de Zacharie, voici, cela est écrit dans le livre des chroniques des rois d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'C’est là la parole de l’ Éternel qu’il avait adressée à Jéhu, disant: Tes fils seront assis sur le trône d’Israël, jusqu’à la quatrième génération. Et il en fut ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Shallum, fils de Jabesh, commença de régner la trente -neuvième année d’Ozias, roi de Juda: et il régna un mois entier à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Et Menahem, fils de Gadi, monta de Thirtsa, et entra dans Samarie, et frappa Shallum, fils de Jabesh, à Samarie, et le fit mourir, et régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Et le reste des actes de Shallum, et la conspiration qu’il fit, voici, cela est écrit au livre des chroniques des rois d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Alors Menahem frappa Thiphsakh, et tout ce qui y était, et son territoire, depuis Thirtsa, parce qu’on ne [lui] avait pas ouvert; et il la frappa, et y fendit le ventre à toutes les femmes enceintes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'La trente -neuvième année d’Azaria, roi de Juda, Menahem, fils de Gadi, commença de régner sur Israël; [il régna] dix ans à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel; tous ses jours, il ne se détourna pas des péchés de Jéroboam, fils de Nebath, par lesquels il avait fait pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Pul, roi d’Assyrie, vint contre le pays; et Menahem donna à Pul 1 000 talents d’argent, pour que sa main soit avec lui pour affermir le royaume dans sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Et Menahem leva l’argent sur Israël, sur tous ceux qui avaient de la fortune, pour le donner au roi d’Assyrie: de chacun 50 sicles d’argent. Et le roi d’Assyrie s’en retourna, et ne resta pas là dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Et le reste des actes de Menahem, et tout ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Et Menahem s’endormit avec ses pères, et Pekakhia, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'La cinquantième année d’Azaria, roi de Juda, Pekakhia, fils de Menahem, commença de régner sur Israël à Samarie; [il régna] deux ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel; il ne se détourna pas des péchés de Jéroboam, fils de Nebath, par lesquels il avait fait pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Et Pékakh, fils de Remalia, son capitaine, conspira contre lui, et le frappa à Samarie dans la forteresse de la maison du roi, ainsi qu’Argob et Arié; et [il avait] avec lui 50 hommes des fils des Galaadites: et il le mit à mort, et régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Et le reste des actes de Pekakhia, et tout ce qu’il fit, voici, cela est écrit dans le livre des chroniques des rois d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'La cinquante -deuxième année d’Azaria, roi de Juda, Pékakh, fils de Remalia, commença de régner sur Israël à Samarie; [il régna] 20 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel: il ne se détourna pas des péchés de Jéroboam, fils de Nebath, par lesquels il avait fait pécher Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Aux jours de Pékakh, roi d’Israël, Tiglath-Piléser, roi d’Assyrie, vint, et prit Ijon, et Abel-Beth-Maaca, et Janoakh, et Kédesh, et Hatsor, et Galaad, et la Galilée, tout le pays de Nephthali, et en transporta [les habitants] en Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Et Osée, fils d’Éla, fit une conspiration contre Pékakh, fils de Remalia, et le frappa, et le mit à mort; et il régna à sa place, la vingtième année de Jotham, fils d’Ozias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Et le reste des actes de Pékakh, et tout ce qu’il fit, voici, cela est écrit dans le livre des chroniques des rois d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, '*La seconde année de Pékakh, fils de Remalia, roi d’Israël, Jotham, fils d’Ozias, roi de Juda, commença de régner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Il était âgé de 25 ans lorsqu’il commença de régner; et il régna 16 ans à Jérusalem; et le nom de sa mère était Jerusha, fille de Tsadok.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Et il fit ce qui est droit aux yeux de l’ Éternel, il fit selon tout ce qu’avait fait Ozias, son père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'seulement les hauts lieux ne furent pas ôtés; le peuple sacrifiait encore et faisait fumer de l’encens sur les hauts lieux. Ce fut lui qui bâtit la porte supérieure de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Et le reste des actes de Jotham, et tout ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'En ces jours-là, l’ Éternel commença d’envoyer contre Juda Retsin, roi de Syrie, et Pékakh, fils de Remalia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Et Jotham s’endormit avec ses pères, et fut enterré avec ses pères dans la ville de David, son père; et Achaz, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 39, '');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'La dix -septième année de Pékakh, fils de Remalia, Achaz, fils de Jotham, roi de Juda, commença de régner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Achaz était âgé de 20 ans lorsqu’il commença de régner; et il régna 16 ans à Jérusalem. Et il ne fit pas ce qui est droit aux yeux de l’ Éternel, son Dieu, comme [avait fait] David, son père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'mais il marcha dans la voie des rois d’Israël, et même il fit passer son fils par le feu, selon les abominations des nations que l’ Éternel avait dépossédées devant les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Et il sacrifiait et faisait fumer de l’encens sur les hauts lieux, et sur les collines, et sous tout arbre vert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Alors Retsin, roi de Syrie, et Pékakh, fils de Remalia, roi d’Israël, montèrent à Jérusalem pour lui faire la guerre; et ils assiégèrent Achaz; mais ils ne purent pas le vaincre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'En ce temps-là, Retsin, roi de Syrie, recouvra Élath pour la Syrie; et il expulsa d’Élath les Juifs; et les Syriens entrèrent à Élath, et ils y ont habité jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Et Achaz envoya des messagers à Tiglath-Piléser, roi d’Assyrie, disant: Je suis ton serviteur et ton fils; monte, et sauve-moi de la main du roi de Syrie et de la main du roi d’Israël qui s’élèvent contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Et Achaz prit l’argent et l’or, ce qui s’en trouva dans la maison de l’ Éternel et dans les trésors de la maison du roi, et l’envoya en présent au roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Et le roi d’Assyrie l’écouta; et le roi d’Assyrie monta à Damas, et la prit, et en transporta [les habitants] à Kir, et fit mourir Retsin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Et le roi Achaz s’en alla à la rencontre de Tiglath-Piléser, roi d’Assyrie, à Damas; et il vit l’autel qui était à Damas; et le roi Achaz envoya à Urie, le sacrificateur, la forme de l’autel et son modèle, selon toute sa façon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Et Urie, le sacrificateur, bâtit l’autel selon tout ce que le roi Achaz avait envoyé de Damas; Urie, le sacrificateur, le fit ainsi, en attendant que le roi Achaz revienne de Damas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Et le roi revint de Damas, et le roi vit l’autel, et le roi s’approcha de l’autel, et y offrit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'et il fit fumer sur l’autel son holocauste et son offrande de gâteau, et versa sa libation, et fit aspersion du sang de ses sacrifices de prospérités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Et quant à l’autel d’airain qui était devant l’ Éternel, il le fit avancer de devant la maison, d’entre [son] autel et la maison de l’ Éternel, et le mit à côté de [son] autel, vers le nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Et le roi Achaz commanda à Urie, le sacrificateur, disant: Fais fumer sur le grand autel l’holocauste du matin et l’offrande de gâteau du soir, et l’holocauste du roi et son offrande de gâteau, et l’holocauste de tout le peuple du pays, et leur offrande de gâteau, et leurs libations; et tu feras aspersion de tout le sang des holocaustes et de tout le sang des sacrifices sur cet autel; et l’autel d’airain sera pour moi, afin d’y consulter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Et Urie, le sacrificateur, fit selon tout ce que le roi Achaz avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Et le roi Achaz enleva les panneaux des bases, et ôta les cuves qui étaient dessus; et il fit descendre la mer de dessus les bœufs d’airain qui étaient sous elle, et la mit sur un pavé de pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Et il changea, dans la maison de l’ Éternel, le portique du sabbat, qu’on avait bâti dans la maison, et l’entrée extérieure du roi, à cause du roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Et le reste des actes d’Achaz, ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Et Achaz s’endormit avec ses pères, et fut enterré avec ses pères dans la ville de David; et Ézéchias, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, '*La douzième année d’Achaz, roi de Juda, Osée, fils d’Éla, commença de régner à Samarie sur Israël; [il régna] neuf ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, non pas toutefois comme les rois d’Israël qui avaient été avant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Shalmanéser, roi d’Assyrie, monta contre lui, et Osée devint son serviteur, et lui envoya des présents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Et le roi d’Assyrie découvrit qu’Osée conspirait; car [Osée] avait envoyé des messagers à Sô, roi d’Égypte, et il n’envoyait pas de présents au roi d’Assyrie comme [il avait fait] d’année en année; et le roi d’Assyrie l’enferma dans une prison et le lia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Et le roi d’Assyrie monta par tout le pays, et monta à Samarie, et l’assiégea trois ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'La neuvième année d’Osée, le roi d’Assyrie prit Samarie, et il transporta Israël en Assyrie, et les fit habiter à Khalakh, et sur le Khabor, fleuve de Gozan, et dans les villes des Mèdes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Et il était arrivé que les fils d’Israël avaient péché contre l’ Éternel, leur Dieu, qui les avait fait monter du pays d’Égypte, de dessous la main du Pharaon, roi d’Égypte, et qu’ils avaient révéré d’autres dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Et ils marchèrent dans les statuts des nations que l’ Éternel avait dépossédées devant les fils d’Israël, et [dans ceux] que les rois d’Israël avaient établis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Et les fils d’Israël firent en secret contre l’ Éternel, leur Dieu, des choses qui ne sont pas droites; et ils se bâtirent des hauts lieux dans toutes leurs villes, depuis la tour des gardes jusqu’à la ville forte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'et ils se dressèrent des statues et des ashères sur toute haute colline et sous tout arbre vert,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'et firent fumer là de l’encens sur tous les hauts lieux, comme les nations que l’ Éternel avait transportées de devant eux; et ils firent des choses mauvaises, pour provoquer à colère l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'et ils servirent les idoles, au sujet desquelles l’ Éternel leur avait dit: Vous ne ferez point cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Et l’ Éternel rendit témoignage contre Israël et contre Juda par tous les prophètes, tous les voyants, disant: Détournez-vous de vos mauvaises voies; et gardez mes commandements, mes statuts, selon toute la loi que j’ai commandée à vos pères et que je vous ai envoyée par mes serviteurs les prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Et ils n’écoutèrent pas, et roidirent leur cou comme le cou de leurs pères, qui n’avaient pas cru l’ Éternel, leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Et ils rejetèrent ses statuts, et son alliance qu’il avait faite avec leurs pères, et ses témoignages qu’il leur avait donnés, et ils marchèrent après la vanité, et agirent vainement, et en suivant les nations qui étaient autour d’eux, touchant lesquelles l’ Éternel leur avait commandé de ne pas faire comme elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Et ils abandonnèrent tous les commandements de l’ Éternel, leur Dieu, et se firent des images de fonte, deux veaux, et se firent des ashères, et se prosternèrent devant toute l’armée des cieux, et servirent Baal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Et ils firent passer leurs fils et leurs filles par le feu, et pratiquèrent la divination et s’adonnèrent aux enchantements, et se vendirent pour faire ce qui est mauvais aux yeux de l’ Éternel, pour le provoquer à colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Et l’ Éternel fut très irrité contre Israël, et les ôta de devant sa face; il n’en resta que la seule tribu de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Et Juda non plus ne garda pas les commandements de l’ Éternel, son Dieu; et ils marchèrent dans les statuts qu’Israël avait établis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Et l’ Éternel rejeta toute la semence d’Israël, et il les affligea, et les livra en la main des pillards, jusqu’à ce qu’il les ait rejetés de devant sa face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Car Israël s’était séparé de la maison de David, et avait fait roi Jéroboam, fils de Nebath; et Jéroboam avait détourné violemment Israël de suivre l’ Éternel, et les avait fait commettre un grand péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Et les fils d’Israël marchèrent dans tous les péchés que Jéroboam avait commis; ils ne s’en détournèrent point,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'jusqu’à ce que l’ Éternel ôta Israël de devant sa face, comme il avait dit par tous ses serviteurs les prophètes; et Israël fut transporté de dessus sa terre en Assyrie, [où il est] jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Et le roi d’Assyrie fit venir [des gens] de Babel, et de Cuth, et d’Avva, et de Hamath, et de Sepharvaïm, et [les] fit habiter dans les villes de la Samarie, à la place des fils d’Israël; et ils possédèrent la Samarie, et habitèrent dans ses villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Et il arriva, quand ils commencèrent d’y habiter, qu’ils ne craignaient pas l’ Éternel, et l’ Éternel envoya contre eux des lions qui les tuaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Et on parla au roi d’Assyrie, disant: Les nations que tu as transportées et que tu as fait habiter dans les villes de Samarie ne connaissent pas la coutume du dieu du pays, et il a envoyé contre elles des lions, et voici, [ces lions] les font mourir, parce qu’elles ne connaissent pas la coutume du dieu du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Et le roi d’Assyrie commanda, disant: Faites aller là quelqu’un des sacrificateurs que vous en avez transportés; et qu’il aille et qu’il demeure là, et qu’il leur enseigne la coutume du dieu du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Et un des sacrificateurs qu’on avait transportés de Samarie, vint et habita à Béthel, et il leur enseignait comment ils devaient craindre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Et chaque nation se fit ses dieux, et elles les placèrent dans les maisons des hauts lieux que les Samaritains avaient faites, chaque nation dans ses villes où elle habitait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Et les hommes de Babel firent Succoth-Benoth; et les hommes de Cuth firent Nergal; et les hommes de Hamath firent Ashima;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'et les Avviens firent Nibkhaz et Tharthak; et les Sepharviens brûlaient au feu leurs fils à Adrammélec et à Anammélec, les dieux de Sepharvaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Et ils craignaient l’ Éternel, et se firent d’entre toutes les classes [du peuple] des sacrificateurs des hauts lieux, qui offraient [des sacrifices] pour eux dans les maisons des hauts lieux:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'ils craignaient l’ Éternel, et ils servaient leurs dieux selon la coutume des nations d’où ils avaient été transportés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Jusqu’à ce jour ils font selon leurs premières coutumes: ils ne craignent pas l’ Éternel, et ils ne font pas selon leurs statuts et selon leurs coutumes, ni selon la loi et selon le commandement que l’ Éternel avait commandés aux fils de Jacob, qu’il nomma Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Et l’ Éternel avait fait alliance avec eux, et il leur avait commandé, disant: Vous ne craindrez point d’autres dieux, et vous ne vous prosternerez point devant eux; et vous ne les servirez point, et ne leur sacrifierez point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Mais l’ Éternel seul, qui vous a fait monter du pays d’Égypte par une grande force et à bras étendu, lui, vous le craindrez, et vous vous prosternerez devant lui, et à lui vous sacrifierez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Et les statuts, et les ordonnances, et la loi, et le commandement, qu’il a écrits pour vous, vous prendrez garde à les pratiquer tous les jours; et vous ne craindrez pas d’autres dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Et vous n’oublierez pas l’alliance que j’ai faite avec vous, et vous ne craindrez pas d’autres dieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'mais vous craindrez l’ Éternel, votre Dieu, et lui vous délivrera de la main de tous vos ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Et ils n’écoutèrent pas, mais ils firent selon leur première coutume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Et ces nations-là craignaient l’ Éternel, et servaient leurs images; leurs fils aussi, et les fils de leurs fils, font jusqu’à ce jour comme leurs pères ont fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, '*Et il arriva, la troisième année d’Osée, fils d’Éla, roi d’Israël, qu’Ézéchias, fils d’Achaz, roi de Juda, commença de régner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Il était âgé de 25 ans lorsqu’il commença de régner; et il régna 29 ans à Jérusalem; et le nom de sa mère était Abi, fille de Zacharie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Et il fit ce qui est droit aux yeux de l’ Éternel, selon tout ce qu’avait fait David, son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Il ôta les hauts lieux, et brisa les statues, et coupa les ashères, et mit en pièces le serpent d’airain que Moïse avait fait, car jusqu’à ces jours-là les fils d’Israël lui brûlaient de l’encens; et il l’appela: Nehushtan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Il mit sa confiance en l’ Éternel, le Dieu d’Israël; et après lui, il n’y en eut point de semblable à lui parmi tous les rois de Juda, non plus que parmi ceux qui avaient été avant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Et il s’attacha à l’ Éternel; il ne se détourna point de lui, et il garda ses commandements, que l’ Éternel avait commandés à Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Et l’ Éternel fut avec lui: partout où il allait, il prospéra. Et il se révolta contre le roi d’Assyrie, et ne le servit pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Il frappa les Philistins jusqu’à Gaza, et ses confins, depuis la tour des gardes jusqu’à la ville forte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Et il arriva, la quatrième année du roi Ézéchias, qui était la septième d’Osée, fils d’Éla, roi d’Israël, que Shalmanéser, roi d’Assyrie, monta contre Samarie et l’assiégea.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Et ils la prirent au bout de trois ans: la sixième année d’Ézéchias, ce fut la neuvième année d’Osée, roi d’Israël, Samarie fut prise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Et le roi d’Assyrie transporta Israël en Assyrie, et les établit à Khalakh, et sur le Khabor, fleuve de Gozan, et dans les villes des Mèdes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'parce qu’ils n’écoutèrent point la voix de l’ Éternel, leur Dieu, et transgressèrent son alliance, tout ce que Moïse, serviteur de l’ Éternel, avait commandé; et ils n’écoutèrent pas, et ne le firent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Et la quatorzième année du roi Ézéchias, Sankhérib, roi d’Assyrie, monta contre toutes les villes fortes de Juda et les prit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Et Ézéchias, roi de Juda, envoya au roi d’Assyrie à Lakis, disant: J’ai péché, retire-toi de moi; ce que tu m’imposeras, je le supporterai. Et le roi d’Assyrie imposa à Ézéchias, roi de Juda, 300 talents d’argent, et 30 talents d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Et Ézéchias donna tout l’argent qui se trouva dans la maison de l’ Éternel et dans les trésors de la maison du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'En ce temps-là, Ézéchias dépouilla les portes du temple de l’ Éternel, et les piliers qu’Ézéchias, roi de Juda, avait recouverts [d’or], et il les donna au roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Et le roi d’Assyrie envoya de Lakis, le Tharthan, et le Rab-Saris, et le Rab-Shaké, avec de grandes forces, vers le roi Ézéchias à Jérusalem; et ils montèrent et vinrent à Jérusalem. Et ils montèrent et vinrent, et se tinrent près de l’aqueduc de l’étang supérieur, qui est sur la route du champ du foulon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Et ils appelèrent le roi. Et Éliakim, fils de Hilkija, qui était [préposé] sur la maison [du roi], et Shebna, le scribe, et Joakh, fils d’Asaph, rédacteur des chroniques, sortirent vers eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Et le Rab-Shaké leur dit: Dites à Ézéchias: Ainsi dit le grand roi, le roi d’Assyrie: Quelle est cette confiance que tu as?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Tu dis (ce ne sont que paroles des lèvres): Le conseil et la force [sont là] pour la guerre. Maintenant, en qui te confies-tu que tu te révoltes contre moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Or voici, tu te confies en ce bâton de roseau cassé, en l’Égypte, lequel, si quelqu’un s’appuie dessus, lui entre dans la main et la perce. Tel est le Pharaon, roi d’Égypte, pour tous ceux qui se confient en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Que si vous me dites: Nous nous confions en l’ Éternel, notre Dieu,... n’est-ce pas lui dont Ézéchias a ôté les hauts lieux et les autels, en disant à Juda et à Jérusalem: Vous vous prosternerez devant cet autel-ci à Jérusalem?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Et maintenant, fais un accord, je te prie, avec le roi d’Assyrie, mon seigneur, et je te donnerai 2 000 chevaux si tu peux donner des cavaliers pour les monter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Et comment ferais-tu tourner visage à un seul capitaine d’entre les moindres serviteurs de mon seigneur? Et tu mets ta confiance en l’Égypte, pour des chars et des cavaliers...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Suis-je maintenant monté sans l’ Éternel contre ce lieu pour le détruire? L’ Éternel m’a dit: Monte contre ce pays, et détruis-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Et Éliakim, fils de Hilkija, et Shebna, et Joakh, dirent au Rab-Shaké: Parle, nous te prions, à tes serviteurs en syriaque, car nous le comprenons, et ne nous parle pas en [langue] judaïque, aux oreilles du peuple qui est sur la muraille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Et le Rab-Shaké leur dit: Est-ce vers ton seigneur et vers toi que mon seigneur m’a envoyé pour dire ces paroles? N’est-ce pas vers les hommes qui se tiennent sur la muraille, pour manger leurs excréments et pour boire leur urine avec vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Et le Rab-Shaké se tint là, et cria à haute voix en [langue] judaïque, et parla, et dit: Écoutez la parole du grand roi, le roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Ainsi dit le roi: Qu’Ézéchias ne vous trompe point; car il ne pourra pas vous délivrer de la main du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Et qu’Ézéchias ne vous fasse pas mettre votre confiance en l’ Éternel, disant: L’ Éternel nous délivrera certainement, et cette ville ne sera point livrée en la main du roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'N’écoutez pas Ézéchias; car ainsi dit le roi d’Assyrie: Faites la paix avec moi, et sortez vers moi; et vous mangerez chacun de sa vigne et chacun de son figuier, et vous boirez chacun des eaux de son puits,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'jusqu’à ce que je vienne et que je vous emmène dans un pays comme votre pays, un pays de blé et de moût, un pays de pain et de vignes, un pays d’oliviers à huile et de miel: et vous vivrez, et vous ne mourrez point. Et n’écoutez pas Ézéchias, car il vous séduit, disant: L’ Éternel nous délivrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Les dieux des nations ont-ils bien délivré chacun son pays de la main du roi d’Assyrie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Où sont les dieux de Hamath et d’Arpad? Où sont les dieux de Sepharvaïm, d’Héna, et d’Ivva? Et ont-ils délivré Samarie de ma main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Quels sont, d’entre tous les dieux des pays, ceux qui ont délivré leur pays de ma main, pour que l’ Éternel délivre Jérusalem de ma main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Et le peuple se tut, et ne lui répondit pas un mot; car c’était là le commandement du roi, disant: Vous ne lui répondrez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Et Éliakim, fils de Hilkija, qui était [préposé] sur la maison, et Shebna, le scribe, et Joakh, fils d’Asaph, rédacteur des chroniques, vinrent vers Ézéchias, leurs vêtements déchirés, et ils lui rapportèrent les paroles du Rab-Shaké.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Et il arriva, quand le roi Ézéchias eut entendu [ces choses], qu’il déchira ses vêtements, et se couvrit d’un sac, et entra dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Et il envoya Éliakim, qui était [préposé] sur la maison, et Shebna, le scribe, et les anciens des sacrificateurs, couverts de sacs, vers Ésaïe, le prophète, fils d’Amots;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'et ils lui dirent: Ainsi dit Ézéchias: Ce jour est un jour de détresse, et de châtiment, et d’opprobre; car les enfants sont venus jusqu’à la naissance, et il n’y a point de force pour enfanter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Peut-être l’ Éternel, ton Dieu, entendra-t-il toutes les paroles du Rab-Shaké, que le roi d’Assyrie, son seigneur, a envoyé pour outrager le Dieu vivant, et punira-t-il les paroles que l’ Éternel, ton Dieu, a entendues? Fais donc monter une prière pour le résidu qui se trouve [encore].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Et les serviteurs du roi Ézéchias vinrent vers Ésaïe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Et Ésaïe leur dit: Vous direz ainsi à votre seigneur: Ainsi dit l’ Éternel: Ne crains pas à cause des paroles que tu as entendues, par lesquelles les serviteurs du roi d’Assyrie m’ont blasphémé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Voici, je vais mettre en lui un esprit, et il entendra une nouvelle, et retournera dans son pays; et je le ferai tomber par l’épée dans son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Et le Rab-Shaké s’en retourna, et trouva le roi d’Assyrie faisant la guerre à Libna; car il avait appris qu’il était parti de Lakis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Et [le roi d’Assyrie] entendit dire, touchant Tirhaka, roi d’Éthiopie: Voici, il est sorti pour te faire la guerre. Et il envoya de nouveau des messagers à Ézéchias, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Vous parlerez ainsi à Ézéchias, roi de Juda, disant: Que ton Dieu, en qui tu te confies, ne te trompe point, disant: Jérusalem ne sera pas livrée en la main du roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Voici, tu as entendu ce que les rois d’Assyrie ont fait à tous les pays, les détruisant entièrement; et toi, tu serais délivré!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Est-ce que les dieux des nations que mes pères ont détruites les ont délivrées, Gozan, et Charan, et Rétseph, et les fils d’Éden qui étaient en Thelassar?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Où est le roi de Hamath, et le roi d’Arpad, et le roi de la ville de Sepharvaïm, d’Héna, et d’Ivva?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Et Ézéchias prit la lettre de la main des messagers, et la lut, et monta dans la maison de l’ Éternel; et Ézéchias la déploya devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Et Ézéchias pria l’ Éternel et dit: Éternel, Dieu d’Israël, qui es assis entre les chérubins, toi, le Même, toi seul tu es le Dieu de tous les royaumes de la terre; toi, tu as fait les cieux et la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Éternel! incline ton oreille et écoute. Éternel! ouvre tes yeux, et vois; et écoute les paroles de Sankhérib, qu’il a envoyées pour outrager le Dieu vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Il est vrai, Éternel! les rois d’Assyrie ont dévasté les nations et leurs pays,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'et ont jeté au feu leurs dieux; car ce n’étaient pas des dieux, mais l’ouvrage de mains d’homme, – du bois, et de la pierre; et ils les ont détruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Et maintenant, Éternel, notre Dieu! sauve-nous, je te prie, de sa main, afin que tous les royaumes de la terre sachent que toi, Éternel, tu es Dieu, toi seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Et Ésaïe, fils d’Amots, envoya vers Ézéchias, disant: Ainsi dit l’ Éternel, le Dieu d’Israël: Quant à la prière que tu m’as faite au sujet de Sankhérib, roi d’Assyrie, je l’ai entendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'C’est ici la parole que l’ Éternel a prononcée contre lui: La vierge, fille de Sion, te méprise, elle se moque de toi; la fille de Jérusalem secoue la tête après toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Qui as-tu outragé et blasphémé? Et contre qui as-tu élevé la voix? C’est contre le Saint d’Israël que tu as levé tes yeux en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Par tes messagers tu as outragé le Seigneur, et tu as dit: Avec la multitude de mes chars j’ai gravi le haut des montagnes, les parties reculées du Liban, et je couperai ses hauts cèdres, l’élite de ses cyprès, et je parviendrai jusqu’à son dernier gîte, à la forêt de son Carmel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'J’ai creusé, et j’ai bu des eaux étrangères; et j’ai desséché avec la plante de mes pieds tous les canaux de Matsor...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'N’as-tu pas entendu que j’ai fait cela dès longtemps, et que je l’ai formé dès les jours d’autrefois? Maintenant je l’ai fait arriver, pour que tu réduises en monceaux de ruines des villes fortes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Et leurs habitants ont été sans force, ils ont été terrifiés, et ont été couverts de honte; ils ont été [comme] l’herbe des champs et l’herbe verte, [comme] l’herbe des toits et la récolte flétrie avant qu’elle soit en tige.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Mais je sais ton habitation, et ta sortie et ton entrée, et ta rage contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Parce que tu es plein de rage contre moi, et que ton insolence est montée à mes oreilles, je mettrai mon anneau à ton nez et mon frein entre tes lèvres, et je te ferai retourner par le chemin par lequel tu es venu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Et ceci en sera le signe pour toi: on mangera cette année ce qui lève des grains tombés, et la seconde année ce qui croît de soi-même; et la troisième année, vous sèmerez et vous moissonnerez, et vous planterez des vignes et vous en mangerez le fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Et ce qui est réchappé et demeuré de reste de la maison de Juda poussera encore des racines en bas et produira du fruit en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Car de Jérusalem sortira un résidu, et de la montagne de Sion, ce qui est réchappé. La jalousie de l’ Éternel ✶[des armées] fera cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'C’est pourquoi, ainsi dit l’ Éternel touchant le roi d’Assyrie: Il n’entrera pas dans cette ville, et il n’y lancera point de flèche; il ne lui présentera pas le bouclier, et il n’élèvera point de terrasse contre elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Il s’en retournera par le chemin par lequel il est venu, et il n’entrera pas dans cette ville, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Et je protégerai cette ville, afin de la sauver, à cause de moi, et à cause de David, mon serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Et il arriva, cette nuit-là, qu’un ange de l’ Éternel sortit, et frappa dans le camp des Assyriens 185 000 [hommes]; et quand on se leva le matin, voici, c’étaient tous des corps morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Et Sankhérib, roi d’Assyrie, partit, et s’en alla et s’en retourna, et habita à Ninive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Et il arriva, comme il se prosternait dans la maison de Nisroc, son dieu, qu’Adrammélec et Sharétser, ✶[ses fils], le frappèrent avec l’épée; et ils se sauvèrent dans le pays d’Ararat; et Ésar-Haddon, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'En ces jours-là, Ézéchias fut malade à la mort; et Ésaïe, le prophète, fils d’Amots, vint vers lui, et lui dit: Ainsi dit l’ Éternel: Donne des ordres pour ta maison, car tu vas mourir et tu ne vivras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Et [Ézéchias] tourna sa face contre la muraille, et pria l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Hélas, Éternel! souviens-toi, je te prie, que j’ai marché devant toi en vérité et avec un cœur parfait, et que j’ai fait ce qui est bon à tes yeux. Et Ézéchias versa beaucoup de larmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Et il arriva qu’Ésaïe, étant sorti, et n’étant pas encore arrivé au milieu de la ville, la parole de l’ Éternel vint à lui, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Retourne, et dis à Ézéchias, prince de mon peuple: Ainsi dit l’ Éternel, Dieu de David, ton père: J’ai entendu ta prière, j’ai vu tes larmes; voici, je te guérirai; le troisième jour tu monteras à la maison de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'et j’ajouterai 15 années à tes jours; et je te délivrerai, toi et cette ville, de la main du roi d’Assyrie, et je protégerai cette ville à cause de moi, et à cause de David, mon serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Et Ésaïe dit: Prenez une masse de figues. Et ils la prirent, et la mirent sur l’ulcère; et [Ézéchias] se rétablit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Et Ézéchias dit à Ésaïe: Quel est le signe que l’ Éternel me guérira et que le troisième jour je monterai à la maison de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Et Ésaïe dit: Ceci en sera le signe pour toi de par l’ Éternel, car l’ Éternel accomplira la parole qu’il a prononcée: l’ombre avancera-t-elle de dix degrés, ou retournera-t-elle de dix degrés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Et Ézéchias dit: C’est peu de chose que l’ombre descende de dix degrés: non, mais que l’ombre retourne de dix degrés en arrière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Et Ésaïe, le prophète, cria à l’ Éternel; et [l’ Éternel] fit retourner l’ombre de dix degrés en arrière sur les degrés par lesquels elle était descendue sur le cadran d’Achaz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'En ce temps-là, Berodac-Baladan, fils de Baladan, roi de Babylone, envoya une lettre et un présent à Ézéchias, car il avait appris qu’Ézéchias avait été malade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Et Ézéchias écouta les [messagers], et leur montra toute la maison [où étaient renfermés] ses objets précieux, l’argent et l’or, et les aromates et l’huile fine, et tout son arsenal, et tout ce qui se trouvait dans ses trésors; il n’y eut rien qu’Ézéchias ne leur montrât dans sa maison et dans tous ses domaines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Et Ésaïe, le prophète, vint vers le roi Ézéchias, et lui dit: Qu’ont dit ces hommes, et d’où sont-ils venus vers toi? Et Ézéchias dit: Ils sont venus d’un pays éloigné, de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Et [Ésaïe] dit: Qu’ont-ils vu dans ta maison? Et Ézéchias dit: Ils ont vu tout ce qui est dans ma maison; il n’y a rien dans mes trésors que je ne leur aie montré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Et Ésaïe dit à Ézéchias: Écoute la parole de l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Voici, des jours viennent où tout ce qui est dans ta maison, et ce que tes pères ont amassé jusqu’à ce jour, sera porté à Babylone; il n’en restera rien, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Et on prendra de tes fils, qui sortiront de toi, que tu auras engendrés, et ils seront eunuques dans le palais du roi de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Et Ézéchias dit à Ésaïe: La parole de l’ Éternel que tu as prononcée est bonne. Et il dit: N’y aura-t-il pas ainsi paix et stabilité pendant mes jours?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Et le reste des actes d’Ézéchias, et toute sa puissance, et comment il fit l’étang et l’aqueduc, et amena les eaux dans la ville, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Et Ézéchias s’endormit avec ses pères; et Manassé, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, '*Manassé était âgé de douze ans lorsqu’il commença de régner; et il régna 55 ans à Jérusalem; et le nom de sa mère était Hephtsiba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, selon les abominations des nations que l’ Éternel avait dépossédées devant les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Et il rebâtit les hauts lieux qu’Ézéchias, son père, avait détruits, et éleva des autels à Baal, et fit une ashère, comme avait fait Achab, roi d’Israël, et il se prosterna devant toute l’armée des cieux, et les servit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'et il bâtit des autels dans la maison de l’ Éternel, de laquelle l’ Éternel avait dit: C’est dans Jérusalem que je mettrai mon nom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'et il bâtit des autels à toute l’armée des cieux, dans les deux parvis de la maison de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'et il fit passer son fils par le feu, et il pronostiquait, et pratiquait les enchantements, et il établit des évocateurs d’esprits et des diseurs de bonne aventure: il fit outre mesure ce qui est mauvais aux yeux de l’ Éternel, pour le provoquer à colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Et l’image de l’ashère qu’il avait faite, il la plaça dans la maison de laquelle l’ Éternel avait dit à David et à Salomon, son fils: C’est dans cette maison, et dans Jérusalem que j’ai choisie d’entre toutes les tribus d’Israël, que je mettrai mon nom à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'et je ne ferai plus errer le pied d’Israël loin de la terre que j’ai donnée à leurs pères, si seulement ils prennent garde à faire selon tout ce que je leur ai commandé, et selon toute la loi que leur a commandée mon serviteur Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Et ils n’écoutèrent point; et Manassé les fit errer [en les induisant] à faire le mal plus que les nations que l’ Éternel avait détruites devant les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Et l’ Éternel parla par ses serviteurs les prophètes, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Parce que Manassé, roi de Juda, a pratiqué ces abominations, [et] a fait le mal plus que tout ce qu’ont fait les Amoréens qui ont été avant lui, et qu’il a fait pécher aussi Juda par ses idoles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'à cause de cela, ainsi dit l’ Éternel, le Dieu d’Israël: Voici, je fais venir sur Jérusalem et sur Juda un mal tel, que quiconque l’entendra, les deux oreilles lui tinteront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'et j’étendrai sur Jérusalem le cordeau de Samarie et le plomb de la maison d’Achab, et j’écurerai Jérusalem comme on écure un plat: on l’écure et on le tourne sens dessus dessous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Et j’abandonnerai le reste de mon héritage, et je les livrerai en la main de leurs ennemis; et ils seront le butin et la proie de tous leurs ennemis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'parce qu’ils ont fait ce qui est mauvais à mes yeux et qu’ils m’ont provoqué à colère depuis le jour où leurs pères sont sortis d’Égypte jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Et Manassé versa aussi le sang innocent en grande abondance, jusqu’à en remplir Jérusalem d’un bout à l’autre bout, outre son péché par lequel il fit pécher Juda, en faisant ce qui est mauvais aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Et le reste des actes de Manassé, et tout ce qu’il fit, et le péché qu’il commit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Et Manassé s’endormit avec ses pères, et fut enterré dans le jardin de sa maison, dans le jardin d’Uzza; et Amon, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, '*Amon était âgé de 22 ans lorsqu’il commença de régner; et il régna deux ans à Jérusalem; et le nom de sa mère était Meshullémeth, fille de Haruts, de Jotba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, comme avait fait Manassé, son père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'et il marcha dans toute la voie dans laquelle avait marché son père, et il servit les idoles que son père avait servies, et se prosterna devant elles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'et il abandonna l’ Éternel, le Dieu de ses pères, et ne marcha pas dans la voie de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Et les serviteurs d’Amon conspirèrent contre lui, et mirent à mort le roi dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Mais le peuple du pays tua tous ceux qui avaient conspiré contre le roi Amon; et le peuple du pays établit pour roi Josias, son fils, à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Et le reste des actes d’Amon, ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Et on l’enterra dans son sépulcre, dans le jardin d’Uzza; et Josias, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, '*Josias était âgé de huit ans lorsqu’il commença de régner; et il régna 31 ans à Jérusalem; et le nom de sa mère était Jedida, fille d’Adaïa, de Botskath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Et il fit ce qui est droit aux yeux de l’ Éternel, et marcha dans toute la voie de David, son père, et ne s’en écarta ni à droite ni à gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Et il arriva, la dix-huitième année du roi Josias, que le roi envoya Shaphan, le scribe, fils d’Atsalia, fils de Meshullam, à la maison de l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Monte vers Hilkija, le grand sacrificateur, et qu’on relève l’argent qui a été apporté dans la maison de l’ Éternel [et] que les gardiens du seuil ont recueilli de la part du peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'et qu’on le remette en la main de ceux qui font l’ouvrage, qui sont préposés [sur le travail] dans la maison de l’ Éternel; et que ceux-ci le remettent à ceux qui font l’ouvrage dans la maison de l’ Éternel, pour réparer les brèches de la maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'aux charpentiers, et aux constructeurs, et aux maçons, et afin d’acheter des bois et des pierres de taille, pour réparer la maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'toutefois qu’on ne compte pas avec eux l’argent remis entre leurs mains, car ils agissent avec fidélité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Et Hilkija, le grand sacrificateur, dit à Shaphan, le scribe: J’ai trouvé le livre de la loi dans la maison de l’ Éternel. Et Hilkija donna le livre à Shaphan, et il le lut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Et Shaphan, le scribe, vint vers le roi, et rendit compte au roi, et dit: Tes serviteurs ont versé l’argent qui s’est trouvé dans la maison, et l’ont remis entre les mains de ceux qui font l’ouvrage, qui sont préposés [sur le travail] dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Et Shaphan, le scribe, raconta au roi, disant: Hilkija, le sacrificateur, m’a donné un livre. Et Shaphan le lut devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Et il arriva que, quand le roi entendit les paroles du livre de la loi, il déchira ses vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Et le roi commanda à Hilkija, le sacrificateur, et à Akhikam, fils de Shaphan, et à Acbor, fils de Michée, et à Shaphan, le scribe, et à Asçaïa, serviteur du roi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Allez, consultez l’ Éternel pour moi, et pour le peuple, et pour tout Juda, touchant les paroles de ce livre qui a été trouvé; car grande est la fureur de l’ Éternel, qui s’est allumée contre nous, parce que nos pères n’ont pas écouté les paroles de ce livre, pour faire selon tout ce qui y est écrit pour nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Et Hilkija, le sacrificateur, et Akhikam, et Acbor, et Shaphan, et Asçaïa, allèrent vers Hulda, la prophétesse, femme de Shallum, fils de Thikva, fils de Harkhas, qui avait la garde des vêtements; et elle habitait à Jérusalem dans le second quartier de la ville; et ils lui parlèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Et elle leur dit: Ainsi dit l’ Éternel, le Dieu d’Israël: Dites à l’homme qui vous a envoyés vers moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Ainsi dit l’ Éternel: Voici, je fais venir du mal sur ce lieu et sur ses habitants, toutes les paroles du livre qu’a lu le roi de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Parce qu’ils m’ont abandonné et qu’ils ont brûlé de l’encens à d’autres dieux, pour me provoquer à colère par toute l’œuvre de leurs mains, ma fureur s’est allumée contre ce lieu, et elle ne s’éteindra point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Et au roi de Juda, qui vous a envoyés pour consulter l’ Éternel, vous lui direz ainsi: Ainsi dit l’ Éternel, le Dieu d’Israël, quant aux paroles que tu as entendues:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Parce que ton cœur a été sensible, et que tu t’es humilié devant l’ Éternel quand tu as entendu ce que j’ai prononcé contre ce lieu et contre ses habitants, [savoir] qu’ils seraient [livrés] à la destruction et à la malédiction, et parce que tu as déchiré tes vêtements et que tu as pleuré devant moi, moi aussi j’ai entendu, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'C’est pourquoi, voici, je vais te recueillir auprès de tes pères, et tu seras recueilli en paix dans tes sépulcres, et tes yeux ne verront pas tout le mal que je fais venir sur ce lieu. Et ils rapportèrent au roi [cette] parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Et le roi envoya, et on assembla vers lui tous les anciens de Juda et de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Et le roi monta à la maison de l’ Éternel, et avec lui tous les hommes de Juda, et tous les habitants de Jérusalem, et les sacrificateurs, et les prophètes, et tout le peuple, depuis le petit jusqu’au grand: et on lut, eux l’entendant, toutes les paroles du livre de l’alliance qui avait été trouvé dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Et le roi se tint debout sur l’estrade, et fit cette alliance devant l’ Éternel, de marcher après l’ Éternel, et de garder ses commandements, et ses témoignages, et ses statuts, de tout [son] cœur et de toute [son] âme, pour accomplir les paroles de cette alliance, écrites dans ce livre; et tout le peuple entra dans l’alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Et le roi commanda à Hilkija, le grand sacrificateur, et aux sacrificateurs de la seconde [classe], et aux gardiens du seuil, d’emporter hors du temple de l’ Éternel tous les objets qui avaient été faits pour Baal, et pour l’ashère, et pour toute l’armée des cieux; et il les brûla en dehors de Jérusalem, dans les champs du Cédron, et il en porta la poussière à Béthel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Et il supprima les Camarim, que les rois de Juda avaient établis pour faire fumer l’encens sur les hauts lieux dans les villes de Juda et dans les environs de Jérusalem, et ceux qui brûlaient de l’encens à Baal, au soleil, et à la lune, et au zodiaque, et à toute l’armée des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Et il fit emporter l’ashère hors de la maison de l’ Éternel, hors de Jérusalem, dans la vallée du Cédron, et il la brûla dans la vallée du Cédron, et la réduisit en poussière, et en jeta la poussière sur les sépulcres des fils du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Et il démolit les maisons des prostituées qui étaient dans la maison de l’ Éternel, [et] où les femmes tissaient des tentes pour l’ashère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Et il fit venir des villes de Juda tous les sacrificateurs, et souilla les hauts lieux où les sacrificateurs faisaient fumer de l’encens, depuis Guéba jusqu’à Beër-Shéba; et il démolit les hauts lieux des portes, qui étaient à l’entrée de la porte de Josué, chef de la ville, [et ceux] qui étaient à la gauche d’un homme [entrant] dans la porte de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Toutefois les sacrificateurs des hauts lieux ne montaient pas vers l’autel de l’ Éternel à Jérusalem, mais ils mangeaient des pains sans levain au milieu de leurs frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Et il souilla Topheth, qui est dans la vallée des fils de Hinnom, afin que personne ne fasse passer par le feu son fils ou sa fille au Moloc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Et il abolit les chevaux que les rois de Juda avaient donnés au soleil, à l’entrée de la maison de l’ Éternel, vers la chambre de Nethan-Mélec, l’eunuque, qui était dans les dépendances [du temple]; et il brûla au feu les chars du soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Et le roi démolit les autels qui étaient sur le toit de la chambre haute d’Achaz, que les rois de Juda avaient faits, et les autels que Manassé avait faits dans les deux parvis de la maison de l’ Éternel; et il les brisa, [les ôtant] de là, et en jeta la poussière dans la vallée du Cédron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Et le roi souilla les hauts lieux qui étaient en face de Jérusalem, à la droite de la montagne de corruption, que Salomon, roi d’Israël, avait bâtis pour Ashtoreth, l’abomination des Sidoniens, et pour Kemosh, l’abomination de Moab, et pour Milcom, l’abomination des fils d’Ammon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'et il brisa les statues, et coupa les ashères, et remplit d’ossements d’hommes les lieux où ils étaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Et l’autel qui était à Béthel, le haut lieu qu’avait fait Jéroboam, fils de Nebath, qui fit pécher Israël, cet autel-là aussi et le haut lieu, il les démolit; et il brûla le haut lieu, le réduisit en poussière, et brûla l’ashère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Et Josias se tourna et vit les sépulcres qui étaient là dans la montagne; et il envoya prendre les ossements des sépulcres, et il les brûla sur l’autel et le souilla, selon la parole de l’ Éternel qu’avait proclamée l’homme de Dieu qui proclama ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Et [le roi] dit: Quel est ce monument que je vois? Et les hommes de la ville lui dirent: C’est le sépulcre de l’homme de Dieu qui vint de Juda, et qui proclama ces choses que tu as faites sur l’autel de Béthel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Et il dit: Laissez-le reposer; que personne ne remue ses os! Et ils préservèrent ses os ainsi que les os du prophète qui était venu de Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Et Josias ôta aussi toutes les maisons des hauts lieux que les rois d’Israël avaient faites dans les villes de Samarie pour provoquer à colère [l’ Éternel]; et il leur fit selon tout ce qu’il avait fait à Béthel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Et il sacrifia sur les autels tous les sacrificateurs des hauts lieux qui étaient là, et y brûla des ossements d’hommes; et il retourna à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Et le roi commanda à tout le peuple, disant: Célébrez la Pâque à l’ Éternel, votre Dieu, comme il est écrit dans ce livre de l’alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Car aucune [Pâque] n’avait été célébrée comme cette Pâque, depuis les jours des juges qui ont jugé Israël, et durant tous les jours des rois d’Israël et des rois de Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'mais la dix-huitième année du roi Josias, cette Pâque fut célébrée à l’ Éternel dans Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Et Josias extermina aussi les évocateurs d’esprits, et les diseurs de bonne aventure, et les théraphim, et les idoles, et toutes les abominations qui se voyaient dans le pays de Juda et à Jérusalem, afin d’effectuer les paroles de la loi, écrites dans le livre que Hilkija, le sacrificateur, avait trouvé dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Avant lui il n’y eut pas de roi semblable à lui, qui se soit retourné vers l’ Éternel de tout son cœur, et de toute son âme, et de toute sa force, selon toute la loi de Moïse; et après lui, il ne s’en est pas levé de semblable à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Toutefois l’ Éternel ne revint point de l’ardeur de sa grande colère, dont il était embrasé contre Juda, à cause de toutes les provocations par lesquelles Manassé l’avait provoqué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Et l’ Éternel dit: J’ôterai aussi Juda de devant ma face comme j’ai ôté Israël; et je rejetterai cette ville de Jérusalem que j’ai choisie, et la maison de laquelle j’ai dit: Mon nom sera là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Et le reste des actes de Josias, et tout ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Dans ses jours, le Pharaon Neco, roi d’Égypte, monta contre le roi d’Assyrie, vers le fleuve Euphrate, et le roi Josias alla à sa rencontre; et [Neco] le tua à Meguiddo, dès qu’il le vit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Et de Meguiddo, ses serviteurs l’emportèrent mort sur un char, et l’amenèrent à Jérusalem, et l’enterrèrent dans son sépulcre. Et le peuple du pays prit Joakhaz, fils de Josias, et ils l’oignirent et le firent roi à la place de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Joakhaz était âgé de 23 ans lorsqu’il commença de régner; et il régna trois mois à Jérusalem; et le nom de sa mère était Hamutal, fille de Jérémie de Libna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, selon tout ce que ses pères avaient fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Et le Pharaon Neco le lia à Ribla, dans le pays de Hamath, pour qu’il ne règne plus à Jérusalem; et il imposa sur le pays une amende de 100 talents d’argent et d’un talent d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Et le Pharaon Neco établit roi Éliakim, fils de Josias, à la place de Josias, son père, et changea son nom en celui de Jehoïakim; et il prit Joakhaz, qui vint en Égypte et y mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Et Jehoïakim donna l’argent et l’or au Pharaon; seulement il établit une taxe proportionnelle sur le pays, pour donner l’argent selon le commandement du Pharaon: il exigea l’argent et l’or du peuple du pays, de chacun selon son estimation, pour le donner au Pharaon Neco.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, '*Jehoïakim était âgé de 25 ans lorsqu’il commença de régner; et il régna onze ans à Jérusalem; et le nom de sa mère était Zebudda, fille de Pedaïa, de Ruma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, selon tout ce que ses pères avaient fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'En ses jours, Nebucadnetsar, roi de Babylone, monta; et Jehoïakim fut son serviteur pendant trois ans; et il se retourna et se révolta contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Et l’ Éternel envoya contre lui les bandes des Chaldéens, et les bandes des Syriens, et les bandes de Moab, et les bandes des fils d’Ammon; et il les envoya contre Juda pour le détruire, selon la parole de l’ Éternel, qu’il avait prononcée par ses serviteurs les prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Certainement cela arriva par le commandement de l’ Éternel contre Juda, pour l’ôter de devant sa face, à cause des péchés de Manassé, selon tout ce qu’il avait fait,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'et aussi à cause du sang innocent qu’il avait versé, car il avait rempli Jérusalem de sang innocent; et l’ Éternel ne voulut pas [lui] pardonner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Et le reste des actes de Jehoïakim, et tout ce qu’il fit, cela n’est-il pas écrit dans le livre des chroniques des rois de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Et Jehoïakim s’endormit avec ses pères; et Jehoïakin, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Et le roi d’Égypte ne sortit plus de nouveau de son pays, car le roi de Babylone avait pris tout ce qui était au roi d’Égypte, depuis le torrent d’Égypte jusqu’au fleuve Euphrate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, '*Jehoïakin était âgé de 18 ans lorsqu’il commença de régner; et il régna trois mois à Jérusalem; et le nom de sa mère était Nehushta, fille d’Elnathan, de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, selon tout ce que son père avait fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'En ce temps-là, les serviteurs de Nebucadnetsar, roi de Babylone, montèrent contre Jérusalem, et la ville fut assiégée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Et Nebucadnetsar, roi de Babylone, vint contre la ville, pendant que ses serviteurs l’assiégeaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Et Jehoïakin, roi de Juda, sortit vers le roi de Babylone, lui, et sa mère, et ses serviteurs, et ses chefs, et ses eunuques; et le roi de Babylone le prit, la huitième année de son règne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Et il emporta de là tous les trésors de la maison de l’ Éternel et les trésors de la maison du roi, et mit en pièces tous les ustensiles d’or que Salomon, roi d’Israël, avait faits dans le temple de l’ Éternel, comme l’ Éternel l’avait dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Et il transporta tout Jérusalem, et tous les chefs, et tous les hommes forts et vaillants, 10 000 captifs, et tous les charpentiers et les forgerons; il ne demeura rien de reste que le peuple pauvre du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Et il transporta Jehoïakin à Babylone; et la mère du roi, et les femmes du roi, et ses eunuques, et les puissants du pays, il les emmena captifs de Jérusalem à Babylone,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'et tous les hommes vaillants, 7 000, et les charpentiers et les forgerons, 1 000, tous hommes propres à la guerre; et le roi de Babylone les amena captifs à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Et le roi de Babylone établit roi, à la place de Jehoïakin, Matthania, son oncle, et lui changea son nom en celui de Sédécias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sédécias était âgé de 21 ans lorsqu’il commença de régner; et il régna onze ans à Jérusalem; et le nom de sa mère était Hamutal, fille de Jérémie de Libna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, selon tout ce que Jehoïakim avait fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Car, parce que la colère de l’ Éternel fut contre Jérusalem et contre Juda, jusqu’à les rejeter de devant sa face, Sédécias se révolta contre le roi de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Et il arriva, en la neuvième année de son règne, au dixième mois, le dixième [jour] du mois, que Nebucadnetsar, roi de Babylone, vint contre Jérusalem, lui et toute son armée, et campa contre elle; et ils bâtirent contre elle une circonvallation tout à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Et la ville fut assiégée jusqu’à la onzième année du roi Sédécias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Le neuvième jour du [quatrième] mois, la famine se renforça dans la ville, et il n’y avait point de pain pour le peuple du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Et la brèche fut faite à la ville; et tous les hommes de guerre [s’enfuirent] de nuit par le chemin de la porte qui était entre les deux murailles près du jardin du roi; (et les Chaldéens étaient près de la ville tout à l’entour); et on s’en alla par le chemin de la plaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Et l’armée des Chaldéens poursuivit le roi; et ils l’atteignirent dans les plaines de Jéricho, et toute son armée se dispersa d’avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Et ils prirent le roi, et le firent monter vers le roi de Babylone à Ribla, et on prononça son jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Et on égorgea les fils de Sédécias devant ses yeux; et on creva les yeux à Sédécias, et on le lia avec des chaînes d’airain, et on l’amena à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Et au cinquième mois, le septième [jour] du mois (c’était la dix -neuvième année du roi Nebucadnetsar, roi de Babylone,) Nebuzaradan, chef des gardes, serviteur du roi de Babylone, vint à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Et il brûla la maison de l’ Éternel, et la maison du roi, et toutes les maisons de Jérusalem; et il brûla par le feu toutes les grandes maisons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Et toute l’armée des Chaldéens qui était avec le chef des gardes abattit les murailles [qui étaient] autour de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Et le reste du peuple, qui était demeuré de reste dans la ville, et les transfuges qui s’étaient rendus au roi de Babylone, et le reste de la multitude, Nebuzaradan, chef des gardes, les transporta;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'mais des pauvres du pays, le chef des gardes en laissa pour être vignerons et laboureurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Et les Chaldéens brisèrent les colonnes d’airain qui étaient devant la maison de l’ Éternel, et les bases, et la mer d’airain qui était dans la maison de l’ Éternel, et en emportèrent l’airain à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Ils prirent aussi les vases [à cendre], et les pelles, et les couteaux, et les coupes, et tous les ustensiles d’airain avec lesquels on faisait le service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Et le chef des gardes prit les brasiers et les bassins, ce qui était d’or, en or, et ce qui était d’argent, en argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Les deux colonnes, la mer unique, et les socles que Salomon avait faits pour la maison de l’ Éternel: pour l’airain de tous ces objets il n’y avait point de poids.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'La hauteur d’une colonne était de 18 coudées; et il y avait dessus un chapiteau d’airain, et la hauteur du chapiteau était de trois coudées; et il y avait un réseau et des grenades tout autour du chapiteau, le tout d’airain: et de même pour la seconde colonne, avec le réseau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Et le chef des gardes prit Seraïa, le premier sacrificateur, et Sophonie, le second sacrificateur, et les trois gardiens du seuil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'et il prit de la ville un eunuque qui était inspecteur des hommes de guerre, et cinq hommes de ceux qui voyaient la face du roi, lesquels furent trouvés dans la ville, et le scribe du chef de l’armée, qui enrôlait le peuple du pays, et 60 hommes du peuple du pays, qui furent trouvés dans la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Et Nebuzaradan, chef des gardes, les prit et les mena vers le roi de Babylone à Ribla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Et le roi de Babylone les frappa et les fit mourir à Ribla, dans le pays de Hamath. Et Juda fut transporté de dessus sa terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Et quant au peuple qui était demeuré de reste dans le pays de Juda, que Nebucadnetsar, roi de Babylone, avait laissé, il établit sur eux Guedalia, fils d’Akhikam, fils de Shaphan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Et tous les chefs des forces, eux et leurs hommes, apprirent que le roi de Babylone avait établi [chef] Guedalia; et ils vinrent vers Guedalia à Mitspa, savoir Ismaël, fils de Nethania, et Jokhanan, fils de Karéakh, et Seraïa, fils de Thanhumeth, le Netophathite, et Jaazania, fils d’un Maacathien, eux et leurs hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Et Guedalia leur jura, à eux et à leurs hommes, et leur dit: Ne craignez pas de devenir les serviteurs des Chaldéens; habitez dans le pays, et servez le roi de Babylone, et vous vous en trouverez bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Et il arriva, au septième mois, qu’Ismaël, fils de Nethania, fils d’Élishama, de la semence royale, et dix hommes avec lui, vinrent et frappèrent Guedalia, (et il mourut), et les Juifs et les Chaldéens qui étaient avec lui à Mitspa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Et tout le peuple, depuis le petit jusqu’au grand, et les chefs des forces, se levèrent et allèrent en Égypte, car ils craignaient les Chaldéens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, '*Et il arriva, en la trente-septième année de la transportation de Jehoïakin, roi de Juda, au douzième mois, le vingt-septième [jour] du mois, qu’Évil-Merodac, roi de Babylone, l’année où il commença de régner, éleva la tête de Jehoïakin, roi de Juda, [et le tira] de prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Et il lui parla avec bonté, et mit son trône au-dessus du trône des rois qui étaient avec lui à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Et il lui changea ses vêtements de prison, et [Jehoïakin] mangea le pain devant lui constamment, tous les jours de sa vie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'et quant à son entretien régulier, un entretien continuel lui fut donné de la part du roi, jour par jour, tous les jours de sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Énosh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kénan, Mahalaleël, Jéred,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Hénoc, Methushélah, Lémec,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noé; Sem, Cham, et Japheth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Les fils de Japheth: Gomer, et Magog, et Madaï, et Javan, et Tubal, et Méshec, et Tiras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, '– Et les fils de Gomer: Ashkenaz, et Diphath, et Togarma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, '– Et les fils de Javan: Élisha, et Tarsis, Kittim, et Rodanim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Les fils de Cham: Cush, et Mitsraïm, Puth, et Canaan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, '– Et les fils de Cush: Seba, et Havila, et Sabta, et Rahma, et Sabteca. – Et les fils de Rahma: Sheba et Dedan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, '– Et Cush engendra Nimrod: lui, commença à être puissant sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, '– Et Mitsraïm engendra les Ludim, et les Anamim, et les Lehabim, et les Naphtukhim,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'et les Pathrusim, et les Caslukhim (d’où sont sortis les Philistins), et les Caphtorim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, '– Et Canaan engendra Sidon, son premier-né, et Heth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'et le Jébusien, et l’Amoréen, et le Guirgasien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'et le Hévien, et l’Arkien, et le Sinien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'et l’Arvadien, et le Tsemarien, et le Hamathien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Les fils de Sem: Élam, et Assur, et Arpacshad, et Lud, et Aram, et Uts, et Hul, et Guéther, et Méshec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, '– Et Arpacshad engendra Shélakh, et Shélakh engendra Héber.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Et il naquit à Héber deux fils: le nom de l’un fut Péleg, car en ses jours la terre fut partagée; et le nom de son frère fut Joktan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Et Joktan engendra Almodad, et Shéleph, et Hatsarmaveth, et Jérakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'et Hadoram, et Uzal, et Dikla,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'et Ébal, et Abimaël, et Sheba,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'et Ophir, et Havila, et Jobab: tous ceux-là sont fils de Joktan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arpacshad, Shélakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Héber, Péleg, Rehu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nakhor, Térakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, qui est Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Les fils d’Abraham: Isaac et Ismaël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, '– Ce sont ici leurs générations: le premier-né d’Ismaël, Nebaïoth; et Kédar, et Adbeël, et Mibsam;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Mishma, et Duma; Massa, Hadad, et Théma;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Naphish, et Kedma: ce sont là les fils d’Ismaël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, '– Et les fils de Ketura, concubine d’Abraham: elle enfanta Zimran, et Jokshan, et Medan, et Madian, et Jishbak, et Shuakh. Et les fils de Jokshan: Sheba et Dedan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Et les fils de Madian: Épha, et Épher, et Hénoc, et Abida, et Eldaa. Tous ceux-là étaient fils de Ketura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Et Abraham engendra Isaac. Les fils d’Isaac: Ésaü et Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, '– Les fils d’Ésaü: Éliphaz, Rehuel, et Jehush, et Jahlam, et Coré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, '– Les fils d’Éliphaz: Théman, et Omar, Tsephi, et Gahtam; Kenaz, et Thimna, et Amalek.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, '– Les fils de Rehuel: Nakhath, Zérakh, Shamma, et Mizza.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Et les fils de Séhir: Lotan, et Shobal, et Tsibhon, et Ana, et Dishon, et Étser, et Dishan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, '– Et les fils de Lotan: Hori et Homam; et la sœur de Lotan: Thimna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, '– Les fils de Shobal: Alian, et Manakhath, et Ébal, Shephi, et Onam. – Et les fils de Tsibhon: Aïa et Ana.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, '– Les fils d’Ana: Dishon. – Et les fils de Dishon: Hamran, et Eshban, et Jithran, et Keran.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, '– Les fils d’Étser: Bilhan, et Zaavan, [et] Jaakan. – Les fils de Dishan: Uts et Aran.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Et ce sont ici les rois qui régnèrent dans le pays d’Édom, avant qu’un roi règne sur les fils d’Israël: Béla, fils de Béor; et le nom de sa ville était Dinhaba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, '– Et Béla mourut; et Jobab, fils de Zérakh, de Botsra, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, '– Et Jobab mourut; et Husham, du pays des Thémanites, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, '– Et Husham mourut; et à sa place régna Hadad, fils de Bedad, qui frappa Madian dans les champs de Moab; et le nom de sa ville était Avith.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, '– Et Hadad mourut; et Samla, de Masréka, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, '– Et Samla mourut; et Saül, de Rehoboth sur le fleuve, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, '– Et Saül mourut; et Baal-Hanan, fils d’Acbor, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, '– Et Baal-Hanan mourut; et Hadad régna à sa place; et le nom de sa ville était Pahi; et le nom de sa femme, Mehétabeël, fille de Matred, fille de Mézahab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Et Hadad mourut. Et il y eut des chefs d’Édom: le chef Thimna, le chef Alia, le chef Jetheth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'le chef Oholibama, le chef Éla, le chef Pinon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'le chef Kenaz, le chef Théman, le chef Mibtsar,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'le chef Magdiel, le chef Iram. Ce sont là les chefs d’Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Ce sont ici les fils d’Israël: Ruben, Siméon, Lévi et Juda; Issacar et Zabulon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph et Benjamin; Nephthali, Gad et Aser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, '*Les fils de Juda: Er, et Onan, et Shéla; [ces] trois lui naquirent de la fille de Shua, la Cananéenne. Et Er, premier-né de Juda, fut méchant aux yeux de l’ Éternel; et il le fit mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Et Tamar, sa belle-fille, lui enfanta Pérets et Zérakh. Tous les fils de Juda: cinq.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, '– Les fils de Pérets: Hetsron et Hamul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, '– Et les fils de Zérakh: Zimri, et Éthan, et Héman, et Calcol, et Dara: cinq en tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, '– Et les fils de Carmi: Acar, qui troubla Israël [et] qui pécha au sujet de l’exécration.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, '– Et les fils d’Éthan: Azaria.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Et les fils qui naquirent à Hetsron: Jerakhmeël, et Ram, et Kelubaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Et Ram engendra Amminadab; et Amminadab engendra Nakhshon, prince des fils de Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'et Nakhshon engendra Salma; et Salma engendra Boaz;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'et Boaz engendra Obed; et Obed engendra Isaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Et Isaï engendra son premier-né, Éliab, et Abinadab, le second, et Shimha, le troisième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Nethaneël, le quatrième; Raddaï, le cinquième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Otsem, le sixième; David, le septième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'et leurs sœurs: Tseruïa et Abigaïl. – Et les fils de Tseruïa: Abishaï, et Joab, et Asçaël, trois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, '– Et Abigaïl enfanta Amasa; et le père d’Amasa fut Jéther, Ismaélite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Et Caleb, fils de Hetsron, eut des enfants d’Azuba, [sa] femme, et de Jerioth dont voici les fils: Jésher, et Shobab, et Ardon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, '– Et Azuba mourut, et Caleb prit [pour femme] Éphrath, et elle lui enfanta Hur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'et Hur engendra Uri, et Uri engendra Betsaleël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, '– Et après cela, Hetsron vint vers la fille de Makir, père de Galaad, et la prit, lui étant âgé de 60 ans; et elle lui enfanta Segub;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'et Segub engendra Jaïr, et il eut 23 villes dans le pays de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Et Gueshur et Aram leur prirent les bourgs de Jaïr, [et] Kenath, et les villes de son ressort, 60 villes. – Tous ceux-là furent fils de Makir, père de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Et après la mort de Hetsron, à Caleb-Éphratha, Abija, la femme de Hetsron, lui enfanta encore Ashkhur, père de Thekoa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Et les fils de Jerakhmeël, premier-né de Hetsron, furent Ram, le premier-né, et Buna, et Oren, et Otsem, d’Akhija.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Et Jerakhmeël eut une autre femme, nommée Atara: elle fut mère d’Onam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, '– Et les fils de Ram, premier-né de Jerakhmeël furent Maats, et Jamin, et Éker.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, '– Et les fils d’Onam furent Shammaï et Jada; et les fils de Shammaï: Nadab et Abishur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Et le nom de la femme d’Abishur était Abikhaïl; et elle lui enfanta Akhban et Molid.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, '– Et les fils de Nadab: Séled et Appaïm; et Séled mourut sans fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Et les fils d’Appaïm: Jishi; et les fils de Jishi: Shéshan; et les fils de Shéshan: Akhlaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, '– Et les fils de Jada, frère de Shammaï: Jéther et Jonathan; et Jéther mourut sans fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Et les fils de Jonathan: Péleth et Zaza: ce furent là les fils de Jerakhmeël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, '– Et Shéshan n’eut point de fils, mais des filles; et Shéshan avait un serviteur égyptien nommé Jarkha;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'et Shéshan donna sa fille pour femme à Jarkha, son serviteur, et elle lui enfanta Atthaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'et Atthaï engendra Nathan, et Nathan engendra Zabad,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'et Zabad engendra Éphlal, et Éphlal engendra Obed,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'et Obed engendra Jéhu, et Jéhu engendra Azaria,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'et Azaria engendra Hélets, et Hélets engendra Elhasça,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'et Elhasça engendra Sismaï, et Sismaï engendra Shallum,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'et Shallum engendra Jekamia, et Jekamia engendra Élishama.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Et les fils de Caleb, frère de Jerakhmeël: Mésha, son premier-né (lui est le père de Ziph), et les fils de Marésha, père de Hébron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Et les fils de Hébron: Coré, et Thappuakh, et Rékem, et Shéma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Et Shéma engendra Rakham, père de Jorkeam. Et Rékem engendra Shammaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'et le fils de Shammaï fut Maon; et Maon fut père de Beth-Tsur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Et Épha, concubine de Caleb, enfanta Haran, et Motsa, et Gazez; et Haran engendra Gazez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, '– Et les fils de Jehdaï: Réguem, et Jotham, et Guéshan, et Péleth, et Épha, et Shaaph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, '– La concubine de Caleb, Maaca, enfanta Shéber et Tirkhana;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'et elle enfanta Shaaph, père de Madmanna, Sheva, père de Macbéna et père de Guibha; et la fille de Caleb fut Acsa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Ce sont ici les fils de Caleb: les fils de Hur, premier-né d’Éphratha: Shobal, père de Kiriath-Jéarim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, père de Bethléhem; Hareph, père de Beth-Gader.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, '– Et Shobal, père de Kiriath-Jéarim, eut des fils: Haroé, Hatsi-Hammenukhoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, '– Et les familles de Kiriath-Jéarim furent: les Jéthriens, et les Puthiens, et les Shumathiens, et les Mishraïens; de ceux-ci sont sortis les Tsorhathiens et les Eshtaoliens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, '– Les fils de Salma: Bethléhem, et les Netophathites, Atroth-Beth-Joab, et les Hatsi-Manakhthiens, les Tsorhiens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'et les familles des scribes, habitant Jahbets: les Tirhathiens, les Shimhathiens, les Sucathiens. Ceux-là sont les Kéniens, qui sont sortis de Hammath, père de la maison de Récab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, '*Et ce sont ici les fils de David qui lui naquirent à Hébron: le premier-né, Amnon, d’Akhinoam, la Jizreélite; le second, Daniel, d’Abigaïl, la Carmélite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'le troisième, Absalom, fils de Maaca, fille de Talmaï, roi de Gueshur; le quatrième, Adonija, fils de Hagguith;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'le cinquième, Shephatia, d’Abital; le sixième, Jithream, d’Égla, sa femme:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'les six lui naquirent à Hébron. Et il régna là sept ans et six mois, et il régna 33 ans à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, '– Et ceux-ci lui naquirent à Jérusalem: Shimha, et Shobab, et Nathan, et Salomon, quatre de Bath-Shua, fille d’Ammiel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'et Jibkhar, et Élishama, et Éliphéleth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'et Nogah, et Népheg, et Japhia,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'et Élishama, et Éliada, et Éliphéleth, neuf:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'tous étaient fils de David, outre les fils des concubines, – et Tamar, leur sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Et le fils de Salomon: Roboam; – Abija, son fils; Asa, son fils; Josaphat, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Joram, son fils; Achazia, son fils; Joas, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Amatsia, son fils; Azaria, son fils; Jotham, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Achaz, son fils; Ézéchias, son fils; Manassé, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Amon, son fils; Josias, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Et les fils de Josias: le premier-né, Jokhanan; le second, Jehoïakim; le troisième, Sédécias; le quatrième, Shallum.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, '– Et les fils de Jehoïakim: Jéconias, son fils; Sédécias, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, '– Et les fils de Jéconias: Assir; Shealthiel, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'et Malkiram, et Pedaïa, et Shenatsar, Jekamia, Hoshama, et Nedabia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, '– Et les fils de Pedaïa: Zorobabel et Shimhi. Et les fils de Zorobabel: Meshullam et Hanania, et Shelomith, leur sœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'et Hashuba, et Ohel, et Bérékia, et Hasadia, [et] Jushab-Hésed, cinq.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, '– Et les fils de Hanania: Pelatia et Ésaïe; les fils de Rephaïa, les fils d’Arnan, les fils d’Abdias, les fils de Shecania.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Et les fils de Shecania: Shemahia; et les fils de Shemahia: Hattush, et Jighal, et Bariakh, et Nearia, et Shaphath, six.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, '– Et les fils de Nearia: Élioénaï, et Ézéchias, et Azrikam, trois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, '– Et les fils d’Élioénaï: Hodavia, et Éliashib, et Pelaïa, et Akkub, et Jokhanan, et Delaïa, et Anani, sept.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, '*Les fils de Juda: Pérets, Hetsron, et Carmi, et Hur, et Shobal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Et Reaïa, fils de Shobal, engendra Jakhath; et Jakhath engendra Akhumaï et Lahad. Ce sont les familles des Tsorhathiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, '– Et ceux-ci [sont du] père d’Étam: Jizreël, et Jishma, et Jidbash; et le nom de leur sœur était Hatselelponi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'et Penuel, père de Guedor; et Ézer, père de Husha: ce sont les fils de Hur, premier-né d’Éphratha, père de Bethléhem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, '– Et Ashkhur, père de Thekoa, eut deux femmes, Hélea et Naara.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, '– Et Naara lui enfanta Akhuzzam, et Hépher, et Themni, et Akhashtari: ce sont les fils de Naara.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, '– Et les fils de Hélea: Tséreth, et Tsokhar, et Ethnan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, '– Et Kots engendra Anub, et Tsobéba, et les familles d’Akharkhel, fils d’Harum.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Et Jahbets fut plus honoré que ses frères; et sa mère l’avait appelé du nom de Jahbets, disant: Je l’ai enfanté avec douleur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Et Jahbets invoqua le Dieu d’Israël, disant: Si tu me bénissais abondamment, et si tu étendais mes limites, et si ta main était avec moi, et si tu me mettais à l’abri du mal, en sorte que je sois sans douleur! Et Dieu fit arriver ce qu’il avait demandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Et Kelub, frère de Shukha, engendra Mekhir; il fut père d’Eshton.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Et Eshton engendra Beth-Rapha, et Paséakh, et Thekhinna, père de la ville de Nakhash: ce sont les gens de Réca.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, '– Et les fils de Kenaz: Othniel et Seraïa; et les fils d’Othniel: Hathath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Et Méonothaï engendra Ophra; et Seraïa engendra Joab, père de la vallée des artisans; car ils étaient artisans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, '– Et les fils de Caleb, fils de Jephunné: Iru, Éla, et Naam; et les fils d’Éla,... et Kenaz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, '– Et les fils de Jehalléleël: Ziph, et Zipha, Tiria, et Asçareël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, '– Et les fils d’Esdras: Jéther, et Méred, et Épher, et Jalon; et elle conçut, [et enfanta] Miriam, et Shammaï, et Jishbakh, père d’Eshtemoa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Et sa femme, la Juive, enfanta Jéred, père de Guedor, et Héber, père de Soco, et Jekuthiel, père de Zanoakh. Et ceux-là sont les fils de Bithia, fille du Pharaon, que Méred prit [pour femme].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, '– Et les fils de la femme d’Hodija, sœur de Nakham: le père de Kehila, le Garmien, et Eshtemoa, le Maacathien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, '– Et les fils de Shimon: Amnon, et Rinna, Ben-Hanan, et Thilon. – Et les fils de Jishi: Zokheth et Ben-Zokheth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Les fils de Shéla, fils de Juda: Er, père de Léca, et Lahda, père de Marésha, et les familles de la maison des ouvriers en byssus de la maison d’Ashbéa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'et Jokim, et les gens de Cozéba, et Joas, et Saraph, qui dominèrent en Moab, et Jashubi-Lékhem. Ce sont des choses anciennes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'C’étaient les potiers, et les gens qui se tenaient dans les plantations et dans les enclos; ils habitaient là, auprès du roi, pour ses travaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, '*Les fils de Siméon: Nemuel, et Jamin, Jarib, Zérakh, [et] Saül;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Shallum, son fils; Mibsam, son fils; Mishma, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Et les fils de Mishma: Hammuel, son fils; Zaccur, son fils; Shimhi, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Et Shimhi eut 16 fils et six filles. Et ses frères n’eurent pas beaucoup de fils, et toutes leurs familles ne se multiplièrent pas comme les fils de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Et ils habitèrent à Beër-Shéba, et à Molada, et à Hatsar-Shual,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'et à Bilha, et à Étsem, et à Tholad,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'et à Bethuel, et à Horma, et à Tsiklag,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'et à Beth-Marcaboth, et à Hatsar-Susim, et à Beth-Biri, et à Shaaraïm. Ce furent leurs villes jusqu’au règne de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Et leurs villages: Étam, et Aïn, Rimmon, et Thoken, et Ashan, cinq villes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'et tous leurs villages qui étaient autour de ces villes, jusqu’à Baal. Ce sont là leurs habitations et leur registre généalogique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, '– Et Meshobab, et Jamlec, et Josha, fils d’Amatsia;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'et Joël, et Jéhu, fils de Joshibia, fils de Seraïa, fils d’Asciel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'et Élioénaï, et Jaakoba, et Jeshokhaïa, et Asçaïa, et Adiel, et Jescimiel, et Benaïa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'et Ziza, fils de Shiphi, fils d’Allon, fils de Jedaïa, fils de Shimri, fils de Shemahia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Ceux-ci, mentionnés par nom, furent princes dans leurs familles; et leurs maisons de pères se répandirent beaucoup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Et ils allèrent à l’entrée de Guedor, jusqu’à l’orient de la vallée, pour chercher des pâturages pour leur menu bétail,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'et ils trouvèrent un pâturage gras et bon, et un pays spacieux, et paisible et fertile; car ceux qui avaient habité là auparavant étaient de Cham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Et ceux-ci, écrits par nom, vinrent au temps d’Ézéchias, roi de Juda; et ils frappèrent leurs tentes et les Maonites qui se trouvaient là, et les détruisirent entièrement, jusqu’à ce jour, et habitèrent à leur place; car il y avait là des pâturages pour leur menu bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Et 500 hommes d’entre eux, des fils de Siméon, s’en allèrent à la montagne de Séhir; et ils avaient à leur tête Pelatia, et Nearia, et Rephaïa, et Uziel, les fils de Jishi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'et ils frappèrent le reste des réchappés d’Amalek; et ils ont habité là jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, '*Et les fils de Ruben, premier-né d’Israël (car il était le premier-né, mais, parce qu’il avait profané le lit de son père, son droit de premier-né fut donné aux fils de Joseph, fils d’Israël, mais [Joseph] n’a pas la primogéniture dans le registre généalogique;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'car Juda eut la prééminence au milieu de ses frères, et le prince [sort] de lui; mais le droit de premier-né fut à Joseph);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, '– les fils de Ruben, premier-né d’Israël: Hénoc et Pallu, Hetsron et Carmi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, '– Les fils de Joël: Shemahia, son fils; Gog, son fils; Shimhi, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Michée, son fils; Reaïa, son fils; Baal, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Beéra, son fils, que Tilgath-Pilnéser, roi d’Assyrie, emmena captif: lui était le prince des Rubénites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Et ses frères, selon leurs familles dans le registre généalogique de leurs générations: le chef Jehiel, et Zacharie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'et Béla, fils d’Azaz, fils de Shéma, fils de Joël; lui habitait à Aroër, et jusqu’à Nebo et Baal-Méon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'et il habita au levant jusqu’à l’entrée du désert, du côté du fleuve Euphrate, car leurs troupeaux s’étaient multipliés dans le pays de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Et, aux jours de Saül, ils firent la guerre contre les Hagaréniens, et ceux-ci tombèrent par leur main; et ils habitèrent dans leurs tentes, dans tout le [pays] à l’orient de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, '*Et les fils de Gad habitèrent à côté d’eux dans le pays de Basan, jusqu’à Salca:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joël, le chef, et Shapham, le second; et Jahnaï et Shaphath, en Basan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Et leurs frères, selon leurs maisons de pères: Micaël, et Meshullam, et Shéba, et Joraï, et Jahcan, et Zia, et Éber, sept.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, '– Ceux-ci furent les fils d’Abikhaïl, fils de Huri, fils de Jaroakh, fils de Galaad, fils de Micaël, fils de Jeshishaï, fils de Jakhdo, fils de Buz:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Akhi, fils d’Abdiel, fils de Guni, chef de leur maison de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Et ils habitèrent en Galaad, en Basan, et dans les villages de leur ressort, et dans tous les pâturages de Saron jusqu’à leurs issues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, '– Ils furent tous enregistrés dans les généalogies, aux jours de Jotham, roi de Juda, et aux jours de Jéroboam, roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Les fils de Ruben, et les Gadites, et la demi-tribu de Manassé, d’entre les vaillants, des hommes portant l’écu et l’épée, tirant de l’arc, et instruits pour la guerre: 44 760, en état d’aller à l’armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Ils firent la guerre contre les Hagaréniens, contre Jetur, et Naphish, et Nodab;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'et ils furent aidés contre eux, et les Hagaréniens et tous ceux qui étaient avec eux furent livrés en leur main; car ils crièrent à Dieu dans la bataille, et il se rendit à leurs prières, car ils avaient mis leur confiance en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Et ils prirent leurs troupeaux, 50 000 chameaux, et 250 000 moutons, et 2 000 ânes, et en hommes, 100 000,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'car il en tomba morts un grand nombre, parce que la bataille venait de Dieu: et ils habitèrent à leur place jusqu’à la transportation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, '*Et les fils de la demi-tribu de Manassé habitèrent dans le pays, depuis Basan jusqu’à Baal-Hermon, et à Senir, et à la montagne de l’Hermon: ils étaient nombreux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Et ce sont ici les chefs de leurs maisons de pères: Épher, et Jishi, et Éliel, et Azriel, et Jérémie, et Hodavia, et Jakhdiel, forts et vaillants hommes, gens de renom, chefs de leurs maisons de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Mais ils péchèrent contre le Dieu de leurs pères, et se prostituèrent après les dieux des peuples du pays, que Dieu avait détruits devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Et le Dieu d’Israël réveilla l’esprit de Pul, roi d’Assyrie, et l’esprit de Tilgath-Pilnéser, roi d’Assyrie, et il transporta les Rubénites, et les Gadites, et la demi-tribu de Manassé, et les emmena à Khalakh, et à Khabor, et à Hara, et au fleuve de Gozan, [où ils sont] jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 27, '*Les fils de Lévi: Guershom, Kehath, et Merari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 28, '– Et les fils de Kehath: Amram, Jitsehar, et Hébron, et Uziel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 29, 'Et les fils d’Amram: Aaron et Moïse, et Marie. Et les fils d’Aaron: Nadab et Abihu, Éléazar et Ithamar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 30, '– Éléazar engendra Phinées; Phinées engendra Abishua,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 31, 'et Abishua engendra Bukki, et Bukki engendra Uzzi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 32, 'et Uzzi engendra Zerakhia, et Zerakhia engendra Meraïoth;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 33, 'Meraïoth engendra Amaria, et Amaria engendra Akhitub,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 34, 'et Akhitub engendra Tsadok, et Tsadok engendra Akhimaats,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 35, 'et Akhimaats engendra Azaria, et Azaria engendra Jokhanan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 36, 'et Jokhanan engendra Azaria: c’est lui qui exerça la sacrificature dans la maison que Salomon bâtit à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 37, 'Et Azaria engendra Amaria, et Amaria engendra Akhitub,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 38, 'et Akhitub engendra Tsadok, et Tsadok engendra Shallum,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 39, 'et Shallum engendra Hilkija, et Hilkija engendra Azaria,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 40, 'et Azaria engendra Seraïa, et Seraïa engendra Jotsadak,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 41, 'et Jotsadak partit quand l’ Éternel transporta Juda et Jérusalem par la main de Nebucadnetsar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Les fils de Lévi: Guershom, Kehath, et Merari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, '– Et ce sont ici les noms des fils de Guershom: Libni et Shimhi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Et les fils de Kehath: Amram, et Jitsehar, et Hébron, et Uziel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Les fils de Merari: Makhli et Mushi. – Ce sont là les familles de Lévi, selon leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'De Guershom: Libni, son fils; Jakhath, son fils; Zimma, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Joakh, son fils; Iddo, son fils; Zérakh, son fils; Jathraï, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Les fils de Kehath: Amminadab, son fils; Coré, son fils; Assir, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Elkana, son fils; et Ébiasaph, son fils; et Assir, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Thakhath, son fils; Uriel, son fils; Ozias, son fils; et Saül, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, '– Et les fils d’Elkana: Amasçaï et Akhimoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Elkana, – les fils d’Elkana: Tsophaï, son fils; et Nakhath, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Éliab, son fils; Jerokham, son fils; Elkana, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Et les fils de Samuel: le premier-né, Vashni, et Abija.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Les fils de Merari: Makhli; Libni, son fils; Shimhi, son fils; Uzza, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Shimha, son fils; Hagguija, son fils; Asçaïa, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Et ce sont ici ceux que David établit pour la direction du chant dans la maison de l’ Éternel, depuis que l’arche fut en repos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Et ils faisaient le service devant le tabernacle de la tente d’assignation, pour le chant, jusqu’à ce que Salomon ait bâti la maison de l’ Éternel à Jérusalem; et ils se tinrent là selon l’ordre établi pour leur service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Et ce sont ici ceux qui se tenaient là, et leurs fils: Des fils des Kehathites: Héman, le chantre, fils de Joël, fils de Samuel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'fils d’Elkana, fils de Jerokham, fils d’Éliel, fils de Thoakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'fils de Tsuph, fils d’Elkana, fils de Makhath, fils d’Amasçaï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'fils d’Elkana, fils de Joël, fils d’Azaria, fils de Sophonie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'fils de Thakhath, fils d’Assir, fils d’Ébiasaph, fils de Coré,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'fils de Jitsehar, fils de Kehath, fils de Lévi, fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Et son frère Asaph, qui se tenait à sa droite: Asaph, fils de Bérékia, fils de Shimha,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'fils de Micaël, fils de Baascéïa, fils de Malkija,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'fils d’Ethni, fils de Zérakh, fils d’Adaïa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'fils d’Éthan, fils de Zimma, fils de Shimhi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'fils de Jakhath, fils de Guershom, fils de Lévi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Et les fils de Merari, leurs frères, à la gauche: Éthan, fils de Kishi, fils d’Abdi, fils de Malluc,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'fils de Hashabia, fils d’Amatsia, fils de Hilkija,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'fils d’Amtsi, fils de Bani, fils de Shémer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'fils de Makhli, fils de Mushi, fils de Merari, fils de Lévi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Et leurs frères, les Lévites, furent donnés pour tout le service du tabernacle de la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Et Aaron et ses fils faisaient fumer [ce qui se brûlait] sur l’autel de l’holocauste et sur l’autel de l’encens, pour tout le service du lieu très saint, et pour faire propitiation pour Israël, selon tout ce que Moïse, serviteur de Dieu, avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Et ce sont ici les fils d’Aaron: Éléazar, son fils; Phinées, son fils; Abishua, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Bukki, son fils; Uzzi, son fils; Zerakhia, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Meraïoth, son fils; Amaria, son fils; Akhitub, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Tsadok, son fils; Akhimaats, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Et ce sont ici leurs habitations, selon leurs enclos, dans leurs confins. – Pour les fils d’Aaron, de la famille des Kehathites, car le sort tomba pour eux:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'et on leur donna Hébron, dans le pays de Juda, et sa banlieue autour d’elle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'mais la campagne de la ville et ses hameaux, on les donna à Caleb, fils de Jephunné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Et aux fils d’Aaron on donna la ville de refuge: Hébron; et Libna et sa banlieue, et Jatthir, et Eshtemoa et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'et Hilen et sa banlieue, [et] Debir et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'et Ashan et sa banlieue, et Beth-Shémesh et sa banlieue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'et de la tribu de Benjamin: Guéba et sa banlieue, et Allémeth et sa banlieue, et Anathoth et sa banlieue. Toutes leurs villes: 13 villes, selon leurs familles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Et aux autres fils de Kehath [on donna], par le sort, dix villes, des familles de la tribu [d’Éphraïm [et de la tribu de Dan] et] de la moitié de la tribu de Manassé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'et aux fils de Guershom, selon leurs familles, 13 villes, de la tribu d’Issacar, et de la tribu d’Aser, et de la tribu de Nephthali, et de la tribu de Manassé, en Basan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, '[et] aux fils de Merari, selon leurs familles, par le sort, douze villes, de la tribu de Ruben, et de la tribu de Gad, et de la tribu de Zabulon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Et les fils d’Israël donnèrent aux Lévites les villes et leurs banlieues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Et ils donnèrent, par le sort, de la tribu des fils de Juda, et de la tribu des fils de Siméon, et de la tribu des fils de Benjamin, ces villes-là, qu’ils nommèrent par [leurs] noms.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Et pour les familles des fils de Kehath qui eurent les villes de leur territoire de la tribu d’Éphraïm,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'on leur donna la ville de refuge: Sichem et sa banlieue, dans la montagne d’Éphraïm, et Guézer et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'et Jokmeam et sa banlieue, et Beth-Horon et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'et Ajalon et sa banlieue, et Gath-Rimmon et sa banlieue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'et de la demi-tribu de Manassé: Aner et sa banlieue, et Bilham et sa banlieue, – pour les familles des autres fils de Kehath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Aux fils de Guershom, [on donna], de la famille de la demi-tribu de Manassé: Golan, en Basan, et sa banlieue, et Ashtaroth et sa banlieue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'et de la tribu d’Issacar: Kédesh et sa banlieue, Dobrath et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'et Ramoth et sa banlieue, et Anem et sa banlieue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'et de la tribu d’Aser: Mashal et sa banlieue, et Abdon et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'et Hukok et sa banlieue, et Rehob et sa banlieue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'et de la tribu de Nephthali: Kédesh, en Galilée, et sa banlieue, et Hammon et sa banlieue, et Kiriathaïm et sa banlieue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Aux fils de Merari qui restaient, [on donna], de la tribu de Zabulon: Rimmono et sa banlieue, [et] Thabor et sa banlieue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'et au-delà du Jourdain de Jéricho, à l’orient du Jourdain, de la tribu de Ruben: Bétser, au désert, et sa banlieue, et Jahtsa et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'et Kedémoth et sa banlieue, et Méphaath et sa banlieue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'et de la tribu de Gad: Ramoth, en Galaad, et sa banlieue, et Mahanaïm et sa banlieue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'et Hesbon et sa banlieue, et Jahzer et sa banlieue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, '*Et les fils d’Issacar: Thola, et Pua, Jashub, et Shimron, quatre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Et les fils de Thola: Uzzi, et Rephaïa, et Jeriel, et Jakhmaï, et Jibsam, et Samuel, chefs de leurs maisons de pères, de Thola, hommes forts et vaillants, dans leurs générations; leur nombre, aux jours de David, fut de 22 600.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, '– Et les fils d’Uzzi: Jizrakhia; et les fils de Jizrakhia: Micaël, et Abdias, et Joël, [et] Jishija, cinq, tous des chefs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Et avec eux, suivant leurs générations, selon leurs maisons de pères, il y eut des bandes de guerre pour combattre, 36 000 hommes; car ils avaient beaucoup de femmes et de fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Et leurs frères de toutes les familles d’Issacar, hommes forts et vaillants, furent en tout 87 000, enregistrés dans les généalogies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, '✶[Fils de] Benjamin: Béla, et Béker, et Jediaël, trois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Et les fils de Béla: Etsbon, et Uzzi, et Uziel, et Jerimoth, et Iri, cinq, chefs de maisons de pères, hommes forts et vaillants, et, enregistrés dans les généalogies, 22 034.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, '– Et les fils de Béker: Zemira, et Joash, et Éliézer, et Élioénaï, et Omri, et Jerémoth, et Abija, et Anathoth, et Alémeth; tous ceux-là étaient fils de Béker;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'et, enregistrés dans les généalogies, selon leurs générations, des chefs de leurs maisons de pères, hommes forts et vaillants, 20 200.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, '– Et les fils de Jediaël: Bilhan; et les fils de Bilhan: Jehush, et Benjamin, et Éhud, et Kenaana, et Zéthan, et Tarsis, et Akhishakhar;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'tous ceux-là étaient fils de Jediaël, selon les chefs des pères, hommes forts et vaillants, 17 200, formés au service pour la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, '– Et Shuppim et Huppim, fils d’Ir. – Hushim: les fils d’Akher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, '*Les fils de Nephthali: Jahtsiel, et Guni, et Jétser, et Shallum, les fils de Bilha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, '*Les fils de Manassé: Asriel, ... qu’elle enfanta. Sa concubine syrienne enfanta Makir, père de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Et Makir prit une femme, [la sœur] de Huppim et de Shuppim; et le nom de leur sœur était Maaca. Et le nom du second [fils] était Tselophkhad; et Tselophkhad n’eut que des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Et Maaca, femme de Makir, enfanta un fils, et l’appela du nom de Péresh; et le nom de son frère, Shéresh; et ses fils: Ulam et Rékem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Et les fils d’Ulam: Bedan. Ce sont là les fils de Galaad, fils de Makir, fils de Manassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, '– Et sa sœur Moléketh enfanta Ishhod, et Abiézer, et Makhla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, '– Et les fils de Shemida furent Akhian, et Sichem, et Likkhi, et Aniam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, '*Et les fils d’Éphraïm: Shuthélakh; et Béred, son fils; et Thakhath, son fils; et Elhada, son fils; et Thakhath, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'et Zabad, son fils; et Shuthélakh, son fils; et Ézer, et Elhad. Et les gens de Gath, qui étaient nés dans le pays, les tuèrent; car ils étaient descendus pour prendre leurs troupeaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Et Éphraïm, leur père, mena deuil pendant nombre de jours; et ses frères vinrent pour le consoler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Et il vint vers sa femme; et elle conçut, et enfanta un fils; et elle l’appela du nom de Beriha, car [il était né] quand le malheur était dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Et sa fille fut Shééra; et elle bâtit Beth-Horon, la basse et la haute, et Uzzen-Shééra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Et son fils fut Réphakh; et Résheph, et Thélakh, son fils; et Thakhan, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Lahdan, son fils; Ammihud, son fils; Élishama, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Nun, son fils; Josué, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Et leur possession et leurs habitations furent Béthel et les villages de son ressort; et au levant, Naaran; et au couchant, Guézer et les villages de son ressort, et Sichem et les villages de son ressort, jusqu’à Gaza et les villages de son ressort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Et aux mains des fils de Manassé étaient: Beth-Shean et les villages de son ressort, Thaanac et les villages de son ressort, Meguiddo et les villages de son ressort, Dor et les villages de son ressort. Les fils de Joseph, fils d’Israël, habitèrent dans ces [villes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, '*Les fils d’Aser: Jimna, et Jishva, et Jishvi, et Beriha, et Sérakh, leur sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Et les fils de Beriha: Héber et Malkiel; (il était père de Birzavith).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Et Héber engendra Japhleth, et Shomer, et Hotham, et Shua, leur sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Et les fils de Japhleth: Pasac, et Bimhal, et Ashvath; ce sont là les fils de Japhleth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, '– Et les fils de Shémer: Akhi, et Rohga, et Hubba, et Aram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, '– Et les fils d’Hélem, son frère: Tsophakh, et Jimnah, et Shélesh, et Amal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Les fils de Tsophakh: Suakh, et Harnépher, et Shual, et Béri, et Jimra,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bétser, et Hod, et Shamma, et Shilsha, et Jithran, et Beéra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, '– Et les fils de Jéther: Jephunné, et Pispa, et Ara.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, '– Et les fils d’Ulla: Arakh, et Hanniel, et Ritsia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, '– Tous ceux-là étaient fils d’Aser, chefs de maisons de pères, hommes d’élite, forts et vaillants hommes, chefs des princes; et, selon leur enregistrement généalogique dans l’armée pour la guerre, leur nombre fut de 26 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, '*Et Benjamin engendra Béla, son premier-né; Ashbel, le second; et Akhrakh, le troisième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Nokha, le quatrième; et Rapha, le cinquième.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, '– Et Béla eut des fils: Addar, et Guéra, et Abihud,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'et Abishua, et Naaman, et Akhoakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'et Guéra, et Shephuphan, et Huram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Et ce sont ici les fils d’Éhud (ceux-ci étaient chefs des pères des habitants de Guéba; et ils les transportèrent à Manakhath,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'savoir Naaman, et Akhija, et Guéra; – lui les transporta): il engendra Uzza, et Akhikhud.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Et Shakharaïm engendra [des fils], dans les champs de Moab, après avoir renvoyé Hushim et Baara, ses femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Et il engendra de Hodesh, sa femme: Jobab, et Tsibia, et Mésha, et Malcam,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'et Jehuts, et Shobia, et Mirma: ce sont là ses fils, des chefs des pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Et de Hushim il engendra Abitub et Elpaal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, '– Et les fils d’Elpaal: Éber, et Misham, et Shémer (lui, bâtit Ono, et Lod et les villages de son ressort),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'et Beriha, et Shéma. Ceux-ci furent chefs des pères des habitants d’Ajalon; ce furent eux qui mirent en fuite les habitants de Gath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, '– Et Akhio, Shashak, et Jerémoth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'et Zebadia, et Arad, et Éder,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'et Micaël, et Jishpa, et Jokha, furent les fils de Beriha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, '– Et Zebadia, et Meshullam, et Hizki, et Héber,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'et Jishmeraï, et Jizlia, et Jobab, furent les fils d’Elpaal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, '– Et Jakim, et Zicri, et Zabdi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'et Éliénaï, et Tsilthaï, et Éliel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'et Adaïa, et Beraïa, et Shimrath, furent les fils de Shimhi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, '– Et Jishpan, et Éber, et Éliel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'et Abdon, et Zicri, et Hanan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'et Hanania, et Élam, et Anthothija,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'et Jiphdeïa, et Penuel, furent les fils de Shashak.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, '– Et Shamsheraï, et Shekharia, et Athalia,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'et Jaaréshia, et Élie, et Zicri, furent les fils de Jerokham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Ce sont là les chefs des pères, – selon leurs générations, des chefs; ceux-là habitèrent à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, '– Et à Gabaon habita le père de Gabaon; et le nom de sa femme était Maaca.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Et son fils premier-né: Abdon; et Tsur, et Kis, et Baal, et Nadab,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'et Guedor, et Akhio, et Zéker.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Et Mikloth engendra Shimea. Et eux aussi habitèrent à côté de leurs frères à Jérusalem, avec leurs frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Et Ner engendra Kis; et Kis engendra Saül; et Saül engendra Jonathan, et Malki-Shua, et Abinadab, et Eshbaal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Et le fils de Jonathan fut Merib-Baal; et Merib-Baal engendra Michée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Et les fils de Michée: Pithon, et Mélec, et Tharéa, et Achaz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Et Achaz engendra Jehoadda; et Jehoadda engendra Alémeth, et Azmaveth, et Zimri; et Zimri engendra Motsa;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'et Motsa engendra Binha: Rapha, son fils; Elhasça, son fils; Atsel, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Et Atsel eut six fils, et ce sont ici leurs noms: Azrikam, Bocru, et Ismaël, et Shéaria, et Abdias, et Hanan; tous ceux-là furent fils d’Atsel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Et les fils d’Éshek, son frère, furent Ulam, son premier-né; Jehush, le second, et Éliphéleth, le troisième.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Et les fils d’Ulam étaient des hommes forts et vaillants, tirant de l’arc, et ils eurent beaucoup de fils et de petits-fils, 150. Tous ceux-là sont d’entre les fils de Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, '*Et tous ceux d’Israël furent enregistrés par généalogies; et voici, ils sont inscrits dans le livre des rois d’Israël. Et Juda fut transporté à Babylone à cause de ses péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Et les premiers habitants qui étaient dans leurs possessions, dans leurs villes, étaient Israël, les sacrificateurs, les lévites, et les Nethiniens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Et à Jérusalem habitèrent des fils de Juda, et des fils de Benjamin, et des fils d’Éphraïm et de Manassé:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Uthaï, fils d’Ammihud, fils d’Omri, fils d’Imri, fils de Bani, des fils de Pérets, fils de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Et des Shilonites: Asçaïa, le premier-né, et ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Et des fils de Zérakh: Jehuel, et ses frères, 690.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Et des fils de Benjamin: Sallu, fils de Meshullam, fils d’Hodavia, fils d’Hassenua;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'et Jibneïa, fils de Jerokham; et Éla, fils d’Uzzi, fils de Micri; et Meshullam, fils de Shephatia, fils de Rehuel, fils de Jibnija;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'et leurs frères, selon leurs générations, 956. Tous ces hommes-là étaient chefs des pères de leurs maisons de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Et des sacrificateurs: Jedahia, et Joïarib, et Jakin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'et Azaria, fils de Hilkija, fils de Meshullam, fils de Tsadok, fils de Meraïoth, fils d’Akhitub, prince de la maison de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'et Adaïa, fils de Jerokham, fils de Pashkhur, fils de Malkija; et Mahçaï, fils d’Adiel, fils de Jakhzéra, fils de Meshullam, fils de Meshillémith, fils d’Immer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'et leurs frères, chefs de leurs maisons de pères, 1 760 hommes forts et vaillants, pour l’œuvre du service de la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Et des lévites: Shemahia, fils de Hashub, fils d’Azrikam, fils de Hashabia, des fils de Merari;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'et Bakbakkar, Héresh, et Galal; et Matthania, fils de Michée, fils de Zicri, fils d’Asaph;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'et Abdias, fils de Shemahia, fils de Galal, fils de Jeduthun; et Bérékia, fils d’Asa, fils d’Elkana, qui habitait dans les villages des Netophathites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Et les portiers: Shallum, et Akkub, et Talmon, et Akhiman, et leurs frères; Shallum était le chef.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Et [ils sont] jusqu’à maintenant à la porte du roi, au levant; ils étaient les portiers des camps des fils de Lévi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Et Shallum, fils de Koré, fils d’Ébiasaph, fils de Coré, et ses frères, les Corites, de la maison de son père, étaient [préposés] sur l’œuvre du service, gardant les seuils de la tente: et leurs pères avaient été [préposés] sur le camp de l’ Éternel, gardant l’entrée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'et Phinées, fils d’Éléazar, fut autrefois prince sur eux: l’ Éternel était avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zacharie, fils de Meshélémia, était portier à l’entrée de la tente d’assignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Tous ceux-là, choisis pour portiers des seuils, étaient 212; ils furent enregistrés par généalogies dans leurs villages; David et Samuel, le voyant, les avaient établis dans leur charge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Et eux, et leurs fils, étaient [établis] aux portes de la maison de l’ Éternel, de la maison de la tente, pour y faire la garde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Les portiers étaient vers les quatre vents, à l’orient, à l’occident, au nord, et au midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Et leurs frères, dans leurs villages, devaient venir de sept jours en sept jours, d’un terme à l’autre, auprès d’eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'car, dans leur charge, ces quatre furent les principaux portiers: ils étaient Lévites; et ils étaient [préposés] sur les chambres et sur les trésors de la maison de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'et ils se tenaient la nuit autour de la maison de Dieu, car la garde leur en appartenait, et ils en avaient la clé, [pour ouvrir] chaque matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Il y en avait aussi quelques-uns d’entre eux [qui étaient préposés] sur les ustensiles du service; car ils les rentraient en les comptant, et ils les sortaient en les comptant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Et il y en avait qui étaient préposés sur les vases, et sur tous les ustensiles du lieu saint, et sur la fleur de farine, et sur le vin, et sur l’huile, et sur l’encens, et sur les aromates.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Et c’étaient des fils des sacrificateurs qui composaient les parfums avec les aromates.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Et Matthithia, d’entre les Lévites, premier-né de Shallum, le Corite, avait la charge de l’ouvrage des [gâteaux] cuits sur la plaque;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'et des fils des Kehathites, d’entre leurs frères, [étaient chargés] des pains à placer en rangées, pour les apprêter chaque sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Et ce sont là les chantres, chefs des pères des Lévites, qui étaient dans les chambres, étant exempts d’autres fonctions, parce que, jour et nuit, ils étaient à l’œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Ce sont les chefs des pères des Lévites, selon leurs générations, des chefs; ceux-là habitèrent à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Et à Gabaon habita le père de Gabaon, Jehiel; et le nom de sa femme était Maaca.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Et son fils premier-né: Abdon; et Tsur, et Kis, et Baal, et Ner, et Nadab,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'et Guedor, et Akhio, et Zacharie, et Mikloth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Et Mikloth engendra Shimeam. Et eux aussi habitèrent à côté de leurs frères à Jérusalem, avec leurs frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, '– Et Ner engendra Kis; et Kis engendra Saül; et Saül engendra Jonathan, et Malki-Shua, et Abinadab, et Eshbaal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, '– Et le fils de Jonathan fut Merib-Baal; et Merib-Baal engendra Michée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Et les fils de Michée: Pithon, et Mélec, et Thakhréa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, '– Et Achaz engendra Jahra; et Jahra engendra Alémeth, et Azmaveth, et Zimri. Et Zimri engendra Motsa;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'et Motsa engendra Binha: et Rephaïa, son fils; Elhasça, son fils; Atsel, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Et Atsel eut six fils, et ce sont ici leurs noms: Azrikam, Bocru, et Ismaël, et Shearia, et Abdias, et Hanan; ce furent là les fils d’Atsel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, '*Et les Philistins combattirent contre Israël, et les hommes d’Israël s’enfuirent devant les Philistins, et tombèrent tués sur la montagne de Guilboa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Et les Philistins pressèrent fortement Saül et ses fils; et les Philistins frappèrent Jonathan, et Abinadab, et Malki-Shua, fils de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Et la bataille se renforça contre Saül, et les archers l’atteignirent; et il eut peur des archers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Et Saül dit à celui qui portait ses armes: Tire ton épée, et perce-m’en, de peur que ces incirconcis ne viennent et ne m’outragent. Et celui qui portait ses armes ne voulut pas [le faire], car il avait très peur. Et Saül prit son épée, et se jeta dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Et quand celui qui portait ses armes vit que Saül était mort, il se jeta, lui aussi, sur l’épée, et mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Et Saül mourut, et ses trois fils; et toute sa maison mourut ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, '– Et tous les hommes d’Israël qui étaient dans la vallée virent que Saül et ses fils s’étaient enfuis, et qu’ils étaient morts, et ils abandonnèrent leurs villes et s’enfuirent; et les Philistins vinrent et y habitèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Et il arriva que, le lendemain, les Philistins vinrent pour dépouiller les tués, et ils trouvèrent Saül et ses fils tombés sur la montagne de Guilboa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Et ils le dépouillèrent, et prirent sa tête et ses armes, et les envoyèrent partout dans le pays des Philistins pour annoncer la bonne nouvelle à leurs idoles et au peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Et ils placèrent ses armes dans la maison de leur dieu, et clouèrent sa tête dans la maison de Dagon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Et tous ceux de Jabès de Galaad entendirent parler de tout ce que les Philistins avaient fait à Saül;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'et tous les hommes vaillants se levèrent, et prirent le corps de Saül et les corps de ses fils, et les apportèrent à Jabès; et ils enterrèrent leurs os sous le térébinthe de Jabès, et jeûnèrent sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Et Saül mourut dans son péché qu’il avait commis contre l’ Éternel, à propos de la parole de l’ Éternel, qu’il n’avait pas gardée, et aussi pour avoir interrogé [une femme] qui évoquait les esprits pour [les] consulter;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'et il ne consulta point l’ Éternel. Et il le fit mourir, et transféra le royaume à David, fils d’Isaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, '*Et tout Israël se rassembla vers David à Hébron, disant: Voici, nous sommes ton os et ta chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Et autrefois, quand aussi Saül était roi, c’était toi qui faisais sortir et qui faisais entrer Israël; et l’ Éternel, ton Dieu, t’a dit: Tu paîtras mon peuple Israël, et tu seras prince sur mon peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Et tous les anciens d’Israël vinrent vers le roi à Hébron; et David fit alliance avec eux à Hébron, devant l’ Éternel; et ils oignirent David pour roi sur Israël, selon la parole de l’ Éternel par Samuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Et David et tous ceux d’Israël s’en allèrent à Jérusalem, qui est Jébus; et là étaient les Jébusiens, habitants du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Et les habitants de Jébus dirent à David: Tu n’entreras point ici. Mais David prit la forteresse de Sion: c’est la ville de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Et David dit: Quiconque frappera le premier les Jébusiens, sera chef et capitaine. Et Joab, fils de Tseruïa, monta le premier, et fut chef.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Et David habita dans la forteresse; c’est pourquoi on l’appela ville de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Et il bâtit la ville tout à l’entour, depuis Millo, et tout autour; et Joab releva le reste de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Et David allait grandissant de plus en plus; et l’ Éternel des armées était avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Et ce sont ici les chefs des hommes forts que David avait, qui se fortifièrent dans son royaume avec lui, avec tout Israël, pour le faire roi, selon la parole de l’ Éternel touchant Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Et voici le nombre des hommes forts que David avait: Jashobham, fils de Hacmoni, chef des principaux capitaines; il leva sa lance contre 300 hommes, qu’il tua en une fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Et après lui, Éléazar, fils de Dodo, l’Akhokhite: il était l’un des trois hommes forts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Il fut avec David à Pas-Dammim; et les Philistins s’étaient assemblés là pour combattre; et il y avait une portion de champ pleine d’orge, et le peuple avait fui devant les Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Et ils se placèrent au milieu du champ, et le sauvèrent, et frappèrent les Philistins; et l’ Éternel opéra une grande délivrance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Et trois des trente chefs descendirent au rocher, vers David, dans la caverne d’Adullam, comme l’armée des Philistins était campée dans la vallée des Rephaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Et David était alors dans le lieu fort, et il y avait alors un poste des Philistins à Bethléhem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Et David convoita, et dit: Qui me fera boire de l’eau du puits de Bethléhem, qui est près de la porte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Et les trois forcèrent le passage à travers le camp des Philistins, et puisèrent de l’eau du puits de Bethléhem, qui est près de la porte, et la prirent et l’apportèrent à David; et David ne voulut pas la boire, mais il en fit une libation à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Et il dit: Loin de moi, par mon Dieu, que je fasse cela! Boirais-je le sang de ces hommes [qui sont allés] au péril de leur vie? Car c’est au péril de leur vie qu’ils l’ont apportée. Et il ne voulut pas la boire. Ces trois hommes forts firent cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Et Abishaï, frère de Joab, était chef de trois; il leva sa lance contre 300 hommes, qu’il tua. Et il eut un nom parmi les trois:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'entre les trois il fut honoré à côté des deux, et il fut leur chef; mais il n’atteignit pas les trois [premiers].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaïa, fils de Jehoïada, fils d’un homme vaillant, de Kabtseël, grand en exploits, lui, frappa deux lions de Moab; et il descendit, et frappa le lion dans une fosse, par un jour de neige.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Et c’est lui qui frappa l’homme égyptien, dont la stature était de cinq coudées; et l’Égyptien avait en sa main une lance [qui était] comme l’ensouple des tisserands; et il descendit vers lui avec un bâton, et arracha la lance de la main de l’Égyptien, et le tua avec sa propre lance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Voilà ce que fit Benaïa, fils de Jehoïada; et il eut un nom parmi les trois hommes forts:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'voici, il fut plus honoré que les trente, mais il n’atteignit pas les trois [premiers]. Et David lui donna une place dans ses audiences privées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Et les hommes vaillants de l’armée étaient: Asçaël, frère de Joab; Elkhanan, fils de Dodo, de Bethléhem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Shammoth, le Harorite; Hélets, le Pelonite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, fils d’Ikkesh, le Thekohite; Abiézer, l’Anathothite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibbecaï, le Hushathite; Ilaï, l’Akhokhite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharaï, le Netophathite; Héled, fils de Baana, le Netophathite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ithaï, fils de Ribaï, de Guibha des fils de Benjamin; Benaïa, le Pirhathonite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Huraï, des torrents de Gaash; Abiel, l’Arbathite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmaveth, le Bakharumite; Éliakhba, le Shaalbonite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Bené-Hashem, le Guizonite; Jonathan, fils de Shagué, l’Hararite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Akhiam, fils de Sacar, l’Hararite; Éliphal, fils d’Ur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hépher, le Mekérathite; Akhija, le Pelonite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hetsro, le Carmélite; Naaraï, fils d’Ezbaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joël, frère de Nathan; Mibkhar, fils d’Hagri;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Tsélek, l’Ammonite; Nakharaï, le Bérothien, qui portait les armes de Joab, fils de Tseruïa;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira, le Jéthrien; Gareb, le Jéthrien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urie, le Héthien; Zabad, fils d’Akhlaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, fils de Shiza, le Rubénite, un chef des Rubénites, et trente avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan, fils de Maaca; et Josaphat, le Mithnite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Ozias, l’Ashtarothite; Shama et Jehiel, les fils de Hotham, l’Aroérite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediaël, fils de Shimri, et Johka, son frère, le Thitsite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Éliel, de Makhavim; et Jeribaï et Joshavia, les fils d’Elnaam; et Jithma, le Moabite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Éliel, et Obed, et Jaasciel, le Metsobaïte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Et ceux-ci vinrent vers David à Tsiklag, lorsqu’il se tenait loin encore de la face de Saül, fils de Kis; et ceux-ci étaient parmi les hommes forts qui lui donnaient du secours dans la guerre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'armés d’arcs, se servant de la main droite et de la main gauche [pour lancer] des pierres, et [pour tirer] des flèches avec l’arc; ils étaient d’entre les frères de Saül, de Benjamin:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'le chef Akhiézer, et Joas, [tous deux] fils de Shemaa, le Guibhathite; et Jeziel, et Péleth, les fils d’Azmaveth; et Beraca, et Jéhu, l’Anathothite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'et Jishmahia, le Gabaonite, homme fort parmi les 30, et au-dessus des 30;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'et Jérémie, et Jakhaziel, et Jokhanan, et Jozabad, le Guedérathite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elhuzaï, et Jerimoth, et Bealia, et Shemaria, et Shephatia, le Haruphite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Elkana, et Jishija, et Azareël, et Joézer, et Jashobham, Corites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'et Joéla et Zebadia, les fils de Jerokham, de Guedor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Et, des Gadites, il se détacha, [pour se joindre] à David dans le lieu fort au désert, des hommes forts et vaillants, hommes exercés pour la guerre, armés de boucliers et de piques; et leurs faces étaient comme des faces de lions, et ils étaient prompts comme des gazelles sur les montagnes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Ézer, le premier; Abdias, le second; Éliab, le troisième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Mishmanna, le quatrième; Jérémie, le cinquième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Atthaï, le sixième; Éliel, le septième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jokhanan, le huitième; Elzabad, le neuvième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Jérémie, le dixième; Macbannaï, le onzième.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Ceux-là, d’entre les fils de Gad, étaient chefs de l’armée; le moindre [était chef] de 100 [hommes], et le plus grand, de 1 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Ce sont ceux qui traversèrent le Jourdain au premier mois, quand il regorge par-dessus tous ses bords; et ils mirent en fuite ceux de toutes les vallées, vers le levant et vers le couchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Et des fils de Benjamin et de Juda allèrent vers David dans le lieu fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Et David sortit à leur rencontre, et prit la parole et leur dit: Si c’est pour la paix que vous venez vers moi, pour m’aider, mon cœur sera uni à vous; mais si c’est pour me livrer à mes ennemis, quand il n’y a pas de violence en ma main, que le Dieu de nos pères regarde, et punisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Et l’Esprit revêtit Amasçaï, chef des principaux capitaines: Nous sommes à toi, David, et avec toi, fils d’Isaï! Paix, paix à toi, et paix à ceux qui t’aident, car ton Dieu t’aide! Et David les reçut, et les établit chefs de bandes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Et, de Manassé, il y en eut qui passèrent à David quand il vint avec les Philistins pour la bataille contre Saül; mais ils ne les aidèrent point, car, après avoir tenu conseil, les princes des Philistins le renvoyèrent, disant: Au péril de nos têtes il passera à son seigneur Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Quand il s’en alla à Tsiklag, [ceux-ci], de Manassé, passèrent à lui: Adnakh, et Jozabad, et Jediaël, et Micaël, et Jozabad, et Élihu, et Tsilthaï, chefs des milliers qui étaient dans Manassé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'et ils aidèrent David dans ses expéditions, car ils étaient tous forts et vaillants, et ils furent chefs dans l’armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Car de jour en jour il arrivait [des gens] vers David pour l’aider, jusqu’à ce que le camp fut grand, comme un camp de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Et c’est ici le nombre des hommes équipés pour l’armée, qui vinrent vers David à Hébron, afin de lui transférer le royaume de Saül, selon le commandement de l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Fils de Juda, portant le bouclier et la pique, 6 800, équipés pour l’armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Des fils de Siméon, hommes forts et vaillants pour l’armée, 7 100.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Des fils de Lévi, 4 600.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Et Jehoïada, prince [des fils] d’Aaron, et avec lui 3 700.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Et Tsadok, jeune homme fort et vaillant; et la maison de son père, 22 chefs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Et, des fils de Benjamin, frères de Saül, 3 000; car jusqu’alors la plus grande partie d’entre eux faisaient la garde de la maison de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Et, des fils d’Éphraïm, 20 800 hommes forts et vaillants, hommes de renom dans leurs maisons de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Et, de la demi-tribu de Manassé, 18 000, qu’on avait nommés par nom pour aller établir David roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Et, des fils d’Issacar, qui savaient discerner les temps pour savoir ce que devait faire Israël: leurs chefs, 200, et tous leurs frères à leur commandement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'De Zabulon, ceux qui allaient à l’armée, préparés pour le combat, avec toutes les armes de guerre: 50 000, gardant leur rang, n’ayant point un cœur double.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Et, de Nephthali, 1 000 chefs, et avec eux, portant le bouclier et la lance, 37 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Et, des Danites, préparés pour la guerre, 28 600.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Et, d’Aser, qui allaient à l’armée pour se mettre en ordre de bataille pour le combat, 40 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Et, d’au-delà le Jourdain, des Rubénites, et des Gadites, et de ceux de la demi-tribu de Manassé, avec toutes les armes de guerre pour combattre: 120 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Tous ceux-là, hommes de guerre, gardant leurs rangs en ordre de bataille, vinrent à Hébron d’un cœur droit, pour établir David roi sur tout Israël; et aussi tout le reste d’Israël était d’un seul cœur pour établir David roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Et ils furent là avec David trois jours, mangeant et buvant; car leurs frères leur avaient [tout] préparé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 41, 'Et même, ceux qui étaient le plus rapprochés d’eux, jusqu’à Issacar et à Zabulon et à Nephthali, apportaient des vivres sur des ânes et sur des chameaux et sur des mulets et sur des bœufs, des aliments de farine, des gâteaux de figues sèches, et des gâteaux de raisins secs, et du vin, et de l’huile, et du gros et du menu bétail en abondance; car il y avait de la joie en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, '*Et David tint conseil avec les chefs de milliers et de centaines, avec tous les princes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Et David dit à toute la congrégation d’Israël: Si cela est bon devant vous, et que cela vienne de l’ Éternel, notre Dieu, envoyons de tous côtés vers nos autres frères qui restent dans tous les pays d’Israël, et, en même temps, vers les sacrificateurs et les lévites, dans leurs villes et leurs banlieues, afin qu’ils se rassemblent auprès de nous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'et ramenons à nous l’arche de notre Dieu; car nous ne l’avons pas consultée aux jours de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Et toute la congrégation dit qu’on fasse ainsi; car la chose était bonne aux yeux de tout le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Et David assembla tout Israël, depuis le Shikhor d’Égypte jusqu’à l’entrée de Hamath, pour faire venir de Kiriath-Jéarim l’arche de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Et David monta, et tout Israël, à Baala, à Kiriath-Jéarim, qui appartient à Juda, pour en faire monter l’arche de Dieu, l’ Éternel, qui siège entre les chérubins, duquel le nom est placé [là].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Et ils montèrent l’arche de Dieu sur un chariot neuf, [et l’emmenèrent] de la maison d’Abinadab; et Uzza et Akhio conduisaient le chariot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Et David et tout Israël s’égayaient devant Dieu de toute leur force, avec des cantiques, et des harpes, et des luths, et des tambourins, et des cymbales, et des trompettes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Et ils arrivèrent à l’aire de Kidon, et Uzza étendit sa main pour saisir l’arche, parce que les bœufs avaient bronché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Et la colère de l’ Éternel s’embrasa contre Uzza, et il le frappa, parce qu’il avait étendu sa main sur l’arche; et il mourut là devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Alors David fut irrité, car l’ Éternel avait fait une brèche en [la personne d’]Uzza; et il appela ce lieu-là du nom de Pérets-Uzza, [qui lui est resté] jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Et David eut peur de Dieu en ce jour-là, disant: Comment ferais-je entrer chez moi l’arche de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Et David ne retira pas l’arche chez lui dans la ville de David, mais il la fit détourner dans la maison d’Obed-Édom, le Guitthien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Et l’arche de Dieu demeura trois mois avec la famille d’Obed-Édom, dans sa maison; et l’ Éternel bénit la maison d’Obed-Édom et tout ce qui lui appartenait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Et Hiram, roi de Tyr, envoya des messagers à David, et des bois de cèdre, et des maçons, et des charpentiers, pour lui bâtir une maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Et David connut que l’ Éternel l’avait établi roi sur Israël, car son royaume était haut élevé à cause de son peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Et David prit encore des femmes à Jérusalem, et David engendra encore des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Et ce sont ici les noms des enfants qu’il eut à Jérusalem: Shammua, et Shobab, Nathan, et Salomon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'et Jibkhar, et Élishua, et Elpéleth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'et Nogah, et Népheg, et Japhia,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'et Élishama, et Beéliada, et Éliphéleth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Et les Philistins apprirent que David avait été oint pour roi sur tout Israël, et tous les Philistins montèrent pour chercher David; et David l’apprit, et sortit au-devant d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Et les Philistins vinrent et se répandirent dans la vallée des Rephaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Et David interrogea Dieu, disant: Monterai-je contre les Philistins, et les livreras-tu en ma main? Et l’ Éternel lui dit: Monte, et je les livrerai en ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Et ils montèrent à Baal-Peratsim, et là David les frappa; et David dit: Dieu a fait une brèche au milieu de mes ennemis par ma main, comme une brèche faite par les eaux; c’est pourquoi on appela le nom de ce lieu Baal-Peratsim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Et ils laissèrent là leurs dieux, et David commanda qu’on les brûle au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Et les Philistins se répandirent encore de nouveau dans la vallée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Et David interrogea encore Dieu; et Dieu lui dit: Tu ne monteras pas après eux; tourne autour d’eux, et tu viendras contre eux vis-à-vis des mûriers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'et aussitôt que tu entendras sur le sommet des mûriers un bruit de gens qui marchent, alors tu sortiras pour la bataille, car Dieu sera sorti devant toi pour frapper l’armée des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Et David fit comme Dieu lui avait commandé; et ils frappèrent l’armée des Philistins depuis Gabaon jusque vers Guézer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Et le nom de David se répandit dans tous les pays; et l’ Éternel mit la frayeur [de David] sur toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Et il fit pour lui des maisons dans la ville de David, et prépara un lieu pour l’arche de Dieu, et tendit une tente pour elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Alors David dit: Il ne convient pas que l’arche de Dieu soit portée par personne excepté les Lévites; car l’ Éternel les a choisis pour porter l’arche de Dieu et pour en faire le service à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Et David assembla tout Israël à Jérusalem, pour faire monter l’arche de l’ Éternel au lieu qu’il lui avait préparé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Et David assembla les fils d’Aaron et les Lévites:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'des fils de Kehath, Uriel, le chef, et ses frères, 120 [hommes];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'des fils de Merari, Asçaïa, le chef, et ses frères, 220;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'des fils de Guershom, Joël, le chef, et ses frères, 130;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'des fils d’Élitsaphan, Shemahia, le chef, et ses frères, 200;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'des fils de Hébron, Éliel, le chef, et ses frères, 80;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'des fils d’Uziel, Amminadab, le chef, et ses frères, 112.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Et David appela Tsadok et Abiathar, les sacrificateurs, et les Lévites, Uriel, Asçaïa, et Joël, Shemahia, et Éliel, et Amminadab;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'et il leur dit: Vous êtes les chefs des pères des Lévites; sanctifiez-vous, vous et vos frères, et faites monter l’arche de l’ Éternel, le Dieu d’Israël, au [lieu que] je lui ai préparé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Car, parce que vous ne l’avez pas [fait] la première fois, l’ Éternel, notre Dieu, a fait une brèche parmi nous; car nous ne l’avons pas recherché conformément à l’ordonnance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Et les sacrificateurs et les Lévites se sanctifièrent pour faire monter l’arche de l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Et les fils des Lévites portèrent l’arche de Dieu sur leurs épaules, avec les barres sur eux, comme Moïse l’avait commandé, selon la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Et David dit aux chefs des Lévites d’établir leurs frères, les chantres, avec des instruments de musique, des luths, et des harpes, et des cymbales, qu’ils feraient retentir en élevant leur voix avec joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Et les Lévites établirent Héman, fils de Joël; et, d’entre ses frères, Asaph, fils de Bérékia; et, d’entre les fils de Merari, leurs frères, Éthan, fils de Kushaïa;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'et avec eux leurs frères du second rang: Zacharie, Ben, et Jaaziel, et Shemiramoth, et Jekhiel, et Unni, Éliab, et Benaïa, et Maascéïa, et Matthithia, et Éliphelé, et Miknéïa, et Obed-Édom, et Jehiel, les portiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Et les chantres, Héman, Asaph, et Éthan, avec des cymbales d’airain, pour les faire retentir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'et Zacharie, et Aziel, et Shemiramoth, et Jekhiel, et Unni, et Éliab, et Maascéïa, et Benaïa, avec des luths, sur [le mode] d’Alamoth;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'et Matthithia, et Éliphelé, et Miknéïa, et Obed-Édom, et Jehiel, et Azazia, avec des harpes sur [le mode] de Sheminith, pour diriger le chant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Et Kenania, le chef des Lévites pour la musique, enseignait la musique; car il était intelligent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Et Bérékia et Elkana étaient portiers pour l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Et Shebania, et Josaphat, et Nethaneël, et Amasçaï, et Zacharie, et Benaïa, et Éliézer, les sacrificateurs, sonnaient avec des trompettes devant l’arche de Dieu; et Obed-Édom et Jekhija étaient portiers pour l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Et David, et les anciens d’Israël, et les chefs de milliers, allèrent pour faire monter l’arche de l’alliance de l’ Éternel, de la maison d’Obed-Édom, avec joie:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'et il arriva que, quand Dieu aida les Lévites qui portaient l’arche de l’alliance de l’ Éternel, ils sacrifièrent sept veaux et sept béliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Et David était vêtu d’une robe de byssus, ainsi que tous les Lévites qui portaient l’arche, et les chantres, et Kenania, le chef de la musique des chantres; et David avait sur lui un éphod de lin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Et tout Israël faisait monter l’arche de l’alliance de l’ Éternel avec des cris de joie, et au son du cor, et avec des trompettes et des cymbales, et en faisant retentir des luths et des harpes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Et comme l’arche de l’alliance de l’ Éternel arrivait à la ville de David, Mical, fille de Saül, regarda par la fenêtre, et elle vit le roi David sautant et jouant, et elle le méprisa dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Et ils amenèrent l’arche de Dieu, et la placèrent dans la tente que David avait tendue pour elle; et ils présentèrent des holocaustes et des sacrifices de prospérités devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Et quand David eut achevé d’offrir les holocaustes et les sacrifices de prospérités, il bénit le peuple au nom de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'et il distribua à tous ceux d’Israël, tant aux femmes qu’aux hommes, à chacun un pain, et une ration [de vin], et un gâteau de raisins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Et il établit des Lévites devant l’arche de l’ Éternel pour faire le service, et pour rappeler et célébrer et louer l’ Éternel, le Dieu d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asaph, le chef, et Zacharie, le second après lui, [et] Jehiel, et Shemiramoth, et Jekhiel, et Matthithia, et Éliab, et Benaïa, et Obed-Édom, et Jehiel, avec des instruments, des luths, et des harpes; et Asaph faisait retentir les cymbales.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Et Benaïa et Jakhaziel, les sacrificateurs, étaient continuellement avec des trompettes devant l’arche de l’alliance de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, '*Alors, en ce jour, David remit entre les mains d’Asaph et de ses frères [ce psaume], le premier, pour célébrer l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Célébrez l’ Éternel, invoquez son nom, faites connaître parmi les peuples ses actes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Chantez-lui, chantez-lui des cantiques! Méditez toutes ses œuvres merveilleuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Glorifiez-vous de son saint nom; que le cœur de ceux qui cherchent l’ Éternel se réjouisse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Recherchez l’ Éternel et sa force, cherchez continuellement sa face;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Souvenez-vous de ses œuvres merveilleuses qu’il a faites, de ses prodiges, et des jugements de sa bouche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Vous, semence d’Israël, son serviteur, vous, fils de Jacob, ses élus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Lui, l’ Éternel, est notre Dieu; ses jugements sont en toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Souvenez-vous pour toujours de son alliance, de la parole qu’il commanda pour mille générations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, '[De l’alliance] qu’il a faite avec Abraham, et qu’il a jurée à Isaac,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Et qu’il a établie pour Jacob comme statut, pour Israël comme alliance perpétuelle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Disant: Je te donnerai le pays de Canaan, le lot de votre héritage,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Quand vous étiez un petit nombre d’hommes, peu de chose, et étrangers dans le [pays];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Et ils allaient de nation en nation, et d’un royaume vers un autre peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Il ne permit à personne de les opprimer, et il reprit des rois à cause d’eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '[Disant]: Ne touchez pas à mes oints, et ne faites pas de mal à mes prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Chantez à l’ Éternel, toute la terre; annoncez de jour en jour son salut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Racontez parmi les nations sa gloire, parmi tous les peuples ses œuvres merveilleuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Car l’ Éternel est grand et fort digne de louange, et il est terrible par-dessus tous les dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Car tous les dieux des peuples sont des idoles, mais l’ Éternel a fait les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'La majesté et la magnificence sont devant lui, la force et la joie sont dans le lieu où il habite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Familles des peuples, rendez à l’ Éternel, rendez à l’ Éternel la gloire et la force!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Rendez à l’ Éternel la gloire de son nom; apportez une offrande et entrez devant lui; adorez l’ Éternel en sainte magnificence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Tremblez devant lui, toute la terre. Aussi le monde est affermi, il ne sera pas ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Que les cieux se réjouissent, et que la terre s’égaie, et qu’on dise parmi les nations: L’ Éternel règne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Que la mer bruie, et tout ce qui la remplit; que les champs se réjouissent, et tout ce qui est en eux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Alors les arbres de la forêt chanteront de joie devant l’ Éternel, car il vient pour juger la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Célébrez l’ Éternel, car il est bon, car sa bonté [demeure] à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Et dites: Sauve-nous, ô Dieu de notre salut; et rassemble-nous et délivre-nous d’entre les nations, afin que nous célébrions ton saint nom, [et] que nous nous glorifiions de ta louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Béni soit l’ Éternel, le Dieu d’Israël, de l’éternité jusqu’en éternité! Et tout le peuple dit: Amen! et loua l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Et [David] laissa là, devant l’arche de l’alliance de l’ Éternel, Asaph et ses frères, pour faire le service devant l’arche continuellement, selon l’œuvre de chaque jour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'et Obed-Édom et ses frères, [au nombre de] 68, et Obed-Édom, fils de Jeduthun, et Hosa, pour portiers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'et Tsadok, le sacrificateur, et ses frères les sacrificateurs, devant le tabernacle de l’ Éternel, au haut lieu qui était à Gabaon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'pour offrir des holocaustes à l’ Éternel sur l’autel de l’holocauste continuellement, matin et soir, et selon tout ce qui est écrit dans la loi de l’ Éternel, qu’il commanda à Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'et avec eux Héman et Jeduthun, et le reste de ceux qui furent choisis, qui furent désignés par nom, pour célébrer l’ Éternel, parce que sa bonté [demeure] à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'et Héman et Jeduthun avaient avec eux des trompettes et des cymbales pour ceux qui [les] faisaient retentir, et les instruments de musique de Dieu; et les fils de Jeduthun [se tenaient] à la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Et tout le peuple s’en alla, chacun en sa maison; et David s’en retourna pour bénir sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, '*Et il arriva, comme David habitait dans sa maison, que David dit à Nathan, le prophète: Voici, moi j’habite dans une maison de cèdres, et l’arche de l’alliance de l’ Éternel est sous des tapis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Et Nathan dit à David: Fais tout ce qui est dans ton cœur, car Dieu est avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Et il arriva, cette nuit-là, que la parole de Dieu vint à Nathan, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Va, et dis à David, mon serviteur: Ainsi dit l’ Éternel: Tu ne me bâtiras pas de maison pour y habiter;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'car je n’ai pas habité dans une maison, depuis le jour où j’ai fait monter Israël, jusqu’à ce jour; mais j’ai été de tente en tente, et de demeure [en demeure].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Partout où j’ai marché au milieu de tout Israël, ai-je dit un mot à l’un des juges d’Israël, à qui j’ai commandé de paître mon peuple, en disant: Pourquoi ne me bâtissez-vous pas une maison de cèdres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Et maintenant, tu diras ainsi à mon serviteur, à David: Ainsi dit l’ Éternel des armées: Je t’ai pris des parcs, d’auprès du menu bétail, pour que tu sois prince sur mon peuple Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'et j’ai été avec toi partout où tu as marché; et j’ai retranché tous tes ennemis de devant toi, et je t’ai fait un nom, comme le nom des grands qui sont sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Et j’ai établi un lieu à mon peuple Israël, et je le planterai, et il habitera chez lui, et ne sera plus agité; et les fils d’iniquité ne le consumeront plus comme au commencement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'et depuis les jours où j’ai établi des juges sur mon peuple Israël. Et je subjuguerai tous tes ennemis; et je t’annonce que l’ Éternel te bâtira une maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Et il arrivera, quand tes jours seront accomplis pour t’en aller vers tes pères, que je susciterai après toi ta semence, qui sera un de tes fils, et j’affermirai son royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Lui, me bâtira une maison; et j’affermirai son trône pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Moi, je lui serai pour père, et lui me sera pour fils; et je ne retirerai pas d’avec lui ma bonté, comme je l’ai retirée de celui qui a été avant toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'et je l’établirai dans ma maison et dans mon royaume à toujours, et son trône sera affermi pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Nathan parla ainsi à David, selon toutes ces paroles et selon toute cette vision.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Et le roi David entra et s’assit devant l’ Éternel, et dit: Qui suis-je, Éternel Dieu! et quelle est ma maison, que tu m’aies amené jusqu’ici?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Et cela a été peu de chose à tes yeux, ô Dieu! et tu as parlé de la maison de ton serviteur pour un long avenir, et tu m’as regardé selon le rang d’un homme haut élevé, ô Éternel Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Que pourrait te [dire] encore David pour la gloire de ton serviteur? Et toi, tu connais ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Ô Éternel! tu as fait toute cette grande chose à cause de ton serviteur, et selon ton cœur, pour faire connaître toutes ces grandes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Ô Éternel! il n’y en a point comme toi, et il n’y a point de Dieu si ce n’est toi, selon tout ce que nous avons entendu de nos oreilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Et qui est comme ton peuple Israël, seule nation sur la terre que Dieu soit allé racheter, afin qu’elle lui soit un peuple,... pour te faire un nom, par de grands et terribles [actes], en chassant les nations de devant ton peuple, que tu as racheté d’Égypte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Et tu t’es fait de ton peuple Israël un peuple, à toujours; et toi, Éternel, tu es devenu leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Et maintenant, ô Éternel, que la parole que tu as prononcée touchant ton serviteur et touchant sa maison soit ferme à toujours, et fais comme tu as dit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'et que cela soit ferme, et que ton nom soit magnifié à toujours, de sorte qu’on dise: L’ Éternel des armées, le Dieu d’Israël, est Dieu à Israël. Et que la maison de David, ton serviteur, soit affermie devant toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Car toi, ô mon Dieu, tu as révélé à ton serviteur que tu lui bâtiras une maison; c’est pourquoi ton serviteur a trouvé [dans son cœur] de te présenter [cette] prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Et maintenant, ô Éternel, toi, tu es Dieu, et tu as dit ce bien à ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Et maintenant, qu’il te plaise de bénir la maison de ton serviteur, afin qu’elle soit à toujours devant toi; car toi, ô Éternel, tu l’as bénie, et elle sera bénie pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, '*Et il arriva, après cela, que David frappa les Philistins et les subjugua, et prit Gath et les villes de son ressort de la main des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Et il frappa Moab, et les Moabites devinrent serviteurs de David: ils lui apportèrent des présents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Et David frappa Hadarézer, roi de Tsoba, à Hamath, comme il allait pour établir sa puissance sur le fleuve Euphrate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Et David lui prit 1 000 chars, et 7 000 cavaliers, et 20 000 hommes de pied; et David coupa les jarrets [aux chevaux] de tous les chars, mais il réserva 100 attelages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Et les Syriens de Damas vinrent au secours d’Hadarézer, roi de Tsoba; et David frappa 22 000 hommes des Syriens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Et David mit [des garnisons] dans la Syrie de Damas, et les Syriens devinrent serviteurs de David: ils lui apportèrent des présents. Et l’ Éternel sauvait David partout où il allait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Et David prit les boucliers d’or qui étaient aux serviteurs d’Hadarézer, et les apporta à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Et de Tibkhath et de Cun, villes d’Hadarézer, David prit une grande quantité d’airain, dont Salomon fit la mer d’airain, et les colonnes, et les vases d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Et Tohu, roi de Hamath, apprit que David avait frappé toutes les forces d’Hadarézer, roi de Tsoba;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'et il envoya Hadoram, son fils, au roi David, pour le saluer et le féliciter de ce qu’il avait fait la guerre à Hadarézer et l’avait battu; car Hadarézer était continuellement en guerre avec Tohu; [il envoya] aussi toutes sortes de vases d’or, et d’argent, et d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Ceux-ci aussi, le roi David les consacra à l’ Éternel, avec l’argent et l’or qu’il avait emportés de toutes les nations, d’Édom, et de Moab, et des fils d’Ammon, et des Philistins, et d’Amalek.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Et Abishaï, fils de Tseruïa, frappa dans la vallée du Sel 18 000 [hommes] d’Édom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'et il mit des garnisons en Édom, et tout Édom fut asservi à David. Et l’ Éternel sauvait David partout où il allait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Et David régna sur tout Israël, et il faisait droit et justice à tout son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Et Joab, fils de Tseruïa, était [préposé] sur l’armée; et Josaphat, fils d’Akhilud, était rédacteur des chroniques;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'et Tsadok, fils d’Akhitub, et Abimélec, fils d’Abiathar, étaient sacrificateurs; et Shavsha était scribe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'et Benaïa, fils de Jehoïada, était [préposé] sur les Keréthiens et les Peléthiens; et les fils de David étaient les premiers à côté du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, '*Et il arriva, après cela, que Nakhash, roi des fils d’Ammon, mourut; et son fils régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Et David dit: J’userai de bonté envers Hanun, fils de Nakhash, car son père a usé de bonté envers moi. Et David envoya des messagers pour le consoler au sujet de son père. Et les serviteurs de David arrivèrent dans le pays des fils d’Ammon, vers Hanun, pour le consoler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Et les chefs des fils d’Ammon dirent à Hanun: Est-ce, à tes yeux, pour honorer ton père que David t’a envoyé des consolateurs? N’est-ce pas pour reconnaître et détruire et explorer le pays, que ses serviteurs sont venus vers toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Et Hanun prit les serviteurs de David, et les fit raser, et fit couper leurs vêtements par le milieu jusqu’au bas des reins, et les renvoya.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Et on alla, et on informa David au sujet de ces hommes; et il envoya à leur rencontre, car les hommes étaient très confus. Et le roi dit: Habitez à Jéricho jusqu’à ce que votre barbe ait poussé, alors vous reviendrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Et les fils d’Ammon virent qu’ils s’étaient mis en mauvaise odeur auprès de David; et Hanun et les fils d’Ammon envoyèrent 1 000 talents d’argent pour prendre à leur solde, de la Mésopotamie, et de la Syrie de Maaca, et de Tsoba, des chars et des cavaliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Et ils prirent à leur solde 32 000 hommes de chars, et le roi de Maaca avec son peuple; et ils vinrent et campèrent devant Médeba. Et les fils d’Ammon s’assemblèrent de leurs villes, et vinrent pour combattre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Et David l’apprit, et il envoya Joab et toute l’armée, les hommes forts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Et les fils d’Ammon sortirent, et se rangèrent en bataille à l’entrée de la ville; et les rois qui étaient venus étaient à part dans la campagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Et Joab vit que le front de la bataille était contre lui, devant et derrière; et il choisit des hommes de toute l’élite d’Israël, et les rangea contre les Syriens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'et le reste du peuple, il le plaça sous la main d’Abishaï, son frère, et ils se rangèrent contre les fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Et il dit: Si les Syriens sont plus forts que moi, tu me seras en aide; et si les fils d’Ammon sont plus forts que toi, je t’aiderai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Sois fort, et fortifions-nous à cause de notre peuple et à cause des villes de notre Dieu; et que l’ Éternel fasse ce qui est bon à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Et Joab s’approcha, et le peuple qui était avec lui, au-devant des Syriens, pour livrer bataille; et ils s’enfuirent devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Et quand les fils d’Ammon virent que les Syriens s’étaient enfuis, ils s’enfuirent, eux aussi, devant Abishaï, son frère, et rentrèrent dans la ville. Et Joab vint à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Et quand les Syriens virent qu’ils étaient battus devant Israël, ils envoyèrent des messagers, et firent sortir les Syriens qui étaient au-delà du fleuve; et Shophac, chef de l’armée d’Hadarézer, était à leur tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Et cela fut rapporté à David, et il assembla tout Israël, et passa le Jourdain, et vint à eux, et se rangea [en bataille] contre eux. Et David se rangea en bataille contre les Syriens; et ils se battirent avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Et les Syriens s’enfuirent de devant Israël; et David tua aux Syriens 7 000 chars, et 40 000 hommes de pied, et il mit à mort Shophac, chef de l’armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Et les serviteurs d’Hadarézer virent qu’ils étaient battus devant Israël, et ils firent la paix avec David, et le servirent. Et les Syriens ne voulurent plus aider les fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Et il arriva, au temps du retour de l’année, au temps où les rois entrent en campagne, que Joab conduisit le gros de l’armée, et dévasta le pays des fils d’Ammon; et il vint et assiégea Rabba; mais David resta à Jérusalem. Et Joab frappa Rabba et la détruisit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Et David prit la couronne de leur roi de dessus sa tête (or elle fut trouvée du poids d’un talent d’or, et il y avait dessus des pierres précieuses); et elle fut [mise] sur la tête de David; et il emmena de la ville une grande quantité de butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Et il fit sortir le peuple qui s’y trouvait, et les scia avec la scie, et avec des herses de fer, et avec des scies: et David fit ainsi à toutes les villes des fils d’Ammon. Et David et tout le peuple s’en retournèrent à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Et il arriva, après cela, qu’il y eut un combat à Guézer avec les Philistins. Alors Sibbecaï, le Hushathite, frappa Sippaï [qui était] d’entre les enfants du géant; et ils furent subjugués.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Et il y eut encore un combat avec les Philistins: et Elkhanan, fils de Jaïr, frappa Lakhmi, frère de Goliath, le Guitthien; et le bois de sa lance était comme l’ensouple des tisserands.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Et il y eut encore un combat à Gath: et il y avait [là] un homme de haute stature qui avait six doigts et six [orteils], [en tout] 24; et lui aussi était né au géant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Et il outragea Israël; mais Jonathan, fils de Shimha, frère de David, le frappa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ceux-là étaient nés au géant, à Gath, et tombèrent par la main de David et par la main de ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, '*Et Satan se leva contre Israël, et incita David à dénombrer Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Et David dit à Joab et aux chefs du peuple: Allez, faites le dénombrement d’Israël depuis Beër-Shéba jusqu’à Dan; et rapportez-le-moi, afin que j’en sache le nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Et Joab dit: Que l’ Éternel ajoute à son peuple 100 fois autant qu’il y en a! Ô roi, mon seigneur, ne sont-ils pas tous serviteurs de mon seigneur? Pourquoi mon seigneur cherche-t-il cela? Pourquoi la culpabilité en viendrait-elle sur Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Mais la parole du roi prévalut sur Joab; et Joab sortit, et alla par tout Israël, et revint à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Et Joab donna à David le chiffre du recensement du peuple; et il y avait, de tout Israël, 1 100 000 hommes tirant l’épée, et, de Juda, 470 000 hommes tirant l’épée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'mais Lévi et Benjamin, il ne les dénombra pas au milieu d’eux; car la parole du roi était une abomination pour Joab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Et cette chose fut mauvaise aux yeux de Dieu; et il frappa Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Et David dit à Dieu: J’ai grandement péché en ce que j’ai fait cette chose; et maintenant, fais passer, je te prie, l’iniquité de ton serviteur, car j’ai agi très follement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Et l’ Éternel parla à Gad, le voyant de David, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Va, et parle à David, en disant: Ainsi dit l’ Éternel: Je te propose trois choses; choisis-en une, et je te la ferai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Et Gad vint vers David, et lui dit: Ainsi dit l’ Éternel: Prends pour toi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'ou trois ans de famine, ou d’être pourchassé trois mois devant tes adversaires et d’être atteint par l’épée de tes ennemis, ou pendant trois jours l’épée de l’ Éternel et la peste dans le pays, et l’ange de l’ Éternel détruisant dans tous les confins d’Israël. Et maintenant, vois quelle parole je rapporterai à celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Et David dit à Gad: Je suis dans une grande détresse. Que je tombe, je te prie, dans les mains de l’ Éternel, car ses compassions sont très grandes; et que je ne tombe point dans la main des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Et l’ Éternel envoya la peste en Israël; et il tomba d’Israël 70 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Et Dieu envoya un ange à Jérusalem pour la détruire; et comme il détruisait, l’ Éternel [le] vit et se repentit de ce mal, et dit à l’ange qui détruisait: Assez! Retire maintenant ta main. Or l’ange de l’ Éternel se tenait près de l’aire d’Ornan, le Jébusien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Et David leva ses yeux, et vit l’ange de l’ Éternel se tenant entre la terre et les cieux, ayant en sa main son épée nue étendue sur Jérusalem. Et David et les anciens, couverts de sacs, tombèrent sur leurs faces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Et David dit à Dieu: N’est-ce pas moi qui ai commandé de dénombrer le peuple? C’est moi qui ai péché et qui ai mal agi; mais ces brebis, qu’ont-elles fait? Éternel, mon Dieu, je te prie, que ta main soit sur moi et sur la maison de mon père, mais qu’elle ne soit pas sur ton peuple pour le frapper.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Et l’ange de l’ Éternel commanda à Gad de dire à David, que David monte pour dresser un autel à l’ Éternel dans l’aire d’Ornan, le Jébusien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Et David monta, selon la parole de Gad, qu’il avait dite au nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Et Ornan se retourna et vit l’ange; et ses quatre fils se cachèrent avec lui: et Ornan foulait du froment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Et David vint à Ornan; et Ornan regarda, et vit David, et sortit de l’aire, et se prosterna devant David, le visage contre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Et David dit à Ornan: Donne-moi la place de l’aire, et j’y bâtirai un autel à l’ Éternel; donne-la-moi pour son plein [prix] en argent, afin que la plaie soit arrêtée de dessus le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Et Ornan dit à David: Prends-la pour toi, et que le roi, mon seigneur, fasse ce qui est bon à ses yeux. Vois, je donne les bœufs pour l’holocauste, et les traîneaux à fouler pour le bois, et le froment pour le gâteau: je donne tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Et le roi David dit à Ornan: Non, car certainement je l’ achèterai pour son plein [prix] en argent; car je ne prendrai pas pour l’ Éternel ce qui est à toi, pour offrir un holocauste qui ne coûte rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Et David donna à Ornan pour la place, en sicles d’or, le poids de 600 [sicles].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Et David bâtit là un autel à l’ Éternel, et offrit des holocaustes et des sacrifices de prospérités, et invoqua l’ Éternel; et il lui répondit par le feu des cieux sur l’autel de l’holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Et l’ Éternel parla à l’ange, et il remit son épée dans son fourreau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'En ce temps-là, David, voyant que l’ Éternel lui avait répondu dans l’aire d’Ornan, le Jébusien, y sacrifia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Et le tabernacle de l’ Éternel, que Moïse avait fait dans le désert, et l’autel de l’holocauste, étaient en ce temps-là sur le haut lieu de Gabaon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'et David ne put point aller devant cet [autel] pour rechercher Dieu, car il était épouvanté à cause de l’épée de l’ange de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Et David dit: C’est ici la maison de l’ Éternel Dieu, et c’est ici l’autel pour l’holocauste d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Et David ordonna de rassembler les étrangers qui étaient dans le pays d’Israël, et il établit des tailleurs de pierres pour tailler des pierres de taille, pour bâtir la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Et David prépara du fer en abondance, pour les clous pour les battants des portes et pour les assemblages, et de l’airain en abondance, sans poids,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'et des bois de cèdre sans nombre, car les Sidoniens et les Tyriens amenèrent à David des bois de cèdre en abondance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Car David dit: Salomon, mon fils, est jeune et délicat, et la maison à bâtir pour l’ Éternel doit être très grande en renom et en beauté dans tous les pays; ainsi je préparerai pour elle [ce qu’il faut]: et David le prépara en abondance avant sa mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Et il appela Salomon, son fils, et lui commanda de bâtir une maison à l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Et David dit à Salomon: Mon fils, j’ai eu à cœur de bâtir une maison pour le nom de l’ Éternel, mon Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'mais la parole de l’ Éternel vint à moi, disant: Tu as versé beaucoup de sang, et tu as fait de grandes guerres; tu ne bâtiras point une maison à mon nom, car tu as versé beaucoup de sang sur la terre devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Voici, un fils te naîtra; lui, sera un homme de paix; et je lui donnerai du repos de tous ses ennemis tout à l’entour; car son nom sera Salomon. Et en ses jours je donnerai paix et tranquillité à Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Lui, bâtira une maison à mon nom; et il me sera pour fils, et moi je lui serai pour père; et j’affermirai le trône de son royaume sur Israël pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Maintenant, mon fils, que l’ Éternel soit avec toi, et te fasse prospérer; et tu bâtiras la maison de l’ Éternel, ton Dieu, selon ce qu’il a prononcé à ton sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Seulement, que l’ Éternel te donne de la sagesse et de l’intelligence, et qu’il t’établisse sur Israël, et pour garder la loi de l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Alors tu prospéreras, si tu prends garde à pratiquer les statuts et les ordonnances que l’ Éternel commanda à Moïse pour Israël. Fortifie-toi, et sois ferme; ne crains point, et ne t’effraie point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Et voici, dans mon affliction, j’ai préparé pour la maison de l’ Éternel de l’or, 100 000 talents, et de l’argent, 1 000 milliers de talents, et de l’airain et du fer, sans poids, car il est en abondance; et j’ai préparé du bois et des pierres; et tu y ajouteras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Et tu as avec toi beaucoup d’ouvriers, des tailleurs de pierres, des maçons, et des charpentiers, et toute espèce d’hommes experts en tout ouvrage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'l’or, l’argent, et l’airain, et le fer, sont sans nombre: lève-toi, et agis, et l’ Éternel sera avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Et David commanda à tous les chefs d’Israël d’aider Salomon, son fils, [disant]:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'L’ Éternel, votre Dieu, n’est-il pas avec vous, et ne vous a-t-il pas donné du repos tout à l’entour? Car il a livré en ma main les habitants du pays, et le pays est soumis devant l’ Éternel et devant son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Maintenant, appliquez vos cœurs et vos âmes à rechercher l’ Éternel, votre Dieu; et levez-vous, et bâtissez le sanctuaire de l’ Éternel Dieu, pour amener l’arche de l’alliance de l’ Éternel et les ustensiles du sanctuaire de Dieu dans la maison qui sera bâtie pour le nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, '*Et David était vieux et rassasié de jours, et il établit Salomon, son fils, roi sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Et il assembla tous les chefs d’Israël, et les sacrificateurs, et les Lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Et on dénombra les Lévites, depuis l’âge de 30 ans et au-dessus; et leur nombre, par tête, par homme, fut de 38 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Il y en eut d’entre eux 24 000 pour diriger l’œuvre de la maison de l’ Éternel, et 6 000 intendants et juges,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'et 4 000 portiers, et 4 000 qui louaient l’ Éternel avec les instruments, que j’ai faits, [dit David,] pour louer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Et David les distribua en classes d’après les fils de Lévi, Guershon, Kehath, et Merari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Des Guershonites: Lahdan et Shimhi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Les fils de Lahdan: Jekhiel, le premier, et Zétham, et Joël, trois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Les fils de Shimhi: Shelomith, et Haziel, et Haran, trois. Ce sont les chefs des pères de Lahdan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Et les fils de Shimhi: Jakhath, Ziza, et Jehush, et Beriha: ce sont les quatre fils de Shimhi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Et Jakhath était le chef, et Ziza, le second. Mais Jehush et Beriha n’eurent pas beaucoup de fils; et, par maison de père, ils furent comptés pour une seule classe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Les fils de Kehath: Amram, Jitsehar, Hébron, et Uziel, quatre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Les fils d’Amram: Aaron et Moïse; et Aaron fut séparé pour qu’il soit sanctifié comme très saint, lui et ses fils, à toujours, pour faire fumer [ce qui se brûle] devant l’ Éternel, pour faire son service, et pour bénir en son nom, à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, '– Et quant à Moïse, homme de Dieu, ses fils furent attribués à la tribu de Lévi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Fils de Moïse: Guershom et Éliézer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Fils de Guershom: Shebuel, le chef.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Et les fils d’Éliézer étaient: Rekhabia, le chef; et Éliézer n’eut pas d’autres fils; mais les fils de Rekhabia furent très nombreux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, '– Fils de Jitsehar: Shelomith, le chef.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Fils de Hébron: Jerija, le chef; Amaria, le second; Jakhaziel, le troisième; et Jekamham, le quatrième.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Fils d’Uziel: Michée, le chef, et Jishija, le second.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Les fils de Merari: Makhli et Mushi. Fils de Makhli: Éléazar et Kis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Et Éléazar mourut, et n’eut point de fils, mais des filles; et les fils de Kis, leurs frères, les prirent [pour femmes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Fils de Mushi: Makhli, et Éder, et Jerémoth, trois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Ce sont là les fils de Lévi, selon leurs maisons de pères, les chefs des pères, selon qu’ils furent recensés, en comptant les noms par tête; ils faisaient l’œuvre du service de la maison de l’ Éternel, depuis l’âge de 20 ans, et au-dessus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'car David dit: L’ Éternel, le Dieu d’Israël, a donné du repos à son peuple, et il demeurera à Jérusalem pour toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'et les Lévites aussi n’auront plus à porter le tabernacle, ni tous les ustensiles pour son service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Car c’est selon les dernières paroles de David que se fit le dénombrement des fils de Lévi, depuis l’âge de 20 ans et au-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Car leur place était à côté des fils d’Aaron pour le service de la maison de l’ Éternel, [pour veiller] sur les parvis et les chambres, et sur la purification de toutes les choses saintes, et sur l’œuvre du service de la maison de Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'pour les pains à placer en rangées, et la fleur de farine pour le gâteau et les galettes sans levain, et [ce qui se cuit sur] la plaque, et ce qui est mêlé [avec de l’huile], et toutes les mesures de capacité et de longueur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'et pour se tenir là chaque matin, afin de célébrer et de louer l’ Éternel, et de même chaque soir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'et [pour être de service] pour tous les holocaustes qu’on offrait à l’ Éternel, aux sabbats, aux nouvelles lunes, et aux jours solennels, en nombre, conformément à l’ordonnance à leur égard, continuellement, devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Et ils vaquaient à leur charge à l’égard de la tente d’assignation, et à leur charge à l’égard du lieu saint, et à leur charge à l’égard des fils d’Aaron, leurs frères, pour le service de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Et quant aux fils d’Aaron, [voici] leurs classes: Fils d’Aaron: Nadab et Abihu, Éléazar et Ithamar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Et Nadab et Abihu moururent avant leur père, et n’eurent point de fils. Et Éléazar et Ithamar exercèrent la sacrificature.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Et Tsadok, des fils d’Éléazar, et Akhimélec, des fils d’Ithamar, David les distribua en classes, selon leur office dans leur service:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'et des fils d’Éléazar on trouva un plus grand nombre de chefs de famille que des fils d’Ithamar, et on les distribua en classes: des fils d’Éléazar, 16 chefs de maisons de pères; et des fils d’Ithamar, huit, selon leurs maisons de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Et on les distribua en classes par le sort, les uns avec les autres; car les chefs du lieu saint et les chefs de Dieu furent d’entre les fils d’Éléazar et parmi les fils d’Ithamar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Et Shemahia, fils de Nethaneël, le scribe, d’entre les Lévites, les inscrivit en la présence du roi, et des chefs, et de Tsadok, le sacrificateur, et d’Akhimélec, fils d’Abiathar, et des chefs des pères des sacrificateurs et des Lévites: une maison de père était tirée pour Éléazar, et une était tirée pour Ithamar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Et le premier sort échut à Jehoïarib; le second, à Jedahia;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'le troisième, à Harim; le quatrième, à Seorim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'le cinquième, à Malkija; le sixième, à Mijamin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'le septième, à Kots; le huitième, à Abija;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'le neuvième, à Jéshua; le dixième, à Shecania;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'le onzième, à Éliashib; le douzième, à Jakim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'le treizième, à Huppa; le quatorzième, à Jéshébeab;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'le quinzième, à Bilga; le seizième, à Immer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'le dix-septième, à Hézir; le dix-huitième, à Pitsets;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'le dix-neuvième, à Pethakhia; le vingtième, à Ézéchiel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'le vingt et unième, à Jakin; le vingt-deuxième, à Gamul;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'le vingt-troisième, à Delaïa; le vingt-quatrième, à Maazia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Ce fut là leur distribution, pour leur service, pour entrer dans la maison de l’ Éternel selon leur ordonnance [donnée] par Aaron, leur père, comme l’ Éternel, le Dieu d’Israël, le lui avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Et quant au reste des fils de Lévi, [les voici]: Des fils d’Amram, Shubaël; des fils de Shubaël, Jekhdia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'De Rekhabia: des fils de Rekhabia, Jishija était le chef.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Des Jitseharites, Shelomoth; des fils de Shelomoth, Jakhath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Et les fils de [Hébron]: Jerija; Amaria, le second; Jakhaziel, le troisième; Jekamham, le quatrième.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Les fils d’Uziel, Michée; des fils de Michée, Shamir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'le frère de Michée était Jishija; des fils de Jishija, Zacharie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Les fils de Merari, Makhli et Mushi; les fils de Jaazija, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'les fils de Merari, de Jaazija, son fils: Shoham, et Zaccur, et Ibri;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'de Makhli, Éléazar, et il n’eut point de fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'de Kis, les fils de Kis, Jerakhmeël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'et les fils de Mushi: Makhli, et Éder, et Jerimoth. Ce sont là les fils des Lévites, selon leurs maisons de pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Et eux aussi, comme leurs frères, les fils d’Aaron, tirèrent au sort devant le roi David, et Tsadok, et Akhimélec, et les chefs des pères des sacrificateurs et des Lévites, les chefs des pères comme le plus petit d’entre leurs frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Et David et les chefs de l’armée mirent à part pour le service, d’entre les fils d’Asaph et d’Héman et de Jeduthun, ceux qui devaient prophétiser avec des harpes, et des luths, et des cymbales; et le nombre des hommes employés au service était:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Des fils d’Asaph: Zaccur, et Joseph, et Nethania, et Ashareéla, fils d’Asaph, sous la direction d’Asaph, qui prophétisait sous la direction du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'De Jeduthun, les fils de Jeduthun: Guedalia, et Tseri, et Ésaïe, Hashabia, et Matthithia, [et Shimhi], six, sous la direction de leur père Jeduthun, qui prophétisait avec la harpe, pour célébrer et louer l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'D’Héman, les fils d’Héman: Bukkija, Matthania, Uziel, Shebuel, et Jerimoth, Hanania, Hanani, Éliatha, Guiddalthi, et Romamthi-Ézer, Joshbekasha, Mallothi, Hothir, Makhazioth:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'tous ceux-là étaient fils d’Héman, le voyant du roi dans les paroles de Dieu, pour exalter sa puissance; et Dieu donna à Héman 14 fils et trois filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, '– Tous ceux-là étaient sous la direction de leurs pères, d’Asaph, et de Jeduthun, et d’Héman, dans le chant de la maison de l’ Éternel, avec des cymbales, des luths, et des harpes, pour le service de la maison de Dieu, sous la direction du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Et leur nombre, avec leurs frères instruits dans l’art de chanter à l’ Éternel, tous les hommes experts, était de 288.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Et ils jetèrent les sorts pour leurs charges, le petit comme le grand, l’homme expert avec le disciple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Et le premier sort échut, pour Asaph, à Joseph; à Guedalia, le second; lui et ses frères et ses fils étaient douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Le troisième, à Zaccur, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Le quatrième, à Jitseri, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Le cinquième, à Nethania, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Le sixième, à Bukkija, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Le septième, à Jeshareéla, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Le huitième, à Ésaïe, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Le neuvième, à Matthania, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Le dixième, à Shimhi, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Le onzième, à Azareël, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Le douzième, à Hashabia, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Le treizième, à Shubaël, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Le quatorzième, à Matthithia, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Le quinzième, à Jerémoth, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Le seizième, à Hanania, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Le dix-septième, à Joshbekasha, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Le dix-huitième, à Hanani, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Le dix-neuvième, à Mallothi, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Le vingtième, à Élijatha, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Le vingt et unième, à Hothir, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Le vingt-deuxième, à Guiddalthi, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Le vingt-troisième, à Makhazioth, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Le vingt-quatrième, à Romamthi-Ézer, ses fils et ses frères, douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Les classes des portiers. Des Corites: Meshélémia, fils de Koré, des fils d’Asaph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Et Meshélémia avait des fils: Zacharie, le premier-né; Jediaël, le second; Zebadia, le troisième; Jathniel, le quatrième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Élam, le cinquième; Jokhanan, le sixième; Élioénaï, le septième.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, '– Et les fils d’Obed-Édom: Shemahia, le premier-né; Jozabad, le second; Joakh, le troisième; et Sacar, le quatrième; et Nethaneël, le cinquième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Ammiel, le sixième; Issacar, le septième; Peülthaï, le huitième, car Dieu l’avait béni.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, '– Et à Shemahia, son fils, naquirent des fils qui gouvernèrent dans la maison de leur père, car ils étaient hommes forts et vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Les fils de Shemahia: Othni, et Rephaël, et Obed, Elzabad, [et] ses frères, hommes vaillants, Élihu et Semakia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Tous ceux-là étaient des fils d’Obed-Édom; eux, et leurs fils, et leurs frères, hommes vaillants et forts pour le service, 62, d’Obed-Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, '– Et Meshélémia avait des fils et des frères, hommes vaillants, 18.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, '– Et Hosa, d’entre les fils de Merari, avait des fils: Shimri, le chef; bien qu’il ne soit pas le premier-né, son père l’établit pour chef;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Hilkija, le second; Tebalia, le troisième; Zacharie, le quatrième: tous les fils et les frères de Hosa étaient 13.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'À ceux-là furent les départements des portiers, aux chefs des hommes [qui vaquaient] à leurs charges avec leurs frères, pour faire le service dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Et ils jetèrent les sorts, le petit comme le grand, selon leurs maisons de pères, pour chaque porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Et le sort qui échut à Shélémia fut le levant; et on jeta le sort pour Zacharie, son fils, sage conseiller, et le sort qui lui échut fut le nord;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'à Obed-Édom [échut] le midi; et à ses fils, la maison des approvisionnements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'à Shuppim et à Hosa, le couchant, avec la porte de Shalléketh, au chemin qui monte, une garde vis-à-vis de l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Au levant, il y avait six Lévites; au nord, quatre par jour; au midi, quatre par jour; et aux approvisionnements, deux [et] deux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'à Parbar, vers le couchant, quatre au chemin, deux à Parbar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, '– Ce sont là les départements des portiers, d’entre les fils des Corites et d’entre les fils de Merari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Et les Lévites: Akhija était [préposé] sur les trésors de la maison de Dieu et sur les trésors des choses saintes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Les fils de Lahdan, les fils des Guershonites de Lahdan, les chefs des pères de Lahdan, le Guershonite: Jekhiéli;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'les fils de Jekhiéli: Zétham et Joël, son frère, [préposés] sur les trésors de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Des Amramites, des Jitseharites, des Hébronites, des Uziélites...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Et Shebuel, fils de Guershom, fils de Moïse, était surintendant des trésors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Et ses frères, d’Éliézer: Rekhabia, son fils, et Ésaïe, son fils, et Joram, son fils, et Zicri, son fils, et Shelomith, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ce Shelomith et ses frères furent [préposés] sur tous les trésors des choses saintes que le roi David, et les chefs des pères, les chefs de milliers et de centaines, et les chefs de l’armée, avaient consacrées,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'qu’ils avaient consacrées, des guerres et du butin, pour l’entretien de la maison de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'et tout ce qu’avaient consacré Samuel, le voyant, et Saül, fils de Kis, et Abner, fils de Ner, et Joab, fils de Tseruïa: tout ce qui était consacré était [mis] sous la main de Shelomith et de ses frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'D’entre les Jitseharites, Kenania et ses fils étaient [établis] sur Israël pour les affaires extérieures, comme intendants et juges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'D’entre les Hébronites, Hashabia et ses frères, hommes vaillants, [au nombre de] 1 700, pour l’administration d’Israël, en deçà du Jourdain, vers le couchant, pour toutes les affaires de l’ Éternel et pour le service du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'D’entre les Hébronites, Jerija fut le chef; (on rechercha les Hébronites, selon leurs générations, selon les pères, en la quarantième année du règne de David, et on trouva parmi eux, à Jahzer de Galaad, des hommes forts et vaillants;)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'et ses frères, hommes vaillants, étaient 2 700, des chefs des pères; et le roi David les établit sur les Rubénites et sur les Gadites et sur la demi-tribu des Manassites, pour toutes les affaires de Dieu et pour les affaires du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Et [ce sont ici] les fils d’Israël, selon leur nombre, les chefs des pères, et les chefs de milliers et de centaines, et leurs intendants, qui servaient le roi dans toutes les affaires de leurs divisions, entrant et sortant, mois par mois, pendant tous les mois de l’année: chaque division de 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Sur la première division, pour le premier mois, était Jashobham, fils de Zabdiel, et dans sa division il y avait 24 000 [hommes];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'il était des fils de Pérets, [et] chef de tous les capitaines des corps d’armée du premier mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Et sur la division du second mois était Dodaï, l’Akhokhite; et Mikloth était surintendant dans sa division; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Le chef du troisième corps d’armée, pour le troisième mois, était Benaïa (fils de Jehoïada, principal officier), chef; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Ce Benaïa était fort, entre les trente, et au-dessus des trente; et Ammizabad, son fils, était dans sa division.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Le quatrième, pour le quatrième mois, était Asçaël, frère de Joab; et Zebadia, son fils, après lui; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Le cinquième, pour le cinquième mois, était le chef Shamhuth, le Jizrakhite; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Le sixième, pour le sixième mois, était Ira, fils d’Ikkesh, le Thekohite; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Le septième, pour le septième mois, était Hélets, le Pelonite, des fils d’Éphraïm; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Le huitième, pour le huitième mois, était Sibbecaï, le Hushathite, des Zarkhites; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Le neuvième, pour le neuvième mois, était Abiézer, l’Anathothite, des Benjaminites; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Le dixième, pour le dixième mois, était Maharaï, le Netophathite, des Zarkhites; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Le onzième, pour le onzième mois, était Benaïa, le Pirhathonite, des fils d’Éphraïm; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Le douzième, pour le douzième mois, était Heldaï, le Netophathite, d’Othniel; et dans sa division il y avait 24 000 [hommes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Et sur les tribus d’Israël: pour les Rubénites, Éliézer, fils de Zicri, était prince; pour les Siméonites, Shephatia, fils de Maaca;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'pour les Lévites, Hashabia, fils de Kemuel; pour Aaron, Tsadok;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'pour Juda, Élihu, des frères de David; pour Issacar, Omri, fils de Micaël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'pour Zabulon, Jishmahia, fils d’Abdias; pour Nephthali, Jerimoth, fils d’Azriel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'pour les fils d’Éphraïm, Osée, fils d’Azazia; pour la demi-tribu de Manassé, Joël, fils de Pedaïa;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'pour la demi-tribu de Manassé, en Galaad, Jiddo, fils de Zacharie; pour Benjamin, Jaasciel, fils d’Abner;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'pour Dan, Azareël, fils de Jerokham. Ce sont là les chefs des tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Et David ne releva pas leur nombre, depuis l’âge de 20 ans et au-dessous, parce que l’ Éternel avait dit qu’il multiplierait Israël comme les étoiles des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab, fils de Tseruïa, commença à dénombrer, mais il n’acheva pas; et à cause de cela il y eut de la colère contre Israël, et le dénombrement n’entra pas dans les dénombrements des chroniques du roi David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Et Azmaveth, fils d’Adiel, était [préposé] sur les trésors du roi; et Jonathan, fils d’Ozias, était [préposé] sur les trésors qui étaient à la campagne, dans les villes, et dans les villages, et dans les tours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Et Ezri, fils de Kelub, était [préposé] sur ceux qui étaient occupés au travail des champs pour le labourage de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'et Shimhi, le Ramathite, sur les vignes; et Zabdi, le Shiphmite, sur ce qui était dans les vignes en trésors de vin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'et Baal-Hanan, le Guedérite, sur les oliviers et sur les sycomores qui étaient dans le pays plat; et Joash, sur les trésors d’huile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'et Shitraï, le Saronite, sur le gros bétail qui paissait en Saron; et Shaphath, fils d’Adlaï, sur le gros bétail qui était dans les vallées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'et Obil, l’Ismaélite, sur les chameaux; et Jekhdia, le Méronothite, sur les ânesses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'et Jaziz, l’Hagarénien, sur le menu bétail. Tous ceux-là étaient intendants des biens qui appartenaient au roi David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Et Jonathan, oncle de David, était conseiller, homme intelligent et un scribe; et Jekhiel, fils de Hacmoni, était avec les fils du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Et Akhitophel était conseiller du roi; et Hushaï, l’Arkite, était l’ami du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Et après Akhitophel était Jehoïada, fils de Benaïa, et Abiathar. Et Joab était le chef de l’armée du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, '*Et David réunit à Jérusalem tous les chefs d’Israël, les chefs des tribus, et les chefs des divisions qui servaient le roi, et les chefs de milliers, et les chefs de centaines, et les chefs de tous les biens et de toutes les possessions du roi et de ses fils, avec les eunuques, et les hommes forts, et tout homme fort et vaillant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Et le roi David se leva sur ses pieds, et dit: Écoutez-moi, mes frères et mon peuple! J’avais dans le cœur de bâtir une maison de repos pour l’arche de l’alliance de l’ Éternel, et pour le marchepied des pieds de notre Dieu; et j’ai fait des préparatifs pour bâtir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Mais Dieu me dit: Tu ne bâtiras pas une maison à mon nom, car tu es un homme de guerre et tu as versé le sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Et l’ Éternel, le Dieu d’Israël, m’a choisi de toute la maison de mon père, pour être roi sur Israël à toujours (car il a choisi Juda pour prince, et de la maison de Juda, la maison de mon père; et parmi les fils de mon père, il a pris plaisir en moi, pour me faire roi sur tout Israël);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'et d’entre tous mes fils (car l’ Éternel m’a donné beaucoup de fils), il a choisi Salomon, mon fils, pour s’asseoir sur le trône du royaume de l’ Éternel sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Et il m’a dit: Salomon, ton fils, c’est lui qui bâtira ma maison et mes parvis, car je me le suis choisi pour fils, et moi je lui serai pour père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'et j’affermirai son royaume à toujours, s’il est ferme pour pratiquer mes commandements et mes ordonnances, comme aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, '– Et maintenant, devant les yeux de tout Israël, qui est la congrégation de l’ Éternel, et aux oreilles de notre Dieu: – Gardez et recherchez tous les commandements de l’ Éternel, votre Dieu, afin que vous possédiez ce bon pays, et que vous le fassiez hériter à vos fils après vous, à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Et toi, Salomon, mon fils, connais le Dieu de ton père, et sers-le avec un cœur parfait et avec une âme qui y prenne plaisir; car l’ Éternel sonde tous les cœurs et discerne toutes les imaginations des pensées. Si tu le cherches, il se fera trouver de toi; mais si tu l’abandonnes, il te rejettera pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Vois maintenant, que l’ Éternel t’a choisi pour bâtir une maison qui soit [son] sanctuaire. Fortifie-toi, et agis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Et David donna à Salomon, son fils, le modèle du portique, et de ses maisons, et de ses trésoreries, et de ses chambres hautes, et de ses chambres intérieures, et de la maison du propitiatoire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'et le modèle de tout ce qu’il avait, par l’Esprit, touchant les parvis de la maison de l’ Éternel, et toutes les chambres, tout autour, pour les trésors de la maison de Dieu, et pour les trésors des choses saintes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'et pour les classes des sacrificateurs et des lévites, et pour toute l’œuvre du service de la maison de l’ Éternel, et pour tous les ustensiles du service de la maison de l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, '– de l’or au poids, pour les [objets] d’or, pour tous les ustensiles de chaque service; [et de l’argent] au poids, pour tous les ustensiles d’argent, pour tous les ustensiles de chaque service;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'et le poids des chandeliers d’or, et de leurs lampes d’or, selon le poids de chaque chandelier et de ses lampes; et [le poids] des chandeliers d’argent, selon le poids de [chaque] chandelier et de ses lampes, selon le service de chaque chandelier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'et de l’or au poids, pour les tables des [pains] à placer en rangées, pour chaque table; et de l’argent, pour les tables d’argent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'et de l’or pur, pour les fourchettes, pour les bassins, pour les gobelets, et pour les coupes d’or, au poids, pour chaque coupe; et [de l’argent], pour les coupes d’argent, au poids, pour chaque coupe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'et pour l’autel de l’encens, de l’or épuré, au poids; et le modèle du char des chérubins d’or, qui étendent [leurs ailes] et couvrent l’arche de l’alliance de l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, '– tout cela, [dit David], toute l’œuvre du modèle, il m’en a, par écrit, donné l’intelligence, par la main de l’ Éternel sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Et David dit à Salomon, son fils: Fortifie-toi, et sois ferme, et agis; ne crains point, et ne t’effraie point; car l’ Éternel Dieu, mon Dieu, sera avec toi: il ne te laissera point et ne t’abandonnera point, jusqu’à ce que soit achevé tout l’ouvrage du service de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Et voici les classes des sacrificateurs et des lévites, pour tout le service de la maison de Dieu; et il y a avec toi, pour toute œuvre, tous les hommes de bonne volonté, habiles pour tout service; et les chefs et tout le peuple sont à tous tes ordres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Et le roi David dit à toute la congrégation: Salomon, mon fils, le seul que Dieu ait choisi, est jeune et délicat, et l’ouvrage est grand, car ce palais n’est point pour un homme, mais pour l’ Éternel Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Et moi, de toute ma force, j’ai préparé, pour la maison de mon Dieu, de l’or pour [ce qui doit être] d’or, et de l’argent pour [ce qui doit être] d’argent, et de l’airain pour [ce qui doit être] d’airain, du fer pour [ce qui doit être] de fer, et du bois pour [ce qui doit être] de bois, des pierres d’onyx et [des pierres] à enchâsser, des pierres brillantes et [des pierres] de diverses couleurs, et toutes sortes de pierres précieuses, et du marbre blanc en abondance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Et de plus, dans mon affection pour la maison de mon Dieu, je donne pour la maison de mon Dieu, de ce que j’ai d’or et d’argent m’appartenant en propre, – outre tout ce que j’ai préparé pour la maison du sanctuaire');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, '– 3 000 talents d’or, d’or d’Ophir, et 7 000 talents d’argent épuré, pour revêtir les murs des maisons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'de l’or, pour [les choses] d’or, et de l’argent, pour [les choses] d’argent, et pour tout l’ouvrage [qui se fait] par main d’ouvrier. Et qui sera de franche volonté pour offrir aujourd’hui à l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Et les chefs des pères, et les chefs des tribus d’Israël, et les chefs des milliers et des centaines, et les chefs des affaires du roi, offrirent volontairement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'et donnèrent, pour le service de la maison de Dieu, 5 000 talents d’or, et 10 000 dariques, et 10 000 talents d’argent, et 18 000 talents d’airain, et 100 000 talents de fer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Et ceux chez qui se trouvaient des pierres [précieuses] les donnèrent au trésor de la maison de l’ Éternel, entre les mains de Jekhiel, le Guershonite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Et le peuple se réjouit de ce qu’ils avaient offert volontairement, car ils offraient volontairement, d’un cœur parfait, à l’ Éternel; et aussi le roi David en eut une grande joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Et David bénit l’ Éternel aux yeux de toute la congrégation, et David dit: Béni sois-tu, Éternel, Dieu d’Israël notre père, de tout temps et à toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'À toi, Éternel, est la grandeur, et la force, et la gloire, et la splendeur, et la majesté; car tout, dans les cieux et sur la terre, [est à toi]. À toi, Éternel, est le royaume et l’élévation, comme Chef sur toutes choses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'et les richesses et la gloire viennent de toi, et tu domines sur toutes choses; et la puissance et la force sont en ta main, et il est en ta main d’agrandir et d’affermir toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Et maintenant, ô notre Dieu, nous te célébrons, et nous louons ton nom glorieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Et qui suis-je, et qui est mon peuple, que nous ayons le pouvoir d’offrir ainsi volontairement? car tout vient de toi; et ce qui vient de ta main, nous te le donnons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Car nous sommes étrangers devant toi, et des hôtes, comme tous nos pères; nos jours sont comme l’ombre, sur la terre, et il n’y a pas d’espérance [de demeurer ici-bas].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Éternel, notre Dieu, toute cette abondance que nous avons préparée afin de te bâtir une maison pour ton saint nom, est de ta main, et tout est à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Et je sais, ô mon Dieu, que tu sondes le cœur, et que tu prends plaisir à la droiture: moi, dans la droiture de mon cœur, j’ai offert volontairement toutes ces choses; et maintenant, j’ai vu avec joie que ton peuple qui se trouve ici t’a offert volontairement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Éternel, Dieu d’Abraham, d’Isaac, et d’Israël, nos pères, garde ceci à toujours dans l’imagination des pensées du cœur de ton peuple, et dirige leurs cœurs vers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Et donne à mon fils Salomon un cœur parfait, pour garder tes commandements, tes témoignages et tes statuts, et pour tout faire, et pour bâtir le palais que j’ai préparé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Et David dit à toute la congrégation: Bénissez l’ Éternel, votre Dieu. Et toute la congrégation bénit l’ Éternel, le Dieu de leurs pères; et ils s’inclinèrent, et se prosternèrent devant l’ Éternel et devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Et, le lendemain de ce jour, ils sacrifièrent des sacrifices à l’ Éternel, et offrirent des holocaustes à l’ Éternel: 1 000 taureaux, 1 000 béliers, 1 000 agneaux, et leurs libations; et des sacrifices en abondance pour tout Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Et ils mangèrent et burent devant l’ Éternel ce jour-là, avec une grande joie; et pour la seconde fois ils établirent roi Salomon, fils de David, et l’oignirent pour l’ Éternel comme prince, et Tsadok comme sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Et Salomon s’assit sur le trône de l’ Éternel, comme roi à la place de David, son père, et il prospéra; et tout Israël lui obéit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Et tous les chefs et les hommes forts, et aussi tous les fils du roi David, se soumirent au roi Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Et l’ Éternel agrandit Salomon à un très haut degré aux yeux de tout Israël, et lui donna une majesté royale telle qu’aucun roi avant lui n’en avait eu en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, '*Et David, fils d’Isaï, régna sur tout Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Et les jours qu’il régna sur Israël furent 40 ans: à Hébron, il régna sept ans; et, à Jérusalem, il régna 33 [ans].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Et il mourut en bonne vieillesse, rassasié de jours, de richesses, et de gloire; et Salomon, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Et les actes du roi David, les premiers et les derniers, voici, ils sont écrits dans le livre de Samuel, le voyant, et dans le livre de Nathan, le prophète, et dans le livre de Gad, le voyant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'avec tout son règne et sa puissance, et les temps qui passèrent sur lui, et sur Israël, et sur tous les royaumes des pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Et Salomon, fils de David, s’affermit dans son royaume; et l’ Éternel, son Dieu, fut avec lui et l’agrandit extrêmement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Et Salomon parla à tout Israël, aux chefs de milliers et de centaines, et aux juges, et à tous les princes de tout Israël, chefs des pères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'et Salomon, et toute la congrégation avec lui, allèrent au haut lieu qui était à Gabaon; car là était la tente d’assignation de Dieu, que Moïse, serviteur de l’ Éternel, avait faite dans le désert');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, '(mais David avait fait monter l’arche de Dieu de Kiriath-Jéarim au [lieu] que David lui avait préparé; car il lui avait tendu une tente à Jérusalem);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'et l’autel d’airain qu’avait fait Betsaleël, fils d’Uri, fils de Hur, était là, devant le tabernacle de l’ Éternel; et Salomon et la congrégation la recherchèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Et Salomon offrit là, devant l’ Éternel, sur l’autel d’airain qui était devant la tente d’assignation; il offrit 1 000 holocaustes sur cet [autel].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Cette même nuit Dieu apparut à Salomon, et lui dit: Demande ce que tu veux que je te donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Et Salomon dit à Dieu: Tu as usé d’une grande bonté envers David, mon père, et tu m’as fait roi à sa place:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'maintenant, Éternel Dieu, que ta parole à David, mon père, soit ferme; car tu m’as établi roi sur un peuple nombreux comme la poussière de la terre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'maintenant, donne-moi de la sagesse et de la connaissance, et je sortirai et j’entrerai devant ce peuple; car qui jugera ton peuple qui est si grand?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Et Dieu dit à Salomon: Parce que c’est cela qui était dans ton cœur, et que tu n’as pas demandé des richesses, des biens, et de la gloire, ni la vie de ceux qui te haïssent, et que tu n’as pas non plus demandé de longs jours, mais que tu as demandé pour toi de la sagesse et de la connaissance afin de pouvoir juger mon peuple sur lequel je t’ai établi roi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'la sagesse et la connaissance te sont données; et je te donnerai des richesses, et des biens, et de la gloire, comme n’en ont pas eu les rois qui ont été avant toi, et comme après toi aucun n’en aura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Et Salomon revint à Jérusalem, du haut lieu qui était à Gabaon, de devant la tente d’assignation, et il régna sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Et Salomon rassembla des chars et des cavaliers; et il eut 1 400 chars et 12 000 cavaliers; et il les plaça dans les villes à chars, et auprès du roi à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Et le roi fit que l’argent et l’or, dans Jérusalem, étaient comme les pierres, et il fit que les cèdres étaient, en quantité, comme les sycomores qui sont dans le pays plat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Et quant aux chevaux de Salomon, il les tirait d’Égypte: une caravane de marchands du roi prenait un convoi [de chevaux] pour un certain prix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'et on faisait monter et sortir d’Égypte un char pour 600 [sicles] d’argent, et un cheval pour 150; et on en faisait venir ainsi, par leur main, pour tous les rois des Héthiens et pour les rois de Syrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 18, '*Et Salomon résolut de bâtir une maison pour le nom de l’ Éternel, et une maison pour son royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Et Salomon dénombra 70 000 portefaix, et 80 000 hommes qui taillaient [la pierre] sur la montagne, et 3 600 surveillants [préposés] sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Et Salomon envoya vers Hiram, roi de Tyr, disant: [Fais pour moi] comme tu as fait pour David, mon père, à qui tu as envoyé des cèdres pour se bâtir une maison afin d’y habiter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Voici, je bâtis une maison pour le nom de l’ Éternel, mon Dieu, pour la lui consacrer, pour faire fumer devant lui l’encens de drogues odoriférantes, et pour l’arrangement continuel [des pains], et pour les holocaustes du matin et du soir, des sabbats, et des nouvelles lunes, et des jours solennels de l’ Éternel, notre Dieu; cela est [prescrit] à Israël à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Et la maison que je bâtis sera grande; car notre Dieu est grand au-dessus de tous les dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Et qui a le pouvoir de lui bâtir une maison, car les cieux, et les cieux des cieux, ne peuvent le contenir? Et qui suis-je, moi, pour lui bâtir une maison, si ce n’est pour faire fumer [ce qui se brûle] devant lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Et maintenant, envoie-moi un homme habile à travailler en or, et en argent, et en airain, et en fer, et en pourpre, et en cramoisi, et en bleu, et qui sache graver, avec les hommes habiles qui sont auprès de moi en Juda et à Jérusalem [et] que David, mon père, a préparés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Et envoie-moi du Liban des bois de cèdres, de cyprès, et d’algummim; car je sais que tes serviteurs s’entendent à couper le bois dans le Liban; et voici, mes serviteurs seront avec tes serviteurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'pour me préparer du bois en abondance; car la maison que je bâtis sera grande et merveilleuse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Et voici, je donnerai à tes serviteurs, les coupeurs, qui abattront les bois, 20 000 cors de froment battu, et 20 000 cors d’orge, et 20 000 baths de vin, et 20 000 baths d’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Et Hiram, roi de Tyr, dit dans un écrit qu’il envoya à Salomon: À cause de l’amour de l’ Éternel pour son peuple, il t’a établi roi sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Et Hiram dit: Béni soit l’ Éternel, le Dieu d’Israël, qui a fait les cieux et la terre, de ce qu’il a donné au roi David un fils sage, doué de sens et d’intelligence, qui bâtira une maison à l’ Éternel et une maison pour son royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Et maintenant je t’envoie un homme habile, doué d’intelligence, Huram-Abi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'fils d’une femme d’entre les filles de Dan, et dont le père est Tyrien, sachant travailler en or, et en argent, en airain, en fer, en pierres, et en bois, en pourpre, en bleu, et en byssus, et en cramoisi, et [sachant] faire toute sorte de gravure et inventer toute sorte de choses qu’on lui donnera à inventer, avec tes hommes habiles et les hommes habiles de mon seigneur David, ton père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Et maintenant, que mon seigneur envoie à ses serviteurs le froment et l’orge, l’huile et le vin qu’il a dit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'et nous, nous couperons des bois dans le Liban, autant que tu en auras besoin, et nous te les amènerons en radeaux sur la mer à Japho; et toi, tu les feras monter à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Et Salomon dénombra tous les hommes étrangers qui étaient dans le pays d’Israël, suivant le dénombrement qu’en avait fait David, son père, et on en trouva 153 600.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Et il en fit 70 000 portefaix, et 80 000 tailleurs de pierres sur la montagne, et 3 600 surveillants pour faire travailler le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, '*Et Salomon commença de bâtir la maison de l’ Éternel à Jérusalem, sur la montagne de Morija, où [l’ Éternel] était apparu à David, son père, sur l’emplacement que David avait préparé dans l’aire d’Ornan, le Jébusien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Et il commença de bâtir le second [jour] du second mois, en la quatrième année de son règne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Et c’est ici le fondement que Salomon posa pour bâtir la maison de Dieu: la longueur, en coudées, d’après l’ancienne mesure, était de 60 coudées, et la largeur, de 20 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Et le portique qui était devant avait 20 coudées de longueur, selon la largeur de la maison; et sa hauteur était de 120 [coudées]; et il le recouvrit à l’intérieur d’or pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Et la grande maison, il la revêtit de bois de cyprès; et il la revêtit d’or fin, et il y fit des palmiers et des chaînes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Et il recouvrit la maison de pierres précieuses, pour [son] ornement; et l’or était de l’or de Parvaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Et il revêtit d’or la maison, les solives, les seuils, et ses murs, et ses portes; et il entailla des chérubins sur les murs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Et il fit la maison du lieu très saint: sa longueur, selon la largeur de la maison, de 20 coudées, et sa largeur de 20 coudées; et il la revêtit d’or fin, se montant à 600 talents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Et le poids des clous se montait à 50 sicles d’or; et il revêtit d’or les chambres hautes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Et il fit dans la maison du lieu très saint deux chérubins, d’ouvrage de statuaire, et on les recouvrit d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Et les ailes des chérubins avaient 20 coudées de long; une aile de l’un, de cinq coudées, touchait le mur de la maison; et l’autre aile, de cinq coudées, touchait l’aile de l’autre chérubin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Et l’aile de l’autre chérubin, de cinq coudées, touchait le mur de la maison; et l’autre aile, de cinq coudées, joignait l’aile de l’autre chérubin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Les ailes de ces chérubins, déployées, [avaient] 20 coudées; et ils se tenaient debout sur leurs pieds, et leurs faces [regardaient] vers la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Et il fit le voile de bleu, et de pourpre, et de cramoisi, et de byssus, et mit dessus des chérubins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Et devant la maison il fit deux colonnes de 35 coudées de hauteur; et le chapiteau qui était sur leur sommet était de cinq coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Et il fit des chaînes [comme] dans l’oracle, et les mit sur le sommet des colonnes; et il fit 100 grenades, et les mit aux chaînes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Et il dressa les colonnes devant le temple, l’une à droite, l’autre à gauche; et il appela le nom de celle qui était à droite, Jakin; et le nom de celle qui était à gauche, Boaz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Et il fit un autel d’airain long de 20 coudées, et large de 20 coudées, et haut de dix coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Et il fit la mer de fonte, de dix coudées d’un bord à l’autre bord, ronde tout autour, et haute de cinq coudées; et un cordon de 30 coudées l’entourait tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Et au-dessous d’elle, l’environnant tout autour, il y avait une ressemblance de bœufs, dix par coudée, entourant la mer tout autour, deux rangs de bœufs, fondus d’une seule fonte avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Elle était posée sur douze bœufs, trois tournés vers le nord, et trois tournés vers l’occident, et trois tournés vers le midi, et trois tournés vers le levant; et la mer était sur eux, par-dessus; et toute leur partie postérieure était en dedans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Et son épaisseur était d’une paume, et son bord était comme le travail du bord d’une coupe, en fleurs de lis: en capacité, elle contenait 3 000 baths.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Et il fit dix cuves, et en plaça cinq à droite, et cinq à gauche, pour y laver: on y lavait ce qu’on préparait pour l’holocauste; et la mer était pour les sacrificateurs, pour s’y laver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Et il fit dix chandeliers d’or, selon l’ordonnance à leur égard: et il les plaça dans le temple, cinq à droite, et cinq à gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Et il fit dix tables, et les plaça dans le temple, cinq à droite, et cinq à gauche. Et il fit 100 bassins d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Et il fit le parvis des sacrificateurs, et la grande cour, et les portes de la cour, et il recouvrit d’airain leurs battants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Et il mit la mer au côté droit, à l’orient, vers le midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Et Huram fit les vases [à cendre], et les pelles, et les bassins. Et Huram acheva de faire l’ouvrage qu’il fit pour le roi Salomon dans la maison de Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'deux colonnes, et les globes, et les deux chapiteaux [qui étaient] sur le sommet des colonnes; et les deux réseaux pour couvrir les deux globes des chapiteaux qui étaient sur le sommet des colonnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'et les 400 grenades pour les deux réseaux, deux rangs de grenades à un réseau, pour couvrir les deux globes des chapiteaux qui étaient sur le sommet des colonnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Et il fit les bases, et fit les cuves sur les bases;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'la mer unique, et les douze bœufs sous elle:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'et les vases [à cendre], et les pelles, et les fourchettes, et tous leurs ustensiles, Huram-Abiv les fit d’airain poli, pour le roi Salomon, pour la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Le roi les fit fondre dans la plaine du Jourdain, dans l’épaisseur du sol, entre Succoth et Tserédatha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Et Salomon fit tous ces objets en grand nombre, car on ne rechercha pas le poids de l’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Et Salomon fit tous les objets qui étaient dans la maison de Dieu: l’autel d’or; et les tables sur lesquelles [on mettait] le pain de proposition;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'et les chandeliers, et leurs lampes d’or pur, pour brûler devant l’oracle, selon l’ordonnance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'et les fleurs, et les lampes, et les pincettes, d’or, (c’était de l’or parfait);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'et les couteaux, et les bassins, et les coupes, et les brasiers, d’or pur; et l’entrée de la maison, ses portes intérieures pour le lieu très saint, et les portes de la maison, pour le temple, étaient [aussi] d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Et tout l’ouvrage que Salomon fit pour la maison de l’ Éternel fut achevé. Et Salomon apporta les choses saintes de David, son père, tant l’argent que l’or, et tous les ustensiles: il les mit dans les trésors de la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, '*Alors Salomon assembla à Jérusalem les anciens d’Israël et tous les chefs des tribus, les princes des pères des fils d’Israël, pour faire monter l’arche de l’alliance de l’ Éternel, de la ville de David, qui est Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Et tous les hommes d’Israël s’assemblèrent vers le roi, à la fête, celle du septième mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Et tous les anciens d’Israël vinrent, et les Lévites portèrent l’arche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Et ils firent monter l’arche, et la tente d’assignation, et tous les ustensiles du lieu saint qui étaient dans la tente: les sacrificateurs, les Lévites, les firent monter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Et le roi Salomon et toute l’assemblée d’Israël qui s’était réunie auprès de lui devant l’arche, sacrifiaient du menu et du gros bétail, qu’on ne pouvait nombrer ni compter à cause de [sa] multitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Et les sacrificateurs firent entrer l’arche de l’alliance de l’ Éternel en son lieu, dans l’oracle de la maison, dans le lieu très saint, sous les ailes des chérubins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Et les chérubins étendaient les ailes sur le lieu de l’arche; et les chérubins couvraient l’arche et ses barres, par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Et les barres étaient longues, de sorte que les bouts des barres se voyaient hors de l’arche sur le devant de l’oracle, mais ils ne se voyaient pas du dehors; et elles sont là jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Il n’y avait rien dans l’arche, sauf les deux tables que Moïse y mit en Horeb, quand l’ Éternel fit alliance avec les fils d’Israël, lorsqu’ils sortirent d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Et il arriva, comme les sacrificateurs sortaient du lieu saint (car tous les sacrificateurs qui s’y trouvaient s’étaient sanctifiés sans observer les classes),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'et que les lévites, les chantres, eux tous, Asaph, et Héman, et Jeduthun, et leurs fils et leurs frères, vêtus de byssus, avec des cymbales et des luths et des harpes, se tenaient à l’orient de l’autel, et avec eux 120 sacrificateurs sonnant des trompettes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, '– il arriva, lorsque les trompettes et les chantres furent comme un seul homme pour faire entendre une même voix en louant et en célébrant l’ Éternel, et qu’ils élevèrent la voix avec des trompettes, et des cymbales, et des instruments de musique, en louant l’ Éternel de ce qu’il est bon, parce que sa bonté demeure à toujours, [il arriva] que la maison, la maison de l’ Éternel, fut remplie d’une nuée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'et les sacrificateurs ne pouvaient pas s’y tenir pour faire le service, à cause de la nuée, car la gloire de l’ Éternel remplissait la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Alors Salomon dit: L’ Éternel a dit qu’il habiterait dans l’obscurité profonde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Mais moi j’ai bâti une maison d’habitation pour toi, un lieu fixe pour que tu y demeures à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Et le roi tourna sa face, et bénit toute la congrégation d’Israël; et toute la congrégation d’Israël était debout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Et il dit: Béni soit l’ Éternel, le Dieu d’Israël, qui parla de sa bouche à David, mon père, et de sa main a accompli [sa parole], disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Depuis le jour où j’ai fait sortir mon peuple du pays d’Égypte, je n’ai choisi aucune ville d’entre toutes les tribus d’Israël pour [y] bâtir une maison afin que mon nom y soit, et je n’ai pas choisi d’homme pour être prince sur mon peuple Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'mais j’ai choisi Jérusalem, afin que mon nom y soit; et j’ai choisi David pour être [roi] sur mon peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Et David, mon père, avait à cœur de bâtir une maison pour le nom de l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Et l’ Éternel dit à David, mon père: Puisque tu as eu à cœur de bâtir une maison pour mon nom, tu as bien fait de l’avoir eu à cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'toutefois, tu ne bâtiras pas la maison; mais ton fils qui sortira de tes reins, lui, bâtira une maison pour mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Et l’ Éternel a accompli sa parole, qu’il a prononcée; et je me suis levé à la place de David, mon père, et je suis assis sur le trône d’Israël, comme l’ Éternel l’a dit; et j’ai bâti la maison pour le nom de l’ Éternel, le Dieu d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'et j’y ai mis l’arche, où est l’alliance de l’ Éternel, qu’il a faite avec les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Et il se tint devant l’autel de l’ Éternel, en face de toute la congrégation d’Israël, et étendit ses mains;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'car Salomon avait fait une estrade d’airain, longue de cinq coudées, large de cinq coudées, et haute de trois coudées, et l’avait mise au milieu de la cour; et il s’y tint, et fléchit les genoux en face de toute la congrégation d’Israël, et étendit ses mains vers les cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'et dit: Éternel, Dieu d’Israël! il n’y a point de Dieu comme toi, dans les cieux et sur la terre, qui gardes l’alliance et la bonté envers tes serviteurs qui marchent devant toi de tout leur cœur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'toi qui as gardé envers ton serviteur David, mon père, ce que tu lui as dit: tu as parlé de ta bouche, et de ta main tu as accompli [ta parole], comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Et maintenant, Éternel, Dieu d’Israël, garde envers ton serviteur David, mon père, ce que tu lui as dit, disant: Tu ne manqueras pas, devant ma face, d’un homme assis sur le trône d’Israël; si seulement tes fils prennent garde à leur voie, pour marcher dans ma loi, comme tu as marché devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Et maintenant, Éternel, Dieu d’Israël, que ta parole, que tu as dite à ton serviteur David, soit ferme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Mais Dieu habitera-t-il vraiment avec l’homme sur la terre? Voici, les cieux, et les cieux des cieux, ne peuvent te contenir; combien moins cette maison que j’ai bâtie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Cependant, Éternel, mon Dieu, aie égard à la prière de ton serviteur et à sa supplication, pour écouter le cri et la prière que ton serviteur t’adresse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'pour que tes yeux soient ouverts jour et nuit sur cette maison, sur le lieu où tu as dit que tu mettrais ton nom, pour écouter la prière que ton serviteur t’adressera [en se tournant] vers ce lieu-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Et écoute les supplications de ton serviteur et de ton peuple Israël, qu’ils t’adresseront [en se tournant] vers ce lieu-ci: toi, écoute des cieux, du lieu de ton habitation; écoute et pardonne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Si un homme pèche contre son prochain, et qu’on lui impose le serment, pour le faire jurer, et que le serment vienne devant ton autel dans cette maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'alors, toi, écoute des cieux, et agis, et juge tes serviteurs, en rendant au méchant [selon ce qu’il a fait], en faisant retomber sa voie sur sa tête, et en justifiant le juste, en lui donnant selon sa justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Et si ton peuple Israël est battu devant l’ennemi, parce qu’ils ont péché contre toi, et qu’ils retournent [vers toi], et confessent ton nom, et te prient, et présentent leur supplication devant toi dans cette maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'alors, toi, écoute des cieux, et pardonne le péché de ton peuple Israël; et fais-les retourner dans la terre que tu leur as donnée, à eux et à leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Quand les cieux seront fermés et qu’il n’y aura pas de pluie, parce qu’ils auront péché contre toi, s’ils prient [en se tournant] vers ce lieu-ci, et qu’ils confessent ton nom et reviennent de leur péché, parce que tu les auras affligés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'alors, toi, écoute dans les cieux, et pardonne le péché de tes serviteurs et de ton peuple Israël, quand tu leur auras enseigné le bon chemin dans lequel ils doivent marcher; et donne la pluie sur ton pays que tu as donné en héritage à ton peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'S’il y a famine dans le pays, s’il y a peste, s’il y a brûlure, ou rouille, sauterelles ou locustes, si ses ennemis l’assiègent dans le pays de ses portes, quelque plaie ou quelque maladie qu’il y ait,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'quelle que soit la prière, quelle que soit la supplication que fera un homme quelconque, ou tout ton peuple Israël, quand ils reconnaîtront chacun sa plaie et sa souffrance et qu’ils étendront leurs mains vers cette maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'alors, toi, écoute des cieux, du lieu de ton habitation, et pardonne, et donne à chacun selon toutes ses voies, suivant que tu connais son cœur (car tu connais, toi seul, le cœur des fils des hommes),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'afin qu’ils te craignent pour marcher dans tes voies, tous les jours qu’ils vivront sur la face de la terre que tu as donnée à nos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Et quant à l’étranger aussi, qui ne sera pas de ton peuple Israël, mais qui viendra d’un pays lointain à cause de ton grand nom, et de ta main forte, et de ton bras étendu, s’il vient et présente sa prière [en se tournant] vers cette maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'alors, toi, écoute des cieux, du lieu de ton habitation, et agis selon tout ce que l’étranger réclamera de toi; afin que tous les peuples de la terre connaissent ton nom, et te craignent, comme ton peuple Israël, et qu’ils sachent que cette maison que j’ai bâtie est appelée de ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Lorsque ton peuple sortira pour la guerre contre ses ennemis, par le chemin par lequel tu l’auras envoyé, et qu’ils te prieront en se tournant vers cette ville que tu as choisie et vers la maison que j’ai bâtie pour ton nom:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'alors, écoute des cieux leur prière et leur supplication, et fais-leur droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'S’ils ont péché contre toi (car il n’y a point d’homme qui ne pèche), et que tu te sois irrité contre eux, et que tu les aies livrés à l’ennemi, et qu’ils les aient emmenés captifs en un pays éloigné ou rapproché,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'et que, dans le pays où ils auront été emmenés captifs, ils rentrent en eux-mêmes, et reviennent [à toi] et te supplient, dans le pays de leur captivité, disant: Nous avons péché, nous avons commis l’iniquité, et nous avons agi méchamment,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, '– et s’ils reviennent à toi de tout leur cœur et de toute leur âme, dans le pays de leur captivité, où on les aura emmenés captifs, et [te] prient en se tournant vers leur pays que tu as donné à leurs pères, et vers la ville que tu as choisie, et vers la maison que j’ai bâtie pour ton nom:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'alors, écoute des cieux, du lieu de ton habitation, leur prière et leurs supplications, et fais-leur droit, et pardonne à ton peuple ce en quoi ils ont péché contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Maintenant, mon Dieu, que tes yeux, je te prie, soient ouverts, et que tes oreilles soient attentives à la prière [qu’on te fera] de ce lieu-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Et maintenant, Éternel Dieu! lève-toi pour [entrer dans] ton repos, toi et l’arche de ta force! Que tes sacrificateurs, Éternel Dieu, soient revêtus de salut, et que tes saints se réjouissent en [ta] bonté!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Éternel Dieu, ne repousse pas la face de ton oint; souviens-toi de [tes] grâces, envers David, ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Et quand Salomon eut achevé de prier, le feu descendit des cieux et consuma l’holocauste et les sacrifices, et la gloire de l’ Éternel remplit la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Et les sacrificateurs ne pouvaient entrer dans la maison de l’ Éternel, car la gloire de l’ Éternel remplissait la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Et tous les fils d’Israël, voyant descendre le feu, et la gloire de l’ Éternel sur la maison, s’inclinèrent le visage en terre sur le pavement, et se prosternèrent, et célébrèrent l’ Éternel: Car il est bon, car sa bonté [demeure] à toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Et le roi et tout le peuple sacrifièrent des sacrifices devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Et le roi Salomon sacrifia un sacrifice de 22 000 bœufs et de 120 000 moutons. Et le roi et tout le peuple firent la dédicace de la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Et les sacrificateurs se tinrent à leurs charges, et les lévites avec les instruments de musique de l’ Éternel, que le roi David avait faits pour célébrer l’ Éternel, parce que sa bonté [demeure] à toujours, – quand David louait par leur moyen. Et les sacrificateurs sonnèrent des trompettes vis-à-vis d’eux, et tout Israël se tenait là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Et Salomon sanctifia le milieu du parvis qui était devant la maison de l’ Éternel; car il offrit là les holocaustes et la graisse des sacrifices de prospérités, parce que l’autel d’airain que Salomon avait fait ne pouvait recevoir l’holocauste, et l’offrande de gâteau, et les graisses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Et Salomon célébra la fête en ce temps-là, pendant sept jours, et tout Israël avec lui, depuis l’entrée de Hamath jusqu’au torrent d’Égypte, une très grande congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Et au huitième jour ils célébrèrent une fête solennelle; car ils firent la dédicace de l’autel pendant sept jours, et la fête pendant sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Et le vingt-troisième jour du septième mois, il renvoya le peuple à ses tentes, joyeux et le cœur heureux à cause du bien que l’ Éternel avait fait à David, et à Salomon, et à Israël, son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Et Salomon acheva la maison de l’ Éternel et la maison du roi; et, en tout ce que Salomon avait eu à cœur de faire dans la maison de l’ Éternel et dans sa maison, il réussit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Et l’ Éternel apparut de nuit à Salomon, et lui dit: J’ai entendu ta prière, et je me suis choisi ce lieu-ci pour une maison de sacrifice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Si je ferme les cieux et qu’il n’y ait pas de pluie, et si je commande à la sauterelle de dévorer la terre, et si j’envoie la peste parmi mon peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'et que mon peuple, qui est appelé de mon nom, s’humilie, et prie, et cherche ma face, et revienne de ses mauvaises voies, moi aussi j’écouterai des cieux, et je pardonnerai leur péché, et je guérirai leur pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Maintenant mes yeux seront ouverts et mes oreilles attentives à la prière [qu’on fera] de ce lieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'car maintenant j’ai choisi et sanctifié cette maison, afin que mon nom y soit à jamais; et mes yeux et mon cœur seront toujours là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Et toi, si tu marches devant moi comme a marché David, ton père, pour faire selon tout ce que je t’ai commandé, et si tu gardes mes statuts et mes ordonnances,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'j’affermirai le trône de ton royaume, selon que j’ai fait alliance avec David, ton père, disant: Tu ne manqueras pas d’un homme pour gouverner Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Mais si vous vous détournez, et que vous abandonniez mes statuts et mes commandements que j’ai mis devant vous, et que vous alliez et serviez d’autres dieux et vous prosterniez devant eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'je vous arracherai de dessus ma terre que je vous ai donnée; et cette maison que j’ai sanctifiée pour mon nom, je la rejetterai de devant ma face, et j’en ferai un proverbe et un sujet de raillerie parmi tous les peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Et cette maison, si haut élevée qu’elle soit, quiconque passera près d’elle sera étonné et dira: Pourquoi l’ Éternel a-t-il fait ainsi à ce pays et à cette maison?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Et on dira: Parce qu’ils ont abandonné l’ Éternel, le Dieu de leurs pères, qui les fit sortir du pays d’Égypte, et qu’ils se sont attachés à d’autres dieux, et se sont prosternés devant eux et les ont servis: c’est pourquoi il a fait venir sur eux tout ce mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, '*Et au bout de 20 ans, lorsque Salomon eut bâti la maison de l’ Éternel et sa propre maison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'il arriva que Salomon bâtit aussi les villes que Hiram avait données à Salomon, et y fit habiter les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Et Salomon alla en Hamath-Tsoba, et l’assujettit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Et il bâtit Tadmor dans le désert, et toutes les villes à entrepôts qu’il bâtit en Hamath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Et il bâtit Beth-Horon la haute, et Beth-Horon la basse, villes fortes, avec des murailles, des portes et des barres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'et Baalath, et toutes les villes à entrepôts qu’avait Salomon, et toutes les villes pour les chars, et les villes pour la cavalerie, et tout ce que Salomon désira de bâtir à Jérusalem, et au Liban, et dans tout le pays de sa domination.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, '– Tout le peuple qui restait des Héthiens, et des Amoréens, et des Phéréziens, et des Héviens, et des Jébusiens, qui n’étaient pas d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, '– leurs fils qui étaient restés après eux dans le pays [et] que les fils d’Israël n’avaient pas détruits, Salomon les assujettit aux levées, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Mais des fils d’Israël, Salomon n’en fit pas des esclaves pour ses travaux; car ils étaient hommes de guerre, et chefs de ses capitaines, et chefs de ses chars et de sa cavalerie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Et c’est ici [le nombre] des chefs des intendants qu’avait le roi Salomon: 250, qui avaient autorité sur le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Et Salomon fit monter la fille du Pharaon, de la ville de David, dans la maison qu’il avait bâtie pour elle; car il dit: Ma femme n’habitera pas dans la maison de David, roi d’Israël, car les lieux où est entrée l’arche de l’ Éternel sont saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Alors Salomon offrit des holocaustes à l’ Éternel, sur l’autel de l’ Éternel, qu’il avait bâti devant le portique,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'offrant chaque jour ce qu’il fallait, selon le commandement de Moïse, pour les sabbats, et pour les nouvelles lunes, et pour les jours solennels, trois fois par an, à la fête des pains sans levain, et à la fête des semaines, et à la fête des tabernacles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Et il établit, suivant l’ordonnance de David, son père, les classes des sacrificateurs dans leur service, et les lévites dans leurs charges, pour louer et pour faire le service devant les sacrificateurs, selon l’œuvre de chaque jour, et les portiers dans leurs divisions, à chaque porte; car tel avait été le commandement de David, homme de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Et on ne s’écarta point du commandement du roi pour les sacrificateurs et les lévites, en aucune chose, ni à l’égard des trésors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Ainsi toute l’œuvre de Salomon fut préparée, jusqu’au jour où la maison de l’ Éternel fut fondée, et jusqu’à ce qu’elle fut terminée. La maison de l’ Éternel fut achevée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Alors Salomon s’en alla à Étsion-Guéber et à Éloth, sur le bord de la mer, dans le pays d’Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Et Hiram lui envoya, par la main de ses serviteurs, des navires et des serviteurs connaissant la mer; et ils allèrent avec les serviteurs de Salomon à Ophir, et y prirent 450 talents d’or, et les apportèrent au roi Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, '*Et la reine de Sheba entendit parler de la renommée de Salomon, et elle vint à Jérusalem, pour éprouver Salomon par des énigmes, avec un fort grand train, et des chameaux qui portaient des aromates et de l’or en grande quantité, et des pierres précieuses; et elle vint vers Salomon et parla avec lui de tout ce qu’elle avait sur son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Et Salomon lui expliqua toutes les choses dont elle parlait; et il n’y eut pas une chose cachée pour Salomon, [pas une chose] qu’il ne lui explique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Et la reine de Sheba vit la sagesse de Salomon, et la maison qu’il avait bâtie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'et les mets de sa table, et la tenue de ses serviteurs, et l’ordre de service de ses officiers, et leurs vêtements, et ses échansons, et leurs vêtements, et la rampe par laquelle il montait dans la maison de l’ Éternel, et il n’y eut plus d’esprit en elle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'et elle dit au roi: Ce que j’ai entendu dire dans mon pays sur tout ton état et sur ta sagesse était la vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'mais je n’ai pas cru leurs paroles, jusqu’à ce que je sois venue et que mes yeux aient vu; et voici, on ne m’avait pas rapporté la moitié de la grandeur de ta sagesse: tu surpasses la rumeur que j’en ai entendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Heureux tes gens, et heureux ceux-ci, tes serviteurs, qui se tiennent continuellement devant toi, et qui entendent ta sagesse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Béni soit l’ Éternel, ton Dieu, qui a pris plaisir en toi, pour te placer sur son trône comme roi pour l’ Éternel, ton Dieu! Parce que ton Dieu a aimé Israël pour l’établir à toujours, il t’a fait roi sur eux pour faire droit et justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Et elle donna au roi 120 talents d’or, et des aromates en très grande quantité, et des pierres précieuses; et il n’y a pas eu d’aromates pareils à ceux que la reine de Sheba donna au roi Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, '(Et les serviteurs de Hiram aussi, et les serviteurs de Salomon, qui apportèrent de l’or d’Ophir, apportèrent du bois d’algummim et des pierres précieuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Et, avec le bois d’algummim, le roi fit des escaliers pour la maison de l’ Éternel et pour la maison du roi, et des harpes et des luths pour les chanteurs: et on n’en avait pas vu de semblable auparavant dans le pays de Juda.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Et le roi Salomon donna à la reine de Sheba tout son désir, [tout ce] qu’elle demanda, outre ce qu’elle avait apporté au roi. Et elle s’en retourna, et s’en alla dans son pays, elle et ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, '*Et le poids de l’or qui arrivait à Salomon dans une année était de 666 talents d’or,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'outre ce qu’apportaient les commerçants ambulants et les trafiquants, et ce qu’apportaient à Salomon tous les rois de l’Arabie, et les gouverneurs du pays, en fait d’or et d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Et le roi Salomon fit 200 grands boucliers d’or battu, mettant à chaque bouclier 600 [sicles] d’or battu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'et 300 petits boucliers d’or battu, mettant à chaque bouclier 300 [sicles] d’or; et le roi les mit dans la maison de la forêt du Liban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Et le roi fit un grand trône d’ivoire, et le recouvrit d’or pur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'et le trône avait six degrés et un marchepied d’or attenants au trône, et des bras d’un côté et de l’autre à l’endroit du siège, et deux lions qui se tenaient à côté des bras,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'et douze lions qui se tenaient là sur les six degrés, d’un côté et de l’autre: il ne s’en était point fait de pareil dans aucun royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Et tous les vases à boire du roi Salomon étaient d’or, et tous les vases de la maison de la forêt du Liban, d’or pur: l’argent, aux jours de Salomon, n’était compté pour rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Car les navires du roi allaient à Tarsis avec les serviteurs de Hiram: une fois tous les trois ans les navires de Tarsis venaient, apportant de l’or et de l’argent, de l’ivoire, et des singes et des paons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Et le roi Salomon fut plus grand que tous les rois de la terre en richesse et en sagesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Et tous les rois de la terre recherchaient la face de Salomon, pour entendre sa sagesse, que Dieu avait mise dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Et ils apportaient chacun son présent: des vases d’argent et des vases d’or, et des vêtements, des armes, et des aromates, des chevaux et des mulets: chaque année le tribut de l’année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Et Salomon avait 4 000 stalles pour des chevaux et des chars, et 12 000 cavaliers; et il les plaça dans les villes à chars, et auprès du roi à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Et il dominait sur tous les rois, depuis le fleuve jusqu’au pays des Philistins et jusqu’à la frontière d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Et le roi fit que l’argent, dans Jérusalem, était comme les pierres, et il fit que les cèdres étaient, en quantité, comme les sycomores qui sont dans le pays plat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Et l’on exportait d’Égypte et de tous les pays des chevaux pour Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Et le reste des actes de Salomon, les premiers et les derniers, ne sont-ils pas écrits dans les paroles de Nathan, le prophète, et dans la prophétie d’Akhija, le Silonite, et dans la vision de Jehdo, le voyant, touchant Jéroboam, fils de Nebath?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Et Salomon régna à Jérusalem sur tout Israël 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Et Salomon s’endormit avec ses pères; et on l’enterra dans la ville de David, son père; et Roboam, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, '*Et Roboam alla à Sichem, car tout Israël était venu à Sichem pour le faire roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Et quand Jéroboam, fils de Nebath, qui était en Égypte, où il s’était enfui de devant le roi Salomon, l’apprit, il arriva que Jéroboam revint d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Et on envoya et on l’appela; et Jéroboam et tout Israël vinrent et parlèrent à Roboam, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Ton père a rendu notre joug dur; et maintenant, allège le dur service de ton père et son joug pesant qu’il a mis sur nous, et nous te servirons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Et il leur dit: Encore trois jours, et revenez vers moi. Et le peuple s’en alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Et le roi Roboam tint conseil avec les vieillards qui s’étaient tenus devant Salomon, son père, lorsqu’il vivait, disant: Comment conseillez-vous de répondre à ce peuple?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Et ils lui parlèrent, disant: Si tu es bon envers ce peuple, et si tu es affable envers eux, et si tu leur dis de bonnes paroles, ils seront tes serviteurs à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Mais il laissa le conseil des vieillards, qu’ils lui avaient donné, et tint conseil avec les jeunes gens qui avaient grandi avec lui, qui se tenaient devant lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'et il leur dit: Que conseillez-vous que nous répondions à ce peuple, qui m’a parlé, disant: Allège le joug que ton père a mis sur nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Et les jeunes gens qui avaient grandi avec lui, lui parlèrent, disant: Tu diras ainsi au peuple qui t’a parlé, disant: Ton père a rendu pesant notre joug; toi, allège-le de dessus nous; – tu leur diras ainsi: Mon petit doigt est plus gros que les reins de mon père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'et maintenant, mon père a chargé sur vous un joug pesant, et moi j’ajouterai à votre joug; mon père vous a corrigés avec des fouets, et moi [je vous corrigerai] avec des scorpions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Et Jéroboam et tout le peuple vinrent vers Roboam le troisième jour, comme le roi avait dit, en disant: Revenez vers moi le troisième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Et le roi leur répondit avec dureté; et le roi Roboam laissa le conseil des vieillards;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'et il leur parla selon le conseil des jeunes gens, disant: Mon père a rendu pesant votre joug, et moi j’y ajouterai; mon père vous a corrigés avec des fouets, et moi [je vous corrigerai] avec des scorpions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Et le roi n’écouta pas le peuple, car cela était amené par Dieu, afin que l’ Éternel accomplisse sa parole, qu’il avait dite par Akhija, le Silonite, à Jéroboam, fils de Nebath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Et tout Israël vit que le roi ne les avait pas écoutés. Et le peuple répondit au roi, disant: Quelle part avons-nous en David? Et nous n’avons pas d’héritage dans le fils d’Isaï. Chacun à ses tentes, Israël! Maintenant, David, regarde à ta maison! Et tout Israël s’en alla à ses tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Mais, quant aux fils d’Israël qui habitaient dans les villes de Juda, Roboam régna sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Et le roi Roboam envoya Hadoram, qui était préposé sur les levées; et les fils d’Israël le lapidèrent avec des pierres, et il mourut. Et le roi Roboam se hâta de monter sur un char pour s’enfuir à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Et Israël se rebella contre la maison de David, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Et Roboam s’en alla à Jérusalem. Et il assembla la maison de Juda, et Benjamin, 180 000 hommes d’élite propres à la guerre, pour faire la guerre à Israël, afin de ramener le royaume à Roboam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Et la parole de l’ Éternel vint à Shemahia, homme de Dieu, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Parle à Roboam, fils de Salomon, roi de Juda, et à tout Israël en Juda et en Benjamin, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Ainsi dit l’ Éternel: Ne montez pas, et ne faites pas la guerre à vos frères; retournez chacun à sa maison, car c’est de par moi que cette chose a eu lieu. Et ils écoutèrent les paroles de l’ Éternel, et s’en retournèrent et n’allèrent pas contre Jéroboam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Et Roboam demeura à Jérusalem. Et il bâtit des villes en Juda, et en [fit] des forteresses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Et il bâtit Bethléhem, et Étam, et Thekoa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'et Beth-Tsur, et Soco, et Adullam,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'et Gath, et Marésha, et Ziph,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'et Adoraïm, et Lakis, et Azéka,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'et Tsorha, et Ajalon, et Hébron, qui étaient en Juda et en Benjamin, des villes fortes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Et il fortifia les places fortes, et y mit des chefs, et des approvisionnements de vivres, et d’huile, et de vin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'et, dans chaque ville, des boucliers et des piques; et il les fortifia beaucoup. Et Juda et Benjamin étaient à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Et les sacrificateurs et les Lévites qui étaient dans tout Israël, se joignirent à lui de toutes leurs contrées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'car les Lévites abandonnèrent leurs banlieues et leurs possessions, et vinrent en Juda et à Jérusalem, parce que Jéroboam et ses fils les avaient repoussés de la sacrificature de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'et [Jéroboam] s’était établi des sacrificateurs pour les hauts lieux, et pour les boucs et pour les veaux qu’il avait faits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Et à leur suite, ceux de toutes les tribus d’Israël qui avaient mis leur cœur à chercher l’ Éternel, le Dieu d’Israël, vinrent à Jérusalem pour sacrifier à l’ Éternel, le Dieu de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Et ils fortifièrent le royaume de Juda, et affermirent Roboam, fils de Salomon, pendant trois ans; car ils marchèrent dans le chemin de David et de Salomon pendant trois ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Et Roboam prit pour femme Mahalath, fille de Jerimoth, fils de David, [et] d’Abikhaïl, fille d’Éliab, fils d’Isaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'et elle lui enfanta des fils: Jehush, et Shemaria, et Zaham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Et après elle, il prit Maaca, fille d’Absalom; et elle lui enfanta Abija, et Atthaï, et Ziza, et Shelomith.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Et Roboam aima Maaca, fille d’Absalom, plus que toutes ses femmes et ses concubines; car il avait pris 18 femmes et 60 concubines, et il engendra 28 fils et 60 filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Et Roboam établit chef Abija, fils de Maaca, pour être prince parmi ses frères; car [il voulait] le faire roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Et il agit avec intelligence, et dispersa tous ses fils par toutes les contrées de Juda et de Benjamin, dans toutes les villes fortes, et leur donna des vivres en abondance, et demanda [pour eux] beaucoup de femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Et il arriva que, quand le royaume de Roboam fut affermi, et qu’il se fut fortifié, il abandonna la loi de l’ Éternel, et tout Israël avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Et parce qu’ils avaient péché contre l’ Éternel, il arriva, en la cinquième année du roi Roboam, que Shishak, roi d’Égypte, monta contre Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'avec 1 200 chars et 60 000 cavaliers; et le peuple qui vint avec lui d’Égypte, Libyens, Sukkiens, et Éthiopiens, était sans nombre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'et il prit les villes fortes qui étaient à Juda, et vint jusqu’à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Et Shemahia, le prophète, vint vers Roboam et vers les chefs de Juda qui s’étaient assemblés à Jérusalem, fuyant Shishak, et leur dit: Ainsi dit l’ Éternel: Vous m’avez abandonné, et moi je vous ai aussi abandonnés aux mains de Shishak.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Et les chefs d’Israël et le roi s’humilièrent, et dirent: L’ Éternel est juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Et quand l’ Éternel vit qu’ils s’étaient humiliés, la parole de l’ Éternel vint à Shemahia, disant: Ils se sont humiliés, je ne les détruirai pas; je leur donnerai un peu de délivrance, et ma fureur ne se déversera pas sur Jérusalem par le moyen de Shishak;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'mais ils lui seront asservis, et ils connaîtront ce que c’est que mon service, et le service des royaumes des pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Et Shishak, roi d’Égypte, monta contre Jérusalem, et prit les trésors de la maison de l’ Éternel et les trésors de la maison du roi: il prit tout. Et il prit les boucliers d’or que Salomon avait faits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Et le roi Roboam fit à leur place des boucliers d’airain, et les confia aux mains des chefs des coureurs qui gardaient l’entrée de la maison du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Et toutes les fois que le roi entrait dans la maison de l’ Éternel, il arrivait que les coureurs venaient et les portaient, puis ils les rapportaient dans la chambre des coureurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Et quand il s’humilia, la colère de l’ Éternel se détourna de lui, et il ne le détruisit pas entièrement; et aussi il y avait en Juda de bonnes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Et le roi Roboam se fortifia dans Jérusalem, et régna. Or Roboam était âgé de 41 ans lorsqu’il commença de régner; et il régna 17 ans à Jérusalem, la ville que l’ Éternel avait choisie d’entre toutes les tribus d’Israël pour y mettre son nom; et le nom de sa mère était Naama, une Ammonite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Mais il fit le mal; car il n’appliqua pas son cœur à rechercher l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Et les actes de Roboam, les premiers et les derniers, ne sont-ils pas écrits dans les paroles de Shemahia, le prophète, et d’Iddo, le voyant, dans les registres généalogiques? Et il y eut des guerres continuelles entre Roboam et Jéroboam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Et Roboam s’endormit avec ses pères, et il fut enterré dans la ville de David; et Abija, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, '*La dix-huitième année du roi Jéroboam, Abija commença de régner sur Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Il régna trois ans à Jérusalem; et le nom de sa mère était Micaïa, fille d’Uriel, de Guibha. Et il y eut guerre entre Abija et Jéroboam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Et Abija commença la guerre avec une armée d’hommes de guerre, de 400 000 hommes d’élite; et Jéroboam se rangea en bataille contre lui avec 800 000 hommes d’élite, forts et vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Et Abija se tint sur le haut de la montagne de Tsemaraïm, qui est dans la montagne d’Éphraïm, et dit: Écoutez-moi, Jéroboam et tout Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'N’est-ce pas à vous de savoir que l’ Éternel, le Dieu d’Israël, a donné à David la royauté sur Israël pour toujours, à lui et à ses fils, par une alliance de sel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Et Jéroboam, fils de Nebath, serviteur de Salomon, fils de David, s’est levé, et s’est révolté contre son seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'et des hommes de rien, des fils de Bélial, se sont assemblés vers lui; et ils se sont fortifiés contre Roboam, fils de Salomon; et Roboam était jeune et craintif; et il ne s’est pas montré fort devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Et maintenant vous pensez vous montrer forts contre le royaume de l’ Éternel, qui est dans la main des fils de David, et vous êtes une grande multitude, et vous avez avec vous les veaux d’or que Jéroboam vous a faits pour [être vos] dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'N’avez-vous pas chassé les sacrificateurs de l’ Éternel, les fils d’Aaron, et les lévites? Et vous vous êtes fait des sacrificateurs, comme les peuples des [autres] pays; quiconque est venu avec un jeune taureau et sept béliers, pour être consacré, est devenu sacrificateur de ce qui n’est pas Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Mais pour nous, l’ Éternel est notre Dieu, et nous ne l’avons pas abandonné; et des sacrificateurs, fils d’Aaron, servent l’ Éternel, et les lévites sont à leurs fonctions;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'et chaque matin et chaque soir, ils font fumer les holocaustes à l’ Éternel, et l’encens de drogues odoriférantes; et [nous avons] les pains rangés sur la table pure, et le chandelier d’or et ses lampes pour brûler chaque soir, car nous, nous faisons l’acquit de la charge que l’ Éternel, notre Dieu, nous a confiée; mais vous, vous l’avez abandonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Et voici, nous avons avec nous, à notre tête, Dieu et ses sacrificateurs, et les trompettes au son éclatant, pour sonner avec éclat contre vous. Fils d’Israël, ne faites pas la guerre contre l’ Éternel, le Dieu de vos pères; car vous ne réussirez pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Mais Jéroboam fit prendre un détour à une embuscade pour venir derrière eux; et ils étaient devant Juda, et l’embuscade était derrière eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Et Juda se tourna, et voici, la bataille était contre eux, devant et derrière; et ils crièrent à l’ Éternel, et les sacrificateurs sonnèrent des trompettes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'et les hommes de Juda jetèrent des cris; et il arriva, comme les hommes de Juda jetaient des cris, que Dieu frappa Jéroboam et tout Israël, devant Abija et Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Et les fils d’Israël s’enfuirent devant Juda, et Dieu les livra en leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Et Abija et son peuple leur infligèrent une grande défaite, et il tomba d’Israël 500 000 hommes d’élite blessés à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Et les fils d’Israël furent humiliés en ce temps-là, et les fils de Juda furent affermis, car ils s’appuyaient sur l’ Éternel, le Dieu de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Et Abija poursuivit Jéroboam et lui prit des villes: Béthel et les villages de son ressort, et Jeshana et les villages de son ressort, et Éphron et les villages de son ressort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Et Jéroboam n’eut plus de force durant les jours d’Abija; et l’ Éternel le frappa, et il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Et Abija s’affermit, et prit 14 femmes, et engendra 22 fils et 16 filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Et le reste des actes d’Abija, et ses voies et ses paroles, sont écrits dans les commentaires d’Iddo le prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 23, '*Et Abija s’endormit avec ses pères, et on l’enterra dans la ville de David. Et Asa, son fils, régna à sa place. De ses jours, le pays fut en repos pendant dix ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Et Asa fit ce qui est bon et droit aux yeux de l’ Éternel, son Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'et il ôta les autels des [dieux] étrangers, et les hauts lieux, et il brisa les statues et abattit les ashères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'et il dit à Juda de rechercher l’ Éternel, le Dieu de leurs pères, et de pratiquer la loi et les commandements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'et il ôta de toutes les villes de Juda les hauts lieux et les colonnes consacrées au soleil. Et le royaume fut tranquille devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Et il bâtit des villes fortes en Juda, car le pays était tranquille, et il n’eut point de guerre pendant ces années-là, car l’ Éternel lui donna du repos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Et il dit à Juda: Bâtissons ces villes, et entourons-les de murailles et de tours, de portes et de barres, pendant que le pays est devant nous; car nous avons recherché l’ Éternel, notre Dieu: nous l’avons recherché, et il nous a donné du repos tout à l’entour. Et ils bâtirent et prospérèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Et Asa avait une armée de 300 000 [hommes] de Juda, portant le bouclier et la pique, et de 280 000 de Benjamin, portant l’écu et tirant de l’arc, tous des hommes forts et vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Et Zérakh, l’Éthiopien, sortit contre eux avec une armée d’un million [d’hommes], et de 300 chars; et il vint jusqu’à Marésha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Et Asa sortit au-devant de lui; et ils se rangèrent en bataille dans la vallée de Tsephatha, près de Marésha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Et Asa invoqua l’ Éternel, son Dieu, et dit: Éternel! il n’y a pas de différence pour toi, pour aider, entre beaucoup [de force] et point de force. Aide-nous, Éternel, notre Dieu! car nous nous appuyons sur toi; et c’est en ton nom que nous sommes venus contre cette multitude. Tu es l’ Éternel, notre Dieu; que l’homme n’ait point de force contre toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Et l’ Éternel frappa les Éthiopiens devant Asa et devant Juda, et les Éthiopiens s’enfuirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Et Asa et le peuple qui était avec lui les poursuivirent jusqu’à Guérar; et il tomba tant d’Éthiopiens qu’ils ne purent reprendre [leur] force, car ils furent abattus devant l’ Éternel et devant son armée. Et ils emportèrent un très grand butin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'et ils frappèrent toutes les villes qui étaient autour de Guérar, car la frayeur de l’ Éternel était sur elles; et ils les pillèrent toutes, car il y avait dans ces villes un grand butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Ils frappèrent aussi les tentes des troupeaux, et emmenèrent du menu bétail en quantité, et des chameaux; et ils s’en retournèrent à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Et l’Esprit de Dieu fut sur Azaria, fils d’Oded:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'et il sortit au-devant d’Asa, et lui dit: Asa, et tout Juda et Benjamin, écoutez-moi: L’ Éternel est avec vous quand vous êtes avec lui; et si vous le cherchez vous le trouverez, et si vous l’abandonnez il vous abandonnera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Pendant bien des jours il n’y eut pour Israël ni vrai Dieu, ni sacrificateur pour enseigner, ni loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'et, dans leur angoisse, ils se retournèrent vers l’ Éternel, le Dieu d’Israël, et le cherchèrent, et ils l’ont trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Et, en ces temps-là, il n’y avait point de paix pour ceux qui sortaient et qui entraient, car il y avait beaucoup de troubles parmi tous les habitants du pays,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'et nation se brisait contre nation, et ville contre ville, car Dieu les troublait par toutes sortes d’angoisses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Vous donc, fortifiez-vous, et que vos mains ne soient point lâches; car il y a une récompense pour ce que vous ferez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Et quand Asa eut entendu ces paroles et la prophétie d’Oded, le prophète, il se fortifia, et fit disparaître les choses abominables de tout le pays de Juda et de Benjamin, et des villes qu’il avait prises de la montagne d’Éphraïm, et il renouvela l’autel de l’ Éternel, qui était devant le portique de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Et il assembla tout Juda et Benjamin, et les étrangers qui étaient avec eux, d’Éphraïm, et de Manassé, et de Siméon; car beaucoup d’Israélites passèrent à lui quand ils virent que l’ Éternel, son Dieu, était avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Et ils se rassemblèrent à Jérusalem, le troisième mois de la quinzième année du règne d’Asa;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'et ils sacrifièrent à l’ Éternel, en ce jour-là, du butin qu’ils avaient amené, 700 bœufs et 7 000 moutons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Et ils s’engagèrent ensemble à rechercher l’ Éternel, le Dieu de leurs pères, de tout leur cœur et de toute leur âme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, '[établissant] que quiconque ne rechercherait pas l’ Éternel, le Dieu d’Israël, serait mis à mort, tant petit que grand, tant homme que femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Et ils jurèrent à l’ Éternel à haute voix, et à grands cris, et avec des trompettes et des cors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Et tout Juda se réjouit du serment, car ils avaient juré de tout leur cœur, et ils avaient recherché l’ Éternel de toute leur âme, et ils l’avaient trouvé. Et l’ Éternel leur donna du repos tout à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Et même à Maaca, sa mère, le roi Asa ôta sa position de reine, parce qu’elle avait fait un simulacre pour Ashère; et Asa abattit son simulacre, et le broya, et le brûla dans la vallée du Cédron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Mais les hauts lieux ne furent pas ôtés d’Israël; cependant le cœur d’Asa fut parfait tous ses jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Et il apporta dans la maison de Dieu les choses saintes de son père et les choses qu’il avait lui-même consacrées, de l’argent, et de l’or, et des ustensiles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Et il n’y eut point de guerre jusqu’à la trente-cinquième année du règne d’Asa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'La trente-sixième année du règne d’Asa, Baësha, roi d’Israël, monta contre Juda; et il bâtit Rama, afin de ne permettre à personne de sortir de chez Asa, roi de Juda, ou d’entrer vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Et Asa tira l’argent et l’or des trésors de la maison de l’ Éternel et de la maison du roi, et envoya vers Ben-Hadad, roi de Syrie, qui habitait à Damas, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Il y a alliance entre moi et toi, et entre mon père et ton père; voici, je t’envoie de l’argent et de l’or: va, romps ton alliance avec Baësha, roi d’Israël, afin qu’il s’en aille d’auprès de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Et Ben-Hadad écouta le roi Asa, et envoya les chefs de ses troupes contre les villes d’Israël, et ils frappèrent Ijon, et Dan, et Abel-Maïm, et tous les entrepôts des villes de Nephthali.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Et il arriva, quand Baësha l’apprit, qu’il se désista de bâtir Rama, et fit cesser ses travaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Et le roi Asa prit tout Juda, et ils emportèrent les pierres de Rama, et les bois avec lesquels Baësha bâtissait; et il en bâtit Guéba et Mitspa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Et en ce temps-là Hanani, le voyant, vint vers Asa, roi de Juda, et lui dit: Parce que tu t’es appuyé sur le roi de Syrie, et que tu ne t’es pas appuyé sur l’ Éternel, ton Dieu, à cause de cela, l’armée du roi de Syrie est échappée de ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Les Éthiopiens et les Libyens n’étaient-ils pas une armée nombreuse, avec des chars et des cavaliers en très grand nombre? Et quand tu t’appuyais sur l’ Éternel, il les livra entre tes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Car les yeux de l’ Éternel parcourent toute la terre, afin qu’il se montre fort, en faveur de ceux qui sont d’un cœur parfait envers lui. En cela, tu as agi follement; car désormais tu auras des guerres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Et Asa s’irrita contre le voyant, et le mit en prison; car il était indigné contre lui à cause de cela. Et en ce temps-là, Asa opprima quelques-uns du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Et voici, les actes d’Asa, les premiers et les derniers, voici, ils sont écrits dans le livre des rois de Juda et d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Et la trente-neuvième année de son règne, Asa fut malade des pieds, jusqu’à ce que son mal fut extrêmement grand; et dans sa maladie aussi, il ne rechercha pas l’ Éternel, mais les médecins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Et Asa s’endormit avec ses pères, et mourut la quarante et unième année de son règne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Et on l’enterra dans son sépulcre, qu’il s’était creusé dans la ville de David; et on le coucha dans un lit qu’on remplit d’aromates et d’un mélange d’épices composé selon l’art du parfumeur; et on en brûla pour lui en très grande abondance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, '*Et Josaphat, son fils, régna à sa place; et il se fortifia contre Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'et mit des troupes dans toutes les villes fortes de Juda, et mit des garnisons dans le pays de Juda et dans les villes d’Éphraïm qu’Asa, son père, avait prises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Et l’ Éternel fut avec Josaphat, car il marcha dans les premières voies de David, son père, et ne rechercha point les Baals,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'mais il rechercha le Dieu de son père, et marcha dans ses commandements, et non comme faisait Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Et l’ Éternel affermit le royaume dans sa main; et tout Juda fit des présents à Josaphat, et il eut beaucoup de richesses et de gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Et il prit courage dans les voies de l’ Éternel, et de plus, il ôta de Juda les hauts lieux et les ashères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Et la troisième année de son règne, il envoya ses chefs, Ben-Haïl, et Abdias, et Zacharie, et Nethaneël, et Michée, pour enseigner dans les villes de Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'et avec eux les lévites, Shemahia, et Nethania, et Zebadia, et Asçaël, et Shemiramoth, et Jonathan, et Adonija, et Tobija, et Tob-Adonija, lévites; et avec eux Élishama et Joram, sacrificateurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'et ils enseignèrent en Juda, ayant avec eux le livre de la loi de l’ Éternel; et ils firent le tour de toutes les villes de Juda, et enseignèrent parmi le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Et la frayeur de l’ Éternel fut sur tous les royaumes des pays qui étaient autour de Juda, et ils ne firent pas la guerre à Josaphat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Et il y eut des Philistins qui apportèrent à Josaphat des présents, et de l’argent comme tribut; les Arabes aussi lui amenèrent du menu bétail, 7 700 béliers et 7 700 boucs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Et Josaphat alla grandissant jusqu’au plus haut degré. Et il bâtit en Juda des châteaux et des villes à entrepôts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Et il eut beaucoup de travail dans les villes de Juda, et des hommes de guerre forts et vaillants dans Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Et c’est ici leur recensement, selon leurs maisons de pères: pour Juda, les chefs de milliers, Adna, le chef, et avec lui 300 000 hommes forts et vaillants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'et à côté de lui, Jokhanan, le chef, et avec lui 280 000;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'et à côté de lui, Amasia, fils de Zicri, qui s’était volontairement donné à l’ Éternel, et avec lui 200 000 hommes forts et vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Et de Benjamin, l’homme fort et vaillant, Éliada, et avec lui 200 000 [hommes] armés de l’arc et de l’écu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'et à côté de lui, Jozabad, et avec lui 180 000 [hommes] équipés pour l’armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Ce sont là ceux qui servaient le roi, outre ceux que le roi avait mis dans les villes fortes, dans tout Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Et Josaphat eut beaucoup de richesses et de gloire; et il s’allia par mariage avec Achab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Et au bout de quelques années, il descendit vers Achab à Samarie; et Achab tua pour lui et pour le peuple qui était avec lui du menu et du gros bétail en abondance, et il le persuada de monter contre Ramoth de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Et Achab, roi d’Israël, dit à Josaphat, roi de Juda: Viendras-tu avec moi à Ramoth de Galaad? Et il lui dit: Moi, je suis comme toi, et mon peuple comme ton peuple; et [je serai] avec toi dans la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Et Josaphat dit au roi d’Israël: Enquiers-toi aujourd’hui, je te prie, de la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Et le roi d’Israël rassembla les prophètes, 400 hommes, et leur dit: Irons-nous à la guerre contre Ramoth de Galaad, ou m’en abstiendrai-je? Et ils dirent: Monte; et Dieu la livrera en la main du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Et Josaphat dit: N’y a-t-il pas ici encore un prophète de l’ Éternel, pour que nous nous enquérions auprès de lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Et le roi d’Israël dit à Josaphat: Il y a encore un homme, pour consulter l’ Éternel par lui; mais je le hais, car il ne prophétise pas du bien à mon égard, mais toujours du mal; c’est Michée, fils de Jimla. Et Josaphat dit: Que le roi ne parle pas ainsi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Et le roi d’Israël appela un eunuque, et dit: Fais promptement venir Michée, fils de Jimla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Et le roi d’Israël et Josaphat, roi de Juda, étaient assis chacun sur son trône, revêtus de leurs robes; ils étaient assis sur une place ouverte à l’entrée de la porte de Samarie; et tous les prophètes prophétisaient devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Et Sédécias, fils de Kenaana, se fit des cornes de fer, et dit: Ainsi dit l’ Éternel: Avec celles-ci tu heurteras les Syriens jusqu’à les exterminer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Et tous les prophètes prophétisaient de même, disant: Monte à Ramoth de Galaad, et prospère; et l’ Éternel la livrera en la main du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Et le messager qui était allé pour appeler Michée lui parla, disant: Voici, les paroles des prophètes, d’une seule bouche, [annoncent] du bien au roi; que ta parole donc soit, je te prie, comme celle de l’un d’eux, et annonce du bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Mais Michée dit: L’ Éternel est vivant, que ce que mon Dieu dira, je l’annoncerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Et il vint vers le roi. Et le roi lui dit: Michée, irons-nous à la guerre à Ramoth de Galaad, ou m’en abstiendrai-je? Et il dit: Montez et prospérez; et ils seront livrés entre vos mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Et le roi lui dit: Combien de fois t’adjurerai-je de ne me dire que la vérité au nom de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Et [Michée] dit: J’ai vu tout Israël dispersé sur les montagnes comme un troupeau qui n’a pas de berger; et l’ Éternel a dit: Ceux-ci n’ont pas de seigneur; qu’ils s’en retournent en paix chacun à sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Et le roi d’Israël dit à Josaphat: Ne t’ai-je pas dit qu’il ne prophétise pas du bien à mon égard, mais du mal?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Et [Michée] dit: C’est pourquoi, écoutez la parole de l’ Éternel. J’ai vu l’ Éternel assis sur son trône, et toute l’armée des cieux se tenant à sa droite et à sa gauche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'et l’ Éternel dit: Qui persuadera Achab, roi d’Israël, afin qu’il monte et qu’il tombe à Ramoth de Galaad? Et on parla, celui-ci disant ainsi, et celui-là disant ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Et un esprit sortit, et se tint devant l’ Éternel, et dit: Moi, je le persuaderai. Et l’ Éternel lui dit: Comment?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Et il dit: Je sortirai, et je serai un esprit de mensonge dans la bouche de tous ses prophètes. Et [l’ Éternel] dit: Tu le persuaderas, et aussi tu réussiras: sors, et fais ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Et maintenant, voici, l’ Éternel a mis un esprit de mensonge dans la bouche de tes prophètes que voilà, et l’ Éternel a prononcé du mal à ton sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Et Sédécias, fils de Kenaana, s’approcha et frappa Michée sur la joue, et dit: Par quel chemin a passé l’Esprit de l’ Éternel, d’avec moi, pour te parler?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Et Michée dit: Voici, tu le verras ce jour-là, quand tu iras de chambre en chambre pour te cacher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Et le roi d’Israël dit: Prenez Michée, et emmenez-le à Amon, chef de la ville, et à Joas, fils du roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'et vous direz: Ainsi dit le roi: Mettez cet [homme] en prison, et donnez-lui à manger le pain d’affliction et l’eau d’affliction, jusqu’à ce que je revienne en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Et Michée dit: Si jamais tu reviens en paix, l’ Éternel n’a point parlé par moi. Et il dit: Peuples, entendez-le tous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Et le roi d’Israël monta, et Josaphat, roi de Juda, à Ramoth de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Et le roi d’Israël dit à Josaphat: Je me déguiserai, et j’irai à la bataille; mais toi, revêts-toi de tes robes. Et le roi d’Israël se déguisa, et ils allèrent à la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Et le roi de Syrie commanda aux chefs de ses chars, disant: Ne combattez ni contre petit, ni contre grand, mais contre le roi d’Israël seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Et il arriva que, quand les chefs des chars virent Josaphat, ils dirent: C’est le roi d’Israël. Et ils l’entourèrent pour combattre contre lui. Et Josaphat cria, et l’ Éternel le secourut; et Dieu les porta [à s’éloigner] de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Et il arriva que, lorsque les chefs des chars virent que ce n’était pas le roi d’Israël, ils s’en revinrent de sa poursuite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Et un homme tira de l’arc à l’aventure et frappa le roi d’Israël entre les pièces d’attache et la cuirasse; et [Achab] dit au conducteur du char: Tourne ta main, et mène-moi hors de l’armée, car je suis blessé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Et la bataille se renforça ce jour-là, et le roi d’Israël se soutint sur [son] char, vis-à-vis des Syriens, jusqu’au soir; et il mourut vers le temps où le soleil se couchait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Et Josaphat, roi de Juda, s’en retourna dans sa maison, en paix, à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Et Jéhu, fils de Hanani, le voyant, sortit au-devant de lui, et dit au roi Josaphat: Aides-tu au méchant, et aimes-tu ceux qui haïssent l’ Éternel? À cause de cela il y a colère sur toi de la part de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Cependant il s’est trouvé de bonnes choses en toi, car tu as ôté du pays les ashères, et tu as appliqué ton cœur à rechercher Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Et Josaphat habita à Jérusalem. Et de nouveau il sortit parmi le peuple, depuis Beër-Shéba jusqu’à la montagne d’Éphraïm; et il les ramena à l’ Éternel, le Dieu de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Et il établit des juges dans le pays, dans toutes les villes fortes de Juda, de ville en ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Et il dit aux juges: Voyez ce que vous ferez; car ce n’est pas pour l’homme que vous jugerez, mais pour l’ Éternel, et il sera avec vous dans ce qui concerne le jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Et maintenant, que la frayeur de l’ Éternel soit sur vous: prenez garde en agissant; car auprès de l’ Éternel, notre Dieu, il n’y a point d’iniquité, ni acception de personnes, ni acceptation de présents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Et à Jérusalem aussi, Josaphat établit des lévites, et des sacrificateurs, et des chefs des pères d’Israël, pour le jugement de l’ Éternel et pour les procès. Et ils étaient revenus à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Et il leur commanda, disant: Vous agirez ainsi dans la crainte de l’ Éternel, avec fidélité et d’un cœur parfait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Et quelque procès qui vienne devant vous de la part de vos frères qui habitent dans leurs villes, entre sang et sang, entre loi et commandement, statuts et ordonnances, vous les avertirez afin qu’ils ne se rendent pas coupables envers l’ Éternel, et qu’il n’y ait pas de la colère contre vous et contre vos frères: vous agirez ainsi, et vous ne vous rendrez pas coupables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Et voici, Amaria, le principal sacrificateur, est [préposé] sur vous dans toutes les affaires de l’ Éternel, et Zebadia, fils d’Ismaël, prince de la maison de Juda, dans toutes les affaires du roi; et vous avez devant vous, pour officiers, les lévites. Fortifiez-vous, et agissez, et l’ Éternel sera avec l’[homme] de bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, '*Et il arriva, après ces choses, que les fils de Moab et les fils d’Ammon, et avec eux une partie des Maonites, vinrent contre Josaphat pour faire la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Et on vint et on rapporta à Josaphat, en disant: Il est venu contre toi une grande multitude, de l’autre côté de la mer, de la Syrie; et voici, ils sont à Hatsatson-Thamar, qui est En-Guédi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Et Josaphat craignit, et tourna sa face pour rechercher l’ Éternel, et proclama un jeûne par tout Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Et Juda s’assembla pour chercher [secours] de la part de l’ Éternel: et on vint aussi de toutes les villes de Juda pour rechercher l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Et Josaphat se tint debout dans la congrégation de Juda et de Jérusalem, dans la maison de l’ Éternel, devant le nouveau parvis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'et il dit: Éternel, Dieu de nos pères! n’es-tu pas le Dieu qui es dans les cieux, et [n’est-ce pas] toi qui domines sur tous les royaumes des nations? Et en ta main est la puissance et la force, et nul ne peut te résister.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'N’est-ce pas toi, notre Dieu, qui as dépossédé les habitants de ce pays devant ton peuple Israël, et qui l’as donné à toujours à la semence d’Abraham, ton ami?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Et ils y ont habité, et t’y ont bâti un sanctuaire pour ton nom, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'S’il nous arrive du mal, épée, jugement, ou peste, ou famine, et que nous nous tenions devant cette maison et devant toi, car ton nom est dans cette maison, et que nous criions à toi à cause de notre angoisse, tu écouteras, et tu sauveras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Et maintenant, voici, les fils d’Ammon et de Moab, et ceux de la montagne de Séhir, chez lesquels tu ne permis pas à Israël d’entrer lorsqu’ils venaient du pays d’Égypte (car ils se détournèrent d’eux, et ne les détruisirent pas),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'les voici qui nous récompensent en venant pour nous chasser de ton héritage que tu nous as fait posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Ô notre Dieu, ne les jugeras-tu pas? car il n’y a point de force en nous devant cette grande multitude qui vient contre nous, et nous ne savons ce que nous devons faire, mais nos yeux sont sur toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Et tout Juda se tenait devant l’ Éternel, avec leurs petits enfants, leurs femmes et leurs fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Et l’Esprit de l’ Éternel vint, au milieu de la congrégation, sur Jakhaziel, fils de Zacharie, fils de Benaïa, fils de Jehiel, fils de Matthania, lévite d’entre les fils d’Asaph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Et il dit: Soyez attentifs, vous, tout Juda, et vous, habitants de Jérusalem, et toi, roi Josaphat. Ainsi vous dit l’ Éternel: Ne craignez point, et ne soyez point effrayés à cause de cette grande multitude; car cette guerre n’est pas la vôtre, mais celle de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Demain, descendez contre eux: voici, ils vont monter par la montée de Tsits, et vous les trouverez au bout de la vallée, devant le désert de Jeruel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Ce n’est point à vous de combattre en cette affaire; présentez-vous, [et] tenez-vous là, et voyez la délivrance de l’ Éternel [qui est] avec vous. Juda et Jérusalem, ne craignez pas et ne soyez pas effrayés; demain, sortez à leur rencontre, et l’ Éternel sera avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Et Josaphat s’inclina le visage contre terre, et tout Juda et les habitants de Jérusalem tombèrent [sur leurs faces] devant l’ Éternel, pour adorer l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Et les lévites d’entre les fils des Kehathites et d’entre les fils des Corites se levèrent pour louer l’ Éternel, le Dieu d’Israël, à grande et haute voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Et ils se levèrent de bonne heure le matin, et sortirent vers le désert de Thekoa; et comme ils sortaient, Josaphat se tint là et dit: Écoutez-moi, Juda, et vous, habitants de Jérusalem: Croyez à l’ Éternel, votre Dieu, et vous serez affermis; croyez ses prophètes, et vous prospérerez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Et il tint conseil avec le peuple, et il établit des chantres pour l’ Éternel, et ceux qui louaient dans la sainte magnificence, et disaient, en sortant devant les troupes équipées: Célébrez l’ Éternel, car sa bonté [demeure] à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Et au moment où ils commençaient le chant de triomphe et la louange, l’ Éternel mit des embûches contre les fils d’Ammon [et] de Moab et [ceux de] la montagne de Séhir, qui venaient contre Juda, et ils furent battus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Et les fils d’Ammon et de Moab se levèrent contre les habitants de la montagne de Séhir, pour les exterminer et les détruire; et quand ils en eurent fini avec les habitants de Séhir, ils s’aidèrent l’un l’autre à se détruire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Et Juda vint sur un lieu élevé [d’où l’on voyait] le désert; et ils regardèrent du côté de la multitude, et voici, c’étaient des cadavres étendus par terre, et personne n’était échappé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Et Josaphat et son peuple vinrent pour piller leur butin, et ils trouvèrent parmi eux en abondance des richesses et des cadavres, et des objets précieux, et ils en ramassèrent à ne pouvoir les porter; et ils furent trois jours à piller le butin, car il était abondant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Et le quatrième jour, ils s’assemblèrent dans la vallée de Beraca, car là ils bénirent l’ Éternel; c’est pourquoi on a appelé ce lieu-là du nom de vallée de Beraca, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Et tous les hommes de Juda et de Jérusalem, et Josaphat à leur tête, s’en retournèrent, revenant à Jérusalem avec joie; car l’ Éternel les avait réjouis au sujet de leurs ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Et ils vinrent à Jérusalem, à la maison de l’ Éternel, avec des luths et des harpes et des trompettes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Et la frayeur de Dieu fut sur tous les royaumes des pays, quand ils entendirent que l’ Éternel combattait contre les ennemis d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Et le royaume de Josaphat fut tranquille, et son Dieu lui donna du repos tout à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Et Josaphat régna sur Juda. Il était âgé de 35 ans lorsqu’il commença de régner, et il régna 25 ans à Jérusalem; et le nom de sa mère était Azuba, fille de Shilkhi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Et il marcha dans la voie d’Asa, son père, et ne s’en détourna pas, faisant ce qui est droit aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Seulement, les hauts lieux ne furent pas ôtés, et le peuple n’avait pas encore disposé son cœur à [rechercher] le Dieu de ses pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Et le reste des actes de Josaphat, les premiers et les derniers, voici, ils sont écrits dans les paroles de Jéhu, fils de Hanani, lesquelles sont insérées dans le livre des rois d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Et après cela, Josaphat, roi de Juda, se lia avec Achazia, roi d’Israël, qui agissait méchamment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Et il s’associa avec lui pour construire des navires pour aller à Tarsis; et ils construisirent les navires à Étsion-Guéber.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Et Éliézer, fils de Dodava, de Marésha, prophétisa contre Josaphat, disant: Parce que tu t’es lié avec Achazia, l’ Éternel a détruit tes œuvres: et les navires furent brisés, et ne purent aller à Tarsis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, '*Et Josaphat s’endormit avec ses pères, et il fut enterré avec ses pères dans la ville de David. Et Joram, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Et il avait des frères, fils de Josaphat: Azaria, et Jekhiel, et Zacharie, et Azaria, et Micaël, et Shephatia; tous ceux-là étaient fils de Josaphat, roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Et leur père leur avait fait de grands dons en argent et en or, et en choses précieuses, avec des villes fortes en Juda; mais il avait donné le royaume à Joram, parce qu’il était le premier-né.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Et Joram s’établit sur le royaume de son père, et s’y fortifia, et tua par l’épée tous ses frères, et quelques-uns aussi des chefs d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Joram était âgé de 32 ans lorsqu’il commença de régner; et il régna huit ans à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Et il marcha dans la voie des rois d’Israël, selon ce que faisait la maison d’Achab, car il avait pour femme une fille d’Achab; et il fit ce qui est mauvais aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Mais l’ Éternel ne voulut point détruire la maison de David, à cause de l’alliance qu’il avait faite avec David et selon ce qu’il avait dit, qu’il lui donnerait une lampe, à lui et à ses fils, à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'En ses jours, Édom se révolta de dessous la main de Juda, et ils établirent un roi sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Et Joram se mit en marche avec ses chefs, et tous les chars avec lui; et il se leva de nuit, et frappa Édom, qui l’avait entouré, et les chefs des chars.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Mais Édom se révolta de dessous la main de Juda, jusqu’à ce jour. Alors, dans ce même temps, Libna se révolta de dessous sa main, car il avait abandonné l’ Éternel, le Dieu de ses pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Il fit aussi des hauts lieux dans les montagnes de Juda, et fit que les habitants de Jérusalem se prostituèrent, et il y poussa Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Et il vint à lui un écrit d’Élie, le prophète, disant: Ainsi dit l’ Éternel, le Dieu de David, ton père: Parce que tu n’as pas marché dans les voies de Josaphat, ton père, ni dans les voies d’Asa, roi de Juda,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'mais que tu as marché dans la voie des rois d’Israël, et que tu as fait que ceux de Juda et les habitants de Jérusalem se sont prostitués selon les prostitutions de la maison d’Achab, et aussi parce que tu as tué tes frères, la maison de ton père, qui étaient meilleurs que toi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, '– voici, l’ Éternel te frappera d’un grand coup dans ton peuple et dans tes fils et dans tes femmes et dans tous tes biens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'et toi-même de grandes maladies, d’une maladie d’entrailles, jusqu’à ce que tes entrailles sortent par l’effet de la maladie, jour après jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Et l’ Éternel réveilla contre Joram l’esprit des Philistins et des Arabes qui sont à côté des Éthiopiens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'et ils montèrent contre Juda, et en forcèrent l’entrée, et emmenèrent tous les biens qui furent trouvés dans la maison du roi, et aussi ses fils et ses femmes; et il ne lui resta aucun fils, sinon Joakhaz, le plus petit de ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Et après tout cela, l’ Éternel le frappa dans ses entrailles d’une maladie incurable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Et il arriva, de jour en jour, et au temps où la seconde année tirait à sa fin, que ses entrailles sortirent par l’effet de la maladie, et il mourut dans de cruelles souffrances; et son peuple ne fit pas brûler pour lui [des aromates], comme on en avait fait brûler pour ses pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Il était âgé de 32 ans lorsqu’il commença de régner; et il régna huit ans à Jérusalem; et il s’en alla sans être regretté; et on l’enterra dans la ville de David, mais non dans les sépulcres des rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Et les habitants de Jérusalem établirent roi à sa place Achazia, son plus jeune fils, car la bande qui était venue au camp avec les Arabes avait tué tous ceux qui étaient plus âgés que lui. Et Achazia, fils de Joram, roi de Juda, régna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Achazia était âgé de 22 ans lorsqu’il commença de régner; et il régna un an à Jérusalem; et le nom de sa mère était Athalie, fille d’Omri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Lui aussi marcha dans les voies de la maison d’Achab; car sa mère était sa conseillère à mal faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, comme la maison d’Achab; car ils furent ses conseillers après la mort de son père, pour sa ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Ce fut aussi selon leur conseil qu’il marcha, et qu’il alla avec Joram, fils d’Achab, roi d’Israël, à la guerre contre Hazaël, roi de Syrie, à Ramoth de Galaad. Et les Syriens blessèrent Joram.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Et il s’en retourna pour se faire guérir à Jizreël, à cause des blessures qu’il avait reçues à Rama en combattant contre Hazaël, roi de Syrie; et Achazia, fils de Joram, roi de Juda, descendit à Jizreël pour voir Joram, fils d’Achab, parce qu’il était malade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Et ce fut, de la part de Dieu, la ruine complète d’Achazia d’être venu vers Joram. Et lorsqu’il fut arrivé, il sortit avec Joram contre Jéhu, fils de Nimshi, que l’ Éternel avait oint pour retrancher la maison d’Achab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Et il arriva que, comme Jéhu faisait justice de la maison d’Achab, il trouva les princes de Juda et les fils des frères d’Achazia, qui servaient Achazia; et il les tua.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Et il chercha Achazia qui s’était caché à Samarie; et on le prit, et on l’amena à Jéhu, et on le fit mourir. Et ils l’enterrèrent; car ils dirent: Il est fils de Josaphat, qui rechercha l’ Éternel de tout son cœur. Et il n’y eut plus personne de la maison d’Achazia qui puisse conserver le pouvoir du royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Or Athalie, mère d’Achazia, vit que son fils était mort, et elle se leva et extermina toute la semence royale de la maison de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Mais Jehoshabhath, fille du roi, prit Joas, fils d’Achazia, et le déroba du milieu des fils du roi qu’on mettait à mort, et le mit, lui et sa nourrice, dans la chambre à coucher. Ainsi Jehoshabhath, fille du roi Joram, femme de Jehoïada, le sacrificateur, le cacha de devant Athalie, car elle était sœur d’Achazia; et [Athalie] ne le mit pas à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Et il fut caché six ans auprès d’eux, dans la maison de Dieu. Et Athalie régna sur le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Et la septième année, Jehoïada se fortifia, et fit un pacte avec les chefs de centaines, Azaria, fils de Jerokham, et Ismaël, fils de Jokhanan, et Azaria, fils d’Obed, et Maascéïa, fils d’Adaïa, et Élishaphat, fils de Zicri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Et ils firent le tour de Juda, et assemblèrent les lévites de toutes les villes de Juda, et les chefs des pères d’Israël; et ils vinrent à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Et toute la congrégation fit alliance avec le roi dans la maison de Dieu; et [Jehoïada] leur dit: Voici, le fils du roi régnera, selon ce que l’ Éternel a dit touchant les fils de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'C’est ici ce que vous ferez: un tiers d’entre vous qui entrez le [jour du] sabbat, sacrificateurs et lévites, sera chargé de la garde des seuils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'et un tiers sera dans la maison du roi; et un tiers à la porte de Jesod; et tout le peuple sera dans les parvis de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Et que personne n’entre dans la maison de l’ Éternel, sauf les sacrificateurs et les lévites qui feront le service: eux, ils entreront, car ils sont saints; et tout le peuple fera l’acquit de la charge de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Et les lévites entoureront le roi de tous côtés, chacun ses armes à la main; et celui qui entrera dans la maison sera mis à mort; et soyez avec le roi quand il entrera et quand il sortira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Et les lévites et tout Juda firent selon tout ce que Jehoïada, le sacrificateur, avait commandé; et ils prirent chacun ses hommes, ceux qui entraient le [jour du] sabbat et ceux qui sortaient le [jour du] sabbat; car Jehoïada, le sacrificateur, n’avait pas renvoyé les classes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Et Jehoïada, le sacrificateur, donna aux chefs de centaines les lances, et les écus, et les boucliers, qui avaient appartenu au roi David, et qui étaient dans la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Et il fit tenir là tout le peuple, chacun sa javeline à la main, depuis le côté droit de la maison jusqu’au côté gauche de la maison, vers l’autel et vers la maison, auprès du roi, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Et ils firent sortir le fils du roi, et mirent sur lui la couronne et le témoignage; et ils le firent roi; et Jehoïada et ses fils l’oignirent, et dirent: Vive le roi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Et Athalie entendit le cri du peuple qui courait et acclamait le roi, et elle entra vers le peuple dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Et elle regarda, et voici, le roi se tenait sur son estrade, à l’entrée, et les chefs et les trompettes étaient auprès du roi, et tout le peuple du pays se réjouissait et sonnait des trompettes, et les chantres [étaient là] avec des instruments de musique, et ceux qui enseignaient à louer [Dieu]. Et Athalie déchira ses vêtements, et dit: Conspiration! Conspiration!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Et Jehoïada, le sacrificateur, fit sortir les chefs de centaines qui étaient préposés sur l’armée, et leur dit: Faites-la sortir en dehors des rangs, et que celui qui la suivra soit mis à mort par l’épée; car le sacrificateur dit: Ne la mettez pas à mort dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Et ils lui firent place; et elle alla par l’entrée de la porte des chevaux dans la maison du roi, et là ils la mirent à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Et Jehoïada fit une alliance entre lui et tout le peuple et le roi, qu’ils seraient le peuple de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Et tout le peuple entra dans la maison de Baal, et ils la démolirent; et ils brisèrent ses autels et ses images, et tuèrent devant les autels Matthan, sacrificateur de Baal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Et Jehoïada mit les charges de la maison de l’ Éternel entre les mains des sacrificateurs lévites, que David avait établis par classes sur la maison de l’ Éternel pour offrir les holocaustes à l’ Éternel, comme il est écrit dans la loi de Moïse, avec joie et avec des cantiques, selon les directions de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Et il plaça les portiers aux portes de la maison de l’ Éternel, afin qu’il n’y entre aucune personne impure en quoi que ce soit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Et il prit les chefs de centaines, et les nobles, et ceux qui avaient autorité sur le peuple, et tout le peuple du pays, et il fit descendre le roi de la maison de l’ Éternel, et ils entrèrent dans la maison du roi par la porte supérieure; et ils firent asseoir le roi sur le trône du royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Et tout le peuple du pays se réjouit, et la ville fut tranquille: et ils avaient mis à mort Athalie par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, '*Joas était âgé de sept ans lorsqu’il commença de régner; et il régna 40 ans à Jérusalem; et le nom de sa mère était Tsibia, de Beër-Shéba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Et Joas fit ce qui est droit aux yeux de l’ Éternel, tous les jours de Jehoïada, le sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Et Jehoïada prit deux femmes pour [Joas], et il engendra des fils et des filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Et il arriva, après cela, que Joas eut à cœur de restaurer la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Et il assembla les sacrificateurs et les lévites, et leur dit: Allez par les villes de Juda, et recueillez de l’argent de tout Israël, pour réparer la maison de votre Dieu, d’année en année, et hâtez cette affaire. Mais les lévites ne la hâtèrent point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Et le roi appela Jehoïada, le chef, et lui dit: Pourquoi n’as-tu pas exigé des lévites qu’ils apportent, de Juda et de Jérusalem, le tribut de Moïse, serviteur de l’ Éternel, [imposé à] la congrégation d’Israël pour la tente du témoignage?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Car Athalie, cette méchante femme, [et] ses fils, avaient dévasté la maison de Dieu, et, toutes les choses saintes de la maison de l’ Éternel, ils les avaient aussi employées pour les Baals.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Et le roi commanda, et on fit un coffre, et on le mit à la porte de la maison de l’ Éternel, en dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Et on publia dans Juda et dans Jérusalem qu’on apporte à l’ Éternel le tribut de Moïse, serviteur de Dieu, [imposé] à Israël, dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Et tous les princes et tout le peuple s’en réjouirent; et ils apportèrent [l’argent] et le jetèrent dans le coffre, jusqu’à ce qu’on ait fini.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Et il arrivait que, lorsque c’était le temps d’apporter le coffre au contrôle du roi, par la main des lévites, et qu’on voyait qu’il y avait beaucoup d’argent, le secrétaire du roi et l’officier du principal sacrificateur venaient et vidaient le coffre; et ils le reportaient et le remettaient à sa place. Ils faisaient ainsi jour par jour, et on recueillit de l’argent en abondance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Et le roi et Jehoïada le donnaient à ceux qui faisaient l’ouvrage du service de la maison de l’ Éternel, et ceux-ci prenaient à gage des tailleurs de pierres et des charpentiers pour restaurer la maison de l’ Éternel, et aussi des ouvriers en fer et en airain pour réparer la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Et ceux qui faisaient l’ouvrage travaillèrent, et l’œuvre de restauration se fit par leur moyen, et ils rétablirent la maison de Dieu en son état, et la consolidèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Et quand ils eurent achevé, ils apportèrent devant le roi et devant Jehoïada le reste de l’argent; et on en fit des ustensiles pour la maison de l’ Éternel, des ustensiles pour le service et pour les holocaustes, et des coupes, et des ustensiles d’or et d’argent. Et on offrit des holocaustes dans la maison de l’ Éternel continuellement, tous les jours de Jehoïada.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Et Jehoïada devint vieux et rassasié de jours, et il mourut. Il était âgé de 130 ans quand il mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Et on l’enterra dans la ville de David avec les rois, car il avait fait du bien en Israël, et pour Dieu et pour sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Et après la mort de Jehoïada, les chefs de Juda vinrent et s’inclinèrent devant le roi; alors le roi les écouta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Et ils abandonnèrent la maison de l’ Éternel, le Dieu de leurs pères, et servirent les ashères et les idoles; et il y eut de la colère contre Juda et contre Jérusalem, parce qu’ils s’étaient rendus coupables en cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Et l’ Éternel envoya parmi eux, pour les ramener à lui, des prophètes qui témoignèrent contre eux; mais ils n’écoutèrent point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Et l’Esprit de Dieu revêtit Zacharie, fils de Jehoïada, le sacrificateur, et il se tint debout au-dessus du peuple, et leur dit: Ainsi dit Dieu: Pourquoi transgressez-vous les commandements de l’ Éternel? Vous ne réussirez point; car vous avez abandonné l’ Éternel, et il vous abandonnera aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Et ils conspirèrent contre lui, et le lapidèrent avec des pierres par l’ordre du roi, dans le parvis de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Et le roi Joas ne se souvint pas de la bonté dont Jehoïada, père de Zacharie, avait usé envers lui, et il tua son fils. Et comme il mourait, il dit: Que l’ Éternel regarde et redemande!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Et il arriva, quand l’année fut révolue, que l’armée de Syrie monta contre Joas, et entra en Juda et à Jérusalem; et ils détruisirent d’entre le peuple tous les chefs du peuple, et envoyèrent toutes leurs dépouilles au roi, à Damas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Car l’armée de Syrie vint avec un petit nombre d’hommes, et l’ Éternel livra en leurs mains une très grande armée, parce qu’ils avaient abandonné l’ Éternel, le Dieu de leurs pères. Ainsi [les Syriens] firent justice de Joas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Et quand ils l’eurent quitté, (or ils l’avaient laissé dans de grandes maladies,) ses serviteurs conspirèrent contre lui, à cause du sang des fils de Jehoïada, le sacrificateur; et ils le tuèrent sur son lit, et il mourut; et on l’enterra dans la ville de David, mais on ne l’enterra pas dans les sépulcres des rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Et ce sont ici ceux qui conspirèrent contre lui: Zabad, fils de Shimhath, l’Ammonite, et Jozabad, fils de Shimrith, la Moabite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Et quant à ses fils, et à la grandeur du tribut qui lui fut imposé, et aux constructions de la maison de Dieu, voici, ces choses sont écrites dans les commentaires du livre des rois. Et Amatsia, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, '*Amatsia était âgé de 25 ans lorsqu’il commença de régner; et il régna 29 ans à Jérusalem; et le nom de sa mère était Jehoaddan, de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Et il fit ce qui est droit aux yeux de l’ Éternel, non pas toutefois d’un cœur parfait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Et il arriva que, quand la royauté fut affermie entre ses mains, il fit mourir ses serviteurs qui avaient frappé le roi son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Mais leurs fils, il ne les mit pas à mort, car [il fit] selon ce qui est écrit dans la loi, dans le livre de Moïse, où l’ Éternel a commandé, disant: Les pères ne mourront pas pour les fils, et les fils ne mourront pas pour les pères; car chacun mourra pour son péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Et Amatsia rassembla Juda, et il les rangea selon [leurs] maisons de pères, selon les chefs de milliers, et selon les chefs de centaines, pour tout Juda et Benjamin; et il fit le recensement de ceux qui étaient âgés de 20 ans et au-dessus: et il trouva 300 000 hommes d’élite, propres pour la guerre, portant la pique et le bouclier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Et il prit à sa solde, d’Israël, 100 000 hommes forts et vaillants, pour 100 talents d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Et un homme de Dieu vint à lui, disant: Ô roi! que l’armée d’Israël ne marche pas avec toi; car l’ Éternel n’est pas avec Israël, avec tous les fils d’Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Que si tu vas, fais-le, fortifie-toi pour la bataille; Dieu te fera tomber devant l’ennemi; car c’est en Dieu qu’est le pouvoir pour aider et pour faire tomber.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Et Amatsia dit à l’homme de Dieu: Mais que faire quant aux 100 talents que j’ai donnés à la troupe d’Israël? Et l’homme de Dieu dit: Il appartient à l’ Éternel de te donner beaucoup plus que cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Et Amatsia sépara la troupe qui lui était venue d’Éphraïm, afin qu’ils s’en aillent chez eux; et leur colère s’embrasa beaucoup contre Juda, et ils s’en retournèrent chez eux dans une ardente colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Et Amatsia se fortifia, et conduisit son peuple, et s’en alla à la vallée du Sel, et frappa 10 000 [hommes] des fils de Séhir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Et les fils de Juda emmenèrent captifs 10 000 hommes, vivants, et les menèrent sur le sommet d’un rocher, et les précipitèrent du sommet du rocher, et ils furent tous mis en pièces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Mais ceux de la troupe qu’Amatsia avait renvoyée, afin qu’elle n’aille pas à la guerre avec lui, tombèrent sur les villes de Juda, depuis Samarie jusqu’à Beth-Horon, et y frappèrent 3 000 [hommes] et enlevèrent un grand butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Et il arriva, après qu’Amatsia fut revenu de la défaite des Édomites, qu’il apporta les dieux des fils de Séhir, et se les établit pour dieux, et se prosterna devant eux et leur brûla de l’encens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Et la colère de l’ Éternel s’embrasa contre Amatsia, et il lui envoya un prophète, et il lui dit: Pourquoi recherches-tu les dieux d’un peuple qui n’ont pas délivré leur peuple de ta main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Et il arriva, comme il parlait au roi, que celui-ci lui dit: Est-ce qu’on t’a fait conseiller du roi? Désiste-toi. Pourquoi te frapperait-on? Et le prophète se désista, et dit: Je sais que Dieu a résolu de te perdre, parce que tu as fait cela, et que tu n’as pas écouté mon conseil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Et Amatsia, roi de Juda, prit conseil, et envoya vers Joas, fils de Joakhaz, fils de Jéhu, roi d’Israël, disant: Viens, voyons-nous face à face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Et Joas, roi d’Israël, envoya vers Amatsia, roi de Juda, disant: L’épine qui est au Liban a envoyé au cèdre qui est au Liban, disant: Donne ta fille pour femme à mon fils. Et une bête des champs qui est au Liban a passé, et a foulé l’épine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Tu dis: Voici, tu as frappé Édom! et ton cœur s’est élevé pour que tu te glorifies. Maintenant, reste dans ta maison; pourquoi te mettrais-tu aux prises avec le malheur et tomberais-tu, toi, et Juda avec toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Et Amatsia n’écouta pas; car cela venait de la part de Dieu, afin de les livrer en la main [de leurs ennemis], parce qu’ils avaient recherché les dieux d’Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Et Joas, roi d’Israël, monta; et ils se virent face à face, lui et Amatsia, roi de Juda, à Beth-Shémesh, qui est à Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Et Juda fut battu devant Israël; et ils s’enfuirent, chacun dans sa tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Et Joas, roi d’Israël, prit Amatsia, roi de Juda, fils de Joas, fils de Joakhaz, à Beth-Shémesh, et l’amena à Jérusalem; et il abattit la muraille de Jérusalem depuis la porte d’Éphraïm jusqu’à la porte du coin, 400 coudées,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'et [prit] tout l’or et l’argent, et tous les ustensiles qui furent trouvés dans la maison de Dieu, sous la main d’Obed-Édom, et les trésors de la maison du roi, et des otages; et il s’en retourna à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Et Amatsia, fils de Joas, roi de Juda, vécut 15 ans après la mort de Joas, fils de Joakhaz, roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Et le reste des actes d’Amatsia, les premiers et les derniers, voici, cela n’est-il pas écrit dans le livre des rois de Juda et d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Et, depuis le temps où Amatsia se fut détourné de l’ Éternel, on fit une conspiration contre lui à Jérusalem, et il s’enfuit à Lakis; et on envoya après lui à Lakis, et là on le mit à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Et on le transporta sur des chevaux, et on l’enterra auprès de ses pères dans la ville de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, '*Et tout le peuple de Juda prit Ozias, qui était âgé de 16 ans, et ils le firent roi à la place de son père Amatsia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Ce fut lui qui bâtit Éloth, et la recouvra pour Juda, après que le roi se fut endormi avec ses pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Ozias était âgé de 16 ans lorsqu’il commença de régner; et il régna 52 ans à Jérusalem; et le nom de sa mère était Jecolia, de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Et il fit ce qui est droit aux yeux de l’ Éternel, selon tout ce qu’avait fait Amatsia, son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Et il rechercha Dieu pendant les jours de Zacharie, qui avait l’intelligence des visions de Dieu; et pendant les jours où il rechercha l’ Éternel, Dieu le fit prospérer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Et il sortit, et fit la guerre contre les Philistins, et abattit la muraille de Gath, et la muraille de Jabné, et la muraille d’Asdod; et il bâtit des villes autour d’Asdod et au milieu des Philistins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Et Dieu l’aida contre les Philistins, et contre les Arabes qui habitaient à Gur-Baal, et contre les Maonites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Et les Ammonites apportèrent des présents à Ozias: et son renom parvint jusqu’à l’entrée de l’Égypte, car il était devenu extrêmement fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Et Ozias bâtit des tours à Jérusalem, sur la porte du coin, et sur la porte de la vallée, et sur l’angle, et les fortifia;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'et il bâtit des tours dans le désert, et creusa beaucoup de puits, car il avait beaucoup de bétail dans le pays plat et sur le plateau, [et] des laboureurs et des vignerons dans les montagnes et en Carmel; car il aimait la campagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Et Ozias avait une armée pour faire la guerre, allant au combat par bandes, selon le chiffre de leur recensement [fait] par la main de Jehiel, le scribe, et de Maascéïa, l’intendant, sous la main de Hanania, l’un des chefs du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Tout le nombre des chefs des pères, des hommes forts et vaillants, était de 2 600.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Et il y avait sous leur main une armée de 307 500 [hommes] pour faire la guerre avec une force puissante, afin d’aider le roi contre l’ennemi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Et Ozias leur prépara, pour toute l’armée, des boucliers, et des piques, et des casques, et des cuirasses, et des arcs, et jusqu’à des pierres de fronde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Et il fit à Jérusalem des machines, inventées par des ingénieurs, pour être [placées] sur les tours et sur le haut des remparts, pour lancer des flèches et de grosses pierres. Et son renom s’étendit au loin; car il fut merveilleusement aidé jusqu’à ce qu’il devint fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Mais quand il fut devenu fort, son cœur s’éleva jusqu’à le perdre, et il pécha contre l’ Éternel, son Dieu, et entra dans le temple de l’ Éternel pour faire fumer [l’encens] sur l’autel de l’encens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Et Azaria, le sacrificateur, entra après lui, et avec lui les sacrificateurs de l’ Éternel, 80 hommes vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Et ils s’opposèrent au roi Ozias, et lui dirent: Ce n’est pas à toi, Ozias, de faire fumer l’encens à l’ Éternel, mais aux sacrificateurs, fils d’Aaron, qui sont sanctifiés pour faire fumer l’encens. Sors du sanctuaire; car tu as péché, et [cela] ne sera pas à ta gloire de la part de l’ Éternel Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Et Ozias s’emporta; et il avait en sa main un encensoir pour faire fumer l’encens; et comme il s’emportait contre les sacrificateurs, la lèpre éclata sur son front devant les sacrificateurs, dans la maison de l’ Éternel, auprès de l’autel de l’encens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Et Azaria, le principal sacrificateur, et tous les sacrificateurs, le regardèrent; et voici, il était lépreux au front; et ils le chassèrent de là; et lui aussi se hâta de sortir, car l’ Éternel l’avait frappé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Et le roi Ozias fut lépreux jusqu’au jour de sa mort; et il habita, lépreux, dans une maison d’isolement, car il fut exclu de la maison de l’ Éternel; et Jotham, son fils, fut chef de la maison du roi, jugeant le peuple du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Et le reste des actes d’Ozias, les premiers et les derniers, Ésaïe, fils d’Amots, le prophète, les a écrits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Et Ozias s’endormit avec ses pères, et on l’enterra auprès de ses pères, dans le champ de la sépulture des rois; car on dit: Il est lépreux. Et Jotham, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, '*Jotham était âgé de 25 ans lorsqu’il commença de régner; et il régna 16 ans à Jérusalem; et le nom de sa mère était Jerusha, fille de Tsadok.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Et il fit ce qui est droit aux yeux de l’ Éternel, selon tout ce qu’avait fait Ozias, son père; seulement il n’entra pas dans le temple de l’ Éternel; et le peuple se corrompait encore.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Ce fut lui qui bâtit la porte supérieure de la maison de l’ Éternel; et il fit beaucoup de constructions sur la muraille d’Ophel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Et il bâtit des villes dans la montagne de Juda, et il bâtit dans les forêts des châteaux et des tours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Et il fit la guerre contre le roi des fils d’Ammon, et l’emporta sur eux; et les fils d’Ammon lui donnèrent cette année-là 100 talents d’argent, et 10 000 cors de froment, et 10 000 d’orge; les fils d’Ammon lui payèrent cela aussi la seconde année et la troisième.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Et Jotham devint fort, car il régla ses voies devant l’ Éternel, son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Et le reste des actes de Jotham, et toutes ses guerres, et ses voies, voici, ces choses sont écrites dans le livre des rois d’Israël et de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Il était âgé de 25 ans quand il commença de régner; et il régna 16 ans à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Et Jotham s’endormit avec ses pères, et on l’enterra dans la ville de David; et Achaz, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, '*Achaz était âgé de 20 ans lorsqu’il commença de régner; et il régna 16 ans à Jérusalem. Et il ne fit pas ce qui est droit aux yeux de l’ Éternel, comme [avait fait] David, son père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'mais il marcha dans les voies des rois d’Israël, et même il fit des images de fonte pour les Baals;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'et il fit fumer [de l’encens] dans la vallée du fils de Hinnom, et brûla ses fils par le feu, selon les abominations des nations que l’ Éternel avait dépossédées devant les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Et il sacrifiait et faisait fumer de l’encens sur les hauts lieux, et sur les collines, et sous tout arbre vert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Et l’ Éternel, son Dieu, le livra en la main du roi de Syrie; et [les Syriens] le frappèrent, et lui prirent un grand nombre de captifs, et les amenèrent à Damas. Et il fut aussi livré en la main du roi d’Israël, qui lui infligea une grande défaite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Et Pékakh, fils de Remalia, tua en un seul jour 120 000 [hommes] de Juda, tous hommes vaillants; car ils avaient abandonné l’ Éternel, le Dieu de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Et Zicri, un homme fort d’Éphraïm, tua Maascéïa, fils du roi, et Azrikam, prince de la maison [du roi], et Elkana, le second après le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Et les fils d’Israël emmenèrent d’entre leurs frères 200 000 captifs, femmes, fils, et filles; ils leur enlevèrent aussi un grand butin, et amenèrent le butin à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Et il y avait là un prophète de l’ Éternel, nommé Oded, et il sortit au-devant de l’armée qui revenait à Samarie, et leur dit: Voici, dans son courroux contre [ceux de] Juda, l’ Éternel, le Dieu de vos pères, les a livrés entre vos mains, et vous les avez tués avec une rage qui est parvenue jusqu’aux cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Et maintenant, vous pensez vous assujettir comme serviteurs et servantes les fils de Juda et de Jérusalem! N’avez-vous pas avec vous, ne concernant que vous, des péchés contre l’ Éternel, votre Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Et maintenant, écoutez-moi: renvoyez les captifs que vous avez emmenés captifs d’entre vos frères; car l’ardeur de la colère de l’ Éternel est sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Et des hommes d’entre les chefs des fils d’Éphraïm, Azaria, fils de Jokhanan, Bérékia, fils de Meshillémoth, et Ézéchias, fils de Shallum, et Amasça, fils de Hadlaï, se levèrent contre ceux qui venaient de l’armée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'et leur dirent: Vous ne ferez point entrer ici les captifs, car, pour notre culpabilité devant l’ Éternel, vous pensez ajouter à nos péchés et à notre crime; car notre crime est grand, et l’ardeur de la colère est sur Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Et les gens armés abandonnèrent les captifs et le butin devant les chefs et devant toute la congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Et les hommes qui ont été nommés par [leurs] noms se levèrent et prirent les captifs, et vêtirent du butin tous ceux d’entre eux qui étaient nus; et ils les vêtirent et les chaussèrent, et leur donnèrent à manger et à boire, et les oignirent; et ils conduisirent sur des ânes tous ceux qui étaient faibles, et les amenèrent à Jéricho, la ville des palmiers, auprès de leurs frères; et ils s’en retournèrent à Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'En ce temps-là, le roi Achaz envoya vers les rois d’Assyrie pour qu’ils l’aident.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Et les Édomites vinrent de nouveau, et frappèrent Juda, et emmenèrent des captifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Et les Philistins se jetèrent sur les villes du pays plat et du midi de Juda, et prirent Beth-Shémesh, et Ajalon, et Guedéroth, et Soco et les villages de son ressort, et Thimna et les villages de son ressort, et Guimzo et les villages de son ressort; et ils y habitèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Car l’ Éternel abaissa Juda, à cause d’Achaz, roi d’Israël, car il avait rejeté tout frein en Juda, et avait beaucoup péché contre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Et Tilgath-Pilnéser, roi d’Assyrie, vint contre lui, et le traita en ennemi, et ne le fortifia pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Car Achaz dépouilla la maison de l’ Éternel et la maison du roi et des chefs, et donna [les dépouilles] au roi d’Assyrie, mais il ne lui fut d’aucune aide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Et au temps de sa détresse, il ajouta aussi à son péché contre l’ Éternel, lui, le roi Achaz;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'et il sacrifia aux dieux de Damas qui l’avaient frappé, et il dit: Puisque les dieux des rois de Syrie leur sont en aide, je leur sacrifierai, et ils me seront en aide. Et ils furent sa ruine et celle de tout Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Et Achaz rassembla les ustensiles de la maison de Dieu, et mit en pièces les ustensiles de la maison de Dieu; et il ferma les portes de la maison de l’ Éternel, et se fit des autels dans tous les coins de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Et dans chacune des villes de Juda il fit des hauts lieux pour brûler de l’encens à d’autres dieux; et il provoqua à colère l’ Éternel, le Dieu de ses pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Et le reste de ses actes, et toutes ses voies, les premières et les dernières, voici, ils sont écrits dans le livre des rois de Juda et d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Et Achaz s’endormit avec ses pères, et on l’enterra dans la ville, à Jérusalem; mais on ne le mit pas dans les sépulcres des rois d’Israël. Et Ézéchias, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, '*Ézéchias commença de régner étant âgé de 25 ans; et il régna 29 ans à Jérusalem; et le nom de sa mère était Abija, fille de Zacharie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Et il fit ce qui est droit aux yeux de l’ Éternel, selon tout ce qu’avait fait David, son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'La première année de son règne, au premier mois, il ouvrit les portes de la maison de l’ Éternel, et les répara.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Et il fit venir les sacrificateurs et les lévites, et les assembla sur la place orientale,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'et leur dit: Écoutez-moi, Lévites! Maintenant, sanctifiez-vous, et sanctifiez la maison de l’ Éternel, le Dieu de vos pères, et jetez la souillure hors du sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Car nos pères ont été infidèles, et ont fait ce qui est mauvais aux yeux de l’ Éternel, notre Dieu, et l’ont abandonné, et ont détourné leurs faces de la demeure de l’ Éternel, et lui ont tourné le dos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Même ils ont fermé les portes du portique, et ont éteint les lampes, et n’ont pas fait fumer l’encens, et n’ont pas offert l’holocauste dans le lieu saint au Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Et la colère de l’ Éternel a été sur Juda et sur Jérusalem, et il les a livrés à la vexation et à la destruction et au sifflement, comme vous le voyez de vos yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Et voici, à cause de cela, nos pères sont tombés par l’épée, et nos fils, et nos filles, et nos femmes, sont en captivité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Maintenant, j’ai à cœur de faire alliance avec l’ Éternel, le Dieu d’Israël, afin que l’ardeur de sa colère se détourne de nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Maintenant, mes fils, ne soyez pas négligents, car c’est vous que l’ Éternel a choisis, pour que vous vous teniez devant lui pour le servir, et pour être ses serviteurs et ceux qui lui offrent [ce qui se brûle sur l’autel].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Et les lévites se levèrent, Makhath, fils d’Amasçaï, et Joël, fils d’Azaria, d’entre les fils des Kehathites; et d’entre les fils de Merari, Kis, fils d’Abdi, et Azaria, fils de Jehalléleël; et d’entre les Guershonites, Joakh, fils de Zimma, et Éden, fils de Joakh;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'et d’entre les fils d’Élitsaphan, Shimri et Jehiel; et d’entre les fils d’Asaph, Zacharie et Matthania;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'et d’entre les fils d’Héman, Jekhiel et Shimhi; et d’entre les fils de Jeduthun, Shemahia et Uziel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Et ils rassemblèrent leurs frères, et se sanctifièrent; et ils entrèrent selon le commandement du roi, d’après les paroles de l’ Éternel, pour purifier la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Et les sacrificateurs entrèrent dans l’intérieur de la maison de l’ Éternel, pour la purifier, et jetèrent dehors, au parvis de la maison de l’ Éternel, toutes les impuretés qu’ils trouvèrent dans le temple de l’ Éternel, et les lévites les prirent pour les jeter dehors dans le torrent du Cédron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Et ils commencèrent la sanctification le premier [jour] du premier mois, et au huitième jour du mois ils vinrent au portique de l’ Éternel, et sanctifièrent la maison de l’ Éternel pendant huit jours; et, le seizième jour du premier mois, ils eurent achevé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Et ils entrèrent chez le roi Ézéchias, et dirent: Nous avons purifié toute la maison de l’ Éternel, et l’autel de l’holocauste et tous ses ustensiles, et la table des [pains] à placer en rangées et tous ses ustensiles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'et nous avons mis en état et sanctifié tous les ustensiles que le roi Achaz avait rejetés pendant son règne, pendant son péché; et voici, ils sont devant l’autel de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Et le roi Ézéchias se leva de bonne heure, et assembla les chefs de la ville, et monta à la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Et ils amenèrent sept taureaux, et sept béliers, et sept agneaux, et sept boucs en sacrifice pour le péché, pour le royaume, et pour le sanctuaire, et pour Juda. Et [le roi] dit aux sacrificateurs, fils d’Aaron, de les offrir sur l’autel de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Et ils égorgèrent les bœufs, et les sacrificateurs reçurent le sang, et en firent aspersion sur l’autel; et ils égorgèrent les béliers et firent aspersion du sang sur l’autel; et ils égorgèrent les agneaux et firent aspersion du sang sur l’autel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'et ils firent approcher les boucs du sacrifice pour le péché, devant le roi et la congrégation, et ils posèrent leurs mains sur eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'et les sacrificateurs les égorgèrent et firent avec leur sang, sur l’autel, la purification du péché, afin de faire propitiation pour tout Israël; car le roi avait dit que l’holocauste et le sacrifice pour le péché seraient pour tout Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Et il plaça les lévites dans la maison de l’ Éternel, avec des cymbales, des luths et des harpes, selon le commandement de David, et de Gad, le voyant du roi, et de Nathan, le prophète; car le commandement était de la part de l’ Éternel par ses prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Et les lévites se tinrent là avec les instruments de David, et les sacrificateurs avec les trompettes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Et Ézéchias dit d’offrir l’holocauste sur l’autel; et, au moment où commença l’holocauste, le cantique de l’ Éternel commença, et les trompettes avec l’accompagnement des instruments de David, roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Et toute la congrégation se prosterna, et le cantique se chanta, et les trompettes sonnèrent, tout le temps, jusqu’à ce que l’holocauste soit achevé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Et quand on eut achevé d’offrir l’holocauste, le roi et tous ceux qui se trouvaient avec lui s’inclinèrent et se prosternèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Et le roi Ézéchias et les chefs dirent aux lévites de louer l’ Éternel avec les paroles de David et d’Asaph, le voyant; et ils louèrent avec joie, et ils s’inclinèrent et se prosternèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Et Ézéchias prit la parole et dit: Vous vous êtes maintenant consacrés à l’ Éternel; approchez-vous, et amenez des sacrifices et des offrandes de louanges dans la maison de l’ Éternel. Et la congrégation amena des sacrifices et des offrandes de louanges, et tous ceux qui avaient un esprit libéral [amenèrent] des holocaustes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Et le nombre des holocaustes que la congrégation amena fut de 70 taureaux, 100 béliers, 200 agneaux, tout cela pour l’holocauste à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Et les choses consacrées furent 600 bœufs et 3 000 moutons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Seulement il y avait trop peu de sacrificateurs, et ils ne purent écorcher tous les holocaustes; et leurs frères, les lévites, les aidèrent, jusqu’à ce que l’ouvrage soit achevé et que les sacrificateurs se soient sanctifiés; car les lévites furent plus droits de cœur que les sacrificateurs pour se sanctifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Et il y eut aussi des holocaustes en abondance, avec les graisses des sacrifices de prospérités, et avec les libations pour les holocaustes. Et le service de la maison de l’ Éternel fut rétabli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Et Ézéchias et tout le peuple se réjouirent de ce que Dieu avait disposé le peuple; car la chose fut faite soudainement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Et Ézéchias envoya vers tout Israël et Juda, et il écrivit aussi des lettres à Éphraïm et à Manassé, pour qu’ils viennent à la maison de l’ Éternel, à Jérusalem, pour faire la Pâque à l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Et le roi, et ses chefs, et toute la congrégation à Jérusalem, tinrent conseil pour faire la Pâque au second mois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'car ils ne pouvaient la faire en ce temps-là, car les sacrificateurs ne s’étaient pas sanctifiés en nombre suffisant, et le peuple n’avait pas été rassemblé à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Et la chose fut agréable aux yeux du roi et de toute la congrégation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'et ils déterminèrent de faire passer une proclamation par tout Israël depuis Beër-Shéba jusqu’à Dan, pour qu’on vienne faire la Pâque à l’ Éternel, le Dieu d’Israël, à Jérusalem; car depuis longtemps ils ne l’avaient pas faite comme il est écrit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Et les courriers allèrent avec les lettres de la main du roi et de ses chefs par tout Israël et Juda, et selon le commandement du roi, en disant: Fils d’Israël, retournez à l’ Éternel, le Dieu d’Abraham, d’Isaac, et d’Israël, et il reviendra au reste d’entre vous qui est échappé à la main des rois d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Et ne soyez pas comme vos pères et comme vos frères, qui ont péché contre l’ Éternel, le Dieu de leurs pères, et il les a livrés à la destruction, comme vous le voyez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Maintenant ne roidissez pas votre cou, comme vos pères; donnez la main à l’ Éternel, et venez à son sanctuaire qu’il a sanctifié pour toujours, et servez l’ Éternel, votre Dieu, afin que l’ardeur de sa colère se détourne de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Car si vous retournez à l’ Éternel, vos frères et vos fils trouveront miséricorde devant ceux qui les ont emmenés captifs, et ils reviendront dans ce pays; car l’ Éternel, votre Dieu, fait grâce et est miséricordieux, et il ne détournera pas sa face de vous, si vous revenez à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Et les courriers passaient de ville en ville, dans le pays d’Éphraïm et de Manassé, et jusqu’à Zabulon; et on se riait et on se raillait d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Toutefois des hommes d’Aser, et de Manassé, et de Zabulon, s’humilièrent et vinrent à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'La main de Dieu fut aussi sur Juda, pour leur donner un même cœur pour exécuter le commandement du roi et des chefs, selon la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Et il s’assembla à Jérusalem une grande multitude de peuple pour célébrer la fête des pains sans levain au second mois, une très grande congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Et ils se levèrent, et ôtèrent les autels qui étaient dans Jérusalem; et ils ôtèrent tous les autels à encens, et les jetèrent dans le torrent du Cédron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Et on égorgea la pâque le quatorzième [jour] du second mois; et les sacrificateurs et les lévites avaient eu honte et s’étaient sanctifiés; et ils amenèrent des holocaustes dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Et ils se tinrent à leur place, selon leur ordonnance, selon la loi de Moïse, homme de Dieu, les sacrificateurs faisant aspersion du sang, [le recevant] des mains des lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Car il y avait une grande partie de la congrégation qui ne s’était pas sanctifiée; et les lévites eurent la charge d’égorger les pâques pour tous ceux qui n’étaient pas purs, afin de les sanctifier à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Car une grande partie du peuple, beaucoup de ceux d’Éphraïm, et de Manassé, et d’Issacar, et de Zabulon, ne s’étaient pas purifiés, et ils mangèrent la pâque, non comme il est écrit; mais Ézéchias pria pour eux, disant: Que l’ Éternel, qui est bon, pardonne à');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'tous ceux qui ont appliqué leur cœur à rechercher Dieu, l’ Éternel, le Dieu de leurs pères, bien que ce ne soit pas conformément à la purification du sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Et l’ Éternel écouta Ézéchias, et guérit le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Et les fils d’Israël qui se trouvèrent à Jérusalem célébrèrent la fête des pains sans levain pendant sept jours, avec une grande joie; et les lévites et les sacrificateurs louaient l’ Éternel, jour après jour, avec les instruments de la louange de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Et Ézéchias parla au cœur de tous les lévites qui étaient entendus dans la bonne connaissance à l’égard de l’ Éternel; et ils mangèrent pendant les sept jours les offrandes de la fête, sacrifiant des sacrifices de prospérités et exaltant l’ Éternel, le Dieu de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Et toute la congrégation résolut de célébrer encore sept jours; et ils célébrèrent les sept jours avec joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Car Ézéchias, roi de Juda, donna à la congrégation 1 000 taureaux et 7 000 moutons; et les chefs donnèrent à la congrégation 1 000 taureaux et 10 000 moutons; et des sacrificateurs, en grand nombre, se sanctifièrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Et toute la congrégation de Juda se réjouit, et les sacrificateurs et les lévites, et toute la congrégation qui était venue d’Israël, et les étrangers qui étaient venus du pays d’Israël, et ceux qui habitaient en Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Et il y eut une grande joie à Jérusalem; car depuis les jours de Salomon, fils de David, roi d’Israël, rien de semblable [n’avait eu lieu] à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Et les sacrificateurs, les Lévites, se levèrent et bénirent le peuple; et leur voix fut écoutée, et leur prière parvint à sa demeure sainte dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Et lorsque tout cela fut terminé, tous ceux d’Israël qui se trouvèrent [là], s’en allèrent par les villes de Juda, et brisèrent les statues, et abattirent les ashères, et démolirent les hauts lieux et les autels dans tout Juda et Benjamin, et en Éphraïm et Manassé, jusqu’à ce qu’ils aient tout détruit; et tous les fils d’Israël retournèrent dans leurs villes, chacun dans sa possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Et Ézéchias établit les classes des sacrificateurs et des lévites, selon leurs classes, chacun selon son service, tant sacrificateurs que lévites, pour les holocaustes et pour les sacrifices de prospérités, pour faire le service et pour rendre grâces et pour louer aux portes des parvis de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Et [il établit] que la portion du roi [serait prise] sur ses biens, pour les holocaustes: pour les holocaustes du matin et du soir, et pour les holocaustes des sabbats et des nouvelles lunes et des fêtes solennelles, comme il est écrit dans la loi de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Et il dit au peuple, aux habitants de Jérusalem, de donner la portion des sacrificateurs et des lévites, afin qu’ils s’attachent à la loi de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Et quand la parole [du roi] se répandit, les fils d’Israël apportèrent en grande quantité les prémices du blé, du moût, et de l’huile, et du miel, et de tous les produits des champs; et ils apportèrent la dîme de tout, en abondance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Et les fils d’Israël et de Juda, qui habitaient dans les villes de Juda, eux aussi apportèrent la dîme du gros bétail et du menu bétail, et la dîme des choses saintes, qui étaient consacrées à l’ Éternel, leur Dieu, et ils les mirent par monceaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Au troisième mois, ils commencèrent de faire les monceaux, et au septième mois ils achevèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Et Ézéchias et les chefs vinrent et virent les monceaux, et ils bénirent l’ Éternel et son peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Et Ézéchias s’informa auprès des sacrificateurs et des lévites au sujet des monceaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Et Azaria, le principal sacrificateur, qui était de la maison de Tsadok, lui parla, et dit: Depuis qu’on a commencé d’apporter l’offrande dans la maison de l’ Éternel, on a mangé et on a été rassasié, et il en est resté en abondance; car l’ Éternel a béni son peuple; et ce qui reste, c’est cette grande quantité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Et Ézéchias dit qu’on prépare des chambres dans la maison de l’ Éternel; et on les prépara;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'et on apporta fidèlement l’offrande, et la dîme, et les choses saintes; et Conania, le lévite, en eut la surintendance, et Shimhi, son frère, en second;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'et Jekhiel, et Azazia, et Nakhath, et Asçaël, et Jerimoth, et Jozabad, et Éliel, et Jismakia, et Makhath, et Benaïa, étaient intendants sous l’autorité de Conania et de Shimhi, son frère, par l’ordre du roi Ézéchias, et d’Azaria, prince de la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Et Koré, fils de Jimna, le lévite, qui était portier vers le levant, [était préposé] sur les offrandes volontaires [faites] à Dieu, pour distribuer l’offrande de l’ Éternel et les choses très saintes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'et il avait sous ses ordres Éden, et Minjamin, et Jéshua, et Shemahia, Amaria et Shecania, dans les villes des sacrificateurs, pour faire les distributions avec fidélité à leurs frères, selon leurs classes, au grand comme au petit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'outre ceux qui étaient enregistrés comme mâles dans les généalogies, depuis l’âge de trois ans et au-dessus, à chacun de ceux qui entraient dans la maison de l’ Éternel, chaque jour pour l’affaire du jour, pour servir dans leurs charges, selon leurs classes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'et aux sacrificateurs enregistrés selon leurs maisons de pères, et aux lévites, depuis l’âge de 20 ans et au-dessus, dans leurs charges, selon leurs classes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'et à tous leurs petits enfants, leurs femmes, et leurs fils, et leurs filles, – toute la congrégation enregistrée; car, dans leur fidélité, ils se sanctifiaient pour être saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Et pour les fils d’Aaron, les sacrificateurs, qui étaient dans la campagne, [répandus] dans les banlieues de leurs villes, il y avait dans chaque ville des hommes désignés par leur nom pour distribuer les portions à tous les mâles parmi les sacrificateurs, et à tous ceux qui étaient enregistrés parmi les lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Et Ézéchias fit ainsi dans tout Juda. Et il fit ce qui est bon, et droit, et vrai, devant l’ Éternel, son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Et dans toute œuvre qu’il entreprit, dans le service de la maison de Dieu et dans la loi et dans les commandements, pour rechercher son Dieu, il agit de tout son cœur, et prospéra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, '*Après ces choses et cette fidélité, Sankhérib, roi d’Assyrie, vint et entra en Judée, et campa contre les villes fortes, et il pensait en forcer l’entrée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Et quand Ézéchias vit que Sankhérib venait, et qu’il se dirigeait contre Jérusalem pour lui faire la guerre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'il tint conseil avec ses chefs et ses hommes forts pour arrêter les eaux des sources qui étaient en dehors de la ville; et ils l’aidèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Et un grand peuple se rassembla, et ils bouchèrent toutes les sources et le torrent qui débordait, disant: Pourquoi les rois d’Assyrie viendraient-ils et trouveraient-ils des eaux abondantes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Et il s’encouragea, et bâtit toute la muraille où il y avait des brèches, et l’éleva jusqu’aux tours, et [bâtit] une autre muraille en dehors; et il fortifia Millo [dans] la ville de David, et fit beaucoup de javelines et de boucliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Et il établit des chefs de guerre sur le peuple, et les rassembla auprès de lui sur la place de la porte de la ville, et parla à leur cœur, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Fortifiez-vous et soyez fermes; ne craignez point et ne soyez point effrayés devant le roi d’Assyrie et à cause de toute la multitude qui est avec lui; car avec nous il y a plus qu’avec lui:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'avec lui est un bras de chair, mais avec nous est l’ Éternel, notre Dieu, pour nous aider et pour combattre nos combats. Et le peuple s’appuya sur les paroles d’Ézéchias, roi de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Après cela, Sankhérib, roi d’Assyrie, étant encore devant Lakis et ayant avec lui toutes ses forces, envoya ses serviteurs à Jérusalem vers Ézéchias, roi de Juda, et vers tous ceux de Juda qui étaient à Jérusalem, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Ainsi dit Sankhérib, roi d’Assyrie: En quoi vous confiez-vous, que vous demeuriez assiégés dans Jérusalem?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Ézéchias ne vous incite-t-il pas, pour vous livrer à la mort par la faim et par la soif, en disant: L’ Éternel, notre Dieu, nous délivrera de la main du roi d’Assyrie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'N’est-ce pas cet Ézéchias qui a ôté ses hauts lieux et ses autels, et qui a parlé à Juda et à Jérusalem, disant: Vous vous prosternerez devant [ce] seul autel, et sur lui vous ferez fumer l’encens?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ne savez-vous pas ce que j’ai fait, moi, et aussi mes pères, à tous les peuples des pays? Les dieux des nations des pays ont-ils bien pu délivrer leur pays de ma main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Lequel d’entre tous les dieux de ces nations que mes pères ont détruites, a pu délivrer son peuple de ma main, pour que votre Dieu puisse vous délivrer de ma main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Et maintenant, qu’Ézéchias ne vous trompe pas, et qu’il ne vous séduise pas de cette manière, et ne le croyez pas; car aucun dieu d’aucune nation ni d’aucun royaume n’a pu délivrer son peuple de ma main ni de la main de mes pères; combien moins votre Dieu vous délivrera-t-il de ma main!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Et ses serviteurs parlèrent encore contre l’ Éternel, le [vrai] Dieu, et contre Ézéchias, son serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Et il écrivit une lettre pour outrager l’ Éternel, le Dieu d’Israël, et pour parler contre lui, disant: De même que les dieux des nations des pays n’ont pas délivré leur peuple de ma main, de même le Dieu d’Ézéchias ne délivrera pas son peuple de ma main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Et ils crièrent à haute voix, en [langue] judaïque, au peuple de Jérusalem qui était sur la muraille, pour leur faire peur et les épouvanter, afin de prendre la ville;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'et ils parlèrent du Dieu de Jérusalem comme des dieux des peuples de la terre, ouvrage de mains d’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Et le roi Ézéchias et Ésaïe, le prophète, fils d’Amots, prièrent à ce sujet, et ils crièrent au ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Et l’ Éternel envoya un ange qui extermina tous les hommes forts et vaillants, et les princes, et les capitaines, dans le camp du roi d’Assyrie; et il s’en retourna, la honte au visage, dans son pays; et comme il entrait dans la maison de son dieu, ceux qui étaient sortis de ses entrailles le firent tomber là par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Et l’ Éternel sauva Ézéchias et les habitants de Jérusalem de la main de Sankhérib, roi d’Assyrie, et de la main de tous, et les protégea tout à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Et beaucoup de gens apportèrent des offrandes à l’ Éternel à Jérusalem, et des choses précieuses à Ézéchias, roi de Juda; et après cela, il fut élevé aux yeux de toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'En ces jours-là, Ézéchias fut malade à la mort; et il pria l’ Éternel, et [l’ Éternel] lui parla, et lui donna un signe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Mais Ézéchias ne rendit pas en raison du bienfait qu’il avait reçu; car son cœur s’éleva, et il y eut de la colère contre lui et contre Juda et Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Et Ézéchias s’humilia de ce que son cœur s’était élevé, lui et les habitants de Jérusalem; et la colère de l’ Éternel ne vint pas sur eux pendant les jours d’Ézéchias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Et Ézéchias eut de très grandes richesses et une très grande gloire; et il se fit des trésoreries pour l’argent, et l’or, et les pierres précieuses, et les aromates, et les boucliers, et pour toute sorte d’objets d’agrément,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'et des magasins pour les produits en blé, en moût, et en huile, et des stalles pour toute espèce de bétail, et [il se procura] des troupeaux pour les stalles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'et il se bâtit des villes, et il eut des troupeaux de menu et de gros bétail en abondance; car Dieu lui donna de fort grands biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Et ce fut lui, Ézéchias, qui boucha l’issue supérieure des eaux de Guihon, et les conduisit sous [le sol], à l’occident de la ville de David. Et Ézéchias prospéra dans tout ce qu’il fit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Mais cependant, lors de l’ambassade que les chefs de Babylone envoyèrent vers lui pour s’informer du miracle qui avait été [opéré] dans le pays, Dieu l’abandonna pour l’éprouver, afin qu’il connaisse tout ce qui était dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Et le reste des actes d’Ézéchias, et ses actions pieuses, voici, ils sont écrits dans la vision d’Ésaïe, le prophète, fils d’Amots, dans le livre des rois de Juda et d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Et Ézéchias s’endormit avec ses pères, et on l’enterra à l’endroit le plus élevé des sépulcres des fils de David; et tout Juda et les habitants de Jérusalem lui rendirent honneur à sa mort; et Manassé, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, '*Manassé était âgé de douze ans lorsqu’il commença de régner; et il régna 55 ans à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, selon les abominations des nations que l’ Éternel avait dépossédées devant les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Et il rebâtit les hauts lieux, qu’Ézéchias, son père, avait démolis, et éleva des autels aux Baals, et fit des ashères, et il se prosterna devant toute l’armée des cieux, et les servit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'et il bâtit des autels dans la maison de l’ Éternel, de laquelle l’ Éternel avait dit: C’est dans Jérusalem que sera mon nom à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'et il bâtit des autels à toute l’armée des cieux, dans les deux parvis de la maison de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'et il fit passer ses fils par le feu dans la vallée du fils de Hinnom; et il pronostiquait, et pratiquait les enchantements et la magie, et il établit des évocateurs d’esprits et des diseurs de bonne aventure: il fit outre mesure ce qui est mauvais aux yeux de l’ Éternel, pour le provoquer à colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Et il plaça une image taillée, l’idole qu’il avait faite, dans la maison de Dieu, de laquelle Dieu avait dit à David et à Salomon, son fils: C’est dans cette maison, et dans Jérusalem que j’ai choisie entre toutes les tribus d’Israël, que je mettrai mon nom à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'et je n’ôterai plus le pied d’Israël de dessus la terre que j’ai assignée à vos pères, si seulement ils prennent garde à faire tout ce que je leur ai commandé par Moïse, selon toute la loi et les statuts et les ordonnances.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Et Manassé fit errer Juda et les habitants de Jérusalem, [en les induisant] à faire le mal plus que les nations que l’ Éternel avait détruites devant les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Et l’ Éternel parla à Manassé, et à son peuple; mais ils n’y firent pas attention.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Et l’ Éternel fit venir contre eux les chefs de l’armée du roi d’Assyrie, et ils prirent Manassé dans des ceps, et le lièrent avec des chaînes d’airain et l’emmenèrent à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Et quand il fut dans la détresse, il implora l’ Éternel, son Dieu, et s’humilia beaucoup devant le Dieu de ses pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'et le pria; et il se laissa fléchir par lui, et écouta sa supplication, et le ramena à Jérusalem dans son royaume; et Manassé reconnut que c’est l’ Éternel qui est Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Et après cela, il bâtit la muraille extérieure de la ville de David, au couchant, vers Guihon, dans la vallée, et vers l’entrée de la porte des poissons, et il entoura Ophel [d’un mur], et l’éleva très haut; et il mit des chefs de l’armée dans toutes les villes fortes de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Et il ôta de la maison de l’ Éternel les dieux étrangers et l’idole, et tous les autels qu’il avait bâtis sur la montagne de la maison de l’ Éternel et à Jérusalem, et les jeta hors de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Et il mit en état l’autel de l’ Éternel, et y sacrifia des sacrifices de prospérités et d’action de grâces; et il commanda à Juda de servir l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Toutefois le peuple sacrifiait encore sur les hauts lieux, mais seulement à l’ Éternel, leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Et le reste des actes de Manassé, et sa prière à son Dieu, et les paroles des voyants qui lui parlèrent au nom de l’ Éternel, le Dieu d’Israël, voici, cela est [écrit] dans les actes des rois d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Et sa prière, et comment [Dieu] fut fléchi, et tout son péché, et le mal qu’il commit, et les endroits où il bâtit des hauts lieux et dressa des ashères et des images taillées, avant qu’il se soit humilié, voici, cela est écrit dans les paroles de Hozaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Et Manassé s’endormit avec ses pères, et on l’enterra dans sa maison; et Amon, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, '*Amon était âgé de 22 ans lorsqu’il commença de régner; et il régna deux ans à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, comme avait fait Manassé, son père; et Amon sacrifia à toutes les images taillées que Manassé, son père, avait faites, et les servit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'et il ne s’humilia point devant l’ Éternel, comme Manassé, son père, s’était humilié; car lui, Amon, multiplia son péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Et ses serviteurs conspirèrent contre lui, et le mirent à mort dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Mais le peuple du pays tua tous ceux qui avaient conspiré contre le roi Amon; et le peuple du pays établit pour roi Josias, son fils, à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, '*Josias était âgé de huit ans lorsqu’il commença de régner; et il régna 31 ans à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Et il fit ce qui est droit aux yeux de l’ Éternel, et marcha dans les voies de David, son père, et ne s’en écarta ni à droite ni à gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Et la huitième année de son règne, lorsqu’il était encore un jeune garçon, il commença de rechercher le Dieu de David, son père; et la douzième année, il commença de purifier Juda et Jérusalem des hauts lieux, et des ashères, et des images taillées, et des images de fonte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Et on démolit devant lui les autels des Baals, et il abattit les colonnes consacrées au soleil, qui étaient en haut au-dessus d’eux; et il brisa les ashères, et les images taillées et les images de fonte, et les broya, et en répandit la poussière sur les sépulcres de ceux qui leur avaient sacrifié;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'et il brûla les os des sacrificateurs sur leurs autels. Et il purifia Juda et Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Et dans les villes de Manassé, et d’Éphraïm, et de Siméon, et jusqu’à Nephthali, dans leurs ruines, tout à l’entour,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'il démolit les autels, et mit en pièces, jusqu’à les réduire en poussière, les ashères et les images taillées, et abattit toutes les colonnes consacrées au soleil, dans tout le pays d’Israël; et il s’en retourna à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Et la dix-huitième année de son règne, lors de la purification du pays et de la maison, il envoya Shaphan, fils d’Atsalia, et Maascéïa, le chef de la ville, et Joakh, fils de Joakhaz, le rédacteur des chroniques, pour réparer la maison de l’ Éternel, son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Et ils vinrent chez Hilkija, le grand sacrificateur; et on [leur] remit l’argent qui avait été apporté dans la maison de Dieu [et] que les lévites, gardiens du seuil, avaient recueilli de la main de Manassé et d’Éphraïm, et de tout le reste d’Israël, et de tout Juda et Benjamin, et des habitants de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Et ils le remirent en la main de ceux qui faisaient l’ouvrage, qui étaient préposés [sur le travail] dans la maison de l’ Éternel; et ceux-ci le remirent aux ouvriers qui travaillaient dans la maison de l’ Éternel pour refaire et réparer la maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'ils le remirent aux charpentiers et aux constructeurs pour acheter des pierres de taille, et des bois pour les assemblages, et pour faire la charpenterie des maisons que les rois de Juda avaient détruites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Et ces hommes faisaient le travail avec fidélité. Et sur eux étaient préposés Jakhath et Abdias, lévites d’entre les fils de Merari, et Zacharie et Meshullam d’entre les fils des Kehathites, pour la surveillance; et tous ces lévites étaient habiles à [jouer] des instruments de musique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Et [ils étaient préposés] sur les portefaix, et ils surveillaient tous ceux qui étaient occupés à toute sorte de service. Et les scribes, et les intendants, et les portiers étaient d’entre les lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Et comme on sortait l’argent qui avait été apporté dans la maison de l’ Éternel, Hilkija, le sacrificateur, trouva le livre de la loi de l’ Éternel [donnée] par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Et Hilkija prit la parole et dit à Shaphan, le scribe: J’ai trouvé le livre de la loi dans la maison de l’ Éternel. Et Hilkija donna le livre à Shaphan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Et Shaphan apporta le livre au roi; et de plus il rendit compte au roi, disant: Tout ce qui a été remis en la main de tes serviteurs, ils l’exécutent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'et ils ont versé l’argent qui s’est trouvé dans la maison de l’ Éternel, et l’ont remis entre les mains des préposés et entre les mains de ceux qui font l’ouvrage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Et Shaphan, le scribe, raconta au roi, disant: Hilkija, le sacrificateur, m’a donné un livre. Et Shaphan y lut devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Et il arriva, quand le roi entendit les paroles de la loi, qu’il déchira ses vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Et le roi commanda à Hilkija, et à Akhikam, fils de Shaphan, et à Abdon, fils de Michée, et à Shaphan, le scribe, et à Asçaïa, serviteur du roi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Allez, consultez l’ Éternel pour moi et pour ce qui est de reste en Israël et en Juda, touchant les paroles du livre qui a été trouvé; car grande est la fureur de l’ Éternel, qui s’est déversée sur nous, parce que nos pères n’ont pas gardé la parole de l’ Éternel, pour faire selon tout ce qui est écrit dans ce livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Et Hilkija et les gens du roi allèrent vers Hulda, la prophétesse, femme de Shallum, fils de Thokehath, fils de Hasra, qui avait la garde des vêtements; et elle habitait à Jérusalem dans le second quartier de la ville; et ils lui parlèrent selon ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Et elle leur dit: Ainsi dit l’ Éternel, le Dieu d’Israël: Dites à l’homme qui vous a envoyés vers moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Ainsi dit l’ Éternel: Voici, je fais venir du mal sur ce lieu et sur ses habitants, toutes les malédictions qui sont écrites dans le livre qu’on a lu devant le roi de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Parce qu’ils m’ont abandonné et qu’ils ont brûlé de l’encens à d’autres dieux, pour me provoquer à colère par toutes les œuvres de leurs mains, ma fureur se déversera sur ce lieu, et elle ne s’éteindra point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Et au roi de Juda qui vous a envoyés pour consulter l’ Éternel, vous direz ainsi: Ainsi dit l’ Éternel, le Dieu d’Israël, quant aux paroles que tu as entendues:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Parce que ton cœur a été sensible, et que tu t’es humilié devant Dieu quand tu as entendu ses paroles contre ce lieu et contre ses habitants, et parce que tu t’es humilié devant moi, et que tu as déchiré tes vêtements, et que tu as pleuré devant moi, moi aussi j’ai entendu, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Voici, je vais te recueillir auprès de tes pères, et tu seras recueilli en paix dans tes sépulcres, et tes yeux ne verront pas tout le mal que je fais venir sur ce lieu, et sur ses habitants. Et ils rapportèrent au roi [cette] parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Et le roi envoya, et assembla tous les anciens de Juda et de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Et le roi monta à la maison de l’ Éternel, et tous les hommes de Juda, et les habitants de Jérusalem, et les sacrificateurs, et les lévites, et tout le peuple, depuis le grand jusqu’au petit; et on lut, eux l’entendant, toutes les paroles du livre de l’alliance qui avait été trouvé dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Et le roi se tint debout à sa place, et fit cette alliance devant l’ Éternel, de marcher après l’ Éternel et de garder ses commandements et ses témoignages et ses statuts, de tout son cœur et de toute son âme, pour pratiquer les paroles de l’alliance, écrites dans ce livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Et il fit entrer [dans l’alliance] tous ceux qui se trouvaient à Jérusalem et en Benjamin; et les habitants de Jérusalem firent selon l’alliance de Dieu, du Dieu de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Et Josias ôta toutes les abominations de tous les pays qui appartenaient aux fils d’Israël, et obligea tous ceux qui se trouvaient en Israël à servir l’ Éternel, leur Dieu. Pendant tous ses jours, ils ne se détournèrent pas de l’ Éternel, le Dieu de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Et Josias célébra à Jérusalem la Pâque à l’ Éternel; et on égorgea la pâque, le quatorzième jour du premier mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Et il établit les sacrificateurs dans leurs charges, et les encouragea pour le service de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Et il dit aux lévites qui enseignaient tout Israël, [et] qui étaient saints, [consacrés] à l’ Éternel: Mettez l’arche sainte dans la maison que Salomon, fils de David, roi d’Israël, a bâtie: vous n’avez pas à la porter sur l’épaule; servez maintenant l’ Éternel, votre Dieu, et son peuple Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'et préparez-vous, selon vos maisons de pères, selon vos divisions, suivant l’écrit de David, roi d’Israël, et suivant l’écrit de Salomon, son fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'et placez-vous dans le lieu saint pour les sections des maisons de pères de vos frères, les fils du peuple, et selon les divisions des maisons de pères des lévites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'et égorgez la pâque, et sanctifiez-vous, et préparez [la pâque] pour vos frères, afin d’agir conformément à la parole de l’ Éternel par Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Et Josias donna aux fils du peuple du menu bétail, des agneaux et des chevreaux, au nombre de 30 000, le tout pour les pâques, pour tous ceux qui se trouvaient là, et 3 000 bœufs; cela fut [pris] sur les biens du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Et ses chefs donnèrent volontairement pour le peuple, pour les sacrificateurs et pour les lévites. Hilkija, et Zacharie, et Jekhiel, les princes de la maison de Dieu, donnèrent aux sacrificateurs, pour les pâques, 2 600 [têtes de menu bétail] et 300 de gros bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Et Conania, et Shemahia et Nethaneël, ses frères, et Hashabia, et Jehiel, et Jozabad, chefs des lévites, donnèrent pour les lévites 5 000 [têtes de menu bétail] pour les pâques, et 500 de gros bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Et le service fut réglé, et les sacrificateurs se tinrent à leurs places, et les lévites dans leurs divisions, selon le commandement du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Et ils égorgèrent la pâque; et les sacrificateurs firent aspersion [du sang qu’ils recevaient] de leurs mains, et les lévites écorchaient [les victimes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Et ils mirent à part les holocaustes pour les donner aux sections des maisons de pères des fils du peuple, pour les présenter à l’ Éternel, selon qu’il est écrit dans le livre de Moïse; et [ils firent] de même pour le gros bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Et ils firent cuire la pâque au feu, selon l’ordonnance; et les choses saintes, ils les firent cuire dans des chaudières, et des chaudrons, et des poêles, et les distribuèrent à la hâte à tous les fils du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Et ensuite, ils préparèrent [ce qui était] pour eux et pour les sacrificateurs; car les sacrificateurs, fils d’Aaron, [furent occupés] jusqu’à la nuit à offrir les holocaustes et les graisses; et les lévites préparèrent [ce qui était] pour eux-mêmes, et pour les sacrificateurs, fils d’Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Et les chantres, fils d’Asaph, étaient à leur place, selon le commandement de David, et d’Asaph, et d’Héman, et de Jeduthun, le voyant du roi; et les portiers étaient à chaque porte: ils n’eurent pas à se retirer de leur service, car leurs frères, les lévites, préparaient [ce qui était] pour eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Et tout le service de l’ Éternel fut réglé, en ce jour-là, pour faire la Pâque, et pour offrir des holocaustes sur l’autel de l’ Éternel, selon le commandement du roi Josias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Et les fils d’Israël présents, firent la Pâque en ce temps-là, et la fête des pains sans levain pendant sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Et on n’avait point célébré en Israël de Pâque semblable depuis les jours de Samuel, le prophète; et aucun des rois d’Israël n’avait célébré une Pâque comme celle que firent Josias, et les sacrificateurs et les lévites, et tout Juda et Israël, qui s’y trouvèrent, et les habitants de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Cette Pâque fut célébrée la dix-huitième année du règne de Josias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Après tout cela, quand Josias eut mis en état la maison, Neco, roi d’Égypte, monta pour faire la guerre à Carkemish sur l’Euphrate; et Josias sortit à sa rencontre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Et [Neco] lui envoya des messagers, disant: Qu’y a-t-il entre moi et toi, roi de Juda? Ce n’est pas contre toi que je viens aujourd’hui, mais contre la maison avec laquelle je suis en guerre, et Dieu m’a dit de me hâter. Désiste-toi de [t’opposer à] Dieu, qui est avec moi, afin qu’il ne te détruise pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Et Josias ne se détourna pas de lui, mais il se déguisa pour combattre contre lui; et il n’écouta pas les paroles de Neco, [qui venaient] de la bouche de Dieu. Et il vint pour combattre dans la vallée de Meguiddo.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Et les archers tirèrent sur le roi Josias; et le roi dit à ses serviteurs: Ôtez-moi d’ici, car je suis grièvement blessé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Et ses serviteurs l’ôtèrent du char, et le mirent sur un second char qu’il avait, et le conduisirent à Jérusalem. Et il mourut; et on l’enterra dans les sépulcres de ses pères; et tout Juda et Jérusalem menèrent deuil sur Josias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Et Jérémie fit des lamentations sur Josias; et tous les chanteurs et toutes les chanteuses ont parlé de Josias dans leurs lamentations jusqu’à aujourd’hui; et on l’a établi comme ordonnance pour Israël. Et, voici, cela est écrit dans les Lamentations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Et le reste des actes de Josias, et ses actions pieuses, conformément à ce qui est écrit dans la loi de l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'et ses actes, les premiers et les derniers, voici, ils sont écrits dans le livre des rois d’Israël et de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, '*Et le peuple du pays prit Joakhaz, fils de Josias, et le fit roi à la place de son père, à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Joakhaz était âgé de 23 ans lorsqu’il commença de régner; et il régna trois mois à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Et le roi d’Égypte le déposa, à Jérusalem, et frappa le pays d’une amende de 100 talents d’argent et d’un talent d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Et le roi d’Égypte établit roi sur Juda et sur Jérusalem, Éliakim, frère de Joakhaz, et changea son nom en celui de Jehoïakim; et Neco prit Joakhaz, frère de Jehoïakim, et l’emmena en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, '*Jehoïakim était âgé de 25 ans lorsqu’il commença de régner; et il régna onze ans à Jérusalem, et fit ce qui est mauvais aux yeux de l’ Éternel, son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Nebucadnetsar, roi de Babylone, monta contre lui, et le lia avec des chaînes d’airain pour le conduire à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Et Nebucadnetsar emporta à Babylone [une partie] des ustensiles de la maison de l’ Éternel, et les mit dans son temple à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Et le reste des actes de Jehoïakim, et ses abominations qu’il commit, et ce qui fut trouvé en lui, voici, cela est écrit dans le livre des rois d’Israël et de Juda. Et Jehoïakin, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, '*Jehoïakin était âgé de [dix]-huit ans lorsqu’il commença de régner; et il régna trois mois et dix jours à Jérusalem. Et il fit ce qui est mauvais aux yeux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Et au retour de l’année, le roi Nebucadnetsar envoya, et l’amena à Babylone, avec les objets désirables de la maison de l’ Éternel; et il établit Sédécias, son frère, roi sur Juda et sur Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, '*Sédécias était âgé de 21 ans lorsqu’il commença de régner; et il régna onze ans à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, son Dieu; il ne s’humilia pas devant Jérémie, le prophète, [qui lui parlait] de la part de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'et il se révolta aussi contre le roi Nebucadnetsar, qui lui avait fait jurer par Dieu; et il roidit son cou, et endurcit son cœur pour ne pas retourner à l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Tous les chefs des sacrificateurs aussi, et le peuple, multiplièrent beaucoup leurs péchés, selon toutes les abominations des nations; et ils rendirent impure la maison de l’ Éternel qu’il avait sanctifiée à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Et l’ Éternel, le Dieu de leurs pères, envoya vers eux par ses messagers, se levant de bonne heure et envoyant, car il avait compassion de son peuple et de sa demeure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Mais ils se moquaient des messagers de Dieu, et méprisaient ses paroles, et se raillaient de ses prophètes, jusqu’à ce que la fureur de l’ Éternel monta contre son peuple et qu’il n’y eut plus de remède.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Et il fit monter contre eux le roi des Chaldéens, et tua leurs jeunes hommes par l’épée dans la maison de leur sanctuaire; et il n’eut pas compassion du jeune homme, ni de la vierge, [ni] de l’ancien, ni du vieillard: il les livra tous entre ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Et tous les ustensiles de la maison de Dieu, grands et petits, et les trésors de la maison de l’ Éternel, et les trésors du roi et de ses chefs, il emporta tout à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Et ils brûlèrent la maison de Dieu, et abattirent la muraille de Jérusalem, et brûlèrent par le feu tous ses palais; et tous ses objets désirables furent livrés à la destruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Et il transporta à Babylone le reste [échappé] à l’épée; et ils furent ses serviteurs, à lui et à ses fils, jusqu’au règne du royaume des Perses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'afin que fût accomplie la parole de l’ Éternel, [dite] par la bouche de Jérémie, jusqu’à ce que le pays ait joui de ses sabbats. Tous les jours de sa désolation il se reposa, jusqu’à ce que 70 ans soient accomplis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, '*Et la première année de Cyrus, roi de Perse, afin que soit accomplie la parole de l’ Éternel [dite] par la bouche de Jérémie, l’ Éternel réveilla l’esprit de Cyrus, roi de Perse; et il fit une proclamation dans tout son royaume, et la publia aussi par écrit, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Ainsi dit Cyrus, roi de Perse: L’ Éternel, le Dieu des cieux, m’a donné tous les royaumes de la terre, et il m’a chargé de lui bâtir une maison à Jérusalem, qui est en Juda. Qui d’entre vous, quel qu’il soit, est de son peuple, – que l’ Éternel, son Dieu, soit avec lui, et qu’il monte!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Et la première année de Cyrus, roi de Perse, afin que fût accomplie la parole de l’ Éternel [dite] par la bouche de Jérémie, l’ Éternel réveilla l’esprit de Cyrus, roi de Perse; et il fit une proclamation dans tout son royaume, et la publia aussi par écrit, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Ainsi dit Cyrus, roi de Perse: L’ Éternel, le Dieu des cieux, m’a donné tous les royaumes de la terre, et il m’a chargé de lui bâtir une maison à Jérusalem, qui est en Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Qui d’entre vous, quel qu’il soit, est de son peuple, – que son Dieu soit avec lui, et qu’il monte à Jérusalem, qui est en Juda, et qu’il bâtisse la maison de l’ Éternel, le Dieu d’Israël (lui est Dieu), à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Et celui qui est de reste, dans tous les lieux où chacun séjourne, que les hommes du lieu lui viennent en aide, avec de l’argent, et avec de l’or, et avec des biens, et avec du bétail, outre les offrandes volontaires pour la maison de Dieu qui est à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Alors se levèrent les chefs des pères de Juda et de Benjamin, et les sacrificateurs et les lévites, tous ceux dont Dieu avait réveillé l’esprit, afin de monter pour bâtir la maison de l’ Éternel qui est à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Et tous ceux qui les entouraient les aidèrent avec des objets d’argent, avec de l’or, avec des biens, et avec du bétail, et avec des choses précieuses, outre tout ce qu’on offrit volontairement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Et le roi Cyrus fit sortir les ustensiles de la maison de l’ Éternel, que Nebucadnetsar avait fait sortir de Jérusalem et qu’il avait mis dans la maison de son dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Et Cyrus, roi de Perse, les fit sortir par Mithredath, le trésorier, qui les compta à Sheshbatsar, prince de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Et en voici le nombre: 30 bassins d’or, 1 000 bassins d’argent, 29 couteaux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, '30 coupes d’or, 410 coupes d’argent de second ordre, [et] 1 000 autres ustensiles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'tous les ustensiles d’or et d’argent étaient [au nombre de] 5 400. Sheshbatsar apporta le tout lorsqu’on fit monter de Babylone à Jérusalem ceux de la transportation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Et voici ceux de la province qui remontèrent de la captivité de ceux qui avaient été transportés, lesquels Nebucadnetsar, roi de Babylone, avait transportés à Babylone, et qui retournèrent à Jérusalem et en Juda, chacun à sa ville,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'lesquels vinrent avec Zorobabel, Jéshua, Néhémie, Seraïa, Reélaïa, Mardochée, Bilshan, Mispar, Bigvaï, Rehum, [et] Baana. Nombre des hommes du peuple d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Les fils de Parhosh, 2 172;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'les fils de Shephatia, 372;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'les fils d’Arakh, 775;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'les fils de Pakhath-Moab, des fils de Jéshua [et de] Joab, 2 812;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'les fils d’Élam, 1 254;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'les fils de Zatthu, 945;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'les fils de Zaccaï, 760;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'les fils de Bani, 642;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'les fils de Bébaï, 623;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'les fils d’Azgad, 1 222;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'les fils d’Adonikam, 666;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'les fils de Bigvaï, 2 056;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'les fils d’Adin, 454;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'les fils d’Ater, [de la famille] d’Ézéchias, 98;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'les fils de Bétsaï, 323;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'les fils de Jora, 112;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'les fils de Hashum, 223;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'les fils de Guibbar, 95;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'les fils de Bethléhem, 123;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'les hommes de Netopha, 56;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'les hommes d’Anathoth, 128;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'les fils d’Azmaveth, 42;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'les fils de Kiriath-Arim, de Kephira et de Beéroth, 743;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'les fils de Rama et de Guéba, 621;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'les hommes de Micmas, 122;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'les hommes de Béthel et d’Aï, 223;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'les fils de Nebo, 52;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'les fils de Magbish, 156;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'les fils de l’autre Élam, 1 254;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'les fils de Harim, 320;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'les fils de Lod, de Hadid et d’Ono, 725;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'les fils de Jéricho, 345;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'les fils de Senaa, 3 630.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Sacrificateurs: les fils de Jedahia, de la maison de Jéshua, 973;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'les fils d’Immer, 1 052;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'les fils de Pashkhur, 1 247;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'les fils de Harim, 1 017.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Lévites: les fils de Jéshua et de Kadmiel, d’entre les fils d’Hodavia, 74.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Chantres: les fils d’Asaph, 128.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Fils des portiers: les fils de Shallum, les fils d’Ater, les fils de Talmon, les fils d’Akkub, les fils de Hatita, les fils de Shobaï, en tout 139.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Nethiniens: les fils de Tsikha, les fils de Hasupha, les fils de Tabbaoth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'les fils de Kéros, les fils de Siaha, les fils de Padon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'les fils de Lebana, les fils de Hagaba, les fils d’Akkub,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'les fils de Hagab, les fils de Shamlaï, les fils de Hanan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'les fils de Guiddel, les fils de Gakhar, les fils de Reaïa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'les fils de Retsin, les fils de Nekoda, les fils de Gazzam,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'les fils d’Uzza, les fils de Paséakh, les fils de Bésaï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'les fils d’Asna, les fils de Meünim, les fils de Nephusim,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'les fils de Bakbuk, les fils de Hakupha, les fils de Harkhur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'les fils de Batsluth, les fils de Mekhida, les fils de Harsha,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'les fils de Barkos, les fils de Sisera, les fils de Thamakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'les fils de Netsiakh, les fils de Hatipha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Fils des serviteurs de Salomon: les fils de Sotaï, les fils de Sophéreth, les fils de Peruda,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'les fils de Jaala, les fils de Darkon, les fils de Guiddel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'les fils de Shephatia, les fils de Hattil, les fils de Pokéreth-Hatsebaïm, les fils d’Ami.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Tous les Nethiniens et les fils des serviteurs de Salomon, 392.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Et voici ceux qui montèrent de Thel-Mélakh, de Thel-Harsha, de Kerub-Addan, d’Immer; mais ils ne purent pas montrer leurs maisons de pères et leur descendance, s’ils étaient d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'les fils de Delaïa, les fils de Tobija, les fils de Nekoda, 652;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'et des fils des sacrificateurs, les fils de Hobaïa, les fils d’Hakkots, les fils de Barzillaï, qui prit une femme d’entre les filles de Barzillaï, le Galaadite, et fut appelé de leur nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Ceux-ci cherchèrent leur inscription généalogique, mais elle ne se trouva pas; et ils furent exclus, comme profanes, de la sacrificature.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Et le Thirshatha leur dit qu’ils ne devaient point manger des choses très saintes, jusqu’à ce que soit suscité un sacrificateur avec les urim et les thummim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Toute la congrégation réunie était de 42 360 [personnes],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'sans compter leurs serviteurs et leurs servantes; ceux-ci [étaient au nombre de] 7 337; et parmi eux, il y avait 200 chanteurs et chanteuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Ils avaient 736 chevaux, 245 mulets,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, '435 chameaux, [et] 6 720 ânes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Et des chefs des pères, quand ils arrivèrent à la maison de l’ Éternel qui est à Jérusalem, donnèrent volontairement pour la maison de Dieu, pour la relever sur son emplacement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'ils donnèrent au trésor de l’œuvre, selon leur pouvoir, 61 000 dariques d’or, et 5 000 mines d’argent, et 100 tuniques de sacrificateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Et les sacrificateurs, et les lévites, et ceux du peuple, et les chantres, et les portiers, et les Nethiniens, habitèrent dans leurs villes: tout Israël se trouva dans ses villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, '*Et quand arriva le septième mois, les fils d’Israël étant dans leurs villes, le peuple s’assembla comme un seul homme à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Et Jéshua, fils de Jotsadak, et ses frères les sacrificateurs, et Zorobabel, fils de Shealthiel, et ses frères, se levèrent et bâtirent l’autel du Dieu d’Israël, pour y offrir des holocaustes, selon ce qui est écrit dans la loi de Moïse, homme de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Et ils établirent l’autel sur son emplacement; car la terreur des peuples de ces contrées était sur eux; et ils offrirent dessus des holocaustes à l’ Éternel, les holocaustes du matin et du soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Et ils firent la fête des tabernacles selon ce qui est écrit, et les holocaustes, jour par jour, selon leur nombre, selon l’ordonnance, le service de chaque jour en son jour,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'et après cela l’holocauste continuel, et celui des nouvelles lunes et de tous les jours solennels de l’ Éternel qui étaient sanctifiés, et [les holocaustes] de tous ceux qui offraient une offrande volontaire à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Depuis le premier jour du septième mois ils commencèrent à offrir des holocaustes à l’ Éternel; mais les fondements du temple de l’ Éternel n’étaient pas encore posés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Et ils donnèrent de l’argent aux tailleurs de pierres et aux charpentiers, et des vivres et des boissons et de l’huile aux Sidoniens et aux Tyriens, pour amener du Liban des bois de cèdre à la mer de Japho, suivant l’autorisation qu’ils avaient de Cyrus, roi de Perse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Et la seconde année de leur arrivée à la maison de Dieu à Jérusalem, au second mois, Zorobabel, fils de Shealthiel, et Jéshua, fils de Jotsadak, et le reste de leurs frères, les sacrificateurs et les lévites, et tous ceux qui étaient venus de la captivité à Jérusalem, commencèrent; et ils établirent les lévites, depuis l’âge de 20 ans et au-dessus, pour surveiller l’œuvre de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Alors Jéshua et ses fils et ses frères, Kadmiel et ses fils, les fils de Juda, se tinrent là comme un seul [homme] pour surveiller ceux qui faisaient l’ouvrage dans la maison de Dieu, [et aussi] les fils de Hénadad, leurs fils et leurs frères, les lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Et lorsque ceux qui bâtissaient posèrent les fondements du temple de l’ Éternel, on fit assister les sacrificateurs revêtus [de leurs robes], avec des trompettes, et les lévites, fils d’Asaph, avec des cymbales, pour louer l’ Éternel selon les directions de David, roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Et ils s’entre-répondaient en louant et en célébrant l’ Éternel: Car il est bon, car sa bonté envers Israël [demeure] à toujours. Et tout le peuple poussa de grands cris, en louant l’ Éternel, parce qu’on posait les fondements de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Et beaucoup d’entre les sacrificateurs, et d’entre les lévites, et d’entre les chefs des pères, les vieillards qui avaient vu la première maison, pleuraient à haute voix lorsque les fondements de cette maison furent posés devant leurs yeux, et beaucoup poussaient des cris de joie, en élevant leur voix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'et le peuple ne pouvait distinguer entre le bruit des cris de joie et la voix du peuple qui pleurait; car le peuple poussait de grands cris, et le bruit s’entendait au loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, '*Et les ennemis de Juda et de Benjamin entendirent que les fils de la transportation bâtissaient le temple de l’ Éternel, le Dieu d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'et ils s’approchèrent de Zorobabel et des chefs des pères, et leur dirent: Nous bâtirons avec vous, car nous recherchons votre Dieu, comme vous, et nous lui offrons des sacrifices depuis les jours d’Ésar-Haddon, roi d’Assyrie, qui nous a fait monter ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Et Zorobabel, et Jéshua, et le reste des chefs des pères d’Israël, leur dirent: Vous n’avez pas affaire avec nous pour bâtir une maison à notre Dieu, mais nous seuls, nous bâtirons à l’ Éternel, le Dieu d’Israël, comme nous l’a commandé le roi Cyrus, roi de Perse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Alors le peuple du pays rendit lâches les mains du peuple de Juda; et ils leur firent peur de bâtir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'et ils soudoyèrent contre eux des conseillers pour faire échouer leur plan, durant tous les jours de Cyrus, roi de Perse, et jusqu’au règne de Darius, roi de Perse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Et sous le règne d’Assuérus, au commencement de son règne, ils écrivirent une accusation contre les habitants de Juda et de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Et aux jours d’Artaxerxès, Bishlam, Mithredath, Tabeël et le reste de ses collègues, écrivirent à Artaxerxès, roi de Perse; et la lettre était écrite en écriture syriaque et traduite en syriaque:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rehum, chancelier, et Shimshaï, secrétaire, écrivirent une lettre contre Jérusalem au roi Artaxerxès, en ces termes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Alors Rehum, chancelier, et Shimshaï, secrétaire, et le reste de leurs collègues, les Dinites, les Apharsathkites, les Tarpelites, les Apharsites, les Arkévites, les Babyloniens, les Susankites, les Déhaviens, les Élamites,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'et le reste des peuplades que le grand et noble Osnappar transporta et fit habiter dans les villes de Samarie et dans le reste [du pays] de ce côté du fleuve, etc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'C’est ici la copie de la lettre qu’ils lui envoyèrent: Au roi Artaxerxès: Tes serviteurs, les hommes de ce côté du fleuve, etc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Que le roi sache que les Juifs qui sont montés de chez toi vers nous [et] sont venus à Jérusalem, bâtissent la ville rebelle et méchante, et que les murailles s’achèvent, et qu’ils restaurent les fondements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Que le roi sache donc que si cette ville est bâtie et que ses murailles s’achèvent, ils ne paieront ni tribut, ni impôt, ni péage, et, plus tard, cela portera préjudice aux rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Or comme nous mangeons le sel du palais, et qu’il n’était pas convenable pour nous de voir qu’on faisait tort au roi, à cause de cela nous avons envoyé et nous avons informé le roi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'afin qu’on cherche dans le livre des annales de tes pères: et tu trouveras dans le livre des annales et tu sauras que cette ville est une ville rebelle, et qu’elle a porté préjudice aux rois et aux provinces, et que, dès les jours anciens, on y a fait des séditions; c’est pourquoi cette ville a été détruite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Nous faisons savoir au roi que si cette ville est rebâtie et que ses murailles s’achèvent, à cause de cela, tu n’auras plus de possession de ce côté du fleuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Le roi envoya un rescrit à Rehum, chancelier, et à Shimshaï, secrétaire, et au reste de leurs collègues qui habitaient à Samarie, et dans le reste [du pays] de l’autre côté du fleuve: Paix, etc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'La lettre que vous nous avez envoyée a été lue exactement devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Et de par moi un ordre a été donné, et on a cherché, et on a trouvé que, dès les jours anciens, cette ville s’est soulevée contre les rois, et qu’il s’y est fait des révoltes et des séditions,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'et qu’il y a eu sur Jérusalem de puissants rois qui ont régné sur tout ce qui est de l’autre côté du fleuve, et que le tribut, l’impôt, et le péage leur ont été payés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Ainsi, donnez ordre de faire cesser ces hommes, et que cette ville ne soit pas bâtie, jusqu’à ce que l’ordre en soit donné de par moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Gardez-vous de manquer à faire cela: pourquoi le dommage augmenterait-il au préjudice des rois?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Alors, aussitôt que la copie de la lettre du roi Artaxerxès eut été lue devant Rehum et Shimshaï, le secrétaire, et leurs collègues, ils allèrent en hâte à Jérusalem vers les Juifs, et les firent cesser par force et par puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Alors le travail de la maison de Dieu qui est à Jérusalem cessa; et il fut arrêté jusqu’à la seconde année du règne de Darius, roi de Perse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, '*Et les prophètes, Aggée le prophète, et Zacharie, fils d’Iddo, prophétisèrent aux Juifs qui étaient en Juda et à Jérusalem, au nom du Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Alors Zorobabel, fils de Shealthiel, et Jéshua, fils de Jotsadak, se levèrent et commencèrent à bâtir la maison de Dieu qui est à Jérusalem, et avec eux, les prophètes de Dieu qui les assistaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'En ce temps-là, Thathnaï, gouverneur de ce côté du fleuve, et Shethar-Boznaï, et leurs collègues, vinrent vers eux, et leur parlèrent ainsi: Qui vous a donné ordre de bâtir cette maison et d’achever cette muraille?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Alors nous leur avons dit quels étaient les noms des hommes qui bâtissaient cet édifice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Et l’œil de leur Dieu était sur les anciens des Juifs; et ils ne les firent pas cesser jusqu’à ce que l’affaire parvienne à Darius; et alors ils répondirent par lettre à ce sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Copie de la lettre que Thathnaï, gouverneur de ce côté du fleuve, et Shethar-Boznaï et ses collègues les Apharsakites, qui étaient de ce côté du fleuve, envoyèrent au roi Darius.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Ils lui envoyèrent un rapport dans lequel il était ainsi écrit: Au roi Darius, toute paix!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Qu’il soit connu du roi que nous sommes allés dans la province de Juda, à la maison du grand Dieu; et elle se bâtit avec de grandes pierres, et le bois se pose dans les murs; et cet ouvrage se poursuit avec zèle et prospère dans leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Alors nous avons interrogé ces anciens, nous leur avons parlé ainsi: Qui vous a donné ordre de bâtir cette maison et d’achever cette muraille?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Et nous leur avons aussi demandé leurs noms pour te les faire savoir, afin de t’écrire les noms des hommes qui sont les principaux parmi eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'et ils répondirent ainsi, disant: Nous sommes les serviteurs du Dieu des cieux et de la terre, et nous bâtissons la maison qui fut bâtie anciennement, il y a bien des années; et un grand roi d’Israël l’a bâtie et achevée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Mais quand nos pères provoquèrent le Dieu des cieux, il les livra en la main de Nebucadnetsar, roi de Babylone, le Chaldéen, et il détruisit cette maison et transporta le peuple à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Mais la première année de Cyrus, roi de Babylone, le roi Cyrus donna ordre de bâtir cette maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Et aussi les ustensiles d’or et d’argent de la maison de Dieu, que Nebucadnetsar a sortis du temple qui était à Jérusalem et a emportés dans le temple de Babylone, le roi Cyrus les sortit du temple de Babylone, et les livra au nommé Sheshbatsar, qu’il avait fait gouverneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'et il lui dit: Prends ces ustensiles, va, place-les dans le temple qui est à Jérusalem, et qu’on bâtisse la maison de Dieu sur son emplacement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Alors ce Sheshbatsar est venu et a posé les fondements de la maison de Dieu qui est à Jérusalem, et depuis lors jusqu’à présent elle se bâtit; mais elle n’est pas achevée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Et maintenant, s’il semble bon au roi, qu’on recherche dans la maison des trésors du roi, qui est là à Babylone, s’il est vrai que, de par le roi Cyrus, ordre a été donné de bâtir cette maison de Dieu à Jérusalem; et que le roi nous envoie sa volonté sur cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Alors le roi Darius donna ordre, et on chercha dans la maison des archives où étaient déposés les trésors, à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Et on trouva à Akhmetha, dans la capitale qui est dans la province de Médie, un rouleau, et, dedans, un mémoire ainsi écrit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'La première année du roi Cyrus, le roi Cyrus donna l’ordre, touchant la maison de Dieu à Jérusalem: Que la maison soit bâtie pour être un lieu où l’on offre des sacrifices, et que ses fondements soient solides. Sa hauteur sera de 60 coudées, sa largeur de 60 coudées,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, '[avec] trois rangées de grandes pierres, et une rangée de bois neuf; et que les dépenses soient payées par la maison du roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'et aussi que les ustensiles d’or et d’argent de la maison de Dieu, que Nebucadnetsar a sortis du temple de Jérusalem et a emportés à Babylone, soient rendus, et qu’on les porte au temple de Jérusalem, en leur lieu; et tu les placeras dans la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Ainsi, Thathnaï, gouverneur de l’autre côté du fleuve, Shethar-Boznaï, et leurs collègues, les Apharsakites, qui êtes de l’autre côté du fleuve, tenez-vous loin de là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'laissez se faire le travail de cette maison de Dieu. Que le gouverneur des Juifs et les anciens des Juifs bâtissent cette maison de Dieu sur son emplacement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Et, de par moi, ordre est donné touchant ce que vous ferez à l’égard de ces anciens des Juifs pour la construction de cette maison de Dieu: Que, des biens du roi provenant du tribut de l’autre côté du fleuve, les dépenses soient promptement payées à ces hommes, pour qu’ils ne soient pas interrompus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'et que ce qui leur est nécessaire, jeunes taureaux, et béliers, et agneaux, pour les holocaustes au Dieu des cieux, froment, sel, vin, et huile, selon l’ordre des sacrificateurs qui sont à Jérusalem, leur soit donné, jour par jour, sans manquer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'afin qu’ils offrent de l’encens au Dieu des cieux et qu’ils prient pour la vie du roi et de ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Et de par moi ordre est donné, que si quelque homme change ce rescrit, un bois soit arraché de sa maison et dressé, et qu’il y soit attaché, et que sa maison soit réduite en un tas de fumier à cause de cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Et que le Dieu qui y a fait demeurer son nom renverse tout roi et peuple qui étendrait sa main pour changer [et] pour détruire cette maison de Dieu qui est à Jérusalem. Moi, Darius, j’ai donné [cet] ordre; qu’il soit promptement exécuté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Alors Thathnaï, gouverneur de ce côté du fleuve, Shethar-Boznaï, et leurs collègues, firent ainsi promptement, selon [l’ordre] que le roi Darius avait envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Et les anciens des Juifs bâtirent et prospérèrent par la prophétie d’Aggée, le prophète, et de Zacharie, fils d’Iddo. Et ils bâtirent et achevèrent, selon l’ordre du Dieu d’Israël et selon l’ordre de Cyrus, et de Darius, et d’Artaxerxès, roi de Perse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Et cette maison fut achevée le troisième jour du mois d’Adar: c’était la sixième année du règne du roi Darius.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Et les fils d’Israël, les sacrificateurs et les lévites, et le reste des fils de la transportation, célébrèrent la dédicace de cette maison de Dieu avec joie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'et ils offrirent pour la dédicace de cette maison de Dieu, 100 taureaux, 200 béliers, 400 agneaux, et, comme sacrifice pour le péché, pour tout Israël, douze boucs, selon le nombre des tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Et ils établirent les sacrificateurs dans leurs classes, et les lévites dans leurs divisions, pour le service de Dieu à Jérusalem, selon ce qui est écrit au livre de Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Et les fils de la transportation célébrèrent la Pâque le quatorzième [jour] du premier mois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'car les sacrificateurs et les lévites s’étaient purifiés comme un seul [homme]: ils étaient tous purs; et ils égorgèrent la pâque pour tous les fils de la transportation, et pour leurs frères les sacrificateurs, et pour eux-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Et les fils d’Israël qui étaient de retour de la transportation [en] mangèrent, et, avec eux, tous ceux qui s’étaient séparés de l’impureté des nations du pays pour rechercher l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Et ils célébrèrent la fête des pains sans levain pendant sept jours, avec joie; car l’ Éternel les avait rendus joyeux, et il avait tourné vers eux le cœur du roi d’Assyrie, pour fortifier leurs mains dans l’œuvre de la maison de Dieu, du Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, '*Et après ces choses, sous le règne d’Artaxerxès, roi de Perse, Esdras, fils de Seraïa, fils d’Azaria, fils de Hilkija,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'fils de Shallum, fils de Tsadok, fils d’Akhitub,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'fils d’Amaria, fils d’Azaria, fils de Meraïoth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'fils de Zerakhia, fils d’Uzzi, fils de Bukki,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'fils d’Abishua, fils de Phinées, fils d’Éléazar, fils d’Aaron, le chef des sacrificateurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, '– cet Esdras monta de Babylone: il était un scribe versé dans la loi de Moïse qu’avait donnée l’ Éternel, le Dieu d’Israël. Et le roi lui accorda toute sa requête, selon que la main de l’ Éternel, son Dieu, était sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, '(Et [un certain nombre] des fils d’Israël, et des sacrificateurs, et des lévites, et des chantres, et des portiers, et des Nethiniens, montèrent à Jérusalem, la septième année du roi Artaxerxès.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Et il arriva à Jérusalem, le cinquième mois; c’était la septième année du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Car le premier [jour] du premier mois le projet de partir de Babylone fut arrêté; et le premier [jour] du cinquième mois il arriva à Jérusalem, selon que la bonne main de son Dieu était sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Car Esdras avait disposé son cœur à rechercher la loi de l’ Éternel, et à la faire, et à enseigner en Israël les statuts et les ordonnances.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Et c’est ici la copie de la lettre que le roi Artaxerxès donna à Esdras le sacrificateur, le scribe, scribe des paroles des commandements de l’ Éternel et de ses statuts [donnés] à Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artaxerxès, roi des rois, à Esdras, sacrificateur, scribe accompli de la loi du Dieu des cieux, etc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'De par moi ordre est donné que tous ceux du peuple d’Israël et de ses sacrificateurs et des lévites, qui, dans mon royaume, sont disposés à aller à Jérusalem avec toi, y aillent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'puisque tu es envoyé par le roi et ses sept conseillers pour t’enquérir au sujet de Juda et de Jérusalem, selon la loi de ton Dieu, qui est dans ta main,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'et pour porter l’argent et l’or que le roi et ses conseillers ont librement offert au Dieu d’Israël, dont la demeure est à Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'ainsi que tout l’argent et l’or que tu trouveras dans toute la province de Babylone, avec l’offrande volontaire du peuple et des sacrificateurs qui offrent volontairement pour la maison de leur Dieu qui est à Jérusalem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'tu achèteras donc promptement, avec cet argent, des bœufs, des béliers, des agneaux, et leurs offrandes de gâteaux et leurs libations, et tu les offriras sur l’autel de la maison de votre Dieu, qui est à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Et ce qu’il vous paraîtra bon à toi et à tes frères de faire avec le reste de l’argent et de l’or, faites-le selon la volonté de votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Et les ustensiles qui te sont donnés pour le service de la maison de ton Dieu, remets-les devant le Dieu de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Et le reste des choses nécessaires pour la maison de ton Dieu que tu pourras avoir à donner, tu les donneras de la maison des trésors du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Et de par moi, moi Artaxerxès, le roi, ordre est donné à tous les trésoriers de l’autre côté du fleuve, de faire promptement tout ce qu’Esdras, sacrificateur, scribe de la loi du Dieu des cieux, vous demandera,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'jusqu’à 100 talents d’argent, et jusqu’à 100 cors de froment, et jusqu’à 100 baths de vin, et jusqu’à 100 baths d’huile, et du sel, sans prescription [de quantité]:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'que tout ce qui est ordonné par le Dieu des cieux soit fait exactement pour la maison du Dieu des cieux; car pourquoi y aurait-il colère contre le royaume du roi et de ses fils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Et nous vous faisons savoir que, sur tous les sacrificateurs et les lévites, chantres, portiers, Nethiniens, et serviteurs de cette maison de Dieu, il ne peut être levé aucun tribut, ni impôt, ni péage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Et toi, Esdras, selon la sagesse de ton Dieu, laquelle est en ta main, établis des magistrats et des juges qui jugeront tout le peuple de l’autre côté du fleuve, tous ceux qui connaissent les lois de ton Dieu; et à celui qui ne les connaît pas, faites-les connaître;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'et quiconque ne pratique pas la loi de ton Dieu et la loi du roi, qu’il en soit fait justice promptement, ou par la mort, ou par l’exil, ou par la confiscation de ses biens, ou par l’emprisonnement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Béni soit l’ Éternel, le Dieu de nos pères, qui a mis de telles [pensées] dans le cœur du roi, d’orner la maison de l’ Éternel qui est à Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'et qui a étendu sur moi sa bonté devant le roi, et ses conseillers, et tous les puissants princes du roi! Et moi, je fus fortifié selon que la main de l’ Éternel, mon Dieu, était sur moi, et je rassemblai d’Israël des chefs pour monter avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, '*Et voici les chefs des pères et la généalogie de ceux qui montèrent avec moi de Babylone, sous le règne du roi Artaxerxès:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'des fils de Phinées, Guershom; des fils d’Ithamar, Daniel; des fils de David, Hattush;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'des fils de Shecania, des fils de Parhosh, Zacharie, et avec lui, enregistrés par généalogies, les mâles, 150;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'des fils de Pakhath-Moab, Élioénaï, fils de Zerakhia, et avec lui 200 hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'des fils de Shecania, le fils de Jakhaziel, et avec lui 300 hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'et des fils d’Adin, Ébed, fils de Jonathan, et avec lui 50 hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'et des fils d’Élam, Ésaïe, fils d’Athalia, et avec lui 70 hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'et des fils de Shephatia, Zebadia, fils de Micaël, et avec lui 80 hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, '[et] des fils de Joab, Abdias, fils de Jekhiel, et avec lui 218 hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'et des fils de Shelomith, le fils de Josiphia, et avec lui 160 hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'et des fils de Bébaï, Zacharie, fils de Bébaï, et avec lui 28 hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'et des fils d’Azgad, Jokhanan, fils d’Hakkatan, et avec lui 110 hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'et des fils d’Adonikam, les derniers, et ce sont ici leurs noms: Éliphéleth, Jehiel, et Shemahia, et avec eux 60 hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'et des fils de Bigvaï, Uthaï et Zabbud, et avec eux 70 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Et je les rassemblai vers le fleuve qui s’en va vers Ahava, et nous avons campé là trois jours; et je considérai le peuple et les sacrificateurs, et je n’y trouvai aucun des fils de Lévi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Alors j’envoyai chercher Éliézer, Ariel, Shemahia, et Elnathan, et Jarib, et Elnathan, et Nathan, et Zacharie, et Meshullam, qui étaient des chefs, et Joïarib, et Elnathan, hommes intelligents;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'et je les envoyai à Iddo, qui était chef dans la localité [appelée] Casiphia, et je mis dans leurs bouches des paroles pour les dire à Iddo [et] à ses frères, les Nethiniens, dans la localité [appelée] Casiphia, pour nous amener des serviteurs pour la maison de notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Et ils nous amenèrent, selon que la bonne main de notre Dieu était sur nous, un homme intelligent d’entre les fils de Makhli, fils de Lévi, fils d’Israël, et Shérébia et ses fils et ses frères, [au nombre de] 18;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'et Hashabia, et avec lui Ésaïe, d’entre les fils de Merari, ses frères et leurs fils, [au nombre de] 20;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'et des Nethiniens, que David et les princes avaient donnés pour le service des lévites, 220 Nethiniens, tous désignés par [leurs] noms.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Et là, près du fleuve Ahava, je publiai un jeûne, pour nous humilier devant notre Dieu, pour lui demander le vrai chemin, pour nous et pour nos enfants, et pour tout notre avoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Car j’avais honte de demander au roi des forces et de la cavalerie pour nous aider en chemin contre l’ennemi; car nous avions parlé au roi, en disant: La main de notre Dieu est en bien sur tous ceux qui le cherchent; et sa force et sa colère sont contre tous ceux qui l’abandonnent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Et nous avons jeûné, et nous avons demandé cela à notre Dieu, et il nous exauça.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Et je séparai douze des chefs des sacrificateurs, Shérébia, Hashabia, et dix de leurs frères avec eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'et je leur pesai l’argent et l’or, et les ustensiles, l’offrande pour la maison de notre Dieu, qu’avaient offerte le roi, et ses conseillers, et ses princes, et tout Israël qui se trouvait là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Et je pesai en leurs mains 650 talents d’argent, et en ustensiles d’argent 100 talents, [et] en or 100 talents,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'et 20 coupes d’or valant 1 000 dariques, et deux vases d’airain d’un beau brillant, précieux comme l’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Et je leur dis: Vous êtes saints, [consacrés] à l’ Éternel, et les ustensiles sont saints, et l’argent et l’or sont une offrande volontaire à l’ Éternel, le Dieu de vos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Veillez, et gardez-les jusqu’à ce que vous les pesiez devant les chefs des sacrificateurs et des lévites, et devant les chefs des pères d’Israël à Jérusalem, dans les chambres de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Et les sacrificateurs et les lévites reçurent au poids l’argent et l’or, et les ustensiles, pour les porter à Jérusalem, à la maison de notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Et nous sommes partis du fleuve Ahava le douzième [jour] du premier mois, pour aller à Jérusalem. Et la main de notre Dieu fut sur nous, et il nous délivra de la main de l’ennemi et de [toute] embûche sur le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Et nous sommes arrivés à Jérusalem, et nous sommes demeurés là trois jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Et le quatrième jour, l’argent et l’or et les ustensiles furent pesés dans la maison de notre Dieu, entre les mains de Merémoth, fils d’Urie, le sacrificateur (et avec lui [était] Éléazar, fils de Phinées, et avec eux Jozabad, fils de Jéshua, et Noadia, fils de Binnuï, lévites),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'selon le nombre [et] selon le poids du tout; et en même temps tout le poids en fut inscrit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Les fils de la transportation qui étaient revenus de la captivité présentèrent des holocaustes au Dieu d’Israël, douze taureaux pour tout Israël, 96 béliers, 77 agneaux, douze boucs en sacrifice pour le péché, le tout en holocauste à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Et ils remirent les édits du roi aux satrapes du roi et aux gouverneurs de ce côté du fleuve, et ceux-ci donnèrent leur appui au peuple et à la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, '*Et quand ces choses furent terminées, les chefs s’approchèrent de moi, en disant: Le peuple d’Israël, et les sacrificateurs et les lévites, ne se sont pas séparés des peuples des pays, quant à leurs abominations, [savoir] celles des Cananéens, des Héthiens, des Phéréziens, des Jébusiens, des Ammonites, des Moabites, des Égyptiens, et des Amoréens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'car ils ont pris de leurs filles pour eux et pour leurs fils, et ont mêlé la semence sainte avec les peuples des pays; et la main des chefs et des gouverneurs a été la première dans ce péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Et quand j’entendis cela, je déchirai mon manteau et ma robe, et j’arrachai les cheveux de ma tête et ma barbe, et je m’assis désolé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'et vers moi s’assemblèrent tous ceux qui tremblaient aux paroles du Dieu d’Israël, à cause du péché de ceux qui avaient été transportés; et je restai assis, désolé, jusqu’à l’offrande du soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Et lors de l’offrande du soir, je me levai de mon humiliation, et, mon manteau et ma robe déchirés, je m’agenouillai, et j’étendis mes mains vers l’ Éternel, mon Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'et je dis: Mon Dieu, je suis confus, et j’ai honte de lever ma face vers toi, ô mon Dieu; car nos iniquités se sont multipliées par-dessus nos têtes, et notre culpabilité a grandi jusqu’aux cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Dès les jours de nos pères jusqu’à ce jour, nous avons été grandement coupables; et à cause de nos iniquités, nous, nos rois, nos sacrificateurs, nous avons été livrés en la main des rois des pays, à l’épée, à la captivité, et au pillage, et à la confusion de face, comme [il paraît] aujourd’hui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'et maintenant, pour un moment, nous est arrivée une faveur de la part de l’ Éternel, notre Dieu, pour nous laisser des réchappés et pour nous donner un clou dans son saint lieu, afin que notre Dieu éclaire nos yeux et nous redonne un peu de vie dans notre servitude,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'car nous sommes serviteurs; mais, dans notre servitude, notre Dieu ne nous a pas abandonnés, et il a étendu sa bonté sur nous devant les rois de Perse, afin de nous redonner de la vie pour élever la maison de notre Dieu et pour restaurer ses ruines, et pour nous donner des murs en Juda et à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Et maintenant, ô notre Dieu, que dirons-nous après cela? Car nous avons abandonné tes commandements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'que tu as commandés par tes serviteurs les prophètes, en disant: Le pays dans lequel vous entrez pour le posséder, est un pays rendu impur par l’impureté des peuples des pays, par les abominations dont ils l’ont rempli d’un bout à l’autre par leurs souillures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Et maintenant, ne donnez pas vos filles à leurs fils, et ne prenez pas leurs filles pour vos fils, et ne cherchez pas leur paix ou leur bien, à jamais, afin que vous soyez forts, et que vous mangiez les biens du pays, et que vous les laissiez en possession à vos fils à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Et après tout ce qui nous est arrivé à cause de nos mauvaises œuvres et à cause de notre grand péché...; mais toi, notre Dieu, tu nous as moins punis que ne méritaient nos iniquités, et tu nous as donné une délivrance comme celle-ci;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, '– est-ce que nous retournerions à enfreindre tes commandements et à nous allier par mariage avec les peuples qui font ces abominations? Ne serais-tu pas courroucé contre nous jusqu’à nous consumer, en sorte qu’il n’y aurait ni reste ni réchappés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Éternel, Dieu d’Israël, tu es juste, car nous sommes un reste de réchappés, comme [il paraît] aujourd’hui. Nous voici devant toi dans notre culpabilité, car, à cause de cela, on ne peut se tenir devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Et comme Esdras priait et faisait sa confession, pleurant et se prosternant devant la maison de Dieu, il se rassembla vers lui, d’Israël, une très grande congrégation d’hommes et de femmes et d’enfants, car le peuple pleurait beaucoup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Et Shecania, fils de Jekhiel, des fils d’Élam, prit la parole et dit à Esdras: Nous avons été infidèles à notre Dieu, et nous avons pris des femmes étrangères d’entre les peuples du pays. Mais maintenant, il y a espérance pour Israël à cet égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Et maintenant, faisons alliance avec notre Dieu pour renvoyer toutes les femmes et ceux qui sont nés d’elles, selon le conseil de mon seigneur et de ceux qui tremblent aux commandements de notre Dieu, et qu’il soit fait selon la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Lève-toi, car la chose repose sur toi, et nous serons avec toi; sois fort et agis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Et Esdras se leva, et il fit jurer aux chefs des sacrificateurs, des lévites, et de tout Israël, d’agir selon cette parole; et ils jurèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Et Esdras se leva de devant la maison de Dieu, et alla dans la chambre de Jokhanan, fils d’Éliashib; et il entra là: il ne mangea point de pain et ne but point d’eau, car il menait deuil sur le péché de ceux qui avaient été transportés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Et on fit passer en Juda et à Jérusalem un appel à tous les fils de la transportation de se rassembler à Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'et pour que quiconque ne viendrait pas dans les trois jours selon le conseil des chefs et des anciens, tous ses biens soient confisqués, et que lui-même soit séparé de la congrégation de ceux qui avaient été transportés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Et tous les hommes de Juda et de Benjamin se rassemblèrent à Jérusalem dans les trois jours: c’était le neuvième mois, le vingtième [jour] du mois; et tout le peuple était assis dans la place de la maison de Dieu, tremblant à cause de cette affaire et à cause des pluies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Et Esdras, le sacrificateur, se leva et leur dit: Vous avez été infidèles, et vous avez pris des femmes étrangères, pour ajouter à la culpabilité d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Et maintenant, faites confession à l’ Éternel, le Dieu de vos pères, et faites ce qui lui est agréable, et séparez-vous des peuples du pays et des femmes étrangères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Et toute la congrégation répondit et dit à haute voix: Oui, à nous de faire selon tes paroles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'mais le peuple est nombreux, et c’est la saison des pluies, et il n’y a pas moyen de se tenir dehors; et ce n’est pas l’œuvre d’un jour ni de deux, car nous avons grandement péché dans cette affaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Que nos chefs donc, pendant cette affaire, se tiennent là pour toute la congrégation, et que tous ceux qui, dans nos villes, ont pris des femmes étrangères, viennent à des époques déterminées, et avec eux les anciens de chaque ville et ses juges, jusqu’à ce que l’ardeur de la colère de notre Dieu soit détournée de nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Seuls, Jonathan, fils d’Asçaël, et Jakhzia, fils de Thikva, s’opposèrent à cela; et Meshullam, et Shabthaï, le lévite, les appuyèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Et les fils de la transportation firent ainsi. Et Esdras, le sacrificateur, et des hommes qui étaient chefs des pères, furent séparés selon leurs maisons de pères, et tous par leurs noms. Et ils s’assirent le premier jour du dixième mois pour examiner l’affaire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'et, le premier jour du premier mois, ils en eurent fini avec tous les hommes qui avaient pris des femmes étrangères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Et, parmi les fils des sacrificateurs, il s’en trouva qui avaient pris des femmes étrangères: des fils de Jéshua, fils de Jotsadak, et de ses frères: Maascéïa, et Éliézer, et Jarib, et Guedalia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Et ils s’engagèrent à renvoyer leurs femmes, et ils offrirent pour leur faute, un bélier du troupeau comme offrande pour le délit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Et des fils d’Immer: Hanani et Zebadia;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'et des fils de Harim, Maascéïa, et Élie, et Shemahia, et Jekhiel, et Ozias;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'et des fils de Pashkhur, Élioénaï, Maascéïa, Ismaël, Nethaneël, Jozabad et Elhasça.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Et des lévites: Jozabad, et Shimhi, et Kélaïa (c’est Kelita), Pethakhia, Juda, et Éliézer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Et des chantres: Éliashib. Et des portiers: Shallum, et Télem, et Uri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Et de ceux d’Israël: des fils de Parhosh, Ramia, et Jizzija, et Malkija, et Mijamin, et Éléazar, et Malkija, et Benaïa;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'et des fils d’Élam, Matthania, Zacharie, et Jekhiel, et Abdi, et Jerémoth, et Élie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'et des fils de Zatthu, Élioénaï, Éliashib, Matthania, et Jerémoth, et Zabad, et Aziza;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'et des fils de Bébaï, Jokhanan, Hanania, Zabbaï, Athlaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'et des fils de Bani, Meshullam, Malluc et Adaïa, Jashub, et Sheal, et Ramoth;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'et des fils de Pakhath-Moab, Adna et Kelal, Benaïa, Maascéïa, Matthania, Betsaleël, et Binnuï, et Manassé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'et les fils de Harim, Éliézer, Jishija, Malkija, Shemahia, Siméon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluc, Shemaria;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'des fils de Hashum, Mathnaï, Matthattha, Zabad, Éliphéleth, Jerémaï, Manassé, Shimhi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'des fils de Bani, Maadaï, Amram et Uel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaïa, Bédia, Keluhu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vania, Merémoth, Éliashib,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Matthania, Mathnaï, et Jaasçaï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'et Bani, et Binnuï, Shimhi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'et Shélémia, et Nathan, et Adaïa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Macnadbaï, Shashaï, Sharaï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azareël et Shélémia, Shemaria,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Shallum, Amaria, Joseph;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'des fils de Nebo, Jehiel, Matthithia, Zabad, Zebina, Jaddaï et Joël, Benaïa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Tous ceux-ci avaient pris des femmes étrangères, et il y en avait parmi eux dont les femmes avaient eu des enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Les paroles de Néhémie, fils de Hacalia. Et au mois de Kislev, la vingtième année, il arriva que, comme j’étais à Suse, la capitale,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Hanani, l’un de mes frères, lui et quelques hommes vinrent de Juda; et je les interrogeai sur les Juifs, les réchappés qui étaient restés de la captivité, et au sujet de Jérusalem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'et ils me dirent: Les restants, qui sont demeurés de reste de la captivité, là, dans la province, sont dans une grande misère et dans l’opprobre, et la muraille de Jérusalem est en ruine et ses portes sont brûlées par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Et lorsque j’entendis ces paroles, je m’assis et je pleurai; et je menai deuil [plusieurs] jours, et je jeûnai, et je priai le Dieu des cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'et je dis: Je te supplie, ô Éternel, Dieu des cieux, le ✶Dieu grand et terrible, qui gardes l’alliance et la bonté envers ceux qui t’aiment et qui gardent tes commandements!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Je te prie, que ton oreille soit attentive et que tes yeux soient ouverts, pour écouter la prière de ton serviteur que je fais aujourd’hui devant toi, jour et nuit, pour les fils d’Israël tes serviteurs, et la confession [que je fais] touchant les péchés des fils d’Israël, que nous avons commis contre toi; moi aussi et la maison de mon père, nous avons péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Nous avons très mal agi contre toi, et nous n’avons pas gardé les commandements et les statuts et les ordonnances que tu as commandés à ton serviteur Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Souviens-toi, je te prie, de la parole que tu as commandée à ton serviteur Moïse, en disant: Si vous êtes infidèles, je vous disperserai parmi les peuples;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'et si vous revenez à moi, et que vous gardiez mes commandements et que vous les pratiquiez, quand vos dispersés seraient au bout des cieux, je les rassemblerai de là et je les ramènerai au lieu que j’ai choisi pour y faire demeurer mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Et ils sont tes serviteurs et ton peuple, que tu as rachetés par ta grande puissance et ta main forte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Je te supplie, Seigneur, que ton oreille soit attentive à la prière de ton serviteur, et à la prière de tes serviteurs qui prennent plaisir à craindre ton nom; et fais réussir aujourd’hui ton serviteur, je te prie, et donne-lui de trouver miséricorde devant cet homme. Or j’étais échanson du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, '*Et il arriva au mois de Nisan, la vingtième année du roi Artaxerxès, comme le vin était devant lui, que je pris le vin et le donnai au roi; et je n’avais pas été triste en sa présence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Et le roi me dit: Pourquoi as-tu mauvais visage, et pourtant tu n’es pas malade? Cela n’est rien que de la tristesse de cœur. Alors j’eus extrêmement peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Et je dis au roi: Que le roi vive à toujours! Pourquoi mon visage ne serait-il pas triste, quand la ville, le lieu des sépulcres de mes pères, est dévastée, et que ses portes sont consumées par le feu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Et le roi me dit: Que demandes-tu? Et je priai le Dieu des cieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'et je dis au roi: Si le roi le trouve bon, et si ton serviteur est agréable devant toi, qu’il m’envoie en Juda, à la ville des sépulcres de mes pères, et je la bâtirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Alors le roi me dit – et la reine était assise à son côté: – Combien de temps durera ton voyage, et quand reviendras-tu? Et il plut au roi de m’envoyer, et je lui fixai un temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Et je dis au roi: Si le roi le trouve bon, qu’il me donne des lettres pour les gouverneurs de l’autre côté du fleuve, pour qu’ils me fassent passer jusqu’à ce que j’arrive en Juda,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'et une lettre pour Asaph, gardien de la forêt du roi, afin qu’il me donne du bois pour faire la charpente des portes du château fort attenant à la maison, et pour la muraille de la ville, et pour la maison dans laquelle je dois entrer. Et le roi me les donna, selon que la bonne main de mon Dieu était sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Et je vins auprès des gouverneurs de l’autre côté du fleuve, et je leur donnai les lettres du roi; or le roi avait envoyé avec moi des chefs de l’armée et des cavaliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Et quand Sanballat, le Horonite, et Tobija, le serviteur ammonite, l’apprirent, ils furent très mécontents de ce qu’un homme soit venu pour chercher le bien des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Et j’arrivai à Jérusalem, et je fus là trois jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Et je me levai de nuit, moi et le peu d’hommes qui étaient avec moi, – et je n’avais informé personne de ce que mon Dieu m’avait mis au cœur de faire pour Jérusalem – et je n’avais pas de bête avec moi, sinon la bête que je montais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Et je sortis de nuit, par la porte de la vallée, en face de la source du chacal, vers la porte du fumier; et je considérai les murailles de Jérusalem qui étaient en ruine, et ses portes consumées par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Et je passai à la porte de la fontaine, et à l’étang du roi, et il n’y avait pas de place où puisse passer la bête qui était sous moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Et je montai de nuit par le torrent, et je considérai la muraille; et je m’en revins, et entrai par la porte de la vallée, et je m’en retournai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Or les chefs ne savaient pas où j’étais allé, ni ce que je faisais; et jusque-là je n’avais rien communiqué aux Juifs, ni aux sacrificateurs, ni aux nobles, ni aux chefs, ni aux autres qui s’occupaient de l’œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Et je leur dis: Vous voyez la misère dans laquelle nous sommes, que Jérusalem est dévastée et que ses portes sont brûlées par le feu. Venez et bâtissons la muraille de Jérusalem, afin que nous ne soyons plus dans l’opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Et je leur racontai comment la main de mon Dieu avait été bonne sur moi, et aussi les paroles du roi qu’il m’avait dites. Et ils dirent: Levons-nous et bâtissons. Et ils fortifièrent leurs mains pour bien faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Et quand Sanballat, le Horonite, et Tobija, le serviteur ammonite, et Guéshem, l’Arabe, l’apprirent, ils se moquèrent de nous et nous méprisèrent, et ils dirent: Qu’est-ce que vous faites là? Voulez-vous vous révolter contre le roi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Et je leur répondis et je leur dis: Le Dieu des cieux, lui, nous fera prospérer, et nous, ses serviteurs, nous nous lèverons et nous bâtirons; mais vous, vous n’avez ni part, ni droit, ni souvenir à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, '*Alors Éliashib, le grand sacrificateur, et ses frères, les sacrificateurs, se levèrent et bâtirent la porte des brebis; ils la sanctifièrent, et en posèrent les battants; et ils la sanctifièrent jusqu’à la tour de Méa, jusqu’à la tour de Hananeël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Et à côté d’eux bâtirent les hommes de Jéricho; et à côté d’eux bâtit Zaccur, fils d’Imri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Et les fils de Senaa bâtirent la porte des poissons; ils en firent la charpenterie, et en posèrent les battants, les verrous et les barres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Et à côté d’eux répara Merémoth, fils d’Urie, fils d’Hakkots. Et à côté d’eux répara Meshullam, fils de Bérékia, fils de Meshézabeël. Et à côté d’eux répara Tsadok, fils de Baana.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Et à côté d’eux réparèrent les Thekohites; mais les principaux d’entre eux ne plièrent pas leur cou au service de leur Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Et Jehoïada, fils de Paséakh, et Meshullam, fils de Besodia, réparèrent la porte du vieux [mur]; ils en firent la charpenterie, et en posèrent les battants, et les verrous et les barres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Et à côté d’eux réparèrent Melatia, le Gabaonite, et Jadon, le Méronothite, les hommes de Gabaon et de Mitspa, vers le siège du gouverneur de l’autre côté du fleuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'À côté d’eux répara Uziel, fils de Harhaïa, [l’un] des orfèvres; et à côté de lui répara Hanania, d’entre les parfumeurs; et ils laissèrent Jérusalem [en son état], jusqu’à la muraille large.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Et à côté d’eux répara Rephaïa, fils de Hur, chef de la moitié du district de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Et à côté d’eux répara Jedaïa, fils de Harumaph, savoir vis-à-vis de sa maison. Et à côté de lui répara Hattush, fils de Hashabnia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Malkija, fils de Harim, et Hashub, fils de Pakhath-Moab, réparèrent une seconde portion et la tour des fours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Et à côté d’eux réparèrent Shallum, fils d’Hallokhesh, chef de la moitié du district de Jérusalem, lui et ses filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Hanun et les habitants de Zanoakh réparèrent la porte de la vallée; ils la bâtirent et posèrent ses battants, ses verrous et ses barres, et [firent] 1 000 coudées de la muraille, jusqu’à la porte du fumier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Et Malkija, fils de Récab, chef du district de Beth-Hakkérem, répara la porte du fumier; il la bâtit et posa ses battants, ses verrous et ses barres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Et Shallun, fils de Col-Hozé, chef du district de Mitspa, répara la porte de la fontaine; il la bâtit et la couvrit, et posa ses battants, ses verrous et ses barres; [il fit] aussi la muraille de l’étang de Siloé, près du jardin du roi, et jusqu’aux degrés qui descendent de la ville de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Après lui Néhémie, fils d’Azbuk, chef de la moitié du district de Beth-Tsur, répara jusque vis-à-vis des sépulcres de David, et jusqu’à l’étang qui avait été fait, et jusqu’à la maison des hommes forts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Et après lui réparèrent les Lévites: Rehum, fils de Bani. À côté de lui Hashabia, chef de la moitié du district de Kehila, répara pour son district.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Après lui réparèrent leurs frères, Bavvaï, fils de Hénadad, chef de la moitié du district de Kehila.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Et, à côté de lui, Ézer, fils de Jéshua, chef de Mitspa, répara une seconde portion, vis-à-vis de la montée de l’arsenal de l’angle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Après lui, Baruc, fils de Zabbaï, répara avec zèle une autre portion, depuis l’angle jusqu’à l’entrée de la maison d’Éliashib, le grand sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Après lui Merémoth, fils d’Urie, fils d’Hakkots, répara une autre portion, depuis l’entrée de la maison d’Éliashib jusqu’au bout de la maison d’Éliashib.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Et après lui réparèrent les sacrificateurs, hommes de la plaine [du Jourdain].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Après eux, Benjamin et Hashub réparèrent vis-à-vis de leur maison. Après eux, Azaria, fils de Maascéïa, fils d’Anania, répara à côté de sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Après lui, Binnuï, fils de Hénadad, répara une seconde portion, depuis la maison d’Azaria jusqu’à l’angle et jusqu’au coin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, fils d’Uzaï, [répara] vis-à-vis de l’angle et de la haute tour saillante de la maison du roi, qui touche à la cour de la prison. Après lui [répara] Pedaïa, fils de Parhosh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, '(Or les Nethiniens demeuraient en Ophel, jusque vis-à-vis de la porte des eaux au levant, et de la tour saillante.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Après lui, les Thekohites réparèrent une seconde portion, vis-à-vis de la grande tour saillante, et jusqu’au mur d’Ophel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Les sacrificateurs réparèrent au-dessus de la porte des chevaux, chacun vis-à-vis de sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Après eux, Tsadok, fils d’Immer, répara vis-à-vis de sa maison. Et après lui répara Shemahia, fils de Shecania, gardien de la porte du levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Après lui, Hanania, fils de Shélémia, et Hanun, sixième fils de Tsalaph, réparèrent une seconde portion. Après eux, Meshullam, fils de Bérékia, répara vis-à-vis de sa demeure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Après lui, Malkija, d’entre les orfèvres, répara jusqu’à la maison des Nethiniens et des commerçants, vis-à-vis de la porte de Miphkad, et jusqu’à la montée du coin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Et entre la montée du coin et la porte des brebis réparèrent les orfèvres et les commerçants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 33, '*Et il arriva que, lorsque Sanballat apprit que nous bâtissions la muraille, il se mit en colère et fut extrêmement irrité, et il se moqua des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 34, 'Et il parla devant ses frères et devant l’armée de Samarie, et dit: Que font ces faibles Juifs? Les laissera-t-on faire? Offriront-ils des sacrifices? Achèveront-ils en un jour? Feront-ils revivre les pierres des monceaux de poussière, quand elles sont brûlées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 35, 'Et Tobija, l’Ammonite, était à côté de lui, et il dit: Au reste, pour ce que ceux-ci bâtissent, si un renard y montait, il ferait crouler leur muraille de pierres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 36, '– Écoute, ô notre Dieu, car nous sommes méprisés, et fais retomber leur outrage sur leurs propres têtes, et livre-les au mépris dans un pays de captivité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 37, 'et ne couvre pas leur iniquité, et que leur péché ne soit pas effacé de devant toi, car ils ont provoqué ceux qui bâtissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 38, 'Mais nous avons rebâti la muraille, et toute la muraille fut reliée jusqu’à la moitié; et le peuple avait le cœur au travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Mais il arriva que, lorsque Sanballat et Tobija, et les Arabes, et les Ammonites, et les Asdodiens, apprirent que la réparation des murs de Jérusalem avançait, que les brèches commençaient à se fermer, ils se mirent dans une grande colère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'et ils se liguèrent tous ensemble pour venir faire la guerre contre Jérusalem et pour lui causer du dommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Et nous avons prié notre Dieu, et nous avons établi une garde contre eux, jour et nuit, à cause d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Et Juda dit: Les forces des porteurs de fardeaux faiblissent, et il y a beaucoup de décombres: nous ne pouvons bâtir la muraille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Et nos ennemis disaient: Ils ne le sauront pas et ne le verront pas, jusqu’à ce que nous arrivions au milieu d’eux: et nous les tuerons, et nous ferons cesser l’ouvrage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Et il arriva que, comme les Juifs qui habitaient près d’eux vinrent et nous le dirent par dix fois, de tous les lieux d’où ils revenaient vers nous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'j’établis [des postes] dans les endroits bas, dans l’espace derrière la muraille, en des lieux découverts, et je plaçai le peuple par familles avec leurs épées, leurs piques et leurs arcs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Et je regardai et je me levai, et je dis aux nobles et aux chefs, et au reste du peuple: Ne les craignez pas; souvenez-vous du Seigneur, qui est grand et terrible, et combattez pour vos frères, pour vos fils et pour vos filles, pour vos femmes et pour vos maisons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Et quand nos ennemis apprirent que nous étions informés, et que Dieu avait dissipé leur conseil, il arriva que nous sommes tous retournés à la muraille, chacun à son travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Et, dès ce jour-là, la moitié de mes jeunes hommes travaillait à l’œuvre, et la moitié tenait les piques, et les boucliers, et les arcs, et les cuirasses; et les chefs étaient derrière toute la maison de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Ceux qui bâtissaient la muraille, et ceux qui portaient les fardeaux [et] ceux qui les chargeaient, faisaient le travail d’une main, et, de l’autre main, tenaient une arme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Et ceux qui bâtissaient avaient chacun leur épée ceinte sur leurs reins et bâtissaient, et celui qui sonnait de la trompette était à côté de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Et je dis aux nobles et aux chefs, et au reste du peuple: L’ouvrage est grand et étendu, et nous sommes épars sur la muraille, éloignés l’un de l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Au lieu où vous entendrez le son de la trompette, là, rassemblez-vous vers nous; notre Dieu combattra pour nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Ainsi nous faisions l’ouvrage; et la moitié d’entre eux tenait les piques depuis le lever de l’aurore jusqu’à l’apparition des étoiles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Dans ce temps-là aussi je dis au peuple: Que chacun, avec son serviteur, passe la nuit à l’intérieur de Jérusalem, afin que de nuit ils nous soient une garde, et que de jour [ils fassent] le travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Et ni moi, ni mes frères, ni mes jeunes hommes, ni les hommes de la garde qui me suivaient, nous n’avons ôté nos vêtements; chacun [avait] son arme à sa droite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Et il y eut un grand cri du peuple et de leurs femmes contre les Juifs, leurs frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Et il y en avait qui disaient: Nous, nos fils et nos filles, nous sommes nombreux, et nous demandons du blé afin que nous mangions et que nous vivions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Et il y en avait qui disaient: Nous avons dû engager nos champs et nos vignes et nos maisons pour nous procurer du blé dans la disette.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Et il y en avait qui disaient: Nous avons emprunté de l’argent sur nos champs et nos vignes pour le tribut du roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'et pourtant notre chair est comme la chair de nos frères, nos fils comme leurs fils; et voici, nous réduisons nos fils et nos filles à la servitude, et parmi nos filles, il y en a qui sont [déjà] asservies, et il n’est pas au pouvoir de nos mains [de les racheter], car nos champs et nos vignes sont à d’autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Et je fus très irrité lorsque j’entendis leur cri et ces paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Et mon cœur se consulta sur cela, et je querellai les nobles et les chefs, et je leur dis: Vous exigez de l’intérêt, chacun de son frère! Et je leur opposai une grande congrégation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'et je leur dis: Nous avons racheté, selon notre pouvoir, nos frères, les Juifs, qui avaient été vendus aux nations; et vous voulez vous-mêmes vendre vos frères? Et c’est à nous qu’ils se vendraient? Et ils se turent et ne trouvèrent rien à dire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Et je dis: Ce que vous faites n’est pas bien. Ne devriez-vous pas marcher dans la crainte de notre Dieu, pour n’être pas dans l’opprobre parmi les nations qui nous sont ennemies?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Moi aussi, mes frères et mes jeunes hommes, nous pourrions exiger d’eux, comme intérêt, de l’argent et du blé. Laissons, je vous prie, cette usure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Rendez-leur, aujourd’hui même, je vous prie, leurs champs, leurs vignes, leurs oliviers et leurs maisons, et le centième de l’argent et du blé, du moût et de l’huile, que vous avez exigé d’eux comme intérêt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Et ils dirent: Nous les rendrons et nous ne leur demanderons rien; nous ferons ainsi, comme tu l’as dit. Et j’appelai les sacrificateurs, et je les fis jurer de faire selon cette parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Je secouai aussi le pan de ma robe, et je dis: Que Dieu secoue ainsi de sa maison et du fruit de son labeur quiconque n’accomplira pas cette parole, et qu’il soit ainsi secoué et à vide! Et toute la congrégation dit: Amen! Et ils louèrent l’ Éternel. Et le peuple fit selon cette parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Dès le jour aussi où je fus établi leur gouverneur dans le pays de Juda, depuis la vingtième année jusqu’à la trente-deuxième année du roi Artaxerxès, pendant douze ans, ni moi, ni mes frères, nous n’avons mangé le pain du gouverneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Mais les gouverneurs précédents qui avaient été avant moi, avaient été à charge au peuple, et ils avaient pris d’eux du pain et du vin, et, de plus, 40 sicles d’argent; leurs jeunes hommes aussi dominaient sur le peuple. Mais moi, je n’ai pas fait ainsi, à cause de la crainte de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Et j’ai aussi tenu ferme, dans ce travail de la muraille, et nous n’avons acheté aucun champ, et tous mes jeunes hommes étaient rassemblés là pour l’ouvrage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'J’avais aussi à ma table 150 Juifs et chefs, outre ceux qui nous venaient du milieu des nations qui nous entouraient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Or ce qui m’était apprêté pour un jour, c’était un bœuf, [et] six moutons choisis; on m’apprêtait aussi de la volaille, et, tous les dix jours, toutes sortes de vins en abondance; et avec cela, je n’ai point réclamé le pain du gouverneur, parce que le service pesait lourdement sur ce peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Souviens-toi en bien pour moi, ô mon Dieu, de tout ce que j’ai fait pour ce peuple!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Et il arriva que, lorsque Sanballat, et Tobija, et Guéshem, l’Arabe, et le reste de nos ennemis, apprirent que j’avais bâti la muraille et qu’il n’y restait aucune brèche, quoique jusqu’à ce temps-là je n’aie pas posé les battants aux portes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Sanballat et Guéshem m’envoyèrent dire: Viens et rencontrons-nous ensemble dans les villages de la vallée d’Ono. Mais ils pensaient à me faire du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Et je leur envoyai des messagers, disant: Je fais un grand travail et je ne puis descendre. Pourquoi le travail cesserait-il pendant que je le quitterais et que je descendrais vers vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Et ils m’envoyèrent dire la même chose quatre fois, et je leur répondis de la même manière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Et Sanballat m’envoya son serviteur, une cinquième fois, de la même manière, une lettre ouverte à la main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Il y était écrit: On entend dire parmi les nations, et Gashmu le dit, que toi et les Juifs vous pensez à vous révolter; c’est pour cela que tu bâtis la muraille; et, d’après ces dires, c’est toi qui deviendras leur roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Et même tu as établi des prophètes pour proclamer et dire de toi dans Jérusalem: Il y a un roi en Juda! Et maintenant, on fera entendre au roi ces mêmes choses; viens donc maintenant, et tenons conseil ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Et je lui envoyai dire: Aucune des choses dont tu parles n’a eu lieu; mais tu les inventes dans ton propre cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Car ils voulaient tous nous effrayer, disant: Leurs mains se lasseront du travail, et il ne se fera pas. Maintenant donc, fortifie mes mains!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Et moi, je vins à la maison de Shemahia, fils de Delaïa, fils de Mehétabeël (et il s’était enfermé); et il dit: Rencontrons-nous dans la maison de Dieu, à l’intérieur du temple, et fermons les portes du temple, car ils vont venir pour te tuer, et c’est de nuit qu’ils vont venir pour te tuer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Et je dis: Un homme comme moi fuirait-il? Et quel homme comme moi entrerait dans le temple et vivrait? Je n’entrerai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Et je reconnus que, voici, ce n’était pas Dieu qui l’avait envoyé, car il prononçait cette prophétie contre moi, et Tobija et Sanballat le soudoyaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'C’est pour cela qu’il était payé, pour que j’aie peur et que je fasse ainsi et pèche, et qu’ils aient de quoi me faire un mauvais renom, afin de me couvrir d’opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Souviens-toi, ô Dieu, de Tobija et de Sanballat selon ces œuvres qu’ils ont faites; et aussi de Noadia, la prophétesse, et du reste des prophètes qui voulaient m’effrayer!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Et la muraille fut achevée le vingt-cinquième [jour du mois] d’Élul, en 52 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Et il arriva que, lorsque tous nos ennemis l’apprirent, toutes les nations qui nous environnaient craignirent et furent fort abaissées à leurs propres yeux, et elles reconnurent que cette œuvre avait été faite de par notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'En ces jours-là aussi, des nobles de Juda envoyèrent lettres sur lettres à Tobija, et celles de Tobija leur arrivaient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'car plusieurs en Juda lui avaient prêté serment, car il était gendre de Shecania, fils d’Arakh, et Jokhanan, son fils, avait pris la fille de Meshullam, fils de Bérékia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Ils disaient aussi devant moi ses bonnes actions, et ils lui rapportaient mes paroles. Tobija envoyait des lettres pour m’effrayer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, '*Or il arriva, quand la muraille fut bâtie et que j’eus posé les battants [des portes], qu’on établit dans leurs emplois les portiers, et les chantres, et les lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Et je chargeai du gouvernement de Jérusalem Hanani, mon frère, et Hanania, chef du château fort; car c’était un homme fidèle, et il craignait Dieu, plus que beaucoup [d’autres];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'et je leur dis que les portes de Jérusalem ne devaient pas être ouvertes avant que le soleil ne soit chaud, et qu’on devait fermer les battants [des portes] pendant qu’ils étaient là, et mettre les barres, et qu’on devait placer des gardes d’entre les habitants de Jérusalem, chacun à son poste, et chacun devant sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Or la ville était spacieuse et grande, mais le peuple peu nombreux au milieu d’elle, et il n’y avait point de maisons bâties.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Et mon Dieu me mit au cœur de rassembler les nobles et les chefs, et le peuple, pour les enregistrer par généalogies. Et je trouvai le registre généalogique de ceux qui étaient montés au commencement, et j’y trouvai écrit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Voici ceux de la province qui remontèrent de la captivité de ceux qui avaient été transportés, lesquels Nebucadnetsar, roi de Babylone, avait transportés, et qui retournèrent à Jérusalem et en Juda, chacun à sa ville,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'ceux qui vinrent avec Zorobabel, Jéshua, Néhémie, Azaria, Raamia, Nakhamani, Mardochée, Bilshan, Mispéreth, Bigvaï, Nehum, [et] Baana. Nombre des hommes du peuple d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Les fils de Parhosh, 2 172;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'les fils de Shephatia, 372;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'les fils d’Arakh, 652;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'les fils de Pakhath-Moab, des fils de Jéshua et de Joab, 2 818;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'les fils d’Élam, 1 254;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'les fils de Zatthu, 845;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'les fils de Zaccaï, 760;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'les fils de Binnuï, 648;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'les fils de Bébaï, 628;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'les fils d’Azgad, 2 322;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'les fils d’Adonikam, 667;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'les fils de Bigvaï, 2 067;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'les fils d’Adin, 655;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'les fils d’Ater, [de la famille] d’Ézéchias, 98;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'les fils de Hashum, 328;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'les fils de Bétsaï, 324;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'les fils de Hariph, 112;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'les fils de Gabaon, 95;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'les hommes de Bethléhem et de Netopha, 188;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'les hommes d’Anathoth, 128;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'les hommes de Beth-Azmaveth, 42;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'les hommes de Kiriath-Jéarim, de Kephira et de Beéroth, 743;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'les hommes de Rama et de Guéba, 621;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'les hommes de Micmas, 122;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'les hommes de Béthel et d’Aï, 123;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'les hommes de l’autre Nebo, 52;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'les fils de l’autre Élam, 1 254;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'les fils de Harim, 320;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'les fils de Jéricho, 345;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'les fils de Lod, de Hadid et d’Ono, 721;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'les fils de Senaa, 3 930.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Sacrificateurs: les fils de Jedahia, de la maison de Jéshua, 973;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'les fils d’Immer, 1 052;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'les fils de Pashkhur, 1 247;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'les fils de Harim, 1 017.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Lévites: les fils de Jéshua [et] de Kadmiel, d’entre les fils d’Hodva, 74.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Chantres: les fils d’Asaph, 148.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Portiers: les fils de Shallum, les fils d’Ater, les fils de Talmon, les fils d’Akkub, les fils de Hatita, les fils de Shobaï, 138.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Nethiniens: les fils de Tsikha, les fils de Hasupha, les fils de Tabbaoth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'les fils de Kéros, les fils de Sia, les fils de Padon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'les fils de Lebana, les fils de Hagaba, les fils de Sçalmaï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'les fils de Hanan, les fils de Guiddel, les fils de Gakhar,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'les fils de Reaïa, les fils de Retsin, les fils de Nekoda,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'les fils de Gazzam, les fils d’Uzza, les fils de Paséakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'les fils de Bésaï, les fils de Meünim, les fils de Nephissim,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'les fils de Bakbuk, les fils de Hakupha, les fils de Harkhur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'les fils de Batslith, les fils de Mekhida, les fils de Harsha,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'les fils de Barkos, les fils de Sisera, les fils de Thamakh,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'les fils de Netsiakh, les fils de Hatipha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Fils des serviteurs de Salomon: les fils de Sotaï, les fils de Sophéreth, les fils de Perida,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'les fils de Jaala, les fils de Darkon, les fils de Guiddel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'les fils de Shephatia, les fils de Hattil, les fils de Pokéreth-Hatsebaïm, les fils d’Amon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Tous les Nethiniens et les fils des serviteurs de Salomon, 392.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Et voici ceux qui montèrent de Thel-Mélakh, de Thel-Harsha, de Kerub-Addon, et d’Immer; mais ils ne purent pas montrer leurs maisons de pères et leur descendance, s’ils étaient d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'les fils de Delaïa, les fils de Tobija, les fils de Nekoda, 642;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'et des sacrificateurs, les fils de Hobaïa, les fils d’Hakkots, les fils de Barzillaï, qui prit une femme d’entre les filles de Barzillaï, le Galaadite, et fut appelé de leur nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ceux-ci cherchèrent leur inscription généalogique, mais elle ne se trouva pas; et ils furent exclus, comme profanes, de la sacrificature.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Et le Thirshatha leur dit qu’ils ne devaient point manger des choses très saintes, jusqu’à ce que soit suscité le sacrificateur avec les urim et les thummim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Toute la congrégation réunie était de 42 360 [personnes],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'sans compter leurs serviteurs et leurs servantes; ceux-ci [étaient au nombre de] 7 337; et parmi eux, il y avait 245 chanteurs et chanteuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Ils avaient 736 chevaux, 245 mulets, 435 chameaux, [et] 6 720 ânes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Et une partie des chefs des pères firent des dons pour l’œuvre. Le Thirshatha donna au trésor 1 000 dariques d’or, 50 bassins, 530 tuniques de sacrificateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Et des chefs des pères donnèrent au trésor de l’œuvre 20 000 dariques d’or et 2 200 mines d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Et ce que donna le reste du peuple fut 20 000 dariques d’or, et 2 000 mines d’argent, et 67 tuniques de sacrificateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Et les sacrificateurs, et les lévites, et les portiers, et les chantres, et ceux du peuple, et les Nethiniens, et tout Israël, habitèrent dans leurs villes. *Et quand arriva le septième mois, les fils d’Israël étaient dans leurs villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, '');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, '– Alors tout le peuple s’assembla comme un seul homme sur la place qui est devant la porte des eaux. Et ils dirent à Esdras, le scribe, d’apporter le livre de la loi de Moïse, que l’ Éternel avait commandée à Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Et le premier jour du septième mois, Esdras, le sacrificateur, apporta la loi devant la congrégation des hommes et des femmes, et devant tous ceux qui avaient de l’intelligence pour entendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Et il y lut devant la place qui est devant la porte des eaux, depuis l’aube jusqu’à midi, en présence des hommes et des femmes, et de ceux qui avaient de l’intelligence. Et tout le peuple prêtait l’oreille au livre de la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Et Esdras, le scribe, se tenait sur une estrade de bois qu’on avait faite pour l’occasion; et Matthithia, et Shéma, et Anaïa, et Urie, et Hilkija, et Maascéïa, se tenaient à côté de lui, à sa droite; et à sa gauche, Pedaïa, et Mishaël, et Malkija, et Hashum, et Hashbaddana, Zacharie, [et] Meshullam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Et Esdras ouvrit le livre aux yeux de tout le peuple, car il était [élevé] au-dessus de tout le peuple; et quand il l’ouvrit, tout le peuple se tint debout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Et Esdras bénit l’ Éternel, le grand Dieu, et tout le peuple répondit: Amen, amen! en élevant les mains, et ils s’inclinèrent et se prosternèrent devant l’ Éternel, le visage contre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Et Jéshua, et Bani, et Shérébia, Jamin, Akkub, Shabthaï, Hodija, Maascéïa, Kelita, Azaria, Jozabad, Hanan, Pelaïa, et les lévites, faisaient comprendre la loi au peuple; et le peuple se tenait à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Et ils lisaient distinctement dans le livre de la loi de Dieu, et ils en donnaient le sens et le faisaient comprendre lorsqu’on lisait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Et Néhémie, qui était le Thirshatha, et Esdras, le sacrificateur, le scribe, et les lévites qui faisaient comprendre au peuple [ce qu’on lisait], dirent à tout le peuple: Ce jour est saint à l’ Éternel, votre Dieu; ne menez pas deuil et ne pleurez pas! Car tout le peuple pleurait en entendant les paroles de la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Et [Néhémie] leur dit: Allez, mangez de ce qui est gras et buvez de ce qui est doux, et envoyez des portions à ceux qui n’ont rien de préparé, car ce jour est saint, [consacré] à notre Seigneur. Et ne vous affligez pas, car la joie de l’ Éternel est votre force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Et les lévites tranquillisèrent tout le peuple, en disant: Taisez-vous, car ce jour est saint, et ne vous affligez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Et tout le peuple s’en alla pour manger et pour boire, et pour envoyer des portions, et pour faire de grandes réjouissances; car ils avaient compris les paroles qu’on leur avait fait connaître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Et le second jour, les chefs des pères de tout le peuple, les sacrificateurs et les lévites, s’assemblèrent auprès d’Esdras, le scribe, et [cela] pour devenir intelligents dans les paroles de la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Et ils trouvèrent écrit dans la loi que l’ Éternel avait commandée par Moïse, que les fils d’Israël devaient habiter dans des tabernacles pendant la fête du septième mois,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'et qu’ils devaient faire entendre et faire passer une proclamation dans toutes leurs villes et à Jérusalem, disant: Sortez dans la montagne, et apportez des branches d’olivier, et des branches d’olivier sauvage, et des branches de myrte, et des branches de palmier, et des branches d’arbres touffus, pour faire des tabernacles, comme il est écrit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Et le peuple sortit et [en] apporta, et ils se firent des tabernacles, chacun sur son toit, et dans leurs cours, et dans les parvis de la maison de Dieu, et sur la place de la porte des eaux, et sur la place de la porte d’Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Et toute la congrégation de ceux qui étaient revenus de la captivité fit des tabernacles, et ils habitèrent dans les tabernacles; car les fils d’Israël n’avaient pas fait cela depuis les jours de Josué, fils de Nun, jusqu’à ce jour-là. Et il y eut une très grande joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Et on lut dans le livre de la loi de Dieu chaque jour, depuis le premier jour jusqu’au dernier jour. Et ils célébrèrent la fête sept jours, et au huitième jour, il y eut une assemblée solennelle, selon l’ordonnance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Et le vingt-quatrième jour de ce mois, les fils d’Israël s’assemblèrent avec jeûne et vêtus de sacs, et avec de la terre sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Et la race d’Israël se sépara de tous les fils de l’étranger; et ils se tinrent là et confessèrent leurs péchés et les iniquités de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Et ils se levèrent à leurs places, et lurent dans le livre de la loi de l’ Éternel, leur Dieu, pendant un quart de la journée; et pendant un quart, ils firent confession et se prosternèrent devant l’ Éternel, leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Et les lévites, Jéshua, Bani, Kadmiel, Shebania, Bunni, Shérébia, Bani, et Kenani, se levèrent sur l’estrade et crièrent à haute voix à l’ Éternel, leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Et les lévites, Jéshua, Kadmiel, Bani, Hashabnia, Shérébia, Hodija, Shebania et Pethakhia, dirent: Levez-vous, bénissez l’ Éternel, votre Dieu, d’éternité en éternité! Et qu’on bénisse le nom de ta gloire, qui est haut élevé au-dessus de toute bénédiction et de toute louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Tu es le Même, toi seul, ô Éternel; tu as fait les cieux, les cieux des cieux et toute leur armée, la terre et tout ce qui est sur elle, les mers et tout ce qui est en elles. Et c’est toi qui fais vivre toutes ces choses, et l’armée des cieux t’adore.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Tu es le Même, ô Éternel, Dieu, qui as choisi Abram et l’as fait sortir d’Ur des Chaldéens, et lui as donné le nom d’Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Et tu trouvas son cœur fidèle devant toi, et tu fis avec lui une alliance pour donner le pays du Cananéen, du Héthien, de l’Amoréen, et du Phérézien, et du Jébusien, et du Guirgasien, pour le donner à sa semence; et tu as accompli tes paroles, car tu es juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Et tu vis l’affliction de nos pères en Égypte, et tu entendis leur cri vers la mer Rouge,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'et tu opéras des signes et des prodiges sur le Pharaon, et sur tous ses serviteurs, et sur tout le peuple de son pays, car tu savais qu’ils avaient agi avec fierté contre eux, et tu t’acquis un nom, comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Et tu fendis la mer devant eux, et ils passèrent à sec par le milieu de la mer; et ceux qui les poursuivaient, tu les jetas dans les abîmes, comme une pierre dans les eaux puissantes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Et tu les conduisis de jour par une colonne de nuée, et de nuit par une colonne de feu, afin d’éclairer pour eux le chemin dans lequel ils devaient marcher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Et tu descendis sur la montagne de Sinaï, et tu parlas avec eux depuis les cieux, et tu leur donnas des ordonnances droites et des lois de vérité, de bons statuts et [de bons] commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Et tu leur fis connaître ton saint sabbat, et tu leur prescrivis des commandements et des statuts et une loi, par ton serviteur Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Et des cieux tu leur donnas du pain pour leur faim, et tu leur fis sortir du rocher de l’eau pour leur soif, et tu leur dis d’entrer pour prendre possession du pays que tu avais juré de leur donner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Mais eux, savoir nos pères, agirent avec fierté, et roidirent leur cou, et n’écoutèrent pas tes commandements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'et refusèrent d’entendre, et ne se souvinrent pas de tes merveilles que tu avais faites pour eux; mais ils roidirent leur cou, et dans leur rébellion ils établirent un chef, pour retourner à leur servitude. Mais toi, tu es un ✝Dieu de pardons, faisant grâce, et miséricordieux, lent à la colère, et grand en bonté, et tu ne les as point abandonnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Même quand ils se firent un veau de fonte, et dirent: C’est ici ton dieu qui t’a fait monter d’Égypte, – et qu’ils te firent de grands outrages,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'toi, dans tes grandes compassions, tu ne les abandonnas point dans le désert; la colonne de nuée ne se retira point de dessus eux, le jour, pour les conduire dans le chemin, ni la colonne de feu, la nuit, pour les éclairer, et [leur montrer] le chemin dans lequel ils devaient marcher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Et tu [leur] donnas ton bon Esprit pour les rendre intelligents, et tu ne refusas pas ta manne à leur bouche, et tu leur donnas de l’eau pour leur soif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Et tu les entretins 40 ans dans le désert: ils ne manquèrent de rien; leurs vêtements ne s’usèrent point, et leurs pieds n’enflèrent point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Et tu leur donnas des royaumes et des peuples, et tu les leur partageas par contrées, et ils prirent possession du pays de Sihon, du pays du roi de Hesbon, aussi bien que du pays d’Og, roi de Basan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Et tu multiplias leurs fils comme les étoiles des cieux, et tu les introduisis dans le pays dont tu avais dit à leurs pères, qu’ils y entreraient pour le posséder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Et leurs fils entrèrent et possédèrent le pays. Et tu subjuguas devant eux les habitants du pays, les Cananéens, et tu les livras en leur main, leurs rois et les peuples du pays, pour leur faire selon leur bon plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Et ils prirent des villes fortifiées, et un pays gras, et ils possédèrent des maisons pleines de tout bien, des puits creusés, des vignes et des oliviers, et des arbres fruitiers en abondance; et ils mangèrent, et furent rassasiés, et s’engraissèrent; et ils vécurent dans les délices par ta grande bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Mais ils se rebellèrent et se révoltèrent contre toi, et jetèrent ta loi derrière leur dos, et tuèrent tes prophètes qui rendaient témoignage contre eux pour les ramener à toi, et ils te firent de grands outrages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Et tu les livras en la main de leurs adversaires qui les opprimèrent. Et au temps de leur détresse ils crièrent à toi, et toi, tu entendis des cieux, et selon tes grandes compassions tu leur accordas des sauveurs qui les sauvèrent de la main de leurs oppresseurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Mais quand ils avaient du repos, ils recommençaient à faire le mal devant toi, et tu les abandonnais en la main de leurs ennemis, et ceux-ci dominaient sur eux. Et de nouveau ils criaient à toi, et toi, tu entendais des cieux, et tu les délivras maintes fois, selon tes compassions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Et tu rendis témoignage contre eux pour les ramener à ta loi; mais ils agirent avec fierté, et n’écoutèrent pas tes commandements, et péchèrent contre tes ordonnances, par lesquelles, s’il les pratique, un homme vivra; et ils opposèrent une épaule revêche, et roidirent leur cou, et n’écoutèrent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Et tu différas à leur égard pendant beaucoup d’années, et tu rendis témoignage contre eux par ton Esprit, par le moyen de tes prophètes; mais ils ne prêtèrent pas l’oreille, et tu les livras en la main des peuples des pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Toutefois, dans tes grandes compassions, tu n’en finis pas avec eux, et tu ne les abandonnas pas; car tu es un ✶Dieu faisant grâce, et miséricordieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Et maintenant, notre Dieu, le ✶Dieu grand, puissant et terrible, qui gardes l’alliance et la bonté, que ce ne soit pas peu de chose devant toi que toutes les peines qui nous ont atteints, nous, nos rois, nos princes, et nos sacrificateurs, et nos prophètes, et nos pères, et tout ton peuple, depuis les jours des rois d’Assyrie jusqu’à ce jour-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Mais tu es juste dans tout ce qui nous est survenu, car tu as agi avec vérité, et nous, nous avons agi méchamment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Et nos rois, nos princes, nos sacrificateurs, et nos pères, n’ont pas pratiqué ta loi, et n’ont pas été attentifs à tes commandements et à tes témoignages que tu as rendus au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Et ils ne t’ont pas servi dans leur royaume, et dans l’abondance des biens que tu leur avais donnés, et dans le spacieux et gras pays que tu avais mis devant eux, et ils ne sont pas revenus de leurs mauvaises actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Voici, nous sommes aujourd’hui serviteurs; et quant au pays que tu donnas à nos pères pour qu’ils en mangent le fruit et les bons produits, voici, nous y sommes serviteurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'et il rapporte beaucoup aux rois que tu as établis sur nous à cause de nos péchés; et ils dominent à leur gré sur nos corps et sur notre bétail, et nous sommes dans une grande détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Et pour tout cela, nous faisons une ferme alliance, et nous l’écrivons. Et à l’apposition des sceaux [se trouvèrent] nos princes, nos lévites, [et] nos sacrificateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Et à la tête de ceux qui apposèrent leur sceau furent: Néhémie, le Thirshatha, fils de Hacalia, et Sédécias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, '– Seraïa, Azaria, Jérémie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Pashkhur, Amaria, Malkija,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Hattush, Shebania, Malluc,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Harim, Merémoth, Abdias,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Daniel, Guinnethon, Baruc,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Meshullam, Abija, Mijamin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Maazia, Bilgaï, Shemahia: c’étaient là les sacrificateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, '– Et les lévites: Jéshua, fils d’Azania; Binnuï, des fils de Hénadad; Kadmiel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'et leurs frères, Shebania, Hodija, Kelita, Pelaïa, Hanan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Michée, Rehob, Hashabia,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Zaccur, Shérébia, Shebania,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Hodija, Bani, Beninu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, '– Les chefs du peuple: Parhosh, Pakhath-Moab, Élam, Zatthu, Bani,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Bunni, Azgad, Bébaï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Adonija, Bigvaï, Adin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Ater, Ézéchias, Azzur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hodija, Hashum, Bétsaï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Hariph, Anathoth, Nébaï,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Magpiash, Meshullam, Hézir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Meshézabeël, Tsadok, Jaddua,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Pelatia, Hanan, Anaïa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Osée, Hanania, Hashub,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Hallokhesh, Pilkha, Shobek,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Rehum, Hashabna, Maascéïa');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'et Akhija, Hanan, Anan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Malluc, Harim, Baana.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Et le reste du peuple, les sacrificateurs, les lévites, les portiers, les chantres, les Nethiniens, et tous ceux qui s’étaient séparés des peuples des pays [pour s’attacher] à la loi de Dieu, leurs femmes, leurs fils et leurs filles, tous ceux qui avaient de la connaissance [et] de l’intelligence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'se joignirent à leurs frères, les principaux d’entre eux, et s’engagèrent par exécration et par serment de marcher selon la loi de Dieu qui avait été donnée par Moïse, serviteur de Dieu, et d’observer et de pratiquer tous les commandements de l’ Éternel, notre Seigneur, et ses ordonnances et ses statuts,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'et [promettant] que nous ne donnerions pas nos filles aux peuples du pays, et que nous ne prendrions pas leurs filles pour nos fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'et que, si les peuples du pays apportaient des marchandises ou toutes sortes de grains, le jour du sabbat, pour les vendre, nous n’en prendrions pas le [jour du] sabbat, ni en un jour saint; et que nous laisserions [la terre en friche] la septième année, et remettrions toute espèce de dettes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Et nous nous sommes établi des commandements, nous imposant le tiers d’un sicle par an pour le service de la maison de notre Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'pour les pains à placer en rangées, et pour l’offrande de gâteau continuelle, et pour les holocaustes, l’[holocauste] continuel, [celui] des sabbats, [et celui] des nouvelles lunes, pour les jours solennels et pour les choses saintes, et pour les sacrifices pour le péché, afin de faire propitiation pour Israël, et pour toute l’œuvre de la maison de notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Et nous avons jeté le sort, sacrificateurs, lévites, et peuple, au sujet de l’offrande du bois à amener à la maison de notre Dieu, selon nos maisons de pères, à des époques fixes, chaque année, pour le brûler sur l’autel de l’ Éternel, notre Dieu, comme il est écrit dans la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Et [nous nous sommes engagés] à apporter les prémices de notre terre, et les prémices de tous les fruits de tous les arbres, chaque année, à la maison de l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'et les premiers-nés de nos fils et de nos bêtes, comme il est écrit dans la loi; et à apporter les premiers-nés de notre gros et de notre menu bétail, à la maison de notre Dieu, aux sacrificateurs qui font le service dans la maison de notre Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'et nous apporterons les prémices de notre pâte et nos offrandes élevées, et le fruit de tout arbre, le moût et l’huile, aux sacrificateurs, dans les chambres de la maison de notre Dieu, et les dîmes de notre terre aux lévites; et eux, les lévites, prélèveront la dîme dans toutes les villes de notre labour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'et le sacrificateur, fils d’Aaron, sera avec les lévites quand les lévites prélèveront la dîme, et les lévites apporteront la dîme de la dîme à la maison de notre Dieu, dans les chambres de la maison du trésor;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 40, 'car les fils d’Israël et les fils de Lévi apporteront l’offrande élevée du blé, du moût, et de l’huile, dans les chambres où sont les ustensiles du sanctuaire, et les sacrificateurs qui font le service, et les portiers et les chantres. Et nous n’abandonnerons pas la maison de notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, '*Et les chefs du peuple habitaient à Jérusalem: et le reste du peuple jeta le sort pour qu’un sur dix vienne habiter à Jérusalem, la ville sainte, et que les neuf [autres] parties [demeurent] dans les villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Et le peuple bénit tous les hommes qui s’offrirent volontairement pour habiter à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Or ce sont ici les chefs de la province qui habitèrent à Jérusalem; mais, dans les villes de Juda, habitèrent, chacun dans sa possession, dans leurs villes, Israël, les sacrificateurs, et les lévites, et les Nethiniens, et les fils des serviteurs de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Et à Jérusalem habitèrent des fils de Juda, et des fils de Benjamin. – Des fils de Juda: Athaïa, fils d’Ozias, fils de Zacharie, fils d’Amaria, fils de Shephatia, fils de Mahalaleël, d’entre les fils de Pérets;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'et Maascéïa, fils de Baruc, fils de Col-Hozé, fils de Hazaïa, fils d’Adaïa, fils de Joïarib, fils de Zacharie, d’entre les Shilonites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Tous les fils de Pérets qui habitèrent à Jérusalem: 468 hommes vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, '– Et ce sont ici les fils de Benjamin: Sallu, fils de Meshullam, fils de Joëd, fils de Pedaïa, fils de Kolaïa, fils de Maascéïa, fils d’Ithiel, fils d’Ésaïe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'et après lui, Gabbaï, Sallaï: 928;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'et Joël, fils de Zicri, était préposé sur eux, et Juda, fils d’Hassenua, en second, sur la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Des sacrificateurs: Jedahia, ✶[fils de] Joïarib, Jakin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraïa, fils de Hilkija, fils de Meshullam, fils de Tsadok, fils de Meraïoth, fils d’Akhitub, prince de la maison de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'et leurs frères qui faisaient les travaux de la maison: 822. Et Adaïa, fils de Jerokham, fils de Pelalia, fils d’Amtsi, fils de Zacharie, fils de Pashkhur, fils de Malkija,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'et ses frères, chefs des pères: 242. Et Amassaï, fils d’Azareël, fils d’Akhzaï, fils de Meshillémoth, fils d’Immer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'et leurs frères, hommes forts et vaillants: 128; et Zabdiel, fils de Guedolim, était préposé sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Et des lévites: Shemahia, fils de Hashub, fils d’Azrikam, fils de Hashabia, fils de Bunni;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'et Shabthaï et Jozabad, d’entre les chefs des lévites, [préposés] sur l’ouvrage extérieur de la maison de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'et Matthania, fils de Michée, fils de Zabdi, fils d’Asaph, le chef, qui entonnait la louange à la prière, et Bakbukia, le second d’entre ses frères, et Abda, fils de Shammua, fils de Galal, fils de Jeduthun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Tous les lévites dans la ville sainte: 284.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Et les portiers, Akkub, Talmon, et leurs frères, qui étaient de garde aux portes, 172.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Et le reste d’Israël, les sacrificateurs, [et] les lévites, [habitèrent] dans toutes les villes de Juda, chacun dans son héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Et les Nethiniens habitèrent Ophel; et Tsikha et Guishpa étaient [préposés] sur les Nethiniens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Et celui qui était préposé sur les lévites à Jérusalem était Uzzi, fils de Bani, fils de Hashabia, fils de Matthania, fils de Michée, des fils d’Asaph, les chantres pour l’œuvre de la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Car c’était le commandement du roi à leur égard, et il y avait un fixe pour les chantres, pour chaque jour ce qu’il fallait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Et Pethakhia, fils de Meshézabeël, des fils de Zérakh, fils de Juda, était auprès du roi pour toutes les affaires du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Et pour ce qui est des hameaux de leurs campagnes, [quelques-uns] des fils de Juda habitèrent à Kiriath-Arba et dans les villages de son ressort, et à Dibon et dans les villages de son ressort, et à Jekabtsëel et dans ses hameaux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'et à Jéshua, et à Molada, et à Beth-Péleth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'et à Hatsar-Shual, et à Beër-Shéba et dans les villages de son ressort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'et à Tsiklag, et à Mecona et dans les villages de son ressort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'et à En-Rimmon, et à Tsorha, et à Jarmuth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zanoakh, Adullam et leurs hameaux, Lakis et ses campagnes, Azéka et les villages de son ressort; et ils demeurèrent depuis Beër-Shéba jusqu’à la vallée de Hinnom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Et les fils de Benjamin [s’établirent], depuis Guéba, [à] Micmash, et Aïa, et Béthel et les villages de son ressort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Anathoth, Nob, Anania,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hatsor, Rama, Guitthaïm,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadid, Tseboïm, Neballath,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lod et Ono, la vallée des artisans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Et d’entre les Lévites, il y eut des divisions de Juda [qui s’établirent] en Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, '*Et ce sont ici les sacrificateurs et les lévites qui montèrent avec Zorobabel, fils de Shealthiel, et Jéshua: Seraïa, Jérémie, Esdras,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amaria, Malluc, Hattush,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Shecania, Rehum, Merémoth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Guinnethoï, Abija,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadia, Bilga,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Shemahia, et Joïarib, Jedahia,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Hilkija, Jedahia. Ce sont là les chefs des sacrificateurs et de leurs frères, aux jours de Jéshua.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Et les lévites: Jéshua, Binnuï, Kadmiel, Shérébia, Juda, Matthania, qui avait la direction des louanges, lui et ses frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Et Bakbukia, et Unni, leurs frères, vis-à-vis d’eux dans leurs fonctions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Et Jéshua engendra Joïakim, et Joïakim engendra Éliashib, et Éliashib engendra Joïada,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'et Joïada engendra Jonathan, et Jonathan engendra Jaddua.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Et aux jours de Joïakim étaient sacrificateurs, chefs des pères: de Seraïa, Meraïa; de Jérémie, Hanania;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'd’Esdras, Meshullam; d’Amaria, Jokhanan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'de Meluki, Jonathan; de Shebania, Joseph;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'de Harim, Adna; de Meraïoth, Helkaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'd’Iddo, Zacharie; de Guinnethon, Meshullam;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'd’Abija, Zicri; de Minjamin [et] Moadia, Piltaï;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'de Bilga, Shammua; de Shemahia, Jonathan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'et de Joïarib, Mathnaï; de Jedahia, Uzzi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'de Sallaï, Kallaï; d’Amok, Éber;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'de Hilkija, Hashabia; de Jedahia, Nethaneël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Quant aux lévites, les chefs des pères furent inscrits aux jours d’Éliashib, de Joïada, et de Jokhanan et de Jaddua, et les sacrificateurs, jusqu’au règne de Darius, le Perse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Les fils de Lévi, chefs des pères, furent inscrits dans le livre des chroniques, jusqu’aux jours de Jokhanan, fils d’Éliashib.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Et les chefs des lévites: Hashabia, Shérébia, et Jéshua, fils de Kadmiel, et leurs frères vis-à-vis d’eux, pour louer [et] pour rendre grâces selon le commandement de David, homme de Dieu, les uns en fonction à côté des autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matthania et Bakbukia, Abdias, Meshullam, Talmon, Akkub, faisaient la garde comme portiers aux magasins des portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ceux-ci [vivaient] aux jours de Joïakim, fils de Jéshua, fils de Jotsadak, et aux jours de Néhémie, le gouverneur, et d’Esdras, le sacrificateur, le scribe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Et lors de la dédicace de la muraille de Jérusalem, on envoya chercher les lévites de tous leurs lieux [d’habitation], pour les amener à Jérusalem, pour faire la dédicace avec joie, avec des louanges et des chants, [avec] des cymbales, des luths et des harpes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Et les fils des chantres s’assemblèrent, tant de la plaine [du Jourdain], des environs de Jérusalem, que des hameaux des Netophathites,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'et de la maison de Guilgal, et des campagnes de Guéba et d’Azmaveth; car les chantres s’étaient bâti des hameaux dans les environs de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Et les sacrificateurs et les lévites se purifièrent, et ils purifièrent le peuple, et les portes, et la muraille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Et je fis monter les chefs de Juda sur la muraille, et je plaçai deux grands chœurs en processions, à droite, sur le mur, vers la porte du fumier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'et après eux marchaient Hoshahia et la moitié des chefs de Juda,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'et Azaria, Esdras et Meshullam,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda et Benjamin, et Shemahia et Jérémie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'et des fils des sacrificateurs avec des trompettes: Zacharie, fils de Jonathan, fils de Shemahia, fils de Matthania, fils de Michée, fils de Zaccur, fils d’Asaph,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'et ses frères, Shemahia, et Azareël, Milalaï, Guilalaï, Maaï, Nethaneël, Juda, et Hanani, avec des instruments de musique de David, homme de Dieu; et Esdras, le scribe, devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Et à la porte de la fontaine, vis-à-vis d’eux, ils montèrent les degrés de la ville de David, par la montée de la muraille, au-dessus de la maison de David, et jusqu’à la porte des eaux, vers le levant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Et le second chœur marcha à l’opposé sur la muraille, et moi après lui, ainsi que la moitié du peuple, depuis la tour des fours jusqu’à la muraille large,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'et au-dessus de la porte d’Éphraïm, et près de la porte du vieux [mur], et de la porte des poissons, et de la tour de Hananeël, et de la tour de Méa, jusqu’à la porte des brebis; et ils s’arrêtèrent à la porte de la prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Et les deux chœurs s’arrêtèrent dans la maison de Dieu, et moi, et la moitié des chefs avec moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'et les sacrificateurs Éliakim, Maascéïa, Minjamin, Michée, Élioénaï, Zacharie, Hanania, avec des trompettes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'et Maascéïa, et Shemahia, et Éléazar, et Uzzi, et Jokhanan, et Malkija, et Élam, et Ézer. Et les chantres firent entendre [leur voix], et Jizrakhia les dirigeait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Et ils offrirent ce jour-là de grands sacrifices, et se réjouirent, car Dieu les avait réjouis d’une grande joie; et les femmes aussi et les enfants se réjouirent; et la joie de Jérusalem s’entendait au loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Et des hommes furent préposés, ce jour-là, sur les chambres des trésors pour les offrandes élevées, pour les prémices, et pour les dîmes, afin d’y recueillir, des champs des villes, les portions assignées par la loi aux sacrificateurs et aux lévites; car Juda se réjouissait à cause des sacrificateurs et des lévites qui se tenaient là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'et, ainsi que les chantres et les portiers, ils gardaient ce que leur Dieu leur avait donné à garder, et ce qu’ils avaient à garder pour la purification, selon le commandement de David [et] de Salomon, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Car autrefois, aux jours de David et d’Asaph, il y avait des chefs pour diriger les chantres et les chants de louanges et les cantiques d’actions de grâces à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Et aux jours de Zorobabel, et aux jours de Néhémie, tout Israël donnait les portions des chantres et des portiers, chaque jour ce qu’il fallait, et on mettait à part pour les lévites, et les lévites mettaient à part pour les fils d’Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Ce jour-là, on lut dans le livre de Moïse, aux oreilles du peuple, et il s’y trouva écrit que l’Ammonite et le Moabite n’entreraient pas dans la congrégation de Dieu, à jamais,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'parce qu’ils n’étaient pas venus à la rencontre des fils d’Israël avec du pain et de l’eau, et qu’ils avaient loué contre eux [à prix d’argent] Balaam pour les maudire (mais notre Dieu changea la malédiction en bénédiction).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Et il arriva que, lorsqu’ils eurent entendu la loi, ils séparèrent d’Israël tout le peuple mélangé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Et avant cela, Éliashib, le sacrificateur, établi sur les chambres de la maison de notre Dieu, allié de Tobija,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'lui avait préparé une grande chambre; et précédemment on y mettait les offrandes de gâteau, l’encens, et les ustensiles, et les dîmes du blé, du moût et de l’huile, ce qui était ordonné pour les lévites et pour les chantres et les portiers, ainsi que l’offrande élevée des sacrificateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Et pendant tout cela je n’étais pas à Jérusalem; car, la trente-deuxième année d’Artaxerxès, roi de Babylone, j’étais allé vers le roi; et au bout de quelque temps j’avais demandé au roi la permission de m’en aller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Et je vins à Jérusalem, et je m’aperçus du mal qu’Éliashib avait fait en faveur de Tobija, en lui préparant une chambre dans les parvis de la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Et je trouvai cela fort mauvais, et je jetai dehors, hors de la chambre, tous les effets de la maison de Tobija.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Et je commandai qu’on purifie les chambres, et j’y fis rapporter les ustensiles de la maison de Dieu, l’offrande de gâteau et l’encens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Et j’appris que les portions des lévites ne leur avaient pas été données, et que les lévites et les chantres qui faisaient le service avaient fui chacun à son champ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Et je querellai les chefs, et je dis: Pourquoi la maison de Dieu est-elle abandonnée? Et je les rassemblai, et je les fis demeurer à leur poste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Et tout Juda apporta dans les magasins la dîme du blé, et du moût, et de l’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Et j’établis sur les magasins Shélémia, le sacrificateur, et Tsadok, le scribe, et Pedaïa, d’entre les lévites, et à côté d’eux, Hanan, fils de Zaccur, fils de Matthania, car ils étaient estimés fidèles, et c’était à eux de faire les répartitions à leurs frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Souviens-toi de moi, ô mon Dieu, à cause de ceci, et n’efface pas les bonnes actions que j’ai faites à l’égard de la maison de mon Dieu et de ce qu’il y avait à y observer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Dans ces jours-là, je vis en Juda des gens qui foulaient aux pressoirs, le [jour du] sabbat, et qui rentraient des gerbes et les chargeaient sur des ânes, et aussi du vin, des raisins et des figues, et toutes sortes de fardeaux, et qui les amenaient à Jérusalem le jour du sabbat; et je protestai, le jour où ils vendaient des denrées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Et les Tyriens y demeuraient, [et] ils apportaient du poisson et toutes sortes de marchandises, et les vendaient le [jour du] sabbat aux fils de Juda et dans Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Et je querellai les nobles de Juda, et je leur dis: Qu’est-ce que cette chose mauvaise que vous faites, profanant le jour du sabbat?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'N’est-ce pas ainsi qu’ont fait vos pères, de sorte que notre Dieu a fait venir tout ce malheur sur nous et sur cette ville? et vous voulez ajouter à la colère contre Israël en profanant le sabbat!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Et il arriva que, lorsque les portes de Jérusalem commencèrent à être dans l’ombre, avant le sabbat, je commandai qu’on ferme les portes. Et je commandai qu’on ne les ouvre point jusqu’après le sabbat; et je plaçai de mes jeunes hommes aux portes, afin qu’aucun fardeau ne soit introduit le jour du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Et les marchands et les vendeurs de toutes sortes de marchandises passèrent la nuit hors de Jérusalem, une et deux fois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'et je les admonestai, et leur dis: Pourquoi passez-vous la nuit devant la muraille? Si vous le faites encore, je mettrai la main sur vous. Depuis ce temps-là, ils ne sont pas venus le [jour du] sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Et je dis aux lévites qu’ils aient à se purifier et à venir garder les portes pour sanctifier le jour du sabbat. Souviens-toi de cela aussi en ma faveur, ô mon Dieu, et aie compassion de moi selon la grandeur de ta bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'En ces jours-là aussi, je vis des Juifs qui avaient pris des femmes asdodiennes, ammonites, [et] moabites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'et leurs fils parlaient à moitié l’asdodien et ne savaient pas parler le juif, mais selon la langue de l’un ou de l’autre peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Et je les querellai, et je les maudis, et je battis quelques hommes d’entre eux et leur arrachai les cheveux, et je les fis jurer par Dieu, [en disant]: Vous ne donnerez pas vos filles à leurs fils, et vous ne prendrez pas de leurs filles pour vos fils, ni pour vous-mêmes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Salomon, roi d’Israël, n’a-t-il pas péché en cela? Or, parmi la multitude des nations, il n’y avait point de roi comme lui, et il était aimé de son Dieu, et Dieu le fit roi sur tout Israël: lui aussi, les femmes étrangères l’ont fait pécher!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Et vous écouterions-nous pour faire tout ce grand mal, pour être infidèles à notre Dieu en prenant des femmes étrangères?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Et l’un des fils de Joïada, fils d’Éliashib, le grand sacrificateur, était gendre de Sanballat, le Horonite, et je le chassai d’auprès de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Souviens-toi d’eux, ô mon Dieu, car ce sont des profanateurs de la sacrificature, et de l’alliance de la sacrificature et des lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Et je les purifiai de tout étranger, et je fixai les fonctions des sacrificateurs et des lévites, chacun dans son service,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'et ce qui concernait l’offrande du bois à des époques fixes, et les premiers fruits. Souviens-toi de moi en bien, ô mon Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Et aux jours d’Assuérus (cet Assuérus régnait depuis l’Inde jusqu’à l’Éthiopie sur 127 provinces),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'en ces jours-là, il arriva que le roi Assuérus, étant assis sur le trône de son royaume, à Suse, la capitale,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'la troisième année de son règne, fit un festin à tous ses princes et ses serviteurs, les puissants de la Perse et de la Médie, les nobles et les chefs des provinces étant devant lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, '– montrant les richesses glorieuses de son royaume et le faste magnifique de sa grandeur pendant nombre de jours, pendant 180 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Et quand ces jours furent accomplis, le roi fit à tout le peuple qui se trouvait à Suse, la capitale, depuis le grand jusqu’au petit, un festin de sept jours, dans la cour du jardin du palais du roi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, '[des draperies] blanches, vertes, et bleues, étaient attachées par des cordons de byssus et de pourpre à des anneaux d’argent et à des colonnes de marbre blanc; les lits étaient d’or et d’argent, [placés] sur un pavement de marbre rouge et blanc, d’albâtre, et de marbre noir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Et on donna à boire dans des vases d’or, les vases différant les uns des autres, et il y avait du vin royal en abondance, selon la puissance du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Et on buvait, selon l’édit: on ne forçait personne; car c’est ainsi que le roi avait ordonné à tous les grands de sa maison, de faire selon le gré de chacun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'La reine Vasthi aussi fit un festin pour les femmes de la maison royale du roi Assuérus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Au septième jour, comme le cœur du roi était gai par le vin, il dit à Mehuman, à Biztha, à Harbona, à Bigtha, et à Abagtha, à Zéthar, et à Carcas, les sept eunuques qui servaient devant le roi Assuérus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'd’amener la reine Vasthi devant le roi, avec la couronne du royaume, pour montrer sa beauté aux peuples et aux princes, car elle était belle de figure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Mais la reine Vasthi refusa de venir à la parole du roi transmise par les eunuques. Et le roi se mit fort en colère, et sa fureur s’embrasa en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Et le roi dit aux sages qui connaissaient les temps (car les affaires du roi [se traitaient] ainsi devant tous ceux qui connaissaient la loi et le droit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'et les plus rapprochés de lui étaient Carshena, Shéthar, Admatha, Tarsis, Mérès, Marsena, Memucan, les sept princes de la Perse et de la Médie qui voyaient la face du roi, qui siégeaient au premier rang dans le royaume):');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Que faut-il faire à la reine Vasthi, selon la loi, pour n’avoir pas fait ce que le roi Assuérus a commandé par l’intermédiaire des eunuques?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Et Memucan dit devant le roi et les princes: Ce n’est pas contre le roi seulement que la reine Vasthi a mal agi, mais contre tous les princes et contre tous les peuples qui sont dans toutes les provinces du roi Assuérus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'car cette affaire de la reine se répandra parmi toutes les femmes, de manière à rendre leurs maris méprisables à leurs yeux, en ce qu’elles diront que le roi Assuérus a commandé d’amener la reine Vasthi devant lui, et qu’elle n’est pas venue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Et aujourd’hui les princesses de la Perse et de la Médie qui auront appris l’affaire de la reine parleront [de même] à tous les princes du roi; et il y aura assez de mépris et de colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Si le roi le trouve bon, qu’un ordre royal émane de lui et soit inscrit dans les lois de la Perse et de la Médie, et ne passe pas, que Vasthi n’entrera plus devant le roi Assuérus; et que le roi donne la dignité royale de Vasthi à une autre qui sera meilleure qu’elle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'et l’édit du roi, qu’il aura fait, sera connu dans tout son royaume, car il est grand, et toutes les femmes rendront honneur à leurs maris, depuis le grand jusqu’au petit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Et cette parole fut bonne aux yeux du roi et des princes. Et le roi fit selon la parole de Memucan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'et il envoya des lettres à toutes les provinces du roi, à chaque province selon son écriture, et à chaque peuple selon sa langue, [portant] que tout homme serait maître dans sa maison, et parlerait selon la langue de son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, '*Après ces choses, quand la colère du roi Assuérus se fut calmée, il se souvint de Vasthi et de ce qu’elle avait fait, et de ce qui avait été décrété contre elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Et les serviteurs du roi, qui le servaient dirent: Qu’on cherche pour le roi des jeunes filles vierges, belles de figure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'et que le roi prépose des commissaires dans toutes les provinces de son royaume, et qu’ils rassemblent toutes les jeunes filles vierges, belles de figure, à Suse, la capitale, dans la maison des femmes, sous la surveillance d’Hégaï, eunuque du roi, gardien des femmes; et qu’on [leur] donne les parfums nécessaires pour leur purification;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'et que la jeune fille qui plaira au roi soit reine à la place de Vasthi. Et la chose fut bonne aux yeux du roi. Et il fit ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Il y avait à Suse, la capitale, un homme juif, et son nom était Mardochée, fils de Jaïr, fils de Shimhi, fils de Kis, Benjaminite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'il avait été transporté de Jérusalem avec les captifs qui avaient été transportés avec Jéconias, roi de Juda, que Nebucadnetsar, roi de Babylone, avait transportés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Et il élevait Hadassa (qui est Esther), fille de son oncle, car elle n’avait ni père ni mère. Et la jeune fille était belle de taille et belle de figure. Et à la mort de son père et de sa mère, Mardochée la prit pour fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Et il arriva que, lorsque la parole du roi et son édit furent connus et que beaucoup de jeunes filles furent rassemblées à Suse, la capitale, sous la surveillance d’Hégaï, Esther aussi fut amenée dans la maison du roi, sous la surveillance d’Hégaï, gardien des femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Et la jeune fille lui plut et trouva faveur devant lui; et il se hâta de lui donner les parfums nécessaires pour sa purification, et ses portions, et de lui donner les sept jeunes filles choisies de la maison du roi; et il la transféra avec ses jeunes filles dans le meilleur [appartement] de la maison des femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Esther n’avait pas fait connaître son peuple et sa naissance, car Mardochée lui avait commandé de ne pas les faire connaître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Et chaque jour Mardochée se promenait devant la cour de la maison des femmes, pour savoir comment Esther se trouvait et ce qu’on faisait à son égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Et quand venait le tour pour chaque jeune fille d’entrer auprès du roi Assuérus, après qu’il lui avait été fait pendant douze mois selon la règle établie pour les femmes (car c’est ainsi que se complétaient les jours de leur purification: six mois avec de l’huile de myrrhe, et six mois avec des aromates, et les parfums nécessaires à la purification des femmes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'et ainsi la jeune fille entrait auprès du roi), tout ce qu’elle demandait lui était donné pour passer avec elle de la maison des femmes dans la maison du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Le soir elle allait, et le matin elle s’en revenait à la seconde maison des femmes, sous la surveillance de Shaashgaz, eunuque du roi, gardien des concubines. Elle n’entrait plus auprès du roi, à moins que le roi ne trouve plaisir en elle, et qu’elle ne soit appelée par [son] nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Et quand arriva le tour d’Esther, fille d’Abikhaïl, oncle de Mardochée, qui l’avait prise pour fille, d’entrer auprès du roi, elle ne demanda rien, sauf ce que dit Hégaï, eunuque du roi, gardien des femmes. Et Esther trouvait faveur aux yeux de tous ceux qui la voyaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Et Esther fut conduite auprès du roi Assuérus, dans sa maison royale, au dixième mois (c’est le mois de Tébeth), la septième année de son règne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Et le roi aima Esther plus que toutes les femmes, et elle trouva grâce et faveur devant lui plus que toutes les vierges, et il mit la couronne du royaume sur sa tête et la fit reine à la place de Vasthi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Et le roi fit un grand festin à tous ses princes et ses serviteurs, le festin d’Esther; et il octroya un dégrèvement aux provinces et fit des dons selon la puissance du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Et lorsque les vierges furent rassemblées pour la seconde fois, Mardochée était assis à la porte du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Esther, ainsi que le lui avait commandé Mardochée, n’avait pas fait connaître sa naissance et son peuple; et Esther faisait ce que Mardochée disait, comme lorsqu’elle était élevée chez lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, '– En ces jours-là, Mardochée étant assis à la porte du roi, deux des eunuques du roi, d’entre les gardiens du seuil, Bigthan et Théresh, se mirent en colère et cherchèrent à porter la main sur le roi Assuérus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Et la chose vint à la connaissance de Mardochée, et il la rapporta à la reine Esther, et Esther la dit au roi au nom de Mardochée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Et on fit une enquête sur la chose, et elle fut trouvée telle, et les deux [eunuques] furent pendus à un bois. Et cela fut écrit dans le livre des chroniques en présence du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, '*Après ces choses, le roi Assuérus agrandit Haman, fils d’Hammedatha, l’Agaguite, et l’éleva, et plaça son siège au-dessus de tous les princes qui étaient avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'et tous les serviteurs du roi qui étaient à la porte du roi se courbaient et se prosternaient devant Haman: car le roi l’avait ainsi commandé à son égard. Mais Mardochée ne se courbait pas et ne se prosternait pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Alors les serviteurs du roi qui étaient à la porte du roi dirent à Mardochée: Pourquoi transgresses-tu le commandement du roi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Et il arriva que, comme ils lui parlaient jour après jour et qu’il ne les écoutait pas, ils informèrent Haman, pour voir si les affaires de Mardochée se maintiendraient; car il leur avait déclaré qu’il était Juif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Et Haman vit que Mardochée ne se courbait pas et ne se prosternait pas devant lui; et Haman fut rempli de fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Mais cela aurait été une chose méprisable à ses yeux que de mettre la main sur Mardochée seul, car on lui avait appris [quel était] le peuple de Mardochée, et Haman chercha à détruire tous les Juifs qui étaient dans tout le royaume d’Assuérus, le peuple de Mardochée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Au premier mois, qui est le mois de Nisan, la douzième année du roi Assuérus, on jeta le pur, c’est-à-dire le sort, devant Haman, pour chaque jour et pour chaque mois jusqu’au douzième [mois], qui est le mois d’Adar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Et Haman dit au roi Assuérus: Il y a un peuple dispersé et répandu parmi les peuples, dans toutes les provinces de ton royaume, et leurs lois sont différentes [de celles] de tous les peuples; ils ne pratiquent pas les lois du roi, et il ne convient pas au roi de les laisser faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Si le roi le trouve bon, qu’on écrive [l’ordre] de les détruire, et je pèserai 10 000 talents d’argent entre les mains de ceux qui font les affaires, pour qu’on les porte dans le trésor du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Et le roi ôta son anneau de sa main et le donna à Haman, fils d’Hammedatha, l’Agaguite, l’adversaire des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Et le roi dit à Haman: L’argent t’est donné, et le peuple, pour en faire ce qui sera bon à tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Et les scribes du roi furent appelés, le premier mois, le treizième jour du mois, et suivant tout ce qu’Haman commanda, on écrivit aux satrapes du roi et aux gouverneurs qui étaient [préposés] sur chaque province, et aux chefs de chaque peuple, à chaque province selon son écriture et à chaque peuple selon sa langue; ce fut au nom du roi Assuérus qu’on écrivit, et on scella avec l’anneau du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Et les lettres furent envoyées par des courriers dans toutes les provinces du roi, pour détruire, tuer et faire périr tous les Juifs, depuis le jeune garçon jusqu’au vieillard, les enfants et les femmes, et pour que leurs biens soient mis au pillage, en un même jour, le treizième [jour] du douzième mois, qui est le mois d’Adar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Pour que l’édit soit rendu [public] dans chaque province, une copie de l’écrit fut portée à la connaissance de tous les peuples, afin qu’ils soient prêts pour ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Les courriers partirent, pressés par la parole du roi. Et l’édit fut rendu à Suse, la capitale. Et le roi et Haman étaient assis à boire; mais la ville de Suse était dans la consternation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Et Mardochée sut tout ce qui s’était fait; et Mardochée déchira ses vêtements et se couvrit d’un sac et de cendre, et sortit au milieu de la ville et poussa un cri grand et amer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Et il vint jusque devant la porte du roi, car il n’était pas permis d’entrer, vêtu d’un sac, dans la porte du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Et dans chaque province, partout où parvint la parole du roi et son édit, il y eut un grand deuil parmi les Juifs, des jeûnes et des pleurs, et des lamentations; beaucoup firent leur lit du sac et de la cendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Et les jeunes filles d’Esther et ses eunuques vinrent et le lui rapportèrent, et la reine en fut dans une grande angoisse; et elle envoya des vêtements pour vêtir Mardochée, et pour lui faire ôter son sac de dessus lui, mais il ne les accepta pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Et Esther appela Hathac, l’un des eunuques du roi, qu’il avait placé auprès d’elle, et elle lui commanda [d’aller] vers Mardochée pour savoir ce que c’était et pourquoi c’était.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Et Hathac sortit vers Mardochée sur la place de la ville qui était devant la porte du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Et Mardochée l’informa de tout ce qui lui était arrivé, et de la somme d’argent qu’Haman avait dit qu’il paierait au trésor du roi en vue des Juifs, pour les détruire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'et il lui donna une copie de l’écrit de l’édit qui avait été rendu à Suse pour les détruire, afin de le montrer à Esther et de le lui faire connaître, et pour lui commander d’entrer vers le roi, de le supplier et de faire requête devant lui en faveur de son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Et Hathac vint et rapporta à Esther les paroles de Mardochée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Et Esther dit à Hathac et le chargea [de dire] à Mardochée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Tous les serviteurs du roi et le peuple des provinces du roi savent que pour quiconque, homme ou femme, entre auprès du roi, dans la cour intérieure, sans avoir été appelé, [il existe] une même loi [prescrivant] de le mettre à mort, à moins que le roi ne lui tende le sceptre d’or, pour qu’il vive; et moi, je n’ai pas été appelée à entrer vers le roi ces 30 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Et on rapporta à Mardochée les paroles d’Esther.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Et Mardochée dit de répondre à Esther: Ne pense pas en ton âme d’échapper, dans la maison du roi, plutôt que tous les Juifs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'car, si tu gardes le silence en ce temps-ci, le soulagement et la délivrance surgiront pour les Juifs d’autre part, mais toi et la maison de ton père vous périrez. Et qui sait si ce n’est pas pour un temps comme celui-ci que tu es parvenue à la royauté?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Et Esther dit de répondre à Mardochée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Va, rassemble tous les Juifs qui se trouvent à Suse, et jeûnez pour moi, et ne mangez ni ne buvez pendant trois jours, ni la nuit, ni le jour; moi aussi, et mes jeunes filles, nous jeûnerons de même; et ainsi, j’entrerai vers le roi, ce qui n’est pas selon la loi; et si je péris, je périrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Et Mardochée s’en alla et fit selon tout ce qu’Esther lui avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Et il arriva, au troisième jour, qu’Esther se revêtit de son vêtement royal et se présenta dans la cour intérieure de la maison du roi, vis-à-vis de la maison du roi. Et le roi était assis sur le trône de son royaume dans la maison royale, en face de l’entrée de la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Et aussitôt que le roi vit la reine Esther se tenant dans la cour, elle trouva faveur à ses yeux. Et le roi tendit à Esther le sceptre d’or qui était dans sa main. Et Esther s’approcha et toucha le bout du sceptre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Et le roi lui dit: Que veux-tu, reine Esther, et quelle est ta requête? [Quand ce serait] jusqu’à la moitié du royaume, elle te sera donnée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Et Esther dit: Si le roi le trouve bon, que le roi, et Haman [avec lui], vienne aujourd’hui au festin que je lui ai préparé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Et le roi dit: Qu’on cherche vite Haman pour faire ce qu’Esther a dit. Et le roi et Haman vinrent au festin qu’Esther avait préparé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Et le roi dit à Esther pendant qu’on buvait le vin: Quelle est ta demande? Elle te sera accordée. Et quelle est ta requête? [Quand ce serait] jusqu’à la moitié du royaume, ce sera fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Et Esther répondit et dit: [Voici] ma demande et ma requête:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Si j’ai trouvé faveur aux yeux du roi, et si le roi trouve bon d’accorder ma demande et de faire selon ma requête, que le roi et Haman viennent au festin que je leur préparerai, et demain je ferai selon la parole du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Et ce jour-là Haman sortit joyeux et le cœur gai. Mais lorsque Haman vit à la porte du roi, Mardochée qui ne se leva ni ne bougea pour lui, Haman fut rempli de fureur contre Mardochée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Mais Haman se contint et rentra dans sa maison; et il envoya et fit venir ses amis et Zéresh, sa femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Et Haman leur raconta la gloire de ses richesses, et le nombre de ses fils, et tout ce en quoi le roi l’avait agrandi et l’avait élevé au-dessus des princes et des serviteurs du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Et Haman dit: La reine Esther n’a même fait venir personne avec le roi au festin qu’elle a fait, excepté moi; et pour demain aussi, je suis invité chez elle avec le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Mais tout cela ne me sert de rien, aussi longtemps que je vois Mardochée, le Juif, assis à la porte du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Et Zéresh, sa femme, et tous ses amis lui dirent: Qu’on prépare un bois, haut de 50 coudées; et au matin, parle au roi, pour qu’on y pende Mardochée; et va-t’en joyeux au festin avec le roi. Et la chose plut à Haman, et il fit préparer le bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, '*Cette nuit-là le sommeil fuyait le roi, et il ordonna d’apporter le livre d’annales des chroniques, et on les lut devant le roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'et on y trouva écrit que Mardochée avait fait connaître, à l’égard de Bigthan et de Théresh, les deux eunuques du roi, gardiens du seuil, qu’ils avaient cherché à porter la main sur le roi Assuérus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Et le roi dit: Quel honneur et quelle distinction a-t-on conférés à Mardochée, à cause de cela? Et les serviteurs du roi qui le servaient, dirent: On n’a rien fait pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Et le roi dit: Qui est dans la cour? Or Haman était venu dans la cour extérieure de la maison du roi, pour dire au roi de faire pendre Mardochée au bois qu’il avait dressé pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Et les serviteurs du roi lui dirent: Voici Haman, qui se tient dans la cour. Et le roi dit: Qu’il entre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Et Haman entra. Et le roi lui dit: Que faut-il faire à l’homme que le roi se plaît à honorer? Et Haman pensa dans son cœur: À quel autre qu’à moi plairait-il au roi de faire honneur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Et Haman dit au roi: Quant à l’homme que le roi se plaît à honorer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'qu’on apporte le vêtement royal dont le roi se revêt, et le cheval que le roi monte, et sur la tête duquel on met la couronne royale;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'et que le vêtement et le cheval soient remis aux mains d’un des princes du roi les plus illustres; et qu’on revête l’homme que le roi se plaît à honorer, et qu’on le promène par les rues de la ville, monté sur le cheval, et qu’on crie devant lui: C’est ainsi qu’on fait à l’homme que le roi se plaît à honorer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Et le roi dit à Haman: Hâte-toi, prends le vêtement et le cheval, comme tu l’as dit, et fais ainsi à Mardochée, le Juif, qui est assis à la porte du roi. N’omets rien de tout ce que tu as dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Et Haman prit le vêtement et le cheval, et revêtit Mardochée et le promena à cheval par les rues de la ville, et il criait devant lui: C’est ainsi qu’on fait à l’homme que le roi se plaît à honorer!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Et Mardochée revint à la porte du roi. Et Haman se rendit en hâte à sa maison, triste et la tête couverte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Et Haman raconta à Zéresh, sa femme, et à tous ses amis, tout ce qui lui était arrivé. Et ses sages et Zéresh, sa femme, lui dirent: Si Mardochée devant lequel tu as commencé de tomber est de la race des Juifs, tu ne l’emporteras pas sur lui, mais tu tomberas certainement devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Comme ils parlaient encore avec lui, les eunuques du roi s’approchèrent et se hâtèrent de conduire Haman au festin qu’Esther avait préparé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Et le roi et Haman vinrent pour boire avec la reine Esther.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Et le roi dit à Esther, le second jour aussi, pendant qu’on buvait le vin: Quelle est ta demande, reine Esther? et elle te sera accordée. Et quelle est ta requête? [Quand ce serait] jusqu’à la moitié du royaume, ce sera fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Et la reine Esther répondit et dit: Si j’ai trouvé faveur à tes yeux, ô roi, et si le roi le trouve bon, qu’à ma demande il m’accorde ma vie, et mon peuple à ma requête!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Car nous sommes vendus, moi et mon peuple, pour être détruits [et] tués, et pour périr. Or si nous avions été vendus pour être serviteurs et servantes, j’aurais gardé le silence, bien que l’ennemi ne puisse compenser le dommage fait au roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Et le roi Assuérus parla et dit à la reine Esther: Qui est-il, et où est-il, celui que son cœur a rempli [de la pensée] de faire ainsi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Et Esther dit: L’adversaire et l’ennemi, c’est ce méchant Haman. Et Haman fut terrifié devant le roi et la reine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Et le roi, dans sa fureur, se leva du festin, [et s’en alla] dans le jardin du palais. Et Haman resta pour faire requête pour sa vie auprès de la reine Esther; car il voyait que son malheur était décidé de la part du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Et le roi revint du jardin du palais dans la maison du festin. Et Haman était tombé sur le divan sur lequel était Esther. Et le roi dit: Veut-il encore faire violence à la reine, chez moi, dans la maison? La parole sortit de la bouche du roi, et on couvrit la face d’Haman.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Et Harbona, l’un des eunuques, dit devant le roi: Voici, le bois, haut de 50 coudées, qu’Haman avait préparé pour Mardochée, qui a parlé pour le bien du roi, est dressé dans la maison d’Haman. Et le roi dit: Qu’on l’y pende!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Et on pendit Haman au bois qu’il avait dressé pour Mardochée. Et la colère du roi s’apaisa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Ce jour-là, le roi Assuérus donna à la reine Esther la maison d’Haman, l’oppresseur des Juifs. Et Mardochée entra devant le roi, car Esther avait déclaré ce qu’il lui était.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Et le roi ôta son anneau qu’il avait retiré à Haman, et le donna à Mardochée. Et Esther établit Mardochée sur la maison d’Haman.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Et Esther parla encore devant le roi, et tomba à ses pieds et pleura, et le supplia de mettre à néant le mal médité par Haman, l’Agaguite, et le dessein qu’il avait formé contre les Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Et le roi tendit à Esther le sceptre d’or, et Esther se leva et se tint devant le roi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'et elle dit: Si le roi le trouve bon, et si j’ai trouvé faveur devant lui, et que le roi estime la chose avantageuse, et que moi, je sois agréable à ses yeux, qu’on écrive pour révoquer les lettres ourdies par Haman, fils d’Hammedatha, l’Agaguite, qu’il a écrites pour faire périr les Juifs qui sont dans toutes les provinces du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Car comment pourrai-je voir le malheur qui atteindra mon peuple, et comment pourrai-je voir la destruction de ma race?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Et le roi Assuérus dit à la reine Esther et à Mardochée, le Juif: Voici, j’ai donné à Esther la maison d’Haman; et lui, on l’a pendu au bois parce qu’il a étendu sa main contre les Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Vous donc, écrivez au nom du roi à l’égard des Juifs ce qui vous paraîtra bon, et scellez-le avec l’anneau du roi. Car un écrit qui a été écrit au nom du roi et scellé avec l’anneau du roi ne peut être révoqué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Et les scribes du roi furent appelés en ce temps-là, au troisième mois, qui est le mois de Sivan, le vingt-troisième [jour] du mois; et, selon tout ce que Mardochée commanda, on écrivit aux Juifs, et aux satrapes, et aux gouverneurs, et aux chefs des provinces, depuis l’Inde jusqu’à l’Éthiopie, 127 provinces, à chaque province selon son écriture, et à chaque peuple selon sa langue, et aux Juifs selon leur écriture et selon leur langue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Et [Mardochée] écrivit au nom du roi Assuérus et scella avec l’anneau du roi; et il envoya des lettres par des courriers à cheval, montés sur des coursiers, des chevaux de race, produits des haras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, '[Ces lettres portaient] que le roi accordait aux Juifs, dans chaque ville, de s’assembler et de se mettre en défense pour leur vie, [et] de détruire, tuer, et faire périr toute force du peuple et de la province qui les opprimerait, – eux [et leurs] enfants et [leurs] femmes, et de mettre au pillage leurs biens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'en un même jour, dans toutes les provinces du roi Assuérus, le treizième [jour] du douzième mois, qui est le mois d’Adar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Pour que l’édit soit rendu [public] dans chaque province, une copie de l’écrit fut portée à la connaissance de tous les peuples, afin que les Juifs soient prêts pour ce jour-là, pour se venger de leurs ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Les courriers, montés sur les coursiers, des chevaux de race, partirent, hâtés et pressés par la parole du roi. Et l’édit fut rendu à Suse, la capitale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Et Mardochée sortit de devant le roi, avec un vêtement royal bleu et blanc, une grande couronne d’or, et un manteau de byssus et de pourpre; et la ville de Suse poussait des cris de joie et se réjouissait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Pour les Juifs il y avait lumière et joie, et allégresse et honneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Et, dans chaque province et dans chaque ville, partout où parvenait la parole du roi et son édit, il y eut de la joie et de l’allégresse pour les Juifs, un festin et un jour de fête; et beaucoup de gens parmi les peuples du pays se firent Juifs, car la frayeur des Juifs tomba sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, '*Et au douzième mois, qui est le mois d’Adar, le treizième jour du mois, où la parole du roi et son édit allaient être exécutés, au jour où les ennemis des Juifs espéraient se rendre maîtres d’eux (mais la chose fut changée en ce que ces mêmes Juifs se rendirent maîtres de ceux qui les haïssaient),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'les Juifs s’assemblèrent dans leurs villes, dans toutes les provinces du roi Assuérus, pour mettre la main sur ceux qui cherchaient leur malheur; et personne ne tint devant eux, car la frayeur des [Juifs] tomba sur tous les peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Et tous les chefs des provinces, et les satrapes, et les gouverneurs, et ceux qui faisaient les affaires du roi, assistaient les Juifs, car la frayeur de Mardochée était tombée sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Car Mardochée était grand dans la maison du roi, et sa renommée se répandait dans toutes les provinces; car cet homme, Mardochée, allait toujours grandissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Et les Juifs frappèrent tous leurs ennemis à coups d’épée, [les] tuant et [les] faisant périr, et ils firent ce qu’ils voulurent à ceux qui les haïssaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Et à Suse, la capitale, les Juifs tuèrent et firent périr 500 hommes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'et ils tuèrent Parshandatha, et Dalphon, et Aspatha,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'et Poratha, et Adalia, et Aridatha,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'et Parmashtha, et Arisaï, et Aridaï, et Vajezatha,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'les dix fils d’Haman, fils d’Hammedatha, l’oppresseur des Juifs; mais ils ne mirent pas la main sur le butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'En ce jour-là, on porta devant le roi le nombre de ceux qui avaient été tués dans Suse, la capitale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Et le roi dit à la reine Esther: Les Juifs ont tué et fait périr dans Suse, la capitale, 500 hommes et les dix fils d’Haman; qu’auront-ils fait dans les autres provinces du roi? Et quelle est ta demande? elle te sera accordée. Et quelle est encore ta requête? et ce sera fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Et Esther dit: Si le roi le trouve bon, qu’il soit accordé encore demain aux Juifs qui sont à Suse de faire selon l’édit d’aujourd’hui; et qu’on pende au bois les dix fils d’Haman.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Et le roi dit de faire ainsi; et l’édit fut rendu dans Suse; et on pendit les dix fils d’Haman.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Et les Juifs qui étaient à Suse s’assemblèrent aussi le quatorzième jour du mois d’Adar, et ils tuèrent dans Suse 300 hommes; mais ils ne mirent pas la main sur le butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Et le reste des Juifs qui étaient dans les provinces du roi s’assemblèrent et se mirent en défense pour leur vie, et eurent du repos de leurs ennemis; et ils tuèrent 75 000 de ceux qui les haïssaient; mais ils ne mirent pas la main sur le butin:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, '[ce fut] le treizième jour du mois d’Adar; et le quatorzième [jour] du mois, ils se reposèrent, et ils en firent un jour de festin et de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Et les Juifs qui étaient à Suse s’assemblèrent le treizième [jour] du mois et le quatorzième [jour], et ils se reposèrent le quinzième [jour], et en firent un jour de festin et de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'C’est pourquoi les Juifs de la campagne qui habitaient des villes ouvertes, firent du quatorzième [jour] du mois d’Adar un jour de joie et de festin, et un jour de fête, où l’on s’envoyait des portions l’un à l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Et Mardochée écrivit ces choses et envoya des lettres à tous les Juifs qui étaient dans toutes les provinces du roi Assuérus, à ceux qui étaient près et à ceux qui étaient loin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'afin d’établir pour eux qu’ils célébreraient le quatorzième jour du mois d’Adar et le quinzième jour, chaque année,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'comme des jours dans lesquels les Juifs avaient eu du repos de leurs ennemis, et comme le mois où leur douleur avait été changée en joie, et leur deuil en un jour de fête, pour en faire des jours de festin et de joie, où l’on s’envoie des portions l’un à l’autre, et [où l’on fait] des dons aux pauvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Et les Juifs acceptèrent de faire ce qu’ils avaient commencé et ce que Mardochée leur avait écrit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Car Haman, fils d’Hammedatha, l’Agaguite, l’oppresseur de tous les Juifs, avait tramé contre les Juifs de les faire périr, et avait fait jeter le pur, c’est-à-dire le sort, pour les détruire et les faire périr.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Et quand [Esther] vint devant le roi, il ordonna, par lettres, que le méchant dessein qu’[Haman] avait tramé contre les Juifs retombe sur sa propre tête, et on le pendit au bois, lui et ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'C’est pourquoi on appela ces jours Purim, d’après le nom de pur. C’est pourquoi, à cause de toutes les paroles de cette lettre, et à cause de ce qu’ils avaient ainsi vu et de ce qui leur était arrivé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'les Juifs établirent et acceptèrent pour eux et pour leur semence, et pour tous ceux qui se joindraient à eux, de ne pas négliger de célébrer chaque année ces deux jours selon leur ordonnance et selon leur temps fixé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'et qu’on se souviendrait de ces jours et qu’on les célébrerait dans toutes les générations, dans chaque famille, dans chaque province, et dans chaque ville; et que ces jours de Purim ne seraient point négligés au milieu des Juifs, et que leur mémoire ne périrait jamais chez leur semence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Et la reine Esther, fille d’Abikhaïl, et Mardochée, le Juif, écrivirent avec toute insistance pour confirmer cette seconde lettre sur les Purim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'et à tous les Juifs dans les 127 provinces du royaume d’Assuérus, il envoya des lettres [avec] des paroles de paix et de vérité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'pour confirmer ces jours de Purim à leurs époques fixes, comme Mardochée, le Juif, et la reine Esther les avaient établis pour eux, et comme ils les avaient établis pour eux-mêmes et pour leur semence, à l’occasion de leurs jeûnes et de leur cri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Et l’ordre d’Esther établit ce qui concernait ces [jours de] Purim, et cela fut écrit dans le livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, '*Et le roi Assuérus imposa un tribut sur le pays et sur les îles de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Et tous les actes de sa puissance et de sa force, et la déclaration de la grandeur de Mardochée, comment le roi l’éleva, ne sont-ils pas écrits dans le livre des chroniques des rois de Médie et de Perse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Car Mardochée, le Juif, fut le second après le roi Assuérus, et il fut grand parmi les Juifs et agréable à la multitude de ses frères, cherchant le bien de son peuple et parlant pour la paix de toute sa race.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Il y avait dans le pays d’Uts un homme dont le nom était Job; et cet homme était parfait et droit, craignant Dieu et se retirant du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Et il lui naquit sept fils et trois filles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'et il possédait 7 000 brebis, et 3 000 chameaux, et 500 paires de bœufs, et 500 ânesses; et [il avait] un très grand nombre de serviteurs; et cet homme était plus grand que tous les fils de l’orient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Et ses fils allaient et faisaient un festin, chacun dans [sa] maison, à son jour; et ils envoyaient appeler leurs trois sœurs pour manger et pour boire avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Et il arrivait que, quand les jours de festin étaient terminés, Job envoyait [vers eux] et les sanctifiait: il se levait de bonne heure le matin et offrait des holocaustes selon leur nombre à tous, car Job disait: Peut-être mes fils ont-ils péché et ont-ils maudit Dieu dans leurs cœurs. Job faisait toujours ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Or, un jour, il arriva que les fils de Dieu vinrent se présenter devant l’ Éternel, et Satan aussi vint au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Et l’ Éternel dit à Satan: D’où viens-tu? Et Satan répondit à l’ Éternel et dit: De courir çà et là sur la terre et de m’y promener.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Et l’ Éternel dit à Satan: As-tu considéré mon serviteur Job, qu’il n’y a sur la terre aucun homme comme lui, parfait et droit, craignant Dieu, et se retirant du mal?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Et Satan répondit à l’ Éternel et dit: Est-ce pour rien que Job craint Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Ne l’as-tu pas, toi, entouré de toutes parts d’une haie de protection, lui, et sa maison, et tout ce qui lui appartient? Tu as béni le travail de ses mains, et tu as fait abonder son avoir sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Mais étends ta main et touche à tout ce qu’il a: [tu verras] s’il ne te maudit pas en face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Et l’ Éternel dit à Satan: Voici, tout ce qu’il a est en ta main, seulement tu n’étendras pas ta main sur lui. Et Satan sortit de la présence de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Et, un jour, il arriva que ses fils et ses filles mangeaient et buvaient du vin dans la maison de leur frère premier-né;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'et un messager vint à Job et dit: Les bœufs labouraient et les ânesses paissaient auprès d’eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'et ceux de Sheba sont tombés [sur eux] et les ont pris, et ils ont frappé les jeunes hommes par le tranchant de l’épée; et j’ai échappé, moi seul, pour te l’annoncer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Celui-ci parlait encore, qu’un autre vint et dit: Le feu de Dieu est tombé du ciel et a brûlé les brebis et les jeunes hommes, et les a consumés; et j’ai échappé, moi seul, pour te l’annoncer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Celui-ci parlait encore, qu’un autre vint et dit: Les Chaldéens ont formé trois bandes, et se sont jetés sur les chameaux et les ont pris, et ils ont frappé les jeunes hommes par le tranchant de l’épée; et j’ai échappé, moi seul, pour te l’annoncer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Celui-ci parlait encore, qu’un autre vint et dit: Tes fils et tes filles mangeaient et buvaient du vin dans la maison de leur frère premier-né,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'et voici, un grand vent est venu d’au-delà du désert et a donné contre les quatre coins de la maison, et elle est tombée sur les jeunes gens et ils sont morts; et j’ai échappé, moi seul, pour te l’annoncer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Et Job se leva, et déchira sa robe, et rasa sa tête, et se jeta à terre et se prosterna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Et il dit: Nu je suis sorti du sein de ma mère, et nu j’y retournerai; l’ Éternel a donné, et l’ Éternel a pris; que le nom de l’ Éternel soit béni!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'En tout cela Job ne pécha pas, et n’attribua rien à Dieu qui soit inconvenable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Or, un jour, il arriva que les fils de Dieu vinrent se présenter devant l’ Éternel, et Satan aussi vint au milieu d’eux se présenter devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Et l’ Éternel dit à Satan: D’où viens-tu? Et Satan répondit à l’ Éternel et dit: De courir çà et là sur la terre et de m’y promener.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Et l’ Éternel dit à Satan: As-tu considéré mon serviteur Job, qu’il n’y a sur la terre aucun homme comme lui, parfait et droit, craignant Dieu, et se retirant du mal? Et encore il reste ferme dans sa perfection, alors que tu m’as incité contre lui pour l’engloutir sans cause.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Et Satan répondit à l’ Éternel et dit: Peau pour peau, et tout ce qu’un homme a, il le donnera pour sa vie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'mais étends ta main et touche à ses os et à sa chair: [tu verras] s’il ne te maudit pas en face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Et l’ Éternel dit à Satan: Le voilà entre tes mains, seulement épargne sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Et Satan sortit de la présence de l’ Éternel; et il frappa Job d’un ulcère malin, depuis la plante de ses pieds jusqu’au sommet de sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Et il prit un tesson pour s’en gratter, et il était assis dans la cendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Et sa femme lui dit: Restes-tu encore ferme dans ta perfection? Maudis Dieu et meurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Et il lui dit: Tu parles comme parlerait l’une des insensées; nous avons reçu le bien aussi de la part de Dieu, et nous ne recevrions pas le mal? En tout cela Job ne pécha point de ses lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Et trois amis de Job apprirent tout ce mal qui lui était arrivé et vinrent chacun de son lieu, Éliphaz, le Thémanite, et Bildad, le Shukhite, et Tsophar, le Naamathite; et ils s’entendirent ensemble pour venir le plaindre et le consoler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Et ils levèrent les yeux de loin, et ils ne le reconnurent pas; et ils élevèrent leur voix et pleurèrent, et ils déchirèrent chacun sa robe et répandirent de la poussière sur leurs têtes [en la jetant] vers les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Et ils s’assirent avec lui à terre sept jours et sept nuits, et nul ne lui dit une parole, car ils voyaient que sa douleur était très grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, '***Après cela, Job ouvrit sa bouche et maudit son jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Et Job prit la parole et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Périsse le jour auquel je naquis, et la nuit qui dit: Un homme a été conçu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Ce jour-là, qu’il soit ténèbres; que ✝Dieu ne s’en enquière pas d’en haut, et que la lumière ne resplendisse pas sur lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Que les ténèbres et l’ombre de la mort le réclament; que les nuées demeurent sur lui; que ce qui assombrit les jours le terrifie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Cette nuit-là, que l’obscurité s’en empare; qu’elle ne se réjouisse point parmi les jours de l’année, qu’elle n’entre pas dans le nombre des mois!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Voici, que cette nuit-là soit stérile; que les cris de joie n’y entrent pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Que ceux qui maudissent le jour la maudissent, ceux qui sont prêts à réveiller Léviathan!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Que les étoiles de son crépuscule soient obscurcies; qu’elle attende la lumière, et qu’il n’y en ait point, et qu’elle ne voie pas les cils de l’aurore!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Parce qu’elle n’a pas fermé les portes du sein qui m’a porté, et n’a pas caché la misère de devant mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Pourquoi ne suis-je pas mort dès la matrice, n’ai-je pas expiré quand je sortis du ventre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Pourquoi les genoux m’ont-ils rencontré, et pourquoi les mamelles, pour les téter?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Car maintenant je serais couché et je serais tranquille, je dormirais: alors j’aurais du repos,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Avec les rois et les conseillers de la terre qui se bâtissent des solitudes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Ou avec les princes qui ont de l’or, qui ont rempli d’argent leurs maisons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Ou, comme un avorton caché, je n’aurais pas été, – comme les petits enfants qui n’ont pas vu la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Là, les méchants ont cessé leur tumulte, et là ceux dont les forces sont épuisées par la fatigue sont en repos;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Les prisonniers demeurent ensemble tranquilles, ils n’entendent pas la voix de l’exacteur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Là sont le petit et le grand, et le serviteur libéré de son maître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Pourquoi la lumière est-elle donnée au misérable, et la vie à ceux qui ont l’amertume dans l’âme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'À ceux qui attendent la mort, et elle n’est pas là, – qui la cherchent plus que des trésors cachés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Qui se réjouissent jusqu’aux transports [et] sont dans l’allégresse, parce qu’ils ont trouvé le sépulcre, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'À l’homme de qui le chemin est caché et que ✝Dieu a enfermé de toutes parts?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Car mon gémissement vient avant mon pain, et mes rugissements débordent comme des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Car j’ai eu une crainte, et elle est venue sur moi, et ce que j’appréhendais m’est arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Je n’étais pas en sécurité, et je n’étais pas tranquille ni en repos, et le trouble est venu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, '*Et Éliphaz, le Thémanite, répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Si nous essayons de t’adresser une parole, en seras-tu irrité? Mais qui pourrait se retenir de parler?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Voici, tu en as enseigné beaucoup, et tu as fortifié les mains languissantes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Tes paroles ont tenu droit celui qui chancelait, et tu as affermi les genoux qui ployaient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Mais maintenant [le malheur] est venu sur toi, et tu es irrité; il t’atteint, et tu es troublé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Ta crainte [de Dieu] n’est-elle pas ta confiance, et l’intégrité de tes voies, ton espérance?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Souviens-toi, je te prie, qui a péri étant innocent? et où les hommes droits ont-ils été détruits?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Selon ce que j’ai vu, ceux qui labourent l’iniquité et qui sèment la misère, la moissonnent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Ils périssent par le souffle de ✝Dieu, et sont consumés par le souffle de ses narines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Le rugissement du lion et la voix du [lion] rugissant [sont étouffés], et les dents des jeunes lions sont brisées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Le lion fort périt faute de proie, et les petits de la lionne sont dispersés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Une parole vint à moi secrètement, et mon oreille en saisit la susurration,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Au milieu des pensées que font naître les visions de la nuit, quand un sommeil profond tombe sur les hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'La frayeur vint sur moi, et le frisson, et elle fit trembler la multitude de mes os;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Et un esprit passa devant moi: les cheveux de ma chair se dressèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Il se tint là; je ne reconnus pas son apparence: une forme était devant mes yeux. J’entendis un léger murmure et une voix:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Un mortel sera-t-il plus juste que ✝Dieu, l’homme sera-t-il plus pur que celui qui l’a fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Voici, il ne se fie pas à ses serviteurs, et ses anges il les charge de folie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Combien plus à ceux qui habitent dans des maisons d’argile dont le fondement est dans la poussière, qui sont écrasés comme la teigne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Du matin au soir, ils sont frappés; ils périssent pour toujours sans qu’on y fasse attention.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Leurs cordes ne leur sont-elles pas arrachées? Ils meurent, et sans sagesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Crie donc! Y a-t-il quelqu’un qui te réponde? Et vers lequel des saints te tourneras-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Car le chagrin fait mourir le sot, et la jalousie tue le simple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'J’ai vu le sot s’enraciner, et soudain j’ai maudit sa demeure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Ses fils sont loin de la sûreté, et sont écrasés dans la porte, et il n’y a personne pour délivrer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Sa moisson, l’affamé la mange, et jusque parmi les épines il la prend; et le piège guette son bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Car l’affliction ne sort pas de la poussière, et la misère ne germe pas du sol;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Car l’homme est né pour la misère, comme les étincelles volent en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Mais moi je rechercherai ✶Dieu, et devant Dieu je placerai ma cause, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Qui fait de grandes choses qu’on ne peut sonder, des merveilles à ne pouvoir les compter;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Qui donne la pluie sur la face de la terre, et envoie des eaux sur la face des campagnes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Plaçant en haut ceux qui sont abaissés; et ceux qui sont en deuil sont élevés au bonheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Il dissipe les projets des hommes rusés, et leurs mains n’accomplissent pas leurs conseils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Il prend les sages dans leur ruse, et le conseil des astucieux est précipité:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'De jour, ils rencontrent les ténèbres, et en plein midi ils marchent à tâtons, comme de nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Et il sauve le pauvre de l’épée, de leur bouche, et de la main du fort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Et il arrive au chétif ce qu’il espère, et l’iniquité a la bouche fermée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Voici, bienheureux l’homme que ✝Dieu reprend! Ne méprise donc pas le châtiment du Tout-puissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Car c’est lui qui fait la plaie et qui la bande; il frappe, et ses mains guérissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'En six détresses il te délivrera, et, dans sept, le mal ne t’atteindra pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Dans la famine il te délivrera de la mort, et, dans la guerre, de la puissance de l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Tu seras à couvert du fouet de la langue, et tu ne craindras pas le désastre quand il viendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Tu te riras du désastre et de la faim, et tu n’auras pas peur des bêtes de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Car tu auras une alliance avec les pierres des champs, et les bêtes des champs seront en paix avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Tu sauras que ta tente est prospère, tu visiteras ta demeure et tu n’y trouveras rien qui manque,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Et tu sauras que ta postérité est nombreuse, et tes rejetons, comme l’herbe de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Tu entreras au sépulcre en bonne vieillesse, comme on enlève le tas de gerbes en sa saison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Voici, nous avons examiné cela; il en est ainsi. Écoute-le, et sache-le pour toi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, '*Et Job répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Oh! si mon chagrin était bien pesé, et si on mettait toute ma calamité dans la balance!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Car maintenant elle pèserait plus que le sable des mers; c’est pourquoi mes paroles sont outrées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Car les flèches du Tout-puissant sont en moi, leur venin boit mon esprit; les frayeurs de ✝Dieu se rangent en bataille contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'L’âne sauvage brait-il auprès de l’herbe? Le bœuf mugit-il auprès de son fourrage?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Ce qui est insipide, le mange-t-on sans sel? Y a-t-il de la saveur dans le blanc d’un œuf?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Ce que mon âme refusait de toucher est comme ma dégoûtante nourriture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Oh! si ma demande s’accomplissait, et si ✝Dieu m’accordait mon désir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'S’il plaisait à ✝Dieu de m’écraser, de lâcher sa main et de me retrancher!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Alors il y aurait encore pour moi une consolation, et, dans la douleur qui ne m’épargne pas, je me réjouirais de ce que je n’ai pas renié les paroles du Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Quelle est ma force pour que j’attende, et quelle est ma fin pour que je patiente?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Ma force est-elle la force des pierres? Ma chair est-elle d’airain?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'N’est-ce pas qu’il n’y a point de secours en moi, et que toute capacité est chassée loin de moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'À celui qui est défaillant est due la miséricorde de la part de son ami, sinon il abandonnera la crainte du Tout-puissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Mes frères m’ont trahi comme un torrent, comme le lit des torrents qui passent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Qui sont troubles à cause des glaces, dans lesquels la neige se cache;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Au temps où ils se resserrent ils tarissent, quand la chaleur les frappe ils disparaissent de leur lieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Ils serpentent dans les sentiers de leur cours, ils s’en vont dans le désert, et périssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Les caravanes de Théma les cherchaient du regard, les voyageurs de Sheba s’attendaient à eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Ils ont été honteux de leur confiance; ils sont venus là, et ont été confondus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'De même maintenant vous n’êtes rien; vous avez vu un objet de terreur, et vous vous êtes effrayés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Ai-je dit: Donnez-moi, et de votre richesse faites-moi des présents,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Et délivrez-moi de la main de l’oppresseur, et rachetez-moi de la main des terribles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Enseignez-moi, et je me tairai; et faites-moi comprendre en quoi je me trompe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Combien sont puissantes les paroles justes! Mais la censure de votre part que reprend-elle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Songez-vous à censurer des discours? Mais les paroles d’un désespéré ne sont faites que pour le vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Certes, vous tombez sur l’orphelin, et vous creusez [une fosse] pour votre ami.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Et maintenant, si vous voulez, regardez-moi; vous mentirais-je donc en face?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Revenez, je vous prie; qu’il n’y ait pas d’injustice; oui, revenez encore: ma justice sera là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Y a-t-il de l’iniquité en ma langue? Mon palais ne discernerait-il pas la méchanceté?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'L’homme n’a-t-il pas une vie de labeur sur la terre? Et ses jours ne sont-ils pas comme les jours d’un mercenaire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Comme l’esclave soupire après l’ombre, et comme le mercenaire attend son salaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Ainsi j’ai eu pour partage des mois de déception, et des nuits de misère me sont assignées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Si je me couche, alors je dis: Quand me lèverai-je et quand l’obscurité prendra-t-elle fin? et je suis excédé d’agitations jusqu’au point du jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Ma chair est couverte de vers et de croûtes de terre, ma peau se retire et suppure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Mes jours s’en vont plus vite qu’une navette, et finissent sans espérance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Souviens-toi que ma vie n’est qu’un souffle: mon œil ne reverra pas le bien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'L’œil qui me regarde ne me reverra plus; tes yeux sont sur moi, et je ne suis plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'La nuée disparaît et s’en va; ainsi celui qui descend au shéol n’en remonte pas,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Il ne revient plus dans sa maison, et son lieu ne le reconnaît plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Aussi je ne retiendrai pas ma bouche; je parlerai dans la détresse de mon esprit, je discourrai dans l’amertume de mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Suis-je une mer, suis-je un monstre marin, que tu établisses des gardes autour de moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Quand je dis: Mon lit me consolera, ma couche allégera ma détresse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Alors tu m’effraies par des songes, tu me terrifies par des visions,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Et mon âme choisit la suffocation, – plutôt la mort que mes os:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'J’en suis dégoûté; je ne vivrai pas à toujours. Laisse-moi, car mes jours sont vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Qu’est-ce que l’homme que tu fasses grand cas de lui, et que ton cœur s’occupe de lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Et que tu le visites chaque matin, que tu l’éprouves à tout moment?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Pourquoi ne détournes-tu pas les yeux de moi, et ne me laisses-tu pas tranquille jusqu’à ce que j’aie avalé ma salive?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'J’ai péché; – que t’ai-je fait? Toi qui observes l’homme, pourquoi m’as-tu placé pour être l’objet de tes coups, de sorte que je suis un fardeau à moi-même?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Et pourquoi ne pardonnes-tu pas ma transgression, et ne fais-tu point passer mon iniquité? Car maintenant je me coucherai dans la poussière, et tu me chercheras, et je ne serai plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, '*Et Bildad, le Shukhite, répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Jusques à quand diras-tu ces choses, et les paroles de ta bouche seront-elles un vent impétueux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Est-ce que ✶Dieu pervertit le droit? Le Tout-puissant pervertira-t-il la justice?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Si tes fils ont péché contre lui, il les a aussi livrés en la main de leur transgression.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Si tu recherches ✶Dieu et que tu supplies le Tout-puissant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Si tu es pur et droit, certainement il se réveillera maintenant en ta faveur, et rendra prospère la demeure de ta justice;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Et ton commencement aura été petit, mais ta fin sera très grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Car interroge, je te prie, la génération précédente, et sois attentif aux recherches de leurs pères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Car nous sommes d’hier et nous n’avons pas de connaissance, car nos jours sont une ombre sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Ceux-là ne t’enseigneront-ils pas, ne te parleront-ils pas, et de leurs cœurs ne tireront-ils pas des paroles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Le papyrus s’élève-t-il où il n’y a pas de marais? Le roseau croît-il sans eau?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Encore dans sa verdeur, sans qu’on l’ait arraché, avant toute herbe il sèche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Tels sont les sentiers de tous ceux qui oublient ✶Dieu; et l’attente de l’impie périra;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Son assurance sera retranchée, et sa confiance sera une toile d’araignée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Il s’appuiera sur sa maison, et elle ne tiendra pas; il s’y cramponnera, et elle ne restera pas debout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Il est verdoyant devant le soleil, et son rameau s’étend sur son jardin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Ses racines s’entrelacent dans un tas de rocaille, il voit la demeure des pierres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'S’Il l’ôte de sa place, celle-ci le désavouera: Je ne t’ai pas vu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Telles sont les délices de ses voies; et de la poussière, d’autres germeront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Voici, ✶Dieu ne méprisera pas l’homme parfait, et ne soutiendra pas les mains des méchants:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Tandis qu’il remplira ta bouche de rire et tes lèvres de chants de joie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Ceux qui te haïssent seront revêtus de honte, et la tente des méchants ne sera plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, '*Et Job répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'En vérité, je sais qu’il en est ainsi. Mais comment l’homme sera-t-il juste devant ✶Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'S’il se plaît à contester avec lui, il ne lui répondra pas sur un point entre mille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Il est sage de cœur et puissant en force: qui s’est endurci contre lui et a prospéré?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Il transporte les montagnes, et elles ne savent pas qu’il les renverse dans sa colère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Il remue la terre de sa place, et ses colonnes tremblent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Il parle au soleil, et [le soleil] ne se lève pas; et sur les étoiles il met son sceau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Seul il étend les cieux et marche sur les hauteurs de la mer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Il fait la grande Ourse, Orion, et les Pléiades, et les chambres du midi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Il fait de grandes choses qu’on ne saurait sonder, et des merveilles à ne pouvoir les compter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Voici, il passe près de moi, et je ne [le] vois pas; et il passe à côté [de moi], et je ne l’aperçois pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Voici, il ravit; qui l’en détournera? Qui lui dira: Que fais-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, '✝Dieu ne retire pas sa colère; sous lui fléchissent les orgueilleux qui prêtent secours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Combien moins lui répondrais-je, moi, [et] choisirais-je mes paroles avec lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Si j’étais juste, je ne lui répondrais pas, je demanderais grâce à mon juge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Si je criais, et qu’il me réponde, je ne croirais pas qu’il ait prêté l’oreille à ma voix, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Lui qui m’écrase dans une tempête, et qui multiplie mes blessures sans cause.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Il ne me permet pas de reprendre haleine; car il me rassasie d’amertumes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'S’agit-il de force, voici, il est fort; s’agit-il de jugement: Qui m’assignera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Si je me justifiais, ma bouche me condamnerait; si j’étais parfait, il me montrerait pervers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Si j’étais parfait, je méconnaîtrais mon âme, je mépriserais ma vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Tout revient au même; c’est pourquoi j’ai dit: Il consume le parfait et le méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Si le fléau donne subitement la mort, il se rit de l’épreuve de l’innocent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'La terre est livrée en la main du méchant: il couvre la face de ses juges. S’il n’en est pas ainsi, qui est-ce donc?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Mes jours s’en vont plus vite qu’un coureur; ils fuient, ils ne voient pas ce qui est bon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Ils passent rapides comme les barques de jonc, comme un aigle qui fond sur sa proie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Si je dis: J’oublierai ma plainte, je renoncerai à mon visage [morne] et je serai joyeux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Je suis épouvanté de tous mes tourments; je sais que tu ne me tiendras pas pour innocent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Soit, je suis méchant: pourquoi me fatigué-je ainsi en vain?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Si je me lave avec de l’eau de neige, et que je nettoie mes mains dans la pureté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Alors tu me plongeras dans un fossé, et mes vêtements m’auront en horreur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Car il n’est pas homme, comme moi, pour que je lui réponde, pour que nous allions ensemble en jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Il n’y a pas entre nous un arbitre qui mettrait sa main sur nous deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Qu’il retire sa verge de dessus moi, et que sa terreur ne me trouble pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Alors je parlerai et je ne le craindrai pas; mais il n’en est pas ainsi de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Mon âme est dégoûtée de ma vie; je laisserai libre cours à ma plainte, je parlerai dans l’amertume de mon âme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Je dirai à ✝Dieu: Ne me condamne pas; fais-moi savoir pourquoi tu contestes avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Prends-tu plaisir à opprimer, que tu méprises le travail de tes mains, et que tu fasses briller ta lumière sur le conseil des méchants?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'As-tu des yeux de chair? Vois-tu comme voit l’homme mortel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Tes jours sont-ils comme les jours d’un mortel, ou tes années, comme les jours de l’homme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Que tu recherches mon iniquité et que tu scrutes mon péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Puisque tu sais que je ne suis pas un méchant, et que nul ne délivre de ta main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Tes mains m’ont formé et m’ont façonné tout à l’entour en un tout, et tu m’engloutis!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Souviens-toi, je te prie, que tu m’as façonné comme de l’argile, et que tu me feras retourner à la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Ne m’as-tu pas coulé comme du lait, et fait cailler comme du fromage?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Tu m’as revêtu de peau et de chair, tu m’as tissé d’os et de nerfs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Tu m’as donné la vie, et tu as usé de bonté envers moi, et tes soins ont gardé mon esprit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Et tu cachais ces choses dans ton cœur: je sais que cela était par-devers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Si j’ai péché, tu m’as aussi observé, et tu ne me tiendras pas pour innocent de mon iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Si j’ai agi méchamment, malheur à moi! Si j’ai marché justement, je ne lèverai pas ma tête, rassasié que je suis de mépris et voyant ma misère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Et elle augmente: tu me fais la chasse comme un lion, et en moi tu répètes tes merveilles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Tu renouvelles tes témoins contre moi, et tu multiplies ton indignation contre moi. Une succession [de maux] et un temps de misère sont avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Et pourquoi m’as-tu fait sortir du sein [de ma mère]? J’aurais expiré, et aucun œil ne m’aurait vu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'J’aurais été comme si je n’avais pas été; de la matrice on m’aurait porté au sépulcre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Mes jours ne sont-ils pas en petit nombre? Qu’il cesse [donc], qu’il se retire de moi, et je me remonterai un peu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Avant que je m’en aille, pour ne plus revenir, dans le pays de l’obscurité et de l’ombre de la mort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Terre sombre comme les ténèbres de l’ombre de la mort, et où il n’y a que confusion, et où la clarté est comme des ténèbres profondes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, '*Et Tsophar, le Naamathite, répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'La multitude des paroles ne recevrait-elle pas de réponse, et un grand parleur serait-il justifié?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Tes mensonges doivent-ils faire taire les gens? Te moqueras-tu, sans que personne te fasse honte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Car tu as dit: Ma doctrine est pure, et je suis sans tache à tes yeux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Oh! qu’il plût à ✝Dieu de parler et d’ouvrir ses lèvres contre toi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Et de te raconter les secrets de la sagesse, comment ils sont le double de ce qu’on réalise! Et sache que ✝Dieu laisse dans l’oubli [beaucoup] de ton iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Peux-tu, en sondant, découvrir ce qui est en ✝Dieu, ou découvriras-tu parfaitement le Tout-puissant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Ce sont les hauteurs des cieux, – que feras-tu? C’est plus profond que le shéol, qu’en sauras-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Plus longue que la terre est sa mesure, plus large que la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'S’il passe et enferme et fait comparaître, qui donc le détournera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Car il connaît, lui, les hommes vains, et il voit l’iniquité sans que [l’homme] s’en aperçoive;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Et l’homme stupide s’enhardit, quoique l’homme naisse comme le poulain de l’âne sauvage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Si tu prépares ton cœur et que tu étendes tes mains vers lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Si tu éloignes l’iniquité qui est dans ta main, et que tu ne laisses pas l’injustice demeurer dans tes tentes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Alors tu lèveras ta face sans tache, tu seras ferme et tu ne craindras pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Car tu oublieras ta misère, tu t’en souviendras comme des eaux écoulées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, '[Ta] vie se lèvera plus claire que le plein midi; si tu étais couvert de ténèbres, tu seras comme le matin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Et tu auras de la confiance, parce qu’il y aura de l’espoir; tu examineras [tout], et tu dormiras en sûreté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Tu te coucheras, et il n’y aura personne pour te faire peur, et beaucoup rechercheront ta faveur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Mais les yeux des méchants seront consumés, et [tout] refuge périra pour eux, et leur espoir sera d’expirer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, '*Et Job répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Vraiment vous êtes les [seuls] hommes, et avec vous mourra la sagesse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Moi aussi j’ai du sens comme vous, je ne vous suis pas inférieur; et de qui de telles choses ne sont-elles pas [connues]?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Je suis un [homme] qui est la risée de ses amis, criant à ✝Dieu, et à qui il répondra; – le juste parfait est un objet de risée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Celui qui est prêt à broncher de ses pieds est une lampe méprisée pour les pensées de celui qui est à son aise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Les tentes des dévastateurs prospèrent, et la confiance est pour ceux qui provoquent ✶Dieu, pour celui dans la main duquel ✝Dieu a fait venir [l’abondance].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Mais, je te prie, interroge donc les bêtes, et elles t’enseigneront, et les oiseaux des cieux, et ils te l’annonceront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Ou parle à la terre, et elle t’enseignera, et les poissons de la mer te le raconteront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Qui d’entre tous ceux-ci ne sait pas que la main de l’ Éternel a fait cela,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Lui, dans la main duquel est l’âme de tout être vivant et l’esprit de toute chair d’homme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'L’oreille n’éprouve-t-elle pas les discours, comme le palais goûte les aliments?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Chez les vieillards est la sagesse, et dans beaucoup de jours l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Avec lui est la sagesse et la force, à lui sont le conseil et l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Voici, il démolit, et on ne rebâtit pas; il enferme un homme, et on ne lui ouvre pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Voici, il retient les eaux, et elles tarissent; puis il les envoie, et elles bouleversent la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Avec lui est la force et la parfaite connaissance; à lui sont celui qui erre et celui qui fait errer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Il emmène captifs les conseillers, et rend fous les juges;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Il rend impuissant le gouvernement des rois, et lie de chaînes leurs reins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Il emmène captifs les sacrificateurs, et renverse les puissants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Il ôte la parole à ceux dont la parole est sûre, et enlève le discernement aux anciens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Il verse le mépris sur les nobles, et relâche la ceinture des forts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Il révèle du sein des ténèbres les choses profondes, et fait sortir à la lumière l’ombre de la mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Il agrandit les nations, et les détruit; il étend les limites des nations, et les ramène.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Il ôte le sens aux chefs du peuple de la terre, et les fait errer dans un désert où il n’y a pas de chemin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Ils tâtonnent dans les ténèbres où il n’y a point de lumière; il les fait errer comme un homme ivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Voici, tout cela, mon œil l’a vu, mon oreille l’a entendu et l’a compris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Ce que vous connaissez, moi aussi je le connais; je ne vous suis pas inférieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Mais je parlerai au Tout-puissant, et mon plaisir sera de raisonner avec ✶Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Mais pour vous, vous êtes des forgeurs de mensonges, des médecins de néant, vous tous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Oh! si seulement vous demeuriez dans le silence! et ce serait votre sagesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Écoutez donc mon plaidoyer, et prêtez attention aux arguments de mes lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Est-ce pour ✶Dieu que vous direz des choses iniques? Et pour lui, direz-vous ce qui est faux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Ferez-vous acception de sa personne? Plaiderez-vous pour ✶Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Vous est-il agréable qu’il vous sonde? Vous moquerez-vous de lui comme on se moque d’un mortel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Certainement il vous reprendra, si en secret vous faites acception de personnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Sa majesté ne vous troublera-t-elle pas? Et sa frayeur ne tombera-t-elle pas sur vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Vos discours sentencieux sont des proverbes de cendre, vos retranchements sont des défenses de boue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Gardez le silence, laissez-moi, et moi je parlerai, quoi qu’il m’arrive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Pourquoi prendrais-je ma chair entre mes dents, et mettrais-je ma vie dans ma main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Voici, qu’il me tue, j’espérerai en lui; seulement, je défendrai mes voies devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Ce sera même ma délivrance, qu’un impie n’entre pas devant sa face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Écoutez, écoutez mon discours, et que ma déclaration [pénètre] dans vos oreilles!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Voyez, j’exposerai [ma] juste cause: je sais que je serai justifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Qui est celui qui contestera avec moi? Car maintenant, si je me taisais, j’expirerais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Seulement ne fais pas deux choses à mon égard; alors je ne me cacherai pas loin de ta face:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Éloigne ta main de dessus moi, et que ta terreur ne me trouble pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Et appelle, et moi je répondrai, ou bien je parlerai, et toi, réponds-moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Quel est le nombre de mes iniquités et de mes péchés? Fais-moi connaître ma transgression et mon péché!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Pourquoi caches-tu ta face, et me tiens-tu pour ton ennemi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Veux-tu épouvanter une feuille chassée [par le vent], et poursuivre du chaume sec?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Car tu écris des choses amères contre moi, et tu me fais hériter des iniquités de ma jeunesse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Et tu mets mes pieds dans les ceps, et tu observes tous mes sentiers; tu as tracé une ligne autour des plantes de mes pieds;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Et celui [que tu poursuis] dépérit comme une chose pourrie, comme un vêtement que la teigne a rongé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'L’homme né de femme est de peu de jours et rassasié de trouble;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Il sort comme une fleur, et il est fauché; il s’enfuit comme une ombre, et il ne dure pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Pourtant, sur lui tu ouvres tes yeux, et tu me fais venir en jugement avec toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Qui est-ce qui tirera de l’impur un [homme] pur? Pas un!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Si ses jours sont déterminés, si le nombre de ses mois est par-devers toi, si tu lui as posé ses limites, qu’il ne doit pas dépasser,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Détourne de lui ton regard, et il aura du repos, jusqu’à ce que, comme un mercenaire, il achève sa journée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Car il y a de l’espoir pour un arbre: s’il est coupé, il repoussera encore, et ses rejetons ne cesseront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Si sa racine vieillit dans la terre, et si son tronc meurt dans la poussière,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'À l’odeur de l’eau il poussera, et il fera des branches comme un jeune plant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Mais l’homme meurt et gît là; l’homme expire, et où est-il?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Les eaux s’en vont du lac; et la rivière tarit et sèche:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Ainsi l’homme se couche et ne se relève pas: jusqu’à ce qu’il n’y ait plus de cieux, ils ne s’éveillent pas, et ils ne se réveillent pas de leur sommeil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Oh! si tu voulais me cacher dans le shéol, me tenir caché jusqu’à ce que ta colère se détourne, me fixer un temps arrêté, et puis te souvenir de moi, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, '(Si un homme meurt, revivra-t-il?) tous les jours de ma détresse, j’attendrais jusqu’à ce que mon état vienne à changer:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Tu appellerais, et moi je te répondrais; ton désir serait tourné vers l’œuvre de tes mains;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Car maintenant tu comptes mes pas: ne veilles-tu pas sur mon péché?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Ma transgression est scellée dans un sac, et [dans tes pensées] tu ajoutes à mon iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Mais une montagne qui s’éboule est réduite en poussière, et le rocher est transporté de son lieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Les eaux usent les pierres, leur débordement emporte la poussière de la terre: ainsi tu fais périr l’espoir de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Tu le domines pour toujours, et il s’en va; tu changes sa face, et tu le renvoies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Ses fils sont honorés, et il ne le sait pas; ils sont abaissés, et il ne s’en aperçoit pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Sa chair ne souffre que pour lui-même, et son âme ne mène deuil que sur lui-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, '*Et Éliphaz, le Thémanite, répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Le sage répondra-t-il avec une connaissance [qui n’est que] du vent, et gonflera-t-il sa poitrine du vent d’orient,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Contestant en paroles qui ne profitent pas et en discours qui ne servent à rien?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Certes tu détruis la crainte [de Dieu], et tu restreins la méditation devant ✶Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Car ta bouche fait connaître ton iniquité, et tu as choisi le langage des [hommes] rusés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Ta bouche te condamnera, et non pas moi, et tes lèvres déposent contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Es-tu né le premier des hommes, et as-tu été enfanté avant les collines?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'As-tu entendu [ce qui se dit] dans le conseil secret de ✝Dieu, et as-tu accaparé pour toi la sagesse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Que sais-tu que nous ne sachions? que comprends-tu qui ne soit également avec nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Parmi nous il y a aussi des hommes à cheveux blancs et des vieillards plus âgés que ton père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Est-ce trop peu pour toi que les consolations de ✶Dieu et la parole douce qui se fait entendre à toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Comment ton cœur t’emporte-t-il, et comment tes yeux clignent-ils,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Que tu tournes contre ✶Dieu ton esprit et que tu fasses sortir de ta bouche des discours?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Qu’est-ce que l’homme mortel, pour qu’il soit pur, et celui qui est né d’une femme, pour qu’il soit juste?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Voici, il ne se fie pas à ses saints, et les cieux ne sont pas purs à ses yeux:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Combien plus l’homme, qui boit l’iniquité comme l’eau, est-il abominable et corrompu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Je t’enseignerai, écoute-moi; et ce que j’ai vu je te le raconterai,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Ce que les sages ont déclaré d’après leurs pères et n’ont pas caché; –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'À eux seuls la terre fut donnée, et aucun étranger ne passa au milieu d’eux: –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Tous ses jours, le méchant est tourmenté, et peu d’années sont réservées à l’homme violent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'La voix des choses effrayantes est dans ses oreilles; au milieu de la prospérité, le dévastateur arrive sur lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Il ne croit pas revenir des ténèbres, et l’épée l’attend;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Il erre çà et là pour du pain: – où en trouver? Il sait qu’à son côté un jour de ténèbres est préparé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'La détresse et l’angoisse le jettent dans l’alarme, elles l’assaillent comme un roi prêt pour la mêlée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Car il a étendu sa main contre ✶Dieu, et il s’élève contre le Tout-puissant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Il court contre lui, le cou [tendu], sous les bosses épaisses de ses boucliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Car il a couvert sa face de sa graisse, et a rendu gras ses flancs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Et il habitera des villes ruinées, des maisons que personne n’habite, qui vont devenir des monceaux de pierres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Il ne deviendra pas riche, et son bien ne subsistera pas, et ses possessions ne s’étendront pas sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Il ne sortira pas des ténèbres; la flamme séchera ses rejetons, et il s’en ira par le souffle de sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Qu’il ne compte pas sur la vanité: il sera déçu, car la vanité sera sa récompense;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Avant son jour, elle sera complète, et son rameau ne verdira pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Il se défait, comme une vigne, de ses grappes vertes, et, comme un olivier, il rejette ses fleurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Car la famille des impies sera stérile, et le feu dévorera les tentes [où entrent] les présents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Il conçoit la misère et enfante le malheur, et son sein prépare la tromperie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, '*Et Job répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'J’ai entendu bien des choses comme celles-là; vous êtes tous des consolateurs fâcheux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Y aura-t-il une fin à [ces] paroles de vent? Qu’est-ce qui t’irrite, que tu répondes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Moi aussi, je pourrais parler comme vous; si votre âme était à la place de mon âme, je pourrais entasser des paroles contre vous et secouer ma tête contre vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, '[Mais] je vous fortifierais de ma bouche, et la consolation de mes lèvres allégerait [vos douleurs].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Si je parle, ma douleur n’est pas allégée; et si je me tais, s’éloignera-t-elle de moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Mais maintenant, il m’a fatigué...: tu as dévasté toute ma famille;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Tu m’as étreint, c’est un témoignage, et ma maigreur se lève contre moi, elle dépose, à ma face, contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Sa colère me déchire et me poursuit; il grince des dents contre moi; [comme] mon adversaire, il aiguise contre moi ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Ils ouvrent contre moi leur bouche, ils me frappent les joues avec mépris; ils s’attroupent contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, '✶Dieu m’a livré à l’inique, et m’a jeté entre les mains des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'J’étais en paix, et il m’a brisé; il m’a saisi par la nuque et m’a broyé, et m’a dressé pour lui servir de but.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Ses archers m’ont environné; il me perce les reins et ne m’épargne pas; il répand mon fiel sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Il fait brèche en moi, brèche sur brèche; il court sur moi comme un homme fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'J’ai cousu un sac sur ma peau, et j’ai dégradé ma corne dans la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Mon visage est enflammé à force de pleurer, et sur mes paupières est l’ombre de la mort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Quoiqu’il n’y ait pas de violence dans mes mains, et que ma prière soit pure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Ô terre, ne recouvre pas mon sang, et qu’il n’y ait pas de place pour mon cri!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Maintenant aussi, voici, mon témoin est dans les cieux, et celui qui témoigne pour moi est dans les lieux élevés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Mes amis se moquent de moi... vers ✝Dieu pleurent mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Que n’y a-t-il un arbitre pour l’homme auprès de ✝Dieu, et pour un fils d’homme vis-à-vis de son ami!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Car les années s’écoulent dont on peut compter le nombre, et je m’en vais dans le chemin [d’où] je ne reviendrai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Mon souffle est corrompu, mes jours s’éteignent: pour moi sont les sépulcres!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Les moqueurs ne sont-ils pas autour de moi, et mes yeux ne demeurent-ils pas au milieu de leurs insultes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Dépose, je te prie, [un gage]; cautionne-moi auprès de toi-même: qui donc frappera dans ma main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Car tu as fermé leur cœur à l’intelligence; c’est pourquoi tu ne les élèveras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Celui qui trahit ses amis pour qu’ils soient pillés, les yeux de ses fils seront consumés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Et il a fait de moi un proverbe des peuples, et je suis devenu un homme auquel on crache au visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Mon œil est terni par le chagrin, et mes membres sont tous comme une ombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Les hommes droits en seront étonnés, et l’innocent s’élèvera contre l’impie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Mais le juste tiendra ferme dans sa voie, et celui qui a les mains pures croîtra en force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Mais quant à vous tous, revenez encore, je vous prie; mais je ne trouverai pas un sage parmi vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Mes jours sont passés, mes desseins sont frustrés, – les plans chéris de mon cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Ils font de la nuit le jour, la lumière proche en présence des ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Si j’espère, le shéol est ma maison, j’étends mon lit dans les ténèbres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Je crie à la fosse: Tu es mon père! aux vers: Ma mère et ma sœur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Où donc est mon espoir? Et mon espoir, qui le verra?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Il descendra vers les barres du shéol, lorsque ensemble nous aurons du repos dans la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, '*Et Bildad, le Shukhite, répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Jusques à quand tendrez-vous des pièges avec vos paroles? Soyez intelligents, et puis nous parlerons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Pourquoi sommes-nous considérés comme des bêtes, et sommes-nous stupides à vos yeux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Toi qui déchires ton âme dans ta colère, la terre sera-t-elle abandonnée à cause de toi, et le rocher sera-t-il transporté de sa place?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Or la lumière des méchants sera éteinte, et la flamme de son feu ne luira point;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'La lumière sera ténèbres dans sa tente, et sa lampe sera éteinte au-dessus de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Les pas de sa force seront resserrés, et son propre conseil le renversera:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Car il est poussé dans le filet par ses propres pieds; et il marche sur les mailles du filet;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Le piège le prend par le talon, le lacet le saisit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Sa corde est cachée dans la terre, et sa trappe sur le sentier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'De toutes parts des terreurs l’alarment et le poussent çà et là, s’attachant à ses pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Sa force est affaiblie par la faim, et la calamité est prête à son côté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Le premier-né de la mort dévore les membres de son corps, il dévore ses membres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Ce qui faisait sa confiance est arraché de sa tente, et il est forcé de marcher vers le roi des terreurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Ce qui n’est pas à lui habite dans sa tente, le soufre est répandu sur son habitation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'En bas ses racines sèchent, et en haut ses branches sont coupées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Sa mémoire périt de dessus la terre, et il n’a pas de nom sur la face du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Il est repoussé de la lumière dans les ténèbres; on le bannit du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Il n’a pas d’enfants ni de postérité parmi son peuple, personne qui lui survive dans les lieux de son séjour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Ceux qui viennent après seront étonnés de son jour, comme l’horreur s’est emparée de ceux qui [les] ont précédés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Certainement, telles sont les demeures de l’inique, et tel est le lieu de celui qui ne connaît pas ✶Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, '*Et Job répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Jusques à quand affligerez-vous mon âme, et m’accablerez-vous de paroles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Voilà dix fois que vous m’avez outragé, vous n’avez pas honte de m’étourdir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Mais si vraiment j’ai erré, mon erreur demeure avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Si réellement vous voulez vous élever contre moi et faire valoir mon opprobre contre moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Sachez donc que c’est ✝Dieu qui me renverse et qui m’entoure de son filet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Voici, je crie à la violence, et je ne suis pas exaucé; je pousse des cris, et il n’y a pas de jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Il a fermé mon chemin et je ne puis passer, et il a mis des ténèbres sur mes sentiers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Il m’a dépouillé de ma gloire et a ôté la couronne de dessus ma tête;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Il m’a détruit de tous côtés, et je m’en vais; il a arraché mon espérance comme un arbre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Il a allumé contre moi sa colère, et il m’a tenu pour l’un de ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Ses troupes sont venues ensemble, et elles ont dressé en chaussée leur chemin contre moi et se sont campées autour de ma tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Il a éloigné de moi mes frères, et ceux de ma connaissance me sont devenus entièrement étrangers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Mes proches m’ont délaissé, et ceux que je connaissais m’ont oublié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Ceux qui séjournent dans ma maison et mes servantes me tiennent pour un étranger; je suis à leurs yeux comme un homme du dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'J’ai appelé mon serviteur, et il n’a pas répondu; de ma bouche je l’ai supplié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Mon haleine est étrangère à ma femme, et ma supplication, aux fils du sein de ma mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Même les petits enfants me méprisent; je me lève, et ils parlent contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Tous les hommes de mon intimité m’ont en horreur, et ceux que j’aimais se sont tournés contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Mes os s’attachent à ma peau et à ma chair, et j’ai échappé avec la peau de mes dents!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Ayez pitié de moi, ayez pitié de moi, vous mes amis! car la main de ✝Dieu m’a atteint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Pourquoi, comme ✶Dieu, me poursuivez-vous et n’êtes-vous pas rassasiés de ma chair?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Oh! si seulement mes paroles étaient écrites! si seulement elles étaient inscrites dans un livre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Avec un style de fer et du plomb, et gravées dans le roc pour toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Et moi, je sais que mon rédempteur est vivant, et que, le dernier, il sera debout sur la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Et après ma peau, ceci sera détruit, et de ma chair je verrai ✝Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Que je verrai, moi, pour moi-même; et mes yeux [le] verront, et non un autre: – mes reins se consument dans mon sein.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Si vous dites: Comment le poursuivrons-nous? et que la racine de la chose se trouve en moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Tremblez pour vous-mêmes devant l’épée! car l’épée est l’instrument de la fureur contre les iniquités; afin que vous sachiez qu’il y a un jugement!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, '*Et Tsophar, le Naamathite, répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'C’est pourquoi mes pensées m’inspirent une réponse, et à cause de ceci l’ardeur de mon esprit [agit] en moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'J’entends une réprimande qui me couvre de honte, et mon esprit me répond par mon intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Sais-tu bien que, de tout temps, depuis que l’homme a été mis sur la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'L’exultation des méchants est courte, et la joie de l’impie n’est que pour un moment?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Si sa hauteur s’élève jusqu’aux cieux, et que sa tête touche les nuées,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Il périra pour toujours comme ses ordures; ceux qui l’ont vu diront: Où est-il?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Il s’envole comme un songe, et on ne le trouve pas; il s’enfuit comme une vision de la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'L’œil l’a regardé et ne l’aperçoit plus, et son lieu ne le revoit plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Ses fils rechercheront la faveur des pauvres, et ses mains restitueront [ce que] sa violence [a ravi].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Ses os étaient pleins de sa jeunesse: elle se couchera avec lui sur la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Si le mal est doux dans sa bouche, [et] qu’il le cache sous sa langue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'S’il l’épargne et ne l’abandonne pas, mais qu’il le retienne dans sa bouche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Son pain sera changé dans ses entrailles en un fiel d’aspic au-dedans de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Il a avalé les richesses, et il les vomira; ✶Dieu les chassera de son ventre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Il sucera le venin des aspics, la langue de la vipère le tuera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Il ne verra pas des ruisseaux, des rivières, des torrents de miel et de beurre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Il rendra le fruit de son travail, et ne l’avalera pas; il le restituera selon sa valeur, et ne s’en réjouira pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Car il a opprimé, délaissé les pauvres; il a pillé une maison qu’il n’avait pas bâtie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Parce qu’il n’a pas connu de repos dans son désir, il ne sauvera rien de ce qu’il a de plus cher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Rien n’a échappé à sa voracité: c’est pourquoi son bien-être ne durera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Dans la plénitude de son abondance, il sera dans la détresse; toutes les mains des malheureux viendront sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Il arrivera que, pour remplir son ventre, [Dieu] enverra sur lui l’ardeur de sa colère, et la fera pleuvoir sur lui dans sa chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'S’il fuit devant les armes de fer, un arc d’airain le transpercera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Il arrache [la flèche] et elle sort de son corps, et le fer étincelant de son fiel: les terreurs sont sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Toutes les ténèbres sont réservées pour ses trésors; un feu qu’on ne souffle pas le dévorera, [et] se repaîtra de ce qui reste dans sa tente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Les cieux révéleront son iniquité, et la terre s’élèvera contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Le revenu de sa maison sera emporté; il s’écoulera au jour de Sa colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Telle est, de la part de Dieu, la portion de l’homme méchant, et l’héritage qui lui est assigné par ✶Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, '*Et Job répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Écoutez, écoutez mon discours, et cela tiendra lieu de vos consolations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Supportez-moi, et moi je parlerai, et après mes paroles, moque-toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Ma plainte s’adresse-t-elle à un homme? Et pourquoi mon esprit ne serait-il pas à bout de patience?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Tournez-vous vers moi, et soyez étonnés, et mettez la main sur la bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Quand je m’en souviens, je suis terrifié, et le frisson saisit ma chair:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Pourquoi les méchants vivent-ils, deviennent-ils âgés, et croissent-ils même en force?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Leur postérité s’établit devant eux, auprès d’eux, et leurs descendants devant leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Leurs maisons sont en paix, loin de la frayeur, et la verge de ✝Dieu n’est pas sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Leur taureau engendre sans manquer, leur vache vêle et n’avorte pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Ils font sortir leurs jeunes enfants comme un troupeau, et leurs enfants s’ébattent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Ils chantent au son du tambourin et de la harpe, et se réjouissent au son du chalumeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Ils passent leurs jours dans le bonheur, et en un moment descendent dans le shéol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Et ils disent à ✶Dieu: Retire-toi de nous, nous ne prenons pas plaisir à la connaissance de tes voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Qu’est-ce que le Tout-puissant pour que nous le servions, et que nous profitera-t-il de nous adresser à lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Voici, leur bonheur n’est pas dans leur main. Loin de moi le conseil des méchants!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Combien de fois la lampe des méchants s’éteint-elle, et leur calamité vient-elle sur eux, [et] leur distribue-t-Il des douleurs dans sa colère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, '[Et] sont-ils comme la paille devant le vent, et comme la balle chassée par la tempête?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, '✝Dieu réserve à ses fils [la punition de] sa méchanceté: il la lui rend, et il le saura;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Ses yeux verront sa calamité, et il boira de la fureur du Tout-puissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Car quel plaisir [a-t-il] à sa maison après lui, quand le nombre de ses mois est tranché?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Est-ce à ✶Dieu qu’on enseignera la connaissance, quand c’est lui qui juge ceux qui sont haut élevés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'L’un meurt en pleine vigueur, entièrement tranquille et à l’aise;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Ses flancs sont garnis de graisse, et la moelle de ses os est abreuvée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Et l’autre meurt dans l’amertume de son âme et n’a jamais goûté le bonheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Ils gisent ensemble sur la poussière, et les vers les couvrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Voici, je connais vos pensées, et vos plans contre moi pour me faire violence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Car vous dites: Où est la maison du noble, et où la tente des demeures des méchants?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Ne l’avez-vous pas demandé à ceux qui passent par le chemin? Et n’avez-vous pas reconnu ce qui les distingue:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Que le méchant est épargné pour le jour de la calamité, qu’ils sont emmenés au jour de la fureur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Qui lui dira en face sa voie? et ce qu’il a fait, qui le lui rendra?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Il sera conduit dans un sépulcre, et sur le tertre il veillera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Les mottes de la vallée lui sont douces; et après lui tout homme suit à la file, et ceux qui l’ont précédé sont sans nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Et comment me consolez-vous avec de vaines [consolations]? Vos réponses restent perfides.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, '*Et Éliphaz, le Thémanite, répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'L’homme peut-il être de quelque profit à ✶Dieu? C’est bien à lui-même que l’homme intelligent profitera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Est-ce un plaisir pour le Tout-puissant que tu sois juste, et un gain [pour lui] que tu sois parfait dans tes voies?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Contestera-t-il avec toi parce qu’il te craint, [et] ira-t-il avec toi en jugement?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Ta méchanceté n’est-elle pas grande, et tes iniquités ne sont-elles pas sans fin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Car sans cause tu as pris un gage de ton frère, et tu as dépouillé de leurs vêtements ceux qui étaient nus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Tu n’as pas donné d’eau à boire à celui qui défaillait de soif, et tu as refusé du pain à celui qui avait faim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Et l’homme fort,... à lui était la terre, et celui qui était considéré y habitait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Tu as renvoyé les veuves à vide, et les bras des orphelins ont été écrasés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'C’est pourquoi il y a des pièges autour de toi, et une terreur subite t’effraie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Ou bien, ce sont des ténèbres, de sorte que tu ne vois pas, et le débordement des eaux te couvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, '✝Dieu n’est-il pas aussi haut que les cieux? Regarde le faîte des étoiles, combien elles sont élevées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Et tu as dit: Qu’est-ce que ✶Dieu sait? Jugera-t-il à travers l’obscurité des nuées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Les nuages l’enveloppent, et il ne voit pas; il se promène dans la voûte des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Observes-tu le sentier ancien où ont marché les hommes vains,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Qui ont été emportés avant le temps, [et] dont les fondements se sont écoulés comme un fleuve;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Qui disaient à ✶Dieu: Retire-toi de nous! Et que nous ferait le Tout-puissant? –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Quoiqu’il ait rempli de biens leurs maisons. Mais que le conseil des méchants soit loin de moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Les justes le verront et se réjouiront, et l’innocent se moquera d’eux:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Celui qui s’élevait contre nous n’a-t-il pas été retranché, et le feu n’a-t-il pas dévoré leur abondance?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Réconcilie-toi avec Lui, je te prie, et sois en paix: ainsi le bonheur t’arrivera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Reçois l’instruction de sa bouche, et mets ses paroles dans ton cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Si tu retournes vers le Tout-puissant, tu seras rétabli. Si tu éloignes l’iniquité de ta tente,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Et que tu mettes l’or avec la poussière, et [l’or d’]Ophir parmi les cailloux des torrents,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Le Tout-puissant sera ton or, et il sera pour toi de l’argent amassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Car alors tu trouveras tes délices dans le Tout-puissant, et vers ✝Dieu tu élèveras ta face;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Tu le supplieras et il t’entendra, et tu acquitteras tes vœux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Tu décideras une chose, et elle te réussira, et la lumière resplendira sur tes voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Quand elles seront abaissées, alors tu diras: Lève-toi! et celui qui a les yeux baissés, Il le sauvera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Même Il délivrera celui qui n’est pas innocent: il sera délivré par la pureté de tes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, '*Et Job répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Encore aujourd’hui ma plainte est amère, la main qui s’appesantit sur moi est plus pesante que mon gémissement!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Oh! si je savais le trouver, et parvenir là où il est assis!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'J’exposerais [ma] juste cause devant lui, et je remplirais ma bouche d’arguments;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Je saurais les paroles qu’il me répondrait, et je comprendrais ce qu’il me dirait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Contesterait-il avec moi dans la grandeur de sa force? Non, mais il ferait attention à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Là, un homme droit raisonnerait avec lui, et je serais délivré pour toujours de mon juge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Voici, je vais en avant, mais il n’y est pas; et en arrière, mais je ne l’aperçois pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'À gauche, quand il y opère, mais je ne le discerne pas; il se cache à droite, et je ne le vois pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Mais il connaît la voie que je suis; il m’éprouve, je sortirai comme de l’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Mon pied s’attache à ses pas; j’ai gardé sa voie, et je n’en ai point dévié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Je ne me suis pas retiré du commandement de ses lèvres; j’ai serré [par-devers moi] les paroles de sa bouche plus que le propos de mon propre cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Mais lui, il a une [pensée], et qui l’en fera revenir? Ce que son âme désire, il le fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Car il achèvera ce qui est déterminé pour moi; et bien des choses semblables sont auprès de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'C’est pourquoi je suis terrifié devant sa face; je considère, et je suis effrayé devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Et ✶Dieu a fait défaillir mon cœur, et le Tout-puissant m’a frappé de terreur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Parce que je n’ai pas été anéanti devant les ténèbres, et qu’il ne m’a pas caché l’obscurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Pourquoi des temps ne sont-ils pas réservés par-devers le Tout-puissant, et ceux qui le connaissent ne voient-ils pas ses jours?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Ils reculent les bornes, ils pillent le troupeau et le paissent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Ils emmènent l’âne des orphelins et prennent en gage le bœuf de la veuve;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Ils détournent du chemin les pauvres; les malheureux de la terre se cachent ensemble:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Voici, ânes sauvages dans le désert, ils sortent pour leur besogne dès le matin, pour chercher leur proie; le désert leur [fournit] le pain pour leurs enfants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Ils moissonnent le fourrage dans les champs, ils grappillent la vigne du méchant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Ils passent la nuit tout nus, sans vêtement, et n’ont pas de couverture par le froid;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Ils sont trempés par les averses des montagnes, et, sans refuge, ils se serrent contre le rocher...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Ils arrachent de la mamelle l’orphelin, et [de la main] des pauvres ils prennent des gages:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Ceux-ci vont nus, sans vêtement, et, affamés, ils portent la gerbe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Entre leurs murailles ils font de l’huile, ils foulent le pressoir, et ont soif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Des villes sortent les soupirs des mourants, et l’âme des blessés à mort crie, et ✝Dieu n’impute pas l’indignité [qui se commet].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'D’autres sont ennemis de la lumière, ils ne connaissent pas ses voies et ne demeurent pas dans ses sentiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Le meurtrier se lève avec la lumière, il tue le malheureux et le pauvre, et la nuit il est comme le voleur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'L’œil aussi de l’adultère guette le crépuscule, en disant: Aucun œil ne m’apercevra; et il met un voile sur son visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Dans les ténèbres ils percent les maisons, de jour ils s’enferment; ils ne connaissent pas la lumière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Car le matin est pour eux tous l’ombre de la mort, car ils connaissent les terreurs de l’ombre de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Ils sont rapides sur la face des eaux, leur part est maudite sur la terre; ils ne se tournent pas vers les vignes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'La sécheresse et la chaleur emportent l’eau de neige; ainsi le shéol fait-il de ceux qui ont péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Le sein maternel les oublie; les vers se repaissent d’eux; on ne se souvient plus d’eux: l’iniquité sera brisée comme du bois!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Ils dépouillent la femme stérile qui n’enfante pas, et ils ne font pas de bien à la veuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Et par leur force ils traînent les puissants; ils se lèvent et on n’est plus sûr de sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, '[Dieu] leur donne la sécurité, et ils s’appuient sur elle; mais il a ses yeux sur leurs voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Ils sont élevés: dans peu, ils ne sont plus; ils défaillent, et sont recueillis comme tous; ils sont coupés comme la tête d’un épi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Et si cela n’est pas, qui me fera menteur et réduira mon discours à néant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, '*Et Bildad, le Shukhite, répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'La domination et la terreur sont avec lui; il fait la paix dans ses hauts lieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Peut-on dénombrer ses troupes? et sur qui sa lumière ne se lève-t-elle pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Et comment l’homme sera-t-il juste devant ✶Dieu, et comment serait pur celui qui est né de femme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Voici, la lune même ne brille pas, et les étoiles ne sont pas pures à ses yeux:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Combien moins l’homme, un ver, et le fils de l’homme, un vermisseau!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, '*Et Job répondit et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Comme tu as aidé celui qui n’avait pas de puissance! Comme tu as délivré le bras qui était sans force!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Quel conseil tu as donné à celui qui n’avait pas de sagesse! et quelle abondance d’intelligence tu as montrée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Pour qui as-tu prononcé des paroles, et de qui est le souffle qui est sorti de toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Les trépassés tremblent au-dessous des eaux et de ceux qui les habitent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Le shéol est à nu devant lui, et l’abîme n’a pas de voile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Il étend le nord sur le vide, il suspend la terre sur le néant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Il serre les eaux dans ses nuages, et la nuée ne se fend pas sous elles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Il couvre la face de son trône et étend ses nuées par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Il a tracé un cercle fixe sur la face des eaux, jusqu’à la limite extrême où la lumière confine aux ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Les colonnes des cieux branlent et s’étonnent à sa menace.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Il soulève la mer par sa puissance, et, par son intelligence, il brise Rahab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Par son Esprit le ciel est beau; sa main a formé le serpent fuyard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Voici, ces choses sont les bords de ses voies, et combien faible est le murmure que nous en avons entendu! Et le tonnerre de sa force, qui peut le comprendre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Et Job reprit son discours sentencieux et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, '✶Dieu qui a écarté mon droit, le Tout-puissant qui met l’amertume dans mon âme, est vivant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Tant que mon souffle est en moi et l’esprit de ✝Dieu dans mes narines,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Mes lèvres ne diront pas d’iniquité, et ma langue ne prononcera pas de fausseté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Loin de moi que je vous justifie! Jusqu’à ce que j’expire, je ne lâcherai pas ma perfection;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Je tiendrai ferme ma justice et je n’en ferai pas abandon; mon cœur ne me reproche aucun de mes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Que mon ennemi soit comme le méchant, et celui qui s’élève contre moi comme l’inique!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Car quelle est l’espérance de l’impie quand [Dieu le] retranche, quand ✝Dieu retire son âme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, '✶Dieu entendra-t-il son cri quand la détresse viendra sur lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Trouvera-t-il ses délices dans le Tout-puissant? Invoquera-t-il ✝Dieu en tout temps?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Je vous enseignerai comment ✶Dieu agit, je ne cacherai pas ce qui est par-devers le Tout-puissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Voici, vous-mêmes, vous l’avez tous vu: et pourquoi entretenez-vous ces vaines pensées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Voici quelle est, par-devers ✶Dieu, la part de l’homme méchant et l’héritage que les violents reçoivent du Tout-puissant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Si ses fils se multiplient, c’est pour l’épée, et ses descendants ne sont pas rassasiés de pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Ceux qui restent après lui seront enterrés dans la mort, et ses veuves ne pleureront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'S’il entasse l’argent comme la poussière et se prépare des vêtements comme de la boue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Il se les prépare, mais le juste s’en vêtira; et l’argent, c’est l’innocent qui se le partagera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Il a bâti sa maison comme la teigne, comme une cabane que fait celui qui garde [les vignes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Il se couche riche, et il ne le refera pas; il ouvre ses yeux, et il n’est plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Les frayeurs le surprennent comme des eaux; l’ouragan l’emporte de nuit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Le vent d’orient l’enlève, et il s’en va, et dans un tourbillon il l’emporte de son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, '[Dieu] lance [ses dards] sur lui et ne l’épargne pas; il voudrait fuir loin de sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'On battra des mains sur lui, et on le chassera de son lieu avec des sifflements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Oui, il y a pour l’argent [un endroit] d’où on le tire, et un lieu pour l’or qu’on affine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Le fer se tire de la poussière, et la pierre fondue donne le cuivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, '[L’homme] met fin aux ténèbres et explore jusqu’à l’extrémité de tout, la pierre d’obscurité et de l’ombre de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'On creuse un puits loin de ceux qui séjournent [sur la terre]; oubliés du pied [de l’homme], ils sont suspendus, balancés loin des humains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'La terre,... d’elle sort le pain; et au-dessous, elle est bouleversée comme par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Ses pierres sont le lieu du saphir, et la poussière d’or s’y trouve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'C’est un sentier que l’oiseau de proie ne connaît pas, et que l’œil du vautour n’a pas aperçu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'La bête fauve ne l’a pas foulé, le lion ne l’a pas traversé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, '[L’homme] porte sa main sur le roc dur, il renverse les montagnes depuis la racine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Il creuse des canaux dans les rochers; et son œil voit tout ce qui est précieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Il enserre les fleuves pour qu’ils ne suintent pas; et il produit à la lumière les choses cachées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Mais la sagesse, où la trouvera-t-on? et où est le lieu de l’intelligence?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Aucun mortel n’en connaît le prix, et elle ne se trouve pas sur la terre des vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'L’abîme dit: Elle n’est pas en moi; et la mer dit: Elle n’est pas chez moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Elle ne s’échange pas contre de l’or pur, et l’argent ne se pèse pas pour l’acheter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'On ne la met pas dans la balance avec l’or d’Ophir, avec l’onyx précieux et le saphir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'On ne peut lui comparer ni l’or ni le verre, ni l’échanger contre un vase d’or fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, '[À côté d’elle] le corail et le cristal ne viennent pas dans la mémoire; et la possession de la sagesse vaut mieux que les perles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'La topaze d’Éthiopie ne lui est pas comparée, on ne la met pas dans la balance avec l’or pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Mais la sagesse, d’où vient-elle? et où est le lieu de l’intelligence?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Elle est voilée aux yeux de tous les vivants, et elle est cachée aux oiseaux des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'La destruction et la mort disent: De nos oreilles nous en avons entendu la rumeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Dieu comprend son chemin, et lui, il connaît son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Car lui, voit jusqu’aux bouts de la terre: sa vue s’étend sous tous les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Quand il fixait au vent sa pesanteur, et qu’il établissait les eaux selon leur mesure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Quand il faisait une loi pour la pluie, et un chemin pour le sillon de la foudre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Alors il la vit et la manifesta; il l’établit, et il la sonda aussi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Et il dit à l’homme: Voici, la crainte du Seigneur, c’est là la sagesse, et se retirer du mal est l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Et Job reprit son discours sentencieux et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Oh! que ne suis-je comme aux mois d’autrefois, comme aux jours où ✝Dieu me gardait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Quand sa clarté luisait sur ma tête, et que dans les ténèbres je marchais à sa lumière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Comme j’étais aux jours de mon automne, quand le conseil secret de ✝Dieu présidait sur ma tente;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Quand le Tout-puissant était encore avec moi, [et] que mes jeunes gens m’entouraient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Quand je lavais mes pas dans le caillé, et que le rocher versait auprès de moi des ruisseaux d’huile! –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Quand je sortais [pour aller] à la porte par la ville, quand je préparais mon siège sur la place:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Les jeunes gens me voyaient et se cachaient, et les vieillards se levaient [et] se tenaient debout;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Les princes s’abstenaient de parler et mettaient la main sur leur bouche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'La voix des nobles s’éteignait, et leur langue se collait à leur palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Quand l’oreille m’entendait, elle m’appelait bienheureux; quand l’œil me voyait, il me rendait témoignage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Car je délivrais le malheureux qui implorait du secours, et l’orphelin qui était sans aide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'La bénédiction de celui qui périssait venait sur moi, et je faisais chanter de joie le cœur de la veuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Je me vêtais de la justice, et elle me revêtait; ma droiture m’était comme un manteau et un turban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'J’étais, moi, les yeux de l’aveugle et les pieds du boiteux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'J’étais un père pour les pauvres, et j’examinais la cause de celui qui m’était inconnu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Et je brisais la mâchoire de l’inique, et d’entre ses dents j’arrachais la proie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Et je disais: J’expirerai dans mon nid, et mes jours seront nombreux comme le sable;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Ma racine sera ouverte aux eaux, et la rosée séjournera sur ma branche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Ma gloire [restera] toujours nouvelle avec moi, et mon arc rajeunira dans ma main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'On m’écoutait et on attendait, et on se taisait pour [avoir] mon conseil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Après que j’avais parlé on ne répliquait pas, et mon discours distillait sur eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Et on m’attendait comme la pluie, et on ouvrait la bouche [comme] pour la pluie de la dernière saison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Si je leur souriais, ils ne le croyaient pas, et ils ne troublaient pas la sérénité de ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Je choisissais pour eux le chemin et je m’asseyais à leur tête, et je demeurais comme un roi au milieu d’une troupe, comme quelqu’un qui console les affligés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Et maintenant, ceux qui sont plus jeunes que moi se moquent de moi, ceux dont j’aurais dédaigné de mettre les pères avec les chiens de mon troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Même à quoi m’aurait servi la force de leurs mains? La vigueur a péri pour eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Desséchés par la disette et la faim, ils s’enfuient dans les lieux arides, dès longtemps désolés et déserts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Ils cueillent le pourpier de mer parmi les broussailles, et, pour leur pain, la racine des genêts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Ils sont chassés du milieu [des hommes], (on crie après eux comme après un voleur,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Pour demeurer dans des gorges affreuses, dans les trous de la terre et des rochers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Ils hurlent parmi les broussailles, ils se rassemblent sous les ronces:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Fils d’insensés, et fils de gens sans nom, ils sont chassés du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Et maintenant, je suis leur chanson et je suis le sujet de leur entretien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Ils m’ont en horreur, ils se tiennent loin de moi, et n’épargnent pas à ma face les crachats;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Car Il a délié ma corde et m’a affligé: ils ont jeté loin [tout] frein devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Cette jeune engeance se lève à ma droite; ils poussent mes pieds et préparent contre moi leur chemin pernicieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Ils détruisent mon sentier, ils contribuent à ma calamité, sans que personne leur vienne en aide;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Ils viennent comme par une large brèche, ils se précipitent au milieu du fracas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Des terreurs m’assaillent, elles poursuivent ma gloire comme le vent, et mon état de sûreté est passé comme une nuée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Et maintenant, mon âme se répand en moi: les jours d’affliction m’ont saisi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'La nuit perce mes os [et les détache] de dessus moi, et ceux qui me rongent ne dorment pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Par leur grande force ils deviennent mon vêtement; ils me serrent comme le collet de ma tunique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Il m’a jeté dans la boue, et je suis devenu comme la poussière et la cendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Je crie à toi, et tu ne me réponds pas; je me tiens là, et tu me regardes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Tu t’es changé pour moi en [ennemi] cruel; tu me poursuis avec la force de ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Tu m’enlèves sur le vent, tu fais qu’il m’emporte, et tu dissous ma substance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Car je sais que tu m’amènes à la mort, la maison de rassemblement de tous les vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Toutefois, dans sa ruine, n’étend-il pas la main, et, dans sa calamité, ne jette-t-il pas un cri [de détresse]?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'N’ai-je pas pleuré sur celui pour qui les temps étaient durs, et mon âme n’a-t-elle pas été attristée pour le pauvre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Car j’attendais le bien, et le mal est arrivé; je comptais sur la lumière, et l’obscurité est venue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Mes entrailles bouillonnent et ne cessent pas; les jours d’affliction sont venus sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Je marche tout noirci, mais non par le soleil; je me lève dans l’assemblée, je crie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Je suis devenu le frère des chacals et le compagnon des autruches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Ma peau devient noire [et se détache] de dessus moi, et mes os sont brûlés par la sécheresse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Et ma harpe est changée en deuil, et mon chalumeau est devenu la voix des pleureurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'J’ai fait alliance avec mes yeux: et comment aurais-je arrêté mes regards sur une vierge?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Et quelle aurait été d’en haut [ma] portion de la part de ✝Dieu, et, des hauts lieux, [mon] héritage de la part du Tout-puissant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'La calamité n’est-elle pas pour l’inique, et le malheur pour ceux qui pratiquent le mal?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Lui, ne voit-il pas mon chemin, et ne compte-t-il point tous mes pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Si j’ai marché avec fausseté, si mes pieds se sont hâtés vers la fraude,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Qu’il me pèse dans la balance de justice, et ✝Dieu reconnaîtra ma perfection.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Si mon pas s’est détourné du chemin, et si mon cœur a suivi mes yeux, et si quelque souillure s’est attachée à ma main,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Que je sème et qu’un autre mange, et que mes rejetons soient déracinés!...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Si mon cœur s’est laissé attirer vers une femme et que j’aie fait le guet à la porte de mon prochain,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Que ma femme tourne la meule pour un autre, et que d’autres se penchent sur elle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Car c’est là une infamie, et une iniquité punissable par les juges:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Car c’est un feu qui dévore jusque dans l’abîme et qui détruirait par la racine tout mon revenu...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Si j’ai méprisé le droit de mon serviteur ou de ma servante quand ils contestaient avec moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Que ferais-je quand ✶Dieu se lèverait? et s’il me visitait, que lui répondrais-je?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Celui qui m’a fait dans le sein de ma mère, ne les a-t-il pas faits [eux aussi], et un seul et même [Dieu] ne nous a-t-il pas formés dans la matrice?...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Si j’ai refusé aux misérables leur désir, si j’ai fait défaillir les yeux de la veuve;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Si j’ai mangé seul mon morceau, et que l’orphelin n’en ait pas mangé; –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Car dès ma jeunesse il m’a honoré comme un père, et dès le ventre de ma mère j’ai soutenu la [veuve];...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Si j’ai vu quelqu’un périr faute de vêtement, et le pauvre manquer de couverture;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Si ses reins ne m’ont pas béni, et qu’il ne se soit pas réchauffé avec la toison de mes agneaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Si j’ai secoué ma main contre un orphelin, parce que je voyais mon appui dans la porte:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Que mon épaule se démette de sa jointure, et que mon bras cassé se détache de l’os!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Car la calamité de la part de ✶Dieu m’était une frayeur, et devant sa grandeur je ne pouvais rien...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Si j’ai mis ma confiance dans l’or, si j’ai dit à l’or fin: C’est à toi que je me fie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Si je me suis réjoui de ce que mes biens étaient grands, et de ce que ma main avait beaucoup acquis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Si j’ai vu le soleil quand il brillait, et la lune quand elle marchait dans sa splendeur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'Et que mon cœur ait été séduit en secret, et que ma bouche ait embrassé ma main, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Cela aussi serait une iniquité punissable par le juge, car j’aurais renié le ✶Dieu qui est en haut;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Si je me suis réjoui dans la calamité de celui qui me haïssait, si j’ai été ému de joie lorsque le malheur l’a trouvé; –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Même je n’ai pas permis à ma bouche de pécher, de demander sa vie par une exécration;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Si les gens de ma tente n’ont pas dit: Qui trouvera quelqu’un qui n’ait pas été rassasié de la chair de ses bêtes? –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'L’étranger ne passait pas la nuit dehors, j’ouvrais ma porte sur le chemin;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Si j’ai couvert ma transgression comme Adam, en cachant mon iniquité dans mon sein,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Parce que je craignais la grande multitude, et que le mépris des familles me faisait peur, et que je sois resté dans le silence et ne sois pas sorti de ma porte...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Oh! si j’avais quelqu’un pour m’écouter! Voici ma signature. Que le Tout-puissant me réponde, et que ma partie adverse fasse un écrit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Ne le porterais-je pas sur mon épaule? Ne le lierais-je pas sur moi comme une couronne?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Je lui déclarerais le nombre de mes pas; comme un prince je m’approcherais de lui...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Si ma terre crie contre moi, et que ses sillons pleurent ensemble,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Si j’en ai mangé le revenu sans argent, et que j’aie tourmenté à mort l’âme de ses possesseurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Que les épines croissent au lieu de froment, et l’ivraie au lieu d’orge! Les paroles de Job sont finies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, '***Et ces trois hommes cessèrent de répondre à Job, parce qu’il était juste à ses propres yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Alors s’enflamma la colère d’Élihu, fils de Barakeël, le Buzite, de la famille de Ram: sa colère s’enflamma contre Job, parce qu’il se justifiait lui-même plutôt que Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'et sa colère s’enflamma contre ses trois amis, parce qu’ils ne trouvaient pas de réponse et qu’ils condamnaient Job.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Et Élihu avait attendu que Job ait cessé de parler, parce qu’ils étaient plus avancés en jours que lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Et Élihu vit qu’il n’y avait point de réponse dans la bouche des trois hommes, et sa colère s’enflamma.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Et Élihu, fils de Barakeël, le Buzite, répondit et dit: Moi, je suis jeune, et vous êtes des vieillards; c’est pourquoi je redoutais et je craignais de vous faire connaître ce que je sais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Je disais: Les jours parleront, et le grand nombre des années donnera à connaître la sagesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Toutefois il y a un esprit qui est dans les hommes, et le souffle du Tout-puissant leur donne de l’intelligence:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Ce ne sont pas les grands qui sont sages, ni les anciens qui discernent ce qui est juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'C’est pourquoi je dis: Écoute-moi; moi aussi je ferai connaître ce que je sais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Voici, j’ai attendu vos paroles, j’ai écouté vos raisonnements, jusqu’à ce que vous ayez examiné le sujet;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Je vous ai donné toute mon attention: et voici, il n’y a eu personne d’entre vous qui convainque Job, qui réponde à ses paroles, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Afin que vous ne disiez pas: Nous avons trouvé la sagesse. ✶Dieu le fera céder, et non pas l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Or il ne m’a pas adressé de discours, et je ne lui répondrai pas avec vos paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Ils ont été confondus, ils ne répondent plus; les paroles leur sont ôtées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'J’ai attendu, car ils ne parlaient plus, car ils se tenaient là, ils ne répondaient plus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Je répondrai, moi aussi, à mon tour; je ferai connaître, moi aussi, ce que je sais;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Car je suis plein de paroles, l’esprit qui est au-dedans de moi me presse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Voici, mon ventre est comme un vin qui n’a pas été ouvert; il éclate comme des outres neuves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Je parlerai et je respirerai; j’ouvrirai mes lèvres et je répondrai;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Je ne ferai pas acception de personnes, et je ne flatterai aucun homme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Car je ne sais pas flatter: celui qui m’a fait m’emporterait bientôt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Mais toutefois, Job, je te prie, écoute ce que je dis, et prête l’oreille à toutes mes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Voici, j’ai ouvert ma bouche, ma langue parle dans mon palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Mes paroles seront selon la droiture de mon cœur, et ce que je sais mes lèvres le diront avec pureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'L’Esprit de ✶Dieu m’a fait, et le souffle du Tout-puissant m’a donné la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Si tu le peux, réponds-moi; arrange [des paroles] devant moi, tiens-toi là!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Voici, je suis comme toi quant à ✶Dieu, je suis fait d’argile, moi aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Voici, ma terreur ne te troublera pas, et mon poids ne t’accablera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Certainement tu as dit à mes propres oreilles, et j’ai entendu le son de [tes] discours:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Moi, je suis net, sans transgression; je suis pur, et il n’y a pas d’iniquité en moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Voici, il trouve des occasions d’inimitié contre moi, il me considère comme son ennemi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Il a mis mes pieds dans les ceps, il observe toutes mes voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Voici, je te répondrai qu’en cela tu n’as pas été juste, car ✝Dieu est plus grand que l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Pourquoi contestes-tu avec lui? car d’aucune de ses actions il ne rend compte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Car ✶Dieu parle une fois, et deux fois – [et] l’on n’y prend pas garde –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Dans un songe, dans une vision de nuit, quand un profond sommeil tombe sur les hommes, quand ils dorment sur leurs lits:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Alors il ouvre l’oreille aux hommes et scelle l’instruction qu’il leur donne,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Pour détourner l’homme de ce qu’il fait; et il cache l’orgueil à l’homme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Il préserve son âme de la fosse, et sa vie de se jeter sur l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Il est châtié aussi sur son lit par la douleur, et la lutte de ses os est continuelle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Et sa vie prend en dégoût le pain, et son âme l’aliment qu’il aimait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Sa chair est consumée et ne se voit plus, et ses os, qu’on ne voyait pas, sont mis à nu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Et son âme s’approche de la fosse, et sa vie, de ceux qui font mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'S’il y a pour lui un messager, un interprète, un entre mille, pour montrer à l’homme ce qui, pour lui, est la droiture,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Il lui fera grâce, et il dira: Délivre-le pour qu’il ne descende pas dans la fosse: j’ai trouvé une propitiation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, '[Alors] sa chair aura plus de fraîcheur que dans l’enfance; il reviendra aux jours de sa jeunesse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Il suppliera ✝Dieu, et [Dieu] l’aura pour agréable; et il verra sa face avec des chants de triomphe, et [Dieu] rendra à l’homme sa justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Il chantera devant les hommes, et dira: J’ai péché et j’ai perverti la droiture, et il ne me l’a pas rendu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Il a délivré mon âme pour qu’elle n’aille pas dans la fosse, et ma vie verra la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Voilà, ✶Dieu opère toutes ces choses deux fois, trois fois, avec l’homme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Pour détourner son âme de la fosse, pour qu’il soit illuminé de la lumière des vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Sois attentif, Job, écoute-moi; tais-toi, et moi je parlerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'S’il y a quelque chose à dire, réponds-moi; parle, car je désire que tu sois trouvé juste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Sinon, écoute-moi; tais-toi, et je t’enseignerai la sagesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Et Élihu reprit la parole et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Sages, écoutez mes paroles, et vous qui avez de la connaissance, prêtez-moi l’oreille;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Car l’oreille éprouve les discours, comme le palais goûte les aliments.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Choisissons pour nous ce qui est juste, et reconnaissons entre nous ce qui est bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Car Job a dit: Je suis juste, et ✶Dieu a écarté mon droit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Mentirai-je contre ma droiture? ma blessure est incurable, sans qu’il y ait de transgression.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Qui est l’homme qui soit comme Job? Il boit la moquerie comme l’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'Il marche dans la compagnie des ouvriers d’iniquité, et il chemine avec les hommes méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Car il a dit: Il ne profite de rien à l’homme de trouver son plaisir en Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'C’est pourquoi, hommes de sens, écoutez-moi: Loin de ✶Dieu la méchanceté, et loin du Tout-puissant l’iniquité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Car il rendra à l’homme ce qu’il aura fait, et il fera trouver à chacun selon sa voie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Certainement ✶Dieu n’agit pas injustement, et le Tout-puissant ne pervertit pas le droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Qui a confié la terre à ses soins, et qui a placé le monde entier [sous lui]?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'S’il ne pensait qu’à lui-même et retirait à lui son esprit et son souffle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Toute chair expirerait ensemble et l’homme retournerait à la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Si [tu as] de l’intelligence, écoute ceci; prête l’oreille à la voix de mes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Celui qui hait la justice gouvernera-t-il donc? Et condamneras-tu le juste par excellence?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Dira-t-on Bélial, au roi? – Méchants, aux nobles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, '[Combien moins] à celui qui ne fait pas acception de la personne des princes, et qui n’a pas égard au riche plutôt qu’au pauvre; car ils sont tous l’œuvre de ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Ils mourront en un moment; au milieu de la nuit les peuples chancellent et s’en vont, et les puissants sont retirés sans main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Car ses yeux sont sur les voies de l’homme, et il voit tous ses pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Il n’y a pas de ténèbres, il n’y a pas d’ombre de la mort, où puissent se cacher les ouvriers d’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Car il ne pense pas longtemps à un homme pour le faire venir devant ✶Dieu en jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Il brise les puissants, sans examen, et il fait que d’autres se tiennent à leur place;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'En effet il connaît leurs œuvres: il les renverse de nuit, et ils sont écrasés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Il les frappe comme des méchants dans le lieu où ils sont en vue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Parce qu’ils se sont retirés de lui, et qu’ils n’ont pas considéré toutes ses voies,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Pour faire monter vers lui le cri du pauvre, en sorte qu’il entende le cri des malheureux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Quand il donne la tranquillité, qui troublera? Il cache sa face, et qui le verra? [Il fait] ainsi, soit à une nation, soit à un homme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Pour empêcher l’homme impie de régner, pour écarter du peuple les pièges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Car a-t-il [jamais] dit à ✶Dieu: Je porte ma peine, je ne ferai plus de mal;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Ce que je ne vois pas, montre-le-moi; si j’ai commis l’iniquité, je ne le referai pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Rétribuera-t-il selon tes pensées? car tu as rejeté [son jugement], car toi, tu as choisi, et non pas moi; ce que tu sais, dis-le donc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Les hommes de sens me diront, et un homme sage qui m’écoute:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Job n’a pas parlé avec connaissance, et ses paroles ne sont pas intelligentes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Je voudrais que Job soit éprouvé jusqu’au bout, parce qu’il a répondu à la manière des hommes iniques;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Car il a ajouté à son péché la transgression; il bat des mains parmi nous, et multiplie ses paroles contre ✶Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Et Élihu reprit la parole et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Penses-tu que ceci soit fondé, que tu aies dit: Je suis plus juste que ✶Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Car tu as demandé quel profit tu en as: Quel avantage en ai-je de plus que si j’avais péché?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Je te répliquerai, moi, par des paroles, et à tes amis avec toi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Regarde les cieux et vois, et contemple les nuées: elles sont plus hautes que toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Si tu pèches, quel tort lui causes-tu? et si tes transgressions se multiplient, que lui as-tu fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Si tu es juste, que lui donnes-tu, ou que reçoit-il de ta main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Pour un homme comme toi ta méchanceté [peut être quelque chose], et pour un fils d’homme, ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'On crie à cause de la multitude des oppressions, et on appelle au secours à cause du bras des grands;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Et on ne dit pas: Où est ✝Dieu, mon créateur, qui donne des chants de joie dans la nuit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Qui nous rend plus instruits que les bêtes de la terre, et plus sages que les oiseaux des cieux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Alors on crie, et il ne répond pas, à cause de l’orgueil des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Certainement ce qui est vanité ✶Dieu ne l’écoute pas, et le Tout-puissant ne le regarde pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Quoique tu dises que tu ne le vois pas, le jugement est devant lui; attends-le donc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Et maintenant, si sa colère n’a pas encore visité, [Job] ne connaît-il pas [sa] grande arrogance?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Et Job ouvre sa bouche vainement; il entasse des paroles sans science.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Et Élihu continua et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Attends-moi un peu, et je te montrerai que j’ai encore des paroles pour ✝Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'J’apporterai de loin ce que je sais, et je donnerai justice à mon créateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Car certainement mes discours ne sont pas des mensonges; celui qui est parfait en connaissances est avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Voici, ✶Dieu est puissant et ne méprise personne; il est puissant en force d’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Il ne fait pas vivre le méchant, mais il fait droit aux malheureux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Il ne retire pas ses yeux de dessus le juste, et [celui-ci] est avec les rois sur le trône, et il les fait asseoir à toujours, et ils sont élevés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Et si, liés dans les chaînes, ils sont pris dans les cordeaux du malheur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Il leur montre ce qu’ils ont fait, et leurs transgressions, parce qu’elles sont devenues grandes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Et il ouvre leurs oreilles à la discipline, et leur dit de revenir de l’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'S’ils écoutent et le servent, ils accompliront leurs jours dans la prospérité et leurs années dans les choses agréables [de la vie];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Mais s’ils n’écoutent pas, ils s’en iront par l’épée, et expireront sans connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Les hypocrites de cœur amassent la colère; ils ne crient pas quand [Dieu] les lie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Ils mourront dans la jeunesse, et leur vie est parmi les hommes voués à l’infamie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Il délivre le malheureux dans son malheur, et lui ouvre l’oreille dans l’oppression.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Il t’aurait aussi tiré de la gueule de la détresse [et mis] au large, là où il n’y a point de gêne, et la graisse abonderait dans les mets de ta table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Mais tu es plein des jugements des méchants; le jugement et la justice [te] saisiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Puisqu’il y a de la colère, prends garde qu’elle ne t’enlève par le châtiment; et une grande rançon ne te le fera pas éviter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Tiendra-t-il compte de tes richesses? Non; – ni de l’or, ni de toutes les ressources de la puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Ne soupire pas après la nuit qui enlèvera les peuples de leur place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Prends garde à toi! Ne te tourne pas vers l’iniquité, car c’est ce que tu as choisi plutôt que l’affliction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Voici, ✶Dieu se montre élevé dans sa puissance: qui enseigne comme lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Qui lui a prescrit son chemin, et qui a dit: Tu as mal agi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Souviens-toi de glorifier son œuvre, que les hommes célèbrent:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Tout homme la contemple, le mortel la regarde de loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Voici, ✶Dieu est grand, et nous ne le connaissons pas; le nombre de ses années, nul ne le sonde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Car il attire les gouttes d’eau: des vapeurs qu’il forme elles distillent la pluie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Que les nuages font couler; ils tombent en gouttes sur les hommes, abondamment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Mais qui peut comprendre le déploiement de la nuée, le fracas de son tabernacle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Voici, il étend sa lumière autour de lui, et couvre le fond de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Car par ces choses il juge les peuples, il donne la nourriture en abondance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Il couvre ses mains de l’éclair, et lui commande où il doit frapper;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Son bruit l’annonce, le bétail même en présage la venue!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'À cause de cela aussi mon cœur tremble, et tressaille comme s’il sortait de sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Écoutez donc le bruit éclatant de sa voix et le grondement qui sort de sa bouche!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Il le dirige sous tous les cieux, et son éclair, jusqu’aux extrémités de la terre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Après lui une voix rugit. Il tonne de sa voix majestueuse, et il ne retient pas ses éclairs quand il fait entendre sa voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, '✶Dieu tonne merveilleusement de sa voix, faisant de grandes choses que nous ne comprenons pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Car il dit à la neige: Tombe sur la terre! et aussi aux averses de pluie, et aux averses des pluies de sa force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Il met un sceau sur la main de tout homme, afin que tous les hommes connaissent son œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Les bêtes sauvages rentrent dans leurs gîtes, et demeurent dans leurs repaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Des chambres [du midi] vient le tourbillon, et des vents du nord, le froid.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Au souffle de ✶Dieu se forme la glace, et la largeur des eaux se resserre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Il charge d’eau le nuage; sa lumière dissipe les nuées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Et sous sa conduite elles tournoient en tout sens, pour accomplir leur œuvre, tout ce qu’il leur commande sur la face du cercle de la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Soit qu’il les fasse venir comme verge, ou pour sa terre, ou en bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Écoute ceci, Job; tiens-toi là, et discerne les œuvres merveilleuses de ✶Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Sais-tu comment ✝Dieu les a disposées et comment il fait briller l’éclair de sa nuée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Comprends-tu le balancement des nuages, les œuvres merveilleuses de celui qui est parfait en connaissance, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Pourquoi tes vêtements sont chauds quand il donne du repos à la terre par le vent du midi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'As-tu étendu avec lui la voûte céleste, aussi ferme qu’un miroir de fonte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Fais-nous savoir ce que nous lui dirons! Nous ne savons préparer [des paroles], à cause de [nos] ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Lui racontera-t-on que je parle? Si quelqu’un lui parle, il sera sûrement englouti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Et maintenant on ne voit pas la lumière brillante, elle est [cachée] dans les nues; mais le vent passe et les [chasse, et] produit un ciel clair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'L’or vient du nord; – par-devers ✝Dieu est la majesté terrible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Le Tout-puissant, nous ne le trouvons pas; grand en force, en jugement et en beaucoup de justice, il n’opprime pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'C’est pourquoi les hommes le craindront; aucun des sages de cœur ne le contemplera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, '***Et l’ Éternel répondit à Job du milieu du tourbillon, et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Qui est celui-ci qui obscurcit le conseil par des discours sans connaissance?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Ceins tes reins comme un homme, et je t’interrogerai et tu m’instruiras!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Où étais-tu quand j’ai fondé la terre? Déclare-le-moi, si tu as de l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Qui lui a établi sa mesure, – si tu le sais? Ou qui a étendu le cordeau sur elle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Sur quoi ses bases sont-elles assises, ou qui a placé sa pierre angulaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Quand les étoiles du matin chantaient ensemble, et que tous les fils de Dieu éclataient de joie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Et qui a renfermé la mer dans des portes, quand elle rompit [les bornes] et sortit de la matrice,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Quand je fis de la nuée son vêtement, et de l’obscurité ses langes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Quand je lui découpai ses limites et lui mis des barres et des portes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'Et que je dis: Tu viendras jusqu’ici et tu n’iras pas plus loin, et ici s’arrêtera l’orgueil de tes flots?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'As-tu, de ta vie, commandé au matin? As-tu montré à l’aube du jour sa place,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Pour qu’elle saisisse les bords de la terre, et que les méchants en soient secoués?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Elle se change comme l’argile d’un sceau, et [toutes choses] se présentent parées comme d’un vêtement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Et leur lumière est ôtée aux méchants, et le bras levé est cassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Es-tu allé aux sources de la mer, et t’es-tu promené dans les profondeurs de l’abîme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Les portes de la mort se sont-elles découvertes à toi? Et as-tu vu les portes de l’ombre de la mort?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Ton regard a-t-il pénétré jusque dans les vastes espaces de la terre? Dis-le, si tu connais tout cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Où est le chemin vers le séjour de la lumière? et les ténèbres, où est leur place?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Pour que tu les prennes à leur limite, et que tu connaisses les sentiers de leur maison?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Tu le sais, car tu étais né alors, et le nombre de tes jours est grand!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Es-tu allé aux trésors de la neige, et as-tu vu les trésors de la grêle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Que j’ai mis en réserve pour le temps de la détresse, pour le jour du combat et de la guerre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Par quel chemin se distribue la lumière, et le vent d’orient se répand-il sur la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Qui a découpé des canaux aux torrents de pluie, et un chemin à l’éclair des tonnerres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Pour faire pleuvoir sur une terre où il n’y a personne, sur le désert où il n’y a pas d’hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Pour rassasier les lieux désolés et déserts, pour faire germer les pousses de l’herbe?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'La pluie a-t-elle un père? ou qui engendre les gouttes de la rosée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Du sein de qui sort la glace? et le frimas des cieux, qui l’enfante?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Devenues pierre, les eaux se cachent, et la surface de l’abîme se prend.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Peux-tu serrer les liens des Pléiades, ou détacher les cordes d’Orion?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Fais-tu sortir les signes du zodiaque en leurs saisons, et mènes-tu la grande Ourse avec ses filles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Connais-tu les lois des cieux, ou établis-tu leur empire sur la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Peux-tu élever ta voix vers les nuages, en sorte que des torrents d’eau te couvrent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'As-tu lancé la foudre, en sorte qu’elle soit allée et t’ait dit: Me voici?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Qui a mis la sagesse dans les reins, ou qui donna l’intelligence à l’esprit?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Qui a compté les nuages dans [sa] sagesse? et qui verse les outres des cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Quand la poussière coule comme du métal en fusion et que les mottes se soudent entre elles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Est-ce toi qui chasses la proie pour la lionne, et qui rassasies l’appétit des lionceaux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'Quand ils sont couchés dans leurs tanières [et] se tiennent aux aguets dans leur fourré?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Qui prépare au corbeau sa pâture quand ses petits crient à ✶Dieu [et] qu’ils errent sans nourriture?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Sais-tu le temps où mettent bas les bouquetins des rochers? As-tu observé les douleurs des biches?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'As-tu compté les mois qu’elles accomplissent, et connais-tu le temps où elles mettent bas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Elles se courbent, elles enfantent leur portée, elles se délivrent de leurs douleurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Leurs petits deviennent forts, ils grandissent dans les champs, ils s’en vont et ne reviennent pas à elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Qui a lâché l’âne sauvage? qui a délié les liens de l’onagre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Auquel j’ai donné le désert pour maison, et la terre salée pour demeure?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Il se rit du tumulte de la ville, il n’entend pas le cri du conducteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Il parcourt les montagnes pour trouver sa pâture, et il est en quête de tout ce qui est vert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Le buffle voudra-t-il être à ton service? Passera-t-il la nuit auprès de ta crèche?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Attacheras-tu le buffle par sa corde dans le sillon? Hersera-t-il les vallées après toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Auras-tu confiance en lui, parce que sa force est grande, et lui abandonneras-tu ton labeur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Te fieras-tu à lui pour rentrer ce que tu as semé, et rassemblera-t-il [le blé] dans ton aire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'L’aile de l’autruche bat joyeusement: ce sont les plumes et le plumage de la cigogne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Toutefois elle abandonne ses œufs à la terre et les chauffe sur la poussière,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Et elle oublie que le pied peut les écraser et la bête des champs les fouler;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Elle est dure avec ses petits comme s’ils n’étaient pas à elle; son labeur est vain, sans qu’elle s’en émeuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Car ✝Dieu l’a privée de sagesse, et ne lui a pas départi l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Quand elle s’enlève, elle se moque du cheval et de celui qui le monte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Est-ce toi qui as donné au cheval sa force? Est-ce toi qui as revêtu son cou d’une crinière flottante?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Est-ce toi qui le fais bondir comme la sauterelle? Son ronflement magnifique est terrible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Il creuse [le sol] dans la plaine et se réjouit de sa force; il sort à la rencontre des armes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Il se rit de la frayeur et ne s’épouvante pas, et il ne se tourne pas devant l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Sur lui retentit le carquois, brillent la lance et le javelot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Frémissant et agité, il dévore le sol, et ne peut se contenir quand sonne la trompette.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Au bruit de la trompette, il dit: Ha! ha! et de loin il flaire la bataille, le tonnerre des chefs et le tumulte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Est-ce par ton intelligence que l’épervier prend son essor et qu’il étend ses ailes vers le midi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Est-ce à ta parole que l’aigle s’élève et qu’il bâtit haut son aire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Il demeure dans les rochers et y fait son habitation, sur la dent du rocher et sur les hautes cimes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'De là il épie sa nourriture, ses yeux regardent dans le lointain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Ses petits sucent le sang, et là où sont les tués, là il est.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Et l’ Éternel répondit à Job et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Celui qui conteste avec le Tout-puissant l’instruira-t-il? Celui qui reprend ✝Dieu, qu’il réponde à cela!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Et Job répondit à l’ Éternel et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Voici, je suis une créature de rien, que te répliquerai-je? Je mettrai ma main sur ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'J’ai parlé une fois, et je ne répondrai plus; et deux fois, et je n’ajouterai rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, '*Et l’ Éternel répondit à Job du milieu du tourbillon et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Ceins tes reins comme un homme; je t’interrogerai, et tu m’instruiras!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Veux-tu donc anéantir mon jugement? Me démontreras-tu inique afin de te justifier?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'As-tu un bras comme ✶Dieu, et tonneras-tu de ta voix comme lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Pare-toi, je te prie, de grandeur et de magnificence; revêts-toi de majesté et de gloire!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Répands les fureurs de ta colère, et regarde tout ce qui s’élève et abaisse-le;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Regarde tout ce qui s’élève [et] humilie-le, et écrase sur place les méchants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Cache-les ensemble dans la poussière, lie leurs faces dans un lieu caché:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Alors moi aussi je te célébrerai, parce que ta droite te sauve!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Vois le béhémoth, que j’ai fait avec toi: il mange l’herbe comme le bœuf.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Regarde donc: sa force est dans ses reins, et sa puissance dans les muscles de son ventre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Il courbe sa queue comme un cèdre; les nerfs de sa cuisse sont entrelacés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Ses os sont des tubes d’airain, ses membres sont des barres de fer!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Il est la première des voies de ✶Dieu: celui qui l’a fait lui a fourni son épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Car les montagnes lui apportent [sa] pâture, là où se jouent toutes les bêtes des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Il se couche sous les lotus dans une retraite de roseaux et de marécages;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Les lotus le couvrent de leur ombre, les saules de la rivière l’environnent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Voici, que le fleuve déborde avec violence, il ne se précipite pas; il est plein d’assurance si un Jourdain se jette contre sa gueule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Le prendra-t-on en face? Lui percera-t-on le nez dans une trappe?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 25, 'Tireras-tu le léviathan avec un hameçon, et avec une corde lui feras-tu y enfoncer sa langue?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 26, 'Lui mettras-tu un jonc dans le nez, et lui perceras-tu la mâchoire avec un crochet?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 27, 'Te fera-t-il beaucoup de supplications, ou te dira-t-il des choses douces?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 28, 'Fera-t-il une alliance avec toi? Le prendras-tu comme serviteur à toujours?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 29, 'Joueras-tu avec lui comme avec un oiseau, et l’attacheras-tu pour tes jeunes filles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 30, 'Des associés feront-ils trafic de lui? Le partageront-ils entre des marchands?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 31, 'Rempliras-tu sa peau de dards, et sa tête de harpons à poissons?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 32, 'Mets ta main sur lui: souviens-toi de la bataille, – n’y reviens pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Voici, on est déçu dans son attente; même à sa vue, n’est-on pas terrassé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Nul n’est assez hardi pour le réveiller; et qui est celui qui se présentera devant moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Qui m’a prévenu, et je lui rendrai? Tout ce qui est sous les cieux est à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Je ne me tairai pas sur ses membres, sur ce qui concerne ses forces et sur la beauté de sa structure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Qui a mis à découvert le dessus de son vêtement? Qui pénétrera dans sa double mâchoire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Qui ouvrira les portes de son museau? Autour de ses dents est la terreur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Il est magnifique par la force de ses boucliers étroitement unis comme par un sceau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'L’un touche à l’autre, et le vent ne pénétrerait pas entre eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'L’un est attaché à l’autre, ils se tiennent et ne se séparent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Ses éternuements font jaillir la lumière, et ses yeux sont comme les paupières de l’aurore.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Des flammes sortent de sa gueule; des étincelles de feu s’en échappent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Une fumée sort de ses narines comme d’un pot qui bouillonne, comme d’une chaudière ardente;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Son souffle allumerait des charbons, et une flamme sort de sa gueule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Dans son cou loge la force, et la frayeur danse devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Les plis de sa chair adhèrent ensemble: coulés sur lui, ils ne bougent pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Son cœur est dur comme une pierre, dur comme la meule inférieure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Quand il se lève, les forts ont peur, ils s’enfuient saisis d’épouvante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Quand on l’atteint de l’épée, elle n’a aucun effet, ni la lance, ni le dard, ni la cuirasse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Il estime le fer comme de la paille, l’airain comme du bois vermoulu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'La flèche ne le met pas en fuite; les pierres de fronde se changent pour lui en du chaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Il estime la massue comme du chaume, et il se rit du bruit du javelot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Sous lui sont des tessons pointus; il étend une herse sur la vase.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Il fait bouillonner l’eau profonde comme une marmite, il fait de la mer comme un pot d’onguent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Il fait briller après lui [son] sillage; on prendrait l’abîme pour des cheveux gris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Il n’a pas son semblable sur la terre: il a été fait pour être sans peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Il regarde tout ce qui est élevé; il est roi sur tous les fiers animaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, '*Et Job répondit à l’ Éternel et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Je sais que tu peux tout, et qu’aucun dessein n’est trop difficile pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Qui est celui-ci qui, sans connaissance, voile le conseil? J’ai donc parlé, et sans comprendre, de choses trop merveilleuses pour moi, que je ne connaissais pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Écoute, je te prie, et je parlerai; je t’interrogerai, et toi, instruis-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Mon oreille avait entendu parler de toi, maintenant mon œil t’a vu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'C’est pourquoi j’ai horreur de moi, et je me repens dans la poussière et dans la cendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, '***Et il arriva, après que l’ Éternel eut dit ces paroles à Job, que l’ Éternel dit à Éliphaz, le Thémanite: Ma colère s’est enflammée contre toi et contre tes deux compagnons, car vous n’avez pas parlé de moi comme il convient, comme mon serviteur Job.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Et maintenant, prenez pour vous sept taureaux et sept béliers, et allez vers mon serviteur Job, et offrez un holocauste pour vous; et mon serviteur Job priera pour vous: car, lui, je l’aurai pour agréable, afin que je n’agisse pas avec vous selon votre folie; car vous n’avez pas parlé de moi comme il convient, comme mon serviteur Job.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Et Éliphaz le Thémanite, et Bildad le Shukhite, et Tsophar le Naamathite, allèrent et firent comme l’ Éternel leur avait dit; et l’ Éternel eut Job pour agréable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Et l’ Éternel rétablit l’ancien état de Job, quand il eut prié pour ses amis; et l’ Éternel donna à Job le double de tout ce qu’il avait eu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Et tous ses frères, et toutes ses sœurs, et tous ceux qui l’avaient connu auparavant vinrent à lui, et mangèrent le pain avec lui dans sa maison; et ils sympathisèrent avec lui et le consolèrent de tout le mal que l’ Éternel avait fait venir sur lui, et lui donnèrent chacun un késita, et chacun un anneau d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Et l’ Éternel bénit la fin de Job plus que son commencement: et il eut 14 000 brebis, et 6 000 chameaux, et 1 000 paires de bœufs, et 1 000 ânesses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'et il eut sept fils et trois filles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'et il appela le nom de la première Jémima, et le nom de la seconde Ketsia, et le nom de la troisième Kéren-Happuc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Et, dans tout le pays, il ne se trouvait point de femmes belles comme les filles de Job; et leur père leur donna un héritage parmi leurs frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Et, après cela, Job vécut 140 ans, et il vit ses fils, et les fils de ses fils, quatre générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Et Job mourut vieux et rassasié de jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Bienheureux l’homme qui ne marche pas dans le conseil des méchants, et ne se tient pas dans le chemin des pécheurs, et ne s’assied pas au siège des moqueurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Mais qui a son plaisir en la loi de l’ Éternel, et médite dans sa loi jour et nuit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Et il sera comme un arbre planté près des ruisseaux d’eaux, qui rend son fruit en sa saison, et dont la feuille ne se flétrit point; et tout ce qu’il fait prospère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Il n’en est pas ainsi des méchants, mais ils sont comme la balle que le vent chasse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'C’est pourquoi les méchants ne subsisteront point dans le jugement, ni les pécheurs dans l’assemblée des justes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Car l’ Éternel connaît la voie des justes; mais la voie des méchants périra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Pourquoi s’agitent les nations, et les peuples méditent-ils la vanité?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Les rois de la terre se lèvent, et les princes consultent ensemble contre l’ Éternel et contre son Oint:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Rompons leurs liens, et jetons loin de nous leurs cordes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Celui qui habite dans les cieux se rira [d’eux], le Seigneur s’en moquera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Alors il leur parlera dans sa colère, et, dans sa fureur, il les épouvantera:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Et moi, j’ai oint mon roi sur Sion, la montagne de ma sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Je raconterai le décret: l’ Éternel m’a dit: Tu es mon Fils; aujourd’hui, je t’ai engendré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Demande-moi, et je te donnerai les nations pour héritage, et, pour ta possession, les bouts de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Tu les briseras avec un sceptre de fer; comme un vase de potier tu les mettras en pièces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Et maintenant, ô rois, soyez intelligents; vous, juges de la terre, recevez instruction:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Servez l’ Éternel avec crainte, et réjouissez-vous avec tremblement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Embrassez le Fils, de peur qu’il ne s’irrite, et que vous ne périssiez dans le chemin, quand sa colère s’embrasera tant soit peu. Bienheureux tous ceux qui se confient en lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, '*Psaume de David, lorsqu’il s’enfuyait de devant Absalom, son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Éternel! combien sont multipliés mes ennemis, et sont nombreux ceux qui s’élèvent contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Beaucoup disent de mon âme: Il n’y a point de salut pour lui en Dieu. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Mais toi, Éternel! tu es un bouclier pour moi; tu es ma gloire, et celui qui élève ma tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Je crierai de ma voix à l’ Éternel, et il me répondra de sa montagne sainte. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Je me suis couché, et je m’endormirai: je me réveillerai, car l’ Éternel me soutient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Je n’aurai pas de crainte des myriades du peuple qui se sont mises contre moi tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Lève-toi, Éternel; sauve-moi, mon Dieu! Car tu as frappé à la joue tous mes ennemis; tu as cassé les dents des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, 'De l’ Éternel est le salut. Ta bénédiction est sur ton peuple. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Au chef de musique. Sur Neguinoth. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Quand je crie, réponds-moi, Dieu de ma justice! Dans la détresse tu m’as mis au large; use de grâce envers moi, et écoute ma prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Fils d’hommes, jusques à quand [livrerez-vous] ma gloire à l’opprobre? [Jusques à quand] aimerez-vous la vanité et chercherez-vous le mensonge? Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Mais sachez que l’ Éternel s’est choisi l’homme pieux. L’ Éternel écoutera quand je crierai à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Agitez-vous, et ne péchez pas; méditez dans vos cœurs sur votre couche, et soyez tranquilles. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Offrez des sacrifices de justice, et confiez-vous en l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Beaucoup disent: Qui nous fera voir du bien? Lève sur nous la lumière de ta face, ô Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Tu as mis de la joie dans mon cœur, plus qu’au temps où leur froment et leur moût ont été abondants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, 'Je me coucherai, et aussi je dormirai en paix; car toi seul, ô Éternel! tu me fais habiter en sécurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Au chef de musique. Pour Nehiloth. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Prête l’oreille à mes paroles, ô Éternel! Considère ma méditation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Sois attentif à la voix de ma supplication, mon Roi et mon Dieu! car c’est toi que je prie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Éternel! le matin, tu entendras ma voix; le matin, je disposerai [ma prière] devant toi, et j’attendrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Car tu n’es pas un ✶Dieu qui prenne plaisir à la méchanceté; le mal ne séjournera point chez toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Les insensés ne subsisteront point devant tes yeux; tu hais tous les ouvriers d’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Tu feras périr ceux qui profèrent le mensonge; l’homme de sang et de fourbe, l’ Éternel l’a en abomination.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Mais moi, dans l’abondance de ta bonté, j’entrerai dans ta maison; je me prosternerai devant le temple de ta sainteté, dans ta crainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Éternel! conduis-moi dans ta justice, à cause de mes ennemis; dresse ta voie devant moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Car il n’y a rien de sûr dans leur bouche; leur intérieur n’est que perversion; c’est un sépulcre ouvert que leur gosier; ils flattent de leur langue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Punis-les, ô Dieu! Qu’ils tombent par leurs propres conseils; chasse-les à cause de la multitude de leurs transgressions; car ils se sont rebellés contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Et tous ceux qui se confient en toi se réjouiront, ils chanteront de joie à toujours, et tu les protégeras; et ceux qui aiment ton nom s’égaieront en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, 'Car toi, tu béniras le juste, ô Éternel! Comme d’un bouclier tu l’environneras de faveur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Au chef de musique. Sur Neguinoth, sur Sheminith. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Éternel! ne me reprends pas dans ta colère, et ne me châtie pas dans ta fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Use de grâce envers moi, Éternel! car je suis défaillant; guéris-moi, Éternel! car mes os sont troublés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Mon âme aussi est fort troublée... Et toi, Éternel! jusques à quand?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Reviens, Éternel! délivre mon âme; sauve-moi à cause de ta bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Car on ne se souvient point de toi dans la mort; dans le shéol, qui te célébrera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Je suis las à force de gémir; toute la nuit je baigne ma couche, je trempe mon lit de mes larmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Mon œil dépérit de chagrin, il a vieilli à cause de tous ceux qui me pressent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Retirez-vous de moi, vous, tous les ouvriers d’iniquité, car l’ Éternel a entendu la voix de mes pleurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'L’ Éternel a entendu ma supplication; l’ Éternel a reçu ma prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, 'Tous mes ennemis seront honteux et fort troublés; ils s’en retourneront, ils seront confus en un moment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Shiggaïon de David, qu’il chanta à l’ Éternel à l’occasion des paroles de Cush, le Benjaminite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Éternel, mon Dieu! en toi j’ai mis ma confiance: sauve-moi de tous ceux qui me poursuivent, et délivre-moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'De peur qu’il ne déchire mon âme comme un lion qui met en pièces, et il n’y a personne qui délivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Éternel, mon Dieu! si j’ai fait cela, s’il y a de la méchanceté dans mes mains,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Si j’ai rendu le mal à celui qui était en paix avec moi (mais j’ai délivré celui qui me pressait sans cause),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Que l’ennemi poursuive mon âme et l’atteigne, et qu’il foule à terre ma vie, et qu’il fasse demeurer ma gloire dans la poussière. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Lève-toi dans ta colère, ô Éternel! Élève-toi contre les fureurs de ceux qui me pressent, et réveille-toi pour moi: tu as commandé le jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Et l’assemblée des peuplades t’environnera; et [toi], à cause d’elle, retourne en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'L’ Éternel jugera les peuples. Juge-moi, ô Éternel, selon ma justice et selon mon intégrité qui est en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Que la malice des méchants prenne fin, je te prie, et affermis le juste, toi, le Dieu juste, qui sondes les cœurs et les reins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Mon bouclier est par-devers Dieu qui sauve ceux qui sont droits de cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Dieu est un juste juge, et un ✶Dieu qui s’irrite tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Si [le méchant] ne se retourne pas, [Dieu] aiguisera son épée: il a bandé son arc, et l’a ajusté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Et il a préparé contre lui des instruments de mort, il a rendu brûlantes ses flèches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Voici, [le méchant] est en travail pour l’iniquité, et il conçoit le trouble et il enfante le mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Il a creusé une fosse, et il l’a rendue profonde; et il est tombé dans la fosse qu’il a faite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Le trouble qu’il avait préparé retombera sur sa tête, et sa violence descendra sur son crâne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 18, 'Je célébrerai l’ Éternel selon sa justice, et je chanterai le nom de l’ Éternel, le Très-haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Au chef de musique. Sur Guitthith. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Éternel, notre Seigneur! que ton nom est magnifique par toute la terre; tu as mis ta majesté au-dessus des cieux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Par la bouche des petits enfants et de ceux qui tètent, tu as fondé [ta] force, à cause de tes adversaires, afin de réduire au silence l’ennemi et le vengeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Quand je regarde tes cieux, l’ouvrage de tes doigts, la lune et les étoiles que tu as disposées:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Qu’est-ce que l’homme, que tu te souviennes de lui, et le fils de l’homme, que tu le visites?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Tu l’as fait de peu inférieur aux anges, et tu l’as couronné de gloire et d’honneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Tu l’as fait dominer sur les œuvres de tes mains; tu as mis toutes choses sous ses pieds:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Les brebis et les bœufs, tous ensemble, et aussi les bêtes des champs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'L’oiseau des cieux, et les poissons de la mer, ce qui passe par les sentiers des mers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, 'Éternel, notre Seigneur! que ton nom est magnifique par toute la terre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, '*Au chef de musique. Sur Muth-Labben. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Je célébrerai l’ Éternel de tout mon cœur; je raconterai toutes tes merveilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Je me réjouirai et je m’égaierai en toi; je chanterai ton nom, ô Très-haut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Quand mes ennemis sont retournés en arrière, ils ont bronché, et ont péri devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Car tu as maintenu mon droit et ma cause; tu t’es assis sur le trône, toi qui juges justement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Tu as tancé les nations, tu as fait périr le méchant; tu as effacé leur nom pour toujours et à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Ô ennemi! les dévastations sont venues à leur fin pour toujours. Tu as aussi rasé des villes, leur mémoire a péri avec elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Mais l’ Éternel est assis pour toujours; il a préparé son trône pour le jugement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Et il jugera le monde avec justice, et exercera le jugement sur les peuples avec droiture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Et l’ Éternel sera une haute retraite pour l’opprimé, une haute retraite dans les temps de détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Et ceux qui connaissent ton nom se confieront en toi; car tu n’as pas abandonné ceux qui te cherchent, ô Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Chantez à l’ Éternel qui habite en Sion, annoncez parmi les peuples ses [hauts] faits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Car en recherchant le sang il se souvient d’eux; il n’oublie pas le cri des affligés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Ô Éternel! use de grâce envers moi; regarde mon affliction [que je souffre] de la part de ceux qui me haïssent, toi qui me fais remonter des portes de la mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Afin que je raconte toutes tes louanges dans les portes de la fille de Sion. Je me réjouirai en ton salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Les nations se sont enfoncées dans la fosse qu’elles ont faite; au filet même qu’elles ont caché, leur pied a été pris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'L’ Éternel s’est fait connaître par le jugement qu’il a exécuté; le méchant est enlacé dans l’œuvre de ses mains. Higgaïon. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Les méchants seront repoussés jusque dans le shéol, toutes les nations qui oublient Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Car le pauvre ne sera pas oublié à jamais, l’attente des débonnaires ne périra pas pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Lève-toi, Éternel! que l’homme ne prévale pas. Que les nations soient jugées devant ta face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 21, 'Éternel! remplis-les de frayeur. Que les nations sachent qu’elles ne sont que des hommes. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Pourquoi, ô Éternel! te tiens-tu loin, te caches-tu aux temps de la détresse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Le méchant, dans son orgueil, poursuit ardemment l’affligé; ils seront pris dans les trames qu’ils ont ourdies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Car le méchant se glorifie du désir de son âme; et il bénit l’avare, il méprise l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Le méchant, dans la fierté de sa face, [dit]: Il ne s’enquerra [de rien]. – Il n’y a point de Dieu: [voilà] toutes ses pensées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Ses voies réussissent en tout temps; tes jugements sont trop hauts pour être devant lui; il souffle contre tous ses adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Il dit en son cœur: Je ne serai pas ébranlé; de génération en génération [je ne tomberai] pas dans le malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Sa bouche est pleine de malédiction, et de tromperies, et d’oppressions; il n’y a sous sa langue que trouble et que vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Il se tient aux embuscades des villages; dans des lieux cachés, il tue l’innocent; ses yeux épient le malheureux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Il se tient aux embûches dans un lieu caché, comme un lion dans son fourré; il se tient aux embûches pour enlever l’affligé; il enlève l’affligé, quand il l’a attiré dans son filet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Il se tapit, il se baisse, afin que les malheureux tombent par sa force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Il dit en son cœur: ✶Dieu a oublié, il cache sa face, il ne verra pas, à jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Lève-toi, Éternel! Ô ✶Dieu, élève ta main! n’oublie pas les affligés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Pourquoi le méchant méprise-t-il Dieu? Il dit en son cœur: Tu ne t’enquerras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Tu l’as vu, car toi tu regardes la peine et le chagrin pour [les] rendre par ta main; le malheureux s’abandonne à toi, tu es le secours de l’orphelin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Casse le bras du méchant, et recherche l’iniquité du méchant jusqu’à ce que tu n’en trouves plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'L’ Éternel est roi à toujours et à perpétuité; les nations ont péri de dessus sa terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Éternel! tu as exaucé le désir des débonnaires, tu as établi leur cœur; tu as prêté l’oreille,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Pour faire droit à l’orphelin et à l’opprimé, afin que l’homme qui est de la terre n’effraie plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, '*Au chef de musique. De David. Je me suis confié en l’ Éternel; – pourquoi dites-vous à mon âme: Oiseau, envole-toi vers votre montagne?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Car voici, les méchants bandent l’arc, ils ajustent leur flèche sur la corde, pour tirer dans les ténèbres sur ceux qui sont droits de cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Si les fondements sont détruits, que fera le juste?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'L’ Éternel est dans le palais de sa sainteté, l’ Éternel a son trône dans les cieux; ses yeux voient, ses paupières sondent les fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'L’ Éternel sonde le juste et le méchant; et celui qui aime la violence, son âme le hait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Il fera pleuvoir sur les méchants des pièges, du feu et du soufre; et un vent brûlant sera la portion de leur coupe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Car l’ Éternel juste aime la justice; sa face regarde l’homme droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Au chef de musique. Sur Sheminith. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Sauve, Éternel! car l’homme pieux n’est plus, car les fidèles ont disparu d’entre les fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Ils parlent la fausseté l’un à l’autre; [leur] lèvre est flatteuse, ils parlent d’un cœur double.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'L’ Éternel retranchera toutes les lèvres flatteuses, la langue qui parle de grandes choses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Ceux qui disent: Par nos langues nous prévaudrons, nos lèvres sont à nous; qui est seigneur sur nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'À cause de l’oppression des affligés, à cause du gémissement des pauvres, maintenant je me lèverai, dit l’ Éternel; je mettrai en sûreté [celui] contre qui on souffle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Les paroles de l’ Éternel sont des paroles pures, un argent affiné dans le creuset de terre, coulé sept fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Toi, Éternel! tu les garderas, tu les préserveras de cette génération, à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 9, 'Les méchants se promènent de toutes parts quand la bassesse est élevée parmi les fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Au chef de musique. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Jusques à quand, ô Éternel, m’oublieras-tu toujours? Jusques à quand cacheras-tu ta face de moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Jusques à quand consulterai -je dans mon âme, avec chagrin dans mon cœur, tous les jours? Jusques à quand mon ennemi s’élèvera-t-il par-dessus moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Regarde, réponds-moi, Éternel, mon Dieu! Illumine mes yeux, de peur que je ne dorme [du sommeil] de la mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'De peur que mon ennemi ne dise: J’ai eu le dessus sur lui, [et] que mes adversaires ne se réjouissent de ce que j’aurai été ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Mais pour moi, je me suis confié en ta bonté, mon cœur s’est réjoui dans ton salut. Je chanterai à l’ Éternel, parce qu’il m’a fait du bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Au chef de musique. De David. L’insensé a dit en son cœur: Il n’y a point de Dieu. Ils se sont corrompus, ils ont rendu abominables leurs actions; il n’y a personne qui fasse le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'L’ Éternel a regardé des cieux sur les fils des hommes, pour voir s’il y a quelqu’un qui soit intelligent, qui recherche Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Ils se sont tous détournés, ils se sont tous ensemble corrompus; il n’y a personne qui fasse le bien, non pas même un seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Tous les ouvriers d’iniquité n’ont-ils aucune connaissance? Ils dévorent mon peuple comme on mange du pain; ils n’invoquent point l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Là, ils ont été saisis de frayeur; car Dieu est au milieu de la génération juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Vous jetez l’opprobre sur le conseil de l’affligé, parce que l’ Éternel était sa confiance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Oh! si de Sion le salut d’Israël était venu! Quand l’ Éternel rétablira les captifs de son peuple, Jacob s’égaiera, Israël se réjouira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Psaume de David. Éternel! qui séjournera dans ta tente? qui demeurera en ta montagne sainte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Celui qui marche dans l’intégrité, et qui fait ce qui est juste, et qui parle la vérité de son cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Qui ne médit pas de sa langue; qui ne fait pas de mal à son compagnon, et qui ne fait pas venir l’opprobre sur son prochain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Aux yeux duquel l’homme vil est méprisable, mais qui honore ceux qui craignent l’ Éternel; qui jure à son détriment, et ne change pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Qui ne donne pas son argent à intérêt, et qui ne prend pas de présent contre l’innocent. Celui qui fait ces choses ne sera jamais ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, '*Mictam de David. Garde-moi, ô ✶Dieu! car je me confie en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Tu as dit à l’ Éternel: Tu es le Seigneur, ma bonté [ne s’élève] pas jusqu’à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, '[Tu as dit] aux saints qui sont sur la terre, et aux excellents: En eux sont toutes mes délices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Les misères de ceux qui courent après un autre seront multipliées: je ne répandrai pas leurs libations de sang, et je ne prendrai pas leurs noms sur mes lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'L’ Éternel est la portion de mon héritage et de ma coupe; tu maintiens mon lot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Les cordeaux sont tombés pour moi en des lieux agréables; oui, un bel héritage m’est échu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Je bénirai l’ Éternel qui me donne conseil; durant les nuits même mes reins m’enseignent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Je me suis toujours proposé l’ Éternel devant moi; parce qu’il est à ma droite je ne serai pas ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'C’est pourquoi mon cœur se réjouit, et mon âme s’égaie; même ma chair reposera en assurance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Car tu n’abandonneras pas mon âme au shéol, tu ne permettras pas que ton saint voie la corruption.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Tu me feras connaître le chemin de la vie; ta face est un rassasiement de joie, il y a des plaisirs à ta droite pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Prière de David. Écoute, ô Éternel, la justice; sois attentif à mon cri; prête l’oreille à ma prière, qui ne s’élève pas de lèvres trompeuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Que mon droit sorte de ta présence, que tes yeux regardent à la droiture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Tu as sondé mon cœur, tu [m’]as visité de nuit; tu m’as éprouvé au creuset, tu n’as rien trouvé; ma pensée ne va pas au-delà de ma parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Quant aux actions de l’homme, par la parole de tes lèvres je me suis gardé des voies de l’homme violent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Quand tu soutiens mes pas dans tes sentiers, mes pieds ne chancellent point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Je t’ai invoqué, car tu m’exauceras, ô ✶Dieu! Incline ton oreille vers moi, écoute mes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Rends admirable ta bonté, toi qui, par ta droite, sauves de [leurs] adversaires ceux qui se confient [en toi].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Garde-moi comme la prunelle de l’œil; cache-moi sous l’ombre de tes ailes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'De devant ces méchants qui me dévastent, mes ardents ennemis qui m’entourent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Ils sont enfermés dans leur propre graisse; de leur bouche, ils parlent avec hauteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'À [chacun de] nos pas, maintenant ils nous environnent; ils fixent leurs yeux, se baissant jusqu’à terre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Il est semblable au lion avide de déchirer, et comme le lionceau qui se tient dans les lieux cachés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Lève-toi, Éternel! devance-le, renverse-le; délivre mon âme du méchant [par] ton épée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, '[Délivre-moi] des hommes [par] ta main, ô Éternel! des hommes de ce monde, [qui ont] leur portion dans cette vie, et dont tu remplis le ventre de tes biens cachés; ils sont rassasiés de fils, et ils laissent le reste de leurs [biens] à leurs enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Moi, je verrai ta face en justice; quand je serai réveillé, je serai rassasié de ton image.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, '*Au chef de musique. Du serviteur de l’ Éternel, de David, qui adressa à l’ Éternel les paroles de ce cantique, le jour où l’ Éternel l’eut délivré de la main de tous ses ennemis, et de la main de Saül.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Et il dit: Je t’aimerai, ô Éternel, ma force!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Éternel, mon rocher, et mon lieu fort, et celui qui me délivre! Mon ✶Dieu, mon rocher, en qui je me confie, mon bouclier et la corne de mon salut, ma haute retraite!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Je crierai à l’ Éternel, qui est digne d’être loué, et je serai sauvé de mes ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Les cordeaux de la mort m’ont environné, et les torrents de Bélial m’ont fait peur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Les cordeaux du shéol m’ont entouré, les filets de la mort m’ont surpris:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Dans ma détresse j’ai invoqué l’ Éternel, et j’ai crié à mon Dieu: de son temple, il a entendu ma voix, et mon cri est parvenu devant lui à ses oreilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Alors la terre fut ébranlée, et trembla, et les fondements des montagnes furent secoués et furent ébranlés, parce qu’il était irrité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Une fumée montait de ses narines, et un feu sortant de sa bouche dévorait; des charbons en jaillissaient embrasés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Et il abaissa les cieux, et descendit; et il y avait une obscurité profonde sous ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Il était monté sur un chérubin, et volait, et il planait sur les ailes du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Il mit les ténèbres pour sa demeure secrète comme sa tente autour de lui, des ténèbres d’eaux, d’épaisses nuées de l’air.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'De la splendeur qui était devant lui, ses nuées épaisses passaient, de la grêle et des charbons de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Et l’ Éternel tonna dans les cieux, et le Très-haut fit retentir sa voix, – de la grêle et des charbons de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Et il tira ses flèches et dispersa [mes ennemis]; il lança des éclairs et les mit en déroute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Alors les lits des eaux parurent, et les fondements du monde furent mis à découvert, quand tu les tanças, ô Éternel, par le souffle du vent de tes narines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'D’en haut il étendit [sa main], il me prit, il me tira des grandes eaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Il me délivra de mon puissant ennemi et de ceux qui me haïssaient; car ils étaient plus forts que moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Ils m’avaient surpris au jour de ma calamité, mais l’ Éternel fut mon appui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Et il me fit sortir au large, il me délivra, parce qu’il prenait son plaisir en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'L’ Éternel m’a récompensé selon ma justice, il m’a rendu selon la pureté de mes mains;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Car j’ai gardé les voies de l’ Éternel, et je ne me suis point méchamment détourné de mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Car toutes ses ordonnances ont été devant moi; et ses statuts, je ne les ai pas écartés de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Et j’ai été parfait avec lui, et je me suis gardé de mon iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Et l’ Éternel m’a rendu selon ma justice, selon la pureté de mes mains devant ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Avec celui qui use de grâce, tu uses de grâce; avec l’homme parfait, tu te montres parfait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Avec celui qui est pur, tu te montres pur; et avec le pervers, tu es roide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Car toi tu sauveras le peuple affligé, et tu abaisseras les yeux hautains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Car c’est toi qui fais luire ma lampe: l’ Éternel, mon Dieu, fait resplendir mes ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Car, par toi, je courrai au travers d’une troupe, et, par mon Dieu, je franchirai une muraille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Quant à ✶Dieu, sa voie est parfaite; la parole de l’ Éternel est affinée; il est un bouclier à tous ceux qui se confient en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Car qui est ✝Dieu, hormis l’ Éternel, et qui est un rocher, si ce n’est notre Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Le ✶Dieu qui me ceint de force et qui rend ma voie parfaite? –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Qui rend mes pieds pareils à ceux des biches, et me fait tenir debout sur mes lieux élevés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Qui enseigne mes mains à combattre, et mes bras bandent un arc d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Et tu m’as donné le bouclier de ton salut, et ta droite m’a soutenu, et ta débonnaireté m’a agrandi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Tu as mis au large mes pas sous moi, et les chevilles de mes pieds n’ont pas chancelé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'J’ai poursuivi mes ennemis, et je les ai atteints; et je ne m’en suis pas retourné que je ne les aie consumés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Je les ai transpercés, et ils n’ont pu se relever; ils sont tombés sous mes pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Et tu m’as ceint de force pour le combat; tu as courbé sous moi ceux qui s’élevaient contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Et tu as fait que mes ennemis m’ont tourné le dos; et ceux qui me haïssaient, je les ai détruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Ils criaient, et il n’y avait point de sauveur; [ils criaient] à l’ Éternel, et il ne leur a pas répondu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Et je les ai brisés menu comme la poussière devant le vent; je les ai jetés loin comme la boue des rues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Tu m’as délivré des débats du peuple; tu m’as établi chef des nations; un peuple que je ne connaissais pas me servira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Dès qu’ils ont entendu de leur oreille, ils m’ont obéi; les fils de l’étranger se sont soumis à moi en dissimulant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Les fils de l’étranger ont dépéri, et ils sont sortis en tremblant de leurs lieux cachés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'L’ Éternel est vivant; et que mon Rocher soit béni! Et que le Dieu de mon salut soit exalté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Le ✶Dieu qui m’a donné des vengeances, et qui m’a assujetti les peuples,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Qui m’a délivré de mes ennemis! Même tu m’as élevé au-dessus de ceux qui s’élèvent contre moi, tu m’as délivré de l’homme violent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'C’est pourquoi, Éternel! je te célébrerai parmi les nations, et je chanterai des cantiques à [la gloire de] ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 51, '[C’est lui] qui a donné de grandes délivrances à son roi, et qui use de bonté envers son oint, envers David, et envers sa semence, à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, '*Au chef de musique. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Les cieux racontent la gloire de ✶Dieu, et l’étendue annonce l’ouvrage de ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Un jour en proclame la parole à l’autre jour, et une nuit la fait connaître à l’autre nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Il n’y a point de langage, il n’y a point de paroles; toutefois leur voix est entendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Leur cordeau s’étend par toute la terre, et leur langage jusqu’au bout du monde. En eux, il a mis une tente pour le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Il sort comme un époux de sa chambre nuptiale; comme un homme vaillant, il se réjouit de courir sa carrière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Sa sortie est d’un bout des cieux, et son tour jusqu’à l’autre bout; et rien n’est caché à sa chaleur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'La loi de l’ Éternel est parfaite, restaurant l’âme; les témoignages de l’ Éternel sont sûrs, rendant sages les sots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Les ordonnances de l’ Éternel sont droites, réjouissant le cœur; le commandement de l’ Éternel est pur, illuminant les yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'La crainte de l’ Éternel est pure, subsistant pour toujours; les jugements de l’ Éternel sont la vérité, justes tous ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Ils sont plus précieux que l’or et que beaucoup d’or fin, et plus doux que le miel et que ce qui distille des rayons de miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Aussi ton serviteur est instruit par eux; il y a un grand salaire à les garder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Qui est-ce qui comprend ses erreurs? Purifie-moi de mes [fautes] cachées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Garde aussi ton serviteur des péchés commis avec fierté; qu’ils ne dominent pas sur moi: alors je serai irréprochable, et je serai innocent de la grande transgression.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 15, 'Que les paroles de ma bouche et la méditation de mon cœur soient agréables devant toi, ô Éternel, mon rocher et mon rédempteur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Au chef de musique. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Que l’ Éternel te réponde au jour de la détresse! Que le nom du Dieu de Jacob te protège!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Que du sanctuaire il envoie ton secours, et que de Sion il te soutienne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Qu’il se souvienne de toutes tes offrandes, et qu’il accepte ton holocauste! Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Qu’il te donne selon ton cœur, et qu’il accomplisse tous tes conseils!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Nous triompherons dans ton salut, et nous élèverons nos bannières au nom de notre Dieu. Que l’ Éternel accomplisse toutes tes demandes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Maintenant je sais que l’ Éternel sauve son oint; il lui répondra des cieux de sa sainteté, par les actes puissants du salut de sa droite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Ceux-ci font gloire de [leurs] chars, et ceux-là de [leurs] chevaux, mais nous, du nom de l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Ceux-là se courbent et tombent; mais nous nous relevons et nous tenons debout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 10, 'Éternel, sauve! Que le roi nous réponde au jour où nous crions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Au chef de musique. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Éternel! le roi se réjouira en ta force, et combien s’égaiera-t-il en ton salut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Tu lui as donné le désir de son cœur, et tu ne lui as pas refusé la requête de ses lèvres. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Car tu l’as prévenu par des bénédictions excellentes; tu as mis sur sa tête une couronne d’or fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Il t’a demandé la vie: tu [la] lui as donnée, – une longueur de jours pour toujours et à perpétuité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Sa gloire est grande dans ta délivrance; tu l’as revêtu de majesté et de magnificence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Car tu l’as mis pour bénédictions à toujours; tu l’as rempli de joie par ta face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Car le roi se confie en l’ Éternel, et, par la bonté du Très-haut, il ne sera pas ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Ta main trouvera tous tes ennemis, ta droite trouvera ceux qui te haïssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Tu les rendras comme un four de feu, au temps de ta présence; l’ Éternel, dans sa colère, les engloutira, et le feu les dévorera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Tu feras périr leur fruit de dessus la terre, et leur semence d’entre les fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Car ils ont essayé de faire venir du mal sur toi, et ont médité des desseins qu’ils n’ont pu mettre à exécution.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Car tu leur feras tourner le dos, quand tu ajusteras la corde de ton arc contre leurs faces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 14, 'Sois exalté, ô Éternel, dans ta force! Nous chanterons, et nous célébrerons ta puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, '*Au chef de musique. Sur Ajéleth-Hashakhar. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mon ✶Dieu! mon ✶Dieu! pourquoi m’as-tu abandonné, [te tenant] loin de mon salut, – des paroles de mon rugissement?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Mon Dieu! je crie de jour, mais tu ne réponds point; et de nuit, et il n’y a point de repos pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Et toi, tu es saint, toi qui habites [au milieu des] louanges d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Nos pères se sont confiés en toi; ils se sont confiés, et tu les as délivrés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Ils ont crié vers toi, et ils ont été sauvés; ils se sont confiés en toi, et ils n’ont point été confus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Mais moi, je suis un ver, et non point un homme; l’opprobre des hommes, et le méprisé du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Tous ceux qui me voient se moquent de moi; ils ouvrent la bouche, ils hochent la tête:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Il se confie à l’ Éternel: qu’il le fasse échapper, qu’il le délivre, car il prend son plaisir en lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Mais c’est toi qui m’as tiré du sein [qui m’a porté]; tu m’as donné confiance sur les mamelles de ma mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'C’est à toi que je fus remis dès la matrice; tu es mon ✶Dieu dès le ventre de ma mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Ne te tiens pas loin de moi, car la détresse est proche, car il n’y a personne qui secoure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Beaucoup de taureaux m’ont environné, des puissants de Basan m’ont entouré;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Ils ouvrent leur gueule contre moi, comme un lion déchirant et rugissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Je suis répandu comme de l’eau, et tous mes os se déjoignent; mon cœur est comme de la cire, il est fondu au-dedans de mes entrailles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Ma vigueur est desséchée comme un têt, et ma langue est attachée à mon palais; et tu m’as mis dans la poussière de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Car des chiens m’ont environné, une assemblée de méchants m’a entouré; ils ont percé mes mains et mes pieds;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Je compterais tous mes os. Ils me contemplent, ils me regardent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Ils partagent entre eux mes vêtements, et sur ma robe ils jettent le sort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Et toi, Éternel! ne te tiens pas loin; ma Force! hâte-toi de me secourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Délivre mon âme de l’épée, mon unique de la patte du chien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Sauve-moi de la gueule du lion. Tu m’as répondu d’entre les cornes des buffles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'J’annoncerai ton nom à mes frères, je te louerai au milieu de la congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Vous qui craignez l’ Éternel, louez-le; toute la semence de Jacob, glorifiez-le; et révérez-le, vous, toute la semence d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Car il n’a pas méprisé ni rejeté l’affliction de l’affligé, et n’a point caché sa face de lui; mais, quand il a crié vers lui, il l’a écouté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'De toi [vient] ma louange dans la grande congrégation. Je paierai mes vœux devant ceux qui le craignent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Les débonnaires mangeront et seront rassasiés; ceux qui cherchent l’ Éternel le loueront; votre cœur vivra à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Tous les bouts de la terre se souviendront, et ils se tourneront vers l’ Éternel, et toutes les familles des nations se prosterneront devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Car le royaume est à l’ Éternel, et il domine au milieu des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Tous les gras de la terre mangeront et se prosterneront: devant lui se courberont tous ceux qui descendent dans la poussière, et celui qui ne peut faire vivre son âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Une semence le servira; elle sera comptée au Seigneur comme une génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 32, 'Ils viendront et raconteront sa justice à un peuple qui naîtra,... qu’il a fait [ces choses].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Psaume de David. L’ Éternel est mon berger: je ne manquerai de rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Il me fait reposer dans de verts pâturages, il me mène à des eaux paisibles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Il restaure mon âme; il me conduit dans des sentiers de justice, à cause de son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Même quand je marcherais par la vallée de l’ombre de la mort, je ne craindrai aucun mal; car tu es avec moi: ta houlette et ton bâton, ce sont eux qui me consolent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Tu dresses devant moi une table, en la présence de mes ennemis; tu as oint ma tête d’huile, ma coupe est comble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Oui, la bonté et la gratuité me suivront tous les jours de ma vie, et mon habitation sera dans la maison de l’ Éternel pour de longs jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'De David. Psaume. À l’ Éternel est la terre et tout ce qu’elle contient, le monde et ceux qui l’habitent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Car lui l’a fondée sur les mers, et l’a établie sur les fleuves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Qui est-ce qui montera en la montagne de l’ Éternel? et qui se tiendra dans le lieu de sa sainteté?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Celui qui a les mains innocentes et le cœur pur, qui n’élève pas son âme à la vanité, et ne jure pas avec fausseté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Il recevra bénédiction de l’ Éternel, et justice du Dieu de son salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Telle est la génération de ceux qui le cherchent, de ceux qui recherchent ta face, ô Jacob. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Portes, élevez vos têtes! et élevez-vous, portails éternels, et le roi de gloire entrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Qui est ce roi de gloire? L’ Éternel fort et puissant, l’ Éternel puissant dans la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Portes, élevez vos têtes! et élevez-vous, portails éternels, et le roi de gloire entrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Qui est-il, ce roi de gloire? L’ Éternel des armées, lui, est le roi de gloire. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, '*De David. À toi, Éternel, j’élève mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Mon Dieu, en toi j’ai mis ma confiance; que je ne sois pas confus, que mes ennemis ne triomphent pas de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Non, aucun de ceux qui s’attendent à toi ne sera confus; ceux-là seront confus qui agissent perfidement sans cause.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Fais-moi connaître tes voies, ô Éternel! enseigne-moi tes sentiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Fais-moi marcher dans ta vérité, et enseigne-moi, car tu es le Dieu de mon salut; c’est à toi que je m’attends tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Souviens-toi de ta miséricorde, ô Éternel, et de ta bonté; car elles sont de tout temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Ne te souviens pas des péchés de ma jeunesse ni de mes transgressions; selon ta gratuité souviens-toi de moi à cause de ta bonté, ô Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'L’ Éternel est bon et droit; c’est pourquoi il enseignera le chemin aux pécheurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Il fera marcher dans le droit [chemin] les débonnaires, et il enseignera sa voie aux débonnaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Tous les sentiers de l’ Éternel sont gratuité et vérité, pour ceux qui gardent son alliance et ses témoignages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'À cause de ton nom, ô Éternel! tu me pardonneras mon iniquité; car elle est grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Qui est l’homme qui craint l’ Éternel? Il lui enseignera le chemin qu’il doit choisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Son âme habitera au milieu du bien, et sa semence possédera la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Le secret de l’ Éternel est pour ceux qui le craignent, pour leur faire connaître son alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Mes yeux sont continuellement sur l’ Éternel; car c’est lui qui fera sortir mes pieds du filet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Tourne-toi vers moi et use de grâce envers moi, car je suis seul et affligé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Les détresses de mon cœur se sont agrandies; fais-moi sortir de mes angoisses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Regarde mon affliction et mes peines, et pardonne tous mes péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Regarde mes ennemis, car ils sont nombreux, et ils me haïssent d’une haine violente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Garde mon âme, et délivre-moi; que je ne sois pas confus, car je me suis confié en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Que l’intégrité et la droiture me gardent, car je me suis attendu à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Ô Dieu! rachète Israël de toutes ses détresses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'De David. Ô Éternel! juge-moi, car j’ai marché dans mon intégrité, et je me suis confié en l’ Éternel: je ne chancellerai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Sonde-moi, ô Éternel! et éprouve-moi; examine mes reins et mon cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Car ta bonté est devant mes yeux, et j’ai marché dans ta vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Je ne me suis pas assis avec des hommes vains, et je ne suis pas allé avec les gens dissimulés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'J’ai haï la congrégation de ceux qui font le mal, et je ne m’assiérai pas avec les méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Je laverai mes mains dans l’innocence, et je ferai le tour de ton autel, ô Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Pour entonner la louange, et pour raconter toutes tes merveilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Éternel! j’ai aimé l’habitation de ta maison, et le lieu de la demeure de ta gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'N’assemble pas mon âme avec les pécheurs, ni ma vie avec les hommes de sang,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'Dans les mains desquels il y a des crimes, et dont la droite est pleine de présents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Mais moi, je marcherai dans mon intégrité. Rachète-moi, et use de grâce envers moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Mon pied se tient au chemin uni: je bénirai l’ Éternel dans les congrégations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'De David. L’ Éternel est ma lumière et mon salut: de qui aurai-je peur? L’ Éternel est la force de ma vie: de qui aurai-je frayeur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Quand les méchants, mes adversaires et mes ennemis, se sont approchés de moi pour dévorer ma chair, ils ont bronché et sont tombés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Quand une armée camperait contre moi, mon cœur ne craindrait pas; si la guerre s’élève contre moi, en ceci j’aurai confiance:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'J’ai demandé une chose à l’ Éternel, je la rechercherai: [c’est] que j’habite dans la maison de l’ Éternel tous les jours de ma vie, pour voir la beauté de l’ Éternel et pour m’enquérir diligemment [de lui] dans son temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Car, au mauvais jour, il me mettra à couvert dans sa loge, il me tiendra caché dans le secret de sa tente; il m’élèvera sur un rocher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Et maintenant, ma tête sera élevée par-dessus mes ennemis qui sont à l’entour de moi; et je sacrifierai dans sa tente des sacrifices de cris de réjouissance; je chanterai et je psalmodierai à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Éternel! écoute; de ma voix, je crie [à toi]: use de grâce envers moi, et réponds-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Mon cœur a dit pour toi: Cherchez ma face. Je chercherai ta face, ô Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Ne me cache pas ta face, ne repousse point ton serviteur avec colère. Tu as été mon secours; ne me délaisse pas, et ne m’abandonne pas, ô Dieu de mon salut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Quand mon père et ma mère m’auraient abandonné, l’ Éternel me recueillera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Éternel! enseigne-moi ton chemin, et conduis-moi dans [le] sentier uni, à cause de mes ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Ne me livre pas au désir de mes adversaires; car de faux témoins se sont élevés contre moi, et des gens qui respirent la violence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Si je n’avais pas eu la confiance que je verrais la bonté de l’ Éternel dans la terre des vivants...!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Attends-toi à l’ Éternel; fortifie-toi, et que ton cœur soit ferme: oui, attends-toi à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'De David. Éternel! je crie à toi; mon rocher! ne te tais point envers moi; de peur que, si tu gardes le silence envers moi, je ne sois fait semblable à ceux qui descendent dans la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Écoute la voix de mes supplications quand je crie à toi, quand j’élève mes mains vers l’oracle de ta sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Ne m’entraîne pas avec les méchants, ni avec les ouvriers d’iniquité, qui parlent paix avec leur prochain, tandis que la méchanceté est dans leur cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Donne-leur selon leur œuvre et selon l’iniquité de leurs actions; donne-leur selon l’ouvrage de leurs mains, rends-leur selon ce qu’ils ont fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Parce qu’ils ne discernent pas les œuvres de l’ Éternel, ni l’ouvrage de ses mains, il les détruira et ne les édifiera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Béni soit l’ Éternel! car il a entendu la voix de mes supplications.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'L’ Éternel est ma force et mon bouclier; en lui mon cœur a eu sa confiance, et j’ai été secouru; et mon cœur se réjouit, et je le célébrerai dans mon cantique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'L’ Éternel est leur force, et il est le lieu fort des délivrances de son oint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Sauve ton peuple, et bénis ton héritage; et pais-les, et élève-les pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Psaume de David. Rendez à l’ Éternel, fils des forts, rendez à l’ Éternel la gloire et la force!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Rendez à l’ Éternel la gloire de son nom; adorez l’ Éternel en sainte magnificence!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'La voix de l’ Éternel est sur les eaux; le ✶Dieu de gloire fait tonner, – l’ Éternel sur les grandes eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'La voix de l’ Éternel est puissante, la voix de l’ Éternel est magnifique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'La voix de l’ Éternel brise les cèdres: l’ Éternel brise les cèdres du Liban,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Et il les fait bondir comme un veau, le Liban et le Sirion comme un jeune buffle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'La voix de l’ Éternel fait jaillir des sillons de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'La voix de l’ Éternel fait trembler le désert; l’ Éternel fait trembler le désert de Kadès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'La voix de l’ Éternel fait faonner les biches, et dépouille les forêts; et dans son temple tout dit: Gloire!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'L’ Éternel s’assied sur les flots, l’ Éternel s’assied comme roi à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'L’ Éternel donnera force à son peuple, l’ Éternel bénira son peuple par la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Psaume. Cantique de dédicace de la maison. De David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Éternel! je t’exalterai, parce que tu m’as délivré, et que tu n’as pas réjoui mes ennemis à mon sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Éternel, mon Dieu! j’ai crié à toi, et tu m’as guéri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Éternel! tu as fait remonter mon âme du shéol; tu m’as rendu la vie, d’entre ceux qui descendent dans la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Chantez à l’ Éternel, vous, ses saints, et célébrez la mémoire de sa sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Car il y a un moment dans sa colère, il y a une vie dans sa faveur; le soir, les pleurs viennent loger [avec nous], et le matin il y a un chant de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Et moi, j’ai dit dans ma prospérité: Je ne serai jamais ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Éternel! par ta faveur, tu as donné la stabilité et la force à ma montagne...; tu as caché ta face, j’ai été épouvanté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Éternel! j’ai crié à toi, et j’ai supplié le Seigneur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Quel profit y a-t-il en mon sang, quand je descendrais dans la fosse? La poussière te célébrera-t-elle? Annoncera-t-elle ta vérité?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Écoute, ô Éternel! et use de grâce envers moi; Éternel, sois-moi en aide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Tu as changé mon deuil en allégresse, tu as détaché mon sac, et tu m’as ceint de joie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 13, 'Afin que [mon] âme te loue par des cantiques et ne se taise point. Éternel, mon Dieu! je te célébrerai à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Au chef de musique. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'En toi, Éternel, j’ai placé ma confiance; que je ne sois jamais confus; délivre-moi dans ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Incline vers moi ton oreille, hâte-toi, délivre-moi; sois pour moi un rocher, une forteresse, une maison [qui me soit] un lieu fort, afin de me sauver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Car tu es mon rocher et mon lieu fort; à cause de ton nom, mène-moi et conduis-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Fais-moi sortir du filet qu’ils ont caché pour moi; car toi, tu es ma force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'En ta main je remets mon esprit; tu m’as racheté, ô Éternel, ✶Dieu de vérité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'J’ai haï ceux qui prennent garde aux vaines idoles; mais moi, je me confierai en l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Je m’égaierai, et je me réjouirai en ta bonté; car tu as regardé mon affliction, tu as connu les détresses de mon âme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Et tu ne m’as pas livré en la main de l’ennemi, tu as fait tenir mes pieds au large.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Éternel! use de grâce envers moi, car je suis dans la détresse; mon œil dépérit de chagrin, mon âme et mon ventre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Car ma vie se consume dans la tristesse, et mes années dans le gémissement; ma force déchoit à cause de mon iniquité, et mes os dépérissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Plus qu’à tous mes ennemis, je suis un opprobre aussi à mes voisins, [même] extrêmement, et une frayeur à ceux de ma connaissance; ceux qui me voient dehors s’enfuient de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Je suis oublié de leur cœur comme un mort, j’ai été comme un vase de rebut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Car j’ai entendu les diffamations de plusieurs, – la terreur de tous côtés! – quand ils consultaient ensemble contre moi: ils complotent de m’ôter la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Mais moi, ô Éternel, je me suis confié en toi; j’ai dit: Tu es mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Mes temps sont en ta main; délivre-moi de la main de mes ennemis et de ceux qui me poursuivent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Fais luire ta face sur ton serviteur; sauve-moi par ta bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Éternel! que je ne sois pas confus, car je t’ai invoqué! Que les méchants soient confus, qu’ils se taisent dans le shéol!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Qu’elles soient muettes, les lèvres menteuses qui parlent contre le juste insolemment, avec orgueil et mépris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Oh! que ta bonté est grande, que tu as mise en réserve pour ceux qui te craignent, [et] dont tu uses devant les fils des hommes envers ceux qui se confient en toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Tu les caches dans le lieu secret de ta face, loin des complots de l’homme; tu les mets à couvert dans une loge, loin des contestations des langues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Béni soit l’ Éternel, car il a rendu admirable sa bonté envers moi dans une ville forte!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Et moi, je disais en mon agitation: Je suis retranché de devant tes yeux. Néanmoins tu as entendu la voix de mes supplications, quand j’ai crié à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Aimez l’ Éternel, vous tous ses saints! L’ Éternel garde les fidèles, et il rétribue largement celui qui agit avec orgueil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 25, 'Fortifiez-vous, et que votre cœur soit ferme, vous tous qui avez votre attente en l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'De David. Instruction. Bienheureux celui dont la transgression est pardonnée, [et] dont le péché est couvert!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Bienheureux l’homme à qui l’ Éternel ne compte pas l’iniquité, et dans l’esprit duquel il n’y a point de fraude!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Quand je me suis tu, mes os ont dépéri, quand je rugissais tout le jour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Car jour et nuit ta main s’appesantissait sur moi; ma vigueur s’est changée en une sécheresse d’été. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Je t’ai fait connaître mon péché, et je n’ai pas couvert mon iniquité; j’ai dit: Je confesserai mes transgressions à l’ Éternel; et toi, tu as pardonné l’iniquité de mon péché. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'C’est pourquoi tout homme pieux te priera au temps où l’on te trouve; certainement, en un déluge de grandes eaux, celles-ci ne l’atteindront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Tu es mon asile; tu me gardes de détresse, tu m’entoures des chants de triomphe de la délivrance. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Je t’instruirai, et je t’enseignerai le chemin où tu dois marcher; je te conseillerai, ayant mon œil sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Ne soyez pas comme le cheval, comme le mulet, qui n’ont pas d’intelligence, dont l’ornement est la bride et le mors, pour les refréner quand ils ne veulent pas s’approcher de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Le méchant a beaucoup d’afflictions; mais [l’homme] qui se confie en l’ Éternel, la bonté l’environnera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Réjouissez-vous en l’ Éternel, et égayez-vous, justes! et jetez des cris de joie, vous tous qui êtes droits de cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Exultez en l’ Éternel, vous justes! aux hommes droits sied la louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Célébrez l’ Éternel avec la harpe; chantez ses louanges sur le luth à dix cordes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Chantez-lui un cantique nouveau; pincez habilement de vos instruments avec un cri de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Car la parole de l’ Éternel est droite, et toute son œuvre est avec vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Il aime la justice et le jugement; la terre est pleine de la bonté de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Les cieux ont été faits par la parole de l’ Éternel, et toute leur armée par l’esprit de sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Il amasse comme un monceau les eaux de la mer, il met dans des réservoirs les abîmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Que toute la terre craigne l’ Éternel; que tous les habitants du monde le redoutent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Car, lui, il a parlé, et [la chose] a été; il a commandé, et elle s’est tenue là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'L’ Éternel dissipe le conseil des nations, il met à néant les desseins des peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Le conseil de l’ Éternel subsiste à toujours, les desseins de son cœur, de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Bienheureuse la nation qui a l’ Éternel pour son Dieu, le peuple qu’il a choisi pour son héritage!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'L’ Éternel regarde des cieux; il voit tous les fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Du lieu de sa demeure il considère tous les habitants de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'C’est lui qui forme leur cœur à tous, qui prend connaissance de toutes leurs œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Un roi n’est pas sauvé par la multitude de son armée, et l’homme puissant n’est pas délivré par sa grande force;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Le cheval est une chose vaine pour sauver, et il ne délivre point par la grandeur de sa force:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Voici, l’œil de l’ Éternel est sur ceux qui le craignent, sur ceux qui s’attendent à sa bonté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Pour délivrer leur âme de la mort, et pour les conserver en vie durant la famine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Notre âme s’attend à l’ Éternel; il est notre aide et notre bouclier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Car notre cœur se réjouira en lui, puisqu’en son saint nom nous avons mis notre confiance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Que ta bonté, ô Éternel! soit sur nous, selon que nous nous sommes attendus à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'De David, quand il dissimula sa raison devant Abimélec, qui le chassa, et il s’en alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Je bénirai l’ Éternel en tout temps; sa louange sera continuellement dans ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Mon âme se glorifiera en l’ Éternel; les débonnaires l’entendront, et se réjouiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Magnifiez l’ Éternel avec moi, et exaltons ensemble son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'J’ai cherché l’ Éternel; et il m’a répondu, et m’a délivré de toutes mes frayeurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Ils ont regardé vers lui, et ils ont été illuminés, et leurs faces n’ont pas été confuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Cet affligé a crié; et l’ Éternel l’a entendu, et l’a sauvé de toutes ses détresses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'L’ange de l’ Éternel campe autour de ceux qui le craignent, et les délivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Goûtez et voyez que l’ Éternel est bon! Bienheureux l’homme qui se confie en lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Craignez l’ Éternel, vous ses saints; car rien ne manque à ceux qui le craignent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Les lionceaux souffrent disette, et ont faim; mais ceux qui cherchent l’ Éternel ne manquent d’aucun bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Venez, fils, écoutez-moi: je vous enseignerai la crainte de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Qui est l’homme qui prenne plaisir à la vie [et] qui aime les jours pour voir du bien?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Garde ta langue du mal, et tes lèvres de proférer la tromperie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Retire-toi du mal, et fais le bien; cherche la paix, et poursuis-la.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Les yeux de l’ Éternel [regardent] vers les justes, et ses oreilles sont [ouvertes] à leur cri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'La face de l’ Éternel est contre ceux qui font le mal, pour retrancher de la terre leur mémoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, '[Les justes] crient, et l’ Éternel entend, et il les délivre de toutes leurs détresses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'L’ Éternel est près de ceux qui ont le cœur brisé, et il sauve ceux qui ont l’esprit abattu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Les maux du juste sont en grand nombre; mais l’ Éternel le délivre de tous:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Il garde tous ses os, pas un d’eux n’est cassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Le mal fera mourir le méchant; et ceux qui haïssent le juste en porteront la peine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 23, 'L’ Éternel rachète l’âme de ses serviteurs; et aucun de ceux qui se confient en lui ne sera tenu pour coupable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'De David. Éternel! conteste contre ceux qui contestent contre moi; fais la guerre à ceux qui me font la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Saisis l’écu et le bouclier, et lève-toi à mon secours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Tire la lance, et barre le chemin au-devant de ceux qui me poursuivent! Dis à mon âme: Je suis ton salut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Que ceux qui cherchent ma vie soient honteux et confus; que ceux qui complotent mon malheur se retirent en arrière et soient confondus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Qu’ils soient comme la balle devant le vent, et que l’ange de l’ Éternel les chasse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Que leur chemin soit ténèbres et lieux glissants, et que l’ange de l’ Éternel les poursuive!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Car, sans cause, ils ont préparé secrètement pour moi leur filet; sans cause, ils ont creusé une fosse pour mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Qu’une ruine qu’il n’a pas connue vienne sur lui, et que son filet qu’il a caché le prenne: qu’il y tombe, pour sa ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Et mon âme s’égaiera en l’ Éternel, elle se réjouira en son salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Tous mes os diront: Éternel! qui est comme toi, qui délivres l’affligé de celui qui est plus fort que lui, et l’affligé et le pauvre de celui qui les pille?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Des témoins violents se lèvent, ils m’interrogent sur des choses que je n’ai pas connues;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Ils m’ont rendu le mal pour le bien: mon âme est dans l’abandon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Mais moi, quand ils ont été malades, je me vêtais d’un sac; j’humiliais mon âme dans le jeûne, et ma prière retournait dans mon sein.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'J’ai marché comme si ç’avait été mon compagnon, mon frère; triste, je me suis courbé comme celui qui mène deuil pour sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Mais, dans mon adversité, ils se sont réjouis et se sont rassemblés; les calomniateurs se sont rassemblés contre moi, et je ne l’ai pas su; ils m’ont déchiré et n’ont pas cessé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Avec d’impies parasites moqueurs ils ont grincé des dents contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Seigneur! jusques à quand regarderas-tu? Retire mon âme de leurs destructions, mon unique, des jeunes lions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Je te célébrerai dans la grande congrégation, je te louerai au milieu d’un grand peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Que ceux qui sont à tort mes ennemis ne se réjouissent pas de moi; que ceux qui me haïssent sans cause ne clignent pas l’œil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Car ils ne parlent pas de paix; mais ils méditent des tromperies contre les hommes paisibles du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Et ils ont élargi leur bouche contre moi; ils ont dit: Ha ha! ha ha! notre œil l’a vu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Tu l’as vu, Éternel! ne garde pas le silence: Seigneur! ne t’éloigne pas de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Éveille-toi, réveille-toi, pour me faire droit, mon Dieu et Seigneur, pour soutenir ma cause.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Juge-moi selon ta justice, ô Éternel, mon Dieu! et qu’ils ne se réjouissent pas à mon sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Qu’ils ne disent pas dans leur cœur: Ha ha! [voilà] notre désir! Qu’ils ne disent pas: Nous l’avons englouti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Que ceux qui se réjouissent de mon malheur soient tous ensemble honteux et confus; que ceux qui s’élèvent orgueilleusement contre moi soient couverts de honte et de confusion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Qu’ils exultent et qu’ils se réjouissent ceux qui sont affectionnés à ma justice; et qu’ils disent continuellement: Magnifié soit l’ Éternel qui prend plaisir à la paix de son serviteur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Et ma langue redira ta justice, ta louange, tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Au chef de musique. Du serviteur de l’ Éternel. De David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'La transgression du méchant dit, au-dedans de mon cœur, qu’il n’y a point de crainte de Dieu devant ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Car il se flatte à ses propres yeux quand son iniquité se présente pour être haïe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Les paroles de sa bouche sont iniquité et tromperie; il s’est désisté d’être sage, de faire le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Il médite la vanité sur son lit; il se tient sur un chemin qui n’est pas bon; il n’a point en horreur le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Éternel, ta bonté est dans les cieux, ta fidélité [atteint] jusqu’aux nues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Ta justice est comme de hautes montagnes; tes jugements sont un grand abîme. Éternel, tu sauves l’homme et la bête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Combien est précieuse ta bonté, ô Dieu! Aussi les fils des hommes se réfugient sous l’ombre de tes ailes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Ils seront abondamment rassasiés de la graisse de ta maison, et tu les abreuveras au fleuve de tes délices;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Car par-devers toi est la source de la vie, en ta lumière nous verrons la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Continue ta bonté à ceux qui te connaissent, et ta justice à ceux qui sont droits de cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Que le pied de l’orgueil ne m’atteigne pas, et que la main des méchants ne me chasse pas loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 13, 'Là sont tombés les ouvriers d’iniquité; ils ont été renversés, et n’ont pu se relever.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'De David. Ne t’irrite pas à cause de ceux qui font le mal, ne sois pas jaloux de ceux qui pratiquent l’iniquité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'car bientôt, comme l’herbe, ils seront fauchés, et, comme l’herbe verte, ils se faneront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Confie-toi en l’ Éternel et pratique le bien; habite le pays, et repais-toi de fidélité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'et fais tes délices de l’ Éternel: et il te donnera les demandes de ton cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Remets ta voie sur l’ Éternel, et confie-toi en lui; et lui, il agira,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'et il produira ta justice comme la lumière, et ton droit comme le plein midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Demeure tranquille, [appuyé] sur l’ Éternel, et attends-toi à lui. Ne t’irrite pas à cause de celui qui prospère dans son chemin, à cause de l’homme qui vient à bout de ses desseins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Laisse la colère et abandonne le courroux; ne t’irrite pas, au moins pour faire le mal:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'car ceux qui font le mal seront retranchés, et ceux qui s’attendent à l’ Éternel, ceux-là posséderont le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Encore un peu de temps, et le méchant ne sera plus; et tu considéreras son lieu, et il n’y sera plus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'et les débonnaires posséderont le pays, et feront leurs délices d’une abondance de paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Le méchant complote contre le juste, et grince des dents contre lui:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'le Seigneur se rira de lui, car il voit que son jour vient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Les méchants ont tiré l’épée et ont bandé leur arc, pour faire tomber l’affligé et le pauvre, pour égorger ceux qui marchent dans la droiture:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'leur épée entrera dans leur cœur, et leurs arcs seront brisés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Mieux vaut le peu du juste que l’abondance de beaucoup de méchants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'car les bras des méchants seront brisés, mais l’ Éternel soutient les justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'L’ Éternel connaît les jours de ceux qui sont intègres, et leur héritage sera pour toujours:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'ils ne seront pas confus au mauvais temps, et ils seront rassasiés aux jours de la famine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Car les méchants périront, et les ennemis de l’ Éternel comme la graisse des agneaux; ils s’en iront, comme la fumée ils s’en iront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Le méchant emprunte, et ne rend pas; mais le juste use de grâce, et donne:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'car ceux qui sont bénis de lui posséderont le pays; mais ceux qui sont maudits de lui seront retranchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Par l’ Éternel les pas de l’homme sont affermis, et il prend plaisir à sa voie:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 's’il tombe, il ne sera pas entièrement abattu; car l’ Éternel lui soutient la main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'J’ai été jeune, et je suis vieux, et je n’ai pas vu le juste abandonné, ni sa semence cherchant du pain:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'il use de grâce tout le jour, et il prête; et sa semence sera en bénédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Retire-toi du mal, et fais le bien, et demeure pour toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'car l’ Éternel aime la droiture, et il n’abandonnera pas ses saints: ils seront gardés à toujours, mais la semence des méchants sera retranchée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Les justes posséderont le pays, et ils l’habiteront à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'La bouche du juste profère la sagesse, et sa langue parle la droiture;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'la loi de son Dieu est dans son cœur, ses pas ne chancelleront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Le méchant épie le juste, et cherche à le faire mourir:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'l’ Éternel ne l’abandonnera pas entre ses mains, et ne le condamnera pas, quand il sera jugé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Attends-toi à l’ Éternel, et garde sa voie; et il t’élèvera afin que tu possèdes le pays: quand les méchants seront retranchés, tu le verras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'J’ai vu le méchant puissant, et s’étendant comme un arbre vert croissant dans son lieu natal;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'mais il passa, et voici, il n’était plus; et je l’ai cherché, et il ne s’est plus trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Prends garde à l’homme intègre, et regarde l’homme droit, car la fin d’un [tel] homme est la paix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'mais les transgresseurs seront détruits ensemble; la fin des méchants, c’est d’être retranché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Mais le salut des justes vient de l’ Éternel; il est leur force au temps de la détresse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'et l’ Éternel les aidera et les délivrera; il les délivrera des méchants et les sauvera, car ils se sont confiés en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Psaume de David, pour faire souvenir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Éternel! ne me reprends pas dans ta colère, et ne me châtie pas dans ta fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Car tes flèches ont pénétré en moi, et ta main est descendue sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Il n’y a rien d’entier en ma chair, à cause de ton indignation; point de paix dans mes os, à cause de mon péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Car mes iniquités ont passé sur ma tête; comme un pesant fardeau, elles sont trop pesantes pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Mes plaies sont fétides, elles coulent, à cause de ma folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Je suis accablé et extrêmement courbé; tout le jour je marche dans le deuil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Car mes reins sont pleins d’inflammation, et il n’y a rien d’entier dans ma chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Je suis languissant et extrêmement brisé; je rugis dans le frémissement de mon cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Seigneur! tout mon désir est devant toi, et mon gémissement ne t’est point caché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mon cœur bat fort, ma force m’a abandonné, et la lumière de mes yeux aussi n’est plus avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Ceux qui m’aiment, et mes compagnons, se tiennent loin de ma plaie, et mes proches se tiennent à distance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Et ceux qui cherchent ma vie me tendent des pièges, et ceux qui cherchent mon mal parlent de malheurs et disent des tromperies tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Et moi, comme un sourd, je n’entends pas, et, comme un muet, je n’ouvre pas la bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Je suis devenu comme un homme qui n’entend point et dans la bouche duquel il n’y a pas de réplique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Car je m’attends à toi, Éternel! Toi, tu répondras, Seigneur, mon Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Car j’ai dit: Qu’ils ne se réjouissent pas à mon sujet! Quand mon pied chancelle, ils s’élèvent orgueilleusement contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Car je suis prêt à boiter, et ma douleur est toujours devant moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Car je déclarerai mon iniquité; je suis en peine pour mon péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Et mes ennemis sont vivants, ils sont forts, et ceux qui me haïssent sans motif sont nombreux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Et ceux qui me rendent le mal pour le bien sont mes adversaires, parce que je poursuis ce qui est bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Éternel! ne m’abandonne point; mon Dieu! ne t’éloigne pas de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 23, 'Hâte-toi de me secourir, Seigneur, mon salut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Au chef de musique, à Jeduthun. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'J’ai dit: Je prendrai garde à mes voies, afin que je ne pèche point par ma langue; je garderai ma bouche avec une muselière pendant que le méchant est devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'J’ai été muet, dans le silence; je me suis tu à l’égard du bien; et ma douleur a été excitée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Mon cœur s’est échauffé au-dedans de moi; dans ma méditation le feu s’est allumé, j’ai parlé de ma langue:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Éternel! fais-moi connaître ma fin, et la mesure de mes jours, ce qu’elle est; je saurai combien je suis fragile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Voici, tu m’as donné des jours comme la largeur d’une main, et ma durée est comme un rien devant toi. Certainement, tout homme qui se tient debout n’est que vanité. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Certainement l’homme se promène parmi ce qui n’a que l’apparence; certainement il s’agite en vain; il amasse [des biens], et il ne sait qui les recueillera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Et maintenant, qu’est-ce que j’attends, Seigneur? Mon attente est en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Délivre-moi de toutes mes transgressions; ne me livre pas à l’opprobre de l’insensé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Je suis resté muet, je n’ai pas ouvert la bouche, car c’est toi qui l’as fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Retire de dessus moi ta plaie: je suis consumé par les coups de ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Quand tu châties un homme, en le corrigeant à cause de l’iniquité, tu consumes comme la teigne sa beauté; certainement, tout homme n’est que vanité. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Écoute ma prière, ô Éternel! et prête l’oreille à mon cri; ne sois pas sourd à mes larmes, car je suis un étranger, un hôte, chez toi, comme tous mes pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 14, 'Détourne tes regards de moi, et que je retrouve ma force, avant que je m’en aille et que je ne sois plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, '*Au chef de musique. De David. Psaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'J’ai attendu patiemment l’ Éternel; et il s’est penché vers moi, et a entendu mon cri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Il m’a fait monter hors du puits de la destruction, hors d’un bourbier fangeux; et il a mis mes pieds sur un roc, il a établi mes pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Et il a mis dans ma bouche un cantique nouveau, la louange de notre Dieu. Plusieurs le verront et craindront, et se confieront en l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Bienheureux l’homme qui a mis en l’ Éternel sa confiance, et ne s’est pas tourné vers les orgueilleux et ceux qui se détournent vers le mensonge!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Tu as multiplié, toi, Éternel mon Dieu, tes œuvres merveilleuses et tes pensées envers nous; on ne peut les arranger devant toi. Si je veux les déclarer et les dire, – elles sont trop nombreuses pour les raconter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Au sacrifice et à l’offrande de gâteau tu n’as pas pris plaisir: tu m’as creusé des oreilles; tu n’as pas demandé d’holocauste ni de sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Alors j’ai dit: Voici, je viens; il est écrit de moi dans le rouleau du livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'C’est mes délices, ô mon Dieu, de faire ce qui est ton bon plaisir, et ta loi est au-dedans de mes entrailles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'J’ai annoncé la justice dans la grande congrégation; voici, je n’ai point retenu mes lèvres, Éternel! tu le sais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Je n’ai point caché ta justice au-dedans de mon cœur; j’ai parlé de ta fidélité et de ton salut; je n’ai point celé ta bonté et ta vérité dans la grande congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Toi, Éternel! ne retiens pas loin de moi tes compassions; que ta bonté et ta vérité me gardent continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Car des maux sans nombre m’ont entouré; mes iniquités m’ont atteint, et je ne puis les regarder; elles sont plus nombreuses que les cheveux de ma tête, et mon cœur m’a abandonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Qu’il te plaise, ô Éternel! de me délivrer. Éternel! hâte-toi de me secourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Que ceux qui cherchent mon âme pour la détruire soient tous ensemble honteux et confondus; qu’ils se retirent en arrière et soient confus, ceux qui prennent plaisir à mon malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Que ceux qui disent de moi: Ha ha! ha ha! soient désolés, en récompense de leur honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Que tous ceux qui te cherchent s’égaient et se réjouissent en toi; que ceux qui aiment ton salut disent continuellement: Magnifié soit l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 18, 'Et moi, je suis affligé et pauvre: le Seigneur pense à moi. Tu es mon secours et celui qui me délivre. Mon Dieu! ne tarde pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Au chef de musique. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Bienheureux celui qui comprend le pauvre! Au mauvais jour, l’ Éternel le délivrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'L’ Éternel le gardera, et le conservera en vie: il sera rendu heureux sur la terre, et tu ne le livreras point à l’animosité de ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'L’ Éternel le soutiendra sur un lit de langueur. Tu transformeras tout son lit, quand il sera malade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'J’ai dit: Éternel! use de grâce envers moi, guéris mon âme, car j’ai péché contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Mes ennemis me souhaitent du mal: Quand mourra-t-il? Quand périra son nom?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Et si l’un vient me voir, il dit des paroles de fausseté; son cœur amasse par-devers lui l’iniquité;... il sort dehors, il en parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Tous ceux qui me haïssent chuchotent ensemble contre moi; ils imaginent du mal contre moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Quelque œuvre de Bélial est attachée à lui, et maintenant qu’il est couché, il ne se relèvera plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Mon intime ami aussi, en qui je me confiais, qui mangeait mon pain, a levé le talon contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Et toi, Éternel! use de grâce envers moi et relève-moi, et je [le] leur rendrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'À ceci je connais que tu prends plaisir en moi, c’est que mon ennemi ne triomphe pas de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Et moi, tu m’as maintenu dans mon intégrité, et tu m’as établi devant toi pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 14, 'Béni soit l’ Éternel, le Dieu d’Israël, de l’éternité jusqu’en éternité! Amen, oui, amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Au chef de musique. Instruction. Des fils de Coré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Comme le cerf brame après les courants d’eau, ainsi mon âme crie après toi, ô Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Mon âme a soif de Dieu, du ✶Dieu vivant. Quand viendrai-je et paraîtrai-je devant Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Mes larmes ont été mon pain, jour et nuit, quand on me disait tout le jour: Où est ton Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Je me souvenais de ces choses, et je répandais mon âme au-dedans de moi: comment j’allais avec la foule, et je m’avançais en leur compagnie, avec une voix de triomphe et de louange, jusqu’à la maison de Dieu,... une multitude en fête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Pourquoi es-tu abattue, mon âme, et es-tu agitée au-dedans de moi? Attends-toi à Dieu; car je le célébrerai encore: sa face est le salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Mon Dieu! mon âme est abattue au-dedans de moi; c’est pourquoi il me souvient de toi depuis le pays du Jourdain et des Hermons, de la montagne de Mitsear.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Un abîme appelle un autre abîme à la voix de tes cataractes; toutes tes vagues et tes flots ont passé sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'De jour, l’ Éternel commandera à sa bonté; et, de nuit, son cantique sera avec moi, ma prière au ✶Dieu de ma vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Je dirai à ✶Dieu, mon rocher: Pourquoi m’as-tu oublié? Pourquoi marché-je en deuil à cause de l’oppression de l’ennemi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Mes adversaires m’outragent comme un brisement dans mes os quand ils me disent tout le jour: Où est ton Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 12, 'Pourquoi es-tu abattue, mon âme? et pourquoi es-tu agitée au-dedans de moi? Attends-toi à Dieu; car je le célébrerai encore: il est le salut de ma face et mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Juge-moi, ô Dieu! et prends en main ma cause contre une nation sans piété; délivre-moi de l’homme trompeur et inique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Car toi, ô Dieu! tu es ma force; pourquoi m’as-tu rejeté? Pourquoi marché-je en deuil à cause de l’oppression de l’ennemi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Envoie ta lumière et ta vérité: elles me conduiront, elles m’amèneront à ta montagne sainte et à tes demeures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Et je viendrai à l’autel de Dieu, au ✶Dieu de l’allégresse de ma joie; et je te célébrerai sur la harpe, ô Dieu, mon Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Pourquoi es-tu abattue, mon âme? et pourquoi es-tu agitée au-dedans de moi? Attends-toi à Dieu; car je le célébrerai encore: il est le salut de ma face et mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, '*Au chef de musique. Des fils de Coré. Instruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Ô Dieu! nous avons entendu de nos oreilles, nos pères nous ont raconté l’œuvre que tu as opérée dans leurs jours, aux jours d’autrefois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Tu as, par ta main, dépossédé les nations, et tu as planté nos pères; tu as affligé les peuples et tu les as chassés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Car ce n’est point par leur épée qu’ils ont possédé le pays, et ce n’est pas leur bras qui les a sauvés; car c’est ta droite et ton bras et la lumière de ta face, parce que tu avais pris ton plaisir en eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'C’est toi qui es mon roi, ô Dieu! Commande le salut pour Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Avec toi, nous frapperons nos adversaires; par ton nom, nous foulerons ceux qui s’élèvent contre nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Car ce n’est pas en mon arc que je me confie, et mon épée ne me sauvera point;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Car tu nous as sauvés de nos adversaires, et tu rends confus ceux qui nous haïssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'En Dieu nous nous glorifierons tout le jour, et nous célébrerons ton nom à toujours. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Mais tu nous as rejetés et rendus confus, et tu ne sors plus avec nos armées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Tu nous as fait retourner en arrière devant l’adversaire, et ceux qui nous haïssent ont pillé pour eux-mêmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Tu nous as livrés comme des brebis [destinées] à être mangées, et tu nous as dispersés parmi les nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Tu as vendu ton peuple pour rien, et tu ne t’es pas agrandi par leur prix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Tu nous as mis en opprobre chez nos voisins, en risée et en raillerie auprès de nos alentours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Tu nous as mis comme proverbe parmi les nations, comme hochement de tête parmi les peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Tout le jour ma confusion est devant moi, et la honte de ma face m’a couvert,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'À cause de la voix de celui qui outrage et qui injurie, à cause de l’ennemi et du vengeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Tout cela nous est arrivé, et nous ne t’avons pas oublié, et nous n’avons pas été infidèles à ton alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Notre cœur ne s’est pas retiré en arrière, et nos pas n’ont point dévié de ton sentier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Quoique tu nous aies écrasés dans le lieu des chacals, et que tu nous aies couverts de l’ombre de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Si nous avions oublié le nom de notre Dieu, et étendu nos mains vers un ✶dieu étranger,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Dieu ne s’en enquerrait-il pas? car lui connaît les secrets du cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Mais, à cause de toi, nous sommes mis à mort tous les jours, nous sommes estimés comme des brebis de tuerie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Éveille-toi! Pourquoi dors-tu, Seigneur? Réveille-toi; ne nous rejette pas pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Pourquoi caches-tu ta face, [et] oublies-tu notre affliction et notre oppression?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Car notre âme est courbée jusque dans la poussière, notre ventre est attaché à la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 27, 'Lève-toi, aide-nous, et rachète-nous à cause de ta bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Au chef de musique. Sur Shoshannim. Des fils de Coré. Instruction. Un cantique du bien-aimé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Mon cœur bouillonne d’une bonne parole; je dis ce que j’ai composé au sujet du roi; ma langue est le style d’un écrivain habile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Tu es plus beau que les fils des hommes; la grâce est répandue sur tes lèvres: c’est pourquoi Dieu t’a béni à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Ceins ton épée sur ton côté, homme vaillant, [dans] ta majesté et ta magnificence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Et, prospérant dans ta magnificence, mène en avant ton char, à cause de la vérité et de la débonnaireté [et] de la justice; et ta droite t’enseignera des choses terribles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Tes flèches sont aiguës, – les peuples tomberont sous toi, – dans le cœur des ennemis du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Ton trône, ô Dieu, est pour toujours et à perpétuité; c’est un sceptre de droiture que le sceptre de ton règne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Tu as aimé la justice, et tu as haï la méchanceté; c’est pourquoi Dieu, ton Dieu, t’a oint d’une huile de joie au-dessus de tes compagnons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Tous tes vêtements sont myrrhe, aloès, et casse, [quand tu sors] des palais d’ivoire d’où ils t’ont réjoui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Des filles de rois ont été parmi tes dames d’honneur; la reine est à ta droite, parée d’or d’Ophir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Écoute, fille! et vois, et incline ton oreille; et oublie ton peuple et la maison de ton père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Et le roi désirera ta beauté, car il est ton seigneur: adore-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Et avec une offrande, la fille de Tyr, les plus riches du peuple rechercheront ta faveur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'La fille du roi est tout gloire, dans l’intérieur [du palais]; son vêtement est de broderies d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Elle sera amenée au roi en vêtements de brocart; des vierges qui la suivent, ses compagnes, te seront amenées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Elles te seront amenées avec joie et allégresse, elles entreront dans le palais du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Au lieu de tes pères, tu auras tes fils; tu les établiras pour princes dans tout le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 18, 'Je rappellerai ton nom dans toutes les générations; c’est pourquoi les peuples te célébreront à toujours et à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Au chef de musique. Des fils de Coré. Sur Alamoth. Chant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Dieu est notre refuge et notre force, un secours dans les détresses, toujours facile à trouver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'C’est pourquoi nous ne craindrons point, quand la terre serait transportée de sa place, et que les montagnes seraient remuées [et jetées] au cœur des mers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Quand ses eaux mugiraient, qu’elles écumeraient, [et] que les montagnes seraient ébranlées à cause de son emportement. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Il y a un fleuve dont les ruisseaux réjouissent la ville de Dieu, le saint lieu des demeures du Très-haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Dieu est au milieu d’elle; elle ne sera pas ébranlée. Dieu la secourra au lever du matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Les nations s’agitent tumultueusement, les royaumes sont ébranlés; il a fait entendre sa voix: la terre s’est fondue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'L’ Éternel des armées est avec nous; le Dieu de Jacob nous est une haute retraite. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Venez, voyez les actes de l’ Éternel, quelles dévastations il a faites sur la terre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Il a fait cesser les guerres jusqu’au bout de la terre; il brise les arcs et met en pièces les lances, il brûle les chariots par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Tenez-vous tranquilles, et sachez que je suis Dieu: je serai exalté parmi les nations, je serai exalté sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 12, 'L’ Éternel des armées est avec nous; le Dieu de Jacob nous est une haute retraite. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Au chef de musique. Des fils de Coré. Psaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Battez des mains, vous, tous les peuples; poussez des cris de joie vers Dieu avec une voix de triomphe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Car l’ Éternel, le Très-haut, est terrible, un grand roi sur toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Il assujettit les peuples sous nous, et les peuplades sous nos pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Il nous a choisi notre héritage, la gloire de Jacob qu’il a aimé. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Dieu est monté avec un chant de triomphe, l’ Éternel avec la voix de la trompette.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Chantez Dieu, chantez; chantez à notre roi, chantez;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Car Dieu est le roi de toute la terre; chantez avec intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Dieu règne sur les nations, Dieu est assis sur le trône de sa sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 10, 'Ceux d’entre les peuples qui sont de bonne volonté se sont réunis au peuple du Dieu d’Abraham; car les boucliers de la terre sont à Dieu: il est fort exalté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Cantique. Psaume des fils de Coré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'L’ Éternel est grand et fort digne de louange dans la ville de notre Dieu, dans sa montagne sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Belle dans son élévation, la joie de toute la terre, est la montagne de Sion, aux côtés du nord, la ville du grand roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Dieu est connu dans ses palais pour une haute retraite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Car voici, les rois se sont assemblés, ils ont passé outre ensemble:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Ils ont vu, – ils ont été étonnés; ils ont été troublés, ils se sont enfuis consternés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Là, le tremblement les a saisis, une angoisse comme [celle de] la femme qui enfante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Par le vent d’orient tu as brisé les navires de Tarsis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Comme nous avons entendu, ainsi nous l’avons vu dans la ville de l’ Éternel des armées, dans la ville de notre Dieu: Dieu l’établit pour toujours. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Ô Dieu! nous avons pensé à ta bonté, au milieu de ton temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Ô Dieu! comme ton nom, ainsi est ta louange, jusqu’aux bouts de la terre; ta droite est pleine de justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Que la montagne de Sion se réjouisse, que les filles de Juda s’égaient, à cause de tes jugements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Faites le tour de Sion, et faites-en le circuit; comptez ses tours,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Faites attention à son rempart, considérez ses palais, afin que vous le racontiez à la génération à venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 15, 'Car ce Dieu est notre Dieu, pour toujours et à perpétuité; il sera notre guide jusqu’à la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, '*Au chef de musique. Des fils de Coré. Psaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Vous, tous les peuples, entendez ceci; vous, tous les habitants du monde, prêtez l’oreille;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Fils des gens du commun, et fils des grands, le riche et le pauvre pareillement:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Ma bouche dira des paroles de sagesse, et la méditation de mon cœur sera [pleine] d’intelligence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Je prêterai l’oreille au discours sentencieux, j’exposerai mon énigme sur la harpe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Pourquoi craindrais-je au mauvais jour, quand l’iniquité de ceux qui me talonnent m’enveloppe?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Ils se confient en leurs biens et se glorifient en l’abondance de leurs richesses...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Un homme ne pourra en aucune manière racheter son frère, ni donner à Dieu sa rançon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, '(Car précieux est le rachat de leur âme, et il faut qu’il y renonce à jamais,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Afin qu’il vive encore, à toujours, [et] qu’il ne voie pas la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Car il voit que les sages meurent, que le sot et l’insensé périssent pareillement et laissent leurs biens à d’autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Leur [pensée] intérieure est que leurs maisons durent à toujours, et leurs demeures de génération en génération; ils appellent les terres de leur propre nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Pourtant l’homme qui est en honneur ne dure pas; il est semblable aux bêtes qui périssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Ce chemin qu’ils tiennent est leur folie; mais ceux qui viennent après eux prennent plaisir aux propos de leur bouche. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Ils gisent dans le shéol comme des brebis: la mort se repaît d’eux, et au matin les hommes droits domineront sur eux; et leur beauté va se consumer dans le shéol, sans qu’ils aient plus de demeure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Mais Dieu rachètera mon âme de la puissance du shéol, car il me prendra. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Ne crains pas quand un homme s’enrichit, quand la gloire de sa maison s’accroît;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Car, lorsqu’il mourra, il n’emportera rien; sa gloire ne descendra pas après lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Quoique pendant sa vie il bénisse son âme (et on te louera, si tu te fais du bien),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Il s’en ira jusqu’à la génération de ses pères: ils ne verront jamais la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 21, 'L’homme qui est en honneur et n’a point d’intelligence, est comme les bêtes qui périssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, '*Psaume d’Asaph. Le [Dieu] Fort, Dieu, l’ Éternel, a parlé, et a appelé la terre, du soleil levant jusqu’au soleil couchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'De Sion, perfection de la beauté, Dieu a fait luire sa splendeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Notre Dieu viendra, et il ne se taira point; un feu dévorera devant lui, et autour de lui tourbillonnera la tempête;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Il appellera les cieux d’en haut, et la terre, pour juger son peuple:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Assemblez-moi mes saints, qui ont fait alliance avec moi par [un] sacrifice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Et les cieux déclareront sa justice, car Dieu lui-même est juge. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Écoute, mon peuple, et je parlerai; [écoute], Israël, et je témoignerai au milieu de toi. Moi, je suis Dieu, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Je ne te reprendrai pas à cause de tes sacrifices ou de tes holocaustes, qui ont été continuellement devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Je ne prendrai pas de taureau de ta maison, ni de boucs de tes parcs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Car tout animal de la forêt est à moi, les bêtes sur mille montagnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Je connais tous les oiseaux des montagnes, et ce qui se meut par les champs est à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Si j’avais faim, je ne te le dirais pas; car le monde est à moi, et tout ce qu’il contient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Mangerais-je la chair des gros taureaux, et boirais-je le sang des boucs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Sacrifie à Dieu la louange, et acquitte tes vœux envers le Très-haut,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Et invoque-moi au jour de la détresse: je te délivrerai, et tu me glorifieras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Mais Dieu dit au méchant: Qu’as-tu à faire de redire mes statuts, et de prendre mon alliance dans ta bouche?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Toi qui hais la correction, et qui as jeté mes paroles derrière toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Si tu as vu un voleur, tu t’es plu avec lui, et ta portion est avec les adultères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Tu livres ta bouche au mal, et ta langue trame la tromperie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Tu t’assieds, tu parles contre ton frère, tu diffames le fils de ta mère:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Tu as fait ces choses-là, et j’ai gardé le silence; – tu as estimé que j’étais véritablement comme toi; [mais] je t’en reprendrai, et je te les mettrai devant les yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Considérez donc cela, vous qui oubliez ✝Dieu, de peur que je ne déchire, et qu’il n’y ait personne qui délivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Celui qui sacrifie la louange me glorifie; et à celui qui règle sa voie je ferai voir le salut de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, '*Au chef de musique. Psaume de David;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'lorsque Nathan le prophète vint à lui, après qu’il fut entré vers Bath-Shéba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Use de grâce envers moi, ô Dieu! selon ta bonté; selon la grandeur de tes compassions, efface mes transgressions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Lave-moi pleinement de mon iniquité, et purifie-moi de mon péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Car je connais mes transgressions, et mon péché est continuellement devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Contre toi, contre toi seul, j’ai péché, et j’ai fait ce qui est mauvais à tes yeux; afin que tu sois justifié quand tu parles, trouvé pur quand tu juges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Voici, j’ai été enfanté dans l’iniquité, et dans le péché ma mère m’a conçu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Voici, tu veux la vérité dans l’homme intérieur, et tu me feras comprendre la sagesse dans le secret [de mon cœur].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Purifie-moi du péché avec de l’hysope, et je serai pur; lave-moi, et je serai plus blanc que la neige.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Fais-moi entendre l’allégresse et la joie, afin que les os que tu as brisés se réjouissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Cache ta face de mes péchés, et efface toutes mes iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Crée-moi un cœur pur, ô Dieu! et renouvelle au-dedans de moi un esprit droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Ne me renvoie pas de devant ta face, et ne m’ôte pas l’esprit de ta sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Rends-moi la joie de ton salut, et qu’un esprit de franche volonté me soutienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'J’enseignerai tes voies aux transgresseurs, et des pécheurs se retourneront vers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Délivre-moi de la coulpe du sang, ô Dieu, Dieu de mon salut! Ma langue chantera hautement ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Seigneur, ouvre mes lèvres, et ma bouche annoncera ta louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Car tu ne prends pas plaisir aux sacrifices, autrement j’en donnerais; l’holocauste ne t’est point agréable:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Les sacrifices de Dieu sont un esprit brisé. Ô Dieu! tu ne mépriseras pas un cœur brisé et humilié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 20, 'Fais du bien, dans ta faveur, à Sion; bâtis les murs de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 21, 'Alors tu prendras plaisir aux sacrifices de justice, à l’holocauste et au sacrifice [qu’on brûle] tout entier; alors on offrira des taureaux sur ton autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, '*Au chef de musique; pour instruire. De David;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'lorsque Doëg, l’Édomite, rapporta à Saül et lui dit: David est venu dans la maison d’Akhimélec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Pourquoi te glorifies-tu du mal, homme fort? La bonté de ✶Dieu subsiste de jour en jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Ta langue trame des malheurs, pratiquant la fausseté, comme un rasoir affilé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Tu as aimé le mal plus que le bien, le mensonge plus que la parole de justice. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Tu as aimé toutes les paroles de destruction, langue trompeuse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Aussi ✶Dieu te détruira pour toujours; il te saisira et t’arrachera de ta tente, et il te déracinera de la terre des vivants. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Et les justes verront, et craindront, et ils se riront de lui:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Voilà l’homme qui n’a pas pris Dieu pour sa force, mais qui s’est confié en la multitude de ses richesses, et qui se fortifiait dans son avidité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 10, 'Mais moi, je suis dans la maison de Dieu comme un olivier vert. Je me confierai en la bonté de Dieu, pour toujours et à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 11, 'Je te célébrerai à jamais, parce que tu l’as fait; et je m’attendrai à ton nom, car il est bon devant tes saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Au chef de musique. Sur Mahalath; pour instruire. De David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'L’insensé a dit dans son cœur: Il n’y a point de Dieu. Ils se sont corrompus, et ils ont rendu abominable la perversité; il n’y a personne qui fasse le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Dieu a regardé des cieux sur les fils des hommes, pour voir s’il y a quelqu’un qui soit intelligent, qui recherche Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Ils se sont tous retirés, ils se sont tous ensemble corrompus; il n’y a personne qui fasse le bien, non pas même un seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Les ouvriers d’iniquité n’ont-ils aucune connaissance? Ils dévorent mon peuple, comme on mange du pain; ils n’invoquent point Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Là où il n’y avait pas de sujet de frayeur ils ont été saisis de frayeur; car Dieu disperse les os de ceux qui se campent contre toi. Tu les as rendus confus, parce que Dieu les a méprisés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 7, 'Oh! si de Sion le salut d’Israël était venu! Quand Dieu rétablira les captifs de son peuple, Jacob s’égaiera, Israël se réjouira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Au chef de musique. Sur Neguinoth; pour instruire. De David;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'lorsque les Ziphiens vinrent, et dirent à Saül: David ne se tient-il pas caché auprès de nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Ô Dieu! sauve-moi par ton nom, et fais-moi justice par ta puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Ô Dieu! écoute ma prière, prête l’oreille aux paroles de ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Car des étrangers se sont levés contre moi, et des hommes violents cherchent ma vie; ils n’ont pas mis Dieu devant eux. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Voici, Dieu est mon secours; le Seigneur est entre ceux qui soutiennent mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Il rendra le mal à ceux qui me pressent: selon ta vérité, détruis-les.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 8, 'De franche volonté je t’offrirai des sacrifices; je célébrerai ton nom, ô Éternel! car cela est bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 9, 'Car il m’a délivré de toute détresse, et mon œil a vu [son plaisir] en mes ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Au chef de musique. Sur Neguinoth; pour instruire. De David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Prête l’oreille, ô Dieu, à ma prière, et ne te cache pas de ma supplication.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Écoute-moi, et réponds-moi; je m’agite dans ma plainte et je me lamente,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'À cause de la voix de l’ennemi [et] devant l’oppression du méchant; car ils font tomber sur moi l’iniquité, et me poursuivent avec passion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Mon cœur est dans l’angoisse au-dedans de moi, et des frayeurs mortelles sont tombées sur moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'La crainte et le tremblement sont venus sur moi, et un frisson de terreur m’a couvert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Et j’ai dit: Oh! si j’avais des ailes comme une colombe, je m’envolerais et je demeurerais tranquille;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Voici, je m’enfuirais loin, et je me logerais au désert. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Je me hâterais de m’échapper loin du vent de tempête, loin de l’ouragan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Engloutis-[les], Seigneur! divise leur langue; car j’ai vu la violence et les querelles dans la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Jour et nuit ils font la ronde sur ses murailles; et l’iniquité et le tourment sont au milieu d’elle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'La perversité est au milieu d’elle, et l’oppression et la fraude ne s’éloignent pas de ses places.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Car ce n’est pas un ennemi qui m’a outragé, alors je l’aurais supporté; ce n’est point celui qui me hait qui s’est élevé orgueilleusement contre moi, alors je me serais caché de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Mais c’est toi, un homme comme moi, mon conseiller et mon ami:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Nous avions ensemble de douces communications; nous allions avec la foule dans la maison de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Que la mort les saisisse! qu’ils descendent vivants dans le shéol! Car la malice est dans leur demeure, au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Moi, je crie à Dieu; et l’ Éternel me sauvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Le soir, et le matin, et à midi, je médite et je me lamente; et il entendra ma voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Il a mis en paix mon âme, la rachetant de la guerre qu’on me fait, car ils étaient plusieurs autour de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Dieu a entendu, et il les accablera: il demeure dès les jours d’autrefois; (Sélah)... car il n’y a point de changement en eux, et ils ne craignent pas Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, '[Le méchant] a étendu ses mains sur ceux qui sont en paix avec lui; il a profané son alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, '[Les paroles de] sa bouche étaient lisses comme le beurre, mais la guerre était dans son cœur; ses paroles étaient douces comme l’huile, mais elles sont des épées nues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Rejette ton fardeau sur l’ Éternel, et il te soutiendra; il ne permettra jamais que le juste soit ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 24, 'Et toi, ô Dieu! tu les feras descendre dans le puits de la destruction: les hommes de sang et de fourbe n’atteindront pas la moitié de leurs jours; mais moi, je me confierai en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Au chef de musique. Sur Jonath-Élem-Rekhokim. De David. Mictam; quand les Philistins le prirent dans Gath.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Use de grâce envers moi, ô Dieu! car l’homme voudrait m’engloutir; me faisant la guerre tout le jour, il m’opprime.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Mes ennemis voudraient tout le jour m’engloutir; car il y en a beaucoup qui me font la guerre, avec hauteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Au jour où je craindrai, je me confierai en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'En Dieu, je louerai sa parole; en Dieu je me confie: je ne craindrai pas; que me fera la chair?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Tout le jour ils tordent mes paroles; toutes leurs pensées sont contre moi en mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Ils s’assemblent, ils se cachent, ils observent mes pas, car ils guettent mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Échapperont-ils par l’iniquité? Dans ta colère, ô Dieu, précipite les peuples!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Tu comptes mes allées et mes venues; mets mes larmes dans tes vaisseaux; ne sont-elles pas dans ton livre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Alors mes ennemis retourneront en arrière, au jour où je crierai; je sais cela, car Dieu est pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'En Dieu, je louerai sa parole; en l’ Éternel, je louerai sa parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'En Dieu je me confie: je ne craindrai pas; que me fera l’homme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Les vœux que je t’ai faits sont sur moi, ô Dieu! je te rendrai des louanges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 14, 'Car tu as délivré mon âme de la mort: [ne garderais-tu] pas mes pieds de broncher, pour que je marche devant Dieu dans la lumière des vivants?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Au chef de musique. Al-Tashkheth. De David. Mictam; quand il fuyait devant Saül, dans la caverne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Use de grâce envers moi, ô Dieu! use de grâce envers moi; car en toi mon âme se réfugie, et sous l’ombre de tes ailes je me réfugie, jusqu’à ce que les calamités soient passées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Je crierai au Dieu Très-haut, à ✶Dieu qui mène [tout] à bonne fin pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Il a envoyé des cieux, et m’a sauvé; il a couvert de honte celui qui veut m’engloutir. Sélah. Dieu a envoyé sa bonté et sa vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Mon âme est au milieu de lions; je suis couché parmi ceux qui soufflent des flammes, – les fils des hommes, dont les dents sont des lances et des flèches, et la langue une épée aiguë.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Élève-toi, ô Dieu! au-dessus des cieux; que ta gloire soit au-dessus de toute la terre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Ils ont préparé un filet pour mes pas, mon âme se courbait; ils ont creusé devant moi une fosse, ils sont tombés dedans. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Mon cœur est affermi, ô Dieu! mon cœur est affermi; je chanterai et je psalmodierai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Éveille-toi, mon âme! Éveillez-vous, luth et harpe! Je m’éveillerai à l’aube du jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Je te célébrerai parmi les peuples, ô Seigneur! je chanterai tes louanges parmi les peuplades;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Car ta bonté est grande jusqu’aux cieux, et ta vérité jusqu’aux nues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 12, 'Élève-toi, ô Dieu! au-dessus des cieux; que ta gloire soit au-dessus de toute la terre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Au chef de musique. Al-Tashkheth. De David. Mictam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Est-ce que vraiment la justice se tait? Prononcez-vous [ce qui est juste]? Vous, fils des hommes, jugez-vous avec droiture?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Bien plutôt, dans le cœur, vous commettez des iniquités; dans le pays, vous pesez la violence de vos mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Les méchants se sont égarés dès la matrice; ils errent dès le ventre, parlant le mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Ils ont un venin semblable au venin d’un serpent, comme l’aspic sourd qui se bouche l’oreille,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Qui n’entend pas la voix des charmeurs, du sorcier expert en sorcelleries.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Ô Dieu! dans leur bouche brise leurs dents; Éternel! arrache les grosses dents des jeunes lions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Qu’ils se fondent comme des eaux qui s’écoulent! S’il ajuste ses flèches, qu’elles soient comme cassées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Qu’ils soient comme une limace qui va se fondant! Comme l’avorton d’une femme, qu’ils ne voient pas le soleil!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Avant que vos chaudières aient senti les épines, vertes ou enflammées, le tourbillon les emportera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Le juste se réjouira quand il verra la vengeance; il lavera ses pieds dans le sang du méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 12, 'Et l’homme dira: Certainement il y a un fruit pour le juste, certainement il y a un Dieu qui juge sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Au chef de musique. Al-Tashkheth. De David. Mictam; quand Saül envoya, et qu’on surveilla sa maison, afin de le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Délivre-moi de mes ennemis, ô mon Dieu! protège-moi contre ceux qui s’élèvent contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Délivre-moi des ouvriers d’iniquité, et sauve-moi des hommes de sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Car voici, ils ont dressé des embûches contre ma vie, des hommes forts se sont assemblés contre moi, – non pour ma transgression, ni pour mon péché, ô Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Sans qu’il y ait d’iniquité [en moi] ils courent et se préparent; éveille-toi pour venir à ma rencontre, et regarde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Et toi, Éternel, Dieu des armées! Dieu d’Israël! réveille-toi pour visiter toutes les nations; n’use de grâce envers aucun de ceux qui trament l’iniquité. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Ils reviennent le soir, ils hurlent comme un chien, et font le tour de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Voici, de leur bouche ils vomissent l’injure, des épées sont sur leurs lèvres; car, [disent-ils], qui [nous] entend?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Mais toi, Éternel, tu te riras d’eux, tu te moqueras de toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, '[À cause de] sa force, je regarderai à toi; car Dieu est ma haute retraite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Le Dieu qui use de bonté envers moi me préviendra; Dieu me fera voir [mon plaisir] en mes ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Ne les tue pas, de peur que mon peuple ne l’oublie; fais-les errer par ta puissance, et abats-les, ô Seigneur, notre bouclier!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, '[À cause du] péché de leur bouche, – la parole de leurs lèvres, – qu’ils soient pris dans leur orgueil, et à cause de la malédiction et des mensonges qu’ils profèrent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Consume-[les] en ta fureur, consume-[les], et qu’ils ne soient plus, et qu’ils sachent que Dieu domine en Jacob jusqu’aux bouts de la terre. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Et ils reviendront le soir, ils hurleront comme un chien, et feront le tour de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Ils errent çà et là pour trouver à manger; ils y passeront la nuit s’ils ne sont pas rassasiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Et moi je chanterai ta force, et, dès le matin, je célébrerai avec joie ta bonté; car tu m’as été une haute retraite et un refuge au jour où j’étais dans la détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 18, 'Ma force! à toi je chanterai; car Dieu est ma haute retraite, le Dieu qui use de bonté envers moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Au chef de musique. Sur Shushan. Témoignage. Mictam. De David; pour enseigner;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'quand il fit la guerre contre les Syriens de Naharaïm, et contre les Syriens de Tsoba, et que Joab revint et frappa les Édomites dans la vallée du Sel, au nombre de 12 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Ô Dieu! tu nous as rejetés, tu nous as dispersés, tu t’es irrité; ramène-nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Tu as fait trembler la terre, tu l’as fendue: répare ses brèches, car elle chancelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Tu as fait voir à ton peuple des choses dures; tu nous as donné à boire un vin d’étourdissement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Tu as donné une bannière à ceux qui te craignent, pour la déployer à cause de la vérité, (Sélah)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Afin que tes bien-aimés soient délivrés. Sauve par ta droite, et réponds-moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Dieu a parlé dans sa sainteté: je me réjouirai; je partagerai Sichem et je mesurerai la vallée de Succoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Galaad est à moi, et Manassé est à moi, et Éphraïm est la force de ma tête; Juda est mon législateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Moab est le bassin où je me lave; sur Édom j’ai jeté ma sandale. Philistie, pousse des cris de triomphe à mon sujet!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Qui me conduira dans la ville forte? Qui me mènera jusqu’en Édom?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Ne sera-ce pas toi, ô Dieu, qui nous as rejetés, et qui n’es pas sorti, ô Dieu, avec nos armées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 13, 'Donne-nous du secours pour sortir de détresse; car la délivrance qui vient de l’homme est vaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 14, 'Par Dieu nous ferons des actes de valeur, et c’est lui qui foulera nos adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Au chef de musique. Sur Neguinoth. De David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Ô Dieu! écoute mon cri, sois attentif à ma prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Du bout de la terre je crierai à toi, dans l’accablement de mon cœur; tu me conduiras sur un rocher qui est trop haut pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Car tu m’as été un refuge, une forte tour, de devant l’ennemi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Je séjournerai dans ta tente à toujours; je me réfugierai sous l’abri de tes ailes. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Car toi, ô Dieu! tu as entendu mes vœux, tu m’as donné l’héritage de ceux qui craignent ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Tu ajouteras des jours aux jours du roi; ses années seront comme des générations et des générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Il habitera pour toujours devant Dieu. Donne la bonté et la vérité, afin qu’elles le gardent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 9, 'Ainsi je chanterai ton nom à perpétuité, acquittant mes vœux jour par jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Au chef de musique. Sur Jeduthun. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Sur Dieu seul mon âme se repose paisiblement; de lui vient mon salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Lui seul est mon rocher et mon salut, ma haute retraite; je ne serai pas beaucoup ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Jusques à quand vous jetterez-vous sur un homme, [et chercherez]-vous tous à le renverser comme une muraille qui penche, comme un mur qui va crouler?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Ils ne consultent que pour [le] précipiter de son élévation; ils prennent plaisir au mensonge; ils bénissent de leur bouche, et intérieurement ils maudissent. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Mais toi, mon âme, repose-toi paisiblement sur Dieu; car mon attente est en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Lui seul est mon rocher et mon salut, ma haute retraite: je ne serai pas ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Sur Dieu [reposent] mon salut et ma gloire; le rocher de ma force, mon refuge, est en Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Peuple, – confiez-vous en lui en tout temps, répandez votre cœur devant lui: Dieu est notre refuge. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Les fils des gens du commun ne sont que vanité, les fils des grands ne sont que mensonge: placés dans la balance, ils montent ensemble plus [légers] que la vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'N’ayez pas confiance dans l’oppression, et ne mettez pas un vain espoir dans la rapine; si les biens augmentent, n’y mettez pas votre cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Dieu a parlé une fois;... deux fois j’ai entendu ceci, que la force est à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 13, 'Et à toi, Seigneur, est la bonté; car toi tu rends à chacun selon son œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Psaume de David; quand il était dans le désert de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Ô Dieu! tu es mon ✶Dieu; je te cherche au point du jour; mon âme a soif de toi, ma chair languit après toi, dans une terre aride et altérée, sans eau,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Pour voir ta force et ta gloire, comme je t’ai contemplé dans le lieu saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Car ta bonté est meilleure que la vie; mes lèvres te loueront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Ainsi je te bénirai durant ma vie, j’élèverai mes mains en ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Mon âme est rassasiée comme de moelle et de graisse, et ma bouche [te] louera avec des lèvres qui chantent de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Quand je me souviens de toi sur mon lit, je médite de toi durant les veilles de la nuit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Car tu as été mon secours, et à l’ombre de tes ailes je chanterai de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Mon âme s’attache à toi pour te suivre, ta droite me soutient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Mais ceux qui cherchent ma vie pour sa ruine entreront dans les parties inférieures de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'On les livrera à la puissance de l’épée, ils seront la portion des renards.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 12, 'Mais le roi se réjouira en Dieu, [et] quiconque jure par lui se glorifiera; car la bouche de ceux qui parlent faussement sera fermée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Au chef de musique. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Écoute, ô Dieu! ma voix, quand je me plains; garde ma vie de la crainte de l’ennemi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Cache-moi loin du conseil secret des méchants, et de la foule tumultueuse des ouvriers d’iniquité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Qui ont aiguisé leur langue comme une épée, ajusté leur flèche, – une parole amère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Pour tirer de leurs cachettes contre celui qui est intègre: soudain ils tirent sur lui, et ils ne craignent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Ils s’affermissent dans de mauvaises choses, ils s’entretiennent ensemble pour cacher des pièges; ils disent: Qui le verra?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Ils méditent des méchancetés: Nous avons fini; la machination est ourdie. L’intérieur de chacun, et le cœur, est profond.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Mais Dieu tirera sa flèche contre eux: soudain ils sont blessés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Et leur langue les fera tomber les uns par-dessus les autres; tous ceux qui les voient s’enfuiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Et tous les hommes craindront, et ils raconteront les actes de Dieu, et considéreront son œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 11, 'Le juste se réjouira en l’ Éternel et se confiera en lui, et tous ceux qui sont droits de cœur se glorifieront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Au chef de musique. Psaume de David. Cantique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Ô Dieu! la louange t’attend dans le silence en Sion, et le vœu te sera payé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Ô toi qui écoutes la prière! toute chair viendra à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Les iniquités ont prévalu sur moi; nos transgressions, toi tu les pardonneras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Bienheureux celui que tu as choisi et que tu fais approcher: il habitera tes parvis. Nous serons rassasiés du bien de ta maison, de ton saint temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Tu nous répondras par des choses terribles de justice, ô Dieu de notre salut, toi qui es la confiance de tous les bouts de la terre, et des régions lointaines de la mer!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Toi qui as établi les montagnes par ta force, qui es ceint de puissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Qui apaises le tumulte des mers, le tumulte de leurs flots, et l’agitation des peuplades.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Et ceux qui habitent aux bouts [de la terre] craindront à la vue de tes prodiges; tu fais chanter de joie les sorties du matin et du soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Tu as visité la terre, tu l’as abreuvée, tu l’enrichis abondamment: le ruisseau de Dieu est plein d’eau. Tu prépares les blés, quand tu l’as ainsi préparée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Tu arroses ses sillons, tu aplanis ses mottes, tu l’amollis par des ondées, tu bénis son germe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Tu couronnes l’année de ta bonté, et tes sentiers distillent la graisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Ils distillent sur les pâturages du désert, et les collines se ceignent d’allégresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 14, 'Les prairies se revêtent de menu bétail, et les plaines sont couvertes de froment: elles poussent des cris de triomphe; oui, elles chantent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Au chef de musique. Cantique. Psaume. Poussez des cris de joie vers Dieu, toute la terre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Chantez la gloire de son nom, rendez glorieuse sa louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Dites à Dieu: Que tes œuvres sont terribles! Tes ennemis se soumettent à toi, à cause de la grandeur de ta force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Toute la terre se prosternera devant toi, et chantera tes louanges; elle chantera ton nom. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Venez, et voyez les œuvres de Dieu: il est terrible dans ses actes envers les fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Il changea la mer en terre sèche; ils passèrent le fleuve à pied: là nous nous sommes réjouis en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Il domine par sa puissance pour toujours; ses yeux observent les nations. Que les rebelles ne s’élèvent pas! Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Peuples, bénissez notre Dieu, et faites entendre la voix de sa louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'C’est lui qui a conservé notre âme en vie, et il n’a pas permis que nos pieds soient ébranlés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Car, ô Dieu! tu nous as éprouvés, tu nous as affinés comme on affine l’argent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Tu nous as fait entrer dans le filet, tu as mis un fardeau accablant sur nos reins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Tu as fait passer les hommes sur notre tête; nous sommes entrés dans le feu et dans l’eau, et tu nous as fait sortir dans un lieu spacieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'J’entrerai dans ta maison avec des holocaustes; j’acquitterai envers toi mes vœux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Ce que mes lèvres ont proféré, et que ma bouche a dit dans ma détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Je t’offrirai des holocaustes de bêtes grasses, avec l’encens des béliers; je sacrifierai du gros bétail avec des boucs. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Venez, écoutez, vous tous qui craignez Dieu, et je raconterai ce qu’il a fait pour mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'J’ai crié à lui de ma bouche, et il a été exalté par ma langue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Si j’avais regardé l’iniquité dans mon cœur, le Seigneur ne m’aurait pas écouté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Cependant Dieu m’a écouté; il a fait attention à la voix de ma prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Béni soit Dieu, qui n’a point rejeté ma prière, ni retiré d’avec moi sa bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Au chef de musique. Sur Neguinoth. Psaume. Cantique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Que Dieu use de grâce envers nous et nous bénisse, qu’il fasse lever la lumière de sa face sur nous, (Sélah)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Pour que ta voie soit connue sur la terre, ton salut parmi toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Que les peuples te célèbrent, ô Dieu! que tous les peuples te célèbrent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Que les peuplades se réjouissent, et chantent de joie; car tu jugeras les peuples avec droiture, et tu conduiras les peuplades sur la terre. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Que les peuples te célèbrent, ô Dieu! que tous les peuples te célèbrent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'La terre donnera son fruit; Dieu, notre Dieu, nous bénira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 8, 'Dieu nous bénira, et tous les bouts de la terre le craindront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Au chef de musique. De David. Psaume. Cantique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Que Dieu se lève, que ses ennemis soient dispersés, et que ceux qui le haïssent s’enfuient devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Comme la fumée est dissipée, tu les dissiperas; comme la cire se fond devant le feu, les méchants périront devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Mais les justes se réjouiront, ils exulteront en la présence de Dieu et s’égaieront avec joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Chantez à Dieu, chantez son nom, dressez un chemin à celui qui passe comme à cheval par les déserts: son nom est Jah; réjouissez-vous devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Dieu, dans sa demeure sainte, est le père des orphelins et le juge des veuves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Dieu fait habiter en famille ceux qui étaient seuls; il fait sortir ceux qui étaient enchaînés, pour qu’ils jouissent de l’abondance; mais les rebelles demeurent dans une terre aride.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Ô Dieu! quand tu sortis devant ton peuple, quand tu marchas dans le désert, (Sélah)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'La terre trembla; les cieux aussi distillèrent des eaux devant Dieu, ce Sinaï [trembla] devant Dieu, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Ô Dieu! tu répandis une pluie abondante sur ton héritage, et, quand il était las, tu l’établis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Ton troupeau a habité là; dans ta bonté, tu préparas [tes biens] pour l’affligé, ô Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Le Seigneur donna la parole: grande fut la foule des femmes qui répandirent la bonne nouvelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Les rois des armées s’enfuirent; ils s’enfuirent, et celle qui demeurait dans la maison partagea le butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Quoique vous ayez été couchés au milieu des étables, vous serez [comme] les ailes d’une colombe couverte d’argent, et dont le plumage est comme l’or vert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Quand le Tout-puissant y dispersa des rois, [le pays] devint blanc comme la neige du Tsalmon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Une montagne de Basan est la montagne de Dieu, une montagne à plusieurs sommets, une montagne de Basan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Pourquoi, montagnes à plusieurs sommets, regardez-vous avec jalousie la montagne que Dieu a désirée pour y habiter? Oui, l’ Éternel y demeurera pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Les chars de Dieu sont par vingt mille, par milliers redoublés; le Seigneur est au milieu d’eux: c’est un Sinaï en sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Tu es monté en haut, tu as emmené captive la captivité; tu as reçu des dons dans l’homme, et même [pour] les rebelles, afin que Jah, Dieu, ait une demeure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Béni soit le Seigneur, qui, de jour en jour, nous comble [de ses dons], le ✶Dieu qui nous sauve. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Notre ✶Dieu est un ✶Dieu de salut; et c’est à l’ Éternel, le Seigneur, de faire sortir de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Mais Dieu brisera la tête de ses ennemis, le crâne chevelu de ceux qui marchent dans leurs iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Le Seigneur a dit: Je ramènerai [les miens] de Basan, je les ramènerai des profondeurs de la mer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Afin que tu trempes ton pied dans le sang de [tes] ennemis, [et] que la langue de tes chiens en ait sa part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Ils ont vu ta marche, ô Dieu! la marche de mon ✶Dieu, de mon roi, dans le lieu saint:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Les chanteurs allaient devant, ensuite les joueurs d’instruments à cordes, au milieu des jeunes filles jouant du tambourin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Dans les congrégations bénissez Dieu, le Seigneur, – vous qui êtes de la source d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Là est Benjamin, le petit, qui domine sur eux; les princes de Juda, leur troupe; les princes de Zabulon, les princes de Nephthali.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Ton Dieu a commandé ta force. Établis en force, ô Dieu, ce que tu as fait pour nous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'À cause de ton temple, à Jérusalem, les rois t’apporteront des présents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Tance la bête des roseaux, l’assemblée des forts taureaux, avec les veaux des peuples: [chacun] se prosterne, offrant des lingots d’argent. Disperse les peuples qui trouvent leurs délices dans la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Des grands viendront d’Égypte; Cush s’empressera d’étendre ses mains vers Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Royaumes de la terre, chantez à Dieu, chantez les louanges du Seigneur, (Sélah)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'À celui qui passe comme à cheval sur les cieux, sur les cieux d’ancienneté! Voici, il fait retentir sa voix, une voix puissante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Attribuez la force à Dieu: sa majesté est sur Israël, et sa force dans les nuées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 36, 'Tu es terrible, ô Dieu! du milieu de tes sanctuaires. Le ✶Dieu d’Israël, c’est lui qui donne la puissance et la force à son peuple. Béni soit Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, '*Au chef de musique. Sur Shoshannim. De David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Sauve-moi, ô Dieu! car les eaux [me] sont entrées jusque dans l’âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Je suis enfoncé dans une boue profonde, et il n’y a pas où prendre pied; je suis entré dans la profondeur des eaux, et le courant me submerge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Je suis las de crier; mon gosier est desséché; mes yeux se consument, pendant que j’attends mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Ceux qui me haïssent sans cause sont plus nombreux que les cheveux de ma tête; ceux qui voudraient me perdre, qui sont à tort mes ennemis, sont puissants; ce que je n’avais pas ravi, je l’ai alors rendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Ô Dieu! tu connais ma folie, et mes fautes ne te sont pas cachées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Que ceux qui s’attendent à toi ne soient pas rendus honteux à cause de moi, Seigneur, Éternel des armées! Que ceux qui te cherchent ne soient pas rendus confus à cause de moi, ô Dieu d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Car à cause de toi j’ai porté l’opprobre, la confusion a couvert mon visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Je suis devenu un étranger à mes frères, et un inconnu aux fils de ma mère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Car le zèle de ta maison m’a dévoré, et les outrages de ceux qui t’outragent sont tombés sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Et j’ai pleuré, mon âme était dans le jeûne; et cela m’a été en opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'J’ai pris aussi un sac pour mon vêtement, et je leur suis devenu un proverbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Ceux qui sont assis dans la porte parlent contre moi, et je sers de chanson aux buveurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Mais, pour moi, ma prière s’adresse à toi, Éternel, en un temps agréé. – Ô Dieu! selon la grandeur de ta bonté, réponds-moi selon la vérité de ton salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Délivre-moi du bourbier, et que je n’y enfonce point; que je sois délivré de ceux qui me haïssent et des profondeurs des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Que le courant des eaux ne me submerge pas, et que la profondeur ne m’engloutisse pas, et que le puits ne ferme pas sa gueule sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Réponds-moi, ô Éternel! car ta gratuité est bonne; selon la grandeur de tes compassions, tourne-toi vers moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Et ne cache pas ta face de ton serviteur, car je suis en détresse. Hâte-toi, réponds-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Approche-toi de mon âme, sois son rédempteur; rachète-moi à cause de mes ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Toi, tu connais mon opprobre, et ma honte, et ma confusion: tous mes adversaires sont devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'L’opprobre m’a brisé le cœur, et je suis accablé; et j’ai attendu que [quelqu’un] ait compassion [de moi], mais il n’y a eu personne,... et des consolateurs, mais je n’en ai pas trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Ils ont mis du fiel dans ma nourriture, et, dans ma soif, ils m’ont abreuvé de vinaigre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Que leur table soit un piège devant eux, et que ce qui tend à la prospérité leur soit un filet;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Que leurs yeux soient obscurcis de sorte qu’ils ne voient pas, et fais continuellement chanceler leurs reins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Répands sur eux ton indignation, et que l’ardeur de ta colère les atteigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Que leur demeure soit désolée, qu’il n’y ait personne qui habite dans leurs tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Car ils persécutent celui que toi tu as frappé, et parlent pour la douleur de ceux que tu as blessés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Mets iniquité sur leur iniquité, et qu’ils n’entrent pas en ta justice;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Qu’ils soient effacés du livre de vie, et qu’ils ne soient pas inscrits avec les justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Mais pour moi, je suis affligé et dans la douleur: que ton salut, ô Dieu, m’élève en un lieu de sûreté!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Je louerai le nom de Dieu dans un cantique, et je le magnifierai par ma louange;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Et cela plaira plus à l’ Éternel qu’un taureau, un bœuf qui a des cornes et l’ongle divisé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Les débonnaires le verront, ils se réjouiront; vous qui cherchez Dieu, votre cœur vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Car l’ Éternel écoute les pauvres, et ne méprise pas ses prisonniers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Les cieux et la terre le loueront, les mers et tout ce qui se meut en elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Car Dieu sauvera Sion, et bâtira les villes de Juda; et on y habitera, et on la possédera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 37, 'Et la semence de ses serviteurs l’héritera, et ceux qui aiment son nom y demeureront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Au chef de musique. De David; pour faire souvenir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Hâte-toi, ô Dieu, de me délivrer! [hâte-toi], ô Éternel, de me secourir!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Que ceux qui cherchent ma vie soient honteux et confondus; qu’ils se retirent en arrière et soient confus, ceux qui prennent plaisir à mon malheur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Qu’ils retournent en arrière à cause de leur honte, ceux qui disent: Ha ha! ha ha!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Que tous ceux qui te cherchent s’égaient et se réjouissent en toi; et que ceux qui aiment ton salut disent continuellement: Magnifié soit Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 6, 'Et moi, je suis affligé et pauvre; ô Dieu, hâte-toi vers moi! Tu es mon secours et celui qui me délivre; Éternel, ne tarde pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'En toi, Éternel! j’ai mis ma confiance: que je ne sois jamais confus!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Dans ta justice, délivre-moi et fais que j’échappe; incline ton oreille vers moi et sauve-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sois pour moi un rocher d’habitation, afin que j’y entre continuellement; tu as donné commandement de me sauver, car tu es mon rocher et mon lieu fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mon Dieu! fais-moi échapper de la main du méchant, de la main de l’injuste et de l’oppresseur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Car toi tu es mon attente, Seigneur Éternel! ma confiance dès ma jeunesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Je me suis appuyé sur toi dès le ventre; c’est toi qui m’as tiré hors des entrailles de ma mère: tu es le sujet continuel de ma louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Je suis pour plusieurs comme un prodige; mais toi, tu es mon fort refuge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Ma bouche est pleine de ta louange [et] de ta magnificence, tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Ne me rejette pas au temps de [ma] vieillesse; ne m’abandonne pas quand ma force est consumée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Car mes ennemis parlent contre moi, et ceux qui guettent mon âme consultent ensemble,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Disant: Dieu l’a abandonné; poursuivez-le et saisissez-le, car il n’y a personne qui le délivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Ô Dieu! ne te tiens pas loin de moi; mon Dieu, hâte-toi de me secourir!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Qu’ils soient honteux, qu’ils soient consumés, ceux qui sont ennemis de mon âme; qu’ils soient couverts d’opprobre et de confusion, ceux qui cherchent mon malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Mais moi, j’attendrai continuellement, et je redirai sans cesse toutes tes louanges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Ma bouche racontera tout le jour ta justice [et] ton salut, car je n’en connais pas l’énumération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'J’irai dans la puissance du Seigneur Éternel; je ferai mention de ta justice, de la tienne seule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Ô Dieu! tu m’as enseigné dès ma jeunesse; et jusqu’ici j’ai annoncé tes merveilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Et aussi, jusqu’à la vieillesse et aux cheveux blancs, ô Dieu! ne m’abandonne pas, jusqu’à ce que j’annonce ton bras à [cette] génération, ta puissance à tous ceux qui viendront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Et ta justice, ô Dieu! est haut élevée. Toi qui as fait de grandes choses, ô Dieu! qui est comme toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Toi qui nous as fait voir de nombreuses et amères détresses, tu nous redonneras la vie, et tu nous feras remonter hors des profondeurs de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Tu multiplieras ma grandeur, et tu te tourneras, tu me consoleras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Aussi, mon Dieu, je te célébrerai avec le luth, [je louerai] ta vérité; je chanterai tes louanges avec la harpe, ô Saint d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Mes lèvres, et mon âme, que tu as rachetée, exulteront quand je chanterai tes louanges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Ma langue aussi redira tout le jour ta justice; car ils seront honteux, car ils seront confondus, ceux qui cherchent mon malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, '*Au sujet de Salomon. Ô Dieu! donne tes jugements au roi, et ta justice au fils du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Il jugera ton peuple en justice, et tes affligés avec droiture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Les montagnes porteront la paix au peuple, et les coteaux, – par la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Il fera justice aux affligés du peuple, il sauvera les fils du pauvre, et il brisera l’oppresseur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Ils te craindront, de génération en génération, tant que dureront le soleil et la lune.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Il descendra comme la pluie sur un pré fauché, comme les gouttes d’une ondée sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'En ses jours le juste fleurira, et il y aura abondance de paix, jusqu’à ce qu’il n’y ait plus de lune.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Et il dominera d’une mer à l’autre mer, et depuis le fleuve jusqu’aux bouts de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Les habitants du désert se courberont devant lui, et ses ennemis lécheront la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Les rois de Tarsis et des îles lui apporteront des présents, les rois de Sheba et de Seba lui présenteront des dons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Oui, tous les rois se prosterneront devant lui, toutes les nations le serviront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Car il délivrera le pauvre qui crie [à lui], et l’affligé qui n’a pas de secours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Il aura compassion du misérable et du pauvre, et il sauvera les âmes des pauvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Il rachètera leur âme de l’oppression et de la violence, et leur sang sera précieux à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Et il vivra, et on lui donnera de l’or de Sheba, et on priera pour lui continuellement; et on le bénira tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Il y aura abondance de froment sur la terre, sur le sommet des montagnes; son fruit bruira comme le Liban; et les [hommes] de la ville fleuriront comme l’herbe de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Son nom sera pour toujours; son nom se perpétuera devant le soleil, et on se bénira en lui: toutes les nations le diront bienheureux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Béni soit l’ Éternel, Dieu, le Dieu d’Israël, qui seul fait des choses merveilleuses!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Et béni soit le nom de sa gloire, à toujours; et que toute la terre soit pleine de sa gloire! Amen! oui, amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Les prières de David, fils d’Isaï, sont finies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Psaume d’Asaph. Certainement Dieu est bon envers Israël, envers ceux qui sont purs de cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Et pour moi, il s’en est fallu de peu que mes pieds ne m’aient manqué, – d’un rien que mes pas n’aient glissé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Car j’ai porté envie aux arrogants, en voyant la prospérité des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Car [il n’y a] pas de tourments dans leur mort, et leur corps est gras;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Ils n’ont point de part aux peines des humains, et ils ne sont pas frappés avec les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'C’est pourquoi l’orgueil les entoure comme un collier, la violence les couvre comme un vêtement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Les yeux leur sortent de graisse; ils dépassent les imaginations de leur cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Ils sont railleurs et parlent méchamment d’opprimer; ils parlent avec hauteur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Ils placent leur bouche dans les cieux, et leur langue se promène sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'C’est pourquoi son peuple se tourne de ce côté-là, et on lui verse l’eau à plein bord,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Et ils disent: Comment ✶Dieu connaîtrait-il, et y aurait-il de la connaissance chez le Très-haut?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Voici, ceux-ci sont des méchants, et ils prospèrent dans le monde, ils augmentent leurs richesses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Certainement c’est en vain que j’ai purifié mon cœur et que j’ai lavé mes mains dans l’innocence:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'J’ai été battu tout le jour, et mon châtiment [revenait] chaque matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Si j’avais dit: Je parlerai ainsi, voici, j’aurais été infidèle à la génération de tes fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Quand j’ai médité pour connaître cela, ce fut un travail pénible à mes yeux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Jusqu’à ce que je sois entré dans les sanctuaires de ✶Dieu ...: j’ai compris leur fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Certainement tu les places en des lieux glissants, tu les fais tomber en ruines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Comme ils sont détruits en un moment! Ils sont péris, consumés par la frayeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Comme un songe, quand on s’éveille, tu mépriseras, Seigneur, leur image, lorsque tu t’éveilleras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, '*Quand mon cœur s’aigrissait, et que je me tourmentais dans mes reins,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'J’étais alors stupide et je n’avais pas de connaissance; j’étais avec toi comme une brute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Mais je suis toujours avec toi: tu m’as tenu par la main droite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Tu me conduiras par ton conseil, et, après la gloire, tu me recevras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Qui ai-je dans les cieux? Et je n’ai eu de plaisir sur la terre qu’en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Ma chair et mon cœur sont consumés; Dieu est le rocher de mon cœur, et mon partage pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Car voici, ceux qui sont loin de toi périront; tu détruiras tous ceux qui se prostituent en se détournant de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mais, pour moi, m’approcher de Dieu est mon bien; j’ai mis ma confiance dans le Seigneur, l’ Éternel, pour raconter tous tes faits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Pour instruire. D’Asaph. Pourquoi, ô Dieu, [nous] as-tu rejetés pour toujours, [et] ta colère fume-t-elle contre le troupeau de ta pâture?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Souviens-toi de ton assemblée, que tu as acquise autrefois, que tu as rachetée pour être la portion de ton héritage, – de la montagne de Sion, où tu as habité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Élève tes pas vers les ruines perpétuelles; l’ennemi a tout saccagé dans le lieu saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Tes adversaires rugissent au milieu des lieux assignés pour ton service; ils ont mis leurs signes pour signes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Un homme se faisait connaître quand il élevait la hache dans l’épaisseur de la forêt;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Et maintenant, avec des cognées et des marteaux, ils brisent ses sculptures toutes ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Ils ont mis le feu à ton sanctuaire, ils ont profané par terre la demeure de ton nom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Ils ont dit en leur cœur: Détruisons-les tous ensemble. Ils ont brûlé tous les lieux assignés [pour le service] de ✶Dieu dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Nous ne voyons plus nos signes; il n’y a plus de prophète, et il n’y a personne avec nous qui sache jusques à quand.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Jusques à quand, ô Dieu! l’adversaire dira-t-il des outrages? L’ennemi méprisera-t-il ton nom à jamais?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Pourquoi détournes-tu ta main, et ta droite? [Tire-la] de ton sein: détruis!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Et Dieu est d’ancienneté mon roi, opérant des délivrances au milieu de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Tu as fendu la mer par ta puissance, tu as brisé les têtes des monstres sur les eaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Tu as écrasé les têtes du léviathan, tu l’as donné pour pâture au peuple, – aux bêtes du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Tu as fait sortir la source et le torrent; tu as séché les grosses rivières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'À toi est le jour, à toi aussi la nuit; toi tu as établi la lune et le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Tu as posé toutes les bornes de la terre; l’été et l’hiver, c’est toi qui les as formés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Souviens-toi de ceci, que l’ennemi a outragé l’ Éternel! et qu’un peuple insensé a méprisé ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Ne livre pas à la bête sauvage l’âme de ta tourterelle; n’oublie pas à jamais la troupe de tes affligés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Regarde à l’alliance! Car les lieux ténébreux de la terre sont pleins d’habitations de violence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Que l’opprimé ne s’en retourne pas confus; que l’affligé et le pauvre louent ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Lève-toi, ô Dieu! plaide ta cause, souviens-toi des outrages que te fait tous les jours l’insensé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'N’oublie pas la voix de tes adversaires: le tumulte de ceux qui s’élèvent contre toi monte continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Au chef de musique. Al-Tashkheth. Psaume d’Asaph. Cantique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Nous te célébrons, ô Dieu! nous te célébrons, et ton nom est proche: tes merveilles le racontent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Quand je recevrai l’assemblée, je jugerai avec droiture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'La terre et tous ses habitants se sont fondus; moi, j’affermis ses piliers. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'J’ai dit à ceux qui se glorifient: Ne vous glorifiez pas; et aux méchants: N’élevez pas [votre] corne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'N’élevez pas en haut votre corne, ne parlez pas avec arrogance, d’un cou [roide].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Car ce n’est ni du levant, ni du couchant, ni du midi, que vient l’élévation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Car c’est Dieu qui juge; il abaisse l’un, et élève l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Car une coupe est dans la main de l’ Éternel, et elle écume de vin; elle est pleine de mixtion, et il en verse: oui, tous les méchants de la terre en suceront la lie, ils la boiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Mais moi, je raconterai [ces choses] à toujours; je chanterai au Dieu de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 11, 'Et toutes les cornes des méchants, je les abattrai; [mais] les cornes des justes seront élevées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Au chef de musique. Sur Neguinoth. Psaume d’Asaph. Cantique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Dieu est connu en Juda, son nom est grand en Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Et son tabernacle est en Salem, et son domicile en Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Là, il a brisé les éclairs de l’arc, le bouclier, et l’épée, et la bataille. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Tu es plus resplendissant, plus magnifique que les montagnes de la rapine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Les forts de cœur ont été dépouillés, ils ont dormi leur sommeil, et aucun des hommes vaillants n’a trouvé ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Quand tu les as tancés, ô Dieu de Jacob! chars et chevaux se sont endormis profondément.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Tu es terrible, toi; et qui est-ce qui subsistera devant toi, dès que ta colère [éclate]?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Tu fis entendre des cieux le jugement; la terre en eut peur, et se tint tranquille,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Quand tu te levas, ô Dieu, pour le jugement, pour sauver tous les débonnaires de la terre. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Car la colère de l’homme te louera; tu te ceindras du reste de la colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Vouez, et acquittez [vos vœux] envers l’ Éternel, votre Dieu; que tous ceux qui l’entourent apportent des présents au Redoutable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 13, 'Il retranchera l’esprit des princes, il est terrible aux rois de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Au chef de musique. Sur Jeduthun. D’Asaph. Psaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Ma voix s’adresse à Dieu, et je crierai; ma voix s’adresse à Dieu, et il m’écoutera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Au jour de ma détresse j’ai cherché le Seigneur; ma main était étendue durant la nuit et ne se lassait point; mon âme refusait d’être consolée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Je me souvenais de Dieu, et j’étais agité; je me lamentais, et mon esprit défaillait. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Tu tiens ouvertes mes paupières; je suis inquiet, et je ne parle pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Je pense aux jours d’autrefois, aux années des siècles passés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Je me souviens, de nuit, de mon cantique; je médite en mon cœur, et mon esprit cherche diligemment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Le Seigneur rejettera-t-il pour toujours? et ne montrera-t-il plus sa faveur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Sa bonté a-t-elle cessé pour toujours? Sa parole a-t-elle pris fin de génération en génération?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, '✶Dieu a-t-il oublié d’user de grâce? A-t-il enfermé ses miséricordes dans la colère? Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Et je dis: C’est ici mon infirmité; – [je me souviendrai des] années de la droite du Très-haut,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Je me souviendrai des œuvres de Jah; car je me souviendrai de tes merveilles d’autrefois,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Et je penserai à toute ton œuvre, et je méditerai tes actes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Ô Dieu! ta voie est dans le lieu saint. Où y a-t-il un ✶dieu grand comme Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Toi, tu es le ✶Dieu qui fais des merveilles; tu as fait connaître ta puissance parmi les peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Tu as racheté par [ton] bras ton peuple, les fils de Jacob et de Joseph. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Les eaux t’ont vu, ô Dieu! les eaux t’ont vu, elles ont tremblé; les abîmes aussi se sont émus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Les nuées ont versé des eaux, les nuages ont fait retentir une voix, et tes flèches se sont promenées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'La voix de ton tonnerre était dans le tourbillon, les éclairs ont illuminé le monde; la terre en a été émue et a tremblé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Ta voie est dans la mer, et tes sentiers dans les grandes eaux; et tes traces ne sont pas connues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 21, 'Tu as conduit ton peuple comme un troupeau, par la main de Moïse et d’Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Pour instruire. D’Asaph. Prête l’oreille à ma loi, mon peuple! inclinez vos oreilles aux paroles de ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'J’ouvrirai ma bouche en paraboles, j’annoncerai les énigmes [des jours] d’autrefois,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Que nous avons entendues et connues, et que nos pères nous ont racontées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Nous ne les cèlerons pas à leurs fils; nous raconterons à la génération à venir les louanges de l’ Éternel, et sa force, et ses merveilles qu’il a faites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Il a établi un témoignage en Jacob, et il a mis en Israël une loi qu’il a commandée à nos pères, pour qu’ils les fassent connaître à leurs fils,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Afin que la génération à venir, les fils qui naîtraient, les connaissent, [et] qu’ils se lèvent et les annoncent à leurs fils,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Et qu’ils mettent leur confiance en Dieu, et qu’ils n’oublient pas les œuvres de ✶Dieu, et qu’ils observent ses commandements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Et qu’ils ne soient pas, comme leurs pères, une génération indocile et rebelle, une génération qui n’a point affermi son cœur, et dont l’esprit n’a pas été fidèle à ✶Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Les fils d’Éphraïm, armés [et] tirant de l’arc, ont tourné le dos le jour du combat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Ils n’ont pas gardé l’alliance de Dieu, et ont refusé de marcher selon sa loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Et ils ont oublié ses actes et ses œuvres merveilleuses, qu’il leur avait fait voir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Il fit des merveilles devant leurs pères dans le pays d’Égypte, dans la campagne de Tsoan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Il fendit la mer, et les fit passer: il fit se dresser les eaux comme un monceau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Et il les conduisit, le jour par une nuée, et toute la nuit par une lumière de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Il fendit les rochers dans le désert, et les abreuva comme aux abîmes, abondamment;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Et il fit sortir des ruisseaux du rocher, et fit couler les eaux comme des fleuves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Et ils péchèrent de nouveau contre lui, irritant le Très-haut dans le désert;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Et ils tentèrent ✶Dieu dans leurs cœurs, en demandant de la viande selon leur désir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Et ils parlèrent contre Dieu; ils dirent: ✶Dieu pourrait-il dresser une table dans le désert?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Voici, il a frappé le rocher, et les eaux ont coulé, et des rivières ont débordé: pourrait-il aussi donner du pain, ou préparer de la chair à son peuple?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'C’est pourquoi l’ Éternel les entendit, et se mit en grande colère; et le feu s’alluma contre Jacob, et la colère aussi monta contre Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Car ils ne crurent pas Dieu, et ne se fièrent pas en son salut,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Bien qu’il ait commandé aux nuées d’en haut, et qu’il ait ouvert les portes des cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Et qu’il ait fait pleuvoir sur eux la manne pour manger, et qu’il leur ait donné le blé des cieux:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'L’homme mangea le pain des puissants; il leur envoya des vivres à satiété.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Il fit lever dans les cieux le vent d’orient, et il amena par sa puissance le vent du midi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Et il fit pleuvoir sur eux de la chair comme de la poussière, et, comme le sable des mers, des oiseaux ailés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Et il les fit tomber au milieu de leur camp, autour de leurs demeures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Et ils en mangèrent, et en furent abondamment rassasiés. Il leur envoya ce qu’ils convoitaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Ils ne s’étaient pas encore détournés de leur convoitise, leur viande était encore dans leur bouche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Que la colère de Dieu monta contre eux; et il tua de leurs hommes forts, et abattit les hommes d’élite d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Avec tout cela ils péchèrent encore, et ne crurent point par ses œuvres merveilleuses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Et il consuma leurs jours par la vanité, et leurs années par la frayeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'S’il les tuait, alors ils le recherchaient, et ils se retournaient, et cherchaient ✶Dieu dès le matin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Et ils se souvenaient que Dieu était leur rocher, et ✶Dieu, le Très-haut, leur rédempteur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Mais ils le flattaient de leur bouche et ils lui mentaient de leur langue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Et leur cœur n’était pas ferme envers lui, et ils ne furent pas fidèles dans son alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Mais lui, étant miséricordieux, pardonna l’iniquité et ne [les] détruisit pas; mais il détourna souvent sa colère, et n’éveilla pas toute sa fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Et il se souvint qu’ils étaient chair, un souffle qui passe et ne revient pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Que de fois ils l’irritèrent dans le désert, [et] le provoquèrent dans le lieu désolé!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Et ils recommencèrent et tentèrent ✶Dieu, et affligèrent le Saint d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Ils ne se souvinrent pas de sa main au jour où il les avait délivrés de l’oppresseur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Lorsqu’il mit ses signes en Égypte, et ses prodiges dans les campagnes de Tsoan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Et qu’il changea en sang leurs canaux et leurs courants d’eau, de sorte qu’ils n’en puissent pas boire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Il envoya contre eux des mouches qui les dévorèrent, et des grenouilles qui les détruisirent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Et il livra leurs fruits à la locuste, et leur travail à la sauterelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Il fit périr leurs vignes par la grêle, et leurs sycomores par les grêlons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Et il livra leur bétail à la grêle, et leurs troupeaux à la foudre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Il envoya sur eux l’ardeur de sa colère, la fureur, et l’indignation, et la détresse, une troupe d’anges de malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Il fraya un chemin à sa colère; il ne préserva pas leurs âmes de la mort, et livra leur vie à la peste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Et il frappa tout premier-né en Égypte, les prémices de la vigueur dans les tentes de Cham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Et il fit partir son peuple comme des brebis, et les mena comme un troupeau dans le désert;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Et il les conduisit sains et saufs, et ils furent sans crainte; et la mer couvrit leurs ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Et il les introduisit dans les confins de sa sainte [terre], cette montagne que sa droite s’est acquise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Et il chassa de devant eux les nations, et leur partagea un héritage, et fit habiter dans leurs tentes les tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Mais ils tentèrent et irritèrent le Dieu Très-haut, et ne gardèrent pas ses témoignages,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Et se retirèrent, et agirent infidèlement, comme leurs pères; ils tournèrent comme un arc trompeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Et ils le provoquèrent à colère par leurs hauts lieux, et l’émurent à jalousie par leurs images taillées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Dieu l’entendit, et se mit en grande colère, et il méprisa fort Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Et il abandonna la demeure de Silo, la tente où il avait habité parmi les hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Et il livra à la captivité sa force, et sa magnificence en la main de l’ennemi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Et il livra son peuple à l’épée, et se mit en grande colère contre son héritage:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Le feu dévora leurs jeunes hommes, et leurs vierges ne furent pas célébrées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Leurs sacrificateurs tombèrent par l’épée, et leurs veuves ne se lamentèrent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Alors le Seigneur s’éveilla comme un homme qui dort, et comme un homme puissant qui, [animé] par le vin, pousse des cris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Et il frappa ses ennemis par-derrière, il les livra à un opprobre éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Et il méprisa la tente de Joseph, et ne choisit pas la tribu d’Éphraïm;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Mais il choisit la tribu de Juda, la montagne de Sion qu’il aima.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Et il bâtit son sanctuaire comme des lieux très hauts, comme la terre qu’il a fondée pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Et il choisit David, son serviteur, et le prit des parcs des brebis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Il le fit venir d’auprès des brebis qui allaitent, pour paître Jacob, son peuple, et Israël, son héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Et il les fit paître selon l’intégrité de son cœur, et les conduisit par l’intelligence de ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Psaume d’Asaph. Ô Dieu! les nations sont entrées dans ton héritage; elles ont profané ton saint temple; elles ont mis Jérusalem en monceaux de pierres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Elles ont donné les cadavres de tes serviteurs en pâture aux oiseaux des cieux, la chair de tes saints aux bêtes de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Elles ont versé leur sang comme de l’eau tout autour de Jérusalem, et il n’y a eu personne pour les enterrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Nous avons été en opprobre à nos voisins, en risée et en raillerie auprès de nos alentours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Jusques à quand, ô Éternel? Seras-tu en colère à toujours? Ta jalousie brûlera-t-elle comme le feu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Verse ta fureur sur les nations qui ne t’ont pas connu, et sur les royaumes qui n’invoquent pas ton nom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Car on a dévoré Jacob, et on a dévasté sa demeure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Ne te souviens pas contre nous des iniquités anciennes; que tes compassions viennent en hâte au-devant de nous, car nous sommes devenus fort misérables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Aide-nous, ô Dieu de notre salut! à cause de la gloire de ton nom; et délivre-nous, et pardonne nos péchés, à cause de ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Pourquoi les nations diraient-elles: Où est leur Dieu? Qu’elle soit connue parmi les nations, devant nos yeux, la vengeance du sang de tes serviteurs qui a été versé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Que le gémissement du prisonnier vienne devant toi; selon la grandeur de ton bras garantis ceux qui sont voués à la mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Et rends à nos voisins sept fois dans leur sein l’opprobre qu’ils ont jeté sur toi, Seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Mais nous, ton peuple et le troupeau de ta pâture, nous te célébrerons à toujours; de génération en génération nous raconterons ta louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Au chef de musique. Sur Shoshannim. Témoignage d’Asaph. Psaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Berger d’Israël! prête l’oreille. Toi qui mènes Joseph comme un troupeau, toi qui es assis entre les chérubins, fais luire ta splendeur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Devant Éphraïm, et Benjamin, et Manassé, réveille ta puissance, et viens nous sauver!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Ô Dieu! ramène-nous; et fais luire ta face, et nous serons sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Éternel, Dieu des armées! jusques à quand ta colère fumera-t-elle contre la prière de ton peuple?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Tu leur as fait manger un pain de larmes, et tu les as abreuvés de larmes à pleine mesure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Tu as fait de nous un sujet de contestation pour nos voisins, et nos ennemis se moquent [de nous] entre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Ô Dieu des armées! ramène-nous; et fais luire ta face, et nous serons sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Tu as transporté d’Égypte un cep; tu as chassé les nations, et tu l’as planté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Tu as préparé une place devant lui, il a poussé des racines, et a rempli le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Les montagnes étaient couvertes de son ombre, et ses sarments étaient [comme] des cèdres de ✶Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Il étendait ses pampres jusqu’à la mer, et ses pousses jusqu’au fleuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Pourquoi as-tu rompu ses clôtures, de sorte que tous ceux qui passent le pillent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Le sanglier de la forêt le déchire, et les bêtes des champs le broutent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Ô Dieu des armées! retourne, je te prie; regarde des cieux, et vois, et visite ce cep,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Et la plante que ta droite a plantée, et le provin que tu avais fortifié pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Elle est brûlée par le feu, elle est coupée; ils périssent, parce que tu les tances.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Que ta main soit sur l’homme de ta droite, sur le fils de l’homme que tu as fortifié pour toi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Et nous ne nous retirerons pas de toi. Fais-nous revivre, et nous invoquerons ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 20, 'Éternel, Dieu des armées! ramène-nous; fais luire ta face, et nous serons sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Au chef de musique. Sur Guitthith. D’Asaph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Chantez joyeusement à Dieu, notre force; poussez des cris de joie vers le Dieu de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Entonnez le cantique, et faites résonner le tambourin, la harpe agréable, avec le luth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Sonnez de la trompette à la nouvelle lune, au temps fixé, au jour de notre fête;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Car c’est un statut pour Israël, une ordonnance du Dieu de Jacob:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Il l’établit comme un témoignage en Joseph, lorsqu’il sortit à travers le pays d’Égypte, où j’entendis une langue que je ne connaissais pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'J’ai retiré son épaule de dessous le fardeau, ses mains ont été déchargées des corbeilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Dans la détresse tu as crié, et je t’ai délivré; je t’ai répondu du lieu secret du tonnerre; je t’ai éprouvé auprès des eaux de Meriba. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Écoute, mon peuple, et je témoignerai au milieu de toi; Israël, oh! si tu voulais m’écouter!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Il n’y aura point au milieu de toi de ✶dieu étranger, et tu ne te prosterneras pas devant un ✶dieu de l’étranger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Moi, je suis l’ Éternel, ton Dieu, qui t’ai fait monter du pays d’Égypte; ouvre ta bouche toute grande, et je la remplirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Mais mon peuple n’a pas écouté ma voix, et Israël n’a pas voulu de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Alors je les ai abandonnés à l’obstination de leur cœur: ils ont marché selon leurs conseils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Oh! si mon peuple m’avait écouté! si Israël avait marché dans mes voies!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'J’aurais bientôt subjugué leurs ennemis, et tourné ma main contre leurs adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Ceux qui haïssent l’ Éternel se seraient soumis à lui; et leur temps, à eux, aurait été à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 17, 'Et il les aurait nourris de la moelle du froment, et je t’aurais rassasié du miel du rocher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Psaume d’Asaph. Dieu se tient dans l’assemblée de ✶Dieu; il juge au milieu des juges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Jusques à quand jugerez-vous injustement et ferez-vous acception de la personne des méchants? Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Faites droit au misérable et à l’orphelin, faites justice à l’affligé et au nécessiteux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Délivrez le misérable et le pauvre, sauvez-le de la main des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Ils ne connaissent ni ne comprennent, ils marchent dans les ténèbres: tous les fondements de la terre chancellent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Moi j’ai dit: Vous êtes des dieux, et vous êtes tous fils du Très-haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Mais vous mourrez comme un homme, et vous tomberez comme un des princes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Lève-toi, ô Dieu! juge la terre; car tu hériteras toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Cantique. Psaume d’Asaph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Ô Dieu! ne garde pas le silence. Ne te tais pas, et ne te tiens pas tranquille, ô ✶Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Car voici, tes ennemis s’agitent, et ceux qui te haïssent lèvent la tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Ils trament avec astuce des complots contre ton peuple, et ils consultent contre tes [fidèles] cachés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Ils ont dit: Venez, et exterminons-les, de sorte qu’ils ne soient plus une nation et qu’on ne fasse plus mention du nom d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Car ils ont consulté ensemble d’un cœur, ils ont fait une alliance contre toi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Les tentes d’Édom, et les Ismaélites, Moab, et les Hagaréniens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Guebal, et Ammon, et Amalek, la Philistie, avec les habitants de Tyr;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Assur aussi s’est joint à eux; ils servent de bras aux fils de Lot. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Fais-leur comme à Madian, – comme à Sisera, comme à Jabin au torrent de Kison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Qui ont été détruits à En-Dor, qui sont devenus du fumier pour la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Fais que leurs nobles soient comme Oreb et comme Zeëb, et tous leurs princes comme Zébakh et comme Tsalmunna;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Car ils ont dit: Prenons possession des habitations de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Mon Dieu! rends-les semblables à un tourbillon, comme la balle devant le vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Comme le feu brûle la forêt, et comme la flamme embrase les montagnes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Ainsi poursuis-les par ta tempête, et épouvante-les par ton ouragan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Remplis leurs faces d’ignominie, afin qu’ils cherchent ton nom, ô Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Qu’ils soient honteux et épouvantés à jamais, qu’ils soient confondus et qu’ils périssent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 19, 'Et qu’ils sachent que toi seul, dont le nom est l’ Éternel, tu es le Très-haut sur toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, '*Au chef de musique. Sur Guitthith. Des fils de Coré. Psaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Combien sont aimables tes demeures, ô Éternel des armées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Mon âme désire, et même elle languit après les parvis de l’ Éternel; mon cœur et ma chair crient après le ✶Dieu vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Le passereau même a trouvé une maison, et l’hirondelle un nid pour elle, où elle a mis ses petits:... tes autels, ô Éternel des armées! mon roi et mon Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Bienheureux ceux qui habitent dans ta maison; ils te loueront sans cesse! Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Bienheureux l’homme dont la force est en toi, [et ceux] dans le cœur desquels sont les chemins frayés!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Passant par la vallée de Baca, ils en font une fontaine; la pluie aussi la couvre de bénédictions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Ils marchent de force en force, ils paraissent devant Dieu en Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Éternel, Dieu des armées! écoute ma prière; Dieu de Jacob! prête l’oreille. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Toi, notre bouclier! – vois, ô Dieu! et regarde la face de ton oint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Car un jour dans tes parvis vaut mieux que mille. J’aimerais mieux me tenir sur le seuil dans la maison de mon Dieu, que de demeurer dans les tentes de la méchanceté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Car l’ Éternel Dieu est un soleil et un bouclier; l’ Éternel donnera la grâce et la gloire; il ne refusera aucun bien à ceux qui marchent dans l’intégrité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 13, 'Éternel des armées! bienheureux l’homme qui se confie en toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Au chef de musique. Des fils de Coré. Psaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Éternel! tu as été propice à ta terre, tu as rétabli les captifs de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Tu as pardonné l’iniquité de ton peuple, tu as couvert tous leurs péchés. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Tu as retiré tout ton courroux, tu es revenu de l’ardeur de ta colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Ramène-nous, ô Dieu de notre salut, et fais cesser ton indignation contre nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Veux-tu être à toujours en colère contre nous, faire durer ta colère de génération en génération?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Ne veux-tu pas nous faire vivre de nouveau, afin que ton peuple se réjouisse en toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Éternel! fais-nous voir ta bonté, et accorde-nous ton salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'J’écouterai ce que dira ✶Dieu, l’ Éternel; car il dira paix à son peuple et à ses saints. Mais qu’ils ne retournent pas à la folie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Certainement, son salut est près de ceux qui le craignent, afin que la gloire demeure dans notre pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'La bonté et la vérité se sont rencontrées, la justice et la paix se sont embrassées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'La vérité germera de la terre, et la justice regardera des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'L’ Éternel aussi donnera ce qui est bon, et notre pays rendra son fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 14, 'La justice marchera devant lui, et elle mettra ses pas sur le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Prière de David. Éternel! incline ton oreille, réponds-moi; car je suis affligé et pauvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Garde mon âme, car je suis un de [tes] saints; toi, mon Dieu! sauve ton serviteur qui se confie en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Use de grâce envers moi, Seigneur! car je crie à toi tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Réjouis l’âme de ton serviteur; car à toi, Seigneur, j’élève mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Car toi, Seigneur! tu es bon, prompt à pardonner, et grand en bonté envers tous ceux qui crient vers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Éternel! prête l’oreille à ma prière, et sois attentif à la voix de mes supplications.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Au jour de ma détresse je crierai vers toi, car tu me répondras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Seigneur! nul entre les dieux n’est comme toi, et il n’y a point d’œuvres comme les tiennes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Toutes les nations que tu as faites viendront et se prosterneront devant toi, Seigneur! et elles glorifieront ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Car tu es grand, et tu fais des choses merveilleuses; tu es Dieu, toi seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Éternel! enseigne-moi ton chemin; je marcherai dans ta vérité; unis mon cœur à la crainte de ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Je te célébrerai de tout mon cœur, Seigneur, mon Dieu! et je glorifierai ton nom à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Car ta bonté est grande envers moi, et tu as sauvé mon âme du shéol profond.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Ô Dieu! des hommes arrogants se sont levés contre moi, et l’assemblée des hommes violents cherche ma vie; et ils ne t’ont pas mis devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Mais toi, Seigneur! tu es un ✶Dieu miséricordieux et faisant grâce, lent à la colère, et grand en bonté et en vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Tourne-toi vers moi, et use de grâce envers moi; donne ta force à ton serviteur, et sauve le fils de ta servante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Opère pour moi un signe de [ta] faveur, et que ceux qui me haïssent le voient et soient honteux; car toi, ô Éternel! tu m’auras aidé, et tu m’auras consolé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Des fils de Coré. Psaume. Cantique. La fondation qu’il a posée est dans les montagnes de sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'L’ Éternel aime les portes de Sion plus que toutes les demeures de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Des choses glorieuses sont dites de toi, cité de Dieu. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Je ferai mention de Rahab et de Babylone à ceux qui me connaissent; voici la Philistie, et Tyr, avec l’Éthiopie: celui-ci était né là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Et de Sion il sera dit: Celui-ci et celui-là sont nés en elle; et le Très-haut, lui, l’établira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Quand l’ Éternel enregistrera les peuples, il comptera: Celui-ci est né là. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Et en chantant et en dansant, [ils diront]: Toutes mes sources sont en toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Cantique. Psaume. Pour les fils de Coré. Au chef de musique, sur Mahalath-Leannoth. Pour instruire. D’Héman, l’Ezrakhite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Éternel, Dieu de mon salut! j’ai crié de jour [et] de nuit devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Que ma prière vienne devant toi, incline ton oreille à mon cri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Car mon âme est rassasiée de maux, et ma vie touche au shéol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Je suis compté parmi ceux qui descendent dans la fosse, je suis comme un homme qui n’a pas de force,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Gisant parmi les morts, comme les tués qui sont couchés dans le sépulcre, desquels tu ne te souviens plus, et qui sont retranchés de ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Tu m’as mis dans une fosse profonde, dans des lieux ténébreux, dans des abîmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Ta fureur s’est appesantie sur moi, et tu m’as accablé de toutes tes vagues. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Tu as éloigné de moi ceux de ma connaissance, tu m’as mis en abomination auprès d’eux; je suis enfermé, et je ne puis sortir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Mon œil se consume d’affliction; j’ai crié à toi, Éternel, tous les jours; j’ai étendu mes mains vers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Feras-tu des merveilles pour les morts? ou les trépassés se lèveront-ils pour te célébrer? Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Racontera-t-on ta bonté dans le sépulcre, ta fidélité dans l’abîme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Connaîtra-t-on tes merveilles dans les ténèbres, et ta justice dans le pays de l’oubli?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Mais moi, Éternel! je crie à toi, et dès le matin ma prière te prévient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Éternel! pourquoi as-tu rejeté mon âme, [et] me caches-tu ta face?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Je suis affligé et expirant dès ma jeunesse; je porte tes terreurs, je ne sais où j’en suis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Les ardeurs de ta colère ont passé sur moi, tes frayeurs m’ont anéanti;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Elles m’ont environné comme des eaux tout le jour, elles m’ont entouré toutes ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 19, 'Tu as éloigné de moi amis et compagnons; ceux de ma connaissance [me sont] des ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Instruction d’Éthan, l’Ezrakhite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Je chanterai à toujours les bontés de l’ Éternel; de génération en génération je ferai connaître de ma bouche ta fidélité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Car j’ai dit: La bonté sera édifiée pour toujours; dans les cieux mêmes tu établiras ta fidélité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'J’ai fait alliance avec mon élu, j’ai juré à David, mon serviteur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'J’établirai ta semence pour toujours, et j’édifierai ton trône de génération en génération. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Et les cieux célébreront tes merveilles, ô Éternel! oui, ta fidélité, dans la congrégation des saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Car qui, dans les nues, peut être comparé à l’ Éternel? Qui, parmi les fils des forts, est semblable à l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, '✶Dieu est extrêmement redoutable dans l’assemblée des saints, et terrible au milieu de tous ceux qui l’entourent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Éternel, Dieu des armées, qui est comme toi, puissant Jah? Et ta fidélité est tout autour de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Toi, tu domines l’orgueil de la mer; quand ses flots se soulèvent, toi tu les apaises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Toi, tu as abattu Rahab comme un homme tué; par le bras de ta force tu as dispersé tes ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'À toi les cieux, et à toi la terre; le monde et tout ce qu’il contient, toi tu l’as fondé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Le nord et le midi, toi tu les as créés; le Thabor et l’Hermon exultent en ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'À toi est le bras de puissance; ta main est forte; ta droite est haut élevée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'La justice et le jugement sont les bases de ton trône; la bonté et la vérité marchent devant ta face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Bienheureux le peuple qui connaît le cri de joie! Ils marchent, ô Éternel! à la lumière de ta face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Ils s’égaient en ton nom tout le jour, et sont haut élevés par ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Car tu es la gloire de leur force; et dans ton bon plaisir notre corne sera haut élevée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Car l’ Éternel est notre bouclier, et le Saint d’Israël, notre roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Alors tu parlas en vision de ton saint, et tu dis: J’ai placé du secours sur un homme puissant, j’ai haut élevé un élu d’entre le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'J’ai trouvé David, mon serviteur; je l’ai oint de mon huile sainte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Ma main sera fermement avec lui, et mon bras le fortifiera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'L’ennemi ne le pressurera pas et le fils d’iniquité ne l’affligera pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'J’abattrai ses adversaires devant sa face, et je frapperai ceux qui le haïssent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Et ma fidélité et ma bonté seront avec lui, et, par mon nom, sa corne sera élevée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Et j’ai mis sa main à la mer, et sa droite dans les fleuves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Lui me criera: Tu es mon père, mon ✶Dieu, et le rocher de mon salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Aussi moi, je ferai de lui le premier-né, le plus élevé des rois de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Je lui garderai ma bonté à toujours, et mon alliance lui sera assurée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Et je ferai subsister sa semence à perpétuité, et son trône comme les jours des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Si ses fils abandonnent ma loi et ne marchent pas dans mes ordonnances,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'S’ils violent mes statuts et ne gardent pas mes commandements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Je visiterai leur transgression avec la verge, et leur iniquité avec des coups;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Mais je ne retirerai pas de lui ma bonté, et je ne démentirai pas ma fidélité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Je ne violerai point mon alliance, et je ne changerai pas ce qui est sorti de mes lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'J’ai une fois juré par ma sainteté, si [jamais] je mens à David!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Sa semence sera à toujours, et son trône comme le soleil devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Comme la lune, il sera affermi pour toujours; et le témoin dans les nues en est ferme. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Mais tu l’as rejeté et tu l’as méprisé, tu as été courroucé contre ton oint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Tu as répudié l’alliance de ton serviteur, tu as profané sa couronne jusqu’en terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Tu as rompu toutes ses clôtures, tu as mis en ruine ses forteresses:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Tous ceux qui passent le pillent; il est en opprobre à ses voisins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Tu as élevé la droite de ses adversaires, tu as réjoui tous ses ennemis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Tu as retourné le tranchant de son épée, et tu ne l’as pas soutenu dans la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Tu as fait cesser son éclat, et tu as jeté par terre son trône;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Tu as abrégé les jours de sa jeunesse, tu l’as couvert de honte. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Jusques à quand, ô Éternel, te cacheras-tu à toujours, [et] ta fureur brûlera-t-elle comme un feu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Souviens-toi, quant à moi, de ce qu’est la vie: pourquoi as-tu créé tous les fils des hommes [pour n’être que] vanité?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Qui est l’homme qui vit et qui ne verra pas la mort, – qui sauvera son âme de la main du shéol? Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Où sont, Seigneur, tes premières bontés, que tu as jurées à David dans ta fidélité?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Souviens-toi, Seigneur, de l’opprobre de tes serviteurs, – je porte dans mon sein [celui de] tous les grands peuples, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, '[L’opprobre] dont tes ennemis couvrent, ô Éternel, dont ils couvrent les pas de ton oint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 53, 'Béni soit l’ Éternel pour toujours! Amen, oui, amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Prière de Moïse, homme de Dieu. Seigneur, tu as été notre demeure de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Avant que les montagnes soient nées et que tu aies formé la terre et le monde, d’éternité en éternité tu es ✶Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Tu fais retourner l’homme jusqu’à la poussière, et tu dis: Retournez, fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Car 1 000 ans, à tes yeux, sont comme le jour d’hier quand il est passé, et comme une veille dans la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Comme un torrent tu les emportes; ils sont comme un sommeil, – au matin, comme l’herbe qui reverdit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Au matin, elle fleurit et reverdit; le soir on la coupe, et elle sèche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Car nous sommes consumés par ta colère, et nous sommes épouvantés par ta fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Tu as mis devant toi nos iniquités, devant la lumière de ta face nos [fautes] cachées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Car tous nos jours s’en vont par ta grande colère; nous consumons nos années comme une pensée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Les jours de nos années montent à 70 ans, et si, à cause de la vigueur, ils vont à 80 ans, leur orgueil encore est peine et vanité; car [notre vie] s’en va bientôt, et nous nous envolons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Qui connaît la force de ta colère, et, selon ta crainte, ton courroux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Enseigne-nous ainsi à compter nos jours, afin que nous en acquérions un cœur sage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Éternel! retourne-toi. – Jusques à quand? – Et repens-toi à l’égard de tes serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Rassasie-nous, au matin, de ta bonté; et nous chanterons de joie, et nous nous réjouirons tous nos jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Réjouis-nous selon les jours où tu nous as affligés, selon les années où nous avons vu des maux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Que ton œuvre apparaisse à tes serviteurs, et ta majesté à leurs fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Et que la gratuité du Seigneur, notre Dieu, soit sur nous; et établis sur nous l’œuvre de nos mains: oui, l’œuvre de nos mains, établis-la.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Celui qui habite dans la [demeure] secrète du Très-haut logera à l’ombre du Tout-puissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'J’ai dit de l’ Éternel: Il est ma confiance et mon lieu fort; il est mon Dieu, je me confierai en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Car il te délivrera du piège de l’oiseleur, de la peste calamiteuse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Il te couvrira de ses plumes, et sous ses ailes tu auras un refuge; sa vérité sera ton bouclier et ta rondache.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Tu n’auras pas peur des frayeurs de la nuit, ni de la flèche qui vole de jour,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Ni de la peste qui marche dans les ténèbres, ni de la destruction qui dévaste en plein midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Il en tombera mille à ton côté, et dix mille à ta droite; – toi, tu ne seras pas atteint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Seulement tu contempleras de tes yeux, et tu verras la récompense des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Parce que toi tu as mis l’ Éternel, mon refuge, le Très-haut, pour ta demeure,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Aucun mal ne t’arrivera, et aucune plaie n’approchera de ta tente;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Car il commandera à ses anges à ton sujet, de te garder en toutes tes voies:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Ils te porteront sur leurs mains, de peur que tu ne heurtes ton pied contre une pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Tu marcheras sur le lion et sur l’aspic, tu fouleras le lionceau et le dragon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Parce qu’il a mis son affection sur moi, je le délivrerai; je le mettrai en une haute retraite, parce qu’il a connu mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Il m’invoquera, et je lui répondrai; dans la détresse je serai avec lui; je le délivrerai et le glorifierai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Je le rassasierai de longs jours, et je lui ferai voir mon salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Psaume. Cantique pour le jour du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Il est bon de célébrer l’ Éternel, et de chanter des cantiques à [la gloire de] ton nom, ô Très-haut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'D’annoncer le matin ta bonté, et ta fidélité dans les nuits,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Sur l’instrument à dix cordes, et sur le luth, et sur le higgaïon avec la harpe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Car, ô Éternel! tu m’as réjoui par tes actes; je chanterai de joie à cause des œuvres de tes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Éternel! que tes œuvres sont grandes! Tes pensées sont très profondes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'L’homme stupide ne le connaît pas, et l’insensé ne le comprend pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Quand les méchants poussent comme l’herbe et que tous les ouvriers d’iniquité fleurissent, c’est pour être détruits à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Mais toi, Éternel! tu es haut élevé pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Car voici, tes ennemis, ô Éternel! car voici, tes ennemis périront, tous les ouvriers d’iniquité seront dispersés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Mais tu élèveras ma corne comme celle du buffle; je serai oint d’une huile fraîche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Et mon œil verra [son plaisir] en mes ennemis, et mes oreilles se repaîtront du sort des méchants qui s’élèvent contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Le juste poussera comme le palmier, il croîtra comme le cèdre dans le Liban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Ceux qui sont plantés dans la maison de l’ Éternel fleuriront dans les parvis de notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Ils porteront des fruits encore dans la blanche vieillesse, ils seront pleins de sève, et verdoyants,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 16, 'Afin d’annoncer que l’ Éternel est droit. Il est mon rocher, et il n’y a point d’injustice en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, '*L’ Éternel règne, il s’est revêtu de majesté; l’ Éternel s’est revêtu, il s’est ceint de force: aussi le monde est affermi, il ne sera pas ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Ton trône est établi dès longtemps; tu es dès l’éternité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Les fleuves ont élevé, ô Éternel! les fleuves ont élevé leur voix, les fleuves ont élevé leurs flots mugissants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'L’ Éternel, dans les lieux hauts, est plus puissant que la voix des grosses eaux, que les puissantes vagues de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Tes témoignages sont très sûrs. La sainteté sied à ta maison, ô Éternel! pour de longs jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, '✶Dieu des vengeances, Éternel, ✶Dieu des vengeances! fais luire ta splendeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Élève-toi, juge de la terre! rends la récompense aux orgueilleux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Jusques à quand les méchants, ô Éternel! jusques à quand les méchants se réjouiront-ils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, '[Jusques à quand] tous les ouvriers d’iniquité proféreront-ils [et] diront-ils des paroles arrogantes? [jusques à quand] se vanteront-ils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Ils foulent ton peuple, ô Éternel! et affligent ton héritage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Ils tuent la veuve et l’étranger, et mettent à mort les orphelins,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Et ils disent: Jah ne le verra pas, et le Dieu de Jacob n’y fera pas attention.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Comprenez, vous les stupides d’entre le peuple! Et vous, insensés, quand serez-vous intelligents?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Celui qui a planté l’oreille n’entendra-t-il point? Celui qui a formé l’œil ne verra-t-il point?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Celui qui instruit les nations ne châtiera-t-il pas, lui qui enseigne la connaissance aux hommes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'L’ Éternel connaît les pensées des hommes, qu’elles ne sont que vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Bienheureux l’homme que tu châties, ô Jah! et que tu enseignes par ta loi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Pour le mettre à l’abri des mauvais jours, jusqu’à ce que la fosse soit creusée pour le méchant!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Car l’ Éternel ne délaissera point son peuple et n’abandonnera point son héritage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Car le jugement retournera à la justice, et tous ceux qui sont droits de cœur le suivront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Qui se lèvera pour moi contre les méchants? Qui se tiendra avec moi contre les ouvriers d’iniquité?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Si l’ Éternel n’avait été mon aide, peu s’en serait fallu que mon âme n’ait été habiter dans le silence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Si j’ai dit: Mon pied glisse, ta bonté, ô Éternel! m’a soutenu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Dans la multitude des pensées qui étaient au-dedans de moi, tes consolations ont fait les délices de mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Le trône d’iniquité, qui fait de l’oppression une loi, sera-t-il uni à toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Ils se rassemblent contre l’âme du juste, et condamnent le sang innocent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Mais l’ Éternel me sera une haute retraite, et mon Dieu, le rocher de ma confiance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Il fera retomber sur eux leur iniquité, et les détruira par leur méchanceté; l’ Éternel, notre Dieu, les détruira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Venez, chantons à haute voix à l’ Éternel; poussons des cris de joie vers le rocher de notre salut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Allons au-devant de lui avec la louange, poussons vers lui des cris de joie en [chantant] des psaumes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Car l’ Éternel est un grand ✶Dieu, et un grand roi par-dessus tous les dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Les lieux profonds de la terre sont en sa main, et les sommets des montagnes sont à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'À lui est la mer, et lui-même l’a faite; et le sec, ses mains l’ont formé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Venez, adorons et inclinons-nous, agenouillons-nous devant l’ Éternel qui nous a faits!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Car c’est lui qui est notre Dieu; et nous, nous sommes le peuple de sa pâture et les brebis de sa main. Aujourd’hui, si vous entendez sa voix,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'N’endurcissez pas votre cœur comme à Meriba, comme au jour de Massa, dans le désert,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Où vos pères m’ont tenté, éprouvé, et ont vu mes œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Quarante ans j’ai eu cette génération en dégoût, et j’ai dit: C’est un peuple dont le cœur s’égare, et ils n’ont point connu mes voies,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'De sorte que j’ai juré dans ma colère: S’ils entrent dans mon repos!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Chantez à l’ Éternel un cantique nouveau; chantez à l’ Éternel, toute la terre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Chantez à l’ Éternel, bénissez son nom, annoncez de jour en jour son salut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Racontez parmi les nations sa gloire, parmi tous les peuples ses œuvres merveilleuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Car l’ Éternel est grand, et fort digne de louange; il est terrible par-dessus tous les dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Car tous les dieux des peuples sont des idoles, mais l’ Éternel a fait les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'La majesté et la magnificence sont devant lui, la force et la beauté sont dans son sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Familles des peuples, rendez à l’ Éternel, rendez à l’ Éternel la gloire et la force!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Rendez à l’ Éternel la gloire de son nom; apportez une offrande et entrez dans ses parvis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Adorez l’ Éternel en sainte magnificence; tremblez devant lui, toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Dites parmi les nations: L’ Éternel règne! Aussi le monde est affermi, il ne sera pas ébranlé. Il exercera le jugement sur les peuples avec droiture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Que les cieux se réjouissent, et que la terre s’égaie; que la mer bruie, et tout ce qui la remplit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Que les champs se réjouissent, et tout ce qui est en eux! Alors tous les arbres de la forêt chanteront de joie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Devant l’ Éternel; car il vient, car il vient pour juger la terre: il jugera le monde avec justice, et les peuples selon sa fidélité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'L’ Éternel règne: que la terre s’égaie, que les îles nombreuses se réjouissent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Des nuées et l’obscurité sont autour de lui; la justice et le jugement sont la base de son trône.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Un feu va devant lui et consume à l’entour ses adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Ses éclairs illuminent le monde: la terre le vit et trembla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Les montagnes se fondirent comme de la cire, à la présence de l’ Éternel, à la présence du Seigneur de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Les cieux déclarent sa justice, et tous les peuples voient sa gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Que tous ceux qui servent une image taillée, qui se vantent des idoles, soient honteux. Vous, tous les dieux, prosternez-vous devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Sion l’a entendu, et s’est réjouie; et les filles de Juda se sont égayées à cause de tes jugements, ô Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Car toi, Éternel! tu es le Très-haut sur toute la terre; tu es fort élevé par-dessus tous les dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Vous qui aimez l’ Éternel, haïssez le mal! Il garde les âmes de ses saints, il les délivre de la main des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'La lumière est semée pour le juste, et la joie pour ceux qui sont droits de cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Justes, réjouissez-vous en l’ Éternel, et célébrez la mémoire de sa sainteté!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Psaume. Chantez à l’ Éternel un cantique nouveau! Car il a fait des choses merveilleuses: sa droite et le bras de sa sainteté l’ont délivré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'L’ Éternel a fait connaître son salut, il a révélé sa justice aux yeux des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Il s’est souvenu de sa bonté et de sa fidélité envers la maison d’Israël; tous les bouts de la terre ont vu le salut de notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Poussez des cris de joie vers l’ Éternel, toute la terre; éclatez d’allégresse, et exultez avec chant de triomphe, et psalmodiez!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Chantez les louanges de l’ Éternel avec la harpe, avec la harpe et une voix de cantique!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Avec des trompettes et le son du cor, poussez des cris de joie devant le Roi, l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Que la mer bruie, et tout ce qui la remplit, le monde et ceux qui y habitent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Que les fleuves battent des mains, que les montagnes chantent de joie ensemble,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Devant l’ Éternel! car il vient pour juger la terre: il jugera le monde avec justice, et les peuples avec droiture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'L’ Éternel règne: que les peuples tremblent! Il est assis entre les chérubins: que la terre s’émeuve!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'L’ Éternel est grand en Sion, et il est haut élevé par-dessus tous les peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Ils célébreront ton nom grand et terrible: – il est saint! –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Et la force du roi qui aime la justice. Toi, tu établis la droiture, tu exerces le jugement et la justice en Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Exaltez l’ Éternel, notre Dieu, et prosternez-vous devant le marchepied de ses pieds: – il est saint!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Moïse et Aaron, parmi ses sacrificateurs, et Samuel, parmi ceux qui invoquent son nom, crièrent à l’ Éternel, et il leur a répondu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Il leur parla dans la colonne de nuée: ils ont gardé ses témoignages, et le statut qu’il leur avait donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Éternel, notre Dieu! tu leur as répondu, tu as été pour eux un ✶Dieu qui pardonnait, et prenait vengeance de leurs actes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Exaltez l’ Éternel, notre Dieu, et prosternez-vous en la montagne de sa sainteté; car l’ Éternel, notre Dieu, est saint!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Psaume d’action de grâces. Poussez des cris de joie vers l’ Éternel, toute la terre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Servez l’ Éternel avec joie, venez devant lui avec des chants de triomphe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Sachez que l’ Éternel est Dieu. C’est lui qui nous a faits, et ce n’est pas nous; [nous sommes] son peuple, et le troupeau de sa pâture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Entrez dans ses portes avec des actions de grâces, dans ses parvis avec des louanges. Célébrez-le, bénissez son nom!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Car l’ Éternel est bon; sa bonté demeure à toujours, et sa fidélité de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, '*Psaume de David. Je chanterai la bonté et le jugement; à toi, ô Éternel, je psalmodierai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Je veux agir sagement, dans une voie parfaite; – quand viendras-tu à moi? – Je marcherai dans l’intégrité de mon cœur au milieu de ma maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Je ne mettrai pas devant mes yeux une chose de Bélial; je hais la conduite de ceux qui se détournent: elle ne s’attachera point à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Le cœur pervers se retirera d’auprès de moi; je ne connaîtrai pas le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Celui qui calomnie en secret son prochain, je le détruirai; celui qui a les yeux hautains et le cœur orgueilleux, je ne le supporterai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'J’aurai les yeux sur les fidèles du pays, pour les faire habiter avec moi; celui qui marche dans une voie parfaite, lui me servira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Celui qui pratique la fraude n’habitera pas au-dedans de ma maison; celui qui profère des mensonges ne subsistera pas devant mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Chaque matin, je détruirai tous les méchants du pays, pour retrancher de la ville de l’ Éternel tous les ouvriers d’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Prière de l’affligé, quand il est accablé et répand sa plainte devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Éternel, entends ma prière, et que mon cri vienne jusqu’à toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Ne me cache pas ta face; au jour de ma détresse, incline vers moi ton oreille; au jour où je crie, hâte-toi, réponds-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Car mes jours s’évanouissent comme la fumée, et mes os sont brûlés comme un foyer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Mon cœur est frappé, et est desséché comme l’herbe; car j’ai oublié de manger mon pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'À cause de la voix de mon gémissement, mes os s’attachent à ma chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Je suis devenu semblable au pélican du désert; je suis comme le hibou des lieux désolés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Je veille, et je suis comme un passereau solitaire sur un toit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Tout le jour mes ennemis m’outragent; ceux qui sont furieux contre moi jurent par moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Car j’ai mangé la cendre comme du pain, et j’ai mêlé de pleurs mon breuvage,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'À cause de ton indignation et de ta colère; car tu m’as élevé haut, et tu m’as jeté en bas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Mes jours sont comme l’ombre qui s’allonge, et je deviens sec comme l’herbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Mais toi, Éternel! tu demeures à toujours, et ta mémoire est de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Tu te lèveras, tu auras compassion de Sion; car c’est le temps d’user de grâce envers elle, car le temps assigné est venu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Car tes serviteurs prennent plaisir à ses pierres, et ont compassion de sa poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Alors les nations craindront le nom de l’ Éternel, et tous les rois de la terre, ta gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Quand l’ Éternel bâtira Sion, il paraîtra dans sa gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Il aura égard à la prière du désolé, et il ne méprisera pas leur prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Cela sera écrit pour la génération à venir; et le peuple qui sera créé louera Jah;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Car il a regardé des lieux hauts de sa sainteté; des cieux l’ Éternel a considéré la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Pour entendre le gémissement du prisonnier, et pour délier ceux qui étaient voués à la mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Afin qu’on annonce dans Sion le nom de l’ Éternel, et sa louange dans Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Quand les peuples seront rassemblés, et les royaumes, pour servir l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Il a abattu ma force dans le chemin, il a abrégé mes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'J’ai dit: Mon ✶Dieu, ne m’enlève pas à la moitié de mes jours!... Tes années sont de génération en génération!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Tu as jadis fondé la terre, et les cieux sont l’ouvrage de tes mains;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Eux, ils périront, mais toi, tu subsisteras; et ils vieilliront tous comme un vêtement; tu les changeras comme un habit, et ils seront changés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Mais toi, tu es le Même, et tes années ne finiront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 29, 'Les fils de tes serviteurs demeureront, et leur semence sera établie devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, '*De David. Mon âme, bénis l’ Éternel! Et que tout ce qui est au-dedans de moi, [bénisse] son saint nom!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Mon âme, bénis l’ Éternel, et n’oublie aucun de ses bienfaits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'C’est lui qui pardonne toutes tes iniquités, qui guérit toutes tes infirmités,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Qui rachète ta vie de la fosse, qui te couronne de bonté et de compassions,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Qui rassasie de biens ta vieillesse; ta jeunesse se renouvelle comme celle de l’aigle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'L’ Éternel fait justice et droit à tous les opprimés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Il a fait connaître ses voies à Moïse, ses actes aux fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'L’ Éternel est miséricordieux, et plein de grâce, lent à la colère et d’une grande bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Il ne contestera pas à jamais, et il ne garde pas sa colère à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Il ne nous a pas fait selon nos péchés, et ne nous a pas rendu selon nos iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Car comme les cieux sont élevés au-dessus de la terre, sa bonté est grande envers ceux qui le craignent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Autant l’orient est loin de l’occident, autant il a éloigné de nous nos transgressions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Comme un père a compassion de ses fils, l’ Éternel a compassion de ceux qui le craignent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Car il sait de quoi nous sommes formés, il se souvient que nous sommes poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'L’homme,... ses jours sont comme l’herbe; il fleurit comme la fleur des champs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Car le vent passe dessus, et elle n’est plus, et son lieu ne la reconnaît plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Mais la bonté de l’ Éternel est de tout temps et à toujours sur ceux qui le craignent, et sa justice pour les fils de leurs fils,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Pour ceux qui gardent son alliance, et qui se souviennent de ses préceptes pour les faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'L’ Éternel a établi son trône dans les cieux, et son royaume domine sur tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Bénissez l’ Éternel, vous, ses anges puissants en force, qui exécutez sa parole, écoutant la voix de sa parole!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Bénissez l’ Éternel, vous, toutes ses armées, qui êtes ses serviteurs, accomplissant son bon plaisir!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Bénissez l’ Éternel, vous, toutes ses œuvres, dans tous les lieux de sa domination! Mon âme, bénis l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Mon âme, bénis l’ Éternel! Éternel, mon Dieu, tu es merveilleusement grand, tu es revêtu de majesté et de magnificence!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Il s’enveloppe de lumière comme d’un manteau; il étend les cieux comme une tenture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Il joint les poutres de ses chambres hautes dans les eaux; il fait des nuées son char; il se promène sur les ailes du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Il fait ses anges des esprits, et ses serviteurs des flammes de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Il a fondé la terre sur ses bases; elle ne sera point ébranlée, à toujours et à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Tu l’avais couverte de l’abîme comme d’un vêtement, les eaux se tenaient au-dessus des montagnes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'À ta menace, elles s’enfuirent; à la voix de ton tonnerre, elles se hâtèrent de fuir: –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Les montagnes s’élevèrent, les vallées s’abaissèrent, au lieu même que tu leur avais établi; –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Tu leur as mis une limite qu’elles ne dépasseront point; elles ne reviendront pas couvrir la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Il a envoyé les sources dans les vallées: elles coulent entre les montagnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Elles abreuvent toutes les bêtes des champs; les ânes sauvages y étanchent leur soif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Les oiseaux des cieux demeurent auprès d’elles; ils font résonner leur voix d’entre les branches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'De ses chambres hautes, il abreuve les montagnes; la terre est rassasiée du fruit de tes œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Il fait germer l’herbe pour le bétail, et les plantes pour le service de l’homme, faisant sortir le pain de la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'Et le vin qui réjouit le cœur de l’homme, faisant reluire son visage avec l’huile; et avec le pain il soutient le cœur de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Les arbres de l’ Éternel sont rassasiés, les cèdres du Liban, qu’il a plantés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Où les oiseaux font leurs nids. Les pins sont la demeure de la cigogne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Les hautes montagnes sont pour les bouquetins; les rochers sont le refuge des damans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Il a fait la lune pour les saisons; le soleil connaît son coucher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Tu amènes les ténèbres, et la nuit arrive: alors toutes les bêtes de la forêt sont en mouvement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Les lionceaux rugissent après la proie, et pour demander à ✶Dieu leur nourriture...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Le soleil se lève: ils se retirent, et se couchent dans leurs tanières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, '[Alors] l’homme sort à son ouvrage et à son travail, jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Que tes œuvres sont nombreuses, ô Éternel! tu les as toutes faites avec sagesse. La terre est pleine de tes richesses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Cette mer, grande et vaste en tous sens! Là se meuvent sans nombre des animaux, les petits avec les grands;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Là se promènent les navires, [là] ce léviathan que tu as formé pour s’y ébattre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Tous s’attendent à toi, afin que tu leur donnes leur nourriture en son temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Tu leur donnes, ils recueillent; tu ouvres ta main, ils sont rassasiés de biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Tu caches ta face, ils sont troublés; tu retires leur souffle, ils expirent et retournent à leur poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Tu envoies ton esprit: ils sont créés, et tu renouvelles la face de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'La gloire de l’ Éternel sera à toujours; l’ Éternel se réjouira en ses œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Il regarde vers la terre, et elle tremble; il touche les montagnes, et elles fument.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Je chanterai à l’ Éternel durant ma vie, je chanterai des cantiques à mon Dieu tant que j’existerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Que ma méditation lui soit agréable; moi, je me réjouirai en l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Les pécheurs prendront fin de dessus la terre, et les méchants ne seront plus. Mon âme, bénis l’ Éternel! Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, '*Célébrez l’ Éternel, invoquez son nom; faites connaître parmi les peuples ses actes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Chantez-lui, chantez-lui des cantiques! Méditez toutes ses œuvres merveilleuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Glorifiez-vous de son saint nom; que le cœur de ceux qui cherchent l’ Éternel se réjouisse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Recherchez l’ Éternel et sa force, cherchez continuellement sa face;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Souvenez-vous de ses œuvres merveilleuses qu’il a faites, de ses prodiges, et des jugements de sa bouche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Vous, semence d’Abraham, son serviteur; vous, fils de Jacob, ses élus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Lui, l’ Éternel, est notre Dieu; ses jugements sont en toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Il s’est souvenu pour toujours de son alliance, de la parole qu’il commanda pour mille générations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, '[De l’alliance] qu’il a faite avec Abraham, et qu’il a jurée à Isaac,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Et qu’il a établie pour Jacob comme statut, pour Israël comme alliance perpétuelle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Disant: Je te donnerai le pays de Canaan, le lot de votre héritage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Quand ils étaient un petit nombre d’hommes, peu de chose, et étrangers dans le [pays],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Et allant de nation en nation, d’un royaume vers un autre peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Il ne permit à personne de les opprimer, et il reprit des rois à cause d’eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '[Disant]: Ne touchez pas à mes oints, et ne faites pas de mal à mes prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Et il appela la famine sur la terre; il brisa tout le bâton du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Il envoya un homme devant eux: Joseph fut vendu pour être esclave.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'On lui serra les pieds dans les ceps, son âme entra dans les fers,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Jusqu’au temps où arriva ce qu’il avait dit: la parole de l’ Éternel l’éprouva.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Le roi envoya, et il le mit en liberté; le dominateur des peuples le relâcha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Il l’établit seigneur sur sa maison, et gouverneur sur toutes ses possessions,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Pour lier ses princes à son plaisir, et pour rendre sages ses anciens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Alors Israël entra en Égypte, et Jacob séjourna dans le pays de Cham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Et [l’ Éternel] fit beaucoup multiplier son peuple, et le rendit plus puissant que ses oppresseurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Il changea leur cœur pour qu’ils haïssent son peuple, pour qu’ils complotent contre ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Il envoya Moïse, son serviteur, Aaron qu’il avait choisi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Ils opérèrent au milieu d’eux ses signes, et des prodiges dans le pays de Cham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Il envoya des ténèbres, et fit une obscurité; et ils ne se rebellèrent pas contre sa parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Il changea leurs eaux en sang, et fit mourir leurs poissons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Leur terre fourmilla de grenouilles, [jusque] dans les chambres de leurs rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Il parla, et il vint des mouches venimeuses, [et] des moustiques dans tous leurs confins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Il leur donna pour pluie de la grêle, un feu de flammes dans leur pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Et il frappa leurs vignes et leurs figuiers, et brisa les arbres de leur contrée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Il parla, et les sauterelles vinrent, et des yéleks sans nombre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Et ils dévorèrent toutes les plantes dans leur pays, et dévorèrent le fruit de leur sol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Et il frappa tout premier-né dans leur pays, les prémices de toute leur vigueur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Et il les fit sortir avec de l’argent et de l’or, et il n’y eut aucun infirme dans ses tribus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'L’Égypte se réjouit à leur sortie, car la frayeur d’Israël était tombée sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Il étendit une nuée pour couverture, et un feu pour éclairer de nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Ils demandèrent, et il fit venir des cailles, et il les rassasia du pain des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Il ouvrit le rocher, et les eaux en découlèrent; elles allèrent par les lieux secs, comme une rivière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Car il se souvint de sa parole sainte, [et] d’Abraham, son serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Et il fit sortir son peuple avec joie, ses élus avec chant de triomphe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Et il leur donna les pays des nations, et ils possédèrent le travail des peuples;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Afin qu’ils gardent ses statuts, et qu’ils observent ses lois. Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Louez Jah. Célébrez l’ Éternel! Car il est bon; car sa bonté demeure à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Qui dira les actes puissants de l’ Éternel? Qui fera entendre toute sa louange?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Bienheureux ceux qui gardent le juste jugement, qui pratiquent la justice en tout temps!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Souviens-toi de moi, Éternel! selon [ta] faveur envers ton peuple; visite-moi par ton salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Afin que je voie le bien de tes élus, que je me réjouisse de la joie de ta nation, [et] que je me glorifie avec ton héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Nous avons péché avec nos pères; nous avons commis l’iniquité, nous avons agi méchamment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Nos pères, en Égypte, n’ont pas été attentifs à tes merveilles; ils ne se sont pas souvenus de la multitude de tes bontés; mais ils ont été rebelles, près de la mer, à la mer Rouge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Cependant il les sauva à cause de son nom, afin de donner à connaître sa puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Et il tança la mer Rouge, et elle sécha; et il les fit marcher par les abîmes comme par un désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Et il les sauva de la main de celui qui les haïssait, et les racheta de la main de l’ennemi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Et les eaux couvrirent leurs oppresseurs: il n’en resta pas un seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Alors ils crurent à ses paroles, ils chantèrent sa louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Ils oublièrent vite ses œuvres, ils ne s’attendirent point à son conseil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Et ils furent remplis de convoitise dans le désert, et ils tentèrent ✶Dieu dans le lieu désolé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Et il leur donna ce qu’ils avaient demandé, mais il envoya la consomption dans leurs âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Ils furent jaloux de Moïse dans le camp, [et] d’Aaron, le saint de l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'La terre s’ouvrit, et engloutit Dathan, et couvrit l’assemblée d’Abiram;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Et un feu s’alluma dans leur assemblée, une flamme consuma les méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Ils firent un veau en Horeb, et se prosternèrent devant une image de fonte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Et ils changèrent leur gloire en la figure d’un bœuf qui mange l’herbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Ils oublièrent ✶Dieu, leur sauveur, qui avait fait de grandes choses en Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Des choses merveilleuses dans le pays de Cham, des choses terribles près de la mer Rouge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Et il dit qu’il les aurait détruits, – si Moïse, son élu, ne s’était pas tenu à la brèche devant lui, pour détourner sa fureur de sorte qu’il ne les détruise pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Et ils méprisèrent le pays désirable; ils ne crurent point à sa parole;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'Et ils murmurèrent dans leurs tentes, ils n’écoutèrent pas la voix de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Et il jura à leur sujet qu’il les ferait tomber dans le désert,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'Et qu’il ferait tomber leur semence parmi les nations, et les disperserait par les pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Et ils s’attachèrent à Baal-Péor, et mangèrent des sacrifices des morts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Et ils provoquèrent [Dieu] par leurs œuvres, et une peste éclata parmi eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Alors Phinées se leva, et exécuta le jugement, et la peste fut arrêtée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Et cela lui a été compté à justice, de génération en génération, pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Et ils l’irritèrent aux eaux de Meriba, et il en arriva du mal à Moïse à cause d’eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Car ils chagrinèrent son esprit, de sorte qu’il parla légèrement de ses lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Ils ne détruisirent point les peuples, comme l’ Éternel leur avait dit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Mais ils se mêlèrent parmi les nations, et ils apprirent leurs œuvres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Et ils servirent leurs idoles, et elles leur furent en piège;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Et ils sacrifièrent leurs fils et leurs filles aux démons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Et versèrent le sang innocent, le sang de leurs fils et de leurs filles, qu’ils sacrifièrent aux idoles de Canaan; et le pays fut profané par le sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Et ils se rendirent impurs par leurs œuvres, et se prostituèrent par leurs pratiques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Et la colère de l’ Éternel s’embrasa contre son peuple, et il abhorra son héritage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Et il les livra en la main des nations; et ceux qui les haïssaient dominèrent sur eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Et leurs ennemis les opprimèrent, et ils furent humiliés sous leur main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Maintes fois il les délivra; mais ils le chagrinèrent par leur conseil, et ils déchurent par leur iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Il les regarda dans leur détresse, quand il entendit leur cri,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Et il se souvint en leur faveur de son alliance, et se repentit selon la multitude de ses bontés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Et il leur fit trouver compassion auprès de tous ceux qui les avaient emmenés captifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Sauve-nous, Éternel, notre Dieu! et rassemble-nous d’entre les nations, afin que nous célébrions ton saint nom, et que nous nous glorifiions de ta louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Béni soit l’ Éternel, le Dieu d’Israël, de l’éternité jusqu’en éternité! et que tout le peuple dise: Amen! Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Célébrez l’ Éternel! Car il est bon; car sa bonté demeure à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Que les rachetés de l’ Éternel le disent, ceux qu’il a rachetés de la main de l’oppresseur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Et qu’il a rassemblés des pays, du levant et du couchant, du nord et de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Ils errèrent par le désert, dans un chemin solitaire; ils ne trouvèrent pas de ville pour y habiter;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Ils étaient affamés et altérés, leur âme défaillait en eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Alors ils crièrent à l’ Éternel dans leur détresse, [et] il les délivra de leurs angoisses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Et les conduisit dans un chemin droit, pour aller dans une ville habitable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Qu’ils célèbrent l’ Éternel pour sa bonté, et pour ses merveilles envers les fils des hommes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Car il a rassasié l’âme altérée, et a rempli de biens l’âme affamée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Ceux qui habitent dans les ténèbres et dans l’ombre de la mort, liés d’affliction et de fers,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Parce qu’ils se sont rebellés contre les paroles de ✶Dieu, et ont méprisé le conseil du Très-haut...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Et il a humilié leur cœur par le travail; ils ont trébuché, sans qu’il y ait personne qui les secoure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Alors ils crièrent à l’ Éternel dans leur détresse, [et] il les délivra de leurs angoisses:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Il les fit sortir des ténèbres et de l’ombre de la mort, et rompit leurs liens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Qu’ils célèbrent l’ Éternel pour sa bonté, et pour ses merveilles envers les fils des hommes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Car il a brisé les portes d’airain, et a mis en pièces les barres de fer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Les insensés, à cause de la voie de leur transgression, et à cause de leurs iniquités, sont affligés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Leur âme abhorre toute nourriture, et ils touchent aux portes de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Alors ils ont crié à l’ Éternel dans leur détresse, [et] il les a délivrés de leurs angoisses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Il a envoyé sa parole et les a guéris, et les a retirés de leurs fosses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Qu’ils célèbrent l’ Éternel pour sa bonté, et pour ses merveilles envers les fils des hommes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Et qu’ils sacrifient des sacrifices d’actions de grâces, et qu’ils racontent ses œuvres avec des chants de joie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Ceux qui descendent sur la mer dans des navires, qui font [leur] travail sur les grandes eaux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Ceux-là voient les œuvres de l’ Éternel, et ses merveilles dans les [eaux] profondes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Il a commandé, et a fait venir un vent de tempête, qui souleva ses flots:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Ils montent aux cieux, ils descendent aux abîmes: leur âme se fond de détresse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Ils tournent et chancellent comme un homme ivre, et toute leur sagesse est venue à néant...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Alors ils ont crié à l’ Éternel dans leur détresse, et il les a fait sortir de leurs angoisses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Il arrête la tempête, [la changeant] en calme, et les flots se taisent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Et ils se réjouissent de ce que les [eaux] sont apaisées, et il les conduit au port qu’ils désiraient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Qu’ils célèbrent l’ Éternel pour sa bonté, et pour ses merveilles envers les fils des hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Et qu’ils l’exaltent dans la congrégation du peuple, et le louent dans l’assemblée des anciens!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Il change les fleuves en désert, et les sources d’eaux en sol aride,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'La terre fertile en terre salée, à cause de l’iniquité de ceux qui y habitent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Il change le désert en un étang d’eau, et la terre aride en des sources d’eaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Et il y fait habiter les affamés; et ils y établissent des villes habitables,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Et sèment les champs, et plantent des vignes, qui leur rapportent du fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Et il les bénit, et ils se multiplient beaucoup; et il ne laisse pas diminuer leur bétail;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Et ils diminuent, et sont accablés par l’oppression, le malheur, et le chagrin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Il verse le mépris sur les nobles, et les fait errer dans un désert où il n’y a pas de chemin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Mais il relève le pauvre de l’affliction, et donne des familles comme des troupeaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Les hommes droits le verront et s’en réjouiront; et toute iniquité fermera sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Qui est sage prendra garde à ces choses, et comprendra les bontés de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Cantique. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Mon cœur est affermi, ô Dieu! je chanterai, et je psalmodierai,... mon âme aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Éveillez-vous, luth et harpe! Je m’éveillerai à l’aube du jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Je te célébrerai parmi les peuples, ô Éternel! et je chanterai tes louanges parmi les peuplades;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Car ta bonté est grande par-dessus les cieux, et ta vérité [atteint] jusqu’aux nues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Élève-toi, ô Dieu! au-dessus des cieux, et que ta gloire soit au-dessus de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Afin que tes bien-aimés soient délivrés, sauve par ta droite, et réponds-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Dieu a parlé dans sa sainteté: je me réjouirai; je partagerai Sichem et je mesurerai la vallée de Succoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Galaad est à moi, Manassé est à moi, et Éphraïm est la force de ma tête; Juda est mon législateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Moab est le bassin où je me lave; sur Édom j’ai jeté ma sandale; sur la Philistie je pousserai des cris de triomphe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Qui me conduira dans la ville forte? Qui me mènera jusqu’en Édom?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Ne sera-ce pas toi, ô Dieu, qui nous as rejetés, et qui n’es pas sorti, ô Dieu, avec nos armées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Donne-nous du secours pour sortir de détresse; car la délivrance qui vient de l’homme est vaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 14, 'Par Dieu nous ferons des actes de valeur, et c’est lui qui foulera nos adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Au chef de musique. De David. Psaume. Ô Dieu de ma louange! ne te tais point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Car la bouche du méchant et la bouche de la fraude se sont ouvertes contre moi: ils parlent contre moi avec une langue menteuse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Et ils m’ont entouré de paroles de haine, et ils me font la guerre sans cause.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Pour mon amour, ils ont été mes adversaires; mais moi [je me suis adonné à la] prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Et ils m’ont rendu le mal pour le bien, et la haine pour mon amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Prépose sur lui un méchant, et que l’adversaire se tienne à sa droite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Quand il sera jugé, qu’il soit déclaré méchant, et que sa prière lui soit [comptée] comme un péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Que ses jours soient peu nombreux, qu’un autre prenne sa charge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Que ses fils soient orphelins, et sa femme veuve;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Que ses fils soient vagabonds, et qu’ils mendient, et qu’ils aillent quêtant loin de leurs [demeures en] ruines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Que l’usurier jette le filet sur tout ce qui est à lui, et que les étrangers pillent [le fruit de] son travail;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Qu’il n’y ait personne qui étende sa bonté sur lui, et qu’il n’y ait personne qui use de grâce envers ses orphelins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Que sa postérité soit retranchée; que, dans la génération qui suivra, leur nom soit effacé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Que l’iniquité de ses pères revienne en mémoire devant l’ Éternel, et que le péché de sa mère ne soit point effacé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Qu’ils soient continuellement devant l’ Éternel, et qu’il retranche leur mémoire de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Parce qu’il ne s’est point souvenu d’user de bonté, et qu’il a persécuté l’affligé et le pauvre, et celui qui a le cœur brisé, pour le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Et il a aimé la malédiction: – qu’elle vienne sur lui! Et il n’a pas pris plaisir à la bénédiction: – qu’elle soit loin de lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Et qu’il soit revêtu de la malédiction comme de sa robe; et qu’elle entre au-dedans de lui comme de l’eau, et dans ses os comme de l’huile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Qu’elle lui soit comme un vêtement dont il se couvre, et comme une ceinture qui le ceigne continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Telle soit, de par l’ Éternel, la récompense de mes adversaires et de ceux qui parlent en mal contre mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Mais toi, Éternel! Seigneur! agis pour moi à cause de ton nom; car ta gratuité est bonne; délivre-moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Car je suis affligé et pauvre, et mon cœur est blessé au-dedans de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Je m’en vais comme l’ombre quand elle s’allonge; je suis jeté çà et là comme la sauterelle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Mes genoux chancellent par le jeûne, et ma chair s’est amaigrie et n’a plus sa graisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Et moi, je leur suis en opprobre; quand ils me voient, ils hochent la tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Aide-moi, Éternel, mon Dieu! Sauve-moi selon ta bonté!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Et qu’on sache que c’est ici ta main, – que toi, ô Éternel! tu l’as fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Qu’eux, ils maudissent; mais toi, bénis. S’ils s’élèvent, qu’ils soient honteux, et que ton serviteur se réjouisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Que mes adversaires soient revêtus de confusion, et qu’ils se couvrent de leur honte comme d’un manteau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, '[Alors] de ma bouche je célébrerai hautement l’ Éternel, et je le louerai au milieu de la multitude;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Car il s’est tenu à la droite du pauvre, pour le sauver de ceux qui jugeaient son âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'De David. Psaume. L’ Éternel a dit à mon Seigneur: Assieds-toi à ma droite, jusqu’à ce que je mette tes ennemis pour le marchepied de tes pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'L’ Éternel enverra de Sion la verge de ta force: Domine au milieu de tes ennemis!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Ton peuple sera [un peuple] de franche volonté, au jour de ta puissance, en sainte magnificence. Du sein de l’aurore te [viendra] la rosée de ta jeunesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'L’ Éternel a juré, et il ne se repentira point: Tu es sacrificateur pour toujours, selon l’ordre de Melchisédec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Le Seigneur, à ta droite, brisera les rois au jour de sa colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Il jugera parmi les nations, il remplira [tout] de corps morts, il brisera le chef d’un grand pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Il boira du torrent dans le chemin, c’est pourquoi il lèvera haut la tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, '*Louez Jah. Je célébrerai l’ Éternel de tout mon cœur, dans la compagnie des hommes droits et dans l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Les œuvres de l’ Éternel sont grandes, elles sont recherchées de tous ceux qui y prennent plaisir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Son œuvre est glorieuse et magnifique, et sa justice demeure à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Il a établi un mémorial de ses merveilles. L’ Éternel est plein de grâce et miséricordieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Il donne de la nourriture à ceux qui le craignent; il se souvient à toujours de son alliance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Il a montré à son peuple la puissance de ses œuvres, pour leur donner l’héritage des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Les œuvres de ses mains sont vérité et jugement; tous ses préceptes sont sûrs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Maintenus à perpétuité, pour toujours, faits avec vérité et droiture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Il a envoyé la rédemption à son peuple; il a commandé son alliance pour toujours. Son nom est saint et terrible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'La crainte de l’ Éternel est le commencement de la sagesse; tous ceux qui pratiquent [ses préceptes] auront une bonne intelligence. Sa louange demeure à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Louez Jah. Bienheureux l’homme qui craint l’ Éternel [et] qui prend un grand plaisir en ses commandements!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Sa semence sera puissante dans le pays;... la génération des hommes droits sera bénie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Les biens et la richesse seront dans sa maison, et sa justice demeure à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'La lumière se lève dans les ténèbres pour les hommes droits. Il est plein de grâce, et miséricordieux, et juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Heureux l’homme qui use de grâce, et qui prête! Il maintiendra sa cause dans le jugement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Aussi il ne sera jamais ébranlé. La mémoire du juste sera à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Il ne craindra pas une mauvaise nouvelle; son cœur est ferme, se confiant en l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Son cœur est soutenu; il ne craint pas, jusqu’à ce qu’il voie [son plaisir] en ses adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Il répand, il donne aux pauvres; sa justice demeure à perpétuité; sa corne est élevée en gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Le méchant [le] verra, et en aura du dépit; il grincera des dents et se fondra; le désir des méchants périra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Louez Jah. Louez, vous serviteurs de l’ Éternel, louez le nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Le nom de l’ Éternel soit béni, dès maintenant et à toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Du soleil levant jusqu’au soleil couchant, le nom de l’ Éternel soit loué!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'L’ Éternel est haut élevé par-dessus toutes les nations; sa gloire est au-dessus des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Qui est comme l’ Éternel, notre Dieu? Il a placé sa demeure en haut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Il s’abaisse pour regarder dans les cieux et sur la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'De la poussière il fait lever le misérable, de dessus le fumier il élève le pauvre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Pour les faire asseoir avec les nobles, avec les nobles de son peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Il fait habiter la femme stérile dans une maison, joyeuse mère de fils. Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, '*Quand Israël sortit d’Égypte, [et] la maison de Jacob d’avec un peuple qui parle une langue étrangère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Juda fut son sanctuaire, Israël la sphère de sa domination.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'La mer le vit, et s’enfuit; le Jourdain retourna en arrière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Les montagnes sautèrent comme des béliers, les collines comme des agneaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Qu’avais-tu, mer, pour t’enfuir; toi, Jourdain, pour retourner en arrière?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Vous, montagnes, pour sauter comme des béliers; vous, collines, comme des agneaux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Devant la face du Seigneur, tremble, ô terre! devant la face du ✝Dieu de Jacob,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Qui a changé le rocher en un étang d’eau, la pierre dure en une source d’eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Non point à nous, ô Éternel! non point à nous, mais à ton nom donne gloire, à cause de ta bonté, à cause de ta vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Pourquoi les nations diraient-elles: Où donc est leur Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Mais notre Dieu est aux cieux; tout ce qu’il lui a plu, il l’a fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Leurs idoles sont de l’argent et de l’or, ouvrage de mains d’homme:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Elles ont une bouche et ne parlent pas; elles ont des yeux et ne voient pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Elles ont des oreilles et n’entendent pas; elles ont un nez et ne sentent pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Elles ont des mains et ne touchent pas; des pieds, et ne marchent pas; elles ne rendent aucun son de leur gosier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Ceux qui les ont faites, tous ceux qui se confient en elles, sont comme elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israël, confie-toi en l’ Éternel: il est leur secours et leur bouclier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Maison d’Aaron, confiez-vous en l’ Éternel: il est leur secours et leur bouclier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Vous qui craignez l’ Éternel, confiez-vous en l’ Éternel: il est leur secours et leur bouclier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'L’ Éternel s’est souvenu de nous: il bénira, il bénira la maison d’Israël; il bénira la maison d’Aaron;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Il bénira ceux qui craignent l’ Éternel, les petits avec les grands.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'L’ Éternel vous augmentera [sa bénédiction], à vous et à vos fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Vous êtes bénis de l’ Éternel, qui a fait les cieux et la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Les cieux sont les cieux de l’ Éternel, mais il a donné la terre aux fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Ni les morts, ni tous ceux qui descendent dans le silence, ne loueront Jah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Mais nous, nous bénirons Jah, dès maintenant et à toujours. Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'J’ai aimé l’ Éternel, car il a entendu ma voix, mes supplications;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Car il a incliné son oreille vers moi, et je l’invoquerai durant mes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Les cordeaux de la mort m’avaient environné, et les détresses du shéol m’avaient atteint; j’avais trouvé la détresse et le chagrin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Mais j’invoquai le nom de l’ Éternel: Je te prie, ô Éternel! délivre mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'L’ Éternel est plein de grâce et juste, et notre Dieu est miséricordieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'L’ Éternel garde les simples; j’étais devenu misérable, et il m’a sauvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Mon âme, retourne en ton repos, car l’ Éternel t’a fait du bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Car tu as délivré mon âme de la mort, mes yeux de larmes, mes pieds de chute:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Je marcherai devant l’ Éternel dans la terre des vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'J’ai cru, c’est pourquoi j’ai parlé. J’ai été fort affligé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Je disais en mon agitation: Tout homme est menteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Que rendrai-je à l’ Éternel pour tous les biens qu’il m’a faits?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Je prendrai la coupe du salut, et j’invoquerai le nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'J’acquitterai mes vœux envers l’ Éternel, – oui, devant tout son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Précieuse, aux yeux de l’ Éternel, est la mort de ses saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Je te prie, ô Éternel! car je suis ton serviteur; je suis ton serviteur, le fils de ta servante; tu as délié mes liens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Je te sacrifierai des sacrifices d’actions de grâces, et j’invoquerai le nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'J’acquitterai mes vœux envers l’ Éternel, – oui, devant tout son peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'Dans les parvis de la maison de l’ Éternel, au milieu de toi, Jérusalem. Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Louez l’ Éternel, vous, toutes les nations; célébrez-le, vous, tous les peuples!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Car sa bonté est grande envers nous, et la vérité de l’ Éternel demeure à toujours. Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Célébrez l’ Éternel! Car il est bon; car sa bonté demeure à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Qu’Israël dise, que sa bonté demeure à toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Que la maison d’Aaron dise, que sa bonté demeure à toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Que ceux qui craignent l’ Éternel disent, que sa bonté demeure à toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Dans ma détresse j’ai invoqué Jah; Jah m’a répondu, [et m’a mis] au large.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'L’ Éternel est pour moi, je ne craindrai pas; que me fera l’homme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'L’ Éternel est pour moi entre ceux qui me secourent; et moi je verrai [mon plaisir] en ceux qui me haïssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Mieux vaut mettre sa confiance en l’ Éternel que de se confier en l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Mieux vaut mettre sa confiance en l’ Éternel que de se confier dans les principaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Toutes les nations m’avaient environné; au nom de l’ Éternel, certes je les ai détruites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Elles m’avaient environné, oui, environné; au nom de l’ Éternel, certes je les ai détruites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Elles m’avaient environné comme des abeilles; elles ont été éteintes comme un feu d’épines; au nom de l’ Éternel, certes je les ai détruites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Tu m’avais rudement poussé, pour que je tombe; mais l’ Éternel m’a été en secours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Jah a été ma force et mon cantique, et il a été mon salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'La voix de triomphe et de salut est dans les tentes des justes: la droite de l’ Éternel agit puissamment;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'La droite de l’ Éternel est haut élevée, la droite de l’ Éternel agit puissamment;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Je ne mourrai pas, mais je vivrai, et je raconterai les œuvres de Jah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Jah m’a sévèrement châtié, mais il ne m’a pas livré à la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Ouvrez-moi les portes de la justice; j’y entrerai, je célébrerai Jah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'C’est ici la porte de l’ Éternel, les justes y entreront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Je te célébrerai, car tu m’as répondu, et tu as été mon salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'La pierre que ceux qui bâtissaient avaient rejetée, est devenue la tête de l’angle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Ceci a été de par l’ Éternel: c’est une chose merveilleuse devant nos yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'C’est ici le jour que l’ Éternel a fait; égayons-nous et réjouissons-nous en lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Ô Éternel, sauve, je te prie! Éternel, je te prie, donne la prospérité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Béni soit celui qui vient au nom de l’ Éternel! Nous vous avons bénis de la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'L’ Éternel est ✶Dieu, et il nous a donné la lumière. Liez avec des cordes le sacrifice aux cornes de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Tu es mon ✶Dieu, et je te célébrerai, – mon Dieu, je t’exalterai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Célébrez l’ Éternel! car il est bon, car sa bonté demeure à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, '* Bienheureux ceux qui sont intègres dans leur voie, qui marchent dans la loi de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Bienheureux ceux qui gardent ses témoignages, qui le cherchent de tout leur cœur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Qui aussi ne font pas d’iniquité; ils marchent dans ses voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Tu as commandé tes préceptes pour qu’on les garde soigneusement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Oh, que mes voies soient dressées, pour garder tes statuts!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Alors je ne serai pas honteux quand je regarderai à tous tes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Je te célébrerai d’un cœur droit, quand j’aurai appris les ordonnances de ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Je garderai tes statuts; ne me délaisse pas tout à fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Comment un jeune homme rendra-t-il pure sa voie? Ce sera en y prenant garde selon ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Je t’ai cherché de tout mon cœur; ne me laisse pas m’égarer de tes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'J’ai caché ta parole dans mon cœur, afin que je ne pèche pas contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Éternel! tu es béni; enseigne-moi tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'J’ai raconté de mes lèvres toutes les ordonnances de ta bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'J’ai pris plaisir au chemin de tes témoignages, autant qu’à toutes les richesses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Je méditerai tes préceptes et je regarderai à tes sentiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Je fais mes délices de tes statuts, je n’oublierai pas ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Fais du bien à ton serviteur, [et] je vivrai et je garderai ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Ouvre mes yeux, et je verrai les merveilles qui sont dans ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Je suis étranger dans le pays; ne me cache pas tes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Mon âme est brisée par l’ardent désir qu’elle a en tout temps pour tes ordonnances.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Tu as tancé les orgueilleux, les maudits, qui s’égarent de tes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Roule de dessus moi l’opprobre et le mépris; car je garde tes témoignages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Les princes même se sont assis [et] parlent contre moi; ton serviteur médite tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Tes témoignages sont aussi mes délices, les hommes de mon conseil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Mon âme est attachée à la poussière; fais-moi vivre selon ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Je [t’]ai déclaré mes voies, et tu m’as répondu; enseigne-moi tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Fais-moi comprendre la voie de tes préceptes, et je méditerai sur tes merveilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Mon âme, de tristesse, se fond en larmes; affermis-moi selon ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Éloigne de moi la voie du mensonge, et, dans ta grâce, donne-moi ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'J’ai choisi la voie de la fidélité, j’ai placé [devant moi] tes jugements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Je suis attaché à tes témoignages: Éternel! ne me rends point honteux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Je courrai dans la voie de tes commandements, quand tu auras mis mon cœur au large.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Éternel! enseigne-moi la voie de tes statuts, et je l’observerai jusqu’à la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Donne-moi de l’intelligence, et j’observerai ta loi, et je la garderai de tout mon cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Fais-moi marcher dans le chemin de tes commandements, car j’y prends plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Incline mon cœur à tes témoignages, et non point au gain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Détourne mes yeux pour qu’ils ne regardent pas la vanité; fais-moi vivre dans ta voie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Confirme ta parole à ton serviteur, qui est [adonné] à ta crainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Détourne de moi l’opprobre que je crains; car tes jugements sont bons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Voici, j’ai ardemment désiré tes préceptes; fais-moi vivre dans ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Et que ta bonté vienne à moi, ô Éternel! – ton salut, selon ta parole!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Et j’aurai de quoi répondre à celui qui m’outrage; car je me suis confié en ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Et n’ôte pas entièrement de ma bouche la parole de la vérité; car je me suis attendu à tes jugements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Alors je garderai ta loi continuellement, à toujours et à perpétuité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Et je marcherai au large, car j’ai recherché tes préceptes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Et je parlerai de tes témoignages devant des rois, et je ne serai pas honteux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Et je trouverai mes délices en tes commandements que j’ai aimés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Et je lèverai mes mains vers tes commandements que j’ai aimés, et je méditerai tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Souviens-toi de ta parole à ton serviteur, à laquelle tu as fait que je me suis attendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'C’est ici ma consolation dans mon affliction, que ta parole m’a fait vivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Les orgueilleux se sont moqués de moi excessivement: je n’ai pas dévié de ta loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Je me suis souvenu de tes ordonnances de jadis, ô Éternel! et je me suis consolé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Une ardente indignation m’a saisi à cause des méchants qui abandonnent ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Tes statuts m’ont été des cantiques, dans la maison de mon pèlerinage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Je me suis souvenu de ton nom pendant la nuit, ô Éternel! et j’ai gardé ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Cela m’est arrivé, car j’ai observé tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Ma part, ô Éternel! je l’ai dit, c’est de garder tes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Je t’ai imploré de tout mon cœur: use de grâce envers moi selon ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'J’ai pensé à mes voies, et j’ai tourné mes pieds vers tes témoignages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Je me suis hâté, et je n’ai point différé de garder tes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Les cordes des méchants m’ont entouré: je n’ai pas oublié ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Je me lève à minuit pour te célébrer à cause des ordonnances de ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Je suis le compagnon de tous ceux qui te craignent, et de ceux qui gardent tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'La terre, ô Éternel! est pleine de ta bonté; enseigne-moi tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Tu as fait du bien à ton serviteur, ô Éternel! selon ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Enseigne-moi le bon sens et la connaissance; car j’ai ajouté foi à tes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Avant que je sois affligé, j’errais; mais maintenant je garde ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Tu es bon et bienfaisant; enseigne-moi tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Les orgueilleux ont inventé contre moi des mensonges; j’observerai tes préceptes de tout mon cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Leur cœur est épaissi comme la graisse; moi, je trouve mes délices en ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Il est bon pour moi que j’aie été affligé, afin que j’apprenne tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'La loi de ta bouche est meilleure pour moi que des milliers [de pièces] d’or et d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Tes mains m’ont fait et façonné; rends-moi intelligent, et j’apprendrai tes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Ceux qui te craignent me verront, et se réjouiront; car je me suis attendu à ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Je sais, ô Éternel! que tes jugements sont justice, et que c’est en fidélité que tu m’as affligé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Que ta bonté, je te prie, soit ma consolation, selon ta parole à ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Que tes compassions viennent sur moi, et je vivrai; car ta loi fait mes délices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Que les orgueilleux soient couverts de honte, car sans cause ils ont agi perversement envers moi; moi, je médite tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Que ceux qui te craignent se tournent vers moi, et ceux qui connaissent tes témoignages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Que mon cœur soit intègre dans tes statuts, afin que je ne sois pas honteux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Mon âme languit après ton salut; je m’attends à ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Mes yeux languissent après ta parole; et j’ai dit: Quand me consoleras-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Car je suis devenu comme une outre mise à la fumée; je n’oublie pas tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Combien [dureront] les jours de ton serviteur? Quand exécuteras-tu le jugement contre ceux qui me persécutent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Les orgueilleux ont creusé pour moi des fosses, ce qui n’est pas selon ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Tous tes commandements sont fidélité. On me persécute sans cause; aide-moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Peu s’en est fallu qu’ils ne m’aient consumé sur la terre; mais moi, je n’ai pas abandonné tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Selon ta bonté, fais-moi vivre, et je garderai le témoignage de ta bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Éternel! ta parole est établie à toujours dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Ta fidélité est de génération en génération. Tu as établi la terre, et elle demeure ferme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Selon tes ordonnances, [ces choses] demeurent fermes aujourd’hui; car toutes choses te servent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Si ta loi n’avait fait mes délices, j’aurais péri dans mon affliction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Jamais je n’oublierai tes préceptes, car par eux tu m’as fait vivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Je suis à toi, sauve-moi; car j’ai recherché tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Les méchants m’attendent pour me faire périr; [mais] je suis attentif à tes témoignages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'J’ai vu la fin de toute perfection; ton commandement est fort étendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Combien j’aime ta loi! tout le jour je la médite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Tes commandements m’ont rendu plus sage que mes ennemis, car ils sont toujours avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'J’ai plus d’intelligence que tous ceux qui m’enseignent, parce que je médite tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'J’ai plus de sens que les anciens, parce que j’observe tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'J’ai gardé mes pieds de toute mauvaise voie, afin que je garde ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Je ne me suis pas détourné de tes ordonnances, car c’est toi qui m’as instruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Que tes paroles ont été douces à mon palais, plus que le miel à ma bouche!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Par tes préceptes je suis devenu intelligent; c’est pourquoi je hais toute voie de mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Ta parole est une lampe à mon pied, et une lumière à mon sentier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'J’ai juré, et je le tiendrai, de garder les ordonnances de ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Je suis extrêmement affligé, ô Éternel! fais-moi vivre selon ta parole!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Agrée, je te prie, ô Éternel! les offrandes volontaires de ma bouche, et enseigne-moi tes ordonnances.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Ma vie est continuellement dans ma main, mais je n’oublie pas ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Les méchants m’ont tendu un piège; mais je ne me suis pas égaré de tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Tes témoignages me sont un héritage à toujours; car ils sont la joie de mon cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'J’ai incliné mon cœur à pratiquer tes statuts, à toujours, jusqu’à la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'J’ai eu en haine ceux qui sont doubles de cœur, mais j’aime ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Tu es mon asile et mon bouclier; je me suis attendu à ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Retirez-vous de moi, vous qui faites le mal, et j’observerai les commandements de mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Soutiens-moi selon ta parole, et je vivrai; et ne me laisse pas être confus en mon espérance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Soutiens-moi, et je serai sauvé, et je regarderai continuellement tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Tu as rejeté tous ceux qui s’égarent de tes statuts; car leur tromperie n’est que mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Tu ôtes tous les méchants de la terre, comme des scories; c’est pourquoi j’aime tes témoignages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Ma chair frissonne de la frayeur que j’ai de toi, et j’ai craint à cause de tes jugements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'J’ai pratiqué le jugement et la justice; ne m’abandonne pas à mes oppresseurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Sois le garant de ton serviteur pour [son] bien; que les orgueilleux ne m’oppriment pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Mes yeux languissent après ton salut et la parole de ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Agis envers ton serviteur selon ta bonté, et enseigne-moi tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Je suis ton serviteur; rends-moi intelligent, et je connaîtrai tes témoignages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Il est temps que l’ Éternel agisse: ils ont annulé ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'C’est pourquoi j’aime tes commandements plus que l’or, et que l’or épuré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'C’est pourquoi j’estime droits tous [tes] préceptes, à l’égard de toutes choses; je hais toute voie de mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Tes témoignages sont merveilleux; c’est pourquoi mon âme les observe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'L’entrée de tes paroles illumine, donnant de l’intelligence aux simples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'J’ai ouvert ma bouche, et j’ai soupiré; car j’ai un ardent désir de tes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Tourne-toi vers moi et use de grâce envers moi, selon ta coutume envers ceux qui aiment ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Affermis mes pas dans ta parole, et qu’aucune iniquité ne domine en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Rachète-moi de l’oppression de l’homme, et je garderai tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Fais luire ta face sur ton serviteur, et enseigne-moi tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Des ruisseaux d’eau coulent de mes yeux, parce qu’on ne garde pas ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Tu es juste, ô Éternel! et droit dans tes jugements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Tu as commandé la justice de tes témoignages, et la fidélité, strictement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Mon zèle m’a dévoré; car mes oppresseurs ont oublié tes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Ta parole est bien affinée, et ton serviteur l’aime.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Je suis petit et méprisé; je n’ai pas oublié tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Ta justice est une justice à toujours, et ta loi est vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'La détresse et l’angoisse m’avaient atteint; tes commandements sont mes délices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'La justice de tes témoignages est à toujours; donne-moi de l’intelligence, et je vivrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'J’ai crié de tout mon cœur; réponds-moi, Éternel! j’observerai tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Je t’invoque: sauve-moi! et je garderai tes témoignages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'J’ai devancé le crépuscule, et j’ai crié; je me suis attendu à ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Mes yeux ont devancé les veilles de la nuit pour méditer ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Écoute ma voix, selon ta bonté, ô Éternel! Fais-moi vivre selon ton ordonnance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Ceux qui poursuivent la méchanceté se sont approchés de moi; ils s’éloignent de ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Éternel! tu es proche; et tous tes commandements sont vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Dès longtemps j’ai connu, d’après tes témoignages, que tu les as fondés pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Vois mon affliction, et délivre-moi! Car je n’ai pas oublié ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Prends en main ma cause, et rachète-moi! Fais-moi vivre selon ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Le salut est loin des méchants, car ils ne recherchent pas tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Tes compassions sont en grand nombre, ô Éternel! – fais-moi vivre selon tes ordonnances.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Mes persécuteurs et mes oppresseurs sont en grand nombre; je n’ai point dévié de tes témoignages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'J’ai vu les perfides, et j’en ai eu horreur, parce qu’ils ne gardaient pas ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Considère que j’ai aimé tes préceptes; Éternel! fais-moi vivre selon ta bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'La somme de ta parole est [la] vérité, et toute ordonnance de ta justice est pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Des princes m’ont persécuté sans cause; mais mon cœur a eu peur de ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'J’ai de la joie en ta parole, comme un [homme] qui trouve un grand butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Je hais, et j’ai en horreur le mensonge; j’aime ta loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Sept fois le jour je te loue, à cause des ordonnances de ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Grande est la paix de ceux qui aiment ta loi; et pour eux il n’y a pas de chute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'J’ai espéré en ton salut, ô Éternel! et j’ai pratiqué tes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Mon âme a gardé tes témoignages, et je les aime beaucoup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'J’ai gardé tes préceptes et tes témoignages; car toutes mes voies sont devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Que mon cri parvienne devant toi, ô Éternel! Rends-moi intelligent, selon ta parole!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Que ma supplication vienne devant toi; délivre-moi selon ta parole!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Mes lèvres publieront [ta] louange, quand tu m’auras enseigné tes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Ma langue parlera haut de ta parole; car tous tes commandements sont justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Ta main me sera pour secours, car j’ai choisi tes préceptes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'J’ai ardemment désiré ton salut, ô Éternel! et ta loi est mes délices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Que mon âme vive, et elle te louera; et fais que tes ordonnances me soient en aide!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'J’ai erré comme une brebis qui périt: cherche ton serviteur, car je n’ai pas oublié tes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, '*Cantique des degrés. À l’ Éternel, en ma détresse, j’ai crié; et il m’a répondu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Éternel! délivre mon âme de la lèvre menteuse, de la langue qui trompe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Que te donnera-t-on, et que t’ajoutera-t-on, langue trompeuse? –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Des flèches aiguës d’un homme puissant, et des charbons ardents de genêt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Malheur à moi de ce que je séjourne en Méshec, de ce que je demeure avec les tentes de Kédar; –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Que mon âme ait tant demeuré avec ceux qui haïssent la paix!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Je veux la paix; mais si j’en parle, ils sont, eux, pour la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Cantique des degrés. J’élève mes yeux vers les montagnes d’où vient mon secours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Mon secours [vient] d’auprès de l’ Éternel, qui a fait les cieux et la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Il ne permettra point que ton pied soit ébranlé; celui qui te garde ne sommeillera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Voici, celui qui garde Israël ne sommeillera pas, et ne dormira pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'L’ Éternel est celui qui te garde; l’ Éternel est ton ombre, à ta main droite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Le soleil ne te frappera pas de jour, ni la lune de nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'L’ Éternel te gardera de tout mal; il gardera ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'L’ Éternel gardera ta sortie et ton entrée, dès maintenant et à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Cantique des degrés. De David. Je me suis réjoui quand ils m’ont dit: Allons à la maison de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Nos pieds se tiendront dans tes portes, ô Jérusalem!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jérusalem, qui es bâtie comme une ville bien unie ensemble en elle-même!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'C’est là que montent les tribus, les tribus de Jah, un témoignage à Israël, pour célébrer le nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Car là sont placés les trônes de jugement, les trônes de la maison de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Demandez la paix de Jérusalem; ceux qui t’aiment prospéreront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Que la paix soit dans tes murs, la prospérité dans tes palais!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'À cause de mes frères et de mes compagnons, je dirai: Que la paix soit en toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'À cause de la maison de l’ Éternel, notre Dieu, je rechercherai ton bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Cantique des degrés. J’élève mes yeux vers toi, qui habites dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Voici, comme les yeux des serviteurs [regardent] à la main de leurs maîtres, comme les yeux de la servante à la main de sa maîtresse, ainsi nos yeux [regardent] à l’ Éternel, notre Dieu, jusqu’à ce qu’il use de grâce envers nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Use de grâce envers nous, ô Éternel! use de grâce envers nous; car nous sommes, outre mesure, rassasiés de mépris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Nos âmes sont, outre mesure, rassasiées des insultes de ceux qui sont à l’aise, du mépris des orgueilleux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Cantique des degrés. De David. N’eût été l’ Éternel, qui a été pour nous, – qu’Israël le dise,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'N’eût été l’ Éternel, qui a été pour nous quand les hommes se sont élevés contre nous, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Alors ils nous auraient engloutis vivants, quand leur colère s’enflammait contre nous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Alors les eaux nous auraient submergés, un torrent aurait passé sur notre âme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Alors les eaux orgueilleuses auraient passé sur notre âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Béni soit l’ Éternel, qui ne nous a pas livrés en proie à leurs dents!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Notre âme est échappée comme un oiseau du piège des oiseleurs: le piège s’est rompu, et nous sommes échappés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Notre secours est dans le nom de l’ Éternel, qui a fait les cieux et la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Cantique des degrés. Ceux qui se confient en l’ Éternel sont comme la montagne de Sion, qui ne chancelle pas, qui demeure à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Jérusalem! – des montagnes sont autour d’elle, et l’ Éternel est autour de son peuple, dès maintenant et à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Car le bâton de la méchanceté ne reposera pas sur le lot des justes; afin que les justes n’étendent pas leur main vers l’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Éternel! fais du bien aux gens de bien et à ceux qui sont droits dans leur cœur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Mais quant à ceux qui se détournent dans leurs voies tortueuses, l’ Éternel les fera marcher avec les ouvriers d’iniquité. La paix soit sur Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Cantique des degrés. Quand l’ Éternel rétablit les captifs de Sion, nous étions comme ceux qui songent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Alors notre bouche fut remplie de rire, et notre langue de chants de joie; alors on dit parmi les nations: L’ Éternel a fait de grandes choses pour ceux-ci!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'L’ Éternel a fait de grandes choses pour nous; nous en avons été réjouis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Ô Éternel! rétablis nos captifs, comme les ruisseaux dans le midi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Ceux qui sèment avec larmes moissonneront avec chant de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Il va en pleurant, portant la semence qu’il répand; il revient avec chant de joie, portant ses gerbes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Cantique des degrés. De Salomon. Si l’ Éternel ne bâtit la maison, ceux qui la bâtissent y travaillent en vain; si l’ Éternel ne garde la ville, celui qui la garde veille en vain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'C’est en vain que vous vous levez matin, que vous vous couchez tard, que vous mangez le pain de douleurs. Ainsi, il donne le sommeil à son bien-aimé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Voici, les fils sont un héritage de l’ Éternel, [et] le fruit du ventre est une récompense.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Comme des flèches dans la main d’un homme puissant, tels sont les fils de la jeunesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Bienheureux l’homme qui en a rempli son carquois! Ils n’auront pas honte quand ils parleront avec des ennemis dans la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Cantique des degrés. Bienheureux quiconque craint l’ Éternel, [et] marche dans ses voies!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Car tu mangeras du travail de tes mains; tu seras bienheureux, et tu seras entouré de biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Ta femme sera au-dedans de ta maison comme une vigne féconde; tes fils seront comme des plants d’oliviers autour de ta table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Voici, ainsi sera béni l’homme qui craint l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'L’ Éternel te bénira de Sion. Et puisses-tu voir le bien de Jérusalem tous les jours de ta vie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Et voir des fils de tes fils! La paix soit sur Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Cantique des degrés. Ils m’ont souvent opprimé dès ma jeunesse, – qu’Israël le dise, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Ils m’ont souvent opprimé dès ma jeunesse; cependant ils n’ont pas prévalu sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Des laboureurs ont labouré mon dos, ils y ont tracé leurs longs sillons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'L’ Éternel est juste; il a coupé les cordes des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Qu’ils soient couverts de honte, et se retirent en arrière, tous ceux qui haïssent Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Qu’ils soient comme l’herbe des toits, qui sèche avant qu’on l’arrache,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Dont le moissonneur ne remplit pas sa main, ni le lieur de gerbes son sein;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Et les passants ne disent pas: La bénédiction de l’ Éternel soit sur vous! nous vous bénissons au nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Cantique des degrés. Je t’ai invoqué des lieux profonds, ô Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Seigneur! écoute ma voix; que tes oreilles soient attentives à la voix de mes supplications.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Ô Jah! si tu prends garde aux iniquités, Seigneur, qui subsistera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Mais il y a pardon auprès de toi, afin que tu sois craint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'J’ai attendu l’ Éternel; mon âme l’a attendu, et j’ai eu mon attente en sa parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Mon âme [attend] le Seigneur, plus que les sentinelles [n’attendent] le matin, que les sentinelles [n’attendent] le matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Israël, attends-toi à l’ Éternel; car auprès de l’ Éternel est la bonté, et il y a rédemption en abondance auprès de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Et lui rachètera Israël de toutes ses iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Cantique des degrés. De David. Éternel! mon cœur n’est pas hautain, et mes yeux ne s’élèvent pas; et je n’ai pas marché en des choses trop grandes et trop merveilleuses pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'N’ai-je pas soumis et fait taire mon âme, comme un enfant sevré auprès de sa mère? Mon âme est en moi comme l’enfant sevré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israël, attends-toi à l’ Éternel, dès maintenant et à toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Cantique des degrés. Éternel, souviens-toi de David, [et] de toutes ses afflictions!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Comment il a juré à l’ Éternel, [et] fait un vœu au Puissant de Jacob:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Si j’entre dans la demeure de ma maison, si je monte sur le lit où je couche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Si je permets à mes yeux de dormir, à mes paupières de sommeiller,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Jusqu’à ce que j’aie trouvé un lieu pour l’ Éternel, des demeures pour le Puissant de Jacob!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Voici, nous avons entendu parler d’elle à Éphrata, nous l’avons trouvée dans les champs de Jaar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Entrons dans ses demeures, prosternons-nous devant le marchepied de ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Lève-toi, Éternel! pour [entrer dans] ton repos, toi et l’arche de ta force!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Que tes sacrificateurs soient revêtus de justice, et que tes saints chantent de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'À cause de David, ton serviteur, ne repousse pas la face de ton oint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'L’ Éternel a juré à David [en] vérité, il n’en reviendra pas: Je mettrai du fruit de ton ventre sur ton trône.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Si tes enfants gardent mon alliance et mes témoignages que je leur enseignerai, leurs fils aussi seront assis à perpétuité sur ton trône.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Car l’ Éternel a choisi Sion; il l’a désirée pour être son habitation:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'C’est ici mon repos à perpétuité; ici j’habiterai, car je l’ai désirée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Je bénirai abondamment ses vivres, je rassasierai de pain ses pauvres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Et je revêtirai de salut ses sacrificateurs, et ses saints exulteront en chantant de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Là je ferai germer la corne de David, j’ai préparé une lampe à mon oint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Je revêtirai de honte ses ennemis; et sur lui fleurira sa couronne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Cantique des degrés. De David. Voici, qu’il est bon et qu’il est agréable que des frères habitent unis ensemble!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'C’est comme l’huile précieuse, [répandue] sur la tête, qui descendait sur la barbe, la barbe d’Aaron, qui descendait sur le bord de ses vêtements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Comme la rosée de l’Hermon, qui descend sur les montagnes de Sion; car c’est là que l’ Éternel a commandé la bénédiction, la vie pour l’éternité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Cantique des degrés. Voici, bénissez l’ Éternel, vous, tous les serviteurs de l’ Éternel, qui vous tenez durant les nuits dans la maison de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Élevez vos mains dans le lieu saint, et bénissez l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Que l’ Éternel, qui a fait les cieux et la terre, te bénisse de Sion!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, '*Louez Jah. Louez le nom de l’ Éternel; louez-[le], serviteurs de l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Qui vous tenez dans la maison de l’ Éternel, dans les parvis de la maison de notre Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Louez Jah! car l’ Éternel est bon. Chantez des cantiques à [la gloire de] son nom! car il est agréable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Car Jah s’est choisi Jacob, Israël pour son trésor particulier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Car je sais que l’ Éternel est grand, et que notre Seigneur est au-dessus de tous les dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Tout ce qu’il lui a plu de faire, l’ Éternel l’a fait, dans les cieux et sur la terre, dans les mers et dans tous les abîmes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Lui qui fait monter les vapeurs du bout de la terre, qui fait les éclairs pour la pluie, qui de ses trésors fait sortir le vent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Lui qui a frappé les premiers-nés d’Égypte, depuis l’homme jusqu’à la bête;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Qui a envoyé des signes et des prodiges au milieu de toi, ô Égypte! contre le Pharaon et contre tous ses serviteurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Qui a frappé de nombreuses nations et tué de puissants rois,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sihon, roi des Amoréens, et Og, roi de Basan, et tous les royaumes de Canaan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'Et qui a donné leur pays en héritage, en héritage à Israël, son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Éternel! ton nom est à toujours; Éternel! ta mémoire est de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Car l’ Éternel jugera son peuple, et se repentira en faveur de ses serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Les idoles des nations sont de l’argent et de l’or, ouvrage de mains d’homme:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Elles ont une bouche, et ne parlent pas; elles ont des yeux, et ne voient pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Elles ont des oreilles, et n’entendent pas; il n’y a pas non plus de respiration dans leur bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Ceux qui les ont faites, tous ceux qui se confient en elles, sont comme elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Maison d’Israël, bénissez l’ Éternel! Maison d’Aaron, bénissez l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Maison de Lévi, bénissez l’ Éternel! Vous qui craignez l’ Éternel, bénissez l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Béni soit, de Sion, l’ Éternel, qui habite à Jérusalem! Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Célébrez l’ Éternel! Car il est bon; car sa bonté demeure à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Célébrez le Dieu des dieux! car sa bonté demeure à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Célébrez le Seigneur des seigneurs! car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Celui qui seul fait de grandes merveilles, car sa bonté demeure à toujours:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Qui a fait les cieux par [son] intelligence, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Qui a étendu la terre sur les eaux, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Qui a fait de grands luminaires, car sa bonté demeure à toujours:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Le soleil pour dominer sur le jour, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'La lune et les étoiles pour dominer sur la nuit, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Qui a frappé l’Égypte en ses premiers-nés, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Et a fait sortir Israël du milieu d’eux, car sa bonté demeure à toujours, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'À main forte et à bras étendu, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Qui a divisé en deux la mer Rouge, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'Et a fait passer Israël au milieu d’elle, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Et a précipité le Pharaon et son armée dans la mer Rouge, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Qui a conduit son peuple par le désert, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Qui a frappé de grands rois, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'Et a tué de puissants rois, car sa bonté demeure à toujours:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihon, roi des Amoréens, car sa bonté demeure à toujours,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Et Og, roi de Basan, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'Et a donné leur pays en héritage, car sa bonté demeure à toujours, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'En héritage à Israël, son serviteur, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Qui, dans notre bas état, s’est souvenu de nous, car sa bonté demeure à toujours,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'Et nous a délivrés de nos ennemis, car sa bonté demeure à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Qui donne du pain à toute chair, car sa bonté demeure à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Célébrez le ✶Dieu des cieux! Car sa bonté demeure à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, '*Auprès des fleuves de Babylone, là nous nous sommes assis, et nous avons pleuré quand nous nous sommes souvenus de Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Aux saules qui étaient au milieu d’elle nous avons suspendu nos harpes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Car là, ceux qui nous avaient emmenés captifs nous demandaient des cantiques, et ceux qui nous faisaient gémir, de la joie: Chantez-nous un des cantiques de Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Comment chanterions-nous un cantique de l’ Éternel sur un sol étranger?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Si je t’oublie, ô Jérusalem, que ma droite s’oublie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Que ma langue s’attache à mon palais si je ne me souviens de toi, si je n’élève Jérusalem au-dessus de la première de mes joies!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Éternel! souviens-toi des fils d’Édom, qui, dans la journée de Jérusalem, disaient: Rasez, rasez jusqu’à ses fondements!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Fille de Babylone, qui vas être détruite, bienheureux qui te rendra la pareille de ce que tu nous as fait!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Bienheureux qui saisira tes petits enfants, et les écrasera contre le roc!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'De David. Je te célébrerai de tout mon cœur; je chanterai tes louanges devant les dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Je me prosternerai vers le temple de ta sainteté, et je célébrerai ton nom à cause de ta bonté et à cause de ta vérité; car tu as exalté ta parole au-dessus de tout ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Au jour où j’ai crié, tu m’as répondu; tu as augmenté la force de mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Tous les rois de la terre te célébreront, ô Éternel! quand ils auront entendu les paroles de ta bouche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Et ils chanteront dans les voies de l’ Éternel, car grande est la gloire de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Car l’ Éternel est haut élevé; mais il voit ceux qui sont en bas état, et il connaît de loin les hautains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Si je marche au milieu de la détresse, tu me feras vivre, tu étendras ta main contre la colère de mes ennemis, et ta droite me sauvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'L’ Éternel achèvera ce qui me concerne. Éternel! ta bonté demeure à toujours. N’abandonne pas les œuvres de tes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Au chef de musique. De David. Psaume. Éternel! tu m’as sondé, et tu m’as connu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Tu connais quand je m’assieds et quand je me lève, tu discernes de loin ma pensée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Tu connais mon sentier et mon coucher, et tu es au fait de toutes mes voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Car la parole n’est pas encore sur ma langue, que voilà, ô Éternel! tu la connais tout entière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Tu me tiens serré par-derrière et par-devant, et tu as mis ta main sur moi,...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Connaissance trop merveilleuse pour moi, si élevée que je n’y puis [atteindre]!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Où irai-je loin de ton Esprit? et où fuirai-je loin de ta face?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Si je monte aux cieux, tu y es; si je me couche au shéol, t’y voilà.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Si je prends les ailes de l’aube du jour, si je fais ma demeure au bout de la mer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'Là aussi ta main me conduira et ta droite me saisira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Et si je dis: Au moins les ténèbres m’envelopperont, – alors la nuit est lumière autour de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Les ténèbres même ne sont pas obscures pour [me] cacher à toi, et la nuit resplendit comme le jour, l’obscurité est comme la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Car tu as possédé mes reins, tu m’as tissé dans le ventre de ma mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Je te célébrerai de ce que j’ai été fait d’une étrange et admirable manière. Tes œuvres sont merveilleuses, et mon âme le sait très bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Mes os ne t’ont point été cachés lorsque j’ai été fait dans le secret, façonné comme une broderie dans les lieux bas de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Tes yeux ont vu ma substance informe, et dans ton livre [mes membres] étaient tous écrits; de jour en jour ils se formaient, lorsqu’il n’y en avait [encore] aucun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Combien me sont précieuses tes pensées, ô ✶Dieu! combien en est grande la somme!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Si je veux les compter, elles sont plus nombreuses que le sable. Si je me réveille, je suis encore avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Ô ✝Dieu! si tu voulais tuer le méchant! Et vous, hommes de sang, retirez-vous de moi;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Eux qui parlent contre toi astucieusement, qui prennent [ton nom] en vain, tes ennemis!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'N’ai-je pas en haine, ô Éternel, ceux qui te haïssent? et n’ai-je pas en horreur ceux qui s’élèvent contre toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Je les hais d’une parfaite haine; ils sont pour moi des ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Sonde-moi, ô ✶Dieu! et connais mon cœur; éprouve-moi, et connais mes pensées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Et regarde s’il y a en moi quelque voie de chagrin, et conduis-moi dans la voie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Au chef de musique. Psaume de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Éternel! délivre-moi de l’homme mauvais, préserve-moi de l’homme violent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Qui méditent le mal dans leur cœur: tous les jours ils s’assemblent pour la guerre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Ils affilent leur langue comme un serpent, il y a du venin d’aspic sous leurs lèvres. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Éternel! garde-moi des mains du méchant, préserve-moi de l’homme violent, qui méditent de faire trébucher mes pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Les orgueilleux m’ont caché un piège et des cordes, ils ont étendu un filet le long du chemin, ils m’ont dressé des lacets. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'J’ai dit à l’ Éternel: Tu es mon ✶Dieu. Prête l’oreille, ô Éternel, à la voix de mes supplications!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'L’ Éternel, le Seigneur, est la force de mon salut; tu as couvert ma tête au jour des armes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'N’accorde pas, ô Éternel! les souhaits du méchant, ne fais pas réussir son dessein: ils s’élèveraient. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Quant à la tête de ceux qui m’environnent,... que le mal de leurs lèvres les couvre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Que des charbons ardents tombent sur eux! Fais-les tomber dans le feu, dans des eaux profondes, et qu’ils ne se relèvent pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Que l’homme à [mauvaise] langue ne soit point établi dans le pays: l’homme violent, le mal le poussera à sa ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Je sais que l’ Éternel maintiendra la cause de l’affligé, le jugement des pauvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 14, 'Certainement, les justes célébreront ton nom, les hommes droits habiteront devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Psaume de David. Éternel! je t’ai invoqué; hâte-toi vers moi. Prête l’oreille à ma voix, quand je crie à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Que ma prière vienne devant toi comme l’encens, l’élévation de mes mains comme l’offrande du soir!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Mets, ô Éternel! une garde à ma bouche, veille sur l’entrée de mes lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'N’incline mon cœur à aucune chose mauvaise, pour pratiquer de méchantes actions avec des hommes qui sont des ouvriers d’iniquité; et que je ne mange pas de leurs délices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Que le juste me frappe, c’est une faveur; qu’il me reprenne, c’est une huile excellente; ma tête ne la refusera pas, car ma prière sera encore là dans leurs calamités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Que leurs juges soient précipités des rochers, alors ils entendront mes paroles, car elles sont douces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Nos os sont dispersés à la gueule du shéol, comme quand on coupe et qu’on fend [du bois] sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Car, ô Éternel, Seigneur! mes yeux sont sur toi, je me confie en toi; n’abandonne pas mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Garde-moi du piège qu’ils m’ont tendu, et des lacets des ouvriers d’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Que les méchants tombent dans leurs propres filets, tandis que moi je passe outre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Instruction de David; lorsqu’il était dans la caverne. Prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'De ma voix, je crie à l’ Éternel; de ma voix, je supplie l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Je répands devant lui ma plainte, je déclare ma détresse devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Quand mon esprit était accablé en moi, toi tu as connu mon sentier. Sur le chemin par lequel je marchais, ils m’ont caché un piège.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Regarde à droite, et vois; il n’y a personne qui me reconnaisse; tout refuge est perdu pour moi; il n’y a personne qui s’enquière de mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'J’ai crié vers toi, Éternel! j’ai dit: Tu es mon refuge, ma part dans la terre des vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Sois attentif à mon cri, car je suis très misérable; délivre-moi de mes persécuteurs, car ils sont plus forts que moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 8, 'Fais sortir mon âme de la prison, pour célébrer ton nom. Les justes m’environneront, parce que tu m’auras fait du bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Psaume de David. Éternel! écoute ma prière; prête l’oreille à mes supplications; dans ta fidélité réponds-moi dans ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Et n’entre pas en jugement avec ton serviteur, car devant toi nul homme vivant ne sera justifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Car l’ennemi poursuit mon âme, il foule ma vie par terre; il me fait habiter dans des lieux ténébreux, comme ceux qui sont morts depuis longtemps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Et mon esprit est accablé en moi, mon cœur est désolé au-dedans de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Je me souviens des jours d’autrefois, je pense à tous tes actes, je médite les œuvres de tes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'J’étends mes mains vers toi; mon âme, comme une terre altérée, [a soif] de toi. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Éternel! hâte-toi, réponds-moi! mon esprit défaille en moi. Ne me cache pas ta face! autrement je serai semblable à ceux qui descendent dans la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Fais-moi entendre dès le matin ta bonté, car en toi j’ai mis ma confiance; fais-moi connaître le chemin où j’ai à marcher, car c’est à toi que j’élève mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Éternel! délivre-moi de mes ennemis! c’est vers toi que je me réfugie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Enseigne-moi à faire ce qui te plaît, car tu es mon Dieu; que ton bon Esprit me conduise dans un pays uni.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'À cause de ton nom, ô Éternel! fais-moi vivre; dans ta justice, fais sortir mon âme de la détresse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Et, dans ta bonté, extermine mes ennemis, et détruis tous ceux qui oppriment mon âme; car je suis ton serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'De David. Béni soit l’ Éternel, mon rocher! qui enseigne mes mains pour le combat, mes doigts pour la bataille,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Ma bonté et mon lieu fort, ma haute retraite et celui qui me délivre, mon bouclier et celui en qui je me réfugie; il assujettit mon peuple sous moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Éternel! qu’est-ce que l’homme, que tu prennes connaissance de lui?... le fils de l’homme, que tu tiennes compte de lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'L’homme ressemble à la vanité; ses jours sont comme une ombre qui passe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Éternel! abaisse tes cieux et descends; touche les montagnes, et elles fumeront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Fais briller l’éclair et disperse-les; lance tes flèches et mets-les en déroute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Étends tes mains d’en haut; arrache-moi et délivre-moi des grandes eaux, de la main des fils de l’étranger,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Dont la bouche profère la vanité et dont la droite est une droite de mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Ô Dieu! je te chanterai un cantique nouveau; je te célébrerai sur le luth à dix [cordes],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Toi qui donnes le salut aux rois, toi qui délivres David, ton serviteur, de l’épée funeste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Arrache-moi et délivre-moi de la main des fils de l’étranger, dont la bouche profère la vanité et dont la droite est une droite de mensonge,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Afin que nos fils soient comme des plantes croissant dans leur jeunesse, [et] nos filles comme des pierres d’angle, ornementées selon le style des palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Que nos greniers soient pleins, fournissant toute espèce [de provisions]; que nos troupeaux se multiplient par milliers, par dix milliers dans nos campagnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Que nos génisses soient fécondes; qu’il n’y ait pas de brèche, pas de sortie, et pas de cri dans nos rues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Bienheureux le peuple pour qui il en est ainsi! Bienheureux le peuple qui a l’ Éternel pour son Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Louange de David. Je t’exalterai, mon Dieu, ô Roi! et je bénirai ton nom à toujours et à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Je te bénirai chaque jour, et je louerai ton nom à toujours et à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'L’ Éternel est grand et fort digne de louange; et sa grandeur est insondable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Une génération célébrera tes œuvres auprès de l’autre génération, et elles raconteront tes actes puissants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Je parlerai de la magnificence glorieuse de ta majesté, et de tes actes merveilleux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Et ils diront la force de tes actes terribles, et [moi], je déclarerai tes grands faits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Ils feront jaillir la mémoire de ta grande bonté, et ils chanteront hautement ta justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'L’ Éternel est plein de grâce et miséricordieux, lent à la colère, et grand en bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'L’ Éternel est bon envers tous, et ses compassions sont sur toutes ses œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Toutes tes œuvres te célébreront, ô Éternel! et tes saints te béniront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Ils parleront de la gloire de ton royaume, et ils diront ta puissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Afin de faire connaître aux fils de l’homme ses actes puissants et la magnificence glorieuse de son royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Ton royaume est un royaume de tous les siècles, et ta domination est de toutes les générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'L’ Éternel soutient tous ceux qui tombent, et relève tous ceux qui sont courbés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Les yeux de tous s’attendent à toi, et tu leur donnes leur nourriture en son temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Tu ouvres ta main, et tu rassasies à souhait tout ce qui a vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'L’ Éternel est juste dans toutes ses voies, et bon dans toutes ses œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'L’ Éternel est près de tous ceux qui l’invoquent, de tous ceux qui l’invoquent en vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Il accomplit le souhait de ceux qui le craignent: il entend leur cri, et les sauve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'L’ Éternel garde tous ceux qui l’aiment, et il extermine tous les méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Ma bouche dira la louange de l’ Éternel; et que toute chair bénisse son saint nom, à toujours et à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, '*Louez Jah. Mon âme, loue l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Je louerai l’ Éternel durant ma vie; je chanterai des cantiques à mon Dieu tant que j’existerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Ne vous confiez pas dans les principaux, dans un fils d’homme, en qui il n’y a pas de salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Son esprit sort, l’homme retourne dans le sol d’où il est tiré; en ce même jour ses desseins périssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Bienheureux celui qui a le ✶Dieu de Jacob pour son secours, qui s’attend à l’ Éternel, son Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Qui a fait les cieux et la terre, la mer, et tout ce qui s’y trouve; qui garde la vérité à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Qui exécute le jugement en faveur des opprimés; qui donne du pain à ceux qui ont faim! L’ Éternel met en liberté les prisonniers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'L’ Éternel ouvre les yeux des aveugles; l’ Éternel relève ceux qui sont courbés; l’ Éternel aime les justes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'L’ Éternel garde les étrangers; il affermit l’orphelin et la veuve, et confond la voie des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'L’ Éternel régnera à toujours, – ton Dieu, ô Sion! de génération en génération. Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Louez Jah! car c’est une chose bonne. Chantez les louanges de notre Dieu! car c’est une chose agréable. La louange est bienséante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'L’ Éternel bâtit Jérusalem; il rassemble les exilés d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'C’est lui qui guérit ceux qui ont le cœur brisé, et qui bande leurs plaies;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Qui compte le nombre des étoiles: à elles toutes il donne des noms.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Notre Seigneur est grand et d’une grande puissance; son intelligence est sans bornes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'L’ Éternel affermit les débonnaires; il renverse les méchants jusqu’en terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Chantez à l’ Éternel avec actions de grâces, psalmodiez sur la harpe à notre Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Qui couvre de nuages les cieux, qui prépare la pluie pour la terre, qui fait germer l’herbe sur les montagnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Qui donne la nourriture au bétail, [et] aux petits du corbeau qui crient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Il ne trouve pas son plaisir en la force du cheval, il ne se complaît pas aux jambes de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Le plaisir de l’ Éternel est en ceux qui le craignent, en ceux qui s’attendent à sa bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Jérusalem, célèbre l’ Éternel! Sion, loue ton Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Car il rend fortes les barres de tes portes; il bénit tes fils au milieu de toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Il met la paix dans tes confins; il te rassasie de la moelle du froment;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Il envoie ses oracles sur la terre: sa parole court avec vitesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'C’est lui qui donne la neige comme de la laine, qui répand la gelée blanche comme de la cendre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Il jette sa glace comme par morceaux: qui peut subsister devant son froid?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Il envoie sa parole et les fait fondre; il fait souffler son vent: les eaux coulent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Il annonce ses paroles à Jacob, ses statuts et ses ordonnances à Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Il n’a fait ainsi à aucune nation; et ses ordonnances, elles ne les ont pas connues. Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Louez Jah. Louez, des cieux, l’ Éternel! Louez-le dans les lieux élevés!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Louez-le, vous, tous ses anges! Louez-le, vous, toutes ses armées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Louez-le, soleil et lune! Louez-le, vous, toutes les étoiles de lumière!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Louez-le, cieux des cieux, et vous, eaux qui êtes au-dessus des cieux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Qu’ils louent le nom de l’ Éternel; car c’est lui qui a commandé, et ils ont été créés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Et il les a établis à perpétuité et pour toujours; il a rendu son décret, et il ne passera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Louez, de la terre, l’ Éternel, vous, monstres des eaux, et vous, tous les abîmes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Feu et grêle, neige et vapeur, vent de tempête qui exécutes sa parole;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Montagnes, et [vous], toutes les collines, arbres fruitiers, et tous les cèdres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Animaux et tout le bétail, reptiles et oiseaux ailés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Rois de la terre et tous les peuples, princes et tous les juges de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Jeunes hommes et les vierges aussi; [vous], vieillards, avec les jeunes gens:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Qu’ils louent le nom de l’ Éternel! car son nom seul est haut élevé; sa majesté est au-dessus de la terre et des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Et il exaltera la corne de son peuple, la louange de tous ses saints, – des fils d’Israël, le peuple qui est près de lui. Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Louez Jah. Chantez à l’ Éternel un cantique nouveau! [Chantez] sa louange dans la congrégation des saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Qu’Israël se réjouisse en celui qui l’a fait; que les fils de Sion s’égaient en leur roi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Qu’ils louent son nom avec des danses, qu’ils chantent ses louanges avec le tambourin et avec la harpe!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Car l’ Éternel prend plaisir en son peuple; il pare les débonnaires de salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Que les saints se réjouissent de la gloire, qu’ils exultent avec chant de triomphe sur leurs lits!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Les louanges de ✶Dieu sont dans leur bouche, et une épée à deux tranchants dans leur main,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Pour exécuter la vengeance contre les nations, des châtiments au milieu des peuples;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Pour lier leurs rois de chaînes, et leurs nobles de ceps de fer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Pour exécuter contre eux le jugement qui est écrit. Cette gloire est pour tous ses saints. Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Louez Jah. Louez ✶Dieu dans son saint lieu! Louez-le dans le firmament de sa force!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Louez-le pour ses actes puissants! Louez-le pour l’étendue de sa grandeur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Louez-le avec le son retentissant de la trompette! Louez-le avec le luth et la harpe!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Louez-le avec le tambourin et la danse! Louez-le avec des instruments à cordes et le chalumeau!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Louez-le avec les cymbales sonores! Louez-le avec les cymbales retentissantes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Que tout ce qui respire loue Jah! Louez Jah!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Proverbes de Salomon, fils de David, roi d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'pour connaître la sagesse et l’instruction, pour discerner les paroles d’intelligence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'pour recevoir instruction dans la sagesse, la justice, le juste jugement, et la droiture;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'pour donner aux simples de la prudence, au jeune homme de la connaissance et de la réflexion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Le sage écoutera, et croîtra en science, et l’intelligent acquerra du sens');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'pour comprendre un proverbe et une allégorie, les paroles des sages et leurs énigmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'La crainte de l’ Éternel est le commencement de la connaissance; les fous méprisent la sagesse et l’instruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Écoute, mon fils, l’instruction de ton père, et n’abandonne pas l’enseignement de ta mère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'car ce sera une guirlande de grâce à ta tête, et des colliers à ton cou.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Mon fils, si les pécheurs cherchent à te séduire, n’y acquiesce pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'S’ils disent: Viens avec nous, nous serons aux embûches pour le sang, nous nous cacherons pour [guetter] l’innocent, sans cause;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'nous les engloutirons vivants, comme le shéol, et tout entiers comme ceux qui descendent dans la fosse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'nous trouverons toute sorte de biens précieux, nous remplirons nos maisons de butin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'prends ton lot parmi nous, il n’y aura qu’une bourse pour nous tous:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'mon fils, ne fais pas route avec eux, retiens ton pied de leur sentier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'car leurs pieds courent au mal, et ils se hâtent pour verser le sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Car en vain le filet est étendu devant les yeux de tout ce qui a des ailes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'et eux, ils sont aux embûches contre leur propre sang, ils se cachent pour [guetter] leurs propres âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Telles sont les voies de tout homme qui cherche le gain déshonnête, lequel ôte la vie à ceux qui le possèdent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'La sagesse crie au-dehors, elle fait retentir sa voix sur les places;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'elle crie à l’entrée des lieux bruyants, aux ouvertures des portes; elle prononce ses paroles dans la ville:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Simples, jusques à quand aimerez-vous la simplicité, et [jusques à quand] les moqueurs prendront-ils plaisir à la moquerie, et les sots haïront-ils la connaissance?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Revenez à ma répréhension; voici, je ferai couler pour vous mon esprit, je vous ferai savoir mes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Parce que j’ai crié et que vous avez refusé [d’écouter], parce que j’ai étendu ma main et que personne n’a pris garde,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'et que vous avez rejeté tout mon conseil et que vous n’avez pas voulu de ma répréhension,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'moi aussi je rirai lors de votre calamité, je me moquerai quand viendra votre frayeur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'quand votre frayeur viendra comme une subite destruction et que votre calamité arrivera comme un tourbillon, quand la détresse et l’angoisse viendront sur vous:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'alors ils crieront vers moi, et je ne répondrai pas; ils me chercheront de bonne heure, mais ils ne me trouveront point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Parce qu’ils ont haï la connaissance et qu’ils n’ont pas choisi la crainte de l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'qu’ils n’ont point voulu de mon conseil, qu’ils ont méprisé toute ma répréhension,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'ils mangeront du fruit de leur voie et seront rassasiés de leurs propres conseils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Car la révolte des simples les tue, et la prospérité des sots les fait périr.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Mais celui qui m’écoute habitera en sécurité et sera tranquille, sans crainte du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Mon fils, si tu reçois mes paroles et que tu caches par-devers toi mes commandements');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'pour rendre ton oreille attentive à la sagesse, si tu inclines ton cœur à l’intelligence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'si tu appelles le discernement, si tu adresses ta voix à l’intelligence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'si tu la cherches comme de l’argent et que tu la recherches comme des trésors cachés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'alors tu comprendras la crainte de l’ Éternel et tu trouveras la connaissance de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Car l’ Éternel donne la sagesse; de sa bouche [procèdent] la connaissance et l’intelligence:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'il réserve de sains conseils pour les hommes droits; il est un bouclier pour ceux qui marchent dans l’intégrité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'protégeant les sentiers de juste jugement et gardant la voie de ses saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Alors tu discerneras la justice et le juste jugement et la droiture, toute bonne voie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Si la sagesse entre dans ton cœur et si la connaissance est agréable à ton âme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'la réflexion te préservera, l’intelligence te protégera:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Pour te sauver du mauvais chemin, de l’homme qui prononce des choses perverses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, '[de ceux] qui abandonnent les sentiers de la droiture pour marcher dans les voies de ténèbres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'qui se réjouissent à mal faire, qui s’égaient en la perversité du mal,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'dont les sentiers sont tortueux et qui s’égarent dans leurs voies;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Pour te sauver de la femme étrangère, de l’étrangère qui use de paroles flatteuses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'qui abandonne le guide de sa jeunesse, et qui a oublié l’alliance de son Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, '– car sa maison penche vers la mort, et ses chemins vers les trépassés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'aucun de ceux qui entrent auprès d’elle ne revient ni n’atteint les sentiers de la vie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, '– afin que tu marches dans la voie des gens de bien, et que tu gardes les sentiers des justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Car les hommes droits habiteront le pays, et les hommes intègres y demeureront de reste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'mais les méchants seront retranchés du pays, et les perfides en seront arrachés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Mon fils, n’oublie pas mon enseignement, et que ton cœur garde mes commandements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'car ils t’ajouteront un prolongement de jours, et des années de vie, et la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Que la bonté et la vérité ne t’abandonnent pas; lie-les à ton cou, écris-les sur la tablette de ton cœur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'et tu trouveras la faveur et la bonne sagesse aux yeux de Dieu et des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Confie-toi de tout ton cœur à l’ Éternel, et ne t’appuie pas sur ton intelligence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'dans toutes tes voies connais-le, et il dirigera tes sentiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Ne sois pas sage à tes propres yeux; crains l’ Éternel et éloigne-toi du mal:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'ce sera la santé pour ton nombril, et un arrosement pour tes os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Honore l’ Éternel de tes biens et des prémices de tout ton revenu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'et tes greniers se rempliront d’abondance, et tes cuves regorgeront de moût.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Mon fils, ne méprise pas l’instruction de l’ Éternel, et n’aie pas en aversion sa réprimande;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'car celui que l’ Éternel aime, il le discipline, comme un père le fils auquel il prend plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Bienheureux l’homme qui trouve la sagesse, et l’homme qui obtient l’intelligence!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'car son acquisition est meilleure que l’acquisition de l’argent, et son revenu [est meilleur] que l’or fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Elle est plus précieuse que les rubis, et aucune des choses auxquelles tu prends plaisir ne l’égale:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'longueur de jours est dans sa droite, dans sa gauche richesse et honneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'ses voies sont des voies agréables, et tous ses sentiers sont paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Elle est un arbre de vie pour ceux qui la saisissent; et qui la tient ferme est rendu bienheureux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'L’ Éternel a fondé la terre par la sagesse, il a établi les cieux par l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Par sa connaissance les abîmes se fendirent, et les nuées distillent la rosée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Mon fils, que [ces choses] ne s’éloignent point de tes yeux: garde le sain conseil et la réflexion,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'et ils seront la vie de ton âme et la grâce de ton cou.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Alors tu iras ton chemin en sécurité, et ton pied ne se heurtera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Si tu te couches tu n’auras point de crainte; mais tu te coucheras et ton sommeil sera doux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Ne crains pas la frayeur subite, ni la ruine des méchants quand elle surviendra;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'car l’ Éternel sera ta confiance, et il gardera ton pied d’être pris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Ne refuse pas le bien à celui à qui il est dû, quand il est au pouvoir de ta main de le faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Ne dis pas à ton prochain: Va et reviens, et je te le donnerai demain, quand tu as la chose par-devers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Ne machine pas du mal contre ton prochain, puisqu’il habite en sécurité près de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Ne conteste pas sans sujet avec un homme, s’il ne t’a pas fait de tort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Ne porte pas envie à un homme violent, et ne choisis aucune de ses voies;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Car l’ Éternel a en abomination le pervers, et son secret est avec les hommes droits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'La malédiction de l’ Éternel est dans la maison du méchant, et il bénit l’habitation des justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Certes il se moque des moqueurs, et il donne la grâce aux débonnaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Les sages hériteront la gloire, mais la honte est l’élévation des sots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Fils, écoutez l’instruction d’un père et soyez attentifs pour connaître l’intelligence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'car je vous donne une bonne doctrine: n’abandonnez pas mon enseignement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Car j’ai été un fils pour mon père, tendre et unique auprès de ma mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Il m’a enseigné et m’a dit: Que ton cœur retienne mes paroles; garde mes commandements, et tu vivras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Acquiers la sagesse, acquiers l’intelligence; ne [l’]oublie pas, et ne te détourne pas des paroles de ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Ne l’abandonne pas, et elle te gardera; aime-la, et elle te conservera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Le commencement de la sagesse, c’est: Acquiers la sagesse, et, au prix de toutes tes acquisitions, acquiers l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Exalte-la, et elle t’élèvera; elle t’honorera quand tu l’auras embrassée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Elle mettra sur ta tête une guirlande de grâce, elle te donnera une couronne de gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Écoute, mon fils, et reçois mes paroles, et les années de ta vie te seront multipliées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Je t’enseignerai la voie de la sagesse, je te dirigerai dans les chemins de la droiture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Quand tu marcheras, tes pas ne seront pas gênés, et si tu cours, tu ne broncheras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Tiens ferme l’instruction, ne la lâche pas; garde-la, car elle est ta vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'N’entre pas dans le sentier des méchants, et ne marche pas dans la voie des iniques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Éloigne-t’en, n’y passe point; détourne-t’en, et passe outre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Car ils ne dormiraient pas s’ils n’avaient fait du mal, et le sommeil leur serait ôté s’ils n’avaient fait trébucher [quelqu’un];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'car ils mangent le pain de méchanceté, et ils boivent le vin des violences.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Mais le sentier des justes est comme la lumière resplendissante qui va croissant jusqu’à ce que le plein jour soit établi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Le chemin des méchants est comme l’obscurité; ils ne savent contre quoi ils trébucheront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Mon fils, sois attentif à mes paroles, incline ton oreille à mes discours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Qu’ils ne s’éloignent point de tes yeux; garde-les au-dedans de ton cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'car ils sont la vie de ceux qui les trouvent, et la santé de toute leur chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Garde ton cœur plus que tout ce que l’on garde, car de lui sont les issues de la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Écarte de toi la fausseté de la bouche, et éloigne de toi la perversité des lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Que tes yeux regardent droit en avant, et que tes paupières se dirigent droit devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Pèse le chemin de tes pieds, et que toutes tes voies soient bien réglées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'N’incline ni à droite ni à gauche; éloigne ton pied du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Mon fils, sois attentif à ma sagesse, incline ton oreille à mon intelligence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'pour garder les pensées réfléchies et pour que tes lèvres conservent la connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Car les lèvres de l’étrangère distillent du miel, et son palais est plus doux que l’huile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'mais à la fin elle est amère comme l’absinthe, aiguë comme une épée à deux tranchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Ses pieds descendent à la mort, ses pas atteignent le shéol,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'de sorte qu’elle ne pèse pas le sentier de la vie; ses voies sont errantes: elle n’a pas de connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Et maintenant, [mes] fils, écoutez-moi, et ne vous détournez pas des paroles de ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Éloigne ta voie d’auprès d’elle, et ne t’approche point de l’entrée de sa maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'de peur que tu ne donnes ton honneur à d’autres, et tes années à l’homme cruel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'de peur que des étrangers ne se rassasient de ton bien, et que ton travail ne soit dans la maison d’un étranger;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'et que tu ne gémisses à ta fin, quand ta chair et ton corps se consumeront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'et que tu ne dises: Comment ai-je haï l’instruction, et mon cœur a-t-il méprisé la répréhension?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Comment n’ai-je pas écouté la voix de ceux qui m’instruisaient, ni incliné mon oreille vers ceux qui m’enseignaient?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Peu s’en est fallu que je n’aie été dans toute sorte de mal, au milieu de la congrégation et de l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Bois des eaux de ta citerne, et de ce qui coule du milieu de ton puits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Tes fontaines se répandront au-dehors, des ruisseaux d’eau dans les places.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Qu’elles soient à toi seul, et non à des étrangers avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Que ta source soit bénie, et réjouis-toi de la femme de ta jeunesse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'biche des amours, et chevrette pleine de grâce; que ses seins t’enivrent en tout temps; sois continuellement épris de son amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Et pourquoi, mon fils, serais-tu épris d’une étrangère, et embrasserais-tu le sein de l’étrangère?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Car les voies de l’homme sont devant les yeux de l’ Éternel, et il pèse tous ses chemins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Le méchant, ses iniquités le saisiront, et il sera tenu par les cordes de son péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'il mourra faute de discipline, et il s’égarera dans la grandeur de sa folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Mon fils, si tu t’es porté caution pour ton prochain, si tu as engagé ta main pour un étranger,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'tu es enlacé dans les paroles de ta bouche, tu es pris dans les paroles de ta bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Mon fils, fais donc ceci, et délivre-toi, puisque tu es tombé en la main de ton prochain: va, humilie-toi, et insiste auprès de ton prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Ne permets pas à tes yeux de dormir, ni à tes paupières de sommeiller;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'dégage-toi, comme la gazelle, de la main [du chasseur], et comme l’oiseau, de la main de l’oiseleur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Va vers la fourmi, paresseux; regarde ses voies, et sois sage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Elle qui n’a ni chef, ni surveillant, ni gouverneur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'elle prépare en été son pain, elle amasse pendant la moisson sa nourriture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Jusques à quand, paresseux, resteras-tu couché? Quand te lèveras-tu de ton sommeil?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Un peu de sommeil, un peu d’assoupissement, un peu croiser les mains pour dormir...,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'et ta pauvreté viendra comme un voyageur, et ton dénuement comme un homme armé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Celui qui marche, la perversité dans sa bouche, est un homme de Bélial, un homme inique;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'il cligne de ses yeux, il parle de ses pieds, il enseigne de ses doigts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'il y a des pensées perverses dans son cœur, il machine du mal en tout temps, il sème des querelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'C’est pourquoi sa calamité viendra subitement; il sera tout à coup brisé, et il n’y a pas de remède.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'L’ Éternel hait ces six choses, et il y en a sept qui sont en abomination à son âme:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'les yeux hautains, la langue fausse, et les mains qui versent le sang innocent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'le cœur qui machine des projets d’iniquité, les pieds qui se hâtent de courir au mal,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'le faux témoin qui profère des mensonges, et celui qui sème des querelles entre des frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Mon fils, garde le commandement de ton père, et n’abandonne pas l’enseignement de ta mère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'tiens-les continuellement liés sur ton cœur, attache-les à ton cou.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Quand tu marcheras, il te conduira; quand tu dormiras, il te gardera; et quand tu te réveilleras, il s’entretiendra avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Car le commandement est une lampe et l’enseignement une lumière, et les répréhensions de la discipline sont le chemin de la vie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'pour te garder de la mauvaise femme, des flatteries de la langue d’une étrangère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Ne désire pas sa beauté dans ton cœur, et qu’elle ne te prenne pas par ses paupières;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'car par la femme prostituée [on en vient] jusqu’à un morceau de pain, et la femme d’autrui chasse après l’âme précieuse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Un homme prendra-t-il du feu dans son sein sans que ses vêtements brûlent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Si un homme marche sur des charbons ardents, ses pieds ne seront-ils pas brûlés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Ainsi celui qui entre vers la femme de son prochain..., quiconque la touchera ne sera point innocent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'On ne méprise pas un voleur s’il vole pour satisfaire son âme quand il a faim;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'et s’il est trouvé, il rendra le septuple, il donnera tous les biens de sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Celui qui commet adultère avec une femme manque de sens; celui qui le fait détruit son âme:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'il trouvera plaie et mépris, et son opprobre ne sera pas effacé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'car dans l’homme, la jalousie est une fureur, et il n’épargnera pas au jour de la vengeance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'il n’acceptera aucune propitiation, et ne se tiendra pas pour satisfait, quand tu multiplierais les présents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Mon fils, garde mes paroles et cache par-devers toi mes commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Garde mes commandements, et tu vivras, – et mon enseignement, comme la prunelle de tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Lie-les sur tes doigts, écris-les sur la tablette de ton cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Dis à la sagesse: Tu es ma sœur! et appelle l’intelligence ton amie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'pour te garder de la femme étrangère, de la foraine qui use de paroles flatteuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Car, à la fenêtre de ma maison, je regardais à travers mon treillis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'et je vis parmi les simples, j’aperçus parmi les jeunes gens, un jeune homme dépourvu de sens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'qui passait dans la rue, près du coin où demeurait cette femme, et il prit le chemin de sa maison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'au crépuscule, au soir du jour, au sein de la nuit et de l’obscurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Et voici, une femme [vint] à sa rencontre, ayant la mise d’une prostituée et le cœur rusé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Elle était bruyante et sans frein; ses pieds ne demeuraient pas dans sa maison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'elle était tantôt dehors, tantôt sur les places, et guettait à tous les coins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Et elle le saisit, et l’embrassa, et d’un visage effronté lui dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'J’ai chez moi des sacrifices de prospérités, j’ai aujourd’hui payé mes vœux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'c’est pourquoi je suis sortie à ta rencontre pour chercher ton visage, et je t’ai trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'J’ai étendu sur mon lit des tapis, des couvertures de fil d’Égypte de couleurs variées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'j’ai parfumé ma couche de myrrhe, d’aloès, et de cinnamome.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Viens, enivrons-nous d’amours jusqu’au matin, délectons-nous de volupté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'car [mon] mari n’est pas à la maison, il s’en est allé loin en voyage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'il a pris un sac d’argent en sa main, il viendra à sa maison au jour de la pleine lune.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Elle le détourna par beaucoup de douces paroles, elle l’entraîna par la flatterie de ses lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Il est allé aussitôt après elle, comme le bœuf va à la boucherie, et comme les ceps [servent à] l’instruction du fou,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'jusqu’à ce que la flèche lui transperce le foie; comme l’oiseau se hâte vers le piège et ne sait pas qu’il y va de sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Maintenant donc, fils, écoutez-moi, et soyez attentifs aux paroles de ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Que ton cœur ne se détourne pas vers ses voies, et ne t’égare pas dans ses sentiers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'car elle a fait tomber beaucoup de blessés, et ceux qu’elle a tués sont très nombreux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Ce sont les voies du shéol que sa maison; elles descendent dans les chambres de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'La sagesse ne crie-t-elle pas, et l’intelligence ne fait-elle pas retentir sa voix?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Au sommet des hauteurs, sur le chemin, aux carrefours, elle se tient debout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'À côté des portes, à l’entrée de la ville, là où l’on passe pour entrer, elle crie:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'À vous, hommes, je crie, et ma voix [s’adresse] aux fils des hommes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Vous, simples, comprenez la prudence, et vous, sots, comprenez ce qu’est le sens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Écoutez, car je dirai des choses excellentes, et l’ouverture de mes lèvres [prononcera] des choses droites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'car mon palais méditera la vérité, et la méchanceté sera une abomination pour mes lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Toutes les paroles de ma bouche sont selon la justice, il n’y a rien en elles de pervers ni de tortueux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'elles sont toutes claires pour celui qui a de l’intelligence, et droites pour ceux qui ont trouvé la connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Recevez mon instruction, et non pas de l’argent, et la connaissance plutôt que l’or fin choisi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'car la sagesse est meilleure que les rubis, et rien de ce qui fait nos délices ne l’égale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Moi, la sagesse, je demeure avec la prudence, et je trouve la connaissance [qui vient] de la réflexion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'La crainte de l’ Éternel, c’est de haïr le mal. Je hais l’orgueil et la hauteur, et la voie d’iniquité, et la bouche perverse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'À moi le conseil et le savoir-faire; je suis l’intelligence; à moi la force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Par moi les rois règnent, et les princes statuent la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Par moi les chefs dominent, et les nobles, tous les juges de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'J’aime ceux qui m’aiment; et ceux qui me recherchent me trouveront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Avec moi sont les richesses et les honneurs, les biens éclatants et la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Mon fruit est meilleur que l’or fin, même que l’or pur; et mon revenu [meilleur] que l’argent choisi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Je marche dans le chemin de la justice, au milieu des sentiers de juste jugement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'pour faire hériter les biens réels à ceux qui m’aiment, et pour remplir leurs trésors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'L’ Éternel m’a possédée au commencement de sa voie, avant ses œuvres d’ancienneté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Dès l’éternité je fus établie, dès le commencement, dès avant les origines de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Quand il n’y avait pas d’abîmes, j’ai été enfantée, quand il n’y avait pas de sources pleines d’eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Avant que les montagnes soient établies sur leurs bases, avant les collines, j’ai été enfantée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'lorsqu’il n’avait pas encore fait la terre et les campagnes, et le commencement de la poussière du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Quand il disposait les cieux, j’étais là; quand il ordonnait le cercle qui circonscrit la face de l’abîme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'quand il établissait les nuées en haut, quand il affermissait les sources des abîmes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'quand il imposait son décret à la mer, afin que les eaux n’outrepassent point son commandement, quand il décrétait les fondements de la terre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'j’étais alors à côté de lui son nourrisson, j’étais ses délices tous les jours, toujours en joie devant lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'me réjouissant en la partie habitable de sa terre, et mes délices étaient dans les fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Maintenant donc, fils, écoutez-moi: bienheureux ceux qui gardent mes voies!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Écoutez l’instruction, et soyez sages, et ne la rejetez point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Bienheureux l’homme qui m’écoute, veillant à mes portes tous les jours, gardant les poteaux de mes entrées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Car celui qui m’a trouvée a trouvé la vie, et acquiert faveur de la part de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'mais celui qui pèche contre moi fait tort à son âme; tous ceux qui me haïssent aiment la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'La sagesse a bâti sa maison, elle a taillé ses sept colonnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'elle a tué ses bêtes, elle a mixtionné son vin, elle a aussi dressé sa table;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'elle a envoyé ses servantes; elle crie sur les sommets des hauteurs de la ville:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Qui est simple? qu’il se retire ici. À celui qui est dépourvu de sens, elle dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Venez, mangez de mon pain, et buvez du vin que j’ai mixtionné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Laissez la sottise, et vivez, et marchez dans la voie de l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Qui instruit un moqueur reçoit pour lui-même de la confusion; et qui reprend un méchant [reçoit] pour lui-même une tache.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Ne reprends pas le moqueur, de peur qu’il ne te haïsse; reprends le sage, et il t’aimera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Donne au sage, et il deviendra encore plus sage; enseigne le juste, et il croîtra en science.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'La crainte de l’ Éternel est le commencement de la sagesse, et la connaissance du Saint est l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Car par moi tes jours seront multipliés, et des années de vie te seront ajoutées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Si tu es sage, tu seras sage pour toi-même; et si tu es moqueur, tu en porteras seul la peine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'La femme folle est bruyante, elle est sotte, il n’y a pas de connaissance en elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Et elle s’assied à l’entrée de sa maison sur un trône, dans les lieux élevés de la ville,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'pour appeler ceux qui passent sur la route, qui vont droit leur chemin:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Qui est simple? qu’il se retire ici. Et à celui qui est dépourvu de sens, elle dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Les eaux dérobées sont douces, et le pain [mangé] en secret est agréable!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Et il ne sait pas que les trépassés sont là, [et] que ses conviés sont dans les profondeurs du shéol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, '***Proverbes de Salomon. Un fils sage réjouit son père, mais un fils insensé est le chagrin de sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Les trésors de la méchanceté ne profitent de rien, mais la justice délivre de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'L’ Éternel ne laisse pas l’âme du juste avoir faim, mais il repousse l’avidité des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Celui qui agit d’une main lâche devient pauvre, mais la main des diligents enrichit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Celui qui amasse en été est un fils sage; celui qui dort durant la moisson est un fils qui fait honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Il y a des bénédictions sur la tête du juste, mais la bouche des méchants couvre la violence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'La mémoire du juste est en bénédiction, mais le nom des méchants tombe en pourriture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Celui qui est sage de cœur reçoit les commandements, mais [celui qui est] insensé de lèvres tombe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Celui qui marche dans l’intégrité marche en sûreté, mais celui qui pervertit ses voies sera connu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Celui qui cligne de l’œil cause du chagrin, et [celui qui est] insensé de lèvres tombe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'La bouche du juste est une fontaine de vie, mais la bouche des méchants couvre la violence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'La haine excite les querelles, mais l’amour couvre toutes les transgressions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Sur les lèvres de l’homme intelligent se trouve la sagesse, mais la verge est pour le dos de celui qui est dépourvu de sens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Les sages tiennent en réserve la connaissance, mais la ruine est près de la bouche du fou.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Les biens du riche sont sa ville forte; la ruine des misérables, c’est leur pauvreté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'L’œuvre du juste est pour la vie, le revenu du méchant est pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Garder l’instruction, [c’est] le sentier [qui mène] à la vie; mais celui qui abandonne la répréhension s’égare.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Celui qui couvre la haine a des lèvres menteuses, et celui qui propage les calomnies est un sot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Dans la multitude des paroles la transgression ne manque pas, mais celui qui retient ses lèvres est sage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'La langue du juste est de l’argent choisi, le cœur des méchants est peu de chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Les lèvres du juste en repaissent plusieurs, mais les fous mourront faute de sens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'La bénédiction de l’ Éternel est ce qui enrichit, et il n’y ajoute aucune peine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'C’est comme une plaisanterie pour le sot que de commettre un crime, mais la sagesse est pour l’homme intelligent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Ce que craint le méchant lui arrive, mais le désir des justes [Dieu] l’accorde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Comme passe le tourbillon, ainsi le méchant n’est plus; mais le juste est un fondement pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Ce que le vinaigre est aux dents, et la fumée aux yeux, tel est le paresseux pour ceux qui l’envoient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'La crainte de l’ Éternel ajoute des jours, mais les années des méchants seront raccourcies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'L’attente des justes est une joie, mais l’espérance des méchants périra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'La voie de l’ Éternel est la force pour l’homme intègre, mais elle est la ruine pour les ouvriers d’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Le juste ne sera jamais ébranlé, mais les méchants n’habiteront pas le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'La bouche du juste produit la sagesse, mais la langue perverse sera retranchée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Les lèvres du juste savent ce qui est agréable, mais la bouche des méchants n’est que perversité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'La fausse balance est en abomination à l’ Éternel, mais le poids juste lui est agréable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, '[Quand] vient l’orgueil, la honte vient aussi; mais la sagesse est avec les hommes modestes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'L’intégrité des hommes droits les guide, mais la perversité des perfides les détruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Les richesses ne profitent de rien au jour de la colère, mais la justice délivre de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'La justice de l’homme intègre rend droite sa voie, mais le méchant tombe par sa méchanceté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'La justice des hommes droits les délivre, mais les perfides sont pris dans leur avidité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Quand l’homme méchant meurt, son espérance périt, et l’attente des iniques périt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Le juste est délivré de la détresse, et le méchant [y] entre à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Par sa bouche l’impie perd son prochain; mais les justes sont délivrés par la connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'La ville se réjouit du bien-être des justes; et quand les méchants périssent il y a des cris de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'La ville s’élève par la bénédiction des hommes droits, mais elle est renversée par la bouche des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Qui méprise son prochain est dépourvu de sens, mais l’homme intelligent se tait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Celui qui va rapportant révèle le secret, mais celui qui est d’un esprit fidèle couvre la chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Quand il n’y a pas de direction le peuple tombe, mais il y a salut dans le grand nombre des conseillers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'On se trouve mal de cautionner un étranger, mais celui qui hait ceux qui frappent [dans la main] est en sûreté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Une femme gracieuse obtient l’honneur, et les hommes forts obtiennent la richesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'L’homme bon fait du bien à son âme, mais le cruel trouble sa chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Le méchant fait une œuvre trompeuse, mais celui qui sème la justice a un vrai salaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Comme la justice [tend] à la vie, celui qui poursuit le mal [tend] à sa mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Ceux qui sont pervers de cœur sont en abomination à l’ Éternel, mais ceux qui sont intègres dans leurs voies lui sont agréables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Certainement l’inique ne sera point tenu pour innocent; mais la semence des justes sera délivrée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Une femme belle et dépourvue de sens, c’est un anneau d’or au nez d’un pourceau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Le désir des justes n’est que le bien; l’attente des méchants, c’est la fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Tel disperse, et augmente encore; et tel retient plus qu’il ne faut, mais n’en a que disette.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'L’âme qui bénit sera engraissée, et celui qui arrose sera lui-même arrosé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Celui qui retient le blé, le peuple le maudit; mais la bénédiction sera sur la tête de celui qui le vend.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Qui recherche le bien cherche la faveur, mais le mal arrive à qui le recherche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Celui-là tombe qui se confie en ses richesses; mais les justes verdissent comme la feuille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Celui qui trouble sa maison héritera le vent, et le fou deviendra serviteur de celui qui est sage de cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Le fruit du juste est un arbre de vie, et le sage gagne les âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Voici, le juste est rétribué sur la terre, combien plus le méchant et le pécheur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Qui aime l’instruction aime la connaissance, et qui hait la répréhension est stupide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'L’homme de bien obtient la faveur de par l’ Éternel, mais l’homme qui fait des machinations, il le condamne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'L’homme n’est point affermi par la méchanceté, mais la racine des justes n’est pas ébranlée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Une femme vertueuse est la couronne de son mari, mais celle qui fait honte est comme de la pourriture dans ses os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Les pensées des justes sont jugement, les desseins des méchants sont fraude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Les paroles des méchants sont des embûches pour [verser] le sang, mais la bouche des hommes droits les délivrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Renversez les méchants, et ils ne sont plus; mais la maison des justes demeure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Un homme est loué d’après sa prudence, mais le cœur perverti est en butte au mépris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Mieux vaut celui qui est d’humble condition, et qui a un serviteur, que celui qui fait l’important et qui manque de pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Le juste regarde à la vie de sa bête, mais les entrailles des méchants sont cruelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Celui qui laboure sa terre sera rassasié de pain, mais celui qui court après les fainéants est dépourvu de sens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Le méchant désire la proie des mauvaises gens, mais la racine des justes est productive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Il y a un mauvais piège dans la transgression des lèvres, mais le juste sort de la détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Du fruit de sa bouche un homme est rassasié de biens, et on rendra à l’homme l’œuvre de ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'La voie du fou est droite à ses yeux, mais celui qui écoute le conseil est sage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'L’irritation du fou se connaît le jour même, mais l’homme avisé couvre sa honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Celui qui dit la vérité annonce la justice, mais le faux témoin, la fraude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Il y a tel homme qui dit légèrement ce qui perce comme une épée, mais la langue des sages est santé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'La lèvre véridique est ferme pour toujours, mais la langue fausse n’est que pour un instant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'La fraude est dans le cœur de ceux qui machinent le mal, mais il y a de la joie pour ceux qui conseillent la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Aucun malheur n’arrive au juste, mais les méchants seront comblés de maux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Les lèvres menteuses sont en abomination à l’ Éternel, mais ceux qui pratiquent la fidélité lui sont agréables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'L’homme avisé couvre la connaissance, mais le cœur des sots proclame la folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'La main des diligents dominera, mais la [main] paresseuse sera tributaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'L’inquiétude dans le cœur d’un homme l’abat, mais une bonne parole le réjouit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Le juste montre le chemin à son compagnon, mais la voie des méchants les fourvoie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Le paresseux ne rôtit pas sa chasse; mais les biens précieux de l’homme sont au diligent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'La vie est dans le sentier de la justice, et il n’y a pas de mort dans le chemin qu’elle trace.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Un fils sage [écoute] l’instruction du père, mais le moqueur n’écoute pas la répréhension.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Du fruit de sa bouche l’homme mange du bien, mais l’âme des perfides [mange] la violence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Qui surveille sa bouche garde son âme; la ruine est pour celui qui ouvre ses lèvres toutes grandes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'L’âme du paresseux désire, et il n’y a rien; mais l’âme des diligents sera engraissée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Le juste hait la parole mensongère, mais le méchant se rend odieux et se couvre de honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'La justice garde celui qui est intègre dans sa voie, mais la méchanceté renverse le pécheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Tel fait le riche et n’a rien du tout; et tel se fait pauvre et a de grands biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'La rançon pour la vie d’un homme, c’est sa richesse; mais le pauvre n’entend pas la réprimande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'La lumière des justes est joyeuse, mais la lampe des méchants s’éteindra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Ce n’est que de l’orgueil que vient la querelle, mais la sagesse est avec ceux qui se laissent conseiller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Les biens qui viennent de la vanité diminuent, mais celui qui amasse à la main les accroîtra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'L’attente différée rend le cœur malade, mais le désir qui arrive est un arbre de vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Qui méprise la parole sera lié par elle; mais qui craint le commandement, celui-là sera récompensé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'L’enseignement du sage est une fontaine de vie, pour faire éviter les pièges de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Le bon sens procure la faveur, mais la voie des perfides est dure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Tout homme avisé agit avec connaissance, mais le sot fait étalage de sa folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Un messager méchant tombe dans le mal, mais un ambassadeur fidèle est santé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'La pauvreté et la honte arrivent à qui rejette l’instruction, mais celui qui a égard à la répréhension sera honoré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Le désir accompli est agréable à l’âme, mais se détourner du mal est une abomination pour les sots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Qui marche avec les sages devient sage, mais le compagnon des sots s’en trouvera mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Le mal poursuit les pécheurs; mais le bien est la récompense des justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'L’homme de bien laisse un héritage aux fils de ses fils, mais la richesse du pécheur est réservée pour le juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Il y a beaucoup à manger dans le défrichement des pauvres, mais il y a ce qui se perd faute de règle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Celui qui épargne la verge hait son fils, mais celui qui l’aime met de la diligence à le discipliner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Le juste mange pour le rassasiement de son âme, mais le ventre des méchants aura disette.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'La sagesse des femmes bâtit leur maison, mais la folie la détruit de ses propres mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Celui qui marche dans sa droiture craint l’ Éternel, mais celui qui est pervers dans ses voies le méprise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Dans la bouche du fou est la verge d’orgueil, mais les lèvres des sages les gardent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Où il n’y a point de bœufs, la crèche est vide; et l’abondance du revenu est dans la force du bœuf.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Le témoin fidèle ne ment pas, mais le faux témoin profère des mensonges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Le moqueur cherche la sagesse, et il n’y en a pas [pour lui]; mais la connaissance est aisée pour l’homme intelligent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Éloigne-toi de la présence de l’homme insensé, chez qui tu n’as pas aperçu des lèvres de connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'La sagesse de l’homme avisé est de discerner sa voie, mais la folie des sots est tromperie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Les fous se moquent du péché, mais pour les hommes droits il y a faveur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Le cœur connaît sa propre amertume, et un étranger ne se mêle pas à sa joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'La maison des méchants sera détruite, mais la tente des hommes droits fleurira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Il y a telle voie qui semble droite à un homme, mais des voies de mort en sont la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Même dans le rire le cœur est triste; et la fin de la joie, c’est le chagrin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Le cœur qui s’éloigne [de Dieu] sera rassasié de ses propres voies, mais l’homme de bien [le sera] de ce qui est en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Le simple croit toute parole, mais l’homme avisé discerne ses pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Le sage craint, et se retire du mal; mais le sot est arrogant et a de l’assurance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'L’homme prompt à la colère agit follement, et l’homme qui fait des machinations est haï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Les simples héritent la folie, mais les avisés sont couronnés de connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Les iniques se courbent devant les bons, et les méchants, aux portes du juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Le pauvre est haï, même de son compagnon, mais les amis du riche sont en grand nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Qui méprise son prochain pèche, mais bienheureux celui qui use de grâce envers les malheureux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Ceux qui machinent du mal ne s’égarent-ils pas? Mais la bonté et la vérité sont pour ceux qui méditent le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'En tout travail il y a profit, mais la parole des lèvres ne mène qu’à la disette.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Les richesses des sages sont leur couronne; la folie des sots est folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Un témoin fidèle délivre les âmes, mais la tromperie profère des mensonges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Dans la crainte de l’ Éternel il y a la sécurité de la force, et il y a un refuge pour ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'La crainte de l’ Éternel est une fontaine de vie, pour faire éviter les pièges de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'La gloire d’un roi, c’est la multitude du peuple, mais dans le manque de peuple est la ruine d’un prince.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'La lenteur à la colère est grande intelligence, mais celui qui est d’un esprit impatient exalte la folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Un cœur sain est la vie de la chair, mais l’envie est la pourriture des os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Qui opprime le pauvre outrage Celui qui l’a fait, mais celui qui l’honore use de grâce envers l’indigent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Le méchant est chassé par son iniquité, mais le juste est plein de confiance, dans sa mort [même].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'La sagesse demeure dans le cœur de celui qui a du discernement, mais ce qui est au-dedans des sots est connu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'La justice élève une nation, mais le péché est la honte des peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'La faveur du roi est pour le serviteur intelligent, mais sa colère est sur celui qui fait honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Une réponse douce détourne la fureur, mais la parole blessante excite la colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'La langue des sages fait valoir la connaissance, mais la bouche des sots fait jaillir la folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Les yeux de l’ Éternel sont en tout lieu, regardant les méchants et les bons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'La bénignité de la langue est un arbre de vie, mais la perversité en elle est un brisement d’esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Le fou méprise l’instruction de son père, mais celui qui a égard à la répréhension devient avisé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Dans la maison du juste il y a un grand trésor, mais dans le revenu du méchant il y a du trouble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Les lèvres des sages répandent la connaissance, mais le cœur des sots ne fait pas ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Le sacrifice des méchants est en abomination à l’ Éternel, mais la prière des hommes droits lui est agréable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'La voie du méchant est en abomination à l’ Éternel, mais il aime celui qui poursuit la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Une discipline fâcheuse attend celui qui abandonne le [droit] sentier; celui qui hait la correction mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Le shéol et l’abîme sont devant l’ Éternel, combien plus les cœurs des fils des hommes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Le moqueur n’aime pas celui qui le reprend; il ne va pas vers les sages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Le cœur joyeux égaie le visage, mais par le chagrin du cœur l’esprit est abattu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Le cœur de l’homme intelligent cherche la connaissance, mais la bouche des sots se repaît de folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Tous les jours du malheureux sont mauvais, mais le cœur heureux est un festin continuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Mieux vaut peu, avec la crainte de l’ Éternel, qu’un grand trésor avec du trouble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Mieux vaut un repas d’herbes, et de l’amour, qu’un bœuf engraissé, et de la haine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'L’homme violent excite la querelle, mais celui qui est lent à la colère apaise la dispute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'La voie du paresseux est comme une haie d’épines, mais le sentier des hommes droits est aplani.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Un fils sage réjouit son père, mais l’homme insensé méprise sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'La folie est la joie de celui qui est dépourvu de sens, mais l’homme intelligent règle ses pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Les projets échouent là où il n’y a point de conseil, mais, par la multitude des conseillers, ils réussissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Il y a de la joie pour un homme dans la réponse de sa bouche; et une parole [dite] en son temps, combien elle est bonne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Le sentier de la vie est en haut pour les intelligents, afin qu’ils se détournent du shéol, en bas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'L’ Éternel démolit la maison des orgueilleux, mais il rend ferme la borne de la veuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Les machinations de l’inique sont en abomination à l’ Éternel, mais les paroles pures [lui] sont agréables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Celui qui cherche le gain déshonnête trouble sa maison, mais celui qui hait les dons vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Le cœur du juste réfléchit pour répondre, mais la bouche des méchants fait jaillir les choses mauvaises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'L’ Éternel est loin des méchants, mais il écoute la prière des justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Ce qui éclaire les yeux réjouit le cœur; une bonne nouvelle engraisse les os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'L’oreille qui écoute la répréhension de vie logera au milieu des sages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Celui qui rejette l’instruction méprise sa vie; mais celui qui écoute la répréhension acquiert du sens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'La crainte de l’ Éternel est la discipline de la sagesse, et l’abaissement va devant la gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'La préparation du cœur est à l’homme, mais de l’ Éternel est la réponse de la langue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Toutes les voies d’un homme sont pures à ses propres yeux, mais l’ Éternel pèse les esprits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Remets tes affaires à l’ Éternel, et tes pensées seront accomplies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'L’ Éternel a tout fait pour lui-même, et même le méchant pour le jour du malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Tout cœur orgueilleux est en abomination à l’ Éternel; certes, il ne sera pas tenu pour innocent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Par la bonté et par la vérité, propitiation est faite pour l’iniquité, et par la crainte de l’ Éternel on se détourne du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Quand les voies d’un homme plaisent à l’ Éternel, il met ses ennemis mêmes en paix avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Mieux vaut peu avec justice, que beaucoup de revenu sans ce qui est juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Le cœur de l’homme se propose sa voie, mais l’ Éternel dispose ses pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Un oracle est sur les lèvres du roi, sa bouche n’erre pas dans le jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'La balance et les plateaux justes sont de l’ Éternel; tous les poids du sac sont son ouvrage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'C’est une abomination pour les rois de faire l’iniquité; car, par la justice, le trône est rendu ferme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Les lèvres justes sont le plaisir des rois, et le [roi] aime celui qui parle droitement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'La fureur du roi, ce sont des messagers de mort; mais l’homme sage l’apaisera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Dans la lumière de la face du roi est la vie, et sa faveur est comme un nuage de pluie dans la dernière saison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Combien acquérir la sagesse est meilleur que l’or fin, et acquérir l’intelligence, préférable à l’argent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Le chemin des hommes droits, c’est de se détourner du mal; celui-là garde son âme qui veille sur sa voie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'L’orgueil va devant la ruine, et l’esprit hautain devant la chute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Mieux vaut être humble d’esprit avec les débonnaires, que de partager le butin avec les orgueilleux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Celui qui prend garde à la parole trouvera le bien, et qui se confie en l’ Éternel est bienheureux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'L’homme sage de cœur sera appelé intelligent, et la douceur des lèvres accroît la science.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'L’intelligence est une fontaine de vie pour ceux qui la possèdent, mais l’instruction des fous est folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Le cœur du sage rend sa bouche sensée, et, sur ses lèvres, accroît la science.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Les paroles agréables sont un rayon de miel, douceur pour l’âme et santé pour les os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Il y a telle voie qui semble droite à un homme, mais des voies de mort en sont la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'L’âme de celui qui travaille, travaille pour lui, car sa bouche l’y contraint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'L’homme de Bélial creuse, [à la recherche] du mal, et sur ses lèvres il y a comme un feu brûlant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'L’homme pervers sème les querelles, et le rapporteur divise les intimes amis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'L’homme violent entraîne son compagnon et le fait marcher dans une voie qui n’est pas bonne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Celui qui ferme ses yeux pour machiner la perversité, celui qui pince ses lèvres, accomplit le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Les cheveux blancs sont une couronne de gloire s’ils se trouvent dans la voie de la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Qui est lent à la colère vaut mieux que l’homme fort, et qui gouverne son esprit vaut mieux que celui qui prend une ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'On jette le sort dans le giron, mais toute décision est de par l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Mieux vaut un morceau sec et la paix, qu’une maison pleine de viandes de sacrifices et des querelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Un serviteur sage gouvernera le fils qui fait honte, et il aura part à l’héritage au milieu des frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Le creuset est pour l’argent, et le fourneau pour l’or; mais l’ Éternel éprouve les cœurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Celui qui fait le mal est attentif à la lèvre d’iniquité; le menteur prête l’oreille à la langue pernicieuse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Qui se moque du pauvre outrage celui qui l’a fait; qui se réjouit de la calamité ne sera pas tenu pour innocent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'La couronne des vieillards, ce sont les fils des fils, et la gloire des fils, ce sont leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'La parole excellente ne convient point à un homme vil; combien moins [sied] à un prince la lèvre menteuse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Le présent est une pierre précieuse aux yeux de celui qui le possède; de quelque côté qu’il se tourne, il réussit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Celui qui couvre une transgression cherche l’amour, mais celui qui répète une chose divise les intimes amis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'La répréhension fait plus d’impression sur l’homme intelligent que 100 coups sur le sot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'L’inique ne cherche que rébellion; mais un messager cruel sera envoyé contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Qu’un homme rencontre une ourse privée de ses petits, plutôt qu’un sot dans sa folie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Le mal ne quittera point la maison de celui qui rend le mal pour le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Le commencement d’une querelle, c’est comme quand on laisse couler des eaux; avant que la dispute s’échauffe, va-t’en.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Celui qui justifie le méchant et celui qui condamne le juste sont tous deux en abomination à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Pourquoi donc le prix dans la main d’un sot pour acheter la sagesse, alors qu’il n’a point de sens?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'L’ami aime en tout temps, et un frère est né pour la détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'L’homme dépourvu de sens frappe dans la main, s’engageant comme caution vis-à-vis de son prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Qui aime les contestations aime la transgression; qui hausse son portail cherche la ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Celui qui est pervers de cœur ne trouve pas le bien; et celui qui use de détours avec sa langue tombe dans le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Celui qui engendre un sot [l’engendre] pour son chagrin; et le père d’un homme vil ne se réjouira pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Le cœur joyeux fait du bien à la santé, mais un esprit abattu dessèche les os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Le méchant prend de [son] sein un présent pour faire dévier les sentiers du jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'La sagesse est en face de l’homme intelligent, mais les yeux du sot sont au bout de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Un fils insensé est un chagrin pour son père et une amertume pour celle qui l’a enfanté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Il n’est pas bon de punir le juste, et de frapper les nobles à cause de [leur] droiture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Celui qui a de la connaissance retient ses paroles, et un homme qui a de l’intelligence est d’un esprit froid.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Même le fou qui se tait est réputé sage, – celui qui ferme ses lèvres, un homme intelligent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Celui qui se tient à l’écart recherche ce qui lui plaît; il conteste contre toute sagesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Le sot ne prend pas plaisir à l’intelligence, mais à ce que son cœur soit manifesté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Quand vient le méchant, le mépris vient aussi, et avec l’ignominie, l’opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Les paroles de la bouche d’un homme sont des eaux profondes, et la fontaine de la sagesse est un torrent qui coule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Ce n’est pas bien d’avoir acception de la personne du méchant pour faire frustrer le juste dans le jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Les lèvres du sot entrent en dispute, et sa bouche appelle les coups.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'La bouche du sot est sa ruine, et ses lèvres sont un piège pour son âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Les paroles du rapporteur sont comme des friandises, et elles descendent jusqu’au-dedans des entrailles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Celui-là aussi qui est lâche dans son ouvrage est frère du destructeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Le nom de l’ Éternel est une forte tour; le juste y court et s’y trouve en une haute retraite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Les biens du riche sont sa ville forte, et comme une haute muraille, dans son imagination.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Avant la ruine le cœur de l’homme s’élève, et la débonnaireté va devant la gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Répondre avant d’avoir entendu, c’est une folie et une confusion pour qui le fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'L’esprit d’un homme soutient son infirmité; mais l’esprit abattu, qui le supportera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Le cœur de l’homme intelligent acquiert la connaissance, et l’oreille des sages cherche la connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Le don d’un homme lui fait faire place et l’introduit devant les grands.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Celui qui est le premier dans son procès est juste; son prochain vient, et l’examine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Le sort fait cesser les querelles et sépare les puissants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Un frère offensé est plus [difficile] à gagner qu’une ville forte, et les querelles sont comme les verrous d’un palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Le ventre d’un homme est rassasié du fruit de sa bouche; du revenu de ses lèvres il est rassasié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'La mort et la vie sont au pouvoir de la langue, et celui qui l’aime mangera de son fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Celui qui a trouvé une femme a trouvé une bonne chose, et il a obtenu faveur de la part de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Le pauvre parle en supplications, mais le riche répond des choses dures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'L’homme qui a [beaucoup] de compagnons va se ruinant; mais il est tel ami plus attaché qu’un frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Mieux vaut le pauvre qui marche dans son intégrité, que celui qui est pervers de lèvres et qui est un sot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'De même, le manque de connaissance dans une âme n’est pas une bonne chose, et celui qui se hâte de ses pieds bronche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'La folie de l’homme pervertit sa voie, et son cœur s’irrite contre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Les richesses font beaucoup d’amis, mais le pauvre est séparé de son ami.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Le faux témoin ne sera pas tenu pour innocent, et celui qui profère des mensonges n’échappera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Beaucoup de gens recherchent la faveur d’un noble, et chacun est ami d’un homme qui donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Tous les frères du pauvre le haïssent; combien plus ses amis s’éloigneront-ils de lui! Il les poursuit de ses paroles,... ils n’y sont plus!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Celui qui acquiert du sens aime son âme; celui qui garde l’intelligence, c’est pour trouver le bonheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Le faux témoin ne sera pas tenu pour innocent, et celui qui profère des mensonges périra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Une vie de délices ne sied pas à un sot; combien moins [sied-il] à un serviteur de gouverner des princes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'La sagesse de l’homme le rend lent à la colère; et sa gloire, c’est de passer par-dessus la transgression.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'La colère d’un roi est comme le rugissement d’un jeune lion, mais sa faveur, comme la rosée sur l’herbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Un fils insensé est un malheur pour son père, et les querelles d’une femme sont une gouttière continuelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Maison et richesse sont l’héritage des pères, mais une femme sage vient de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'La paresse fait tomber dans un profond sommeil, et l’âme négligente aura faim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Celui qui garde le commandement garde son âme; celui qui ne veille pas sur ses voies mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Qui use de grâce envers le pauvre prête à l’ Éternel, et il lui rendra son bienfait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Corrige ton fils tandis qu’il y a de l’espoir, mais ne te laisse pas aller au désir de le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Celui qui est très colère en portera la peine; car si tu le délivres, tu devras recommencer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Écoute le conseil, et reçois l’instruction, afin que tu sois sage à ta fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Il y a beaucoup de pensées dans le cœur d’un homme; mais le conseil de l’ Éternel, c’est là ce qui s’accomplit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Ce qui attire dans un homme, c’est sa bonté; et le pauvre vaut mieux que l’homme menteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'La crainte de l’ Éternel mène à la vie, et l’on reposera rassasié, sans être visité par le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Le paresseux enfonce sa main dans le plat, et il ne la ramène pas à sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Frappe le moqueur, et le simple deviendra avisé; corrige l’homme intelligent, et il comprendra la connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Celui qui ruine son père et chasse sa mère, est un fils qui fait honte et apporte l’opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Mon fils, cesse d’écouter l’instruction qui fait errer loin des paroles de la connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Un témoin de Bélial se moque du juste jugement, et la bouche des méchants avale l’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Les jugements sont préparés pour les moqueurs, et les coups pour le dos des sots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Le vin est moqueur, la boisson forte est tumultueuse, et quiconque s’y égare n’est pas sage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'La terreur du roi est comme le rugissement d’un jeune lion: qui l’irrite, pèche contre sa propre âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'C’est la gloire d’un homme que de s’abstenir des contestations, mais chaque fou s’y engage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'À cause de l’hiver, le paresseux ne laboure pas; lors de la moisson, il mendiera et n’aura rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Le conseil dans le cœur d’un homme est une eau profonde, et l’homme intelligent y puise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Nombre d’hommes proclament chacun sa bonté; mais un homme fidèle, qui le trouvera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Le juste marche dans son intégrité; heureux ses fils après lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Le roi siège sur le trône du jugement; il dissipe tout mal par son regard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Qui dira: J’ai purifié mon cœur, je suis net de mon péché?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Poids et poids, épha et épha, sont tous deux en abomination à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Même un jeune garçon se fait connaître par ses actions, si sa conduite est pure et si elle est droite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Et l’oreille qui entend et l’œil qui voit, l’ Éternel les a faits tous les deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'N’aime pas le sommeil, de peur que tu ne deviennes pauvre; ouvre tes yeux, [et] rassasie-toi de pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Mauvais, mauvais! dit l’acheteur; puis il s’en va et se vante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Il y a de l’or et beaucoup de rubis; mais les lèvres de la connaissance sont un vase précieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Prends son vêtement, car il a cautionné autrui; et prends de lui un gage, à cause des étrangers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Le pain du mensonge est agréable à l’homme; mais ensuite, sa bouche est pleine de gravier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Les plans s’affermissent par le conseil; et fais la guerre avec prudence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Qui va rapportant révèle le secret; aussi ne te mêle pas avec le bavard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Qui maudit son père et sa mère, – sa lampe s’éteindra au sein des ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'L’héritage acquis avec hâte au commencement, ne sera pas béni à la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Ne dis point: Je rendrai le mal. Attends-toi à l’ Éternel, et il te sauvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Poids et poids est en abomination à l’ Éternel, et la fausse balance n’est pas une chose bonne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Les pas de l’homme viennent de l’ Éternel; et comment un homme comprendrait-il sa propre voie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'C’est un piège pour l’homme que de dire précipitamment: Chose sainte! – et, après des vœux, d’examiner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Un roi sage disperse les méchants, et ramène sur eux la roue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'L’esprit de l’homme est une lampe de l’ Éternel; il sonde toutes les profondeurs du cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'La bonté et la vérité préservent le roi, et il soutient son trône par la bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'L’ornement des jeunes gens, c’est leur force; et la gloire des vieillards, ce sont les cheveux blancs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Les meurtrissures [et] les plaies nettoient le mal, et les coups, les profondeurs de l’âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Le cœur d’un roi, dans la main de l’ Éternel, est des ruisseaux d’eau; il l’incline à tout ce qui lui plaît.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Toute voie de l’homme est droite à ses yeux; mais l’ Éternel pèse les cœurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Pratiquer ce qui est juste et droit, est une chose plus agréable à l’ Éternel qu’un sacrifice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'L’élévation des yeux et un cœur qui s’enfle, la lampe des méchants, c’est péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Les pensées d’un homme diligent [ne mènent] qu’à l’abondance; mais tout étourdi [ne court] qu’à la disette.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Acquérir des trésors par une langue fausse, c’est une vanité fugitive de ceux qui cherchent la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'La dévastation des méchants les emporte, car ils refusent de pratiquer ce qui est droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'La voie d’un homme coupable est détournée; mais l’œuvre de celui qui est pur est droite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Mieux vaut habiter sur le coin d’un toit, que [d’avoir] une femme querelleuse et une maison en commun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'L’âme du méchant désire le mal; son prochain ne trouve pas grâce à ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Quand on punit le moqueur, le simple devient sage; et quand on instruit le sage, il reçoit de la connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Il y a un juste qui considère attentivement la maison du méchant, il renverse les méchants dans le malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Celui qui ferme son oreille au cri du pauvre, criera lui aussi, et on ne lui répondra pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Un don [fait] en secret apaise la colère, et un présent [mis] dans le sein [calme] une violente fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'C’est une joie pour le juste de pratiquer ce qui est droit, mais c’est la ruine pour les ouvriers d’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'L’homme qui s’égare du chemin de la sagesse demeurera dans l’assemblée des trépassés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Celui qui aime la joie sera dans l’indigence; celui qui aime le vin et l’huile ne s’enrichira pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Le méchant est une rançon pour le juste, et le perfide est à la place des hommes intègres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Mieux vaut habiter dans une terre déserte, qu’avec une femme querelleuse et irritable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Il y a un trésor désirable et de l’huile dans la demeure du sage; mais l’homme insensé les engloutit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Qui poursuit la justice et la bonté trouvera la vie, la justice, et la gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Le sage monte dans la ville des hommes forts, et abat la force de ce qui en faisait la sécurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Qui garde sa bouche et sa langue, garde son âme de détresses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Orgueilleux, arrogant, moqueur, est le nom de celui qui agit avec colère et orgueil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Le désir du paresseux le tue, car ses mains refusent de travailler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Tout le jour il désire avidement; mais le juste donne et ne retient pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Le sacrifice des méchants est une abomination; combien plus s’ils l’apportent avec une pensée mauvaise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Le témoin menteur périra; mais l’homme qui écoute parlera à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'L’homme méchant enhardit son visage, mais celui qui est droit règle sa voie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Il n’y a point de sagesse, et il n’y a point d’intelligence, et il n’y a point de conseil, en présence de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Le cheval est préparé pour le jour de la bataille, mais la délivrance est à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Une bonne renommée est préférable à de grandes richesses, et la bonne grâce à l’argent et à l’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Le riche et le pauvre se rencontrent: l’ Éternel les a tous faits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'L’homme avisé voit le mal et se cache; mais les simples passent outre et en portent la peine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'La fin de la débonnaireté, de la crainte de l’ Éternel, c’est la richesse, et la gloire, et la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Il y a des épines, des pièges, sur la voie du pervers; celui qui garde son âme s’en éloigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Élève le jeune garçon selon la règle de sa voie; même lorsqu’il vieillira, il ne s’en détournera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Le riche gouverne les pauvres, et celui qui emprunte est serviteur de l’homme qui prête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Qui sème l’injustice moissonnera le malheur, et la verge de son courroux prendra fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, '[Celui qui a] l’œil bienveillant sera béni, car il donne de son pain au pauvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Chasse le moqueur, et la querelle s’en ira, et les disputes et la honte cesseront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Celui qui aime la pureté de cœur a la grâce sur les lèvres, [et] le roi est son ami.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Les yeux de l’ Éternel gardent la connaissance, mais il renverse les paroles du perfide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Le paresseux dit: Il y a un lion là dehors, je serai tué au milieu des rues!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'La bouche des étrangères est une fosse profonde; celui contre qui l’ Éternel est irrité y tombera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'La folie est liée au cœur du jeune enfant; la verge de la correction l’éloignera de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Celui qui opprime le pauvre, ce sera pour l’enrichir; celui qui donne au riche, ce sera pour le faire tomber dans l’indigence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Incline ton oreille et écoute les paroles des sages, et applique ton cœur à ma science;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'car c’est une chose agréable si tu les gardes au-dedans de toi: elles seront disposées ensemble sur tes lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Afin que ta confiance soit en l’ Éternel, je te [les] ai fait connaître à toi, aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Ne t’ai-je pas écrit des choses excellentes en conseils et en connaissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'pour te faire connaître la sûre norme des paroles de vérité, afin que tu répondes des paroles de vérité à ceux qui t’envoient?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Ne pille pas le pauvre, parce qu’il est pauvre, et ne foule pas l’affligé à la porte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'car l’ Éternel prendra en main leur cause, et dépouillera l’âme de ceux qui les dépouillent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Ne sois pas l’ami de l’homme colère, et n’entre pas chez l’homme violent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'de peur que tu n’apprennes ses sentiers, et que tu n’emportes un piège dans ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Ne sois point parmi ceux qui frappent dans la main, parmi ceux qui se rendent caution pour des dettes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'si tu n’avais pas de quoi payer, pourquoi voudrais-tu qu’on prenne ton lit de dessous toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Ne recule pas la borne ancienne que tes pères ont faite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'As-tu vu un homme diligent dans son travail? il se tiendra devant les rois, il ne se tiendra pas devant des gens obscurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Quand tu t’assieds pour manger le pain avec un gouverneur, considère bien celui qui est devant toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'et mets un couteau à ta gorge, si tu es gourmand.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Ne désire point ses friandises, car c’est un pain trompeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Ne te fatigue pas pour acquérir des richesses, finis-en avec ta prudence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Jetteras-tu tes yeux sur elles?... Déjà elles ne sont plus; car certes elles se font des ailes, et, comme l’aigle, s’envolent vers les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Ne mange point le pain de celui qui a l’œil mauvais, et ne désire pas ses friandises;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'car comme il a pensé dans son âme, tel il est. Mange et bois, te dira-t-il; mais son cœur n’est pas avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Ton morceau que tu as mangé, tu le vomiras, et tu perdras tes paroles agréables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Ne parle pas aux oreilles du sot, car il méprisera la sagesse de ton discours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Ne recule pas la borne ancienne, et n’entre pas dans les champs des orphelins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'car leur rédempteur est fort, il prendra en main leur cause contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Applique ton cœur à l’instruction et tes oreilles aux paroles de la connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Ne manque pas de corriger le jeune garçon; quand tu l’auras frappé de la verge, il n’en mourra pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Tu le frapperas de la verge, mais tu délivreras son âme du shéol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Mon fils, si ton cœur est sage, mon cœur s’en réjouira, oui, moi-même,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'et mes reins s’égaieront quand tes lèvres diront des choses droites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Que ton cœur n’envie pas les méchants; mais sois tout le jour dans la crainte de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'car certainement il y a une fin, et ton attente ne sera pas réduite à néant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Toi, mon fils, écoute et sois sage, et dirige ton cœur dans le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Ne sois pas parmi les buveurs de vin, ni parmi les gourmands;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'car le buveur et le gourmand deviendront pauvres, et sommeiller revêt de haillons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Écoute ton père qui t’a engendré, et ne méprise pas ta mère quand elle aura vieilli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Achète la vérité, et ne la vends point, – la sagesse, et l’instruction, et l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Le père du juste aura beaucoup de joie, et celui qui a engendré le sage, se réjouira en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Que ton père et ta mère se réjouissent, et que celle qui t’a enfanté ait de la joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Mon fils, donne-moi ton cœur, et que tes yeux se plaisent à mes voies;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'car la prostituée est une fosse profonde, et l’étrangère un puits de détresse:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'aussi se tient-elle aux embûches comme un voleur, et elle augmente le nombre des perfides parmi les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Pour qui les: Hélas? Pour qui les: Malheur à moi? Pour qui les querelles, pour qui la plainte, pour qui les blessures sans cause? Pour qui la rougeur des yeux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Pour ceux qui s’attardent auprès du vin, qui vont essayer le vin mixtionné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, '– Ne regarde pas le vin quand il est vermeil, quand il est perlé dans la coupe, et qu’il coule aisément;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'à la fin, il mord comme un serpent et il pique comme une vipère:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'tes yeux regarderont les étrangères, et ton cœur dira des choses perverses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'et tu seras comme celui qui se coucherait au cœur de la mer, et comme celui qui se coucherait au sommet d’un mât...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'On m’a frappé, [et] je n’en ai point été malade; on m’a battu, [et] je ne l’ai pas su. Quand me réveillerai-je? J’y reviendrai, je le rechercherai encore!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'N’envie pas les hommes qui font le mal, et ne désire pas d’être avec eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'car leur cœur médite la destruction, et leurs lèvres parlent de tourment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Par la sagesse la maison est bâtie, et elle est établie par l’intelligence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'et par la connaissance les chambres sont remplies de tous les biens précieux et agréables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'L’homme sage a de la force, et l’homme de connaissance affermit sa puissance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'car sous une [sage] direction tu feras ta guerre, et le salut est dans le grand nombre des conseillers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'La sagesse est trop haute pour le fou, il n’ouvrira pas la bouche dans la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Celui qui pense à mal faire, on l’appellera intrigant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Le plan de la folie est péché, et le moqueur est en abomination aux hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Si tu perds courage au jour de la détresse, ta force est mince.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Délivre ceux qui sont menés à la mort, et ne te retire pas de ceux qui chancellent vers une mort violente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Si tu dis: Voici, nous n’en savions rien; celui qui pèse les cœurs, lui ne le considérera-t-il pas? et celui qui garde ton âme, lui le sait; et il rend à l’homme selon son œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Mon fils, mange du miel, car il est bon; et un rayon de miel est doux à ton palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Ainsi connais pour ton âme la sagesse: si tu l’as trouvée, il y a un avenir, et ton attente ne sera point réduite à néant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Méchant, ne mets pas des embûches contre l’habitation du juste, ne dévaste pas son gîte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Car le juste tombe sept fois, et se relève; mais les méchants trébuchent [pour tomber] dans le malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Si ton ennemi tombe, ne te réjouis pas; et s’il trébuche, que ton cœur ne s’égaie pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'de peur que l’ Éternel ne le voie, et que cela ne soit mauvais à ses yeux, et qu’il ne détourne de dessus lui sa colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Ne t’irrite pas à cause de ceux qui font le mal, n’envie pas les méchants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'car il n’y a pas d’avenir pour l’inique: la lampe des méchants s’éteindra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Mon fils, crains l’ Éternel et le roi; ne te mêle pas avec les gens remuants,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'car leur calamité surgira tout à coup; et qui sait la ruine des uns et des autres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, '*Ces choses aussi viennent des sages: Faire acception des personnes dans le jugement n’est pas bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Celui qui dit au méchant: Tu es juste, les peuples le maudiront, les peuplades seront indignées contre lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'mais ceux qui le reprennent seront agréables, et une bénédiction de bien viendra sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Celui qui répond des paroles justes embrasse les lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Prépare ton ouvrage au-dehors, et mets en état ton champ, et après, bâtis ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Ne sois pas témoin, sans motif, contre ton prochain; voudrais-tu donc tromper de tes lèvres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Ne dis pas: Comme il m’a fait, je lui ferai; je rendrai à l’homme selon son œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'J’ai passé près du champ de l’homme paresseux et près de la vigne de l’homme dépourvu de sens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'et voici, tout y était monté en chardons; les orties en avaient couvert la surface, et sa clôture de pierres était démolie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Et je regardai, j’y appliquai mon cœur; je vis, [et] je reçus instruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Un peu de sommeil, un peu d’assoupissement, un peu croiser les mains pour dormir...,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'et ta pauvreté viendra [comme] un voyageur, et ton dénuement comme un homme armé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, '*Ce sont ici aussi des proverbes de Salomon, que les gens d’Ézéchias, roi de Juda, ont transcrits:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'La gloire de Dieu est de cacher une chose, et la gloire des rois est de sonder une chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Les cieux en hauteur, et la terre en profondeur, et le cœur des rois, on ne peut les sonder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Ôte de l’argent les scories, et il en sortira un vase pour l’orfèvre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'ôte le méchant de devant le roi, et son trône sera affermi par la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Ne fais pas le magnifique devant le roi, et ne te tiens pas à la place des grands;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'car il vaut mieux qu’on te dise: Monte ici, que si l’on t’abaissait devant le prince que tes yeux voient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Ne sors pas à la hâte pour contester, de peur [que tu ne saches] que faire à la fin, lorsque ton prochain t’aura rendu confus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Plaide ta cause avec ton prochain, et ne révèle pas le secret d’autrui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'de peur que celui qui l’écoute ne te fasse honte, et que ton opprobre ne se retire pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Des pommes d’or incrustées d’argent, c’est la parole dite à propos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Un anneau d’or et un joyau d’or fin, tel est, pour l’oreille qui écoute, celui qui reprend sagement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'La fraîcheur de la neige au temps de la moisson, tel est le messager fidèle pour ceux qui l’envoient: il restaure l’âme de son maître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Les nuages et le vent, et point de pluie, tel est celui qui se glorifie faussement d’un présent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Par la lenteur à la colère un prince est gagné, et la langue douce brise les os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'As-tu trouvé du miel, manges-en ce qu’il t’en faut, de peur que tu n’en sois repu et que tu ne le vomisses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Mets rarement ton pied dans la maison de ton prochain, de peur qu’il ne soit rassasié de toi et qu’il ne te haïsse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'L’homme qui rend un faux témoignage contre son prochain est un marteau, et une épée, et une flèche aiguë.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'La confiance en un perfide, au jour de la détresse, est une dent cassée et un pied chancelant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, '[Comme] celui qui ôte son vêtement en un jour de froid, [comme] du vinaigre sur le nitre, tel est celui qui chante des chansons à un cœur affligé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Si celui qui te hait a faim, donne-lui du pain à manger, et, s’il a soif, donne-lui de l’eau à boire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'car tu entasseras des charbons ardents sur sa tête, et l’ Éternel te le rendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Le vent du nord enfante les averses; et les visages indignés, une langue [qui médit] en secret.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Mieux vaut habiter sur le coin d’un toit, que [d’avoir] une femme querelleuse et une maison en commun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Les bonnes nouvelles d’un pays éloigné sont de l’eau fraîche pour une âme altérée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Le juste qui chancelle devant le méchant est une fontaine trouble et une source corrompue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Manger beaucoup de miel n’est pas bon, et s’occuper de sa propre gloire n’est pas la gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'L’homme qui ne gouverne pas son esprit est une ville en ruine, sans murailles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Comme la neige en été, et comme la pluie dans la moisson, ainsi la gloire ne sied pas à un sot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Comme le moineau qui va çà et là, et l’hirondelle qui vole, ainsi la malédiction sans cause n’arrivera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Le fouet est pour le cheval, la bride pour l’âne, et la verge pour le dos des sots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Ne réponds pas au sot selon sa folie, de peur que toi aussi tu ne lui ressembles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Réponds au sot selon sa folie, de peur qu’il ne soit sage à ses propres yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Celui qui envoie des messages par la main d’un sot, se coupe les pieds [et] boit l’injustice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Les jambes du boiteux sont sans force: tel est un proverbe dans la bouche des sots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Celui qui donne de la gloire à un sot, c’est comme un sachet de pierres précieuses dans un tas de pierres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Une épine qui entre dans la main d’un homme ivre, tel est un proverbe dans la bouche des sots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Le puissant use de violence envers tout le monde: il prend à gages le sot et il prend à gages les passants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Comme le chien retourne à son vomissement, le sot répète sa folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'As-tu vu un homme sage à ses propres yeux? Il y a plus d’espoir pour un sot que pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Le paresseux dit: Il y a un [lion] rugissant sur le chemin, un lion dans les rues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'La porte tourne sur ses gonds, et le paresseux sur son lit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Le paresseux enfonce sa main dans le plat, il est las de la ramener à sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Le paresseux est plus sage à ses yeux que sept [hommes] qui répondent avec bon sens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Il saisit un chien par les oreilles, celui qui, en passant, s’emporte pour une dispute qui n’est pas la sienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Comme un fou qui jette des brandons, des flèches, et la mort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'ainsi est l’homme qui trompe son prochain, et qui dit: N’était-ce pas pour plaisanter?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Faute de bois, le feu s’éteint; et, quand il n’y a plus de rapporteurs, la querelle s’apaise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Du charbon sur le brasier et du bois sur le feu, ainsi est l’homme querelleur pour échauffer les disputes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Les paroles du rapporteur sont comme des friandises, et elles descendent jusqu’au-dedans des entrailles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Les lèvres brûlantes et le cœur mauvais sont comme de la litharge d’argent appliquée sur un vase de terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Celui qui hait se déguise par ses lèvres; mais au-dedans de lui il nourrit la fraude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Quand il rend sa voix gracieuse, ne le crois point, car il y a sept abominations dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'La haine se cache-t-elle sous la dissimulation, sa méchanceté sera découverte dans la congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Qui creuse une fosse y tombera, et la pierre retournera sur celui qui la roule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'La langue fausse hait ceux qu’elle a écrasés, et la bouche flatteuse amène la ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Ne te glorifie pas du jour de demain, car tu ne sais pas ce qu’un jour enfantera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Qu’un autre te loue, et non ta bouche, – un étranger, et non tes lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'La pierre est pesante et le sable est lourd; mais l’humeur d’un fou est plus pesante que tous les deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'La fureur est cruelle et la colère déborde, mais qui subsistera devant la jalousie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Mieux vaut une réprimande ouverte qu’un amour caché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Les blessures faites par un ami sont fidèles, mais les baisers de celui qui hait sont fréquents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'L’âme rassasiée foule aux pieds les rayons de miel, mais pour l’âme qui a faim tout ce qui est amer est doux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Comme un oiseau erre çà et là loin de son nid, ainsi est l’homme qui erre loin de son lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'L’huile et le parfum réjouissent le cœur, et la douceur d’un ami est [le fruit] d’un conseil qui vient du cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'N’abandonne point ton ami, ni l’ami de ton père, et n’entre pas dans la maison de ton frère au jour de ta calamité. Mieux vaut un voisin proche qu’un frère éloigné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Mon fils, sois sage et réjouis mon cœur, afin que j’aie de quoi répondre à celui qui m’outrage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'L’homme avisé voit le mal [et] se cache; les simples passent outre [et] en portent la peine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Prends son vêtement, car il a cautionné autrui; et prends de lui un gage, à cause de l’étrangère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'À celui qui bénit son ami à haute voix, se levant le matin de bonne heure, on le lui comptera comme une malédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Une gouttière continuelle en un jour de pluie, et une femme querelleuse, cela se ressemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Qui l’arrête, arrête le vent, et sa droite trouve de l’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Le fer s’aiguise par le fer, et un homme ranime le visage de son ami.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Celui qui soigne le figuier mange de son fruit, et celui qui veille sur son maître sera honoré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Comme dans l’eau le visage répond au visage, ainsi le cœur de l’homme répond à l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Le shéol et l’abîme sont insatiables, et les yeux de l’homme sont insatiables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Le creuset est pour l’argent, et le fourneau pour l’or, ainsi l’homme, pour la bouche qui le loue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Quand tu broierais le fou dans un mortier, au milieu du grain, avec un pilon, sa folie ne se retirerait pas de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Connais bien la face de ton menu bétail, veille sur tes troupeaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'car l’abondance n’est pas pour toujours, et une couronne [dure-t-elle] de génération en génération?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Le foin disparaît, et l’herbe tendre se montre, et l’on ramasse les herbes des montagnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Les agneaux sont pour ton vêtement, et les boucs pour le prix d’un champ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'et l’abondance du lait de tes chèvres pour ta nourriture, pour la nourriture de ta maison, et pour la vie de tes servantes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Le méchant se sauve quand personne ne le poursuit, mais les justes sont pleins d’assurance comme un jeune lion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'À cause de l’iniquité d’un pays, ses princes sont nombreux; mais, par un homme intelligent qui a de la connaissance, la stabilité se prolonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'L’homme pauvre qui opprime les misérables est une pluie violente qui [ne laisse] point de pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Ceux qui abandonnent la loi louent les méchants, mais ceux qui gardent la loi leur font la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Les hommes adonnés au mal ne comprennent pas le juste jugement, mais ceux qui cherchent l’ Éternel comprennent tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Mieux vaut le pauvre qui marche dans son intégrité, que l’homme pervers dans ses doubles voies, bien qu’il soit riche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Qui garde la loi est un fils intelligent; mais le compagnon des débauchés fait honte à son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Celui qui augmente son bien par l’intérêt et l’usure, l’amasse pour celui qui est bon pour les misérables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Qui détourne son oreille pour ne pas écouter la loi, sa prière même est une abomination.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Celui qui égare les hommes droits sur un mauvais chemin tombera lui-même dans la fosse qu’il aura creusée; mais les hommes intègres hériteront le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'L’homme riche est sage à ses yeux, mais le pauvre qui est intelligent le sonde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Quand les justes se réjouissent il y a beaucoup de gloire; mais quand les méchants se lèvent, les hommes se cachent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Celui qui cache ses transgressions ne prospérera point, mais celui qui les confesse et les abandonne obtiendra miséricorde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Bienheureux l’homme qui craint continuellement; mais celui qui endurcit son cœur tombera dans le malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Un lion rugissant et un ours à la poursuite de sa proie, c’est le dominateur méchant d’un peuple pauvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Le prince privé d’intelligence opprime beaucoup, [mais] celui qui hait le gain déshonnête prolongera [ses] jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'L’homme chargé du sang d’une âme fuira jusqu’à la fosse,... qu’on ne le retienne pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Qui marche dans l’intégrité sera sauvé, mais qui suit tortueusement deux voies tombera une fois pour toutes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Qui laboure sa terre sera rassasié de pain, mais qui court après les fainéants sera rassasié de pauvreté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'L’homme fidèle abonde en bénédictions, mais celui qui a hâte de s’enrichir ne demeurera pas innocent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Faire acception des personnes n’est pas bien; même pour un morceau de pain un homme commettra une transgression.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'L’homme qui a l’œil mauvais se hâte pour avoir des richesses, et il ne sait pas que la disette viendra sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Celui qui reprend un homme trouvera la faveur dans la suite, plutôt que celui qui flatte de la langue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Qui dépouille son père et sa mère, et dit: Ce n’est point une transgression, celui-là est compagnon du destructeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Celui qui a l’âme altière excite la querelle; mais qui se confie en l’ Éternel sera engraissé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Qui se confie en son propre cœur est un sot; mais qui marche dans la sagesse, celui-là sera délivré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Qui donne au pauvre ne manquera de rien, mais qui détourne les yeux sera comblé de malédictions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Quand les méchants se lèvent, les hommes se cachent; mais quand ils périssent, les justes se multiplient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'L’homme qui, étant souvent repris, roidit son cou, sera brisé subitement, et il n’y a pas de remède.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Quand les justes se multiplient, le peuple se réjouit; mais quand le méchant gouverne, le peuple gémit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'L’homme qui aime la sagesse est la joie de son père, mais le compagnon des prostituées dissipera son bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Un roi, par le juste jugement, affermit le pays, mais l’homme qui accepte des présents le ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'L’homme qui flatte son prochain étend un filet devant ses pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Dans la transgression de l’homme mauvais, il y a un piège; mais le juste chantera et se réjouira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Le juste prend connaissance de la cause des pauvres; le méchant ne comprend aucune connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Les hommes moqueurs mettent en feu une ville, mais les sages détournent la colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Un homme sage qui plaide avec un homme insensé, qu’il s’irrite ou qu’il rie, n’a point de repos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Les hommes de sang haïssent l’homme intègre, mais les hommes droits tiennent à sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Le sot met dehors tout son esprit, mais le sage le calme et le retient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Qu’un gouverneur prête attention à la parole de mensonge, tous ses serviteurs seront méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Le pauvre et l’oppresseur se rencontrent, l’ Éternel éclaire les yeux de tous deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Le roi qui juge les pauvres selon la vérité,... son trône sera affermi pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'La verge et la répréhension donnent la sagesse, mais le jeune garçon abandonné à lui-même fait honte à sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Quand les méchants se multiplient, la transgression se multiplie; mais les justes verront leur chute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Corrige ton fils, et il te donnera du repos et procurera des délices à ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Quand il n’y a point de vision, le peuple est sans frein; mais bienheureux celui qui garde la loi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Un serviteur n’est pas corrigé par des paroles; car il comprend, mais il ne répond pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'As-tu vu un homme précipité dans ses paroles? Il y a plus d’espoir pour un sot que pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Celui qui gâte son serviteur dès sa jeunesse, le verra fils à la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'L’homme colère excite les querelles, et l’homme qui se met en fureur abonde en transgressions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'L’orgueil d’un homme l’abaisse, mais celui qui est humble d’esprit acquiert la gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Qui partage avec un voleur hait son âme; il entend l’adjuration, et ne déclare pas [la chose].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'La crainte des hommes tend un piège, mais qui se confie en l’ Éternel est élevé dans une haute retraite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Plusieurs cherchent la face du gouverneur, mais le juste jugement d’un homme vient de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'L’homme inique est l’abomination des justes, et celui qui est droit dans sa voie, l’abomination du méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, '***Paroles d’Agur, fils de Jaké, l’oracle prononcé par cet homme à Ithiel, à Ithiel et à Ucal:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Certes, moi je suis plus stupide que personne, et je n’ai pas l’intelligence d’un homme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'et je n’ai pas appris la sagesse, ni ne possède la connaissance du Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Qui est monté dans les cieux, et qui en est descendu? Qui a rassemblé le vent dans le creux de ses mains? Qui a serré les eaux dans un manteau? Qui a établi toutes les bornes de la terre? Quel est son nom, et quel est le nom de son fils, si tu le sais?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Toute parole de ✝Dieu est affinée; il est un bouclier pour ceux qui s’attendent à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'N’ajoute pas à ses paroles, de peur qu’il ne te reprenne, et que tu ne sois trouvé menteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Je te demanderai deux choses; ne me les refuse pas, avant que je meure:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Éloigne de moi la vanité et la parole de mensonge; ne me donne ni pauvreté ni richesse; nourris-moi du pain qui m’est nécessaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'de peur que je ne sois rassasié, et que je ne te renie et ne dise: Qui est l’ Éternel? et de peur que je ne sois appauvri, et que je ne dérobe, et que je ne parjure le nom de mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'N’accuse pas un serviteur auprès de son maître, de peur qu’il ne te maudisse, et que tu n’en portes la peine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Il est une génération qui maudit son père et qui ne bénit pas sa mère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'une génération pure à ses propres yeux et qui n’est pas lavée de son ordure,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'une génération,... que ses yeux sont hautains, et ses paupières élevées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, '– une génération dont les dents sont des épées et les molaires des couteaux, pour dévorer les affligés de dessus la terre, et les nécessiteux d’entre les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'La sangsue a deux filles: Donne! donne! Il y a trois choses qui sont insatiables, quatre qui ne disent pas: C’est assez!...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'le shéol, et la matrice stérile, la terre qui n’est pas rassasiée d’eau, et le feu, qui ne dit pas: C’est assez!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'L’œil qui se moque d’un père et qui méprise l’obéissance envers la mère, les corbeaux du torrent le crèveront et les petits de l’aigle le dévoreront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Trois choses sont trop merveilleuses pour moi, et il en est quatre que je ne puis connaître:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'le chemin de l’aigle dans les cieux, le chemin du serpent sur le rocher, le chemin d’un navire au cœur de la mer, et le chemin de l’homme vers la jeune fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Tel est le chemin de la femme adultère: elle mange et s’essuie la bouche, et dit: Je n’ai point commis d’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Sous trois choses la terre tremble, et sous quatre elle n’en peut plus:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'sous le serviteur quand il règne, et l’homme vil quand il est rassasié de pain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'sous la femme odieuse quand elle se marie, et la servante quand elle hérite de sa maîtresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Il y a quatre choses petites sur la terre, qui sont sages entre les sages:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'les fourmis, peuple sans force, et qui préparent en été leurs vivres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'les damans, peuple sans puissance, et qui ont placé leurs maisons dans le rocher;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'les sauterelles n’ont point de roi, mais elles sortent toutes par bandes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'tu saisis le lézard avec les mains, et il est dans les palais des rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Il y a trois choses qui ont une belle allure, et quatre qui ont une belle démarche:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'le lion, le fort parmi les bêtes, et qui ne se détourne devant qui que ce soit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'le [coursier] qui a les reins ceints; ou le bouc; et le roi, contre qui personne ne peut se lever.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Si tu as agi follement en t’élevant et si tu as pensé à mal, [mets] la main sur ta bouche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Car la pression du lait produit le beurre, et la pression du nez fait sortir le sang, et la pression de la colère excite la querelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, '***Paroles du roi Lemuel, l’oracle que sa mère lui enseigna:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Quoi, mon fils? et quoi, fils de mon ventre? et quoi, fils de mes vœux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Ne donne point ta force aux femmes, ni tes voies à celles qui perdent les rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ce n’est point aux rois, Lemuel, ce n’est point aux rois de boire du vin, ni aux grands [de dire]: Où sont les boissons fortes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'de peur qu’ils ne boivent, et n’oublient le statut, et ne fassent fléchir le jugement de tous les fils de l’affliction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Donnez de la boisson forte à celui qui va périr, et du vin à ceux qui ont l’amertume dans le cœur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'qu’il boive et qu’il oublie sa pauvreté, et ne se souvienne plus de ses peines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Ouvre ta bouche pour le muet, pour la cause de tous les délaissés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Ouvre ta bouche, juge avec justice, et fais droit à l’affligé et au pauvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, '*Une femme vertueuse! Qui la trouvera? Car son prix est bien au-delà des rubis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Le cœur de son mari se confie en elle, et il ne manquera point de butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Elle lui fait du bien et non du mal, tous les jours de sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Elle cherche de la laine et du lin, et travaille de ses mains avec joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Elle est comme les navires d’un marchand, elle amène son pain de loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Elle se lève quand il est encore nuit, et elle donne la nourriture à sa maison, et la tâche à ses servantes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Elle pense à un champ, et elle l’acquiert; du fruit de ses mains elle plante une vigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Elle ceint ses reins de force, et fortifie ses bras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Elle éprouve que son trafic est bon; de nuit sa lampe ne s’éteint pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Elle met la main à la quenouille, et ses doigts tiennent le fuseau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Elle étend sa main vers l’affligé, et tend ses mains au nécessiteux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Elle ne craint pas la neige pour sa maison, car toute sa maison est vêtue d’écarlate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Elle se fait des tapis; le fin coton et la pourpre sont ses vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Son mari est connu dans les portes quand il s’assied avec les anciens du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Elle fait des chemises, et les vend; et elle livre des ceintures au marchand.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Elle est vêtue de force et de dignité, et elle se rit du jour à venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Elle ouvre sa bouche avec sagesse, et la loi de la bonté est sur sa langue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Elle surveille les voies de sa maison, et ne mange pas le pain de paresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Ses fils se lèvent et la disent bienheureuse, son mari [aussi], et il la loue:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Plusieurs filles ont agi vertueusement; mais toi, tu les surpasses toutes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'La grâce est trompeuse, et la beauté est vanité; la femme qui craint l’ Éternel, c’est elle qui sera louée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Donnez-lui du fruit de ses mains, et qu’aux portes ses œuvres la louent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Les paroles du Prédicateur, fils de David, roi à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Vanité des vanités, dit le prédicateur; vanité des vanités! Tout est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Quel profit a l’homme de tout son labeur dont il se tourmente sous le soleil?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Une génération s’en va, et une génération vient; et la terre subsiste toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Et le soleil se lève, et le soleil se couche, et il se hâte vers son lieu où il se lève.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Le vent va vers le midi, et il tourne vers le nord; il tourne et retourne; et le vent revient sur ses circuits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Toutes les rivières vont vers la mer, et la mer n’est pas remplie; au lieu où les rivières allaient, là elles vont de nouveau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Toutes choses travaillent, l’homme ne peut le dire; l’œil ne se rassasie pas de voir, et l’oreille ne se satisfait pas d’entendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Ce qui a été, c’est ce qui sera; et ce qui a été fait, c’est ce qui se fera; et il n’y a rien de nouveau sous le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Y a-t-il une chose dont on puisse dire: Regarde ceci, c’est nouveau? – Elle a été déjà, dans les siècles qui furent avant nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Il n’y a pas de souvenir des choses qui ont précédé; et de même, de celles qui seront après, il n’y en aura pas de souvenir chez ceux qui vivront plus tard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Moi, le prédicateur, j’ai été roi sur Israël à Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'et j’ai appliqué mon cœur à rechercher et à explorer par la sagesse tout ce qui se fait sous les cieux: c’est une occupation ingrate que Dieu a donnée aux fils des hommes afin qu’ils s’y fatiguent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'J’ai vu tous les travaux qui se font sous le soleil; et voici, tout est vanité et poursuite du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Ce qui est tordu ne peut être redressé, et ce qui manque ne peut être compté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'J’ai parlé en mon cœur, disant: Voici, je suis devenu grand et j’ai acquis de la sagesse plus que tous ceux qui ont été avant moi sur Jérusalem, et mon cœur a vu beaucoup de sagesse et de connaissance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'et j’ai appliqué mon cœur à la connaissance de la sagesse et à la connaissance des choses déraisonnables et de la folie. J’ai connu que cela aussi, c’est la poursuite du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Car à beaucoup de sagesse, beaucoup de chagrin; et qui augmente la connaissance, augmente la douleur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'J’ai dit en mon cœur: Allons! je t’éprouverai par la joie: jouis donc du bien-être. Et voici, cela aussi est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'J’ai dit au rire: [Tu es] déraison; et à la joie: Que fait-elle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'J’ai recherché en mon cœur de traiter ma chair avec du vin, tout en conduisant mon cœur par la sagesse, et de saisir la folie, jusqu’à ce que je voie quel serait, pour les fils des hommes, ce bien qu’ils feraient sous les cieux tous les jours de leur vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'J’ai fait de grandes choses: je me suis bâti des maisons, je me suis planté des vignes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'je me suis fait des jardins et des parcs, et j’y ai planté des arbres à fruit de toute espèce;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'je me suis fait des réservoirs d’eau pour en arroser la forêt où poussent les arbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'J’ai acquis des serviteurs et des servantes, et j’en ai eu qui sont nés dans ma maison; j’ai eu aussi des troupeaux de gros et de menu bétail, en grand nombre, plus que tous ceux qui ont été avant moi à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Je me suis aussi amassé de l’argent et de l’or, et les trésors des rois et des provinces; je me suis procuré des chanteurs et des chanteuses, et les délices des fils des hommes, une femme et des concubines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Et je suis devenu grand et je me suis accru plus que tous ceux qui ont été avant moi à Jérusalem; et pourtant ma sagesse est demeurée avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Et quoi que mes yeux aient désiré, je ne les en ai point privés; je n’ai refusé à mon cœur aucune joie, car mon cœur s’est réjoui de tout mon travail, et c’est là la part que j’ai eue de tout mon travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Et je me suis tourné vers toutes les œuvres que mes mains avaient faites, et vers tout le travail dont je m’étais travaillé pour [les] faire; et voici, tout était vanité et poursuite du vent, et il n’y en avait aucun profit sous le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Et je me suis tourné pour voir la sagesse, et les choses déraisonnables et la folie; car que fera l’homme qui viendra après le roi? – ce qui a été déjà fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Et j’ai vu que la sagesse a un avantage sur la folie, comme la lumière a un avantage sur les ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Le sage a ses yeux à sa tête, et le fou marche dans les ténèbres; mais j’ai connu, moi aussi, qu’un même sort les atteint tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Et j’ai dit en mon cœur: Le sort du fou m’atteint, moi aussi; et pourquoi alors ai-je été si sage? Et j’ai dit en mon cœur que cela aussi est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Car jamais on ne se souviendra du sage, non plus que du fou, puisque déjà dans les jours qui viennent tout est oublié. Et comment le sage meurt-il comme le fou?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Et j’ai haï la vie, parce que l’œuvre qui se fait sous le soleil m’a été à charge, car tout est vanité et poursuite du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Et j’ai haï tout le travail auquel j’ai travaillé sous le soleil, parce que je dois le laisser à l’homme qui sera après moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Et qui sait s’il sera un sage ou un sot? Et il sera maître de tout mon travail auquel j’ai travaillé et dans lequel j’ai été sage sous le soleil. Cela aussi est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Alors je me suis mis à faire désespérer mon cœur à l’égard de tout le travail dont je me suis travaillé sous le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Car il y a tel homme qui a travaillé avec sagesse, et avec connaissance, et avec droiture, et qui laisse [ce qu’il a acquis] à un homme qui n’y a pas travaillé, pour être son partage. Cela aussi est vanité et un grand mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Car qu’est-ce que l’homme a de tout son travail, et de la poursuite de son cœur, dont il s’est tourmenté sous le soleil?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Car tous ses jours sont douleur, et son occupation est chagrin; même la nuit son cœur ne repose pas. Cela aussi est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Il n’y a rien de bon pour l’homme que de manger et de boire, et de faire jouir son âme du bien-être dans son travail. Et j’ai vu que cela aussi vient de la main de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Car qui peut manger, et qui peut jouir plus que moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Car à l’homme qui est bon devant lui, [Dieu] donne sagesse et connaissance et joie; mais à celui qui pèche, il donne l’occupation de rassembler et d’amasser, pour donner à celui qui est bon devant Dieu. Cela aussi est vanité et poursuite du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Il y a une saison pour tout, et il y a un temps pour toute affaire sous les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Il y a un temps de naître, et un temps de mourir; un temps de planter, et un temps d’arracher ce qui est planté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'un temps de tuer, et un temps de guérir; un temps de démolir, et un temps de bâtir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'un temps de pleurer, et un temps de rire; un temps de se lamenter, et un temps de sauter de joie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'un temps de jeter des pierres, et un temps d’amasser des pierres; un temps d’embrasser, et un temps de s’éloigner des embrassements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'un temps de chercher, et un temps de perdre; un temps de garder, et un temps de jeter;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'un temps de déchirer, et un temps de coudre; un temps de se taire, et un temps de parler;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'un temps d’aimer, et un temps de haïr; un temps de guerre, et un temps de paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Celui qui agit, quel profit a-t-il de ce à quoi il travaille?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'J’ai vu l’occupation que Dieu a donnée aux fils des hommes pour s’y fatiguer:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'il a fait toute chose belle en son temps; et il a mis le monde dans leur cœur, de sorte que l’homme ne peut comprendre, depuis le commencement jusqu’à la fin, l’œuvre que Dieu a faite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'J’ai connu qu’il n’y a rien de bon pour eux, sauf de se réjouir et de se faire du bien pendant leur vie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'et aussi que tout homme mange et boive, et qu’il jouisse du bien-être dans tout son travail: cela, c’est un don de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'J’ai connu que tout ce que Dieu fait subsiste à toujours; il n’y a rien à y ajouter, ni rien à en retrancher; et Dieu le fait, afin que, devant lui, on craigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Ce qui est a déjà été, et ce qui est à venir est déjà arrivé, et Dieu ramène ce qui est passé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Et j’ai encore vu sous le soleil que, dans le lieu du jugement, là il y avait la méchanceté, et que, dans le lieu de la justice, là il y avait la méchanceté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'J’ai dit en mon cœur: Dieu jugera le juste et le méchant; car il y a là un temps pour toute affaire et pour toute œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'J’ai dit en mon cœur: Quant aux fils des hommes [il en est ainsi], pour que Dieu les éprouve, et qu’ils voient eux-mêmes qu’ils ne sont que des bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Car ce qui arrive aux fils des hommes est aussi ce qui arrive aux bêtes; il y a pour tous un même sort: comme celle-ci meurt, ainsi meurt celui-là; et ils ont tous un même souffle, et l’homme n’a point d’avantage sur la bête, car tout est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Tout va dans un même lieu, tout est de poussière, et tout retourne à la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Qui est-ce qui connaît l’esprit des fils des hommes? Celui-ci monte-t-il en haut, et l’esprit de la bête descend-il en bas dans la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Et j’ai vu qu’il n’y a rien de mieux [que ceci]: que l’homme se réjouisse dans ce qu’il fait, car c’est là sa part; car qui l’amènera pour voir ce qui sera après lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Et je me suis tourné, et j’ai regardé toutes les oppressions qui se font sous le soleil; et voici les larmes des opprimés, et il n’y a point pour eux de consolateur! Et la force est dans la main de leurs oppresseurs, et il n’y a point pour eux de consolateur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'C’est pourquoi j’estime heureux les morts qui sont déjà morts, plutôt que les vivants qui sont encore vivants,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'et plus heureux encore que tous les deux celui qui n’a pas encore été, qui n’a pas vu le mauvais travail qui se fait sous le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Et j’ai vu tout le labeur et toute l’habileté dans le travail: que c’est une jalousie de l’un contre l’autre. Cela aussi est vanité et poursuite du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Le sot se croise les mains, et mange sa propre chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Mieux vaut le creux de la main rempli, et le repos, que les deux mains pleines, avec le travail et la poursuite du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Et je me tournai, et je vis la vanité sous le soleil:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'tel est seul sans qu’il y ait de second: il n’a pas non plus de fils ni de frère, et il n’y a pas de fin à tout son labeur; son œil n’est pas non plus rassasié par la richesse, et [il ne se dit pas]: Pour qui donc est-ce que je me tourmente et que je prive mon âme de bonheur? Cela aussi est une vanité et une ingrate occupation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Deux valent mieux qu’un; car ils ont un bon salaire de leur travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Car, s’ils tombent, l’un relèvera son compagnon; mais malheur à celui qui est seul, et qui tombe, et qui n’a pas de second pour le relever!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'De même, si l’on couche à deux, on a de la chaleur; mais celui qui est seul, comment aura-t-il chaud?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Et si quelqu’un a le dessus sur un seul, les deux lui tiendront tête; et la corde triple ne se rompt pas vite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Mieux vaut un jeune garçon pauvre et sage, qu’un roi vieux et sot qui ne sait plus être averti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Car il est sorti de la maison des prisonniers pour régner, lors même qu’il est né pauvre dans son royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'J’ai vu tous les vivants qui marchent sous le soleil, avec le jeune garçon, le second, qui occupera sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Il n’y a pas de fin à tout le peuple, à tous ceux qui ont été devant eux; cependant ceux qui viendront après ne se réjouiront point en lui. Car cela aussi est vanité et poursuite du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 17, 'Prends garde à ton pied, quand tu vas dans la maison de Dieu, et approche-toi pour entendre, plutôt que pour donner le sacrifice des sots; car ils ne savent pas qu’ils font mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Ne te presse point de ta bouche, et que ton cœur ne se hâte point de proférer une parole devant Dieu; car Dieu est dans les cieux, et toi sur la terre: c’est pourquoi, que tes paroles soient peu nombreuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Car le songe vient de beaucoup d’occupations, et la voix du sot de beaucoup de paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Quand tu auras voué un vœu à Dieu, ne tarde point à l’acquitter; car il ne prend pas plaisir aux sots: ce que tu auras voué, accomplis-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Mieux vaut que tu ne fasses point de vœu, que d’en faire un et de ne pas l’accomplir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Ne permets pas à ta bouche de faire pécher ta chair, et ne dis point devant l’ange que c’est une erreur. Pourquoi Dieu se courroucerait-il à ta voix, et détruirait-il l’œuvre de tes mains?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Car dans la multitude des songes il y a des vanités, et aussi dans beaucoup de paroles; mais crains Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Si tu vois le pauvre opprimé et le droit et la justice violentés dans une province, ne t’étonne pas de cela; car il y en a un qui est haut au-dessus des hauts, [et] qui y prend garde, et il y en a de plus hauts qu’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'La terre est profitable à tous égards, le roi même est asservi à la glèbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Celui qui aime l’argent n’est point rassasié par l’argent, et celui qui aime les richesses ne l’est pas par le revenu. Cela aussi est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Avec l’augmentation des biens, ceux qui les mangent augmentent aussi; et quel profit en a le maître, sauf qu’ il les voit de ses yeux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Le sommeil est doux pour celui qui travaille, qu’il mange peu ou beaucoup; mais le rassasiement du riche ne le laisse pas dormir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Il y a un mal douloureux que j’ai vu sous le soleil: les richesses sont conservées à leurs maîtres pour leur détriment,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, '– ou ces richesses périssent par quelque circonstance malheureuse, et il a engendré un fils, et il n’a rien en sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Comme il est sorti du ventre de sa mère, il s’en retournera nu, s’en allant comme il est venu, et de son travail il n’emportera rien qu’il puisse prendre dans sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Et cela aussi est un mal douloureux, que, tout comme il est venu, ainsi il s’en va; et quel profit a-t-il d’avoir travaillé pour le vent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Il mange aussi tous les jours de sa vie dans les ténèbres et se chagrine beaucoup, et est malade et irrité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Voici ce que j’ai vu de bon et de beau: c’est de manger et de boire et de jouir du bien-être dans tout le travail dont [l’homme] se tourmente sous le soleil tous les jours de sa vie, que Dieu lui a donnés; car c’est là sa part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Et encore tout homme auquel Dieu donne de la richesse et des biens, et le pouvoir d’en manger et d’en prendre sa part, et de se réjouir en son travail,... c’est là un don de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'car il ne se souviendra pas beaucoup des jours de sa vie; car Dieu lui a donné une réponse dans la joie de son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Il y a un mal que j’ai vu sous le soleil, et qui est fréquent parmi les hommes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'il y a tel homme à qui Dieu donne de la richesse, et des biens, et de l’honneur, et il ne manque rien à son âme de tout ce qu’il désire; et Dieu ne lui a pas donné le pouvoir d’en manger, car un étranger s’en repaît. Cela est une vanité et un mal douloureux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Si un homme engendre 100 [fils], et qu’il vive beaucoup d’années, et que les jours de ses années soient en grand nombre, et que son âme ne soit pas rassasiée de bien, et aussi qu’il n’ait pas de sépulture, je dis que mieux vaut un avorton que lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'car celui-ci vient dans la vanité, et il s’en va dans les ténèbres, et son nom est couvert de ténèbres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'et aussi il n’a pas vu et n’a pas connu le soleil: celui-ci a plus de repos que celui-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Et s’il vivait deux fois 1 000 ans, il n’aura pas vu le bonheur: tous ne vont-ils pas en un même lieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Tout le travail de l’homme est pour sa bouche, et cependant son désir n’est pas satisfait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Car quel avantage le sage a-t-il sur le sot? Quel [avantage] a l’affligé qui sait marcher devant les vivants?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Mieux vaut la vue des yeux que le mouvement du désir. Cela aussi est vanité et poursuite du vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Ce qui existe a déjà été appelé de son nom; et on sait ce qu’est l’homme, et qu’il ne peut contester avec celui qui est plus fort que lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Car il y a beaucoup de choses qui multiplient la vanité: quel avantage en a l’homme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Car qui sait ce qui est bon pour l’homme dans la vie, tous les jours de la vie de sa vanité, qu’il passe comme une ombre? Et qui déclarera à l’homme ce qui sera après lui sous le soleil?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Mieux vaut une bonne renommée que le bon parfum, et le jour de la mort que le jour de la naissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Mieux vaut aller dans la maison de deuil, que d’aller dans la maison de festin, en ce que là est la fin de tout homme; et le vivant prend cela à cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Mieux vaut le chagrin que le rire, car le cœur est rendu meilleur par la tristesse du visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Le cœur des sages est dans la maison de deuil, mais le cœur des sots, dans la maison de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Mieux vaut écouter la répréhension du sage, que d’écouter la chanson des sots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Car comme le bruit des épines sous la marmite, ainsi est le rire du sot. Cela aussi est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Certainement, l’oppression rend insensé le sage, et le don ruine le cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Mieux vaut la fin d’une chose que son commencement. Mieux vaut un esprit patient qu’un esprit hautain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Ne te hâte pas en ton esprit pour t’irriter, car l’irritation repose dans le sein des sots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Ne dis pas: Comment se fait-il que les jours précédents ont été meilleurs que ceux-ci? car ce n’est pas par sagesse que tu t’enquiers de cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'La sagesse est aussi bonne qu’un héritage, et profitable pour ceux qui voient le soleil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'car on est à l’ombre de la sagesse [comme] à l’ombre de l’argent; mais l’avantage de la connaissance, [c’est que] la sagesse fait vivre celui qui la possède.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Considère l’œuvre de Dieu, car qui peut redresser ce qu’il a tordu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Au jour du bien-être, jouis du bien-être, et, au jour de l’adversité, prends garde; car Dieu a placé l’un vis-à-vis de l’autre, afin que l’homme ne trouve rien [de ce qui sera] après lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'J’ai vu tout [cela] dans les jours de ma vanité: il y a tel juste qui périt par sa justice, et il y a tel méchant qui prolonge [ses jours] par son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Ne sois pas juste à l’excès, et ne fais pas le sage outre mesure; pourquoi te détruirais-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Ne sois pas méchant à l’excès, et ne sois pas insensé; pourquoi mourrais-tu avant ton temps? –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Il est bon que tu saisisses ceci et que tu ne retires point ta main de cela; car qui craint Dieu sort de tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'La sagesse fortifie le sage plus que dix hommes puissants qui sont dans la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Certes, il n’y a pas d’homme juste sur la terre qui ait fait le bien et qui n’ait pas péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Aussi ne mets pas ton cœur à toutes les paroles qu’on dit, afin que tu n’entendes pas ton serviteur te maudissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Car aussi ton cœur sait que bien des fois, toi aussi, tu as maudit les autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'J’ai éprouvé tout cela par la sagesse; j’ai dit: Je serai sage; mais elle était loin de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Ce qui a été est loin et très profond, qui le trouvera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Je me suis mis, moi et mon cœur, à connaître et à explorer et à rechercher la sagesse et l’intelligence, et à connaître que la méchanceté est sottise, et la folie, déraison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'et j’ai trouvé plus amère que la mort la femme dont le cœur est [comme] des filets et des rets, [et] dont les mains sont des chaînes: celui qui est agréable à Dieu lui échappera, mais celui qui pèche sera pris par elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Regarde ceci que j’ai trouvé, dit le prédicateur, [en examinant les choses] une à une pour en trouver la raison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'ce que mon âme cherche encore et que je n’ai pas trouvé: j’ai trouvé un homme entre mille, mais une femme entre elles toutes, je ne l’ai pas trouvée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Seulement, voici, j’ai trouvé que Dieu a fait l’homme droit; mais eux, ils ont cherché beaucoup de raisonnements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Qui est comme le sage? et qui sait l’explication des choses? La sagesse d’un homme illumine son visage, et l’arrogance de son visage en est changée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Je [dis]: Prends garde au commandement du roi, et cela à cause du serment [fait] à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Ne te presse pas de t’en aller de devant lui; ne persévère point dans une chose mauvaise; car tout ce qu’il lui plaît, il le fait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'parce que la parole du roi est une puissance, et qui lui dira: Que fais-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Celui qui garde le commandement ne connaîtra aucun mal; et le cœur du sage connaît le temps et le jugement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'car pour toute chose il y a un temps et un jugement. Car la misère de l’homme abonde sur lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'car il ne sait pas ce qui adviendra; car comment cela arrivera, qui le lui déclarera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Il n’y a point d’homme qui ait pouvoir sur l’esprit pour emprisonner l’esprit, et il n’y a personne qui ait de la puissance sur le jour de la mort, et il n’y a point de dispense dans une telle guerre, et la méchanceté ne délivrera pas ceux qui la pratiquent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'J’ai vu tout cela, et j’ai appliqué mon cœur à toute œuvre qui se fait sous le soleil. Il est un temps où des hommes dominent sur des hommes pour leur mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Et de même j’ai vu des méchants enterrés et s’en allant, mais ceux qui avaient bien fait s’en allaient du lieu saint, et étaient oubliés dans la ville. Cela aussi est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Parce que la sentence contre les mauvaises œuvres ne s’exécute pas immédiatement, à cause de cela le cœur des fils des hommes est au-dedans d’eux plein [d’envie] de faire le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Bien que le pécheur fasse le mal 100 fois et prolonge [ses jours], je sais cependant que [tout] ira bien pour ceux qui craignent Dieu, parce qu’ils craignent sa face;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'mais il n’y aura pas de bonheur pour le méchant, et il ne prolongera pas [ses] jours, comme l’ombre, parce qu’il ne craint pas la face de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Il est encore une vanité qui a lieu sur la terre: c’est qu’il y a des justes auxquels il arrive selon l’œuvre des méchants, et il y a des méchants auxquels il arrive selon l’œuvre des justes. J’ai dit que cela aussi est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Et j’ai loué la joie, parce qu’il n’y a rien de bon pour l’homme, sous le soleil, que de manger et de boire et de se réjouir; et c’est ce qui lui demeurera de son travail durant les jours de sa vie que Dieu lui donne sous le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Lorsque j’ai appliqué mon cœur à connaître la sagesse et à regarder les choses qui se font sur la terre (car il y a tel homme qui, ni jour ni nuit, ne voit le sommeil de ses yeux),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'alors j’ai vu que tout [est] l’œuvre de Dieu, [et] que l’homme ne peut pas trouver l’œuvre qui se fait sous le soleil: bien que l’homme se travaille pour la chercher, il ne la trouve point; et même si le sage se propose de la connaître, il ne peut la trouver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Car j’ai appliqué mon cœur à tout cela, et pour examiner tout cela, [savoir] que les justes et les sages, et leurs travaux, sont dans la main de Dieu: l’homme ne connaît ni l’amour ni la haine. Tout est devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Tout arrive également à tous: un même événement au juste et au méchant, au bon et au pur, et à l’impur, à celui qui sacrifie et à celui qui ne sacrifie pas; comme l’homme de bien, ainsi le pécheur; celui qui jure, comme celui qui craint le serment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'C’est un mal dans tout ce qui se fait sous le soleil, qu’un même événement arrive à tous; et aussi le cœur des fils des hommes est plein de mal, et la folie est dans leur cœur pendant qu’ils vivent; et après cela [ils vont] vers les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Car pour celui qui est lié à tous les vivants il y a de l’espoir, car un chien vivant vaut mieux qu’un lion mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Car les vivants savent qu’ils mourront; mais les morts ne savent rien du tout; et il n’y a plus pour eux de salaire, car leur mémoire est oubliée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Leur amour aussi, et leur haine, et leur envie, ont déjà péri, et ils n’ont plus de part, à jamais, dans tout ce qui se fait sous le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Va, mange ton pain avec joie, et bois ton vin d’un cœur heureux; car Dieu a déjà tes œuvres pour agréables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Qu’en tout temps tes vêtements soient blancs, et que l’huile ne manque pas sur ta tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Jouis de la vie avec la femme que tu aimes, tous les jours de la vie de ta vanité, qui t’a été donnée sous le soleil, tous les jours de ta vanité; car c’est là ta part dans la vie et dans ton travail auquel tu as travaillé sous le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Tout ce que ta main trouve à faire, fais-le selon ton pouvoir; car il n’y a ni œuvre, ni combinaison, ni connaissance, ni sagesse, dans le shéol, où tu vas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Je me suis tourné, et j’ai vu sous le soleil que la course n’est point aux agiles, ni la bataille aux hommes forts, ni le pain aux sages, ni les richesses aux intelligents, ni la faveur à ceux qui ont de la connaissance; car le temps et les circonstances les atteignent tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Car aussi l’homme ne connaît pas son temps, comme les poissons qui sont pris dans le filet de malheur, et comme les oiseaux qui sont pris dans le piège: comme eux, les fils des hommes sont enlacés dans un temps mauvais, lorsqu’il tombe sur eux subitement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'J’ai vu aussi cette sagesse sous le soleil, et elle a été grande pour moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'il y avait une petite ville, et peu d’hommes dedans; et un grand roi vint contre elle, et l’investit, et bâtit contre elle de grandes terrasses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'or il s’y trouva un homme pauvre [et] sage, qui délivra la ville par sa sagesse; mais personne ne se souvint de cet homme pauvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Et j’ai dit: Mieux vaut la sagesse que la force; mais la sagesse du pauvre est méprisée, et ses paroles ne sont pas écoutées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Les paroles des sages sont écoutées dans la tranquillité, plus que le cri de celui qui gouverne parmi les sots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Mieux vaut la sagesse, que les instruments de guerre, et un seul pécheur détruit beaucoup de bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Les mouches mortes font sentir mauvais, elles font fermenter l’huile du parfumeur; [ainsi fait] un peu de folie, [à l’égard de] celui qui est estimé pour sa sagesse et sa gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Le cœur du sage est à sa droite, et le cœur du sot, à sa gauche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'et même, quand l’insensé marche dans le chemin, le sens lui manque, et il dit à chacun qu’il est un insensé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Si l’esprit du gouverneur s’élève contre toi, ne quitte pas ta place; car la douceur apaise de grands péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Il est un mal que j’ai vu sous le soleil, comme une erreur provenant du gouverneur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'le manque de sens est placé dans de hautes dignités, et les riches sont assis dans une position basse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'J’ai vu des serviteurs sur des chevaux, et des princes marchant sur la terre comme des serviteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Qui creuse une fosse y tombe; et qui renverse une clôture, un serpent le mord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Qui remue des pierres en sera meurtri; qui fend du bois se met en danger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Si le fer est émoussé, et que [celui qui l’emploie] n’en aiguise pas le tranchant, il aura des efforts à faire; mais la sagesse est profitable pour amener le succès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Si le serpent mord parce qu’il n’y a pas de charme, celui qui a une langue ne vaut pas mieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Les paroles de la bouche du sage sont pleines de grâce, mais les lèvres d’un sot l’engloutissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Le commencement des paroles de sa bouche est folie, et la fin de son discours est un mauvais égarement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Et l’insensé multiplie les paroles: l’homme ne sait pas ce qui arrivera; et ce qui sera après lui, qui le lui déclarera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Le travail des sots les lasse, parce qu’ils ne savent pas aller à la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Malheur à toi, terre qui as pour roi un jeune garçon, et dont les princes mangent dès le matin!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Bienheureuse toi, terre qui as pour roi le fils des nobles, et dont les princes mangent au temps convenable, pour [réparer] leurs forces, et non pour le [plaisir de] boire!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'À cause de la paresse, la charpente s’affaisse; et à cause des mains lâches, la maison a des gouttières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'On fait un repas pour s’égayer, et le vin rend la vie joyeuse; mais l’argent répond à tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Ne maudis pas le roi, même dans ta pensée, et ne maudis pas le riche dans la chambre où tu couches, car l’oiseau des cieux en emporterait la voix, et ce qui a des ailes en divulguerait les paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Jette ton pain sur la face des eaux, car tu le trouveras après bien des jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Donne une portion à sept, et même à huit; car tu ne sais pas quel mal arrivera sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Si les nuées sont pleines, elles verseront la pluie sur la terre; et si un arbre tombe, vers le midi ou vers le nord, à l’endroit où l’arbre sera tombé, là il sera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Celui qui observe le vent ne sèmera pas; et celui qui regarde les nuées ne moissonnera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Comme tu ne sais point quel est le chemin de l’esprit, [ni] comment [se forment] les os dans le ventre de celle qui est enceinte, ainsi tu ne connais pas l’œuvre de Dieu qui fait tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Le matin, sème ta semence, et, le soir, ne laisse pas reposer ta main; car tu ne sais pas ce qui réussira, ceci ou cela, ou si tous les deux seront également bons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'La lumière est douce, et il est agréable pour les yeux de voir le soleil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'mais si un homme vit beaucoup d’années, [et] se réjouit en toutes, qu’il se souvienne aussi des jours de ténèbres, car ils sont en grand nombre: tout ce qui arrive est vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Réjouis-toi, jeune homme, dans ta jeunesse, et que ton cœur te rende heureux aux jours de ton adolescence, et marche dans les voies de ton cœur et selon les regards de tes yeux; mais sache que, pour toutes ces choses, Dieu t’amènera en jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Ôte de ton cœur le chagrin, et fais passer le mal loin de ta chair; car le jeune âge et l’aurore sont vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Et souviens-toi de ton Créateur dans les jours de ta jeunesse, avant que soient venus les jours mauvais, et avant qu’arrivent les années dont tu diras: Je n’y prends point de plaisir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'avant que s’obscurcissent le soleil, et la lumière, et la lune, et les étoiles, et que les nuages reviennent après la pluie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'au jour où tremblent les gardiens de la maison, et où se courbent les hommes forts, et où chôment celles qui moulent, parce qu’elles sont en petit nombre, et où ceux qui regardent par les fenêtres sont obscurcis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'et où les deux battants de la porte se ferment sur la rue; quand baisse le bruit de la meule, et qu’on se lève à la voix de l’oiseau, et que toutes les filles du chant faiblissent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'quand aussi on craint ce qui est haut, et qu’on a peur sur le chemin, et quand l’amandier fleurit, et que la sauterelle devient pesante, et que la câpre est sans effet; (car l’homme s’en va dans sa demeure des siècles, et ceux qui mènent deuil parcourent les rues;)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, '– avant que le câble d’argent se détache, que le vase d’or se rompe, que le seau se brise à la source, et que la roue se casse à la citerne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'et que la poussière retourne à la terre, comme elle y avait été, et que l’esprit retourne à Dieu qui l’a donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Vanité des vanités, dit le prédicateur; tout est vanité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Et de plus, parce que le prédicateur était sage, il a encore enseigné la connaissance au peuple; et il a pesé et sondé, [et] mis en ordre beaucoup de proverbes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Le prédicateur s’est étudié à trouver des paroles agréables; et ce qui a été écrit est droit, des paroles de vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Les paroles des sages sont comme des aiguillons, et les recueils, comme des clous enfoncés: ils sont donnés par un seul pasteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Et de plus, mon fils, laisse-toi instruire par eux: à faire beaucoup de livres, il n’y a point de fin, et beaucoup d’étude lasse la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Écoutons la fin de tout ce qui a été dit: Crains Dieu, et garde ses commandements; car c’est là le tout de l’homme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'car Dieu amènera toute œuvre en jugement, avec tout ce qui est caché, soit bien, soit mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Le cantique des cantiques, qui est de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Qu’il m’embrasse des baisers de sa bouche! car tes amours sont meilleures que le vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Tes parfums sont d’agréable odeur; ton nom est un parfum répandu; c’est pourquoi les jeunes filles t’aiment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Tire-moi: nous courrons après toi. – Le roi m’a amenée dans ses chambres. – Nous nous égaierons, et nous nous réjouirons en toi; nous nous souviendrons de tes amours plus que du vin. Elles t’aiment avec droiture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Je suis noire, mais je suis agréable, filles de Jérusalem! comme les tentes de Kédar, comme les tentures de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Ne me regardez pas, parce que je suis noire, parce que le soleil m’a regardée: les fils de ma mère se sont irrités contre moi, ils m’ont mise à garder les vignes; ma vigne qui est à moi, je ne l’ai point gardée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Dis-moi, toi qu’aime mon âme, où tu pais [ton troupeau], où tu le fais reposer à midi; car pourquoi serais-je comme une femme voilée auprès des troupeaux de tes compagnons?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Si tu ne le sais pas, ô la plus belle parmi les femmes! sors sur les traces du troupeau, et pais tes chevreaux près des habitations des bergers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Je te compare, mon amie, à une jument aux chars du Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Tes joues sont agréables avec des rangées de joyaux; ton cou, avec des colliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Nous te ferons des chaînes d’or avec des paillettes d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Pendant que le roi est à table, mon nard exhale son odeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Mon bien-aimé est pour moi un bouquet de myrrhe; il passera la nuit entre mes seins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Mon bien-aimé est pour moi une grappe de henné dans les vignes d’En-Guédi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Voici, tu es belle, mon amie; voici, tu es belle! Tes yeux sont des colombes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Voici, tu es beau, mon bien-aimé; oui, tu es agréable! oui, notre lit est verdoyant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Les solives de nos maisons sont des cèdres; nos lambris des cyprès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Je suis le narcisse de Saron, le lis des vallées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Comme le lis entre les épines, telle est mon amie entre les filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Comme le pommier entre les arbres de la forêt, tel est mon bien-aimé entre les fils; j’ai pris plaisir à son ombre, et je m’y suis assise; et son fruit est doux à mon palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Il m’a fait entrer dans la maison du vin; et sa bannière sur moi, c’est l’amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Soutenez-moi avec des gâteaux de raisins, ranimez-moi avec des pommes; car je suis malade d’amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Sa main gauche est sous ma tête, et sa droite m’embrasse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Je vous adjure, filles de Jérusalem, par les gazelles ou par les biches des champs, n’éveillez pas, ne réveillez pas [mon] amour, jusqu’à ce qu’elle le veuille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, '*La voix de mon bien-aimé! le voici qui vient, sautant sur les montagnes, bondissant sur les collines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Mon bien-aimé est semblable à la gazelle, ou au faon des biches. Le voici, il se tient derrière notre mur, il regarde par les fenêtres, il regarde à travers les treillis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Mon bien-aimé m’a parlé, et m’a dit: Lève-toi, mon amie, ma belle, et viens!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Car voici, l’hiver est passé, la pluie a cessé, elle s’en est allée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'les fleurs paraissent sur la terre, la saison des chants est arrivée, et la voix de la tourterelle s’entend dans notre pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'le figuier embaume ses figues d’hiver, et les vignes en fleur exhalent leur parfum. Lève-toi, mon amie, ma belle, et viens!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Ma colombe, [qui te tiens] dans les fentes du rocher, dans les cachettes des lieux escarpés, montre-moi ton visage, fais-moi entendre ta voix; car ta voix est douce, et ton visage est agréable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, '– Prenez-nous les renards, les petits renards qui ravagent les vignes, car nos vignes sont en fleur. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Mon bien-aimé est à moi, et je suis à lui, qui paît parmi les lis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'jusqu’à ce que l’aube se lève et que les ombres fuient. – Tourne-toi; sois semblable, mon bien-aimé, à la gazelle ou au faon des biches sur les montagnes de Béther.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Sur mon lit, durant les nuits, j’ai cherché celui qu’aime mon âme; je l’ai cherché, mais je ne l’ai pas trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, '– Je me lèverai maintenant, et je ferai le tour de la ville dans les rues et dans les places; je chercherai celui qu’aime mon âme. – Je l’ai cherché, mais je ne l’ai pas trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Les gardes qui font la ronde par la ville m’ont trouvée. Avez-vous vu celui que mon âme aime?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'À peine avais-je passé plus loin, que j’ai trouvé celui qu’aime mon âme; je l’ai saisi, et je ne l’ai pas lâché que je ne l’aie amené dans la maison de ma mère, et dans la chambre de celle qui m’a conçue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Je vous adjure, filles de Jérusalem, par les gazelles ou par les biches des champs, n’éveillez pas, ne réveillez pas [mon] amour, jusqu’à ce qu’elle le veuille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, '*Qui est celle-ci qui monte du désert, comme des colonnes de fumée, parfumée de myrrhe et d’encens, [et] de toutes sortes de poudres des marchands?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, '– Voici son lit, celui de Salomon; 60 hommes forts l’entourent, d’entre les hommes forts d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'tous tiennent l’épée [et] sont exercés à la guerre, ayant chacun son épée sur sa cuisse à cause des frayeurs de la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Le roi Salomon s’est fait un palanquin de bois du Liban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Il a fait ses colonnes d’argent, son dossier d’or, son siège de pourpre, son intérieur pavé d’amour par les filles de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Sortez, filles de Sion, et voyez le roi Salomon, avec la couronne dont sa mère l’a couronné au jour de ses fiançailles, et au jour de la joie de son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Voici, tu es belle, mon amie; voici, tu es belle! Tes yeux sont des colombes derrière ton voile; tes cheveux sont comme un troupeau de chèvres sur les pentes de la montagne de Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Tes dents sont comme un troupeau de [brebis] tondues, qui montent du lavoir, qui toutes ont des jumeaux, et pas une d’elles n’est stérile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Tes lèvres sont comme un fil écarlate, et ta bouche est agréable; ta joue est comme un quartier de grenade derrière ton voile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Ton cou est comme la tour de David, bâtie pour y suspendre des armures; mille boucliers y sont suspendus, tous les pavois des vaillants hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Tes deux seins sont comme deux faons jumeaux d’une gazelle, qui paissent parmi les lis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Jusqu’à ce que l’aube se lève, et que les ombres fuient, j’irai à la montagne de la myrrhe et à la colline de l’encens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Tu es toute belle, mon amie, et en toi il n’y a point de défaut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, '[Viens] avec moi du Liban, [ma] fiancée, viens du Liban avec moi; regarde du sommet de l’Amana, du sommet du Senir et de l’Hermon, des tanières des lions, des montagnes des léopards.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Tu m’as ravi le cœur, ma sœur, [ma] fiancée; tu m’as ravi le cœur par l’un de tes yeux, par l’un des colliers de ton cou.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Que de charme ont tes amours, ma sœur, [ma] fiancée! Que tes amours sont meilleures que le vin, et l’odeur de tes parfums plus que tous les aromates!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Tes lèvres, [ma] fiancée, distillent le miel; sous ta langue il y a du miel et du lait, et l’odeur de tes vêtements est comme l’odeur du Liban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, '[Tu es] un jardin clos, ma sœur, [ma] fiancée, une source fermée, une fontaine scellée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Tes plants sont un paradis de grenadiers et de fruits exquis, de henné et de nard,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'de nard et de safran, de roseau odorant et de cinnamome, avec tous les arbres à encens; de myrrhe et d’aloès, avec tous les principaux aromates;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'une fontaine dans les jardins, un puits d’eaux vives, qui coulent du Liban!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Réveille-toi, nord, et viens, midi; souffle dans mon jardin, pour que ses aromates s’exhalent! Que mon bien-aimé vienne dans son jardin, et qu’il mange ses fruits exquis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Je suis venu dans mon jardin, ma sœur, [ma] fiancée! J’ai cueilli ma myrrhe avec mes aromates, j’ai mangé mon rayon de miel avec mon miel, j’ai bu mon vin avec mon lait. Mangez, amis; buvez, buvez abondamment, bien-aimés!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, '*Je dormais, mais mon cœur était réveillé. C’est la voix de mon bien-aimé qui heurte: Ouvre-moi, ma sœur, mon amie, ma colombe, ma parfaite! Car ma tête est pleine de rosée, mes boucles, des gouttes de la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, '– Je me suis dépouillée de ma tunique, comment la revêtirais-je? J’ai lavé mes pieds, comment les salirais-je? –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Mon bien-aimé a avancé sa main par le guichet, et mes entrailles se sont émues à cause de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Je me suis levée pour ouvrir à mon bien-aimé, et de mes mains a dégoutté la myrrhe, et de mes doigts, la myrrhe limpide, sur les poignées du verrou.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'J’ai ouvert à mon bien-aimé, mais mon bien-aimé s’était retiré, il avait passé plus loin; mon âme s’en était allée pendant qu’il parlait. Je le cherchai, mais je ne le trouvai pas; je l’appelai, mais il ne me répondit pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Les gardes qui font la ronde par la ville me trouvèrent; ils me frappèrent, ils m’ont blessée; les gardes des murailles m’ont ôté mon voile de dessus moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Je vous adjure, filles de Jérusalem, si vous trouvez mon bien-aimé, que lui direz-vous? Que je suis malade d’amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Ton bien-aimé qu’est-il de plus qu’un autre bien-aimé, ô la plus belle parmi les femmes? Ton bien-aimé qu’est-il de plus qu’un autre bien-aimé, que tu nous adjures ainsi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Mon bien-aimé est blanc et vermeil, un porte-bannière entre dix mille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Sa tête est un or très fin; ses boucles sont flottantes, noires comme un corbeau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'ses yeux, comme des colombes près des ruisseaux d’eau, baignés dans le lait, bien enchâssés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'ses joues, comme des parterres d’aromates, des corbeilles de fleurs parfumées; ses lèvres, des lis distillant une myrrhe limpide;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'ses mains, des rondelles d’or, où sont enchâssées des chrysolithes; son ventre, un ivoire poli, couvert de saphirs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'ses jambes, des colonnes de marbre blanc, reposant sur des socles d’or fin; son port, comme le Liban, distingué comme les cèdres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'son palais est plein de douceur, et toute sa personne est désirable. Tel est mon bien-aimé, tel est mon ami, filles de Jérusalem!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Où est allé ton bien-aimé, ô la plus belle parmi les femmes? De quel côté ton bien-aimé s’est-il tourné? et nous le chercherons avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Mon bien-aimé est descendu dans son jardin, aux parterres des aromates, pour paître dans les jardins et pour cueillir des lis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Je suis à mon bien-aimé, et mon bien-aimé est à moi; il paît parmi les lis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Tu es belle, mon amie, comme Thirtsa, agréable comme Jérusalem, redoutable comme des troupes sous leurs bannières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Détourne de moi tes yeux, car ils me troublent. Tes cheveux sont comme un troupeau de chèvres sur les pentes de Galaad;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'tes dents, comme un troupeau de brebis qui montent du lavoir, qui toutes ont des jumeaux, et pas une d’elles n’est stérile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'ta joue est comme un quartier de grenade derrière ton voile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Il y a 60 reines, et 80 concubines, et des jeunes filles sans nombre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'ma colombe, ma parfaite, est unique; elle est l’unique de sa mère, la choisie de celle qui l’a enfantée. Les filles l’ont vue, et l’ont dite bienheureuse; les reines aussi et les concubines, et elles l’ont louée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Qui est celle-ci qui apparaît comme l’aurore, belle comme la lune, pure comme le soleil, redoutable comme des troupes sous leurs bannières?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Je suis descendu au jardin des noisettes, pour voir la verdure de la vallée, pour voir si la vigne bourgeonne, si les grenadiers s’épanouissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Sans que je m’en aperçoive, mon âme m’a transporté sur les chars de mon peuple de franche volonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, '*Reviens, reviens, Sulamithe! reviens, reviens, et que nous te voyions. – Que verriez-vous dans la Sulamithe? – Comme la danse de deux bandes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Que tes pieds sont beaux dans ta chaussure, fille de prince! Les contours de tes hanches sont comme des joyaux, ouvrage des mains d’un artiste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Ton nombril est une coupe arrondie, où le vin aromatique ne manque pas; ton ventre, un tas de froment, entouré de lis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Tes deux seins sont comme deux faons jumeaux d’une gazelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Ton cou est comme une tour d’ivoire; tes yeux sont comme les étangs [qui sont] à Hesbon, vers la porte de Bath-Rabbim; ton nez est comme la tour du Liban, qui regarde vers Damas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'ta tête, sur toi, comme le Carmel, et les cheveux de ta tête comme la pourpre. Un roi est enchaîné par [tes] boucles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Que tu es belle, et que tu es agréable, mon amour, dans tes délices!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Ta taille ressemble à un palmier, et tes seins à des grappes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'J’ai dit: Je monterai sur le palmier, je saisirai ses rameaux; et que tes seins soient comme les grappes de la vigne, et le parfum de ton nez comme des pommes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'et ton palais comme le bon vin,... Qui coule aisément pour mon bien-aimé, [et] qui glisse sur les lèvres de ceux qui s’endorment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Je suis à mon bien-aimé, et son désir se porte vers moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, '– Viens, mon bien-aimé, sortons aux champs, passons la nuit dans les villages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Nous nous lèverons dès le matin, [pour aller] aux vignes; nous verrons si la vigne bourgeonne, si la fleur s’ouvre, si les grenadiers s’épanouissent: là je te donnerai mes amours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 14, 'Les mandragores donnent [leur] parfum; et à nos portes il y a tous les fruits exquis, nouveaux et anciens: mon bien-aimé, je les ai gardés pour toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Oh! que tu aies été pour moi comme un frère qui ait sucé les mamelles de ma mère! Si je te trouvais dehors, je t’embrasserais, sans qu’on m’en méprise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Je t’amènerais, je t’introduirais dans la maison de ma mère: tu m’instruirais; je te ferais boire du vin aromatisé, du jus de mes grenades.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Sa main gauche serait sous ma tête, et sa droite m’embrasserait!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Je vous adjure, filles de Jérusalem, pourquoi éveilleriez-vous, et pourquoi réveilleriez-vous [mon] amour, avant qu’elle le veuille!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, '*Qui est celle-ci qui monte du désert, s’appuyant sur son bien-aimé? – Je t’ai réveillée sous le pommier: là ta mère t’a enfantée dans les douleurs, là celle qui t’a enfantée a été en travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Mets-moi comme un cachet sur ton cœur, comme un cachet sur ton bras; car l’amour est fort comme la mort, la jalousie, cruelle comme le shéol; ses ardeurs sont des ardeurs de feu, une flamme de Jah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Beaucoup d’eaux ne peuvent éteindre l’amour, et des fleuves ne le submergent pas; si un homme donnait tous les biens de sa maison pour l’amour, on l’aurait en un profond mépris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Nous avons une petite sœur, et elle n’a pas encore de seins. Que ferons-nous pour notre sœur, au jour où l’on parlera d’elle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, '– Si elle est une muraille, nous bâtirons sur elle une demeure d’argent; et si elle est une porte, nous la fermerons avec une planche de cèdre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Je suis une muraille, et mes seins sont des tours; je fus alors à ses yeux comme celle qui a trouvé la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, '– Salomon avait une vigne à Baal-Hamon: il remit la vigne à des gardiens; chacun devait apporter pour son fruit 1 000 [pièces] d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Ma vigne, qui est à moi, est devant moi. À toi, Salomon, les 1 000 [pièces]; et 200 pour ceux qui en gardent le fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Habitante des jardins, les compagnons sont attentifs à ta voix! Fais que je l’entende!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Fuis, mon bien-aimé, et sois semblable à une gazelle ou au faon des biches, sur les montagnes des aromates.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'La vision d’Ésaïe, fils d’Amots, qu’il a vue touchant Juda et Jérusalem, aux jours d’Ozias, de Jotham, d’Achaz, et d’Ézéchias, rois de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Écoutez, cieux, et prête l’oreille, terre! car l’ Éternel a parlé: J’ai nourri et élevé des fils, et ils se sont rebellés contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Le bœuf connaît son possesseur, et l’âne la crèche de son maître; Israël ne connaît pas, mon peuple n’a point d’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ha! nation pécheresse, peuple chargé d’iniquité, race de gens qui font le mal, fils qui se corrompent! Ils ont abandonné l’ Éternel, ils ont méprisé le Saint d’Israël; ils se sont retirés en arrière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Pourquoi seriez-vous encore frappés? vous ajouterez des révoltes! Toute la tête est malade et tout le cœur défaille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Depuis la plante du pied jusqu’à la tête, il n’y a rien en lui qui soit sain: [tout est] blessure, et meurtrissure, et plaies vives; elles n’ont pas été pansées, ni bandées, ni adoucies avec l’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Votre pays est dévasté, vos villes sont brûlées par le feu; votre terre, des étrangers la dévorent devant vos yeux, et elle est dévastée, comme ruinée par des étrangers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Et la fille de Sion est laissée comme une hutte dans une vigne, comme une cabane dans un champ de concombres, comme une ville assiégée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Si l’ Éternel des armées ne nous avait laissé un bien petit résidu, nous aurions été comme Sodome, nous ressemblerions à Gomorrhe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Écoutez la parole de l’ Éternel, chefs de Sodome; prêtez l’oreille à la loi de notre Dieu, peuple de Gomorrhe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'À quoi me sert la multitude de vos sacrifices? dit l’ Éternel. Je suis rassasié d’holocaustes de béliers, et de la graisse de bêtes grasses; et je ne prends pas plaisir au sang des taureaux, et des agneaux, et des boucs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Quand vous venez pour paraître devant ma face, qui a demandé cela de vos mains, que vous fouliez mes parvis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Ne continuez pas d’apporter de vaines offrandes: l’encens m’est une abomination, – la nouvelle lune et le sabbat, la convocation des assemblées; je ne puis supporter l’iniquité et la fête solennelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Vos nouvelles lunes et vos assemblées, mon âme les hait; elles me sont à charge, je suis las de les supporter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Et quand vous étendrez vos mains, je cacherai de vous mes yeux; quand même vous multiplierez la prière, je n’écouterai pas. Vos mains sont pleines de sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Lavez-vous, purifiez-vous; ôtez de devant mes yeux le mal de vos actions; cessez de mal faire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'apprenez à bien faire; recherchez le juste jugement, rendez heureux l’opprimé; faites droit à l’orphelin, plaidez la cause de la veuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Venez, et plaidons ensemble, dit l’ Éternel: Si vos péchés sont comme le cramoisi, ils deviendront blancs comme la neige; s’ils sont rouges comme l’écarlate, ils seront comme la laine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Si vous êtes de bonne volonté et que vous écoutiez, vous mangerez des biens du pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'mais si vous refusez, et que vous soyez rebelles, vous serez consumés par l’épée; car la bouche de l’ Éternel a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Comment la ville fidèle est-elle devenue une prostituée? Elle était pleine de droiture; la justice habitait en elle, et maintenant, des meurtriers!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Ton argent est devenu des scories, ton vin est mêlé avec de l’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'tes princes sont rebelles et compagnons de voleurs; chacun aime les présents et court après les récompenses; ils ne font pas droit à l’orphelin, et la cause de la veuve n’a pas accès auprès d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'C’est pourquoi le Seigneur, l’ Éternel des armées, le Puissant d’Israël, dit: Ha! je me satisferai en mes adversaires, et je me vengerai de mes ennemis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'et je tournerai ma main sur toi, et je te purifierai de tes scories comme avec de la potasse, et j’ôterai tout ton étain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'et je rétablirai tes juges comme au commencement, et tes conseillers comme dans les premiers temps. Après cela, tu seras appelée ville de justice, cité fidèle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Sion sera rachetée par le jugement, et les siens qui reviennent, par la justice;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'mais la ruine des transgresseurs et des pécheurs arrivera en une fois, et ceux qui abandonnent l’ Éternel seront consumés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Car ils auront honte des térébinthes auxquels vous avez pris plaisir, et vous rougirez des jardins que vous aurez choisis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'car vous serez comme un térébinthe dont la feuille se flétrit, et comme un jardin qui n’a pas d’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Et le fort sera de l’étoupe, et son œuvre une étincelle, et tous deux brûleront ensemble, et il n’y a personne qui éteigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, '*La parole qu’Ésaïe, fils d’Amots, vit, touchant Juda et Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Et il arrivera, à la fin des jours, que la montagne de la maison de l’ Éternel sera établie sur le sommet des montagnes, et sera élevée au-dessus des collines; et toutes les nations y afflueront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'et beaucoup de peuples iront, et diront: Venez, et montons à la montagne de l’ Éternel, à la maison du Dieu de Jacob, et il nous instruira de ses voies, et nous marcherons dans ses sentiers. Car de Sion sortira la loi, et de Jérusalem, la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Et il jugera au milieu des nations, et prononcera le droit à beaucoup de peuples; et de leurs épées ils forgeront des socs, et de leurs lances, des serpes: une nation ne lèvera pas l’épée contre une [autre] nation, et on n’apprendra plus la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Venez, maison de Jacob, et marchons dans la lumière de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Car tu as abandonné ton peuple, la maison de Jacob, parce qu’ils sont remplis de ce qui vient de l’orient, et sont des pronostiqueurs, comme les Philistins, et s’allient avec les enfants des étrangers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Et leur pays est rempli d’argent et d’or, et il n’y a pas de fin à leurs trésors; et leur pays est rempli de chevaux, et il n’y a pas de fin à leurs chars;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'et leur pays est rempli d’idoles: ils se prosternent devant l’ouvrage de leurs mains, devant ce que leurs doigts ont fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Et l’homme du peuple se courbera, et le grand sera abaissé: et ne leur pardonne pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Entre dans le rocher, et cache-toi dans la poussière, de devant la terreur de l’ Éternel et de devant la magnificence de sa majesté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Les yeux hautains de l’homme seront abaissés, et la hauteur des hommes sera humiliée, et l’ Éternel seul sera haut élevé en ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Car il y a un jour de l’ Éternel des armées contre tout ce qui s’exalte et s’élève, et contre tout ce qui est haut, et ils seront abaissés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'et contre tous les cèdres du Liban, hauts et élevés, et contre tous les chênes de Basan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'et contre toutes les hautes montagnes, et contre toutes les collines élevées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'et contre toute haute tour, et contre toute muraille forte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'et contre tous les navires de Tarsis, et contre tous les objets d’art agréables:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'et la hauteur de l’homme sera humiliée, et l’élévation des hommes sera abaissée, et l’ Éternel seul sera haut élevé en ce jour-là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'et les idoles disparaîtront entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Et on entrera dans les cavernes des rochers, et dans les trous de la terre, de devant la terreur de l’ Éternel, et de devant la magnificence de sa majesté, quand il se lèvera pour frapper d’épouvante la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'En ce jour-là, l’homme jettera ses idoles d’argent et ses idoles d’or, qu’il s’était faites pour se prosterner [devant elles], aux rats et aux chauves-souris,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'pour entrer dans les fentes des rochers et dans les creux des escarpements, de devant la terreur de l’ Éternel et de devant la magnificence de sa majesté, quand il se lèvera pour frapper d’épouvante la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Finissez-en avec l’homme, dont le souffle est dans ses narines, car quel cas doit-on faire de lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Car voici, le Seigneur, l’ Éternel des armées, ôte de Jérusalem et de Juda le soutien et l’appui, tout soutien de pain et tout soutien d’eau,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'l’homme fort et l’homme de guerre, le juge et le prophète, le devin et l’ancien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'le chef de cinquantaine, et l’homme considéré, et le conseiller, et l’habile ouvrier, et celui qui s’entend aux enchantements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Et je leur donnerai des jeunes gens pour être leurs princes, et de petits enfants domineront sur eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'et le peuple sera opprimé, l’homme par l’homme, et chacun par son voisin; le jeune garçon usera d’insolence contre le vieillard, et l’homme de néant contre l’homme honorable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Alors, si un homme saisit son frère, dans la maison de son père, [disant]: Tu as un manteau, tu seras notre chef, et cette ruine sera sous ta main,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'il jurera en ce jour-là, disant: Je ne puis être un médecin, et dans ma maison il n’y a pas de pain et il n’y a pas de manteau; vous ne me ferez pas chef du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Car Jérusalem bronche, et Juda tombe; parce que leur langue et leurs actions sont contre l’ Éternel, pour braver les yeux de sa gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'L’aspect de leur visage témoigne contre eux, et ils annoncent leur péché comme Sodome; ils ne le cachent pas. Malheur à leur âme! car ils ont fait venir le mal sur eux-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Dites au juste que le bien [lui arrivera], car ils mangeront le fruit de leurs actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Malheur au méchant! [il lui arrivera] du mal, car l’œuvre de ses mains lui sera rendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Quant à mon peuple, des enfants l’oppriment, et des femmes le gouvernent. Mon peuple! ceux qui te conduisent te fourvoient, et détruisent le chemin de tes sentiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'L’ Éternel se tient là pour plaider, et il est debout pour juger les peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'L’ Éternel entrera en jugement avec les anciens de son peuple et avec ses princes, [disant]: Et vous, vous avez brouté la vigne; la dépouille du pauvre est dans vos maisons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Qu’avez-vous à faire de fouler mon peuple, et de broyer la face des pauvres? dit le Seigneur, l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Et l’ Éternel dit: Parce que les filles de Sion sont hautaines, et qu’elles marchent le cou tendu et les regards pleins de convoitise, et qu’elles marchent allant à petits pas, faisant résonner leurs pieds,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'le Seigneur rendra chauve le sommet de la tête des filles de Sion, et l’ Éternel exposera leur nudité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'En ce jour-là, le Seigneur ôtera l’ornement des anneaux de pieds, et les petits soleils, et les petites lunes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'les pendeloques de perles, et les bracelets, et les voiles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'les diadèmes, et les chaînettes des pieds, et les ceintures, et les boîtes de senteur, et les amulettes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'les bagues, et les anneaux de nez;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'les vêtements de fête, et les tuniques, et les manteaux, et les bourses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'et les miroirs, et les chemises, et les turbans, et les voiles de gaze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Et il arrivera qu’au lieu de parfum il y aura pourriture; et au lieu de ceinture, une corde; et au lieu de cheveux artistement tressés, une tête chauve; et au lieu d’une robe d’apparat, un sarrau de toile à sac; flétrissure, au lieu de beauté. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Tes hommes tomberont par l’épée, et tes hommes forts, dans la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Et ses portes se lamenteront et mèneront deuil; et, désolée, elle s’assiéra sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Et sept femmes saisiront un seul homme en ce jour-là, disant: Nous mangerons notre propre pain, et nous nous vêtirons de nos propres vêtements, seulement que nous soyons appelées de ton nom; ôte notre opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'En ce jour-là, il y aura un germe de l’ Éternel pour splendeur et pour gloire, et le fruit de la terre, pour magnificence et pour ornement, pour les réchappés d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'et le résidu en Sion, et le reste dans Jérusalem, sera appelé saint: quiconque sera écrit parmi les vivants dans Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'quand le Seigneur aura nettoyé la saleté des filles de Sion, et aura lavé le sang de Jérusalem du milieu d’elle, par l’esprit de jugement et par l’esprit de consomption.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Et l’ Éternel créera sur chaque demeure de la montagne de Sion, et sur ses assemblées, une nuée et une fumée, de jour; et la splendeur d’une flamme de feu, la nuit; car sur toute la gloire il y aura une couverture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Et il y aura un tabernacle pour ombrage, de jour, contre la chaleur, et pour abri et pour refuge contre l’orage et contre la pluie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, '*Je chanterai à mon bien-aimé un cantique de mon bien-aimé, sur sa vigne: Mon bien-aimé avait une vigne sur un coteau fertile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Et il la fossoya et en ôta les pierres, et la planta de ceps exquis; et il bâtit une tour au milieu d’elle, et y tailla aussi un pressoir; et il s’attendait à ce qu’elle produirait de bons raisins, et elle produisit des raisins sauvages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, '– Et maintenant, habitants de Jérusalem et hommes de Juda, jugez, je vous prie, entre moi et ma vigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Qu’y avait-il encore à faire pour ma vigne, que je n’aie pas fait pour elle? Pourquoi, quand j’espérais qu’elle produirait de bons raisins, a-t-elle produit des raisins sauvages?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Et maintenant je vous apprendrai ce que je ferai à ma vigne: j’ôterai sa haie, et elle sera broutée; j’abattrai sa clôture, et elle sera foulée aux pieds;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'et je la réduirai en désert; elle ne sera pas taillée, et elle ne sera pas sarclée, et les ronces et les épines monteront; et je commanderai aux nuées qu’elles ne laissent pas tomber de pluie sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Car la vigne de l’ Éternel des armées est la maison d’Israël, et les hommes de Juda sont la plante de ses délices. Et il s’attendait au juste jugement, et voici l’effusion de sang, – à la justice, et voici un cri!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Malheur à ceux qui ajoutent maison à maison, qui joignent champ à champ, jusqu’à ce qu’il n’y ait plus de place et que vous habitiez seuls au milieu du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'À mes oreilles, l’ Éternel des armées [a dit]: Si beaucoup de maisons ne sont désolées, [si] de grandes et belles [maisons ne sont] vides d’habitants!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Car dix arpents de vigne ne produiront qu’un bath, et un khomer de semence produira un épha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Malheur à ceux qui, se levant de bonne heure, courent après la boisson, [et] qui, s’attardant jusqu’à la tombée de la nuit, sont enflammés par le vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Et la harpe et le luth, le tambourin et la flûte, et le vin, [abondent dans] leurs festins; et ils ne regardent pas l’œuvre de l’ Éternel, et ils ne voient pas l’opération de ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'C’est pourquoi mon peuple est allé en captivité, parce qu’il n’a pas de connaissance; et ses grands meurent de faim, et sa multitude est asséchée de soif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'C’est pourquoi le shéol élargit son désir et ouvre sa bouche sans mesure; et la magnificence de Jérusalem y descendra, et sa multitude, et son tumulte, et sa joie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'et l’homme du peuple se courbera, et le grand sera abaissé; et les yeux des hautains seront abaissés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'et l’ Éternel des armées sera élevé en jugement, et le ✶Dieu saint sera sanctifié en justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Et les agneaux paîtront comme dans leur pâturage, et les étrangers dévoreront les lieux désolés des [hommes] gras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Malheur à ceux qui tirent l’iniquité avec des cordes de vanité, et le péché comme avec des cordes de chariot,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'qui disent: Qu’il se hâte, qu’il accélère son œuvre, afin que nous la voyions; et que le conseil du Saint d’Israël s’approche, et vienne, et que nous le connaissions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Malheur à ceux qui appellent le mal bien, et le bien mal, qui mettent les ténèbres pour la lumière, et la lumière pour les ténèbres, qui mettent l’amer pour le doux, et le doux pour l’amer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Malheur à ceux qui sont sages à leurs propres yeux, et intelligents à leur propre estime!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Malheur à ceux qui sont forts pour boire du vin, et hommes vaillants pour mêler les boissons fortes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'qui justifient le méchant pour un présent, et qui ôtent aux justes leur justice!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'C’est pourquoi, comme une langue de feu dévore le chaume, et comme l’herbe sèche s’affaisse dans la flamme, leur racine sera comme la pourriture, et leur fleur montera comme la poussière; car ils ont méprisé la loi de l’ Éternel des armées, et ont rejeté avec dédain la parole du Saint d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'C’est pourquoi la colère de l’ Éternel s’est embrasée contre son peuple; et il a étendu sa main sur lui, et l’a frappé; et les montagnes ont été ébranlées; et leurs cadavres sont devenus comme des ordures au milieu des rues. Pour tout cela, sa colère ne s’est pas détournée, et sa main est encore étendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Et il élèvera un étendard devant les nations lointaines: et il en sifflera une des bouts de la terre; et voici, elle viendra, rapide [et] légère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'En elle, nul qui soit las ou qui bronche; nul ne sommeille, nul ne dort; nul n’a la ceinture de ses reins déliée, ou la courroie de sa chaussure arrachée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Ses flèches sont aiguës, et tous ses arcs tendus; les sabots de ses chevaux sont comme le caillou, et ses roues comme le tourbillon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Son rugissement est comme celui d’une lionne; elle rugit comme les jeunes lions; elle gronde, et saisit la proie et l’emporte, et il n’y a personne qui délivre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'et elle mugira sur elle, en ce jour-là, comme mugit la mer; et on regardera sur la terre, et voici les ténèbres [et] la détresse: la lumière est obscurcie dans son ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, '*L’année de la mort du roi Ozias, je vis le Seigneur assis sur un trône haut et élevé, et les pans de sa robe remplissaient le temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Des séraphins se tenaient au-dessus de lui; ils avaient chacun six ailes: de deux ils se couvraient la face, et de deux ils se couvraient les pieds, et de deux ils volaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Et l’un criait à l’autre, et disait: Saint, saint, saint, est l’ Éternel des armées; toute la terre est pleine de sa gloire!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Et les fondements des seuils étaient ébranlés à la voix de celui qui criait, et la maison était remplie de fumée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Et je dis: Malheur à moi! car je suis perdu; car moi, je suis un homme aux lèvres impures, et je demeure au milieu d’un peuple aux lèvres impures; car mes yeux ont vu le roi, l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Et l’un des séraphins vola vers moi; et il avait en sa main un charbon ardent qu’il avait pris de dessus l’autel avec des pincettes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'et il en toucha ma bouche, et dit: Voici, ceci a touché tes lèvres; et ton iniquité est ôtée, et propitiation est faite pour ton péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Et j’entendis la voix du Seigneur qui disait: Qui enverrai-je, et qui ira pour nous? Et je dis: Me voici, envoie-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, '– Et il dit: Va, et dis à ce peuple: En entendant vous entendrez et vous ne comprendrez pas, et en voyant vous verrez et vous ne connaîtrez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Engraisse le cœur de ce peuple, et rends ses oreilles pesantes, et bouche ses yeux, de peur qu’il ne voie des yeux, et n’entende de ses oreilles, et ne comprenne de son cœur, et ne se convertisse, et qu’il ne soit guéri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, '– Et je dis: Jusques à quand, Seigneur? Et il dit: Jusqu’à ce que les villes soient dévastées, de sorte qu’il n’y ait pas d’habitants, et les maisons, de sorte qu’il n’y ait pas d’hommes, et que le sol soit réduit en entière désolation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'et que l’ Éternel en ait éloigné les hommes, et que la solitude soit grande au milieu du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Mais il y aura encore là un dixième; et il reviendra et il sera brouté, comme le térébinthe et le chêne, dont le tronc [reste] quand ils sont abattus: la semence sainte en sera le tronc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, '*Et il arriva, dans les jours d’Achaz, fils de Jotham, fils d’Ozias, roi de Juda, que Retsin, roi de Syrie, et Pékakh, fils de Remalia, roi d’Israël, montèrent à Jérusalem pour lui faire la guerre; mais ils ne purent pas l’assiéger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Et on rapporta à la maison de David, disant: La Syrie est venue prêter appui à Éphraïm. Et son cœur fut agité, et le cœur de son peuple, comme les arbres de la forêt sont agités devant le vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Et l’ Éternel dit à Ésaïe: Sors à la rencontre d’Achaz, toi et Shear-Jashub, ton fils, au bout de l’aqueduc de l’étang supérieur, sur la route du champ du foulon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'et tu lui diras: Prends garde et sois tranquille; ne crains point, et que ton cœur ne défaille pas devant ces deux bouts de tisons fumants, devant l’ardeur de la colère de Retsin et de la Syrie, et du fils de Remalia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Parce que la Syrie a formé contre toi de mauvais desseins, Éphraïm [aussi] et le fils de Remalia, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Montons contre Juda, et jetons-y l’alarme, et faisons-y pour nous une brèche, et établissons pour roi au milieu d’elle le fils de Tabeël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'ainsi dit le Seigneur, l’ Éternel: Il ne s’accomplira pas et n’aura pas lieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'car le chef de la Syrie, c’est Damas, et le chef de Damas, c’est Retsin. Et encore 65 ans, et Éphraïm cessera d’être un peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'et le chef d’Éphraïm, c’est la Samarie, et le chef de la Samarie, c’est le fils de Remalia. Si vous ne croyez pas, vous ne subsisterez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Et l’ Éternel parla encore à Achaz, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Demande pour toi un signe de la part de l’ Éternel, ton Dieu; demande-le dans les lieux bas ou dans les hauteurs d’en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Et Achaz dit: Je ne [le] demanderai pas, et je ne tenterai pas l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Et il dit: Écoutez donc, maison de David: Est-ce peu de chose pour vous de lasser [la patience] des hommes, que vous lassiez aussi [la patience de] mon Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'C’est pourquoi le Seigneur, lui, vous donnera un signe: Voici, la vierge concevra et elle enfantera un fils, et appellera son nom Emmanuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Il mangera du caillé et du miel, pour savoir rejeter le mal et choisir le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Car avant que l’enfant sache rejeter le mal et choisir le bien, le pays des deux rois duquel tu as peur sera abandonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'L’ Éternel fera venir sur toi, et sur ton peuple et sur la maison de ton père, des jours qui ne sont pas venus depuis le jour où Éphraïm s’est retiré de Juda, – [savoir] le roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Et il arrivera, en ce jour-là, que l’ Éternel sifflera la mouche qui est au bout des fleuves d’Égypte, et l’abeille qui est dans le pays d’Assyrie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'et elles viendront et se poseront toutes dans les vallées désertes et dans les fentes des rochers, et sur toutes les broussailles, et sur tous les pâturages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'En ce jour-là, le Seigneur rasera avec un rasoir pris à louage au-delà du fleuve, avec le roi d’Assyrie, la tête et les poils des pieds, et il enlèvera aussi la barbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Et il arrivera, en ce jour-là, qu’un homme nourrira une jeune vache et deux brebis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'et il arrivera que, de l’abondance du lait qu’elles donneront, il mangera du caillé; car tous ceux qui seront de reste au milieu du pays mangeront du caillé et du miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Et il arrivera, en ce jour-là, que tout lieu où il y avait 1 000 ceps de 1 000 [pièces] d’argent, sera [abandonné] aux ronces et aux épines;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'on y viendra avec des flèches et avec l’arc, car tout le pays sera ronces et épines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Et toutes les montagnes qu’on cultivait avec la bêche, – on n’y viendra pas, par crainte des ronces et des épines; et elles seront un lieu pour y envoyer le bœuf, et pour que les brebis le foulent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Et l’ Éternel me dit: Prends-toi une grande plaque, et écris dessus avec un style d’homme: Maher-Shalal-Hash-Baz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Et je me pris de fidèles témoins pour témoigner, Urie, le sacrificateur, et Zacharie, fils de Jebérékia.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Et je m’approchai de la prophétesse, et elle conçut, et enfanta un fils; et l’ Éternel me dit: Appelle son nom: Maher-Shalal-Hash-Baz;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'car avant que l’enfant sache crier: Mon père, et, Ma mère, on emportera la puissance de Damas et le butin de Samarie devant le roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Et l’ Éternel me parla encore, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Parce que ce peuple rejette les eaux de Siloé qui vont doucement, et qu’il trouve son plaisir en Retsin et dans le fils de Remalia;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'à cause de cela, voici, le Seigneur fait monter sur eux les eaux du fleuve, fortes et grosses, le roi d’Assyrie et toute sa gloire; et il montera sur tout son lit, et s’en ira par-dessus tous ses bords;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'et il traversera Juda, il débordera et passera outre, il atteindra jusqu’au cou; et le déploiement de ses ailes remplira la largeur de ton pays, ô Emmanuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Associez-vous, peuples, et vous serez brisés; et prêtez l’oreille, vous tous qui habitez au loin sur la terre! Ceignez-vous, et vous serez brisés! Ceignez-vous, et vous serez brisés!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Prenez un conseil, et il n’aboutira à rien; dites la parole, et elle n’aura pas d’effet: car ✶Dieu est avec nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Car ainsi m’a dit l’ Éternel avec main forte, et il m’a averti de ne pas marcher dans le chemin de ce peuple, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Ne dites pas conjuration, de tout ce dont ce peuple dira conjuration, et ne craignez pas leur crainte, et ne soyez pas effrayés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'l’ Éternel des armées, lui, sanctifiez-le, et que lui soit votre crainte, et lui, votre frayeur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'et il sera pour sanctuaire, et pour pierre d’achoppement et rocher de trébuchement aux deux maisons d’Israël, pour piège et pour lacet aux habitants de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Et beaucoup d’entre eux trébucheront, et tomberont, et seront brisés, et enlacés, et pris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Lie le témoignage, scelle la loi parmi mes disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Et je m’attendrai à l’ Éternel qui cache sa face de la maison de Jacob, et je l’attendrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Voici, moi et les enfants que l’ Éternel m’a donnés, nous sommes pour signes et pour prodiges en Israël de la part de l’ Éternel des armées qui demeure en la montagne de Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Et s’ils vous disent: Enquérez-vous des évocateurs d’esprits et des diseurs de bonne aventure, qui murmurent et qui chuchotent,... un peuple ne s’enquiert-il pas de son Dieu? [ira-t-il] aux morts pour les vivants?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'À la loi et au témoignage! S’ils ne parlent pas selon cette parole, il n’y a pas d’aurore pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Et il passera là, affligé et ayant faim; et il arrivera que, lorsqu’il aura faim, il se dépitera, et maudira son roi et son Dieu; et il regardera en haut,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'et il fixera son regard sur la terre, et voici la détresse et les ténèbres, l’obscurité de l’angoisse! et il est repoussé dans d’épaisses ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 23, 'Toutefois l’obscurité ne sera pas selon que la détresse fut sur la terre, quand au commencement il pesa légèrement sur le pays de Zabulon et le pays de Nephthali, et plus tard s’appesantit [sur elle],... chemin de la mer, au-delà du Jourdain, Galilée des nations:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'le peuple qui marchait dans les ténèbres a vu une grande lumière; ceux qui habitaient dans le pays de l’ombre de la mort,... la lumière a resplendi sur eux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Tu as multiplié la nation, tu lui as accru la joie; ils se réjouissent devant toi, comme la joie à la moisson, comme on est transporté de joie quand on partage le butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Car tu as cassé le joug qui pesait sur elle, et la verge de son épaule, le bâton de son oppresseur, comme au jour de Madian.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Car toute chaussure de guerre qu’on chausse pour le tumulte, et le manteau roulé dans le sang, seront un embrasement, la pâture du feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Car un enfant nous est né, un fils nous a été donné, et le gouvernement sera sur son épaule; et on appellera son nom: Merveilleux, Conseiller, ✶Dieu fort, Père du siècle, Prince de paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'À l’accroissement de [son] empire, et à la paix, il n’y aura pas de fin, sur le trône de David et dans son royaume, pour l’établir et le soutenir en jugement et en justice, dès maintenant et à toujours. La jalousie de l’ Éternel des armées fera cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, '*Le Seigneur a envoyé une parole à Jacob, et elle tombe sur Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'et le peuple tout entier le saura, Éphraïm et celui qui habite la Samarie, qui disent avec orgueil et avec hauteur de cœur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Les briques sont tombées, nous bâtirons en pierres de taille; les sycomores ont été coupés, nous les remplacerons par des cèdres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Mais l’ Éternel suscitera les adversaires de Retsin contre lui, et armera ses ennemis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'les Syriens, à l’est, et les Philistins, à l’ouest; et ils dévoreront Israël à gueule ouverte. Pour tout cela, sa colère ne s’est pas détournée, et sa main est encore étendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Mais le peuple ne retourne pas à celui qui le frappe, et ne recherche pas l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Et l’ Éternel retranchera d’Israël la tête et la queue, la branche de palmier et le jonc, en un seul jour:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'l’ancien et l’homme considéré, lui, est la tête; et le prophète qui enseigne le mensonge, lui, est la queue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Car les conducteurs de ce peuple le fourvoient, et ceux qui sont conduits par eux périssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'C’est pourquoi le Seigneur ne se réjouira pas en leurs jeunes gens, et n’aura pas compassion de leurs orphelins et de leurs veuves; car tous ensemble, ce sont des profanes et des gens qui font le mal, et toute bouche profère l’impiété. Pour tout cela, sa colère ne s’est pas détournée, et sa main est encore étendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Car la méchanceté brûle comme un feu, elle dévore les ronces et les épines, et embrase les épaisseurs de la forêt, et roule et s’élève en colonne de fumée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Par la fureur de l’ Éternel des armées le pays est consumé, et le peuple est comme ce qui alimente le feu: l’un n’épargne pas l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Et on arrache à droite, et on a faim; et on dévore à gauche, et on n’est pas rassasié. Ils mangent chacun la chair de son bras:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Manassé, Éphraïm, et Éphraïm, Manassé; [et] ceux-ci ensemble sont contre Juda. Pour tout cela, sa colère ne s’est pas détournée, et sa main est encore étendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Malheur à ceux qui rendent des décrets d’iniquité, et à ceux qui écrivent des arrêts d’oppression,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'pour empêcher que justice ne soit faite aux pauvres, et pour ravir leur droit aux affligés de mon peuple; pour faire des veuves leur proie et piller les orphelins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Et que ferez-vous au jour de la visitation et de la destruction qui vient de loin? Vers qui vous enfuirez-vous pour avoir du secours, et où laisserez-vous votre gloire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, '[Il ne reste] qu’à se courber sous les prisonniers; et ils tomberont sous ceux qui sont massacrés. Pour tout cela, sa colère ne s’est pas détournée, et sa main est encore étendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Ha! l’Assyrie, verge de ma colère! Et le bâton qui est dans leur main, c’est mon indignation!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Je l’enverrai contre une nation profane; et je lui donnerai un mandat contre le peuple de ma fureur, pour [le] butiner et [le] piller, et pour le fouler aux pieds comme la boue des rues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Mais lui n’en juge pas ainsi, et son cœur ne pense pas ainsi; car il a au cœur de dévaster et de retrancher des nations, pas en petit nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Car il a dit: Mes princes ne sont-ils pas tous des rois?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Calno n’est-elle pas comme Carkemish? Hamath n’est-elle pas comme Arpad? Samarie n’est-elle pas comme Damas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Comme ma main a trouvé les royaumes des idoles (et leurs images étaient plus que celles de Jérusalem et de Samarie),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'ne ferai-je pas à Jérusalem et à ses images ainsi que j’ai fait à Samarie et à ses idoles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Et il arrivera que, quand le Seigneur aura achevé toute son œuvre contre la montagne de Sion et contre Jérusalem, je visiterai le fruit de l’arrogance du cœur du roi d’Assyrie et la gloire de la fierté de ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Car il a dit: Par la force de ma main je l’ai fait, et par ma sagesse, car je suis intelligent; et j’ai ôté les bornes des peuples, et j’ai pillé leurs trésors, et comme un [homme] puissant j’ai fait descendre ceux qui étaient assis [sur des trônes].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Et ma main a trouvé comme un nid les richesses des peuples; et, comme on ramasse des œufs délaissés, moi, j’ai ramassé toute la terre, et il n’y en a pas eu un qui ait remué l’aile, ni ouvert le bec, ni crié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, '– La cognée se glorifiera-t-elle contre celui qui s’en sert? La scie s’élèvera-t-elle contre celui qui la manie? Comme si la verge faisait mouvoir ceux qui la lèvent, comme si le bâton levait celui qui n’est pas du bois!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'C’est pourquoi le Seigneur, l’ Éternel des armées, enverra la maigreur parmi ses [hommes] gras, et, sous sa gloire, allumera un incendie comme un incendie de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Et la lumière d’Israël sera un feu, et son Saint, une flamme; et il brûlera et dévorera ses épines et ses ronces, en un seul jour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'et il consumera la gloire de sa forêt et de son champ fertile, depuis l’âme jusqu’à la chair; et il en sera comme d’un malade qui va dépérissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Et le reste des arbres de sa forêt sera un petit nombre, et un enfant les inscrirait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Et il arrivera, en ce jour-là, que le résidu d’Israël et les réchappés de la maison de Jacob ne s’appuieront plus sur celui qui les a frappés; mais ils s’appuieront sur l’ Éternel, le Saint d’Israël, en vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Le résidu reviendra, le résidu de Jacob, au ✶Dieu fort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'car ton peuple Israël serait-il comme le sable de la mer, un résidu [seulement] reviendra; la consomption décrétée débordera en justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Car le Seigneur, l’ Éternel des armées, accomplit au milieu de toute la terre une consomption, et une [consomption] décrétée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel des armées: Mon peuple, qui habites en Sion, ne crains pas l’Assyrien! Il te frappera avec une verge et lèvera son bâton sur toi à la manière de l’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'car encore très peu de temps, et l’indignation sera accomplie, et ma colère, dans leur destruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Et l’ Éternel des armées suscitera contre lui un fouet, comme Madian a été frappé au rocher d’Oreb; et son bâton [sera] sur la mer, et il le lèvera à la manière de l’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Et il arrivera en ce jour-là, que son fardeau sera ôté de dessus ton épaule, et son joug de dessus ton cou; et le joug sera détruit à cause de l’onction...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Il est arrivé à Aïath, il a traversé Migron, il a déposé ses bagages à Micmash.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Ils ont passé le défilé; ils ont dressé leur camp à Guéba. Rama tremble, Guibha de Saül a pris la fuite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Pousse des cris, fille de Gallim! Fais attention, Laïs! – Pauvre Anathoth!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madména est en fuite, les habitants de Guébim se sauvent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Encore un jour d’arrêt à Nob; il menace de sa main la montagne de la fille de Sion, la colline de Jérusalem...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Voici, le Seigneur, l’ Éternel des armées, abat les hautes branches avec violence, et ceux qui sont grands de stature seront coupés, et ceux qui sont élevés seront abaissés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'et il éclaircira avec le fer les épais taillis de la forêt, et le Liban tombera par un puissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Et il sortira un rejeton du tronc d’Isaï, et une branche de ses racines fructifiera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'et l’Esprit de l’ Éternel reposera sur lui, l’esprit de sagesse et d’intelligence, l’esprit de conseil et de force, l’esprit de connaissance et de crainte de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Et son plaisir sera la crainte de l’ Éternel; et il ne jugera pas d’après la vue de ses yeux, et ne reprendra pas selon l’ouïe de ses oreilles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'mais il jugera avec justice les misérables, et reprendra avec droiture les débonnaires de la terre; et il frappera la terre avec la verge de sa bouche, et par le souffle de ses lèvres il fera mourir le méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Et la justice sera la ceinture de ses reins, et la fidélité, la ceinture de ses flancs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Et le loup habitera avec l’agneau, et le léopard couchera avec le chevreau; et le veau et le jeune lion, et la bête grasse, seront ensemble, et un petit enfant les conduira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'La vache paîtra avec l’ourse, leurs petits coucheront l’un près de l’autre, et le lion mangera de la paille comme le bœuf.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Le nourrisson s’ébattra sur le trou de l’aspic, et l’enfant sevré étendra sa main sur l’antre de la vipère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'On ne fera pas de tort, et on ne détruira pas, dans toute ma sainte montagne; car la terre sera pleine de la connaissance de l’ Éternel, comme les eaux couvrent [le fond de] la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Et, en ce jour-là, il y aura une racine d’Isaï, se tenant là comme une bannière des peuples: les nations la rechercheront, et son repos sera gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Et il arrivera, en ce jour-là, que le Seigneur mettra sa main encore une seconde fois pour acquérir le résidu de son peuple, qui sera demeuré de reste, de l’Assyrie, et de l’Égypte, et de Pathros, et de Cush, et d’Élam, et de Shinhar, et de Hamath, et des îles de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Et il élèvera un étendard devant les nations, et rassemblera les exilés d’Israël, et réunira les dispersés de Juda des quatre bouts de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Et la jalousie d’Éphraïm s’en ira, et les adversaires de Juda seront retranchés; Éphraïm ne sera pas rempli d’envie contre Juda, et Juda ne sera pas l’adversaire d’Éphraïm;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'mais ils voleront sur l’épaule des Philistins vers l’ouest, ils pilleront ensemble les fils de l’orient: Édom et Moab seront la proie de leurs mains, et les fils d’Ammon leur obéiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Et l’ Éternel desséchera la langue de la mer d’Égypte; et il secouera sa main sur le fleuve dans l’impétuosité de son vent, et le frappera pour [qu’il devienne] sept ruisseaux, et [y] fera marcher avec des souliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Et il y aura un chemin battu pour le résidu de son peuple, qui sera demeuré de reste, de l’Assyrie, selon ce qui est arrivé à Israël au jour où il est monté du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Et tu diras en ce jour-là: Je te célébrerai, Éternel, car tu étais en colère contre moi, [et] ta colère s’est détournée, et tu m’as consolé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Voici, ✶Dieu est mon salut; j’aurai confiance, et je ne craindrai pas; car Jah, Jéhovah, est ma force et mon cantique, et il a été mon salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Et vous puiserez de l’eau avec joie aux fontaines du salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Et vous direz en ce jour-là: Célébrez l’ Éternel, invoquez son nom; faites connaître parmi les peuples ses actes, rappelez que son nom est haut élevé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Chantez l’ Éternel, car il a fait des choses magnifiques. Cela est connu dans toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Pousse des cris de joie et exulte, habitante de Sion, car grand, au milieu de toi, est le Saint d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, '***L’oracle touchant Babylone, qu’a vu Ésaïe, fils d’Amots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Élevez un étendard sur une montagne nue, élevez la voix vers eux, secouez la main, et qu’ils entrent dans les portes des nobles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'J’ai donné commandement à mes saints, j’ai appelé aussi pour ma colère mes hommes forts, ceux qui se réjouissent en ma grandeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'La voix d’une multitude sur les montagnes, semblable à un grand peuple, la voix d’un tumulte des royaumes des nations rassemblées...: l’ Éternel des armées fait la revue de la milice de guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Ils viennent d’un pays lointain, du bout des cieux, l’ Éternel et les instruments de son indignation, pour détruire tout le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Hurlez, car le jour de l’ Éternel est proche! Il viendra comme une destruction du Tout-puissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'C’est pourquoi toutes les mains deviendront lâches, et tout cœur d’homme se fondra,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'et ils seront terrifiés; les détresses et les douleurs s’empareront d’eux; ils se tordront comme celle qui enfante; ils se regarderont stupéfaits; leurs visages seront de flamme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Voici, le jour de l’ Éternel vient, cruel, avec fureur et ardeur de colère, pour réduire la terre en désolation; et il en exterminera les pécheurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Car les étoiles des cieux et leurs constellations ne feront pas briller leur lumière; le soleil sera obscur à son lever, et la lune ne fera pas luire sa clarté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'et je punirai le monde pour sa malice, et les méchants pour leur iniquité; et je ferai cesser l’orgueil des arrogants et j’abattrai la hauteur des hommes fiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Je ferai qu’un mortel sera plus précieux que l’or fin, et un homme, plus que l’or d’Ophir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'C’est pourquoi je ferai trembler les cieux, et la terre sera ébranlée de sa place, par la fureur de l’ Éternel des armées et au jour de l’ardeur de sa colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Et il en sera comme d’une gazelle chassée et d’un troupeau que personne ne rassemble: chacun se tournera vers son peuple, et chacun fuira vers son pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'tous ceux qui seront trouvés seront transpercés, et quiconque se joindra [à eux] tombera par l’épée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'et leurs petits enfants seront écrasés devant leurs yeux, leurs maisons seront pillées, et leurs femmes seront violées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Voici, je réveille contre eux les Mèdes, qui n’estiment pas l’argent, et, quant à l’or, n’y prennent pas de plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Et leurs arcs abattront les jeunes gens, et ils n’auront pas compassion du fruit du ventre; leur œil n’épargnera pas les fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Et Babylone, l’ornement des royaumes, la gloire de l’orgueil des Chaldéens, sera comme quand Dieu renversa Sodome et Gomorrhe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Elle ne sera jamais habitée, et on n’y demeurera pas, de génération en génération, et l’Arabe n’y dressera pas sa tente, et les bergers n’y feront pas reposer [leurs troupeaux];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'mais les bêtes du désert y auront leur gîte, et les hiboux rempliront ses maisons, et les autruches y feront leur demeure, et les boucs sauvages y sauteront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'et les chacals s’entre-répondront dans ses palais, et les chiens sauvages, dans les maisons luxueuses. Et son temps est près d’arriver; et ses jours ne seront pas prolongés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Car l’ Éternel aura compassion de Jacob et choisira encore Israël, et les établira en repos sur leur terre; et l’étranger se joindra à eux, et sera ajouté à la maison de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Et les peuples les prendront et les feront venir en leur lieu, et la maison d’Israël les possédera, sur la terre de l’ Éternel, pour serviteurs et pour servantes: et ils mèneront captifs ceux qui les tenaient captifs, et ils domineront sur leurs oppresseurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Et il arrivera, au jour où l’ Éternel te donnera du repos de ton labeur et de ton trouble et du dur service auquel on t’a asservi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'que tu prononceras ce cantique sentencieux sur le roi de Babylone, et tu diras: Comment l’oppresseur a-t-il cessé? comment l’exactrice a-t-elle cessé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'L’ Éternel a brisé le bâton des méchants, le sceptre des dominateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Celui qui, dans sa fureur, frappait de coups les peuples, sans relâche, dominant les nations dans sa colère, est poursuivi sans trêve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Toute la terre est en repos [et] tranquille; elle éclate en chants de triomphe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Les cyprès aussi se réjouissent de toi, les cèdres du Liban: Depuis que tu es tombé, l’abatteur n’est plus monté contre nous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, '– Le shéol d’en bas s’émeut pour toi, te rencontrant à ta venue, réveillant pour toi les trépassés, tous les boucs de la terre, faisant lever de leurs trônes tous les rois des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Tous, ils prendront la parole et te diront: Toi aussi, tu as été rendu faible, comme nous; tu es devenu semblable à nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, '– Ton orgueil est descendu dans le shéol, le son de tes luths. Les vers sont étendus sous toi, et les larves sont ta couverture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Comment es-tu tombé des cieux, astre brillant, fils de l’aurore? Tu es abattu jusqu’à terre, toi qui subjuguais les nations!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Et toi, tu as dit dans ton cœur: Je monterai aux cieux, j’élèverai mon trône au-dessus des étoiles de ✶Dieu, et je m’assiérai sur la montagne de l’assignation, au fond du nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Je monterai sur les hauteurs des nues, je serai semblable au Très-haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Toutefois, on t’a fait descendre dans le shéol, au fond de la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Ceux qui te voient fixent leurs regards sur toi, ils te considèrent, [disant]: Est-ce ici l’homme qui a fait trembler la terre, qui ébranlait les royaumes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'qui a fait du monde un désert, et qui ruinait ses villes? Ses prisonniers, il ne les renvoyait pas chez eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, '– Tous les rois des nations, eux tous, reposent dans leur gloire, chacun dans sa maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'mais toi, tu as été jeté hors de ton sépulcre comme une branche qui fait horreur, recouvert de tués, percés par l’épée, descendus jusqu’aux pierres d’une fosse,... comme un cadavre foulé aux pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Tu ne seras pas réuni avec eux dans le sépulcre; car tu as ruiné ton pays, tu as tué ton peuple. De la race des méchants il ne sera jamais fait mention.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Préparez la tuerie pour ses fils, à cause de l’iniquité de leurs pères; qu’ils ne se lèvent pas, ni ne possèdent la terre, ni ne remplissent de villes la face du monde!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Je me lèverai contre eux, dit l’ Éternel des armées, et je retrancherai de Babylone le nom et le reste, enfants et postérité, dit l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'et j’en ferai une possession du butor, et des mares d’eau; et je la balaierai avec le balai de la destruction, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'L’ Éternel des armées a juré, disant: Pour certain, comme j’ai pensé, ainsi il arrivera, et, comme j’ai pris conseil, la chose s’accomplira,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'de briser l’Assyrien dans mon pays; et je le foulerai aux pieds sur mes montagnes; et son joug sera ôté de dessus eux, et son fardeau sera ôté de dessus leurs épaules.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'C’est là le conseil qui est arrêté contre toute la terre, et c’est là la main qui est étendue sur toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Car l’ Éternel des armées a pris [ce] conseil, et qui l’annulera? Et sa main est étendue, et qui la [lui] fera retirer?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, '*L’année de la mort du roi Achaz, fut [prononcé] cet oracle:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Ne te réjouis pas, Philistie tout entière, de ce que la verge qui t’a frappée est brisée; car de la racine du serpent sortira une vipère, et son fruit sera un serpent brûlant qui vole;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'et les premiers-nés des misérables paîtront, et les pauvres se coucheront en assurance; mais je ferai mourir de faim ta racine, et tes restes, on les tuera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Hurle, porte! Ville, pousse des cris! Sois dissoute, Philistie tout entière! car une fumée vient du nord, et nul ne reste à l’écart dans ses rassemblements de troupes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Et que répondra-t-on aux messagers des nations? Que l’ Éternel a fondé Sion, et que les pauvres de son peuple y trouvent un refuge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, '*L’oracle touchant Moab. Car, dans la nuit où elle est dévastée, Ar de Moab est détruite, car, dans la nuit où elle est dévastée, Kir de Moab est détruite:...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Il est monté à Baïth et à Dibon, aux hauts lieux, pour pleurer; Moab hurle sur Nebo et sur Médeba; toutes les têtes sont chauves, toute barbe est coupée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Dans ses rues, ils ont ceint le sac; sur ses toits et dans ses places tout gémit, se fondant en pleurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'et Hesbon pousse des cris, et Elhalé: leur voix est entendue jusqu’à Jahats. C’est pourquoi les gens armés de Moab crient, son âme tremble en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mon cœur pousse des cris au sujet de Moab; ses fugitifs [vont] jusqu’à Tsoar, [jusqu’à] Églath-Shelishija; car ils montent la montée de Lukhith en pleurant, et sur le chemin de Horonaïm ils élèvent un cri de ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Car les eaux de Nimrim seront des désolations; car l’herbage est desséché, l’herbe verte a péri, la verdure n’est plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'C’est pourquoi, les biens qu’ils ont acquis, et leur réserve, ils les portent au ruisseau des saules.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Car un cri environne la frontière de Moab: son hurlement [se fait entendre] jusqu’à Églaïm, et le hurlement jusqu’à Beër-Élim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Car les eaux de Dimon sont pleines de sang; car je ferai venir encore davantage sur Dimon: le lion sur les réchappés de Moab et sur ce qui reste du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Envoyez l’agneau [du] dominateur du pays, – du rocher vers le désert – à la montagne de la fille de Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Et comme un oiseau fugitif, une nichée chassée, ainsi seront les filles de Moab, aux gués de l’Arnon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Donne conseil, fais ce qui est juste; rends ton ombre comme la nuit, en plein midi: cache les exilés, ne découvre pas le fugitif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Que mes exilés séjournent avec toi, Moab! Sois-leur une retraite de devant le destructeur. Car l’oppresseur ne sera plus, la dévastation finira; celui qui foule disparaîtra du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Et un trône sera établi par la bonté; et il y en aura un qui y siégera dans la vérité, dans la tente de David, jugeant, et recherchant la droiture, et hâtant la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Nous avons entendu l’orgueil de Moab, le très hautain, sa fierté, et son orgueil, et sa rage; ses vanteries ne sont que vanité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'C’est pourquoi Moab hurlera sur Moab; tout entier il hurlera! Vous gémirez sur les fondations de Kir-Haréseth, tout affligés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Car les campagnes de Hesbon languiront, – la vigne de Sibma. Les maîtres des nations ont abîmé ses ceps exquis: ils s’étendaient jusqu’à Jahzer, ils erraient dans le désert; ses provins s’étendaient et dépassaient la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'C’est pourquoi je pleurerai des pleurs de Jahzer la vigne de Sibma; je vous arroserai de mes larmes, Hesbon et Elhalé, car un cri est tombé sur votre récolte et sur votre moisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Et la joie et l’allégresse ont disparu des champs fertiles, et dans les vignes on ne chante pas, on ne pousse pas des cris de joie; celui qui foulait ne foule plus le vin dans les pressoirs: j’ai fait cesser le cri [du pressoir].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'C’est pourquoi mes entrailles mènent un bruit sourd au sujet de Moab, comme une harpe, et mon cœur, au sujet de Kir-Hérès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Et il arrivera que, quand Moab se présentera, se fatiguera sur le haut lieu, et entrera dans son sanctuaire pour prier, il ne prévaudra pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Telle est la parole que l’ Éternel a prononcée jadis sur Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Et maintenant l’ Éternel a parlé, disant: Dans trois ans, comme les années d’un mercenaire, la gloire de Moab sera réduite à rien avec toute sa grande multitude; et le reste sera petit, amoindri, peu de chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, '*L’oracle touchant Damas. Voici, Damas va cesser d’être une ville, et elle sera un monceau de ruines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Les villes d’Aroër sont abandonnées, elles seront pour les troupeaux; ils y coucheront, et il n’y aura personne qui les effraie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Et la forteresse a cessé en Éphraïm, et le royaume à Damas; et ce qui reste de la Syrie sera comme la gloire des fils d’Israël, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Et il arrivera, en ce jour-là, que la gloire de Jacob sera affaiblie, et que la graisse de sa chair sera amaigrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Et il en sera comme quand le moissonneur récolte les blés, et que son bras moissonne les épis; il en sera comme quand on ramasse des épis dans la vallée de Rephaïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Mais il y restera un grappillage, comme quand on secoue l’olivier: deux, trois baies au plus haut sommet, quatre, cinq dans ses branches fruitières, dit l’ Éternel, le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'En ce jour-là, l’homme regardera vers celui qui l’a fait, et ses yeux verront le Saint d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'et il ne regardera pas aux autels, œuvre de ses mains, et il ne tournera pas son regard vers ce que ses doigts ont fait, ni vers les ashères, ni vers les colonnes consacrées au soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'En ce jour-là ses villes fortifiées seront comme les lieux délaissés d’un bois épais et d’un sommet, qui ont été délaissés devant les fils d’Israël; et ce sera une désolation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Car tu as oublié le Dieu de ton salut, et tu ne t’es pas souvenue du rocher de ton lieu fort; c’est pourquoi tu planteras des plantations agréables, et tu les sèmeras de ceps étrangers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'le jour même où tu planteras, tu feras croître, et le matin tu feras pousser ta semence; [mais] au jour de l’entrée en possession, la moisson sera un monceau, et la douleur, incurable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Malheur à la multitude de peuples nombreux! – ils bruient comme le bruit des mers, – et au tumulte des peuplades! ils s’émeuvent en tumulte comme le tumulte de grosses eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Les peuplades s’émeuvent en tumulte comme les grandes eaux s’émeuvent en tumulte; mais [Dieu] les reprendra, et elles fuiront au loin, et elles seront chassées comme la balle des montagnes devant le vent, et comme le chaume devant le tourbillon:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'au temps du soir, voici l’épouvante; avant le matin, elles ne sont plus. Tel est le partage de ceux qui nous dépouillent, et le sort de ceux qui nous pillent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, '*Ha! pays qui fais ombre avec tes ailes, [toi] qui es au-delà des fleuves de Cush,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'qui envoies des ambassadeurs sur la mer et dans des vaisseaux de papyrus, sur la face des eaux, [disant]: Allez, messagers rapides, vers une nation répandue loin et ravagée, vers un peuple merveilleux dès ce temps et au-delà, vers une nation qui attend, attend, et qui est foulée aux pieds, de laquelle les rivières ont ravagé le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Vous tous, habitants du monde, et vous qui demeurez sur la terre, quand l’étendard sera élevé sur les montagnes, voyez; et quand la trompette sonnera, écoutez!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Car ainsi m’a dit l’ Éternel: Je resterai tranquille, et je regarderai de ma demeure, comme une chaleur sereine sur la verdure, comme une nuée de rosée dans la chaleur de la moisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Car avant la moisson, lorsque la floraison est finie et que la fleur devient un raisin vert qui mûrit, il coupera les pousses avec des serpes, et il ôtera [et] retranchera les sarments.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Ils seront abandonnés ensemble aux oiseaux de proie des montagnes et aux bêtes de la terre; et les oiseaux de proie passeront l’été sur eux, et toutes les bêtes de la terre passeront l’hiver sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'En ce temps-là, un présent sera apporté à l’ Éternel des armées, [le présent] d’un peuple répandu loin et ravagé, – et de la part d’un peuple merveilleux dès ce temps et au-delà, de la part d’une nation qui attend, attend, et qui est foulée aux pieds, de laquelle les rivières ont ravagé le pays,... au lieu où est le nom de l’ Éternel des armées, à la montagne de Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, '*L’oracle touchant l’Égypte. Voici, l’ Éternel, porté sur une nuée rapide, vient en Égypte, et les idoles de l’Égypte sont agitées à cause de sa présence, et le cœur de l’Égypte se fond au-dedans d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Et j’exciterai l’Égyptien contre l’Égyptien; et ils feront la guerre chacun contre son frère et chacun contre son compagnon, ville contre ville, royaume contre royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Et l’esprit de l’Égypte s’en ira, au milieu d’elle, et je détruirai son conseil; et ils s’enquerront auprès des idoles, et auprès des nécromanciens et des évocateurs d’esprits et des diseurs de bonne aventure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Et je livrerai l’Égypte en la main d’un seigneur dur, et un roi cruel dominera sur eux, dit le Seigneur, l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Et les eaux manqueront à la mer, et la rivière tarira et se desséchera,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'et les rivières deviendront puantes; les fleuves de l’Égypte seront diminués et tariront, les roseaux et les joncs se flétriront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Les prairies sur le Nil, sur le bord du Nil, et tout ce qui est ensemencé le long du Nil, [tout] se desséchera, se réduira en poussière et ne sera plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Et les pêcheurs gémiront; et tous ceux qui jettent un hameçon dans le Nil mèneront deuil, et ceux qui étendent un filet sur la face des eaux languiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Et ceux qui travaillent le lin peigné seront honteux, et ceux qui tissent le coton.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Et les colonnes [du pays] sont brisées; tous ceux qui gagnent un salaire ont l’âme attristée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Ils ne sont que des fous, les princes de Tsoan, les sages conseillers du Pharaon; [leur] conseil est devenu stupide. Comment dites-vous au Pharaon: Je suis un fils des sages, le fils d’anciens rois?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Où sont-ils donc, tes sages? Qu’ils te déclarent, je te prie, et te fassent savoir ce que l’ Éternel des armées a résolu contre l’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Les princes de Tsoan sont devenus fous, les princes de Noph sont trompés, et les chefs de ses tribus ont fait errer l’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'l’ Éternel a versé au milieu d’elle un esprit de perversité; et ils ont fait errer l’Égypte dans tout ce qu’elle fait, comme chancelle dans son vomissement celui qui est ivre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'et il n’y aura pas pour l’Égypte une œuvre que puisse faire tête ou queue, branche de palmier ou jonc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'En ce jour-là, l’Égypte sera comme des femmes; et elle tremblera et aura peur devant le secouement de la main de l’ Éternel des armées, qu’il secoue contre elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Et la terre de Juda sera pour l’Égypte une terreur: quiconque se la rappellera aura peur, à cause du conseil de l’ Éternel des armées, que, lui, il a pris contre elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'En ce jour-là, il y aura cinq villes dans le pays d’Égypte qui parleront la langue de Canaan et jureront par l’ Éternel des armées; l’une sera appelée Ir-ha-Hérès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'En ce jour-là, il y aura un autel [élevé] à l’ Éternel au milieu du pays d’Égypte, et, à la frontière même, une colonne [dédiée] à l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'et ce sera un signe et un témoignage à l’ Éternel des armées dans le pays d’Égypte. Car ils crieront à l’ Éternel à cause des oppresseurs, et il leur enverra un sauveur et un défenseur, et il les délivrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Et l’ Éternel se fera connaître des Égyptiens, et les Égyptiens connaîtront l’ Éternel, en ce jour-là; et ils serviront avec un sacrifice et une offrande, et ils voueront un vœu à l’ Éternel et l’accompliront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Et l’ Éternel frappera l’Égypte; il frappera, et il guérira; et ils se tourneront vers l’ Éternel, et il leur sera propice et les guérira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'En ce jour-là, il y aura un chemin battu de l’Égypte à l’Assyrie; et l’Assyrie viendra en Égypte, et l’Égypte en Assyrie; et l’Égypte servira avec l’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'En ce jour-là, Israël sera le troisième, avec l’Égypte et avec l’Assyrie, une bénédiction au milieu de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'car l’ Éternel des armées le bénira, disant: Béni soit l’Égypte, mon peuple, et l’Assyrie, l’ouvrage de mes mains, et Israël, mon héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, '*L’année où le Tharthan vint à Asdod, quand Sargon, roi d’Assyrie, l’envoya (et il fit la guerre contre Asdod et la prit):');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'en ce temps-là, l’ Éternel parla par Ésaïe, fils d’Amots, disant: Va, ôte le sac de dessus tes reins, et détache ta sandale de ton pied. Et il fit ainsi, marchant nu et nu-pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Et l’ Éternel dit: Comme mon serviteur Ésaïe a marché nu et nu-pieds trois années, [pour être] un signe et un symbole à l’égard de l’Égypte et de l’Éthiopie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'ainsi le roi d’Assyrie mènera les captifs de l’Égypte et les transportés de l’Éthiopie, jeunes et vieux, nus et nu-pieds et leurs hanches découvertes, à la honte de l’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, '– Et ils seront terrifiés, et auront honte de l’Éthiopie, leur confiance, et de l’Égypte, leur orgueil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Et l’habitant de cette côte dira en ce jour-là: Voilà notre confiance, ceux vers qui nous avons couru pour avoir du secours, pour être délivrés de devant le roi d’Assyrie! et nous, comment échapperons-nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, '*L’oracle touchant le désert de la mer. Comme des tourbillons dans le midi quand ils passent, il vient du désert, du pays terrible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Une cruelle vision m’est révélée: Le perfide agit perfidement, et le destructeur détruit. Monte, Élam! assiège, Médie! J’ai fait cesser tout son gémissement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'C’est pourquoi mes reins sont remplis de douleur; des angoisses m’ont saisi comme les angoisses de celle qui enfante; je suis courbé, à ne pas entendre; je suis terrifié, à n’y pas voir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'mon cœur bat; le tremblement s’est emparé de moi; la nuit de mon plaisir, il me l’a changée en effroi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Dresse la table; fais le guet; mange, bois... Princes, levez-vous, oignez le bouclier!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Car ainsi m’a dit le Seigneur: Va, place une sentinelle; qu’elle déclare ce qu’elle voit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Et elle vit un char, une paire de cavaliers, un char [attelé] d’ânes, un char [attelé] de chameaux. Et elle écouta diligemment, avec grande attention;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'et elle cria [comme] un lion: Seigneur, je me tiens dans le poste d’observation constamment, de jour, et je suis là faisant ma garde toutes les nuits...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Et voici, il vient un char d’hommes, une paire de cavaliers! Et il répondit, et dit: Babylone est tombée, elle est tombée, et toutes les images de ses dieux sont brisées par terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Ô vous, mon blé battu, et le fruit de mon aire! ce que j’ai entendu de l’ Éternel des armées, le Dieu d’Israël, je vous l’ai rapporté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, '*L’oracle touchant Duma. Il me crie de Séhir: Sentinelle, à quoi en est la nuit? Sentinelle, à quoi en est la nuit?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'La sentinelle dit: Le matin vient, et aussi la nuit. Si vous voulez vous enquérir, enquérez-vous; revenez, venez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, '*L’oracle contre l’Arabie. Vous logerez dans la forêt de l’Arabie, caravanes des Dedanites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'À la rencontre de celui qui a soif apportez de l’eau! Les habitants du pays de Théma viennent avec leur pain au-devant de celui qui fuit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'car ils s’enfuient devant les épées, devant l’épée dégainée, et devant l’arc tendu, et devant le poids de la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Car ainsi m’a dit le Seigneur: Encore une année comme les années d’un mercenaire, et toute la gloire de Kédar aura pris fin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'et le reste du nombre des archers des hommes forts des fils de Kédar sera amoindri; car l’ Éternel, le Dieu d’Israël, a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, '*L’oracle touchant la vallée de vision. Qu’as-tu donc que tu sois tout entière montée sur les toits,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'toi qui étais pleine de mouvement, ville bruyante, cité joyeuse? Tes tués ne sont pas tués par l’épée et ne sont pas morts à la guerre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'tous tes chefs se sont enfuis ensemble: ils sont faits prisonniers sans l’arc; tous les tiens qui sont trouvés sont faits prisonniers ensemble; ils fuyaient au loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'C’est pourquoi j’ai dit: Détournez-vous de moi, que je pleure amèrement! Ne vous pressez pas de me consoler au sujet de la ruine de la fille de mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Car [c’est] un jour de trouble et d’écrasement et de consternation [de la part] du Seigneur, l’ Éternel des armées, dans la vallée de vision; on renverse la muraille, et des cris [retentissent] vers la montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Élam porte le carquois, avec des chars d’hommes [et] des cavaliers; et Kir découvre le bouclier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Et il arrivera que les meilleures de tes vallées seront remplies de chars, et la cavalerie s’établira à la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Et il ôte la couverture de Juda. Et tu as regardé en ce jour-là vers l’arsenal de la maison de la forêt;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'et vous avez vu les brèches de la ville de David, qu’elles sont nombreuses; et vous avez rassemblé les eaux de l’étang inférieur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'et vous avez compté les maisons de Jérusalem; et vous avez démoli les maisons pour fortifier la muraille;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'et vous avez fait un réservoir entre les murs, pour les eaux du vieil étang; mais vous n’avez pas regardé vers celui qui a fait [cela], ni tourné vos regards vers celui qui l’a formé dès longtemps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Et le Seigneur, l’ Éternel des armées, appela en ce jour-là à pleurer et à se lamenter, et à se raser les cheveux, et à ceindre le sac:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'et voici, l’allégresse et la joie! On tue des bœufs et on égorge des moutons, on mange de la chair et on boit du vin: Mangeons et buvons, car demain nous mourrons!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Et il a été révélé dans mes oreilles de par l’ Éternel des armées: Si [jamais] cette iniquité vous est pardonnée, jusqu’à ce que vous mouriez, dit le Seigneur, l’ Éternel des armées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Ainsi dit le Seigneur, l’ Éternel des armées: Va, entre auprès de cet intendant, auprès de Shebna, qui est [établi] sur la maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Qu’as-tu ici, et qui as-tu ici, que tu te creuses un sépulcre ici, [comme] qui creuse son sépulcre sur la hauteur, et se taille dans le rocher une habitation?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Voici, l’ Éternel te jettera loin avec force, et te couvrira entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'T’enroulant en pelote, il te roulera comme une boule dans un pays spacieux. Là tu mourras, et là seront les chars de ta gloire, ô opprobre de la maison de ton Seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Et je te chasserai de ta place, et te renverserai de ta position.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Et il arrivera, en ce jour-là, que j’appellerai mon serviteur Éliakim, fils de Hilkija;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'et je le revêtirai de ta tunique, et je le fortifierai avec ta ceinture, et je mettrai ton intendance en sa main; et il sera pour père aux habitants de Jérusalem et à la maison de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Et je mettrai la clé de la maison de David sur son épaule; et il ouvrira, et personne ne fermera; et il fermera, et personne n’ouvrira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Et je le fixerai comme un clou dans un lieu sûr, et il sera un trône de gloire pour la maison de son père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'et on suspendra sur lui toute la gloire de la maison de son père: les descendants et les rejetons, tous les petits vases, tant les coupes que toutes les amphores.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, '– En ce jour-là, dit l’ Éternel des armées, le clou fixé en un lieu sûr sera ôté, et sera brisé et tombera; et le fardeau qui y est [suspendu] sera coupé, car l’ Éternel a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, '*L’oracle sur Tyr. Hurlez, navires de Tarsis, car elle est dévastée, de sorte qu’il n’y a pas de maisons, personne qui entre. Du pays de Kittim cela leur est révélé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Tenez-vous en silence, habitants de l’île! Les marchands de Sidon qui passent par la mer t’ont remplie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Et sur de grandes eaux la semence du Shikhor, la moisson du Nil, était son revenu; et elle était le marché des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Aie honte, Sidon, car la mer a parlé, la force de la mer, disant: Je n’ai pas été en travail d’enfant, je n’ai pas enfanté, et je n’ai pas nourri de jeunes hommes, ni élevé de vierges. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Quand la rumeur est arrivée en Égypte, ils ont été dans l’angoisse à [l’ouïe des] nouvelles de Tyr.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Traversez vers Tarsis, hurlez, vous, les habitants de l’île!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Est-ce là votre [ville] joyeuse, qui avait son origine dès les jours d’autrefois? Ses pieds la porteront pour demeurer au loin en étrangère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Qui a pris ce conseil à l’égard de Tyr, distributrice de couronnes, dont les négociants étaient des princes, dont les marchands étaient les nobles de la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'L’ Éternel des armées a pris ce conseil, pour profaner l’orgueil de toute gloire, pour réduire à néant tous les nobles de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Répands-toi sur ton pays comme le Nil, fille de Tarsis; il n’y a plus rien qui retienne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Il a étendu sa main sur la mer; il a fait trembler les royaumes. L’ Éternel a commandé contre Canaan, d’en détruire les forteresses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'et il a dit: Tu ne t’égaieras plus, vierge opprimée, fille de Sidon! Lève-toi, passe à Kittim; là encore il n’y aura pas de repos pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Vois le pays des Chaldéens: ce peuple n’existait pas; Assur l’a fondé pour les habitants des déserts: ils ont élevé leurs tours, ils ont renversé ses palais; il en a fait des ruines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Hurlez, navires de Tarsis, car votre forteresse est détruite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Et il arrivera, en ce jour-là, que Tyr sera oubliée 70 ans, selon les jours d’un roi. Au bout de 70 ans, ce sera pour Tyr comme la chanson d’une prostituée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Prends la harpe, fais le tour de la ville, prostituée oubliée! Touche habilement les cordes, multiplie tes chansons, afin qu’on se souvienne de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Et il arrivera qu’au bout de 70 ans, l’ Éternel visitera Tyr; et elle reviendra à ses présents et se prostituera avec tous les royaumes de la terre, sur la face du sol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Et ses marchandises et les présents qu’on lui fera seront saints, [consacrés] à l’ Éternel; ils ne seront pas accumulés et ils ne seront pas amassés; car sa marchandise sera pour ceux qui demeurent devant l’ Éternel, afin qu’ils mangent et soient rassasiés, et afin qu’ils aient des vêtements magnifiques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, '*Voici, l’ Éternel rend le pays vide et le dévaste; et il bouleverse sa face, et il disperse ses habitants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Et il en sera, comme du peuple, ainsi du sacrificateur; comme du serviteur, ainsi de son maître; comme de la servante, ainsi de sa maîtresse; comme de l’acheteur, ainsi du vendeur; comme du prêteur, ainsi de l’emprunteur; de celui qui prête à usure, comme de celui à qui est fait un prêt à usure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Le pays sera entièrement vidé et entièrement pillé; car l’ Éternel a dit cette parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Le pays mène deuil et se fane, le monde languit et se fane; ils languissent, – le peuple haut élevé du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Et le pays est souillé sous ceux qui l’habitent; car ils ont transgressé les lois, changé le statut, violé l’alliance éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'C’est pourquoi la malédiction a dévoré le pays, et ceux qui l’habitent subissent la peine de leur culpabilité; c’est pourquoi les habitants du pays sont consumés et il ne reste que peu d’hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Le moût mène deuil, la vigne languit; tous ceux qui étaient joyeux de cœur soupirent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'la joie des tambourins a cessé, le bruit tumultueux de ceux qui se réjouissent a pris fin, la joie de la harpe a cessé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'ils ne boivent pas le vin en chantant, les boissons fortes sont amères pour ceux qui les boivent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'La cité de désolation est ruinée; toute maison est fermée, de sorte que personne n’y entre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Il y a un cri dans les rues au sujet du vin. Toute joie est assombrie, l’allégresse est bannie du pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'la désolation reste dans la ville, et la porte est brisée, – une ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Car il en sera ainsi au milieu du pays, parmi les peuples, – comme quand on secoue l’olivier, comme le grappillage quand la vendange est achevée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Ceux-ci élèveront leur voix, ils exulteront, ils pousseront des cris de joie depuis la mer, à cause de la majesté de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'C’est pourquoi glorifiez l’ Éternel dans les pays de l’aurore, – le nom de l’ Éternel, le Dieu d’Israël, dans les îles de l’occident.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Du bout du pays nous avons entendu des chants: Gloire au juste! Et j’ai dit: Ma maigreur, ma maigreur, malheur à moi! Les perfides ont agi perfidement, les perfides ont agi avec une insigne perfidie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'La frayeur, et la fosse, et le piège, sont sur toi, habitant du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Et il arrivera que celui qui s’enfuit de devant le cri de la frayeur tombera dans la fosse, et celui qui monte du milieu de la fosse sera pris dans le piège; car les fenêtres d’en haut sont ouvertes, et les fondements de la terre sont ébranlés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'La terre est entièrement brisée, la terre se dissout, la terre est violemment remuée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'la terre chancelle, elle chancelle comme un homme ivre; elle est ébranlée deçà et delà comme une cabane pour la nuit; sa transgression pèse sur elle: elle tombera et ne se relèvera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Et il arrivera, en ce jour-là, que l’ Éternel visitera l’armée d’en haut, en haut, et les rois de la terre, sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Et ils seront assemblés dans la fosse, comme on assemble des prisonniers, et ils seront renfermés dans la prison; et après beaucoup de jours ils seront visités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Et la lune rougira, et le soleil aura honte; car l’ Éternel des armées régnera en la montagne de Sion et à Jérusalem, et devant ses anciens, en gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Éternel, tu es mon Dieu; je t’exalterai, je célébrerai ton nom, car tu as accompli des choses merveilleuses, des conseils [qui datent] de loin, qui sont fidélité [et] vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Car tu as fait d’une ville un monceau de pierres; d’une cité fortifiée, des ruines; d’un palais d’étrangers, qu’il ne soit plus une ville: il ne sera jamais rebâti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'C’est pourquoi le peuple fort te glorifiera; la cité des nations terribles te craindra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Car tu as été au misérable un lieu fort, un lieu fort au pauvre dans sa détresse, un abri contre l’orage, une ombre contre la chaleur; car la tempête des terribles [a été] comme une pluie d’orage [contre] un mur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Tu as rabaissé le bruit tumultueux des étrangers, comme la chaleur en un lieu aride; [et] comme la chaleur par l’ombre d’un nuage, le chant des terribles a été apaisé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Et l’ Éternel des armées fera, en cette montagne, à tous les peuples un festin de choses grasses, un festin de vins vieux, de choses grasses moelleuses, de vins vieux bien épurés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Et il détruira en cette montagne la face du voile qui couvre tous les peuples, et la couverture qui est étendue sur toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Il engloutira la mort en victoire; et le Seigneur, l’ Éternel, essuiera les larmes de dessus tout visage, et il ôtera l’opprobre de son peuple de dessus toute la terre; car l’ Éternel a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Et il sera dit en ce jour-là: Voici, c’est ici notre Dieu; nous l’avons attendu, et il nous sauvera; c’est ici l’ Éternel, nous l’avons attendu. Égayons-nous et réjouissons-nous dans sa délivrance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'car la main de l’ Éternel reposera en cette montagne, et Moab sera foulé aux pieds sous lui comme la paille est foulée au fumier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'et il étendra ses mains au milieu de Moab comme celui qui nage les étend pour nager, et il abaissera son orgueil ainsi que les artifices de ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Et la forteresse des hautes défenses de tes murs, il l’abattra, il l’abaissera, il la mettra par terre jusque dans la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'En ce jour-là sera chanté ce cantique dans le pays de Juda: Nous avons une ville forte: il a mis le salut pour murailles et pour remparts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Ouvrez les portes, et qu’elle entre, la nation juste qui garde la fidélité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Tu garderas dans une paix parfaite l’esprit qui s’appuie [sur toi], car il se confie en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Confiez-vous en l’ Éternel, à tout jamais; car en Jah, Jéhovah, est le rocher des siècles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Car il abat ceux qui habitent en haut; il abaisse la ville haut élevée, il l’abaisse jusqu’en terre, il la fait descendre jusque dans la poussière:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'le pied la foulera, les pieds des affligés, les pas des misérables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Le chemin du juste est la droiture. Toi qui es droit, tu aplanis le sentier du juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Oui, dans le chemin de tes jugements, ô Éternel, nous t’avons attendu; le désir de notre âme est après ton nom et après ton souvenir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Mon âme te désire de nuit; oui, mon esprit, au-dedans de moi, te cherche diligemment; car, lorsque tes jugements sont sur la terre, les habitants du monde apprennent la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Si l’on use de grâce envers le méchant, il n’apprend pas la justice; dans le pays de la droiture il fait le mal, et il ne voit pas la majesté de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Ô Éternel, ta main est élevée, mais ils ne voient point; [mais] ils verront [ta] jalousie pour le peuple et seront honteux. Oui, le feu [qui attend] tes adversaires les dévorera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Éternel, tu établiras la paix pour nous; car aussi toutes nos œuvres, tu les as opérées pour nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Éternel, notre Dieu, d’autres seigneurs que toi ont dominé sur nous: par toi seul nous ferons mention de ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Les morts ne vivront pas, les trépassés ne se relèveront pas; car tu les as visités, et tu les as exterminés, et tu as détruit toute mémoire d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Tu as augmenté la nation, ô Éternel; tu as augmenté la nation; tu as été glorifié: tu l’avais éloignée jusqu’à tous les bouts de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Éternel, dans la détresse ils t’ont cherché; ils ont épanché [leur] prière à voix basse, lorsque tu les as châtiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Comme une femme enceinte, près d’enfanter, est dans les douleurs [et] crie dans ses peines, ainsi nous avons été devant toi, ô Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'nous avons conçu, nous avons été dans les douleurs, nous avons comme enfanté du vent; nous n’avons pas opéré le salut du pays, et les habitants du monde ne sont pas tombés...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Tes morts vivront, mes corps morts se relèveront. Réveillez-vous et exultez avec chant de triomphe, vous qui habitez dans la poussière; car ta rosée est la rosée de l’aurore, et la terre jettera dehors les trépassés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Viens, mon peuple, entre dans tes chambres et ferme tes portes sur toi; cache-toi pour un petit moment, jusqu’à ce que l’indignation soit passée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Car voici, l’ Éternel sort de son lieu pour visiter l’iniquité des habitants de la terre sur eux, et la terre révélera son sang, et ne cachera plus ses tués.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'En ce jour-là, l’ Éternel visitera de son épée, dure et grande et forte, le léviathan, serpent fuyard, et le léviathan, serpent tortueux; et il tuera le monstre qui est dans la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'En ce jour-là, [il y aura] une vigne de vin pur; chantez à son sujet:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Moi, l’ Éternel, j’en prends soin; à tout moment je l’arroserai; de peur qu’on ne la visite, j’en prendrai soin nuit et jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Il n’y a pas en moi de fureur. Oh! si j’avais les ronces et les épines en bataille contre moi, je marcherais contre elles; je les brûlerais ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Ou bien, qu’il saisisse ma force, qu’il fasse la paix avec moi, qu’il fasse la paix avec moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Dorénavant Jacob prendra racine, Israël fleurira et poussera, et remplira de fruits la face du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'L’a-t-il frappé selon le coup de ceux qui l’ont frappé? A-t-il été tué selon la tuerie de ceux qu’il a tués?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'C’est avec mesure que tu as contesté avec elle, lorsque tu l’as renvoyée. Il l’ôta par son vent fort, au jour de [son] vent d’orient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'C’est pourquoi par cela est expiée l’iniquité de Jacob. Et ceci est tout le fruit de ce que son péché est ôté: quand il rendra toutes les pierres de l’autel comme des pierres calcaires désagrégées, les ashères et les colonnes consacrées au soleil ne se relèveront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Car la ville forte est solitaire, une demeure abandonnée et délaissée comme le désert; le veau y paîtra et y couchera, et en broutera les rameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Quand ses branches seront séchées, elles seront cassées; les femmes viendront et y mettront le feu. Car ce n’est pas un peuple qui ait de l’intelligence; c’est pourquoi celui qui l’a fait n’en aura pas compassion, et celui qui l’a formé n’usera pas de grâce envers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Et il arrivera en ce jour-là que l’ Éternel battra au fléau depuis le courant du fleuve jusqu’au torrent d’Égypte, et vous serez rassemblés un à un, fils d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Et il arrivera en ce jour-là qu’on sonnera de la grande trompette; et ceux qui périssaient dans le pays d’Assyrie, et les exilés du pays d’Égypte, viendront et se prosterneront devant l’ Éternel, en la montagne sainte, à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, '***Malheur à la couronne d’orgueil des ivrognes d’Éphraïm, et à la fleur flétrie de son bel ornement, qui est sur le sommet de la riche vallée de ceux qui sont vaincus par le vin!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Voici, le Seigneur a un [instrument] fort et puissant, comme un orage de grêle, un tourbillon de destruction: comme un orage de puissantes eaux qui débordent, il renversera par terre avec force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'La couronne d’orgueil des ivrognes d’Éphraïm sera foulée aux pieds,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'et la fleur flétrie de son bel ornement qui est sur le sommet de la riche vallée sera comme un fruit précoce avant l’été: dès que celui qui l’aperçoit l’a vu, à peine il est dans sa main, il l’avale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'En ce jour-là l’ Éternel des armées sera pour couronne de beauté et pour diadème d’ornement au résidu de son peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'et pour esprit de jugement à celui qui est assis pour juger, et pour force à ceux qui refoulent la guerre jusqu’à la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Mais ceux-ci aussi ont erré par le vin et se sont égarés par la boisson forte. Le sacrificateur et le prophète ont erré par la boisson forte, ils sont dévorés par le vin, ils se sont égarés par la boisson forte; ils ont erré dans [leur] vision, ils ont bronché dans le jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Car toutes les tables sont pleines de sales vomissements, de sorte qu’il n’y a plus de place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'À qui enseignera-t-il la connaissance? et à qui fera-t-il comprendre ce qui est annoncé? À ceux qui sont sevrés du lait, arrachés aux mamelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Car commandement sur commandement, commandement sur commandement; ligne sur ligne, ligne sur ligne; ici un peu, là un peu...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Car par des lèvres bégayantes et par une langue étrangère il parlera à ce peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'auquel il avait dit: C’est ici le repos, faites reposer celui qui est las; et c’est ici ce qui rafraîchit. Mais ils n’ont pas voulu entendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Et la parole de l’ Éternel leur a été commandement sur commandement, commandement sur commandement; ligne sur ligne, ligne sur ligne; ici un peu, là un peu; afin qu’ils marchent, et qu’ils tombent en arrière, et qu’ils soient brisés, et enlacés, et pris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'C’est pourquoi, écoutez la parole de l’ Éternel, hommes moqueurs, qui gouvernez ce peuple qui est à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Car vous avez dit: Nous avons fait une alliance avec la mort, et nous avons fait un pacte avec le shéol: si le fléau qui inonde passe, il n’arrivera pas jusqu’à nous; car nous avons fait du mensonge notre abri, et nous nous sommes cachés sous la fausseté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'C’est pourquoi ainsi dit le Seigneur, l’ Éternel: Voici, je pose comme fondement, en Sion, une pierre, une pierre éprouvée, une précieuse [pierre] de coin, un sûr fondement: celui qui se fie [à elle] ne se hâtera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Et j’ai mis le jugement pour cordeau, et la justice pour plomb, et la grêle balaiera l’abri de mensonge, et les eaux inonderont la retraite cachée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'et votre alliance avec la mort sera abolie, et votre pacte avec le shéol ne subsistera pas. Lorsque le fléau qui inonde passera, vous serez foulés par lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'dès qu’il passera, il vous prendra; car matin après matin il passera, de jour et de nuit, et ce ne sera qu’effroi d’en entendre la rumeur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'car le lit est trop court pour qu’on s’y allonge, et la couverture trop étroite quand on s’en enveloppe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Car l’ Éternel se lèvera comme en la montagne de Peratsim, il sera ému de colère comme dans la vallée de Gabaon, pour faire son œuvre, son œuvre étrange, et pour accomplir son travail, son travail inaccoutumé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Et maintenant ne soyez pas des moqueurs, de peur que vos liens ne soient renforcés; car j’ai entendu du Seigneur, l’ Éternel des armées, [qu’il y a] une consomption, et une [consomption] décrétée, sur toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Prêtez l’oreille, et écoutez ma voix; soyez attentifs, et écoutez ma parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Le laboureur laboure-t-il tout le jour pour semer? ouvre-t-il et herse-t-il [tout le jour] son terrain?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'N’est-ce pas que, lorsqu’il en a aplani la surface, il répand l’aneth, et sème le cumin, et met le froment par rangées, et l’orge au lieu désigné, et l’épeautre dans ses limites?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Son Dieu le dirige dans [son] jugement; il l’instruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Car il ne foule pas l’aneth avec un traîneau à tranchants et ne fait pas tourner la roue du chariot sur le cumin; car on bat l’aneth avec un bâton et le cumin avec une verge:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'il broie le blé pour le pain, parce qu’il ne veut pas le battre toujours; il ne le broie pas en chassant par-dessus la roue de son chariot et ses chevaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Cela aussi vient de l’ Éternel des armées: il se montre merveilleux en conseil et grand en sagesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, '*Malheur à Ariel, à Ariel, la cité où David demeura! Ajoutez année à année, que les fêtes se succèdent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'mais j’enserrerai Ariel; et il y aura soupir et gémissement; et elle me sera comme un Ariel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Et je camperai comme un cercle contre toi, et je t’assiégerai au moyen de postes [armés], et j’élèverai contre toi des forts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'et, humiliée, tu parleras depuis la terre, et ta parole sortira sourdement de la poussière, et ta voix, sortant de la terre, sera comme celle d’un évocateur d’esprits; et ta parole s’élèvera de la poussière comme un murmure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Et la multitude de tes ennemis sera comme une fine poussière, et la multitude des hommes terribles comme la balle menue qui passe; et [cela] arrivera en un moment, subitement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Tu seras visitée de par l’ Éternel des armées avec tonnerre et tremblement de terre et une grande voix, avec tourbillon et tempête, et une flamme de feu dévorant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Et la multitude de toutes les nations qui font la guerre à Ariel, et tous ceux qui combattent contre elle et contre ses remparts, et qui l’enserrent, seront comme un songe d’une vision de nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Et ce sera comme celui qui rêve ayant faim, et voici, il mange, et il se réveille, et son âme est vide, – et comme celui qui rêve ayant soif, et voici, il boit, et il se réveille, et voici, il est las et son âme est altérée: ainsi il arrivera à la multitude de toutes les nations qui font la guerre contre la montagne de Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Soyez étonnés et soyez stupéfaits! aveuglez-vous et soyez aveugles! Ils sont enivrés, mais non de vin; ils chancellent, mais non par la boisson forte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Car l’ Éternel a répandu sur vous un esprit de profond sommeil; il a bandé vos yeux; les prophètes et vos chefs, les voyants, il les a couverts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Et la vision de tout vous sera comme les paroles d’un livre scellé qu’on donne à quelqu’un qui sait lire, en disant: Lis ceci, je te prie; et il dit: Je ne puis, car il est scellé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'et on donne le livre à celui qui ne sait pas lire, en disant: Lis ceci, je te prie; et il dit: Je ne sais pas lire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Et le Seigneur dit: Parce que ce peuple s’approche de moi de sa bouche, et qu’ils m’honorent de leurs lèvres, et que leur cœur est éloigné de moi, et que leur crainte de moi est un commandement d’hommes enseigné,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'c’est pourquoi, voici, j’agirai encore merveilleusement, et je ferai une œuvre merveilleuse envers ce peuple: la sagesse de ses sages périra, et l’intelligence de ses intelligents se cachera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Malheur à ceux qui cachent profond, loin de l’ Éternel, [leur] conseil, et dont les actions sont dans les ténèbres, et qui disent: Qui nous voit, et qui nous connaît?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Vos perversités!... Le potier sera-t-il estimé comme l’argile, pour que la chose faite dise de celui qui l’a faite: Il ne m’a pas faite? et que ce qui est formé dise de celui qui l’a formé: Il n’a pas d’intelligence?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'N’y a-t-il pas encore très peu de temps, et le Liban sera converti en un champ fertile, et le champ fertile sera réputé une forêt?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Et en ce jour-là les sourds entendront les paroles du livre, et les yeux des aveugles, [délivrés] de l’obscurité et des ténèbres, verront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'et les débonnaires augmenteront leur joie en l’ Éternel, et les pauvres d’entre les hommes s’égaieront dans le Saint d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Car l’homme violent ne sera plus, et le moqueur aura pris fin; et tous ceux qui veillent pour l’iniquité seront retranchés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, '[ceux] qui tiennent un homme coupable pour un mot, qui tendent des pièges à ceux qui reprennent à la porte, et qui font fléchir [le droit] du juste par des choses futiles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'C’est pourquoi, ainsi dit à la maison de Jacob l’ Éternel qui racheta Abraham: Maintenant Jacob ne sera plus honteux, et maintenant sa face ne sera plus pâle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'car quand il verra ses enfants, l’œuvre de mes mains au milieu de lui, ils sanctifieront mon nom, et ils sanctifieront le Saint de Jacob, et ils craindront le Dieu d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'et ceux qui errent en esprit auront de l’intelligence, et les désobéissants apprendront la bonne doctrine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, '*Malheur aux fils qui se rebellent, dit l’ Éternel, pour former des desseins, mais non de par moi, et pour établir des alliances, mais non [par] mon Esprit, afin d’ajouter péché sur péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'qui s’en vont pour descendre en Égypte, et ils n’ont pas interrogé ma bouche, – afin de se réfugier sous la protection du Pharaon et de se confier en l’ombre de l’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Et la protection du Pharaon vous sera une honte, et votre confiance en l’ombre de l’Égypte, une ignominie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Car ses princes ont été à Tsoan, et ses messagers sont arrivés à Hanès;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'ils ont tous été honteux d’un peuple qui ne leur était d’aucun profit, ni à aide, ni à utilité, mais à honte et aussi à opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, '– L’oracle touchant les bêtes du midi: par un pays de détresse et d’angoisse, d’où [sortent] la lionne et le lion, la vipère et le serpent brûlant qui vole, ils portent sur le dos des ânes leurs richesses, et sur la bosse des chameaux leurs trésors, à un peuple qui ne leur sera d’aucun profit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Car l’Égypte aidera en vain et inutilement; c’est pourquoi je l’ai nommée: Arrogance qui ne fait rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Maintenant viens, écris-le sur une table devant eux, et inscris-le dans un livre (et ce sera pour le jour à venir, en témoignage à toujours),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'que c’est ici un peuple rebelle, – des fils menteurs, des fils qui ne veulent pas entendre la loi de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'qui disent aux voyants: Ne voyez pas, et à ceux qui ont des visions: N’ayez pas pour nous des visions de droiture; dites-nous des choses douces, voyez des tromperies;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'déviez du chemin, détournez-vous du sentier; ôtez de devant nous le Saint d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'C’est pourquoi, ainsi dit le Saint d’Israël: Parce que vous rejetez cette parole, et que vous vous confiez dans l’oppression et dans la perversité, et que vous vous appuyez dessus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'à cause de cela cette iniquité vous sera comme une brèche qui s’écroule, un renflement dans un mur élevé, dont la rupture arrive subitement, tout à coup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Et il le brisera comme on brise un vase de potier, qu’on casse sans ménagement: et, dans ses fragments, il ne se trouvera pas un tesson pour prendre du feu au foyer ou pour puiser de l’eau à la citerne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Car ainsi dit le Seigneur, l’ Éternel, le Saint d’Israël: C’est en revenant et en vous tenant en repos que vous serez sauvés; dans la tranquillité et dans la confiance sera votre force. Mais vous ne le voulez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Et vous avez dit: Non, car nous nous enfuirons sur des chevaux; c’est pourquoi vous vous enfuirez; et: Nous monterons sur des [chevaux] rapides; c’est pourquoi ceux qui vous poursuivent seront rapides.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Un millier [fuira] à la menace d’un seul; à la menace de cinq, vous fuirez, jusqu’à ce que vous restiez comme une perche au sommet d’une montagne et comme un étendard sur une colline.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Et c’est pourquoi l’ Éternel attendra pour user de grâce envers vous, et c’est pourquoi il s’élèvera haut pour avoir compassion de vous; car l’ Éternel est un Dieu de jugement: bienheureux tous ceux qui s’attendent à lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Car le peuple habitera en Sion, dans Jérusalem. Tu ne pleureras plus; à la voix de ton cri, il usera richement de grâce envers toi; aussitôt qu’il l’entendra, il te répondra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Et le Seigneur vous donnera le pain de la détresse et l’eau de l’oppression; mais ceux qui t’enseignent ne seront plus cachés, mais tes yeux verront ceux qui t’enseignent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'et, que vous alliez à droite ou que vous alliez à gauche, tes oreilles entendront une parole derrière toi, disant: C’est ici le chemin, marchez-y.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Et vous souillerez le plaqué d’argent de tes images taillées et le revêtement d’or de tes images de fonte; tu les jetteras loin comme un linge impur: Dehors! lui diras-tu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Et il donnera la pluie à ta semence dont tu ensemenceras le sol, et le pain, produit du sol; et il sera riche et nourrissant. Ton bétail paîtra en ce jour-là dans de vastes pâturages,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'et les bœufs et les ânes qui labourent le sol mangeront du fourrage salé qu’on a vanné avec la pelle et avec le van.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Et, sur toute haute montagne et sur toute colline élevée, il y aura des ruisseaux, des courants d’eau, au jour du grand carnage, quand les tours s’écrouleront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Et la lumière de la lune sera comme la lumière du soleil, et la lumière du soleil sera septuple, comme la lumière de sept jours, au jour où l’ Éternel bandera la brisure de son peuple et guérira la blessure de ses plaies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Voici, le nom de l’ Éternel vient de loin, brûlant de sa colère, un incendie véhément; ses lèvres sont pleines d’indignation, et sa langue est comme un feu qui dévore,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'et son haleine comme un torrent qui déborde, qui atteint jusqu’au cou, pour cribler les nations au crible de la vanité et [pour mettre] aux mâchoires des peuples un frein qui fait errer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Il y aura pour vous un chant comme dans la nuit où l’on sanctifie une fête, et une joie de cœur comme a celui qui va avec une flûte pour se rendre à la montagne de l’ Éternel, vers le rocher d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Et l’ Éternel fera entendre la majesté de sa voix, et montrera le poids de son bras, avec indignation de colère et flamme de feu dévorant, trombe d’eau, et tempête, et pierres de grêle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Car, par la voix de l’ Éternel, Assur sera renversé; il le frappera de sa verge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'et partout où passera le bâton ordonné que l’ Éternel appesantira sur lui, ce sera avec des tambourins et des harpes; et par des batailles tumultueuses il lui fera la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Car Topheth est préparé depuis longtemps: pour le roi aussi il est préparé. Il l’a fait profond et large; son bûcher est du feu et beaucoup de bois: le souffle de l’ Éternel, comme un torrent de soufre, l’allume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Malheur à ceux qui descendent en Égypte pour [avoir] du secours, [et] qui s’appuient sur des chevaux et se fient à des chars, parce qu’ils sont nombreux, et à des cavaliers, parce qu’ils sont très forts, et qui ne regardent pas au Saint d’Israël et ne recherchent pas l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Cependant lui aussi est sage, et il fait venir le malheur, et ne retire pas ses paroles; et il se lève contre la maison de ceux qui font le mal et contre le secours de ceux qui pratiquent l’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Et les Égyptiens sont des hommes et non pas ✶Dieu, et leurs chevaux sont chair et non pas esprit; et l’ Éternel étendra sa main, et celui qui aide trébuchera, et celui qui est aidé tombera, et tous ensemble ils périssent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Car ainsi m’a dit l’ Éternel: Comme le lion, le jeune lion, contre lequel une troupe de bergers est convoquée, rugit sur sa proie, ne s’effraie pas à leur voix, et ne cède pas devant leur multitude, ainsi l’ Éternel des armées descendra pour combattre sur la montagne de Sion et sur sa colline.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Comme des oiseaux qui déploient leurs ailes, ainsi l’ Éternel des armées couvrira Jérusalem: la protégeant, il la délivrera, et l’épargnant, il la sauvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Fils d’Israël, revenez à celui de qui vous vous êtes si profondément détournés!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Car en ce jour-là ils rejetteront chacun ses idoles d’argent et ses idoles d’or, que vos mains iniques ont faites pour vous-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Et Assur tombera par l’épée, non d’un homme d’importance; et l’épée, non d’un homme du commun, le dévorera: et il fuira devant l’épée, et ses jeunes hommes seront soumis au tribut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'et, de frayeur, il passera vers son rocher, et ses princes seront terrifiés à cause de l’étendard, dit l’ Éternel qui a son feu dans Sion et son four dans Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Voici, un roi régnera en justice, et des princes domineront avec droiture;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'et il y aura un homme [qui sera] comme une protection contre le vent et un abri contre l’orage, comme des ruisseaux d’eau dans un lieu sec, comme l’ombre d’un grand rocher dans un pays aride.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Et les yeux de ceux qui voient ne seront pas aveuglés, et les oreilles de ceux qui entendent écouteront,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'et le cœur de ceux qui vont étourdiment sera intelligent dans la connaissance, et la langue de ceux qui bégaient parlera promptement et clairement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'L’homme vil ne sera plus appelé noble, et on ne dira pas l’avare généreux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Car l’homme vil dira des choses viles, et son cœur commettra l’iniquité pour pratiquer l’impiété et pour dire l’erreur contre l’ Éternel, pour rendre vide l’âme qui a faim et ôter la boisson à celui qui a soif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Les armes de l’avare sont mauvaises; il trame des artifices pour détruire les débonnaires par des dires mensongers, même quand le pauvre parle droitement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Mais l’homme noble se propose des choses nobles, et il se maintiendra par des choses nobles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Levez-vous, femmes qui êtes à votre aise, écoutez ma voix; vous filles qui vivez en sécurité, prêtez l’oreille à ce que je dis:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Dans un an et des jours vous serez agitées, vous qui êtes en sécurité; car c’en est fait de la vendange, la récolte ne viendra pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Tremblez, vous femmes qui êtes à votre aise; soyez agitées, vous qui vivez en sécurité. Dépouillez-vous, et mettez-vous nues, et ceignez [le sac] sur vos reins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'On se frappe la poitrine à cause des champs agréables, à cause des vignes fertiles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Sur la terre de mon peuple croissent des épines et des ronces, même sur toutes les maisons de délices de la cité joyeuse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Car le palais est délaissé, le tumulte de la ville est abandonné. Ophel et la tour de la sentinelle seront des cavernes pour toujours, les délices des ânes sauvages, un pâturage des troupeaux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'jusqu’à ce que l’Esprit soit répandu d’en haut sur nous, et que le désert devienne un champ fertile, et que le champ fertile soit réputé une forêt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Et la droiture demeurera dans le désert, et la justice habitera le champ fertile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'et l’œuvre de la justice sera la paix, et le travail de la justice, repos et sécurité à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Et mon peuple habitera une demeure de paix et des habitations sûres, et des lieux de repos tranquilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Et la grêle tombera sur la forêt, et la ville sera abaissée dans un lieu bas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Bienheureux, vous qui semez près de toutes les eaux, envoyant [partout] le pied du bœuf et de l’âne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, '*Malheur à toi qui détruis, et tu n’as pas été détruit, et à toi qui agis perfidement, et on n’a pas agi perfidement envers toi! Quand tu auras fini de détruire, tu seras détruit; quand tu auras complété la perfidie, on agira perfidement envers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Éternel, use de grâce envers nous: nous nous sommes attendus à toi. Sois leur bras tous les matins, et notre salut au temps de la détresse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'À la voix du tumulte, les peuples s’enfuirent: quand tu t’es élevé, les nations ont été dispersées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Et votre butin sera moissonné, comme moissonnent les locustes; comme se précipitent les sauterelles, on se précipitera sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'L’ Éternel est exalté; car il demeure en haut, il a rempli Sion de droiture et de justice;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'et il sera la sûreté de tes temps, le trésor du salut, sagesse et connaissance. La crainte de l’ Éternel sera votre trésor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Voici, leurs vaillants hommes crient au-dehors, les messagers de la paix pleurent amèrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Les routes sont désertes; le passant sur le chemin a cessé. Il a rompu l’alliance, il a méprisé les villes, il n’a égard à personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Le pays mène deuil, il languit; le Liban est honteux, il s’est fané; le Saron est devenu comme un désert, et Basan et le Carmel se dépouillent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Maintenant, dit l’ Éternel, je me lèverai; maintenant je serai exalté; maintenant je m’élèverai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Vous concevrez l’herbe sèche, vous enfanterez le chaume: votre colère est un feu qui vous consumera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Et les peuples seront comme la pierre à chaux dans l’ardeur de la fournaise; comme des épines coupées, ils seront consumés dans le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Entendez, vous qui êtes loin, ce que j’ai fait; et connaissez ma puissance, vous qui êtes près!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Les pécheurs ont peur dans Sion; le tremblement a saisi les impies: Qui de nous séjournera dans le feu consumant? Qui de nous séjournera dans les flammes éternelles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, '– Celui qui marche dans la justice, et celui qui parle avec droiture, celui qui rejette le gain [acquis] par extorsion, qui secoue ses mains pour ne pas prendre de présent, qui bouche ses oreilles pour ne pas entendre parler de sang et qui ferme ses yeux pour ne pas voir le mal,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, '– celui-là demeurera en haut: les forteresses des rochers seront sa haute retraite; son pain lui sera donné, ses eaux seront assurées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Tes yeux verront le roi dans sa beauté; ils contempleront le pays lointain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Ton cœur méditera la crainte: Où est l’enregistreur? où est le peseur? où est celui qui compte les tours?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Tu ne verras plus le peuple audacieux, un peuple au langage trop obscur pour l’entendre, à la langue bégayante qu’on ne comprend pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Regarde Sion, la cité de nos assemblées solennelles! Tes yeux verront Jérusalem, une demeure tranquille, une tente qui ne sera pas transportée: ses pieux ne seront jamais arrachés, et aucune de ses cordes ne sera rompue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'mais là l’ Éternel est pour nous magnifique, – un lieu de fleuves, de larges rivières: il n’y viendra aucun vaisseau à rames, aucun noble navire n’y passera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Car l’ Éternel est notre juge, l’ Éternel est notre législateur, l’ Éternel est notre roi; lui, nous sauvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Tes cordages sont relâchés: ils n’affermissent pas le pied de leur mât, ils ne déploient pas la voile. On partage alors la proie d’un grand butin, les boiteux pillent les dépouilles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'et l’habitant ne dira pas: Je suis malade; l’iniquité du peuple qui demeure là sera pardonnée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, '*Approchez, nations, pour entendre; et vous, peuples, soyez attentifs! Que la terre écoute et tout ce qu’elle contient, le monde et tout ce qu’il produit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Car la colère de l’ Éternel est sur toutes les nations, et sa fureur sur toutes leurs armées. Il les a vouées à la destruction; il les a livrées au carnage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'et leurs tués seront jetés loin, et la puanteur de leurs cadavres s’élèvera; et les montagnes seront dissoutes par leur sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Et toute l’armée des cieux s’est fondue, et les cieux sont enroulés comme un livre, et toute leur armée est tombée comme une feuille tombe de la vigne, et comme ce qui tombe du figuier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Car mon épée sera enivrée dans les cieux: voici, elle descendra sur Édom et sur le peuple que j’ai voué à la destruction, pour le jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'L’épée de l’ Éternel est pleine de sang; elle est engraissée de graisse, du sang des agneaux et des boucs, de la graisse des rognons des béliers; car l’ Éternel a un sacrifice à Botsra, et une grande tuerie dans le pays d’Édom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Et les buffles descendront avec eux, et les jeunes bœufs avec les taureaux; et leur pays sera trempé de sang, et leur poussière sera engraissée de graisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Car c’est le jour de la vengeance de l’ Éternel, l’année des récompenses pour la cause de Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Et les rivières d’Édom seront changées en poix, et sa poussière en soufre, et son pays deviendra une poix brûlante;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'ni jour ni nuit elle ne sera éteinte, sa fumée montera à toujours; – de génération en génération il sera désert; à tout jamais personne n’y passera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'le pélican et le butor l’hériteront, et le hibou et le corbeau y habiteront. Et il étendra sur lui le cordeau de la désolation et les plombs du vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Ses nobles pour proclamer le royaume,... il n’y en a pas! Tous ses princes sont devenus néant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Des épines croîtront dans ses palais, des orties et des ronces dans ses forteresses; et il sera le repaire des chiens sauvages, le parc des autruches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Les bêtes du désert s’y rencontreront avec les chacals, et le bouc sauvage y criera à son compagnon. Là aussi la lilith se reposera et trouvera sa tranquille habitation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Là le serpent-dard fera son nid, et pondra, et fera éclore et rassemblera [ses petits] sous son ombre; là aussi se rassembleront les vautours l’un avec l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Cherchez dans le livre de l’ Éternel, et lisez. Pas un d’eux ne manquera; l’un n’aura pas à chercher l’autre; car ma bouche l’a commandé, et mon Esprit les a rassemblés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Et Lui a jeté le sort pour eux, et sa main leur a partagé le [pays] au cordeau: ils le posséderont pour toujours; ils y habiteront de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Le désert et la terre aride se réjouiront; le lieu stérile sera dans l’allégresse, et fleurira comme la rose;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'il fleurira abondamment, et il sera dans l’allégresse, oui, dans l’allégresse, et il exultera. La gloire du Liban lui sera donnée, la magnificence du Carmel et du Saron; ils verront la gloire de l’ Éternel, la magnificence de notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Fortifiez les mains lassées, et affermissez les genoux qui chancellent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Dites à ceux qui ont le cœur timide: Soyez forts, ne craignez pas; voici votre Dieu: la vengeance vient, la rétribution de Dieu! Lui-même viendra, et vous sauvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Alors les yeux des aveugles s’ouvriront, et les oreilles des sourds seront ouvertes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Alors le boiteux sautera comme le cerf, et la langue du muet chantera de joie. Car des eaux jailliront dans le désert, et des rivières dans le lieu stérile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'et le mirage deviendra un étang, et la terre aride, des sources d’eau; dans l’habitation des chacals où ils couchaient, il y aura un parc à roseaux et à joncs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Et il y aura là une grande route et un chemin, et il sera appelé le chemin de la sainteté: l’impur n’y passera pas, mais il sera pour ceux-là. Ceux qui vont [ce] chemin, même les insensés, ne s’égareront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Il n’y aura pas là de lion, et une bête qui déchire n’y montera pas [et] n’y sera pas trouvée; mais les rachetés y marcheront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Et ceux que l’ Éternel a délivrés retourneront et viendront à Sion avec des chants de triomphe; et une joie éternelle sera sur leur tête; ils obtiendront l’allégresse et la joie, et le chagrin et le gémissement s’enfuiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, '*** Et il arriva, la quatorzième année du roi Ézéchias, que Sankhérib, roi d’Assyrie, monta contre toutes les villes fortes de Juda et les prit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Et le roi d’Assyrie envoya le Rab-Shaké, de Lakis à Jérusalem, vers le roi Ézéchias, avec de grandes forces; et il se tint près de l’aqueduc de l’étang supérieur, sur la route du champ du foulon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Et Éliakim, fils de Hilkija, qui était [préposé] sur la maison [du roi], et Shebna, le scribe, et Joakh, fils d’Asaph, rédacteur des chroniques, sortirent vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Et le Rab-Shaké leur dit: Dites à Ézéchias: Ainsi dit le grand roi, le roi d’Assyrie: Quelle est cette confiance que tu as?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Tu dis (ce ne sont que paroles des lèvres): Le conseil et la force [sont là] pour la guerre. Maintenant, en qui te confies-tu que tu te révoltes contre moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Voici, tu te confies en ce bâton de roseau cassé, en l’Égypte, lequel, si quelqu’un s’appuie dessus, lui entre dans la main et la perce. Tel est le Pharaon, roi d’Égypte, pour tous ceux qui se confient en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Que si tu me dis: Nous nous confions en l’ Éternel, notre Dieu,... n’est-ce pas lui dont Ézéchias a ôté les hauts lieux et les autels, en disant à Juda et à Jérusalem: Vous vous prosternerez devant cet autel-ci?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Et maintenant, fais un accord, je te prie, avec le roi d’Assyrie, mon seigneur, et je te donnerai 2 000 chevaux si tu peux donner des cavaliers pour les monter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Et comment ferais-tu tourner visage à un seul capitaine d’entre les moindres serviteurs de mon seigneur? Et tu mets ta confiance en l’Égypte, pour des chars et des cavaliers...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Et maintenant, suis-je monté sans l’ Éternel contre ce pays pour le détruire? L’ Éternel m’a dit: Monte contre ce pays, et détruis-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Et Éliakim et Shebna et Joakh dirent au Rab-Shaké: Parle, nous te prions, à tes serviteurs en syriaque, car nous le comprenons, et ne nous parle pas en [langue] judaïque, aux oreilles du peuple qui est sur la muraille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Et le Rab-Shaké dit: Est-ce vers ton seigneur et vers toi que mon seigneur m’a envoyé pour dire ces paroles? N’est-ce pas vers les hommes qui se tiennent sur la muraille, pour manger leurs excréments et pour boire leur urine avec vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Et le Rab-Shaké se tint là et cria à haute voix en [langue] judaïque, et dit: Écoutez les paroles du grand roi, le roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Ainsi dit le roi: Qu’Ézéchias ne vous trompe point; car il ne pourra pas vous délivrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Et qu’Ézéchias ne vous fasse pas mettre votre confiance en l’ Éternel, disant: L’ Éternel nous délivrera certainement; cette ville ne sera point livrée en la main du roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'N’écoutez pas Ézéchias; car ainsi dit le roi d’Assyrie: Faites la paix avec moi, et sortez vers moi; et vous mangerez chacun de sa vigne et chacun de son figuier, et vous boirez chacun des eaux de son puits,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'jusqu’à ce que je vienne et que je vous emmène dans un pays comme votre pays, un pays de blé et de moût, un pays de pain et de vignes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Qu’Ézéchias ne vous séduise pas, disant: L’ Éternel nous délivrera. Les dieux des nations ont-ils délivré chacun son pays de la main du roi d’Assyrie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Où sont les dieux de Hamath et d’Arpad? Où sont les dieux de Sepharvaïm? Et ont-ils délivré Samarie de ma main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Quels sont d’entre tous les dieux de ces pays ceux qui ont délivré leur pays de ma main, pour que l’ Éternel délivre Jérusalem de ma main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Et ils se turent, et ne lui répondirent pas un mot; car c’était là le commandement du roi, disant: Vous ne lui répondrez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Et Éliakim, fils de Hilkija, qui était [préposé] sur la maison, et Shebna, le scribe, et Joakh, fils d’Asaph, rédacteur des chroniques, vinrent vers Ézéchias, leurs vêtements déchirés, et ils lui rapportèrent les paroles du Rab-Shaké.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Et il arriva, quand le roi Ézéchias eut entendu [ces choses], qu’il déchira ses vêtements, et se couvrit d’un sac, et entra dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Et il envoya Éliakim, qui était [préposé] sur la maison, et Shebna, le scribe, et les anciens des sacrificateurs, couverts de sacs, vers Ésaïe le prophète, fils d’Amots;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'et ils lui dirent: Ainsi dit Ézéchias: Ce jour est un jour de détresse, et de châtiment, et d’opprobre; car les enfants sont venus jusqu’à la naissance, et il n’y a point de force pour enfanter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Peut-être l’ Éternel, ton Dieu, entendra-t-il les paroles du Rab-Shaké, que le roi d’Assyrie, son seigneur, a envoyé pour outrager le Dieu vivant, et punira-t-il les paroles que l’ Éternel, ton Dieu, a entendues. Fais donc monter une prière pour le résidu qui se trouve [encore].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Et les serviteurs du roi Ézéchias vinrent vers Ésaïe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Et Ésaïe leur dit: Vous direz ainsi à votre seigneur: Ainsi dit l’ Éternel: Ne crains pas à cause des paroles que tu as entendues, par lesquelles les serviteurs du roi d’Assyrie m’ont blasphémé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Voici, je vais mettre en lui un esprit, et il entendra une nouvelle, et retournera dans son pays; et je le ferai tomber par l’épée dans son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Et le Rab-Shaké s’en retourna, et trouva le roi d’Assyrie faisant la guerre à Libna; car il avait appris qu’il était parti de Lakis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Et [le roi d’Assyrie] entendit dire touchant Tirhaka, roi d’Éthiopie: Il est sorti pour te faire la guerre. Lorsqu’il l’entendit, il envoya des messagers à Ézéchias, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Vous parlerez ainsi à Ézéchias, roi de Juda, disant: Que ton Dieu, en qui tu te confies, ne te trompe point, disant: Jérusalem ne sera pas livrée en la main du roi d’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Voici, tu as entendu ce que les rois d’Assyrie ont fait à tous les pays, les détruisant entièrement; et toi, tu serais délivré!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Est-ce que les dieux des nations, que mes pères ont détruites, les ont délivrées, Gozan, et Charan, et Rétseph, et les fils d’Éden qui étaient en Thelassar?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Où est le roi de Hamath, et le roi d’Arpad, et le roi de la ville de Sepharvaïm, d’Héna, et d’Ivva?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Et Ézéchias prit la lettre de la main des messagers, et la lut, et monta dans la maison de l’ Éternel; et Ézéchias la déploya devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Et Ézéchias pria l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Éternel des armées, Dieu d’Israël, qui es assis entre les chérubins, toi, le Même, toi seul tu es le Dieu de tous les royaumes de la terre; toi, tu as fait les cieux et la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Éternel! incline ton oreille et écoute. Éternel! ouvre tes yeux, et vois; et écoute toutes les paroles de Sankhérib, qui a envoyé pour outrager le Dieu vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Il est vrai, Éternel! les rois d’Assyrie ont dévasté tous les pays et leurs terres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'et ont jeté au feu leurs dieux; car ce n’étaient pas des dieux, mais l’ouvrage de mains d’homme, – du bois, et de la pierre; et ils les ont détruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Et maintenant, Éternel, notre Dieu! sauve-nous de sa main, afin que tous les royaumes de la terre sachent que toi seul tu es l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Et Ésaïe, fils d’Amots, envoya vers Ézéchias, disant: Ainsi dit l’ Éternel, le Dieu d’Israël: Quant à la prière que tu m’as faite au sujet de Sankhérib, roi d’Assyrie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'c’est ici la parole que l’ Éternel a prononcée contre lui: La vierge, fille de Sion, te méprise, elle se moque de toi; la fille de Jérusalem secoue la tête après toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Qui as-tu outragé et blasphémé? Et contre qui as-tu élevé la voix? C’est contre le Saint d’Israël que tu as levé tes yeux en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Par tes serviteurs, tu as outragé le Seigneur, et tu as dit: Avec la multitude de mes chars j’ai gravi le haut des montagnes, les parties reculées du Liban, et je couperai ses hauts cèdres, l’élite de ses cyprès, et je parviendrai jusqu’à sa dernière cime, à la forêt de son Carmel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'J’ai creusé, et j’ai bu de l’eau; et j’ai desséché avec la plante de mes pieds tous les fleuves de Matsor...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'N’as-tu pas entendu que j’ai fait cela dès longtemps, et que je l’ai formé dès les jours d’autrefois? Maintenant je l’ai fait arriver, pour que tu réduises en monceaux de ruines des villes fortes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Et leurs habitants ont été sans force, ils ont été terrifiés, et ont été couverts de honte; ils ont été [comme] l’herbe des champs et l’herbe verte, [comme] l’herbe des toits et la récolte flétrie avant qu’elle soit en tige.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Mais je sais ton habitation, et ta sortie et ton entrée, et ta rage contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Parce que tu es plein de rage contre moi, et que ton insolence est montée à mes oreilles, je mettrai mon anneau à ton nez et mon frein entre tes lèvres, et je te ferai retourner par le chemin par lequel tu es venu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Et ceci en sera le signe pour toi: on mangera cette année ce qui lève des grains tombés, et la seconde année ce qui croît de soi-même; et la troisième année, vous sèmerez et vous moissonnerez, et vous planterez des vignes et vous en mangerez le fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Et ce qui est réchappé et demeuré de reste de la maison de Juda, poussera encore des racines en bas et produira du fruit en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Car de Jérusalem sortira un résidu, et de la montagne de Sion ce qui est réchappé. La jalousie de l’ Éternel des armées fera cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'C’est pourquoi, ainsi dit l’ Éternel touchant le roi d’Assyrie: Il n’entrera pas dans cette ville, et il n’y lancera point de flèche; il ne lui présentera pas le bouclier, et il n’élèvera point de terrasse contre elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Il s’en retournera par le chemin par lequel il est venu, et il n’entrera pas dans cette ville, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Et je protégerai cette ville, afin de la sauver, à cause de moi, et à cause de David, mon serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Et un ange de l’ Éternel sortit, et frappa dans le camp des Assyriens 185 000 [hommes]; et quand on se leva le matin, voici, c’étaient tous des corps morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Et Sankhérib, roi d’Assyrie, partit et s’en alla et s’en retourna, et habita à Ninive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Et il arriva, comme il se prosternait dans la maison de Nisroc, son dieu, qu’Adrammélec et Sharétser, ses fils, le frappèrent avec l’épée; et ils se sauvèrent dans le pays d’Ararat; et Ésar-Haddon, son fils, régna à sa place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, '*En ces jours-là, Ézéchias fut malade à la mort; et Ésaïe le prophète, fils d’Amots, vint vers lui, et lui dit: Ainsi dit l’ Éternel: Donne des ordres pour ta maison, car tu vas mourir et tu ne vivras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Et Ézéchias tourna sa face contre la muraille, et pria l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Et il dit: Hélas, Éternel! souviens-toi, je te prie, que j’ai marché devant toi en vérité et avec un cœur parfait, et que j’ai fait ce qui est bon à tes yeux. Et Ézéchias versa beaucoup de larmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Et la parole de l’ Éternel vint à Ésaïe, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Va, et dis à Ézéchias: Ainsi dit l’ Éternel, Dieu de David, ton père: J’ai entendu ta prière, j’ai vu tes larmes; voici, j’ajouterai 15 années à tes jours,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'et je te délivrerai, toi et cette ville, de la main du roi d’Assyrie, et je protégerai cette ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Et ceci en sera le signe pour toi, de par l’ Éternel, car l’ Éternel accomplira cette parole qu’il a prononcée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Voici, je ferai retourner en arrière, de dix degrés, l’ombre des degrés qui est descendue sur le cadran d’Achaz, par le soleil. Et le soleil retourna sur le cadran de dix degrés, dont il était descendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Écrit d’Ézéchias, roi de Juda, quand, ayant été malade, il fut rétabli de sa maladie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Moi, je disais: Au méridien de mes jours j’irai dans les portes du shéol; je suis privé du reste de mes années.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Je disais: Je ne verrai pas Jah, Jah dans la terre des vivants! Avec les habitants du lieu où tout a cessé, je ne contemplerai plus l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Ma durée s’en est allée, et elle est transportée loin de moi comme une tente de berger. J’ai, comme le tisserand, coupé ma vie;... il me séparera de la penne; du jour à la nuit, tu en auras fini avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'J’ai possédé mon âme jusqu’au matin;... comme un lion, ainsi il me brisait tous les os. Du jour à la nuit, tu en auras fini avec moi!...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Comme une hirondelle, comme une grue, ainsi je grommelais, je gémissais comme une colombe; mes yeux se sont consumés [en regardant] en haut. Seigneur, je suis opprimé; garantis-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Que dirai-je? Il m’a parlé, et lui l’a fait. J’irai doucement, toutes mes années, dans l’amertume de mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Seigneur, par ces choses on vit, et en toutes ces choses est la vie de mon esprit. Et tu m’as rendu la santé, et tu m’as fait vivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Voici, au lieu de la paix j’avais amertume sur amertume; mais toi, tu as aimé mon âme, [la retirant] de la fosse de destruction, car tu as jeté tous mes péchés derrière ton dos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Car ce n’est pas le shéol qui te louera, [ni] la mort qui te célébrera; ceux qui descendent dans la fosse ne s’attendent plus à ta vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Le vivant, le vivant est celui qui te louera, comme moi aujourd’hui; le père fera connaître aux fils ta vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'L’ Éternel a voulu me sauver! Et nous jouerons de mes instruments à cordes tous les jours de notre vie, dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Et Ésaïe avait dit: Qu’on prenne une masse de figues, et qu’on la mette comme emplâtre sur l’ulcère; et il se rétablira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Et Ézéchias avait dit: Quel est le signe que je monterai à la maison de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, '*En ce temps-là, Merodac-Baladan, fils de Baladan, roi de Babylone, envoya une lettre et un présent à Ézéchias; or il avait appris qu’il avait été malade, et qu’il était rétabli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Et Ézéchias se réjouit [de leur venue], et leur montra la maison [où étaient renfermés] ses objets précieux, l’argent et l’or, et les aromates et l’huile fine, et tout son arsenal, et tout ce qui se trouvait dans ses trésors; il n’y eut rien qu’Ézéchias ne leur montrât dans sa maison et dans tous ses domaines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Et Ésaïe le prophète vint vers le roi Ézéchias, et lui dit: Qu’ont dit ces hommes, et d’où sont-ils venus vers toi? Et Ézéchias dit: Ils sont venus vers moi d’un pays éloigné, de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Et [Ésaïe] dit: Qu’ont-ils vu dans ta maison? Et Ézéchias dit: Ils ont vu tout ce qui est dans ma maison; il n’y a rien dans mes trésors que je ne leur aie montré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Et Ésaïe dit à Ézéchias: Écoute la parole de l’ Éternel des armées:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Voici, des jours viennent où tout ce qui est dans ta maison, et ce que tes pères ont amassé jusqu’à ce jour, sera porté à Babylone; il n’en restera rien, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Et on prendra de tes fils, qui sortiront de toi, que tu auras engendrés, et ils seront eunuques dans le palais du roi de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Et Ézéchias dit à Ésaïe: La parole de l’ Éternel, que tu as prononcée, est bonne. Puis il dit: Car il y aura paix et stabilité pendant mes jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, '***Consolez, consolez mon peuple, dit votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Parlez au cœur de Jérusalem, et criez-lui que son temps de détresse est accompli, que son iniquité est acquittée; qu’elle a reçu de la main de l’ Éternel le double pour tous ses péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'La voix de celui qui crie dans le désert: Préparez le chemin de l’ Éternel, aplanissez dans le lieu stérile une route pour notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Toute vallée sera relevée, et toute montagne et [toute] colline seront abaissées; et ce qui est tortu sera rendu droit, et les lieux raboteux deviendront une plaine unie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Et la gloire de l’ Éternel sera révélée, et toute chair ensemble la verra; car la bouche de l’ Éternel a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Une voix dit: Crie. Et il dit: Que crierai-je? – Toute chair est de l’herbe, et toute sa beauté comme la fleur des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'L’herbe est desséchée, la fleur est fanée; car le souffle de l’ Éternel a soufflé dessus. Certes, le peuple est de l’herbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'L’herbe est desséchée, la fleur est fanée, mais la parole de notre Dieu demeure à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Sion, messagère de bonnes nouvelles, monte sur une haute montagne; élève ta voix avec force, Jérusalem, messagère de bonnes nouvelles: élève-la, ne crains point; dis aux villes de Juda: Voici votre Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Voici, le Seigneur l’ Éternel viendra avec puissance, et son bras dominera pour lui. Voici, son salaire est avec lui, et sa récompense devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Comme un berger il paîtra son troupeau; par son bras il rassemblera les agneaux et les portera dans son sein; il conduira doucement celles qui allaitent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Qui a mesuré les eaux dans le creux de sa main, et réglé les cieux avec l’empan, et mesuré dans un boisseau la poussière de la terre? Qui a pesé les montagnes au crochet, ou les collines dans la balance?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Qui a dirigé l’Esprit de l’ Éternel, et l’a instruit comme l’homme de son conseil?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Avec qui a-t-il tenu conseil, et [qui] lui a donné de l’intelligence, et l’a instruit dans le sentier du juste jugement, et lui a enseigné la connaissance, et lui a fait connaître le chemin de l’intelligence?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Voici, les nations sont réputées comme une goutte d’un seau, et comme la poussière d’une balance; voici, il enlève les îles comme un atome.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Et le Liban ne suffit pas pour le feu, et ses bêtes ne suffisent pas pour l’holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Toutes les nations sont comme un rien devant lui; elles sont réputées par lui comme moins que le néant et le vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'À qui donc comparerez-vous ✶Dieu, et à quelle ressemblance l’égalerez-vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'L’ouvrier fond une image, et l’orfèvre étend l’or dessus et lui fond des chaînes d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Celui qui est trop pauvre pour [faire] une offrande choisit un bois qui ne pourrisse pas; il se cherche un habile ouvrier pour établir une image taillée qui ne branle pas. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Ne savez-vous pas? Ne l’avez-vous pas entendu? Cela ne vous a-t-il pas été déclaré dès le commencement? N’avez-vous pas compris la fondation de la terre?...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Lui, qui est assis au-dessus du cercle de la terre, et ses habitants sont comme des sauterelles, – qui étend les cieux comme une toile légère, et qui les déploie comme une tente pour y habiter;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'qui réduit ses chefs à néant, qui fait que les juges de la terre sont comme rien:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'ils ne seront pas même plantés, ils ne seront pas même semés, leur tige ne sera même pas enracinée dans la terre, qu’il soufflera sur eux, et ils seront desséchés, et le tourbillon les enlèvera comme du chaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'À qui donc me comparerez-vous et serai-je égalé? dit le Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Levez vos yeux en haut, et voyez! Qui a créé ces choses, faisant sortir par nombre leur armée? Il les appelle toutes par nom. Par la grandeur de son pouvoir et de sa force puissante, pas une ne manque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Pourquoi dis-tu, ô Jacob, et parles-tu, ô Israël: Ma voie est cachée à l’ Éternel, et ma cause a passé inaperçue de mon Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Ne sais-tu pas, n’as-tu pas entendu, que le Dieu d’éternité, l’ Éternel, créateur des bouts de la terre, ne se lasse pas et ne se fatigue pas? On ne sonde pas son intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Il donne de la force à celui qui est las, et il augmente l’énergie à celui qui n’a pas de vigueur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Les jeunes gens seront las et se fatigueront, et les jeunes hommes deviendront chancelants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'mais ceux qui s’attendent à l’ Éternel renouvelleront leur force; ils s’élèveront avec des ailes, comme des aigles; ils courront et ne se fatigueront pas, ils marcheront et ne se lasseront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Faites silence devant moi, îles; et que les peuples renouvellent leur force! Qu’ils s’approchent;... alors, qu’ils parlent! Approchons ensemble en jugement!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Qui, du levant, réveilla [celui] dont la justice accompagne les pas? Il livra les nations devant lui, et lui soumit les rois; il les livra à son épée comme de la poussière, et à son arc comme du chaume chassé [par le vent].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Il les poursuivit; il passa en sûreté par un chemin où il n’était pas allé de ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Qui a opéré et fait [cela], appelant les générations dès le commencement? Moi, l’ Éternel, le premier; et, avec les derniers, je suis le Même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Les îles le virent et eurent peur, les bouts de la terre tremblèrent: ils s’approchèrent et vinrent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'ils s’entraidèrent l’un l’autre, et [chacun] dit à son frère: Sois fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Et l’ouvrier fortifiait le fondeur; celui qui polit au marteau [fortifiait] celui qui frappe sur l’enclume, disant de la soudure: Elle est bonne;... et il l’a affermi avec des clous, afin qu’il ne branle pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Et toi, Israël, mon serviteur, Jacob, que j’ai choisi, semence d’Abraham mon ami,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'toi que j’ai pris des bouts de la terre et appelé de ses extrémités, et à qui j’ai dit: Tu es mon serviteur, je t’ai choisi et je ne t’ai pas rejeté;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'ne crains point, car je suis avec toi; ne sois pas inquiet, car moi je suis ton Dieu. Je te fortifierai; oui, je t’aiderai; oui, je te soutiendrai par la droite de ma justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Voici, tous ceux qui s’irritent contre toi, seront honteux et confondus; ils seront comme un rien, et les hommes qui contestent contre toi périront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Tu les chercheras, et tu ne les trouveras pas, les hommes qui ont querelle avec toi; ils seront comme un rien et comme néant, les hommes qui te font la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Car moi, l’ Éternel, ton Dieu, je tiens ta droite, [moi] qui te dis: Ne crains point, moi je t’aiderai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Ne crains point, toi Jacob, vermisseau! [et vous], hommes d’Israël! Moi je t’aiderai, dit l’ Éternel, et ton rédempteur, le Saint d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Voici, j’ai fait de toi un traîneau à battre, tranchant, neuf, à doubles dents: tu battras les montagnes et tu les réduiras en poussière, et tu rendras les collines comme de la balle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'tu les vanneras, et le vent les emportera, et le tourbillon les dispersera; et toi, tu t’égaieras en l’ Éternel, tu te glorifieras dans le Saint d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Les affligés et les nécessiteux chercheront de l’eau, et il n’y en a pas, leur langue est desséchée par la soif: moi, l’ Éternel, je leur répondrai, [moi], le Dieu d’Israël, je ne les abandonnerai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Je ferai couler des rivières sur les hauteurs, et des fontaines au milieu des vallées; je changerai le désert en un étang d’eau, et la terre aride en des sources jaillissantes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Je ferai croître dans le désert le cèdre, l’acacia, et le myrte, et l’olivier; je mettrai dans le lieu stérile le cyprès, le pin et le buis ensemble;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'afin qu’ils voient, et qu’ils sachent, et qu’ils considèrent, et qu’ils comprennent tous ensemble, que la main de l’ Éternel a fait cela, et que le Saint d’Israël l’a créé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Produisez votre cause, dit l’ Éternel; apportez ici vos arguments, dit le roi de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Qu’ils les apportent, et qu’ils nous déclarent ce qui arrivera. Déclarez les premières choses, ce qu’elles sont, afin que nous [y] fassions attention, et que nous en connaissions le résultat; ou faites-nous savoir celles qui viendront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, '– déclarez les choses qui vont arriver dans la suite, et nous saurons que vous êtes des dieux; oui, faites du bien et faites du mal, afin que nous le considérions et le voyions ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Voici, vous êtes moins que rien, et votre œuvre est du néant: qui vous choisit est une abomination...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Je l’ai réveillé du nord, et il vient, – du lever du soleil, celui qui invoquera mon nom. Et il marchera sur les princes comme sur de la boue, et comme le potier foule l’argile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Qui l’a déclaré dès le commencement, afin que nous le sachions, et d’avance, afin que nous disions: C’est juste? Non, il n’y a personne qui le déclare; non, personne qui le fasse entendre; non, personne qui entende vos paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Le premier, [j’ai dit] à Sion: Voici, les voici! et à Jérusalem: Je donnerai un messager de bonnes nouvelles!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Et j’ai regardé, et il n’y avait personne – même parmi eux – et point de conseiller, pour leur demander, et avoir d’eux une réponse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Voici, tous sont la vanité, leurs œuvres sont un néant, leurs images de fonte sont le vent et le vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Voici mon serviteur que je soutiens, mon élu [en qui] mon âme trouve son plaisir. Je mettrai mon Esprit sur lui; il fera valoir le jugement à l’égard des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Il ne criera pas, et il n’élèvera pas sa voix, et il ne la fera pas entendre dans la rue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Il ne brisera pas le roseau froissé, et n’éteindra pas le lin qui brûle à peine. Il fera valoir le jugement en faveur de la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Il ne se lassera pas, et il ne se hâtera pas, jusqu’à ce qu’il ait établi le juste jugement sur la terre; et les îles s’attendront à sa loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Ainsi dit ✶Dieu, l’ Éternel, qui a créé les cieux et les a déployés, qui a étendu la terre et ses produits, qui donne la respiration au peuple [qui est] sur elle, et un esprit à ceux qui y marchent:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Moi, l’ Éternel, je t’ai appelé en justice; et je tiendrai ta main; et je te garderai; et je te donnerai pour [être] une alliance du peuple, pour [être] une lumière des nations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'pour ouvrir les yeux aveugles, pour faire sortir de la prison le prisonnier, [et] du cachot ceux qui sont assis dans les ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Je suis l’ Éternel: c’est là mon nom; et je ne donnerai pas ma gloire à un autre, ni ma louange à des images taillées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Voici, les premières choses sont arrivées, et je déclare les choses nouvelles: avant qu’elles germent, je vous les ferai entendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Chantez à l’ Éternel un cantique nouveau, sa louange du bout de la terre, vous qui descendez sur la mer, et ce qui la remplit, les îles et ceux qui les habitent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Que le désert et ses villes élèvent [la voix], les villages qu’habite Kédar! Que les habitants du rocher exultent! Que du haut des montagnes on jette des cris!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Qu’on donne gloire à l’ Éternel, et qu’on déclare sa louange dans les îles!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'L’ Éternel sortira comme un homme vaillant, il éveillera la jalousie comme un homme de guerre; il criera, oui, il jettera des cris; contre ses ennemis il se montrera vaillant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Dès longtemps je suis resté tranquille, je me suis tu, je me suis contenu. Je crierai comme une femme qui enfante, je soufflerai et je serai haletant à la fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Je dévasterai les montagnes et les collines, et je dessécherai toute leur verdure; je changerai les rivières en îles, et je mettrai à sec les étangs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'et je ferai marcher les aveugles par un chemin qu’ils n’ont pas connu, par des sentiers qu’ils n’ont pas connus je les conduirai. Je changerai les ténèbres en lumière devant eux, et les chemins tortueux en ce qui est droit. Je leur ferai ces choses, et je ne les abandonnerai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Ils se retireront en arrière, ils seront couverts de honte, ceux qui mettent leur confiance en une image taillée, qui disent à une image de fonte: Vous êtes nos dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Écoutez, sourds, et vous, aveugles, regardez pour voir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Qui est aveugle, si ce n’est mon serviteur, et sourd, comme mon messager que j’ai envoyé? Qui est aveugle comme celui en qui je me confie, et aveugle comme le serviteur de l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'pour voir bien des choses et ne pas y faire attention? Les oreilles ouvertes, il n’entend pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'L’ Éternel a pris plaisir [en lui] à cause de sa justice: il a rendu la loi grande et honorable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Mais c’est ici un peuple pillé et dépouillé; ils sont tous liés dans des fosses, et ils sont cachés dans des prisons; ils sont devenus un butin, et il n’y a personne qui délivre, – une proie, et il n’y a personne qui dise: Restitue!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Qui parmi vous prêtera l’oreille à cela? Qui fera attention, et écoutera ce qui est à venir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Qui a livré Jacob pour être une proie, et Israël à ceux qui le pillent? N’est-ce pas l’ Éternel, celui contre qui nous avons péché? Et ils n’ont pas voulu marcher dans ses voies, et ils n’ont pas écouté sa loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'et il a versé sur lui l’ardeur de sa colère et la force de la guerre: et elle l’a embrasé de tous côtés, et il ne l’a pas su; et elle l’a brûlé, et il ne l’a pas pris à cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Mais maintenant, ainsi dit l’ Éternel, qui t’a créé, ô Jacob, et qui t’a formé, ô Israël: Ne crains point, car je t’ai racheté; je t’ai appelé par ton nom, tu es à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Quand tu passeras par les eaux, je serai avec toi, et par les rivières, elles ne te submergeront pas; quand tu marcheras dans le feu, tu ne seras pas brûlé, et la flamme ne te consumera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Car moi, je suis l’ Éternel, ton Dieu, le Saint d’Israël, ton sauveur. J’ai donné l’Égypte pour ta rançon, Cush et Seba pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Depuis que tu es devenu précieux à mes yeux, tu as été glorieux, et moi, je t’ai aimé; et je donnerai des hommes pour toi et des peuples pour ta vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Ne crains pas, car je suis avec toi. Je ferai venir du levant ta semence, et je te rassemblerai du couchant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'je dirai au nord: Donne, et au midi: Ne retiens pas; amène mes fils de loin, et mes filles du bout de la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'chacun qui est appelé de mon nom, et que j’ai créé pour ma gloire, que j’ai formé, oui, que j’ai fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Fais sortir le peuple aveugle qui a des yeux, et les sourds qui ont des oreilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Que toutes les nations soient réunies ensemble, et que les peuples se rassemblent! Qui d’entre eux a déclaré cela, et nous a fait entendre les choses précédentes? Qu’ils produisent leurs témoins et qu’ils se justifient, ou qu’ils entendent, et disent: C’est la vérité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Vous êtes mes témoins, dit l’ Éternel, [vous] et mon serviteur que j’ai choisi, afin que vous connaissiez, et que vous me croyiez, et que vous compreniez que moi je suis le Même: avant moi aucun ✶Dieu n’a été formé, et après moi il n’y en aura pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Moi, moi, je suis l’ Éternel, et hors moi il n’y en a point qui sauve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Moi, j’ai déclaré, et j’ai sauvé, et j’ai fait entendre, quand il n’y avait pas de [dieu] étranger au milieu de vous; et vous êtes mes témoins, dit l’ Éternel, que je suis ✶Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Aussi, depuis qu’il y a un jour, je suis le Même, et il n’y a personne qui délivre de ma main: j’opérerai, et qui peut [m’en] détourner?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Ainsi dit l’ Éternel, votre rédempteur, le Saint d’Israël: À cause de vous j’ai envoyé à Babylone, et je les ai fait descendre tous comme des fugitifs, même les Chaldéens, dans les vaisseaux où s’entend leur cri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Moi, je suis l’ Éternel, votre Saint, le créateur d’Israël, votre roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Ainsi dit l’ Éternel, qui donne un chemin dans la mer et un sentier dans les eaux puissantes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'qui fait sortir le char et le cheval, l’armée et les forts, – ils sont couchés ensemble, ils ne se lèveront pas; ils finissent, éteints comme une mèche:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Ne vous souvenez pas des choses précédentes, et ne considérez pas les choses anciennes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Voici, je fais une chose nouvelle; maintenant elle va germer: ne la connaîtrez-vous pas? Oui, je mettrai un chemin dans le désert, des rivières dans le lieu désolé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'La bête des champs me glorifiera, les chacals et les autruches; car j’ai donné des eaux dans le désert, des rivières dans le lieu désolé, pour abreuver mon peuple, mon élu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'J’ai formé ce peuple pour moi-même; ils raconteront ma louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Mais tu ne m’as pas invoqué, ô Jacob; car tu as été las de moi, ô Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Tu ne m’as pas apporté le menu bétail de tes holocaustes, et tu ne m’as pas glorifié par tes sacrifices. Je ne t’ai pas asservi à des offrandes de gâteau, et je ne t’ai pas fatigué pour l’encens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Tu n’as pas acheté pour moi du roseau aromatique pour de l’argent, et tu ne m’as pas rassasié de la graisse de tes sacrifices; mais tu m’as asservi par tes péchés, tu m’as fatigué par tes iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, '– C’est moi, c’est moi qui efface tes transgressions à cause de moi-même; et je ne me souviendrai pas de tes péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Fais-moi souvenir, plaidons ensemble; raconte toi-même, afin que tu sois justifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Ton premier père a péché, et tes médiateurs se sont rebellés contre moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'et j’ai profané les chefs du lieu saint, et j’ai livré Jacob à la destruction et Israël à l’opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Et maintenant écoute, Jacob, mon serviteur, et toi, Israël, que j’ai choisi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Ainsi dit l’ Éternel, qui t’a fait et formé dès la matrice, celui qui t’aide: Ne crains pas, mon serviteur Jacob, et toi, Jeshurun, que j’ai choisi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Car je verserai de l’eau sur celui qui a soif, et des ruisseaux d’eau sur la terre sèche; je verserai mon Esprit sur ta semence, et ma bénédiction sur ceux qui sortent de toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'et ils germeront parmi l’herbe, comme les saules auprès des courants d’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Celui-ci dira: Moi, je suis à l’ Éternel; et celui-là s’appellera du nom de Jacob; et celui-là écrira de sa main: Je suis à l’ Éternel, et se nommera du nom d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Ainsi dit l’ Éternel, le roi d’Israël, et son rédempteur, l’ Éternel des armées: Je suis le premier, et je suis le dernier; et hors moi il n’y a pas de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Et qui, comme moi, appellera, – et qui le déclarera, et l’arrangera pour moi, depuis que j’ai établi le peuple ancien? Qu’ils leur déclarent les choses qui arriveront et celles qui viendront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'N’ayez pas peur, et ne craignez pas. Ne te l’ai-je pas, dès ce temps-là, fait entendre et déclaré? et vous m’en êtes les témoins. Y a-t-il un ✝Dieu hors moi? Il n’y a pas de rocher, je n’en connais point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Ceux qui forment une image taillée sont tous un néant, et leurs choses désirables ne sont d’aucun profit; et ils en sont eux-mêmes les témoins: ils ne voient pas, et ils ne connaissent pas, afin qu’ils soient honteux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Qui a formé un ✶dieu, ou fondu une image, qui n’est d’aucun profit?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Voici, tous ses compagnons seront honteux, et les ouvriers ne sont que des hommes. Qu’ils s’assemblent tous, qu’ils se tiennent là! Qu’ils aient peur, qu’ils aient honte ensemble!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'L’ouvrier en fer [a] un ciseau, et il travaille avec des charbons; il forme l’image avec des marteaux, et la travaille avec son bras vigoureux; mais il a faim et il n’a pas de force; il n’a pas bu d’eau, et il est las.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Le sculpteur en bois étend un cordeau; il trace sa forme avec de la craie rouge, il la fait avec des outils tranchants, et la trace avec un compas, et la fait selon la figure d’un homme, selon la beauté de l’homme, pour qu’elle demeure dans la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Il se coupe des cèdres, et il prend un rouvre et un chêne; il choisit parmi les arbres de la forêt. Il plante un pin, et la pluie le fait croître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Et un homme l’aura pour en faire du feu, et il en prend et s’en chauffe; il l’allume aussi, et cuit du pain; il en fait aussi un ✶dieu, et l’adore; il en fait une image taillée, et se prosterne devant elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Il en brûle la moitié au feu; avec la moitié il mange de la chair, il cuit un rôti, et il est rassasié; il a chaud aussi, et dit: Ha, ha! je me chauffe, je vois le feu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Et avec le reste il fait un ✶dieu, son image taillée: il se prosterne devant elle et l’adore, et lui adresse sa prière, et dit: Délivre-moi, car tu es mon ✶dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Ils n’ont pas de connaissance et ne comprennent pas; car Il a couvert d’un enduit leurs yeux, en sorte qu’ils ne voient pas, [et] leurs cœurs, en sorte qu’ils ne comprennent pas. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Et on ne rentre pas en soi-même, et il n’y a pas de connaissance, et il n’y a pas d’intelligence, pour dire: J’en ai brûlé la moitié au feu, et encore, j’ai cuit du pain sur ses charbons, j’ai rôti de la chair, et j’ai mangé; et de ce qui reste, en ferai-je une abomination? Me prosternerai-je devant ce qui provient d’un arbre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Il se repaît de cendres; un cœur abusé l’a détourné; et il ne délivre pas son âme, et ne dit pas: N’ai-je pas un mensonge dans ma main droite?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Souviens-toi de ces choses, ô Jacob, et toi, Israël, car tu es mon serviteur. Je t’ai formé; tu es mon serviteur, Israël; tu ne seras pas oublié de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'J’ai effacé comme un nuage épais tes transgressions, et comme une nuée tes péchés: reviens à moi, car je t’ai racheté. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Exultez, cieux, car l’ Éternel l’a fait; jetez des cris, vous, profondeurs de la terre; éclatez en chants de triomphe, montagnes, forêts, et tous les arbres qui y sont! Car l’ Éternel a racheté Jacob, et s’est glorifié en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Ainsi dit l’ Éternel, ton rédempteur, et celui qui t’a formé dès la matrice: C’est moi, l’ Éternel, qui ai fait toutes choses, qui seul ai déployé les cieux, et qui, par moi-même, ai étendu la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'qui rends vains les signes des menteurs et qui trouble l’esprit des devins, qui fais retourner en arrière les sages et qui fais de leur connaissance une folie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'qui confirme la parole de mon serviteur et accomplis le conseil de mes messagers; qui dis à Jérusalem: Tu seras habitée, et aux villes de Juda: Vous serez bâties, et je relèverai ses ruines;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, '[moi] qui dis à l’abîme: Sois sec, et je dessécherai tes fleuves;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'qui dis de Cyrus: [Il est] mon berger, et il accomplira tout mon bon plaisir, disant à Jérusalem: Tu seras bâtie, et au temple: Tes fondements seront posés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Ainsi dit l’ Éternel à son oint, à Cyrus, dont j’ai tenu la droite pour soumettre devant lui des nations;... et je délierai les reins des rois, pour ouvrir les deux battants devant lui afin que les portes ne soient pas fermées:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Moi, j’irai devant toi, et j’aplanirai les choses élevées; je briserai les portes d’airain, et je casserai les barres de fer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'et je te donnerai les trésors des ténèbres et les richesses des lieux cachés; afin que tu saches que moi, l’ Éternel, qui t’ai appelé par ton nom, je suis le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'À cause de mon serviteur Jacob, et d’Israël, mon élu, je t’ai appelé par ton nom, je t’ai donné un nom, et tu ne me connaissais pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Moi, je suis l’ Éternel, et il n’y en a point d’autre; il n’y a point de Dieu si ce n’est moi. Je t’ai ceint, et tu ne me connaissais pas;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'afin qu’ils sachent, depuis le lever du soleil et depuis le couchant, qu’il n’y en a point hors moi. Moi, je suis l’ Éternel, et il n’y en a pas d’autre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, '– [moi] qui ai formé la lumière et qui ai créé les ténèbres; qui fais la prospérité, et qui crée le malheur: moi, l’ Éternel, je fais toutes ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Cieux, distillez d’en haut, et que les nuages fassent ruisseler la justice; que la terre s’ouvre, et que, à la fois, le salut se produise et la justice germe! Moi, l’ Éternel, je l’ai créé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Malheur à celui qui conteste avec celui qui l’a formé! Qu’un tesson [conteste] avec des tessons de la terre...! L’argile dira-t-elle à celui qui la forme: Que fais-tu? – et ton œuvre: Il n’a pas de mains?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Malheur à celui qui dit à son père: Qu’as-tu engendré? et à sa mère: Qu’as-tu enfanté?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Ainsi dit l’ Éternel, le Saint d’Israël, et celui qui l’a formé: Enquérez-vous de moi touchant les choses à venir; commandez-moi à l’égard de mes fils et à l’égard de l’œuvre de mes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Moi, j’ai fait la terre, et j’ai créé l’homme sur elle; c’est moi, ce sont mes mains qui ont étendu les cieux, et j’ai ordonné toute leur armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Moi, je l’ai suscité en justice, et je rendrai droites toutes ses voies: lui, bâtira ma ville, et renverra libres mes captifs, sans prix et sans présent, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Ainsi dit l’ Éternel: Le travail de l’Égypte et le gain de l’Éthiopie et des Sabéens, hommes de haute taille, passeront vers toi et seront à toi. Ils marcheront après toi; ils passeront enchaînés, et se prosterneront devant toi; ils te supplieront, [disant]: Certainement ✶Dieu est au milieu de toi; il n’y en a pas d’autre, point d’autre Dieu ...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Certes, tu es un ✶Dieu qui te caches, le Dieu d’Israël, le sauveur...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Ils auront honte, et seront aussi tous confus; ils s’en iront ensemble avec confusion, les fabricateurs d’idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Israël sera sauvé par l’ Éternel d’un salut éternel; vous n’aurez pas honte et vous ne serez pas confus, aux siècles des siècles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Car ainsi dit l’ Éternel qui a créé les cieux, le Dieu qui a formé la terre et qui l’a faite, celui qui l’a établie, qui ne l’a pas créée [pour être] vide, qui l’a formée pour être habitée: Moi, je suis l’ Éternel, et il n’y en a point d’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Je n’ai pas parlé en secret, dans un lieu ténébreux de la terre; je n’ai pas dit à la semence de Jacob: Cherchez-moi en vain. Je suis l’ Éternel parlant justice, déclarant ce qui est droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Rassemblez-vous et venez, approchez-vous ensemble, réchappés des nations! – Ils n’ont point de connaissance, ceux qui portent le bois de leur image taillée et présentent leur supplication à un ✶dieu qui ne sauve pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, '– Déclarez, et faites-[les] approcher! Oui, qu’ensemble ils consultent! Qui a fait entendre cela d’ancienneté? Qui l’a déclaré dès longtemps? N’est-ce pas moi, l’ Éternel? Et hors moi il n’y a pas de Dieu; – de ✶Dieu juste et sauveur, il n’y en a point si ce n’est moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Tournez-vous vers moi, et soyez sauvés, vous, tous les bouts de la terre; car moi, je suis ✶Dieu, et il n’y en a pas d’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'J’ai juré par moi-même, la parole est sortie de ma bouche [en] justice, et ne reviendra pas, que devant moi tout genou se ploiera, [par moi] toute langue jurera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'En l’ Éternel seul, dira-t-on, j’ai justice et force. C’est à lui qu’on viendra, et tous ceux qui s’irritent contre lui auront honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'En l’ Éternel sera justifiée et se glorifiera toute la semence d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel s’est affaissé, Nebo se courbe; leurs idoles ont été [mises] sur les animaux et sur le bétail: celles que vous portiez sont chargées, – un fardeau pour la [bête] lassée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Ils se sont courbés, ils se sont affaissés ensemble; ils n’ont pas pu sauver leur fardeau: eux-mêmes sont allés en captivité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Écoutez-moi, maison de Jacob, et vous, tout le résidu de la maison d’Israël, vous qui avez été chargés dès le ventre, [et] qui avez été portés dès la matrice:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Jusqu’à votre vieillesse je suis le Même, et jusqu’aux cheveux blancs, je vous porterai. Moi, je l’ai fait; moi, je porterai, et moi, je chargerai sur moi, et je délivrerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'À qui me comparerez-vous et m’égalerez-vous ou m’assimilerez-vous, pour que nous soyons semblables?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, '– Ils prodiguent l’or de la bourse, et pèsent l’argent à la balance; ils louent un orfèvre pour qu’il en fasse un ✶dieu: ils se prosternent, oui, ils l’adorent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'ils le chargent sur l’épaule, ils le portent, et le posent à sa place; et il se tient debout, il ne quitte pas sa place; on crie bien à lui, mais il ne répond pas, il ne les sauve pas de leur détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Souvenez-vous de cela, et montrez-vous hommes; rappelez-le à votre esprit, transgresseurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Souvenez-vous des premières choses de jadis. Car moi, je suis ✶Dieu, et il n’y en a pas d’autre; [je suis] Dieu, et il n’y en a point comme moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'déclarant dès le commencement ce qui sera à la fin, et d’ancienneté ce qui n’a pas été fait, disant: Mon conseil s’accomplira, et je ferai tout mon bon plaisir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'appelant du levant un oiseau de proie, d’un pays lointain l’homme de mon conseil. Oui, je l’ai dit, et je ferai que cela arrivera; je me le suis proposé, et je l’effectuerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Écoutez-moi, vous au cœur dur, qui êtes éloignés de la justice!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'J’ai fait approcher ma justice; elle ne sera pas éloignée, et mon salut ne tardera pas; et je mets en Sion le salut, [et] sur Israël ma gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Descends, et assieds-toi dans la poussière, vierge, fille de Babylone; assieds-toi par terre, il n’y a pas de trône, fille des Chaldéens; car tu ne seras plus appelée tendre et délicate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Prends les meules et mouds de la farine; ôte ton voile, relève ta robe, découvre ta jambe, traverse les fleuves:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'ta nudité sera découverte; oui, ta honte sera vue. Je tirerai vengeance, et je ne rencontrerai personne [qui m’arrête]...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Notre rédempteur, son nom est l’ Éternel des armées, le Saint d’Israël...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Assieds-toi dans le silence, et entre dans les ténèbres, fille des Chaldéens; car tu ne seras plus appelée maîtresse des royaumes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'J’ai été courroucé contre mon peuple, j’ai profané mon héritage, et je les ai livrés en ta main: tu n’as usé d’aucune miséricorde envers eux; sur l’ancien tu as fort appesanti ton joug;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'et tu as dit: Je serai maîtresse pour toujours,... jusqu’à ne point prendre ces choses à cœur: tu ne t’es pas souvenue de ce qui en serait la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Et maintenant, écoute ceci, voluptueuse, qui habites en sécurité, qui dis en ton cœur: C’est moi, et il n’y en a pas d’autre; je ne serai pas assise en veuve, et je ne saurai pas ce que c’est que d’être privée d’enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Ces deux choses t’arriveront en un instant, en un seul jour, la privation d’enfants et le veuvage; elles viendront sur toi en plein, malgré la multitude de tes sorcelleries, malgré le grand nombre de tes sortilèges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Et tu as eu confiance en ton iniquité; tu as dit: Personne ne me voit. Ta sagesse et ta connaissance, c’est ce qui t’a fait errer; et tu as dit en ton cœur: C’est moi, et il n’y en a pas d’autre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Mais un mal viendra sur toi, dont tu ne connaîtras pas l’aube; et un malheur tombera sur toi, que tu ne pourras pas éviter, et une désolation que tu n’as pas soupçonnée viendra sur toi subitement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Tiens-toi là avec tes sortilèges, et avec la multitude de tes sorcelleries, dont tu t’es fatiguée dès ta jeunesse; peut-être pourras-tu en tirer profit, peut-être effraieras-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Tu es devenue lasse par la multitude de tes conseils. Qu’ils se tiennent là et te sauvent, les interprétateurs des cieux, les observateurs des étoiles, ceux qui, d’après les nouvelles lunes, donnent la connaissance des choses qui viendront sur toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Voici, ils seront comme du chaume, le feu les brûlera; ils ne délivreront pas leur âme de la force de la flamme: il ne [restera] ni charbon pour se chauffer, ni feu pour s’asseoir devant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Ainsi seront pour toi ceux avec lesquels tu t’es lassée, avec lesquels tu as trafiqué dès ta jeunesse. Ils erreront chacun de son côté; il n’y a personne qui te sauve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Écoutez ceci, maison de Jacob, vous qui êtes appelés du nom d’Israël et qui sortez des eaux de Juda, qui jurez par le nom de l’ Éternel, et faites mention du Dieu d’Israël, [mais] non pas en vérité ni en justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Car ils se nomment d’après la ville sainte, et s’appuient sur le Dieu d’Israël: l’ Éternel des armées est son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'J’ai déclaré les premières choses dès longtemps, et elles sont sorties de ma bouche et je les ai fait entendre; je les ai faites subitement, et elles sont arrivées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Parce que je savais que tu es obstiné, et que ton cou est une barre de fer, et ton front, d’airain,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'je te les ai déclarées dès longtemps; avant qu’elles arrivent je te les ai fait entendre, de peur que tu ne dises: Mon idole les a faites; et mon image taillée ou mon image de fonte les a ordonnées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Tu les as entendues, vois-les tout entières. Et vous, ne voulez-vous pas les déclarer? Je t’ai fait entendre des choses nouvelles, dès maintenant, et des choses cachées et que tu n’as pas connues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Elles sont créées maintenant, et non dès longtemps; et avant ce jour tu ne les as pas entendues, de peur que tu ne dises: Voici, je les savais!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Et tu n’as pas entendu, et tu n’as pas su, et dès longtemps ton oreille ne s’est pas ouverte; car je [te] connais: tu agis toujours perfidement, et tu as été appelé transgresseur dès la matrice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'À cause de mon nom je différerai ma colère, et à cause de ma louange je me retiendrai à ton égard, pour ne pas te retrancher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Voici, je te purifierai, mais non comme de l’argent: je t’ai choisi au creuset de l’affliction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'À cause de moi-même, à cause de moi-même, je [le] ferai; car comment [mon nom] serait-il profané? Et je ne donnerai pas ma gloire à un autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Écoute-moi, Jacob, et toi, Israël, que j’ai appelé. Moi, je suis le Même, – moi, le premier, et moi, le dernier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Ma main aussi a fondé la terre, et ma droite a étendu les cieux; moi je les appelle: ils se tiennent là ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Rassemblez-vous, vous tous, et écoutez. Qui d’entre eux a déclaré ces choses? Celui que l’ Éternel a aimé exécutera son bon plaisir sur Babylone, et son bras [sera sur] les Chaldéens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Moi, moi j’ai parlé, moi je l’ai aussi appelé; je l’ai fait venir, et son chemin prospérera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Approchez-vous de moi, écoutez ceci: Je n’ai pas parlé en secret dès le commencement; dès le temps où cela a existé, je suis là; et maintenant le Seigneur l’ Éternel m’a envoyé, et son Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Ainsi dit l’ Éternel, ton rédempteur, le Saint d’Israël: Moi, je suis l’ Éternel, ton Dieu, qui t’enseigne pour ton profit, qui te dirige dans le chemin [par lequel] tu dois marcher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Oh! si tu avais fait attention à mes commandements, ta paix aurait été comme un fleuve, et ta justice comme les flots de la mer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'et ta semence aurait été comme le sable, et ceux qui sortent de tes entrailles, comme le gravier de la mer: son nom n’aurait pas été retranché ni détruit de devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Sortez de Babylone, fuyez du milieu des Chaldéens, avec une voix de chant de joie! Déclarez et faites entendre ceci, portez-le jusqu’au bout de la terre; dites: L’ Éternel a racheté son serviteur Jacob!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Et ils n’ont pas eu soif, quand il les fit marcher dans les déserts; du rocher il a fait jaillir pour eux les eaux; il a fendu le rocher, et les eaux ont coulé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Il n’y a pas de paix, dit l’ Éternel, pour les méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, '**Écoutez-moi, îles, et soyez attentives, peuplades lointaines! L’ Éternel m’a appelé dès le ventre; dès les entrailles de ma mère il a fait mention de mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Et il a rendu ma bouche semblable à une épée aiguë; il m’a caché sous l’ombre de sa main, et il a fait de moi une flèche polie; il m’a caché dans son carquois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Et il m’a dit: Tu es mon serviteur, Israël, en qui je me glorifierai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, '– Et moi j’ai dit: J’ai travaillé en vain, j’ai consumé ma force pour le néant et en vain; toutefois mon jugement est par-devers l’ Éternel, et mon œuvre par-devers mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Et maintenant, dit l’ Éternel, qui m’a formé dès le ventre pour lui être serviteur afin de lui ramener Jacob...; quoique Israël ne soit pas rassemblé, je serai glorifié aux yeux de l’ Éternel, et mon Dieu sera ma force...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Et il [me] dit: C’est peu de chose que tu me sois serviteur pour rétablir les tribus de Jacob et pour ramener les préservés d’Israël; je te donnerai aussi pour [être] une lumière des nations, pour être mon salut jusqu’au bout de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Ainsi dit l’ Éternel, le rédempteur d’Israël, son Saint, à celui que l’homme méprise, à celui que la nation abhorre, au serviteur de ceux qui dominent: Des rois verront, et se lèveront, – des princes, et ils se prosterneront, à cause de l’ Éternel qui est fidèle, du Saint d’Israël qui te choisira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Ainsi dit l’ Éternel: En un temps agréé je t’ai répondu, et au jour du salut je t’ai secouru; et je te garderai, et je te donnerai pour [être] une alliance du peuple, pour rétablir le pays, pour faire hériter les héritages dévastés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'disant aux prisonniers: Sortez! à ceux qui sont dans les ténèbres: Paraissez! Ils paîtront sur les chemins, et sur toutes les hauteurs seront leurs pâturages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Ils n’auront pas faim, et ils n’auront pas soif, la chaleur et le soleil ne les frapperont pas; car celui qui a compassion d’eux les conduira et les mènera à des sources d’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Et je ferai de toutes mes montagnes un chemin, et mes grandes routes seront élevées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Voici, ceux-ci viendront de loin; et voici, ceux-là, du nord et de l’ouest, et ceux-ci, du pays de Sinim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Exultez, cieux, et égaie-toi, terre! Montagnes, éclatez en chants de triomphe! Car l’ Éternel console son peuple et fera miséricorde à ses affligés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Mais Sion a dit: L’ Éternel m’a abandonnée, et le Seigneur m’a oubliée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Une femme oubliera-t-elle son nourrisson, pour ne pas avoir compassion du fruit de son ventre? Même celles-là oublieront;... mais moi, je ne t’oublierai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Voici, je t’ai gravée sur les paumes de mes mains; tes murs sont continuellement devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Tes fils se hâteront; ceux qui te détruisaient et ceux qui te dévastaient sortiront d’avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Lève autour de toi tes yeux, et regarde: ils se rassemblent tous, ils viennent vers toi. Je suis vivant, dit l’ Éternel, que tu te revêtiras d’eux tous comme d’un ornement, et que tu t’en ceindras comme une fiancée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Car [dans] tes lieux déserts et tes contrées désolées et ton pays détruit, tu seras maintenant à l’étroit à cause des habitants, et ceux qui te dévoraient seront loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Les fils que tu as eus quand tu étais privée d’enfants diront encore à tes oreilles: Le lieu est trop étroit pour moi; fais-moi place, afin que j’y habite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Et tu diras en ton cœur: Qui m’a enfanté ceux-ci? Et moi, j’étais privée d’enfants et abandonnée, captive et chassée; et ceux-ci, qui les a élevés? Voici, moi j’étais laissée seule, – ceux-ci, où étaient-ils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Ainsi dit le Seigneur, l’ Éternel: Voici, je lèverai ma main devant les nations, et j’élèverai mon étendard devant les peuples; et ils apporteront tes fils sur [leurs] bras, et tes filles seront portées sur [leurs] épaules;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'et des rois seront tes nourriciers, et leurs princesses, tes nourrices; ils se prosterneront devant toi le visage contre terre, et ils lécheront la poussière de tes pieds; et tu sauras que moi je suis l’ Éternel: ceux qui s’attendent à moi ne seront pas confus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Ce qu’il a pris sera-t-il enlevé à l’homme fort, et celui qui est justement captif sera-t-il délivré?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Car ainsi dit l’ Éternel: Même le captif de l’homme fort [lui] sera enlevé, et ce qui a été pris par l’[homme] puissant sera délivré; et moi je contesterai avec celui qui conteste avec toi, et je sauverai tes fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Et je donnerai à ceux qui t’oppriment leur propre chair à manger, et ils s’enivreront de leur sang comme avec du moût; et toute chair saura que je suis l’ Éternel, ton sauveur, et ton rédempteur, le Puissant de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Ainsi dit l’ Éternel: Où est la lettre de divorce de votre mère que j’ai renvoyée? Ou, qui est celui de mes créanciers auquel je vous ai vendus? Voici, vous vous êtes vendus par vos iniquités, et à cause de vos transgressions votre mère a été renvoyée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Pourquoi suis-je venu, et il n’y a eu personne? [Pourquoi] ai-je appelé, et il n’y a eu personne qui réponde? Ma main est-elle devenue trop courte pour que je puisse racheter, et n’y a-t-il pas de force en moi pour délivrer? Voici, par ma réprimande je dessèche la mer, je fais des rivières un désert; leurs poissons deviennent puants, faute d’eau, et meurent de soif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Je revêts les cieux de noirceur, et je leur donne un sac pour couverture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Le Seigneur l’ Éternel m’a donné la langue des savants, pour que je sache soutenir par une parole celui qui est las. Il [me] réveille chaque matin, il réveille mon oreille pour que j’écoute comme ceux qu’on enseigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Le Seigneur l’ Éternel m’a ouvert l’oreille, et moi je n’ai pas été rebelle, je ne me suis pas retiré en arrière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'J’ai donné mon dos à ceux qui frappaient, et mes joues à ceux qui arrachaient le poil; je n’ai pas caché ma face à l’opprobre et aux crachats.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Mais le Seigneur l’ Éternel m’aidera: c’est pourquoi je ne serai pas confondu; c’est pourquoi j’ai dressé ma face comme un caillou, et je sais que je ne serai pas confus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Celui qui me justifie est proche: qui contestera avec moi? – tenons-nous là ensemble. Qui plaidera contre moi en jugement? – qu’il s’approche de moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Voici, le Seigneur l’ Éternel m’aidera: qui me condamnera? Voici, ils vieilliront tous comme un vêtement, la teigne les dévorera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Qui d’entre vous craint l’ Éternel, qui entend la voix de son serviteur, quiconque marche dans les ténèbres et n’a pas de lumière, qu’il se confie dans le nom de l’ Éternel et s’appuie sur son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Voici, vous tous qui allumez un feu, qui vous entourez d’étincelles, marchez à la lumière de votre feu et des étincelles que vous avez allumées; c’est ici ce que vous aurez de ma main: vous coucherez dans la douleur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Écoutez-moi, vous qui poursuivez la justice, qui cherchez l’ Éternel! Regardez au rocher d’où vous avez été taillés, et au creux du puits d’où vous avez été tirés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Regardez à Abraham, votre père, et à Sara, qui vous a enfantés; car je l’ai appelé seul, et je l’ai béni, et je l’ai multiplié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Car l’ Éternel consolera Sion; il consolera tous ses lieux arides, et fera de son désert un Éden, et de son lieu stérile, comme le jardin de l’ Éternel. L’allégresse et la joie y seront trouvées, des actions de grâces et une voix de cantiques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Prête-moi attention, mon peuple, et prête-moi l’oreille, ma nation! Car une loi sortira d’auprès de moi, et j’établirai mon jugement pour une lumière des peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Ma justice est proche, mon salut est sorti, et mes bras jugeront les peuples; les îles s’attendront à moi et auront leur attente en mon bras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Élevez vos yeux vers les cieux, et regardez vers la terre, en bas; car les cieux s’évanouiront comme la fumée, et la terre vieillira comme un vêtement, et ceux qui y habitent mourront également; mais mon salut sera à toujours, et ma justice ne défaillira pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Écoutez-moi, vous qui connaissez la justice, peuple dans le cœur duquel est ma loi: Ne craignez pas l’opprobre de [la part de] l’homme, et ne soyez pas effrayés de leurs outrages;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'car la teigne les rongera comme un vêtement, et le ver les rongera comme de la laine; mais ma justice sera à toujours, et mon salut, de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Réveille-toi, réveille-toi, revêts-toi de force, bras de l’ Éternel! Réveille-toi, comme aux jours d’autrefois, [comme dans] les générations des siècles passés! N’est-ce pas toi qui as taillé en pièces Rahab, qui as frappé le monstre [des eaux]?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'N’est-ce pas toi qui desséchas la mer, les eaux du grand abîme? qui fis des profondeurs de la mer un chemin pour le passage des rachetés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Et ceux que l’ Éternel a délivrés retourneront et viendront à Sion avec des chants de triomphe; et une joie éternelle sera sur leur tête; ils obtiendront l’allégresse et la joie; le chagrin et le gémissement s’enfuiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'C’est moi, c’est moi qui vous console! Qui es-tu, que tu craignes un homme qui mourra, et un fils d’homme qui deviendra comme l’herbe,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'et que tu oublies l’ Éternel qui t’a fait, qui a étendu les cieux et fondé la terre, et que tu trembles continuellement tout le jour devant la fureur de l’oppresseur, lorsqu’il se prépare à détruire? Et où est la fureur de l’oppresseur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Celui qui est courbé [sous les chaînes] sera bientôt mis en liberté, et il ne mourra pas dans la fosse et ne sera pas privé de son pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Mais moi, je suis l’ Éternel, ton Dieu, qui soulève la mer, et ses flots mugissent: l’ Éternel des armées est son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Et j’ai mis mes paroles dans ta bouche, et je t’ai couvert de l’ombre de ma main, pour établir les cieux, et pour fonder la terre, et pour dire à Sion: Tu es mon peuple!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Réveille-toi, réveille-toi, lève-toi, Jérusalem, qui as bu de la main de l’ Éternel la coupe de sa fureur, qui as bu, qui as vidé jusqu’au fond le calice de la coupe d’étourdissement!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'De tous les fils qu’elle a enfantés il n’y en a pas un qui la conduise, et de tous les fils qu’elle a élevés il n’y en a pas un qui la prenne par la main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Ces deux [choses] te sont arrivées, – qui te plaindra? – la dévastation et la ruine, et la famine et l’épée: par qui te consolerai-je?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Tes fils ont langui, ils sont couchés au coin de toutes les rues comme un bœuf sauvage dans un rets; ils sont remplis de la fureur de l’ Éternel, de la répréhension de ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'C’est pourquoi, écoute ceci, toi qui es affligée et ivre, mais non de vin:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Ainsi dit ton Seigneur, l’ Éternel, et ton Dieu qui plaide la cause de son peuple: Voici, je prends de ta main la coupe d’étourdissement, le calice de la coupe de ma fureur; tu n’en boiras plus désormais;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'et je la mets dans la main de ceux qui t’affligent, qui ont dit à ton âme: Courbe-toi, afin que nous passions; et tu as mis ton corps comme le sol, et comme une rue pour les passants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Réveille-toi, réveille-toi, revêts-toi de ta force, Sion! Revêts-toi de tes vêtements de parure, Jérusalem, ville sainte! car l’incirconcis et l’impur n’entreront plus en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Secoue de toi la poussière, lève-toi, assieds-toi, Jérusalem; délivre-toi des chaînes de ton cou, captive, fille de Sion!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Car ainsi dit l’ Éternel: Vous vous êtes vendus pour rien, et vous serez rachetés sans argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Car ainsi dit le Seigneur, l’ Éternel: Mon peuple est descendu en Égypte, au commencement, pour y séjourner, et l’Assyrie l’a opprimé sans cause:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'et maintenant, qu’ai-je [à faire] ici, dit l’ Éternel, que mon peuple ait été enlevé gratuitement? Ceux qui dominent sur lui le font hurler, dit l’ Éternel, et mon nom est continuellement blasphémé tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'C’est pourquoi mon peuple connaîtra mon nom; c’est pourquoi, en ce jour-là, [il connaîtra] que c’est moi-même, qui dis: Me voici!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Combien sont beaux sur les montagnes les pieds de celui qui apporte de bonnes nouvelles, qui annonce la paix, qui apporte des nouvelles de bonheur, qui annonce le salut, qui dit à Sion: Ton Dieu règne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'La voix de tes sentinelles! – elles élèvent la voix, elles exultent ensemble avec chant de triomphe; car elles verront face à face, quand l’ Éternel restaurera Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Éclatez de joie, exultez ensemble, lieux déserts de Jérusalem; car l’ Éternel console son peuple; il a racheté Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'L’ Éternel a mis à nu le bras de sa sainteté aux yeux de toutes les nations; et tous les bouts de la terre verront le salut de notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, '– Partez, partez; sortez de là; ne touchez pas à ce qui est impur! Sortez du milieu d’elle, soyez purs, vous qui portez les vases de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Car vous ne sortirez pas avec précipitation et vous n’irez pas comme des fugitifs; car l’ Éternel ira devant vous, et le Dieu d’Israël sera votre arrière-garde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, '*Voici, mon serviteur agira sagement; il sera exalté et élevé, et [placé] très haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Comme beaucoup ont été stupéfaits en te voyant, – tellement son visage était défait plus que celui d’aucun homme, et sa forme, plus que celle d’aucun fils d’homme, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'ainsi il fera tressaillir d’étonnement beaucoup de nations; des rois fermeront leur bouche en le voyant; car ils verront ce qui ne leur avait pas été raconté, et ils considéreront ce qu’ils n’avaient pas entendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Qui a cru à ce que nous avons fait entendre, et à qui le bras de l’ Éternel a-t-il été révélé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Il montera devant lui comme un rejeton, et comme une racine [sortant] d’une terre aride. Il n’a ni forme, ni éclat; quand nous le voyons, il n’y a point d’apparence [en lui] pour nous le faire désirer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Il est méprisé et délaissé des hommes, homme de douleurs, et sachant ce que c’est que la langueur, et comme quelqu’un de qui on cache sa face; il est méprisé, et nous n’avons eu pour lui aucune estime.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Certainement, lui, a porté nos langueurs, et s’est chargé de nos douleurs; et nous, nous l’avons estimé battu, frappé de Dieu, et affligé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'mais il a été blessé pour nos transgressions, il a été meurtri pour nos iniquités; le châtiment de notre paix a été sur lui, et par ses meurtrissures nous sommes guéris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Nous avons tous été errants comme des brebis, nous nous sommes tournés chacun vers son propre chemin, et l’ Éternel a fait tomber sur lui l’iniquité de nous tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Il a été opprimé et affligé, et il n’a pas ouvert sa bouche. Il a été amené comme un agneau à la boucherie, et a été comme une brebis muette devant ceux qui la tondent; et il n’a pas ouvert sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Il est ôté de l’angoisse et du jugement; et sa génération, qui la racontera? Car il a été retranché de la terre des vivants; à cause de la transgression de mon peuple, lui, a été frappé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Et on lui donna son sépulcre avec les méchants; mais il a été avec le riche dans sa mort, parce qu’il n’avait fait aucune violence, et qu’il n’y avait pas de fraude dans sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Mais il plut à l’ Éternel de le meurtrir; il l’a soumis à la souffrance. S’il livre son âme en sacrifice pour le péché, il verra une semence; il prolongera ses jours, et le plaisir de l’ Éternel prospérera en sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Il verra [du fruit] du travail de son âme, [et] sera satisfait. Par sa connaissance mon serviteur juste enseignera la justice à plusieurs, et lui, il portera leurs iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'C’est pourquoi je lui assignerai une part avec les grands, et il partagera le butin avec les forts, parce qu’il aura livré son âme à la mort, et qu’il aura été compté parmi les transgresseurs, et qu’il a porté le péché de plusieurs, et qu’il a intercédé pour les transgresseurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, '*Exulte, stérile, qui n’enfantais pas; éclate en chants de triomphe, et pousse des cris de joie, toi qui n’as pas été en travail! car les fils de la désolée sont plus nombreux que les fils de la femme mariée, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Élargis le lieu de ta tente, et qu’on étende les tentures de tes tabernacles; n’épargne pas, allonge tes cordages et affermis tes pieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Car tu t’étendras à droite et à gauche, et ta semence possédera les nations et fera que les villes désolées seront habitées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Ne crains pas, car tu ne seras pas honteuse; et ne sois pas confuse, car tu n’auras pas à rougir; car tu oublieras la honte de ta jeunesse, et tu ne te souviendras plus de l’opprobre de ton veuvage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Car celui qui t’a faite est ton mari; son nom est l’ Éternel des armées, et ton rédempteur, le Saint d’Israël: il sera appelé Dieu de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Car l’ Éternel t’a appelée comme une femme délaissée et affligée d’esprit, et une épouse de la jeunesse [et] qu’on a méprisée, dit ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Pour un petit moment je t’ai abandonnée, mais avec de grandes compassions je te rassemblerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Dans l’effusion de la colère, je t’ai caché ma face pour un moment; mais avec une bonté éternelle j’aurai compassion de toi, dit ton rédempteur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Car ceci m’est [comme] les eaux de Noé, lorsque je jurai que les eaux de Noé ne passeraient plus sur la terre: ainsi j’ai juré que je ne serais plus courroucé contre toi, et que je ne te tancerais plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Car les montagnes se retireraient et les collines seraient ébranlées, que ma bonté ne se retirerait pas d’avec toi, et que mon alliance de paix ne serait pas ébranlée, dit l’ Éternel, qui a compassion de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Ô affligée, battue de la tempête, qui ne trouves pas de consolation, voici, moi je pose tes pierres dans la stibine, et je te fonde sur des saphirs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'et je ferai tes créneaux de rubis, et tes portes d’escarboucles, et toute ton enceinte de pierres précieuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Et tous tes fils [seront] enseignés de l’ Éternel, et la paix de tes fils sera grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Tu seras établie en justice; tu seras loin de l’oppression, car tu ne craindras pas, – et de l’effroi, car il n’approchera pas de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Voici, ils s’assembleront, [mais] ce ne sera pas de par moi: celui qui s’assemble contre toi tombera à cause de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Voici, moi j’ai créé le forgeron qui souffle le feu du charbon et forme un instrument pour son ouvrage; et moi, j’ai créé le destructeur pour ruiner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Aucun instrument formé contre toi ne réussira, et toute langue qui se lèvera contre toi en jugement, tu la condamneras. C’est là l’héritage des serviteurs de l’ Éternel, et leur justice est de par moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, '*Ho! quiconque a soif, venez aux eaux, et vous qui n’avez pas d’argent, venez, achetez et mangez; oui, venez, achetez sans argent et sans prix du vin et du lait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Pourquoi dépensez-vous l’argent pour ce qui n’est pas du pain, et votre labeur pour ce qui ne rassasie pas? Écoutez-moi attentivement, et mangez ce qui est bon; et que votre âme jouisse à plaisir des choses grasses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Inclinez votre oreille et venez à moi; écoutez, et votre âme vivra: et je ferai avec vous une alliance éternelle, les grâces assurées de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Voici, je l’ai donné pour témoignage aux peuples, pour chef et commandant des peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Voici, tu appelleras une nation que tu n’as pas connue; et une nation qui ne te connaît pas accourra vers toi, à cause de l’ Éternel, ton Dieu, et du Saint d’Israël; car il t’a glorifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Cherchez l’ Éternel tandis qu’on le trouve; invoquez-le pendant qu’il est proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Que le méchant abandonne sa voie, et l’homme inique, ses pensées, et qu’il retourne à l’ Éternel, et il aura compassion de lui, – et à notre Dieu, car il pardonne abondamment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Car mes pensées ne sont pas vos pensées, et vos voies ne sont pas mes voies, dit l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'car [comme] les cieux sont élevés au-dessus de la terre, ainsi mes voies sont élevées au-dessus de vos voies, et mes pensées au-dessus de vos pensées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Car comme la pluie et la neige descendent des cieux, et n’y retournent pas, mais arrosent la terre et la font produire et germer, et donner de la semence au semeur, et du pain à celui qui mange,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'ainsi sera ma parole qui sort de ma bouche: elle ne reviendra pas à moi sans effet, mais fera ce qui est mon plaisir, et accomplira ce pour quoi je l’ai envoyée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Car vous sortirez avec joie, et vous serez conduits en paix; les montagnes et les collines éclateront devant vous en chants de triomphe, et tous les arbres des champs battront des mains:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'au lieu de l’épine croîtra le cyprès; au lieu de l’ortie croîtra le myrte; et ce sera pour l’ Éternel un nom, un signe à toujours, qui ne sera pas retranché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Ainsi dit l’ Éternel: Gardez le jugement, et pratiquez la justice, car mon salut est près de venir, et ma justice, d’être révélée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Bienheureux l’homme qui fait cela, et le fils de l’homme qui le tient ferme; qui garde le sabbat pour ne pas le profaner, et qui garde sa main de faire aucun mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Et que le fils de l’étranger qui s’est attaché à l’ Éternel ne parle pas, disant: L’ Éternel m’a entièrement séparé de son peuple; et que l’eunuque ne dise pas: Voici, je suis un arbre sec;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'car ainsi dit l’ Éternel: Aux eunuques qui gardent mes sabbats, et choisissent les choses auxquelles je prends plaisir, et qui tiennent ferme mon alliance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'je leur donnerai dans ma maison et au-dedans de mes murs une place et un nom meilleurs que des fils et des filles; je leur donnerai un nom éternel, qui ne sera pas retranché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Et les fils de l’étranger qui s’attachent à l’ Éternel pour le servir et pour aimer le nom de l’ Éternel, pour être ses serviteurs, – quiconque observe le sabbat pour ne pas le profaner, et ceux qui tiennent ferme mon alliance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'je les ferai venir à ma montagne sainte, et je les rendrai joyeux dans ma maison de prière: leurs holocaustes et leurs sacrifices seront agréés sur mon autel; car ma maison sera appelée une maison de prière pour tous les peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Le Seigneur l’ Éternel, qui rassemble les exilés d’Israël, dit: J’en rassemblerai encore d’autres vers lui, avec les siens déjà rassemblés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Vous, toutes les bêtes des champs, venez pour dévorer, [vous], toutes les bêtes de la forêt!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Ses sentinelles sont toutes aveugles, elles sont dénuées de connaissance. Ils sont tous des chiens muets qui ne peuvent aboyer, rêvant, se tenant couchés, aimant à sommeiller;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'et ces chiens sont voraces, ils ne savent pas être rassasiés: ce sont des bergers qui ne savent pas comprendre. Tous, ils tournent leurs regards vers leur propre chemin, chacun vers son intérêt particulier, jusqu’au dernier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Venez, [disent-ils], je prendrai du vin, et buvons notre soûl de boissons fortes; et demain sera comme aujourd’hui, [et] encore bien supérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Le juste périt, et personne ne le prend à cœur; et les hommes de bonté sont recueillis sans que personne comprenne que le juste est recueilli de devant le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Il est entré dans la paix: ils se reposent sur leurs couches, ceux qui ont marché dans leur droit chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Mais vous, approchez ici, fils de la devineresse, semence de l’adultère et de la prostituée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'De qui vous moquez-vous? Contre qui allongez-vous la bouche, [et] tirez-vous la langue? N’êtes-vous pas des enfants de transgression, une semence de mensonge,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'vous enflammant avec les idoles sous tout arbre vert, égorgeant les enfants dans les vallées, sous les fentes des rochers?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Les pierres polies de la vallée sont ta part: elles, elles sont ton sort; à elles aussi tu as répandu une libation, tu as offert un gâteau. Me consolerais-je de ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Tu as placé ta couche sur une montagne haute et élevée: là aussi tu es montée pour sacrifier des sacrifices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Et tu as mis ton mémorial derrière la porte et les poteaux; car, t’éloignant de moi, tu t’es découverte; et tu es montée, tu as élargi ton lit, et tu les as obligés envers toi par un accord; tu as aimé leur lit, tu as vu leur nudité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Et tu t’es rendue auprès du roi avec de l’huile, et tu as multiplié tes parfums; et tu as envoyé tes messagers au loin, et tu t’es dégradée jusque dans le shéol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Tu t’es fatiguée par la multitude de tes voies; [mais] tu n’as pas dit: C’est en vain! Tu as trouvé la vigueur de ta force, c’est pourquoi tu ne t’es pas lassée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'De qui as-tu peur, et qui crains-tu, que tu aies menti, et que tu ne te sois pas souvenue de moi, [et] ne l’aies pas pris à cœur? N’ai-je pas gardé le silence, et [cela] dès longtemps; et tu ne m’as pas craint?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Je déclarerai ta justice et tes œuvres, et elles ne te profiteront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Quand tu cries, que ceux que tu as rassemblés te délivrent! Mais le vent les emportera tous, un souffle les enlèvera; mais celui qui se confie en moi héritera le pays et possédera ma montagne sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Et on dira: Élevez, élevez [la chaussée], préparez le chemin; ôtez [toute] pierre d’achoppement du chemin de mon peuple!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Car ainsi dit celui qui est haut élevé et exalté, qui habite l’éternité, et duquel le nom est le Saint: J’habite le lieu haut élevé et saint, et avec celui qui est abattu et d’un esprit contrit, pour revivifier l’esprit de ceux qui sont contrits, et pour revivifier le cœur de ceux qui sont abattus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Car je ne contesterai pas à toujours, et je ne me courroucerai pas à jamais; car l’esprit défaillirait devant moi et les âmes que j’ai faites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Je me suis courroucé à cause de l’iniquité de son avarice, et je l’ai frappé; je me suis caché, et je me suis courroucé, et il a marché, dévoyé, dans le chemin de son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'J’ai vu ses voies, et je le guérirai, et je le conduirai, et je [lui] rendrai la consolation, à lui et aux siens qui mènent deuil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Je crée le fruit des lèvres. Paix, paix à celui qui est loin, et à celui qui est près! dit l’ Éternel; et je le guérirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Mais les méchants sont comme la mer agitée, qui ne peut se tenir tranquille et dont les eaux jettent dehors la vase et la boue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Il n’y a pas de paix, dit mon Dieu, pour les méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, '**Crie à plein gosier, ne te retiens pas; élève ta voix comme une trompette, et déclare à mon peuple leur transgression, et à la maison de Jacob leurs péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Cependant ils me cherchent tous les jours et trouvent leur plaisir à connaître mes voies, comme une nation qui pratiquerait la justice, et n’aurait pas abandonné le juste jugement de son Dieu; ils me demandent les ordonnances de la justice, ils trouvent leur plaisir à s’approcher de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Pourquoi avons-nous jeûné, et tu ne l’as pas vu? [et] avons-nous affligé nos âmes, et tu ne le sais pas? Voici, au jour de vos jeûnes, vous cherchez votre plaisir, et vous exigez durement tous les travaux qui vous sont dus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Voici, vous jeûnez pour contester et quereller, et pour frapper d’un poing méchant. Vous ne jeûnez pas maintenant, pour faire entendre votre voix en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Est-ce un jeûne comme celui-là que j’ai choisi, un jour où un homme afflige son âme? Courber sa tête comme un roseau, et étendre sous soi le sac et la cendre, appelleras-tu cela un jeûne, et un jour agréable à l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'N’est-ce pas ici le jeûne que j’ai choisi, qu’on rompe les chaînes de l’iniquité, qu’on fasse tomber les liens du joug, et qu’on renvoie libres les opprimés, et que vous brisiez tout joug?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'N’est-ce pas que tu partages ton pain avec celui qui a faim, et que tu fasses entrer dans la maison les affligés qui errent sans asile? quand tu vois un homme nu, que tu le couvres, et que tu ne te caches pas à ta propre chair?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Alors ta lumière jaillira comme l’aurore et ta santé germera promptement, et ta justice marchera devant toi, la gloire de l’ Éternel sera ton arrière-garde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Alors tu appelleras, et l’ Éternel répondra; tu crieras, et il dira: Me voici. Si tu ôtes du milieu de toi le joug, [si tu cesses] de montrer au doigt et de parler vanité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'si tu prodigues ton âme à l’affamé, et que tu rassasies l’âme de l’affligé, ta lumière se lèvera dans les ténèbres, et ton obscurité sera comme le midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Et l’ Éternel te conduira continuellement, et rassasiera ton âme dans les sécheresses, et rendra agiles tes os; et tu seras comme un jardin arrosé, et comme une source jaillissante dont les eaux ne trompent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Et ceux qui [seront issus] de toi bâtiront ce qui était ruiné dès longtemps; tu relèveras les fondements [qui étaient restés] de génération en génération, et on t’appellera: réparateur des brèches, restaurateur des sentiers fréquentés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Si tu gardes ton pied de [profaner] le sabbat, de faire ton plaisir en mon saint jour, si tu appelles le sabbat [tes] délices, [et] honorable le saint [jour] de l’ Éternel, si tu l’honores en t’abstenant de suivre tes propres chemins, de chercher ton plaisir et de dire des paroles [vaines],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'alors tu trouveras tes délices en l’ Éternel, et je te ferai passer à cheval sur les lieux hauts de la terre, et je te nourrirai de l’héritage de Jacob, ton père: car la bouche de l’ Éternel a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Voici, la main de l’ Éternel n’est pas devenue trop courte pour délivrer, ni son oreille trop appesantie pour entendre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'mais vos iniquités ont fait séparation entre vous et votre Dieu, et vos péchés ont fait [qu’il a] caché de vous sa face, pour ne pas écouter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Car vos mains sont souillées de sang, et vos doigts, d’iniquité; vos lèvres ont dit des mensonges, votre langue a murmuré l’iniquité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'il n’y a personne qui invoque la justice, et personne qui plaide en jugement avec intégrité; on se confie dans le néant, et on parle avec fausseté; on conçoit l’oppression, et on enfante l’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Ils font éclore des œufs de serpent, et ils tissent des toiles d’araignées: celui qui mange de leurs œufs mourra, et si l’on en écrase un, il en éclot une vipère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Leurs toiles ne deviendront pas des vêtements, et ils ne se couvriront point de leurs œuvres; leurs œuvres sont des œuvres d’iniquité, et des actes de violence sont dans leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Leurs pieds courent au mal, et se hâtent pour verser le sang innocent; leurs pensées sont des pensées d’iniquité; la destruction et la ruine sont dans leurs sentiers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'le chemin de la paix, ils ne le connaissent pas, et il n’y a pas de rectitude dans leurs voies; ils ont perverti leurs sentiers; quiconque y marche ne connaît pas la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'C’est pourquoi le juste jugement est loin de nous, et la justice ne nous atteint pas; nous attendons la lumière, et voici les ténèbres! la clarté, [et] nous marchons dans l’obscurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Nous tâtonnons après le mur comme des aveugles, et nous tâtonnons comme si nous n’avions pas d’yeux; nous avons trébuché en plein midi, comme dans le crépuscule; au milieu de ceux qui se portent bien nous sommes comme des morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Nous rugissons tous comme les ours, et nous ne cessons de gémir comme les colombes: nous attendons le juste jugement, et il n’y en a pas; le salut, [et] il est loin de nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Car nos transgressions se sont multipliées devant toi, et nos péchés témoignent contre nous; car nos transgressions sont avec nous, et nos iniquités, nous les connaissons:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'se rebeller et mentir contre l’ Éternel, et se détourner de notre Dieu, proférer l’oppression et la révolte, concevoir et énoncer du cœur des paroles de mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Et le jugement est repoussé en arrière, et la justice se tient loin; car la vérité a trébuché sur la place publique, et la droiture ne peut entrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Et la vérité fait défaut, et celui qui se retire du mal devient une proie. Et l’ Éternel l’a vu: et ce fut mauvais à ses yeux qu’il n’y ait pas de juste jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Et il vit qu’il n’y avait personne, et il s’étonna de ce qu’il n’y ait pas d’intercesseur; et son bras le sauva, et sa justice le soutint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Et il revêtit la justice comme une cuirasse, et [mit] un casque de salut sur sa tête, et il revêtit, comme un habit, les vêtements de la vengeance, et se revêtit de jalousie comme d’un manteau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Selon qu’a été la conduite, il rétribuera la fureur à ses adversaires, la pareille à ses ennemis; aux îles il rendra la rétribution.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Et, du couchant, ils craindront le nom de l’ Éternel, et du lever du soleil, sa gloire. Quand l’ennemi viendra comme un fleuve, l’Esprit de l’ Éternel lèvera un étendard contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Et le rédempteur viendra à Sion et vers ceux qui, en Jacob, reviennent de [leur] rébellion, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Et quant à moi, c’est ici mon alliance avec eux, dit l’ Éternel: Mon esprit qui est sur toi, et mes paroles que j’ai mises dans ta bouche, ne se retireront pas de ta bouche, ni de la bouche de ta semence, ni de la bouche de la semence de ta semence, dit l’ Éternel, dès maintenant et à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Lève-toi, resplendis, car ta lumière est venue, et la gloire de l’ Éternel s’est levée sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Car voici, les ténèbres couvriront la terre, et l’obscurité profonde, les peuples; mais sur toi se lèvera l’ Éternel, et sa gloire sera vue sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Et les nations marcheront à ta lumière, et les rois, à la splendeur de ton lever.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Lève autour de toi tes yeux, et regarde: ils se rassemblent tous, ils viennent vers toi; tes fils viennent de loin, et tes filles sont portées sur les bras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Alors tu verras, et tu seras rayonnante, et ton cœur frissonnera et s’élargira; car l’abondance de la mer se tournera vers toi, les richesses des nations viendront vers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Une multitude de chameaux te couvrira, les dromadaires de Madian et d’Épha; tous ils viendront de Sheba; ils porteront de l’or et de l’encens, et annonceront avec joie les louanges de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'tous les troupeaux de Kédar se rassembleront vers toi, les béliers de Nebaïoth te serviront; une offrande agréée, ils monteront sur mon autel; et j’ornerai la maison de ma magnificence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Qui sont ceux-ci, qui volent comme une nuée, et comme les colombes vers leurs colombiers?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Car les îles s’attendront à moi, et les navires de Tarsis [viennent] les premiers, pour apporter tes fils de loin, leur argent et leur or avec eux, au nom de l’ Éternel, ton Dieu, et au Saint d’Israël, car il t’a glorifiée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Et les fils de l’étranger bâtiront tes murs, et leurs rois te serviront. Car dans ma colère je t’ai frappée, mais dans ma faveur j’ai eu compassion de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Et tes portes seront continuellement ouvertes (elles ne seront fermées ni de jour ni de nuit), pour que te soient apportées les richesses des nations, et pour que leurs rois te soient amenés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Car la nation et le royaume qui ne te serviront pas périront, et ces nations seront entièrement désolées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'La gloire du Liban viendra vers toi, le cyprès, le pin, et le buis ensemble, pour orner le lieu de mon sanctuaire; et je rendrai glorieuse la place de mes pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Et les fils de tes oppresseurs viendront se courber devant toi, et tous ceux qui t’ont méprisée se prosterneront à la plante de tes pieds, et t’appelleront la ville de l’ Éternel, la Sion du Saint d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Au lieu d’être abandonnée et haïe, de sorte que personne ne passait [par toi], je te mettrai en honneur à toujours, pour joie de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Et tu suceras le lait des nations, et tu suceras les mamelles des rois; et tu sauras que moi je suis l’ Éternel, ton sauveur, et ton rédempteur, le Puissant de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Au lieu d’airain je ferai venir de l’or, et au lieu de fer je ferai venir de l’argent, et au lieu de bois, de l’airain, et au lieu de pierres, du fer. Et je te donnerai pour gouvernants la paix, et pour magistrats, la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'On n’entendra plus [parler] de violence dans ton pays, de dévastation et de ruine dans tes confins; mais tu appelleras tes murs Salut, et tes portes Louange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Le soleil ne sera plus ta lumière, de jour, et la clarté de la lune ne t’éclairera plus; mais l’ Éternel sera ta lumière à toujours, et ton Dieu, ta gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Ton soleil ne se couchera plus, et ta lune ne se retirera pas; car l’ Éternel sera ta lumière à toujours, et les jours de ton deuil seront finis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Et ton peuple, – eux tous, seront justes; ils posséderont le pays pour toujours, rejeton que j’ai planté, l’œuvre de mes mains pour me glorifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Le petit deviendra mille, et le moindre, une nation forte. Moi, l’ Éternel, je hâterai cela en son temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, '*L’Esprit du Seigneur, l’ Éternel, est sur moi, parce que l’ Éternel m’a oint pour apporter de bonnes nouvelles aux débonnaires: il m’a envoyé pour panser ceux qui ont le cœur brisé, pour proclamer aux captifs la liberté, et aux prisonniers l’ouverture de la prison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'pour proclamer l’année de la faveur de l’ Éternel et le jour de la vengeance de notre Dieu, pour consoler tous ceux qui mènent deuil,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'pour mettre et donner à ceux de Sion qui mènent deuil l’ornement au lieu de la cendre, l’huile de joie au lieu du deuil, un vêtement de louange au lieu d’un esprit abattu, afin qu’ils soient appelés térébinthes de justice, le plant de l’ Éternel pour qu’il soit glorifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Et ils bâtiront ce qui était ruiné dès longtemps, ils relèveront les désolations anciennes, et ils renouvelleront les villes ruinées, les lieux désolés de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Et les étrangers se tiendront là et paîtront vos troupeaux, et les fils de l’étranger seront vos laboureurs et vos vignerons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Mais vous, vous serez appelés les sacrificateurs de l’ Éternel; on dira de vous: les serviteurs de notre Dieu. Vous mangerez des richesses des nations, et vous vous revêtirez de leur gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Au lieu de votre honte [vous aurez] le double; au lieu d’être confondus, ils célébreront avec joie leur portion: c’est pourquoi, dans leur pays, ils posséderont le double, ils auront une joie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Car moi, l’ Éternel, j’aime le juste jugement, je hais la rapine d’iniquité; et je leur donnerai leur récompense avec vérité, et je ferai avec eux une alliance éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Et leur semence sera connue parmi les nations, et leur postérité, au milieu des peuples; tous ceux qui les verront les reconnaîtront, qu’ils sont la semence que l’ Éternel a bénie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Je me réjouirai avec joie en l’ Éternel, mon âme s’égaiera en mon Dieu; car il m’a revêtu des vêtements du salut, il m’a couvert de la robe de la justice, comme un fiancé se pare de son turban et comme une fiancée s’orne de ses joyaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Car, comme la terre produit son germe et comme un jardin fait germer ses semences, ainsi le Seigneur l’ Éternel fera germer la justice et la louange devant toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'À cause de Sion je ne me tairai pas, et à cause de Jérusalem je ne me tiendrai pas tranquille, jusqu’à ce que sa justice paraisse comme l’éclat de la lumière, et son salut comme un flambeau qui brûle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Et les nations verront ta justice, et tous les rois, ta gloire; et on t’appellera d’un nom nouveau, que la bouche de l’ Éternel désignera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Et tu seras une couronne de beauté dans la main de l’ Éternel, et une tiare royale dans la main de ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'On ne te dira plus la délaissée, et on n’appellera plus ta terre la désolée. Car on t’appellera: Mon plaisir en elle, et ta terre: La mariée; car le plaisir de l’ Éternel est en toi, et ton pays sera marié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Car, [comme] un jeune homme épouse une vierge, tes fils t’épouseront, et de la joie que le fiancé a de sa fiancée, ton Dieu se réjouira de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Sur tes murailles, Jérusalem, j’ai établi des gardiens; ils ne se tairont jamais, de tout le jour et de toute la nuit. Vous qui faites se ressouvenir l’ Éternel, ne gardez pas le silence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'et ne lui laissez pas de repos, jusqu’à ce qu’il établisse Jérusalem, et qu’il en fasse un sujet de louange sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'L’ Éternel a juré par sa droite et par le bras de sa force: Si je donne encore ton froment pour nourriture à tes ennemis, et si les fils de l’étranger boivent ton moût, pour lequel tu as travaillé!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'car ceux qui l’ont amassé le mangeront et loueront l’ Éternel; et ceux qui l’ont recueilli le boiront dans mes saints parvis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Passez, passez par les portes; préparez le chemin du peuple; élevez, élevez la chaussée, ôtez les pierres; élevez un étendard devant les peuples!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Voici, l’ Éternel a fait entendre jusqu’au bout de la terre: Dites à la fille de Sion: Voici, ton salut vient; voici, son salaire est avec lui, et sa récompense devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Et on les appellera le peuple saint, les rachetés de l’ Éternel; et toi, tu seras appelée la recherchée, la ville non abandonnée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Qui est celui-ci, qui vient d’Édom, de Botsra, avec des habits teints en rouge, celui-ci, qui est magnifique dans ses vêtements, qui marche dans la grandeur de sa force? C’est moi, qui parle en justice, – puissant pour sauver. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Pourquoi y a-t-il du rouge à tes vêtements, et tes habits sont-ils comme celui qui foule dans la cuve?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'J’ai été seul à fouler le pressoir, et d’entre les peuples pas un homme n’a été avec moi; et je les ai foulés dans ma colère, et je les ai écrasés dans ma fureur, et leur sang a rejailli sur mes habits, et j’ai souillé tous mes vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Car le jour de la vengeance était dans mon cœur, et l’année de mes rachetés était venue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Et je regardai, et il n’y avait point de secours; et je m’étonnai de ce qu’il n’y avait personne qui [me] soutienne; et mon bras m’a sauvé, et ma fureur m’a soutenu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Et j’ai foulé les peuples dans ma colère, et je les ai enivrés dans ma fureur; et j’ai fait couler leur sang à terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, '*Je rappellerai les bontés de l’ Éternel, les louanges de l’ Éternel, selon tout ce dont l’ Éternel nous a comblés, et les grands bienfaits envers la maison d’Israël, dont il l’a comblée selon ses compassions et selon la multitude de ses bontés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Et il dit: Certainement ils sont mon peuple, des fils qui ne mentiront pas; et il est devenu leur sauveur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Dans toutes leurs détresses, il a été en détresse, et l’Ange de sa face les a sauvés; dans son amour et dans sa miséricorde il les a rachetés, et il s’est chargé d’eux, et il les a portés tous les jours d’autrefois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'mais ils se rebellèrent et contristèrent l’Esprit de sa sainteté, et il se changea pour eux en ennemi; lui-même, il combattit contre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Mais il se souvint des jours d’autrefois, de Moïse, de son peuple: Où est celui qui les fit monter de la mer, avec les bergers de son troupeau? Où est celui qui mit l’Esprit de sa sainteté au-dedans de lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'son bras magnifique les faisant marcher par la droite de Moïse; – qui fendit les eaux devant eux pour se faire un nom à toujours,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'qui les a fait marcher par les abîmes, comme un cheval dans le désert? Ils ne bronchaient pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Comme une bête descend dans la vallée, l’Esprit de l’ Éternel leur donna du repos. Ainsi tu as conduit ton peuple, pour te faire un nom magnifique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Regarde des cieux, et vois, de la demeure de ta sainteté et de ta magnificence! Où sont ta jalousie et ta puissance, le frémissement de tes entrailles et de tes compassions? Se retiennent-elles envers moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Car tu es notre père: si Abraham ne nous connaît pas, et si Israël nous ignore, toi, Éternel, tu es notre Père; ton nom est: Notre rédempteur, de tout temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Pourquoi nous as-tu fait errer, ô Éternel, loin de tes voies, [et] as-tu endurci notre cœur pour ne pas te craindre? Retourne-toi, à cause de tes serviteurs, des tribus de ton héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Ton peuple saint ne l’a possédé que pour peu [de temps]; nos ennemis ont foulé aux pieds ton sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Nous sommes [comme ceux] sur lesquels tu n’as jamais dominé, qui ne sont pas appelés de ton nom. Oh! si tu fendais les cieux! Si tu voulais descendre, [et] que devant toi les montagnes se fondent, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, '[descendre] comme le feu brûle les broussailles, comme le feu fait bouillonner l’eau, pour faire connaître ton nom à tes ennemis, en sorte que les nations tremblent devant toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Quand tu fis des choses terribles que nous n’attendions pas, tu descendis: devant toi les montagnes se fondirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Et jamais on n’a entendu, [jamais] on n’a entendu de l’oreille, [jamais] l’œil n’a vu, hors toi, ô Dieu, ce que [Dieu] a préparé pour celui qui s’attend à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Tu viens à la rencontre de celui qui se réjouit à pratiquer la justice, [de ceux] qui se souviennent de toi dans tes voies! Voici, tu as été courroucé, et nous avons péché;... en tes voies est la perpétuité, et nous serons sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Et tous, nous sommes devenus comme une chose impure, et toutes nos justices, comme un vêtement souillé; et nous sommes tous fanés comme une feuille, et nos iniquités, comme le vent, nous emportent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'et il n’y a personne qui invoque ton nom, qui se réveille pour te saisir! Car tu as caché ta face de nous, et tu nous as fait fondre par nos iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Or maintenant, Éternel, tu es notre père: nous sommes l’argile, tu es celui qui nous as formés, et nous sommes tous l’ouvrage de tes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Ne sois pas extrêmement courroucé, ô Éternel, et ne te souviens pas à toujours de l’iniquité. Voici, regarde: nous sommes tous ton peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Tes villes saintes sont devenues un désert; Sion est un désert, Jérusalem, une désolation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'notre maison sainte et magnifique, où nos pères te louaient, est brûlée par le feu, et toutes nos choses désirables sont dévastées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Te retiendras-tu, Éternel, à la vue de ces choses? Te tairas-tu, et nous affligeras-tu extrêmement?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Je suis recherché de ceux qui ne s’enquéraient pas [de moi], je suis trouvé de ceux qui ne me cherchaient pas. J’ai dit: Me voici, me voici, à une nation qui n’était pas appelée de mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'J’ai étendu ma main tout le jour vers un peuple rebelle, qui marche dans une voie qui n’est pas bonne, après leurs propres pensées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'un peuple qui me provoque continuellement en face, qui sacrifie dans des jardins et brûle de l’encens sur des [autels de] briques;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'qui habite les sépulcres et passe la nuit dans les lieux cachés; qui mange la chair du porc, et le jus des choses impures est dans leurs vases;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'qui dit: Tiens-toi loin, ne me touche pas, car je suis saint vis-à-vis de toi. Ceux-ci sont une fumée dans mes narines, un feu qui brûle tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Voici, cela est écrit devant moi; je ne me tairai point, mais je rendrai, oui, je rendrai dans leur sein');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'à la fois, dit l’ Éternel, vos iniquités et les iniquités de vos pères, qui ont brûlé de l’encens sur les montagnes, et m’ont outragé sur les collines, – et je mesurerai dans leur sein leur œuvre passée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Ainsi dit l’ Éternel: Comme le moût est trouvé dans la grappe, et qu’on dit: Ne la détruis pas, car il y a une bénédiction en elle, ainsi je ferai à cause de mes serviteurs, pour ne pas détruire le tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Et je ferai sortir de Jacob une semence, et de Juda un possesseur de mes montagnes, et mes élus posséderont le pays et mes serviteurs y demeureront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Et le Saron sera une demeure du menu bétail, et la vallée d’Acor, un lieu où couchera le gros bétail, pour mon peuple qui m’aura cherché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Mais vous qui abandonnez l’ Éternel, vous qui oubliez ma montagne sainte, qui dressez une table pour Gad, et qui remplissez pour Meni [la coupe] de vin mixtionné,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'je vous ai aussi comptés pour l’épée, et vous vous courberez tous dans le carnage, parce que j’ai appelé et vous n’avez pas répondu, j’ai parlé et vous n’avez pas écouté, et parce que vous faites ce qui est mauvais à mes yeux, et que vous avez choisi ce en quoi je ne prends pas plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Voici, mes serviteurs mangeront, et vous aurez faim; voici, mes serviteurs boiront, et vous aurez soif; voici, mes serviteurs se réjouiront, et vous serez honteux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'voici, mes serviteurs chanteront de joie à cause du bonheur de [leur] cœur, et vous, vous crierez à cause de la douleur de [votre] cœur, et vous hurlerez à cause du brisement de [votre] esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Et vous laisserez votre nom comme imprécation à mes élus; car le Seigneur, l’ Éternel, te mettra à mort, et appellera ses serviteurs d’un autre nom,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'de sorte que celui qui se bénira dans le pays, se bénira par le Dieu de vérité, et celui qui jurera dans le pays, jurera par le Dieu de vérité; car les détresses précédentes seront oubliées, et elles seront cachées de devant mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Car voici, je crée de nouveaux cieux et une nouvelle terre, et on ne se souviendra plus de ceux qui ont précédé, et ils ne monteront pas au cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Mais réjouissez-vous et égayez-vous à toujours de ce que je crée; car voici, je crée Jérusalem [pour être] une jubilation, et son peuple, une joie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'et je m’égaierai sur Jérusalem, et je me réjouirai en mon peuple. Et on n’y entendra plus la voix des pleurs et la voix des cris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Il n’y aura plus, dès lors, ni petit enfant de peu de jours, ni vieillard qui n’ait pas accompli ses jours. Car le jeune homme mourra âgé de 100 ans, et le pécheur âgé de 100 ans sera maudit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Et ils bâtiront des maisons et les habiteront, et ils planteront des vignes et en mangeront le fruit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'ils ne bâtiront pas pour qu’un autre habite; ils ne planteront pas pour qu’un autre mange; car les jours de mon peuple seront comme les jours d’un arbre, et mes élus useront [eux-mêmes] l’ouvrage de leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Ils ne travailleront pas en vain, ni n’engendreront pour la frayeur; car ils sont la semence des bénis de l’ Éternel, et leur postérité avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Et il arrivera que, avant qu’ils crient, je répondrai, [et] pendant qu’ils parlent, j’exaucerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Le loup et l’agneau paîtront ensemble, et le lion mangera de la paille comme le bœuf; et la poussière sera la nourriture du serpent. On ne fera pas de tort, et on ne détruira pas sur toute ma montagne sainte, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Ainsi dit l’ Éternel: Les cieux sont mon trône, et la terre le marchepied de mes pieds: quelle est la maison que vous me bâtirez, et quel est le lieu de mon repos?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Toutes ces choses, ma main les a faites, et toutes ces choses ont été, dit l’ Éternel. Mais c’est à celui-ci que je regarderai: à l’affligé, et à celui qui a l’esprit contrit et qui tremble à ma parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Celui qui égorge un bœuf, frappe un homme; celui qui sacrifie un agneau, brise la nuque à un chien; celui qui offre un gâteau, c’est du sang de porc; celui qui présente le mémorial de l’encens [est comme] celui qui bénit une idole. Comme ils ont choisi leurs propres chemins, et que leur âme a pris plaisir à leurs choses exécrables,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'moi aussi, je choisirai leurs calamités, et je ferai venir sur eux ce qu’ils craignent, parce que j’ai crié, et il n’y a eu personne qui réponde; j’ai parlé, et ils n’ont pas écouté, et ont fait ce qui est mauvais à mes yeux, et ont choisi ce en quoi je ne prends pas plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Écoutez la parole de l’ Éternel, vous qui tremblez à sa parole: Vos frères qui vous haïssaient, qui vous rejetaient à cause de mon nom, disaient: Que l’ Éternel soit glorifié, et que nous voyions votre joie! Mais eux, ils seront confus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Une voix de tumulte [vient] de la ville, une voix, du temple, une voix de l’ Éternel qui rend la récompense à ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Avant qu’elle ait été en travail, elle a enfanté; avant que les douleurs lui soient venues, elle a donné le jour à un [enfant] mâle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Qui a entendu une chose pareille? Qui a vu de telles choses? Fera-t-on qu’un pays enfante en un seul jour? Une nation naîtra-t-elle en une fois? Car aussitôt que Sion a été en travail, elle a enfanté ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Amènerais-je jusqu’au moment de l’enfantement, et je ne ferais pas enfanter? dit l’ Éternel. Moi, qui fais enfanter, je fermerais [la matrice]? dit ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Réjouissez-vous avec Jérusalem, et égayez-vous à cause d’elle, vous tous qui l’aimez; tressaillez de joie avec elle, vous tous qui menez deuil sur elle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'parce que vous téterez et serez rassasiés du sein de ses consolations, parce que vous sucerez et que vous vous délecterez de l’abondance de sa gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Car ainsi dit l’ Éternel: Voici, j’étends sur elle la paix comme une rivière, et la gloire des nations comme un torrent qui déborde; et vous téterez, vous serez portés sur les bras et caressés sur les genoux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Comme quelqu’un que sa mère console, ainsi moi, je vous consolerai; et vous serez consolés dans Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Et vous le verrez, et votre cœur se réjouira, et vos os fleuriront comme l’herbe verte; et la main de l’ Éternel sera connue en ses serviteurs, et il verse sa colère sur ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Car voici, l’ Éternel viendra en feu, et ses chars, comme un tourbillon, pour rendre sa colère avec fureur, et son tancement avec des flammes de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Car l’ Éternel entrera en jugement avec toute chair, par le feu, et par son épée; et les tués de l’ Éternel seront en grand nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Ceux qui se sanctifient et se purifient dans les jardins, en en suivant un seul [qui est] au milieu, mangeant la chair du porc et des choses exécrables et des souris, périront tous ensemble, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Et moi,... leurs actes et leurs pensées [sont devant moi]. [Le temps] est venu de rassembler toutes les nations et les langues; et elles viendront et verront ma gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Et je mettrai au milieu d’eux un signe; et j’enverrai les réchappés d’entre eux vers les nations: à Tarsis, à Pul, et à Lud, qui bandent l’arc; à Tubal et à Javan, aux îles lointaines, qui n’ont pas entendu parler de moi et n’ont pas vu ma gloire; et ils raconteront ma gloire parmi les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Et ils amèneront tous vos frères, d’entre toutes les nations, en offrande à l’ Éternel, sur des chevaux, et sur des chars, et dans des voitures couvertes, et sur des mulets, et sur des dromadaires, à ma montagne sainte, à Jérusalem, dit l’ Éternel, comme les fils d’Israël apportent l’offrande dans un vase pur à la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Et j’en prendrai aussi d’entre eux pour sacrificateurs, pour Lévites, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Car, comme les nouveaux cieux et la nouvelle terre que je fais, subsisteront devant moi, dit l’ Éternel, ainsi subsisteront votre semence et votre nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Et il arrivera que, de nouvelle lune à nouvelle lune, et de sabbat en sabbat, toute chair viendra pour se prosterner devant moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Et ils sortiront, et verront les cadavres des hommes qui se sont rebellés contre moi; car leur ver ne mourra pas, et leur feu ne s’éteindra pas, et ils seront en horreur à toute chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Paroles de Jérémie, fils de Hilkija, d’entre les sacrificateurs qui étaient à Anathoth, dans le pays de Benjamin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'auquel vint la parole de l’ Éternel, dans les jours de Josias, fils d’Amon, roi de Juda, la treizième année de son règne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'elle vint aussi [à lui] dans les jours de Jehoïakim, fils de Josias, roi de Juda, jusqu’à la fin de la onzième année de Sédécias, fils de Josias, roi de Juda, jusqu’à ce que Jérusalem fut emmenée en captivité, au cinquième mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Avant que je te forme dans le ventre [de ta mère], je t’ai connu, et avant que tu sortes de [son] sein, je t’ai sanctifié, je t’ai établi prophète pour les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Et je dis: Ah, Seigneur Éternel! voici, je ne sais pas parler; car je suis un enfant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Et l’ Éternel me dit: Ne dis pas: Je suis un enfant, car pour tout ce pour quoi je t’enverrai, tu iras, et tout ce que je te commanderai, tu le diras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Ne les crains point; car je suis avec toi pour te délivrer, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Et l’ Éternel étendit sa main, et toucha ma bouche; et l’ Éternel me dit: Voici, j’ai mis mes paroles dans ta bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Regarde, je t’ai établi ce jour-ci sur les nations et sur les royaumes, pour arracher, et pour démolir, et pour détruire, et pour renverser, pour bâtir et pour planter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Et la parole de l’ Éternel vint à moi, disant: Que vois-tu, Jérémie? Et je dis: Je vois un bâton d’amandier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Et l’ Éternel me dit: Tu as bien vu, car je veille sur ma parole pour l’exécuter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Et la parole de l’ Éternel vint à moi une seconde fois, disant: Que vois-tu? Et je dis: Je vois un pot bouillant, dont le devant est du côté du nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Et l’ Éternel me dit: Du nord le mal fondra sur tous les habitants du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Car voici, j’appelle toutes les familles des royaumes du nord, dit l’ Éternel, et elles viendront, et mettront chacune son trône à l’entrée des portes de Jérusalem, et contre toutes ses murailles à l’entour, et contre toutes les villes de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Et je prononcerai contre eux mes jugements, à cause de toute leur iniquité par laquelle ils m’ont abandonné, et ont brûlé de l’encens à d’autres dieux, et se sont prosternés devant l’ouvrage de leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Et toi, ceins tes reins, et lève-toi, et dis-leur tout ce que je te commanderai; ne sois point effrayé d’eux, de peur que moi je ne t’épouvante devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Et moi, voici, je t’établis aujourd’hui comme une ville forte, et comme une colonne de fer, et comme des murailles d’airain, contre tout le pays, contre les rois de Juda, ses princes, ses sacrificateurs, et le peuple du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Et ils combattront contre toi, mais ils ne prévaudront pas sur toi, car moi je suis avec toi, dit l’ Éternel, pour te délivrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Va, et crie aux oreilles de Jérusalem, disant: Ainsi dit l’ Éternel: Je me souviens de toi, de la grâce de ta jeunesse, de l’amour de tes fiançailles, quand tu marchais après moi dans le désert, dans un pays non semé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Israël était saint à l’ Éternel, les prémices de ses fruits. Tous ceux qui le dévorent sont coupables; il viendra sur eux du mal, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Écoutez la parole de l’ Éternel, maison de Jacob, et [vous], toutes les familles de la maison d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Ainsi dit l’ Éternel: Quelle iniquité vos pères ont-ils trouvée en moi, qu’ils se soient éloignés de moi, et soient allés après la vanité, et soient devenus vains?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Et ils n’ont pas dit: Où est l’ Éternel qui nous a fait monter du pays d’Égypte, qui nous a fait marcher dans le désert, dans un pays stérile et plein de fosses, dans un pays aride et d’ombre de mort, dans un pays où personne ne passe et où aucun homme n’habite?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Et je vous ai amenés dans un pays fertile, pour en manger les fruits et les biens; et vous y êtes venus, et vous avez rendu impur mon pays, et de mon héritage vous avez fait une abomination.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Les sacrificateurs n’ont pas dit: Où est l’ Éternel? et ceux qui s’occupaient de la loi ne m’ont point connu, et les pasteurs se sont rebellés contre moi, et les prophètes ont prophétisé par Baal et ont marché après des choses qui ne profitent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'C’est pourquoi je contesterai encore avec vous, dit l’ Éternel, et je contesterai avec les fils de vos fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Car passez par les îles de Kittim, et voyez; et envoyez en Kédar, et considérez bien, et voyez s’il y a eu rien de tel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Y a-t-il une nation qui ait changé de dieux? – et ce ne sont pas des dieux. Mais mon peuple a changé sa gloire contre ce qui n’est d’aucun profit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Cieux, soyez étonnés de ceci, frissonnez, et soyez extrêmement confondus, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Car mon peuple a fait deux maux: ils m’ont abandonné, moi, la source des eaux vives, pour se creuser des citernes, des citernes crevassées qui ne retiennent pas l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Israël est-il un serviteur? Est-il un [esclave] né dans la maison? Pourquoi est-il mis au pillage?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Les jeunes lions ont rugi contre lui, ils ont fait retentir leur voix, et ils ont mis son pays en désolation; ses villes sont brûlées, de sorte qu’il n’y a plus d’habitant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Même les fils de Noph et de Takhpanès te brouteront le sommet de la tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'N’est-ce pas toi qui t’es fait cela, en ce que tu as abandonné l’ Éternel, ton Dieu, dans le temps où il te faisait marcher dans le chemin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Et maintenant, qu’as-tu affaire d’aller en Égypte pour boire les eaux du Shikhor? Et qu’as-tu affaire d’aller vers l’Assyrie pour boire les eaux du fleuve?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Ton iniquité te châtie, et tes rébellions te reprennent; et connais, et vois, que c’est une chose mauvaise et amère que tu aies abandonné l’ Éternel, ton Dieu, et que ma crainte ne soit pas en toi, dit le Seigneur, l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Car d’ancienneté tu as rompu ton joug, arraché tes liens, et tu as dit: Je ne servirai pas. Car, sur toute haute colline et sous tout arbre vert tu t’inclines, tu te prostitues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Et moi je t’avais plantée, un cep exquis, une toute vraie semence; comment t’es-tu changée pour moi en sarments dégénérés d’une vigne étrangère?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Quand tu te laverais avec du nitre, et que tu emploierais beaucoup de potasse, ton iniquité reste marquée devant moi, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Comment dis-tu: Je ne me suis pas rendue impure, je n’ai pas marché après les Baals? Regarde ton chemin dans la vallée, reconnais ce que tu as fait, dromadaire légère, qui vas çà et là croisant tes chemins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Ânesse sauvage accoutumée au désert, dans le désir de son âme elle hume le vent: dans son ardeur, qui la détournera? Tous ceux qui la cherchent ne se fatigueront point; ils la trouveront en son mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Retiens ton pied de se laisser déchausser; et ton gosier d’avoir soif. Mais tu dis: C’est en vain; non, car j’aime les étrangers, et j’irai après eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Comme un voleur est confus quand il est trouvé, ainsi sera confuse la maison d’Israël, eux, leurs rois, leurs princes, et leurs sacrificateurs, et leurs prophètes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'ils disent à un bois: Tu es mon père; et à une pierre: Tu m’as engendré. Car ils m’ont tourné le dos, et non la face; et, dans le temps de leur malheur, ils diront: Lève-toi, et délivre-nous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Et où sont tes dieux que tu t’es faits? Qu’ils se lèvent, s’ils peuvent te sauver au temps de ton malheur! Car le nombre de tes dieux est celui de tes villes, ô Juda!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Pourquoi contesteriez-vous avec moi? Vous vous êtes tous rebellés contre moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'J’ai frappé vos fils en vain, ils ne reçoivent pas la correction; votre épée a dévoré vos prophètes, comme un lion destructeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Ô génération! voyez la parole de l’ Éternel! Ai-je été un désert pour Israël, ou un pays de ténèbres? Pourquoi mon peuple a-t-il dit: Nous sommes maîtres, nous ne viendrons plus à toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'La vierge oublie-t-elle sa parure? l’épouse, ses atours? Mais mon peuple m’a oublié pendant des jours sans nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Comme tu es habile dans tes voies pour chercher l’amour! C’est pourquoi aussi tu as accoutumé tes voies aux choses iniques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Même dans les pans de ta robe a été trouvé le sang des pauvres innocents, que tu n’avais point trouvés faisant effraction; mais [il y a été trouvé] à cause de toutes ces choses-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Et tu dis: Oui, je suis innocente, sa colère se détournera de moi. Voici, j’entrerai en jugement avec toi sur ce que tu as dit: Je n’ai point péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Pourquoi te donnes-tu tant de mouvement pour changer de chemin? Tu auras honte aussi de l’Égypte, comme tu as eu honte de l’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'De celle-là aussi tu sortiras avec tes mains sur ta tête, car l’ Éternel a rejeté ceux en qui tu as eu confiance, et tu ne réussiras pas par eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Il est dit: Si un homme renvoie sa femme, et qu’elle le quitte et soit à un autre homme, retournera-t-il vers elle? ce pays-là n’en sera-t-il pas entièrement souillé? Et toi, tu t’es prostituée à beaucoup d’amants; toutefois retourne vers moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Lève tes yeux vers les hauteurs, et regarde! Où ne t’es-tu pas abandonnée? Tu t’es assise sur les chemins pour eux, comme un Arabe dans le désert, et tu as souillé le pays par tes prostitutions et par ton iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Aussi les ondées ont été retenues, et il n’y a pas eu de pluie de la dernière saison; mais tu as un front de femme prostituée, tu refuses d’avoir honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Ne me crieras-tu pas désormais: Mon Père! tu es le conducteur de ma jeunesse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Gardera-t-il à toujours sa colère, la conservera -t-il à jamais? Voici, tu as parlé, et tu as fait les choses mauvaises et tu as su les accomplir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Et l’ Éternel me dit dans les jours du roi Josias: As-tu vu ce qu’a fait Israël, l’infidèle? Elle s’en est allée sur toute haute montagne et sous tout arbre vert, et elle s’y est prostituée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Et j’ai dit: Après qu’elle a fait toutes ces choses, elle reviendra à moi; mais elle n’est pas revenue. Et sa sœur, Juda la perfide, l’a vu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Et j’ai vu que, [quand], pour toutes les choses en lesquelles Israël l’infidèle avait commis adultère, je l’ai renvoyée et lui ai donné sa lettre de divorce, toutefois sa sœur, Juda la perfide, n’en a pas eu de crainte, mais elle s’en est allée et s’est prostituée, elle aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Et il est arrivé que, par la légèreté de sa prostitution, elle a souillé le pays, et a commis adultère avec la pierre et le bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Et même, avec tout cela, sa sœur, Juda la perfide, n’est pas revenue à moi de tout son cœur, mais avec mensonge, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Et l’ Éternel me dit: Israël l’infidèle s’est montrée plus juste que Juda la perfide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Va, et crie ces paroles vers le nord, et dis: Reviens, Israël l’infidèle, dit l’ Éternel; je ne ferai pas peser sur vous un visage irrité, car je suis bon, dit l’ Éternel; je ne garderai pas ma colère à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Seulement, reconnais ton iniquité, car tu t’es rebellée contre l’ Éternel, ton Dieu, et tu as tourné çà et là tes chemins vers les étrangers sous tout arbre vert; et vous n’avez pas écouté ma voix, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Revenez, fils infidèles, dit l’ Éternel, car moi je vous ai épousés; et je vous prendrai, un d’une ville, et deux d’une famille, et je vous ferai venir à Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Et je vous donnerai des pasteurs selon mon cœur, et ils vous paîtront avec connaissance et avec intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Et il arrivera que, quand vous aurez multiplié et fructifié dans le pays, en ces jours-là, dit l’ Éternel, on ne dira plus: L’arche de l’alliance de l’ Éternel! Et elle ne montera plus au cœur, et on ne s’en souviendra pas, et on ne la visitera pas, et on ne fera plus cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Dans ce temps-là on appellera Jérusalem le trône de l’ Éternel; et toutes les nations se rassembleront vers elle, au nom de l’ Éternel, à Jérusalem; et elles ne marcheront plus suivant le penchant obstiné de leur mauvais cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'En ces jours-là, la maison de Juda marchera avec la maison d’Israël; et ils viendront ensemble du pays du nord au pays que j’ai donné en héritage à vos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Et moi j’ai dit: Comment te mettrai-je parmi les fils, et te donnerai-je un pays désirable, le bel héritage des armées des nations? Et j’ai dit: Vous m’appellerez: Mon père! et vous ne vous détournerez pas de moi...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Certainement, comme une femme perfide [se détourne] de son ami, ainsi vous avez agi perfidement envers moi, maison d’Israël, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Une voix a été entendue sur les hauteurs, les pleurs et les supplications des fils d’Israël; car ils ont perverti leur voie, ils ont oublié l’ Éternel, leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Revenez, fils infidèles; je guérirai vos infidélités... Nous voici, nous venons à toi, car tu es l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Certainement, c’est en vain [qu’on s’attend] aux collines, à la multitude des montagnes; certainement, c’est en l’ Éternel, notre Dieu, qu’est le salut d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Mais la honte a dévoré dès notre jeunesse le travail de nos pères, leur menu bétail et leur gros bétail, leurs fils et leurs filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Nous nous coucherons dans notre honte, et notre confusion nous couvre; car nous avons péché contre l’ Éternel, notre Dieu, nous et nos pères, dès notre jeunesse et jusqu’à ce jour, et nous n’avons pas écouté la voix de l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Si tu reviens, ô Israël, dit l’ Éternel, reviens à moi; et si tu ôtes tes abominations de devant moi, tu ne seras plus errant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'et tu jureras en vérité, en jugement et en justice: L’ Éternel est vivant! Et les nations se béniront en lui, et en lui elles se glorifieront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Car ainsi dit l’ Éternel aux hommes de Juda et à Jérusalem: Défrichez pour vous un terrain neuf, et ne semez pas au milieu des épines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Circoncisez-vous pour l’ Éternel, et ôtez le prépuce de vos cœurs, hommes de Juda et habitants de Jérusalem, de peur que ma fureur ne sorte comme un feu et ne brûle, sans qu’il y ait personne pour l’éteindre, à cause de l’iniquité de vos actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Annoncez en Juda, et faites entendre dans Jérusalem, et dites,... et sonnez de la trompette dans le pays; criez à plein gosier et dites: Assemblez-vous, et entrons dans les villes fortes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Élevez l’étendard vers Sion, fuyez, et ne vous arrêtez pas; car je fais venir du nord le mal et une grande ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Le lion est monté de son fourré, et le destructeur des nations s’est mis en chemin; il est sorti de son lieu pour mettre ton pays en désolation: tes villes seront dévastées, de sorte qu’il n’y aura pas d’habitant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'C’est pourquoi ceignez-vous de sacs, lamentez-vous, et hurlez; car l’ardeur de la colère de l’ Éternel ne s’est point détournée de nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Et il arrivera en ce jour-là, dit l’ Éternel, que le cœur du roi défaillira et le cœur des princes, et que les sacrificateurs seront étonnés, et les prophètes stupéfaits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Et je dis: Ah, Seigneur Éternel! certainement tu as bien trompé ce peuple et Jérusalem, en disant: Vous aurez la paix!... et l’épée est venue jusqu’à l’âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'En ce temps-là, il sera dit à ce peuple et à Jérusalem: Un vent sec [vient] des hauteurs du désert, dans le chemin de la fille de mon peuple, non pour vanner, ni pour purifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Un vent plus véhément que celui-là viendra de par moi; maintenant, moi aussi je prononcerai [mes] jugements sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Voici, il monte comme des nuées, et ses chars sont comme un tourbillon; ses chevaux, plus rapides que les aigles. Malheur à nous! car nous sommes détruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Lave ton cœur de l’iniquité, Jérusalem, afin que tu sois sauvée! Jusques à quand tes vaines pensées demeureront-elles au-dedans de toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Car une voix annonce de Dan, et, de la montagne d’Éphraïm, publie l’affliction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Faites savoir aux nations; voici, faites entendre à Jérusalem: Des assiégeants viennent d’un pays lointain et font retentir leur voix contre les villes de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Ils sont tout autour d’elle comme ceux qui gardent un champ; car elle s’est rebellée contre moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Ta voie et tes actions ont amené sur toi ces choses, c’est là ton iniquité; oui, c’est [une chose] amère; oui, elle pénètre jusqu’à ton cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Mes entrailles! mes entrailles! je suis dans la douleur! Les parois de mon cœur! Mon cœur bruit au-dedans de moi, je ne puis me taire; car, mon âme, tu entends le son de la trompette, la clameur de la guerre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Ruine sur ruine se fait entendre, car tout le pays est dévasté: soudain mes tentes sont dévastées, en un moment, mes courtines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Jusques à quand verrai-je l’étendard, entendrai-je la voix de la trompette?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Car mon peuple est fou, ils ne m’ont pas connu; ce sont des fils insensés, ils n’ont pas d’intelligence; ils sont sages pour faire le mal, mais ils ne savent pas faire le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'J’ai regardé la terre, et voici, elle était désolation et vide, et vers les cieux, et leur lumière n’était pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'J’ai regardé les montagnes, et voici, elles se remuaient, et toutes les collines branlaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'J’ai regardé, et voici, il n’y avait pas d’homme, et tous les oiseaux des cieux avaient fui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'J’ai regardé, et voici, le Carmel était un désert, et toutes ses villes étaient renversées devant l’ Éternel, devant l’ardeur de sa colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Car ainsi dit l’ Éternel: Tout le pays sera une désolation, mais je ne le détruirai pas entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'À cause de cela, la terre mènera deuil, et, au-dessus, les cieux seront noirs, parce que je l’ai dit, je l’ai pensé, et je ne m’en repentirai point et je n’en reviendrai point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Devant le bruit des cavaliers et des tireurs d’arc toute ville fuit: ils entrent dans les fourrés et montent sur les rochers; toute ville est abandonnée, et aucun homme n’y habite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Et toi, dévastée, que feras-tu? Tu as beau te revêtir d’écarlate, te parer d’ornements d’or, te déchirer les yeux avec du fard, tu te fais belle en vain: les amants te méprisent, ils cherchent ta vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Car j’ai entendu une voix comme celle d’une femme en travail, une angoisse comme d’une femme enfantant son premier-né, la voix de la fille de Sion; elle soupire, elle étend ses mains: Malheur à moi! car mon âme a défailli à cause des meurtriers!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, '*Courez çà et là par les rues de Jérusalem, et regardez et sachez et cherchez dans ses places si vous trouvez un homme, s’il y a quelqu’un qui fasse ce qui est droit, qui cherche la fidélité, et je pardonnerai à la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Et s’ils disent: L’ Éternel est vivant! en cela même, ils jurent faussement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Éternel! tes yeux ne [regardent-ils] pas à la fidélité? Tu les as frappés, mais ils n’en ont point ressenti de douleur; tu les as consumés, ils ont refusé de recevoir la correction; ils ont rendu leurs faces plus dures qu’un roc, ils ont refusé de revenir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Et j’ai dit: Voilà, ce sont de pauvres gens, ce sont des fous; car ils ne connaissent pas la voie de l’ Éternel, le jugement de leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Je m’en irai vers les grands, et je leur parlerai; car eux, ils connaissent la voie de l’ Éternel, le jugement de leur Dieu; mais ceux-ci, tous ensemble, ont brisé le joug, rompu les liens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'C’est pourquoi un lion de la forêt les frappera, un loup du soir les ravagera; le léopard veille devant leurs villes, quiconque en sort est déchiré; car leurs transgressions sont multipliées, leurs infidélités se sont renforcées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Pourquoi te pardonnerai-je? Tes fils m’ont abandonné, et ils jurent par ce qui n’est pas Dieu; je les ai rassasiés, et ils ont commis adultère, et sont allés en troupe dans la maison de la prostituée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Chevaux bien nourris, ils courent çà et là, chacun hennit après la femme de son prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Ne punirais-je pas de telles choses? dit l’ Éternel; et mon âme ne se vengerait-elle pas d’une nation comme celle-là?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Montez sur ses murailles, et détruisez! mais ne détruisez pas entièrement; ôtez ses créneaux, car ils ne sont pas à l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'car la maison d’Israël et la maison de Juda ont agi très perfidement envers moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Ils ont renié l’ Éternel, et ont dit: Il n’est pas! et le mal ne viendra pas sur nous; nous ne verrons ni l’épée ni la famine,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'et les prophètes seront du vent, et la parole n’est pas en eux: ainsi leur sera-t-il fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'C’est pourquoi, ainsi dit l’ Éternel, le Dieu des armées: Parce que vous avez prononcé cette parole, voici, je ferai que mes paroles dans ta bouche seront du feu, et ce peuple sera le bois, et le [feu] les consumera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Voici, je fais venir de loin une nation contre vous, maison d’Israël, dit l’ Éternel, une nation puissante, une nation ancienne, une nation dont tu ne sais pas la langue, et dont tu ne comprends pas la parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Son carquois est comme un sépulcre ouvert, ils sont tous des hommes vaillants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Elle dévorera ta moisson et ton pain, elle dévorera tes fils et tes filles, elle dévorera ton menu et ton gros bétail, elle dévorera ta vigne et ton figuier, elle détruira par l’épée tes villes fortes sur lesquelles tu te confiais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Mais, même en ces jours-là, dit l’ Éternel, je ne vous détruirai pas entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Et il arrivera que, quand vous direz: Pourquoi l’ Éternel, notre Dieu, nous a-t-il fait toutes ces choses? tu leur diras: Comme vous m’avez abandonné et que vous avez servi des dieux étrangers dans votre pays, ainsi vous servirez les étrangers dans un pays qui n’est pas le vôtre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Annoncez ceci dans la maison de Jacob, et faites-le entendre dans Juda, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Écoutez pourtant ceci, peuple insensé et sans intelligence, qui avez des yeux et ne voyez pas, qui avez des oreilles et n’entendez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Ne me craindrez-vous pas, dit l’ Éternel, ne tremblerez-vous pas devant moi, qui ai mis le sable pour limite à la mer, statut perpétuel, qu’elle n’outrepassera pas? Ses vagues se soulèvent, mais elles ne prévaudront pas; et elles bruient, mais elles ne l’outrepasseront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Mais ce peuple-ci a un cœur indocile et rebelle; ils se sont détournés, et s’en sont allés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'et ils n’ont pas dit dans leur cœur: Craignons pourtant l’ Éternel, notre Dieu, qui donne les pluies en leur temps, la pluie de la première saison et la pluie de la dernière saison, [et] qui nous garde les semaines ordonnées de la moisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Vos iniquités ont détourné ces choses, et vos péchés ont retenu de vous le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Car il se trouve des méchants parmi mon peuple; ils épient comme l’oiseleur qui se baisse, ils posent des pièges, ils prennent des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Comme une cage est pleine d’oiseaux, ainsi leurs maisons sont pleines de fraude; c’est pourquoi ils sont devenus grands et se sont enrichis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Ils sont devenus gras et luisants, aussi ils débordent de méchancetés; ils ne jugent pas la cause, la cause de l’orphelin, et ils prospèrent; et ils ne font pas droit aux pauvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Ne punirais-je pas de telles choses? dit l’ Éternel; mon âme ne se vengerait-elle pas d’une nation comme celle-là?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Une chose étonnante et horrible est arrivée dans le pays:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'les prophètes prophétisent avec mensonge, et les sacrificateurs dominent par leur moyen; et mon peuple l’aime ainsi. Et que ferez-vous à la fin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Fils de Benjamin, fuyez du milieu de Jérusalem, et sonnez de la trompette à Thekoa, et élevez un signal sur Beth-Hakkérem! car du nord apparaît le mal, et une grande ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'La belle et la délicate, la fille de Sion, je la détruis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Les pasteurs et leurs troupeaux viennent contre elle; ils dressent leurs tentes contre elle tout à l’entour; ils broutent chacun son quartier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Préparez le combat contre elle; levez-vous, et montons en plein midi. Malheur à nous! car le jour baisse, car les ombres du soir s’allongent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Levez-vous, et montons de nuit, et détruisons ses palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Car ainsi dit l’ Éternel des armées: Coupez des arbres, et élevez des terrasses contre Jérusalem: c’est la ville qui doit être visitée; tout est oppression au milieu d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Comme un puits fait couler ses eaux, ainsi elle fait sourdre son iniquité; on entend en elle la violence et la dévastation; il y a devant moi continuellement souffrance et blessure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Reçois instruction, ô Jérusalem, de peur que mon âme ne se détache de toi, de peur que je ne fasse de toi une désolation, une terre inhabitée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Ainsi dit l’ Éternel des armées: On grappillera entièrement, comme une vigne, le reste d’Israël. Remets, comme le vendangeur, ta main dans les paniers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'À qui parlerai-je, et qui avertirai-je, pour qu’ils entendent? Voici, leur oreille est incirconcise, et ils ne peuvent prêter attention; voici, la parole de l’ Éternel est en opprobre parmi eux, ils n’y trouvent point de plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Et je suis plein de la fureur de l’ Éternel, je suis las de la retenir. Verse-la sur les petits enfants dans la rue, et sur l’assemblée des jeunes gens réunis; car et l’homme et la femme seront pris, le vieillard et celui qui est comblé de jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Et leurs maisons passeront à d’autres, les champs et les femmes également; car j’étendrai ma main sur les habitants du pays, dit l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'car, depuis le petit d’entre eux jusqu’au grand, ils sont tous adonnés au gain déshonnête, et, depuis le prophète jusqu’au sacrificateur, tous usent de fausseté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Et ils ont pansé la plaie de la fille de mon peuple légèrement, disant: Paix, paix! et il n’y avait point de paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Avaient-ils honte, parce qu’ils avaient commis l’abomination? Ils n’ont eu même aucune honte, ils n’ont même pas connu la confusion; c’est pourquoi ils tomberont parmi ceux qui tombent; au temps où je les visiterai, ils trébucheront, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Ainsi dit l’ Éternel: Tenez-vous sur les chemins, et regardez, et enquérez-vous touchant les sentiers anciens, quelle est la bonne voie; et marchez-y, et vous trouverez du repos pour vos âmes. Mais ils ont dit: Nous n’y marcherons pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'J’ai aussi établi sur vous des sentinelles: soyez attentifs à la voix de la trompette. Mais ils ont dit: Nous n’y serons pas attentifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'C’est pourquoi, écoutez, nations; et toi, assemblée, sache ce qui est au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Écoute, terre: Voici, je fais venir un mal sur ce peuple, le fruit de leurs pensées; car ils n’ont pas été attentifs à mes paroles, et ma loi, ils l’ont rejetée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'À quoi me sert que l’encens vienne de Sheba, et le doux roseau du pays lointain? Vos holocaustes ne me sont pas agréables, et vos sacrifices ne me plaisent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'C’est pourquoi, ainsi dit l’ Éternel: Voici, je mets devant ce peuple des pierres d’achoppement, et les pères et les fils ensemble trébucheront contre elles, le voisin et son compagnon périront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Ainsi dit l’ Éternel: Voici, un peuple vient du pays du nord, et une grande nation se réveille des extrémités de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Ils saisissent l’arc et le javelot; ils sont cruels, et ils n’ont pas de compassion; leur voix bruit comme la mer, et ils sont montés sur des chevaux, préparés comme un homme pour la guerre, contre toi, fille de Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Nous en avons entendu la rumeur; nos mains sont devenues lâches, la détresse nous a saisis, l’angoisse comme celle d’une femme qui enfante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Ne sortez pas dans les champs, et n’allez point par le chemin; car l’épée de l’ennemi, la terreur est partout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Fille de mon peuple, ceins-toi d’un sac, et roule-toi dans la cendre; mène deuil comme pour un fils unique, [fais] une lamentation amère, car le dévastateur est venu subitement sur nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Je t’ai établi comme un essayeur au milieu de mon peuple, une forteresse, afin que tu connaisses et que tu éprouves leur voie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Ils sont tous des rebelles entre les rebelles; ils marchent dans la calomnie; ils sont de l’airain et du fer; ils sont tous des corrupteurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Le soufflet brûle, le plomb est consumé par le feu, on affine, on affine en vain: les mauvais n’ont point été ôtés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'On les nommera: Argent réprouvé; car l’ Éternel les a rejetés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, '*La parole qui vint à Jérémie de par l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Tiens-toi dans la porte de la maison de l’ Éternel, et là, crie cette parole et dis: Écoutez la parole de l’ Éternel, vous, tout Juda, qui entrez par ces portes pour vous prosterner devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Amendez vos voies et vos actions, et je vous ferai demeurer dans ce lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Ne mettez pas votre confiance en des paroles de mensonge, disant: C’est ici le temple de l’ Éternel, le temple de l’ Éternel, le temple de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Mais si vous amendez réellement vos voies et vos actions, si vous faites réellement la justice entre un homme et son prochain,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'si vous n’opprimez pas l’étranger, l’orphelin et la veuve, et que vous ne versiez pas le sang innocent dans ce lieu, et que vous ne marchiez pas après d’autres dieux pour votre dommage,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'je vous ferai demeurer dans ce lieu, dans le pays que j’ai donné à vos pères, de siècle en siècle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Voici, vous vous confiez en des paroles de mensonge, qui ne profitent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Quoi? voler, tuer, commettre adultère, jurer faussement, brûler de l’encens à Baal, marcher après d’autres dieux que vous ne connaissez pas!...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'et vous venez, et vous vous tenez devant moi dans cette maison qui est appelée de mon nom, et vous dites: Nous sommes délivrés pour faire toutes ces abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Cette maison qui est appelée de mon nom, est-elle une caverne de voleurs à vos yeux? Moi aussi, voici, je l’ai vu, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Car allez à mon lieu qui était à Silo, où j’ai fait demeurer mon nom au commencement, et regardez ce que je lui ai fait, à cause de l’iniquité de mon peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Et maintenant, parce que vous avez fait toutes ces actions, dit l’ Éternel, et que je vous ai parlé, me levant de bonne heure et parlant, et que vous n’avez pas écouté, et que je vous ai appelés et que vous n’avez pas répondu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'je ferai à cette maison qui est appelée de mon nom, en laquelle vous avez mis votre confiance, et au lieu que je vous ai donné, à vous et à vos pères, comme j’ai fait à Silo;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'et je vous chasserai de devant ma face, comme j’ai chassé tous vos frères, toute la semence d’Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Et toi, ne prie pas pour ce peuple, et ne fais monter pour eux ni cri ni prière; et n’insiste pas auprès de moi, car je ne t’écouterai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Ne vois-tu pas ce qu’ils font dans les villes de Juda, et dans les rues de Jérusalem?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Les fils ramassent le bois, et les pères allument le feu, et les femmes pétrissent la pâte pour faire des gâteaux à la reine des cieux, et pour répandre des libations à d’autres dieux, afin de me provoquer à colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Est-ce moi qu’ils provoquent à colère? dit l’ Éternel. N’est-ce pas eux-mêmes, à la honte de leur visage?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Voici, ma colère et ma fureur vont être versées sur ce lieu-ci, sur l’homme et sur la bête, sur l’arbre des champs et sur le fruit de la terre; et elles s’embraseront et ne s’éteindront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Ajoutez vos holocaustes à vos sacrifices, et mangez de la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Car je n’ai point parlé avec vos pères, et je ne leur ai point commandé touchant des holocaustes et des sacrifices, au jour où je les fis sortir du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Mais je leur ai commandé ceci, disant: Écoutez ma voix, et je serai votre Dieu, et vous serez mon peuple; et marchez dans toute la voie que je vous commande, afin que vous vous trouviez bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Et ils n’écoutèrent pas et n’inclinèrent pas leur oreille; mais ils marchèrent dans les conseils, dans l’obstination de leur mauvais cœur, et ils sont allés en arrière et non en avant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Depuis le jour où vos pères sortirent du pays d’Égypte, jusqu’à ce jour, je vous ai envoyé tous mes serviteurs les prophètes, chaque jour me levant de bonne heure, et les envoyant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Mais ils ne m’ont point écouté, et ils n’ont point incliné leur oreille; et ils ont roidi leur cou, ils ont fait pis que leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Et tu leur diras toutes ces paroles, mais ils ne t’écouteront pas; et tu crieras après eux, mais ils ne te répondront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Et tu leur diras: C’est ici la nation qui n’a point écouté la voix de l’ Éternel, son Dieu, et qui n’a point accepté la correction; la fidélité a péri, et est retranchée de leur bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Coupe ta chevelure, et jette-la loin, et, sur les hauteurs, élève une complainte; car l’ Éternel a rejeté et abandonné la génération de sa colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Car les fils de Juda ont fait ce qui est mauvais à mes yeux, dit l’ Éternel; ils ont mis leurs abominations dans la maison qui est appelée de mon nom, pour la rendre impure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Et ils ont bâti les hauts lieux de Topheth, qui est dans la vallée du fils de Hinnom, pour brûler au feu leurs fils et leurs filles, ce que je n’ai point commandé et qui ne m’est point monté au cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'C’est pourquoi, voici, des jours viennent, dit l’ Éternel, où l’on ne dira plus Topheth et la vallée du fils de Hinnom, mais la vallée de la tuerie; et on enterrera à Topheth, jusqu’à ce qu’il n’y ait plus de place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Et les cadavres de ce peuple seront en pâture aux oiseaux des cieux et aux bêtes de la terre, et il n’y aura personne qui les effraie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Et je ferai cesser dans les villes de Juda et dans les rues de Jérusalem la voix de l’allégresse et la voix de la joie, la voix de l’époux et la voix de l’épouse; car le pays deviendra un désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'En ce temps-là, dit l’ Éternel, on sortira de leurs sépulcres les os des rois de Juda, et les os de ses princes, et les os des sacrificateurs, et les os des prophètes, et les os des habitants de Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'et on les étendra devant le soleil, et devant la lune, et devant toute l’armée des cieux, qu’ils ont aimés, et qu’ils ont servis, et après lesquels ils ont marché, et qu’ils ont recherchés, et devant lesquels ils se sont prosternés: ils ne seront pas recueillis, et ne seront pas enterrés; ils seront du fumier sur la face du sol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Et tout le résidu choisira la mort plutôt que la vie, ceux qui restent de cette méchante famille dans tous les lieux où j’aurai chassé ceux qui sont de reste, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Et tu leur diras: Ainsi dit l’ Éternel: Est-ce qu’on tombe, et qu’on ne se relève pas? Est-ce qu’on se détourne, et qu’on ne revient pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Pourquoi ce peuple de Jérusalem s’est-il détourné par un égarement continuel? Ils tiennent ferme à la tromperie, ils refusent de revenir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'J’ai fait attention, et j’ai écouté: ils ne parlent pas droitement, il n’y a personne qui se repente de son iniquité, disant: Qu’ai-je fait? Tous ils retournent à leur course, comme le cheval qui se précipite dans la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Même la cigogne dans les cieux connaît sa saison; et la tourterelle, et l’hirondelle, et la grue, prennent garde au temps où elles doivent venir, mais mon peuple ne connaît pas le jugement de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Comment dites-vous: Nous sommes sages, et la loi de l’ Éternel est avec nous? – Mais voici, la plume menteuse des scribes [en] a fait une fausseté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Les sages sont couverts de honte, ils ont peur, et sont pris; voici, ils ont méprisé la parole de l’ Éternel, et quelle sagesse ont-ils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'C’est pourquoi je donnerai leurs femmes à d’autres, leurs champs à ceux qui les posséderont; car depuis le petit jusqu’au grand, ils sont tous adonnés au gain déshonnête; depuis le prophète jusqu’au sacrificateur, tous usent de fausseté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Et ils ont pansé la plaie de la fille de mon peuple légèrement, disant: Paix, paix! et il n’y avait point de paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Avaient-ils honte, parce qu’ils avaient commis l’abomination? Ils n’ont eu même aucune honte, et ils ne savent pas ce que c’est que d’être confus; c’est pourquoi ils tomberont parmi ceux qui tombent; au temps de leur visitation ils trébucheront, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Je les ôterai entièrement, dit l’ Éternel. Il n’y a pas de raisins sur la vigne, et pas de figues sur le figuier, et la feuille est flétrie; et je les livrerai à ceux qui passeront sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Pourquoi sommes-nous là assis? Assemblez-vous, et entrons dans les villes fortes, et là nous garderons le silence; car l’ Éternel, notre Dieu, nous a réduits au silence et nous a fait boire de l’eau de fiel, car nous avons péché contre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'On attend la paix, et il n’y a rien de bon, – le temps de la guérison, et voici l’épouvante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'De Dan nous avons entendu le ronflement de ses chevaux; au bruit des hennissements de ses puissants [coursiers] tout le pays a tremblé; ils sont venus, et ont dévoré le pays et ce qu’il contient, la ville et ceux qui y habitent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Car voici, j’envoie au milieu de vous des serpents, des vipères, contre lesquels il n’y a point de charmes, et ils vous mordront, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Ô ma consolation dans ma douleur! Mon cœur est languissant au-dedans de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Voici, la voix du cri de la fille de mon peuple [vient] d’un pays lointain: L’ Éternel n’est-il pas dans Sion? Son Roi n’est-il pas au milieu d’elle? Pourquoi m’ont-ils provoqué par leurs images taillées, par les vanités de l’étranger?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'La moisson est passée, l’été est fini, et nous ne sommes pas sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Je suis brisé de la ruine de la fille de mon peuple; je mène deuil, l’épouvante m’a saisi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'N’y a-t-il point de baume en Galaad? N’y a-t-il point là de médecin? Car pourquoi n’a-t-on pas appliqué un appareil de pansement à la fille de mon peuple?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 23, 'Oh! ma tête, que n’est-elle des eaux, et mes yeux, une fontaine de larmes! et je pleurerais jour et nuit les blessés à mort de la fille de mon peuple!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Oh! qui me donnera dans le désert une cabane de voyageur! et j’abandonnerais mon peuple et je m’en irais d’avec eux; car ils sont tous des adultères, une assemblée de perfides.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Et ils bandent leur langue, leur arc de mensonge, et ils ne sont pas vaillants dans le pays pour la fidélité; car ils passent d’iniquité en iniquité, et ne me connaissent pas, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Gardez-vous chacun de son ami, et ne vous confiez en aucun frère; car tout frère ne fera que supplanter, et tout ami marche dans la calomnie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Et chacun d’eux trompe son ami, et ne dit pas la vérité; ils ont enseigné leur langue à dire le mensonge, ils se fatiguent à faire le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Ton habitation est au milieu de la tromperie; à cause de la tromperie ils refusent de me connaître, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'C’est pourquoi, ainsi dit l’ Éternel des armées: Voici, je vais les affiner et les éprouver; car comment agirais-je à l’égard de la fille de mon peuple?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Leur langue est une flèche mortelle, elle profère la tromperie; de sa bouche il parle de paix avec son ami, mais au-dedans il lui dresse des embûches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Ne les punirais-je pas à cause de ces choses? dit l’ Éternel; mon âme ne se vengerait-elle pas d’une nation comme celle-là?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'J’élèverai une voix de pleurs et une lamentation sur les montagnes, et une complainte sur les pâturages du désert, car ils sont brûlés, de sorte que personne n’y passe et qu’on n’y entend pas la voix des troupeaux; tant les oiseaux des cieux que les bêtes ont fui; ils s’en sont allés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Et je ferai de Jérusalem des monceaux [de ruines], un repaire de chacals; et des villes de Juda, j’en ferai une désolation, de sorte qu’il n’y aura plus d’habitant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Qui est l’homme sage? qu’il comprenne cela. Et celui à qui la bouche de l’ Éternel a parlé, qu’il le déclare! Pourquoi le pays périt-il, [et] est-il brûlé comme un désert, de sorte que personne n’y passe?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Et l’ Éternel dit: Parce qu’ils ont abandonné ma loi que j’avais mise devant eux, et qu’ils n’ont pas écouté ma voix, et parce qu’ils n’ont pas marché en elle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'et qu’ils ont marché suivant le penchant obstiné de leur cœur et après les Baals, ce que leurs pères leur ont enseigné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'C’est pourquoi, ainsi dit l’ Éternel des armées, le Dieu d’Israël: Voici, je vais faire manger de l’absinthe à ce peuple, et je leur ferai boire de l’eau de fiel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'et je les disperserai parmi les nations qu’ils n’ont pas connues, eux et leurs pères; et j’enverrai après eux l’épée, jusqu’à ce que je les aie consumés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Ainsi dit l’ Éternel des armées: Considérez, et appelez les pleureuses, et qu’elles viennent; et envoyez vers les femmes sages, et qu’elles viennent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'et qu’elles se hâtent, et qu’elles élèvent une [voix de] lamentation sur nous, et que nos yeux se fondent en larmes, et que l’eau coule de nos paupières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Car une voix de lamentation se fait entendre de Sion: Comme nous sommes détruits, [et] devenus fort honteux! car nous avons abandonné le pays, car ils ont jeté à bas nos demeures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Vous, femmes, écoutez donc la parole de l’ Éternel, et que votre oreille reçoive la parole de sa bouche; et enseignez à vos filles la lamentation, et chacune à son amie la complainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Car la mort est montée par nos fenêtres, elle est entrée dans nos palais, pour retrancher de la rue les petits enfants, [et] des places, les jeunes hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Dis: Ainsi dit l’ Éternel: Oui, le cadavre de l’homme tombera comme du fumier sur la face des champs, et comme la gerbe après le moissonneur, et il n’y a personne qui la recueille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Ainsi dit l’ Éternel: Que le sage ne se glorifie pas dans sa sagesse, et que l’homme vaillant ne se glorifie pas dans sa vaillance; que le riche ne se glorifie pas dans sa richesse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'mais que celui qui se glorifie, se glorifie en ceci, qu’il a de l’intelligence et qu’il me connaît; car je suis l’ Éternel, qui use de bonté, de jugement et de justice sur la terre, car je trouve mes délices en ces choses-là, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Voici, des jours viennent, dit l’ Éternel, et je punirai tous les circoncis avec les incirconcis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'l’Égypte, et Juda, et Édom, et les fils d’Ammon, et Moab, et tous ceux qui coupent les coins [de leur barbe], lesquels habitent le désert; car toutes les nations sont incirconcises, et toute la maison d’Israël est incirconcise de cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, '*Écoutez la parole que l’ Éternel vous dit, maison d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Ainsi dit l’ Éternel: N’apprenez pas le chemin des nations, et ne soyez pas effrayés des signes des cieux, car les nations s’en effraient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Car les statuts des peuples sont vanité; car [c’est] un bois coupé de la forêt, façonné au ciseau par la main d’un artisan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'on l’embellit avec de l’argent et de l’or; on le fait tenir avec des clous et des marteaux, afin qu’il ne bouge pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Ils sont comme une colonne faite au tour: ils ne parlent point; on les porte, car ils ne marchent pas. Ne les craignez pas, car ils ne peuvent pas faire du mal, et aussi il n’est pas en leur pouvoir de faire du bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Nul n’est semblable à toi, ô Éternel! Tu es grand, et ton nom est grand en force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Qui ne te craindrait, Roi des nations? Car cela t’est dû; car, parmi tous les sages des nations et dans tous leurs royaumes, nul n’est comme toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'mais jusqu’au dernier ils sont stupides et fous: l’enseignement des vanités est du bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'L’argent en plaques est apporté de Tarsis, et l’or d’Uphaz, ouvrage de l’artisan et des mains du fondeur; le bleu et la pourpre sont leur vêtement: ils sont tous l’ouvrage de gens de l’art.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Mais l’ Éternel Dieu est vérité, lui est le Dieu vivant et le Roi d’éternité; devant son courroux la terre est ébranlée, et les nations ne peuvent [soutenir] son indignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Vous leur direz ainsi: Les dieux qui n’ont pas fait les cieux et la terre, ceux-là périront de la terre et de dessous les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'C’est lui qui a fait la terre par sa puissance, qui a établi le monde par sa sagesse, et qui, par son intelligence, a étendu les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Quand il fait retentir sa voix, il y a un tumulte d’eaux dans les cieux, et il fait monter les vapeurs du bout de la terre; il fait les éclairs pour la pluie, et de ses trésors il tire le vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Tout homme est devenu stupide, en sorte qu’il n’a pas de connaissance; tout fondeur a honte de l’image taillée, car son image de fonte est un mensonge; il n’y a point de respiration en elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Elles sont vanité, un ouvrage de déception: elles périront au temps de leur visitation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'La portion de Jacob n’est pas comme elles, car c’est Celui qui a tout formé, et Israël est la verge de son héritage: son nom est l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Ramasse, [et porte hors] du pays ce qui t’appartient, toi qui habites la forteresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Car ainsi dit l’ Éternel: Voici, cette fois je vais lancer, comme avec une fronde, les habitants du pays; et je ferai venir sur eux la détresse, afin qu’on les trouve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Malheur à moi, à cause de ma ruine! ma plaie est douloureuse. Et moi j’ai dit: C’est ici mon mal, et je le supporterai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Ma tente est dévastée et toutes mes cordes sont rompues; mes fils sont sortis d’auprès de moi, et ils ne sont plus; personne ne tend plus ma tente et n’arrange mes courtines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Car les pasteurs sont stupides, et n’ont pas cherché l’ Éternel. C’est pourquoi ils n’ont pas agi sagement, et tout leur troupeau est dispersé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Le bruit d’une rumeur! Voici, elle vient, et une grande commotion du pays du nord, pour réduire les villes de Juda en désolation, en repaire de chacals.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Je sais, Éternel, que la voie de l’homme n’est pas à lui, qu’il n’est pas au pouvoir de l’homme qui marche de diriger ses pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Éternel! corrige-moi, mais avec mesure, non dans ta colère, de peur que tu ne me rendes chétif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Verse ta fureur sur les nations qui ne t’ont pas connu et sur les familles qui n’invoquent pas ton nom; car elles ont dévoré Jacob: ils l’ont dévoré, et ils l’ont consumé, et ils ont désolé son habitation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, '*La parole qui vint à Jérémie de par l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Écoutez les paroles de cette alliance, et parlez aux hommes de Juda et aux habitants de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Et tu leur diras: Ainsi dit l’ Éternel, le Dieu d’Israël: Maudit l’homme qui n’écoute pas les paroles de cette alliance');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'que j’ai commandée à vos pères au jour où je les ai fait sortir du pays d’Égypte, de la fournaise de fer, disant: Écoutez ma voix, et faites ces [paroles] selon tout ce que je vous ai commandé, et vous serez mon peuple, et moi je serai votre Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'afin que j’accomplisse le serment que j’ai juré à vos pères, de leur donner un pays ruisselant de lait et de miel, comme [il paraît] aujourd’hui. Et je répondis et dis: Amen! ô Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Et l’ Éternel me dit: Proclame toutes ces paroles dans les villes de Juda, et dans les rues de Jérusalem, disant: Écoutez les paroles de cette alliance, et faites-les;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'car j’ai protesté à vos pères, au jour où je les ai fait monter du pays d’Égypte jusqu’à ce jour, me levant de bonne heure et protestant, en disant: Écoutez ma voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Mais ils n’ont pas écouté, et n’ont pas incliné leur oreille; mais ils ont marché chacun dans l’obstination de leur mauvais cœur; et j’ai fait venir sur eux toutes les paroles de cette alliance que j’avais commandé de faire, et qu’ils n’ont pas faite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Et l’ Éternel me dit: Il a été trouvé une conjuration parmi les hommes de Juda et parmi les habitants de Jérusalem:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'ils sont retournés aux iniquités de leurs premiers pères qui ont refusé d’écouter mes paroles, et ils ont marché après d’autres dieux pour les servir. La maison d’Israël et la maison de Juda ont rompu mon alliance que j’avais faite avec leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'C’est pourquoi, ainsi dit l’ Éternel: Voici, je fais venir sur eux un mal dont ils ne pourront pas sortir; et ils crieront à moi, et je ne les écouterai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Alors les villes de Juda et les habitants de Jérusalem s’en iront, et crieront aux dieux auxquels ils ont brûlé de l’encens; mais ils ne les sauveront point au temps de leur malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Car le nombre de tes dieux est celui de tes villes, ô Juda! et selon le nombre des rues de Jérusalem vous avez dressé des autels à cette honteuse [idole], des autels pour brûler de l’encens à Baal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Et toi, ne prie pas pour ce peuple, et ne fais monter pour eux ni cri ni prière; car je n’écouterai pas au temps où ils crieront vers moi au sujet de leur malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Que vient faire mon bien-aimé dans ma maison, alors que la multitude pratique ses mauvais desseins, et que la chair sainte passe loin de toi? Quand tu as mal fait, alors tu t’égaies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'L’ Éternel avait appelé ton nom Olivier vert, beau de son fruit excellent. Au bruit d’un grand tumulte il a allumé un feu contre lui, et ses branches sont cassées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'et l’ Éternel des armées qui t’a planté, a prononcé le mal contre toi, à cause de l’iniquité de la maison d’Israël et de la maison de Juda, qu’elles ont commise contre elles-mêmes, pour me provoquer à colère en brûlant de l’encens à Baal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Et l’ Éternel me l’a fait savoir, et je l’ai connu: alors tu m’as montré leurs actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Et moi j’étais comme un agneau familier qui est mené à la tuerie; et je ne savais pas qu’ils faisaient des complots contre moi, [disant]: Détruisons l’arbre avec son fruit, et retranchons-le de la terre des vivants, afin qu’on ne se souvienne plus de son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Et toi, Éternel des armées, qui juges justement, qui éprouves les reins et le cœur, fais que je voie ta vengeance sur eux; car à toi j’ai découvert ma cause.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'C’est pourquoi, ainsi dit l’ Éternel touchant les hommes d’Anathoth qui cherchent ta vie, disant: Ne prophétise pas au nom de l’ Éternel, afin que tu ne meures pas par nos mains; –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'c’est pourquoi, ainsi dit l’ Éternel des armées: Voici, je les punis: les jeunes hommes mourront par l’épée, leurs fils et leurs filles mourront par la famine,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'et il ne restera rien d’eux; car je ferai venir du mal sur les hommes d’Anathoth, en l’année de leur visitation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Éternel! tu es juste quand je conteste avec toi; toutefois je parlerai avec toi de [tes] jugements. Pourquoi la voie des méchants est-elle prospère? [Pourquoi] ceux qui agissent très perfidement sont-ils en paix?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Tu les as plantés, même ils prennent racine; ils progressent, même ils portent du fruit. Tu es près, dans leur bouche, mais tu es loin de leurs reins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Mais toi, Éternel! tu me connais, tu m’as vu, et tu as éprouvé mon cœur à ton égard. Traîne-les comme des brebis à la tuerie, et mets-les à part pour le jour de la tuerie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Jusques à quand le pays mènera-t-il deuil et l’herbe de tous les champs séchera-t-elle? À cause de l’iniquité de ceux qui y habitent, le bétail et les oiseaux périssent; car ils disent: Il ne verra pas notre fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Si tu as couru avec les piétons, et qu’ils t’aient lassé, comment rivaliseras-tu avec les chevaux? Et si, dans une terre de paix, tu te crois en sécurité, que feras-tu quand le Jourdain sera enflé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Car tes frères aussi et la maison de ton père, eux aussi ont agi perfidement envers toi, eux aussi ont crié après toi à plein gosier. Ne les crois point, même s’ils te disent de bonnes [paroles].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'J’ai abandonné ma maison, j’ai délaissé mon héritage, j’ai livré le bien-aimé de mon âme en la main de ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mon héritage m’est devenu comme un lion dans la forêt; il a fait retentir sa voix contre moi, c’est pourquoi je l’ai haï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Mon héritage m’est comme un oiseau de proie tacheté; les oiseaux de proie sont contre lui, tout à l’entour. Venez, assemblez toutes les bêtes des champs, faites-les venir pour dévorer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Plusieurs pasteurs ont gâté ma vigne, ils ont foulé mon lot, ils ont réduit le lot de mon désir en un désert aride;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'on en a fait une désolation; tout désolé, il mène deuil devant moi; toute la terre est dévastée, car personne ne la prend à cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Sur toutes les hauteurs dans le désert sont venus les destructeurs; car l’épée de l’ Éternel dévore depuis un bout du pays jusqu’à l’autre bout du pays: il n’y a de paix pour aucune chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Ils ont semé du froment, et ils moissonnent des épines; ils se sont tourmentés, [et] ils n’en ont pas eu de profit: soyez confus du rapport de vos [champs], à cause de l’ardeur de la colère de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Ainsi dit l’ Éternel contre tous mes mauvais voisins qui mettent la main sur l’héritage que j’ai fait hériter à mon peuple, à Israël: Voici, je les arracherai de dessus leur sol, et j’arracherai la maison de Juda du milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Et il arrivera qu’après que je les aurai arrachés, je leur ferai de nouveau miséricorde et je les ferai retourner chacun à son héritage et chacun dans son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Et il arrivera que, s’ils apprennent diligemment les voies de mon peuple, pour jurer par mon nom: L’ Éternel est vivant! comme ils ont enseigné à mon peuple à jurer par Baal, ils seront édifiés au milieu de mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Et s’ils n’écoutent pas, j’arracherai entièrement cette nation-là et je la ferai périr, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, '*Ainsi m’a dit l’ Éternel: Va, et achète-toi une ceinture de lin, et mets-la sur tes reins, et ne la trempe pas dans l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Et j’achetai une ceinture, selon la parole de l’ Éternel, et je la mis sur mes reins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Et la parole de l’ Éternel vint à moi pour la seconde fois, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Prends la ceinture que tu as achetée, qui est sur tes reins, et lève-toi, va vers l’Euphrate, et là, cache-la dans le creux d’un rocher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Et je m’en allai, et la cachai dans l’Euphrate, comme l’ Éternel m’avait commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Et il arriva, à la fin de plusieurs jours, que l’ Éternel me dit: Lève-toi, va vers l’Euphrate, et prends de là la ceinture que je t’avais commandé d’y cacher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Et je m’en allai vers l’Euphrate, et je creusai, et je pris la ceinture du lieu où je l’avais cachée; et voici, la ceinture était gâtée, elle n’était plus bonne à rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Ainsi dit l’ Éternel: C’est ainsi que je détruirai l’orgueil de Juda, et le grand orgueil de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Ce peuple mauvais, qui refuse d’écouter mes paroles, qui marche dans l’obstination de son cœur, et qui marche après d’autres dieux pour les servir et pour se prosterner devant eux, sera comme cette ceinture qui n’est bonne à rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Car, comme une ceinture s’attache aux reins d’un homme, ainsi je me suis attaché toute la maison d’Israël et toute la maison de Juda, dit l’ Éternel, pour être mon peuple, et un renom, et une louange, et un ornement; mais ils n’ont pas écouté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Et tu leur diras cette parole: Ainsi dit l’ Éternel, le Dieu d’Israël: Toute cruche sera remplie de vin. Et ils te diront: Ne savons-nous pas bien que toute cruche sera remplie de vin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Et tu leur diras: Ainsi dit l’ Éternel: Voici, je remplis d’ivresse tous les habitants de ce pays, et les rois [issus] de David, qui sont assis sur son trône, et les sacrificateurs, et les prophètes, et tous les habitants de Jérusalem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'et je les briserai l’un contre l’autre, et les pères et les fils ensemble, dit l’ Éternel; je n’aurai pas de compassion, et je n’épargnerai pas, et je n’aurai pas de pitié pour ne pas les détruire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Écoutez, et prêtez l’oreille! Ne vous élevez point, car l’ Éternel a parlé!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Donnez gloire à l’ Éternel, votre Dieu, avant qu’il fasse venir des ténèbres, et avant que vos pieds se heurtent contre les montagnes du crépuscule: vous attendrez la lumière, et il en fera une ombre de mort et la réduira en obscurité profonde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Et si vous n’écoutez pas ceci, mon âme pleurera en secret à cause de votre orgueil, et mon œil pleurera amèrement et se fondra en larmes, car le troupeau de l’ Éternel est allé en captivité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Parle au roi et à la reine: Humiliez-vous, asseyez-vous [par terre]; car la couronne de votre magnificence est descendue de dessus vos têtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Les villes du midi sont fermées, et il n’y a personne qui les ouvre; tout Juda est transporté, il est tout entier transporté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Levez vos yeux, et voyez ceux qui viennent du nord. Où est le troupeau qui t’a été donné, le troupeau de ta gloire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Que diras-tu quand il te punira? Toi-même tu les as enseignés à être princes et chefs sur toi. Les douleurs ne te saisiront-elles pas comme une femme qui enfante?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Et si tu dis en ton cœur: Pourquoi me sont arrivées ces choses? C’est par la multitude de tes iniquités que les pans de ta robe ont été découverts, [et] que tes talons ont été violemment déchaussés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'L’Éthiopien peut-il changer sa peau, et le léopard ses taches? [Alors] aussi vous pourrez faire le bien, vous qui êtes instruits à faire le mal. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Et je les disperserai comme le chaume qui s’en va par le vent du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'C’est là ton lot, ta portion mesurée de par moi, dit l’ Éternel, parce que tu m’as oublié, et que tu t’es confiée au mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Et moi aussi, je relèverai tes pans sur ton visage, et ta honte se verra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Tes adultères, tes hennissements, l’infamie de ta prostitution sur les collines, dans les champs, – tes abominations, je [les] ai vues. Malheur à toi, Jérusalem! Ne te purifieras-tu pas,... après combien de temps encore?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, '*La parole de l’ Éternel qui vint à Jérémie au sujet de la sécheresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Juda mène deuil, et ses portes défaillent; elles sont en deuil, par terre; et le cri de Jérusalem est monté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Et ses nobles ont envoyé à l’eau les petits; ils sont allés aux citernes, ils n’ont pas trouvé d’eau; ils sont revenus, leurs vases vides; ils ont eu honte, ils ont été confus, et ils ont couvert leur tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Parce que la terre est crevassée, parce qu’il n’y a point eu de pluie dans le pays, les cultivateurs sont honteux, ils ont couvert leur tête;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'car aussi la biche a mis bas dans les champs, et a abandonné [son faon], parce qu’il n’y a point d’herbe verte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'et les ânes sauvages se sont tenus sur les hauteurs, ils ont humé l’air comme des chacals; leurs yeux se sont consumés, parce qu’il n’y a point d’herbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Éternel! si nos iniquités rendent témoignage contre nous, agis à cause de ton nom; car nos infidélités sont multipliées, nous avons péché contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Attente d’Israël, celui qui le sauve au temps de la détresse! pourquoi serais-tu comme un étranger dans le pays, comme un voyageur qui se détourne pour passer la nuit?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Pourquoi serais-tu comme un homme stupéfait, comme un homme fort qui ne peut sauver? Toutefois tu es au milieu de nous, ô Éternel, et nous sommes appelés de ton nom; ne nous délaisse pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Ainsi dit l’ Éternel à ce peuple: C’est ainsi qu’ils ont aimé à aller çà et là, ils n’ont pas retenu leurs pieds; et l’ Éternel ne prend point plaisir en eux: maintenant il se souviendra de leurs iniquités et il visitera leurs péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Et l’ Éternel me dit: Ne prie pas pour ce peuple pour leur bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'S’ils jeûnent, je n’écouterai pas leur cri, et s’ils offrent un holocauste et une offrande de gâteau, je ne les agréerai pas; car je les consumerai par l’épée, et par la famine, et par la peste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Et je dis: Ah, Seigneur Éternel! voici, les prophètes leur disent: Vous ne verrez pas l’épée, et la famine ne viendra pas sur vous; car je vous donnerai une vraie paix en ce lieu-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Et l’ Éternel me dit: Les prophètes prophétisent le mensonge en mon nom; je ne les ai pas envoyés, et je ne leur ai pas commandé, et je ne leur ai pas parlé; ils vous prophétisent une vision de mensonge, et la divination, et la vanité, et la tromperie de leur cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'C’est pourquoi, ainsi dit l’ Éternel au sujet des prophètes qui prophétisent en mon nom, et que je n’ai point envoyés, et qui disent: L’épée et la famine ne seront pas dans ce pays: Ces prophètes-là seront consumés par l’épée et par la famine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Et le peuple auquel ils prophétisent sera jeté dans les rues de Jérusalem à cause de la famine et de l’épée, et il n’y aura personne pour les enterrer, eux, leurs femmes, et leurs fils, et leurs filles; et je verserai sur eux leur iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Et tu leur diras cette parole: Que mes yeux se fondent en larmes, nuit et jour, et qu’ils ne cessent pas, car la vierge, fille de mon peuple, est ruinée d’une grande ruine, d’un coup très douloureux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Si je sors aux champs, voici des gens tués par l’épée, et si j’entre dans la ville, voici des gens alanguis par la faim; car prophète et sacrificateur s’en iront dans un pays qu’ils ne connaissent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Aurais-tu entièrement rejeté Juda? Ton âme serait-elle dégoûtée de Sion? Pourquoi nous as-tu frappés sans qu’il y ait de guérison pour nous? On attendait la paix, et il n’y a rien de bon, – et le temps de la guérison, et voici l’épouvante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Nous reconnaissons, ô Éternel! notre méchanceté, l’iniquité de nos pères; car nous avons péché contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'À cause de ton nom, ne [nous] dédaigne point, n’avilis pas le trône de ta gloire; souviens-toi, ne romps pas ton alliance avec nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Parmi les vanités des nations, en est-il qui donnent la pluie? ou les cieux donnent-ils des ondées? N’est-ce pas toi, Éternel! notre Dieu? Et nous nous attendons à toi; car c’est toi qui as fait toutes ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Et l’ Éternel me dit: Quand Moïse et Samuel se tiendraient devant moi, mon âme ne serait pas [tournée] vers ce peuple; renvoie-les de devant moi, et qu’ils sortent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Et il arrivera que, s’ils te disent: Où sortirons-nous? tu leur diras: Ainsi dit l’ Éternel: Ceux qui sont pour la mort, à la mort; et ceux qui sont pour l’épée, à l’épée; et ceux qui sont pour la famine, à la famine; et ceux qui sont pour la captivité, à la captivité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Et j’établirai sur eux quatre espèces de punitions, dit l’ Éternel: l’épée pour tuer, et les chiens pour traîner, et les oiseaux des cieux et les bêtes de la terre pour dévorer et pour détruire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Et je les livrerai pour être chassés çà et là par tous les royaumes de la terre, à cause de Manassé, fils d’Ézéchias, roi de Juda, pour ce qu’il a fait dans Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Car qui aurait compassion de toi, Jérusalem, et qui te plaindrait? et qui se détournerait pour s’enquérir de ta paix?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Tu m’as délaissé, dit l’ Éternel, tu t’en es allée en arrière; et j’ai étendu ma main sur toi, et je te détruirai: je suis las de me repentir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Je les vannerai avec un van aux portes du pays; je priverai d’enfants [et] je ferai périr mon peuple: ils ne reviennent pas de leurs voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Les veuves sont multipliées devant moi plus que le sable des mers; je fais venir contre eux, sur la mère des jeunes hommes, un dévastateur en plein midi; je fais tomber sur elle subitement l’angoisse et l’épouvante;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'celle qui en avait enfanté sept languit, elle rend l’âme; son soleil s’est couché pendant qu’il faisait encore jour; elle est couverte de honte et d’opprobre. Et ce qui reste d’eux, je le livrerai à l’épée devant leurs ennemis, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Malheur à moi, ma mère! de ce que tu m’as enfanté homme de débat et homme de contestation à tout le pays; je n’ai pas prêté à usure, on ne m’a pas prêté à usure, [et] chacun me maudit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'L’ Éternel dit: Si je ne te délivre pour le bien! Si je ne fais venir au-devant de toi l’ennemi, au temps du malheur, et au temps de la détresse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Le fer se brisera-t-il, le fer du nord et l’airain? –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Tes biens et tes trésors, je les livrerai au pillage, sans en faire le prix, et [cela] à cause de tous tes péchés, et dans tous tes confins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'et je [les] ferai passer avec tes ennemis dans un pays que tu ne connais pas; car un feu est allumé dans ma colère, il brûlera contre vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Tu le sais, ô Éternel! Souviens-toi de moi, et visite-moi, et venge-moi de mes persécuteurs. Selon la lenteur de ta colère, ne m’enlève pas; sache que, pour toi, je porte l’opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Tes paroles se sont-elles trouvées, je les ai mangées; et tes paroles ont été pour moi l’allégresse et la joie de mon cœur; car je suis appelé de ton nom, ô Éternel, Dieu des armées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Je ne me suis pas assis dans l’assemblée des moqueurs, ni ne me suis égayé: à cause de ta main, je me suis assis solitaire, parce que tu m’as rempli d’indignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Pourquoi ma douleur est-elle continuelle, et ma plaie, incurable? Elle refuse d’être guérie. Me serais-tu bien comme une source qui trompe, comme des eaux qui ne sont pas constantes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'C’est pourquoi, ainsi dit l’ Éternel: Si tu te retournes, je te ramènerai, tu te tiendras devant moi; et si tu sépares ce qui est précieux de ce qui est vil, tu seras comme ma bouche. Qu’ils reviennent vers toi, mais toi ne retourne pas vers eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Et je te ferai être à l’égard de ce peuple une muraille d’airain bien forte; ils combattront contre toi, mais ils ne prévaudront pas sur toi; car je suis avec toi pour te sauver et pour te délivrer, dit l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'et je te délivrerai de la main des iniques et te rachèterai de la main des violents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Tu ne te prendras point de femme et tu n’auras point de fils ni de filles en ce lieu-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Car ainsi dit l’ Éternel touchant les fils et les filles qui naissent en ce lieu, et touchant leurs mères qui les enfantent, et touchant les pères qui les engendrent dans ce pays:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Ils mourront de morts misérables; ils ne seront pas pleurés, et ne seront pas enterrés; ils seront du fumier sur la face du sol, et ils seront consumés par l’épée et par la famine, et leurs cadavres seront en pâture aux oiseaux des cieux et aux bêtes de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Car ainsi dit l’ Éternel: N’entre pas dans la maison de lamentation, et ne va pas pour pleurer, et ne mène pas deuil sur eux; car j’ai ôté à ce peuple, dit l’ Éternel, ma paix, – la bonté, et les compassions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Et grands et petits mourront dans ce pays; ils ne seront pas enterrés, et on ne les pleurera point, et on ne se fera pas d’incision, ni ne se rendra chauve à cause d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Et on ne rompra pas pour eux le pain dans le deuil, en consolation au sujet d’un mort, et on ne leur donnera pas à boire la coupe des consolations pour leur père ou pour leur mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Et tu n’entreras pas dans une maison de festin afin de t’asseoir avec eux pour manger et pour boire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Car ainsi dit l’ Éternel des armées, le Dieu d’Israël: Voici, je vais faire cesser dans ce lieu-ci, devant vos yeux et en vos jours, la voix de l’allégresse et la voix de la joie, la voix de l’époux et la voix de l’épouse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Et il arrivera que, quand tu annonceras à ce peuple toutes ces paroles, et qu’ils te diront: Pourquoi l’ Éternel dit-il contre nous tout ce grand mal, et quelle est notre iniquité, et quel est notre péché que nous avons commis contre l’ Éternel, notre Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'alors tu leur diras: C’est parce que vos pères m’ont abandonné, dit l’ Éternel, et sont allés après d’autres dieux, et les ont servis, et se sont prosternés devant eux, et m’ont abandonné, et n’ont point gardé ma loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'et vous, vous avez fait pis encore que vos pères, et vous voilà marchant chacun suivant le penchant obstiné de son mauvais cœur, pour ne pas m’écouter;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'et je vous jetterai de ce pays dans un pays que vous n’avez pas connu, ni vous, ni vos pères; et vous servirez là d’autres dieux, jour et nuit, parce que je ne vous témoignerai aucune faveur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'C’est pourquoi, voici, des jours viennent, dit l’ Éternel, où on ne dira plus: L’ Éternel est vivant, qui a fait monter les fils d’Israël du pays d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'mais: L’ Éternel est vivant, qui a fait monter les fils d’Israël du pays du nord, et de tous les pays où il les avait chassés. Et je les ramènerai dans leur terre, que j’ai donnée à leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Voici, je fais venir beaucoup de pêcheurs, dit l’ Éternel, et ils les pêcheront; et après cela je ferai venir beaucoup de chasseurs, qui les prendront comme du gibier de dessus toutes les montagnes, et de dessus toutes les collines, et des trous des rochers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Car mes yeux sont sur toutes leurs voies; elles ne sont pas cachées de devant ma face, ni leur iniquité mise à couvert de devant mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Et je rendrai premièrement le double de leur iniquité et de leur péché, parce qu’ils ont souillé mon pays par les cadavres de leurs choses exécrables; et ils ont rempli mon héritage de leurs abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Éternel, ma force, et ma forteresse, et mon refuge au jour de la détresse! à toi les nations viendront des bouts de la terre, et elles diront: Certainement nos pères ont hérité le mensonge, la vanité; et dans ces choses il n’y a point de profit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'L’homme se fera-t-il bien des dieux, qui ne sont pas des dieux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'C’est pourquoi, voici, cette fois je leur fais connaître, je leur ferai connaître ma main et ma puissance, et ils sauront que mon nom est l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Le péché de Juda est écrit avec un style de fer, avec une pointe de diamant; il est gravé sur la table de leur cœur, et sur les cornes de leurs autels,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'comme leurs fils se souviennent de leurs autels et de leurs ashères auprès des arbres verts, sur les hautes collines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Ma montagne dans les champs, ton bien, tous tes trésors, je les livrerai au pillage, – tes hauts lieux, à cause de [ton] péché dans tous tes confins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Et, à cause de toi-même, tu délaisseras ton héritage que je t’avais donné, et je t’asservirai à tes ennemis dans un pays que tu ne connais pas; car vous avez allumé un feu dans ma colère; il brûlera à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Ainsi dit l’ Éternel: Maudit l’homme qui se confie en l’homme, et qui fait de la chair son bras, et dont le cœur se retire de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Et il sera comme un dénué dans le désert, et il ne verra pas quand le bien arrivera, mais il demeurera dans des lieux secs au désert, dans un pays de sel et inhabité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Béni l’homme qui se confie en l’ Éternel, et de qui l’ Éternel est la confiance!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Il sera comme un arbre planté près des eaux; et il étendra ses racines vers le courant; et il ne s’apercevra pas quand la chaleur viendra, et sa feuille sera [toujours] verte; et dans l’année de la sécheresse il ne craindra pas, et il ne cessera de porter du fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Le cœur est trompeur par-dessus tout, et incurable; qui le connaît?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Moi, l’ Éternel, je sonde le cœur, j’éprouve les reins; et [cela] pour rendre à chacun selon ses voies, selon le fruit de ses actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Comme la perdrix qui couve ce qu’elle n’a pas pondu, celui qui acquiert des richesses, et non avec droiture, les laissera au milieu de ses jours, et, à sa fin, il sera un insensé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Le lieu de notre sanctuaire est un trône de gloire, un lieu haut élevé dès le commencement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Attente d’Israël, Éternel! tous ceux qui t’abandonnent seront honteux. Ceux qui se retirent de moi seront écrits sur la terre, car ils ont délaissé la source des eaux vives, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Guéris-moi, Éternel! et je serai guéri; sauve-moi, et je serai sauvé; car c’est toi qui es ma louange!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Voici, ceux-ci me disent: Où est la parole de l’ Éternel? Qu’elle vienne donc!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Mais moi, je ne me suis pas hâté de cesser d’être pasteur en te suivant, et je n’ai pas désiré le mauvais jour, tu le sais; ce qui est sorti de mes lèvres a été devant ta face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Ne me sois point une épouvante: tu es mon refuge au mauvais jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Que ceux qui me persécutent soient honteux, et que moi, je ne sois pas honteux; qu’ils aient peur, et que moi, je n’aie pas peur; fais venir sur eux le jour de malheur, et ruine-les d’une double ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Ainsi m’a dit l’ Éternel: Va, et tiens-toi dans la porte des fils du peuple, par laquelle entrent les rois de Juda et par laquelle ils sortent, et dans toutes les portes de Jérusalem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'et dis-leur: Écoutez la parole de l’ Éternel, vous, rois de Juda, et tout Juda, et vous tous, habitants de Jérusalem, qui entrez par ces portes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Ainsi dit l’ Éternel: Prenez garde à vos âmes, et ne portez pas de fardeau le jour du sabbat, ni n’en faites passer par les portes de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Et ne portez pas de fardeau hors de vos maisons, le jour du sabbat, et ne faites aucune œuvre, et sanctifiez le jour du sabbat, comme j’ai commandé à vos pères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'mais ils n’écoutèrent pas, et n’inclinèrent pas leur oreille; mais ils roidirent leur cou, pour ne pas écouter et pour ne pas recevoir l’instruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Et il arrivera, si vous m’ écoutez attentivement, dit l’ Éternel, pour ne pas faire passer de fardeau par les portes de cette ville, le jour du sabbat, et pour sanctifier le jour du sabbat, pour ne faire aucune œuvre ce jour-là,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'qu’alors entreront par les portes de cette ville les rois et les princes assis sur le trône de David, montés sur des chars et sur des chevaux, eux et leurs princes, les hommes de Juda et les habitants de Jérusalem; et cette ville sera habitée à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'et on viendra des villes de Juda, et des environs de Jérusalem, et du pays de Benjamin, et du pays plat, et de la montagne, et du midi, apportant des holocaustes, et des sacrifices, et des offrandes de gâteau, et de l’encens, et apportant des actions de grâces à la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Mais si vous ne m’écoutez pas pour sanctifier le jour du sabbat, et pour ne pas porter de fardeau en entrant par les portes de Jérusalem le jour du sabbat, j’allumerai un feu dans ses portes, et il dévorera les palais de Jérusalem, et ne sera pas éteint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, '*La parole qui vint à Jérémie de par l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Lève-toi, et descends dans la maison du potier, et là je te ferai entendre mes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Et je descendis dans la maison du potier; et voici, il faisait son ouvrage sur son tour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Et le vase qu’il faisait fut gâté comme de l’argile dans la main du potier; et il en fit un autre vase, comme il plut aux yeux du potier de le faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Ne puis-je pas faire de vous comme [fait] ce potier, ô maison d’Israël? dit l’ Éternel. Voici, comme est l’argile dans la main du potier, ainsi êtes-vous dans ma main, ô maison d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Au moment où je parle au sujet d’une nation et au sujet d’un royaume, pour arracher, pour démolir, et pour détruire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'si cette nation au sujet de laquelle j’ai parlé se détourne du mal qu’elle a fait, je me repentirai du mal que je pensais lui faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Et au moment où je parle d’une nation et d’un royaume, pour bâtir et pour planter,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'si elle fait ce qui est mauvais à mes yeux, pour ne pas écouter ma voix, je me repentirai du bien que j’avais dit vouloir lui faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Et maintenant, parle aux hommes de Juda et aux habitants de Jérusalem, disant: Ainsi dit l’ Éternel: Voici, moi je prépare contre vous du mal, et je forme un dessein contre vous; revenez donc chacun de sa mauvaise voie, et amendez vos voies et vos actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Mais ils disent: C’est en vain; car nous marcherons suivant nos pensées, et nous ferons chacun [selon] l’obstination de son mauvais cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'C’est pourquoi, ainsi dit l’ Éternel: Demandez aux nations: Qui a entendu de telles choses? La vierge d’Israël a fait une chose très horrible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'La neige du Liban abandonnerait-elle le rocher du champ? Ou les eaux fraîches [et] ruisselantes qui viennent de loin tariraient-elles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Car mon peuple m’a oublié; ils brûlent de l’encens à la vanité; et on les a fait broncher dans leurs voies, les sentiers anciens, pour marcher dans les sentiers d’un chemin non frayé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'pour faire de leur pays un sujet d’étonnement, de raillerie perpétuelle; quiconque passera à côté sera étonné et secouera sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Comme par le vent d’orient, je les disperserai devant l’ennemi; je leur tournerai le dos et non la face, au jour de leur calamité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Et ils ont dit: Venez, et faisons des complots contre Jérémie, car la loi ne périra pas de chez le sacrificateur, ni le conseil de chez le sage, ni la parole de chez le prophète. Venez, et frappons-le de la langue, et ne soyons attentifs à aucune de ses paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Éternel, fais attention à moi, et écoute la voix de ceux qui contestent avec moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Le mal sera-t-il rendu pour le bien? car ils ont creusé une fosse pour mon âme. Souviens-toi que je me suis tenu devant ta face afin de parler pour eux en bien, afin de détourner d’eux ton courroux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'C’est pourquoi abandonne leurs fils à la famine, et livre-les à la puissance de l’épée, et que leurs femmes soient privées d’enfants et veuves, et que leurs hommes soient enlevés par la mort, [et] leurs jeunes gens frappés par l’épée dans la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Qu’on entende un cri de leurs maisons, quand tu auras fait venir subitement une troupe sur eux; car ils ont creusé une fosse pour me prendre, et ils ont caché des pièges pour mes pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Et toi, Éternel, tu connais tout leur conseil contre moi, pour me mettre à mort: ne pardonne pas leur iniquité, et n’efface pas leur péché de devant ta face; mais qu’ils tombent devant toi. Agis contre eux au temps de ta colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Ainsi dit l’ Éternel: Va, et achète un vase de potier, et [prends] des anciens du peuple et des anciens des sacrificateurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'et sors vers la vallée du fils de Hinnom, qui est à l’entrée de la porte de la poterie, et crie là les paroles que je te dirai,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'et dis: Écoutez la parole de l’ Éternel, vous, rois de Juda, et vous, habitants de Jérusalem: Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Voici, je fais venir sur ce lieu-ci un mal tel, que quiconque l’entendra, les oreilles lui tinteront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'parce qu’ils m’ont abandonné, et qu’ils m’ont aliéné ce lieu, et qu’ils y ont brûlé de l’encens à d’autres dieux que n’ont connus ni eux, ni leurs pères, ni les rois de Juda, et qu’ils ont rempli ce lieu du sang des innocents,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'et ont bâti les hauts lieux de Baal, pour brûler au feu leurs fils en holocauste à Baal; ce que je n’ai point commandé, et dont je n’ai point parlé, et qui ne m’est point monté au cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'C’est pourquoi, voici, des jours viennent, dit l’ Éternel, où ce lieu-ci ne sera plus appelé Topheth, ni la vallée du fils de Hinnom, mais la vallée de la tuerie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Et je rendrai vain le conseil de Juda et de Jérusalem dans ce lieu-ci, et je les ferai tomber par l’épée devant leurs ennemis et par la main de ceux qui cherchent leur vie, et je donnerai leurs cadavres en pâture aux oiseaux des cieux et aux bêtes de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Et je ferai de cette ville un sujet d’étonnement et de sifflement: quiconque passera à côté d’elle s’étonnera et sifflera sur toutes ses plaies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Et je leur ferai manger la chair de leurs fils et la chair de leurs filles; et ils mangeront chacun la chair de son prochain, dans le siège et dans la détresse dont les enserreront leurs ennemis et ceux qui cherchent leur vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Et tu briseras le vase devant les yeux des hommes qui sont allés avec toi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'et tu leur diras: Ainsi dit l’ Éternel des armées: Je briserai ainsi ce peuple et cette ville, comme on brise un vase de potier qui ne peut être raccommodé; et on enterrera à Topheth, jusqu’à ce qu’il n’y ait plus de place pour enterrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Je ferai ainsi à ce lieu, dit l’ Éternel, et à ses habitants, pour rendre cette ville semblable à Topheth;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'et les maisons de Jérusalem et les maisons des rois de Juda seront, comme le lieu de Topheth, impures, – toutes les maisons sur les toits desquelles ils ont brûlé de l’encens à toute l’armée des cieux, et ont répandu des libations à d’autres dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Et Jérémie vint de Topheth, où l’ Éternel l’avait envoyé pour prophétiser; et il se tint dans le parvis de la maison de l’ Éternel, et dit à tout le peuple:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Voici, je fais venir sur cette ville, et sur toutes ses villes, tout le mal que j’ai prononcé contre elle, parce qu’ils ont roidi leur cou pour ne point écouter mes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, '*Et Pashkhur, fils d’Immer, le sacrificateur (et il était premier intendant dans la maison de l’ Éternel), entendit Jérémie prophétiser ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Et Pashkhur frappa Jérémie le prophète, et le mit au bloc à la porte haute de Benjamin, dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Et il arriva, le lendemain, que Pashkhur tira Jérémie du bloc; et Jérémie lui dit: L’ Éternel n’appelle pas ton nom Pashkhur, mais Magor-Missabib.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Car ainsi dit l’ Éternel: Voici, je te ferai [être] une terreur pour toi et pour tous ceux qui t’aiment; et ils tomberont par l’épée de leurs ennemis, et tes yeux le verront; et je livrerai tout Juda en la main du roi de Babylone, et il les transportera à Babylone, et les frappera de l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Et je livrerai toutes les richesses de cette ville et tout son travail, et tout ce qu’elle a de précieux, et tous les trésors des rois de Juda, je les livrerai en la main de leurs ennemis; et ils les pilleront, et les prendront, et les emporteront à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Et toi, Pashkhur, et tous ceux qui habitent dans ta maison, vous irez en captivité; et tu iras à Babylone, et là tu mourras, et là tu seras enterré, toi et tous ceux qui t’aiment, auxquels tu as prophétisé le mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Tu m’as entraîné, ô Éternel! et j’ai été entraîné; tu m’as saisi, et tu as été le plus fort; je suis un objet de dérision tout le jour, chacun se moque de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Car toutes les fois que je parle, je crie, je proclame la violence et la dévastation; car la parole de l’ Éternel m’a été à opprobre et à moquerie tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Et j’ai dit: Je ne ferai plus mention de lui, et je ne parlerai plus en son nom; mais elle a été dans mon cœur comme un feu brûlant, renfermé dans mes os; je fus las de [la] retenir, et je ne l’ai pu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Car j’ai entendu les diffamations de plusieurs: la terreur de tous côtés! Rapportez, et nous rapporterons! Tous mes familiers guettaient ma chute [disant]: Peut-être se laissera-t-il séduire; et nous prévaudrons contre lui, et nous nous vengerons sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Mais l’ Éternel est avec moi comme un homme puissant; c’est pourquoi mes persécuteurs trébucheront, et ne prévaudront pas; ils seront fort honteux, car ils n’ont pas réussi: confusion éternelle qui ne sera point oubliée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Éternel des armées, qui éprouves le juste, [et] qui vois les reins et le cœur! fais que je voie ta vengeance sur eux; car à toi j’ai découvert ma cause.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Chantez à l’ Éternel, louez l’ Éternel! car il a délivré l’âme du pauvre de la main des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Maudit le jour où je naquis! Que le jour où ma mère m’enfanta ne soit point béni!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Maudit l’homme qui annonça des nouvelles à mon père, disant: Un enfant mâle t’est né, et qui le combla de joie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Que cet homme-là soit comme les villes que l’ Éternel a renversées sans s’en repentir! Qu’il entende des cris le matin, et des clameurs au temps de midi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'parce qu’il ne m’a pas fait mourir dès le ventre. Ou ma mère, que n’a-t-elle pas été mon sépulcre! et son ventre, que ne m’a-t-il toujours porté!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Pourquoi suis-je sorti du ventre, pour voir le trouble et l’affliction, et pour que mes jours se consument dans l’opprobre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, '*La parole qui vint à Jérémie de par l’ Éternel, lorsque le roi Sédécias envoya vers lui Pashkhur, fils de Malkija, et Sophonie, fils de Maascéïa, le sacrificateur, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Consulte, je te prie, l’ Éternel à notre égard, car Nebucadretsar, roi de Babylone, nous fait la guerre; peut-être que l’ Éternel agira pour nous selon toutes ses merveilles et que [Nebucadretsar] montera d’auprès de nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Et Jérémie leur dit: Vous direz ainsi à Sédécias:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Ainsi dit l’ Éternel, le Dieu d’Israël: Voici, je retourne en arrière les instruments de guerre qui sont en vos mains, avec lesquels vous combattez en dehors des murailles contre le roi de Babylone et contre les Chaldéens qui vous assiègent, et je les rassemblerai au-dedans de cette ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Et moi je combattrai contre vous avec une main étendue, et avec un bras puissant, et avec colère, et avec fureur, et avec un grand courroux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'et je frapperai les habitants de cette ville, et les hommes et les bêtes; ils mourront d’une grande peste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Et après cela, dit l’ Éternel, je livrerai Sédécias, roi de Juda, et ses serviteurs, et le peuple, savoir ceux qui, dans cette ville, seront demeurés de reste de la peste, de l’épée et de la famine, en la main de Nebucadretsar, roi de Babylone, et en la main de leurs ennemis, et en la main de ceux qui cherchent leur vie; et il les frappera au tranchant de l’épée; il ne les épargnera pas, et n’en aura pas compassion et n’en aura pas pitié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Et tu diras à ce peuple: Ainsi dit l’ Éternel: Voici, je mets devant vous le chemin de la vie et le chemin de la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Celui qui demeurera dans cette ville mourra par l’épée, et par la famine, et par la peste; et celui qui en sortira et se rendra aux Chaldéens qui vous assiègent vivra et aura sa vie pour butin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Car j’ai mis ma face contre cette ville, pour le mal et non pour le bien, dit l’ Éternel; elle sera livrée en la main du roi de Babylone, et il la brûlera par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Et quant à la maison du roi de Juda, écoutez la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Maison de David, ainsi dit l’ Éternel: Jugez justement, le matin, et délivrez de la main de l’oppresseur celui qui est pillé, de peur que ma fureur ne sorte comme un feu et ne brûle, sans qu’il y ait personne pour l’éteindre, à cause de l’iniquité de vos actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Voici, je suis contre toi, qui habites la vallée, le rocher de la plaine, dit l’ Éternel; [contre] vous qui dites: Qui descendra contre nous, et qui viendra dans nos habitations?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Et je vous punirai selon le fruit de vos actions, dit l’ Éternel; et j’allumerai un feu dans sa forêt, et il consumera tout ce qui est autour d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Ainsi dit l’ Éternel: Descends à la maison du roi de Juda, et prononce là cette parole,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'et dis: Écoute la parole de l’ Éternel, ô roi de Juda, qui es assis sur le trône de David! toi, et tes serviteurs, et ton peuple, qui entrez par ces portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Ainsi dit l’ Éternel: Pratiquez le jugement et la justice, et délivrez de la main de l’oppresseur celui qui est pillé; et n’opprimez pas, ne violentez pas l’étranger, l’orphelin, et la veuve, et ne versez pas le sang innocent dans ce lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Car si en effet vous accomplissez fidèlement cette parole, alors les rois qui sont assis à la place de David sur son trône entreront par les portes de cette maison, montés sur des chars et sur des chevaux, – lui, et ses serviteurs, et son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Et si vous n’écoutez pas ces paroles, je jure par moi-même, dit l’ Éternel, que cette maison sera réduite en désolation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Car ainsi dit l’ Éternel touchant la maison du roi de Juda: Tu es pour moi un Galaad, le sommet du Liban... Si je ne te réduis en désert, en villes inhabitées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Et je préparerai contre toi des destructeurs, chacun avec ses armes, et ils couperont et jetteront au feu l’élite de tes cèdres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Et beaucoup de nations passeront près de cette ville, et chacun dira à son compagnon: Pourquoi l’ Éternel a-t-il fait ainsi à cette grande ville?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Et on dira: Parce qu’ils ont abandonné l’alliance de l’ Éternel leur Dieu, et qu’ils se sont prosternés devant d’autres dieux, et les ont servis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Ne pleurez pas celui qui est mort, et ne vous lamentez pas sur lui. Pleurez, pleurez celui qui s’en va, car il ne reviendra plus, ni ne reverra plus le pays de sa naissance!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Car ainsi dit l’ Éternel quant à Shallum, fils de Josias, roi de Juda, qui régna à la place de Josias, son père, [et] qui s’en est allé de ce lieu: Il n’y reviendra plus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'car il mourra dans le lieu où on l’a transporté, et ne verra plus ce pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Malheur à celui qui bâtit sa maison par l’injustice, et ses chambres hautes par le manque de droiture; qui se sert pour rien de son prochain, et ne lui donne rien pour son travail;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'qui dit: Je me bâtirai une vaste maison et de spacieuses chambres hautes, et qui se la perce de fenêtres, et la lambrisse de cèdre, et la peint en vermillon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Régneras-tu, parce que tu rivalises avec le cèdre? Ton père n’a-t-il pas mangé et bu, et pratiqué le jugement et la justice? alors il s’est bien trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Il a jugé la cause de l’affligé et du pauvre; alors cela a bien été. N’est-ce pas là me connaître? dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Car tes yeux et ton cœur ne sont qu’ à ton gain déshonnête, et au sang innocent pour le répandre, et à l’oppression et à la violence pour les faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'C’est pourquoi, ainsi dit l’ Éternel quant à Jehoïakim, fils de Josias, roi de Juda: On ne se lamentera pas sur lui: Hélas, mon frère! Hélas, [ma] sœur! On ne se lamentera pas sur lui: Hélas, Seigneur! et: Hélas, sa gloire!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Il sera enseveli de l’ensevelissement d’un âne, – traîné et jeté par-delà les portes de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Monte au Liban et crie, et de Basan fais entendre ta voix, et crie [des hauteurs] d’Abarim, parce que tous tes amants sont brisés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Je t’ai parlé dans le temps de ta prospérité; [mais] tu as dit: Je n’écouterai point. Ceci a été ton chemin dès ta jeunesse, que tu n’as point écouté ma voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Tous tes pasteurs seront la pâture du vent, et tes amants iront en captivité; et alors tu seras honteuse et confuse à cause de toute ton iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Habitante du Liban, qui fais ton nid dans les cèdres, combien tu seras un objet de pitié quand les douleurs viendront sur toi, l’angoisse comme celle d’une femme qui enfante!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Je suis vivant, dit l’ Éternel, que quand même Conia, fils de Jehoïakim, roi de Juda, serait un cachet à ma main droite, je t’arracherai de là!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Et je te livrerai en la main de ceux qui cherchent ta vie, et en la main de ceux dont tu as peur, et en la main de Nebucadretsar, roi de Babylone, et en la main des Chaldéens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Et je te jetterai, toi et ta mère qui t’a enfanté, dans un autre pays, où vous n’êtes pas nés; et là vous mourrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Et, dans le pays où ils désirent ardemment de retourner, ils ne retourneront point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Cet homme, Conia, est-il un vase d’argile méprisé et mis en pièces? un ustensile auquel on n’a point de plaisir? Pourquoi ont-ils été jetés loin, lui et sa postérité, et lancés dans un pays qu’ils ne connaissent point?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Terre, terre, terre, écoute la parole de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Ainsi dit l’ Éternel: Inscrivez cet homme comme privé d’enfants, comme un homme qui ne prospérera pas pendant ses jours; car, de sa semence, nul ne prospérera, assis sur le trône de David, ou dominant encore en Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Malheur aux pasteurs qui détruisent et dispersent le troupeau de ma pâture! dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'C’est pourquoi, ainsi dit l’ Éternel, le Dieu d’Israël, quant aux pasteurs qui paissent mon peuple: Vous avez dispersé mon troupeau, et vous les avez chassés, et vous ne les avez pas visités; voici, je visite sur vous l’iniquité de vos actions, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Et moi, je rassemblerai le reste de mon troupeau de tous les pays où je les aurai chassés, et je les ferai retourner à leurs pâturages, et ils fructifieront et multiplieront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Et je susciterai sur eux des pasteurs qui les paîtront; et ils ne craindront plus, et ne seront pas effrayés, et il n’en manquera aucun, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Voici, les jours viennent, dit l’ Éternel, et je susciterai à David un Germe juste; et il régnera en roi, et prospérera, et exercera le jugement et la justice dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Dans ses jours Juda sera sauvé et Israël demeurera en sécurité; et c’est ici le nom dont on l’appellera: L’ Éternel notre justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'C’est pourquoi, voici, des jours viennent, dit l’ Éternel, où l’on ne dira plus: L’ Éternel est vivant, qui a fait monter les fils d’Israël du pays d’Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'mais: L’ Éternel est vivant, qui a fait monter et qui a ramené la semence de la maison d’Israël du pays du nord, et de tous les pays où je les avais chassés; et ils habiteront en leur terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'À cause des prophètes, mon cœur est brisé au-dedans de moi; tous mes os tremblent; je suis comme un homme ivre, et comme un homme que le vin a surmonté, à cause de l’ Éternel, et à cause de ses paroles saintes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Car le pays est rempli d’adultères, car le pays est en deuil à cause de l’exécration; les pâturages du désert sont desséchés; leur course est mauvaise, et leur force est injuste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Car, tant le prophète que le sacrificateur sont profanes; même dans ma maison j’ai trouvé leur iniquité, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'C’est pourquoi leur chemin leur sera comme des lieux glissants dans les ténèbres; ils y seront poussés, et ils y tomberont; car je ferai venir du mal sur eux, en l’année de leur visitation, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Et dans les prophètes de Samarie j’ai vu de la folie; ils ont prophétisé par Baal, et ont fait errer mon peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Et dans les prophètes de Jérusalem j’ai vu des choses horribles, commettre adultère et marcher dans le mensonge; ils fortifient les mains de ceux qui font le mal, en sorte qu’aucun ne revienne de son iniquité; ils me sont tous comme Sodome, et ses habitants, comme Gomorrhe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'C’est pourquoi, ainsi dit l’ Éternel des armées quant aux prophètes: Voici, je leur fais manger de l’absinthe et leur fais boire de l’eau de fiel; car c’est des prophètes de Jérusalem que l’impiété s’est répandue par tout le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Ainsi dit l’ Éternel des armées: N’écoutez pas les paroles des prophètes qui vous prophétisent; ils vous entraînent à des choses vaines, ils disent la vision de leur cœur, non [celle qui sort] de la bouche de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Ils disent continuellement à ceux qui me méprisent: L’ Éternel dit: Vous aurez la paix. Et à tous ceux qui marchent dans l’obstination de leur cœur ils disent: Il ne viendra point de mal sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Car qui s’est tenu dans le conseil secret de l’ Éternel, en sorte qu’il ait vu et entendu sa parole? Qui a été attentif à sa parole, et a écouté?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Voici, une tempête de l’ Éternel, la fureur, est sortie; et une tempête tourbillonnante fondra sur la tête des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'La colère de l’ Éternel ne retournera pas jusqu’à ce qu’il ait exécuté et accompli les pensées de son cœur. À la fin des jours vous le comprendrez avec intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Je n’ai pas envoyé ces prophètes, et ils ont couru; je ne leur ai pas parlé, et ils ont prophétisé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'mais, s’ils s’étaient tenus dans mon conseil secret et avaient fait entendre mes paroles à mon peuple, ils les auraient détournés de leur mauvaise voie et de l’iniquité de leurs actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Suis-je un Dieu de près, dit l’ Éternel, et non un Dieu de loin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Un homme se cachera-t-il dans quelque cachette où je ne le voie pas? dit l’ Éternel. N’est-ce pas moi qui remplis les cieux et la terre? dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'J’ai entendu ce que les prophètes disent, prophétisant le mensonge en mon nom, disant: J’ai eu un songe, j’ai eu un songe!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Jusques à quand [cela] sera-t-il dans le cœur des prophètes qui prophétisent le mensonge et qui sont des prophètes de la tromperie de leur cœur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'qui pensent faire oublier mon nom à mon peuple par leurs songes que chacun raconte à son compagnon, comme leurs pères ont oublié mon nom pour Baal?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Que le prophète qui a un songe récite le songe, et que celui qui a ma parole énonce ma parole en vérité. Qu’est-ce que la paille à côté du froment? dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Ma parole n’est-elle pas comme un feu, dit l’ Éternel, et comme un marteau qui brise le roc?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'C’est pourquoi, voici, dit l’ Éternel, j’en veux aux prophètes qui volent mes paroles chacun à son prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Voici, dit l’ Éternel, j’en veux aux prophètes qui usent de leur langue, et disent: Il dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Voici, dit l’ Éternel, j’en veux à ceux qui prophétisent des songes faux, et qui les récitent, et font errer mon peuple par leurs mensonges et par leurs vanteries; et moi je ne les ai pas envoyés, et je ne leur ai pas donné de commandement; et ils ne profiteront de rien à ce peuple, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Et si ce peuple, ou un prophète, ou un sacrificateur, t’interroge, disant: Quel est l’oracle de l’ Éternel? tu leur diras: Quel oracle? Je vous abandonnerai, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Et quant au prophète, et au sacrificateur, et au peuple qui dit: Oracle de l’ Éternel, – je punirai cet homme-là et sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Ainsi vous direz, chacun à son compagnon et chacun à son frère: Qu’a répondu l’ Éternel, et qu’a dit l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Et vous ne ferez plus mention de l’oracle de l’ Éternel, car la parole de chacun lui sera pour oracle; car vous avez perverti les paroles du Dieu vivant, de l’ Éternel des armées, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Ainsi tu diras au prophète: Que t’a répondu l’ Éternel, et qu’a dit l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Et si vous dites: Oracle de l’ Éternel; – à cause de cela, ainsi dit l’ Éternel: Parce que vous dites cette parole: Oracle de l’ Éternel, et que j’ai envoyé vers vous, disant: Ne dites pas: Oracle de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, '– à cause de cela, voici, je vous oublierai entièrement, et je vous rejetterai loin de ma face, vous et la ville que j’ai donnée à vous et à vos pères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'et je ferai venir sur vous un opprobre éternel, et une éternelle confusion, et elle ne sera point oubliée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, '*L’ Éternel me fit voir [une vision], et voici deux paniers de figues, posés devant le temple de l’ Éternel, après que Nebucadretsar, roi de Babylone, eut transporté de Jérusalem Jéconias, fils de Jehoïakim, roi de Juda, et les princes de Juda, et les charpentiers, et les forgerons, et qu’il les eut emmenés à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'L’un des paniers avait de très bonnes figues, comme les figues de la première saison; et l’autre panier avait de très mauvaises figues qu’on ne pouvait manger, tant elles étaient mauvaises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Et l’ Éternel me dit: Que vois-tu, Jérémie? Et je dis: Des figues; les bonnes figues, très bonnes, et les mauvaises, très mauvaises, qui ne peuvent être mangées, tant elles sont mauvaises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Ainsi dit l’ Éternel, le Dieu d’Israël: Comme [tu vois] ces bonnes figues, ainsi je me souviendrai, en bien, des transportés de Juda, que j’ai envoyés hors de ce lieu au pays des Chaldéens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'et je mettrai mes yeux sur eux pour [leur] bien, et je les ferai retourner dans ce pays; et je les bâtirai et je ne les renverserai pas, et je les planterai, et je ne les arracherai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Et je leur donnerai un cœur pour me connaître, car moi je suis l’ Éternel; et ils seront mon peuple, et moi je serai leur Dieu; car ils retourneront à moi de tout leur cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Et comme les figues mauvaises qu’on ne peut manger, tant elles sont mauvaises,... oui, ainsi dit l’ Éternel, tels je rendrai Sédécias, le roi de Juda, et ses princes, et le reste de Jérusalem, qui sont de reste dans ce pays, et ceux qui habitent dans le pays d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'et je les livrerai pour être chassés çà et là par tous les royaumes de la terre, pour leur malheur, pour être en opprobre et en proverbe, un objet de raillerie et de malédiction, dans tous les lieux où je les chasserai;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'et j’enverrai contre eux l’épée, la famine, et la peste, jusqu’à ce qu’ils soient consumés de dessus la terre que je leur ai donnée, à eux et à leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, '*La parole qui vint à Jérémie touchant tout le peuple de Juda, la quatrième année de Jehoïakim, fils de Josias, roi de Juda, (qui est la première année de Nebucadretsar, roi de Babylone,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, '[et] que Jérémie le prophète dit à tout le peuple de Juda, et à tous les habitants de Jérusalem, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Depuis la treizième année de Josias, fils d’Amon, roi de Juda, jusqu’à ce jour, ces 23 ans, la parole de l’ Éternel m’est venue, et je vous ai parlé, me levant de bonne heure et parlant; et vous n’avez pas écouté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Et l’ Éternel vous a envoyé tous ses serviteurs les prophètes, se levant de bonne heure et [les] envoyant; et vous n’avez pas écouté, et vous n’avez point incliné vos oreilles pour écouter,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'lorsqu’ils disaient: Revenez donc chacun de sa mauvaise voie, et de l’iniquité de vos actions, et vous habiterez sur la terre que l’ Éternel vous a donnée, à vous et à vos pères, de siècle en siècle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'et n’allez point après d’autres dieux pour les servir, et pour vous prosterner devant eux, et ne me provoquez pas par l’œuvre de vos mains; et je ne vous ferai pas de mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Mais vous ne m’avez pas écouté, dit l’ Éternel, pour me provoquer par l’œuvre de vos mains, pour votre propre malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'C’est pourquoi, ainsi dit l’ Éternel des armées: Parce que vous n’avez pas écouté mes paroles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'voici, j’envoie, et je prends toutes les familles du nord, dit l’ Éternel, et Nebucadretsar, roi de Babylone, mon serviteur, et je les ferai venir contre ce pays, et contre ses habitants, et contre toutes ces nations à l’entour: et je les vouerai à la destruction, j’en ferai une désolation, et un objet de sifflement, et des déserts perpétuels;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'et je ferai périr du milieu d’eux la voix de l’allégresse et la voix de la joie, la voix de l’époux et la voix de l’épouse, le bruit des meules et la lumière de la lampe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Et tout ce pays sera un désert, une désolation; et ces nations serviront le roi de Babylone 70 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Et il arrivera, quand [les] 70 ans seront accomplis, que je visiterai sur le roi de Babylone et sur cette nation-là leur iniquité, dit l’ Éternel, et sur le pays des Chaldéens, et je le réduirai en désolations perpétuelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Et je ferai venir sur ce pays toutes mes paroles que j’ai dites contre lui, tout ce qui est écrit dans ce livre, ce que Jérémie a prophétisé contre toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Car plusieurs nations et de grands rois se serviront d’eux aussi; et je leur rendrai selon leurs actions, et selon l’œuvre de leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Car ainsi m’a dit l’ Éternel, le Dieu d’Israël: Prends de ma main la coupe du vin de cette fureur, et tu en feras boire à toutes les nations auxquelles je t’envoie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'et elles boiront et elles seront étourdies, et elles seront comme folles, à cause de l’épée que j’enverrai parmi elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Et je pris la coupe de la main de l’ Éternel, et j’en fis boire à toutes les nations auxquelles l’ Éternel m’envoyait:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'à Jérusalem, et aux villes de Juda, et à ses rois, et à ses princes, pour les livrer à l’aridité, à la désolation, au sifflement, et à la malédiction, comme [il paraît] aujourd’hui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'au Pharaon, roi d’Égypte, et à ses serviteurs, et à ses princes, et à tout son peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'et à tout le peuple mélangé, et à tous les rois du pays d’Uts, et à tous les rois du pays des Philistins, et à Askalon, et à Gaza, et à Ékron, et au reste d’Asdod;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'à Édom, et à Moab, et aux fils d’Ammon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'et à tous les rois de Tyr, et à tous les rois de Sidon; et aux rois des îles qui sont au-delà de la mer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'à Dedan, et à Théma, et à Buz, et à tous ceux qui coupent les coins [de leur barbe];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'et à tous les rois d’Arabie, et à tous les rois du peuple mélangé, qui demeurent dans le désert;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'et à tous les rois de Zimri, et à tous les rois d’Élam, et à tous les rois de Médie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'et à tous les rois du nord, à ceux qui sont près et à ceux qui sont éloignés, aux uns et aux autres, et à tous les royaumes de la terre qui sont sur la face du sol; et le roi de Shéshac boira après eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Et tu leur diras: Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Buvez et soyez ivres, et vomissez, et tombez, et vous ne vous relèverez pas devant l’épée que j’envoie parmi vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Et il arrivera que, s’ils refusent de prendre la coupe de ta main pour boire, alors tu leur diras: Ainsi dit l’ Éternel des armées: Certainement, vous en boirez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Car voici, par la ville qui est appelée de mon nom, je commence à faire du mal, et vous, vous resteriez entièrement impunis? Vous ne resterez pas impunis; car j’appelle l’épée sur tous les habitants de la terre, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Et toi, prophétise-leur toutes ces paroles, et dis-leur: L’ Éternel rugira d’en haut, et de sa demeure sainte il fera entendre sa voix; il rugira, il rugira contre son habitation, il poussera un cri contre tous les habitants de la terre, comme ceux qui foulent au pressoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Le son éclatant en viendra jusqu’au bout de la terre; car l’ Éternel a un débat avec les nations, il entre en jugement avec toute chair. Les méchants, il les livrera à l’épée, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Ainsi dit l’ Éternel des armées: Voici, le mal s’en ira de nation à nation, et une grande tempête se lèvera des extrémités de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Et les tués de l’ Éternel, en ce jour-là, seront depuis un bout de la terre jusqu’à l’autre bout de la terre. On ne se lamentera pas sur eux, et ils ne seront pas recueillis, et ne seront pas enterrés; ils seront du fumier sur la face du sol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Vous, pasteurs, hurlez et criez; et vous, les nobles du troupeau, roulez-vous par terre, car vos jours sont accomplis, pour vous tuer; et je vous disperserai, et vous tomberez comme un vase d’agrément.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Et [tout] refuge a péri pour les pasteurs, et la délivrance, pour les nobles du troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Il y aura une voix du cri des pasteurs et un hurlement des nobles du troupeau; car l’ Éternel dévaste leur pâturage,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'et les parcs paisibles sont désolés devant l’ardeur de la colère de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Il a abandonné son tabernacle comme un jeune lion [son fourré]; car leur pays sera une désolation devant l’ardeur de l’oppresseur et devant l’ardeur de sa colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, '***Au commencement du règne de Jehoïakim, fils de Josias, roi de Juda, cette parole vint de par l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Ainsi dit l’ Éternel: Tiens-toi dans le parvis de la maison de l’ Éternel, et dis à toutes les villes de Juda, qui viennent pour se prosterner dans la maison de l’ Éternel, toutes les paroles que je t’ai commandé de leur dire; n’en retranche pas une parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Peut-être qu’ils écouteront, et qu’ils reviendront chacun de sa mauvaise voie; et je me repentirai du mal que je pense à leur faire à cause de l’iniquité de leurs actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Et tu leur diras: Ainsi dit l’ Éternel: Si vous ne m’écoutez pas, pour marcher dans ma loi que j’ai mise devant vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'pour écouter les paroles de mes serviteurs, les prophètes que je vous envoie, me levant de bonne heure et [les] envoyant, – mais vous ne les avez pas écoutés –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'je rendrai cette maison comme Silo, et je livrerai cette ville pour être une malédiction à toutes les nations de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Et les sacrificateurs et les prophètes et tout le peuple entendirent Jérémie dire ces paroles dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Et il arriva que, comme Jérémie achevait de dire tout ce que l’ Éternel avait commandé de dire à tout le peuple, les sacrificateurs et les prophètes et tout le peuple le saisirent, disant: Tu mourras certainement!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Pourquoi prophétises-tu au nom de l’ Éternel, disant: Cette maison sera comme Silo, et cette ville sera désolée, de sorte qu’il n’y aura pas d’habitant? Et tout le peuple s’assembla contre Jérémie dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Et les princes de Juda entendirent ces choses, et ils montèrent de la maison du roi à la maison de l’ Éternel, et s’assirent dans l’entrée de la porte neuve de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Et les sacrificateurs et les prophètes parlèrent aux princes et à tout le peuple, disant: Cet homme mérite la mort; car il a prophétisé contre cette ville, comme vous avez entendu de vos oreilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Et Jérémie parla à tous les princes et à tout le peuple, disant: L’ Éternel m’a envoyé pour prophétiser contre cette maison et contre cette ville toutes les paroles que vous avez entendues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Et maintenant, amendez vos voies et vos actions, et écoutez la voix de l’ Éternel, votre Dieu, et l’ Éternel se repentira du mal qu’il a prononcé contre vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Pour moi, me voici entre vos mains; faites-moi comme il est bon et droit à vos yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Seulement, sachez bien que, si vous me faites mourir, vous mettrez du sang innocent sur vous, et sur cette ville, et sur ses habitants; car en vérité l’ Éternel m’a envoyé vers vous pour prononcer à vos oreilles toutes ces paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Et les princes et tout le peuple dirent aux sacrificateurs et aux prophètes: Cet homme ne mérite pas la mort; car il nous a parlé au nom de l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Et quelques hommes des anciens du pays se levèrent, et parlèrent à toute la congrégation du peuple, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Michée, le Morashtite, prophétisait dans les jours d’Ézéchias, roi de Juda, et a parlé à tout le peuple de Juda, disant: Ainsi dit l’ Éternel des armées: Sion sera labourée comme un champ, et Jérusalem sera des monceaux de pierres, et la montagne de la maison, les lieux hauts d’une forêt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Ézéchias, le roi de Juda, avec tout Juda, le fit-il donc mourir? Ne craignit-il pas l’ Éternel, et n’implora-t-il pas l’ Éternel, de sorte que l’ Éternel se repentit du mal qu’il avait prononcé contre eux? Et nous ferions un grand mal contre nos âmes. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Il y avait aussi un homme qui prophétisait au nom de l’ Éternel, Urie, fils de Shemahia, de Kiriath-Jéarim; et il prophétisait contre cette ville et contre ce pays, selon toutes les paroles de Jérémie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'et le roi Jehoïakim, et tous ses hommes forts et tous les princes, entendirent ses paroles, et le roi chercha à le faire mourir; mais Urie l’apprit, et eut peur, et s’enfuit, et alla en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Et le roi Jehoïakim envoya des hommes en Égypte, Elnathan, fils d’Acbor, et des hommes avec lui, en Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'et ils firent sortir d’Égypte Urie, et l’amenèrent au roi Jehoïakim, et il le frappa avec l’épée, et jeta son cadavre dans les sépulcres des fils du peuple. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Toutefois la main d’Akhikam, fils de Shaphan, fut avec Jérémie, afin qu’on ne le livre point aux mains du peuple pour le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, '*Au commencement du règne de Jehoïakim, fils de Josias, roi de Juda, cette parole vint de par l’ Éternel à Jérémie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Ainsi me dit l’ Éternel: Fais-toi des liens et des jougs, et mets-les sur ton cou;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'et envoie-les au roi d’Édom, et au roi de Moab, et au roi des fils d’Ammon, et au roi de Tyr, et au roi de Sidon, par la main des messagers qui sont venus à Jérusalem vers Sédécias, roi de Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'et commande-leur, pour leurs seigneurs, disant: Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Vous direz ainsi à vos seigneurs:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Moi, j’ai fait la terre, l’homme et la bête qui sont sur la face de la terre, par ma grande puissance et par mon bras étendu, et je les ai donnés à qui il était bon à mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Et maintenant j’ai livré tous ces pays en la main de Nebucadnetsar, roi de Babylone, mon serviteur, et je lui ai aussi donné les bêtes des champs pour le servir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Et toutes les nations le serviront, lui, et son fils et le fils de son fils, jusqu’à ce que vienne le temps de son pays aussi, et que plusieurs nations et de grands rois l’asservissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Et il arrivera que la nation ou le royaume qui ne le servira pas, lui, Nebucadnetsar, roi de Babylone, et qui n’aura pas mis son cou sous le joug du roi de Babylone, je visiterai cette nation, dit l’ Éternel, par l’épée, et par la famine, et par la peste, jusqu’à ce que je les aie consumés par sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Et vous, n’écoutez pas vos prophètes, et vos devins, et vos songeurs, et vos pronostiqueurs, et vos magiciens, qui vous parlent, disant: Vous ne servirez point le roi de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Car ils vous prophétisent le mensonge, pour vous faire aller loin de votre terre, et pour que je vous jette dehors, et que vous périssiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Et la nation qui mettra son cou sous le joug du roi de Babylone et le servira, je la laisserai dans sa terre, dit l’ Éternel, et elle la labourera et y demeurera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Et je parlai à Sédécias, roi de Juda, selon toutes ces paroles, disant: Prêtez vos cous au joug du roi de Babylone, et servez-le, lui et son peuple, et vous vivrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Pourquoi mourriez-vous, toi et ton peuple, par l’épée, par la famine, et par la peste, selon que l’ Éternel a parlé contre la nation qui ne servira pas le roi de Babylone?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Et n’écoutez pas les paroles des prophètes qui vous parlent, disant: Vous ne servirez pas le roi de Babylone; car ils vous prophétisent le mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Car je ne les ai pas envoyés, dit l’ Éternel, et ils prophétisent le mensonge en mon nom, afin que je vous jette dehors et que vous périssiez, vous et les prophètes qui vous prophétisent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Et je parlai aux sacrificateurs et à tout ce peuple, disant: Ainsi dit l’ Éternel: N’écoutez point les paroles de vos prophètes qui vous prophétisent, disant: Voici, les ustensiles de la maison de l’ Éternel vont bientôt revenir de Babylone; car c’est le mensonge qu’ils vous prophétisent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Ne les écoutez pas; servez le roi de Babylone, et vivez. Pourquoi cette ville serait-elle un désert?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Et s’ils sont prophètes, et si la parole de l’ Éternel est avec eux, qu’ils intercèdent auprès de l’ Éternel des armées, afin que les ustensiles qui restent dans la maison de l’ Éternel, et dans la maison du roi de Juda, et à Jérusalem, n’aillent point à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Car ainsi dit l’ Éternel des armées touchant les colonnes, et touchant la mer, et touchant les socles, et touchant le reste des ustensiles qui sont de reste dans cette ville,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'que n’a pas pris Nebucadnetsar, roi de Babylone, quand il transporta de Jérusalem à Babylone Jéconias, fils de Jehoïakim, roi de Juda, et tous les nobles de Juda et de Jérusalem; –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'car ainsi dit l’ Éternel des armées, le Dieu d’Israël, touchant les ustensiles qui restent dans la maison de l’ Éternel, et dans la maison du roi de Juda, et à Jérusalem:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Ils seront emportés à Babylone, et ils seront là jusqu’au jour où je m’en occuperai, dit l’ Éternel, et où je les ferai remonter et revenir dans ce lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Et il arriva, en cette même année, au commencement du règne de Sédécias, roi de Juda, en la quatrième année, au cinquième mois, que Hanania, fils d’Azzur, le prophète, qui était de Gabaon, me parla dans la maison de l’ Éternel, aux yeux des sacrificateurs et de tout le peuple, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Ainsi a parlé l’ Éternel des armées, le Dieu d’Israël, disant: J’ai brisé le joug du roi de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Encore deux années, et je ferai revenir en ce lieu tous les ustensiles de la maison de l’ Éternel que Nebucadnetsar, roi de Babylone, a pris de ce lieu et a transportés à Babylone;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'et Jéconias, fils de Jehoïakim, roi de Juda, et tous les transportés de Juda qui sont allés à Babylone, je les ramènerai dans ce lieu, dit l’ Éternel; car je briserai le joug du roi de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Et Jérémie le prophète parla à Hanania, le prophète, aux yeux des sacrificateurs et aux yeux de tout le peuple, qui se tenaient dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Et Jérémie le prophète dit: Amen! Qu’ainsi fasse l’ Éternel! Que l’ Éternel confirme tes paroles, que tu as prophétisées, pour faire revenir de Babylone en ce lieu les ustensiles de la maison de l’ Éternel et tous les captifs!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Toutefois, écoute, je te prie, cette parole que je prononce à tes oreilles et aux oreilles de tout le peuple:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Les prophètes qui ont été avant moi et avant toi, d’ancienneté, ont aussi prophétisé, touchant plusieurs pays et touchant de grands royaumes, la guerre, et le malheur, et la peste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'le prophète qui prophétise la paix, quand la parole de ce prophète arrivera, on saura que c’est un prophète que l’ Éternel a véritablement envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Et Hanania le prophète prit le joug de dessus le cou de Jérémie le prophète, et le brisa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Et Hanania parla aux yeux de tout le peuple, disant: Ainsi dit l’ Éternel: Encore deux années, et je briserai ainsi le joug de Nebucadnetsar, roi de Babylone, de dessus le cou de toutes les nations. Et Jérémie le prophète s’en alla son chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Et la parole de l’ Éternel vint à Jérémie, après que Hanania le prophète eut brisé le joug de dessus le cou de Jérémie le prophète, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Va, et parle à Hanania, disant: Ainsi dit l’ Éternel: Tu as brisé les jougs de bois, et tu as fait à leur place des jougs de fer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Car ainsi dit l’ Éternel des armées, le Dieu d’Israël: J’ai mis un joug de fer sur le cou de toutes ces nations, afin qu’elles servent Nebucadnetsar, roi de Babylone; et elles le serviront; et je lui ai aussi donné les bêtes des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Et Jérémie le prophète dit à Hanania le prophète: Écoute, Hanania! L’ Éternel ne t’a point envoyé; mais tu as fait que ce peuple s’est confié au mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'C’est pourquoi, ainsi dit l’ Éternel: Voici, je te renvoie de dessus la face de la terre; tu mourras cette année, car tu as parlé de révolte contre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Et Hanania le prophète mourut cette année-là, au septième mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, '*Et ce sont ici les paroles de la lettre que Jérémie le prophète envoya de Jérusalem au reste des anciens de la captivité, et aux sacrificateurs, et aux prophètes, et à tout le peuple que Nebucadnetsar avait transportés de Jérusalem à Babylone');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '(après que furent sortis de Jérusalem le roi Jéconias, et la reine, et les eunuques, les princes de Juda et de Jérusalem, et les charpentiers et les forgerons),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'par la main d’Elhasça, fils de Shaphan, et de Guemaria, fils de Hilkija, que Sédécias, roi de Juda, envoyait à Babylone vers Nebucadnetsar, roi de Babylone, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Ainsi dit l’ Éternel des armées, le Dieu d’Israël, à tous les captifs que j’ai transportés de Jérusalem à Babylone:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Bâtissez des maisons et habitez-y; plantez des jardins et mangez-en les fruits;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'prenez des femmes et engendrez des fils et des filles, et prenez des femmes pour vos fils, et donnez vos filles à des maris, et qu’elles enfantent des fils et des filles; et multipliez-vous là et ne diminuez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Et cherchez la paix de la ville où je vous ai transportés, et priez l’ Éternel pour elle; car dans sa paix sera votre paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Car ainsi dit l’ Éternel des armées, le Dieu d’Israël: Que vos prophètes qui sont au milieu de vous, et vos devins, ne vous séduisent point, et n’écoutez pas vos songes que vous vous plaisez à songer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'car c’est avec mensonge qu’ils vous prophétisent en mon nom; je ne les ai pas envoyés, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Car ainsi dit l’ Éternel: Lorsque 70 ans seront accomplis pour Babylone, je vous visiterai, et j’accomplirai envers vous ma bonne parole, pour vous faire revenir en ce lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Car moi je connais les pensées que je pense à votre égard, dit l’ Éternel, pensées de paix et non de mal, pour vous donner un avenir et une espérance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Et vous m’invoquerez, et vous irez, et me supplierez, et je vous écouterai;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'et vous me chercherez, et vous me trouverez, car vous me rechercherez de tout votre cœur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'et je me ferai trouver à vous, dit l’ Éternel; et je rétablirai vos captifs, et je vous rassemblerai d’entre toutes les nations et de tous les lieux où je vous aurai chassés, dit l’ Éternel, et je vous ferai retourner au lieu d’où je vous ai transportés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Si vous dites: L’ Éternel nous a suscité des prophètes à Babylone!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Oui, ainsi dit l’ Éternel touchant le roi qui est assis sur le trône de David, et touchant tout le peuple qui habite dans cette ville, vos frères qui ne sont pas allés avec vous en captivité; –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'ainsi dit l’ Éternel des armées: Voici, j’envoie contre eux l’épée, la famine, et la peste, et je les ferai devenir comme ces figues affreuses qu’on ne peut manger tant elles sont mauvaises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Et je les poursuivrai avec l’épée, avec la famine, et avec la peste; et je les livrerai pour être chassés çà et là par tous les royaumes de la terre, – [et] à l’exécration, et à la désolation, et au sifflement, et à l’opprobre, dans toutes les nations où je les chasserai;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'parce que, dit l’ Éternel, ils n’ont point écouté mes paroles quand je leur ai envoyé mes serviteurs les prophètes, me levant de bonne heure et [les] envoyant; et vous n’avez point écouté, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Mais vous, tous les captifs que j’ai renvoyés de Jérusalem à Babylone, écoutez la parole de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Ainsi dit l’ Éternel des armées, le Dieu d’Israël, touchant Achab, fils de Kolaïa, et touchant Sédécias, fils de Maascéïa, qui vous prophétisent le mensonge en mon nom: Voici, je les livre en la main de Nebucadretsar, roi de Babylone, et il les frappera devant vos yeux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'et on se servira d’eux comme d’une malédiction parmi tous les transportés de Juda qui sont à Babylone, disant: L’ Éternel te rende comme Sédécias et Achab, que le roi de Babylone a grillés au feu, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'parce qu’ils ont commis l’infamie en Israël, et ont commis adultère avec les femmes de leur prochain, et ont dit en mon nom des paroles de mensonge que je ne leur avais pas commandées; et moi, je le sais, et j’en suis témoin, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Et parle à Shemahia, le Nékhélamite, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Ainsi parle l’ Éternel des armées, le Dieu d’Israël, disant: Parce que tu as envoyé en ton nom des lettres à tout le peuple qui est à Jérusalem, et à Sophonie, fils de Maascéïa, le sacrificateur, et à tous les sacrificateurs, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'L’ Éternel t’a établi sacrificateur à la place de Jehoïada, le sacrificateur, pour qu’il y ait des intendants dans la maison de l’ Éternel pour tout homme qui fait l’inspiré et qui prophétise, afin que tu le mettes au bloc et au carcan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'et maintenant, pourquoi n’as-tu pas repris Jérémie, l’Anathothite, qui vous prophétise?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'parce qu’il a envoyé vers nous à Babylone, disant: Ce sera long; bâtissez des maisons, et habitez-y; plantez des jardins, et mangez-en les fruits. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Et Sophonie le sacrificateur lut cette lettre aux oreilles de Jérémie le prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Et la parole de l’ Éternel vint à Jérémie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Fais savoir à tous ceux de la transportation, disant: Ainsi dit l’ Éternel touchant Shemahia, le Nékhélamite: Parce que Shemahia vous a prophétisé, et que moi je ne l’ai pas envoyé, et qu’il vous a fait vous confier au mensonge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'à cause de cela, ainsi dit l’ Éternel: Voici, je punirai Shemahia, le Nékhélamite, et sa semence; il n’aura pas un homme qui habite parmi ce peuple, et il ne verra point le bien que je fais à mon peuple, car il a parlé de révolte contre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, '*La parole qui vint à Jérémie de par l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Ainsi parle l’ Éternel, le Dieu d’Israël, disant: Écris pour toi dans un livre toutes les paroles que je t’ai dites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Car voici, les jours viennent, dit l’ Éternel, où je rétablirai les captifs de mon peuple Israël et Juda, dit l’ Éternel; et je les ferai retourner au pays que j’ai donné à leurs pères, et ils le posséderont.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Et ce sont ici les paroles que l’ Éternel a dites touchant Israël et touchant Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'car ainsi dit l’ Éternel: Nous entendons la voix de la frayeur; il y a la peur, et point de paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Demandez, je vous prie, et voyez si un mâle enfante. Pourquoi vois-je tout homme tenant ses mains sur ses reins comme une femme qui enfante, et pourquoi tous les visages sont-ils devenus pâles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Hélas! que cette journée est grande! Il n’y en a point de semblable; et c’est le temps de la détresse pour Jacob, mais il en sera sauvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Et il arrivera en ce jour-là, dit l’ Éternel des armées, que je briserai son joug de dessus ton cou, et que je romprai tes liens, et les étrangers ne se serviront plus de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'et ils serviront l’ Éternel, leur Dieu, et David, leur roi, lequel je leur susciterai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Et toi, mon serviteur Jacob, ne crains point, dit l’ Éternel, et ne t’effraie pas, Israël! car voici, je te sauve d’un [pays] lointain, et ta semence, du pays de leur captivité, et Jacob reviendra, et sera tranquille et en repos, et il n’y aura personne qui l’effraie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Car je suis avec toi, dit l’ Éternel, pour te sauver; car je détruirai entièrement toutes les nations où je t’ai dispersé; mais quant à toi, je ne te détruirai pas entièrement, mais je te corrigerai avec mesure, et je ne te tiendrai point pour innocent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Car ainsi dit l’ Éternel: Ta blessure est incurable, ta plaie est difficile à guérir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Nul ne défend ta cause pour bander [ta plaie]; il n’y a point de remèdes, [point] de guérison pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Tous tes amants t’ont oubliée, ils ne te recherchent pas; car je t’ai frappée d’une plaie d’ennemi, d’une correction d’homme cruel, à cause de la grandeur de ton iniquité: tes péchés se sont renforcés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Pourquoi cries-tu à cause de ton brisement? Ta douleur est incurable; je t’ai fait ces choses à cause de la grandeur de ton iniquité, [parce que] tes péchés se sont renforcés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'C’est pourquoi tous ceux qui te dévorent seront dévorés, et tous tes ennemis, oui, tous, iront en captivité, et ceux qui te dépouillent seront dépouillés, et tous ceux qui te pillent je les livrerai au pillage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Car je t’appliquerai un appareil et je te guérirai de tes plaies, dit l’ Éternel; car ils t’ont appelée la Chassée: c’est Sion, que personne ne recherche!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Ainsi dit l’ Éternel: Voici, je rétablirai les captifs des tentes de Jacob, et j’aurai compassion de ses demeures; et la ville sera bâtie sur le monceau de ses ruines, et le palais sera habité selon sa coutume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Et il en sortira la louange et la voix de gens qui s’égaient; et je les multiplierai, et ils ne seront pas diminués; et je les glorifierai, et ils ne seront pas amoindris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Et ses fils seront comme jadis, et son assemblée sera affermie devant moi, et je punirai tous ses oppresseurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Et son chef sera de lui, et son dominateur sortira du milieu de lui; et je le ferai approcher, et il viendra à moi; car qui est celui qui engage son cœur pour venir à moi? dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Et vous serez mon peuple, et moi je serai votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Voici, une tempête de l’ Éternel, la fureur, est sortie; une tempête continue fondra sur la tête des méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'L’ardeur de la colère de l’ Éternel ne retournera pas, jusqu’à ce qu’il ait exécuté et accompli les pensées de son cœur. À la fin des jours vous le comprendrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'En ce temps-là, dit l’ Éternel, je serai le Dieu de toutes les familles d’Israël, et ils seront mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Ainsi dit l’ Éternel: Le peuple des réchappés de l’épée a trouvé grâce dans le désert; je m’en vais donner du repos à Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'L’ Éternel m’est apparu de loin: Je t’ai aimée d’un amour éternel; c’est pourquoi je t’attire avec bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Je te bâtirai encore, et tu seras bâtie, vierge d’Israël! Tu te pareras encore de tes tambourins, et tu sortiras dans la danse de ceux qui s’égaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Tu planteras encore des vignes sur les montagnes de Samarie; les planteurs les planteront, et en mangeront le fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Car il y a un jour auquel les gardes crieront sur la montagne d’Éphraïm: Levez-vous, et nous monterons à Sion, vers l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Car ainsi dit l’ Éternel: Exultez d’allégresse au sujet de Jacob, et poussez des cris de joie, à la tête des nations; faites éclater la louange, et dites: Éternel, sauve ton peuple, le reste d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Voici, je les fais venir du pays du nord, et je les rassemble des extrémités de la terre, [et] parmi eux l’aveugle et le boiteux, la femme enceinte et celle qui enfante, [tous] ensemble, – une grande congrégation: ils retourneront ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Ils viendront avec des larmes, et je les conduirai avec des supplications; je les ferai marcher vers des torrents d’eaux par un chemin droit; ils n’y trébucheront pas; car je serai pour père à Israël, et Éphraïm sera mon premier-né.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Nations, écoutez la parole de l’ Éternel, et annoncez-la aux îles éloignées, et dites: Celui qui a dispersé Israël le rassemblera et le gardera comme un berger son troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Car l’ Éternel a délivré Jacob, et l’a racheté de la main d’un plus fort que lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Et ils viendront et exulteront avec chant de triomphe sur les hauteurs de Sion, et ils afflueront vers les biens de l’ Éternel, au blé, et au moût, et à l’huile, et au fruit du menu et du gros bétail; et leur âme sera comme un jardin arrosé, et ils ne seront plus languissants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Alors la vierge se réjouira dans la danse, et les jeunes gens et les vieillards, [tous] ensemble. Et je changerai leur deuil en allégresse, et je les consolerai, et je les réjouirai [en les délivrant] de leur douleur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'et je rassasierai de graisse l’âme des sacrificateurs, et mon peuple sera rassasié de mes biens, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Ainsi dit l’ Éternel: Une voix a été entendue à Rama, une lamentation, des pleurs amers, Rachel pleurant ses fils, refusant d’être consolée au sujet de ses fils, parce qu’ils ne sont pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Ainsi dit l’ Éternel: Retiens ta voix de pleurer et tes yeux [de verser] des larmes; car il y a un salaire pour ton travail, dit l’ Éternel; et ils reviendront du pays de l’ennemi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Et il y a espoir pour ta fin, dit l’ Éternel, et tes fils reviendront dans leurs confins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'J’ai très bien entendu Éphraïm se lamentant: Tu m’as corrigé, et j’ai été corrigé comme un veau indompté; convertis-moi, et je serai converti, car tu es l’ Éternel, mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Car, après que j’ai été converti, je me suis repenti; et, après que je me suis connu, j’ai frappé sur ma cuisse; j’ai été honteux, et j’ai aussi été confus, car je porte l’opprobre de ma jeunesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Éphraïm m’est-il un fils précieux, un enfant de prédilection? Car depuis que j’ai parlé contre lui, je me souviens de lui encore constamment; c’est pourquoi mes entrailles se sont émues pour lui; certainement j’aurai compassion de lui, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Dresse-toi des signaux, place-toi des poteaux, mets ton cœur au chemin battu, au chemin par lequel tu es venue. Retourne, vierge d’Israël, retourne à ces tiennes villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Jusques à quand seras-tu errante, fille infidèle? Car l’ Éternel a créé une chose nouvelle sur la terre: une femme entourera l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Ainsi dit l’ Éternel des armées, le Dieu d’Israël: On dira encore cette parole dans le pays de Juda et dans ses villes, quand j’aurai rétabli leurs captifs: L’ Éternel te bénisse, demeure de justice, montagne de sainteté!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Et Juda y habitera, et toutes ses villes ensemble, les laboureurs, et ceux qui partent avec les troupeaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Car j’ai rassasié l’âme lassée, et j’ai rempli toute âme languissante. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Là-dessus je me suis réveillé, et j’ai regardé, et mon sommeil m’a été doux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Voici, des jours viennent, dit l’ Éternel, où j’ensemencerai la maison d’Israël et la maison de Juda de semence d’hommes et de semence de bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Et il arrivera que, comme j’ai veillé sur eux pour arracher, et pour démolir, et pour renverser, et pour détruire, et pour faire du mal, ainsi je veillerai sur eux pour bâtir et pour planter, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'En ces jours-là on ne dira plus: Les pères ont mangé du raisin vert et les dents des fils en sont agacées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Car chacun mourra dans son iniquité: tout homme qui mangera du raisin vert, en aura ses dents agacées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Voici, des jours viennent, dit l’ Éternel, et j’établirai avec la maison d’Israël et avec la maison de Juda une nouvelle alliance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'non selon l’alliance que je fis avec leurs pères, au jour où je les pris par la main pour les faire sortir du pays d’Égypte, mon alliance qu’ils ont rompue, quoique je les aie épousés, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Car c’est ici l’alliance que j’établirai avec la maison d’Israël, après ces jours-là, dit l’ Éternel: Je mettrai ma loi au-dedans d’eux, et je l’écrirai sur leur cœur, et je serai leur Dieu, et ils seront mon peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'et ils n’enseigneront plus chacun son prochain, et chacun son frère, disant: Connaissez l’ Éternel; car ils me connaîtront tous, depuis le petit d’entre eux jusqu’au grand, dit l’ Éternel; car je pardonnerai leur iniquité, et je ne me souviendrai plus de leur péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Ainsi dit l’ Éternel, qui donne le soleil pour la lumière du jour, les ordonnances de la lune et des étoiles pour la lumière de la nuit; qui soulève la mer, et ses flots mugissent; l’ Éternel des armées est son nom:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Si jamais ces ordonnances s’en vont de devant moi, dit l’ Éternel, la semence d’Israël cessera aussi d’être une nation devant moi pour toujours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Ainsi dit l’ Éternel: Si on mesure les cieux en haut, et qu’on sonde les fondements de la terre en bas, alors aussi moi, je rejetterai toute la race d’Israël, à cause de tout ce qu’ils ont fait, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Voici, les jours viennent, dit l’ Éternel, où la ville sera bâtie à l’ Éternel depuis la tour de Hananeël jusqu’à la porte du coin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'et le cordeau à mesurer sortira encore vis-à-vis d’elle jusqu’à la colline de Gareb et fera le tour jusqu’à Goath;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'et toute la vallée des cadavres et des cendres, et tous les champs jusqu’au torrent du Cédron, jusqu’au coin de la porte des chevaux vers le levant, seront saints, [consacrés] à l’ Éternel: elle ne sera plus arrachée ni renversée, à jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, '*La parole qui vint à Jérémie de par l’ Éternel, en la dixième année de Sédécias, roi de Juda (ce fut la dix -huitième année de Nebucadretsar).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Et l’armée du roi de Babylone assiégeait alors Jérusalem, et Jérémie le prophète était enfermé dans la cour de la prison qui était dans la maison du roi de Juda,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'où Sédécias, roi de Juda, l’avait enfermé, disant: Pourquoi prophétises-tu, disant: Ainsi dit l’ Éternel: Voici, je livre cette ville en la main du roi de Babylone, et il la prendra;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'et Sédécias, roi de Juda, ne sera pas délivré de la main des Chaldéens, car certainement il sera livré en la main du roi de Babylone, et il lui parlera bouche à bouche, et ses yeux verront ses yeux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'et il fera aller Sédécias à Babylone, et il sera là, jusqu’à ce que je le visite, dit l’ Éternel: si vous combattez contre les Chaldéens, vous ne réussirez pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Et Jérémie dit: La parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Voici, Hanameël, fils de Shallum ton oncle, vient vers toi, disant: Achète-toi mon champ qui est à Anathoth, car le droit de rachat est à toi pour l’acheter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Et Hanameël, fils de mon oncle, vint vers moi, selon la parole de l’ Éternel, dans la cour de la prison, et me dit: Achète, je te prie, mon champ qui est à Anathoth, dans le pays de Benjamin, car à toi est le droit d’héritage, et à toi le rachat: achète-le pour toi. Et je connus que c’était la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Et j’achetai de Hanameël, fils de mon oncle, le champ qui est à Anathoth; et je lui pesai l’argent, 17 sicles d’argent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'et j’en écrivis la lettre, et je la scellai, et je la fis attester par des témoins, et je pesai l’argent dans la balance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'et je pris la lettre d’achat, celle qui était scellée [selon] le commandement et les statuts, et celle qui était ouverte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'et je donnai la lettre d’achat à Baruc, fils de Nérija, fils de Makhséïa, sous les yeux de Hanameël [le fils de] mon oncle, et sous les yeux des témoins qui avaient signé à la lettre d’achat, [et] sous les yeux de tous les Juifs qui étaient assis dans la cour de la prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Et je commandai sous leurs yeux à Baruc, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Prends ces lettres, cette lettre d’achat, celle qui est scellée, et cette lettre ouverte, et mets-les dans un vase de terre, afin qu’elles se conservent beaucoup de jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Car ainsi dit l’ Éternel des armées, le Dieu d’Israël: On achètera encore des maisons, et des champs, et des vignes, dans ce pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Et après avoir donné à Baruc, fils de Nérija, la lettre d’achat, je priai l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ah, Seigneur Éternel! voici, tu as fait les cieux et la terre par ta grande puissance, et par ton bras étendu; aucune chose n’est trop difficile pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Tu uses de bonté envers des milliers [de générations], et tu rétribueras l’iniquité des pères dans le sein de leurs fils après eux, toi, le ✶Dieu grand et fort (l’ Éternel des armées est son nom),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'grand en conseil et abondant en œuvres, dont les yeux sont ouverts sur toutes les voies des fils des hommes, pour rendre à chacun selon ses voies et selon le fruit de ses actions;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'toi qui as fait des signes et des prodiges jusqu’à ce jour dans le pays d’Égypte, et en Israël, et parmi les hommes, et qui t’es fait un nom tel qu’il est aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Et tu as fait sortir ton peuple Israël du pays d’Égypte, avec des signes et avec des prodiges, et à main forte et à bras étendu, et par une grande frayeur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'et tu leur as donné ce pays, que tu avais juré à leurs pères de leur donner, un pays ruisselant de lait et de miel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'et ils y sont entrés, et l’ont possédé; mais ils n’ont point écouté ta voix, et n’ont pas marché dans ta loi; et tout ce que tu leur avais commandé de faire ils ne l’ont pas fait, de sorte que tu leur as fait rencontrer tout ce mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Voici, les terrasses sont venues jusqu’à la ville, pour la prendre; et la ville est livrée par l’épée, et par la famine, et par la peste, en la main des Chaldéens qui combattent contre elle; et ce que tu as dit est arrivé; et voici, tu le vois!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Et toi, Seigneur Éternel! tu m’as dit: Achète-toi le champ à prix d’argent, et fais-le attester par des témoins;... et la ville est livrée en la main des Chaldéens!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Et la parole de l’ Éternel vint à Jérémie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Voici, je suis l’ Éternel, le Dieu de toute chair; quelque chose est-il trop difficile pour moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'C’est pourquoi, ainsi dit l’ Éternel: Voici, je livre cette ville en la main des Chaldéens, et en la main de Nebucadretsar, roi de Babylone; et il la prendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Et les Chaldéens qui combattent contre cette ville entreront, et mettront le feu à cette ville, et la brûleront, et les maisons sur les toits desquelles on a brûlé de l’encens à Baal et répandu des libations à d’autres dieux, pour me provoquer à colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Car les fils d’Israël et les fils de Juda n’ont fait, dès leur jeunesse, que ce qui est mauvais à mes yeux; car les fils d’Israël n’ont fait que me provoquer par l’œuvre de leurs mains, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Car cette ville a été [une provocation] à ma colère et à ma fureur, depuis le jour où ils l’ont bâtie jusqu’à ce jour, afin que je l’ôte de devant ma face,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'à cause de toute l’iniquité des fils d’Israël et des fils de Juda, qu’ils ont commise pour me provoquer, eux, leurs rois, leurs princes, leurs sacrificateurs, et leurs prophètes, et les hommes de Juda, et les habitants de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Ils m’ont tourné le dos et non la face; et je les ai enseignés, me levant de bonne heure et [les] enseignant, et ils n’ont pas écouté pour recevoir l’instruction;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'et ils ont mis leurs abominations dans la maison qui est appelée de mon nom, pour la rendre impure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'et ils ont bâti les hauts lieux de Baal, qui sont dans la vallée du fils de Hinnom, pour faire passer [par le feu] leurs fils et leurs filles à Moloc: ce que je ne leur ai point commandé; et il ne m’est point monté au cœur qu’ils fassent cette chose abominable, pour faire pécher Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Et maintenant, à cause de cela, l’ Éternel, le Dieu d’Israël, dit ainsi touchant cette ville dont vous dites qu’elle est livrée en la main du roi de Babylone par l’épée, et par la famine, et par la peste:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Voici, je les rassemblerai de tous les pays où je les ai chassés dans ma colère, et dans ma fureur, et dans [mon] grand courroux; et je les ferai retourner en ce lieu; et je les ferai habiter en sécurité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'et ils seront mon peuple, et moi je serai leur Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'et je leur donnerai un seul cœur, et une seule voie, pour me craindre tous les jours, pour leur bien et [le bien] de leurs fils après eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'et je ferai avec eux une alliance éternelle, que je ne me retirerai point d’auprès d’eux, pour leur faire du bien; et je mettrai ma crainte dans leur cœur, pour qu’ils ne se retirent pas de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Et je me réjouirai en eux pour leur faire du bien, et je les planterai dans ce pays, en vérité, de tout mon cœur et de toute mon âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Car ainsi dit l’ Éternel: Comme j’ai fait venir sur ce peuple tout ce grand mal, ainsi je ferai venir sur eux tout le bien que j’ai prononcé à leur égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Et on achètera des champs dans ce pays dont vous dites qu’il est une désolation, de sorte qu’il n’y a ni homme, ni bête; il est livré en la main des Chaldéens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'On achètera des champs à prix d’argent, et on en écrira les lettres, et on les scellera, et on les fera attester par des témoins dans le pays de Benjamin, et aux environs de Jérusalem, et dans les villes de Juda, et dans les villes de la montagne, et dans les villes du pays plat, et dans les villes du midi; car je rétablirai leurs captifs, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Et la parole de l’ Éternel vint à Jérémie une seconde fois, lorsqu’il était encore enfermé dans la cour de la prison, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Ainsi dit l’ Éternel qui fait cela, l’ Éternel qui se le propose pour l’effectuer, l’ Éternel est son nom:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Crie vers moi, et je te répondrai, et je te déclarerai des choses grandes et cachées que tu ne sais pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Car ainsi dit l’ Éternel, le Dieu d’Israël, touchant les maisons de cette ville et touchant les maisons des rois de Juda, qui sont renversées à cause des terrasses et à cause de l’épée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Ils s’en vont pour combattre contre les Chaldéens, pour remplir les [maisons] des cadavres des hommes que j’ai frappés dans ma colère et dans ma fureur, et à cause de toute l’iniquité desquels j’ai caché ma face de cette ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Voici, je lui appliquerai un appareil de pansement, et des remèdes, et je les guérirai, et leur révélerai une abondance de paix et de vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'et je rétablirai les captifs de Juda et les captifs d’Israël, et je les bâtirai comme au commencement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'et je les purifierai de toute leur iniquité [par] laquelle ils ont péché contre moi, et je pardonnerai toutes leurs iniquités [par] lesquelles ils ont péché contre moi et [par] lesquelles ils se sont rebellés contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Et ce sera pour moi un nom d’allégresse, une louange et un ornement parmi toutes les nations de la terre, qui apprendront toute la bonté dont j’ai usé envers eux; et ils craindront et trembleront à cause de tout le bien et à cause de toute la prospérité dont je les ferai jouir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Ainsi dit l’ Éternel: Dans ce lieu-ci dont vous dites: C’est un désert où il n’y a pas d’homme et où il n’y a pas de bête, dans les villes de Juda et dans les rues de Jérusalem, qui sont désolées, où il n’y a pas d’homme, et où il n’y a pas d’habitant, et où il n’y a pas de bête, on entendra encore');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'la voix de l’allégresse et la voix de la joie, la voix de l’époux et la voix de l’épouse, la voix de ceux qui disent: Célébrez l’ Éternel des armées, car l’ Éternel est bon, car sa bonté [demeure] à toujours, – des gens qui apportent des actions de grâces à la maison de l’ Éternel. Car je délivrerai le pays de sa captivité, et je le rétablirai comme il était au commencement, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Ainsi dit l’ Éternel des armées: Dans ce lieu qui est désert, où il n’y a ni homme ni bête, et dans toutes ses villes, il y aura encore une demeure de bergers qui y feront reposer leur menu bétail;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'dans les villes de la montagne, dans les villes du pays plat, et dans les villes du midi, et dans le pays de Benjamin, et dans les environs de Jérusalem, et dans les villes de Juda, le menu bétail passera encore sous les mains de celui qui le compte, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Voici, des jours viennent, dit l’ Éternel, où j’accomplirai la bonne parole que j’ai dite à la maison d’Israël et à la maison de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'En ces jours-là, et en ce temps-là, je ferai germer à David un Germe de justice, et il exercera le jugement et la justice dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'En ces jours-là Juda sera sauvé, et Jérusalem demeurera en sécurité; et voici comment on l’appellera: L’ Éternel notre justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Car ainsi dit l’ Éternel: David ne manquera pas d’un homme assis sur le trône de la maison d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'et les sacrificateurs, les Lévites, ne manqueront pas, devant moi, d’un homme offrant des holocaustes, et faisant fumer des offrandes de gâteau, et faisant des sacrifices, tous les jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Et la parole de l’ Éternel vint à Jérémie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Ainsi dit l’ Éternel: Quand vous romprez mon alliance touchant le jour, et mon alliance touchant la nuit, de sorte qu’il n’y ait pas de jour et de nuit en leur temps,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'alors aussi mon alliance avec David, mon serviteur, sera rompue, de sorte qu’il n’ait pas de fils régnant sur son trône, – et avec les Lévites, les sacrificateurs, qui me servent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Comme l’armée des cieux ne peut se nombrer, ni le sable de la mer se mesurer, ainsi je multiplierai la semence de David, mon serviteur, et les Lévites qui me servent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Et la parole de l’ Éternel vint à Jérémie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'N’as-tu pas vu ce que ce peuple a dit, disant: Les deux familles que l’ Éternel avait choisies, il les a aussi rejetées?... Et ils ont méprisé mon peuple de manière à ce que, devant eux, il ne soit plus une nation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Ainsi dit l’ Éternel: Si mon alliance touchant le jour et la nuit ne [demeure] pas, si je n’ai pas établi les ordonnances des cieux et de la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'alors aussi je rejetterai la semence de Jacob et de David, mon serviteur, pour ne pas prendre de sa semence ceux qui domineront sur la semence d’Abraham, d’Isaac et de Jacob, car je rétablirai leurs captifs, et j’aurai compassion d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, '**La parole qui vint à Jérémie de par l’ Éternel, lorsque Nebucadnetsar, roi de Babylone, et toute son armée, et tous les royaumes de la terre sur lesquels dominait sa main, et tous les peuples, combattaient contre Jérusalem et contre toutes ses villes, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Ainsi dit l’ Éternel, le Dieu d’Israël: Va, et tu parleras à Sédécias, roi de Juda, et tu lui diras: Ainsi dit l’ Éternel: Voici, je livre cette ville en la main du roi de Babylone, et il la brûlera par le feu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'et toi, tu n’échapperas pas à sa main, car certainement tu seras pris, et tu seras livré en sa main, et tes yeux verront les yeux du roi de Babylone, et sa bouche parlera à ta bouche, et tu iras à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Seulement, écoute la parole de l’ Éternel, Sédécias, roi de Juda! Ainsi dit l’ Éternel sur toi: Tu ne mourras pas par l’épée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'tu mourras en paix, et, comme on a brûlé [des aromates] pour tes pères, les rois précédents qui ont été avant toi, ainsi on en brûlera pour toi, et on se lamentera sur toi, [disant]: Hélas, seigneur! Car j’ai dit cette parole, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Et Jérémie le prophète dit à Sédécias, roi de Juda, toutes ces paroles, dans Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Et l’armée du roi de Babylone combattit contre Jérusalem, et contre toutes les villes de Juda qui restaient, contre Lakis et contre Azéka; car c’étaient, d’entre les villes de Juda, les villes fortes qui restaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'La parole qui vint à Jérémie de par l’ Éternel, après que le roi Sédécias eut fait un pacte avec tout le peuple qui était à Jérusalem, pour leur proclamer la liberté:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'pour que chacun renvoie libre son serviteur, et chacun sa servante, hébreu ou hébreue, pour que personne ne fasse plus servir son frère, un Juif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Et tous les princes et tout le peuple qui étaient entrés dans ce pacte écoutèrent pour renvoyer libres chacun son serviteur et chacun sa servante, pour ne plus les obliger à servir: ils écoutèrent et les renvoyèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Mais ensuite ils revinrent en arrière, et firent revenir les serviteurs et les servantes qu’ils avaient renvoyés libres, et les assujettirent pour être serviteurs et servantes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Et la parole de l’ Éternel vint à Jérémie de par l’ Éternel, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Ainsi dit l’ Éternel, le Dieu d’Israël: J’ai fait une alliance avec vos pères, au jour où je les ai fait sortir du pays d’Égypte, de la maison de servitude, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Au bout de sept ans vous renverrez chacun votre frère, l’hébreu qui se sera vendu à toi; il te servira six ans, et tu le renverras libre de chez toi. Mais vos pères ne m’ont point écouté, et n’ont pas incliné leur oreille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Et vous, vous en étiez revenus aujourd’hui, et vous aviez fait ce qui est droit à mes yeux, en proclamant la liberté chacun à son prochain, et vous aviez fait une alliance devant moi, dans la maison qui est appelée de mon nom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'mais vous êtes revenus en arrière, et vous avez profané mon nom; et vous avez fait revenir chacun son serviteur, et chacun sa servante, que vous aviez renvoyés libres [pour agir] à leur gré, et vous les avez assujettis pour vous être serviteurs et servantes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'C’est pourquoi, ainsi dit l’ Éternel: Vous ne m’avez point écouté pour proclamer la liberté chacun à son frère, et chacun à son prochain; voici, je proclame, dit l’ Éternel, la liberté contre vous à l’épée, à la peste, et à la famine; et je vous livrerai pour être chassés çà et là par tous les royaumes de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Et je livrerai les hommes qui ont transgressé mon alliance, qui n’ont point accompli les paroles de l’alliance qu’ils avaient faite devant moi (le veau qu’ils ont coupé en deux et entre les pièces duquel ils ont passé),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'les princes de Juda, et les princes de Jérusalem, les eunuques, et les sacrificateurs, et tout le peuple du pays, qui ont passé entre les pièces du veau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'je les livrerai en la main de leurs ennemis, et en la main de ceux qui cherchent leur vie, et leurs cadavres seront en pâture aux oiseaux des cieux et aux bêtes de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Et je livrerai Sédécias, roi de Juda, et ses princes, en la main de leurs ennemis, et en la main de ceux qui cherchent leur vie, et en la main de l’armée du roi de Babylone, qui s’est retirée d’auprès de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Voici, je commande, dit l’ Éternel, et je les fais revenir contre cette ville; et ils combattront contre elle, et la prendront, et la brûleront par le feu; et des villes de Juda, j’en ferai une désolation, de sorte qu’il n’y aura pas d’habitant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, '*La parole qui vint à Jérémie, de par l’ Éternel, aux jours de Jehoïakim, fils de Josias, roi de Juda, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Va à la maison des Récabites, et parle-leur, et amène-les dans la maison de l’ Éternel, dans une des chambres, et verse-leur du vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Et je pris Jaazania, fils de Jérémie, fils de Habatsinia, et ses frères, et tous ses fils, et toute la maison des Récabites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'et je les amenai dans la maison de l’ Éternel, dans la chambre des fils de Hanan, fils de Jigdalia, homme de Dieu, qui était à côté de la chambre des princes, laquelle était au-dessus de la chambre de Maascéïa, fils de Shallum, gardien du seuil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'et je mis devant les fils de la maison des Récabites des gobelets pleins de vin, et des coupes, et je leur dis: Buvez du vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Et ils dirent: Nous ne boirons point de vin; car Jonadab, fils de Récab, notre père, nous a commandé, disant: Vous ne boirez point de vin, ni vous, ni vos fils, à toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'et vous ne bâtirez pas de maison, et vous ne sèmerez pas de semence, et vous ne planterez pas de vigne, et vous n’en aurez point; mais vous habiterez dans des tentes tous vos jours, afin que vous viviez beaucoup de jours sur la face de la terre où vous séjournez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Et nous avons écouté la voix de Jonadab, fils de Récab, notre père, dans tout ce qu’il nous a commandé, pour ne pas boire de vin tous nos jours, ni nous, ni nos femmes, ni nos fils, ni nos filles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'et pour ne pas bâtir des maisons pour notre demeure, et pour n’avoir ni vigne, ni champ, ni semaille;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'et nous avons habité dans des tentes, et nous avons écouté, et nous avons fait selon tout ce que nous a commandé Jonadab, notre père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Et il est arrivé que, quand Nebucadretsar, roi de Babylone, est monté contre le pays, nous avons dit: Venez, et entrons dans Jérusalem devant l’armée des Chaldéens et devant l’armée de Syrie; et nous habitons à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Et la parole de l’ Éternel vint à Jérémie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Va, et dis aux hommes de Juda et aux habitants de Jérusalem: Ne recevrez-vous point instruction pour écouter mes paroles? dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Les paroles de Jonadab, fils de Récab, qu’il a commandées à ses fils, de ne point boire de vin, ont été observées, et ils n’en ont pas bu jusqu’à ce jour; car ils ont écouté le commandement de leur père. Mais moi, je vous ai parlé, me levant de bonne heure et parlant; et vous ne m’avez point écouté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Et je vous ai envoyé tous mes serviteurs les prophètes, me levant de bonne heure et [les] envoyant, disant: Revenez donc chacun de sa mauvaise voie, et amendez vos actions, et n’allez pas après d’autres dieux pour les servir, et vous habiterez sur la terre que j’ai donnée à vous et à vos pères. Mais vous n’avez pas incliné votre oreille, et vous ne m’avez pas écouté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Oui, les fils de Jonadab, fils de Récab, ont observé le commandement de leur père qu’il leur avait commandé, et ce peuple ne m’a pas écouté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'à cause de cela, ainsi dit l’ Éternel, le Dieu des armées, le Dieu d’Israël: Voici, je fais venir sur Juda, et sur tous les habitants de Jérusalem, tout le mal que j’ai prononcé contre eux, parce que je leur ai parlé, et ils n’ont pas écouté, et que je les ai appelés, et ils n’ont pas répondu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Et Jérémie dit à la maison des Récabites: Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Parce que vous avez écouté le commandement de Jonadab, votre père, et que vous avez observé tous ses commandements et avez fait selon tout ce qu’il vous a commandé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'à cause de cela, ainsi dit l’ Éternel des armées, le Dieu d’Israël: Jonadab, fils de Récab, ne manquera jamais d’un homme qui se tienne devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, '*Et il arriva, en la quatrième année de Jehoïakim, fils de Josias, roi de Juda, que cette parole vint de par l’ Éternel à Jérémie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Prends-toi un rouleau de livre, et y écris toutes les paroles que je t’ai dites contre Israël et contre Juda, et contre toutes les nations, depuis le jour où je t’ai parlé, depuis les jours de Josias et jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Peut-être la maison de Juda écoutera-t-elle tout le mal que je pense à lui faire, afin qu’ils reviennent chacun de sa mauvaise voie, et que je leur pardonne leur iniquité et leur péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Et Jérémie appela Baruc, fils de Nérija; et Baruc écrivit, de la bouche de Jérémie, sur un rouleau de livre, toutes les paroles de l’ Éternel, qu’il lui dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Et Jérémie commanda à Baruc, disant: Je suis enfermé, je ne puis entrer dans la maison de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'mais toi, tu y entreras, et tu liras, dans le rouleau que tu as écrit de ma bouche, les paroles de l’ Éternel, aux oreilles du peuple, dans la maison de l’ Éternel, le jour du jeûne; et tu les liras aussi aux oreilles de tous ceux de Juda qui viennent de leurs villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Peut-être leur supplication sera-t-elle présentée devant l’ Éternel, et ils reviendront chacun de sa mauvaise voie; car grande est la colère et la fureur que l’ Éternel a prononcée contre ce peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Et Baruc, fils de Nérija, fit selon tout ce que Jérémie le prophète lui avait commandé, pour lire dans le livre les paroles de l’ Éternel, dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Et il arriva, en la cinquième année de Jehoïakim, fils de Josias, roi de Juda, au neuvième mois, qu’on proclama un jeûne devant l’ Éternel pour tout le peuple à Jérusalem et pour tout le peuple qui venait des villes de Juda à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Et Baruc lut dans le livre les paroles de Jérémie, dans la maison de l’ Éternel, dans la chambre de Guemaria, fils de Shaphan, le scribe, dans le parvis supérieur, à l’entrée de la porte neuve de la maison de l’ Éternel, aux oreilles de tout le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Et Michée, fils de Guemaria, fils de Shaphan, entendit du livre toutes les paroles de l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'et il descendit dans la maison du roi, dans la chambre du scribe, et voici, tous les princes y étaient assis: Élishama, le scribe, et Delaïa, fils de Shemahia, et Elnathan, fils d’Acbor, et Guemaria, fils de Shaphan, et Sédécias, fils de Hanania, et tous les princes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Et Michée leur rapporta toutes les paroles qu’il avait entendues, quand Baruc lisait dans le livre aux oreilles du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Et tous les princes envoyèrent Jehudi, fils de Nethania, fils de Shélémia, fils de Cushi, vers Baruc, pour [lui] dire: Prends dans ta main le rouleau dans lequel tu as lu aux oreilles du peuple, et viens. – Et Baruc, fils de Nérija, prit le rouleau dans sa main, et vint vers eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Et ils lui dirent: Assieds-toi, et lis-le à nos oreilles. Et Baruc lut à leurs oreilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Et il arriva, lorsqu’ils entendirent toutes ces paroles, qu’ils furent effrayés, [se regardant] l’un l’autre; et ils dirent à Baruc: Certainement nous rapporterons au roi toutes ces paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Et ils interrogèrent Baruc, disant: Raconte-nous comment tu as écrit toutes ces paroles sous sa dictée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Et Baruc leur dit: De sa bouche il m’a dicté toutes ces paroles, et moi j’écrivais dans le livre avec de l’encre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Et les princes dirent à Baruc: Va, cache-toi, toi et Jérémie; et que personne ne sache où vous êtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Et ils vinrent vers le roi, dans la cour, et ils déposèrent le rouleau dans la chambre d’Élishama, le scribe; et ils rapportèrent aux oreilles du roi toutes les paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Et le roi envoya Jehudi pour prendre le rouleau; et il le prit de la chambre d’Élishama, le scribe, et Jehudi le lut aux oreilles du roi et aux oreilles de tous les princes qui se tenaient là près du roi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'et le roi était assis dans la maison d’hiver, au neuvième mois; et le brasier brûlait devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Et il arriva que, quand Jehudi en eut lu trois ou quatre pages, [le roi] le coupa avec le canif du scribe et le jeta au feu qui était dans le brasier, jusqu’à ce que tout le rouleau soit consumé au feu qui était dans le brasier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Et ils ne craignirent pas, et ne déchirèrent pas leurs vêtements, [ni] le roi ni tous ses serviteurs qui entendirent toutes ces paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Et même Elnathan, et Delaïa, et Guemaria, intercédèrent auprès du roi, afin qu’il ne brûle pas le rouleau; mais il ne les écouta point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Et le roi commanda à Jerakhmeël, fils d’Hammélec, et à Seraïa, fils d’Azriel, et à Shélémia, fils d’Abdeël, de prendre Baruc, le scribe, et Jérémie le prophète; mais l’ Éternel les cacha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Et après que le roi eut brûlé le rouleau et les paroles que Baruc avait écrites de la bouche de Jérémie, la parole de l’ Éternel vint à Jérémie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Prends-toi encore un autre rouleau, et écris-y toutes les premières paroles qui étaient sur le premier rouleau que Jehoïakim, roi de Juda, a brûlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Et tu diras à Jehoïakim, roi de Juda: Ainsi dit l’ Éternel: Tu as brûlé ce rouleau, en disant: Pourquoi y as-tu écrit, disant: Le roi de Babylone viendra certainement, et il détruira ce pays et en fera disparaître les hommes et les bêtes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'C’est pourquoi, ainsi dit l’ Éternel touchant Jehoïakim, roi de Juda: Il n’aura personne qui s’asseye sur le trône de David, et son cadavre sera jeté dehors, de jour à la chaleur, et de nuit à la gelée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Et je le punirai, lui, et sa semence, et ses serviteurs, pour leur iniquité, et je ferai venir sur eux, et sur les habitants de Jérusalem, et sur les hommes de Juda, tout le mal que je leur ai annoncé, et ils n’ont point écouté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Et Jérémie prit un autre rouleau, et le donna à Baruc, fils de Nérija, le scribe; et il y écrivit, de la bouche de Jérémie, toutes les paroles du livre que Jehoïakim, roi de Juda, avait brûlé au feu; et il y fut encore ajouté plusieurs paroles semblables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, '*Et le roi Sédécias, fils de Josias, régna à la place de Conia, fils de Jehoïakim: Nebucadretsar, roi de Babylone, l’avait établi roi sur le pays de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Et il n’écouta point, ni lui, ni ses serviteurs, ni le peuple du pays, les paroles de l’ Éternel qu’il avait dites par Jérémie le prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Et le roi Sédécias envoya Jucal, fils de Shélémia, et Sophonie, fils de Maascéïa, le sacrificateur, vers Jérémie le prophète, disant: Intercède, je te prie, pour nous, auprès de l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Et Jérémie entrait et sortait parmi le peuple, et on ne l’avait pas [encore] mis en prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Et l’armée du Pharaon était sortie d’Égypte, et les Chaldéens qui assiégeaient Jérusalem, en entendirent la nouvelle et se retirèrent de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Et la parole de l’ Éternel vint à Jérémie le prophète, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Ainsi dit l’ Éternel, le Dieu d’Israël: Vous direz ainsi au roi de Juda, qui vous a envoyés vers moi pour me consulter: Voici, l’armée du Pharaon, qui est sortie à votre secours, retournera dans son pays d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'et les Chaldéens reviendront, et combattront contre cette ville, et ils la prendront, et la brûleront par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Ainsi dit l’ Éternel: N’abusez point vos âmes, disant: Les Chaldéens s’en sont allés de nous tout de bon; car ils ne s’en sont pas allés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Car si vous aviez frappé toute l’armée des Chaldéens qui combattent contre vous, et qu’il n’en reste que des gens transpercés, ils se relèveraient chacun dans sa tente et brûleraient cette ville par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Et il arriva, quand l’armée des Chaldéens se retira de Jérusalem à cause de l’armée du Pharaon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'que Jérémie sortit de Jérusalem pour s’en aller dans le pays de Benjamin au milieu du peuple, pour avoir de là [sa] part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Et comme il était dans la porte de Benjamin, il y avait là un capitaine de la garde (et son nom était Jirija, fils de Shélémia, fils de Hanania), et il saisit Jérémie le prophète, en disant: Tu vas te rendre aux Chaldéens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Et Jérémie dit: C’est un mensonge; je ne vais point me rendre aux Chaldéens. Mais il ne l’écouta pas; et Jirija saisit Jérémie et l’amena aux princes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Et les princes se mirent en colère contre Jérémie, et le battirent, et le mirent en prison dans la maison de Jonathan, le scribe; car ils en avaient fait une maison de détention.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Quand Jérémie fut entré dans la maison de la fosse et dans les caveaux, et que Jérémie fut resté là bien des jours,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'le roi Sédécias envoya, et le prit. Et le roi l’interrogea en secret dans sa maison, et dit: Y a-t-il quelque parole de par l’ Éternel? Et Jérémie dit: Il y en a une; et il dit: Tu seras livré en la main du roi de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Et Jérémie dit au roi Sédécias: Quel péché ai-je commis contre toi, et contre tes serviteurs, et contre ce peuple, que vous m’ayez mis dans la maison de détention?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Et où sont vos prophètes qui vous prophétisaient, disant: Le roi de Babylone ne viendra point contre vous, ni contre ce pays?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Et maintenant écoute, je te prie, ô roi, mon seigneur: que ma requête soit reçue devant toi, et ne me fais pas retourner dans la maison de Jonathan, le scribe, de peur que je n’y meure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Et le roi Sédécias commanda, et on fit garder Jérémie dans la cour de la prison; et on lui donna par jour un pain, de la rue des boulangers, jusqu’à ce que fut consommé tout le pain de la ville. Et Jérémie demeura dans la cour de la prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Et Shephatia, fils de Matthan, et Guedalia, fils de Pashkhur, et Jucal, fils de Shélémia, et Pashkhur, fils de Malkija, entendirent les paroles que Jérémie disait à tout le peuple, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Ainsi dit l’ Éternel: Celui qui demeurera dans cette ville mourra par l’épée, par la famine, ou par la peste; et celui qui sortira vers les Chaldéens vivra, et aura sa vie pour butin et vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Ainsi dit l’ Éternel: Cette ville sera livrée certainement en la main de l’armée du roi de Babylone, et il la prendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Et les princes dirent au roi: Qu’on fasse donc mourir cet homme! car pourquoi rend-il lâches les mains des hommes de guerre qui sont de reste dans cette ville, et les mains de tout le peuple, en leur parlant selon ces paroles? car cet homme ne cherche point la prospérité de ce peuple, mais le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Et le roi Sédécias dit: Voici, il est entre vos mains; car le roi ne peut rien contre vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Et ils prirent Jérémie et le jetèrent dans la fosse de Malkija, fils d’Hammélec, laquelle était dans la cour de la prison; et ils descendirent Jérémie avec des cordes; et il n’y avait point d’eau dans la fosse, mais de la boue, et Jérémie enfonça dans la boue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Et Ébed-Mélec, l’Éthiopien, un eunuque, qui était dans la maison du roi, apprit qu’ils avaient mis Jérémie dans la fosse; et le roi était assis dans la porte de Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Et Ébed-Mélec sortit de la maison du roi, et parla au roi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Ô roi, mon seigneur! ces hommes ont mal fait dans tout ce qu’ils ont fait à Jérémie le prophète, qu’ils ont jeté dans la fosse; il mourra là où il est, à cause de la famine, car il n’y a plus de pain dans la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Et le roi commanda à Ébed-Mélec, l’Éthiopien, disant: Prends d’ici 30 hommes sous tes ordres, et fais monter Jérémie le prophète hors de la fosse, avant qu’il meure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Et Ébed-Mélec prit les hommes sous ses ordres, et alla dans la maison du roi, au-dessous du trésor. Et il prit de là de vieux lambeaux d’étoffes et de vieux haillons, et les descendit avec des cordes à Jérémie dans la fosse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'et Ébed-Mélec, l’Éthiopien, dit à Jérémie: Mets ces vieux lambeaux et ces haillons sous les aisselles de tes bras, sous les cordes. Et Jérémie fit ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Et ils tirèrent Jérémie dehors avec les cordes, et le firent monter hors de la fosse. Et Jérémie habita dans la cour de la prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Et le roi Sédécias envoya, et se fit amener Jérémie le prophète, à la troisième entrée qui était dans la maison de l’ Éternel. Et le roi dit à Jérémie: Je te demanderai une chose; ne me cache rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Et Jérémie dit à Sédécias: Si je te le déclare, ne me feras-tu pas mourir? Et si je te donne un conseil, tu ne m’écouteras pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Et le roi Sédécias jura secrètement à Jérémie, disant: L’ Éternel est vivant qui a fait notre âme: si je te fais mourir, et si je te livre en la main de ces hommes qui cherchent ta vie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Et Jérémie dit à Sédécias: Ainsi dit l’ Éternel, le Dieu des armées, le Dieu d’Israël: Si tu sors franchement vers les princes du roi de Babylone, ton âme vivra et cette ville ne sera point brûlée par le feu, mais tu vivras, toi et ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Mais si tu ne sors pas vers les princes du roi de Babylone, cette ville sera livrée en la main des Chaldéens, et ils la brûleront par le feu; et toi, tu n’échapperas pas à leur main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Et le roi Sédécias dit à Jérémie: Je crains les Juifs qui se sont rendus aux Chaldéens; [j’ai] peur qu’on ne me livre en leur main, et qu’ils ne me maltraitent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Et Jérémie dit: On ne te livrera point; écoute, je te prie, la voix de l’ Éternel dans ce que je te dis, et tout ira bien pour toi, et ton âme vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Mais si tu refuses de sortir, voici la parole que l’ Éternel m’a fait voir:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Voici, toutes les femmes qui sont de reste dans la maison du roi de Juda seront menées dehors vers les princes du roi de Babylone, et elles diront: Tes familiers t’ont entraîné, ils ont prévalu sur toi; tes pieds se sont enfoncés dans le bourbier, ils ont glissé en arrière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Et toutes tes femmes et tes fils, on les mènera dehors vers les Chaldéens, et toi tu n’échapperas pas à leur main; car tu seras pris par la main du roi de Babylone, et tu feras que cette ville sera brûlée par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Et Sédécias dit à Jérémie: Que personne ne sache rien de ces paroles, et tu ne mourras pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'et si les princes entendent que j’ai parlé avec toi, et qu’ils viennent vers toi et te disent: Déclare-nous donc ce que tu as dit au roi; ne nous le cache pas, et nous ne te ferons point mourir; et que t’a dit le roi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'tu leur diras: J’ai présenté ma requête devant le roi, qu’on ne me fasse pas retourner dans la maison de Jonathan pour y mourir. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Et tous les princes vinrent vers Jérémie, et l’interrogèrent; et il leur rapporta [la chose] selon toutes ces paroles que le roi avait commandées; et ils se turent et le laissèrent, car l’affaire ne s’ébruita pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Et Jérémie habita dans la cour de la prison jusqu’au jour où Jérusalem fut prise. *Et il arriva, lorsque Jérusalem fut prise,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'qu’en la neuvième année de Sédécias, roi de Juda, au dixième mois, Nebucadretsar, roi de Babylone, vint, et toute son armée, contre Jérusalem, et ils l’assiégèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'En la onzième année de Sédécias, au quatrième mois, le neuvième [jour] du mois, la brèche fut faite à la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Et tous les princes du roi de Babylone entrèrent, et s’assirent dans la porte intérieure: Nergal-Sharétser, Samgar-Nebu, Sarsekim, chef des eunuques, Nergal-Sharétser, chef des mages, et tout le reste des princes du roi de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Et il arriva que, quand Sédécias, roi de Juda, et tous les hommes de guerre les eurent vus, ils s’enfuirent, et sortirent de nuit de la ville, par le chemin du jardin du roi, par la porte qui était entre les deux murailles; et il sortit par le chemin de la plaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Et l’armée des Chaldéens les poursuivit, et ils atteignirent Sédécias dans les plaines de Jéricho, et ils le prirent, et le firent monter vers Nebucadnetsar, roi de Babylone, à Ribla, dans le pays de Hamath; et il prononça son jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Et le roi de Babylone égorgea les fils de Sédécias, à Ribla, devant ses yeux; et le roi de Babylone égorgea tous les nobles de Juda;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'et il creva les yeux à Sédécias, et le lia avec des chaînes d’airain, pour le mener à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Et les Chaldéens brûlèrent par le feu la maison du roi et les maisons du peuple, et ils abattirent les murailles de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Et le reste du peuple qui était demeuré de reste dans la ville, et les transfuges qui étaient allés se rendre à lui, et le reste du peuple, ceux qui étaient de reste, Nebuzaradan, chef des gardes, les transporta à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Mais d’entre le peuple, Nebuzaradan, chef des gardes, laissa les pauvres, ceux qui n’avaient rien, dans le pays de Juda; et en ce jour-là il leur donna des vignes et des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Et Nebucadretsar, roi de Babylone, avait commandé par Nebuzaradan, chef des gardes, touchant Jérémie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Prends-le, et aie les yeux sur lui, et ne lui fais aucun mal; mais selon ce qu’il te dira, ainsi agis avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Et Nebuzaradan, chef des gardes, envoya, et Nebushazban, chef des eunuques, et Nergal-Sharétser, chef des mages, et tous les chefs du roi de Babylone,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'envoyèrent, et prirent Jérémie de la cour de la prison, et le remirent à Guedalia, fils d’Akhikam, fils de Shaphan, pour le mener dehors, à la maison. Et il demeura au milieu du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Et la parole de l’ Éternel vint à Jérémie, pendant qu’il était enfermé dans la cour de la prison, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Va, et tu parleras à Ébed-Mélec, l’Éthiopien, disant: Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Voici, je fais venir mes paroles sur cette ville pour le mal, et non pour le bien; et elles auront lieu devant toi, en ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Et je te délivrerai en ce jour-là, dit l’ Éternel, et tu ne seras point livré en la main des hommes dont tu as peur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'car certainement je te sauverai, et tu ne tomberas pas par l’épée; et tu auras ta vie pour butin; car tu as eu confiance en moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, '*La parole qui vint à Jérémie de par l’ Éternel, après que Nebuzaradan, chef des gardes, l’eut renvoyé de Rama, quand il l’eut pris, et qu’il était lié de chaînes au milieu de tous les captifs de Jérusalem et de Juda qu’on transportait à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Et le chef des gardes prit Jérémie, et lui dit: L’ Éternel, ton Dieu, avait prononcé ce mal sur ce lieu-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Et l’ Éternel l’a fait venir, et a fait comme il avait dit, car vous avez péché contre l’ Éternel, et vous n’avez pas écouté sa voix; et cette chose vous est arrivée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Et maintenant, voici, aujourd’hui je te délivre des chaînes qui sont à tes mains. S’il est bon à tes yeux de venir avec moi à Babylone, viens, et j’aurai les yeux sur toi; mais, s’il est mauvais à tes yeux de venir avec moi à Babylone, ne viens pas. Regarde, toute la terre est devant toi: va où il est bon et droit à tes yeux d’aller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Et comme encore il ne répondait pas, [Nebuzaradan lui dit]: Retourne-t’en vers Guedalia, fils d’Akhikam, fils de Shaphan, que le roi de Babylone a établi sur les villes de Juda, et demeure avec lui au milieu du peuple, ou va partout où il sera bon à tes yeux d’aller. Et le chef des gardes lui donna des provisions et un présent, et le renvoya.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Et Jérémie vint vers Guedalia, fils d’Akhikam, à Mitspa, et habita avec lui parmi le peuple qui était de reste dans le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Et tous les chefs des forces qui étaient dans la campagne, eux et leurs hommes, apprirent que le roi de Babylone avait établi Guedalia, fils d’Akhikam, sur le pays, et qu’il lui avait confié les hommes, et les femmes, et les enfants, et des pauvres du pays d’entre ceux qui n’avaient pas été transportés à Babylone;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'et ils vinrent vers Guedalia à Mitspa, savoir Ismaël, fils de Nethania, et Jokhanan et Jonathan, les fils de Karéakh, et Seraïa, fils de Thanhumeth, et les fils d’Éphaï, le Netophathite, et Jezania, fils d’un Maacathien, eux et leurs hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Et Guedalia, fils d’Akhikam, fils de Shaphan, leur jura, à eux et à leurs hommes, disant: Ne craignez pas de servir les Chaldéens; habitez dans le pays et servez le roi de Babylone, et vous vous en trouverez bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Et pour moi, voici, j’habite à Mitspa, pour me tenir là devant les Chaldéens qui viendront vers nous; et vous, récoltez du vin, et des fruits d’été, et de l’huile, et mettez-les dans vos vases, et habitez dans vos villes dont vous avez pris possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Et aussi tous les Juifs qui étaient en Moab, et parmi les fils d’Ammon, et en Édom, ou qui étaient dans tous les pays, entendirent que le roi de Babylone avait accordé un reste à Juda, et qu’il avait établi sur eux Guedalia, fils d’Akhikam, fils de Shaphan;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'alors tous les Juifs retournèrent de tous les lieux où ils avaient été chassés, et vinrent dans le pays de Juda, vers Guedalia, à Mitspa, et récoltèrent du vin et des fruits d’été en grande abondance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Mais Jokhanan, fils de Karéakh, et tous les chefs des forces qui étaient dans la campagne, vinrent vers Guedalia, à Mitspa,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'et lui dirent: Sais-tu bien que Baalis, roi des fils d’Ammon, a envoyé Ismaël, fils de Nethania, pour te frapper à mort? Mais Guedalia, fils d’Akhikam, ne les crut point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Et Jokhanan, fils de Karéakh, parla en secret à Guedalia, à Mitspa, disant: Que j’aille, je te prie, et je frapperai Ismaël, fils de Nethania, et personne ne le saura; pourquoi te frapperait-il à mort, et tous ceux de Juda qui se sont rassemblés vers toi seraient-ils dispersés, et le reste de Juda périrait-il?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Et Guedalia, fils d’Akhikam, dit à Jokhanan, fils de Karéakh: Ne fais pas cette chose-là, car c’est un mensonge que tu dis à l’égard d’Ismaël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Et il arriva, au septième mois, qu’Ismaël, fils de Nethania, fils d’Élishama, de la semence royale et [l’un] d’entre les grands du roi, et dix hommes avec lui, vinrent vers Guedalia, fils d’Akhikam, à Mitspa; et ils mangèrent là du pain ensemble à Mitspa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Et Ismaël, fils de Nethania, se leva, et les dix hommes qui étaient avec lui, et ils frappèrent avec l’épée Guedalia, fils d’Akhikam, fils de Shaphan: et il le fit mourir, lui que le roi de Babylone avait établi sur le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Et Ismaël frappa tous les Juifs qui étaient avec Guedalia à Mitspa, et les Chaldéens qui se trouvaient là, les hommes de guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Et il arriva, le second jour après qu’on eut fait mourir Guedalia, et personne ne le savait,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'que des hommes vinrent de Sichem, de Silo et de Samarie, 80 hommes, la barbe rasée et les vêtements déchirés, et qui s’étaient fait des incisions, et avaient dans leur main une offrande et de l’encens, pour les porter dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Et Ismaël, fils de Nethania, sortit de Mitspa à leur rencontre, s’en allant et pleurant; et il arriva que, lorsqu’il les eut atteints, il leur dit: Venez vers Guedalia, fils d’Akhikam!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Et il arriva que, quand ils furent entrés jusqu’au milieu de la ville, Ismaël, fils de Nethania (lui et les hommes qui étaient avec lui), les égorgea [et les jeta] au milieu d’une fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Et il se trouva parmi eux dix hommes qui dirent à Ismaël: Ne nous fais pas mourir, car nous avons des choses cachées dans la campagne, du froment, et de l’orge, et de l’huile, et du miel. Et il s’abstint, et ne les fit pas mourir parmi leurs frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Et la fosse où Ismaël jeta tous les cadavres des hommes qu’il tua à côté de Guedalia est celle que le roi Asa avait faite à cause de Baësha, roi d’Israël; c’est celle-là qu’Ismaël, fils de Nethania, remplit de gens tués.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Et Ismaël emmena captif tout le reste du peuple qui était à Mitspa, les filles du roi, et tous ceux du peuple qui étaient demeurés de reste à Mitspa, que Nebuzaradan, chef des gardes, avait confiés à Guedalia, fils d’Akhikam: Ismaël, fils de Nethania, les emmena captifs, et s’en alla pour passer vers les fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Et Jokhanan, fils de Karéakh, et tous les chefs des forces qui étaient avec lui, apprirent tout le mal qu’Ismaël, fils de Nethania, avait fait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'et ils prirent tous leurs hommes et s’en allèrent pour combattre contre Ismaël, fils de Nethania; et ils le trouvèrent près des grandes eaux qui sont à Gabaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Et il arriva que, lorsque tout le peuple qui était avec Ismaël vit Jokhanan, fils de Karéakh, et tous les chefs des forces qui étaient avec lui, ils se réjouirent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'et tout le peuple qu’Ismaël avait emmené captif de Mitspa fit volte-face, et s’en retourna, et s’en alla vers Jokhanan, fils de Karéakh.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Et Ismaël, fils de Nethania, échappa avec huit hommes, de devant Jokhanan, et s’en alla vers les fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Et Jokhanan, fils de Karéakh, et tous les chefs des forces qui étaient avec lui, prirent tout le reste du peuple qu’ils avaient ramené d’avec Ismaël, fils de Nethania, venant de Mitspa, après qu’il eut frappé Guedalia, fils d’Akhikam: les vaillants hommes de guerre, et les femmes, et les petits enfants, et les eunuques, qu’ils avaient ramenés de Gabaon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'et ils s’en allèrent, et habitèrent à l’hôtellerie de Kimham, qui est près de Bethléhem, pour se retirer en Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'à cause des Chaldéens; car ils les craignaient, parce qu’Ismaël, fils de Nethania, avait frappé Guedalia, fils d’Akhikam, que le roi de Babylone avait établi sur le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Et tous les chefs des forces, et Jokhanan, fils de Karéakh, et Jezania, fils de Hoshahia, et tout le peuple, depuis le petit jusqu’au grand, s’approchèrent');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'et dirent à Jérémie le prophète: Que notre supplication soit reçue devant toi, et prie l’ Éternel, ton Dieu, pour nous, pour tout ce reste; car, de beaucoup [que nous étions], nous sommes restés peu, selon que tes yeux nous voient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'et que l’ Éternel, ton Dieu, nous montre le chemin par lequel nous devons marcher, et ce que nous devons faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Et Jérémie le prophète, leur dit: J’ai entendu; voici, je prierai l’ Éternel, votre Dieu, selon vos paroles; et il arrivera que, tout ce que l’ Éternel vous répondra, je vous le déclarerai: je ne vous cacherai rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Et ils dirent à Jérémie: L’ Éternel soit entre nous un témoin véritable et fidèle, si nous ne faisons selon toute la parole pour laquelle l’ Éternel, ton Dieu, t’enverra vers nous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Soit bien, soit mal, nous écouterons la voix de l’ Éternel notre Dieu, vers qui nous t’envoyons, afin qu’il nous arrive du bien, quand nous écouterons la voix de l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Et il arriva, au bout de dix jours, que la parole de l’ Éternel vint à Jérémie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Et il appela Jokhanan, fils de Karéakh, et tous les chefs des forces qui étaient avec lui, et tout le peuple, depuis le petit jusqu’au grand,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'et leur dit: Ainsi dit l’ Éternel, le Dieu d’Israël, vers qui vous m’avez envoyé pour présenter votre supplication devant lui:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Si vous continuez à habiter dans ce pays, je vous bâtirai, et je ne vous renverserai pas, et je vous planterai, et je ne vous arracherai pas; car je me repens du mal que je vous ai fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Ne craignez point le roi de Babylone, dont vous avez peur; ne le craignez pas, dit l’ Éternel; car je suis avec vous pour vous sauver et pour vous délivrer de sa main;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'et j’userai de miséricorde envers vous, et il aura pitié de vous, et vous fera retourner dans votre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Mais si vous dites: Nous n’habiterons pas dans ce pays, et que vous n’écoutiez pas la voix de l’ Éternel, votre Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'disant: Non, mais nous irons dans le pays d’Égypte, où nous ne verrons pas la guerre, et où nous n’entendrons pas le son de la trompette, et où nous n’aurons pas disette de pain; et nous habiterons là;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'et maintenant, à cause de cela, écoutez la parole de l’ Éternel, vous, le reste de Juda: Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Si vous tournez vos faces pour aller en Égypte, et que vous y alliez pour y demeurer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'il arrivera que l’épée dont vous avez peur vous atteindra là, dans le pays d’Égypte, et la famine que vous craignez vous suivra de près, là, en Égypte, et vous y mourrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Et il arrivera que tous les hommes qui auront tourné leur face pour aller en Égypte afin d’y séjourner, mourront par l’épée, par la famine, et par la peste; et il n’y aura pour eux ni reste ni réchappé de devant le mal que je fais venir sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Car ainsi dit l’ Éternel des armées, le Dieu d’Israël: Comme ma colère et ma fureur ont été versées sur les habitants de Jérusalem, ainsi ma fureur sera versée sur vous si vous allez en Égypte; et vous serez une exécration, et une désolation, et une malédiction, et un opprobre; et vous ne verrez plus ce lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'L’ Éternel vous a dit, reste de Juda: N’allez pas en Égypte. Sachez certainement que je vous ai avertis aujourd’hui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'car vous vous êtes séduits vous-mêmes dans vos âmes quand vous m’avez envoyé vers l’ Éternel, votre Dieu, disant: Prie l’ Éternel, notre Dieu, pour nous, et selon tout ce que l’ Éternel, notre Dieu, dira, ainsi déclare-nous, et nous le ferons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Et je vous l’ai déclaré aujourd’hui; et vous n’avez pas écouté la voix de l’ Éternel, votre Dieu, ni tout ce avec quoi il m’a envoyé vers vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Et maintenant, sachez certainement que vous mourrez par l’épée, par la famine, et par la peste, dans le lieu où vous avez désiré d’aller pour y séjourner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Et lorsque Jérémie eut achevé de dire à tout le peuple toutes les paroles de l’ Éternel, leur Dieu, toutes ces paroles avec lesquelles l’ Éternel, leur Dieu, l’avait envoyé vers eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'il arriva qu’Azaria, fils de Hoshahia, et Jokhanan, fils de Karéakh, et tous les hommes orgueilleux, parlèrent à Jérémie, disant: C’est un mensonge que tu dis; l’ Éternel, notre Dieu, ne t’a pas envoyé pour [nous] dire: N’allez point en Égypte pour y séjourner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Mais Baruc, fils de Nérija, t’incite contre nous, afin de nous livrer en la main des Chaldéens, pour nous faire mourir et pour nous transporter à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Et Jokhanan, fils de Karéakh, et tous les chefs des forces, et tout le peuple, n’écoutèrent point la voix de l’ Éternel, pour habiter dans le pays de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Et Jokhanan, fils de Karéakh, et tous les chefs des forces, prirent tout le reste de Juda, ceux qui, de toutes les nations parmi lesquelles ils avaient été chassés, étaient retournés pour séjourner dans le pays de Juda:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'les hommes forts, et les femmes, et les petits enfants, et les filles du roi, et toutes les âmes que Nebuzaradan, chef des gardes, avait laissées avec Guedalia, fils d’Akhikam, fils de Shaphan, et Jérémie le prophète, et Baruc, fils de Nérija;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'et ils entrèrent dans le pays d’Égypte, car ils n’avaient pas écouté la voix de l’ Éternel; et ils vinrent jusqu’à Takhpanès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Et la parole de l’ Éternel vint à Jérémie, à Takhpanès, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Prends dans ta main de grosses pierres, et cache-les dans l’argile, dans le four à briques qui est à l’entrée de la maison du Pharaon, à Takhpanès, sous les yeux des Juifs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'et dis-leur: Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Voici, j’envoie, et je prendrai Nebucadretsar, roi de Babylone, mon serviteur; et je mettrai son trône au-dessus de ces pierres que j’ai cachées, et il étendra sur elles sa tente magnifique;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'et il viendra, et frappera le pays d’Égypte: qui pour la mort, à la mort, et qui pour la captivité, à la captivité, et qui pour l’épée, à l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Et j’allumerai un feu dans les maisons des dieux d’Égypte, et [Nebucadretsar] les brûlera, et les emmènera captifs; et il se revêtira du pays d’Égypte comme un berger se revêt de son vêtement, et il en sortira en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Et il brisera les stèles de Beth-Shémesh, qui est dans le pays d’Égypte, et brûlera par le feu les maisons des dieux de l’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, '*La parole qui vint à Jérémie pour tous les Juifs qui habitaient dans le pays d’Égypte, qui habitaient à Migdol, et à Takhpanès, et à Noph, et dans le pays de Pathros, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Vous avez vu tout le mal que j’ai fait venir sur Jérusalem et sur toutes les villes de Juda; et voici, elles sont aujourd’hui un désert, et personne n’y habite,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'à cause de l’iniquité qu’ils ont commise pour me provoquer à colère, en allant brûler de l’encens pour servir d’autres dieux, qu’ils n’ont pas connus, eux, ni vous, ni vos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Et je vous ai envoyé tous mes serviteurs les prophètes, me levant de bonne heure et [les] envoyant, disant: Ne faites point cette chose abominable que je hais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Et ils n’ont pas écouté, et n’ont pas incliné leur oreille pour se détourner de leur iniquité, afin de ne pas brûler de l’encens à d’autres dieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'alors ma fureur et ma colère ont été versées [sur eux], et ont brûlé dans les villes de Juda et dans les rues de Jérusalem; et elles sont devenues un désert, une désolation, comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Et maintenant, ainsi dit l’ Éternel, le Dieu des armées, le Dieu d’Israël: Pourquoi faites-vous un grand mal contre vos âmes, pour vous faire retrancher du milieu de Juda, homme et femme, enfant et celui qui tète, en sorte qu’il ne vous demeure aucun reste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'en me provoquant par les œuvres de vos mains, en brûlant de l’encens à d’autres dieux dans le pays d’Égypte où vous êtes venus pour y séjourner, en sorte que vous soyez retranchés, et que vous deveniez une malédiction et un opprobre parmi toutes les nations de la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Avez-vous oublié les iniquités de vos pères, et les iniquités des rois de Juda, et les iniquités de leurs femmes, et vos iniquités, et les iniquités de vos femmes, commises dans le pays de Juda et dans les rues de Jérusalem?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Ils ne se sont pas humiliés jusqu’à ce jour, et ils n’ont pas eu de crainte, et ils n’ont pas marché dans ma loi et dans mes statuts, que j’ai mis devant vous et devant vos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'C’est pourquoi, ainsi dit l’ Éternel des armées, le Dieu d’Israël: Voici, je mets ma face contre vous pour le mal, et pour retrancher tout Juda!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Et je prendrai le reste de Juda qui a tourné sa face pour aller dans le pays d’Égypte pour y séjourner; et ils seront tous consumés; ils tomberont dans le pays d’Égypte; ils seront consumés par l’épée [et] par la famine, depuis le petit jusqu’au grand; ils mourront par l’épée et par la famine, et ils seront une exécration, une désolation, et une malédiction, et un opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Et je punirai ceux qui habitent dans le pays d’Égypte, comme j’ai puni Jérusalem par l’épée, par la famine, et par la peste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'et, du reste de Juda qui est venu dans le pays d’Égypte pour y séjourner, il n’y aura ni réchappé ni résidu pour retourner dans le pays de Juda, où ils avaient le désir de retourner pour y habiter; car ils ne retourneront pas, sauf [quelques] réchappés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Et tous les hommes qui savaient que leurs femmes brûlaient de l’encens à d’autres dieux, et toutes les femmes qui se tenaient là, un grand rassemblement, et tout le peuple qui demeurait dans le pays d’Égypte, à Pathros, répondirent à Jérémie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Quant à la parole que tu nous as dite au nom de l’ Éternel, nous ne t’écouterons pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'mais nous ferons certainement toute parole qui est sortie de notre bouche, en brûlant de l’encens à la reine des cieux, et en lui faisant des libations, comme nous avons fait, nous et nos pères, nos rois et nos princes, dans les villes de Juda, et dans les rues de Jérusalem; et nous étions rassasiés de pain, et nous étions à notre aise, et nous ne voyions pas de malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Mais depuis que nous avons cessé de brûler de l’encens à la reine des cieux et de lui faire des libations, nous manquons de tout, et nous sommes consumés par l’épée et par la famine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Et si nous avons brûlé de l’encens à la reine des cieux, et si nous lui avons fait des libations, est-ce sans nos maris que nous lui avons fait des gâteaux à son image, ou que nous lui avons fait des libations?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Et Jérémie parla à tout le peuple, aux hommes et aux femmes, et à tout le peuple qui lui avait répondu [cette] parole, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Ne sont-ce pas ces encensements que vous avez faits dans les villes de Juda et dans les rues de Jérusalem, vous et vos pères, vos rois et vos princes et le peuple du pays, que l’ Éternel s’est rappelés, et qui lui sont montés au cœur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Et l’ Éternel ne put plus le supporter, à cause de l’iniquité de vos actions, [et] à cause des choses abominables que vous avez faites, et votre pays est devenu un désert, et une désolation, et une malédiction, de sorte qu’il n’y a pas d’habitant, comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Parce que vous avez brûlé de l’encens, et que vous avez péché contre l’ Éternel, et que vous n’avez pas écouté la voix de l’ Éternel, et n’avez point marché dans sa loi, ni dans ses statuts, ni dans ses témoignages, à cause de cela ce mal vous est arrivé, comme [il paraît] aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Et Jérémie dit à tout le peuple et à toutes les femmes: Écoutez la parole de l’ Éternel, vous, tout Juda, qui êtes dans le pays d’Égypte:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Ainsi parle l’ Éternel des armées, le Dieu d’Israël, disant: Vous et vos femmes, vous avez parlé de votre bouche, et vous avez accompli de vos mains, disant: Certainement nous accomplirons nos vœux que nous avons voués, pour brûler de l’encens à la reine des cieux et lui faire des libations. Vous ferez certainement selon vos vœux, et vous accomplirez certainement vos vœux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'C’est pourquoi, écoutez la parole de l’ Éternel, vous, tout Juda, qui habitez dans le pays d’Égypte: Voici, j’ai juré par mon grand nom, dit l’ Éternel, que mon nom ne sera plus réclamé par la bouche d’aucun homme de Juda, dans tout le pays d’Égypte, disant: Le Seigneur, l’ Éternel, est vivant!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Voici, je veille sur eux pour le mal, et non pour le bien; et ils seront consumés, chaque homme de Juda qui est dans le pays d’Égypte, par l’épée et par la famine, jusqu’à ce qu’il n’y en ait plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Et ceux qui échapperont à l’épée retourneront du pays d’Égypte dans le pays de Juda, un fort petit nombre; et ils sauront, tout ce reste de Juda, ceux qui sont venus dans le pays d’Égypte pour y séjourner, de qui, de moi ou d’eux, la parole s’accomplira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Et ceci sera pour vous le signe, dit l’ Éternel, que je vous punirai dans ce lieu, afin que vous sachiez que mes paroles s’effectueront certainement contre vous en mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Ainsi dit l’ Éternel: Voici, je livre le Pharaon Hophra, roi d’Égypte, en la main de ses ennemis et en la main de ceux qui cherchent sa vie, comme j’ai livré Sédécias, roi de Juda, en la main de Nebucadretsar, roi de Babylone, son ennemi, celui qui cherchait sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, '*La parole que Jérémie le prophète dit à Baruc, fils de Nérija, lorsqu’il écrivait ces paroles-là dans un livre, sous la dictée de Jérémie, en la quatrième année de Jehoïakim, fils de Josias, roi de Juda, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Ainsi dit l’ Éternel, le Dieu d’Israël, à ton sujet, Baruc:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Tu as dit: Malheur à moi! car l’ Éternel a ajouté le chagrin à ma douleur; je me suis fatigué dans mon gémissement, et je n’ai pas trouvé de repos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Tu lui diras ainsi: Ainsi dit l’ Éternel: Voici, ce que j’avais bâti, je le renverse, et ce que j’avais planté, je l’arrache, – tout ce pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Et toi, tu chercherais pour toi de grandes choses? Ne les cherche pas; car voici, je fais venir du mal sur toute chair, dit l’ Éternel; mais je te donnerai ta vie pour butin, dans tous les lieux où tu iras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, '***La parole de l’ Éternel, qui vint à Jérémie le prophète, touchant les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Sur l’Égypte. Touchant l’armée du Pharaon Neco, roi d’Égypte, qui était près du fleuve Euphrate, à Carkemish, laquelle Nebucadretsar, roi de Babylone, battit en la quatrième année de Jehoïakim, fils de Josias, roi de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Préparez l’écu et le bouclier, et approchez-vous du combat!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Attelez les chevaux, et montez, vous, cavaliers, et présentez-vous en casques! Fourbissez les piques, revêtez les cottes de mailles!...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Pourquoi les vois-je terrifiés, se retirant en arrière, et [pourquoi] leurs hommes forts sont-ils battus et fuient-ils sans se retourner? L’épouvante de tous côtés, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Que l’homme léger à la course ne fuie pas, et que le fort n’échappe pas! Au nord, près du fleuve Euphrate, ils ont bronché et sont tombés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Qui est celui-ci qui monte comme le Nil, [et] dont les eaux s’agitent comme les fleuves?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'C’est l’Égypte qui monte comme le Nil, et, comme les fleuves, ses eaux s’agitent. Et elle dit: Je monterai, je couvrirai le pays, je détruirai la ville et ceux qui y habitent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Montez, chevaux! et précipitez-vous, chars! et que les hommes forts sortent, Cush et Puth, qui manient le bouclier, et ceux de Lud, qui manient [et] bandent l’arc!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'car ce jour est [le jour] du Seigneur, l’ Éternel des armées, un jour de vengeance, pour se venger de ses ennemis. Et l’épée dévorera, et elle sera rassasiée et abondamment abreuvée de leur sang; car il y a un sacrifice au Seigneur, l’ Éternel des armées, dans le pays du nord, près du fleuve Euphrate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Monte à Galaad, et prends du baume, vierge, fille de l’Égypte! En vain tu multiplies les remèdes, il n’y a point de guérison pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Les nations ont entendu ta confusion, et ton cri a rempli la terre; car l’homme fort a trébuché sur l’homme fort, ils sont tombés tous deux ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'La parole que l’ Éternel dit à Jérémie le prophète, touchant la venue de Nebucadretsar, roi de Babylone, pour frapper le pays d’Égypte:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Annoncez en Égypte, et faites entendre à Migdol, et faites entendre à Noph et à Takhpanès; dites: Tiens ferme et prépare-toi, car l’épée dévore tout autour de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Pourquoi tes hommes forts ont-ils été emportés? Ils n’ont pas tenu ferme, car l’ Éternel les a renversés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Il multiplie ceux qui bronchent; même un homme est tombé sur son compagnon, et ils ont dit: Lève-toi, retournons vers notre peuple et au pays de notre naissance, de devant l’épée qui ravage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Ils ont crié là: Le Pharaon, roi d’Égypte, n’est qu’un bruit; il a laissé passer le temps!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Je suis vivant, dit le Roi, l’ Éternel des armées est son nom: Comme le Thabor entre les montagnes, et comme le Carmel sur la mer, ainsi il viendra!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Fais-toi un bagage de transporté, habitante, fille de l’Égypte, car Noph sera une désolation et sera dévastée, de sorte qu’il n’y aura pas d’habitant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'L’Égypte est une très belle génisse: le taon vient, il vient du nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Et ses mercenaires au milieu d’elle sont comme des veaux à l’engrais; car eux aussi ont tourné le dos, ils se sont enfuis ensemble, ils n’ont pas tenu ferme; car le jour de leur calamité, le temps de leur visitation, est venu sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Sa voix sera comme celle du serpent; car ils viendront en force, et ils viendront contre elle avec des haches, comme ceux qui coupent les arbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Ils couperont sa forêt, dit l’ Éternel, quoiqu’elle soit inexplorable, car ils sont plus nombreux que les sauterelles, et on ne peut les compter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Elle est honteuse, la fille de l’Égypte, elle est livrée en la main du peuple du nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'L’ Éternel des armées, le Dieu d’Israël, dit: Voici, je vais punir l’Amon de No, et le Pharaon, et l’Égypte, et ses dieux, et ses rois, le Pharaon et ceux qui se confient en lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'et je les livrerai en la main de ceux qui cherchent leur vie, et en la main de Nebucadretsar, roi de Babylone, et en la main de ses serviteurs; et après cela elle sera habitée comme aux jours d’autrefois, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Et toi, mon serviteur Jacob, ne crains point, et ne t’effraie pas, Israël! car voici, je te sauve d’un [pays] lointain, et ta semence, du pays de leur captivité, et Jacob reviendra et sera tranquille et en repos, et il n’y aura personne qui l’effraie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Toi, mon serviteur Jacob, ne crains point, dit l’ Éternel, car je suis avec toi; car je détruirai entièrement toutes les nations où je t’ai chassé, mais je ne te détruirai pas entièrement, et je te corrigerai avec mesure, et je ne te tiendrai point pour innocent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'La parole de l’ Éternel qui vint à Jérémie le prophète, contre les Philistins, avant que le Pharaon frappe Gaza.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Ainsi dit l’ Éternel: Voici des eaux qui montent du nord, et elles sont comme un torrent qui déborde; et elles déborderont sur le pays et tout ce qu’il contient, sur la ville et ceux qui y habitent. Et les hommes crieront, et tous les habitants du pays hurleront,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'au bruit retentissant des sabots de ses puissants [chevaux], au fracas de ses chars, au bruit tumultueux de ses roues. Les pères ne se retourneront pas vers leurs fils, à cause de la faiblesse de leurs mains,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'à cause du jour qui vient pour dévaster tous les Philistins, pour retrancher à Tyr et à Sidon quiconque resterait pour les secourir; car l’ Éternel dévaste les Philistins, le reste de l’île de Caphtor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Gaza est devenue chauve, Askalon est détruite [avec] le reste de leur plaine... Jusques à quand te feras-tu des incisions?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Ah! épée de l’ Éternel! jusques à quand ne te tiendras-tu pas tranquille? Rentre dans ton fourreau, donne-toi du repos, et tiens-toi tranquille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Comment te tiendrais-tu tranquille? Car l’ Éternel lui a donné un commandement. Contre Askalon, et contre le rivage de la mer, – là, il l’a assignée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Sur Moab. Ainsi dit l’ Éternel des armées, le Dieu d’Israël: Malheur à Nebo! car elle est dévastée. Kiriathaïm est honteuse, elle est prise. Misgab est honteuse et terrifiée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'C’en est fait de la louange de Moab. À Hesbon, ils ont machiné contre lui du mal: Venez, et retranchons-le, qu’il ne soit plus une nation! Toi aussi, Madmen, tu seras détruite; l’épée ira après toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'La voix d’un cri [qui vient] de Horonaïm! Dévastation et grande ruine!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moab est ruiné, ses petits enfants ont fait entendre un cri;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'car de la montée de Lukhith montent pleurs sur pleurs; car à la descente de Horonaïm on a entendu un cri d’angoisse de ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Fuyez, sauvez vos vies; et vous serez comme la bruyère dans le désert!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Car, parce que tu as eu confiance en tes ouvrages et en tes trésors, toi aussi tu seras pris; et Kemosh s’en ira en captivité, ses sacrificateurs et ses princes ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Et le dévastateur viendra contre chaque ville, et pas une ville n’échappera; et la vallée périra, et le plateau sera dévasté, comme l’ Éternel l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Donnez des ailes à Moab! car il partira au vol, et ses villes seront désolées, sans qu’il y ait personne qui y habite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Maudit celui qui fera l’œuvre de l’ Éternel frauduleusement! Maudit celui qui retiendra son épée loin du sang!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Moab a été à son aise dès sa jeunesse, et tranquille sur sa lie; il n’a pas été versé de vase en vase, et il n’est pas allé en captivité: c’est pourquoi son goût lui est demeuré, et son parfum ne s’est point changé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'C’est pourquoi, voici, des jours viennent, dit l’ Éternel, où je lui enverrai des transvaseurs qui le transvaseront, et qui videront ses vases, et qui briseront ses cruches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Et Moab sera honteux de Kemosh, comme la maison d’Israël a été honteuse de Béthel, sa confiance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Comment dites-vous: Nous sommes des hommes forts, des hommes vaillants pour la guerre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Moab est dévasté, et ses villes montent [en fumée], et l’élite de ses jeunes gens descend à la tuerie, dit le Roi; l’ Éternel des armées est son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'La calamité de Moab est près d’arriver, et son malheur se hâte beaucoup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Lamentez-vous sur lui, vous tous qui êtes autour de lui; et vous tous qui connaissez son nom, dites: Comment a été brisée la verge de force, le bâton de magnificence!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Descends de la gloire, et assieds-toi dans la soif, habitante, fille de Dibon! car le dévastateur de Moab est monté contre toi, il a détruit tes forteresses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Tiens-toi sur le chemin, et veille, habitante d’Aroër; interroge celui qui fuit et celle qui est échappée; dis: Qu’est-il arrivé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moab est honteux, car il est brisé. Hurlez et criez, annoncez dans Arnon que Moab est dévasté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Et le jugement est venu sur le pays du plateau, sur Holon, et sur Jahtsa, et sur Méphaath,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'et sur Dibon, et sur Nebo, et sur Beth-Diblathaïm,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'et sur Kiriathaïm, et sur Beth-Gamul, et sur Beth-Méon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'et sur Kerijoth, et sur Botsra, et sur toutes les villes du pays de Moab, éloignées et proches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'La corne de Moab est coupée, et son bras est cassé, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Enivrez-le, car il s’est exalté contre l’ Éternel; et Moab se roulera dans son vomissement, et il sera, lui aussi, un objet de dérision.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Et Israël n’a-t-il pas été un objet de dérision pour toi? A-t-il été pris parmi les voleurs? Car chaque fois que tu as parlé de lui, tu as secoué [la tête].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Abandonnez les villes, et demeurez dans les rochers, habitants de Moab, et soyez comme une colombe qui fait son nid aux côtés de l’entrée d’une caverne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Nous avons entendu l’orgueil de Moab, le très hautain, son arrogance, et son orgueil, et sa fierté, et son cœur altier!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Je connais, dit l’ Éternel, sa rage: ses vanteries ne sont que vanité, ils ne font pas ce [qu’ils disent].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'C’est pourquoi je hurlerai sur Moab; au sujet de tout Moab je crierai; on gémira sur les hommes de Kir-Hérès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Plus que des pleurs de Jahzer, je pleurerai sur toi, ô vigne de Sibma; tes sarments ont passé au-delà de la mer, ils ont atteint jusqu’à la mer de Jahzer; le dévastateur est tombé sur tes fruits d’été et sur ta vendange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Et la joie et l’allégresse ont disparu des champs fertiles, et du pays de Moab, et j’ai fait cesser le vin des cuves: on ne foulera plus avec des cris de joie, le cri de joie ne sera plus un cri de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'À cause du cri de Hesbon, ils ont fait retentir leurs voix jusqu’à Elhalé, jusqu’à Jahats, de Tsoar jusqu’à Horonaïm, [jusqu’à] Églath-Shelishija; car aussi les eaux de Nimrim sont devenues des désolations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Et je ferai cesser en Moab, dit l’ Éternel, celui qui offre sur le haut lieu et qui brûle de l’encens à ses dieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'C’est pourquoi mon cœur bruira sur Moab comme des flûtes, et mon cœur bruira comme des flûtes sur les hommes de Kir-Hérès, parce que les biens qu’ils avaient acquis ont péri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Car toute tête sera chauve, et toute barbe sera coupée; sur toutes les mains il y aura des incisions, et le sac sera sur les reins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'sur tous les toits de Moab et dans ses places, tout est lamentation, car j’ai brisé Moab comme un vase auquel on ne prend pas plaisir, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Ils hurleront: Comment a-t-il été brisé! Comment Moab a-t-il tourné le dos, [tout] honteux! Et Moab sera un objet de dérision et d’effroi à tous ceux qui l’entourent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Car ainsi dit l’ Éternel: Voici, il volera comme un aigle, et il étendra ses ailes sur Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kerijoth est prise et on s’est emparé des lieux forts; et le cœur des hommes forts de Moab sera en ce jour-là comme le cœur d’une femme en travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Et Moab sera détruit de manière à n’être plus un peuple, car il s’est exalté contre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'La frayeur, et la fosse, et le piège sont sur toi, habitant de Moab! dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Celui qui s’ enfuit à cause de la frayeur tombera dans la fosse; et celui qui monte de la fosse sera pris dans le piège; car je ferai venir sur lui, sur Moab, l’année de leur visitation, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'À l’ombre de Hesbon se sont tenus ceux qui fuyaient devant la force; car un feu est sorti de Hesbon, et une flamme du milieu de Sihon, et elle a dévoré le coin de Moab et le sommet de la tête des fils du tumulte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Malheur à toi, Moab! le peuple de Kemosh est perdu; car tes fils ont été pris captifs, et tes filles, captives.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Et je rétablirai les captifs de Moab à la fin des jours, dit l’ Éternel. Jusqu’ici est le jugement de Moab.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Sur les fils d’Ammon. Ainsi dit l’ Éternel: Israël n’a-t-il point de fils? n’a-t-il point d’héritier? Pourquoi leur roi a-t-il hérité de Gad, et son peuple demeure-t-il dans ses villes? –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'C’est pourquoi, voici, des jours viennent, dit l’ Éternel, et je ferai entendre dans Rabba des fils d’Ammon la clameur de la guerre, et elle sera un monceau de ruines, et ses villes seront brûlées par le feu, et Israël aura en héritage ceux qui étaient ses héritiers, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Hurle, Hesbon! car Aï est dévastée. Criez, filles de Rabba, ceignez-vous de sacs, lamentez-vous, et courez çà et là entre les clôtures, car leur roi ira en captivité, ses sacrificateurs et ses princes ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Pourquoi te glorifies-tu des vallées? Ta vallée ruissellera, fille infidèle, qui te confies en tes trésors, [disant]: Qui viendra contre moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Voici, je fais venir, de tous tes alentours, la frayeur contre toi, dit le Seigneur, l’ Éternel des armées; et vous serez chassés chacun devant soi, et il n’y aura personne qui rassemble les fugitifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Et après cela, je rétablirai les captifs des fils d’Ammon, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Sur Édom. Ainsi dit l’ Éternel des armées: N’y a-t-il plus de sagesse dans Théman? Le conseil des intelligents a-t-il péri? leur sagesse est-elle perdue?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fuyez, tournez le dos, habitez dans les lieux profonds, vous, habitants de Dedan, car je ferai venir sur Ésaü sa calamité, le temps où je le visiterai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Si des vendangeurs venaient chez toi, ne laisseraient-ils pas des grappillages? si c’étaient des voleurs de nuit, ils ne détruiraient que ce qui leur suffirait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Mais moi, j’ai dépouillé Ésaü, j’ai découvert ses lieux secrets; il ne peut se cacher. Sa semence est dévastée, et ses frères et ses voisins, et il n’est plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Laisse tes orphelins, moi je les garderai en vie, et que tes veuves se confient en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Car ainsi dit l’ Éternel: Voici, ceux dont le jugement n’était pas de boire la coupe, la boiront certainement; et toi tu resterais entièrement impuni? Tu ne resteras pas impuni, mais tu la boiras certainement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Car j’ai juré par moi-même, dit l’ Éternel, que Botsra sera une désolation, un opprobre, un désert, et une malédiction, et que toutes ses villes seront des déserts perpétuels.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'J’ai entendu une rumeur de par l’ Éternel, et un ambassadeur a été envoyé parmi les nations: Assemblez-vous, et venez contre lui, et levez-vous pour la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Car voici, je t’ai fait petit parmi les nations, méprisé parmi les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Ta fierté, l’arrogance de ton cœur, t’a séduit, toi qui demeures dans les creux du rocher, [et] qui t’es emparé du haut de la colline. Quand tu élèverais ton nid comme l’aigle, je te ferai descendre de là, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Et Édom sera une désolation; quiconque passera près de lui, sera étonné et sifflera à cause de toutes ses plaies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Comme dans la subversion de Sodome et de Gomorrhe et des villes voisines, dit l’ Éternel, personne n’y habitera et aucun fils d’homme n’y séjournera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Voici, comme un lion, il monte de la crue du Jourdain contre la demeure forte; car je les en chasserai précipitamment. Et qui est l’homme choisi, que je préposerai sur lui? Car qui est comme moi, et qui m’assignera le temps, et qui sera le pasteur qui se tiendra devant moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'C’est pourquoi, écoutez le conseil de l’ Éternel, qu’il a formé contre Édom, et les pensées qu’il a pensées contre les habitants de Théman: Si les petits du troupeau ne les entraînent! S’il ne rend désolée pour eux leur habitation!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Au bruit de leur chute la terre tremble; il y a un cri! le bruit en est entendu à la mer Rouge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Voici, il monte comme un aigle, et il vole, et il étend ses ailes sur Botsra; et le cœur des hommes forts d’Édom sera en ce jour-là comme le cœur d’une femme en travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Sur Damas. Hamath et Arpad sont honteuses, car elles ont entendu un bruit de malheur; elles défaillent; il y a une tourmente dans la mer, elle ne peut rester tranquille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damas est devenue lâche, elle se tourne pour fuir, l’effroi l’a saisie; la détresse et les angoisses se sont emparées d’elle comme d’une femme qui enfante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Dans quel abandonnement n’est-elle pas, la ville de la louange, la cité de mon délice!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Aussi ses jeunes gens sont tombés dans ses places et tous ses hommes de guerre sont détruits en ce jour, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Et j’allumerai un feu dans les murs de Damas, et il dévorera les palais de Ben-Hadad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Sur Kédar et sur les royaumes de Hatsor, que Nebucadretsar, roi de Babylone, frappa. Ainsi dit l’ Éternel: Levez-vous, montez contre Kédar, et détruisez les fils de l’orient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'On prendra leurs tentes et leur menu bétail, on emmènera leurs tapis, et tous leurs bagages, et leurs chameaux; et on leur criera: La terreur de tous côtés!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Fuyez, enfuyez-vous très loin, habitez dans les lieux profonds, vous, habitants de Hatsor, dit l’ Éternel; car Nebucadretsar, roi de Babylone, a formé un dessein contre vous, et il a conçu une pensée contre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Levez-vous, montez vers la nation qui jouit de la paix, qui habite en sécurité, dit l’ Éternel; elle n’a ni portes ni barres; ils demeurent seuls.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Et leurs chameaux seront un butin, et la multitude de leurs troupeaux sera une proie; et je les disperserai à tout vent, ceux qui coupent les coins [de leur barbe], et je ferai venir de tous les côtés leur calamité, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Et Hatsor deviendra un repaire de chacals, une désolation à toujours; personne n’y habitera et aucun fils d’homme n’y séjournera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'La parole de l’ Éternel, qui vint à Jérémie le prophète, sur Élam, au commencement du règne de Sédécias, roi de Juda, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Ainsi dit l’ Éternel des armées: Voici, je briserai l’arc d’Élam, les prémices de sa force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Et je ferai venir contre Élam les quatre vents, des quatre bouts des cieux, et je les disperserai à tous ces vents; et il n’y aura point de nation où ne viennent les fugitifs d’Élam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Et je ferai trembler les Élamites devant leurs ennemis et devant ceux qui cherchent leur vie; et je ferai venir du mal sur eux, l’ardeur de ma colère, dit l’ Éternel; et j’enverrai après eux l’épée, jusqu’à ce que je les aie consumés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Et je mettrai mon trône en Élam, et j’en ferai périr le roi et les princes, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Et il arrivera, à la fin des jours, que je rétablirai les captifs d’Élam, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, '*La parole que l’ Éternel dit sur Babylone, sur le pays des Chaldéens, par Jérémie le prophète:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Annoncez parmi les nations, et faites-le entendre, et élevez l’étendard; faites-le entendre, ne le cachez pas; dites: Babylone est prise, Bel est honteux; Merodac est brisé; ses idoles sont honteuses, ses images sont brisées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Car une nation est montée du nord contre elle; elle a mis en désolation son pays, et il n’y aura plus là d’habitant: tant les hommes que les bêtes se sont enfuis, ils s’en sont allés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'En ces jours-là et en ce temps-là, dit l’ Éternel, les fils d’Israël viendront, eux et les fils de Juda ensemble; ils iront, marchant et pleurant, et ils chercheront l’ Éternel leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Ils s’enquerront de Sion; vers elle leur face [sera tournée]: Venez, attachons-nous à l’ Éternel par une alliance éternelle qui ne sera pas oubliée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Mon peuple est un troupeau perdu; leurs pasteurs les ont fait errer, les égarant sur les montagnes; ils sont allés de montagne en colline, ils ont oublié leur gîte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Tous ceux qui les ont trouvés les ont dévorés; et leurs ennemis disent: Nous ne sommes pas coupables, parce qu’ils ont péché contre l’ Éternel, contre la demeure de la justice, contre l’ Éternel, l’attente de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Fuyez du milieu de Babylone, et sortez du pays des Chaldéens, et soyez comme les boucs [qui vont] devant le troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Car voici, du pays du nord je réveillerai et je ferai monter contre Babylone un rassemblement de grandes nations qui se rangeront contre elle: de là elle sera prise. Leurs flèches sont comme celles d’un habile homme fort; pas une ne reviendra à vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Et la Chaldée sera un butin; tous ceux qui la pilleront seront rassasiés, dit l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'parce que vous vous êtes réjouis, parce que vous vous êtes égayés, vous qui avez pillé mon héritage, parce que vous avez bondi comme une génisse qui foule le blé, et que vous avez henni comme de puissants chevaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Votre mère est fort honteuse, celle qui vous enfanta est couverte d’opprobre: voici, [elle est] la dernière des nations, un désert, un pays stérile et une solitude!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'À cause du courroux de l’ Éternel elle ne sera pas habitée, elle sera tout entière une désolation; quiconque passera près de Babylone sera étonné et sifflera à cause de toutes ses plaies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Rangez-vous en bataille contre Babylone, tout alentour, vous tous qui bandez l’arc; tirez contre elle, n’épargnez pas les flèches, car elle a péché contre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Poussez des cris contre elle tout alentour! Elle s’est rendue, ses remparts sont tombés, ses murailles sont renversées, car c’est ici la vengeance de l’ Éternel. Vengez-vous sur elle, faites-lui comme elle a fait!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Retranchez de Babylone celui qui sème, et celui qui tient la faucille au temps de la moisson. À cause de l’épée qui ravage, qu’ils s’en retournent chacun vers son peuple, et qu’ils fuient chacun vers son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israël est une brebis chassée çà et là; les lions l’ont pourchassée. Le roi d’Assyrie, le premier, l’a dévorée; et celui-ci, le dernier, Nebucadretsar, roi de Babylone, lui a brisé les os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'C’est pourquoi, ainsi dit l’ Éternel des armées, le Dieu d’Israël: Voici, je visite le roi de Babylone et son pays, comme j’ai visité le roi d’Assyrie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'et je ferai revenir Israël à ses pâturages; et il paîtra sur le Carmel et en Basan, et son âme sera rassasiée dans la montagne d’Éphraïm et en Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'En ces jours-là et en ce temps-là, dit l’ Éternel, on cherchera l’iniquité d’Israël, et il n’y en aura point, et les péchés de Juda, et ils ne seront pas trouvés; car je pardonnerai à ceux que j’aurai fait demeurer de reste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Monte contre le pays doublement rebelle, contre lui et contre les habitants destinés à la visitation; dévaste et détruis entièrement derrière eux, dit l’ Éternel, et fais selon tout ce que je t’ai commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Le cri de guerre est dans le pays, et une grande ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Comment est mis en pièces et brisé le marteau de toute la terre! Comment Babylone est-elle réduite en désolation parmi les nations!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Je t’ai tendu un piège, et aussi tu es prise, Babylone! et tu ne le savais pas; tu as été trouvée, et tu as aussi été saisie, parce que tu as combattu contre l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'L’ Éternel a ouvert son trésor, et il en a fait sortir les armes de son indignation; car c’est ici l’œuvre du Seigneur, l’ Éternel des armées, dans le pays des Chaldéens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Venez contre elle de toute part; ouvrez ses granges, entassez-la comme des gerbes et détruisez-la entièrement; qu’elle n’ait rien de reste!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Tuez tous ses taureaux; qu’ils descendent à la tuerie. Malheur à eux! car leur jour est venu, le temps de leur visitation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'La voix de ceux qui fuient, qui sont réchappés du pays de Babylone, pour annoncer dans Sion la vengeance de l’ Éternel, notre Dieu, la vengeance de son temple!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Convoquez des archers contre Babylone, tous ceux qui bandent l’arc! Campez contre elle tout alentour, qu’elle n’ait pas de réchappés; rendez-lui selon son œuvre, faites-lui selon tout ce qu’elle a fait; car elle a été fière contre l’ Éternel, contre le Saint d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'C’est pourquoi ses jeunes gens tomberont dans ses places et tous ses hommes de guerre seront détruits en ce jour-là, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Voici, [j’en veux] à toi, orgueilleuse, dit le Seigneur, l’ Éternel des armées; car ton jour est venu, le temps où je te visite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Et l’orgueilleuse a bronché et est tombée, et il n’y a personne qui la relève; et j’allumerai dans ses villes un feu qui dévorera tous ses alentours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Ainsi dit l’ Éternel des armées: Les fils d’Israël et les fils de Juda ont été ensemble opprimés; et tous ceux qui les emmenèrent captifs les ont retenus, ils ont refusé de les laisser aller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Leur rédempteur est fort. Son nom est l’ Éternel des armées; il prendra certainement en main leur cause, afin de donner du repos au pays et de troubler les habitants de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'L’épée est sur les Chaldéens, dit l’ Éternel, et sur les habitants de Babylone, et sur ses princes, et sur ses sages;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'l’épée est sur les menteurs, et ils deviendront insensés; l’épée est sur ses hommes forts, et ils seront terrifiés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'l’épée est sur ses chevaux, et sur ses chars, et sur tout le peuple mélangé qui est au milieu d’elle, et ils seront comme des femmes; l’épée est sur ses trésors, et ils seront pillés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'la sécheresse est sur ses eaux, et elles tarissent; car c’est un pays d’images taillées, et ils sont fous de leurs affreuses idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'C’est pourquoi les bêtes du désert, avec des chacals, y habiteront, et il y habitera des autruches; et elle ne sera plus jamais habitée, et on n’y demeurera plus, de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Comme dans la subversion que Dieu a faite de Sodome et de Gomorrhe et des villes voisines, dit l’ Éternel, personne n’y habitera et aucun fils d’homme n’y séjournera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Voici, un peuple vient du nord, et une grande nation et beaucoup de rois se réveillent des extrémités de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Ils saisissent l’arc et le javelot; ils sont cruels, et ils n’ont pas de compassion; leur voix bruit comme la mer, et ils sont montés sur des chevaux, préparés comme un homme pour la guerre, contre toi, fille de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Le roi de Babylone en a entendu la rumeur, et ses mains sont devenues lâches; la détresse l’a saisi, l’angoisse comme celle d’une femme qui enfante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Voici, comme un lion il monte de la crue du Jourdain contre la demeure forte; car je les en chasserai précipitamment. Et qui est l’homme choisi, que je préposerai sur elle? Car qui est comme moi, et qui m’assignera le temps, et qui sera le pasteur qui se tiendra devant moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'C’est pourquoi, écoutez le conseil de l’ Éternel, qu’il a formé contre Babylone, et les pensées qu’il a pensées contre le pays des Chaldéens: Si les petits du troupeau ne les entraînent! S’il ne rend désolée pour eux [leur] habitation!...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Au bruit de la prise de Babylone la terre est ébranlée, et il y a un cri, entendu parmi les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Ainsi dit l’ Éternel: Voici, je fais lever un vent destructeur contre Babylone, et contre les [hommes] qui habitent au cœur de ceux qui s’élèvent contre moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'et j’enverrai contre Babylone des étrangers qui la vanneront et qui videront son pays; car ils seront contre elle tout alentour, au jour de [son] malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Qu’on bande son arc contre celui qui le bande et contre celui qui s’élève dans sa cotte de mailles; et n’épargnez point ses jeunes hommes, détruisez entièrement toute son armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Et les tués tomberont dans le pays des Chaldéens, et les transpercés, dans ses rues:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'car Israël et Juda ne sont point privés de leur Dieu, de l’ Éternel des armées; car leur pays est plein de péché devant le Saint d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fuyez du milieu de Babylone, et sauvez chacun sa vie! Ne soyez point détruits dans son iniquité, car c’est le temps de la vengeance de l’ Éternel: il lui rend sa récompense.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Babylone a été une coupe d’or dans la main de l’ Éternel, enivrant toute la terre. Les nations ont bu de son vin, c’est pourquoi les nations sont devenues insensées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Subitement Babylone est tombée, et elle a été brisée. Hurlez sur elle, prenez du baume pour sa douleur, peut-être qu’elle guérira!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Nous avons traité Babylone, mais elle n’est pas guérie; abandonnez-la, et allons-nous-en chacun dans son pays; car son jugement atteint aux cieux et s’est élevé jusqu’aux nues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'L’ Éternel a produit au jour notre justice. Venez, et racontons en Sion l’œuvre de l’ Éternel, notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Aiguisez les flèches, prenez les boucliers! L’ Éternel a réveillé l’esprit des rois des Mèdes, car sa pensée est contre Babylone pour la détruire, car c’est ici la vengeance de l’ Éternel, la vengeance de son temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Élevez l’étendard sur les murs de Babylone! Renforcez le guet, placez les gardes, préparez les embuscades; car comme l’ Éternel a pensé, il a aussi fait ce qu’il a dit contre les habitants de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Toi qui habites sur beaucoup d’eaux, abondante en trésors, ta fin est venue, la mesure de tes rapines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'L’ Éternel des armées a juré par lui-même, [disant]: Si je ne te remplis d’hommes comme de sauterelles, et s’ils ne poussent un cri de triomphe sur toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'C’est lui qui a fait la terre par sa puissance, qui a établi le monde par sa sagesse, et qui, par son intelligence, a étendu les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Quand il fait retentir sa voix, il y a un tumulte d’eaux dans les cieux, et il fait monter les vapeurs du bout de la terre; il fait les éclairs pour la pluie, et de ses trésors il tire le vent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Tout homme est devenu stupide, en sorte qu’il n’a pas de connaissance; tout fondeur a honte de l’image taillée, car son image de fonte est un mensonge; il n’y a point de respiration en elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Elles sont vanité, un ouvrage de déception; elles périront au temps de leur visitation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'La portion de Jacob n’est pas comme elles; car c’est Celui qui a tout formé, et [Israël] est la verge de son héritage: son nom est l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Tu es mon marteau, mes armes de guerre; et par toi je briserai les nations, et par toi je détruirai les royaumes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'et par toi je briserai le cheval et celui qui le monte, et par toi je briserai le char et celui qui le conduit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'et par toi je briserai l’homme et la femme, et par toi je briserai le vieillard et le jeune garçon, et par toi je briserai le jeune homme et la vierge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'et par toi je briserai le pasteur et son troupeau; et par toi je briserai le laboureur et son attelage; et par toi je briserai les gouverneurs et les chefs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'et je rendrai à Babylone et à tous les habitants de la Chaldée tout le mal qu’ils ont fait en Sion, devant vos yeux, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Voici, [j’en veux] à toi, dit l’ Éternel, montagne de destruction qui détruis toute la terre; j’étendrai ma main contre toi, et je te roulerai du haut des rochers, et je ferai de toi une montagne brûlante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Et on ne prendra pas de toi une pierre pour un angle, ni une pierre pour des fondements, car tu seras des désolations perpétuelles, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Élevez l’étendard dans le pays, sonnez de la trompette parmi les nations, préparez les nations contre elle, convoquez contre elle les royaumes d’Ararat, de Minni et d’Ashkenaz, établissez contre elle un capitaine, faites monter des chevaux comme des sauterelles hérissées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Préparez contre elle les nations, les rois des Mèdes, leurs capitaines, et tous leurs chefs, et tout le pays de leur domination.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Et la terre tremble et est en travail, car les desseins de l’ Éternel contre Babylone s’accomplissent, pour réduire la terre de Babylone en désolation, de sorte qu’il n’y a pas d’habitant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Les hommes forts de Babylone ont cessé de combattre, ils sont assis dans les places fortes; leur force est épuisée, ils sont comme des femmes; on a mis le feu à leurs demeures, leurs barres sont brisées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Le coureur court à la rencontre du coureur, et le messager à la rencontre du messager, pour annoncer au roi de Babylone que sa ville est prise de bout en bout,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'et que les passages sont saisis, et que les étangs sont brûlés par le feu, et que les hommes de guerre sont épouvantés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Car ainsi dit l’ Éternel des armées, le Dieu d’Israël: La fille de Babylone est comme une aire au temps où on la foule; encore un peu, et le temps de la moisson viendra pour elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Nebucadretsar, roi de Babylone, m’a dévorée, il m’a exterminée, il m’a laissée comme un vase vide; comme un dragon, il m’a avalée, il a rempli son ventre de mes délices, il m’a chassée au loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Que la violence qui m’est faite, et ma chair, soient sur Babylone, dira l’habitante de Sion; et que mon sang soit sur les habitants de la Chaldée, dira Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'C’est pourquoi, ainsi dit l’ Éternel: Voici, je prends en main ta cause, et j’exerce ta vengeance; et je dessécherai sa mer, et je tarirai sa source;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'et Babylone sera des monceaux [de ruines], un repaire de chacals, un sujet d’étonnement et de sifflement, de sorte qu’il n’y aura pas d’habitant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Ils rugiront ensemble comme de jeunes lions, ils gronderont comme les petits des lions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Quand ils seront échauffés, je préparerai leur breuvage, et je les enivrerai, afin qu’ils s’égaient, et qu’ils dorment d’un sommeil perpétuel et ne se réveillent plus, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Je les ferai descendre comme des agneaux à la tuerie, comme des béliers avec des boucs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Comment a été prise Shéshac, et comment la louange de toute la terre a-t-elle été saisie! Comment Babylone est-elle devenue un sujet d’étonnement parmi les nations!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'La mer est montée sur Babylone; elle a été couverte du tumulte de ses flots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Ses villes sont devenues une désolation, un pays sec et une lande aride, un pays où n’habite aucun homme et par où ne passe aucun fils d’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Et je punirai Bel à Babylone, et je ferai sortir de sa bouche ce qu’il a englouti, et les nations n’afflueront plus vers lui: la muraille aussi de Babylone est tombée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Sortez du milieu d’elle, mon peuple! et sauvez chacun son âme de l’ardeur de la colère de l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'de peur que votre cœur ne mollisse, et que vous n’ayez peur du bruit qui s’entendra sur la terre; car un bruit viendra une année, et après lui, un [autre] bruit une [autre] année, et il y aura violence sur la terre, dominateur contre dominateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'C’est pourquoi, voici, des jours viennent, et je punirai les images taillées de Babylone; et tout son pays sera honteux, et tous ses tués tomberont au milieu d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Et les cieux et la terre, et tout ce qui est en eux, exulteront avec chant de triomphe sur Babylone; car du nord il viendra des dévastateurs contre elle, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'De même que Babylone a fait tomber les tués d’Israël, de même les tués de toute la terre tomberont à Babylone. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Réchappés de l’épée, marchez, ne vous arrêtez pas! De loin souvenez-vous de l’ Éternel, et que Jérusalem vous vienne au cœur. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Nous sommes honteux, parce que nous avons entendu des opprobres; la confusion a couvert nos faces, car des étrangers sont entrés dans les sanctuaires de la maison de l’ Éternel. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'C’est pourquoi, voici, des jours viennent, dit l’ Éternel, et je punirai ses images taillées, et dans toute sa terre gémiront les blessés à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Que Babylone monte jusqu’aux cieux, et qu’elle fortifie la hauteur de sa force: de par moi viendront des dévastateurs contre elle, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'La voix d’un cri [qui vient] de Babylone! Une grande ruine, du pays des Chaldéens!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'car l’ Éternel dévaste Babylone, et il détruira du milieu d’elle la grande voix. Et leurs flots mugissent comme de grosses eaux, le bruit de leur voix retentit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Car le dévastateur est venu contre elle, contre Babylone; et ses hommes forts sont pris, leurs arcs sont brisés! Car l’ Éternel, le ✶Dieu des rétributions, rend certainement ce qui est dû.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Et j’enivrerai ses princes et ses sages, ses gouverneurs, et ses chefs, et ses hommes forts; et ils dormiront d’un sommeil perpétuel, et ils ne se réveilleront pas, dit le Roi: l’ Éternel des armées est son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Ainsi dit l’ Éternel des armées: La large muraille de Babylone sera entièrement rasée, et ses hautes portes seront brûlées par le feu; et les peuples auront travaillé pour néant, et les peuplades pour le feu, et elles seront lasses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'La parole que Jérémie le prophète commanda à Seraïa, fils de Nérija, fils de Makhséïa, quand il alla avec Sédécias, roi de Juda, à Babylone, en la quatrième année de son règne; or Seraïa était premier chambellan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Et Jérémie écrivit dans un livre tout le mal qui viendrait sur Babylone, toutes ces paroles qui sont écrites contre Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Et Jérémie dit à Seraïa: Quand tu seras venu à Babylone, alors regarde et lis toutes ces paroles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'et tu diras: Éternel! tu as parlé contre ce lieu pour le retrancher, de manière qu’il n’y ait pas d’habitant, depuis l’homme jusqu’à la bête, mais qu’il soit des désolations perpétuelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Et il arrivera que, quand tu auras achevé de lire ce livre, tu y attacheras une pierre, et tu le jetteras au milieu de l’Euphrate;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'et tu diras: Ainsi Babylone s’enfoncera, et ne se relèvera point du mal que je vais faire venir sur elle; et ils seront las. Jusqu’ici les paroles de Jérémie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, '***Sédécias était âgé de 21 ans lorsqu’il commença de régner; et il régna onze ans à Jérusalem; et le nom de sa mère était Hamutal, fille de Jérémie de Libna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Et il fit ce qui est mauvais aux yeux de l’ Éternel, selon tout ce que Jehoïakim avait fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Car, parce que la colère de l’ Éternel fut contre Jérusalem et Juda, jusqu’à les rejeter de devant sa face, Sédécias se révolta contre le roi de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Et il arriva, en la neuvième année de son règne, au dixième mois, le dixième [jour] du mois, que Nebucadretsar, roi de Babylone, vint contre Jérusalem, lui et toute son armée; et ils campèrent contre elle, et bâtirent contre elle une circonvallation tout à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Et la ville fut assiégée jusqu’à la onzième année du roi Sédécias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Au quatrième mois, le neuvième [jour] du mois, la famine se renforça dans la ville, et il n’y avait point de pain pour le peuple du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Et la brèche fut faite à la ville; et tous les hommes de guerre s’enfuirent et sortirent de nuit de la ville, par le chemin de la porte qui était entre les deux murailles près du jardin du roi (et les Chaldéens étaient près de la ville tout à l’entour); et ils s’en allèrent par le chemin de la plaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Et l’armée des Chaldéens poursuivit le roi; et ils atteignirent Sédécias dans les plaines de Jéricho, et toute son armée se dispersa d’avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Et ils prirent le roi, et le firent monter vers le roi de Babylone à Ribla, dans le pays de Hamath; et il prononça son jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Et le roi de Babylone égorgea les fils de Sédécias devant ses yeux, et il égorgea aussi tous les chefs de Juda à Ribla;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'et il creva les yeux à Sédécias, et le lia avec des chaînes d’airain, et le roi de Babylone l’amena à Babylone, et le mit sous garde en prison, jusqu’au jour de sa mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Et au cinquième mois, le dixième [jour] du mois (c’était la dix -neuvième année du roi Nebucadretsar, roi de Babylone), Nebuzaradan, chef des gardes, qui se tenait devant le roi de Babylone, vint à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Et il brûla la maison de l’ Éternel, et la maison du roi, et toutes les maisons de Jérusalem; et il brûla par le feu toutes les grandes maisons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Et toute l’armée des Chaldéens qui était avec le chef des gardes abattit toutes les murailles [qui étaient] autour de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Et les plus pauvres du peuple, et le reste du peuple, qui était demeuré de reste dans la ville, et les transfuges qui s’étaient rendus au roi de Babylone, et le reste de la multitude, Nebuzaradan, chef des gardes, les transporta;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'mais des pauvres du pays, Nebuzaradan, chef des gardes, en laissa pour être vignerons et laboureurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Et les Chaldéens brisèrent les colonnes d’airain qui étaient devant la maison de l’ Éternel, et les bases, et la mer d’airain qui était dans la maison de l’ Éternel, et en emportèrent tout l’airain à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Ils prirent aussi les vases [à cendre], et les pelles, et les couteaux, et les bassins, et les coupes, et tous les ustensiles d’airain avec lesquels on faisait le service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Et le chef des gardes prit les écuelles, et les brasiers, et les bassins, et les vases [à cendre], et les chandeliers, et les coupes et les vases, ce qui était d’or, en or, et ce qui était d’argent, en argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Les deux colonnes, la mer unique, et les douze bœufs d’airain qui tenaient lieu de socles, que le roi Salomon avait faits pour la maison de l’ Éternel: pour l’airain de tous ces objets il n’y avait point de poids.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Et quant aux colonnes, la hauteur d’une colonne était de 18 coudées, et un filet de douze coudées en faisait le tour, et son épaisseur était de quatre doigts; elle était creuse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'et il y avait dessus un chapiteau d’airain, et la hauteur d’un chapiteau était de cinq coudées; et il y avait un réseau et des grenades tout autour du chapiteau, le tout d’airain: et de même pour la seconde colonne, [elle avait] aussi des grenades;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'et il y avait 96 grenades sur les [quatre] côtés; toutes les grenades sur le réseau à l’entour étaient au nombre de 100.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Et le chef des gardes prit Seraïa, le premier sacrificateur, et Sophonie, le second sacrificateur, et les trois gardiens du seuil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'et il prit de la ville un eunuque qui était inspecteur des hommes de guerre, et sept hommes de ceux qui voyaient la face du roi, lesquels furent trouvés dans la ville, et le scribe du chef de l’armée, qui enrôlait le peuple du pays, et 60 hommes du peuple du pays, qui furent trouvés dans la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Et Nebuzaradan, chef des gardes, les prit et les mena vers le roi de Babylone à Ribla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Et le roi de Babylone les frappa et les fit mourir à Ribla, dans le pays de Hamath. Et Juda fut transporté de dessus sa terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'C’est ici le peuple que Nebucadretsar transporta: la septième année, 3 023 Juifs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'la dix-huitième année de Nebucadretsar, [il transporta] de Jérusalem 832 âmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, '[et] la vingt-troisième année de Nebucadretsar, Nebuzaradan, chef des gardes, transporta d’entre les Juifs 745 âmes: toutes les âmes furent 4 600.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Et il arriva, en la trente-septième année de la transportation de Jehoïakin, roi de Juda, au douzième mois, le vingt-cinquième [jour] du mois, qu’Évil-Merodac, roi de Babylone, l’année où il commença de régner, éleva la tête de Jehoïakin, roi de Juda, et le fit sortir de prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Et il lui parla avec bonté, et mit son trône au-dessus du trône des rois qui étaient avec lui à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Et il lui changea ses vêtements de prison, et [Jehoïakin] mangea le pain devant lui constamment, tous les jours de sa vie:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'et quant à son entretien régulier, un entretien continuel lui fut donné de la part du roi de Babylone, jour par jour, jusqu’au jour de sa mort, tous les jours de sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Comment est-elle assise solitaire, la ville si peuplée! Celle qui était grande entre les nations est devenue comme veuve; la princesse parmi les provinces est devenue tributaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Elle pleure, elle pleure pendant la nuit, et ses larmes sont sur ses joues; de tous ses amants, il n’en est pas un qui la console; tous ses amis ont agi perfidement envers elle, ils sont pour elle des ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juda est allé en captivité à cause de [son] affliction et de la grandeur de [son] esclavage; il habite parmi les nations, il n’a pas trouvé de repos; tous ses persécuteurs l’ont atteint dans [ses] lieux resserrés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Les chemins de Sion mènent deuil de ce qu’il n’y a personne qui vienne aux fêtes; toutes ses portes sont désolées; ses sacrificateurs gémissent, ses vierges sont dans la détresse; elle-même est dans l’amertume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Ses adversaires dominent, ses ennemis prospèrent; car l’ Éternel l’a affligée à cause de la multitude de ses transgressions; ses petits enfants ont marché captifs devant l’adversaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Et toute la magnificence de la fille de Sion s’est retirée d’elle. Ses princes sont comme des cerfs qui ne trouvent pas de pâture, et ils s’en sont allés sans force devant celui qui les poursuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jérusalem, dans les jours de son affliction et de son bannissement, lorsque son peuple tombait dans la main de l’ennemi et qu’il n’y avait personne qui l’aide, s’est souvenue de toutes les choses désirables qu’elle avait dans les jours d’autrefois; les adversaires l’ont vue, ils se sont moqués de sa ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jérusalem a grièvement péché, c’est pourquoi elle est [rejetée] comme une impureté; tous ceux qui l’honoraient l’ont méprisée, car ils ont vu sa nudité: elle aussi gémit et s’est retournée en arrière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Son impureté était aux pans de sa robe, elle ne s’est pas souvenue de sa fin; elle est descendue prodigieusement; il n’y a personne qui la console! Regarde, ô Éternel, mon affliction, car l’ennemi s’est élevé avec orgueil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'L’ennemi a étendu sa main sur toutes ses choses désirables; car elle a vu entrer dans son sanctuaire les nations, au sujet desquelles tu avais commandé qu’elles n’entreraient point dans ta congrégation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Tout son peuple gémit; ils cherchent du pain; ils ont donné leurs choses désirables contre des aliments pour restaurer [leur] âme. Regarde, Éternel, et contemple, car je suis devenue vile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'N’est-ce rien pour vous tous qui passez par le chemin? Contemplez, et voyez s’il est une douleur comme ma douleur qui m’est survenue, à moi que l’ Éternel a affligée au jour de l’ardeur de sa colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'D’en haut il a envoyé dans mes os un feu qui les a maîtrisés; il a tendu un filet pour mes pieds, il m’a fait retourner en arrière; il m’a mise dans la désolation, dans la langueur, tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Le joug de mes transgressions est lié par sa main; elles sont entrelacées, elles montent sur mon cou; il a fait défaillir ma force; le Seigneur m’a livrée en des mains d’où je ne puis me relever.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Le Seigneur a abattu tous mes hommes forts au milieu de moi; il a convoqué contre moi une assemblée pour écraser mes jeunes gens. Le Seigneur a foulé comme au pressoir la vierge, fille de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'À cause de ces choses je pleure; mon œil, mon œil se fond en eau; car il est loin de moi, le consolateur qui restaurerait mon âme. Mes fils sont péris, car l’ennemi a été le plus fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Sion étend ses mains, il n’y a personne qui la console. L’ Éternel a commandé au sujet de Jacob que ses adversaires l’entourent; Jérusalem est devenue au milieu d’eux une impureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'L’ Éternel est juste; car je me suis rebellée contre son commandement. Écoutez, je vous prie, vous tous les peuples, et voyez ma douleur: mes vierges et mes jeunes gens sont allés en captivité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'J’ai appelé mes amants: ils m’ont trompée. Mes sacrificateurs et mes anciens ont expiré dans la ville, alors qu’ils se sont cherché de la nourriture afin de restaurer leur âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Regarde, Éternel, car je suis dans la détresse; mes entrailles sont agitées, mon cœur est bouleversé au-dedans de moi, car je me suis grièvement rebellée: au-dehors l’épée m’a privée d’enfants; au-dedans, c’est comme la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Ils m’ont entendue gémir: il n’y a personne qui me console; tous mes ennemis ont appris mon malheur, ils se sont réjouis de ce que toi tu l’as fait. Tu feras venir le jour que tu as appelé, et ils seront comme moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Que toute leur iniquité vienne devant toi, et fais -leur comme tu m’as fait à cause de toutes mes transgressions; car mes gémissements sont nombreux, et mon cœur est languissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Comment, dans sa colère, le Seigneur a-t-il couvert d’un nuage la fille de Sion! Il a jeté des cieux sur la terre la beauté d’Israël, et, au jour de sa colère, il ne s’est pas souvenu du marchepied de ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Le Seigneur a englouti, sans épargner, toutes les habitations de Jacob; il a renversé dans sa fureur les forteresses de la fille de Juda; il a jeté par terre, il a profané le royaume et ses princes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Il a retranché, dans l’ardeur de sa colère, toute la corne d’Israël; il a retiré sa droite devant l’ennemi, et il a brûlé en Jacob comme un feu flamboyant qui dévore à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Il a bandé son arc comme un ennemi; il s’est tenu là avec sa droite comme un adversaire, et il a tué tout ce qui était agréable à l’œil dans la tente de la fille de Sion; il a versé, comme un feu, sa fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Le Seigneur a été comme un ennemi; il a englouti Israël; il a englouti tous ses palais, il a détruit ses forteresses, et il a multiplié chez la fille de Juda le gémissement et la plainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Il a saccagé sa clôture comme un jardin; il a détruit le lieu de son assemblée. L’ Éternel a fait oublier dans Sion jour solennel et sabbat; et, dans l’indignation de sa colère, il a méprisé roi et sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Le Seigneur a rejeté son autel, il a répudié son sanctuaire; il a livré en la main de l’ennemi les murs de ses palais; on a poussé des cris dans la maison de l’ Éternel comme au jour d’une fête solennelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'L’ Éternel s’est proposé de détruire la muraille de la fille de Sion; il a étendu le cordeau, il n’a pas retiré sa main pour cesser de détruire; et il fait mener deuil au rempart et à la muraille: ils languissent ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Ses portes sont enfoncées dans la terre; il a détruit et brisé ses barres; son roi et ses princes sont parmi les nations; la loi n’est plus; ses prophètes aussi ne trouvent pas de vision de la part de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Les anciens de la fille de Sion sont assis par terre, ils gardent le silence; ils ont mis de la poussière sur leur tête, ils se sont ceints de sacs; les vierges de Jérusalem baissent leur tête vers la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Mes yeux se consument dans les larmes, mes entrailles sont agitées, mon foie s’est répandu sur la terre, à cause de la ruine de la fille de mon peuple, parce que les enfants et ceux qui tètent défaillent dans les places de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Ils disent à leurs mères: Où est le blé et le vin? – défaillant dans les places de la ville comme des blessés à mort, [et] rendant l’âme sur le sein de leurs mères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Quel témoignage t’apporterai-je? Que comparerai-je à toi, fille de Jérusalem? Qui est-ce que j’égalerai à toi, afin que je te console, vierge, fille de Sion? car ta ruine est grande comme la mer: qui te guérira?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Tes prophètes ont vu pour toi la vanité et la folie, et ils n’ont pas mis à découvert ton iniquité pour détourner ta captivité; mais ils ont vu pour toi des oracles de vanité et de séduction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Tous ceux qui passent par le chemin battent des mains sur toi; ils sifflent et branlent la tête sur la fille de Jérusalem: Est-ce ici la ville dont on disait: La parfaite en beauté, la joie de toute la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Tous tes ennemis ouvrent la bouche sur toi; ils sifflent et grincent des dents; ils disent: Nous les avons engloutis; oui, c’est ici le jour que nous attendions! Nous l’avons trouvé, nous l’avons vu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'L’ Éternel a fait ce qu’il s’était proposé, il a accompli sa parole qu’il avait commandée dès les jours d’autrefois; il a renversé et n’a point épargné, et il a fait que l’ennemi s’est réjoui sur toi; il a élevé la corne de tes adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Leur cœur a crié au Seigneur. Muraille de la fille de Sion, laisse couler des larmes jour et nuit, comme un torrent; ne te donne pas de relâche, que la prunelle de tes yeux ne cesse point!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Lève-toi, crie de nuit au commencement des veilles; répands ton cœur comme de l’eau devant la face du Seigneur. Lève tes mains vers lui pour la vie de tes petits enfants qui défaillent de faim au coin de toutes les rues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Regarde, Éternel, et considère à qui tu as fait ainsi! Les femmes dévoreront-elles leur fruit, les petits enfants dont elles prennent soin? Tuera-t-on le sacrificateur et le prophète dans le sanctuaire du Seigneur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'L’enfant et le vieillard sont couchés par terre dans les rues; mes vierges et mes jeunes hommes sont tombés par l’épée: tu as tué au jour de ta colère, tu as égorgé, tu n’as point épargné!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Tu as convoqué, comme en un jour de fête solennelle, mes terreurs de toutes parts; et au jour de la colère de l’ Éternel, il n’y a eu ni réchappé, ni reste: ceux dont j’avais pris soin et que j’avais élevés, mon ennemi les a consumés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, '*Je suis l’homme qui ai vu l’affliction par la verge de sa fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Il m’a conduit et amené dans les ténèbres, et non dans la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Certes c’est contre moi qu’il a tout le jour tourné et retourné sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Il a fait vieillir ma chair et ma peau; il a brisé mes os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Il a bâti contre moi, et m’a environné de fiel et de peine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Il m’a fait habiter dans des lieux ténébreux, comme ceux qui sont morts depuis longtemps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Il a fait une clôture autour de moi, afin que je ne sorte point; il a appesanti mes chaînes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Même quand je crie et que j’élève ma voix, il ferme l’accès à ma prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Il a barré mes chemins avec des pierres de taille; il a bouleversé mes sentiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Il a été pour moi un ours aux embûches, un lion dans les lieux cachés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Il a fait dévier mes chemins et m’a déchiré; il m’a rendu désolé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Il a bandé son arc, et m’a placé comme un but pour la flèche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Il a fait entrer dans mes reins les flèches de son carquois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Je suis la risée de tout mon peuple, leur chanson tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Il m’a rassasié d’amertumes, il m’a abreuvé d’absinthe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Il m’a brisé les dents avec du gravier; il m’a couvert de cendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Et tu as rejeté mon âme loin de la paix, j’ai oublié le bonheur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'et j’ai dit: Ma confiance est périe, et mon espérance en l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Souviens-toi de mon affliction, et de mon bannissement, de l’absinthe et du fiel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Mon âme s’en souvient sans cesse, et elle est abattue au-dedans de moi. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Je rappelle ceci à mon cœur, c’est pourquoi j’ai espérance:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Ce sont les bontés de l’ Éternel que nous ne sommes pas consumés, car ses compassions ne cessent pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'elles sont nouvelles chaque matin; grande est ta fidélité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'L’ Éternel est ma portion, dit mon âme; c’est pourquoi j’espérerai en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'L’ Éternel est bon pour ceux qui s’attendent à lui, pour l’âme qui le cherche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'C’est une chose bonne qu’on attende, et dans le silence, le salut de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Il est bon à l’homme de porter le joug dans sa jeunesse:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Il est assis solitaire, et se tait, parce qu’il l’a pris sur lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'il met sa bouche dans la poussière: peut-être y aura-t-il quelque espoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Il présente la joue à celui qui le frappe, il est rassasié d’opprobres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Car le Seigneur ne rejette pas pour toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'mais, s’il afflige, il a aussi compassion, selon la grandeur de ses bontés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'car ce n’est pas volontiers qu’il afflige et contriste les fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Qu’on écrase sous les pieds tous les prisonniers de la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'qu’on fasse fléchir le droit d’un homme devant la face du Très-haut,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'qu’on fasse tort à un homme dans sa cause, le Seigneur ne le voit-il point?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Qui est-ce qui dit une chose, et elle arrive, quand le Seigneur ne l’a point commandée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'N’est-ce pas de la bouche du Très-haut que viennent les maux et les biens?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Pourquoi un homme vivant se plaindrait-il, un homme, à cause de la peine de ses péchés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Recherchons nos voies, et scrutons-les, et retournons jusqu’à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Élevons nos cœurs avec nos mains vers ✶Dieu dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Nous avons désobéi et nous avons été rebelles; tu n’as pas pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Tu t’es enveloppé de colère et tu nous as poursuivis; tu as tué, tu n’as point épargné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Tu t’es enveloppé d’un nuage, de manière à ce que la prière ne passe point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Tu nous as faits la balayure et le rebut au milieu des peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Tous nos ennemis ont ouvert la bouche sur nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'La frayeur et la fosse sont venues sur nous, la destruction et la ruine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Des ruisseaux d’eaux coulent de mes yeux à cause de la ruine de la fille de mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Mon œil se fond en eau, il ne cesse pas et n’a point de relâche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'jusqu’à ce que l’ Éternel regarde et voie des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Mon œil afflige mon âme à cause de toutes les filles de ma ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Ceux qui sont mes ennemis sans cause m’ont donné la chasse comme à l’oiseau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Ils m’ont ôté la vie dans une fosse, et ont jeté des pierres sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Les eaux ont coulé par-dessus ma tête; j’ai dit: Je suis retranché!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'J’ai invoqué ton nom, ô Éternel! de la fosse des abîmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Tu as entendu ma voix; ne cache point ton oreille à mon soupir, à mon cri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Tu t’es approché au jour où je t’ai invoqué; tu as dit: Ne crains pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Seigneur, tu as pris en main la cause de mon âme, tu as racheté ma vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Tu as vu, Éternel, le tort qu’on me fait; juge ma cause.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Tu as vu toute leur vengeance, toutes leurs machinations contre moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Tu as entendu leurs outrages, ô Éternel! toutes leurs machinations contre moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'les lèvres de ceux qui s’élèvent contre moi, et ce qu’ils se proposent contre moi tout le jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Regarde quand ils s’asseyent et quand ils se lèvent: je suis leur chanson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Rends-leur une récompense, ô Éternel! selon l’ouvrage de leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Donne-leur un cœur cuirassé; ta malédiction soit sur eux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Poursuis-les dans ta colère et détruis-les de dessous les cieux de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, '*Comment l’or est-il devenu obscur, et l’or fin a-t-il été changé! [Comment] les pierres du lieu saint sont-elles répandues au coin de toutes les rues!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Les fils de Sion, si précieux, estimés à l’égal de l’or fin, comment sont-ils réputés des vases de terre, ouvrage des mains d’un potier?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Les chacals même présentent la mamelle, allaitent leurs petits; la fille de mon peuple est devenue cruelle comme les autruches du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'La langue de celui qui tétait se colle par la soif à son palais; les petits enfants demandent du pain, personne ne le rompt pour eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Ceux qui mangeaient des mets délicats sont là, périssant dans les rues; ceux qui étaient élevés sur l’écarlate embrassent le fumier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Et la peine de l’iniquité de la fille de mon peuple est plus grande que la peine du péché de Sodome qui fut renversée comme en un moment sans qu’on ait porté les mains sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Ses nazaréens étaient plus purs que la neige, plus blancs que le lait; leur corps était plus vermeil que des rubis, leur taille un saphir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Leur figure est plus sombre que le noir, on ne les connaît pas dans les rues; leur peau s’attache à leurs os, elle est sèche comme du bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Ceux qui ont été tués par l’épée ont été plus heureux que ceux qui sont morts par la famine; parce que ceux-ci ont dépéri, consumés par le manque du produit des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Les mains de femmes tendres ont cuit leurs enfants, ils ont été leur viande dans la ruine de la fille de mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'L’ Éternel a accompli sa fureur, il a versé l’ardeur de sa colère et a allumé dans Sion un feu qui en a dévoré les fondements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Les rois de la terre et tous les habitants du monde n’auraient pas cru que l’adversaire et l’ennemi entreraient dans les portes de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'C’est à cause des péchés de ses prophètes, des iniquités de ses sacrificateurs, qui versaient au milieu d’elle le sang des justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Ils erraient aveugles par les rues, ils étaient souillés de sang, de sorte qu’on ne pouvait toucher leurs vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Retirez-vous! un impur! leur criait-on; retirez-vous, retirez-vous, ne touchez pas!... Quand ils se sont enfuis, ils ont erré çà et là; on a dit parmi les nations: Ils n’auront plus leur demeure!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'La face de l’ Éternel les a coupés en deux; il ne veut plus les regarder. Ils n’ont pas respecté la face des sacrificateurs, ils n’ont pas usé de grâce envers les vieillards.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Pour nous, nos yeux se consumaient après un secours de vanité; nous avons attendu continuellement une nation qui ne sauvait pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Ils ont fait la chasse à nos pas, de manière que nous ne pouvions pas marcher sur nos places: notre fin est proche, nos jours sont accomplis; notre fin est venue!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Ceux qui nous poursuivaient ont été plus rapides que les aigles des cieux, ils nous ont donné la chasse sur les montagnes, ils nous ont tendu des embûches dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Le souffle de nos narines, l’oint de l’ Éternel, a été pris dans leurs fosses, celui dont nous disions: Nous vivrons sous son ombre parmi les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Sois dans l’allégresse et réjouis-toi, fille d’Édom, qui habites dans le pays d’Uts! La coupe passera aussi vers toi; tu en seras enivrée, et tu te mettras à nu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'La peine de ton iniquité a pris fin, fille de Sion; il ne te mènera plus captive. Il visitera ton iniquité, fille d’Édom; il découvrira tes péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Souviens-toi, ô Éternel! de ce qui nous est arrivé. Regarde, et vois notre opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Notre héritage est dévolu à des étrangers, nos maisons, à des forains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Nous sommes des orphelins, sans père; nos mères sont comme des veuves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Nous buvons notre eau à prix d’argent; notre bois nous vient par achat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Ceux qui nous poursuivent sont sur notre cou; nous nous fatiguons, pas de repos pour nous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Nous avons tendu la main vers l’Égypte, vers l’Assyrie, pour être rassasiés de pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Nos pères ont péché, ils ne sont plus, et nous portons la peine de leurs iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Des serviteurs dominent sur nous; personne ne nous délivre de leur main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Nous recueillons notre pain au [péril de] notre vie, à cause de l’épée du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Notre peau brûle comme un four, à cause de l’ardeur de la faim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Ils ont humilié les femmes dans Sion, les vierges dans les villes de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Des princes ont été pendus par leur main; la personne des vieillards n’a pas été honorée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Les jeunes gens ont porté les meules, et les jeunes garçons ont trébuché sous le bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Les vieillards ne sont plus assis dans la porte, les jeunes gens n’[y] chantent plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Notre cœur a cessé de se réjouir; notre danse est changée en deuil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'La couronne de notre tête est tombée. Malheur à nous, car nous avons péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'À cause de cela notre cœur est abattu; à cause de ces choses nos yeux sont obscurcis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'À cause de la montagne de Sion qui est désolée: les renards s’y promènent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Toi, ô Éternel! tu demeures à toujours, ton trône est de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Pourquoi nous oublies-tu à jamais, nous abandonnes-tu pour de longs jours?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Fais-nous revenir à toi, ô Éternel! et nous reviendrons; renouvelle nos jours comme [ils étaient] autrefois!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Ou bien, nous aurais-tu entièrement rejetés? Serais-tu extrêmement courroucé contre nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Et il arriva en la trentième année, au quatrième [mois], le cinquième [jour] du mois, comme j’étais au milieu des captifs, près du fleuve Kebar, que les cieux furent ouverts, et je vis des visions de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Le cinquième [jour] du mois (c’était la cinquième année de la transportation du roi Jehoïakin),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'la parole de l’ Éternel vint expressément à Ézéchiel, le sacrificateur, fils de Buzi, dans le pays des Chaldéens, près du fleuve Kebar; et la main de l’ Éternel fut là sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Et je vis, et voici, un vent de tempête venait du nord, une grosse nuée, et un feu qui s’entortillait; et il y avait une splendeur tout autour, et de son milieu, du milieu du feu, [brillait] comme l’apparence de l’airain luisant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'et, du milieu, la ressemblance de quatre animaux; et voici leur aspect: ils avaient la ressemblance d’un homme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'et chacun d’eux avait quatre faces, et chacun avait quatre ailes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'et leurs pieds étaient des pieds droits, et la plante de leurs pieds était comme la plante du pied d’un veau; et ils étincelaient comme l’apparence de l’airain poli;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'et il y avait des mains d’homme sous leurs ailes sur leurs quatre côtés; et ils avaient, les quatre, leurs faces et leurs ailes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'leurs ailes étaient jointes l’une à l’autre; ils ne se tournaient pas quand ils allaient: ils allaient chacun droit devant soi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Et la ressemblance de leurs faces était la face d’un homme; et, les quatre, ils avaient la face d’un lion, à droite; et, les quatre, ils avaient la face d’un bœuf, à gauche; et, les quatre, ils avaient la face d’un aigle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'et leurs faces et leurs ailes étaient séparées par le haut: chacun avait deux [ailes] jointes l’une à l’autre, et deux qui couvraient leur corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Et ils allaient chacun droit devant soi: là où l’Esprit devait aller, ils allaient; ils ne se tournaient point lorsqu’ils allaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Et quant à la ressemblance des animaux, leur aspect était comme des charbons de feu brûlants, comme l’aspect de torches; le [feu] courait entre les animaux; et le feu avait de l’éclat, et du feu sortaient des éclairs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Et les animaux couraient et retournaient, comme l’aspect du sillon de l’éclair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Et je regardais les animaux, et voici, une roue sur la terre, à côté des animaux, vers leurs quatre faces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'L’aspect et la structure des roues étaient comme l’apparence d’une chrysolithe; et il y avait une même ressemblance pour les quatre, et leur aspect et leur structure étaient comme si une roue avait été au milieu d’une roue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'En allant, elles allaient sur leurs quatre côtés; elles ne se tournaient point quand elles allaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Et quant à leurs jantes, elles étaient hautes et terribles, – et leurs jantes, à toutes les quatre, étaient pleines d’yeux tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Et quand les animaux allaient, les roues allaient à côté d’eux; et quand les animaux s’élevaient de dessus la terre, les roues s’élevaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Là où l’Esprit devait aller, là ils allaient, là [leur] esprit tendait à aller; et les roues s’élevaient auprès d’eux, car l’esprit de l’animal était dans les roues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Quand ils allaient, elles allaient; et quand ils s’arrêtaient, elles s’arrêtaient; et quand ils s’élevaient de dessus la terre, les roues s’élevaient auprès d’eux, car l’esprit de l’animal était dans les roues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Et au-dessus des têtes de l’animal, il y avait la ressemblance d’une étendue, comme l’apparence d’un cristal terrible étendu sur leurs têtes, en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Et au-dessous de l’étendue, leurs ailes se tenaient droites, l’une vers l’autre: chacun en avait deux, qui couvraient [leur corps], d’un côté, et chacun en avait deux, qui couvraient leur corps, de l’autre côté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Et j’entendis le bruit de leurs ailes quand ils volaient, comme le bruit de grandes eaux, comme la voix du Tout-puissant, un bruit tumultueux comme le bruit d’une armée. Quand ils s’arrêtaient, ils abaissaient leurs ailes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'et il y avait une voix au-dessus de l’étendue qui était sur leurs têtes: quand ils s’arrêtaient, ils abaissaient leurs ailes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Et au-dessus de l’étendue qui était sur leurs têtes, il y avait comme l’aspect d’une pierre de saphir, la ressemblance d’un trône; et, sur la ressemblance du trône, une ressemblance comme l’aspect d’un homme, dessus, en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Et je vis comme l’apparence de l’airain luisant, comme l’aspect du feu, au-dedans, tout autour: depuis l’aspect de ses reins vers le haut et depuis l’aspect de ses reins vers le bas, je vis comme l’aspect du feu; et il y avait une splendeur tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Comme l’aspect de l’arc qui est dans la nuée en un jour de pluie, tel était l’aspect de la splendeur tout autour. C’était là l’aspect de la ressemblance de la gloire de l’ Éternel. Et je vis, et je tombai sur ma face, et j’entendis une voix qui parlait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Et il me dit: Fils d’homme, tiens-toi debout sur tes pieds, et je parlerai avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Et comme il me parlait, l’Esprit entra en moi, et me fit tenir sur mes pieds, et j’entendis celui qui me parlait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Et il me dit: Fils d’homme, je t’envoie vers les fils d’Israël, vers les nations, les rebelles qui se sont rebellés contre moi; eux et leurs pères m’ont désobéi jusqu’à ce jour même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Et ce sont des fils à la face impudente et au cœur obstiné; je t’envoie vers eux, et tu leur diras: Ainsi dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Et eux, soit qu’ils écoutent, soit qu’ils n’en fassent rien, car ils sont une maison rebelle, ils sauront qu’il y a eu un prophète au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Et toi, fils d’homme, ne les crains pas, et ne crains pas leurs paroles; car tu as près de toi des ronces et des épines, et tu demeures parmi des scorpions: ne crains point leurs paroles et ne sois point effrayé de leurs visages, car ils sont une maison rebelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Et tu leur diras mes paroles, soit qu’ils écoutent, soit qu’ils n’en fassent rien; car ils sont rebelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Et toi, fils d’homme, écoute ce que je te dis; ne sois pas rebelle, comme cette maison rebelle; ouvre ta bouche, et mange ce que je te donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Et je regardai, et voici, une main étendue vers moi, et voici, il y avait en elle un rouleau de livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Et il le déploya devant moi; et il était écrit devant et derrière; et des lamentations, et des plaintes, et des gémissements y étaient écrits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Et il me dit: Fils d’homme, mange ce que tu trouves; mange ce rouleau, et va, parle à la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Et j’ouvris ma bouche, et il me donna à manger ce rouleau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Et il me dit: Fils d’homme, nourris ton ventre et remplis tes entrailles de ce rouleau que je te donne. Et je le mangeai, et il fut dans ma bouche doux comme du miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Et il me dit: Va, fils d’homme, va vers la maison d’Israël, et tu leur parleras avec mes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Car ce n’est pas vers un peuple à langage obscur ou à langue incompréhensible que tu es envoyé: c’est vers la maison d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'ce n’est pas vers beaucoup de peuples à langage obscur ou à langue incompréhensible, dont tu ne puisses entendre les paroles: si tu étais envoyé vers eux, ne t’écouteraient-ils pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Mais la maison d’Israël ne voudra pas t’écouter, car aucun d’eux ne veut m’écouter; car toute la maison d’Israël a le front dur et le cœur obstiné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Voici, j’ai rendu ta face dure contre leurs faces, et ton front dur contre leur front;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'j’ai rendu ton front comme un diamant, plus dur que le roc. Ne les crains pas, et ne sois point effrayé d’eux, car ils sont une maison rebelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Et il me dit: Fils d’homme, toutes mes paroles que je te dirai, reçois-les dans ton cœur, et écoute-les de tes oreilles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'et va, va vers ceux de la transportation, vers les fils de ton peuple, et tu leur parleras et tu leur diras: Ainsi dit le Seigneur l’ Éternel, – soit qu’ils écoutent, soit qu’ils n’en fassent rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Et l’Esprit m’enleva; et j’entendis derrière moi le bruit d’une grande commotion, [disant]: Bénie soit de son lieu la gloire de l’ Éternel! –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'et le bruit des ailes des animaux qui s’entre-touchaient l’une l’autre, et le bruit des roues auprès d’eux, et le bruit d’une grande commotion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Et l’Esprit m’enleva, et me prit; et je m’en allai plein d’amertume dans l’ardeur de mon esprit; et la main de l’ Éternel était forte sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Et je vins à Thel-Abib vers ceux de la transportation qui demeuraient auprès du fleuve Kebar; et là où ils étaient assis, je m’assis stupéfait, là au milieu d’eux, sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Et il arriva, au bout de sept jours, que la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Fils d’homme, je t’ai établi sentinelle pour la maison d’Israël; et tu entendras la parole de ma bouche, et tu les avertiras de ma part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Quand je dirai au méchant: Tu mourras certainement, et que tu ne l’avertiras pas, et que tu ne parleras pas pour avertir le méchant [de se détourner] de sa méchante voie, afin qu’il vive, – lui, le méchant, mourra dans son iniquité, mais je redemanderai son sang de ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Et si tu avertis le méchant, et qu’il ne se détourne pas de sa méchanceté ni de sa méchante voie, il mourra, lui, dans son iniquité; mais toi, tu as délivré ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Et si le juste se détourne de sa justice et commet l’iniquité, et que je mette une pierre d’achoppement devant lui, il mourra; parce que tu ne l’as point averti, il mourra dans son péché, et ses actes justes qu’il a faits ne viendront pas en mémoire; mais je redemanderai son sang de ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Et si tu avertis le juste de ne pas pécher, et que le juste ne pèche pas, il vivra certainement, car il s’est tenu pour averti; et toi tu as délivré ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Et la main de l’ Éternel fut là sur moi, et il me dit: Lève-toi, sors dans la vallée, et là je parlerai avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Et je me levai, et je sortis dans la vallée; et voici, la gloire de l’ Éternel se tenait là, selon la gloire que j’avais vue près du fleuve Kebar; et je tombai sur ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Et l’Esprit entra en moi et me fit tenir sur mes pieds; et il me parla, et me dit: Va, enferme-toi dans ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Et toi, fils d’homme, voici, on mettra sur toi des cordes, et on t’en liera; et tu ne sortiras pas parmi eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Et je collerai ta langue à ton palais, et tu seras muet, et tu ne seras pas pour eux un homme qui les reprenne; car ils sont une maison rebelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Et quand je parlerai avec toi, j’ouvrirai ta bouche, et tu leur diras: Ainsi dit le Seigneur, l’ Éternel: Que celui qui écoute, écoute; et que celui qui n’en fait rien, n’en fasse rien; car ils sont une maison rebelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Et toi, fils d’homme, prends une brique et mets-la devant toi, et trace sur elle une ville, Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Et mets le siège contre elle, et bâtis contre elle des tours, et élève contre elle une terrasse, et pose des camps contre elle, et place contre elle des béliers tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Et toi, prends une plaque de fer, et mets-la comme un mur de fer entre toi et la ville; et dresse ta face contre elle, et elle sera assiégée, et tu l’assiégeras: ce sera un signe pour la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Et toi, couche-toi sur ton côté gauche, et mets sur lui l’iniquité de la maison d’Israël: le nombre des jours que tu coucheras sur ce côté, tu porteras leur iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Et moi, je t’ai assigné les années de leur iniquité selon le nombre des jours, 390 jours, et tu porteras l’iniquité de la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Et quand tu auras accompli ceux-là, tu te coucheras une seconde fois sur ton côté droit, et tu porteras l’iniquité de la maison de Juda, 40 jours; je t’ai assigné un jour pour chaque année.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Et tu dresseras ta face vers le siège de Jérusalem; et ton bras sera découvert, et tu prophétiseras contre elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Et voici, j’ai mis sur toi des cordes, et tu ne te tourneras point de l’un de tes côtés sur l’autre, jusqu’à ce que tu aies accompli les jours de ton siège.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Et toi, prends du froment, et de l’orge, et des fèves, et des lentilles, et du millet, et de l’épeautre; et tu les mettras dans un même vase, et tu t’en feras du pain selon le nombre des jours que tu te coucheras sur ton côté: tu en mangeras 390 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Et ton manger que tu mangeras sera au poids, 20 sicles par jour; tu le mangeras de temps en temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Et l’eau, tu la boiras à la mesure, un sixième de hin; tu la boiras de temps en temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Et tu mangeras cela [préparé comme] un gâteau d’orge, et tu le cuiras sous leurs yeux avec des excréments sortis de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Et l’ Éternel dit: Les fils d’Israël mangeront ainsi leur pain impur parmi les nations où je les chasserai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Et je dis: Ah, Seigneur Éternel! voici, mon âme ne s’est pas rendue impure, et, depuis ma jeunesse jusqu’à maintenant, je n’ai mangé de rien de ce qui est mort de soi-même ou qui a été déchiré, et aucune chair impure n’est entrée dans ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Et il me dit: Regarde, je t’ai donné la fiente du bétail au lieu des excréments de l’homme, et tu cuiras ton pain sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Et il me dit: Fils d’homme, voici, je brise le bâton du pain dans Jérusalem; et ils mangeront le pain au poids et avec inquiétude, et ils boiront l’eau à la mesure et avec stupeur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'parce que le pain et l’eau manqueront; et ils seront dans la stupeur, les uns et les autres, et ils se consumeront dans leur iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Et toi, fils d’homme, prends un couteau tranchant (tu prendras un rasoir de barbier), et tu le feras passer sur ta tête et sur ta barbe; et tu prendras une balance à peser, et tu partageras les [cheveux].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Tu en brûleras un tiers dans le feu, au milieu de la ville, lorsque les jours du siège seront accomplis; et tu en prendras un tiers, [et] tu les frapperas avec le couteau tout autour; et un tiers, tu le disperseras au vent, et je tirerai l’épée après eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Et tu en prendras un petit nombre, et tu les serreras dans les pans de ta robe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'et de ceux-ci, tu en prendras encore, et tu les jetteras au milieu du feu, et tu les brûleras au feu: il en sortira un feu contre toute la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Ainsi dit le Seigneur, l’ Éternel: C’est ici Jérusalem! Je l’ai posée au milieu des nations, et autour d’elle, des pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'et, dans sa méchanceté, elle a été rebelle à mes jugements plus que les nations, et à mes statuts, plus que les pays qui sont autour d’elle; car ils ont rejeté mes jugements et n’ont point marché dans mes statuts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Parce que votre turbulence a été plus grande que celle des nations qui sont autour de vous, parce que vous n’avez point marché dans mes statuts et n’avez point pratiqué mes ordonnances, et que vous n’avez pas [même] agi selon les droits établis des nations qui sont autour de vous, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'à cause de cela, ainsi dit le Seigneur, l’ Éternel: Voici, j’en veux à toi, moi aussi, et j’exécuterai au milieu de toi des jugements aux yeux des nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'et je ferai en toi ce que je n’ai pas fait et ne ferai plus semblablement, à cause de toutes tes abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'C’est pourquoi les pères mangeront les fils au milieu de toi, et les fils mangeront les pères; et j’exécuterai des jugements sur toi, et je disperserai à tout vent tous tes restes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'C’est pourquoi, je suis vivant, dit le Seigneur, l’ Éternel! parce que tu as rendu impur mon sanctuaire par toutes tes choses exécrables et par toutes tes abominations, moi aussi, je retirerai mon œil et il n’aura plus compassion, et moi aussi je ne t’épargnerai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Un tiers d’entre vous mourra par la peste et sera consumé par la famine au milieu de toi; et un tiers tombera par l’épée autour de toi; et j’en disperserai un tiers à tout vent, et je tirerai l’épée après eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Et ma colère s’accomplira, et je satisferai ma fureur sur eux, et je me consolerai; et ils sauront que moi, l’ Éternel, j’ai parlé dans ma jalousie, quand j’aurai accompli ma fureur sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Et je ferai de toi un désert et un opprobre parmi les nations qui sont autour de toi, aux yeux de tout passant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Et l’opprobre et l’insulte seront une instruction et un étonnement pour les nations qui sont autour de toi, quand j’exécuterai sur toi des jugements, avec colère, et avec fureur, et par des châtiments de fureur. Moi, l’ Éternel, j’ai parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Quand j’enverrai parmi eux les flèches funestes de la famine qui seront pour la destruction, lesquelles j’enverrai pour vous détruire, j’augmenterai sur vous la famine, et je briserai pour vous le bâton du pain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'et j’enverrai sur vous la famine et les bêtes mauvaises qui te priveront d’enfants, et la peste et le sang passeront sur toi, et je ferai venir l’épée sur toi. Moi, l’ Éternel, j’ai parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Fils d’homme, tourne ta face contre les montagnes d’Israël, et prophétise contre elles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'et dis: Montagnes d’Israël, écoutez la parole du Seigneur, l’ Éternel: Ainsi dit le Seigneur, l’ Éternel, aux montagnes et aux collines, aux ravins et aux vallées: Voici, moi je fais venir sur vous l’épée, et je détruirai vos hauts lieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Et vos autels seront dévastés, et vos colonnes consacrées au soleil seront brisées; et je ferai tomber vos blessés à mort devant vos idoles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'et je mettrai les cadavres des fils d’Israël devant leurs idoles, et je disperserai vos ossements autour de vos autels.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Dans toutes vos demeures les villes seront réduites en solitudes et les hauts lieux seront désolés, afin que vos autels soient délaissés et désolés, et que vos idoles soient brisées et ne soient plus, et que vos colonnes consacrées au soleil soient abattues, et vos ouvrages anéantis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Et les blessés à mort tomberont au milieu de vous; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Mais je laisserai un reste, en ce que vous aurez des réchappés de l’épée parmi les nations, quand vous serez dispersés dans les pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Et vos réchappés se souviendront de moi parmi les nations où ils auront été emmenés captifs, quand j’aurai brisé leur cœur prostitué qui s’est détourné de moi, et leurs yeux qui se prostituent après leurs idoles; et ils auront horreur d’eux-mêmes à cause des iniquités qu’ils ont commises par toutes leurs abominations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'et ils sauront que moi, l’ Éternel, je n’ai pas dit en vain que je leur ferais ce mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Ainsi dit le Seigneur, l’ Éternel: Bats de tes mains, et frappe de ton pied, et dis: Hélas, pour toutes les abominations des iniquités de la maison d’Israël! car ils tomberont par l’épée, par la famine et par la peste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Celui qui est loin mourra par la peste, et celui qui est près tombera par l’épée; et celui qui est demeuré de reste, et qui est assiégé, mourra par la famine; et je consommerai ma fureur sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Et vous saurez que je suis l’ Éternel, quand leurs blessés à mort seront au milieu de leurs idoles, autour de leurs autels, sur toute haute colline, sur tous les sommets des montagnes, et sous tout arbre vert, et sous tout térébinthe touffu, dans les lieux où ils offraient à toutes leurs idoles des parfums agréables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Et j’étendrai ma main sur eux, et je ferai du pays une désolation et il sera plus désolé que le désert de Dibla, dans toutes leurs demeures; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Et toi, fils d’homme! Ainsi dit le Seigneur, l’ Éternel, à la terre d’Israël: Une fin!... la fin vient sur les quatre coins du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Maintenant la fin [vient] sur toi, et j’enverrai sur toi ma colère, et je te jugerai selon tes voies, et je mettrai sur toi toutes tes abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Et mon œil n’aura point compassion de toi, et je n’épargnerai pas; mais je mettrai tes voies sur toi, et tes abominations seront au milieu de toi; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Ainsi dit le Seigneur, l’ Éternel: Un mal, un mal unique! Voici, il est venu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'La fin est venue, la fin est venue! Elle se réveille contre toi; voici, elle vient!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Ton destin est venu sur toi, habitant du pays; le temps est venu, le jour est proche, – le trouble, et non le cri joyeux des montagnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Maintenant, bientôt, je verserai sur toi ma fureur, et je consommerai ma colère contre toi, et je te jugerai selon tes voies, et je mettrai sur toi toutes tes abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Et mon œil n’aura point compassion, et je ne t’épargnerai pas; je te rendrai selon tes voies, et tes abominations seront au milieu de toi; et vous saurez que c’est moi, l’ Éternel, qui frappe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Voici le jour, voici, il est arrivé! Le destin a germé, la verge a fleuri, la fierté s’est épanouie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'La violence s’élève pour être une verge de méchanceté. [Il ne reste] rien d’eux, ni de leur foule bruyante, ni de leur abondance de biens, ni de la magnificence au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Le temps est venu, le jour s’est approché; que celui qui achète ne se réjouisse pas, et que celui qui vend ne mène pas deuil; car il y a une ardente colère sur toute sa foule bruyante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Car celui qui vend ne rentrera pas en possession de ce qui a été vendu, serait-il même encore en vie parmi les vivants; car la vision est touchant toute sa foule bruyante, elle ne sera point révoquée, et personne par son iniquité ne fortifiera sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Ils ont sonné de la trompette et ont tout préparé; mais personne ne marche au combat, parce que l’ardeur de ma colère est sur toute sa foule bruyante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'L’épée est au-dehors, et la peste et la famine sont au-dedans: celui qui est aux champs mourra par l’épée; et celui qui est dans la ville, la famine et la peste le dévoreront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Et leurs réchappés échapperont, et seront sur les montagnes comme les colombes des vallées, tous gémissant, chacun pour son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Toutes les mains deviendront lâches, et tous les genoux se fondront en eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Ils se ceindront de sacs, et le frisson les couvrira; la honte sera sur tous les visages, et toutes leurs têtes seront chauves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Ils jetteront leur argent dans les rues, et leur or sera [rejeté] comme une impureté; leur argent ni leur or ne pourra les délivrer au jour de la fureur de l’ Éternel; ils ne rassasieront pas leurs âmes, et ne rempliront pas leurs entrailles, car c’est ce qui a été la pierre d’achoppement de leur iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Et de la beauté de son ornement il a fait sa gloire; mais ils y ont fait des images de leurs abominations [et] de leurs choses exécrables. C’est pourquoi j’en ai fait pour eux une impureté abjecte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'et je l’ai livrée en pillage aux mains des étrangers, et pour butin aux méchants de la terre, et ils la profaneront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Et je détournerai d’eux ma face; et ils profaneront mon lieu secret; et les violents y entreront et le profaneront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Fabrique la chaîne; car le pays est plein de coulpe de sang, et la ville est pleine de violence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Et je ferai venir les iniques des nations, et ils posséderont leurs maisons; et je ferai cesser l’orgueil des forts, et leurs sanctuaires seront profanés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'La destruction vient; et ils chercheront la paix, mais il n’y en aura point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Il viendra calamité sur calamité, et il y aura rumeur sur rumeur, et ils chercheront [quelque] vision de la part d’un prophète; mais la loi est périe de chez le sacrificateur, et le conseil, de chez les anciens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Le roi mènera deuil, et les princes seront vêtus de stupeur, et les mains du peuple du pays trembleront: je leur ferai selon leur voie, et je les jugerai par leurs propres jugements; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, '*Et il arriva, en la sixième année, au sixième [mois], le cinquième [jour] du mois, qu’étant assis dans ma maison, et les anciens de Juda étant assis devant moi, la main du Seigneur, l’ Éternel, tomba là sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Et je vis, et voici une ressemblance comme l’aspect d’un feu: depuis l’aspect de ses reins vers le bas, c’était du feu; et depuis ses reins vers le haut, c’était comme l’aspect d’une splendeur, comme l’apparence de l’airain luisant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Et il étendit la forme d’une main, et me prit par les boucles de ma tête; et l’Esprit m’éleva entre la terre et les cieux, et m’emmena à Jérusalem, dans les visions de Dieu, à l’entrée de la porte intérieure qui regarde vers le nord, où était le siège de l’idole de jalousie qui provoque à la jalousie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Et voici, là était la gloire du Dieu d’Israël, selon la vision que j’avais vue dans la vallée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Et il me dit: Fils d’homme, lève tes yeux vers le nord. Et je levai mes yeux vers le nord; et voici, au nord de la porte de l’autel, cette idole de jalousie, à l’entrée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Et il me dit: Fils d’homme, vois-tu ce qu’ils font, les grandes abominations que la maison d’Israël commet ici, pour m’éloigner de mon sanctuaire? Et tu verras encore de grandes abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Et il me mena à l’entrée du parvis; et je regardai, et voici, un trou dans le mur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Et il me dit: Fils d’homme, perce le mur. Et je perçai le mur, et voici, une porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Et il me dit: Entre, et regarde les mauvaises abominations qu’ils commettent ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Et j’entrai, et je regardai; et voici toute [sorte] de figures de reptiles, et de bêtes exécrables, et toutes les idoles de la maison d’Israël tracées sur le mur, tout autour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'et 70 hommes d’entre les anciens de la maison d’Israël se tenaient devant elles, et au milieu d’eux se tenait Jaazania, fils de Shaphan: chacun avait son encensoir dans sa main, et il montait une épaisse nuée d’encens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Et il me dit: As-tu vu, fils d’homme, ce que les anciens de la maison d’Israël font dans les ténèbres, chacun dans leurs cabinets d’images? Car ils disent: L’ Éternel ne nous voit pas, l’ Éternel a abandonné le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Et il me dit: Tu verras encore de grandes abominations qu’ils commettent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Puis il me mena à l’entrée de la porte de la maison de l’ Éternel, qui est vers le nord; et voici des femmes assises là, pleurant Thammuz.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Et il me dit: As-tu vu, fils d’homme? Tu verras encore des abominations plus grandes que celles-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Puis il me fit entrer au parvis intérieur de la maison de l’ Éternel; et voici, à l’entrée du temple de l’ Éternel, entre le portique et l’autel, environ 25 hommes, le dos tourné vers le temple de l’ Éternel, et leurs faces vers l’orient; et ils se prosternaient vers l’orient devant le soleil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Et il me dit: As-tu vu, fils d’homme? Est-ce une chose légère à la maison de Juda de commettre les abominations qu’ils commettent ici, pour qu’ils remplissent encore le pays de violence, et qu’ils me provoquent à colère [toujours] de nouveau? Et voici, ils mettent le rameau à leur nez!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Et moi aussi, j’agirai avec fureur; mon œil n’aura point compassion, et je n’épargnerai pas; et quand ils crieront à mes oreilles à haute voix, je ne les écouterai point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Et il cria à mes oreilles à haute voix, disant: Approchez, vous qui avez la charge de la ville, et chacun avec son instrument de destruction dans sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Et voici six hommes qui venaient du chemin de la porte supérieure qui est tournée vers le nord, et chacun avec son instrument de mort dans sa main; et il y avait au milieu d’eux un homme vêtu de lin, avec un encrier d’écrivain à ses reins; et ils entrèrent, et se tinrent à côté de l’autel d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Et la gloire du Dieu d’Israël s’éleva de dessus le chérubin sur lequel elle était, [et vint] sur le seuil de la maison; et il cria à l’homme vêtu de lin, qui avait l’encrier d’écrivain à ses reins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'et l’ Éternel lui dit: Passe au milieu de la ville, au milieu de Jérusalem, et fais une marque sur les fronts des hommes qui soupirent et gémissent à cause de toutes les abominations qui se commettent au-dedans d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Et à ceux-là il dit, à mes oreilles: Passez par la ville après lui, et frappez; que votre œil n’ait point compassion, et n’épargnez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Tuez, détruisez vieillards, jeunes hommes, et vierges, et petits enfants, et femmes; mais n’approchez d’aucun de ceux qui ont sur eux la marque, et commencez par mon sanctuaire. Et ils commencèrent par les anciens qui étaient devant la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Et il leur dit: Rendez impure la maison, et remplissez les parvis de tués; sortez! Et ils sortirent et frappèrent dans la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Et il arriva que, comme ils frappaient et que moi je demeurais de reste, je tombai sur ma face, et je criai et dis: Ah, Seigneur Éternel! veux-tu détruire tout le reste d’Israël en versant ta fureur sur Jérusalem?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Et il me dit: L’iniquité de la maison d’Israël et de Juda est excessivement grande, et le pays est rempli de sang, et la ville est remplie d’injustices; car ils ont dit: L’ Éternel a abandonné le pays, et l’ Éternel ne voit pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Et moi aussi, – mon œil n’aura point compassion, et je n’épargnerai pas; je ferai retomber leur voie sur leur tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Et voici, l’homme vêtu de lin, qui avait l’encrier à ses reins, rapporta, disant: J’ai fait comme tu m’as commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Et je regardai, et voici, sur l’étendue, qui était au-dessus de la tête des chérubins, parut comme une pierre de saphir, comme l’aspect de la ressemblance d’un trône, au-dessus d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Et il parla à l’homme vêtu de lin, et dit: Viens entre les roues, au-dessous du chérubin, et remplis le creux de tes mains de charbons de feu pris d’entre les chérubins, et répands-les sur la ville. Et il entra, devant mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Et les chérubins se tenaient à droite de la maison lorsque l’homme entra, et la nuée remplissait le parvis intérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Et la gloire de l’ Éternel s’éleva de dessus le chérubin, [et vint] sur le seuil de la maison; et la maison fut remplie de la nuée, et le parvis fut rempli de la splendeur de la gloire de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Et le bruit des ailes des chérubins s’entendit jusqu’au parvis extérieur, comme la voix du ✶Dieu Tout-puissant quand il parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Et il arriva que, lorsqu’il eut commandé à l’homme vêtu de lin, disant: Prends du feu d’entre les roues, d’entre les chérubins, il entra et se tint à côté de la roue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Et le chérubin étendit sa main entre les chérubins, vers le feu qui était entre les chérubins, et il [en] prit, et le mit dans le creux des mains de l’[homme] vêtu de lin; et il le prit et sortit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Et on voyait aux chérubins la figure d’une main d’homme sous leurs ailes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Et je regardai, et voici, quatre roues à côté des chérubins, une roue à côté d’un chérubin, et une roue à côté d’un chérubin, et l’aspect des roues était comme l’apparence d’une pierre de chrysolithe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Et quant à leur aspect, elles avaient les quatre une seule ressemblance, comme si une roue était au milieu d’une roue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Quand elles allaient, elles allaient sur leurs quatre côtés; elles ne se tournaient pas, quand elles allaient; mais, vers le lieu où la tête regardait, elles allaient après elle: elles ne se tournaient pas quand elles allaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Et tout leur corps, et leur dos, et leurs mains, et leurs ailes, et les roues, étaient pleins d’yeux tout autour, – à eux quatre, leurs roues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Quant aux roues, on leur cria, moi l’entendant: Roue!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Et chacun avait quatre faces: la première face était la face d’un chérubin, et la seconde face était la face d’un homme, et la troisième était la face d’un lion, et la quatrième, la face d’un aigle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Et les chérubins s’élevèrent. C’était là l’animal que j’avais vu près du fleuve Kebar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Et quand les chérubins allaient, les roues allaient à côté d’eux; et quand les chérubins levaient leurs ailes pour s’élever de dessus terre, les roues aussi ne se détournaient point d’à côté d’eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'quand ils s’arrêtaient, elles s’arrêtaient, et quand ils s’élevaient, elles s’élevaient avec eux, car l’esprit de l’animal était en elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Et la gloire de l’ Éternel sortit de dessus le seuil de la maison, et se tint au-dessus des chérubins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Et les chérubins haussèrent leurs ailes et s’élevèrent de terre à mes yeux, quand ils sortirent; et les roues étaient auprès d’eux. Et ils s’arrêtèrent à l’entrée de la porte orientale de la maison de l’ Éternel; et la gloire du Dieu d’Israël était au-dessus d’eux, en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'C’était là l’animal que j’avais vu au-dessous du Dieu d’Israël, près du fleuve Kebar; et je connus que c’étaient des chérubins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Chacun avait quatre faces, et chacun, quatre ailes, et il y avait une ressemblance de mains d’homme sous leurs ailes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Et quant à la ressemblance de leurs faces, c’étaient les faces que j’avais vues près du fleuve Kebar, leur aspect, et eux-mêmes; ils allaient chacun droit devant soi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Et l’Esprit m’éleva et me transporta à la porte orientale de la maison de l’ Éternel qui regarde vers l’orient; et voici, à l’entrée de la porte, 25 hommes; et je vis au milieu d’eux Jaazania, fils d’Azzur, et Pelatia, fils de Benaïa, princes du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Et il me dit: Fils d’homme, ce sont ici les hommes qui méditent l’iniquité et qui donnent de mauvais conseils dans cette ville,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'qui disent: Ce n’est pas le moment de bâtir des maisons; elle est la marmite, et nous sommes la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'C’est pourquoi prophétise contre eux, prophétise, fils d’homme!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Et l’Esprit de l’ Éternel tomba sur moi et me dit: Parle: Ainsi dit l’ Éternel: Vous dites ainsi, maison d’Israël; et je connais ce qui monte dans votre esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Vous avez multiplié le nombre de vos tués dans cette ville, et vous avez rempli ses rues de tués.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Vos tués, que vous avez mis au milieu d’elle, c’est la chair, et elle, c’est la marmite; mais vous, je vous ferai sortir du milieu d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Vous avez eu peur de l’épée; et je ferai venir l’épée sur vous, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Et je vous ferai sortir du milieu d’elle, et je vous livrerai en la main des étrangers, et j’exécuterai des jugements contre vous:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'vous tomberez par l’épée; dans les confins d’Israël je vous jugerai, et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Elle ne sera pas pour vous une marmite, et vous ne serez pas la chair au milieu d’elle; je vous jugerai dans les confins d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'et vous saurez que je suis l’ Éternel, dans les statuts duquel vous n’avez point marché, et dont vous n’avez point pratiqué les ordonnances; mais vous avez agi selon les droits établis des nations qui sont autour de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Et il arriva, comme je prophétisais, que Pelatia, fils de Benaïa, mourut; et je tombai sur ma face, et je criai à haute voix, et je dis: Ah, Seigneur Éternel! veux-tu détruire entièrement le reste d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Fils d’homme, tes frères, tes frères, les hommes de ta parenté, et toute la maison d’Israël, eux tous, sont ceux auxquels les habitants de Jérusalem disent: Éloignez-vous de l’ Éternel, ce pays nous est donné en possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'C’est pourquoi dis: Ainsi dit le Seigneur, l’ Éternel: Bien que je les aie éloignés parmi les nations, et bien que je les aie dispersés par les pays, toutefois je leur serai comme un petit sanctuaire dans les pays où ils sont venus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'C’est pourquoi dis: Ainsi dit le Seigneur, l’ Éternel: Aussi je vous rassemblerai d’entre les peuples, et je vous recueillerai des pays où vous êtes dispersés, et je vous donnerai la terre d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Et là ils viendront, et ils en ôteront toutes ses choses exécrables et toutes ses abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Et je leur donnerai un seul cœur, et je mettrai au-dedans de vous un esprit nouveau; et j’ôterai de leur chair le cœur de pierre, et je leur donnerai un cœur de chair, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'afin qu’ils marchent dans mes statuts, et qu’ils gardent mes ordonnances et les pratiquent; et ils seront mon peuple, et moi je serai leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Mais quant à ceux dont le cœur marche au gré de leurs choses exécrables et de leurs abominations, je ferai retomber leur voie sur leur tête, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Et les chérubins levèrent leurs ailes, et les roues étaient auprès d’eux; et la gloire du Dieu d’Israël était au-dessus d’eux, en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Et la gloire de l’ Éternel monta du milieu de la ville, et se tint sur la montagne qui est à l’orient de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Et l’Esprit m’éleva et me transporta en Chaldée, vers ceux de la transportation, en vision, par l’Esprit de Dieu; et la vision que j’avais vue monta d’auprès de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Et je dis à ceux de la transportation toutes les choses que l’ Éternel m’avait fait voir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, '**Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Fils d’homme, tu demeures au milieu d’une maison rebelle; ils ont des yeux pour voir, et ne voient pas; ils ont des oreilles pour entendre, et n’entendent pas; car ils sont une maison rebelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Et toi, fils d’homme, fais-toi un bagage de transporté, et va captif, de jour, sous leurs yeux; va captif, de ton lieu vers un autre lieu, sous leurs yeux; peut-être verront-ils, car ils sont une maison rebelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Et, de jour, tu mettras dehors ton bagage, comme un bagage de transporté, sous leurs yeux; et toi, tu sortiras sur le soir, devant leurs yeux, comme ceux qui s’en vont en captivité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Perce le mur sous leurs yeux, et mets dehors par là [ton bagage];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'tu le porteras sur l’épaule, sous leurs yeux; tu le mettras dehors dans l’obscurité; tu couvriras ta face, et tu ne verras pas le pays, car je t’ai donné pour signe à la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Et je fis comme il m’avait été commandé: je sortis de jour mon bagage, comme un bagage de transporté, et, sur le soir, je perçai le mur avec la main: je le mis dehors dans l’obscurité, je le portai sur l’épaule, sous leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Et la parole de l’ Éternel vint à moi, le matin, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Fils d’homme, la maison d’Israël, la maison rebelle, ne t’a-t-elle pas dit: Que fais-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Dis-leur: Ainsi dit le Seigneur, l’ Éternel: Cet oracle [concerne] le prince qui est dans Jérusalem, et toute la maison d’Israël qui est au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Dis: Je suis pour vous un signe; comme j’ai fait, ainsi il leur sera fait: ils iront en exil [et] en captivité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Et le prince qui est au milieu d’eux portera [son bagage] sur l’épaule, dans l’obscurité, et sortira; on percera le mur pour le faire sortir par là; il couvrira sa face, afin qu’il ne voie pas de ses yeux le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Et j’étendrai sur lui mon filet, et il sera pris dans mon piège; et je l’amènerai à Babylone, dans le pays des Chaldéens; mais il ne le verra point, et là il mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Et tout ce qui l’entoure, son secours, et toutes ses troupes, je les disperserai à tout vent; et je tirerai l’épée après eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Et ils sauront que je suis l’ Éternel, quand je les aurai dispersés parmi les nations et que je les aurai disséminés dans les pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Et je laisserai de reste d’entre eux quelque peu de gens [sauvés] de l’épée, de la famine et de la peste, afin qu’ils racontent toutes leurs abominations parmi les nations où ils seront venus. Et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Fils d’homme, mange ton pain dans le trouble, et bois ton eau avec tremblement et dans l’inquiétude;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'et dis au peuple du pays: Ainsi dit le Seigneur, l’ Éternel, touchant les habitants de Jérusalem, sur la terre d’Israël: Ils mangeront leur pain avec inquiétude et ils boiront leur eau avec stupeur, parce que leur pays sera désolé, [vide] de tout ce qu’il contient, à cause de la violence de tous ceux qui l’habitent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'et les villes habitées seront rendues désertes, et le pays sera une désolation; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Fils d’homme, quel est ce proverbe que vous avez dans la terre d’Israël, disant: Les jours seront prolongés, et toute vision a péri?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'C’est pourquoi dis-leur: Ainsi dit le Seigneur, l’ Éternel: Je ferai cesser ce proverbe, et on ne s’en servira plus comme proverbe en Israël; mais dis-leur: Les jours se sont approchés, et l’accomplissement de chaque vision;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'car il n’y aura plus aucune vision vaine, ni divination flatteuse, au milieu de la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Car moi, je suis l’ Éternel; je parlerai, et la parole que j’aurai dite sera exécutée, elle ne sera plus différée; car en vos jours, maison rebelle, je dirai une parole et je l’exécuterai, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Fils d’homme, voici, la maison d’Israël dit: La vision que celui-ci voit est pour des jours lointains, et il prophétise pour des temps éloignés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'C’est pourquoi dis-leur: Ainsi dit le Seigneur, l’ Éternel: Aucune de mes paroles ne sera plus différée; la parole que j’aurai dite sera exécutée, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Fils d’homme, prophétise contre les prophètes d’Israël qui prophétisent, et dis à ceux qui prophétisent d’après leur propre cœur: Écoutez la parole de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Ainsi dit le Seigneur, l’ Éternel: Malheur aux prophètes insensés qui suivent leur propre esprit et n’ont rien vu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Israël, tes prophètes ont été comme des renards dans les lieux déserts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Vous n’êtes point montés aux brèches, et vous n’avez pas fermé l’enceinte pour la maison d’Israël, afin de tenir ferme dans la bataille, au jour de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Ils ont eu des visions de vanité et de divination de mensonge, ceux qui disent: L’ Éternel a dit! et l’ Éternel ne les a pas envoyés; et ils font espérer que la parole dite sera accomplie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'N’avez-vous pas vu des visions de vanité et prononcé des divinations de mensonge, quand vous dites: L’ Éternel a dit! – et je n’ai point parlé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Parce que vous dites des choses vaines, et que vous avez eu des visions de mensonge, à cause de cela, voici, je suis contre vous, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Et ma main sera sur les prophètes qui ont des visions de vanité et qui devinent le mensonge: ils ne seront pas dans l’assemblée de mon peuple, et ils ne seront pas écrits dans le registre de la maison d’Israël, et ils n’entreront pas dans la terre d’Israël; et vous saurez que je suis le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Parce que, oui, parce qu’ils égarent mon peuple, disant: Paix! et il n’y a point de paix; et que, si celui-ci bâtit un mur, ceux-là l’enduisent de mauvais mortier,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'dis à ceux qui enduisent le mur de mauvais mortier, qu’il s’écroulera: il y aura une pluie torrentielle; et vous, pierres de grêle, vous tomberez, et un vent de tempête éclatera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Et voici, quand le mur s’écroulera, ne vous sera-t-il pas dit: Où est l’enduit dont vous l’avez enduit?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Je ferai éclater, dans ma fureur, un vent de tempête; et, dans ma colère, il y aura une pluie torrentielle, et, dans ma fureur, des pierres de grêle, pour détruire entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Et je renverserai le mur que vous avez enduit de mauvais mortier, et je le jetterai par terre, et ses fondements seront découverts, et il croulera, et vous périrez au milieu de ses ruines; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Et je consommerai ma fureur contre ce mur et contre ceux qui l’enduisent de mauvais mortier; et je vous dirai: Le mur n’est plus, ni ceux qui l’enduisaient,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'les prophètes d’Israël qui prophétisent touchant Jérusalem, et qui voient pour elle une vision de paix, et il n’y a point de paix, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Et toi, fils d’homme, tourne ta face contre les filles de ton peuple qui prophétisent d’après leur propre cœur, et prophétise contre elles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'et dis: Ainsi dit le Seigneur, l’ Éternel: Malheur à celles qui cousent des coussinets pour toutes les jointures des mains, et qui font des voiles pour la tête [des gens] de toute taille, afin de prendre au piège des âmes! Voulez-vous prendre au piège les âmes de mon peuple et vous conserver la vie à vous-mêmes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Et me profaneriez-vous auprès de mon peuple pour des poignées d’orge et pour des morceaux de pain, afin de faire mourir les âmes qui ne devaient pas mourir, et pour faire vivre les âmes qui ne devaient pas vivre, en mentant à mon peuple qui écoute le mensonge?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Voici, j’en veux à vos coussinets pour que les âmes, que par eux vous prenez au piège, s’envolent; et je les arracherai de dessus vos bras, et je ferai échapper les âmes que vous prenez au piège, les âmes,... afin qu’elles s’envolent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'et je déchirerai vos voiles, et je délivrerai mon peuple de vos mains, et ils ne seront plus en vos mains pour les prendre au piège; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Parce que vous avez chagriné par la fausseté le cœur du juste, que moi je n’ai pas attristé, et parce que vous avez fortifié les mains du méchant, pour qu’il ne se détourne pas de ses mauvaises voies afin de sauver sa vie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'à cause de cela, vous n’aurez plus de visions de vanité et vous ne pratiquerez plus la divination; et je délivrerai mon peuple de vos mains, et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, '*Et des hommes d’entre les anciens d’Israël vinrent vers moi, et s’assirent devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Fils d’homme, ces hommes ont élevé leurs idoles dans leurs cœurs et ont placé devant leur face la pierre d’achoppement de leur iniquité. Serais-je consulté par eux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'C’est pourquoi parle-leur, et dis-leur: Ainsi dit le Seigneur, l’ Éternel: Quiconque, de la maison d’Israël, aura élevé ses idoles dans son cœur et aura placé devant sa face la pierre d’achoppement de son iniquité, et viendra vers le prophète, – moi, l’ Éternel, je lui répondrai selon ceci, selon la multitude de ses idoles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'afin de prendre la maison d’Israël par leur propre cœur, car ils se sont tous séparés de moi par leurs idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'C’est pourquoi, dis à la maison d’Israël: Ainsi dit le Seigneur, l’ Éternel: Revenez, détournez-vous de vos idoles, et détournez vos faces de toutes vos abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Car quiconque, de la maison d’Israël ou des étrangers qui séjournent en Israël, se sépare de moi, et élève ses idoles dans son cœur et place la pierre d’achoppement de son iniquité devant sa face, et viendra vers le prophète pour me consulter par lui, – moi, l’ Éternel, je lui répondrai par moi-même;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'et je mettrai ma face contre cet homme et je le rendrai désolé de telle sorte qu’il sera en signe et en proverbe, et je le retrancherai du milieu de mon peuple; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Et si le prophète est séduit, et qu’il profère une parole, moi l’ Éternel, j’ai séduit ce prophète; et j’étendrai ma main sur lui, et je le détruirai du milieu de mon peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Et ils porteront leur iniquité: la peine de l’iniquité du prophète sera comme la peine de l’iniquité de celui qui consulte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'afin que la maison d’Israël ne s’égare plus d’auprès de moi, et qu’ils ne se rendent plus impurs par toutes leurs transgressions. Et ils seront mon peuple, et moi je serai leur Dieu, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Fils d’homme, si un pays pèche contre moi en commettant une infidélité, et que j’étende ma main sur lui, et que je lui brise le bâton du pain, et y envoie la famine, et retranche du milieu de lui les hommes et les bêtes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'et que ces trois hommes, Noé, Daniel et Job, soient au milieu de lui, ceux-ci délivreraient leurs âmes par leur justice, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Si je fais passer les bêtes mauvaises par le pays, et qu’elles le dépeuplent, et qu’il soit devenu une désolation en sorte que personne n’y passe à cause de ces bêtes, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'ces trois hommes seraient-ils au milieu de lui, je suis vivant, dit le Seigneur, l’ Éternel, s’ils délivraient fils ou filles! eux seuls seraient délivrés, et le pays sera une désolation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Ou, [si] je fais venir l’épée sur ce pays-là, et que je dise: Épée, passe par le pays; et que je retranche du milieu de lui les hommes et les bêtes, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'ces trois hommes seraient-ils au milieu de lui, je suis vivant, dit le Seigneur, l’ Éternel, ils ne délivreraient ni fils ni filles! mais eux seuls seraient délivrés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Ou, [si] j’envoie la peste sur ce pays-là, et que je verse ma fureur sur lui en [faisant couler le] sang, pour retrancher du milieu de lui les hommes et les bêtes, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Noé, Daniel et Job, seraient-ils au milieu de lui, je suis vivant, dit le Seigneur, l’ Éternel, s’ils délivraient fils ou filles! eux [seulement], par leur justice, délivreraient leurs âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Car ainsi dit le Seigneur, l’ Éternel: Combien plus si j’envoie mes quatre jugements désastreux, l’épée, et la famine, et les bêtes mauvaises, et la peste, contre Jérusalem, pour en retrancher les hommes et les bêtes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Mais voici, il y aura en elle un reste réchappé de gens qui en sortiront, des fils et des filles; voici, ils sortiront vers vous, et vous verrez leur voie et leurs actions, et vous vous consolerez du mal que j’ai fait venir sur Jérusalem, de tout ce que j’ai fait venir sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Et ils vous consoleront, car vous verrez leur voie et leurs actions; et vous saurez que ce n’est pas sans raison que j’ai fait tout ce que j’ai fait en elle, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Fils d’homme, le bois de la vigne, que vaut-il plus que tout [autre] bois, le sarment qui est parmi les arbres de la forêt?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'En prendra-t-on du bois pour en faire quelque ouvrage, ou en prendra-t-on une cheville pour y suspendre quelque ustensile?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Voici, on le met au feu pour être consumé; le feu en consume les deux bouts, et le milieu est brûlé. Serait-il propre à un ouvrage?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Voici, quand il était entier, on n’en a fait aucun ouvrage; combien moins, quand le feu l’aura consumé et qu’il sera brûlé, en fera-t-on encore un ouvrage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Comme le bois de la vigne parmi les arbres de la forêt, que j’ai livré au feu pour être consumé, ainsi je livrerai les habitants de Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'et je mettrai ma face contre eux: ils sortiront d’un feu, et un [autre] feu les consumera; et vous saurez que je suis l’ Éternel, quand j’aurai mis ma face contre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Et je ferai du pays une désolation, parce qu’ils ont commis le péché, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Fils d’homme, fais connaître à Jérusalem ses abominations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'et dis: Ainsi dit le Seigneur, l’ Éternel, à Jérusalem: Ton origine et ta naissance sont du pays des Cananéens; ton père était un Amoréen, et ta mère une Héthienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Et, quant à ta naissance, le jour où tu naquis ton nombril ne fut pas coupé; et tu ne fus pas lavée dans l’eau pour être nettoyée; et tu ne fus pas frottée avec du sel, et tu ne fus pas emmaillotée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Aucun œil n’eut pitié de toi pour te faire une seule de ces choses, pour avoir compassion de toi; mais tu fus jetée sur la face des champs, à cause de l’horreur qu’on avait de toi, le jour où tu naquis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Et je passai près de toi, et je te vis gisante dans ton sang, et je te dis, dans ton sang: Vis! et je te dis, dans ton sang: Vis!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Je t’ai multipliée comme le germe des champs; et tu pris ta croissance, et tu devins grande, et tu parvins au comble de la beauté; tes seins se formèrent, et ta chevelure se développa; mais tu étais nue et découverte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Et je passai près de toi, et je te vis, et voici, ton âge était l’âge des amours; et j’étendis sur toi le pan de ma robe, et je couvris ta nudité; et je te jurai, et j’entrai en alliance avec toi, dit le Seigneur, l’ Éternel; et tu fus à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Et je te lavai dans l’eau, et je lavai à grande eau ton sang de dessus toi, et je t’oignis d’huile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'et je te vêtis de broderie, et je te chaussai de [peau de] taisson, et je te ceignis de lin blanc, et je te couvris de soie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'et je te parai d’ornements, et je mis des bracelets à tes mains et un collier à ton cou;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'et je mis un anneau à ton nez et des pendants à tes oreilles, et une couronne de beauté sur ta tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Et tu fus parée d’or et d’argent, et ton vêtement était de lin blanc, et de soie, et de broderie. Tu mangeas de la fleur de farine, et du miel, et de l’huile. Et tu devins extrêmement belle, et tu prospéras jusqu’à être un royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Et ta renommée se répandit parmi les nations à cause de ta beauté, car elle était parfaite par ma magnificence que j’avais mise sur toi, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Mais tu te confias en ta beauté, et tu te prostituas à cause de ta renommée, et tu prodiguas tes prostitutions à tout passant: c’était pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Et tu pris de tes vêtements, et tu te fis des hauts lieux de diverses couleurs, et tu t’y prostituas, ce qui n’était jamais arrivé, et ne sera plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Et tu pris tes objets de parure, [faits] de mon or et de mon argent que je t’avais donnés, et tu t’en fis des images d’un mâle, et tu te prostituas avec elles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'et tu pris tes vêtements de broderie, et tu les en couvris, et tu mis devant elles mon huile et mon encens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'et mon pain que je t’avais donné, la fleur de farine, et l’huile, et le miel, dont je te nourrissais, tu les mis devant elles, en odeur agréable. Il en a été ainsi, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Et tu pris tes fils et tes filles que tu m’avais enfantés, et tu les leur offris en sacrifice pour qu’ils les dévorent. Était-ce trop peu que ta prostitution?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Tu égorgeas mes fils, et tu les livras, en les leur consacrant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Et avec toutes tes abominations et tes prostitutions, tu ne t’es pas souvenue des jours de ta jeunesse, quand tu étais nue et découverte, gisante dans ton sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Et il arriva, après toutes tes iniquités, – malheur, malheur à toi, dit le Seigneur, l’ Éternel, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'que tu t’es bâti un lieu de débauche et que tu t’es fait un haut lieu dans toutes les places:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'au bout de chaque chemin tu as bâti ton haut lieu, et tu as rendu ta beauté abominable, et tu t’es découverte à tout passant, et tu as multiplié tes prostitutions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Et tu as commis fornication avec les fils de l’Égypte, tes voisins, au corps vigoureux; et tu as multiplié tes prostitutions pour me provoquer à colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Et voici, j’ai étendu ma main sur toi, et j’ai diminué ce qui t’était assigné, et je t’ai livrée à la volonté de celles qui te haïssent, les filles des Philistins, qui ont honte de tes voies d’infamie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Et tu as commis fornication avec les fils d’Assur, parce que tu ne pouvais être rassasiée; tu as commis fornication avec eux, et même tu n’as pas été rassasiée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Et tu as multiplié tes prostitutions avec un pays de marchands, la Chaldée, et même avec cela tu n’as pas été rassasiée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Oh! que ton cœur est faible, dit le Seigneur, l’ Éternel, que tu aies fait toutes ces choses, l’œuvre d’une prostituée éhontée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'te bâtissant ton lieu de débauche au bout de chaque chemin; et tu as établi ton haut lieu dans toutes les places. Et tu n’es pas comme une prostituée, en ce que tu dédaignes le salaire:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'femme qui commets l’adultère, tu prends des étrangers à la place de ton mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'On fait des cadeaux à toutes les prostituées; mais toi, tu fais tes cadeaux à tous tes amants, et tu les engages par des présents à venir vers toi de tous côtés, pour tes prostitutions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Et il arrive chez toi, dans tes prostitutions, le contraire de [ce qui se voit] chez les femmes: on ne te suit pas pour commettre fornication; et, en ce que tu donnes des présents et qu’on ne te donne pas de présents, tu fais le contraire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'C’est pourquoi, prostituée, écoute la parole de l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Ainsi dit le Seigneur, l’ Éternel: Parce que ton argent a été dissipé, et que ta nudité a été découverte à tes amants par tes prostitutions, et à toutes les idoles de tes abominations, et à cause du sang de tes fils que tu leur as livrés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'à cause de cela, voici, je rassemble tous tes amants avec lesquels tu te plaisais, et tous ceux que tu as aimés, avec tous ceux que tu as haïs; et je les rassemblerai de toutes parts contre toi, et je leur découvrirai ta nudité, et ils verront toute ta nudité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Et je te jugerai du jugement des femmes adultères et de celles qui versent le sang, et je te livrerai au sang de la fureur et de la jalousie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'et je te livrerai entre leurs mains, et ils abattront ton lieu de débauche et démoliront tes hauts lieux; et ils te dépouilleront de tes vêtements, et prendront tes objets de parure, et te laisseront nue et découverte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Et on fera monter contre toi un rassemblement [d’hommes], et ils te lapideront avec des pierres, et te transperceront avec leurs épées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'et ils brûleront tes maisons par le feu, et exécuteront sur toi des jugements aux yeux de beaucoup de femmes. Et je te ferai cesser de commettre fornication, et, des présents aussi, tu n’en donneras plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Et je satisferai ma fureur sur toi, et ma jalousie se retirera de toi; et je me tiendrai tranquille, et je ne me courroucerai plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Parce que tu ne t’es pas souvenue des jours de ta jeunesse, et que tu m’as irrité par toutes ces choses, voici, moi aussi je fais retomber ta voie sur ta tête, dit le Seigneur, l’ Éternel; et tu ne commettras pas l’infamie par-dessus toutes tes abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Voici, tous ceux qui font des proverbes feront un proverbe sur toi, disant: Telle mère, telle fille!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Tu es la fille de ta mère qui avait en horreur son mari et ses enfants; et tu es la sœur de tes sœurs qui avaient en horreur leurs maris et leurs enfants. Votre mère était une Héthienne, et votre père était un Amoréen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Et ta sœur, l’aînée, c’est Samarie qui demeure à ta gauche, elle et ses filles; et ta jeune sœur qui demeure à ta droite, c’est Sodome et ses filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Mais tu n’as pas marché dans leurs voies, et tu n’as pas fait selon leurs abominations; mais, comme si c’était bien peu, tu t’es corrompue dans toutes tes voies plus qu’elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Je suis vivant, dit le Seigneur, l’ Éternel, que Sodome ta sœur, elle et ses filles, n’a pas fait comme tu as fait, toi et tes filles!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Voici, c’est ici l’iniquité de ta sœur Sodome: orgueil, abondance de pain et insouciant repos, elle les a possédés, elle et ses filles; mais elle n’a pas fortifié la main de l’affligé et du pauvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Elles se sont élevées et ont commis des abominations devant moi; et je les ai ôtées lorsque je l’ai vu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Et Samarie n’a pas péché selon la moitié de tes péchés; tu as multiplié plus qu’elles tes abominations, et tu as justifié tes sœurs par toutes tes abominations que tu as commises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Toi aussi, toi qui as jugé tes sœurs, porte ta confusion à cause de tes péchés, par lesquels tu as agi plus abominablement qu’elles; elles sont plus justes que toi. Et toi aussi, sois honteuse et porte ta confusion, parce que tu as justifié tes sœurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Et je tournerai [en délivrance] leur captivité, la captivité de Sodome et de ses filles, et la captivité de Samarie et de ses filles, et la captivité de tes captifs au milieu d’elles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'afin que tu portes ta confusion, et que tu sois confuse de tout ce que tu as fait, en ce que tu les consoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Et tes sœurs, Sodome et ses filles, retourneront à leur ancien état, et Samarie et ses filles retourneront à leur ancien état; et toi et tes filles, vous retournerez à votre ancien état.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Et Sodome, ta sœur, n’a pas été mentionnée par ta bouche, au jour de ton orgueil,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'avant que ton iniquité soit découverte, comme au temps des outrages des filles d’Aram et de toutes celles d’alentour, des filles des Philistins, qui te méprisaient de toutes parts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Ton infamie et tes abominations, tu les portes, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Car ainsi dit le Seigneur, l’ Éternel: Je te ferai comme tu as fait, toi qui as méprisé le serment et rompu l’alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Mais je me souviendrai de mon alliance avec toi dans les jours de ta jeunesse, et j’établirai pour toi une alliance éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Et tu te souviendras de tes voies; et tu seras confuse, quand tu recevras tes sœurs, tes aînées, avec celles qui sont plus jeunes que toi, et que je te les donnerai pour filles, mais non pas selon ton alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Et j’établirai mon alliance avec toi, et tu sauras que je suis l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'afin que tu te souviennes, et que tu sois honteuse, et que tu n’ouvres plus la bouche, à cause de ta confusion, quand je te pardonnerai tout ce que tu as fait, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Fils d’homme, propose une énigme et présente une parabole à la maison d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'et dis: Ainsi dit le Seigneur, l’ Éternel: Un grand aigle, à grandes ailes, à longues pennes, plein de plumes, qui était de couleurs variées, vint au Liban, et prit la cime d’un cèdre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'il arracha la plus haute de ses jeunes pousses, et la transporta dans un pays de marchands et la mit dans une ville de commerçants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Et il prit de la semence du pays et la mit dans un champ où l’on sème; il la transporta près de grandes eaux, il la planta comme un saule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Et elle poussa et devint une vigne qui s’étendit, mais avait peu de hauteur, pour que ses branches se tournent vers lui et que ses racines soient sous lui; et elle devint une vigne, et produisit des sarments, et poussa des feuilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Mais il y avait un [autre] grand aigle, à grandes ailes et à beaucoup de plumes; et voici, des carrés de sa plantation, cette vigne tourna vers lui ses racines, et étendit ses branches vers lui, afin qu’il l’arrose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Elle était plantée dans un bon terrain, près de grandes eaux, afin de produire des sarments et de porter du fruit, afin d’être une vigne magnifique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Dis: Ainsi dit le Seigneur, l’ Éternel: Prospérera-t-elle? N’arrachera-t-il pas ses racines, et ne coupera-t-il pas son fruit, en sorte qu’elle sèche? Toutes les jeunes feuilles de ses pousses sécheront, et il ne sera pas besoin d’un grand bras et d’un peuple nombreux pour l’enlever de dessus ses racines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Et voici, elle est plantée: prospérera-t-elle? Quand le vent d’orient l’aura touchée, ne séchera -t-elle pas entièrement? Elle séchera sur les carrés où elle a poussé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Dis à la maison rebelle: Ne savez-vous pas ce que signifient ces choses? Dis: Voici, le roi de Babylone est venu à Jérusalem, et il a pris son roi et ses princes, et les a emmenés avec lui à Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Et il en a pris un de la semence du royaume, et a fait alliance avec lui, et lui a fait prêter un serment [d’exécration], et il a pris les puissants du pays,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'afin que le royaume soit bas et qu’il ne s’élève point, afin qu’il garde son alliance pour subsister.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Mais il s’est rebellé contre lui, envoyant ses messagers en Égypte, pour qu’on lui donne des chevaux et un peuple nombreux. Prospérera-t-il, échappera-t-il, celui qui fait de telles choses? Rompra-t-il l’alliance, et échappera-t-il?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Je suis vivant, dit le Seigneur, l’ Éternel, si, dans le lieu [même] du roi qui l’a fait roi, dont il a méprisé le serment et dont il a rompu l’alliance, près de lui, il ne meurt au milieu de Babylone!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Et le Pharaon, avec une grande armée et un grand rassemblement [d’hommes], ne fera rien pour lui dans la guerre, quand on élèvera des terrasses et qu’on bâtira des tours, pour exterminer beaucoup de gens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Il a méprisé le serment et rompu l’alliance; et voici, il a donné sa main, et il a fait toutes ces choses: il n’échappera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Je suis vivant, si je ne mets sur sa tête mon serment qu’il a méprisé et mon alliance qu’il a rompue!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Et j’étendrai sur lui mon filet, et il sera pris dans mon piège; et je l’amènerai à Babylone, et là j’entrerai en jugement avec lui pour son infidélité par laquelle il a été infidèle envers moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Et tous ses fugitifs, de toutes ses troupes, tomberont par l’épée, et ceux qui resteront seront dispersés à tout vent. Et vous saurez que moi, l’ Éternel, j’ai parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Ainsi dit le Seigneur, l’ Éternel: Et moi, je prendrai de la cime du cèdre élevé [un rejeton], et je le placerai: de la plus haute de ses jeunes pousses, j’arracherai un tendre [rejeton] et je le planterai sur une montagne haute et éminente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Je le planterai sur la haute montagne d’Israël; et il portera des branches et produira du fruit, et il sera un cèdre magnifique; et tout oiseau de toute aile demeurera sous lui; ils habiteront à l’ombre de ses branches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Et tous les arbres des champs sauront que moi, l’ Éternel, j’abaisse l’arbre élevé [et] j’élève l’arbre abaissé, je fais sécher l’arbre vert et je fais fleurir l’arbre sec. Moi, l’ Éternel, je l’ai dit, et je le ferai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Que voulez-vous dire, vous qui usez de ce proverbe dans la terre d’Israël, disant: Les pères mangent du raisin vert, et les dents des fils en sont agacées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Je suis vivant, dit le Seigneur, l’ Éternel, si vous usez encore de ce proverbe en Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Voici, toutes les âmes sont à moi; comme l’âme du père, ainsi aussi l’âme du fils est à moi: l’âme qui péchera, celle-là mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Et si un homme est juste, et pratique le jugement et la justice;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 's’il n’a pas mangé sur les montagnes, et s’il n’a pas levé ses yeux vers les idoles de la maison d’Israël, et n’a pas rendu impure la femme de son prochain, et ne s’est pas approché d’une femme pendant sa séparation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'et s’il n’a opprimé personne; s’il a rendu le gage de sa créance, n’a pas commis de rapine, a donné son pain à celui qui avait faim, et a couvert d’un vêtement celui qui était nu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 's’il n’a pas donné à intérêt, et n’a pas pris d’usure; s’il a détourné sa main de l’iniquité, a rendu un jugement juste entre homme et homme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'a marché dans mes statuts, et a gardé mes ordonnances pour agir fidèlement, celui-là est juste: certainement il vivra, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Et s’il a engendré un fils qui soit un homme violent, qui verse le sang, et qui fasse seulement l’une de ces choses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'et de ces autres choses n’en fasse aucune, – qui aussi a mangé sur les montagnes, a rendu impure la femme de son prochain,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'a foulé l’affligé et le pauvre, a commis des rapines, n’a pas rendu le gage, a levé ses yeux vers les idoles, a commis l’abomination,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'a donné à intérêt, et a pris de l’usure: vivra-t-il? Il ne vivra pas, il a fait toutes ces abominations: certainement il mourra, son sang sera sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Mais voici, s’il a engendré un fils qui voie tous les péchés que son père a commis, et qui y prenne garde, et ne fasse pas selon ces choses:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'il n’a pas mangé sur les montagnes, et n’a pas levé ses yeux vers les idoles de la maison d’Israël; il n’a pas rendu impure la femme de son prochain,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'et n’a opprimé personne; il n’a pas pris de gage, et n’a pas commis de rapine; il a donné son pain à celui qui avait faim, et a couvert d’un vêtement celui qui était nu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'il a détourné sa main de dessus l’affligé, il n’a pas pris d’intérêt ni d’usure, il a pratiqué mes ordonnances [et] a marché dans mes statuts: celui-là ne mourra pas pour l’iniquité de son père; certainement il vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Quant à son père, parce qu’il a pratiqué l’extorsion, qu’il a commis des rapines contre son frère, et a fait au milieu de son peuple ce qui n’est pas bien, voici, il mourra dans son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Et vous direz: Pourquoi le fils ne portera-t-il pas l’iniquité de son père? Mais le fils a pratiqué le jugement et la justice, il a gardé tous mes statuts et les a pratiqués: certainement il vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'L’âme qui a péché, celle-là mourra. Le fils ne portera pas l’iniquité du père, et le père ne portera pas l’iniquité du fils; la justice du juste sera sur lui, et la méchanceté du méchant sera sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Et le méchant, s’il se détourne de tous ses péchés qu’il a commis, et qu’il garde tous mes statuts, et qu’il pratique le jugement et la justice, certainement il vivra; il ne mourra pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'De toutes ses transgressions qu’il aura commises, aucune ne viendra en mémoire contre lui; dans sa justice qu’il a pratiquée, il vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Est-ce que je prends plaisir à la mort du méchant? dit le Seigneur, l’ Éternel; n’est-ce pas [plutôt] à ce qu’il se détourne de ses voies, et qu’il vive?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Et si le juste se détourne de sa justice et commet l’iniquité, faisant selon toutes les abominations que le méchant commet, vivra-t-il? De tous ses actes justes qu’il aura faits, aucun ne viendra en mémoire; dans son iniquité qu’il aura commise et dans son péché qu’il a fait, en eux il mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Et vous dites: La voie du Seigneur n’est pas réglée. Écoutez donc, maison d’Israël: Ma voie n’est-elle pas réglée? Ne sont-ce pas vos voies qui ne sont pas réglées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Quand le juste se détournera de sa justice, et qu’il pratiquera l’iniquité, il mourra pour cela; dans son iniquité qu’il aura commise, il mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Et quand le méchant se détournera de sa méchanceté qu’il aura commise, et qu’il pratiquera le jugement et la justice, celui-là fera vivre son âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Puisqu’il prend garde, et se détourne de toutes ses transgressions qu’il a commises, certainement il vivra, il ne mourra point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Et la maison d’Israël dit: La voie du Seigneur n’est pas réglée. Maison d’Israël! mes voies ne sont-elles pas réglées? Ne sont-ce pas vos voies qui ne sont pas réglées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'C’est pourquoi je vous jugerai, chacun selon ses voies, maison d’Israël, dit le Seigneur, l’ Éternel. Revenez, et détournez-vous de toutes vos transgressions, et l’iniquité ne vous sera pas une pierre d’achoppement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Jetez loin de vous toutes vos transgressions dans lesquelles vous vous êtes rebellés, et faites-vous un cœur nouveau et un esprit nouveau; et pourquoi mourriez-vous, maison d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Car je ne prends point plaisir à la mort de celui qui meurt, dit le Seigneur, l’ Éternel. Revenez donc, et vivez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, '*Et toi, élève une complainte sur les princes d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'et dis: Qu’était ta mère? Une lionne couchée parmi les lions, élevant ses petits au milieu des lionceaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Et elle éleva un de ses petits; il devint un jeune lion et apprit à déchirer la proie; il dévora des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Et les nations entendirent parler de lui; il fut pris dans leur fosse, et on le mena avec un anneau à ses narines dans le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Et quand elle vit qu’elle avait attendu [et] que son espoir avait péri, elle prit un [autre] de ses petits, [et] en fit un jeune lion;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'il marcha au milieu des lions, il devint un jeune lion et apprit à déchirer la proie; il dévora des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Il connut leurs palais [désolés], et dévasta leurs villes, et le pays et tout ce qu’il contenait fut désolé par la voix de son rugissement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Alors, de [toutes] les provinces, les nations d’alentour se rangèrent contre lui, et étendirent sur lui leur filet: il fut pris dans leur fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Et elles le mirent dans une cage, avec un anneau à ses narines, et le menèrent au roi de Babylone; elles le menèrent dans une forteresse, afin que sa voix ne soit plus entendue sur les montagnes d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Ta mère était comme une vigne, plantée près des eaux dans ton repos; elle était féconde et chargée de branches à cause des grandes eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Et elle avait des rameaux robustes pour des sceptres de dominateurs, et elle s’élevait haut au milieu de branches touffues, et elle était apparente par sa hauteur, par la multitude de ses rameaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Mais elle fut arrachée avec fureur, jetée par terre, et le vent d’orient fit sécher son fruit; ses rameaux robustes ont été brisés et desséchés, le feu les a consumés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Et maintenant elle est plantée dans le désert, dans une terre sèche et aride.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Et un feu est sorti d’un rameau de ses branches [et] a consumé son fruit, et il n’y a pas en elle de rameau robuste, de sceptre pour dominer. C’est là une complainte, et ce sera une complainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, '*Et il arriva, la septième année, au cinquième [mois], le dixième [jour] du mois, que des hommes d’entre les anciens d’Israël vinrent pour consulter l’ Éternel; et ils s’assirent devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Fils d’homme, parle aux anciens d’Israël, et dis-leur: Ainsi dit le Seigneur, l’ Éternel: Êtes-vous venus pour me consulter? Je suis vivant, dit le Seigneur, l’ Éternel, si je suis consulté par vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Les jugeras-tu, les jugeras-tu, fils d’homme? Fais-leur connaître les abominations de leurs pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'et dis-leur: Ainsi dit le Seigneur, l’ Éternel: Au jour où je choisis Israël, et que je levai ma main à la semence de la maison de Jacob, et que je me fis connaître à eux dans le pays d’Égypte, et que je leur levai ma main, disant: Je suis l’ Éternel, votre Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, '– en ce jour-là je leur levai ma main de les faire sortir du pays d’Égypte [pour les amener] dans le pays sur lequel j’avais jeté les yeux pour eux, [pays] ruisselant de lait et de miel, qui est un ornement entre tous les pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'et je leur dis: Que chacun de vous rejette les abominations que ses yeux regardent, et ne vous rendez pas impurs par les idoles de l’Égypte. Je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Et ils se rebellèrent contre moi, et ne voulurent pas m’écouter; aucun d’eux ne rejeta les abominations que ses yeux regardaient, ni ne quitta les idoles de l’Égypte; et je dis que je verserais ma fureur sur eux, et que je consommerais ma colère sur eux, au milieu du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Mais j’ai agi à cause de mon nom, afin de ne pas le profaner aux yeux des nations au milieu desquelles ils étaient, aux yeux desquelles je m’étais fait connaître à eux, en les faisant sortir du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Et je les fis sortir du pays d’Égypte, et les amenai au désert;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'et je leur donnai mes statuts et leur fis connaître mes ordonnances, – par lesquels, s’il les pratique, un homme vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Et je leur donnai aussi mes sabbats, pour être un signe entre moi et eux, afin qu’ils connaissent que je suis l’ Éternel qui les sanctifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Et la maison d’Israël se rebella contre moi dans le désert; ils ne marchèrent pas dans mes statuts, et ils rejetèrent mes ordonnances, – par lesquels, s’il les pratique, un homme vivra; et ils profanèrent extrêmement mes sabbats; et je dis que je verserais sur eux ma fureur dans le désert, pour les consumer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Mais j’ai agi à cause de mon nom, afin de ne pas le profaner aux yeux des nations sous les yeux desquelles je les avais fait sortir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Et je leur levai aussi ma main dans le désert, que je ne les amènerais pas dans le pays que je [leur] avais donné, [pays] ruisselant de lait et de miel, qui est un ornement entre tous les pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'parce qu’ils avaient rejeté mes ordonnances, et qu’ils n’avaient pas marché dans mes statuts, et qu’ils avaient profané mes sabbats; car leur cœur marchait après leurs idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Mais mon œil eut compassion d’eux pour ne pas les détruire, et je ne les consumai pas entièrement dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Et je dis à leurs fils dans le désert: Ne marchez pas dans les statuts de vos pères, et ne gardez point leurs ordonnances, et ne vous rendez pas impurs par leurs idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Je suis l’ Éternel, votre Dieu; marchez dans mes statuts, et gardez mes ordonnances et pratiquez-les;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'et sanctifiez mes sabbats, et qu’ils soient un signe entre moi et vous, afin que vous connaissiez que je suis l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Et les fils se rebellèrent contre moi; ils ne marchèrent pas dans mes statuts et ne gardèrent pas mes ordonnances pour les pratiquer, – par lesquels, s’il les pratique, un homme vivra; ils profanèrent mes sabbats; et je dis que je verserais sur eux ma fureur, pour consommer ma colère contre eux dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Mais je retirai ma main; et j’ai agi à cause de mon nom, afin de ne pas le profaner aux yeux des nations sous les yeux desquelles je les avais fait sortir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Je leur levai aussi ma main dans le désert, que je les disperserais parmi les nations et que je les disséminerais dans les pays,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'parce qu’ils ne pratiquaient pas mes ordonnances, et qu’ils rejetaient mes statuts et profanaient mes sabbats, et que leurs yeux étaient après les idoles de leurs pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Et moi aussi, je leur donnai des statuts qui n’étaient pas bons et des ordonnances par lesquelles ils ne pouvaient vivre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'et je les rendis impurs dans leurs dons, en ce qu’ils consacraient tout ce qui ouvrait la matrice, afin que je les mette en désolation, pour qu’ils connaissent que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'C’est pourquoi, fils d’homme, parle à la maison d’Israël, et dis-leur: Ainsi dit le Seigneur, l’ Éternel: Encore en ceci vos pères m’ont outragé, en étant infidèles envers moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Quand je les introduisis dans le pays touchant lequel j’avais levé ma main de le leur donner, ils ont regardé toute haute colline et tout arbre touffu, et là ils ont offert leurs sacrifices, et là ils ont présenté la provocation de leur offrande, et là ils ont placé leurs parfums agréables, et là ils ont répandu leurs libations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Et je leur dis: Qu’est-ce que ce haut lieu où vous allez? et son nom a été appelé Bama, jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'C’est pourquoi, dis à la maison d’Israël: Ainsi dit le Seigneur, l’ Éternel: Ne vous rendez-vous pas impurs dans la voie de vos pères, et ne vous prostituez-vous pas après leurs abominations?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Et quand vous offrez vos dons, en faisant passer vos fils par le feu, vous vous rendez impurs par toutes vos idoles jusqu’à aujourd’hui, – et moi, je serais consulté par vous, maison d’Israël? Je suis vivant, dit le Seigneur, l’ Éternel, si je suis consulté par vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Et ce qui monte dans votre esprit n’arrivera nullement, en ce que vous dites: Nous serons comme les nations, comme les familles des pays, en servant le bois et la pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Je suis vivant, dit le Seigneur, l’ Éternel, si je ne règne sur vous avec une main forte et un bras étendu, et avec effusion de fureur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'et si je ne vous fais sortir d’entre les peuples, et ne vous rassemble hors des pays dans lesquels vous êtes dispersés, avec une main forte et un bras étendu, et avec effusion de fureur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'et si je ne vous introduis dans le désert des peuples, et là n’entre en jugement avec vous face à face!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Comme je suis entré en jugement avec vos pères dans le désert du pays d’Égypte, ainsi j’entrerai en jugement avec vous, dit le Seigneur, l’ Éternel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'et je vous ferai passer sous la verge, et vous introduirai dans le lien de l’alliance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'et je séparerai d’entre vous les rebelles et ceux qui se sont révoltés contre moi: je les ferai sortir du pays dans lequel ils séjournent, mais ils n’entreront point dans la terre d’Israël; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Et vous, maison d’Israël! ainsi dit le Seigneur, l’ Éternel: Allez, servez chacun vos idoles, à l’avenir aussi, si aucun de vous ne veut m’écouter; mais ne profanez plus mon saint nom par vos dons et par vos idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Car en ma montagne sainte, en la haute montagne d’Israël, dit le Seigneur, l’ Éternel, là me servira la maison d’Israël tout entière, dans le pays; là je prendrai plaisir en eux, et là je demanderai vos offrandes élevées et les prémices de vos offrandes, dans toutes vos choses saintes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Je prendrai plaisir en vous comme en un parfum agréable, quand je vous aurai fait sortir d’entre les peuples, et que je vous aurai rassemblés des pays dans lesquels vous serez dispersés, et que je serai sanctifié en vous aux yeux des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Et vous saurez que je suis l’ Éternel, quand je vous aurai fait entrer dans la terre d’Israël, dans le pays touchant lequel j’ai levé ma main de le donner à vos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Et là vous vous souviendrez de vos voies et de toutes vos actions par lesquelles vous vous êtes rendus impurs, et vous aurez horreur de vous-mêmes à cause de toutes vos iniquités, que vous avez commises;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'et vous saurez que je suis l’ Éternel, quand j’agirai envers vous à cause de mon nom, non pas selon vos mauvaises voies et selon vos actions corrompues, ô maison d’Israël, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Fils d’homme, tourne ta face vers le sud, et distille [tes paroles] contre le midi, et prophétise contre la forêt des champs du midi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'et dis à la forêt du midi: Écoute la parole de l’ Éternel: Ainsi dit le Seigneur, l’ Éternel: Voici, j’allume en toi un feu qui consumera en toi tout bois vert et tout bois sec; la flamme flamboyante ne sera pas éteinte, et tout ce qu’elle rencontrera en sera brûlé, du midi jusqu’au nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Et toute chair verra que moi, l’ Éternel, je l’ai allumé; il ne sera pas éteint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Et je dis: Ah, Seigneur Éternel! ils disent de moi: Celui-ci ne parle-t-il pas en paraboles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Fils d’homme, tourne ta face contre Jérusalem, et distille [tes paroles] contre les sanctuaires, et prophétise contre la terre d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'et dis à la terre d’Israël: Ainsi dit l’ Éternel: Voici, c’est à toi que j’en veux, et je tirerai mon épée de son fourreau, et je retrancherai de toi le juste et le méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Parce que je retrancherai de toi le juste et le méchant, à cause de cela mon épée sortira de son fourreau contre toute chair, du midi jusqu’au nord;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'et toute chair saura que moi, l’ Éternel, j’ai tiré mon épée de son fourreau: elle n’y retournera plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Et toi, fils d’homme, gémis à te briser les reins, gémis avec amertume devant leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Et il arrivera que, quand ils te diront: Pourquoi gémis-tu? tu diras: C’est à cause de la rumeur, car elle vient; et tout cœur sera défaillant, et toutes les mains deviendront lâches, et tout esprit faiblira, et tous les genoux se fondront en eau. Voici, elle vient, elle est là, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Fils d’homme, prophétise, et dis: Ainsi dit l’ Éternel: Dis: L’épée, l’épée est aiguisée et aussi fourbie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'C’est afin qu’elle égorge bien, qu’elle est aiguisée; c’est pour briller comme l’éclair, qu’elle est fourbie. Ou bien nous réjouirions-nous, [disant]: Le sceptre de mon fils méprise tout bois?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Et il l’a donnée à fourbir, pour qu’on la prenne dans la main; c’est une épée aiguisée, et elle est fourbie, pour la mettre dans la main de celui qui tue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Crie et hurle, fils d’homme! Car elle sera contre mon peuple, elle sera contre tous les princes d’Israël: ils sont livrés à l’épée avec mon peuple; c’est pourquoi frappe sur ta cuisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Car l’épreuve [est faite]; et quoi?... si même le sceptre méprisant n’existe plus? dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Et toi, fils d’homme, prophétise, et frappe tes mains l’une contre l’autre, et que [les coups de] l’épée redoublent jusqu’à la troisième fois; c’est l’épée des tués, l’épée qui a tué le grand, [et] qui les environne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'C’est afin que le cœur se fonde et que les occasions de chute soient multipliées, que j’envoie l’épée menaçante contre toutes leurs portes. Ah! elle est faite pour briller comme l’éclair, et affilée pour tuer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Ramasse [tes forces], va à droite, tourne-toi, va à gauche, où que ta face soit dirigée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Et moi aussi je frapperai mes mains l’une contre l’autre, et je satisferai ma fureur. Moi, l’ Éternel, j’ai parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Et toi, fils d’homme, place devant toi deux chemins par où vienne l’épée du roi de Babylone: qu’ils partent tous deux du même pays; et fais-toi un indicateur, fais-le à l’entrée du chemin d’une ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Tu disposeras un chemin pour que l’épée vienne à Rabba des fils d’Ammon, et [un chemin] en Juda, [pour que l’épée vienne] à Jérusalem, la [ville] forte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Car le roi de Babylone se tient au point d’embranchement de la route, à la tête des deux chemins, pour pratiquer la divination: il secoue les flèches, il interroge les théraphim, il examine le foie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Dans sa droite est la divination touchant Jérusalem, pour placer des béliers, pour qu’on ouvre la bouche en cris de carnage, pour qu’on élève la voix en cris de guerre, pour placer des béliers contre les portes, pour élever des terrasses, pour bâtir des tours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Et ce sera pour eux, à leurs yeux, une divination fausse, pour eux qui se sont engagés par serment; mais lui, il rappellera le souvenir de l’iniquité, pour qu’ils soient pris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Parce que vous rappelez en mémoire votre iniquité, en ce que vos transgressions sont découvertes, de sorte que vos péchés paraissent dans toutes vos actions; parce que vous êtes rappelés en mémoire, vous serez pris par [sa] main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Et toi, profane, méchant prince d’Israël, dont le jour est venu au temps de l’iniquité de la fin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'ainsi dit le Seigneur, l’ Éternel: Ôte la tiare, et enlève la couronne; ce qui est ne sera plus. Élève ce qui est bas, et abaisse ce qui est élevé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'J’en ferai une ruine, une ruine, une ruine! Ceci aussi ne sera plus, jusqu’à ce que vienne celui auquel appartient le juste jugement, et je le lui donnerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 33, 'Et toi, fils d’homme, prophétise, et dis: Ainsi dit le Seigneur, l’ Éternel, touchant les fils d’Ammon et touchant leur opprobre; et tu diras: L’épée, l’épée est tirée, elle est fourbie pour la tuerie, pour dévorer, pour briller,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 34, 'pendant qu’ils ont pour toi des visions de vanité et qu’ils devinent pour toi le mensonge, pour te jeter sur les cous des méchants qui sont tués, dont le jour est venu au temps de l’iniquité de la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 35, 'Remets-la dans son fourreau! Je te jugerai au lieu où tu fus créé, au pays de ton origine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 36, 'Je verserai sur toi mon indignation, je soufflerai contre toi le feu de mon courroux, et je te livrerai en la main d’hommes brutaux, artisans de destruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 37, 'Tu seras pour le feu, pour être dévoré; ton sang sera au milieu du pays; on ne se souviendra pas de toi; car moi, l’ Éternel, j’ai parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Et toi, fils d’homme, jugeras-tu, jugeras-tu la ville de sang? et lui feras-tu connaître toutes ses abominations?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Tu diras: Ainsi dit le Seigneur, l’ Éternel: Ville, qui verses le sang au milieu de toi, afin que ton temps vienne, et qui as fait des idoles chez toi pour te rendre impure,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'tu t’es rendue coupable par ton sang que tu as versé, et tu t’es rendue impure par tes idoles que tu as faites, et tu as fait approcher tes jours, et tu es parvenue à tes années: c’est pourquoi je t’ai livrée à l’opprobre des nations et à la raillerie de tous les pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Ceux qui sont près et ceux qui sont loin de toi se moqueront de toi, qui es impure de renommée, [et] pleine de trouble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Voici, les princes d’Israël étaient au-dedans de toi pour verser le sang, chacun selon son pouvoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Ils ont méprisé père et mère au-dedans de toi; ils ont agi oppressivement envers l’étranger au milieu de toi; ils ont foulé l’orphelin et la veuve au-dedans de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Tu as méprisé mes choses saintes, et tu as profané mes sabbats.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Il y a eu au-dedans de toi des hommes calomniateurs pour verser le sang; et au-dedans de toi ils ont mangé sur les montagnes; ils ont commis des infamies au milieu de toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'au-dedans de toi ils ont découvert la nudité d’un père; au-dedans de toi ils ont humilié la femme séparée à cause de ses mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Et l’un a commis une abomination avec la femme de son prochain, et l’autre a rendu impure sa belle-fille par une infamie, et un autre, au-dedans de toi, a humilié sa sœur, fille de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Au-dedans de toi, ils ont reçu des présents pour verser le sang; tu as pris intérêt et usure, et tu as fait par l’extorsion un gain déshonnête aux dépens de ton prochain; et tu m’as oublié, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Et voici, j’ai frappé des mains contre ton gain déshonnête que tu as fait, et contre le sang qui est versé au milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Ton cœur tiendra-t-il ferme, ou tes mains seront-elles fortes, aux jours où j’agirai contre toi? Moi, l’ Éternel, j’ai parlé, et je le ferai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Et je te disperserai parmi les nations, et je te disséminerai dans les pays, et je consumerai du milieu de toi ton impureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Et tu seras profanée par toi-même aux yeux des nations, et tu sauras que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Fils d’homme, la maison d’Israël est devenue pour moi des scories; eux tous sont de l’airain, et de l’étain, et du fer, et du plomb, au milieu du fourneau; ils sont devenus des scories d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Parce que vous êtes tous devenus des scories, à cause de cela, voici, je vous rassemble au milieu de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, '[Comme] on rassemble l’argent, et l’airain, et le fer, et le plomb, et l’étain, au milieu d’un fourneau, pour souffler le feu dessus afin de les fondre, ainsi je vous rassemblerai dans ma colère et dans ma fureur, et je vous laisserai [là], et je vous fondrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Et je vous assemblerai, et je soufflerai contre vous le feu de mon courroux, et vous serez fondus au milieu de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Comme l’argent est fondu au milieu du fourneau, ainsi vous serez fondus au milieu d’elle; et vous saurez que moi, l’ Éternel, j’ai versé ma fureur sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Fils d’homme, dis-lui: Tu es un pays qui n’est pas purifié, qui n’est pas arrosé de pluie au jour de l’indignation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Il y a une conjuration de ses prophètes au milieu d’elle, comme un lion rugissant qui déchire la proie; ils dévorent les âmes, ils enlèvent les richesses et les choses précieuses; ils multiplient ses veuves au milieu d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Ses sacrificateurs font violence à ma loi et profanent mes choses saintes; ils ne font pas de différence entre ce qui est saint et ce qui est profane, et ils ne font pas connaître la différence entre ce qui est impur et ce qui est pur; et ils cachent leurs yeux de mes sabbats, et je suis profané au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Ses princes, au milieu d’elle, sont comme des loups qui déchirent la proie, pour verser le sang, pour détruire les âmes, afin de faire un gain déshonnête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Et ses prophètes leur ont fait des enduits de mauvais mortier, ayant des visions de vanité et devinant pour eux le mensonge, disant: Ainsi dit le Seigneur, l’ Éternel; – et l’ Éternel n’a point parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Le peuple du pays pratique l’extorsion et commet la rapine, et foule l’affligé et le pauvre; et ils oppriment l’étranger contrairement à tout droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Et j’ai cherché parmi eux un homme qui ferme l’enceinte, et qui se tienne à la brèche devant moi pour le pays, afin que je ne le détruise pas; mais je n’en ai point trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Et je verserai sur eux mon indignation; dans le feu de mon courroux je les consumerai, je ferai retomber leur voie sur leur tête, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Fils d’homme, il y avait deux femmes, filles d’une même mère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'et elles se prostituèrent en Égypte, elles se prostituèrent dans leur jeunesse: là leurs mamelles furent froissées, là les seins de leur virginité furent pressés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Et leurs noms étaient: Ohola, l’aînée, et Oholiba, sa sœur; et elles étaient à moi, et elles enfantèrent des fils et des filles. Et leurs noms: Samarie est Ohola, et Jérusalem, Oholiba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Et Ohola, étant à moi, se prostitua et se passionna pour ses amants, pour les Assyriens, ses voisins,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'vêtus de bleu, gouverneurs et chefs, tous beaux jeunes hommes, cavaliers montés sur des chevaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'et elle se livra à ses prostitutions avec eux, tous l’élite des fils d’Assur; et, avec tous ceux pour lesquels elle se passionna, avec toutes leurs idoles, elle se rendit impure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Et elle n’abandonna pas ses prostitutions [qui datent] de l’Égypte, car ils avaient couché avec elle dans sa jeunesse, et ils avaient pressé les seins de sa virginité, et avaient versé sur elle leur prostitution.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'C’est pourquoi je la livrai en la main de ses amants, en la main des fils d’Assur pour lesquels elle s’était passionnée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Ils découvrirent sa nudité, prirent ses fils et ses filles, et la tuèrent elle-même par l’épée; et elle devint renommée parmi les femmes, et ils exécutèrent des jugements sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Et sa sœur Oholiba vit [cela], et se corrompit plus qu’elle dans ses amours passionnées; et ses prostitutions furent plus [grandes] que les débauches de sa sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Elle se passionna pour les fils d’Assur, gouverneurs et chefs, ses voisins, vêtus magnifiquement, cavaliers montés sur des chevaux, tous beaux jeunes hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Et je vis qu’elle s’était rendue impure: elles suivaient toutes deux la même voie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Et elle avait ajouté à ses prostitutions, et elle avait vu des hommes dessinés sur le mur, des images de Chaldéens tracés au vermillon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'portant des ceintures sur leurs reins, avec des tiares flottantes sur leurs têtes, tous ayant l’aspect de grands seigneurs, à la ressemblance des fils de Babel, de la Chaldée, pays de leur naissance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'et elle se passionna pour eux en les voyant de ses yeux, et envoya des messagers vers eux en Chaldée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Et les fils de Babel vinrent vers elle dans le lit des amours, et la rendirent impure par leur prostitution, et elle se rendit impure avec eux; puis son âme se détacha d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Et elle découvrit ses prostitutions, et elle découvrit sa nudité; et mon âme se détacha d’elle, comme mon âme s’était détachée de sa sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Et elle multiplia ses prostitutions, se souvenant des jours de sa jeunesse, où elle s’était prostituée dans le pays d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'et elle se passionna pour ses concubins, dont la chair est [comme] la chair des ânes, et dont le flux est [comme] le flux des chevaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Tu te rappelas l’infamie de ta jeunesse, lorsque les Égyptiens pressaient tes seins à cause des mamelles de ta jeunesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'C’est pourquoi, Oholiba! ainsi dit le Seigneur, l’ Éternel: Voici, je réveille contre toi tes amants, desquels ton âme s’est détachée, et je les ferai venir contre toi de tous côtés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'les fils de Babel, et tous les Chaldéens, Pekod et Shoa et Koa, tous les fils d’Assur avec eux, tous beaux jeunes hommes, gouverneurs et chefs, grands seigneurs et gens de renom, tous montés sur des chevaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Et ils viendront contre toi avec des armes, des chars et des roues, et avec un rassemblement de peuples; ils se placeront contre toi, tout autour, avec le bouclier et l’écu et le casque; et je leur commettrai le jugement, et ils te jugeront selon leurs jugements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Et je mettrai ma jalousie contre toi, et ils agiront envers toi avec fureur: ils te couperont le nez et les oreilles; et ce qui restera de toi tombera par l’épée. Ils prendront tes fils et tes filles, et ce qui restera de toi sera dévoré par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Et ils te dépouilleront de tes vêtements, et prendront les objets dont tu te pares;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'et je ferai cesser en toi ton infamie et ta prostitution [qui date] du pays d’Égypte; et tu ne lèveras plus tes yeux vers eux, et tu ne te souviendras plus de l’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Car ainsi dit le Seigneur, l’ Éternel: Voici, je te livre en la main de ceux que tu hais, en la main de ceux dont ton âme s’est détachée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'et ils agiront envers toi avec haine, et prendront tout ton travail, et te laisseront nue et découverte; et la nudité de tes débauches, et ton infamie, et tes prostitutions, seront découvertes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Ces choses t’arriveront, parce que tu t’es prostituée après les nations, parce que tu t’es rendue impure par leurs idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Tu as marché dans le chemin de ta sœur; et j’ai mis sa coupe dans ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Ainsi dit le Seigneur, l’ Éternel: Tu boiras la coupe de ta sœur, profonde et large; tu seras en risée et en raillerie, [car] elle contient beaucoup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Tu seras remplie d’ivresse et de chagrin; ce sera une coupe d’étonnement et de désolation, la coupe de ta sœur Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Tu la boiras, et tu la suceras, et tu en rongeras les tessons, et tu te déchireras les seins; car j’ai parlé, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Parce que tu m’as oublié et que tu m’as jeté derrière ton dos, toi aussi porte ton infamie et tes prostitutions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Et l’ Éternel me dit: Fils d’homme, jugeras-tu Ohola et Oholiba? Déclare-leur leurs abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Car elles ont commis adultère, et il y a du sang à leurs mains; elles ont commis adultère avec leurs idoles; et même leurs fils qu’elles m’avaient enfantés, elles les leur ont consacrés pour être dévorés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Elles m’ont fait encore ceci: elles ont rendu impur mon sanctuaire en ce jour-là, et elles ont profané mes sabbats;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'quand elles avaient égorgé leurs fils à leurs idoles, elles venaient ce même jour dans mon sanctuaire, pour le profaner; et voici, elles ont fait ainsi au milieu de ma maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Et bien plus, elles ont envoyé vers des hommes venant de loin, auxquels un messager avait été envoyé; et voici, ils sont venus, ceux pour lesquels tu t’es lavée, tu as peint tes yeux et tu t’es parée d’ornements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'et tu t’es assise sur un lit somptueux devant lequel était dressée une table, et tu as placé sur elle mon encens et mon huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Et il y avait en elle le bruit d’une multitude à l’aise; et, vers la foule des hommes, on fit venir du désert des buveurs, qui leur mirent des bracelets aux mains et une couronne de beauté sur la tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Et j’ai dit de celle qui était usée par l’adultère: Maintenant commettra -t-elle ses prostitutions, elle aussi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Et on est venu vers elle comme on vient vers une femme prostituée. Ainsi ils sont venus vers Ohola et vers Oholiba, femmes criminelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Et des hommes justes, eux, les jugeront du jugement des femmes adultères et du jugement de celles qui versent le sang; car elles sont adultères, et il y a du sang à leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Car ainsi dit le Seigneur, l’ Éternel: On fera monter contre elles un rassemblement [d’hommes], et on les livrera à la vexation et au pillage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'et le rassemblement les lapidera avec des pierres, et ils les transperceront avec leurs épées; ils tueront leurs fils et leurs filles, et ils brûleront leurs maisons par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Et je ferai cesser l’infamie dans le pays; et toutes les femmes seront enseignées, et ne feront pas selon votre infamie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Et ils mettront vos infamies sur vous, et vous porterez les péchés de vos idoles; et vous saurez que je suis le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, '**Et la parole de l’ Éternel vint à moi, en la neuvième année, au dixième mois, le dixième [jour] du mois, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Fils d’homme, écris pour toi le nom de ce jour, de ce propre jour: le roi de Babylone s’approche contre Jérusalem, en ce jour même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Et propose une parabole à la maison rebelle, et dis-leur: Ainsi dit le Seigneur, l’ Éternel: Place la marmite, place-la, et verses-y aussi de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Rassembles-y ses morceaux, tous les bons morceaux, la cuisse et l’épaule; remplis-la d’os choisis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'prends du meilleur du menu bétail; et [mets] aussi dessous un tas de bois pour les os; fais-la bien bouillir, et que les os cuisent au-dedans d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Malheur à la ville de sang, la marmite en laquelle est sa rouille, et dont la rouille ne se détache pas! Tires-en morceau par morceau; qu’on ne jette pas le sort sur elle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'car son sang est au milieu d’elle: elle l’a mis sur le roc nu, elle ne l’a pas versé sur la terre pour le couvrir de poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Pour faire monter la fureur, pour exécuter la vengeance, j’ai mis son sang sur le roc nu, pour qu’il ne soit pas couvert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Malheur à la ville de sang! Moi aussi je ferai une grande pile de bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Entasse le bois, allume le feu, fais consommer la chair, assaisonne-la bien, et que les os soient brûlés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Place-la vide sur les charbons ardents, afin qu’elle s’échauffe et que son airain devienne brûlant, et que son impureté soit fondue au-dedans d’elle [et] que sa rouille soit consumée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Elle a lassé les efforts, et la rouille dont elle est pleine ne se détache pas: – au feu sa rouille!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Il y a de l’infamie dans ton impureté; puisque je t’ai purifiée, et tu n’es point pure. Tu ne seras plus purifiée de ton impureté, jusqu’à ce que j’aie satisfait sur toi ma fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Moi, l’ Éternel, j’ai parlé: cela arrivera, et je le ferai; je ne reculerai point, et je n’aurai point de compassion, et je ne me repentirai pas. On te jugera selon tes voies et selon tes actions, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Fils d’homme, voici, je vais t’ôter, par une plaie, le désir de tes yeux; et tu ne mèneras pas deuil, et tu ne pleureras pas, et tes larmes ne couleront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Gémis en silence: tu ne feras point le deuil des morts. Enroule ton turban sur toi, et mets tes sandales à tes pieds, et ne couvre pas ta barbe, et ne mange pas le pain des hommes. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Et je parlai au peuple le matin, et ma femme mourut le soir; et, le matin, je fis comme il m’avait été commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Et le peuple me dit: Ne nous déclareras-tu pas ce que signifient pour nous ces choses que tu fais?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Et je leur dis: La parole de l’ Éternel est venue à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Dis à la maison d’Israël: Ainsi dit le Seigneur, l’ Éternel: Voici, je profane mon sanctuaire, l’orgueil de votre force, le désir de vos yeux, et l’affection de votre âme; et vos fils et vos filles que vous avez laissés en arrière tomberont par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Et vous ferez comme j’ai fait: vous ne couvrirez point votre barbe et vous ne mangerez pas le pain des hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'et vos turbans seront sur vos têtes, et vos sandales à vos pieds; vous ne mènerez pas deuil et vous ne pleurerez pas, mais vous vous consumerez dans vos iniquités, et vous gémirez l’un vis-à-vis de l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Et Ézéchiel sera pour vous un signe: selon tout ce qu’il a fait, vous ferez. Quand cela arrivera, vous saurez que je suis le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Et toi, fils d’homme, au jour où je leur ôterai ce qui a été leur confiance, la joie de leur ornement, le désir de leurs yeux, et ce que recherchent leurs âmes, leurs fils et leurs filles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'en ce jour-là celui qui sera réchappé ne viendra-t-il pas vers toi pour le faire entendre à tes oreilles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'En ce jour-là ta bouche sera ouverte avec le réchappé, et tu parleras et tu ne seras plus muet; et tu seras pour eux un signe, et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Fils d’homme, tourne ta face vers les fils d’Ammon, et prophétise contre eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'et dis aux fils d’Ammon: Écoutez la parole du Seigneur, l’ Éternel! Ainsi dit le Seigneur, l’ Éternel: Parce que tu as dit: Ha ha! contre mon sanctuaire, quand il a été profané, et contre la terre d’Israël, quand elle a été désolée, et contre la maison de Juda, quand elle est allée en captivité:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'à cause de cela, voici, je te donne en possession aux fils de l’orient, et ils établiront chez toi leurs parcs, et placeront chez toi leurs demeures; ils mangeront tes fruits et boiront ton lait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Et je ferai de Rabba un pâturage pour les chameaux, et [du pays] des fils d’Ammon un gîte pour le menu bétail; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Car ainsi dit le Seigneur, l’ Éternel: Parce que tu as battu des mains et que tu as frappé du pied, et que tu t’es réjoui dans tout le mépris que tu avais en ton âme contre la terre d’Israël, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'à cause de cela, voici, j’étendrai ma main sur toi et je te livrerai en proie aux nations, et je te retrancherai d’entre les peuples, et je te ferai périr d’entre les pays; je te détruirai, et tu sauras que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Ainsi dit le Seigneur, l’ Éternel: Parce que Moab et Séhir ont dit: Voici, la maison de Juda est comme toutes les nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'à cause de cela, voici, j’ouvre le côté de Moab par les villes, par ses villes, jusqu’à la dernière, la gloire du pays, Beth-Jeshimoth, Baal-Méon, et Kiriathaïm;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, '[je l’ouvre] aux fils de l’orient, avec [le pays] des fils d’Ammon; et je le leur donnerai en possession, afin qu’on ne se souvienne plus des fils d’Ammon parmi les nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'et j’exécuterai des jugements sur Moab; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Ainsi dit le Seigneur, l’ Éternel: À cause de ce qu’Édom a fait quand il s’est vengé cruellement de la maison de Juda, et parce qu’il s’est rendu fort coupable en se vengeant d’eux, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'à cause de cela, ainsi dit le Seigneur, l’ Éternel: J’étendrai ma main aussi sur Édom, et j’en retrancherai hommes et bêtes, et j’en ferai un désert depuis Théman, et, jusqu’à Dedan, ils tomberont par l’épée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'et j’exercerai ma vengeance sur Édom par la main de mon peuple Israël; et ils agiront en Édom selon ma colère et selon ma fureur; et ils connaîtront ma vengeance, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Ainsi dit le Seigneur, l’ Éternel: À cause de ce que les Philistins ont fait par vengeance, et parce qu’ils se sont vengés cruellement, dans le mépris de leurs âmes, pour détruire par une inimitié perpétuelle, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'à cause de cela, ainsi dit le Seigneur, l’ Éternel: Voici, j’étends ma main sur les Philistins, et je retrancherai les Keréthiens, et je ferai périr le reste qui est sur le bord de la mer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'et j’exercerai sur eux de grandes vengeances par des châtiments de fureur; et ils sauront que je suis l’ Éternel, quand j’exécuterai sur eux ma vengeance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Et il arriva, la onzième année, le premier [jour] du mois, que la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Fils d’homme, parce que Tyr a dit touchant Jérusalem: Ha ha! elle est brisée, la porte des peuples! elle est tournée vers moi; je serai remplie; elle a été rendue déserte;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'à cause de cela, ainsi dit le Seigneur, l’ Éternel: Voici, j’en veux à toi, Tyr! et je ferai monter contre toi des nations nombreuses, comme la mer fait monter ses flots.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Et elles détruiront les murs de Tyr et renverseront ses tours; et je balaierai d’elle sa poussière, et je ferai d’elle un rocher nu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Elle sera un lieu pour étendre les filets, au milieu de la mer; car j’ai parlé, dit le Seigneur, l’ Éternel; et elle deviendra la proie des nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'et ses filles qui sont dans la campagne seront tuées par l’épée; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Car ainsi dit le Seigneur, l’ Éternel: Voici, je fais venir du nord, contre Tyr, Nebucadretsar, roi de Babylone, le roi des rois, avec des chevaux, et des chars, et des cavaliers, et un rassemblement et un peuple nombreux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Tes filles qui sont dans la campagne, il les tuera par l’épée; et il établira contre toi des tours; et il élèvera contre toi des terrasses; et il lèvera le bouclier contre toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'et il placera ses machines de siège contre tes murailles, et démolira tes tours avec ses pointes de fer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'À cause de la multitude de ses chevaux, leur poussière te couvrira; tes murailles trembleront au bruit de la cavalerie, et des roues et des chars, quand il entrera par tes portes comme on entre dans une ville ouverte par la brèche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Sous le sabot de ses chevaux il foulera toutes tes rues; il tuera ton peuple par l’épée, et les colonnes de ta force tomberont par terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Et ils feront une proie de tes richesses, et pilleront tes biens, et renverseront tes murs, et abattront tes maisons de plaisance; et ils mettront tes pierres, et ton bois, et ta poussière, au milieu des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Et je ferai cesser le bruit de tes chansons, et le son de tes harpes ne sera plus entendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Et je ferai de toi un rocher nu; tu seras un lieu pour étendre les filets; et tu ne seras plus bâtie; car moi, l’ Éternel, j’ai parlé, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Ainsi dit le Seigneur, l’ Éternel, à Tyr: Les îles ne trembleront-elles pas au bruit de ta chute, au gémissement de tes blessés à mort, quand le carnage se fera au milieu de toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Et tous les princes de la mer descendront de leurs trônes, et ôteront leurs robes, et dépouilleront leurs vêtements de broderie; ils se revêtiront de frayeur, ils s’assiéront sur la terre, et ils trembleront à tout moment et seront dans la stupeur à cause de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Et ils élèveront une complainte sur toi, et te diront: Comment as-tu péri, toi qui étais habitée par ceux qui venaient des mers, ville célèbre qui étais puissante sur la mer, toi et tes habitants qui répandiez votre terreur sur tous ceux qui habitent en elle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Maintenant les îles tremblent au jour de ta chute, et les îles qui sont dans la mer seront troublées à cause de l’issue de ta [voie].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Car ainsi dit le Seigneur, l’ Éternel: Quand je ferai de toi une ville déserte, comme sont les villes qui ne sont pas habitées; quand je ferai monter sur toi l’abîme, et que les grandes eaux te couvriront,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'alors je te ferai descendre avec ceux qui descendent dans la fosse, vers le peuple d’autrefois, et je te ferai habiter dans les lieux bas de la terre, dans les lieux désolés de tout temps, avec ceux qui descendent dans la fosse, afin que tu ne sois plus habitée, et que je mette la gloire dans la terre des vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Je ferai de toi une terreur, et tu ne seras plus; et on te cherchera, et on ne te trouvera plus, à jamais, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Et toi, fils d’homme, élève une complainte sur Tyr,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'et dis à Tyr: [Toi] qui demeures aux avenues de la mer, qui trafiques avec les peuples dans beaucoup d’îles, ainsi dit le Seigneur, l’ Éternel: Tyr, tu as dit: Je suis parfaite en beauté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Tes frontières sont au cœur des mers; ceux qui t’ont bâtie ont rendu ta beauté parfaite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Avec le cyprès de Senir ils construisaient tous tes doubles bordages; ils prenaient le cèdre du Liban pour faire ta mâture;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'avec les chênes de Basan ils faisaient tes rames; ils faisaient tes ponts d’ivoire enchâssé dans le buis des îles de Kittim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Le fin lin brodé d’Égypte était ta voile [et] te servait de pavillon; le bleu et la pourpre des îles d’Élisha étaient ta tente;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'les habitants de Sidon et d’Arvad étaient tes rameurs. Tes sages, ô Tyr, qui étaient en toi, étaient tes pilotes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Les anciens de Guebal et ses sages étaient en toi, réparant tes fissures; tous les navires de la mer et leurs marins étaient chez toi, pour faire trafic avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'La Perse, et Lud, et Puth, étaient dans ton armée tes hommes de guerre; ils suspendaient chez toi le bouclier et le casque, ils faisaient ta splendeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Les fils d’Arvad et ton armée étaient tout autour sur tes murailles, et [tes] guerriers étaient dans tes tours; ils suspendaient leurs boucliers à tes murailles tout autour, ils rendaient parfaite ta beauté. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarsis commerçait avec toi pour l’abondance de tous biens; d’argent, de fer, d’étain, et de plomb, ils fournissaient tes marchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Tubal et Méshec étaient tes marchands; ils fournissaient à ton trafic des âmes d’hommes et des ustensiles d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'De la maison de Togarma ils fournissaient tes marchés en chevaux, et en cavaliers, et en mulets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Les fils de Dedan étaient tes marchands; de nombreuses îles étaient en relation de commerce avec toi; elles te donnaient en retour des dents d’ivoire et de l’ébène.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'La Syrie commerçait avec toi à cause de la multitude de tes ouvrages; ils fournissaient tes marchés d’escarboucles, de pourpre, de broderie, et de fin lin, et de corail, et de rubis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda et le pays d’Israël étaient tes marchands; ils fournissaient à ton trafic du froment de Minnith, et de la pâtisserie, et du miel, et de l’huile, et du baume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Pour la multitude de tes ouvrages, à cause de l’abondance de tous biens, Damas commerçait avec toi en vin de Helbon et en laine blanche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Vedan, et Javan d’Uzal, fournissaient tes marchés de fer ouvragé; la casse et le roseau aromatique étaient dans ton trafic.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan était ton marchand en draps précieux pour housses de cheval.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'L’Arabie et tous les princes de Kédar étaient en relation de commerce avec toi; en agneaux, en béliers et en boucs, en ces choses-là, ils étaient tes commerçants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Les marchands de Sheba et de Rahma étaient tes marchands; ils fournissaient tes marchés de tout aromate excellent, et de toute pierre précieuse, et d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Charan, et Canné, et Éden, les marchands de Sheba, Assur, Kilmad, ta marchande,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'ceux-là trafiquaient avec toi en objets de prix, en draps bleus, et en broderies, et en caisses de riches étoffes, liées de cordes et [faites] de cèdre, entre tes marchandises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Les navires de Tarsis étaient tes caravanes, pour ton trafic; et tu as été remplie et tu es devenue extrêmement glorieuse au cœur des mers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Tes rameurs t’ont amenée dans de grandes eaux; le vent d’orient t’a brisée au cœur des mers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Tes richesses et tes échanges, ton trafic, tes marins et tes pilotes, ceux qui réparent tes fissures, et ceux qui font trafic avec toi, et tous tes hommes de guerre qui sont en toi, et toute ta multitude qui est au milieu de toi, tomberont au cœur des mers, au jour de ta chute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Les lieux ouverts trembleront au bruit du cri de tes pilotes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Et tous ceux qui manient la rame, les marins, tous les pilotes de la mer, descendront de leurs navires; ils se tiendront sur la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'et feront entendre leur voix sur toi, et crieront amèrement; et ils jetteront de la poussière sur leurs têtes, ils se rouleront dans la cendre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'et ils se rendront chauves à cause de toi, et se ceindront de sacs, et pleureront sur toi avec amertume d’âme, avec un deuil amer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Et dans leur gémissement ils élèveront sur toi une complainte, ils se lamenteront sur toi: Qui fut comme Tyr, comme celle qui est détruite au milieu de la mer?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Par les débouchés de tes marchés au-delà des mers tu as rassasié beaucoup de peuples; par l’abondance de tes richesses et de ton trafic tu as enrichi les rois de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Au temps où tu as été brisée par les mers dans les profondeurs des eaux, ton trafic et toute ta multitude au milieu de toi sont tombés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Tous les habitants des îles sont dans la stupeur à cause de toi, et leurs rois frémiront d’horreur, leurs visages sont agités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Les marchands parmi les peuples ont sifflé sur toi; tu es devenue une terreur, et tu ne seras plus, à jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Fils d’homme, dis au prince de Tyr: Ainsi dit le Seigneur, l’ Éternel: Parce que ton cœur s’est élevé et que tu as dit: Je suis ✶Dieu, je suis assis sur le siège d’un dieu, au cœur des mers (et tu es un homme, et non pas ✶Dieu), et que tu élèves ton cœur comme un cœur de dieu');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, '(voici, tu es plus sage que Daniel! rien de caché n’est obscur pour toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'par ta sagesse et par ton intelligence tu t’es acquis de la puissance et tu as amassé de l’or et de l’argent dans tes trésors;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'par la grandeur de ta sagesse, tu as, par ton négoce, multiplié ta richesse; et ton cœur s’est élevé à cause de ta richesse) –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'à cause de cela, ainsi dit le Seigneur, l’ Éternel: Parce que tu as élevé ton cœur comme un cœur de dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'à cause de cela, voici, je fais venir contre toi des étrangers, les terribles d’entre les nations; et ils tireront leurs épées contre la beauté de ta sagesse, et ils profaneront ta splendeur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'ils te feront descendre dans la fosse, et tu mourras de la mort de ceux qui sont tués au cœur des mers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Diras -tu peut-être devant celui qui te tue: Je suis Dieu? Mais tu seras un homme, et non pas ✶Dieu, dans la main de celui qui te transperce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Tu mourras de la mort des incirconcis, par la main des étrangers; car j’ai parlé, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Fils d’homme, élève une complainte sur le roi de Tyr, et dis-lui: Ainsi dit le Seigneur, l’ Éternel: Toi, tu étais la forme accomplie de la perfection, plein de sagesse, et parfait en beauté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'tu as été en Éden, le jardin de Dieu; toutes les pierres précieuses te couvraient, le sardius, la topaze et le diamant, la chrysolithe, l’onyx et le jaspe, le saphir, l’escarboucle et l’émeraude, et l’or; le riche travail de tes tambourins et de tes flûtes était en toi; au jour où tu fus créé ils étaient préparés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Tu étais un chérubin oint, qui couvrait, et je t’avais établi [tel]; tu étais dans la sainte montagne de Dieu, tu marchais parmi les pierres de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Tu fus parfait dans tes voies depuis le jour où tu fus créé, jusqu’à ce que l’iniquité s’est trouvée en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Par l’abondance de ton trafic, ton intérieur a été rempli de violence, et tu as péché; et je t’ai précipité de la montagne de Dieu comme une chose profane, et je t’ai détruit du milieu des pierres de feu, ô chérubin qui couvrait!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Ton cœur s’est élevé pour ta beauté, tu as corrompu ta sagesse à cause de ta splendeur; je t’ai jeté à terre, je t’ai mis devant les rois, afin qu’ils te voient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Par la multitude de tes iniquités, par l’injustice de ton trafic, tu as profané tes sanctuaires; et j’ai fait sortir un feu du milieu de toi: il t’a dévoré, et je t’ai réduit en cendre sur la terre, aux yeux de tous ceux qui te voient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Tous ceux qui te connaissent parmi les peuples sont dans la stupeur à cause de toi; tu es devenu une terreur, et tu ne seras plus, à jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Fils d’homme, tourne ta face vers Sidon, et prophétise contre elle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'et dis: Ainsi dit le Seigneur, l’ Éternel: Voici, j’en veux à toi, Sidon, et je serai glorifié au milieu de toi; et on saura que je suis l’ Éternel, quand j’exécuterai des jugements au milieu d’elle et que j’aurai été sanctifié en elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Et j’enverrai chez elle la peste, et le sang dans ses rues; et les blessés à mort tomberont au milieu d’elle par l’épée qui sera tout autour contre elle; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Et il n’y aura plus pour la maison d’Israël d’aiguillon qui blesse, ni d’épine qui cause de la douleur, d’entre tous ceux qui étaient autour d’eux et qui les méprisaient; et ils sauront que je suis le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Ainsi dit le Seigneur, l’ Éternel: Quand je rassemblerai la maison d’Israël d’entre les peuples parmi lesquels ils seront dispersés, et que je serai sanctifié en eux aux yeux des nations, alors ils habiteront sur leur terre que j’ai donnée à mon serviteur Jacob:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'ils y habiteront en sécurité; ils bâtiront des maisons, et ils planteront des vignes, et ils habiteront en sécurité, quand j’aurai exécuté des jugements sur tous ceux qui les méprisaient, tout autour d’eux; et ils sauront que je suis l’ Éternel, leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, '*La dixième année, au dixième [mois], le douzième [jour] du mois, la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Fils d’homme, tourne ta face contre le Pharaon, le roi d’Égypte, et prophétise contre lui et contre l’Égypte tout entière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Parle, et dis: Ainsi dit le Seigneur, l’ Éternel: Voici, j’en veux à toi, le Pharaon, roi d’Égypte, grand monstre des eaux, couché au milieu de ses fleuves, qui dis: Mon fleuve est à moi, et je me le suis fait!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Et je mettrai un anneau dans tes mâchoires, et j’attacherai à tes écailles les poissons de tes fleuves, et je te ferai monter du milieu de tes fleuves, et tous les poissons de tes fleuves qui sont attachés à tes écailles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Et je te jetterai dans le désert, toi et tous les poissons de tes fleuves; tu tomberas sur la face des champs, tu ne seras pas recueilli ni rassemblé; je te donnerai en pâture aux bêtes de la terre et aux oiseaux des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Et tous les habitants de l’Égypte sauront que je suis l’ Éternel, parce qu’ils ont été un appui de roseau pour la maison d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'lorsqu’ils t’ont pris par la main, tu t’es rompu, et tu leur as déchiré toute l’épaule; et quand ils se sont appuyés sur toi, tu t’es cassé, et tu as fait chanceler tous leurs reins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Voici, je fais venir l’épée sur toi, et je retrancherai de toi hommes et bêtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Et le pays d’Égypte sera une désolation et un désert; et ils sauront que je suis l’ Éternel, parce qu’il a dit: Le fleuve est à moi, et moi je l’ai fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'C’est pourquoi, voici, j’en veux à toi et à tes fleuves, et je ferai du pays d’Égypte des déserts d’aridité et de désolation, depuis Migdol à Syène, et jusqu’à la frontière de l’Éthiopie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'le pied de l’homme n’y passera pas, et le pied de la bête n’y passera pas; et il ne sera pas habité pendant 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Et je ferai du pays d’Égypte une désolation au milieu des pays désolés, et ses villes seront, au milieu des villes dévastées, une désolation pendant 40 ans; et je disperserai les Égyptiens parmi les nations, et je les disséminerai dans les pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Mais ainsi dit le Seigneur, l’ Éternel: Au bout de 40 ans, je rassemblerai les Égyptiens d’entre les peuples parmi lesquels ils auront été dispersés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'et je rétablirai les captifs de l’Égypte, et je les ferai revenir dans le pays de Pathros, dans le pays de leur origine; et ils seront là un royaume abaissé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Il sera plus bas que tous les royaumes, et il ne s’élèvera plus au-dessus des nations, et je les diminuerai, en sorte qu’ils ne dominent plus sur les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Et il ne sera plus la confiance de la maison d’Israël, mettant en mémoire son iniquité quand elle se tournait après eux; et ils sauront que je suis le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Et il arriva, la vingt-septième année, au premier [mois], le premier [jour] du mois, que la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Fils d’homme, Nebucadretsar, roi de Babylone, a fait travailler son armée à un grand travail contre Tyr: toute tête en est devenue chauve, et toute épaule en a été écorchée; et il n’a eu de Tyr aucun salaire, ni pour lui, ni pour son armée, pour le travail qu’il a fait contre elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Voici, je donne à Nebucadretsar, roi de Babylone, le pays d’Égypte; et il en enlèvera la multitude, il en emportera le butin, et en fera le pillage: et ce sera le salaire de son armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'En récompense de son travail contre Tyr, je lui ai donné le pays d’Égypte, parce qu’ils ont travaillé pour moi, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'En ce jour-là je ferai germer la corne de la maison d’Israël, et je te donnerai une bouche ouverte au milieu d’eux; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Fils d’homme, prophétise, et dis: Ainsi dit le Seigneur, l’ Éternel: Hurlez: Ah! quel jour!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Car le jour est proche; oui, le jour de l’ Éternel est proche, un jour de nuées: c’est le temps des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Et l’épée viendra sur l’Égypte, et il y aura de l’angoisse dans l’Éthiopie, quand ils tomberont blessés à mort en Égypte, et qu’on ôtera sa multitude, et que ses fondements seront détruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Cush, et Puth, et Lud, et tout le peuple mélangé, et Cub, et les fils du pays de l’alliance, tomberont par l’épée avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Ainsi dit l’ Éternel: Les appuis de l’Égypte tomberont, et l’orgueil de sa force sera abaissé; ils tomberont au milieu d’elle par l’épée, depuis Migdol à Syène, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Et ils seront désolés au milieu des pays désolés, et ses villes seront entre les villes dévastées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Et ils sauront que je suis l’ Éternel, quand j’aurai mis le feu en Égypte, et que tous ceux qui l’aident seront brisés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'En ce jour-là des messagers sortiront de devant moi sur des navires pour effrayer l’Éthiopie [dans sa] sécurité; et il y aura au milieu d’eux de l’angoisse comme au jour de l’Égypte; car voici, il vient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Ainsi dit le Seigneur, l’ Éternel: Je mettrai fin aussi à la multitude de l’Égypte par la main de Nebucadretsar, roi de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Lui, et son peuple avec lui, les terribles d’entre les nations, seront amenés pour détruire le pays; et ils tireront leurs épées contre l’Égypte, et rempliront le pays de blessés à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Et je mettrai les fleuves à sec, et je vendrai le pays en la main des méchants, et, par la main des étrangers, je désolerai le pays et tout ce qu’il contient. Moi, l’ Éternel, j’ai parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Ainsi dit le Seigneur, l’ Éternel: Je détruirai aussi les idoles, et je mettrai fin aux images de Noph; et il n’y aura plus de prince du pays d’Égypte; et je mettrai la frayeur dans le pays d’Égypte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'et je désolerai Pathros, et je mettrai le feu dans Tsoan, et j’exécuterai des jugements dans No;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'et je verserai ma fureur sur Sin, la forteresse de l’Égypte, et je retrancherai la multitude de No;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'et je mettrai le feu en Égypte; Sin sera dans une grande angoisse, et No sera ouverte par des brèches, et il y aura à Noph des ennemis en plein jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Les jeunes hommes d’Aven et de Pi-Béseth tomberont par l’épée, et elles-mêmes iront en captivité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Et à Takhpanès le jour sera obscurci lorsque j’y romprai le joug de l’Égypte, et que l’orgueil de sa force y aura cessé; une nuée la couvrira elle-même, et ses filles iront en captivité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Et j’exécuterai des jugements en Égypte; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Et il arriva, la onzième année, au premier [mois], le septième [jour] du mois, que la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Fils d’homme, j’ai cassé le bras du Pharaon, roi d’Égypte, et voici, il n’a point été bandé pour y appliquer des remèdes, pour y mettre des ligatures pour le bander, afin de le fortifier pour qu’il tienne l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Voici, j’en veux au Pharaon, roi d’Égypte, et je lui casserai les bras, celui qui est fort et celui qui est cassé, et je ferai tomber l’épée de sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Et je disperserai les Égyptiens parmi les nations et je les disséminerai dans les pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Et je fortifierai les bras du roi de Babylone, et je mettrai mon épée dans sa main; et je casserai les bras du Pharaon, et il gémira devant lui des gémissements d’un blessé à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Et je fortifierai les bras du roi de Babylone, et les bras du Pharaon tomberont. Et ils sauront que je suis l’ Éternel, quand j’aurai mis mon épée dans la main du roi de Babylone, et qu’il l’aura étendue sur le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Et je disperserai les Égyptiens parmi les nations, et je les disséminerai dans les pays; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Et il arriva, la onzième année, au troisième [mois], le premier [jour] du mois, que la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Fils d’homme, dis au Pharaon, roi d’Égypte, et à sa multitude: À qui es-tu semblable dans ta grandeur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Voici, Assur était un cèdre sur le Liban, beau par sa ramure, et touffu, donnant de l’ombre, et de haute taille, et sa cime était au milieu des rameaux feuillus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Les eaux l’ont fait grandir, l’abîme l’a élevé en hauteur; ses rivières coulaient autour de ses plants, et il envoyait ses canaux à tous les arbres des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'C’est pourquoi sa hauteur s’éleva par-dessus tous les arbres des champs, et ses branches se multiplièrent et ses rameaux s’allongèrent, parce qu’il poussait à cause des grandes eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Tous les oiseaux des cieux faisaient leurs nids dans ses rameaux, et toutes les bêtes des champs faisaient leurs petits sous ses branches, et toutes les nations nombreuses habitaient sous son ombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Et il était beau dans sa grandeur et dans la longueur de ses branches, parce que sa racine était auprès de grandes eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Les cèdres dans le jardin de Dieu ne le cachaient pas, les cyprès n’égalaient point ses rameaux, et les érables n’étaient pas comme ses branches; aucun arbre dans le jardin de Dieu ne lui était semblable en beauté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Je l’avais fait beau dans la multitude de ses branches, et tous les arbres d’Éden, qui étaient dans le jardin de Dieu, lui portaient envie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Parce que tu t’es élevé en hauteur..., et qu’il a dressé sa cime au milieu des rameaux feuillus et que son cœur s’est élevé dans sa hauteur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'je l’ai livré en la main du puissant des nations; il l’a traité à son gré. Je l’ai chassé à cause de son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Et des étrangers, les terribles d’entre les nations, l’ont coupé et l’ont laissé là; ses branches sont tombées sur les montagnes et dans toutes les vallées, et ses rameaux ont été brisés dans tous les ravins de la terre; et tous les peuples de la terre se sont retirés de dessous son ombre et l’ont laissé là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Tous les oiseaux des cieux demeurent sur son [tronc] renversé, et toutes les bêtes des champs sont sur ses branches;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'afin qu’aucun des arbres [plantés près] des eaux ne s’élève dans sa hauteur, et ne dresse sa cime au milieu des rameaux feuillus, et qu’aucun de ceux qui boivent des eaux ne se soutienne par lui-même dans sa hauteur; car eux tous sont livrés à la mort, [pour s’en aller] dans les lieux bas de la terre, au milieu des fils des hommes, vers ceux qui descendent dans la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Ainsi dit le Seigneur, l’ Éternel: Au jour de sa descente au shéol, je fis mener deuil; à cause de lui, je couvris l’abîme et j’en retins les fleuves, et les grandes eaux furent arrêtées; et à cause de lui, je mis en deuil le Liban, et tous les arbres des champs défaillirent à cause de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Du bruit de sa chute je fis trembler les nations, quand je le fis descendre dans le shéol avec ceux qui descendent dans la fosse; et tous les arbres d’Éden, l’élite et le meilleur du Liban, tous ceux qui buvaient des eaux, furent consolés dans les lieux bas de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Ceux-là aussi sont descendus avec lui dans le shéol, vers ceux qui ont été tués par l’épée, et [qui, étant] son bras, habitaient sous son ombre au milieu des nations. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'À qui es-tu semblable ainsi, en gloire et en grandeur, parmi les arbres d’Éden? Ainsi tu seras abaissé avec les arbres d’Éden jusque dans les lieux bas de la terre; tu seras couché, au milieu des incirconcis, avec ceux qui ont été tués par l’épée. C’est là le Pharaon et toute sa multitude, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Et il arriva, en la douzième année, au douzième mois, le premier [jour] du mois, que la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Fils d’homme, élève une complainte sur le Pharaon, le roi d’Égypte, et dis-lui: Tu étais semblable à un jeune lion parmi les nations, tu étais comme un monstre dans les eaux; et tu t’élançais dans tes fleuves, et tu troublais les eaux avec tes pieds, et tu rendais bourbeux leurs fleuves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Ainsi dit le Seigneur, l’ Éternel: J’étendrai sur toi mon rets par un rassemblement de peuples nombreux, et ils te feront monter avec mon filet;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'et je te laisserai là, sur la terre, je te jetterai sur la face des champs, et je ferai demeurer sur toi tous les oiseaux des cieux et je rassasierai de toi les bêtes de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Et je mettrai ta chair sur les montagnes, et je remplirai les vallées du monceau de tes membres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'et j’arroserai de ton sang le pays où tu nages, jusqu’aux montagnes; et les ravins seront remplis de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Et quand je t’éteindrai, je couvrirai les cieux, et j’obscurcirai leurs étoiles; je couvrirai le soleil de nuages, et la lune ne fera pas luire sa clarté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Tous les luminaires qui luisent dans les cieux, je les obscurcirai à cause de toi, et je mettrai les ténèbres sur ton pays, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Et je troublerai le cœur de beaucoup de peuples, quand je ferai parvenir [la nouvelle de] ta ruine parmi les nations, dans des pays que tu n’as pas connus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Et je frapperai de stupeur à cause de toi beaucoup de peuples; et leurs rois frémiront d’horreur à cause de toi, quand je brandirai mon épée devant eux, et ils trembleront à tout moment, chacun pour sa vie, au jour de ta chute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Car ainsi dit le Seigneur, l’ Éternel: L’épée du roi de Babylone viendra sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Par les épées des hommes forts je ferai tomber ta multitude; tous, ils sont les terribles d’entre les nations, et ils détruiront l’orgueil de l’Égypte, et toute sa multitude sera anéantie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Et je ferai périr tout son bétail d’auprès des grandes eaux; et le pied de l’homme ne les troublera plus, et l’ongle divisé du bétail ne les troublera plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Alors je rendrai leurs eaux limpides, et je ferai couler leurs rivières comme de l’huile, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Quand j’aurai fait du pays d’Égypte une désolation, et que le pays sera désolé, [vide] de ce qu’il contient, quand j’aurai frappé tous ceux qui y habitent, alors ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'C’est une complainte, et on la dira pour se lamenter; les filles des nations la diront en se lamentant, elles la diront en se lamentant sur l’Égypte et sur toute sa multitude, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Et il arriva, la douzième année, le quinzième [jour] du mois, que la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Fils d’homme, gémis sur la multitude de l’Égypte, et fais-la descendre, elle et les filles des nations magnifiques, dans les lieux bas de la terre, avec ceux qui descendent dans la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'À qui es-tu supérieure en agrément? Descends, et sois couchée avec les incirconcis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Ils tomberont parmi ceux qui ont été tués par l’épée; l’épée a été donnée; traînez l’Égypte et toute sa multitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Les forts d’entre les puissants, avec ceux qui l’avaient aidé, lui parleront du milieu du shéol; ils sont descendus, ils sont couchés, incirconcis, tués par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Là est Assur et toute son assemblée, ses sépulcres autour de lui: tous tués, tombés par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Ses sépulcres ont été posés au fond de la fosse, et son assemblée est autour de son sépulcre: tous tués, tombés par l’épée, eux qui répandaient la terreur sur la terre des vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Là est Élam, et toute sa multitude autour de son sépulcre: tous tués, tombés par l’épée; ils sont descendus incirconcis dans les lieux bas de la terre, eux qui répandaient leur terreur sur la terre des vivants, et qui ont porté leur confusion avec ceux qui sont descendus dans la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'On a mis sa couche au milieu des tués, avec toute sa multitude, ses sépulcres autour de lui: eux tous incirconcis, tués par l’épée, quoique leur terreur ait été répandue sur la terre des vivants; et ils portent leur confusion avec ceux qui descendent dans la fosse: il a été placé parmi les tués.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Là est Méshec, Tubal, et toute leur multitude, leurs sépulcres autour d’eux: eux tous incirconcis, tués par l’épée, quoiqu’ils aient répandu leur terreur sur la terre des vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Et ils n’ont pas été couchés avec les hommes forts, tombés d’entre les incirconcis, qui sont descendus dans le shéol avec leurs instruments de guerre, et sous la tête desquels on a mis leurs épées, et dont les iniquités sont sur leurs os; quoiqu’ils aient été la terreur des hommes forts sur la terre des vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Toi aussi, tu as été brisée au milieu des incirconcis, et tu es couchée avec ceux qui ont été tués par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Là est Édom, ses rois, et tous ses princes, qui, dans leur vaillance, ont été placés avec ceux qui ont été tués par l’épée; ils sont couchés avec les incirconcis et avec ceux qui sont descendus dans la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Là sont les princes du nord, eux tous, et tous les Sidoniens, qui sont descendus avec les tués, honteux de la terreur qu’ils répandaient par leur vaillance; et ils sont couchés incirconcis avec ceux qui ont été tués par l’épée, et ils portent leur confusion avec ceux qui sont descendus dans la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Le Pharaon les verra, et il sera consolé au sujet de toute sa multitude, le Pharaon et toute son armée, tués par l’épée, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Car j’ai répandu ma terreur dans la terre des vivants; et il sera couché au milieu des incirconcis, avec ceux qui ont été tués par l’épée, le Pharaon, et toute sa multitude, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, '**Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Fils d’homme, parle aux fils de ton peuple, et dis-leur: Si je fais venir l’épée sur un pays, et que le peuple du pays prenne un homme d’entre eux tous, et se le donne pour sentinelle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'et qu’il voie venir l’épée sur le pays, et sonne de la trompette, et avertisse le peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'et que quelqu’un entende bien le son de la trompette, mais ne reçoive pas l’avertissement, et que l’épée vienne et le saisisse, son sang sera sur sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Il a entendu le son de la trompette, et n’a pas reçu l’avertissement: son sang est sur lui; alors que s’il avait reçu l’avertissement, il aurait délivré son âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Mais si la sentinelle voit venir l’épée, et ne sonne pas de la trompette, et que le peuple ne soit pas averti, et que l’épée vienne et saisisse quelqu’un d’entre eux, lui est saisi dans son iniquité; mais je redemanderai son sang de la main de la sentinelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Et toi, fils d’homme, je t’ai établi sentinelle pour la maison d’Israël, et tu entendras la parole de ma bouche, et tu les avertiras de ma part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Quand je dirai au méchant: Méchant, certainement tu mourras! et que tu ne parleras pas pour avertir le méchant à l’égard de sa voie, lui, le méchant, mourra dans son iniquité; mais je redemanderai son sang de ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Et si tu avertis le méchant à l’égard de sa voie, pour qu’il s’en détourne, et qu’il ne se détourne pas de sa voie, il mourra, lui, dans son iniquité; mais toi, tu as délivré ton âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Et toi, fils d’homme, dis à la maison d’Israël: Vous avez parlé ainsi, disant: Nos transgressions et nos péchés sont sur nous, et nous sommes consumés par eux, et comment vivrions-nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Dis-leur: Je suis vivant, dit le Seigneur, l’ Éternel, si je prends plaisir en la mort du méchant,... mais [plutôt] à ce que le méchant se détourne de sa voie et qu’il vive! Détournez-vous, détournez-vous de vos mauvaises voies; et pourquoi mourriez-vous, maison d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Et toi, fils d’homme, dis aux fils de ton peuple: La justice du juste ne le délivrera pas, au jour de sa transgression; et la méchanceté du méchant ne le fera pas tomber, au jour où il se détournera de sa méchanceté; et le juste ne pourra pas vivre par sa justice, au jour où il péchera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Quand j’aurai dit au juste que certainement il vivra, et que lui se confie en sa justice et commette l’iniquité, de tous ses actes justes, aucun ne viendra en mémoire, mais dans son iniquité qu’il a commise il mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Et quand j’aurai dit au méchant: Certainement tu mourras,... s’il se détourne de son péché, et pratique le jugement et la justice;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'si le méchant rend le gage, restitue ce qu’il a pillé, marche dans les statuts de la vie, en ne commettant pas l’iniquité, certainement il vivra, il ne mourra pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'De tous ses péchés qu’il a commis, aucun ne viendra en mémoire contre lui: il a pratiqué le jugement et la justice; certainement il vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Et les fils de ton peuple disent: La voie du Seigneur n’est pas réglée; mais c’est eux dont la voie n’est pas réglée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Quand le juste se détournera de sa justice et pratiquera l’iniquité, il en mourra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Et quand le méchant se détournera de sa méchanceté et pratiquera le jugement et la justice, il vivra à cause de cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Et vous dites: La voie du Seigneur n’est pas réglée. Je vous jugerai, chacun selon ses voies, maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, '*Et il arriva, la douzième année de notre transportation, au dixième [mois], le cinquième [jour] du mois, qu’un réchappé de Jérusalem vint vers moi, disant: La ville est frappée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Et la main de l’ Éternel avait été sur moi le soir avant que vienne le réchappé, et elle avait ouvert ma bouche jusqu’à ce qu’il vienne vers moi le matin; ainsi ma bouche fut ouverte, et je ne fus plus muet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Fils d’homme, les habitants de ces lieux désolés, sur la terre d’Israël, parlent, disant: Abraham était un seul, et il a hérité le pays; et nous sommes plusieurs, le pays nous est donné pour héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'C’est pourquoi dis-leur: Ainsi dit le Seigneur, l’ Éternel: Vous mangez avec le sang, et vous levez vos yeux vers vos idoles, et vous versez le sang: et vous hériteriez le pays?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Vous vous roidissez sur votre épée, vous commettez des abominations, et vous rendez impure, chacun de vous, la femme de son prochain: et vous hériteriez le pays?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Tu leur diras ainsi: Ainsi dit le Seigneur, l’ Éternel: Je suis vivant, si ceux qui sont dans les lieux désolés ne tombent par l’épée; et si je ne livre aux bêtes celui qui est par les champs, afin qu’elles le dévorent; et si ceux qui sont dans les lieux forts et dans les cavernes ne meurent de la peste!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Et je réduirai le pays en désolation et en désert; et l’orgueil de sa force cessera; et les montagnes d’Israël seront dévastées, de sorte que personne n’y passera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Et ils sauront que je suis l’ Éternel, quand j’aurai réduit le pays en désolation et en désert, à cause de toutes leurs abominations qu’ils ont commises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Et toi, fils d’homme, les fils de ton peuple parlent contre toi auprès des murs et aux entrées des maisons, et ils parlent l’un avec l’autre, chacun avec son frère, disant: Venez donc, et écoutez quelle est la parole qui est sortie de la part de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Et ils viennent vers toi comme vient un peuple, et ils s’asseyent devant toi [comme étant] mon peuple; et ils entendent tes paroles, mais ils ne les pratiquent pas; car de leur bouche ils disent des choses agréables, [mais] leur cœur va après leur gain déshonnête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Et voici, tu es pour eux comme un chant agréable, une belle voix, et quelqu’un qui joue bien; et ils entendent tes paroles, mais ils ne les pratiquent nullement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Et quand la chose arrivera (la voici qui arrive), alors ils sauront qu’il y a eu un prophète au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Fils d’homme, prophétise contre les pasteurs d’Israël; prophétise, et dis-leur, à ces pasteurs: Ainsi dit le Seigneur, l’ Éternel: Malheur aux pasteurs d’Israël, qui se paissent eux-mêmes! Les pasteurs ne doivent-ils pas paître le troupeau?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Vous mangez la graisse, et vous vous habillez de la laine; vous égorgez ce qui est engraissé; vous ne paissez pas le troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Vous n’avez pas fortifié les [brebis] faibles, et vous n’avez pas guéri celle qui était malade, et vous n’avez pas bandé celle qui était blessée, et vous n’avez pas ramené celle qui était égarée, et vous n’avez pas cherché celle qui était perdue; mais vous les avez gouvernées avec dureté et rigueur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Et elles ont été dispersées, parce qu’il n’y avait pas de pasteur, et elles étaient la pâture de toutes les bêtes des champs, et elles ont été dispersées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Mes brebis ont erré dans toutes les montagnes et sur toute haute colline, et mes brebis ont été dispersées sur toute la face du pays, et il n’y a eu personne qui les ait recherchées, personne qui se soit enquis d’elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'C’est pourquoi, pasteurs, écoutez la parole de l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Je suis vivant, dit le Seigneur, l’ Éternel: parce que mes brebis ont été une proie, et que mes brebis ont été la pâture de toutes les bêtes des champs, faute de pasteur, et que mes pasteurs n’ont pas cherché mes brebis, mais que les pasteurs se paissaient eux-mêmes, et ne paissaient pas mes brebis!...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'C’est pourquoi, pasteurs, écoutez la parole de l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Ainsi dit le Seigneur, l’ Éternel: Voici, j’en veux à ces pasteurs, et je réclamerai mes brebis de leur main; je les ferai cesser de paître le troupeau, et les pasteurs ne se paîtront plus eux-mêmes; et je délivrerai mes brebis de leur bouche, et ils ne les mangeront plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Car, ainsi dit le Seigneur, l’ Éternel: Me voici, moi, et je rechercherai mes brebis, et j’en prendrai soin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Comme un berger prend soin de son troupeau au jour où il est au milieu de ses brebis dispersées, ainsi je prendrai soin de mes brebis, et je les sauverai de tous les lieux où elles ont été dispersées au jour de la nuée et de l’obscurité profonde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Et je les ferai sortir d’entre les peuples, et je les rassemblerai des pays, et les amènerai dans leur terre; et je les paîtrai sur les montagnes d’Israël, auprès des ruisseaux et dans toutes les habitations du pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'je les ferai paître dans un bon pâturage, et leur parc sera dans les hautes montagnes d’Israël; elles seront là, couchées dans un bon parc, et paîtront dans de gras pâturages, sur les montagnes d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Moi-même je paîtrai mes brebis, et moi je les ferai reposer, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'La perdue, je la chercherai, et l’égarée, je la ramènerai, et la blessée, je la banderai, et la malade, je la fortifierai; mais je détruirai la grasse et la forte. Je les paîtrai avec jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Mais vous, mon troupeau, – ainsi dit le Seigneur, l’ Éternel: Voici, je juge entre brebis et brebis, entre béliers et boucs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Est-ce trop peu pour vous de brouter le bon pâturage, pour que vous fouliez avec vos pieds le reste de votre pâturage; – et de boire les eaux limpides, pour que vous troubliez le reste avec vos pieds?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Et mes brebis ont pour pâture ce que vos pieds ont foulé, et elles boivent ce que vos pieds ont troublé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'C’est pourquoi, ainsi leur dit le Seigneur, l’ Éternel: Me voici, moi; et je jugerai entre la brebis grasse et la brebis maigre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Parce que vous poussez du côté et de l’épaule, et que vous heurtez de vos cornes toutes les [brebis] faibles, jusqu’à ce que vous les ayez dispersées au-dehors,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'je sauverai mes brebis, et elles ne seront plus une proie, et je jugerai entre brebis et brebis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Et je susciterai sur eux un pasteur qui les paîtra, mon serviteur David: lui les paîtra, et lui sera leur pasteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Et moi, l’ Éternel, je serai leur Dieu, et mon serviteur David sera prince au milieu d’eux. Moi, l’ Éternel, j’ai parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Et je ferai avec eux une alliance de paix, et je mettrai fin aux bêtes mauvaises dans le pays; et ils habiteront dans le désert en sécurité, et dormiront dans les forêts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Et d’eux et des alentours de ma colline, je ferai une bénédiction; et je ferai tomber la pluie en son temps: ce seront des pluies de bénédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Et l’arbre des champs donnera son fruit, et la terre donnera son rapport; et ils seront dans leur terre en sécurité, et sauront que je suis l’ Éternel, quand j’aurai brisé les liens de leur joug, et que je les aurai sauvés de la main de ceux qui les tenaient asservis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Et ils ne seront plus en proie aux nations, et les bêtes de la terre ne les dévoreront plus; mais ils habiteront en sécurité, et il n’y aura personne qui les effraie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Et je leur susciterai un plant de renom; et ils ne seront plus enlevés par la famine dans le pays, et ils ne porteront plus l’ignominie des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Et ils sauront que moi, l’ Éternel, leur Dieu, je suis avec eux, et qu’eux, la maison d’Israël, ils sont mon peuple, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Et vous, mon troupeau, le troupeau de ma pâture, vous êtes des hommes; moi, je suis votre Dieu, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Fils d’homme, tourne ta face contre la montagne de Séhir, et prophétise contre elle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'et dis-lui: Ainsi dit le Seigneur, l’ Éternel: Voici, j’en veux à toi, montagne de Séhir; et j’étendrai ma main sur toi, et je te réduirai en désolation et en désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Je réduirai tes villes en déserts, et tu seras une désolation; et tu sauras que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Parce que tu as eu une inimitié perpétuelle, et que tu as livré les fils d’Israël à la puissance de l’épée, au temps de leur calamité, au temps de l’iniquité de la fin:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'à cause de cela, je suis vivant, dit le Seigneur, l’ Éternel, que je te mettrai à sang, et le sang te poursuivra; puisque tu n’as pas haï le sang, le sang te poursuivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Et je réduirai en désolation et en désert la montagne de Séhir, et j’en retrancherai les allants et les venants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'et je remplirai ses montagnes de ses tués. Des tués par l’épée tomberont sur tes collines, et dans tes vallées, et dans tous tes ravins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Je te réduirai en désolations perpétuelles, et tes villes ne seront plus habitées; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Parce que tu as dit: Les deux nations et les deux pays seront à moi, et nous les posséderons; – et l’ Éternel y était;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'à cause de cela, je suis vivant, dit le Seigneur, l’ Éternel, que j’agirai selon ta colère et selon ta jalousie, comme tu as agi à cause de ta haine contre eux; et je me ferai connaître parmi eux, quand je t’aurai jugé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Et tu sauras que moi, l’ Éternel, j’ai entendu tous tes outrages que tu as proférés contre les montagnes d’Israël, disant: Elles sont désolées, elles nous sont données pour les dévorer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Et vous vous êtes, de votre bouche, élevés contre moi, et vous avez multiplié contre moi vos paroles; moi, je l’ai entendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Ainsi dit le Seigneur, l’ Éternel: Quand toute la terre se réjouira, je te réduirai en désolation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Comme tu t’es réjouie sur l’héritage de la maison d’Israël, parce qu’il a été désolé, j’en ferai de même envers toi; tu seras une désolation, montagne de Séhir, et Édom tout entier; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Et toi, fils d’homme, prophétise touchant les montagnes d’Israël et dis: Montagnes d’Israël, écoutez la parole de l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Ainsi dit le Seigneur, l’ Éternel: Parce que l’ennemi a dit contre vous: Ha ha! les hauteurs éternelles sont devenues notre possession;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'c’est pourquoi, prophétise et dis: Ainsi dit le Seigneur, l’ Éternel: Parce que, oui, parce qu’on vous a désolées, et qu’on vous a englouties de toutes parts, afin que vous soyez la possession du reste des nations, et que vous avez été en butte au bavardage de la langue et aux mauvais propos des hommes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'à cause de cela, montagnes d’Israël, écoutez la parole du Seigneur, l’ Éternel: Ainsi dit le Seigneur, l’ Éternel, aux montagnes et aux collines, aux ravins et aux vallées, et aux lieux déserts [et] désolés, et aux villes abandonnées, qui ont été la proie et la raillerie du reste des nations qui sont tout alentour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'à cause de cela, ainsi dit le Seigneur, l’ Éternel: Si je ne parle dans le feu de ma jalousie contre le reste des nations, et contre Édom tout entier, qui se sont attribué mon pays comme une possession, dans toute la joie de leur cœur, dans le mépris de leurs âmes, afin de la dépouiller par le pillage!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'C’est pourquoi, prophétise touchant la terre d’Israël, et dis aux montagnes et aux collines, aux ravins et aux vallées: Ainsi dit le Seigneur, l’ Éternel: Voici, j’ai parlé dans ma jalousie et dans ma fureur, parce que vous avez porté l’ignominie des nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'c’est pourquoi, ainsi dit le Seigneur, l’ Éternel: J’ai levé ma main, si les nations qui sont autour de vous ne portent elles-mêmes leur ignominie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Mais vous, montagnes d’Israël, vous pousserez vos branches, et vous porterez votre fruit pour mon peuple Israël, car ils sont près de venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Car voici, [je pense] à vous, et je me tourne vers vous: vous serez labourées et vous serez semées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Et je multiplierai sur vous les hommes, la maison d’Israël tout entière; et les villes seront habitées, et les lieux désolés seront rebâtis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'et je multiplierai sur vous les hommes et les bêtes, et ils multiplieront et fructifieront; et je ferai que vous serez habitées comme en vos temps d’autrefois, et je [vous] ferai plus de bien que lors de votre commencement; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Et je ferai marcher sur vous des hommes, mon peuple Israël; et ils te posséderont, et tu seras leur héritage, et tu ne les priveras plus d’enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Ainsi dit le Seigneur, l’ Éternel: Parce qu’on dit de vous: Tu dévores les hommes, et tu prives d’enfants ta nation;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'c’est pourquoi tu ne dévoreras plus les hommes, et tu ne priveras plus d’enfants ta nation, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Et je ne te ferai plus entendre les insultes des nations; et tu ne porteras plus l’opprobre des peuples, et tu ne feras plus choir ta nation, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Fils d’homme, la maison d’Israël habitait sa terre, et ils l’ont rendue impure par leur voie et par leurs actions; leur voie a été devant moi comme l’impureté d’une femme séparée à cause de ses mois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'et je versai ma fureur sur eux, à cause du sang qu’ils avaient versé sur le pays, et parce qu’ils l’avaient rendu impur par leurs idoles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'et je les dispersai parmi les nations, et ils furent disséminés dans les pays: je les jugeai selon leur voie et selon leurs actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Et ils vinrent chez les nations où ils sont venus, et ils profanèrent mon saint nom, en ce qu’on disait d’eux: C’est ici le peuple de l’ Éternel, et ils sont sortis de son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Mais j’ai épargné mon saint nom, que la maison d’Israël profana parmi les nations où ils sont venus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'C’est pourquoi, dis à la maison d’Israël: Ainsi dit le Seigneur, l’ Éternel: Ce n’est point à cause de vous, maison d’Israël, que je le fais, mais c’est à cause de mon saint nom, que vous avez profané parmi les nations où vous êtes venus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Et je sanctifierai mon grand nom, qui a été profané parmi les nations, [et] que vous avez profané au milieu d’elles; et les nations sauront que je suis l’ Éternel, dit le Seigneur, l’ Éternel, quand je serai sanctifié en vous, à leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Et je vous prendrai d’entre les nations, et je vous rassemblerai de tous les pays, et je vous amènerai sur votre terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'et je répandrai sur vous des eaux pures, et vous serez purs: je vous purifierai de toutes vos impuretés et de toutes vos idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Et je vous donnerai un cœur nouveau, et je mettrai au-dedans de vous un esprit nouveau; et j’ôterai de votre chair le cœur de pierre, et je vous donnerai un cœur de chair;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'et je mettrai mon Esprit au-dedans de vous, et je ferai que vous marchiez dans mes statuts, et que vous gardiez mes ordonnances et les pratiquiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Et vous habiterez dans le pays que j’ai donné à vos pères, et vous serez mon peuple, et moi je serai votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Et je vous délivrerai de toutes vos impuretés. Et j’appellerai le blé, et je le multiplierai, et je ne vous enverrai pas la famine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'et je multiplierai le fruit des arbres et le produit des champs, afin que vous ne portiez plus l’opprobre de la famine parmi les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Et vous vous souviendrez de vos mauvaises voies et de vos actions qui ne sont pas bonnes, et vous aurez horreur de vous-mêmes à cause de vos iniquités et à cause de vos abominations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Ce n’est point à cause de vous que je le fais, dit le Seigneur, l’ Éternel: sachez-le. Soyez honteux et soyez confus à cause de vos voies, maison d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Ainsi dit le Seigneur, l’ Éternel: Au jour où je vous purifierai de toutes vos iniquités, je ferai que les villes seront habitées, et les lieux désolés seront rebâtis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'et le pays désert sera labouré, au lieu d’être une désolation aux yeux de tous les passants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Et ils diront: Ce pays qui était désolé, est devenu comme le jardin d’Éden; et les villes ruinées et désertes et renversées sont fortifiées et habitées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Et les nations qui demeureront de reste autour de vous, sauront que moi, l’ Éternel, j’ai rebâti les [villes] renversées, j’ai planté ce qui était désolé. Moi, l’ Éternel, j’ai parlé, et je le ferai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Ainsi dit le Seigneur, l’ Éternel: Encore en ceci je serai recherché par la maison d’Israël, pour le leur faire: je les multiplierai comme un troupeau d’hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Comme un troupeau saint, comme un troupeau de Jérusalem dans ses fêtes solennelles, ainsi les villes ruinées seront remplies de troupeaux d’hommes; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, '*La main de l’ Éternel fut sur moi, et l’ Éternel me fit sortir en esprit, et me posa au milieu de la plaine; et elle était remplie d’ossements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'et il me fit passer auprès d’eux, tout autour; et voici, ils étaient fort nombreux sur la face de la plaine; et voici, ils étaient très secs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Et il me dit: Fils d’homme, ces os revivront-ils? Et je dis: Seigneur Éternel! tu le sais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Et il me dit: Prophétise sur ces os, et dis-leur: Os secs, écoutez la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Ainsi dit le Seigneur, l’ Éternel, à ces os: Voici, je fais venir en vous le souffle, et vous vivrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Et je mettrai sur vous des nerfs, et je ferai venir sur vous de la chair, et je vous recouvrirai de peau; et je mettrai en vous le souffle, et vous vivrez; et vous saurez que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Et je prophétisai selon qu’il m’avait été commandé; et comme je prophétisais, il y eut un bruit, et voici, il se fit un mouvement, et les os se rapprochèrent, un os de son os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Et je vis, et voici, il vint sur eux des nerfs et de la chair, et de la peau les recouvrit par-dessus; mais il n’y avait pas de souffle en eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Et il me dit: Prophétise au souffle, prophétise, fils d’homme, et dis au souffle: Ainsi dit le Seigneur, l’ Éternel: Esprit, viens des quatre vents, et souffle sur ces tués, et qu’ils vivent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Et je prophétisai selon qu’il m’avait commandé; et le souffle entra en eux, et ils vécurent, et se tinrent sur leurs pieds, – une immense armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Et il me dit: Fils d’homme, ces os sont toute la maison d’Israël. Voici, ils disent: Nos os sont desséchés, et notre attente a péri; nous sommes retranchés!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'C’est pourquoi prophétise, et dis-leur: Ainsi dit le Seigneur, l’ Éternel: Voici, j’ouvrirai vos sépulcres, et je vous ferai monter hors de vos sépulcres, mon peuple, et je vous amènerai dans la terre d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Et vous saurez que je suis l’ Éternel, quand j’aurai ouvert vos sépulcres, et que je vous aurai fait monter hors de vos sépulcres, mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Et je mettrai mon Esprit en vous, et vous vivrez, et je vous placerai sur votre terre; et vous saurez que c’est moi, l’ Éternel, qui ai parlé et qui l’ai fait, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Et toi, fils d’homme, prends un bois, et écris dessus: Pour Juda, et pour les fils d’Israël, ses compagnons. Et prends un autre bois, et écris dessus: Pour Joseph, le bois d’Éphraïm et de toute la maison d’Israël, ses compagnons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Et rapproche-les l’un de l’autre, pour qu’ils soient un seul bois, et ils ne seront qu’un dans ta main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Et quand les fils de ton peuple te parleront, disant: Ne nous déclareras-tu pas ce que signifient pour toi ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'dis-leur: Ainsi dit le Seigneur, l’ Éternel: Voici, je prendrai le bois de Joseph, qui est dans la main d’Éphraïm, et les tribus d’Israël, ses compagnons; et je les mettrai sur celui-ci, [savoir] sur le bois de Juda, et je les ferai être un seul bois, et ils seront un dans ma main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Et les bois sur lesquels tu auras écrit seront dans ta main, sous leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Et dis-leur: Ainsi dit le Seigneur, l’ Éternel: Voici, je prendrai les fils d’Israël d’entre les nations où ils sont allés, et je les rassemblerai de toutes parts, et je les ferai entrer dans leur terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'et je les ferai être une seule nation dans le pays, sur les montagnes d’Israël: un seul roi sera leur roi à tous; et ils ne seront plus deux nations, et ils ne seront plus divisés en deux royaumes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Et ils ne se rendront plus impurs par leurs idoles, et par leurs choses exécrables, et par toutes leurs transgressions; et je les délivrerai de toutes leurs habitations où ils ont péché, et je les purifierai; et ils seront mon peuple, et moi je serai leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Et mon serviteur David sera roi sur eux, et il y aura un seul pasteur pour eux tous; et ils marcheront dans mes ordonnances, et ils garderont mes statuts et les pratiqueront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Et ils habiteront dans le pays que j’ai donné à mon serviteur Jacob, où vos pères ont habité; et ils y habiteront, eux et leurs fils, et les fils de leurs fils, à toujours; et David mon serviteur sera leur prince à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Et je ferai avec eux une alliance de paix, ce sera, avec eux, une alliance éternelle; et je les établirai, et je les multiplierai, et je mettrai mon sanctuaire au milieu d’eux pour toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'et ma demeure sera sur eux; et je serai leur Dieu, et ils seront mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Et les nations sauront que moi je suis l’ Éternel qui sanctifie Israël, quand mon sanctuaire sera au milieu d’eux à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, '*Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Fils d’homme, tourne ta face vers Gog, le pays de Magog, [le] prince de Rosh, de Méshec et de Tubal, et prophétise contre lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'et dis: Ainsi dit le Seigneur, l’ Éternel: Voici, j’en veux à toi, Gog, prince de Rosh, de Méshec et de Tubal!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'et je te ferai retourner, et je mettrai un anneau dans tes mâchoires, et je te ferai sortir, toi et toute ton armée, chevaux et cavaliers, tous parfaitement équipés, un grand rassemblement, avec le bouclier et l’écu, tous portant l’épée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'avec eux la Perse, Cush, et Puth, ayant tous des boucliers et des casques;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomer et toutes ses bandes; la maison de Togarma, du fond du nord, et toutes ses bandes, – beaucoup de peuples avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Prépare-toi, et tiens-toi prêt, toi et tout ton rassemblement qui est assemblé auprès de toi, et sois leur chef.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Après beaucoup de jours tu seras visité: à la fin des années tu viendras dans le pays délivré de l’épée [et] rassemblé d’entre beaucoup de peuples, sur les montagnes d’Israël qui ont été une désolation perpétuelle, vers ceux qui sont sortis d’entre les peuples et qui habitent tous en sécurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Et tu monteras, tu viendras comme une tempête, tu seras comme une nuée pour couvrir le pays, toi et toutes tes bandes, et beaucoup de peuples avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Ainsi dit le Seigneur, l’ Éternel: Il arrivera en ce jour-là, que des choses monteront dans ton cœur et que tu concevras une mauvaise pensée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'et tu diras: Je monterai dans un pays de villes ouvertes, je viendrai vers ceux qui sont tranquilles, qui habitent en sécurité, qui tous habitent là où il n’y a pas de murailles et chez qui il n’y a ni barres ni portes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'pour emporter un butin et faire un pillage, pour tourner ta main sur des lieux désolés [de nouveau] habités, et sur un peuple rassemblé d’entre les nations, qui a acquis du bétail et des biens, et habite le centre du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Sheba, et Dedan, et les marchands de Tarsis, et tous ses lionceaux, te diront: Est-ce pour emporter un butin que tu es venu? est-ce pour faire le pillage que tu as assemblé ton rassemblement [de peuples], pour enlever de l’argent et de l’or, pour prendre le bétail et les biens, pour emporter un grand butin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'C’est pourquoi, fils d’homme, prophétise, et dis à Gog: Ainsi dit le Seigneur, l’ Éternel: En ce jour-là, quand mon peuple Israël habitera en sécurité, ne le sauras-tu pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Et tu viendras de ton lieu, du fond du nord, toi et beaucoup de peuples avec toi, tous montés sur des chevaux, un grand rassemblement et une nombreuse armée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'et tu monteras contre mon peuple Israël comme une nuée, pour couvrir le pays. Ce sera à la fin des jours; et je te ferai venir sur mon pays, afin que les nations me connaissent, quand je serai sanctifié en toi, ô Gog! devant leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Ainsi dit le Seigneur, l’ Éternel: N’es-tu pas celui dont j’ai parlé dans les jours d’autrefois, par mes serviteurs les prophètes d’Israël, qui, en ces jours-là, pendant des années, ont prophétisé que je te ferais venir contre eux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Et il arrivera en ce jour-là, au jour où Gog viendra contre la terre d’Israël, dit le Seigneur, l’ Éternel, que ma fureur me montera au visage; –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'et je parle dans ma jalousie, dans le feu de mon courroux: Oui, en ce jour-là, il y aura une grande commotion sur la terre d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'et les poissons de la mer, et les oiseaux des cieux, et les bêtes des champs, trembleront devant moi, et tout ce qui rampe sur la terre, et tout homme qui est sur la face de la terre; et les montagnes seront renversées, et les hauts rochers s’écrouleront, et toutes les murailles tomberont par terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Et j’appellerai contre lui l’épée sur toutes mes montagnes, dit le Seigneur, l’ Éternel; l’épée de chacun sera contre son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Et j’entrerai en jugement avec lui par la peste et par le sang; et je ferai pleuvoir une pluie torrentielle, et des pierres de grêle, du feu et du soufre, sur lui et sur ses bandes, et sur les peuples nombreux qui seront avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Et je me glorifierai et je me sanctifierai, et je serai connu aux yeux de beaucoup de nations; et elles sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Et toi, fils d’homme, prophétise contre Gog, et dis: Ainsi dit le Seigneur, l’ Éternel: Voici, j’en veux à toi, Gog, prince de Rosh, de Méshec et de Tubal;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'et je te ferai retourner, et je te mènerai, et je te ferai monter du fond du nord, et je te ferai venir sur les montagnes d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Et j’abattrai ton arc de ta main gauche, et je ferai tomber tes flèches de ta main droite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'tu tomberas sur les montagnes d’Israël, toi et toutes tes bandes, et les peuples qui seront avec toi; je te donnerai en pâture aux oiseaux de proie de toute aile, et aux bêtes des champs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'tu tomberas sur la face des champs; car moi, j’ai parlé, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Et j’enverrai un feu en Magog et parmi ceux qui habitent les îles en sécurité; et ils sauront que je suis l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Et je ferai connaître mon saint nom au milieu de mon peuple Israël, et je ne profanerai plus mon saint nom; et les nations sauront que je suis l’ Éternel, le Saint en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Voici, cela vient et s’accomplit, dit le Seigneur, l’ Éternel: c’est ici le jour dont j’ai parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Et les habitants des villes d’Israël sortiront et allumeront du feu, et brûleront les armes, et les écus, et les boucliers avec les arcs, et les flèches, et les épieux, et les piques; et ils en feront du feu pendant sept ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Et ils n’apporteront point de bois des champs et ils n’en couperont point des forêts, car ils feront du feu avec des armes; et ils butineront ceux qui les ont butinés, et ils pilleront ceux qui les ont pillés, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Et il arrivera, en ce jour-là, que je donnerai là à Gog un lieu pour sépulcre en Israël, la vallée des passants, à l’orient de la mer; et le chemin sera [ainsi] fermé aux passants, et on enterrera là Gog et toute la multitude; et on l’appellera la vallée de Hamon-Gog.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Et la maison d’Israël les enterrera pendant sept mois, pour purifier le pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'et tout le peuple du pays les enterrera; et ce sera un renom pour eux, le jour où je me glorifierai, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Et ils mettront à part, pour un [service] continuel, des hommes qui parcourront le pays [et] qui, avec les passants, enterreront ceux qui seront demeurés sur la face du pays, pour le purifier: au bout de sept mois ils en chercheront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Et les passants passeront par le pays, et s’ils voient un ossement d’homme, ils élèveront à côté de lui un signal, jusqu’à ce que les enterreurs l’aient enterré dans la vallée de Hamon-Gog;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'et le nom de la ville aussi sera Hamona. Ainsi on purifiera le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Et toi, fils d’homme, ainsi dit le Seigneur, l’ Éternel: Dis aux oiseaux de toute aile, et à toutes les bêtes des champs: Assemblez-vous et venez, réunissez-vous de toutes parts vers mon sacrifice que je sacrifie pour vous, un grand sacrifice sur les montagnes d’Israël, et mangez de la chair et buvez du sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Vous mangerez la chair des forts, et vous boirez le sang des princes de la terre, – des béliers, des agneaux, des boucs, des bœufs, tous, bêtes grasses de Basan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Vous mangerez de la graisse à satiété, et vous boirez du sang à en être enivrés, du sacrifice que j’ai sacrifié pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Et à ma table vous serez rassasiés de chevaux et d’attelages, d’hommes forts et de toute sorte d’hommes de guerre, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Et je mettrai ma gloire parmi les nations; et toutes les nations verront mon jugement, que j’aurai exécuté, et ma main, que j’aurai mise sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Et la maison d’Israël saura que je suis l’ Éternel, leur Dieu, dès ce jour-là et dans la suite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Et les nations sauront que la maison d’Israël est allée en captivité à cause de son iniquité, parce qu’ils ont été infidèles envers moi, et que je leur avais caché ma face, et que je les avais livrés en la main de leurs ennemis; et ils sont tous tombés par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Je leur ai fait selon leur impureté et selon leurs transgressions, et je leur ai caché ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: Maintenant je rétablirai les captifs de Jacob et j’aurai compassion de toute la maison d’Israël, et je serai jaloux de mon saint nom,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'et ils porteront [en eux] leur confusion, et toutes leurs infidélités par lesquelles ils ont été infidèles envers moi, alors qu’ils habiteront en sécurité dans leur terre et qu’il n’y aura personne qui les effraie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'quand je les aurai ramenés d’entre les peuples et que je les aurai rassemblés des pays de leurs ennemis, et que je serai sanctifié en eux aux yeux de beaucoup de nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Et ils sauront que je suis l’ Éternel, leur Dieu, parce que je les ai emmenés captifs parmi les nations, et que je les aurai rassemblés dans leur terre, et que je n’en aurai laissé là aucun de reste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Et je ne leur cacherai plus ma face, parce que j’aurai répandu mon Esprit sur la maison d’Israël, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, '***En la vingt-cinquième année de notre transportation, au commencement de l’année, le dixième [jour] du mois, en la quatorzième année après que la ville eut été frappée, en ce même jour, la main de l’ Éternel fut sur moi, et il m’amena là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Dans les visions de Dieu, il m’amena au pays d’Israël, et me posa sur une très haute montagne; et sur elle il y avait comme une ville bâtie, du côté du midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Et il m’amena là, et voici un homme dont l’aspect était comme l’aspect de l’airain; et [il avait] dans sa main un cordeau de lin et une canne à mesurer, et il se tenait dans la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Et l’homme me dit: Fils d’homme, regarde de tes yeux, et écoute de tes oreilles, et applique ton cœur à tout ce que je te fais voir; car c’est afin de te le faire voir que tu as été amené ici. Déclare à la maison d’Israël tout ce que tu vois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Et voici, en dehors de la maison, un mur tout à l’entour, et, dans la main de l’homme, une canne à mesurer de six coudées, ayant [chacune] une coudée et une paume. Et il mesura la largeur de la construction, une canne, et la hauteur, une canne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Et il vint à la porte qui regardait vers l’orient, et il monta par ses degrés; et il mesura le seuil de la porte, une canne en largeur, et l’autre seuil, une canne en largeur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'et [chaque] chambre, une canne en longueur et une canne en largeur; et entre les chambres, cinq coudées; et le seuil de la porte, du côté du portique de la porte, en dedans, une canne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Et il mesura le portique de la porte, en dedans, une canne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Et il mesura le portique de la porte, huit coudées, et ses piliers, deux coudées; et le portique de la porte était vers l’intérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Et les chambres de la porte qui [regardait] vers l’orient étaient trois deçà et trois delà: elles avaient, les trois, une seule mesure, et les piliers deçà et delà, une seule mesure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Et il mesura la largeur de l’entrée de la porte, dix coudées, [et] la longueur de la porte, 13 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Et il y avait devant les chambres une banquette d’une coudée, et une banquette d’une coudée de [l’autre] côté; et [chaque] chambre avait six coudées deçà et six coudées delà.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Et il mesura la porte depuis le toit d’une chambre jusqu’au toit [de l’autre chambre], une largeur de 25 coudées, entrée vis-à-vis d’entrée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Et il fit des piliers, 60 coudées; et à côté du pilier était le parvis, tout autour de la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Et depuis le devant de la porte d’entrée jusqu’au devant du portique de la porte intérieure, 50 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Et il y avait aux chambres des fenêtres fermées, ainsi qu’à leurs piliers, en dedans de la porte, tout autour, et de même aux avancées; et les fenêtres tout autour [donnaient] vers l’intérieur; et sur les piliers il y avait des palmiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Et il m’amena dans le parvis extérieur; et voici, des cellules, et un pavement garnissant le parvis, tout autour; il y avait 30 cellules sur le pavement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Et le pavement était à côté des portes, répondant à la longueur des portes, [savoir] le pavement inférieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Et il mesura la largeur depuis le devant de la porte inférieure jusqu’au devant du parvis intérieur, en dehors, 100 coudées à l’orient et au nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Et il mesura la longueur et la largeur de la porte du parvis extérieur, qui regardait vers le nord;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'et ses chambres, trois deçà et trois delà, et ses piliers, et ses avancées: elle était selon la mesure de la première porte, sa longueur, 50 coudées, et sa largeur, 25 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Et ses fenêtres, et ses avancées, et ses palmiers, étaient selon la mesure de la porte qui regardait vers l’orient; et on y montait par sept degrés, et ses avancées étaient devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Et la porte du parvis intérieur était vis-à-vis de la porte du nord et de l’orient; et il mesura, de porte à porte, 100 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Et il me conduisit vers le midi; et voici, une porte vers le midi; et il mesura ses piliers et ses avancées selon ces [mêmes] mesures;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'et il y avait des fenêtres à la [porte] et à ses avancées, tout autour, comme ces fenêtres-là: la longueur, 50 coudées, et la largeur, 25 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Et il y avait sept degrés pour y monter, et ses avancées devant eux; et la porte avait des palmiers, un deçà et un delà, sur ses piliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Et il y avait une porte au parvis intérieur vers le midi; et il mesura de porte à porte, vers le midi, 100 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Et il m’amena dans le parvis intérieur, par la porte du midi; et il mesura la porte du midi selon ces [mêmes] mesures;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'et ses chambres, et ses piliers, et ses avancées, selon ces mesures-là; et il y avait des fenêtres à la [porte] et à ses avancées, tout autour: la longueur, 50 coudées, et la largeur, 25 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Et il y avait des avancées tout autour; la longueur, 25 coudées, et la largeur, cinq coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Et ses avancées étaient vers le parvis extérieur; et il y avait des palmiers sur ses piliers; et son escalier avait huit degrés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Et il m’amena dans le parvis intérieur, vers l’orient; et il mesura la porte selon ces [mêmes] mesures;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'et ses chambres, et ses piliers, et ses avancées, selon ces mesures-là; et il y avait des fenêtres à la [porte] et à ses avancées, tout autour: la longueur, 50 coudées, et la largeur, 25 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Et ses avancées étaient vers le parvis extérieur; et il y avait des palmiers sur ses piliers, deçà et delà; et son escalier avait huit degrés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Et il m’amena à la porte du nord, et il mesura selon ces mesures-là');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'ses chambres, ses piliers, et ses avancées; et elle avait des fenêtres tout autour: la longueur, 50 coudées, et la largeur, 25 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Et ses piliers étaient vers le parvis extérieur; et il y avait des palmiers sur ses piliers, deçà et delà; et son escalier avait huit degrés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Et il y avait une cellule et son entrée auprès des piliers des portes: là on lavait l’holocauste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Et, dans le portique de la porte, il y avait deux tables deçà et deux tables delà, pour égorger sur elles l’holocauste et le sacrifice pour le péché et le sacrifice pour le délit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Et sur le côté, en dehors, à la montée, à l’entrée de la porte du nord, il y avait deux tables; et de l’autre côté, près du portique de la porte, deux tables:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'quatre tables deçà et quatre tables delà, à côté de la porte, – huit tables, sur lesquelles on égorgeait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'et, auprès de l’escalier, quatre tables en pierre de taille, longues d’une coudée et demie, et larges d’une coudée et demie, et hautes d’une coudée; on y posait les instruments avec lesquels on égorgeait l’holocauste et les [autres] sacrifices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Et les doubles crochets, d’une paume, étaient fixés à la maison, tout autour; et, sur les tables, [on mettait] la chair des offrandes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Et en dehors de la porte intérieure il y avait dans le parvis intérieur deux cellules, l’une sur le côté de la porte du nord et qui regardait vers le midi, l’autre sur le côté de la porte du midi, qui regardait vers le nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Et il me dit: Cette cellule qui regarde vers le midi est pour les sacrificateurs qui font l’acquit de la charge de la maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'et la cellule qui regarde vers le nord est pour les sacrificateurs qui font l’acquit de la charge concernant l’autel. Ce sont les fils de Tsadok, qui, d’entre les fils de Lévi, s’approchent de l’ Éternel pour faire son service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Et il mesura le parvis: la longueur, 100 coudées, et la largeur, 100 coudées, un carré; et l’autel était devant la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Et il m’amena au portique de la maison; et il mesura le pilier du portique, cinq coudées deçà, et cinq coudées delà; et la largeur de la porte était de trois coudées deçà, et de trois coudées delà.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'La longueur du portique était de 20 coudées, et la largeur, de onze coudées, et [cela] aux degrés par lesquels on y montait; et il y avait des colonnes près des piliers, une deçà et une delà.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Et il m’amena dans le temple; et il mesura les piliers, six coudées en largeur deçà et six coudées en largeur delà, la largeur de la tente;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'et la largeur de l’entrée, dix coudées, et les côtés de l’entrée, cinq coudées deçà et cinq coudées delà; et il mesura sa longueur, 40 coudées, et la largeur, 20 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Et il entra dans l’intérieur; et il mesura le pilier de l’entrée, deux coudées, et l’entrée, six coudées, et la largeur de l’entrée, sept coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Et il mesura sa longueur, 20 coudées, et la largeur, 20 coudées, en face du temple. Et il me dit: C’est ici le lieu très saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Et il mesura le mur de la maison, six coudées; et la largeur de [chaque] chambre latérale, quatre coudées, à l’entour de la maison, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Et les chambres latérales étaient, chambre sur chambre, [au nombre de] trois, et cela 30 fois; et elles rentraient dans le mur qu’avait la maison vers les chambres latérales, tout autour, afin qu’elles y soient appuyées; mais elles n’étaient pas appuyées dans le mur de la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Et il y avait aux chambres latérales un élargissement, et il allait tournant toujours vers le haut, car le pourtour de la maison allait toujours vers le haut tout autour de la maison; c’est pourquoi la largeur de la maison était [plus grande] vers le haut; et ainsi la partie du bas montait à la partie du haut par la partie du milieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Je vis aussi à la maison une élévation tout autour, – les fondations des chambres latérales, une pleine canne, six coudées jusqu’à la jonction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'La largeur du mur qu’avaient les chambres latérales, en dehors, était de cinq coudées, comme aussi ce qui était laissé libre le long du bâtiment des chambres latérales qui étaient [attenantes] à la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Et entre les cellules [et la maison] il y avait une largeur de 20 coudées, autour de la maison, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Et l’entrée des chambres latérales était dans [l’espace] laissé libre, une entrée vers le nord, et une entrée vers le midi; et la largeur de l’espace libre était de cinq coudées, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Et le bâtiment qui était devant la place séparée, du côté de l’occident, avait une largeur de 70 coudées, et le mur du bâtiment avait cinq coudées d’épaisseur tout autour, et sa longueur était de 90 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Et il mesura la maison: la longueur, 100 coudées; et la place séparée, et le bâtiment, et ses murs, la longueur, 100 coudées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'et la largeur du devant de la maison et de la place séparée, vers l’orient, 100 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Et il mesura la longueur du bâtiment devant la place séparée, sur le derrière, et ses galeries, deçà et delà, 100 coudées; et le temple intérieur, et les portiques du parvis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Les seuils, et les fenêtres fermées, et les galeries, à l’entour, – aux trois – (vis-à-vis des seuils il y avait une boiserie mince, tout autour, et depuis le sol jusqu’aux fenêtres, et les fenêtres étaient couvertes)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, '[et] le dessus de l’entrée, et jusqu’à la maison intérieure, et au-dehors, et tout le long du mur, tout autour, intérieurement et extérieurement, [tout avait ses] mesures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Et on [y] avait fait des chérubins et des palmiers, un palmier entre deux chérubins; et le chérubin avait deux faces:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'une face d’homme vers le palmier, d’un côté, et une face de jeune lion vers le palmier, de l’autre côté; on avait fait [ainsi] sur toute la maison, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Depuis le sol jusqu’au-dessus de l’entrée, on avait fait des chérubins et des palmiers, et [sur] le mur du temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Les poteaux [de la porte] du temple étaient carrés, ainsi que [ceux du] devant du lieu saint: ils avaient le même aspect.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'L’autel de bois était haut de trois coudées, et sa longueur était de deux coudées; et il avait ses angles; et sa longueur et ses côtés étaient de bois. Et il me dit: C’est ici la table qui est devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Et le temple et le lieu saint avaient deux portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Et aux portes il y avait deux battants, deux battants tournants: deux à une porte, et deux battants à l’autre [porte].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Et sur elles, sur les portes du temple, on avait fait des chérubins et des palmiers, comme on les avait faits sur les murs. Et il y avait un entablement en bois sur la façade du portique, en dehors,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'et des fenêtres fermées, et des palmiers, deçà et delà, sur les côtés du portique et des chambres latérales de la maison et des entablements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Et il me fit sortir dans le parvis extérieur par le chemin qui va vers le nord; et il m’amena aux cellules qui étaient vis-à-vis de la place séparée, et qui étaient vis-à-vis du bâtiment, vers le nord,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'en face de la longueur, qui était de 100 coudées: l’entrée était au nord; et la largeur était de 50 coudées,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'vis-à-vis des 20 [coudées] qu’avait le parvis intérieur, et vis-à-vis du pavement qui était au parvis extérieur; il y avait galerie contre galerie, au troisième [étage];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'et devant les cellules, un passage de dix coudées de largeur; vers l’intérieur, un chemin de 100 coudées; et leurs entrées étaient au nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Et les cellules supérieures étaient raccourcies (parce que les galeries en ôtaient [une portion]) en comparaison des inférieures et de celles du milieu du bâtiment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Car elles étaient à trois étages, et n’avaient pas de colonnes comme les colonnes des parvis; c’est pourquoi [le troisième étage] était en retraite, en comparaison des [cellules] inférieures et de celles du milieu, depuis le sol.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Et le mur qui était en dehors, le long des cellules, du côté du parvis extérieur, en face des cellules, avait une longueur de 50 coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Car la longueur des cellules qui [aboutissaient] au parvis extérieur était de 50 coudées; mais voici, en face du temple, elle était de 100 coudées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'et, au-dessous de ces cellules, l’entrée était du côté de l’orient, lorsqu’on y arrivait du parvis extérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Dans la largeur du mur du parvis, du côté du midi, vis-à-vis de la place séparée et vis-à-vis du bâtiment, il y avait des cellules,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'et un passage devant elles, selon la forme des cellules qui étaient du côté du nord, selon leur longueur, selon leur largeur, et [selon] toutes leurs issues, et selon leurs ordonnances, et selon leurs portes d’entrée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Et selon les entrées des cellules qui étaient du côté du midi, il y avait une entrée à la tête du chemin, [du] chemin [qui était] en face du mur correspondant, chemin venant de l’orient, quand on venait vers les [cellules].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Et il me dit: Les cellules du nord [et] les cellules du midi, qui sont en face de la place séparée, ce sont des cellules saintes où les sacrificateurs qui s’approchent de l’ Éternel mangeront les choses très saintes; ils déposeront là les choses très saintes: l’offrande de gâteau, et le sacrifice pour le péché, et le sacrifice pour le délit, car le lieu est saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Quand les sacrificateurs seront entrés, ils ne sortiront pas du lieu saint dans le parvis extérieur; mais ils déposeront là leurs vêtements dans lesquels ils font le service, car ils sont saints; et ils revêtiront d’autres vêtements, et s’approcheront de ce qui est pour le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Et quand il eut achevé de mesurer la maison intérieure, il me fit sortir par le chemin de la porte qui regardait vers l’orient; et il mesura [l’enceinte] tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Il mesura le côté oriental avec la canne à mesurer: 500 cannes, avec la canne à mesurer, tout autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Il mesura le côté septentrional: 500 cannes, avec la canne à mesurer, [tout] autour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Il mesura le côté méridional: 500 cannes, avec la canne à mesurer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Il se tourna vers le côté occidental, [et] mesura 500 cannes avec la canne à mesurer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Il la mesura des quatre côtés. Elle avait un mur tout à l’entour: la longueur, 500, et la largeur, 500, pour séparer ce qui était saint et ce qui était profane.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Et il me conduisit à la porte, la porte qui regardait vers l’orient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Et voici, la gloire du Dieu d’Israël venait du côté de l’orient; et sa voix était comme une voix de grandes eaux, et la terre était illuminée par sa gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Et l’aspect de la vision que je voyais était comme la vision que j’avais vue quand je vins pour détruire la ville; et les visions étaient comme la vision que je vis près du fleuve Kebar; et je tombai sur ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Et la gloire de l’ Éternel entra dans la maison par le chemin de la porte qui regardait vers l’orient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Et l’Esprit m’enleva et m’amena dans le parvis intérieur; et voici, la gloire de l’ Éternel remplissait la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Et j’entendis [quelqu’un] qui me parlait depuis la maison, et un homme se tenait à côté de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Et il me dit: Fils d’homme, [c’est ici] le lieu de mon trône et le lieu de la plante de mes pieds, où je demeurerai au milieu des fils d’Israël à toujours. Et la maison d’Israël ne rendra plus impur mon saint nom, ni eux, ni leurs rois, par leurs prostitutions et par les cadavres de leurs rois [sur] leurs hauts lieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'alors qu’ils mettaient leur seuil contre mon seuil, et leurs poteaux à côté de mes poteaux, et [qu’il y avait seulement] un mur entre moi et eux: et ils ont rendu mon saint nom impur par leurs abominations qu’ils ont commises, et je les ai consumés dans ma colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Maintenant, qu’ils éloignent de moi leurs prostitutions et les cadavres de leurs rois, et je demeurerai au milieu d’eux à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Toi, fils d’homme, montre à la maison d’Israël la maison, afin qu’ils soient confus à cause de leurs iniquités; et qu’ils en mesurent la disposition.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Et, s’ils sont confus de tout ce qu’ils ont fait, fais-leur connaître la forme de la maison, et son arrangement, et ses issues, et ses entrées, et toutes ses formes, et toutes ses ordonnances, et toutes ses formes, et toutes ses lois; et écris-les devant leurs yeux, afin qu’ils observent toute sa forme, et toutes ses ordonnances, et qu’ils les fassent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'C’est ici la loi de la maison: sur la cime de la montagne, toutes ses limites tout à l’entour sont un lieu très saint. Voici, telle est la loi de la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Et ce sont ici les mesures de l’autel, en coudées; la coudée est une coudée et une paume: l’embasement avait une coudée [en hauteur], et une coudée en largeur; et le rebord de son avancée, tout autour, un empan; et c’était la base de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Et depuis l’embasement sur le sol jusqu’à la banquette inférieure il y avait deux coudées, et une coudée en largeur; et depuis la petite banquette jusqu’à la grande banquette, quatre coudées, et une coudée en largeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Et la montagne de ✶Dieu avait quatre coudées, et, depuis le lion de ✶Dieu en haut, les quatre cornes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Et le lion de ✶Dieu avait douze [coudées] de longueur, sur douze de largeur, en carré, sur ses quatre côtés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'et la banquette, 14 [coudées] de longueur, sur 14 de largeur, sur ses quatre côtés; et le rebord qui l’entourait, une demi-coudée, et son embasement une coudée à l’entour; et ses degrés regardaient vers l’orient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Et il me dit: Fils d’homme, ainsi dit le Seigneur, l’ Éternel: Ce sont ici les ordonnances de l’autel, au jour où il sera fait, pour y offrir des holocaustes et pour faire aspersion du sang sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Et aux sacrificateurs Lévites, qui sont de la semence de Tsadok, qui s’approchent de moi, pour faire mon service, dit le Seigneur, l’ Éternel, tu donneras un jeune taureau comme sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Et tu prendras de son sang, et tu le mettras sur les quatre cornes de [l’autel], et sur les quatre coins de la banquette, et sur le rebord, tout à l’entour; et tu le purifieras, et tu feras propitiation pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Et tu prendras le taureau du sacrifice pour le péché, et on le brûlera dans le lieu de la maison, désigné [pour cela], en dehors du sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Et le second jour, tu présenteras un bouc sans défaut, comme sacrifice pour le péché; et on purifiera l’autel comme on l’avait purifié par le taureau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Quand tu auras achevé de purifier [l’autel], tu présenteras un jeune taureau sans défaut, et un bélier du menu bétail, sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'et tu les présenteras devant l’ Éternel, et les sacrificateurs jetteront du sel sur eux, et les offriront en holocauste à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Pendant sept jours, tu offriras un bouc en sacrifice pour le péché, chaque jour; et on offrira un jeune taureau et un bélier du menu bétail, sans défaut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Pendant sept jours, on fera propitiation pour l’autel, et on le purifiera, et on le consacrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Et quand les jours seront achevés, il arrivera que, dès le huitième jour et ensuite, les sacrificateurs offriront sur l’autel vos holocaustes et vos sacrifices de prospérités; et je vous aurai pour agréables, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Et il me fit retourner vers la porte extérieure du sanctuaire, qui regardait vers l’orient, et elle était fermée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Et l’ Éternel me dit: Cette porte sera fermée; elle ne sera pas ouverte, et personne n’entrera par elle; car l’ Éternel, le Dieu d’Israël, est entré par elle; et elle sera fermée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Quant au prince, le prince, lui, y sera assis pour manger le pain devant l’ Éternel. Il entrera par le chemin du portique de cette porte, et il sortira par le même chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Et il m’amena par la porte du nord, devant la maison; et je vis, et voici, la gloire de l’ Éternel remplissait la maison de l’ Éternel; et je tombai sur ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Et l’ Éternel me dit: Fils d’homme, applique ton cœur et regarde de tes yeux, et écoute de tes oreilles tout ce que je te dis concernant toutes les ordonnances de la maison de l’ Éternel et toutes ses lois; et applique ton cœur à [considérer] l’entrée de la maison, ainsi que toutes les issues du sanctuaire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'et dis aux rebelles, à la maison d’Israël: Ainsi dit le Seigneur, l’ Éternel: C’en est assez de toutes vos abominations, maison d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'que vous ayez amené les fils de l’étranger, incirconcis de cœur et incirconcis de chair, pour qu’ils soient dans mon sanctuaire, – ma maison, – pour le profaner quand vous avez présenté mon pain, la graisse et le sang; et ils ont rompu mon alliance par toutes vos abominations!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Et vous n’avez pas vaqué au service de mes choses saintes, mais vous avez établi pour vous [des étrangers] pour vaquer à mon service dans mon sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Ainsi dit le Seigneur, l’ Éternel: Aucun étranger, incirconcis de cœur et incirconcis de chair, n’entrera dans mon sanctuaire, d’entre tous les étrangers qui sont au milieu des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Mais les Lévites, qui se sont éloignés de moi dans les égarements d’Israël par lesquels ils se sont égarés d’auprès de moi [en allant] après leurs idoles, porteront leur iniquité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'mais ils serviront dans mon sanctuaire comme gardes aux portes de la maison, et feront le service de la maison; ils égorgeront pour le peuple l’holocauste et le sacrifice, et ils se tiendront devant eux pour les servir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Parce qu’ils les ont servis devant leurs idoles, et ont été à la maison d’Israël une pierre d’achoppement pour l’iniquité, à cause de cela j’ai levé ma main contre eux, dit le Seigneur, l’ Éternel: ils porteront leur iniquité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Et ils ne s’approcheront pas de moi pour exercer la sacrificature devant moi, ni pour s’approcher de toutes mes choses saintes, dans ce qui concerne les choses très saintes; et ils porteront leur ignominie, et leurs abominations qu’ils ont commises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Et je les établirai pour faire l’acquit de la charge de la maison, pour tout son service, et pour tout ce qui y sera fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Mais les sacrificateurs, les Lévites, fils de Tsadok, qui ont fait l’acquit de la charge de mon sanctuaire, quand les fils d’Israël se sont égarés d’auprès de moi, eux s’approcheront de moi pour faire mon service, et se tiendront devant moi, pour me présenter la graisse et le sang, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Eux entreront dans mon sanctuaire, et eux s’approcheront de ma table pour faire mon service, et ils feront l’acquit de la charge que je leur confie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Et il arrivera que, quand ils entreront dans les portes du parvis intérieur, ils se revêtiront de vêtements de lin, et ils ne porteront pas de laine sur eux pendant leur service dans les portes du parvis intérieur et vers la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Ils auront des turbans de lin sur leur tête, et des caleçons de lin sur leurs reins; ils ne se ceindront pas avec ce qui fait transpirer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Et quand ils sortiront dans le parvis extérieur, dans le parvis extérieur vers le peuple, ils ôteront leurs vêtements dans lesquels ils auront fait le service, et les déposeront dans les cellules saintes; et ils revêtiront d’autres vêtements, afin de ne pas sanctifier le peuple par leurs vêtements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Et ils ne se raseront pas la tête, et ne laisseront pas croître librement leurs cheveux; ils auront soin de couper les cheveux de leurs têtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Et aucun sacrificateur ne boira de vin quand il entrera dans le parvis intérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Et ils ne prendront pas pour femme une veuve, ni une répudiée; mais ils prendront une vierge de la semence de la maison d’Israël, ou une veuve qui sera veuve d’un sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Et ils instruiront mon peuple [à distinguer] entre ce qui est saint et ce qui est profane, et lui feront connaître [la différence] entre ce qui est impur et ce qui est pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Et, dans les contestations, ils se tiendront là pour juger; ils jugeront par mes jugements, et ils garderont mes lois et mes statuts dans toutes mes solennités, et ils sanctifieront mes sabbats.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Et ils n’entreront pas auprès d’un homme mort, pour se rendre impurs; mais pour un père ou pour une mère, ou pour un fils ou pour une fille, pour un frère ou pour une sœur qui n’a pas été mariée, ils se rendront impurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Et après qu’il se sera purifié, on comptera sept jours pour celui qui s’est rendu impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Et au jour où il entrera dans le lieu saint, dans le parvis intérieur, pour faire le service dans le lieu saint, il présentera son sacrifice pour le péché, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Et [mon service] leur sera pour héritage: moi, je suis leur héritage; et vous ne leur donnerez pas de possession en Israël: moi, je suis leur possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Ils mangeront l’offrande de gâteau, et le sacrifice pour le péché, et le sacrifice pour le délit; et tout ce qui est voué [à Dieu] en Israël leur appartiendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Et les prémices de tous les premiers fruits de toute [espèce], et toute offrande élevée de toute [espèce], de toutes vos offrandes élevées, appartiendront aux sacrificateurs; et les prémices de votre pâte, vous les donnerez au sacrificateur, pour faire reposer la bénédiction sur ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Les sacrificateurs ne mangeront de rien de ce qui est mort de soi-même ou de ce qui a été déchiré, soit d’entre les oiseaux, soit d’entre le bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Et quand vous partagerez par le sort le pays en héritage, vous offrirez en offrande élevée à l’ Éternel une portion du pays sanctifiée: la longueur, 25 000 [coudées] en longueur, et la largeur, 10 000. Elle sera sainte dans toutes ses limites à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'De celle-ci il y aura, pour le lieu saint, 500 [cannes] sur 500, un carré, à l’entour; et il aura 50 coudées de banlieue, à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Et, d’après cette mesure, tu mesureras en longueur 25 000, et en largeur 10 000; et le sanctuaire sera là, le lieu très saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Ce sera une portion sanctifiée du pays; elle sera pour les sacrificateurs qui font le service du sanctuaire, qui s’approchent pour servir l’ Éternel; et ce sera un lieu pour leurs maisons, et un lieu consacré pour le sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Et [un espace de] 25 000 en longueur et [de] 10 000 en largeur sera aux Lévites qui font le service de la maison; ils l’auront comme possession [pour leurs] lieux d’habitation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Et, pour possession de la ville, vous donnerez 5 000 en largeur, et 25 000 en longueur, le long de la sainte offrande élevée: ce sera pour toute la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Et il y aura [une portion] pour le prince, d’un côté et de l’autre côté de la sainte offrande élevée et de la possession de la ville, en face de la sainte offrande élevée et en face de la possession de la ville, au côté occidental vers l’occident, et au côté oriental vers l’orient; et la longueur en sera vis-à-vis de l’une des portions [des tribus], depuis la limite occidentale jusqu’à la limite vers l’orient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Elle lui appartiendra comme terre, comme possession en Israël; et mes princes n’opprimeront plus mon peuple, mais ils laisseront le pays à la maison d’Israël, selon leurs tribus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Ainsi dit le Seigneur, l’ Éternel: C’en est assez, princes d’Israël! Ôtez la violence et la rapine, et pratiquez le jugement et la justice; cessez d’expulser mon peuple [de leur terre], dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Ayez des balances justes, et un épha juste, et un bath juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'L’épha et le bath auront une même mesure, en sorte que le bath contienne la dixième partie d’un khomer, et l’épha, la dixième partie d’un khomer; leur mesure correspondra au khomer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Et le sicle sera de 20 guéras; 20 sicles, 25 sicles, 15 sicles, seront votre mine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'C’est ici l’offrande élevée que vous offrirez: sur un khomer de froment, le sixième d’un épha, et sur un khomer d’orge, le sixième d’un épha;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'et la redevance en huile, pour un bath d’huile, le dixième d’un bath sur un cor, [qui est] un khomer de dix baths (car dix baths font un khomer);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'et une brebis du petit bétail sur 200, des pâturages arrosés d’Israël; – pour offrande de gâteau, et pour holocauste, et pour sacrifices de prospérités, pour faire propitiation pour eux, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Tout le peuple du pays sera obligé à cette offrande élevée pour le prince en Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Et le prince sera chargé de [fournir] les holocaustes, et l’offrande de gâteau, et la libation, aux jours de fête, et aux nouvelles lunes, et aux sabbats, dans toutes les solennités de la maison d’Israël. Lui, offrira le sacrifice pour le péché, et l’offrande de gâteau, et l’holocauste, et les sacrifices de prospérités, pour faire propitiation pour la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Ainsi dit le Seigneur, l’ Éternel: Au premier [mois], le premier [jour] du mois, tu prendras un jeune taureau sans défaut, et tu purifieras le sanctuaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Et le sacrificateur prendra du sang du sacrifice pour le péché, et en mettra sur les poteaux de la maison, et sur les quatre coins de la banquette de l’autel, et sur les poteaux de la porte du parvis intérieur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Et tu feras ainsi, le septième [jour] du mois, pour celui qui pèche par erreur, et pour le simple, et vous ferez propitiation pour la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Au premier [mois], le quatorzième jour du mois, sera pour vous la Pâque, une fête de sept jours; on mangera des pains sans levain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Et le prince offrira en ce jour-là, pour lui-même et pour tout le peuple du pays, un taureau en sacrifice pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Et, les sept jours de la fête, il offrira à l’ Éternel, comme holocauste, sept taureaux et sept béliers sans défaut, chaque jour, les sept jours; et, en sacrifice pour le péché, un bouc, chaque jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Et il offrira, comme offrande de gâteau, un épha par taureau, et un épha par bélier, et de l’huile, un hin par épha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Au septième [mois], le quinzième jour du mois, à la fête, il fera selon ces [ordonnances], sept jours, quant au sacrifice pour le péché, quant à l’holocauste, et quant à l’offrande de gâteau, et quant à l’huile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Ainsi dit le Seigneur, l’ Éternel: La porte du parvis intérieur, qui regarde vers l’orient, sera fermée les six jours de travail; mais le jour du sabbat, elle sera ouverte, et le jour de la nouvelle lune, elle sera ouverte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Et le prince viendra du dehors par le chemin du portique de la porte, et il se tiendra près des poteaux de la porte, et les sacrificateurs offriront son holocauste et ses sacrifices de prospérités; et il rendra son culte sur le seuil de la porte, et il sortira; et la porte ne se fermera pas jusqu’au soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Et le peuple du pays rendra son culte à l’entrée de cette porte, les jours de sabbat et aux nouvelles lunes, devant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Et l’holocauste que le prince présentera à l’ Éternel, le jour du sabbat, sera de six agneaux sans défaut, et d’un bélier sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'et l’offrande de gâteau, d’un épha pour le bélier; et pour les agneaux, l’offrande de gâteau sera ce que sa main peut donner; et de l’huile, un hin par épha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Et, au jour de la nouvelle lune, un jeune taureau sans défaut, et six agneaux, et un bélier; ils seront sans défaut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'et il offrira une offrande de gâteau d’un épha pour le taureau, et d’un épha pour le bélier; et, pour les agneaux, selon ce que sa main aura pu trouver; et de l’huile, un hin par épha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Et quand le prince entrera, il entrera par le chemin du portique de la porte, et il sortira par le même chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Et quand le peuple du pays entrera devant l’ Éternel, lors des solennités, celui qui entrera par le chemin de la porte du nord, pour rendre son culte, sortira par le chemin de la porte du midi; et celui qui entrera par le chemin de la porte du midi, sortira par le chemin de la porte du nord; il ne s’en retournera pas par le chemin de la porte par laquelle il est entré, mais il sortira par celle qui est vis-à-vis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Et le prince entrera au milieu d’eux, quand ils entreront; et, quand ils sortiront, ils sortiront [ensemble].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Et aux fêtes, et aux solennités, l’offrande de gâteau sera d’un épha pour le taureau, et d’un épha pour le bélier; et, pour les agneaux, ce que sa main peut donner; et de l’huile, un hin par épha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Mais si le prince offre un holocauste volontaire, ou des sacrifices volontaires de prospérités à l’ Éternel, on lui ouvrira la porte qui regarde vers l’orient; et il offrira son holocauste et ses sacrifices de prospérités, comme il fait le jour du sabbat; puis il sortira, et on fermera la porte après qu’il sera sorti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Et tu offriras chaque jour à l’ Éternel un agneau âgé d’un an, sans défaut, comme holocauste; tu l’offriras chaque matin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'et tu offriras l’offrande de gâteau, avec lui, chaque matin, le sixième d’un épha; et de l’huile, le tiers d’un hin, pour humecter la fleur de farine, – une offrande continuelle de gâteau à l’ Éternel, par ordonnance perpétuelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Et on offrira l’agneau, et le gâteau, et l’huile, chaque matin, un holocauste continuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Ainsi dit le Seigneur, l’ Éternel: Si le prince fait un don à l’un de ses fils, ce sera l’héritage de celui-ci pour ses fils, leur possession comme héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Et si, de son héritage, il fait un don à l’un de ses serviteurs, cela lui appartiendra jusqu’à l’année de liberté, et [alors] retournera au prince; seulement son héritage demeurera à ses fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Et le prince ne prendra pas de l’héritage du peuple en les opprimant, les chassant de leur possession: c’est de sa propre possession qu’il fera hériter ses fils, afin que mon peuple ne soit pas dispersé, chacun [loin] de sa possession.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Puis il m’amena par le passage qui était à côté de la porte, vers les cellules saintes des sacrificateurs, qui regardent vers le nord; et voici, il y avait là un lieu, au fond, vers l’occident.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Et il me dit: C’est ici le lieu où les sacrificateurs feront bouillir le sacrifice pour le délit et le sacrifice pour le péché, [et] où ils cuiront l’offrande de gâteau, en sorte qu’ils ne les portent pas dehors dans le parvis extérieur de manière à sanctifier le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Et il me fit sortir dans le parvis extérieur et me fit passer aux quatre angles du parvis; et voici, il y avait un parvis dans chaque angle du parvis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Dans les quatre angles du parvis, il y avait des parvis clos, 40 [coudées] en longueur et 30 en largeur; il y avait une même mesure pour les quatre [parvis] des angles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'et, à l’entour, dans ces [parvis], une [maçonnerie] continue, autour des quatre; et des foyers à cuire, pratiqués au-dessous des rangées, à l’entour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Et il me dit: Ce sont ici les cuisines, où ceux qui font le service de la maison font cuire les sacrifices du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Et il me fit retourner à l’entrée de la maison, et voici des eaux qui sortaient de dessous le seuil de la maison, vers l’orient, car la façade de la maison était [tournée] vers l’orient. Et les eaux descendaient de dessous, du côté droit de la maison, au midi de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Et il me fit sortir par le chemin de la porte du nord, et il me fit faire le tour par-dehors vers la porte extérieure, vers [la porte] qui regarde vers l’orient; et voici des eaux qui coulaient du côté droit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Quand l’homme sortit vers l’orient, il avait un cordeau dans sa main; et il mesura 1 000 coudées, et me fit traverser les eaux, – des eaux [montant] jusqu’aux chevilles des pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Et il mesura 1 000 [coudées], et me fit traverser les eaux, – des eaux [montant] jusqu’aux genoux. Et il mesura 1 000 [coudées], et me fit traverser, – des eaux [montant] jusqu’aux reins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Et il mesura 1 000 [coudées]: c’était une rivière que je ne pouvais traverser, car les eaux avaient crû, des eaux où il fallait nager, une rivière qu’on ne pouvait traverser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Et il me dit: As-tu vu, fils d’homme? Et il me fit aller et retourner sur le bord de la rivière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Quand j’y fus retourné, voici, au bord de la rivière, des arbres en très grand nombre, d’un côté et de l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Et il me dit: Ces eaux sortent vers la contrée orientale, et elles descendent dans la plaine et parviennent jusqu’à la mer; lorsqu’elles se seront déversées dans la mer, les eaux [de la mer] seront rendues saines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Et il arrivera que tout être vivant qui se meut partout où parvient la double rivière, vivra. Et il y aura une très grande quantité de poissons, car ces eaux parviendront là, et [les eaux de la mer] seront rendues saines; et tout vivra, là où parviendra la rivière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Et les pêcheurs se tiendront auprès d’elle: depuis En-Guédi jusqu’à En-Églaïm, ce sera [un lieu] pour étendre les filets. Leur poisson sera selon ses espèces, comme le poisson de la grande mer, en très grand nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Ses marais et ses étangs ne seront pas assainis, ils seront abandonnés au sel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Et sur la rivière, sur son bord, d’un côté et de l’autre, croissaient toutes sortes d’arbres dont on mange. Leur feuille ne se flétrira pas, et leur fruit ne cessera pas: tous les mois ils porteront du fruit mûr; car ses eaux sortent du sanctuaire. Et leur fruit sera pour nourrir, et leur feuille, pour guérir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, '*Ainsi dit le Seigneur, l’ Éternel: C’est ici la frontière selon laquelle vous donnerez le pays en héritage aux douze tribus d’Israël. Joseph [aura deux] parts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Et vous l’hériterez l’un comme l’autre, [le pays] au sujet duquel j’ai levé ma main de le donner à vos pères; et ce pays vous écherra en héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Et c’est ici la frontière du pays: Du côté du nord, depuis la grande mer, le chemin de Hethlon, quand on va à Tsedad;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamath, Bérotha, Sibraïm, qui est entre la frontière de Damas et la frontière de Hamath, Hatser-Hatthicon qui est sur la frontière du Hauran.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Et la frontière, depuis la mer, sera Hatsar-Énon, la frontière de Damas, et le nord, vers le nord, et la frontière de Hamath; c’est là le côté du nord. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Et le côté de l’orient: vous mesurerez d’entre le Hauran et Damas, et Galaad, et le pays d’Israël, le long du Jourdain, – depuis la frontière jusqu’à la mer orientale; c’est là le côté de l’orient. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Et le côté du midi, vers le sud: depuis Thamar jusqu’aux eaux de Meriba de Kadès, la rivière jusqu’à la grande mer; c’est là le côté du sud, vers le midi. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Et le côté de l’occident: la grande mer, depuis la frontière jusque vis-à-vis de l’entrée de Hamath; c’est le côté de l’occident.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Et vous vous partagerez ce pays entre les tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Et il arrivera que vous le partagerez par le sort, comme un héritage pour vous et pour les étrangers qui séjournent au milieu de vous, qui engendreront des fils au milieu de vous; et ils vous seront comme les Israélites de naissance; ils hériteront avec vous par le sort, au milieu des tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Et il arrivera que, dans la tribu chez laquelle l’étranger séjourne, là vous [lui] donnerez son héritage, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Et ce sont ici les noms des tribus. Depuis l’extrémité nord, le long du chemin de Hethlon quand on va à Hamath [et] Hatsar-Énan, la frontière de Damas, au nord près de Hamath, – le côté de l’orient, [et] l’occident, seront à lui, – une [part] pour Dan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Et sur la frontière de Dan, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Aser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Et sur la frontière d’Aser, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Nephthali.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Et sur la frontière de Nephthali, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Manassé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Et sur la frontière de Manassé, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Éphraïm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Et sur la frontière d’Éphraïm, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Ruben.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Et sur la frontière de Ruben, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Et sur la frontière de Juda, depuis le côté de l’orient jusqu’au côté de l’occident, sera l’offrande élevée que vous offrirez: 25 000 [coudées] en largeur, et la longueur comme l’une des [autres] parts, depuis le côté de l’orient jusqu’au côté de l’occident; et le sanctuaire sera au milieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'L’offrande élevée que vous offrirez à l’ Éternel sera de 25 000 en longueur, et de 10 000 en largeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Et cette [portion] sera pour les sacrificateurs, la sainte offrande: au nord, 25 000; et à l’occident, la largeur, 10 000; et à l’orient, la largeur, 10 000; et au midi, la longueur, 25 000; et le sanctuaire de l’ Éternel sera au milieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, '[L’offrande sera] pour les sacrificateurs qui sont sanctifiés d’entre les fils de Tsadok, qui ont fait l’acquit de la charge que je leur ai confiée, qui ne se sont pas égarés dans les égarements des fils d’Israël, comme les Lévites se sont égarés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Et, sur l’offrande du pays, ils auront une offrande élevée, une chose très sainte, sur la frontière des Lévites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Et le long de la frontière des sacrificateurs, les Lévites auront une longueur de 25 000, et une largeur de 10 000; toute la longueur sera de 25 000, et la largeur, de 10 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Ils n’en vendront rien, et n’en feront pas d’échange, et ils n’aliéneront pas les prémices du pays, car il est saint, [consacré] à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Et les 5 000 qui restent de la largeur en face des 25 000 seront [un espace] profane pour la ville, pour des habitations et pour une banlieue; et la ville sera au milieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Et ce sont ici ses mesures: le côté du nord, 4 500; et le côté du midi, 4 500; et le côté de l’orient, 4 500; et le côté de l’occident, 4 500.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Et la banlieue de la ville, au nord, sera de 250, et au midi, de 250, et à l’orient, de 250, et à l’occident, de 250.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Et ce qui reste sur la longueur, le long de la sainte offrande, sera de 10 000 vers l’orient, et de 10 000 vers l’occident: il sera le long de la sainte offrande élevée, et son rapport sera pour la nourriture de ceux qui servent la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Et ceux qui servent la ville la serviront, de toutes les tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Toute l’offrande élevée sera de 25 000 sur 25 000; vous offrirez la sainte offrande élevée, un carré, avec la possession de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Et le restant [sera] pour le prince, d’un côté et de l’autre de la sainte offrande et de la possession de la ville, en face des 25 000 de l’offrande élevée jusqu’à la frontière d’orient, et, vers l’occident, en face des 25 000 jusqu’à la frontière d’occident, le long des [autres] portions: [cela sera] pour le prince. Et la sainte offrande élevée et le sanctuaire de la maison seront au milieu d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Et depuis la possession des Lévites et la possession de la ville, qui sont au milieu de ce qui sera au prince, – [ce qui est] entre la frontière de Juda et la frontière de Benjamin sera pour le prince.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Et quant au reste des tribus, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Et sur la frontière de Benjamin, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Siméon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Et sur la frontière de Siméon, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Issacar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Et sur la frontière d’Issacar, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Zabulon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Et sur la frontière de Zabulon, depuis le côté de l’orient jusqu’au côté de l’occident: une [part] pour Gad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Et sur la frontière de Gad, du côté du midi, vers le sud, la frontière sera depuis Thamar [jusqu’aux] eaux de Meriba de Kadès, la rivière jusqu’à la grande mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'C’est là le pays que vous partagerez par le sort, comme héritage entre les tribus d’Israël, et ce sont là leurs parts, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, '*Et ce sont ici les issues de la ville: du côté du nord, une mesure de 4 500 [coudées];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'et les portes de la ville [seront] selon les noms des tribus d’Israël: trois portes vers le nord: la porte de Ruben, une; la porte de Juda, une; la porte de Lévi, une.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Et vers le côté de l’orient, 4 500, et trois portes: la porte de Joseph, une; la porte de Benjamin, une; la porte de Dan, une.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Et du côté du midi, une mesure de 4 500 [coudées], et trois portes: la porte de Siméon, une; la porte d’Issacar, une; la porte de Zabulon, une.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Du côté de l’occident, 4 500, [et] leurs trois portes: la porte de Gad, une; la porte d’Aser, une; la porte de Nephthali, une.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Le circuit était de 18 000 [coudées]; et le nom de la ville, dès ce jour: l’ Éternel est là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'La troisième année du règne de Jehoïakim, roi de Juda, Nebucadnetsar, roi de Babylone, vint à Jérusalem et l’assiégea;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'et le Seigneur livra en sa main Jehoïakim, roi de Juda, et une partie des ustensiles de la maison de Dieu, et il les fit apporter dans le pays de Shinhar, dans la maison de son dieu: il fit porter les ustensiles dans la maison du trésor de son dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Et le roi dit à Ashpenaz, chef de ses eunuques, d’amener d’entre les fils d’Israël, et de la semence royale et d’entre les nobles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'des jeunes gens en qui il n’y ait aucun défaut, et beaux de visage, et instruits en toute sagesse, et possédant des connaissances, et entendus en science, et qui soient capables de se tenir dans le palais du roi, – et de leur enseigner les lettres et la langue des Chaldéens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Et le roi leur assigna, pour chaque jour, une portion fixe des mets délicats du roi et du vin qu’il buvait, pour les élever pendant trois ans, à la fin desquels ils se tiendraient devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Et parmi eux il y avait, d’entre les fils de Juda, Daniel, Hanania, Mishaël, et Azaria;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'et le prince des eunuques leur donna des noms: à Daniel il donna [le nom de] Belteshatsar, et à Hanania celui de Shadrac, et à Mishaël celui de Méshac, et à Azaria celui d’Abed-Nego.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Et Daniel arrêta dans son cœur qu’il ne se souillerait point par les mets délicats du roi et par le vin qu’il buvait; et il demanda au prince des eunuques [de lui permettre] de ne pas se souiller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Et Dieu fit trouver à Daniel faveur et grâce auprès du prince des eunuques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Et le prince des eunuques dit à Daniel: Je crains le roi mon seigneur, qui a prescrit votre nourriture et votre boisson; car pourquoi verrait-il vos visages plus tristes que ceux des jeunes gens de votre âge? Et vous exposeriez ma tête auprès du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Et Daniel dit à l’intendant que le prince des eunuques avait établi sur Daniel, Hanania, Mishaël et Azaria:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Éprouve, je te prie, tes serviteurs dix jours, et qu’on nous donne des légumes à manger, et de l’eau à boire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'et on regardera, en ta présence, nos visages et le visage des jeunes gens qui mangent les mets délicats du roi; et tu agiras avec tes serviteurs d’après ce que tu verras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Et il les écouta dans cette affaire, et les mit à l’épreuve, dix jours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'et, au bout de dix jours, leurs visages avaient meilleure apparence et étaient plus gras que ceux de tous les jeunes gens qui mangeaient les mets délicats du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Alors l’intendant ôta leurs mets délicats et le vin de leur boisson, et leur donna des légumes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Et à ces jeunes gens, aux quatre, Dieu donna de la science et de l’instruction dans toutes les lettres et dans toute la sagesse; et Daniel avait de l’intelligence en toute vision et dans les songes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Et, à la fin des jours où le roi avait dit de les amener, le prince des eunuques les amena devant Nebucadnetsar;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'et le roi parla avec eux, et entre eux tous il n’en fut trouvé aucun comme Daniel, Hanania, Mishaël et Azaria; et ils se tinrent devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Et dans toutes les choses qui réclamaient de la sagesse et de l’intelligence, au sujet desquelles le roi les interrogea, il les trouva dix fois supérieurs à tous les devins [et] enchanteurs qui étaient dans tout son royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Et Daniel fut là jusqu’à la première année du roi Cyrus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Et en la seconde année du règne de Nebucadnetsar, Nebucadnetsar songea des songes, et son esprit fut agité, et son sommeil le quitta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Et le roi commanda d’appeler les devins, et les enchanteurs, et les magiciens, et les Chaldéens, pour exposer au roi ses songes; et ils vinrent et se tinrent devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Et le roi leur dit: J’ai songé un songe, et mon esprit est agité pour connaître le songe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Et les Chaldéens dirent au roi, en syriaque: Ô roi, vis à jamais! Dis le songe à tes serviteurs, et nous en indiquerons l’interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Le roi répondit et dit aux Chaldéens: La chose est par moi prononcée: si vous ne me faites pas connaître le songe et son interprétation, vous serez mis en pièces, et vos maisons seront réduites en tas d’immondices;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'mais, si vous indiquez le songe et son interprétation, vous recevrez de ma part des dons, et des présents, et de grands honneurs. Indiquez-moi donc le songe et son interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Ils répondirent pour la seconde fois et dirent: Que le roi dise le songe à ses serviteurs, et nous en indiquerons l’interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Le roi répondit et dit: Je sais très certainement que vous voulez gagner du temps, parce que vous voyez que la chose est par moi prononcée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'or, si vous ne me faites pas connaître le songe, il y a un seul et même décret pour vous; car vous avez préparé une parole mensongère et perverse pour la dire devant moi, en attendant que le temps ait changé. C’est pourquoi, dites-moi le songe, et je saurai que vous pouvez m’en indiquer l’interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Les Chaldéens répondirent devant le roi et dirent: Il n’existe pas un homme sur la terre qui puisse indiquer la chose que le roi demande; c’est pourquoi aucun roi, quelque grand et puissant qu’il soit, n’a demandé chose pareille d’aucun devin, ou enchanteur, ou Chaldéen;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'et la chose que le roi demande est difficile, et il n’existe personne qui puisse l’indiquer devant le roi, excepté les dieux, dont la demeure n’est pas avec la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'À cause de cela, le roi s’irrita et se mit dans une très grande colère, et commanda de détruire tous les sages de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Et un décret fut promulgué [portant] que les sages soient tués; et on chercha Daniel et ses compagnons, pour les tuer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Alors Daniel répondit avec prudence et avec sens à Arioc, chef des gardes du roi, qui était sorti pour tuer les sages de Babylone;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'il répondit et dit à Arioc, le grand officier du roi: Pourquoi ce décret est-il si rigoureux de par le roi? Alors Arioc fit connaître la chose à Daniel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Et Daniel entra et demanda au roi de lui accorder du temps pour indiquer au roi l’interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Alors Daniel s’en alla à sa maison et fit connaître la chose à Hanania, Mishaël et Azaria, ses compagnons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'pour implorer, de la part du Dieu des cieux, [ses] compassions au sujet de ce secret, afin que Daniel et ses compagnons ne soient pas détruits avec le reste des sages de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Alors le secret fut révélé à Daniel dans une vision de la nuit. Alors Daniel bénit le Dieu des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel répondit et dit: Béni soit le nom de Dieu, d’éternité en éternité! car la sagesse et la puissance sont à lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'et c’est lui qui change les temps et les saisons, qui dépose les rois et établit les rois, qui donne la sagesse aux sages et la connaissance à ceux qui connaissent l’intelligence:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'c’est lui qui révèle les choses profondes et secrètes; il sait ce qui est dans les ténèbres, et la lumière demeure auprès de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Toi, Dieu de mes pères, je te célèbre et je te loue, parce que tu m’as donné sagesse et puissance, et que maintenant tu m’as fait connaître ce que nous t’avons demandé, nous ayant fait connaître la chose que réclame le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'C’est pourquoi Daniel entra auprès d’Arioc, que le roi avait établi pour détruire les sages de Babylone; il alla, et lui parla ainsi: Ne détruis pas les sages de Babylone; conduis-moi devant le roi, et j’indiquerai au roi l’interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Alors Arioc fit entrer Daniel en hâte devant le roi, et lui parla ainsi: J’ai trouvé un homme, des fils de la captivité de Juda, qui fera connaître au roi l’interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Le roi répondit et dit à Daniel, dont le nom était Belteshatsar: Peux-tu me faire connaître le songe que j’ai vu et son interprétation?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel répondit devant le roi, et dit: Le secret que le roi demande, les sages, les enchanteurs, les devins, les augures, n’ont pu l’indiquer au roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'mais il y a un Dieu dans les cieux qui révèle les secrets et fait savoir au roi Nebucadnetsar ce qui arrivera à la fin des jours. Ton songe et les visions de ta tête, sur ton lit, les voici:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Toi, ô roi,... tes pensées, sur ton lit, sont montées [dans ton esprit], ce qui doit arriver ci-après; et celui qui révèle les secrets te fait savoir ce qui va arriver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Et quant à moi, ce n’est pas par quelque sagesse qui soit en moi plus qu’en tous les vivants, que ce secret m’a été révélé: c’est afin que l’interprétation soit connue du roi, et que tu connaisses les pensées de ton cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Toi, ô roi, tu voyais, et voici une grande statue: cette statue était grande, et sa splendeur, extraordinaire; elle se tint devant toi, et son aspect était terrible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'La tête de cette statue était d’or pur; sa poitrine et ses bras, d’argent; son ventre et ses cuisses, d’airain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'ses jambes, de fer; ses pieds, en partie de fer et en partie d’argile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Tu vis, jusqu’à ce qu’une pierre se détacha sans mains; et elle frappa la statue dans ses pieds de fer et d’argile, et les broya;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'alors furent broyés ensemble le fer, l’argile, l’airain, l’argent et l’or, et ils devinrent comme la balle de l’aire d’été; et le vent les emporta, et il ne se trouva aucun lieu pour eux; et la pierre qui avait frappé la statue devint une grande montagne qui remplit toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'C’est là le songe, et nous en dirons l’interprétation devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Toi, ô roi, tu es le roi des rois, auquel le Dieu des cieux a donné le royaume, la puissance, et la force, et la gloire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'et partout où habitent les fils des hommes, les bêtes des champs et les oiseaux des cieux, il les a mis entre tes mains et t’a fait dominer sur eux tous. Toi, tu es cette tête d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Et après toi s’élèvera un autre royaume, inférieur à toi; puis un troisième [et] autre royaume, d’airain, qui dominera sur toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Et le quatrième royaume sera fort comme le fer. De même que le fer broie et écrase tout, et que le fer brise toutes ces choses, il broiera et brisera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Et selon que tu as vu les pieds et les orteils en partie d’argile de potier et en partie de fer, le royaume sera divisé; et il y aura en lui de la dureté du fer, selon que tu as vu le fer mêlé avec de l’argile grasse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'et quant à ce que les orteils des pieds étaient en partie de fer et en partie d’argile, le royaume sera en partie fort et sera en partie fragile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Et selon que tu as vu le fer mêlé avec de l’argile grasse, ils se mêleront à la semence des hommes, mais ils n’adhéreront pas l’un à l’autre, de même que le fer ne se mêle pas avec l’argile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Et dans les jours de ces rois, le Dieu des cieux établira un royaume qui ne sera jamais détruit; et ce royaume ne passera point à un autre peuple; il broiera et détruira tous ces royaumes, mais lui, il subsistera à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Selon que tu as vu que, de la montagne, la pierre s’est détachée sans mains, et qu’elle a broyé le fer, l’airain, l’argile, l’argent et l’or, le grand Dieu fait connaître au roi ce qui arrivera ci-après. Et le songe est certain, et son interprétation est sûre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Alors le roi Nebucadnetsar tomba sur sa face et se prosterna devant Daniel, et commanda de lui présenter une offrande et des parfums.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Le roi répondit et dit à Daniel: En vérité, votre Dieu est le Dieu des dieux et le Seigneur des rois, et le révélateur des secrets, puisque tu as pu révéler ce secret.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Alors le roi éleva Daniel en dignité, et lui fit beaucoup de grands dons, et l’établit gouverneur sur toute la province de Babylone, et grand intendant de tous les sages de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Et Daniel fit une demande au roi, qui établit Shadrac, Méshac et Abed-Nego sur les services de la province de Babylone. Et Daniel [se tenait] à la porte du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, '*Nebucadnetsar, le roi, fit une statue d’or; sa hauteur était de 60 coudées, sa largeur, de six coudées; il la dressa dans la plaine de Dura, dans la province de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Et Nebucadnetsar, le roi, envoya [un ordre] pour assembler les satrapes, les préfets, les gouverneurs, les grands juges, les trésoriers, les conseillers, les légistes, et tous les magistrats des provinces, afin qu’ils viennent pour la dédicace de la statue que Nebucadnetsar, le roi, avait dressée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Alors s’assemblèrent les satrapes, les préfets, les gouverneurs, les grands juges, les trésoriers, les conseillers, les légistes, et tous les magistrats des provinces, pour la dédicace de la statue que Nebucadnetsar, le roi, avait dressée; et ils se tinrent devant la statue que Nebucadnetsar avait dressée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Et un héraut cria avec force: Il vous est ordonné, peuples, peuplades, et langues:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Aussitôt que vous entendrez le son du cor, de la flûte, de la cithare, de la sambuque, du psaltérion, de la musette, et toute espèce de musique, vous vous prosternerez et vous adorerez la statue d’or que Nebucadnetsar, le roi, a dressée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'et quiconque ne se prosternera pas et n’adorera pas, sera jeté à l’heure même au milieu d’une fournaise de feu ardent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'C’est pourquoi, au moment même où tous les peuples entendirent le son du cor, de la flûte, de la cithare, de la sambuque, du psaltérion, et toute espèce de musique, tous les peuples, peuplades et langues, se prosternèrent [et] adorèrent la statue d’or que Nebucadnetsar, le roi, avait dressée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'À cause de cela, en ce même moment, des hommes chaldéens s’approchèrent et accusèrent les Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Ils prirent la parole et dirent au roi Nebucadnetsar: Ô roi, vis à jamais!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Toi, ô roi, tu as donné ordre que tout homme qui entendrait le son du cor, de la flûte, de la cithare, de la sambuque, du psaltérion, de la musette, et toute espèce de musique, se prosterne et adore la statue d’or,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'et que quiconque ne se prosternerait pas et n’adorerait pas, serait jeté au milieu d’une fournaise de feu ardent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Il y a des hommes juifs, que tu as établis sur les services de la province de Babylone, Shadrac, Méshac et Abed-Nego: ces hommes ne tiennent pas compte de toi, ô roi; ils ne servent pas tes dieux, et la statue d’or que tu as dressée ils ne l’adorent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Alors Nebucadnetsar, en colère et en fureur, commanda d’amener Shadrac, Méshac et Abed-Nego; alors on amena ces hommes devant le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nebucadnetsar prit la parole et leur dit: Est-ce à dessein, Shadrac, Méshac et Abed-Nego, que vous ne servez pas mon dieu, et que vous n’adorez pas la statue d’or que j’ai dressée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Maintenant, si, au moment où vous entendrez le son du cor, de la flûte, de la cithare, de la sambuque, du psaltérion, de la musette, et toute espèce de musique, vous êtes prêts à vous prosterner et à adorer la statue que j’ai faite...; mais si vous ne l’adorez pas, à l’instant même vous serez jetés au milieu de la fournaise de feu ardent. Et qui est le Dieu qui vous délivrera de ma main?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Shadrac, Méshac et Abed-Nego répondirent et dirent au roi: Nebucadnetsar, il n’est pas nécessaire que nous te répondions sur ce sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'S’il en est [comme tu dis], notre Dieu que nous servons peut nous délivrer de la fournaise de feu ardent, et il [nous] délivrera de ta main, ô roi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Et sinon, sache, ô roi, que nous ne servirons pas tes dieux, et que nous n’adorerons pas la statue d’or que tu as dressée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Alors Nebucadnetsar fut rempli de fureur, et l’apparence de son visage fut changée envers Shadrac, Méshac et Abed-Nego. Il prit la parole et commanda de chauffer la fournaise sept fois plus qu’on n’était accoutumé de la chauffer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'et il commanda aux hommes les plus vaillants de son armée, de lier Shadrac, Méshac et Abed-Nego, et de les jeter dans la fournaise de feu ardent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Alors ces hommes furent liés dans leurs caleçons, leurs tuniques, et leurs manteaux et leurs vêtements, et jetés au milieu de la fournaise de feu ardent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Parce que la parole du roi était rigoureuse et la fournaise extrêmement chauffée, la flamme du feu tua ces hommes qui avaient fait monter Shadrac, Méshac et Abed-Nego;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'et ces trois hommes, Shadrac, Méshac et Abed-Nego, tombèrent liés au milieu de la fournaise de feu ardent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Alors le roi Nebucadnetsar, consterné, se leva précipitamment [et] prit la parole et dit à ses conseillers: N’avons-nous pas jeté au milieu du feu trois hommes liés? Ils répondirent et dirent au roi: Certainement, ô roi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Il répondit et dit: Voici, je vois quatre hommes déliés, se promenant au milieu du feu, et ils n’ont aucun mal; et l’aspect du quatrième est semblable à un fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Alors Nebucadnetsar s’approcha de l’ouverture de la fournaise de feu ardent; il prit la parole et dit: Shadrac, Méshac et Abed-Nego, serviteurs du Dieu Très-haut, sortez et venez! Alors Shadrac, Méshac et Abed-Nego sortirent du milieu du feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Et les satrapes, les préfets, les gouverneurs, et les conseillers du roi, qui étaient assemblés, virent ces hommes sur le corps desquels le feu n’avait eu aucune puissance: les cheveux de leur tête n’avaient pas été brûlés, et leurs caleçons n’avaient pas changé, et l’odeur du feu n’avait pas passé sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Nebucadnetsar prit la parole et dit: Béni soit le Dieu de Shadrac, de Méshac et d’Abed-Nego, qui a envoyé son ange et a sauvé ses serviteurs qui se sont confiés en lui, et ont changé la parole du roi, et ont livré leurs corps, afin de ne servir et n’adorer aucun autre dieu que leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Et de par moi l’ordre est donné qu’en tout peuple, peuplade, et langue, quiconque parlera mal du Dieu de Shadrac, de Méshac et d’Abed-Nego, sera mis en pièces, et sa maison sera réduite en un tas d’immondices, parce qu’il n’y a pas d’autre Dieu qui puisse sauver ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Alors le roi éleva Shadrac, Méshac et Abed-Nego dans la province de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 31, '*Nebucadnetsar, le roi, à tous les peuples, peuplades et langues, qui habitent sur toute la terre: Que votre paix soit multipliée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 32, 'Il m’a semblé bon de faire connaître les signes et les prodiges que le Dieu Très-haut a opérés à mon égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 33, 'Ses signes, combien ils sont grands! Et ses prodiges, combien ils sont puissants! Son royaume est un royaume éternel, et sa domination est de génération en génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Moi, Nebucadnetsar, j’étais en paix dans ma maison, et florissant dans mon palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Je vis un songe, et il m’effraya, et les pensées que j’avais sur mon lit, et les visions de ma tête, me troublèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Et de par moi fut donné un ordre qu’on amène devant moi tous les sages de Babylone pour qu’ils me fassent connaître l’interprétation du songe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Alors vinrent les devins, les enchanteurs, les Chaldéens, et les augures; et je dis le songe devant eux, mais ils ne m’en firent pas connaître l’interprétation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'mais, à la fin, entra devant moi Daniel, dont le nom est Belteshatsar, selon le nom de mon dieu, et en qui est l’esprit des dieux saints; et je dis le songe devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Belteshatsar, chef des devins, puisque je sais que l’esprit des dieux saints est en toi, et qu’aucun secret ne t’embarrasse, dis-moi les visions du songe que j’ai vu, et son interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Or les visions de ma tête, sur mon lit, [étaient celles-ci]: je voyais, et voici, un arbre au milieu de la terre, et sa hauteur était grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'L’arbre crût et devint fort, et sa hauteur atteignit jusqu’aux cieux, et on le voyait jusqu’au bout de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Son feuillage était beau et son fruit abondant, et en lui il y avait de la nourriture pour tous; sous son ombre se tenaient les bêtes des champs, et dans ses branches habitaient les oiseaux des cieux; et de lui toute chair se nourrissait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Je voyais, dans les visions de ma tête, sur mon lit, et voici un veillant, un saint, descendit des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Il cria avec force, et dit ainsi: Abattez l’arbre et coupez ses branches, faites tomber son feuillage et dispersez son fruit; que les bêtes s’enfuient de dessous lui, et les oiseaux, de ses branches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Toutefois, laissez dans la terre le tronc de ses racines, avec un lien de fer et d’airain [autour de lui], dans l’herbe des champs; et qu’il soit baigné de la rosée des cieux, et qu’il ait, avec les bêtes, sa part à l’herbe de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'que son cœur d’homme soit changé, et qu’un cœur de bête lui soit donné; et que sept temps passent sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Cette sentence est par le décret des veillants, et la chose, par la parole des saints, afin que les vivants sachent que le Très-haut domine sur le royaume des hommes, et qu’il le donne à qui il veut, et y élève le plus vil des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Ce songe, moi, le roi Nebucadnetsar, je l’ai vu; et toi, Belteshatsar, dis-en l’interprétation, puisque tous les sages de mon royaume n’ont pas pu me faire connaître l’interprétation; mais toi, tu le peux, car l’esprit des dieux saints est en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Alors Daniel, dont le nom est Belteshatsar, fut stupéfié pour une heure environ, et ses pensées le troublèrent. Le roi prit la parole et dit: Belteshatsar, que le songe et son interprétation ne te troublent pas. Belteshatsar répondit et dit: Mon seigneur! que le songe soit pour ceux qui te haïssent, et son interprétation pour tes ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'L’arbre que tu as vu, qui croissait et devenait fort, et dont la hauteur atteignait jusqu’aux cieux, et qu’on voyait de toute la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'et dont le feuillage était beau et le fruit abondant, et qui avait de la nourriture pour tous, sous lequel habitaient les bêtes des champs, et dans les branches duquel demeuraient les oiseaux des cieux:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'c’est toi, ô roi, qui t’es agrandi et es devenu puissant; et ta grandeur s’est accrue et atteint jusqu’aux cieux, et ta domination, jusqu’au bout de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Et quant à ce que le roi a vu un veillant, un saint, descendre des cieux et dire: Abattez l’arbre et détruisez-le; toutefois laissez dans la terre le tronc de ses racines, avec un lien de fer et d’airain [autour de lui], dans l’herbe des champs, et qu’il soit baigné de la rosée des cieux, et qu’il ait sa part avec les bêtes des champs jusqu’à ce que sept temps passent sur lui, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'c’est ici l’interprétation, ô roi, et la décision du Très-haut, ce qui va arriver au roi, mon seigneur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'On te chassera du milieu des hommes, et ta demeure sera avec les bêtes des champs, et on te fera manger l’herbe comme les bœufs, et tu seras baigné de la rosée des cieux, et sept temps passeront sur toi, jusqu’à ce que tu connaisses que le Très-haut domine sur le royaume des hommes, et qu’il le donne à qui il veut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Et quant à ce qu’on a dit de laisser le tronc des racines de l’arbre, ton royaume te demeurera, quand tu auras connu que les cieux dominent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'C’est pourquoi, ô roi, que mon conseil te soit agréable; et romps avec tes péchés par la justice, et avec ton iniquité, par la compassion envers les affligés, si ce peut être un prolongement de ta paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Tout cela arriva au roi Nebucadnetsar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Au bout de douze mois, il se promenait sur le palais du royaume de Babylone.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Le roi prit la parole et dit: N’est-ce pas ici Babylone la grande, que j’ai bâtie pour être la maison de mon royaume, par la puissance de ma force et pour la gloire de ma magnificence?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'La parole était encore dans la bouche du roi, qu’une voix tomba des cieux: Roi Nebucadnetsar, il t’est dit: Le royaume s’en est allé d’avec toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'et on te chassera du milieu des hommes, et ta demeure sera avec les bêtes des champs; on te fera manger de l’herbe comme les bœufs, et sept temps passeront sur toi, jusqu’à ce que tu connaisses que le Très-haut domine sur le royaume des hommes et qu’il le donne à qui il veut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Au même instant la parole s’accomplit sur Nebucadnetsar: il fut chassé du milieu des hommes, et il mangea de l’herbe comme les bœufs, et son corps fut baigné de la rosée des cieux, jusqu’à ce que ses cheveux soient devenus longs comme [les plumes] de l’aigle, et ses ongles, comme ceux des oiseaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Et à la fin de ces jours, moi, Nebucadnetsar, j’élevai mes yeux vers les cieux, et mon intelligence me revint, et je bénis le Très-haut, et je louai et magnifiai celui qui vit éternellement, duquel la domination est une domination éternelle, et dont le royaume est de génération en génération;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'et tous les habitants de la terre sont réputés comme néant, et il agit selon son bon plaisir dans l’armée des cieux et parmi les habitants de la terre; et il n’y a personne qui puisse arrêter sa main et lui dire: Que fais-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Dans ce temps-là, mon intelligence me revint, et, pour la gloire de mon royaume, ma magnificence et ma splendeur me revinrent, et mes conseillers et mes grands me cherchèrent, et je fus rétabli dans mon royaume, et ma grandeur fut extraordinairement augmentée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Maintenant, moi, Nebucadnetsar, je loue et j’exalte et je magnifie le roi des cieux, dont toutes les œuvres sont vérité, et les voies, jugement, et qui est puissant pour abaisser ceux qui marchent avec orgueil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, '*Le roi Belshatsar fit un grand festin à 1 000 de ses grands, et but du vin devant les 1 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Belshatsar, comme il buvait le vin, commanda d’apporter les vases d’or et d’argent que son père Nebucadnetsar avait tirés du temple qui était à Jérusalem, afin que le roi et ses grands, ses femmes et ses concubines, y boivent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Alors on apporta les vases d’or qu’on avait tirés du temple de la maison de Dieu, qui était à Jérusalem; et le roi et ses grands, ses femmes et ses concubines, y burent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Ils burent du vin, et ils louèrent les dieux d’or et d’argent, d’airain, de fer, de bois, et de pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'En ce même moment, les doigts d’une main d’homme sortirent, et écrivirent, vis-à-vis du chandelier, sur le plâtre de la muraille du palais du roi; et le roi vit l’extrémité de la main qui écrivait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Alors le roi changea de couleur, et ses pensées le troublèrent; et les liens de ses reins se délièrent, et ses genoux se heurtèrent l’un contre l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Le roi cria avec force d’amener les enchanteurs, les Chaldéens et les augures. Le roi prit la parole et dit aux sages de Babylone: Quiconque lira cette écriture et m’en indiquera l’interprétation sera revêtu de pourpre, et [aura] une chaîne d’or autour de son cou, et sera le troisième gouverneur dans le royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Alors arrivèrent tous les sages du roi, mais ils ne purent lire l’écriture ni faire connaître au roi l’interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Alors le roi Belshatsar fut extrêmement troublé, et il changea de couleur; et ses grands furent bouleversés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'La reine, à cause des paroles du roi et de ses grands, entra dans la maison du festin. La reine prit la parole et dit: Ô roi, vis à jamais! Que tes pensées ne te troublent pas, et ne change pas de couleur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'il y a un homme dans ton royaume, en qui est l’esprit des dieux saints; et, aux jours de ton père, de la lumière, et de l’intelligence, et une sagesse comme la sagesse des dieux, ont été trouvées en lui; et le roi Nebucadnetsar, ton père, – ton père, ô roi, l’a établi chef des devins, des enchanteurs, des Chaldéens, des augures,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'parce qu’un esprit extraordinaire, et la connaissance et l’intelligence pour interpréter les songes et pour expliquer les énigmes et pour résoudre les problèmes difficiles, ont été trouvés en lui, en Daniel, à qui le roi a donné le nom de Belteshatsar. Que Daniel soit donc appelé, et il indiquera l’interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Alors Daniel fut introduit devant le roi. Le roi prit la parole et dit à Daniel: Es-tu ce Daniel, l’un des fils de la captivité de Juda, que le roi, mon père, a amenés de Juda?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Et j’ai entendu dire de toi que l’esprit des dieux est en toi, et que de la lumière, et de l’intelligence, et une sagesse extraordinaire se trouvent en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Et maintenant, les sages, les enchanteurs, ont été amenés devant moi, afin qu’ils lisent cette écriture et m’en fassent connaître l’interprétation, et ils n’ont pu indiquer l’interprétation de la chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Et j’ai entendu dire de toi que tu peux donner des interprétations et résoudre les problèmes difficiles. Maintenant, si tu peux lire l’écriture et m’en faire connaître l’interprétation, tu seras vêtu de pourpre, et tu auras une chaîne d’or autour de ton cou, et tu seras le troisième gouverneur dans le royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Alors Daniel répondit et dit devant le roi: Que tes présents te demeurent, et donne tes récompenses à un autre. Toutefois je lirai l’écriture au roi, et je lui en ferai connaître l’interprétation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Ô roi, le Dieu Très-haut donna à Nebucadnetsar, ton père, le royaume, et la grandeur, et l’honneur, et la majesté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'et, à cause de la grandeur qu’il lui donna, tous les peuples, les peuplades et les langues, tremblaient devant lui, et le craignaient; il tuait qui il voulait, et il conservait en vie qui il voulait; il exaltait qui il voulait, et il abaissait qui il voulait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Mais quand son cœur s’éleva et que son esprit s’endurcit jusqu’à l’orgueil, il fut précipité du trône de son royaume, et sa dignité lui fut ôtée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'et il fut chassé du milieu des fils des hommes, et son cœur fut rendu semblable à celui des bêtes, et sa demeure fut avec les ânes sauvages; on le nourrit d’herbe comme les bœufs, et son corps fut baigné de la rosée des cieux, jusqu’à ce qu’il connut que le Dieu Très-haut domine sur le royaume des hommes, et qu’il y établit qui il veut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Et toi, son fils Belshatsar, tu n’as pas humilié ton cœur, bien que tu aies su tout cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Mais tu t’es élevé contre le Seigneur des cieux; et on a apporté devant toi les vases de sa maison, et toi et tes grands, tes femmes et tes concubines, vous y avez bu du vin; et tu as loué les dieux d’argent et d’or, d’airain, de fer, de bois et de pierre, qui ne voient, et n’entendent, et ne comprennent point; et le Dieu en la main duquel est ton souffle, et à qui appartiennent toutes tes voies, tu ne l’as pas glorifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Alors a été envoyée de sa part l’extrémité de la main, et cette écriture a été tracée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Et voici l’écriture qui a été tracée: Mené, Mené, Thekel, Upharsin!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Voici l’interprétation des paroles. Mené: Dieu a compté ton royaume, et y a mis fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Thekel: Tu as été pesé à la balance, et tu as été trouvé manquant de poids.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Pérès: Ton royaume est divisé, et donné aux Mèdes et aux Perses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Alors Belshatsar donna des ordres, et on vêtit Daniel de pourpre, et [on mit] une chaîne d’or à son cou, et on proclama qu’il serait le troisième gouverneur dans le royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'En cette nuit-là, Belshatsar, roi des Chaldéens, fut tué.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Et Darius, le Mède, reçut le royaume, étant âgé d’environ 62 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, '*Il plut à Darius d’établir sur le royaume 120 satrapes, pour qu’ils soient dans tout le royaume;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'et au-dessus d’eux, trois présidents, dont Daniel était l’un, pour que ces satrapes leur rendent compte, et que le roi ne souffre aucun dommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Et ce Daniel surpassa les présidents et les satrapes, parce qu’il y avait en lui un esprit extraordinaire; et le roi pensa à l’établir sur tout le royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Alors les présidents et les satrapes cherchèrent à trouver dans [l’administration du] royaume quelque sujet d’accusation contre Daniel; et ils ne pouvaient trouver aucun sujet d’accusation ni aucune faute, parce qu’il était fidèle; et aucun manquement ni aucune faute ne se trouva en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Et ces hommes dirent: Nous ne trouverons dans ce Daniel aucun sujet d’accusation, à moins que nous n’en trouvions contre lui à cause de la loi de son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Alors ces présidents et ces satrapes s’assemblèrent en foule auprès du roi, et lui parlèrent ainsi: Roi Darius, vis à jamais!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Tous les présidents du royaume, les préfets et les satrapes, les conseillers et les gouverneurs, ont tenu conseil ensemble pour établir un statut royal et mettre en vigueur une défense, [portant] que quiconque fera une demande à quelque dieu ou à quelque homme que ce soit, durant 30 jours, excepté à toi, ô roi, sera jeté dans la fosse aux lions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Maintenant, ô roi, établis la défense, et signe l’écrit afin qu’il ne soit pas changé, selon la loi des Mèdes et des Perses, qui ne peut être abrogée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'À cause de cela, le roi Darius signa l’écrit et la défense.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Or Daniel, quand il sut que l’écrit était signé, entra dans sa maison; et, ses fenêtres étant ouvertes dans sa chambre haute, du côté de Jérusalem, il s’agenouillait sur ses genoux trois fois le jour, et priait, et rendait grâce devant son Dieu, comme il avait fait auparavant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Mais ces hommes s’assemblèrent en foule et trouvèrent Daniel qui priait et présentait sa supplication devant son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Alors ils s’approchèrent et dirent devant le roi, touchant la défense du roi: N’as-tu pas signé une défense, [portant] que tout homme qui, durant 30 jours, ferait une demande à quelque dieu ou à quelque homme que ce soit, excepté à toi, ô roi, serait jeté dans la fosse aux lions? Le roi répondit et dit: La chose est certaine, selon la loi des Mèdes et des Perses, qui ne peut être abrogée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Alors ils répondirent et dirent devant le roi: Daniel, qui est d’entre les fils de la captivité de Juda, ne tient pas compte de toi, ô roi, ni de la défense que tu as signée, mais il fait sa requête trois fois par jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Alors le roi, quand il entendit ces paroles, en fut fort affligé, et il pensa avec sollicitude à Daniel afin de le sauver, et jusqu’au coucher du soleil il s’efforça de le délivrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Alors ces hommes s’assemblèrent en foule auprès du roi, et dirent au roi: Sache, ô roi, que c’est la loi des Mèdes et des Perses, qu’aucune défense ou statut que le roi a établi, ne peut être changé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Alors le roi donna des ordres, et on amena Daniel, et on le jeta dans la fosse aux lions. Le roi prit la parole et dit à Daniel: Ton Dieu que tu sers continuellement, lui, te sauvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Et une pierre fut apportée et mise sur l’ouverture de la fosse, et le roi la scella de son cachet et du cachet de ses grands, afin que l’intention à l’égard de Daniel ne soit pas changée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Alors le roi s’en alla dans son palais, et il passa la nuit en jeûnant, et ne voulut pas qu’on lui amène des concubines; et son sommeil s’enfuit loin de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Ensuite le roi se leva avec l’aurore, au point du jour, et s’en alla en hâte à la fosse aux lions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Et comme il approchait de la fosse, il cria à Daniel d’une voix triste. Le roi prit la parole et dit à Daniel: Daniel, serviteur du Dieu vivant, ton Dieu, que tu sers continuellement, a-t-il pu te délivrer des lions?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Alors Daniel parla au roi: Ô roi, vis à jamais!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Mon Dieu a envoyé son ange et a fermé la gueule des lions, et ils ne m’ont fait aucun mal, parce que devant lui l’innocence s’est trouvée en moi, et devant toi non plus, ô roi, je n’ai rien fait de mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Alors le roi fut très joyeux et dit qu’on tire Daniel de la fosse. Et Daniel fut tiré de la fosse, et aucun mal ne fut trouvé sur lui, parce qu’il s’était confié en son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Et le roi donna des ordres, et on amena ces hommes qui avaient accusé Daniel, et on les jeta dans la fosse aux lions, eux, leurs enfants et leurs femmes; et ils n’étaient pas parvenus au fond de la fosse, que déjà les lions se rendirent maîtres d’eux et leur brisèrent tous les os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Alors le roi Darius écrivit: À tous les peuples, peuplades et langues, qui habitent sur toute la terre! Que votre paix soit multipliée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'De par moi l’ordre est donné que, dans tous les gouvernements de mon royaume, on tremble devant le Dieu de Daniel et on le craigne; car il est le Dieu vivant, et il subsiste à jamais, et son royaume est [un royaume] qui ne sera pas détruit, et sa domination [durera] jusqu’à la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Il sauve et il délivre, et il opère des signes et des prodiges dans les cieux et sur la terre: c’est lui qui a sauvé Daniel de la puissance des lions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 29, 'Et ce Daniel prospéra pendant le règne de Darius et pendant le règne de Cyrus, le Perse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, '**La première année de Belshatsar, roi de Babylone, Daniel vit un songe, et des visions de sa tête, sur son lit. Alors il écrivit le songe, [et] raconta la somme des choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel prit la parole et dit: Je voyais dans ma vision de nuit, et voici, les quatre vents des cieux se déchaînèrent sur la grande mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Et quatre grandes bêtes montèrent de la mer, différentes l’une de l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'La première était comme un lion, et elle avait des ailes d’aigle. Je vis jusqu’à ce que ses ailes furent arrachées, et qu’elle fut soulevée de terre, et mise debout sur ses pieds, comme un homme; et un cœur d’homme lui fut donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Et voici une autre, une seconde bête, semblable à un ours, et elle se dressait sur un côté. Et [elle avait] trois côtes dans sa gueule, entre ses dents; et on lui dit ainsi: Lève-toi, mange beaucoup de chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Après cela, je vis, et en voici une autre, – comme un léopard; et elle avait quatre ailes d’oiseau sur son dos; et la bête avait quatre têtes; et la domination lui fut donnée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Après cela je vis dans les visions de la nuit, et voici une quatrième bête, effrayante et terrible et extraordinairement puissante, et elle avait de grandes dents de fer: elle dévorait et écrasait; et ce qui restait, elle le foulait avec ses pieds. Et elle était différente de toutes les bêtes qui étaient avant elle; et elle avait dix cornes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Je considérais les cornes, et voici une autre corne, petite, monta au milieu d’elles, et trois des premières cornes furent arrachées devant elle. Et voici, [il y avait] à cette corne des yeux comme des yeux d’homme, et une bouche proférant de grandes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Je vis jusqu’à ce que les trônes furent placés, et que l’Ancien des jours s’assit. Son vêtement était blanc comme la neige, et les cheveux de sa tête, comme de la laine pure; son trône était des flammes de feu; les roues du trône, un feu brûlant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Un fleuve de feu coulait et sortait de devant lui. Mille milliers le servaient, et des myriades de myriades se tenaient devant lui. Le jugement s’assit, et les livres furent ouverts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Je vis alors, à cause de la voix des grandes paroles que la corne proférait, – je vis jusqu’à ce que la bête fut tuée; et son corps fut détruit et elle fut livrée pour être brûlée au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Quant aux autres bêtes, la domination leur fut ôtée; mais une prolongation de vie leur fut donnée, jusqu’à une saison et un temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Je voyais dans les visions de la nuit, et voici, [quelqu’un] comme un fils d’homme vint avec les nuées des cieux, et il avança jusqu’à l’Ancien des jours, et on le fit approcher de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Et on lui donna la domination, et l’honneur, et la royauté, pour que tous les peuples, les peuplades et les langues, le servent. Sa domination est une domination éternelle, qui ne passera pas, et son royaume, [un royaume] qui ne sera pas détruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Moi, Daniel, je fus troublé dans mon esprit au-dedans de mon corps, et les visions de ma tête m’effrayèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Je m’approchai de l’un de ceux qui se tenaient là, et je lui demandai la vérité touchant tout cela. Et il me [la] dit, et me fit savoir l’interprétation des choses:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Ces grandes bêtes, qui sont quatre, sont quatre rois qui surgiront de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'et les saints des [lieux] très hauts recevront le royaume, et posséderont le royaume à jamais, et aux siècles des siècles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Alors je désirai de savoir la vérité touchant la quatrième bête, qui était différente d’elles toutes, extraordinairement terrible: ses dents étaient de fer, et ses ongles, d’airain; elle dévorait, écrasait, et foulait avec ses pieds ce qui restait;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'et touchant les dix cornes qui étaient sur sa tête, et touchant l’autre qui montait, et devant laquelle trois étaient tombées, cette corne qui avait des yeux, et une bouche proférant de grandes choses, et dont l’aspect était plus grand que celui des autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Je regardais; et cette corne fit la guerre contre les saints, et prévalut contre eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'jusqu’à ce que l’Ancien des jours vint, et que le jugement fut donné aux saints des [lieux] très hauts, et que le temps arriva où les saints possédèrent le royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Il dit ainsi: La quatrième bête sera un quatrième royaume sur la terre, qui sera différent de tous les royaumes, et dévorera toute la terre, et la foulera aux pieds et l’écrasera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Et les dix cornes,... ce sont dix rois qui surgiront du royaume. Et un autre surgira après eux; et il sera différent des premiers; et il abattra trois rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Et il proférera des paroles contre le Très-haut, et il consumera les saints des [lieux] très hauts, et il pensera changer [les] saisons et [la] loi, et elles seront livrées en sa main jusqu’à un temps et [des] temps et une moitié de temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Et le jugement s’assiéra; et on lui ôtera la domination, pour la détruire et la faire périr jusqu’à la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Et le royaume, et la domination, et la grandeur des royaumes sous tous les cieux, seront donnés au peuple des saints des [lieux] très hauts. Son royaume est un royaume éternel, et toutes les dominations le serviront et lui obéiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Jusqu’ici, la fin de la chose. Quant à moi, Daniel, mes pensées me troublèrent beaucoup, et ma couleur fut changée en moi. Mais je gardai la chose dans mon cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, '*La troisième année du règne de Belshatsar le roi, une vision m’apparut, à moi, Daniel, après celle qui m’était apparue au commencement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Et je vis dans la vision; et il arriva, quand je vis, que j’étais à Suse, le palais, qui est dans la province d’Élam. Et je vis dans la vision, et j’étais près du fleuve Ulaï.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Et je levai les yeux, et je vis; et voici, un bélier se tenait devant le fleuve, et il avait deux cornes; et les deux cornes étaient hautes, et l’une était plus haute que l’autre, et la plus haute s’éleva la dernière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Je vis le bélier heurtant vers l’occident, et vers le nord, et vers le midi; et aucune bête ne pouvait tenir devant lui, et il n’y avait personne qui puisse délivrer de sa main; et il fit selon son gré, et devint grand.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Et je considérais, et voici, un bouc venant du couchant sur la face de toute la terre, et qui ne touchait pas la terre; et le bouc avait une corne de grande apparence entre ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Et il vint jusqu’au bélier qui avait les deux cornes, que j’avais vu se tenir devant le fleuve, et courut sur lui dans la fureur de sa force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Et je le vis arriver tout près du bélier, et il s’exaspéra contre lui et frappa le bélier, et brisa ses deux cornes, et le bélier fut sans force pour tenir devant lui: il le jeta par terre et le foula aux pieds, et il n’y eut personne qui puisse délivrer le bélier de sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Et le bouc devint très grand; et lorsqu’il fut devenu fort, la grande corne fut brisée, et quatre cornes de grande apparence s’élevèrent à sa place, vers les quatre vents des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Et de l’une d’elles sortit une petite corne, et elle grandit extrêmement vers le midi, et vers le levant, et vers le [pays] de beauté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Et elle grandit jusqu’à l’armée des cieux, et fit tomber à terre une partie de l’armée et des étoiles, et les foula aux pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, '(Et il s’éleva jusqu’au chef de l’armée; et le [sacrifice] continuel fut ôté à celui-ci, et le lieu de son sanctuaire fut renversé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Et un temps de détresse fut assigné au [sacrifice] continuel, pour cause de transgression.) Et elle jeta la vérité par terre, et agit, et prospéra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Et j’entendis un saint qui parlait; et un autre saint dit au personnage qui parlait: Jusqu’où [va] la vision du [sacrifice] continuel et de la transgression qui désole, pour livrer le lieu saint et l’armée pour être foulés aux pieds?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Et il me dit: Jusqu’à 2 300 soirs [et] matins; alors le lieu saint sera purifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Et il arriva que, lorsque moi, Daniel, j’eus vu la vision, j’en cherchai l’intelligence; et voici, comme l’apparence d’un homme se tint vis-à-vis de moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'et j’entendis la voix d’un homme au milieu de l’Ulaï; et il cria et dit: Gabriel, fais comprendre à celui-ci la vision.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Et il vint près du lieu où j’étais, et quand il vint, je fus effrayé et je tombai sur ma face; et il me dit: Comprends, fils d’homme, car la vision est pour le temps de la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Or, comme il parlait avec moi, j’étais dans une profonde stupeur, ma face contre terre; et il me toucha et me fit tenir debout à la place où j’étais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Et il dit: Voici, je te fais connaître ce qui aura lieu à la fin de l’indignation; car à un temps déterminé sera la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Le bélier que tu as vu, qui avait deux cornes, ce sont les rois de Médie et de Perse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Et le bouc velu, c’est le roi de Javan; et la grande corne qui était entre ses yeux, c’est le premier roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'et qu’elle ait été brisée et que quatre [autres cornes] se soient élevées à sa place, c’est que quatre royaumes s’élèveront de la nation, mais non avec sa puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Et au dernier temps de leur royaume, quand les transgresseurs auront comblé la mesure, il s’élèvera un roi au visage audacieux, et entendant les énigmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'et sa puissance sera forte, mais non par sa propre puissance; et il détruira merveilleusement, et il prospérera et agira; et il détruira les [hommes] forts et le peuple des saints;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'et, par son intelligence, il fera prospérer la fraude dans sa main; et il s’élèvera dans son cœur; et, par la prospérité il corrompra beaucoup de gens; et il se lèvera contre le prince des princes, mais il sera brisé sans main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Et la vision du soir et du matin, qui a été dite, est vérité. Et toi, serre la vision, car [elle est] pour beaucoup de jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Et moi, Daniel, je défaillis, et je fus malade quelques jours; puis je me levai, et je m’occupai des affaires du roi. Et je fus stupéfié de la vision, mais personne ne la comprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'La première année de Darius, fils d’Assuérus, de la semence des Mèdes, qui fut fait roi sur le royaume des Chaldéens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'la première année de son règne, moi, Daniel, je compris par les livres que le nombre des années touchant lequel la parole de l’ Éternel vint à Jérémie le prophète, pour l’accomplissement des désolations de Jérusalem, était de 70 années.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Et je tournai ma face vers le Seigneur Dieu, pour [le] rechercher par la prière et la supplication, dans le jeûne, et le sac et la cendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Et je priai l’ Éternel, mon Dieu, et je fis ma confession, et je dis: Je te supplie, Seigneur, le ✶Dieu grand et terrible, qui gardes l’alliance et la bonté envers ceux qui t’aiment et qui gardent tes commandements!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Nous avons péché, nous avons commis l’iniquité, nous avons agi méchamment, et nous nous sommes rebellés et nous nous sommes détournés de tes commandements et de tes ordonnances;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'et nous n’avons pas écouté tes serviteurs les prophètes, qui parlaient en ton nom à nos rois, à nos princes, et à nos pères, et à tout le peuple du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'À toi, Seigneur, la justice, et à nous la confusion de face, comme [elle est] aujourd’hui, – aux hommes de Juda et aux habitants de Jérusalem et à tout Israël, à ceux qui sont près et à ceux qui sont loin, dans tous les pays où tu les as chassés, à cause de leurs infidélités par lesquelles ils ont été infidèles envers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Seigneur, à nous la confusion de face, à nos rois, à nos princes, et à nos pères, parce que nous avons péché contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Au Seigneur notre Dieu sont les compassions et les pardons, car nous nous sommes rebellés contre lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'et nous n’avons pas écouté la voix de l’ Éternel, notre Dieu, pour marcher selon ses lois qu’il a mises devant nous par ses serviteurs les prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Et tout Israël a transgressé ta loi et s’est détourné en n’écoutant pas ta voix. Alors ont été versés sur nous l’exécration et le serment qui sont écrits dans la loi de Moïse, serviteur de Dieu, parce que nous avons péché contre lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'et il a accompli ses paroles qu’il a prononcées contre nous et contre nos juges qui nous jugeaient, en faisant venir sur nous un mal si grand que rien ne s’est fait sous tous les cieux comme ce qui a été fait à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Selon qu’il est écrit dans la loi de Moïse, tout ce mal est venu sur nous; et nous n’avons pas imploré l’ Éternel, notre Dieu, afin de revenir de nos iniquités et de comprendre ta vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Et l’ Éternel a veillé sur le mal, et l’a fait venir sur nous; car l’ Éternel, notre Dieu, est juste dans toutes les œuvres qu’il a faites; et nous n’avons pas écouté sa voix. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Et maintenant, Seigneur, notre Dieu, toi qui as fait sortir ton peuple du pays d’Égypte à main forte, et qui t’es fait un nom, comme [il paraît] aujourd’hui: nous avons péché, nous avons agi méchamment!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Seigneur, selon toutes tes justices, que ta colère et ta fureur se détournent, je te prie, de ta ville de Jérusalem, ta sainte montagne. Car à cause de nos péchés, et à cause des iniquités de nos pères, Jérusalem et ton peuple sont en opprobre à tous ceux qui nous entourent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Et maintenant, écoute, ô notre Dieu, la prière de ton serviteur et ses supplications, et, pour l’amour du Seigneur, fais luire ta face sur ton sanctuaire désolé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Incline ton oreille, ô mon Dieu, et écoute; ouvre tes yeux, et vois nos désolations, et la ville qui est appelée de ton nom. Car ce n’est pas à cause de nos justices que nous présentons devant toi nos supplications, mais à cause de tes grandes compassions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Seigneur, écoute; Seigneur, pardonne; Seigneur, sois attentif et agis; ne tarde pas, à cause de toi-même, mon Dieu; car ta ville et ton peuple sont appelés de ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Et je parlais encore, et je priais et confessais mon péché et le péché de mon peuple Israël, et je présentais ma supplication devant l’ Éternel, mon Dieu, pour la sainte montagne de mon Dieu, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'je parlais encore en priant, et l’homme Gabriel que j’avais vu dans la vision au commencement, volant avec rapidité, me toucha vers le temps de l’offrande de gâteau du soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Et il me fit comprendre, et me parla, et dit: Daniel, je suis maintenant sorti pour éclairer ton intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Au commencement de tes supplications la parole est sortie, et je suis venu pour [te la] déclarer, car tu es un bien-aimé. Comprends donc la parole, et sois intelligent dans la vision:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, '70 semaines ont été déterminées sur ton peuple et sur ta sainte ville, pour clore la transgression, et pour en finir avec les péchés, et pour faire propitiation pour l’iniquité, et pour introduire la justice des siècles, et pour sceller la vision et le prophète, et pour oindre le saint des saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Et sache, et comprends: Depuis la sortie de la parole pour rétablir et rebâtir Jérusalem, jusqu’au Messie, [le] prince, il y a 7 semaines et 62 semaines; la place et le fossé seront rebâtis, et [cela] en des temps de trouble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Et après les 62 semaines, [le] Messie sera retranché et n’aura rien; et le peuple du prince qui viendra, détruira la ville et le lieu saint, et la fin en sera avec débordement; et jusqu’à la fin [il y aura] guerre, un décret de désolations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Et il confirmera une alliance avec la multitude [pour] une semaine; et au milieu de la semaine il fera cesser le sacrifice et l’offrande; et à cause de la protection des abominations [il y aura] un désolateur, et jusqu’à ce que la consomption et [ce qui est] décrété soient versés sur la désolée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, '*La troisième année de Cyrus, roi de Perse, une chose fut révélée à Daniel qui est appelé du nom de Belteshatsar; et la chose est vraie, mais le temps d’épreuve déterminé est long. Et il comprit la chose et eut l’intelligence de la vision.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'En ces jours-là, moi, Daniel, je menai deuil trois semaines entières;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'je ne mangeai pas de pain agréable, et la chair et le vin n’entrèrent pas dans ma bouche; et je ne m’oignis point, jusqu’à ce que trois semaines entières soient accomplies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Et le vingt-quatrième jour du premier mois, j’étais au bord du grand fleuve qui est le Hiddékel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'et je levai les yeux, et je vis; et voici un homme vêtu de lin, et ses reins étaient ceints d’or d’Uphaz;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'et son corps était comme une chrysolithe, et son visage comme l’aspect de l’éclair, et ses yeux comme des flammes de feu, et ses bras et ses pieds comme l’apparence de l’airain poli, et la voix de ses paroles comme la voix d’une multitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Et moi, Daniel, je vis seul la vision, et les hommes qui étaient avec moi ne virent pas la vision, mais un grand tremblement tomba sur eux, et ils coururent pour se cacher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Et moi je fus laissé seul, et je vis cette grande vision; et il ne resta aucune force en moi, et mon teint frais fut changé en corruption, et je ne conservai aucune force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Et j’entendis la voix de ses paroles; et, comme j’entendais la voix de ses paroles, je tombai dans une profonde stupeur sur ma face, et ma face contre terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Et voici, une main me toucha et me secoua, [et me mit] sur mes genoux et sur les paumes de mes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Et il me dit: Daniel, homme bien-aimé, comprends les paroles que je te dis, et tiens-toi debout à la place où tu es; car je suis maintenant envoyé vers toi. Et comme il parlait avec moi, [disant] cette parole, je me tins debout, tremblant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Et il me dit: Ne crains pas, Daniel, car dès le premier jour où tu as appliqué ton cœur à comprendre et à t’humilier devant ton Dieu, tes paroles ont été entendues, et moi, je suis venu à cause de tes paroles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'mais le chef du royaume de Perse m’a résisté 21 jours, et voici, Micaël, un des premiers chefs, vint à mon secours: et je restai là, auprès des rois de Perse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Et je suis venu pour te faire comprendre ce qui arrivera à ton peuple à la fin des jours; car la vision est encore pour [beaucoup de] jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Et comme il parlait avec moi selon ces paroles, je tournai ma face vers la terre, et je devins muet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Et voici, comme la ressemblance des fils des hommes toucha mes lèvres. Et j’ouvris ma bouche et je parlai, et je dis à celui qui se tenait devant moi: Mon seigneur, par la vision les douleurs m’ont saisi, et je n’ai conservé aucune force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Et comment le serviteur de mon seigneur, que voici, parlerait-il avec mon seigneur, que voici? Car pour moi, dès maintenant, aucune force ne subsiste en moi, et il ne reste plus en moi de souffle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Et comme l’aspect d’un homme me toucha de nouveau, et me fortifia,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'et il dit: Ne crains pas, homme bien-aimé; paix te soit! sois fort, oui, sois fort! Et comme il parlait avec moi, je pris des forces, et je dis: Que mon seigneur parle, car tu m’as fortifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Et il dit: Sais-tu pourquoi je suis venu vers toi? Et maintenant, je m’en retournerai pour combattre contre le chef de la Perse; et quand je sortirai, voici, le chef de Javan viendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Cependant je te déclarerai ce qui est consigné dans l’écrit de vérité; et pas un seul ne tient ferme avec moi contre ceux-là, sinon Micaël, votre chef.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Et moi, dans la première année de Darius, le Mède, je me tins là pour l’aider et le fortifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Et maintenant, je te déclarerai la vérité: Voici, il s’élèvera encore trois rois en Perse; et le quatrième deviendra riche de grandes richesses plus que tous, et quand il sera devenu fort par ses richesses, il excitera tout contre le royaume de Javan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Et un roi vaillant se lèvera et exercera une grande domination, et il agira selon son bon plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Et quand il se sera levé, son royaume sera brisé et sera divisé vers les quatre vents des cieux, et [ne passera] pas à sa postérité, et ne sera pas selon la domination qu’il exerçait; car son royaume sera arraché, et sera à d’autres, outre ceux-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Et le roi du midi sera fort, et un de ses chefs; mais [un autre] sera plus fort que lui, et dominera; sa domination sera une grande domination.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Et au bout de [plusieurs] années, ils s’uniront ensemble; et la fille du roi du midi viendra vers le roi du nord pour faire un arrangement droit; mais elle ne conservera pas la force de son bras; et il ne subsistera pas, ni son bras; et elle sera livrée, elle, et ceux qui l’ont amenée, et celui qui l’a engendrée, et celui qui l’aidait dans ces temps-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Mais d’un rejeton de ses racines se lèvera à sa place [un homme], et il viendra à l’armée, et il entrera dans la forteresse du roi du nord; et il agira contre eux et se montrera puissant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'et même il emmènera captifs, en Égypte, leurs dieux et leurs princes, avec leurs objets précieux, l’argent et l’or; et il subsistera plus d’années que le roi du nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Et celui-ci viendra dans le royaume du roi du midi et il retournera dans son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Mais ses fils s’irriteront et rassembleront une multitude de forces nombreuses; et [l’un d’eux] viendra et inondera et passera outre; et il reviendra et poussera le combat jusqu’à sa forteresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Et le roi du midi s’exaspérera, et sortira, et fera la guerre contre lui, contre le roi du nord; et celui-ci mettra sur pied une grande multitude, mais la multitude sera livrée en sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Et quand la multitude sera ôtée, son cœur s’exaltera, et il fera tomber des myriades; mais il ne prévaudra pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Et le roi du nord reviendra et mettra sur pied une multitude plus grande que la première; et au bout d’une période d’années, il s’avancera avec une armée nombreuse et de grandes richesses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Et, dans ces temps-là, plusieurs se lèveront contre le roi du midi, et les violents de ton peuple s’élèveront pour accomplir la vision; mais ils tomberont.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Et le roi du nord viendra, et il élèvera une terrasse, et s’emparera de la ville forte; et les forces du midi ne tiendront pas, ni l’élite de son peuple; et il n’y aura pas de force [en lui] pour se maintenir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Mais celui qui vient contre lui agira selon son gré, et il n’y aura personne qui lui résiste; et il se tiendra dans le pays de beauté, ayant la destruction dans sa main;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'et il dirigera sa face pour venir avec les forces de tout son royaume, et des hommes droits avec lui, et il agira; et il lui donnera la fille des femmes pour la pervertir; mais elle ne tiendra pas, et elle ne sera pas pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Et il tournera sa face vers les îles, et il en prendra beaucoup. Mais un chef mettra fin, pour lui, à son opprobre, [et] le fera retomber sur lui-même, sans opprobre pour lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'et il tournera sa face vers les forteresses de son propre pays; et il bronchera et tombera, et ne sera pas trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Puis il s’en élèvera un à sa place qui fera passer l’exacteur par la gloire du royaume; mais en quelques jours il sera brisé, non par colère, ni par guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Et un [homme] méprisé s’élèvera à sa place, auquel on ne donnera pas l’honneur du royaume; mais il entrera paisiblement, et prendra possession du royaume par des flatteries;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'et les forces qui débordent seront débordées devant lui et seront brisées, et même le prince de l’alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Et dès qu’il se sera associé à lui, il agira avec fraude, et il montera, et sera fort avec peu de gens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'En pleine paix il entrera dans les lieux les plus riches de la province, et il fera ce que ses pères et les pères de ses pères n’ont pas fait; il leur distribuera du butin, et des dépouilles, et des richesses, et il tramera ses desseins contre les places fortes, et [cela] pour un temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Et il réveillera sa puissance et son cœur contre le roi du midi, avec une grande armée. Et le roi du midi s’engagera dans la guerre avec une grande et très puissante armée. Mais il ne tiendra pas, car ils trameront leurs desseins contre lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'et ceux qui mangeaient ses mets délicats le briseront; et son armée se dissoudra, et beaucoup de gens tomberont tués.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Et ces deux rois auront à cœur de faire du mal, et diront des mensonges à une même table; mais cela ne réussira pas, car la fin sera encore pour le temps déterminé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Et il retournera dans son pays avec de grandes richesses, et son cœur sera contre la sainte alliance, et il agira, et retournera dans son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Au temps déterminé il retournera et viendra dans le midi; mais il n’en sera pas la dernière fois comme la première;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'car les navires de Kittim viendront contre lui; et il sera découragé, et retournera et sera courroucé contre la sainte alliance, et il agira; et il retournera et portera son attention sur ceux qui abandonnent la sainte alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Et des forces se tiendront là de sa part, et elles profaneront le sanctuaire de la forteresse, et ôteront le [sacrifice] continuel, et elles placeront l’abomination qui cause la désolation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Et, par de douces paroles, il entraînera à l’impiété ceux qui agissent méchamment à l’égard de l’alliance; mais le peuple qui connaît son Dieu sera fort et agira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Et les sages du peuple enseigneront la multitude; et ils tomberont par l’épée et par la flamme, par la captivité et par le pillage, plusieurs jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Et quand ils tomberont, ils seront secourus avec un peu de secours, et plusieurs se joindront à eux par des flatteries.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Et d’entre les sages il en tombera pour les éprouver ainsi, et pour les purifier, et pour les blanchir, jusqu’au temps de la fin; car ce sera encore pour le temps déterminé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Et le roi agira selon son bon plaisir, et s’exaltera, et s’élèvera contre tout ✶dieu, et proférera des choses impies contre le ✶Dieu des ✶dieux; et il prospérera jusqu’à ce que l’indignation soit accomplie; car ce qui est déterminé sera fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Et il n’aura point égard au Dieu de ses pères, et il n’aura point égard à l’objet du désir des femmes, ni à aucun ✝dieu; car il s’agrandira au-dessus de tout;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'et, à sa place, il honorera le ✝dieu des forteresses: avec de l’or, et avec de l’argent, et avec des pierres précieuses, et avec des choses désirables, il honorera un ✝dieu que n’ont pas connu ses pères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'et il agira dans les lieux forts des forteresses, avec un ✝dieu étranger: à qui le reconnaîtra il multipliera la gloire; et il les fera dominer sur la multitude et [leur] partagera le pays en récompense.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Et, au temps de la fin, le roi du midi heurtera contre lui, et le roi du nord fondra sur lui comme une tempête, avec des chars et des cavaliers, et avec beaucoup de navires, et entrera dans les pays et inondera et passera outre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'et il viendra dans le pays de beauté, et plusieurs [pays] tomberont; mais ceux-ci échapperont de sa main: Édom, et Moab, et les principaux des fils d’Ammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Et il étendra sa main sur les pays, et le pays d’Égypte n’ échappera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Et il aura sous sa puissance les trésors d’or et d’argent, et toutes les choses désirables de l’Égypte; et les Libyens et les Éthiopiens suivront ses pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Mais des nouvelles de l’orient et du nord l’effraieront, et il sortira en grande fureur pour exterminer et détruire entièrement beaucoup de gens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Et il plantera les tentes de son palais entre la mer et la montagne de sainte beauté; et il viendra à sa fin, et il n’y aura personne pour le secourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Et en ce temps-là se lèvera Micaël, le grand chef, qui tient pour les fils de ton peuple; et ce sera un temps de détresse tel, qu’il n’y en a pas eu depuis qu’il existe une nation jusqu’à ce temps-là. Et en ce temps-là ton peuple sera délivré: quiconque sera trouvé écrit dans le livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Et plusieurs qui dorment dans la poussière de la terre se réveilleront, les uns pour la vie éternelle, et les autres pour l’opprobre, pour être un objet d’horreur éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Et les sages brilleront comme la splendeur de l’étendue, et ceux qui ont enseigné la justice à la multitude, comme les étoiles, à toujours et à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Et toi, Daniel, cache les paroles et scelle le livre jusqu’au temps de la fin. Plusieurs courront çà et là; et la connaissance sera augmentée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Et moi, Daniel, je regardai; et voici deux autres [personnages] qui se tenaient, l’un deçà, sur le bord du fleuve, et l’autre delà, sur le bord du fleuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Et il dit à l’homme vêtu de lin qui était au-dessus des eaux du fleuve: Jusques à quand la fin de ces merveilles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Et j’entendis l’homme vêtu de lin qui était au-dessus des eaux du fleuve; et il leva sa main droite et sa main gauche vers les cieux, et jura par celui qui vit éternellement que ce serait pour un temps déterminé, et des temps déterminés, et une moitié [de temps]; et lorsqu’il aura achevé de briser la force du peuple saint, toutes ces choses seront achevées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Et moi, j’entendis, mais je ne compris pas. Et je dis: Mon seigneur, quelle sera l’issue de ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Et il dit: Va, Daniel; car ces paroles sont cachées et scellées jusqu’au temps de la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Plusieurs seront purifiés et blanchis et affinés; et les méchants agiront méchamment, et aucun des méchants ne comprendra; mais les sages comprendront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Et depuis le temps où le [sacrifice] continuel sera ôté et où l’abomination qui désole sera placée, [il y aura] 1 290 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Bienheureux celui qui attend et qui parvient à 1 335 jours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Et toi, va jusqu’à la fin; et tu te reposeras, et tu te tiendras dans ton lot, à la fin des jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'La parole de l’ Éternel qui vint à Osée, fils de Beéri, aux jours d’Ozias, de Jotham, d’Achaz, et d’Ézéchias, rois de Juda, et aux jours de Jéroboam, fils de Joas, roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Commencement de la parole de l’ Éternel par Osée. Et l’ Éternel dit à Osée: Va, prends-toi une femme prostituée et des enfants de prostitution; car le pays s’est entièrement prostitué en abandonnant l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Et il s’en alla et prit Gomer, fille de Diblaïm; et elle conçut, et lui enfanta un fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Et l’ Éternel lui dit: Appelle son nom Jizreël, car encore un peu de temps, et je visiterai le sang de Jizreël sur la maison de Jéhu, et je ferai cesser le royaume de la maison d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'et il arrivera, en ce jour-là, que je briserai l’arc d’Israël dans la vallée de Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Et elle conçut encore, et enfanta une fille; et il lui dit: Appelle son nom Lo-Rukhama, car je ne ferai plus miséricorde à la maison d’Israël, pour leur pardonner encore;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'mais je ferai miséricorde à la maison de Juda, et je les sauverai par l’ Éternel leur Dieu; et je ne les sauverai pas par l’arc, ni par l’épée, ni par la guerre, [ni] par des chevaux, ni par des cavaliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Et elle sevra Lo-Rukhama. Et elle conçut, et enfanta un fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Et il dit: Appelle son nom Lo-Ammi, car vous n’êtes pas mon peuple, et je ne serai pas à vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Cependant le nombre des fils d’Israël sera comme le sable de la mer, qui ne peut se mesurer ni nombrer; et il arrivera que, dans le lieu où il leur a été dit: Vous n’êtes pas mon peuple, il leur sera dit: Fils du ✶Dieu vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Et les fils de Juda et les fils d’Israël se rassembleront, et s’établiront un chef, et monteront du pays; car la journée de Jizreël est grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, '*Dites à vos frères: Ammi! et à vos sœurs: Rukhama!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Plaidez contre votre mère, plaidez! car elle n’est pas ma femme et je ne suis pas son mari; et qu’elle ôte ses prostitutions de devant sa face, et ses adultères d’entre ses seins,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'de peur que je ne la dépouille à nu, et que je ne la place là comme au jour de sa naissance, et que je n’en fasse comme un désert, et que je ne la rende comme une terre aride, et ne la tue de soif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Et je ne ferai pas miséricorde à ses enfants, car ce sont des enfants de prostitution;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'car leur mère s’est prostituée, celle qui les a conçus s’est déshonorée; car elle a dit: J’irai après mes amants qui m’ont donné mon pain et mon eau, ma laine et mon lin, mon huile et ma boisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'C’est pourquoi, voici, je vais fermer ton chemin avec des épines, et j’élèverai une clôture; et elle ne trouvera pas ses sentiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Et elle courra après ses amants, et ne les atteindra pas; et elle les cherchera, et ne les trouvera pas. Et elle dira: J’irai et je m’en retournerai à mon premier mari; car alors j’étais mieux que maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Et elle ne sait pas que c’est moi qui lui ai donné le blé, et le moût, et l’huile. Je lui ai multiplié aussi l’argent et l’or: – ils l’ont employé pour Baal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'C’est pourquoi je reprendrai mon blé en son temps, et mon moût en sa saison; et j’ôterai ma laine et mon lin, qui devaient couvrir sa nudité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Et maintenant je découvrirai sa honte aux yeux de ses amants, et personne ne la délivrera de ma main;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'et je ferai cesser toutes ses délices, sa fête, sa nouvelle lune, et son sabbat, et toutes ses assemblées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'et je détruirai sa vigne et son figuier, dont elle disait: Ce sont là mes présents que mes amants m’ont donnés; et j’en ferai une forêt, et les bêtes des champs les dévoreront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Et je visiterai sur elle les jours des Baals, où elle leur brûlait de l’encens, et se parait de son anneau de nez et de ses colliers, et allait après ses amants, et m’a oublié, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'C’est pourquoi, voici, moi, je l’attirerai, et je la mènerai au désert, et je lui parlerai au cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'et de là je lui donnerai ses vignes, et la vallée d’Acor pour une porte d’espérance; et là elle chantera comme dans les jours de sa jeunesse et comme au jour où elle monta du pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Et il arrivera, en ce jour-là, dit l’ Éternel, que tu m’appelleras: Mon mari, et tu ne m’appelleras plus: Mon maître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Et j’ôterai de sa bouche les noms des Baals, et on ne se souviendra plus de leur nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Et je ferai pour eux, en ce jour-là, une alliance avec les bêtes des champs, et avec les oiseaux des cieux, et avec les reptiles du sol; et j’ôterai du pays, en les brisant, l’arc et l’épée et la guerre; et je les ferai reposer en sécurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Et je te fiancerai à moi pour toujours; et je te fiancerai à moi en justice, et en jugement, et en bonté, et en miséricorde;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'et je te fiancerai à moi en vérité; et tu connaîtras l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Et il arrivera, en ce jour-là, que j’exaucerai, dit l’ Éternel, j’exaucerai les cieux, et eux exauceront la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 24, 'et la terre exaucera le froment et le moût et l’huile, et eux exauceront Jizreël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 25, 'Et je la sèmerai pour moi dans le pays, et je ferai miséricorde à Lo-Rukhama, et je dirai à Lo-Ammi: Tu es mon peuple, et il me dira: Mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Et l’ Éternel me dit: Va encore, aime une femme aimée d’un ami, et adultère, selon l’amour de l’ Éternel pour les fils d’Israël, tandis qu’eux se tournent vers d’autres dieux et aiment les gâteaux de raisins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Et je me l’achetai pour 15 [pièces] d’argent, et un khomer d’orge et un léthec d’orge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Et je lui dis: Durant beaucoup de jours tu m’attendras, tu ne te prostitueras pas, et tu ne seras à [aucun] homme; et moi [je ferai] de même à ton égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Car les fils d’Israël resteront beaucoup de jours sans roi, et sans prince, et sans sacrifice, et sans statue, et sans éphod ni théraphim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Ensuite, les fils d’Israël retourneront et rechercheront l’ Éternel, leur Dieu, et David, leur roi, et se tourneront avec crainte vers l’ Éternel et vers sa bonté, à la fin des jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, '*Écoutez la parole de l’ Éternel, fils d’Israël, car l’ Éternel a un débat avec les habitants du pays; car il n’y a pas de vérité, et il n’y a pas de bonté, et il n’y a pas de connaissance de Dieu dans le pays:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'exécration, et mensonge, et meurtre, et vol, et adultère; la violence déborde, et le sang touche le sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'C’est pourquoi le pays sera dans le deuil; et tous ceux qui y habitent seront languissants, avec les bêtes des champs, et avec les oiseaux des cieux; et même les poissons de la mer seront ôtés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Toutefois que nul ne conteste, que nul ne reprenne; or ton peuple est comme ceux qui contestent avec le sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Et tu broncheras de jour, et le prophète aussi avec toi bronchera de nuit: et je détruirai ta mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mon peuple est détruit, faute de connaissance; car toi, tu as rejeté la connaissance, et je te rejetterai afin que tu n’exerces plus la sacrificature devant moi. Car tu as oublié la loi de ton Dieu, et moi j’oublierai tes fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Selon qu’ils se sont accrus, ainsi ils ont péché contre moi. Je changerai leur gloire en ignominie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Ils mangent le péché de mon peuple, et leur âme désire son iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Et comme le peuple, ainsi sera le sacrificateur. Et je visiterai sur eux leurs voies, et je leur rendrai leurs actions;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'et ils mangeront et ne seront pas rassasiés; ils se prostitueront, mais ne s’étendront pas, car ils ont cessé de prendre garde à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'La fornication, et le vin, et le moût, ôtent le sens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mon peuple interroge son bois, et son bâton est son oracle, car l’esprit de fornication égare; et il se prostitue, se soustrayant à son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Ils offrent des sacrifices sur les sommets des montagnes, et font fumer de l’encens sur les collines, sous le chêne et le peuplier et le térébinthe, parce que leur ombre est bonne. C’est pourquoi vos filles se prostituent et vos belles-filles commettent l’adultère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Je ne punirai pas vos filles pour s’être prostituées, ni vos belles-filles pour avoir commis l’adultère; car ils se sont séparés eux-mêmes avec les prostituées, et sacrifient avec des femmes consacrées à la prostitution; et le peuple qui n’a pas d’intelligence court à sa perte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Si tu te prostitues, ô Israël, que Juda ne se rende pas coupable! N’allez pas à Guilgal, et ne montez pas à Beth-Aven, et ne jurez pas: L’ Éternel est vivant!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Car Israël est revêche comme une génisse rétive. Maintenant l’ Éternel les paîtra comme un agneau dans un lieu spacieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Éphraïm s’est attaché aux idoles: laisse-le faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Leurs orgies se sont avilies; ils se livrent à la fornication; leurs chefs ont ardemment aimé l’ignominie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Le vent a enserré [Éphraïm] dans ses ailes, et ils sont honteux à cause de leurs sacrifices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, '*Écoutez ceci, sacrificateurs; et sois attentive, maison d’Israël, et prête l’oreille, maison du roi, car c’est contre vous qu’est le jugement; car vous avez été un piège à Mitspa, et un filet étendu sur le Thabor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Ils se sont enfoncés dans la corruption de l’apostasie, et moi, je les châtierai tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Je connais Éphraïm, et Israël ne m’est point caché; car maintenant, Éphraïm, tu as commis la fornication; Israël s’est souillé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Leurs méfaits ne leur permettent pas de retourner à leur Dieu; car l’esprit de fornication est au milieu d’eux et ils ne connaissent pas l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Et l’orgueil d’Israël témoigne en face contre lui; et Israël et Éphraïm tomberont par leur iniquité; Juda aussi tombera avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Avec leurs brebis et avec leurs bœufs, ils iront pour chercher l’ Éternel, mais ils ne le trouveront pas: il s’est retiré d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Ils ont agi perfidement envers l’ Éternel, car ils ont engendré des fils étrangers: maintenant, un mois les dévorera avec leurs biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Sonnez du cor en Guibha, de la trompette à Rama. Criez dans Beth-Aven: Derrière toi, Benjamin!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Éphraïm sera une désolation au jour du châtiment: je fais savoir parmi les tribus d’Israël une chose certaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Les princes de Juda sont comme ceux qui reculent les bornes: je répandrai sur eux ma fureur comme de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Éphraïm est opprimé, brisé par le jugement, parce que, selon sa propre volonté, il est allé après le commandement [de l’homme];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'et moi, je serai comme une teigne pour Éphraïm, et comme de la vermoulure pour la maison de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Et Éphraïm a vu sa maladie, et Juda, sa plaie; et Éphraïm s’en est allé en Assyrie et a envoyé vers le roi Jareb; mais lui n’a pu vous guérir, et ne vous a pas ôté votre plaie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Car je serai comme un lion à Éphraïm, et comme un jeune lion à la maison de Juda: moi, moi, je déchirerai, et je m’en irai; j’emporterai, et il n’y aura personne qui délivre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Je m’en irai, je retournerai en mon lieu, jusqu’à ce qu’ils se reconnaissent coupables et recherchent ma face. Dans leur détresse, ils me chercheront dès le matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Venez, retournons à l’ Éternel, car lui a déchiré, et il nous guérira; il a frappé, et il bandera nos plaies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Dans deux jours, il nous fera vivre; au troisième jour, il nous mettra debout, et nous vivrons devant sa face,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'et nous connaîtrons [et] nous nous attacherons à connaître l’ Éternel. Sa sortie est préparée comme l’aube du jour; et il viendra à nous comme la pluie, comme la pluie de la dernière saison arrose la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, '*Que te ferai-je, Éphraïm? Que te ferai-je, Juda? Votre piété est comme la nuée du matin et comme la rosée qui s’en va de bonne heure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'C’est pourquoi je les ai hachés par les prophètes, je les ai tués par les paroles de ma bouche... Et mon jugement sort comme la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Car j’ai aimé la bonté, et non le sacrifice, et la connaissance de Dieu plus que les holocaustes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'mais eux, comme Adam, ont transgressé [l’]alliance; là ils ont agi perfidement envers moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Galaad est une ville d’ouvriers d’iniquité, couverte de traces de sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Et comme les troupes [de voleurs] guettent un homme, la bande des sacrificateurs assassine sur le chemin de Sichem; car ils commettent des infamies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'J’ai vu des choses horribles dans la maison d’Israël: là est la prostitution d’Éphraïm! Israël s’est souillé!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Pour toi aussi, Juda, une moisson t’est assignée, quand je rétablirai les captifs de mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Quand j’ai voulu guérir Israël, l’iniquité d’Éphraïm s’est découverte, et les méchancetés de Samarie; car ils ont pratiqué la fausseté, et le voleur entre, [et] la troupe des brigands assaille dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Et ils ne se sont pas dit dans leur cœur que je me souviens de toute leur méchanceté. Maintenant leurs méfaits les environnent, ils sont devant ma face.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Ils réjouissent le roi par leur méchanceté, et les princes par leurs mensonges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Tous, ils commettent l’adultère, comme un four allumé par le boulanger, qui cesse de l’attiser depuis qu’il s’est mis à pétrir la pâte jusqu’à ce qu’elle ait levé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Au jour de notre roi, les princes se sont rendus malades par l’ardeur du vin; il a tendu sa main aux moqueurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Car ils ont appliqué leur cœur comme un four à leurs embûches: toute la nuit, leur boulanger dort; le matin, il brûle comme un feu de flammes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Ils sont tous ardents comme un four, et ils dévorent leurs juges: tous leurs rois sont tombés; nul d’entre eux ne m’invoque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Éphraïm s’est mêlé avec les peuples; Éphraïm est un gâteau qu’on n’a pas retourné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Des étrangers ont consumé sa force, et il ne le sait pas. Des cheveux gris sont aussi parsemés sur lui, et il ne le sait pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Et l’orgueil d’Israël témoigne en face contre lui, et ils ne se tournent pas vers l’ Éternel, leur Dieu, et ils ne le recherchent pas malgré tout cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Éphraïm est devenu comme une colombe niaise, sans intelligence; ils appellent l’Égypte, ils vont vers l’Assyrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Dès qu’ils iront, j’étendrai sur eux mon filet, je les ferai descendre comme les oiseaux des cieux. Je les châtierai selon que leur assemblée l’a entendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Malheur à eux, car ils se sont enfuis loin de moi! Ruine sur eux, car ils se sont rebellés contre moi! Et moi, je voulais les racheter, mais ils disent des mensonges contre moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'et ils n’ont pas crié à moi dans leur cœur, quand ils ont hurlé sur leurs lits. Ils se rassemblent pour du froment et du moût; ils se sont retirés de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Et moi, j’ai châtié; j’ai fortifié leurs bras: et ils ont médité le mal contre moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'ils retournent, [mais] non au [Très]-Haut; ils sont comme un arc trompeur. Leurs princes tomberont par l’épée, à cause de l’insolence de leur langue: cela fera d’eux un objet de risée dans le pays d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, '*Embouche la trompette! Comme l’aigle, [il fond] sur la maison de l’ Éternel, parce qu’ils ont transgressé mon alliance et ont été rebelles à ma loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Ils me crieront: Mon Dieu, nous te connaissons, [nous], Israël!...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israël a rejeté le bien, l’ennemi le poursuivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Ils ont fait des rois, mais non de par moi; ils ont fait des princes, et je ne le savais pas. De leur argent et de leur or ils se sont fait des idoles, afin qu’ils soient retranchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Ton veau t’a rejetée, Samarie! Ma colère s’est enflammée contre eux. Jusques à quand seront-ils incapables d’innocence?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Car il est d’Israël, celui-là aussi: un ouvrier l’a fait; il n’est pas Dieu; car le veau de Samarie sera [mis en] pièces!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Car ils ont semé le vent, et ils moissonneront le tourbillon. Il n’a pas une tige de blé; elle germerait, qu’elle ne produirait pas de farine; et en produirait-elle, des étrangers la dévoreraient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Israël est dévoré; maintenant, ils seront parmi les nations comme un vase auquel on ne prend pas plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Car ils sont montés vers l’Assyrien: un âne sauvage se tient isolé. Éphraïm a fait des présents à des amants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Quand même ils ont fait des présents parmi les nations, maintenant je les assemblerai, et ils commenceront à être amoindris sous le fardeau du roi des princes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Car Éphraïm a multiplié les autels pour pécher, [et] les autels seront son péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'J’ai écrit pour lui les grandes choses de ma loi; elles sont estimées comme une chose étrange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Pour sacrifice de mes offrandes, ils offrent de la chair, et ils la mangent; l’ Éternel ne les a pas pour agréables. Maintenant, il se souviendra de leur iniquité et visitera leurs péchés. Ils retourneront en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Mais Israël a oublié celui qui l’a fait; et il bâtit des palais, et Juda multiplie les villes fortes; mais j’enverrai un feu dans leurs villes, et il dévorera leurs palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Ne te réjouis pas, Israël, jusqu’à l’exultation, comme les peuples; car tu t’es prostitué, abandonnant ton Dieu. Tu as aimé les présents dans toutes les aires à froment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'L’aire et la cuve ne les nourriront pas, et le moût les trompera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Ils ne demeureront pas dans le pays de l’ Éternel; mais Éphraïm retournera en Égypte, et mangera en Assyrie ce qui est impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Ils ne feront pas de libations de vin à l’ Éternel, et leurs sacrifices ne lui seront pas agréables: ce sera pour eux comme le pain de deuil; tous ceux qui en mangeront se souilleront; car leur pain est pour eux-mêmes; il n’entrera pas dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Que ferez-vous au jour de l’assemblée, et au jour de fête de l’ Éternel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Car voici, ils s’en sont allés à cause de la dévastation: l’Égypte les rassemblera, Moph les enterrera. Ce qu’ils ont de précieux [en objets] d’argent, l’ortie les héritera; le chardon est dans leurs tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Ils arrivent, les jours de la visitation; ils arrivent, les jours de la récompense! Israël le saura. Le prophète est insensé, l’homme inspiré est fou, à cause de la grandeur de ton iniquité et de la grandeur de ton hostilité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Éphraïm est aux aguets, [regardant à d’autres] à côté de mon Dieu. Le prophète est un piège d’oiseleur sur tous ses chemins, une hostilité dans la maison de son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Ils se sont enfoncés dans la corruption comme aux jours de Guibha. Il se souviendra de leur iniquité, il visitera leurs péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'J’ai trouvé Israël comme des raisins dans le désert; j’ai vu vos pères au commencement comme le premier fruit du figuier. Ils sont allés à Baal-Péor, et ils se sont voués à cette honteuse [idole], et sont devenus abominables comme leur amant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Quant à Éphraïm, leur gloire s’envolera comme un oiseau;... point d’enfantement, point de grossesse, point de conception!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Quand même ils élèveraient leurs fils, je les priverais de fils, en sorte qu’il n’y ait pas d’homme. Car aussi, malheur à eux, lorsque je me serai retiré d’eux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Éphraïm, comme je l’ai vu, a été une Tyr plantée dans une campagne agréable; mais Éphraïm doit mener dehors ses fils au meurtrier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Donne-leur, Éternel! Que donneras-tu? Donne-leur un sein qui avorte et des mamelles desséchées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Toute leur méchanceté est à Guilgal, car là, je les ai haïs; à cause de la méchanceté de leurs actions, je les chasserai de ma maison. Je ne les aimerai plus. Tous leurs princes sont des rebelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Éphraïm a été frappé: leur racine a séché, ils ne produiront pas de fruit. Si même ils enfantent, je ferai mourir le fruit précieux de leur sein.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mon Dieu les a rejetés, car ils ne l’ont pas écouté, et ils seront errants parmi les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israël est une vigne branchue; il porte du fruit pour lui-même. Selon l’abondance de son fruit, il a multiplié les autels; selon la beauté de son pays, il a rendu belles ses statues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Leur cœur est flatteur; maintenant ils seront tenus pour coupables. Il abattra leurs autels, il détruira leurs statues;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'car maintenant ils diront: Nous n’avons pas de roi, car nous n’avons pas craint l’ Éternel; et un roi, que ferait-il pour nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Ils prononcent des paroles, ils jurent faussement, [et] ils concluent une alliance; aussi le jugement poussera comme une plante vénéneuse dans les sillons des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'L’habitant de Samarie a peur pour le veau de Beth-Aven; car son peuple mènera deuil sur lui, et ses Camarim trembleront à cause de lui, pour sa gloire, car elle a été transportée d’auprès de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'on le porte à l’Assyrie, comme présent au roi Jareb. Éphraïm est saisi de honte, et Israël aura honte de son conseil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Samarie [est détruite], son roi a péri, comme un fétu sur la face des eaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'et les hauts lieux d’Aven, le péché d’Israël, seront détruits. L’épine et la ronce monteront sur leurs autels; et ils diront aux montagnes: Couvrez-nous! et aux collines: Tombez sur nous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Dès les jours de Guibha, tu as péché, Israël: là ils sont restés; la guerre contre les fils d’iniquité ne les atteignit pas à Guibha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Selon mon bon plaisir, je les châtierai; et les peuples seront rassemblés contre eux, quand ils seront liés pour leurs deux iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Et Éphraïm est une génisse dressée, qui aime à fouler le blé; et j’ai passé sur son beau cou: je ferai tirer le chariot à Éphraïm; Juda labourera, et Jacob hersera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Semez pour vous en justice, moissonnez selon la piété. Défrichez pour vous un terrain neuf; [c’est] le temps pour chercher l’ Éternel, jusqu’à ce qu’il vienne et qu’il fasse pleuvoir sur vous la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Vous avez labouré la méchanceté, moissonné l’iniquité, mangé le fruit du mensonge; car tu as eu confiance en ta voie, en la multitude de tes hommes forts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Et un tumulte s’élèvera parmi tes peuples, et toutes tes forteresses seront détruites, comme Shalman détruisit Beth-Arbel, au jour de la guerre: la mère fut écrasée avec les fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Béthel vous fera de même, à cause de la méchanceté de votre méchanceté: à l’aube du jour, le roi d’Israël aura entièrement cessé d’être.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, '*Quand Israël était jeune, je l’ai aimé, et j’ai appelé mon fils hors d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, '[Les prophètes] les appelaient, et chaque fois ils s’en allaient d’auprès d’eux: ils sacrifiaient aux Baals et brûlaient de l’encens aux images taillées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Et moi, j’ai enseigné à Éphraïm à marcher, – Il les a pris sur ses bras, – mais ils ne savaient pas que je les guérissais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Je les tirais avec des cordes d’homme, avec des liens d’amour, et j’étais pour eux comme ceux qui ôteraient le joug de dessus leurs mâchoires et leur donneraient doucement à manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Il ne retournera pas dans le pays d’Égypte, mais l’Assyrien sera son roi; car ils ont refusé de revenir [à moi];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'et l’épée fera le tour de leurs villes, détruira leurs barres, et les dévorera, à cause de leurs desseins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Et mon peuple tient à se détourner de moi; on les appelle vers le [Très]-Haut: pas un d’eux ne l’exalte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Que ferai-je de toi, Éphraïm? Comment te livrerais-je, Israël? Comment ferais-je de toi comme d’Adma, te rendrais-je tel que Tseboïm? Mon cœur est changé en moi; toutes ensemble, mes compassions se sont émues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Je ne donnerai pas cours à l’ardeur de ma colère, je ne détruirai pas de nouveau Éphraïm; car je suis ✶Dieu, et non pas un homme, – le Saint, au milieu de toi; et je ne viendrai pas avec colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Ils marcheront après l’ Éternel. Il rugira comme un lion; car il rugira, et les fils accourront en émoi de l’occident,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'ils accourront en émoi de l’Égypte comme un oiseau, et, comme une colombe, du pays d’Assyrie; et je les ferai habiter dans leurs maisons, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Éphraïm m’entoure de mensonge, et la maison d’Israël de fraude; mais Juda marche encore avec ✶Dieu, et avec les vrais saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Éphraïm se repaît de vent, et poursuit le vent d’orient; tout le jour il multiplie le mensonge et la dévastation; et ils font alliance avec l’Assyrie, et portent de l’huile en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'L’ Éternel a aussi un débat avec Juda, et il punira Jacob selon ses voies, et il lui rendra selon ses actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Dans le ventre il prit son frère par le talon, et par sa force il lutta avec Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'oui, il lutta avec l’Ange et prévalut: il pleura et le supplia. À Béthel, il le trouva; et là, il parla avec nous:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'et l’ Éternel, le Dieu des armées, – l’ Éternel, est son mémorial.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Et toi, retourne à ton Dieu, garde la piété et le jugement, et attends-toi à ton Dieu continuellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'C’est un marchand; la fausse balance est dans sa main; il aime à extorquer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Et Éphraïm dit: Toutefois je me suis enrichi, je me suis procuré des biens. Dans tout mon travail on n’a trouvé contre moi aucune iniquité qui soit péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Et moi, l’ Éternel ton Dieu dès le pays d’Égypte, je te ferai encore habiter sous des tentes, comme aux jours de la fête solennelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Et j’ai parlé aux prophètes; et moi, j’ai multiplié les visions, et, par les prophètes, j’ai parlé en similitudes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Si Galaad est vanité, eux, ils ne seront que néant. À Guilgal, ils ont sacrifié des bœufs; leurs autels aussi seront comme des tas de pierres dans les sillons des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Et Jacob s’enfuit dans la plaine de Syrie; et Israël servit pour une femme; et pour une femme, il garda [les troupeaux].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Et, par un prophète, l’ Éternel fit monter Israël d’Égypte, et par un prophète il fut gardé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 15, 'Éphraïm a amèrement provoqué la colère: son Seigneur laissera sur lui son sang, et lui rendra ses mépris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Quand Éphraïm parlait, c’était une terreur; il s’éleva en Israël: mais il se rendit coupable par Baal, et mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Et maintenant ils continuent de pécher et se sont fait avec leur argent des images de fonte, des idoles selon leurs pensées, toutes un travail d’artisans, desquelles ils disent: Que les hommes qui sacrifient embrassent les veaux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'C’est pourquoi ils seront comme la nuée du matin et comme la rosée qui s’en va de bonne heure, comme la balle chassée par le tourbillon hors de l’aire, et comme la fumée qui sort par le treillis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Et moi, je suis l’ Éternel, ton Dieu, dès le pays d’Égypte; et tu n’as pas connu d’[autre] Dieu que moi, et il n’y a pas de sauveur hors moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Moi, je t’ai connu dans le désert, dans une terre aride.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Selon qu’étaient leurs pâturages, ils furent rassasiés; ils furent rassasiés, et leur cœur s’éleva; c’est pourquoi ils m’ont oublié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Et je leur serai comme un lion; comme un léopard, je les guetterai sur le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Je les attaquerai comme une ourse privée de ses petits; je déchirerai l’enveloppe de leur cœur, et je les dévorerai là, comme une lionne; les bêtes des champs les dépèceront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'C’est ta destruction, Israël, que tu aies été contre moi, contre ton secours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Où donc est ton roi? pour qu’il te sauve dans toutes tes villes. Où sont tes juges, dont tu as dit: Donne-moi un roi et des princes?...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Je t’ai donné un roi dans ma colère, et je l’ai ôté dans ma fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'L’iniquité d’Éphraïm est liée ensemble; son péché est tenu en réserve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Les douleurs de celle qui enfante viendront sur lui. C’est un fils qui n’est pas sensé, car au temps de la sortie des enfants, il ne se tint pas là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Je les délivrerai de la main du shéol, je les rachèterai de la mort. Ô mort, où sont tes pestes? Ô shéol, où est ta destruction? Le repentir est caché à mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Car il a porté du fruit parmi [ses] frères: un vent d’orient viendra, le vent de l’ Éternel qui monte du désert, et il desséchera ses sources et fera tarir ses fontaines. Il pillera le trésor de tous les objets d’agrément.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Samarie portera son iniquité, car elle s’est révoltée contre son Dieu; ils tomberont par l’épée, leurs petits enfants seront écrasés, et on fendra le ventre à leurs femmes enceintes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, '*Israël, reviens à l’ Éternel, ton Dieu, car tu es tombé par ton iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Prenez avec vous des paroles, et revenez à l’ Éternel; dites-lui: Pardonne toute iniquité, et accepte ce qui est bon, et nous [te] rendrons les sacrifices de nos lèvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'L’Assyrie ne nous sauvera pas; nous ne monterons pas sur des chevaux, et nous ne dirons plus: Notre Dieu, à l’œuvre de nos mains; car, auprès de toi, l’orphelin trouve la miséricorde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Je guérirai leur abandon [de moi], je les aimerai librement, car ma colère s’est détournée d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Je serai pour Israël comme la rosée; il fleurira comme le lis, et il poussera ses racines comme le Liban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Ses rejetons s’étendront, et sa magnificence sera comme l’olivier, et son parfum, comme le Liban:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'ils reviendront s’asseoir sous son ombre, ils feront vivre le froment, et ils fleuriront comme une vigne; leur renommée sera comme le vin du Liban.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Éphraïm [dira]: Qu’ai-je plus à faire avec les idoles? – Moi, je lui répondrai et je le regarderai. – Moi, je suis comme un cyprès vert. – De moi provient ton fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 10, 'Qui est sage? il comprendra ces choses; et intelligent? il les connaîtra; car les voies de l’ Éternel sont droites, et les justes y marcheront, mais les transgresseurs y tomberont.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'La parole de l’ Éternel, qui vint à Joël, fils de Pethuel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Écoutez ceci, vieillards, et prêtez l’oreille, vous, tous les habitants du pays! Ceci est-il arrivé de vos jours, ou même dans les jours de vos pères?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Racontez-le à vos fils, et vos fils à leurs fils, et leurs fils à une autre génération:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'ce qu’a laissé la chenille, la sauterelle l’a mangé; et ce qu’a laissé la sauterelle, l’yélek l’a mangé, et ce qu’a laissé l’yélek, la locuste l’a mangé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Réveillez-vous, ivrognes, et pleurez; et hurlez, vous tous, buveurs de vin, à cause du moût, car il est retranché à vos bouches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Car une nation est montée sur mon pays, forte et innombrable. Ses dents sont les dents d’un lion, et elle a les grosses dents d’une lionne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Elle a réduit ma vigne en une désolation, mon figuier en un tas de bois; elle l’a écorcé entièrement, et l’a jeté par terre; ses rameaux ont blanchi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Gémis comme une vierge ceinte du sac, sur le mari de sa jeunesse!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'L’offrande et la libation sont retranchées de la maison de l’ Éternel; les sacrificateurs, les serviteurs de l’ Éternel, mènent deuil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'les champs sont ravagés, la terre mène deuil; car le blé est ravagé, le vin nouveau est honteux, l’huile languit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Soyez honteux, laboureurs; hurlez, vignerons, – à cause du froment et de l’orge, car la moisson des champs a péri!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'La vigne est honteuse, et le figuier languit, – le grenadier, le palmier aussi, et le pommier; tous les arbres des champs sont desséchés; car la joie est tarie du milieu des fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Ceignez-vous et lamentez-vous, sacrificateurs; hurlez, vous qui servez l’autel; venez, passez la nuit sous le sac, vous qui servez mon Dieu! car l’offrande et la libation sont ôtées à la maison de votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Sanctifiez un jeûne, convoquez une assemblée solennelle; assemblez les anciens, tous les habitants du pays, à la maison de l’ Éternel, votre Dieu, et criez à l’ Éternel!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Hélas, quel jour! car le jour de l’ Éternel est proche, et il viendra comme une destruction du Tout-puissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'La nourriture n’est-elle pas retranchée de devant nos yeux, [et], de la maison de notre Dieu, la joie et l’allégresse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Les semences pourrissent sous leurs mottes; les greniers sont désolés; les granges sont renversées, car le blé est desséché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Comme le bétail gémit! Les troupeaux de gros bétail sont déconcertés, car il n’y a pas de pâturage pour eux; les troupeaux de menu bétail aussi sont en peine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'À toi, Éternel, je crierai; car le feu a dévoré les pâturages du désert, et la flamme a brûlé tous les arbres des champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Les bêtes des champs aussi crient à toi, car les cours d’eau sont desséchés, et le feu a dévoré les pâturages du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, '*Sonnez de la trompette en Sion, sonnez avec éclat dans ma sainte montagne! Que tous les habitants du pays tremblent, car le jour de l’ Éternel vient; car il est proche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'un jour de ténèbres et d’obscurité, un jour de nuées et d’épaisses ténèbres: c’est comme l’aube qui s’étend sur les montagnes, – un peuple nombreux et fort, tel qu’il n’y en eut jamais, et qu’après lui, il n’y en aura point jusqu’aux années des générations et des générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Devant lui un feu dévore, et une flamme brûle après lui; devant lui le pays est comme le jardin d’Éden, et après lui, la solitude d’un désert; et rien ne lui échappe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Leur aspect est comme l’aspect des chevaux, et ils courent comme des cavaliers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Ils sautent:... c’est comme le bruit des chars sur les sommets des montagnes, comme le bruit d’une flamme de feu qui dévore le chaume, comme un peuple puissant rangé en bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Les peuples en sont angoissés, tous les visages pâlissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Ils courent comme des hommes forts, ils escaladent la muraille comme des hommes de guerre; ils marchent chacun dans son chemin, et ne changent pas leurs sentiers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'et ils ne se pressent pas l’un l’autre. Ils marchent chacun dans sa route; ils se précipitent à travers les traits et ne sont pas blessés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'ils se répandent par la ville, ils courent sur la muraille, ils montent dans les maisons, ils entrent par les fenêtres comme un voleur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Devant eux la terre tremble, les cieux sont ébranlés, le soleil et la lune sont obscurcis, et les étoiles retirent leur splendeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Et l’ Éternel fait entendre sa voix devant son armée, car son camp est très grand, car l’exécuteur de sa parole est puissant; parce que le jour de l’ Éternel est grand et fort terrible; et qui peut le supporter?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Ainsi, encore maintenant, dit l’ Éternel, revenez à moi de tout votre cœur, avec jeûne, et avec pleurs, et avec deuil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'et déchirez vos cœurs et non vos vêtements, et revenez à l’ Éternel, votre Dieu; car il est plein de grâce et miséricordieux, lent à la colère et grand en bonté, et il se repent du mal [dont il a menacé].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Qui sait? il reviendra et se repentira et laissera après lui une bénédiction, une offrande et une libation à l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Sonnez de la trompette en Sion, sanctifiez un jeûne, convoquez une assemblée solennelle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'assemblez le peuple, sanctifiez la congrégation, réunissez les anciens, assemblez les enfants et ceux qui tètent les mamelles; que l’époux sorte de sa chambre, et l’épouse de sa chambre nuptiale;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'que les sacrificateurs, les serviteurs de l’ Éternel, pleurent entre le portique et l’autel, et qu’ils disent: Épargne ton peuple, ô Éternel, et ne livre pas ton héritage à l’opprobre, en sorte qu’ils soient le proverbe des nations. Pourquoi dirait-on parmi les peuples: Où est leur Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Alors l’ Éternel sera jaloux pour son pays, et aura pitié de son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Et l’ Éternel répondra et dira à son peuple: Voici, je vous envoie le blé, et le moût, et l’huile, et vous en serez rassasiés; et je ne vous livrerai plus à l’opprobre parmi les nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'et j’éloignerai de vous celui qui vient du nord, et je le chasserai dans un pays aride et désolé, sa face vers la mer orientale, et son arrière-garde vers la mer d’occident; et sa puanteur montera, et son infection montera, parce qu’il s’est élevé pour faire de grandes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Ne crains pas, terre; égaie-toi et réjouis-toi; car l’ Éternel fait de grandes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Ne craignez pas, bêtes des champs, car les pâturages du désert verdissent, car l’arbre porte son fruit, le figuier et la vigne donnent leur force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Et vous, fils de Sion, égayez-vous et réjouissez-vous en l’ Éternel, votre Dieu; car il vous donne la première pluie dans sa mesure, et fait descendre sur vous la première pluie et la dernière pluie, au commencement [de la saison].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Et les aires seront pleines de blé, et les cuves regorgeront de moût et d’huile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'et je vous rendrai les années qu’a mangées la sauterelle, l’yélek, et la locuste, et la chenille, ma grande armée que j’ai envoyée au milieu de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Et vous mangerez abondamment et serez rassasiés, et vous louerez le nom de l’ Éternel, votre Dieu, qui a fait des choses merveilleuses pour vous; et mon peuple ne sera jamais honteux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Et vous saurez que je suis au milieu d’Israël, et que moi, l’ Éternel, je suis votre Dieu, et qu’il n’y en a point d’autre; et mon peuple ne sera jamais honteux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, '*Et il arrivera, après cela, que je répandrai mon Esprit sur toute chair, et vos fils et vos filles prophétiseront, vos vieillards songeront des songes, vos jeunes hommes verront des visions;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'et aussi sur les serviteurs et sur les servantes, en ces jours-là, je répandrai mon Esprit. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Et je montrerai des signes dans les cieux et sur la terre, du sang, et du feu, et des colonnes de fumée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'le soleil sera changé en ténèbres, et la lune en sang, avant que vienne le grand et terrible jour de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Et il arrivera que, quiconque invoquera le nom de l’ Éternel sera sauvé. Car sur la montagne de Sion il y aura délivrance, et à Jérusalem, comme l’ Éternel l’a dit, et pour les réchappés que l’ Éternel appellera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 1, '*Car voici, en ces jours-là et en ce temps-là où je rétablirai les captifs de Juda et de Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 2, 'je rassemblerai toutes les nations, et je les ferai descendre dans la vallée de Josaphat, et là j’entrerai en jugement avec elles au sujet de mon peuple et de mon héritage, Israël, qu’elles ont dispersé parmi les nations; et elles ont partagé mon pays,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 3, 'et elles ont jeté le sort sur mon peuple, et ont donné le jeune garçon pour une prostituée, et ont vendu la jeune fille pour du vin, et elles l’ont bu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 4, 'Et vous aussi, que me voulez-vous, Tyr et Sidon, et tous les districts de la Philistie? Est-ce une récompense que vous me donnez? Et si vous me récompensez, je ferai retomber votre récompense vite et promptement sur votre tête;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 5, 'parce que vous avez pris mon argent et mon or, et que vous avez porté dans vos temples mes belles choses désirables,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 6, 'et que vous avez vendu aux fils de Javan les fils de Juda et les fils de Jérusalem, afin de les éloigner de leurs confins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 7, 'Voici, je les réveillerai du lieu où vous les avez vendus, et je ferai retomber votre récompense sur votre tête;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 8, 'et je vendrai vos fils et vos filles en la main des fils de Juda, et ils les vendront aux Sabéens, à une nation lointaine; car l’ Éternel a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 9, 'Proclamez ceci parmi les nations, préparez la guerre, réveillez les hommes forts; qu’ils approchent, qu’ils montent, tous les hommes de guerre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 10, 'De vos socs forgez des épées, et de vos serpes, des javelines. Que le faible dise: Je suis fort!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 11, 'Accourez et venez, vous, toutes les nations, de toute part, et rassemblez-vous! Là, Éternel, fais descendre tes hommes forts!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 12, 'Que les nations se réveillent et montent à la vallée de Josaphat, car là je m’assiérai pour juger toutes les nations, de toute part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 13, 'Mettez la faucille, car la moisson est mûre; venez, descendez, car le pressoir est plein, les cuves regorgent; car leur iniquité est grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 14, 'Multitudes, multitudes, dans la vallée de jugement! car le jour de l’ Éternel est proche dans la vallée de jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 15, 'Le soleil et la lune seront obscurcis, et les étoiles retireront leur splendeur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 16, 'et l’ Éternel rugira de Sion, et de Jérusalem il fera entendre sa voix, et les cieux et la terre trembleront; et l’ Éternel sera l’abri de son peuple et le refuge des fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 17, 'Et vous saurez que moi, l’ Éternel, je suis votre Dieu, qui demeure en Sion, ma montagne sainte. Et Jérusalem sera sainte, et les étrangers n’y passeront plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 18, 'Et il arrivera, en ce jour-là, que les montagnes ruisselleront de moût, et les collines découleront de lait, et tous les torrents de Juda découleront d’eau; et une source sortira de la maison de l’ Éternel, et arrosera la vallée de Sittim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 19, 'L’Égypte sera une désolation, et Édom sera un désert désolé, à cause de leur violence contre les fils de Juda, parce qu’ils ont répandu du sang innocent dans leur pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 20, 'Mais Juda sera habité à toujours, et Jérusalem de génération en génération,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 21, 'et je les purifierai du sang dont je ne les avais pas purifiés: et l’ Éternel demeure en Sion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Les paroles d’Amos, qui était d’entre les bergers de Thekoa, qu’il a vues touchant Israël, aux jours d’Ozias, roi de Juda, et aux jours de Jéroboam, fils de Joas, roi d’Israël, deux ans avant le tremblement de terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Et il dit: L’ Éternel rugit de Sion, et de Jérusalem il fait entendre sa voix; et les pâturages des bergers mènent deuil, et le sommet du Carmel est séché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Ainsi dit l’ Éternel: À cause de trois transgressions de Damas, et à cause de quatre, je ne révoquerai pas [mon arrêt]; parce qu’ils ont foulé Galaad avec des traîneaux de fer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Et j’enverrai un feu dans la maison de Hazaël, et il dévorera les palais de Ben-Hadad;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'et je briserai la barre de Damas, et, de la vallée d’Aven je retrancherai l’habitant, et de Beth-Éden, celui qui tient le sceptre; et le peuple de la Syrie ira en captivité à Kir, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Ainsi dit l’ Éternel: À cause de trois transgressions de Gaza, et à cause de quatre, je ne le révoquerai point, parce qu’ils ont emmené captive la captivité tout entière, pour la livrer à Édom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'mais j’enverrai un feu dans les murs de Gaza, et il dévorera ses palais;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'et je retrancherai d’Asdod l’habitant, et d’Askalon celui qui tient le sceptre; et je tournerai ma main contre Ékron, et le reste des Philistins périra, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Ainsi dit l’ Éternel: À cause de trois transgressions de Tyr, et à cause de quatre, je ne le révoquerai point, parce qu’ils ont livré la captivité tout entière à Édom, et ne se sont pas souvenus de l’alliance fraternelle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'mais j’enverrai un feu dans les murs de Tyr, et il dévorera ses palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Ainsi dit l’ Éternel: À cause de trois transgressions d’Édom, et à cause de quatre, je ne le révoquerai point, parce qu’il a poursuivi son frère avec l’épée, et a étouffé la miséricorde, et que sa colère déchira sans fin, et qu’il garda sa fureur à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Et j’enverrai un feu sur Théman, et il dévorera les palais de Botsra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Ainsi dit l’ Éternel: À cause de trois transgressions des fils d’Ammon, et à cause de quatre, je ne le révoquerai point, parce qu’ils ont fendu le ventre aux femmes enceintes de Galaad, afin d’élargir leurs frontières;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'et j’allumerai un feu dans les murs de Rabba, et il dévorera ses palais, au milieu des cris au jour de la bataille, au milieu de la tempête au jour du tourbillon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'et leur roi ira en captivité, lui et ses princes ensemble, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Ainsi dit l’ Éternel: À cause de trois transgressions de Moab, et à cause de quatre, je ne le révoquerai point, parce qu’il a brûlé, [réduit] en chaux les os du roi d’Édom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'et j’enverrai un feu sur Moab, et il dévorera les palais de Kerijoth, et Moab mourra au milieu du tumulte, au milieu des cris, au son de la trompette,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'et je retrancherai le juge du milieu de lui, et je tuerai tous ses princes avec lui, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Ainsi dit l’ Éternel: À cause de trois transgressions de Juda, et à cause de quatre, je ne le révoquerai point, parce qu’ils ont méprisé la loi de l’ Éternel et n’ont pas gardé ses statuts, et que leurs mensonges, après lesquels leurs pères ont marché, les ont fait errer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'et j’enverrai un feu dans Juda, et il dévorera les palais de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Ainsi dit l’ Éternel: À cause de trois transgressions d’Israël, et à cause de quatre, je ne le révoquerai point, parce qu’ils ont vendu le juste pour de l’argent, et le pauvre pour une paire de sandales,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'eux qui désirent ardemment [de voir] la poussière de la terre sur la tête des chétifs, et qui pervertissent le chemin des débonnaires; et un homme et son père vont vers la [même] fille, pour profaner mon saint nom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'et ils s’étendent à côté de chaque autel, sur des vêtements pris en gage, et boivent dans la maison de leur dieu le vin de ceux qui ont été mis à l’amende.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Mais moi, j’ai détruit devant eux l’Amoréen, dont la taille était comme la hauteur des cèdres, et qui était fort comme les chênes; et j’ai détruit son fruit en haut et ses racines en bas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Et moi, je vous ai fait monter du pays d’Égypte, et je vous ai fait marcher dans le désert 40 ans, pour posséder le pays de l’Amoréen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Et j’ai suscité des prophètes d’entre vos fils, et d’entre vos jeunes gens, des nazaréens. N’en est-il pas ainsi, fils d’Israël? dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Et vous avez fait boire du vin aux nazaréens, et vous avez commandé aux prophètes, disant: Ne prophétisez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Voici, je pèserai sur vous comme pèse le char plein de gerbes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Et la fuite manquera à celui qui est agile; et le fort n’affermira pas sa force; et l’homme vaillant ne sauvera pas sa vie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'et celui qui manie l’arc ne tiendra pas ferme; et celui qui a les pieds agiles n’échappera pas; et celui qui monte le cheval ne sauvera pas sa vie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'et celui qui a le cœur plein de courage parmi les hommes vaillants s’enfuira nu en ce jour-là, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, '*Écoutez cette parole que l’ Éternel prononce sur vous, fils d’Israël, sur la famille entière que j’ai fait monter du pays d’Égypte, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Je vous ai connus, vous seuls, de toutes les familles de la terre; c’est pourquoi je visiterai sur vous toutes vos iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Deux [hommes] peuvent-ils marcher ensemble s’ils ne sont pas d’accord?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Le lion rugira-t-il dans la forêt s’il n’a pas de proie? Le lionceau fera-t-il entendre sa voix de son repaire, s’il n’a pris quelque chose?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'L’oiseau tombera-t-il dans le piège sur la terre, quand il n’y a pas de filet [tendu] pour lui? Le piège se lèvera-t-il du sol, s’il n’a rien pris du tout?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Sonnera-t-on de la trompette dans une ville, et le peuple ne tremblera pas? Y aura-t-il du mal dans une ville, et l’ Éternel ne l’aura pas fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Or le Seigneur, l’ Éternel, ne fera rien, qu’ il ne révèle son secret à ses serviteurs les prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Le lion a rugi: qui n’aura peur? Le Seigneur, l’ Éternel, a parlé: qui ne prophétisera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Faites-le entendre dans les palais dans Asdod, et dans les palais dans le pays d’Égypte, et dites: Assemblez-vous sur les montagnes de Samarie, et voyez la grande confusion qui est au milieu d’elle, et les oppressions [qui ont lieu] dans son sein:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'et ils ne savent pas faire ce qui est droit, dit l’ Éternel, eux qui amassent la violence et la rapine dans leurs palais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'C’est pourquoi, ainsi dit le Seigneur, l’ Éternel: L’ennemi! – et tout autour du pays! Et il abattra ta force, et tes palais seront pillés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Ainsi dit l’ Éternel: Comme le berger sauve de la gueule du lion deux jambes ou un bout d’oreille, ainsi seront sauvés les fils d’Israël qui sont assis à Samarie sur le coin d’un lit, et sur le damas d’un divan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Écoutez, et rendez témoignage dans la maison de Jacob, dit le Seigneur, l’ Éternel, le Dieu des armées,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'qu’au jour où je visiterai les transgressions d’Israël sur lui, je punirai les autels de Béthel, et les cornes de l’autel seront coupées et tomberont à terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Et je frapperai la maison d’hiver avec la maison d’été, et les maisons d’ivoire périront, et beaucoup de maisons cesseront d’exister, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Écoutez cette parole, vaches de Basan, qui êtes sur la montagne de Samarie, qui opprimez les chétifs, qui écrasez les pauvres, qui dites à vos maîtres: Apporte, afin que nous buvions!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Le Seigneur, l’ Éternel, a juré par sa sainteté, que, voici, des jours viennent sur vous, où il vous enlèvera avec des hameçons, et votre postérité avec des haims de pêche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Et vous sortirez par les brèches, chacune droit devant elle, et vous serez lancées vers Harmon, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Venez à Béthel, et péchez! À Guilgal, multipliez la transgression! Apportez le matin vos sacrifices, tous les trois jours vos dîmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'et faites fumer du pain levé [en sacrifice] d’actions de grâces; et publiez des offrandes volontaires, annoncez-[les]! Car c’est ainsi que vous aimez [à faire], fils d’Israël, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Et moi aussi, je vous ai donné les dents nettes dans toutes vos villes, et le manque de pain dans toutes vos demeures; et vous n’êtes pas revenus à moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Et je vous ai aussi retenu la pluie quand il n’y avait que trois mois jusqu’à la moisson; et j’ai fait pleuvoir sur une ville, et je n’ai pas fait pleuvoir sur une [autre] ville; il y avait de la pluie sur un champ, et le champ sur lequel il n’y avait pas de pluie séchait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'et deux [et] trois villes se rendaient dans une [autre] ville pour boire de l’eau, et ils n’ont pas été rassasiés; et vous n’êtes pas revenus à moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Je vous ai frappés par la brûlure et la rouille [des blés]; la chenille a dévoré la multitude de vos jardins, et de vos vignes, et de vos figuiers et de vos oliviers; mais vous n’êtes pas revenus à moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'J’ai envoyé parmi vous une peste à la façon de l’Égypte; j’ai tué vos jeunes gens par l’épée, emmenant aussi vos chevaux; et j’ai fait monter la puanteur de vos camps, et [cela] dans vos narines; et vous n’êtes pas revenus à moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'J’ai fait des renversements parmi vous, comme la subversion que Dieu a faite de Sodome et de Gomorrhe, et vous avez été comme un tison sauvé d’un incendie; et vous n’êtes pas revenus à moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'C’est pourquoi, je te ferai ainsi, Israël. Puisque je te ferai ceci, prépare-toi, Israël, à rencontrer ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Car voici, celui qui forme les montagnes, et qui crée le vent, et qui déclare à l’homme quelle est sa pensée, qui de l’aube fait des ténèbres, et qui marche sur les lieux hauts de la terre, – l’ Éternel, le Dieu des armées, est son nom!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, '*Écoutez cette parole, une complainte que j’élève sur vous, maison d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Elle est tombée, elle ne se relèvera pas, la vierge d’Israël; elle est étendue sur sa terre, il n’y a personne qui la relève.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Car ainsi dit le Seigneur, l’ Éternel: La ville qui allait en campagne avec 1 000, en aura 100 de reste; et celle qui allait en campagne avec 100, en aura dix de reste, pour la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Car ainsi dit l’ Éternel à la maison d’Israël: Cherchez-moi, et vous vivrez;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'et ne cherchez pas Béthel, et n’allez pas à Guilgal, et ne passez pas à Beër-Shéba; car Guilgal ira certainement en captivité, et Béthel sera réduite à rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Cherchez l’ Éternel, et vous vivrez, de peur qu’il n’envahisse comme le feu la maison de Joseph, et ne la dévore, et qu’il n’y ait personne à Béthel qui éteigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Vous qui changez en absinthe le droit, et qui couchez par terre la justice,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, '[cherchez-le], lui qui a fait les Pléiades et Orion; qui change en matin l’ombre de la mort, et transforme le jour en ténèbres de la nuit; qui appelle les eaux de la mer, et les verse sur la face de la terre: l’ Éternel est son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Il fait lever subitement la destruction sur le fort, et la destruction vient sur la forteresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Ils haïssent celui qui reprend à la porte, et ont en abomination celui qui parle avec intégrité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'C’est pourquoi, parce que vous foulez aux pieds le pauvre, et que vous prenez de lui des charges de blé: vous avez bâti des maisons de pierres de taille, mais vous n’y habiterez pas; vous avez planté des vignes excellentes, et vous n’en boirez pas le vin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'car je connais vos nombreuses transgressions et vos grands péchés: ils oppriment le juste, prennent des présents, et font fléchir à la porte le droit des pauvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'C’est pourquoi, en ce temps-ci, le sage gardera le silence, car c’est un temps mauvais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Recherchez le bien, et non le mal, afin que vous viviez; et ainsi l’ Éternel, le Dieu des armées, sera avec vous, comme vous le dites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Haïssez le mal, et aimez le bien, et établissez dans la porte le juste jugement; peut-être l’ Éternel, le Dieu des armées, usera-t-il de grâce envers le reste de Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'C’est pourquoi, ainsi dit l’ Éternel, le Dieu des armées, le Seigneur: Dans toutes les places, la lamentation! et dans toutes les rues, on dira: Hélas, hélas! Et on appellera le laboureur au deuil, et à la lamentation ceux qui s’entendent aux chants de douleur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Et dans toutes les vignes, la lamentation! car je passerai au milieu de toi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Malheur à vous qui désirez le jour de l’ Éternel! À quoi vous [servira] le jour de l’ Éternel? Il sera ténèbres, et non lumière,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'comme si un homme s’enfuyait de devant un lion, et qu’un ours le rencontre; ou qu’il entre dans la maison et appuie sa main contre le mur, et qu’un serpent le morde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Le jour de l’ Éternel n’est-il pas ténèbres, et non lumière? et profonde obscurité, et non splendeur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Je hais, je méprise vos fêtes, et je ne flairerai pas [de bonne odeur] dans vos assemblées solennelles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'si vous m’offrez des holocaustes et vos offrandes de gâteau, je ne les agréerai pas, et je ne regarderai pas le sacrifice de prospérités de vos bêtes grasses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Ôte de devant moi le bruit de tes cantiques; et la musique de tes luths, je ne l’écouterai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Mais que le jugement roule comme des eaux, et la justice comme un fleuve qui ne tarit pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'M’avez-vous offert des sacrifices et des offrandes dans le désert, pendant 40 ans, maison d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Mais vous avez porté le tabernacle de votre Moloc, et le Kiun de vos images, l’étoile de votre dieu, que vous vous êtes fait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'et je vous transporterai au-delà de Damas, dit l’ Éternel; son nom est le Dieu des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, '*Malheur à ceux qui sont à l’aise en Sion, et à ceux qui vivent en sécurité sur la montagne de Samarie, les grands de la première des nations, auprès desquels vient la maison d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Passez à Calné, et voyez; et, de là, allez à Hamath la grande, et descendez à Gath des Philistins: sont-elles meilleures que ces royaumes-ci? Est-ce que leur frontière est plus étendue que votre frontière?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Vous qui éloignez le mauvais jour, et qui faites approcher le siège de la violence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'vous qui vous couchez sur des lits d’ivoire et qui vous étendez mollement sur vos divans, et qui mangez les agneaux du troupeau et les veaux gras de l’étable;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'qui chantez au son du luth, [et] inventez, comme David, à votre usage, des instruments pour le chant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'qui buvez le vin dans des coupes, et vous oignez de la meilleure huile, et ne vous affligez pas de la brèche de Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'C’est pourquoi, maintenant ils iront en captivité à la tête de ceux qui vont en captivité, et les cris de ceux qui sont mollement couchés cesseront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Le Seigneur, l’ Éternel, a juré par lui-même, dit l’ Éternel, le Dieu des armées: J’ai en horreur l’orgueil de Jacob, et je hais ses palais; et je livrerai la ville et tout ce qu’elle contient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Et il arrivera que, s’il reste dix hommes dans une maison, ils mourront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'et le parent de [l’un d’eux], celui qui doit le brûler, prendra le mort pour sortir de la maison les os, et il dira à celui qui est dans l’intérieur de la maison: Y a-t-il encore quelqu’un auprès de toi? Et il dira: Personne! Et il dira: Silence! car nous ne pouvons faire mention du nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Car voici, l’ Éternel a commandé, et on frappera la grande maison de brèches, et la petite maison, de fentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Les chevaux courront-ils sur un rocher, ou bien y labourera-t-on avec des bœufs? Car vous avez changé le droit en poison, et en absinthe le fruit de la justice,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'vous qui vous réjouissez en ce qui n’est rien, vous qui dites: Avec notre force, ne nous sommes-nous pas acquis de la puissance?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Car voici, maison d’Israël, dit l’ Éternel, le Dieu des armées, je suscite contre vous une nation, et ils vous opprimeront depuis l’entrée de Hamath jusqu’à la rivière de la plaine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, '*Ainsi m’a fait voir le Seigneur, l’ Éternel, et voici, il forma des sauterelles, comme le regain commençait à pousser; et voici, c’était le regain après la fauche du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Et il arriva, lorsqu’elles eurent entièrement mangé l’herbe de la terre, que je dis: Seigneur Éternel, pardonne, je te prie! Comment Jacob se relèvera-t-il? car il est petit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'L’ Éternel se repentit de cela: cela ne sera pas, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Ainsi m’a fait voir le Seigneur, l’ Éternel; et voici, le Seigneur, l’ Éternel, appela pour juger par le feu; et il dévora le grand abîme, et il dévora l’héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Et je dis: Seigneur Éternel, cesse, je te prie! Comment Jacob se relèvera-t-il? car il est petit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'L’ Éternel se repentit de cela: cela aussi ne sera pas, dit le Seigneur, l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Ainsi il m’a fait voir; et voici, le Seigneur se tenait sur un mur [bâti] d’aplomb, et il avait un plomb à sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Et l’ Éternel me dit: Que vois-tu, Amos? Et je dis: Un plomb. Et le Seigneur dit: Voici, je place un plomb au milieu de mon peuple Israël; je ne passerai plus par-dessus lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Et les hauts lieux d’Isaac seront désolés, et les sanctuaires d’Israël seront dévastés, et je me lèverai avec l’épée contre la maison de Jéroboam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Alors Amatsia, sacrificateur de Béthel, envoya à Jéroboam, roi d’Israël, disant: Amos a conspiré contre toi au milieu de la maison d’Israël; le pays ne peut pas supporter toutes ses paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Car ainsi dit Amos: Jéroboam mourra par l’épée, et Israël sera certainement transporté de dessus sa terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Et Amatsia dit à Amos: Voyant, va-t’en; fuis au pays de Juda, et mange là du pain, et prophétise là,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'mais ne prophétise plus à Béthel, car c’est le sanctuaire du roi et la maison du royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Et Amos répondit et dit à Amatsia: Je n’étais pas prophète, et je n’étais pas fils de prophète; mais je gardais le bétail, et je cueillais le fruit des sycomores;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'et l’ Éternel me prit quand je suivais le menu bétail, et l’ Éternel me dit: Va, prophétise à mon peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Et maintenant, écoute la parole de l’ Éternel: Tu me dis: Ne prophétise pas contre Israël, et ne profère pas des paroles contre la maison d’Isaac.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'C’est pourquoi, ainsi dit l’ Éternel: Ta femme se prostituera dans la ville, et tes fils et tes filles tomberont par l’épée, et ta terre sera partagée au cordeau, et tu mourras dans une terre impure, et Israël sera certainement transporté de dessus sa terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, '*Ainsi m’a fait voir le Seigneur, l’ Éternel, et voici, un panier de fruits d’été!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Et il dit: Que vois-tu, Amos? Et je dis: Un panier de fruits d’été. Et l’ Éternel me dit: La fin est venue pour mon peuple Israël; je ne passerai plus par-dessus lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Et, en ce jour-là, les cantiques du palais seront des hurlements, dit le Seigneur, l’ Éternel. Les cadavres seront en grand nombre; en tout lieu on les jettera dehors... Silence!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Écoutez ceci, vous qui êtes acharnés après les pauvres pour faire disparaître les débonnaires du pays,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'disant: Quand sera passée la nouvelle lune, pour que nous vendions du blé? et le sabbat, pour que nous ouvrions nos greniers? faisant l’épha petit et le sicle grand, et falsifiant la balance pour frauder;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'afin d’acheter les chétifs pour de l’argent, et le pauvre pour une paire de sandales, et de vendre la criblure du grain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'L’ Éternel a juré par la gloire de Jacob: Si jamais j’oublie aucune de leurs œuvres!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Pour cela, le pays ne tremblera-t-il pas? Et chacun de ses habitants ne mènera-t-il pas deuil? Et il montera tout entier comme le Nil, et enflera ses flots, et s’abaissera comme le fleuve d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Et il arrivera en ce jour-là, dit le Seigneur, l’ Éternel, que je ferai coucher le soleil en plein midi, et que j’amènerai les ténèbres sur la terre en plein jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Et je changerai vos fêtes en deuil, et toutes vos chansons en lamentation; et sur tous les reins j’amènerai le sac, et chaque tête je la rendrai chauve; et je ferai que ce sera comme le deuil d’un [fils] unique, et la fin sera comme un jour d’amertume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Voici, des jours viennent, dit le Seigneur, l’ Éternel, où j’enverrai une famine dans le pays; non une famine de pain, ni une soif d’eau, mais d’entendre les paroles de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Et ils erreront d’une mer à l’autre, et du nord au levant; ils courront çà et là pour chercher la parole de l’ Éternel, et ils ne la trouveront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'En ce jour-là, les belles vierges et les jeunes gens défailliront de soif, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'ceux qui jurent par le péché de Samarie et qui disent: Dan, ton Dieu est vivant! et: La voie de Beër-Shéba est vivante! Et ils tomberont, et ne se relèveront jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, '*Je vis le Seigneur se tenant debout sur l’autel, et il dit: Frappe le linteau, afin que les seuils soient ébranlés, et brise-leur la tête à tous; et ce qui restera d’eux, je le tuerai par l’épée. Celui d’entre eux qui s’enfuira, ne se sauvera pas par la fuite, et celui d’entre eux qui échappera, ne sera pas délivré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Quand ils pénétreraient jusque dans le shéol, de là ma main les prendra; et quand ils monteraient dans les cieux, je les en ferai descendre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'et quand ils se cacheraient au sommet du Carmel, je les y chercherai, et de là je les prendrai; et quand ils se seraient cachés de devant mes yeux, au fond de la mer, là je commanderai au serpent, et il les mordra;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'et quand ils iraient en captivité devant leurs ennemis, là, je commanderai à l’épée, et elle les tuera; et je mettrai mes yeux sur eux pour le mal et non pour le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Et le Seigneur, l’ Éternel des armées, c’est lui qui touche le pays, et il fond; et tous ceux qui y habitent mèneront deuil; et il montera tout entier comme le Nil, et il s’abaissera comme le fleuve d’Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'C’est lui qui bâtit dans les cieux ses degrés, et qui a fondé sa voûte sur la terre; qui appelle les eaux de la mer, et les verse sur la face de la terre; l’ Éternel est son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'N’êtes-vous pas pour moi comme les fils des Éthiopiens, ô fils d’Israël? dit l’ Éternel. N’ai-je pas fait monter Israël du pays d’Égypte, et les Philistins de Caphtor, et les Syriens de Kir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Voici, les yeux du Seigneur, l’ Éternel, sont sur le royaume pécheur, et je le détruirai de dessus la face de la terre; seulement je ne détruirai pas entièrement la maison de Jacob, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Car voici, je commande, et je secouerai la maison d’Israël parmi toutes les nations, comme on secoue dans un crible, mais pas un grain ne tombera à terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'C’est par l’épée que mourront tous les pécheurs de mon peuple, qui disent: Le mal ne nous atteindra pas, et ne viendra pas jusqu’à nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'En ce jour-là, je relèverai le tabernacle de David, qui est tombé, et je fermerai ses brèches, et je relèverai ses ruines, et je le bâtirai comme aux jours d’autrefois,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'afin qu’ils possèdent le reste d’Édom, et toutes les nations sur lesquelles mon nom est réclamé, dit l’ Éternel qui fait cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Voici, les jours viennent, dit l’ Éternel, où celui qui laboure atteindra celui qui moissonne, et celui qui foule les raisins, celui qui répand la semence; et les montagnes ruisselleront de moût, et toutes les collines se fondront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Et je rétablirai les captifs de mon peuple Israël, et ils bâtiront les villes dévastées et y habiteront, et ils planteront des vignes et en boiront le vin, et ils feront des jardins et en mangeront le fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Et je les planterai sur leur terre, et ils ne seront plus arrachés de dessus leur terre que je leur ai donnée, dit l’ Éternel, ton Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'La vision d’Abdias. – Ainsi dit le Seigneur, l’ Éternel, touchant Édom. Nous avons entendu une rumeur de par l’ Éternel, et un ambassadeur a été envoyé parmi les nations: Levez-vous! et levons-nous contre lui pour la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Voici, je t’ai fait petit parmi les nations; tu es fort méprisé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'L’arrogance de ton cœur t’a séduit, toi qui demeures dans les creux du rocher, ta haute habitation; [toi] qui dis dans ton cœur: Qui me fera descendre par terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Si tu t’élèves comme l’aigle, et que parmi les étoiles tu mettes ton nid, je te ferai descendre de là, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Si des voleurs, si des pillards de nuit venaient chez toi (comme tu es ruiné!) voleraient-ils plus que ce qui leur suffit? Si des vendangeurs venaient chez toi, ne laisseraient-ils pas des grappillages?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Comme Ésaü est fouillé! comme ses choses cachées sont mises à découvert!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Tous tes alliés t’ont poussé à la frontière; ceux qui étaient en paix avec toi t’ont trompé, ils ont prévalu contre toi; [ceux qui mangeaient] ton pain ont mis un piège sous toi. Il n’y a pas d’intelligence en lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'N’est-ce pas en ce jour-là, dit l’ Éternel, que je détruirai du milieu d’Édom les sages, et de la montagne d’Ésaü, l’intelligence?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Et tes hommes forts, ô Théman, seront terrifiés, afin que chacun soit retranché de la montagne d’Ésaü par le carnage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'À cause de la violence [faite] à ton frère Jacob, la honte te couvrira, et tu seras retranché pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Au jour où tu te tins vis-à-vis, au jour où des étrangers emportaient ses richesses, et où des forains entraient dans ses portes et jetaient le sort sur Jérusalem, toi aussi tu étais comme l’un d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Mais tu n’aurais pas dû regarder le jour de ton frère, le jour de son désastre; et tu n’aurais pas dû te réjouir au sujet des fils de Juda, au jour de leur destruction, et tu n’aurais pas dû ouvrir ta bouche toute grande au jour de la détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Tu n’aurais pas dû entrer dans la porte de mon peuple, au jour de leur calamité; ni regarder, toi non plus, sa misère, au jour de sa calamité; et tu n’aurais pas dû porter [la main] sur ses richesses au jour de sa calamité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'et tu n’aurais pas dû te tenir au carrefour pour exterminer ses réchappés, et tu n’aurais pas dû livrer ceux des siens qui étaient demeurés de reste au jour de la détresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Car le jour de l’ Éternel est proche, contre toutes les nations: comme tu as fait, il te sera fait; ta récompense retombera sur ta tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Car, comme vous avez bu sur ma montagne sainte, toutes les nations boiront continuellement; et elles boiront, et elles avaleront, et elles seront comme si elles n’avaient pas été.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Et sur la montagne de Sion il y aura délivrance; et elle sera sainte, et la maison de Jacob possédera ses possessions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Et la maison de Jacob sera un feu, et la maison de Joseph, une flamme; et la maison d’Ésaü sera du chaume; et elles y mettront le feu et la dévoreront; et il n’y aura pas de reste de la maison d’Ésaü, car l’ Éternel a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Et ceux du midi posséderont la montagne d’Ésaü, et ceux du pays plat, les Philistins; et [les fils d’Israël] posséderont la campagne d’Éphraïm et la campagne de Samarie; et Benjamin [possédera] Galaad.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Et les captifs de cette armée des fils d’Israël [posséderont] ce qui appartenait aux Cananéens jusqu’à Sarepta, et les captifs de Jérusalem, qui [avaient été] à Sepharad, posséderont les villes du midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Et des sauveurs monteront sur la montagne de Sion pour juger la montagne d’Ésaü. Et le royaume sera à l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Et la parole de l’ Éternel [vint] à Jonas, fils d’Amitthaï, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Lève-toi, va à Ninive, la grande ville, et crie contre elle, car leur méchanceté est montée devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Et Jonas se leva pour s’enfuir à Tarsis, de devant la face de l’ Éternel; et il descendit à Joppé et trouva un navire allant à Tarsis; et ayant donné le prix de sa place, il y descendit pour aller avec eux à Tarsis, de devant la face de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Et l’ Éternel envoya un grand vent sur la mer; et il y eut une grande tempête sur la mer, de sorte que le navire semblait vouloir se briser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Et les marins eurent peur et crièrent chacun à son dieu; et ils jetèrent dans la mer les objets qui étaient dans le navire, pour l’en alléger. Et Jonas était descendu au fond du vaisseau et s’était couché, et dormait profondément.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Et le maître des rameurs s’approcha de lui, et lui dit: Que fais-tu, dormeur? Lève-toi, crie à ton Dieu! Peut-être Dieu pensera-t-il à nous, et nous ne périrons pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Et ils se dirent l’un à l’autre: Venez, jetons le sort, afin que nous sachions à cause de qui ce malheur nous arrive. Et ils jetèrent le sort, et le sort tomba sur Jonas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Et ils lui dirent: Déclare-nous à cause de qui ce mal nous est arrivé? Quelle est ton occupation? et d’où viens-tu? Quel est ton pays, et de quel peuple es-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Et il leur dit: Je suis Hébreu, et je crains l’ Éternel, le Dieu des cieux, qui a fait la mer et la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Et les hommes eurent une grande frayeur, et ils lui dirent: Qu’est-ce que tu as fait? Car les hommes savaient qu’il s’enfuyait de devant la face de l’ Éternel, car il le leur avait déclaré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Et ils lui dirent: Que te ferons-nous, afin que la mer s’apaise pour nous? car la mer allait grossissant toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Et il leur dit: Prenez-moi et jetez-moi à la mer, et la mer s’apaisera pour vous; car je sais que c’est à cause de moi que cette grosse tempête est [venue] sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Mais les hommes ramèrent pour regagner la terre; et ils ne purent pas, car la mer allait toujours grossissant contre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Et ils crièrent à l’ Éternel, et dirent: Ah, Éternel! que nous ne périssions pas, nous t’en prions, à cause de la vie de cet homme; et ne mets pas sur nous du sang innocent; car toi, Éternel, tu as fait comme il t’a plu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Et ils prirent Jonas et le jetèrent à la mer; et la fureur de la mer s’arrêta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Et les hommes craignirent beaucoup l’ Éternel, et offrirent un sacrifice à l’ Éternel, et firent des vœux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Et l’ Éternel prépara un grand poisson pour engloutir Jonas; et Jonas fut dans les entrailles du poisson trois jours et trois nuits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Et Jonas pria l’ Éternel, son Dieu, des entrailles du poisson,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'et il dit: J’ai crié à l’ Éternel du fond de ma détresse, et il m’a répondu. Du sein du shéol, j’ai crié; tu as entendu ma voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Tu m’as jeté dans l’abîme, dans le cœur des mers, et le courant m’a entouré; toutes tes vagues et tes flots ont passé sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Et moi je disais: Je suis rejeté de devant tes yeux: toutefois, je regarderai encore vers le temple de ta sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Les eaux m’ont environné jusqu’à l’âme, l’abîme m’a entouré, les algues ont enveloppé ma tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Je suis descendu jusqu’aux fondements des montagnes; les barres de la terre s’étaient fermées sur moi pour toujours; mais, ô Éternel, mon Dieu, tu as fait remonter ma vie de la fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Quand mon âme défaillait en moi, je me suis souvenu de l’ Éternel, et ma prière est venue jusqu’à toi, dans le temple de ta sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Ceux qui regardent aux vanités mensongères abandonnent la grâce qui est à eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Mais moi, je te sacrifierai avec une voix de louange; je m’acquitterai de ce que j’ai voué. La délivrance est de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, 'Et l’ Éternel commanda au poisson, et il vomit Jonas sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Et la parole de l’ Éternel [vint] à Jonas une seconde fois, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Lève-toi, va à Ninive, la grande ville, et crie-lui selon le cri que je te dirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Et Jonas se leva et s’en alla à Ninive, selon la parole de l’ Éternel. Or Ninive était une fort grande ville, de trois journées de chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Et Jonas commença à entrer dans la ville, le chemin d’un jour; et il cria et dit: Encore 40 jours, et Ninive sera renversée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Et les hommes de Ninive crurent Dieu, et proclamèrent un jeûne, et se vêtirent de sacs, depuis les plus grands d’entre eux jusqu’aux plus petits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Car la parole parvint au roi de Ninive, et il se leva de son trône, et ôta de dessus lui son manteau, et se couvrit d’un sac et s’assit sur la cendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Et il fit crier et dire dans Ninive, par un édit du roi et de ses grands, disant: Que les hommes, et les bêtes, le gros et le menu bétail, ne goûtent de rien; qu’ils ne paissent pas et ne boivent pas d’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'et que les hommes et les bêtes soient recouverts de sacs. Et qu’ils crient à Dieu avec force; et qu’ils reviennent, chacun, de leur mauvaise voie et de la violence qui est en leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Qui sait? Dieu reviendra et se repentira, et reviendra de l’ardeur de sa colère, et nous ne périrons pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Et Dieu vit leurs œuvres, qu’ils revenaient de leur mauvaise voie; et Dieu se repentit du mal qu’il avait parlé de leur faire, et il ne le fit pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Mais Jonas trouva [cela] très mauvais, et il fut irrité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Et il pria l’ Éternel, et dit: Éternel, je te prie, n’était-ce pas là ma parole, quand j’étais encore dans mon pays? C’est pourquoi j’ai d’abord voulu m’enfuir à Tarsis, car je savais que tu es un ✶Dieu qui fais grâce et qui es miséricordieux, lent à la colère et grand en bonté et qui te repens du mal [dont tu as menacé];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'et maintenant, Éternel, je t’en prie, prends-moi ma vie, car mieux me vaut la mort que la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Et l’ Éternel dit: Fais-tu bien de t’irriter?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Et Jonas sortit de la ville, et s’assit à l’orient de la ville; et il se fit là une cabane, et s’assit dessous à l’ombre, jusqu’à ce qu’il voie ce qui arriverait à la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Et l’ Éternel Dieu prépara un kikajon et le fit monter au-dessus de Jonas, pour faire ombre sur sa tête, pour le délivrer de sa misère, et Jonas se réjouit d’une grande joie à cause du kikajon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Et Dieu prépara un ver le lendemain, au lever de l’aurore, et il rongea le kikajon, et il sécha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Et il arriva que, quand le soleil se leva, Dieu prépara un doux vent d’orient, et le soleil frappa la tête de Jonas, et il défaillait, et il demanda la mort pour son âme, et dit: Mieux me vaut la mort que la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Et Dieu dit à Jonas: Fais-tu bien de t’irriter à cause du kikajon? Et il dit: Je fais bien de m’irriter jusqu’à la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Et l’ Éternel dit: Tu as pitié du kikajon pour lequel tu n’as pas travaillé, et que tu n’as pas fait croître; qui, né en une nuit, a péri en une nuit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'et moi, je n’aurais pas pitié de Ninive, la grande ville, dans laquelle il y a plus de 120 000 êtres humains qui ne savent pas distinguer entre leur droite et leur gauche, et [aussi] beaucoup de bétail!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'La parole de l’ Éternel qui vint à Michée, le Morashtite, aux jours de Jotham, d’Achaz, d’Ézéchias, rois de Juda, laquelle il vit au sujet de Samarie et de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Écoutez, vous, tous les peuples; sois attentive, terre, et tout ce qui est en toi; et que le Seigneur, l’ Éternel, soit témoin contre vous, le Seigneur, du palais de sa sainteté!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Car voici, l’ Éternel sort de son lieu, et descendra, et marchera sur les lieux hauts de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'et les montagnes se fondront sous lui, et les vallées s’entrouvriront, comme la cire devant le feu, comme des eaux versées sur une pente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Tout cela, à cause de la transgression de Jacob et à cause des péchés de la maison d’Israël! [De] qui est la transgression de Jacob? N’est-ce pas [de] Samarie? Et [de] qui, les hauts lieux de Juda? N’est-ce pas [de] Jérusalem?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Et je ferai de Samarie un monceau dans les champs, des plantations de vigne; et je ferai rouler ses pierres dans la vallée, et je découvrirai ses fondements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Et toutes ses images taillées seront mises en pièces; et tous ses présents [de prostitution] seront brûlés au feu; et je mettrai en désolation toutes ses idoles; car c’est avec un présent de prostituée qu’elle les a rassemblées, et elles redeviendront un présent de prostituée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'À cause de cela je me frapperai [la poitrine], et je hurlerai; j’irai dépouillé et nu; je ferai une lamentation comme les chacals, et des cris de deuil comme les autruches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Car sa plaie est incurable; car elle est venue jusqu’à Juda, elle atteint jusqu’à la porte de mon peuple, jusqu’à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Ne le racontez pas dans Gath, ne versez point de pleurs. Dans Beth-Leaphra, roule-toi dans la poussière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Passe outre, toi, habitante de Shaphir, ta nudité découverte! L’habitante de Tsaanan n’est pas sortie [pour] la lamentation de Beth-Haëtsel; il vous ôtera son abri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Car l’habitante de Maroth s’attendait au bien, mais le mal est descendu de par l’ Éternel à la porte de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Attache le char au coursier, habitante de Lakis: elle a été les prémices du péché pour la fille de Sion; car en toi ont été trouvées les transgressions d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'C’est pourquoi tu donneras des présents à Morésheth-Gath. Les maisons d’Aczib seront un mensonge pour les rois d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'À toi j’amènerai encore l’héritier, habitante de Marésha; la gloire d’Israël viendra jusqu’à Adullam.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Rends-toi chauve et coupe tes cheveux pour les fils de tes délices; élargis ta tonsure, comme le vautour; car ils sont allés en captivité loin de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Malheur à ceux qui méditent la vanité et qui préparent le mal sur leurs lits! À la lumière du matin, ils l’exécutent, parce que c’est au pouvoir de leur main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Et ils convoitent des champs et les ravissent, et des maisons, et ils s’en emparent; et ils oppriment l’homme et sa maison, l’homme et son héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'C’est pourquoi, ainsi dit l’ Éternel: Voici, je médite contre cette famille un mal d’où vous ne pourrez pas retirer vos cous; et vous ne marcherez pas la tête haute, car c’est un temps mauvais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'En ce jour-là, on vous prendra pour proverbe, et on se lamentera dans une douloureuse lamentation; on dira: Nous sommes entièrement détruits; il a changé la portion de mon peuple: comme il me l’a ôtée! À celui qui se détourne [de l’ Éternel] il a partagé nos champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'C’est pourquoi tu n’auras personne qui étende le cordeau pour [faire] un lot dans la congrégation de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Ne prophétisez point, prophétisent-ils. S’ils ne prophétisent pas à ceux-ci, l’ignominie ne s’éloignera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Toi qui es appelée la maison de Jacob: l’ Éternel est-il impatient? Sont-ce là ses actes? Mes paroles ne font-elles pas du bien à celui qui marche avec droiture?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Naguère encore mon peuple s’est levé comme un ennemi: vous enlevez le manteau avec la tunique à ceux qui passent en sécurité, qui se détournent de la guerre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'vous avez chassé les femmes de mon peuple des maisons de leurs délices; de dessus leurs enfants, vous avez ôté ma magnificence, pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Levez-vous et allez-vous-en! car ce n’est pas ici un lieu de repos, à cause de la souillure qui amène la ruine: la ruine est terrible!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'S’il y a un homme qui marche selon le vent et le mensonge, qui mente, [disant]: Je te prophétiserai au sujet du vin et de la boisson forte! il sera le prophète de ce peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Je te rassemblerai certainement, Jacob, toi, tout entier; je réunirai certainement le résidu d’Israël; je les mettrai ensemble comme le menu bétail de Botsra, comme un troupeau au milieu de son pâturage. Ils bruiront à cause [de la multitude] des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Celui qui fait la brèche est monté devant eux; ils ont fait la brèche et ont passé par la porte, et sont sortis par elle, et leur roi est passé devant eux, et l’ Éternel est à leur tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, '*Et je dis: Écoutez, je vous prie, chefs de Jacob, et vous, princes de la maison d’Israël: N’est-ce pas à vous de connaître ce qui est juste?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Vous qui haïssez le bien et qui aimez le mal, qui arrachez leur peau de dessus eux, et leur chair de dessus leurs os,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'qui mangez la chair de mon peuple et ôtez leur peau de dessus eux, et qui brisez leurs os, et les mettez en morceaux comme dans une chaudière, et comme de la chair au milieu d’une marmite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Alors ils crieront à l’ Éternel, et il ne leur répondra pas, et il leur cachera sa face en ce temps-là, selon qu’ils ont agi méchamment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Ainsi dit l’ Éternel touchant les prophètes qui font errer mon peuple; qui mordent avec leurs dents, et crient: Paix! et si quelqu’un ne met rien dans leur bouche, ils préparent la guerre contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'C’est pourquoi vous aurez la nuit, sans vision, et vous aurez les ténèbres, sans divination; et le soleil se couchera sur les prophètes, et le jour s’obscurcira sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Et les voyants seront honteux, et les devins seront confondus, et ils se couvriront tous la barbe, parce qu’ il n’y a pas de réponse de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Mais moi, je suis plein de puissance par l’esprit de l’ Éternel, et de jugement et de force pour déclarer à Jacob sa transgression et à Israël son péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Écoutez ceci, je vous prie, chefs de la maison de Jacob, et vous, princes de la maison d’Israël, qui abhorrez le jugement et pervertissez toute droiture,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'bâtissant Sion avec du sang, et Jérusalem avec l’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Ses chefs jugent pour des présents, et ses sacrificateurs enseignent pour un salaire, et ses prophètes devinent pour de l’argent et s’appuient sur l’ Éternel, disant: L’ Éternel n’est-il pas au milieu de nous? Il ne viendra point de mal sur nous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'C’est pourquoi, à cause de vous, Sion sera labourée comme un champ, et Jérusalem sera des monceaux de pierres, et la montagne de la maison, les lieux hauts d’une forêt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Et il arrivera, à la fin des jours, que la montagne de la maison de l’ Éternel sera établie sur le sommet des montagnes, et sera élevée au-dessus des collines; et les peuples y afflueront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'et beaucoup de nations iront, et diront: Venez, et montons à la montagne de l’ Éternel, et à la maison du Dieu de Jacob, et il nous instruira de ses voies, et nous marcherons dans ses sentiers. Car de Sion sortira la loi, et de Jérusalem, la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Et il jugera au milieu de beaucoup de peuples, et prononcera le droit à de fortes nations jusqu’au loin; et de leurs épées ils forgeront des socs, et de leurs lances, des serpes: une nation ne lèvera pas l’épée contre une [autre] nation, et on n’apprendra plus la guerre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Et ils s’assiéront chacun sous sa vigne et sous son figuier, et il n’y aura personne qui les effraie: car la bouche de l’ Éternel des armées a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Car tous les peuples marcheront, chacun au nom de son dieu; et nous, nous marcherons au nom de l’ Éternel, notre Dieu, à toujours et à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'En ce jour-là, dit l’ Éternel, je rassemblerai celle qui boitait, et je recueillerai celle qui était chassée et celle sur laquelle j’avais fait venir du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Et je ferai de celle qui boitait, un reste, et de celle qui avait été repoussée au loin, une nation forte; et l’ Éternel régnera sur eux, en la montagne de Sion, dès lors et à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Et toi, tour du troupeau, colline élevée de la fille de Sion, à toi arrivera et viendra la domination première, – le royaume, à la fille de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Maintenant, pourquoi pousses-tu des cris? N’y a-t-il point de roi au milieu de toi? Ton conseiller a-t-il péri? car l’angoisse t’a saisie, comme une femme qui enfante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Sois dans l’angoisse et gémis, fille de Sion, comme une femme qui enfante; car maintenant tu sortiras de la ville, et tu habiteras aux champs, et tu viendras jusqu’à Babylone; là, tu seras délivrée; là, l’ Éternel te rachètera de la main de tes ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Et maintenant sont rassemblées contre toi beaucoup de nations qui disent: Qu’elle soit profanée, que notre œil voie Sion!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Mais elles ne connaissent pas les pensées de l’ Éternel et ne comprennent pas son conseil; car il les a amassées comme la gerbe sur l’aire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Lève-toi et foule, fille de Sion, car je ferai ta corne de fer, et je ferai tes sabots d’airain, et tu broieras beaucoup de peuples; et je consacrerai leur butin à l’ Éternel, et leurs biens au Seigneur de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 14, 'Maintenant, attroupe-toi, fille de troupes; il a mis le siège contre nous; ils frappent le juge d’Israël avec une verge sur la joue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, '(Et toi, Bethléhem Éphrata, bien que tu sois petite entre les milliers de Juda, de toi sortira pour moi celui qui doit dominer en Israël, et duquel les origines ont été d’ancienneté, dès les jours d’éternité.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'C’est pourquoi il les livrera jusqu’au temps où celle qui enfante aura enfanté; et le reste de ses frères retournera vers les fils d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Et il se tiendra et paîtra [son troupeau] avec la force de l’ Éternel, dans la majesté du nom de l’ Éternel, son Dieu. Et ils habiteront [en sûreté], car maintenant il sera grand jusqu’aux bouts de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Et lui sera la paix. Quand l’Assyrien entrera dans notre pays, et quand il mettra le pied dans nos palais, nous établirons contre lui sept pasteurs et huit princes des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Et ils ravageront le pays d’Assyrie avec l’épée, et le pays de Nimrod dans ses portes. Et il [nous] délivrera de l’Assyrien, quand il entrera dans notre pays, et qu’il mettra le pied dans nos confins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Et le résidu de Jacob sera, au milieu de beaucoup de peuples, comme une rosée de par l’ Éternel, comme des ondées sur l’herbe, – qui n’attend pas l’homme, et ne dépend pas des fils des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Et le résidu de Jacob sera, parmi les nations, au milieu de beaucoup de peuples, comme un lion parmi les bêtes de la forêt, comme un jeune lion parmi les troupeaux de menu bétail, qui, s’il passe, foule et déchire, et il n’y a personne qui délivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Ta main se lèvera sur tes adversaires, et tous tes ennemis seront retranchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Et il arrivera, en ce jour-là, dit l’ Éternel, que je retrancherai tes chevaux du milieu de toi, et je détruirai tes chars;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'et je retrancherai les villes de ton pays, et je renverserai toutes tes forteresses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'et je retrancherai de ta main les enchantements, et tu n’auras pas de pronostiqueurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'et je retrancherai du milieu de toi tes images taillées et tes statues, et tu ne te prosterneras plus devant l’ouvrage de tes mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Et j’arracherai tes ashères du milieu de toi, et je détruirai tes villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Et j’exécuterai sur les nations, avec colère et avec fureur, une vengeance dont elles n’ont pas entendu parler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, '*Écoutez, je vous prie, ce que dit l’ Éternel: Lève-toi, plaide devant les montagnes, et que les collines entendent ta voix!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Écoutez, montagnes, le plaidoyer de l’ Éternel, et vous, fondements immuables de la terre; car l’ Éternel a un débat avec son peuple, et il conteste avec Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Mon peuple, que t’ai-je fait, et en quoi t’ai-je lassé? Réponds-moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Car je t’ai fait monter du pays d’Égypte, et je t’ai racheté de la maison de servitude; et j’ai envoyé devant toi Moïse, Aaron et Marie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mon peuple, souviens-toi, je te prie, du dessein que forma Balak, roi de Moab, et de ce que Balaam, fils de Béor, lui répondit, de Sittim jusqu’à Guilgal, afin que vous connaissiez la justice de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Avec quoi m’approcherai-je de l’ Éternel, m’inclinerai-je devant le Dieu d’en haut? M’approcherai-je de lui avec des holocaustes, avec des veaux âgés d’un an?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'L’ Éternel prendra-t-il plaisir à des milliers de béliers, à des myriades de torrents d’huile? Donnerai-je mon premier-né pour ma transgression, le fruit de mon ventre pour le péché de mon âme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Il t’a déclaré, ô homme, ce qui est bon. Et qu’est-ce que l’ Éternel recherche de ta part, sinon que tu fasses ce qui est droit, que tu aimes la bonté, et que tu marches humblement avec ton Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'La voix de l’ Éternel crie à la ville, et la sagesse a l’œil sur ton nom. Écoutez la verge et celui qui l’a décrétée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Y a-t-il encore des trésors de méchanceté dans la maison du méchant, et un épha petit, chose maudite?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Serai-je pur avec une balance inique et avec un sac de faux poids?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Parce que ses riches sont pleins de violence, et que ses habitants disent des mensonges, et que leur langue est fausse dans leur bouche:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'moi aussi, je te rendrai malade en te frappant, je te rendrai désolée à cause de tes péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Tu mangeras, et tu ne seras pas rassasiée, et ton ventre sera vide; et tu emporteras, mais tu ne sauveras pas; et ce que tu sauveras, je le livrerai à l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Tu sèmeras, et tu ne moissonneras pas; tu fouleras les olives, mais tu ne t’oindras pas d’huile, et le moût, mais tu ne boiras pas de vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Car on observe les statuts d’Omri et toutes les œuvres de la maison d’Achab; et vous marchez selon leurs conseils, afin que je fasse de toi une désolation, et de ses habitants un objet de sifflement; et vous porterez l’opprobre de mon peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Malheur à moi! car je suis comme quand on a fait la cueillette des fruits d’été, comme les grappillages lors de la vendange: pas une grappe de raisin à manger! aucun fruit précoce que mon âme désirait!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'L’homme pieux a disparu du pays, et il n’y a pas de gens droits parmi les hommes; tous ils se placent aux embûches pour [verser] le sang; ils font la chasse chacun à son frère avec un filet;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'les deux mains sont prêtes au mal, afin de le bien faire; le prince exige, et le juge [est là] pour une récompense, et le grand exprime l’avidité de son âme; et [ensemble] ils trament la chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Le meilleur d’entre eux est comme une ronce, le plus droit, pire qu’une haie d’épines. Le jour de tes sentinelles [et] de ta visitation est arrivé; maintenant sera leur confusion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'N’ayez pas de confiance en un compagnon; ne vous fiez pas à un ami; garde les portes de ta bouche devant celle qui couche dans ton sein.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Car le fils flétrit le père, la fille s’élève contre sa mère, la belle-fille contre sa belle-mère; les ennemis d’un homme sont les gens de sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Mais moi, je regarderai vers l’ Éternel, je m’attendrai au Dieu de mon salut; mon Dieu m’écoutera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Ne te réjouis pas sur moi, mon ennemie: si je tombe, je me relèverai; si je suis assise dans les ténèbres, l’ Éternel sera ma lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Je supporterai l’indignation de l’ Éternel, car j’ai péché contre lui, – jusqu’à ce qu’il prenne en main ma cause et me fasse droit: il me fera sortir à la lumière; je verrai sa justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Et mon ennemie [le] verra et la honte la couvrira, elle qui me disait: Où est l’ Éternel, ton Dieu? Mes yeux la verront; maintenant elle sera foulée comme la boue des rues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Au jour où tes murs doivent se bâtir, ce jour-là, la limite établie sera reculée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Ce jour-là, on viendra jusqu’à toi, depuis l’Assyrie et les villes de l’Égypte, et depuis l’Égypte jusqu’au fleuve, et de mer à mer, et de montagne en montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Mais le pays sera une désolation, à cause de ses habitants, pour le fruit de leurs actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Pais ton peuple avec ton bâton, le troupeau de ton héritage qui demeure seul dans la forêt, au milieu du Carmel; qu’ils paissent en Basan et en Galaad comme aux jours d’autrefois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Comme aux jours où tu sortis du pays d’Égypte, je lui ferai voir des choses merveilleuses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Les nations verront et seront confondues à cause de toute leur puissance; elles mettront la main sur la bouche, leurs oreilles seront sourdes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Elles lécheront la poussière comme le serpent; comme les bêtes rampantes de la terre, elles sortiront en tremblant de leurs lieux cachés; elles viendront avec frayeur vers l’ Éternel, notre Dieu, et elles te craindront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Qui est un ✶Dieu comme toi, pardonnant l’iniquité et passant par-dessus la transgression du reste de son héritage? Il ne gardera pas à perpétuité sa colère, parce qu’il prend son plaisir en la bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Il aura encore une fois compassion de nous, il mettra sous ses pieds nos iniquités; et tu jetteras tous leurs péchés dans les profondeurs de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Tu accompliras envers Jacob [ta] vérité, envers Abraham [ta] bonté, que tu as jurées à nos pères dès les jours d’autrefois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'L’oracle touchant Ninive; livre de la vision de Nahum, l’Elkoshite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'C’est un ✶Dieu jaloux et vengeur que l’ Éternel; l’ Éternel est vengeur et plein de furie; l’ Éternel tire vengeance de ses adversaires et garde sa colère contre ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'L’ Éternel est lent à la colère et grand en puissance, et il ne tiendra nullement [le coupable] pour innocent. L’ Éternel, – son chemin est dans le tourbillon et dans la tempête, et la nue est la poussière de ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Il tance la mer et la dessèche, et fait tarir toutes les rivières. Basan et le Carmel languissent, et la fleur du Liban languit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Les montagnes tremblent devant lui, et les collines se fondent; et devant sa face la terre se soulève, et le monde et tous ceux qui y habitent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Qui tiendra devant son indignation, et qui subsistera devant l’ardeur de sa colère? Sa fureur est versée comme le feu, et devant lui les rochers sont brisés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'L’ Éternel est bon, un lieu fort au jour de la détresse, et il connaît ceux qui se confient en lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'mais, par une inondation débordante, il détruira entièrement son lieu, et les ténèbres poursuivront ses ennemis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Qu’imaginez-vous contre l’ Éternel? Il détruira entièrement; la détresse ne se lèvera pas deux fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Quand même ils sont comme des ronces entrelacées, et comme ivres de leur vin, ils seront dévorés comme du chaume sec, entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'De toi est sorti celui qui imagine du mal contre l’ Éternel, un conseiller de Bélial.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Ainsi dit l’ Éternel: Qu’ ils soient intacts, et ainsi nombreux, ils seront retranchés et ne seront plus. Et si je t’ai affligé, je ne t’affligerai plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Et maintenant je briserai son joug de dessus toi, et je romprai tes liens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Et l’ Éternel a commandé à ton égard: on ne sèmera plus [de semence] de ton nom. De la maison de ton dieu je retrancherai l’image taillée et l’image de fonte, je préparerai ton sépulcre, car tu es vil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Voici sur les montagnes les pieds de celui qui apporte de bonnes nouvelles, de celui qui annonce la paix! Juda, célèbre tes fêtes, acquitte tes vœux; car le méchant ne passera plus par toi, il est entièrement retranché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, '*Celui qui brise est monté contre toi: garde la forteresse, surveille le chemin, fortifie tes reins, affermis beaucoup ta puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Car l’ Éternel a ramené la gloire de Jacob comme la gloire d’Israël; car ceux qui dépouillent les ont dépouillés et ont gâté leurs sarments.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Le bouclier de ses hommes forts est teint en rouge, les hommes vaillants sont vêtus d’écarlate, l’acier fait étinceler les chars, au jour où il se prépare, et les [lances de] cyprès sont brandies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Les chars s’élancent avec furie dans les rues, ils se précipitent sur les places; leur apparence est comme des torches, ils courent comme des éclairs. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Il pense à ses vaillants hommes: ils trébuchent dans leur marche, ils se hâtent vers la muraille, et l’abri est préparé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Les portes des fleuves sont ouvertes, et le palais s’effondre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'C’est arrêté: elle sera mise à nu, elle sera emmenée, et ses servantes gémiront comme la voix des colombes, en se frappant la poitrine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Or, dès le jour où elle exista, Ninive a été comme une mare d’eau. Mais ils fuient... Arrêtez! Arrêtez! Mais personne ne se retourne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Pillez l’argent, pillez l’or! Il n’y a pas de fin au splendide arroi de toute sorte d’objets d’agrément.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, '[Elle est] vidée, et dépouillée, et dévastée! Et le cœur se fond, et les genoux sont tremblants, et une poignante douleur est dans tous les reins, et tous les visages pâlissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Où est le repaire des lions, et le lieu où se repaissaient les lionceaux, où se promenaient le lion, la lionne, [et] le petit du lion, sans que personne les effraie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Le lion déchirait suffisamment pour ses petits, et étranglait pour ses lionnes, et remplissait de proie ses antres, et de bêtes déchirées ses repaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 14, 'Voici, j’en veux à toi, dit l’ Éternel des armées; et je réduirai tes chars en fumée; et l’épée dévorera tes lionceaux, et je retrancherai de la terre ta proie; et la voix de tes messagers ne s’entendra plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, '*Malheur à la ville de sang, toute pleine de fausseté [et] de violence! la rapine ne la quitte pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Bruit du fouet et fracas des roues, et galop des chevaux, et chars qui bondissent;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'le cavalier qui s’élance, et la flamme de l’épée, et l’éclair de la lance, et une multitude de tués, et des monceaux de corps morts, et des cadavres sans fin! on trébuche sur les cadavres!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'À cause de la multitude des prostitutions de la prostituée attrayante, enchanteresse, qui vend les nations par ses prostitutions, et les familles par ses enchantements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'voici, j’en veux à toi, dit l’ Éternel des armées, et je relèverai les pans de ta robe sur ton visage, et je montrerai aux nations ta nudité, et aux royaumes ta honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Et je jetterai sur toi des ordures, et je t’avilirai, et je te donnerai en spectacle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Et il arrivera que tous ceux qui te verront fuiront loin de toi, et diront: Ninive est dévastée! Qui la plaindra? D’où te chercherai-je des consolateurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Es-tu meilleure que No-Amon, qui habitait sur les canaux, des eaux autour d’elle, – elle qui avait la mer pour rempart, la mer pour sa muraille?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'L’Éthiopie était sa force, et l’Égypte, et il n’y avait pas de fin; Puth et les Libyens étaient parmi ceux qui l’aidaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Elle aussi fut emmenée et s’en alla en captivité; ses petits enfants aussi furent écrasés aux coins de toutes les rues; on jeta le sort sur ses hommes honorables, et tous ses grands furent liés de chaînes. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Toi aussi, tu seras enivrée; tu seras cachée; toi aussi, tu chercheras un lieu fort devant l’ennemi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Toutes tes forteresses sont [comme] des figuiers avec leurs premières figues; si on les secoue, elles tombent dans la bouche de celui qui les mange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Voici, ton peuple au-dedans de toi est [comme] des femmes; les portes de ton pays sont grandes ouvertes à tes ennemis, le feu dévore tes barres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Puise de l’eau pour le siège, fortifie tes lieux forts, entre dans la glaise et foule l’argile, répare le four à briques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Là, le feu te dévorera, l’épée te détruira; elle te dévorera comme l’yélek. Multiplie-toi comme l’yélek, multiplie-toi comme la sauterelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Tu as augmenté le nombre de tes marchands plus que les étoiles des cieux; l’yélek se répand, puis s’envole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Tes hommes d’élite sont comme les sauterelles, et tes capitaines sont comme une nuée de gobs qui campent dans les haies au frais du jour; le soleil se lève, ils s’envolent, et on ne connaît pas le lieu où ils sont.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Tes pasteurs dorment, roi d’Assyrie! tes vaillants hommes sont couchés là, ton peuple est dispersé sur les montagnes, et personne ne les rassemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Il n’y a pas de soulagement à ta blessure; ta plaie est très maligne; tous ceux qui entendent parler de toi battent des mains sur toi; car sur qui ta méchanceté n’a-t-elle pas continuellement passé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'L’oracle qu’a vu Habakuk, le prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Jusques à quand, Éternel, crierai-je, et tu n’entendras pas? Je crie à toi: Violence! et tu ne sauves pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Pourquoi me fais-tu voir l’iniquité, et contemples-tu l’oppression? La dévastation et la violence sont devant moi, et il y a contestation, et la discorde s’élève.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'C’est pourquoi la loi reste impuissante, et le juste jugement ne vient jamais au jour; car le méchant cerne le juste; c’est pourquoi le jugement sort perverti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Voyez parmi les nations, et regardez, et soyez stupéfaits; car je ferai en vos jours une œuvre que vous ne croirez pas, si elle [vous] est racontée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Car voici, je suscite les Chaldéens, la nation cruelle et impétueuse, qui marche par la largeur de la terre pour prendre possession de domiciles qui ne lui appartiennent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Elle est formidable et terrible; son jugement et sa dignité procèdent d’elle-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Ses chevaux sont plus rapides que les léopards, plus agiles que les loups du soir; et ses cavaliers s’élancent fièrement, et ses cavaliers viennent de loin: ils volent comme l’aigle se hâte pour dévorer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Ils viennent tous pour la violence; leurs faces sont toutes ensemble tournées en avant; ils rassemblent les captifs comme le sable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Et il se moque des rois, et les princes lui sont une risée; il se rit de toutes les forteresses: il entassera de la poussière et les prendra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Alors il changera de pensée, et passera outre et péchera: cette puissance qu’il a, est devenue son ✝dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, '– Toi, n’es-tu pas de toute ancienneté, Éternel, mon Dieu, mon Saint? Nous ne mourrons pas! Ô Éternel, tu l’as établi pour le jugement, et tu l’as fondé, ô Rocher, pour châtier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Tu as les yeux trop purs pour voir le mal, et tu ne peux contempler l’oppression. Pourquoi contemples-tu ceux qui agissent perfidement, [et] gardes-tu le silence quand le méchant engloutit celui qui est plus juste que lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Tu rends aussi les hommes comme les poissons de la mer, comme la bête rampante qui n’a personne qui la gouverne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Il les fait tous monter avec l’hameçon; il les tire dans son filet, et les rassemble dans son rets; c’est pourquoi il se réjouit et s’égaie:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'c’est pourquoi il sacrifie à son filet, et brûle de l’encens à son rets, parce que, par leur moyen, sa portion est grasse et sa nourriture succulente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Videra-t-il pour cela son filet, et égorgera-t-il toujours les nations, sans épargner?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, '*Je me placerai en observation et je me tiendrai sur la tour, et je veillerai pour voir ce qu’il me dira, et ce que je répliquerai quand il contestera avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Et l’ Éternel me répondit et dit: Écris la vision et grave-la sur des tablettes, afin que celui qui la lit puisse courir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Car la vision est encore pour un temps déterminé, et elle parle de la fin, et ne mentira pas. Si elle tarde, attends-la, car elle viendra sûrement, elle ne sera pas différée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Voici, son âme enflée d’orgueil n’est pas droite en lui; mais le juste vivra par sa foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Et bien plus, le vin est perfide; [cet] homme est arrogant et ne se tient pas tranquille, lui qui élargit son désir comme le shéol, et est comme la mort, et ne peut être rassasié; et il rassemble vers lui toutes les nations, et recueille vers lui tous les peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Tous ceux-ci ne proféreront-ils pas sur lui un proverbe, et une allégorie [et] des énigmes contre lui? Et ils diront: Malheur à qui accumule ce qui n’est pas à lui:... jusques à quand? – et qui se charge d’un fardeau de gages!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Ne se lèveront-ils pas subitement, ceux qui te mordront? et ne s’éveilleront-ils pas, ceux qui te tourmenteront? et tu seras leur proie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Car tu as pillé beaucoup de nations, [et] tout le reste des peuples te pillera, à cause du sang des hommes et de la violence [faite] au pays, à la ville, et à tous ceux qui y habitent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Malheur à qui fait un gain inique pour sa maison, afin de placer haut son nid, pour échapper à la main du malheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Tu as pris conseil pour [couvrir de] honte ta maison, pour détruire beaucoup de peuples, et tu as péché contre ta propre âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Car de la muraille, la pierre crie, et de la charpente, le chevron répond!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Malheur à celui qui bâtit une ville avec du sang et qui établit une cité sur l’iniquité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Voici, n’est-ce pas de par l’ Éternel des armées que les peuples travaillent pour le feu, et que les peuplades se lassent pour néant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Car la terre sera pleine de la connaissance de la gloire de l’ Éternel, comme les eaux couvrent [le fond de] la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Malheur à celui qui donne à boire à son prochain, – à toi qui verses ton outre, et qui aussi enivres, afin que tu regardes leur nudité!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Tu t’es rassasié d’ignominie plus que de gloire; bois, toi aussi, et découvre ton incirconcision! La coupe de la droite de l’ Éternel s’est tournée vers toi, et il y aura un honteux vomissement sur ta gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Car la violence [faite] au Liban te couvrira, et la destruction qui effraya les bêtes, à cause du sang des hommes, et de la violence [faite] au pays, à la ville et à tous ceux qui y habitent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'De quel profit est l’image taillée, que l’ouvrier l’ait taillée? [À quoi sert] l’image de fonte, enseignant le mensonge, pour que l’ouvrier se confie en sa propre œuvre pour faire des idoles muettes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Malheur à celui qui dit au bois: Réveille-toi! – à la pierre muette: Lève-toi! Elle, elle enseignerait? Voici, elle est plaquée d’or et d’argent, et il n’y a aucun souffle au-dedans d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'L’ Éternel est dans le palais de sa sainteté:... que toute la terre fasse silence devant lui!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, '*Prière de Habakuk, le prophète. Sur Shiguionoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Ô Éternel, j’ai entendu ce que tu as déclaré, [et] j’ai eu peur. Éternel, ravive ton œuvre au milieu des années; au milieu des années, fais-la connaître. Dans la colère, souviens-toi de la miséricorde!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, '✝Dieu vint de Théman, et le Saint, de la montagne de Paran. Sélah. Sa magnificence couvre les cieux, et sa louange remplit la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Et sa splendeur était comme la lumière: des rayons lui jaillissaient de la main; et là se cachait sa force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'La peste marchait devant lui, et une flamme ardente sortait sous ses pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Il se tint là et mesura la terre, il regarda et mit en déroute les nations; Et les montagnes antiques furent brisées en éclats, les collines éternelles s’affaissèrent. Ses voies sont éternelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Je vis les tentes de Cushan dans l’affliction; les tentures du pays de Madian tremblèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Est-ce contre les rivières que s’irrita l’ Éternel? ou contre les rivières que fut ta colère? contre la mer, ta fureur, que tu sois monté sur tes chevaux, [sur] tes chars de salut?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Ton arc était mis à nu,... les verges [de jugement] jurées par [ta] parole. Sélah. Tu fendis la terre par des rivières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Les montagnes te virent, elles tremblèrent; des torrents d’eau passèrent, l’abîme fit retentir sa voix; il leva ses mains en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Le soleil, la lune, s’arrêtèrent dans leur demeure à la lumière de tes flèches qui volaient, à la splendeur de l’éclair de ta lance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Tu parcourus le pays avec indignation, tu foulas les nations avec colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Tu sortis pour le salut de ton peuple, pour le salut de ton oint; tu brisas le faîte de la maison du méchant, mettant à nu les fondements jusqu’au cou. Sélah.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Tu transperças de ses propres traits la tête de ses chefs: ils arrivaient comme un tourbillon pour me disperser, leur joie était comme de dévorer l’affligé en secret.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Tu traversas la mer avec tes chevaux, l’amas de grandes eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'J’entendis, et mes entrailles tremblèrent; à la voix [que j’entendis] mes lèvres frémirent, la pourriture entra dans mes os, et je tremblai sous moi-même, pour que j’aie du repos au jour de la détresse, quand montera contre le peuple celui qui l’assaillira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Car le figuier ne fleurira pas, et il n’y aura point de produit dans les vignes; le travail de l’olivier mentira, et les campagnes ne produiront pas de nourriture; les brebis manqueront dans le parc, et il n’y aura pas de bœufs dans les étables;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Mais moi, je me réjouirai en l’ Éternel, je m’égaierai dans le Dieu de mon salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'L’ Éternel, le Seigneur, est ma force; il rendra mes pieds pareils à ceux des biches, et il me fera marcher sur mes lieux élevés. Au chef de musique. Sur Neguinoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'La parole de l’ Éternel qui vint à Sophonie, fils de Cushi, fils de Guedalia, fils d’Amaria, fils d’Ézéchias, dans les jours de Josias, fils d’Amon, roi de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'J’ôterai, j’enlèverai tout de dessus la face de la terre, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Je détruirai les hommes et les bêtes, je détruirai les oiseaux des cieux et les poissons de la mer, et les pierres d’achoppement avec les méchants, et je retrancherai l’homme de dessus la face de la terre, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Et j’étendrai ma main sur Juda et sur tous les habitants de Jérusalem; et je retrancherai de ce lieu le reste de Baal et le nom des Camarim avec les sacrificateurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'et ceux qui se prosternent sur les toits devant l’armée des cieux, et ceux qui se prosternent devant l’ Éternel, qui jurent par [lui] et qui jurent par leur roi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'et ceux qui se détournent de l’ Éternel, et ceux qui ne cherchent pas l’ Éternel et ne s’enquièrent pas de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Fais silence, devant le Seigneur, l’ Éternel! car le jour de l’ Éternel est proche; car l’ Éternel a préparé un sacrifice, il a sanctifié ses conviés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Et il arrivera, au jour du sacrifice de l’ Éternel, que je punirai les princes et les fils du roi, et tous ceux qui se vêtent de vêtements étrangers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Et je punirai, en ce jour-là, tous ceux qui sautent par-dessus le seuil, ceux qui remplissent la maison de leur seigneur de violence et de fraude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Et il y aura, en ce jour-là, dit l’ Éternel, le bruit d’un cri [venant] de la porte des poissons, et un hurlement [venant] du second [quartier de la ville], et un grand fracas [venant] des collines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Hurlez, habitants de Mactesh, car tout le peuple de Canaan sera détruit, tous ceux qui sont chargés d’argent seront exterminés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Et il arrivera, en ce temps-là, que je fouillerai Jérusalem avec des lampes; et je punirai les hommes qui reposent sur leurs lies, – qui disent dans leur cœur: L’ Éternel ne fera ni bien ni mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Et leurs biens deviendront une proie, et leurs maisons, une désolation, et ils bâtiront des maisons et ne les habiteront pas, et ils planteront des vignes et n’en boiront pas le vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Le grand jour de l’ Éternel est proche; il est proche et se hâte beaucoup. La voix du jour de l’ Éternel: l’homme vaillant poussera là des cris amers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Ce jour est un jour de fureur, un jour de détresse et d’angoisse, un jour de dévastation et de ruine, un jour de ténèbres et d’obscurité, un jour de nuées et d’épaisses ténèbres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'un jour de trompette et de retentissement contre les villes fortifiées et contre les créneaux élevés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Et je ferai venir la détresse sur les hommes, et ils marcheront comme des aveugles; car ils ont péché contre l’ Éternel; et leur sang sera répandu comme de la poussière, et leur chair comme de la fiente;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'leur argent ni leur or ne pourra les délivrer au jour de la fureur de l’ Éternel; et par le feu de sa jalousie tout le pays sera dévoré, car il consumera, oui, il détruira subitement tous les habitants du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Assemblez-vous, rassemblez-vous, nation sans honte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'avant que le décret enfante, [avant que] le jour passe comme la balle, avant que vienne sur vous l’ardeur de la colère de l’ Éternel, avant que vienne sur vous le jour de la colère de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Cherchez l’ Éternel, vous, tous les débonnaires du pays, qui pratiquez ce qui est juste à ses yeux; recherchez la justice, recherchez la débonnaireté; peut-être serez-vous à couvert au jour de la colère de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Car Gaza sera abandonnée, et Askalon sera une désolation; Asdod, on la chassera en plein midi, et Ékron sera déracinée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Malheur à ceux qui habitent les côtes de la mer, la nation des Keréthiens: la parole de l’ Éternel est contre vous, Canaan, pays des Philistins! et je te détruirai, de sorte qu’il n’y aura pas d’habitant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Et les côtes de la mer seront des excavations pour les bergers, et des enclos pour le menu bétail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Et les côtes seront pour le résidu de la maison de Juda: ils y paîtront; le soir, ils se coucheront dans les maisons d’Askalon; car l’ Éternel, leur Dieu, les visitera, et rétablira leurs captifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'J’ai entendu l’outrage de Moab et les insultes des fils d’Ammon, par lesquels ils ont outragé mon peuple et se sont élevés orgueilleusement contre leur frontière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'C’est pourquoi, je suis vivant, dit l’ Éternel des armées, le Dieu d’Israël, que Moab sera comme Sodome, et les fils d’Ammon comme Gomorrhe, un lieu couvert d’orties, et des carrières de sel, et une désolation, à toujours. Le résidu de mon peuple les pillera, et le reste de ma nation les héritera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Voilà ce qu’ils auront pour leur orgueil, car ils ont outragé le peuple de l’ Éternel des armées et se sont exaltés contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'L’ Éternel sera terrible contre eux, car il affamera tous les dieux de la terre, et toutes les îles des nations se prosterneront devant lui, chacun du lieu où il est.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Vous aussi, Éthiopiens, vous aussi, vous serez tués par mon épée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Et il étendra sa main vers le nord, et il détruira l’Assyrie, et il changera Ninive en désolation, en un lieu aride comme un désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Et les troupeaux se coucheront au milieu d’elle, toutes les bêtes, en foule; le pélican aussi, et le butor, passeront la nuit sur ses chapiteaux; il y aura la voix [des oiseaux] qui chantent aux fenêtres, la désolation sera sur le seuil; car il a mis à nu les [lambris] de cèdre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'C’est là cette ville qui s’égayait, qui habitait en sécurité, qui disait en son cœur: Moi, et à part moi, nulle autre! Comment est-elle devenue une désolation, un gîte pour les bêtes? Quiconque passera à côté d’elle sifflera, [et] secouera sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Malheur à la rebelle, à la corrompue, à la ville qui opprime!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Elle n’écoute pas la voix, elle ne reçoit pas l’instruction, elle ne se confie pas en l’ Éternel, elle ne s’approche pas de son Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Ses princes au milieu d’elle sont des lions rugissants; ses juges, des loups du soir: ils ne laissent rien jusqu’au matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Ses prophètes sont des vantards, des hommes perfides; ses sacrificateurs profanent le lieu saint, ils font violence à la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'L’ Éternel juste est au milieu d’elle; il ne commet pas l’iniquité; chaque matin il met en lumière son juste jugement; il ne fait pas défaut; mais l’inique ne connaît pas la honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'J’ai retranché des nations, leurs créneaux sont dévastés; j’ai rendu désolées leurs rues, de sorte que personne n’y passe; leurs villes sont ravagées, de sorte qu’il n’y a plus d’homme, point d’habitant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'J’ai dit: Crains-moi seulement, reçois l’instruction; et sa demeure ne sera pas retranchée, quelle que soit la punition que je lui inflige. Mais ils se sont levés de bonne heure [et] ont corrompu toutes leurs actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'C’est pourquoi, attendez-moi, dit l’ Éternel, pour le jour où je me lèverai pour le butin. Car ma détermination c’est de rassembler les nations, de réunir les royaumes pour verser sur eux mon indignation, toute l’ardeur de ma colère; car toute la terre sera dévorée par le feu de ma jalousie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Car alors, je changerai la [langue] des peuples en une langue purifiée, pour qu’ils invoquent tous le nom de l’ Éternel pour le servir d’un seul cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'D’au-delà des fleuves de l’Éthiopie, mes suppliants, la fille de mes dispersés, apporteront mon offrande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'En ce jour-là, tu ne seras pas honteuse à cause de toutes tes actions par lesquelles tu t’es rebellée contre moi; car alors, j’ôterai du milieu de toi ceux qui s’égaient en ton orgueil, et tu ne seras plus hautaine à cause de ma montagne sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Et je laisserai au milieu de toi un peuple affligé et abaissé, et ils se confieront au nom de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Le résidu d’Israël ne pratiquera pas l’iniquité, et ne dira pas de mensonge, et une langue trompeuse ne se trouvera pas dans leur bouche; car ils paîtront et se coucheront, et il n’y aura personne qui les effraie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Exulte, fille de Sion; pousse des cris, Israël! Réjouis-toi et égaie-toi de tout ton cœur, fille de Jérusalem!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'L’ Éternel a éloigné tes jugements, il a écarté ton ennemi. Le roi d’Israël, l’ Éternel, est au milieu de toi: tu ne verras plus le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'En ce jour-là, il sera dit à Jérusalem: Ne crains pas! Sion, que tes mains ne soient pas lâches!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'L’ Éternel, ton Dieu, au milieu de toi, est puissant; il sauvera; il se réjouira avec joie à ton sujet: il se reposera dans son amour, il s’égaiera en toi avec chant de triomphe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Je rassemblerai ceux qui se lamentent à cause des assemblées solennelles; ils étaient de toi; sur eux pesait l’opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Voici, en ce temps-là, j’agirai à l’égard de tous ceux qui t’affligent, et je sauverai celle qui boitait, et je recueillerai celle qui était chassée, et je ferai d’elles une louange et un nom dans tous les pays où elles étaient couvertes de honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'En ce temps-là, je vous amènerai, dans ce même temps où je vous rassemblerai, car je ferai de vous un nom et une louange parmi tous les peuples de la terre, quand je rétablirai vos captifs, devant vos yeux, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'La seconde année du roi Darius, au sixième mois, le premier jour du mois, la parole de l’ Éternel vint par Aggée, le prophète, à Zorobabel, fils de Shealthiel, gouverneur de Juda, et à Joshua, fils de Jotsadak, le grand sacrificateur, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Ainsi parle l’ Éternel des armées, disant: Ce peuple dit: Le temps n’est pas venu, le temps de la maison de l’ Éternel, pour [la] bâtir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Et la parole de l’ Éternel vint par Aggée le prophète, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Est-ce le temps pour vous d’habiter dans vos maisons lambrissées, tandis que cette maison est dévastée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Et maintenant, ainsi dit l’ Éternel des armées: Considérez bien vos voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Vous avez semé beaucoup, et vous rentrez peu; vous mangez, mais vous n’êtes pas rassasiés; vous buvez, mais vous n’en avez pas assez; vous vous vêtez, mais personne n’a chaud; et celui qui travaille pour des gages, travaille pour [les mettre dans] une bourse trouée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Ainsi dit l’ Éternel des armées: Considérez bien vos voies:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Montez à la montagne et apportez du bois, et bâtissez la maison; et j’y prendrai plaisir, et je serai glorifié, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Vous vous attendiez à beaucoup, et voici, ce n’a été que peu; et vous l’avez apporté à la maison, et j’ai soufflé dessus. Pourquoi? dit l’ Éternel des armées. À cause de ma maison, qui est dévastée, – et vous courez chacun à sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'C’est pourquoi au-dessus de vous les cieux ont retenu la rosée, et la terre a retenu son produit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'et j’ai appelé une sécheresse sur la terre, et sur les montagnes, et sur le blé, et sur le moût, et sur l’huile, et sur ce que le sol rapporte, et sur les hommes et sur les bêtes, et sur tout le travail des mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Et Zorobabel, fils de Shealthiel, et Joshua, fils de Jotsadak, le grand sacrificateur, et tout le reste du peuple, écoutèrent la voix de l’ Éternel, leur Dieu, et les paroles d’Aggée le prophète, selon la mission que lui avait donnée l’ Éternel, leur Dieu; et le peuple craignit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Et Aggée, le messager de l’ Éternel, parla au peuple par le message de l’ Éternel, disant: Je suis avec vous, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Et l’ Éternel réveilla l’esprit de Zorobabel, fils de Shealthiel, gouverneur de Juda, et l’esprit de Joshua, fils de Jotsadak, le grand sacrificateur, et l’esprit de tout le reste du peuple; et ils vinrent et travaillèrent à la maison de l’ Éternel des armées, leur Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'le vingt-quatrième jour du sixième mois, en la seconde année du roi Darius.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, '*Au septième [mois], le vingt et unième [jour] du mois, la parole de l’ Éternel vint par Aggée le prophète, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Parle à Zorobabel, fils de Shealthiel, gouverneur de Juda, et à Joshua, fils de Jotsadak, le grand sacrificateur, et au reste du peuple, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Qui est de reste parmi vous qui ait vu cette maison dans sa première gloire, et comment la voyez-vous maintenant? N’est-elle pas comme rien à vos yeux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Mais maintenant, sois fort, Zorobabel, dit l’ Éternel, et sois fort, Joshua, fils de Jotsadak, grand sacrificateur, et soyez forts, vous, tout le peuple du pays, dit l’ Éternel, et travaillez; car je suis avec vous, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'La parole [selon laquelle] j’ai fait alliance avec vous, lorsque vous êtes sortis d’Égypte, et mon Esprit, demeurent au milieu de vous; ne craignez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Car, ainsi dit l’ Éternel des armées: Encore une fois, ce sera dans peu de temps, et j’ébranlerai les cieux et la terre, et la mer et la terre sèche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'et j’ébranlerai toutes les nations. Et l’objet du désir de toutes les nations viendra, et je remplirai cette maison de gloire, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'L’argent est à moi, et l’or est à moi, dit l’ Éternel des armées:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'la dernière gloire de cette maison sera plus grande que la première, dit l’ Éternel des armées, et dans ce lieu, je donnerai la paix, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Le vingt-quatrième [jour] du neuvième [mois], dans la seconde année de Darius, la parole de l’ Éternel vint par Aggée le prophète, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Ainsi dit l’ Éternel des armées: Interroge les sacrificateurs sur la loi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Si un homme porte de la chair sainte dans le pan de sa robe, et qu’il touche avec le pan de sa robe du pain, ou quelque mets, ou du vin, ou de l’huile, ou quoi que ce soit qu’on mange, [ce qu’il a touché] sera-t-il sanctifié? Et les sacrificateurs répondirent et dirent: Non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Et Aggée dit: Si un homme qui est impur par un corps [mort] touche quelqu’une de toutes ces choses, est-elle devenue impure? Et les sacrificateurs répondirent et dirent: Elle est impure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Et Aggée répondit et dit: Ainsi est ce peuple, et ainsi est cette nation devant moi, dit l’ Éternel, et ainsi est toute l’œuvre de leurs mains, et ce qu’ils présentent là est impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Et maintenant, considérez bien, je vous prie, [ce qui va arriver] dès ce jour et dorénavant: avant qu’on ait mis pierre sur pierre au temple de l’ Éternel, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'avant que ces [jours] soient, si l’on venait à un tas de 20 [boisseaux], il y en avait dix; si l’on venait à la cuve pour puiser 50 mesures, il y en avait 20;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'je vous ai frappés par la brûlure et la rouille et la grêle, [dans] toute l’œuvre de vos mains, et aucun de vous [n’est revenu] à moi, dit l’ Éternel:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'considérez-le bien, je vous prie, dès ce jour et dorénavant, depuis le vingt-quatrième jour du neuvième [mois], depuis le jour où le temple de l’ Éternel a été fondé; considérez-le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'La semence est-elle encore dans le grenier? Même la vigne, et le figuier, et le grenadier, et l’olivier, n’ont pas porté de fruit. Dès ce jour-ci, je bénirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Et la parole de l’ Éternel vint à Aggée, pour la seconde fois, le vingt-quatrième [jour] du mois, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Parle à Zorobabel, gouverneur de Juda, disant: J’ébranlerai les cieux et la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'je renverserai le trône des royaumes, et je détruirai la puissance des royaumes des nations, et je renverserai les chars et ceux qui les montent; et les chevaux seront abattus, et ceux qui les montent, chacun par l’épée de son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'En ce jour-là, dit l’ Éternel des armées, je te prendrai, Zorobabel, fils de Shealthiel, mon serviteur, dit l’ Éternel, et je te mettrai comme un cachet; car je t’ai choisi, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Au huitième mois, en la seconde année de Darius, la parole de l’ Éternel vint à Zacharie le prophète, fils de Bérékia, fils d’Iddo, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'L’ Éternel a été fort en courroux contre vos pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Et tu leur diras: Ainsi dit l’ Éternel des armées: Revenez à moi, dit l’ Éternel des armées, et je reviendrai à vous, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Ne soyez pas comme vos pères, auxquels les premiers prophètes ont crié, disant: Ainsi dit l’ Éternel des armées: Revenez donc de vos mauvaises voies et de vos mauvaises actions!... mais ils n’écoutèrent pas, et ne firent pas attention à moi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Vos pères, où sont-ils? et les prophètes, ont-ils vécu à toujours?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Mais mes paroles et mes décrets que j’ai commandés à mes serviteurs les prophètes, n’ont-ils pas atteint vos pères? Et ils sont revenus et ont dit: Comme l’ Éternel des armées s’est proposé de nous faire, selon nos voies et selon nos actions, ainsi en a-t-il fait à notre égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Le vingt-quatrième jour du onzième mois, qui est le mois de Shebath, en la seconde année de Darius, la parole de l’ Éternel vint à Zacharie le prophète, fils de Bérékia, fils d’Iddo, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Je vis de nuit; et voici un homme monté sur un cheval roux, et il se tenait parmi les myrtes qui étaient dans le fond, et, après lui, il y avait des chevaux roux, bais, et blancs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Et je dis: Que sont ceux-ci, mon seigneur? Et l’ange qui parlait avec moi me dit: Je te ferai voir ce que sont ceux-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Et l’homme qui se tenait parmi les myrtes répondit et dit: Ce sont ceux que l’ Éternel a envoyés pour se promener par la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Et ils répondirent à l’ange de l’ Éternel qui se tenait parmi les myrtes, et dirent: Nous nous sommes promenés par la terre, et voici, toute la terre est en repos et tranquille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Et l’ange de l’ Éternel prit la parole et dit: Éternel des armées, jusques à quand n’useras-tu pas de miséricorde envers Jérusalem, et envers les villes de Juda, contre lesquelles tu as été indigné ces 70 ans?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Et l’ Éternel répondit à l’ange qui parlait avec moi, de bonnes paroles, des paroles de consolation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Et l’ange qui parlait avec moi me dit: Crie, disant: Ainsi dit l’ Éternel des armées: Je suis jaloux d’une grande jalousie à l’égard de Jérusalem et à l’égard de Sion;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'et je suis courroucé d’un grand courroux contre les nations qui sont à leur aise; car j’étais un peu courroucé, et elles ont aidé au mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'C’est pourquoi, ainsi dit l’ Éternel: Je suis revenu à Jérusalem avec miséricorde; ma maison y sera bâtie, dit l’ Éternel des armées, et le cordeau sera étendu sur Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Crie encore, disant: Ainsi dit l’ Éternel des armées: Mes villes regorgeront encore de biens, et l’ Éternel consolera encore Sion, et choisira encore Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Et je levai mes yeux et regardai; et voici quatre cornes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Et je dis à l’ange qui parlait avec moi: Que sont celles-ci? Et il me dit: Ce sont ici les cornes qui ont dispersé Juda, Israël et Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Et l’ Éternel me fit voir quatre ouvriers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Et je dis: Que viennent faire ceux-ci? Et il parla, disant: Ce sont là les cornes qui ont dispersé Juda, de manière que personne ne levait la tête; mais ceux-ci sont venus pour les effrayer, pour jeter loin les cornes des nations qui ont levé la corne contre le pays de Juda pour le disperser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Et je levai les yeux, et je regardai; et voici un homme, et dans sa main un cordeau à mesurer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Et je dis: Où vas-tu? Et il me dit: [Je vais] pour mesurer Jérusalem, pour voir quelle est sa largeur et quelle est sa longueur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Et voici, l’ange qui parlait avec moi sortit, et un autre ange sortit à sa rencontre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'et lui dit: Cours, parle à ce jeune homme, disant: Jérusalem sera habitée comme les villes ouvertes, à cause de la multitude des hommes et du bétail [qui seront] au milieu d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Et moi, je lui serai, dit l’ Éternel, une muraille de feu tout autour, et je serai [sa] gloire au milieu d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Ho, Ho! fuyez donc du pays du nord, dit l’ Éternel, car je vous ai dispersés aux quatre vents des cieux, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Ho! échappe-toi, Sion, toi qui habites chez la fille de Babylone!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Car ainsi dit l’ Éternel des armées: Après la gloire, il m’a envoyé vers les nations qui ont fait de vous leur proie; car celui qui vous touche, touche la prunelle de son œil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Car voici, je secoue ma main sur elles, et elles seront la proie de ceux qui les servaient; et vous saurez que l’ Éternel des armées m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 14, 'Exulte, et réjouis-toi, fille de Sion! car voici, je viens et je demeurerai au milieu de toi, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 15, 'Et beaucoup de nations se joindront à l’ Éternel en ce jour-là, et elles me seront pour peuple, et je demeurerai au milieu de toi; et tu sauras que l’ Éternel des armées m’a envoyé à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 16, 'Et l’ Éternel possédera Juda [comme] sa part sur la terre sainte, et il choisira encore Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 17, 'Que toute chair fasse silence devant l’ Éternel, car il s’est réveillé de sa demeure sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, '*Et il me fit voir Joshua, le grand sacrificateur, debout devant l’Ange de l’ Éternel, et Satan se tenant à sa droite pour s’opposer à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Et l’ Éternel dit à Satan: Que l’ Éternel te tance, Satan; que l’ Éternel, qui a choisi Jérusalem, te tance! Celui-ci n’est-il pas un tison sauvé du feu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Et Joshua était vêtu de vêtements sales, et se tenait devant l’Ange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Et [l’Ange] prit la parole et parla à ceux qui se tenaient devant lui, disant: Ôtez de dessus lui les vêtements sales. Et il lui dit: Regarde, j’ai fait passer de dessus toi ton iniquité, et je te revêts d’habits de fête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Et je dis: Qu’ils mettent une tiare pure sur sa tête; et ils mirent la tiare pure sur sa tête, et le revêtirent de vêtements; et l’Ange de l’ Éternel se tenait là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Et l’Ange de l’ Éternel protesta à Joshua, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Ainsi dit l’ Éternel des armées: Si tu marches dans mes voies, et si tu fais l’acquit de la charge que je te confie, alors tu jugeras aussi ma maison, et tu auras aussi la garde de mes parvis, et je te donnerai de marcher au milieu de ceux-ci qui se tiennent [devant moi].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Écoute, Joshua, grand sacrificateur, toi et tes compagnons qui sont assis devant toi, car ce sont des hommes [qui servent] de signes; car voici, je ferai venir mon serviteur, le Germe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Car voici, la pierre que j’ai placée devant Joshua; sur cette seule pierre, [il y aura] sept yeux; voici, j’en graverai la gravure, dit l’ Éternel des armées; et j’ôterai l’iniquité de ce pays en un seul jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'En ce jour-là, dit l’ Éternel des armées, vous convierez chacun son prochain sous la vigne et sous le figuier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, '*Et l’ange qui parlait avec moi revint et me réveilla comme un homme qu’on réveille de son sommeil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Et il me dit: Que vois-tu? Et je dis: Je vois, et voici un chandelier tout d’or, et une coupe à son sommet; et ses sept lampes sur lui; sept [lampes] et sept conduits pour les lampes qui sont à son sommet;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'et deux oliviers auprès de lui, l’un à la droite de la coupe, et l’autre à sa gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Et je pris la parole et dis à l’ange qui parlait avec moi, disant: Que sont ces choses, mon seigneur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Et l’ange qui parlait avec moi répondit et me dit: Ne sais-tu pas ce que sont ces choses? Et je dis: Non, mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Et il répondit et me parla, disant: C’est ici la parole de l’ Éternel à Zorobabel, disant: Ni par force, ni par puissance, mais par mon Esprit, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Qui es-tu, grande montagne, devant Zorobabel? [Tu deviendras] une plaine; et il fera sortir la pierre du faîte avec des acclamations: Grâce, grâce sur elle!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Les mains de Zorobabel ont fondé cette maison, et ses mains l’achèveront; et tu sauras que l’ Éternel des armées m’a envoyé vers vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Car qui a méprisé le jour des petites choses? Ils se réjouiront, ces sept-là, et verront le plomb dans la main de Zorobabel: ce sont là les yeux de l’ Éternel qui parcourent toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Et je répondis et lui dis: Que sont ces deux oliviers à la droite du chandelier, et à sa gauche?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Et je répondis une seconde fois et lui dis: Que sont les deux branches des oliviers qui, à côté des deux conduits d’or, déversent l’or d’elles-mêmes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Et il me parla, disant: Ne sais-tu pas ce qu’elles sont? Et je dis: Non, mon seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Et il dit: Ce sont les deux fils de l’huile, qui se tiennent auprès du Seigneur de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, '*Et de nouveau je levai mes yeux, et je vis; et voici un rouleau qui volait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Et il me dit: Que vois-tu? Et je dis: Je vois un rouleau qui vole, long de 20 coudées, et large de dix coudées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Et il me dit: C’est ici la malédiction qui sort sur la face de toute la terre; car tout voleur sera détruit, selon ce [qui est écrit], d’une part; et chacun qui jure sera détruit, selon ce [qui est écrit], de l’autre part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Je la fais sortir, dit l’ Éternel des armées, et elle entrera dans la maison du voleur, et dans la maison de celui qui jure faussement par mon nom; et elle logera au milieu de sa maison et la consumera avec le bois et les pierres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Et l’ange qui parlait avec moi sortit et me dit: Lève tes yeux et regarde: Qu’est-ce qui sort là?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Et je dis: Qu’est-ce? Et il dit: C’est l’épha qui sort. Et il dit: C’est ici leur aspect dans toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Et voici, un disque de plomb fut soulevé: et il y avait là une femme assise au milieu de l’épha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Et il dit: C’est la méchanceté. Et il la jeta au milieu de l’épha, et il jeta le poids de plomb sur l’ouverture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Et je levai mes yeux, et je vis; et voici, deux femmes sortirent, et le vent était dans leurs ailes, et elles avaient des ailes comme des ailes de cigogne, et elles soulevèrent l’épha entre la terre et les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Et je dis à l’ange qui parlait avec moi: Où celles-ci emportent-elles l’épha?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Et il me dit: Pour lui bâtir une maison dans le pays de Shinhar; et là elle sera fixée et posée sur sa base.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, '*Et de nouveau je levai mes yeux, et je vis: et voici quatre chars qui sortaient d’entre deux montagnes, et les montagnes étaient des montagnes d’airain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Au premier char il y avait des chevaux roux; et au second char, des chevaux noirs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'et au troisième char, des chevaux blancs; et au quatrième char, des chevaux tachetés, vigoureux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Et je pris la parole et dis à l’ange qui parlait avec moi: Que sont ceux-ci, mon seigneur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Et l’ange répondit et me dit: Ce sont les quatre esprits des cieux qui sortent de là où ils se tenaient devant le Seigneur de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Celui auquel sont les chevaux noirs sort vers le pays du nord; et les blancs sortent après eux; et les tachetés sortent vers le pays du midi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'et les vigoureux sortent et cherchent à s’en aller, à se promener par la terre. Et il dit: Allez, promenez-vous par la terre. Et ils se promenèrent par la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Et il me cria, et me parla, disant: Vois; ceux qui sont sortis vers le pays du nord ont apaisé mon esprit dans le pays du nord.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Et la parole de l’ Éternel vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Prends de la part de [ceux de] la transportation, de la part de Heldaï, de Tobija, et de Jedahia, (et viens, toi, en ce même jour, et entre dans la maison de Josias, fils de Sophonie, où ils sont venus de Babylone);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'tu prendras, [dis-je] de l’argent et de l’or, oui, prends des couronnes, et tu [les] mettras sur la tête de Joshua, fils de Jotsadak, le grand sacrificateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'et tu lui parleras, disant: Ainsi parle l’ Éternel des armées, disant: Voici un homme dont le nom est Germe, et il germera de son propre lieu, et il bâtira le temple de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Lui, il bâtira le temple de l’ Éternel, et il portera la gloire, et il s’assiéra, et dominera sur son trône, et il sera sacrificateur sur son trône; et le conseil de paix sera entre eux deux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Et les couronnes seront pour Hélem, et pour Tobija, et pour Jedahia, et pour Hen, fils de Sophonie, pour mémorial dans le temple de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Et ceux qui sont éloignés viendront et bâtiront au temple de l’ Éternel; et vous saurez que l’ Éternel des armées m’a envoyé vers vous. Et [cela] arrivera, si vous écoutez fidèlement la voix de l’ Éternel, votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, '**Et il arriva, la quatrième année du roi Darius, que la parole de l’ Éternel vint à Zacharie, le quatrième [jour] du neuvième mois, [au mois] de Kislev,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'quand Béthel envoya Sharétser et Réguem-Mélec et ses hommes pour implorer l’ Éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'pour parler aux sacrificateurs qui étaient dans la maison de l’ Éternel des armées, et aux prophètes, disant: Pleurerai-je au cinquième mois, en me séparant comme j’ai fait, voici tant d’années?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Et la parole de l’ Éternel des armées vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Parle à tout le peuple du pays, et aux sacrificateurs, disant: Quand vous avez jeûné et que vous vous êtes lamentés au cinquième et au septième [mois], et cela pendant 70 ans, est-ce réellement pour moi, pour moi, que vous avez jeûné?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Et quand vous avez mangé et bu, n’est-ce pas vous qui mangiez et qui buviez?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Ne sont-ce pas là les paroles que l’ Éternel a criées par les premiers prophètes, alors que Jérusalem était habitée et jouissait de la paix, ainsi que ses villes qui l’entouraient, et que le midi et le pays plat étaient habités?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Et la parole de l’ Éternel vint à Zacharie, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Ainsi parle l’ Éternel des armées, disant: Prononcez des jugements de vérité, et usez de bonté et de miséricorde l’un envers l’autre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'et n’opprimez pas la veuve et l’orphelin, l’étranger et l’affligé; et ne méditez pas le mal dans votre cœur, l’un contre l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Mais ils refusèrent d’être attentifs, et opposèrent une épaule revêche, et appesantirent leurs oreilles pour ne pas entendre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'et rendirent leur cœur [dur comme] un diamant, pour ne pas écouter la loi et les paroles que l’ Éternel des armées envoyait par son Esprit, par les premiers prophètes; et il y eut une grande colère de la part de l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Et il arriva que, comme il cria et qu’ils n’écoutèrent pas, de même ils crièrent, et je n’écoutai pas, dit l’ Éternel des armées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'et je les dispersai, comme par un tourbillon, parmi toutes les nations qu’ils ne connaissaient pas, et le pays fut désolé derrière eux, de sorte qu’il n’y avait ni allants ni venants; et ils rendirent désolé le pays désirable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Et la parole de l’ Éternel des armées vint [à moi], disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Ainsi dit l’ Éternel des armées: Je suis jaloux pour Sion d’une grande jalousie, et je suis jaloux pour elle d’une grande fureur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Ainsi dit l’ Éternel: Je suis revenu à Sion, et j’habiterai au milieu de Jérusalem; et Jérusalem sera appelée la ville de vérité, et la montagne de l’ Éternel des armées, la montagne sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Ainsi dit l’ Éternel des armées: Il y aura encore des vieillards et des femmes âgées, assis dans les rues de Jérusalem, chacun son bâton à sa main, à cause du nombre de [leurs] jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Et les places de la ville seront pleines de jeunes garçons et de jeunes filles, jouant dans ses places.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Ainsi dit l’ Éternel des armées: Si c’est une chose difficile aux yeux du reste de ce peuple, en ces jours-là, serait-ce difficile aussi à mes yeux? dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Ainsi dit l’ Éternel des armées: Voici, je sauve mon peuple du pays du levant, et du pays du coucher du soleil,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'et je les amènerai, et ils demeureront au milieu de Jérusalem, et ils seront mon peuple, et moi je serai leur Dieu, en vérité et en justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Ainsi dit l’ Éternel des armées: Que vos mains soient fortes, ô vous qui entendez en ces jours-ci ces paroles de la bouche des prophètes, au jour où le fondement de la maison de l’ Éternel des armées a été posé pour bâtir le temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Car avant ces jours-là, il n’y avait point de salaire pour les hommes, et il n’y avait point de salaire pour les bêtes, et il n’y avait point de paix pour celui qui sortait, ni pour celui qui entrait, à cause de la détresse; et je lâchais tout homme, chacun contre son prochain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Mais maintenant, je ne serai pas pour le reste de ce peuple comme dans les premiers jours, dit l’ Éternel des armées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'car la semence prospérera, la vigne donnera son fruit, et la terre donnera ses produits, et les cieux donneront leur rosée, et je ferai hériter au reste de ce peuple toutes ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Et il arrivera que, comme vous étiez une malédiction parmi les nations, maison de Juda, et maison d’Israël, ainsi je vous sauverai, et vous serez une bénédiction. Ne craignez point: que vos mains soient fortes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Car ainsi dit l’ Éternel des armées: Comme j’ai pensé à vous faire du mal, quand vos pères m’ont provoqué à la colère, dit l’ Éternel des armées (et je ne m’en suis pas repenti),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'ainsi j’ai pensé de nouveau, en ces jours-ci, à faire du bien à Jérusalem et à la maison de Juda. Ne craignez point!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Ce sont ici les choses que vous ferez: Parlez la vérité chacun à son prochain, jugez [selon] la vérité, et [prononcez] un jugement de paix, dans vos portes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'et ne méditez pas le mal dans vos cœurs chacun contre son prochain, et n’aimez pas le faux serment; car toutes ces choses-là, je les hais, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Et la parole de l’ Éternel des armées vint à moi, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Ainsi dit l’ Éternel des armées: Le jeûne du quatrième [mois], et le jeûne du cinquième, et le jeûne du septième, et le jeûne du dixième [mois] seront pour la maison de Juda allégresse et joie, et d’heureuses assemblées. Aimez donc la vérité et la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Ainsi dit l’ Éternel des armées: Encore une fois il viendra des peuples et des habitants de beaucoup de villes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'et les habitants de l’une iront à l’autre, disant: Allons, allons implorer l’ Éternel, et rechercher l’ Éternel des armées! Moi aussi, j’irai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Et beaucoup de peuples, et des nations puissantes, iront pour rechercher l’ Éternel des armées à Jérusalem, et pour implorer l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Ainsi dit l’ Éternel des armées: En ces jours-là, dix hommes de toutes les langues des nations saisiront, oui, saisiront le pan de la robe d’un homme juif, disant: Nous irons avec vous, car nous avons entendu dire que Dieu est avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, '*L’oracle de la parole de l’ Éternel [qui vient] dans le pays de Hadrac; et Damas sera le lieu de son repos (car l’ Éternel a l’œil sur les hommes et sur toutes les tribus d’Israël),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'et Hamath aussi, [qui] est sur sa frontière, Tyr, et Sidon, bien qu’elle soit très sage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Et Tyr s’est bâti une forteresse, et elle amasse l’argent comme de la poussière, et l’or comme la boue des rues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Voici, le Seigneur s’en emparera et brisera sa force dans la mer, et elle sera dévorée par le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Askalon le verra et aura peur; Gaza aussi, et elle sera fort angoissée; Ékron aussi, car elle sera honteuse de sa confiance; et le roi sera retranché de Gaza, et Askalon ne sera pas habitée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'et un bâtard demeurera à Asdod; et je détruirai l’orgueil des Philistins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'et j’ôterai son sang de sa bouche, et ses abominations d’entre ses dents; mais celui qui restera, lui aussi, sera pour notre Dieu, et sera comme un chef en Juda, et Ékron, comme un Jébusien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Et je camperai à côté de ma maison, à cause de l’armée, à cause des allants et des venants, et l’exacteur ne passera plus sur eux; car maintenant j’ai vu de mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Réjouis-toi avec transports, fille de Sion; pousse des cris de joie, fille de Jérusalem! Voici, ton roi vient à toi; il est juste et ayant le salut, humble et monté sur un âne, et sur un poulain, le petit d’une ânesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Et je retrancherai d’Éphraïm le char, et de Jérusalem, le cheval, et l’arc de guerre sera retranché. Et il annoncera la paix aux nations, et dominera d’une mer à l’autre, et depuis le fleuve jusqu’aux bouts de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Quant à toi aussi, à cause du sang de ton alliance, je renverrai tes prisonniers hors de la fosse où il n’y avait point d’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Revenez à la place forte, prisonniers de l’espérance! Aujourd’hui même, je le déclare: Je te rendrai le double.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Car j’ai bandé pour moi Juda, d’Éphraïm j’ai rempli mon arc, et je réveillerai tes fils, ô Sion, contre tes fils, ô Javan, et je te rendrai telle que l’épée d’un homme fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Et l’ Éternel sera vu au-dessus d’eux, et sa flèche sortira comme l’éclair; et le Seigneur, l’ Éternel, sonnera de la trompette, et marchera avec les tourbillons du midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'L’ Éternel des armées les protégera, et ils dévoreront, et ils fouleront les pierres de fronde, et ils boiront, et bruiront comme par le vin, et ils seront remplis comme un bassin, comme les coins de l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Et l’ Éternel leur Dieu les sauvera, en ce jour-là, comme le troupeau de son peuple; car ils seront des pierres de couronne élevées sur sa terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Car combien grande est sa bonté! et combien grande est sa beauté! Le froment fera croître les jeunes gens, et le moût, les jeunes filles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, '*Demandez à l’ Éternel de la pluie, au temps de la pluie de la dernière saison. L’ Éternel fera des éclairs, et il leur donnera des ondées de pluie: à chacun de l’herbe dans son champ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Car les théraphim ont dit des paroles de vanité, et les devins ont vu un mensonge, et ils ont prononcé des songes trompeurs; ils consolent en vain. C’est pourquoi ils sont partis comme le menu bétail; ils sont opprimés, parce qu’il n’y a point de berger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Ma colère s’est embrasée contre les bergers, et je punirai les boucs; car l’ Éternel des armées a visité son troupeau, la maison de Juda, et il en a fait son cheval de gloire dans la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'De lui est la pierre angulaire, de lui le clou, de lui l’arc de guerre, de lui sortent tous les dominateurs ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Et ils seront dans la bataille comme des hommes forts qui foulent aux pieds la boue des rues; et ils combattront, car l’ Éternel sera avec eux; et ceux qui montent les chevaux seront couverts de honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Et je rendrai forte la maison de Juda, et je sauverai la maison de Joseph, et je les ramènerai, car j’userai de miséricorde envers eux; et ils seront comme si je ne les avais pas rejetés; car je suis l’ Éternel, leur Dieu, et je les exaucerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Et [ceux d’]Éphraïm seront comme un homme fort, et leur cœur se réjouira comme par le vin, et leurs fils [le] verront et se réjouiront; leur cœur s’égaiera en l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Je les sifflerai et je les rassemblerai, car je les ai rachetés; et ils multiplieront comme ils avaient multiplié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Et je les sèmerai parmi les peuples, et ils se souviendront de moi dans les [pays] éloignés, et ils vivront avec leurs fils, et ils reviendront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Et je les ramènerai du pays d’Égypte, et je les rassemblerai de l’Assyrie, et je les ferai venir au pays de Galaad et au Liban, et il ne sera pas trouvé [assez de place] pour eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Et il passera par la mer, [par] l’affliction, et dans la mer il frappera les vagues, et toutes les profondeurs du Nil seront desséchées, et l’orgueil de l’Assyrie sera abattu, et le sceptre de l’Égypte sera ôté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Et je les fortifierai en l’ Éternel, et ils marcheront en son nom, dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, '*Liban, ouvre tes portes, et que le feu dévore tes cèdres!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Hurle, cyprès! car le cèdre est tombé, les nobles sont dévastés. Hurlez, chênes de Basan! car la forêt inaccessible est abattue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Une voix du hurlement des bergers, – car leur magnificence est dévastée; une voix du rugissement des jeunes lions, – car l’orgueil du Jourdain est dévasté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Ainsi dit l’ Éternel, mon Dieu: Pais le troupeau de la tuerie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'que leurs possesseurs tuent, sans passer pour coupables, et dont les vendeurs disent: Béni soit l’ Éternel, je me suis enrichi! et leurs bergers ne les épargnent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Car je n’épargnerai plus les habitants du pays, dit l’ Éternel. Et voici, je ferai tomber les hommes dans les mains l’un de l’autre et dans la main de son roi; et ils écraseront le pays; et je ne délivrerai pas de leur main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Et je me mis à paître le troupeau de la tuerie, voire même les pauvres du troupeau; et je pris deux bâtons: je nommai l’un Beauté, et je nommai l’autre Liens, et je me mis à paître le troupeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Et je détruisis trois des bergers en un mois, et mon âme fut ennuyée d’eux, et leur âme aussi se dégoûta de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Et je dis: Je ne vous paîtrai pas: que ce qui meurt, meure; et que ce qui périt, périsse; et quant à ce qui reste, qu’ils se dévorent l’un l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Et je pris mon bâton Beauté, et je le brisai, pour rompre mon alliance, que j’avais faite avec tous les peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Et elle fut rompue en ce jour-là; et les pauvres du troupeau, qui prenaient garde à moi, connurent ainsi que c’était la parole de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Et je leur dis: Si cela est bon à vos yeux, donnez-[moi] mon salaire: sinon, laissez-le. Et ils pesèrent mon salaire, 30 [pièces] d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Et l’ Éternel me dit: Jette-le au potier, [ce] prix magnifique auquel j’ai été estimé par eux. Et je pris les 30 [pièces] d’argent, et je les jetai au potier, dans la maison de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Et je brisai mon second bâton Liens, pour rompre la fraternité entre Juda et Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Et l’ Éternel me dit: Prends encore les instruments d’un berger insensé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Car voici, je suscite un berger dans le pays, qui ne visitera pas ce qui va périr, qui ne cherchera pas ce qui est dispersé, qui ne pansera pas ce qui est blessé, et ne nourrira pas ce qui est en bon état; mais il mangera la chair de ce qui est gras, et rompra la corne de leurs pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Malheur au pasteur de néant qui abandonne le troupeau! L’épée [tombera] sur son bras et sur son œil droit. Son bras sera entièrement desséché, et son œil droit sera entièrement obscurci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, '*L’oracle de la parole de l’ Éternel sur Israël: [Ainsi] dit l’ Éternel, qui a étendu les cieux, et qui a fondé la terre, et qui a formé l’esprit de l’homme au-dedans de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Voici, je ferai de Jérusalem une coupe d’étourdissement pour tous les peuples d’alentour, et elle sera aussi contre Juda lors du siège contre Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Et il arrivera, en ce jour-là, que je ferai de Jérusalem une pierre pesante pour tous les peuples: tous ceux qui s’en chargeront s’y meurtriront certainement; et toutes les nations de la terre seront rassemblées contre elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'En ce jour-là, dit l’ Éternel, je frapperai de terreur tous les chevaux, et de délire ceux qui les montent, et j’ouvrirai mes yeux sur la maison de Juda, et je frapperai de cécité tous les chevaux des peuples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Et les chefs de Juda diront en leur cœur: Les habitants de Jérusalem seront ma force, par l’ Éternel des armées, leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'En ce jour-là, je rendrai les chefs de Juda semblables à un foyer de feu au milieu du bois et à une torche de feu dans une gerbe, et ils dévoreront à droite et à gauche tous les peuples d’alentour, et Jérusalem demeurera encore à sa place, à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Et l’ Éternel sauvera premièrement les tentes de Juda, afin que la gloire de la maison de David et la gloire des habitants de Jérusalem ne s’élèvent pas contre Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'En ce jour-là, l’ Éternel protégera les habitants de Jérusalem, et celui qui chancelle parmi eux sera en ce jour-là comme David, et la maison de David sera comme Dieu, comme l’Ange de l’ Éternel devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Et il arrivera, en ce jour-là, que je chercherai à détruire toutes les nations qui viennent contre Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Et je répandrai sur la maison de David et sur les habitants de Jérusalem un esprit de grâce et de supplications; et ils regarderont vers moi, celui qu’ils auront percé, et ils se lamenteront sur lui, comme on se lamente sur un [fils] unique, et il y aura de l’amertume pour lui, comme on a de l’amertume pour un premier-né.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'En ce jour-là, il y aura une grande lamentation à Jérusalem, comme la lamentation de Hadadrimmon dans la vallée de Meguiddon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'et le pays se lamentera, chaque famille à part: la famille de la maison de David à part, et leurs femmes à part; la famille de la maison de Nathan à part, et leurs femmes à part;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'la famille de la maison de Lévi à part, et leurs femmes à part; la famille des Shimhites à part, et leurs femmes à part:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'toutes les familles qui seront de reste, chaque famille à part, et leurs femmes à part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'En ce jour-là, une source sera ouverte pour la maison de David et pour les habitants de Jérusalem, pour le péché et pour l’impureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Et il arrivera, en ce jour-là, dit l’ Éternel des armées, que je retrancherai du pays les noms des idoles, et on ne s’en souviendra plus; et j’ôterai aussi du pays les prophètes et l’esprit impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Et il arrivera que, si un homme prophétise encore, son père et sa mère qui l’ont engendré, lui diront: Tu ne vivras pas, car tu dis des mensonges au nom de l’ Éternel. Et son père et sa mère qui l’ont engendré, le transperceront quand il prophétisera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Et il arrivera, en ce jour-là, que les prophètes auront honte, chacun de sa vision, quand il prophétisera, et ils ne se vêtiront plus d’un manteau de poil pour mentir. –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Et il dira: Je ne suis pas prophète; je suis un homme qui laboure la terre; car l’homme m’a acquis [comme esclave] dès ma jeunesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Et on lui dira: Quelles sont ces blessures à tes mains? Et il dira: Celles dont j’ai été blessé dans la maison de mes amis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Épée, réveille-toi contre mon berger, contre l’homme [qui est] mon compagnon, dit l’ Éternel des armées; frappe le berger, et le troupeau sera dispersé; et je tournerai ma main sur les petits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Et il arrivera dans tout le pays, dit l’ Éternel, que deux parties y seront retranchées et expireront; mais un tiers y demeurera de reste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Et le tiers, je l’amènerai dans le feu, et je les affinerai comme on affine l’argent, et je les éprouverai comme on éprouve l’or. Ils invoqueront mon nom, et moi, je leur répondrai; je dirai: C’est ici mon peuple; et lui, dira: L’ Éternel est mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Voici, un jour vient pour l’ Éternel, et tes dépouilles seront partagées au milieu de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Et j’assemblerai toutes les nations contre Jérusalem, pour le combat; et la ville sera prise, et les maisons seront pillées, et les femmes violées, et la moitié de la ville s’en ira en captivité; et le reste du peuple ne sera pas retranché de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Et l’ Éternel sortira et combattra contre ces nations comme au jour où il a combattu au jour de la bataille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Et ses pieds se tiendront, en ce jour-là, sur la montagne des Oliviers, qui est en face de Jérusalem, vers l’orient; et la montagne des Oliviers se fendra par le milieu, vers le levant, et vers l’occident, – une fort grande vallée; et la moitié de la montagne se retirera vers le nord, et la moitié vers le midi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Et vous fuirez dans la vallée de mes montagnes; car la vallée des montagnes s’étendra jusqu’à Atsal; et vous fuirez comme vous avez fui devant le tremblement de terre, aux jours d’Ozias, roi de Juda. – Et l’ Éternel, mon Dieu, viendra, [et] tous les saints avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Et il arrivera, en ce jour-là, qu’il n’y aura pas de lumière, les luminaires seront obscurcis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'mais ce sera un jour connu de l’ Éternel, – pas jour et pas nuit; et au temps du soir il y aura de la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Et il arrivera, en ce jour-là, que des eaux vives sortiront de Jérusalem, la moitié vers la mer orientale, et la moitié vers la mer d’occident; cela aura lieu été et hiver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Et l’ Éternel sera roi sur toute la terre. En ce jour-là, il y aura un Éternel, et son nom sera un.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Tout le pays, de Guéba à Rimmon [qui est] au midi de Jérusalem, sera changé [pour être] comme l’Araba, et [Jérusalem] sera élevée et demeurera en son lieu, depuis la porte de Benjamin jusqu’à l’endroit de la première porte, jusqu’à la porte du coin, et depuis la tour de Hananeël jusqu’aux pressoirs du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Et on y habitera, et il n’y aura plus d’anathème; et Jérusalem habitera en sécurité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Et c’est ici la plaie dont l’ Éternel frappera tous les peuples qui auront fait la guerre contre Jérusalem: leur chair se fondra tandis qu’ils seront debout sur leurs pieds, et leurs yeux se fondront dans leurs orbites, et leur langue se fondra dans leur bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Et il arrivera, en ce jour-là, qu’il y aura, de par l’ Éternel, un grand trouble parmi eux, et ils saisiront la main l’un de l’autre, et lèveront la main l’un contre l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Et Juda aussi combattra à Jérusalem; et les richesses de toutes les nations d’alentour seront rassemblées, or et argent et vêtements en grande quantité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Et ainsi sera la plaie du cheval, du mulet, du chameau, et de l’âne, et de toute bête qui sera dans ces camps: [elle sera] selon cette plaie-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Et il arrivera que tous ceux qui resteront de toutes les nations qui seront venues contre Jérusalem, monteront d’année en année pour se prosterner devant le roi, l’ Éternel des armées, et pour célébrer la fête des tabernacles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Et il arrivera que, celle des familles de la terre qui ne montera pas à Jérusalem pour se prosterner devant le roi, l’ Éternel des armées,... sur celle-là, il n’y aura pas de pluie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'et si la famille d’Égypte ne monte pas et ne vient pas, il n’y en aura pas sur elle: ce sera la plaie dont l’ Éternel frappera les nations qui ne monteront pas pour célébrer la fête des tabernacles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Ceci sera la peine du péché de l’Égypte et la peine du péché de toutes les nations qui ne monteront pas pour célébrer la fête des tabernacles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'En ce jour-là, il y aura sur les clochettes des chevaux: Sainteté à l’ Éternel; et les chaudières dans la maison de l’ Éternel seront comme les bassins devant l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Et toute chaudière dans Jérusalem et en Juda sera une chose sainte, [consacrée] à l’ Éternel des armées; et tous ceux qui offriront des sacrifices viendront et en prendront, et y cuiront. Et il n’y aura plus de Cananéen dans la maison de l’ Éternel des armées, en ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'L’oracle de la parole de l’ Éternel à Israël par Malachie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Je vous ai aimés, dit l’ Éternel; et vous dites: En quoi nous as-tu aimés? Ésaü n’était-il pas frère de Jacob? dit l’ Éternel; et j’ai aimé Jacob;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'et j’ai haï Ésaü, et j’ai fait de ses montagnes une désolation, et [j’ai livré] son héritage aux chacals du désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Si Édom dit: Nous sommes détruits, mais nous rebâtirons ce qui est ruiné, – ainsi dit l’ Éternel des armées: Ils bâtiront, mais moi, je renverserai, et on les appellera contrée de méchanceté, et le peuple contre lequel l’ Éternel est indigné à toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Et vos yeux le verront, et vous direz: L’ Éternel sera magnifié par-delà les confins d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Un fils honore son père, et un serviteur, son maître. Si donc je suis père, où est mon honneur? et si je suis maître, où est la crainte qui m’est due? dit l’ Éternel des armées, à vous, sacrificateurs, qui méprisez mon nom. Et vous dites: En quoi avons-nous méprisé ton nom?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Vous présentez sur mon autel du pain souillé, et vous dites: En quoi t’avons-nous profané? En ce que vous dites: La table de l’ Éternel est méprisable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Et si vous présentez une [bête] aveugle en sacrifice, n’est-ce pas mal? et si vous [en] présentez une boiteuse et malade, n’est-ce pas mal? Offre-la donc à ton gouverneur: t’agréera-t-il, ou te recevra-t-il avec faveur? dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Et maintenant, implorez donc ✶Dieu, afin qu’il use de grâce envers nous. C’est par vos mains que cela a eu lieu: vous recevra-t-il avec faveur? dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Qui même d’entre vous fermerait les portes? et vous n’allumeriez pas [le feu] sur mon autel pour rien! Je ne prends pas plaisir en vous, dit l’ Éternel des armées, et l’offrande, je ne l’agréerai pas de vos mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Car, du soleil levant jusqu’au soleil couchant, mon nom sera grand parmi les nations, et, en tout lieu, l’encens sera brûlé à mon nom, et une offrande pure sera présentée, car mon nom sera grand parmi les nations, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Mais vous, vous le profanez, en ce que vous dites: La table du Seigneur est souillée; et ce qu’elle fournit, sa nourriture, est méprisable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Et vous dites: Voilà, quel ennui! et vous soufflez dessus, dit l’ Éternel des armées, et vous apportez ce qui a été déchiré, et la [bête] boiteuse, et la malade; c’est ainsi que vous apportez l’offrande. Agréerais-je cela de votre main? dit l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Et maudit est celui qui trompe, et qui a dans son troupeau un mâle, et fait un vœu et sacrifie au Seigneur ce qui est corrompu; car je suis un grand roi, dit l’ Éternel des armées, et mon nom est terrible parmi les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Et maintenant, sacrificateurs, ce commandement est pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Si vous n’écoutez pas, et si vous ne prenez pas à cœur de donner gloire à mon nom, dit l’ Éternel des armées, j’enverrai parmi vous la malédiction et je maudirai vos bénédictions, et même je les ai maudites, parce que vous ne le prenez pas à cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Voici, je vais flétrir vos semences, et je répandrai de la fiente sur vos visages, la fiente de vos fêtes, et on vous emportera avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Et vous saurez que je vous ai envoyé ce commandement, afin que mon alliance subsiste avec Lévi, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Mon alliance avec lui était la vie et la paix, et je les lui donnai pour qu’il craigne; et il me craignit et trembla devant mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'La loi de vérité était dans sa bouche, et l’iniquité ne se trouva pas sur ses lèvres; il marcha avec moi dans la paix et dans la droiture, et il détourna de l’iniquité beaucoup de gens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Car les lèvres du sacrificateur gardent la connaissance, et c’est de sa bouche qu’on recherche la loi, car il est le messager de l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Mais vous vous êtes écartés du chemin, vous avez fait broncher beaucoup de gens à l’égard de la loi, vous avez corrompu l’alliance de Lévi, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Et moi aussi, je vous ai rendus méprisables et vils devant tout le peuple, parce que vous n’avez pas gardé mes voies, et avez fait acception des personnes dans ce qui concerne la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'N’y a-t-il pas pour nous tous un seul père? Un seul ✶Dieu ne nous a-t-il pas créés? Pourquoi agissons-nous perfidement chacun envers son frère, en profanant l’alliance de nos pères?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juda a agi perfidement, et l’abomination se commet en Israël et dans Jérusalem; car Juda a profané le sanctuaire de l’ Éternel, qu’il aima, et a épousé la fille d’un ✶dieu étranger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'L’ Éternel retranchera des tentes de Jacob l’homme qui fait cela, celui qui veille et celui qui répond, et celui qui apporte une offrande à l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Et en second lieu, voici ce que vous faites: vous couvrez l’autel de l’ Éternel de larmes, de pleurs et de gémissements, de sorte qu’il n’a plus égard à l’offrande, ni ne l’agrée de vos mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Et vous dites: Pourquoi? Parce que l’ Éternel est témoin entre toi et la femme de ta jeunesse, envers laquelle tu as agi perfidement; cependant elle est ta compagne et la femme de ton alliance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Et un seul ne [les] a-t-il pas faits? Toutefois il avait le reste de l’Esprit. Et pourquoi ce seul [a-t-il fait ainsi]? Il cherchait une semence de Dieu. Or prenez garde à votre esprit; et n’agis pas perfidement envers la femme de ta jeunesse');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, '(car je hais la répudiation, dit l’ Éternel, le Dieu d’Israël)...; il couvre aussi de violence son vêtement, dit l’ Éternel des armées. Prenez donc garde à votre esprit, et n’agissez pas perfidement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Vous fatiguez l’ Éternel par vos paroles, et vous dites: En quoi l’avons-nous fatigué? – En ce que vous dites: Quiconque fait le mal est bon aux yeux de l’ Éternel, et c’est en eux qu’il prend plaisir – ou bien: Où est le Dieu de jugement?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, '*Voici, j’envoie mon messager, et il préparera le chemin devant moi; et le Seigneur que vous cherchez viendra soudain à son temple, et l’Ange de l’alliance en qui vous prenez plaisir, – voici, il vient, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Mais qui supportera le jour de sa venue, et qui subsistera lorsqu’il se manifestera? Car il est comme un feu d’affineur, et comme la potasse des foulons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Et il s’assiéra [comme] celui qui affine et purifie l’argent; et il purifiera les fils de Lévi, et les affinera comme l’or et comme l’argent, et ils apporteront à l’ Éternel une offrande en justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Alors l’offrande de Juda et de Jérusalem sera agréable à l’ Éternel, comme aux jours anciens, et comme aux années d’autrefois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Et je m’approcherai de vous en jugement, et je serai un prompt témoin contre les magiciens et contre les adultères, et contre ceux qui jurent faussement, et contre ceux qui oppriment le mercenaire quant à son salaire, [ou] la veuve et l’orphelin, et qui font fléchir le droit de l’étranger, et ne me craignent pas, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Car moi, l’ Éternel, je ne change pas; et vous, fils de Jacob, vous n’êtes pas consumés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Dès les jours de vos pères, vous vous êtes détournés de mes statuts, et vous ne les avez pas gardés. Revenez à moi, et je reviendrai à vous, dit l’ Éternel des armées. Et vous dites: En quoi retournerons-nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Un homme frustrera-t-il Dieu? Toutefois, vous me frustrez, et vous dites: En quoi te frustrons-nous? Dans les dîmes et dans les offrandes élevées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Vous êtes chargés de malédiction, et vous me frustrez [toujours], [vous], la nation tout entière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Apportez toutes les dîmes à la maison du trésor, afin qu’il y ait de la nourriture dans ma maison, et éprouvez-moi par ce moyen, dit l’ Éternel des armées, si je ne vous ouvre pas les écluses des cieux, et ne verse pas sur vous la bénédiction, jusqu’à ce qu’il n’y ait plus assez [de place].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Et je tancerai en votre faveur celui qui dévore, afin qu’il ne détruise pas pour vous le fruit du sol, et que, pour vous, la vigne ne soit pas stérile, dans la campagne, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Et toutes les nations vous diront bienheureux, car vous serez un pays de délices, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Vos paroles ont été fortes contre moi, dit l’ Éternel; et vous dites: Qu’avons-nous dit contre toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Vous dites: C’est en vain qu’on sert Dieu; et quel profit y a-t-il à ce que nous fassions l’acquit de la charge qu’il nous a confiée, et que nous marchions dans le deuil devant l’ Éternel des armées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Et maintenant, nous tenons pour heureux les orgueilleux; ceux même qui pratiquent la méchanceté sont établis; même ils tentent Dieu et sont délivrés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Alors ceux qui craignent l’ Éternel ont parlé l’un à l’autre, et l’ Éternel a été attentif et a entendu, et un livre de souvenir a été écrit devant lui pour ceux qui craignent l’ Éternel, et pour ceux qui pensent à son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Et ils seront à moi, mon trésor particulier, dit l’ Éternel des armées, au jour que je ferai; et je les épargnerai comme un homme épargne son fils qui le sert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Alors vous reviendrez, et vous ferez la différence entre le juste et le méchant, entre celui qui sert Dieu et celui qui ne le sert pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 19, 'Car voici, le jour vient, brûlant comme un four; et tous les orgueilleux, et tous ceux qui pratiquent la méchanceté seront du chaume, et le jour qui vient les brûlera, dit l’ Éternel des armées, de manière à ne leur laisser ni racine, ni branche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 20, 'Et pour vous qui craignez mon nom, se lèvera le soleil de justice; et la guérison sera dans ses ailes; et vous sortirez, et vous prospérerez comme des veaux à l’engrais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 21, 'Et vous foulerez les méchants, car ils seront de la cendre sous la plante de vos pieds, au jour que je ferai, dit l’ Éternel des armées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 22, 'Souvenez-vous de la loi de Moïse, mon serviteur, que je lui commandai en Horeb pour tout Israël, – des statuts et des ordonnances.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 23, 'Voici, je vous envoie Élie, le prophète, avant que vienne le grand et terrible jour de l’ Éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 24, 'Et il fera retourner le cœur des pères vers les fils, et le cœur des fils vers leurs pères, de peur que je ne vienne et ne frappe le pays de malédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Livre de la généalogie de Jésus Christ, fils de David, fils d’Abraham:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham engendra Isaac; et Isaac engendra Jacob; et Jacob engendra Juda et ses frères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'et Juda engendra Pharès et Zara, de Thamar; et Pharès engendra Esrom; et Esrom engendra Aram;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'et Aram engendra Aminadab; et Aminadab engendra Naasson; et Naasson engendra Salmon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'et Salmon engendra Booz, de Rachab; et Booz engendra Obed, de Ruth; et Obed engendra Jessé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'et Jessé engendra David le roi; et David le roi engendra Salomon, de celle [qui avait été femme] d’Urie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'et Salomon engendra Roboam; et Roboam engendra Abia; et Abia engendra Asa;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'et Asa engendra Josaphat; et Josaphat engendra Joram; et Joram engendra Ozias;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'et Ozias engendra Joatham; et Joatham engendra Achaz; et Achaz engendra Ézéchias;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'et Ézéchias engendra Manassé; et Manassé engendra Amon; et Amon engendra Josias;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'et Josias engendra Jéchonias et ses frères, au temps de la transportation de Babylone;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'et après la transportation de Babylone, Jéchonias engendra Salathiel; et Salathiel engendra Zorobabel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'et Zorobabel engendra Abiud; et Abiud engendra Éliakim; et Éliakim engendra Azor;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'et Azor engendra Sadok; et Sadok engendra Achim; et Achim engendra Éliud;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'et Éliud engendra Éléazar; et Éléazar engendra Matthan; et Matthan engendra Jacob;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'et Jacob engendra Joseph, le mari de Marie, de laquelle est né Jésus, qui est appelé Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Toutes les générations, depuis Abraham jusqu’à David, sont donc 14 générations; et depuis David jusqu’à la transportation de Babylone, 14 générations; et depuis la transportation de Babylone jusqu’au Christ, 14 générations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Or la naissance de Jésus Christ arriva ainsi: sa mère, Marie, étant fiancée à Joseph, avant qu’ils soient ensemble, se trouva enceinte par l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Mais Joseph, son mari, étant juste, et ne voulant pas faire d’elle un exemple, se proposa de la répudier secrètement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Mais comme il méditait sur ces choses, voici, un ange du ✶Seigneur lui apparut en songe, disant: Joseph, fils de David, ne crains pas de prendre auprès de toi Marie ta femme, car ce qui a été conçu en elle est de l’Esprit Saint;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'et elle enfantera un fils, et tu appelleras son nom Jésus, car c’est lui qui sauvera son peuple de leurs péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Or tout cela arriva, afin que fût accompli ce que le ✶Seigneur a dit par le prophète, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '« Voici, la vierge sera enceinte et enfantera un fils, et on appellera son nom Emmanuel », ce qui, interprété, est: Dieu avec nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Or Joseph, étant réveillé de son sommeil, fit comme l’ange du ✶Seigneur le lui avait ordonné, et prit sa femme auprès de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'et il ne la connut point jusqu’à ce qu’elle ait enfanté son fils premier-né; et il appela son nom Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Or, après que Jésus fut né à Bethléhem de Judée, aux jours du roi Hérode, voici, des mages de l’orient arrivèrent à Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'disant: Où est le roi des Juifs qui a été mis au monde? car nous avons vu son étoile dans l’orient, et nous sommes venus lui rendre hommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Mais le roi Hérode, l’ayant entendu dire, en fut troublé, et tout Jérusalem avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'et ayant assemblé tous les principaux sacrificateurs et scribes du peuple, il s’enquit d’eux où le Christ devait naître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Et ils lui dirent: À Bethléhem de Judée; car il est ainsi écrit par le prophète:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '« Et toi, Bethléhem, terre de Juda, tu n’es nullement la plus petite parmi les gouverneurs de Juda, car de toi sortira un conducteur qui paîtra mon peuple Israël ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Alors Hérode, ayant appelé secrètement les mages, s’informa exactement auprès d’eux du temps de l’étoile qui apparaissait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'et les ayant envoyés à Bethléhem, il dit: Allez et enquérez-vous exactement touchant le petit enfant; et quand vous l’aurez trouvé, faites-le-moi savoir, en sorte que moi aussi j’aille lui rendre hommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Et eux, ayant entendu le roi, s’en allèrent; et voici, l’étoile qu’ils avaient vue dans l’orient allait devant eux, jusqu’à ce qu’elle vint et se tint au-dessus du lieu où était le petit enfant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Et quand ils virent l’étoile, ils se réjouirent d’une fort grande joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Et étant entrés dans la maison, ils virent le petit enfant avec Marie sa mère; et, se prosternant, ils lui rendirent hommage; et ayant ouvert leurs trésors, ils lui offrirent des dons, de l’or, et de l’encens, et de la myrrhe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Et étant avertis divinement, en songe, de ne pas retourner vers Hérode, ils se retirèrent dans leur pays par un autre chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Or, après qu’ils se furent retirés, voici, un ange du ✶Seigneur apparut en songe à Joseph, disant: Lève-toi, prends le petit enfant et sa mère, et fuis en Égypte, et demeure là jusqu’à ce que je te le dise; car Hérode cherchera le petit enfant pour le faire périr.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Et lui, s’étant levé, prit de nuit le petit enfant et sa mère, et se retira en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Et il fut là jusqu’à la mort d’Hérode, afin que fût accompli ce que le ✶Seigneur avait dit par le prophète, disant: « J’ai appelé mon fils hors d’Égypte ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Alors Hérode, voyant que les mages s’étaient joués de lui, fut fort en colère; et il envoya, et fit tuer tous les enfants qui étaient dans Bethléhem et dans tout son territoire, depuis l’âge de deux ans et au-dessous, selon le temps dont il s’était enquis exactement auprès des mages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Alors fut accompli ce qui a été dit par Jérémie le prophète, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '« Une voix a été entendue à Rama, [des lamentations, et] des pleurs, et de grands gémissements, Rachel pleurant ses enfants; et elle n’a pas voulu être consolée, parce qu’ils ne sont pas ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Or, Hérode étant mort, voici, un ange du ✶Seigneur apparaît en songe à Joseph en Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'disant: Lève-toi et prends le petit enfant et sa mère, et va dans la terre d’Israël; car ceux qui cherchaient la vie du petit enfant sont morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Et lui, s’étant levé, prit le petit enfant et sa mère, et s’en vint dans la terre d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'mais, ayant entendu dire qu’Archélaüs régnait en Judée à la place d’Hérode son père, il craignit d’y aller; et ayant été averti divinement, en songe, il se retira dans les quartiers de la Galilée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'et alla et habita dans une ville appelée Nazareth; en sorte que fût accompli ce qui avait été dit par les prophètes: Il sera appelé Nazaréen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Or, en ces jours-là vient Jean le baptiseur, prêchant dans le désert de la Judée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'et disant: Repentez-vous, car le royaume des cieux s’est approché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Car c’est ici celui dont il a été parlé par Ésaïe le prophète, disant: « Voix de celui qui crie dans le désert: Préparez le chemin du ✶Seigneur, faites droits ses sentiers ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Or Jean lui-même avait son vêtement de poil de chameau et une ceinture de cuir autour de ses reins; et sa nourriture était des sauterelles et du miel sauvage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Alors Jérusalem, et toute la Judée, et tout le pays des environs du Jourdain, sortaient vers lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'et ils étaient baptisés par lui dans le Jourdain, confessant leurs péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Et voyant plusieurs des pharisiens et des sadducéens venir à son baptême, il leur dit: Race de vipères, qui vous a avertis de fuir la colère qui vient?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Produisez donc du fruit qui convienne à la repentance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'et ne pensez pas de dire en vous-mêmes: Nous avons Abraham pour père; car je vous dis que Dieu peut, de ces pierres, susciter des enfants à Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Et déjà la cognée est mise à la racine des arbres; tout arbre donc qui ne produit pas de bon fruit est coupé et jeté au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Moi, je vous baptise d’eau pour la repentance; mais celui qui vient après moi est plus puissant que moi, et je ne suis pas digne de porter ses sandales: lui vous baptisera de l’Esprit Saint et de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Il a son van dans sa main, et il nettoiera entièrement son aire et assemblera son froment dans le grenier; mais il brûlera la balle au feu inextinguible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Alors Jésus vient de Galilée au Jourdain auprès de Jean, pour être baptisé par lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'mais Jean l’en empêchait fort, disant: Moi, j’ai besoin d’être baptisé par toi, et toi, tu viens à moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Et Jésus, répondant, lui dit: Laisse faire maintenant, car ainsi il nous est convenable d’accomplir toute justice. Alors il le laissa faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Et Jésus, ayant été baptisé, remonta aussitôt de l’eau; et voici, les cieux lui furent ouverts, et il vit l’Esprit de Dieu descendre comme une colombe, et venir sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Et voici une voix qui venait des cieux, disant: Celui-ci est mon Fils bien-aimé, en qui j’ai trouvé mon plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Alors Jésus fut emmené dans le désert par l’Esprit pour être tenté par le diable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Et ayant jeûné 40 jours et 40 nuits, après cela il eut faim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Et le tentateur, s’approchant de lui, dit: Si tu es Fils de Dieu, dis que ces pierres deviennent des pains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Mais lui, répondant, dit: Il est écrit: « L’homme ne vivra pas de pain seulement, mais de toute parole qui sort de la bouche de Dieu ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Alors le diable le transporte dans la ville sainte, et le place sur le faîte du temple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'et lui dit: Si tu es Fils de Dieu, jette-toi en bas, car il est écrit: « Il donnera des ordres à ses anges à ton sujet, et ils te porteront sur [leurs] mains, de peur que tu ne heurtes ton pied contre une pierre ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jésus lui dit: Il est encore écrit: « Tu ne tenteras pas le ✶Seigneur ton Dieu ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Le diable le transporte encore sur une fort haute montagne, et lui montre tous les royaumes du monde et leur gloire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'et lui dit: Je te donnerai toutes ces choses, si, te prosternant, tu me rends hommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Alors Jésus lui dit: Va-t’en, Satan, car il est écrit: « Tu rendras hommage au ✶Seigneur ton Dieu, et tu le serviras lui seul ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Alors le diable le laisse: et voici, des anges s’approchèrent et le servirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Or, ayant entendu dire que Jean avait été livré, il se retira en Galilée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'et ayant quitté Nazareth, il alla demeurer à Capernaüm, qui est au bord de la mer, sur les confins de Zabulon et de Nephthali,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'afin que fût accompli ce qui avait été dit par Ésaïe le prophète, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '« Terre de Zabulon, et terre de Nephthali, chemin de la mer au-delà du Jourdain, Galilée des nations:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'le peuple assis dans les ténèbres a vu une grande lumière; et sur ceux qui sont assis dans la région et dans l’ombre de la mort, la lumière s’est levée ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Dès lors Jésus commença à prêcher et à dire: Repentez-vous, car le royaume des cieux s’est approché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Et comme il marchait le long de la mer de Galilée, il vit deux frères, Simon appelé Pierre, et André son frère, qui jetaient un filet dans la mer, car ils étaient pêcheurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'et il leur dit: Venez après moi, et je vous ferai pêcheurs d’hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Et eux aussitôt, ayant laissé leurs filets, le suivirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Et, passant de là plus avant, il vit deux autres frères, Jacques le [fils] de Zébédée, et Jean son frère, dans le bateau avec Zébédée leur père, raccommodant leurs filets, et il les appela;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'et eux aussitôt, ayant quitté le bateau et leur père, le suivirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Et Jésus parcourait toute la Galilée, enseignant dans leurs synagogues, et prêchant l’évangile du royaume, et guérissant toute sorte de maladies et toute sorte de langueurs parmi le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Et sa renommée se répandit dans toute la Syrie; et on lui amena tous ceux qui se portaient mal, qui étaient affligés de diverses maladies et de divers tourments, et des démoniaques, et des lunatiques, et des paralytiques, et il les guérit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Et de grandes foules le suivirent de la Galilée, et de Décapolis, et de Jérusalem, et de Judée, et de par-delà le Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Or, voyant les foules, il monta sur la montagne; et lorsqu’il se fut assis, ses disciples s’approchèrent de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'et ayant ouvert la bouche, il les enseignait, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Bienheureux les pauvres en esprit, car c’est à eux qu’est le royaume des cieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'bienheureux ceux qui mènent deuil, car c’est eux qui seront consolés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'bienheureux les débonnaires, car c’est eux qui hériteront de la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'bienheureux ceux qui ont faim et soif de la justice, car c’est eux qui seront rassasiés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'bienheureux les miséricordieux, car c’est à eux que miséricorde sera faite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'bienheureux ceux qui sont purs de cœur, car c’est eux qui verront Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'bienheureux ceux qui procurent la paix, car c’est eux qui seront appelés fils de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'bienheureux ceux qui sont persécutés à cause de la justice, car c’est à eux qu’est le royaume des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Vous êtes bienheureux quand on vous injuriera, et qu’on vous persécutera, et qu’on dira, en mentant, toute espèce de mal contre vous, à cause de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Réjouissez-vous et tressaillez de joie, car votre récompense est grande dans les cieux; car on a persécuté ainsi les prophètes qui ont été avant vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Vous êtes le sel de la terre; mais si le sel a perdu sa saveur, avec quoi sera-t-il salé? Il n’est plus bon à rien qu’ à être jeté dehors et à être foulé aux pieds par les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vous êtes la lumière du monde: une ville située sur une montagne ne peut être cachée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Aussi n’allume-t-on pas une lampe pour la mettre ensuite sous le boisseau, mais sur le pied de lampe; et elle luit pour tous ceux qui sont dans la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Que votre lumière luise ainsi devant les hommes, en sorte qu’ils voient vos bonnes œuvres, et qu’ils glorifient votre Père qui est dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Ne pensez pas que je sois venu pour abolir la loi ou les prophètes: je ne suis pas venu pour abolir, mais pour accomplir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'car, en vérité, je vous dis: Jusqu’à ce que le ciel et la terre passent, un seul iota ou un seul trait de lettre ne passera point de la loi, que tout ne soit accompli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Quiconque donc aura supprimé l’un de ces plus petits commandements et aura enseigné ainsi les hommes, sera appelé le plus petit dans le royaume des cieux; et quiconque l’aura pratiqué et enseigné, celui-là sera appelé grand dans le royaume des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Car je vous dis que, si votre justice ne surpasse pas celle des scribes et des pharisiens, vous n’entrerez point dans le royaume des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Vous avez entendu qu’il a été dit aux anciens: « Tu ne tueras pas; et quiconque tuera, sera passible du jugement ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Mais moi, je vous dis que quiconque se met en colère légèrement contre son frère sera passible du jugement; et quiconque dira à son frère: “Raca”, sera passible [du jugement] du sanhédrin; et quiconque dira “fou”, sera passible de la géhenne du feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Si donc tu offres ton don à l’autel, et que là il te souvienne que ton frère a quelque chose contre toi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'laisse là ton don devant l’autel, et va d’abord, réconcilie-toi avec ton frère; et alors viens et offre ton don.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Mets-toi promptement d’accord avec ta partie adverse, pendant que tu es en chemin avec elle, de peur que ta partie adverse ne te livre au juge, et que le juge ne te livre au sergent, et que tu ne sois jeté en prison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'en vérité, je te dis: Tu ne sortiras point de là, jusqu’à ce que tu aies payé le dernier quadrant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Vous avez entendu qu’il a été dit: « Tu ne commettras pas adultère ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Mais moi, je vous dis que quiconque regarde une femme pour la convoiter, a déjà commis adultère avec elle dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Mais si ton œil droit est pour toi une occasion de chute, arrache-le et jette-le loin de toi; car il est avantageux pour toi qu’un de tes membres périsse, et que tout ton corps ne soit pas jeté dans la géhenne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Et si ta main droite est pour toi une occasion de chute, coupe-la et jette-la loin de toi; car il est avantageux pour toi qu’un de tes membres périsse, et que tout ton corps ne soit pas jeté dans la géhenne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Il a été dit aussi: « Si quelqu’un répudie sa femme, qu’il lui donne une lettre de divorce ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Mais moi, je vous dis que quiconque répudiera sa femme, si ce n’est pour cause de fornication, la fait commettre adultère; et quiconque épousera une femme répudiée, commet adultère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Vous avez encore entendu qu’il a été dit aux anciens: « Tu ne te parjureras pas, mais tu rendras justement au ✶Seigneur tes serments ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Mais moi, je vous dis de ne pas jurer du tout; ni par le ciel, car il est le trône de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'ni par la terre, car elle est le marchepied de ses pieds; ni par Jérusalem, car elle est la ville du grand Roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Tu ne jureras pas non plus par ta tête, car tu ne peux faire blanc ou noir un cheveu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Mais que votre parole soit: Oui, oui; non, non; car ce qui est de plus vient du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Vous avez entendu qu’il a été dit: « Œil pour œil, et dent pour dent ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Mais moi, je vous dis: Ne résistez pas au mal; mais si quelqu’un te frappe sur la joue droite, présente-lui aussi l’autre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'et à celui qui veut plaider contre toi et t’ôter ta tunique, laisse-lui encore le manteau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'et si quelqu’un veut te contraindre de faire un mille, vas-en deux avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Donne à qui te demande, et ne te détourne pas de qui veut emprunter de toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Vous avez entendu qu’il a été dit: « Tu aimeras ton prochain, et tu haïras ton ennemi ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Mais moi, je vous dis: Aimez vos ennemis, [bénissez ceux qui vous maudissent, faites du bien à ceux qui vous haïssent], et priez pour ceux qui [vous font du tort et] vous persécutent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'en sorte que vous soyez les fils de votre Père qui est dans les cieux; car il fait lever son soleil sur les méchants et sur les bons, et envoie sa pluie sur les justes et sur les injustes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Car si vous aimez ceux qui vous aiment, quelle récompense avez-vous? Les publicains même n’en font-ils pas autant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Et si vous saluez vos frères seulement, que faites-vous de plus [que les autres]? Les nations même ne font-elles pas ainsi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Vous, soyez donc parfaits, comme votre Père céleste est parfait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Prenez garde de ne pas faire votre aumône devant les hommes, pour être vus par eux; autrement vous n’avez pas de récompense auprès de votre Père qui est dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Quand donc tu fais l’aumône, ne fais pas sonner la trompette devant toi, comme font les hypocrites dans les synagogues et dans les rues, pour être glorifiés par les hommes. En vérité, je vous dis: ils ont déjà leur récompense!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Mais toi, quand tu fais l’aumône, que ta main gauche ne sache pas ce que fait ta droite,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'en sorte que ton aumône soit [faite] dans le secret; et ton Père qui voit dans le secret, te récompensera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Et quand tu pries, ne sois pas comme les hypocrites, car ils aiment à prier en se tenant debout dans les synagogues et aux coins des rues, en sorte qu’ils soient vus des hommes. En vérité, je vous dis: ils ont déjà leur récompense!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Mais toi, quand tu pries, entre dans ta chambre, et ayant fermé ta porte, prie ton Père qui [demeure] dans le secret; et ton Père qui voit dans le secret, te récompensera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Et quand vous priez, n’usez pas de vaines redites, comme ceux des nations, car ils s’imaginent qu’ils seront exaucés en parlant beaucoup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Ne leur ressemblez donc pas, car votre Père sait de quoi vous avez besoin, avant que vous le lui demandiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Vous donc, priez ainsi: Notre Père qui es dans les cieux, que ton nom soit sanctifié;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'que ton règne vienne; que ta volonté soit faite, comme dans le ciel, aussi sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Donne-nous aujourd’hui le pain qu’il nous faut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'et remets-nous nos dettes, comme nous aussi nous remettons à nos débiteurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'et ne nous induis pas en tentation, mais délivre-nous du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Car si vous pardonnez aux hommes leurs fautes, votre Père céleste vous pardonnera aussi à vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'mais si vous ne pardonnez pas aux hommes leurs fautes, votre Père ne pardonnera pas non plus vos fautes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Et quand vous jeûnez, ne prenez pas, comme les hypocrites, un air morne, car ils donnent à leur visage un air défait, en sorte qu’il paraisse aux hommes qu’ils jeûnent. En vérité, je vous dis: ils ont déjà leur récompense!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Mais toi, quand tu jeûnes, oins ta tête et lave ton visage,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'en sorte qu’il ne paraisse pas aux hommes que tu jeûnes, mais à ton Père qui [demeure] dans le secret; et ton Père qui voit dans le secret, te récompensera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Ne vous amassez pas des trésors sur la terre, où la teigne et la rouille gâtent, et où les voleurs percent et dérobent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'mais amassez-vous des trésors dans le ciel, où ni la teigne ni la rouille ne gâtent, et où les voleurs ne percent ni ne dérobent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'car là où est ton trésor, là sera aussi ton cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'La lampe du corps, c’est l’œil; si donc ton œil est simple, ton corps tout entier sera [plein de] lumière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'mais si ton œil est méchant, ton corps tout entier sera ténébreux; si donc la lumière qui est en toi est ténèbres, combien seront grandes les ténèbres!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Nul ne peut servir deux maîtres; car, ou il haïra l’un et aimera l’autre, ou il s’attachera à l’un et méprisera l’autre: vous ne pouvez servir Dieu et Mammon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'C’est pourquoi je vous dis: Ne soyez pas en souci pour votre vie, de ce que vous mangerez et de ce que vous boirez, ni pour votre corps, de quoi vous serez vêtus: la vie n’est-elle pas plus que la nourriture, et le corps plus que le vêtement?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Regardez aux oiseaux du ciel: ils ne sèment, ni ne moissonnent, ni n’assemblent dans des greniers, et votre Père céleste les nourrit. Ne valez-vous pas beaucoup mieux qu’eux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Et qui d’entre vous, par le souci qu’il se donne, peut ajouter une coudée à sa taille?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Et pourquoi êtes-vous en souci du vêtement? Étudiez les lis des champs, comment ils croissent: ils ne travaillent ni ne filent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'cependant je vous dis que, même Salomon dans toute sa gloire, n’était pas vêtu comme l’un d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Et si Dieu revêt ainsi l’herbe des champs qui est aujourd’hui, et qui demain est jetée dans le four, ne vous [vêtira-t-il] pas beaucoup plutôt, gens de petite foi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Ne soyez donc pas en souci, disant: Que mangerons-nous? ou que boirons-nous? ou de quoi serons-nous vêtus?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'car les nations recherchent toutes ces choses; car votre Père céleste sait que vous avez besoin de toutes ces choses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'mais cherchez premièrement le royaume de Dieu et sa justice, et toutes ces choses vous seront données par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Ne soyez donc pas en souci pour le lendemain, car le lendemain sera en souci de lui-même: à chaque jour suffit sa peine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Ne jugez pas, afin que vous ne soyez pas jugés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'car, du jugement dont vous jugerez, vous serez jugés; et de la mesure dont vous mesurerez, il vous sera mesuré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Et pourquoi regardes-tu le fétu qui est dans l’œil de ton frère, et tu ne t’aperçois pas de la poutre qui est dans ton œil?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Ou comment dis-tu à ton frère: Permets, j’ôterai le fétu de ton œil; et voici, la poutre est dans ton œil?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Hypocrite, ôte premièrement de ton œil la poutre, et alors tu verras clair pour ôter le fétu de l’œil de ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Ne donnez pas ce qui est saint aux chiens, ni ne jetez vos perles devant les pourceaux, de peur qu’ils ne les foulent à leurs pieds, et que, se retournant, ils ne vous déchirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Demandez, et il vous sera donné; cherchez, et vous trouverez; heurtez, et il vous sera ouvert;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'car quiconque demande, reçoit; et celui qui cherche, trouve; et à celui qui heurte, il sera ouvert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Ou quel est l’homme d’entre vous, qui, si son fils lui demande un pain, lui donne une pierre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'et s’il demande un poisson, lui donne un serpent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Si donc vous, qui êtes méchants, vous savez donner à vos enfants des choses bonnes, combien plus votre Père qui est dans les cieux donnera-t-il de bonnes choses à ceux qui les lui demandent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Toutes les choses donc que vous voulez que les hommes vous fassent, faites-les-leur, vous aussi, de même; car c’est là la loi et les prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Entrez par la porte étroite; car large est la porte, et spacieux le chemin qui mène à la perdition, et nombreux sont ceux qui entrent par elle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'car étroite est la porte, et resserré le chemin qui mène à la vie, et peu nombreux sont ceux qui le trouvent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Or soyez en garde contre les faux prophètes qui viennent à vous en habits de brebis, mais qui au-dedans sont des loups ravisseurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Vous les reconnaîtrez à leurs fruits. Cueille-t-on du raisin sur des épines, ou des figues sur des chardons?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Ainsi tout bon arbre produit de bons fruits, mais l’arbre mauvais produit de mauvais fruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Un bon arbre ne peut pas produire de mauvais fruits, ni un arbre mauvais produire de bons fruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Tout arbre qui ne produit pas de bon fruit est coupé et jeté au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Ainsi vous les reconnaîtrez à leurs fruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ce ne sont pas tous ceux qui me disent: Seigneur, Seigneur, qui entreront dans le royaume des cieux; mais celui qui fait la volonté de mon Père qui est dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Plusieurs me diront en ce jour-là: Seigneur, Seigneur, n’avons-nous pas prophétisé en ton nom, et n’avons-nous pas chassé des démons en ton nom, et n’avons-nous pas fait beaucoup de miracles en ton nom?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Et alors je leur déclarerai: Je ne vous ai jamais connus; retirez-vous de moi, vous qui pratiquez l’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Quiconque donc entend ces miennes paroles et les met en pratique, je le comparerai à un homme prudent qui a bâti sa maison sur le roc;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'et la pluie est tombée, et les torrents sont venus, et les vents ont soufflé et ont donné contre cette maison; et elle n’est pas tombée, car elle avait été fondée sur le roc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Et quiconque entend ces miennes paroles, et ne les met pas en pratique, sera comparé à un homme insensé qui a bâti sa maison sur le sable;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'et la pluie est tombée, et les torrents sont venus, et les vents ont soufflé et ont battu cette maison, et elle est tombée, et sa chute a été grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Et il arriva que, quand Jésus eut achevé ces discours, les foules s’étonnaient de sa doctrine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'car il les enseignait comme ayant autorité, et non pas comme leurs scribes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Et quand il fut descendu de la montagne, de grandes foules le suivirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Et voici, un lépreux s’approchant, se prosterna devant lui, disant: Seigneur, si tu veux, tu peux me rendre net.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Et [Jésus], étendant la main, le toucha, disant: Je veux, sois net. Et aussitôt il fut nettoyé de sa lèpre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Et Jésus lui dit: Prends garde de ne le dire à personne; mais va, montre-toi au sacrificateur et offre le don que Moïse a ordonné, pour qu’il leur serve de témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Et comme il entrait dans Capernaüm, un centurion vint à lui, le suppliant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'et disant: Seigneur, mon serviteur est couché à la maison, atteint de paralysie, horriblement tourmenté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Et Jésus lui dit: J’irai, moi, et je le guérirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Et le centurion répondit et dit: Seigneur, je ne suis pas digne que tu entres sous mon toit; mais dis seulement une parole, et mon serviteur sera guéri;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'car moi aussi, je suis un homme placé sous l’autorité [d’autrui], ayant sous moi des soldats; et je dis à l’un: Va, et il va; et à un autre: Viens, et il vient; et à mon esclave: Fais cela, et il le fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Et Jésus, l’ayant entendu, s’en étonna, et dit à ceux qui [le] suivaient: En vérité, je vous dis: je n’ai pas trouvé, même en Israël, une si grande foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Et je vous dis que plusieurs viendront d’orient et d’occident, et s’assiéront avec Abraham et Isaac et Jacob dans le royaume des cieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'mais les fils du royaume seront jetés dans les ténèbres de dehors: là seront les pleurs et les grincements de dents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Et Jésus dit au centurion: Va, et qu’il te soit fait comme tu as cru; et à cette heure-là son serviteur fut guéri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Et Jésus, étant venu dans la maison de Pierre, vit la belle-mère de Pierre couchée là et ayant la fièvre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'et il lui toucha la main, et la fièvre la quitta; et elle se leva et le servit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Et le soir étant venu, on lui apporta beaucoup de démoniaques; et il chassa les esprits par [une] parole, et guérit tous ceux qui se portaient mal;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'en sorte que fût accompli ce qui a été dit par Ésaïe le prophète, disant: « Lui-même a pris nos langueurs, et a porté nos maladies ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Or Jésus, voyant de grandes foules autour de lui, commanda de passer à l’autre rive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Et un scribe s’approchant, lui dit: Maître, je te suivrai où que tu ailles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Et Jésus lui dit: Les renards ont des tanières, et les oiseaux du ciel ont des demeures; mais le fils de l’homme n’a pas où reposer sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Et un autre de ses disciples lui dit: Seigneur, permets-moi de m’en aller premièrement et d’ensevelir mon père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Mais Jésus lui dit: Suis-moi, et laisse les morts ensevelir leurs morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Et quand il fut monté dans le bateau, ses disciples le suivirent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'et voici, une grande tourmente s’éleva sur la mer, en sorte que le bateau était couvert par les vagues; mais lui dormait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Et les disciples s’approchèrent et le réveillèrent, disant: Seigneur, sauve-[nous]! nous périssons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Et il leur dit: Pourquoi êtes-vous craintifs, gens de petite foi? Alors, s’étant levé, il reprit les vents et la mer, et il se fit un grand calme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Et les gens s’en étonnèrent, disant: Quel est celui-ci, que les vents même et la mer lui obéissent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Et quand il arriva à l’autre rive, dans le pays des Gergéséniens, deux démoniaques, sortant des sépulcres, vinrent à sa rencontre; [et ils étaient] très violents, en sorte que personne ne pouvait passer par ce chemin-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Et voici, ils s’écrièrent, disant: Qu’y a-t-il entre nous et toi Jésus, Fils de Dieu? Es-tu venu ici avant le temps pour nous tourmenter?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Et il y avait, loin d’eux, un grand troupeau de pourceaux qui paissait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Et les démons le priaient, disant: Si tu nous chasses, permets-nous de nous en aller dans le troupeau des pourceaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Et il leur dit: Allez. Et eux, sortant, s’en allèrent dans le troupeau des pourceaux; et voici, tout le troupeau des pourceaux se rua du haut de la côte dans la mer; et ils moururent dans les eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Et ceux qui les paissaient s’enfuirent; et, s’en étant allés dans la ville, ils racontèrent tout, et ce qui était arrivé aux démoniaques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Et voici, toute la ville sortit au-devant de Jésus; et l’ayant vu, ils le prièrent de se retirer de leur territoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Et étant monté dans le bateau, il passa à l’autre rive, et vint dans sa propre ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Et voici, on lui apporta un paralytique couché sur un lit. Et Jésus, voyant leur foi, dit au paralytique: Aie bon courage, [mon] enfant, tes péchés sont pardonnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Et voici, quelques-uns des scribes dirent en eux-mêmes: Cet homme blasphème.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Et Jésus, voyant leurs pensées, dit: Pourquoi pensez-vous du mal dans vos cœurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Car lequel est le plus facile, de dire: Tes péchés sont pardonnés, ou de dire: Lève-toi et marche?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Or, afin que vous sachiez que le fils de l’homme a le pouvoir sur la terre de pardonner les péchés...; alors il dit au paralytique: Lève-toi, prends ton lit, et va dans ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Et il se leva et s’en alla dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Et les foules, ayant vu cela, furent saisies de crainte, et elles glorifièrent Dieu qui donnait un tel pouvoir aux hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Et Jésus, passant de là plus avant, vit un homme nommé Matthieu, assis au bureau de recette; et il lui dit: Suis-moi. Et se levant, il le suivit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Et il arriva, comme il était à table dans la maison, que voici, beaucoup de publicains et de pécheurs vinrent et se mirent à table avec Jésus et ses disciples;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'ce que les pharisiens ayant vu, ils dirent à ses disciples: Pourquoi votre maître mange-t-il avec les publicains et les pécheurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Et Jésus, l’ayant entendu, leur dit: Ceux qui sont en bonne santé n’ont pas besoin de médecin, mais ceux qui se portent mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Mais allez et apprenez ce que c’est que: « Je veux miséricorde et non pas sacrifice »; car je ne suis pas venu appeler des justes, mais des pécheurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Alors les disciples de Jean viennent à lui, disant: Pourquoi, nous et les pharisiens, jeûnons-nous souvent, et tes disciples ne jeûnent pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Et Jésus leur dit: Les fils de la chambre nuptiale peuvent-ils mener deuil tant que l’époux est avec eux? Mais des jours viendront, lorsque l’époux leur aura été ôté; et alors ils jeûneront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Et personne ne met un morceau de drap neuf à un vieil habit, car la pièce emporte [une partie] de l’habit, et la déchirure en devient plus mauvaise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'On ne met pas non plus du vin nouveau dans de vieilles outres; autrement les outres se rompent, et le vin se répand, et les outres sont perdues; mais on met le vin nouveau dans des outres neuves, et tous les deux se conservent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Comme il leur disait ces choses, voici, un chef [de synagogue] s’étant approché lui rendit hommage, disant: Ma fille vient de mourir, mais viens et pose ta main sur elle, et elle vivra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Et Jésus se levant le suivit, ainsi que ses disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Et voici, une femme qui avait une perte de sang depuis douze ans s’approcha par-derrière et toucha le bord de son vêtement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'car elle disait en elle-même: Si seulement je touche son vêtement, je serai guérie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Et Jésus, s’étant retourné et la voyant, dit: Aie bon courage, [ma] fille; ta foi t’a guérie. Et la femme fut guérie dès cette heure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Et Jésus, étant arrivé à la maison du chef [de synagogue], et voyant les joueurs de flûte et la foule qui faisait un grand bruit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'dit: Retirez-vous, car la jeune fille n’est pas morte, mais elle dort. Et ils se riaient de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Et lorsque la foule eut été mise dehors, il entra et prit sa main, et la jeune fille se leva.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Et le bruit s’en répandit par tout ce pays-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Et comme Jésus passait de là plus avant, deux aveugles le suivirent, criant et disant: Aie pitié de nous, Fils de David!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Et quand il fut arrivé dans la maison, les aveugles vinrent à lui. Et Jésus leur dit: Croyez-vous que je puisse faire ceci? Ils lui disent: Oui, Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Alors il toucha leurs yeux, disant: Qu’il vous soit fait selon votre foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Et leurs yeux furent ouverts. Et Jésus leur parla sévèrement, disant: Prenez garde que personne ne le sache.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Mais eux, étant partis, répandirent sa renommée dans tout ce pays-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Et comme ils sortaient, voici, on lui amena un homme muet, démoniaque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Et le démon ayant été chassé, le muet parla. Et les foules s’en étonnèrent, disant: Il ne s’est jamais rien vu de pareil en Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'mais les pharisiens disaient: Il chasse les démons par le chef des démons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Et Jésus allait par toutes les villes et par les villages, enseignant dans leurs synagogues, et prêchant l’évangile du royaume, et guérissant toute maladie et toute langueur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Et voyant les foules, il fut ému de compassion pour elles, parce qu’ils étaient las et dispersés, comme des brebis qui n’ont pas de berger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Alors il dit à ses disciples: La moisson est grande, mais il y a peu d’ouvriers:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'suppliez donc le Seigneur de la moisson, en sorte qu’il pousse des ouvriers dans sa moisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Et ayant appelé ses douze disciples, il leur donna autorité sur les esprits immondes pour les chasser, et pour guérir toute maladie et toute langueur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Or ce sont ici les noms des douze apôtres: le premier, Simon appelé Pierre, et André son frère; Jacques le [fils] de Zébédée, et Jean son frère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philippe et Barthélemy; Thomas et Matthieu le publicain; Jacques le [fils] d’Alphée, et Lebbée surnommé Thaddée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon le Cananéen, et Judas l’Iscariote, qui aussi le livra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Jésus envoya ces douze et leur donna des ordres, disant: Ne vous en allez pas sur le chemin des nations, et n’entrez dans aucune ville de Samaritains;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'mais allez plutôt vers les brebis perdues de la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Et quand vous irez, prêchez, disant: Le royaume des cieux s’est approché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Guérissez les infirmes; [ressuscitez les morts]; rendez nets les lépreux; chassez les démons: vous avez reçu gratuitement, donnez gratuitement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ne faites provision ni d’or, ni d’argent, ni de cuivre dans vos ceintures,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'ni d’un sac pour le chemin, ni de deux tuniques, ni de sandales, ni d’un bâton, car l’ouvrier est digne de sa nourriture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Et dans quelque ville ou village que vous entriez, informez-vous qui y est digne; et demeurez là jusqu’à ce que vous partiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Et quand vous entrerez dans une maison, saluez-la.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Et si la maison [en] est digne, que votre paix vienne sur elle; mais si elle n’[en] est pas digne, que votre paix retourne à vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Et si quelqu’un ne vous reçoit pas et n’écoute pas vos paroles, – quand vous partirez de cette maison ou de cette ville, secouez la poussière de vos pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'En vérité, je vous dis: le sort du pays de Sodome et de Gomorrhe sera plus supportable au jour de jugement que celui de cette ville-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Voici, moi je vous envoie comme des brebis au milieu des loups; soyez donc prudents comme les serpents, et simples comme les colombes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'et soyez en garde contre les hommes, car ils vous livreront aux sanhédrins et vous fouetteront dans leurs synagogues;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'et vous serez menés même devant les gouverneurs et les rois, à cause de moi, en témoignage à eux et aux nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Et quand ils vous livreront, ne soyez pas en souci comment vous parlerez, ni de ce que vous direz; car il vous sera donné dans cette heure-là ce que vous direz;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'car ce n’est pas vous qui parlez, mais c’est l’Esprit de votre Père qui parle en vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Et le frère livrera son frère à la mort, et le père son enfant; et les enfants s’élèveront contre leurs parents et les feront mourir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'et vous serez haïs de tous à cause de mon nom; et celui qui persévérera jusqu’à la fin, celui-là sera sauvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Mais quand on vous persécutera dans cette ville, fuyez dans l’autre; car, en vérité, je vous dis: Vous n’aurez point achevé [de parcourir] les villes d’Israël, que le fils de l’homme ne soit venu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Le disciple n’est pas au-dessus du maître, ni l’esclave au-dessus de son seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Il suffit au disciple qu’il soit comme son maître, et à l’esclave qu’il soit comme son seigneur: s’ils ont appelé le maître de la maison Béelzébul, combien plus les gens de sa maison?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Ne les craignez donc pas; car il n’y a rien de couvert qui ne sera révélé, ni rien de secret qui ne sera connu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Ce que je vous dis dans les ténèbres, dites-le dans la lumière; et ce qui vous est dit à l’oreille, prêchez-le sur les toits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Et ne craignez pas ceux qui tuent le corps et qui ne peuvent pas tuer l’âme; mais craignez plutôt celui qui peut détruire et l’âme et le corps, dans la géhenne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Ne vend-on pas deux passereaux pour un sou? Et pas un seul d’entre eux ne tombe en terre, sans votre Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Et pour vous, les cheveux même de votre tête sont tous comptés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Ne craignez donc pas: vous valez mieux que beaucoup de passereaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Quiconque donc me confessera devant les hommes, moi aussi je le confesserai devant mon Père qui est dans les cieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'mais quiconque me reniera devant les hommes, moi aussi je le renierai devant mon Père qui est dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Ne pensez pas que je sois venu mettre la paix sur la terre; je ne suis pas venu mettre la paix, mais l’épée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'car je suis venu jeter la division entre un homme et son père, entre la fille et sa mère, entre la belle-fille et sa belle-mère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'et les ennemis d’un homme seront les gens de sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Celui qui aime père ou mère plus que moi, n’est pas digne de moi; et celui qui aime fils ou fille plus que moi, n’est pas digne de moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'et celui qui ne prend pas sa croix et ne vient pas après moi, n’est pas digne de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Celui qui aura trouvé sa vie, la perdra; et celui qui aura perdu sa vie pour l’amour de moi, la trouvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Celui qui vous reçoit, me reçoit; et celui qui me reçoit, reçoit celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Celui qui reçoit un prophète en qualité de prophète, recevra la récompense d’un prophète; et celui qui reçoit un juste en qualité de juste, recevra la récompense d’un juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Et quiconque aura donné à boire seulement une coupe d’eau froide à l’un de ces petits, en qualité de disciple, en vérité, je vous dis, il ne perdra point sa récompense.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Et il arriva, quand Jésus eut achevé de donner ses ordres à ses douze disciples, qu’il partit de là pour enseigner et prêcher dans leurs villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Et Jean, ayant entendu parler dans la prison des œuvres du Christ, envoya par ses disciples,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'et lui dit: Es-tu celui qui vient, ou devons-nous en attendre un autre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Et Jésus, répondant, leur dit: Allez, et rapportez à Jean les choses que vous entendez et que vous voyez:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'les aveugles recouvrent la vue et les boiteux marchent; les lépreux sont rendus nets et les sourds entendent, et les morts sont ressuscités, et l’évangile est annoncé aux pauvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Et bienheureux est quiconque n’aura pas été scandalisé en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Et comme ils s’en allaient, Jésus se mit à dire de Jean aux foules: Qu’êtes-vous allés voir au désert? Un roseau agité par le vent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Mais qu’êtes-vous allés voir? Un homme vêtu de vêtements précieux? Voici, ceux qui portent des choses précieuses sont dans les maisons des rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Mais qu’êtes-vous allés voir? Un prophète? Oui, vous dis-je, et plus qu’un prophète;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'car c’est ici celui dont il est écrit: « Voici, moi j’envoie mon messager devant ta face, lequel préparera ton chemin devant toi ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'En vérité, je vous dis: parmi ceux qui sont nés de femme, il n’en a été suscité aucun de plus grand que Jean le baptiseur; mais le moindre dans le royaume des cieux est plus grand que lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Mais, depuis les jours de Jean le baptiseur jusqu’à maintenant, le royaume des cieux est pris par violence, et les violents le ravissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Car tous les prophètes et la loi ont prophétisé jusqu’à Jean.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Et si vous voulez recevoir [ce que je vous dis], celui-ci est Élie qui doit venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Qui a des oreilles pour entendre, qu’il entende.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Mais à qui comparerai-je cette génération? Elle est semblable à de petits enfants assis dans les marchés, et criant à leurs compagnons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'et disant: Nous vous avons joué de la flûte, et vous n’avez pas dansé; nous vous avons chanté des complaintes, et vous ne vous êtes pas lamentés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Car Jean est venu ne mangeant ni ne buvant, et ils disent: Il a un démon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Le fils de l’homme est venu mangeant et buvant, et ils disent: Voici un mangeur et un buveur, un ami des publicains et des pécheurs. Et la sagesse a été justifiée par ses enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Alors il commença à adresser des reproches aux villes dans lesquelles le plus grand nombre de ses miracles avaient été faits, parce qu’elles ne s’étaient pas repenties:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Malheur à toi, Chorazin! malheur à toi, Bethsaïda! car si les miracles qui ont été faits au milieu de vous avaient été faits dans Tyr et dans Sidon, il y a longtemps qu’elles se seraient repenties sous le sac et la cendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Mais je vous dis que le sort de Tyr et de Sidon sera plus supportable au jour de jugement que le vôtre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Et toi, Capernaüm, qui as été élevée jusqu’au ciel, tu seras abaissée jusque dans le hadès; car si les miracles qui ont été faits au milieu de toi avaient été faits dans Sodome, elle serait demeurée jusqu’à aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Mais je vous dis que le sort du pays de Sodome sera plus supportable au jour de jugement que le tien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'En ce temps-là, Jésus répondit et dit: Je te loue, ô Père, Seigneur du ciel et de la terre, parce que tu as caché ces choses aux sages et aux intelligents, et que tu les as révélées aux petits enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Oui, Père, car c’est ce que tu as trouvé bon devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Toutes choses m’ont été livrées par mon Père; et personne ne connaît le Fils, si ce n’est le Père; ni personne ne connaît le Père, si ce n’est le Fils, et celui à qui le Fils voudra le révéler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Venez à moi, vous tous qui vous fatiguez et qui êtes chargés, et moi, je vous donnerai du repos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Prenez mon joug sur vous, et apprenez de moi, car je suis débonnaire et humble de cœur; et vous trouverez le repos de vos âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Car mon joug est aisé et mon fardeau est léger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'En ce temps-là, Jésus allait par les blés, un jour de sabbat; et ses disciples avaient faim, et se mirent à arracher des épis et à manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Et les pharisiens voyant [cela], lui dirent: Voilà, tes disciples font ce qu’il n’est pas permis de faire en un jour de sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Mais il leur dit: N’avez-vous pas lu ce que fit David, quand il eut faim, et ceux qui étaient avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'comment il entra dans la maison de Dieu et mangea les pains de proposition, qu’il ne lui était pas permis de manger ni à ceux qui étaient avec lui, mais aux sacrificateurs seuls?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Ou n’avez-vous pas lu dans la loi, que, le jour de sabbat, les sacrificateurs dans le temple profanent le sabbat et ne sont pas coupables?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Mais je vous dis qu’il y a ici quelque chose de plus grand que le temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Et si vous aviez connu ce que c’est que: « Je veux miséricorde et non pas sacrifice », vous n’auriez pas condamné ceux qui ne sont pas coupables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Car le fils de l’homme est seigneur du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Et étant parti de là, il vint dans leur synagogue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Et voici, il y avait [là] un homme qui avait la main sèche. Et ils l’interrogèrent, disant: Est-il permis de guérir, le jour de sabbat? – afin de l’accuser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Mais il leur dit: Quel sera l’homme d’entre vous, qui aura une brebis, et qui, si elle vient à tomber dans une fosse un jour de sabbat, ne la prendra et ne la relèvera pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Combien donc un homme vaut-il mieux qu’une brebis! De sorte qu’il est permis de faire du bien le jour de sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Alors il dit à l’homme: Étends ta main. Et il l’étendit, et elle fut rendue saine comme l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Et les pharisiens, étant sortis, tinrent conseil contre lui pour le faire périr;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'mais Jésus, le sachant, se retira de là; et de grandes foules le suivirent, et il les guérit tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Et il leur défendit expressément de rendre son nom public,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'afin que fût accompli ce qui a été dit par Ésaïe le prophète, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '« Voici mon serviteur que j’ai élu, mon bien-aimé, en qui mon âme a trouvé son plaisir; je mettrai mon Esprit sur lui, et il annoncera [le] jugement aux nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Il ne contestera pas, et ne criera pas, et personne n’entendra sa voix dans les rues;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'il ne brisera pas le roseau froissé, et il n’éteindra pas le lumignon qui fume, jusqu’à ce qu’il ait produit en victoire le jugement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'et les nations espéreront en son nom ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Alors il lui fut amené un démoniaque aveugle et muet, et il le guérit; de sorte que l’homme aveugle et muet parlait et voyait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Et toutes les foules étaient hors d’elles et disaient: Celui-ci serait-il le fils de David?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Mais les pharisiens, ayant entendu cela, dirent: Celui-ci ne chasse les démons que par Béelzébul, chef des démons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Et Jésus, connaissant leurs pensées, leur dit: Tout royaume divisé contre lui-même sera réduit en désert; et toute ville ou maison divisée contre elle-même ne subsistera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Et si Satan chasse Satan, il est divisé contre lui-même; comment donc son royaume subsistera-t-il?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Et si c’est par Béelzébul que moi je chasse les démons, vos fils par qui les chassent-ils? C’est pourquoi ils seront eux-mêmes vos juges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Mais si moi je chasse les démons par l’Esprit de Dieu, alors le royaume de Dieu est parvenu jusqu’à vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Ou comment quelqu’un pourra-t-il entrer dans la maison de l’homme fort et piller ses biens, si premièrement il n’a lié l’homme fort? et alors il pillera sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Celui qui n’est pas avec moi, est contre moi; et celui qui n’assemble pas avec moi, disperse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'C’est pourquoi je vous dis: tout péché et [tout] blasphème sera pardonné aux hommes; mais le blasphème contre l’Esprit ne sera pas pardonné aux hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Et quiconque aura parlé contre le fils de l’homme, il lui sera pardonné; mais quiconque aura parlé contre l’Esprit Saint, il ne lui sera pardonné ni dans ce siècle, ni dans celui qui est à venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Ou faites l’arbre bon et son fruit bon, ou faites l’arbre mauvais et son fruit mauvais, car l’arbre est connu par son fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Race de vipères, comment, étant méchants, pouvez-vous dire de bonnes choses? car de l’abondance du cœur la bouche parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'L’homme bon, du bon trésor, produit de bonnes choses, et l’homme mauvais, du mauvais trésor, produit de mauvaises choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Et je vous dis que, de toute parole oiseuse qu’ils auront dite, les hommes rendront compte au jour de jugement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'car par tes paroles tu seras justifié, et par tes paroles tu seras condamné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Alors quelques-uns des scribes et des pharisiens lui répondirent, disant: Maître, nous désirons voir un signe de ta part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Mais lui, répondant, leur dit: Une génération méchante et adultère recherche un signe; et il ne lui sera pas donné de signe, si ce n’est le signe de Jonas le prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Car, comme Jonas fut dans le ventre du cétacé trois jours et trois nuits, ainsi le fils de l’homme sera trois jours et trois nuits dans le sein de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Des hommes de Ninive se lèveront au jugement avec cette génération et la condamneront, car ils se sont repentis à la prédication de Jonas, et voici, il y a ici plus que Jonas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Une reine du midi se lèvera au jugement avec cette génération et la condamnera, car elle vint des bouts de la terre pour entendre la sagesse de Salomon, et voici, il y a ici plus que Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Or quand l’esprit immonde est sorti d’un homme, il va par des lieux secs, cherchant du repos, et il n’en trouve point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Alors il dit: Je retournerai dans ma maison d’où je suis sorti. Et y étant venu, il la trouve vide, balayée et ornée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Alors il va, et prend avec lui sept autres esprits plus méchants que lui-même; et étant entrés, ils habitent là; et la dernière condition de cet homme-là est pire que la première. Ainsi en sera-t-il aussi de cette génération méchante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Et comme il parlait encore aux foules, voici, sa mère et ses frères se tenaient dehors, cherchant à lui parler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Et quelqu’un lui dit: Voici, ta mère et tes frères se tiennent dehors, cherchant à te parler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Mais lui, répondant, dit à celui qui lui parlait: Qui est ma mère, et qui sont mes frères?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Et étendant sa main vers ses disciples, il dit: Voici ma mère et mes frères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'car quiconque fera la volonté de mon Père qui est dans les cieux, celui-là est mon frère, et ma sœur, et ma mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Et en ce jour-là, Jésus, étant sorti de la maison, s’assit près de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Et de grandes foules étaient rassemblées auprès de lui, de sorte que, montant dans un bateau, il s’assit; et toute la foule se tenait sur le rivage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Et il leur dit beaucoup de choses par des paraboles, disant: Voici, un semeur sortit pour semer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Et comme il semait, quelques [grains] tombèrent le long du chemin, et les oiseaux vinrent et les dévorèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Et d’autres tombèrent sur les endroits rocailleux, où ils n’avaient pas beaucoup de terre; et aussitôt ils levèrent, parce qu’ils n’avaient pas une terre profonde;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'et, le soleil s’étant levé, ils furent brûlés, et parce qu’ils n’avaient pas de racine, ils séchèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Et d’autres tombèrent entre les épines, et les épines montèrent et les étouffèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Et d’autres tombèrent sur une bonne terre et produisirent du fruit, l’un 100, l’autre 60, l’autre 30.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Qui a des oreilles pour entendre, qu’il entende.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Et les disciples, s’approchant, lui dirent: Pourquoi leur parles-tu en paraboles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Et lui, répondant, leur dit: C’est parce qu’à vous il est donné de connaître les mystères du royaume des cieux; mais à eux, il n’est pas donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Car à quiconque a, il sera donné, et il sera dans l’abondance; mais à quiconque n’a pas, cela même qu’il a sera ôté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'C’est pourquoi je leur parle en paraboles, parce que voyant ils ne voient pas, et qu’entendant ils n’entendent ni ne comprennent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Et par eux s’accomplit la prophétie d’Ésaïe qui dit: « En entendant vous entendrez et vous ne comprendrez point, et en voyant vous verrez et vous n’apercevrez point;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'car le cœur de ce peuple s’est épaissi, et ils ont endurci leurs oreilles, et ils ont fermé leurs yeux, de peur qu’ils ne voient des yeux, et qu’ils n’entendent des oreilles, et qu’ils ne comprennent du cœur, et qu’ils ne se convertissent, et que je ne les guérisse ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Mais bienheureux sont vos yeux, car ils voient, et vos oreilles, car elles entendent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'car en vérité, je vous dis, que plusieurs prophètes et [plusieurs] justes ont désiré de voir les choses que vous voyez, et ils ne les ont pas vues, et d’entendre les choses que vous entendez, et ils ne les ont pas entendues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Vous donc, écoutez la parabole du semeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Toutes les fois que quelqu’un entend la parole du royaume, et ne [la] comprend pas, le méchant vient et ravit ce qui est semé dans son cœur; c’est là celui qui a été semé le long du chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Et celui qui a été semé sur les endroits rocailleux, c’est celui qui entend la parole, et qui la reçoit aussitôt avec joie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'mais il n’a pas de racine en lui-même, mais n’est que pour un temps: et quand la tribulation ou la persécution survient à cause de la parole, il est aussitôt scandalisé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Et celui qui a été semé dans les épines, c’est celui qui entend la parole; et les soucis de ce siècle et la tromperie des richesses étouffent la parole, et il est sans fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Et celui qui a été semé sur la bonne terre, c’est celui qui entend et comprend la parole, qui aussi porte du fruit, et produit l’un 100, l’autre 60, l’autre 30.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Il leur proposa une autre parabole, disant: Le royaume des cieux a été fait semblable à un homme qui semait de bonne semence dans son champ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Mais pendant que les hommes dormaient, son ennemi vint et sema de l’ivraie parmi le froment, et s’en alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Et lorsque la tige monta et produisit du fruit, alors l’ivraie aussi parut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Et les esclaves du maître de la maison, s’approchant, lui dirent: Seigneur, n’as-tu pas semé de bonne semence dans ton champ? D’où vient donc qu’il a l’ivraie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Et il leur dit: Un ennemi a fait cela. Et les esclaves lui dirent: Veux-tu donc que nous allions et que nous la cueillions?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Et il dit: Non, de peur qu’en cueillant l’ivraie, vous ne déraciniez le froment avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Laissez-les croître tous deux ensemble jusqu’à la moisson; et au temps de la moisson, je dirai aux moissonneurs: Cueillez premièrement l’ivraie, et liez-la en bottes pour la brûler, mais assemblez le froment dans mon grenier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Il leur proposa une autre parabole, disant: Le royaume des cieux est semblable à un grain de moutarde qu’un homme prit et sema dans son champ:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'lequel est, il est vrai, plus petit que toutes les semences; mais quand il a pris sa croissance, il est plus grand que les herbes et devient un arbre, de sorte que les oiseaux du ciel viennent et demeurent dans ses branches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Il leur dit une autre parabole: Le royaume des cieux est semblable à du levain qu’une femme prit et qu’elle cacha parmi trois mesures de farine, jusqu’à ce que tout soit levé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Jésus dit toutes ces choses aux foules en paraboles, et sans parabole il ne leur disait rien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'en sorte que fût accompli ce qui a été dit par le prophète, disant: « J’ouvrirai ma bouche en paraboles, je proférerai des choses qui ont été cachées dès la fondation du monde ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Alors, ayant congédié les foules, il entra dans la maison; et ses disciples vinrent à lui, disant: Expose-nous la parabole de l’ivraie du champ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Et lui, répondant, leur dit: Celui qui sème la bonne semence, c’est le fils de l’homme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'et le champ, c’est le monde; et la bonne semence, ce sont les fils du royaume; et l’ivraie, ce sont les fils du méchant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'et l’ennemi qui l’a semée, c’est le diable; et la moisson, c’est la consommation du siècle; et les moissonneurs sont des anges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Comme donc l’ivraie est cueillie et brûlée au feu, il en sera de même à la consommation du siècle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Le fils de l’homme enverra ses anges, et ils cueilleront de son royaume tous les scandales et ceux qui commettent l’iniquité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'et ils les jetteront dans la fournaise de feu: là seront les pleurs et les grincements de dents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Alors les justes resplendiront comme le soleil dans le royaume de leur Père. Qui a des oreilles pour entendre, qu’il entende.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Encore, le royaume des cieux est semblable à un trésor caché dans un champ, qu’un homme, après l’avoir trouvé, a caché; et de la joie qu’il en a, il s’en va, et vend tout ce qu’il a, et achète ce champ-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Encore, le royaume des cieux est semblable à un marchand qui cherche de belles perles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'et ayant trouvé une perle de très grand prix, il s’en alla, et vendit tout ce qu’il avait, et l’acheta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Encore, le royaume des cieux est semblable à une seine jetée dans la mer et rassemblant [des poissons] de toute sorte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'et quand elle fut pleine, ils la tirèrent sur le rivage, et s’asseyant, ils mirent ensemble les bons dans des vaisseaux, et jetèrent dehors les mauvais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Il en sera de même à la consommation du siècle: les anges sortiront, et sépareront les méchants du milieu des justes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'et les jetteront dans la fournaise de feu: là seront les pleurs et les grincements de dents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Jésus leur dit: Avez-vous compris toutes ces choses? Ils lui disent: Oui, [Seigneur].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Et il leur dit: C’est pour cela que tout scribe qui a été fait disciple du royaume des cieux est semblable à un maître de maison qui produit de son trésor des choses nouvelles et des choses vieilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Et il arriva que, quand Jésus eut achevé ces paraboles, il se retira de là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Et étant venu dans son pays, il les enseignait dans leur synagogue, en sorte qu’ils étaient étonnés et disaient: D’où viennent à celui-ci cette sagesse et ces miracles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Celui-ci n’est-il pas le fils du charpentier? Sa mère ne s’appelle-t-elle pas Marie? et ses frères, Jacques, et Joses, et Simon, et Jude?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Et ses sœurs ne sont-elles pas toutes auprès de nous? D’où donc viennent à celui-ci toutes ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Et ils étaient scandalisés en lui. Et Jésus leur dit: Un prophète n’est pas sans honneur, si ce n’est dans son pays et dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Et il ne fit pas là beaucoup de miracles, à cause de leur incrédulité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'En ce temps-là, Hérode le tétrarque entendit parler de la renommée de Jésus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'et il dit à ses serviteurs: C’est Jean le baptiseur; il est ressuscité des morts, et c’est pourquoi les miracles s’opèrent par lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Car Hérode, ayant fait prendre Jean, l’avait fait lier et mettre en prison, à cause d’Hérodias, la femme de Philippe son frère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'car Jean lui disait: Il ne t’est pas permis de l’avoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Et tout en ayant le désir de le faire mourir, il craignait la foule, parce qu’ils le tenaient pour prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Mais lorsqu’on célébrait l’anniversaire de la naissance d’Hérode, la fille d’Hérodias dansa devant tous, et plut à Hérode:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'sur quoi il lui promit avec serment de lui donner tout ce qu’elle demanderait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Et elle, poussée par sa mère: Donne-moi ici, dit-elle, dans un plat, la tête de Jean le baptiseur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Et le roi en fut affligé; mais, à cause des serments et de ceux qui étaient à table avec lui, il donna l’ordre qu’on la lui donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Et il envoya décapiter Jean dans la prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Et sa tête fut apportée dans un plat et donnée à la jeune fille; et elle la porta à sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Et ses disciples vinrent et enlevèrent le corps et l’ensevelirent; et s’en allant, ils rapportèrent à Jésus [ce qui était arrivé].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Et Jésus, l’ayant entendu, se retira de là dans un bateau en un lieu désert, à l’écart; et les foules, l’ayant appris, le suivirent à pied, des [différentes] villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Et étant sorti, il vit une grande foule; et il fut ému de compassion envers eux, et il guérit leurs infirmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Et le soir étant venu, ses disciples vinrent à lui, disant: Le lieu est désert, et l’heure est déjà passée; renvoie les foules, afin qu’elles s’en aillent aux villages et qu’elles s’achètent des vivres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Mais Jésus leur dit: Il n’est pas nécessaire qu’elles s’en aillent; vous, donnez-leur à manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Mais ils lui disent: Nous n’avons ici que cinq pains et deux poissons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Et il dit: Apportez-les-moi ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Et ayant donné l’ordre aux foules de s’asseoir sur l’herbe, ayant pris les cinq pains et les deux poissons, il regarda vers le ciel et bénit; et ayant rompu les pains, il les donna aux disciples, et les disciples aux foules.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Et ils mangèrent tous et furent rassasiés. Et ils ramassèrent, des morceaux qui étaient de reste, douze paniers pleins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Or ceux qui avaient mangé étaient environ 5 000 hommes, outre les femmes et les enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Et aussitôt il contraignit les disciples de monter dans le bateau et de le précéder à l’autre rive, jusqu’à ce qu’il ait renvoyé les foules.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Et quand il eut renvoyé les foules, il monta sur une montagne à l’écart pour prier; et le soir étant venu, il était là seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Or le bateau était déjà au milieu de la mer, battu par les vagues, car le vent était contraire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Et à la quatrième veille de la nuit, il s’en alla vers eux, marchant sur la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Et les disciples, le voyant marcher sur la mer, furent troublés, disant: C’est un fantôme. Et ils crièrent de peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Mais Jésus leur parla aussitôt, disant: Ayez bon courage; c’est moi, n’ayez point de peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Et Pierre, lui répondant, dit: Seigneur, si c’est toi, commande-moi d’aller à toi sur les eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Et il dit: Viens. Et Pierre, étant descendu du bateau, marcha sur les eaux pour aller à Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Mais voyant que le vent était fort, il eut peur; et comme il commençait à enfoncer, il s’écria, disant: Seigneur, sauve-moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Et aussitôt Jésus, étendant la main, le prit et lui dit: Homme de petite foi, pourquoi as-tu douté?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Et quand ils furent montés dans le bateau, le vent tomba.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Et ceux qui étaient dans le bateau vinrent et lui rendirent hommage, disant: Véritablement tu es le Fils de Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Et ayant passé à l’autre rive, ils vinrent dans la contrée de Génésareth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Et les hommes de ce lieu-là, l’ayant reconnu, envoyèrent dans tout le pays d’alentour; et on lui apporta tous ceux qui se portaient mal;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'et ils le priaient de [les laisser] toucher seulement le bord de sa robe: et tous ceux qui le touchèrent furent complètement guéris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Alors les scribes et les pharisiens de Jérusalem viennent à Jésus, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Pourquoi tes disciples transgressent-ils la tradition des anciens, car ils ne lavent pas leurs mains quand ils mangent du pain?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Mais lui, répondant, leur dit: Et vous, pourquoi transgressez-vous le commandement de Dieu à cause de votre tradition?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'car Dieu a commandé, disant: « Honore ton père et ta mère »; et: « que celui qui médira de père ou de mère, meure de mort »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'mais vous, vous dites: Quiconque dira à son père ou à sa mère: Tout ce dont tu pourrais tirer profit de ma part est un don,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, '– et il n’honorera point son père ou sa mère. Et vous avez annulé le commandement de Dieu à cause de votre tradition.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Hypocrites! Ésaïe a bien prophétisé de vous, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '« Ce peuple m’honore des lèvres, mais leur cœur est fort éloigné de moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'mais ils m’honorent en vain, enseignant comme doctrines des commandements d’hommes ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Et ayant appelé la foule, il leur dit: Écoutez et comprenez:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'ce n’est pas ce qui entre dans la bouche qui souille l’homme; mais ce qui sort de la bouche, c’est là ce qui souille l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Alors ses disciples, s’approchant, lui dirent: Sais-tu que les pharisiens ont été scandalisés en entendant cette parole?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Mais lui, répondant, dit: Toute plante que mon Père céleste n’a pas plantée sera déracinée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Laissez-les; ce sont des aveugles, conducteurs d’aveugles: et si un aveugle conduit un aveugle, ils tomberont tous deux dans une fosse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Et Pierre, répondant, lui dit: Expose-nous cette parabole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Et il dit: Et vous aussi, êtes-vous encore sans intelligence?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'N’entendez-vous pas encore que tout ce qui entre dans la bouche va dans le ventre, et passe ensuite dans les lieux d’aisances?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Mais les choses qui sortent de la bouche viennent du cœur, et ces choses-là souillent l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Car du cœur viennent les mauvaises pensées, les meurtres, les adultères, les fornications, les vols, les faux témoignages, les injures:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'ce sont ces choses qui souillent l’homme; mais de manger avec des mains non lavées ne souille pas l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Et Jésus, partant de là, se retira dans les quartiers de Tyr et de Sidon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Et voici, une femme cananéenne de ces contrées-là, sortant, s’écria, lui disant: Seigneur, Fils de David, aie pitié de moi; ma fille est cruellement tourmentée d’un démon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Et il ne lui répondit mot. Et ses disciples, s’approchant, le prièrent, disant: Renvoie-la, car elle crie après nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Mais lui, répondant, dit: Je ne suis envoyé qu’ aux brebis perdues de la maison d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Et elle vint et lui rendit hommage, disant: Seigneur, assiste-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Et lui, répondant, dit: Il ne convient pas de prendre le pain des enfants et de le jeter aux chiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Et elle dit: Oui, Seigneur; car même les chiens mangent des miettes qui tombent de la table de leurs maîtres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Alors Jésus, répondant, lui dit: Ô femme, ta foi est grande; qu’il te soit fait comme tu veux. Et dès cette heure-là sa fille fut guérie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Et Jésus, étant parti de là, vint près de la mer de Galilée; et montant sur une montagne, il s’assit là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Et de grandes foules vinrent à lui, ayant avec elles des boiteux, des aveugles, des muets, des estropiés, et beaucoup d’autres; et elles les jetèrent à ses pieds, et il les guérit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'de sorte que les foules s’étonnèrent en voyant les muets parler, les estropiés guérir, les boiteux marcher, et les aveugles voir; et elles glorifièrent le Dieu d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Et Jésus, ayant appelé à lui ses disciples, dit: Je suis ému de compassion envers la foule, car voici trois jours déjà qu’ils demeurent auprès de moi, et ils n’ont rien à manger; et je ne veux pas les renvoyer à jeun, de peur qu’ils ne défaillent en chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Et ses disciples lui disent: D’où aurions-nous dans le désert assez de pains pour rassasier une si grande foule?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Et Jésus leur dit: Combien avez-vous de pains? Et ils dirent: Sept, et quelques petits poissons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Et il commanda aux foules de s’asseoir sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Et ayant pris les sept pains et les poissons, il rendit grâces et les rompit et les donna à ses disciples, et les disciples à la foule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Et ils mangèrent tous et furent rassasiés; et ils ramassèrent, des morceaux qui étaient de reste, sept corbeilles pleines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Or ceux qui avaient mangé étaient 4 000 hommes, outre les femmes et les enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Et ayant renvoyé les foules, il monta dans un bateau et vint dans la contrée de Magadan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Et les pharisiens et les sadducéens, s’approchant, lui demandèrent, pour l’éprouver, de leur montrer un signe du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Mais lui, répondant, leur dit: Quand le soir est venu, vous dites: Il fera beau temps, car le ciel est rouge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'et le matin: Il y aura aujourd’hui de l’orage, car le ciel est rouge et sombre. Vous savez discerner l’apparence du ciel; et ne pouvez-vous pas [discerner] les signes des temps?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Une génération méchante et adultère recherche un signe; et il ne lui sera pas donné de signe, si ce n’est le signe de Jonas. Et les laissant, il s’en alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Et quand les disciples furent venus à l’autre rive, ils avaient oublié de prendre du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Et Jésus leur dit: Voyez, et soyez en garde contre le levain des pharisiens et des sadducéens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Et ils raisonnaient en eux-mêmes, disant: C’est parce que nous n’avons pas pris du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Mais Jésus, le sachant, dit: Pourquoi raisonnez-vous en vous-mêmes, gens de petite foi, sur ce que vous n’avez pas pris du pain?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'N’entendez-vous pas encore, et ne vous souvient-il pas des cinq pains des 5 000 hommes, et combien de paniers vous en avez recueillis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'ni des sept pains des 4 000 hommes, et combien de corbeilles vous en avez recueillies?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Comment n’entendez-vous pas que ce n’était pas touchant du pain que je vous disais: Soyez en garde contre le levain des pharisiens et des sadducéens?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Alors ils comprirent que ce n’était pas contre le levain du pain qu’il leur avait dit d’être en garde, mais contre la doctrine des pharisiens et des sadducéens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Or, lorsque Jésus fut venu aux quartiers de Césarée de Philippe, il interrogea ses disciples, disant: Qui disent les hommes que je suis, moi, le fils de l’homme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Et ils dirent: Les uns [disent]: Jean le baptiseur; les autres: Élie; et d’autres: Jérémie ou l’un des prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Il leur dit: Et vous, qui dites-vous que je suis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Et Simon Pierre, répondant, dit: Tu es le Christ, le Fils du Dieu vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Et Jésus, répondant, lui dit: Tu es bienheureux, Simon Barjonas, car la chair et le sang ne t’ont pas révélé [cela], mais mon Père qui est dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Et moi aussi, je te dis que tu es Pierre; et sur ce roc je bâtirai mon assemblée, et [les] portes du hadès ne prévaudront pas contre elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Et je te donnerai les clés du royaume des cieux; et tout ce que tu lieras sur la terre sera lié dans les cieux; et tout ce que tu délieras sur la terre sera délié dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Alors il enjoignit aux disciples de ne dire à personne qu’il était le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Dès lors Jésus commença à montrer à ses disciples qu’il fallait qu’il aille à Jérusalem, et qu’il souffre beaucoup de la part des anciens et des principaux sacrificateurs et des scribes, et qu’il soit mis à mort, et qu’il soit ressuscité le troisième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Et Pierre, le prenant à part, se mit à le reprendre, disant: Seigneur, Dieu t’en préserve, cela ne t’arrivera point!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Mais lui, se retournant, dit à Pierre: Va arrière de moi, Satan, tu m’es en scandale; car tes pensées ne sont pas aux choses de Dieu, mais à celles des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Alors Jésus dit à ses disciples: Si quelqu’un veut venir après moi, qu’il se renonce soi-même, et qu’il prenne sa croix, et me suive:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'car quiconque voudra sauver sa vie la perdra; et quiconque perdra sa vie pour l’amour de moi, la trouvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Car que profitera-t-il à un homme s’il gagne le monde entier, et qu’il fasse la perte de son âme; ou que donnera un homme en échange de son âme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Car le fils de l’homme viendra dans la gloire de son Père, avec ses anges, et alors il rendra à chacun selon sa conduite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'En vérité, je vous dis: Il y en a quelques-uns de ceux qui sont ici présents, qui ne goûteront point la mort jusqu’à ce qu’ils aient vu le fils de l’homme venant dans son royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Et après six jours, Jésus prend avec lui Pierre, et Jacques, et Jean son frère, et les mène à l’écart sur une haute montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Et il fut transfiguré devant eux; et son visage resplendit comme le soleil, et ses vêtements devinrent blancs comme la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Et voici, Moïse et Élie leur apparurent, parlant avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Et Pierre, répondant, dit à Jésus: Seigneur, il est bon que nous soyons ici; si tu le veux, faisons ici trois tentes: une pour toi, et une pour Moïse, et une pour Élie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Comme il parlait encore, voici, une nuée lumineuse les couvrit; et voici une voix de la nuée, disant: Celui-ci est mon fils bien-aimé, en qui j’ai trouvé mon plaisir; écoutez-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Ce que les disciples ayant entendu, ils tombèrent le visage contre terre et furent saisis d’une très grande peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Et Jésus, s’approchant, les toucha et dit: Levez-vous, et n’ayez point de peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Et eux, levant leurs yeux, ne virent personne que Jésus seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Et comme ils descendaient de la montagne, Jésus leur enjoignit, disant: Ne dites à personne la vision, jusqu’à ce que le fils de l’homme soit ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Et ses disciples l’interrogèrent, disant: Pourquoi donc les scribes disent-ils qu’il faut qu’Élie vienne premièrement?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Et lui, répondant, leur dit: En effet, Élie vient premièrement, et il rétablira toutes choses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'mais je vous dis qu’Élie est déjà venu, et ils ne l’ont pas reconnu; mais ils lui ont fait tout ce qu’ils ont voulu; ainsi aussi le fils de l’homme va souffrir de leur part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Alors les disciples comprirent qu’il leur parlait de Jean le baptiseur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Et quand ils furent venus auprès de la foule, un homme s’approcha de lui, se jetant à genoux devant lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'et disant: Seigneur, aie pitié de mon fils, car il est lunatique et souffre cruellement, car souvent il tombe dans le feu, et souvent dans l’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'et je l’ai apporté à tes disciples, et ils n’ont pu le guérir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Et Jésus, répondant, dit: Ô génération incrédule et perverse, jusques à quand serai-je avec vous; jusques à quand vous supporterai-je? Amenez-le-moi ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Et Jésus le tança; et le démon sortit de lui; et le jeune garçon fut guéri dès cette heure-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Alors les disciples, venant à Jésus à l’écart, dirent: Pourquoi n’avons-nous pu le chasser?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Et Jésus leur dit: À cause de votre incrédulité; car, en vérité, je vous dis: si vous aviez de la foi comme un grain de moutarde, vous diriez à cette montagne: Transporte-toi d’ici là, et elle se transporterait; et rien ne vous serait impossible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Mais cette sorte ne sort que par la prière et par le jeûne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Et comme ils séjournaient en Galilée, Jésus leur dit: Le fils de l’homme va être livré entre les mains des hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'et ils le feront mourir; et le troisième jour il sera ressuscité. Et ils furent fort attristés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Et lorsqu’ils furent venus à Capernaüm, les receveurs des didrachmes vinrent à Pierre, et dirent: Votre maître ne paie-t-il pas les didrachmes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Il dit: Oui. Et quand il fut entré dans la maison, Jésus le prévint, disant: Que t’en semble, Simon? Les rois de la terre, de qui reçoivent-ils des tributs ou des impôts, de leurs fils ou des étrangers?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Pierre lui dit: Des étrangers. Jésus lui dit: Les fils en sont donc exempts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Mais, afin que nous ne les scandalisions pas, va-t’en à la mer, jette un hameçon, et prends le premier poisson qui montera; et quand tu lui auras ouvert la bouche, tu y trouveras un statère; prends-le, et donne-le-leur pour moi et pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'En cette heure-là les disciples vinrent à Jésus, disant: Qui donc est le plus grand dans le royaume des cieux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Et Jésus, ayant appelé auprès de lui un petit enfant, le plaça au milieu d’eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'et dit: En vérité, je vous dis: si vous ne vous convertissez et ne devenez comme les petits enfants, vous n’entrerez point dans le royaume des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Quiconque donc s’abaissera comme ce petit enfant, celui-là est le plus grand dans le royaume des cieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'et quiconque reçoit un seul petit enfant tel que celui-ci en mon nom, me reçoit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Et quiconque est une occasion de chute pour un de ces petits qui croient en moi, il serait avantageux pour lui qu’on lui ait pendu au cou une meule d’âne et qu’il ait été noyé dans les profondeurs de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Malheur au monde à cause des occasions de chute! car il est nécessaire qu’il arrive des occasions de chute; mais malheur à cet homme par qui l’occasion de chute arrive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Et si ta main ou ton pied est pour toi une occasion de chute, coupe-les et jette-les loin de toi: il vaut mieux pour toi d’entrer dans la vie boiteux ou estropié, que d’avoir deux mains ou deux pieds, et d’être jeté dans le feu éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Et si ton œil est pour toi une occasion de chute, arrache-le et jette-le loin de toi; car il vaut mieux pour toi d’entrer dans la vie n’ayant qu’un œil, que d’avoir deux yeux, et d’être jeté dans la géhenne du feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Prenez garde de ne pas mépriser un de ces petits; car je vous dis que, dans les cieux, leurs anges voient continuellement la face de mon Père qui est dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Car le fils de l’homme est venu pour sauver ce qui était perdu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Que vous en semble? Si un homme a 100 brebis, et que l’une d’elles se soit égarée, ne laisse-t-il pas les 99 sur les montagnes, pour s’en aller chercher celle qui s’est égarée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Et s’il arrive qu’il la trouve, – en vérité, je vous dis qu’il a plus de joie de celle-là que des 99 qui ne se sont pas égarées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Ainsi, ce n’est pas la volonté de votre Père qui est dans les cieux, qu’un seul de ces petits périsse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Et si ton frère pèche contre toi, va, reprends-le, entre toi et lui seul; s’il t’écoute, tu as gagné ton frère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'mais s’il ne t’écoute pas, prends avec toi encore une ou deux personnes, afin que par la bouche de deux ou de trois témoins toute parole soit établie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Et s’il ne veut pas les écouter, dis-le à l’assemblée; et s’il ne veut pas écouter l’assemblée non plus, qu’il te soit comme un homme des nations et comme un publicain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'En vérité, je vous dis: Tout ce que vous lierez sur la terre sera lié dans le ciel, et tout ce que vous délierez sur la terre sera délié dans le ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Je vous dis encore que si deux d’entre vous sont d’accord sur la terre pour une chose quelconque, quelle que soit la chose qu’ils demanderont, elle sera faite pour eux par mon Père qui est dans les cieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'car là où deux ou trois sont assemblés en mon nom, je suis là au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Alors Pierre, s’approchant de lui, dit: Seigneur, combien de fois mon frère péchera-t-il contre moi, et lui pardonnerai-je? Sera-ce jusqu’à sept fois?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jésus lui dit: Je ne te dis pas jusqu’à sept fois, mais jusqu’à 70 fois sept fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'C’est pourquoi le royaume des cieux a été fait semblable à un roi qui voulut compter avec ses esclaves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Et quand il eut commencé à compter, on lui en amena un qui lui devait 10 000 talents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Et comme il n’avait pas de quoi payer, son seigneur ordonna qu’il soit vendu, [lui], et sa femme, et ses enfants, et tout ce qu’il avait; et que le paiement soit fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'L’esclave donc, se jetant à ses pieds, lui rendit hommage, disant: Seigneur, use de patience envers moi, et je te paierai tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Et le seigneur de cet esclave-là, touché de compassion, le relâcha et lui remit la dette.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Mais cet esclave, étant sorti, trouva un de ceux qui étaient esclaves avec lui, qui lui devait 100 deniers; et l’ayant saisi, il l’étranglait, disant: Paie, si tu dois quelque chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Celui donc qui était esclave avec lui, se jetant à ses pieds, le supplia, disant: Use de patience envers moi, et je te paierai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Et il ne voulut pas; mais il s’en alla et le jeta en prison jusqu’à ce qu’il ait payé la dette.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Or ceux qui étaient esclaves avec lui, voyant ce qui était arrivé, furent extrêmement affligés, et s’en vinrent et déclarèrent à leur seigneur tout ce qui s’était passé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Alors son seigneur, l’ayant appelé auprès de lui, lui dit: Méchant esclave, je t’ai remis toute cette dette, parce que tu m’en as supplié;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'n’aurais-tu pas dû aussi avoir pitié de celui qui est esclave avec toi, comme moi aussi j’ai eu pitié de toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Et son seigneur, étant en colère, le livra aux bourreaux, jusqu’à ce qu’il ait payé tout ce qui lui était dû.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Ainsi aussi mon Père céleste vous fera, si vous ne pardonnez pas de tout votre cœur, chacun à son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Et il arriva, quand Jésus eut achevé ces discours, qu’il partit de la Galilée et vint vers les confins de la Judée, au-delà du Jourdain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'et de grandes foules le suivirent, et il les guérit là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Et les pharisiens vinrent à lui, l’éprouvant et [lui] disant: Est-il permis à un homme de répudier sa femme pour quelque cause que ce soit?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Et lui, répondant, leur dit: N’avez-vous pas lu que celui qui les a faits, dès le commencement les a faits mâle et femelle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'et qu’il dit: « C’est pourquoi, l’homme laissera son père et sa mère et sera uni à sa femme; et les deux seront une seule chair »?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Ainsi, ils ne sont plus deux, mais une seule chair. Ce donc que Dieu a uni, que l’homme ne le sépare pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Ils lui disent: Pourquoi donc Moïse a-t-il commandé de donner une lettre de divorce, et de la répudier?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Il leur dit: Moïse, à cause de votre dureté de cœur, vous a permis de répudier vos femmes; mais au commencement il n’en était pas ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Et je vous dis que quiconque répudiera sa femme, non pour cause de fornication, et en épousera une autre, commet adultère; et celui qui épouse une femme répudiée, commet adultère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Ses disciples lui disent: Si telle est la condition de l’homme à l’égard de la femme, il ne convient pas de se marier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Mais il leur dit: Tous ne reçoivent pas cette parole, mais ceux à qui il est donné;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'car il y a des eunuques qui sont nés tels dès le ventre de leur mère; et il y a des eunuques qui ont été faits eunuques par les hommes; et il y a des eunuques qui se sont faits eux-mêmes eunuques pour le royaume des cieux. Que celui qui peut le recevoir, le reçoive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Alors on lui apporta de petits enfants, afin qu’il leur impose les mains et qu’il prie; mais les disciples reprenaient ceux [qui les apportaient].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Et Jésus dit: Laissez venir à moi les petits enfants, et ne les en empêchez pas; car à de tels est le royaume des cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Et leur ayant imposé les mains, il partit de là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Et voici, quelqu’un s’approchant, lui dit: Maître, quel bien ferai-je pour avoir la vie éternelle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Et il lui dit: Pourquoi m’interroges-tu touchant ce qui est bon? Un seul est bon. Mais si tu veux entrer dans la vie, garde les commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Il lui dit: Lesquels? Et Jésus dit: Tu ne tueras point; tu ne commettras point adultère; tu ne déroberas point; tu ne diras point de faux témoignage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'honore ton père et ta mère; et, tu aimeras ton prochain comme toi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Le jeune homme lui dit: J’ai gardé toutes ces choses; que me manque-t-il encore?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jésus lui dit: Si tu veux être parfait, va, vends ce que tu as, et donne aux pauvres; et tu auras un trésor dans le ciel; et viens, suis-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Et le jeune homme, ayant entendu cette parole, s’en alla tout triste, car il avait de grands biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Et Jésus dit à ses disciples: En vérité, je vous dis qu’un riche entrera difficilement dans le royaume des cieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'et je vous le dis encore: Il est plus facile qu’un chameau entre par un trou d’aiguille, qu’un riche n’entre dans le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Et les disciples, l’ayant entendu, s’étonnèrent fort, disant: Qui donc peut être sauvé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Et Jésus, [les] regardant, leur dit: Pour les hommes, cela est impossible; mais pour Dieu, toutes choses sont possibles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Alors Pierre, répondant, lui dit: Voici, nous avons tout quitté et nous t’avons suivi; que nous adviendra-t-il donc?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Et Jésus leur dit: En vérité, je vous dis que vous qui m’avez suivi, – dans la régénération, quand le fils de l’homme se sera assis sur le trône de sa gloire, vous aussi, vous serez assis sur douze trônes, jugeant les douze tribus d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'et quiconque aura quitté maisons, ou frères, ou sœurs, ou père, ou mère, ou femme, ou enfants, ou champs, pour l’amour de mon nom, en recevra 100 fois autant, et héritera de la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Mais plusieurs qui sont les premiers seront les derniers, et des derniers seront les premiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Car le royaume des cieux est semblable à un maître de maison qui sortit dès le point du jour afin de louer des ouvriers pour sa vigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Et étant tombé d’accord avec les ouvriers pour un denier par jour, il les envoya dans sa vigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Et sortant vers la troisième heure, il en vit d’autres qui étaient sur la place du marché à ne rien faire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'et il dit à ceux-ci: Allez, vous aussi, dans la vigne, et je vous donnerai ce qui sera juste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'et ils s’en allèrent. Sortant encore vers la sixième heure et vers la neuvième heure, il fit de même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Et sortant vers la onzième heure, il en trouva d’autres qui étaient là; et il leur dit: Pourquoi vous tenez-vous ici tout le jour sans rien faire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Ils lui disent: Parce que personne ne nous a engagés. Il leur dit: Allez, vous aussi, dans la vigne, et vous recevrez ce qui sera juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Et le soir étant venu, le maître de la vigne dit à son intendant: Appelle les ouvriers, et paie-leur leur salaire, en commençant depuis les derniers jusqu’aux premiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Et lorsque ceux [qui avaient été engagés] vers la onzième heure furent venus, ils reçurent chacun un denier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'et quand les premiers furent venus, ils croyaient recevoir davantage, mais ils reçurent, eux aussi, chacun un denier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Et l’ayant reçu, ils murmuraient contre le maître de maison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'disant: Ces derniers n’ont travaillé qu’une heure, et tu les as faits égaux à nous qui avons porté le faix du jour et la chaleur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Et lui, répondant, dit à l’un d’entre eux: Mon ami, je ne te fais pas tort: n’es-tu pas tombé d’accord avec moi pour un denier?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Prends ce qui est à toi et va-t’en. Mais je veux donner à ce dernier autant qu’à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Ne m’est-il pas permis de faire ce que je veux de ce qui est mien? Ton œil est-il méchant, parce que moi, je suis bon?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Ainsi les derniers seront les premiers, et les premiers les derniers, car il y a beaucoup d’appelés, mais peu d’élus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Et Jésus, montant à Jérusalem, prit à part sur le chemin les douze disciples, et leur dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Voici, nous montons à Jérusalem, et le fils de l’homme sera livré aux principaux sacrificateurs et aux scribes, et ils le condamneront à mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'et ils le livreront aux nations pour s’en moquer, et le fouetter, et le crucifier; et le troisième jour il ressuscitera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Alors la mère des fils de Zébédée vint à lui avec ses fils, [lui] rendant hommage et lui demandant quelque chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Et il lui dit: Que veux-tu? Elle lui dit: Ordonne que mes deux fils que voici, s’asseyent, l’un à ta droite et l’un à ta gauche, dans ton royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Et Jésus, répondant, dit: Vous ne savez ce que vous demandez. Pouvez-vous boire la coupe que moi, je vais boire? Ils lui disent: Nous le pouvons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Et il leur dit: Vous boirez bien ma coupe; mais de s’asseoir à ma droite et à ma gauche, n’est pas à moi pour le donner, sinon à ceux pour lesquels cela est préparé par mon Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Et les dix, l’ayant entendu, furent indignés à l’égard des deux frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Et Jésus, les ayant appelés auprès de lui, dit: Vous savez que les chefs des nations dominent sur elles, et que les grands usent d’autorité sur elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Il n’en sera pas ainsi parmi vous; mais quiconque voudra devenir grand parmi vous sera votre serviteur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'et quiconque voudra être le premier parmi vous, qu’il soit votre esclave;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'de même que le fils de l’homme n’est pas venu pour être servi, mais pour servir et pour donner sa vie en rançon pour plusieurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Et comme ils sortaient de Jéricho, une grande foule le suivit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Et voici, deux aveugles assis sur le bord du chemin, ayant entendu que Jésus passait, s’écrièrent, disant: Aie pitié de nous, Seigneur, Fils de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Et la foule les reprit, afin qu’ils se taisent; mais ils criaient plus fort, disant: Aie pitié de nous, Seigneur, Fils de David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Et Jésus, s’arrêtant, les appela et dit: Que voulez-vous que je vous fasse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Ils lui disent: Seigneur, que nos yeux soient ouverts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Et Jésus, ému de compassion, toucha leurs yeux; et aussitôt leurs yeux recouvrèrent la vue; et ils le suivirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Et quand ils approchèrent de Jérusalem et qu’ils furent arrivés à Bethphagé, vers la montagne des Oliviers, alors Jésus envoya deux disciples,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'leur disant: Allez au village qui est vis-à-vis de vous, et aussitôt vous trouverez une ânesse attachée, et un ânon avec elle; détachez-les et amenez-les-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Et si quelqu’un vous dit quelque chose, vous direz: Le Seigneur en a besoin; et aussitôt il les enverra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Et tout cela arriva, afin que fût accompli ce qui avait été dit par le prophète, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '« Dites à la fille de Sion: Voici, ton roi vient à toi, débonnaire et monté sur une ânesse et sur un ânon, le petit d’une ânesse ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Et les disciples, s’en étant allés et ayant fait comme Jésus leur avait ordonné,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'amenèrent l’ânesse et l’ânon, et mirent leurs vêtements dessus; et il s’y assit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Et une immense foule étendit ses vêtements sur le chemin, et d’autres coupaient des rameaux des arbres et les répandaient sur le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Et les foules qui allaient devant lui, et celles qui suivaient, criaient, disant: Hosanna au fils de David! Béni soit celui qui vient au nom du ✶Seigneur! Hosanna dans les lieux très hauts!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Et comme il entrait dans Jérusalem, toute la ville fut émue, disant: Qui est celui-ci?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Et les foules disaient: Celui-ci est Jésus, le prophète, qui est de Nazareth de Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Et Jésus entra dans le temple de Dieu, et chassa dehors tous ceux qui vendaient et qui achetaient dans le temple; et il renversa les tables des changeurs et les sièges de ceux qui vendaient les colombes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'et il leur dit: Il est écrit: « Ma maison sera appelée une maison de prière »; mais vous, vous en avez fait une caverne de voleurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Et des aveugles et des boiteux vinrent à lui dans le temple, et il les guérit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Et les principaux sacrificateurs et les scribes, voyant les merveilles qu’il faisait, et les enfants criant dans le temple et disant: Hosanna au fils de David! en furent indignés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'et lui dirent: Entends-tu ce que ceux-ci disent? Mais Jésus leur dit: Sans doute; n’avez-vous jamais lu: « Par la bouche des petits enfants et de ceux qui tètent, tu as établi ta louange »?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Et les ayant laissés, il sortit de la ville [et s’en alla] à Béthanie; et il y passa la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Et le matin, comme il retournait à la ville, il eut faim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Et voyant un figuier sur le chemin, il s’en approcha; et il n’y trouva rien que des feuilles; et il lui dit: Que jamais aucun fruit ne naisse plus de toi! Et à l’instant le figuier sécha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Et les disciples, le voyant, en furent étonnés, disant: Comment en un instant le figuier est-il devenu sec!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Et Jésus, répondant, leur dit: En vérité, je vous dis: Si vous avez de la foi et que vous ne doutiez pas, non seulement vous ferez ce qui [a été fait] au figuier, mais si même vous disiez à cette montagne: Ôte-toi et jette-toi dans la mer, cela se ferait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Et quoi que vous demandiez en priant, si vous croyez, vous le recevrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Et quand il fut entré dans le temple, les principaux sacrificateurs et les anciens du peuple vinrent à lui, comme il enseignait, disant: Par quelle autorité fais-tu ces choses, et qui t’a donné cette autorité?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Et Jésus, répondant, leur dit: Je vous demanderai, moi aussi, une chose; et si vous me la dites, je vous dirai, moi aussi, par quelle autorité je fais ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Le baptême de Jean, d’où était-il? du ciel, ou des hommes? Et ils raisonnaient en eux-mêmes, disant: Si nous disons: Du ciel, il nous dira: Pourquoi donc ne l’avez-vous pas cru?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Et si nous disons: Des hommes, nous craignons la foule, car tous tiennent Jean pour un prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Et, répondant, ils dirent à Jésus: Nous ne savons. Lui aussi leur dit: Moi non plus, je ne vous dis pas par quelle autorité je fais ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Mais que vous en semble? Un homme avait deux enfants; et venant au premier, il dit: [Mon] enfant, va aujourd’hui travailler dans ma vigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Et lui, répondant, dit: Je ne veux pas; mais après, ayant du remords, il y alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Et venant au second, il dit la même chose; et lui, répondant, dit: Moi [j’y vais], seigneur; et il n’y alla pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Lequel des deux fit la volonté du père? Ils lui disent: Le premier. Jésus leur dit: En vérité, je vous dis que les publicains et les prostituées vous devancent dans le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Car Jean est venu à vous dans la voie de la justice, et vous ne l’avez pas cru; mais les publicains et les prostituées l’ont cru; et vous, l’ayant vu, vous n’en avez pas eu de remords ensuite pour le croire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Écoutez une autre parabole: Il y avait un maître de maison, qui planta une vigne, et l’environna d’une clôture, et y creusa un pressoir, et y bâtit une tour; et il la loua à des cultivateurs et s’en alla hors du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Et lorsque la saison des fruits approcha, il envoya ses esclaves aux cultivateurs pour recevoir ses fruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Et les cultivateurs, ayant pris ses esclaves, battirent l’un, tuèrent l’autre, et en lapidèrent un autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Il envoya encore d’autres esclaves en plus grand nombre que les premiers, et ils leur firent de même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Et enfin, il envoya auprès d’eux son fils, disant: Ils auront du respect pour mon fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Mais les cultivateurs, voyant le fils, dirent entre eux: Celui-ci est l’héritier; venez, tuons-le, et possédons son héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Et l’ayant pris, ils le jetèrent hors de la vigne et le tuèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Quand donc le maître de la vigne viendra, que fera-t-il à ces cultivateurs-là?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Ils lui disent: Il fera périr misérablement ces méchants, et louera sa vigne à d’autres cultivateurs qui lui remettront les fruits en leur saison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jésus leur dit: N’avez-vous jamais lu dans les écritures: « La pierre que ceux qui bâtissaient ont rejetée, celle-là est devenue la maîtresse pierre du coin; celle-ci est de par le ✶Seigneur, et est merveilleuse devant nos yeux »?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'C’est pourquoi je vous dis que le royaume de Dieu vous sera ôté, et sera donné à une nation qui en rapportera les fruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Et celui qui tombera sur cette pierre sera brisé; mais celui sur qui elle tombera, elle le broiera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Les principaux sacrificateurs et les pharisiens, ayant entendu ses paraboles, connurent qu’il parlait d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Et, cherchant à se saisir de lui, ils craignaient les foules, parce qu’elles le tenaient pour un prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Et Jésus, répondant, leur parla encore en paraboles, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Le royaume des cieux a été fait semblable à un roi qui fit des noces pour son fils,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'et envoya ses esclaves pour convier ceux qui étaient invités aux noces; et ils ne voulurent pas venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Il envoya encore d’autres esclaves, disant: Dites aux conviés: Voici, j’ai apprêté mon dîner; mes taureaux et mes bêtes grasses sont tués et tout est prêt: venez aux noces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Mais eux, n’en ayant pas tenu compte, s’en allèrent, l’un à son champ, et un autre à son trafic;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'et les autres, s’étant saisis de ses esclaves, les outragèrent et les tuèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Et le roi, [l’ayant entendu, en] fut irrité; et ayant envoyé ses troupes, il fit périr ces meurtriers-là et brûla leur ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Alors il dit à ses esclaves: Les noces sont prêtes, mais les conviés n’en étaient pas dignes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'allez donc dans les carrefours des chemins, et autant de gens que vous trouverez, conviez-les aux noces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Et ces esclaves-là, étant sortis, [s’en allèrent] par les chemins, et assemblèrent tous ceux qu’ils trouvèrent, tant mauvais que bons; et la [salle] des noces fut remplie de gens qui étaient à table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Et le roi, étant entré pour voir ceux qui étaient à table, aperçut là un homme qui n’était pas vêtu d’une robe de noces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Et il lui dit: Ami, comment es-tu entré ici, sans avoir une robe de noces? Et il eut la bouche fermée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Alors le roi dit aux serviteurs: Liez-le pieds et mains, emportez-le, et jetez-le dans les ténèbres de dehors: là seront les pleurs et les grincements de dents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Car il y a beaucoup d’appelés, mais peu d’élus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Alors les pharisiens vinrent et tinrent conseil pour l’enlacer dans [ses] paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Et ils lui envoient leurs disciples avec les hérodiens, disant: Maître, nous savons que tu es vrai et que tu enseignes la voie de Dieu en vérité, et que tu ne t’embarrasses de personne, car tu ne regardes pas à l’apparence des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Dis-nous donc, que t’en semble: est-il permis de payer le tribut à César, ou non?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Et Jésus, connaissant leur méchanceté, dit: Pourquoi me tentez-vous, hypocrites?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Montrez-moi la monnaie du tribut. Et ils lui apportèrent un denier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Et il leur dit: De qui est cette image et cette inscription?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Ils lui disent: De César. Alors il leur dit: Rendez donc les choses de César à César, et les choses de Dieu à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Et l’ayant entendu, ils furent étonnés; et le laissant, ils s’en allèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'En ce jour-là, des sadducéens, qui disent qu’il n’y a pas de résurrection, vinrent à lui et l’interrogèrent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'disant: Maître, Moïse dit: Si quelqu’un meurt n’ayant pas d’enfants, son frère épousera sa femme, et suscitera de la postérité à son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Or il y avait parmi nous sept frères; et le premier s’étant marié, mourut, et n’ayant pas de postérité, il laissa sa femme à son frère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'de la même manière le second aussi et le troisième, jusqu’au septième;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'et après eux tous, la femme aussi mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Dans la résurrection donc, duquel des sept sera-t-elle la femme, car tous l’ont eue?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Et Jésus, répondant, leur dit: Vous errez, ne connaissant pas les écritures, ni la puissance de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'car, dans la résurrection, on ne se marie ni on n’est donné en mariage, mais on est comme des anges de Dieu dans le ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Et quant à la résurrection des morts, n’avez-vous pas lu ce qui vous est dit par Dieu, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '« Moi, je suis le Dieu d’Abraham, et le Dieu d’Isaac, et le Dieu de Jacob »? Dieu n’est pas le Dieu des morts, mais des vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Et les foules, ayant entendu [cela], s’étonnèrent de sa doctrine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Et les pharisiens, ayant entendu dire qu’il avait fermé la bouche aux sadducéens, s’assemblèrent en un même lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Et l’un d’eux, docteur de la loi, l’interrogea pour l’éprouver, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Maître, quel est le grand commandement dans la loi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Et il lui dit: « Tu aimeras le ✶Seigneur ton Dieu de tout ton cœur, et de toute ton âme, et de toute ta pensée ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'C’est là le grand et premier commandement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Et le second lui est semblable: « Tu aimeras ton prochain comme toi-même ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'De ces deux commandements dépendent la loi tout entière et les prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Et les pharisiens étant assemblés, Jésus les interrogea,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'disant: Que vous semble-t-il du Christ? – de qui est-il fils? Ils lui disent: De David.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Il leur dit: Comment donc David, en Esprit, l’appelle-t-il seigneur, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '« Le ✶Seigneur a dit à mon seigneur: Assieds-toi à ma droite, jusqu’à ce que je mette tes ennemis sous tes pieds »?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Si donc David l’appelle seigneur, comment est-il son fils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Et personne ne pouvait lui répondre un mot; et personne, depuis ce jour-là, n’osa plus l’interroger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Alors Jésus parla aux foules et à ses disciples,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'disant: Les scribes et les pharisiens se sont assis dans la chaire de Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Toutes les choses donc qu’ils vous diront, faites-les et observez-les; mais ne faites pas selon leurs œuvres, car ils disent et ne font pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'mais ils lient des fardeaux pesants et difficiles à porter, et les mettent sur les épaules des hommes, mais eux, ils ne veulent pas les remuer de leur doigt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Et ils font toutes leurs œuvres pour être vus des hommes; car ils élargissent leurs phylactères et donnent plus de largeur aux franges [de leurs vêtements],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'et ils aiment la première place dans les repas et les premiers sièges dans les synagogues,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'et les salutations dans les places publiques, et à être appelés par les hommes: Rabbi, Rabbi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Mais vous, ne soyez pas appelés: Rabbi; car un seul est votre conducteur, [le Christ]; et vous, vous êtes tous frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Et n’appelez personne sur la terre votre père; car un seul est votre père, celui qui est dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Ne soyez pas non plus appelés conducteurs; car un seul est votre conducteur, le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Mais le plus grand de vous sera votre serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Et quiconque s’élèvera sera abaissé; et quiconque s’abaissera sera élevé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Mais malheur à vous, scribes et pharisiens hypocrites! car vous fermez le royaume des cieux devant les hommes; car vous n’entrez pas vous-mêmes, ni ne permettez à ceux qui entrent, d’entrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, '');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Malheur à vous, scribes et pharisiens hypocrites! car vous parcourez la mer et la terre pour faire un prosélyte; et quand il l’est devenu, vous le rendez fils de la géhenne deux fois plus que vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Malheur à vous, guides aveugles, qui dites: Quiconque aura juré par le temple, ce n’est rien; mais quiconque aura juré par l’or du temple, est obligé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Fous et aveugles! car lequel est le plus grand, ou l’or, ou le temple qui sanctifie l’or?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Et quiconque aura juré par l’autel, ce n’est rien; mais quiconque aura juré par le don qui est dessus, est obligé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Aveugles! car lequel est le plus grand, ou le don, ou l’autel qui sanctifie le don?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Celui donc qui jure par l’autel, jure par l’autel et par toutes les choses qui sont dessus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'et celui qui jure par le temple jure par le temple et par celui qui y habite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'et celui qui jure par le ciel, jure par le trône de Dieu et par celui qui est assis dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Malheur à vous, scribes et pharisiens hypocrites! car vous payez la dîme de la menthe et de l’aneth et du cumin, et vous avez laissé les choses plus importantes de la loi, le jugement et la miséricorde et la fidélité; il fallait faire ces choses-ci, et ne pas laisser celles-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Guides aveugles, qui coulez le moucheron et qui avalez le chameau!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Malheur à vous, scribes et pharisiens hypocrites! car vous nettoyez le dehors de la coupe et du plat; mais au-dedans, ils sont pleins de rapine et d’intempérance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Pharisien aveugle! nettoie premièrement le dedans de la coupe et du plat, afin que le dehors aussi soit net.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Malheur à vous, scribes et pharisiens hypocrites! car vous ressemblez à des sépulcres blanchis, qui paraissent beaux au-dehors, mais qui, au-dedans, sont pleins d’ossements de morts et de toute sorte d’impureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Ainsi, vous aussi, au-dehors vous paraissez justes aux hommes, mais au-dedans vous êtes pleins d’hypocrisie et d’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Malheur à vous, scribes et pharisiens hypocrites! car vous bâtissez les tombeaux des prophètes, et vous ornez les sépulcres des justes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'et vous dites: Si nous avions été dans les jours de nos pères, nous n’aurions pas pris part avec eux au sang des prophètes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'en sorte que vous êtes témoins contre vous-mêmes que vous êtes les fils de ceux qui ont tué les prophètes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'et vous, – comblez la mesure de vos pères!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Serpents, race de vipères! comment échapperez-vous au jugement de la géhenne?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'C’est pourquoi voici, moi, je vous envoie des prophètes, et des sages, et des scribes; et vous en tuerez et vous en crucifierez, et vous en fouetterez dans vos synagogues, et vous les persécuterez de ville en ville,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'en sorte que vienne sur vous tout le sang juste versé sur la terre, depuis le sang d’Abel le juste, jusqu’au sang de Zacharie, fils de Barachie, que vous avez tué entre le temple et l’autel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'En vérité, je vous dis: toutes ces choses viendront sur cette génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jérusalem, Jérusalem, la [ville] qui tue les prophètes et qui lapide ceux qui lui sont envoyés, que de fois j’ai voulu rassembler tes enfants comme une poule rassemble ses poussins sous ses ailes, et vous ne l’avez pas voulu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Voici, votre maison vous est laissée déserte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'car je vous dis: Vous ne me verrez plus désormais, jusqu’à ce que vous disiez: Béni soit celui qui vient au nom du ✶Seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Et Jésus sortit et s’en alla du temple; et ses disciples s’approchèrent pour lui montrer les bâtiments du temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Et lui, répondant, leur dit: Ne voyez-vous pas toutes ces choses? En vérité, je vous dis: Il ne sera point laissé ici pierre sur pierre qui ne soit jetée à bas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Et comme il était assis sur la montagne des Oliviers, les disciples vinrent à lui en particulier, disant: Dis-nous quand ces choses auront lieu, et quel sera le signe de ta venue et de la consommation du siècle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Et Jésus, répondant, leur dit: Prenez garde que personne ne vous séduise;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'car plusieurs viendront en mon nom, disant: Moi, je suis le Christ; et ils en séduiront plusieurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Et vous entendrez parler de guerres et de bruits de guerres; prenez garde que vous ne soyez troublés, car il faut que tout arrive; mais la fin n’est pas encore.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Car nation s’élèvera contre nation, et royaume contre royaume; et il y aura des famines, et des pestes, et des tremblements de terre en divers lieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Mais toutes ces choses sont un commencement de douleurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Alors ils vous livreront pour être affligés, et ils vous feront mourir; et vous serez haïs de toutes les nations à cause de mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Et alors plusieurs seront scandalisés, et se livreront l’un l’autre, et se haïront l’un l’autre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'et plusieurs faux prophètes s’élèveront et en séduiront plusieurs:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'et parce que l’iniquité prévaudra, l’amour de plusieurs sera refroidi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'mais celui qui persévérera jusqu’à la fin, celui-là sera sauvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Et cet évangile du royaume sera prêché dans la terre habitée tout entière, en témoignage à toutes les nations; et alors viendra la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Quand donc vous verrez l’abomination de la désolation, dont il a été parlé par Daniel le prophète, établie dans [le] lieu saint (que celui qui lit comprenne),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'alors que ceux qui sont en Judée s’enfuient dans les montagnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'que celui qui est sur le toit ne descende pas pour emporter ses effets hors de sa maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'et que celui qui est aux champs ne retourne pas en arrière pour emporter son vêtement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Mais malheur à celles qui sont enceintes et à celles qui allaitent en ces jours-là!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Et priez que votre fuite n’ait pas lieu en hiver, ni un jour de sabbat;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'car alors il y aura une grande tribulation, telle qu’il n’y en a point eu depuis le commencement du monde jusqu’à maintenant, et qu’il n’y en aura jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Et si ces jours-là n’avaient été abrégés, nulle chair n’aurait été sauvée; mais, à cause des élus, ces jours-là seront abrégés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Alors, si quelqu’un vous dit: Voici, le Christ est ici, ou: Il est là, ne le croyez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Car il s’élèvera de faux christs et de faux prophètes; et ils montreront de grands signes et des prodiges, de manière à séduire, si possible, même les élus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Voici, je vous l’ai dit à l’avance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Si donc on vous dit: Voici, il est au désert, ne sortez pas; voici, il est dans les chambres intérieures, ne le croyez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Car comme l’éclair sort de l’orient et apparaît jusqu’à l’occident, ainsi sera la venue du fils de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Car, où que soit le corps mort, là s’assembleront les aigles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Et aussitôt après la tribulation de ces jours-là, le soleil sera obscurci, et la lune ne donnera pas sa lumière, et les étoiles tomberont du ciel, et les puissances des cieux seront ébranlées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Et alors paraîtra le signe du fils de l’homme dans le ciel: et alors toutes les tribus de la terre se lamenteront et verront le fils de l’homme venant sur les nuées du ciel, avec puissance et une grande gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Et il enverra ses anges avec un grand son de trompette; et ils rassembleront ses élus des quatre vents, depuis l’un des bouts du ciel jusqu’à l’autre bout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Mais apprenez du figuier la parabole [qu’il vous offre]: Quand déjà son rameau est tendre et qu’il pousse des feuilles, vous connaissez que l’été est proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'De même aussi vous, quand vous verrez toutes ces choses, sachez que cela est proche, à la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'En vérité, je vous dis: Cette génération ne passera point que toutes ces choses ne soient arrivées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Mais, quant à ce jour-là et à l’heure, personne n’en a connaissance, pas même les anges des cieux, si ce n’est mon Père seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Mais comme ont été les jours de Noé, ainsi sera aussi la venue du fils de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Car, comme dans les jours avant le déluge on mangeait et on buvait, on se mariait et on donnait en mariage, jusqu’au jour où Noé entra dans l’arche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'et ils ne connurent rien, jusqu’à ce que le déluge vint et les emporta tous, ainsi sera aussi la venue du fils de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Alors deux hommes seront au champ, l’un sera pris et l’autre laissé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'deux femmes moudront à la meule, l’une sera prise et l’autre laissée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Veillez donc; car vous ne savez pas à quelle heure votre Seigneur vient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Mais sachez ceci, que si le maître de la maison avait su à quelle veille le voleur devait venir, il aurait veillé, et n’aurait pas laissé percer sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'C’est pourquoi, vous aussi, soyez prêts; car, à l’heure que vous ne pensez pas, le fils de l’homme vient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Qui donc est l’esclave fidèle et prudent, que son maître a établi sur les domestiques de sa maison pour leur donner leur nourriture au temps convenable?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Bienheureux est cet esclave-là que son maître, lorsqu’il viendra, trouvera faisant ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'En vérité, je vous dis qu’il l’établira sur tous ses biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Mais si ce méchant esclave-là dit en son cœur: Mon maître tarde à venir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'et qu’il se mette à battre ceux qui sont esclaves avec lui, et qu’il mange et boive avec les ivrognes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'le maître de cet esclave-là viendra en un jour qu’il n’attend pas, et à une heure qu’il ne sait pas,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'et il le coupera en deux et lui donnera sa part avec les hypocrites: là seront les pleurs et les grincements de dents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Alors le royaume des cieux sera fait semblable à dix vierges qui, ayant pris leurs lampes, sortirent à la rencontre de l’époux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Et cinq d’entre elles étaient prudentes, et cinq folles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Celles qui étaient folles, en prenant leurs lampes, ne prirent pas d’huile avec elles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'mais les prudentes prirent de l’huile dans leurs vaisseaux avec leurs lampes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Or, comme l’époux tardait, elles s’assoupirent toutes et s’endormirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Mais au milieu de la nuit il se fit un cri: Voici l’époux; sortez à sa rencontre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Alors toutes ces vierges se levèrent et apprêtèrent leurs lampes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Et les folles dirent aux prudentes: Donnez-nous de votre huile, car nos lampes s’éteignent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Mais les prudentes répondirent, disant: [Non], de peur qu’il n’y en ait pas assez pour nous et pour vous; allez plutôt vers ceux qui en vendent, et achetez-en pour vous-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Or, comme elles s’en allaient pour en acheter, l’époux vint; et celles qui étaient prêtes entrèrent avec lui aux noces; et la porte fut fermée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Ensuite viennent aussi les autres vierges, disant: Seigneur, Seigneur, ouvre-nous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Mais lui, répondant, dit: En vérité, je vous dis: je ne vous connais pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Veillez donc; car vous ne savez ni le jour ni l’heure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Car c’est comme un homme qui, s’en allant hors du pays, appela ses propres esclaves et leur remit ses biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Et à l’un, il donna cinq talents; à un autre, deux; à un autre, un; à chacun selon sa propre capacité; et aussitôt il s’en alla hors du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Or celui qui avait reçu les cinq talents s’en alla et les fit valoir, et acquit cinq autres talents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'De même aussi, celui qui avait reçu les deux, en gagna, lui aussi, deux autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Mais celui qui en avait reçu un, s’en alla et creusa dans la terre, et cacha l’argent de son maître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Et longtemps après, le maître de ces esclaves vient et règle compte avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Et celui qui avait reçu les cinq talents vint et apporta cinq autres talents, disant: Maître, tu m’as remis cinq talents; voici, j’ai gagné cinq autres talents par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Son maître lui dit: Bien, bon et fidèle esclave; tu as été fidèle en peu de chose, je t’établirai sur beaucoup: entre dans la joie de ton maître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Et celui qui avait reçu les deux talents vint aussi et dit: Maître, tu m’as remis deux talents; voici, j’ai gagné deux autres talents par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Son maître lui dit: Bien, bon et fidèle esclave; tu as été fidèle en peu de chose, je t’établirai sur beaucoup: entre dans la joie de ton maître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Et celui qui avait reçu un talent vint aussi et dit: Maître, je te connaissais, que tu es un homme dur, moissonnant où tu n’as pas semé et recueillant où tu n’as pas répandu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'et, craignant, je m’en suis allé et j’ai caché ton talent dans la terre; voici, tu as ce qui est à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Et son maître, répondant, lui dit: Méchant et paresseux esclave, tu savais que je moissonne où je n’ai pas semé, et que je recueille où je n’ai pas répandu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, '– tu aurais donc dû placer mon argent chez les banquiers, et, quand je serais venu, j’aurais reçu ce qui est à moi avec l’intérêt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Ôtez -lui donc le talent, et donnez-le à celui qui a les dix talents;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'car à chacun qui a il sera donné, et il sera dans l’abondance; mais à celui qui n’a pas, cela même qu’il a lui sera ôté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Et jetez l’esclave inutile dans les ténèbres de dehors: là seront les pleurs et les grincements de dents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Or, quand le fils de l’homme viendra dans sa gloire, et tous les anges avec lui, alors il s’assiéra sur le trône de sa gloire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'et toutes les nations seront assemblées devant lui; et il séparera les uns d’avec les autres, comme un berger sépare les brebis d’avec les chèvres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'et il mettra les brebis à sa droite et les chèvres à sa gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Alors le roi dira à ceux qui seront à sa droite: Venez, les bénis de mon Père, héritez du royaume qui vous est préparé dès la fondation du monde;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'car j’ai eu faim, et vous m’avez donné à manger; j’ai eu soif, et vous m’avez donné à boire; j’étais étranger, et vous m’avez recueilli;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'j’étais nu, et vous m’avez vêtu; j’étais infirme, et vous m’avez visité; j’étais en prison, et vous êtes venus auprès de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Alors les justes lui répondront, disant: Seigneur, quand est-ce que nous t’avons vu avoir faim, et que nous t’avons nourri; ou avoir soif, et que nous t’avons donné à boire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Et quand est-ce que nous t’avons vu étranger, et que nous t’avons recueilli; ou nu, et que nous t’avons vêtu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Et quand est-ce que nous t’avons vu infirme, ou en prison, et que nous sommes venus auprès de toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Et le roi, répondant, leur dira: En vérité, je vous dis: En tant que vous l’avez fait à l’un des plus petits de ceux-ci [qui sont] mes frères, vous me l’avez fait à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Alors il dira aussi à ceux qui seront à sa gauche: Allez-vous-en loin de moi, maudits, dans le feu éternel qui est préparé pour le diable et ses anges;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'car j’ai eu faim, et vous ne m’avez pas donné à manger; j’ai eu soif, et vous ne m’avez pas donné à boire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'j’étais étranger, et vous ne m’avez pas recueilli; nu, et vous ne m’avez pas vêtu; infirme et en prison, et vous ne m’avez pas visité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Alors eux aussi répondront, disant: Seigneur, quand est-ce que nous t’avons vu avoir faim, ou avoir soif, ou être étranger, ou nu, ou infirme, ou en prison, et que nous ne t’avons pas servi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Alors il leur répondra, disant: En vérité, je vous dis: En tant que vous ne l’avez pas fait à l’un de ces plus petits, vous ne me l’avez pas fait non plus à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Et ceux-ci s’en iront dans les tourments éternels, et les justes, dans la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Et il arriva, lorsque Jésus eut achevé tous ces discours, qu’il dit à ses disciples:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Vous savez que la Pâque est dans deux jours, et le fils de l’homme est livré pour être crucifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Alors les principaux sacrificateurs et les anciens du peuple s’assemblèrent dans le palais du souverain sacrificateur, appelé Caïphe,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'et tinrent conseil ensemble pour se saisir de Jésus par ruse et le faire mourir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'mais ils disaient: Non pas pendant la fête, afin qu’il n’y ait pas de tumulte parmi le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Et comme Jésus était à Béthanie dans la maison de Simon le lépreux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'une femme, ayant un vase d’albâtre [plein] d’un parfum de grand prix, vint à lui et le répandit sur sa tête comme il était à table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Et les disciples, le voyant, en furent indignés, disant: À quoi bon cette perte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Car ce [parfum] aurait pu être vendu pour une forte somme, et être donné aux pauvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Et Jésus, le sachant, leur dit: Pourquoi donnez-vous du déplaisir à cette femme? car elle a fait une bonne œuvre envers moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'car vous avez toujours les pauvres avec vous, mais moi, vous ne m’avez pas toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'car cette femme, en répandant ce parfum sur mon corps, l’a fait pour ma sépulture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'En vérité, je vous dis: En quelque lieu que cet évangile soit prêché dans le monde entier, on parlera aussi de ce que cette femme a fait, en mémoire d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Alors l’un des douze, appelé Judas Iscariote, s’en alla vers les principaux sacrificateurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'et dit: Que voulez-vous me donner, et moi, je vous le livrerai? Et ils lui comptèrent 30 pièces d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Et dès lors, il cherchait une bonne occasion pour le livrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Et, le premier jour des pains sans levain, les disciples vinrent à Jésus, disant: Où veux-tu que nous te préparions [ce qu’il faut] pour manger la pâque?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Et il dit: Allez à la ville auprès d’un tel, et dites-lui: Le maître dit: Mon temps est proche; je ferai la pâque chez toi avec mes disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Et les disciples firent comme Jésus leur avait ordonné, et ils apprêtèrent la pâque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Et le soir étant venu, il se mit à table avec les douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Et comme ils mangeaient, il dit: En vérité, je vous dis que l’un d’entre vous me livrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Et, en étant fort attristés, ils commencèrent, chacun d’eux, à lui dire: Seigneur, est-ce moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Et lui, répondant, dit: Celui qui aura trempé la main avec moi dans le plat, celui-là me livrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Le fils de l’homme s’en va, selon qu’il est écrit de lui; mais malheur à cet homme par qui le fils de l’homme est livré! Il aurait été bon pour cet homme-là qu’il ne soit pas né.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Et Judas qui le livrait, répondant, dit: Est-ce moi, Rabbi? Il lui dit: Tu l’as dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Et comme ils mangeaient, Jésus ayant pris le pain et ayant béni, le rompit et le donna aux disciples, et dit: Prenez, mangez; ceci est mon corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Et, ayant pris la coupe et ayant rendu grâces, il la leur donna, disant: Buvez -en tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Car ceci est mon sang, le [sang] de la nouvelle alliance, qui est versé pour plusieurs en rémission de péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Mais je vous dis que désormais je ne boirai plus de ce fruit de la vigne, jusqu’à ce jour où je le boirai nouveau avec vous dans le royaume de mon Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Et ayant chanté une hymne, ils sortirent [et s’en allèrent] à la montagne des Oliviers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Alors Jésus leur dit: Vous serez tous scandalisés en moi cette nuit; car il est écrit: « Je frapperai le berger, et les brebis du troupeau seront dispersées »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'mais, après que j’aurai été ressuscité, j’irai devant vous en Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Et Pierre, répondant, lui dit: Si tous étaient scandalisés en toi, moi, je ne serai jamais scandalisé [en toi].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jésus lui dit: En vérité, je te dis, que cette nuit-ci, avant que le coq ait chanté, tu me renieras trois fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Pierre lui dit: Quand même il me faudrait mourir avec toi, je ne te renierai point. Et tous les disciples dirent la même chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Alors Jésus s’en vient avec eux en un lieu appelé Gethsémané, et dit aux disciples: Asseyez-vous ici, jusqu’à ce que, m’en étant allé, j’aie prié là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Et ayant pris Pierre et les deux fils de Zébédée, il commença à être attristé et fort angoissé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Alors il leur dit: Mon âme est saisie de tristesse jusqu’à la mort; demeurez ici et veillez avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Et s’en allant un peu plus avant, il tomba sur sa face, priant et disant: Mon Père, s’il est possible, que cette coupe passe loin de moi; toutefois, non pas comme moi je veux, mais comme toi [tu veux].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Et il vient vers les disciples, et il les trouve dormant; et il dit à Pierre: Ainsi, vous n’avez pas pu veiller une heure avec moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Veillez et priez, afin que vous n’entriez pas en tentation; l’esprit est prompt, mais la chair est faible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Il s’en alla de nouveau, une seconde fois, et il pria, disant: Mon Père, s’il n’est pas possible que ceci passe loin de moi, sans que je le boive, que ta volonté soit faite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Et étant venu, il les trouva de nouveau dormant; car leurs yeux étaient appesantis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Et les laissant, il s’en alla de nouveau, et pria une troisième fois, disant les mêmes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Alors il vient vers les disciples, et leur dit: Dormez dorénavant et reposez-vous; voici, l’heure s’est approchée, et le fils de l’homme est livré entre les mains des pécheurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Levez-vous, allons; voici, celui qui me livre s’est approché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Et comme il parlait encore, voici Judas, l’un des douze, vint, et avec lui une grande foule avec des épées et des bâtons, de la part des principaux sacrificateurs et des anciens du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Et celui qui le livrait leur donna un signe, disant: Celui que j’embrasserai, c’est lui; saisissez-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Et aussitôt, s’approchant de Jésus, il dit: Je te salue, Rabbi; et il l’embrassa avec empressement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Et Jésus lui dit: Ami, pourquoi es-tu venu? Alors, s’étant approchés, ils mirent les mains sur Jésus et se saisirent de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Et voici, l’un de ceux qui étaient avec Jésus, étendant la main tira son épée, et frappant l’esclave du souverain sacrificateur, lui emporta l’oreille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Alors Jésus lui dit: Remets ton épée en son lieu; car tous ceux qui auront pris l’épée périront par l’épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Penses-tu que je ne puisse pas maintenant prier mon Père, et il me fournira plus de douze légions d’anges?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Comment donc seraient accomplies les écritures, [qui disent] qu’il faut qu’il en arrive ainsi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'En cette heure-là Jésus dit aux foules: Êtes-vous sortis comme après un brigand, avec des épées et des bâtons, pour me prendre? J’étais tous les jours assis parmi vous, enseignant dans le temple; et vous ne vous êtes pas saisis de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Mais tout ceci est arrivé, afin que les écritures des prophètes soient accomplies. Alors tous les disciples le laissèrent et s’enfuirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Et ceux qui s’étaient saisis de Jésus l’amenèrent à Caïphe le souverain sacrificateur, où les scribes et les anciens étaient assemblés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Et Pierre le suivait de loin, jusqu’au palais du souverain sacrificateur; et étant entré, il s’assit avec les huissiers pour voir la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Or les principaux sacrificateurs et les anciens et tout le sanhédrin cherchaient [quelque] faux témoignage contre Jésus, de manière à le faire mourir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'et ils n’en trouvèrent point, – bien que plusieurs faux témoins soient venus. Mais, à la fin, deux faux témoins vinrent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'et dirent: Celui-ci a dit: Je puis détruire le temple de Dieu, et en trois jours le bâtir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Et le souverain sacrificateur, se levant, lui dit: Ne réponds-tu rien? De quoi ceux-ci témoignent-ils contre toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Mais Jésus garda le silence. Et le souverain sacrificateur, répondant, lui dit: Je t’adjure, par le Dieu vivant, que tu nous dises si toi, tu es le Christ, le Fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jésus lui dit: Tu l’as dit. De plus, je vous dis: dorénavant vous verrez le fils de l’homme assis à la droite de la puissance, et venant sur les nuées du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Alors le souverain sacrificateur déchira ses vêtements, disant: Il a blasphémé; qu’avons-nous encore besoin de témoins? Voici, vous avez entendu maintenant [son] blasphème:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'que vous en semble? Et répondant, ils dirent: Il mérite la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Alors ils lui crachèrent au visage et lui donnèrent des soufflets; et quelques-uns le frappèrent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'disant: Prophétise-nous, Christ; qui est celui qui t’a frappé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Or Pierre était assis dehors, dans la cour; et une servante vint à lui, disant: Et toi, tu étais avec Jésus le Galiléen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Et il le nia devant tous, disant: Je ne sais ce que tu dis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Et une autre [servante] le vit, comme il était sorti dans le vestibule; et elle dit à ceux qui étaient là: Celui-ci aussi était avec Jésus le Nazaréen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Et il le nia de nouveau avec serment: Je ne connais pas cet homme!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Et un peu après, ceux qui se trouvaient là s’approchèrent et dirent à Pierre: Certainement, toi, tu es aussi de ces gens-là; car aussi ton langage te fait reconnaître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Alors il se mit à faire des imprécations et à jurer: Je ne connais pas cet homme! Et aussitôt le coq chanta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Et Pierre se souvint de la parole de Jésus, qui lui avait dit: Avant que le coq chante, tu me renieras trois fois. Et étant sorti dehors, il pleura amèrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Or, quand le matin fut venu, tous les principaux sacrificateurs et les anciens du peuple tinrent conseil contre Jésus pour le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Et l’ayant lié, ils l’emmenèrent et le livrèrent à Ponce Pilate, le gouverneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Alors Judas qui l’avait livré, voyant qu’il était condamné, ayant du remords, reporta les 30 pièces d’argent aux principaux sacrificateurs et aux anciens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'disant: J’ai péché en livrant le sang innocent. Mais ils dirent: Que nous importe! tu y aviseras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Et ayant jeté l’argent dans le temple, il se retira; et s’en étant allé, il se pendit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Mais les principaux sacrificateurs, ayant pris les pièces d’argent, dirent: Il n’est pas permis de les mettre dans le trésor sacré, puisque c’est le prix du sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Et ayant tenu conseil, ils achetèrent avec cet [argent] le champ du potier, pour la sépulture des étrangers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'c’est pourquoi ce champ-là a été appelé Champ de sang, jusqu’à aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Alors fut accompli ce qui avait été dit par Jérémie le prophète, disant: Et ils ont pris les 30 pièces d’argent, le prix de celui qui a été évalué, lequel ceux d’entre les fils d’Israël ont évalué;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'et ils les ont données pour le champ du potier, comme le ✶Seigneur m’avait ordonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Or Jésus se tenait devant le gouverneur; et le gouverneur l’interrogea, disant: Es-tu, toi, le roi des Juifs? Et Jésus lui dit: Tu le dis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Et étant accusé par les principaux sacrificateurs et les anciens, il ne répondit rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Alors Pilate lui dit: N’entends-tu pas de combien de choses ils portent témoignage contre toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Et il ne lui répondit pas même un seul mot; en sorte que le gouverneur s’en étonnait fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Or, à la fête, le gouverneur avait coutume de relâcher un prisonnier à la foule, celui qu’ils voulaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Et il y avait alors un prisonnier fameux, nommé Barabbas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Comme donc ils étaient assemblés, Pilate leur dit: Lequel voulez-vous que je vous relâche, Barabbas, ou Jésus qui est appelé Christ?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Car il savait qu’ils l’avaient livré par envie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Et comme il était assis sur le tribunal, sa femme lui envoya dire: N’aie rien à faire avec ce juste; car j’ai beaucoup souffert aujourd’hui à son sujet dans un songe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Mais les principaux sacrificateurs et les anciens persuadèrent les foules de demander Barabbas et de faire périr Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Et le gouverneur, répondant, leur dit: Lequel des deux voulez-vous que je vous relâche? Et ils dirent: Barabbas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilate leur dit: Que ferai-je donc de Jésus, qui est appelé Christ? Ils disent tous: Qu’il soit crucifié!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Et le gouverneur dit: Mais quel mal a-t-il fait? Et ils s’écriaient encore plus fort, disant: Qu’il soit crucifié!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Et Pilate, voyant qu’il ne gagnait rien, mais que plutôt il s’élevait un tumulte, prit de l’eau et se lava les mains devant la foule, disant: Je suis innocent du sang de ce juste; vous, vous y aviserez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Et tout le peuple, répondant, dit: Que son sang soit sur nous et sur nos enfants!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Alors il leur relâcha Barabbas; et ayant fait fouetter Jésus, il le livra pour être crucifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Alors les soldats du gouverneur, ayant emmené Jésus au prétoire, assemblèrent contre lui toute la cohorte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Et lui ayant ôté ses vêtements, ils lui mirent un manteau d’écarlate;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'et ayant tressé une couronne d’épines, ils la mirent sur sa tête, et un roseau dans sa main droite; et fléchissant les genoux devant lui, ils se moquaient de lui, disant: Salut, roi des Juifs!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Et ayant craché contre lui, ils prirent le roseau et lui en frappaient la tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Et après qu’ils se furent moqués de lui, ils lui ôtèrent le manteau, et le revêtirent de ses vêtements, et l’emmenèrent pour le crucifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Et comme ils sortaient, ils trouvèrent un homme de Cyrène, nommé Simon, qu’ils contraignirent de porter sa croix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Et étant arrivés au lieu appelé Golgotha, ce qui signifie lieu du crâne,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'ils lui donnèrent à boire du vinaigre mêlé de fiel; et l’ayant goûté, il ne voulut pas en boire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Et l’ayant crucifié, ils partagèrent ses vêtements, en tirant au sort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'et s’étant assis, ils veillaient là sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Et ils placèrent au-dessus de sa tête son accusation écrite: Celui-ci est Jésus, le roi des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Alors sont crucifiés avec lui deux brigands, un à la droite, et un à la gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Et ceux qui passaient par là l’injuriaient, hochant la tête,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'et disant: Toi qui détruis le temple et qui le bâtis en trois jours, sauve-toi toi-même. Si tu es Fils de Dieu, descends de la croix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Et pareillement aussi les principaux sacrificateurs avec les scribes et les anciens, se moquant, disaient:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Il a sauvé les autres, il ne peut se sauver lui-même; s’il est le roi d’Israël, qu’il descende maintenant de la croix, et nous croirons en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Il s’est confié en Dieu; qu’il le délivre maintenant, s’il tient à lui; car il a dit: Je suis Fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Et les brigands aussi qui avaient été crucifiés avec lui l’insultaient de la même manière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Mais, depuis la sixième heure, il y eut des ténèbres sur tout le pays, jusqu’à la neuvième heure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Et vers la neuvième heure, Jésus s’écria d’une forte voix, disant: Éli, Éli, lama sabachthani? c’est-à-dire: Mon Dieu, mon Dieu, pourquoi m’as-tu abandonné?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Et quelques-uns de ceux qui se tenaient là, ayant entendu [cela], disaient: Il appelle Élie, celui-ci!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Et aussitôt l’un d’entre eux courut et prit une éponge, et l’ayant remplie de vinaigre, la mit au bout d’un roseau, et lui donna à boire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Mais les autres disaient: Laisse, voyons si Élie vient pour le sauver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Et Jésus, ayant encore crié d’une forte voix, rendit l’esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Et voici, le voile du temple se déchira en deux, depuis le haut jusqu’en bas; et la terre trembla, et les rochers se fendirent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'et les sépulcres s’ouvrirent; et beaucoup de corps des saints endormis ressuscitèrent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'et étant sortis des sépulcres après sa résurrection, ils entrèrent dans la sainte ville, et apparurent à plusieurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Et le centurion et ceux qui avec lui veillaient sur Jésus, ayant vu le tremblement de terre et ce qui venait d’arriver, eurent une fort grande peur, disant: Certainement celui-ci était Fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Et il y avait là plusieurs femmes qui regardaient de loin, qui avaient suivi Jésus depuis la Galilée, en le servant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'entre lesquelles étaient Marie de Magdala, et Marie, la mère de Jacques et de Joses, et la mère des fils de Zébédée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Et, le soir étant venu, il arriva un homme riche d’Arimathée, dont le nom était Joseph, qui aussi lui-même était disciple de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Celui-ci étant allé auprès de Pilate, demanda le corps de Jésus; alors Pilate donna l’ordre que le corps soit livré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Et Joseph, ayant pris le corps, l’enveloppa d’un linceul net,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'et le mit dans son sépulcre neuf qu’il avait taillé dans le roc; et ayant roulé une grande pierre contre la porte du sépulcre, il s’en alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Et Marie de Magdala et l’autre Marie étaient là, assises vis-à-vis du sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Et le lendemain, qui est après la Préparation, les principaux sacrificateurs et les pharisiens s’assemblèrent auprès de Pilate,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'disant: Seigneur, il nous souvient que ce séducteur, pendant qu’il était encore en vie, disait: Après trois jours, je ressuscite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Ordonne donc que le sépulcre soit gardé avec soin jusqu’au troisième jour; de peur que ses disciples ne viennent et ne le dérobent, et ne disent au peuple: Il est ressuscité des morts; et ce dernier égarement sera pire que le premier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Et Pilate leur dit: Vous avez une garde; allez, rendez-le sûr comme vous l’entendez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Et eux, s’en allant, rendirent le sépulcre sûr, scellant la pierre, et y mettant la garde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Or, sur le tard, le jour du sabbat, au crépuscule du premier jour de la semaine, Marie de Magdala et l’autre Marie vinrent voir le sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Et voici, il se fit un grand tremblement de terre; car un ange du ✶Seigneur, descendant du ciel, vint et roula la pierre, et s’assit sur elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Et son aspect était comme un éclair, et son vêtement blanc comme la neige.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Et de la frayeur qu’ils en eurent, les gardiens tremblèrent et devinrent comme morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Et l’ange, répondant, dit aux femmes: Pour vous, n’ayez point de peur; car je sais que vous cherchez Jésus le crucifié;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'il n’est pas ici; car il est ressuscité, comme il l’avait dit. Venez, voyez le lieu où le Seigneur gisait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'et allez promptement, et dites à ses disciples qu’il est ressuscité des morts. Et voici, il s’en va devant vous en Galilée: là vous le verrez; voici, je vous l’ai dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Et sortant promptement du sépulcre avec crainte et une grande joie, elles coururent l’annoncer à ses disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Et comme elles allaient pour l’annoncer à ses disciples, voici aussi Jésus vint au-devant d’elles, disant: Je vous salue. Et elles, s’approchant de lui, saisirent ses pieds et lui rendirent hommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Alors Jésus leur dit: N’ayez point de peur; allez annoncer à mes frères qu’ils aillent en Galilée, et là ils me verront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Et comme elles s’en allaient, voici, quelques hommes de la garde s’en allèrent dans la ville, et rapportèrent aux principaux sacrificateurs toutes les choses qui étaient arrivées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Et s’étant assemblés avec les anciens, ils tinrent conseil et donnèrent une bonne somme d’argent aux soldats,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'disant: Dites: ses disciples sont venus de nuit, et l’ont dérobé pendant que nous dormions;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'et si le gouverneur vient à en entendre parler, nous le persuaderons, et nous vous mettrons hors de souci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Et eux, ayant pris l’argent, firent comme ils avaient été enseignés; et cette parole s’est répandue parmi les Juifs jusqu’à aujourd’hui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Et les onze disciples s’en allèrent en Galilée, sur la montagne où Jésus leur avait ordonné [de se rendre].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Et l’ayant vu, ils lui rendirent hommage; mais quelques-uns doutèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Et Jésus, s’approchant, leur parla, disant: Toute autorité m’a été donnée dans le ciel et sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Allez donc, et faites disciples toutes les nations, les baptisant pour le nom du Père et du Fils et du Saint Esprit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'leur enseignant à garder toutes les choses que je vous ai commandées. Et voici, moi je suis avec vous tous les jours, jusqu’à la consommation du siècle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Commencement de l’évangile de Jésus Christ, Fils de Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'comme il est écrit dans Ésaïe le prophète: « Voici, moi j’envoie mon messager devant ta face, lequel préparera ton chemin ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, '« Voix de celui qui crie dans le désert: Préparez le chemin du ✶Seigneur, faites droits ses sentiers ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Jean vint, baptisant dans le désert, et prêchant le baptême de repentance en rémission de péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Et tout le pays de Judée et tous ceux de Jérusalem sortaient vers lui; et ils étaient baptisés par lui dans le fleuve du Jourdain, confessant leurs péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Or Jean était vêtu de poil de chameau et d’une ceinture de cuir autour des reins, et il mangeait des sauterelles et du miel sauvage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Et il prêchait, disant: Il vient après moi, celui qui est plus puissant que moi, duquel je ne suis pas digne de délier, en me baissant, la courroie des sandales.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Moi, je vous ai baptisés d’eau; lui, vous baptisera de l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Et il arriva, en ces jours-là, que Jésus vint de Nazareth de Galilée, et fut baptisé par Jean au Jourdain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Et [s’éloignant] aussitôt de l’eau, il monta, et vit les cieux se fendre, et l’Esprit comme une colombe descendre sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Et il y eut une voix qui venait des cieux: Tu es mon Fils bien-aimé; en toi j’ai trouvé mon plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Et aussitôt l’Esprit le pousse dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Et il fut dans le désert 40 jours, tenté par Satan; et il était avec les bêtes sauvages; et les anges le servaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Mais après que Jean eut été livré, Jésus vint en Galilée, prêchant l’évangile du royaume de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'et disant: Le temps est accompli, et le royaume de Dieu s’est approché: repentez-vous et croyez à l’évangile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Et comme il marchait le long de la mer de Galilée, il vit Simon et André le frère de Simon, qui jetaient un filet dans la mer; car ils étaient pêcheurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Et Jésus leur dit: Venez après moi, et je vous ferai devenir pêcheurs d’hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Et aussitôt, ayant quitté leurs filets, ils le suivirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Et passant de là un peu plus avant, il vit Jacques le [fils] de Zébédée et Jean son frère; et eux [étaient] dans le bateau, raccommodant les filets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Et aussitôt il les appela; et laissant leur père Zébédée dans le bateau avec les gens à gages, ils s’en allèrent après lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Et ils entrent dans Capernaüm; et étant entré aussitôt le jour du sabbat dans la synagogue, il enseignait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Et ils s’étonnaient de sa doctrine; car il les enseignait comme ayant autorité, et non pas comme les scribes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Et il y avait dans leur synagogue un homme possédé d’un esprit immonde; et il s’écria,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'disant: Ha! qu’y a-t-il entre nous et toi, Jésus Nazarénien? Es-tu venu pour nous détruire? Je te connais, qui tu es: le Saint de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Et Jésus le tança, disant: Tais-toi, et sors de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Et l’esprit immonde, l’ayant déchiré et ayant crié à haute voix, sortit de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Et ils furent tous saisis d’étonnement, de sorte qu’ils s’enquéraient entre eux, disant: Qu’est ceci? Quelle doctrine nouvelle est celle-ci? Car il commande avec autorité, même aux esprits immondes, et ils lui obéissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Et sa renommée se répandit aussitôt tout à l’entour dans la Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Et aussitôt, sortant de la synagogue, ils allèrent avec Jacques et Jean dans la maison de Simon et d’André.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Or la belle-mère de Simon était là couchée, ayant la fièvre; et aussitôt ils lui parlent d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Et s’approchant, il la fit lever en la prenant par la main; et aussitôt la fièvre la quitta; et elle les servit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Et, le soir étant venu, comme le soleil se couchait, on lui apporta tous ceux qui se portaient mal, et les démoniaques;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'et la ville tout entière était rassemblée à la porte:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'et il en guérit plusieurs qui souffraient de diverses maladies, et chassa plusieurs démons, et ne permit pas aux démons de parler parce qu’ils le connaissaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Et s’étant levé sur le matin, longtemps avant le jour, il sortit et s’en alla dans un lieu désert; et il priait là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Et Simon et ceux qui étaient avec lui, le suivirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'Et l’ayant trouvé, ils lui dirent: Tous te cherchent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Et il leur dit: Allons ailleurs dans les bourgades voisines, afin que j’y prêche aussi; car c’est pour cela que je suis venu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Et il prêchait dans leurs synagogues par toute la Galilée, et chassait les démons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Et un lépreux vient à lui, le suppliant et se jetant à genoux devant lui, et lui disant: Si tu veux, tu peux me rendre net.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Et Jésus, ému de compassion, étendant la main, le toucha, et lui dit: Je veux, sois net.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Et comme il parlait, aussitôt la lèpre se retira de lui; et il fut net.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Et usant de paroles sévères, il le renvoya aussitôt,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'et lui dit: Prends garde de n’en rien dire à personne; mais va, montre-toi au sacrificateur, et offre pour ta purification ce que Moïse a ordonné, pour que cela leur serve de témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Mais lui, étant sorti, commença à beaucoup publier et à divulguer ce qui était arrivé, de sorte que Jésus ne pouvait plus entrer ouvertement dans la ville; mais il se tenait dehors dans des lieux déserts; et on venait à lui de toutes parts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Et il entra de nouveau dans Capernaüm, quelques jours après, et on entendit dire qu’il était à la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Et aussitôt beaucoup de gens s’y assemblèrent, de sorte qu’il ne se trouva plus de place, même auprès de la porte; et il leur annonçait la parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Et des gens viennent à lui, amenant un paralytique porté par quatre personnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Et ne pouvant s’approcher de lui, à cause de la foule, ils découvrirent le toit [du lieu] où il était; et l’ayant percé, ils descendirent le petit lit sur lequel le paralytique était couché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Et Jésus, voyant leur foi, dit au paralytique: [Mon] enfant, tes péchés sont pardonnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Et il y avait là quelques-uns des scribes, assis et raisonnant dans leurs cœurs:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Pourquoi celui-ci parle-t-il ainsi? Il blasphème. Qui peut pardonner les péchés, sinon un [seul], Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Et aussitôt Jésus, connaissant dans son esprit qu’ils raisonnaient ainsi en eux-mêmes, leur dit: Pourquoi faites-vous ces raisonnements dans vos cœurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Lequel est le plus facile, de dire au paralytique: [Tes] péchés te sont pardonnés; ou de dire: Lève-toi, prends ton petit lit, et marche?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Or, afin que vous sachiez que le fils de l’homme a le pouvoir sur la terre de pardonner les péchés (il dit au paralytique):');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Je te dis, lève-toi, prends ton petit lit, et va dans ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Et il se leva aussitôt, et ayant pris son petit lit, il sortit en la présence de tous; de sorte qu’ils en furent tous étonnés et qu’ils glorifiaient Dieu, disant: Nous n’avons jamais vu pareille chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Et il sortit encore et longea la mer; et toute la foule venait à lui, et il les enseignait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Et en passant, il vit Lévi le [fils] d’Alphée assis au bureau de recette, et il lui dit: Suis-moi. Et se levant, il le suivit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Et il arriva, comme il était à table dans sa maison, que beaucoup de publicains et de pécheurs aussi se trouvèrent à table avec Jésus et ses disciples; car ils étaient nombreux, et ils le suivaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Et les scribes et les pharisiens, le voyant manger avec les publicains et les pécheurs, dirent à ses disciples: Pourquoi mange-t-il et boit-il avec les publicains et les pécheurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Et Jésus, l’ayant entendu, leur dit: Ceux qui sont en bonne santé n’ont pas besoin de médecin, mais ceux qui se portent mal; je ne suis pas venu appeler des justes, mais des pécheurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Et les disciples de Jean et les pharisiens jeûnaient; et ils viennent et lui disent: Pourquoi les disciples de Jean et ceux des pharisiens jeûnent-ils, mais tes disciples ne jeûnent pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Et Jésus leur dit: Les fils de la chambre nuptiale peuvent-ils jeûner pendant que l’époux est avec eux? Aussi longtemps qu’ils ont l’époux avec eux, ils ne peuvent pas jeûner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Mais des jours viendront, lorsque l’époux leur aura été ôté; et alors ils jeûneront en ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Personne ne coud un morceau de drap neuf à un vieil habit; autrement la pièce neuve emporte [une partie] du vieil [habit], et la déchirure en devient plus mauvaise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Et personne ne met du vin nouveau dans de vieilles outres; autrement le vin rompt les outres, et le vin se répand, et les outres sont perdues; mais le vin nouveau doit être mis dans des outres neuves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Et il arriva qu’il passait par les blés en un jour de sabbat; et ses disciples, chemin faisant, se mirent à arracher des épis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Et les pharisiens lui dirent: Voici, pourquoi font-ils, le jour de sabbat, ce qui n’est pas permis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Et lui leur dit: N’avez-vous jamais lu ce que fit David quand il fut dans le besoin et qu’il eut faim, lui et ceux qui étaient avec lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'comment, au [titre] “Abiathar, souverain sacrificateur”, il entra dans la maison de Dieu, et mangea les pains de proposition, qu’il n’est pas permis de manger, sinon aux sacrificateurs, et en donna aussi à ceux qui étaient avec lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Et il leur dit: Le sabbat a été fait pour l’homme, non pas l’homme pour le sabbat;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'de sorte que le fils de l’homme est seigneur aussi du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Et il entra encore dans la synagogue; et il y avait là un homme qui avait la main desséchée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Et ils l’observaient [pour voir] s’il le guérirait le jour de sabbat, afin de l’accuser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Et il dit à l’homme qui avait la main desséchée: Lève-toi là devant tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Et il leur dit: Est-il permis de faire du bien le jour de sabbat, ou de faire du mal? de sauver la vie, ou de tuer? Mais ils gardaient le silence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Et les ayant regardés à l’entour avec colère, étant attristé de l’endurcissement de leur cœur, il dit à l’homme: Étends ta main. Et il l’étendit, et sa main fut rétablie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Et les pharisiens, sortant aussitôt avec les hérodiens, tinrent conseil contre lui pour le faire périr.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Et Jésus se retira avec ses disciples vers la mer; et une grande multitude le suivit de la Galilée, et de la Judée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'et de Jérusalem, et de l’Idumée, et de par-delà le Jourdain. Et ceux des environs de Tyr et de Sidon, une grande multitude, ayant entendu les choses qu’il faisait, vinrent vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Et il dit à ses disciples qu’un petit bateau soit là à sa disposition, à cause de la foule, afin qu’elle ne le presse pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'car il en guérit beaucoup, de sorte que tous ceux qui étaient affligés de quelque fléau se jetaient sur lui afin de le toucher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Et les esprits immondes, quand ils le voyaient, se jetaient devant lui et s’écriaient, disant: Tu es le Fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Et il leur défendait très expressément de le faire connaître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Et il monte sur une montagne, et il appelle ceux qu’il voulait; et ils vinrent à lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'et il en établit douze pour être avec lui, et pour les envoyer prêcher,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'et pour avoir autorité [de guérir les maladies et] de chasser les démons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'et il surnomma Simon, Pierre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'et Jacques le [fils] de Zébédée et Jean le frère de Jacques, et il les surnomma Boanergès, ce qui est: fils de tonnerre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'et André, et Philippe, et Barthélemy, et Matthieu, et Thomas, et Jacques le [fils] d’Alphée, et Thaddée, et Simon le Cananéen,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'et Judas Iscariote, qui aussi le livra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Et ils viennent à la maison; et la foule s’assemble de nouveau, en sorte qu’ils ne pouvaient pas même manger leur pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Et ses proches, ayant entendu cela, sortirent pour se saisir de lui; car ils disaient: Il est hors de sens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Et les scribes qui étaient descendus de Jérusalem, dirent: Il a Béelzébul; et: Par le chef des démons, il chasse les démons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Et les ayant appelés, il leur dit par des paraboles: Comment Satan peut-il chasser Satan?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Et si un royaume est divisé contre lui-même, ce royaume-là ne peut pas subsister.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Et si une maison est divisée contre elle-même, cette maison-là ne peut pas subsister.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Et si Satan s’élève contre lui-même et est divisé, il ne peut pas subsister, mais il vient à sa fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Nul ne peut entrer dans la maison de l’homme fort, et piller ses biens, si premièrement il n’a lié l’homme fort; et alors il pillera sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'En vérité, je vous dis que tous les péchés seront pardonnés aux fils des hommes, et les paroles injurieuses, quelles qu’elles soient, par lesquelles ils blasphèment;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'mais quiconque proférera des paroles injurieuses contre l’Esprit Saint n’aura jamais de pardon; mais il est passible du jugement éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'C’était parce qu’ils disaient: Il a un esprit immonde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Ses frères et sa mère donc viennent; et se tenant dehors, ils l’envoyèrent appeler;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'et la foule était assise autour de lui. Et on lui dit: Voici, ta mère et tes frères, là dehors, te cherchent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Et il leur répondit, disant: Qui est ma mère, ou [qui sont] mes frères?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Et regardant tout à l’entour ceux qui étaient assis autour de lui, il dit: Voici ma mère et mes frères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'car quiconque fera la volonté de Dieu, celui-là est mon frère, et ma sœur, et ma mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Et il se mit encore à enseigner près de la mer. Et une grande foule se rassembla auprès de lui; de sorte que, montant dans un bateau, il s’assit sur la mer; et toute la foule était à terre sur le bord de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Et il leur enseignait beaucoup de choses par des paraboles; et il leur disait dans son enseignement:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Écoutez: Voici, un semeur sortit pour semer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Et il arriva qu’en semant, quelques [grains] tombèrent le long du chemin; et les oiseaux vinrent et les dévorèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Et d’autres tombèrent sur les endroits rocailleux où ils n’avaient pas beaucoup de terre; et aussitôt ils levèrent, parce qu’ils n’avaient pas une terre profonde;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'et quand le soleil se leva, ils furent brûlés, et, parce qu’ils n’avaient pas de racine, ils furent séchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Et d’autres tombèrent dans les épines; et les épines montèrent et les étouffèrent, et ils ne donnèrent pas de fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Et d’autres tombèrent dans la bonne terre, et donnèrent du fruit, montant et croissant, et rapportèrent, l’un 30, et l’un 60, et l’un 100.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Et il dit: Qui a des oreilles pour entendre, qu’il entende.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Et quand il fut en particulier, ceux qui étaient autour de lui, avec les douze, l’interrogèrent touchant la parabole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Et il leur dit: À vous [il] est donné [de connaître] le mystère du royaume de Dieu; mais pour ceux qui sont dehors, toutes choses se traitent par des paraboles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'afin qu’en voyant ils voient et n’aperçoivent pas, et qu’en entendant ils entendent et ne comprennent pas: de peur qu’ils ne se convertissent et que leurs péchés ne leur soient pardonnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Et il leur dit: Ne connaissez-vous pas cette parabole? et comment connaîtrez-vous toutes les paraboles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Le semeur sème la parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Et ce sont ici ceux qui sont le long du chemin, là où la parole est semée; et quand ils ont entendu, Satan vient aussitôt et ravit la parole semée en eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Et pareillement, ceux qui sont semés sur les endroits rocailleux, ce sont ceux qui, quand ils ont entendu la parole, la reçoivent aussitôt avec joie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'et ils n’ont pas de racine en eux-mêmes, mais ne sont que pour un temps; puis, quand la tribulation ou la persécution survient à cause de la parole, ils sont aussitôt scandalisés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Et d’autres sont ceux qui sont semés dans les épines: ce sont ceux qui ont entendu la parole;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'et les soucis du siècle, et la tromperie des richesses, et les convoitises à l’égard des autres choses, entrant, étouffent la parole, et elle est sans fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Et ceux qui sont semés sur la bonne terre, ce sont ceux qui entendent la parole, et la reçoivent, et portent du fruit: l’un 30, et l’un 60, et l’un 100.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Et il leur dit: La lampe vient-elle pour être mise sous le boisseau ou sous le lit? N’est-ce pas pour être mise sur le pied de lampe?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Car il n’y a rien de secret qui ne soit manifesté, et rien de caché n’arrive, si ce n’est afin de venir en évidence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Si quelqu’un a des oreilles pour entendre, qu’il entende.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Et il leur dit: Prenez garde à ce que vous entendez: de la mesure dont vous mesurerez il vous sera mesuré; et à vous [qui entendez], il sera ajouté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'car à quiconque a, il sera donné; et à celui qui n’a pas, cela même qu’il a sera ôté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Il dit aussi: Ainsi est le royaume de Dieu: c’est comme si un homme jetait de la semence sur la terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'et dormait et se levait de nuit et de jour, et que la semence germe et croisse sans qu’il sache comment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'La terre produit spontanément du fruit, premièrement l’herbe, ensuite l’épi, et puis le plein froment dans l’épi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'et quand le fruit est produit, on y met aussitôt la faucille, parce que la moisson est arrivée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Il disait aussi: Comment comparerons-nous le royaume de Dieu, ou par quelle parabole le représenterons-nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Il est semblable à un grain de moutarde, qui, lorsqu’il est semé sur la terre, est la plus petite de toutes les semences qui sont sur la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'et après qu’il est semé, il monte et devient plus grand que toutes les herbes, et jette de grandes branches, de sorte que les oiseaux du ciel peuvent demeurer sous son ombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Et par plusieurs paraboles de cette sorte, il leur annonçait la parole, selon qu’ils pouvaient l’entendre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'mais il ne leur parlait pas sans parabole; et en particulier il interprétait tout à ses disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Et en ce jour-là, le soir étant venu, il leur dit: Passons à l’autre rive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Et ayant renvoyé la foule, ils le prennent dans un bateau, comme il était; et d’autres bateaux aussi étaient avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Et il se lève un grand tourbillon de vent, et les vagues se jetaient dans le bateau, de sorte qu’il s’emplissait déjà.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Et il était, lui, à la poupe, dormant sur un oreiller; et ils le réveillent et lui disent: Maître, ne te mets-tu pas en peine que nous périssions?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Et s’étant réveillé, il reprit le vent, et dit à la mer: Fais silence, tais-toi! Et le vent tomba, et il se fit un grand calme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Et il leur dit: Pourquoi êtes-vous ainsi craintifs? Comment n’avez-vous pas de foi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Et ils furent saisis d’une grande peur, et ils dirent entre eux: Qui donc est celui-ci, que le vent même et la mer lui obéissent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Et ils arrivèrent à l’autre rive de la mer, dans le pays des Gadaréniens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Et aussitôt, comme il sortait du bateau, un homme possédé d’un esprit immonde,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, '[et] qui avait sa demeure dans les sépulcres, sortant des sépulcres, le rencontra; et personne ne pouvait le lier, pas même avec des chaînes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'car souvent, quand il avait été lié de fers aux pieds et de chaînes, il avait rompu les chaînes et mis les fers en pièces, et personne ne pouvait le dompter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Et il était continuellement, de nuit et de jour, dans les sépulcres et dans les montagnes, criant et se meurtrissant avec des pierres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Et voyant Jésus de loin, il courut et se prosterna devant lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'et, criant avec une voix forte, il dit: Qu’y a-t-il entre moi et toi, Jésus, Fils du Dieu Très-haut? Je t’adjure par Dieu, ne me tourmente pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Car il lui disait: Sors de cet homme, esprit immonde!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Et il lui demanda: Quel est ton nom? Et il lui dit: J’ai nom Légion, car nous sommes plusieurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Et il le priait instamment pour qu’il ne les envoie pas hors du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Et il y avait là, vers la montagne, un grand troupeau de pourceaux qui paissait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Et ils le prièrent, disant: Envoie-nous dans les pourceaux, afin que nous entrions en eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Et aussitôt Jésus le leur permit. Et les esprits immondes, sortant, entrèrent dans les pourceaux, et le troupeau se rua du haut de la côte dans la mer; [or ils étaient] environ 2 000; et ils furent étouffés dans la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Et ceux qui les paissaient s’enfuirent, et portèrent la nouvelle dans la ville et dans les campagnes. Et ils sortirent pour voir ce qui était arrivé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'et ils viennent vers Jésus, et voient le démoniaque, assis, vêtu, et dans son bon sens, celui qui avait Légion; et ils eurent peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Et ceux qui avaient vu [ce qui s’était passé], leur racontèrent ce qui était arrivé au démoniaque et ce qui concernait les pourceaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'et ils se mirent à le prier de s’en aller de leur territoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Et comme il montait dans le bateau, celui qui avait été démoniaque le pria [de permettre] qu’il soit avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Et il ne le lui permit pas, mais lui dit: Va dans ta maison, vers les tiens, et raconte-leur tout ce que le Seigneur t’a fait, et [comment] il a usé de miséricorde envers toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Et il s’en alla, et se mit à publier en Décapolis tout ce que Jésus lui avait fait; et tous s’en étonnaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Et Jésus, ayant encore repassé à l’autre rive, dans le bateau, une grande foule se rassembla auprès de lui; et il était au bord de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Et un des chefs de synagogue, nommé Jaïrus, vient; et le voyant, il se jette à ses pieds;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'et il le suppliait instamment, disant: Ma fille est à l’extrémité; [je te prie] de venir et de lui imposer les mains, afin qu’elle soit sauvée, et qu’elle vive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Et il s’en alla avec lui; et une grande foule le suivit, et elle le pressait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Et une femme qui avait une perte de sang depuis douze ans,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'et qui avait beaucoup souffert d’un grand nombre de médecins, et avait dépensé tout son bien, et n’en avait retiré aucun profit, mais plutôt allait en empirant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'ayant entendu parler de Jésus, vint dans la foule par-derrière, et toucha son vêtement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'car elle disait: Si je touche, ne serait-ce que ses vêtements, je serai guérie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Et aussitôt son flux de sang tarit; et elle connut en son corps qu’elle était guérie du fléau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Et aussitôt Jésus, connaissant en lui-même la puissance qui était sortie de lui, se retournant dans la foule, dit: Qui a touché mes vêtements?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Et ses disciples lui dirent: Tu vois la foule qui te presse, et tu dis: Qui m’a touché?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Et il regardait tout à l’entour pour voir celle qui avait fait cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Et la femme, effrayée et tremblante, sachant ce qui lui était arrivé, vint et se jeta devant lui, et lui déclara toute la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Et il lui dit: [Ma] fille, ta foi t’a guérie; va en paix, et sois guérie de ton fléau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Comme il parlait encore, il vient des gens de chez le chef de synagogue, disant: Ta fille est morte; pourquoi tourmentes-tu encore le maître?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Et Jésus, ayant entendu la parole qui avait été dite, dit aussitôt au chef de synagogue: Ne crains pas, crois seulement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Et il ne permit à personne de le suivre, sinon à Pierre et à Jacques et à Jean le frère de Jacques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Et il vient à la maison du chef de synagogue; et il voit le tumulte, et ceux qui pleuraient et jetaient de grands cris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Et étant entré, il leur dit: Pourquoi faites-vous ce tumulte, et pourquoi pleurez-vous? L’enfant n’est pas morte, mais elle dort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Et ils se riaient de lui. Mais les ayant tous mis dehors, il prend le père de l’enfant et la mère, et ceux qui étaient avec lui, et entre là où l’enfant était couchée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Et ayant pris la main de l’enfant, il lui dit: Talitha coumi; ce qui, interprété, est: Jeune fille, je te dis, lève-toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Et aussitôt la jeune fille se leva et marcha, car elle avait douze ans; et ils furent transportés d’une grande admiration.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Et il leur enjoignit fort que personne ne le sache; et il dit qu’on lui donne à manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Et il sortit de là, et vint dans son pays; et ses disciples le suivent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Et le sabbat étant venu, il se mit à enseigner dans la synagogue; et plusieurs, l’ayant entendu, étaient dans l’étonnement, disant: D’où [viennent] ces choses à celui-ci? Et quelle est cette sagesse qui lui est donnée, et [d’où vient] que de tels miracles s’opèrent par ses mains?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Celui-ci n’est-il pas le charpentier, le fils de Marie, et le frère de Jacques et de Joses et de Jude et de Simon; et ses sœurs ne sont-elles pas ici auprès de nous? Et ils étaient scandalisés en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Et Jésus leur dit: Un prophète n’est pas sans honneur, si ce n’est dans son pays et parmi ses parents et dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Et il ne put faire là aucun miracle, sinon qu’il imposa les mains à un petit nombre d’infirmes, et les guérit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Et il s’étonnait de leur incrédulité; et il visitait l’un après l’autre les villages à la ronde, en enseignant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Et il appelle les douze; et il se mit à les envoyer deux à deux, et leur donna autorité sur les esprits immondes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Et il leur commanda de ne rien prendre pour le chemin, si ce n’est un bâton seulement, ni sac, ni pain, ni monnaie dans leur ceinture,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'mais d’être chaussés de sandales; et ne portez pas deux tuniques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Et il leur dit: Partout où vous entrerez dans une maison, demeurez-y jusqu’à ce que vous partiez de là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'et tous ceux qui ne vous recevront pas et ne vous écouteront pas, quand vous partirez de là, secouez la poussière de dessous vos pieds, pour leur servir de témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Et étant partis, ils prêchèrent qu’on se repente,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'et chassèrent beaucoup de démons, et oignirent d’huile beaucoup d’infirmes et les guérirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Et le roi Hérode entendit parler [de lui], car son nom était devenu public; et il dit: Jean le baptiseur est ressuscité d’entre les morts; et c’est pourquoi les miracles s’opèrent par lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Et d’autres disaient: C’est Élie; et d’autres disaient: C’est un prophète, comme un des prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Mais Hérode, ayant appris [ce qu’il faisait], dit: C’est Jean que j’ai fait décapiter; il est ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Car Hérode lui-même avait envoyé prendre Jean, et l’avait fait lier dans une prison, à cause d’Hérodias, la femme de Philippe son frère; car il l’avait épousée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Car Jean disait à Hérode: Il ne t’est pas permis d’avoir la femme de ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Et Hérodias lui en voulait, et aurait désiré le faire mourir; et elle ne pouvait pas,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'car Hérode craignait Jean, le sachant homme juste et saint, et il le gardait soigneusement; et lorsqu’il l’avait entendu, il faisait beaucoup de choses, et il l’écoutait volontiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Et un jour favorable étant venu, lorsque Hérode, le jour anniversaire de sa naissance, donnait un repas à ses grands seigneurs, et aux chiliarques, et aux principaux de la Galilée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'et la fille de cette même Hérodias, étant entrée et ayant dansé, plut à Hérode et à ceux qui étaient à table avec lui. Et le roi dit à la jeune fille: Demande-moi tout ce que tu voudras, et je te le donnerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Et il lui jura: Tout ce que tu me demanderas, je te le donnerai, jusqu’à la moitié de mon royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Et elle sortit et dit à sa mère: Que dois-je demander? Et celle-ci dit: La tête de Jean le baptiseur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Et aussitôt elle entra avec empressement vers le roi, et fit sa demande, disant: Je veux que sur-le-champ tu me donnes dans un plat la tête de Jean le baptiseur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Et le roi en fut très attristé, mais, à cause des serments et de ceux qui étaient à table avec lui, il ne voulut pas lui manquer de parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Et le roi aussitôt envoya un de ses gardes, et lui commanda d’apporter la tête de Jean. Et celui-ci, s’en étant allé, le décapita dans la prison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'et apporta sa tête dans un plat, et la donna à la jeune fille; et la jeune fille la donna à sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Et ses disciples, l’ayant appris, vinrent et enlevèrent son corps et le mirent dans un sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Et les apôtres se rassemblent auprès de Jésus; et ils lui racontèrent tout: et tout ce qu’ils avaient fait, et tout ce qu’ils avaient enseigné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Et il leur dit: Venez à l’écart vous-mêmes dans un lieu désert, et reposez-vous un peu; car il y avait beaucoup de gens qui allaient et qui venaient, et ils n’avaient pas même le loisir de manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Et ils s’en allèrent dans un bateau en un lieu désert, à l’écart.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Et plusieurs les virent qui s’en allaient, et les reconnurent, et accoururent là, à pied, de toutes les villes, et arrivèrent avant eux, [et se rassemblèrent auprès de lui].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Et Jésus, étant sorti, vit une grande foule; et il fut ému de compassion envers eux, parce qu’ils étaient comme des brebis qui n’ont pas de berger; et il se mit à leur enseigner beaucoup de choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Et comme l’heure était déjà fort avancée, ses disciples venant à lui, disent: Le lieu est désert et l’heure est déjà fort avancée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'renvoie-les, afin qu’ils s’en aillent dans les campagnes et les villages d’alentour, et qu’ils s’achètent du pain; car ils n’ont rien à manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Et lui, répondant, leur dit: Vous, donnez-leur à manger. Et ils lui disent: Irons-nous acheter pour 200 deniers de pain, et leur donnerons-nous à manger?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Mais il leur dit: Combien de pains avez-vous? Allez et regardez. Et quand ils le surent, ils disent: Cinq, et deux poissons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Et il leur commanda de les faire tous asseoir par troupes sur l’herbe verte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Et ils s’assirent en rangs, les uns de 100, et les autres de 50.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Et ayant pris les cinq pains et les deux poissons, et regardant vers le ciel, il bénit, et rompit les pains et les donna à ses disciples, afin qu’ils les mettent devant eux; et il partagea les deux poissons entre tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Et ils mangèrent tous, et furent rassasiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Et ils ramassèrent des morceaux douze paniers pleins, et des restes des poissons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Et ceux qui avaient mangé les pains étaient 5 000 hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Et aussitôt il contraignit ses disciples de monter dans le bateau, et d’aller devant [lui] à l’autre rive, vers Bethsaïda, tandis qu’il renvoyait la foule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Et leur ayant donné congé, il s’en alla sur une montagne pour prier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Et le soir étant venu, le bateau était au milieu de la mer, et lui, seul à terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Et les voyant se tourmenter à ramer, car le vent leur était contraire, vers la quatrième veille de la nuit, il vient vers eux, marchant sur la mer; et il voulait passer à côté d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Mais eux, le voyant marcher sur la mer, crurent que c’était un fantôme, et ils poussèrent des cris;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'car ils le virent tous, et ils furent troublés. Et aussitôt il parla avec eux, et leur dit: Ayez bon courage; c’est moi; n’ayez point de peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Et il monta vers eux dans le bateau, et le vent tomba. Et ils furent excessivement frappés et étonnés en eux-mêmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'car ils n’avaient pas été rendus intelligents par les pains, car leur cœur était endurci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Et ayant passé à l’autre rive, ils vinrent dans la contrée de Génésareth, et ils abordèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Et comme ils sortaient du bateau, ils le reconnurent aussitôt;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'et ils coururent par tout le pays d’alentour, et se mirent à apporter de tous côtés dans de petits lits ceux qui se portaient mal, là où ils entendaient dire qu’il était.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Et où que ce soit qu’il entrait, dans les villages, ou dans les villes, ou dans les campagnes, ils plaçaient les infirmes dans les marchés et le priaient de les laisser toucher ne serait-ce que le bord de son vêtement; et tous ceux qui le touchaient étaient guéris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Et les pharisiens et quelques-uns des scribes, qui étaient venus de Jérusalem, s’assemblent auprès de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Et voyant quelques-uns de ses disciples mangeant du pain avec des mains souillées, c’est-à-dire non lavées ...;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'car les pharisiens et tous les Juifs ne mangent pas qu’ils ne lavent soigneusement leurs mains, retenant la tradition des anciens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'et [étant de retour] du marché, ils ne mangent pas qu’ils ne soient lavés. Et il y a beaucoup d’autres choses qu’ils ont reçues traditionnellement pour les observer, [comme] de laver les coupes, les pots, les vases d’airain, et les lits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, '– Sur cela, les pharisiens et les scribes l’interrogent, [disant]: Pourquoi tes disciples ne marchent-ils pas selon la tradition des anciens, mais mangent-ils du pain avec des mains souillées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Mais lui, répondant, leur dit: Ésaïe a bien prophétisé de vous, hypocrites; comme il est écrit: « Ce peuple-ci m’honore des lèvres, mais leur cœur est fort éloigné de moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'mais ils m’honorent en vain, enseignant, comme doctrines, des commandements d’hommes ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Car, laissant le commandement de Dieu, vous observez la tradition des hommes, de laver les pots et les coupes; et vous faites beaucoup d’autres choses semblables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Et il leur dit: Vous annulez bien le commandement de Dieu, afin de garder votre tradition.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Car Moïse a dit: « Honore ton père et ta mère »; et: « que celui qui médira de père ou de mère, meure de mort »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'mais vous, vous dites: Si un homme dit à son père ou à sa mère: Tout ce dont tu pourrais tirer profit de ma part est corban, c’est-à-dire don...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'Et vous ne lui permettez plus de rien faire pour son père ou pour sa mère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'annulant la parole de Dieu par votre tradition que vous vous êtes transmise [les uns aux autres]; et vous faites beaucoup de choses semblables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Et ayant de nouveau appelé la foule, il leur dit: Écoutez-moi, vous tous, et comprenez:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Il n’y a rien en dehors de l’homme, qui, entrant au-dedans de lui, puisse le souiller; mais les choses qui sortent de lui, ce sont celles qui souillent l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Si quelqu’un a des oreilles pour entendre, qu’il entende.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Et quand il fut entré dans la maison, [s’étant retiré] d’avec la foule, ses disciples l’interrogèrent touchant cette parabole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Et il leur dit: Vous aussi, êtes-vous ainsi sans intelligence? N’entendez-vous pas que tout ce qui est de dehors, entrant dans l’homme, ne peut pas le souiller,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'parce que cela n’entre pas dans son cœur, mais dans son ventre, et s’en va dans les lieux d’aisances, purifiant toutes les viandes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Et il dit: Ce qui sort de l’homme, c’est là ce qui souille l’homme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'car du dedans, du cœur des hommes, sortent les mauvaises pensées, les adultères, les fornications, les meurtres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'les vols, la cupidité, les méchancetés, la fraude, l’impudicité, l’œil méchant, les injures, l’orgueil, la folie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Toutes ces mauvaises choses sortent du dedans et souillent l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Et se levant, il s’en alla de là vers les frontières de Tyr et de Sidon; et étant entré dans une maison, il ne voulait pas que personne le sache: et il ne put être caché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'car une femme dont la fille avait un esprit immonde, ayant entendu parler de lui, vint et se jeta à ses pieds;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, '(or la femme était grecque, syrophénicienne de race;) et elle le pria qu’il chasse le démon hors de sa fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Et Jésus lui dit: Laisse premièrement rassasier les enfants; car il ne convient pas de prendre le pain des enfants et de le jeter aux chiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Et elle répondit et lui dit: Oui, Seigneur; car même les chiens, sous la table, mangent des miettes des enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Et il lui dit: À cause de cette parole, va, le démon est sorti de ta fille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Et s’en allant en sa maison, elle trouva le démon sorti, et sa fille couchée sur le lit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Et étant de nouveau parti des confins de Tyr et de Sidon, il vint vers la mer de Galilée, à travers le pays de Décapolis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Et on lui amène un sourd qui parlait avec peine, et on le prie pour qu’il lui impose la main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Et l’ayant tiré à l’écart, hors de la foule, il lui mit les doigts dans les oreilles; et ayant craché, il lui toucha la langue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'et regardant vers le ciel, il soupira, et lui dit: Ephphatha, c’est-à-dire, ouvre-toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Et aussitôt ses oreilles s’ouvrirent, et le lien de sa langue se délia, et il parlait distinctement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Et Jésus leur enjoignit de ne le dire à personne; mais plus il le leur défendait, d’autant plus ils le publiaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Et ils étaient extrêmement étonnés, disant: il fait toutes choses bien; il fait entendre les sourds et parler les muets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'En ces jours-là, comme il y avait là une fort grande foule, et qu’ils n’avaient rien à manger, [Jésus], ayant appelé à lui ses disciples, leur dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Je suis ému de compassion envers la foule, car voici trois jours déjà qu’ils demeurent auprès de moi, et ils n’ont rien à manger;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'et si je les renvoie à jeun dans leurs maisons, ils tomberont en défaillance par le chemin; car quelques-uns d’entre eux sont venus de loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Et ses disciples lui répondirent: D’où pourra-t-on les rassasier de pain, ici, dans le désert?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Et il leur demanda: Combien avez-vous de pains? Et ils dirent: Sept.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Et il commanda à la foule de s’asseoir sur la terre. Et ayant pris les sept pains, il rendit grâces et les rompit et les donna à ses disciples pour les mettre devant la foule: et ils les mirent devant elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Ils avaient aussi quelques petits poissons; et ayant béni, il dit qu’ils les mettent aussi devant [la foule].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Et ils mangèrent et furent rassasiés; et ils ramassèrent, des morceaux qui étaient de reste, sept corbeilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Or ceux qui avaient mangé étaient environ 4 000. Et il les renvoya.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Et aussitôt, montant dans un bateau avec ses disciples, il vint aux quartiers de Dalmanutha.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Et les pharisiens sortirent et se mirent à disputer avec lui, demandant de lui un signe du ciel, pour l’éprouver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Et, soupirant en son esprit, il dit: Pourquoi cette génération demande-t-elle un signe? En vérité, je vous dis: il ne sera point donné de signe à cette génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Et les laissant, il remonta de nouveau dans le bateau et s’en alla à l’autre rive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Et ils avaient oublié de prendre des pains, et ils n’avaient qu’ un seul pain avec eux dans le bateau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Et il leur enjoignit, disant: Voyez, gardez-vous du levain des pharisiens et du levain d’Hérode.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Et ils raisonnaient entre eux, [disant]: C’est parce que nous n’avons pas de pains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Et Jésus, le sachant, leur dit: Pourquoi raisonnez-vous sur ce que vous n’avez pas de pains? N’entendez-vous pas encore, et ne comprenez-vous pas? Avez-vous encore votre cœur endurci?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Ayant des yeux, ne voyez-vous pas? et ayant des oreilles, n’entendez-vous pas? et n’avez-vous point de mémoire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Quand je rompis les cinq pains aux 5 000, combien avez-vous recueilli de paniers pleins de morceaux? Ils lui disent: Douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Et quand [je rompis] les sept aux 4 000, combien avez-vous recueilli de corbeilles pleines de morceaux? Et ils dirent: Sept.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Et il leur dit: Comment ne comprenez-vous pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Et il vient à Bethsaïda; et on lui amène un aveugle, et on le prie pour qu’il le touche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Et ayant pris la main de l’aveugle, il le mena hors de la bourgade; et lui ayant craché sur les yeux, il posa les mains sur lui et lui demanda s’il voyait quelque chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Et ayant regardé, [l’homme] dit: Je vois des hommes, car je vois comme des arbres qui marchent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Puis Jésus lui mit encore les mains sur les yeux et le fit regarder; et il fut rétabli, et voyait tout clairement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Et il le renvoya dans sa maison, disant: N’entre pas dans la bourgade, et ne le dis à personne dans la bourgade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Et Jésus s’en alla, et ses disciples, aux villages de Césarée de Philippe; et chemin faisant, il interrogea ses disciples, leur disant: Qui disent les hommes que je suis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Et ils répondirent: Jean le baptiseur; et d’autres: Élie; et d’autres: L’un des prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Et il leur demanda: Et vous, qui dites-vous que je suis? Et Pierre, répondant, lui dit: Tu es le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Et il leur défendit expressément de dire cela de lui à personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Et il commença à les enseigner: Il faut que le fils de l’homme souffre beaucoup, et qu’il soit rejeté des anciens et des principaux sacrificateurs et des scribes, et qu’il soit mis à mort, et qu’il ressuscite après trois jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Et il tenait ce discours ouvertement. Et Pierre, le prenant à part, se mit à le reprendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Mais lui, se retournant et regardant ses disciples, reprit Pierre, disant: Va arrière de moi, Satan, car tes pensées ne sont pas aux choses de Dieu, mais à celles des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Et ayant appelé la foule avec ses disciples, il leur dit: Quiconque veut venir après moi, qu’il se renonce soi-même, et qu’il prenne sa croix, et me suive:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'car quiconque voudra sauver sa vie la perdra; et quiconque perdra sa propre vie pour l’amour de moi et de l’évangile la sauvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Car que profitera-t-il à un homme s’il gagne le monde entier, et qu’il fasse la perte de son âme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'ou que donnera un homme en échange de son âme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Car quiconque aura honte de moi et de mes paroles parmi cette génération adultère et pécheresse, le fils de l’homme aura aussi honte de lui, quand il viendra dans la gloire de son Père, avec les saints anges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Et il leur dit: En vérité, je vous dis, que de ceux qui sont ici présents, il y en a quelques-uns qui ne goûteront point la mort jusqu’à ce qu’ils aient vu le royaume de Dieu venu avec puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Et après six jours, Jésus prend avec lui Pierre et Jacques et Jean, et les mène seuls à l’écart, sur une haute montagne. Et il fut transfiguré devant eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'et ses vêtements devinrent brillants et d’une extrême blancheur, comme de la neige, tels qu’il n’y a point de foulon sur la terre qui puisse ainsi blanchir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Et Élie leur apparut avec Moïse, et ils parlaient avec Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Et Pierre, répondant, dit à Jésus: Rabbi, il est bon que nous soyons ici; et faisons trois tentes: une pour toi, et une pour Moïse, et une pour Élie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Car il ne savait que dire; car ils étaient épouvantés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Et il vint une nuée qui les couvrit, et il vint de la nuée une voix: Celui-ci est mon Fils bien-aimé, écoutez-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Et aussitôt, ayant regardé de tous côtés, ils ne virent plus personne, sinon Jésus seul avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Et comme ils descendaient de la montagne, il leur enjoignit de ne raconter à personne ce qu’ils avaient vu, sinon lorsque le fils de l’homme serait ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Et ils gardèrent cette parole, s’entre-demandant ce que c’était que ressusciter d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Et ils l’interrogèrent, disant: Pourquoi les scribes disent-ils qu’il faut qu’Élie vienne premièrement?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Et lui, répondant, leur dit: En effet, Élie vient premièrement et rétablit toutes choses; – et comment il est écrit du fils de l’homme, qu’il souffrira beaucoup et qu’il sera chargé de mépris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Mais je vous dis qu’aussi Élie est venu, et ils lui ont fait tout ce qu’ils ont voulu, comme il est écrit de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Et venant vers les disciples, il vit autour d’eux une grande foule, et des scribes qui disputaient avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Et aussitôt toute la foule, le voyant, fut saisie d’étonnement; et ils accoururent et le saluèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Et il les interrogea, [disant]: De quoi disputez-vous avec eux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Et quelqu’un de la foule lui répondit: Maître, je t’ai amené mon fils qui a un esprit muet,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'et, partout où il le saisit, il l’agite violemment; et il écume, et grince des dents, et il devient sec; et j’ai dit à tes disciples de le chasser, et ils n’ont pas pu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Et lui, leur répondant, dit: Ô génération incrédule, jusques à quand serai-je avec vous? jusques à quand vous supporterai-je? Amenez-le -moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Et ils le lui amenèrent; et quand il l’eut vu, aussitôt l’esprit le déchira; et [l’enfant], tombant à terre, se roulait en écumant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Et Jésus demanda au père de l’enfant: Combien y a-t-il de temps que ceci lui est arrivé? Et il dit: Dès son enfance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'et souvent il l’a jeté dans le feu et dans les eaux pour le faire périr; mais si tu peux quelque chose, assiste-nous, étant ému de compassion envers nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Et Jésus lui dit: Le “Si tu peux”, c’est: Crois! toutes choses sont possibles à celui qui croit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Et aussitôt le père de l’enfant, s’écriant, dit avec larmes: Je crois, viens en aide à mon incrédulité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Et Jésus, voyant que la foule accourait ensemble, tança l’esprit immonde, lui disant: Esprit muet et sourd, je te commande, moi, sors de lui et n’y rentre plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Et ayant crié et l’ayant violemment déchiré, il sortit; et [l’enfant] devint comme mort, de sorte que la plupart disaient: Il est mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Et Jésus, l’ayant pris par la main, le redressa; et il se leva.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Et lorsqu’il fut entré dans la maison, ses disciples lui demandèrent en particulier: Pourquoi n’avons-nous pu le chasser?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Et il leur dit: Cette sorte ne peut sortir en aucune façon, si ce n’est par la prière et par le jeûne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Et étant sortis de là, ils traversèrent la Galilée; et il ne voulut pas que personne le sache.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Car il enseignait ses disciples et leur disait: Le fils de l’homme est livré entre les mains des hommes, et ils le feront mourir; et ayant été mis à mort, il ressuscitera le troisième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Mais ils ne comprenaient pas ce discours, et ils craignaient de l’interroger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Et il vint à Capernaüm; et quand il fut dans la maison, il leur demanda: Sur quoi raisonniez-vous en chemin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Et ils gardaient le silence, car ils avaient disputé entre eux, en chemin, qui serait le plus grand.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Et lorsqu’il se fut assis, il appela les douze et leur dit: Si quelqu’un veut être le premier, il sera le dernier de tous et le serviteur de tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Et ayant pris un petit enfant, il le plaça au milieu d’eux; et l’ayant pris entre ses bras, il leur dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Quiconque recevra l’un de tels petits enfants en mon nom, me reçoit; et quiconque me recevra, ce n’est pas moi qu’il reçoit, mais c’est celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Et Jean lui répondit, disant: Maître, nous avons vu quelqu’un qui chassait des démons en ton nom, qui ne nous suit pas; et nous le lui avons défendu, parce qu’il ne nous suit pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Et Jésus leur dit: Ne le lui défendez pas; car il n’y a personne qui fasse un miracle en mon nom, et qui puisse aussitôt mal parler de moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'car celui qui n’est pas contre nous est pour nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Car quiconque vous donnera à boire une coupe d’eau en [mon] nom, parce que vous êtes de Christ, en vérité, je vous dis qu’il ne perdra point sa récompense.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Et quiconque sera une occasion de chute pour un des petits qui croient en moi, mieux vaudrait pour lui qu’on lui mette au cou une pierre de meule, et qu’il soit jeté dans la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Et si ta main est pour toi une occasion de chute, coupe-la: il vaut mieux pour toi d’entrer estropié dans la vie, que d’avoir les deux mains, et d’aller dans la géhenne, dans le feu inextinguible,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'là où leur ver ne meurt pas et où le feu ne s’éteint pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Et si ton pied est pour toi une occasion de chute, coupe-le: il vaut mieux pour toi d’entrer boiteux dans la vie, que d’avoir les deux pieds, et d’être jeté dans la géhenne, dans le feu inextinguible,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'là où leur ver ne meurt pas et où le feu ne s’éteint pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Et si ton œil est pour toi une occasion de chute, arrache-le: il vaut mieux pour toi d’entrer dans le royaume de Dieu, n’ayant qu’un œil, que d’avoir deux yeux et d’être jeté dans la géhenne de feu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'là où leur ver ne meurt pas et où le feu ne s’éteint pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Car chacun sera salé de feu; et tout sacrifice sera salé de sel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Le sel est bon; mais si le sel devient insipide, avec quoi lui donnerez-vous de la saveur? Ayez du sel en vous-mêmes, et soyez en paix entre vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Et de là, se levant, il vient vers les confins de la Judée, et au-delà du Jourdain; et des foules se rassemblent encore auprès de lui; et il les enseignait encore, comme il avait coutume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Et des pharisiens vinrent à lui, et, pour l’éprouver, lui demandèrent: Est-il permis à un homme de répudier sa femme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Et lui, répondant, leur dit: Qu’est-ce que Moïse vous a commandé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Et ils dirent: Moïse a permis d’écrire une lettre de divorce, et de répudier [sa femme].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Et Jésus, répondant, leur dit: Il vous a écrit ce commandement à cause de votre dureté de cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'mais au commencement de la création, Dieu les fit mâle et femelle:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'c’est pourquoi l’homme laissera son père et sa mère et sera uni à sa femme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'et les deux seront une seule chair; ainsi ils ne sont plus deux, mais une seule chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Ce donc que Dieu a uni, que l’homme ne le sépare pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Et dans la maison encore, ses disciples l’interrogèrent sur ce sujet;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'et il leur dit: Quiconque répudiera sa femme et en épousera une autre, commet adultère envers la première;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'et si une femme répudie son mari, et en épouse un autre, elle commet adultère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Et on lui apporta de petits enfants, afin qu’il les touche; et les disciples reprenaient ceux qui les apportaient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'et Jésus, voyant [cela], en fut indigné, et leur dit: Laissez venir à moi les petits enfants; ne les en empêchez pas; car à de tels est le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'En vérité, je vous dis: quiconque ne recevra pas le royaume de Dieu comme un petit enfant, n’y entrera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Et les ayant pris entre ses bras, il posa les mains sur eux et les bénit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Et comme il sortait sur la route, un homme accourut, et, se jetant à genoux devant lui, il lui demanda: Bon maître, que ferai-je afin que j’hérite de la vie éternelle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Et Jésus lui dit: Pourquoi m’appelles-tu bon? Nul n’est bon, sinon un [seul], Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Tu sais les commandements: Ne commets point adultère; ne tue point; ne dérobe point; ne dis point de faux témoignage; ne fais tort à personne; honore ton père et ta mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Et répondant, il lui dit: Maître, j’ai gardé toutes ces choses dès ma jeunesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Et Jésus, l’ayant regardé, l’aima, et lui dit: Une chose te manque: va, vends tout ce que tu as et donne aux pauvres, et tu auras un trésor dans le ciel, et viens, suis-moi, ayant chargé la croix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Et lui, affligé de cette parole, s’en alla tout triste, car il avait de grands biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Et Jésus, ayant regardé tout à l’entour, dit à ses disciples: Combien difficilement ceux qui ont des biens entreront-ils dans le royaume de Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Et les disciples s’étonnèrent de ses paroles; et Jésus, répondant encore, leur dit: Enfants, combien il est difficile à ceux qui se confient aux richesses d’entrer dans le royaume de Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Il est plus facile qu’un chameau passe par un trou d’aiguille, qu’un riche n’entre dans le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Et ils s’en étonnèrent excessivement, disant entre eux: Et qui peut être sauvé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Et Jésus, les ayant regardés, dit: Pour les hommes, cela est impossible, mais non pas pour Dieu; car toutes choses sont possibles pour Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Pierre se mit à lui dire: Voici, nous avons tout quitté et nous t’avons suivi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jésus, répondant, dit: En vérité, je vous dis: il n’y a personne qui ait quitté maison, ou frères, ou sœurs, ou père, ou mère, [ou femme], ou enfants, ou champs, pour l’amour de moi et pour l’amour de l’évangile,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'qui n’en reçoive maintenant, en ce temps-ci, 100 fois autant, maisons, et frères, et sœurs, et mères, et enfants, et champs, avec des persécutions, et dans le siècle qui vient, la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Mais plusieurs qui sont les premiers seront les derniers; et les derniers seront les premiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Et ils étaient en chemin, montant à Jérusalem, et Jésus allait devant eux; et ils étaient stupéfiés et craignaient en le suivant. Et prenant encore une fois les douze avec lui, il se mit à leur dire les choses qui devaient lui arriver:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Voici, nous montons à Jérusalem; et le fils de l’homme sera livré aux principaux sacrificateurs et aux scribes; et ils le condamneront à mort, et le livreront aux nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'et ils se moqueront de lui, et le fouetteront, et cracheront contre lui, et le feront mourir; et il ressuscitera le troisième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Et Jacques et Jean, fils de Zébédée, viennent à lui, disant: Maître, nous voudrions que tu fasses pour nous tout ce que nous te demanderons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Et il leur dit: Que voulez-vous que je fasse pour vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Et ils lui dirent: Accorde-nous que nous soyons assis, l’un à ta droite et l’un à ta gauche, dans ta gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Et Jésus leur dit: Vous ne savez ce que vous demandez. Pouvez-vous boire la coupe que moi je bois, ou être baptisés du baptême dont moi je serai baptisé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Et ils lui dirent: Nous le pouvons. Et Jésus leur dit: Vous boirez bien la coupe que moi je bois, et vous serez baptisés du baptême dont moi je serai baptisé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'mais de s’asseoir à ma droite ou à ma gauche, n’est pas à moi pour le donner, sinon à ceux pour lesquels cela est préparé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Et les dix, l’ayant entendu, en conçurent de l’indignation à l’égard de Jacques et de Jean.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Et Jésus, les ayant appelés auprès de lui, leur dit: Vous savez que ceux qui sont réputés gouverner les nations dominent sur elles, et que les grands d’entre eux usent d’autorité sur elles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'mais il n’en est pas ainsi parmi vous, mais quiconque voudra devenir grand parmi vous, sera votre serviteur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'et quiconque d’entre vous voudra devenir le premier, sera l’esclave de tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Car aussi le fils de l’homme n’est pas venu pour être servi, mais pour servir et pour donner sa vie en rançon pour plusieurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Et ils arrivent à Jéricho; et comme il sortait de Jéricho avec ses disciples et une grande foule, Bartimée l’aveugle, le fils de Timée, était assis sur le bord du chemin et mendiait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Et ayant entendu dire que c’était Jésus le Nazarénien, il se mit à crier et à dire: Fils de David, Jésus, aie pitié de moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Et plusieurs le reprirent afin qu’il se taise; mais il criait d’autant plus fort: Fils de David! aie pitié de moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Et Jésus, s’arrêtant, dit qu’on l’appelle; et ils appellent l’aveugle, lui disant: Aie bon courage, lève-toi, il t’appelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Et jetant loin son vêtement, il se leva en hâte et s’en vint à Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Et Jésus, répondant, lui dit: Que veux-tu que je te fasse? Et l’aveugle lui dit: Rabboni, que je recouvre la vue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Et Jésus lui dit: Va, ta foi t’a guéri; et aussitôt il recouvra la vue, et il le suivit dans le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Et comme ils approchent de Jérusalem, de Bethphagé et de Béthanie, vers la montagne des Oliviers, il envoie deux de ses disciples');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'et leur dit: Allez au village qui est vis-à-vis de vous; et aussitôt, en y entrant, vous trouverez un ânon attaché, sur lequel jamais aucun homme ne s’est assis; détachez-le, et amenez-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Et si quelqu’un vous dit: Pourquoi faites-vous cela? dites: Le Seigneur en a besoin; et aussitôt il l’enverra ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Et ils s’en allèrent et trouvèrent un ânon qui était attaché dehors, à la porte, au carrefour; et ils le détachent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Et quelques-uns de ceux qui étaient là, leur dirent: Que faites-vous là à détacher l’ânon?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Et ils leur dirent comme Jésus avait commandé; et on les laissa faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Et ils amenèrent l’ânon à Jésus et mirent leurs vêtements sur l’ânon, et il s’assit dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Et plusieurs étendaient leurs vêtements sur le chemin, et d’autres coupaient des rameaux des arbres, et les répandaient sur le chemin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'et ceux qui allaient devant et ceux qui suivaient, criaient: Hosanna, béni soit celui qui vient au nom du ✶Seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Béni soit le royaume de notre père David, qui vient. Hosanna dans les lieux très hauts!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Et il entra dans Jérusalem, [et] dans le temple; et après avoir promené ses regards de tous côtés sur tout, comme le soir était déjà venu, il sortit [et s’en alla] à Béthanie avec les douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Et le lendemain, comme ils sortaient de Béthanie, il eut faim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Et, voyant de loin un figuier qui avait des feuilles, il s’en approcha pour voir si peut-être il y trouverait quelque chose; mais, y étant venu, il n’y trouva rien que des feuilles, car ce n’était pas la saison des figues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Et répondant, il lui dit: Que désormais personne ne mange jamais de fruit de toi. Et ses disciples l’entendirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Et ils s’en viennent à Jérusalem. Et, entrant au temple, il se mit à chasser dehors ceux qui vendaient et ceux qui achetaient dans le temple, et il renversa les tables des changeurs et les sièges de ceux qui vendaient les colombes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'et il ne permettait pas que personne porte aucun vase par le temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Et il les enseignait en disant: N’est-il pas écrit: « Ma maison sera appelée une maison de prière pour toutes les nations »? mais vous, vous en avez fait une caverne de voleurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Et les principaux sacrificateurs et les scribes l’entendirent, et ils cherchèrent comment ils le feraient mourir, car ils le craignaient, parce que toute la foule était dans l’étonnement à l’égard de sa doctrine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Et quand le soir fut venu, il sortit de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Et le matin, comme ils passaient, ils virent le figuier séché depuis les racines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Et Pierre, se ressouvenant [de ce qui s’était passé], lui dit: Rabbi, voici, le figuier que tu as maudit est sec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Et Jésus, répondant, leur dit: Ayez foi en Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'En vérité, je vous dis que quiconque dira à cette montagne: Ôte-toi, et jette-toi dans la mer, et qui ne doutera pas dans son cœur, mais croira que ce qu’il dit se fait, tout ce qu’il aura dit lui sera fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'C’est pourquoi je vous dis: Tout ce que vous demanderez en priant, croyez que vous le recevez, et il vous sera fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Et quand vous ferez votre prière, si vous avez quelque chose contre quelqu’un, pardonnez-lui, afin que votre Père aussi, qui est dans les cieux, vous pardonne vos fautes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Mais si vous ne pardonnez pas, votre Père qui est dans les cieux ne pardonnera pas non plus vos fautes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Et ils viennent encore à Jérusalem. Et comme il se promenait dans le temple, les principaux sacrificateurs, et les scribes et les anciens viennent à lui');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'et lui disent: Par quelle autorité fais-tu ces choses, et qui t’a donné cette autorité pour faire ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Et Jésus, répondant, leur dit: Je vous demanderai, moi aussi, une chose, et répondez-moi; et je vous dirai par quelle autorité je fais ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Le baptême de Jean, était-il du ciel ou des hommes? répondez-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Et ils raisonnaient entre eux, disant: Si nous disons: Du ciel, il dira: Pourquoi donc ne l’avez-vous pas cru?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Mais dirions-nous: Des hommes?... ils craignaient le peuple; car tous estimaient que Jean était réellement un prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Et répondant, ils disent à Jésus: Nous ne savons. Et Jésus leur dit: Moi non plus, je ne vous dis pas par quelle autorité je fais ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Et il se mit à leur dire en paraboles: Un homme planta une vigne, et l’environna d’une clôture, et y creusa une fosse pour un pressoir, et y bâtit une tour; et il la loua à des cultivateurs et s’en alla hors du pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Et en la saison, il envoya un esclave aux cultivateurs pour recevoir des cultivateurs du fruit de la vigne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'mais eux, le prenant, le battirent et le renvoyèrent à vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Et il leur envoya encore un autre esclave; et à celui-là ils lui meurtrirent la tête, et le couvrirent d’outrages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Et il en envoya un autre, et celui-là ils le tuèrent; et plusieurs autres, battant les uns, et tuant les autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Ayant donc encore un unique fils bien-aimé, il le leur envoya, lui aussi, le dernier, disant: Ils auront du respect pour mon fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Mais ces cultivateurs-là dirent entre eux: Celui-ci est l’héritier; venez, tuons-le, et l’héritage sera à nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Et l’ayant pris, ils le tuèrent et le jetèrent hors de la vigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Que fera donc le maître de la vigne? Il viendra et fera périr les cultivateurs et donnera la vigne à d’autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Et n’avez-vous pas même lu cette écriture: « La pierre que ceux qui bâtissaient ont rejetée, celle-là est devenue la maîtresse pierre du coin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'celle-ci est de par le ✶Seigneur, et est merveilleuse devant nos yeux »?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Et ils cherchaient à se saisir de lui; et ils craignirent la foule, car ils connurent qu’il avait dit cette parabole contre eux; et le laissant, ils s’en allèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Et ils lui envoient quelques-uns des pharisiens et des hérodiens pour le surprendre dans [ses] paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Et étant venus, ils lui disent: Maître, nous savons que tu es vrai, et que tu ne t’embarrasses de personne; car tu ne regardes pas à l’apparence des hommes, mais tu enseignes la voie de Dieu avec vérité. Est-il permis de payer le tribut à César, ou non? Paierons-nous, ou ne paierons-nous pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Et lui, connaissant leur hypocrisie, leur dit: Pourquoi me tentez-vous? Apportez-moi un denier, que je le voie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Et ils le lui apportèrent. Et il leur dit: De qui est cette image et cette inscription? Et ils lui dirent: De César.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Et Jésus, répondant, leur dit: Rendez les choses de César à César, et les choses de Dieu à Dieu! Et ils étaient dans l’étonnement à son sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Et les sadducéens, qui disent qu’il n’y a pas de résurrection, viennent à lui; et ils l’interrogèrent, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Maître! Moïse nous a écrit que si le frère de quelqu’un meurt et laisse une femme, et ne laisse pas d’enfants, son frère prenne sa femme et suscite de la postérité à son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Il y avait sept frères; et le premier prit une femme, et en mourant ne laissa pas de postérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'et le second la prit et mourut; et lui non plus ne laissa pas de postérité; et le troisième de même;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'et les sept la prirent et ne laissèrent pas de postérité. La dernière de tous, la femme aussi mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Dans la résurrection, quand ils ressusciteront, duquel d’entre eux sera-t-elle la femme, car les sept l’ont eue pour femme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Et Jésus, répondant, leur dit: N’est-ce pas à cause de ceci que vous errez, c’est que vous ne connaissez pas les écritures, ni la puissance de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Car, quand on ressuscite d’entre les morts, on ne se marie, ni on n’est donné en mariage, mais on est comme des anges dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Et quant aux morts [et] à ce qu’ils ressuscitent, n’avez-vous pas lu dans le livre de Moïse, au [titre]: “Du buisson”, comment Dieu lui parla, disant: « Moi, je suis le Dieu d’Abraham, et le Dieu d’Isaac, et le Dieu de Jacob »?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Il n’est pas le Dieu des morts, mais des vivants. Vous êtes donc dans une grande erreur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Et l’un des scribes, qui les avait entendus disputer, voyant qu’il leur avait bien répondu, s’approcha et lui demanda: Quel est le premier de tous les commandements?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Et Jésus lui répondit: Le premier de tous les commandements est: « Écoute, Israël, le ✶Seigneur notre Dieu est un seul ✶Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'et tu aimeras le ✶Seigneur ton Dieu de tout ton cœur, et de toute ton âme, et de toute ta pensée, et de toute ta force ». C’est là le premier commandement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Et le second lui est semblable: « Tu aimeras ton prochain comme toi-même ». Il n’y a point d’autre commandement plus grand que ceux-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Et le scribe lui dit: Bien, maître, tu as dit selon la vérité, car il y en a un, et il n’y en a point d’autre que lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'et que de l’aimer de tout son cœur, et de toute son intelligence, et de toute son âme, et de toute sa force, et d’aimer son prochain comme soi-même, c’est plus que tous les holocaustes et les sacrifices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Et Jésus, voyant qu’il avait répondu avec intelligence, lui dit: Tu n’es pas loin du royaume de Dieu. Et personne n’osait plus l’interroger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Et comme il enseignait dans le temple, Jésus répondit et dit: Comment disent les scribes que le Christ est fils de David?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Car David lui-même a dit par l’Esprit Saint: « Le ✶Seigneur a dit à mon seigneur: Assieds-toi à ma droite, jusqu’à ce que je mette tes ennemis pour marchepied de tes pieds ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'David lui-même donc l’appelle seigneur; et comment est-il son fils? Et la grande foule prenait plaisir à l’entendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Et il leur disait dans son enseignement: Gardez-vous des scribes, qui se plaisent à se promener en longues robes et [qui aiment] les salutations dans les places publiques,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'et les premiers sièges dans les synagogues, et les premières places dans les repas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'qui dévorent les maisons des veuves, et pour prétexte font de longues prières; – ceux-ci recevront une sentence plus sévère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Et Jésus, étant assis vis-à-vis du trésor [du temple], regardait comment la foule jetait de la monnaie au trésor; et plusieurs riches y jetaient beaucoup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Et une pauvre veuve vint, et y jeta deux pites, qui font un quadrant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Et ayant appelé ses disciples, il leur dit: En vérité, je vous dis que cette pauvre veuve a plus jeté au trésor que tous ceux qui y ont mis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'car tous y ont mis de leur superflu, mais celle-ci y a mis de son indigence, tout ce qu’elle avait, toute sa subsistance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Et comme il sortait du temple, un de ses disciples lui dit: Maître, regarde, quelles pierres et quels bâtiments!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Et Jésus, répondant, lui dit: Tu vois ces grands bâtiments? il ne sera point laissé pierre sur pierre qui ne soit jetée à bas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Et comme il était assis sur la montagne des Oliviers, vis-à-vis du temple, Pierre, et Jacques, et Jean, et André, l’interrogèrent en particulier:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Dis-nous quand ces choses auront lieu, et quel sera le signe quand toutes ces choses devront s’accomplir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Et Jésus, leur répondant, se mit à dire: Prenez garde que personne ne vous séduise;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'car plusieurs viendront en mon nom, disant: C’est moi! et ils en séduiront plusieurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Et quand vous entendrez parler de guerres et de bruits de guerres, ne soyez pas troublés, car il faut que [ces choses] arrivent; mais la fin n’est pas encore.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Car nation s’élèvera contre nation, et royaume contre royaume; et il y aura des tremblements de terre en divers lieux; et il y aura des famines et des troubles. Ces choses sont des commencements de douleurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Mais vous, prenez garde à vous-mêmes; car ils vous livreront aux sanhédrins et aux synagogues; vous serez battus, et vous serez traduits devant les gouverneurs et les rois à cause de moi, pour leur servir de témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Et il faut que l’évangile soit auparavant prêché dans toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Et quand ils vous mèneront pour vous livrer, ne soyez pas à l’avance en souci de ce que vous direz, et ne méditez pas [votre discours]; mais tout ce qui vous sera donné en cette heure-là, dites-le; car ce n’est pas vous qui parlez, mais l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Et le frère livrera son frère à la mort, et le père son enfant; et les enfants s’élèveront contre leurs parents et les feront mourir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'et vous serez haïs de tous à cause de mon nom; et celui qui persévérera jusqu’à la fin, celui-là sera sauvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Et quand vous verrez l’abomination de la désolation établie où elle ne doit pas être (que celui qui lit comprenne), alors que ceux qui sont en Judée s’enfuient dans les montagnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'et que celui qui est sur le toit ne descende pas dans la maison, et n’y entre pas pour emporter quoi que ce soit hors de sa maison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'et que celui qui est aux champs ne retourne pas en arrière pour emporter son vêtement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Mais malheur à celles qui sont enceintes et à celles qui allaitent en ces jours-là!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Et priez que [cela] n’ait pas lieu en hiver;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'car ces jours-là seront une tribulation telle qu’il n’y en a point eu de semblable depuis le commencement de la création que Dieu a créée, jusqu’à maintenant, et qu’il n’y en aura jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Et si le ✶Seigneur n’avait abrégé ces jours, nulle chair n’aurait été sauvée; mais à cause des élus qu’il a élus, il a abrégé les jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Et alors, si quelqu’un vous dit: Voici, le Christ est ici, ou: Voici, il est là, ne le croyez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Car il s’élèvera de faux christs et de faux prophètes; et ils montreront des signes et des prodiges, pour séduire, si possible, même les élus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Mais vous, soyez sur vos gardes! voici, je vous ai tout dit à l’avance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Mais en ces jours-là, après cette tribulation, le soleil sera obscurci, et la lune ne donnera pas sa lumière,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'et les étoiles du ciel tomberont, et les puissances qui sont dans les cieux seront ébranlées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Et alors ils verront le fils de l’homme venant sur les nuées avec une grande puissance et avec gloire:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'et alors il enverra ses anges, et il rassemblera ses élus des quatre vents, depuis le bout de la terre jusqu’au bout du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Mais apprenez du figuier la parabole [qu’il vous offre]: Quand déjà son rameau est tendre et qu’il pousse des feuilles, vous connaissez que l’été est proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'De même aussi vous, quand vous verrez arriver ces choses, sachez que cela est proche, à la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'En vérité, je vous dis que cette génération ne passera point que toutes ces choses ne soient arrivées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Mais quant à ce jour-là, ou à l’heure, personne n’en a connaissance, pas même les anges qui sont dans le ciel, ni même le Fils, mais le Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Prenez garde, veillez et priez, car vous ne savez pas quand ce temps sera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, '– C’est comme un homme allant hors du pays, laissant sa maison, et donnant de l’autorité à ses esclaves, et à chacun son ouvrage...; et il commanda au portier de veiller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Veillez donc; car vous ne savez pas quand le maître de la maison viendra, le soir, ou à minuit, ou au chant du coq, ou au matin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'de peur qu’arrivant tout à coup, il ne vous trouve dormant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Or ce que je vous dis, à vous, je le dis à tous: Veillez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Or, deux jours après, c’était la Pâque et les Pains sans levain. Et les principaux sacrificateurs et les scribes cherchaient comment ils pourraient se saisir de lui par ruse, et le faire mourir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'car ils disaient: Non pas pendant la fête, de peur qu’il n’y ait du tumulte parmi le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Et comme il était à Béthanie dans la maison de Simon le lépreux, et qu’il était à table, une femme vint, ayant un vase d’albâtre [plein] d’un parfum de nard pur et de grand prix; et, ayant brisé le vase, elle le répandit sur sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Et quelques-uns étaient [là], qui s’indignaient en eux-mêmes et disaient: À quoi bon la perte de ce parfum?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Car ce parfum aurait pu être vendu plus de 300 deniers, et être donné aux pauvres; et ils la reprenaient vivement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Mais Jésus dit: Laissez-la; pourquoi lui donnez-vous du déplaisir? Elle a fait une bonne œuvre envers moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'car vous avez toujours les pauvres avec vous, et quand vous voudrez, vous pourrez leur faire du bien; mais moi, vous ne m’avez pas toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Ce qui était en son pouvoir, elle l’a fait; elle a anticipé [le moment] d’oindre mon corps pour ma sépulture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Et en vérité, je vous dis: en quelque lieu que cet évangile soit prêché dans le monde entier, on parlera aussi de ce que cette femme a fait, en mémoire d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Et Judas Iscariote, l’un des douze, s’en alla vers les principaux sacrificateurs pour le leur livrer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'et ceux-ci, l’ayant entendu, s’en réjouirent et promirent de lui donner de l’argent; et il cherchait comment il le livrerait commodément.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Et le premier jour des pains sans levain, lorsqu’on sacrifiait la pâque, ses disciples lui disent: Où veux-tu que nous allions préparer [ce qu’il faut], afin que tu manges la pâque?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Et il envoie deux de ses disciples et leur dit: Allez à la ville; et un homme portant une cruche d’eau viendra à votre rencontre; suivez-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Et où qu’il entre, dites au maître de la maison: Le maître dit: Où est mon logis où je mangerai la pâque avec mes disciples?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Et lui vous montrera une grande chambre garnie, toute prête; apprêtez-nous là [ce qu’il faut].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Et ses disciples s’en allèrent et entrèrent dans la ville, et trouvèrent [tout] comme il leur avait dit; et ils apprêtèrent la pâque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Et le soir étant venu, il vient avec les douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Et comme ils étaient à table et qu’ils mangeaient, Jésus dit: En vérité, je vous dis que l’un d’entre vous qui mange avec moi, me livrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Et ils commencèrent à s’attrister et à lui dire l’un après l’autre: Est-ce moi? Et un autre: Est-ce moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Mais répondant, il leur dit: C’est l’un d’entre les douze qui trempe avec moi au plat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Le fils de l’homme s’en va, selon qu’il est écrit de lui; mais malheur à cet homme par qui le fils de l’homme est livré! Il aurait été bon pour cet homme-là qu’il ne soit pas né.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Et comme ils mangeaient, Jésus, ayant pris un pain [et] ayant béni, le rompit et le leur donna, et dit: Prenez; ceci est mon corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Et ayant pris la coupe [et] ayant rendu grâces, il la leur donna; et ils en burent tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Et il leur dit: Ceci est mon sang, le [sang] de la nouvelle alliance, qui est versé pour plusieurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'En vérité, je vous dis que je ne boirai plus du fruit de la vigne, jusqu’à ce jour où je le boirai nouveau dans le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Et ayant chanté une hymne, ils sortirent [et s’en allèrent] à la montagne des Oliviers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Et Jésus leur dit: Vous serez tous scandalisés; car il est écrit: « Je frapperai le berger, et les brebis seront dispersées »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'mais après que je serai ressuscité, j’irai devant vous en Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Et Pierre lui dit: Si même tous étaient scandalisés, je ne le serai pourtant pas, moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Et Jésus lui dit: En vérité, je te dis qu’aujourd’hui, cette nuit-ci, avant que le coq ait chanté deux fois, toi, tu me renieras trois fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Mais [Pierre] disait encore plus fortement: Quand il me faudrait mourir avec toi, je ne te renierai point. Et ils dirent tous aussi la même chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Et ils viennent en un lieu dont le nom était Gethsémané. Et il dit à ses disciples: Asseyez-vous ici, jusqu’à ce que j’aie prié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Et il prend avec lui Pierre et Jacques et Jean; et il commença à être saisi d’effroi et fort angoissé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Et il leur dit: Mon âme est saisie de tristesse jusqu’à la mort; demeurez ici et veillez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Et s’en allant un peu plus avant, il se jeta contre terre, et il priait que, s’il était possible, l’heure passe loin de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Et il disait: Abba, Père, toutes choses te sont possibles; fais passer cette coupe loin de moi; toutefois non pas ce que je veux, moi, mais ce que tu veux, toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Et il vient, et les trouve dormant; et il dit à Pierre: Simon, tu dors? Tu n’as pu veiller une heure?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Veillez et priez, afin que vous n’entriez pas en tentation; l’esprit est prompt, mais la chair est faible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Et il s’en alla de nouveau, et il pria, disant les mêmes paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Et s’en étant retourné, il les trouva de nouveau dormant (car leurs yeux étaient appesantis); et ils ne savaient que lui répondre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Et il vient pour la troisième fois et leur dit: Dormez dorénavant et reposez-vous; il suffit, l’heure est venue; voici, le fils de l’homme est livré entre les mains des pécheurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Levez-vous, allons; voici, celui qui me livre s’est approché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Et aussitôt, comme il parlait encore, Judas, l’un des douze, se trouve là, et avec lui une grande foule avec des épées et des bâtons, de la part des principaux sacrificateurs et des scribes et des anciens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Et celui qui le livrait leur avait donné un signe, disant: Celui que j’embrasserai, c’est lui; saisissez-le, et emmenez-le sûrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Et quand il fut venu, aussitôt s’approchant de lui, il dit: Rabbi, Rabbi! et il l’embrassa avec empressement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Et ils mirent les mains sur lui et se saisirent de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Et l’un de ceux qui étaient là présents, ayant tiré l’épée, frappa l’esclave du souverain sacrificateur, et lui emporta l’oreille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Et Jésus, répondant, leur dit: Êtes-vous sortis comme après un brigand, avec des épées et des bâtons, pour me prendre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'J’étais tous les jours avec vous, enseignant dans le temple, et vous ne vous êtes pas saisis de moi; mais c’est afin que les écritures soient accomplies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Et tous le laissèrent et s’enfuirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Et un certain jeune homme le suivit, enveloppé d’une toile de fin lin sur le corps nu; et ils le saisissent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'et, abandonnant la toile de fin lin, il leur échappa tout nu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Et ils amenèrent Jésus au souverain sacrificateur; et tous les principaux sacrificateurs et les anciens et les scribes s’assemblent auprès de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Et Pierre le suivit de loin, jusque dans l’intérieur du palais du souverain sacrificateur, et il s’assit avec les huissiers, et se chauffait près du feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Or les principaux sacrificateurs et tout le sanhédrin cherchaient [quelque] témoignage contre Jésus, pour le faire mourir; et ils n’en trouvaient point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Car plusieurs portaient de faux témoignages contre lui; et les témoignages ne s’accordaient pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Et quelques-uns s’élevèrent et portèrent un faux témoignage contre lui, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Nous l’avons entendu disant: Moi, je détruirai ce temple qui est fait de main, et en trois jours j’en bâtirai un autre qui ne sera pas fait de main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Et ainsi non plus leur témoignage ne s’accordait pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Et le souverain sacrificateur, se levant devant tous, interrogea Jésus, disant: Ne réponds-tu rien? De quoi ceux-ci témoignent-ils contre toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Et il garda le silence, et ne répondit rien. Le souverain sacrificateur l’interrogea encore, et lui dit: Toi, tu es le Christ, le Fils du Béni?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Et Jésus dit: Je le suis; et vous verrez le fils de l’homme assis à la droite de la puissance, et venant avec les nuées du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Et le souverain sacrificateur, ayant déchiré ses vêtements, dit: Qu’avons-nous encore besoin de témoins?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Vous avez entendu le blasphème: que vous en semble? Et tous le condamnèrent comme méritant la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Et quelques-uns se mirent à cracher contre lui, et à lui couvrir le visage, et à lui donner des soufflets, et à lui dire: Prophétise. Et les huissiers le frappaient de leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Et comme Pierre était en bas, dans la cour, une des servantes du souverain sacrificateur vient,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'et, apercevant Pierre qui se chauffait, elle le regarda et dit: Et toi, tu étais avec le Nazarénien Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Et il le nia, disant: Je ne sais ni n’entends ce que tu dis. Et il sortit dehors dans le vestibule; et le coq chanta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Et la servante, l’apercevant encore, se mit à dire à ceux qui étaient là: Celui-ci est de ces gens-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Et il le nia de nouveau. Et encore un peu après, ceux qui étaient là présents dirent à Pierre: Certainement tu es de ces gens-là; car aussi tu es Galiléen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Et il se mit à faire des imprécations et à jurer: Je ne connais pas cet homme dont vous parlez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Et le coq chanta pour la seconde fois. Et Pierre se ressouvint de la parole que Jésus lui avait dite: Avant que le coq chante deux fois, tu me renieras trois fois. Et en y pensant, il pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Et aussitôt, au matin, les principaux sacrificateurs avec les anciens et les scribes et tout le sanhédrin, ayant tenu conseil, lièrent Jésus et l’emmenèrent et le livrèrent à Pilate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Et Pilate l’interrogea: Toi, tu es le roi des Juifs? Et répondant, il lui dit: Tu le dis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Et les principaux sacrificateurs l’accusaient de beaucoup de choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Et Pilate l’interrogea encore, disant: Ne réponds-tu rien? Vois de combien de choses ils portent témoignage contre toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Mais encore Jésus ne répondit rien, de sorte que Pilate s’en étonnait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Or il leur relâchait à la fête un prisonnier, lequel que ce soit qu’ils demandent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Et il y avait le nommé Barabbas qui était détenu avec ses compagnons de sédition, lesquels, dans la sédition, avaient commis un meurtre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Et la foule, poussant des cris, se mit à lui demander [de faire] comme il leur avait toujours fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Et Pilate leur répondit, disant: Voulez-vous que je vous relâche le roi des Juifs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Car il savait que les principaux sacrificateurs l’avaient livré par envie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Mais les principaux sacrificateurs excitèrent le peuple [à demander] que plutôt il leur relâche Barabbas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Et Pilate, répondant, leur dit encore: Que voulez-vous donc que je fasse de celui que vous appelez roi des Juifs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Et ils s’écrièrent encore: Crucifie-le!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Et Pilate leur dit: Mais quel mal a-t-il fait? Et ils s’écrièrent encore plus fort: Crucifie-le!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Et Pilate, voulant contenter la foule, leur relâcha Barabbas; et, ayant fait fouetter Jésus, il le livra pour être crucifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Et les soldats l’emmenèrent dans la cour, qui est le prétoire. Et ils assemblent toute la cohorte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'et ils le revêtent de pourpre, et ayant tressé une couronne d’épines, ils la lui mettent autour [de la tête].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'Et ils se mirent à le saluer, [disant]: Salut, roi des Juifs!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Et ils lui frappaient la tête avec un roseau et crachaient contre lui, et, se mettant à genoux, ils lui rendaient hommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Et après qu’ils se furent moqués de lui, ils le dépouillèrent de la pourpre et le revêtirent de ses propres vêtements; et ils l’emmènent dehors pour le crucifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Et ils contraignent un certain homme, Simon, Cyrénéen, père d’Alexandre et de Rufus, qui passait par là, venant des champs, de porter sa croix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Et ils le mènent au lieu [appelé] Golgotha, ce qui, interprété, est: lieu du crâne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Et ils lui donnèrent à boire du vin mixtionné de myrrhe; mais il ne le prit pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Et l’ayant crucifié, ils partagent ses vêtements, en tirant au sort [pour savoir] ce que chacun en prendrait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Et c’était la troisième heure, et ils le crucifièrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Et l’écriteau concernant le sujet de son accusation portait écrit: Le roi des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Et, avec lui, ils crucifient deux brigands, un à sa droite, et un à sa gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, '[Et l’écriture fut accomplie, qui dit: « Et il a été compté parmi les iniques »].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Et ceux qui passaient par là, l’injuriaient, hochant la tête et disant: Hé! toi qui détruis le temple et qui le bâtis en trois jours,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'sauve-toi toi-même, et descends de la croix!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Pareillement aussi les principaux sacrificateurs, se moquant entre eux avec les scribes, disaient: Il a sauvé les autres, il ne peut se sauver lui-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Que le Christ, le roi d’Israël, descende maintenant de la croix, afin que nous voyions et que nous croyions! Ceux aussi qui étaient crucifiés avec lui l’insultaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Et quand la sixième heure fut venue, il y eut des ténèbres sur tout le pays jusqu’à la neuvième heure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Et à la neuvième heure, Jésus s’écria d’une forte voix, disant: Éloï, Éloï, lama sabachthani? ce qui, interprété, est: Mon Dieu, mon Dieu, pourquoi m’as-tu abandonné?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Et quelques-uns de ceux qui étaient là présents, ayant entendu cela, disaient: Voici, il appelle Élie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Et l’un d’eux courut, et ayant rempli une éponge de vinaigre et l’ayant mise au bout d’un roseau, il lui donna à boire, disant: Laissez, voyons si Élie vient pour le faire descendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Et Jésus, ayant jeté un grand cri, expira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Et le voile du temple se déchira en deux, depuis le haut jusqu’en bas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Et le centurion qui était là vis-à-vis de lui, voyant qu’il avait expiré en criant ainsi, dit: Certainement, cet homme était Fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Et il y avait aussi des femmes qui regardaient de loin, entre lesquelles étaient aussi Marie de Magdala, et Marie, la mère de Jacques le mineur et de Joses, et Salomé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'qui, lorsqu’il était en Galilée, l’avaient suivi et l’avaient servi, et plusieurs autres qui étaient montées avec lui à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Et le soir étant déjà venu, puisque c’était la Préparation, ce qui est le jour qui précède un sabbat,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Joseph qui était d’Arimathée, conseiller honorable, qui aussi lui-même attendait le royaume de Dieu, vint et prit sur lui d’entrer auprès de Pilate, et lui demanda le corps de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Et Pilate s’étonna, [ayant peine à croire] qu’il soit déjà mort; et ayant appelé le centurion, il lui demanda s’il y avait longtemps qu’il était mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Et l’ayant appris du centurion, il donna le corps à Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Et Joseph, ayant acheté un linceul, le descendit, et l’enveloppa du linceul, et le mit dans un sépulcre qui était taillé dans le roc, et roula une pierre contre la porte du sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Et Marie de Magdala, et Marie, la [mère] de Joses, regardaient où on le mettait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Et le sabbat étant passé, Marie de Magdala, et Marie, la [mère] de Jacques, et Salomé, achetèrent des aromates pour venir l’embaumer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Et de fort grand matin, le premier jour de la semaine, elles viennent au sépulcre, comme le soleil se levait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Et elles disaient entre elles: Qui nous roulera la pierre de devant la porte du sépulcre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Et ayant regardé, elles voient que la pierre était roulée; car elle était fort grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Et étant entrées dans le sépulcre, elles virent un jeune homme assis du côté droit, vêtu d’une robe blanche, et elles s’épouvantèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Et lui leur dit: Ne vous épouvantez point; vous cherchez Jésus le Nazarénien, le crucifié: il est ressuscité, il n’est pas ici; voici le lieu où on l’avait mis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Mais allez, dites à ses disciples et à Pierre: Il s’en va devant vous en Galilée; là vous le verrez, comme il vous l’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Et sortant, elles s’enfuirent du sépulcre. Et le tremblement et le trouble les avaient saisies; et elles ne dirent rien à personne, car elles avaient peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Et étant ressuscité le matin, le premier jour de la semaine, il apparut premièrement à Marie de Magdala, de laquelle il avait chassé sept démons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Elle, s’en allant, l’annonça à ceux qui avaient été avec lui, qui étaient dans le deuil et pleuraient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Et ceux-ci, apprenant qu’il était vivant et qu’il avait été vu d’elle, ne le crurent point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Et après ces choses, il apparut sous une autre forme à deux d’entre eux qui étaient en chemin, allant aux champs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Et ceux-ci s’en allèrent et l’annoncèrent aux autres; mais ils ne crurent pas ceux-là non plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Plus tard, il apparut aux onze, comme ils étaient à table, et leur reprocha leur incrédulité et leur dureté de cœur, parce qu’ils n’avaient pas cru ceux qui l’avaient vu ressuscité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Et il leur dit: Allez dans tout le monde, et prêchez l’évangile à toute la création.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Celui qui aura cru et qui aura été baptisé sera sauvé; et celui qui n’aura pas cru sera condamné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Et ce sont ici les signes qui accompagneront ceux qui auront cru: en mon nom ils chasseront les démons; ils parleront de nouvelles langues;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'ils prendront des serpents; et quand ils auront bu quelque chose de mortel, cela ne leur nuira point; ils imposeront les mains aux infirmes, et ceux-ci se porteront bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Le Seigneur donc, après leur avoir parlé, fut élevé en haut dans le ciel, et s’assit à la droite de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, '– Et eux, étant partis, prêchèrent partout, le Seigneur coopérant avec eux, et confirmant la parole par les signes qui l’accompagnaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Puisque plusieurs ont entrepris de rédiger un récit des choses qui sont reçues parmi nous avec une pleine certitude,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'comme nous les ont transmises ceux qui, dès le commencement, ont été les témoins oculaires et les ministres de la parole,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'il m’a semblé bon à moi aussi, qui ai suivi exactement toutes choses depuis le commencement, très excellent Théophile, de te [les] écrire par ordre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'afin que tu connaisses la certitude des choses dont tu as été instruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Aux jours d’Hérode, roi de Judée, il y avait un certain sacrificateur, nommé Zacharie, de la classe d’Abia; et sa femme était des filles d’Aaron, et son nom était Élisabeth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Et ils étaient tous deux justes devant Dieu, marchant dans tous les commandements et dans toutes les ordonnances du ✶Seigneur, sans reproche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Et ils n’avaient pas d’enfant, parce qu’Élisabeth était stérile; et ils étaient tous deux fort avancés en âge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Or il arriva, pendant qu’il exerçait la sacrificature devant Dieu dans l’ordre de sa classe,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'que, selon la coutume de la sacrificature, le sort lui échut d’offrir le parfum en entrant dans le temple du ✶Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Et toute la multitude du peuple priait dehors, à l’heure du parfum.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Et un ange du ✶Seigneur lui apparut, se tenant au côté droit de l’autel du parfum.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Et Zacharie, le voyant, fut troublé, et la crainte le saisit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Et l’ange lui dit: Ne crains pas, Zacharie, parce que tes supplications ont été exaucées, et ta femme Élisabeth t’enfantera un fils, et tu appelleras son nom Jean.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Et il sera pour toi un sujet de joie et d’allégresse, et plusieurs se réjouiront de sa naissance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'car il sera grand devant le ✶Seigneur, et il ne boira ni vin ni cervoise; et il sera rempli de l’Esprit Saint déjà dès le ventre de sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Et il fera retourner plusieurs des fils d’Israël au ✶Seigneur leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Et il ira devant lui dans l’esprit et la puissance d’Élie, pour faire retourner les cœurs des pères vers les enfants, et les désobéissants à la pensée des justes, pour préparer au ✶Seigneur un peuple bien disposé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Et Zacharie dit à l’ange: Comment connaîtrai-je cela? car moi, je suis un vieillard, et ma femme est fort avancée en âge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Et l’ange, répondant, lui dit: Moi, je suis Gabriel, qui me tiens devant Dieu, et j’ai été envoyé pour te parler et pour t’annoncer ces bonnes nouvelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Et voici, tu seras muet et tu ne pourras point parler jusqu’au jour où ces choses arriveront, parce que tu n’as pas cru mes paroles qui s’accompliront en leur temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Et le peuple attendait Zacharie; et ils s’étonnaient de ce qu’il tardait tant dans le temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Et quand il fut sorti, il ne pouvait pas leur parler: et ils reconnurent qu’il avait vu une vision dans le temple; et lui-même leur faisait des signes, et il demeura muet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Et il arriva que, quand les jours de son ministère furent accomplis, il s’en alla dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Or après ces jours, Élisabeth sa femme conçut, et elle se cacha cinq mois, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Le ✶Seigneur m’a ainsi fait aux jours où il m’a regardée, pour ôter mon opprobre parmi les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Et au sixième mois, l’ange Gabriel fut envoyé par Dieu dans une ville de Galilée, nommée Nazareth,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'à une vierge, fiancée à un homme dont le nom était Joseph, de la maison de David; et le nom de la vierge était Marie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Et l’ange étant entré auprès d’elle, dit: Je te salue, toi que [Dieu] fait jouir de sa faveur! Le ✶Seigneur est avec toi; tu es bénie entre les femmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Et elle, le voyant, fut troublée à sa parole; et elle raisonnait en elle-même sur ce que pourrait être cette salutation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Et l’ange lui dit: Ne crains pas, Marie, car tu as trouvé grâce auprès de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Et voici, tu concevras dans ton ventre, et tu enfanteras un fils, et tu appelleras son nom Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Il sera grand et sera appelé le Fils du Très-haut; et le ✶Seigneur Dieu lui donnera le trône de David son père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'et il régnera sur la maison de Jacob à toujours, et il n’y aura pas de fin à son royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Et Marie dit à l’ange: Comment ceci arrivera-t-il, puisque je ne connais pas d’homme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Et l’ange répondant, lui dit: L’Esprit Saint viendra sur toi, et la puissance du Très-haut te couvrira de son ombre; c’est pourquoi aussi la sainte chose qui naîtra sera appelée Fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Et voici, Élisabeth ta parente, elle aussi a conçu un fils dans sa vieillesse, et c’est ici le sixième mois pour celle qui était appelée stérile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'car rien ne sera impossible à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Et Marie dit: Voici l’esclave du ✶Seigneur; qu’il me soit fait selon ta parole. Et l’ange se retira d’auprès d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Et Marie, se levant en ces jours-là, s’en alla en hâte au pays des montagnes, dans une ville de Juda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'Et elle entra dans la maison de Zacharie et salua Élisabeth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Et il arriva, comme Élisabeth entendait la salutation de Marie, que le petit enfant tressaillit dans son ventre; et Élisabeth fut remplie de l’Esprit Saint,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'et elle s’écria à haute voix et dit: Tu es bénie entre les femmes, et béni est le fruit de ton ventre!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Et d’où me vient ceci, que la mère de mon Seigneur vienne vers moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Car voici, dès que la voix de ta salutation est parvenue à mes oreilles, le petit enfant a tressailli de joie dans mon ventre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Et bienheureuse est celle qui a cru; car il y aura un accomplissement des choses qui lui ont été dites de la part du ✶Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Et Marie dit: Mon âme magnifie le ✶Seigneur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'et mon esprit s’est réjoui en Dieu mon Sauveur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'car il a regardé l’humble état de son esclave; car voici, désormais toutes les générations me diront bienheureuse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'car le Puissant m’a fait de grandes choses, et son nom est saint;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'et sa miséricorde est de générations en générations sur ceux qui le craignent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Il a agi puissamment par son bras; il a dispersé les orgueilleux dans la pensée de leur cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'il a fait descendre les puissants de leurs trônes, et il a élevé les petits;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'il a rempli de biens ceux qui avaient faim, et il a renvoyé les riches à vide;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'il a pris la cause d’Israël, son serviteur, pour se souvenir de sa miséricorde');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, '(selon qu’il avait parlé à nos pères) envers Abraham et envers sa semence, à jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, '– Et Marie demeura avec elle environ trois mois; et elle s’en retourna en sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Or le temps où elle devait accoucher fut accompli pour Élisabeth, et elle mit au monde un fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Et ses voisins et ses parents apprirent que le ✶Seigneur avait magnifié sa miséricorde envers elle, et ils se réjouirent avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Et il arriva qu’au huitième jour ils vinrent pour circoncire le petit enfant; et ils l’appelaient Zacharie, du nom de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Et sa mère, répondant, dit: Non, mais il sera appelé Jean.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Et ils lui dirent: Il n’y a personne dans ta parenté qui soit appelé de ce nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Et ils firent signe à son père [qu’il déclare] comment il voulait qu’il soit appelé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Et ayant demandé des tablettes, il écrivit, disant: Jean est son nom. Et ils en furent tous étonnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Et à l’instant sa bouche fut ouverte et sa langue [déliée]; et il parlait, louant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Et tous leurs voisins furent saisis de crainte; et on s’entretenait de toutes ces choses par tout le pays des montagnes de la Judée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'et tous ceux qui les entendirent, les mirent dans leur cœur, disant: Que sera donc cet enfant? Et la main du ✶Seigneur était avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Et Zacharie, son père, fut rempli de l’Esprit Saint, et prophétisa, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Béni soit le ✶Seigneur, le Dieu d’Israël, car il a visité et sauvé son peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'et nous a suscité une corne de délivrance dans la maison de David son serviteur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'selon ce qu’il avait dit par la bouche de ses saints prophètes, qui ont été de tout temps,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'une délivrance de nos ennemis et de la main de tous ceux qui nous haïssent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'pour accomplir la miséricorde envers nos pères et pour se souvenir de sa sainte alliance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'du serment qu’il a juré à Abraham notre père, de nous accorder,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'étant libérés de la main de nos ennemis, de le servir sans crainte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'en sainteté et en justice devant lui, tous nos jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Et toi, petit enfant, tu seras appelé prophète du Très-haut: car tu iras devant la face du ✶Seigneur pour préparer ses voies,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'pour donner la connaissance du salut à son peuple, dans la rémission de leurs péchés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'par les entrailles de miséricorde de notre Dieu, selon lesquelles l’Orient d’en haut nous a visités,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'afin de luire à ceux qui sont assis dans les ténèbres et dans l’ombre de la mort, pour conduire nos pieds dans le chemin de la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Et l’enfant croissait et se fortifiait en esprit; et il fut dans les déserts jusqu’au jour de sa manifestation à Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Or il arriva, en ces jours-là, qu’un décret fut rendu de la part de César Auguste, [portant] qu’il soit fait un recensement de toute la terre habitée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, '(Le recensement lui-même se fit seulement lorsque Cyrénius eut le gouvernement de la Syrie.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Et tous allaient pour être enregistrés, chacun en sa propre ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Et Joseph aussi monta de Galilée, de la ville de Nazareth, en Judée, dans la ville de David qui est appelée Bethléhem, parce qu’il était de la maison et de la famille de David,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'pour être enregistré avec Marie, la femme qui lui était fiancée, laquelle était enceinte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Et il arriva, pendant qu’ils étaient là, que les jours où elle devait accoucher s’accomplirent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'et elle mit au monde son fils premier-né, et l’emmaillota, et le coucha dans la crèche, parce qu’il n’y avait pas de place pour eux dans l’hôtellerie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Et il y avait dans la même contrée des bergers demeurant aux champs, et gardant leur troupeau durant les veilles de la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Et voici, un ange du ✶Seigneur se trouva avec eux, et la gloire du ✶Seigneur resplendit autour d’eux; et ils furent saisis d’une fort grande peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Et l’ange leur dit: N’ayez point de peur, car voici, je vous annonce un grand sujet de joie qui sera pour tout le peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'car aujourd’hui, dans la cité de David, vous est né un sauveur, qui est le Christ, le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Et ceci en est le signe pour vous, c’est que vous trouverez un petit enfant emmailloté et couché dans une crèche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Et soudain il y eut avec l’ange une multitude de l’armée céleste, louant Dieu, et disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Gloire à Dieu dans les lieux très hauts; et sur la terre, paix; et bon plaisir dans les hommes!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Et il arriva, lorsque les anges s’en furent allés d’avec eux au ciel, que les bergers dirent entre eux: Allons donc jusqu’à Bethléhem, et voyons cette chose qui est arrivée que le ✶Seigneur nous a fait connaître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Et ils allèrent en hâte, et ils trouvèrent Marie et Joseph, et le petit enfant couché dans la crèche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Et l’ayant vu, ils divulguèrent la parole qui leur avait été dite touchant ce petit enfant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Et tous ceux qui l’entendirent s’étonnèrent des choses qui leur étaient dites par les bergers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Et Marie gardait toutes ces choses par-devers elle, les repassant dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Et les bergers s’en retournèrent, glorifiant et louant Dieu de toutes les choses qu’ils avaient entendues et vues, selon qu’il leur en avait été parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Et quand huit jours furent accomplis pour le circoncire, son nom fut appelé Jésus, nom duquel il avait été appelé par l’ange avant qu’il soit conçu dans le ventre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Et quand les jours de leur purification, selon la loi de Moïse, furent accomplis, ils le portèrent à Jérusalem, pour le présenter au ✶Seigneur');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(selon qu’il est écrit dans la loi du ✶Seigneur, que tout mâle qui ouvre la matrice sera appelé saint au ✶Seigneur),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'et pour offrir un sacrifice, selon ce qui est prescrit dans la loi du ✶Seigneur, une paire de tourterelles ou deux jeunes colombes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Et voici, il y avait à Jérusalem un homme dont le nom était Siméon; et cet homme était juste et pieux, et il attendait la consolation d’Israël; et l’Esprit Saint était sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Et il avait été averti divinement par l’Esprit Saint qu’il ne verrait pas la mort, que premièrement il n’ait vu le Christ du ✶Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Et il vint par l’Esprit dans le temple; et comme les parents apportaient le petit enfant Jésus pour faire à son égard selon l’usage de la loi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'il le prit entre ses bras et bénit Dieu et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Maintenant, Seigneur, tu laisses aller ton esclave en paix selon ta parole;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'car mes yeux ont vu ton salut,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'lequel tu as préparé devant la face de tous les peuples:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'une lumière pour la révélation des nations, et la gloire de ton peuple Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Et son père et sa mère s’étonnaient des choses qui étaient dites de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Et Siméon les bénit et dit à Marie sa mère: Voici, celui-ci est mis pour la chute et le relèvement de plusieurs en Israël, et pour un signe que l’on contredira');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(et même une épée transpercera ta propre âme), en sorte que les pensées de plusieurs cœurs soient révélées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Et il y avait Anne, une prophétesse, fille de Phanuel, de la tribu d’Aser (elle était fort avancée en âge, ayant vécu avec un mari sept ans depuis sa virginité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'et veuve d’environ 84 ans), qui ne quittait pas le temple, servant [Dieu] en jeûnes et en prières, nuit et jour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'celle-ci, survenant en ce même moment, louait le ✶Seigneur, et parlait de lui à tous ceux qui, à Jérusalem, attendaient la délivrance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Et quand ils eurent tout accompli selon la loi du ✶Seigneur, ils s’en retournèrent en Galilée, à Nazareth, leur ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Et l’enfant croissait et se fortifiait, étant rempli de sagesse; et la faveur de Dieu était sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Et ses parents allaient chaque année à Jérusalem, à la fête de Pâque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Et quand il eut douze ans, comme ils étaient montés à Jérusalem, selon la coutume de la fête,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'et qu’ils avaient accompli les jours [de la fête], comme ils s’en retournaient, l’enfant Jésus demeura dans Jérusalem; et ses parents ne le savaient pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Mais croyant qu’il était dans la troupe des voyageurs, ils marchèrent le chemin d’un jour et le cherchèrent parmi leurs parents et leurs connaissances;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'et ne le trouvant pas, ils s’en retournèrent à Jérusalem à sa recherche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Et il arriva qu’après trois jours ils le trouvèrent dans le temple, assis au milieu des docteurs, les écoutant et les interrogeant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Et tous ceux qui l’entendaient s’étonnaient de son intelligence et de ses réponses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Et quand ils le virent, ils furent frappés d’étonnement, et sa mère lui dit: Mon enfant, pourquoi nous as-tu fait ainsi? Voici, ton père et moi nous te cherchions, étant en grande peine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Et il leur dit: Pourquoi me cherchiez-vous? Ne saviez-vous pas qu’il me faut être aux affaires de mon Père?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Et ils ne comprirent pas la parole qu’il leur disait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Et il descendit avec eux, et vint à Nazareth, et leur était soumis. Et sa mère conservait toutes ces paroles dans son cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Et Jésus avançait en sagesse et en stature, et en faveur auprès de Dieu et des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Or, en la quinzième année du règne de Tibère César, Ponce Pilate étant gouverneur de la Judée, et Hérode tétrarque de la Galilée, et Philippe son frère tétrarque de l’Iturée et de la contrée de Trachonite, et Lysanias tétrarque de l’Abilène,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'sous la souveraine sacrificature d’Anne et de Caïphe, la parole de Dieu vint à Jean, le fils de Zacharie, au désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Et il alla dans tout le pays des environs du Jourdain, prêchant le baptême de repentance en rémission de péchés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'comme il est écrit au livre des paroles d’Ésaïe le prophète: « Voix de celui qui crie dans le désert: Préparez le chemin du ✶Seigneur, faites droits ses sentiers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Toute vallée sera comblée, et toute montagne et toute colline sera abaissée, et les choses tortues seront rendues droites, et les [sentiers] raboteux deviendront des sentiers unis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'et toute chair verra le salut de Dieu ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Il disait donc aux foules qui sortaient pour être baptisées par lui: Race de vipères, qui vous a avertis de fuir la colère qui vient?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Produisez donc des fruits qui conviennent à la repentance; et ne vous mettez pas à dire en vous-mêmes: Nous avons Abraham pour père; car je vous dis que Dieu peut, de ces pierres, susciter des enfants à Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Et déjà même la cognée est mise à la racine des arbres; tout arbre donc qui ne produit pas de bon fruit, est coupé et jeté au feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Et les foules l’interrogèrent, disant: Que faut-il donc que nous fassions?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Et répondant, il leur dit: Que celui qui a deux tuniques en donne à celui qui n’en a point, et que celui qui a des vivres fasse de même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Et des publicains vinrent aussi pour être baptisés; et ils lui dirent: Maître, que faut-il que nous fassions?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Et il leur dit: Ne percevez rien au-delà de ce qui vous est ordonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Et des gens de guerre l’interrogèrent aussi, disant: Et nous, que faut-il que nous fassions? Et il leur dit: Ne commettez pas d’extorsions, ni n’accusez faussement personne, et contentez-vous de vos gages.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, '– Et comme le peuple était dans l’attente, et que tous raisonnaient dans leurs cœurs à l’égard de Jean si lui ne serait point le Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Jean répondait à tous, disant: Moi, je vous baptise avec de l’eau; mais il vient, celui qui est plus puissant que moi, duquel je ne suis pas digne de délier la courroie des sandales: lui vous baptisera de l’Esprit Saint et de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Il a son van dans sa main, et il nettoiera entièrement son aire et assemblera le froment dans son grenier, mais il brûlera la balle au feu inextinguible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Et faisant aussi plusieurs autres exhortations, il évangélisait donc le peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'mais Hérode le tétrarque, étant repris par lui au sujet d’Hérodias, la femme de son frère, et à cause de toutes les choses méchantes qu’Hérode avait faites,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'ajouta encore à toutes les autres celle de mettre Jean en prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Et il arriva que, comme tout le peuple était baptisé, Jésus aussi étant baptisé et priant, le ciel s’ouvrit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'et l’Esprit Saint descendit sur lui sous une forme corporelle, comme une colombe; et il y eut une voix qui venait du ciel: Tu es mon Fils bien-aimé; en toi j’ai trouvé mon plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Et Jésus lui-même commençait d’avoir environ 30 ans, étant, comme on l’estimait, fils de Joseph: d’Héli,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'de Matthat, de Lévi, de Melchi, de Janna, de Joseph,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'de Mattathie, d’Amos, de Nahum, d’Esli, de Naggé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'de Maath, de Mattathie, de Séméi, de Joseph, de Juda,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'de Johanna, de Rhésa, de Zorobabel, de Salathiel, de Néri,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'de Melchi, d’Addi, de Cosam, d’Elmodam, d’Er,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'de José, d’Éliézer, de Jorim, de Matthat, de Lévi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'de Siméon, de Juda, de Joseph, de Jonan, d’Éliakim,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'de Méléa, de Maïnan, de Mattatha, de Nathan, de David,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'de Jessé, d’Obed, de Booz, de Salmon, de Naasson,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'd’Aminadab, d’Aram, d’Esrom, de Pharès, de Juda,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'de Jacob, d’Isaac, d’Abraham, de Thara, de Nachor,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'de Seruch, de Ragaü, de Phalek, d’Éber, de Sala,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'de Caïnan, d’Arphaxad, de Sem, de Noé, de Lamech,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'de Mathusala, d’Énoch, de Jared, de Maléléel, de Caïnan,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'd’Énos, de Seth, d’Adam, de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Or Jésus, plein de l’Esprit Saint, s’en retourna du Jourdain et fut mené par l’Esprit dans le désert,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'étant tenté par le diable 40 jours. Et il ne mangea rien pendant ces jours-là; et lorsqu’ils furent accomplis, il eut faim.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Et le diable lui dit: Si tu es Fils de Dieu, dis à cette pierre qu’elle devienne du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Et Jésus lui répondit, disant: Il est écrit que « l’homme ne vivra pas de pain seulement, mais de toute parole de Dieu ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Et le diable, le menant sur une haute montagne, lui montra, en un instant, tous les royaumes de la terre habitée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'Et le diable lui dit: Je te donnerai toute cette autorité et la gloire de ces royaumes; car elle m’a été donnée, et je la donne à qui je veux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Si donc tu te prosternes devant moi, elle sera toute à toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Et Jésus, lui répondant, dit: Il est écrit: « Tu rendras hommage au ✶Seigneur ton Dieu, et tu le serviras lui seul ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Et il l’amena à Jérusalem, et le plaça sur le faîte du temple et lui dit: Si tu es Fils de Dieu, jette-toi d’ici en bas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'car il est écrit: « Il donnera des ordres à ses anges à ton sujet, pour te garder;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'et ils te porteront sur leurs mains, de peur que tu ne heurtes ton pied contre une pierre ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Et Jésus, répondant, lui dit: Il est dit: « Tu ne tenteras pas le ✶Seigneur ton Dieu ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Et ayant accompli toute tentation, le diable se retira d’avec lui pour un temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Et Jésus s’en retourna en Galilée, dans la puissance de l’Esprit; et sa renommée se répandit par tout le pays d’alentour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Et lui-même enseignait dans leurs synagogues, étant glorifié par tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Et il vint à Nazareth où il avait été élevé; et il entra dans la synagogue au jour du sabbat, selon sa coutume, et se leva pour lire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Et on lui donna le livre du prophète Ésaïe; et ayant déployé le livre, il trouva le passage où il était écrit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '« L’Esprit du ✶Seigneur est sur moi, parce qu’il m’a oint pour annoncer de bonnes nouvelles aux pauvres; il m’a envoyé pour publier aux captifs la délivrance, et aux aveugles le recouvrement de la vue; pour renvoyer libres ceux qui sont foulés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'et pour publier l’an agréable du ✶Seigneur ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Et ayant ployé le livre, et l’ayant rendu à celui qui était de service, il s’assit; et les yeux de tous ceux qui étaient dans la synagogue étaient arrêtés sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Et il se mit à leur dire: Aujourd’hui cette écriture est accomplie, vous l’entendant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Et tous lui rendaient témoignage, et s’étonnaient des paroles de grâce qui sortaient de sa bouche, et ils disaient: Celui-ci n’est-il pas le fils de Joseph?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Et il leur dit: Assurément vous me direz cette parabole: Médecin, guéris-toi toi-même; fais ici aussi dans ton pays toutes les choses que nous avons entendu dire qui ont été faites à Capernaüm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Et il dit: En vérité, je vous dis qu’aucun prophète n’est reçu dans son pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Et, en vérité, je vous dis qu’il y avait plusieurs veuves en Israël, aux jours d’Élie, lorsque le ciel fut fermé trois ans et six mois, de sorte qu’il y eut une grande famine par tout le pays;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'et Élie ne fut envoyé vers aucune d’elles, sinon à Sarepta de la Sidonie vers une femme veuve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Et il y avait plusieurs lépreux en Israël au temps d’Élisée le prophète; et aucun d’eux ne fut rendu net, sinon Naaman, le Syrien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Et ils furent tous remplis de colère dans la synagogue en entendant ces choses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'et s’étant levés, ils le chassèrent hors de la ville, et le menèrent jusqu’au bord escarpé de la montagne sur laquelle leur ville était bâtie, de manière à l’en précipiter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Mais lui, passant au milieu d’eux, s’en alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Et il descendit à Capernaüm, ville de Galilée, et il les enseignait au jour de sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Et ils s’étonnaient de sa doctrine, parce que sa parole était avec autorité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Et il y avait dans la synagogue un homme qui avait un esprit de démon immonde; et il s’écria à haute voix,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'disant: Ha! qu’y a-t-il entre nous et toi, Jésus Nazarénien? Es-tu venu pour nous détruire? Je te connais, qui tu es: le Saint de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Et Jésus le tança, disant: Tais-toi, et sors de lui. Et le démon, l’ayant jeté au milieu [de tous], sortit de lui sans lui avoir fait aucun mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Et ils furent tous saisis d’étonnement, et ils parlaient entre eux, disant: Quelle parole est celle-ci? car il commande avec autorité et puissance aux esprits immondes, et ils sortent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Et sa renommée se répandait dans tous les lieux d’alentour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Et s’étant levé, [il sortit] de la synagogue et entra dans la maison de Simon. Et la belle-mère de Simon était prise d’une grosse fièvre, et on le pria pour elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Et s’étant penché sur elle, il tança la fièvre, et [la fièvre] la quitta; et à l’instant s’étant levée, elle les servit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Et comme le soleil se couchait, tous ceux qui avaient des infirmes atteints de diverses maladies, les lui amenèrent; et ayant imposé les mains à chacun d’eux, il les guérit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Et les démons aussi sortaient de plusieurs, criant et disant: Tu es le Fils de Dieu. Et, les tançant, il ne leur permettait pas de parler, parce qu’ils savaient qu’il était le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Et quand il fut jour, il sortit et s’en alla en un lieu désert; et les foules le recherchaient et vinrent jusqu’à lui; et elles le retenaient, afin qu’il ne s’en aille point d’auprès d’elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Mais il leur dit: Il faut que j’annonce le royaume de Dieu aux autres villes aussi; car j’ai été envoyé pour cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Et il prêchait dans les synagogues de la Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Or il arriva, comme la foule se jetait sur lui pour entendre la parole de Dieu, qu’il se tenait sur le bord du lac de Génésareth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Et il vit deux bateaux qui étaient au bord du lac. Or les pêcheurs en étaient descendus et lavaient leurs filets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Et montant dans l’un des bateaux qui était à Simon, il le pria de s’éloigner un peu de terre; et, s’étant assis, il enseignait les foules de dessus le bateau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Et quand il eut cessé de parler, il dit à Simon: Mène en pleine eau, et lâchez vos filets pour la pêche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Et Simon, répondant, lui dit: Maître, nous avons travaillé toute la nuit, et nous n’avons rien pris; mais sur ta parole je lâcherai le filet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Et ayant fait cela, ils enfermèrent une grande quantité de poissons, et leur filet se rompait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Et ils firent signe à leurs compagnons qui étaient dans l’autre bateau de venir les aider; et ils vinrent et remplirent les deux bateaux, de sorte qu’ils enfonçaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Et Simon Pierre, ayant vu cela, se jeta aux genoux de Jésus, disant: Seigneur, retire-toi de moi, car je suis un homme pécheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Car la frayeur l’avait saisi, lui et tous ceux qui étaient avec lui, à cause de la prise de poissons qu’ils venaient de faire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'de même que Jacques et Jean aussi, fils de Zébédée, qui étaient associés de Simon. Et Jésus dit à Simon: Ne crains pas; dorénavant tu prendras des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Et ayant mené les bateaux à terre, ils quittèrent tout et le suivirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Et il arriva, comme il était dans une des villes, que voici un homme plein de lèpre; et voyant Jésus, il se jeta sur sa face et le supplia, disant: Seigneur, si tu veux, tu peux me rendre net.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Et étendant la main, il le toucha, disant: Je veux, sois net. Et aussitôt la lèpre se retira de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Et il lui commanda de ne le dire à personne: mais va et montre-toi au sacrificateur, et offre pour ta purification selon ce que Moïse a ordonné, pour que cela leur serve de témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Et sa renommée se répandait de plus en plus; et de grandes foules s’assemblèrent pour l’entendre et pour être guéries de leurs infirmités;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'mais lui, se tenait retiré dans les déserts et priait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Et il arriva, l’un de ces jours, qu’il enseignait. Et des pharisiens et des docteurs de la loi, qui étaient venus de chaque bourgade de Galilée, et de Judée, et de Jérusalem, étaient assis [là], et la puissance du ✶Seigneur était [là] pour les guérir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Et voici des hommes portant sur un lit un homme qui était paralysé; et ils cherchaient à l’introduire et à le mettre devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Et ne trouvant pas par quel moyen ils pourraient l’introduire, à cause de la foule, ils montèrent sur le toit et le descendirent par les tuiles, avec son petit lit, au milieu, devant Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Et voyant leur foi, il dit: Homme, tes péchés te sont pardonnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Et les scribes et les pharisiens se mirent à raisonner, disant: Qui est celui-ci qui profère des blasphèmes? Qui peut pardonner les péchés, si ce n’est Dieu seul?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Et Jésus, connaissant leurs pensées, répondant, leur dit: Pourquoi raisonnez-vous dans vos cœurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Lequel est le plus facile, de dire: Tes péchés te sont pardonnés, ou de dire: Lève-toi et marche?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Or, afin que vous sachiez que le fils de l’homme a le pouvoir sur la terre de pardonner les péchés (il dit au paralytique): Je te dis, lève-toi, et, prenant ton petit lit, va dans ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Et à l’instant, s’étant levé devant eux, il prit [le lit] sur lequel il était couché, et s’en alla dans sa maison, glorifiant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Et ils furent tous saisis d’étonnement, et glorifiaient Dieu; et ils furent remplis de crainte, disant: Nous avons vu aujourd’hui des choses étranges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Et après cela il sortit; et il vit un publicain nommé Lévi, assis au bureau de recette, et il lui dit: Suis-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Et quittant tout, il se leva et le suivit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Et Lévi lui fit un grand festin dans sa maison; et il y avait une grande foule de publicains et d’autres gens qui étaient avec eux à table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Et leurs scribes et les pharisiens murmuraient contre ses disciples, disant: Pourquoi mangez-vous et buvez-vous avec les publicains et les pécheurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Et Jésus, répondant, leur dit: Ceux qui sont en santé n’ont pas besoin de médecin, mais ceux qui se portent mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Je ne suis pas venu appeler des justes, mais des pécheurs à la repentance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Et ils lui dirent: Pourquoi les disciples de Jean jeûnent-ils souvent et font-ils des prières, pareillement aussi ceux des pharisiens, mais les tiens mangent et boivent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Et il leur dit: Pouvez-vous faire jeûner les fils de la chambre nuptiale pendant que l’époux est avec eux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Mais des jours viendront, où aussi l’époux leur aura été ôté; alors ils jeûneront en ces jours-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Et il leur dit aussi une parabole: Personne ne met un morceau d’un habit neuf à un vieil habit; autrement il déchirera le neuf, et aussi la pièce [prise] du neuf ne s’accordera pas avec le vieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Et personne ne met du vin nouveau dans de vieilles outres; autrement le vin nouveau rompra les outres, et il se répandra, et les outres seront perdues;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'mais le vin nouveau doit être mis dans des outres neuves, et tous les deux se conservent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Et il n’y a personne qui ait bu du vieux, qui veuille aussitôt du nouveau; car il dit: Le vieux est meilleur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Or il arriva, au sabbat second-premier, qu’il passait par des blés; et ses disciples arrachaient des épis et les mangeaient, les froissant entre leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Et quelques-uns des pharisiens leur dirent: Pourquoi faites-vous ce qu’il n’est pas permis de faire au jour de sabbat?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Et Jésus, répondant, leur dit: N’avez-vous pas même lu ce que fit David quand il eut faim, lui et ceux qui étaient avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'comment il entra dans la maison de Dieu, et prit les pains de proposition, et en mangea, et en donna aussi à ceux qui étaient avec lui, quoiqu’il ne soit pas permis d’en manger, sinon aux sacrificateurs seuls?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Et il leur dit: Le fils de l’homme est seigneur aussi du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Et il arriva aussi, un autre sabbat, qu’il entra dans la synagogue et qu’il enseignait. Et il y avait là un homme, et sa main droite était sèche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Et les scribes et les pharisiens observaient s’il guérirait en un jour de sabbat, afin de trouver de quoi l’accuser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Et lui connut leurs pensées et dit à l’homme qui avait la main sèche: Lève-toi, et tiens-toi là devant tous. Et s’étant levé, il se tint là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Jésus donc leur dit: Je vous demanderai s’il est permis, le jour de sabbat, de faire du bien ou de faire du mal, de sauver la vie ou de la perdre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Et les ayant tous regardés à l’entour, il lui dit: Étends ta main. Et il fit ainsi; et sa main fut rendue [saine] comme l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Et ils en furent hors d’eux-mêmes, et s’entretenaient ensemble de ce qu’ils pourraient faire à Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Or il arriva, en ces jours-là, qu’il s’en alla sur une montagne pour prier. Et il passa toute la nuit à prier Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Et quand le jour fut venu, il appela ses disciples. Et en ayant choisi douze d’entre eux, lesquels il nomma aussi apôtres:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simon, qu’il nomma aussi Pierre, et André son frère; Jacques et Jean; Philippe et Barthélemy;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matthieu et Thomas; Jacques le [fils] d’Alphée, et Simon qui était appelé Zélote;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Jude [frère] de Jacques, et Judas Iscariote, qui aussi devint traître;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, '– et étant descendu avec eux, il s’arrêta dans un lieu uni, ainsi que la foule de ses disciples et une grande multitude de peuple de toute la Judée et de Jérusalem, et de la contrée maritime de Tyr et de Sidon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'qui étaient venus pour l’entendre et pour être guéris de leurs maladies; ceux aussi qui étaient tourmentés par des esprits immondes furent guéris;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'et toute la foule cherchait à le toucher, car il sortait de lui de la puissance, et elle les guérissait tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Et lui, élevant les yeux vers ses disciples, dit: Bienheureux, vous pauvres, car à vous est le royaume de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'bienheureux, vous qui maintenant avez faim, car vous serez rassasiés; bienheureux, vous qui pleurez maintenant, car vous rirez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Vous êtes bienheureux quand les hommes vous haïront, et quand ils vous retrancheront [de leur société], et qu’ils vous insulteront et rejetteront votre nom comme mauvais, à cause du fils de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Réjouissez-vous en ce jour-là et tressaillez de joie, car voici, votre récompense est grande dans le ciel, car leurs pères en ont fait de même aux prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Mais malheur à vous, riches, car vous avez votre consolation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'malheur à vous qui êtes rassasiés, car vous aurez faim; malheur à vous qui riez maintenant, car vous mènerez deuil et vous pleurerez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Malheur [à vous] quand tous les hommes diront du bien de vous, car leurs pères en ont fait de même aux faux prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Mais à vous qui écoutez, je vous dis: Aimez vos ennemis; faites du bien à ceux qui vous haïssent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'bénissez ceux qui vous maudissent; priez pour ceux qui vous font du tort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'À celui qui te frappe sur une joue, présente aussi l’autre; et si quelqu’un t’ôte ton manteau, ne l’empêche pas [de prendre] aussi ta tunique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Donne à tout homme qui te demande, et à celui qui t’ôte ce qui t’appartient, ne le redemande pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Et comme vous voulez que les hommes vous fassent, vous aussi faites-leur de même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Et si vous aimez ceux qui vous aiment, quel gré vous en saura-t-on? car les pécheurs aussi aiment ceux qui les aiment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Et si vous faites du bien à ceux qui vous font du bien, quel gré vous en saura-t-on? car les pécheurs aussi en font autant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Et si vous prêtez à ceux de qui vous espérez recevoir, quel gré vous en saura-t-on? car les pécheurs aussi prêtent aux pécheurs, afin qu’ils reçoivent la pareille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Mais aimez vos ennemis, et faites du bien, et prêtez sans en rien espérer; et votre récompense sera grande, et vous serez les fils du Très-haut; car il est bon envers les ingrats et les méchants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Soyez donc miséricordieux, comme aussi votre Père est miséricordieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'et ne jugez pas, et vous ne serez point jugés; ne condamnez pas, et vous ne serez point condamnés; acquittez, et vous serez acquittés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'donnez, et il vous sera donné: on vous donnera dans le sein bonne mesure, pressée et secouée, et qui débordera; car de la même mesure dont vous mesurerez, il vous sera mesuré en retour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Et il leur disait aussi une parabole: Un aveugle peut-il conduire un aveugle? ne tomberont-ils pas tous deux dans la fosse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Le disciple n’est pas au-dessus de son maître, mais tout homme accompli sera comme son maître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Et pourquoi regardes-tu le fétu qui est dans l’œil de ton frère, et tu ne t’aperçois pas de la poutre qui est dans ton propre œil?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Ou comment peux-tu dire à ton frère: Frère, permets, j’ôterai le fétu qui est dans ton œil, toi qui ne vois pas la poutre qui est dans ton œil? Hypocrite, ôte premièrement la poutre de ton œil, et alors tu verras clair pour ôter le fétu qui est dans l’œil de ton frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Car il n’y a pas de bon arbre qui produise de mauvais fruit, ni d’arbre mauvais qui produise de bon fruit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'car chaque arbre se connaît à son propre fruit, car on ne récolte pas des figues sur des épines, ni ne cueille du raisin sur un buisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'L’homme bon, du bon trésor de son cœur produit ce qui est bon, et l’homme mauvais, du mauvais produit ce qui est mauvais: car de l’abondance du cœur sa bouche parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Et pourquoi m’appelez-vous: Seigneur, Seigneur, et ne faites-vous pas ce que je dis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Je vous montrerai à qui est semblable tout homme qui vient à moi, et qui entend mes paroles et les met en pratique:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'il est semblable à un homme qui bâtit une maison, qui a foui et creusé profondément, et a mis un fondement sur le roc: mais une inondation étant survenue, le fleuve s’est jeté avec violence contre cette maison, et il n’a pu l’ébranler, car elle avait été fondée sur le roc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Mais celui qui a entendu et n’a pas mis en pratique, est semblable à un homme qui a bâti une maison sur la terre, sans fondement; et le fleuve s’est jeté avec violence contre elle, et aussitôt elle est tombée; et la ruine de cette maison a été grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Or, quand il eut achevé tous ses discours, le peuple l’entendant, il entra dans Capernaüm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Et l’esclave d’un certain centurion, à qui il était fort cher, était malade et s’en allait mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Et ayant entendu parler de Jésus, il envoya vers lui des anciens des Juifs, le priant de venir sauver son esclave.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Et étant venus à Jésus, ils le priaient instamment, disant: Il est digne que tu lui accordes cela,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'car il aime notre nation et nous a lui-même bâti la synagogue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Et Jésus alla avec eux. Et déjà comme il n’était plus guère loin de la maison, le centurion envoya des amis vers lui, lui disant: Seigneur, ne te donne pas de fatigue, car je ne suis pas digne que tu entres sous mon toit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'c’est pourquoi je ne me suis pas cru digne moi-même non plus d’aller vers toi; mais dis une parole et mon serviteur sera guéri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Car moi aussi, je suis un homme placé sous l’autorité [d’autrui], ayant sous moi des soldats; et je dis à l’un: Va, et il va; et à un autre: Viens, et il vient; et à mon esclave: Fais cela, et il le fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Et Jésus, ayant entendu ces choses, l’admira; et se tournant vers la foule qui le suivait, il dit: Je vous dis que je n’ai pas trouvé, même en Israël, une si grande foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Et ceux qui avaient été envoyés, s’en étant retournés à la maison, trouvèrent bien portant l’esclave malade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Et le jour suivant, il arriva que [Jésus] allait à une ville appelée Naïn, et plusieurs de ses disciples et une grande foule allaient avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Et comme il approchait de la porte de la ville, voici, on portait dehors un mort, fils unique de sa mère, et elle était veuve; et une foule considérable de la ville était avec elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Et le Seigneur, la voyant, fut ému de compassion envers elle et lui dit: Ne pleure pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Et s’approchant, il toucha la bière; et ceux qui la portaient s’arrêtèrent; et il dit: Jeune homme, je te dis, lève-toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Et le mort se leva sur son séant, et commença à parler; et il le donna à sa mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Et ils furent tous saisis de crainte, et ils glorifiaient Dieu, disant: Un grand prophète a été suscité parmi nous, et Dieu a visité son peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Et le bruit de ce fait se répandit à son sujet dans toute la Judée et dans tout le pays d’alentour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Et les disciples de Jean lui rapportèrent toutes ces choses. Et ayant appelé deux de ses disciples, Jean');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'les envoya vers Jésus, disant: Es-tu celui qui vient, ou devons-nous en attendre un autre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Et les hommes, étant venus à lui, dirent: Jean le baptiseur nous a envoyés auprès de toi, disant: Es-tu celui qui vient, ou devons-nous en attendre un autre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, '(En cette heure-là, il guérit plusieurs personnes de maladies et de fléaux et de mauvais esprits, et il donna la vue à plusieurs aveugles.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Et Jésus, répondant, leur dit: Allez, et rapportez à Jean les choses que vous avez vues et entendues: que les aveugles recouvrent la vue, que les boiteux marchent, que les lépreux sont rendus nets, que les sourds entendent, que les morts ressuscitent, et que l’évangile est annoncé aux pauvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'Et bienheureux est quiconque n’aura pas été scandalisé en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Et lorsque les messagers de Jean s’en furent allés, il se mit à dire de Jean aux foules: Qu’êtes-vous allés voir au désert? Un roseau agité par le vent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Mais qu’êtes-vous allés voir? Un homme vêtu de vêtements précieux? Voici, ceux qui sont vêtus magnifiquement et qui vivent dans les délices, sont dans les palais des rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Mais qu’êtes-vous allés voir? Un prophète? Oui, vous dis-je, et plus qu’un prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'C’est ici celui dont il est écrit: « Voici, j’envoie mon messager devant ta face, lequel préparera ton chemin devant toi »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'car je vous dis: Parmi ceux qui sont nés de femme, il n’y a aucun prophète plus grand que Jean le baptiseur; mais le moindre dans le royaume de Dieu est plus grand que lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, '(Et tout le peuple qui entendait cela, et les publicains, justifiaient Dieu, ayant été baptisés du baptême de Jean;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'mais les pharisiens et les docteurs de la loi rejetaient contre eux-mêmes le conseil de Dieu, n’ayant pas été baptisés par lui.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'À qui donc comparerai-je les hommes de cette génération, et à qui ressemblent-ils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Ils sont semblables à des petits enfants qui sont assis au marché et qui crient les uns aux autres et disent: Nous vous avons joué de la flûte et vous n’avez pas dansé; nous vous avons chanté des complaintes et vous n’avez pas pleuré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Car Jean le baptiseur est venu, ne mangeant pas de pain et ne buvant pas de vin, et vous dites: Il a un démon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Le fils de l’homme est venu, mangeant et buvant, et vous dites: Voici un mangeur et un buveur, un ami des publicains et des pécheurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Et la sagesse a été justifiée par tous ses enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Et un des pharisiens le pria de manger avec lui. Et entrant dans la maison du pharisien, il se mit à table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Et voici, une femme dans la ville, qui était une pécheresse, et qui savait qu’il était à table dans la maison du pharisien, apporta un vase d’albâtre [plein] de parfum;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'et se tenant derrière à ses pieds, et pleurant, elle se mit à les arroser de ses larmes, et elle les essuyait avec les cheveux de sa tête, et couvrait ses pieds de baisers, et les oignait avec le parfum.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Et le pharisien qui l’avait convié, voyant cela, dit en lui-même: Celui-ci, s’il était prophète, saurait qui et quelle est cette femme qui le touche, car c’est une pécheresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Et Jésus, répondant, lui dit: Simon, j’ai quelque chose à te dire. Et il dit: Maître, dis-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Un créancier avait deux débiteurs: l’un lui devait 500 deniers, et l’autre 50;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'et comme ils n’avaient pas de quoi payer, il quitta la dette à l’un et à l’autre. Dis donc lequel des deux l’aimera le plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Et Simon, répondant, dit: J’estime que c’est celui à qui il a été quitté davantage. Et il lui dit: Tu as jugé justement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Et se tournant vers la femme, il dit à Simon: Vois-tu cette femme? Je suis entré dans ta maison; tu ne m’as pas donné d’eau pour mes pieds, mais elle a arrosé mes pieds de ses larmes et les a essuyés avec ses cheveux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Tu ne m’as pas donné de baiser; mais elle, depuis que je suis entré, n’a pas cessé de couvrir mes pieds de baisers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Tu n’as pas oint ma tête d’huile, mais elle a oint mes pieds avec un parfum.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'C’est pourquoi je te dis: Ses nombreux péchés sont pardonnés, car elle a beaucoup aimé; mais celui à qui il est peu pardonné, aime peu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Et il dit à la femme: Tes péchés sont pardonnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Et ceux qui étaient à table avec lui, se mirent à dire en eux-mêmes: Qui est celui-ci qui même pardonne les péchés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Et il dit à la femme: Ta foi t’a sauvée, va-t’en en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Et il arriva après cela, qu’il passait par les villes et par les villages, prêchant et annonçant le royaume de Dieu; et les douze [étaient] avec lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'et des femmes aussi qui avaient été guéries d’esprits malins et d’infirmités, Marie, qu’on appelait Magdeleine, de laquelle étaient sortis sept démons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'et Jeanne, femme de Chuzas intendant d’Hérode, et Susanne, et plusieurs autres, qui l’assistaient de leurs biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Et comme une grande foule s’assemblait, et qu’on venait à lui de toutes les villes, il dit en parabole:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Le semeur sortit pour semer sa semence. Et comme il semait, quelques [grains] tombèrent le long du chemin, et furent foulés aux pieds, et les oiseaux du ciel les dévorèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Et d’autres tombèrent sur le roc; et ayant levé, ils séchèrent, parce qu’ils n’avaient pas d’humidité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Et d’autres tombèrent au milieu des épines; et les épines levèrent avec eux et les étouffèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Et d’autres tombèrent dans la bonne terre, et ils levèrent, et produisirent du fruit au centuple. En disant ces choses, il criait: Qui a des oreilles pour entendre, qu’il entende.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Et ses disciples l’interrogèrent, disant: Qu’est-ce que cette parabole?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Et il dit: À vous il est donné de connaître les mystères du royaume de Dieu; mais [il en est parlé] aux autres en paraboles, afin que voyant, ils ne voient pas, et qu’entendant, ils ne comprennent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Or voici ce qu’est la parabole: La semence est la parole de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'et ceux qui sont le long du chemin, sont ceux qui entendent [la parole]; ensuite vient le diable, et il ôte de leur cœur la parole, de peur qu’en croyant, ils ne soient sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Et ceux qui sont sur le roc, sont ceux qui, lorsqu’ils entendent la parole, la reçoivent avec joie; et ceux-ci n’ont pas de racine: ils ne croient que pour un temps, et au temps de la tentation ils se retirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Et ce qui est tombé dans les épines, ce sont ceux qui, ayant entendu [la parole] et s’en étant allés, sont étouffés par les soucis et par les richesses et par les voluptés de la vie, et ils ne portent pas de fruit à maturité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Mais ce qui est dans la bonne terre, ce sont ceux qui, ayant entendu la parole, la retiennent dans un cœur honnête et bon, et portent du fruit avec patience.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Or personne, après avoir allumé une lampe, ne la couvre d’un vase, ni ne la met sous un lit; mais il la place sur un pied de lampe, afin que ceux qui entrent voient la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Car il n’y a rien de secret qui ne deviendra manifeste, ni rien de caché qui ne se connaîtra et ne vienne en évidence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Prenez donc garde comment vous entendez; car à quiconque a, il sera donné, et à quiconque n’a pas, cela même qu’il paraît avoir sera ôté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Or sa mère et ses frères vinrent auprès de lui; et ils ne pouvaient l’aborder, à cause de la foule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Et cela lui fut rapporté par [quelques-uns] qui disaient: Ta mère et tes frères se tiennent dehors, désirant te voir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Mais lui, répondant, leur dit: Ma mère et mes frères sont ceux qui écoutent la parole de Dieu et qui la mettent en pratique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Et il arriva, l’un de ces jours, qu’il monta dans un bateau, et ses disciples [avec lui]. Et il leur dit: Passons à l’autre rive du lac. Et ils prirent le large.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Et comme ils voguaient, il s’endormit; et un vent impétueux fondit sur le lac, et [le bateau] s’emplissait, et ils étaient en péril.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Et ils vinrent et le réveillèrent, disant: Maître, maître, nous périssons! Et lui, s’étant levé, reprit le vent et les flots; et ils s’apaisèrent, et il se fit un calme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Et il leur dit: Où est votre foi? Mais eux, saisis de crainte, étaient dans l’étonnement, disant entre eux: Qui donc est celui-ci, qui commande même aux vents et à l’eau, et ils lui obéissent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Et ils abordèrent dans le pays des Gadaréniens, qui est vis-à-vis de la Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Et quand il fut descendu à terre, un homme de la ville vint à sa rencontre, qui depuis longtemps avait des démons, et ne portait pas de vêtements, et ne demeurait pas dans une maison, mais dans les sépulcres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Et ayant aperçu Jésus, et s’étant écrié, il se jeta devant lui, et dit à haute voix: Qu’y a-t-il entre moi et toi, Jésus, Fils du Dieu Très-haut? Je te supplie, ne me tourmente pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Car [Jésus] avait commandé à l’esprit immonde de sortir de l’homme; car depuis longtemps il s’était saisi de lui, et [l’homme] avait été lié et gardé dans les chaînes et avec les fers aux pieds; et brisant ses liens, il était emporté par le démon dans les déserts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Et Jésus lui demanda, disant: Quel est ton nom? Et il dit: Légion; car beaucoup de démons étaient entrés en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Et ils le priaient pour qu’il ne leur commande pas de s’en aller dans l’abîme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Et il y avait là un grand troupeau de pourceaux paissant sur la montagne, et ils le priaient de leur permettre d’entrer en eux; et il le leur permit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Et les démons, sortant de l’homme, entrèrent dans les pourceaux, et le troupeau se rua du haut de la côte dans le lac, et fut étouffé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Et ceux qui le paissaient, voyant ce qui était arrivé, s’enfuirent, et le racontèrent dans la ville et dans les campagnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Et ils sortirent pour voir ce qui était arrivé, et vinrent vers Jésus, et trouvèrent assis, vêtu et dans son bon sens, aux pieds de Jésus, l’homme duquel les démons étaient sortis; et ils eurent peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Et ceux qui avaient vu [ce qui s’était passé], leur racontèrent aussi comment le démoniaque avait été délivré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Et toute la multitude du pays environnant des Gadaréniens, pria Jésus de s’en aller de chez eux, car ils étaient saisis d’une grande frayeur: et lui, étant monté dans le bateau, s’en retourna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Et l’homme duquel les démons étaient sortis, le supplia [de lui permettre] d’être avec lui; mais il le renvoya, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Retourne dans ta maison et raconte tout ce que Dieu t’a fait. Et il s’en alla, publiant par toute la ville tout ce que Jésus lui avait fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Et quand Jésus fut de retour, il arriva que la foule l’accueillit, car tous l’attendaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Et voici, un homme dont le nom était Jaïrus, – et il était chef de la synagogue, – vint, et se jetant aux pieds de Jésus, le supplia de venir dans sa maison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'car il avait une fille unique, d’environ douze ans, et elle se mourait. Et comme il s’en allait, les foules le serraient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, '– Et une femme qui avait une perte de sang depuis douze ans, et qui, ayant dépensé tout son bien en médecins, n’avait pu être guérie par aucun,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 's’approcha par-derrière et toucha le bord de son vêtement; et à l’instant sa perte de sang s’arrêta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Et Jésus dit: Qui est-ce qui m’a touché? Et comme tous niaient, Pierre dit, et ceux qui étaient avec lui: Maître, les foules te serrent et te pressent, et tu dis: Qui est-ce qui m’a touché?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Et Jésus dit: Quelqu’un m’a touché, car je sais qu’il est sorti de moi de la puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Et la femme, voyant qu’elle n’était pas cachée, vint en tremblant, et, se jetant devant lui, déclara devant tout le peuple pour quelle raison elle l’avait touché, et comment elle avait été guérie instantanément.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Et il lui dit: Aie bon courage, [ma] fille; ta foi t’a guérie; va-t’en en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, '– Comme il parlait encore, il vient quelqu’un de chez le chef de synagogue, lui disant: Ta fille est morte, ne tourmente pas le maître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Et Jésus, l’ayant entendu, lui répondit, disant: Ne crains pas, crois seulement, et elle sera sauvée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Et quand il fut arrivé à la maison, il ne permit à personne d’entrer, sinon à Pierre et à Jean et à Jacques, et au père de la jeune fille et à la mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Et tous pleuraient et se lamentaient sur elle; et il leur dit: Ne pleurez pas, car elle n’est pas morte, mais elle dort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Et ils se riaient de lui, sachant qu’elle était morte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Mais lui, les ayant tous mis dehors, et l’ayant prise par la main, cria, disant: Jeune fille, lève-toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Et son esprit retourna [en elle], et elle se leva immédiatement; et il commanda qu’on lui donne à manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Et ses parents étaient hors d’eux; et il leur enjoignit de ne dire à personne ce qui était arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Et ayant assemblé les douze, il leur donna puissance et autorité sur tous les démons, et [le pouvoir] de guérir les maladies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Et il les envoya prêcher le royaume de Dieu et guérir les infirmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'et il leur dit: Ne prenez rien pour le chemin, ni bâton, ni sac, ni pain, ni argent; et n’ayez pas chacun deux tuniques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Et dans quelque maison que vous entriez, là demeurez, et de là partez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Et tous ceux qui ne vous recevront pas,... en sortant de cette ville-là, secouez même la poussière de vos pieds, en témoignage contre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Et, partant, ils parcouraient tous les villages, évangélisant et guérissant partout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Et Hérode le tétrarque entendit parler de toutes les choses qui étaient faites par lui; et il était en perplexité, parce que quelques-uns disaient que Jean était ressuscité d’entre les morts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'et quelques-uns, qu’Élie était apparu; et d’autres, que l’un des anciens prophètes était ressuscité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Et Hérode dit: Moi, j’ai fait décapiter Jean; mais qui est celui-ci, de qui j’entends dire de telles choses? et il cherchait à le voir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Et les apôtres, étant de retour, lui racontèrent tout ce qu’ils avaient fait. Et les prenant avec lui, il se retira à l’écart dans un lieu désert d’une ville appelée Bethsaïda.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Et les foules, l’ayant su, le suivirent. Et les ayant reçus, il leur parla du royaume de Dieu, et guérit ceux qui avaient besoin de guérison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Et le jour commença à baisser; et les douze, s’approchant, lui dirent: Renvoie la foule, afin qu’ils aillent dans les villages et dans les campagnes d’alentour, et s’y logent et trouvent des vivres, car nous sommes ici dans un lieu désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Mais il leur dit: Vous, donnez-leur à manger. Et ils dirent: Nous n’avons pas plus de cinq pains et de deux poissons, à moins que nous n’allions et que nous n’achetions de quoi manger pour tout ce peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'car ils étaient environ 5 000 hommes. Et il dit à ses disciples: Faites-les asseoir par rangs de 50 chacun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Et ils firent ainsi, et les firent tous asseoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Et ayant pris les cinq pains et les deux poissons, et regardant vers le ciel, il les bénit, et les rompit; et il les donna à ses disciples pour les mettre devant la foule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Et ils mangèrent tous et furent rassasiés; et de ce qui leur était resté de morceaux, on ramassa douze paniers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Et il arriva, comme il priait à l’écart, que ses disciples étaient avec lui. Et il les interrogea, disant: Qui disent les foules que je suis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Et répondant, ils dirent: Jean le baptiseur; et d’autres: Élie; et d’autres, que l’un des anciens prophètes est ressuscité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Et il leur dit: Et vous, qui dites-vous que je suis? Et Pierre, répondant, dit: Le Christ de Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Et s’adressant à eux avec force, il leur commanda de ne dire ceci à personne,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'disant: Il faut que le fils de l’homme souffre beaucoup, et qu’il soit rejeté des anciens et des principaux sacrificateurs et des scribes, et qu’il soit mis à mort, et qu’il soit ressuscité le troisième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Et il disait à tous: Si quelqu’un veut venir après moi, qu’il se renonce soi-même, et qu’il prenne sa croix chaque jour, et me suive:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'car quiconque voudra sauver sa vie la perdra; et quiconque perdra sa vie pour l’amour de moi, celui-là la sauvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Car que profitera-t-il à un homme de gagner le monde entier, s’il se détruit lui-même ou se perd lui-même?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Car quiconque aura honte de moi et de mes paroles, le fils de l’homme aura honte de lui quand il viendra dans sa gloire et dans celle du Père et des saints anges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Et je vous dis, en vérité, que de ceux qui sont ici présents, il y en a quelques-uns qui ne goûteront point la mort jusqu’à ce qu’ils aient vu le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Et il arriva, environ huit jours après ces paroles, qu’il prit avec lui Pierre et Jean et Jacques, et qu’il monta sur une montagne pour prier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Et comme il priait, l’apparence de son visage devint tout autre, et son vêtement devint blanc [et] resplendissant comme un éclair;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'et voici, deux hommes, qui étaient Moïse et Élie, parlaient avec lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'lesquels, apparaissant en gloire, parlaient de sa mort qu’il allait accomplir à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Et Pierre et ceux qui étaient avec lui étaient accablés de sommeil; et quand ils furent réveillés, ils virent sa gloire et les deux hommes qui étaient avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Et il arriva, comme ils se séparaient de lui, que Pierre dit à Jésus: Maître, il est bon que nous soyons ici; et faisons trois tentes: une pour toi, et une pour Moïse, et une pour Élie, ne sachant ce qu’il disait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Et comme il disait ces choses, une nuée vint et les couvrit; et ils eurent peur comme ils entraient dans la nuée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Et il y eut une voix venant de la nuée, disant: Celui-ci est mon Fils bien-aimé, écoutez-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Et la voix s’étant fait entendre, Jésus se trouva seul. Et ils se turent, et ne rapportèrent en ces jours-là à personne rien de ce qu’ils avaient vu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Et il arriva, le jour suivant, quand ils furent descendus de la montagne, qu’une grande foule vint à sa rencontre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Et voici, un homme de la foule s’écria, disant: Maître, je te supplie, jette les yeux sur mon fils, car il est mon unique;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'et voici, un esprit le saisit; et soudain il crie; et il le déchire, en le faisant écumer; et c’est à peine s’il se retire de lui après l’avoir broyé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'et j’ai supplié tes disciples de le chasser, et ils n’ont pas pu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Et Jésus, répondant, dit: Ô génération incrédule et perverse, jusques à quand serai-je avec vous et vous supporterai-je? Amène ici ton fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Et encore, comme il approchait, le démon le renversa et le tourmenta violemment; mais Jésus tança l’esprit immonde, et guérit l’enfant, et le rendit à son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Et tous furent étonnés de la grandeur de Dieu. Et comme tous s’étonnaient de tout ce que Jésus faisait, il dit à ses disciples:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Vous, gardez bien ces paroles que vous avez entendues, car le fils de l’homme va être livré entre les mains des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Mais ils ne comprirent pas cette parole, et elle leur était cachée, en sorte qu’ils ne la saisissaient pas; et ils craignaient de l’interroger touchant cette parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Et il s’éleva au milieu d’eux une question, [à savoir] lequel d’entre eux serait le plus grand.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Mais Jésus, voyant la pensée de leur cœur, prit un petit enfant, et le plaça auprès de lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'et il leur dit: Quiconque recevra ce petit enfant en mon nom, me reçoit; et quiconque me reçoit, reçoit celui qui m’a envoyé. Car celui qui est le plus petit parmi vous tous, c’est celui-là qui est grand.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Et Jean, répondant, dit: Maître, nous avons vu quelqu’un qui chassait des démons en ton nom, et nous le lui avons défendu, parce qu’il ne [te] suit pas avec nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Et Jésus lui dit: Ne le lui défendez pas, car celui qui n’est pas contre vous est pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Or il arriva, comme les jours de son assomption s’accomplissaient, qu’il dressa sa face résolument pour aller à Jérusalem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'et il envoya devant sa face des messagers. Et s’en étant allés, ils entrèrent dans un village de Samaritains pour lui préparer [un logis];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'et ils ne le reçurent point, parce que sa face était tournée vers Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Et ses disciples, Jacques et Jean, voyant cela, dirent: Seigneur, veux-tu que nous disions que le feu descende du ciel et les consume, comme aussi fit Élie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Et, se tournant, il les censura fortement [et dit: Vous ne savez de quel esprit vous êtes animés]!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Et ils s’en allèrent à un autre village.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Et il arriva, comme ils allaient par le chemin, qu’un certain homme lui dit: Seigneur, je te suivrai où que tu ailles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Et Jésus lui dit: Les renards ont des tanières, et les oiseaux du ciel ont des demeures; mais le fils de l’homme n’a pas où reposer sa tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Et il dit à un autre: Suis-moi; – et il dit: Seigneur, permets-moi d’aller premièrement ensevelir mon père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Et Jésus lui dit: Laisse les morts ensevelir leurs morts; mais toi, va et annonce le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Et un autre aussi dit: Je te suivrai, Seigneur; mais permets-moi de prendre premièrement congé de ceux qui sont dans ma maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Et Jésus lui dit: Nul qui a mis la main à la charrue et qui regarde en arrière, n’est propre pour le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Or après ces choses, le Seigneur en désigna aussi 70 autres, et les envoya deux à deux devant sa face dans toutes les villes et dans tous les lieux où il devait lui-même aller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Il leur disait donc: La moisson est grande, mais il y a peu d’ouvriers: suppliez donc le Seigneur de la moisson, en sorte qu’il pousse des ouvriers dans sa moisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Allez; voici, moi je vous envoie comme des agneaux au milieu des loups.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ne portez ni bourse, ni sac, ni sandales; et ne saluez personne en chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Mais, dans quelque maison que vous entriez, dites premièrement: Paix sur cette maison!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Et si un fils de paix est là, votre paix reposera sur elle, sinon elle retournera sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Et demeurez dans la même maison, mangeant et buvant de ce qui [vous sera offert] de leur part; car l’ouvrier est digne de son salaire. Ne passez pas de maison en maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Et dans quelque ville que vous entriez et qu’on vous reçoive, mangez de ce qui sera mis devant vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'et guérissez les infirmes qui y seront, et dites-leur: Le royaume de Dieu s’est approché de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Mais dans quelque ville que vous soyez entrés et qu’on ne vous reçoive pas, sortez dans ses rues et dites:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'La poussière même de votre ville, qui s’est attachée à nos pieds, nous la secouons contre vous; mais sachez ceci, que le royaume de Dieu s’est approché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Je vous dis que le sort de Sodome sera plus supportable en ce jour-là que celui de cette ville-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Malheur à toi, Chorazin! malheur à toi, Bethsaïda! car si les miracles qui ont été faits au milieu de vous avaient été faits dans Tyr et dans Sidon, il y a longtemps qu’elles se seraient repenties, s’étant assises dans le sac et la cendre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'mais le sort de Tyr et de Sidon, au jugement, sera plus supportable que le vôtre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Et toi, Capernaüm, qui as été élevée jusqu’au ciel, tu seras abaissée jusque dans le hadès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Celui qui vous écoute, m’écoute; et celui qui vous rejette, me rejette; et celui qui me rejette, rejette celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Et les soixante-dix s’en revinrent avec joie, disant: Seigneur, les démons mêmes nous sont assujettis en ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Et il leur dit: Je voyais Satan tombant du ciel comme un éclair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Voici, je vous donne l’autorité de marcher sur les serpents et sur les scorpions, et sur toute la puissance de l’ennemi; et rien ne vous nuira;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'toutefois ne vous réjouissez pas de ce que les esprits vous sont assujettis, mais réjouissez-vous parce que vos noms sont écrits dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, '– En cette même heure, Jésus se réjouit en esprit et dit: Je te loue, ô Père, Seigneur du ciel et de la terre, parce que tu as caché ces choses aux sages et aux intelligents, et que tu les as révélées aux petits enfants. Oui, Père, car c’est ce que tu as trouvé bon devant toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Toutes choses m’ont été livrées par mon Père; et personne ne connaît qui est le Fils, si ce n’est le Père; ni qui est le Père, si ce n’est le Fils, et celui à qui le Fils voudra le révéler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Et se tournant vers les disciples, il leur dit en particulier: Bienheureux sont les yeux qui voient ce que vous voyez!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Car je vous dis que plusieurs prophètes et [plusieurs] rois ont désiré de voir les choses que vous voyez, et ils ne les ont pas vues, et d’entendre les choses que vous entendez, et ils ne les ont pas entendues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Et voici, un docteur de la loi se leva pour l’éprouver, et dit: Maître, que faut-il que j’aie fait pour hériter de la vie éternelle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Et il lui dit: Qu’est-il écrit dans la loi? Comment lis-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Et répondant, il dit: « Tu aimeras le ✶Seigneur ton Dieu de tout ton cœur, et de toute ton âme, et de toute ta force, et de toute ta pensée »; « et ton prochain comme toi-même ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Et il lui dit: Tu as bien répondu; fais cela, et tu vivras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Mais lui, voulant se justifier lui-même, dit à Jésus: Et qui est mon prochain?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Et Jésus, répondant, dit: Un homme descendit de Jérusalem à Jéricho, et tomba entre [les mains des] voleurs, qui aussi, l’ayant dépouillé et l’ayant couvert de blessures, s’en allèrent, le laissant à demi mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Or, par aventure, un sacrificateur descendait par ce chemin-là, et, le voyant, passa outre de l’autre côté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'et pareillement aussi un lévite, étant arrivé en cet endroit-là, s’en vint, et, le voyant, passa outre de l’autre côté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'mais un Samaritain, allant son chemin, vint à lui, et, le voyant, fut ému de compassion,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'et s’approcha et banda ses plaies, y versant de l’huile et du vin; et l’ayant mis sur sa propre bête, il le mena dans l’hôtellerie et eut soin de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Et le lendemain, s’en allant, il tira deux deniers et les donna à l’hôtelier, et lui dit: Prends soin de lui; et ce que tu dépenseras de plus, moi, à mon retour, je te le rendrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Lequel de ces trois te semble avoir été le prochain de celui qui était tombé entre les [mains des] voleurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Et il dit: C’est celui qui a usé de miséricorde envers lui. Et Jésus lui dit: Va, et toi fais de même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Et il arriva, comme ils étaient en chemin, qu’il entra dans un village. Et une femme nommée Marthe le reçut dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Et elle avait une sœur appelée Marie, qui aussi, s’étant assise aux pieds de Jésus, écoutait sa parole;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'mais Marthe était distraite par beaucoup de service. Et étant venue à Jésus, elle dit: Seigneur, ne te soucies-tu pas de ce que ma sœur me laisse toute seule à servir? Dis-lui donc qu’elle m’aide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Et Jésus, lui répondant, dit: Marthe, Marthe, tu es en souci et tu te tourmentes de beaucoup de choses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'mais il n’est besoin que d’une seule; et Marie a choisi la bonne part qui ne lui sera pas ôtée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Et comme il était en prière dans un certain lieu, il arriva, après qu’il eut cessé, que quelqu’un de ses disciples lui dit: Seigneur, enseigne-nous à prier, comme aussi Jean l’a enseigné à ses disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Et il leur dit: Quand vous priez, dites: Père, que ton nom soit sanctifié; que ton règne vienne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'donne-nous chaque jour le pain qu’il nous faut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'et remets-nous nos péchés, car nous-mêmes aussi nous remettons à tous ceux qui nous doivent; et ne nous induis pas en tentation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Et il leur dit: Qui sera celui d’entre vous qui, ayant un ami, aille à lui sur le minuit, et lui dise: Ami, prête-moi trois pains,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'car mon ami est arrivé de voyage chez moi, et je n’ai rien à lui présenter?...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'et celui qui est dedans, répondant, dira: Ne m’importune pas; la porte est déjà fermée, et mes enfants sont au lit avec moi; je ne puis me lever et t’en donner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, '– Je vous dis que, bien qu’il ne se lève pas et ne lui en donne pas parce qu’il est son ami, pourtant, à cause de son importunité, il se lèvera et lui en donnera autant qu’il en a besoin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Et moi, je vous dis: Demandez, et il vous sera donné; cherchez, et vous trouverez; heurtez, et il vous sera ouvert;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'car quiconque demande, reçoit; et celui qui cherche, trouve; et à celui qui heurte, il sera ouvert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Or quel est le père d’entre vous à qui son fils demandera un pain et qui lui donnera une pierre? ou aussi, [s’il demande] un poisson, lui donnera, au lieu d’un poisson, un serpent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'ou aussi, s’il demande un œuf, lui donnera un scorpion?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Si donc vous qui êtes méchants, vous savez donner à vos enfants des choses bonnes, combien plus le Père qui est du ciel donnera-t-il l’Esprit Saint à ceux qui le lui demandent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Et il chassa un démon qui était muet. Et il arriva que, quand le démon fut sorti, le muet parla; et les foules s’en étonnèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Mais quelques-uns d’entre eux disaient: Il chasse les démons par Béelzébul, le chef des démons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Et d’autres, pour l’éprouver, lui demandaient un signe du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Mais lui, connaissant leurs pensées, leur dit: Tout royaume divisé contre lui-même sera réduit en désert; et une maison [divisée] contre elle-même tombe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'et si Satan aussi est divisé contre lui-même, comment son royaume subsistera-t-il? parce que vous dites que je chasse les démons par Béelzébul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Or si c’est par Béelzébul que moi je chasse les démons, vos fils, par qui les chassent-ils? C’est pourquoi ils seront eux-mêmes vos juges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Mais si je chasse les démons par le doigt de Dieu, alors le royaume de Dieu est parvenu jusqu’à vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Quand l’homme fort, revêtu de ses armes, garde son palais, ses biens sont en paix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'mais s’il en survient un plus fort que lui qui le vainque, il lui ôte son armure à laquelle il se confiait, et fait le partage de ses dépouilles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Celui qui n’est pas avec moi est contre moi; et celui qui n’assemble pas avec moi, disperse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Quand l’esprit immonde est sorti d’un homme, il va par des lieux secs, cherchant du repos; et n’en trouvant point, il dit: Je retournerai dans ma maison d’où je suis sorti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Et y étant venu, il la trouve balayée et ornée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Alors il va, et prend sept autres esprits plus méchants que lui-même; et étant entrés, ils habitent là; et la dernière condition de cet homme-là est pire que la première.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Et il arriva, comme il disait ces choses, qu’une femme éleva sa voix du milieu de la foule et lui dit: Bienheureux est le ventre qui t’a porté, et les mamelles que tu as tétées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Et il dit: Mais plutôt, bienheureux sont ceux qui écoutent la parole de Dieu et qui la gardent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Et comme les foules s’amassaient, il se mit à dire: Cette génération est une méchante génération; elle demande un signe; et il ne lui sera pas donné de signe, si ce n’est le signe de Jonas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Car comme Jonas fut un signe aux Ninivites, ainsi aussi sera le fils de l’homme à cette génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Une reine du midi se lèvera au jugement avec les hommes de cette génération et les condamnera; car elle vint des bouts de la terre pour entendre la sagesse de Salomon, et voici, il y a ici plus que Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Des hommes de Ninive se lèveront au jugement avec cette génération et la condamneront; car ils se sont repentis à la prédication de Jonas, et voici, il y a ici plus que Jonas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Or personne, après avoir allumé une lampe, ne la met dans un lieu caché, ni sous le boisseau, mais sur le pied de lampe, afin que ceux qui entrent voient la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'La lampe du corps, c’est ton œil; lorsque ton œil est simple, ton corps tout entier aussi est plein de lumière; mais lorsqu’il est méchant, ton corps aussi est ténébreux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Prends donc garde que la lumière qui est en toi ne soit ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Si donc ton corps tout entier est plein de lumière, n’ayant aucune partie ténébreuse, il sera tout plein de lumière, comme quand la lampe t’éclaire de son éclat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Et comme il parlait, un pharisien le pria de dîner chez lui; et entrant, il se mit à table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Mais le pharisien, voyant [cela], s’étonna parce qu’il ne s’était pas premièrement lavé avant le dîner.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Et le Seigneur lui dit: Pour vous, pharisiens, vous nettoyez le dehors de la coupe et du plat, mais au-dedans vous êtes pleins de rapine et de méchanceté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Insensés! celui qui a fait le dehors, n’a-t-il pas fait le dedans aussi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Mais donnez l’aumône de ce que vous avez; et voici, toutes choses vous seront nettes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Mais malheur à vous, pharisiens! car vous payez la dîme de la menthe et de la rue et de toute sorte d’herbe, et vous négligez le jugement et l’amour de Dieu: il fallait faire ces choses-ci, et ne pas laisser celles-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Malheur à vous, pharisiens! car vous aimez les premiers sièges dans les synagogues, et les salutations dans les places publiques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Malheur à vous! car vous êtes comme les sépulcres qui ne paraissent pas; et les hommes, marchant dessus, n’en savent rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Et l’un des docteurs de la loi, répondant, lui dit: Maître, en disant ces choses tu nous dis aussi des injures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Et il dit: À vous aussi, malheur, docteurs de la loi! car vous chargez les hommes de fardeaux difficiles à porter, et vous-mêmes vous ne touchez pas ces fardeaux d’un seul de vos doigts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Malheur à vous! car vous bâtissez les tombeaux des prophètes, et vos pères les ont tués.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Vous rendez donc témoignage aux œuvres de vos pères et vous y prenez plaisir; car eux, ils les ont tués, et vous, vous bâtissez leurs tombeaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'C’est pourquoi aussi la sagesse de Dieu a dit: Je leur enverrai des prophètes et des apôtres, et ils en tueront et en chasseront par des persécutions:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'afin que le sang de tous les prophètes qui a été versé depuis la fondation du monde soit redemandé à cette génération,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'depuis le sang d’Abel jusqu’au sang de Zacharie, qui périt entre l’autel et la maison: oui, vous dis-je, il sera redemandé à cette génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Malheur à vous, les docteurs de la loi! car vous avez enlevé la clé de la connaissance: vous n’êtes pas entrés vous-mêmes, et vous avez empêché ceux qui entraient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Et comme il leur disait ces choses, les scribes et les pharisiens se mirent à le presser fortement; et ils le provoquaient à parler de plusieurs choses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'lui dressant des pièges, et cherchant à surprendre quelque chose de sa bouche, afin de l’accuser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Cependant les foules s’étant rassemblées par milliers, de sorte qu’ils se foulaient les uns les autres, il se mit, avant tout, à dire à ses disciples: Tenez-vous en garde contre le levain des pharisiens, qui est l’hypocrisie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Mais il n’y a rien de couvert qui ne sera révélé, ni rien de secret qui ne sera connu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'C’est pourquoi toutes les choses que vous avez dites dans les ténèbres seront entendues dans la lumière, et ce dont vous avez parlé à l’oreille dans les chambres sera publié sur les toits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Mais je vous dis à vous, mes amis: Ne craignez pas ceux qui tuent le corps et qui après cela ne peuvent rien faire de plus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'mais je vous montrerai qui vous devez craindre: craignez celui qui, après avoir tué, a le pouvoir de jeter dans la géhenne: oui, vous dis-je, craignez celui-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Ne vend-on pas cinq passereaux pour deux sous? et pas un seul d’entre eux n’est oublié devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Mais les cheveux même de votre tête sont tous comptés. Ne craignez donc pas: vous valez mieux que beaucoup de passereaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Et je vous dis: Quiconque m’aura confessé devant les hommes, le fils de l’homme le confessera aussi devant les anges de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'mais celui qui m’aura renié devant les hommes sera renié devant les anges de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Et quiconque parlera contre le fils de l’homme, il lui sera pardonné; mais à celui qui aura proféré des paroles injurieuses contre le Saint Esprit, il ne sera pas pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Et quand ils vous mèneront devant les synagogues et les magistrats et les autorités, ne soyez pas en souci comment, ou quelle chose vous répondrez, ou de ce que vous direz;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'car le Saint Esprit vous enseignera à l’heure même ce qu’il faudra dire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Et quelqu’un lui dit du milieu de la foule: Maître, dis à mon frère de partager avec moi l’héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Mais il lui dit: Homme, qui est-ce qui m’a établi sur vous [pour être votre] juge et pour faire vos partages?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Et il leur dit: Voyez, et gardez-vous de toute avarice; car encore que quelqu’un soit riche, sa vie n’est pas dans ses biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Et il leur dit une parabole, disant: Les champs d’un homme riche avaient beaucoup rapporté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'et il raisonnait en lui-même, disant: Que ferai-je, car je n’ai pas où je puisse assembler mes fruits?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Et il dit: Voici ce que je ferai: j’abattrai mes greniers et j’en bâtirai de plus grands, et j’y assemblerai tous mes produits et mes biens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'et je dirai à mon âme: [Mon] âme, tu as beaucoup de biens assemblés pour beaucoup d’années; repose-toi, mange, bois, fais grande chère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Mais Dieu lui dit: Insensé! cette nuit même ton âme te sera redemandée; et ces choses que tu as préparées, à qui seront-elles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Il en est ainsi de celui qui amasse des trésors pour lui-même, et qui n’est pas riche quant à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Et il dit à ses disciples: À cause de cela, je vous dis: Ne soyez pas en souci pour la vie, de ce que vous mangerez; ni pour le corps, de quoi vous serez vêtus:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'la vie est plus que la nourriture, et le corps plus que le vêtement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Considérez les corbeaux: ils ne sèment ni ne moissonnent, et ils n’ont pas de cellier ni de grenier; et Dieu les nourrit: combien valez-vous mieux que les oiseaux!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Et qui d’entre vous, par le souci qu’il se donne, peut ajouter une coudée à sa taille?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Si donc vous ne pouvez pas même ce qui est très petit, pourquoi êtes-vous en souci du reste?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Considérez les lis, comment ils croissent: ils ne travaillent ni ne filent; cependant je vous dis que même Salomon, dans toute sa gloire, n’était pas vêtu comme l’un d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Et si Dieu revêt ainsi l’herbe qui est aujourd’hui au champ et qui demain est jetée dans le four, combien plus vous [vêtira-t-il], gens de petite foi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Et vous, ne recherchez pas ce que vous mangerez ou ce que vous boirez, et n’en soyez pas en peine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'car les nations du monde recherchent toutes ces choses, et votre Père sait que vous avez besoin de ces choses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'mais recherchez son royaume, et ces choses vous seront données par-dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, '– Ne crains pas, petit troupeau, car il a plu à votre Père de vous donner le royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Vendez ce que vous avez, et donnez l’aumône; faites-vous des bourses qui ne vieillissent pas, un trésor qui ne défaille pas, dans les cieux, d’où le voleur n’approche pas, et où la teigne ne détruit pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'car là où est votre trésor, là sera aussi votre cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Que vos reins soient ceints et vos lampes allumées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'et soyez vous-mêmes semblables à des hommes qui attendent leur maître, à quelque moment qu’il revienne des noces, afin que, quand il viendra et qu’il heurtera, ils lui ouvrent aussitôt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Bienheureux sont ces esclaves, que le maître, quand il viendra, trouvera veillant. En vérité, je vous dis qu’il se ceindra et les fera mettre à table, et, s’avançant, il les servira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Et s’il vient à la seconde veille, et s’il vient à la troisième, et qu’il les trouve ainsi, bienheureux sont ces [esclaves]-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Mais sachez ceci, que si le maître de la maison avait su à quelle heure le voleur devait venir, il aurait veillé et n’aurait pas laissé percer sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Vous donc aussi soyez prêts; car, à l’heure que vous ne pensez pas, le fils de l’homme vient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Et Pierre lui dit: Seigneur, dis-tu cette parabole pour nous, ou aussi pour tous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Et le Seigneur dit: Qui donc est l’économe fidèle et prudent que le maître établira sur les domestiques de sa maison, pour leur donner au temps convenable leur ration de blé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Bienheureux est cet esclave-là, que son maître lorsqu’il viendra, trouvera faisant ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'En vérité, je vous dis qu’il l’établira sur tous ses biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Mais si cet esclave-là dit en son cœur: Mon maître tarde à venir, et qu’il se mette à battre les serviteurs et les servantes, et à manger et à boire et à s’enivrer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'le maître de cet esclave-là viendra en un jour qu’il n’attend pas, et à une heure qu’il ne sait pas, et il le coupera en deux, et lui donnera sa part avec les infidèles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Or cet esclave qui a connu la volonté de son maître, et qui ne s’est pas préparé et n’a point fait selon sa volonté, sera battu de plusieurs coups;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'et celui qui ne l’a point connue, et qui a fait des choses qui méritent des coups, sera battu de peu de coups: car à quiconque il aura été beaucoup donné, il sera beaucoup redemandé; et à celui à qui il aura été beaucoup confié, il sera plus redemandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Je suis venu jeter le feu sur la terre; et que veux-je, si déjà il est allumé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Mais j’ai à être baptisé d’un baptême; et combien suis-je à l’étroit jusqu’à ce qu’il soit accompli!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Pensez-vous que je sois venu donner la paix sur la terre? Non, vous dis-je; mais plutôt la division.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Car désormais ils seront cinq dans une maison, divisés: trois seront divisés contre deux, et deux contre trois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'le père contre le fils, et le fils contre le père; la mère contre la fille, et la fille contre la mère; la belle-mère contre sa belle-fille, et la belle-fille contre sa belle-mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Et il dit aussi aux foules: Quand vous voyez une nuée se lever de l’occident, aussitôt vous dites: Une ondée vient; et cela arrive ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Et quand [vous voyez] souffler le vent du midi, vous dites: Il fera chaud; et cela arrive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Hypocrites! vous savez discerner les apparences de la terre et du ciel, et comment ne discernez-vous pas ce temps-ci?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Et pourquoi aussi ne jugez-vous pas par vous-mêmes de ce qui est juste?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Car quand tu vas avec ta partie adverse devant le magistrat, efforce-toi en chemin d’en être délivré, de peur qu’elle ne te tire devant le juge; et le juge te livrera au sergent, et le sergent te jettera en prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Je te dis que tu ne sortiras point de là, que tu n’aies payé jusqu’à la dernière pite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Or en ce même temps, quelques-uns se trouvaient là présents, qui lui racontèrent [ce qui s’était passé] touchant les Galiléens dont Pilate avait mêlé le sang avec leurs sacrifices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Et [Jésus], répondant, leur dit: Croyez-vous que ces Galiléens étaient plus pécheurs que tous les Galiléens, parce qu’ils ont souffert de telles choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Non, vous dis-je; mais si vous ne vous repentez, vous périrez tous de la même manière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Ou, ces 18 sur qui tomba la tour dans Siloé, et qu’elle tua, croyez-vous qu’ils étaient plus coupables que tous les hommes qui habitent Jérusalem?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Non, vous dis-je; mais si vous ne vous repentez, vous périrez tous pareillement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Et il disait cette parabole: Quelqu’un avait un figuier planté dans sa vigne; et il vint y chercher du fruit, et il n’en trouva point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Et il dit au vigneron: Voici trois ans que je viens chercher du fruit sur ce figuier, et je n’en trouve point: coupe-le; pourquoi aussi occupe-t-il inutilement la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Et répondant, il lui dit: Maître, laisse-le cette année aussi, jusqu’à ce que je l’aie déchaussé et que j’y aie mis du fumier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'et peut-être portera-t-il du fruit: sinon, après, tu le couperas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Or il enseignait dans l’une des synagogues en un jour de sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Et voici, il y avait là une femme ayant un esprit d’infirmité depuis 18 ans, et elle était courbée et ne pouvait nullement se redresser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Et Jésus, la voyant, l’appela et lui dit: Femme, tu es délivrée de ton infirmité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Et il posa les mains sur elle: et à l’instant elle fut redressée, et glorifiait Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Et le chef de synagogue, indigné de ce que Jésus avait guéri, un jour de sabbat, répondant, dit à la foule: Il y a six jours où il faut travailler; venez donc ces jours-là, et soyez guéris, et non pas le jour du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Le Seigneur donc lui répondit, et dit: Hypocrites! chacun de vous ne détache-t-il pas de la crèche son bœuf ou son âne un jour de sabbat, et ne les mène-t-il pas boire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Et celle-ci qui est fille d’Abraham, laquelle Satan avait liée, voici, il y a 18 ans, ne fallait-il pas la délier de ce lien le jour du sabbat?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Et comme il disait ces choses, tous ses adversaires furent couverts de honte; et toute la foule se réjouissait de toutes les choses glorieuses qui étaient faites par lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Et il disait: À quoi est semblable le royaume de Dieu, et à quoi le comparerai-je?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Il est semblable à un grain de moutarde qu’un homme prit et jeta dans son jardin; et il crût et devint un grand arbre, et les oiseaux du ciel demeuraient dans ses branches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Et il dit encore: À quoi comparerai-je le royaume de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Il est semblable à du levain qu’une femme prit, et qu’elle cacha parmi trois mesures de farine, jusqu’à ce que tout soit levé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Et il allait par les villes et par les villages, enseignant, et poursuivant son chemin vers Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Et quelqu’un lui dit: Seigneur, ceux qui doivent être sauvés sont-ils en petit nombre? Et il leur dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Luttez pour entrer par la porte étroite; car beaucoup, je vous le dis, chercheront à entrer et ne pourront pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Dès que le maître de la maison se sera levé, et aura fermé la porte, et que vous vous serez mis à vous tenir dehors et à heurter à la porte, en disant: Seigneur, ouvre-nous! et que, répondant, il vous dira: Je ne vous connais pas [ni ne sais] d’où vous êtes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'alors vous vous mettrez à dire: Nous avons mangé et bu en ta présence, et tu as enseigné dans nos rues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Et il dira: Je vous dis, je ne vous connais pas, [ni ne sais] d’où vous êtes; retirez-vous de moi, vous tous, ouvriers d’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Là seront les pleurs et les grincements de dents, quand vous verrez Abraham et Isaac et Jacob et tous les prophètes dans le royaume de Dieu, mais vous, jetés dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Et il en viendra d’orient et d’occident, et du nord et du midi; et ils s’assiéront dans le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Et voici, il y a des derniers qui seront les premiers, et il y a des premiers qui seront les derniers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'En ce même jour, des pharisiens vinrent, lui disant: Retire-toi et va-t’en d’ici; car Hérode veut te tuer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Et il leur dit: Allez, dites à ce renard: Voici, je chasse des démons et j’accomplis des guérisons aujourd’hui et demain, et le troisième jour je suis consommé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Mais il faut que je marche aujourd’hui et demain et le jour suivant, car il ne se peut qu’un prophète périsse hors de Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jérusalem, Jérusalem, [la ville] qui tue les prophètes et qui lapide ceux qui lui sont envoyés, que de fois j’ai voulu rassembler tes enfants, comme une poule sa couvée sous ses ailes, et vous ne l’avez pas voulu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Voici, votre maison vous est abandonnée; et je vous dis, que vous ne me verrez point jusqu’à ce qu’il arrive que vous disiez: Béni soit celui qui vient au nom du ✶Seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Et il arriva que, comme il entrait, un sabbat, dans la maison d’un des principaux des pharisiens pour manger du pain, ils l’observaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Et voici, il y avait un homme hydropique devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Et Jésus, répondant, parla aux docteurs de la loi et aux pharisiens, disant: Est-il permis de guérir, un jour de sabbat?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Et ils se turent. Et l’ayant pris, il le guérit, et le renvoya.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Et répondant, il leur dit: Qui sera celui de vous, qui, ayant un âne ou un bœuf, lequel vienne à tomber dans un puits, ne l’en retire aussitôt le jour du sabbat?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Et ils ne pouvaient répliquer à ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Or il dit une parabole aux conviés, observant comment ils choisissaient les premières places; et il leur disait:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Quand tu seras convié par quelqu’un à des noces, ne te mets pas à table à la première place, de peur qu’un plus honorable que toi ne soit convié par lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'et que celui qui vous a conviés, toi et lui, ne vienne et ne te dise: Fais place à celui-ci; et qu’alors tu ne te mettes avec honte à occuper la dernière place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Mais, quand tu seras convié, va et assieds-toi à la dernière place, afin que, quand celui qui t’a convié viendra, il te dise: Ami, monte plus haut. Alors tu auras de la gloire devant tous ceux qui seront à table avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Car quiconque s’élève, sera abaissé; et celui qui s’abaisse sera élevé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Et il dit aussi à celui qui l’avait convié: Quand tu fais un dîner ou un souper, n’appelle pas tes amis, ni tes frères, ni tes parents, ni de riches voisins; de peur qu’eux aussi ne te convient à leur tour, et que la pareille ne te soit rendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Mais quand tu fais un festin, convie les pauvres, les estropiés, les boiteux, les aveugles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'et tu seras bienheureux, car ils n’ont pas de quoi te rendre la pareille: car la pareille te sera rendue en la résurrection des justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Et un de ceux qui étaient à table, ayant entendu ces choses, lui dit: Bienheureux celui qui mangera du pain dans le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Et il lui dit: Un homme fit un grand souper et y convia beaucoup de gens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Et à l’heure du souper, il envoya son esclave dire aux conviés: Venez, car déjà tout est prêt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Et ils commencèrent tous unanimement à s’excuser. Le premier lui dit: J’ai acheté un champ, et il faut nécessairement que je m’en aille et que je le voie; je te prie, tiens-moi pour excusé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Et un autre dit: J’ai acheté cinq paires de bœufs, et je vais les essayer; je te prie, tiens-moi pour excusé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Et un autre dit: J’ai épousé une femme, et à cause de cela je ne puis aller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Et l’esclave, s’en étant retourné, rapporta ces choses à son maître. Alors le maître de la maison, en colère, dit à son esclave: Va-t’en promptement dans les rues et dans les ruelles de la ville, et amène ici les pauvres, et les estropiés, et les aveugles, et les boiteux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Et l’esclave dit: Maître, il a été fait ainsi que tu as commandé, et il y a encore de la place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Et le maître dit à l’esclave: Va-t’en dans les chemins et [le long des] haies, et contrains [les gens] d’entrer, afin que ma maison soit remplie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'car je vous dis, qu’aucun de ces hommes qui ont été conviés ne goûtera de mon souper.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Et de grandes foules allaient avec lui. Et se tournant, il leur dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Si quelqu’un vient à moi, et ne hait pas son père, et sa mère, et sa femme, et ses enfants, et ses frères, et ses sœurs, et même aussi sa propre vie, il ne peut être mon disciple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Et quiconque ne porte pas sa croix, et ne vient pas après moi, ne peut être mon disciple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Car quel est celui d’entre vous qui, voulant bâtir une tour, ne s’asseye premièrement et ne calcule la dépense, [pour voir] s’il a de quoi l’achever?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'de peur que, en ayant jeté le fondement et n’ayant pu l’achever, tous ceux qui le voient ne se mettent à se moquer de lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'disant: Cet homme a commencé à bâtir, et il n’a pu achever.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Ou, quel est le roi qui, partant pour faire la guerre à un autre roi, ne s’asseye premièrement et ne délibère s’il peut, avec 10 000 [hommes], résister à celui qui vient contre lui avec 20 000?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Autrement, pendant qu’il est encore loin, il lui envoie une ambassade et s’informe des [conditions] de paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Ainsi donc, quiconque d’entre vous ne renonce pas à tout ce qu’il a, ne peut être mon disciple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Le sel donc est bon; mais si le sel aussi a perdu sa saveur, avec quoi l’assaisonnera-t-on?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Il n’est propre, ni pour la terre, ni pour le fumier; on le jette dehors. Qui a des oreilles pour entendre, qu’il entende.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Et tous les publicains et les pécheurs s’approchaient de lui pour l’entendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Et les pharisiens et les scribes murmuraient, disant: Celui-ci reçoit des pécheurs, et mange avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Et il leur dit cette parabole, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Quel est l’homme d’entre vous, qui, ayant 100 brebis et en ayant perdu une, ne laisse les 99 au désert, et ne s’en aille après celle qui est perdue, jusqu’à ce qu’il l’ait trouvée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'et l’ayant trouvée, il la met sur ses propres épaules, bien joyeux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'et, étant de retour à la maison, il appelle les amis et les voisins, leur disant: Réjouissez-vous avec moi, car j’ai trouvé ma brebis perdue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Je vous dis, qu’ainsi il y aura de la joie au ciel pour un seul pécheur qui se repent, plus que pour 99 justes qui n’ont pas besoin de repentance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Ou quelle est la femme, qui, ayant dix drachmes, si elle perd une drachme, n’allume la lampe et ne balaie la maison, et ne cherche diligemment jusqu’à ce qu’elle l’ait trouvée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'et l’ayant trouvée, elle assemble les amies et les voisines, disant: Réjouissez-vous avec moi, car j’ai trouvé la drachme que j’avais perdue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Ainsi, je vous dis, il y a de la joie devant les anges de Dieu pour un seul pécheur qui se repent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Et il dit: Un homme avait deux fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'et le plus jeune d’entre eux dit à son père: Père, donne-moi la part du bien qui me revient. Et il leur partagea son bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Et peu de jours après, le plus jeune fils, ayant tout ramassé, s’en alla dehors en un pays éloigné; et là il dissipa son bien en vivant dans la débauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Et après qu’il eut tout dépensé, une grande famine survint dans ce pays-là; et il commença d’être dans le besoin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Et il s’en alla et se joignit à l’un des citoyens de ce pays-là, et celui-ci l’envoya dans ses champs pour paître des pourceaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Et il désirait de remplir son ventre des gousses que les pourceaux mangeaient; et personne ne lui donnait [rien].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Et étant revenu à lui-même, il dit: Combien de mercenaires de mon père ont du pain en abondance, et moi je péris ici de faim!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Je me lèverai et je m’en irai vers mon père, et je lui dirai: Père, j’ai péché contre le ciel et devant toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'je ne suis plus digne d’être appelé ton fils; traite-moi comme l’un de tes mercenaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Et se levant, il vint vers son père. Et comme il était encore loin, son père le vit et fut ému de compassion, et, courant [à lui], se jeta à son cou et le couvrit de baisers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Et le fils lui dit: Père, j’ai péché contre le ciel et devant toi; je ne suis plus digne d’être appelé ton fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Mais le père dit à ses esclaves: Apportez dehors la plus belle robe, et l’en revêtez; et mettez un anneau à sa main et des sandales à ses pieds;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'et amenez le veau gras et tuez-le; et mangeons et faisons bonne chère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'car mon fils que voici était mort, et il est revenu à la vie; il était perdu, et il est retrouvé. Et ils se mirent à faire bonne chère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Or son fils aîné était aux champs; et comme il revenait et qu’il approchait de la maison, il entendit la mélodie et les danses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'et, ayant appelé l’un des serviteurs, il demanda ce que c’était.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Et il lui dit: Ton frère est venu, et ton père a tué le veau gras, parce qu’il l’a recouvré sain et sauf.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Et il se mit en colère et ne voulait pas entrer. Et son père étant sorti, le pria.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Mais lui, répondant, dit à son père: Voici tant d’années que je te sers, et jamais je n’ai transgressé ton commandement; et tu ne m’as jamais donné un chevreau pour faire bonne chère avec mes amis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'mais quand celui-ci, ton fils, qui a mangé ton bien avec des prostituées, est venu, tu as tué pour lui le veau gras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Et il lui dit: [Mon] enfant, tu es toujours avec moi, et tout ce qui est à moi est à toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'mais il fallait faire bonne chère et se réjouir; car celui-ci, ton frère, était mort, et il est revenu à la vie; il était perdu, et il est retrouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Et il dit aussi à ses disciples: Il y avait un homme riche qui avait un économe; et celui-ci fut accusé devant lui comme dissipant ses biens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Et l’ayant appelé, il lui dit: Qu’est-ce que ceci que j’entends dire de toi? Rends compte de ton administration; car tu ne pourras plus administrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Et l’économe dit en lui-même: Que ferai-je, car mon maître m’ôte l’administration? Je ne puis pas bêcher la terre; j’ai honte de mendier:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'je sais ce que je ferai, afin que, quand je serai renvoyé de mon administration, je sois reçu dans leurs maisons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Et ayant appelé chacun des débiteurs de son maître, il dit au premier: Combien dois-tu à mon maître?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Et il dit: 100 baths d’huile. Et il lui dit: Prends ton écrit, et assieds-toi promptement et écris 50.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Puis il dit à un autre: Et toi, combien dois-tu? Et il dit: 100 cors de froment. Et il lui dit: Prends ton écrit, et écris 80.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Et le maître loua l’économe injuste parce qu’il avait agi prudemment. Car les fils de ce siècle sont plus prudents, par rapport à leur propre génération, que les fils de la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Et moi, je vous dis: Faites-vous des amis avec les richesses injustes, afin que, quand vous viendrez à manquer, vous soyez reçus dans les tabernacles éternels.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Celui qui est fidèle dans ce qui est très petit, est fidèle aussi dans ce qui est grand; et celui qui est injuste dans ce qui est très petit, est injuste aussi dans ce qui est grand.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Si donc vous n’avez pas été fidèles dans les richesses injustes, qui vous confiera les vraies?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Et si, dans ce qui est à autrui, vous n’avez pas été fidèles, qui vous donnera ce qui est vôtre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Nul serviteur ne peut servir deux maîtres; car ou il haïra l’un et aimera l’autre, ou il s’attachera à l’un et méprisera l’autre: vous ne pouvez servir Dieu et les richesses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Et les pharisiens aussi, qui étaient avares, entendirent toutes ces choses, et ils se moquèrent de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Et il leur dit: Vous êtes ceux qui se justifient eux-mêmes devant les hommes; mais Dieu connaît vos cœurs: car ce qui est haut estimé parmi les hommes est une abomination devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'La loi et les prophètes [ont été] jusqu’à Jean; dès lors le royaume de Dieu est annoncé et chacun use de violence pour y entrer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Or il est plus facile que le ciel et la terre passent, qu’il ne l’est qu’un seul trait de lettre de la loi tombe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Quiconque répudie sa femme et en épouse une autre, commet adultère; et quiconque épouse une femme répudiée par son mari, commet adultère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Or il y avait un homme riche qui se vêtait de pourpre et de fin lin, et qui faisait joyeuse chère, chaque jour, splendidement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Et il y avait un pauvre, nommé Lazare, couché à sa porte, tout couvert d’ulcères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'et qui désirait de se rassasier des miettes qui tombaient de la table du riche; mais les chiens aussi venaient lécher ses ulcères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Et il arriva que le pauvre mourut, et qu’il fut porté par les anges dans le sein d’Abraham. Et le riche aussi mourut, et fut enseveli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Et, en hadès, levant ses yeux, comme il était dans les tourments, il voit de loin Abraham, et Lazare dans son sein.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Et s’écriant, il dit: Père Abraham, aie pitié de moi et envoie Lazare, afin qu’il trempe dans l’eau le bout de son doigt, et qu’il rafraîchisse ma langue, car je suis tourmenté dans cette flamme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Mais Abraham dit: [Mon] enfant, souviens-toi que tu as reçu tes biens pendant ta vie, et Lazare pareillement les maux; et maintenant lui est consolé ici, et toi tu es tourmenté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Et outre tout cela, un grand gouffre est fermement établi entre nous et vous; en sorte que ceux qui veulent passer d’ici vers vous ne le peuvent, et que ceux qui [veulent passer] de là ne traversent pas non plus vers nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Et il dit: Je te prie donc, père, de l’envoyer dans la maison de mon père,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'car j’ai cinq frères, en sorte qu’il les adjure; de peur qu’eux aussi ne viennent dans ce lieu de tourment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Mais Abraham lui dit: Ils ont Moïse et les prophètes; qu’ils les écoutent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Mais il dit: Non, père Abraham; mais si quelqu’un va des morts vers eux, ils se repentiront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Et il lui dit: S’ils n’écoutent pas Moïse et les prophètes, ils ne seront pas persuadés non plus si quelqu’un ressuscitait d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Or il dit à ses disciples: Il est impossible qu’il n’arrive pas des scandales; mais malheur à celui par qui ils arrivent!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Mieux lui vaudrait qu’on lui mette au cou une meule d’âne, et qu’il soit jeté dans la mer, que de scandaliser un de ces petits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Prenez garde à vous-mêmes. Si ton frère pèche, reprends-le, et s’il se repent, pardonne-lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'et si sept fois le jour il pèche contre toi, et que sept fois il retourne à toi, disant: Je me repens, tu lui pardonneras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Et les apôtres dirent au Seigneur: Augmente-nous la foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Et le Seigneur dit: Si vous avez de la foi comme un grain de moutarde, vous diriez à ce mûrier: Déracine-toi, et plante-toi dans la mer; et il vous obéirait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Mais qui est celui d’entre vous, qui, ayant un esclave labourant ou paissant [le bétail], quand il revient des champs, dise: Avance-toi de suite et mets-toi à table?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Ne lui dira-t-il pas au contraire: Apprête-moi à souper et ceins-toi, et sers-moi jusqu’à ce que j’aie mangé et bu; et après cela, tu mangeras et tu boiras, toi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Est-il obligé à l’esclave de ce qu’il a fait ce qui avait été commandé? Je ne le pense pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Ainsi, vous aussi, quand vous aurez fait toutes les choses qui vous ont été commandées, dites: Nous sommes des esclaves inutiles; ce que nous étions obligés de faire, nous l’avons fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Et il arriva qu’en allant à Jérusalem, il traversait la Samarie et la Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Et comme il entrait dans un village, dix hommes lépreux le rencontrèrent; et ils s’arrêtèrent de loin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'et ils élevèrent la voix, disant: Jésus, maître, aie pitié de nous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Et les voyant, il leur dit: Allez, montrez-vous aux sacrificateurs. Et il arriva qu’en s’en allant ils furent rendus nets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Or l’un d’entre eux, voyant qu’il était guéri, revint sur ses pas, glorifiant Dieu à haute voix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'et il se jeta sur sa face aux pieds de Jésus, lui rendant grâces. Et c’était un Samaritain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Et Jésus, répondant, dit: Les dix n’ont-ils pas été rendus nets? Et les neuf, où sont-ils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Il ne s’en est point trouvé qui soient revenus pour donner gloire à Dieu, si ce n’est cet étranger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Et il lui dit: Lève-toi, et t’en va; ta foi t’a guéri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Or, étant interrogé par les pharisiens quand viendrait le royaume de Dieu, il leur répondit et dit: Le royaume de Dieu ne vient pas de manière à attirer l’attention;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'et on ne dira pas: Voici, il est ici; ou, voilà, il est là. Car voici, le royaume de Dieu est au milieu de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Et il dit aux disciples: Les jours viendront où vous désirerez de voir l’un des jours du fils de l’homme, et vous ne le verrez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Et on vous dira: Voici, il est ici; ou, voilà, il est là. N’y allez pas, et ne les suivez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Car comme l’éclair qui brille, luit de l’un des côtés de dessous le ciel jusqu’à l’autre côté de dessous le ciel, ainsi sera le fils de l’homme en son jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Mais auparavant il faut qu’il souffre beaucoup, et qu’il soit rejeté par cette génération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Et comme il arriva aux jours de Noé, ainsi en sera-t-il aux jours du fils de l’homme aussi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'on mangeait, on buvait, on se mariait, on donnait en mariage, jusqu’au jour où Noé entra dans l’arche; et le déluge vint, et les fit tous périr.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'De même aussi, comme il arriva aux jours de Lot: on mangeait, on buvait, on achetait, on vendait, on plantait, on bâtissait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'mais, au jour où Lot sortit de Sodome, il plut du feu et du soufre du ciel, qui les fit tous périr;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'il en sera de même au jour où le fils de l’homme sera manifesté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'En ce jour-là, que celui qui sera sur le toit et qui aura ses effets dans la maison, ne descende pas pour les emporter; et pareillement que celui qui sera aux champs ne retourne pas en arrière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Souvenez-vous de la femme de Lot.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Quiconque cherchera à sauver sa vie, la perdra; et quiconque la perdra, la gagnera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Je vous dis qu’en cette nuit-là deux seront sur un même lit, l’un sera pris et l’autre laissé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'deux femmes moudront ensemble, l’une sera prise et l’autre laissée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '[deux seront aux champs, l’un sera pris et l’autre laissé].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Et répondant, ils lui disent: Où, Seigneur? Et il leur dit: Là où est le corps, là aussi s’assembleront les aigles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Et il leur dit aussi une parabole, pour [montrer] qu’ils devaient toujours prier et ne pas se lasser,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'disant: Il y avait dans une ville un certain juge qui ne craignait pas Dieu et qui ne respectait pas les hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'et dans cette ville-là il y avait une veuve, et elle alla vers lui, disant: Venge-moi de mon adversaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Et il ne le voulut pas pour un temps. Mais après cela, il dit en lui-même: Quoique je ne craigne pas Dieu et que je ne respecte pas les hommes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'néanmoins, parce que cette veuve m’ennuie, je lui ferai justice, de peur que, revenant sans cesse, elle ne me rompe la tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Et le Seigneur dit: Écoutez ce que dit le juge inique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Et Dieu ne ferait-il point justice à ses élus, qui crient à lui jour et nuit, et il use de patience [avant d’intervenir] pour eux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Je vous dis que bientôt il leur fera justice. Mais le fils de l’homme quand il viendra, trouvera-t-il de la foi sur la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Et il dit aussi cette parabole à quelques-uns qui se confiaient en eux-mêmes comme s’ils étaient justes, et qui tenaient le reste des hommes pour rien:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Deux hommes montèrent au temple pour prier, l’un pharisien, et l’autre publicain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Le pharisien, se tenant à l’écart, priait en lui-même en ces termes: Ô Dieu, je te rends grâces de ce que je ne suis pas comme le reste des hommes qui sont ravisseurs, injustes, adultères; ou même comme ce publicain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Je jeûne deux fois la semaine, je donne la dîme de tout ce que je possède.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Et le publicain, se tenant loin, ne voulait même pas lever les yeux vers le ciel, mais se frappait la poitrine, disant: Ô Dieu, sois apaisé envers moi, pécheur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Je vous dis que celui-ci descendit en sa maison justifié plutôt que l’autre; car quiconque s’élève, sera abaissé; et celui qui s’abaisse sera élevé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Et on lui apporta aussi les petits enfants, afin qu’il les touche; et les disciples, le voyant, reprirent ceux [qui les apportaient].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Mais Jésus, les ayant appelés, dit: Laissez venir à moi les petits enfants, et ne les en empêchez pas; car à de tels est le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'En vérité, je vous dis: Quiconque ne recevra pas le royaume de Dieu comme un petit enfant, n’y entrera point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Et un des chefs [du peuple] l’interrogea, disant: Bon maître, que faut-il que j’aie fait pour hériter de la vie éternelle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Et Jésus lui dit: Pourquoi m’appelles-tu bon? Nul n’est bon, sinon un [seul], Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Tu sais les commandements: Ne commets point adultère; ne tue point; ne dérobe point; ne dis point de faux témoignage; honore ton père et ta mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Et il dit: J’ai gardé toutes ces choses dès ma jeunesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Et quand Jésus eut entendu cela, il lui dit: Une chose te manque encore: vends tout ce que tu as, et distribue-le aux pauvres, et tu auras un trésor dans les cieux; et viens, suis-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Et lui, ayant entendu ces choses, devint fort triste; car il était extrêmement riche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Et Jésus, voyant qu’il était devenu fort triste, dit: Combien difficilement ceux qui ont des biens entreront-ils dans le royaume de Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Car il est plus facile qu’un chameau entre par un trou d’aiguille, qu’un riche n’entre dans le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Et ceux qui entendirent cela, dirent: Et qui peut être sauvé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Et il dit: Les choses qui sont impossibles aux hommes, sont possibles à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Et Pierre dit: Voici, nous avons tout quitté et nous t’avons suivi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Et il leur dit: En vérité, je vous dis, qu’il n’y a personne qui ait quitté maison, ou parents, ou frères, ou femme, ou enfants, pour l’amour du royaume de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'qui ne reçoive beaucoup plus en ce temps-ci, et, dans le siècle qui vient, la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Et prenant à lui les douze, il leur dit: Voici, nous montons à Jérusalem, et toutes les choses qui sont écrites par les prophètes touchant le fils de l’homme seront accomplies:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'car il sera livré aux nations; on se moquera de lui, et on l’injuriera, et on crachera contre lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'et après qu’ils l’auront fouetté, ils le mettront à mort; et le troisième jour il ressuscitera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Et ils ne comprirent rien de ces choses; et cette parole leur était cachée, et ils ne comprirent pas les choses qui étaient dites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Et il arriva, lorsqu’il fut venu dans le voisinage de Jéricho, qu’un aveugle était assis sur le bord du chemin et mendiait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Et entendant la foule qui passait, il demanda ce que c’était.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Et on lui rapporta que Jésus le Nazaréen passait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Et il cria, disant: Jésus, Fils de David, aie pitié de moi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Et ceux qui allaient devant le reprirent afin qu’il se taise; mais il criait d’autant plus fort: Fils de David! aie pitié de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Et Jésus, s’étant arrêté, ordonna qu’on le lui amène; et comme il s’approchait, il l’interrogea, [disant]:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Que veux-tu que je te fasse? Et il dit: Seigneur, que je recouvre la vue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Et Jésus lui dit: Recouvre la vue, ta foi t’a guéri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Et à l’instant il recouvra la vue et le suivit, glorifiant Dieu. Et tout le peuple, voyant cela, donna louange à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Et il entra dans Jéricho, et traversa [la ville].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Et voici, un homme, appelé du nom de Zachée: et il était chef de publicains, et il était riche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'et il cherchait à voir Jésus, quel il était; et il ne pouvait, à cause de la foule, car il était petit de taille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Et, courant en avant, il monta sur un sycomore pour le voir; car il allait passer là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Et quand il fut venu à cet endroit, Jésus, regardant, le vit, et lui dit: Zachée, descends vite; car il faut que je demeure aujourd’hui dans ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Et il descendit à la hâte, et le reçut avec joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Et voyant cela, tous murmuraient, disant qu’il était entré chez un pécheur pour y loger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Et Zachée, se tenant là, dit au Seigneur: Voici, Seigneur, je donne la moitié de mes biens aux pauvres; et si j’ai fait tort à quelqu’un par une fausse accusation, je lui rends le quadruple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Et Jésus lui dit: Aujourd’hui [le] salut est venu à cette maison, vu que lui aussi est fils d’Abraham;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'car le fils de l’homme est venu chercher et sauver ce qui était perdu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Et comme ils entendaient ces choses, il ajouta et [leur] dit une parabole, parce qu’il était près de Jérusalem, et qu’ils pensaient que le royaume de Dieu allait immédiatement paraître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Il dit donc: Un homme noble s’en alla dans un pays éloigné, pour recevoir un royaume et revenir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Et ayant appelé dix de ses propres esclaves, il leur donna dix mines, et leur dit: Trafiquez jusqu’à ce que je vienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Or ses concitoyens le haïssaient; et ils envoyèrent après lui une ambassade, disant: Nous ne voulons pas que celui-ci règne sur nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Et il arriva, à son retour, après qu’il eut reçu le royaume, qu’il commanda d’appeler auprès de lui ces esclaves auxquels il avait donné l’argent, afin de savoir combien chacun aurait gagné par son trafic.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Et le premier se présenta, disant: Maître, ta mine a produit dix mines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Et il lui dit: Bien, bon esclave, parce que tu as été fidèle en ce qui est très peu de chose, aie autorité sur dix villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Et le second vint, disant: Maître, ta mine a produit cinq mines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Et il dit aussi à celui-ci: Et toi, sois [établi] sur cinq villes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Et un autre vint, disant: Maître, voici ta mine, que j’ai gardée déposée dans un linge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'car je t’ai craint, parce que tu es un homme sévère: tu prends ce que tu n’as pas mis, et tu moissonnes ce que tu n’as pas semé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Il lui dit: Je te jugerai par ta propre parole, méchant esclave: tu savais que moi je suis un homme sévère, prenant ce que je n’ai pas mis et moissonnant ce que je n’ai pas semé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'et pourquoi n’as-tu pas mis mon argent à la banque, et quand je serais venu je l’aurais retiré avec l’intérêt?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Et il dit à ceux qui étaient présents: Ôtez -lui la mine et donnez-la à celui qui a les dix mines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, '– Et ils lui dirent: Seigneur, il a dix mines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, '– Car je vous dis qu’à quiconque a, il sera donné; et à celui qui n’a pas, cela même qu’il a lui sera ôté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Mais ceux-là, mes ennemis, qui n’ont pas voulu que je règne sur eux, amenez-les ici et tuez-les devant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Et ayant dit ces choses, il allait devant eux, montant à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Et il arriva, comme il approchait de Bethphagé et de Béthanie, vers la montagne appelée des Oliviers, qu’il envoya deux de ses disciples,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'disant: Allez au village qui est vis-à-vis; et y étant entrés, vous trouverez un ânon attaché, sur lequel jamais aucun homme ne s’assit; détachez-le, et amenez-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Et si quelqu’un vous demande pourquoi vous le détachez, vous lui direz ainsi: Le Seigneur en a besoin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Et ceux qui étaient envoyés, s’en allant, trouvèrent [tout] comme il le leur avait dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Et comme ils détachaient l’ânon, les maîtres de celui-ci leur dirent: Pourquoi détachez-vous l’ânon?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Et ils dirent: Parce que le Seigneur en a besoin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Et ils l’amenèrent à Jésus; et ayant jeté leurs vêtements sur l’ânon, ils mirent Jésus dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Et comme il allait son chemin, ils étendaient leurs vêtements sur le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Et comme il approchait déjà, à la descente de la montagne des Oliviers, toute la multitude des disciples, se réjouissant, se mit à louer Dieu à haute voix pour tous les miracles qu’ils avaient vus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'disant: Béni soit le roi qui vient au nom du ✶Seigneur! Paix au ciel, et gloire dans les lieux très hauts!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Et quelques-uns des pharisiens lui dirent du milieu de la foule: Maître, reprends tes disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Et répondant, il leur dit: Je vous dis que si ceux-ci se taisent, les pierres crieront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Et quand il fut proche, voyant la ville, il pleura sur elle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'disant: Si tu avais connu, toi aussi, au moins en cette tienne journée, les choses qui appartiennent à ta paix! mais maintenant elles sont cachées devant tes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Car des jours viendront sur toi, où tes ennemis t’entoureront de tranchées, et t’environneront, et te serreront de tous côtés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'et te renverseront par terre, toi et tes enfants au-dedans de toi; et ils ne laisseront pas en toi pierre sur pierre, parce que tu n’as point connu le temps de ta visitation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Et il entra au temple, et se mit à chasser dehors ceux qui y vendaient et qui y achetaient,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'leur disant: Il est écrit: « Ma maison est une maison de prière »; mais vous, vous en avez fait une caverne de voleurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Et il enseignait tous les jours dans le temple; et les principaux sacrificateurs et les scribes, et les principaux du peuple, tâchaient de le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Et ils ne trouvaient rien qu’ils puissent faire; car tout le peuple se tenait suspendu à ses lèvres pour l’entendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Et il arriva, l’un de ces jours, comme il enseignait le peuple dans le temple et évangélisait, que les principaux sacrificateurs et les scribes survinrent avec les anciens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'Et ils lui parlèrent, disant: Dis-nous par quelle autorité tu fais ces choses, ou qui est celui qui t’a donné cette autorité?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Et répondant, il leur dit: Je vous demanderai, moi aussi, une chose, et dites-moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Le baptême de Jean était-il du ciel, ou des hommes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Et ils raisonnèrent entre eux, disant: Si nous disons: Du ciel, il dira: Pourquoi ne l’avez-vous pas cru?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Et si nous disons: Des hommes, tout le peuple nous lapidera, car il est persuadé que Jean était un prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Et ils répondirent qu’ils ne savaient pas d’où [il était].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Et Jésus leur dit: Moi non plus, je ne vous dis pas par quelle autorité je fais ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Et il se mit à dire au peuple cette parabole: Un homme planta une vigne, et la loua à des cultivateurs, et s’en alla hors du pays pour longtemps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Et en la saison, il envoya un esclave aux cultivateurs, afin qu’ils lui donnent du fruit de la vigne; mais les cultivateurs, l’ayant battu, le renvoyèrent à vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Et il envoya encore un autre esclave; mais l’ayant battu lui aussi, et l’ayant traité ignominieusement, ils le renvoyèrent à vide.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Et il en envoya encore un troisième; mais ils blessèrent aussi celui-ci, et le jetèrent dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Et le maître de la vigne dit: Que ferai-je? J’enverrai mon fils bien-aimé; peut-être que, quand ils verront celui-ci, ils le respecteront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Mais quand les cultivateurs le virent, ils raisonnèrent entre eux, disant: Celui-ci est l’héritier, tuons-le, afin que l’héritage soit à nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Et l’ayant jeté hors de la vigne, ils le tuèrent. Que leur fera donc le maître de la vigne?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Il viendra et fera périr ces cultivateurs, et donnera la vigne à d’autres. Et l’ayant entendu, ils dirent: Qu’ainsi n’advienne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Et lui, les regardant, dit: Qu’est-ce donc que ceci qui est écrit: « La pierre que ceux qui bâtissaient ont rejetée, celle-là est devenue la maîtresse pierre du coin »?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Quiconque tombera sur cette pierre, sera brisé; mais celui sur qui elle tombera, elle le broiera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Et les principaux sacrificateurs et les scribes cherchèrent, en cette heure même, à mettre les mains sur lui; et ils craignaient le peuple, car ils connurent qu’il avait dit cette parabole contre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Et l’observant, ils envoyèrent des agents secrets, qui feignaient d’être justes, pour le surprendre en [quelque] parole, de manière à le livrer au magistrat et au pouvoir du gouverneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Et ils l’interrogèrent, disant: Maître, nous savons que tu dis et que tu enseignes justement, et que tu n’as point égard à l’apparence des personnes, mais que tu enseignes la voie de Dieu avec vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Nous est-il permis de payer le tribut à César, ou non?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Et s’apercevant de leur perfidie, il leur dit: Pourquoi me tentez-vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Montrez-moi un denier; de qui a-t-il l’image et l’inscription? Et répondant, ils dirent: De César.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Et il leur dit: Rendez donc les choses de César à César, et les choses de Dieu à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Et ils ne pouvaient le surprendre dans ses paroles devant le peuple; et étonnés de sa réponse, ils se turent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Et quelques-uns des sadducéens, qui nient qu’il y ait une résurrection, s’approchèrent, et l’interrogèrent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'disant: Maître, Moïse nous a écrit, que si le frère de quelqu’un meurt, ayant une femme, et qu’il meure sans enfants, son frère prenne la femme et suscite de la postérité à son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Il y avait donc sept frères; et le premier, ayant pris une femme, mourut sans enfants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'et le second [prit la femme, et celui-ci aussi mourut sans enfants];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'et le troisième la prit, et de même aussi les sept: ils ne laissèrent pas d’enfants et moururent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'et après eux tous la femme aussi mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Dans la résurrection donc, duquel d’entre eux sera-t-elle la femme, car les sept l’ont eue pour femme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Et Jésus leur dit: Les fils de ce siècle se marient et sont donnés en mariage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'mais ceux qui seront estimés dignes d’avoir part à ce siècle-là et à la résurrection d’entre les morts, ne se marient ni ne sont donnés en mariage,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'car aussi ils ne peuvent plus mourir; car ils sont semblables aux anges, et ils sont fils de Dieu, étant fils de la résurrection.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Or que les morts ressuscitent, Moïse même l’a montré, au [titre]: “Du buisson”, quand il appelle le ✶Seigneur: le Dieu d’Abraham, et le Dieu d’Isaac, et le Dieu de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Or il n’est pas le Dieu des morts, mais des vivants; car pour lui tous vivent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Et quelques-uns des scribes, répondant, dirent: Maître, tu as bien dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Et ils n’osèrent plus l’interroger sur rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Et il leur dit: Comment dit-on que le Christ est fils de David?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Et David lui-même dit, dans le livre des Psaumes: « Le ✶Seigneur a dit à mon seigneur: Assieds-toi à ma droite,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'jusqu’à ce que je mette tes ennemis pour marchepied de tes pieds ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'David donc l’appelle seigneur; et comment est-il son fils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Et comme tout le peuple écoutait, il dit à ses disciples:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Soyez en garde contre les scribes, qui se plaisent à se promener en longues robes, et qui aiment les salutations dans les places publiques, et les premiers sièges dans les synagogues, et les premières places dans les repas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'qui dévorent les maisons des veuves, et pour prétexte font de longues prières; – ceux-ci recevront une sentence plus sévère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Et comme il regardait, il vit des riches qui jetaient leurs dons au trésor.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Et il vit aussi une pauvre veuve qui y jetait deux pites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Et il dit: En vérité, je vous dis que cette pauvre veuve a jeté plus que tous [les autres];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'car tous ceux-ci ont jeté aux offrandes [de Dieu] de leur superflu, mais celle-ci y a jeté de sa pénurie, tout ce qu’elle avait pour vivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Et comme quelques-uns parlaient du temple [et disaient] qu’il était orné de belles pierres et de dons, il dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Quant à ces choses que vous regardez, les jours viendront où il ne sera laissé pierre sur pierre qui ne soit jetée à bas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Et ils l’interrogèrent, disant: Maître, quand donc ces choses auront-elles lieu, et quel sera le signe quand ces choses devront arriver?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Et il dit: Prenez garde que vous ne soyez séduits; car plusieurs viendront en mon nom, disant: C’est moi, et le temps est proche; n’allez point après eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Et quand vous entendrez parler de guerres et de séditions, ne vous épouvantez pas; car il faut que ces choses arrivent premièrement; mais la fin ne sera pas tout aussitôt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Alors il leur dit: Nation s’élèvera contre nation, et royaume contre royaume;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'et il y aura de grands tremblements de terre en divers lieux, et des famines, et des pestes; et il y aura des sujets d’épouvantement et de grands signes du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Mais, avant toutes ces choses, ils mettront les mains sur vous, et vous persécuteront, vous livrant aux synagogues et [vous mettant] en prison; et vous serez menés devant les rois et les gouverneurs à cause de mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Et cela se tournera pour vous en témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Mettez donc dans vos cœurs de ne pas vous préoccuper à l’avance de votre défense,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'car moi je vous donnerai une bouche et une sagesse, à laquelle tous vos adversaires ne pourront répondre ou résister.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Et vous serez aussi livrés par des parents et par des frères, et par des proches et par des amis, et on fera mourir [quelques-uns] d’entre vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'et vous serez haïs de tous, à cause de mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Et pas un cheveu de votre tête ne périra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Possédez vos âmes par votre patience.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Et quand vous verrez Jérusalem environnée d’armées, sachez alors que sa désolation est proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Alors, que ceux qui sont en Judée s’enfuient dans les montagnes; et que ceux qui sont au milieu de Jérusalem s’en retirent; et que ceux qui sont dans les campagnes n’entrent pas en elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Car ce sont là des jours de vengeance; afin que toutes les choses qui sont écrites soient accomplies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Mais malheur à celles qui sont enceintes et à celles qui allaitent en ces jours-là! car il y aura une grande détresse sur le pays, et de la colère contre ce peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Et ils tomberont sous le tranchant de l’épée, et seront menés captifs parmi toutes les nations; et Jérusalem sera foulée aux pieds par les nations jusqu’à ce que les temps des nations soient accomplis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Et il y aura des signes dans le soleil et la lune et les étoiles, et sur la terre une angoisse des nations en perplexité devant le grand bruit de la mer et des flots,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'les hommes rendant l’âme de peur et à cause de l’attente des choses qui viennent sur la terre habitée, car les puissances des cieux seront ébranlées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Et alors on verra le fils de l’homme venant sur une nuée avec puissance et une grande gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Et quand ces choses commenceront à arriver, regardez en haut, et levez vos têtes, parce que votre rédemption approche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Et il leur dit une parabole: Voyez le figuier et tous les arbres:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'quand ils ont déjà commencé à pousser, vous connaissez par vous-mêmes, en les voyant, que l’été est déjà proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'De même aussi vous, quand vous verrez arriver ces choses, sachez que le royaume de Dieu est proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'En vérité, je vous dis que cette génération ne passera point que tout ne soit arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Et prenez garde à vous-mêmes, de peur que vos cœurs ne soient appesantis par la gourmandise et l’ivrognerie, et par les soucis de la vie, et que ce jour-là ne vous surprenne inopinément;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'car il viendra comme un filet sur tous ceux qui habitent sur la face de toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Veillez donc, priant en tout temps, afin que vous soyez estimés dignes d’échapper à toutes ces choses qui doivent arriver, et de vous tenir devant le fils de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Et il passait les jours dans le temple à enseigner; et les nuits il sortait et demeurait dans la montagne qui est appelée des Oliviers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Et tout le peuple, dès le point du jour, venait à lui dans le temple, pour l’entendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Or la fête des pains sans levain, qui est appelée la Pâque, approchait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Et les principaux sacrificateurs et les scribes cherchaient comment ils pourraient le faire mourir; car ils craignaient le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Et Satan entra dans Judas, surnommé Iscariote, qui était du nombre des douze;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'et il s’en alla et parla avec les principaux sacrificateurs et [les] capitaines sur la manière dont il le leur livrerait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Et ils se réjouirent, et convinrent de lui donner de l’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Et il s’engagea; et il cherchait une bonne occasion pour le leur livrer sans que la foule y soit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Et le jour des pains sans levain, dans lequel il fallait sacrifier la pâque, arriva.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Et il envoya Pierre et Jean, disant: Allez, et apprêtez-nous la pâque, afin que nous la mangions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Et ils lui dirent: Où veux-tu que nous l’apprêtions?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Et il leur dit: Voici, quand vous entrerez dans la ville, un homme portant une cruche d’eau viendra à votre rencontre; suivez-le dans la maison où il entrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'Et vous direz au maître de la maison: Le maître te dit: Où est le logis où je mangerai la pâque avec mes disciples?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Et lui vous montrera une grande chambre garnie; apprêtez là [la pâque].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Et s’en étant allés, ils trouvèrent [tout] comme il leur avait dit; et ils apprêtèrent la pâque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Et quand l’heure fut venue, il se mit à table, et les [douze] apôtres avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Et il leur dit: J’ai fort désiré de manger cette pâque avec vous, avant que je souffre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'car je vous dis que je n’en mangerai plus jusqu’à ce qu’elle soit accomplie dans le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Et ayant reçu une coupe, il rendit grâces et dit: Prenez ceci et distribuez-le entre vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'car je vous dis que je ne boirai plus du fruit de la vigne, jusqu’à ce que le royaume de Dieu soit venu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Et ayant pris un pain, [et] ayant rendu grâces, il le rompit, et le leur donna, en disant: Ceci est mon corps, qui est donné pour vous; faites ceci en mémoire de moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, '– de même la coupe aussi, après le souper, en disant: Cette coupe est la nouvelle alliance en mon sang, qui est versé pour vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'mais voici, la main de celui qui me livre est avec moi à table.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Et le fils de l’homme s’en va bien, selon ce qui est déterminé; mais malheur à cet homme par qui il est livré!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Et ils se mirent à s’entre-demander l’un à l’autre, qui donc serait celui d’entre eux qui allait faire cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Et il arriva aussi une contestation entre eux [pour savoir] lequel d’entre eux serait estimé le plus grand.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Et il leur dit: Les rois des nations les dominent, et ceux qui exercent l’autorité sur elles sont appelés bienfaiteurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'mais il n’en sera pas ainsi de vous; mais que le plus grand parmi vous soit comme le plus jeune, et celui qui conduit comme celui qui sert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Car lequel est le plus grand, celui qui est à table ou celui qui sert? N’est-ce pas celui qui est à table? Or moi, je suis au milieu de vous comme celui qui sert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Mais vous, vous êtes ceux qui avez persévéré avec moi dans mes tentations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'Et moi, je vous confère un royaume comme mon Père m’en a conféré un,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'afin que vous mangiez et que vous buviez à ma table dans mon royaume; et que vous soyez assis sur des trônes, jugeant les douze tribus d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Et le Seigneur dit: Simon, Simon, voici, Satan a demandé à vous avoir pour vous cribler comme le blé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'mais moi, j’ai prié pour toi, afin que ta foi ne défaille pas; et toi, quand une fois tu seras revenu, fortifie tes frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, '– Et il lui dit: Seigneur, avec toi, je suis prêt à aller et en prison et à la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, '– Et il dit: Pierre, je te dis: le coq ne chantera point aujourd’hui, que premièrement tu n’aies nié trois fois de me connaître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Et il leur dit: Quand je vous ai envoyés sans bourse, sans sac et sans sandales, avez-vous manqué de quelque chose? Et ils dirent: De rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Il leur dit donc: Mais maintenant, que celui qui a une bourse la prenne, et de même [celui qui a] un sac, et que celui qui n’a pas [d’épée] vende son vêtement et achète une épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Car je vous dis, qu’il faut encore que ceci qui est écrit, soit accompli en moi: « Et il a été compté parmi les iniques ». Car aussi les choses qui me concernent vont avoir leur fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Et ils dirent: Seigneur, voici ici deux épées. Et il leur dit: C’est assez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Et sortant, il s’en alla, selon sa coutume, à la montagne des Oliviers, et les disciples aussi le suivirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Et quand il fut en ce lieu-là, il leur dit: Priez que vous n’entriez pas en tentation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Et il s’éloigna d’eux lui-même environ d’un jet de pierre, et s’étant mis à genoux, il priait,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'disant: Père, si tu voulais faire passer cette coupe loin de moi! Toutefois, que ce ne soit pas ma volonté mais la tienne qui soit faite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Et un ange du ciel lui apparut, le fortifiant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Et étant dans [l’angoisse du] combat, il priait plus instamment; et sa sueur devint comme des grumeaux de sang découlant sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Et s’étant levé de sa prière, il vint vers les disciples, qu’il trouva endormis de tristesse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'et il leur dit: Pourquoi dormez-vous? Levez-vous, et priez afin que vous n’entriez pas en tentation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Comme il parlait encore, voici une foule, et celui qui avait nom Judas, l’un des douze, les précédait; et il s’approcha de Jésus, pour l’embrasser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Et Jésus lui dit: Judas, tu livres le fils de l’homme par un baiser?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Et ceux qui étaient autour de lui, voyant ce qui allait arriver, lui dirent: Seigneur, frapperons-nous de l’épée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Et l’un d’entre eux frappa l’esclave du souverain sacrificateur et lui emporta l’oreille droite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Mais Jésus, répondant, dit: Laissez [faire] jusqu’ici; et lui ayant touché l’oreille, il le guérit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Et Jésus dit aux principaux sacrificateurs et aux capitaines du temple et aux anciens qui étaient venus contre lui: Êtes-vous sortis comme contre un brigand avec des épées et des bâtons?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Lorsque j’étais tous les jours avec vous, dans le temple, vous n’avez pas étendu vos mains contre moi; mais c’est ici votre heure, et le pouvoir des ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Et se saisissant de lui, ils l’emmenèrent, et le conduisirent dans la maison du souverain sacrificateur. Or Pierre suivait de loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Et lorsqu’ils eurent allumé un feu au milieu de la cour et qu’ils se furent assis ensemble, Pierre s’assit au milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Et une servante, le voyant assis auprès de la lumière, et l’ayant regardé fixement, dit: Celui-ci aussi était avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Mais il le renia, disant: Femme, je ne le connais pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Et peu après, un autre le voyant, dit: Et toi, tu es de ces gens-là. Mais Pierre dit: Ô homme, je n’en suis point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Et environ une heure après, un autre affirma, disant: En vérité, celui-ci aussi était avec lui; car aussi il est Galiléen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Et Pierre dit: Ô homme, je ne sais ce que tu dis. Et à l’instant, comme il parlait encore, le coq chanta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Et le Seigneur, se tournant, regarda Pierre; et Pierre se ressouvint de la parole du Seigneur, comme il lui avait dit: Avant que le coq chante, tu me renieras trois fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Et Pierre, étant sorti dehors, pleura amèrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Et les hommes qui tenaient Jésus se moquaient de lui et le frappaient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'et lui couvrant [les yeux], ils l’interrogeaient, disant: Prophétise; qui est celui qui t’a frappé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Et ils disaient plusieurs autres choses contre lui, en l’outrageant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Et quand le jour fut venu, le corps des anciens du peuple, principaux sacrificateurs et scribes, s’assembla; et ils l’amenèrent dans leur sanhédrin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'disant: Si toi, tu es le Christ, dis-le-nous. Et il leur dit: Si je vous le disais, vous ne le croiriez point;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'et si je vous interroge, vous ne me répondrez point [ou ne me laisserez point aller].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Mais désormais le fils de l’homme sera assis à la droite de la puissance de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Et ils dirent tous: Toi, tu es donc le Fils de Dieu? Et il leur dit: Vous dites vous-mêmes que je le suis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Et ils dirent: Qu’avons-nous encore besoin de témoignage? Car nous-mêmes nous l’avons entendu de sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Et se levant tous ensemble, ils le menèrent à Pilate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Et ils se mirent à l’accuser, disant: Nous avons trouvé cet homme pervertissant notre nation et défendant de donner le tribut à César, se disant lui-même être le Christ, un roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Et Pilate l’interrogea, disant: Toi, tu es le roi des Juifs? Et répondant, il lui dit: Tu le dis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Et Pilate dit aux principaux sacrificateurs et aux foules: Je ne trouve aucun crime en cet homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Mais ils insistaient, disant: Il soulève le peuple, enseignant par toute la Judée, ayant commencé depuis la Galilée jusqu’ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Et Pilate, ayant entendu parler de la Galilée, demanda si l’homme était Galiléen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Et ayant appris qu’il était de la juridiction d’Hérode, il le renvoya à Hérode qui, en ces jours-là, était lui-même aussi à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Et Hérode, voyant Jésus, se réjouit fort; car il y avait longtemps qu’il désirait de le voir, parce qu’il avait entendu dire plusieurs choses de lui; et il espérait voir quelque miracle opéré par lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Et il l’interrogea longuement; mais il ne lui répondit rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Et les principaux sacrificateurs et les scribes se tinrent là, l’accusant avec véhémence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Et Hérode, avec ses troupes, l’ayant traité avec mépris et s’étant moqué de lui, le revêtit d’un vêtement éclatant et le renvoya à Pilate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Et Pilate et Hérode devinrent amis entre eux ce même jour; car auparavant ils étaient en inimitié l’un avec l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Et Pilate, ayant assemblé les principaux sacrificateurs, et les chefs, et le peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'leur dit: Vous m’avez amené cet homme comme détournant le peuple, et voici, l’ayant examiné devant vous, moi je n’ai trouvé aucun crime dans cet homme quant aux choses dont vous l’accusez,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'ni Hérode non plus, car je vous ai renvoyés à lui; et voici, rien n’a été fait par lui qui soit digne de mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'L’ayant donc châtié, je le relâcherai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Or il était obligé de leur relâcher quelqu’un à la fête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Et toute la multitude s’écria ensemble, disant: Ôte celui-ci, et relâche-nous Barabbas');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, '(qui avait été jeté en prison pour une sédition qui avait eu lieu dans la ville, et pour meurtre).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilate donc s’adressa de nouveau à eux, désirant relâcher Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Mais ils s’écriaient, disant: Crucifie, crucifie-le!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Et il leur dit pour la troisième fois: Mais quel mal celui-ci a-t-il fait? Je n’ai rien trouvé en lui qui soit digne de mort; l’ayant donc châtié, je le relâcherai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Mais ils insistaient à grands cris, demandant qu’il soit crucifié. Et leurs cris et ceux des principaux sacrificateurs eurent le dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Et Pilate prononça que ce qu’ils demandaient soit fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Et il relâcha celui qui, pour sédition et pour meurtre, avait été jeté en prison, lequel ils demandaient; et il livra Jésus à leur volonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Et comme ils l’emmenaient, ils prirent un certain Simon, Cyrénéen, qui venait des champs, et le chargèrent de la croix, pour la porter après Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Et une grande multitude du peuple et de femmes qui se frappaient la poitrine et le pleuraient, le suivait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Mais Jésus, se tournant vers elles, dit: Filles de Jérusalem, ne pleurez pas sur moi; mais pleurez sur vous-mêmes et sur vos enfants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'car voici, des jours viennent, dans lesquels on dira: Bienheureuses les stériles, et les ventres qui n’ont pas enfanté, et les mamelles qui n’ont pas nourri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Alors ils se mettront à dire aux montagnes: Tombez sur nous; et aux coteaux: Couvrez-nous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'car s’ils font ces choses au bois vert, que sera-t-il fait au bois sec?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Et deux autres aussi, qui étaient des malfaiteurs, furent menés avec lui, pour être mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Et quand ils furent venus au lieu appelé Crâne, ils le crucifièrent là, et les malfaiteurs, l’un à la droite, l’autre à la gauche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Et Jésus dit: Père, pardonne-leur, car ils ne savent ce qu’ils font. Et ayant fait le partage de ses vêtements, ils tirèrent au sort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Et le peuple se tenait là, regardant; et les gouverneurs aussi se raillaient de lui [avec eux], disant: Il a sauvé les autres; qu’il se sauve lui-même, si lui est le Christ, l’élu de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Et les soldats aussi se moquaient de lui, s’approchant, et lui présentant du vinaigre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'et disant: Si toi, tu es le roi des Juifs, sauve-toi toi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Et il y avait aussi au-dessus de lui un écriteau en lettres grecques, romaines, et hébraïques: Celui-ci est le roi des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Et l’un des malfaiteurs qui étaient pendus l’injuriait, disant: N’es-tu pas le Christ, toi? Sauve-toi toi-même, et nous aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Mais l’autre, répondant, le reprit, disant: Et tu ne crains pas Dieu, toi, car tu es sous le même jugement?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Et pour nous, nous y sommes justement; car nous recevons ce que méritent les choses que nous avons commises: mais celui-ci n’a rien fait qui ne dût se faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Et il disait à Jésus: Souviens-toi de moi, Seigneur, quand tu viendras dans ton royaume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Et Jésus lui dit: En vérité, je te dis: Aujourd’hui tu seras avec moi dans le paradis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Or il était environ la sixième heure; et il y eut des ténèbres sur tout le pays jusqu’à la neuvième heure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'et le soleil fut obscurci, et le voile du temple se déchira par le milieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Et Jésus, criant à haute voix, dit: Père! entre tes mains je remets mon esprit. Et ayant dit cela, il expira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Et le centurion, voyant ce qui était arrivé, glorifia Dieu, disant: En vérité, cet homme était juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Et toutes les foules qui s’étaient assemblées à ce spectacle, ayant vu les choses qui étaient arrivées, s’en retournaient, frappant leurs poitrines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Et tous ceux de sa connaissance, et des femmes qui l’avaient accompagné depuis la Galilée, se tenaient loin, regardant ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Et voici, un homme nommé Joseph, qui était conseiller, homme de bien et juste');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '(celui-ci ne s’était pas joint à leur conseil et à leur action), qui était d’Arimathée, ville des Juifs, et qui attendait, lui aussi, le royaume de Dieu ...;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'celui-ci, étant venu à Pilate, lui demanda le corps de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Et l’ayant descendu, il l’enveloppa d’un linceul, et le mit dans un sépulcre taillé dans le roc, où personne n’avait jamais été déposé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Et c’était le jour de la Préparation et le crépuscule du sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Et des femmes qui l’avaient accompagné depuis la Galilée, ayant suivi, regardèrent le sépulcre et comment son corps y avait été déposé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Et s’en étant retournées, elles préparèrent des aromates et des parfums; et, le sabbat, elles se tinrent en repos, selon le commandement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Or le premier jour de la semaine, de très grand matin, elles vinrent au sépulcre, apportant les aromates qu’elles avaient préparés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Et elles trouvèrent la pierre roulée de devant le sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'Et étant entrées, elles ne trouvèrent pas le corps du seigneur Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Et il arriva, comme elles étaient en grande perplexité à ce sujet, que voici, deux hommes se trouvèrent avec elles, en vêtements éclatants de lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Et comme elles étaient épouvantées et baissaient le visage contre terre, ils leur dirent: Pourquoi cherchez-vous parmi les morts celui qui est vivant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Il n’est point ici, mais il est ressuscité. Souvenez-vous comment il vous parla quand il était encore en Galilée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'disant: Il faut que le fils de l’homme soit livré entre les mains des pécheurs, et qu’il soit crucifié, et qu’il ressuscite le troisième jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Et elles se souvinrent de ses paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'Et, laissant le sépulcre, elles s’en retournèrent et rapportèrent toutes ces choses aux onze et à tous les autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Or ce furent Marie de Magdala, et Jeanne, et Marie, la [mère] de Jacques, et les autres femmes avec elles, qui dirent ces choses aux apôtres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Et leurs paroles semblèrent à leurs yeux comme des contes, et ils ne les crurent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Mais Pierre, s’étant levé, courut au sépulcre; et, se baissant, il voit les linges là tout seuls; et il s’en alla chez lui, s’étonnant de ce qui était arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Et voici, deux d’entre eux étaient ce même jour en chemin, pour aller à un village dont le nom était Emmaüs, éloigné de Jérusalem de 60 stades.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'Et ils s’entretenaient ensemble de toutes ces choses qui étaient arrivées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Et il arriva, comme ils s’entretenaient et raisonnaient ensemble, que Jésus lui-même, s’étant approché, se mit à marcher avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Mais leurs yeux étaient retenus, de manière qu’ils ne le reconnurent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Et il leur dit: Quels sont ces discours que vous tenez entre vous en marchant, et vous êtes tristes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Et l’un d’eux, dont le nom était Cléopas, répondant, lui dit: Est-ce que tu séjournes tout seul dans Jérusalem, que tu ne saches pas les choses qui y sont arrivées ces jours-ci?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Et il leur dit: Lesquelles? Et ils lui dirent: Celles touchant Jésus le Nazaréen, qui était un prophète puissant en œuvre et en parole devant Dieu et devant tout le peuple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'et comment les principaux sacrificateurs et nos chefs l’ont livré pour être condamné à mort, et l’ont crucifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Or nous, nous espérions qu’il était celui qui doit délivrer Israël; mais encore, avec tout cela, c’est aujourd’hui le troisième jour depuis que ces choses sont arrivées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Mais aussi quelques femmes d’entre nous nous ont fort étonnés; ayant été de grand matin au sépulcre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'et n’ayant pas trouvé son corps, elles sont venues, disant qu’elles avaient vu aussi une vision d’anges qui disent qu’il est vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Et quelques-uns de ceux qui sont avec nous, sont allés au sépulcre, et ont trouvé [les choses] ainsi que les femmes aussi avaient dit; mais pour lui, ils ne l’ont point vu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Et lui leur dit: Ô gens sans intelligence et lents de cœur à croire toutes les choses que les prophètes ont dites!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Ne fallait-il pas que le Christ souffre ces choses, et qu’il entre dans sa gloire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Et commençant par Moïse et par tous les prophètes, il leur expliquait, dans toutes les écritures, les choses qui le regardent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Et ils approchèrent du village où ils allaient; et lui, il fit comme s’il allait plus loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Et ils le forcèrent, disant: Demeure avec nous, car le soir approche et le jour a baissé. Et il entra pour rester avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Et il arriva que, comme il était à table avec eux, il prit le pain et il bénit; et l’ayant rompu, il le leur distribua.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Et leurs yeux furent ouverts, et ils le reconnurent; mais lui devint invisible [et disparut] de devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Et ils dirent entre eux: Notre cœur ne brûlait-il pas au-dedans de nous, lorsqu’il nous parlait par le chemin, et lorsqu’il nous ouvrait les écritures?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Et se levant à l’heure même, ils s’en retournèrent à Jérusalem, et trouvèrent assemblés les onze et ceux qui étaient avec eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'disant: Le Seigneur est réellement ressuscité, et il est apparu à Simon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Et ils racontèrent les choses qui étaient arrivées en chemin, et comment il s’était fait connaître à eux dans la fraction du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Et comme ils disaient ces choses, il se trouva lui-même là au milieu d’eux, et leur dit: Paix vous soit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Et eux, tout effrayés et remplis de crainte, croyaient voir un esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Et il leur dit: Pourquoi êtes-vous troublés, et pourquoi monte-t-il des pensées dans vos cœurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Voyez mes mains et mes pieds; – que c’est moi-même: touchez-moi, et voyez; car un esprit n’a pas de la chair et des os, comme vous voyez que j’ai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Et en disant cela, il leur montra ses mains et ses pieds.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Et comme, de joie, ils ne croyaient pas encore et s’étonnaient, il leur dit: Avez-vous ici quelque chose à manger?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Et ils lui donnèrent un morceau de poisson cuit et [quelque peu] d’un rayon de miel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'et l’ayant pris, il en mangea devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Et il leur dit: Ce sont ici les paroles que je vous disais quand j’étais encore avec vous, qu’il fallait que toutes les choses qui sont écrites de moi dans la loi de Moïse, et dans les prophètes, et dans les psaumes, soient accomplies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Alors il leur ouvrit l’intelligence pour entendre les écritures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Et il leur dit: Il est ainsi écrit; et ainsi il fallait que le Christ souffre, et qu’il ressuscite d’entre les morts le troisième jour,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'et que la repentance et la rémission des péchés soient prêchées en son nom à toutes les nations, en commençant par Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Et vous, vous êtes témoins de ces choses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'et voici, moi, j’envoie sur vous la promesse de mon Père. Mais vous, demeurez dans la ville, jusqu’à ce que vous soyez revêtus de puissance d’en haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Et il les mena dehors jusqu’à Béthanie, et, levant ses mains en haut, il les bénit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Et il arriva qu’en les bénissant, il fut séparé d’eux, et fut élevé dans le ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Et eux, lui ayant rendu hommage, s’en retournèrent à Jérusalem avec une grande joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'Et ils étaient continuellement dans le temple, louant et bénissant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Au commencement était la Parole; et la Parole était auprès de Dieu; et la Parole était Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Elle était au commencement auprès de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Toutes choses furent faites par elle, et sans elle pas une seule chose ne fut faite de ce qui a été fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'En elle était [la] vie, et la vie était la lumière des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Et la lumière luit dans les ténèbres; et les ténèbres ne l’ont pas comprise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Il y eut un homme envoyé de Dieu; son nom était Jean.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Celui-ci vint pour [rendre] témoignage, pour rendre témoignage de la lumière, afin que tous croient par lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Lui n’était pas la lumière, mais pour rendre témoignage de la lumière:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'la vraie lumière était celle, qui, venant dans le monde, éclaire tout homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Il était dans le monde, et le monde fut fait par lui; et le monde ne l’a pas connu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Il vint chez soi; et les siens ne l’ont pas reçu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Mais à tous ceux qui l’ont reçu, il leur a donné le droit d’être enfants de Dieu, [savoir] à ceux qui croient en son nom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'lesquels sont nés, non pas de sang, ni de la volonté de la chair, ni de la volonté de l’homme, mais de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Et la Parole devint chair, et habita au milieu de nous (et nous avons vu sa gloire, une gloire comme d’un fils unique de la part du Père) pleine de grâce et de vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, '– Jean rend témoignage de lui, et a crié, disant: C’était celui-ci duquel je disais: Celui qui vient après moi prend place avant moi; car il était avant moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, '– car, de sa plénitude, nous tous nous avons reçu, et grâce sur grâce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Car la loi a été donnée par Moïse; la grâce et la vérité vinrent par Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Personne ne vit jamais Dieu; le Fils unique, qui est dans le sein du Père, lui, l’a fait connaître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Et c’est ici le témoignage de Jean, lorsque les Juifs envoyèrent de Jérusalem des sacrificateurs et des lévites, pour lui demander: Toi, qui es-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Et il confessa, et ne nia pas, et confessa: Moi, je ne suis pas le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Et ils lui demandèrent: Quoi donc? Es-tu Élie? Et il dit: Je ne le suis pas. Es-tu le prophète? Et il répondit: Non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Ils lui dirent donc: Qui es-tu, afin que nous donnions réponse à ceux qui nous ont envoyés? Que dis-tu de toi-même?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Il dit: Moi, je suis la voix de celui qui crie dans le désert: Faites droit le chemin du ✶Seigneur, comme dit Ésaïe le prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Et ils avaient été envoyés d’entre les pharisiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Et ils l’interrogèrent et lui dirent: Pourquoi donc baptises-tu, si tu n’es ni le Christ, ni Élie, ni le prophète?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Jean leur répondit, disant: Moi, je baptise d’eau; [mais] au milieu de vous il y en a un que vous ne connaissez pas,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'celui qui vient après moi, duquel moi je ne suis pas digne de délier la courroie de la sandale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Ces choses arrivèrent à Béthanie, au-delà du Jourdain, où Jean baptisait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Le lendemain, il voit Jésus venant à lui, et il dit: Voilà l’agneau de Dieu qui ôte le péché du monde!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'C’est de celui-ci que moi, je disais: Après moi vient un homme qui prend place avant moi, car il était avant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Et pour moi, je ne le connaissais pas; mais afin qu’il soit manifesté à Israël, à cause de cela, je suis venu baptiser d’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Et Jean rendit témoignage, disant: J’ai vu l’Esprit descendant du ciel comme une colombe, et il demeura sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Et pour moi, je ne le connaissais pas; mais celui qui m’a envoyé baptiser d’eau, celui-là me dit: Celui sur qui tu verras l’Esprit descendre, et demeurer sur lui, c’est celui-là qui baptise de l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Et moi, j’ai vu et j’ai rendu témoignage que celui-ci est le Fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Le lendemain encore, Jean se tint là, et deux de ses disciples;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'et regardant Jésus qui marchait, il dit: Voilà l’agneau de Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Et les deux disciples l’entendirent parler, et ils suivirent Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Et Jésus se retournant, et voyant qu’ils le suivaient, leur dit: Que cherchez-vous? Et ils lui dirent: Rabbi (ce qui, interprété, signifie maître), où demeures-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Il leur dit: Venez et voyez. Ils allèrent donc, et virent où il demeurait; et ils demeurèrent auprès de lui ce jour-là: c’était environ la dixième heure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'André, le frère de Simon Pierre, était l’un des deux qui avaient entendu parler [de lui] à Jean, et qui l’avaient suivi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Celui-ci trouve d’abord son propre frère Simon, et lui dit: Nous avons trouvé le Messie (ce qui, interprété, est Christ).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Et il le mena à Jésus. Jésus, l’ayant regardé, dit: Tu es Simon, le fils de Jonas; tu seras appelé Céphas (qui est interprété Pierre).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Le lendemain, il voulut s’en aller en Galilée. Et Jésus trouve Philippe, et lui dit: Suis-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Or Philippe était de Bethsaïda, de la ville d’André et de Pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Philippe trouve Nathanaël et lui dit: Nous avons trouvé celui duquel Moïse a écrit dans la loi et duquel les prophètes ont écrit, Jésus, le fils de Joseph, qui est de Nazareth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Et Nathanaël lui dit: Peut-il venir quelque chose de bon de Nazareth? Philippe lui dit: Viens et vois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jésus vit Nathanaël venir vers lui, et il dit de lui: Voici un vrai Israélite, en qui il n’y a pas de fraude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Nathanaël lui dit: D’où me connais-tu? Jésus répondit et lui dit: Avant que Philippe t’ait appelé, quand tu étais sous le figuier, je te voyais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Nathanaël répondit et lui dit: Rabbi, tu es le Fils de Dieu; tu es le roi d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jésus répondit et lui dit: Parce que je t’ai dit que je te voyais sous le figuier, tu crois? tu verras de plus grandes choses que celles-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Et il lui dit: En vérité, en vérité, je vous dis: Désormais vous verrez le ciel ouvert, et les anges de Dieu montant et descendant sur le fils de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Et le troisième jour, il y eut une noce à Cana de Galilée, et la mère de Jésus était là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Et Jésus fut aussi convié à la noce, ainsi que ses disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Et le vin étant venu à manquer, la mère de Jésus lui dit: Ils n’ont pas de vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jésus lui dit: Qu’y a-t-il entre moi et toi, femme? Mon heure n’est pas encore venue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Sa mère dit aux serviteurs: Faites tout ce qu’il vous dira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Or il y avait là six vaisseaux de pierre, pour tenir de l’eau, placés là selon [l’usage de] la purification des Juifs, pouvant recevoir chacun deux ou trois mesures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jésus leur dit: Emplissez d’eau les vaisseaux. Et ils les emplirent jusqu’au haut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Et il leur dit: Puisez maintenant, et portez-en au maître d’hôtel. Et ils lui en portèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Mais lorsque le maître d’hôtel eut goûté l’eau qui était devenue du vin, et qu’il ne savait point d’où celui-ci venait (mais les serviteurs qui avaient puisé l’eau le savaient), le maître d’hôtel appelle l’époux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'et lui dit: Tout homme sert le bon vin le premier, et puis le moindre, après qu’on a bien bu; toi, tu as gardé le bon vin jusqu’à maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Jésus fit ce commencement de [ses] miracles à Cana de Galilée, et il manifesta sa gloire; et ses disciples crurent en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Après cela, il descendit à Capernaüm, lui et sa mère et ses frères et ses disciples; et ils y demeurèrent peu de jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Et la Pâque des Juifs était proche, et Jésus monta à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Et il trouva dans le temple les vendeurs de bœufs et de brebis et de colombes, et les changeurs qui y étaient assis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Et ayant fait un fouet de cordes, il les chassa tous hors du temple, et les brebis et les bœufs; et il répandit la monnaie des changeurs et renversa les tables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Et il dit à ceux qui vendaient les colombes: Ôtez ces choses d’ici; ne faites pas de la maison de mon Père une maison de trafic.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, '[Et] ses disciples se souvinrent qu’il est écrit: « Le zèle de ta maison me dévore ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Les Juifs donc répondirent et lui dirent: Quel miracle nous montres-tu, que tu fasses ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jésus répondit et leur dit: Détruisez ce temple, et en trois jours je le relèverai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Les Juifs donc dirent: On a été 46 ans à bâtir ce temple, et toi, tu le relèveras en trois jours!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Mais lui parlait du temple de son corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Lors donc qu’il fut ressuscité d’entre les morts, ses disciples se souvinrent qu’il avait dit cela; et ils crurent à l’écriture, et à la parole que Jésus avait dite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Et comme il était à Jérusalem, à la Pâque, pendant la fête, plusieurs crurent en son nom, contemplant les miracles qu’il faisait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Mais Jésus lui-même ne se fiait pas à eux, parce qu’il connaissait tous [les hommes],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'et qu’il n’avait pas besoin que quelqu’un rende témoignage au sujet de l’homme; car lui-même connaissait ce qui était dans l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Mais il y avait un homme d’entre les pharisiens, dont le nom était Nicodème, qui était un chef des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Celui-ci vint à lui de nuit, et lui dit: Rabbi, nous savons que tu es un docteur venu de Dieu; car personne ne peut faire ces miracles que toi tu fais, si Dieu n’est avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jésus répondit et lui dit: En vérité, en vérité, je te dis: Si quelqu’un n’est né de nouveau, il ne peut voir le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nicodème lui dit: Comment un homme peut-il naître quand il est vieux? Peut-il entrer une seconde fois dans le sein de sa mère et naître?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jésus répondit: En vérité, en vérité, je te dis: Si quelqu’un n’est né d’eau et de l’Esprit, il ne peut entrer dans le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Ce qui est né de la chair est chair; et ce qui est né de l’Esprit est esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Ne t’étonne pas de ce que je t’ai dit: Il vous faut être nés de nouveau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Le vent souffle où il veut, et tu en entends le son; mais tu ne sais pas d’où il vient, ni où il va: il en est ainsi de tout homme qui est né de l’Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nicodème répondit et lui dit: Comment ces choses peuvent-elles se faire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jésus répondit et lui dit: Tu es le docteur d’Israël, et tu ne connais pas ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'En vérité, en vérité, je te dis: Nous disons ce que nous connaissons, et nous rendons témoignage de ce que nous avons vu, et vous ne recevez pas notre témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Si je vous ai parlé des choses terrestres, et que vous ne croyiez pas, comment croirez-vous, si je vous parle des choses célestes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Et personne n’est monté au ciel, sinon celui qui est descendu du ciel, le fils de l’homme qui est dans le ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Et comme Moïse éleva le serpent dans le désert, ainsi il faut que le fils de l’homme soit élevé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'afin que quiconque croit en lui ne périsse pas, mais qu’il ait la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Car Dieu a tant aimé le monde, qu’il a donné son Fils unique, afin que quiconque croit en lui ne périsse pas, mais qu’il ait la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Car Dieu n’a pas envoyé son Fils dans le monde afin qu’il juge le monde, mais afin que le monde soit sauvé par lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Celui qui croit en lui n’est pas jugé, mais celui qui ne croit pas est déjà jugé, parce qu’il n’a pas cru au nom du Fils unique de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Or c’est ici le jugement, que la lumière est venue dans le monde, et que les hommes ont mieux aimé les ténèbres que la lumière, car leurs œuvres étaient mauvaises;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'car quiconque fait des choses mauvaises hait la lumière, et ne vient pas à la lumière, de peur que ses œuvres ne soient reprises;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'mais celui qui pratique la vérité vient à la lumière, afin que ses œuvres soient manifestées, qu’elles sont faites en Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Après ces choses, Jésus vint dans le pays de Judée, et ses disciples [avec lui]; et il séjourna là avec eux, et baptisait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Et Jean aussi baptisait en Énon, près de Salim, parce qu’il y avait là beaucoup d’eau; et on venait, et on était baptisé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Car Jean n’avait pas encore été jeté en prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Il y eut donc une discussion entre quelques-uns des disciples de Jean et un Juif, touchant la purification.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Et ils vinrent à Jean, et lui dirent: Rabbi, celui qui était avec toi au-delà du Jourdain, à qui tu as toi-même rendu témoignage, voilà, il baptise, et tous viennent à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Jean répondit et dit: Un homme ne peut rien recevoir, à moins qu’il ne lui soit donné du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vous-mêmes, vous me rendez témoignage que j’ai dit: Ce n’est pas moi qui suis le Christ, mais je suis envoyé devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Celui qui a l’épouse est l’époux; mais l’ami de l’époux, qui assiste et l’entend, est tout réjoui à cause de la voix de l’époux; cette joie donc, qui est la mienne, est accomplie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Il faut que lui croisse, et que moi je diminue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Celui qui vient d’en haut est au-dessus de tous. Celui qui est de la terre est de la terre, et parle [comme étant] de la terre. Celui qui vient du ciel est au-dessus de tous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, '[et] de ce qu’il a vu et entendu, de cela il rend témoignage; et personne ne reçoit son témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Celui qui a reçu son témoignage, a scellé que Dieu est vrai;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'car celui que Dieu a envoyé parle les paroles de Dieu, car Dieu ne donne pas l’Esprit par mesure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Le Père aime le Fils, et a mis toutes choses entre ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Qui croit au Fils a la vie éternelle; mais qui désobéit au Fils ne verra pas la vie, mais la colère de Dieu demeure sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Quand donc le Seigneur connut que les pharisiens avaient entendu dire: Jésus fait et baptise plus de disciples que Jean');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(toutefois Jésus lui-même ne baptisait pas, mais ses disciples),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'il quitta la Judée, et s’en alla encore en Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Et il fallait qu’il traverse la Samarie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Il vient donc à une ville de la Samarie, nommée Sichar, près de la terre que Jacob donna à Joseph son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Et il y avait là une fontaine de Jacob. Jésus donc, étant lassé du chemin, se tenait là assis sur la fontaine; c’était environ la sixième heure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Une femme de la Samarie vient pour puiser de l’eau. Jésus lui dit: Donne-moi à boire');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '(car ses disciples s’en étaient allés à la ville pour acheter des vivres).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'La femme samaritaine lui dit donc: Comment toi qui es Juif, me demandes-tu à boire à moi qui suis une femme samaritaine? (Car les Juifs n’ont point de relations avec les Samaritains.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jésus répondit et lui dit: Si tu connaissais le don de Dieu, et qui est celui qui te dit: Donne-moi à boire, toi, tu lui aurais demandé, et il t’aurait donné de l’eau vive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'La femme lui dit: Seigneur, tu n’as rien pour puiser, et le puits est profond; d’où as-tu donc cette eau vive?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Es-tu plus grand que notre père Jacob qui nous a donné le puits; et lui-même en a bu, et ses fils, et son bétail?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jésus répondit et lui dit: Quiconque boit de cette eau-ci aura de nouveau soif;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'mais celui qui boira de l’eau que je lui donnerai, moi, n’aura plus soif à jamais; mais l’eau que je lui donnerai, sera en lui une fontaine d’eau jaillissant en vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'La femme lui dit: Seigneur, donne-moi cette eau, afin que je n’aie pas soif et que je ne vienne pas ici pour puiser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jésus lui dit: Va, appelle ton mari, et viens ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'La femme répondit et dit: Je n’ai pas de mari. Jésus lui dit: Tu as bien dit: Je n’ai pas de mari;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'car tu as eu cinq maris, et celui que tu as maintenant n’est pas ton mari; en cela tu as dit vrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'La femme lui dit: Seigneur, je vois que tu es un prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Nos pères ont adoré sur cette montagne-ci, et vous, vous dites qu’à Jérusalem est le lieu où il faut adorer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jésus lui dit: Femme, crois-moi: l’heure vient que vous n’adorerez le Père, ni sur cette montagne, ni à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vous, vous adorez, vous ne savez quoi; nous, nous savons ce que nous adorons; car le salut vient des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Mais l’heure vient, et elle est maintenant, que les vrais adorateurs adoreront le Père en esprit et en vérité; car aussi le Père en cherche de tels qui l’adorent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Dieu est esprit, et il faut que ceux qui l’adorent, l’adorent en esprit et en vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'La femme lui dit: Je sais que le Messie qui est appelé le Christ, vient; quand celui-là sera venu, il nous fera connaître toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jésus lui dit: Je le suis, moi qui te parle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Et là-dessus ses disciples vinrent; et ils s’étonnaient de ce qu’il parlait avec une femme; toutefois nul ne dit: Que lui demandes-tu? ou, de quoi parles-tu avec elle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'La femme donc laissa sa cruche et s’en alla à la ville, et dit aux hommes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Venez, voyez un homme qui m’a dit tout ce que j’ai fait; celui-ci n’est-il point le Christ?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Ils sortirent de la ville, et ils venaient vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Mais pendant ce temps, les disciples le priaient, disant: Rabbi, mange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Mais il leur dit: Moi, j’ai de la viande à manger que vous, vous ne connaissez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Les disciples donc dirent entre eux: Quelqu’un lui aurait-il apporté à manger?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jésus leur dit: Ma viande est de faire la volonté de celui qui m’a envoyé, et d’accomplir son œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Ne dites-vous pas, vous: Il y a encore quatre mois, et la moisson vient? Voici, je vous dis: Levez vos yeux et regardez les campagnes; car elles sont déjà blanches pour la moisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Celui qui moissonne reçoit un salaire et assemble du fruit en vie éternelle; afin que, et celui qui sème et celui qui moissonne, se réjouissent ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Car en ceci est [vérifiée] la vraie parole: L’un sème, et un autre moissonne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Moi, je vous ai envoyés moissonner ce à quoi vous n’avez pas travaillé; d’autres ont travaillé, et vous, vous êtes entrés dans leur travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Or plusieurs des Samaritains de cette ville-là crurent en lui, à cause de la parole de la femme qui avait rendu témoignage: Il m’a dit tout ce que j’ai fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Quand donc les Samaritains furent venus vers lui, ils le priaient de demeurer avec eux; et il demeura là deux jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Et beaucoup plus de gens crurent à cause de sa parole;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'et ils disaient à la femme: Ce n’est plus à cause de ton dire que nous croyons; car nous-mêmes nous [l’]avons entendu, et nous connaissons que celui-ci est véritablement le Sauveur du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Or, après les deux jours, il partit de là, et s’en alla en Galilée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'car Jésus lui-même rendait témoignage qu’un prophète n’est pas honoré dans son propre pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Quand donc il fut venu en Galilée, les Galiléens le reçurent, ayant vu toutes les choses qu’il avait faites à Jérusalem pendant la fête; car eux aussi allaient à la fête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Il vint donc encore à Cana de Galilée, où il avait, de l’eau, fait du vin. Et il y avait à Capernaüm un seigneur de la cour, duquel le fils était malade;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'celui-ci, ayant entendu dire que Jésus était venu de la Judée en Galilée, s’en alla vers lui, et le pria de descendre et de guérir son fils; car il allait mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Jésus donc lui dit: Si vous ne voyez des signes et des prodiges, vous ne croirez point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Le seigneur de la cour lui dit: Seigneur, descends avant que mon enfant meure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jésus lui dit: Va, ton fils vit. Et l’homme crut la parole que Jésus lui avait dite, et s’en alla.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Et, déjà comme il descendait, ses esclaves vinrent au-devant de lui, et lui rapportèrent que son fils vivait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Alors il s’enquit d’eux à quelle heure il s’était trouvé mieux; et ils lui dirent: Hier, à la septième heure, la fièvre l’a quitté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Le père donc connut que c’était à cette heure-là à laquelle Jésus lui avait dit: Ton fils vit. Et il crut, lui et toute sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Jésus fit encore ce second miracle, quand il fut venu de Judée en Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Après ces choses, il y avait une fête des Juifs, et Jésus monta à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Or il y a à Jérusalem, près de la porte des brebis, un réservoir d’eau, appelé en hébreu Béthesda, ayant cinq portiques,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'dans lesquels étaient couchés une multitude d’infirmes, d’aveugles, de boiteux et de gens qui avaient les membres secs, [attendant le mouvement de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Car à de certaines saisons un ange descendait dans le réservoir et agitait l’eau; le premier donc qui entrait après que l’eau avait été agitée, était guéri, de quelque maladie qu’il soit pris].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Or il y avait là un homme infirme depuis 38 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Jésus, le voyant couché là, et sachant qu’il était dans cet état déjà depuis longtemps, lui dit: Veux-tu être guéri?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Le malade lui répondit: Seigneur, je n’ai personne qui, lorsque l’eau a été agitée, me jette dans le réservoir; et, pendant que moi je viens, un autre descend avant moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jésus lui dit: Lève-toi, prends ton petit lit, et marche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Et aussitôt l’homme fut guéri, et il prit son petit lit, et marcha. Or c’était sabbat ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Les Juifs donc dirent à celui qui avait été guéri: C’est [un jour de] sabbat; il ne t’est pas permis de prendre ton petit lit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Il leur répondit: Celui qui m’a guéri, celui-là m’a dit: Prends ton petit lit, et marche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Ils lui demandèrent donc: Qui est l’homme qui t’a dit: Prends ton petit lit, et marche?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Mais celui qui avait été guéri ne savait pas qui c’était; car Jésus s’était retiré de là, une foule se trouvant dans ce lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Après ces choses, Jésus le trouva dans le temple, et lui dit: Voici, tu es guéri; ne pèche plus, de peur que pis ne t’arrive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'L’homme s’en alla et annonça aux Juifs que c’était Jésus qui l’avait guéri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Et à cause de cela les Juifs persécutaient Jésus [et cherchaient à le faire mourir], parce qu’il avait fait ces choses en un jour de sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Mais Jésus leur répondit: Mon Père travaille jusqu’à maintenant, et moi je travaille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'À cause de cela donc les Juifs cherchaient d’autant plus à le faire mourir, parce que non seulement il violait le sabbat, mais aussi parce qu’il disait que Dieu était son propre Père, se faisant égal à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Jésus donc répondit et leur dit: En vérité, en vérité, je vous dis: Le Fils ne peut rien faire de lui-même, à moins qu’il ne voie faire une chose au Père, car quelque chose que celui-ci fasse, cela, le Fils aussi de même le fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Car le Père aime le Fils, et lui montre toutes les choses qu’il fait lui-même, et il lui montrera des œuvres plus grandes que celles-ci, afin que vous soyez dans l’admiration.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Car comme le Père réveille les morts et les vivifie, de même aussi le Fils vivifie ceux qu’il veut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'car aussi le Père ne juge personne, mais il a donné tout le jugement au Fils;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'afin que tous honorent le Fils comme ils honorent le Père. Celui qui n’honore pas le Fils, n’honore pas le Père qui l’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'En vérité, en vérité, je vous dis que celui qui entend ma parole, et qui croit celui qui m’a envoyé, a la vie éternelle et ne vient pas en jugement; mais il est passé de la mort à la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'En vérité, en vérité, je vous dis que l’heure vient, et elle est maintenant, que les morts entendront la voix du Fils de Dieu, et ceux qui l’auront entendue vivront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Car comme le Père a la vie en lui-même, ainsi il a donné au Fils aussi d’avoir la vie en lui-même;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'et il lui a donné autorité de juger aussi, parce qu’il est fils de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Ne vous étonnez pas de cela; car l’heure vient en laquelle tous ceux qui sont dans les sépulcres entendront sa voix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'et ils sortiront, ceux qui auront pratiqué le bien, en résurrection de vie; et ceux qui auront fait le mal, en résurrection de jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Je ne puis rien faire, moi, de moi-même; je juge selon ce que j’entends, et mon jugement est juste; car je ne cherche pas ma volonté, mais la volonté de celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Si moi je rends témoignage de moi-même, mon témoignage n’est pas vrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'C’est un autre qui rend témoignage de moi; et je sais que le témoignage qu’il rend de moi est vrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vous, vous avez envoyé auprès de Jean, et il a rendu témoignage à la vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'mais moi, je ne reçois pas témoignage de l’homme, mais je dis ces choses afin que vous, vous soyez sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Celui-là était la lampe ardente et brillante; et vous, vous avez voulu vous réjouir pour un temps à sa lumière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'mais moi, j’ai un témoignage plus grand que celui de Jean; car les œuvres que le Père m’a données pour les accomplir, ces œuvres mêmes que je fais rendent témoignage de moi, que le Père m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Et le Père qui m’a envoyé, lui, a rendu témoignage de moi. Jamais vous n’avez entendu sa voix, ni vu sa figure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'et vous n’avez pas sa parole demeurant en vous; car celui-là que lui a envoyé, vous, vous ne le croyez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Sondez les écritures, car vous, vous estimez avoir en elles la vie éternelle, et ce sont elles qui rendent témoignage de moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, '– et vous ne voulez pas venir à moi pour avoir la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Je ne reçois pas de gloire des hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'mais je vous connais, [et je sais] que vous n’avez pas l’amour de Dieu en vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Moi, je suis venu au nom de mon Père, et vous ne me recevez pas; si un autre vient en son propre nom, celui-là vous le recevrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Comment pouvez-vous croire, vous qui recevez de la gloire l’un de l’autre et qui ne cherchez pas la gloire qui [vient] de Dieu seul?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ne pensez pas que moi, je vous accuserai devant le Père; il y en a un qui vous accuse, Moïse en qui vous espérez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Car si vous croyiez Moïse, vous me croiriez aussi; car lui a écrit de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Mais si vous ne croyez pas ses écrits, comment croirez-vous mes paroles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Après ces choses Jésus s’en alla de l’autre côté de la mer de Galilée, [qui est la mer] de Tibérias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Et une grande foule le suivit, parce qu’ils voyaient les miracles qu’il faisait sur ceux qui étaient malades.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Et Jésus monta sur la montagne, et s’assit là avec ses disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Or la Pâque, la fête des Juifs, était proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Jésus donc, ayant levé les yeux, et voyant qu’une grande foule venait à lui, dit à Philippe: D’où achèterons-nous des pains, afin que ceux-ci mangent?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Mais il disait cela pour l’éprouver, car lui savait ce qu’il allait faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Philippe lui répondit: Pour 200 deniers de pain ne leur suffirait pas, pour que chacun en reçoive quelque peu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'L’un de ses disciples, André, le frère de Simon Pierre, lui dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Il y a ici un petit garçon qui a cinq pains d’orge et deux poissons; mais qu’est-ce que cela pour tant de monde?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Et Jésus dit: Faites asseoir les gens (or il y avait beaucoup d’herbe en ce lieu-là). Les hommes donc s’assirent, au nombre d’environ 5 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Et Jésus prit les pains; et ayant rendu grâces, il les distribua à ceux qui étaient assis; de même aussi des poissons, autant qu’ils en voulaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Et après qu’ils furent rassasiés, il dit à ses disciples: Amassez les morceaux qui sont de reste, afin que rien ne soit perdu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Ils les amassèrent donc et remplirent douze paniers des morceaux qui étaient de reste des cinq pains d’orge, lorsqu’ils eurent mangé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Les hommes donc, ayant vu le miracle que Jésus avait fait, disaient: Celui-ci est véritablement le prophète qui vient dans le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Jésus donc, sachant qu’ils allaient venir et l’enlever afin de le faire roi, se retira encore sur la montagne, lui tout seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Et quand le soir fut venu, ses disciples descendirent à la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Et étant montés sur un bateau, ils allèrent de l’autre côté de la mer, à Capernaüm. Et il faisait déjà nuit, et Jésus n’était pas venu à eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Et la mer s’élevait par un grand vent qui soufflait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Ayant donc ramé environ 25 ou 30 stades, ils voient Jésus marchant sur la mer et s’approchant du bateau; et ils furent saisis de peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Mais il leur dit: C’est moi, n’ayez point de peur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Ils étaient donc tout disposés à le recevoir dans le bateau; et aussitôt le bateau prit terre au lieu où ils allaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Le lendemain, la foule qui était de l’autre côté de la mer, voyant qu’il n’y avait point là d’autre petit bateau que celui-là sur lequel ses disciples étaient montés, et que Jésus n’était pas entré avec ses disciples dans le bateau, mais que ses disciples s’en étaient allés seuls');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(mais d’autres petits bateaux étaient venus de Tibérias, près du lieu où ils avaient mangé le pain, après que le Seigneur eut rendu grâces);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, '– lors donc que la foule vit que Jésus n’était point là, ni ses disciples, ils montèrent eux-mêmes sur les bateaux, et vinrent à Capernaüm, cherchant Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Et l’ayant trouvé de l’autre côté de la mer, ils lui dirent: Rabbi, quand es-tu venu ici?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jésus leur répondit et dit: En vérité, en vérité, je vous dis: Vous me cherchez, non parce que vous avez vu des miracles, mais parce que vous avez mangé des pains et que vous avez été rassasiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Travaillez, non point pour la viande qui périt, mais pour la viande qui demeure jusque dans la vie éternelle, laquelle le fils de l’homme vous donnera; car c’est lui que le Père, Dieu, a scellé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Ils lui dirent donc: Que ferons-nous pour faire les œuvres de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jésus répondit et leur dit: C’est ici l’œuvre de Dieu, que vous croyiez en celui qu’il a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Ils lui dirent donc: Quel miracle fais-tu donc, toi, afin que nous le voyions, et que nous te croyions? Quelle œuvre fais-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Nos pères ont mangé la manne au désert, ainsi qu’il est écrit: « Il leur a donné à manger du pain venant du ciel ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Jésus donc leur dit: En vérité, en vérité, je vous dis: Moïse ne vous a pas donné le pain qui vient du ciel, mais mon Père vous donne le véritable pain qui vient du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Car le pain de Dieu est celui qui descend du ciel, et qui donne la vie au monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Ils lui dirent donc: Seigneur, donne-nous toujours ce pain-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Et Jésus leur dit: Moi, je suis le pain de vie. Celui qui vient à moi n’aura jamais faim; et celui qui croit en moi n’aura jamais soif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Mais je vous ai dit qu’aussi vous m’avez vu, et vous ne croyez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Tout ce que le Père me donne viendra à moi; et je ne mettrai point dehors celui qui vient à moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'car je suis descendu du ciel, non pour faire ma volonté, mais la volonté de celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Or c’est ici la volonté de celui qui m’a envoyé: que je ne perde rien de tout ce qu’il m’a donné, mais que je le ressuscite au dernier jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Car c’est ici la volonté de mon Père: que quiconque discerne le Fils et croit en lui, ait la vie éternelle; et moi, je le ressusciterai au dernier jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Les Juifs donc murmuraient contre lui, parce qu’il avait dit: Moi, je suis le pain descendu du ciel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'et ils disaient: N’est-ce pas ici Jésus, le fils de Joseph, duquel nous connaissons le père et la mère? Comment donc celui-ci dit-il: Je suis descendu du ciel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jésus donc répondit et leur dit: Ne murmurez pas entre vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Nul ne peut venir à moi, à moins que le Père qui m’a envoyé ne le tire; et moi, je le ressusciterai au dernier jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Il est écrit dans les prophètes: « Et ils seront tous enseignés de Dieu ». Quiconque a entendu le Père et a appris [de lui], vient à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Non pas que quelqu’un ait vu le Père, sinon celui qui est de Dieu; celui-là a vu le Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'En vérité, en vérité, je vous dis: Celui qui croit [en moi], a la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Moi, je suis le pain de vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Vos pères ont mangé la manne au désert, et sont morts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'c’est ici le pain qui descend du ciel, afin que quelqu’un en mange et ne meure pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Moi, je suis le pain vivant qui est descendu du ciel: si quelqu’un mange de ce pain, il vivra éternellement; or le pain aussi que moi je donnerai, c’est ma chair, laquelle moi je donnerai pour la vie du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Les Juifs disputaient donc entre eux, disant: Comment celui-ci peut-il nous donner sa chair à manger?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jésus donc leur dit: En vérité, en vérité, je vous dis: Si vous ne mangez la chair du fils de l’homme et ne buvez son sang, vous n’avez pas la vie en vous-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Celui qui mange ma chair et qui boit mon sang a la vie éternelle, et moi, je le ressusciterai au dernier jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Car ma chair est en vérité un aliment, et mon sang est en vérité un breuvage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Celui qui mange ma chair et qui boit mon sang demeure en moi et moi en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Comme le Père [qui est] vivant m’a envoyé, et que moi, je vis à cause du Père, de même celui qui me mangera, celui-là aussi vivra à cause de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'C’est ici le pain qui est descendu du ciel, non pas comme les pères mangèrent et moururent: celui qui mangera ce pain vivra éternellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Il dit ces choses dans la synagogue, enseignant à Capernaüm.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Plusieurs donc de ses disciples, l’ayant entendu, dirent: Cette parole est dure; qui peut l’entendre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Et Jésus, sachant en lui-même que ses disciples murmuraient là-dessus, leur dit: Ceci vous scandalise-t-il?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Si donc vous voyez le fils de l’homme monter où il était auparavant...?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'C’est l’Esprit qui vivifie; la chair ne profite de rien: les paroles que moi je vous ai dites sont esprit et sont vie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'mais il y en a quelques-uns d’entre vous qui ne croient pas; car Jésus savait, dès le commencement, qui étaient ceux qui ne croyaient pas, et qui était celui qui le livrerait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Et il dit: C’est pour cela que je vous ai dit que nul ne peut venir à moi, à moins qu’il ne lui soit donné du Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Dès lors plusieurs de ses disciples se retirèrent; et ils ne marchaient plus avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Jésus donc dit aux douze: Et vous, voulez-vous aussi vous en aller?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simon Pierre lui répondit: Seigneur, auprès de qui nous en irions-nous? Tu as les paroles de la vie éternelle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'et nous, nous croyons et nous savons que toi, tu es le Saint de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jésus leur répondit: N’est-ce pas moi qui vous ai choisis, vous, les douze, et l’un d’entre vous est un diable?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Or il parlait de Judas Iscariote, [fils] de Simon; car c’était lui qui allait le livrer, lui qui était l’un des douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Et après ces choses, Jésus se tenait en Galilée, car il ne voulait pas se tenir en Judée, parce que les Juifs cherchaient à le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Or la fête des Juifs, celle des tabernacles, était proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Ses frères lui dirent donc: Pars d’ici et va en Judée, afin que tes disciples aussi voient les œuvres que tu fais;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'car nul ne fait quelque chose en secret et ne cherche à être lui-même publiquement connu; si tu fais ces choses, montre-toi au monde toi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Car ses frères ne croyaient pas en lui non plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Jésus donc leur dit: Mon temps n’est pas encore venu, mais votre temps est toujours prêt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Le monde ne peut pas vous haïr; mais il me hait, parce que moi je rends témoignage de lui, que ses œuvres sont mauvaises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Vous, montez à cette fête; moi, je ne monte pas à cette fête, car mon temps n’est pas encore accompli.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Leur ayant dit ces choses, il demeura en Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Mais lorsque ses frères furent montés, alors lui aussi monta à la fête, non pas publiquement, mais comme en secret.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Les Juifs donc le cherchaient à la fête et disaient: Où est cet [homme]?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Et il y avait une grande rumeur à son sujet parmi les foules. Les uns disaient: Il est homme de bien. D’autres disaient: Non, mais il séduit la foule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Toutefois personne ne parlait ouvertement de lui, par crainte des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Mais, comme on était déjà au milieu de la fête, Jésus monta au temple, et il enseignait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Les Juifs donc s’étonnaient, disant: Comment celui-ci connaît-il les lettres, vu qu’il ne [les] a point apprises?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jésus donc leur répondit et dit: Ma doctrine n’est pas mienne, mais de celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Si quelqu’un veut faire sa volonté, il connaîtra de la doctrine si elle est de Dieu, ou si moi je parle de par moi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Celui qui parle de par lui-même cherche sa propre gloire; mais celui qui cherche la gloire de celui qui l’a envoyé, celui-là est vrai, et il n’y a point d’injustice en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Moïse ne vous a-t-il pas donné la loi? Et nul d’entre vous n’observe la loi. Pourquoi cherchez-vous à me faire mourir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'La foule répondit et dit: Tu as un démon; qui cherche à te faire mourir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jésus répondit et leur dit: J’ai fait une œuvre, et vous vous étonnez tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'C’est pourquoi Moïse vous a donné la circoncision (non qu’elle soit de Moïse, mais elle est des pères), et vous circoncisez un homme en un jour de sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Si un homme reçoit la circoncision en un jour de sabbat, afin que la loi de Moïse ne soit pas violée, êtes-vous irrités contre moi de ce que j’ai guéri un homme tout entier en un jour de sabbat?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Ne jugez pas sur l’apparence, mais portez un jugement juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Quelques-uns donc de ceux de Jérusalem disaient: N’est-ce pas celui qu’ils cherchent à faire mourir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Et voici, il parle librement, et ils ne lui disent rien: les chefs auraient-ils vraiment reconnu que celui-ci est le Christ?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Mais nous connaissons celui-ci, [et nous savons] d’où il est; mais lorsque le Christ viendra, personne ne sait d’où il est.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Jésus donc criait dans le temple, enseignant et disant: Et vous me connaissez, et vous savez d’où je suis: et je ne suis pas venu de par moi-même, mais celui qui m’a envoyé est véritable, et vous ne le connaissez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Moi, je le connais, car je viens de lui, et c’est lui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Ils cherchaient donc à le prendre; et personne ne mit la main sur lui, parce que son heure n’était pas encore venue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Et plusieurs d’entre la foule crurent en lui, et disaient: Le Christ, quand il sera venu, fera-t-il plus de miracles que celui-ci n’en a fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Les pharisiens entendirent la foule murmurant ces choses de lui; et les pharisiens et les principaux sacrificateurs envoyèrent des huissiers pour le prendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Jésus donc dit: Je suis encore pour un peu de temps avec vous, et je m’en vais à celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Vous me chercherez, et vous ne me trouverez pas; et là où moi je serai, vous, vous ne pouvez venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Les Juifs donc dirent entre eux: Où celui-ci va-t-il aller que nous ne le trouverons pas? Va-t-il aller à la dispersion [au milieu] des Grecs, et enseigner les Grecs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Quelle est cette parole qu’il a dite: Vous me chercherez, et vous ne me trouverez pas; et là où moi je serai, vous, vous ne pouvez venir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Et en la dernière journée, la grande journée de la fête, Jésus se tint là et cria, disant: Si quelqu’un a soif, qu’il vienne à moi, et qu’il boive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Celui qui croit en moi, selon ce qu’a dit l’écriture, des fleuves d’eau vive couleront de son ventre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, '(Or il disait cela de l’Esprit qu’allaient recevoir ceux qui croyaient en lui; car l’Esprit n’était pas encore, parce que Jésus n’avait pas encore été glorifié.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Des gens de la foule donc, ayant entendu cette parole, disaient: Celui-ci est véritablement le prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'D’autres disaient: Celui-ci est le Christ. D’autres disaient: Le Christ vient-il donc de Galilée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'L’écriture n’a-t-elle pas dit que le Christ vient de la semence de David et de la bourgade de Bethléhem, où était David?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Il y eut donc de la division dans la foule à cause de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Et quelques-uns d’entre eux voulaient le prendre; mais personne ne mit les mains sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Les huissiers donc s’en vinrent vers les principaux sacrificateurs et les pharisiens; et ceux-ci leur dirent: Pourquoi ne l’avez-vous pas amené?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Les huissiers répondirent: Jamais homme ne parla comme cet homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Les pharisiens donc leur répondirent: Et vous aussi, êtes-vous séduits?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Aucun d’entre les chefs ou d’entre les pharisiens, a-t-il cru en lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Mais cette foule qui ne connaît pas la loi est maudite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Nicodème, qui était l’un d’entre eux, leur dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Notre loi juge-t-elle l’homme avant de l’avoir entendu et d’avoir connu ce qu’il fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Ils répondirent et lui dirent: Et toi, es-tu aussi de Galilée? Enquiers-toi, et vois qu’un prophète n’est pas suscité de Galilée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'Et chacun s’en alla dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Et Jésus s’en alla à la montagne des Oliviers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Et au point du jour il vint encore au temple, et tout le peuple vint à lui; et s’étant assis, il les enseignait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Et les scribes et les pharisiens lui amènent une femme surprise en adultère; et l’ayant placée devant lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'ils lui disent: Maître, cette femme a été surprise sur le fait même, commettant adultère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Or, dans la loi, Moïse nous a commandé de lapider de telles femmes: toi donc, que dis-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Or ils disaient cela pour l’éprouver, afin qu’ils aient de quoi l’accuser. Mais Jésus, s’étant baissé, écrivait avec le doigt sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Et comme ils continuaient à l’interroger, s’étant relevé, il leur dit: Que celui de vous qui est sans péché, jette le premier la pierre contre elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Et s’étant encore baissé, il écrivait sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Et eux, l’ayant entendu, sortirent un à un, en commençant depuis les plus anciens jusqu’aux derniers; et Jésus fut laissé seul avec la femme devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Et Jésus, s’étant relevé et ne voyant personne que la femme, lui dit: Femme, où sont-ils, ceux-là, tes accusateurs? Nul ne t’a-t-il condamnée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Et elle dit: Nul, Seigneur. Et Jésus lui dit: Moi non plus, je ne te condamne pas; va, – dorénavant ne pèche plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Jésus donc leur parla encore, disant: Moi, je suis la lumière du monde; celui qui me suit ne marchera point dans les ténèbres, mais il aura la lumière de la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Les pharisiens donc lui dirent: Tu rends témoignage de toi-même; ton témoignage n’est pas vrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jésus répondit et leur dit: Quoique moi je rende témoignage de moi-même, mon témoignage est vrai, car je sais d’où je suis venu et où je vais; mais vous, vous ne savez pas d’où je viens et où je vais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vous, vous jugez selon la chair; moi, je ne juge personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Et si aussi moi, je juge, mon jugement est vrai, car je ne suis pas seul, mais moi et le Père qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Et il est écrit aussi dans votre loi, que le témoignage de deux hommes est vrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Moi, je rends témoignage de moi-même; et le Père qui m’a envoyé rend aussi témoignage de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Ils lui dirent donc: Où est ton père? Jésus répondit: Vous ne connaissez ni moi, ni mon Père; si vous m’aviez connu, vous auriez connu aussi mon Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Il dit ces paroles dans le trésor, enseignant dans le temple; et personne ne le prit, parce que son heure n’était pas encore venue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, '[Jésus] leur dit donc encore: Moi, je m’en vais, et vous me chercherez; et vous mourrez dans votre péché: là où moi je vais, vous, vous ne pouvez venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Les Juifs donc disaient: Se tuera-t-il, qu’il dise: Là où moi je vais, vous, vous ne pouvez venir?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Et il leur dit: Vous êtes d’en bas; moi, je suis d’en haut: vous êtes de ce monde; moi, je ne suis pas de ce monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Je vous ai donc dit que vous mourrez dans vos péchés; car si vous ne croyez pas que c’est moi, vous mourrez dans vos péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Ils lui disaient donc: Toi, qui es-tu? Et Jésus leur dit: Absolument ce qu’aussi je vous dis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'J’ai beaucoup de choses à dire de vous et à juger; mais celui qui m’a envoyé est vrai, et les choses que j’ai entendues de lui, moi, je les dis au monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Ils ne connurent pas qu’il leur parlait du Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Jésus donc leur dit: Quand vous aurez élevé le fils de l’homme, alors vous connaîtrez que c’est moi, et que je ne fais rien de moi-même, mais que, selon que le Père m’a enseigné, je dis ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Et celui qui m’a envoyé est avec moi; il ne m’a pas laissé seul, parce que moi, je fais toujours les choses qui lui plaisent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Comme il disait ces choses, plusieurs crurent en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Jésus donc dit aux Juifs qui avaient cru en lui: Si vous persévérez dans ma parole, vous êtes vraiment mes disciples;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'et vous connaîtrez la vérité, et la vérité vous affranchira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Ils lui répondirent: Nous sommes la postérité d’Abraham, et jamais nous n’avons été dans la servitude de personne; comment dis-tu, toi: Vous serez rendus libres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jésus leur répondit: En vérité, en vérité, je vous dis: Quiconque pratique le péché est esclave du péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Or l’esclave ne demeure pas dans la maison pour toujours; le fils y demeure pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Si donc le Fils vous affranchit, vous serez réellement libres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Je sais que vous êtes la postérité d’Abraham; mais vous cherchez à me faire mourir, parce que ma parole n’a pas d’entrée auprès de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Moi, je dis ce que j’ai vu chez mon Père; vous aussi donc, vous faites les choses que vous avez entendues de la part de votre père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Ils répondirent et lui dirent: Abraham est notre père. Jésus leur dit: Si vous étiez enfants d’Abraham, vous feriez les œuvres d’Abraham;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'mais maintenant vous cherchez à me faire mourir, moi, un homme qui vous ai dit la vérité que j’ai entendue de Dieu: Abraham n’a pas fait cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vous, vous faites les œuvres de votre père. Ils lui dirent donc: Nous ne sommes pas nés de la fornication; nous avons un père, Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jésus leur dit: Si Dieu était votre père, vous m’aimeriez, car moi je procède de Dieu et je viens de lui; car je ne suis pas venu de moi-même, mais c’est lui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Pourquoi n’entendez-vous pas mon langage? Parce que vous ne pouvez pas entendre ma parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Vous, vous avez pour père le diable, et vous voulez faire les convoitises de votre père. Lui a été meurtrier dès le commencement, et il n’a pas persévéré dans la vérité, car il n’y a pas de vérité en lui. Quand il profère le mensonge, il parle de son propre fonds, car il est menteur, et le père du mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Mais moi, parce que je dis la vérité, vous ne me croyez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Qui d’entre vous me convainc de péché? Si je dis la vérité, vous, pourquoi ne me croyez-vous pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Celui qui est de Dieu entend les paroles de Dieu; c’est pourquoi vous, vous n’entendez pas, parce que vous n’êtes pas de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Les Juifs répondirent et lui dirent: Ne disons-nous pas bien que tu es un Samaritain, et que tu as un démon?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jésus répondit: Moi, je n’ai point un démon, mais j’honore mon Père, et vous, vous jetez du déshonneur sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Mais pour moi, je ne cherche pas ma gloire; il y en a un qui cherche, et qui juge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'En vérité, en vérité, je vous dis: Si quelqu’un garde ma parole, il ne verra point la mort, à jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Les Juifs donc lui dirent: Maintenant nous connaissons que tu as un démon: Abraham est mort, et les prophètes, et toi, tu dis: Si quelqu’un garde ma parole, il ne goûtera point la mort, à jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Es-tu plus grand que notre père Abraham, qui est mort? et les prophètes sont morts. Qui te fais-tu toi-même?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jésus répondit: Si moi je me glorifie moi-même, ma gloire n’est rien; c’est mon Père qui me glorifie, lui de qui vous dites: Il est notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Et vous ne le connaissez pas; mais moi, je le connais: et si je disais que je ne le connais pas, je serais menteur, semblable à vous; mais je le connais, et je garde sa parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, votre père, a tressailli de joie de ce qu’il verrait mon jour; et il l’a vu, et s’est réjoui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Les Juifs donc lui dirent: Tu n’as pas encore 50 ans, et tu as vu Abraham!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jésus leur dit: En vérité, en vérité, je vous dis: Avant qu’Abraham fût, je suis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Ils prirent donc des pierres pour les jeter contre lui; mais Jésus se cacha et sortit du temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Et comme il passait, il vit un homme aveugle dès sa naissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Et ses disciples l’interrogèrent, disant: Rabbi, qui a péché: celui-ci, ou ses parents, pour qu’il soit né aveugle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jésus répondit: Ni celui-ci n’a péché, ni ses parents; mais c’est afin que les œuvres de Dieu soient manifestées en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Il me faut faire les œuvres de celui qui m’a envoyé, tandis qu’il est jour; la nuit vient, en laquelle personne ne peut travailler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Pendant que je suis dans le monde, je suis la lumière du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Ayant dit ces choses, il cracha en terre et fit de la boue de son crachat, et mit la boue comme un onguent sur ses yeux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'et lui dit: Va, et lave-toi au réservoir de Siloé (ce qui est interprété Envoyé). Il s’en alla donc, et se lava, et revint voyant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Les voisins donc, et ceux qui, l’ayant vu auparavant, [savaient] qu’il était mendiant, dirent: N’est-ce pas celui qui était assis et qui mendiait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Quelques-uns disaient: C’est lui. D’autres disaient: Non, mais il lui ressemble. Lui dit: C’est moi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Ils lui dirent donc: Comment ont été ouverts tes yeux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Il répondit et dit: Un homme, appelé Jésus, fit de la boue et oignit mes yeux, et me dit: Va à Siloé et lave-toi. Et je m’en suis allé, et je me suis lavé, et j’ai vu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Ils lui dirent donc: Où est cet [homme]? Il dit: Je ne sais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Ils amenèrent aux pharisiens celui qui auparavant avait été aveugle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Or c’était un jour de sabbat que Jésus fit la boue, et qu’il ouvrit ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Les pharisiens donc aussi lui demandèrent encore comment il avait recouvré la vue. Et il leur dit: Il a mis de la boue sur mes yeux, et je me suis lavé, et je vois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Quelques-uns donc d’entre les pharisiens dirent: Cet homme n’est pas de Dieu, car il ne garde pas le sabbat. D’autres disaient: Comment un homme pécheur peut-il faire de tels miracles? Et il y avait de la division entre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Ils disent donc encore à l’aveugle: Toi, que dis-tu de lui, sur ce qu’il t’a ouvert les yeux? Et il dit: C’est un prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Les Juifs donc ne crurent pas qu’il avait été aveugle et qu’il avait recouvré la vue, jusqu’à ce qu’ils aient appelé les parents de celui qui avait recouvré la vue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Et ils les interrogèrent, disant: Celui-ci est-il votre fils, que vous dites être né aveugle? Comment donc voit-il maintenant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Ses parents [leur] répondirent et dirent: Nous savons que celui-ci est notre fils, et qu’il est né aveugle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'mais comment il voit maintenant, nous ne le savons pas; et qui lui a ouvert les yeux, nous ne le savons pas, nous; il a de l’âge, interrogez-le, il parlera de ce qui le concerne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Ses parents dirent ces choses, parce qu’ils craignaient les Juifs; car les Juifs étaient déjà convenus que si quelqu’un le confessait comme le Christ, il serait exclu de la synagogue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'C’est pourquoi ses parents dirent: Il a de l’âge, interrogez-le.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Ils appelèrent donc, pour la seconde fois, l’homme qui avait été aveugle, et lui dirent: Donne gloire à Dieu; nous savons que cet homme est un pécheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Il répondit donc: S’il est un pécheur, je ne sais; je sais une chose, c’est que j’étais aveugle, et que maintenant je vois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Et ils lui dirent encore: Que t’a-t-il fait? Comment a-t-il ouvert tes yeux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Il leur répondit: Je vous l’ai déjà dit, et vous n’avez pas écouté. Pourquoi voulez-vous encore l’entendre? Voulez-vous aussi, vous, devenir ses disciples?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Ils l’injurièrent et dirent: Toi, tu es le disciple de celui-là; mais nous, nous sommes disciples de Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Pour nous, nous savons que Dieu a parlé à Moïse; mais, pour celui-ci, nous ne savons d’où il est.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'L’homme répondit et leur dit: En ceci pourtant il y a une chose étrange, que vous ne sachiez pas d’où il est, et il a ouvert mes yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Or, nous savons que Dieu n’écoute pas les pécheurs; mais si quelqu’un est pieux envers Dieu et fait sa volonté, celui-là il l’écoute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Jamais on n’entendit dire que quelqu’un ait ouvert les yeux d’un aveugle-né.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Si celui-ci n’était pas de Dieu, il ne pourrait rien faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Ils répondirent et lui dirent: Tu es entièrement né dans le péché, et tu nous enseignes! Et ils le chassèrent dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jésus apprit qu’ils l’avaient chassé dehors, et l’ayant trouvé, il lui dit: Crois-tu au Fils de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Il répondit et dit: Qui est-il, Seigneur, afin que je croie en lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Et Jésus lui dit: Et tu l’as vu, et celui qui te parle, c’est lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Et il dit: Je crois, Seigneur! Et il lui rendit hommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Et Jésus dit: Moi, je suis venu dans ce monde pour [le] jugement, afin que ceux qui ne voient pas, voient; et que ceux qui voient deviennent aveugles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Et quelques-uns d’entre les pharisiens qui étaient avec lui entendirent ces choses, et lui dirent: Et nous, sommes-nous aussi aveugles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jésus leur dit: Si vous étiez aveugles, vous n’auriez pas de péché; mais maintenant vous dites: Nous voyons! – votre péché demeure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'En vérité, en vérité, je vous dis: Celui qui n’entre pas par la porte dans la bergerie des brebis, mais qui y monte par ailleurs, celui-là est un voleur et un larron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Mais celui qui entre par la porte, est le berger des brebis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'À celui-ci le portier ouvre; et les brebis écoutent sa voix; et il appelle ses propres brebis par leur nom, et les mène dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Et quand il a mis dehors toutes ses propres [brebis], il va devant elles; et les brebis le suivent, car elles connaissent sa voix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'mais elles ne suivront point un étranger, mais elles s’enfuiront loin de lui, parce qu’elles ne connaissent pas la voix des étrangers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Jésus leur dit cette similitude; mais ils ne comprirent pas ce que c’était qu’il leur disait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Jésus donc leur dit encore: En vérité, en vérité, je vous dis que moi je suis la porte des brebis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Tous, autant qu’il en est venu avant moi, sont des voleurs et des larrons; mais les brebis ne les ont pas écoutés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Moi, je suis la porte: si quelqu’un entre par moi, il sera sauvé; et il entrera et il sortira, et il trouvera de la pâture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Le voleur ne vient que pour voler, et tuer, et détruire: moi, je suis venu afin qu’elles aient la vie, et qu’elles l’aient en abondance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Moi, je suis le bon berger: le bon berger met sa vie pour les brebis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'mais l’homme qui reçoit des gages, et qui n’est pas le berger, à qui les brebis n’appartiennent pas en propre, voit venir le loup, et laisse les brebis, et s’enfuit; et le loup les ravit, et il disperse les brebis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Or l’homme à gages s’enfuit, parce qu’il est un homme à gages et qu’il ne se met pas en souci des brebis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Moi, je suis le bon berger, et je connais les miens et je suis connu des miens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'comme le Père me connaît et moi je connais le Père; et je mets ma vie pour les brebis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Et j’ai d’autres brebis qui ne sont pas de cette bergerie; il faut que je les amène, elles aussi; et elles écouteront ma voix, et il y aura un seul troupeau, un seul berger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'À cause de ceci le Père m’aime, c’est que moi je laisse ma vie, afin que je la reprenne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Personne ne me l’ôte, mais moi, je la laisse de moi-même; j’ai le pouvoir de la laisser, et j’ai le pouvoir de la reprendre: j’ai reçu ce commandement de mon Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Il y eut encore de la division parmi les Juifs à cause de ces paroles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'et plusieurs d’entre eux disaient: Il a un démon, et il est fou; pourquoi l’écoutez-vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'D’autres disaient: Ces paroles ne sont pas d’un démoniaque; un démon peut-il ouvrir les yeux des aveugles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Or la fête de la Dédicace se célébrait à Jérusalem, et c’était en hiver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Et Jésus se promenait dans le temple, au portique de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Les Juifs donc l’environnèrent et lui dirent: Jusques à quand tiens-tu notre âme en suspens? Si toi, tu es le Christ, dis-le-nous franchement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jésus leur répondit: Je vous l’ai dit, et vous ne croyez pas. Les œuvres que moi je fais au nom de mon Père, celles-ci rendent témoignage de moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'mais vous, vous ne croyez pas, car vous n’êtes pas de mes brebis, comme je vous l’ai dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Mes brebis écoutent ma voix, et moi je les connais, et elles me suivent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'et moi, je leur donne la vie éternelle, et elles ne périront jamais; et personne ne les ravira de ma main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mon Père, qui me les a données, est plus grand que tous, et personne ne peut les ravir de la main de mon Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Moi et le Père, nous sommes un.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Les Juifs donc levèrent encore des pierres pour le lapider.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jésus leur répondit: Je vous ai fait voir plusieurs bonnes œuvres de la part de mon Père: pour laquelle de ces œuvres me lapidez-vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Les Juifs lui répondirent: Nous ne te lapidons pas pour une bonne œuvre, mais pour blasphème; et parce que toi, étant homme, tu te fais Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jésus leur répondit: N’est-il pas écrit dans votre loi: « Moi j’ai dit: Vous êtes des dieux »?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'S’il appelle dieux ceux à qui la parole de Dieu est venue (et l’écriture ne peut être anéantie),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'dites-vous à celui que le Père a sanctifié, et qu’il a envoyé dans le monde: Tu blasphèmes, parce que j’ai dit: Je suis le Fils de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Si je ne fais pas les œuvres de mon Père, ne me croyez pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'mais si je les fais, alors même que vous ne me croiriez pas, croyez les œuvres, afin que vous connaissiez et que vous croyiez que le Père est en moi, et moi en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Ils cherchaient donc encore à le prendre; mais il échappa de leur main');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'et s’en alla encore au-delà du Jourdain, à l’endroit où Jean avait baptisé au commencement, et il demeura là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Et plusieurs vinrent à lui, et ils disaient: Jean n’a fait aucun miracle; mais toutes les choses que Jean a dites de celui-ci étaient vraies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Et plusieurs crurent là en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Or il y avait un certain homme malade, Lazare, de Béthanie, du village de Marie et de Marthe sa sœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '(Et c’était la Marie qui oignit le Seigneur d’un parfum et qui lui essuya les pieds avec ses cheveux, de laquelle Lazare, le malade, était le frère.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Les sœurs donc envoyèrent vers lui, disant: Seigneur, voici, celui que tu aimes est malade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Jésus, l’ayant entendu, dit: Cette maladie n’est pas à la mort, mais pour la gloire de Dieu, afin que le Fils de Dieu soit glorifié par elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Or Jésus aimait Marthe, et sa sœur, et Lazare.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Après donc qu’il eut entendu que Lazare était malade, il demeura encore deux jours au lieu où il était.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Puis après cela, il dit à ses disciples: Retournons en Judée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Les disciples lui disent: Rabbi, les Juifs cherchaient tout à l’heure à te lapider, et tu y vas encore!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jésus répondit: N’y a-t-il pas douze heures au jour? Si quelqu’un marche de jour, il ne bronche pas, car il voit la lumière de ce monde;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'mais si quelqu’un marche de nuit, il bronche, car la lumière n’est pas en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Il dit ces choses; et après cela il leur dit: Lazare, notre ami, s’est endormi; mais je vais pour l’éveiller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Les disciples donc lui dirent: Seigneur, s’il s’est endormi, il sera guéri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Or Jésus avait parlé de sa mort; mais eux pensaient qu’il avait parlé du dormir du sommeil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Jésus leur dit donc alors ouvertement: Lazare est mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'et je me réjouis, à cause de vous, de ce que je n’étais pas là, afin que vous croyiez. Mais allons vers lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Thomas donc, appelé Didyme, dit à ses condisciples: Allons-y, nous aussi, afin que nous mourions avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Jésus étant donc arrivé trouva qu’il était déjà depuis quatre jours dans le sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Or Béthanie était près de Jérusalem, à une distance d’environ 15 stades.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Et plusieurs d’entre les Juifs étaient venus auprès de Marthe et de Marie, pour les consoler au sujet de leur frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Marthe donc, quand elle eut entendu dire que Jésus venait, alla au-devant de lui; mais Marie se tenait assise dans la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Marthe donc dit à Jésus: Seigneur, si tu avais été ici mon frère ne serait pas mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, '[mais] même maintenant je sais que tout ce que tu demanderas à Dieu, Dieu te le donnera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jésus lui dit: Ton frère ressuscitera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marthe lui dit: Je sais qu’il ressuscitera en la résurrection, au dernier jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jésus lui dit: Moi, je suis la résurrection et la vie: celui qui croit en moi, encore qu’il soit mort, vivra;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'et quiconque vit, et croit en moi, ne mourra point, à jamais. Crois-tu cela?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Elle lui dit: Oui, Seigneur, moi je crois que tu es le Christ, le Fils de Dieu, qui vient dans le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Et ayant dit cela, elle s’en alla et appela secrètement Marie, sa sœur, disant: Le maître est venu, et il t’appelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Celle-ci, aussitôt qu’elle l’eut entendu, se lève promptement et s’en vient à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, '(Or Jésus n’était pas encore arrivé dans le village; mais il était au lieu où Marthe l’avait rencontré.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Les Juifs donc qui étaient avec Marie dans la maison et qui la consolaient, ayant vu que Marie s’était levée promptement et était sortie, la suivirent, disant: Elle s’en va au sépulcre pour y pleurer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Marie donc, quand elle fut venue là où était Jésus, et qu’elle l’eut vu, se jeta à ses pieds, lui disant: Seigneur, si tu avais été ici, mon frère ne serait pas mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Jésus donc, quand il la vit pleurer, et les Juifs qui étaient venus avec elle, pleurer, frémit en [son] esprit, et se troubla,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'et dit: Où l’avez-vous mis? Ils lui disent: Seigneur, viens et vois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jésus pleura.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Les Juifs donc dirent: Voyez comme il l’affectionnait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Mais quelques-uns d’entre eux dirent: Celui-ci, qui a ouvert les yeux de l’aveugle, n’aurait-il pas pu faire aussi que cet homme ne meure pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jésus donc, frémissant encore en lui-même, vient au sépulcre (or c’était une grotte, et il y avait une pierre dessus).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jésus dit: Ôtez la pierre. Marthe, la sœur du mort, lui dit: Seigneur, il sent déjà, car il est [là] depuis quatre jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jésus lui dit: Ne t’ai-je pas dit que, si tu crois, tu verras la gloire de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Ils ôtèrent donc la pierre. Et Jésus leva les yeux en haut et dit: Père, je te rends grâces de ce que tu m’as entendu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Or moi je savais que tu m’entends toujours; mais je l’ai dit à cause de la foule qui est autour de moi, afin qu’ils croient que toi, tu m’as envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Et ayant dit ces choses, il cria à haute voix: Lazare, sors dehors!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Et le mort sortit, ayant les pieds et les mains liés de bandes; et son visage était enveloppé d’un suaire. Jésus leur dit: Déliez-le, et laissez-le aller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Plusieurs donc d’entre les Juifs qui étaient venus auprès de Marie, et qui avaient vu ce que Jésus avait fait, crurent en lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'mais quelques-uns d’entre eux s’en allèrent auprès des pharisiens et leur dirent ce que Jésus avait fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Les principaux sacrificateurs et les pharisiens donc assemblèrent un sanhédrin, et dirent: Que faisons-nous? car cet homme fait beaucoup de miracles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Si nous le laissons ainsi [faire], tous croiront en lui, et les Romains viendront, et ôteront et notre lieu et notre nation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Et l’un d’entre eux, [appelé] Caïphe, qui était souverain sacrificateur cette année-là, leur dit: Vous ne savez rien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'ni ne considérez qu’il nous est avantageux qu’un seul homme meure pour le peuple et que la nation entière ne périsse pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Or il ne dit pas cela de lui-même; mais étant souverain sacrificateur cette année-là, il prophétisa que Jésus allait mourir pour la nation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'et non pas seulement pour la nation, mais aussi pour rassembler en un les enfants de Dieu dispersés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Depuis ce jour-là donc, ils consultèrent [ensemble] pour le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Jésus donc ne marcha plus ouvertement parmi les Juifs; mais il s’en alla de là dans la contrée qui est près du désert, en une ville appelée Éphraïm; et il séjourna là avec les disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Or la Pâque des Juifs était proche, et plusieurs montèrent de la campagne à Jérusalem, avant la Pâque, afin de se purifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Ils cherchaient donc Jésus, et se disaient l’un à l’autre, comme ils étaient dans le temple: Que vous semble? [Pensez-vous] qu’il ne viendra point à la fête?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Or les principaux sacrificateurs et les pharisiens avaient donné ordre que si quelqu’un savait où il était, il le déclare, afin qu’on le prenne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Jésus donc, six jours avant la Pâque, vint à Béthanie où était Lazare, le mort, que Jésus avait ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'On lui fit donc là un souper; et Marthe servait, et Lazare était un de ceux qui étaient à table avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Marie donc, ayant pris une livre de parfum de nard pur de grand prix, oignit les pieds de Jésus et lui essuya les pieds avec ses cheveux; et la maison fut remplie de l’odeur du parfum.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'L’un de ses disciples donc, Judas Iscariote, [fils] de Simon, qui allait le livrer, dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Pourquoi ce parfum n’a-t-il pas été vendu 300 deniers et donné aux pauvres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Or il dit cela, non pas qu’il se soit soucié des pauvres, mais parce qu’il était voleur, et qu’il avait la bourse et portait ce qu’on y mettait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Jésus donc dit: Permets-lui d’avoir gardé ceci pour le jour de ma sépulture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Car vous avez les pauvres toujours avec vous; mais moi, vous ne m’avez pas toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Une grande foule d’entre les Juifs sut donc qu’il était là, et vint, non seulement à cause de Jésus, mais aussi pour voir Lazare qu’il avait ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Mais les principaux sacrificateurs tinrent conseil, afin de faire mourir aussi Lazare;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'car, à cause de lui, plusieurs des Juifs s’en allaient et croyaient en Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Le lendemain, une grande foule qui était venue à la fête, ayant entendu dire que Jésus venait à Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'prit les rameaux des palmiers et sortit au-devant de lui, et criait: Hosanna! béni soit celui qui vient au nom du ✶Seigneur, le roi d’Israël!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Et Jésus, ayant trouvé un ânon, s’assit dessus, selon qu’il est écrit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '« Ne crains point, fille de Sion; voici, ton roi vient, assis sur l’ânon d’une ânesse ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Or ses disciples ne comprirent pas d’abord ces choses; mais quand Jésus eut été glorifié, alors ils se souvinrent que ces choses étaient écrites de lui et qu’ils avaient fait ces choses à son égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'La foule donc qui était avec lui, [lui] rendait témoignage, parce qu’il avait appelé Lazare hors du sépulcre, et qu’il l’avait ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'C’est pourquoi aussi la foule alla au-devant de lui, parce qu’ils avaient appris qu’il avait fait ce miracle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Les pharisiens donc dirent entre eux: Vous voyez que vous ne gagnez rien; voici, le monde est allé après lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Or il y avait quelques Grecs, d’entre ceux qui étaient montés pour adorer pendant la fête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Ceux-ci donc vinrent à Philippe qui était de Bethsaïda de Galilée, et ils le priaient, disant: Seigneur, nous désirons voir Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Philippe vient, et le dit à André; et puis André vient, et Philippe, et ils le disent à Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Et Jésus leur répondit, disant: L’heure est venue pour que le fils de l’homme soit glorifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'En vérité, en vérité, je vous dis: À moins que le grain de blé, tombant en terre, ne meure, il demeure seul; mais s’il meurt, il porte beaucoup de fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Celui qui affectionne sa vie, la perdra; et celui qui hait sa vie dans ce monde-ci, la conservera pour la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Si quelqu’un me sert, qu’il me suive; et où je suis, moi, là aussi sera mon serviteur: si quelqu’un me sert, le Père l’honorera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Maintenant mon âme est troublée; et que dirai-je? Père, délivre-moi de cette heure; mais c’est pour cela que je suis venu à cette heure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Père, glorifie ton nom. Il vint donc une voix du ciel: Et je l’ai glorifié, et je le glorifierai de nouveau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'La foule donc qui était là et qui avait entendu, dit qu’un coup de tonnerre avait eu lieu; d’autres disaient: Un ange lui a parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jésus répondit et dit: Cette voix n’est pas venue pour moi, mais pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Maintenant est le jugement de ce monde; maintenant le chef de ce monde sera jeté dehors.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Et moi, si je suis élevé de la terre, j’attirerai tous les hommes à moi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Or il disait cela pour indiquer de quelle mort il allait mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'La foule lui répondit: Nous, nous avons appris de la loi, que le Christ demeure éternellement: et comment, toi, dis-tu qu’il faut que le fils de l’homme soit élevé? Qui est ce fils de l’homme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Jésus donc leur dit: Encore pour un peu de temps la lumière est au milieu de vous; marchez pendant que vous avez la lumière, afin que les ténèbres ne s’emparent pas de vous; et celui qui marche dans les ténèbres ne sait où il va.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Pendant que vous avez la lumière, croyez en la lumière, afin que vous soyez fils de lumière. Jésus dit ces choses, et s’en allant, il se cacha de devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Et quoiqu’il ait fait tant de miracles devant eux, ils ne crurent pas en lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'afin que la parole d’Ésaïe le prophète, qu’il prononça, fût accomplie: « ✶Seigneur, qui est-ce qui a cru à ce qu’il a entendu de nous, et à qui le bras du ✶Seigneur a-t-il été révélé? ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'C’est pourquoi ils ne pouvaient croire, parce qu’Ésaïe dit encore:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '« Il a aveuglé leurs yeux et il a endurci leur cœur, afin qu’ils ne voient pas des yeux, et qu’ils n’entendent pas du cœur, et qu’ils ne soient convertis, et que je ne les guérisse ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Ésaïe dit ces choses parce qu’il vit sa gloire et qu’il parla de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Toutefois plusieurs d’entre les chefs mêmes crurent en lui; mais à cause des pharisiens ils ne le confessaient pas, de peur d’être exclus de la synagogue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'car ils ont aimé la gloire des hommes plutôt que la gloire de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Et Jésus s’écria et dit: Celui qui croit en moi, ne croit pas en moi, mais en celui qui m’a envoyé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'et celui qui me voit, voit celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Moi, je suis venu dans le monde, [la] lumière, afin que quiconque croit en moi ne demeure pas dans les ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Et si quelqu’un entend mes paroles et ne les garde pas, moi, je ne le juge pas; car je ne suis pas venu afin de juger le monde, mais afin de sauver le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Celui qui me rejette et qui ne reçoit pas mes paroles, a qui le juge; la parole que j’ai dite, celle-là le jugera au dernier jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Car moi, je n’ai pas parlé de moi-même; mais le Père qui m’a envoyé, lui-même m’a commandé ce que je devais dire et comment j’avais à parler;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'et je sais que son commandement est la vie éternelle. Les choses donc que moi je dis, je les dis comme le Père m’a dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Or, avant la fête de Pâque, Jésus, sachant que son heure était venue pour passer de ce monde au Père, ayant aimé les siens qui étaient dans le monde, les aima jusqu’à la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Et pendant qu’ils étaient à souper, le diable ayant déjà mis dans le cœur de Judas Iscariote, [fils] de Simon, de le livrer, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, '[Jésus], sachant que le Père lui avait mis toutes choses entre les mains, et qu’il était venu de Dieu, et s’en allait à Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'se lève du souper et met de côté ses vêtements; et ayant pris un linge, il s’en ceignit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Puis il verse de l’eau dans le bassin, et se met à laver les pieds des disciples, et à les essuyer avec le linge dont il était ceint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Il vient donc à Simon Pierre; et celui-ci lui dit: Seigneur, me laves-tu, toi, les pieds?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jésus répondit et lui dit: Ce que je fais, tu ne le sais pas maintenant, mais tu le sauras dans la suite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Pierre lui dit: Tu ne me laveras jamais les pieds. Jésus lui répondit: Si je ne te lave, tu n’as pas de part avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Simon Pierre lui dit: Seigneur, non pas mes pieds seulement, mais aussi mes mains et ma tête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jésus lui dit: Celui qui a tout le corps lavé n’a besoin que de se laver les pieds; mais il est tout net; et vous, vous êtes nets, mais non pas tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Car il savait qui le livrerait; c’est pourquoi il dit: Vous n’êtes pas tous nets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Quand donc il eut lavé leurs pieds et qu’il eut repris ses vêtements, s’étant remis à table, il leur dit: Savez-vous ce que je vous ai fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vous m’appelez maître et seigneur, et vous dites bien, car je le suis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'si donc moi, le seigneur et le maître, j’ai lavé vos pieds, vous aussi vous devez vous laver les pieds les uns aux autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Car je vous ai donné un exemple, afin que, comme je vous ai fait, moi, vous aussi vous fassiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'En vérité, en vérité, je vous dis: L’esclave n’est pas plus grand que son seigneur, ni l’envoyé plus grand que celui qui l’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Si vous savez ces choses, vous êtes bienheureux si vous les faites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Je ne parle pas de vous tous; moi, je connais ceux que j’ai choisis; mais c’est afin que l’écriture soit accomplie: « Celui qui mange le pain avec moi a levé son talon contre moi ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Je vous le dis dès maintenant, avant que cela arrive, afin que, quand ce sera arrivé, vous croyiez que c’est moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'En vérité, en vérité, je vous dis: Celui qui reçoit quelqu’un que j’envoie, me reçoit; et celui qui me reçoit, reçoit celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Ayant dit ces choses, Jésus fut troublé dans [son] esprit, et rendit témoignage et dit: En vérité, en vérité, je vous dis que l’un d’entre vous me livrera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Les disciples se regardaient donc les uns les autres, étant en perplexité, [ne sachant] de qui il parlait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Or l’un d’entre ses disciples, que Jésus aimait, était à table dans le sein de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Simon Pierre donc lui fait signe de demander lequel était celui dont il parlait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Et lui, s’étant penché sur la poitrine de Jésus, lui dit: Seigneur, lequel est-ce?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jésus répond: C’est celui à qui moi je donnerai le morceau après l’avoir trempé. Et ayant trempé le morceau, il le donne à Judas Iscariote, [fils] de Simon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Et après le morceau, alors Satan entra en lui. Jésus donc lui dit: Ce que tu fais, fais-le promptement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Mais aucun de ceux qui étaient à table ne comprit pourquoi il lui avait dit cela;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'car quelques-uns pensaient que, puisque Judas avait la bourse, Jésus lui avait dit: Achète ce dont nous avons besoin pour la fête; ou, qu’il donne quelque chose aux pauvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Ayant donc reçu le morceau, il sortit aussitôt; or il était nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Lors donc qu’il fut sorti, Jésus dit: Maintenant le fils de l’homme est glorifié, et Dieu est glorifié en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Si Dieu est glorifié en lui, Dieu aussi le glorifiera en lui-même; et aussitôt il le glorifiera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Enfants, je suis encore pour un peu de temps avec vous: vous me chercherez; et, comme j’ai dit aux Juifs: Là où moi je vais, vous, vous ne pouvez venir, je vous le dis aussi maintenant à vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Je vous donne un commandement nouveau, que vous vous aimiez l’un l’autre; comme je vous ai aimés, que vous aussi vous vous aimiez l’un l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'À ceci tous connaîtront que vous êtes mes disciples, si vous avez de l’amour entre vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Pierre lui dit: Seigneur, où vas-tu? Jésus lui répondit: Là où je vais, tu ne peux pas me suivre maintenant, mais tu me suivras plus tard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Pierre lui dit: Seigneur, pourquoi ne puis-je pas te suivre maintenant? Je laisserai ma vie pour toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jésus répond: Tu laisseras ta vie pour moi! En vérité, en vérité, je te dis: Le coq ne chantera point, que tu ne m’aies renié trois fois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Que votre cœur ne soit pas troublé; vous croyez en Dieu, croyez aussi en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Dans la maison de mon Père, il y a plusieurs demeures; s’il en était autrement, je vous l’aurais dit, car je vais vous préparer une place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Et si je m’en vais et que je vous prépare une place, je reviendrai, et je vous prendrai auprès de moi; afin que là où moi je suis, vous, vous soyez aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Et vous savez où moi je vais, et vous en savez le chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Thomas lui dit: Seigneur, nous ne savons pas où tu vas; et comment pouvons-nous en savoir le chemin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jésus lui dit: Moi, je suis le chemin, et la vérité, et la vie; nul ne vient au Père que par moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Si vous m’aviez connu, vous auriez connu aussi mon Père; et dès maintenant vous le connaissez et vous l’avez vu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Philippe lui dit: Seigneur, montre-nous le Père, et cela nous suffit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jésus lui dit: Je suis depuis si longtemps avec vous, et tu ne m’as pas connu, Philippe? Celui qui m’a vu, a vu le Père; et comment toi, dis-tu: Montre-nous le Père?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Ne crois-tu pas que moi je suis dans le Père, et que le Père est en moi? Les paroles que moi je vous dis, je ne les dis pas de par moi-même; mais le Père qui demeure en moi, c’est lui qui fait les œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Croyez-moi, que je suis dans le Père, et que le Père est en moi; sinon, croyez-moi à cause des œuvres elles-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'En vérité, en vérité, je vous dis: Celui qui croit en moi fera, lui aussi, les œuvres que moi je fais, et il en fera de plus grandes que celles-ci; parce que moi, je m’en vais au Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Et quoi que vous demandiez en mon nom, je le ferai, afin que le Père soit glorifié dans le Fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Si vous demandez quelque chose en mon nom, moi, je le ferai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Si vous m’aimez, gardez mes commandements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'et moi, je prierai le Père, et il vous donnera un autre consolateur, pour être avec vous éternellement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'l’Esprit de vérité, que le monde ne peut pas recevoir, parce qu’il ne le voit pas et ne le connaît pas; mais vous, vous le connaissez, parce qu’il demeure avec vous, et qu’il sera en vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Je ne vous laisserai pas orphelins; je viens à vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Encore un peu de temps, et le monde ne me verra plus; mais vous, vous me verrez; parce que moi je vis, vous aussi vous vivrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'En ce jour-là, vous connaîtrez que moi je suis en mon Père, et vous en moi et moi en vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Celui qui a mes commandements et qui les garde, c’est celui-là qui m’aime; et celui qui m’aime, sera aimé de mon Père; et moi je l’aimerai, et je me manifesterai à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Jude (non pas l’Iscariote) lui dit: Seigneur, comment se fait-il que tu vas te manifester à nous, et non pas au monde?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jésus répondit et lui dit: Si quelqu’un m’aime, il gardera ma parole, et mon Père l’aimera; et nous viendrons à lui, et nous ferons notre demeure chez lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Celui qui ne m’aime pas ne garde pas mes paroles. Et la parole que vous entendez n’est pas la mienne, mais celle du Père qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Je vous ai dit ces choses demeurant avec vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'mais le Consolateur, l’Esprit Saint, que le Père enverra en mon nom, lui, vous enseignera toutes choses et vous rappellera toutes les choses que je vous ai dites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Je vous laisse la paix; je vous donne ma paix; je ne vous donne pas, moi, comme le monde donne. Que votre cœur ne soit pas troublé, ni craintif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Vous avez entendu que moi je vous ai dit: Je m’en vais, et je viens à vous. Si vous m’aviez aimé, vous vous seriez réjouis de ce que je m’en vais au Père, car mon Père est plus grand que moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Et maintenant je vous l’ai dit avant que cela arrive, afin que, quand ce sera arrivé, vous croyiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Je ne parlerai plus beaucoup avec vous, car le chef du monde vient, et il n’a rien en moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'mais afin que le monde connaisse que j’aime le Père; et selon que le Père m’a commandé, ainsi je fais. Levez-vous, partons d’ici!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Moi, je suis le vrai cep, et mon Père est le cultivateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Tout sarment en moi qui ne porte pas de fruit, il l’ôte; et tout sarment qui porte du fruit, il le nettoie, afin qu’il porte plus de fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Vous, vous êtes déjà nets, à cause de la parole que je vous ai dite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Demeurez en moi, et moi en vous. Comme le sarment ne peut pas porter de fruit de lui-même, à moins qu’il ne demeure dans le cep, de même vous non plus [vous ne le pouvez pas], à moins que vous ne demeuriez en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Moi, je suis le cep, vous, les sarments. Celui qui demeure en moi, et moi en lui, celui-là porte beaucoup de fruit; car, séparés de moi, vous ne pouvez rien faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Si quelqu’un ne demeure pas en moi, il est jeté dehors comme le sarment, et il sèche; et on les amasse, et on les met au feu, et ils brûlent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Si vous demeurez en moi, et que mes paroles demeurent en vous, vous demanderez ce que vous voudrez, et il vous sera fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'En ceci mon Père est glorifié, que vous portiez beaucoup de fruit; et vous serez mes disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Comme le Père m’a aimé, moi aussi je vous ai aimés; demeurez dans mon amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Si vous gardez mes commandements, vous demeurerez dans mon amour; comme moi j’ai gardé les commandements de mon Père, et je demeure dans son amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Je vous ai dit ces choses, afin que ma joie soit en vous, et que votre joie soit accomplie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'C’est ici mon commandement: Que vous vous aimiez les uns les autres, comme je vous ai aimés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Personne n’a un plus grand amour que celui-ci, qu’il laisse sa vie pour ses amis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Vous êtes mes amis, si vous faites tout ce que moi je vous commande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Je ne vous appelle plus esclaves, car l’esclave ne sait pas ce que son maître fait; mais je vous ai appelés amis, parce que je vous ai fait connaître tout ce que j’ai entendu de mon Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ce n’est pas vous qui m’avez choisi; mais c’est moi qui vous ai choisis et qui vous ai établis, afin que vous alliez, et que vous portiez du fruit, et que votre fruit demeure; afin que tout ce que vous demanderez au Père en mon nom, il vous le donne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Je vous commande ces choses, c’est que vous vous aimiez les uns les autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Si le monde vous hait, sachez qu’il m’a haï avant vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Si vous étiez du monde, le monde aimerait ce qui serait sien; mais parce que vous n’êtes pas du monde, mais que moi je vous ai choisis du monde, à cause de cela le monde vous hait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Souvenez-vous de la parole que moi je vous ai dite: L’esclave n’est pas plus grand que son maître. S’ils m’ont persécuté, ils vous persécuteront aussi; s’ils ont gardé ma parole, ils garderont aussi la vôtre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Mais ils vous feront toutes ces choses à cause de mon nom, parce qu’ils ne connaissent pas celui qui m’a envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Si je n’étais pas venu, et que je ne leur aie pas parlé, ils n’auraient pas eu de péché; mais maintenant ils n’ont pas de prétexte pour leur péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Celui qui me hait, hait aussi mon Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Si je n’avais pas fait parmi eux les œuvres qu’aucun autre n’a faites, ils n’auraient pas eu de péché; mais maintenant ils ont, et vu, et haï et moi et mon Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Mais c’est afin que fût accomplie la parole qui est écrite dans leur loi: « Ils m’ont haï sans cause ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Mais quand le Consolateur sera venu, lequel moi je vous enverrai d’auprès du Père, l’Esprit de vérité, qui procède du Père, celui-là rendra témoignage de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Et vous aussi, vous rendrez témoignage; parce que dès le commencement vous êtes avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Je vous ai dit ces choses, afin que vous ne soyez pas scandalisés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Ils vous excluront des synagogues; même l’heure vient que quiconque vous tuera pensera rendre service à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Et ils feront ces choses, parce qu’ils n’ont connu ni le Père, ni moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Mais je vous ai dit ces choses, afin que, quand l’heure sera venue, il vous souvienne que moi je vous les ai dites; et je ne vous ai pas dit ces choses dès le commencement, parce que j’étais avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Mais maintenant je m’en vais à celui qui m’a envoyé, et aucun d’entre vous ne me demande: Où vas-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Mais parce que je vous ai dit ces choses, la tristesse a rempli votre cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Toutefois, je vous dis la vérité: Il vous est avantageux que moi je m’en aille; car si je ne m’en vais, le Consolateur ne viendra pas à vous; mais si je m’en vais, je vous l’enverrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Et quand celui-là sera venu, il convaincra le monde de péché, et de justice, et de jugement:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'de péché, parce qu’ils ne croient pas en moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'de justice, parce que je m’en vais à mon Père, et que vous ne me voyez plus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'de jugement, parce que le chef de ce monde est jugé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'J’ai encore beaucoup de choses à vous dire; mais vous ne pouvez les supporter maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Mais quand celui-là, l’Esprit de vérité, sera venu, il vous conduira dans toute la vérité: car il ne parlera pas de par lui-même; mais il dira tout ce qu’il aura entendu, et il vous annoncera les choses qui vont arriver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Celui-là me glorifiera; car il prendra de ce qui est à moi, et vous l’annoncera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Tout ce qu’a le Père est à moi; c’est pourquoi j’ai dit qu’il prend du mien, et qu’il vous l’annoncera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Un peu de temps et vous ne me verrez pas, et encore un peu de temps et vous me verrez, [parce que je m’en vais au Père].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Quelques-uns donc d’entre ses disciples se dirent les uns aux autres: Qu’est-ce que ceci qu’il nous dit: Un peu de temps et vous ne me verrez pas, et encore un peu de temps et vous me verrez, et: Parce que je m’en vais au Père?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Ils disaient donc: Qu’est-ce que ceci qu’il dit: Un peu de temps? Nous ne savons ce qu’il dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jésus donc savait qu’ils voulaient l’interroger, et il leur dit: Vous vous enquérez entre vous touchant ceci, que j’ai dit: Un peu de temps et vous ne me verrez pas, et encore un peu de temps et vous me verrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'En vérité, en vérité, je vous dis, que vous, vous pleurerez et vous vous lamenterez, et le monde se réjouira; et vous, vous serez dans la tristesse; mais votre tristesse sera changée en joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'La femme, quand elle enfante, a de la tristesse, parce que son heure est venue; mais après qu’elle a donné le jour à l’enfant, il ne lui souvient plus de son angoisse, à cause de la joie qu’elle a de ce qu’un homme est né dans le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Et vous donc, vous avez maintenant de la tristesse; mais je vous reverrai, et votre cœur se réjouira: et personne ne vous ôte votre joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Et en ce jour-là vous ne me ferez pas de demandes. En vérité, en vérité, je vous dis, que toutes les choses que vous demanderez au Père en mon nom, il vous les donnera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Jusqu’à présent vous n’avez rien demandé en mon nom; demandez, et vous recevrez, afin que votre joie soit accomplie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Je vous ai dit ces choses par des similitudes: l’heure vient que je ne vous parlerai plus par similitudes, mais je vous parlerai ouvertement du Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'En ce jour-là, vous demanderez en mon nom, et je ne vous dis pas que moi je ferai des demandes au Père pour vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'car le Père lui-même vous aime, parce que vous m’avez aimé et que vous avez cru que moi je suis sorti d’auprès de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Je suis sorti d’auprès du Père, et je suis venu dans le monde; et de nouveau je laisse le monde, et je m’en vais au Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Ses disciples lui disent: Voici, maintenant tu parles ouvertement, et tu ne dis aucune similitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Maintenant nous savons que tu sais toutes choses, et que tu n’as pas besoin que personne te fasse des demandes; à cause de cela, nous croyons que tu es venu de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jésus leur répondit: Vous croyez maintenant?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Voici, l’heure vient, et elle est venue, que vous serez dispersés chacun chez soi, et que vous me laisserez seul; – et je ne suis pas seul, car le Père est avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Je vous ai dit ces choses, afin qu’en moi vous ayez la paix. Vous avez de la tribulation dans le monde; mais ayez bon courage, moi j’ai vaincu le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Jésus dit ces choses, et leva ses yeux au ciel, et dit: Père, l’heure est venue; glorifie ton Fils, afin que ton Fils te glorifie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'comme tu lui as donné autorité sur toute chair, afin que, [quant à] tout ce que tu lui as donné, il leur donne la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Et c’est ici la vie éternelle, qu’ils te connaissent seul vrai Dieu, et celui que tu as envoyé, Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Moi, je t’ai glorifié sur la terre, j’ai achevé l’œuvre que tu m’as donnée à faire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'et maintenant glorifie-moi, toi, Père, auprès de toi-même, de la gloire que j’avais auprès de toi avant que le monde fût.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'J’ai manifesté ton nom aux hommes que tu m’as donnés du monde; ils étaient à toi, et tu me les as donnés; et ils ont gardé ta parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Maintenant ils ont connu que tout ce que tu m’as donné vient de toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'car je leur ai donné les paroles que tu m’as données, et ils les ont reçues; et ils ont vraiment connu que je suis sorti d’auprès de toi, et ils ont cru que toi tu m’as envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Moi, je fais des demandes pour eux; je ne fais pas de demandes pour le monde, mais pour ceux que tu m’as donnés, parce qu’ils sont à toi');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, '(et tout ce qui est à moi, est à toi; et ce qui est à toi est à moi), et je suis glorifié en eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Et je ne suis plus dans le monde, et ceux-ci sont dans le monde, et moi, je viens à toi. Père saint, garde-les en ton nom que tu m’as donné, afin qu’ils soient un comme nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Quand j’étais avec eux, moi je les gardais en ton nom; j’ai gardé ceux que tu m’as donnés, et aucun d’entre eux n’est perdu, sinon le fils de perdition, afin que l’écriture fût accomplie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Et maintenant je viens à toi, et je dis ces choses dans le monde, afin qu’ils aient ma joie accomplie en eux-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Moi, je leur ai donné ta parole, et le monde les a haïs, parce qu’ils ne sont pas du monde, comme moi je ne suis pas du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Je ne fais pas la demande que tu les ôtes du monde, mais que tu les gardes du mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Ils ne sont pas du monde, comme moi je ne suis pas du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Sanctifie-les par la vérité; ta parole est la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Comme tu m’as envoyé dans le monde, moi aussi je les ai envoyés dans le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Et moi, je me sanctifie moi-même pour eux, afin qu’eux aussi soient sanctifiés par la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Or je ne fais pas seulement des demandes pour ceux-ci, mais aussi pour ceux qui croient en moi par leur parole;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'afin que tous soient un, comme toi, Père, tu es en moi, et moi en toi; afin qu’eux aussi soient un en nous, afin que le monde croie que toi tu m’as envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Et la gloire que tu m’as donnée, moi, je la leur ai donnée, afin qu’ils soient un, comme nous, nous sommes un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'moi en eux, et toi en moi; afin qu’ils soient consommés en un, et que le monde connaisse que toi tu m’as envoyé, et que tu les as aimés comme tu m’as aimé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Père, je veux, quant à ceux que tu m’as donnés, que là où moi je suis, ils y soient aussi avec moi, afin qu’ils voient ma gloire, que tu m’as donnée; car tu m’as aimé avant la fondation du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Père juste; – et le monde ne t’a pas connu, mais moi je t’ai connu; et ceux-ci ont connu que toi tu m’as envoyé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Et je leur ai fait connaître ton nom, et je le leur ferai connaître, afin que l’amour dont tu m’as aimé soit en eux, et moi en eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Ayant dit ces choses, Jésus s’en alla avec ses disciples au-delà du torrent du Cédron, où était un jardin, dans lequel il entra, lui et ses disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Et Judas aussi, qui le livrait, connaissait le lieu; car Jésus s’y était souvent assemblé avec ses disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judas donc, ayant pris la compagnie [de soldats], et des huissiers, de la part des principaux sacrificateurs et des pharisiens, vient là, avec des lanternes et des flambeaux et des armes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jésus donc, sachant toutes les choses qui devaient lui arriver, s’avança et leur dit: Qui cherchez-vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Ils lui répondirent: Jésus le Nazaréen. Jésus leur dit: C’est moi. Et Judas aussi qui le livrait était là avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Quand donc il leur dit: C’est moi, ils reculèrent, et tombèrent par terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Il leur demanda donc de nouveau: Qui cherchez-vous? Et ils dirent: Jésus le Nazaréen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jésus répondit: Je vous ai dit que c’est moi; si donc vous me cherchez, laissez aller ceux-ci,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, '– afin que fût accomplie la parole qu’il avait dite: De ceux que tu m’as donnés, je n’en ai perdu aucun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Simon Pierre donc, ayant une épée, la tira et frappa l’esclave du souverain sacrificateur et lui coupa l’oreille droite; et le nom de l’esclave était Malchus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Jésus donc dit à Pierre: Remets l’épée dans le fourreau: la coupe que le Père m’a donnée, ne la boirai-je pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'La compagnie [de soldats] donc, et le chiliarque, et les huissiers des Juifs, se saisirent de Jésus et le lièrent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'et l’amenèrent premièrement à Anne; car il était beau-père de Caïphe, qui était souverain sacrificateur cette année-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Or Caïphe était celui qui avait donné aux Juifs le conseil, qu’il était avantageux qu’un seul homme périsse pour le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Or Simon Pierre suivait Jésus, et l’autre disciple [aussi]; et ce disciple-là était connu du souverain sacrificateur, et il entra avec Jésus dans le palais du souverain sacrificateur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'mais Pierre se tenait dehors à la porte. L’autre disciple donc, qui était connu du souverain sacrificateur, sortit, et parla à la portière, et fit entrer Pierre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'La servante qui était portière dit donc à Pierre: Et toi, n’es-tu pas des disciples de cet homme? Lui dit: Je n’en suis point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Or les esclaves et les huissiers, ayant allumé un feu de charbon, se tenaient là, car il faisait froid, et ils se chauffaient; et Pierre était avec eux, se tenant là et se chauffant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Le souverain sacrificateur donc interrogea Jésus touchant ses disciples et touchant sa doctrine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jésus lui répondit: Moi, j’ai ouvertement parlé au monde; j’ai toujours enseigné dans la synagogue, et dans le temple où tous les Juifs s’assemblent, et je n’ai rien dit en secret.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Pourquoi m’interroges-tu? Interroge sur ce que je leur ai dit ceux qui m’ont entendu; voilà, ils savent, eux, ce que moi j’ai dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Or comme il disait ces choses, un des huissiers qui se tenait là donna un soufflet à Jésus, disant: Réponds-tu ainsi au souverain sacrificateur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jésus lui répondit: Si j’ai mal parlé, rends témoignage du mal; mais si j’ai bien parlé, pourquoi me frappes-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Anne donc l’avait envoyé lié à Caïphe, le souverain sacrificateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Et Simon Pierre se tenait là, et se chauffait; ils lui dirent donc: Et toi, n’es-tu pas de ses disciples? Il le nia, et dit: Je n’en suis point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'L’un d’entre les esclaves du souverain sacrificateur, parent de celui à qui Pierre avait coupé l’oreille, dit: Ne t’ai-je pas vu, moi, dans le jardin avec lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Pierre donc nia encore; et aussitôt le coq chanta.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Ils mènent donc Jésus de chez Caïphe au prétoire (or c’était le matin); et eux-mêmes, ils n’entrèrent pas au prétoire, afin qu’ils ne soient pas souillés; mais qu’ils puissent manger la pâque.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilate donc sortit vers eux, et dit: Quelle accusation portez-vous contre cet homme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Ils répondirent et lui dirent: Si cet homme n’était pas un malfaiteur, nous ne te l’aurions pas livré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Pilate donc leur dit: Prenez-le, vous, et jugez-le selon votre loi. Les Juifs donc lui dirent: Il ne nous est pas permis de faire mourir personne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'afin que fût accomplie la parole que Jésus avait dite, indiquant de quelle mort il devait mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilate donc entra encore dans le prétoire, et appela Jésus, et lui dit: Toi, tu es le roi des Juifs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jésus lui répondit: Dis-tu ceci de toi-même, ou d’autres te l’ont-ils dit de moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilate répondit: Suis-je Juif, moi? Ta nation et les principaux sacrificateurs t’ont livré à moi; qu’as-tu fait?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jésus répondit: Mon royaume n’est pas de ce monde. Si mon royaume était de ce monde, mes serviteurs auraient combattu, afin que je ne sois pas livré aux Juifs; mais maintenant mon royaume n’est pas d’ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Pilate donc lui dit: Tu es donc roi? Jésus répondit: Tu le dis que moi je suis roi. Moi, je suis né pour ceci, et c’est pour ceci que je suis venu dans le monde, afin de rendre témoignage à la vérité. Quiconque est de la vérité, écoute ma voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilate lui dit: Qu’est-ce que la vérité? Et ayant dit cela, il sortit encore vers les Juifs; et il leur dit: Moi, je ne trouve aucun crime en lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'mais vous avez une coutume, que je vous relâche quelqu’un à la Pâque; voulez-vous donc que je vous relâche le roi des Juifs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Ils s’écrièrent donc tous encore, disant: Non pas celui-ci, mais Barabbas. Or Barabbas était un brigand.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Alors donc Pilate prit Jésus et le fit fouetter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Et les soldats, ayant tressé une couronne d’épines, la mirent sur sa tête, et le vêtirent d’un vêtement de pourpre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'et vinrent à lui et dirent: Salut, roi des Juifs! Et ils lui donnaient des soufflets.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Et Pilate sortit encore et leur dit: Voici, je vous l’amène dehors, afin que vous sachiez que je ne trouve en lui aucun crime.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Jésus donc sortit dehors, portant la couronne d’épines et le vêtement de pourpre. Et il leur dit: Voici l’homme!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Quand donc les principaux sacrificateurs et les huissiers le virent, ils s’écrièrent, disant: Crucifie, crucifie-le! Pilate leur dit: Prenez-le, vous, et crucifiez-le; car moi, je ne trouve pas de crime en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Les Juifs lui répondirent: Nous avons une loi, et selon notre loi il doit mourir, car il s’est fait Fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Quand donc Pilate entendit cette parole, il craignit davantage,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'et il entra de nouveau dans le prétoire, et dit à Jésus: D’où es-tu? Et Jésus ne lui donna pas de réponse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Pilate donc lui dit: Ne me parles-tu pas? Ne sais-tu pas que j’ai le pouvoir de te relâcher, et que j’ai le pouvoir de te crucifier?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jésus répondit: Tu n’aurais aucun pouvoir contre moi, s’il ne t’était donné d’en haut; c’est pourquoi celui qui m’a livré à toi a plus de péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Dès lors Pilate cherchait à le relâcher; mais les Juifs criaient, disant: Si tu relâches celui-ci, tu n’es pas ami de César; quiconque se fait roi, s’oppose à César.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Pilate donc, ayant entendu ces paroles, amena Jésus dehors, et s’assit sur le tribunal, dans le lieu appelé le Pavé, et en hébreu Gabbatha;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, '(or c’était la Préparation de la Pâque, c’était environ la sixième heure;) et il dit aux Juifs: Voici votre roi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Mais ils crièrent: Ôte, ôte! crucifie-le! Pilate leur dit: Crucifierai-je votre roi? Les principaux sacrificateurs répondirent: Nous n’avons pas d’autre roi que César.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Alors donc il le leur livra pour être crucifié; et ils prirent Jésus, et l’emmenèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Et il sortit portant sa croix, [et s’en alla] au lieu appelé [lieu] du crâne, qui est appelé en hébreu Golgotha,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'où ils le crucifièrent, et deux autres avec lui, un de chaque côté, et Jésus au milieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Et Pilate fit aussi un écriteau, et le plaça sur la croix; et il y était écrit: Jésus le Nazaréen, le roi des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Plusieurs des Juifs donc lurent cet écriteau, parce que le lieu où Jésus fut crucifié était près de la ville; et il était écrit en hébreu, en grec, en latin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Les principaux sacrificateurs des Juifs donc dirent à Pilate: N’écris pas: Le roi des Juifs; mais que lui a dit: Je suis le roi des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilate répondit: Ce que j’ai écrit, je l’ai écrit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Les soldats donc, quand ils eurent crucifié Jésus, prirent ses vêtements et en firent quatre parts, une part pour chaque soldat. [Ils prirent] aussi la tunique. Or la tunique était sans couture, tissée tout d’une pièce depuis le haut [jusqu’en bas].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Ils dirent donc entre eux: Ne la déchirons pas, mais jetons-la au sort, à qui elle sera, – afin que l’écriture fût accomplie, qui dit: « Ils ont partagé entre eux mes vêtements, et ils ont jeté le sort sur ma robe ». Les soldats donc firent ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Or, près de la croix de Jésus, se tenaient sa mère, et la sœur de sa mère, Marie, [femme] de Clopas, et Marie de Magdala.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Jésus donc voyant sa mère, et le disciple qu’il aimait se tenant là, dit à sa mère: Femme, voilà ton fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Puis il dit au disciple: Voilà ta mère. Et dès cette heure-là, le disciple la prit chez lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Après cela Jésus, sachant que toutes choses étaient déjà accomplies, dit, afin que l’écriture fût accomplie: J’ai soif.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Il y avait donc là un vase plein de vinaigre. Et ils emplirent de vinaigre une éponge, et, l’ayant mise sur de l’hysope, ils la lui présentèrent à la bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Quand donc Jésus eut pris le vinaigre, il dit: C’est accompli. Et ayant baissé la tête, il remit son esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Les Juifs donc, afin que les corps ne demeurent pas sur la croix en un jour de sabbat, puisque c’était la Préparation (car le jour de ce sabbat-là était grand), firent à Pilate la demande qu’on leur rompe les jambes, et qu’on les ôte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Les soldats donc vinrent et rompirent les jambes du premier, et de l’autre qui était crucifié avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Mais étant venus à Jésus, comme ils virent qu’il était déjà mort, ils ne lui rompirent pas les jambes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'mais l’un des soldats lui perça le côté avec une lance; et aussitôt il en sortit du sang et de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Et celui qui l’a vu rend témoignage; et son témoignage est véritable; et lui sait qu’il dit vrai, afin que vous aussi vous croyiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Car ces choses sont arrivées afin que l’écriture fût accomplie: « Pas un de ses os ne sera cassé ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Et encore une autre écriture dit: « Ils regarderont vers celui qu’ils ont percé ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Or, après ces choses, Joseph d’Arimathée, qui était disciple de Jésus, en secret toutefois par crainte des Juifs, fit à Pilate la demande d’ôter le corps de Jésus; et Pilate le permit. Il vint donc et ôta le corps de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Et Nicodème aussi, celui qui au commencement était allé de nuit à Jésus, vint, apportant une mixtion de myrrhe et d’aloès, d’environ 100 livres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Ils prirent donc le corps de Jésus, et l’enveloppèrent de linges, avec les aromates, comme les Juifs ont coutume d’ensevelir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Or il y avait, au lieu où il avait été crucifié, un jardin, et dans le jardin un sépulcre neuf, dans lequel personne n’avait jamais été mis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Ils mirent donc Jésus là, à cause de la Préparation des Juifs, parce que le sépulcre était proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Et le premier jour de la semaine, Marie de Magdala vint le matin au sépulcre, comme il faisait encore nuit; et elle voit la pierre ôtée du sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Elle court donc, et vient vers Simon Pierre et vers l’autre disciple que Jésus aimait, et elle leur dit: On a enlevé du sépulcre le Seigneur, et nous ne savons où on l’a mis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Pierre donc sortit, et l’autre disciple, et ils s’en allèrent au sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Et ils couraient les deux ensemble; et l’autre disciple courut en avant plus vite que Pierre, et arriva le premier au sépulcre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'et s’étant baissé, il voit les linges à terre; cependant il n’entra pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Simon Pierre donc, qui le suivait, arrive; et il entra dans le sépulcre; et il voit les linges à terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'et le suaire qui avait été sur sa tête, lequel n’était pas avec les linges, mais plié en un lieu à part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Alors donc l’autre disciple aussi, qui était arrivé le premier au sépulcre, entra, et il vit, et crut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'car ils ne connaissaient pas encore l’écriture, qu’il devait ressusciter d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Les disciples s’en retournèrent donc chez eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Mais Marie se tenait près du sépulcre, dehors, et pleurait. Comme elle pleurait donc, elle se baissa dans le sépulcre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'et elle voit deux anges vêtus de blanc, assis, un à la tête et un aux pieds, là où le corps de Jésus avait été couché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Et ils lui disent: Femme, pourquoi pleures-tu? Elle leur dit: Parce qu’on a enlevé mon Seigneur, et je ne sais où on l’a mis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Ayant dit cela, elle se tourna en arrière, et elle voit Jésus qui était là; et elle ne savait pas que c’était Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jésus lui dit: Femme, pourquoi pleures-tu? Qui cherches-tu? Elle, pensant que c’était le jardinier, lui dit: Seigneur, si toi tu l’as emporté, dis-moi où tu l’as mis, et moi je l’ôterai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jésus lui dit: Marie! Elle, s’étant retournée, lui dit en hébreu: Rabboni (ce qui veut dire, maître)!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jésus lui dit: Ne me touche pas, car je ne suis pas encore monté vers mon Père; mais va vers mes frères, et dis-leur: Je monte vers mon Père et votre Père, et vers mon Dieu et votre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Marie de Magdala vient rapporter aux disciples qu’elle a vu le Seigneur, et qu’il lui a dit ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Le soir donc étant [venu], ce jour-là, le premier de la semaine, et les portes [du lieu] où les disciples étaient, par crainte des Juifs, étant fermées, Jésus vint, et se tint au milieu d’eux. Et il leur dit: Paix vous soit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Et ayant dit cela, il leur montra ses mains et son côté. Les disciples se réjouirent donc quand ils virent le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Jésus donc leur dit encore: Paix vous soit! Comme le Père m’a envoyé, moi aussi je vous envoie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Et ayant dit cela, il souffla en eux, et leur dit: Recevez [l’]Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'À quiconque vous remettrez les péchés, ils sont remis; [et] à quiconque vous les retiendrez, ils sont retenus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Or Thomas, l’un des douze, appelé Didyme, n’était pas avec eux quand Jésus vint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Les autres disciples donc lui dirent: Nous avons vu le Seigneur. Mais il leur dit: À moins que je ne voie en ses mains la marque des clous, et que je ne mette mon doigt dans la marque des clous, et que je ne mette ma main dans son côté, je ne le croirai point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Et huit jours après, ses disciples étaient de nouveau dans la maison, et Thomas avec eux. Jésus vient, les portes étant fermées; et il se tint au milieu d’eux et dit: Paix vous soit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Puis il dit à Thomas: Avance ton doigt ici, et regarde mes mains; avance aussi ta main, et mets-la dans mon côté; et ne sois pas incrédule, mais croyant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Thomas répondit et lui dit: Mon Seigneur et mon Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jésus lui dit: Parce que tu m’as vu, tu as cru; bienheureux ceux qui n’ont point vu et qui ont cru.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Jésus donc fit aussi devant ses disciples beaucoup d’autres miracles, qui ne sont pas écrits dans ce livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Mais ces choses sont écrites afin que vous croyiez que Jésus est le Christ, le Fils de Dieu, et qu’en croyant vous ayez la vie par son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Après ces choses, Jésus se manifesta encore aux disciples près de la mer de Tibérias; et il se manifesta ainsi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simon Pierre, et Thomas, appelé Didyme, et Nathanaël de Cana de Galilée, et les [fils] de Zébédée, et deux autres de ses disciples étaient ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Simon Pierre leur dit: Je m’en vais pêcher. Ils lui disent: Nous allons aussi avec toi. Ils sortirent, et montèrent dans le bateau: et cette nuit-là ils ne prirent rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Et le matin venant déjà, Jésus se tint sur le rivage; les disciples toutefois ne savaient pas que c’était Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Jésus donc leur dit: Enfants, avez-vous quelque chose à manger? Ils lui répondirent: Non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Et il leur dit: Jetez le filet au côté droit du bateau, et vous trouverez. Ils le jetèrent donc, et ils ne pouvaient plus le tirer, à cause de la multitude des poissons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Ce disciple donc que Jésus aimait, dit à Pierre: C’est le Seigneur. Simon Pierre donc, ayant entendu que c’était le Seigneur, ceignit sa robe de dessus, car il était nu, et se jeta dans la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Et les autres disciples vinrent dans le petit bateau (car ils n’étaient pas loin de terre, mais à environ 200 coudées), traînant le filet de poissons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Quand ils furent donc descendus à terre, ils voient là de la braise, et du poisson mis dessus, et du pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jésus leur dit: Apportez quelques-uns des poissons que vous venez de prendre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Pierre monta, et tira le filet à terre, plein de 153 gros poissons; et quoiqu’il y en eût tant, le filet n’avait pas été déchiré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jésus leur dit: Venez, dînez. Et aucun des disciples n’osait lui demander: Qui es-tu? sachant que c’était le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jésus vient et prend le pain, et le leur donne, et de même le poisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Ce fut là la troisième fois déjà que Jésus fut manifesté aux disciples, après qu’il fut ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Lors donc qu’ils eurent dîné, Jésus dit à Simon Pierre: Simon, [fils] de Jonas, m’aimes-tu plus que [ne font] ceux-ci? Il lui dit: Oui, Seigneur, tu sais que je t’aime. Il lui dit: Pais mes agneaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Il lui dit encore une seconde fois: Simon, [fils] de Jonas, m’aimes-tu? Il lui dit: Oui, Seigneur, tu sais que je t’aime. Il lui dit: Sois berger de mes brebis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Il lui dit pour la troisième fois: Simon, [fils] de Jonas, m’aimes-tu? Pierre fut attristé de ce qu’il lui disait pour la troisième fois: M’aimes-tu? Et il lui dit: Seigneur, tu connais toutes choses, tu sais que je t’aime. Jésus lui dit: Pais mes brebis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'En vérité, en vérité, je te dis: Quand tu étais jeune, tu te ceignais, et tu allais où tu voulais; mais quand tu seras devenu vieux, tu étendras les mains, et un autre te ceindra, et te conduira où tu ne veux pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Or il dit cela pour indiquer de quelle mort il glorifierait Dieu. Et quand il eut dit cela, il lui dit: Suis-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Pierre, se retournant, voit suivre le disciple que Jésus aimait, qui aussi, durant le souper, s’était penché sur sa poitrine, et avait dit: Seigneur, lequel est celui qui te livrera?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Pierre, le voyant, dit à Jésus: Seigneur, et celui-ci, – que [lui arrivera-t-il]?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jésus lui dit: Si je veux qu’il demeure jusqu’à ce que je vienne, que t’importe? Toi, suis-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Cette parole donc se répandit parmi les frères, que ce disciple-là ne mourrait pas. Et Jésus ne lui avait pas dit qu’il ne mourrait pas, mais: Si je veux qu’il demeure jusqu’à ce que je vienne, que t’importe?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'C’est ce disciple-là qui rend témoignage de ces choses, et qui a écrit ces choses, et nous savons que son témoignage est vrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Et il y a aussi plusieurs autres choses que Jésus a faites, lesquelles, si elles étaient écrites une à une, je ne pense pas que le monde même puisse contenir les livres qui seraient écrits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'J’ai composé le premier traité, ô Théophile, sur toutes les choses que Jésus commença de faire et d’enseigner,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'jusqu’au jour où il fut élevé [au ciel], après avoir donné, par l’Esprit Saint, des ordres aux apôtres qu’il avait choisis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'à qui aussi, après avoir souffert, il se présenta lui-même vivant, avec plusieurs preuves assurées, étant vu par eux durant 40 jours, et parlant des choses qui regardent le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Et étant assemblé avec eux, il leur commanda de ne pas partir de Jérusalem, mais d’attendre la promesse du Père, laquelle, [dit-il], vous avez entendue de moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'car Jean a baptisé avec de l’eau; mais vous, vous serez baptisés de l’Esprit Saint, dans peu de jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Eux donc étant assemblés, l’interrogèrent, disant: Seigneur, est-ce en ce temps-ci que tu rétablis le royaume pour Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Mais il leur dit: Ce n’est pas à vous de connaître les temps ou les saisons que le Père a réservés à sa propre autorité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'mais vous recevrez de la puissance, le Saint Esprit venant sur vous; et vous serez mes témoins à Jérusalem et dans toute la Judée et la Samarie, et jusqu’au bout de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Et ayant dit ces choses, il fut élevé [de la terre], comme ils regardaient, et une nuée le reçut [et l’emporta] de devant leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Et comme ils regardaient fixement vers le ciel, tandis qu’il s’en allait, voici, deux hommes en vêtements blancs, se tinrent là à côté d’eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'qui aussi dirent: Hommes galiléens, pourquoi vous tenez-vous ici, regardant vers le ciel? Ce Jésus, qui a été élevé d’avec vous dans le ciel, viendra de la même manière que vous l’avez vu s’en allant au ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Alors ils s’en retournèrent à Jérusalem, de la montagne appelée des Oliviers, qui est près de Jérusalem, le chemin d’un sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Et quand ils furent entrés [dans la ville], ils montèrent dans la chambre haute où demeuraient Pierre, et Jean, et Jacques, et André, Philippe et Thomas, Barthélemy et Matthieu, Jacques [fils] d’Alphée et Simon Zélote, et Jude [frère] de Jacques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Tous ceux-ci persévéraient d’un commun accord dans la prière, avec les femmes, et avec Marie, la mère de Jésus, et avec ses frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Et en ces jours-là, Pierre se levant au milieu des disciples (le nombre de ceux qui étaient réunis était d’environ 120), dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Hommes frères, il fallait que soit accomplie cette écriture que l’Esprit Saint a dite d’avance par la bouche de David, touchant Judas, qui a été le guide de ceux qui ont pris Jésus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'car il était compté parmi nous, et il avait reçu en partage ce service;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, '(celui-ci donc s’était acquis un champ avec le salaire de l’iniquité, et, étant tombé la tête en avant, s’est crevé par le milieu, et toutes ses entrailles ont été répandues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Et ceci a été connu de tous les habitants de Jérusalem, de sorte que ce champ-là est appelé dans leur propre dialecte Aceldama, c’est-à-dire champ de sang;)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'car il est écrit dans le livre des Psaumes: « Que sa demeure soit déserte, et qu’il n’y ait personne qui y habite », et: « Qu’un autre prenne sa charge de surveillant ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Il faut donc que d’entre les hommes qui se sont rassemblés avec nous pendant tout le temps que le seigneur Jésus entrait et sortait au milieu de nous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'en commençant depuis le baptême de Jean, jusqu’au jour auquel il a été élevé [au ciel] d’avec nous, quelqu’un d’entre eux soit témoin avec nous de sa résurrection.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Et ils en mirent deux sur les rangs: Joseph, appelé Barsabbas, qui était surnommé Juste, et Matthias.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Et priant, ils dirent: Toi, Seigneur, qui connais les cœurs de tous, montre lequel de ces deux tu as choisi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'afin qu’il reçoive en partage ce service et cet apostolat, duquel Judas est déchu pour s’en aller en son propre lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Et ils jetèrent le sort sur eux; et le sort tomba sur Matthias, qui fut adjoint aux onze apôtres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Et comme le jour de la Pentecôte s’accomplissait, ils étaient tous ensemble dans un même lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Et il se fit tout à coup du ciel un son, comme d’un souffle violent et impétueux, et il remplit toute la maison où ils étaient assis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Et il leur apparut des langues divisées, comme de feu; et elles se posèrent sur chacun d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Et ils furent tous remplis de l’Esprit Saint, et commencèrent à parler d’autres langues, selon que l’Esprit leur donnait de s’énoncer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Or il y avait des Juifs séjournant à Jérusalem, hommes pieux, de toute nation d’entre ceux qui sont sous le ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Et le bruit de ceci s’étant répandu, la multitude s’assembla, et fut confondue de ce que chacun les entendait parler dans son propre langage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Et ils étaient tous hors d’eux-mêmes, et s’étonnaient, disant: Voici, tous ceux-ci qui parlent ne sont-ils pas des Galiléens?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Et comment les entendons-nous, chacun dans son propre langage, [celui du pays] dans lequel nous sommes nés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parthes et Mèdes et Élamites, et nous qui habitons la Mésopotamie, la Judée et la Cappadoce, le Pont et l’Asie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'la Phrygie et la Pamphylie, l’Égypte et les quartiers de la Libye qui est près de Cyrène, et nous, Romains qui séjournons [ici],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'tant Juifs que prosélytes, Crétois et Arabes, – nous les entendons annoncer dans nos langues les choses magnifiques de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Et ils étaient tous hors d’eux-mêmes et en perplexité, disant l’un à l’autre: Que veut dire ceci?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Et d’autres, se moquant, disaient: Ils sont pleins de vin doux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Mais Pierre, s’étant levé avec les onze, éleva sa voix, et leur parla: Hommes juifs, et vous tous qui habitez Jérusalem, sachez ceci, et prêtez l’oreille à mes paroles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'car ceux-ci ne sont pas ivres, comme vous pensez, car c’est la troisième heure du jour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'mais c’est ici ce qui a été dit par le prophète Joël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '« Et il arrivera aux derniers jours, dit Dieu, que je répandrai de mon Esprit sur toute chair, et vos fils et vos filles prophétiseront, et vos jeunes hommes verront des visions, et vos vieillards songeront en songes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'et sur mes serviteurs et sur mes servantes, en ces jours-là, je répandrai de mon Esprit, et ils prophétiseront;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'et je montrerai des prodiges dans le ciel en haut, et des signes sur la terre en bas, du sang et du feu, et une vapeur de fumée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'le soleil sera changé en ténèbres et la lune en sang, avant que vienne la grande et éclatante journée du ✶Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Et il arrivera que quiconque invoquera le nom du ✶Seigneur sera sauvé ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Hommes israélites, écoutez ces paroles: Jésus le Nazaréen, homme approuvé de Dieu auprès de vous par les miracles et les prodiges et les signes que Dieu a faits par lui au milieu de vous, comme vous-mêmes vous le savez,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'ayant été livré par le conseil défini et par la préconnaissance de Dieu, – lui, vous l’avez cloué à [une croix] et vous l’avez fait périr par la main d’hommes iniques,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'lequel Dieu a ressuscité, ayant délié les douleurs de la mort, puisqu’il n’était pas possible qu’il soit retenu par elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Car David dit de lui: « Je contemplais toujours le ✶Seigneur devant moi; car il est à ma droite, afin que je ne sois pas ébranlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'C’est pourquoi mon cœur s’est réjoui, et ma langue a tressailli de joie; et plus encore, ma chair aussi reposera en espérance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'car tu ne laisseras pas mon âme en hadès, et tu ne permettras pas que ton saint voie la corruption.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Tu m’as fait connaître les chemins de la vie, tu me rempliras de joie par [le regard de] ta face ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Hommes frères, qu’il me soit permis de vous dire avec liberté, touchant le patriarche David, et qu’il est mort, et qu’il a été enseveli, et que son sépulcre est au milieu de nous jusqu’à ce jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Étant donc prophète, et sachant que Dieu lui avait juré, avec serment, qu’il ferait asseoir [quelqu’un suscité] du fruit de ses reins, sur son trône,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'il a dit de la résurrection du Christ, en la prévoyant, qu’il n’a pas été laissé dans le hadès, et que sa chair non plus n’a pas vu la corruption.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Ce Jésus, Dieu l’a ressuscité, ce dont nous, nous sommes tous témoins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Ayant donc été exalté par la droite de Dieu, et ayant reçu de la part du Père l’Esprit Saint promis, il a répandu ce que vous voyez et entendez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Car David n’est pas monté dans les cieux; mais lui-même dit: « Le ✶Seigneur a dit à mon seigneur: Assieds-toi à ma droite,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'jusqu’à ce que j’aie mis tes ennemis pour marchepied de tes pieds ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Que toute la maison d’Israël donc sache certainement que Dieu a fait et Seigneur et Christ ce Jésus que vous avez crucifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Et ayant entendu [ces choses], ils eurent le cœur saisi de componction, et ils dirent à Pierre et aux autres apôtres: Que ferons-nous, frères?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Et Pierre leur dit: Repentez-vous, et que chacun de vous soit baptisé au nom de Jésus Christ, en rémission des péchés; et vous recevrez le don du Saint Esprit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'car à vous est la promesse et à vos enfants, et à tous ceux qui sont loin, autant que le ✶Seigneur notre Dieu en appellera à lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Et par plusieurs autres paroles, il conjurait et exhortait, disant: Sauvez-vous de cette génération perverse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Ceux donc qui reçurent sa parole, furent baptisés; et en ce jour-là furent ajoutées environ 3 000 âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Et ils persévéraient dans la doctrine et la communion des apôtres, dans la fraction du pain et les prières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Et toute âme avait de la crainte; et beaucoup de prodiges et de miracles se faisaient par les apôtres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Et tous les croyants étaient en un même lieu, et ils avaient toutes choses communes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'et ils vendaient leurs possessions et leurs biens, et les distribuaient à tous, selon que quelqu’un pouvait en avoir besoin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Et tous les jours ils persévéraient d’un commun accord dans le temple; et, rompant le pain dans leurs maisons, ils prenaient leur nourriture avec joie et simplicité de cœur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'louant Dieu, et ayant la faveur de tout le peuple. Et le Seigneur ajoutait tous les jours à l’assemblée ceux qui devaient être sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Et Pierre et Jean montaient ensemble au temple, à l’heure de la prière, qui est la neuvième,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'et on portait un homme qui était boiteux dès le ventre de sa mère, lequel on mettait tous les jours à la porte du temple, appelée la Belle, pour demander l’aumône à ceux qui entraient dans le temple:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'cet homme, voyant Pierre et Jean qui allaient entrer dans le temple, leur demanda l’aumône.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Et Pierre, ayant, avec Jean, arrêté ses yeux sur lui, dit: Regarde -nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Et il les regardait attentivement, s’attendant à recevoir quelque chose d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Mais Pierre dit: Je n’ai ni argent ni or, mais ce que j’ai, je te le donne: Au nom de Jésus Christ le Nazaréen, lève-toi et marche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Et l’ayant pris par la main droite, il le leva; et à l’instant les plantes et les chevilles de ses pieds devinrent fermes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'et faisant un saut, il se tint debout et marcha; et il entra avec eux au temple, marchant, et sautant, et louant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Et tout le peuple le vit marchant et louant Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'et ils le reconnurent comme celui qui était assis, pour demander l’aumône, à la Belle porte du temple, et ils furent remplis d’étonnement et d’admiration de ce qui lui était arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Et comme il tenait [par la main] Pierre et Jean, tout le peuple étonné accourut vers eux au portique appelé de Salomon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Et Pierre, voyant cela, répondit au peuple: Hommes israélites, pourquoi vous étonnez-vous de ceci? Ou pourquoi avez-vous les yeux fixés sur nous, comme si nous avions fait marcher cet homme par notre propre puissance ou par notre piété?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Le Dieu d’Abraham et d’Isaac et de Jacob, le Dieu de nos pères, a glorifié son serviteur Jésus, que vous, vous avez livré, et que vous avez renié devant Pilate, lorsqu’il avait décidé de le relâcher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Mais vous, vous avez renié le saint et le juste, et vous avez demandé qu’on vous accorde un meurtrier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'et vous avez mis à mort le prince de la vie, lequel Dieu a ressuscité d’entre les morts; ce dont nous, nous sommes témoins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Et, par la foi en son nom, son nom a raffermi cet homme que vous voyez et que vous connaissez; et la foi qui est par lui a donné à celui-ci cette entière disposition de tous ses membres, en la présence de vous tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Et maintenant, frères, je sais que vous l’avez fait par ignorance, de même que vos chefs aussi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'mais Dieu a ainsi accompli ce qu’il avait prédit par la bouche de tous les prophètes, [savoir] que son Christ devait souffrir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Repentez-vous donc et convertissez-vous, pour que vos péchés soient effacés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'en sorte que viennent des temps de rafraîchissement de devant la face du ✶Seigneur, et qu’il envoie Jésus Christ, qui vous a été préordonné,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'lequel il faut que le ciel reçoive, jusqu’aux temps du rétablissement de toutes choses dont Dieu a parlé par la bouche de ses saints prophètes de tout temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Moïse déjà a dit: « Le ✶Seigneur, votre Dieu, vous suscitera d’entre vos frères un prophète comme moi; vous l’écouterez dans tout ce qu’il pourra vous dire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'et il arrivera que toute âme qui n’écoutera pas ce prophète sera exterminée d’entre le peuple ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Et même tous les prophètes, depuis Samuel et ceux qui l’ont suivi, tous ceux qui ont parlé, ont aussi annoncé ces jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vous, vous êtes les fils des prophètes et de l’alliance que Dieu a établie avec nos pères, disant à Abraham: « Et en ta semence seront bénies toutes les familles de la terre ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'À vous premièrement, Dieu, ayant suscité son serviteur, l’a envoyé pour vous bénir, en détournant chacun [de vous] de vos méchancetés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Mais comme ils parlaient au peuple, les sacrificateurs et le commandant du temple et les sadducéens survinrent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'étant en peine de ce qu’ils enseignaient le peuple et annonçaient par Jésus la résurrection d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Et ils mirent les mains sur eux, et les firent garder jusqu’au lendemain, car c’était déjà le soir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Mais plusieurs de ceux qui avaient entendu la parole crurent; et le nombre des hommes se monta à environ 5 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Or il arriva que, le lendemain, leurs chefs et leurs anciens et leurs scribes, s’assemblèrent à Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'et Anne, le souverain sacrificateur, et Caïphe, et Jean, et Alexandre, et tous ceux qui étaient de la race souveraine sacerdotale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Et les ayant fait comparaître, ils [leur] demandaient: Par quelle puissance ou par quel nom avez-vous fait ceci?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Alors Pierre, étant rempli de l’Esprit Saint, leur dit: Chefs du peuple et anciens d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'si aujourd’hui nous sommes interrogés au sujet de la bonne œuvre qui a été faite à un homme impotent, [et qu’on veuille apprendre] comment il a été guéri,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'sachez, vous tous, et tout le peuple d’Israël, que ç’a été par le nom de Jésus Christ le Nazaréen, que vous, vous avez crucifié, [et] que Dieu a ressuscité d’entre les morts; c’est, [dis-je], par ce [nom] que cet homme est ici devant vous plein de santé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Celui-ci est la pierre méprisée par vous qui bâtissez, qui est devenue la pierre angulaire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'et il n’y a de salut en aucun autre; car aussi il n’y a point d’autre nom sous le ciel, qui soit donné parmi les hommes, par lequel il nous faille être sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, '– Et, voyant la hardiesse de Pierre et de Jean, et s’étant aperçus qu’ils étaient des hommes illettrés et du commun, ils s’en étonnaient, et ils les reconnaissaient pour avoir été avec Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Et, voyant là présent avec eux l’homme qui avait été guéri, ils n’avaient rien à opposer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Et leur ayant ordonné de sortir du sanhédrin, ils conférèrent entre eux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'disant: Que ferons-nous à ces hommes? car il est apparent pour tous les habitants de Jérusalem, qu’un miracle notoire a été fait par eux, et nous ne pouvons le nier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'mais afin que cela ne soit pas répandu davantage parmi le peuple, défendons-leur avec menaces, de parler davantage en ce nom à qui que ce soit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Et les ayant appelés, ils [leur] enjoignirent de ne plus parler ni enseigner, en aucune manière, au nom de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Mais Pierre et Jean, répondant, leur dirent: Jugez s’il est juste devant Dieu de vous écouter plutôt que Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Car, pour nous, nous ne pouvons pas ne pas parler des choses que nous avons vues et entendues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Et après les avoir menacés, ils les relâchèrent, ne trouvant pas comment ils pourraient les punir, à cause du peuple; parce que tous glorifiaient Dieu de ce qui avait été fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Car l’homme en qui avait été faite cette miraculeuse guérison, avait plus de 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Et ayant été relâchés, ils vinrent vers les leurs et leur rapportèrent tout ce que les principaux sacrificateurs et les anciens leur avaient dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Et l’ayant entendu, ils élevèrent d’un commun accord leur voix à Dieu, et dirent: Ô Souverain! toi, tu es le Dieu qui as fait le ciel et la terre, et la mer, et toutes les choses qui y sont:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'qui as dit, par la bouche de David ton serviteur: « Pourquoi se sont déchaînées les nations, et les peuples ont-ils projeté des choses vaines?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Les rois de la terre se sont trouvés là, et les chefs se sont réunis ensemble, contre le ✶Seigneur et contre son Christ ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Car en effet, dans cette ville, contre ton saint serviteur Jésus que tu as oint, se sont assemblés et Hérode et Ponce Pilate, avec les nations et les peuples d’Israël,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'pour faire toutes les choses que ta main et ton conseil avaient à l’avance déterminé devoir être faites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Et maintenant, Seigneur, regarde à leurs menaces, et donne à tes esclaves d’annoncer ta parole avec toute hardiesse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'en étendant ta main pour guérir, et pour qu’il se fasse des miracles et des prodiges par le nom de ton saint serviteur Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Et comme ils faisaient leur supplication, le lieu où ils étaient assemblés fut ébranlé, et ils furent tous remplis du Saint Esprit, et annonçaient la parole de Dieu avec hardiesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Et la multitude de ceux qui avaient cru était un cœur et une âme; et nul ne disait d’aucune des choses qu’il possédait, qu’elle soit à lui; mais toutes choses étaient communes entre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Et les apôtres rendaient avec une grande puissance le témoignage de la résurrection du seigneur Jésus; et une grande grâce était sur eux tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Car il n’y avait parmi eux aucune personne nécessiteuse; car tous ceux qui possédaient des champs ou des maisons les vendaient, et apportaient le prix des choses vendues,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'et le mettaient aux pieds des apôtres; et il était distribué à chacun, selon que l’un ou l’autre pouvait en avoir besoin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Et Joseph qui, par les apôtres, fut surnommé Barnabas (ce qui, étant interprété, est fils de consolation), lévite, et Cypriote de naissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'ayant une terre, la vendit, et en apporta la valeur, et la mit aux pieds des apôtres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Mais un homme nommé Ananias, avec Sapphira sa femme, vendit une possession,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'et, de connivence avec sa femme, mit de côté une partie du prix, et, en apportant une partie, la mit aux pieds des apôtres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Mais Pierre dit: Ananias, pourquoi Satan a-t-il rempli ton cœur, que tu aies menti à l’Esprit Saint et que tu aies mis de côté une partie du prix de la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Si elle était restée [non vendue], ne te demeurait-elle pas? Et vendue, n’était-elle pas en ton pouvoir? Comment t’es-tu proposé cette action dans ton cœur? Tu n’as pas menti aux hommes, mais à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Et Ananias, entendant ces paroles, tomba et expira. Et une grande crainte s’empara de tous ceux qui entendirent [ces choses].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Et les jeunes hommes, se levant, le couvrirent, et l’ayant emporté dehors, l’ensevelirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Et il arriva, environ trois heures après, que sa femme, ne sachant pas ce qui était arrivé, entra;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'et Pierre lui répondit: Dis-moi, avez-vous donné le champ pour tant? Et elle dit: Oui, pour tant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Et Pierre lui [dit]: Comment êtes-vous convenus entre vous de tenter l’Esprit du ✶Seigneur? Voici, les pieds de ceux qui ont enseveli ton mari sont à la porte, et ils t’emporteront aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Et à l’instant elle tomba à ses pieds et expira. Et les jeunes hommes, entrant, la trouvèrent morte; et ils l’emportèrent dehors et l’ensevelirent auprès de son mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Et une grande crainte s’empara de toute l’assemblée et de tous ceux qui entendaient parler de ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Et beaucoup de miracles et de prodiges se faisaient parmi le peuple, par les mains des apôtres; (et ils étaient tous d’un commun accord au portique de Salomon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'mais, d’entre les autres, nul n’osait se joindre à eux, mais le peuple les louait hautement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'et des croyants d’autant plus nombreux se joignaient au Seigneur, une multitude tant d’hommes que de femmes;)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'de sorte qu’on apportait les infirmes dehors dans les rues, et qu’on les mettait sur de petits lits et sur des couchettes, afin que, quand Pierre viendrait, au moins son ombre passe sur quelqu’un d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Et la multitude aussi des villes d’alentour s’assemblait à Jérusalem, apportant les infirmes et ceux qui étaient tourmentés par des esprits immondes; et ils étaient tous guéris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Et le souverain sacrificateur se leva, lui et tous ceux qui étaient avec lui, savoir la secte des sadducéens; et ils furent remplis de jalousie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'et mirent les mains sur les apôtres et les jetèrent dans la prison publique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Mais un ange du ✶Seigneur ouvrit de nuit les portes de la prison, et les conduisit dehors, et dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Allez, et, vous tenant dans le temple, annoncez au peuple toutes les paroles de cette vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Ce qu’ayant entendu, ils entrèrent, vers le point du jour, dans le temple, et ils enseignaient. Mais le souverain sacrificateur étant venu, et ceux qui étaient avec lui, ils assemblèrent le sanhédrin et tous les anciens des fils d’Israël, et ils envoyèrent à la prison pour les faire amener.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Mais les huissiers, y étant arrivés, ne les trouvèrent pas dans la prison; et s’en retournant, ils le rapportèrent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'disant: Nous avons trouvé la prison fermée avec toute sûreté, et les gardes se tenant aux portes; mais, ayant ouvert, nous n’avons trouvé personne dedans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Et quand le sacrificateur et le commandant du temple et les principaux sacrificateurs eurent entendu ces paroles, ils furent en perplexité à leur sujet, [ne sachant] ce que cela deviendrait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Or quelqu’un arriva et leur rapporta: Voilà, les hommes que vous avez mis en prison sont au temple et enseignent le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Alors le commandant, avec les huissiers, s’en alla et les amena sans violence; car ils craignaient d’ être lapidés par le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Et les ayant amenés, ils les présentèrent devant le sanhédrin. Et le souverain sacrificateur les interrogea,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'disant: Nous vous avons expressément enjoint de ne pas enseigner en ce nom-là, et voici, vous avez rempli Jérusalem de votre doctrine, et vous voulez faire venir sur nous le sang de cet homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Et Pierre et les apôtres, répondant, dirent: Il faut obéir à Dieu plutôt qu’aux hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Le Dieu de nos pères a ressuscité Jésus que vous avez fait mourir, le pendant au bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'C’est lui que Dieu a exalté par sa droite prince et sauveur, afin de donner la repentance à Israël et la rémission des péchés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'et nous, nous lui sommes témoins de ces choses, ainsi que l’Esprit Saint que Dieu a donné à ceux qui lui obéissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Mais eux, ayant entendu [ces choses], frémissaient de rage, et tenaient conseil pour les faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Mais un pharisien, nommé Gamaliel, docteur de la loi, honoré de tout le peuple, se leva dans le sanhédrin et donna l’ordre de faire sortir les apôtres pour un peu de temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Et il leur dit: Hommes israélites, prenez garde à vous-mêmes par rapport à ces hommes, [et voyez] ce que vous allez faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Car, avant ces jours-ci, Theudas se leva, se disant être quelque chose, auquel se joignit un nombre d’environ 400 hommes; et il fut tué, et tous ceux qui lui obéissaient furent dissipés et réduits à rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Après lui s’éleva Judas le Galiléen, aux jours du recensement, et il entraîna à la révolte un [grand] peuple après lui; lui aussi a péri, et tous ceux qui lui obéissaient furent dispersés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Et maintenant je vous dis: Ne vous mêlez plus de ces hommes, et laissez-les; car si ce dessein ou cette œuvre est des hommes, elle sera détruite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'mais si elle est de Dieu, vous ne pourrez les détruire; – de peur que vous ne soyez même trouvés faire la guerre à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Et ils furent de son avis. Et ayant appelé les apôtres, ils leur enjoignirent, après les avoir battus, de ne pas parler au nom de Jésus, et les relâchèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Eux donc se retiraient de devant le sanhédrin en se réjouissant d’avoir été estimés dignes de souffrir des opprobres pour le nom;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'et ils ne cessaient tous les jours d’enseigner et d’annoncer Jésus [comme] le Christ, dans le temple et de maison en maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Or en ces jours-là, le nombre des disciples se multipliant, il s’éleva un murmure des Hellénistes contre les Hébreux, parce que leurs veuves étaient négligées dans le service journalier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Et les douze, ayant appelé la multitude des disciples, dirent: Il ne convient pas que, laissant la parole de Dieu, nous servions aux tables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Jetez donc les yeux, frères, sur sept hommes d’entre vous, qui aient un [bon] témoignage, pleins de l’Esprit Saint et de sagesse, que nous établirons sur cette affaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Et, pour nous, nous persévérerons dans la prière et dans le service de la parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Et ce discours plut à toute la multitude; et ils choisirent Étienne, homme plein de foi et de l’Esprit Saint, et Philippe, et Prochore, et Nicanor, et Timon, et Parménas, et Nicolas, prosélyte d’Antioche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'qu’ils présentèrent aux apôtres; et, après avoir prié, ils leur imposèrent les mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Et la parole de Dieu croissait, et le nombre des disciples se multipliait beaucoup dans Jérusalem, et une grande foule de sacrificateurs obéissait à la foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Or Étienne, plein de grâce et de puissance, faisait parmi le peuple des prodiges et de grands miracles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Et quelques-uns de la synagogue appelée des Libertins, et des Cyrénéens, et des Alexandrins, et de ceux de Cilicie et d’Asie, se levèrent, disputant contre Étienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Et ils ne pouvaient pas résister à la sagesse et à l’Esprit par lequel il parlait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Alors ils subornèrent des hommes qui disaient: Nous l’avons entendu proférant des paroles blasphématoires contre Moïse et contre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Et ils soulevèrent le peuple et les anciens et les scribes; et tombant sur lui, ils l’enlevèrent et l’amenèrent devant le sanhédrin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Et ils présentèrent de faux témoins qui disaient: Cet homme ne cesse pas de proférer des paroles contre le saint lieu et contre la loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'car nous l’avons entendu dire que ce Jésus le Nazaréen détruira ce lieu-ci, et changera les coutumes que Moïse nous a enseignées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Et tous ceux qui étaient assis dans le sanhédrin, ayant leurs yeux arrêtés sur lui, virent son visage comme le visage d’un ange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Et le souverain sacrificateur dit: Ces choses donc sont-elles ainsi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Et il dit: Hommes frères et pères, écoutez: Le Dieu de gloire apparut à notre père Abraham, lorsqu’il était en Mésopotamie, avant qu’il habite en Charran,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'et il lui dit: Sors de ton pays et de ta parenté, et viens au pays que je te montrerai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Alors, sortant du pays des Chaldéens, il habita en Charran; et de là, après que son père fut mort, Dieu le fit passer dans ce pays où vous habitez maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Et il ne lui donna pas d’héritage dans ce pays, pas même où poser son pied, et il lui promit de le lui donner en possession, et à sa postérité après lui, alors qu’il n’avait point d’enfant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Et Dieu parla ainsi: « Sa postérité séjournera dans une terre étrangère, et on l’asservira et on la maltraitera pendant 400 ans;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'et je jugerai, moi, la nation à laquelle ils auront été asservis, dit Dieu; et après cela ils sortiront et me serviront en ce lieu-ci ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Et il lui donna l’alliance de la circoncision; et ainsi Abraham engendra Isaac et le circoncit le huitième jour; et Isaac, Jacob; et Jacob, les douze patriarches.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Et les patriarches, étant pleins d’envie contre Joseph, le vendirent [pour être mené] en Égypte; et Dieu était avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'et il le délivra de toutes ses afflictions, et lui fit trouver grâce et sagesse auprès du Pharaon, roi d’Égypte; et il l’établit gouverneur sur l’Égypte et sur toute sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Or il survint une famine dans tout le pays d’Égypte et en Canaan, et une grande détresse, et nos pères ne trouvèrent pas de nourriture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Et Jacob, ayant entendu dire qu’il y avait du blé en Égypte, y envoya une première fois nos pères;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'et, la seconde fois, Joseph fut reconnu de ses frères, et la famille de Joseph fut connue du Pharaon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Et Joseph envoya chercher son père Jacob et toute sa parenté, en [tout] 75 âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Et Jacob descendit en Égypte; et il mourut, lui et nos pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'et ils furent transportés à Sichem, et mis dans le sépulcre qu’Abraham avait acheté à prix d’argent des fils d’Emmor, le [père] de Sichem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Mais comme le temps de la promesse que Dieu avait promise à Abraham, approchait, le peuple s’accrut et se multiplia en Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'jusqu’à ce qu’il se leva un autre roi sur l’Égypte, qui ne connaissait pas Joseph.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Celui-ci, usant de ruse contre notre race, maltraita les pères jusqu’à leur faire exposer leurs enfants pour qu’ils ne demeurent pas en vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'En ce temps-là naquit Moïse, et il était divinement beau; et il fut nourri trois mois dans la maison du père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Mais, ayant été exposé, la fille du Pharaon l’emporta, et l’éleva pour elle, afin qu’il soit son fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Et Moïse fut instruit dans toute la sagesse des Égyptiens; et il était puissant dans ses paroles et dans ses actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Mais quand il fut parvenu à l’âge de 40 ans, il lui vint au cœur de visiter ses frères, les fils d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'et voyant l’un d’eux à qui l’on faisait tort, il le défendit, et vengea l’opprimé, en frappant l’Égyptien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Or il croyait que ses frères comprendraient que Dieu leur donnerait la délivrance par sa main, mais ils ne le comprirent point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Et le jour suivant, il se montra à eux comme ils se battaient; et il les engagea à la paix, disant: Vous êtes frères; pourquoi vous faites-vous tort l’un à l’autre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Mais celui qui faisait tort à son prochain, le repoussa, disant: Qui t’a établi chef et juge sur nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Veux-tu me tuer, toi, comme tu tuas hier l’Égyptien?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Et Moïse s’enfuit à cette parole, et fut étranger dans le pays de Madian, où il engendra deux fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Et, 40 ans s’étant écoulés, un ange lui apparut au désert de la montagne de Sinaï, dans la flamme de feu d’un buisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Et Moïse, voyant cela, fut étonné de la vision; et comme il approchait pour regarder, une voix du ✶Seigneur se fit [entendre]:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Moi, je suis le Dieu de tes pères, le Dieu d’Abraham, et d’Isaac, et de Jacob. Et Moïse, devenu tout tremblant, n’osait regarder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Et le ✶Seigneur lui dit: Délie les sandales de tes pieds; car le lieu sur lequel tu te tiens est une terre sainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'J’ai vu, j’ai vu l’oppression de mon peuple qui est en Égypte, et j’ai entendu leur gémissement, et je suis descendu pour les délivrer; et maintenant viens, je t’enverrai en Égypte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Ce Moïse qu’ils avaient rejeté, disant: Qui t’a établi chef et juge? celui-là, Dieu l’a envoyé pour chef et pour libérateur, par la main de l’ange qui lui était apparu au buisson.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'C’est lui qui les conduisit dehors, en faisant des prodiges et des miracles dans le pays d’Égypte, et dans la mer Rouge, et au désert pendant 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'C’est ce Moïse qui a dit aux fils d’Israël: Dieu vous suscitera d’entre vos frères un prophète comme moi; [écoutez-le].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'C’est lui qui fut dans l’assemblée au désert, avec l’ange qui lui parlait sur la montagne de Sinaï, et avec nos pères; qui reçut des oracles vivants pour nous les donner;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'auquel nos pères ne voulurent pas être soumis; mais ils le repoussèrent et retournèrent de leur cœur en Égypte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'disant à Aaron: Fais-nous des dieux qui aillent devant nous, car, quant à ce Moïse qui nous a conduits hors du pays d’Égypte, nous ne savons ce qui lui est arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Et ils firent en ces jours-là un veau, et offrirent un sacrifice à l’idole, et se réjouirent dans les œuvres de leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Et Dieu se retourna, et les livra au service de l’armée du ciel, ainsi qu’il est écrit au livre des prophètes: « M’avez-vous offert des bêtes égorgées et des sacrifices pendant 40 ans dans le désert, maison d’Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Et vous avez porté le tabernacle de Moloch et l’étoile de votre dieu Remphan, les figures que vous avez faites pour leur rendre hommage; et je vous transporterai au-delà de Babylone ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Nos pères avaient le tabernacle du témoignage dans le désert, comme avait ordonné celui qui avait dit à Moïse de le faire selon le modèle qu’il avait vu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Et nos pères, l’ayant reçu, l’introduisirent avec Josué, en prenant possession des nations que Dieu chassa de devant la face de nos pères, jusqu’aux jours de David,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'qui trouva grâce devant Dieu, et qui demanda de trouver un tabernacle pour le Dieu de Jacob.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Mais Salomon lui bâtit une maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Mais le Très-haut n’habite point dans des [demeures] faites de main; selon que dit le prophète:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '« Le ciel est mon trône, et la terre est le marchepied de mes pieds. Quelle maison me bâtirez-vous, dit le ✶Seigneur, et quel sera le lieu de mon repos?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Ma main n’a-t-elle pas fait toutes ces choses? ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Gens de cou roide et incirconcis de cœur et d’oreilles, vous résistez toujours à l’Esprit Saint; comme vos pères, vous aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Lequel des prophètes vos pères n’ont-ils pas persécuté? Et ils ont tué ceux qui ont prédit la venue du Juste, lequel maintenant vous, vous avez livré et mis à mort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'vous qui avez reçu la loi par la disposition des anges, et qui ne l’avez point gardée...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'En entendant ces choses, ils frémissaient de rage dans leurs cœurs, et ils grinçaient des dents contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Mais lui, étant plein de l’Esprit Saint, et ayant les yeux attachés sur le ciel, vit la gloire de Dieu, et Jésus debout à la droite de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'et il dit: Voici, je vois les cieux ouverts, et le Fils de l’homme debout à la droite de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Et criant à haute voix, ils bouchèrent leurs oreilles, et d’un commun accord se précipitèrent sur lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'et l’ayant poussé hors de la ville, ils le lapidaient; et les témoins déposèrent leurs vêtements aux pieds d’un jeune homme appelé Saul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Et ils lapidaient Étienne, qui priait et disait: Seigneur Jésus, reçois mon esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Et s’étant mis à genoux, il cria à haute voix: Seigneur, ne leur impute point ce péché. Et quand il eut dit cela, il s’endormit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'et Saul consentait à sa mort. Or en ce temps-là, il y eut une grande persécution contre l’assemblée qui était à Jérusalem; et tous furent dispersés dans les contrées de la Judée et de la Samarie, excepté les apôtres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Et des hommes pieux emportèrent Étienne pour l’ensevelir, et menèrent un grand deuil sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Or Saul ravageait l’assemblée, entrant dans les maisons; et traînant hommes et femmes, il les livrait [pour être jetés] en prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Ceux donc qui avaient été dispersés allaient çà et là, annonçant la parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Et Philippe, étant descendu dans une ville de la Samarie, leur prêcha le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Et les foules, d’un commun accord, étaient attentives aux choses que Philippe disait, l’entendant, et voyant les miracles qu’il faisait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'car les esprits immondes, criant à haute voix, sortaient de plusieurs qui en étaient possédés; et beaucoup de paralytiques et de boiteux furent guéris;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'et il y eut une grande joie dans cette ville-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Or, avant cela, il y avait dans la ville un homme nommé Simon, qui exerçait la magie et étonnait le peuple de la Samarie, se disant être quelque grand personnage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'auquel tous s’attachaient, depuis le petit jusqu’au grand, disant: Celui-ci est la puissance de Dieu appelée la grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Et ils s’attachaient à lui, parce que depuis longtemps il les étonnait par sa magie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Mais quand ils eurent cru Philippe qui leur annonçait les bonnes nouvelles touchant le royaume de Dieu et le nom de Jésus Christ, tant les hommes que les femmes furent baptisés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Et Simon crut aussi lui-même; et après avoir été baptisé, il se tenait toujours auprès de Philippe; et voyant les prodiges et les grands miracles qui se faisaient, il était dans l’étonnement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Or les apôtres qui étaient à Jérusalem, ayant appris que la Samarie avait reçu la parole de Dieu, leur envoyèrent Pierre et Jean,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'qui, étant descendus, prièrent pour eux, pour qu’ils reçoivent l’Esprit Saint:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'car il n’était encore tombé sur aucun d’eux, mais seulement ils avaient été baptisés pour le nom du seigneur Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Puis ils leur imposèrent les mains, et ils reçurent l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Or Simon, voyant que l’Esprit Saint était donné par l’imposition des mains des apôtres, leur offrit de l’argent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'disant: Donnez-moi aussi ce pouvoir, afin que tous ceux à qui j’imposerai les mains reçoivent l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Mais Pierre lui dit: Que ton argent périsse avec toi, parce que tu as pensé acquérir avec de l’argent le don de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Tu n’as ni part ni portion dans cette affaire; car ton cœur n’est pas droit devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Repens-toi donc de cette méchanceté, et supplie le Seigneur, afin que, si faire se peut, la pensée de ton cœur te soit pardonnée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'car je vois que tu es dans un fiel d’amertume et dans un lien d’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Et Simon, répondant, dit: Vous, suppliez le Seigneur pour moi, en sorte que rien ne vienne sur moi de ce dont vous avez parlé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Eux donc, après avoir rendu témoignage et avoir annoncé la parole du Seigneur, s’en retournaient à Jérusalem; et ils évangélisaient plusieurs villages des Samaritains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Et un ange du ✶Seigneur parla à Philippe, disant: Lève-toi, et va vers le midi, sur le chemin qui descend de Jérusalem à Gaza, lequel est désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Et lui, se levant, s’en alla. Et voici, un Éthiopien, eunuque, homme puissant à la cour de Candace, reine des Éthiopiens, intendant de tous ses trésors, et qui était venu pour adorer à Jérusalem,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 's’en retournait; et il était assis dans son char et lisait le prophète Ésaïe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Et l’Esprit dit à Philippe: Approche-toi et joins-toi à ce char.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Et Philippe étant accouru, l’entendit qui lisait le prophète Ésaïe; et il dit: Mais comprends-tu ce que tu lis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Et il dit: Comment donc le pourrais-je, si quelqu’un ne me conduit? Et il pria Philippe de monter et de s’asseoir avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Or le passage de l’écriture qu’il lisait était celui-ci: « Il a été mené comme une brebis à la boucherie; et comme un agneau, muet devant celui qui le tond, ainsi il n’ouvre point sa bouche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'dans son humiliation, son jugement a été ôté; et qui racontera sa génération? car sa vie est ôtée de la terre ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Et l’eunuque, répondant, dit à Philippe: Je te prie, de qui le prophète dit-il cela? De lui-même, ou de quelque autre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Et Philippe, ouvrant sa bouche et commençant par cette écriture, lui annonça Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Et comme ils continuaient leur chemin, ils arrivèrent à une eau, et l’eunuque dit: Voici de l’eau, qu’est-ce qui m’empêche d’être baptisé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, '');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Et il donna l’ordre qu’on arrête le char, et ils descendirent tous deux à l’eau, et Philippe et l’eunuque; et [Philippe] le baptisa.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Et, quand ils furent remontés hors de l’eau, l’Esprit du Seigneur enleva Philippe, et l’eunuque ne le vit plus, car il continua son chemin tout joyeux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'mais Philippe fut trouvé à Azot; et en passant au travers [du pays], il évangélisa toutes les villes, jusqu’à ce qu’il fut arrivé à Césarée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Or Saul, respirant encore menace et meurtre contre les disciples du Seigneur, alla au souverain sacrificateur');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'et lui demanda pour Damas des lettres [adressées] aux synagogues, en sorte que, s’il en trouvait quelques-uns qui soient de la voie, il les amène, hommes et femmes, liés à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Et, comme il était en chemin, il arriva qu’il approcha de Damas; et tout à coup une lumière brilla du ciel comme un éclair autour de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Et étant tombé par terre, il entendit une voix qui lui disait: Saul! Saul! pourquoi me persécutes-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Et il dit: Qui es-tu, Seigneur? Et il [dit]: Je suis Jésus que tu persécutes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Mais lève-toi, et entre dans la ville; et il te sera dit ce que tu dois faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Et les hommes qui faisaient route avec lui s’arrêtèrent tout interdits, entendant bien la voix, mais ne voyant personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Et Saul se leva de terre; et ses yeux étant ouverts, il ne voyait personne; et, le conduisant par la main, ils l’emmenèrent à Damas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'et il fut trois jours sans voir, et il ne mangea ni ne but.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Or il y avait à Damas un disciple nommé Ananias; et le Seigneur lui dit en vision: Ananias! Et il dit: Me voici, Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Et le Seigneur lui [dit]: Lève-toi, et va dans la rue appelée la Droite, et cherche dans la maison de Judas un nommé Saul, de Tarse; car voici, il prie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'et il a vu [en vision] un homme nommé Ananias, entrant et lui imposant la main pour qu’il recouvre la vue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Et Ananias répondit: Seigneur, j’ai entendu parler à plusieurs de cet homme, combien de maux il a faits à tes saints dans Jérusalem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'et ici il a pouvoir, de la part des principaux sacrificateurs, de lier tous ceux qui invoquent ton nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Mais le Seigneur lui dit: Va; car cet homme m’est un vase d’élection pour porter mon nom devant les nations et les rois, et les fils d’Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'car je lui montrerai combien il doit souffrir pour mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Et Ananias s’en alla, et entra dans la maison; et, lui imposant les mains, il dit: Saul, frère, le Seigneur, Jésus qui t’est apparu dans le chemin par où tu venais, m’a envoyé pour que tu recouvres la vue et que tu sois rempli de [l’]Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Et aussitôt il tomba de ses yeux comme des écailles; et il recouvra la vue; et se levant, il fut baptisé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'et ayant mangé, il reprit des forces. Et il fut quelques jours avec les disciples qui étaient à Damas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'et aussitôt il prêcha Jésus dans les synagogues, [disant] que lui est le Fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Et tous ceux qui l’entendaient étaient dans l’étonnement et disaient: N’est-ce pas celui-là qui a détruit à Jérusalem ceux qui invoquent ce nom, et qui est venu ici dans le but de les amener liés aux principaux sacrificateurs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Mais Saul se fortifiait de plus en plus, et confondait les Juifs qui demeuraient à Damas, démontrant que celui-ci était le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Et des jours en grand nombre s’étant écoulés, les Juifs tinrent conseil ensemble pour le tuer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'mais leur complot fut connu de Saul. Et ils surveillaient aussi les portes, jour et nuit, pour le tuer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Mais les disciples, le prenant de nuit, le descendirent par la muraille, en le dévalant dans une corbeille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Et étant arrivé à Jérusalem, il cherchait à se joindre aux disciples; et tous le craignaient, ne croyant pas qu’il soit disciple;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'mais Barnabas le prit et le mena aux apôtres, et leur raconta comment, sur le chemin, il avait vu le Seigneur, qui lui avait parlé, et comment il avait parlé ouvertement, à Damas, au nom de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Et il était avec eux à Jérusalem, allant et venant, et parlant ouvertement au nom du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Et il parlait et disputait avec les Hellénistes; mais ceux-ci tâchaient de le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Et les frères, l’ayant su, le menèrent à Césarée, et l’envoyèrent à Tarse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Les assemblées donc, par toute la Judée et la Galilée et la Samarie, étaient en paix, étant édifiées, et marchant dans la crainte du Seigneur; et elles croissaient par la consolation du Saint Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Or il arriva que, comme Pierre parcourait toute la contrée, il descendit aussi vers les saints qui habitaient Lydde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Et il trouva là un homme nommé Énée, qui depuis huit ans était couché sur un petit lit; et il était paralytique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Et Pierre lui dit: Énée! Jésus, le Christ, te guérit; lève-toi, et fais-toi toi-même ton lit. Et aussitôt il se leva.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Et tous ceux qui habitaient Lydde et le Saron le virent; et ils se tournèrent vers le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Or il y avait à Joppé une femme disciple, nommée Tabitha, qui, interprété, signifie Dorcas; elle était pleine de bonnes œuvres et d’aumônes qu’elle faisait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Et il arriva en ces jours-là, qu’étant tombée malade elle mourut; et quand ils l’eurent lavée, ils la mirent dans la chambre haute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Et comme Lydde est près de Joppé, les disciples ayant appris que Pierre était dans cette [ville], envoyèrent vers lui deux hommes, le priant: Ne tarde pas de venir jusqu’à nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Et Pierre, se levant, s’en alla avec eux. Et quand il fut arrivé, ils le menèrent dans la chambre haute; et toutes les veuves vinrent auprès de lui en pleurant, et en montrant les robes et les vêtements, toutes les choses que Dorcas avait faites pendant qu’elle était avec elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Mais Pierre, les ayant tous mis dehors et s’étant mis à genoux, pria; et, se tournant vers le corps, il dit: Tabitha, lève-toi. Et elle ouvrit ses yeux, et voyant Pierre, elle se mit sur son séant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, '– et lui ayant donné la main, il la leva; et ayant appelé les saints et les veuves, il la [leur] présenta vivante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Et cela fut connu dans tout Joppé; et plusieurs crurent au Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Et il arriva qu’il demeura plusieurs jours à Joppé, chez un certain Simon, corroyeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Or, à Césarée, un homme nommé Corneille, centurion de la cohorte appelée Italique,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'pieux et craignant Dieu avec toute sa maison, faisant beaucoup d’aumônes au peuple, et priant Dieu continuellement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'vit clairement en vision, environ vers la neuvième heure du jour, un ange de Dieu entrant auprès de lui et lui disant: Corneille!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Et, fixant les yeux sur lui et étant tout effrayé, il dit: Qu’est-ce, Seigneur? Et il lui dit: Tes prières et tes aumônes sont montées pour mémorial devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Et maintenant envoie des hommes à Joppé, et fais venir Simon qui est surnommé Pierre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'il est logé chez un certain Simon, corroyeur, qui a sa maison au bord de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Et quand l’ange qui lui parlait s’en fut allé, Corneille, ayant appelé deux de ses domestiques et un soldat pieux d’entre ceux qui se tenaient toujours auprès de lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'et leur ayant tout raconté, les envoya à Joppé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Or le lendemain, comme ils marchaient et qu’ils approchaient de la ville, Pierre monta sur le toit pour prier, vers la sixième heure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Et il eut très faim, et voulut manger; et comme on lui apprêtait [à manger], il lui survint une extase.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Et il voit le ciel ouvert, et un vase descendant comme une grande toile [liée] par les quatre coins et dévalée en terre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'dans laquelle il y avait tous les quadrupèdes et les reptiles de la terre, et les oiseaux du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Et une voix lui [fut adressée, disant]: Lève-toi, Pierre, tue et mange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Mais Pierre dit: Non point, Seigneur; car jamais je n’ai rien mangé qui soit impur ou immonde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Et une voix lui [fut adressée] encore, pour la seconde fois, [disant]: Ce que Dieu a purifié, toi, ne le tiens pas pour impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Et cela eut lieu par trois fois, et le vase fut aussitôt élevé au ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Et comme Pierre était en perplexité en lui-même à l’égard de ce qu’ était cette vision qu’il avait vue, voici aussi, les hommes envoyés de la part de Corneille, s’étant enquis de la maison de Simon, se tenaient à la porte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'et ayant appelé, ils demandèrent si Simon surnommé Pierre, logeait là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Et comme Pierre méditait sur la vision, l’Esprit lui dit: Voilà, trois hommes te cherchent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'mais lève-toi, et descends, et va avec eux sans hésiter, parce que c’est moi qui les ai envoyés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Et Pierre étant descendu vers les hommes, dit: Voici, moi, je suis celui que vous cherchez; quelle est la cause pour laquelle vous êtes venus?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Et ils dirent: Corneille, centurion, homme juste et craignant Dieu, et qui a un [bon] témoignage de toute la nation des Juifs, a été averti divinement par un saint ange de te faire venir dans sa maison et d’entendre des paroles de ta part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Les ayant donc fait entrer, il les logea; et le lendemain, se levant, il s’en alla avec eux; et quelques-uns des frères de Joppé allèrent avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Et le lendemain ils entrèrent à Césarée. Et Corneille les attendait, ayant assemblé ses parents et ses intimes amis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Et comme il arrivait que Pierre entrait, Corneille allant au-devant de lui se jeta à ses pieds et lui rendit hommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Mais Pierre le releva, disant: Lève-toi; et moi aussi je suis un homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Et conversant avec lui, il entra et trouva plusieurs personnes assemblées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Et il leur dit: Vous savez, vous, que c’est une chose illicite pour un Juif que de se lier avec un étranger, ou d’aller à lui; et Dieu m’a montré, à moi, à n’appeler aucun homme impur ou immonde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'C’est pourquoi aussi, lorsque vous m’avez envoyé chercher, je suis venu sans faire de difficulté. Je vous demande donc pour quel sujet vous m’avez fait venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Et Corneille dit: Il y a quatre jours que j’étais en jeûne jusqu’à cette heure-ci, et à la neuvième heure, je priais dans ma maison; et voici, un homme se tint devant moi dans un vêtement éclatant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'et dit: Corneille, ta prière est exaucée, et tes aumônes ont été rappelées en mémoire devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Envoie donc à Joppé, et fais venir Simon qui est surnommé Pierre; il loge dans la maison de Simon, corroyeur, au bord de la mer; et lorsqu’il sera venu, il te parlera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'J’ai donc aussitôt envoyé vers toi, et tu as bien fait de venir. Maintenant donc, nous sommes tous présents devant Dieu, pour entendre tout ce qui t’a été ordonné de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Et Pierre, ouvrant la bouche, dit: En vérité, je comprends que Dieu ne fait pas acception de personnes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'mais qu’en toute nation celui qui le craint et qui pratique la justice, lui est agréable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Vous connaissez la parole qu’il a envoyée aux fils d’Israël, annonçant la bonne nouvelle de la paix par Jésus Christ (lui est Seigneur de tous),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'ce qui a été annoncé par toute la Judée, en commençant par la Galilée, après le baptême que Jean a prêché,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, '– Jésus qui était de Nazareth, comment Dieu l’a oint de l’Esprit Saint et de puissance, lui qui a passé de lieu en lieu, faisant du bien, et guérissant tous ceux que le diable avait asservis à sa puissance; car Dieu était avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, '(et nous, nous sommes témoins de toutes les choses qu’il a faites, au pays des Juifs et à Jérusalem;) lequel aussi ils ont fait mourir, le pendant au bois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, '– celui-ci, Dieu l’a ressuscité le troisième jour, et l’a donné pour être manifesté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'non à tout le peuple, mais à des témoins qui avaient été auparavant choisis de Dieu, [savoir] à nous qui avons mangé et bu avec lui après qu’il eut été ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Et il nous a commandé de prêcher au peuple, et d’attester que c’est lui qui est établi de Dieu juge des vivants et des morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Tous les prophètes lui rendent témoignage, que, par son nom, quiconque croit en lui reçoit la rémission des péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Comme Pierre prononçait encore ces mots, l’Esprit Saint tomba sur tous ceux qui entendaient la parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Et les fidèles de la circoncision, tous ceux qui étaient venus avec Pierre, s’étonnèrent de ce que le don du Saint Esprit était répandu aussi sur les nations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'car ils les entendaient parler en langues et magnifier Dieu. Alors Pierre répondit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Quelqu’un pourrait-il refuser l’eau, afin que ceux-ci ne soient pas baptisés, eux qui ont reçu l’Esprit Saint comme nous-mêmes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Et il commanda qu’ils soient baptisés au nom du Seigneur. Alors ils le prièrent de demeurer [là] quelques jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Or les apôtres et les frères qui étaient en Judée apprirent que les nations aussi avaient reçu la parole de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Et quand Pierre fut monté à Jérusalem, ceux de la circoncision disputaient avec lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'disant: Tu es entré chez des hommes incirconcis, et tu as mangé avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Mais Pierre se mit à leur exposer [les choses] par ordre, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'J’étais en prière dans la ville de Joppé, et je vis dans une extase une vision, [savoir] un vase descendant comme une grande toile dévalée du ciel par les quatre coins; et elle vint jusqu’à moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'et y ayant jeté les yeux, je considérais, et je vis les quadrupèdes de la terre, et les bêtes sauvages, et les reptiles, et les oiseaux du ciel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'et j’entendis aussi une voix qui me dit: Lève-toi, Pierre, tue et mange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Et je dis: Non point, Seigneur; car jamais chose impure ou immonde n’entra dans ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Et une voix répondit pour la seconde fois du ciel: Ce que Dieu a purifié, toi, ne le tiens pas pour impur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Et cela eut lieu par trois fois, et tout fut de nouveau retiré dans le ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Et voici, aussitôt, trois hommes qui avaient été envoyés de Césarée vers moi, se trouvèrent devant la maison où j’étais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Et l’Esprit me dit d’aller avec eux sans hésiter; et les six frères que voici vinrent avec moi, et nous sommes entrés dans la maison de cet homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Et il nous raconta comment il avait vu dans sa maison l’ange qui, se tenant là, lui avait dit: Envoie à Joppé, et fais venir Simon qui est surnommé Pierre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'qui te dira des choses par lesquelles tu seras sauvé, toi et toute ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Et comme je commençais à parler, l’Esprit Saint tomba sur eux, comme aussi [il est tombé] sur nous au commencement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Et je me souvins de la parole du Seigneur, comment il a dit: Jean a baptisé avec de l’eau, mais vous, vous serez baptisés de l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Si donc Dieu leur a fait le même don qu’à nous qui avons cru au seigneur Jésus Christ, qui étais-je, moi, pour pouvoir l’interdire à Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Et ayant entendu ces choses, ils se turent, et glorifièrent Dieu disant: Dieu a donc en effet donné aux nations la repentance pour la vie!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Ceux donc qui avaient été dispersés par la tribulation qui arriva à l’occasion d’Étienne, passèrent jusqu’en Phénicie, et à Chypre, et à Antioche, n’annonçant la parole à personne, si ce n’est à des Juifs seulement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Mais quelques-uns d’entre eux étaient des Cypriotes et des Cyrénéens, qui, étant venus à Antioche, parlaient aussi aux Grecs, annonçant le seigneur Jésus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'et la main du Seigneur était avec eux; et un grand nombre, ayant cru, se tournèrent vers le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Et le bruit en vint aux oreilles de l’assemblée qui était à Jérusalem; et ils envoyèrent Barnabas pour passer jusqu’à Antioche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'lequel, y étant arrivé et ayant vu la grâce de Dieu, se réjouit; et il les exhortait tous à demeurer [attachés] au Seigneur de tout leur cœur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'car il était homme de bien et plein de l’Esprit Saint et de foi; et une grande foule fut ajoutée au Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Et il s’en alla à Tarse, pour chercher Saul;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'et l’ayant trouvé, il le mena à Antioche. Et il leur arriva que, pendant un an tout entier, ils se réunirent dans l’assemblée et enseignèrent une grande foule, – et que ce fut à Antioche premièrement que les disciples furent nommés chrétiens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'Or en ces jours-là, des prophètes descendirent de Jérusalem à Antioche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Et l’un d’entre eux, nommé Agabus, se leva et déclara par l’Esprit, qu’une grande famine aurait lieu dans toute la terre habitée, laquelle aussi eut lieu sous Claude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Et les disciples, chacun selon ses ressources, déterminèrent d’envoyer quelque chose pour le service des frères qui demeuraient en Judée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'ce qu’ils firent aussi, l’envoyant aux anciens par les mains de Barnabas et de Saul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Or vers ce temps-là, le roi Hérode mit les mains sur quelques-uns de ceux de l’assemblée pour les maltraiter,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'et il fit mourir par l’épée Jacques, le frère de Jean.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Et voyant que cela était agréable aux Juifs, il continua, en faisant prendre aussi Pierre; (or c’étaient les jours des pains sans levain;)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'et quand il l’eut fait prendre, il le mit en prison, et le livra à quatre bandes de quatre soldats chacune pour le garder, voulant, après la Pâque, le produire devant le peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Pierre donc était gardé dans la prison; mais l’assemblée faisait d’instantes prières à Dieu pour lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Mais lorsque Hérode allait le produire, cette nuit-là, Pierre dormait entre deux soldats, lié de deux chaînes; et des gardes, devant la porte, gardaient la prison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Et voici, un ange du ✶Seigneur survint, et une lumière resplendit dans la prison; et frappant le côté de Pierre, il le réveilla, disant: Lève-toi promptement. Et les chaînes tombèrent de ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Et l’ange lui dit: Ceins-toi et chausse tes sandales. Et il fit ainsi. Et il lui dit: Jette ton vêtement sur toi et suis-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Et sortant, il le suivit; et il ne savait pas que ce qui se faisait par l’ange était réel, mais il croyait voir une vision.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Et ayant passé la première et la seconde garde, ils vinrent à la porte de fer qui conduit à la ville, et elle s’ouvrit à eux d’elle-même; et, étant sortis, ils allèrent jusqu’au bout d’une rue; et aussitôt l’ange se retira d’avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Et Pierre, étant revenu à lui, dit: Je connais à présent certainement que le Seigneur a envoyé son ange, et m’a délivré de la main d’Hérode et de toute l’attente du peuple des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Et s’étant reconnu, il se rendit à la maison de Marie, mère de Jean surnommé Marc, où plusieurs étaient assemblés et priaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Et comme il heurtait à la porte du vestibule, une servante nommée Rhode vint pour écouter;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'et reconnaissant la voix de Pierre, de joie elle n’ouvrit point le vestibule; mais étant rentrée en courant, elle rapporta que Pierre se tenait devant le vestibule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Et ils lui dirent: Tu es folle. Mais elle affirmait qu’il en était ainsi. Et ils disaient: C’est son ange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Mais Pierre continuait à heurter; et quand ils eurent ouvert, ils le virent et furent hors d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Et leur ayant fait signe de la main de se taire, il leur raconta comment le Seigneur l’avait fait sortir de la prison; et il dit: Rapportez ces choses à Jacques et aux frères. Et sortant, il s’en alla en un autre lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Mais le jour étant venu, il y eut un grand trouble parmi les soldats au sujet de ce que Pierre était donc devenu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Et Hérode, l’ayant cherché et ne l’ayant pas trouvé, fit subir un interrogatoire aux gardes et donna ordre qu’ils soient emmenés au supplice. Et descendant de la Judée à Césarée, il y séjourna.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Or il était très irrité contre les Tyriens et les Sidoniens; mais ils vinrent à lui d’un commun accord, et ayant gagné Blaste le chambellan du roi, ils demandèrent la paix, parce que leur pays était nourri par celui du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Et, à un jour marqué, Hérode, revêtu d’une robe royale et assis sur une estrade, les haranguait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Et le peuple s’écriait: Voix d’un dieu et non pas d’un homme!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Et à l’instant un ange du ✶Seigneur le frappa, parce qu’il n’avait pas donné la gloire à Dieu; et, étant rongé par les vers, il expira.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Mais la parole de Dieu croissait et se multipliait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Et Barnabas et Saul, ayant accompli leur service, s’en retournèrent de Jérusalem, emmenant aussi avec eux Jean qui était surnommé Marc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Or il y avait à Antioche, dans l’assemblée qui était là, des prophètes et des docteurs: et Barnabas, et Siméon, appelé Niger, et Lucius le Cyrénéen, et Manahem, qui avait été nourri avec Hérode le tétrarque, et Saul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Et comme ils servaient le Seigneur et jeûnaient, l’Esprit Saint dit: Mettez-moi maintenant à part Barnabas et Saul, pour l’œuvre à laquelle je les ai appelés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Alors, ayant jeûné et prié, et leur ayant imposé les mains, ils les laissèrent aller.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Eux donc, ayant été envoyés par l’Esprit Saint, descendirent à Séleucie; et de là ils firent voile pour Chypre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Et quand ils furent à Salamine, ils annonçaient la parole de Dieu dans les synagogues des Juifs; et ils avaient aussi Jean pour serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Et ayant traversé toute l’île jusqu’à Paphos, ils trouvèrent un certain homme, un magicien, faux prophète juif, nommé Bar-Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'qui était avec le proconsul Serge Paul, homme intelligent. Celui-ci, ayant fait appeler Barnabas et Saul, demanda à entendre la parole de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Mais Élymas, le magicien (car c’est ainsi que son nom s’interprète), leur résistait, cherchant à détourner le proconsul de la foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Et Saul qui est aussi [appelé] Paul, étant rempli de l’Esprit Saint, fixant ses yeux sur lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'dit: Ô homme plein de toute fraude et de toute méchanceté, fils du diable, ennemi de toute justice, ne cesseras-tu pas de pervertir les voies droites du Seigneur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Et maintenant voici, la main du Seigneur est sur toi, et tu seras aveugle, sans voir le soleil pour un temps. Et à l’instant une obscurité et des ténèbres tombèrent sur lui; et se tournant de tous côtés, il cherchait quelqu’un qui le conduise par la main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Alors le proconsul, voyant ce qui était arrivé, crut, étant saisi par la doctrine du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Et faisant voile de Paphos, Paul et ses compagnons se rendirent à Perge de Pamphylie. Mais Jean, s’étant retiré d’avec eux, s’en retourna à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Et eux, étant partis de Perge, traversèrent [le pays] et arrivèrent à Antioche de Pisidie; et étant entrés dans la synagogue le jour du sabbat, ils s’assirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Et après la lecture de la loi et des prophètes, les chefs de la synagogue leur envoyèrent dire: Hommes frères, si vous avez quelque parole d’exhortation pour le peuple, parlez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Et Paul, s’étant levé et ayant fait signe de la main, dit: Hommes israélites, et vous qui craignez Dieu, écoutez:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Le Dieu de ce peuple choisit nos pères et éleva haut le peuple pendant son séjour au pays d’Égypte; et il les en fit sortir à bras élevé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Et il prit soin d’eux dans le désert, comme une mère, environ 40 ans;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'et ayant détruit sept nations au pays de Canaan, il leur en donna le pays en héritage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Et après ces choses, jusqu’à environ 450 ans, il leur donna des juges, jusqu’à Samuel le prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Et puis ils demandèrent un roi, et Dieu leur donna Saül, fils de Kis, homme de la tribu de Benjamin, pendant 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Et l’ayant ôté, il leur suscita David pour roi, duquel aussi il dit en lui rendant témoignage: J’ai trouvé David, le [fils] de Jessé, un homme selon mon cœur, qui fera toute ma volonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'De la semence de cet homme, Dieu, selon sa promesse, a amené à Israël un Sauveur, Jésus, –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Jean ayant déjà, immédiatement avant son arrivée, prêché le baptême de repentance à tout le peuple d’Israël.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Et comme Jean achevait sa course, il dit: Qui pensez-vous que je sois? Je ne le suis pas, moi; mais voici, il en vient un après moi, des pieds duquel je ne suis pas digne de délier la sandale.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Hommes frères, fils de la race d’Abraham, à vous et à ceux qui parmi vous craignent Dieu, la parole de ce salut est envoyée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'car ceux qui habitent à Jérusalem et leurs chefs, n’ayant pas connu [Jésus], ni les voix des prophètes qui se lisent chaque sabbat, ont accompli celles-ci en le jugeant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Et quoiqu’ils n’aient trouvé [en lui] aucun crime [qui soit digne] de mort, ils prièrent Pilate de le faire mourir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Et après qu’ils eurent accompli toutes les choses qui sont écrites de lui, ils le descendirent du bois et le mirent dans un sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Mais Dieu l’a ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Et il a été vu pendant plusieurs jours par ceux qui étaient montés avec lui de la Galilée à Jérusalem, qui sont maintenant ses témoins auprès du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Et nous, nous vous annonçons la bonne nouvelle quant à la promesse qui a été faite aux pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'que Dieu l’a accomplie envers nous, leurs enfants, ayant suscité Jésus; comme aussi il est écrit dans le psaume second: « Tu es mon Fils, moi je t’ai aujourd’hui engendré ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Or qu’il l’ait ressuscité d’entre les morts, pour ne devoir plus retourner à la corruption, il l’a dit ainsi: « Je vous donnerai les grâces assurées de David ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'C’est pourquoi il dit aussi dans un autre endroit: « Tu ne permettras point que ton saint voie la corruption ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Car David, après avoir, en sa propre génération, servi au conseil de Dieu, s’est endormi, et a été réuni à ses pères, et a vu la corruption;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'mais celui que Dieu a ressuscité, n’a pas vu la corruption.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Sachez donc, hommes frères, que par lui vous est annoncée la rémission des péchés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'et que de tout ce dont vous n’avez pu être justifiés par la loi de Moïse, quiconque croit est justifié par lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Prenez donc garde qu’il ne vous arrive ce qui est dit dans les prophètes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '« Voyez, contempteurs, et étonnez-vous, et soyez anéantis; car moi, je fais une œuvre en vos jours, une œuvre que vous ne croiriez point, si quelqu’un vous la racontait ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Et comme ils sortaient, ils demandèrent que ces paroles leur soient annoncées le sabbat suivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Et la synagogue s’étant dissoute, plusieurs des Juifs et des prosélytes qui servaient [Dieu] suivirent Paul et Barnabas qui, leur parlant, les exhortaient à persévérer dans la grâce de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Et le sabbat suivant, presque toute la ville fut assemblée pour entendre la parole de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'mais les Juifs, voyant les foules, furent remplis de jalousie et contredirent ce que Paul disait, contredisant et blasphémant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Et Paul et Barnabas, s’enhardissant, dirent: C’était à vous premièrement qu’il fallait annoncer la parole de Dieu; mais puisque vous la rejetez, et que vous vous jugez vous-mêmes indignes de la vie éternelle, voici, nous nous tournons vers les nations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'car le Seigneur nous a commandé ainsi: « Je t’ai établi pour être la lumière des nations, afin que tu sois en salut jusqu’au bout de la terre ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Et lorsque ceux des nations entendirent cela, ils s’en réjouirent, et ils glorifièrent la parole du Seigneur; et tous ceux qui étaient destinés à la vie éternelle crurent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Et la parole du Seigneur se répandait par tout le pays.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Mais les Juifs excitèrent les femmes de qualité qui servaient [Dieu] et les principaux de la ville; et ils suscitèrent une persécution contre Paul et Barnabas, et les chassèrent de leur territoire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Mais eux, ayant secoué contre eux la poussière de leurs pieds, s’en vinrent à Iconium.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Et les disciples étaient remplis de joie et de l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Or il arriva qu’à Iconium ils entrèrent ensemble dans la synagogue des Juifs, et parlèrent de telle sorte qu’une grande multitude de Juifs et de Grecs crurent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Mais les Juifs qui ne croyaient pas émurent et irritèrent les esprits [de ceux] des nations contre les frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Ils séjournèrent donc là assez longtemps, parlant hardiment, [appuyés] sur le Seigneur, qui rendait témoignage à la parole de sa grâce, accordant que des miracles et des prodiges se fassent par leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Mais la multitude de la ville fut partagée, et les uns étaient avec les Juifs, et les autres avec les apôtres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Et ceux des nations et les Juifs avec leurs chefs s’étant soulevés pour les outrager et pour les lapider,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, '– eux l’ayant su, s’enfuirent aux villes de Lycaonie, à Lystre et à Derbe et dans les environs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'et ils y évangélisaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Et [il y avait] à Lystre un homme impotent de ses pieds, [qui] se tenait assis; perclus dès le ventre de sa mère, il n’avait jamais marché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Cet homme entendait parler Paul qui, fixant ses yeux sur lui et voyant qu’il avait la foi pour être guéri,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, '[lui] dit à haute voix: Lève-toi droit sur tes pieds. Et il sautait et marchait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Et les foules, ayant vu ce que Paul avait fait, élevèrent leur voix, disant en lycaonien: Les dieux, s’étant faits semblables aux hommes, sont descendus vers nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Et ils appelaient Barnabas Jupiter, et Paul Mercure, parce que c’était lui qui portait la parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Et le sacrificateur du Jupiter qui était devant la ville, ayant amené des taureaux et des couronnes jusqu’aux portes, voulait sacrifier avec les foules.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Mais les apôtres, Barnabas et Paul, l’ayant appris, déchirèrent leurs vêtements et s’élancèrent dans la foule, s’écriant');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'et disant: Hommes, pourquoi faites-vous ces choses? Nous sommes, nous aussi, des hommes ayant les mêmes passions que vous; et nous vous annonçons que de ces choses vaines vous vous tourniez vers le Dieu vivant, qui a fait le ciel, et la terre, et la mer, et toutes les choses qui y sont;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'lequel dans les générations passées a laissé toutes les nations marcher dans leurs propres voies;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'quoique cependant il ne se soit pas laissé sans témoignage, en faisant du bien, en vous donnant du ciel des pluies et des saisons fertiles, remplissant vos cœurs de nourriture et de joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Et en disant ces choses, à peine empêchèrent-ils les foules de leur sacrifier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Mais des Juifs arrivèrent d’Antioche et d’Iconium; et ayant gagné les foules et lapidé Paul, ils le traînèrent hors de la ville, croyant qu’il était mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Mais comme les disciples se tenaient autour de lui, se levant, il entra dans la ville; et le lendemain il s’en alla avec Barnabas à Derbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Et ayant évangélisé cette ville-là et fait beaucoup de disciples, ils s’en retournèrent à Lystre, et à Iconium, et à Antioche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'fortifiant les âmes des disciples, les exhortant à persévérer dans la foi, et [les avertissant] que c’est par beaucoup d’afflictions qu’il nous faut entrer dans le royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Et leur ayant choisi des anciens dans chaque assemblée, ils prièrent avec jeûne, et les recommandèrent au Seigneur en qui ils avaient cru.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Et ayant traversé la Pisidie, ils vinrent en Pamphylie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'et ayant annoncé la parole à Perge, ils descendirent à Attalie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'et de là ils se rendirent par mer à Antioche, d’où ils avaient été recommandés à la grâce de Dieu pour l’œuvre qu’ils avaient accomplie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Et, étant arrivés, et ayant réuni l’assemblée, ils racontèrent toutes les choses que Dieu avait faites avec eux, et comment il avait ouvert aux nations la porte de la foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Et ils séjournèrent assez longtemps avec les disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Et quelques-uns, étant descendus de Judée, enseignaient les frères [disant]: Si vous n’avez pas été circoncis selon l’usage de Moïse, vous ne pouvez être sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Une contestation s’étant donc élevée et une grande dispute, entre Paul et Barnabas et eux, ils résolurent que Paul et Barnabas et quelques autres d’entre eux monteraient à Jérusalem vers les apôtres et les anciens pour cette question.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Eux donc, ayant été accompagnés par l’assemblée, traversèrent la Phénicie et la Samarie, racontant la conversion des nations; et ils causèrent une grande joie à tous les frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Et étant arrivés à Jérusalem, ils furent reçus par l’assemblée et les apôtres et les anciens; et ils racontèrent toutes les choses que Dieu avait faites avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Et quelques-uns de la secte des pharisiens, qui avaient cru, s’élevèrent, disant qu’il faut les circoncire et leur enjoindre de garder la loi de Moïse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Et les apôtres et les anciens s’assemblèrent pour examiner cette affaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Et une grande discussion ayant eu lieu, Pierre se leva et leur dit: Hommes frères, vous savez vous-mêmes que, dès les jours anciens, Dieu m’a choisi entre vous, afin que par ma bouche les nations entendent la parole de l’évangile, et qu’elles croient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Et Dieu qui connaît les cœurs, leur a rendu témoignage, leur ayant donné l’Esprit Saint comme à nous-mêmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'et il n’a fait aucune différence entre nous et eux, ayant purifié leurs cœurs par la foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Maintenant donc, pourquoi tentez-vous Dieu, en mettant sur le cou des disciples un joug que ni nos pères ni nous n’avons pu porter?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Mais nous croyons être sauvés par la grâce du seigneur Jésus, de la même manière qu’eux aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Et toute la multitude se tut; et ils écoutaient Barnabas et Paul qui racontaient quels miracles et quels prodiges Dieu avait faits par leur moyen parmi les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Et après qu’ils se furent tus, Jacques répondit, disant: Hommes frères, écoutez-moi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Siméon a raconté comment Dieu a premièrement visité les nations pour en tirer un peuple pour son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Et avec cela s’accordent les paroles des prophètes, selon qu’il est écrit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '« Après ces choses, je retournerai et je réédifierai le tabernacle de David, qui est tombé, et je réédifierai ses ruines et je le relèverai,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'en sorte que le résidu des hommes recherche le ✶Seigneur, et toutes les nations sur lesquelles mon nom est réclamé, dit le ✶Seigneur, qui fait ces choses »');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'connues de tout temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'C’est pourquoi moi, je suis d’avis de ne pas inquiéter ceux des nations qui se tournent vers Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'mais de leur écrire qu’ils s’abstiennent des souillures des idoles, et de la fornication, et de ce qui est étouffé, et du sang;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'car Moïse, dès les générations anciennes, a dans chaque ville ceux qui le prêchent, étant lu dans les synagogues chaque sabbat.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Alors il sembla bon aux apôtres et aux anciens, avec toute l’assemblée, de choisir parmi eux des hommes, et de les envoyer à Antioche avec Paul et Barnabas: [savoir] Judas appelé Barsabbas, et Silas, hommes [d’entre ceux] qui tenaient la première place parmi les frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Et ils écrivirent par leur main en ces termes: Les apôtres et les anciens et les frères, aux frères d’entre les nations qui sont à Antioche et en Syrie et en Cilicie: Salut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Comme nous avons entendu dire que quelques-uns qui sont sortis d’entre nous, vous ont troublés par des discours, bouleversant vos âmes, [disant qu’il faut être circoncis et garder la loi], (auxquels nous n’avons donné aucun ordre,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'il nous a semblé bon, étant tous d’accord, de choisir parmi nous des hommes et de les envoyer vers vous avec nos bien-aimés Barnabas et Paul,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'hommes qui ont exposé leurs vies pour le nom de notre seigneur Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Nous avons donc envoyé Judas et Silas, qui vous annonceront de bouche les mêmes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Car il a semblé bon au Saint Esprit et à nous de ne mettre sur vous aucun autre fardeau que ces choses-ci qui sont nécessaires:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'qu’on s’abstienne des choses sacrifiées aux idoles, et du sang, et de ce qui est étouffé, et de la fornication. Si vous vous gardez de ces choses, vous ferez bien. Portez-vous bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Eux donc ayant été congédiés, vinrent à Antioche, et ayant assemblé la multitude, ils remirent la lettre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Et l’ayant lue, ils se réjouirent de la consolation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Et Judas et Silas qui eux aussi étaient prophètes, exhortèrent les frères par plusieurs discours et les fortifièrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Et après avoir séjourné là quelque temps, ils furent renvoyés en paix par les frères vers ceux qui les avaient envoyés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Et Paul et Barnabas séjournèrent à Antioche, enseignant et annonçant, avec plusieurs autres aussi, la parole du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Et quelques jours après, Paul dit à Barnabas: Retournons maintenant visiter les frères par toutes les villes où nous avons annoncé la parole du Seigneur, [pour voir] comment ils vont.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Et Barnabas se proposait de prendre avec eux Jean aussi, appelé Marc.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Mais Paul trouvait bon de ne pas prendre avec eux un homme qui les avait abandonnés dès la Pamphylie et qui n’était pas allé à l’œuvre avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Il y eut donc [entre eux] de l’irritation, en sorte qu’ils se séparèrent l’un de l’autre, et que Barnabas, prenant Marc, fit voile pour Chypre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Mais Paul, ayant fait choix pour lui de Silas, partit, après avoir été recommandé à la grâce du Seigneur par les frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Et il parcourait la Syrie et la Cilicie, fortifiant les assemblées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Et il arriva à Derbe et à Lystre. Et voici, il y avait là un disciple nommé Timothée, fils d’une femme juive croyante, mais d’un père grec,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'lequel avait un [bon] témoignage des frères qui étaient à Lystre et à Iconium.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Paul voulut que celui-ci aille avec lui, et l’ayant pris, il le circoncit, à cause des Juifs qui étaient dans ces lieux-là; car tous, ils savaient que son père était Grec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Et comme ils passaient par les villes, ils leur remirent pour les garder, les ordonnances établies par les apôtres et les anciens qui étaient à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Les assemblées donc étaient affermies dans la foi et croissaient en nombre chaque jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Et ils traversèrent la Phrygie et le pays de Galatie, ayant été empêchés par le Saint Esprit d’annoncer la parole en Asie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'et étant venus jusqu’en Mysie, ils essayèrent de se rendre en Bithynie, mais l’Esprit de Jésus ne le leur permit pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Mais ayant passé par la Mysie, ils descendirent dans la Troade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Et Paul vit de nuit une vision: un homme macédonien se tenait là, le priant et disant: Passe en Macédoine et aide-nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Et quand il eut vu la vision, aussitôt nous avons cherché à partir pour la Macédoine, concluant que le Seigneur nous avait appelés à les évangéliser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Quittant donc la Troade, nous avons fait voile, tirant droit sur Samothrace, et le lendemain à Néapolis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'et de là à Philippes, qui est la première ville du quartier de la Macédoine, [et] une colonie; et nous avons séjourné quelques jours dans cette ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Et le jour du sabbat, nous sommes sortis hors de la porte [et nous nous sommes rendus] au bord du fleuve, où l’on avait coutume de faire la prière; et, nous étant assis, nous parlions aux femmes qui étaient assemblées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Et une femme nommée Lydie, marchande de pourpre de la ville de Thyatire, qui servait Dieu, écoutait; et le Seigneur lui ouvrit le cœur pour qu’elle soit attentive aux choses que Paul disait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Et après qu’elle eut été baptisée ainsi que sa maison, elle [nous] pria, disant: Si vous jugez que je suis fidèle au Seigneur, entrez dans ma maison, et demeurez-y. Et elle nous y contraignit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Or il arriva que, comme nous allions à la prière, une servante qui avait un esprit de python et qui, en prophétisant, procurait à ses maîtres un grand gain, vint au-devant de nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Et marchant après Paul et nous, elle criait, disant: Ces hommes sont les esclaves du Dieu Très-haut, qui vous annoncent la voie du salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Et elle fit cela pendant plusieurs jours. Mais Paul, affligé, se retourna et dit à l’esprit: Je te commande au nom de Jésus Christ de sortir d’elle. Et à l’heure même il sortit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Mais ses maîtres, voyant que l’espérance de leur gain s’en était allée, ayant saisi Paul et Silas les traînèrent dans la place publique devant les magistrats.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Et les ayant présentés aux préteurs, ils dirent: Ces hommes-ci, qui sont Juifs, mettent tout en trouble dans notre ville');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'et annoncent des coutumes qu’il ne nous est pas permis de recevoir ni de pratiquer, à nous qui sommes Romains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Et la foule se souleva ensemble contre eux; et les préteurs, leur ayant fait arracher leurs vêtements, donnèrent l’ordre de les fouetter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Et leur ayant fait donner un grand nombre de coups, ils les jetèrent en prison, en commandant au geôlier de les garder sûrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Celui-ci, ayant reçu un tel ordre, les jeta dans la prison intérieure et fixa sûrement leurs pieds dans le bois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Or sur le minuit, Paul et Silas, en priant, chantaient les louanges de Dieu; et les prisonniers les écoutaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Et tout d’un coup il se fit un grand tremblement de terre, de sorte que les fondements de la prison furent ébranlés; et au même instant toutes les portes s’ouvrirent, et les liens de tous furent détachés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Et le geôlier, s’étant éveillé et voyant les portes de la prison ouvertes, tira son épée et allait se tuer, croyant que les prisonniers s’étaient enfuis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Mais Paul cria à haute voix, disant: Ne te fais point de mal, car nous sommes tous ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Et ayant demandé de la lumière, le geôlier s’élança dans [la prison], et tout tremblant il se jeta aux pieds de Paul et de Silas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Et les ayant menés dehors, il dit: Seigneurs, que faut-il que je fasse pour être sauvé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Et ils dirent: Crois au seigneur Jésus, et tu seras sauvé, toi et ta maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Et ils lui annoncèrent la parole du Seigneur, ainsi qu’à tous ceux qui étaient dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Et il les prit en cette même heure de la nuit, et lava leurs plaies; et sur-le-champ il fut baptisé, lui et tous les siens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Et il les fit monter dans sa maison, et fit dresser une table; et croyant Dieu, il se réjouit avec toute sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Et le jour étant venu, les préteurs envoyèrent les licteurs, disant: Relâche ces hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Et le geôlier rapporta ces paroles à Paul, [disant]: Les préteurs ont envoyé afin que vous soyez relâchés; sortez donc maintenant, et allez-vous-en en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Mais Paul leur dit: Après nous avoir fait battre publiquement, sans que nous soyons condamnés, nous qui sommes Romains, ils nous ont jetés en prison; et maintenant ils nous mettent dehors en secret! Non certes, mais qu’ils viennent eux-mêmes et qu’ils nous mènent dehors!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Les licteurs rapportèrent ces paroles aux préteurs; et ils eurent peur, ayant appris qu’ils étaient Romains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'Et ils vinrent et les prièrent [de se rendre à leur vœu], et les ayant menés dehors, leur demandèrent de sortir de la ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Et étant sortis de la prison, ils entrèrent chez Lydie; et ayant vu les frères, ils les exhortèrent et partirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Et ayant traversé Amphipolis et Apollonie, ils vinrent à Thessalonique, où était la synagogue des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Et selon sa coutume, Paul entra vers eux, et, pendant trois sabbats, il discourut avec eux d’après les écritures,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'expliquant et exposant qu’il fallait que le Christ souffre et qu’il ressuscite d’entre les morts; – et [disant], que celui-ci, Jésus, que moi je vous annonce, est le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Et quelques-uns d’entre eux furent persuadés et se joignirent à Paul et à Silas, et une grande multitude de Grecs qui servaient [Dieu], et des femmes de premier rang en assez grand nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Mais les Juifs, pleins de jalousie, ayant pris quelques méchants hommes de la populace, et ayant fait un amas de peuple, troublèrent la ville, et ayant assailli la maison de Jason, ils cherchèrent Paul et Silas pour les amener au peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Mais ne les ayant pas trouvés, ils traînèrent Jason et quelques frères devant les magistrats de la ville, en criant: Ces gens qui ont bouleversé la terre habitée, sont aussi venus ici;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'et Jason les a reçus chez lui, et ils contreviennent tous aux ordonnances de César, disant qu’il y a un autre roi, Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Et la foule et les magistrats de la ville, qui entendaient ces choses, furent troublés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Et après avoir reçu caution de Jason et des autres, ils les relâchèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Et aussitôt les frères envoyèrent Paul et Silas, de nuit, à Bérée, lesquels étant arrivés, entrèrent dans la synagogue des Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Or ceux-ci étaient plus nobles que ceux de Thessalonique; et ils reçurent la parole avec toute bonne volonté, examinant chaque jour les écritures [pour voir] si les choses étaient ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Plusieurs donc d’entre eux crurent, et des femmes grecques de qualité et des hommes aussi, en assez grand nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Mais quand les Juifs de Thessalonique surent que la parole de Dieu était aussi annoncée par Paul à Bérée, ils y vinrent aussi, agitant les foules.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Mais alors les frères renvoyèrent aussitôt Paul, comme pour aller à la mer; mais Silas et Timothée demeurèrent encore là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Et ceux qui conduisaient Paul le menèrent jusqu’à Athènes; et après avoir reçu pour Silas et pour Timothée l’ordre de le rejoindre au plus tôt, ils partirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Et comme Paul les attendait à Athènes, son esprit était excité au-dedans de lui, en voyant la ville remplie d’idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Il discourait donc dans la synagogue avec les Juifs et avec ceux qui servaient [Dieu], et tous les jours sur la place publique avec ceux qui s’y rencontraient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Et quelques-uns aussi des philosophes épicuriens et des philosophes stoïciens s’en prirent à lui; et les uns disaient: Que veut dire ce discoureur? et d’autres: Il semble annoncer des divinités étrangères; parce qu’il leur annonçait Jésus et la résurrection.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Et l’ayant pris, ils le menèrent à l’Aréopage, disant: Pourrions-nous savoir quelle est cette nouvelle doctrine dont tu parles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'car tu nous fais entendre certaines choses étranges; nous voudrions donc savoir ce que veulent dire ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Or tous les Athéniens et les étrangers séjournant [à Athènes], ne passaient leur temps à autre chose qu’à dire ou à écouter quelque nouvelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Mais Paul, se tenant au milieu de l’Aréopage, dit: Hommes athéniens, je vois qu’en toutes choses vous êtes voués au culte des divinités;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'car, en passant et en contemplant les objets de votre culte, j’ai trouvé aussi un autel sur lequel était inscrit: Au dieu inconnu! Celui donc que vous honorez sans le connaître, c’est celui que moi je vous annonce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Le Dieu qui a fait le monde et toutes les choses qui y sont, lui qui est le Seigneur du ciel et de la terre, n’habite pas dans des temples faits de main;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'et il n’est pas servi par des mains d’hommes, comme s’il avait besoin de quelque chose, lui qui donne à tous la vie et la respiration et toutes choses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'et il a fait d’un seul sang toutes les races des hommes pour habiter sur toute la face de la terre, ayant déterminé les temps ordonnés et les bornes de leur habitation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'pour qu’ils cherchent Dieu, s’ils pourraient en quelque sorte le toucher en tâtonnant et le trouver, quoiqu’il ne soit pas loin de chacun de nous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'car en lui nous vivons et nous nous mouvons et nous sommes, comme aussi quelques-uns de vos poètes ont dit: “Car aussi nous sommes sa race.”');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Étant donc la race de Dieu, nous ne devons pas penser que la divinité soit semblable à de l’or, ou à de l’argent, ou à de la pierre, à une œuvre sculptée de l’art et de l’imagination de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Dieu donc, ayant passé par-dessus les temps de l’ignorance, ordonne maintenant aux hommes que tous, en tous lieux, ils se repentent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'parce qu’il a établi un jour auquel il doit juger en justice la terre habitée, par l’homme qu’il a destiné [à cela], de quoi il a donné une preuve certaine à tous, l’ayant ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Mais quand ils entendirent parler de la résurrection des morts, les uns s’en moquaient, et les autres disaient: Nous t’entendrons encore sur ce sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Ainsi Paul sortit du milieu d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Mais quelques hommes se joignirent à lui et crurent, entre lesquels aussi était Denys, l’Aréopagite, et une femme nommée Damaris, et d’autres avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Après cela, étant parti d’Athènes, il vint à Corinthe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'et ayant trouvé un Juif, nommé Aquilas, originaire du Pont, tout récemment venu d’Italie, ainsi que Priscilla sa femme (parce que Claude avait commandé que tous les Juifs sortent de Rome), il alla à eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'et parce qu’il était du même métier, il demeura avec eux et travaillait, car leur métier était de faire des tentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Et chaque sabbat, il discourait dans la synagogue et persuadait Juifs et Grecs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Et quand et Silas et Timothée furent descendus de Macédoine, Paul était étreint par la parole, rendant témoignage aux Juifs que Jésus était le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Et comme ils s’opposaient et blasphémaient, il secoua ses vêtements et leur dit: Que votre sang soit sur votre tête! Moi, je suis net: désormais je m’en irai vers les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Et étant parti de là, il entra dans la maison d’un nommé Juste qui servait Dieu, et dont la maison tenait à la synagogue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Mais Crispus, le chef de synagogue, crut au Seigneur avec toute sa maison; et plusieurs des Corinthiens l’ayant entendu, crurent et furent baptisés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Or le Seigneur dit de nuit, dans une vision, à Paul: Ne crains point, mais parle et ne te tais point,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'parce que je suis avec toi; et personne ne mettra les mains sur toi pour te faire du mal, parce que j’ai un grand peuple dans cette ville.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Et il demeura là un an et six mois, enseignant parmi eux la parole de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Mais pendant que Gallion était proconsul d’Achaïe, les Juifs, d’un commun accord, s’élevèrent contre Paul et l’amenèrent devant le tribunal,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'disant: Cet homme persuade les hommes de servir Dieu contrairement à la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Et comme Paul allait ouvrir la bouche, Gallion dit aux Juifs: S’ il s’agissait de quelque injustice ou de quelque méchante fourberie, ô Juifs, je vous supporterais à bon droit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'mais si ce sont des questions de paroles, et de noms, et de votre loi, vous y mettrez ordre vous-mêmes, [car] moi, je ne veux pas être juge de ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Et il les chassa de devant le tribunal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Et ayant tous saisi Sosthène, le chef de synagogue, ils le battaient devant le tribunal; et Gallion ne se mettait pas en peine de tout cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Et Paul, ayant demeuré là encore assez longtemps, prit congé des frères et mit à la voile pour la Syrie, et avec lui Priscilla et Aquilas, après qu’il se fut fait raser la tête à Cenchrée, car il avait fait un vœu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Et il arriva à Éphèse et les y laissa; mais étant entré lui-même dans la synagogue, il discourut avec les Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Mais lorsqu’ils le prièrent de demeurer plus longtemps avec eux, il n’y consentit pas,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'mais il prit congé d’eux, disant: [Il faut absolument que je célèbre la fête prochaine à Jérusalem]; je reviendrai vers vous, si Dieu le veut. Et il partit d’Éphèse par mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Et ayant abordé à Césarée, il monta et salua l’assemblée, et descendit à Antioche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Et ayant séjourné là quelque temps, il s’en alla, et traversa successivement le pays de Galatie et la Phrygie, fortifiant tous les disciples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Et il vint à Éphèse un Juif, nommé Apollos, Alexandrin d’origine, homme éloquent et puissant dans les écritures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Il était instruit dans la voie du Seigneur; et, étant fervent d’esprit, il parlait et enseignait diligemment les choses qui concernaient Jésus, ne connaissant que le baptême de Jean.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Et il se mit à parler avec hardiesse dans la synagogue. Et Aquilas et Priscilla, l’ayant entendu, le prirent et lui expliquèrent plus exactement la voie de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Et comme il se proposait de passer en Achaïe, les frères écrivirent aux disciples et les exhortèrent à le recevoir; et quand il y fut arrivé, il contribua beaucoup par la grâce à [l’avancement de] ceux qui avaient cru;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'car il réfutait publiquement les Juifs avec une grande force, démontrant par les écritures que Jésus était le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Or il arriva, comme Apollos était à Corinthe, que Paul, après avoir traversé les contrées supérieures, vint à Éphèse; et ayant trouvé de certains disciples,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'il leur dit: Avez-vous reçu l’Esprit Saint après avoir cru? Et ils lui [dirent]: Mais nous n’avons même pas entendu dire si l’Esprit Saint est.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Et il dit: De quel [baptême] donc avez-vous été baptisés? Et ils dirent: Du baptême de Jean.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Et Paul dit: Jean a baptisé du baptême de la repentance, disant au peuple qu’ils croient en celui qui venait après lui, c’est-à-dire en Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Et ayant entendu [ces choses], ils furent baptisés pour le nom du Seigneur Jésus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'et, Paul leur ayant imposé les mains, l’Esprit Saint vint sur eux, et ils parlèrent en langues et prophétisèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Et ils étaient en tout environ douze hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Et étant entré dans la synagogue, il parla avec hardiesse, discourant pendant trois mois et les persuadant des choses du royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Mais comme quelques-uns s’endurcissaient et étaient rebelles, disant du mal de la voie devant la multitude, lui, s’étant retiré d’avec eux, sépara les disciples, discourant tous les jours dans l’école de Tyrannus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Et cela continua pendant deux ans, de sorte que tous ceux qui demeuraient en Asie entendirent la parole du Seigneur, tant Juifs que Grecs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Et Dieu faisait des miracles extraordinaires par les mains de Paul,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'de sorte que même on portait de dessus son corps des mouchoirs et des tabliers sur les infirmes; et les maladies les quittaient, et les esprits malins sortaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Mais quelques-uns aussi des Juifs exorcistes qui couraient çà et là, essayèrent d’invoquer le nom du seigneur Jésus sur ceux qui avaient des esprits malins, disant: Je vous adjure par Jésus que Paul prêche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Et il y avait sept fils de Scéva, Juif, principal sacrificateur, qui faisaient cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Mais l’esprit malin, répondant, leur dit: Je connais Jésus et je sais qui est Paul; mais vous, qui êtes-vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Et l’homme en qui était l’esprit malin, s’élança sur eux, et, s’étant rendu maître des deux, usa de violence contre eux, de sorte qu’ils s’enfuirent de cette maison, nus et blessés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Et cela vint à la connaissance de tous ceux qui demeuraient à Éphèse, Juifs et Grecs; et ils furent tous saisis de crainte, et le nom du seigneur Jésus était magnifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Et plusieurs de ceux qui avaient cru, venaient, confessant et déclarant ce qu’ils avaient fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Plusieurs aussi de ceux qui s’étaient adonnés à des pratiques curieuses, apportèrent leurs livres et les brûlèrent devant tous; et ils en supputèrent le prix, et ils trouvèrent [qu’il se montait à] 50 000 pièces d’argent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'C’est avec une telle puissance que la parole du Seigneur croissait et montrait sa force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Or, après que ces choses se furent accomplies, Paul se proposa dans son esprit de passer par la Macédoine et par l’Achaïe, et d’aller à Jérusalem, disant: Après que j’aurai été là, il faut que je voie Rome aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Et ayant envoyé en Macédoine deux de ceux qui le servaient, Timothée et Éraste, il demeura lui-même quelque temps en Asie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Or il y eut en ce temps-là un grand trouble au sujet de la voie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'car un certain homme nommé Démétrius, qui travaillait en argenterie et faisait des temples de Diane en argent, procurait un grand profit aux artisans;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'et il les assembla, ainsi que ceux qui travaillaient à de semblables ouvrages, et dit: Ô hommes, vous savez que notre bien-être vient de ce travail;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'et vous voyez et apprenez que non seulement à Éphèse, mais presque par toute l’Asie, ce Paul, usant de persuasion, a détourné une grande foule, disant que ceux-là ne sont pas des dieux, qui sont faits de main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Et non seulement il y a du danger pour nous que cette partie ne tombe en discrédit, mais aussi que le temple de la grande déesse Diane ne soit plus rien estimé, et qu’il n’arrive que sa majesté, laquelle l’Asie entière et la terre habitée révère, soit anéantie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Et quand ils eurent entendu [ces choses], ils furent remplis de colère, et s’écriaient, disant: Grande est la Diane des Éphésiens!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Et [toute] la ville fut remplie de confusion; et, d’un commun accord, ils se précipitèrent dans le théâtre, entraînant avec eux Gaïus et Aristarque, Macédoniens, compagnons de voyage de Paul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Et comme Paul voulait entrer vers le peuple, les disciples ne le lui permirent pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'et quelques-uns aussi des Asiarques, qui étaient ses amis, envoyèrent vers lui pour le prier de ne pas s’aventurer dans le théâtre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Les uns donc criaient une chose, les autres une autre; car l’assemblée était en confusion, et la plupart ne savaient pas pourquoi ils étaient assemblés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Et ils tirèrent Alexandre hors de la foule, les Juifs le poussant en avant; et Alexandre, faisant signe de la main, voulait présenter une apologie au peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Mais quand ils eurent connu qu’il était Juif, ils s’écrièrent tous d’une seule voix, durant près de deux heures: Grande est la Diane des Éphésiens!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Mais le secrétaire [de la ville], ayant apaisé la multitude, dit: Hommes éphésiens, qui est donc l’homme qui ne sache pas que la ville des Éphésiens est consacrée à la garde du temple de la grande Diane, et à l’[image] tombée du ciel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Ces choses donc étant incontestables, il convient que vous vous teniez tranquilles et que vous ne fassiez rien précipitamment;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'car vous avez amené ces hommes qui ne sont ni des voleurs sacrilèges, ni des blasphémateurs de votre déesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Si donc Démétrius et les artisans qui sont avec lui ont quelque affaire contre quelqu’un, les tribunaux sont ouverts et il y a des proconsuls; qu’ils s’accusent les uns les autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Et si vous avez une réclamation à faire sur d’autres sujets, on en décidera dans l’assemblée légale;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'car nous sommes en danger d’être accusés de sédition pour ce qui s’est passé aujourd’hui, puisqu’il n’y a pas de motif que nous puissions alléguer pour rendre raison de cet attroupement. Et quand il eut dit ces choses, il congédia l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Or, après que le tumulte eut cessé, Paul fit venir les disciples, et les ayant embrassés, il partit pour aller en Macédoine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Et ayant traversé ces quartiers-là, et ayant beaucoup exhorté les [disciples], il vint en Grèce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Et après qu’il y eut séjourné trois mois, les Juifs lui ayant dressé des embûches comme il allait s’embarquer pour la Syrie, on fut d’avis de s’en retourner par la Macédoine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Et Sopater de Bérée, [fils] de Pyrrhus, l’accompagna jusqu’en Asie, et les Thessaloniciens Aristarque et Second, et Gaïus, et Timothée de Derbe, et Tychique et Trophime d’Asie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ceux-ci ayant pris les devants, nous attendirent en Troade.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Et pour nous, nous sommes partis à force de voiles, de Philippes, après les jours des pains sans levain, et nous sommes arrivés au bout de cinq jours auprès d’eux dans la Troade, et nous y avons séjourné sept jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Et le premier jour de la semaine, lorsque nous étions assemblés pour rompre le pain, Paul qui devait partir le lendemain, leur fit un discours, et il prolongea le discours jusqu’à minuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Or il y avait beaucoup de lampes dans la chambre haute où nous étions assemblés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Et un jeune homme nommé Eutyche, qui était assis sur la fenêtre, accablé d’un profond sommeil, comme Paul prêchait très longuement, tomba, accablé par le sommeil, du troisième étage en bas, et fut relevé mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Mais Paul étant descendu, se pencha sur lui, et l’ayant embrassé, il dit: Ne soyez pas troublés, car son âme est en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Et après qu’il fut remonté, et qu’il eut rompu le pain et mangé, et qu’il eut conversé longtemps jusqu’à l’aube, il partit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Et ils amenèrent le jeune garçon vivant, et furent extrêmement consolés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Or pour nous, ayant pris les devants sur un navire, nous avons fait voile vers Assos où nous devions prendre Paul à bord; car il l’avait ainsi ordonné, étant dans l’intention d’aller lui-même à pied.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Et lorsqu’il nous eut rejoints à Assos, nous l’avons pris à bord, et nous sommes allés à Mitylène.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Et ayant fait voile de là, nous sommes arrivés le lendemain à la hauteur de Chios; et le jour suivant nous avons touché à Samos; et, nous étant arrêtés à Trogylle, nous sommes venus le jour d’après à Milet;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'car Paul avait résolu de passer devant Éphèse, de manière à ne pas dépenser son temps en Asie; car il se hâtait pour être, s’il lui était possible, le jour de la Pentecôte, à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Or il envoya de Milet à Éphèse, et appela auprès de lui les anciens de l’assemblée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'et quand ils furent venus vers lui, il leur dit: Vous savez de quelle manière je me suis conduit envers vous tout le temps, depuis le premier jour où je suis entré en Asie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'servant le Seigneur en toute humilité, et avec des larmes, et des épreuves qui me sont arrivées par les embûches des Juifs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'comment je n’ai rien caché des choses qui étaient profitables, en sorte que je ne vous aie pas prêché et enseigné publiquement et dans les maisons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'insistant et auprès des Juifs et auprès des Grecs sur la repentance envers Dieu et la foi en notre seigneur Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Et maintenant, voici, étant lié dans mon esprit, je m’en vais à Jérusalem, ignorant les choses qui doivent m’y arriver,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'sauf que l’Esprit Saint rend témoignage de ville en ville, me disant que des liens et de la tribulation m’attendent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Mais je ne fais aucun cas de ma vie, [ni ne la tiens] pour précieuse à moi-même, pourvu que j’achève ma course, et le service que j’ai reçu du seigneur Jésus pour rendre témoignage à l’évangile de la grâce de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Et maintenant, voici, moi je sais que vous tous, parmi lesquels j’ai passé en prêchant le royaume de Dieu, vous ne verrez plus mon visage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'C’est pourquoi je vous prends aujourd’hui à témoin, que je suis net du sang de tous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'car je n’ai mis aucune réserve à vous annoncer tout le conseil de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Prenez donc garde à vous-mêmes, et à tout le troupeau au milieu duquel l’Esprit Saint vous a établis surveillants pour paître l’assemblée de Dieu, laquelle il a acquise par le sang de son propre [fils].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Moi je sais qu’après mon départ il entrera parmi vous des loups redoutables qui n’épargneront pas le troupeau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'et il se lèvera d’entre vous-mêmes des hommes qui annonceront des [doctrines] perverses pour attirer les disciples après eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'C’est pourquoi veillez, vous souvenant que, durant trois ans, je n’ai cessé nuit et jour d’avertir chacun [de vous] avec larmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Et maintenant je vous recommande à Dieu, et à la parole de sa grâce, qui a la puissance d’édifier et de [vous] donner un héritage avec tous les sanctifiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Je n’ai convoité ni l’argent, ni l’or, ni la robe de personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Vous savez vous-mêmes que ces mains ont été employées pour mes besoins et pour les personnes qui étaient avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Je vous ai montré en toutes choses, qu’en travaillant ainsi il nous faut secourir les faibles, et nous souvenir des paroles du seigneur Jésus, qui lui-même a dit: Il est plus heureux de donner que de recevoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Et ayant dit ces choses, il se mit à genoux et pria avec eux tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Et ils versaient tous beaucoup de larmes, et se jetant au cou de Paul, ils le couvraient de baisers,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'étant surtout peinés de la parole qu’il avait dite, qu’ils ne verraient plus son visage. Et ils l’accompagnèrent au navire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Et quand, nous étant arrachés d’auprès d’eux, nous avons mis à la voile, voguant en droite ligne, nous sommes arrivés à Cos, et le jour suivant à Rhodes, et de là à Patara.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Et ayant trouvé un navire qui passait en Phénicie, nous y sommes montés et avons mis à la voile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Et ayant découvert Chypre, et l’ayant laissée à gauche, nous avons vogué vers la Syrie et nous avons abordé à Tyr; car c’était là que le navire devait décharger sa cargaison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Et ayant trouvé les disciples, nous y sommes demeurés sept jours. Et ils dirent à Paul, par l’Esprit, de ne pas monter à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Mais ayant accompli ces jours, nous sommes partis et nous nous sommes mis en chemin; et tous nous accompagnèrent avec femmes et enfants jusque hors de la ville; et nous étant mis à genoux sur le rivage, nous avons prié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Et après nous être embrassés les uns les autres, nous sommes montés sur le navire; et ils s’en retournèrent chez eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Et quant à nous, achevant notre navigation, nous sommes arrivés de Tyr à Ptolémaïs; et ayant salué les frères, nous sommes demeurés un jour auprès d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Et le lendemain, étant partis, nous sommes venus à Césarée; et étant entrés dans la maison de Philippe l’évangéliste qui était [l’un] des sept, nous sommes demeurés chez lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Or il avait quatre filles vierges qui prophétisaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Et comme nous nous sommes arrêtés là plusieurs jours, un prophète nommé Agabus descendit de la Judée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'et étant venu auprès de nous et ayant pris la ceinture de Paul, et s’étant lié les pieds et les mains, il dit: L’Esprit Saint dit ces choses: L’homme à qui est cette ceinture, les Juifs à Jérusalem le lieront ainsi et le livreront entre les mains des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Et quand nous avons entendu ces choses, nous et ceux qui étaient du lieu, nous l’avons supplié de ne pas monter à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Mais Paul répondit: Que faites-vous en pleurant et en brisant mon cœur? Car pour moi, je suis prêt, non seulement à être lié, mais encore à mourir à Jérusalem pour le nom du seigneur Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Et comme il ne se laissait pas persuader, nous nous sommes tus, disant: La volonté du Seigneur soit faite!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Et après ces jours, ayant rassemblé nos effets, nous sommes montés à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Et quelques-uns aussi des disciples de Césarée vinrent avec nous, amenant un certain Mnason, Cypriote, un ancien disciple, chez qui nous devions loger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Et quand nous sommes arrivés à Jérusalem, les frères nous reçurent avec joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Et, le jour suivant, Paul entra avec nous chez Jacques, et tous les anciens y vinrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Et après qu’il les eut embrassés, il raconta une à une les choses que Dieu avait faites parmi les nations par son service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Et eux, l’ayant entendu, glorifièrent Dieu et dirent à Paul: Tu vois, frère, combien il y a de milliers de Juifs qui ont cru; et ils sont tous zélés pour la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Or ils ont entendu dire de toi, que tu enseignes à tous les Juifs qui sont parmi les nations de renoncer à Moïse, disant qu’ils ne doivent pas circoncire leurs enfants, ni vivre selon les coutumes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Qu’est-ce donc? Il faut absolument que la multitude s’assemble, car ils entendront dire que tu es arrivé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Fais donc ce que nous te disons: Nous avons quatre hommes qui ont fait un vœu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'prends-les et purifie-toi avec eux, et paie leur dépense, afin qu’ils se rasent la tête, et tous sauront que rien n’est [vrai] des choses qu’ils ont entendu dire de toi, mais que toi aussi, tu marches gardant la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Mais à l’égard de ceux des nations qui ont cru, nous [en] avons écrit, ayant décidé qu’ils n’ont rien de semblable à observer, si ce n’est qu’ils se gardent et de ce qui est sacrifié aux idoles, et du sang, et de ce qui est étouffé, et de la fornication.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Alors Paul, ayant pris les hommes avec lui, et, le jour suivant, s’étant purifié, entra avec eux au temple, annonçant quand seraient accomplis les jours de leur purification, l’époque à laquelle l’offrande aurait été présentée pour chacun d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Et comme les sept jours allaient s’accomplir, les Juifs d’Asie l’ayant vu dans le temple, soulevèrent toute la foule et mirent les mains sur lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 's’écriant: Hommes israélites, aidez-nous! C’est ici l’homme qui partout enseigne tout le monde contre le peuple, et la loi, et ce lieu; et qui de plus a aussi amené des Grecs dans le temple et a profané ce saint lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Car ils avaient vu auparavant dans la ville Trophime l’Éphésien avec lui, et ils croyaient que Paul l’avait amené dans le temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Et toute la ville fut en émoi, et il se fit un rassemblement du peuple; et ayant saisi Paul, ils le traînèrent hors du temple; et aussitôt les portes furent fermées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Et comme ils cherchaient à le tuer, le bruit vint au chiliarque de la cohorte, que tout Jérusalem était en confusion;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'et aussitôt il prit des soldats et des centurions, et courut à eux; mais eux, voyant le chiliarque et les soldats, cessèrent de battre Paul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Alors le chiliarque s’étant approché, se saisit de lui et donna l’ordre de le lier de deux chaînes, et demanda qui il était et ce qu’il avait fait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Mais les uns criaient une chose, les autres une autre, dans la foule; et n’en pouvant apprendre quelque chose de certain, à cause du tumulte, il donna ordre que Paul soit mené dans la forteresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Et quand il fut sur les degrés, il arriva qu’il fut porté par les soldats à cause de la violence de la foule;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'car la multitude du peuple suivait, en criant: Ôte-le!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Et comme on allait faire entrer Paul dans la forteresse, il dit au chiliarque: M’est-il permis de te dire quelque chose? Et il dit: Tu sais le grec?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'N’es-tu donc pas l’Égyptien qui, ces jours passés, a excité une sédition et emmené au désert les 4 000 hommes des assassins?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Et Paul dit: Je suis Juif, de Tarse, citoyen d’une ville de la Cilicie qui n’est pas sans renom; je te prie, permets-moi de parler au peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Et quand il le lui eut permis, Paul, se tenant sur les degrés, fit signe de la main au peuple, et un grand silence s’étant fait, il leur parla en langue hébraïque, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Hommes frères et pères, écoutez maintenant mon apologie auprès de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Et quand ils entendirent qu’il leur parlait en langue hébraïque, ils firent silence encore plus; et il dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Je suis Juif, né à Tarse de Cilicie, mais élevé dans cette ville-ci, [et] instruit aux pieds de Gamaliel selon l’exactitude de la loi de nos pères, étant zélé pour Dieu, comme vous l’êtes tous aujourd’hui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'et j’ai persécuté cette voie jusqu’à la mort, liant les hommes et les femmes, et les livrant [pour être mis] en prison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'comme le souverain sacrificateur même m’en est témoin, et tout le corps des anciens, desquels aussi ayant reçu des lettres pour les frères, j’allais à Damas, afin d’amener liés à Jérusalem ceux aussi qui se trouvaient là, pour qu’ils soient punis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Et il m’arriva, comme j’étais en chemin et que j’approchais de Damas, que vers midi, tout à coup, une grande lumière, venant du ciel, brilla comme un éclair autour de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Et je tombai sur le sol, et j’entendis une voix qui me disait: Saul! Saul! pourquoi me persécutes-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Et moi je répondis: Qui es-tu, Seigneur? Et il me dit: Je suis Jésus le Nazaréen que tu persécutes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Et ceux qui étaient avec moi virent la lumière, et ils furent saisis de crainte, mais ils n’entendirent pas la voix de celui qui me parlait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Et je dis: Que dois-je faire, Seigneur? Et le Seigneur me dit: Lève-toi et va à Damas, et là on te parlera de toutes les choses qu’il t’est ordonné de faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Et comme je n’y voyais pas, à cause de la gloire de cette lumière, j’arrivai à Damas, ceux qui étaient avec moi me conduisant par la main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Et un certain Ananias, homme pieux selon la loi, et qui avait un [bon] témoignage de tous les Juifs qui demeuraient [là],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'venant vers moi et se tenant là, me dit: Saul, frère, recouvre la vue. Et sur l’heure, levant les yeux, moi je le vis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Et il dit: Le Dieu de nos pères t’a choisi d’avance pour connaître sa volonté, et pour voir le Juste, et entendre une voix de sa bouche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'car tu lui seras témoin, auprès de tous les hommes, des choses que tu as vues et entendues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Et maintenant que tardes-tu? Lève-toi et sois baptisé, et te lave de tes péchés, invoquant son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Or, quand je fus de retour à Jérusalem, comme je priais dans le temple, il m’arriva d’être en extase,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'et de le voir me disant: Hâte-toi et sors au plus tôt de Jérusalem; parce qu’ils ne recevront pas ton témoignage à mon égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Et moi je dis: Seigneur, ils savent que je mettais en prison et que je battais dans les synagogues ceux qui croient en toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'et lorsque le sang d’Étienne, ton témoin, fut répandu, moi-même aussi j’étais présent et consentant, et je gardais les vêtements de ceux qui le tuaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Et il me dit: Va, car je t’enverrai au loin vers les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Et ils l’écoutèrent jusqu’à ce mot, et ils élevèrent leur voix, disant: Ôte de la terre un pareil homme, car il n’aurait pas dû vivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Et comme ils poussaient des cris et jetaient leurs vêtements et lançaient de la poussière en l’air,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'le chiliarque donna l’ordre de le conduire à la forteresse, disant qu’on le mette à la question par le fouet, afin d’apprendre pour quel sujet ils criaient ainsi contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Mais quand ils l’eurent fait étendre avec les courroies, Paul dit au centurion qui était près [de lui]: Vous est-il permis de fouetter un homme qui est Romain et qui n’est pas condamné?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Et quand le centurion entendit cela, il s’en alla faire son rapport au chiliarque, disant: Que vas-tu faire? car cet homme est Romain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Et le chiliarque s’approchant dit à Paul: Dis-moi, es-tu Romain? Et il dit: Oui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Et le chiliarque reprit: Moi, j’ai acquis cette bourgeoisie pour une grande somme. Et Paul dit: Mais moi, je l’ai par naissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Aussitôt donc, ceux qui allaient le mettre à la question se retirèrent de lui; et le chiliarque aussi eut peur, sachant qu’il était Romain, et parce qu’il l’avait fait lier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Mais le lendemain, voulant savoir exactement ce pour quoi il était accusé par les Juifs, il le fit délier et ordonna que les principaux sacrificateurs et tout le sanhédrin s’assemblent; et ayant fait descendre Paul, il le présenta devant eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Et Paul, ayant arrêté les yeux sur le sanhédrin, dit: Hommes frères, je me suis conduit en toute bonne conscience devant Dieu jusqu’à ce jour...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Mais le souverain sacrificateur Ananias commanda à ceux qui étaient près de lui de le frapper sur la bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Alors Paul lui dit: Dieu te frappera, paroi blanchie! Es-tu assis là pour me juger selon la loi; et, contrairement à la loi, tu ordonnes que je sois frappé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Et ceux qui étaient présents dirent: Injuries-tu le souverain sacrificateur de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Et Paul dit: Je ne savais pas, frères, que c’était le souverain sacrificateur; car il est écrit: « Tu ne diras pas du mal du chef de ton peuple ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Et Paul, sachant qu’une partie [d’entre eux] étaient des sadducéens et l’autre des pharisiens, s’écria dans le sanhédrin: Hommes frères, je suis pharisien, fils de pharisien; je suis mis en jugement pour l’espérance et la résurrection des morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Et quand il eut dit cela, il s’éleva une dissension entre les pharisiens et les sadducéens; et la multitude fut partagée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'car les sadducéens disent qu’il n’y a pas de résurrection, ni d’ange, ni d’esprit; mais les pharisiens confessent l’un et l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Et il s’éleva une grande clameur; et quelques scribes du parti des pharisiens se levèrent et contestèrent, disant: Nous ne trouvons aucun mal en cet homme; mais si un esprit lui a parlé, ou un ange ...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Et un grand tumulte s’étant élevé, le chiliarque, craignant que Paul ne soit mis en pièces par eux, commanda à la troupe de descendre et de l’enlever du milieu d’eux et de le conduire à la forteresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Et la nuit suivante, le Seigneur se tint près de lui et dit: Aie bon courage; car comme tu as rendu témoignage des choses qui me regardent, à Jérusalem, ainsi il faut que tu rendes témoignage aussi à Rome.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Et quand le jour fut venu, les Juifs s’unirent et s’obligèrent par un serment d’exécration, disant qu’ils ne mangeraient ni ne boiraient jusqu’à ce qu’ils aient tué Paul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Et ils étaient plus de 40 qui avaient fait cette conjuration.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Et ils vinrent aux principaux sacrificateurs et aux anciens, et dirent: Nous nous sommes obligés par un serment d’exécration à ne goûter de rien jusqu’à ce que nous ayons tué Paul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Vous donc, maintenant, avec le sanhédrin, avertissez le chiliarque pour qu’il le fasse descendre vers vous, comme si vous vouliez vous informer plus exactement de ce qui le regarde; et, avant qu’il approche, nous sommes prêts pour le tuer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Mais le fils de la sœur de Paul, ayant entendu parler de ce guet-apens, s’en alla et entra dans la forteresse, et le rapporta à Paul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Et Paul, ayant appelé l’un des centurions, dit: Conduis ce jeune homme au chiliarque, car il a quelque chose à lui rapporter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Il le prit donc et le conduisit au chiliarque et dit: Le prisonnier Paul m’a appelé, et m’a prié de t’amener ce jeune homme qui a quelque chose à te dire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Et le chiliarque, l’ayant pris par la main et s’étant retiré à part, lui demanda: Qu’est-ce que tu as à me rapporter?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Et il dit: Les Juifs se sont entendus pour te prier que demain tu fasses descendre Paul devant le sanhédrin, comme si tu voulais t’enquérir plus exactement à son sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Toi donc n’y consens pas, car plus de 40 hommes d’entre eux lui dressent un guet-apens, lesquels se sont obligés par un serment d’exécration de ne manger ni ne boire jusqu’à ce qu’ils l’aient tué; et ils sont maintenant prêts, attendant de toi la promesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Le chiliarque donc renvoya le jeune homme, lui ayant enjoint de ne divulguer à personne qu’il lui avait déclaré ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Et ayant appelé deux des centurions, il dit: Préparez 200 soldats pour aller à Césarée, et 70 cavaliers, et 200 porte-lances, dès la troisième heure de la nuit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'et procurez-vous des montures, afin qu’ayant mis Paul dessus ils le conduisent en sûreté auprès de Félix le gouverneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Et il écrivit une lettre conçue en ces termes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Claude Lysias, au très excellent gouverneur Félix, salut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Cet homme ayant été saisi par les Juifs et étant sur le point d’être tué par eux, je suis survenu avec la troupe et je l’ai délivré, ayant appris qu’il est Romain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Et voulant connaître le motif pour lequel ils l’accusaient, je l’ai fait descendre devant leur sanhédrin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'et j’ai trouvé qu’il était accusé touchant des questions de leur loi, mais qu’il n’était sous le coup d’aucune accusation qui mérite la mort ou les liens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Et ayant été averti des embûches que [les Juifs] allaient dresser contre cet homme, je te l’ai aussitôt envoyé, ayant donné l’ordre à ses accusateurs aussi de dire devant toi les choses qu’ils ont contre lui. Porte-toi bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Les soldats donc, selon les ordres qui leur avaient été donnés, prirent Paul et le menèrent de nuit à Antipatris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Et le lendemain, ayant laissé les cavaliers s’en aller avec lui, ils retournèrent à la forteresse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Et ceux-là, étant arrivés à Césarée, remirent la lettre au gouverneur et lui présentèrent aussi Paul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Et quand il eut lu [la lettre] et qu’il eut demandé de quelle province il était, ayant appris qu’il était de Cilicie:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Je t’entendrai à fond, dit-il, quand tes accusateurs aussi seront arrivés. Et il donna ordre qu’il soit gardé au prétoire d’Hérode.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Or cinq jours après, le souverain sacrificateur Ananias descendit avec les anciens et un certain orateur [nommé] Tertulle, et ils portèrent plainte devant le gouverneur contre Paul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Et quand celui-ci eut été appelé, Tertulle se mit à l’accuser, disant: Puisque nous jouissons par ton moyen d’une grande tranquillité, et que par ta prévoyance des mesures excellentes sont prises en vue de cette nation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'très excellent Félix, nous l’acceptons, en tout et partout, avec une entière gratitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Mais afin de ne pas t’arrêter davantage, je te prie de nous entendre brièvement selon ta clémence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'car nous avons trouvé que cet homme est une peste, et qu’il excite des séditions parmi tous les Juifs dans toute la terre habitée, et qu’il est un meneur de la secte des Nazaréens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'il a même tenté de profaner le temple: aussi l’avons-nous saisi, [et nous avons voulu le juger selon notre loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'mais Lysias, le chiliarque, étant survenu, l’a emmené en l’arrachant d’entre nos mains avec une grande violence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'donnant ordre que ses accusateurs viennent auprès de toi]; et par lui tu pourras toi-même, en l’interrogeant, arriver à la pleine connaissance de toutes ces choses dont nous l’accusons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Et les Juifs aussi se joignirent à lui pour insister contre [Paul], affirmant que les choses étaient ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Et Paul, après que le gouverneur lui eut fait signe de parler, répondit: Sachant que depuis plusieurs années tu es juge de cette nation, je fais mon apologie avec plus de courage:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'car tu peux connaître qu’il ne s’est pas passé plus de douze jours depuis que je suis monté pour adorer à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Et ils ne m’ont trouvé, ni dans le temple, disputant avec quelqu’un ou ameutant la foule, ni dans les synagogues, ni dans la ville;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'et ils ne peuvent pas soutenir les choses dont ils m’accusent présentement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Mais je te confesse bien ceci, que, selon la voie qu’ils appellent secte, ainsi je sers le Dieu de mes pères, croyant toutes les choses qui sont écrites dans la loi et dans les prophètes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'ayant espérance en Dieu, – [espérance] que ceux-ci nourrissent aussi eux-mêmes, – qu’il y aura une résurrection, tant des justes que des injustes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'À cause de cela, moi aussi je m’exerce à avoir toujours une conscience sans reproche devant Dieu et devant les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Or, après plusieurs années, je suis venu pour faire des aumônes à ma nation et des offrandes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Sur ces entrefaites, ils me trouvèrent purifié dans le temple, sans attroupement et sans tumulte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Or c’étaient certains Juifs d’Asie, qui auraient dû être ici devant toi et m’accuser, s’ils avaient quelque chose contre moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'ou bien, que ceux-ci eux-mêmes disent quelle injustice ils ont trouvée en moi, quand j’ai été devant le sanhédrin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'si ce n’est ce seul cri que je fis entendre, étant au milieu d’eux: C’est pour la résurrection des morts que je suis aujourd’hui mis en jugement par vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Mais Félix, ayant plus exactement connaissance de ce qui regardait la voie, les ajourna, disant: Quand le chiliarque Lysias sera descendu, je prendrai connaissance de votre affaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, '– ordonnant au centurion que [Paul] soit gardé, et qu’il ait [quelque] liberté, et qu’on n’empêche aucun des siens de le servir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Or quelques jours après, Félix étant venu avec Drusille sa femme qui était Juive, fit venir Paul et l’entendit sur la foi en Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Et comme il discourait sur la justice et sur la tempérance et sur le jugement à venir, Félix tout effrayé répondit: Pour le présent va-t’en; quand je trouverai un moment convenable, je te ferai appeler,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, '– espérant en même temps que Paul lui donnerait quelque argent; c’est pourquoi aussi il le faisait venir souvent et s’entretenait avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Or, quand deux ans furent accomplis, Félix eut pour successeur Porcius Festus; et, voulant gagner la faveur des Juifs, Félix laissa Paul prisonnier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Festus donc, étant arrivé dans la province, monta trois jours après de Césarée à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Et les principaux sacrificateurs et les principaux d’entre les Juifs portèrent plainte devant lui contre Paul; et ils lui présentaient leur requête,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'lui demandant contre [Paul] cette grâce qu’il le fasse venir à Jérusalem, dressant des embûches pour le tuer en chemin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Festus donc répondit que Paul serait gardé à Césarée, et que lui-même allait bientôt partir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Que les hommes influents parmi vous descendent donc avec [moi], dit-il; et s’il y a quelque crime en cet homme, qu’ils l’accusent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Et n’ayant pas séjourné parmi eux plus de huit ou dix jours, il descendit à Césarée; et le lendemain, s’étant assis sur le tribunal, il donna l’ordre que Paul soit amené.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Et lorsqu’il fut arrivé, les Juifs qui étaient descendus de Jérusalem se tinrent à l’entour, portant contre [Paul] de nombreuses et graves accusations qu’ils ne pouvaient prouver;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'tandis que Paul se défendait, [en disant]: Je n’ai péché en rien, ni contre la loi des Juifs, ni contre le temple, ni contre César.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Mais Festus, voulant gagner la faveur des Juifs, répondit à Paul et dit: Veux-tu monter à Jérusalem pour y être jugé quant à ces choses, devant moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Et Paul dit: Je suis ici devant le tribunal de César, où je dois être jugé. Je n’ai fait aucun tort aux Juifs, comme tu le sais toi-même très bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Si donc je leur ai fait tort, ou que j’aie fait quelque chose qui soit digne de mort, je ne refuse pas de mourir; mais si rien n’est [vrai] de ce dont ils m’accusent, personne ne peut me livrer à eux: j’en appelle à César.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Alors Festus, ayant conféré avec le conseil, répondit: Tu en as appelé à César, tu iras à César.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Or, quelques jours s’étant écoulés, le roi Agrippa et Bérénice vinrent à Césarée pour saluer Festus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Et comme ils séjournaient là plusieurs jours, Festus exposa au roi l’affaire de Paul, disant: Un certain homme a été laissé [ici] prisonnier par Félix,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'au sujet duquel, lorsque j’étais à Jérusalem, les principaux sacrificateurs et les anciens des Juifs ont porté plainte, sollicitant une sentence contre lui:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'mais je leur ai répondu que ce n’est pas la coutume des Romains de livrer quelqu’un avant que l’accusé ait ses accusateurs devant lui et qu’il ait l’occasion de se défendre de ce dont il est accusé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Quand donc ils furent venus ici, sans aucun délai, le jour suivant, m’étant assis sur le tribunal, j’ordonnai que cet homme soit amené;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'au sujet duquel les accusateurs, se tenant là, n’avancèrent aucune charge relativement aux choses que moi je supposais;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'mais ils avaient contre lui quelques questions touchant leur culte religieux et touchant un certain Jésus mort, que Paul affirmait être vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Et comme moi j’étais dans l’embarras pour procéder à une information sur ces choses, je demandai [à cet homme] s’il voulait aller à Jérusalem pour y être jugé quant à ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Mais Paul, en ayant appelé, [demandant] à être réservé au jugement d’Auguste, je donnai ordre qu’il soit gardé jusqu’à ce que je l’envoie à César.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Et Agrippa [dit] à Festus: Je voudrais bien moi-même aussi entendre cet homme. Demain, dit-il, tu l’entendras.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Le lendemain donc, Agrippa et Bérénice étant venus en grande pompe, et étant entrés dans la salle d’audience avec les chiliarques et les principaux de la ville, Paul, sur l’ordre de Festus, fut amené.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Et Festus dit: Roi Agrippa, et vous tous qui êtes ici présents avec nous, vous voyez cet homme au sujet duquel toute la multitude des Juifs m’a sollicité, tant à Jérusalem qu’ici, s’écriant qu’il ne devait plus vivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Mais moi, ayant trouvé qu’il n’avait rien fait qui soit digne de mort, et cet homme lui-même en ayant appelé à Auguste, j’ai résolu de l’envoyer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Mais je n’ai rien de certain à écrire à l’empereur à son sujet, c’est pourquoi je l’ai amené devant vous, et principalement devant toi, roi Agrippa, en sorte qu’après avoir procédé à un interrogatoire, j’aie quelque chose à écrire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'car il me semble déraisonnable d’envoyer un prisonnier sans indiquer en même temps les choses qui sont mises à sa charge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Et Agrippa dit à Paul: Il t’est permis de parler pour toi. Alors Paul, ayant étendu la main, prononça son apologie:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Je m’estime heureux, roi Agrippa, de ce que, au sujet de toutes les choses dont je suis accusé par les Juifs, je dois faire mon apologie aujourd’hui devant toi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'surtout parce que tu es au fait de toutes les coutumes et questions qui [existent] parmi les Juifs; c’est pourquoi je te prie de m’écouter avec patience.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Ma manière de vivre donc dès ma jeunesse, telle qu’elle a été dès le commencement au milieu de ma nation à Jérusalem, tous les Juifs la connaissent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'm’ayant connu depuis le commencement, s’ils veulent en rendre témoignage, [et sachant] que, selon la secte la plus exacte de notre culte, j’ai vécu pharisien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Et maintenant je comparais en jugement pour l’espérance de la promesse faite par Dieu à nos pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'à laquelle nos douze tribus, en servant [Dieu] sans relâche nuit et jour, espèrent parvenir; et c’est pour cette espérance, ô roi, que je suis accusé par les Juifs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Pourquoi, parmi vous, juge-t-on incroyable que Dieu ressuscite des morts?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Pour moi donc, j’ai pensé en moi-même qu’il fallait faire beaucoup contre le nom de Jésus le Nazaréen:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'ce que j’ai fait aussi dans Jérusalem; et j’ai enfermé dans les prisons plusieurs des saints, après en avoir reçu le pouvoir des principaux sacrificateurs; et quand on les faisait mourir, j’y donnais ma voix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'et souvent, dans toutes les synagogues, en les punissant, je les contraignais de blasphémer; et transporté de fureur contre eux, je les persécutais même jusque dans les villes étrangères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Et comme j’allais aussi à Damas pour cela, avec pouvoir et commission de la part des principaux sacrificateurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'en chemin, en plein midi, je vis, ô roi, une lumière plus éclatante que la splendeur du soleil, laquelle resplendit du ciel autour de moi et de ceux qui étaient en chemin avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Et comme nous étions tous tombés à terre, j’entendis une voix qui me parlait et qui disait en langue hébraïque: Saul! Saul! pourquoi me persécutes-tu? Il t’est dur de regimber contre les aiguillons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Et moi je dis: Qui es-tu, Seigneur? Et le Seigneur dit: Je suis Jésus que tu persécutes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Mais lève-toi et tiens-toi sur tes pieds: car je te suis apparu afin de te désigner pour serviteur et témoin, et des choses que tu as vues et de celles pour [la révélation] desquelles je t’apparaîtrai,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'en te retirant du milieu du peuple et des nations vers lesquelles moi je t’envoie');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'pour ouvrir leurs yeux, pour qu’ils se tournent des ténèbres à la lumière, et du pouvoir de Satan à Dieu; pour qu’ils reçoivent la rémission des péchés et une part avec ceux qui sont sanctifiés, par la foi en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Ainsi, ô roi Agrippa, je n’ai pas été désobéissant à la vision céleste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'mais j’ai annoncé premièrement à ceux de Damas, et à Jérusalem, et à tout le pays de la Judée, et aux nations, de se repentir et de se tourner vers Dieu, en faisant des œuvres convenables à la repentance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'À cause de cela les Juifs, m’ayant pris dans le temple, cherchaient à me tuer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Ayant donc reçu le secours qui vient de Dieu, me voici debout jusqu’à ce jour, rendant témoignage aux petits et aux grands, ne disant rien d’autre que ce que les prophètes et Moïse ont annoncé devoir arriver,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, '[savoir] qu’il fallait que le Christ soit soumis aux souffrances, et que, le premier par [la] résurrection des morts il devait annoncer la lumière et au peuple et aux nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Et comme il parlait ainsi pour sa défense, Festus dit à haute voix: Tu es hors de sens, Paul; ton grand savoir te met hors de sens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Mais Paul dit: Je ne suis point hors de sens, très excellent Festus, mais je prononce des paroles de vérité et de sens rassis:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'car le roi a la connaissance de ces choses, et je parle hardiment devant lui, car je suis persuadé qu’il n’ignore rien de ces choses: car ceci n’a point été fait en secret.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Ô roi Agrippa! crois-tu aux prophètes? Je sais que tu [y] crois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Et Agrippa [dit] à Paul: Tu me persuaderas bientôt d’être chrétien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Mais Paul [dit]: Plût à Dieu que non seulement toi, mais aussi tous ceux qui m’entendent aujourd’hui, vous deveniez de toutes manières tels que je suis, hormis ces liens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Et le roi se leva, et le gouverneur et Bérénice, et ceux qui étaient assis avec eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'et quand ils se furent retirés, ils conférèrent entre eux, disant: Cet homme ne fait rien qui soit digne de mort ou de liens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Et Agrippa dit à Festus: Cet homme aurait pu être relâché, s’il n’en avait appelé à César.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Or après qu’il eut été décidé que nous ferions voile pour l’Italie, ils remirent Paul et quelques autres prisonniers à un centurion nommé Jules, de la cohorte Auguste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Et étant montés sur un navire d’Adramytte devant faire voile pour les lieux [qui sont situés] le long de la côte d’Asie, nous sommes partis, Aristarque, Macédonien de Thessalonique, étant avec nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Et le jour suivant nous sommes arrivés à Sidon; et Jules, traitant Paul avec humanité, lui permit d’aller vers ses amis pour jouir de leurs soins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Et étant partis de là, nous avons vogué à l’abri de Chypre, parce que les vents étaient contraires;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'et après avoir traversé la mer qui baigne la Cilicie et la Pamphylie, nous sommes arrivés à Myra en Lycie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'et là, le centurion ayant trouvé un navire d’Alexandrie qui allait en Italie, nous y fit monter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Et naviguant pesamment durant plusieurs jours, et étant arrivés avec peine à la hauteur de Cnide, le vent ne nous permettant pas d’avancer, nous avons côtoyé la Crète, vis-à-vis de Salmone;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'et l’ayant longée avec peine, nous sommes arrivés en un lieu qui est appelé Beaux-Ports, près duquel était la ville de Lasée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Et comme il s’était écoulé assez de temps, et que la navigation était déjà périlleuse, parce que le jeûne aussi était déjà passé, Paul les avertissait,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'disant: Hommes, je vois que la navigation sera accompagnée de revers et de beaucoup de dommage, non seulement quant au chargement et au navire, mais même quant à nos vies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Mais le centurion se fiait plus au pilote et au patron du navire qu’à ce que Paul disait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Et comme le port n’était pas commode pour hiverner, la plupart furent d’avis de partir de là, afin d’atteindre, s’il était possible, Phénice, port de Crète regardant vers le nord-est et le sud-est, afin d’y passer l’hiver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Et comme le vent du midi soufflait doucement, pensant qu’ils étaient venus à bout de leur dessein, ils levèrent l’ancre et côtoyèrent de près [l’île de] Crète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Mais un peu après, un vent orageux, appelé Euroclydon, descendit violemment de l’île.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Et le navire étant emporté et ne pouvant tenir contre le vent, nous l’avons laissé aller à la dérive et avons été emportés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Et courant sous une petite île appelée Clauda, nous nous sommes rendus à grand-peine maîtres de la chaloupe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'et l’ayant retirée à bord, ils employèrent des mesures de sûreté en liant le navire avec un câble passé dessous; et craignant de tomber sur les bancs de sable de la Syrte, ils descendirent les agrès [supérieurs], et étaient ainsi emportés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Et comme nous étions violemment battus par la tempête, le jour suivant ils jetèrent une partie de la charge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'Et le troisième jour ils jetèrent de leurs propres mains les agrès du navire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Et comme durant plusieurs jours il ne parut ni soleil ni étoiles, et qu’une grande tempête nous pressait, dès lors toute espérance de pouvoir nous sauver nous fut ôtée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Et après qu’on eut été longtemps sans manger, alors Paul, se tenant au milieu d’eux, dit: Ô hommes, vous auriez dû m’écouter et ne pas partir de Crète, et éviter ces avaries et ce dommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Et maintenant je vous exhorte à avoir bon courage; car on ne fera la perte de la vie d’aucun de vous, mais seulement du navire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Car un ange du Dieu à qui je suis et que je sers, est venu à moi cette nuit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'disant: Ne crains point, Paul: il faut que tu comparaisses devant César; et voici, Dieu t’a donné tous ceux qui naviguent avec toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'C’est pourquoi, ô hommes, ayez bon courage; car je crois Dieu, [et je sais] que la chose arrivera comme il m’a été dit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Mais il faut que nous soyons jetés sur quelque île.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, '– Et quand la quatorzième nuit fut venue, comme nous étions portés çà et là sur la mer Adriatique, les matelots, au milieu de la nuit, pensèrent que quelque terre les approchait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'et ayant jeté la sonde, ils trouvèrent 20 brasses; puis ayant passé un peu plus loin, et ayant encore jeté la sonde, ils trouvèrent 15 brasses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Et craignant que nous ne donnions au milieu des écueils, ils jetèrent quatre ancres de la poupe et souhaitèrent que le jour vienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Et comme les matelots cherchaient à s’enfuir du navire, ayant descendu la chaloupe en mer sous prétexte d’aller jeter au loin les ancres de la proue,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Paul dit au centurion et aux soldats: Si ceux-ci ne demeurent pas dans le navire, vous ne pouvez être sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Alors les soldats coupèrent les cordes de la chaloupe et la laissèrent tomber.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Et en attendant que le jour vienne, Paul les exhortait tous à prendre de la nourriture, disant: C’est aujourd’hui le quatorzième jour que vous passez à jeun, dans l’attente, sans avoir rien pris;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'c’est pourquoi je vous exhorte à prendre de la nourriture, car cela est nécessaire pour votre conservation; car pas un cheveu de la tête d’aucun de vous ne périra.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Et quand il eut dit ces choses, ayant pris du pain il rendit grâces à Dieu devant tous, et, l’ayant rompu, il se mit à manger.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Et ayant tous pris courage, eux aussi prirent de la nourriture.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Or nous étions en tout dans le navire 276 personnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Et quand ils eurent assez mangé, ils allégèrent le navire en jetant le froment dans la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Et le jour étant venu, ils ne reconnaissaient pas le pays; mais ils apercevaient une baie ayant une plage, sur laquelle ils résolurent, s’ils le pouvaient, de faire échouer le navire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Et ils abandonnèrent les ancres à la mer, coupant [les câbles], lâchant en même temps les attaches des gouvernails; et ayant mis au vent la voile d’artimon, ils cinglèrent vers la plage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Et étant tombés en un lieu baigné des deux côtés par la mer, ils échouèrent le navire; et la proue se trouvant engagée demeurait immobile, mais la poupe se rompait par la violence des vagues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Et l’avis des soldats fut de tuer les prisonniers, de peur que quelqu’un d’eux ne se sauve à la nage et ne s’enfuie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Mais le centurion, voulant sauver Paul, les empêcha [d’exécuter] leur dessein, et il ordonna que ceux qui savaient nager se jettent dehors les premiers et gagnent la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'et le reste, les uns sur des planches, et les autres sur quelques [débris] du navire. Et ainsi il arriva que tous parvinrent à terre sains et saufs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Et ayant été sauvés, alors nous avons appris que l’île s’appelait Malte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Et les barbares usèrent d’une humanité peu ordinaire envers nous, car ayant allumé un feu, ils nous reçurent tous, à cause de la pluie qui tombait et à cause du froid.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Et Paul ayant ramassé une quantité de branches sèches et les ayant mises sur le feu, une vipère sortit de la chaleur et s’attacha à sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Et quand les barbares virent la bête suspendue à sa main, ils se dirent l’un à l’autre: Assurément, cet homme est un meurtrier, puisque, après avoir été sauvé de la mer, Némésis n’a pas permis qu’il vive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Lui donc, ayant secoué la bête dans le feu, n’en souffrit aucun mal;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'et ils s’attendaient à ce qu’il enflerait ou tomberait mort subitement. Mais quand ils eurent longtemps attendu et qu’ils eurent vu qu’il ne lui arrivait rien d’extraordinaire, changeant de sentiment, ils dirent que c’était un dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Or aux environs de ce lieu-là se trouvaient des possessions du premier de l’île, nommé Publius, qui nous reçut, et nous logea durant trois jours avec beaucoup de bonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Et il arriva que le père de Publius était [là] couché, souffrant beaucoup de la fièvre et de la dysenterie; et Paul, étant entré auprès de lui, pria et lui imposa les mains et le guérit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Mais ceci étant arrivé, les autres malades aussi qui se trouvaient dans l’île vinrent et furent guéris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Et ceux-ci nous firent aussi de grands honneurs, et à notre départ nous fournirent ce qui nous était nécessaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Et trois mois après, nous sommes partis sur un navire d’Alexandrie qui avait hiverné dans l’île, et qui avait pour enseigne les Dioscures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Et ayant relâché à Syracuse, nous y sommes demeurés trois jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'De là nous avons fait un circuit, et nous sommes arrivés à Rhegium; et un jour après, le vent du midi s’étant levé, nous sommes arrivés le deuxième jour à Pouzzoles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'où, ayant trouvé des frères, nous avons été priés de demeurer avec eux sept jours; et ainsi nous sommes allés à Rome.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Et de là, les frères, ayant appris les choses qui nous étaient arrivées, vinrent au-devant de nous jusqu’au Forum d’Appius et aux Trois-Tavernes; et Paul, les voyant, rendit grâces à Dieu et prit courage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Et lorsque nous sommes arrivés à Rome, [le centurion livra les prisonniers au préfet du prétoire, et] il fut permis à Paul de demeurer chez lui avec un soldat qui le gardait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Or il arriva, trois jours après, que [Paul] convoqua ceux qui étaient les principaux des Juifs; et quand ils furent assemblés, il leur dit: Hommes frères, quoique je n’aie rien fait contre le peuple ou contre les coutumes des pères, fait prisonnier à Jérusalem, j’ai été livré entre les mains des Romains');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'qui, après m’avoir interrogé, voulaient me relâcher, parce qu’il n’y avait en moi aucun crime digne de mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Mais les Juifs s’y opposant, j’ai été contraint d’en appeler à César, non que j’aie quelque accusation à porter contre ma nation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'C’est donc là le sujet pour lequel je vous ai appelés, afin de vous voir et de vous parler, car c’est pour l’espérance d’Israël que je suis chargé de cette chaîne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Mais ils lui dirent: Pour nous, nous n’avons pas reçu de lettre de Judée à ton sujet; et aucun des frères qui sont arrivés n’a rapporté ou dit quelque mal de toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'mais nous demandons à entendre de toi quel est ton sentiment; car, quant à cette secte, il nous est connu que partout on la contredit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Et lui ayant assigné un jour, plusieurs vinrent auprès de lui dans son logis; et il leur exposait [la vérité], en rendant témoignage du royaume de Dieu, depuis le matin jusqu’au soir, cherchant à les persuader [des choses] concernant Jésus, et par la loi de Moïse et par les prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Et les uns furent persuadés par les choses qu’il disait; et les autres ne croyaient pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Et n’étant pas d’accord entre eux, ils se retirèrent, après que Paul leur eut dit une seule parole: L’Esprit Saint a bien parlé à nos pères par Ésaïe le prophète,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'disant: « Va vers ce peuple et dis: En entendant vous entendrez et vous ne comprendrez point, et en voyant vous verrez et vous n’apercevrez point;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'car le cœur de ce peuple s’est épaissi et ils ont endurci leurs oreilles, et ils ont fermé leurs yeux, de peur qu’ils ne voient des yeux, et qu’ils n’entendent des oreilles et qu’ils ne comprennent du cœur, et qu’ils ne se convertissent, et que je ne les guérisse ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Sachez donc que ce salut de Dieu a été envoyé aux nations; et eux écouteront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, '[Quand il eut dit ces choses, les Juifs se retirèrent, ayant entre eux une grande discussion.]');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Et [Paul] demeura deux ans entiers dans un logement qu’il avait loué pour lui, et il recevait tous ceux qui venaient vers lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'prêchant le royaume de Dieu et enseignant les choses qui regardent le seigneur Jésus Christ, avec toute hardiesse, sans empêchement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paul, esclave de Jésus Christ, apôtre appelé, mis à part pour l’évangile de Dieu');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, '(lequel il avait auparavant promis par ses prophètes dans de saintes écritures),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'touchant son Fils (né de la semence de David, selon la chair,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'déterminé Fils de Dieu, en puissance, selon [l’]Esprit de sainteté, par [la] résurrection des morts), Jésus Christ, notre Seigneur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'par lequel nous avons reçu grâce et apostolat, pour [l’]obéissance de [la] foi parmi toutes les nations, pour son nom,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'parmi lesquelles vous aussi, vous êtes des appelés de Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, '– à tous les bien-aimés de Dieu qui sont à Rome, saints appelés: Grâce et paix à vous, de la part de Dieu notre Père et du seigneur Jésus Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Premièrement, je rends grâces à mon Dieu, par Jésus Christ, pour vous tous, de ce que votre foi est publiée dans le monde entier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Car Dieu, que je sers dans mon esprit dans l’évangile de son Fils, m’est témoin que sans cesse je fais mention de vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'demandant toujours dans mes prières, si en quelque manière, maintenant une fois, il me sera accordé par la volonté de Dieu d’aller vers vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Car je désire ardemment de vous voir, afin de vous faire part de quelque don de grâce spirituel, pour que vous soyez affermis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'c’est-à-dire pour que nous soyons consolés ensemble au milieu de vous, vous et moi, chacun par la foi qui est dans l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Or je ne veux pas que vous ignoriez, frères, que je me suis souvent proposé d’aller vers vous (et que j’en ai été empêché jusqu’à présent), afin de recueillir quelque fruit parmi vous aussi, comme parmi les autres nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Je suis débiteur et envers les Grecs et envers les barbares, et envers les sages et envers les inintelligents:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'ainsi, pour autant qu’il dépend de moi, je suis tout prêt à vous annoncer l’évangile, à vous aussi qui êtes à Rome.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Car je n’ai pas honte de l’évangile, car il est [la] puissance de Dieu en salut à quiconque croit, et au Juif premièrement, et au Grec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Car [la] justice de Dieu y est révélée sur le principe de la foi pour la foi, selon qu’il est écrit: « Or le juste vivra de foi ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Car [la] colère de Dieu est révélée du ciel contre toute impiété et toute iniquité des hommes qui possèdent la vérité [tout en vivant] dans l’iniquité:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'parce que ce qui peut se connaître de Dieu est manifeste parmi eux; car Dieu le leur a manifesté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'car, depuis la fondation du monde, ce qui ne peut se voir de lui, [savoir] et sa puissance éternelle et sa divinité, se discerne par le moyen de l’intelligence, par les choses qui sont faites, de manière à les rendre inexcusables:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, '– parce que, ayant connu Dieu, ils ne le glorifièrent point comme Dieu, ni ne lui rendirent grâces; mais ils devinrent vains dans leurs raisonnements, et leur cœur destitué d’intelligence fut rempli de ténèbres:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'se disant sages, ils sont devenus fous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'et ils ont changé la gloire du Dieu incorruptible en la ressemblance de l’image d’un homme corruptible et d’oiseaux et de quadrupèdes et de reptiles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'C’est pourquoi Dieu les a aussi livrés, dans les convoitises de leurs cœurs, à l’impureté, en sorte que leurs corps soient déshonorés entre eux-mêmes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'eux qui ont changé la vérité de Dieu en mensonge, et ont honoré et servi la créature plutôt que celui qui l’a créée, qui est béni éternellement. Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'C’est pourquoi Dieu les a livrés à des passions infâmes, car leurs femmes ont changé l’usage naturel en celui qui est contre nature;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'et les hommes aussi pareillement, laissant l’usage naturel de la femme, se sont embrasés dans leur convoitise l’un envers l’autre, commettant l’infamie, mâles avec mâles, et recevant en eux-mêmes la due récompense de leur égarement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Et comme ils n’ont pas eu de sens moral pour garder la connaissance de Dieu, Dieu les a livrés à un esprit réprouvé, pour pratiquer des choses qui ne conviennent pas,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'étant remplis de toute injustice, de méchanceté, de cupidité, de malice, – pleins d’envie, de meurtres, de querelles, de fraude, de mauvaises mœurs, – délateurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'médisants, haïssables pour Dieu, outrageux, hautains, vantards, inventeurs de mauvaises choses, désobéissants à leurs parents,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'sans intelligence, ne tenant pas ce qu’ils ont promis, sans affection naturelle, sans miséricorde,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, '[et] qui, ayant connu la juste sentence de Dieu, que ceux qui commettent de telles choses sont dignes de mort, non seulement les pratiquent, mais encore trouvent leur plaisir en ceux qui les commettent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'C’est pourquoi tu es inexcusable, ô homme, qui que tu sois qui juges; car en ce que tu juges autrui, tu te condamnes toi-même, puisque toi qui juges, tu commets les mêmes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Or nous savons que le jugement de Dieu est selon la vérité contre ceux qui commettent de telles choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Et penses-tu, ô homme qui juges ceux qui commettent de telles choses et qui les pratiques, que tu échapperas au jugement de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Ou méprises-tu les richesses de sa bonté, et de sa patience, et de sa longue attente, ne connaissant pas que la bonté de Dieu te pousse à la repentance?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Mais, selon ta dureté et selon ton cœur sans repentance, tu amasses pour toi-même la colère dans le jour de la colère et de la révélation du juste jugement de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'qui rendra à chacun selon ses œuvres:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'à ceux qui, en persévérant dans les bonnes œuvres, cherchent la gloire et l’honneur et l’incorruptibilité, – la vie éternelle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'mais à ceux qui sont disputeurs et qui désobéissent à la vérité, et obéissent à l’iniquité, – la colère et l’indignation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'tribulation et angoisse sur toute âme d’homme qui fait le mal, et du Juif premièrement, et du Grec;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'mais gloire et honneur et paix à tout [homme] qui fait le bien, et au Juif premièrement, et au Grec;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'car il n’y a pas d’acception de personnes auprès de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Car tous ceux qui ont péché sans loi, périront aussi sans loi; et tous ceux qui ont péché sous [la] loi, seront jugés par [la] loi');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(car ce ne sont pas les auditeurs de la loi qui sont justes devant Dieu; mais ce sont ceux qui accomplissent la loi qui seront justifiés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'car quand les nations qui n’ont point de loi, font naturellement les choses de la loi, n’ayant pas de loi, elles sont loi à elles-mêmes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'et elles montrent l’œuvre de la loi, écrite dans leurs cœurs, leur conscience rendant en même temps témoignage, et leurs pensées s’accusant entre elles, ou aussi s’excusant),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, '[seront jugés, dis-je,] au jour où Dieu jugera par Jésus Christ les secrets des hommes, selon mon évangile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Or si toi, tu portes le nom de Juif, et que tu te reposes entièrement sur la loi, et que tu te glorifies en Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'et que tu connaisses la volonté, et que tu saches discerner les choses excellentes, étant instruit par la loi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'et que tu croies que tu es conducteur d’aveugles, lumière de ceux qui sont dans les ténèbres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'instructeur des hommes dépourvus d’intelligence, maître de petits enfants, ayant la formule de la connaissance et de la vérité dans la loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'toi donc qui enseignes les autres, ne t’enseignes-tu pas toi-même? Toi qui prêches qu’on ne doit pas dérober, dérobes-tu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Toi qui dis qu’on ne doit pas commettre adultère, commets-tu adultère? Toi qui as en abomination les idoles, commets-tu des sacrilèges?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Toi qui te glorifies en [la] loi, déshonores-tu Dieu par la transgression de la loi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Car le nom de Dieu est blasphémé à cause de vous parmi les nations, comme il est écrit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Car en effet [la] circoncision est profitable si tu accomplis [la] loi; mais si tu es transgresseur de [la] loi, ta circoncision est devenue incirconcision.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Si donc l’incirconcision garde les exigences de la loi, son incirconcision ne sera-t-elle pas comptée pour circoncision;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'et l’incirconcision qui l’est par nature, en accomplissant la loi, ne te jugera-t-elle pas, toi qui, dans la lettre et la circoncision, es transgresseur de [la] loi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Car celui-là n’est pas Juif qui l’est au-dehors, et celle-là n’est pas la circoncision qui l’est au-dehors dans la chair;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'mais celui-là est Juif qui l’est au-dedans, et la circoncision est du cœur, en esprit, non pas dans la lettre; et la louange de ce [Juif] ne vient pas des hommes, mais de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Quel est donc l’avantage du Juif, ou quel est le profit de la circoncision?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, '– Grand de toute manière, et d’abord en ce que les oracles de Dieu leur ont été confiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Quoi donc? Si quelques-uns n’ont pas cru, leur incrédulité annulera-t-elle la fidélité de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Qu’ainsi n’advienne! mais que Dieu soit vrai et tout homme menteur, selon ce qui est écrit: « En sorte que tu sois justifié dans tes paroles, et que tu aies gain de cause quand tu es jugé ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Mais si notre injustice constate la justice de Dieu, que dirons-nous? Dieu est-il injuste quand il donne cours à la colère? – Je parle selon l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, '– Qu’ainsi n’advienne! puisqu’[alors], comment Dieu jugera-t-il le monde?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Car si la vérité de Dieu dans mon mensonge a abondé pour sa gloire, pourquoi moi aussi suis-je encore jugé comme pécheur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Et non, comme nous sommes calomnieusement accusés et que quelques-uns prétendent que nous disons: Faisons du mal, afin qu’arrive le bien? – desquels le jugement est juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Quoi donc? Sommes-nous plus excellents? Nullement. Car nous avons déjà accusé et Juifs et Grecs d’être tous sous [le] péché,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'selon qu’il est écrit: « Il n’y a point de juste, non pas même un seul;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'il n’y a personne qui ait de l’intelligence, il n’y a personne qui recherche Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'ils se sont tous détournés, ils se sont tous ensemble rendus inutiles; il n’y en a aucun qui exerce la bonté, il n’y en a pas même un seul »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, '« c’est un sépulcre ouvert que leur gosier; ils ont frauduleusement usé de leurs langues »; « il y a du venin d’aspic sous leurs lèvres »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, '« et leur bouche est pleine de malédiction et d’amertume »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, '« leurs pieds sont rapides pour verser le sang;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'la destruction et la misère sont dans leurs voies,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'et ils n’ont point connu la voie de la paix »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, '« il n’y a point de crainte de Dieu devant leurs yeux ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Or nous savons que tout ce que la loi dit, elle le dit à ceux qui sont sous la loi, afin que toute bouche soit fermée, et que tout le monde soit coupable devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'C’est pourquoi nulle chair ne sera justifiée devant lui par des œuvres de loi, car par [la] loi est la connaissance du péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Mais maintenant, sans loi, [la] justice de Dieu est manifestée, témoignage lui étant rendu par la loi et [par] les prophètes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, '[la] justice, dis-je, de Dieu par [la] foi en Jésus Christ envers tous, et sur tous ceux qui croient; car il n’y a pas de différence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'car tous ont péché et n’atteignent pas à la gloire de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, '– étant justifiés gratuitement par sa grâce, par la rédemption qui est dans le christ Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'lequel Dieu a présenté pour propitiatoire, par la foi en son sang, afin de montrer sa justice à cause du support des péchés précédents dans la patience de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'afin de montrer, [dis-je], sa justice dans le temps présent, en sorte qu’il soit juste et justifiant celui qui est de la foi de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Où donc est la vanterie? – Elle a été exclue. – Par quelle loi? – celle des œuvres? – Non, mais par la loi de la foi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'car nous concluons que l’homme est justifié par [la] foi, sans œuvres de loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, '[Dieu] est-il seulement le Dieu des Juifs? ne l’est-il pas aussi des nations? – Certes, aussi des nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'puisque c’est un seul Dieu qui justifiera la circoncision sur le principe de [la] foi et l’incirconcision par la foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Annulons-nous donc [la] loi par la foi? Qu’ainsi n’advienne! au contraire, nous établissons [la] loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Que dirons-nous donc que, selon la chair, Abraham notre père a trouvé?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Car si Abraham a été justifié sur le principe des œuvres, il a de quoi se glorifier, mais non pas relativement à Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'car que dit l’écriture? « Et Abraham crut Dieu, et cela lui fut compté à justice ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Or à celui qui fait des œuvres, le salaire n’est pas compté à titre de grâce, mais à titre de chose due;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'mais à celui qui ne fait pas des œuvres, mais qui croit en celui qui justifie l’impie, sa foi [lui] est comptée à justice;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'ainsi que David aussi exprime la béatitude de l’homme à qui Dieu compte la justice sans œuvres:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '« Bienheureux ceux dont les iniquités ont été pardonnées et dont les péchés ont été couverts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'bienheureux l’homme à qui le ✶Seigneur ne compte point le péché ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Cette béatitude donc [vient-elle] sur la circoncision ou aussi sur l’incirconcision? Car nous disons que la foi fut comptée à Abraham à justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Comment donc lui fut-elle comptée? quand il était dans la circoncision, ou dans l’incirconcision? – Non pas dans la circoncision, mais dans l’incirconcision.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Et il reçut le signe de la circoncision, comme sceau de la justice de la foi qu’[il avait] dans l’incirconcision, pour qu’il soit le père de tous ceux qui croient étant dans l’incirconcision, pour que la justice leur soit aussi comptée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'et qu’il soit père de circoncision, non seulement pour ceux qui sont de la circoncision, mais aussi pour ceux qui marchent sur les traces de la foi qu’a eue notre père Abraham, dans l’incirconcision.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Car ce n’est pas par [la] loi que la promesse d’être héritier du monde [a été faite] à Abraham ou à sa semence, mais par [la] justice de [la] foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Car si ceux qui sont du principe de [la] loi sont héritiers, la foi est rendue vaine et la promesse annulée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'car [la] loi produit la colère, mais là où il n’y a pas de loi, il n’y a pas non plus de transgression.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Pour cette raison, [c’est] sur le principe de [la] foi, afin que [ce soit] selon [la] grâce, pour que la promesse soit assurée à toute la semence, non seulement à celle qui est de la loi, mais aussi à celle qui est de la foi d’Abraham, lequel est père de nous tous');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(selon qu’il est écrit: « Je t’ai établi père de plusieurs nations »), devant Dieu qu’il a cru, – qui fait vivre les morts et appelle les choses qui ne sont point comme si elles étaient,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, '– qui, contre espérance, crut avec espérance, pour devenir père de plusieurs nations, selon ce qui a été dit: « Ainsi sera ta semence ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Et n’étant pas faible dans la foi, il n’eut pas égard à son propre corps déjà amorti, âgé qu’il était d’environ 100 ans, ni à l’état de mort du sein de Sara;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'et il ne forma point de doute sur la promesse de Dieu par incrédulité, mais il fut fortifié dans la foi, donnant gloire à Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'et étant pleinement persuadé que ce qu’il a promis, il est puissant aussi pour l’accomplir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'C’est pourquoi aussi cela lui a été compté à justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Or ce n’est pas pour lui seul qu’il a été écrit que cela lui a été compté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'mais aussi pour nous, à qui il sera compté, à nous qui croyons en celui qui a ressuscité d’entre les morts Jésus notre Seigneur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'lequel a été livré pour nos fautes et a été ressuscité pour notre justification.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Ayant donc été justifiés sur le principe de la foi, nous avons la paix avec Dieu par notre seigneur Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'par lequel nous avons trouvé aussi accès, par la foi, à cette faveur dans laquelle nous sommes, et nous nous glorifions dans l’espérance de la gloire de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Et non seulement [cela], mais aussi nous nous glorifions dans les tribulations, sachant que la tribulation produit la patience,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'et la patience l’expérience, et l’expérience l’espérance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'et l’espérance ne rend point honteux, parce que l’amour de Dieu est versé dans nos cœurs par l’Esprit Saint qui nous a été donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Car Christ, alors que nous étions encore sans force, au temps convenable, est mort pour des impies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Car à peine, pour un juste, quelqu’un mourra-t-il, (car pour l’homme de bien, peut-être, quelqu’un se résoudrait même à mourir);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'mais Dieu constate son amour à lui envers nous, en ce que, lorsque nous étions encore pécheurs, Christ est mort pour nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Beaucoup plutôt donc, ayant été maintenant justifiés par son sang, serons-nous sauvés de la colère par lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Car si, étant ennemis, nous avons été réconciliés avec Dieu par la mort de son Fils, beaucoup plutôt, ayant été réconciliés, serons-nous sauvés par sa vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Et non seulement [cela], mais aussi nous nous glorifions en Dieu par notre seigneur Jésus Christ, par lequel nous avons maintenant reçu la réconciliation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'C’est pourquoi, comme par un seul homme le péché est entré dans le monde, et par le péché la mort, et qu’ainsi la mort a passé à tous les hommes, en ce que tous ont péché...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, '(car jusqu’à [la] loi [le] péché était dans le monde; mais [le] péché n’est pas mis en compte quand il n’y a pas de loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'mais la mort régna depuis Adam jusqu’à Moïse, même sur ceux qui ne péchèrent pas selon la ressemblance de la transgression d’Adam, qui est la figure de celui qui devait venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Mais n’en est-il pas du don de grâce comme de la faute? car si, par la faute d’un seul, plusieurs sont morts, beaucoup plutôt la grâce de Dieu et le don ont abondé envers plusieurs, par la grâce qui est d’un seul homme, Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Et n’en est-il pas du don comme [de ce qui est arrivé] par un seul qui a péché? car le jugement vient d’un seul en condamnation, – mais le don de grâce, de plusieurs fautes, en justification.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Car si, par la faute d’un seul, la mort a régné par un seul, beaucoup plutôt ceux qui reçoivent l’abondance de la grâce et du don de la justice, régneront-ils en vie par un seul, Jésus Christ);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'ainsi donc, comme par une seule faute [les conséquences de cette faute furent] envers tous les hommes en condamnation, ainsi aussi par une seule justice [les conséquences de cette justice furent] envers tous les hommes en justification de vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Car comme par la désobéissance d’un seul homme plusieurs ont été constitués pécheurs, ainsi aussi par l’obéissance d’un seul, plusieurs seront constitués justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Or [la] loi est intervenue afin que la faute abonde; mais là où le péché abondait, la grâce a surabondé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'afin que, comme le péché a régné par la mort, ainsi aussi la grâce règne par [la] justice pour [la] vie éternelle par Jésus Christ notre Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Que dirons-nous donc? Demeurerions-nous dans le péché afin que la grâce abonde?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, '– Qu’ainsi n’advienne! Nous qui sommes morts au péché, comment vivrons-nous encore dans le péché?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, '– Ignorez-vous que nous tous qui avons été baptisés pour le christ Jésus, nous avons été baptisés pour sa mort?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Nous avons donc été ensevelis avec lui par le baptême, pour la mort, afin que comme Christ a été ressuscité d’entre les morts par la gloire du Père, ainsi nous aussi nous marchions en nouveauté de vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Car si nous avons été identifiés avec lui dans la ressemblance de sa mort, nous le serons donc aussi [dans la ressemblance] de [sa] résurrection;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'sachant ceci, que notre vieil homme a été crucifié avec lui, afin que le corps du péché soit annulé, pour que nous ne servions plus le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Car celui qui est mort est justifié du péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Or si nous sommes morts avec Christ, nous croyons que nous vivrons aussi avec lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'sachant que Christ, ayant été ressuscité d’entre les morts, ne meurt plus; la mort ne domine plus sur lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Car en ce qu’il est mort, il est mort une fois pour toutes au péché; mais en ce qu’il vit, il vit à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'De même vous aussi, tenez-vous vous-mêmes pour morts au péché, mais pour vivants à Dieu dans le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Que le péché donc ne règne point dans votre corps mortel pour que vous obéissiez aux convoitises de celui-ci;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'et ne livrez pas vos membres au péché comme instruments d’iniquité, mais livrez-vous vous-mêmes à Dieu, comme d’entre les morts étant [faits] vivants, – et vos membres à Dieu, comme instruments de justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Car le péché ne dominera pas sur vous, parce que vous n’êtes pas sous [la] loi, mais sous [la] grâce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Quoi donc! pécherions-nous, parce que nous ne sommes pas sous [la] loi, mais sous [la] grâce? – Qu’ainsi n’advienne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Ne savez-vous pas qu’à quiconque vous vous livrez vous-mêmes comme esclaves pour obéir, vous êtes esclaves de celui à qui vous obéissez, soit du péché pour [la] mort, soit de l’obéissance pour [la] justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Or grâces à Dieu de ce que vous étiez esclaves du péché, mais de ce que [ensuite] vous avez obéi de cœur à la forme de doctrine dans laquelle vous avez été instruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Mais ayant été affranchis du péché, vous avez été asservis à la justice');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, '(je parle à la façon des hommes, à cause de l’infirmité de votre chair). Car ainsi que vous avez livré vos membres comme esclaves à l’impureté et à l’iniquité pour l’iniquité, ainsi livrez maintenant vos membres comme esclaves à la justice pour la sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Car lorsque vous étiez esclaves du péché, vous étiez libres à l’égard de la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Quel fruit donc aviez-vous alors des choses dont maintenant vous avez honte? car la fin de ces choses est la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, '– Mais maintenant, ayant été affranchis du péché et asservis à Dieu, vous avez votre fruit dans la sainteté et pour fin la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Car les gages du péché, c’est la mort; mais le don de grâce de Dieu, c’est la vie éternelle dans le christ Jésus, notre Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Ignorez-vous, frères, (car je parle à gens qui entendent ce que c’est que [la] loi,) que la loi a autorité sur l’homme aussi longtemps qu’il vit?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Car la femme qui est soumise à un mari, est liée à son mari par [la] loi, tant qu’il vit; mais si le mari meurt, elle est déliée de la loi du mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Ainsi donc, le mari étant vivant, elle sera appelée adultère si elle est à un autre homme; mais si le mari meurt, elle est libre de la loi, de sorte qu’elle n’est pas adultère en étant à un autre homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'C’est pourquoi, mes frères, vous aussi, vous avez été mis à mort à la loi par le corps du Christ, pour être à un autre, à celui qui est ressuscité d’entre les morts, afin que nous portions du fruit pour Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Car, quand nous étions dans la chair, les passions des péchés, lesquelles sont par la loi, agissaient dans nos membres pour porter du fruit pour la mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'mais maintenant nous avons été déliés de la loi, étant morts dans ce en quoi nous étions tenus, en sorte que nous servions en nouveauté d’esprit, et non pas en vieillesse de lettre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Que dirons-nous donc? La loi est-elle péché? – Qu’ainsi n’advienne! Mais je n’aurais pas connu le péché, si ce n’avait été par [la] loi; car je n’aurais pas eu conscience de la convoitise, si la loi n’avait dit: « Tu ne convoiteras point ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Mais le péché, ayant trouvé une occasion par le commandement, a produit en moi toutes les convoitises, car sans [la] loi [le] péché est mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Or moi, étant autrefois sans loi, je vivais; mais le commandement étant venu, le péché a repris vie, et moi je mourus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'et le commandement qui était pour la vie, a été trouvé lui-même pour moi pour la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Car le péché, ayant trouvé une occasion par le commandement, me séduisit, et par lui me tua.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'La loi donc est sainte, et le commandement est saint, et juste, et bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Ce qui est bon est-il donc devenu pour moi [la] mort? – Qu’ainsi n’advienne! Mais le péché, afin qu’il paraisse péché, m’a causé la mort par ce qui est bon, afin que le péché devienne par le commandement excessivement pécheur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Car nous savons que la loi est spirituelle: mais moi je suis charnel, vendu au péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'car ce que je fais, je ne le reconnais pas, car ce n’est pas ce que je veux, que je fais, mais ce que je hais, je le pratique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Or si c’est ce que je ne veux pas que je pratique, j’approuve la loi, [reconnaissant] qu’elle est bonne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Or maintenant, ce n’est plus moi qui fais cela, mais c’est le péché qui habite en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Car je sais qu’en moi, c’est-à-dire en ma chair, il n’habite point de bien; car le vouloir est avec moi, mais accomplir le bien, [cela] je ne le trouve pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Car le bien que je veux, je ne le pratique pas; mais le mal que je ne veux pas, je le fais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Or si ce que je ne veux pas, moi, – je le pratique, ce n’est plus moi qui l’accomplis, mais c’est le péché qui habite en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Je trouve donc cette loi pour moi qui veux pratiquer le bien, que le mal est avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Car je prends plaisir à la loi de Dieu selon l’homme intérieur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'mais je vois dans mes membres une autre loi qui combat contre la loi de mon entendement et qui me rend captif de la loi du péché qui existe dans mes membres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Misérable homme que je suis, qui me délivrera de ce corps de mort?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Je rends grâces à Dieu par Jésus Christ notre Seigneur. Ainsi donc moi-même, de l’entendement je sers la loi de Dieu; mais de la chair, la loi du péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Il n’y a donc maintenant aucune condamnation pour ceux qui sont dans le christ Jésus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'car la loi de l’Esprit de vie dans le christ Jésus, m’a affranchi de la loi du péché et de la mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'car ce qui était impossible à la loi, en ce qu’elle était faible par la chair, Dieu, ayant envoyé son propre Fils en ressemblance de chair de péché, et pour [le] péché, a condamné le péché dans la chair,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'afin que la juste exigence de la loi soit accomplie en nous, qui ne marchons pas selon [la] chair, mais selon [l’]Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Car ceux qui sont selon [la] chair ont leurs pensées aux choses de la chair; mais ceux qui sont selon [l’]Esprit, aux choses de l’Esprit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'car la pensée de la chair est [la] mort; mais la pensée de l’Esprit, vie et paix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, '– parce que la pensée de la chair est inimitié contre Dieu, car elle ne se soumet pas à la loi de Dieu, car aussi elle ne le peut pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Et ceux qui sont dans la chair ne peuvent plaire à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Or vous n’êtes pas dans [la] chair, mais dans [l’]Esprit, si du moins [l’]Esprit de Dieu habite en vous; mais si quelqu’un n’a pas [l’]Esprit de Christ, celui-là n’est pas de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Mais si Christ est en vous, le corps est bien mort à cause du péché, mais l’Esprit est vie à cause de [la] justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Et si l’Esprit de celui qui a ressuscité Jésus d’entre les morts habite en vous, celui qui a ressuscité le Christ d’entre les morts vivifiera vos corps mortels aussi, à cause de son Esprit qui habite en vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Ainsi donc, frères, nous sommes débiteurs, non pas à la chair pour vivre selon [la] chair;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'car si vous vivez selon [la] chair, vous mourrez; mais si par [l’]Esprit vous faites mourir les actions du corps, vous vivrez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Car tous ceux qui sont conduits par [l’]Esprit de Dieu, ceux-là sont fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Car vous n’avez pas reçu un esprit de servitude pour être de nouveau dans la crainte, mais vous avez reçu [l’]Esprit d’adoption, par lequel nous crions: Abba, Père!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'L’Esprit lui-même rend témoignage avec notre esprit, que nous sommes enfants de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'et si [nous sommes] enfants, [nous sommes] aussi héritiers; héritiers de Dieu, cohéritiers de Christ; si du moins nous souffrons avec lui, afin que nous soyons aussi glorifiés avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Car j’estime que les souffrances du temps présent ne sont pas dignes [d’être comparées] avec la gloire à venir qui doit nous être révélée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Car la vive attente de la création attend la révélation des fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Car la création a été assujettie à la vanité (non de sa volonté, mais à cause de celui qui l’a assujettie),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'dans l’espérance que la création elle-même aussi sera affranchie de la servitude de la corruption, pour [jouir de] la liberté de la gloire des enfants de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Car nous savons que toute la création ensemble soupire et est en travail jusqu’à maintenant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'et non seulement [elle], mais nous-mêmes aussi qui avons les prémices de l’Esprit, nous aussi, nous soupirons en nous-mêmes, attendant l’adoption, la délivrance de notre corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Car nous avons été sauvés en espérance: or une espérance qu’on voit n’est pas une espérance; car ce que quelqu’un voit, pourquoi aussi l’espère-t-il?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Mais si ce que nous ne voyons pas, nous l’espérons, nous l’attendons avec patience.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'De même aussi l’Esprit nous est en aide dans notre infirmité; car nous ne savons pas ce qu’il faut demander comme il convient; mais l’Esprit lui-même intercède par des soupirs inexprimables;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, '– et celui qui sonde les cœurs sait quelle est la pensée de l’Esprit, car il intercède pour les saints, selon Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, '– mais nous savons que toutes choses travaillent ensemble pour le bien de ceux qui aiment Dieu, de ceux qui sont appelés selon [son] propos.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Car ceux qu’il a préconnus, il les a aussi prédestinés à être conformes à l’image de son Fils, pour qu’il soit premier-né entre plusieurs frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Et ceux qu’il a prédestinés, il les a aussi appelés; et ceux qu’il a appelés, il les a aussi justifiés; et ceux qu’il a justifiés, il les a aussi glorifiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Que dirons-nous donc à ces choses? Si Dieu est pour nous, qui sera contre nous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Celui même qui n’a pas épargné son propre Fils, mais qui l’a livré pour nous tous, comment ne nous fera-t-il pas don aussi, librement, de toutes choses avec lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Qui intentera accusation contre des élus de Dieu? – C’est Dieu qui justifie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'qui est celui qui condamne? – C’est Christ qui est mort, mais plutôt qui est aussi ressuscité, qui est aussi à la droite de Dieu, qui aussi intercède pour nous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'qui est-ce qui nous séparera de l’amour du Christ? Tribulation, ou détresse, ou persécution, ou famine, ou nudité, ou péril, ou épée?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Selon qu’il est écrit: « Pour l’amour de toi, nous sommes mis à mort tout le jour; nous avons été estimés comme des brebis de tuerie ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Au contraire, dans toutes ces choses, nous sommes plus que vainqueurs par celui qui nous a aimés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Car je suis assuré que ni mort, ni vie, ni anges, ni principautés, ni choses présentes, ni choses à venir, ni puissances,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'ni hauteur, ni profondeur, ni aucune autre créature, ne pourra nous séparer de l’amour de Dieu, qui est dans le christ Jésus, notre Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Je dis la vérité en Christ; je ne mens point, ma conscience me rendant témoignage par l’Esprit Saint,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'que j’ai une grande tristesse et une douleur continuelle dans mon cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'car moi-même j’ai souhaité d’être [par] anathème [séparé] du Christ, pour mes frères, mes parents selon la chair,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'qui sont Israélites, auxquels sont l’adoption, et la gloire, et les alliances, et le don de la loi, et le service [divin], et les promesses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'auxquels sont les pères, et desquels, selon la chair, est [issu] le Christ, qui est sur toutes choses Dieu béni éternellement. Amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, '– Ce n’est pas cependant comme si la parole de Dieu avait été sans effet, car tous ceux qui sont [issus] d’Israël ne sont pas Israël;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'aussi, pour être [la] semence d’Abraham, ils ne sont pas tous enfants; mais « en Isaac te sera appelée [une] semence »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'c’est-à-dire, ce ne sont pas les enfants de la chair qui sont enfants de Dieu; mais les enfants de la promesse sont comptés pour semence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Car cette parole est [une parole] de promesse: « En cette saison-ci, je viendrai, et Sara aura un fils ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Et non seulement [cela], mais aussi quant à Rebecca, lorsqu’elle conçut d’un, d’Isaac, notre père,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, '(car avant que les enfants soient nés et qu’ils aient rien fait de bon ou de mauvais, afin que le propos de Dieu selon l’élection demeure, non point sur le principe des œuvres, mais de celui qui appelle,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'il lui fut dit: « Le plus grand sera asservi au plus petit »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'ainsi qu’il est écrit: « J’ai aimé Jacob, et j’ai haï Ésaü ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Que dirons-nous donc? Y a-t-il de l’injustice en Dieu? Qu’ainsi n’advienne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Car il dit à Moïse: « Je ferai miséricorde à celui à qui je fais miséricorde, et j’aurai compassion de qui j’ai compassion ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Ainsi donc ce n’est pas de celui qui veut, ni de celui qui court, mais de Dieu qui fait miséricorde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Car l’écriture dit au Pharaon: « C’est pour cela même que je t’ai suscité, pour montrer en toi ma puissance, et pour que mon nom soit publié dans toute la terre ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Ainsi donc il fait miséricorde à qui il veut, et il endurcit qui il veut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Tu me diras donc: Pourquoi se plaint-il encore? car qui est-ce qui a résisté à sa volonté?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Mais plutôt, toi, ô homme, qui es-tu, qui contestes contre Dieu? La chose formée dira-t-elle à celui qui l’a formée: Pourquoi m’as-tu ainsi faite?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Le potier n’a-t-il pas pouvoir sur l’argile pour faire de la même masse un vase à honneur et un autre à déshonneur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Et si Dieu, voulant montrer sa colère et faire connaître sa puissance, a supporté avec une grande patience des vases de colère tout préparés pour la destruction;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, '– et afin de faire connaître les richesses de sa gloire dans des vases de miséricorde qu’il a préparés d’avance pour la gloire...?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'lesquels aussi il a appelés, [savoir] nous, non seulement d’entre les Juifs, mais aussi d’entre les nations:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'comme aussi il dit en Osée: « J’appellerai mon peuple celui qui n’était pas mon peuple, et bien-aimée celle qui n’était pas bien-aimée »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, '« et il arrivera que dans le lieu où il leur a été dit: Vous n’êtes pas mon peuple, là ils seront appelés fils du Dieu vivant ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Mais Ésaïe s’écrie au sujet d’Israël: « Quand le nombre des fils d’Israël serait comme le sable de la mer, le résidu [seul] sera sauvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Car il consomme et abrège l’affaire en justice, parce que le ✶Seigneur fera une affaire abrégée sur la terre ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Et comme Ésaïe a dit auparavant: « Si le ✶Seigneur Sabaoth ne nous avait laissé [quelque] semence, nous serions devenus comme Sodome et nous aurions été semblables à Gomorrhe ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Que dirons-nous donc? Que les nations qui ne poursuivaient pas [la] justice, ont trouvé [la] justice, [la] justice qui est sur le principe de [la] foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Mais Israël, poursuivant une loi de justice, n’est point parvenu à [cette] loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Pourquoi? – Parce que ce n’a point été sur le principe de la foi, mais comme sur le principe des œuvres: car ils ont heurté contre la pierre d’achoppement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'selon qu’il est écrit: « Voici, je mets en Sion une pierre d’achoppement, et un rocher de chute », et « celui qui croit en lui ne sera pas confus ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Frères, le souhait de mon cœur, et la supplication [que j’adresse] à Dieu pour eux, c’est qu’ils soient sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Car je leur rends témoignage qu’ils ont du zèle pour Dieu, mais non selon la connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Car, ignorant la justice de Dieu et cherchant à établir leur propre justice, ils ne se sont pas soumis à la justice de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Car Christ est [la] fin de [la] loi pour justice à tout croyant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Car Moïse décrit la justice qui vient de la loi: « L’homme qui aura pratiqué ces choses vivra par elles ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Mais la justice qui est sur le principe de la foi parle ainsi: Ne dis pas en ton cœur: « Qui montera au ciel? » – c’est à savoir pour en faire descendre Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'ou: « Qui descendra dans l’abîme? » – c’est à savoir pour faire monter Christ d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Mais que dit-elle? « La parole est près de toi, dans ta bouche et dans ton cœur », c’est-à-dire la parole de la foi, laquelle nous prêchons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, '[savoir] que, si tu confesses de ta bouche Jésus comme Seigneur et que tu croies dans ton cœur que Dieu l’a ressuscité d’entre les morts, tu seras sauvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Car du cœur on croit à justice, et de la bouche on fait confession à salut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Car l’écriture dit: « Quiconque croit en lui ne sera pas confus ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Car il n’y a pas de différence de Juif et de Grec, car le même Seigneur de tous est riche envers tous ceux qui l’invoquent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, '« car quiconque invoquera le nom du ✶Seigneur sera sauvé ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Comment donc invoqueront-ils celui en qui ils n’ont point cru? Et comment croiront-ils en celui dont ils n’ont point entendu parler? Et comment entendront-ils sans quelqu’un qui prêche?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Et comment prêcheront-ils, à moins qu’ils ne soient envoyés? selon qu’il est écrit: « Combien sont beaux les pieds de ceux qui annoncent la paix, de ceux qui annoncent de bonnes choses ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Mais tous n’ont pas obéi à l’évangile; car Ésaïe dit: « ✶Seigneur, qui est-ce qui a cru à ce qu’il a entendu de nous? ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Ainsi la foi est de ce qu’on entend, et ce qu’on entend par la parole de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Mais je dis: N’ont-ils pas entendu? Oui, certes, « leur voix est allée par toute la terre, et leurs paroles jusqu’aux extrémités de la terre habitée ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Mais je dis: Israël n’a-t-il pas connu? Moïse, le premier, dit: « Je vous exciterai à la jalousie par ce qui n’est pas une nation; je vous provoquerai à la colère par une nation sans intelligence ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Mais Ésaïe s’enhardit tout à fait, et dit: « J’ai été trouvé de ceux qui ne me cherchaient point, et j’ai été manifesté à ceux qui ne s’enquéraient point de moi ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Mais quant à Israël, il dit: « Tout le long du jour j’ai étendu mes mains vers un peuple désobéissant et contredisant ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Je dis donc: Dieu a-t-il rejeté son peuple? Qu’ainsi n’advienne! Car moi aussi je suis Israélite, de la semence d’Abraham, de la tribu de Benjamin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Dieu n’a point rejeté son peuple, lequel il a préconnu. Ne savez-vous pas ce que l’écriture dit dans [l’histoire d’]Élie, comment il fait requête à Dieu contre Israël?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '« ✶Seigneur, ils ont tué tes prophètes; ils ont renversé tes autels; et moi, je suis demeuré seul, et ils cherchent ma vie. »');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Mais que lui dit la réponse divine? « Je me suis réservé 7 000 hommes qui n’ont pas fléchi le genou devant Baal ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Ainsi donc, au temps actuel aussi, il y a un résidu selon [l’]élection de [la] grâce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Or, si c’est par la grâce, ce n’est plus sur le principe des œuvres, puisque autrement la grâce n’est plus [la] grâce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Quoi donc? Ce qu’Israël recherche, il ne l’a pas obtenu, mais l’élection l’a obtenu, et les autres ont été endurcis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'selon qu’il est écrit: « Dieu leur a donné un esprit d’étourdissement, des yeux pour ne point voir et des oreilles pour ne point entendre, jusqu’au jour d’aujourd’hui ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Et David dit: « Que leur table devienne pour eux un filet, et un piège, et une occasion de chute, et une rétribution;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'que leurs yeux soient obscurcis pour ne point voir; et courbe continuellement leur dos ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Je dis donc: Ont-ils bronché afin qu’ils tombent? Qu’ainsi n’advienne! Mais par leur chute, le salut [parvient] aux nations pour les exciter à la jalousie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Or, si leur chute est la richesse du monde, et leur diminution, la richesse des nations, combien plus le sera leur plénitude!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Car je parle à vous, nations, en tant que moi je suis en effet apôtre des nations, je glorifie mon ministère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'si en quelque façon je puis exciter à la jalousie ma chair et sauver quelques-uns d’entre eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Car si leur mise à l’écart est la réconciliation du monde, quelle sera leur réception, sinon la vie d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Or, si les prémices sont saintes, la masse l’est aussi; et si la racine est sainte, les branches le sont aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Or, si quelques-unes des branches ont été arrachées, et si toi qui étais un olivier sauvage, as été enté au milieu d’elles, et es devenu coparticipant de la racine et de la graisse de l’olivier,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'ne te glorifie pas contre les branches; mais si tu te glorifies, ce n’est pas toi qui portes la racine, mais c’est la racine qui te porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Tu diras donc: Les branches ont été arrachées, afin que moi je sois enté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Bien! elles ont été arrachées pour cause d’incrédulité, et toi tu es debout par la foi. Ne t’enorgueillis pas, mais crains');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, '(si en effet Dieu n’a pas épargné les branches [qui sont telles] selon la nature), qu’il ne t’épargne pas non plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Considère donc la bonté et la sévérité de Dieu: la sévérité envers ceux qui sont tombés; la bonté de Dieu envers toi, si tu persévères dans cette bonté; puisque autrement, toi aussi, tu seras coupé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Et eux aussi, s’ils ne persévèrent pas dans l’incrédulité, ils seront entés, car Dieu est puissant pour les enter de nouveau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Car si toi, tu as été coupé de l’olivier qui selon la nature était sauvage, et as été enté contre nature sur l’olivier franc, combien plus ceux qui en sont selon la nature seront-ils entés sur leur propre olivier?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Car je ne veux pas, frères, que vous ignoriez ce mystère-ci, afin que vous ne soyez pas sages à vos propres yeux: c’est qu’un endurcissement partiel est arrivé à Israël jusqu’à ce que la plénitude des nations soit entrée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'et ainsi tout Israël sera sauvé, selon qu’il est écrit: « Le libérateur viendra de Sion; il détournera de Jacob l’impiété.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Et c’est là l’alliance de ma part pour eux, lorsque j’ôterai leurs péchés ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'En ce qui concerne l’évangile, ils sont ennemis à cause de vous; mais en ce qui concerne l’élection, ils sont bien-aimés à cause des pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Car les dons de grâce et l’appel de Dieu sont sans repentir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Car comme vous aussi vous avez été autrefois désobéissants à Dieu et que maintenant vous êtes devenus des objets de miséricorde par la désobéissance de ceux-ci,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'de même ceux-ci aussi ont été maintenant désobéissants à votre miséricorde, afin qu’eux aussi deviennent des objets de miséricorde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Car Dieu a renfermé tous, [Juifs et nations], dans la désobéissance, afin de faire miséricorde à tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Ô profondeur des richesses et de la sagesse et de la connaissance de Dieu! Que ses jugements sont insondables, et ses voies introuvables!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Car qui a connu la pensée du ✶Seigneur, ou qui a été son conseiller?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'ou qui lui a donné le premier, et il lui sera rendu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Car de lui, et par lui, et pour lui, sont toutes choses! À lui soit la gloire éternellement! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Je vous exhorte donc, frères, par les compassions de Dieu, à présenter vos corps en sacrifice vivant, saint, agréable à Dieu, [ce qui est] votre service intelligent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Et ne vous conformez pas à ce siècle; mais soyez transformés par le renouvellement de [votre] entendement, pour que vous discerniez quelle est la volonté de Dieu, bonne et agréable et parfaite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Car, par la grâce qui m’a été donnée, je dis à chacun de ceux qui sont parmi vous de ne pas avoir une haute pensée [de lui-même], au-dessus de celle qu’il convient d’avoir, mais de penser de manière à avoir de saines pensées, selon la mesure de foi que Dieu a départie à chacun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Car comme dans un seul corps nous avons plusieurs membres, et que tous les membres n’ont pas la même fonction,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'ainsi nous qui sommes plusieurs, sommes un seul corps en Christ, et chacun individuellement membres l’un de l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Or ayant des dons de grâce différents, selon la grâce qui nous a été donnée, soit la prophétie, [prophétisons] selon la proportion de la foi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'soit le service, [soyons occupés] du service; soit celui qui enseigne, [qu’il s’applique] à l’enseignement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'soit celui qui exhorte, à l’exhortation; – celui qui distribue, [qu’il le fasse] en simplicité; celui qui est à la tête, [qu’il conduise] soigneusement; celui qui exerce la miséricorde, [qu’il le fasse] joyeusement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Que l’amour soit sans hypocrisie; ayez en horreur le mal, tenez ferme au bien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'quant à l’amour fraternel, soyez pleins d’affection les uns pour les autres; quant à l’honneur, étant les premiers à le rendre aux autres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'quant à l’activité, pas paresseux; fervents en esprit; servant le Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'vous réjouissant dans l’espérance; patients dans la tribulation; persévérants dans la prière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'subvenant aux nécessités des saints; vous appliquant à l’hospitalité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Bénissez ceux qui vous persécutent; bénissez et ne maudissez pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Réjouissez-vous avec ceux qui se réjouissent, et pleurez avec ceux qui pleurent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'ayant, les uns envers les autres, un même sentiment; ne pensant pas aux choses élevées, mais vous associant aux humbles. Ne soyez pas sages à vos propres yeux;...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'ne rendant à personne mal pour mal; vous proposant ce qui est honnête devant tous les hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 's’il est possible, autant que cela dépend de vous, vivant en paix avec tous les hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'ne vous vengeant pas vous-mêmes, bien-aimés; mais laissez agir la colère, car il est écrit: « À moi la vengeance; moi je rendrai, dit le ✶Seigneur ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, '« Si donc ton ennemi a faim, donne-lui à manger; s’il a soif, donne-lui à boire; car en faisant cela tu entasseras des charbons de feu sur sa tête ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Ne sois pas surmonté par le mal, mais surmonte le mal par le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Que toute âme se soumette aux autorités qui sont au-dessus d’elle; car il n’existe pas d’autorité, si ce n’est de par Dieu; et celles qui existent sont ordonnées de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'de sorte que celui qui résiste à l’autorité résiste à l’ordonnance de Dieu; et ceux qui résistent feront venir un jugement sur eux-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Car les magistrats ne sont pas une terreur pour une bonne œuvre, mais pour une mauvaise. Or veux-tu ne pas craindre l’autorité? fais le bien, et tu recevras d’elle de la louange;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'car [le magistrat] est serviteur de Dieu pour ton bien; mais si tu fais le mal, crains; car il ne porte pas l’épée en vain; car il est serviteur de Dieu, vengeur pour [exécuter] la colère sur celui qui fait le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'C’est pourquoi il est nécessaire d’être soumis, non seulement à cause de la colère, mais aussi à cause de la conscience.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Car c’est pour cela que vous payez aussi les tributs; – car ils sont ministres de Dieu, s’employant constamment à cela même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Rendez à tous ce qui leur est dû: à qui le tribut, le tribut; à qui le péage, le péage; à qui la crainte, la crainte; à qui l’honneur, l’honneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Ne devez rien à personne, sinon de vous aimer les uns les autres, car celui qui aime les autres a accompli [la] loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Car ce [qui est dit]: « Tu ne commettras point adultère, tu ne tueras point, tu ne déroberas point, tu ne convoiteras point », et tout autre commandement qu’il puisse y avoir, est résumé dans cette parole-ci: « Tu aimeras ton prochain comme toi-même ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'L’amour ne fait point de mal au prochain; l’amour donc est la somme de la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Et [encore] ceci: connaissant le temps, que c’est déjà l’heure de nous réveiller du sommeil, car maintenant le salut est plus près de nous que lorsque nous avons cru:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'la nuit est fort avancée, et le jour s’est approché; rejetons donc les œuvres des ténèbres, et revêtons les armes de la lumière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Conduisons-nous honnêtement, comme de jour; non point en orgies ni en ivrogneries; non point en impudicités ni en débauches; non point en querelles ni en envie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Mais revêtez le seigneur Jésus Christ, et ne prenez pas soin de la chair pour [satisfaire à ses] convoitises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Or quant à celui qui est faible en foi, recevez-le; non pas pour la décision de questions [douteuses].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'L’un croit pouvoir manger de toutes choses; l’autre qui est faible, mange des herbes:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'que celui qui mange ne méprise pas celui qui ne mange pas; et que celui qui ne mange pas ne juge pas celui qui mange, car Dieu l’a reçu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Qui es-tu, toi qui juges le domestique d’autrui? Il se tient debout ou il tombe pour son propre maître; et il sera tenu debout, car le Seigneur est puissant pour le tenir debout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'L’un estime un jour plus qu’un autre jour, et l’autre estime tous les jours [égaux]: que chacun soit pleinement persuadé dans son propre esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Celui qui a égard au jour, y a égard à cause du Seigneur; et celui qui mange, mange à cause du Seigneur, car il rend grâces à Dieu; et celui qui ne mange pas, ne mange pas à cause du Seigneur, et il rend grâces à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Car nul de nous ne vit ayant égard à lui-même, et nul ne meurt ayant égard à lui-même:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'mais soit que nous vivions, nous vivons ayant égard au Seigneur, soit que nous mourions, nous mourons ayant égard au Seigneur; soit donc que nous vivions, soit que nous mourions, nous sommes du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Car c’est pour cela que Christ est mort et qu’il a revécu, afin qu’il domine et sur les morts et sur les vivants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Mais toi, pourquoi juges-tu ton frère? Ou aussi toi, pourquoi méprises-tu ton frère? Car nous comparaîtrons tous devant le tribunal de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'car il est écrit: « Je suis vivant, dit le ✶Seigneur, que tout genou se ploiera devant moi, et que toute langue confessera hautement Dieu ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Ainsi donc, chacun de nous rendra compte pour lui-même à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Ne nous jugeons donc plus l’un l’autre; mais jugez plutôt ceci, de ne pas mettre une pierre d’achoppement ou une occasion de chute devant votre frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Je sais, et je suis persuadé dans le seigneur Jésus, que rien n’est souillé par soi-même, sauf qu’à celui qui croit qu’une chose est souillée, elle lui est souillée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Car si, à cause d’une viande, ton frère est attristé, tu ne marches plus selon l’amour. Ne détruis pas par ta viande celui pour lequel Christ est mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Que ce qui est bien en vous ne soit donc pas blâmé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Car le royaume de Dieu n’est pas manger et boire, mais justice, et paix, et joie dans l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Car celui qui en cela sert le Christ est agréable à Dieu et approuvé des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Ainsi donc poursuivons les choses qui tendent à la paix et celles qui tendent à l’édification mutuelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'À cause d’une viande, ne détruis pas l’œuvre de Dieu. Toutes choses, il est vrai, sont pures; mais il y a du mal pour l’homme qui mange en bronchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Il est bon de ne pas manger de chair, de ne pas boire de vin, et de ne [faire aucune chose] en laquelle ton frère bronche, ou est scandalisé, ou est faible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Toi, tu as de la foi; aie-la par-devers toi-même devant Dieu; bienheureux est celui qui ne se juge pas lui-même en ce qu’il approuve;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'mais celui qui hésite, s’il mange, est condamné, parce qu’[il n’agit] pas sur un principe de foi. Or tout ce qui n’est pas sur le principe de la foi est péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Or nous devons, nous les forts, porter les infirmités des faibles, et non pas nous plaire à nous-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Que chacun de nous cherche à plaire à son prochain, en vue du bien, pour l’édification.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Car aussi le Christ n’a point cherché à plaire à lui-même, mais selon qu’il est écrit: « Les outrages de ceux qui t’outragent sont tombés sur moi ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Car toutes les choses qui ont été écrites auparavant ont été écrites pour notre instruction, afin que, par la patience et par la consolation des écritures, nous ayons espérance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Or le Dieu de patience et de consolation vous donne d’avoir entre vous un même sentiment selon le christ Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'afin que, d’un commun accord, d’une même bouche, vous glorifiiez le Dieu et Père de notre seigneur Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'C’est pourquoi recevez-vous les uns les autres, comme aussi le Christ vous a reçus, à la gloire de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Car je dis que Jésus Christ a été serviteur de [la] circoncision, pour la vérité de Dieu, pour la confirmation des promesses [faites] aux pères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'et pour que les nations glorifient Dieu pour [la] miséricorde, selon qu’il est écrit: « C’est pourquoi je te célébrerai parmi les nations, et je psalmodierai à ton nom ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Et encore, il dit: « Nations, réjouissez-vous avec son peuple ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Et encore: « Louez le ✶Seigneur, vous toutes les nations, et que tous les peuples le célèbrent ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Et encore Ésaïe dit: « Il y aura la racine de Jessé, et il y en aura un qui s’élèvera pour gouverner les nations; c’est en lui que les nations espéreront ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Or que le Dieu d’espérance vous remplisse de toute joie et paix en croyant, pour que vous abondiez en espérance par la puissance de l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Or je suis persuadé, mes frères, moi-même aussi, à votre égard, que vous-mêmes aussi vous êtes pleins de bonté, remplis de toute connaissance et capables de vous exhorter l’un l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Mais je vous ai écrit en quelque sorte plus hardiment, frères, comme réveillant vos souvenirs, à cause de la grâce qui m’a été donnée par Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'pour que je sois ministre du christ Jésus envers les nations, exerçant la sacrificature dans l’évangile de Dieu, afin que l’offrande des nations soit agréable, étant sanctifiée par l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'J’ai donc de quoi me glorifier dans le christ Jésus, dans les choses qui concernent Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Car je n’oserai rien dire que Christ n’ait accompli par moi pour l’obéissance des nations, par parole et par œuvre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'par la puissance de miracles et de prodiges, par la puissance de l’Esprit [de Dieu]; de sorte que, depuis Jérusalem, et tout alentour, jusqu’en Illyrie, j’ai pleinement annoncé l’évangile du Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'mais ainsi m’attachant à évangéliser, non pas là où Christ avait été prêché, (afin que je n’édifie pas sur le fondement d’autrui)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'mais selon qu’il est écrit: « Ceux à qui il n’a pas été annoncé, verront, et ceux qui n’ont pas entendu, comprendront ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'C’est pourquoi aussi j’ai été souvent empêché d’aller vers vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'mais maintenant, n’ayant plus de sujet [de m’arrêter] dans ces pays-ci, et ayant depuis plusieurs années un grand désir d’aller vers vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'pour le cas où je me rendrais en Espagne...; car j’espère que je vous verrai à mon passage, et que vous me ferez la conduite de ce côté-là, quand j’aurai d’abord un peu joui de vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'mais à présent je vais à Jérusalem, étant occupé au service des saints;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'car la Macédoine et l’Achaïe ont trouvé bon de subvenir, par une contribution, aux besoins des pauvres d’entre les saints qui sont à Jérusalem;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'car elles l’ont pris à cœur, et elles sont leurs débiteurs; car si les nations ont participé à leurs [biens] spirituels, elles sont aussi sous l’obligation de les servir dans les choses charnelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Après donc que j’aurai achevé cette [œuvre] et que je leur aurai scellé ce fruit, j’irai en Espagne en passant par [chez] vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Et je sais qu’en allant auprès de vous, j’irai dans la plénitude de la bénédiction de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Mais je vous exhorte, frères, par notre seigneur Jésus Christ et par l’amour de l’Esprit, à combattre avec moi dans vos prières à Dieu pour moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'afin que je sois délivré des incrédules qui sont en Judée, et que mon service que j’ai [à accomplir] à Jérusalem soit agréable aux saints,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'afin que j’aille vers vous avec joie par la volonté de Dieu, et que je me récrée avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Or, que le Dieu de paix soit avec vous tous! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Or je vous recommande Phœbé, notre sœur, qui est servante de l’assemblée qui est à Cenchrée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'afin que vous la receviez dans le Seigneur, comme il convient à des saints, et que vous l’assistiez dans toute affaire pour laquelle elle aurait besoin de vous; car elle-même aussi a été en aide à plusieurs, et à moi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Saluez Prisca et Aquilas, mes compagnons d’œuvre dans le christ Jésus');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, '(qui, pour ma vie, ont exposé leur propre cou; auxquels je ne rends pas grâces moi seul, mais aussi toutes les assemblées des nations),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'et l’assemblée qui [se réunit] dans leur maison. Saluez Épaïnète, mon bien-aimé, qui est les prémices de l’Asie pour Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Saluez Marie, qui a beaucoup travaillé pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Saluez Andronique et Junias, mes parents et mes compagnons de captivité, qui sont distingués parmi les apôtres, qui même ont été avant moi en Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Saluez Amplias, mon bien-aimé dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Saluez Urbain, notre compagnon d’œuvre en Christ, et Stachys, mon bien-aimé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Saluez Appellès, approuvé en Christ. Saluez ceux de chez Aristobule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Saluez Hérodion, mon parent. Saluez ceux de chez Narcisse qui sont dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Saluez Tryphène et Tryphose, lesquelles travaillent dans le Seigneur. Saluez Persis, la bien-aimée, qui a beaucoup travaillé dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Saluez Rufus, l’élu dans le Seigneur, et sa mère, qui est aussi la mienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Saluez Asyncrite, Phlégon, Hermas, Patrobas, Hermès, et les frères qui sont avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Saluez Philologue, et Julie, Nérée et sa sœur, et Olympas, et tous les saints qui sont avec eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Saluez-vous les uns les autres par un saint baiser. Toutes les assemblées du Christ vous saluent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Or je vous exhorte, frères, à avoir l’œil sur ceux qui causent les divisions et les occasions de chute par [des choses qui ne sont] pas selon la doctrine que vous avez apprise; et éloignez-vous d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Car ces sortes de gens ne servent pas notre seigneur Christ, mais leur propre ventre; et par de douces paroles et un beau langage, ils séduisent les cœurs des simples.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Car votre obéissance est venue à [la connaissance de] tous. Je me réjouis donc à votre sujet; mais je désire que vous soyez sages quant au bien, et simples quant au mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Or le Dieu de paix brisera bientôt Satan sous vos pieds. Que la grâce de notre seigneur Jésus Christ soit avec vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Timothée, mon compagnon d’œuvre, et Lucius, et Jason, et Sosipater, mes parents, vous saluent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Moi, Tertius, qui ai écrit la lettre, je vous salue dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Gaïus, mon hôte et celui de toute l’assemblée, vous salue. Éraste, l’administrateur de la ville, et le frère Quartus vous saluent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Que la grâce de notre seigneur Jésus Christ soit avec vous tous! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Or, à celui qui est puissant pour vous affermir selon mon évangile et la prédication de Jésus Christ, selon la révélation du mystère à l’égard duquel le silence a été gardé dès les temps éternels,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'mais qui a été manifesté maintenant, et qui, par des écrits prophétiques, a été donné à connaître à toutes les nations, selon le commandement du Dieu éternel, pour [l’]obéissance de [la] foi,...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'au Dieu qui seul est sage, par Jésus Christ, – auquel soit la gloire éternellement! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paul, apôtre appelé de Jésus Christ par la volonté de Dieu, et Sosthène, le frère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'à l’assemblée de Dieu qui est à Corinthe, aux sanctifiés dans le christ Jésus, saints appelés, avec tous ceux qui en tout lieu invoquent le nom de notre seigneur Jésus Christ, et leur [seigneur] et le nôtre:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Grâce et paix à vous, de la part de Dieu notre Père et du seigneur Jésus Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Je rends toujours grâces à mon Dieu pour vous, à cause de la grâce de Dieu qui vous a été donnée dans le christ Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'de ce qu’en toutes choses vous avez été enrichis en lui en toute parole et toute connaissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'selon que le témoignage du Christ a été confirmé au milieu de vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'de sorte que vous ne manquez d’aucun don de grâce pendant que vous attendez la révélation de notre seigneur Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'qui aussi vous affermira jusqu’à la fin [pour être] irréprochables dans la journée de notre seigneur Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Dieu, par qui vous avez été appelés à la communion de son Fils Jésus Christ, notre Seigneur, est fidèle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Or je vous exhorte, frères, par le nom de notre seigneur Jésus Christ, à parler tous un même langage, et à ce qu’il n’y ait pas de divisions parmi vous, mais que vous soyez parfaitement unis dans un même sentiment et dans un même avis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Car, mes frères, il m’a été dit de vous, par ceux qui sont de chez Chloé, qu’il y a des dissensions parmi vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Or voici ce que je dis, c’est que chacun de vous dit: Moi, je suis de Paul; et moi, d’Apollos; et moi, de Céphas; et moi, de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Le Christ est-il divisé? Paul a-t-il été crucifié pour vous? ou avez-vous été baptisés pour le nom de Paul?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Je rends grâces à Dieu de ce que je n’ai baptisé aucun de vous, sinon Crispus et Gaïus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'afin que personne ne dise que j’ai baptisé pour mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'J’ai bien aussi baptisé la maison de Stéphanas; du reste je ne sais pas si j’ai baptisé quelqu’un d’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Car Christ ne m’a pas envoyé baptiser, mais évangéliser, non point avec sagesse de parole, afin que la croix du Christ ne soit pas rendue vaine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'car la parole de la croix est folie pour ceux qui périssent, mais à nous qui obtenons le salut elle est la puissance de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Car il est écrit: « Je détruirai la sagesse des sages et j’annulerai l’intelligence des intelligents ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Où est le sage? où est le scribe? où est le disputeur de ce siècle? Dieu n’a-t-il pas fait de la sagesse du monde une folie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Car, puisque, dans la sagesse de Dieu, le monde, par la sagesse, n’a pas connu Dieu, il a plu à Dieu, par la folie de la prédication, de sauver ceux qui croient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'puisque les Juifs demandent des miracles et que les Grecs recherchent la sagesse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'mais nous, nous prêchons Christ crucifié, aux Juifs occasion de chute, aux nations folie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'mais à ceux qui sont appelés, et Juifs et Grecs, Christ la puissance de Dieu et la sagesse de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'parce que la folie de Dieu est plus sage que les hommes, et que la faiblesse de Dieu est plus forte que les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Car considérez votre appel, frères, – qu’il n’y a pas beaucoup de sages selon la chair, pas beaucoup de puissants, pas beaucoup de nobles,...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Mais Dieu a choisi les choses folles du monde pour couvrir de honte les [hommes] sages; et Dieu a choisi les choses faibles du monde pour couvrir de honte les choses fortes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'et Dieu a choisi les choses viles du monde, et celles qui sont méprisées, et celles qui ne sont pas, pour annuler celles qui sont;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'en sorte que nulle chair ne se glorifie devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Or vous êtes de lui dans le christ Jésus, qui nous a été fait sagesse de la part de Dieu, et justice, et sainteté, et rédemption,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'afin que, comme il est écrit, « celui qui se glorifie, se glorifie dans le ✶Seigneur ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Et moi-même, quand je suis allé auprès de vous, frères, je ne suis pas allé avec excellence de parole ou de sagesse, en vous annonçant le témoignage de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'car je n’ai pas jugé bon de savoir quoi que ce soit parmi vous, sinon Jésus Christ, et Jésus Christ crucifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Et moi-même j’ai été parmi vous dans la faiblesse, et dans la crainte, et dans un grand tremblement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'et ma parole et ma prédication n’ont pas été en paroles persuasives de sagesse, mais en démonstration de l’Esprit et de puissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'afin que votre foi ne repose pas sur la sagesse des hommes, mais sur la puissance de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Or nous parlons sagesse parmi les parfaits, sagesse toutefois non pas de ce siècle, ni des chefs de ce siècle qui s’en vont;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'mais nous parlons la sagesse de Dieu en mystère, la [sagesse] cachée, laquelle Dieu avait préordonnée avant les siècles pour notre gloire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'qu’aucun des chefs de ce siècle n’a connue, (car s’ils l’avaient connue, ils n’auraient pas crucifié le Seigneur de gloire,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, '– mais selon qu’il est écrit: « Ce que l’œil n’a pas vu, et que l’oreille n’a pas entendu, et qui n’est pas monté au cœur de l’homme, ce que Dieu a préparé pour ceux qui l’aiment »,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, '– mais Dieu nous l’a révélée par son Esprit; car l’Esprit sonde toutes choses, même les choses profondes de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Car qui des hommes connaît les choses de l’homme, si ce n’est l’esprit de l’homme qui est en lui? Ainsi personne ne connaît les choses de Dieu non plus, si ce n’est l’Esprit de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Mais nous, nous avons reçu, non l’esprit du monde, mais l’Esprit qui est de Dieu, afin que nous connaissions les choses qui nous ont été librement données par Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'desquelles aussi nous parlons, non point en paroles enseignées de sagesse humaine, mais en paroles enseignées de l’Esprit, communiquant des choses spirituelles par des moyens spirituels.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Or l’homme animal ne reçoit pas les choses qui sont de l’Esprit de Dieu, car elles lui sont folie; et il ne peut les connaître, parce qu’elles se discernent spirituellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Mais celui qui est spirituel discerne toutes choses; mais lui n’est discerné par personne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'car « qui a connu la pensée du ✶Seigneur pour qu’il l’instruise »? Mais nous, nous avons la pensée de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Et moi, frères, je n’ai pas pu vous parler comme à des hommes spirituels, mais comme à des hommes charnels, comme à de petits enfants en Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Je vous ai donné du lait à boire, non pas de la viande, car vous ne pouviez pas encore [la supporter], et même maintenant encore vous ne le pouvez pas,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'car vous êtes encore charnels. Car, puisqu’il y a parmi vous de l’envie et des querelles, n’êtes-vous pas charnels et ne marchez-vous pas à la manière des hommes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Car quand l’un dit: Moi, je suis de Paul; et l’autre: moi, je suis d’Apollos, n’êtes-vous pas des hommes?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Qui donc est Apollos, et qui Paul? Des serviteurs par lesquels vous avez cru, et comme le Seigneur a donné à chacun d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Moi, j’ai planté, Apollos a arrosé; mais Dieu a donné l’accroissement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'De sorte que ni celui qui plante n’est rien, ni celui qui arrose, mais Dieu qui donne l’accroissement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Or celui qui plante et celui qui arrose sont un; mais chacun recevra sa propre récompense selon son propre travail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Car nous sommes collaborateurs de Dieu; vous êtes le labourage de Dieu, l’édifice de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Selon la grâce de Dieu qui m’a été donnée, comme un sage architecte, j’ai posé le fondement, et un autre édifie dessus; mais que chacun considère comment il édifie dessus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Car personne ne peut poser d’autre fondement que celui qui est posé, lequel est Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Or si quelqu’un édifie sur ce fondement de l’or, de l’argent, des pierres précieuses, du bois, du foin, du chaume,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'l’ouvrage de chacun sera rendu manifeste, car le jour le fera connaître, parce qu’il est révélé en feu; et quel est l’ouvrage de chacun, le feu l’éprouvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Si l’ouvrage de quelqu’un qu’il aura édifié dessus demeure, il recevra une récompense;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'si l’ouvrage de quelqu’un vient à être consumé, il en éprouvera une perte, mais lui-même il sera sauvé, toutefois comme à travers le feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Ne savez-vous pas que vous êtes le temple de Dieu et que l’Esprit de Dieu habite en vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Si quelqu’un corrompt le temple de Dieu, Dieu le détruira, car le temple de Dieu est saint, et tels vous êtes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Que personne ne s’abuse soi-même: si quelqu’un parmi vous a l’air d’être sage dans ce siècle, qu’il devienne fou, afin de devenir sage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'car la sagesse de ce monde est folie devant Dieu; car il est écrit: « Celui qui prend les sages dans leurs ruses »,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'et encore: « Le ✶Seigneur connaît les raisonnements des sages, qu’ils sont vains ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Que personne donc ne se glorifie dans les hommes, car toutes choses sont à vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'soit Paul, soit Apollos, soit Céphas, soit monde, soit vie, soit mort, soit choses présentes, soit choses à venir: toutes choses sont à vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'et vous à Christ, et Christ à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Que [tout] homme pense ainsi à notre égard, – [qu’il nous tienne] pour des serviteurs de Christ et pour des administrateurs des mystères de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Ici, au reste, ce qui est requis dans des administrateurs, c’est qu’un homme soit trouvé fidèle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Mais il m’importe fort peu, à moi, que je sois jugé par vous, ou de jugement d’homme; et même je ne me juge pas moi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Car je n’ai rien sur ma conscience; mais par là je ne suis pas justifié; mais celui qui me juge, c’est le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Ainsi ne jugez rien avant le temps, jusqu’à ce que le Seigneur vienne, qui aussi mettra en lumière les choses cachées des ténèbres, et qui manifestera les conseils des cœurs; et alors chacun recevra sa louange de la part de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Or, frères, j’ai tourné ceci sur moi et sur Apollos, à cause de vous, afin qu’en nous, vous appreniez à ne pas élever vos pensées au-dessus de ce qui est écrit, afin que vous ne vous enfliez pas pour l’un contre un autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Car qui est-ce qui met de la différence entre toi [et un autre]? Et qu’as-tu, que tu n’aies reçu? Et si aussi tu l’as reçu, pourquoi te glorifies-tu, comme si tu ne l’avais pas reçu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Déjà vous êtes rassasiés; déjà vous êtes riches; vous avez régné sans nous; et je voudrais bien que vous régniez, afin que nous aussi nous régnions avec vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Car je pense que Dieu nous a produits les derniers sur la scène, nous les apôtres, comme des gens voués à la mort; car nous avons été faits un spectacle pour le monde, et pour les anges et pour les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Nous, nous sommes fous pour l’amour de Christ, mais vous, vous êtes sages en Christ; nous sommes faibles, mais vous forts; vous en honneur, mais nous dans le mépris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Jusqu’à cette heure nous souffrons et la faim et la soif, et nous sommes nus, et nous sommes souffletés, et nous sommes sans demeure fixe,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'et nous prenons de la peine, travaillant de nos propres mains; injuriés, nous bénissons; persécutés, nous [le] supportons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'calomniés, nous supplions; nous sommes devenus comme les balayures du monde [et] le rebut de tous jusqu’à maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Ce n’est pas pour vous faire honte que j’écris ces choses, mais je vous avertis comme mes enfants bien-aimés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Car quand vous auriez 10 000 maîtres dans le Christ, vous n’avez cependant pas beaucoup de pères, car moi je vous ai engendrés dans le christ Jésus par l’évangile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Je vous supplie donc d’être mes imitateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'C’est pourquoi je vous ai envoyé Timothée, qui est mon enfant bien-aimé et qui est fidèle dans le Seigneur; il vous fera souvenir de mes voies en Christ, selon que j’enseigne partout dans chaque assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Or quelques-uns se sont enflés d’orgueil, comme si je ne devais pas aller vers vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'mais j’irai bientôt vers vous, si le Seigneur le veut, et je connaîtrai, non la parole de ceux qui se sont enflés, mais la puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Car le royaume de Dieu n’est pas en parole, mais en puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Que voulez-vous? Que j’aille vers vous avec la verge, ou avec amour et un esprit de douceur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'On entend dire partout qu’il y a de la fornication parmi vous, et une fornication telle qu’elle [n’existe] pas même parmi les nations, de sorte que quelqu’un aurait la femme de son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Et vous êtes enflés d’orgueil, et vous n’avez pas plutôt mené deuil, afin que celui qui a commis cette action soit ôté du milieu de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Car pour moi, étant absent de corps, mais présent en esprit, j’ai déjà, comme présent, jugé');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, '(vous et mon esprit étant assemblés, avec la puissance de notre seigneur Jésus Christ), [de livrer], au nom de notre seigneur Jésus Christ, celui qui a ainsi commis cette action,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, '[j’ai jugé, dis-je,] de livrer un tel homme à Satan pour la destruction de la chair, afin que l’esprit soit sauvé dans la journée du Seigneur Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Votre vanterie n’est pas bonne; ne savez-vous pas qu’un peu de levain fait lever la pâte tout entière?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Ôtez le vieux levain, afin que vous soyez une nouvelle pâte, comme vous êtes sans levain. Car aussi notre pâque, Christ, a été sacrifiée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'c’est pourquoi célébrons la fête, non avec du vieux levain, ni avec un levain de malice et de méchanceté, mais avec des pains sans levain de sincérité et de vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Je vous ai écrit dans la lettre, de ne pas avoir de commerce avec des fornicateurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'non pas absolument avec les fornicateurs de ce monde, ou les avares et les ravisseurs, ou les idolâtres, puisqu’ainsi il faudrait que vous sortiez du monde;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'mais, maintenant, je vous ai écrit que, si quelqu’un appelé frère est fornicateur, ou avare, ou idolâtre, ou outrageux, ou ivrogne, ou ravisseur, vous n’ayez pas de commerce avec lui, que vous ne mangiez pas même avec un tel homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Car qu’ai-je affaire de juger ceux de dehors aussi? Vous, ne jugez-vous pas ceux qui sont de dedans?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Mais ceux de dehors, Dieu les juge. Ôtez le méchant du milieu de vous-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Quelqu’un de vous, lorsqu’il a une affaire avec un autre, ose-t-il entrer en procès devant les injustes et non devant les saints?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Ne savez-vous pas que les saints jugeront le monde? Et si le monde est jugé par vous, êtes-vous indignes des plus petits jugements?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Ne savez-vous pas que nous jugerons les anges? et [nous ne jugerions] pas les affaires de cette vie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Si donc vous avez des procès pour les affaires de cette vie, établissez ceux-là [pour juges] qui sont peu estimés dans l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Je parle pour vous faire honte: ainsi il n’y a pas d’[homme] sage parmi vous, pas même un seul, qui soit capable de décider entre ses frères?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Mais un frère entre en procès avec un frère, et cela devant les incrédules.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'C’est donc de toute manière déjà une faute en vous, que vous ayez des procès entre vous. Pourquoi ne supportez-vous pas plutôt des injustices? pourquoi ne vous laissez-vous pas plutôt faire tort?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Mais vous, vous faites des injustices et vous faites tort, et cela à vos frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Ne savez-vous pas que les injustes n’hériteront point du royaume de Dieu? Ne vous y trompez pas: ni fornicateurs, ni idolâtres, ni adultères, ni efféminés, ni ceux qui abusent d’eux-mêmes avec des hommes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'ni voleurs, ni avares, ni ivrognes, ni outrageux, ni ravisseurs, n’hériteront du royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Et quelques-uns de vous, vous étiez tels; mais vous avez été lavés, mais vous avez été sanctifiés, mais vous avez été justifiés au nom du seigneur Jésus, et par l’Esprit de notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Toutes choses me sont permises, mais toutes choses ne sont pas avantageuses; toutes choses me sont permises, mais je ne me laisserai, moi, asservir par aucune.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Les viandes pour l’estomac, et l’estomac pour les viandes; mais Dieu mettra à néant et celui-ci et celles-là. Or le corps n’est pas pour la fornication, mais pour le Seigneur, et le Seigneur pour le corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Mais Dieu a ressuscité le Seigneur, et il nous ressuscitera par sa puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Ne savez-vous pas que vos corps sont des membres de Christ? Prendrai-je donc les membres du Christ pour en faire les membres d’une prostituée? Qu’ainsi n’advienne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Ne savez-vous pas que celui qui est uni à une prostituée est un seul corps [avec elle]? « Car les deux, dit-il, seront une seule chair »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'mais celui qui est uni au Seigneur est un seul esprit [avec lui].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fuyez la fornication: quelque péché que l’homme commette, il est hors du corps, mais le fornicateur pèche contre son propre corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Ne savez-vous pas que votre corps est le temple du Saint Esprit qui est en vous, et que vous avez de Dieu? Et vous n’êtes pas à vous-mêmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'car vous avez été achetés à prix. Glorifiez donc Dieu dans votre corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Or, pour ce qui est des choses au sujet desquelles vous m’avez écrit, il est bon à l’homme de ne pas toucher de femme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'mais, à cause de la fornication, que chacun ait sa propre femme, et que chaque femme ait son mari à elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Que le mari rende à la femme ce qui lui est dû, et pareillement aussi la femme au mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'La femme ne dispose pas de son propre corps, mais le mari; et pareillement aussi le mari ne dispose pas de son propre corps, mais la femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Ne vous privez pas l’un l’autre, à moins que ce ne soit d’un consentement mutuel, pour un temps, afin que vous vaquiez à la prière, et que vous vous trouviez de nouveau ensemble, afin que Satan ne vous tente pas à cause de votre incontinence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Or je dis ceci par indulgence, non comme commandement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'mais je voudrais que tous les hommes soient comme moi; toutefois chacun a son propre don de grâce de la part de Dieu, l’un d’une manière, et l’autre d’une autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Or je dis à ceux qui ne sont pas mariés et aux veuves, qu’il leur est bon de demeurer comme moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Mais s’ils ne savent pas garder la continence, qu’ils se marient, car il vaut mieux se marier que de brûler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Mais quant à ceux qui sont mariés, je leur enjoins, non pas moi, mais le Seigneur: que la femme ne soit pas séparée du mari;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, '(et si elle est séparée, qu’elle demeure sans être mariée, ou qu’elle se réconcilie avec son mari;) et que le mari n’abandonne pas sa femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Mais quant aux autres, je dis, moi, non pas le Seigneur: Si quelque frère a une femme incrédule, et qu’elle veuille habiter avec lui, qu’il ne l’abandonne pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'et si une femme a un mari incrédule, et qu’il veuille habiter avec elle, qu’elle n’abandonne pas [son] mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Car le mari incrédule est sanctifié par la femme, et la femme incrédule est sanctifiée par le frère, [son mari]; puisque autrement vos enfants seraient impurs; mais maintenant ils sont saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Mais si l’incrédule s’en va, qu’il s’en aille; le frère ou la sœur ne sont pas asservis en pareil cas; mais Dieu nous a appelés [à marcher] dans la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Car que sais-tu, femme, si tu ne sauveras pas ton mari? ou que sais-tu, mari, si tu ne sauveras pas ta femme?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Toutefois, que chacun marche comme le Seigneur le lui a départi, chacun comme Dieu l’a appelé; et c’est ainsi que j’en ordonne dans toutes les assemblées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Quelqu’un a-t-il été appelé étant circoncis, qu’il ne redevienne pas incirconcis. Quelqu’un a-t-il été appelé étant dans l’incirconcision, qu’il ne soit pas circoncis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'La circoncision n’est rien, et l’incirconcision n’est rien, mais l’observation des commandements de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Que chacun demeure dans la vocation dans laquelle [il était quand] il a été appelé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'As-tu été appelé étant esclave, ne t’en mets pas en peine; toutefois, si tu peux devenir libre, uses-en plutôt:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'car l’esclave qui est appelé dans le Seigneur est l’affranchi du Seigneur; de même aussi l’homme libre qui a été appelé est l’esclave de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Vous avez été achetés à prix; ne devenez pas esclaves des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Frères, que chacun demeure auprès de Dieu dans l’état dans lequel il a été appelé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Or, pour ce qui est de ceux qui sont vierges, je n’ai pas d’ordre du Seigneur; mais je donne mon opinion comme ayant reçu miséricorde du Seigneur pour être fidèle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'J’estime donc que ceci est bon, à cause de la nécessité présente, qu’il est bon, [dis-je], à l’homme d’être tel qu’il est.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Es-tu lié à une femme, ne cherche pas à en être séparé. N’es-tu pas lié à une femme, ne cherche pas de femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Toutefois, si même tu te maries, tu n’as pas péché; et si la vierge se marie, elle n’a pas péché. Mais ceux qui font ainsi auront de l’affliction pour ce qui regarde la chair; mais moi, je vous épargne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Or je dis ceci, frères: le temps est difficile: au reste, c’est pour que ceux mêmes qui ont une femme soient comme n’en ayant pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'et ceux qui pleurent, comme ne pleurant pas; et ceux qui se réjouissent, comme ne se réjouissant pas; et ceux qui achètent, comme ne possédant pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'et ceux qui usent du monde, comme n’en usant pas à leur gré; car la figure de ce monde passe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Mais je voudrais que vous soyez sans inquiétude. Celui qui n’est pas marié a le cœur occupé des choses du Seigneur, comment il plaira au Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'mais celui qui s’est marié a le cœur occupé des choses du monde, comment il plaira à sa femme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Il y a une différence entre la femme et la vierge: celle qui n’est pas mariée a le cœur occupé des choses du Seigneur, pour être sainte, et de corps et d’esprit; mais celle qui s’est mariée a le cœur occupé des choses du monde, comment elle plaira à son mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Mais je dis ceci pour votre propre avantage, non pour vous enlacer dans des liens, mais en vue de ce qui est bienséant, et pour que vous vaquiez au service du Seigneur sans distraction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Mais si quelqu’un estime qu’il agit d’une manière inconvenante à l’égard de sa virginité, et qu’elle ait passé la fleur de son âge, et qu’il faut que cela soit ainsi, qu’il fasse ce qu’il veut: il ne pèche pas; – qu’ils se marient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Mais celui qui tient ferme dans son cœur, et qui n’est pas sous l’empire de la nécessité, mais qui est maître de sa propre volonté et a décidé dans son cœur de garder sa propre virginité, fait bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Ainsi, et celui qui se marie fait bien; et celui qui ne se marie pas fait mieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'La femme est liée pendant tout le temps que son mari est en vie; mais si le mari s’est endormi, elle est libre de se marier à qui elle veut, seulement dans le Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'mais elle est, à mon avis, plus heureuse si elle demeure ainsi: or j’estime que moi aussi j’ai l’Esprit de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Pour ce qui est des choses sacrifiées aux idoles, nous savons – (car nous avons tous de la connaissance; la connaissance enfle, mais l’amour édifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Si quelqu’un pense savoir quelque chose, il ne connaît rien encore comme il faut connaître;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'mais si quelqu’un aime Dieu, celui-là est connu de lui).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, '– Pour ce qui est donc de manger des choses sacrifiées aux idoles, nous savons qu’une idole n’est rien dans le monde, et qu’il n’y a point d’autre Dieu qu’ un seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Car aussi, s’il y en a qui sont appelés dieux, soit dans le ciel, soit sur la terre, (comme il y a beaucoup de dieux et beaucoup de seigneurs,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'toutefois, pour nous, il y a un seul Dieu, le Père, duquel sont toutes choses, et nous pour lui, et un seul Seigneur, Jésus Christ, par lequel sont toutes choses, et nous par lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Toutefois la connaissance n’est pas en tous; mais quelques-uns, ayant jusqu’à maintenant conscience de l’idole, mangent des choses comme sacrifiées aux idoles, et leur conscience, étant faible, en est souillée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Or la viande ne nous recommande pas à Dieu; si nous ne mangeons pas, nous n’avons pas moins, et si nous mangeons, nous n’avons rien de plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Mais prenez garde que cette liberté que vous avez ne devienne une pierre d’achoppement pour les faibles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Car si quelqu’un te voit, toi qui as de la connaissance, assis à table dans un temple d’idoles, sa conscience à lui qui est faible, ne sera-t-elle pas enhardie à manger les choses sacrifiées à l’idole?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'et celui qui est faible, le frère pour lequel Christ est mort, périra par ta connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Or en péchant ainsi contre les frères, et en blessant leur conscience qui est faible, vous péchez contre Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'C’est pourquoi, si la viande est une occasion de chute pour mon frère, je ne mangerai pas de chair, à jamais, pour ne pas être une occasion de chute pour mon frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Ne suis-je pas libre? Ne suis-je pas apôtre? N’ai-je pas vu Jésus notre Seigneur? N’êtes-vous pas, vous, mon ouvrage dans le Seigneur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Si je ne suis pas apôtre pour d’autres, je le suis pour vous du moins; car vous êtes le sceau de mon apostolat dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'C’est ici ma défense auprès de ceux qui m’interrogent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'N’avons-nous pas le droit de manger et de boire?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'N’avons-nous pas le droit de mener avec nous une sœur comme femme, comme [font] aussi les autres apôtres, et les frères du Seigneur, et Céphas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'N’y a-t-il que moi et Barnabas qui n’ayons pas le droit de ne pas travailler?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Qui jamais va à la guerre à ses propres dépens? Qui plante une vigne et n’en mange pas le fruit? Ou qui paît un troupeau et ne mange pas du lait du troupeau?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Est-ce que je dis ces choses selon l’homme? Ou la loi aussi ne dit-elle pas ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Car dans la loi de Moïse il est écrit: « Tu n’emmuselleras pas le bœuf qui foule le grain ». Dieu s’occupe-t-il des bœufs?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'ou parle-t-il entièrement pour nous? Car c’est pour nous que cela est écrit, que celui qui laboure doit labourer avec espérance, et que celui qui foule le grain [doit le fouler] dans l’espérance d’y avoir part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Si nous avons semé pour vous des [biens] spirituels, est-ce beaucoup que nous moissonnions de vos [biens] charnels?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Si d’autres ont part à ce droit sur vous, ne l’avons-nous pas bien plus? Mais nous n’avons pas usé de ce droit, mais nous supportons tout, afin de ne mettre aucun obstacle à l’évangile du Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Ne savez-vous pas que ceux qui s’emploient aux choses sacrées mangent [de ce qui vient] du temple; que ceux qui servent à l’autel ont leur part de l’autel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'De même aussi, le Seigneur a ordonné à ceux qui annoncent l’évangile, de vivre de l’évangile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Mais moi je n’ai usé d’aucune de ces choses, et je n’ai pas écrit ceci, afin qu’il en soit fait ainsi à mon égard; car il serait bon pour moi de mourir, plutôt que [de voir] quelqu’un anéantir ma gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Car, si j’évangélise, je n’ai pas de quoi me glorifier, car c’est une nécessité qui m’est imposée, car malheur à moi si je n’évangélise pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Car, si je fais cela volontairement, j’en ai un salaire; mais si c’est malgré moi, une administration m’est confiée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Quel est donc mon salaire? C’est que, en évangélisant, je rends l’évangile exempt de frais, pour ne pas user comme d’une chose à moi de mon droit dans l’évangile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Car, étant libre à l’égard de tous, je me suis asservi à tous, afin de gagner le plus de gens;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'et pour les Juifs, je suis devenu comme Juif, afin de gagner les Juifs; pour ceux qui étaient sous la loi, comme si j’étais sous la loi, n’étant pas moi-même sous la loi, afin de gagner ceux qui étaient sous la loi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'pour ceux qui étaient sans loi, comme si j’étais sans loi (non que je sois sans loi quant à Dieu, mais je suis justement soumis à Christ), afin de gagner ceux qui étaient sans loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Je suis devenu pour les faibles [comme] faible, afin de gagner les faibles; je suis devenu toutes choses pour tous, afin que de toute manière j’en sauve quelques-uns.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Et je fais toutes choses à cause de l’évangile, afin que je sois coparticipant avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Ne savez-vous pas que ceux qui courent dans la lice courent tous, mais un seul reçoit le prix? Courez de telle manière que vous le remportiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Or quiconque combat dans l’arène vit de régime en toutes choses; eux donc, afin de recevoir une couronne corruptible; mais nous, [afin d’en recevoir] une incorruptible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Moi donc je cours ainsi, non comme ne sachant pas vers quel but; je combats ainsi, non comme battant l’air;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'mais je mortifie mon corps et je l’asservis, de peur qu’après avoir prêché à d’autres, je ne sois moi-même réprouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Car je ne veux pas que vous ignoriez, frères, que nos pères ont tous été sous la nuée, et que tous ils ont passé à travers la mer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'et que tous ils ont été baptisés pour Moïse dans la nuée et dans la mer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'et que tous ils ont mangé la même viande spirituelle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'et que tous ils ont bu le même breuvage spirituel, car ils buvaient d’un rocher spirituel qui les suivait: et le rocher était le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Mais Dieu n’a point pris plaisir en la plupart d’entre eux, car ils tombèrent dans le désert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Or ces choses arrivèrent comme types de ce qui nous concerne, afin que nous ne convoitions pas des choses mauvaises, comme ceux-là aussi ont convoité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Ne soyez pas non plus idolâtres, comme quelques-uns d’eux, ainsi qu’il est écrit: « Le peuple s’assit pour manger et pour boire, et ils se levèrent pour jouer ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Ne commettons pas non plus la fornication, comme quelques-uns d’eux ont commis la fornication, et il en est tombé en un seul jour 23 000.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Ne tentons pas non plus le Christ, comme quelques-uns d’eux l’ont tenté et ont péri par les serpents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Ne murmurez pas non plus, comme quelques-uns d’eux ont murmuré et ont péri par le destructeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Or toutes ces choses leur arrivèrent comme types, et elles ont été écrites pour nous servir d’avertissement, à nous que les fins des siècles ont atteints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Ainsi, que celui qui croit être debout prenne garde qu’il ne tombe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Aucune tentation ne vous est survenue qui n’ait été une tentation humaine; et Dieu est fidèle, qui ne permettra pas que vous soyez tentés au-delà de ce que vous pouvez [supporter], mais avec la tentation il fera aussi l’issue, afin que vous puissiez la supporter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'C’est pourquoi, mes bien-aimés, fuyez l’idolâtrie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Je parle comme à des personnes intelligentes: jugez vous-mêmes de ce que je dis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'La coupe de bénédiction que nous bénissons, n’est-elle pas la communion du sang du Christ? Le pain que nous rompons, n’est-il pas la communion du corps du Christ?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Car nous qui sommes plusieurs, sommes un seul pain, un seul corps, car nous participons tous à un seul et même pain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Considérez l’Israël selon la chair: ceux qui mangent les sacrifices n’ont-ils pas communion avec l’autel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Que dis-je donc? que ce qui est sacrifié à une idole soit quelque chose? ou qu’une idole soit quelque chose?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, '[Non], mais que les choses que les nations sacrifient, elles les sacrifient à des démons et non pas à Dieu: or je ne veux pas que vous ayez communion avec les démons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Vous ne pouvez boire la coupe du Seigneur et la coupe des démons; vous ne pouvez participer à la table du Seigneur et à la table des démons.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Provoquons-nous le Seigneur à la jalousie? Sommes-nous plus forts que lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Toutes choses sont permises, mais toutes choses ne sont pas avantageuses; toutes choses sont permises, mais toutes choses n’édifient pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Que personne ne cherche son propre intérêt, mais celui d’autrui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Mangez de tout ce qui se vend à la boucherie, sans vous enquérir de rien à cause de la conscience:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, '« car la terre est au ✶Seigneur, et tout ce qu’elle contient ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Or si quelqu’un des incrédules vous convie, et que vous vouliez aller, mangez de tout ce qui est mis devant vous, sans vous enquérir de rien à cause de la conscience.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Mais si quelqu’un vous dit: Ceci a été offert en sacrifice, – n’en mangez pas, à cause de celui qui vous a avertis, et à cause de la conscience.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Or je dis: la conscience, non la tienne, mais celle de l’autre; car pourquoi ma liberté est-elle jugée par la conscience d’autrui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Si moi, je participe avec action de grâces, pourquoi suis-je blâmé pour une chose dont moi je rends grâces?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Soit donc que vous mangiez, soit que vous buviez, ou quoi que vous fassiez, faites tout pour la gloire de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Ne devenez une cause d’achoppement ni aux Juifs, ni aux Grecs, ni à l’assemblée de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'comme moi aussi je complais à tous en toutes choses, ne cherchant pas mon avantage propre, mais celui du grand nombre, afin qu’ils soient sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Soyez mes imitateurs, comme moi aussi je le suis de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Or je vous loue de ce que vous vous souvenez de moi en toutes choses, et de ce que vous gardez les enseignements, comme je vous les ai donnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Mais je veux que vous sachiez que le chef de tout homme, c’est le Christ, et que le chef de la femme, c’est l’homme, et que le chef du Christ, c’est Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Tout homme qui prie ou qui prophétise en ayant [quelque chose] sur la tête, déshonore sa tête;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'et toute femme qui prie ou qui prophétise, la tête découverte, déshonore sa tête, car c’est la même chose qu’une femme qui serait rasée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Car si la femme n’est pas couverte, qu’on lui coupe aussi les cheveux. Mais s’il est déshonnête pour une femme d’avoir les cheveux coupés ou d’être rasée, qu’elle soit couverte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Car l’homme, étant l’image et la gloire de Dieu, ne doit pas se couvrir la tête; mais la femme est la gloire de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Car l’homme ne procède pas de la femme, mais la femme de l’homme;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'car aussi l’homme n’a pas été créé à cause de la femme, mais la femme à cause de l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'C’est pourquoi la femme, à cause des anges, doit avoir sur la tête [une marque de l’]autorité [à laquelle elle est soumise].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Toutefois, ni la femme n’est sans l’homme, ni l’homme sans la femme, dans le Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'car comme la femme procède de l’homme, ainsi aussi l’homme est par la femme; mais toutes choses procèdent de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Jugez-en en vous-mêmes: est-il convenable qu’une femme prie Dieu sans être couverte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'La nature même ne vous enseigne-t-elle pas que, si un homme a une longue chevelure, c’est un déshonneur pour lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Mais si une femme a une longue chevelure, c’est une gloire pour elle, parce que la chevelure lui est donnée en guise de voile.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Mais si quelqu’un paraît vouloir contester, nous, nous n’avons pas une telle coutume, ni les assemblées de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Or, en prescrivant ceci, je ne [vous] loue pas, – c’est que vous vous réunissez, non pas pour votre profit, mais à votre détriment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Car d’abord, quand vous vous réunissez en assemblée, j’entends dire qu’il y a des divisions parmi vous, et je le crois en partie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'car il faut aussi qu’il y ait des sectes parmi vous, afin que ceux qui sont approuvés soient manifestes parmi vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Quand donc vous vous réunissez ensemble, ce n’est pas manger la cène dominicale:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'car lorsqu’on mange, chacun prend par avance son propre souper, et l’un a faim, et l’autre s’enivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'N’avez-vous donc pas des maisons pour manger et pour boire? Ou méprisez-vous l’assemblée de Dieu, et faites-vous honte à ceux qui n’ont rien? Que vous dirai-je? Vous louerai-je? En cela, je ne vous loue pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Car moi, j’ai reçu du Seigneur ce qu’aussi je vous ai enseigné: c’est que le seigneur Jésus, la nuit qu’il fut livré, prit du pain,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'et après avoir rendu grâces, il le rompit et dit: « Ceci est mon corps, qui est pour vous; faites ceci en mémoire de moi. »');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'De même [il prit] la coupe aussi, après le souper, en disant: « Cette coupe est la nouvelle alliance en mon sang: faites ceci, toutes les fois que vous la boirez, en mémoire de moi. »');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Car toutes les fois que vous mangez ce pain et que vous buvez la coupe, vous annoncez la mort du Seigneur jusqu’à ce qu’il vienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Ainsi quiconque mange le pain ou boit la coupe du Seigneur indignement sera coupable à l’égard du corps et du sang du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Mais que chacun s’éprouve soi-même, et qu’ainsi il mange du pain et boive de la coupe;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'car celui qui mange et qui boit, mange et boit un jugement contre lui-même, ne distinguant pas le corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'C’est pour cela que plusieurs sont faibles et malades parmi vous, et qu’un assez grand nombre dorment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Mais si nous nous jugions nous-mêmes, nous ne serions pas jugés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Mais quand nous sommes jugés, nous sommes châtiés par le Seigneur, afin que nous ne soyons pas condamnés avec le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Ainsi, mes frères, quand vous vous réunissez pour manger, attendez-vous l’un l’autre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'si quelqu’un a faim, qu’il mange chez lui, afin que vous ne vous réunissiez pas pour être jugés. Or, quant aux autres points, je les réglerai quand j’irai [vers vous].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Or, pour ce qui est des [manifestations] spirituelles, frères, je ne veux pas que vous soyez ignorants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Vous savez que, quand vous étiez [gens des] nations, [vous étiez] entraînés vers les idoles muettes, selon que vous étiez menés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'C’est pourquoi je vous fais savoir que nul homme parlant par l’Esprit de Dieu, ne dit: “Anathème [à] Jésus”; et que nul ne peut dire “Seigneur Jésus”, si ce n’est par l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Or il y a diversité de dons de grâce, mais le même Esprit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'et il y a diversité de services, et le même Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'et il y a diversité d’opérations, mais le même Dieu qui opère tout en tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Or à chacun est donnée la manifestation de l’Esprit en vue de l’utilité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Car à l’un est donnée, par l’Esprit, la parole de sagesse; et à un autre la parole de connaissance, selon le même Esprit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'et à un autre la foi, par le même Esprit; et à un autre des dons de grâce de guérisons, par le même Esprit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'et à un autre des opérations de miracles; et à un autre la prophétie; et à un autre des discernements d’esprits; et à un autre [diverses] sortes de langues; et à un autre l’interprétation des langues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Mais le seul et même Esprit opère toutes ces choses, distribuant à chacun en particulier comme il lui plaît.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Car de même que le corps est un et qu’il a plusieurs membres, mais que tous les membres du corps, quoiqu’ils soient plusieurs, sont un seul corps, ainsi aussi est le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Car aussi nous avons tous été baptisés d’un seul Esprit pour être un seul corps, soit Juifs, soit Grecs, soit esclaves, soit hommes libres; et nous avons tous été abreuvés pour [l’unité d’]un seul Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Car aussi le corps n’est pas un seul membre, mais plusieurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Si le pied disait: Parce que je ne suis pas main, je ne suis pas du corps, est-ce qu’à cause de cela il n’est pas du corps?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Et si l’oreille disait: Parce que je ne suis pas œil, je ne suis pas du corps, est-ce qu’à cause de cela elle n’est pas du corps?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Si le corps tout entier était œil, où serait l’ouïe? Si tout était ouïe, où serait l’odorat?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Mais maintenant, Dieu a placé les membres, – chacun d’eux, – dans le corps, comme il l’a voulu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Or, si tous étaient un seul membre, où serait le corps?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Mais maintenant les membres sont plusieurs, mais le corps, un.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'L’œil ne peut pas dire à la main: Je n’ai pas besoin de toi; ou bien encore la tête, aux pieds: Je n’ai pas besoin de vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, '– mais bien plutôt les membres du corps qui paraissent être les plus faibles, sont nécessaires;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'et les membres du corps que nous estimons être les moins honorables, nous les environnons d’un honneur plus grand; et nos membres qui ne sont pas décents sont les plus parés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'tandis que nos membres décents n’en ont pas besoin. Mais Dieu a composé le corps en donnant un plus grand honneur à ce qui en manquait,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'afin qu’il n’y ait point de division dans le corps, mais que les membres aient un égal soin les uns des autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Et si un membre souffre, tous les membres souffrent avec lui; si un membre est glorifié, tous les membres se réjouissent avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Or vous êtes le corps de Christ, et [ses] membres chacun en particulier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Et Dieu a placé les uns dans l’assemblée: – d’abord des apôtres, en second lieu des prophètes, en troisième lieu des docteurs, ensuite des miracles, puis des dons de grâce de guérisons, des aides, des gouvernements, [diverses] sortes de langues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Tous sont-ils apôtres? Tous sont-ils prophètes? Tous sont-ils docteurs? Tous [font-ils] des miracles?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Tous ont-ils des dons de grâce de guérisons? Tous parlent-ils en langues? Tous interprètent-ils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Or désirez avec ardeur les dons de grâce plus grands: et je vous montre encore un chemin bien plus excellent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Si je parle dans les langues des hommes et des anges, mais que je n’aie pas l’amour, je suis comme un airain qui résonne ou comme une cymbale retentissante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Et si j’ai la prophétie, et que je connaisse tous les mystères et toute connaissance, et que j’aie toute la foi de manière à transporter des montagnes, mais que je n’aie pas l’amour, je ne suis rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Et quand je distribuerais en aliments tous mes biens, et que je livrerais mon corps afin que je sois brûlé, mais que je n’aie pas l’amour, cela ne me profite de rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'L’amour use de longanimité; il est plein de bonté; l’amour n’est pas envieux; l’amour ne se vante pas; il ne s’enfle pas d’orgueil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'il n’agit pas avec inconvenance; il ne cherche pas son propre intérêt; il ne s’irrite pas; il n’impute pas le mal;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'il ne se réjouit pas de l’injustice, mais se réjouit avec la vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'il supporte tout, croit tout, espère tout, endure tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'L’amour ne périt jamais. Or y a-t-il des prophéties? elles auront leur fin. Y a-t-il des langues? elles cesseront. Y a-t-il de la connaissance? elle aura sa fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Car nous connaissons en partie, et nous prophétisons en partie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'mais quand ce qui est parfait sera venu, ce qui est en partie aura sa fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Quand j’étais enfant, je parlais comme un enfant, je pensais comme un enfant, je raisonnais comme un enfant; quand je suis devenu homme, j’en ai fini avec ce qui était de l’enfant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Car nous voyons maintenant au travers d’un verre, obscurément, mais alors face à face; maintenant je connais en partie, mais alors je connaîtrai à fond comme aussi j’ai été connu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Or maintenant ces trois choses demeurent: la foi, l’espérance, l’amour; mais la plus grande de ces choses, c’est l’amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Poursuivez l’amour, et désirez avec ardeur les [dons] spirituels, mais surtout de prophétiser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Parce que celui qui parle en langue ne parle pas aux hommes, mais à Dieu, car personne ne l’entend; mais en esprit il prononce des mystères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Mais celui qui prophétise parle aux hommes pour l’édification, et l’exhortation, et la consolation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Celui qui parle en langue s’édifie lui-même; mais celui qui prophétise édifie l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Or je désire que tous vous parliez en langues, mais surtout que vous prophétisiez; mais celui qui prophétise est plus grand que celui qui parle en langues, à moins qu’il n’interprète, afin que l’assemblée reçoive de l’édification.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Et maintenant, frères, si je viens à vous et que je parle en langues, en quoi vous profiterai-je, à moins que je ne vous parle par révélation, ou par connaissance, ou par prophétie, ou par doctrine?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'De même les choses inanimées qui rendent un son, soit une flûte, soit une harpe, si elles ne rendent pas des sons distincts, comment connaîtra-t-on ce qui est joué sur la flûte ou sur la harpe?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Car aussi, si la trompette rend un son confus, qui se préparera pour le combat?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'De même aussi vous, avec une langue, si vous ne prononcez pas un discours intelligible, comment saura-t-on ce qui est dit, car vous parlerez en l’air?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Il y a je ne sais combien de genres de voix dans le monde, et aucune d’elles n’est sans son distinct.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Si donc je ne connais pas le sens de la voix, je serai barbare pour celui qui parle, et celui qui parle sera barbare pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Ainsi vous aussi, puisque vous désirez avec ardeur des dons de l’Esprit, cherchez à en être abondamment doués pour l’édification de l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'C’est pourquoi, que celui qui parle en langue prie pour qu’il interprète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Car si je prie en langue, mon esprit prie, mais mon intelligence est sans fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Qu’est-ce donc? Je prierai avec l’esprit, mais je prierai aussi avec l’intelligence; je chanterai avec l’esprit, mais je chanterai aussi avec l’intelligence.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Autrement, si tu as béni avec l’esprit, comment celui qui occupe la place d’un homme simple dira-t-il l’amen à ton action de grâces, puisqu’il ne sait ce que tu dis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Car toi, il est vrai, tu rends bien grâces; mais l’autre n’est pas édifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Je rends grâces à Dieu de ce que je parle en langue plus que vous tous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'mais, dans l’assemblée, j’aime mieux prononcer cinq paroles avec mon intelligence, afin que j’instruise aussi les autres, que 10 000 paroles en langue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Frères, ne soyez pas des enfants dans vos entendements, mais, pour la malice, soyez de petits enfants; mais, dans vos entendements, soyez des hommes faits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Il est écrit dans la loi: « C’est en d’autres langues et par des lèvres étrangères que je parlerai à ce peuple; et même ainsi, ils ne m’écouteront pas, dit le ✶Seigneur ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'De sorte que les langues sont pour signe, non à ceux qui croient, mais aux incrédules; mais la prophétie [est un signe], non aux incrédules, mais à ceux qui croient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Si donc l’assemblée tout entière se réunit ensemble, et que tous parlent en langues, et qu’il entre des hommes simples ou des incrédules, ne diront-ils pas que vous êtes fous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Mais si tous prophétisent, et qu’il entre quelque incrédule ou quelque homme simple, il est convaincu par tous, [et] il est jugé par tous:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'les secrets de son cœur sont rendus manifestes; et ainsi, tombant sur sa face, il rendra hommage à Dieu, publiant que Dieu est véritablement parmi vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Qu’est-ce donc, frères? Quand vous vous réunissez, chacun de vous a un psaume, a un enseignement, a une langue, a une révélation, a une interprétation: que tout se fasse pour l’édification.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Et si quelqu’un parle en langue, que ce soient deux, ou tout au plus trois, [qui parlent], et chacun à son tour, et que [quelqu’]un interprète;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'mais s’il n’y a pas d’interprète, qu’il se taise dans l’assemblée, et qu’il parle à soi-même et à Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'et que les prophètes parlent, deux ou trois, et que les autres jugent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'et s’il y a eu une révélation faite à un autre qui est assis, que le premier se taise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Car vous pouvez tous prophétiser un à un, afin que tous apprennent et que tous soient exhortés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Et les esprits des prophètes sont assujettis aux prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Car Dieu n’est pas [un Dieu] de désordre, mais de paix, comme dans toutes les assemblées des saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Que vos femmes se taisent dans les assemblées, car il ne leur est pas permis de parler; mais qu’elles soient soumises, comme le dit aussi la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Et si elles veulent apprendre quelque chose, qu’elles interrogent leurs propres maris chez elles, car il est honteux pour une femme de parler dans l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'La parole de Dieu est-elle procédée de vous, ou est-elle parvenue à vous seuls?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Si quelqu’un pense être prophète ou spirituel, qu’il reconnaisse que les choses que je vous écris sont le commandement du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Et si quelqu’un est ignorant, qu’il soit ignorant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Ainsi, frères, désirez avec ardeur de prophétiser, et n’empêchez pas de parler en langues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Mais que toutes choses se fassent avec bienséance et avec ordre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Or je vous fais savoir, frères, l’évangile que je vous ai annoncé, que vous avez aussi reçu, et dans lequel vous êtes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'par lequel aussi vous êtes sauvés, si vous tenez ferme la parole que je vous ai annoncée, à moins que vous n’ayez cru en vain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Car je vous ai communiqué avant toutes choses ce que j’ai aussi reçu, que Christ est mort pour nos péchés, selon les écritures,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'et qu’il a été enseveli, et qu’il a été ressuscité le troisième jour, selon les écritures;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'et qu’il a été vu de Céphas, puis des douze.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Ensuite il a été vu de plus de 500 frères à la fois, dont la plupart sont demeurés [en vie] jusqu’à présent, mais quelques-uns aussi se sont endormis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Ensuite il a été vu de Jacques, puis de tous les apôtres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'et, après tous, comme d’un avorton, il a été vu aussi de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Car je suis le moindre des apôtres, moi qui ne suis pas digne d’être appelé apôtre, parce que j’ai persécuté l’assemblée de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Mais par la grâce de Dieu, je suis ce que je suis; et sa grâce envers moi n’a pas été vaine, mais j’ai travaillé beaucoup plus qu’eux tous, non pas moi toutefois, mais la grâce de Dieu qui est avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Soit donc moi, soit eux, nous prêchons ainsi, et vous avez cru ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Or si Christ est prêché, – qu’il a été ressuscité d’entre les morts, comment disent quelques-uns parmi vous qu’il n’y a pas de résurrection de morts?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Mais s’il n’y a pas de résurrection de morts, Christ n’a pas été ressuscité non plus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'et si Christ n’a pas été ressuscité, notre prédication donc est vaine aussi, et votre foi aussi est vaine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'et même nous sommes trouvés de faux témoins de Dieu, car nous avons rendu témoignage à l’égard de Dieu qu’il a ressuscité Christ, lequel il n’a pas ressuscité si réellement les morts ne ressuscitent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Car si les morts ne ressuscitent pas, Christ n’a pas été ressuscité non plus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'et si Christ n’a pas été ressuscité, votre foi est vaine, vous êtes encore dans vos péchés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'ceux donc aussi qui se sont endormis en Christ ont péri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Si, pour cette vie seulement, nous avons espérance en Christ, nous sommes plus misérables que tous les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, '(Mais maintenant Christ a été ressuscité d’entre les morts, prémices de ceux qui sont endormis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Car puisque la mort est par l’homme, c’est par l’homme aussi qu’est la résurrection des morts;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'car, comme dans l’Adam tous meurent, de même aussi dans le Christ tous seront rendus vivants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'mais chacun dans son propre rang: les prémices, Christ; puis ceux qui sont du Christ, à sa venue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'ensuite la fin, quand il aura remis le royaume à Dieu le Père, quand il aura aboli toute principauté, et toute autorité, et [toute] puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Car il faut qu’il règne jusqu’à ce qu’il ait mis tous les ennemis sous ses pieds:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'le dernier ennemi qui sera aboli, c’est la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Car « il a assujetti toutes choses sous ses pieds ». Or, quand il dit que toutes choses sont assujetties, il est évident que c’est à l’exclusion de celui qui lui a assujetti toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Mais quand toutes choses lui auront été assujetties, alors le Fils aussi lui-même sera assujetti à celui qui lui a assujetti toutes choses, afin que Dieu soit tout en tous.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Autrement, que feront ceux qui sont baptisés pour les morts, si les morts ne ressuscitent absolument pas? Pourquoi aussi sont-ils baptisés pour eux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Pourquoi aussi nous, bravons-nous le péril à toute heure?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Par votre confiance que j’ai dans le christ Jésus notre Seigneur, je meurs chaque jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Si, [pour parler] à la manière des hommes, j’ai combattu contre les bêtes à Éphèse, quel profit en ai-je si les morts ne ressuscitent pas? « Mangeons et buvons, car demain nous mourrons ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Ne soyez pas séduits: les mauvaises compagnies corrompent les bonnes mœurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Réveillez-vous [pour vivre] justement, et ne péchez pas; car quelques-uns sont dans l’ignorance de Dieu, je vous le dis à votre honte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Mais quelqu’un dira: Comment ressuscitent les morts, et avec quel corps viennent-ils?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Insensé! ce que tu sèmes n’est pas vivifié s’il ne meurt;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'et quant à ce que tu sèmes, tu ne sèmes pas le corps qui sera, mais le simple grain, de blé, comme il se rencontre, ou de quelqu’une des autres semences;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'mais Dieu lui donne un corps comme il a voulu, et à chacune des semences son propre corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Toute chair n’est pas la même chair; mais autre est celle des hommes, autre la chair des bêtes, autre celle des oiseaux, autre celle des poissons:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'et il y a des corps célestes et des corps terrestres; mais différente est la gloire des célestes, et différente celle des terrestres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'autre la gloire du soleil, et autre la gloire de la lune, et autre la gloire des étoiles, car une étoile diffère d’une [autre] étoile en gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Ainsi aussi est la résurrection des morts: il est semé en corruption, il ressuscite en incorruptibilité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'il est semé en déshonneur, il ressuscite en gloire; il est semé en faiblesse, il ressuscite en puissance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'il est semé corps animal, il ressuscite corps spirituel. S’il y a un corps animal, il y en a aussi un spirituel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'c’est ainsi aussi qu’il est écrit: « Le premier homme Adam devint une âme vivante », le dernier Adam, un esprit vivifiant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Mais ce qui est spirituel n’est pas le premier, mais ce qui est animal; ensuite ce qui est spirituel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Le premier homme est [tiré] de la terre, – poussière; le second homme est [venu] du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Tel qu’est celui qui est poussière, tels aussi sont ceux qui sont poussière; et tel qu’est le céleste, tels aussi sont les célestes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Et comme nous avons porté l’image de celui qui est poussière, nous porterons aussi l’image du céleste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Or je dis ceci, frères, que la chair et le sang ne peuvent pas hériter du royaume de Dieu, et que la corruption non plus n’hérite pas de l’incorruptibilité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Voici, je vous dis un mystère: Nous ne nous endormirons pas tous, mais nous serons tous changés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'en un instant, en un clin d’œil, à la dernière trompette, car la trompette sonnera et les morts seront ressuscités incorruptibles, et nous, nous serons changés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Car il faut que ce corruptible revête l’incorruptibilité, et que ce mortel revête l’immortalité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Or quand ce corruptible aura revêtu l’incorruptibilité, et que ce mortel aura revêtu l’immortalité, alors s’accomplira la parole qui est écrite: « La mort a été engloutie en victoire ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, '« Où est, ô mort, ton aiguillon? où est, ô mort, ta victoire? ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Or l’aiguillon de la mort, c’est le péché; et la puissance du péché, c’est la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Mais grâces à Dieu, qui nous donne la victoire par notre seigneur Jésus Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Ainsi, mes frères bien-aimés, soyez fermes, inébranlables, abondant toujours dans l’œuvre du Seigneur, sachant que votre travail n’est pas vain dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Or pour ce qui est de la collecte qui [se fait] pour les saints, comme j’en ai ordonné aux assemblées de Galatie, ainsi faites, vous aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Que chaque premier jour de la semaine chacun de vous mette à part chez lui, accumulant selon qu’ il aura prospéré, afin que, lorsque je serai arrivé, il ne se fasse pas alors de collectes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Et quand je serai là, ceux que vous approuverez, je les enverrai avec des lettres, pour porter votre libéralité à Jérusalem.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Et s’il convient que j’y aille moi-même, ils iront avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Or je me rendrai auprès de vous quand j’aurai traversé la Macédoine, car je traverse la Macédoine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'et peut-être séjournerai-je auprès de vous, ou même y passerai-je l’hiver, afin que vous me fassiez la conduite où que ce soit que j’aille;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'car je ne veux pas vous voir maintenant en passant, car j’espère que je demeurerai avec vous quelque temps, si le Seigneur le permet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Mais je demeurerai à Éphèse jusqu’à la Pentecôte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'car une porte grande et efficace m’est ouverte, et il y a beaucoup d’adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Or, si Timothée vient, ayez soin qu’il soit sans crainte au milieu de vous, car il s’emploie à l’œuvre du Seigneur comme moi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Que personne donc ne le méprise; mais faites-lui la conduite en paix, afin qu’il vienne vers moi, car je l’attends avec les frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Or, pour ce qui est du frère Apollos, je l’ai beaucoup prié d’aller auprès de vous avec les frères, mais ce n’a pas été du tout sa volonté d’y aller maintenant; mais il ira quand il trouvera l’occasion favorable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Veillez, tenez ferme dans la foi; soyez hommes, affermissez-vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Que toutes choses parmi vous se fassent dans l’amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Or je vous exhorte, frères – (vous connaissez la maison de Stéphanas, qu’elle est les prémices de l’Achaïe, et qu’ils se sont voués au service des saints,) –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'à vous soumettre, vous aussi, à de tels hommes et à quiconque coopère à l’œuvre et travaille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Or je me réjouis de la venue de Stéphanas, et de Fortunat, et d’Achaïque, parce qu’ils ont suppléé à ce qui a manqué de votre part;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'car ils ont récréé mon esprit et le vôtre: reconnaissez donc de tels hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Les assemblées de l’Asie vous saluent. Aquilas et Priscilla, avec l’assemblée qui [se réunit] dans leur maison, vous saluent affectueusement dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Tous les frères vous saluent. Saluez-vous les uns les autres par un saint baiser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'La salutation, de la propre main de moi, Paul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, '– Si quelqu’un n’aime pas le seigneur [Jésus Christ], qu’il soit anathème, Maranatha!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Que la grâce du Seigneur Jésus Christ soit avec vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Mon amour est avec vous tous dans le christ Jésus. Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paul, apôtre de Jésus Christ par la volonté de Dieu, et Timothée, le frère, à l’assemblée de Dieu qui est à Corinthe, avec tous les saints qui sont dans l’Achaïe tout entière:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Grâce et paix à vous, de la part de Dieu notre Père et du seigneur Jésus Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Béni soit le Dieu et Père de notre seigneur Jésus Christ, le Père des miséricordes et le Dieu de toute consolation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'qui nous console à l’égard de toute notre affliction, afin que nous soyons capables de consoler ceux qui sont dans quelque affliction que ce soit, par la consolation dont nous sommes nous-mêmes consolés de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Car comme les souffrances du Christ abondent à notre égard, ainsi, par le Christ, notre consolation aussi abonde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Et soit que nous soyons affligés, c’est pour votre consolation et votre salut, qui est opéré en ce que vous endurez les mêmes souffrances que nous aussi nous souffrons');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, '(et notre espérance à votre égard est ferme); soit que nous soyons consolés, c’est pour votre consolation et votre salut; sachant que, comme vous avez part aux souffrances, de même aussi vous avez part à la consolation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Car nous ne voulons pas, frères, que vous ignoriez, quant à notre affliction qui [nous] est arrivée en Asie, que nous avons été excessivement chargés, au-delà de notre force, de sorte que nous avons désespéré même de vivre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Mais nous-mêmes nous avions en nous-mêmes la sentence de mort, afin que nous n’ayons pas confiance en nous-mêmes, mais en Dieu qui ressuscite les morts,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'qui nous a délivrés d’une si grande mort, et qui nous délivre; en qui nous espérons qu’il nous délivrera aussi encore,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'vous aussi coopérant par vos supplications pour nous, afin que, pour le don de grâce qui nous est [accordé] par le moyen de plusieurs personnes, des actions de grâces soient rendues pour nous par plusieurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Car notre gloire est celle-ci, [savoir] le témoignage de notre conscience, qu’avec simplicité et sincérité de Dieu, non pas avec une sagesse charnelle, mais par la grâce de Dieu, nous nous sommes conduits dans le monde et plus encore envers vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Car nous ne vous écrivons pas autre chose que ce que vous savez, et que vous reconnaissez, et que vous reconnaîtrez, je l’espère, jusqu’à la fin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'comme aussi vous nous avez reconnus en partie, que nous sommes votre sujet de gloire, comme vous êtes aussi le nôtre dans la journée du seigneur Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Et dans cette confiance j’avais voulu aller auprès de vous d’abord, afin que vous ayez une seconde grâce,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'et par chez vous passer en Macédoine, et de Macédoine de nouveau aller auprès de vous; et puis que vous me fassiez la conduite vers la Judée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'En me proposant donc cela, est-ce que j’aurais usé de légèreté? Ou les choses que je me propose, me les proposé-je selon la chair, en sorte qu’il y ait en moi le oui, oui, et le non, non?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Mais Dieu est fidèle, que notre parole que nous vous avons adressée, n’est pas oui et non.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Car le Fils de Dieu, Jésus Christ, qui a été prêché par nous au milieu de vous, [savoir] par moi et par Silvain et par Timothée, n’a pas été oui et non, mais il y a oui en lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'car autant il y a de promesses de Dieu, en lui est le oui et en lui l’amen, à la gloire de Dieu par nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Or celui qui nous lie fermement avec vous à Christ et qui nous a oints, c’est Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'qui aussi nous a scellés, et nous a donné les arrhes de l’Esprit dans nos cœurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Or, moi, j’appelle Dieu à témoin sur mon âme, que ç’a été pour vous épargner que je ne suis pas encore allé à Corinthe,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'non que nous dominions sur votre foi, mais nous coopérons à votre joie: car c’est par la foi que vous êtes debout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Mais j’ai jugé ceci en moi-même, de ne pas retourner auprès de vous avec de la tristesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Car si moi je vous attriste, qui est-ce donc qui me réjouit, sinon celui qui est attristé par moi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Et j’ai écrit ceci même, afin que, quand j’arriverai, je n’aie pas de tristesse de la part de ceux de qui je devais me réjouir, ayant cette confiance à l’égard de vous tous, que ma joie est celle de vous tous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'car je vous ai écrit dans une grande affliction et avec serrement de cœur, avec beaucoup de larmes, non afin que vous soyez attristés, mais afin que vous connaissiez l’amour que j’ai si abondamment pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Mais si quelqu’un a causé de la tristesse, ce n’est pas moi qu’il a attristé, mais, en quelque sorte (afin que je ne vous surcharge pas), c’est vous tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Il suffit, pour un tel homme, de cette punition [qui lui a été infligée] par le grand nombre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'de sorte qu’au contraire vous devriez plutôt pardonner et consoler, de peur qu’un tel homme ne soit accablé par une tristesse excessive.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'C’est pourquoi je vous exhorte à ratifier envers lui votre amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Car c’est aussi pour cela que je vous ai écrit, afin que je connaisse, à l’épreuve, si vous êtes obéissants en toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Or à celui à qui vous pardonnez quelque chose, moi aussi [je pardonne]; car moi aussi, ce que j’ai pardonné, si j’ai pardonné quelque chose, [je l’ai fait] à cause de vous dans la personne de Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'afin que nous ne soyons pas circonvenus par Satan, car nous n’ignorons pas ses desseins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Or, étant arrivé dans la Troade pour l’évangile du Christ, et une porte m’y étant ouverte dans le Seigneur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'je n’ai point eu de repos dans mon esprit, parce que je n’ai pas trouvé Tite, mon frère; mais, ayant pris congé d’eux, je suis parti pour la Macédoine.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Or grâces à Dieu qui nous mène toujours en triomphe dans le Christ et manifeste par nous l’odeur de sa connaissance en tout lieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Car nous sommes la bonne odeur de Christ pour Dieu, à l’égard de ceux qui sont sauvés et à l’égard de ceux qui périssent:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'aux uns une odeur de mort pour la mort, et aux autres une odeur de vie pour la vie. Et qui est suffisant pour ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Car nous ne sommes pas comme plusieurs, qui frelatent la parole de Dieu; mais comme avec sincérité, comme de la part de Dieu, devant Dieu, nous parlons en Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Commençons-nous de nouveau à nous recommander nous-mêmes? Ou avons-nous besoin, comme quelques-uns, de lettres de recommandation pour vous ou de lettres de recommandation de votre part?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Vous êtes, vous, notre lettre, écrite dans nos cœurs, connue et lue de tous les hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'car vous êtes manifestés comme étant la lettre de Christ, dressée par notre ministère, écrite non avec de l’encre, mais par l’Esprit du Dieu vivant, non sur des tables de pierre, mais sur les tables de chair du cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Or nous avons une telle confiance par le Christ envers Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'non que nous soyons capables par nous-mêmes de penser quelque chose comme de nous-mêmes, mais notre capacité vient de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'qui nous a rendus propres aussi pour être des ministres de la nouvelle alliance, non de la lettre, mais de l’esprit, car la lettre tue, mais l’Esprit vivifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, '(Or si le ministère de la mort, gravé en lettres sur des pierres, a été introduit avec gloire, de sorte que les fils d’Israël ne pouvaient arrêter leurs yeux sur la face de Moïse, à cause de la gloire de sa face, laquelle devait prendre fin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'combien plus le ministère de l’Esprit ne subsistera-t-il pas en gloire!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Car si le ministère de la condamnation a été gloire, combien plus le ministère de la justice abonde-t-il en gloire!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Car aussi ce qui a été glorifié n’a pas été glorifié sous ce rapport, à cause de la gloire qui l’emporte de beaucoup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Car si ce qui devait prendre fin [a été introduit] avec gloire, bien plus ce qui demeure [subsistera-t-il] en gloire!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Ayant donc une telle espérance, nous usons d’une grande liberté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'et [nous ne faisons] pas comme Moïse qui mettait un voile sur sa face, pour que les fils d’Israël n’arrêtent pas leurs yeux sur la consommation de ce qui devait prendre fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Mais leurs entendements ont été endurcis, car jusqu’à aujourd’hui, dans la lecture de l’ancienne alliance, ce même voile demeure sans être levé, lequel prend fin en Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Mais jusqu’à aujourd’hui, lorsque Moïse est lu, le voile demeure sur leur cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'mais quand il se tournera vers le Seigneur, le voile sera ôté.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Or le Seigneur est l’esprit; mais là où est l’Esprit du Seigneur, il y a la liberté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Or nous tous, contemplant à face découverte la gloire du Seigneur, nous sommes transformés en la même image, de gloire en gloire, comme par le Seigneur en Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'C’est pourquoi, ayant ce ministère comme ayant obtenu miséricorde, nous ne nous lassons point,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'mais nous avons entièrement renoncé aux choses honteuses qui se font en secret, ne marchant point avec ruse et ne falsifiant point la parole de Dieu, mais, par la manifestation de la vérité, nous recommandant nous-mêmes à toute conscience d’homme devant Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'et si aussi notre évangile est voilé, il est voilé en ceux qui périssent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'en lesquels le dieu de ce siècle a aveuglé les pensées des incrédules, pour que la lumière de l’évangile de la gloire du Christ qui est l’image de Dieu, ne resplendisse pas [pour eux].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Car nous ne nous prêchons pas nous-mêmes, mais [nous prêchons] le christ Jésus comme Seigneur, et nous-mêmes comme vos esclaves pour l’amour de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Car c’est le Dieu qui a dit que du sein des ténèbres la lumière resplendisse, qui a relui dans nos cœurs pour faire luire la connaissance de la gloire de Dieu dans la face de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Mais nous avons ce trésor dans des vases de terre, afin que l’excellence de la puissance soit de Dieu et non pas de nous:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'étant dans la tribulation de toute manière, mais non pas réduits à l’étroit; dans la perplexité, mais non pas sans ressource;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'persécutés, mais non pas abandonnés; abattus, mais ne périssant pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'portant toujours partout dans le corps la mort de Jésus, afin que la vie aussi de Jésus soit manifestée dans notre corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Car nous qui vivons, nous sommes toujours livrés à la mort pour l’amour de Jésus, afin que la vie aussi de Jésus soit manifestée dans notre chair mortelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Ainsi donc la mort opère en nous, mais la vie en vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Or, ayant le même esprit de foi, selon ce qui est écrit: « J’ai cru, c’est pourquoi j’ai parlé », nous aussi nous croyons, c’est pourquoi aussi nous parlons:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'sachant que celui qui a ressuscité le seigneur Jésus, nous ressuscitera aussi avec Jésus, et nous présentera avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Car toutes choses sont pour vous, afin que la grâce, abondant par le moyen de plusieurs, multiplie les actions de grâces à la gloire de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'C’est pourquoi nous ne nous lassons point; mais si même notre homme extérieur dépérit, toutefois l’homme intérieur est renouvelé de jour en jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Car notre légère tribulation d’un moment, opère pour nous, en mesure surabondante, un poids éternel de gloire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'nos regards n’étant pas fixés sur les choses qui se voient, mais sur celles qui ne se voient pas: car les choses qui se voient sont pour un temps, mais celles qui ne se voient pas sont éternelles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Car nous savons que, si notre maison terrestre qui n’est qu’une tente, est détruite, nous avons un édifice de la part de Dieu, une maison qui n’est pas faite de main, éternelle, dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Car aussi, dans cette tente, nous gémissons, désirant avec ardeur d’avoir revêtu notre domicile qui est du ciel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'si toutefois, même en étant vêtus, nous ne sommes pas trouvés nus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Car aussi nous qui sommes dans la tente, nous gémissons, étant chargés; non pas que nous désirions d’être dépouillés, mais [nous désirons] d’être revêtus, afin que ce qui est mortel soit absorbé par la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Or celui qui nous a formés à cela même, c’est Dieu, qui nous a aussi donné les arrhes de l’Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Nous avons donc toujours confiance, et nous savons qu’étant présents dans le corps, nous sommes absents du Seigneur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'car nous marchons par la foi, non par la vue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'nous avons, dis-je, de la confiance, et nous aimons mieux être absents du corps et être présents avec le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'C’est pourquoi aussi, que nous soyons présents ou que nous soyons absents, nous nous appliquons avec ardeur à lui être agréables;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'car il faut que nous soyons tous manifestés devant le tribunal du Christ, afin que chacun reçoive les choses [accomplies] dans le corps, selon ce qu’il aura fait, soit bien, soit mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Connaissant donc combien le Seigneur doit être craint, nous persuadons les hommes, mais nous avons été manifestés à Dieu, et j’espère aussi que nous avons été manifestés dans vos consciences.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Nous ne nous recommandons pas de nouveau à vous, mais nous vous donnons occasion de vous glorifier de nous, afin que vous ayez [de quoi répondre] à ceux qui se glorifient extérieurement et non pas du cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Car si nous sommes hors de nous-mêmes, c’est pour Dieu; si nous sommes de sens rassis, c’est pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Car l’amour du Christ nous étreint, en ce que nous avons jugé ceci, que si un est mort pour tous, tous donc sont morts,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'et qu’il est mort pour tous, afin que ceux qui vivent ne vivent plus pour eux-mêmes, mais pour celui qui pour eux est mort et a été ressuscité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'En sorte que nous, désormais, nous ne connaissons personne selon la chair; et, si même nous avons connu Christ selon la chair, toutefois maintenant nous ne le connaissons plus [ainsi].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'En sorte que si quelqu’un est en Christ, c’est une nouvelle création: les choses vieilles sont passées; voici, toutes choses sont faites nouvelles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'et toutes sont du Dieu qui nous a réconciliés avec lui-même par Christ, et qui nous a donné le service de la réconciliation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'savoir, que Dieu était en Christ, réconciliant le monde avec lui-même, ne leur imputant pas leurs fautes et mettant en nous la parole de la réconciliation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Nous sommes donc ambassadeurs pour Christ, – Dieu, pour ainsi dire, exhortant par notre moyen; nous supplions pour Christ: Soyez réconciliés avec Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Celui qui n’a pas connu le péché, il l’a fait péché pour nous, afin que nous devenions justice de Dieu en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Or, travaillant à cette même œuvre, nous aussi, nous exhortons à ce que vous n’ayez pas reçu la grâce de Dieu en vain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '(car il dit: « Au temps agréé je t’ai exaucé, et en un jour de salut je t’ai secouru ». Voici, c’est maintenant le temps agréable; voici, c’est maintenant le jour du salut)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, '– ne donnant aucun scandale en rien, afin que le service ne soit pas blâmé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'mais en toutes choses nous recommandant comme serviteurs de Dieu, par une grande patience, dans les tribulations, dans les nécessités, dans les détresses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'sous les coups, dans les prisons, dans les troubles, dans les travaux, dans les veilles, dans les jeûnes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'par la pureté, par la connaissance, par la longanimité, par la bonté, par l’Esprit Saint, par un amour sans hypocrisie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'par la parole de la vérité, par la puissance de Dieu, par les armes de justice de la main droite et de la main gauche,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'dans la gloire et dans l’ignominie, dans la mauvaise et dans la bonne renommée; comme séducteurs, et véritables;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'comme inconnus, et bien connus; comme mourants, et voici, nous vivons; comme châtiés, et non mis à mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'comme attristés, mais toujours joyeux; comme pauvres, mais enrichissant plusieurs; comme n’ayant rien, et possédant toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Notre bouche est ouverte pour vous, ô Corinthiens! notre cœur s’est élargi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'vous n’êtes pas à l’étroit en nous, mais vous êtes à l’étroit dans vos entrailles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'et, en juste récompense, (je [vous] parle comme à mes enfants,) élargissez-vous, vous aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ne vous mettez pas sous un joug mal assorti avec les incrédules; car quelle participation y a-t-il entre la justice et l’iniquité? ou quelle communion entre la lumière et les ténèbres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'et quel accord de Christ avec Béliar? ou quelle part a le croyant avec l’incrédule?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'et quelle convenance y a-t-il entre le temple de Dieu et les idoles? Car vous êtes le temple du Dieu vivant, selon ce que Dieu a dit: « J’habiterai au milieu d’eux, et j’y marcherai, et je serai leur Dieu, et eux seront mon peuple ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, '« C’est pourquoi sortez du milieu d’eux, et soyez séparés, dit le ✶Seigneur, et ne touchez pas à ce qui est impur, et moi, je vous recevrai »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, '« et je vous serai pour père, et vous, vous me serez pour fils et pour filles, dit le ✶Seigneur, [le] Tout-puissant. »');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Ayant donc ces promesses, bien-aimés, purifions-nous nous-mêmes de toute souillure de chair et d’esprit, achevant la sainteté dans la crainte de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Recevez-nous: nous n’avons fait tort à personne, nous n’avons ruiné personne, nous ne nous sommes enrichis aux dépens de personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Je ne dis pas ceci pour [vous] condamner, car j’ai déjà dit que vous êtes dans nos cœurs à mourir ensemble et à vivre ensemble.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Ma franchise est grande envers vous, je me glorifie grandement de vous; je suis rempli de consolation; ma joie surabonde au milieu de toute notre affliction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Car aussi, lorsque nous sommes arrivés en Macédoine, notre chair n’a eu aucun repos, mais nous avons été affligés en toute manière: au-dehors, des combats; au-dedans, des craintes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Mais celui qui console ceux qui sont abaissés, Dieu, nous a consolés par la venue de Tite,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'et non seulement par sa venue, mais aussi par la consolation dont il a été rempli à votre sujet, en nous racontant votre grand désir, vos larmes, votre affection ardente envers moi, de sorte que je me suis d’autant plus réjoui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Car si aussi je vous ai attristés par ma lettre, je n’en ai pas de regret, si même j’en ai eu du regret (car je vois que cette lettre vous a attristés, lors même que [ce n’a été que] pour un temps).');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Maintenant je me réjouis, non de ce que vous avez été attristés, mais de ce que vous avez été attristés à repentance; car vous avez été attristés selon Dieu, afin qu’en rien vous ne receviez de préjudice de notre part.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Car la tristesse qui est selon Dieu opère une repentance à salut dont on n’a pas de regret, mais la tristesse du monde opère la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Car voici, ce [fait] même que vous avez été attristés selon Dieu, quel empressement il a produit en vous, mais quelles excuses, mais quelle indignation, mais quelle crainte, mais quel ardent désir, mais quel zèle, mais quelle vengeance: À tous égards, vous avez montré que vous êtes purs dans l’affaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Ainsi, si même je vous ai écrit, ce n’a point été à cause de celui qui a fait le tort ni à cause de celui à qui on a fait tort, mais afin que le zèle que nous avons pour vous, vous soit manifesté devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'C’est pourquoi nous avons été consolés. Et nous nous sommes réjouis d’autant plus abondamment, dans notre consolation, de la joie de Tite, parce que son esprit a été récréé par vous tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Parce que, si en quelque chose je me suis glorifié de vous auprès de lui, je n’en ai pas été confus; mais comme nous vous avons dit toutes choses selon la vérité, ainsi aussi ce dont nous nous étions glorifiés auprès de Tite s’est trouvé vrai,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'et son affection se porte plus abondamment sur vous, quand il se souvient de l’obéissance de vous tous, comment vous l’avez reçu avec crainte et tremblement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Je me réjouis de ce qu’en toutes choses j’ai de la confiance à votre égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Or nous vous faisons connaître, frères, la grâce de Dieu donnée [aux saints] dans les assemblées de la Macédoine:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'c’est que, dans une grande épreuve de tribulation, l’abondance de leur joie et leur profonde pauvreté ont abondé dans la richesse de leur libéralité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Car selon leur pouvoir (j’en rends témoignage), et au-delà de leur pouvoir, [ils ont agi] spontanément,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'nous demandant avec de grandes instances la grâce et la communion de ce service envers les saints;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'et non [seulement] comme nous l’avions espéré, mais ils se sont donnés premièrement eux-mêmes au Seigneur, et puis à nous, par la volonté de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'de sorte que nous avons exhorté Tite, afin que, comme il l’avait auparavant commencée, ainsi aussi il achève à votre égard cette grâce aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Mais comme vous abondez en toutes choses: en foi, et en parole, et en connaissance, et en toute diligence, et dans votre amour envers nous, – que vous abondiez aussi dans cette grâce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Je ne parle pas comme [donnant un] commandement, mais à cause de la diligence d’autres personnes, et pour mettre à l’épreuve la sincérité de votre amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Car vous connaissez la grâce de notre seigneur Jésus Christ, comment, étant riche, il a vécu dans la pauvreté pour vous, afin que par sa pauvreté vous soyez enrichis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Et en cela je [vous] donne un avis, car cela vous est profitable, à vous qui avez déjà commencé dès l’année passée, non seulement de faire, mais aussi de vouloir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Or maintenant, achevez aussi de faire, de sorte que, comme vous avez été prompts à vouloir, ainsi aussi [vous soyez prompts] à achever en prenant sur ce que vous avez;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'car si la promptitude à donner existe, elle est agréable selon ce qu’on a, non selon ce qu’on n’a pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'car ce n’est pas afin que d’autres soient à leur aise et que vous, vous soyez opprimés, mais sur un principe d’égalité:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'que dans le temps présent votre abondance [supplée] à leurs besoins, afin qu’aussi leur abondance supplée à vos besoins, de sorte qu’il y ait égalité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'selon qu’il est écrit: « Celui qui [recueillait] beaucoup n’avait pas plus, et celui qui [recueillait] peu n’avait pas moins ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Or grâces à Dieu qui met le même zèle pour vous dans le cœur de Tite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'car il a reçu l’exhortation; mais, étant très zélé, il est allé spontanément auprès de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Et nous avons envoyé avec lui le frère dont la louange dans l’évangile est répandue dans toutes les assemblées');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, '(et non seulement [cela], mais aussi il a été choisi par les assemblées pour notre compagnon de voyage, avec cette grâce qui est administrée par nous à la gloire du Seigneur lui-même, et [pour montrer] notre empressement);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'évitant que personne ne nous blâme dans cette abondance qui est administrée par nous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'car nous veillons à ce qui est honnête, non seulement devant le Seigneur, mais aussi devant les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Et nous avons envoyé avec eux notre frère, du zèle duquel, en plusieurs choses, nous avons souvent fait l’épreuve, et qui maintenant est beaucoup plus zélé à cause de la grande confiance qu’il a en vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Quant à Tite, il est mon associé et mon compagnon d’œuvre auprès de vous; quant à nos frères, ils sont les envoyés des assemblées, la gloire de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Montrez donc envers eux, devant les assemblées, la preuve de votre amour et du sujet que nous avons eu de nous glorifier de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Car pour ce qui est du service envers les saints, il est superflu que je vous en écrive;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'car je connais votre promptitude, au sujet de laquelle je me glorifie de vous auprès des Macédoniens, [leur disant] que l’Achaïe est prête dès l’année passée; et le zèle de chez vous a excité la généralité [des frères];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'mais j’ai envoyé les frères, afin que ce en quoi nous nous sommes glorifiés de vous ne soit pas mis à néant à cet égard, afin que, comme je l’ai dit, vous soyez prêts,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'de peur que si des Macédoniens venaient avec moi et ne vous trouvaient pas prêts, nous (pour ne pas dire vous), nous ne soyons confus de cette assurance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'J’ai donc estimé nécessaire de prier les frères d’aller au préalable vers vous, et de compléter d’avance votre libéralité, annoncée d’avance, afin qu’elle soit ainsi prête comme une libéralité et non comme une chose extorquée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Or [je dis] ceci: Celui qui sème chichement moissonnera aussi chichement, et celui qui sème libéralement moissonnera aussi libéralement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Que chacun [fasse] selon qu’il se l’est proposé dans son cœur, non à regret, ou par contrainte, car Dieu aime celui qui donne joyeusement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Mais Dieu est puissant pour faire abonder toute grâce envers vous, afin qu’ayant toujours en toutes choses tout ce qui suffit, vous abondiez pour toute bonne œuvre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'selon qu’il est écrit: « Il a répandu, il a donné aux pauvres, sa justice demeure éternellement ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Or celui qui fournit de la semence au semeur et du pain à manger, fournira et multipliera votre semence, et augmentera les fruits de votre justice,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'étant de toute manière enrichis pour une entière libéralité, qui produit par nous des actions de grâces à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Parce que l’administration de cette charge, non seulement comble les besoins des saints, mais aussi abonde par beaucoup d’actions de grâces [rendues] à Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'puisque, par l’expérience qu’ils font de ce service, ils glorifient Dieu pour la soumission dont vous faites profession à l’égard de l’évangile du Christ, et pour la libéralité de vos dons envers eux et envers tous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'et par les supplications qu’ils font pour vous, étant animés d’une ardente affection envers vous, à cause de la surabondante grâce de Dieu [qui repose] sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Grâces à Dieu pour son don inexprimable!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Or moi-même, Paul, je vous exhorte par la douceur et la débonnaireté du Christ, moi qui, présent, quant à l’apparence suis chétif au milieu de vous, mais qui, absent, use de hardiesse envers vous...;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'mais je vous supplie que, lorsque je serai présent, je n’use pas de hardiesse avec cette assurance avec laquelle je pense que je prendrai sur moi d’agir envers quelques-uns qui pensent que nous marchons selon la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Car, en marchant dans la chair, nous ne combattons pas selon la chair;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'car les armes de notre guerre ne sont pas charnelles, mais puissantes par Dieu pour la destruction des forteresses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'détruisant les raisonnements et toute hauteur qui s’élève contre la connaissance de Dieu, et amenant toute pensée captive à l’obéissance du Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'et étant prêts à tirer vengeance de toute désobéissance, après que votre obéissance aura été rendue complète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Considérez-vous les choses selon l’apparence? Si quelqu’un a la confiance en lui-même d’être à Christ, qu’il pense encore ceci en lui-même, que, comme lui-même est à Christ, ainsi nous aussi [nous sommes à Christ].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Car si même je me glorifiais un peu plus de notre autorité que le Seigneur nous a donnée pour l’édification et non pas pour votre destruction, je ne serais pas confus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, '– afin que je ne paraisse pas comme si je vous effrayais par mes lettres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Car ses lettres, dit-on, sont graves et fortes, mais sa présence personnelle est faible et sa parole méprisable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Qu’un tel homme estime que, tels que nous sommes en parole par nos lettres, étant absents, tels aussi nous sommes de fait, étant présents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Car nous n’osons pas nous ranger parmi quelques-uns qui se recommandent eux-mêmes, ou nous comparer à eux; mais eux, se mesurant eux-mêmes par eux-mêmes, et se comparant eux-mêmes à eux-mêmes, ne sont pas intelligents;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'mais nous, nous ne nous glorifierons pas dans ce qui est au-delà de notre mesure, mais selon la mesure de la règle que le Dieu de mesure nous a départie pour parvenir aussi jusqu’à vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Car nous ne nous étendons pas nous-mêmes plus qu’il ne faut, comme si nous ne parvenions pas jusqu’à vous, (car nous sommes arrivés même jusqu’à vous dans [la prédication de] l’évangile du Christ,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'ne nous glorifiant pas dans ce qui est au-delà de notre mesure, dans les travaux d’autrui, mais ayant espérance, votre foi s’accroissant, d’être abondamment agrandis au milieu de vous, selon notre règle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'pour évangéliser dans les lieux qui sont au-delà de vous, non pas pour nous glorifier dans la règle d’autrui, des choses déjà toutes préparées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Mais que celui qui se glorifie, se glorifie dans le Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'car ce n’est pas celui qui se recommande lui-même qui est approuvé, mais celui que le Seigneur recommande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Je voudrais que vous supportiez un peu ma folie! Mais aussi supportez-moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Car je suis jaloux à votre égard d’une jalousie de Dieu; car je vous ai fiancés à un seul mari, pour vous présenter au Christ comme une vierge chaste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Mais je crains que, en quelque manière, comme le serpent séduisit Ève par sa ruse, ainsi vos pensées ne soient corrompues [et détournées] de la simplicité quant au Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Car si celui qui vient prêche un autre Jésus que nous n’avons pas prêché, ou que vous receviez un esprit différent que vous n’avez pas reçu, ou un évangile différent que vous n’avez pas reçu, vous pourriez bien [le] supporter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Car j’estime que je n’ai été en rien moindre que les plus excellents apôtres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Et si même je suis un homme simple quant au langage, je ne le suis pourtant pas quant à la connaissance; mais nous avons été manifestés de toute manière, en toutes choses, envers vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Ai-je commis une faute en m’abaissant moi-même, afin que vous soyez élevés, parce que je vous ai annoncé gratuitement l’évangile de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'J’ai dépouillé d’autres assemblées en recevant un salaire pour vous servir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Et me trouvant auprès de vous et dans le besoin, je n’ai été à charge à personne; (car les frères venus de Macédoine ont suppléé à mes besoins;) et je me suis gardé de vous être à charge en quoi que ce soit, et je m’en garderai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Comme la vérité de Christ est en moi, cette gloire ne me sera pas interdite dans les contrées de l’Achaïe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Pourquoi? Est-ce parce que je ne vous aime pas? Dieu le sait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Mais ce que je fais, je le ferai encore, pour retrancher l’occasion à ceux qui veulent une occasion, afin qu’en ce de quoi ils se glorifient, ils soient trouvés aussi tels que nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Car de tels hommes sont de faux apôtres, des ouvriers trompeurs, se transformant en apôtres de Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'et ce n’est pas étonnant, car Satan lui-même se transforme en ange de lumière:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'ce n’est donc pas chose étrange si ses ministres aussi se transforment en ministres de justice, desquels la fin sera selon leurs œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Je le dis encore: que personne ne me tienne pour un insensé; ou bien, s’il en est autrement, recevez-moi, même comme un insensé, afin que moi aussi je me glorifie un peu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Ce que je dis, je ne le dis pas selon le Seigneur, mais comme un insensé, dans cette assurance [dont j’use] en me glorifiant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Puisque plusieurs se glorifient selon la chair, moi aussi je me glorifierai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Car vous supportez volontiers les insensés, étant sages vous-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Car si quelqu’un vous asservit, si quelqu’un vous dévore, si quelqu’un prend votre bien, si quelqu’un s’élève, si quelqu’un vous frappe au visage, vous le supportez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Je le dis pour ce qui regarde le déshonneur, comme si nous, nous avions été faibles; mais dans ce en quoi quelqu’un pourrait être osé (je parle en insensé), moi aussi je suis osé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Sont-ils Hébreux? – moi aussi. Sont-ils Israélites? – moi aussi. Sont-ils la semence d’Abraham? – moi aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Sont-ils ministres de Christ? (je parle comme un homme hors de sens,) – moi outre mesure; dans les travaux surabondamment, sous les coups excessivement, dans les prisons surabondamment, dans les morts souvent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, '(cinq fois j’ai reçu des Juifs 40 [coups] moins un;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'trois fois j’ai été battu de verges; une fois j’ai été lapidé; trois fois j’ai fait naufrage; j’ai passé un jour et une nuit dans les profondeurs de la mer);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'en voyages souvent, dans les périls sur les fleuves, dans les périls de la part des brigands, dans les périls de la part de mes compatriotes, dans les périls de la part des nations, dans les périls à la ville, dans les périls au désert, dans les périls en mer, dans les périls parmi de faux frères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'en peine et en labeur, en veilles souvent, dans la faim et la soif, dans les jeûnes souvent, dans le froid et la nudité:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'outre ces choses exceptionnelles, il y a ce qui me tient assiégé tous les jours, la sollicitude pour toutes les assemblées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Qui est faible, que je ne sois faible aussi? Qui est scandalisé, que moi aussi je ne brûle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'S’il faut se glorifier, je me glorifierai dans ce qui est de mon infirmité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Le Dieu et Père du seigneur Jésus (lui qui est béni éternellement), sait que je ne mens point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'À Damas, l’ethnarque du roi Arétas faisait garder la ville des Damascéniens, voulant se saisir de moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'et je fus dévalé dans une corbeille par une fenêtre à travers la muraille, et j’échappai à ses mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Il est vrai qu’il est sans profit pour moi de me glorifier, car j’en viendrai à des visions et à des révélations du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Je connais un homme en Christ, qui, il y a 14 ans (si ce fut dans le corps, je ne sais; si ce fut hors du corps, je ne sais; Dieu le sait), [je connais] un tel homme qui a été ravi jusqu’au troisième ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Et je connais un tel homme, (si ce fut dans le corps, si ce fut hors du corps, je ne sais, Dieu le sait,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, '– qu’il a été ravi dans le paradis, et a entendu des paroles ineffables qu’il n’est pas permis à l’homme d’exprimer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Je me glorifierai d’un tel homme, mais je ne me glorifierai pas de moi-même, si ce n’est dans mes infirmités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Car quand je voudrais me glorifier, je ne serais pas insensé, car je dirais la vérité; mais je m’en abstiens, de peur que quelqu’un ne m’estime au-dessus de ce qu’il me voit être ou de ce qu’il a pu entendre dire de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Et afin que je ne m’enorgueillisse pas à cause de l’extraordinaire des révélations, il m’a été donné une écharde pour la chair, un ange de Satan pour me souffleter, afin que je ne m’enorgueillisse pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'À ce sujet j’ai supplié trois fois le Seigneur, afin qu’elle se retire de moi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'et il m’a dit: Ma grâce te suffit, car ma puissance s’accomplit dans l’infirmité. Je me glorifierai donc très volontiers plutôt dans mes infirmités, afin que la puissance du Christ demeure sur moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'C’est pourquoi je prends plaisir dans les infirmités, dans les outrages, dans les nécessités, dans les persécutions, dans les détresses pour Christ: car quand je suis faible, alors je suis fort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Je suis devenu insensé: vous m’y avez contraint; car moi, j’aurais dû être recommandé par vous; car je n’ai été en rien moindre que les plus excellents apôtres, quoique je ne sois rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Certainement les signes d’un apôtre ont été opérés au milieu de vous avec toute patience, [par] des signes, et des prodiges, et des miracles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Car en quoi avez-vous été inférieurs aux autres assemblées, sinon en ce que moi-même je ne vous ai pas été à charge? Pardonnez-moi ce tort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Voici, cette troisième fois, je suis prêt à aller auprès de vous; et je ne vous serai pas à charge, car je ne cherche pas vos biens, mais vous-mêmes; car ce ne sont pas les enfants qui doivent amasser pour leurs parents, mais les parents pour leurs enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Or moi, très volontiers je dépenserai et je serai entièrement dépensé pour vos âmes, si même, vous aimant beaucoup plus, je devais être moins aimé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Mais soit! moi, je ne vous ai pas été à charge, mais, étant rusé, je vous ai pris par finesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Me suis-je enrichi à vos dépens par aucun de ceux que je vous ai envoyés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'J’ai prié Tite et j’ai envoyé le frère avec lui. Tite s’est-il enrichi à vos dépens? N’avons-nous pas marché dans le même esprit? N’avons-nous pas marché sur les mêmes traces?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Vous avez longtemps pensé que nous nous justifions auprès de vous. Nous parlons devant Dieu en Christ, et toutes choses, bien-aimés, pour votre édification.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Car je crains que, quand j’arriverai, je ne vous trouve pas tels que je voudrais, et que moi je ne sois trouvé par vous tel que vous ne voudriez pas, [et] qu’il n’y ait des querelles, des jalousies, des colères, des intrigues, des médisances, des insinuations, des enflures d’orgueil, des désordres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'et qu’étant de nouveau revenu [au milieu de vous], mon Dieu ne m’humilie quant à vous, et que je ne sois affligé à l’occasion de plusieurs de ceux qui ont péché auparavant et qui ne se sont pas repentis de l’impureté et de la fornication et de l’impudicité qu’ils ont commises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'C’est ici la troisième fois que je viens à vous: par la bouche de deux ou de trois témoins toute affaire sera établie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'J’ai déjà dit, et je dis à l’avance, comme si j’étais présent pour la seconde fois, et maintenant étant absent, à ceux qui ont péché auparavant et à tous les autres, que si je viens encore une fois, je n’épargnerai pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Puisque vous cherchez une preuve que Christ parle en moi (lequel n’est pas faible envers vous, mais puissant au milieu de vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'car même s’il a été crucifié en infirmité, néanmoins il vit par la puissance de Dieu; car aussi nous, nous sommes faibles en lui, mais nous vivrons avec lui, par la puissance de Dieu envers vous),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'examinez-vous vous-mêmes, [et voyez] si vous êtes dans la foi; éprouvez-vous vous-mêmes. Ne reconnaissez-vous pas à l’égard de vous-mêmes que Jésus Christ est en vous? à moins que vous ne soyez des réprouvés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'mais j’espère que vous connaîtrez que nous, nous ne sommes pas des réprouvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Mais nous prions Dieu que vous ne fassiez aucun mal, non afin que nous, nous paraissions approuvés, mais afin que vous, vous fassiez ce qui est bon, et que nous, nous soyons comme des réprouvés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'car nous ne pouvons rien contre la vérité, mais pour la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Car nous nous réjouissons lorsque nous, nous sommes faibles, et que vous, vous êtes puissants: et nous demandons ceci aussi, votre perfectionnement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'C’est pourquoi j’écris ces choses étant absent, afin que, quand je serai présent, je n’use pas de sévérité, selon l’autorité que le Seigneur m’a donnée pour l’édification et non pas pour la destruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Au reste, frères, réjouissez-vous; perfectionnez-vous; soyez consolés; ayez un même sentiment; vivez en paix: et le Dieu d’amour et de paix sera avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Saluez-vous les uns les autres par un saint baiser. Tous les saints vous saluent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Que la grâce du seigneur Jésus Christ, et l’amour de Dieu, et la communion du Saint Esprit, soient avec vous tous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paul, apôtre, non de la part des hommes, ni par l’homme, mais par Jésus Christ, et Dieu le Père qui l’a ressuscité d’entre les morts,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'et tous les frères qui sont avec moi, aux assemblées de la Galatie:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Grâce et paix à vous, de la part de Dieu le Père et de notre seigneur Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'qui s’est donné lui-même pour nos péchés, en sorte qu’il nous retire du présent siècle mauvais, selon la volonté de notre Dieu et Père,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'auquel soit la gloire aux siècles des siècles! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Je m’étonne de ce que vous passez si promptement de celui qui vous a appelés par la grâce de Christ, à un évangile différent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'qui n’en est pas un autre; mais il y a des gens qui vous troublent, et qui veulent pervertir l’évangile du Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Mais quand nous-mêmes, ou quand un ange venu du ciel vous évangéliserait outre ce que nous vous avons évangélisé, qu’il soit anathème.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Comme nous l’avons déjà dit, maintenant aussi je le dis encore: si quelqu’un vous évangélise outre ce que vous avez reçu, qu’il soit anathème.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Car maintenant, est-ce que je m’applique à satisfaire des hommes, ou Dieu? Ou est-ce que je cherche à complaire à des hommes? Si je complaisais encore à des hommes, je ne serais pas esclave de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Or je vous fais savoir, frères, que l’évangile qui a été annoncé par moi n’est pas selon l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Car moi, je ne l’ai pas reçu de l’homme non plus, ni appris, mais par la révélation de Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Car vous avez entendu dire [quelle a été] autrefois ma conduite dans le judaïsme, comment je persécutais outre mesure l’assemblée de Dieu et la dévastais,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'et comment j’avançais dans le judaïsme plus que plusieurs de ceux de mon âge dans ma nation, étant le plus ardent zélateur des traditions de mes pères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Mais quand il plut à Dieu, qui m’a mis à part dès le ventre de ma mère et qui m’a appelé par sa grâce,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'de révéler son Fils en moi, afin que je l’annonce parmi les nations, aussitôt, je ne pris pas conseil de la chair ni du sang,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'ni ne montai à Jérusalem vers ceux qui étaient apôtres avant moi, mais je m’en allai en Arabie, et je retournai de nouveau à Damas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Puis, trois ans après, je montai à Jérusalem pour faire la connaissance de Céphas, et je demeurai chez lui 15 jours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'et je ne vis aucun autre des apôtres, sinon Jacques le frère du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Or dans les choses que je vous écris, voici, devant Dieu, je ne mens point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Ensuite j’allai dans les pays de Syrie et de Cilicie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Or j’étais inconnu de visage aux assemblées de la Judée qui sont en Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'mais seulement elles entendaient dire: Celui qui nous persécutait autrefois, annonce maintenant la foi qu’il détruisait jadis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'et elles glorifiaient Dieu à cause de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Ensuite, au bout de 14 ans, je montai de nouveau à Jérusalem avec Barnabas, prenant aussi Tite avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Or j’y montai selon une révélation, et je leur exposai l’évangile que je prêche parmi les nations, mais, dans le particulier, à ceux qui étaient considérés, de peur qu’en quelque manière je ne coure ou n’aie couru en vain');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, '(cependant, même Tite qui était avec moi, quoiqu’il soit Grec, ne fut pas contraint à être circoncis):');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'et cela à cause des faux frères, furtivement introduits, qui s’étaient insinués pour épier la liberté que nous avons dans le christ Jésus, afin de nous réduire à la servitude;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'auxquels nous n’avons pas cédé par soumission, non pas même un moment, afin que la vérité de l’évangile demeure avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Or, de ceux qui étaient considérés comme étant quelque chose..., quels qu’ils aient pu être, cela ne m’importe en rien: Dieu n’a point égard à l’apparence de l’homme..., à moi, certes, ceux qui étaient considérés n’ont rien communiqué de plus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'mais au contraire, ayant vu que l’évangile de l’incirconcision m’a été confié, comme celui de la circoncision l’a été à Pierre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(car celui qui a opéré en Pierre pour l’apostolat de la circoncision a opéré en moi aussi envers les nations),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'et ayant reconnu la grâce qui m’a été donnée, Jacques, et Céphas, et Jean, qui étaient considérés comme étant des colonnes, me donnèrent, à moi et à Barnabas, la main d’association, afin que nous [allions] vers les nations, et eux vers la circoncision,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, '[voulant] seulement que nous nous souvenions des pauvres, ce qu’aussi je me suis appliqué à faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Mais quand Céphas vint à Antioche, je lui résistai en face, parce qu’il était condamné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Car, avant que quelques-uns soient venus d’auprès de Jacques, il mangeait avec ceux des nations; mais quand ceux-là furent venus, il se retira et se sépara lui-même, craignant ceux de la circoncision;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'et les autres Juifs aussi usèrent de dissimulation avec lui, de sorte que Barnabas même fut entraîné avec eux par leur dissimulation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Mais quand je vis qu’ils ne marchaient pas droit, selon la vérité de l’évangile, je dis à Céphas devant tous: Si toi qui es Juif, tu vis comme les nations et non pas comme les Juifs, comment contrains-tu les nations à judaïser?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Nous qui, de nature, sommes Juifs et non point pécheurs d’entre les nations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'sachant néanmoins que l’homme n’est pas justifié sur le principe des œuvres de loi, ni autrement que par la foi en Jésus Christ, nous aussi, nous avons cru au christ Jésus, afin que nous soyons justifiés sur le principe de la foi en Christ et non pas sur le principe des œuvres de loi: parce que sur le principe des œuvres de loi nulle chair ne sera justifiée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Or si, en cherchant à être justifiés en Christ, nous-mêmes aussi nous avons été trouvés pécheurs, Christ donc est ministre de péché? Qu’ainsi n’advienne!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Car si ces mêmes choses que j’ai renversées, je les réédifie, je me constitue transgresseur moi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Car moi, par [la] loi, je suis mort à [la] loi, afin que je vive à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Je suis crucifié avec Christ; et je ne vis plus, moi, mais Christ vit en moi; – et ce que je vis maintenant dans [la] chair, je le vis dans [la] foi, la [foi] au Fils de Dieu, qui m’a aimé et qui s’est livré lui-même pour moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Je n’annule pas la grâce de Dieu; car si [la] justice est par [la] loi, Christ est donc mort pour rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Ô Galates insensés, qui vous a ensorcelés, vous devant les yeux de qui Jésus Christ a été dépeint, crucifié [au milieu de vous]?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Je voudrais seulement apprendre ceci de vous: avez-vous reçu l’Esprit sur le principe des œuvres de loi, ou de l’ouïe de [la] foi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Êtes-vous si insensés? Ayant commencé par l’Esprit, achèveriez-vous maintenant par la chair?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Avez-vous tant souffert en vain, si toutefois c’est en vain?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Celui donc qui vous fournit l’Esprit et qui opère des miracles au milieu de vous, [le fait-il] sur le principe des œuvres de loi, ou de l’ouïe de [la] foi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'comme Abraham a cru Dieu, et cela lui fut compté à justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Sachez donc que ceux qui sont sur le principe de [la] foi, ceux-là sont fils d’Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Or l’écriture, prévoyant que Dieu justifierait les nations sur le principe de [la] foi, a d’avance annoncé la bonne nouvelle à Abraham: « En toi toutes les nations seront bénies ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'De sorte que ceux qui sont sur le principe de [la] foi sont bénis avec le croyant Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Car tous ceux qui sont sur le principe des œuvres de loi sont sous malédiction; car il est écrit: « Maudit est quiconque ne persévère pas dans toutes les choses qui sont écrites dans le livre de la loi pour les faire ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Or que par [la] loi personne ne soit justifié devant Dieu, cela est évident, parce que: « Le juste vivra de foi ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Mais la loi n’est pas sur le principe de [la] foi, mais: « Celui qui aura fait ces choses vivra par elles ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Christ nous a rachetés de la malédiction de la loi, étant devenu malédiction pour nous (car il est écrit: « Maudit est quiconque est pendu au bois »),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'afin que la bénédiction d’Abraham parvienne aux nations dans le christ Jésus, afin que nous recevions par la foi l’Esprit promis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Frères, je parle selon l’homme: personne n’annule une alliance qui est confirmée, même [celle] d’un homme, ni n’y ajoute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Or c’est à Abraham que les promesses ont été faites, et à sa semence. Il ne dit pas: “et aux semences”, comme [parlant] de plusieurs; mais comme [parlant] d’un seul: – « et à ta semence », qui est Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Or je dis ceci: que la loi, qui est survenue 430 ans après, n’annule point une alliance antérieurement confirmée par Dieu, de manière à rendre la promesse sans effet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Car si l’héritage est sur le principe de loi, il n’est plus sur le principe de promesse; mais Dieu a fait le don à Abraham par promesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Pourquoi donc la loi? Elle a été ajoutée à cause des transgressions, jusqu’à ce que vienne la semence à laquelle la promesse est faite, ayant été ordonnée par des anges, par la main d’un médiateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Or un médiateur n’est pas [médiateur] d’un seul, mais Dieu est un seul.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'La loi est-elle donc contre les promesses de Dieu? Qu’ainsi n’advienne! Car s’il avait été donné une loi qui ait le pouvoir de faire vivre, la justice serait en réalité sur le principe de [la] loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Mais l’écriture a renfermé toutes choses sous le péché, afin que la promesse, sur le principe de [la] foi en Jésus Christ, soit donnée à ceux qui croient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Or avant que la foi vienne, nous étions gardés sous [la] loi, renfermés pour la foi qui devait être révélée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'de sorte que la loi a été notre conducteur jusqu’à Christ, afin que nous soyons justifiés sur le principe de [la] foi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'mais, la foi étant venue, nous ne sommes plus sous un conducteur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'car vous êtes tous fils de Dieu par la foi dans le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Car vous tous qui avez été baptisés pour Christ, vous avez revêtu Christ:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'il n’y a ni Juif, ni Grec; il n’y a ni esclave, ni homme libre; il n’y a ni mâle, ni femelle; car vous tous, vous êtes un dans le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Or si vous êtes de Christ, vous êtes donc [la] semence d’Abraham, héritiers selon [la] promesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Or je dis qu’aussi longtemps que l’héritier est en bas âge, il ne diffère en rien d’un esclave, quoiqu’il soit seigneur de tout;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'mais il est sous des tuteurs et des curateurs jusqu’à l’époque fixée par le père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Ainsi aussi nous, lorsque nous étions en bas âge, nous étions asservis sous les éléments du monde;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'mais, quand l’accomplissement du temps est venu, Dieu a envoyé son Fils, né de femme, né sous [la] loi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'afin qu’il rachète ceux [qui étaient] sous [la] loi, afin que nous recevions l’adoption.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Et, parce que vous êtes fils, Dieu a envoyé l’Esprit de son Fils dans nos cœurs, criant: Abba, Père:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'de sorte que tu n’es plus esclave, mais fils; et, si fils, héritier aussi par Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Mais alors, ne connaissant pas Dieu, vous étiez asservis à ceux qui, par [leur] nature, ne sont pas dieux:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'mais maintenant, ayant connu Dieu, mais plutôt ayant été connus de Dieu, comment retournez-vous de nouveau aux faibles et misérables éléments auxquels vous voulez encore à nouveau être asservis?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Vous observez des jours, et des mois, et des temps, et des années.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Je crains, quant à vous, que peut-être je n’aie travaillé en vain pour vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Soyez comme moi, car moi aussi [je suis] comme vous, frères; je vous en prie. Vous ne m’avez fait aucun tort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, '– et vous savez que dans l’infirmité de la chair je vous ai évangélisé au commencement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'et vous n’avez point méprisé, ni rejeté avec dégoût ma tentation qui était en ma chair; mais vous m’avez reçu comme un ange de Dieu, comme le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Quel était donc votre bonheur? Car je vous rends témoignage que, si cela avait été possible, arrachant vos propres yeux, vous me les auriez donnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Je suis donc devenu votre ennemi en vous disant la vérité?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Ils ne sont pas zélés à votre égard comme il faut, mais ils veulent vous exclure, afin que vous soyez zélés à leur égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Mais il est bon d’être toujours zélé pour le bien, et de ne pas l’être seulement quand je suis présent avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Mes enfants, pour l’enfantement desquels je travaille de nouveau jusqu’à ce que Christ ait été formé en vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'oui, je voudrais être maintenant auprès de vous et changer de langage, car je suis en perplexité à votre sujet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Dites-moi, vous qui voulez être sous [la] loi, n’écoutez-vous pas la loi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Car il est écrit qu’Abraham a eu deux fils, l’un de la servante, et l’autre de la femme libre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Mais celui qui [naquit] de la servante naquit selon la chair, et celui qui [naquit] de la femme libre [naquit] par la promesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Ces choses doivent être prises dans un sens allégorique: car ce sont deux alliances, l’une du mont Sina, enfantant pour la servitude, et c’est Agar.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Car “Agar” est le mont Sina, en Arabie, et correspond à la Jérusalem de maintenant, car elle est dans la servitude avec ses enfants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Mais la Jérusalem d’en haut est la femme libre qui est notre mère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Car il est écrit: « Réjouis-toi, stérile qui n’enfantes point; éclate [de joie] et pousse des cris, toi qui n’es point en travail d’enfant; car les enfants de la délaissée sont plus nombreux que [les enfants] de celle qui a un mari ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Or vous, frères, comme Isaac, vous êtes enfants de promesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Mais, comme alors celui qui était né selon la chair persécutait celui qui [était né] selon l’Esprit, [il en est] de même aussi maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Mais que dit l’écriture? « Chasse la servante et son fils, car le fils de la servante n’héritera point avec le fils de la femme libre ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Ainsi, frères, nous ne sommes pas enfants de [la] servante, mais de la femme libre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Christ nous a placés dans la liberté en nous affranchissant; tenez-vous donc fermes, et ne soyez pas de nouveau retenus sous un joug de servitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Voici, moi Paul, je vous dis que si vous êtes circoncis, Christ ne vous profitera de rien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'et je proteste de nouveau à tout homme circoncis, qu’il est tenu d’accomplir toute la loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Vous vous êtes séparés de tout le bénéfice qu’il y a dans le Christ, vous tous qui vous justifiez par [la] loi; vous êtes déchus de la grâce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Car nous, par [l’]Esprit, sur le principe de [la] foi, nous attendons l’espérance de la justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Car, dans le christ Jésus, ni circoncision, ni incirconcision, n’ont de valeur, mais [la] foi opérante par [l’]amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Vous couriez bien, qui est-ce qui vous a arrêtés pour que vous n’obéissiez pas à la vérité?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'La persuasion ne vient pas de celui qui vous appelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Un peu de levain fait lever la pâte tout entière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'J’ai confiance à votre égard par le Seigneur, que vous n’aurez point d’autre sentiment; mais celui qui vous trouble, quel qu’il soit, en portera le jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Mais moi, frères, si je prêche encore la circoncision, pourquoi suis-je encore persécuté? – alors le scandale de la croix est anéanti.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Je voudrais que ceux qui vous bouleversent se retranchent même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Car vous, frères, vous avez été appelés à la liberté; seulement [n’usez] pas de la liberté comme d’une occasion pour la chair, mais, par amour, servez-vous l’un l’autre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'car toute la loi est accomplie dans une seule parole, dans celle-ci: « Tu aimeras ton prochain comme toi-même ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Mais si vous vous mordez et vous dévorez l’un l’autre, prenez garde que vous ne soyez consumés l’un par l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Mais je dis: Marchez par l’Esprit, et vous n’accomplirez point la convoitise de la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Car la chair convoite contre l’Esprit, et l’Esprit contre la chair; et ces choses sont opposées l’une à l’autre, afin que vous ne pratiquiez pas les choses que vous voudriez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Mais si vous êtes conduits par [l’]Esprit, vous n’êtes pas sous [la] loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Or les œuvres de la chair sont manifestes, lesquelles sont la fornication, l’impureté, l’impudicité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'l’idolâtrie, la magie, les inimitiés, les querelles, les jalousies, les colères, les intrigues, les divisions, les sectes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'les envies, les meurtres, les ivrogneries, les orgies, et les choses semblables à celles-là, au sujet desquelles je vous déclare d’avance, comme aussi je l’ai déjà dit, que ceux qui commettent de telles choses n’hériteront pas du royaume de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Mais le fruit de l’Esprit est l’amour, la joie, la paix, la longanimité, la bienveillance, la bonté, la fidélité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'la douceur, la tempérance: contre de telles choses, il n’y a pas de loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Or ceux qui sont du Christ ont crucifié la chair avec les passions et les convoitises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Si nous vivons par l’Esprit, marchons aussi par l’Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Ne soyons pas désireux de vaine gloire, en nous provoquant les uns les autres [et] en nous portant envie les uns aux autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Frères, quand même un homme s’est laissé surprendre par quelque faute, vous qui êtes spirituels, redressez un tel homme dans un esprit de douceur, prenant garde à toi-même, de peur que toi aussi tu ne sois tenté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Portez les charges les uns des autres, et ainsi accomplissez la loi du Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'car si, n’étant rien, quelqu’un pense être quelque chose, il se séduit lui-même;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'mais que chacun éprouve sa propre œuvre, et alors il aura de quoi se glorifier, relativement à lui-même seulement et non relativement à autrui:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'car chacun portera son propre fardeau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Que celui qui est enseigné dans la parole fasse participer à tous les biens [temporels] celui qui enseigne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Ne soyez pas séduits; on ne se moque pas de Dieu; car ce qu’un homme sème, cela aussi il le moissonnera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Car celui qui sème pour sa propre chair moissonnera de la chair la corruption; mais celui qui sème pour l’Esprit moissonnera de l’Esprit la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Or ne nous lassons pas en faisant le bien, car, au temps propre, nous moissonnerons, si nous ne défaillons pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Ainsi donc, comme nous en avons l’occasion, faisons du bien à tous, mais surtout à ceux de la maison de la foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Vous voyez quelle longue lettre je vous ai écrite de ma propre main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Tous ceux qui veulent avoir une belle apparence dans la chair, ceux-là vous contraignent à être circoncis, seulement afin qu’ils ne soient pas persécutés à cause de la croix de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Car ceux-là qui sont circoncis, eux-mêmes ne gardent pas [la] loi; mais ils veulent que vous soyez circoncis, afin de se glorifier dans votre chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Mais qu’il ne m’arrive pas à moi de me glorifier, sinon en la croix de notre seigneur Jésus Christ, par laquelle le monde m’est crucifié, et moi au monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Car ni la circoncision, ni l’incirconcision ne sont rien, mais une nouvelle création.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Et à l’égard de tous ceux qui marcheront selon cette règle, paix et miséricorde sur eux et sur l’Israël de Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Désormais que personne ne vienne me troubler, car moi je porte en mon corps les marques du seigneur Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Que la grâce de notre seigneur Jésus Christ soit avec votre esprit, frères! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paul, apôtre de Jésus Christ par la volonté de Dieu, aux saints et fidèles dans le christ Jésus, qui sont à Éphèse:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Grâce et paix à vous, de la part de Dieu notre Père et du seigneur Jésus Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Béni soit le Dieu et Père de notre seigneur Jésus Christ, qui nous a bénis de toute bénédiction spirituelle dans les lieux célestes en Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'selon qu’il nous a élus en lui avant la fondation du monde, pour que nous soyons saints et irréprochables devant lui en amour,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'nous ayant prédestinés pour nous adopter pour lui par Jésus Christ, selon le bon plaisir de sa volonté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'à la louange de la gloire de sa grâce dans laquelle il nous a rendus agréables dans le Bien-aimé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'en qui nous avons la rédemption par son sang, la rémission des fautes selon les richesses de sa grâce:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'laquelle il a fait abonder envers nous en toute sagesse et intelligence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'nous ayant fait connaître le mystère de sa volonté selon son bon plaisir, qu’il s’est proposé en lui-même');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'pour l’administration de la plénitude des temps, [savoir] de réunir en un toutes choses dans le Christ, les choses qui sont dans les cieux et les choses qui sont sur la terre, en lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'en qui nous avons aussi été faits héritiers, ayant été prédestinés selon le propos de celui qui opère toutes choses selon le conseil de sa volonté,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'afin que nous soyons à la louange de sa gloire, nous qui avons espéré à l’avance dans le Christ:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'en qui vous aussi [vous avez espéré], ayant entendu la parole de la vérité, l’évangile de votre salut; auquel aussi ayant cru, vous avez été scellés du Saint Esprit de la promesse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'qui est les arrhes de notre héritage, pour la rédemption de la possession acquise, à la louange de sa gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'C’est pourquoi moi aussi, ayant entendu parler de la foi au seigneur Jésus qui est en vous, et de l’amour que [vous avez] pour tous les saints,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'je ne cesse de rendre grâces pour vous, faisant mention [de vous] dans mes prières,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'afin que le Dieu de notre seigneur Jésus Christ, le Père de gloire, vous donne [l’]esprit de sagesse et de révélation dans sa connaissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'les yeux de votre cœur étant éclairés, pour que vous sachiez quelle est l’espérance de son appel, et quelles sont les richesses de la gloire de son héritage dans les saints,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'et quelle est l’excellente grandeur de sa puissance envers nous qui croyons, selon l’opération de la puissance de sa force,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'qu’il a opérée dans le Christ, en le ressuscitant d’entre les morts; – (et il l’a fait asseoir à sa droite dans les lieux célestes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'au-dessus de toute principauté, et autorité, et puissance, et domination, et de tout nom qui se nomme, non seulement dans ce siècle, mais aussi dans celui qui est à venir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'et il a assujetti toutes choses sous ses pieds, et l’a donné [pour être] chef sur toutes choses à l’assemblée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'qui est son corps, la plénitude de celui qui remplit tout en tous;)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, '– et vous, lorsque vous étiez morts dans vos fautes et dans vos péchés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, '(dans lesquels vous avez marché autrefois, selon le train de ce monde, selon le chef de l’autorité de l’air, de l’esprit qui opère maintenant dans les fils de la désobéissance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'parmi lesquels, nous aussi, nous avons tous vécu autrefois dans les convoitises de notre chair, accomplissant les volontés de la chair et des pensées; et nous étions par nature des enfants de colère, comme aussi les autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Mais Dieu, qui est riche en miséricorde, à cause de son grand amour dont il nous a aimés,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'alors même que nous étions morts dans nos fautes, nous a vivifiés ensemble avec le Christ (vous êtes sauvés par [la] grâce),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'et nous a ressuscités ensemble, et nous a fait asseoir ensemble dans les lieux célestes dans le christ Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'afin qu’il montre dans les siècles à venir les immenses richesses de sa grâce, dans sa bonté envers nous dans le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Car vous êtes sauvés par la grâce, par la foi, et cela ne vient pas de vous, c’est le don de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'non pas sur le principe des œuvres, afin que personne ne se glorifie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'car nous sommes son ouvrage, ayant été créés dans le christ Jésus pour les bonnes œuvres que Dieu a préparées à l’avance, afin que nous marchions en elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'C’est pourquoi souvenez-vous que vous, autrefois les nations dans la chair, qui étiez appelés incirconcision par ce qui est appelé la circoncision, faite de main dans la chair,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'vous étiez en ce temps-là sans Christ, sans droit de cité en Israël et étrangers aux alliances de la promesse, n’ayant pas d’espérance, et étant sans Dieu dans le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Mais maintenant, dans le christ Jésus, vous qui étiez autrefois loin, vous avez été approchés par le sang du Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Car c’est lui qui est notre paix, qui des deux en a fait un et a détruit le mur mitoyen de clôture,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'ayant aboli dans sa chair l’inimitié, la loi des commandements [qui consiste] en ordonnances, afin qu’il crée les deux en lui-même pour être un seul homme nouveau, en faisant la paix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'et qu’il les réconcilie tous les deux en un seul corps à Dieu par la croix, ayant tué par elle l’inimitié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Et il est venu, et a annoncé la bonne nouvelle de la paix à vous qui étiez loin, et la [bonne nouvelle de la] paix à ceux qui étaient près;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'car par lui nous avons, les uns et les autres, accès auprès du Père par un seul Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Ainsi donc vous n’êtes plus étrangers ni forains, mais vous êtes concitoyens des saints et gens de la maison de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'ayant été édifiés sur le fondement des apôtres et prophètes, Jésus Christ lui-même étant la maîtresse pierre du coin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'en qui tout l’édifice, bien ajusté ensemble, croît pour être un temple saint dans le Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'en qui, vous aussi, vous êtes édifiés ensemble, pour être une habitation de Dieu par l’Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'C’est pour cela que moi, Paul, le prisonnier du christ Jésus pour vous, les nations');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, '– (si du moins vous avez entendu parler de l’administration de la grâce de Dieu qui m’a été donnée envers vous:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'comment, par révélation, le mystère m’a été donné à connaître (ainsi que je l’ai déjà écrit en peu de mots;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'd’après quoi, en le lisant, vous pouvez comprendre quelle est mon intelligence dans le mystère du Christ),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'lequel, en d’autres générations, n’a pas été donné à connaître aux fils des hommes, comme il a été maintenant révélé à ses saints apôtres et prophètes par l’Esprit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, '[savoir] que les nations seraient cohéritières et d’un même corps et coparticipantes de sa promesse dans le christ Jésus, par l’évangile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'duquel je suis devenu serviteur, selon le don de la grâce de Dieu qui m’a été donné selon l’opération de sa puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'À moi, qui suis moins que le moindre de tous les saints, cette grâce a été donnée d’annoncer parmi les nations les richesses insondables du Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'et de mettre en lumière devant tous quelle est l’administration du mystère caché dès les siècles en Dieu qui a créé toutes choses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'afin que la sagesse si diverse de Dieu soit maintenant donnée à connaître aux principautés et aux autorités dans les lieux célestes, par l’assemblée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'selon le propos des siècles, lequel il a établi dans le christ Jésus notre Seigneur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'en qui nous avons hardiesse et accès en confiance, par la foi en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'C’est pourquoi je [vous] prie de ne pas perdre courage à cause de mes afflictions pour vous, ce qui est votre gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, '– C’est pour cela que je fléchis mes genoux devant le Père [de notre seigneur Jésus Christ],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'duquel est nommée toute famille dans les cieux et sur la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'afin que, selon les richesses de sa gloire, il vous donne d’être fortifiés en puissance par son Esprit, quant à l’homme intérieur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'de sorte que le Christ habite, par la foi, dans vos cœurs, [et que vous soyez] enracinés et fondés dans l’amour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'afin que vous soyez capables de comprendre avec tous les saints quelle est la largeur et la longueur, et la profondeur et la hauteur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, '– et de connaître l’amour du Christ qui surpasse toute connaissance; afin que vous soyez remplis jusqu’à toute la plénitude de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Or, à celui qui peut faire infiniment plus que tout ce que nous demandons ou pensons, selon la puissance qui opère en nous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'à lui gloire dans l’assemblée dans le christ Jésus, pour toutes les générations du siècle des siècles! Amen.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Je vous exhorte donc, moi, le prisonnier dans le Seigneur, à marcher d’une manière digne de l’appel dont vous avez été appelés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'avec toute humilité et douceur, avec longanimité, vous supportant l’un l’autre dans l’amour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'vous appliquant à garder l’unité de l’Esprit par le lien de la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, '[Il y a] un seul corps et un seul Esprit, comme aussi vous avez été appelés pour une seule espérance de votre appel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, '[Il y a] un seul Seigneur, une seule foi, un seul baptême.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, '[Il y a] un seul Dieu et Père de tous, qui est au-dessus de tout, et partout, et en nous tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Mais à chacun de nous la grâce a été donnée selon la mesure du don de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'C’est pourquoi il dit: « Étant monté en haut, il a emmené captive la captivité, et a donné des dons aux hommes ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Or, qu’il soit monté, qu’est-ce, sinon qu’il est aussi descendu dans les parties inférieures de la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Celui qui est descendu est le même que celui qui est aussi monté au-dessus de tous les cieux, afin qu’il remplisse toutes choses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'et lui, a donné les uns [comme] apôtres, les autres [comme] prophètes, les autres [comme] évangélistes, les autres [comme] pasteurs et docteurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'en vue du perfectionnement des saints, pour l’œuvre du service, pour l’édification du corps de Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'jusqu’à ce que nous parvenions tous à l’unité de la foi et de la connaissance du Fils de Dieu, à l’état d’homme fait, à la mesure de la stature de la plénitude du Christ:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'afin que nous ne soyons plus de petits enfants, ballottés et emportés çà et là par tout vent de doctrine dans la tromperie des hommes, dans leur habileté à user de voies détournées pour égarer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'mais que, étant vrais dans l’amour, nous croissions en toutes choses jusqu’à lui qui est le chef, le Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'duquel tout le corps, bien ajusté et lié ensemble par chaque jointure du fournissement, produit, selon l’opération de chaque partie dans sa mesure, l’accroissement du corps pour l’édification de lui-même en amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Voici donc ce que je dis et témoigne dans le Seigneur, c’est que vous ne marchiez plus comme le reste des nations marche, dans la vanité de leurs pensées,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'ayant leur entendement obscurci, étant étrangers à la vie de Dieu à cause de l’ignorance qui est en eux, à cause de l’endurcissement de leur cœur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'et qui, ayant perdu tout sentiment moral, se sont livrés à la débauche, pour pratiquer avidement toute impureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Mais vous n’avez pas ainsi appris le Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'si du moins vous l’avez entendu et avez été instruits en lui selon que la vérité est en Jésus:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, '[c’est-à-dire], en ce qui concerne votre première manière de vivre, d’avoir dépouillé le vieil homme qui se corrompt selon les convoitises trompeuses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'et d’être renouvelés dans l’esprit de votre entendement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'et d’avoir revêtu le nouvel homme, créé selon Dieu, en justice et sainteté de la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'C’est pourquoi, ayant dépouillé le mensonge, parlez la vérité chacun à son prochain; car nous sommes membres les uns des autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Mettez-vous en colère et ne péchez pas: que le soleil ne se couche pas sur votre irritation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'et ne donnez pas occasion au diable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Que celui qui dérobait ne dérobe plus, mais plutôt qu’il travaille en faisant de ses propres mains ce qui est bon, afin qu’il ait de quoi donner à celui qui est dans le besoin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Qu’aucune parole déshonnête ne sorte de votre bouche, mais celle-là qui est bonne, [propre] à l’édification selon le besoin, afin qu’elle communique la grâce à ceux qui l’entendent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Et n’attristez pas le Saint Esprit de Dieu, par lequel vous avez été scellés pour le jour de la rédemption.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Que toute amertume, et tout courroux, et toute colère, et toute crierie, et toute injure, soient ôtés du milieu de vous, de même que toute malice;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'mais soyez bons les uns envers les autres, compatissants, vous pardonnant les uns aux autres comme Dieu aussi, en Christ, vous a pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Soyez donc imitateurs de Dieu comme de bien-aimés enfants,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'et marchez dans l’amour, comme aussi le Christ nous a aimés et s’est livré lui-même pour nous, comme offrande et sacrifice à Dieu, en parfum de bonne odeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Mais que ni la fornication, ni aucune impureté ou cupidité, ne soient même nommées parmi vous, comme il convient à des saints;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'ni aucune chose honteuse, ni parole folle ou plaisanterie, lesquelles ne sont pas bienséantes, mais plutôt des actions de grâces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Cela en effet vous le savez, connaissant qu’aucun fornicateur, ou impur, ou cupide (qui est un idolâtre), n’a d’héritage dans le royaume du Christ et de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Que personne ne vous séduise par de vaines paroles; car, à cause de ces choses, la colère de Dieu vient sur les fils de la désobéissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'N’ayez donc pas de participation avec eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'car vous étiez autrefois ténèbres, mais maintenant vous êtes lumière dans le Seigneur; marchez comme des enfants de lumière');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(car le fruit de la lumière [consiste] en toute bonté, et justice, et vérité),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'éprouvant ce qui est agréable au Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Et n’ayez rien de commun avec les œuvres infructueuses des ténèbres, mais plutôt reprenez-les aussi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'car les choses qu’ils font en secret, il est honteux même de les dire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Mais toutes choses, étant reprises par la lumière, sont manifestées; car ce qui manifeste tout, c’est la lumière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'c’est pourquoi il dit: « Réveille-toi, toi qui dors, et relève-toi d’entre les morts, et le Christ luira sur toi ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Prenez donc garde à marcher soigneusement, non pas comme étant dépourvus de sagesse, mais comme étant sages;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'saisissant l’occasion, parce que les jours sont mauvais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'C’est pourquoi ne soyez pas sans intelligence, mais comprenez quelle est la volonté du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Et ne vous enivrez pas de vin, en quoi il y a de la dissolution; mais soyez remplis de l’Esprit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'vous entretenant par des psaumes et des hymnes et des cantiques spirituels, chantant et psalmodiant de votre cœur au Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'rendant toujours grâces pour toutes choses, au nom de notre seigneur Jésus Christ, à Dieu le Père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'étant soumis les uns aux autres dans la crainte de Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Femmes, soyez soumises à vos propres maris comme au Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'parce que le mari est le chef de la femme, comme aussi le Christ est le chef de l’assemblée, lui, le sauveur du corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Mais comme l’assemblée est soumise au Christ, ainsi que les femmes le soient aussi à leurs maris en toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Maris, aimez vos propres femmes, comme aussi le Christ a aimé l’assemblée et s’est livré lui-même pour elle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'afin qu’il la sanctifie, en la purifiant par le lavage d’eau par [la] parole;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'afin que lui se présente l’assemblée à lui-même, glorieuse, n’ayant ni tache, ni ride, ni rien de semblable, mais afin qu’elle soit sainte et irréprochable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'De même aussi, les maris doivent aimer leurs propres femmes comme leurs propres corps; celui qui aime sa propre femme s’aime lui-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Car personne n’a jamais haï sa propre chair, mais il la nourrit et la chérit, comme aussi le Christ l’assemblée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'car nous sommes membres de son corps, – de sa chair et de ses os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, '« C’est pour cela que l’homme laissera son père et sa mère et sera joint à sa femme; et les deux seront une seule chair ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Ce mystère est grand; mais moi je parle relativement à Christ et à l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Toutefois, que chacun de vous aussi en particulier aime sa propre femme comme lui-même; et quant à la femme, qu’elle craigne son mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Enfants, obéissez à vos parents dans le Seigneur, car cela est juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '« Honore ton père et ta mère », (c’est le premier commandement avec promesse,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '« afin que tu prospères et que tu vives longtemps sur la terre ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Et vous, pères, ne provoquez pas vos enfants, mais élevez-les dans la discipline et sous les avertissements du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Esclaves, obéissez à vos maîtres selon la chair avec crainte et tremblement, en simplicité de cœur, comme à Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'ne servant pas sous leurs yeux seulement, comme voulant plaire aux hommes, mais comme esclaves de Christ, faisant de cœur la volonté de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'servant joyeusement, comme asservis au Seigneur et non pas aux hommes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'sachant que chacun, soit esclave, soit homme libre, quelque bien qu’il fasse, le recevra du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Et vous, maîtres, faites-en de même envers eux, renonçant aux menaces, sachant que et leur maître et le vôtre est dans les cieux, et qu’il n’y a pas d’acception de personnes auprès de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Au reste, mes frères, fortifiez-vous dans le Seigneur et dans la puissance de sa force;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'revêtez-vous de l’armure complète de Dieu, afin que vous puissiez tenir ferme contre les artifices du diable:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'car notre lutte n’est pas contre le sang et la chair, mais contre les principautés, contre les autorités, contre les dominateurs de ces ténèbres, contre la [puissance] spirituelle de méchanceté qui est dans les lieux célestes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'C’est pourquoi prenez l’armure complète de Dieu, afin que, au mauvais jour, vous puissiez résister, et, après avoir tout surmonté, tenir ferme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Tenez donc ferme, ayant ceint vos reins de [la] vérité, et ayant revêtu la cuirasse de la justice,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'et ayant chaussé vos pieds de la préparation de l’évangile de paix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'par-dessus tout, prenant le bouclier de la foi par lequel vous pourrez éteindre tous les dards enflammés du méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Prenez aussi le casque du salut, et l’épée de l’Esprit, qui est la parole de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'priant par toutes sortes de prières et de supplications, en tout temps, par l’Esprit, et veillant à cela avec toute persévérance et des supplications pour tous les saints,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'et pour moi, afin qu’il me soit donné de parler à bouche ouverte pour donner à connaître avec hardiesse le mystère de l’évangile,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'pour lequel je suis un ambassadeur lié de chaînes, afin que j’use de hardiesse en lui, comme je dois parler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Mais afin que vous aussi vous sachiez ce qui me concerne, comment je me trouve, Tychique, le bien-aimé frère et fidèle serviteur dans le Seigneur, vous fera tout savoir:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'je l’ai envoyé vers vous tout exprès, afin que vous connaissiez l’état de nos affaires, et qu’il console vos cœurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Paix aux frères, et amour, avec la foi, de la part de Dieu le Père et du seigneur Jésus Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Que la grâce soit avec tous ceux qui aiment notre seigneur Jésus Christ en pureté!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paul et Timothée, esclaves de Jésus Christ, à tous les saints dans le christ Jésus qui sont à Philippes, avec les surveillants et les serviteurs:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Grâce et paix à vous, de la part de Dieu notre Père et du seigneur Jésus Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Je rends grâces à mon Dieu pour tout le souvenir que j’ai de vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'dans chacune de mes supplications, faisant toujours des supplications pour vous tous, avec joie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'à cause de la part que vous prenez à l’évangile depuis le premier jour jusqu’à maintenant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'étant assuré de ceci même, que celui qui a commencé en vous une bonne œuvre, l’achèvera jusqu’au jour de Jésus Christ:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'comme il est juste que je pense ainsi de vous tous, parce que vous m’avez dans votre cœur, et que, dans mes liens et dans la défense et la confirmation de l’évangile, vous avez tous été participants de la grâce avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Car Dieu m’est témoin que je pense avec une vive affection à vous tous, dans les entrailles du christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Et je demande ceci dans mes prières, que votre amour abonde encore de plus en plus en connaissance et toute intelligence,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'pour que vous discerniez les choses excellentes, afin que vous soyez purs et que vous ne bronchiez pas jusqu’au jour de Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'étant remplis du fruit de la justice, qui est par Jésus Christ à la gloire et à la louange de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Or, frères, je veux que vous sachiez que les circonstances par lesquelles je passe sont plutôt arrivées pour l’avancement de l’évangile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'en sorte que mes liens sont devenus manifestes comme étant en Christ, dans tout le prétoire et à tous les autres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'et que la plupart des frères, ayant, dans le Seigneur, pris confiance par mes liens, ont beaucoup plus de hardiesse pour annoncer la parole sans crainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Quelques-uns, il est vrai, prêchent le Christ aussi par envie et par un esprit de dispute, mais quelques-uns aussi de bonne volonté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'ceux-ci par amour, sachant que je suis établi pour la défense de l’évangile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'ceux-là annoncent le Christ par esprit de parti, non pas purement, croyant susciter de la tribulation pour mes liens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Quoi donc? – Toutefois, de toute manière, soit comme prétexte, soit en vérité, Christ est annoncé; et en cela je me réjouis et aussi je me réjouirai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Car je sais que ceci me tournera à salut par vos supplications et par les secours de l’Esprit de Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'selon ma vive attente et mon espérance que je ne serai confus en rien, mais qu’avec toute hardiesse, maintenant encore comme toujours, Christ sera magnifié dans mon corps, soit par la vie, soit par la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Car pour moi, vivre c’est Christ; et mourir, un gain;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'mais si [je dois] vivre dans la chair, il en vaut bien la peine; et ce que je dois choisir, je n’en sais rien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'mais je suis pressé des deux côtés, ayant le désir de déloger et d’être avec Christ, [car] cela est de beaucoup meilleur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'mais il est plus nécessaire à cause de vous que je demeure dans la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Et ayant cette confiance, je sais que je demeurerai et que je resterai avec vous tous pour l’avancement et la joie de votre foi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'afin qu’en moi vous ayez plus abondamment sujet de vous glorifier dans le christ Jésus, par mon retour au milieu de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Seulement conduisez-vous d’une manière digne de l’évangile du Christ, afin que, soit que je vienne et que je vous voie, soit que je sois absent, j’apprenne à votre sujet que vous tenez ferme dans un seul et même esprit, combattant ensemble d’une même âme, avec la foi de l’évangile,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'et n’étant en rien épouvantés par les adversaires: ce qui pour eux est une démonstration de perdition, mais de votre salut, et cela de la part de Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'parce qu’à vous, il a été gratuitement donné, par rapport à Christ, non seulement de croire en lui, mais aussi de souffrir pour lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'ayant [à soutenir] le même combat que vous avez vu en moi et que vous apprenez être maintenant en moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Si donc il y a quelque consolation en Christ, si quelque soulagement d’amour, si quelque communion de l’Esprit, si quelque tendresse et quelques compassions,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'rendez ma joie accomplie [en ceci] que vous ayez une même pensée, ayant un même amour, étant d’un même sentiment, pensant à une seule et même chose.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, '[Que] rien [ne se fasse] par esprit de parti, ou par vaine gloire; mais que, dans l’humilité, l’un estime l’autre supérieur à lui-même,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'chacun ne regardant pas à ce qui est à lui, mais chacun aussi à ce qui est aux autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Qu’il y ait donc en vous cette pensée qui a été aussi dans le christ Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'lequel, étant en forme de Dieu, n’a pas regardé comme un objet à ravir d’être égal à Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'mais s’est anéanti lui-même, prenant la forme d’esclave, étant fait à la ressemblance des hommes; et, étant trouvé en figure comme un homme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'il s’est abaissé lui-même, étant devenu obéissant jusqu’à la mort, et à la mort de la croix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'C’est pourquoi aussi Dieu l’a haut élevé et lui a donné un nom au-dessus de tout nom,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'afin qu’au nom de Jésus se ploie tout genou des êtres célestes, et terrestres, et infernaux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'et que toute langue confesse que Jésus Christ est Seigneur, à la gloire de Dieu le Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Ainsi donc, mes bien-aimés, de même que vous avez toujours obéi, non seulement comme en ma présence, mais beaucoup plus maintenant en mon absence, travaillez à votre propre salut avec crainte et tremblement:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'car c’est Dieu qui opère en vous et le vouloir et le faire, selon son bon plaisir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Faites toutes choses sans murmures et sans raisonnements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'afin que vous soyez sans reproche et purs, des enfants de Dieu irréprochables, au milieu d’une génération tortue et perverse, parmi laquelle vous reluisez comme des luminaires dans le monde,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'présentant la parole de vie, pour ma gloire au jour de Christ, [en témoignage] que je n’ai pas couru en vain ni travaillé en vain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Mais si même je sers d’aspersion sur le sacrifice et le service de votre foi, j’en suis joyeux et je m’en réjouis avec vous tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Pareillement, vous aussi, soyez-en joyeux et réjouissez-vous-en avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Or j’espère dans le seigneur Jésus vous envoyer bientôt Timothée, afin que moi aussi j’aie bon courage quand j’aurai connu l’état de vos affaires;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'car je n’ai personne qui soit animé d’un même sentiment [avec moi] pour avoir une sincère sollicitude à l’égard de ce qui vous concerne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'parce que tous cherchent leurs propres intérêts, non pas ceux de Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Mais vous savez qu’il a été connu à l’épreuve, [savoir] qu’il a servi avec moi dans l’évangile comme un enfant [sert] son père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'J’espère donc l’envoyer incessamment, quand j’aurai vu la tournure que prendront mes affaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Mais j’ai confiance dans le Seigneur que, moi-même aussi, j’irai [vous voir] bientôt;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'mais j’ai estimé nécessaire de vous envoyer Épaphrodite mon frère, mon compagnon d’œuvre et mon compagnon d’armes, mais votre envoyé et ministre pour mes besoins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Car il pensait à vous tous avec une vive affection, et il était fort abattu parce que vous aviez entendu dire qu’il était malade;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'en effet il a été malade, fort près de la mort, mais Dieu a eu pitié de lui, et non seulement de lui, mais aussi de moi, afin que je n’aie pas tristesse sur tristesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Je l’ai donc envoyé avec d’autant plus d’empressement, afin qu’en le revoyant vous ayez de la joie, et que moi j’aie moins de tristesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Recevez-le donc dans le Seigneur avec toute sorte de joie, et honorez de tels hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'car, pour l’œuvre, il a été proche de la mort, ayant exposé sa vie, afin de compléter ce qui manquait à votre service envers moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Au reste, mes frères, réjouissez-vous dans le Seigneur: vous écrire les mêmes choses n’est pas pénible pour moi, et c’est votre sûreté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Prenez garde aux chiens, prenez garde aux mauvais ouvriers, prenez garde à la concision;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'car nous sommes la circoncision, nous qui rendons culte par l’Esprit de Dieu, et qui nous glorifions dans le christ Jésus, et qui n’avons pas confiance en la chair:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'bien que moi, j’aie [de quoi avoir] confiance même dans la chair. Si quelque autre s’imagine [pouvoir] se confier en la chair, moi davantage:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, '[moi] circoncis le huitième jour, de la race d’Israël, de la tribu de Benjamin, Hébreu des Hébreux; quant à la loi, pharisien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'quant au zèle, persécutant l’assemblée; quant à la justice qui est par [la] loi, étant sans reproche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Mais les choses qui pour moi étaient un gain, je les ai regardées, à cause du Christ, comme une perte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Et je regarde même aussi toutes choses comme étant une perte, à cause de l’excellence de la connaissance du christ Jésus, mon Seigneur, à cause duquel j’ai fait la perte de toutes et je les estime comme des ordures, afin que je gagne Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'et que je sois trouvé en lui, n’ayant pas ma justice qui est de [la] loi, mais celle qui est par [la] foi en Christ, la justice qui est de Dieu, moyennant la foi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'pour le connaître, lui, et la puissance de sa résurrection, et la communion de ses souffrances, étant rendu conforme à sa mort,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'si en quelque manière que ce soit je puis parvenir à la résurrection d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Non que j’aie déjà reçu [le prix] ou que je sois déjà parvenu à la perfection; mais je poursuis, cherchant à le saisir, vu aussi que j’ai été saisi par le Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Frères, pour moi, je ne pense pas moi-même l’avoir saisi; mais [je fais] une chose: oubliant les choses qui sont derrière et tendant avec effort vers celles qui sont devant,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'je cours droit au but pour le prix de l’appel céleste de Dieu dans le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Nous tous donc qui sommes parfaits, ayons ce sentiment; et si en quelque chose vous avez un autre sentiment, cela aussi Dieu vous le révélera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'cependant, dans les choses auxquelles nous sommes parvenus, marchons dans le même [sentier].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Soyez tous ensemble mes imitateurs, frères, et portez vos regards sur ceux qui marchent ainsi suivant le modèle que vous avez en nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Car plusieurs marchent, dont je vous ai dit souvent et dont maintenant je le dis même en pleurant, qu’ils sont ennemis de la croix du Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'dont la fin est la perdition, dont le dieu est le ventre et dont la gloire est dans leur honte, qui ont leurs pensées aux choses terrestres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Car notre bourgeoisie est dans les cieux, d’où aussi nous attendons le Seigneur Jésus Christ [comme] Sauveur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'qui transformera le corps de notre abaissement en la conformité du corps de sa gloire, selon l’opération de ce pouvoir qu’il a de s’assujettir même toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Ainsi donc, mes frères bien-aimés et ardemment désirés, ma joie et ma couronne, demeurez ainsi fermes dans le Seigneur, bien-aimés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Je supplie Évodie, et je supplie Syntyche, d’avoir une même pensée dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Oui, je te prie, toi aussi, vrai compagnon de travail, aide celles qui ont combattu avec moi dans l’évangile avec Clément aussi et mes autres compagnons d’œuvre, dont les noms sont dans le livre de vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Réjouissez-vous toujours dans le Seigneur; encore une fois, je vous le dirai: réjouissez-vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Que votre douceur soit connue de tous les hommes; le Seigneur est proche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'ne vous inquiétez de rien, mais, en toutes choses, exposez vos requêtes à Dieu par des prières et des supplications avec des actions de grâces;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'et la paix de Dieu, laquelle surpasse toute intelligence, gardera vos cœurs et vos pensées dans le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Au reste, frères, toutes les choses qui sont vraies, toutes les choses qui sont vénérables, toutes les choses qui sont justes, toutes les choses qui sont pures, toutes les choses qui sont aimables, toutes les choses qui sont de bonne renommée, – s’il y a quelque vertu et quelque louange, – que ces choses occupent vos pensées:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'ce que vous avez et appris, et reçu, et entendu, et vu en moi, – faites ces choses, et le Dieu de paix sera avec vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Or je me suis grandement réjoui dans le Seigneur de ce que maintenant enfin vous avez fait revivre votre pensée pour moi, quoique vous y ayez bien aussi pensé, mais l’occasion vous manquait;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'non que je parle ayant égard à des privations, car, moi, j’ai appris à être content en moi-même dans les circonstances où je me trouve.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Je sais être abaissé, je sais aussi être dans l’abondance; en toutes choses et à tous égards, je suis enseigné aussi bien à être rassasié qu’à avoir faim, aussi bien à être dans l’abondance qu’à être dans les privations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Je puis toutes choses en celui qui me fortifie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Néanmoins vous avez bien fait de prendre part à mon affliction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Or vous aussi, Philippiens, vous savez qu’au commencement de l’évangile, quand je quittai la Macédoine, aucune assemblée ne me communiqua [rien], pour ce qui est de donner et de recevoir, excepté vous seuls;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'car, même à Thessalonique, une fois et même deux fois, vous m’avez fait un envoi pour mes besoins;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'non que je recherche un don, mais je recherche du fruit qui abonde pour votre compte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Or j’ai amplement de tout, et je suis dans l’abondance; je suis comblé, ayant reçu d’Épaphrodite ce qui [m’a été envoyé] de votre part..., un parfum de bonne odeur, un sacrifice acceptable, agréable à Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'mais mon Dieu suppléera à tous vos besoins selon ses richesses en gloire par le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Or à notre Dieu et Père soit la gloire aux siècles des siècles! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Saluez chaque saint dans le christ Jésus. Les frères qui sont avec moi vous saluent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Tous les saints vous saluent, et principalement ceux qui sont de la maison de César.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Que la grâce du seigneur Jésus Christ soit avec votre esprit! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paul, apôtre du christ Jésus par la volonté de Dieu, et Timothée, le frère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'aux saints et fidèles frères en Christ qui sont à Colasses: Grâce et paix à vous, de la part de Dieu notre Père [et du seigneur Jésus Christ]!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Nous rendons grâces au Dieu et Père de notre seigneur Jésus Christ, priant toujours pour vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'ayant entendu parler de votre foi dans le christ Jésus et de l’amour que vous avez pour tous les saints,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'à cause de l’espérance qui vous est réservée dans les cieux et dont vous avez déjà entendu parler dans la parole de la vérité de l’évangile,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'qui est parvenu jusqu’à vous, comme aussi [il l’est] dans tout le monde, et qui porte du fruit et croît, comme aussi parmi vous, depuis le jour où vous avez entendu et connu la grâce de Dieu en vérité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'comme vous l’avez entendue d’Épaphras, notre bien-aimé compagnon de service, qui est un fidèle serviteur du Christ pour vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'qui nous a aussi fait connaître votre amour dans l’Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'C’est pourquoi nous aussi, depuis le jour où nous en avons entendu parler, nous ne cessons pas de prier et de demander pour vous que vous soyez remplis de la connaissance de sa volonté, en toute sagesse et intelligence spirituelle,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'pour marcher d’une manière digne du Seigneur pour lui plaire à tous égards, portant du fruit en toute bonne œuvre, et croissant par la connaissance de Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'étant fortifiés en toute force, selon la puissance de sa gloire, pour toute patience et constance, avec joie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'rendant grâces au Père qui nous a rendus capables de participer au lot des saints dans la lumière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'qui nous a délivrés du pouvoir des ténèbres, et nous a transportés dans le royaume du Fils de son amour,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'en qui nous avons la rédemption, la rémission des péchés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'qui est [l’]image du Dieu invisible, [le] premier-né de toute [la] création;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'car par lui ont été créées toutes choses, les choses qui sont dans les cieux et les choses qui sont sur la terre, les visibles et les invisibles, soit trônes, ou seigneuries, ou principautés, ou autorités: toutes choses ont été créées par lui et pour lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'et lui est avant toutes choses, et toutes choses subsistent par lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'et il est le chef du corps, de l’assemblée, lui qui est [le] commencement, [le] premier-né d’entre les morts, afin qu’en toutes choses il tienne, lui, la première place;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'car, en lui, toute la plénitude s’est plu à habiter,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'et, par lui, à réconcilier toutes choses avec elle-même, ayant fait la paix par le sang de sa croix, par lui, soit les choses qui sont sur la terre, soit les choses qui sont dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Et vous qui étiez autrefois étrangers et ennemis quant à votre entendement, dans les mauvaises œuvres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'il vous a toutefois maintenant réconciliés dans le corps de sa chair, par la mort, pour vous présenter saints et irréprochables et irrépréhensibles devant lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'si du moins vous demeurez dans la foi, fondés et fermes, et ne vous laissant pas détourner de l’espérance de l’évangile que vous avez entendu, lequel a été prêché dans toute la création qui est sous le ciel, [et] duquel moi, Paul, je suis devenu serviteur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Maintenant, je me réjouis dans les souffrances pour vous, et j’accomplis dans ma chair ce qui reste [encore à souffrir] des afflictions du Christ pour son corps qui est l’assemblée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'de laquelle moi je suis devenu serviteur selon l’administration de Dieu qui m’a été donnée envers vous, pour compléter la parole de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, '[savoir] le mystère qui avait été caché dès les siècles et dès les générations, mais qui a été maintenant manifesté à ses saints,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'auxquels Dieu a voulu donner à connaître quelles sont les richesses de la gloire de ce mystère parmi les nations, c’est-[à-dire] Christ en vous l’espérance de la gloire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'lequel nous annonçons, exhortant tout homme et enseignant tout homme en toute sagesse, afin que nous présentions tout homme parfait en Christ:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'à quoi aussi je travaille, combattant selon son opération qui opère en moi avec puissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Car je veux que vous sachiez quel combat j’ai pour vous et pour ceux qui sont à Laodicée, et tous ceux qui n’ont point vu mon visage en la chair,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'afin que leurs cœurs soient consolés, étant unis ensemble dans l’amour et pour toutes les richesses de la pleine certitude d’intelligence, pour la connaissance du mystère de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'dans lequel sont cachés tous les trésors de la sagesse et de la connaissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Or je dis ceci, afin que personne ne vous séduise par des discours spécieux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'car lors même que je suis absent de corps, toutefois je suis avec vous en esprit, me réjouissant et voyant votre ordre, et la fermeté de votre foi en Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Comme donc vous avez reçu le christ Jésus, le Seigneur, marchez en lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'enracinés et édifiés en lui, et affermis dans la foi, selon que vous avez été enseignés, abondant en elle avec des actions de grâces.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Prenez garde que personne ne fasse de vous sa proie par la philosophie et par de vaines déceptions, selon l’enseignement des hommes, selon les éléments du monde, et non selon Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'car en lui habite toute la plénitude de la déité corporellement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'et vous êtes accomplis en lui, qui est le chef de toute principauté et autorité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'en qui aussi vous avez été circoncis d’une circoncision qui n’a pas été faite de main, dans le dépouillement du corps de la chair par la circoncision du Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'étant ensevelis avec lui dans le baptême, dans lequel aussi vous avez été ressuscités ensemble par la foi en l’opération de Dieu qui l’a ressuscité d’entre les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Et vous, lorsque vous étiez morts dans vos fautes et dans l’incirconcision de votre chair, il vous a vivifiés ensemble avec lui, nous ayant pardonné toutes nos fautes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'ayant effacé l’obligation qui était contre nous, [laquelle consistait] en ordonnances [et] qui nous était contraire, et il l’a ôtée en la clouant à la croix:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'ayant dépouillé les principautés et les autorités, il les a produites en public, triomphant d’elles en la [croix].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Que personne donc ne vous juge en ce qui concerne le manger ou le boire, ou à propos d’un jour de fête ou de nouvelle lune, ou de sabbats,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'qui sont une ombre des choses à venir; mais le corps est du Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Que personne ne vous frustre du prix [du combat], faisant sa volonté propre dans [l’]humilité et dans [le] culte des anges, s’ingérant dans les choses qu’il n’a pas vues, enflé d’un vain orgueil par les pensées de sa chair,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'et ne tenant pas ferme le chef, duquel tout le corps, alimenté et bien uni ensemble par des jointures et des liens, croît de l’accroissement de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Si vous êtes morts avec Christ aux éléments du monde, pourquoi, comme si vous étiez encore en vie dans le monde, établissez-vous des ordonnances,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '– ne prends pas, ne goûte pas, ne touche pas!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '– (choses qui sont toutes destinées à périr par l’usage,) selon les commandements et les enseignements des hommes');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, '(qui ont bien une apparence de sagesse en dévotion volontaire et en humilité, et en ce qu’elles n’épargnent pas le corps, ne [lui] rendant pas un certain honneur), pour la satisfaction de la chair?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Si donc vous avez été ressuscités avec le Christ, cherchez les choses qui sont en haut, où le Christ est assis à la droite de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'pensez aux choses qui sont en haut, non pas à celles qui sont sur la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'car vous êtes morts, et votre vie est cachée avec le Christ en Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Quand le Christ qui est notre vie, sera manifesté, alors vous aussi, vous serez manifestés avec lui en gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Mortifiez donc vos membres qui sont sur la terre, la fornication, l’impureté, les affections déréglées, la mauvaise convoitise, et la cupidité, qui est de l’idolâtrie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'à cause desquelles la colère de Dieu vient sur les fils de la désobéissance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'parmi lesquels vous aussi vous avez marché autrefois, quand vous viviez dans ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Mais maintenant, renoncez, vous aussi, à toutes ces choses: colère, courroux, malice, injures, paroles honteuses venant de votre bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Ne mentez point l’un à l’autre, ayant dépouillé le vieil homme avec ses actions');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'et ayant revêtu le nouvel [homme] qui est renouvelé en connaissance, selon [l’]image de celui qui l’a créé,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'où il n’y a pas Grec et Juif, circoncision et incirconcision, barbare, Scythe, esclave, homme libre; mais où Christ est tout et en tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Revêtez-vous donc, comme des élus de Dieu, saints et bien-aimés, d’entrailles de miséricorde, de bonté, d’humilité, de douceur, de longanimité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'vous supportant l’un l’autre et vous pardonnant les uns aux autres, si l’un a un sujet de plainte contre un autre; comme aussi le Christ vous a pardonné, vous aussi [faites] de même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Et par-dessus toutes ces choses, [revêtez-vous] de l’amour, qui est le lien de la perfection.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Et que la paix du Christ, à laquelle aussi vous avez été appelés en un seul corps, préside dans vos cœurs; et soyez reconnaissants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Que la parole du Christ habite en vous richement, – en toute sagesse vous enseignant et vous exhortant l’un l’autre, par des psaumes, des hymnes, des cantiques spirituels, chantant de vos cœurs à Dieu dans [un esprit de] grâce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Et quelque chose que vous fassiez, en parole ou en œuvre, [faites] tout au nom du seigneur Jésus, rendant grâces par lui à Dieu le Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Femmes, soyez soumises à vos maris, comme il convient dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Maris, aimez vos femmes et ne vous aigrissez pas contre elles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Enfants, obéissez à vos parents en toutes choses, car cela est agréable dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Pères, n’irritez pas vos enfants, afin qu’ils ne soient pas découragés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Esclaves, obéissez en toutes choses à vos maîtres selon la chair, ne servant pas sous leurs yeux seulement, comme voulant plaire aux hommes, mais en simplicité de cœur, craignant le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Quoi que vous fassiez, faites-[le] de cœur, comme pour le Seigneur et non pour les hommes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'sachant que du Seigneur vous recevrez la récompense de l’héritage: vous servez le seigneur Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Car celui qui agit injustement, recevra ce qu’il aura fait injustement; et il n’y a pas d’acception de personnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Maîtres, accordez à vos esclaves ce qui est juste et équitable, sachant que vous aussi vous avez un maître dans les cieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Persévérez dans la prière, veillant en elle avec des actions de grâces;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'priant en même temps aussi pour nous, afin que Dieu nous ouvre une porte pour la parole, pour annoncer le mystère du Christ, [mystère] pour lequel aussi je suis lié,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'afin que je le manifeste comme je dois parler.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Marchez dans la sagesse envers ceux de dehors, saisissant l’occasion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Que votre parole soit toujours dans [un esprit de] grâce, assaisonnée de sel, afin que vous sachiez comment vous devez répondre à chacun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Tychique, le bien-aimé frère et fidèle serviteur et compagnon de service dans le Seigneur, vous fera savoir tout ce qui me concerne:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'je l’ai envoyé vers vous tout exprès, afin qu’il connaisse l’état de vos affaires, et qu’il console vos cœurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'avec Onésime, le fidèle et bien-aimé frère, qui est des vôtres. Ils vous informeront de toutes les choses d’ici.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Aristarque, mon compagnon de captivité, vous salue, et Marc, le neveu de Barnabas, touchant lequel vous avez reçu des ordres (s’il vient vers vous, recevez-le),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'et Jésus appelé Juste, – qui sont de la circoncision. Ceux-ci sont les seuls compagnons d’œuvre pour le royaume de Dieu qui [aussi] m’ont été en consolation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Épaphras qui est des vôtres, esclave du christ Jésus, vous salue, combattant toujours pour vous par des prières, afin que vous demeuriez parfaits et bien assurés dans toute la volonté de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'car je lui rends témoignage qu’il est dans un grand travail [de cœur] pour vous, et pour ceux qui sont à Laodicée, et pour ceux qui sont à Hiérapolis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Luc, le médecin bien-aimé, vous salue, et Démas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Saluez les frères qui sont à Laodicée, et Nymphas, et l’assemblée qui [se réunit] dans sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Et quand la lettre aura été lue parmi vous, faites qu’elle soit lue aussi dans l’assemblée des Laodicéens, et vous aussi lisez celle qui [viendra] de Laodicée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Et dites à Archippe: Prends garde au service que tu as reçu dans le Seigneur, afin que tu l’accomplisses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'La salutation, de la propre main de moi, Paul. – Souvenez-vous de mes liens. La grâce soit avec vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paul, et Silvain, et Timothée, à l’assemblée des Thessaloniciens, en Dieu le Père et dans le seigneur Jésus Christ: Grâce et paix à vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Nous rendons toujours grâces à Dieu pour vous tous, faisant mention de vous dans nos prières,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'nous souvenant sans cesse de votre œuvre de foi, de votre travail d’amour, et de votre patience d’espérance de notre seigneur Jésus Christ, devant notre Dieu et Père,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'sachant, frères aimés de Dieu, votre élection.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Car notre évangile n’est pas venu à vous en parole seulement, mais aussi en puissance, et dans l’Esprit Saint, et dans une grande plénitude d’assurance, ainsi que vous savez quels nous avons été parmi vous pour l’amour de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Et vous êtes devenus nos imitateurs et ceux du Seigneur, ayant reçu la parole, [accompagnée] de grandes tribulations, avec la joie de l’Esprit Saint;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'de sorte que vous êtes devenus des modèles pour tous ceux qui croient dans la Macédoine et dans l’Achaïe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Car la parole du Seigneur a retenti de chez vous, non seulement dans la Macédoine et dans l’Achaïe, mais, en tous lieux, votre foi envers Dieu s’est répandue, de sorte que nous n’avons pas besoin d’en rien dire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Car eux-mêmes racontent de nous quelle entrée nous avons eue auprès de vous, et comment vous vous êtes tournés des idoles vers Dieu, pour servir le Dieu vivant et vrai,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'et pour attendre des cieux son Fils qu’il a ressuscité d’entre les morts, Jésus, qui nous délivre de la colère qui vient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Car vous-mêmes vous savez, frères, que notre entrée au milieu de vous n’a pas été vaine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'mais, après avoir auparavant souffert et avoir été outragés à Philippes, comme vous le savez, nous avons eu toute hardiesse en notre Dieu pour vous annoncer l’évangile de Dieu avec beaucoup de combats.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Car notre exhortation n’a eu pour principe ni séduction, ni impureté, et [nous n’y avons] pas [usé] de ruse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'mais comme nous avons été approuvés de Dieu pour que l’évangile nous soit confié, nous parlons ainsi, non comme plaisant aux hommes, mais à Dieu qui éprouve nos cœurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Car aussi nous n’avons jamais usé de parole de flatterie, comme vous le savez, ni de prétexte de cupidité, Dieu en est témoin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'et nous n’avons pas cherché la gloire qui vient des hommes, ni de votre part, ni de la part des autres, quand nous aurions pu [vous] être à charge comme apôtres de Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'mais nous avons été doux au milieu de vous. Comme une nourrice chérit ses propres enfants,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'ainsi, vous étant tendrement affectionnés, nous aurions été tout disposés à vous communiquer non seulement l’évangile de Dieu, mais aussi nos propres vies, parce que vous nous étiez devenus fort chers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Car vous vous souvenez, frères, de notre peine et de notre labeur; c’est en travaillant nuit et jour pour n’être à charge à aucun de vous, que nous vous avons prêché l’évangile de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vous-mêmes, vous êtes témoins, et Dieu aussi, combien nous nous sommes conduits saintement, et justement, et irréprochablement envers vous qui croyez,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'ainsi que vous savez comment [nous avons exhorté] chacun de vous, comme un père ses propres enfants,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'vous exhortant, et vous consolant, et rendant témoignage, pour que vous marchiez d’une manière digne de Dieu qui vous appelle à son propre royaume et à sa propre gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Et c’est pourquoi aussi nous, nous rendons sans cesse grâces à Dieu de ce que, ayant reçu de nous la parole de la prédication [qui est] de Dieu, vous avez accepté, non la parole des hommes, mais (ainsi qu’elle l’est véritablement) la parole de Dieu, laquelle aussi opère en vous qui croyez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Car vous, frères, vous êtes devenus les imitateurs des assemblées de Dieu qui sont dans la Judée dans le christ Jésus; car vous aussi, vous avez souffert de la part de vos propres compatriotes les mêmes choses qu’elles aussi [ont souffertes] de la part des Juifs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'qui ont mis à mort et le seigneur Jésus et les prophètes, et qui nous ont chassés par la persécution, et qui ne plaisent pas à Dieu, et qui sont opposés à tous les hommes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, '– nous empêchant de parler aux nations afin qu’elles soient sauvées, pour combler toujours la mesure de leurs péchés; mais la colère est venue sur eux au dernier terme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Or pour nous, frères, ayant été séparés de vous pour un temps, de visage et non de cœur, nous avons d’autant plus, avec un fort grand désir, cherché à voir votre visage;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'c’est pourquoi nous avons voulu aller vers vous, moi Paul, et une fois et deux fois, et Satan nous en a empêchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Car quelle est notre espérance, ou notre joie, ou la couronne dont nous nous glorifions? N’est-ce pas bien vous devant notre seigneur Jésus, à sa venue?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Car vous, vous êtes notre gloire et notre joie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'C’est pourquoi, n’y tenant plus, nous avons trouvé bon d’être laissés seuls à Athènes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'et nous avons envoyé Timothée, notre frère et compagnon d’œuvre sous Dieu dans l’évangile du Christ, pour vous affermir et vous encourager touchant votre foi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'afin que nul ne soit ébranlé dans ces tribulations; car vous savez vous-mêmes que nous sommes destinés à cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Car aussi, quand nous étions auprès de vous, nous vous avons dit d’avance que nous aurions à subir des tribulations, comme cela est aussi arrivé, et comme vous le savez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'C’est pourquoi moi aussi, n’y tenant plus, j’ai envoyé afin de connaître [ce qui en était de] votre foi, de peur que le tentateur ne vous ait tentés, et que notre travail ne soit rendu vain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Mais Timothée venant d’arriver de chez vous auprès de nous, et nous ayant apporté les bonnes nouvelles de votre foi et de votre amour, et [nous ayant dit] que vous gardez toujours un bon souvenir de nous, désirant ardemment de nous voir, comme nous aussi nous désirons vous voir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, '– c’est pourquoi, frères, nous avons été consolés à votre sujet par votre foi, dans toute notre nécessité et dans notre tribulation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'car maintenant nous vivons, si vous tenez fermes dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Car comment pourrions-nous rendre à Dieu assez d’actions de grâces pour vous, pour toute la joie avec laquelle nous nous réjouissons à cause de vous devant notre Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'priant nuit et jour très instamment, pour que nous voyions votre visage et que nous suppléions à ce qui manque à votre foi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Or que notre Dieu et Père lui-même, et notre seigneur Jésus, nous fraie le chemin auprès de vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'et quant à vous, que le Seigneur vous fasse abonder et surabonder en amour les uns envers les autres et envers tous, comme nous aussi envers vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'pour affermir vos cœurs sans reproche en sainteté devant notre Dieu et Père en la venue de notre seigneur Jésus avec tous ses saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Au reste donc, frères, nous vous prions et nous vous exhortons par le seigneur Jésus, pour que, comme vous avez reçu de nous de quelle manière il faut que vous marchiez et plaisiez à Dieu, comme aussi vous marchez, vous y abondiez de plus en plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Car vous savez quels commandements nous vous avons donnés par le seigneur Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Car c’est ici la volonté de Dieu, votre sainteté, que vous vous absteniez de la fornication,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'que chacun de vous sache posséder son propre vase en sainteté et en honneur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'non dans la passion de la convoitise comme font les nations aussi qui ne connaissent pas Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'que personne ne circonvienne son frère ni ne lui fasse tort dans l’affaire, parce que le Seigneur est le vengeur de toutes ces choses, comme aussi nous vous l’avons dit précédemment et affirmé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Car Dieu ne nous a pas appelés à l’impureté, mais dans la sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'C’est pourquoi celui qui méprise, ne méprise pas l’homme, mais Dieu, qui vous a aussi donné son Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Or, quant à l’amour fraternel, vous n’avez pas besoin que je vous en écrive; car vous-mêmes, vous êtes enseignés de Dieu à vous aimer l’un l’autre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'car aussi c’est ce que vous faites à l’égard de tous les frères qui sont dans toute la Macédoine; mais nous vous exhortons, frères, à y abonder de plus en plus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'et à vous appliquer à vivre paisiblement, à faire vos propres affaires et à travailler de vos propres mains, ainsi que nous vous l’avons ordonné,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'afin que vous marchiez honorablement envers ceux de dehors et que vous n’ayez besoin de personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Or nous ne voulons pas, frères, que vous soyez dans l’ignorance à l’égard de ceux qui dorment, afin que vous ne soyez pas affligés comme les autres qui n’ont pas d’espérance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Car si nous croyons que Jésus mourut et qu’il est ressuscité, de même aussi, avec lui, Dieu amènera ceux qui se sont endormis par Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, '(Car nous vous disons ceci par la parole du Seigneur: que nous, les vivants, qui demeurons jusqu’à la venue du Seigneur, nous ne devancerons aucunement ceux qui se sont endormis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Car le Seigneur lui-même, avec un cri de commandement, avec une voix d’archange, et avec [la] trompette de Dieu, descendra du ciel; et les morts en Christ ressusciteront premièrement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'puis nous, les vivants qui demeurons, nous serons ravis ensemble avec eux dans les nuées à la rencontre du Seigneur, en l’air; et ainsi nous serons toujours avec le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Consolez-vous donc l’un l’autre par ces paroles.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Mais pour ce qui est des temps et des saisons, frères, vous n’avez pas besoin qu’on vous en écrive;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'car vous savez vous-mêmes parfaitement que le jour du Seigneur vient comme un voleur dans la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Quand ils diront: “Paix et sûreté”, alors une subite destruction viendra sur eux, comme les douleurs sur celle qui est enceinte, et ils n’échapperont point.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Mais vous, frères, vous n’êtes pas dans les ténèbres, en sorte que le jour vous surprenne comme un voleur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'car vous êtes tous des fils de la lumière et des fils du jour; nous ne sommes pas de la nuit ni des ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Ainsi donc ne dormons pas comme les autres, mais veillons et soyons sobres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'car ceux qui dorment, dorment la nuit, et ceux qui s’enivrent, s’enivrent la nuit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'mais nous qui sommes du jour, soyons sobres, revêtant la cuirasse de la foi et de l’amour, et, pour casque, l’espérance du salut;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'car Dieu ne nous a pas destinés à la colère, mais à l’acquisition du salut par notre seigneur Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'qui est mort pour nous, afin que, soit que nous veillions, soit que nous dormions, nous vivions ensemble avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'C’est pourquoi exhortez-vous l’un l’autre et édifiez-vous l’un l’autre, chacun en particulier, comme aussi vous le faites.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Or nous vous prions, frères, de connaître ceux qui travaillent parmi vous, et qui sont à la tête parmi vous dans le Seigneur, et qui vous avertissent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'et de les estimer très haut en amour à cause de leur œuvre. Soyez en paix entre vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Or nous vous exhortons, frères: avertissez les déréglés, consolez ceux qui sont découragés, venez en aide aux faibles, usez de patience envers tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Prenez garde que nul ne rende à personne mal pour mal; mais poursuivez toujours ce qui est bon, et entre vous, et à l’égard de tous les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Réjouissez-vous toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Priez sans cesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'En toutes choses rendez grâces, car telle est la volonté de Dieu dans le christ Jésus à votre égard.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'N’éteignez pas l’Esprit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'ne méprisez pas les prophéties,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'mais éprouvez toutes choses; retenez ce qui est bon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Abstenez-vous de toute forme de mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Or le Dieu de paix lui-même vous sanctifie entièrement; et que votre esprit, et votre âme, et votre corps tout entiers, soient conservés sans reproche en la venue de notre seigneur Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Celui qui vous appelle est fidèle, qui aussi le fera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Frères, priez pour nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Saluez tous les frères par un saint baiser.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Je vous adjure par le Seigneur que la lettre soit lue à tous les saints frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Que la grâce de notre seigneur Jésus Christ soit avec vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paul, et Silvain, et Timothée, à l’assemblée des Thessaloniciens, en Dieu notre Père et dans le seigneur Jésus Christ:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Grâce et paix à vous, de la part de Dieu notre Père et du seigneur Jésus Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Nous devons toujours rendre grâces à Dieu pour vous, frères, comme il est juste, parce que votre foi augmente beaucoup et que l’amour de chacun de vous tous, l’un pour l’autre, abonde,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'en sorte que nous-mêmes nous nous glorifions de vous dans les assemblées de Dieu au sujet de votre patience et de votre foi dans toutes vos persécutions et dans les tribulations que vous supportez,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, '[lesquelles sont] une démonstration du juste jugement de Dieu, pour que vous soyez estimés dignes du royaume de Dieu pour lequel aussi vous souffrez;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'si du moins c’est une chose juste devant Dieu que de rendre la tribulation à ceux qui vous font subir la tribulation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'et [que de vous donner], à vous qui subissez la tribulation, du repos avec nous dans la révélation du seigneur Jésus du ciel avec les anges de sa puissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'en flammes de feu, exerçant la vengeance contre ceux qui ne connaissent pas Dieu, et contre ceux qui n’obéissent pas à l’évangile de notre seigneur Jésus Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'lesquels subiront le châtiment d’une destruction éternelle de devant la présence du Seigneur et de devant la gloire de sa force,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'quand il viendra pour être, dans ce jour-là, glorifié dans ses saints et admiré dans tous ceux qui auront cru, car notre témoignage envers vous a été cru.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'C’est pour cela que nous prions aussi toujours pour vous, que notre Dieu vous juge dignes de l’appel, et qu’il accomplisse tout le bon plaisir de sa bonté et l’œuvre de la foi en puissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'en sorte que le nom de notre seigneur Jésus [Christ] soit glorifié en vous, et vous en lui, selon la grâce de notre Dieu et du seigneur Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Or nous vous prions, frères, par la venue de notre seigneur Jésus Christ et par notre rassemblement auprès de lui,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'de ne pas vous laisser promptement bouleverser dans vos pensées, ni troubler, ni par esprit, ni par parole, ni par lettre, comme [si c’était] par nous, comme si le jour du Seigneur était là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Que personne ne vous séduise en aucune manière, car [ce jour-là ne viendra pas] que l’apostasie ne soit arrivée auparavant et que l’homme de péché n’ait été révélé, le fils de perdition,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'qui s’oppose et s’élève contre tout ce qui est appelé Dieu ou qui est un objet de vénération, en sorte que lui-même s’assiéra au temple de Dieu, se présentant lui-même comme étant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Ne vous souvenez-vous pas que, quand j’étais encore auprès de vous, je vous disais ces choses?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Et maintenant vous savez ce qui retient pour qu’il soit révélé en son propre temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Car le mystère d’iniquité opère déjà; seulement celui qui retient maintenant, [le fera] jusqu’à ce qu’il soit loin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Et alors sera révélé l’inique, que le seigneur Jésus consumera par le souffle de sa bouche et qu’il anéantira par l’apparition de sa venue;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'duquel la venue est selon l’opération de Satan, en toute sorte de miracles et signes et prodiges de mensonge,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'et en toute séduction d’injustice pour ceux qui périssent, parce qu’ils n’ont pas reçu l’amour de la vérité pour être sauvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Et à cause de cela, Dieu leur envoie une énergie d’erreur pour qu’ils croient au mensonge,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'afin que tous ceux-là soient jugés qui n’ont pas cru la vérité, mais qui ont pris plaisir à l’injustice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Mais nous, nous devons toujours rendre grâces à Dieu pour vous, frères aimés du Seigneur, de ce que Dieu vous a choisis dès le commencement pour le salut, dans la sainteté de l’Esprit et la foi de la vérité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'à quoi il vous a appelés par notre évangile, pour que vous obteniez la gloire de notre seigneur Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Ainsi donc, frères, demeurez fermes, et retenez les enseignements que vous avez appris soit par parole, soit par notre lettre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Or notre seigneur Jésus Christ lui-même, et notre Dieu et Père, qui nous a aimés et [nous] a donné une consolation éternelle et une bonne espérance par grâce,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'veuille consoler vos cœurs et [vous] affermir en toute bonne œuvre et en toute bonne parole.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Au reste, frères, priez pour nous, afin que la parole du Seigneur coure et qu’elle soit glorifiée, comme elle l’est aussi chez vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'et que nous soyons délivrés des hommes fâcheux et méchants, car la foi n’est pas de tous:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'mais le Seigneur est fidèle, qui vous affermira et vous gardera du méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Mais nous avons confiance dans le Seigneur à votre égard, que vous faites et que vous ferez ce que nous avons commandé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Or que le Seigneur incline vos cœurs à l’amour de Dieu et à la patience du Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Mais nous vous enjoignons, frères, au nom de notre seigneur Jésus Christ, de vous retirer de tout frère qui marche dans le désordre, et non pas selon l’enseignement qu’il a reçu de nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Car vous savez vous-mêmes comment il faut que vous nous imitiez; car nous n’avons pas marché dans le désordre au milieu de vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'ni n’avons mangé du pain chez personne gratuitement, mais dans la peine et le labeur, travaillant nuit et jour pour n’être à charge à aucun de vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'non que nous n’en ayons pas le droit, mais afin de nous donner nous-mêmes à vous pour modèle, pour que vous nous imitiez.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Car aussi, quand nous étions auprès de vous, nous vous avons enjoint ceci: que si quelqu’un ne veut pas travailler, qu’il ne mange pas non plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Car nous apprenons qu’il y en a quelques-uns parmi vous qui marchent dans le désordre, ne travaillant pas du tout, mais se mêlant de tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Mais nous enjoignons à ceux qui sont tels, et nous les exhortons dans le seigneur Jésus Christ, de manger leur propre pain en travaillant paisiblement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Mais vous, frères, ne vous lassez pas en faisant le bien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Et si quelqu’un n’obéit pas à notre parole [qui vous est adressée] dans cette lettre, notez-le et n’ayez pas de commerce avec lui, afin qu’il en ait de la honte;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'et ne le tenez pas pour un ennemi, mais avertissez-le comme un frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Or le Seigneur de paix lui-même vous donne toujours la paix en toute manière. Le Seigneur soit avec vous tous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'La salutation, de la propre main de moi, Paul; ce qui est le signe dans chaque lettre: ainsi j’écris.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Que la grâce de notre seigneur Jésus Christ soit avec vous tous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paul, apôtre de Jésus Christ, selon le commandement de Dieu notre Sauveur et du christ Jésus notre espérance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'à Timothée, [mon] véritable enfant dans la foi: Grâce, miséricorde, paix, de la part de Dieu le Père et du christ Jésus notre Seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Comme je t’ai prié de rester à Éphèse lorsque j’allais en Macédoine, afin que tu ordonnes à certaines personnes de ne pas enseigner des doctrines étrangères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'et de ne pas s’attacher aux fables et aux généalogies interminables, qui produisent des disputes plutôt que l’administration de Dieu, qui est par la foi...');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Or la fin de l’ordonnance, c’est l’amour qui procède d’un cœur pur et d’une bonne conscience et d’une foi sincère,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'desquels quelques-uns s’étant écartés, se sont détournés à un vain babil,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'voulant être docteurs de la loi, n’entendant ni ce qu’ils disent, ni ce sur quoi ils insistent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Mais nous savons que la loi est bonne, si quelqu’un en use légitimement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'sachant ceci, que [la] loi n’est pas pour le juste, mais pour les iniques et les insubordonnés, pour les impies et les pécheurs, pour les gens sans piété et les profanes, pour les batteurs de père et les batteurs de mère, pour les homicides,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'pour les fornicateurs, pour ceux qui abusent d’eux-mêmes avec des hommes, pour les voleurs d’hommes, les menteurs, les parjures, et s’il y a quelque autre chose qui soit opposée à la saine doctrine,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'suivant l’évangile de la gloire du Dieu bienheureux, qui m’a été confié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Et je rends grâces au christ Jésus, notre Seigneur, qui m’a fortifié, de ce qu’il m’a estimé fidèle, m’ayant établi dans le service,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'moi qui auparavant étais un blasphémateur, et un persécuteur, et un outrageux; mais miséricorde m’a été faite, parce que j’ai agi dans l’ignorance, dans l’incrédulité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'et la grâce de notre Seigneur a surabondé avec la foi et l’amour qui est dans le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Cette parole est certaine et digne de toute acceptation, que le christ Jésus est venu dans le monde pour sauver les pécheurs, dont moi je suis le premier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Mais miséricorde m’a été faite, à cause de ceci, [savoir] afin qu’en moi, le premier, Jésus Christ montre toute sa patience, afin que je sois un exemple de ceux qui viendront à croire en lui pour la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Or, qu’au roi des siècles, l’incorruptible, invisible, seul Dieu, soit honneur et gloire aux siècles des siècles! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Je te confie cette ordonnance, [mon] enfant Timothée, selon les prophéties qui ont été précédemment faites à ton sujet, afin que par elles tu combattes le bon combat,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'gardant la foi et une bonne conscience, que quelques-uns ayant rejetée, ils ont fait naufrage quant à la foi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'du nombre desquels sont Hyménée et Alexandre, que j’ai livrés à Satan, afin qu’ils apprennent à ne pas blasphémer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'J’exhorte donc, avant toutes choses, à faire des supplications, des prières, des intercessions, des actions de grâces pour tous les hommes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, '– pour les rois et pour tous ceux qui sont haut placés, afin que nous puissions mener une vie paisible et tranquille, en toute piété et honnêteté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'car cela est bon et agréable devant notre Dieu sauveur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'qui veut que tous les hommes soient sauvés et viennent à la connaissance de la vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'car Dieu est un, et le médiateur entre Dieu et les hommes est un, [l’]homme Christ Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'qui s’est donné lui-même en rançon pour tous, témoignage [qui devait être rendu] en son propre temps,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'pour lequel moi, j’ai été établi prédicateur et apôtre (je dis la vérité, je ne mens pas), docteur des nations dans la foi et dans la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Je veux donc que les hommes prient en tout lieu, élevant des mains saintes, sans colère et sans raisonnement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'De même aussi, que les femmes se parent d’un costume décent, avec pudeur et modestie, non pas de tresses et d’or, ou de perles, ou d’habillements somptueux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'mais par de bonnes œuvres, ce qui sied à des femmes qui font profession de servir Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Que la femme apprenne dans le silence, en toute soumission;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'mais je ne permets pas à la femme d’enseigner ni d’user d’autorité sur l’homme; mais elle doit demeurer dans le silence;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'car Adam a été formé le premier, et puis Ève;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'et Adam n’a pas été trompé; mais la femme, ayant été trompée, est tombée dans la transgression;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'mais elle sera sauvée en enfantant, si elles persévèrent dans la foi et l’amour et la sainteté, avec modestie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Cette parole est certaine, que si quelqu’un aspire à la surveillance, il désire une œuvre bonne:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'il faut donc que le surveillant soit irrépréhensible, mari d’une seule femme, sobre, sage, honorable, hospitalier, propre à enseigner,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'non adonné au vin, non batteur, mais doux, non querelleur, n’aimant pas l’argent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'conduisant bien sa propre maison, tenant ses enfants soumis en toute gravité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(Mais si quelqu’un ne sait pas conduire sa propre maison, comment prendra-t-il soin de l’assemblée de Dieu?)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Qu’il ne soit pas nouvellement converti, de peur qu’étant enflé d’orgueil, il ne tombe dans la faute du diable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Or il faut aussi qu’il ait un bon témoignage de ceux de dehors, afin qu’il ne tombe pas dans l’opprobre et dans le piège du diable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'De même, [il faut] que les serviteurs soient graves, non doubles en paroles, non adonnés à beaucoup de vin, non avides d’un gain honteux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'gardant le mystère de la foi dans une conscience pure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'et que ceux-ci aussi soient premièrement mis à l’épreuve; ensuite, qu’ils servent, étant trouvés irréprochables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'De même, que les femmes soient graves, non médisantes, sobres, fidèles en toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Que les serviteurs soient maris d’une seule femme, conduisant bien leurs enfants et leurs propres maisons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'car ceux qui ont bien servi acquièrent un bon degré pour eux et une grande hardiesse dans la foi qui est dans le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Je t’écris ces choses, espérant me rendre bientôt auprès de toi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'mais, si je tarde, – afin que tu saches comment il faut se conduire dans la maison de Dieu, qui est l’assemblée du Dieu vivant, la colonne et le soutien de la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Et, sans contredit, le mystère de la piété est grand: – Dieu a été manifesté en chair, a été justifié en Esprit, a été vu des anges, a été prêché parmi les nations, a été cru au monde, a été élevé dans la gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Or l’Esprit dit expressément qu’aux derniers temps quelques-uns apostasieront de la foi, s’attachant à des esprits séducteurs et à des enseignements de démons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'disant des mensonges par hypocrisie, ayant leur propre conscience cautérisée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'défendant de se marier, [prescrivant] de s’abstenir des viandes que Dieu a créées pour être prises avec action de grâces par les fidèles et par ceux qui connaissent la vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'car toute créature de Dieu est bonne et il n’y en a aucune qui soit à rejeter, étant prise avec action de grâces,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'car elle est sanctifiée par la parole de Dieu et par la prière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'En proposant ces choses aux frères, tu seras un bon serviteur du christ Jésus, nourri dans les paroles de la foi et de la bonne doctrine que tu as pleinement comprise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Mais rejette les fables profanes et de vieilles femmes, et exerce-toi toi-même à la piété:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'car l’exercice corporel est utile à peu de chose, mais la piété est utile à toutes choses, ayant la promesse de la vie présente et de la vie qui est à venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Cette parole est certaine et digne de toute acceptation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'car si nous travaillons et sommes dans l’opprobre, c’est parce que nous espérons dans le Dieu vivant qui est [le] conservateur de tous les hommes, spécialement des fidèles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Ordonne ces choses et enseigne-les.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Que personne ne méprise ta jeunesse; mais sois le modèle des fidèles, en parole, en conduite, en amour, en foi, en pureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Jusqu’à ce que je vienne, attache-toi à la lecture, à l’exhortation, à l’enseignement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Ne néglige pas le don de grâce qui est en toi, qui t’a été donné par prophétie avec l’imposition des mains du corps des anciens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Occupe-toi de ces choses; sois-y tout entier, afin que tes progrès soient évidents à tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Sois attentif à toi-même et à l’enseignement; persévère dans ces choses, car en faisant ainsi tu te sauveras toi-même et ceux qui t’écoutent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Ne reprends pas rudement l’homme âgé, mais exhorte-le comme un père, les jeunes gens comme des frères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'les femmes âgées comme des mères, les jeunes comme des sœurs, en toute pureté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Honore les veuves qui sont vraiment veuves;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'mais si quelque veuve a des enfants ou des descendants, qu’ils apprennent premièrement à montrer leur piété envers leur propre maison et à rendre à ceux dont ils descendent les soins qu’ils en ont reçus, car cela est agréable devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Or celle qui est vraiment veuve et qui est laissée seule, a mis son espérance en Dieu, et persévère dans les supplications et dans les prières nuit et jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Mais celle qui vit dans le plaisir est morte en vivant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Ordonne aussi ces choses, afin qu’elles soient irrépréhensibles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Mais si quelqu’un n’a pas soin des siens et spécialement de ceux de sa famille, il a renié la foi et il est pire qu’un incrédule.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Que la veuve soit inscrite, n’ayant pas moins de 60 ans, [ayant été] femme d’un seul mari,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'ayant le témoignage [d’avoir marché] dans les bonnes œuvres, – si elle a élevé des enfants, si elle a logé des étrangers, si elle a lavé les pieds des saints, si elle a secouru ceux qui sont dans la tribulation, si elle s’est appliquée à toute bonne œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Mais refuse les veuves qui sont jeunes; car, quand elles s’élèvent contre le Christ en s’abandonnant à leurs désirs, elles veulent se marier,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'étant en faute parce qu’elles ont rejeté leur première foi;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'et en même temps elles apprennent aussi à être oisives, allant de maison en maison; et non seulement oisives, mais aussi causeuses, se mêlant de tout, disant des choses qui ne conviennent pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Je veux donc que les jeunes se marient, aient des enfants, gouvernent leur maison, ne donnent aucune occasion à l’adversaire à cause des mauvais propos;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'car déjà quelques-unes se sont détournées après Satan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Si un fidèle ou une fidèle a des veuves, qu’il les assiste et que l’assemblée n’en soit pas chargée, afin qu’elle vienne au secours de celles qui sont vraiment veuves.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Que les anciens qui président dûment soient estimés dignes d’un double honneur, spécialement ceux qui travaillent dans la parole et dans l’enseignement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'car l’écriture dit: « Tu n’emmuselleras pas le bœuf qui foule le grain », et: « L’ouvrier est digne de son salaire ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Ne reçois pas d’accusation contre un ancien, si ce n’est quand il y a deux ou trois témoins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Ceux qui pèchent, convaincs-les devant tous, afin que les autres aussi aient de la crainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Je t’adjure devant Dieu et le christ Jésus et les anges élus, que tu gardes ces choses, sans préférence, ne faisant rien avec partialité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'N’impose les mains précipitamment à personne et ne participe pas aux péchés d’autrui; garde-toi pur toi-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Ne bois plus de l’eau seulement, mais use d’un peu de vin, à cause de ton estomac et de tes fréquentes indispositions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Les péchés de quelques hommes sont manifestes d’avance et vont devant pour le jugement; mais ceux d’autres [hommes] aussi les suivent après.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'De même aussi les bonnes œuvres sont manifestes d’avance, et celles qui sont autrement ne peuvent être cachées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Que tous les esclaves qui sont sous le joug estiment leurs propres maîtres dignes de tout honneur, afin que le nom de Dieu et la doctrine ne soient pas blasphémés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'et que ceux qui ont des maîtres croyants ne les méprisent pas parce qu’ils sont frères, mais qu’ils les servent d’autant plus que ceux qui profitent de leur bon et prompt service sont des fidèles et des bien-aimés. Enseigne ces choses et exhorte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Si quelqu’un enseigne autrement et ne se range pas à de saines paroles, [savoir] à celles de notre seigneur Jésus Christ et à la doctrine qui est selon la piété,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'il est enflé d’orgueil, ne sachant rien, mais ayant la maladie des questions et des disputes de mots, d’où naissent l’envie, les querelles, les paroles injurieuses, les mauvais soupçons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'les vaines disputes d’hommes corrompus dans leur entendement et privés de la vérité, qui estiment que la piété est une source de gain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Or la piété avec le contentement est un grand gain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Car nous n’avons rien apporté dans le monde, et il est évident que nous n’en pouvons rien emporter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Mais ayant la nourriture et de quoi nous couvrir, nous serons satisfaits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Or ceux qui veulent devenir riches tombent dans la tentation et dans un piège, et dans plusieurs désirs insensés et pernicieux qui plongent les hommes dans la ruine et la perdition;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'car c’est une racine de toutes sortes de maux que l’amour de l’argent: ce que quelques-uns ayant ambitionné, ils se sont égarés de la foi et se sont transpercés eux-mêmes de beaucoup de douleurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Mais toi, ô homme de Dieu, fuis ces choses, et poursuis la justice, la piété, la foi, l’amour, la patience, la douceur d’esprit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'combats le bon combat de la foi; saisis la vie éternelle, pour laquelle tu as été appelé et tu as fait la belle confession devant beaucoup de témoins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Je t’ordonne devant Dieu qui appelle toutes choses à l’existence, et devant le christ Jésus qui a fait la belle confession devant Ponce Pilate,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'que tu gardes ce commandement, sans tache, irrépréhensible, jusqu’à l’apparition de notre seigneur Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'laquelle le bienheureux et seul Souverain, le roi de ceux qui règnent et le seigneur de ceux qui dominent, montrera au temps propre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'lui qui seul possède l’immortalité, qui habite la lumière inaccessible, lequel aucun des hommes n’a vu, ni ne peut voir, – auquel soit honneur et force éternelle! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Ordonne à ceux qui sont riches dans le présent siècle, qu’ils ne soient pas hautains et qu’ils ne mettent pas leur confiance dans l’incertitude des richesses, mais dans le Dieu qui nous donne toutes choses richement pour en jouir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'qu’ils fassent du bien; qu’ils soient riches en bonnes œuvres; qu’ils soient prompts à donner, libéraux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 's’amassant comme trésor un bon fondement pour l’avenir, afin qu’ils saisissent ce qui est vraiment la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Ô Timothée, garde ce qui t’a été confié, fuyant les discours vains et profanes et l’opposition de la connaissance faussement ainsi nommée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'de laquelle quelques-uns faisant profession, se sont écartés de la foi. Que la grâce soit avec toi!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paul, apôtre de Jésus Christ par la volonté de Dieu, selon la promesse de la vie qui est dans le christ Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'à Timothée, [mon] enfant bien-aimé: Grâce, miséricorde, paix, de la part de Dieu le Père et du christ Jésus notre Seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Je suis reconnaissant envers Dieu, que je sers dès mes ancêtres avec une conscience pure, de ce que je me souviens si constamment de toi dans mes supplications, nuit et jour');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, '(désirant ardemment de te voir, me souvenant de tes larmes, afin que je sois rempli de joie,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'me rappelant la foi sincère qui [est] en toi, et qui a d’abord habité dans ta grand-mère Loïs et dans ta mère Eunice, et, j’en suis persuadé, en toi aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'C’est pourquoi je te rappelle de ranimer le don de grâce de Dieu qui est en toi par l’imposition de mes mains;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'car Dieu ne nous a pas donné un esprit de crainte, mais de puissance, et d’amour, et de conseil.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'N’aie donc pas honte du témoignage de notre Seigneur, ni de moi son prisonnier, mais prends part aux souffrances de l’évangile, selon la puissance de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'qui nous a sauvés et nous a appelés d’un saint appel, non selon nos œuvres, mais selon son propre dessein, et sa propre grâce qui nous a été donnée dans le christ Jésus avant les temps des siècles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'mais qui a été manifestée maintenant par l’apparition de notre Sauveur Jésus Christ, qui a annulé la mort et a fait luire la vie et l’incorruptibilité par l’évangile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'pour lequel moi j’ai été établi prédicateur et apôtre et docteur des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'C’est pourquoi aussi je souffre ces choses; mais je n’ai pas de honte, car je sais qui j’ai cru, et je suis persuadé qu’il a la puissance de garder ce que je lui ai confié, jusqu’à ce jour-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Aie un modèle des saines paroles que tu as entendues de moi, dans la foi et l’amour qui est dans le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Garde le bon dépôt par l’Esprit Saint qui habite en nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Tu sais ceci, que tous ceux qui sont en Asie, du nombre desquels sont Phygelle et Hermogène, se sont détournés de moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Le Seigneur fasse miséricorde à la maison d’Onésiphore, car il m’a souvent consolé et n’a point eu honte de ma chaîne,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'mais, quand il a été à Rome, il m’a cherché très soigneusement et il m’a trouvé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Le Seigneur lui fasse trouver miséricorde de la part du Seigneur dans ce jour-là; et tu sais mieux [que personne] combien de services il a rendus dans Éphèse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Toi donc, mon enfant, fortifie-toi dans la grâce qui est dans le christ Jésus;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'et les choses que tu as entendues de moi devant plusieurs témoins, confie-les à des hommes fidèles qui soient capables d’instruire aussi les autres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Prends ta part des souffrances comme un bon soldat de Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Nul homme qui va à la guerre ne s’embarrasse dans les affaires de la vie, afin qu’il plaise à celui qui l’a enrôlé pour la guerre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'de même si quelqu’un combat dans la lice, il n’est pas couronné s’il n’a pas combattu selon les lois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'il faut que le laboureur travaille premièrement, pour qu’il jouisse des fruits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Considère ce que je dis; car le Seigneur te donnera de l’intelligence en toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Souviens-toi de Jésus Christ, ressuscité d’entre les morts, de la semence de David, selon mon évangile,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'dans lequel j’endure des souffrances jusqu’à être lié de chaînes comme un malfaiteur; toutefois la parole de Dieu n’est pas liée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'C’est pourquoi j’endure tout pour l’amour des élus, afin qu’eux aussi obtiennent le salut qui est dans le christ Jésus, avec la gloire éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Cette parole est certaine; car si nous sommes morts avec lui, nous vivrons aussi avec lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'si nous souffrons, nous régnerons aussi avec lui; si nous le renions, lui aussi nous reniera;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'si nous sommes incrédules, lui demeure fidèle, car il ne peut se renier lui-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Remets ces choses en mémoire, protestant devant le Seigneur qu’on n’ait pas de disputes de mots, [ce qui est] sans aucun profit, [et] pour la subversion des auditeurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Étudie-toi à te présenter approuvé à Dieu, ouvrier qui n’a pas à avoir honte, exposant justement la parole de la vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'mais évite les discours vains et profanes, car [ceux qui s’y livrent] iront plus avant dans l’impiété,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'et leur parole rongera comme une gangrène, desquels sont Hyménée et Philète');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'qui se sont écartés de la vérité, disant que la résurrection a déjà eu lieu, et qui renversent la foi de quelques-uns.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Toutefois le solide fondement de Dieu demeure, ayant ce sceau: Le Seigneur connaît ceux qui sont siens, et: Qu’il se retire de l’iniquité, quiconque prononce le nom du Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Or, dans une grande maison, il n’y a pas seulement des vases d’or et d’argent, mais aussi de bois et de terre; et les uns à honneur, les autres à déshonneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Si donc quelqu’un se purifie de ceux-ci, il sera un vase à honneur, sanctifié, utile au maître, préparé pour toute bonne œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Mais fuis les convoitises de la jeunesse, et poursuis la justice, la foi, l’amour, la paix, avec ceux qui invoquent le Seigneur d’un cœur pur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'mais évite les questions folles et insensées, sachant qu’elles engendrent des contestations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Et il ne faut pas que l’esclave du Seigneur conteste, mais qu’il soit doux envers tous, propre à enseigner, ayant du support;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'enseignant avec douceur les opposants, [attendant] si Dieu, peut-être, ne leur donnera pas la repentance pour reconnaître la vérité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'et s’ils ne se réveilleront pas du piège du diable, par qui ils ont été pris, pour faire sa volonté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Or sache ceci, que dans les derniers jours il surviendra des temps fâcheux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'car les hommes seront égoïstes, avares, vantards, hautains, outrageux, désobéissants à leurs parents, ingrats, sans piété,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'sans affection naturelle, implacables, calomniateurs, incontinents, cruels, n’aimant pas le bien,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'traîtres, téméraires, enflés d’orgueil, amis des voluptés plutôt qu’amis de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'ayant la forme de la piété, mais en ayant renié la puissance. Or détourne-toi de telles gens.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Car d’entre eux sont ceux qui s’introduisent dans les maisons et qui mènent captives des femmelettes chargées de péchés, entraînées par des convoitises diverses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'qui apprennent toujours et qui ne peuvent jamais parvenir à la connaissance de la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Or de la même manière dont Jannès et Jambrès résistèrent à Moïse, ainsi aussi ceux-ci résistent à la vérité, hommes corrompus dans leur entendement, réprouvés quant à la foi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'mais ils n’iront pas plus avant, car leur folie sera manifeste pour tous, comme a été celle de ceux-là aussi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Mais toi, tu as pleinement compris ma doctrine, ma conduite, mon but constant, ma foi, mon support, mon amour, ma patience,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'mes persécutions, mes souffrances, telles qu’elles me sont arrivées à Antioche, à Iconium et à Lystre, quelles persécutions j’ai endurées; – et le Seigneur m’a délivré de toutes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Et tous ceux aussi qui veulent vivre pieusement dans le christ Jésus, seront persécutés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'mais les hommes méchants et les imposteurs iront de mal en pis, séduisant et étant séduits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Mais toi, demeure dans les choses que tu as apprises et dont tu as été pleinement convaincu, sachant de qui tu les as apprises,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'et que, dès l’enfance, tu connais les saintes lettres, qui peuvent te rendre sage à salut par la foi qui est dans le christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Toute écriture est inspirée de Dieu, et utile pour enseigner, pour convaincre, pour corriger, pour instruire dans la justice,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'afin que l’homme de Dieu soit accompli et parfaitement accompli pour toute bonne œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Je t’en adjure devant Dieu et le christ Jésus, qui va juger vivants et morts, et par son apparition et par son règne:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'prêche la parole, insiste en temps et hors de temps, convaincs, reprends, exhorte, avec toute longanimité et doctrine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'car il y aura un temps où ils ne supporteront pas le sain enseignement; mais, ayant des oreilles qui leur démangent, ils s’amasseront des docteurs selon leurs propres convoitises,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'et ils détourneront leurs oreilles de la vérité et se tourneront vers les fables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Mais toi, sois sobre en toutes choses, endure les souffrances, fais l’œuvre d’un évangéliste, accomplis pleinement ton service;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'car, pour moi, je sers déjà de libation, et le temps de mon départ est arrivé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'j’ai combattu le bon combat, j’ai achevé la course, j’ai gardé la foi:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'désormais m’est réservée la couronne de justice, que le Seigneur juste juge me donnera dans ce jour-là, et non seulement à moi, mais aussi à tous ceux qui aiment son apparition.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Empresse-toi de venir bientôt auprès de moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'car Démas m’a abandonné, ayant aimé le présent siècle; et il s’en est allé à Thessalonique, Crescens en Galatie, Tite en Dalmatie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Luc seul est avec moi. Prends Marc et amène-le avec toi, car il m’est utile pour le service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Or j’ai envoyé Tychique à Éphèse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Quand tu viendras, apporte le manteau que j’ai laissé en Troade chez Carpus, et les livres, spécialement les parchemins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexandre, l’ouvrier en cuivre, a montré envers moi beaucoup de méchanceté; le Seigneur lui rendra selon ses œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Garde-toi aussi de lui, car il s’est fort opposé à nos paroles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Dans ma première défense, personne n’a été avec moi, mais tous m’ont abandonné: que cela ne leur soit pas imputé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Mais le Seigneur s’est tenu près de moi et m’a fortifié, afin que par moi la prédication soit pleinement accomplie et que toutes les nations l’entendent; et j’ai été délivré de la gueule du lion.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Le Seigneur me délivrera de toute mauvaise œuvre et me conservera pour son royaume céleste. À lui la gloire, aux siècles des siècles! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Salue Prisca et Aquilas et la maison d’Onésiphore.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Éraste est demeuré à Corinthe, et j’ai laissé Trophime malade à Milet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Empresse-toi de venir avant l’hiver. Eubulus et Pudens, et Linus et Claudia, et tous les frères, te saluent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Le seigneur Jésus Christ soit avec ton esprit. Que la grâce soit avec vous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paul, esclave de Dieu, et apôtre de Jésus Christ selon la foi des élus de Dieu et la connaissance de la vérité qui est selon la piété,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'dans l’espérance de la vie éternelle que Dieu, qui ne peut mentir, a promise avant les temps des siècles...;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'mais il a manifesté, au temps propre, sa parole, dans la prédication qui m’a été confiée à moi selon le commandement de notre Dieu sauveur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, '– à Tite, mon véritable enfant selon la commune foi: Grâce et paix, de la part de Dieu le Père et du christ Jésus notre Sauveur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Je t’ai laissé en Crète dans ce but, que tu mettes en bon ordre les choses qui restent [à régler], et que, dans chaque ville, tu établisses des anciens, suivant que moi je t’ai ordonné:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'si quelqu’un est irréprochable, mari d’une seule femme, ayant des enfants fidèles, qui ne soient pas accusés de dissipation, ou insubordonnés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Car il faut que le surveillant soit irréprochable comme administrateur de Dieu, non adonné à son sens, non colère, non adonné au vin, non batteur, non avide d’un gain honteux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'mais hospitalier, aimant le bien, sage, juste, pieux, continent,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'tenant ferme la fidèle parole selon la doctrine, afin qu’il soit capable, tant d’exhorter par un sain enseignement, que de réfuter les contredisants.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Car il y a beaucoup d’insubordonnés vains discoureurs et séducteurs, principalement ceux qui sont de la circoncision,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'auxquels il faut fermer la bouche, qui renversent des maisons entières, enseignant ce qui ne convient pas, pour un gain honteux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Quelqu’un d’entre eux, leur propre prophète, a dit: “Les Crétois sont toujours menteurs, de méchantes bêtes, des ventres paresseux.”');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Ce témoignage est vrai; c’est pourquoi reprends-les vertement, afin qu’ils soient sains dans la foi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'ne s’attachant pas aux fables judaïques et aux commandements des hommes qui se détournent de la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Toutes choses sont pures pour ceux qui sont purs; mais, pour ceux qui sont souillés et incrédules, rien n’est pur, mais leur entendement et leur conscience sont souillés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Ils professent connaître Dieu, mais par leurs œuvres ils le renient, étant abominables et désobéissants, et, à l’égard de toute bonne œuvre, réprouvés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Mais toi, annonce les choses qui conviennent au sain enseignement:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'que les vieillards soient sobres, graves, sages, sains dans la foi, dans l’amour, dans la patience.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'De même, que les femmes âgées soient, dans toute leur manière d’être, comme il convient à de saintes femmes, – ni médisantes, ni asservies à beaucoup de vin, enseignant de bonnes choses,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'afin qu’elles instruisent les jeunes femmes à aimer leurs maris, à aimer leurs enfants,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'à être sages, pures, occupées des soins de la maison, bonnes, soumises à leurs propres maris, afin que la parole de Dieu ne soit pas blasphémée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Exhorte de même les jeunes hommes à être sobres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'te montrant toi-même en toutes choses un modèle de bonnes œuvres, [faisant preuve] dans l’enseignement, de pureté de doctrine, de gravité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'de parole saine qu’on ne peut condamner, afin que celui qui s’oppose ait honte, n’ayant rien de mauvais à dire de nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, '[Exhorte] les esclaves à être soumis à leurs propres maîtres, à leur complaire en toutes choses, n’étant pas contredisants;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'ne détournant rien, mais montrant toute bonne fidélité, afin qu’ils ornent en toutes choses l’enseignement qui est de notre Dieu sauveur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Car la grâce de Dieu qui apporte le salut est apparue à tous les hommes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'nous enseignant que, reniant l’impiété et les convoitises mondaines, nous vivions dans le présent siècle sobrement, et justement, et pieusement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'attendant la bienheureuse espérance et l’apparition de la gloire de notre grand Dieu et Sauveur Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'qui s’est donné lui-même pour nous, afin qu’il nous rachète de toute iniquité et qu’il purifie pour lui-même un peuple acquis, zélé pour les bonnes œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Annonce ces choses, exhorte et reprends, avec toute autorité de commander. Que personne ne te méprise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Rappelle-leur d’être soumis aux principautés et aux autorités, d’être obéissants, d’être prêts à toute bonne œuvre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'de n’injurier personne, de n’être pas querelleurs, [mais] modérés, montrant toute douceur envers tous les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Car nous étions, nous aussi, autrefois, insensés, désobéissants, égarés, asservis à diverses convoitises et voluptés, vivant dans la malice et dans l’envie, haïssables, nous haïssant l’un l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Mais, quand la bonté de notre Dieu sauveur et son amour envers les hommes sont apparus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'il nous sauva, non sur le principe d’œuvres [accomplies] en justice, que nous, nous aurions faites, mais selon sa propre miséricorde, par le lavage de la régénération et le renouvellement de l’Esprit Saint,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'qu’il a répandu richement sur nous par Jésus Christ, notre Sauveur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'afin que, ayant été justifiés par sa grâce, nous devenions héritiers selon l’espérance de la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Cette parole est certaine, et je veux que tu insistes sur ces choses, afin que ceux qui ont cru Dieu s’appliquent à être les premiers dans les bonnes œuvres: ces choses sont bonnes et utiles aux hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Mais évite les folles questions, et les généalogies, et les contestations, et les disputes sur la loi, car elles sont inutiles et vaines.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Rejette l’homme sectaire après une première et une seconde admonestation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'sachant qu’un tel homme est perverti et pèche, étant condamné par lui-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Quand j’enverrai Artémas auprès de toi, – ou Tychique, empresse-toi de venir auprès de moi à Nicopolis, car j’ai résolu d’y passer l’hiver.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Accompagne avec soin Zénas, le docteur de la loi, et Apollos, afin que rien ne leur manque;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'et que les nôtres aussi apprennent à être les premiers dans les bonnes œuvres pour les choses nécessaires, afin qu’ils ne soient pas sans fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Tous ceux qui sont avec moi te saluent. Salue ceux qui nous aiment dans la foi. Que la grâce soit avec vous tous!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paul, prisonnier de Jésus Christ, et le frère Timothée, à Philémon, le bien-aimé et notre compagnon d’œuvre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'et à la sœur Apphie, et à Archippe notre compagnon d’armes, et à l’assemblée qui [se réunit] dans ta maison:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Grâce et paix à vous, de la part de Dieu notre Père et du seigneur Jésus Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Je rends grâces à mon Dieu, faisant toujours mention de toi dans mes prières,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'apprenant l’amour et la foi que tu as envers le seigneur Jésus et pour tous les saints;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'en sorte que ta communion dans la foi opère en reconnaissant tout le bien qui est en nous à l’égard du christ Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Car nous avons une grande joie et une grande consolation dans ton amour, parce que les entrailles des saints sont rafraîchies par toi, frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'C’est pourquoi, tout en ayant une grande liberté en Christ de te commander ce qui convient,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, '– à cause de l’amour, je te prie plutôt, étant tel que je suis, Paul, un vieillard, et maintenant aussi prisonnier de Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'je te prie pour mon enfant que j’ai engendré dans les liens, Onésime,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'qui t’a été autrefois inutile, mais qui maintenant est utile à toi et à moi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'lequel je t’ai renvoyé, – lui, mes propres entrailles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Moi, j’aurais voulu le retenir auprès de moi, afin qu’il me serve pour toi dans les liens de l’évangile;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'mais je n’ai rien voulu faire sans ton avis, afin que le bien que tu fais ne soit pas l’effet de la contrainte, mais qu’il soit volontaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Car c’est peut-être pour cette raison qu’il a été séparé [de toi] pour un temps, afin que tu le possèdes pour toujours,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'non plus comme un esclave, mais au-dessus d’un esclave, comme un frère bien-aimé, spécialement de moi, et combien plus de toi, soit dans la chair, soit dans le Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Si donc tu me tiens pour associé [à toi], reçois-le comme moi-même;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'mais, s’il t’a fait quelque tort ou s’il te doit quelque chose, mets-le-moi en compte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Moi, Paul, je l’ai écrit de ma propre main; moi, je paierai, pour ne pas te dire que tu te dois toi-même aussi à moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Oui, frère, que moi, je tire ce profit de toi dans le Seigneur: rafraîchis mes entrailles en Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Ayant de la confiance dans ton obéissance, je t’ai écrit, sachant que tu feras même plus que je ne dis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Mais en même temps, prépare-moi aussi un logement, car j’espère que, par vos prières, je vous serai donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Épaphras, mon compagnon de captivité dans le christ Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Marc, Aristarque, Démas, Luc, mes compagnons d’œuvre, te saluent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Que la grâce de notre seigneur Jésus Christ soit avec votre esprit!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Dieu ayant autrefois, à plusieurs reprises et en plusieurs manières, parlé aux pères par les prophètes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'à la fin de ces jours-là, nous a parlé dans [le] Fils, qu’il a établi héritier de toutes choses, par lequel aussi il a fait les mondes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'qui, étant le resplendissement de sa gloire et l’empreinte de sa substance, et soutenant toutes choses par la parole de sa puissance, ayant fait par lui-même la purification des péchés, s’est assis à la droite de la majesté dans les hauts [lieux];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'étant devenu d’autant plus excellent que les anges, qu’il a hérité d’un nom plus excellent qu’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Car auquel des anges a-t-il jamais dit: « Tu es mon Fils, moi je t’ai aujourd’hui engendré »? Et encore: « Moi, je lui serai pour père, et lui me sera pour fils »?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Et encore, quand il introduit le Premier-né dans le monde habité, il dit: « Et que tous les anges de Dieu lui rendent hommage ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Et quant aux anges, il dit: « Qui fait ses anges des esprits, et ses ministres une flamme de feu ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Mais quant au Fils: « Ton trône, ô Dieu, [est] aux siècles des siècles; c’est un sceptre de droiture que le sceptre de ton règne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'tu as aimé la justice et haï l’iniquité; c’est pourquoi Dieu, ton Dieu, t’a oint d’une huile de joie au-dessus de tes compagnons ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Et: « Toi, dans les commencements, ✶Seigneur, tu as fondé la terre, et les cieux sont les œuvres de tes mains:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'eux, ils périront, mais toi, tu demeures; et ils vieilliront tous comme un habit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'et tu les plieras comme un vêtement, et ils seront changés; mais toi, tu es le même, et tes ans ne cesseront point ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Et auquel des anges a-t-il jamais dit: « Assieds-toi à ma droite, jusqu’à ce que j’aie mis tes ennemis pour marchepied de tes pieds »?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Ne sont-ils pas tous des esprits administrateurs, envoyés pour servir en faveur de ceux qui vont hériter du salut?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'C’est pourquoi nous devons porter une plus grande attention aux choses que nous avons entendues, de peur que nous ne nous écartions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Car si la parole prononcée par les anges a été ferme, et si toute transgression et désobéissance a reçu une juste rétribution,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'comment échapperons-nous, si nous négligeons un si grand salut, qui, ayant commencé par être annoncé par le Seigneur, nous a été confirmé par ceux qui l’avaient entendu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Dieu rendant témoignage avec eux par des signes et des prodiges, et par divers miracles et distributions de l’Esprit Saint, selon sa propre volonté?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Car ce n’est point aux anges qu’il a assujetti le monde habité à venir dont nous parlons;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'mais quelqu’un a rendu ce témoignage quelque part, disant: « Qu’est-ce que l’homme que tu te souviennes de lui, ou le fils de l’homme que tu le visites?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Tu l’as fait un peu moindre que les anges; tu l’as couronné de gloire et d’honneur, [et l’as établi sur les œuvres de tes mains];');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'tu as assujetti toutes choses sous ses pieds »; car en lui assujettissant toutes choses, il n’a rien laissé qui ne lui soit assujetti; mais maintenant nous ne voyons pas encore que toutes choses lui soient assujetties;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'mais nous voyons Jésus, qui a été fait un peu moindre que les anges à cause de la passion de la mort, couronné de gloire et d’honneur, en sorte que, par la grâce de Dieu, il goûtât la mort pour tout.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Car il convenait pour lui, à cause de qui sont toutes choses et par qui sont toutes choses, que, amenant plusieurs fils à la gloire, il consommât le chef de leur salut par des souffrances.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Car, et celui qui sanctifie et ceux qui sont sanctifiés sont tous d’un; c’est pourquoi il n’a pas honte de les appeler frères,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'disant: « J’annoncerai ton nom à mes frères; au milieu de l’assemblée je chanterai tes louanges ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Et encore: « Moi, je me confierai en lui ». Et encore: « Me voici, moi, et les enfants que Dieu m’a donnés ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Puisque donc les enfants ont eu part au sang et à la chair, lui aussi semblablement y a participé, afin que, par la mort, il rende impuissant celui qui avait le pouvoir de la mort, c’est-à-dire le diable;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'et qu’il délivre tous ceux qui, par la crainte de la mort, étaient, pendant toute leur vie, assujettis à la servitude.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Car, certes, il ne prend pas les anges, mais il prend la semence d’Abraham.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'C’est pourquoi il dut, en toutes choses, être rendu semblable à ses frères, afin qu’il soit un miséricordieux et fidèle souverain sacrificateur dans les choses qui concernent Dieu, pour faire propitiation pour les péchés du peuple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Car, en ce qu’il a souffert lui-même, étant tenté, il est à même de secourir ceux qui sont tentés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'C’est pourquoi, frères saints, participants à l’appel céleste, considérez l’apôtre et le souverain sacrificateur de notre confession, Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'qui est fidèle à celui qui l’a établi, comme Moïse aussi [l’a été] dans toute sa maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Car celui-là a été jugé digne d’une gloire d’autant plus grande que celle de Moïse, que celui qui a bâti la maison a plus d’honneur que la maison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Car toute maison est bâtie par quelqu’un; mais celui qui a bâti toutes choses, est Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Et Moïse a bien été fidèle dans toute sa maison, comme serviteur, en témoignage des choses qui devaient être dites;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'mais Christ, comme Fils, sur sa maison; et nous sommes sa maison, si du moins nous retenons ferme jusqu’au bout la confiance et la gloire de l’espérance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'C’est pourquoi, – comme dit l’Esprit Saint: « Aujourd’hui, si vous entendez sa voix,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'n’endurcissez pas vos cœurs comme dans l’irritation au jour de la tentation dans le désert,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'où vos pères m’ont tenté en m’éprouvant, et ont vu mes œuvres durant 40 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'C’est pourquoi j’ai été indigné contre cette génération, et j’ai dit: Ils s’égarent toujours dans leur cœur et ils n’ont point connu mes voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Ainsi je jurai dans ma colère: S’ils entrent dans mon repos! ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Prenez garde, frères, qu’il n’y ait en quelqu’un de vous un méchant cœur d’incrédulité, en ce qu’il abandonne le Dieu vivant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'mais exhortez-vous l’un l’autre chaque jour, aussi longtemps qu’il est dit: “Aujourd’hui”, afin qu’aucun d’entre vous ne s’endurcisse par la séduction du péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Car nous sommes devenus les compagnons du Christ, si du moins nous retenons ferme jusqu’au bout le commencement de notre assurance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'selon qu’il est dit: « Aujourd’hui, si vous entendez sa voix, n’endurcissez pas vos cœurs, comme dans l’irritation ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, '(Car qui sont ceux qui, l’ayant entendu, l’irritèrent? Mais [est-ce que ce ne furent] pas tous ceux qui sont sortis d’Égypte par Moïse?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Et contre lesquels fut-il indigné durant 40 ans? N’est-ce pas contre ceux qui ont péché et dont les corps sont tombés dans le désert?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Et auxquels jura-t-il qu’ils n’entreraient pas dans son repos, sinon à ceux qui ont désobéi?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Et nous voyons qu’ils n’y purent entrer à cause de [l’]incrédulité.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, '– Craignons donc qu’une promesse ayant été laissée d’entrer dans son repos, quelqu’un d’entre vous paraisse ne pas l’atteindre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'car nous aussi, nous avons été évangélisés de même que ceux-là; mais la parole qu’ils entendirent ne leur servit de rien, n’étant pas mêlée avec de la foi dans ceux qui l’entendirent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Car nous qui avons cru, nous entrons dans le repos, comme il a dit: « Ainsi je jurai dans ma colère: S’ils entrent dans mon repos », bien que les œuvres aient été faites dès la fondation du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Car il a dit ainsi quelque part touchant le septième jour: « Et Dieu se reposa de toutes ses œuvres au septième jour »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'et encore dans ce passage: « S’ils entrent dans mon repos! »');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Puisqu’il reste donc que quelques-uns y entrent, et que ceux qui auparavant avaient été évangélisés ne sont pas entrés à cause de leur désobéissance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'encore une fois il détermine un certain jour, disant, en David, si longtemps après: “Aujourd’hui”, comme il a été dit auparavant: « Aujourd’hui, si vous entendez sa voix, n’endurcissez pas vos cœurs. »');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Car si Josué leur avait donné le repos, il n’aurait pas parlé après cela d’un autre jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Il reste donc un repos sabbatique pour le peuple de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Car celui qui est entré dans son repos, lui aussi s’est reposé de ses œuvres, comme Dieu s’est reposé des siennes propres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Appliquons-nous donc à entrer dans ce repos-là, afin que personne ne tombe en imitant une semblable désobéissance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Car la parole de Dieu est vivante et opérante, et plus pénétrante qu’aucune épée à deux tranchants, et atteignant jusqu’à la division de l’âme et de l’esprit, des jointures et des moelles; et elle discerne les pensées et les intentions du cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Et il n’y a aucune créature qui soit cachée devant lui, mais toutes choses sont nues et découvertes aux yeux de celui à qui nous avons affaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Ayant donc un grand souverain sacrificateur qui a traversé les cieux, Jésus, le Fils de Dieu, tenons ferme [notre] confession;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'car nous n’avons pas un souverain sacrificateur qui ne puisse sympathiser à nos infirmités, mais [nous en avons un qui a été] tenté en toutes choses comme nous, à part le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Approchons-nous donc avec confiance du trône de la grâce, afin que nous recevions miséricorde et que nous trouvions grâce pour [avoir du] secours au moment opportun.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Car tout souverain sacrificateur pris d’entre les hommes est établi pour les hommes dans les choses qui concernent Dieu, afin qu’il offre et des dons et des sacrifices pour les péchés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'étant capable d’avoir de l’indulgence pour les ignorants et les errants, puisqu’il est aussi lui-même enveloppé d’infirmité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'et, à cause de cette infirmité, il doit offrir pour les péchés, comme pour le peuple, ainsi aussi pour lui-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Or nul ne s’arroge cet honneur; mais [seulement] s’il est appelé de Dieu, ainsi que le fut aussi Aaron.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'De même le Christ aussi ne s’est pas glorifié lui-même pour être fait souverain sacrificateur, mais celui-là [l’a glorifié] qui lui a dit: « Tu es mon Fils; moi je t’ai aujourd’hui engendré »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'comme il dit aussi dans un autre passage: « Tu es sacrificateur pour l’éternité selon l’ordre de Melchisédec »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, '– qui, durant les jours de sa chair, ayant offert, avec de grands cris et avec larmes, des prières et des supplications à celui qui pouvait le sauver de la mort, et ayant été exaucé à cause de sa piété,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'quoiqu’il fût Fils, a appris l’obéissance par les choses qu’il a souffertes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'et ayant été consommé, il est devenu, pour tous ceux qui lui obéissent, l’auteur du salut éternel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'étant salué par Dieu souverain sacrificateur selon l’ordre de Melchisédec,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'au sujet duquel nous avons beaucoup de choses à dire et qui sont difficiles à expliquer, puisque vous êtes devenus paresseux à écouter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Car lorsque vous devriez être des docteurs, vu le temps, vous avez de nouveau besoin qu’on vous enseigne quels sont les premiers rudiments des oracles de Dieu, et vous êtes devenus tels, que vous avez besoin de lait et non de nourriture solide;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'car quiconque use de lait est inexpérimenté dans la parole de la justice, car il est un petit enfant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'mais la nourriture solide est pour les hommes faits, qui, par le fait de l’habitude, ont les sens exercés à discerner le bien et le mal.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'C’est pourquoi, laissant la parole du commencement du Christ, avançons vers l’état d’hommes faits, ne posant pas de nouveau [le] fondement de la repentance des œuvres mortes et de la foi en Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'de la doctrine des ablutions et de l’imposition des mains, et de la résurrection des morts et du jugement éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Et c’est ce que nous ferons, si Dieu le permet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Car il est impossible que ceux qui ont été une fois éclairés, et qui ont goûté du don céleste, et qui sont devenus participants de l’Esprit Saint,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'et qui ont goûté la bonne parole de Dieu et les miracles du siècle à venir,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'et qui sont tombés, soient renouvelés encore à la repentance, crucifiant pour eux-mêmes le Fils de Dieu et l’exposant à l’opprobre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Car la terre qui boit la pluie qui vient souvent sur elle, et qui produit des herbes utiles pour ceux pour qui elle est aussi labourée, reçoit de Dieu de la bénédiction;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'mais si elle porte des épines et des chardons, elle est réprouvée et près de la malédiction, et sa fin est d’être brûlée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Mais nous sommes persuadés, en ce qui vous concerne, bien-aimés, de choses meilleures et qui tiennent au salut, quoique nous parlions ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Car Dieu n’est pas injuste pour oublier votre œuvre et l’amour que vous avez montré pour son nom, ayant servi les saints et les servant [encore].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Mais nous désirons que chacun de vous montre la même diligence pour la pleine assurance de l’espérance jusqu’au bout;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'afin que vous ne deveniez pas paresseux, mais imitateurs de ceux qui, par la foi et par la patience, héritent ce qui avait été promis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Car lorsque Dieu fit la promesse à Abraham, puisqu’il n’avait personne de plus grand par qui jurer, il jura par lui-même,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'disant: « Certes, en bénissant je te bénirai, et en multipliant je te multiplierai ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Et ainsi Abraham, ayant eu patience, obtint ce qui avait été promis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Car les hommes jurent par quelqu’un qui est plus grand qu’eux, et le serment est pour eux un terme à toute dispute, pour rendre ferme [ce qui est convenu].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Et Dieu, voulant en cela montrer plus abondamment aux héritiers de la promesse l’immutabilité de son conseil, est intervenu par un serment,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'afin que, par deux choses immuables, dans lesquelles il était impossible que Dieu mente, nous ayons une ferme consolation, nous qui nous sommes enfuis pour saisir l’espérance proposée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'laquelle nous avons comme une ancre de l’âme, sûre et ferme, et qui entre jusqu’au-dedans du voile');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'où Jésus est entré comme précurseur pour nous, étant devenu souverain sacrificateur pour l’éternité selon l’ordre de Melchisédec.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Car ce Melchisédec, roi de Salem, sacrificateur du Dieu Très-haut, qui alla au-devant d’Abraham lorsqu’il revenait de la défaite des rois, et qui le bénit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'auquel aussi Abraham donna pour part la dîme de tout, premièrement, étant interprété, roi de justice, et puis aussi roi de Salem, c’est-à-dire roi de paix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'sans père, sans mère, sans généalogie, n’ayant ni commencement de jours, ni fin de vie, mais assimilé au Fils de Dieu, demeure sacrificateur à perpétuité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Mais considérez combien grand était celui à qui même Abraham donna une dîme du butin, lui le patriarche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Et ceux d’entre les fils de Lévi qui reçoivent la sacrificature ont bien un commandement de dîmer le peuple selon la loi, c’est-à-dire leurs frères, bien qu’ils soient sortis des reins d’Abraham;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'mais celui qui ne tire pas généalogiquement son origine d’eux, a dîmé Abraham et a béni celui qui avait les promesses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Or, sans contredit, le moindre est béni par celui qui est plus excellent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Et ici, des hommes qui meurent reçoivent des dîmes; mais là, celui de qui il est rendu témoignage qu’il vit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'et, pour ainsi dire, Lévi même, qui reçoit des dîmes, a été dîmé en Abraham,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'car il était encore dans les reins de son père quand Melchisédec alla au-devant de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Si donc la perfection était par la sacrificature lévitique, (car c’est en relation avec elle que le peuple a reçu sa loi,) quel besoin était-il encore qu’un autre sacrificateur se lève selon l’ordre de Melchisédec et qui ne soit pas nommé selon l’ordre d’Aaron?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Car la sacrificature étant changée, il y a aussi par nécessité un changement de loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Car celui à l’égard duquel ces choses sont dites appartient à une autre tribu, dont personne n’a été attaché à l’autel;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'car il est évident que notre Seigneur a surgi de Juda, tribu à l’égard de laquelle Moïse n’a rien dit concernant des sacrificateurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Et cela est encore bien plus évident, si, à la ressemblance de Melchisédec, un autre sacrificateur se lève,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'qui n’a pas été établi selon la loi d’un commandement charnel, mais selon la puissance d’une vie impérissable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Car [ce] témoignage [lui] est rendu: « Tu es sacrificateur pour l’éternité, selon l’ordre de Melchisédec ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Car il y a abrogation du commandement qui a précédé, à cause de sa faiblesse et de son inutilité');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '(car la loi n’a rien amené à la perfection), et introduction d’une meilleure espérance par laquelle nous approchons de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Et en tant que [cela n’a] pas [eu lieu] sans serment');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '(car ceux-là sont devenus sacrificateurs sans serment, mais celui-ci [l’est devenu] avec serment, par celui qui a dit de lui: « Le ✶Seigneur a juré et ne se repentira pas: Tu es sacrificateur pour l’éternité [selon l’ordre de Melchisédec] »),');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'c’est d’une alliance d’autant meilleure que Jésus a été fait le garant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Et ceux-là étaient plusieurs sacrificateurs, parce que la mort les empêchait de demeurer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'mais celui-ci, parce qu’il demeure éternellement, a la sacrificature qui ne se transmet pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'De là vient aussi qu’il peut sauver entièrement ceux qui s’approchent de Dieu par lui, étant toujours vivant pour intercéder pour eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Car un tel souverain sacrificateur nous convenait, saint, innocent, sans souillure, séparé des pécheurs, et élevé plus haut que les cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'qui n’est pas journellement dans la nécessité, comme les souverains sacrificateurs, d’offrir des sacrifices, d’abord pour ses propres péchés, ensuite pour ceux du peuple; car cela, il l’a fait une fois pour toutes, s’étant offert lui-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Car la loi établit pour souverains sacrificateurs des hommes qui sont dans l’infirmité, mais la parole du serment, qui est après la loi, [établit] un Fils qui est consommé pour l’éternité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Or la somme de ce que nous disons, c’est que nous avons un tel souverain sacrificateur qui s’est assis à la droite du trône de la majesté dans les cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'ministre des lieux saints et du vrai tabernacle que le ✶Seigneur a dressé, non pas l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Car tout souverain sacrificateur est établi pour offrir des dons et des sacrifices; c’est pourquoi il était nécessaire que celui-ci aussi ait quelque chose à offrir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Si donc il était sur la terre, il ne serait pas sacrificateur, puisqu’il y a ceux qui offrent des dons selon la loi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'lesquels servent la figure et l’ombre des choses célestes: comme Moïse, quand il allait construire le tabernacle, a été averti divinement; car: « Prends garde », dit-il, « à faire toutes choses selon le modèle qui t’a été montré sur la montagne ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Or maintenant [Christ] a obtenu un ministère d’autant plus excellent, qu’il est médiateur d’une meilleure alliance qui est établie sur de meilleures promesses;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'car si cette première [alliance] avait été irréprochable, il n’aurait jamais été cherché de lieu pour une seconde;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'car, en censurant, il leur dit: « Voici, des jours viennent, dit le ✶Seigneur, et je conclurai, pour la maison d’Israël et pour la maison de Juda, une nouvelle alliance,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'non selon l’alliance que j’ai faite avec leurs pères, au jour où je les pris par la main pour les tirer du pays d’Égypte; car ils n’ont pas persévéré dans mon alliance, et moi je les ai délaissés, dit le ✶Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Car c’est ici l’alliance que j’établirai pour la maison d’Israël après ces jours-là, dit le ✶Seigneur: En mettant mes lois dans leur entendement, je les écrirai aussi sur leurs cœurs, et je leur serai pour Dieu, et ils me seront pour peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'et ils n’enseigneront point chacun son concitoyen et chacun son frère, disant: Connais le ✶Seigneur; car ils me connaîtront tous, depuis le plus petit jusqu’au plus grand d’entre eux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'car je serai clément à l’égard de leurs injustices, et je ne me souviendrai plus jamais de leurs péchés ni de leurs iniquités ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'En disant: “une nouvelle”, il a rendu ancienne la première: or ce qui devient ancien et qui vieillit, est près de disparaître.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'La première donc avait aussi des ordonnances pour le culte, et le sanctuaire, un [sanctuaire] terrestre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Car un tabernacle fut construit, – le premier, qui est appelé saint, dans lequel était le chandelier, et la table, et la proposition des pains;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'et, après le second voile, un tabernacle qui est appelé saint des saints,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'ayant l’encensoir d’or, et l’arche de l’alliance entièrement couverte d’or tout autour, dans laquelle était la cruche d’or qui renfermait la manne, et la verge d’Aaron qui avait bourgeonné, et les tables de l’alliance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'et, au-dessus de l’arche, des chérubins de gloire ombrageant le propitiatoire; sur quoi nous n’avons pas à parler dans ce moment en détail.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Or ces choses étant ainsi disposées, les sacrificateurs entrent constamment dans le premier tabernacle, accomplissant le service;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'mais, dans le second, le seul souverain sacrificateur, une fois l’an, non sans du sang qu’il offre pour lui-même et pour les fautes du peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'l’Esprit Saint indiquant ceci: le chemin des lieux saints n’a pas encore été manifesté, tandis que le premier tabernacle a encore sa place,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'lequel est une figure pour le temps présent, dans lequel sont offerts des dons et des sacrifices qui ne peuvent pas rendre parfait quant à la conscience celui qui rend le culte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, '[culte qui consiste] seulement en viandes, en breuvages, en diverses ablutions, ordonnances charnelles imposées jusqu’au temps du redressement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Mais Christ étant venu, souverain sacrificateur des biens à venir, par le tabernacle plus grand et plus parfait qui n’est pas fait de main, c’est-à-dire qui n’est pas de cette création,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'et non avec le sang de boucs et de veaux, mais avec son propre sang, est entré une fois pour toutes dans les lieux saints, ayant obtenu une rédemption éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Car si le sang de boucs et de taureaux, – et la cendre d’une génisse avec laquelle on fait aspersion sur ceux qui sont souillés, – sanctifie pour la pureté de la chair,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'combien plus le sang du Christ, qui, par l’Esprit éternel, s’est offert lui-même à Dieu sans tache, purifiera-t-il votre conscience des œuvres mortes, pour que vous serviez le Dieu vivant!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Et c’est pourquoi il est médiateur d’une nouvelle alliance, en sorte que, la mort étant intervenue pour la rançon des transgressions qui étaient sous la première alliance, ceux qui sont appelés reçoivent l’héritage éternel qui a été promis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, '(Car là où il y a un testament, il est nécessaire que la mort du testateur intervienne;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'car un testament est valide lorsque la mort est intervenue, puisqu’il n’a pas de force tant que le testateur vit.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'De là vient qu’aussi la première [alliance] n’a pas été inaugurée sans du sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Car chaque commandement, pour ce qui concerne la loi, ayant été proclamé par Moïse à tout le peuple, il prit le sang des veaux et des boucs, avec de l’eau et de la laine écarlate et de l’hysope, et en fit aspersion sur le livre lui-même et sur tout le peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'en disant: « C’est ici le sang de l’alliance que Dieu vous a ordonnée ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Et, de la même manière, il fit aspersion du sang sur le tabernacle aussi et sur tous les ustensiles du service.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Et presque toutes choses sont purifiées par du sang, selon la loi; et sans effusion de sang il n’y a pas de rémission.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Il était donc nécessaire que les images des choses qui sont dans les cieux soient purifiées par de telles choses, mais que les choses célestes elles-mêmes le soient par de meilleurs sacrifices que ceux-là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Car le Christ n’est pas entré dans des lieux saints faits de main, copies des vrais, mais dans le ciel même, afin de paraître maintenant pour nous devant la face de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, '– ni, non plus, afin de s’offrir lui-même plusieurs fois, ainsi que le souverain sacrificateur entre dans les lieux saints chaque année avec un sang autre [que le sien]');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, '(puisque [dans ce cas] il aurait fallu qu’il souffre plusieurs fois depuis la fondation du monde); mais maintenant, en la consommation des siècles, il a été manifesté une fois pour l’abolition du péché par son sacrifice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Et comme il est réservé aux hommes de mourir une fois, – et après cela [le] jugement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'ainsi le Christ aussi, ayant été offert une fois pour porter les péchés de plusieurs, apparaîtra une seconde fois, sans péché, à salut à ceux qui l’attendent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Car la loi, ayant l’ombre des biens à venir, non l’image même des choses, ne peut jamais, par les mêmes sacrifices que l’on offre continuellement chaque année, rendre parfaits ceux qui s’approchent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Autrement n’auraient-ils pas cessé d’être offerts, puisque ceux qui rendent le culte, étant une fois purifiés, n’auraient plus eu aucune conscience de péchés?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Mais il y a dans ces [sacrifices], chaque année, un acte remémoratif de péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Car il est impossible que le sang de taureaux et de boucs ôte les péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'C’est pourquoi, en entrant dans le monde, il dit: « Tu n’as pas voulu de sacrifice ni d’offrande, mais tu m’as formé un corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Tu n’as pas pris plaisir aux holocaustes ni aux sacrifices pour le péché;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'alors j’ai dit: Voici, je viens, – il est écrit de moi dans le rouleau du livre – pour faire, ô Dieu, ta volonté ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Ayant dit plus haut: « Tu n’as pas voulu de sacrifices, ni d’offrandes, ni d’holocaustes, ni de sacrifices pour le péché, et tu n’y as pas pris plaisir » – lesquels sont offerts selon la loi,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, '– alors il dit: « Voici, je viens pour faire ta volonté ». Il ôte le premier afin d’établir le second.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'C’est par cette volonté que nous avons été sanctifiés, par l’offrande du corps de Jésus Christ [faite] une fois pour toutes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, '– Et tout sacrificateur se tient debout chaque jour, faisant le service et offrant souvent les mêmes sacrifices qui ne peuvent jamais ôter les péchés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'mais celui-ci, ayant offert un seul sacrifice pour les péchés, s’est assis à perpétuité à la droite de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'attendant désormais « jusqu’à ce que ses ennemis soient mis pour marchepied de ses pieds ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Car, par une seule offrande, il a rendu parfaits à perpétuité ceux qui sont sanctifiés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Et l’Esprit Saint aussi nous en rend témoignage; car, après avoir dit:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '« C’est ici l’alliance que j’établirai pour eux après ces jours-là, dit le ✶Seigneur: En mettant mes lois dans leurs cœurs, je les écrirai aussi sur leurs entendements »,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, '[il dit]: « Et je ne me souviendrai plus jamais de leurs péchés ni de leurs iniquités ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Or, là où il y a rémission de ces choses, il n’y a plus d’offrande pour le péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Ayant donc, frères, une pleine liberté pour entrer dans les lieux saints par le sang de Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'par le chemin nouveau et vivant qu’il nous a consacré à travers le voile, c’est-à-dire sa chair,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'et ayant un grand sacrificateur [établi] sur la maison de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'approchons-nous avec un cœur vrai, en pleine assurance de foi, [ayant] les cœurs par aspersion purifiés d’une mauvaise conscience et le corps lavé d’eau pure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Retenons la confession de notre espérance sans chanceler, car celui qui a promis est fidèle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'et prenons garde l’un à l’autre pour nous exciter à l’amour et aux bonnes œuvres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'n’abandonnant pas le rassemblement de nous-mêmes, comme quelques-uns ont l’habitude [de faire], mais nous exhortant [l’un l’autre], et cela d’autant plus que vous voyez le jour approcher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Car si nous péchons volontairement après avoir reçu la connaissance de la vérité, il ne reste plus de sacrifice pour les péchés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'mais une certaine attente terrible de jugement et l’ardeur d’un feu qui va dévorer les adversaires.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Si quelqu’un a méprisé la loi de Moïse, il meurt sans miséricorde sur [la déposition de] deux ou [de] trois témoins:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'd’une punition combien plus sévère pensez-vous que sera jugé digne celui qui a foulé aux pieds le Fils de Dieu, et qui a estimé profane le sang de l’alliance par lequel il avait été sanctifié, et qui a outragé l’Esprit de grâce?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Car nous connaissons celui qui a dit: « À moi la vengeance; moi je rendrai, dit le ✶Seigneur »; et encore: « Le ✶Seigneur jugera son peuple ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'C’est une chose terrible que de tomber entre les mains du Dieu vivant!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Mais rappelez dans votre mémoire les jours précédents, dans lesquels, ayant été éclairés, vous avez enduré un grand combat de souffrances,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'soit en ce que vous avez été offerts en spectacle par des opprobres et des afflictions, soit en ce que vous vous êtes associés à ceux qui ont été ainsi traités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Car vous avez montré de la sympathie pour les prisonniers et vous avez accepté avec joie l’enlèvement de vos biens, sachant que vous avez pour vous-mêmes des biens meilleurs et permanents.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Ne rejetez donc pas loin votre confiance qui a une grande récompense.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Car vous avez besoin de patience, afin que, ayant fait la volonté de Dieu, vous receviez les choses promises.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Car encore très peu de temps, « et celui qui vient viendra, et il ne tardera pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Or le juste vivra de foi; et: Si [quelqu’un] se retire, mon âme ne prend pas plaisir en lui ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Mais pour nous, nous ne sommes pas de ceux qui se retirent pour la perdition, mais de ceux qui croient pour la conservation de l’âme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Or la foi est l’assurance des choses qu’on espère, et la conviction de celles qu’on ne voit pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Car c’est par elle que les anciens ont reçu témoignage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Par la foi, nous comprenons que les mondes ont été formés par la parole de Dieu, de sorte que ce qui se voit n’a pas été fait de choses qui paraissent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Par la foi, Abel offrit à Dieu un plus excellent sacrifice que Caïn, et par ce sacrifice il a reçu le témoignage d’être juste, Dieu rendant témoignage à ses dons; et par lui, étant mort, il parle encore.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Par la foi, Énoch fut enlevé pour qu’il ne voie pas la mort; et il ne fut pas trouvé, parce que Dieu l’avait enlevé; car, avant son enlèvement, il a reçu le témoignage d’avoir plu à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Or, sans la foi il est impossible de lui plaire; car il faut que celui qui s’approche de Dieu croie que [Dieu] est, et qu’il est le rémunérateur de ceux qui le recherchent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Par la foi, Noé, étant averti divinement des choses qui ne se voyaient pas encore, craignit et bâtit une arche pour la conservation de sa maison; et par cette arche il condamna le monde et devint héritier de la justice qui est selon la foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Par la foi, Abraham, étant appelé, obéit pour s’en aller au lieu qu’il devait recevoir pour héritage; et il s’en alla, ne sachant où il allait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Par la foi, il demeura dans la terre de la promesse comme dans [une terre] étrangère, demeurant sous des tentes avec Isaac et Jacob, les cohéritiers de la même promesse;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'car il attendait la cité qui a les fondements, de laquelle Dieu est l’architecte et le créateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Par la foi, Sara elle-même aussi reçut la force de fonder une postérité, et [cela], étant hors d’âge, puisqu’elle estima fidèle celui qui avait promis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'c’est pourquoi aussi d’un seul, et d’un homme déjà amorti, sont nés des gens qui sont comme les étoiles du ciel en nombre et comme le sable qui est sur le rivage de la mer, lequel ne peut se compter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Tous ceux-ci sont morts dans la foi, n’ayant pas reçu les choses promises, mais les ayant vues de loin et saluées, ayant confessé qu’ils étaient étrangers et forains sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Car ceux qui disent de telles choses montrent clairement qu’ils recherchent une patrie;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'et en effet, s’ils s’étaient souvenus de celle d’où ils étaient sortis, ils auraient eu du temps pour y retourner;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'mais maintenant ils en désirent une meilleure, c’est-à-dire une céleste; c’est pourquoi Dieu n’a point honte d’eux, savoir d’être appelé leur Dieu, car il leur a préparé une cité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Par la foi, Abraham, étant éprouvé, a offert Isaac; et celui qui avait reçu les promesses offrit son fils unique,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'à l’égard duquel il avait été dit: « En Isaac te sera appelée [une] semence », –');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'ayant estimé que Dieu pouvait le ressusciter même d’entre les morts, d’où aussi, en figure, il le reçut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Par la foi, Isaac bénit Jacob et Ésaü à l’égard des choses à venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Par la foi, Jacob mourant bénit chacun des fils de Joseph, et adora, [appuyé] sur le bout de son bâton.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Par la foi, Joseph, en terminant sa vie, fit mention de la sortie des fils d’Israël et donna un ordre touchant ses os.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Par la foi, Moïse, étant né, fut caché trois mois par ses parents, parce qu’ils virent que l’enfant était beau, et ils ne craignirent pas l’ordonnance du roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Par la foi, Moïse, étant devenu grand, refusa d’être appelé fils de la fille du Pharaon,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'choisissant plutôt d’être dans l’affliction avec le peuple de Dieu, que de jouir pour un temps des délices du péché,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'estimant l’opprobre du Christ une plus grande richesse que les trésors de l’Égypte; car il regardait à la rémunération.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Par la foi, il quitta l’Égypte, ne craignant pas la colère du roi, car il tint ferme, comme voyant celui qui est invisible.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Par la foi, il a fait la pâque et l’aspersion du sang, afin que le destructeur des premiers-nés ne les touche pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Par la foi, ils traversèrent la mer Rouge comme une terre sèche, ce que les Égyptiens ayant essayé, ils furent engloutis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Par la foi, les murs de Jéricho tombèrent, après qu’on en eut fait le tour sept jours durant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Par la foi, Rahab, la prostituée, ne périt pas avec ceux qui n’ont pas cru, ayant reçu les espions en paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Et que dirai-je davantage? Car le temps me manquera si je discours de Gédéon, de Barac et de Samson et de Jephté, de David et de Samuel et des prophètes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'qui par la foi subjuguèrent des royaumes, accomplirent la justice, obtinrent les choses promises, fermèrent la gueule des lions,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'éteignirent la force du feu, échappèrent au tranchant de l’épée, de faibles qu’ils étaient furent rendus vigoureux, devinrent forts dans la bataille, firent ployer les armées des étrangers.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Les femmes reçurent leurs morts par la résurrection; et d’autres furent torturés, n’acceptant pas la délivrance, afin d’obtenir une meilleure résurrection;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'et d’autres furent éprouvés par des moqueries et par des coups, et encore par des liens et par la prison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'ils furent lapidés, sciés, tentés; ils moururent égorgés par l’épée; ils errèrent çà et là, vêtus de peaux de brebis, de peaux de chèvres, dans le besoin, affligés, maltraités,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(desquels le monde n’était pas digne,) errant dans les déserts et les montagnes, et les cavernes et les trous de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Et tous ceux-ci, ayant reçu témoignage par la foi, n’ont pas reçu ce qui avait été promis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Dieu ayant eu en vue quelque chose de meilleur pour nous, afin qu’ils ne parviennent pas à la perfection sans nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'C’est pourquoi, nous aussi, ayant une si grande nuée de témoins qui nous entoure, rejetant tout fardeau et le péché qui [nous] enveloppe si aisément, courons avec patience la course qui est devant nous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'fixant les yeux sur Jésus, le chef et le consommateur de la foi, lequel, à cause de la joie qui était devant lui, a enduré la croix, ayant méprisé la honte, et est assis à la droite du trône de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Car considérez celui qui a enduré une telle contradiction de la part des pécheurs contre lui-même, afin que vous ne soyez pas las, étant découragés dans vos âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Vous n’avez pas encore résisté jusqu’au sang en combattant contre le péché,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'et vous avez oublié l’exhortation qui s’adresse à vous comme à des fils: « Mon fils, ne méprise pas la discipline du ✶Seigneur, et ne perds pas courage quand tu es repris par lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'car celui que le ✶Seigneur aime, il le discipline, et il fouette tout fils qu’il agrée ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Vous endurez [des peines] comme discipline: Dieu agit envers vous comme envers des fils, car qui est le fils que le père ne discipline pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Mais si vous êtes sans [la] discipline à laquelle tous participent, alors vous êtes des bâtards et non pas des fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'De plus, nous avons eu les pères de notre chair pour nous discipliner, et nous les avons respectés; ne serons-nous pas beaucoup plutôt soumis au Père des esprits, et nous vivrons?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Car ceux-là disciplinaient pendant peu de jours, selon qu’ils le trouvaient bon; mais celui-ci [nous discipline] pour notre profit, afin que nous participions à sa sainteté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Or aucune discipline, pour le présent, ne semble être [un sujet] de joie, mais de tristesse; mais plus tard, elle rend le fruit paisible de la justice à ceux qui sont exercés par elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'C’est pourquoi, redressez les mains lassées et les genoux défaillants,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'et faites des sentiers droits à vos pieds, afin que ce qui est boiteux ne se dévoie pas, mais plutôt se guérisse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Poursuivez la paix avec tous, et la sainteté, sans laquelle nul ne verra le Seigneur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'veillant de peur que quelqu’un ne manque de la grâce de Dieu; de peur que quelque racine d’amertume, bourgeonnant en haut, ne [vous] trouble, et que par elle plusieurs ne soient souillés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'de peur qu’il n’y ait quelque fornicateur, ou profane comme Ésaü, qui pour un seul mets vendit son droit de premier-né;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'car vous savez que, aussi, plus tard, désirant hériter de la bénédiction, il fut rejeté, (car il ne trouva pas lieu à la repentance,) quoiqu’il l’ait recherchée avec larmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Car vous n’êtes pas venus à la montagne qui peut être touchée, ni au feu brûlant, ni à l’obscurité, ni aux ténèbres, ni à la tempête,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'ni au son de la trompette, ni à la voix de paroles, [voix telle] que ceux qui l’entendaient prièrent que la parole ne leur soit plus adressée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '(car ils ne pouvaient supporter ce qui était enjoint: « Si même une bête touche la montagne, elle sera lapidée »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'et Moïse, si terrible était ce qui paraissait, dit: Je suis épouvanté et tout tremblant;)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'mais vous êtes venus à la montagne de Sion; et à la cité du Dieu vivant, la Jérusalem céleste; et à des myriades d’anges, l’assemblée universelle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'et à l’assemblée des premiers-nés écrits dans les cieux; et à Dieu, juge de tous; et aux esprits des justes consommés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'et à Jésus, médiateur d’une nouvelle alliance; et au sang d’aspersion qui parle mieux qu’Abel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Prenez garde que vous ne refusiez pas celui qui parle: car si ceux-là n’ont pas échappé qui refusèrent celui qui parlait en oracles sur la terre, combien moins [échapperons]-nous, si nous nous détournons de celui qui [parle ainsi] des cieux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'duquel la voix ébranla alors la terre; mais maintenant il a promis, disant: « Encore une fois je secouerai non seulement la terre, mais aussi le ciel ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Or ce “Encore une fois” indique le changement des choses muables, comme ayant été faites, afin que celles qui sont immuables demeurent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'C’est pourquoi, recevant un royaume inébranlable, retenons la grâce par laquelle nous servions Dieu d’une manière qui lui soit agréable, avec révérence et avec crainte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Car aussi notre Dieu est un feu consumant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Que l’amour fraternel demeure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'N’oubliez pas l’hospitalité; car par elle quelques-uns, à leur insu, ont logé des anges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Souvenez-vous des prisonniers, comme si vous étiez liés avec eux, de ceux qui sont maltraités, comme étant vous-mêmes aussi dans le corps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Que le mariage soit [tenu] en honneur à tous égards, et le lit sans souillure; mais Dieu jugera les fornicateurs et les adultères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Que votre conduite soit sans avarice, étant contents de ce que vous avez présentement; car lui-même a dit: « Je ne te laisserai point et je ne t’abandonnerai point »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'en sorte que, pleins de confiance, nous disions: « Le ✶Seigneur est mon aide et je ne craindrai point: que me fera l’homme? ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Souvenez-vous de vos conducteurs qui vous ont annoncé la parole de Dieu, et, considérant l’issue de leur conduite, imitez leur foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jésus Christ est le même, hier, et aujourd’hui, et éternellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Ne soyez pas séduits par des doctrines diverses et étrangères, car il est bon que le cœur soit affermi par la grâce, non par les viandes, lesquelles n’ont pas profité à ceux qui y ont marché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Nous avons un autel dont ceux qui servent le tabernacle n’ont pas le droit de manger;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'car les corps des animaux dont le sang est porté, pour le péché, dans les lieux saints, par le souverain sacrificateur, sont brûlés hors du camp.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'C’est pourquoi aussi Jésus, afin qu’il sanctifie le peuple par son propre sang, a souffert hors de la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Ainsi donc, sortons vers lui hors du camp, portant son opprobre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'car nous n’avons pas ici de cité permanente, mais nous recherchons celle qui est à venir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Offrons donc, par lui, sans cesse à Dieu un sacrifice de louanges, c’est-à-dire le fruit des lèvres qui confessent son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Mais n’oubliez pas la bienfaisance, et de faire part de vos biens, car Dieu prend plaisir à de tels sacrifices.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Obéissez à vos conducteurs et soyez soumis, car ils veillent pour vos âmes, comme ayant à rendre compte; afin qu’ils fassent cela avec joie, et non en gémissant, car cela ne vous serait pas profitable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Priez pour nous, car nous croyons que nous avons une bonne conscience, désirant de bien nous conduire en toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Mais je vous prie d’autant plus instamment de faire cela, afin que je vous sois rendu plus tôt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Or le Dieu de paix qui a ramené d’entre les morts le grand pasteur des brebis, dans [la puissance du] sang de l’alliance éternelle, notre seigneur Jésus,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'vous rende accomplis en toute bonne œuvre pour faire sa volonté, faisant en vous ce qui est agréable devant lui, par Jésus Christ, auquel soit la gloire aux siècles des siècles! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Or je vous exhorte, frères, à supporter la parole d’exhortation, car ce n’est qu’en peu de mots que je vous ai écrit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Sachez que notre frère Timothée a été mis en liberté: s’il vient bientôt, je vous verrai avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Saluez tous vos conducteurs et tous les saints. Ceux d’Italie vous saluent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Que la grâce soit avec vous tous! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jacques, esclave de Dieu et du seigneur Jésus Christ, aux douze tribus qui sont dans la dispersion, salut!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Estimez-le comme une parfaite joie, mes frères, quand vous serez en butte à diverses tentations,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'sachant que l’épreuve de votre foi produit la patience.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Mais que la patience ait son œuvre parfaite, afin que vous soyez parfaits et accomplis, ne manquant de rien.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Et si quelqu’un de vous manque de sagesse, qu’il demande à Dieu qui donne à tous libéralement et qui ne fait pas de reproches, et il lui sera donné;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'mais qu’il demande avec foi, ne doutant nullement; car celui qui doute est semblable au flot de la mer, agité par le vent et jeté çà et là;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'or que cet homme-là ne pense pas qu’il recevra quoi que ce soit du Seigneur:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'il est un homme incertain dans ses pensées, inconstant dans toutes ses voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Or que le frère de basse condition se glorifie dans son élévation,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'et le riche dans son abaissement, car il passera comme la fleur de l’herbe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Car le soleil s’est levé avec sa brûlante chaleur et a séché l’herbe, et sa fleur est tombée, et la grâce de sa forme a péri: ainsi aussi le riche se flétrira dans ses voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Bienheureux est l’homme qui endure la tentation; car, quand il aura été manifesté fidèle par l’épreuve il recevra la couronne de vie, qu’Il a promise à ceux qui l’aiment.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Que nul, quand il est tenté, ne dise: Je suis tenté par Dieu; – car Dieu ne peut être tenté par le mal, et lui ne tente personne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Mais chacun est tenté, étant attiré et amorcé par sa propre convoitise;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'puis la convoitise, ayant conçu, enfante le péché; et le péché, étant consommé, produit la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Ne vous égarez pas, mes frères bien-aimés:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'tout ce qui nous est donné de bon et tout don parfait descendent d’en haut, du Père des lumières, en qui il n’y a pas de variation ou d’ombre de changement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'De sa propre volonté, il nous a engendrés par la parole de la vérité, pour que nous soyons une sorte de prémices de ses créatures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Ainsi, mes frères bien-aimés, que tout homme soit prompt à écouter, lent à parler, lent à la colère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'car la colère de l’homme n’accomplit pas la justice de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'C’est pourquoi, rejetant toute saleté et tout débordement de malice, recevez avec douceur la parole implantée, qui a la puissance de sauver vos âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Mais mettez la parole en pratique, et ne l’écoutez pas seulement, vous séduisant vous-mêmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Car si quelqu’un écoute la parole et ne la met pas en pratique, il est semblable à un homme qui considère sa face naturelle dans un miroir;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'car il s’est considéré lui-même et s’en est allé, et aussitôt il a oublié quel il était.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Mais celui qui aura regardé de près dans la loi parfaite, celle de la liberté, et qui aura persévéré, n’étant pas un auditeur oublieux, mais un faiseur d’œuvre, celui-là sera bienheureux dans son faire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Si quelqu’un pense être religieux et qu’il ne tienne pas sa langue en bride, mais séduise son cœur, le service religieux de cet homme est vain.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Le service religieux pur et sans tache devant Dieu le Père, est celui-ci: de visiter les orphelins et les veuves dans leur affliction, de se conserver pur du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Mes frères, n’ayez pas la foi de notre seigneur Jésus Christ, [seigneur] de gloire, en faisant acception de personnes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Car s’il entre dans votre synagogue un homme portant une bague d’or, en vêtements éclatants, et qu’il entre aussi un pauvre en vêtements sales,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'et que vous regardiez vers celui qui porte les vêtements éclatants, et que vous disiez: Toi, assieds-toi ici à ton aise; et que vous disiez au pauvre: Toi, tiens-toi là debout; ou: Assieds-toi ici au bas de mon marchepied;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'n’avez-vous pas fait une distinction en vous-mêmes, et n’êtes-vous pas devenus des juges ayant de mauvaises pensées?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Écoutez, mes frères bien-aimés: Dieu n’a-t-il pas choisi les pauvres quant au monde, riches en foi et héritiers du royaume qu’il a promis à ceux qui l’aiment?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Mais vous, vous avez méprisé le pauvre. Les riches ne vous oppriment-ils pas, et ne sont-ce pas eux qui vous tirent devant les tribunaux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Ne sont-ce pas eux qui blasphèment le beau nom qui a été invoqué sur vous?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Si en effet vous accomplissez la loi royale, selon l’écriture: « Tu aimeras ton prochain comme toi-même », vous faites bien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'mais si vous faites acception de personnes, vous commettez le péché, et vous êtes convaincus par la loi comme transgresseurs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Car quiconque gardera toute la loi et faillira en un seul point, est coupable sur tous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Car celui qui a dit: « Tu ne commettras pas adultère », a dit aussi: « Tu ne tueras pas ». Or si tu ne commets pas adultère, mais que tu tues, tu es devenu transgresseur de [la] loi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Ainsi parlez, et ainsi agissez comme devant être jugés par la loi de la liberté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'car le jugement est sans miséricorde pour celui qui n’a pas usé de miséricorde. La miséricorde se glorifie vis-à-vis du jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Mes frères, quel profit y a-t-il si quelqu’un dit qu’il a la foi, et qu’il n’ait pas d’œuvres? La foi peut-elle le sauver?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Et si un frère ou une sœur sont nus et manquent de leur nourriture de tous les jours,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'et que quelqu’un d’entre vous leur dise: Allez en paix, chauffez-vous et rassasiez-vous, – et que vous ne leur donniez pas les choses nécessaires pour le corps, quel profit y a-t-il?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'De même aussi la foi, si elle n’a pas d’œuvres, est morte par elle-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Mais quelqu’un dira: Tu as la foi, et moi j’ai des œuvres. Montre-moi ta foi sans œuvres, et moi, par mes œuvres, je te montrerai ma foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Tu crois que Dieu est un; tu fais bien: les démons aussi croient, et ils frissonnent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Mais veux-tu savoir, ô homme vain, que la foi sans les œuvres est morte?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Abraham, notre père, n’a-t-il pas été justifié par des œuvres, ayant offert son fils Isaac sur l’autel?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Tu vois que la foi agissait avec ses œuvres; et par les œuvres la foi fut rendue parfaite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Et l’écriture a été accomplie qui dit: « Et Abraham crut Dieu, et cela lui fut compté à justice »; et il a été appelé ami de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vous voyez qu’un homme est justifié par les œuvres et non par la foi seulement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Et pareillement Rahab aussi, la prostituée, n’a-t-elle pas été justifiée par les œuvres, ayant reçu les messagers et les ayant mis dehors par un autre chemin?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Car comme le corps sans esprit est mort, ainsi aussi la foi sans les œuvres est morte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Ne soyez pas beaucoup de docteurs, mes frères, sachant que nous en recevrons un jugement plus sévère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'car nous faillissons tous à plusieurs égards. Si quelqu’un ne faillit pas en paroles, celui-là est un homme parfait, capable de tenir aussi tout le corps en bride.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Voici, nous mettons les mors des chevaux dans leurs bouches, pour qu’ils nous obéissent, et nous dirigeons çà et là leur corps tout entier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Voici, les navires aussi, qui sont si grands et qui sont poussés par des vents violents, sont dirigés çà et là par un très petit gouvernail, où que ce soit que le veuille l’impulsion de celui qui les gouverne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Ainsi aussi la langue est un petit membre et elle se vante de grandes choses. Voici, un petit feu, quelle grande forêt allume-t-il!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Et la langue est un feu. La langue, un monde d’iniquité, est établie parmi nos membres; c’est elle qui souille tout le corps, et enflamme tout le cours de la nature, et est enflammée par la géhenne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Car toute espèce de bêtes sauvages et d’oiseaux, de reptiles et d’animaux marins, se dompte et a été domptée par l’espèce humaine;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'mais pour la langue, aucun des hommes ne peut la dompter: c’est un mal désordonné, plein d’un venin mortel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Par elle nous bénissons le Seigneur et Père, et par elle nous maudissons les hommes faits à la ressemblance de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'de la même bouche procède la bénédiction et la malédiction. Mes frères, il ne devrait pas en être ainsi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Une fontaine fait-elle jaillir par une même ouverture le doux et l’amer?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Mes frères, un figuier peut-il produire des olives, ou une vigne, des figues? De l’eau salée ne peut pas non plus faire de l’eau douce.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Qui est sage et intelligent parmi vous? Que par une bonne conduite il montre ses œuvres avec la douceur de la sagesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Mais si vous avez une jalousie amère et un esprit de querelle dans vos cœurs, ne vous glorifiez pas et ne mentez pas contre la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Ce n’est pas là la sagesse qui descend d’en haut, mais [une sagesse] terrestre, animale, diabolique.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Car où il y a de la jalousie et un esprit de querelle, là il y a du désordre et toute espèce de mauvaises actions.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Mais la sagesse d’en haut est premièrement pure, ensuite paisible, modérée, traitable, pleine de miséricorde et de bons fruits, sans partialité, sans hypocrisie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Or le fruit de la justice, dans la paix, se sème pour ceux qui procurent la paix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'D’où viennent les guerres, et d’où les batailles parmi vous? N’est-ce pas de cela, de vos voluptés qui combattent dans vos membres?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Vous convoitez, et vous n’avez pas; vous tuez et vous avez d’ardents désirs, et vous ne pouvez obtenir; vous contestez et vous faites la guerre; vous n’avez pas, parce que vous ne demandez pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'vous demandez, et vous ne recevez pas, parce que vous demandez mal, afin de le dépenser pour vos voluptés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Adultères, ne savez-vous pas que l’amitié du monde est inimitié contre Dieu? Quiconque donc voudra être ami du monde, se constitue ennemi de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Ou pensez-vous que l’écriture parle en vain? L’Esprit qui demeure en nous, désire-t-il avec envie?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Mais il donne une plus grande grâce. C’est pourquoi il dit: « Dieu résiste aux orgueilleux, mais il donne [la] grâce aux humbles ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Soumettez-vous donc à Dieu. Résistez au diable, et il s’enfuira de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Approchez-vous de Dieu, et il s’approchera de vous. Nettoyez vos mains, pécheurs, et purifiez vos cœurs, vous qui êtes doubles de cœur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Sentez vos misères, et menez deuil et pleurez. Que votre rire se change en deuil, et votre joie en tristesse.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Humiliez-vous devant le ✶Seigneur, et il vous élèvera.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Ne parlez pas l’un contre l’autre, frères. Celui qui parle contre son frère ou qui juge son frère, parle contre la loi et juge la loi. Or si tu juges la loi, tu n’es pas un observateur de la loi, mais un juge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Un seul est législateur et juge, celui qui peut sauver et détruire; mais toi, qui es-tu qui juges ton prochain?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'À vous maintenant, qui dites: Aujourd’hui ou demain nous irons dans telle ou telle ville, et nous y passerons une année, et nous trafiquerons et nous gagnerons,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'vous qui ne savez pas ce [qui arrivera] le jour de demain; (car qu’est-ce que votre vie? car elle n’est qu’une vapeur paraissant pour un peu de temps et puis disparaissant;)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'au lieu de dire: Si le Seigneur le veut et si nous vivons, nous ferons aussi ceci ou cela.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Mais maintenant vous vous glorifiez dans vos vanteries. Toute jactance pareille est mauvaise.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Pour celui donc qui sait faire le bien et qui ne le fait pas, pour lui c’est pécher.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'À vous maintenant, riches! Pleurez en poussant des cris, à cause des misères qui vont venir sur vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Vos richesses sont pourries et vos vêtements sont rongés par les vers;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'votre or et votre argent sont rouillés, et leur rouille sera en témoignage contre vous et dévorera votre chair comme le feu: vous avez amassé un trésor dans les derniers jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Voici, le salaire des ouvriers qui ont moissonné vos champs et duquel ils ont été frustrés par vous, crie, et les cris de ceux qui ont moissonné sont parvenus aux oreilles du ✶Seigneur Sabaoth.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Vous avez vécu dans les délices sur la terre, et vous vous êtes livrés aux voluptés; vous avez rassasié vos cœurs [comme] en un jour de sacrifice;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'vous avez condamné, vous avez mis à mort le juste: il ne vous résiste pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Usez donc de patience, frères, jusqu’à la venue du Seigneur. Voici, le laboureur attend le fruit précieux de la terre, prenant patience à son égard, jusqu’à ce qu’il reçoive les pluies de la première et de la dernière saison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Vous aussi, usez de patience; affermissez vos cœurs, car la venue du Seigneur est proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Ne murmurez pas les uns contre les autres, frères, afin que vous ne soyez pas jugés: voici, le juge se tient devant la porte.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Mes frères, prenez pour exemple de souffrance et de patience les prophètes qui ont parlé au nom du ✶Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Voici, nous disons bienheureux ceux qui endurent [l’épreuve avec patience]. Vous avez entendu parler de la patience de Job, et vous avez vu la fin du ✶Seigneur, [savoir] que le ✶Seigneur est plein de compassion et miséricordieux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Mais avant toutes choses, mes frères, ne jurez pas, ni par le ciel, ni par la terre, ni par aucun autre serment; mais que votre oui soit oui, et votre non, non, afin que vous ne tombiez pas sous le jugement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Quelqu’un parmi vous est-il maltraité, qu’il prie. Quelqu’un est-il joyeux, qu’il chante des cantiques.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Quelqu’un parmi vous est-il malade, qu’il appelle les anciens de l’assemblée, et qu’ils prient pour lui en l’oignant d’huile au nom du Seigneur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'et la prière de la foi sauvera le malade, et le Seigneur le relèvera; et s’il a commis des péchés, il lui sera pardonné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Confessez donc vos fautes l’un à l’autre, et priez l’un pour l’autre, en sorte que vous soyez guéris: la fervente supplication du juste peut beaucoup.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Élie était un homme ayant les mêmes passions que nous, et il pria avec instance qu’il ne pleuve pas, et il ne tomba pas de pluie sur la terre durant trois ans et six mois;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'et il pria de nouveau, et le ciel donna de la pluie, et la terre produisit son fruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Mes frères, si quelqu’un parmi vous s’égare de la vérité, et que quelqu’un le ramène,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'qu’il sache que celui qui aura ramené un pécheur de l’égarement de son chemin, sauvera une âme de la mort et couvrira une multitude de péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Pierre, apôtre de Jésus Christ, à ceux de la dispersion, du Pont, de la Galatie, de la Cappadoce, de l’Asie et de la Bithynie, qui séjournent [parmi les nations], élus');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'selon la préconnaissance de Dieu le Père, en sainteté de l’Esprit, pour l’obéissance et l’aspersion du sang de Jésus Christ: Que la grâce et la paix vous soient multipliées!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Béni soit le Dieu et Père de notre seigneur Jésus Christ, qui, selon sa grande miséricorde, nous a régénérés pour une espérance vivante par la résurrection de Jésus Christ d’entre les morts,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'pour un héritage incorruptible, sans souillure, immarcescible, conservé dans les cieux pour vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'qui êtes gardés par la puissance de Dieu par la foi, pour un salut qui est prêt à être révélé au dernier temps;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'en quoi vous vous réjouissez, tout en étant affligés maintenant pour un peu de temps par diverses tentations, si cela est nécessaire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'afin que l’épreuve de votre foi, bien plus précieuse que celle de l’or qui périt et qui toutefois est éprouvé par le feu, soit trouvée [tourner] à louange, et à gloire, et à honneur, dans la révélation de Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'lequel, quoique vous ne l’ayez pas vu, vous aimez; et, croyant en lui, quoique maintenant vous ne le voyiez pas, vous vous réjouissez d’une joie ineffable et glorieuse,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'recevant la fin de votre foi, [le] salut des âmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'duquel salut les prophètes qui ont prophétisé de la grâce qui vous était destinée se sont informés et enquis avec soin,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'recherchant quel temps ou quelle sorte de temps l’Esprit de Christ qui était en eux indiquait, rendant par avance témoignage des souffrances qui devaient être la part de Christ et des gloires qui suivraient;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'et il leur fut révélé que ce n’était pas pour eux-mêmes, mais pour vous, qu’ils administraient ces choses, qui vous sont maintenant annoncées par ceux qui vous ont annoncé la bonne nouvelle par l’Esprit Saint envoyé du ciel, dans lesquelles des anges désirent de regarder de près.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'C’est pourquoi, ayant ceint les reins de votre entendement et étant sobres, espérez parfaitement dans la grâce qui vous sera apportée à la révélation de Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, '– comme des enfants d’obéissance, ne vous conformant pas à vos convoitises d’autrefois pendant votre ignorance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'mais, comme celui qui vous a appelés est saint, vous aussi soyez saints dans toute [votre] conduite;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'parce qu’il est écrit: « Soyez saints, car moi je suis saint ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Et si vous invoquez comme père celui qui, sans acception de personnes, juge selon l’œuvre de chacun, conduisez-vous avec crainte pendant le temps de votre séjour [ici-bas],');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'sachant que vous avez été rachetés de votre vaine conduite qui vous avait été enseignée par vos pères, non par des choses corruptibles, de l’argent ou de l’or,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'mais par le sang précieux de Christ, comme d’un agneau sans défaut et sans tache,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'préconnu dès avant la fondation du monde, mais manifesté à la fin des temps pour vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'qui, par lui, croyez en Dieu qui l’a ressuscité d’entre les morts et lui a donné la gloire, en sorte que votre foi et votre espérance soient en Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Ayant purifié vos âmes par l’obéissance à la vérité, pour [que vous ayez] une affection fraternelle sans hypocrisie, aimez-vous l’un l’autre ardemment, d’un cœur pur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'vous qui êtes régénérés, non par une semence corruptible, mais [par une semence] incorruptible, par la vivante et permanente parole de Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'parce que « toute chair est comme l’herbe, et toute sa gloire comme la fleur de l’herbe: l’herbe a séché et sa fleur est tombée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'mais la parole du ✶Seigneur demeure éternellement ». Or c’est cette parole qui vous a été annoncée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Rejetant donc toute malice et toute fraude, et l’hypocrisie et l’envie, et toutes médisances,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'désirez ardemment, comme des enfants nouveau-nés, le pur lait intellectuel, afin que vous croissiez par lui à salut,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'si toutefois vous avez goûté que le Seigneur est bon;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'duquel vous approchant [comme] d’une pierre vivante, rejetée par les hommes, mais choisie et précieuse auprès de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'vous-mêmes aussi, comme des pierres vivantes, êtes édifiés une maison spirituelle, une sainte sacrificature, pour offrir des sacrifices spirituels, agréables à Dieu par Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Parce qu’on trouve dans l’écriture: « Voici, je pose en Sion une maîtresse pierre de coin, élue, précieuse; et celui qui croit en elle ne sera point confus ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'C’est donc pour vous qui croyez, qu’elle a ce prix; mais pour les désobéissants, « la pierre que ceux qui bâtissaient ont rejetée, celle-là est devenue la maîtresse pierre du coin »,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, '« et une pierre d’achoppement et un rocher de chute », lesquels heurtent contre la parole, étant désobéissants, à quoi aussi ils ont été destinés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Mais vous, vous êtes une race élue, une sacrificature royale, une nation sainte, un peuple acquis, pour que vous annonciez les vertus de celui qui vous a appelés des ténèbres à sa merveilleuse lumière;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'vous qui autrefois n’étiez pas un peuple, mais qui maintenant êtes le peuple de Dieu; vous qui n’aviez pas obtenu miséricorde, mais qui maintenant avez obtenu miséricorde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Bien-aimés, je vous exhorte, comme forains et étrangers, à vous abstenir des convoitises charnelles, lesquelles font la guerre à l’âme,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'ayant une conduite honnête parmi les nations, afin que, quant aux choses dans lesquelles ils médisent de vous comme de gens qui font le mal, ils glorifient Dieu au jour de la visitation, à cause de vos bonnes œuvres qu’ils observent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Soyez donc soumis à tout ordre humain pour l’amour du Seigneur, soit au roi comme étant au-dessus de tous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'soit aux gouverneurs comme à ceux qui sont envoyés de sa part pour punir ceux qui font le mal et pour louer ceux qui font le bien;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'car c’est ici la volonté de Dieu, qu’en faisant le bien vous fermiez la bouche à l’ignorance des hommes dépourvus de sens,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'comme libres, et non comme ayant la liberté pour voile de la méchanceté, mais comme esclaves de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Honorez tous les hommes; aimez tous les frères; craignez Dieu; honorez le roi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Vous, domestiques, soyez soumis en toute crainte à vos maîtres, non seulement à ceux qui sont bons et doux, mais aussi à ceux qui sont fâcheux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'car c’est une chose digne de louange, si quelqu’un, par conscience envers Dieu, supporte des afflictions, souffrant injustement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Car quelle gloire y a-t-il, si, souffletés pour avoir mal fait, vous l’endurez? mais si, en faisant le bien, vous souffrez, et que vous l’enduriez, cela est digne de louange devant Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'car c’est à cela que vous avez été appelés; car aussi Christ a souffert pour vous, vous laissant un modèle, afin que vous suiviez ses traces,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, '« lui qui n’a pas commis de péché, et dans la bouche duquel il n’a pas été trouvé de fraude »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'qui, lorsqu’on l’outrageait, ne rendait pas d’outrage, quand il souffrait, ne menaçait pas, mais se remettait à celui qui juge justement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'qui lui-même a porté nos péchés en son corps sur le bois, afin qu’étant morts aux péchés, nous vivions à la justice; « par la meurtrissure duquel vous avez été guéris »;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'car vous étiez errants comme des brebis, mais maintenant vous êtes retournés au berger et au surveillant de vos âmes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Pareillement, vous, femmes, soyez soumises à vos propres maris, afin que, si même il y en a qui n’obéissent pas à la parole, ils soient gagnés sans [la] parole, par la conduite de leurs femmes,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'ayant observé la pureté de votre conduite dans la crainte,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, '– vous, dont la parure ne doit pas être [une parure] extérieure qui consiste à avoir les cheveux tressés et à être paré d’or et habillé de [beaux] vêtements,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'mais l’homme caché du cœur, dans l’incorruptibilité d’un esprit doux et paisible qui est d’un grand prix devant Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'car c’est ainsi que jadis se paraient aussi les saintes femmes qui espéraient en Dieu, étant soumises à leurs propres maris,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'comme Sara obéissait à Abraham, l’appelant seigneur, de laquelle vous êtes devenues les enfants, en faisant le bien et en ne craignant aucune frayeur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Pareillement, vous, maris, demeurez avec elles selon la connaissance, comme avec un vase plus faible, [c’est-à-dire] féminin, leur portant honneur comme étant aussi ensemble héritiers de la grâce de la vie, pour que vos prières ne soient pas interrompues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Enfin, soyez tous d’un même sentiment, sympathisants, fraternels, compatissants, humbles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'ne rendant pas mal pour mal, ou outrage pour outrage, mais au contraire bénissant, parce que vous avez été appelés à ceci, c’est que vous héritiez de la bénédiction;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, '« car celui qui veut aimer la vie et voir d’heureux jours, qu’il garde sa langue de mal, et ses lèvres de proférer la fraude;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'qu’il se détourne du mal et qu’il fasse le bien; qu’il recherche la paix et qu’il la poursuive;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'car les yeux du ✶Seigneur sont sur les justes et ses oreilles sont [tournées] vers leurs supplications; mais la face du ✶Seigneur est contre ceux qui font le mal ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Et qui est-ce qui vous fera du mal, si vous êtes devenus les imitateurs de celui qui est bon?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Mais, si même vous souffrez pour la justice, vous êtes bienheureux; « et ne craignez pas leurs craintes, et ne soyez pas troublés,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'mais sanctifiez le ✶Seigneur le Christ dans vos cœurs »; et soyez toujours prêts à répondre, mais avec douceur et crainte, à quiconque vous demande raison de l’espérance qui est en vous,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'ayant une bonne conscience, afin que, quant aux choses dans lesquelles ils médisent de vous comme de gens qui font le mal, ceux qui calomnient votre bonne conduite en Christ, soient confus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Car il vaut mieux, si la volonté de Dieu le voulait, souffrir en faisant le bien, qu’en faisant le mal;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'car aussi Christ a souffert une fois pour les péchés, [le] juste pour les injustes, afin qu’il nous amène à Dieu, ayant été mis à mort en chair, mais vivifié par l’Esprit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'par lequel aussi étant allé, il a prêché aux esprits [qui sont] en prison,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'qui ont été autrefois désobéissants, quand la patience de Dieu attendait dans les jours de Noé, tandis que l’arche se construisait, dans laquelle un petit nombre, savoir huit personnes, furent sauvées à travers l’eau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'or cet antitype vous sauve aussi maintenant, [c’est-à-dire] le baptême, non le dépouillement de la saleté de la chair, mais la demande à Dieu d’une bonne conscience, par la résurrection de Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'qui est à la droite de Dieu (étant allé au ciel), anges, et autorités, et puissances lui étant soumis.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Christ donc ayant souffert pour nous dans la chair, vous aussi, armez-vous de cette même pensée, que celui qui a souffert dans la chair s’est reposé du péché,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'pour ne plus vivre le reste de [son] temps dans la chair pour les convoitises des hommes, mais pour la volonté de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Car il nous suffit d’avoir accompli, dans le temps déjà écoulé, la volonté des nations, alors que nous marchions dans la débauche, les convoitises, l’ivrognerie, les excès dans le manger et le boire et les criminelles idolâtries,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'en quoi ils trouvent étrange que vous ne couriez pas avec eux dans le même bourbier de corruption, [vous] disant des injures;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'et ils rendront compte à celui qui est prêt à juger les vivants et les morts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Car c’est pour cela qu’il a été évangélisé à ceux aussi qui sont morts, afin qu’ils soient jugés, selon les hommes, quant à la chair; et qu’ils vivent, selon Dieu, quant à l’esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Mais la fin de toutes choses s’est approchée; soyez donc sobres et veillez pour prier;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'mais, avant toutes choses, ayant entre vous un amour fervent, car l’amour couvre une multitude de péchés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'étant hospitaliers les uns envers les autres, sans murmures.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Suivant que chacun de vous a reçu quelque don de grâce, employez-le les uns pour les autres, comme bons dispensateurs de la grâce variée de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Si quelqu’un parle, qu’il le fasse comme oracle de Dieu; si quelqu’un sert, qu’il serve comme par la force que Dieu fournit, afin qu’en toutes choses Dieu soit glorifié par Jésus Christ, à qui est la gloire et la puissance, aux siècles des siècles! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Bien-aimés, ne trouvez pas étrange le feu ardent qui est au milieu de vous, qui est venu sur vous pour votre épreuve, comme s’il vous arrivait quelque chose d’extraordinaire;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'mais, en tant que vous avez part aux souffrances de Christ, réjouissez-vous, afin qu’aussi, à la révélation de sa gloire, vous vous réjouissiez avec transport.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Si vous êtes insultés pour le nom de Christ, vous êtes bienheureux, car l’Esprit de gloire et de Dieu repose sur vous: [de leur part, il est blasphémé, mais quant à vous, glorifié].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Mais que nul de vous ne souffre comme meurtrier ou voleur, ou comme faisant le mal, ou s’ingérant dans les affaires d’autrui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'mais si [quelqu’un souffre] comme chrétien, qu’il n’en ait pas honte, mais qu’il glorifie Dieu en ce nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Car le temps [est venu] de commencer le jugement par la maison de Dieu; mais s’il commence premièrement par nous, quelle sera la fin de ceux qui n’obéissent pas à l’évangile de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Et si le juste est sauvé difficilement, où paraîtra l’impie et le pécheur?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Que ceux donc aussi qui souffrent selon la volonté de Dieu, remettent leurs âmes en faisant le bien, à un fidèle créateur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'J’exhorte les anciens qui sont parmi vous, moi qui suis ancien avec eux et témoin des souffrances de Christ, qui aussi ai part à la gloire qui va être révélée:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'paissez le troupeau de Dieu qui est avec vous, le surveillant, non point par contrainte, mais volontairement, ni pour un gain honteux, mais de bon gré,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'ni comme dominant sur des héritages, mais en étant [les] modèles du troupeau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'et quand le souverain pasteur sera manifesté, vous recevrez la couronne inflétrissable de gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Pareillement, vous, jeunes gens, soyez soumis aux anciens; et tous, les uns à l’égard des autres, soyez revêtus d’humilité; car Dieu résiste aux orgueilleux, mais il donne [la] grâce aux humbles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Humiliez-vous donc sous la puissante main de Dieu, afin qu’il vous élève quand le temps sera venu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'rejetant sur lui tout votre souci, car il a soin de vous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Soyez sobres, veillez: votre adversaire, le diable, comme un lion rugissant, rôde autour [de vous], cherchant qui il pourra dévorer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Résistez-lui, étant fermes dans la foi, sachant que les mêmes souffrances s’accomplissent dans vos frères qui sont dans le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Mais le Dieu de toute grâce, qui vous a appelés à sa gloire éternelle dans le christ Jésus, lorsque vous aurez souffert un peu de temps, vous rendra lui-même accomplis, vous affermira, vous fortifiera, et vous établira sur un fondement [inébranlable].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'À lui [la gloire et] la puissance, aux siècles des siècles! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Je vous ai écrit brièvement par Silvain, qui est un frère fidèle, comme je le pense, vous exhortant et attestant que cette [grâce] dans laquelle vous êtes est la vraie grâce de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Celle qui est élue avec vous à Babylone, vous salue, et Marc, mon fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Saluez-vous les uns les autres par un baiser d’amour. Paix soit à vous tous qui êtes en Christ!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Siméon Pierre, esclave et apôtre de Jésus Christ, à ceux qui ont reçu en partage une foi de pareil prix avec nous, par [la] justice de notre Dieu et Sauveur Jésus Christ:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Que la grâce et la paix vous soient multipliées dans la connaissance de Dieu et de Jésus notre Seigneur!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Comme sa divine puissance nous a donné tout ce qui regarde la vie et la piété, par la connaissance de celui qui nous a appelés par [la] gloire et par [la] vertu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'par lesquelles il nous a donné les très grandes et précieuses promesses, afin que par elles vous participiez de la nature divine, ayant échappé à la corruption qui est dans le monde par la convoitise...;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'pour cette même raison aussi, y apportant tout empressement, joignez à votre foi, la vertu; et à la vertu, la connaissance;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'et à la connaissance, la tempérance; et à la tempérance, la patience; et à la patience, la piété;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'et à la piété, l’affection fraternelle; et à l’affection fraternelle, l’amour;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'car, si ces choses sont en vous et y abondent, elles font que vous ne serez pas oisifs ni stériles pour ce qui regarde la connaissance de notre Seigneur Jésus Christ;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'car celui en qui ces choses ne se trouvent pas est aveugle, et ne voit pas loin, ayant oublié la purification de ses péchés d’autrefois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'C’est pourquoi, frères, étudiez-vous d’autant plus à affermir votre appel et votre élection, car en faisant ces choses vous ne faillirez jamais;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'car ainsi l’entrée dans le royaume éternel de notre Seigneur et Sauveur Jésus Christ vous sera richement donnée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'C’est pourquoi je m’appliquerai à vous faire souvenir toujours de ces choses, quoique vous les connaissiez et que vous soyez affermis dans la vérité présente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Mais j’estime qu’il est juste, tant que je suis dans cette tente, de vous réveiller en rappelant [ces choses] à votre mémoire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'sachant que le moment de déposer ma tente s’approche rapidement, comme aussi notre Seigneur Jésus Christ me l’a montré;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'mais je m’étudierai à ce qu’après mon départ vous puissiez aussi en tout temps vous rappeler ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Car ce n’est pas en suivant des fables ingénieusement imaginées, que nous vous avons fait connaître la puissance et la venue de notre Seigneur Jésus Christ, mais comme ayant été témoins oculaires de sa majesté.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Car il reçut de Dieu le Père honneur et gloire, lorsqu’une telle voix lui fut adressée par la gloire magnifique: « Celui-ci est mon Fils bien-aimé, en qui j’ai trouvé mon plaisir ».');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Et nous, nous avons entendu cette voix venue du ciel, étant avec lui sur la sainte montagne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Et nous avons la parole prophétique [rendue] plus ferme, (à laquelle vous faites bien d’être attentifs, comme à une lampe qui brille dans un lieu obscur), jusqu’à ce que [le] jour ait commencé à luire et que [l’]étoile du matin se soit levée dans vos cœurs,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'sachant ceci premièrement, qu’aucune prophétie de l’écriture ne s’interprète elle-même.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Car [la] prophétie n’est jamais venue par la volonté de l’homme, mais de saints hommes de Dieu ont parlé, étant poussés par l’Esprit Saint.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Or il y a eu aussi de faux prophètes parmi le peuple, comme aussi il y aura parmi vous de faux docteurs qui introduiront furtivement des sectes de perdition, reniant aussi le maître qui les a achetés, faisant venir sur eux-mêmes une prompte destruction;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'et plusieurs suivront leurs excès: et à cause d’eux la voie de la vérité sera blasphémée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'et, par cupidité, ils feront trafic de vous avec des paroles artificieuses; mais leur jugement, dès longtemps, ne demeure pas oisif, et leur destruction ne sommeille pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Car, si Dieu n’a pas épargné les anges qui ont péché, mais, les ayant précipités dans l’abîme, les a livrés pour être gardés dans des chaînes d’obscurité pour le jugement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, '– et s’il n’a pas épargné l’ancien monde, mais a préservé Noé, lui huitième, prédicateur de justice, faisant venir [le] déluge sur un monde d’impies;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, '– et si, réduisant en cendres les villes de Sodome et de Gomorrhe, il les a condamnées par une totale subversion, les établissant pour être un exemple à ceux qui vivraient dans l’impiété;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'et s’il a délivré le juste Lot, accablé par la conduite débauchée de ces hommes pervers,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(car ce juste qui habitait parmi eux, les voyant et les entendant, tourmentait de jour en jour son âme juste à cause de leurs actions iniques,)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, '– le Seigneur sait délivrer de la tentation les hommes pieux, et réserver les injustes pour le jour du jugement, pour être punis,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'mais spécialement ceux qui suivent la chair dans la convoitise de l’impureté et qui méprisent la domination. Gens audacieux, adonnés à leur sens, ils ne tremblent pas en injuriant les dignités,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'tandis que les anges, plus grands en force et en puissance, ne portent pas contre elles de jugement injurieux devant le ✶Seigneur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Mais ceux-ci, comme des bêtes sans raison, [purement] animales, nées pour être prises et détruites, parlant injurieusement dans les choses qu’ils ignorent, périront aussi dans leur propre corruption,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'recevant la récompense de l’iniquité, estimant plaisir les voluptés d’un jour; – des taches et des souillures, s’abandonnant aux délices de leurs propres tromperies tout en faisant des festins avec vous;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'ayant les yeux pleins d’adultère et ne cessant jamais de pécher; amorçant les âmes mal affermies, ayant le cœur exercé à la cupidité, enfants de malédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Ayant laissé le droit chemin, ils se sont égarés, ayant suivi le chemin de Balaam, [fils] de Bosor, qui aima le salaire d’iniquité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'mais il fut repris de sa propre désobéissance: une bête de somme muette, parlant d’une voix d’homme, réprima la folie du prophète.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ce sont des fontaines sans eau et des nuages poussés par la tempête, [des gens] à qui l’obscurité des ténèbres est réservée pour toujours;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'car, en prononçant d’orgueilleux discours de vanité, ils amorcent par les convoitises de la chair, par leurs impudicités, ceux qui avaient depuis peu échappé à ceux qui vivent dans l’erreur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, '– leur promettant la liberté, eux qui sont esclaves de la corruption; car on est esclave de celui par qui on est vaincu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Car, si, après avoir échappé aux souillures du monde par la connaissance du Seigneur et Sauveur Jésus Christ, étant de nouveau enlacés, ils sont vaincus par elles, leur dernière condition est pire que la première;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'car il leur aurait mieux valu n’avoir pas connu la voie de la justice, que de se détourner, après l’avoir connue, du saint commandement qui leur avait été donné;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'mais ce que dit le proverbe véritable leur est arrivé: Le chien est retourné à ce qu’il avait vomi lui-même, et la truie lavée, à se vautrer au bourbier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Je vous écris déjà, bien-aimés, cette seconde lettre; et, dans l’une et dans l’autre, je réveille votre pure intelligence en rappelant [ces choses] à votre mémoire,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'afin que vous vous souveniez des paroles qui ont été dites à l’avance par les saints prophètes, et du commandement du Seigneur et Sauveur par vos apôtres,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'sachant tout d’abord ceci, qu’aux derniers jours des moqueurs viendront, marchant dans la moquerie selon leurs propres convoitises');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'et disant: Où est la promesse de sa venue? car, depuis que les pères se sont endormis, toutes choses demeurent au même état dès le commencement de la création.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Car ils ignorent volontairement ceci, que, par la parole de Dieu, des cieux subsistaient jadis, et une terre [tirée] des eaux et subsistant au milieu des eaux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'par lesquelles le monde d’alors fut détruit, étant submergé par de l’eau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Mais les cieux et la terre de maintenant sont réservés par sa parole pour le feu, gardés pour le jour du jugement et de la destruction des hommes impies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Mais n’ignorez pas cette chose, bien-aimés, c’est qu’un jour est devant le ✶Seigneur comme 1 000 ans, et 1 000 ans comme un jour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Le ✶Seigneur ne tarde pas pour ce qui concerne la promesse, comme quelques-uns estiment qu’il y a du retardement; mais il est patient envers vous, ne voulant pas qu’aucun périsse, mais que tous viennent à la repentance.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Or le jour du ✶Seigneur viendra comme un voleur; et, dans ce jour-là, les cieux passeront avec un bruit sifflant, et les éléments embrasés seront dissous, et la terre et les œuvres qui sont en elle seront brûlées entièrement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Toutes ces choses devant donc se dissoudre, quelles [gens] devriez-vous être en sainte conduite et en piété,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'attendant et hâtant la venue du jour de Dieu, à cause duquel les cieux en feu seront dissous et les éléments embrasés se fondront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Mais, selon sa promesse, nous attendons de nouveaux cieux et une nouvelle terre, dans lesquels la justice habite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'C’est pourquoi, bien-aimés, en attendant ces choses, étudiez-vous à être trouvés sans tache et irréprochables devant lui, en paix;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'et estimez que la patience de notre Seigneur est salut, comme notre bien-aimé frère Paul aussi vous a écrit selon la sagesse qui lui a été donnée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'ainsi qu’[il le fait] aussi dans toutes ses lettres, où il parle de ces choses, parmi lesquelles il y en a de difficiles à comprendre, que les ignorants et les mal affermis tordent, comme aussi les autres écritures, à leur propre destruction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Vous donc, bien-aimés, sachant [ces choses] à l’avance, prenez garde, de peur qu’étant entraînés par l’erreur des pervers, vous ne veniez à déchoir de votre propre fermeté;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'mais croissez dans la grâce et dans la connaissance de notre Seigneur et Sauveur Jésus Christ. À lui la gloire, et maintenant et jusqu’au jour d’éternité! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Ce qui était dès le commencement, ce que nous avons entendu, ce que nous avons vu de nos yeux, ce que nous avons contemplé et que nos mains ont touché, concernant la parole de la vie');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(et la vie a été manifestée; et nous avons vu, et nous déclarons, et nous vous annonçons la vie éternelle, qui était auprès du Père et qui nous a été manifestée);');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'ce que nous avons vu et entendu, nous vous l’annonçons, afin que vous aussi vous ayez communion avec nous: or notre communion est avec le Père et avec son Fils Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Et nous vous écrivons ces choses, afin que votre joie soit accomplie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Et c’est ici le message que nous avons entendu de lui et que nous vous annonçons, [savoir] que Dieu est lumière et qu’il n’y a en lui aucunes ténèbres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Si nous disons que nous avons communion avec lui, et que nous marchions dans les ténèbres, nous mentons et nous ne pratiquons pas la vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'mais si nous marchons dans la lumière, comme lui-même est dans la lumière, nous avons communion les uns avec les autres, et le sang de Jésus Christ son Fils nous purifie de tout péché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Si nous disons que nous n’avons pas de péché, nous nous séduisons nous-mêmes, et la vérité n’est pas en nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Si nous confessons nos péchés, il est fidèle et juste pour nous pardonner nos péchés et nous purifier de toute iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Si nous disons que nous n’avons pas péché, nous le faisons menteur et sa parole n’est pas en nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Mes enfants, je vous écris ces choses afin que vous ne péchiez pas; et si quelqu’un a péché, nous avons un avocat auprès du Père, Jésus Christ, le juste;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'et lui est la propitiation pour nos péchés, et non pas seulement pour les nôtres, mais aussi pour le monde entier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Et par ceci nous savons que nous le connaissons, [savoir] si nous gardons ses commandements.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Celui qui dit: Je le connais, et qui ne garde pas ses commandements, est menteur, et la vérité n’est pas en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Mais quiconque garde sa parole, – en lui l’amour de Dieu est véritablement consommé: par cela nous savons que nous sommes en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Celui qui dit demeurer en lui, doit lui-même aussi marcher comme lui a marché.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Bien-aimés, je ne vous écris pas un commandement nouveau, mais un commandement ancien que vous avez eu dès le commencement. Le commandement ancien est la parole que vous avez entendue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Encore une fois, je vous écris un commandement nouveau, ce qui est vrai en lui et en vous, parce que les ténèbres s’en vont et que la vraie lumière luit déjà.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Celui qui dit être dans la lumière et qui hait son frère, est dans les ténèbres jusqu’à maintenant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Celui qui aime son frère demeure dans la lumière, et il n’y a point en lui d’occasion de chute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Mais celui qui hait son frère est dans les ténèbres, et il marche dans les ténèbres, et il ne sait où il va, parce que les ténèbres ont aveuglé ses yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Je vous écris, enfants, parce que vos péchés vous sont pardonnés par son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Je vous écris, pères, parce que vous connaissez celui qui est dès le commencement. Je vous écris, jeunes gens, parce que vous avez vaincu le méchant. Je vous écris, petits enfants, parce que vous connaissez le Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Je vous ai écrit, pères, parce que vous connaissez celui qui est dès le commencement. Je vous ai écrit, jeunes gens, parce que vous êtes forts, et que la parole de Dieu demeure en vous, et que vous avez vaincu le méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'N’aimez pas le monde, ni les choses qui sont dans le monde: si quelqu’un aime le monde, l’amour du Père n’est pas en lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'parce que tout ce qui est dans le monde, la convoitise de la chair, et la convoitise des yeux, et l’orgueil de la vie, n’est pas du Père, mais est du monde;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'et le monde s’en va et sa convoitise, mais celui qui fait la volonté de Dieu demeure éternellement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Petits enfants, c’est la dernière heure; et comme vous avez entendu que l’antichrist vient, maintenant aussi il y a plusieurs antichrists, par quoi nous savons que c’est la dernière heure:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'ils sont sortis du milieu de nous, mais ils n’étaient pas des nôtres; car s’ils avaient été des nôtres, ils seraient demeurés avec nous; mais c’est afin qu’ils soient manifestés comme n’étant aucun [d’eux] des nôtres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Et vous, vous avez l’onction de la part du Saint et vous connaissez toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Je ne vous ai pas écrit parce que vous ne connaissez pas la vérité, mais parce que vous la connaissez et qu’aucun mensonge ne vient de la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Qui est le menteur, sinon celui qui nie que Jésus est le Christ? Celui-là est l’antichrist, qui nie le Père et le Fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Quiconque nie le Fils n’a pas non plus le Père; celui qui confesse le Fils a aussi le Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Pour vous, que ce que vous avez entendu dès le commencement demeure en vous: si ce que vous avez entendu dès le commencement demeure en vous, vous aussi vous demeurerez dans le Fils et dans le Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Et c’est ici la promesse que lui nous a promise, – la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Je vous ai écrit ces choses touchant ceux qui vous égarent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'et, pour vous, l’onction que vous avez reçue de lui demeure en vous, et vous n’avez pas besoin que personne vous enseigne; mais comme la même onction vous enseigne à l’égard de toutes choses, et qu’elle est vraie et n’est pas mensonge, – et selon qu’elle vous a enseignés, vous demeurerez en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Et maintenant, enfants, demeurez en lui, afin que, quand il sera manifesté, nous ayons de l’assurance et que nous ne soyons pas couverts de honte, de par lui, à sa venue.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Si vous savez qu’il est juste, sachez que quiconque pratique la justice est né de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, '– Voyez de quel amour le Père nous a fait don, que nous soyons appelés enfants de Dieu; c’est pourquoi le monde ne nous connaît pas, parce qu’il ne l’a pas connu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Bien-aimés, nous sommes maintenant enfants de Dieu, et ce que nous serons n’a pas encore été manifesté; nous savons que quand il sera manifesté, nous lui serons semblables, car nous le verrons comme il est.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Et quiconque a cette espérance en lui se purifie, comme lui est pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Quiconque pratique le péché, pratique aussi l’iniquité, et le péché est l’iniquité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Et vous savez que lui a été manifesté, afin qu’il ôte nos péchés; et il n’y a point de péché en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Quiconque demeure en lui ne pèche pas; quiconque pèche ne l’a pas vu, ni ne l’a pas connu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Enfants, que personne ne vous égare: celui qui pratique la justice est juste, comme lui est juste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Celui qui pratique le péché est du diable, car dès le commencement le diable pèche. C’est pour ceci que le Fils de Dieu a été manifesté, afin qu’il détruise les œuvres du diable.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Quiconque est né de Dieu ne pratique pas le péché, car la semence de Dieu demeure en lui, et il ne peut pas pécher, parce qu’il est né de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Par ceci sont [rendus] manifestes les enfants de Dieu et les enfants du diable: quiconque ne pratique pas la justice n’est pas de Dieu, et celui qui n’aime pas son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Car c’est ici le message que vous avez entendu dès le commencement, [savoir] que nous nous aimions l’un l’autre,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'non comme Caïn était du méchant et tua son frère. Et pour quelle raison le tua-t-il? Parce que ses œuvres étaient mauvaises et que celles de son frère étaient justes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Ne vous étonnez pas, frères, si le monde vous hait.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Nous, nous savons que nous sommes passés de la mort à la vie, parce que nous aimons les frères; celui qui n’aime pas son frère demeure dans la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Quiconque hait son frère est un meurtrier, et vous savez qu’aucun meurtrier n’a la vie éternelle demeurant en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Par ceci nous avons connu l’amour, c’est que lui a laissé sa vie pour nous; et nous, nous devons laisser nos vies pour les frères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Mais celui qui a les biens de ce monde, et qui voit son frère dans le besoin, et qui lui ferme ses entrailles, comment l’amour de Dieu demeure-t-il en lui?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Enfants, n’aimons pas de parole ni de langue, mais en action et en vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Et par ceci nous saurons que nous sommes de la vérité, et nous assurerons nos cœurs devant lui');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, '– que, si notre cœur nous condamne, Dieu est plus grand que notre cœur et il sait toutes choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Bien-aimés, si notre cœur ne nous condamne pas, nous avons de l’assurance envers Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'et quoi que nous demandions, nous le recevons de lui, parce que nous gardons ses commandements et que nous pratiquons les choses qui sont agréables devant lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, '– Et c’est ici son commandement, que nous croyions au nom de son Fils Jésus Christ et que nous nous aimions l’un l’autre, selon qu’il nous en a donné le commandement;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'et celui qui garde ses commandements demeure en lui, et lui en cet homme; et par ceci nous savons qu’il demeure en nous, [savoir] par l’Esprit qu’il nous a donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Bien-aimés, ne croyez pas tout esprit, mais éprouvez les esprits [pour voir] s’ils sont de Dieu, car beaucoup de faux prophètes sont sortis dans le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Par ceci vous connaissez l’Esprit de Dieu: tout esprit qui confesse Jésus Christ venu en chair est de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'et tout esprit qui ne confesse pas Jésus Christ venu en chair n’est pas de Dieu; et ceci est l’[esprit] de l’antichrist, duquel vous avez entendu dire qu’il vient, et déjà maintenant il est dans le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Pour vous, enfants, vous êtes de Dieu, et vous les avez vaincus, parce que celui qui est en vous est plus grand que celui qui est dans le monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Pour eux, ils sont du monde; c’est pourquoi ils parlent selon les principes du monde, et le monde les écoute.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Nous, nous sommes de Dieu; celui qui connaît Dieu nous écoute; celui qui n’est pas de Dieu ne nous écoute pas: à cela nous connaissons l’esprit de vérité et l’esprit d’erreur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Bien-aimés, aimons-nous l’un l’autre, car l’amour est de Dieu, et quiconque aime est né de Dieu et connaît Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Celui qui n’aime pas n’a pas connu Dieu, car Dieu est amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'En ceci a été manifesté l’amour de Dieu pour nous, c’est que Dieu a envoyé son Fils unique dans le monde, afin que nous vivions par lui;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'en ceci est l’amour, non en ce que nous, nous ayons aimé Dieu, mais en ce que lui nous aima et qu’il envoya son Fils [pour être la] propitiation pour nos péchés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Bien-aimés, si Dieu nous aima ainsi, nous aussi nous devons nous aimer l’un l’autre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Personne ne vit jamais Dieu; si nous nous aimons l’un l’autre, Dieu demeure en nous, et son amour est consommé en nous.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Par ceci nous savons que nous demeurons en lui et lui en nous, c’est qu’il nous a donné de son Esprit;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'et nous, nous avons vu et nous témoignons que le Père a envoyé le Fils [pour être le] Sauveur du monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Quiconque confessera que Jésus est le Fils de Dieu, Dieu demeure en lui et lui en Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Et nous avons connu et cru l’amour que Dieu a pour nous. Dieu est amour, et celui qui demeure dans l’amour, demeure en Dieu et Dieu en lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'En ceci est consommé l’amour avec nous, afin que nous ayons toute assurance au jour du jugement, c’est que, comme il est, lui, nous sommes, nous aussi, dans ce monde.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Il n’y a pas de crainte dans l’amour, mais l’amour parfait chasse la crainte, car la crainte porte avec elle du tourment; et celui qui craint n’est pas consommé dans l’amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Nous, nous l’aimons parce que lui nous a aimés le premier.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Si quelqu’un dit: J’aime Dieu, et qu’il haïsse son frère, il est menteur; car celui qui n’aime pas son frère qu’il voit, comment peut-il aimer Dieu qu’il ne voit pas?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Et nous avons ce commandement de sa part, que celui qui aime Dieu, aime aussi son frère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Quiconque croit que Jésus est le Christ, est né de Dieu; et quiconque aime celui qui a engendré, aime aussi celui qui est engendré de lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Par ceci nous savons que nous aimons les enfants de Dieu, c’est quand nous aimons Dieu et que nous gardons ses commandements;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'car c’est ici l’amour de Dieu, que nous gardions ses commandements, et ses commandements ne sont pas pénibles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'parce que tout ce qui est né de Dieu est victorieux du monde; et c’est ici la victoire qui a vaincu le monde, [savoir] notre foi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Qui est celui qui est victorieux du monde, sinon celui qui croit que Jésus est le Fils de Dieu?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'C’est lui qui est venu par [l’]eau et par [le] sang, Jésus le Christ, non seulement dans [la puissance de] l’eau, mais dans [la puissance de] l’eau et du sang; et c’est l’Esprit qui rend témoignage, car l’Esprit est la vérité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'car il y en a trois qui rendent témoignage:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'l’Esprit, et l’eau, et le sang, et les trois sont [d’accord] pour un même [témoignage].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Si nous recevons le témoignage des hommes, le témoignage de Dieu est plus grand; car c’est ici le témoignage de Dieu qu’il a rendu au sujet de son Fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Celui qui croit au Fils de Dieu, a le témoignage au-dedans de lui-même; celui qui ne croit pas Dieu, l’a fait menteur, car il n’a pas cru au témoignage que Dieu a rendu au sujet de son Fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Et c’est ici le témoignage: que Dieu nous a donné la vie éternelle, et cette vie est dans son Fils:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Celui qui a le Fils a la vie, celui qui n’a pas le Fils de Dieu n’a pas la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Je vous ai écrit ces choses afin que vous sachiez que vous avez la vie éternelle, vous qui croyez au nom du Fils de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Et c’est ici la confiance que nous avons en lui, que si nous demandons quelque chose selon sa volonté, il nous écoute;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'et si nous savons qu’il nous écoute, quoi que ce soit que nous demandions, nous savons que nous avons les choses que nous lui avons demandées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Si quelqu’un voit son frère pécher d’un péché qui ne soit pas à la mort, il demandera [pour lui]; et il lui donnera la vie, [savoir] à ceux qui ne pèchent pas à la mort. Il y a un péché à la mort: pour ce péché-là, je ne dis pas qu’il demande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Toute iniquité est péché, et il y a tel péché qui n’est pas à la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Nous savons que quiconque est né de Dieu ne pèche pas, mais celui qui est né de Dieu se conserve lui-même, et le méchant ne le touche pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Nous savons que nous sommes de Dieu, et que le monde entier gît dans le méchant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Or nous savons que le Fils de Dieu est venu, et il nous a donné une intelligence afin que nous connaissions le Véritable, et nous sommes dans le Véritable, [savoir] dans son Fils Jésus Christ: lui est le Dieu véritable et la vie éternelle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Enfants, gardez-vous des idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'L’ancien à la dame élue et à ses enfants, que j’aime dans [la] vérité, – et non pas moi seul, mais aussi tous ceux qui connaissent la vérité,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, '– à cause de la vérité qui demeure en nous et qui sera avec nous à jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'La grâce, la miséricorde, la paix, seront avec vous de la part de Dieu le Père et de la part du seigneur Jésus Christ le Fils du Père, dans [la] vérité et [dans l’]amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Je me suis fort réjoui d’avoir trouvé de tes enfants marchant dans [la] vérité, comme nous en avons reçu le commandement de la part du Père.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Or maintenant, ô dame, je te prie, non comme t’écrivant un nouveau commandement, mais celui que nous avons eu dès le commencement, que nous nous aimions les uns les autres:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'et c’est ici l’amour, que nous marchions selon ses commandements. C’est ici le commandement, comme vous l’avez entendu dès le commencement, afin que vous y marchiez;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'car plusieurs séducteurs sont sortis dans le monde, ceux qui ne confessent pas Jésus Christ venant en chair: celui-là est le séducteur et l’antichrist.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Prenez garde à vous-mêmes, afin que nous ne perdions pas ce que nous avons opéré, mais que nous recevions un plein salaire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Quiconque [vous] mène en avant et ne demeure pas dans la doctrine du Christ, n’a pas Dieu. Celui qui demeure dans la doctrine, celui-là a le Père et le Fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Si quelqu’un vient à vous et n’apporte pas cette doctrine, ne le recevez pas dans votre maison et ne le saluez pas,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'car celui qui le salue participe à ses mauvaises œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Ayant beaucoup de choses à vous écrire, je n’ai pas voulu le faire avec du papier et de l’encre, mais j’espère aller vers vous et vous parler bouche à bouche, afin que notre joie soit accomplie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Les enfants de ta sœur élue te saluent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'L’ancien à Gaïus, le bien-aimé, que j’aime dans [la] vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Bien-aimé, je souhaite qu’à tous égards tu prospères et que tu sois en bonne santé, comme ton âme prospère;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'car je me suis très fort réjoui quand des frères sont venus et ont rendu témoignage à ta vérité, comment toi tu marches dans la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Je n’ai pas de plus grande joie que ceci, c’est que j’entende dire que mes enfants marchent dans la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Bien-aimé, tu agis fidèlement dans tout ce que tu fais envers les frères, et cela [envers ceux-là même qui sont] étrangers,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'qui ont rendu témoignage à ton amour devant l’assemblée; et tu feras bien de leur faire la conduite d’une manière digne de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'car ils sont sortis pour le nom, ne recevant rien de ceux des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Nous donc, nous devons recevoir de tels hommes, afin que nous coopérions avec la vérité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'J’ai écrit quelque chose à l’assemblée; mais Diotrèphe, qui aime à être le premier parmi eux, ne nous reçoit pas;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'c’est pourquoi, si je viens, je me souviendrai des œuvres qu’il fait en débitant de méchantes paroles contre nous; et, non content de cela, lui-même il ne reçoit pas les frères et il empêche ceux qui veulent [les recevoir], et les chasse de l’assemblée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Bien-aimé, n’imite pas le mal, mais le bien. Celui qui fait le bien est de Dieu; celui qui fait le mal n’a pas vu Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Démétrius a le témoignage de tous et de la vérité elle-même; et nous aussi, nous lui rendons témoignage: et tu sais que notre témoignage est vrai.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'J’avais beaucoup de choses à t’écrire, mais je ne veux pas t’écrire avec l’encre et la plume,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'mais j’espère te voir bientôt et nous parlerons bouche à bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Paix te soit. Les amis te saluent. Salue les amis, chacun par son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Jude, esclave de Jésus Christ et frère de Jacques, aux appelés, bien-aimés en Dieu le Père, et conservés en Jésus Christ:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Que la miséricorde, et la paix, et l’amour vous soient multipliés!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Bien-aimés, quand j’usais de toute diligence pour vous écrire de notre commun salut, je me suis trouvé dans la nécessité de vous écrire afin de vous exhorter à combattre pour la foi qui a été une fois enseignée aux saints;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'car certains hommes se sont glissés [parmi les fidèles], inscrits jadis à l’avance pour ce jugement, des impies, qui changent la grâce de notre Dieu en dissolution, et qui renient notre seul maître et seigneur, Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Or je désire vous rappeler, à vous qui une fois saviez tout, que le Seigneur, ayant délivré le peuple du pays d’Égypte, a détruit ensuite ceux qui n’ont pas cru;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, '– et qu’il a réservé dans des liens éternels, sous l’obscurité, pour le jugement du grand jour, les anges qui n’ont pas gardé leur origine, mais qui ont abandonné leur propre demeure;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'comme Sodome et Gomorrhe, et les villes d’alentour, s’étant abandonnées à la fornication de la même manière que ceux-là, et étant allées après une autre chair, sont là comme exemple, subissant la peine d’un feu éternel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'De la même manière cependant, ces rêveurs aussi souillent la chair, et méprisent la domination, et injurient les dignités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Mais Michel l’archange, quand, discutant avec le diable, il contestait touchant le corps de Moïse, n’osa pas proférer de jugement injurieux contre [lui]; mais il dit: Que le ✶Seigneur te censure!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Mais ceux-ci, ils injurient tout ce qu’ ils ne connaissent pas, et se corrompent dans tout ce qu’ils comprennent naturellement comme des bêtes sans raison.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Malheur à eux, car ils ont marché dans le chemin de Caïn, et se sont abandonnés à l’erreur de Balaam pour une récompense, et ont péri dans la contradiction de Coré.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Ceux-ci, ils sont des taches dans vos agapes, faisant des festins avec vous sans crainte, se repaissant eux-mêmes: nuées sans eau, emportées par les vents; arbres d’automne, sans fruit, deux fois morts, déracinés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'vagues impétueuses de la mer, jetant l’écume de leurs infamies; étoiles errantes, à qui l’obscurité des ténèbres est réservée pour toujours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Or Énoch aussi, le septième depuis Adam, a prophétisé de ceux-ci, en disant: Voici, le Seigneur est venu au milieu de ses saintes myriades,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'pour exécuter le jugement contre tous, et pour convaincre tous les impies d’entre eux de toutes leurs œuvres d’impiété qu’ils ont impiement commises et de toutes les [paroles] dures que les pécheurs impies ont proférées contre lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Ceux-ci, ils sont des murmurateurs, se plaignant de leur sort, marchant selon leurs propres convoitises (tandis que leur bouche prononce d’orgueilleux discours), et admirant les hommes en vue de [leur propre] profit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Mais vous, bien-aimés, souvenez-vous des paroles qui ont été dites auparavant par les apôtres de notre seigneur Jésus Christ,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'comment ils vous disaient que, à la fin du temps, il y aurait des moqueurs, marchant selon leurs propres convoitises d’impiétés;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'ceux-ci sont ceux qui se séparent [eux-mêmes], des hommes naturels, n’ayant pas l’Esprit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Mais vous, bien-aimés, vous édifiant vous-mêmes sur votre très sainte foi, priant par le Saint Esprit,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'conservez-vous dans l’amour de Dieu, attendant la miséricorde de notre seigneur Jésus Christ pour la vie éternelle;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'et les uns qui contestent, reprenez-les;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'les autres sauvez-les avec crainte, les arrachant hors du feu, haïssant même le vêtement souillé par la chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Or, à celui qui a le pouvoir de vous garder sans que vous bronchiez et de vous placer irréprochables devant sa gloire avec abondance de joie,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, '– au seul Dieu, notre Sauveur, par notre seigneur Jésus Christ, gloire, majesté, force et pouvoir, dès avant tout siècle, et maintenant, et pour tous les siècles! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Révélation de Jésus Christ, que Dieu lui a donnée pour montrer à ses esclaves les choses qui doivent arriver bientôt; et il l’a signifiée, en l’envoyant par son ange, à son esclave Jean,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'qui a rendu témoignage de la parole de Dieu et du témoignage de Jésus Christ, [de] toutes [les] choses qu’il a vues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Bienheureux celui qui lit et ceux qui entendent les paroles de la prophétie et qui gardent les choses qui y sont écrites, car le temps est proche!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Jean, aux sept assemblées qui sont en Asie: Grâce et paix à vous, de la part de celui qui est, et qui était, et qui vient, et de la part des sept Esprits qui sont devant son trône,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'et de la part de Jésus Christ, le témoin fidèle, le premier-né des morts, et le prince des rois de la terre! À celui qui nous aime, et qui nous a lavés de nos péchés dans son sang;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, '– et il nous a faits un royaume, des sacrificateurs pour son Dieu et Père; – à lui la gloire et la force aux siècles des siècles! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Voici, il vient avec les nuées, et tout œil le verra, et ceux qui l’ont percé; et toutes les tribus de la terre se lamenteront à cause de lui. Oui, amen!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Moi, je suis l’alpha et l’oméga, dit le ✶Seigneur Dieu, celui qui est, et qui était, et qui vient, le Tout-puissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Moi, Jean, qui suis votre frère et qui ai part avec vous à la tribulation et au royaume et à la patience en Jésus, j’étais dans l’île appelée Patmos, pour la parole de Dieu et pour le témoignage de Jésus Christ.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Je fus en Esprit, dans la journée dominicale, et j’entendis derrière moi une grande voix, comme d’une trompette,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'disant: Ce que tu vois, écris-le dans un livre et envoie-le aux sept assemblées: à Éphèse, et à Smyrne, et à Pergame, et à Thyatire, et à Sardes, et à Philadelphie, et à Laodicée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Et je me retournai pour voir la voix qui me parlait; et, m’étant retourné, je vis sept lampes d’or,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'et au milieu des [sept] lampes [quelqu’un de] semblable au Fils de l’homme, vêtu d’une robe qui allait jusqu’aux pieds, et ceint, à la poitrine, d’une ceinture d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Sa tête et ses cheveux étaient blancs comme de la laine blanche, comme de la neige; et ses yeux, comme une flamme de feu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'et ses pieds, semblables à de l’airain brillant, comme embrasés dans une fournaise; et sa voix, comme une voix de grandes eaux;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, '– et il avait dans sa main droite sept étoiles; et de sa bouche sortait une épée aiguë à deux tranchants; – et son visage, comme le soleil [quand il] luit dans sa force.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Et, lorsque je le vis, je tombai à ses pieds comme mort; et il mit sa droite sur moi, disant: Ne crains point; moi, je suis le premier et le dernier,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'et le vivant; et j’ai été mort; et voici, je suis vivant aux siècles des siècles; et je tiens les clés de la mort et du hadès.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Écris donc les choses que tu as vues, et les choses qui sont, et les choses qui doivent arriver après celles-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Le mystère des sept étoiles que tu as vues dans ma droite, et les sept lampes d’or: les sept étoiles sont [les] anges des sept assemblées, et les sept lampes sont sept assemblées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'À l’ange de l’assemblée qui est à Éphèse, écris: Voici ce que dit celui qui tient les sept étoiles dans sa droite, qui marche au milieu des sept lampes d’or:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Je connais tes œuvres, et ton travail, et ta patience, et que tu ne peux supporter les méchants; et tu as éprouvé ceux qui se disent apôtres et ne le sont pas, et tu les as trouvés menteurs;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'et tu as patience, et tu as supporté [des afflictions] pour mon nom, et tu ne t’es pas lassé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'mais j’ai contre toi que tu as abandonné ton premier amour.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Souviens-toi donc d’où tu es déchu, et repens-toi, et fais les premières œuvres; autrement, je viens à toi et j’ôterai ta lampe de son lieu, à moins que tu ne te repentes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Mais tu as ceci, que tu hais les œuvres des Nicolaïtes, lesquelles moi aussi je hais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Que celui qui a des oreilles écoute ce que l’Esprit dit aux assemblées. À celui qui vaincra, je lui donnerai de manger de l’arbre de vie qui est dans le paradis de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Et à l’ange de l’assemblée qui est à Smyrne, écris: Voici ce que dit le premier et le dernier, qui a été mort et qui a repris vie:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Je connais ta tribulation, et ta pauvreté (mais tu es riche), et l’outrage de ceux qui se disent être Juifs; et ils ne le sont pas, mais ils sont la synagogue de Satan.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ne crains en aucune manière les choses que tu vas souffrir. Voici, le diable va jeter [quelques-uns] d’entre vous en prison, afin que vous soyez éprouvés: et vous aurez une tribulation de dix jours. Sois fidèle jusqu’à la mort et je te donnerai la couronne de vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Que celui qui a des oreilles écoute ce que l’Esprit dit aux assemblées. Celui qui vaincra n’aura point à souffrir de la seconde mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Et à l’ange de l’assemblée qui est à Pergame, écris: Voici ce que dit celui qui a l’épée aiguë à deux tranchants:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Je sais où tu habites, là où est le trône de Satan; et tu tiens ferme mon nom, et tu n’as pas renié ma foi, même dans les jours dans lesquels Antipas était mon fidèle témoin, qui a été mis à mort parmi vous, là où Satan habite.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Mais j’ai quelques choses contre toi: c’est que tu as là des gens qui tiennent la doctrine de Balaam, lequel enseignait à Balac à jeter une pierre d’achoppement devant les fils d’Israël, pour qu’ils mangent des choses sacrifiées aux idoles et qu’ils commettent la fornication.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Ainsi tu en as, toi aussi, qui tiennent la doctrine des Nicolaïtes pareillement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Repens-toi donc; autrement je viens à toi promptement, et je combattrai contre eux par l’épée de ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Que celui qui a des oreilles écoute ce que l’Esprit dit aux assemblées. À celui qui vaincra, je lui donnerai de la manne cachée, et je lui donnerai un caillou blanc, et, sur le caillou, un nouveau nom écrit, que nul ne connaît, sinon celui qui le reçoit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Et à l’ange de l’assemblée qui est à Thyatire, écris: Voici ce que dit le Fils de Dieu, qui a ses yeux comme une flamme de feu, et dont les pieds sont semblables à de l’airain brillant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Je connais tes œuvres, et ton amour, et ta foi, et ton service, et ta patience, et tes dernières œuvres qui dépassent les premières.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Mais j’ai contre toi, que tu laisses faire la femme Jésabel qui se dit prophétesse; et elle enseigne et égare mes esclaves [en les entraînant] à commettre la fornication et à manger des choses sacrifiées aux idoles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Et je lui ai donné du temps afin qu’elle se repente; et elle ne veut pas se repentir de sa fornication.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Voici, je la jette sur un lit, et ceux qui commettent adultère avec elle, dans une grande tribulation, à moins qu’ils ne se repentent de ses œuvres;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'et je ferai mourir de mort ses enfants; et toutes les assemblées connaîtront que c’est moi qui sonde les reins et les cœurs; et je vous donnerai à chacun selon vos œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Mais à vous je dis, aux autres qui sont à Thyatire, autant qu’il y en a qui n’ont pas cette doctrine, qui n’ont pas connu les profondeurs de Satan, comme ils disent: je ne vous impose pas d’autre charge;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'mais seulement, ce que vous avez, tenez-le ferme jusqu’à ce que je vienne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Et celui qui vaincra, et celui qui gardera mes œuvres jusqu’à la fin, – je lui donnerai autorité sur les nations;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'et il les paîtra avec une verge de fer, comme sont brisés les vases de poterie, selon que moi aussi j’ai reçu de mon Père;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'et je lui donnerai l’étoile du matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Que celui qui a des oreilles écoute ce que l’Esprit dit aux assemblées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Et à l’ange de l’assemblée qui est à Sardes, écris: Voici ce que dit celui qui a les sept Esprits de Dieu et les sept étoiles: Je connais tes œuvres, – que tu as le nom de vivre, et tu es mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Sois vigilant, et affermis ce qui reste, qui s’en va mourir, car je n’ai pas trouvé tes œuvres parfaites devant mon Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Souviens-toi donc comment tu as reçu et entendu, et garde, et repens-toi. Si donc tu ne veilles pas, je viendrai [sur toi] comme un voleur, et tu ne sauras point à quelle heure je viendrai sur toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Toutefois tu as quelques noms à Sardes qui n’ont pas souillé leurs vêtements; et ils marcheront avec moi en [vêtements] blancs, car ils en sont dignes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Celui qui vaincra, celui-là sera vêtu de vêtements blancs, et je n’effacerai point son nom du livre de vie, et je confesserai son nom devant mon Père et devant ses anges.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Que celui qui a des oreilles écoute ce que l’Esprit dit aux assemblées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Et à l’ange de l’assemblée qui est à Philadelphie, écris: Voici ce que dit le saint, le véritable, celui qui a la clé de David, celui qui ouvre et nul ne fermera, qui ferme et nul n’ouvrira:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Je connais tes œuvres. Voici, j’ai mis devant toi une porte ouverte que personne ne peut fermer, car tu as peu de force, et tu as gardé ma parole, et tu n’as pas renié mon nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Voici, je donne [de ceux] de la synagogue de Satan qui se disent être Juifs, – et ils ne le sont pas, mais ils mentent; voici, je les ferai venir et se prosterner devant tes pieds, et ils connaîtront que moi je t’ai aimé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Parce que tu as gardé la parole de ma patience, moi aussi je te garderai de l’heure de l’épreuve qui va venir sur la terre habitée tout entière, pour éprouver ceux qui habitent sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Je viens bientôt; tiens ferme ce que tu as, afin que personne ne prenne ta couronne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Celui qui vaincra, je le ferai une colonne dans le temple de mon Dieu, et il ne sortira plus jamais dehors; et j’écrirai sur lui le nom de mon Dieu, et le nom de la cité de mon Dieu, de la nouvelle Jérusalem qui descend du ciel d’auprès de mon Dieu, et mon nouveau nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Que celui qui a des oreilles écoute ce que l’Esprit dit aux assemblées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Et à l’ange de l’assemblée qui est à Laodicée, écris: Voici ce que dit l’Amen, le témoin fidèle et véritable, le commencement de la création de Dieu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Je connais tes œuvres, – que tu n’es ni froid ni bouillant. Je voudrais que tu sois ou froid ou bouillant!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Ainsi, parce que tu es tiède et que tu n’es ni froid ni bouillant, je vais te vomir de ma bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Parce que tu dis: Je suis riche, et je me suis enrichi, et je n’ai besoin de rien, et que tu ne connais pas que, toi, tu es le malheureux et le misérable, et pauvre, et aveugle, et nu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'je te conseille d’acheter de moi de l’or passé au feu, afin que tu deviennes riche, et des vêtements blancs, afin que tu sois vêtu et que la honte de ta nudité ne paraisse pas, et un collyre pour oindre tes yeux, afin que tu voies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Moi, je reprends et je châtie tous ceux que j’aime; aie donc du zèle et repens-toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Voici, je me tiens à la porte et je frappe: si quelqu’un entend ma voix et qu’il ouvre la porte, j’entrerai chez lui et je souperai avec lui, et lui avec moi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Celui qui vaincra, – je lui donnerai de s’asseoir avec moi sur mon trône, comme moi aussi j’ai vaincu et je me suis assis avec mon Père sur son trône.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Que celui qui a des oreilles écoute ce que l’Esprit dit aux assemblées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Après ces choses, je vis: et voici, une porte ouverte dans le ciel, et la première voix que j’avais entendue, comme d’une trompette parlant avec moi, disant: Monte ici, et je te montrerai les choses qui doivent arriver après celles-ci.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Sur-le-champ je fus en Esprit: et voici, un trône était placé dans le ciel, et sur le trône, [quelqu’un était] assis;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'et celui qui était assis était, à le voir, semblable à une pierre de jaspe et de sardius; et autour du trône, un arc-en-ciel, à le voir, semblable à une émeraude;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'et autour du trône, 24 trônes, et sur les trônes, 24 anciens assis, vêtus de vêtements blancs, et sur leurs têtes des couronnes d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Et du trône sortent des éclairs et des voix et des tonnerres; et [il y a] sept lampes de feu, brûlant devant le trône, qui sont les sept Esprits de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'et devant le trône, comme une mer de verre, semblable à du cristal; et au milieu du trône et à l’entour du trône, quatre animaux pleins d’yeux devant et derrière.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Et le premier animal est semblable à un lion; et le second animal, semblable à un veau; et le troisième animal a la face comme d’un homme; et le quatrième animal est semblable à un aigle volant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Et les quatre animaux, chacun d’eux ayant six ailes, sont, tout autour et au-dedans, pleins d’yeux; et ils ne cessent de dire, jour et nuit: Saint, saint, saint, ✶Seigneur, Dieu, Tout-puissant, celui qui était, et qui est, et qui vient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Et quand les animaux rendront gloire et honneur et action de grâces à celui qui est assis sur le trône, à celui qui vit aux siècles des siècles,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'les 24 anciens tomberont [sur leurs faces] devant celui qui est assis sur le trône, et se prosterneront devant celui qui vit aux siècles des siècles; et ils jetteront leurs couronnes devant le trône, disant:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Tu es digne, notre Seigneur et notre Dieu, de recevoir la gloire, et l’honneur, et la puissance; car c’est toi qui as créé toutes choses, et c’est à cause de ta volonté qu’elles étaient, et qu’elles furent créées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Et je vis dans la droite de celui qui était assis sur le trône, un livre, écrit au-dedans et sur le revers, scellé de sept sceaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Et je vis un ange puissant, proclamant à haute voix: Qui est digne d’ouvrir le livre et d’en rompre les sceaux?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Et personne, ni dans le ciel, ni sur la terre, ni au-dessous de la terre, ne pouvait ouvrir le livre ni le regarder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Et moi, je pleurais fort, parce que nul n’était trouvé digne d’ouvrir le livre ni de le regarder.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Et l’un des anciens me dit: Ne pleure pas; voici, le lion qui est de la tribu de Juda, la racine de David, a vaincu pour ouvrir le livre et ses sept sceaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Et je vis au milieu du trône et des quatre animaux, et au milieu des anciens, un agneau qui se tenait là, comme immolé, ayant sept cornes et sept yeux, qui sont les sept Esprits de Dieu, envoyés sur toute la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Et il vint et prit [le livre] de la main droite de celui qui était assis sur le trône.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Et lorsqu’il eut pris le livre, les quatre animaux et les 24 anciens tombèrent [sur leurs faces] devant l’Agneau, ayant chacun une harpe et des coupes d’or pleines de parfums, qui sont les prières des saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Et ils chantent un cantique nouveau, disant: Tu es digne de prendre le livre, et d’en ouvrir les sceaux; car tu as été immolé, et tu as acheté pour Dieu par ton sang, de toute tribu, et langue, et peuple, et nation;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'et tu les as faits rois et sacrificateurs pour notre Dieu, et ils régneront sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Et je vis: et j’entendis une voix de beaucoup d’anges à l’entour du trône et des animaux et des anciens; et leur nombre était des myriades de myriades et des milliers de milliers,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'disant à haute voix: Digne est l’Agneau qui a été immolé, de recevoir la puissance, et richesse, et sagesse, et force, et honneur, et gloire, et bénédiction.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Et j’entendis toutes les créatures qui sont dans le ciel, et sur la terre, et au-dessous de la terre, et sur la mer, et toutes les choses qui y sont, disant: À celui qui est assis sur le trône et à l’Agneau, la bénédiction, et l’honneur, et la gloire, et la force, aux siècles des siècles!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Et les quatre animaux disaient: Amen! Et les anciens tombèrent [sur leurs faces] et rendirent hommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Et je vis, lorsque l’Agneau ouvrit l’un des sept sceaux, et j’entendis l’un des quatre animaux disant comme une voix de tonnerre: Viens [et vois].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Et je vis: et voici un cheval blanc, et celui qui était assis dessus ayant un arc; et une couronne lui fut donnée, et il sortit en vainqueur et pour vaincre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Et lorsqu’il ouvrit le second sceau, j’entendis le second animal disant: Viens [et vois].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Et il sortit un autre cheval, roux; et il fut donné à celui qui était assis dessus d’ôter la paix de la terre, et [de faire] qu’ils s’égorgent l’un l’autre; et il lui fut donné une grande épée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Et lorsqu’il ouvrit le troisième sceau, j’entendis le troisième animal disant: Viens [et vois]. Et je vis: et voici un cheval noir; et celui qui était assis dessus, ayant une balance dans sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Et j’entendis comme une voix au milieu des quatre animaux, disant: Une mesure de froment pour un denier, et trois mesures d’orge pour un denier; et ne nuis pas à l’huile ni au vin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Et lorsqu’il ouvrit le quatrième sceau, j’entendis [la voix du] quatrième animal, disant: Viens [et vois].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Et je vis: et voici un cheval livide; et le nom de celui qui était assis dessus est la Mort; et le hadès suivait avec lui; et il lui fut donné pouvoir sur le quart de la terre, pour tuer avec l’épée, et par la famine, et par la mort, et par les bêtes sauvages de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Et lorsqu’il ouvrit le cinquième sceau, je vis sous l’autel les âmes de ceux qui avaient été égorgés pour la parole de Dieu et pour le témoignage qu’ils avaient [rendu].');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Et elles criaient à haute voix, disant: Jusques à quand, ô Souverain, saint et véritable, ne juges-tu pas et ne venges-tu pas notre sang sur ceux qui habitent sur la terre?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Et il leur fut donné à chacun une longue robe blanche; et il leur fut dit qu’ils se reposent encore un peu de temps, jusqu’à ce que, et leurs compagnons d’esclavage et leurs frères qui devaient être mis à mort comme eux, soient au complet.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Et je vis, lorsqu’il ouvrit le sixième sceau: et il se fit un grand tremblement de terre, et le soleil devint noir comme un sac de poil, et la lune devint tout entière comme du sang;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'et les étoiles du ciel tombèrent sur la terre, comme un figuier agité par un grand vent jette loin ses figues tardives.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Et le ciel se retira comme un livre qui s’enroule, et toute montagne et toute île furent transportées de leur place.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Et les rois de la terre, et les grands, et les chiliarques, et les riches, et les forts, et tout esclave, et [tout] homme libre, se cachèrent dans les cavernes et dans les rochers des montagnes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'et ils disent aux montagnes et aux rochers: Tombez sur nous et tenez-nous cachés de devant la face de celui qui est assis sur le trône et de devant la colère de l’Agneau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'car le grand jour de sa colère est venu, et qui peut subsister?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Et après cela, je vis quatre anges debout aux quatre coins de la terre, retenant les quatre vents de la terre, afin qu’aucun vent ne souffle sur la terre, ni sur la mer, ni sur aucun arbre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Et je vis un autre ange montant de l’orient, ayant le sceau du Dieu vivant; et il cria à haute voix aux quatre anges, auxquels il avait été donné de nuire à la terre et à la mer,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'disant: Ne nuisez pas à la terre, ni à la mer, ni aux arbres, jusqu’à ce que nous ayons scellé au front les esclaves de notre Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Et j’entendis le nombre de ceux qui étaient scellés: 144 000 scellés de toute tribu des fils d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'de la tribu de Juda, 12 000 scellés; de la tribu de Ruben, 12 000; de la tribu de Gad, 12 000;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'de la tribu d’Aser, 12 000; de la tribu de Nephthali, 12 000; de la tribu de Manassé, 12 000;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'de la tribu de Siméon, 12 000; de la tribu de Lévi, 12 000; de la tribu d’Issachar, 12 000;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'de la tribu de Zabulon, 12 000; de la tribu de Joseph, 12 000; de la tribu de Benjamin, 12 000 scellés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Après ces choses, je vis: et voici, une grande foule que personne ne pouvait dénombrer, de toute nation et tribus et peuples et langues, se tenant devant le trône et devant l’Agneau, vêtus de longues robes blanches et [ayant] des palmes dans leurs mains.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'Et ils crient à haute voix, disant: Le salut est à notre Dieu qui est assis sur le trône, et à l’Agneau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, '– Et tous les anges se tenaient à l’entour du trône et des anciens et des quatre animaux; et ils tombèrent sur leurs faces devant le trône, et rendirent hommage à Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'disant: Amen! La bénédiction, et la gloire, et la sagesse, et l’action de grâces, et l’honneur, et la puissance, et la force, à notre Dieu, aux siècles des siècles! Amen.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Et l’un des anciens répondit, me disant: Ceux-ci qui sont vêtus de longues robes blanches, qui sont-ils et d’où sont-ils venus?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Et je lui dis: Mon seigneur, tu le sais. Et il me dit: Ce sont ceux qui viennent de la grande tribulation, et ils ont lavé leurs robes et les ont blanchies dans le sang de l’Agneau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'C’est pourquoi ils sont devant le trône de Dieu et le servent jour et nuit dans son temple; et celui qui est assis sur le trône dressera sa tente sur eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Ils n’auront plus faim et ils n’auront plus soif, et le soleil ne les frappera plus, ni aucune chaleur,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'parce que l’Agneau qui est au milieu du trône les paîtra et les conduira aux fontaines des eaux de la vie, et Dieu essuiera toute larme de leurs yeux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Et lorsqu’il ouvrit le septième sceau, il se fit un silence au ciel d’environ une demi-heure.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Et je vis les sept anges qui se tiennent devant Dieu, et il leur fut donné sept trompettes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Et un autre ange vint et se tint debout devant l’autel, ayant un encensoir d’or; et beaucoup de parfums lui furent donnés, pour donner [efficace] aux prières de tous les saints, sur l’autel d’or qui est devant le trône.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Et la fumée des parfums monta avec les prières des saints, de la main de l’ange devant Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Et l’ange prit l’encensoir et le remplit du feu de l’autel; et il jeta [le feu] sur la terre; et il y eut des voix et des tonnerres et des éclairs et un tremblement de terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Et les sept anges qui avaient les sept trompettes se préparèrent pour sonner de la trompette.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Et le premier sonna de la trompette: et il y eut de la grêle et du feu, mêlés de sang, et ils furent jetés sur la terre; et le tiers de la terre fut brûlé; et le tiers des arbres fut brûlé, et toute herbe verte fut brûlée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Et le second ange sonna de la trompette: et comme une grande montagne toute en feu fut jetée dans la mer; et le tiers de la mer devint du sang,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'et le tiers des créatures qui étaient dans la mer et qui avaient vie mourut, et le tiers des navires fut détruit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Et le troisième ange sonna de la trompette: et il tomba du ciel une grande étoile, brûlant comme un flambeau; et elle tomba sur le tiers des fleuves et sur les fontaines des eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Et le nom de l’étoile est Absinthe; et le tiers des eaux devint absinthe, et beaucoup d’hommes moururent par les eaux, parce qu’elles avaient été rendues amères.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Et le quatrième ange sonna de la trompette: et le tiers du soleil fut frappé, et le tiers de la lune, et le tiers des étoiles, afin que le tiers de ces [astres] soit obscurci, et que le jour ne paraisse pas pour le tiers de sa [durée], et de même pour la nuit.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Et je vis: et j’entendis un aigle qui volait par le milieu du ciel, disant à haute voix: Malheur, malheur, malheur, à ceux qui habitent sur la terre, à cause des autres voix de la trompette des trois anges qui vont sonner de la trompette!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Et le cinquième ange sonna de la trompette: et je vis une étoile tombée du ciel sur la terre; et la clé du puits de l’abîme lui fut donnée,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'et elle ouvrit le puits de l’abîme, et une fumée monta du puits, comme la fumée d’une grande fournaise, et le soleil et l’air furent obscurcis par la fumée du puits.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Et de la fumée il sortit des sauterelles sur la terre; et il leur fut donné un pouvoir semblable au pouvoir qu’ont les scorpions de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Et il leur fut dit qu’elles ne nuisent ni à l’herbe de la terre, ni à aucune verdure, ni à aucun arbre, mais aux hommes qui n’ont pas le sceau de Dieu sur leurs fronts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Et il leur fut donné de ne pas les tuer, mais qu’ils soient tourmentés cinq mois; et leur tourment est comme le tourment du scorpion, quand il frappe l’homme.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Et en ces jours-là les hommes chercheront la mort et ils ne la trouveront point; et ils désireront de mourir, et la mort s’enfuit d’eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Et la ressemblance des sauterelles était semblable à des chevaux préparés pour le combat; et sur leurs têtes il y avait comme des couronnes semblables à de l’or; et leurs faces étaient comme des faces d’hommes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'et elles avaient des cheveux comme des cheveux de femmes, et leurs dents étaient comme [des dents] de lions;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'et elles avaient des cuirasses comme des cuirasses de fer, et le bruit de leurs ailes était comme le bruit de chariots à plusieurs chevaux courant au combat;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'et elles ont des queues semblables à des scorpions, et des aiguillons; et leur pouvoir était dans leurs queues, pour nuire aux hommes cinq mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Elles ont sur elles un roi, l’ange de l’abîme, dont le nom est en hébreu: Abaddon, et en grec il a nom: Apollyon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Le premier malheur est passé; voici, il arrive encore deux malheurs après ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Et le sixième ange sonna de la trompette: et j’entendis une voix sortant des [quatre] cornes de l’autel d’or qui était devant Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'disant au sixième ange qui avait la trompette: Délie les quatre anges qui sont liés sur le grand fleuve Euphrate.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Et les quatre anges qui étaient préparés pour l’heure et le jour et le mois et l’année, furent déliés, afin de tuer le tiers des hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Et le nombre des armées de la cavalerie était de deux myriades de myriades: j’en entendis le nombre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Et c’est ainsi que je vis les chevaux dans la vision, et ceux qui étaient assis dessus, ayant des cuirasses de feu, et d’hyacinthe, et de soufre; et les têtes des chevaux étaient comme des têtes de lions; et de leur bouche sortent du feu, et de la fumée, et du soufre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Par ces trois fléaux fut tué le tiers des hommes, par le feu et la fumée et le soufre qui sortent de leur bouche;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'car le pouvoir des chevaux est dans leur bouche et dans leurs queues; car leurs queues sont semblables à des serpents, ayant des têtes, et par elles ils nuisent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Et les autres hommes qui n’avaient pas été tués par ces plaies, ne se repentirent pas des œuvres de leurs mains, pour ne pas rendre hommage aux démons, et aux idoles d’or, et d’argent, et d’airain, et de pierre, et de bois, qui ne peuvent ni voir, ni entendre, ni marcher;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'et ils ne se repentirent pas de leurs meurtres, ni de leur magie, ni de leur fornication, ni de leurs larcins.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Et je vis un autre ange puissant descendant du ciel, revêtu d’une nuée, et l’arc-en-ciel sur sa tête, et son visage comme le soleil, et ses pieds comme des colonnes de feu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'et il avait dans sa main un petit livre ouvert. Et il mit son pied droit sur la mer et le gauche sur la terre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'et il cria à haute voix, comme un lion rugit; et quand il cria, les sept tonnerres firent entendre leurs propres voix.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Et quand les sept tonnerres eurent parlé, j’allais écrire; et j’entendis une voix venant du ciel, disant: Scelle les choses que les sept tonnerres ont prononcées et ne les écris pas.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Et l’ange que j’avais vu se tenir sur la mer et sur la terre, leva sa main droite vers le ciel,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'et jura par celui qui vit aux siècles des siècles, lequel a créé le ciel et les choses qui y sont, et la terre et les choses qui y sont, et la mer et les choses qui y sont, qu’il n’y aurait plus de délai,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'mais qu’aux jours de la voix du septième ange, quand il sera sur le point de sonner de la trompette, le mystère de Dieu aussi sera terminé, comme il en a annoncé la bonne nouvelle à ses esclaves les prophètes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Et la voix que j’avais entendue du ciel me parla de nouveau et dit: Va, prends le petit livre qui est ouvert dans la main de l’ange qui se tient sur la mer et sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Et je m’en allai vers l’ange, lui disant de me donner le petit livre. Et il me dit: Prends-le et dévore-le; et il remplira ton ventre d’amertume, mais dans ta bouche il sera doux comme du miel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Et je pris le petit livre de la main de l’ange, et je le dévorai; et il fut dans ma bouche doux comme du miel; et quand je l’eus dévoré, mon ventre fut rempli d’amertume.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Et il me fut dit: Il faut que tu prophétises de nouveau sur des peuples et des nations et des langues et beaucoup de rois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Et il me fut donné un roseau semblable à une verge, et il me fut dit: Lève-toi et mesure le temple de Dieu, et l’autel, et ceux qui y adorent;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'et le parvis, qui est en dehors du temple, rejette-le et ne le mesure point, car il a été donné aux nations, et elles fouleront aux pieds la cité sainte 42 mois.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Et je donnerai [puissance] à mes deux témoins, et ils prophétiseront 1 260 jours, vêtus de sacs.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Ceux-ci sont les deux oliviers et les deux lampes qui se tiennent devant le Seigneur de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Et si quelqu’un veut leur nuire, le feu sort de leur bouche et dévore leurs ennemis; et si quelqu’un veut leur nuire, il faut qu’il soit ainsi mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Ceux-ci ont le pouvoir de fermer le ciel, afin qu’il ne tombe point de pluie durant les jours de leur prophétie; et ils ont pouvoir sur les eaux pour les changer en sang, et pour frapper la terre de toutes sortes de plaies, toutes les fois qu’ils le voudront.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Et, quand ils auront achevé leur témoignage, la bête qui monte de l’abîme leur fera la guerre, et les vaincra, et les mettra à mort;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'et leur corps mort [sera étendu] sur la place de la grande ville qui est appelée spirituellement Sodome et Égypte, où aussi leur Seigneur a été crucifié.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Et ceux des peuples et des tribus et des langues et des nations voient leur corps mort durant trois jours et demi, et ils ne permettent point que leurs corps morts soient mis dans un sépulcre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Et ceux qui habitent sur la terre se réjouissent à leur sujet et font des réjouissances, et ils s’enverront des présents les uns aux autres, parce que ces deux prophètes tourmentaient ceux qui habitent sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Et après les trois jours et demi, l’esprit de vie venant de Dieu entra en eux; et ils se tinrent sur leurs pieds, et une grande crainte tomba sur ceux qui les contemplaient.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Et j’entendis une grande voix venant du ciel, leur disant: Montez ici. Et ils montèrent au ciel dans la nuée, et leurs ennemis les contemplèrent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Et à cette heure-là, il y eut un grand tremblement de terre; et la dixième partie de la ville tomba, et 7 000 noms d’hommes furent tués dans le tremblement de terre; et les autres furent épouvantés et donnèrent gloire au Dieu du ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Le second malheur est passé; voici, le troisième malheur vient promptement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Et le septième ange sonna de la trompette: et il y eut dans le ciel de grandes voix, disant: Le royaume du monde de notre ✶Seigneur et de son Christ est venu, et il régnera aux siècles des siècles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Et les 24 anciens qui sont assis devant Dieu sur leurs trônes, tombèrent sur leurs faces et rendirent hommage à Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'disant: Nous te rendons grâces, ✶Seigneur, Dieu, Tout-puissant, celui qui est et qui était, de ce que tu as pris ta grande puissance et de ce que tu es entré dans ton règne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Et les nations se sont irritées; et ta colère est venue, et le temps des morts pour être jugés, et pour donner la récompense à tes esclaves les prophètes, et aux saints, et à ceux qui craignent ton nom, petits et grands, et pour détruire ceux qui corrompent la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Et le temple de Dieu dans le ciel fut ouvert, et l’arche de son alliance apparut dans son temple, et il y eut des éclairs et des voix et des tonnerres et un tremblement de terre et une grosse grêle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Et un grand signe apparut dans le ciel: une femme revêtue du soleil, et la lune sous ses pieds, et sur sa tête une couronne de douze étoiles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Et étant enceinte, elle crie étant en mal d’enfant et en grand tourment pour enfanter.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Et il apparut un autre signe dans le ciel: et voici, un grand dragon roux, ayant sept têtes et dix cornes, et sur ses têtes sept diadèmes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'et sa queue entraîne le tiers des étoiles du ciel, et elle les jeta sur la terre. Et le dragon se tenait devant la femme qui allait enfanter, afin que, lorsqu’elle aurait enfanté, il dévore son enfant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Et elle enfanta un fils mâle qui doit paître toutes les nations avec une verge de fer; et son enfant fut enlevé vers Dieu et vers son trône.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Et la femme s’enfuit dans le désert, où elle a un lieu préparé par Dieu, afin qu’on la nourrisse là 1 260 jours.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Et il y eut un combat dans le ciel: Michel et ses anges combattaient contre le dragon. Et le dragon combattait, et ses anges;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'et il ne fut pas le plus fort, et leur place ne fut plus trouvée dans le ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Et le grand dragon fut précipité, le serpent ancien, celui qui est appelé diable et Satan, celui qui séduit la terre habitée tout entière, – il fut précipité sur la terre, et ses anges furent précipités avec lui.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Et j’entendis une grande voix dans le ciel, disant: Maintenant est venu le salut et la puissance et le royaume de notre Dieu et le pouvoir de son Christ, car l’accusateur de nos frères, qui les accusait devant notre Dieu jour et nuit, a été précipité;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'et eux l’ont vaincu à cause du sang de l’Agneau et à cause de la parole de leur témoignage; et ils n’ont pas aimé leur vie, [même] jusqu’à la mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'C’est pourquoi réjouissez-vous, cieux et vous qui y habitez. Malheur à la terre et à la mer, car le diable est descendu vers vous, étant en grande fureur, sachant qu’il a peu de temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Et quand le dragon vit qu’il avait été précipité sur la terre, il persécuta la femme qui avait enfanté le [fils] mâle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Et les deux ailes du grand aigle furent données à la femme, afin qu’elle s’envole dans le désert, en son lieu, où elle est nourrie un temps, et des temps, et la moitié d’un temps, loin de la face du serpent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Et le serpent lança de sa bouche de l’eau, comme un fleuve, après la femme, afin de la faire emporter par le fleuve;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'et la terre vint en aide à la femme, et la terre ouvrit sa bouche et engloutit le fleuve que le dragon avait lancé de sa bouche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Et le dragon fut irrité contre la femme, et s’en alla faire la guerre contre le résidu de la semence de la femme, ceux qui gardent les commandements de Dieu et qui ont le témoignage de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, 'Et je me tins sur le sable de la mer;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'et je vis monter de la mer une bête qui avait dix cornes et sept têtes, et sur ses cornes dix diadèmes, et sur ses têtes des noms de blasphème.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Et la bête que je vis était semblable à un léopard, et ses pieds comme ceux d’un ours, et sa bouche comme la bouche d’un lion; et le dragon lui donna sa puissance et son trône, et un grand pouvoir.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Et [je vis] l’une de ses têtes comme frappée à mort; et sa plaie mortelle avait été guérie; et la terre tout entière était dans l’admiration de la bête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'Et ils rendirent hommage au dragon, parce qu’il avait donné le pouvoir à la bête; et ils rendirent hommage à la bête, disant: Qui est semblable à la bête, et qui peut combattre contre elle?');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Et il lui fut donné une bouche qui proférait de grandes choses et des blasphèmes; – et le pouvoir d’agir 42 mois lui fut donné.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Et elle ouvrit sa bouche en blasphèmes contre Dieu, pour blasphémer son nom, et son habitation, et ceux qui habitent dans le ciel.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Et il lui fut donné de faire la guerre aux saints et de les vaincre. Et il lui fut donné pouvoir sur toute tribu et peuple et langue et nation.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Et tous ceux qui habitent sur la terre, dont le nom n’a pas été écrit, dès la fondation du monde, dans le livre de vie de l’Agneau immolé, lui rendront hommage.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Si quelqu’un a des oreilles, qu’il écoute!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Si quelqu’un [mène] en captivité, il ira en captivité; si quelqu’un tue avec l’épée, il faut qu’il soit tué par l’épée. C’est ici la patience et la foi des saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Et je vis une autre bête montant de la terre; et elle avait deux cornes semblables à un agneau; et elle parlait comme un dragon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Et elle exerce tout le pouvoir de la première bête devant elle, et fait que la terre et ceux qui habitent sur elle rendent hommage à la première bête dont la plaie mortelle avait été guérie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Et elle fait de grands miracles, en sorte que même elle fait descendre le feu du ciel sur la terre, devant les hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Et elle séduit ceux qui habitent sur la terre, à cause des miracles qu’il lui fut donné de faire devant la bête, disant à ceux qui habitent sur la terre de faire une image à la bête qui a la plaie de l’épée et qui a repris vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Et il lui fut donné de donner la respiration à l’image de la bête, afin que l’image de la bête parle même, et qu’elle fasse que tous ceux qui ne rendraient pas hommage à l’image de la bête soient mis à mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Et elle fait qu’à tous, petits et grands, et riches et pauvres, et libres et esclaves, on leur donne une marque sur leur main droite ou sur leur front;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'et que personne ne peut acheter ou vendre, sinon celui qui a la marque, le nom de la bête, ou le nombre de son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Ici est la sagesse. Que celui qui a de l’intelligence compte le nombre de la bête, car c’est un nombre d’homme; et son nombre est 666.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Et je vis: et voici l’Agneau se tenant sur la montagne de Sion, et avec lui 144 milliers, ayant son nom et le nom de son Père écrits sur leurs fronts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Et j’entendis une voix venant du ciel, comme une voix de grandes eaux et comme une voix d’un grand tonnerre; et la voix que j’entendis était comme de joueurs de harpe, jouant de leurs harpes;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'et ils chantent un cantique nouveau devant le trône, et devant les quatre animaux et les anciens. Et personne ne pouvait apprendre le cantique, sinon les 144 milliers qui ont été achetés de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Ce sont ceux qui ne se sont point souillés avec les femmes, car ils sont vierges; ce sont ceux qui suivent l’Agneau où qu’il aille; ceux-ci ont été achetés d’entre les hommes, des prémices à Dieu et à l’Agneau;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'et il n’a pas été trouvé de mensonge dans leur bouche; ils sont irréprochables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Et je vis un [autre] ange volant par le milieu du ciel, ayant l’évangile éternel pour l’annoncer à ceux qui sont établis sur la terre, et à toute nation et tribu et langue et peuple,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'disant à haute voix: Craignez Dieu et donnez-lui gloire, car l’heure de son jugement est venue; et rendez hommage à celui qui a fait le ciel et la terre et la mer et les fontaines d’eaux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Et un autre, un second ange, suivit, disant: Elle est tombée, elle est tombée, Babylone la grande, qui, du vin de la fureur de sa fornication, a fait boire à toutes les nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Et un autre, un troisième ange, suivit ceux-là, disant à haute voix: Si quelqu’un rend hommage à la bête et à son image, et qu’il reçoive une marque sur son front ou sur sa main,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'lui aussi boira du vin de la fureur de Dieu, versé sans mélange dans la coupe de sa colère; et il sera tourmenté dans le feu et le soufre devant les saints anges et devant l’Agneau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Et la fumée de leur tourment monte aux siècles des siècles; et ils n’ont aucun repos, ni jour, ni nuit, ceux qui rendent hommage à la bête et à son image, et si quelqu’un prend la marque de son nom.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Ici est la patience des saints; [ici], ceux qui gardent les commandements de Dieu et la foi de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Et j’entendis une voix venant du ciel, disant: Écris: Bienheureux les morts qui meurent dans le Seigneur, dorénavant. Oui, dit l’Esprit, afin qu’ils se reposent de leurs travaux, car leurs œuvres les suivent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Et je vis: et voici une nuée blanche, et sur la nuée [quelqu’un] assis, semblable au Fils de l’homme, ayant sur sa tête une couronne d’or et dans sa main une faucille tranchante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Et un autre ange sortit du temple, criant à haute voix à celui qui était assis sur la nuée: Lance ta faucille et moissonne; car l’heure de moissonner est venue, parce que la moisson de la terre est desséchée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Et celui qui était assis sur la nuée mit sa faucille sur la terre, et la terre fut moissonnée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Et un autre ange sortit du temple qui est dans le ciel, ayant lui aussi une faucille tranchante.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Et un autre ange, ayant pouvoir sur le feu, sortit de l’autel et, en jetant un grand cri, il cria à celui qui avait la faucille tranchante, disant: Lance ta faucille tranchante et vendange les grappes de la vigne de la terre, car ses raisins ont mûri.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Et l’ange mit sa faucille sur la terre, et vendangea la vigne de la terre, et jeta [les grappes] dans la grande cuve du courroux de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Et la cuve fut foulée hors de la ville; et de la cuve il sortit du sang jusqu’aux mors des chevaux, sur un espace de 1 600 stades.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Et je vis dans le ciel un autre signe, grand et merveilleux: sept anges, ayant sept plaies, les dernières; car en elles le courroux de Dieu est consommé.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Et je vis comme une mer de verre, mêlée de feu, et ceux qui avaient remporté la victoire sur la bête, et sur son image, et sur le nombre de son nom, se tenant debout sur la mer de verre, ayant des harpes de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Et ils chantent le cantique de Moïse, esclave de Dieu, et le cantique de l’Agneau, disant: Grandes et merveilleuses sont tes œuvres, ✶Seigneur, Dieu, Tout-puissant! Justes et véritables sont tes voies, ô Roi des nations!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Qui ne te craindrait, ✶Seigneur, et qui ne glorifierait ton nom? car seul tu es saint; car toutes les nations viendront et se prosterneront devant toi; parce que tes faits justes ont été manifestés.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Et après ces choses je vis: et le temple du tabernacle du témoignage dans le ciel fut ouvert.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Et les sept anges qui avaient les sept plaies sortirent du temple, vêtus d’un lin pur et éclatant, et ceints sur leurs poitrines de ceintures d’or.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Et l’un des quatre animaux donna aux sept anges sept coupes d’or, pleines du courroux de Dieu qui vit aux siècles des siècles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Et le temple fut rempli de la fumée qui procédait de la gloire de Dieu et de sa puissance; et personne ne pouvait entrer dans le temple, jusqu’à ce que les sept plaies des sept anges soient consommées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Et j’entendis une grande voix venant du temple, disant aux sept anges: Allez, et versez sur la terre les sept coupes du courroux de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Et le premier s’en alla et versa sa coupe sur la terre; et un ulcère mauvais et malin vint sur les hommes qui avaient la marque de la bête et sur ceux qui rendaient hommage à son image.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Et le second versa sa coupe sur la mer; et elle devint du sang, comme d’un corps mort; et tout ce qui avait vie dans la mer mourut.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Et le troisième versa sa coupe sur les fleuves, et sur les fontaines des eaux; et ils devinrent du sang.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Et j’entendis l’ange des eaux, disant: Tu es juste, toi qui es et qui étais, le Saint, parce que tu as ainsi jugé;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'car ils ont versé le sang des saints et des prophètes, et tu leur as donné du sang à boire; ils en sont dignes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Et j’entendis l’autel, disant: Oui, ✶Seigneur, Dieu, Tout-puissant, véritables et justes sont tes jugements!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Et le quatrième versa sa coupe sur le soleil; et il lui fut donné de brûler les hommes par le feu:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'et les hommes furent brûlés par une grande chaleur; et ils blasphémèrent le nom de Dieu qui a pouvoir sur ces plaies, et ils ne se repentirent pas pour lui donner gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Et le cinquième versa sa coupe sur le trône de la bête; et son royaume devint ténébreux; et de douleur, ils se mordaient la langue:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'et ils blasphémèrent le Dieu du ciel, à cause de leurs douleurs et de leurs ulcères, et ne se repentirent pas de leurs œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Et le sixième versa sa coupe sur le grand fleuve Euphrate; et son eau tarit, afin que la voie des rois qui viennent de l’orient soit préparée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Et je vis sortir de la bouche du dragon, et de la bouche de la bête, et de la bouche du faux prophète, trois esprits immondes, comme des grenouilles;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'car ce sont des esprits de démons faisant des miracles, qui s’en vont vers les rois de la terre habitée tout entière, pour les assembler pour le combat de ce grand jour de Dieu le Tout-puissant.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '(Voici, je viens comme un voleur. Bienheureux celui qui veille et qui garde ses vêtements, afin qu’il ne marche pas nu et qu’on ne voie pas sa honte.)');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Et ils les assemblèrent au lieu appelé en hébreu: Armagédon.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Et le septième versa sa coupe dans l’air; et il sortit du temple du ciel une grande voix procédant du trône, disant: C’est fait!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Et il y eut des éclairs, et des voix, et des tonnerres; et il y eut un grand tremblement de terre, un tremblement de terre tel, si grand, qu’il n’y en a jamais eu de semblable depuis que les hommes sont sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Et la grande ville fut divisée en trois parties; et les villes des nations tombèrent; et la grande Babylone vint en mémoire devant Dieu, pour lui donner la coupe du vin de la fureur de sa colère.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Et toute île s’enfuit, et les montagnes ne furent pas trouvées;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'et une grande grêle, du poids d’un talent, descend du ciel sur les hommes; et les hommes blasphémèrent Dieu à cause de la plaie de la grêle; car la plaie en est fort grande.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Et l’un des sept anges qui avaient les sept coupes, vint et me parla, disant: Viens ici; je te montrerai la sentence de la grande prostituée qui est assise sur plusieurs eaux,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'avec laquelle les rois de la terre ont commis fornication; et ceux qui habitent sur la terre ont été enivrés du vin de sa fornication.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Et il m’emporta en esprit dans un désert: et je vis une femme assise sur une bête écarlate, pleine de noms de blasphème, ayant sept têtes et dix cornes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Et la femme était vêtue de pourpre et d’écarlate, et parée d’or et de pierres précieuses et de perles, ayant dans sa main une coupe d’or pleine d’abominations, et les impuretés de sa fornication;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'et [il y avait] sur son front un nom écrit: Mystère, Babylone la grande, la mère des prostituées et des abominations de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Et je vis la femme enivrée du sang des saints, et du sang des témoins de Jésus; et, en la voyant, je fus saisi d’un grand étonnement.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Et l’ange me dit: Pourquoi es-tu étonné? Je te dirai, moi, le mystère de la femme et de la bête qui la porte, qui a les sept têtes et les dix cornes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'La bête que tu as vue était, et n’est pas, et va monter de l’abîme et aller à la perdition; et ceux qui habitent sur la terre, dont les noms ne sont pas écrits dès la fondation du monde au livre de vie, s’étonneront, en voyant la bête, – qu’elle était, et qu’elle n’est pas, et qu’elle sera présente.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Ici est l’entendement, qui a de la sagesse: Les sept têtes sont sept montagnes où la femme est assise;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'ce sont aussi sept rois: cinq sont tombés; l’un est; l’autre n’est pas encore venu, et, quand il sera venu, il faut qu’il demeure un peu de temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Et la bête qui était et qui n’est pas, est, elle aussi, un huitième, et elle est d’entre les sept, et elle s’en va à la perdition.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Et les dix cornes que tu as vues sont dix rois qui n’ont pas encore reçu de royaume, mais reçoivent pouvoir comme rois, une heure, avec la bête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ceux-ci ont une seule et même pensée, et ils donnent leur puissance et leur pouvoir à la bête.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ceux-ci combattront contre l’Agneau; et l’Agneau les vaincra, car il est Seigneur des seigneurs et Roi des rois, et ceux qui sont avec lui, appelés, et élus, et fidèles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Et il me dit: Les eaux que tu as vues, où la prostituée est assise, sont des peuples et des foules et des nations et des langues.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Et les dix cornes que tu as vues et la bête, – celles-ci haïront la prostituée et la rendront déserte et nue, et mangeront sa chair et la brûleront au feu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'car Dieu a mis dans leurs cœurs d’exécuter sa pensée, et d’exécuter une seule et même pensée, et de donner leur royaume à la bête, jusqu’à ce que les paroles de Dieu soient accomplies.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Et la femme que tu as vue est la grande ville qui a la royauté sur les rois de la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Après ces choses, je vis un autre ange descendant du ciel, ayant un grand pouvoir; et la terre fut illuminée de sa gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Et il cria avec une forte voix, disant: Elle est tombée, elle est tombée, Babylone la grande! et elle est devenue la demeure de démons, et le repaire de tout esprit immonde, et le repaire de tout oiseau immonde et exécrable;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'car toutes les nations ont bu du vin de la fureur de sa fornication, et les rois de la terre ont commis fornication avec elle, et les marchands de la terre sont devenus riches par la puissance de son luxe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Et j’entendis une autre voix venant du ciel, disant: Sortez du milieu d’elle, mon peuple, afin que vous ne participiez pas à ses péchés et que vous ne receviez pas de ses plaies:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'car ses péchés se sont amoncelés jusqu’au ciel, et Dieu s’est souvenu de ses iniquités.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Donnez-lui comme elle [vous] a donné, et doublez-lui le double, selon ses œuvres; dans la coupe qu’elle a mixtionnée, versez-lui le double.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Autant elle s’est glorifiée et a été dans les délices, autant donnez-lui de tourment et de deuil. Parce qu’elle dit dans son cœur: Je suis assise en reine, et je ne suis point veuve, et je ne verrai point de deuil;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, '– c’est pourquoi en un seul jour viendront ses plaies, mort, et deuil, et famine, et elle sera brûlée au feu; car le ✶Seigneur Dieu qui l’a jugée est puissant!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Et les rois de la terre qui ont commis fornication et qui ont vécu dans les délices avec elle, pleureront et se lamenteront sur elle, quand ils verront la fumée de son embrasement,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, '– se tenant loin par crainte de son tourment, et disant: Hélas! hélas! la grande ville, Babylone, la ville forte! car en une seule heure son jugement est venu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Et les marchands de la terre pleurent et mènent deuil sur elle, parce que personne n’achète plus leur marchandise,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'marchandise d’or, et d’argent, et de pierres précieuses, et de perles, et de fin lin, et de pourpre, et de soie, et d’écarlate, et tout bois de thuya, et tout article d’ivoire, et tout article en bois très précieux, et en airain, et en fer, et en marbre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'et de la cannelle, et de l’amome, et des parfums, et de l’huile aromatique, et de l’encens, et du vin, et de l’huile, et de la fine farine, et du froment, et du bétail, et des brebis, et des chevaux, et des chariots, et des esclaves, et des âmes d’hommes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Et les fruits du désir de ton âme se sont éloignés de toi; et toutes les choses délicates et éclatantes ont péri pour toi; et on ne les trouvera plus jamais.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Les marchands de ces choses, qui se sont enrichis par elle, se tiendront loin à cause de la crainte de son tourment, pleurant et menant deuil, [et]');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'disant: Hélas! hélas! la grande ville qui était vêtue de fin lin et de pourpre et d’écarlate, et parée d’or et de pierres précieuses et de perles!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'car, en une seule heure, tant de richesses ont été changées en désolation! Et tout pilote, et quiconque navigue vers [quelque] lieu, et les matelots, et ceux qui sont occupés sur mer, se tenaient loin;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'et voyant la fumée de son embrasement, ils s’écrièrent, disant: Quelle [ville] est semblable à la grande ville!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Et ils jetèrent de la poussière sur leurs têtes, et, pleurant et menant deuil, ils s’écriaient, disant: Hélas! hélas! la grande ville, dans laquelle, par son opulence, tous ceux qui avaient des navires sur la mer étaient devenus riches! car, en une seule heure, elle a été désolée!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Ô ciel, réjouis-toi sur elle, et [vous] les saints et les apôtres et les prophètes! car Dieu a jugé votre cause [en tirant vengeance] d’elle.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Et un ange puissant leva une pierre, comme une grande meule, et la jeta dans la mer, disant: Ainsi sera jetée avec violence Babylone la grande ville, et elle ne sera plus trouvée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Et la voix des joueurs de harpe, et des musiciens, et des joueurs de hautbois, et de ceux qui sonnent de la trompette, ne sera plus entendue en toi; et aucun ouvrier, d’aucun métier, ne sera plus trouvé en toi; et le bruit de la meule ne sera plus entendu en toi.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'Et la lumière de la lampe ne luira plus en toi; et la voix de l’époux et de l’épouse ne sera plus entendue en toi; car tes marchands étaient les grands de la terre; car, par ta magie, toutes les nations ont été égarées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Et en elle a été trouvé le sang des prophètes, et des saints, et de tous ceux qui ont été immolés sur la terre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Après ces choses, j’entendis comme une grande voix d’une foule nombreuse dans le ciel, disant: Alléluia! Le salut et la gloire et la puissance de notre Dieu!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'car ses jugements sont véritables et justes; car il a jugé la grande prostituée qui corrompait la terre par sa fornication, et il a vengé le sang de ses esclaves, [le réclamant] de sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Et ils dirent une seconde fois: Alléluia! Et sa fumée monte aux siècles des siècles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Et les 24 anciens et les quatre animaux tombèrent [sur leurs faces] et rendirent hommage à Dieu qui était assis sur le trône, disant: Amen! Alléluia!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Et une voix sortit du trône, disant: Louez notre Dieu, vous tous ses esclaves et vous qui le craignez, petits et grands.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Et j’entendis comme une voix d’une foule nombreuse, et comme une voix de grandes eaux, et comme une voix de forts tonnerres, disant: Alléluia! car le ✶Seigneur, notre Dieu, le Tout-puissant, est entré dans son règne.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Réjouissons-nous et tressaillons de joie, et donnons-lui gloire; car les noces de l’Agneau sont venues; et sa femme s’est préparée;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'et il lui a été donné d’être vêtue de fin lin, éclatant [et] pur, car le fin lin, ce sont les justices des saints.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Et il me dit: Écris: Bienheureux ceux qui sont conviés au banquet des noces de l’Agneau. Et il me dit: Ce sont ici les véritables paroles de Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, '– Et je tombai devant ses pieds pour lui rendre hommage. Et il me dit: Garde-toi de le faire; je suis ton compagnon d’esclavage et [celui] de tes frères qui ont le témoignage de Jésus: rends hommage à Dieu, car l’esprit de prophétie est le témoignage de Jésus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Et je vis le ciel ouvert: et voici un cheval blanc, et celui qui est assis dessus [appelé] fidèle et véritable; et il juge et combat en justice.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Et ses yeux sont une flamme de feu; et sur sa tête il y a plusieurs diadèmes; et il porte un nom écrit que nul ne connaît que lui seul;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'et il est vêtu d’un vêtement teint dans le sang; et son nom s’appelle: “La Parole de Dieu”;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'et les armées qui sont dans le ciel le suivaient sur des chevaux blancs, vêtues de fin lin, blanc et pur;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'et une épée aiguë à deux tranchants sort de sa bouche, afin qu’il en frappe les nations; et lui les paîtra avec une verge de fer, et lui foule la cuve du vin de la fureur de la colère de Dieu le Tout-puissant;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'et il a sur son vêtement et sur sa cuisse un nom écrit: “Roi des rois, et Seigneur des seigneurs”.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Et je vis un ange se tenant dans le soleil; et il cria à haute voix, disant à tous les oiseaux qui volent par le milieu du ciel: Venez, assemblez-vous au grand souper de Dieu;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'afin que vous mangiez la chair des rois, et la chair des chiliarques, et la chair des puissants, et la chair des chevaux et de ceux qui sont assis dessus, et la chair de tous, libres et esclaves, petits et grands.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Et je vis la bête, et les rois de la terre, et leurs armées assemblées pour livrer combat à celui qui était assis sur le cheval et à son armée.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Et la bête fut prise, et le faux prophète qui était avec elle, qui avait fait devant elle les miracles par lesquels il avait séduit ceux qui recevaient la marque de la bête, et ceux qui rendaient hommage à son image. Ils furent tous deux jetés vifs dans l’étang de feu embrasé par le soufre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'et le reste fut tué par l’épée de celui qui était assis sur le cheval, laquelle sortait de sa bouche, et tous les oiseaux furent rassasiés de leur chair.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Et je vis un ange descendant du ciel, ayant la clé de l’abîme et une grande chaîne dans sa main.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Et il saisit le dragon, le serpent ancien qui est le diable et Satan, et le lia pour 1 000 ans;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'et il le jeta dans l’abîme, et l’enferma; et il mit un sceau sur lui, afin qu’il ne séduise plus les nations, jusqu’à ce que les 1 000 ans soient accomplis; après cela, il faut qu’il soit délié pour un peu de temps.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Et je vis des trônes, et ils étaient assis dessus, et le jugement leur fut donné; et les âmes de ceux qui avaient été décapités pour le témoignage de Jésus, et pour la parole de Dieu; et ceux qui n’avaient pas rendu hommage à la bête ni à son image, et qui n’avaient pas reçu la marque sur leur front et sur leur main; et ils vécurent et régnèrent avec le Christ 1 000 ans:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'le reste des morts ne vécut pas jusqu’à ce que les 1 000 ans soient accomplis. C’est ici la première résurrection.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Bienheureux et saint celui qui a part à la première résurrection: sur eux la seconde mort n’a point de pouvoir; mais ils seront sacrificateurs de Dieu et du Christ, et ils régneront avec lui 1 000 ans.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Et quand les 1 000 ans seront accomplis, Satan sera délié de sa prison;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'et il sortira pour égarer les nations qui sont aux quatre coins de la terre, Gog et Magog, pour les assembler pour le combat, eux dont le nombre est comme le sable de la mer.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Et ils montèrent sur la largeur de la terre, et ils environnèrent le camp des saints et la cité bien-aimée; et du feu descendit du ciel [de la part de Dieu] et les dévora.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Et le diable qui les avait égarés fut jeté dans l’étang de feu et de soufre, où sont et la bête et le faux prophète; et ils seront tourmentés, jour et nuit, aux siècles des siècles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Et je vis un grand trône blanc, et celui qui était assis dessus, de devant la face duquel la terre s’enfuit et le ciel; et il ne fut pas trouvé de lieu pour eux.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Et je vis les morts, les grands et les petits, se tenant devant le trône; et des livres furent ouverts; et un autre livre fut ouvert qui est celui de la vie. Et les morts furent jugés d’après les choses qui étaient écrites dans les livres, selon leurs œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Et la mer rendit les morts qui étaient en elle; et la mort et le hadès rendirent les morts qui étaient en eux, et ils furent jugés chacun selon leurs œuvres.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Et la mort et le hadès furent jetés dans l’étang de feu: c’est ici la seconde mort, l’étang de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Et si quelqu’un n’était pas trouvé écrit dans le livre de vie, il était jeté dans l’étang de feu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Et je vis un nouveau ciel et une nouvelle terre; car le premier ciel et la première terre s’en étaient allés, et la mer n’est plus.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Et je vis la sainte cité, nouvelle Jérusalem, descendant du ciel d’auprès de Dieu, préparée comme une épouse ornée pour son mari.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Et j’entendis une grande voix venant du ciel, disant: Voici, l’habitation de Dieu est avec les hommes, et il habitera avec eux; et ils seront son peuple, et Dieu lui-même sera avec eux, leur Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Et [Dieu] essuiera toute larme de leurs yeux; et la mort ne sera plus; et il n’y aura plus ni deuil, ni cri, ni peine, car les premières choses sont passées.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Et celui qui était assis sur le trône dit: Voici, je fais toutes choses nouvelles. Et il [me] dit: Écris, car ces paroles sont certaines et véritables.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Et il me dit: C’est fait. Moi, je suis l’alpha et l’oméga, le commencement et la fin. À celui qui a soif, je donnerai, moi, gratuitement, de la fontaine de l’eau de la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Celui qui vaincra héritera de ces choses, et je lui serai Dieu, et lui me sera fils.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Mais quant aux timides, et aux incrédules, et à ceux qui se sont souillés avec des abominations, et aux meurtriers, et aux fornicateurs, et aux magiciens, et aux idolâtres, et à tous les menteurs, leur part sera dans l’étang brûlant de feu et de soufre, qui est la seconde mort.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Et l’un des sept anges qui avaient eu les sept coupes pleines des sept dernières plaies, vint et me parla, disant: Viens ici, je te montrerai l’épouse, la femme de l’Agneau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Et il m’emporta en esprit sur une grande et haute montagne, et il me montra la sainte cité, Jérusalem, descendant du ciel d’auprès de Dieu,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'ayant la gloire de Dieu. Son luminaire était semblable à une pierre très précieuse, comme à une pierre de jaspe cristallin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Elle avait une grande et haute muraille; elle avait douze portes, et aux portes douze anges, et des noms écrits sur [elles], qui sont ceux des douze tribus des fils d’Israël:');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'à l’orient, trois portes; et au nord, trois portes; et au midi, trois portes; et à l’occident, trois portes.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Et la muraille de la cité avait douze fondements, et sur eux les douze noms des douze apôtres de l’Agneau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Et celui qui me parlait avait pour mesure un roseau d’or, pour mesurer la cité et ses portes et sa muraille.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Et la cité est bâtie en carré, et sa longueur est aussi grande que sa largeur. Et il mesura la cité avec le roseau, jusqu’à 12 000 stades: sa longueur et sa largeur, et sa hauteur étaient égales.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Et il mesura sa muraille, 144 coudées, mesure d’homme, c’est-à-dire d’ange.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Et sa muraille était bâtie de jaspe; et la cité était d’or pur, semblable à du verre pur.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Les fondements de la muraille de la cité étaient ornés de toute pierre précieuse: le premier fondement était de jaspe, le second de saphir, le troisième de calcédoine, le quatrième d’émeraude,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'le cinquième de sardonix, le sixième de sardius, le septième de chrysolithe, le huitième de béryl, le neuvième de topaze, le dixième de chrysoprase, le onzième d’hyacinthe, le douzième d’améthyste.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Et les douze portes étaient douze perles; chacune des portes était d’une seule perle; et la rue de la cité était d’or pur, comme du verre transparent.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Et je ne vis pas de temple en elle; car le ✶Seigneur, Dieu, le Tout-puissant, et l’Agneau, en sont le temple.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Et la cité n’a pas besoin du soleil ni de la lune, pour l’éclairer; car la gloire de Dieu l’a illuminée, et l’Agneau est sa lampe.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Et les nations marcheront par sa lumière; et les rois de la terre lui apporteront leur gloire.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Et ses portes ne seront point fermées de jour: car il n’y aura pas de nuit là.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Et on lui apportera la gloire et l’honneur des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Et il n’y entrera aucune chose souillée, ni ce qui fait une abomination et un mensonge: mais seulement ceux qui sont écrits dans le livre de vie de l’Agneau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Et il me montra un fleuve d’eau vive, éclatant comme du cristal, sortant du trône de Dieu et de l’Agneau.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Au milieu de sa rue, et du fleuve, de çà et de là, était l’arbre de vie, portant douze fruits, rendant son fruit chaque mois; et les feuilles de l’arbre sont pour la guérison des nations.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Et il n’y aura plus de malédiction; et le trône de Dieu et de l’Agneau sera en elle; et ses esclaves le serviront,');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'et ils verront sa face, et son nom sera sur leurs fronts.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Et il n’y aura plus de nuit, ni besoin d’une lampe et de la lumière du soleil; car le ✶Seigneur Dieu fera briller [sa] lumière sur eux; et ils régneront aux siècles des siècles.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Et il me dit: Ces paroles sont certaines et véritables; et le ✶Seigneur Dieu des esprits des prophètes, a envoyé son ange, pour montrer à ses esclaves les choses qui doivent arriver bientôt.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Et voici, je viens bientôt. Bienheureux celui qui garde les paroles de la prophétie de ce livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Et c’est moi, Jean, qui ai entendu et vu ces choses; et quand j’eus entendu et que j’eus vu, je tombai à terre pour rendre hommage devant les pieds de l’ange qui me montrait ces choses.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Et il me dit: Garde-toi de le faire; je suis ton compagnon d’esclavage et [celui] de tes frères les prophètes et de ceux qui gardent les paroles de ce livre: rends hommage à Dieu.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Et il me dit: Ne scelle point les paroles de la prophétie de ce livre; le temps est proche.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Que celui qui est injuste commette encore l’injustice; et que celui qui est souillé se souille encore; et que celui qui est juste pratique encore la justice; et que celui qui est saint soit sanctifié encore.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Voici, je viens bientôt, et ma récompense est avec moi, pour rendre à chacun selon que sera son œuvre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Moi, je suis l’alpha et l’oméga, le premier et le dernier, le commencement et la fin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Bienheureux ceux qui lavent leurs robes, afin qu’ils aient droit à l’arbre de vie et qu’ils entrent par les portes dans la cité.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Dehors sont les chiens, et les magiciens, et les fornicateurs, et les meurtriers, et les idolâtres, et quiconque aime et fait le mensonge.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Moi, Jésus, j’ai envoyé mon ange pour vous rendre témoignage de ces choses dans les assemblées. Moi, je suis la racine et la postérité de David, l’étoile brillante du matin.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Et l’Esprit et l’épouse disent: Viens. Et que celui qui entend dise: Viens. Et que celui qui a soif vienne; que celui qui veut prenne gratuitement de l’eau de la vie.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Moi, je rends témoignage à quiconque entend les paroles de la prophétie de ce livre, que si quelqu’un ajoute à ces choses, Dieu lui ajoutera les plaies écrites dans ce livre;');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'et que si quelqu’un ôte quelque chose des paroles du livre de cette prophétie, Dieu ôtera sa part de l’arbre de vie et de la sainte cité, qui sont écrits dans ce livre.');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Celui qui rend témoignage de ces choses dit: Oui, je viens bientôt. – Amen; viens, seigneur Jésus!');
INSERT INTO `FreJND_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Que la grâce du seigneur Jésus Christ soit avec tous les saints.');
